INSERT INTO `descriptive_answers_tam24` (`id`, `question_id`, `answer_text`, `created_at`) VALUES
(733, 750, 'گزینه&laquo;4&raquo; فقط مورد &laquo;د&raquo; به درستی بیان شده است. بررسی همه موارد: الف) نادرست - نبود مرکز تنظیم ژنتیک یاخته (هسته) را می توان در یاخته های آوند چوبی، آوند آبکشی و فیبر مشاهده نمود. ب) نادرست ـ در بین یاخته های مطرح شده در صورت سؤال، فقط عنصر آوندی فاقد دیواره عرضی است. این ویژگی سبب می شود تعداد زیادی از آن ها، کنار هم قرار بگیرند و لوله پیوسته ای ایجاد کنند. ج) نادرست ـ از دست دادن پروتوپلاست و نبود کانال های سیتوپلاسمی را می توان در فیبر، یاخته های تراکئید و عنصر آوندی (سه نوع یاخته) مشاهده کرد. د) درست ـ منظور مکش تعرقی است که در اثر فعالیت یاخته های نگهبان روزنه (خروج آب به صورت بخار از منفذ بین دو یاخته) ایجاد می شود. مکش تعرقی در حمل شیره خام در آوندهای چوبی نقش دارد. (دو نوع یاخته)', '2026-02-05 17:20:29'),
(734, 751, 'گزینه&laquo;4&raquo; طبق کتاب درسی یونهای \\( NH_4^+\\) و \\(NO_3^- \\) توسط باکتری ها به خاک وارد می شود؛ باکتری های نیترات ساز با مصرف یون آمونیوم، یون نیترات تولید می کنند که وارد خاک می شود، بار این یون مانند بار یون های گیاخاک منفی است. باکتری های نیترات ساز شیمیوسنتز کننده اند و می توانند مواد آلی را بسازند؛ از طرفی همه باکتری ها می توانند طی واکنش های آنزیمی، مولکول های آلی مثل پروتئین ها و نوکلئیک اسیدها را بسازند و این موضوع ربطی به فتوسنتز و یا شیمیوسنتز کنندگی آنها ندارد. بررسی سایر گزینه ها: 1) باکتری نیترات ساز، آمونیوم را مصرف و نیترات را تولید می کند که هر دوی آنها می توانند توسط گیاه جذب شوند. باکتری های نیترات ساز، شیمیوسنتز کننده هستند و انرژی مورد نیاز برای شیمیوسنتز را از واکنش های اکسایشی به دست می آورند. 2) سیانوباکتری با گیاه آزولا که یک گیاه کوچک آبزی است همزیستی دارد. سیانوباکتری ها حاوی سبزینه \\(a\\) هستند که در محدوده طول موج ۶۰۰ تا ۷۰۰ نانومتر بیشترین جذب نور را در بین رنگیزه ها دارد. 3) باکتری های آمونیاک ساز، تثبیت کننده نیتروژن و نیترات ساز، همگی در تأمین نیتروژن مورد نیاز گیاهان نقش دارند؛ باکتری آمونیاک ساز با مصرف مواد آلی یون آمونیوم را تولید می کند.', '2026-02-05 17:20:29'),
(736, 753, 'گزینه&laquo;4&raquo; در مسیر سیمپلاستی آب و مواد محلول در آن، از سیتوپلاسم و پلاسمودسم ها، عبور می کنند. طی این روش، مواد برای جابه جاشدن بین دو یاخته در پوست ریشه، از غشای یاخته ها، عبور نمی کنند. در محل ،لاسمودسم، طبق کنکور تیر ۱۴۰۲ تیغه میانی وجود ندارد. بررسی سایر گزینه ها: 1) هر چند که مسیر سیمپلاستی می تواند ویروس های گیاهی را منتقل کند، اما در این مسیر مواد از غشای یاخته ای و از بین فسفولیپیدهای غشایی عبور نمی کنند، بلکه از طریق کانال های سیتوپلاسمی (پلاسمودسم ها) جابه جا می شوند. 2) در مسیر سیمپلاستی، آب و بسیاری از مواد محلول می توانند منتقل شوند، نه همۀ آن ها. در مسیر عرض غشایی نیز به دلیل نفوذپذیری انتخابی غشا، هر ماده ای امکان ورود به یاخته را ندارد؛ پس این مورد درباره هیچ یک از روش ها صادق نمی باشد. 3) این ویژگی را هم در مسیر عرض غشایی و هم در مسیر سیمپلاستی شاهد هستیم. ترکیبات مختلف در مسیر سیمپلاستی از درون سیتوپلاسم و پلاسمودسم عبور می کنند که در طی این جابه جایی ممکن است از غشای واکوئول ها هم بگذرند و با کمک پروتئین هایی در این غشا جابه جا شوند. در مسیر عرض غشایی نیز؛ ترکیبات با گذر از غشا و دیواره یاخته، بخشی از مسیر خود را در سیتوپلاسم طی می کنند. عبور از غشای یاخته ای هم می تواند با کمک پروتئین ها باشد. صورت سؤال موردی را می خواهد که درباره بعضی از این روش ها صادق باشد.', '2026-02-05 17:20:29'),
(737, 754, 'گزینه&laquo;4&raquo; منظور صورت سؤال، یاخته های نعلی یا \\(U\\) شکل در لایه درون پوست برخی گیاهان تک لپه ای است. است. فقط مورد &laquo;د&raquo; صحیح است. بررسی همۀ موارد الف) نادرست: این یاخته ها در تشکیل لایه درون پوست برخی از گیاهان نقش دارند. لایۀ درون پوست، داخلی ترین لایه در بخش پوست ریشه محسوب می شود و جزئی از بخش آوندی نمی باشد. بلافاصله در خارج از بخش آوندی (آوندهای چوب و آبکش) در ریشه، لایه ریشه زا قرار دارد. ب) نادرست: یاخته های \\(U\\) شکل در ریشه بعضی گیاهان، علاوه بر دیواره های جانبی خود، در دیواره پشتی شان نیز نوار کاسپاری دارند؛ در نتیجه این ویژگی، انتقال مواد از طریق این یاخته ها را به بخش بعدی (جلوتر) غیرممکن می کند. ج) نادرست: در گیاهان جابه جایی شیره خام در مسیرهای طولانی، توسط جریان توده ای و یاخته های آوند چوبی (نه نعلی شکل) انجام می شود. د) درست: در این یاخته ها، نوار کاسپاری علاوه بر دیواره های جانبی (۴ دیواره بالا ،پایین، چپ و راست)، دیواره پشتی را نیز می پوشاند، اما دیواره جلویی (شکمی) نوار کاسپاری ندارد؛ بنابراین یاخته های \\(U\\)شکل فقط در دیواره جلویی خود، فاقد نوار کاسپاری (از جنس چوب پنبه) هستند.', '2026-02-05 17:20:29'),
(763, 780, 'گزینه 4 لایه سطحی پوست از یاخته های پوششی غیر زنده تشکیل شده است. به همین دلیل، در این یاخته ها فرآیندهای زیستی مثل مصرف اکسیژن مشاهده نمی شود. بررسی سایر گزینه ها: 1) بخش ابتدای بینی از پوست نازکی تشکیل شده و این بخش، فاقد یاخته های پوششی مژک دار است. دقت داشته باشید که در مخاط مژک دار هم فقط بعضی از یاخته ها دارای مژک هستند و یاخته های پوششی فاقد مژک هم در این مخاط دیده می شود. 2) پوست مودار، موهای نازکی برای جلوگیری از ورود ناخالصی های هوا دارد. 3) در بینی، شبکه ای وسیع از رگ هایی با دیواره نازک وجود دارد که هوا را گرم میکند؛ بنابراین کل بخش های بینی در گرم کردن هوای ورودی به دستگاه تنفسی نقش دارند.', '2026-02-05 17:20:29'),
(767, 784, 'گزینه 3 درون حبابک های شش های انسان، گروهی از یاخته های بیگانه خوار به نام درشت خوار وجود دارند. این یاخته ها می توانند باکتری هایی را که وارد حبابک ها شده اند، با بیگانه خواری نابود کنند. لذا در پی ورود باکتری های استرپتوکوکوس نومونیا به درون حبابک های شش ها، فعالیت درشت خوارها افزایش می یابد. بررسی سایر گزینه ها: 1) در فرد مبتلا به سینه پهلو، فرایند تنفس با اختلال مواجه می شود. لذا، دفع کربن دی اکسید از بدن نیز مختل می شود و کربن دی اکسید در خون تجمع می یابد. کربن دی اکسید در خون به کربنیک اسید تبدیل می شود و در نتیجه، غلظت کربنیک اسید در خون افزایش می یابد. 2) آنزیم ها در دمای بالاتر ممکن است شکل غیرطبیعی یا برگشت ناپذیر پیدا کنند و غیرفعال شوند. دقت داشته باشید که غیرفعال شدن آنزیم ها در دمای بالا، به صورت دائمی و برگشت ناپذیر است و به همین دلیل، گفته می شود تب بالا خطرناک است. 4) در نتیجة اختلال در فرایند تنفس و تبادلات گازی در حبابکهای شش ها، ورود اکسیژن به درون جریان خون نیز کاهش می یابد. در نتیجه، تعداد یون های آهنِ گروه های هِم مولکول های هموگلوبین که به مولکول اکسیژن متصل هستند، کمتر می شود.', '2026-02-05 17:20:29'),
(784, 801, 'گزینه&laquo;3&raquo; در صورتی که ژنوتیپ والد ماده را BBBb فرض کنیم، گامت های قابل انتظار برای ماده به صورت BB یا Bb هستند و ژنوتیپ یاخته های دوهسته ای به صورت BBBB یا BBbb می باشد. با توجه به ژنوتیپ تخم اصلی (BBb)، ژنوتیپ اسپرم های سازنده تخم اصلی به ترتیب b یا B خواهد بود؛ در نتیجه ژنوتیپ قابل انتظار برای آندوسپرم نیز به صورت BBBBb یا BBBbb خواهد بود. بررسی سایر گزینه ها: 1) اگر ژنوتیپ والد ماده به صورت Bb باشد؛ در نتیجه ژنوتیپ تخم زاهای قابل انتظار به صورت B یا b می باشد که به ترتیب ژنوتیپ اسپرم ها با توجه به ژنوتیپ تخم اصلی Bb یا BB خواهد بود. اگر ژنوتیپ تخم زا b باشد، ژنوتیپ دوهسته ای bb خواهد بود و با اسپرم BB می تواند تخم ضمیمه ای با ژنوتیپ BBbb ایجاد کند. 2) اگر ژنوتیپ والد ماده به صورت BBbb باشد، ژنوتیپ قابل انتظار برای گامت ماده (تخم زا) به صورت BB یا bb یا Bb است که با توجه به ژنوتیپ تخم اصلی، ژنوتیپ bb قابل قبول نیست. حال اگر ژنوتیپ تخم زا را به صورت Bb فرض کنیم، ژنوتیپ دوهسته ای به صورت BBbb است که با فرض تخم اصلی BBb، اسپرم به صورت B است و ژنوتیپ آندوسپرم به شکل BBBbb می تواند باشد. 4) اگر ژنوتیپ والد ماده به صورت BB باشد؛ در نتیجه ژنوتیپ تخم زا و یاخته دوهسته ای به ترتیب B و BB است. با توجه به ژنوتیپ تخم اصلی متوجه می شویم که ژنوتیپ استام به صورت Bb می باشد؛ در نتیجه ژنوتیب تخم ضمیمه و یاخته های آندوسپرم به صورت BBBb می باشد.', '2026-02-05 17:20:29'),
(785, 802, 'گزینه&laquo;1&raquo; فردی که دارای دگره بارز برای صفت گروه خونی Rh است (یعنی حداقل یک الل D دارد)، حتما Rh+ است، اما فردی که Rh- هست قطعا ژن نمود dd دارد و فاقد الل D در یاخته های بدن خود است. بررسی سایر گزینه ها: 2) اگر فرض کنید پدر گروه خونی B با ژن نمود BO و مادر گروه خونی A با ژن نمود مثلا AA داشته باشد، امکان تولد فرزندی با گروه خونی) A با ژن نمود (AO وجود دارد. 3) در صورتی که پدر و مادر هر دو از نظر گروه خونی Rh دارای ژن نمود Dd باشند، فرزند Rh- متولد می شود! 4) اگر هر دو والد AB باشند، فرزند دارای گروه خونی A متولد خواهد شد!', '2026-02-05 17:20:29'),
(786, 803, 'گزینه&laquo;1&raquo; در بیماری هموفیلی، فرد در انعقاد خون دچار اختلال شده است، در شایعترین نوع هموفیلی، فاکتور انعقادی شماره ۸ که نوعی پروتئین در بدن افراد است، ساخته نمی شود. در بیماری فنیل کتونوری نیز آنزیم پروتئینی که وظیفه تجزیه آمینواسید فنیل آلانین را برعهده دارد، تولید نمی شود. این گزاره در خصوص هر دو بیماری هموفیلی و فنیل کتونوری صادق است. بررسی سایر گزینه ها: 2) در بیماری های ژنتیکی با الگوی وراثت مستقل از جنس (مثل فنیل کتونوری)، الل بیماری از هر دو والد به فرزند پسر منتقل می شود، اما خب در هموفیلی که الگوی وراثت آن وابسته به جنس (X) است، پسر الل مربوط به آن را از مادر خود دریافت می کند. پدر الل X خود را به پس نمی دهد؛ بنابراین این گزاره فقط در خصوص بیماری فنیل کتونوری صادق است. 3) صفاتی را که جایگاه ژنی آنها در یکی از فام تن های غیر جنسی قرار داشته باشد، مستقل از جنس و صفاتی را که جایگاه ژنی آنها در یکی از فام تن های جنسی قرار داشته باشد، وابسته به جنس می گویند. بیماری هموفیلی از الگوی وراثت وابسته به جنس و بیماری فنیل کتونوری از الگوی وراثت مستقل از جنس، پیروی می کند؛ پس در بیماری هموفیلی، هر مرد بیمار، فقط الل مربوط به این بیماری را بر روی کروموزوم X خود دارد. این گزاره در خصوص بیماری هموفیلی بر خلاف فنیل کتونوری صادق است. 4) فنیل کتونوری یک بیماری نهفته است که فرد نمی تواند آنزیم تجزیه کننده فنیل آلانین را بسازد، وقتی نوزاد متولد می شود، علائم آشکاری ندارد. در عین حال، تغذیه نوزاد مبتلا به فنیل کتونوری با شیر مادر (که حاوی فنیل آلانین است) به دلیل تجمع ترکیبات حاصل از فنیل آلانین، به آسیب یاخته های مغزی او می انجامد، اما می توان از بروز این بیماری (نههه درمان) جلوگیری کرد. چه جوری؟ با تغذیه نکردن از خوراکی هایی که فنیل آلانین دارند؛ پس دقت کنید بیماری ژنتیکی فنیل کتونوری به شکل کامل قابل درمان نیست؛ بلکه با عدم تغذیه از مواد حاوی فنیل آلانین (مثل شیر مادر) می توان از بروز اثرات آن جلوگیری کرد.', '2026-02-05 17:20:29'),
(787, 804, 'گزینه&laquo;3&raquo; ژن نمود فرزندان از نظر هموفیلی⟵\\( X^H X^H\\) و \\(X^H Y\\) و \\(X^h X^h\\) و \\(X^h Y\\)، ژن نمود فرزندان از نظر گروه خونی \\(AB+AO+BO+OO⟵ABO\\) و ژن نمود فرزندان از نظر فنیل کتونوری⟵ \\(PP + Pp + pp \\)خواهد بود؛ پس تولد پسر \\( X^H Y PP \\) امکان پذیر هست. همچنین فرزندان می توانند گروه خونی \\(AB\\)نیز داشته باشند. البته دقت کنید یک آنزیم نمی تواند هم کربوهیدرات \\(A\\)و هم کربوهیدرات \\(B\\)را به غشای یاخته ها اضافه کند؛ بلکه در فرد ،\\(AB\\) دو نوع آنزیم تولید می شود که یکی کربوهیدرات \\(A\\) و دیگری کربوهیدرات \\(B\\) را به غشای گویچه های قرمز نابالغ اضافه می کند. بررسی سایر گزینه ها: 1) امکان تولد پسری هموفیل \\((X^h Y)\\) و مبتلا به فنیل کتونوری \\((pp)\\)که گروه خونی \\(B\\) یا \\(O\\)داشته باشد، وجود دارد. 2) تولد دختری با گروه خونی \\(AB\\) و \\(PP\\)(کاملا سالم) که الل \\(X^h\\) را داشته باشد، ممکن است؛ چراکه مادر این دختر ناخالص است و می تواند ادگره \\(X^h\\) خود را به دخترش بدهد. دختر \\(X\\)دیگر خود را از پدر سالمش دریافت می کند. 4) دختری با گروه خونی \\(AB\\) یا \\(B\\) دارای کربوهیدرات\\(B\\) است اما فرد \\(AO\\)یا \\(OO\\) این کربوهیدرات را ندارد و می تواند متولد شود. همچنین اگر این دختر مبتلا به فنیل کتونوری \\((pp)\\)باشد، به دلیل مصرف فنیل آلانین ممکن است دچار آسیب مغزی شده باشد (فنیل آلانین در شیر مادر وجود دارد)؛ این فرد با به ارث بردن دگره \\(X^H\\) از نظر هموفیلی سالم است (دارای فاکتور انعقادی شماره هشت می باشد) در واقع هم پدر و هم مادر\\(X^H\\) دارند و آن را به فرزند خود می توانند منتقل کنند. نکته در هموفیلی وجود یک الل \\(XH\\)برای تولید فاکتور انعقادی هشت کافی است همچنین در گروهی از افراد وجود یک دگره \\(Xh\\)برای ایجاد هموفیلی هم کافی است اگه گفتی در چه کسانی؟ آفرین در مردان مبتلا که ژنوتیپ \\(XY\\)دارند.', '2026-02-05 17:20:29'),
(788, 805, 'گزینه&laquo;4&raquo; با توجه به این که رویان (لپه یا برگ های رویانی بخشی از رویان است) دارای ژنوتیپ AB است؛ پس ژنوتیپ اندوسپره نیز دارای هر دو الل A و B بوده و می تواند یا AAB یا ABB باشد. (آندوسپرم از الل مادری دو تا دارد). پوسته دانه از تغییر پوسته تخمک حاصل می شود، لذا ژنوتیپی مشابه با والد ماده خواهد داشت. می دانیم که دو الل تکراری در ژنوتیپ آندوسپرم، مربوط به یاخته دوهسته ای (یک الل مشابه یاخته تخم زا دارد) است، لذا اگر آندوسپرم ژنوتیپ AAB داشته باشد، پوسته دانه باید حتما دارای الل A باشد و در نتیجه می تواند ژنوتیپ AB یا AA داشته باشد. آندوسپرم AAB حاصل لقاح یاخته دو هسته ای AA با گامت نر B است؛ پس ژنوتیپ یاخته زایشی و رویشی که در گرده رسیده وجود دارند نیز B بوده و لذا ژنوتیپ دانۀ گردۀ رسیده سازندۀ گیاه جدید BB خواهد بود (تأیید 4 و رد 2). بررسی سایر گزینه ها: 1و ۳) اگر ژنوتیپ آندوسپرم ABB باشد، ژنوتیپ پوسته دانه BB یا AB خواهد بود (رد 3) اگر ژنوتیپ پوسته دانه BB باشد؛ پس برای تولید آندوسپرم مورد نظر، گامت نر A شرکت داشته و لذا ژنوتیپ دانۀ گردۀ رسیدۀ سازندۀ گیاه جدید AA خواهد بود (رد1). همچنین 1 را می توان اینگونه نیز رد کرد که از آنجا که دانه گردۀ رسیدۀ شامل دو یاخته رویشی و زایشی با ژنوتیپ یکسان است (چون حاصل میتوز هستند)؛ پس همواره ژنوتیپ خالص خواهد داشت و نمی تواند مثلا ژنوتیپ AB داشته باشد.', '2026-02-05 17:20:29'),
(789, 806, 'گزینه&laquo;2&raquo; فردی که پروتئین D را تولید می کند و در غشاء گویچه های قرمز خود این پروتئین را دارد، فنوتیپ بارز و ژنوتیپ خالص(DD)یا ناخالص (Dd) مربوط به این صفت را دارد و طبق توضیحات، حداقل یک دگره بارز را در ژنوتیپ خود قرار داده است. بررسی سایر گزینه ها: 1) توالی های نوکلئوتیدی مختلف یعنی وجود دگره های متفاوت؛ فردی که دو توالی نوکلئوتیدی مختلف در جایگاه ژنی گروه خونی ABO در فام تن های شماره ۹ خود دارد، ژنوتیپ ناخالص خواهد داشت (AO، BO یا AB.) از طرفی، می دانیم که اضافه شدن کربوهیدرات های A و B به غشای گویچه قرمز، یک واکنش آنزیمی است. در رابطه با این صفت، دو نوع آنزیم وجود دارد. یکی آنزیم A که کربوهیدرات A را به غشا اضافه می کند و دیگری آنزیم B، که کربوهیدرات B را اضافه می کند. اگر هیچ یک از این دو آنزیم وجود نداشته باشند، آن گاه فرد گروه خونی O خواهد داشت. مطابق توضیحات، فرد دارای ژنوتیپ AO، تنها یک نوع آنزیم مختص به این صفت را می سازد، اما دو دگره و دو توالی نوکلئوتیدی متفاوت دارد. 3) فردی که فقط یک نوع الل برای گروه خونی ABO دارد، دارای ژنوتیپ خالص است و میتواند ژنوتیپهای BB، AA یا OO را داشت باشد. افراد دارای ژنوتیپ AA یا BB یک نوع کربوهیدرات گروه خونی را در سطح غشاء گویچه های قرمز خود قرار می دهند، اما افراد دارای ژنوتیپ ،OO گروه خونی O دارند و هیچ کدام از کربوهیدرات های گروه خونی را در سطح گویچه های قرمز خود قرار نمی دهند. 4) اگر فردی برای گروه های خونی Rh و ABO، به ترتیب ژنوتیپ های dd و OO را داشته باشد، هیچ پروتئین مربوط به گروه خونی را نمی سازد.', '2026-02-05 17:20:29'),
(790, 807, 'گزینه&laquo;4&raquo; در صورت سؤال از ما ژن نمود پوسته دانه حاصل از آمیزش این دو گیاه را خواسته است که همان ژنوتیپ پوسته تخمک (ژنوتیپ والد ماده) را خواهد داشت ژنوتیپ یاخته سازنده لوله گرده (یاخته رویشی!) نیز مشابه یکی از دگره های والد نر است. مطابق توضیحات، اگر ژنوتیپ پوسته دانه و والد ماده، RW باشد؛ نباید والد نر دگره W را داشته باشد. سایر موارد، مطابق موارد نوشته شده در والدین قابل انتظار خواهند بود.', '2026-02-05 17:20:29'),
(791, 808, 'گزینه&laquo;1&raquo; در بیماری های وابسته به \\(X\\)، در مردان فرد ناقل وجود نخواهد داشت، چراکه فقط یک کروموزوم \\(X\\) دارند. در حالت مستقل از جنس بارز نیز، فرد ناخالص بیمار خواهد بود، نه ناقل؛ چراکه وجود دگره بیماری، سبب بروز علائم خواهد شد. بررسی سایر گزینه ها: 2) در بیماری وابسته به \\(X\\) نهفته (مثل هموفیلی)، پدری که سالم است، \\( (X^H Y)\\) به طور حتم دختر سالمی نیز خواهد داشت؛ چراکه دگره سلامت خود را به دختران انتقال می دهد. 3) مادر مبتلا به بیماری وابسته به \\(X\\) نهفته، ژنوتیپ خالص داشته \\((X^h X^h)\\)و نمی تواند پسری سالم داشته باشد؛ چراکه در هر حال دگره بیماری را به هر فرزند پسر خود منتقل می نماید. 4) در بیماری مستقل از جنس بارز، اگر مادر \\((aa)\\)و پدر \\((Aa)\\)باشد، امکان تولد دختر بیمار \\((Aa)\\) وجود دارد. در حالت وابسته به \\(X\\) بارز، اگر پدر بیمار باشد، می تواند الل بیماری را به دختر بدهد \\( (X^A Y &times; X^a X^a)\\). در حالت وابسته به \\(X\\) نهفته، پدر بیمار و مادر ناقل می توانند دختر بیمار داشته باشند.', '2026-02-05 17:20:29'),
(792, 809, 'گزینه&laquo;2&raquo; هر یک از ما ویژگی هایی داریم که ما را با آنها می شناسند. بعضی از این ویژگی ها را از والدین خود دریافت کرده ایم؛ مثل رنگ چشم، رنگ مو یا گروه خونی. به عبارتی این ویژگی ها، ارثی هستند. ویژگی هایی را هم می شناسیم که ارثی نیستند؛ مثل تیره شدن رنگ پوست که به علت قرار گرفتن در معرض آفتاب ایجاد شده است. بررسی سایر گزینه ها: 1) مرد مبتلا به هموفیلی (بیماری وابسته به جنس نهفته) دارای ژنوتیپ \\(X^h Y\\) است و زن بیمار ژنوتیپ \\(X^h X^h\\)دارد؛ مرد در طی هر بار گامت زایی (هر بار تقسیم میوز) می تواند دو نوع گامت (یکی دارای کروموزوم \\(Y\\)و دیگری دارای کروموزوم \\(X^h\\)) و زن بیمار فقط یک نوع گامت (دارای کروموزوم \\(X^h\\)) ایجاد کند. دقت کنید در مردان، در هر بار گامت زایی، ۴ گامت ایجاد می شود که دوتا \\(X^h\\) و دوتا \\(Y\\) دارند. 3) پیش از کشف قوانین وراثت توسط گریگور مندل، تصور بر آن بود که صفات فرزندان، آمیخته ای از صفات والدین و حد واسطی از آنها است، اما مندل اثبات کرد که این تصور غلط است. 4) دگره ای از گروه خونی \\(ABO\\)که هیچ آنزیمی مرتبط با این گروه خونی را نمی سازد دگره \\( (i)O\\) است؛ پس منظور از بخش اول این گزینه، افراد فاقد الل \\(O\\)است که می توانند ژنوتیپ های\\(AB\\)، \\(AA\\) و \\(BB\\)داشته باشند، با توجه به ژنوتیپ های مطرح شده، فنوتیپ های \\(A\\)، \\(B\\) و \\(AB\\) (سه نوع فنوتیپ) در این جمعیت مشاهده می شود.', '2026-02-05 17:20:29'),
(793, 810, 'گزینه&laquo;2&raquo; ذرت هایی که صفر یا شش دگر بارز دارند، در یکی از دو آستانه نمودار زنگوله ای قرار دارند. این ذرت ها از ذرت مورد سؤال، بیش از یک ستون فاصله دارند (۲ ستون فاصله دارند از هم) بررسی سایر گزینه ها: 1) ذرت aabbCC که دو الل بارز دارد، کاملا مجاور ذرت مورد سؤال است، یعنی فاصله ای از هم ندارند. 3) ذرت هایی با پنج دگره بارز، می توانند نزدیک ترین رنگ را به ذرت های کاملا قرمز داشته باشند؛ چراکه هر چه تعداد الل های بارز بیشتر باشد، رنگ ذرت به ذرت های کاملا قرمز، نزدیک تر است. ذرت های با ۳ دگره بارز به اندازه یک ستون (نه بیشتر) با ذرت های دارای ۵ دگره بارز فاصله دارند. 4) طبق نمودار شکل ۹ کتاب درسی در فصل ۳ زیست شناسی (۳)؛ ذرت هایی با بیش از یک جایگاه ژنی خالص می توانند در ستون های صفر، 1، 2، 3، 4، 5 و 6 باشند که خب همۀ اینها لزوما از ذرت های میانه نمودار، بیش از یک ستون فاصله ندارند.', '2026-02-05 17:20:29'),
(794, 811, 'گزینه&laquo;4&raquo; بررسی سایر گزینه ها: 1) اگر در ژنوتیپ آندوسپرم، ۵ نوع الل وجود داشته باشد، الل ها در دو جایگاه متفاوت از هم و در یک جایگاه مشابه هم هستند، مثلا آندوسپرم می تواند به صورت aaaBbbCcc یا AAABBbCC و رویان می تواند به صورت aaBbCc یا AABbCc باشد. همان طور که می بینید، در ژنوتیپ ساقه رویانی حداقل دو دگره بارز و غیر یکسان وجود دارد. البته دقت داشته باشید که شما می توانید ۴ نوع ژنوتیپ دیگر هم داشته باشید (مثلا به جای اینکه جایگاه اول خالص بارز و یا نهفته باشد، جایگاه های دوم و یا سوم چنین حالتی را داشته باشند)، ولی در پاسخ به سؤال تفاوتی ایجاد نمی کند. 2) اگر در ژنوتیپ آندوسپرم ۳ نوع الل باشد، یعنی در هر جایگاه، فقط الل های مشابه هم (چه خالص چه ناخالص) وجود دارد، مثلا آندوسپرم می تواند به صورت aaabbbccc یا AAABBBCCC باشد یا حتی AAAbbbccc و...؛ در این وضعیت ممکن است ژنوتیپ هر دو والد د سه جایگاه ژنی به صورت ناخالص بوده باشد. 3) اگر در ژنوتیپ آندوسپرم ۴ نوع الل باشد، یعنی فقط در یکی از جایگاه ها الل ها متفاوت از هم هستند، مثلا آندوسپرم می تواند به صورت Aaabbbccc یا aaaBbbccc یا aaabbbCcc یا AAaBBBCCC یا AAABBbCCC یا AAABBBCC باشد که حداقل یک والد باید الل بارز داشته باشد تا این امکان فراهم شود.', '2026-02-05 17:20:29'),
(795, 812, 'گزینه&laquo;3&raquo; صفاتی که بر روی دناهای حلقوی میتوکندری جایگاه ژنی دارند، فقط از مادر به همۀ فرزندان منتقل می شوند، زیرا در لقاح، فقط میتوکندری های تخمک به یاخته تخم منتقل می شوند و فقط سراسپرم (هسته آن) وارد اووسیت ثانویه می شود. دو انتهای دنای حلقوی به هم متصل اند. بررسی سایر گزینه ها: 1) صفت های مستقل از جنس نیز از پدر به دختر قابل انتقال هستند، اما در کروموزوم های غیر جنسی جایگاه ژنی دارند. 2) صفاتی که بر روی فام تن Y قرار دارند، از پدر فقط به پسر می رسند. کروموزوم Y در تعیین جنسیت مستقیما نقش دارد. جایگاه ژنی صفت هموفیلی بر روی کروموزوم X قرار دارد. علاوه بر صفات وابسته به جنس، صفات مستقل از جنس نیز می توانند از ماد به پسر منتقل شوند.', '2026-02-05 17:20:29'),
(796, 813, 'گزینه&laquo;2&raquo; وجود همه فنوتیپ های گروه خونی \\(ABO\\)در بین فرزندان (گروه خونی \\(A\\)، \\(B\\)، \\(AB\\) و\\(O\\) ) فقط در شرایطی امکان پذیر است که یک والد ژنوتیپ \\(AO\\)و دیگری ژنوتیپ \\(BO\\)داشته باشد. لذا هر والد تنها در یکی از کروموزوم های شماره ۹ خود الل \\(A\\) یا \\(B\\) را دارد و از روی آن آنزیم \\(A\\) یا \\(B\\) را می سازد. بررسی سایر گزینه ها: 1) برای گروه خونی \\(Rh\\)، دو فنوتیپ مثبت و یا منفی وجود دارد. مثلا در شرایطی که والدین دارای ژنوتیپ \\(dd\\)و \\(Dd\\) باشند، هر دو فنوتیپ \\(Rh\\) مثبت و منفی در فرزندان یافت می شود؛ اما در این حالت یکی از والدین در بدن خود فاقد الل \\(D\\)برای تولید پروتئین \\(D\\) خواهد بود. 3) فقط در صورتی ممکن است که در فرزندان فقط گروه خونی \\(A\\) مثبت و \\(B\\) مثبت وجود داشته باشد که والدین از نظر گروه خونی \\(ABO\\) ژنوتیپ AB و \\(OO\\) و از نظر گروه خونی \\(Rh\\) ژنوتیپ \\(dd\\) و \\(DD\\)و یا \\(DD\\) و \\(Dd\\)یا \\(DD\\)داشته باشند. ژنوتیپ \\(dd\\) فاقد الل \\(D\\)است. 4) زمانی گروه خونی \\(ABO\\) فرزندان با والدین متفاوت خواهد بود که والدین \\(AA\\)) (\\(BB\\) ویا AB) و (\\(OO\\) باشند. در صورتی که والدین گروه خونی \\(AA\\)و \\(BB\\) داشته باشند (حالت اول)، واکنش آنزیمی افزوده شدن کربوهیدرات \\(A\\) و یا \\(B\\) گروه خونی به غشای یاخته ها، در هر دو والد انجام می شود.', '2026-02-05 17:20:29'),
(797, 814, 'گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;ج&raquo; غیر ممکن هستند. حالا می رویم سراغ بررسی عبارت ها: الف) اگر زنبور نر با ژنوتیپ K با زنبور ملکه دارای شاخک بلند (BB) یا متوسط (BK) آمیزش انجام دهد، امکان تولید زنبور کارگر با شاخک متوسط (ژنوتیپ BK) وجود خواهد داشت. ب) این مورد به دو علت نادرست است، اول این که زنبور نر هاپلوئید است و لذا ممکن نیست ژنوتیپ BK و شاخک متوسط داشته باشد. در واقع شاخک زنبور نر یا بلند )ژنوتیپ (B و یا کوتاه )ژنوتیپ (K خواهد بود. به علاوه زنبور ملکه BB با بکرزایی، همواره زنبور نری با ژنوتیپ B تولید خواهد کرد. ج) زنبور ملکه با شاخک کوتاه ژنوتیپ KK دارد، لذا زنبور مادۀ کارگر حاصل از تولیدمثل آن حداقل یک اللK خواهد داشت و نمی تواند دارای شاخک بلند )ژنوتیپ (BB باشد. د) زنبور کارگر، ماده ای نازا است و اصلا توانایی تولیدمثل ندارد.', '2026-02-05 17:20:29'),
(798, 815, 'گزینه&laquo;3&raquo; دقت کنید در این سؤال باید حالتی را پیدا کنید که با هر ژنوتیپ قابل تصوری برای پدر امکان تولد فرزند مطرح شده وجود داشته باشد. مادر ناخالص برای صفات هموفیلی و فنیل کتونوری ژنوتیپ \\( X^H X^h Ff \\) دارد. در این حالت پدر هر ژنوتیپی داشته باشد، امکان تولد دختری سالم و ناخالص وجود دارد؛ چراکه مادر هم الل سالم را دارد و هم الل بیماری را. بررسی سایر گزینه ها: 1) در بیماری فنیل کتونوری، در صورتی که پدر سالم و خالص \\((FF)\\)و مادر ناخالص \\((Ff)\\)باشد، امکان تولد پسری مبتلا به این بیماری \\((ff)\\)وجود ندارد. 2) در بیماری فنیل کتونوری، در صورتی که پدر سالم و خالص \\((FF)\\) و مادر خالص و بیمار \\((ff)\\) باشد، امکان تولد پسری مبتلا به این بیماری وجود ندارد، اما مادر مبتلا به هموفیلی، حتما پسر مبتلا به هموفیلی خواهد داشت. 4) ژنوتیپ مادر سالم و خالص برای بیماری های ذکر شده، \\( X^H X^H FF\\) است. در صورتی که پدر مبتلا به هر دو بیماری باشد، امکان تولد دختری سالم و خالص وجود ندارد! دقت کنید در این حالت دختر می تواند سالم باشد، اما خالص نیست!', '2026-02-05 17:20:29'),
(799, 816, 'گزینه&laquo;3&raquo; هر پسر کروموزوم \\(X\\)خود را از مادر دریافت می کند؛ پس پسری که مبتلا به این بیماری است، کروموزوم حاوی الل بیماری را از مادر دریافت کرده و مادر وی، خالص بارز یا ناخالص است که در هر دو حالت، به دلیل وجود الل بارز بیماری زا ،مبتلا به این بیماری می باشد. بررسی سایر گزینه ها: 1) پدر سالم الل \\(X^a \\) خود را به دختر میدهد، اما اگر مادر دارای الل بیماری \\((X^A)\\)باشد، میتواند آن را به دختر خود انتقال دهد و سبب بیمارشدن وی شود (با ژن نمود \\(X^A X^B\\)( 2) دختر بیمار می تواند ناخالص باشد که ممکن است الل بیماری را از پدر دریافت کرده و دارای مادری سالم باشد. در این صورت، برادر او که کروموزم \\(X\\) خود را از مادر دریافت کرده است، سالم خواهد بود. 4) مادر سالم، دارای ژنوتیپ خالص و نهفته است \\((X^a X^a)\\)که فقط الل سالم را به پسران خود می دهد؛ پس همۀ پسران سالم خواهند بود، نه بیمار.', '2026-02-05 17:20:29'),
(800, 817, 'گزینه&laquo;3&raquo; فقط مورد &laquo;ج&raquo; عبارت را به درستی تکمیل می کند. در فصل سوم کتاب درسی دوازدهم، تنها دو بیماری فنیل کتونوری (مستقل از جنس نهفته) و هموفیلی (وابسته به \\(X\\) نهفته) مطرح شده اند. بررسی عبارت ها: الف) در هیچ کدام از بیماری های مذکور، پدر و مادر بیمار دختر سالم نخواهند داشت زیرا پدر و مادر بیمار برای این صفات فقط الل نهفته دارند که آن را به فرزندان منتقل می کنند. ب) از نظر فنیل کتونوری، اگر پدر \\(ff\\)(بیمار) و مادر \\(Ff\\)(ناقل و سالم) باشد، امکان تولد پسری بیمار \\((ff)\\)وجود دارد. از نظر هموفیلی نیز اگر پدر \\(X^HY\\) (بیمار) و مادر \\(X^HX^h\\)(ناقل و سالم) باشد، امکان تولد پسری با ژنوتیپ مشابه پدر وجود خواهد داشت. این مورد برای هر دو صفت ممکن است. ج) دختر خالص می تواند سالم یا بیمار باشد. در مورد فنیل کتونوری در حالت \\( Ff&times;ff \\) امکان تولد دختر خالص و بیمار \\((ff)\\) وجود دارد. در مورد هموفیلی اگر پدر \\(X^HY\\) و مادر \\(X^hX^h\\) باشد همۀ دختران \\(X^HX^h\\) خواهند بود که ناخالص است. د) از نظر فنیل کتونوری از مادر \\(ff\\) (بیمار) و پدر \\(FF\\)(ناقل) امکان تولد فرزندی با فنوتیپ مشابه با مادر وجود دارد. از نظر هموفیلی نیز اگر پدر \\(X^HY\\) (سالم) و مادر \\(X^HX^h\\) (بیمار) باشد، امکان تولد پسری هموفیل (با فنوتیپ شبیه به مادر) وجود خواهد داشت؛ پس این مورد درباره هر دو صفت صادق می باشد.', '2026-02-05 17:20:29'),
(801, 818, 'گزینه&laquo;4&raquo; مثلا صفت گروه خونی \\(ABO\\)تحت کنترل الل های \\(I^A\\) ، \\(I^B\\) و \\(i\\) است. الل \\(I^A\\) و \\(I^B\\) بر \\(i\\) بارز هستند، اما رابطه بین الل های \\(A\\)و \\(B\\)، هم توانی است. در این حالت شش نوع ژنوتیپ برای گروه خونی \\((OO - BO - BB - AB - AO - AA) \\) و ۴ نوع فنوتیپ برای ایر گروه های خونی \\((O-AB-B-A)\\) وجود دارد؛ پس می توان گفت از نظر فنوتیپ حداقل ۴ نوع مختلف در جمعیت نمایان می شود. بررسی سایر گزینه ها: 1) شایع ترین نوع هموفیلی (اختلال در فرایند لخته شدن خون) به فقدان عامل انعقادی شماره8 \\((VIII)\\)مربوط است. ممکن است علت اختلال در انعقاد خون، چیزی غیر از ساخته نشدن عامل انعقادی ۸ باشد. 2) صفات وابسته به جنس می توانند بر روی \\(X\\)باشند یا \\(Y\\)، زنان که دو تا \\(X\\) دارند، این ژن را بر روی هر دو کروموزوم \\(X\\) خواهند داشت، اما در مردان این گونه نخواهد بود. دقت کنید زنان ژن های بر روی فام تن \\(Y\\) را نخواهند داشت! 3) به طور مثال گروه خونی \\(ABO\\) در جمعیت به صورت گسسته دیده می شود. اگر مادر و پدر \\(AB\\)باشند، فرزندان آنها می توانند فنوتیپ \\(AB\\)، \\(A\\) و \\(B\\) داشته باشند. گروه خونی \\(AB\\) فنوتیپ حد واسط محسوب نمی شود؛ چراکه رابطه بین الل های \\(A\\) و \\(B\\) هم توانی است (نههه بارزیت ناقص)؛ بنابراین بخش دوم این گزینه فقط در شرایطی درست است که رابطه بین الل ها بارزیت ناقص باشد (نههه رابطه هم توانی یا بارز نهفتگی)', '2026-02-05 17:20:29'),
(802, 819, 'گزینه&laquo;3&raquo; یک زن سالم خالص از نظر بیماری وابسته به X نهفته (مثل هموفیلی) روی هر فام تن جنسی خود فقط دگره بارز یا سالم را خواهد داشت، بنابراین در تمامی فرزندان وی حداقل يك دگره بارز (سالم) قابل مشاهده است؛ در نتیجه فرزندان با داشتن این دگره، هرگز به بیماری مبتلا نخواهند شد، حتی اگر فرزند دختر دگرۀ نهفته را نیز داشته باشد. بررسی سایر گزینه ها: 1) طبق فرض سؤال، ژنوتیپ این زن \\(X^AX^A\\)خواهد بود؛ یعنی بر روی هر فام تن جنسی خود یک دگره بارز را دارد؛ پس هر دو والد حداقل یک دگره بیماری را داشته اند که آن را به فرزند خود داده اند. اگر مادر او ناخالص باشد \\((X^AX^a) \\) ،امکان سالم بودن برادر این زن وجود خواهد داشت (اگر الل \\(X^a\\)و سلامت مادر را دریافت کند.) 2) اگر مردی از نظر این صفت سالم باشد، قطعا به صورت خالص نهفته خواهد بود .\\((aa)\\) این فرد دگره های نهفته خود را از پدر و مادر دریافت کرده است؛ حال اگر والدین علاوه بر دگره نهفته دارای دگره بارز نیز باشند (ناخالص)، در مورد این صفت بیمار هستند. 4) مردی که از نظر نوعی بیماری مستقل از جنس نهفته بیمار باشد، قطعا به صورت خالص \\((aa)\\) است. این فرد یکی از دگره های نهفته خود را به دخترش منتقل می کند؛ حال اگر از مادر دگره باز به دختر به ارث برسد، دختر سالم خواهد شد.', '2026-02-05 17:20:29'),
(803, 820, 'گزینه&laquo;2&raquo; یکی از نتایج آزمایش های واتسون و کریک مطرح کردن مدل نردبان مارپیچ در هر یک از رشته های دنا، دورشته ای است. در این مدل، ستون های این نردبان را قند و فسفات و پیوند بین آنها و پله ها را بازهای آلی و پیوندهای هیدروژنی بین آن ها، تشکیل می دهند. در هر یک از رشته های دنا، بین قند یک نوکلئوتید و قند نوکلئوتید مجاور پیوند فسفودی استر، و بین بازهای روبه روی هم (بین دو رشته سازندۀ دنا) پیوند هیدروژنی برقرار است. بررسی سایر گزینه ها: 1) در همانندسازی غیر حفاظتی، دناهای حاصل از همانندسازی قطعاتی از رشته های قبلی و رشته های جدید را به صورت پراکنده در هر رشته مولکول دنای خود دارند. مزلسون و استال در نتیجه آزمایشهای خود دریافتند که همانندسازی دنا، به صورت نیمه حفاظتی (نه غیر حفاظتی) انجام می شود که طی آن هر مولکول دنا، یک رشته جدید و یک رشته قدیمی دارد. ۳) قابل انتقال بودن مادۀ وراثتی از نتایج آزمایش های گریفیت بود، ولی دقت کنید که در نتیجه آزمایش های ایوری مشخص شد که عامل اصلی انتقال صفات وراثتی، دنا است و برخلاف عقیده بسیاری از دانشمندان، پروتئین ها عامل اصلی انتقال صفات نیستند. 4) چارگاف ثابت کرد که تصور تساوی تعداد چهار نوع نوکلئوتید در دنای جانداران، حقیقت ندارد بلکه در مولکول دنا A با T و C با G برابر است نه هر چهارتا با هم. براساس پژوهش های چارگاف معلوم شد که در یک مولکول دنا (که دو رشته دارد)، میزان بازهای آلی آدنین با تیمین و گوانین با سیتوزین برابر است. در حالی که نوکلئیک اسیدهای دیگری هم داریم مثل رنا که تک رشته ای است و این قانون لزوما برای آن صدق نمی کند.', '2026-02-05 17:20:29'),
(804, 821, 'گزینه&laquo;3&raquo; براساس مربع های پانت، شانس تولد فرزندی مبتلا به فنیل کتونوری، \\(\\frac{2}{4 }\\) (دو خانه از ۴ از خانه مربع پانت) است. در حالی که شانس تولد فرزند سالم از نظر بیماری هموفیلی،\\(\\frac{3}{4 }\\) (یعنی ۳ خانه از ۴ خانه مربع پانت!) است. بررسی سایر گزینه ها: 1) همانطور که در مربع پانت مربوط به گروه خونی \\(ABO\\)مشاهده می کنید، شانس تولد فرزندی با گروه خونی\\(A\\)، \\(\\frac{2}{4 }\\) است؛ یعنی شانسی برابر با تولد فرزند مبتلا به فنیل کتونوری. 2) طبق مربع پانت مربوط به بیماری فنیل کتونوری، شانس تولد فرزند بیمار و سالم در این آمیزش، با هم برابر است. 4) مطابق مربع پانت مربوط به بیماری هموفیلی، شانس تولد فرزند بیمار \\(\\frac{1}{4 }\\) است؛ یعنی یک خانه از ۴ خانه مربع پانت.', '2026-02-05 17:20:29'),
(805, 822, 'گزینه&laquo;4&raquo; همه موارد به نادرستی بیان شده اند. برای حل این تست باید به شکل کتاب درسی دقت کنید: جایگاه (۱) طبق شکل کتاب مرتبط با ذرت هایی است که فقط یک دگره عامل رنگ قرمز (بارز) دارند و جایگاه (۲)مرتبط با ذرت هایی است که چهار دگره عامل رنگ قرمز (بارز) دارند. بررسی عبارت ها: تعداد دگره های قرمز الف) با توجه به ژنوتیپ ذرت های دارای ۴ دگره بارز، به طور مثال ذرتی با ژنوتیپ AAbbCC به دلیل فقدان دگره B، نمی تواند طی خود لقاحی ذرتی کاملا قرمز با ژنوتیپ AABBCC ایجاد کند. ب) اگر به ذرت هایی با یک دگره بارز دقت کنید، واضح است هیچ کدام در همه جایگاه های خود الل بارز ندارند؛ بلکه فقط در یکی از جایگاه های خود یک دگره بارز دارند!! ج) با توجه به شکل کتاب درسی، در ذرت هایی که فقط یک دگره بارز دارند، همگی در دو جایگاه خود خالص و در یک جایگاه ناخالص می باشند (ژنوتیپ های Aabbcc، aaBbcc و aabbCc) و اگر بیشتر بیشتر دقت کنید در ذرت هایی با ۴ دگره بارز، فقط برخی از آنها با ژنوتیپ های AabCc،AaBBCc و AaBbCC در دو جایگاه خود ناخالص و در یک جایگاه خالص می باشند و بقیه در همه جایگاه های ژنی خود، خالص می باشند؛ پس امکان ویژگی مطرح شده در سؤال وجود ندارد. د) اگر به ذرت های با ۴ دگره بارز دقت کنید، هیچ کدام از ژنوتیپ ها فقط دارای دو جایگاه خالص نمی باشد!! یا در همه جایگاه ها خالص هستند و یا فقط یک جایگاه خالص دارند؛ پس این مورد نیز نادرست است.', '2026-02-05 17:20:29'),
(806, 823, 'گزینه&laquo;3&raquo; در مارهای حاصل از بکرزایی، کروموزوم های همتا، ژن های کاملا یکسانی دارند؛ پس مارهای حاصل از بکرزایی، از لحاظ ژنوتیپی برای تمام صفات خود، کاملا خالص هستند و امکان تولد ماری با ژنوتیپ ناخالص Aabb در بین آنها وجود نخواهد داشت. دقت کنید طی بکرزایی این مار، گامت های AB،Ab،aB و ab تولید می شوند و سپس از روی همین دگره ها، دگره دیگری ساخته می شود پس نوع الل های فام تن ها تغییری نمی کند. بررسی سایر گزینه ها: 1) از آنجایی که بی مهره مطرح شده در این گزینه دیپلوئید است، پس منظور کرم پهن است، چراکه زنبور نر حاصل از بکرزایی ملکه، هاپلوئید است. در صورتی که گامت های Ab و AB در کرم هرمافرودیت با هم لقاح کنند، این جانور حاصل خواهد شد. 2) زنبور نر با ژنوتیپ و فنوتیپ Ab می تواند از میوز و بکرزایی زنبور ملکه AaBb حاصل گردد. 4) ماری که حاصل بکرزایی باشد و ژنوتیپ خالص aaBB را داشته باشد، فنوتیپ aB را خواهد داشت.', '2026-02-05 17:20:29'),
(807, 824, 'گزینه&laquo;1&raquo; بله! مثلا در بیماری فنیل کتونوری. اگر در این صفت، فردی، فقط دگره های نهفته داشته باشد، بیمار می باشد \\((ff)\\) اما اگر فنیل آلانین مصرف نکند، عوارض و علائم بیماری در او بروز نمی یابد. فنیل آلانین نوعی آمینواسید است که در برخی غذاها وجود دارد. همچنین می توان به کم خونی داسی شکل نیز اشاره کرد که فرد \\(Hb^AHb^S\\)فقط در \\(O_2\\)پایین، گویچه های قرمز داسی شکل دارد. بررسی سایر گزینه ها: 2) رابطه بین الل های \\(A\\)و \\(B\\)گروه خونی \\(ABO\\)، از نوع هم توانی است نه بارزیت ناقص. در هم توانی فنوتیپ مربوط به هر دو دگره همزمان با هم ظاهر می شود، نه حد واسط آنها! در گروه خونی \\(Rh\\)هم بین الل ها، رابطه بارز و نهفتگی وجود دارد و فرد ناخالص، فنوتیپ بارز را بروز می دهد. ۳) صفات چند جایگاهی، پیوسته هستند و فراوانی رخ نمودهای آنها در نموداری شبیه زنگوله نمایش داده می شود، برای صفات تک جایگاهی صادق نمی باشد. 4) صفات گسسته، تک جایگاهی هستند. البته دقت کنید که همۀ صفات گسسته، تنها دارای دو شکل مختلف نیستند؛ مثلا در گروه خونی \\(ABO\\)می توان چهار شکل مختلف را در جمعیت مشاهده کرد، اما در این حالت هم، همه انواع دگره ها، در یک جایگاه ژنی مشخص قرار دارند نه چند جایگاه! در واقع این صفت تک جایگاهی می باشد.', '2026-02-05 17:20:29'),
(808, 825, 'گزینه&laquo;2&raquo; با توجه به ژنوتیپ ABB برای آندوسپرم، گامت نر دارای الل A و گامت ماده دارای الل B باید باشد. بر این اساس، ژنوتیپ بخش پذیرندۀ دانۀ گرده (کلاله) باید حداقل یک الل B داشته باشد (ژنوتیپ آن می تواند BB یا AB باشد) و ژنوتیپ گردۀ نارس (هاپلوئید) حتما باید دارای الل A باشد. دقت کنید در صورت سؤال گفته شده که هر دوتا باید غیر محتمل باشند، پس ۳ جواب نمی باشد؛ چراکه AB برای کلاله امکان پذیر است.', '2026-02-05 17:20:29'),
(809, 826, 'گزینه&laquo;4&raquo; ژنوتیپ پدر rrو ژنوتیپ مادر Rr است که خب با هم متفاوت هستند. بررسی سایر گزینه ها: 1) دختران و پسران ناخالص در این خانواده، ژن نمود مشابه دارند؛ ولی رخ نمودهای آنها متفاوت است. (بی مو در مقابل با مو!) 2) پسر Rr که فرزند ناخالص این خانواده بوده، روی لاله گوش خود مو دارد و فنوتیپ متفاوتی نسبت به پدر خود دارد. 3) دختری که روی لاله گوش خود مو دارد، ژنوتیپ RR دارد. امکان تولد این فرزند از پدری که ژنوتیت rr دارد، دور از انتظار خواهد بود.', '2026-02-05 17:20:29'),
(810, 827, 'گزینه&laquo;4&raquo; همه موارد به درستی بیان شده اند. با توجه به توضیحات ذکر شده در صورت سؤال، فاویسم نوعی بیماری وابسته به X نهفته است؛ چراکه مردان فقط یک X دارند و نمی تواند ناقل باشند. دگره هموفیلی نیز روی فام تن X قرار دارد و نهفته است. در این بیماری، فرایند لخته شدن خون دچار اختلال می شود. از آنجا که از پدر و مادری سالم پسری هموفیل متولد شده، در می یابیم که ژنوتیپ پدر و مادر برای این صفت، به ترتیب \\(X^HY\\)و \\(X^HX^h\\) است. از طرفی، فرزند بعدی پسری است که از نظر هموفیلی سالم است (پس دگره \\(X^H\\) را از مادر دریافت کرده)، اما مبتلا به فاویسم است؛ پس ژنوتیپ این فرد می باشد. ژنوتیپ این پسر نشان دهندۀ این است که الل های H مربوط به هموفیلی و f مربوط به فاویسم، بر روی یک کروموزوم مادر قرار دارند و با هم به ارث می رسند؛ بنابراین ژنوتیپ مادر و پدر از نظر این دو صفت به ترتیب \\(X_f^HX_f^H\\) و \\(X_f^HY\\) است. در میوز ۱، هنگام جفت شدن فام تن های همتا و ایجاد چهارتایه، ممکن است قطعه ای از فام تن بین فامینک های غیر خواهری مبادله شود. این پدیده را چلیپایی شدن (کراسینگ اور) می گویند. اگر قطعات مبادله شده حاوی دگره های متفاوتی باشند، ترکیب جدیدی از دگره ها در این دو فامینک به وجود می آید که به آنها فامینک های نوترکیب می گویند، دقت کنید که در این شرایط، دو فامینک دیگر با همان ترکیب اللی باقی خواهند ماند (در واقع در هیچ شرایطی، همه فامینک ها نوترکیب نخواهند بود و همواره هم فامینک های والدی داریم و هم نوترکیب). فرایند کراسینگ اور در کروموزوم های جنسی زنان قابل وقوع است (زیرا کروموزوم های جنسی مردان همتا نیست) و با توجه به اینکه هر دو بیماری مورد نظر وابسته به جنس هستند؛ پس اصلا وقوع کراسینگ اور در مرد را برای حل این سؤال مد نظر قرار نمی دهیم. با انجام کراسینگ اور طی میوزهای مختلف در مادر گامت هایی با ژن نمود \\(X_f^H\\) و \\( X_f^h\\) (هر دو والدی هستند)، \\(X_f^H\\) و \\( X_f^h\\) (هر دو نوترکیب) می توانند ایجاد شوند (دقت کنید در هر بار گامت زایی در زنان، فقط یک گامت تولید می شود که می تواند یکی از این ژن نمودها را داشته باشد) به دنبال لقاح بین این گامت ها و گامت پدر که دارای X است )با ژن نمود (XfH، فرزند دختر می تواند \\(X_f^h ، X_F^H X_F^H ، X_F^h X_F^H \\) و یا \\(X_F^H X_F^h\\) باشد (تأیید مورد &laquo;الف&raquo; و &laquo;د&raquo;). همچنین با وقوع کراسینگ اور، امکان تولد پسری با ژنوتیپ \\(X_F^H Y \\) و یا ژنوتیپ \\(X_f^h Y \\) وجود دارد (تأیید مورد &laquo;ب&raquo; و &laquo;ج&raquo;). در ارتباط با مورد &laquo;ب&raquo; توجه کنید که هموفیلی انواع مختلفی دارد و فقط افرادی که به شایع ترین نوع آن مبتلا هستند، فاقد عامل انعقادی شمارۀ هشت هستند؛ پس فرد ممکن است علی رغم داشتن این فاکتور، همچنان در انعقاد خون ناتوان باشد و به نوع دیگری از هموفیلی مبتلا باشد.', '2026-02-05 17:20:29'),
(811, 828, 'گزینه&laquo;2&raquo; مطابق توضیحات صورت سؤال، ذرت های مد نظر، دارای چهار یا پنج دگره بارز در خصوص این صفت خواهند بود. هر دو گروه ذرت های مورد نظر فراوانی بیشتری از ذرت های کاملا سفید یا کاملا قرمز دارند بررسی سایر گزینه ها: 1) گفتیم که این ذرت ها دارای چهار یا پنج دگر بارز هستند. مطابق نمودار دیده می شود، در صورتی که چهار دگره بارز داشته باشند، شش نوع ژنوتیپ و در صورتی که پنج دگره بارز داشته باشند سه نوع ژنوتیپ خواهند داشت. 3) ذرتی که دارای چهار دگره بارز است، می تواند ژنوتیپی به صورت AaBbCC داشته باشد که در این صورت، دو جایگاه ژنی با ژنوتیپ ناخالص خواهد داشت. 4) ذرتی که ژنوتیپ AABBCC دارد، تنها در یک جایگاه ژنی خودالل های متفاوتی را جای داده است؛ پس این مورد نیز قابل انتظار می باشد.', '2026-02-05 17:20:29'),
(812, 829, 'گزینه&laquo;1&raquo; اگر پدر خانواده دارای کربوهیدرات A گروه خونی باشد؛ بنابراین دختر می تواند هر دو نوع کربوهیدرات گروه خونی را در سطح گویچه های قرمز خود داشته باشد (Aاز پدر و B از مادر)، همچنین پدر برای گروه خونی Rh ژن نمودی به صورت dd دارد. اگر ژن نمود مادر به صورت Dd یا DD باشد، آنگاه دختر می تواند ژن نمود Dd داشته و برای گروه خونی Rh ناخالص باشد. همچنین پدر برای بیماری هموفیلی دگره نهفته داشته و بیمار است و مادر نیز ناقل است، یعنی دارای دگرۀ نهفته برای بیماری هموفیلی است؛ بنابراین دختر می تواند مبتلا به هموفیلی باشد که در این شرایط در تولید رشته های پروتئینی فیبرین دچار مشکل است. بررسی سایر گزینه ها: 2) محدودیت مصرف فنیل آلانین، یعنی مبتلا به بیماری فنیل کتونوری (ff) که امکان تولد آن وجود دارد \\( Rh^+\\) هم می تواند باشد. به بخش آخر این گزینه توجه داشته باشید، ممکن است پسر این خانواده دارای ژن نمود OO برای گروه خونی ABO باشد \\( (AO&times;BO) \\) در این حالت فاقد کربوهیدرات های این گروه خونی در سطح گویچه های قرمز خود است، اما به هر حال کربوهیدرات های دیگری در سطح غشای گویچه های قرمز آن یافت می شود! در سطح خارجی غشای یاخته های یوکاریوتی، کربوهیدرات دیده می شود. 3) دختری با ژن نمود \\(X^HX^h\\) توانایی تشکیل لخته را دارد. لخته در هنگام خونریزی های شدید تشکیل می شود، در حالی که در خونریزی های جزئی که دیواره رگ آسیب محدودی می بیند، گرده ها دور یکدیگر جمع شده و با ایجاد درپوش پلاکتی (بدون تشکیل لخته) از خونریزی جلوگیری می کنند. 4) اگر فرد مبتلا به فنیل کتونوری، فنیل آلانین مصرف کند ممکن است یاخته های مغزی او آسیب ببینند که در این شرایط با اختلال در تصمیم گیری و قضاوت مواجه خواهد بود! با توجه به این که پدر خانواده برای گروه خونی Rh دارای ژن نمود dd است؛ بنابراین پسر خانواده هرگز نمی تواند برای هر دو نوع گروه خونی ژن نمود خالص بارز داشته باشد.', '2026-02-05 17:20:29'),
(813, 830, 'گزینه&laquo;1&raquo; در صورتی که ژن نمود آندوسپرم ABB باشد، گیاه (بخش) ماده الل B و گیاه (بخش) نر الل A را دارد؛ در نتیجه ژن نمود گیاه ماده (پوسته دانه) می تواند BB و گیاه نر AA باشد. از طرفی ژن نمود پوسته دانه و یاخته های گیاه مادر (مثل یاخته بافت خورش) یکسان است؛ پس اگر پوسته دانه BB باشد، ژن نمود یاخته بافت خورش هم باید BB باشد. بررسی سایر گزینه ها: 2) در صورتی که ژن نمود آندوسپرم ABB باشد، گیاه نر نمی تواند ژن نمود BB داشته باشد؛ چراکه طبق آندوسپرم B مربوط به گامت ماده و A مربوط به اسپرم است و گیاه نر حتما باید A را داشته باشد. 3) ژن نمود یاخته های پوسته دانه و یاخته خورش، یکسان باید باشد، چون همگی مربوط به یک گیاه هستند. 4) در صورتی که ژن نمود آندوسپرم AABباشد، گیاه ماده نمی تواند BB باشد (باید حتما یک A داشته باشد) همچنین گیاه نر نمی تواند ژن نمود AA داشته باشد. باید حتما B را داشته باشد.', '2026-02-05 17:20:29'),
(814, 831, 'گزینه&laquo;2&raquo; موارد &laquo;الف&raquo; و &laquo;ب&raquo; به نادرستی بیان شده اند. بررسی همه موارد: الف) هر تخمک فقط یک عدد گامت (تخم زا) ایجاد می کند ب) یاخته های مولد گرده های نارس در همۀ پرچم ها، دیپلوئید بوده و از تقسیم میتوز یاخته های این بخش، ایجاد شده اند، پس همگی ژنوتیپ AaBb و فنوتیپ یکسانی دارند. ج) در لوله گرده علاوه بر هسته یاخته رویشی، دو اسپرم نیز از تقسیم میتوز یاخته زایشی به وجود می آیند که همگی دارای ژنوتیپ مشابهی با یکدیگر هستند، چراکه یاخته های رویشی و زایشی از تقسیم میتوز یک گرده نارس ایجاد شده اند و چون این گرده هاپلوئید است، همگی ژن نمود و رخ نمود مشابهی دارند. د) درون تخمک از تقسیم میوز بزرگ ترین یاخته بافت خورش، چهار یاخته ها پلوئید ایجاد می شود که یکی از آنها باقی می ماند و بقیه مراحل را طی می کند. این یاخته ها می توانند ژنوتیپ های مختلفی داشته باشند. بسته به این که ژنوتیپ گیاه مادر چه باشد. مثلا در اینجا که گیاه ما، ژنوتیپ AaBb دارد، یاخته های حاصل از تقسیم میوز یاخته خورش می توانند ژن نمودهای aB, Ab, AB و ab داشته باشند. دقت کنید فقط یکی از این یاخته ها باقی می ماند و با میتوز خود، کیسه رویانی را ایجاد می.کند یاخته های هاپلوئید کیسه رویانی، همگی ژن نمود مشابه دارند.', '2026-02-05 17:20:29'),
(815, 832, 'گزینه&laquo;4&raquo; ذرت های دو آستانه، دارای ژنوتیپ های aabbcc و AABBCC هستند که ذرت های حاصل از لقاح آنها همگی ژنوتیپ AaBbCo دارند و در میانه این نمودار (فنوتیپ حد واسط) قرار می گیرند. طبق شکل کتاب درسی مشخص است که بیشترین تنوع ژنوتیپ ها مربوط به فنوتیپ ذرت هایی با سه الل بارز می باشد. منظور از صورت سؤال نیز ویژگی مشترک همه ذرت های این ستون که دارای ژنوتیپ های دیگری به جز خود ژنوتیپ AaBbCc هستند، می باشد. به جز ژنوتیپ AaBbC، در سایر ژنوتیپ ها یک جایگاه، فقط الل نهفته دارد، یک جایگاه ژنوتیپ ناخالص دارد و دو جایگاه ژنوتیپ خالص (بارز یا نهفته) دارند. یکی از جایگاه هایی که ژنوتیپ خالص دارد، فقط الل بارز دارد و جایگاه دیگری که دارای ژنوتیپ خالص است، فقط دارای الل نهفته می باشد. با توجه به توضیحات فوق، مثلاً ممکن است دگره نهفته یا بارز یکی از جایگاه ها در این ذرت ها دیده نشود، مثلن ذرتAABbcc، الل a را ندارد.', '2026-02-05 17:20:29'),
(816, 833, 'گزینه&laquo;4&raquo; فقط مورد الف به طور قطعی درست است. بررسی همه موارد: الف) درست؛ پسرها، کروموزوم X خود را از مادر می گیرند و به دلیل سالم بودن پسر (\\(X^HY\\))، مشخص می شود که مادرش حداقل باید یک دگره سالم برای صفت هموفیلی را داشته باشد. ب) نادرست؛ با توجه به این که گروه خونی این فرد، A است؛ بنابراین ژنوتیپ آن به صورت AA یا AO است که در صورت داشتن ژنوتیپ AO برای این صفت گروه خونی نمی توان گفت بر روی هر دو کروموزوم (کروموزوم های) شماره ۹، دگره های مربوط به تولید آنزیم متصل کننده کربوهیدرات گروه خونی قرار دارد. ج) نادرست؛ همان طور که توضیح داده شد، مادر این پسر حداقل یک دگره \\(X^H\\) دارد، بنابراین از نظر ابتلا به شایعترین نوع هموفیلی، سالم است؛ اما به هر دلیل دیگری ممکن است در انعقاد خون دچار مشکل باشد! مثلاً کمبود یون کلسیم یا ویتامین K داشته باشد و نهایتا نتواند پروتئین فیبرینوژن را به فیبرین تبدیل کند. د) نادرست؛ بزرگ ترین کروموزوم های موجود در تصویر کاریوتیپ این پسربچه، کروموزوم های شماره یک هستند. از آنجا که این فرد، گروه خونی منفی دارد، بنابراین ژنوتیپ آن برای گروه خونی Rh به صورت dd بوده و واجد دو دگره یکسان می باشد. حالا دلیل نادرستی این مورد چیه؟ نکته بسیار مهمی که در این گزینه وجود دارد، آن است که حین تهیه تصویر کاریوتیپ، کروموزوم ها دو کروماتیدی هستند؛ پس در این صورت فرد با ژنوتیپ dd، چهار نسخه مشابه از الل های مربوط به این صفت را خواهد داشت؛ نه دوتا!', '2026-02-05 17:20:29'),
(817, 834, 'گزینه&laquo;3&raquo; برای حل این تست باید روی شکل زیر تسلط داشت: با توجه به لقاح دو ژن نمود (ژنوتیپ) AABBcc و aabbCC، زاده های حاصل همگی ژنوتیپ AaBbCc خواهند داشت. با توجه به شکل، این ژنوتیپ دارای ۳ الل بارز و ۳ الل نهفته است و در مرکز یا میانه نمودار زنگوله ای قرار دارد. ژنوتیپ هایی که طبق خواسته سؤال، فاصله یکسانی از این ژنوتیپ دارند به این شکل است: ۲-۱،۴- ۵، 6-0 حالا ۲-۴ به چه معنی است؟ - اگر در ژنوتیپ ذرتی ۴ الل بارز باشد و ژنوتیپ ذرت دیگری ۲ الل بارز داشته باشد، از نظر فاصله، با ذرت دارای الل بارز مثل هم هستند (امیدوارم برای 5-1 و ۶ - ۰ هم این موضوع رو متوجه باشید). ذرتی که دو جایگاه ژنی خالص بارز و یک جایگاه ژنی نهفته دارد، ذرتی با ۴ الل بارز است. ذرتی که یک جایگاه ژنی خالص بارز و دو جایگاه ژنی نهفته دارد، ذرتی با ۲ الل بارز می باشد. طبق توضیحات بالا، 2-4 داریم! پس این درسته! بررسی سایر گزینه ها: 1) ذرتی که یک جایگاه ژنی ناخالص و دو جایگاه ژنی خالص بارز دارد، ذرتی با ۵ الل بارز است. ذرتی که دو جایگاه ژنی خالص نهفته و یک جایگاه ژنی خالص بارز دارد. ذرتی با ۲ الل بارز می باشد. طبق توضیحات بالا، 5&ne;2 نیست! 2) ذرتی که یک جایگاه ژنی خالص بارز و دو جایگاه ژنی ناخالص دارد، ذرتی با ۴ الل بارز است. ذرتی که فقط یک جایگاه ژنی ناخالص و فقط یک جایگاه ژنی نهفته دارد، ذرتی با ۳ الل بارز می باشد. طبق توضیحات بالا، 4&ne;3 نیست! 4) ذرتی که سه جایگاه ژنی خالص بارز دارد، ذرتی با ۶ الل بارز است. ذرتی که فقط یک جایگاه ژنی ناخالص و دو جایگاه ژنی نهفته دارد، ذرتی با یک الل بارز می باشد. طبق توضیحات بالا، 6&ne;1 نیست!', '2026-02-05 17:20:29'),
(818, 835, 'گزینه&laquo;4&raquo; دقت کنید، در بیماری های وابسته به X، مردان نمی توانند ژنوتیپ ناقل و ناخالص داشته باشند. بنابراین مردی که تنها ناقل یک بیماری است، یعنی از نظر هموفیلی سالم و از نظر بیماری کم خونی داسی شکل ناخالص (\\(Hb^AHb^s\\)) است. در صورت ازدواج زنی سالم و ناقل بیماری هموفیلی با مردی سالم: در بین فرزندان، پسر هموفیل دیده می شود، پس احتمال تولد پسر مبتلا به هموفیلی وجود دارد. در بیماری کم خونی داسی شکل، در صورت ازدواج زنی ناقل و سالم با مردی ناقل و سالم. در بین فرزندان، فرزند (پسر یا دختر) بیمار دیده می شود، پس احتمال تولد پسر مبتلا به کم خونی داسی شکل وجود دارد. در گروه خونی ABO: در صورت ازدواج زنی دارای گروه خونی A (با ژنوتیپAO) با مردی دارای گروه خونی B (با ژنوتیپ BO): در بین فرزندان، همه انواع گروه های خونی دیده می شود، پس احتمال تولد پسری با گروه خونی O وجود دارد. بررسی سایر گزینه ها: 1) برای آن که پسری مبتلا به کم خونی داسی شکل متولد شود، باید الل بیماری را از هر دو والد خود دریافت کند. در این گزینه پدر، چون در معرض خطر ابتلا به مالاریا قرار دارد، ژن نمود خالص و بارز دارد HbAHbA و فاقد الل بیماری است، پس هرگز نمی تواند پسر مبتلا به کم خونی داسی شکل داشته باشد؛ همچنین با توجه به ژنوتیپ پدر که AB می باشد، امکان تولد فرزندی با ژنوتیپ OO وجود ندارد. 2) همان طور که گفتیم برای آن که فرزندی مبتلا به کم خونی داسی شکل متولد شود، باید الل بیماری \\((Hb^s) \\)را از پدر و مادر خود دریافت کند؛ بنابراین مادری که دارای ژنوتیپ خالص و فنوتیپ سالم است، ژنوتیپ \\(Hb^AHb^A\\) دارد و هرگز نمی تواند الل \\(Hb^s\\) را به فرزندان خود منتقل کند، پس فرزند مبتلا به کم خونی داسی شکل متولد نمی شود؛ همچنین مادر از نظر هموفیلی خالص و سالم است؛ در نتیجه امکان تولد پسر مبتلا به هموفیلی نیز وجود ندارد. 3) برای آن که فرزندی دارای گروه خونی O متولد شود، باید در ژنوتیپ هر یک از والدین حداقل یک الل Oدیده شود، چون مادر دارای گروه خونی AB است، پس هیچگاه فرزندی با گروه خونی O متولد نخواهد شد.', '2026-02-05 17:20:29'),
(820, 837, 'گزینه&laquo;4&raquo; برای حل این سؤال، باید به نکات استثنا دقت داشته باشیم به خصوص در بیماری وابسته به جنس نهفته مثل هموفیلی! در بیماری هموفیلی در صورتی که مادر بیمار باشد، امکان تولد پسر سالم از نظر آن وجود ندارد، بنابراین در 4 با فرض بیمار بودن مادر، امکان تولد پسر سالم وجود ندارد؛ پس این گزینه برای همۀ حالت های ممکن، محتمل نیست. بررسی سایر گزینه ها: 1) در صورتی که پدر یا مادر از نظر بیماری هموفیلی کاملا سالم باشند؛ یعنی به ترتیب ژنوتیپ \\(X^HY \\) و \\(X^HX^H\\) داشته باشند، همه فرزندان دختر به دلیل دریافت حداقل یک الل سالم از پدر یا مادر خود، فنوتیپ سالم خواهند داشت و تولد دختر بیمار غیر محتمل است. در مورد کم خونی داسی شکل هم، آمیزش بین دو ژنوتیپ \\(Hb^AHb^A\\) و \\(Hb^sHb^s \\) است که منجر به تولید فرزند \\(Hb^AHb^s\\) می شود. 2) اگر مادر بیمار (\\(Hb^sHb^s X^hX^h\\)) و پدر کاملا سالم \\((X^HY Hb^AHb^A ) \\) باشد، به دلیل این که الل سالم هموفیلی و کم خونی داسی شکل از پدر به دختر منتقل می شود، همۀ دختران فنوتیپ سالم خواهند داشت. 3) در صورتی که مادر ژنوتیپ کاملا سالم و خالص \\((X^HX^HHb^AHb^A ) \\) داشته باشد، فرزندان پسر همگی از نظر هموفیلی سالم هستند و از طرفی، با دریافت الل سالم مربوط به صفت کم خونی داسی شکل نیز، فنوتیپ سالم را بروز می دهند.', '2026-02-05 17:20:29'),
(821, 838, 'گزینه&laquo;3&raquo; مورد اول: نادرست؛ زنبور نازا در جمعیت زنبورهای عسل، زنبور مادۀ کارگر است. به دلیل وجود دگره L در گامت زنبور نر، امکان تولد هیچ زنبور ماده ای با شاخک کوتاه (SS) وجود نخواهد داشت و همۀ زاده های ماده شاخک هایی با طول متوسط دارند. مورد دوم: درست؛ زنبوری که نمی تواند میوز ۱ را انجام دهد، یا زنبور مادۀ کارگر است (که کلا نازا است و به دنبال آمیزش ملکه با زنبور نر متولد می شود) و یا زنبور نر (که فقط میتوز انجام می دهد و به دنبال بکرزایی ملکه ایجاد می شود). زنبور نر به دلیل هاپلوئیدی بودن و زنبور کارگر به دلیل نازا بودن توانایی تولید گامت به دنبال انجام میوز را ندارند. امکان تولد زنبور مادۀ کارگر با شاخک متوسط وجود دارد؛ زیرا زنبور ملکه، دگره S و زنبور نر دگره L را به نسل بعد انتقال می دهند. مورد سوم: نادرست؛ زنبور نر در جمعیت زنبورهای عسل، هاپلوئید است و از بکرزایی زنبور ملکه (نه آمیزش بین زنبورهای نر و ماده) به وجود می آید؛ در صورت بکرزایی هم طول شاخک زنبورهای نر، تنها می تواند کوتاه باشد، چراکه همۀ آنها فقط دگرۀ S را از ملکه به ارث می برند، پس همۀ زنبورهای نر، شاخک کوتاه هستند. مورد چهارم درست؛ طبق ژنوتیپ زنبور ملکه و زنبور نر مطرح شده ممکن است در اثر آمیزش و لقاح میان گامت های نر و ماده، زنبور کارگر و یا ملکه ای (زنبوری زیستا و زایا) با ویژگی مذکور پدید آید.', '2026-02-05 17:20:29'),
(822, 839, 'گزینه&laquo;3&raquo; لپه، حاصل رشد و نمو یاخته تخم است. به عبارتی، بخشی از رویان است، پس یکی از الل هایش مربوط به والد ماده (گامت ماده یا تخم زا) و الل دیگر آن، مربوط به گامت نر است. ژنوتیپ پوسته دانه هم نماینده ژنوتیپ یاخته های پیکری گیاه ماده است. ژنوتیپ یاخته سازنده گرده نارس، نماینده ژنوتیپ یاخته های پیکری گیاه نر است. در ژنوتیپ آندوسپرم دگره ای که تکرار می شود از گیاه ماده و دگره دیگر از گیاه نر می آید. در ۳ دگره تکرار شونده در آندوسپرم A است؛ پس والد ماده (یا در ژنوتیپ پوسته دانه) حتم باید A باشد، اما ژنوتیپ پوسته دانه BB است که این غیرممکن است. سایر گزینه ها هم با همین استدلال، امکان پذیر هستند.', '2026-02-05 17:20:29'),
(823, 840, 'گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;ج&raquo; محتمل هستند. الف) احتمال تولد دختری با ژنوتیپ \\(X^HX^HHb^AHb^A \\)که فقط ناقل هموفیلی است وجود دارد، اما طبق توضیحات، می فهمیم که احتمال تولد دختری با گروه خونی O (که ژنوتیپ OO دارد) وجود ندارد. ب) احتمال تولد پسری با ژنوتیپ \\(X^hYHb^sHb^s \\)وجود دارد که می تواند الل B هم داشته باشد. (گروه خونی AB یا (BO ج) پسری سالم با گروه خونی AB می تواند ژنوتیپ \\(X^HYHb^AHb^A \\) داشته باشد که احتمال تولد او وجود دارد. د) طبق توضیحات، فرزندان نمی توانند از نظر صفت گروه خونی، ژنوتیپ خالص داشته باشند.', '2026-02-05 17:20:29');
INSERT INTO `descriptive_answers_tam24` (`id`, `question_id`, `answer_text`, `created_at`) VALUES
(824, 841, 'گزینه&laquo;2&raquo; ذرتی که فقط دارای یک جایگاه ژنی ناخالص است می تواند یکی از این ژنوتیپ ها را داشته باشد: AaBBcc - Aabbcc -AaBBCC و AabbCC یعنی دارای ۱، 3 و یا ۵ الل بارز است. ذرت ستون 3 مثل AAbbcc و ذرت ستون ۵ مثل AABBcc که زاده حاصل از آمیزش آنها می تواند AABbcc باشد که ۳ الل بارز دارد، پس در یکی از ستون های مورد نظر ما قرار می گیرد. حالا ذرت AaBbcc از ستون ۳ و ذرت AaBBC از ستون ۵ را در نظر بگیرد، حاصل لقاح گامت ها ABC و AB می شود ذرت AABBcc که ۴ الل بارز دارد و در یکی از ستون های مورد نظر ما نیست؛ پس فقط بعضی ها، ویژگی مورد نظر ما را دارند. بررسی سایر گزینه ها: 1) ذرت های ستون 2، فقط یک الل بارز دارند مثل Aabbcc و ذرت های ستون ۶، ۵ الل بارز دارند مثل AABBCC. ذرت اول گامت های Abe و abc و ذرت دوم گامت های ABC و ABC را تولید می کند. زاده ها می توانند 4، ۳ و یا ۲ الل بارز داشته باشند. در ستون ۱، ذرتی داریم که خالص نهفته است و فاصله زاده ها از این ذرت ها، با هم یکسان نیست! مثالی که زدیم میشه مثال نقض که می گه گزینه غلط هست. 3) ذرت هایی که دو جایگاه ژنى خالص دارند (هر دو بارز، هر دو نهفته، یکی بارز و یکی نهفته)، دارای ۱، ۳ و یا ۵الل بارز هستند، اگر ذرت AaBbCe از ستون ۴ با ذرت aabbcc از ستون 1 ، آمیزش کند می تواند ذرتی با ژنوتیپ AaBbCc تولید کند که از ذرتی با ۳ الل بارز، روشن تر نیست!. 4) ذرتی که دو جایگاه ژنی ناخالص و یک جایگاه خالص نهفته دارد می تواند ژنوتیپ AaBbcc داشته باشد یعنی دارای ۲ الل بارز باشد. ذرتی که در ستون ۴ قرار دارد، ۳ الل بارز و ۳ الل نهفته دارد پس می تواند یاخته جنسی با حداکثر ۳ الل نفهته (abc) تولید کند اما ذرتی که در جایگاه ۷ قرار دارد هر گامتی که بسازد ۳ الل بارز دارد، پس حاصل آمیزش آنها نمی تواند ذرتی با ۲ الل بارز باشد.', '2026-02-05 17:20:29'),
(830, 847, 'گزینه&laquo;3&raquo; هر رفتار (از جمله رفتارهای یادگیری)، واکنش یا مجموعه ای از واکنش ها است که جانور در پاسخ به محرک درونی یا بیرونی از خود بروز می دهد. به عبارتی تا محرکی نباشد، پاسخی هم نیست و رفتاری هم بروز نمی یابد. بررسی سایر گزینه ها: 1) گروهی از رفتارهای غریزی تحت تأثیر تجربه می توانند اصلاح شوند یا تغییر کنند اما برخی رفتارهای غریزی مانند ترشح بزاق در مواجهه با غذا یا رفتار مراقبت مادری در موش مادر، تصحیح نمی شوند. این رفتارها، در هر بار بروز یافتن، به یک شکل انجام می شوند. 2) نه الزاما! مثلا رفتار مراقبت مادری در جمعیت موش ها، در افراد نر به شکلی که در مادران بروز می یابد، انجام نمی شود. در واقع بعضی از رفتارهای جانوری، فقط در برخی افراد (مثلا در جنسیت خاصی از جانوران) بروز پیدا می کنند. یا این که بعضی رفتارها، فقط در بازه زمانی خاص بروز می یابد، مثلا درخواست غذا از والدین در بچه های پرندگان دیده می شود ولی در پرنده های بالغ، چنین رفتاری نداریم. 4) جانورانی که حاصل بکرزایی اند یا والد آنها هرمافرودیتی است که به تنهایی تولیدمثل می کند (مانند کرم کبد)، ژن های خود را تنها از یک والد (نه والدین) دریافت کرده اند. در واقع ژن های به ارث رسیده از یک والد (نه والدین) در بروز رفتار مؤثر است.', '2026-02-05 17:20:29'),
(835, 852, 'گزینه&laquo;4&raquo; مطابق متن کتاب درسی، زنبورهای کارگر شهد و گرده گل ها را جمع آوری کرده و به کندو می آورند. وقتی زنبور کارگر منبع غذایی جدیدی پیدا می کند و به کندو باز می گردد، خیلی طول نمی کشد که تعداد زیادی زنبور کارگر در محل آن منبع غذایی دیده می شوند. زنبور یابنده پس از بازگشت، اطلاعات خود درباره منبع غذایی را به زنبورهای دیگر ارائه می کند. این زنبور با انجام حرکات ویژه ای، اطلاعات خود را به زنبورهای دیگر نشان می دهد. زنبورهای کارگر با مشاهده این حرکات، فاصله تقریبی کندو تا محل منبع غذا و جهتی را که باید پرواز کنند، در می یابند. زنبورهای کارگر با استفاده از اطلاعات کلی که از زنبور یابنده درباره منبع غذایی دریافت کرده اند، به سمت آن پرواز و به کمک بویایی خود (نه فرومون های ترشح شده)، محل دقیق غذا را پیدا می کنند. پس دقت کنید که طبق توضیحات کتاب زیست شناسی (۲)، در زنبورهای عسل، فرومون ها برای هشدار خطر حضور شکارچی کاربرد دارد و نقشی در فراخوانی زنبورهای کارگر به محل منبع غذایی و پیدا کردن منبع دقیق غذا، ندارد. بررسی سایر گزینه ها: 1) دقت کنید تنها برخی پرندگان در ناحیه سر خود دارای ذرات مغناطیسی هستند. این ذرات مغناطیسی در مهاجرت پرنده نقش مهمی دارند. 2) جانوران در برابر افراد همگونه یا افراد گونه های دیگر از قلمرو خود دفاع می کنند. رفتار قلمرو خواهی به شکل های مختلفی می تواند بروز پیدا کند. مثلا جانور با رفتارهایی مانند اجرای نمایش و یا تهاجم به جانوران دیگر اعلام می کند که قلمرو متعلق به آن است یا مثلا یک پرنده با آواز خواندن سعی می کند از ورود پرنده مزاحم به قلمرو خود جلوگیری کند. اگر آواز مؤثر نباشد، ممکن است پرنده صاحب قلمرو برای بیرون راندن مزاحم به آن حمله کند. علاوه بر این روش ها، از فصل ۴ یازدهم نیز به یاد داریم که برخی از جانوران مثل گربه ها از فرومون ها برای تعیین قلمرو خود استفاده می کنند. 3) به طور معمول در برخی جانوران ممکن است خواب زمستانی و یا رکود تابستانی دیده شود که در این دوره ها، کاهش فعالیت سوخت و سازی جانور مشاهده می شود، ولی توجه داشته باشید که قبل از خواب زمستانی، افزایش تولید چربی ها را شاهد هستیم. در این جانوران، قبل از خواب زمستانی، مقدار زیادی غذا مصرف می شود و مقدار زیادی ذخیره لیپیدی ایجاد می شود تا جانور طی دورۀ خواب به میزان کافی اندوخته غذایی برای مصرف داشته باشد.', '2026-02-05 17:20:29'),
(836, 853, 'گزینه&laquo;4&raquo; خفاش های خون آشام رفتار دگرخواهی دارند. در پی این رفتار، غذا در اختیار جانور دیگری قرار می گیرد، پس در لوله گوارش جانور دریافت کننده غذا، برای تجزیه مواد غذایی لازم است آنزیم های گوارشی ترشح شود. در رفتار شرطی شدن فعال نیز، رفتار می تواند با دریافت غذا همراه باشد (مثل موش اسکینر یا جوجه کاکایی)؛ پس می تواند منجر به ترشح آنزیم های گوارشی در لوله گوارش شود. بررسی سایر گزینه ها: 1) رفتار زنبورهای کارگر به نفع خود آنها هم هست، چراکه در بقای ژن های آنها به طور غیر مستقیم نقش دارد. زنبورهای کارگر با سایر زنبورها، دارای ژن های مشترکی هستند (همگی خویشاوند هستند) که رفتار دگرخواهی، به طور غیر مستقیم در بقای آنها مؤثر است. رفتار خفاش های خون آشام، به نفع خود آنها هم هست چراکه در زمانی که خودشان گرسنه هستند هم می توانند غذا به دست بیاورند. 2) رفتار دگرخواهی مشاهده شده در بین خفاش های خون آشام، در زمانی که دگرخواهی در حال بروز است، به نوعی با کاهش احتمال بقای جانور همراه است زیرا جانور بخشی از غذای خود را در اختیار سایر افراد قرار می دهد (گرچه در آینده می تواند سبب افزایش شانس وی برای به دست آوردن غذا شود اما در لحظه بروز دگرخواهی، شانس بقای وی را کاهش می دهد). همچنین در رفتار مورچه های برگ بر کوچک تر که در دفاع نقش دارند، کاهش احتمال بقای جانور امکان پذیر است (افزایش احتمال شکار شدن). 3) رفتار غذایابی طوطی ها ممکن است سبب به دست آوردن موادی شود که مواد سمی حاصل از غذاهای گیاهی را در لوله گوارش آن ها خنثی می کند؛ ولی این غذای مصرفی محتوای انرژی چندانی ندارد.', '2026-02-05 17:20:29'),
(837, 854, 'گزینه&laquo;4&raquo; مستقر کردن مترسک عادی در مزرعه، ابتدا باعث ترساندن کلاغ ها می شود و سبب می شود از مزرعه دوری کنند، ولی بعد از مدتی این وضعیت، برای کلاغ ها عادی می شود و دوباره به مزرعه حمله می کنند. قوطی های فلزی متصل به مترسک، با وزش باد تکان می خورند صدا ایجاد می کنند و موجب ترس پرنده ها می شوند. به عبارتی مانع خوگیری پرنده ها به مترسک می شوند. از آنجایی که این محرک دائمی نیست استفاده از مترسکی با قوطی های فلزی اثر گذارتر از مترسک عادی است. جانوران در صورت احساس خطر رفتارهای غذایابی خود را تغییر می دهند تا با مصرف کم ترین انرژی و مواجه شدن با کمترین خطر، حداکثر استفاده را از غذایابی خود داشته باشند. بررسی سایر گزینه ها: 1) شقایق دریایی سیستم عصبی مرکزی و محیطی ندارد، اما با این وجود می تواند خوگیری را بروز دهد. 2) لاک پشت مطرح شده در کتاب درسی، رکود تابستانی انجام می دهد که طی آن، فعالیت های خود را کاهش می دهد. این رفتار کاملا غریزی (رفتار ژنی) است، چراکه حتی در صورت وجود آب و غذای کافی هم این رفتار را بروز می دهد. رکود تابستانی در جانورانی رخ می دهد که در مناطق خیلی گرم که غذای کافی هم ندارند زندگی می کنند. در این حالت این جانوران فعالیت های خود را کاهش می دهند، اما چون لاک پشت در شرایط محیطی خوب! هم همچنان رکود را نشان می دهد، می توان نتیجه گرفت این رفتار، کاملا غریزی است. 3) تهوع پرنده در پی بلعیدن پروانه مونارک، سبب بروز رفتار شرطی شدن فعال می شود، چراکه جانور غذایی خورده است که بعد از آن تنبیه شده است و کم کم یاد می گیرد که دیگر این نوع پروانه ها را نخورد. در این رفتار جانور بین محرک (پروانه مونارک یا غذا) و نتیجه رفتار خود (تنبیه)دریافت شده) ارتباط برقرار می کند.', '2026-02-05 17:20:29'),
(838, 855, 'گزینه&laquo;2&raquo; زنبور یابنده پس از بازگشت از محل منبع غذایی جدیدی که پیدا کرده است، اطلاعات خود را درباره منبع غذایی، به زنبورهای دیگر ارائه می کند. این زنبور با انجام حرکات ویژهای اطلاعات خود را به زنبورهای دیگر منتقل می کند. زنبورهای کارگر، با مشاهده این حرکات، فاصله تقریبی کندو تا محل منبع غذا و جهتی را که باید پرواز کنند، در می یابند؛ برای مثال هر چه این حرکات طولانی تر باشد، منبع غذایی دورتر است (درستی2) . افزون بر آن هنگام انجام حرکات، زنبور یابنده صدای وزوز متفاوتی نیز دارد. این رفتارها، اطلاعات کلی را در اختیار سایر زنبورها قرار می دهد. زنبورهای کارگر نیز با استفاده از این اطلاعات کلی که از زنبور یابنده درباره منبع غذایی دریافت کرده اند، به سمت آن پرواز و به کمک بویایی خود (نادرستی ۳ و ۱)، محل دقیق غذا را پیدا می کنند. وقتی زنبورهای کارگر قبل از جست وجو درباره محل منبع غذا اطلاعات داشته باشند، با صرف انرژی کمتر و در زمان کوتاه تری محل دقیق آن را پیدا می کنند. دقت کنید این موارد ارتباطی با ترشح انواع مختلف فرومون ها توسط زنبورها ندارد! (نادرستی4). چراکه زنبورها فرومون هایی ترشح می کنند که در هشدار خطر حضور شکارچی نقش دارد. این فرومون ها در جست وجوی غذا نقش ندارند.', '2026-02-05 17:20:29'),
(840, 857, 'گزینه&laquo;4&raquo; منظور سؤال رفتارهای کاملا غریزی است. طبق تعریف رفتار در جانوران، برای بروز هر رفتار، وجود محرک(ها) ضروری است. این محرک می تواند درونی یا بیرونی باشد. بررسی سایر گزینه ها: 1) مثلا رفتار وارسی نوزادان و رفتار مراقبت مادری در موش مادر، رفتارهایی کاملا غریزی هستند که در بازه زمانی خاص (پس از به دنیا آمدن بچه ها) بروز می یابند، نه در تمام طول زندگی فرد. 2) گاهی اوقات بیش از یک ژن برای بروز یک رفتار لازم است؛ مثلا در رفتار مراقبت مادری در موش مادر، پس از بیان ژن B، ژن های دیگری هم باید فعال شوند تا این رفتار بتواند بروز یابد. 3) بعضی رفتارها فقط در یکی از دو جنس نر یا ماده بروز می یابند، مثلا در انسان، رفتارهایی هستند که ژن مربوط به آنها بر روی کروموزوم Y قرار دارد این رفتارها در افراد ماده، اللی ندارند', '2026-02-05 17:20:29'),
(842, 859, 'گزینه&laquo;4&raquo; منظور از صورت سؤال، بسیاری از پستانداران و برخی از پرندگان است که نظام جفت گیری چندهمسری دارند. در این نظام، یکی از والدین وظیفه پرورش و نگه داری از زاده ها را انجام می دهند. اکسیژن رسانی در مهره داران، توسط گردش خون بسته و به کمک فعالیت گویچه های قرمز صورت می گیرد. در پستانداران و پرندگان، این یاخته ها از تقسیم یاخته های بنیادی و تمایز یاخته های حاصل از این تقسیم، در مغز استخوان تولید می شوند. بررسی سایر گزینه ها: 1) این مورد تنها درباره پستانداران جفت دار صادق است. در پستانداران، به سبب ارتباط خونی بین مادر و جنین، اندوخته غذایی تخمک کم است. در حالی که در پرندگان و خزندگان، اندوخته غذایی تخمک زیاد است. 2) در پستانداران جنین می تواند درون رحم یا رحم ابتدایی، رشد و نمو خود را آغاز نماید که پس از تولد از غدد شیری مادر تغذیه می کند. پرندگان نه رحم دارند و نه غدد شیری! 3) در پستانداران، انقباض ماهیچه های دیافراگم و بین دنده ای خارجی طی دم، سبب کاهش فشار درون شش ها و ورود هوا به درون شش ها می شود. در پرندگان دیافراگم وجود ندارد. این نکته در کنکور سراسری ۱۴۰۱ تیرماه مطرح شده است.', '2026-02-05 17:20:29'),
(843, 860, 'گزینه&laquo;4&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) شارش ژن یعنی افرادی از یک جمعیت به جمعیت دیگر بروند و با این کار، ژن های خود را به جمعیت مقصد وارد کنند، اما لاک پشت های دریایی ماده پس از طی مسافت های طولانی برای تخم گذاری به ساحل دریا می آیند و پس از تخم گذاری دوباره به دریا بازمی گردند، این کار شارش ژن محسوب نمی شود؛ زیرا جانور بین دو جمعیت مختلف جابه جا نمی شود. ب) مورچه های برگ بر از قارچ ها تغذیه می کنند. قارچ ها می توانند گلوکز را به شکل گلیکوژن ذخیره کنند. ج) رفتارشناسان در بررسی یک رفتار تلاش می کنند به دو نوع پرسش پاسخ دهند. نوع اول این که جانور چگونه رفتاری را انجام می دهد؟ برای پاسخ به این پرسش پژوهشگران فرایندهای ژنی، رشد و نمو و عملکرد بدن جانور را بررسی می کنند. پرسش نوع دوم این است که چرا جانور رفتاری را انجام می دهد؟ پاسخ به پرسش دوم به دیدگاه انتخاب طبیعی مربوط است. د) جانوران انواعی از رفتارهای غذایابی را بروز می دهند. در هر حالتی، این رفتار زمانی توسط انتخاب طبیعی برگزیده می شود که مواد مورد نیاز جانور را تأمین کند. مثلا طوطی ها از خاک رس تغذیه می کنند تا مواد سمی درون لوله گوارش آن ها را خنثی کند نه این که خاک رس انرژی داشته باشد، اما به هر حال برای جانور فایده دارد.', '2026-02-05 17:20:29'),
(844, 861, 'گزینه&laquo;1&raquo; منظور صورت سؤال، زنبور عسل (ملکه) و برخی مارها است. این جانوران می توانند با دو برابر کردن دنای هسته ای یا همان کروماتیدهای گامت های خود (در مارها با دو برابر شدن تعداد کروموزوم ها که هر کدام یک کروماتید هستند و در زنبور عسل، با دو برابر کردن تعداد کروماتیدها)، بکرزایی کنند. دقت کنید در زنبور عسل ملکه تعداد فام تن های گامت ثابت می ماند (فام تن ها فقط مضاعف و دو کروماتیدی می شوند) اما در مارها، تعداد فام تن های گامت ماده، طی بکرزایی دو برابر می شود اندام های حرکتی جلویی در مهره داران دارای آن اساس ساختاری یکسانی دارد، چراکه این ها همتا هستند؛ اما توجه کنید که زنبور بی مهره است و مارها نیز فاقد اندام حرکتی جلویی هستند. بررسی سایر گزینه ها: 2) اولا فقط برخی مارها گیرنده فروسرخ دارند و دوما این گیرنده ها داخل چشم آنها قرار ندارند؛ بلکه در سوراخ هایی در زیر چشم جانور می باشند. زنبورهای عسل می توانند پرتو فرابنفش را با کمک گیرنده های درون چشم خود ببینند. 3) آواز خواندن و تهاجم قوهای سرخرود با هدف قلمرو خواهی انجام می شود. تعیین قلمرو به کمک فرومون، بر اساس مطالب کتاب درسی توسط گربه ها انجام می شود. مارها از فرومون برای جفت یابی و زنبورهای عسل برای هشدار خطر حضور شکارچی، استفاده کنند. 4) این مورد برای حشرات صادق نیست زیرا درون قلب حشرات، خون وجود ندارد؛ حشرات، همولنف دارند.', '2026-02-05 17:20:29'),
(845, 862, 'گزینه&laquo;2&raquo; فقط مورد &laquo;د&raquo; نادرست است. بررسی همه موارد: الف) دقت کنید همه رفتارهای جانوری (چه کاملا غریزی و چه حاصل از یادگیری) دارای اساس ژنی لازم برای بروز رفتار می باشند؛ می دانیم برای بروز رفتار، باید این ژن ها بیان شوند و بیان ژن ها هم در یوکاریوت ها، وابسته به وجود عوامل رونویسی پروتئینی و آنزیم رنابسپار از می باشد. ب) این رفتار نوعی غذایابی است و باعث می شود که جانور از غذاهایی که انرژی و نیازهای او را برطرف نمی کند دوری کند و برود سراغ غذای حاوی انرژی بیشتر؛ به عبارتی جانور انرژی کم تری برای به دست آوردن غذا مصرف می کند. غذایابی بهینه هم یعنی بین هزینه های به دست آوردن غذا و محتوای انرژی آن، موازنه و تعادل وجود داشته باشد. ج) همه رفتارها تحت اثر انتخاب طبیعی هستند؛ انتخاب طبیعی، با حذف افراد ناسازگار با محیط، فراوانی نسبی برخی فنوتیپ ها را کاهش می دهد. د) برنامه ریزی آگاهانه جهت بروز رفتار جدید مربوط به رفتار حل مسئله است.', '2026-02-05 17:20:29'),
(846, 863, 'گزینه&laquo;4&raquo; در یوکاریوت ها و پروکاریوت ها، در هر دوراهی همانندسازی، یک آنزیم هلیکاز وجود دارد که با اثر بر دنای اولیه موجب شکسته شدن پیوندهای هیدروژنی ساختار آن می شود. بررسی سایر گزینه ها: 1) یکی از راه های تنظیم بیان ژن در یوکاریوت ها، تغییر در فشردگی فام تن هاست اما یاخته های پروکاریوتی فاقد پروتئین های هیستون و در نتیجه نوکلئوزوم می باشند. 2) در یوکاریوت ها، فقط ساخت مولکول های NADH می تواند در ماده زمینه ای سیتوپلاسم انجام شود و FADH2 در میتوکندری تولید می شود. در پروکاریوت ها، هر دو نوع ناقل الکترون در ماده زمینه ای سیتوپلاسم تولید می شوند، چراکه اصلا راکیزه ندارند؛ پس استفاده از جمله &laquo;انواعی از مولکول های حامل الکترون!&raquo; در خصوص یاخته های یوکاریوتی نادرست است. 3) در پروکاریوت ها برخلاف یوکاریوت ها، توالی افزاینده وجود ندارد. عوامل رونویسی متصل به این توالی با ایجاد خمیدگی در مولکول DNA، عوامل رونویسی متصل به توالی راه انداز را در مجاورت عوامل رونویسی متصل به توالی افزاینده قرار می دهند و از این طریق سرعت رونویسی افزایش می یابد.', '2026-02-05 17:20:29'),
(847, 864, 'گزینه&laquo;3&raquo; در صورتی که ژنوتیپ والد ماده را BBBb فرض کنیم، گامت های قابل انتظار برای ماده به صورت BB یا Bb هستند و ژنوتیپ یاخته های دوهسته ای به صورت BBBB یا BBbb می باشد. با توجه به ژنوتیپ تخم اصلی (BBb)، ژنوتیپ اسپرم های سازنده تخم اصلی به ترتیب b یا B خواهد بود؛ در نتیجه ژنوتیپ قابل انتظار برای آندوسپرم نیز به صورت BBBBb یا BBBbb خواهد بود. بررسی سایر گزینه ها: 1) اگر ژنوتیپ والد ماده به صورت Bb باشد؛ در نتیجه ژنوتیپ تخم زاهای قابل انتظار به صورت B یا b می باشد که به ترتیب ژنوتیپ اسپرم ها با توجه به ژنوتیپ تخم اصلی Bb یا BB خواهد بود. اگر ژنوتیپ تخم زا b باشد، ژنوتیپ دوهسته ای bb خواهد بود و با اسپرم BB می تواند تخم ضمیمه ای با ژنوتیپ BBbb ایجاد کند. 2) اگر ژنوتیپ والد ماده به صورت BBbb باشد، ژنوتیپ قابل انتظار برای گامت ماده (تخم زا) به صورت BB یا bb یا Bb است که با توجه به ژنوتیپ تخم اصلی، ژنوتیپ bb قابل قبول نیست. حال اگر ژنوتیپ تخم زا را به صورت Bb فرض کنیم، ژنوتیپ دوهسته ای به صورت BBbb است که با فرض تخم اصلی BBb، اسپرم به صورت B است و ژنوتیپ آندوسپرم به شکل BBBbb می تواند باشد. 4) اگر ژنوتیپ والد ماده به صورت BB باشد؛ در نتیجه ژنوتیپ تخم زا و یاخته دوهسته ای به ترتیب B و BB است. با توجه به ژنوتیپ تخم اصلی متوجه می شویم که ژنوتیپ استام به صورت Bb می باشد؛ در نتیجه ژنوتیب تخم ضمیمه و یاخته های آندوسپرم به صورت BBBb می باشد.', '2026-02-05 17:20:29'),
(864, 881, 'گزینه&laquo;4&raquo; تشکیل ساختار سوم پروتئین در اثر برهم کنش های آب گریز است؛ به این صورت که گروه های R آمینواسیدهایی که آب گریزند به یکدیگر نزدیک می شوند تا در معرض آب نباشند. سپس با تشکیل پیوندهایی مانند هیدروژنی اشتراکی و یونی ساختار سوم تثبیت می گردد. دقت داشته باشید که هم در ساختار اول و هم ساختار سوم پروتئین ها، پیوند اشتراکی تشکیل می شود. در ساختار سوم امکان تشکیل این پیوند بین گروه های R آمینواسیدها وجود دارد. بررسی سایر گزینه ها: 1) در ساختار دوم پروتئین ها، الگوهایی از پیوندهای هیدروژنی تشکیل می شود. در این ساختار، پیوندهای هیدروژنی بین گروه های CO و NH گروهی از آمینواسیدها تشکیل می گردند. ضمنن این سطح را همانند سطح اول میتوان در ساختار تمام پروتئین ها مشاهده نمود. 2) همزمان با تشکیل ساختار سوم پروتئین ها، فاصله گروه های آمینواسیدهای آب گریز کاهش می یابد (این گروه ها به یکدیگر نزدیک می شوند.) دقت داشته باشید که ساختار نهایی مولکول میوزین، ساختار چهارم است؛ چراکه این پروتئین دارای دو زنجیره است و آرایش این زنجیره ها در کنار هم، سبب تشکیل ساختار چهارم می شود. 3) تا خوردگی اولیه زنجیره پلی پپتیدی در ساختار دوم و با تشکیل پیوندهای هیدروژنی رخ می دهد. تاخوردگی بیشتر پلی پپتید در ساختار سوم و بر اثر برهم کنش های آب گریز می باشد. پیوندهای هیدروژنی تشکیل شده بین بخش های مختلف یک زنجیره پلی پپتیدی، منشأ تشکیل ساختار دوم در پروتئین ها هستند که به چند صورت (نه فقط دو صورت) دیده می شوند. دو نمونه معروف (نه تنها نمونه های) آن ها، ساختار مارپیچ و ساختار صفحه ای است.', '2026-02-05 17:20:29'),
(865, 882, 'گزینه&laquo;2&raquo; صورت سؤال در خصوص گزاره های &laquo;الف&raquo;، &laquo;ب&raquo; و &laquo;ج&raquo; صحیح است. بررسی همه موارد: الف) در یک دوراهی همانندسازی، فقط یک آنزیم هلیکاز حضور دارد. تعداد پیوندهای هیدروژنی بین نوکلئوتیدهای G دار و Cدار از Tدار U)دار) و A دار بیشتر است؛ پس این تعداد بیشتر از یکی است، چراکه حداقل یک پیوند هیدروژنی بین A و(U) T وجود دارد. ب) در اغلب پروکاریوت ها یک جایگاه آغاز همانندسازی دیده می شود. دو آنزیم دنابسپار از در هر ساختار Y شکل همانندسازی دیده می شود. ج) سه حلقه آلی در نوکلئوتیدهای گوانین دار دیده می شود، در حالی که مولکول های دنا که می توانند حلقوی باشند، دو رشته پلی نوکلئوتیدی دارند. دقت کنید نوکلئیک اسیدی که سه رشته باشد نداریم! د) چهار سطح ساختاری در پروتئین هموگلوبین دیده می شود. کربن مرکزی در ساختار همۀ انواع آمینواسیدها دارای چهار ظرفیت است.', '2026-02-05 17:20:29'),
(867, 884, 'گزینه&laquo;1&raquo; در یوکاریوت ها تنظیم بیان ژن می تواند پیش از رونویسی یا پس از آن انجام شود. اتصال بعضی رناهای کوچک مکمل به رنای پیک مثالی از تنظیم بیان ژن پس از رونویسی است. با اتصال این رناها به هم، از کار رناتن جلوگیری می شود. در نتیجه عمل ترجمه متوقف و رنای ساخته شده پس از مدتی تجزیه می شود. 2مربوط به تنظیم بیان ژن پیش از رونویسی و ۳ و ۴ مربوط به تنظیم بیان ژن در مرحله رونویسی هستند.', '2026-02-05 17:20:29'),
(868, 885, 'گزینه&laquo;4&raquo; طی پیرایش، رونوشت های اینترون از رنای نابالغ حذف می شوند و رونوشت های اگزون در کنار هم قرار می گیرند. در رنای نابالغ، رونوشت های اگزون با فاصله از هم قرار دارند، اما با حذف رونوشت های اینترون، رونوشت های اگزون، کنار هم قرار می گیرند، پس امکان تشکیل پیوند بین ریبونوکلئوتیدهای غیر مجاور هم وجود دارد. بررسی سایر گزینه ها: 1) پیرایش رنای پیک می تواند درون هسته رخ دهد؛ در واقع هر دو رنای پیک بالغ و نابالغ میتوانند درون هسته یافت شوند. در رنای پیک بالغ رونوشت میانه (اینترون) وجود ندارد. 2) در فرایند پیرایش رنای پیک، رونوشت میانه ها حذف می شود و رونوشت اگزون ها باقی می ماند و رنای پیک بالغ را می سازند. دقت کنید خود توالی های اگزون و اینترون در دنا هستند و حذف نمی شوند، بلکه پیرایش در مورد رونوشت آن ها رخ می دهد که در رنای پیک نابالغ هستند. ۳) طبق شکل ۴ کتاب درسی زیست دوازدهم، ممکن است بعضی از توالی های میانه طویل تر از توالی های بیانه (اگزون) باشند و لذا نوکلئوتیدهای بیشتری دارند؛ نوکلئوتیدها، ساختارهای سه بخشی (باز، قند و فسفات) هستند.', '2026-02-05 17:20:29'),
(869, 886, 'گزینه&laquo;1&raquo; منظور صورت سؤال، عوامل رونویسی در یاخته های یوکاریوتی است. اگر به شکل کتاب درسی نگاه کنید، عوامل رونویسی متصل به افزاینده می توانند هم زمان به توالی افزاینده و رنابسپار از متصل باشند. اما در خصوص عوامل رونویسی متصل به راه انداز، برخی از این عوامل هم زمان به راه انداز و رنابسپار از متصل اند و برخی دیگر فقط به راه انداز و دیگر عوامل رونویسی اتصال دارند. 2) عوامل رونویسی متصل به افزاینده در سرعت و در نتیجه مقدار رونویسی نقش دارند، به عبارتی با افزایش سرعت رونویسی مقدار رنای ساخته شده در واحد زمان بیشتر می شود. به عبارتی نتیجه نهایی می شود افزایش مقدار رنای ساخته شده! عوامل رونویسی متصل به راه انداز نیز می توانند میزان رونویسی از ژن را تغییر دهند. 3) گروهی از عوامل رونویسی، به بخش های خاصی از دنا به نام توالی افزاینده، متصل می شوند. با پیوستن این پروتئین ها به توالی افزاینده و با ایجاد خمیدگی در دنا، این عوامل رونویسی در کنار عوامل رونویسی متصل به راه انداز قرار می گیرند که این اتفاق، سبب نزدیک شدن راه انداز و توالی افزاینده به یکدیگر می شود. دقت کنید این دو توالی در تماس مستقیم با هم قرار نمی گیرند. افزاینده به طور معمول در فاصله دوری از راه انداز قرار دارد. 4) جهت رونویسی برخی ژنها عوامل رونویسی متصل به توالی افزاینده با ایجاد خمیدگی در دنا، در کنار عوامل رونویسی متصل به راه انداز قرار می گیرند. کنار هم قرارگیری این عوامل، سرعت رونویسی را افزایش می دهد.', '2026-02-05 17:20:29'),
(870, 887, 'گزینه&laquo;4&raquo; در همه جانداران تک یاخته ای و پریاخته ای فرایند تنظیم بیان ژن رونویسی و بیان ژن ها، را به طور دقیق بررسی و تنظیم می کند. بنابراین ژن های مختلف به طور غیر تصادفی رونویسی می شوند. یعنی زمانی این فرایندها رخ می دهد که یاخته به محصول ژن نیاز داشته باشد؛ پس همین طوری الکی نیست. بررسی سایر گزینه ها: 1) رنای ناقل، رنای پیک و رنای رناتنی در فرایند ترجمه (تبدیل زبان نوکلئیک اسیدی به پلی پپتیدی) شرکت می کنند، اما دقت کنید فقط رنای پیک (mRNA) رمزه (کدون) آغاز دارد. 2) هر رنای ،پیک پیامی خاص از ژن(ها) را همراه خود دارد که به منظور ترجمه آن به ترتیب بخش های کوچک و بزرگ ریبوزوم به رنای پیک متصل می شوند؛ اما نکته این گزینه واژه پیرایش است که فقط در یاخته های یوکاریوتی دیده می شود. 3) کدون ها (توالی های ۳ نوکلئوتیدی) در رنای پیک تعیین می کنند که کدام آمینواسیدها باید در ساختار پلی پپتید قرار بگیرد. اما دقت کنید که زمزه (کدون)های پایان شامل UAA، UGA و UAG هیچ آمینواسیدی را رمز نمی کنند.', '2026-02-05 17:20:29'),
(871, 888, 'گزینه&laquo;3&raquo; شکل، نشان دهنده رونویسی هم زمان دو ژن مجاور هم توسط چندین آنزیم رنابسپاراز و تشکیل ساختار پرمانند است و در بخشهای ۱، ۲ و ۳ مولکول های رنا در حال ساخته شدن هستند (طی مرحلۀ طویل شدن رونویسی) و بخش ۴ مولکول دنا است. از آن جا که رنای ۲ و ۳ هر دو از روی یک ژن مشترک در حال ساخته شدن هستند، لذا بین آن ها توالی راه انداز مشاهده نمی شود راه انداز این ژن عقبتر، در سمت چپ رنای ۲(بین دو ژن) قرار دارد. بررسی سایر گزینه ها: 1) طبق متن کتاب، رناها در این ساختار، در زمان های مختلفی از رونویسی هستند و لذا دارای طول های متفاوتی اند؛ اما با توجه اندازه مولکول های ۲ و ۳، می توان گفت هر دوی آن ها در مرحله طویل شدن رونویسی قرار دارند. 2) نوع رنا و لذا نوع رنابسپار از سازندۀ رنای ۲ و ۳ یکسان است، اما نوع این دو رنا و رنابسپار از سازنده آن ها لزوما با رنای ۱ و آنزیم سازنده آن، که در حال رونویسی از یک ژن دیگر است، لزوما یکسان نیست. مثلا ممکن است رنای ۲ و ۳ نوعی رنای پیک باشند و توسط رنابسپاراز ۲ ساخته شوند، اما رنای ۱ نوعی رنای رناتنی باشد و توسط رنابسپار از ۱ تولید شود. 4) فرایند بالغ شدن مربوط به برخی از رناهای پیک است که با حذف رونوشت های اینترون و اتصال رونوشت های اگزون به هم، این بالغ شدن رخ می دهد.', '2026-02-05 17:20:29'),
(872, 889, 'گزینه&laquo;1&raquo; فقط مورد &laquo;ب&raquo; صحیح است. بررسی همه موارد: الف) برخی پروتئین ها توسط ریبوزوم های آزاد در سیتوپلاسم ساخته می شوند. این پروتئین ها ممکن است به فضای درونی هسته، میتوکندری و کلروپلاست (ساختارهای دوغشایی) وارد شوند یا درون مادۀ زمین های سیتوپلاسم باقی بمانند و در آنجا فعالیت نمایند. ب) پروتئین هایی که توسط ریبوزوم های متصل به شبکه آندوپلاسمی زبر ساخته می شوند می توانند به خارج یاخته یا درون ساختار غشای یاخته بروند یا در اندامک هایی مثل واکوئول یا کافنده تن قرار بگیرند. دقت کنید درون یک واکوئول یا کافنده تن همواره فقط یک نوع پروتئین وجود ندارد، بلکه ممکن است انواع مختلفی پروتئین وجود داشته باشد که هر کدام از آن ها می توانند توسط یک رناتن ساخته شده باشند؛ همچنین برخی از این پروتئین ها چندرشته ای هستند و هر رشته می تواند توسط یک رناتن ساخته شود. ج) رشته های پلی پپتیدی که توسط ریبوزوم های متصل به غشای شبکه آندوپلاسمی زیر ساخته ها می شوند به درون ساختارهای کیسه ای شکل غشادار این اندامک وارد و دچار تاخوردگی هایی می گردند. از طرفی این پروتئین ها ممکن است درون کیسه های دستگاه گلژی هم، تغییراتی بکنند. این پروتئین ها ممکن است درون سیتوپلاسم (در اندامک لیزوزوم و یا واکوئول) یا خارج یاخته و یا به عنوان پروتئین غشایی در غشای یاخته فعالیت کنند. د) پروتئین هایی همچون آنزیم های رنابسپاراز ،هلیکاز دنابسپاراز و ... توسط ریبوزوم های آزاد در ماده زمین های سیتوپلاسم ساخته می شوند و در نهایت با عبور از منافذ پوشش هسته، به درون هسته وارد می شوند، چراکه محل فعالیت این پروتئین ها، فضای درون هسته است. دقت کنید که پروتئین هایی که به هسته وارد می شوند توسط ریبوزومهای آزاد ساخته می شوند. در حالی که &laquo;اتصال یک اندامک (رناتن) به نوعی غشای زیستی تک لایه&raquo; در خصوص ریبوزوم های متصل به غشای شبکه آندوپلاسمی زبر صادق است.', '2026-02-05 17:20:29'),
(873, 890, 'گزینه&laquo;4&raquo; با توجه به شکل کتاب درسی، بخش های مشخص شده به ترتیب: الف: آنزیم رنا بسپاراز ب: توالی ژن (بخشی از مولکول دنا) ج: رناتن (ریبوزوم) د: رشته پلی پپتیدی در حال ساخت ه: رنای پیک مطابق با شکل صورت سؤال، هر چه قدر که یک ریبوزوم به میزان بیشتری بر روی رنای پیک حرکت کند و رشته پلی پپتیدی طویل تری را بسازد به ژن (دنا) نزدیک تر می شود. بررسی سایر گزینه ها: 1) با توجه به شکل هر چه قدر که فاصله ریبوزوم از آنزیم رنابسپاراز و توالی دنا بیشتر باشد، به ابتدای رنای پیک و رمزه (کدون) آغاز و در نتیجه انتهای آمینی رشته پلی پپتیدی در حال ساخت نزدیک تر است. 2) دقت کنید در این ساختار تسبیح مانند، چندین ریبوزوم به شکل هم زمان در حال ترجمه هستند، اما این فرایند را به صورت هم زمان با هم شروع نکرده اند. 3) در یاخته های پروکاریوتی فقط یک نوع رنابسپار از رونویسی از ژن را بر عهده دارد؛ بنابراین در پروکاریوت ها انواعی از رنابسپار از مشاهده نمی شود. شکل هم مربوط به یک پروکاریوت است، چراکه رونویسی و ترجمه به صورت هم زمان انجام می شوند؛ هم چنین اگر این ساختار مربوط به یوکاریوت هم باشد چون رونویسی یک ژن خاص انجام می شود باز هم همۀ رنا بسپارازها از یک نوع هستند.', '2026-02-05 17:20:29'),
(875, 892, 'گزینه&laquo;4&raquo; موارد &laquo;ب&raquo; و &laquo;ج&raquo; ویژگی مشترک تنظیم مثبت و منفی در باکتری E.coli محسوب می شود. بررسی همه موارد: الف) در تنظیم مثبت، پروتئین فعال کننده به مالتوز و در تنظیم منفی، پروتئین مهارکننده به لاکتوز متصل می شود. در نبود لاکتوز، پروتئین مهار کننده به توالی اپراتور که در مجاورت نخستین ژن و راه انداز می باشد، متصل است. اما در حضور لاکتوز، مهارکننده متصل به لاکتوز از دنا جدا می شود. فعال کننده نیز پس از اتصال به مالتوز، به جایگاه اتصال فعال کننده که توالی ای در مجاورت راه انداز است، متصل می شود. دقت کنید که مهارکننده ای که به لاکتوز متصل است، توانایی اتصال به اپراتور را از دست می دهد، بنابراین این گزاره فقط برای تنظیم مثبت صادق است. ب) در طی تنظیم مثبت و منفی در پروکاریوت ها مشابه سایر جانداران، رونویسی با پیوستن رنابسپاراز به راه انداز آغاز می شود. بنابراین این گزاره برای هر دو نوع تنظیم رونویسی صادق است. دقت کنید در تنظیم مثبت و منفی، هر سه ژن مؤثر در تجزیه نوعی قند (لاکتوز یا مالتوز) یک توالی تنظیمی مشترک دارند. ج) محصول مستقیم رونویسی در هر دو حالت، رنای پیک حاوی اطلاعات سه ژن mRNA) چندژنی( است که این رنای پیک، در نهایت پس از ترجمه توسط ریبوزوم ها، سبب تولید رشته های پلی پپتیدی (بسپارهای زیستی) مختلفی می شود؛ پس ساختار نهایی این بسپارها، با یکدیگر متفاوت خواهد بود. د) در، E.coli لاکتوز موجود در محیط به باکتری وارد می شود و با اتصال به مهارکننده، باعث تغییر شکل آن می شود. تغییر شکل مهارکننده، آن را از اپراتور جدا می کند و نیز مانع از اتصال آن به اپراتور می شود. بنابراین مهارکننده دارای تمایل بیشتری برای اتصال به قند نسبت به دنا (توالی اپراتور) است. در تنظیم مثبت نیز، مالتوز پس از اتصال به فعال کننده باعث می شود، فعال کننده به جایگاه خود در دنا متصل شود؛ این گزاره در مورد تنظیم منفی صادق نیست.', '2026-02-05 17:20:29'),
(884, 901, 'گزینه&laquo;2&raquo; اشرشیاکلای و استرپتوکوکوس نومونیا از جمله باکتریهای مطرح شده در کتاب درسی اند. همچنین پارامسی نیز جزء آغازیان و یوکاریوت ها محسوب می شود. تنظیم بیان ژن، در پروکاریوت ها می تواند در هر یک از مراحل ساخت رنا و پروتئین تأثیر بگذارد، ولی به طور معمول تنظیم بیان ژن در این گروه از جانداران، در مرحله رونویسی انجام می شود. یعنی رونویسی شدن یا نشدن توالی ژن. بررسی سایر گزینه ها: 1) پروتئین های ساخته شده در سیتوپلاسم یاخته های یوکاریوتی سرنوشت های مختلفی پیدا می کنند. بعضی از این پروتئین ها به شبکه آندوپلاسمی و دستگاه گلژی می روند و سپس ممکن است برای ترشح به خارج از یاخته یا در غشای یاخته قرار بگیرند یا در بخشهایی مثل واکوئول و کافنده تن قرار بگیرند. بعضی پروتئین ها نیز در مادۀ زمینه سیتوپلاسم، راکیزه ها، هسته و یا دیسه ها می مانند و در آنجا فعالیت می کنند. رنا بسپاراز در هسته می تواند فعالیت کند. این آنزیم توالی آمینواسیدی خاصی دارد که پروتئین را به مقصدش (هسته) هدایت می کند. دقت کنید که باکتری ها هسته ندارند. ۳) همۀ انواع رنا در یاخته ها در نتیجه فعالیت نوعی رنابسپار از تولید می شوند، اما لزوما همۀ رناها بالغ نمی شوند! بالغ شدن گروهی از مولکول های رنای پیک فقط در یوکاریوت ها و در طی فرایند پیرایش صورت می گیرد که طی آن توالی های معینی از رنای ساخته شده، جدا و حذف می شوند و سایر بخش ها به هم متصل می شوند و یک رنای پیک یکپارچه می سازند. 4) در تنظیم رونویسی در پروکاریوت ها، عواملی به پیوستن رنابسپاراز به توالی راه انداز کمک (مثل فعال کننده) و یا مانع حرکت رنابسپاراز می شوند (مثل مهارکننده). در نتیجه، رونویسی ژن تسهیل یا از آن ممانعت می شود؛ مثلا با اتصال پروتئین مهار کننده به بخشی از دنا (اپراتور)که سر راه رنابسپاراز است، از انجام رونویسی جلوگیری می شود. (دقت کنید پروتئین های مهار کننده توانایی اتصال به راه انداز را ندارند)', '2026-02-05 17:20:29'),
(885, 902, 'گزینه&laquo;4&raquo; مولکول دنا اغلب با یک نردبان پیچ خورده مقایسه می شود. ستون های این نردبان را قند و فسفات و پیوند بین آنها و پله ها را بازهای آلی و پیوندهای هیدروژنی بین آن ها تشکیل می دهند. آنزیم های رنابسپاراز و هلیکاز در طی فعالیت خود پیوند هیدروژنی بین بازهای آلی مکمل (بخش پله ای ساختار نردبان پیچ خورده) را می شکنند. 1) هر آنزیم رنابسپار از از جنس پروتئین بوده و دارای ژن (های) سازنده است. آنزیم رنابسپار از ۲ چون در ساخت پروتئین نقش دارد (به واسطه ساخت رنای پیک مربوطه) می تواند ژن (های) سازندۀ خود و سایر انواع رنا بسپارازهای ۱ و ۳ را رونویسی کند (چراکه این ها هم، آنزیم هایی پروتئینی هستند) و یکی از رشته های ژن را الگوی خود قرار دهد در صورتی که سایر رنابسپارازها چنین ویژگی ای ندارند. 2) آنزیم های رنابسپاراز طبق شکل های ۱ و ۲ فصل ۲ زیست دوازدهم، هر دو رشته مولکول DNA (ژن) را در بر می گیرند. 3) ژن هایی که رمز کننده پروتئین ها هستند می توانند دارای بخش های اینترون و اگزون باشند، آنزیم رنا بسپاراز ۲ برخلاف سایر رنابسپارازها می تواند طی رونویسی، از توالی های اینترونی و اگزونی در ژن، رونوشت برداری کند.', '2026-02-05 17:20:29'),
(887, 904, 'گزینه&laquo;2&raquo; رانش دگرهای به دلیل توانایی ایجاد تغییر در فراوانی نسبی دگره ها، می تواند جمعیت را از حالت تعادل خارج کند. هر چه اندازه یک جمعیت کوچک تر باشد، رانش دگره ای اثر بیشتری بر آن دارد. اما طبق کتاب درسی، برای آن که جمعیتی در حال تعادل ژنی باشد، باید اندازه بزرگی داشته باشد. بررسی سایر گزینه ها: 1و ۳ ) جهش، شارش ژن و انتخاب طبیعی، به دلیل توانایی آن ها در تغییر فراوانی نسبی دگره ها! جمعیت را از تعادل ژنی خارج می کنند. 4) برای آنکه جمعیتی در حال تعادل باشد، لازم است آمیزش ها در آن تصادفی باشند. آمیزش تصادفی آمیزشی است که در آن احتمال آمیزش هر فرد با افراد جنس دیگر در آن جمعیت یکسان باشد. اگر آمیزش ها به رخ نمود یا ژن نمود بستگی داشته باشد، تصادفی نیست و فراوانی نسبی ژن نمودها تغییر می کند که در این حالت نیز، امکان خارج شدن جمعیت از تعادل وجود دارد.', '2026-02-05 17:20:29'),
(888, 905, 'گزینه&laquo;4&raquo; دقت کنید جهش جانشینی میتواند در برخی موارد الل جدید ایجاد کند و یا باعث ایجاد الل جدید نشود. همچنین جهش های واژگونی، جابه جایی و مضاعف شدگی نیز گاهی می توانند تغییری در تنوع دگرهای ایجاد نکنند و یا جابه جایی می تواند در برخی موارد، ترکیب دگره ای یک فام تن را تغییر دهد! پس تنها بعضی از این جهش ها (نه همه حالات) امکان تغییر ترکیب دگره ای را دارند. بررسی سایر گزینه ها: 1) اگر جانشینی در یک انتهای دنا در یکی از کروموزوم ها رخ دهد، ممکن است فقط یک پیوند فسفودی استر بشکند، دقت کنید که اگرچه طی جانشینی، هر دو نوکلئوتید مقابل (هم جفت) نوکلئوتید تغییر می کنند. اما این تغییر طی همانندسازی رخ می دهد؛ یعنی بعد از این که رشته ای از DNA که جهش در آن رخ داده است، در فرایند همانندسازی استفاده شود، نوکلئوتید مقابل آن هم تغییر می کند. همچنین دقت کنید طی جهش دوپار تیمین نیز تعداد نوکلئوتیدهای هسته ای تغییر نمی کند پس تعداد پیوند فسفودی استر نیز ثابت است (این پیوندها شکسته نمی شوند.) 2) جهش واژگونی همانند جابه جایی، جزء جهش های بزرگ محسوب می شود، پس می توانند سبب تغییرات گسترده در فام تن(های) یاخته شوند. دقت کنید که جهش جابه جایی همانند واژگونی میتواند به گونه ای رخ دهد که طول کروموزوم های یاخته (و همچنین تعداد نوکلئوتیدهای آن فام تن) تغییر نکند مثلا در جهش جابه جایی ممکن است بخش جابه جاشونده از کروموزوم اولیه، به سایر قسمت های همان کروموزوم (همان کروماتید) منتقل شود که در این صورت تغییری در طول کروموزوم مشاهده نمی شود. طبق شکل کتاب درسی، جهش واژگونی نیز باعث تغییر طول كروموزوم نمی شود و تنها قسمتی از یک کروموزوم به صورت وارونه در همان محل قرار می گیرد. همچنین جهش های مضاعف شدگی نیز باعث تغییرات گسترده در DNA می شود. 3) مثلا جهش جانشینی می تواند در توالی نوکلئوتیدی ژن(های) هموگلوبین تغییر ایجاد کند، اما دقت کنید که ساخت پروتئین هموگلوبین اصلن قرار نیست در یاخته های پوششی پوست صورت گیرد!', '2026-02-05 17:20:29'),
(889, 906, 'گزینه&laquo;4&raquo; انتخاب طبیعی عاملی است که در انتخاب فرد سازگارتر با محیط نقش دارد. افراد سازگارتر، الل هایی دارند که سبب این سازگاری شده است، پس وقتی این افراد انتخاب می شوند، الل های آن ها با احتمال بیشتری ممکن است به نسل بعد منتقل شوند، به عبارتی فراوانی نسبی این الل های مؤثر در سازگاری، افزایش می یابد. بررسی سایر گزینه ها: 1) جهش و رانش دگره ای از جمله رویدادهایی هستند که می توانند به صورت تصادفی رخ دهند؛ در طی رانش دگره ای ممکن است تعدادی از افراد جمعیت حذف شوند، اما ممکن است افراد باقی مانده ژنوتیپ مشابه افراد حذف شده داشته باشند؛ در نتیجه هیچ نوعی از دگره ها از جمعیت حذف نمی گردد. جهش نیز لزوما باعث حذف دگره ها نمی شود؛ بلکه حتی ممکن است دگره جدیدی ایجاد کند و باعث افزایش تنوع دگره ای شود. 2) اگر جهش نامطلوب بوده باشد، منجر به ناسازگار شدن فرد و مرگ وی می شود، پس در نهایت، بعد از گذشت مدتی خزانه ژنی غنی تر نخواهد شد. از طرفی مثلا طی جهش دوپار تیمین که بر اثر پرتو فرابنفش رخ می دهد، ژن جدیدی به افراد جمعیت اضافه نمی شود، پس خزانه ژنی غنی تر نخواهد شد. گاهی اوقات برخی جهش ها مثل خاموش باعث تغییر دگره نمی شوند. 3) مهاجرت افراد (شارش ژنی) اگر به صورت دوسویه باشد می تواند شبیه شدن خزانه های ژنی دو جمعیت (مبدأ و مقصد) را در پی داشته باشد.', '2026-02-05 17:20:29'),
(890, 907, 'گزینه&laquo;2&raquo; طی کراسینگ اور علاوه بر امکان تشکیل گامت های نوترکیب (که ترکیب دگره ای جدیدی دارند)، گامت های والدی (دارای ژنوتیپ قدیمی) هم تشکیل می شوند که این گامت ها، همان گامت هایی هستند که بدون کراسینگ اور نیز (از قبل) تولید می شده اند. بررسی سایر گزینه ها: 1) جاندارانی که دارای توانایی تولیدمثل جنسی هستند، در تعریف ارنست مایر در رابطه با گونه قرار می گیرند؛ کراسینگ اور طی تقسیم میوز رخ می دهد، اما توجه کنید که تولید گامت همیشه با میوز نیست، مثلا زنبور عسل نر با استفاده از تقسیم میتوز گامت تولید می کند که طی آن کراسینگ اور قابل مشاهده نمی باشد. 3) طی کراسینگ اور، ایجاد ترکیبات جدید دگره ای تنها در حالتی دو گامت از نوع والدین رخ می دهد که فام تن های همتا در رابطه با صفت مورد نظر به صورت ناخالص باشند. در واقع قطعه ای از کروموزومها که طی کراسینگ اور با هم جابه جا می شوند، دارای دگره ه ای متفاوتی باشند. 4) در مراحل پروفاز و متافاز و ابتدای آنافاز تقسیم میوز ۱، امکان مشاهده تترادها وجود دارد؛ اما کراسینگ اور تنها در مرحله پروفاز میوز ۱،قابل مشاهده است.', '2026-02-05 17:20:29'),
(891, 908, 'گزینه&laquo;2&raquo; موارد &laquo;الف&raquo; و &laquo;ب&raquo; نادرست هستند. بررسی همه موارد: الف) نادرست ـ در بیماری کم خونی داسی شکل، آمینواسید والین به جای گلوتامیک اسید در زنجیره بتای هموگلوبین قرار گرفته است. ب) نادرست ـ در فرد مبتلا به کم خونی داسی شکل، در رشته الگوی ژن جهش یافته، نوکلئوتید A قرار دارد، در حالی که در دنای سالم، در این رشته از دنا، نوکلئوتید T قرار گرفته است؛ به دلیل وجود رابطه مکملی بین بازهای آلی A و T، در هر صورت در ژن زنجیره بتا، تعداد نوکلئوتیدهای دارای باز آلی A و T تغییری نمی کند، چراکه در هر دو حالت، هم چنان باز آلی A با T، پیوند هیدروژنی برقرار می کند؛ در نتیجه تعداد پیوندهای هیدروژنی در کل این ژن نسبت به قبل جهش، تغییری نخواهد کرد. ج) درست - در رنای پیک حاصل از ژن جهش یافته، باز آلی یوراسیل قرار می گیرد، در واقع در رنای طبیعی باز آدنین وجود دارد که تغییر می کند. آدنین، نوعی باز پورینی و دو حلقه ای است؛ اما یوراسیل نوعی باز پیریمیدین و تک حلقه ای می باشد. د) درست ـ در این بیماری، تغییر در ساختار اول نیمی از زنجیره های پلی پپتیدی هموگلوبین (زنجیره های بتا) به تغییر در ساختار نهایی (ساختار چهارم )این پروتئین منجر می شود. به عبارتی به خاطر تغییر در نوع و توالی آمینواسیدها، ساختارهای بعدی نیز ممکن است تغییر کند، به خاطر', '2026-02-05 17:20:29'),
(892, 909, 'گزینه&laquo;4&raquo; گیاه ذکر شده در صورت سؤال، دارای عدد کروموزومی \\( 4n=28 \\) است. این گل مغربی همانند گونه نیایی خود (با عدد کروموزومی \\(2n=14\\) ) در هر مجموعه کروموزومی خود هفت کروموزوم دارد. یعنی در هر دو \\(n=7\\) است! بررسی سایر گزینه ها: 1) این گل مغربی ها در پی آمیزش با سایر گل مغربی های چارلاد می توانند زادها ی زیستا و زایا به وجود بیاورند (زاده های تتراپلوئید) و با آمیزش با گیاهان دولاد، می توانند زاده ای زیستا تولید کنند (زاده های تریپلوئید) دقت کنید گیاه تریپلوئید زیستا و نازا است. 2) این گیاه، چارلاد است اما از نظر محتوای وراثتی با گیاه والد خود تفاوتی ندارد؛ یعنی همان الل ها و ژن ها را دارد فقط تعداد این ژن ها بیشتر است، بنابراین تغییری در ژنگان آن نسبت به گیاه والد ایجاد نشده است، زیرا همان کروموزومهای والدی را دارد. 3) در پی آمیزش گیاه دولاد (واجد گامت (\\(n\\) با گیاه چارلاد (با گامت\\(2n \\)) گیاه حاصل سه لاد (\\(3n\\) ) است، ولی تخم ضمیمه آن می تواند \\(4n\\) یا \\(5n\\) باشد. (اگر گیاه نر ، \\(4n\\) باشد و ماده \\(&larr;2n \\) اسپرم \\(+2n\\) یاخته دوهسته ای (\\(n+n\\) )= تخم ضمیمه \\(4n\\) و اگر گیاه ماده \\(4n\\) باشد و نر \\(&larr;2n\\) یاخته دوهسته ای \\(+(2n+2n)\\) اسپرم \\(n\\) = تخم ضمیمه \\( 5n\\) ) همچنین پوسته دانه نیز می تواند \\(2n\\) یا \\(4n\\) باشد. از طرفی گیاه \\(4n\\) اگر گامت طبیعی \\(2n\\) تولید کند و گونۀ نیایی، گامت غیر طبیعی \\(2n\\)؛ همچنان زادهای \\(4n\\) تولید خواهد شد!', '2026-02-05 17:20:29'),
(893, 910, 'گزینه&laquo;2&raquo; توالی هایی از دنا را که در بین گونه های مختلف دیده می شوند، توالی های حفظ شده می نامند، در جانورانی از گونه های متفاوت که خویشاوندی نزدیک تری با یکدیگر دارند، تعداد توالی های حفظ شده مشابه در دنای آن ها بیشتر است. دلفین و شیرکوهی نسبت به سایر گزینه ها، خویشاوندی نزدیک تری با هم دارند (طبق شکل ۱۱ در فصل ۴ زیست شناسی (۳))؛ در نتیجه در دنای آن ها تعداد توالی های حفظ شده مشابه هم، بیشتر است. به عبارتی دنای آن ها شباهت بیشتری به یکدیگر دارد. در مورد1 ، بدانید درخت گیسو نوعی نهان دانه است، اما خزه جزء این دسته از گیاهان نیست و طبق کتاب یازدهم، در گروه متفاوتی قرار دارد؛ پس با هم خیلی متفاوت هستند. دلفین و کوسه نسبت به شیرکوهی و دلفین ،خویشاوندی دورتری از هم دارند، پس این گزینه هم رد می شود. در مورد4 بدانید که پروانه مونارک نوعی جانور بی مهره است و با کبوتر خانگی که جزء مهره داران است، خویشاوندی نزدیک ندارد!', '2026-02-05 17:20:29'),
(895, 912, 'گزینه&laquo;3&raquo; شکل، نشان دهنده گونه زایی هم میهنی است. طبق خط کتاب درسی، &laquo;اگر میان افراد یک گونه جدایی تولید مثلی رخ دهد، آن گاه خزانه ژنی آن ها از یکدیگر جدا و احتمال تشکیل گونه جدید فراهم می شود. منظور از جدایی تولید مثلی، عواملی است که مانع آمیزش بعضی از افراد یک گونه با بعضی دیگر از افراد همان گونه می شوند.&raquo; بررسی سایر گزینه ها: 1) این مورد مربوط به گونه زایی دگرمیهنی است؛ نه هم میهنی. این مانع جغرافیایی به همراه عوامل برهم زننده تعادل و کراسینگ اور، در ایجاد گونه جدید نقش دارد. 2) گونه زایی هم میهنی به دلایل مختلفی رخ می دهد؛ یکی از دلایل آن تشکیل گامت هایی هست که به دلیل جهش پلی پلوئیدی، عدد کروموزومی متفاوتی با گامت طبیعی دارند که به دنبال لقاح این گامت های غیر طبیعی، ایجاد گونۀ جدید ممکن می شود، تجزیه پروتئین اتصالی در ناحیه سانترومر، در میوز ۲ و یا میتوز رخ می دهد، که در صورت تجزیه نشدن آن، احتمال تشکیل گامت های غیر طبیعی از نظر تعداد فام تن ها وجود دارد، اما دقت کنید تشکیل این نوع گامت ها می تواند به دلیل خطا در تقسیم میوز ۱ هم باشد که همۀ فام تن ها به یکی از یاخته ها می رسند؛ در چنین زمانی هم امکان تشکیل گونه جدید، طی گونه زایی هم میهنی وجود دارد. دقت کنید طی تقسیم میوز ۱ تجزیه پروتئین اتصالی و جداشدن کروماتیدهای خواهری رخ نمیدهد. 4) وجود گامت متفاوت با گامت والدی سبب گونه زایی می شود اما این گامت لزوما از نظر تنوع اللی متفاوت نیست؛ بلکه ممکن است همان الل ها را داشته باشد ،اما تعداد فام تن ها متفاوت باشد.', '2026-02-05 17:20:29'),
(906, 923, 'گزینه&laquo;3&raquo; موارد سوم و چهارم نادرست هستند. بررسی همه موارد: مورد اول و دوم: مطابق مربع پانت رسم شده، احتمال تولد فرزندان پسر و دختر مقاوم به مالاریا )\\(Hb^AHb^A \\) (و در معرض خطر ابتلا به مالاریا \\((Hb^AHb^A )\\)وجود دارد. مورد سوم: تولد فرزندی با ژنوتیپ کاملن سالم با توجه به مربع پانت، ممکن است (\\(Hb^AHb^A\\)) اما دقت کنید که پدر و مادر ژنوتیپ ناخالص دارند. پس کاملا سالم نیستند چراکه در شرایط کمبود اکسیژن، گویچه های قرمز آن ها، داسی شکل می شود. مورد چهارم: در مناطق مالاریاخیز، فردی با ژنوتیپ \\(Hb^AHb^S \\) احتمال بقای بیشتری دارد چراکه انگل مالاریا نمی تواند او را بیمار کند، اما افراد\\(Hb^AHb^A\\) به دلیل ابتلا به بیماری مالاریا، ممکن است بمیرند )کاهش احتمال بقا)؛ اما دقت کنید که ژن نمود مادر خانواده \\(Hb^A Hb^S\\) است.', '2026-02-05 17:20:29'),
(907, 924, 'گزینه&laquo;2&raquo; رمزۀ آغاز توالی AUG و رمزه های پایان یکی از سه توالی UAG ،UGA و UAA را دارند. لذا نوکلئوتیدهای مشترک بین همۀ این رمزه ها، ریبونوکلئوتیدهای Aدار و Uدار هستند. ریبونوکلئوتیدهای آدنین دار در حالت سه فسفاته و آزاد (ATP) می توانند به عنوان شکل رایج انرژی مصرف شوند. بررسی سایر گزینه ها: 1) یوراسیل نوعی باز آلی پیریمیدینی و متشکل از یک حلقه آلی نیتروژن دار است. 3) در نوکلئوتیدهای مختلف، گروه فسفات به کربن خارج از حلقه آلی قند متصل می شود. به عبارتی در حلقه ۵ضلعی قند، ۴ کربن وجود دارد و یکی از کربن های قند در خارج از ساختار حلقه قرار دارد. 4) کدون مربوط به والین، GUA است که هر دو ریبونوکلئوتید Uدار و A دار را دارد.', '2026-02-05 17:20:29'),
(909, 926, 'گزینه&laquo;2&raquo; عدم اتصال لاکتوز (دی ساکارید موجود در شیر) به پروتئین مهار کننده می تواند ناشی از تغییر شکل پروتئین مهارکننده (تغییر شکل محل اتصال قند لاكتوز) باشد. این حالت ممکن است به علت جهشی باشد که درون توالی ژنی مربوط به ساخت این پروتئین در یاخته رخ داده است که سبب تغییر شکل فضایی آن شده است. بررسی سایر گزینه ها: 1) پروتئین فعال کننده به جایگاه مخصوص خود در دنا که قبل از توالی راه انداز قرار دارد متصل می شود به عبارتی پروتئین فعال کننده هیچ گاه به توالی راه انداز متصل نمی شود؛ بنابراین این مورد از پیامدهای جهش در باکتری اشرشیاکلای نیست. ۳) باکتری ها فقط یک رنا بسپار از دارند که مختص خودشان است رنابسپار از ۲ فقط در یاخته های یوکاریوتی دیده می شود. جهش در توالی های تنظیمی می تواند میزان رونویسی را تغییر دهد، مثلا آن را افزایش دهد. توالی های تنظیمی در خارج از ژن قرار دارند و جزء توالی های ژنی محسوب نمی شوند. 4) پروتئین فعال کننده به مالتوز (قند موجود در جوانه گندم و جو) وصل شده و سپس با یکدیگر به جایگاه اتصال فعال کننده در مولکول دنا متصل می شوند. پروتئین فعال کننده خودش به تجزیه مالتوز نمی پردازد و آنزیم تجزیه کننده نمی باشد.', '2026-02-05 17:20:29'),
(910, 927, 'گزینه&laquo;1&raquo; ابعاد مولکول دنا برای نخستین بار توسط ویلکینز و فرانکلین کشف شد؛ در حالی که یکسان بودن قطر دنا در سراسر این مولکول و همچنین علت این موضوع، از نتایج مدل مولکولی واتسون و کریک بود. بررسی سایر گزینه ها: 2) چارگاف نخستین کسی بود که برابری تعداد بازهای آلی آدنین و تیمین در کل مولکول دنا (نه فقط یک رشته آن) را متوجه شد، اما این دانشمند نتوانست علت برابری این جفت بازها را با یکدیگر توضیح دهد. 3) ویلکینز و فرانکلین برای نخستین بار مارپیچی بودن مولکول دنا را متوجه شدند. اما دقت داشته باشید این دانشمندان در آزمایشات خود بیان کردند مولکول دنا از بیش از یک رشته تشکیل شده است، اما نگفتند دنا قطعن دورشته ای است. یعنی فقط فهمیدند بیش از یک رشته دارد، نه اینکه دورشته ای باشد. 4) گریفیت برای نخستین بار انتقال مادۀ وراثتی میان جانداران گوناگون و یاخته های زنده را مشاهده کرد. این دانشمند در آزمایشات خود از باکتری استرپتوکوکوس نومونیا استفاده کرد که عامل اصلی بروز بیماری سینه پهلو است. در آزمایشات این دانشمند ماهیت ماده وراثتی و نحوه انتقال آن بین یاخته ها مشخص نشد.', '2026-02-05 17:20:29'),
(911, 928, 'گزینه&laquo;1&raquo; طبق تعریف کتاب درسی، ژنگان به کل محتوای مادۀ وراثتی یاخته گفته می شود و در یوکاریوت ها، برابر است با مجموع محتوای مادۀ وراثتی هسته ای و سیتوپلاسمی (درستی1) . طبق قرارداد، ژنگان هسته ای را معادل مجموعه ای شامل یک نسخه از هر یک از انواع فام تن ها در نظر می گیرند. پس از بین دو فام تن همتا در انسان، فقط اطلاعات وراثتی یکی از آن ها در نظر گرفته می شود نه هر دوی آن ها. ژنگان هسته ای انسان بیشترین بخش ژنوم انسان را تشکیل می دهد و شامل ۲۲ فام تن غیر جنسی و فام تنهای جنسی X و Y است؛ به عبارتی ژنوم در ارتباط با یک فرد تعریف نمی شود بلکه افراد هر دو جنس به شکل هم زمان مد نظر قرار می گیرند. (نادرستی ۳ و ۴). دناهای راکیزه، ژنگان سیتوپلاسمی را در ژنگان انسان تشکیل می دهد. ژن ها فقط بخشی از ژنگان اند و توالی های بین ژنی نیز جزء ژنگان هستند(نادرستی 1).', '2026-02-05 17:20:29'),
(912, 929, 'گزینه&laquo;2&raquo; تمامی نوکلئوتیدها حلقه پنج ضلعی متصل به حلقه شش ضلعی دارند؛ نوکلئوتیدهای پورین دار، یک حلقه پنج ضلعی و یک حلقه شش ضلعی در باز آلی خود دارند که به هم متصل هستند و در نوکلئوتیدهای پیریمیدین دار نیز بین حلقه (شش ضلعی) باز آلی (پنج ضلعی) قند اتصال وجود دارد. با این اوصاف فقط نوکلئوتیدهای پوریندار دنا در مقابل نوکلئوتیدهای پیریمیدین دار قرار می گیرند. بررسی سایر گزینه ها: 1) برخی رناها می توانند خاصیت آنزیمی داشته باشند. همۀ نوکلئوتیدهایی که در ساختار انواع رناها قابل مشاهده اند، حداقل در زمان رونویسی (لحظه قرارگیری در رشته پلی نوکلئوتیدی در حال ساخت) می توانند با دئوکسی ریبونوکلئوتیدهای رشته الگوی ژن، پیوند هیدروژنی برقرار کنند. 3) نوکلئوتیدی که در ساختار دنای حلقوی به کار می رود، تنها دارای یک گروه فسفات است. بنابراین اگر بگوییم این نوکلئوتیدها دارای کربنی متصل به گروه های فسفات می باشند، جمله ای غلط بیان کرده ایم. 4) مفهوم این گزینه، کاملا به درستی بیان شده است، چراکه طبق شکل کتاب درسی مشخص است که نوکلئوتیدهای دارای قند ریبوز و یا باز آلی یوراسیل (قابل مشاهده در محل دوراهی های همانندسازی) توسط دنابسپار از در ساختار رشته در حال ساخت قرار نمی گیرند؛ اما دلیل رد این گزینه، چیز دیگری است! دقت داشته باشید که یاخته نگهبان روزنه قابلیت تقسیم ندارد، پس قابلیت همانندسازی دنای خطی هسته خود را نیز ندارد و اصلا دوراهی های همانندسازی در هسته آن شکل نمی گیرند.', '2026-02-05 17:20:29'),
(913, 930, 'گزینه&laquo;1&raquo; در ابتدای مرحله آغاز ترجمه، بخش هایی از رنای پیک در قبل از کدون آغاز، ابتدا زیرواحد کوچک رناتن را به سوی رمزه آغاز هدایت می کند. در ادامه، زیر واحد بزرگ رناتن به این مجموعه می پیوندد. بررسی سایر گزینه ها: 2) با توجه به شکل های ۱۲ و ۱۴ فصل ۲ زیست شناسی3 ، انتهای آمینی پلی پپتید حاصل از ترجمه در مرحله طویل شدن ترجمه، می تواند خارج از رناتن و در نتیجه، خارج از زیرواحد بزرگ آن، مشاهده شود. انتهای کربوکسیل این پلی پپتید، نیز در مرحله پایان ترجمه از رنای ناقل جدا و از زیرواحد بزرگ رناتن خارج می گردد. 3) طبق متن و شکل های کتاب درسی صحیح است. جایگاه های رناتن، تنها در ساختار کامل رناتن شامل هر دو زیرواحد کوچک و بزرگ) دیده می شوند، نه هر یک از آن ها به تنهایی! 4) طبق شکل ۱۳ فصل ۲ زیست شناسی3 ، رنای ناقل تنها در داخل بخشی از جایگاه مختص خود در ساختار رناتن مشاهده می شود، به عنوان مثال رنای ناقل در بخش هایی از زیرواحد کوچک رناتن دیده نمی شود.', '2026-02-05 17:20:29'),
(914, 931, 'گزینه&laquo;4&raquo; با رسم همۀ ژن نمودهای حاصل از آمیزش بین این افراد می توان گفت (۴) تعداد بیشتری را شامل می شود؛ به عبارتی براساس ژن نمودهای مادر می توان گفت در هر چهار حالت آمیزش بین والدین امکان تولد دختری سالم و غیر خالص برای حداقل یک صفت (مثل \\(X^HX^hHb^AHb^s\\) ) وجود دارد. بررسی سایر گزینه ها: 1) در سه حالت امکان تولد دختری فقط مبتلا به یک نوع بیماری وجود دارد اما اگر مادر خانواده دارای ژن نمود\\(X^HX^HHb^AHb^A \\) باشد، دیگر دختر خانواده بیمار نخواهد بود. 2) این مورد از نظر علمی ایراد دارد، از آنجا که بیماری هموفیلی نوعی بیماری وابسته به جنس (کروموزوم \\(X\\) ) و نهفته است، بنابراین پسر مبتلا به بیماری هموفیلی فقط دارای یک دگره نهفته بر روی کروموزوم \\(X\\) خود بوده و نمی تواند برای این صفت، خالص باشد! 3) مطابق ژن نمودها در سه حالت می توان پسری بیمار و واجد حداقل دو دگره بیماری زا (،\\(X^hYHb^AHb^s \\)\\(X^hYHb^SHb^s\\) و \\(X^HYHb^SHb^s\\)) را مشاهده نمود.', '2026-02-05 17:20:29'),
(915, 932, 'گزینه&laquo;4&raquo; فقط در یوکاریوت ها، تعداد جایگاه های آغاز همانندسازی، بسته به مراحل رشد و نمو تنظیم می شود. بررسی سایر گزینه ها: 1) در پروکاریوت ها چنین امکانی وجود دارد و دلیل آن هم، وقوع رونویسی و ترجمه در یک محل از یاخته (سیتوپلاسم) است. 2) تنظیم بیان ژن در سطح فام تنی، مختص یوکاریوت هاست که با افزایش یا کاهش میزان فشردگی فام تن ها، رونویسی از ژن ها به دلیل تفاوت در دسترسی آنزیم به آن ها تغییر می کند. ۳) در هر دو گروه جانداران ذکر شده، طبق متن کتاب درسی، رنای ناقل پس از رونویسی دچار تغییراتی می شود. این رنای ناقل، پیچ وتاب می خورد (دچار تاخوردگی می شود) و ساختار سه بعدی خاصی پیدا می کند و در نهایت آمینواسید خاصی هم به آن متصل می شود.', '2026-02-05 17:20:29'),
(917, 934, 'گزینه&laquo;3&raquo; آنزیم های ویژه ای که براساس نوع توالی پادرمزه، آمینواسید مناسب را به رنای ناقل متصل می کنند؛ برای این کار نیازمند مصرف انرژی هستند. علاوه بر این، رنایی که در تشکیل پیوند پپتیدی شرکت می کند نیز، برای این کار، انرژی مصرف می کند. طبق متن کتاب درسی، انرژی لازم برای تهیه پلی پپتید طی ترجمه، از مولکول های پرانرژی مانند ATP به دست می آید. لذا هر دو فرایند انرژی خواه هستند و آنزیم های مورد نظر به کمک فرایندی انرژی زا (تجزیه ATP با آزاد شدن انرژی همراه است)، انرژی مورد نیاز آن را تأمین می کنند. بررسی سایر گزینه ها: 1) در یوکاریوت ها، برخی از مولکول های RNA در هسته تولید می شوند ولی در سیتوپلاسم فعالیت می کنند؛ از جمله رنایی که در ساختار رناتن های موجود در سیتوپلاسم فعالیت می کند. آنزیم متصل کننده آمینواسید به رنای ناقل، به دنبال ترجمۀ رنای پیک در سیتوپلاسم تولید و در همان بخش هم فعالیت می کند. 2) آنزیم رنا از جنس نوکلئیک اسید است، نه پروتئین. 4) فقط برای آنزیم ویژه اتصال دهنده آمینواسید مناسب به رنای ناقل صادق است.', '2026-02-05 17:20:29');
INSERT INTO `descriptive_answers_tam24` (`id`, `question_id`, `answer_text`, `created_at`) VALUES
(920, 937, 'گزینه&laquo;2&raquo; جهش های بزرگ ساختاری از نوع مضاعف شدن و جابه جایی (در صورتی که بین دو فام تن صورت گیرد)، با جداشدن قطعه ای از یک کروموزوم و اضافه شدن آن به کروموزوم دیگر همراه هستند، پس منجر به افزایش میزان مادۀ وراثتی و افزایش تعداد ساختارهای نوکلئوزومی در کروموزوم جهش یافته ای که قطعه کروموزومی را دریافت می کنند، می شوند. مطابق توضیحات، می دانیم که ابتدا باید با تجزیه پیوندهای فسفودی استر، قطعه ای از یک کروموزوم جدا شود تا بتواند به کروموزوم دیگری اتصال یابد. بررسی سایر گزینه ها 1) هر دو ویژگی این مورد را می توان به جهش های بزرگ از نوع عددی نسبت داد! در این نوع جهش ها اگر مثلا تعداد کروموزومها افزایش یابد، با وجود این که هیچ گونه پیوند اشتراکی میان نوکلئوتیدهای مادۀ وراثتی تجزیه نشده است اما مقدار کل مادۀ وراثتی نوعی یاخته حاصل از تقسیم تغییر کرده است. ۳) اگر جهش بزرگ ساختاری از نوع واژگونی، به گونه ای رخ دهد که محل سانترومر را تحت تأثیر قرار دهد، تغییری در طول کل کروموزوم ایجاد نمی کند؛ ولی به دلیل تغییر جایگاه سانترومر نسبت به قبل، توسط تصاویر کاریوتیپ قابل تشخیص می باشد. جهش جابه جایی هم می تواند بدون تغییر در طول کل فام تن رخ دهد، اگر قطعه ای از یک کروماتید برود به بخش دیگری در همان کروماتید متصل شود؛ در این حالت هم به دلیل تغییر در ساختار فام تن و موقعیت سانترومر آن (علی رغم عدم تغيير طول كل فام تن) می توان آن را در کاریوتیپ تشخیص داد. 4) جهش جابه جایی، با تغییر موقعیت یک قطعه فام تن، تعداد ژن های دو کروموزوم را تغییر می دهد. جهش بزرگ جابه جایی، چون بین کروموزوم های غیرهمتا صورت می گیرد، می تواند در یاخته های هاپلوئید نیز قابل انجام باشد.', '2026-02-05 17:20:29'),
(921, 938, 'گزینه&laquo;4&raquo; منظور صورت سؤال گریفیت است که اطلاعات اولیه از مادۀ وراثتی از آزمایشات آن به دست آمد. ایوری و همکارانش، به ماهیت مادۀ وراثتی پی بردند. آزمایشات این دانشمندان منجر به کشف نوع یا همان مادۀ وراثتی شد و بعد از آزمایش های گریفیت انجام شد. بررسی همه موارد: الف) گریفیت در سومین آزمایش خود، باکتری های پوشینه دار را حرارت داد و سبب تخریب برخی مولکول های زیستی این باکتری ها (مثل را برخی پروتئین ها) و مرگ آنها شد. ب) برای ایوری و همکارانش صادق است. گریفیت در آزمایش های خود از گریزانه، استفاده نکرد. ج) گریفیت در چهارمین آزمایش خود، مولکول های زیستی باکتری های پوشینه دار کشته شده (مثل دنا) را در مجاورت باکتری های بدون پوشینه زنده قرار داد. د) این گزینه در مورد گریفیت نادرست است، چراکه او مخلوط پوشینه دارهای کشته شده و بدون پوشینه ها را، با هم به موش تزریق کرد و پوشینه دار شدن باکتری ها، در بدن موش رخ داد. در واقع تزریق باکتری های پوشینه دار زنده رخ نداد.', '2026-02-05 17:20:29'),
(922, 939, 'گزینه&laquo;3&raquo; شکل، مربوط به مرحله پایان ترجمه و قرارگیری عامل آزادکننده در جایگاه A است. پس از این رویداد، عوامل آزادکننده باعث جداشدن همه چیز از هم می شوند. ابتدا جداشدن پلی پپتید از آخرین رنای ناقل و سپس جداشدن این رنای ناقل از رنای پیک رخ می دهد (شکستن پیوندهای هیدروژنی و خارج شدن رنای ناقل از رناتن) و پس از این رویداد جداشدن زیرواحدهای رناتن از هم و جداشدن رنای پیک از رناتن، رخ می دهد. (نادرستی ۳ و درستی 1.) بررسی سایر گزینه ها: 2) قبل از این مرحله آخرین وقایع مرحله طویل شدن رخ می دهد که در آن، به دنبال آخرین جابه جایی رناتن روی رنای پیک، چهارمین رنای ناقل (برحسب تعداد آمینواسیدهای قابل مشاهده در شکل سؤال) پس از ورود به جایگاه E از آن خارج می شود و پنجمین رنای ناقل به جایگاه P وارد خواهد شد. طی ترجمه، به ازای هر آمینواسید قرار گرفته در رشته پپتیدی، یک رنای ناقل در رناتن قابل مشاهده است. 4) پادرمزۀ GAA در رنای ناقل وجود دارد که مکمل رمزۀ CUU در رنای پیک است. در مرحله طویل شدن، طبق شکل کتاب درسی، بعد از ورود tRNA مکمل به جایگاه A و تشکیل پیوند پپتیدی، در پی حرکت رناتن، tRNA فاقد آمینواسید به جایگاه E وارد می شود و سپس از آن خارج میشود.', '2026-02-05 17:20:29'),
(923, 940, 'گزینه&laquo;1&raquo; تنها مورد &laquo;ج&raquo; غیر ممکن است. منظور از صورت سؤال، آنزیم های پروتئینی هستند. بررسی همه موارد: الف) بعضی از آنزیم ها برای فعالیت خود به کوآنزیم ها نیاز ندارند، پس در نبود این مولکول ها نیز، همچنان قادر به افزایش سرعت واکنش های شیمیایی یا کاهش مدت زمان لازم برای انجام این واکنش ها هستند. ب) آنزیم هایی که در تجزیه مواد سمی و خنثی کردن آن ها نقش دارند (مانند گروهی از آنزیم های کبدی که ماده سمی آمونیاک را به اوره تبدیل می کنند)، با ورود مواد سمی به جایگاه فعال آنها، به فعالیت صحیح خود ادامه می دهند. ج) بیشتر آنزیم های بدن انسان در دمای ۳۷ درجه سانتی گراد بهترین فعالیت را دارند (آنزیم های موجود در بیضه ها در دمای پایین تری فعالیت می کنند). این آنزیم های پروتئینی در دمای بالاتر ممکن است شکل غیرطبیعی و برگشت ناپذیر پیدا کنند و غیر فعال شوند. آنزیم هایی که در دمای پایین غیر فعال می شوند، با برگشت دما به حالت طبیعی، می توانند به حالت فعال برگردند. اما آنزیم های پروتئینی که در دمای بالا (مثلا در تب شدید) غیر فعال می شوند، با برگشت دما به حالت طبیعی، مجددا فعال نخواهند شد. در واقع در اثر گرما یا غیر فعال نمی شوند یا اگر غیر فعال شوند به شکل طبیعی برنمی گردند. د) بعضی آنزیم های پروتئینی در یاخته ای فعالیت می کنند که توسط خود یاخته تولید نشده اند، مثل آنزیم القاکننده مرگ یاخته ای که توسط لنفوسیت T کشنده تولید می شود. اما در یاخته های دیگری (مثل سرطانی یا آلوده به ویروس) فعالیت می کند.', '2026-02-05 17:20:29'),
(924, 941, 'گزینه&laquo;3&raquo; تجمع رناتن ها بر روی رنای پیک هم در پروکاریوت ها و هم در یوکاریوت ها مشاهده می شود. در این شرایط میزان تولید پروتئین ها افزایش می یابد، چراکه به طور همزمان تعداد زیادی پروتئین در حال ساخته شدن هستند. در همۀ این جانداران، عوامل آزاد کننده در مرحله پایان ترجمه فعالیت می کنند. ترجمه هم در بیان شدن ژن ها نقش دارد. بررسی سایر گزینه ها: 1) رونویسی در یوکاریوت ها در هسته و سیتوپلاسم رخ می دهد (درون اندامک های میتوکندری و دیسه ها). ترجمه هم در یوکاریوت ها در ماده زمینه سیتوپلاسم (برای ژن های هسته ای) و درون میتوکندری و دیسه ها (برای ژن های خودشان) رخ می دهد. در پروکاریوت ها هم که رونویسی و ترجمه در سیتوپلاسم است، پس تولید پروتئین ها در محل انجام رونویسی، توسط پروکاریوت ها و یوکاریوت ها (در داخل دیسه و راکیزه) قابل انجام است. در یوکاریوت ها دنا در هر فام تن به صورت خطی است، در واقع دنای سیتوپلاسمی یوکاریوت ها که درون راکیزه و دیسه ها است، فام تن محسوب نمی شود. 2) همۀ یوکاریوت ها و برخی از پروکاریوت ها می توانند بیش از یک جایگاه آغاز همانندسازی داشته باشند اما رنای پیک بالغ فقط مختص یوکاریوت هاست. در یوکاریوت ها در گروهی از ژن ها پس از رونویسی، رنای پیک نابالغی تولید می شود که رونوشت اینترون و اگزون دارد که رونوشت اینترون ها حذف و رونوشت اگزون ها به هم متصل می شوند. 4) در پروکاریوت ها، یک نوع رنابسپاراز وجود دارد و می تواند به راه انداز همۀ ژن های روشن متصل شود. هیستون ها فقط در یوکاریوت ها یافت می شوند.', '2026-02-05 17:20:29'),
(925, 942, 'گزینه&laquo;2&raquo; پس از شروع همانندسازی در بخشی از دنا، در محل دوراهی های همانندسازی، آنزیم های هلیکاز و دنابسپار از حضور دارند. طبق متن کتاب درسی، در محلی که دو رشته دنا از هم جدا می شوند، دو ساختار Y مانند به وجود می آید که به هر یک از آنها دوراهی همانندسازی می گویند. در فاصله بین این دو ساختار، پیوندهای هیدروژنی بین دو رشته دنای اولیه شکسته شده (این دو رشته از هم جدا شده اند) و پیوندهای فسفودی استر در رشته در حال ساخت و پیوندهای هیدروژنی بین رشته الگو و رشته در حال ساخت تشکیل می شود. آنزیم دنابسپار از علاوه بر این که پیوند فسفودی استر ایجاد می کند، می تواند طی ویرایش پیوند فسفودی استر را در رشته در حال ساخت (فقط در یک رشته دنا) بشکند. این آنزیم فعالیت بسپارازی دارد. بررسی سایر گزینه ها: 1) آنزیم هایی که پیچ وتاب فامینه را باز می کنند، فاقد فعالیت نوکلئازی هستند، دقت کنید این آنزیم ها اصلا در محل دوراهی های همانندسازی وجود ندارند؛ بلکه پیش از آغاز همانندسازی و شکل گیری دوراهی های همانندسازی، فعالیت خود را انجام می دهند. 3) هلیکاز مارپیچ دنا و دو رشته آن را از هم باز می کند. این آنزیم برای شکستن پیوندهای هیدروژنی بین جفت نوکلئوتید گوانین دار و سیتوزین دار باید انرژی بیشتری مصرف کند (نسبت به جفت نوکلئوتید آدنین دار و تیمین دار)، زیرا تعداد پیوندهای هیدروژنی بین سیتوزین و گوانین بیشتر از این تعداد بین آدنین و تیمین است. 4) دنابسپار از نوکلئوتیدهای مکمل را مقابل هم قرار می دهد. این آنزیم علاوه بر فرایند ویرایش، طی فعالیت بسپارازی خود، پیوند اشتراکی بین فسفاتی در نوکلئوتیدهای سه فسفاته ای که می خواهند به رشته در حال ساخت اضافه شوند را تجزیه می کنند.', '2026-02-05 17:20:29'),
(926, 943, 'گزینه&laquo;4&raquo; برقراری مجدد پیوند هیدروژنی بین نوکلئوتیدهای دنا (نوکلئوتیدهای رشته های الگو و رمزگذار) مربوط به مراحل طویل شدن و پایان رونویسی است. نخستین نوکلئوتید ژن در مرحله آغاز رونویسی الگوبرداری می شود، ولی در مرحله طویل شدن با نوکلئوتید مکمل خود در دنا مجددا پیوند هیدروژنی تشکیل می دهد. طبق متن کتاب در این مرحله رنابسپار از ساخت رنا را ادامه می دهد که در نتیجه آن، رنا طویل می شود. همچنان که مولکول رنابسپاراز به پیش می رود، دو رشته دنا در جلوی آن از یکدیگر باز و در چندین نوکلئوتید عقب تر، رنا از دنا جدا می شود و دو رشته دنا مجددا به هم می پیوندند. بررسی سایر گزینه ها: 1) این گزینه در مرحله آغاز رونویسی رخ می دهد که آنزیم رنابسپاراز با شناسایی راه انداز، رونویسی را از محل صحیح خود آغاز می کند. 2) رنای در حال ساخت علاوه بر این که به جای نوکلئوتید Tدار، نوکلئوتید Uدار دارد، در نوکلئوتیدهای خود نیز به جای قند دئوکسی ریبوز دارای قند ریبوز است. نوکلئوتیدها از نظر نوع باز، نوع قند و تعداد فسفات می توانند با هم متفاوت باشند. 3) رنا بسپاراز در مقابل نوکلئوتیدهای آدنین دار رشته الگو (نه رمزگذار)، نوکلئوتیدهای یوراسیل دار را قرار می دهد.', '2026-02-05 17:20:29'),
(927, 944, 'گزینه&laquo;3&raquo; منظور صورت سؤال، جهش دگر معنا است که از نوع جهش های جانشینی می باشد. در کم خونی داسی شکل، یک آمینواسید جانشین آمینواسید دیگری شده است که این حالت در اثر جهش دگر معنا رخ می دهد. بررسی همه موارد: الف) گروهی از جهش های حذف و اضافه که با حذف و یا اضافه شدن نوکلئوتیدهایی با مضرب غیر از ۳ رخ می دهند، توانایی تغییر چارچوب خواندن را دارند. ب) جهش های کوچک در کاریوتیپ غیر قابل تشخیص هستند. ج) هم جهش دگر معنا و هم خاموش با تغییر در توالی نوکلئوتیدی دنا همراه هستند که به دنبال رونویسی از این بخش دنا، رنای حاصل هم توالی نوکلئوتیدی متفاوت با قبل خواهد داشت. تفاوت این دو جهش در وقوع تغییر در رشته پلی پپتیدی حاصل از ژن است. در دگر معنا این رشته هم تغییر می کند، اما در خاموش، توالی آمینواسیدی رشته پلی پپتیدی حاصل از ژن تغییری نمی کند. د) جهش دگر معنا همواره بر طول رشته پلی پپتیدی حاصل از ژن بی تأثیر است.', '2026-02-05 17:20:29'),
(928, 945, 'گزینه&laquo;3&raquo; اندامهای آنالوگ نشان دهنده روش های متفاوت سازش جانداران در پاسخ به یک نیاز مشترک هستند. اندام های آنالوگ در تعیین خویشاوندی استفاده نمی شوند. از اندام های همتا و و ستیجیال می توان برای تعیین خویشاوندی استفاده کرد. بررسی سایر گزینه ها: 1) توالی های حفظ شده، توالی هایی هستند که در بین گونه های مختلف وجود دارند؛ به عبارتی نشان دهنده یک ویژگی یا صفت مشترک بین همه این افراد هستند، چرا که رمزهای دنا، رمزه های رنا و نوع آمینواسیدهای مرتبط با این رمزها در بین جانداران مختلف مشابه است، به عبارتی در همۀ جانداران رمزۀ AUG در رنای پیک به متیونین ترجمه می شود. 2) مقایسۀ گونه ها را می توان در تراز ژنگان (ژنوم) هم انجام داد. از این مقایسه، اطلاعات ارزشمندی به دست می آید. مثلا این که کدام ژن ها در بین گونه ها مشترک اند و کدام ژن ها ویژگی های خاص یک گونه را باعث می شوند. همچنین زیست شناسان از مقایسه بین دنای جانداران مختلف برای تشخیص خویشاوندی آنها استفاده می کنند. هر چه بین دنای دو جاندار، شباهت بیشتری وجود داشته باشد، یعنی خویشاوندی نزدیک تری هم با یکدیگر دارند. 4) از شواهد مختلفی برای رده بندی جانداران می توان استفاده کرد مثل توالی نوکلئوتیدی ژنوم، ساختارهای همتا و وستيجيال، طبق شکل کتاب درسی در فصل ۴ زیست شناسی 3 ، دلفین خویشاوندی نزدیک تری با شیرکوهی نسبت به کوسه دارد، زیرا هر دو پستاندار هستند.', '2026-02-05 17:20:29'),
(929, 946, 'گزینه&laquo;1&raquo; منظور از عامل تمایز دهنده آمینواسیدها از یکدیگر، گروه R آنها است. همان طور که در شکل مقابل مشاهده می کنید، در ساختار مارپیچی و صفحه ای، گروه های R پیوند هیدروژنی ساختار صفحه ای می توانند به سمت بیرون اسکلت کربن - نیتروژن زنجیره قرار بگیرند. بررسی سایر گزینه ها: 2) در تشکیل ساختار دوم (هم مارپیچ و هم صفحه ای) الگوهایی تکراری از پیوندهای هیدروژنی بین گروه های CO و NH شکل می گیرد. ۳) طبق شکل، هر یک از اتم های کربن موجود در اسکلت اصلی زنجیره که خارج از گروه های R قرار دارند، از یک سمت به یک اتم کربن دیگر و از سمت دیگر به اتم نیتروژن متصل اند. 4) تشکیل ساختار سوم (ساختار تاخورده و متصل به هم) با نزدیک شدن گروه های R آب گریز آمینواسیدها به هم و ایجاد برهم کنش های آب گریز همراه است؛ در نتیجه نقش این گروه ها از سایر بخش های آمینواسیدها برای تشکیل ساختار سوم بیشتر است.', '2026-02-05 17:20:29'),
(930, 947, 'گزینه&laquo;4&raquo; کاهش تفاوت های ژنتیکی میان افراد یک جمعیت می تواند منجر به کاهش تفاوت های فردی میان افراد جمعیت و شبیه شدن آنها به هم شود؛ هر چه افراد یک جمعیت به هم شبیه تر باشند، یعنی ویژگی های مشترک بیشتری داشته باشند، توان بقای جمعیت کمتر می شود؛ چراکه اگر با یک عامل ناسازگار محیطی مواجه شوند همۀ آنها از نظر مقابله یا مواجه با این عامل شبیه هم هستند، پس یا سازگارند یا ناسازگار؛ اگر ناسازگار باشند، بخش زیادی از افراد جمعیت به دلیل ناسازگاری (در اثر انتخاب طبیعی) می میرند. بررسی سایر گزینه ها: 1) افزوده شدن دگرۀ جدید به خزانه ژنی یک جمعیت، هم می تواند متأثر از جهش و هم می تواند متأثر از شارش ژنی به درون یک جمعیت باشد. در صورت شارش، تغییر ماندگار در نوکلئوتیدهای مادۀ وراثتی افراد رخ نمی دهد و این مورد، تعریف جهش است. 2) در صورتی که حذف شدن دگره ای خاص از یک جمعیت، تحت تأثیر رانش ژنی رخ دهد، به دلیل انتخاب افراد سازگارتر با محیط رخ نداده است. در واقع بخش دوم این گزینه توصیفی از انتخاب طبیعی است. دقت کنید در اثر رانش هم ممکن است افراد سازگارتر نیز باقی بمانند، اما این باقی ماندن تصادفی است، اما در انتخاب طبیعی بقای این افراد هدفمند است. ۳) عوامل برهم زننده تعادل در یک جمعیت، می توانند منجر به کاهش فراوانی نسبی برخی از دگره ها در جمعیت شوند، اما خب بخش دوم این گزینه در خصوص شارش ژنی صادق نخواهد بود، یا مثلا جهش ممکن است منجر به حذف برخی دگره ها شود که این حذف لزوما به معنی حذف شدن افراد نیست.', '2026-02-05 17:20:29'),
(931, 948, 'گزینه&laquo;1&raquo; در مراحل آغاز و پایان ترجمه (دو مرحله) تنها جایگاه P ریبوزوم از رنای ناقل پر شده است. از طرفی، در دو مرحله از فرایند رونویسی (طویل شدن و پایان)، تشکیل پیوند هیدروژنی بین دو رشته دنا قابل مشاهده است. باز T فقط در دنا وجود دارد؛ پس منظور قسمت دوم گزینه، اتصال دو رشته دنا، به هم است. بررسی سایر گزینه ها: 2) در مراحل طویل شدن و پایان ترجمه (دو مرحله)، رنای ناقل متصل به زنجیره آمینواسیدی در جایگاه P رناتن قرار می گیرد. تشکیل پیوندهای فسفودی استر بین نوکلئوتیدهای رنا را می توان در تمامی مراحل فرایند رونویسی مشاهده نمود. ۳) پیوند اشتراکی که در جایگاه P رناتن شکسته می شود، هرگز و در هیچ مرحله ای از نوع پپتیدی نیست؛ بلکه پیوند میان آمینواسید و ریبونوکلئوتید مولکول رنای ناقل در این جایگاه شکسته می شود. طی ترجمه پیوندهای پپتیدی تشکیل می شوند، اما شکسته نمی شوند. 4) در مرحله طویل شدن ترجمه، پیوندهای هیدروژنی میان رمزه رنای پیک و پادرمزه رنای ناقل مکمل آن، در جایگاه E شکسته می شوند (فقط یک مرحله). دقت داشته باشید که در مرحله پایان، شکست این پیوندهای هیدروژنی در جایگاه P رخ می دهد. در خصوص فرایند رونویسی نیز توجه داشته باشید که در مرحله آغاز، راه انداز و در مرحله پایان، جایگاه پایان رونویسی مورد شناسایی قرار می گیرند؛ پس در دو مرحله می توان شناسایی توالی های خاص از دنا را مشاهده نمود که آنزیم به آنها متصل است.', '2026-02-05 17:20:29'),
(932, 949, 'گزینه&laquo;3&raquo; در محیطی که لاکتوز نیز وجود دارد، ممکن است قند دیگری مثل گلوکز هم باشد. در این صورت باکتری ترجیح می دهد که از گلوکز استفاده کند. برای تجزیه شدن گلوکز نیز الزامی بر جداشدن مهار کننده از توالی اپراتور وجود ندارد. در شرایطی که گلوکز و لاکتوز هر دو در محیط باشند، مهارکننده به اپراتور متصل است و با جلوگیری از رونویسی ژن های مرتبط با تجزیه لاکتوز، آنزیم های مربوطه هم ساخته نمی شود و لاکتوز تجزیه نمی شود. بررسی سایر گزینه ها: 1) در صورتی که باکتری وارد محیطی شود که فقط قند مالتوز در آن قرار دارد، از این قند برای تأمین انرژی استفاده می کند. در این حالت مالتوز به پروتئین فعال کننده متصل می شود؛ در نتیجه این اتفاق، فعال کننده به جایگاه خود در دنا متصل می شود و به رنابسپار از کمک می کند که رونویسی ژن های مرتبط با تجزیه مالتوز را شروع کند. این کمک کردن از طریق اتصال فعال کننده متصل به مالتوز به رنابسپار از امکان پذیر می شود (پیوستن پروتئین به پروتئین). 2) در صورت قرارگیری باکتری در محیطی که فقط لاکتوز دارد باکتری باید مسیرهایی را طی کند که بتواند لاکتوز را تجزیه کند. طی این فرایند، لاکتوز به مهارکننده متصل می شود و باعث می شود که مهارکننده تغییر شکل داده و از دنا جدا شود؛ در نتیجه رنابسپار از از روی راه انداز و اپراتور ژن های مرتبط با تجزیه لاکتوز عبور می کند. ۴) در محیطی که مالتوز نیز وجود دارد، ممکن است گلوکز و یا حتی لاکتوز هم وجود داشته باشد. در هر صورت یاخته از هر کدام از این قندها بخواهد استفاده کند، باید آنها را در جایگاه فعال آنزیمی قرار دهد که آن را تجزیه می کند و در نتیجه انرژی در دسترس یاخته بیشتر می شود.', '2026-02-05 17:20:29'),
(933, 950, 'گزینه&laquo;1&raquo; فقط مورد &laquo;ب&raquo;، عبارت را به درستی کامل می کند. در این سؤال، با یک صورت سؤال چالشی و مفهومی مواجه هستیم. از اون تستاس که بعدش می گید عجب نکته ای داشت! بررسی همه موارد: الف) مطابق شکل ۱۹ در صفحه ۳۵ زیست شناسی (۳) دیده می شود که عوامل رونویسی متصل به افزاینده، اندازه بزرگ تری نسبت به رنابسپاراز متصل به راه انداز دارند، این عوامل متصل به افزاینده، به رنابسپار از کمک می کنند تا سرعت رونویسی را افزایش دهد. ب) پروتئین هایی که پس از تولید در مادۀ زمینه سیتوپلاسم، به هسته منتقل می شوند و درون آن فعالیت می کنند، توسط رناتن های آزاد سیتوپلاسمی تولید شده اند. در یوکاریوت ها پروتئین سازی در هسته صورت نمی گیرد. پروتئین ها فقط در سیتوپلاسم ساخته می شود (یا در ماده زمینه ای آن و یا در اندامک هایی مثل راکیزه و یا دیسه ها). ج) این مورد، در خصوص عوامل رونویسی متصل به افزاینده صادق خواهد بود، اما خب در مورد هیستون ها صادق نیست. هیستون ها به شکل مستقیم سرعت رونویسی را زیاد نمی کنند. از طرفی اگر قرار باشد رونویسی اتفاق بیفتد، باید هیستون ها از دنا، جدا شوند. د) این مورد نیز فقط در خصوص عوامل رونویسی صادق است؛ چراکه اتصال هیستون به دنا و تغییر فشردگی آن، تنظیم بیان ژن در سطح فام تنی را معرفی می کند.', '2026-02-05 17:20:29'),
(934, 951, 'گزینه&laquo;2&raquo; ششمین آمینواسید موجود در زنجیره بتای هموگلوبین، در افراد مبتلا به کم خونی داسی شکل آمینواسید والین و در افراد سالم، گلوتامیک اسید است. با فرض مطرح شده در صورت سؤال، فقط یک آمینواسید والین در بین ۱۰ آمینواسید ابتدایی رشته بتای هموگلوبین فرد بیمار یافت می شود و طبق متن کتاب، والین ششمین آمینواسید این زنجیره پلی پپتیدی خواهد بود. در فرد مبتلا به کم خونی داسی شکل، با توجه به این که دو رنای ناقل ابتدایی بدون جابه جایی رناتن درون آن قرار می گیرند، لذا به دنبال چهارمین جابه جایی رناتن روی رنای پیک، رنای ناقل آمینواسید والین (با پادرمزه CAU) وارد جایگاه A می شود (نادرستی 1 ، با پنجمین جابه جایی رناتن، این رنای ناقل که دیگر به زنجیره ای از آمینواسیدها متصل شده است، از جایگاه A وارد جایگاه P می شود و در نهایت با ششمین جابه جایی رناتن، این رنای ناقل که از آمینواسیدها جدا شده است، وارد جایگاه E شده و بلافاصله از آن خارج می شود. بررسی سایر گزینه ها: 3) به دنبال انجام چهارمین جابه جایی رناتن و ورود رنای ناقل حمل کننده والین به جایگاه A، زنجیره آمینواسیدی از جایگاه P به جایگاه A منتقل و بین والین و آمینواسید پنجم، پیوند پپتیدی تشکیل می شود. 4) دقت کنید که بعد از جابه جایی پنجم رناتن، والین که از یک سو در پیوند پپتیدی شرکت کرده است و از سوی دیگر به رنای ناقل خود متصل است، از رنای ناقل جدا و همراه با انتقال با زنجیره آمینواسیدی به جایگاه A ، در دومین پیوند پپتیدی خود نیز شرکت می کند، لذا پس از جابه جایی ششم رناتن، این آمینواسید دیگر پیوند پپتیدی جدیدی تشکیل نمی دهد.', '2026-02-05 17:20:29'),
(935, 952, 'گزینه&laquo;2&raquo; تنها مورد &laquo;د&raquo; غیرممکن است. بررسی همه موارد: الف) امکان تولد دختری ناقل (ناخالص) هر دو بیماری فنیل کتونوری و کم خونی داسی شکل، از ژنوتیپ والدین ذکر شده وجود خواهد داشت. ب) امکان تولد فرزند پسری با ژنوتیپ خالص بارز HbA HbA وجود دارد که واجد گویچه های قرمزی کاملا طبیعی است. ج) در این خانواده امکان تولد فرزندان ناخالص (HbA Hbs) وجود دارد. در بدن دختر واجد این ژنوتیپ، یاخته های ماهیچه اسکلتی که چند هسته ای هستند، به تعداد هسته های خود دگره Hbs را در خود جای داده اند. د) طبق متن کتاب، انگل مالاریا نمی تواند در افراد ناخالص HbA Hbs سبب بیماری شود، اما می تواند به آنها وارد شود، از کجا به این نتیجه رسیدیم؟ در کتاب درسی گفته شده است این انگل بخشی از چرخه زندگی خود را در گویچه های قرمز می گذراند؛ پس در همه افراد انگل وارد گویچه های قرمز می شود اما در همه بیماری ایجاد نمی کند.', '2026-02-05 17:20:29'),
(936, 953, 'گزینه&laquo;2&raquo; دنای حلقوی به منظور همانندسازی خود (همزمان با چرخه یاخته ای و یا مستقل از چرخه یاخته ای) می تواند به پروتئین هایی مثل آنزیم های هلیکاز و دنابسپار از متصل گردد! راستی همین جا بگم که پروتئین ها توی ساختار شون پیوند هیدروژنی دارن! رنای ناقل نیز در حین ترجمه یک رنای پیک، می تواند به زنجیره ای از آمینواسیدها اتصال یابد (مثلا طی مرحله طویل شدن). حالا نکته اصلی این جاست که طبق شکل ۱۴ در صفحه ۳۱ کتاب درسی زیست شناسی ۳، دیده می شود که پروتئین ها می توانند همزمان با مراحل ساخت خود در رناتن و قبل از اتمام فرایند ترجمه هنگامی که به رنای ناقل موجود در رناتن اتصال دارند)، پیچ و تاب هایی در رشته پلی پپتیدی خود پیدا کنند. این پیچ و تاب ها می تواند در اثر تشکیل پیوندهای هیدروژنی بین آمینواسیدها باشد. خوشت اومد؟ از طرفی رنا هم حین ساخته شدن می تواند به رنابسپار از متصل باشد. بررسی سایر گزینه ها: 1) برابر بودن تعداد بازهای آلی پورینی و پیریمیدینی، فقط ویژگی دناست! که این برابر بودن به خاطر وجود رابطه مکملی بین بازهاست. 3) فقط ساختار دنا دورشته ای است و این گزینه در خصوص رنای ناقل نادرست می باشد. 4) رنای ناقل ساختار خطی دارد و بنابراین نوکلئوتیدهای ابتدا و انتهای آن، فقط در تشکیل یک پیوند فسفودی استر شرکت می کنند.', '2026-02-05 17:20:29'),
(937, 954, 'گزینه&laquo;2&raquo; موارد &laquo;الف&raquo; و &laquo;ج&raquo; عبارت را به نادرستی کامل می کنند. مطابق کتاب درسی، تعریف گونه از نگاه! ارنست مایر برای جاندارانی صادق است که تولید مثل جنسی دارند که شامل گیاهان و جانوران می شود. بررسی همه موارد: الف) لزوما هر فردی برای تولید مثل جنسی نیازمند حضور جانداری همگونۀ خود نمی باشد. به عنوان مثال کرم کبد، نوعی کرم هرمافرودیت است که می تواند تخمک های خود را به کمک اسپرم های خود بارور سازد. ب) گیاهان هم تولید مثل جنسی دارند، اما فضای سیناپسی فقط در جانوران دارای بافت عصبی دیده می شود؛ بنابراین عبارت صحیح است. ج) تک یاخته ای هایی مانند باکتری ها نیز فاقد تولید مثل جنسی هستند. دقت کنید باکتری ها فضای بین یاخته ای ندارند! همه جانداران زنده غشای یاخته ای دارند که عبور و مرور مواد از غشای یاخته ها را تنظیم می کند. د) گروهی از جاندارانی که فاقد تولید مثل جنسی هستند، یوکاریوت هستند و می توانند هسته و اندامک های غشادار داشته باشند، مانند پارامسی! بنابراین این گزینه در خصوص فقط بعضی از جانداران فاقد توانایی انجام تولید مثل جنسی صحیح است!', '2026-02-05 17:20:29'),
(938, 955, 'گزینه&laquo;1&raquo; منظور از بخش مشخص شده در شکل صورت سؤال، گروه R در آمینواسیدها است. تنها مورد سوم صحیح است. بررسی همه موارد: مورد اول: با توجه به این که گروه R در هر آمینواسید منحصر به فرد است، در واقع تنها تفاوت آمینواسیدها با هم، در گروه R آنهاست، لذا به تعداد انواع آمینواسیدها، فرمول شیمیایی برای گروه R وجود دارد. دقت کنید که تنوع آمینواسیدهای موجود در طبیعت، بیشتر از ۲۰ تا است، اما تنها ۲۰ نوع از آنها در تشکیل پروتئین ها شرکت می کنند. مورد دوم: منظور از ساختار خطی، ساختار اول پروتئین ها است. گروه های R آمینواسیدها در تشکیل پیوندهای پپتیدی شرکت نمی کنند؛ بلکه این گروه های کربوکسیل و آمینی هستند که موجب تشکیل پیوند پپتیدی می شوند. مورد سوم: ابتدا دقت کنید که طبق متن کتاب درسی، تأثیر هر آمینواسید بر شکل دهی پروتئین، وابسته به ماهیت شیمیایی گروه R است. تغییر pH محیط با تأثیر بر پیوندهای شیمیایی مولکول پروتئین می تواند باعث تغییر شکل آنزیم شود، لذا این مورد می تواند با تغییر در پیوندهای شیمیایی مربوط به این گروه نیز صورت گرفته باشد. مورد چهارم: تفاوت آمینواسیدها با هم در ماهیت شیمیایی گروه R آنهاست و تفاوت رناهای ناقل با هم نیز در توالی پادرمزه آنها می باشد. از آنجا که تنوع پادرمزه ها بیشتر از آمینواسیدهاست (بعضی آمینواسیدها بیش از یک نوع رمزه و در نتیجه بیش از یک پادرمزه دارند)؛ پس تنوع فرمول شیمیایی گروه های R آمینواسیدها در بدن انسان قطعا کمتر از تنوع پادرمزه ها خواهد بود.', '2026-02-05 17:20:29'),
(939, 956, 'گزینه&laquo;2&raquo; به طور کلی سازوکارهایی را که باعث ایجاد گونه های جدید می شوند، به دو گروه تقسیم می کنند؛ گونه زایی دگرمیهنی که در آن جدایی جغرافیایی رخ می دهد و گونه زایی هم میهنی که در بین افرادی رخ می دهد که در یک زیستگاه زندگی می کنند. در گونه زایی دگرمیهنی، سد جغرافیایی ایجاد شده، ارتباط دو جمعیت را قطع می کنند و بین آنها دیگر شارش ژن (یکی از عوامل برهم زننده تعادل جمعیت) صورت نمی گیرد. توقف شارش ژنی بین دو گروه جدا شده از هم برای وقوع گونه زایی دگر میهنی لازم است، اما توقف این عامل برای گونه زایی هم میهنی ضروری نیست. بررسی سایر گزینه ها: 1) در هر دو نوع گونه زایی، پدیده رانش ژن می تواند رخ دهد که بر میزان تفاوت دو جمعیت بیفزاید! از طرفی دقت کنید رانش بر جمعیت های کوچک تر مؤثرتر می باشد. 3) در گونه زایی هم میهنی که بین افراد ساکن یک زیستگاه رخ می دهد ایجاد گونه جدید به طور ناگهانی و در طی یک نسل رخ می دهد؛ نه طی نسل ها و به طور تدریجی! دقت کنید گونه زایی دگرمیهنی که می تواند به صورت تدریجی رخ دهد، بین افرادی رخ می دهد که در دو زیستگاه متفاوت زندگی می کنند، به عبارتی این گزینه کلا غلط است. 4) در همه انواع گونه زایی، خزانه ژنی دو جمعیت از هم جدا و گونه جدید ایجاد می شود. از آنجا که افراد دو گونه متفاوت قادر به آمیزش موفقیت آمیز با یکدیگر نیستند؛ در نتیجه تبادل ژن بین آنها متوقف می گردد.', '2026-02-05 17:20:29'),
(940, 957, 'گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. منظور صورت سؤال، عوامل رونویسی متصل شونده به راه انداز در یوکاریوت ها و نیز پروتئین فعال کننده متصل شونده به جایگاه خود در دنای پروکاریوت ها است. بررسی همه موارد: الف) در یوکاریوت ها، طبق متن کتاب درسی، تمایل پیوستن عوامل رونویسی به راه انداز در اثر عواملی تغییر می کند؛ در پروکاریوت ها نیز قند مالتوز در تغییر تمایل اتصال پروتئین فعال کننده به جایگاه اتصال خود نقش دارد. اما دقت کنید که جایگاه اتصال پروتئین فعال کننده در پروکاریوت ها، راه انداز نیست. مالتوز در تمایل پیوستن فعال کننده به جایگاه ویژه خود در دنا نقش دارد. ب) طبق شکل های ۱۷ و ۱۸ کتاب درسی در فصل 2، هر دو پروتئین مذکور نسبت به رنابسپاراز در بخش دورتری از توالی ژن به دنا متصل می شوند. ج) عوامل رونویسی به دنا و فعال کننده به قند مالتوز و دنا متصل می شوند. دنا دارای دئوکسی ریبوز و مالتوز دارای گلوکز است؛ در واقع هر دو مولکول تنها یک نوع کربوهیدرات دارند. د) عوامل رونویسی و پروتئین فعال کننده، ابتدا به جایگاه خود در دنا متصل می شوند و سپس رنابسپاراز را به محل صحیح خود هدایت می کنند، به عبارتی اتصال این ها به دنا همزمان با اتصالشان به رنابسپار از نیست.', '2026-02-05 17:20:29'),
(941, 958, 'گزینه&laquo;4&raquo; انجام مهاجرت یعنی شارش ژنی اگر افراد از جمعیت اولیه به جمعیت مقصد مهاجرت کنند، در جمعیت مقصد شانس تولیدمثل دارند؛ پس احتمال دارد شانس آنها در تشکیل خزانه ژنی نسل بعد افزایش یابد. به دنبال شارش ژنی، فراوانی نسبی دگره ها در هر دو جمعیت مبدأ و مقصد می تواند تغییر کند و بنابراین هر دو جمعیت می توانند از تعادل ژنی خارج شوند. بررسی سایر گزینه ها: 1) آمیزش غیر تصادفی می تواند سبب خروج جمعیت از حالت تعادل شود. در این حالت، انتخاب جفت می تواند براساس ویژگی های ظاهری یا رفتاری صورت بگیرد. 2) ممکن است این افراد با محیط سازگار بوده باشند، اما بروز شرایطی مانند سیل و ... که از وقایع مربوط به رانش هستند، سبب مرگ آنها شده باشد. رانش اللی ارتباطی با میزان سازگاری افراد با محیط ندارد. 3) جهش، تغییر ماندگار در مادۀ وراثتی می باشد. دقت کنید که جهش ها اگر اکتسابی باشند و تنها بر یاخته های پیکری جاندار اثر گذاشته باشند، آنگاه به نسل های بعد منتقل نمی شوند (مثلا جهش در یاخته های پوست بدن انسان). همچنین توجه کنید برخی جهش ها مانند جهش های خاموش و یا جهش های رخ داده در توالی های بین ژنی، تأثیری بر روی فراوانی نسبی دگره ها و ژنوتیپ ها نخواهند داشت.', '2026-02-05 17:20:29'),
(942, 959, 'گزینه&laquo;4&raquo; همه موارد عبارت را به درستی کامل می کنند. بررسی همه موارد: الف) گروهی از پروتئین هایی که در جلوگیری از تقسیم بیش از حد یاخته ها و مبارزه با سرطان مؤثرند، درون سیتوپلاسم خود یاخته (پروتئین های پدال ترمز در چرخه یاخته ای) و گروهی دیگر در خارج از سیتوپلاسم خود یاخته (مثل پرفورین و آنزیم همراهش) تولید می شوند. پروتئین های درون یاخته ای توسط رناتن های آزاد در سیتوپلاسم ساخته می شوند و پروتئین های ترشحی توسط رناتن های سطح شبکه آندوپلاسمی تولید می شوند. ب) گروهی از پروتئین هایی که درون ریز کیسه های داخل یاخته مشاهده می شوند، ممکن است از خارج از یاخته در پی درون بری به سیتوپلاسم آن وارد شده باشند و موقتا در آن ذخیره شوند؛ بنابراین لزوما هر پروتئین قرار گرفته در ریز کیسه، توسط رناتن های متصل به شبکه آندوپلاسمی همان یاخته ساخته نشده است. ج) پروتئین های مختلفی می توانند ساختار یا شکل غشا را تغییر بدهند، مثل پروتئین مکمل یا پرفورین که در آن منفذ می سازند. همچنین دقت کنید حین تقسیم سیتوپلاسم یاخته جانوری، رشته های اکتین و میوزین که به غشا متصل می شوند و حلقه انقباضی را می سازند، می توانند شکل غشا را تغییر دهند. اکتین و میوزین توسط رناتن های آزاد و پرفورین و پروتئین مکمل توسط رناتن های متصل به شبکه آندوپلاسمی سنتز می شوند. د) آنزیم های درون یاخته ای می توانند هم توسط رناتن های آزاد (مانند هلیکاز دنابسپاراز و ...) و هم توسط رناتن های متصل به شبکه آندوپلاسمی (مانند آنزیم های درون لیزوزوم) سنتز شوند.', '2026-02-05 17:20:29'),
(943, 960, 'گزینه&laquo;1&raquo; همه موارد به درستی بیان شده اند. بررسی همه موارد: الف) مقاوم شدن باکتری ها به پادزیست ها یکی از مثال هایی است که نشان می دهد، موجودات زنده در گذر زمان تغییر می کنند. ب) انتخاب طبیعی با انتخاب کردن افراد سازگارتر برای بقا و تولیدمثل گوناگونی را در جمعیت کاهش می دهد. ج) برای پایداری جمعیت باید تفاوتهای فردی بین اعضای جمعیت وجود داشته باشد تا در صورت تغییر شرایط محیط به دلیل تنوع موجود در جمعیت تعدادی با این شرایط جدید سازگار باشند و جمعیت بتواند بقا داشته باشد. د) محیط زندگی یک جاندار تعیین می کند که کدام صفات سازگارتر هستند (می توانند به نسل بعد منتقل شوند) و کدام صفات ناسازگارتر (حذف می شوند و به نسل بعد نمی رسند)! بسته به نوع محیط، صفتی که در یک جمعیت سازگار است ممکن است در جمعیت بعدی ناسازگار باشد.', '2026-02-05 17:20:29'),
(944, 961, 'گزینه&laquo;2&raquo; رمزۀ آغاز توالی AUG و رمزه های پایان یکی از سه توالی UAG ، UGA و UAA را دارند. لذا نوکلئوتیدهای مشترک بین همۀ این رمزه ها، ریبونوکلئوتیدهای Aدار و Uدار هستند. ریبونوکلئوتیدهای آدنین دار در حالت سه فسفاته و آزاد (ATP) می توانند به عنوان شکل رایج انرژی مصرف شوند. بررسی سایر گزینه ها: 1) يوراسيل نوعی باز آلی پیریمیدینی و متشکل از یک حلقه آلی نیتروژن دار است. 3) در نوکلئوتیدهای مختلف، گروه فسفات به کربن خارج از حلقه آلی قند متصل می شود. به عبارتی در حلقه ۵ضلعی قند، ۴ کربن وجود دارد و یکی از کربنهای قند در خارج از ساختار حلقه قرار دارد. 4) کدون مربوط به والین، GUA است که هر دو ریبونوکلئوتید Uدار و Aدار را دارد.', '2026-02-05 17:20:29'),
(945, 962, 'گزینه&laquo;4&raquo; در فرایند قندکافت (اولین مرحله تنفس هوازی)، مولکول های گلوکز، قند سه کربنۀ فسفاته و ADP گروه(های) فسفات دریافت می کنند. در واکنش هایی از قند کافت که این مولکول ها، مصرف می شوند، به ترتیب ADP، NADH و ATP حاصل می شود که همگی ترکیباتی نوکلئوتیدی هستند. بررسی سایر گزینه ها: 1) برای ADP صادق نیست؛ دقت کنید درست است که در ساختار ADP، قند ریبوز مشاهده می شود؛ اما ترکیبی نوکلئوتیدی محسوب می شود. 2) گلوکز از ATP و ADP از اسید دوفسفاته، فسفات خود را دریافت می کنند، اما قند سه کربنه فسفاته، گروه فسفات را به صورت آزاد، دریافت می کند و آن را از ترکیب آلی دریافت نمی کند. 3) در زمان مصرف قند سه کربنی فسفاته، +NAD مصرف می شود و NADH که نوعی حامل الکترون است تولید می شود. دقت کنید حداقل می توان گفت، ADP در تولید حامل الکترون نقش ندارد.', '2026-02-05 17:20:29'),
(946, 963, 'گزینه&laquo;2&raquo; از مصرف یک اسید دوفسفاته تا پایان یک چرخه کربس، سه مولکول کربن دی اکسید آزاد می شود؛ دوتا در طی چرخه کربس و یکی در اکسایش پیرووات (دقت کنید این اعداد مربوط به زمانی است که یک اسید دوفسفاته مصرف شود). بررسی سایر گزینه ها: 1) طی سمیت زدایی آمونیاک در کبد، آمونیاک با کربن دی اکسید، ترکیب می شود و اورهای تولید می شود که سمیت کمتری دارد، به عبارتی طی این فرایند \\(CO_2\\) مصرف می شود نه آزاد. 3) اکسایش استیل کوآنزیم A در چرخه کربس رخ می دهد که در هر چرخه، دو کربن دی اکسید به ازای هر استیل کوآنزیم A آزاد می شود. 4) در اینجا دو کربن دی اکسید تولید می شود! در واقع طی تنفس یاخته ای به ازای مصرف هر استیل تا تولید اولین ترکیب ۴کربنی در چرخه کربس، دو کربن دی اکسید تولید می شود.', '2026-02-05 17:20:29'),
(947, 964, 'گزینه&laquo;2&raquo; طبق متن کتاب درسی، مولکول ATP شکل رایج انرژی در یاخته است. این مولکول می تواند از افزوده شدن ۳ گروه فسفات به آدنوزین (شامل آدنین و قند ریبوز) طی سه مرحله ایجاد شود. در سومین مرحله افزوده شدن فسفات، گروه فسفات به ADP افزوده می شود. ADP دارای یک پیوند پرانرژی بین فسفاتی است. خود ATP دارای دو پیوند پرانرژی بین فسفاتی است. بررسی سایر گزینه ها: 1) طبق شکل کتاب درسی، در اولین مرحله (تشکیل AMP)، گروه فسفات با کربنی از قند ریبوز در آدنوزین پیوند می دهد که این کربن در خارج از حلقه پنج ضلعی قند قرار گرفته است. 3) در همه مراحل تولید ATP، ترکیبی با دو حلقه آلی پنج ضلعی (یک حلقه مربوط به قند و یک حلقه مربوط به آدنین) مصرف می شود. این واکنش با مصرف AMP و فسفات و تشکیل ADP همراه است. تشکیل پیوند بین فسفاتی، نوعی واکنش سنتز آبدهی است و با آزاد شدن مولکول آب همراه است. 4) در اولین مرحله آدنوزین مصرف و AMP تولید می شود. هر دو مولکول دارای سه حلقه آلی هستند و همچنین فاقد پیوند بین فسفاتی می باشند. AMP کلا یه دونه فسفات داره؛ چه جوری پیوند بین فسفاتی داشته باشه؟!', '2026-02-05 17:20:29'),
(948, 965, 'گزینه&laquo;4&raquo; در بازه زمانی مطرح شده، شش مولکول سه کربنه (دوتا قند فسفاته سه کربنی، دوتا اسید سه کربنی دوفسفاته و دو عدد پیرووات) تولید می گردد؛ همچنین دو عدد مولکول NAD+ در قند کافت (در زمان تبدیل قند سه کربنی فسفاته به اسید سه کربنی) و دو عدد از این مولکول ها در زمان اکسایش پیرووات مصرف می شود. (در مجموع ۴ عدد) دقت کنید، سؤال گفته به دنبال مصرف فروکتوز فسفاته، پس باید واکنش اکسایش پیرووات را ۲ بار حساب کنیم! بررسی سایر گزینه ها: 1) در طول این فرایندها، دو عدد مولکول کربن دی اکسید در زمان اکسایش یافتن دو مولکول پیرووات تولید میگردد، اما دقت کنید تعداد مولکول های ADP مصرفی در این بازه زمانی ۴ عدد است؛ به عبارتی همراه با مصرف هر اسید سه کربنی دوفسفاته، دو عدد مولکول ADP مصرف می شود. 2) در این فرایندها، مولکول ADP مصرف می گردد، نه این که تولید شود! تولید ADP در نخستین مرحله قند کافت صورت می گیرد. 3) دقت کنید تعداد مولکولهای NADH تولیدی برابر ۴ عدد است. دوتا در زمان قند کافت و دو عدد در زمان اکسایش دو مولکول پیرووات در راکیزه!', '2026-02-05 17:20:29'),
(949, 966, 'گزینه&laquo;3&raquo; ترکیبات نوکلئوتیدی که در قندکافت نقش دارند شامل NAD ADP ATP و NADH می شود. ADP و ATP که در واکنش های اکسایش و کاهش شرکت نمی کنند. طی قند کافت هم NAD کاهش می یابد؛ یعنی با دریافت الکترون به NADH تبدیل می شود، یعنی این گزینه درباره هیچ مرحله ای از مراحل قند کافت! صادق نیست. بررسی سایر گزینه ها: 1) در مرحله نخست قندکافت، مولکول گلوکز با اتصال به گروه های فسفات به فروکتوز فسفاته تبدیل می شود. در مرحله سوم به یک انتهای قند فسفاته، گروه فسفات آزاد افزوده شده و به اسید دوفسفاته تبدیل می گردد. در مرحله چهارم نیز، به مولکول ADP، گروه فسفات افزوده می شود و ATP تولید می شود. در مرحله ۱، به دو انتهای نوعی ترکیب کربن دار، گروه فسفات افزوده می شود و در مراحل سوم و چهارم (دو مرحله)، به یک انتهای نوعی ترکیب آلی! یعنی در کل، طی ۳ مرحله. 2) در تمامی مراحل قند کافت، تولید و مصرف مولکول آلی فسفات دار قابل مشاهده است. دقت داشته باشید که در مراحل اول و چهارم نیز، مولکول های فسفات دار ATP و ADP مورد استفاده قرار می گیرند. 4) شکستن پیوند اشتراکی در مراحل اول(در مولکول ATP)، دوم (شکسته شدن فروکتوز فسفاته) و چهارم (جداشدن فسفات از اسید دوفسفاته) انجام می شود.', '2026-02-05 17:20:29'),
(950, 967, 'گزینه&laquo;1&raquo; منظور صورت سؤال، اندامک میتوکندری است. میتوکندری برای خودش دنا و رناتن دارد. در دنای راکیزه، ژن های مورد نیاز برای ساخته شدن انواعی (نه همه) از پروتئین های مورد نیاز تنفس یاخته ای وجود دارند که این پروتئین ها توسط رناتن های همین اندامک ساخته می شوند؛ یعنی رونویسی از این ژن ها و ترجمۀ رنای پیک حاصل در خود میتوکندری رخ می دهد، اما راکیزه برای انجام نقش خود در تنفس یاخته ای، به پروتئین هایی وابسته است که ژن های آن ها در هسته قرار دارند که این پروتئین ها، به وسیلۀ رناتن های آزاد درون ماده زمینه سیتوپلاسم ساخته می شوند و بعد به میتوکندری وارد می شوند. بررسی سایر گزینه ها: 2) آخرین پمپ غشایی یک زنجیره انتقال الکترون، در غشای چین خورده (داخلی) میتوکندری، الکترونها را به \\(O_2\\) منتقل و یون های اکسید تولید می کند. این یون ها، در ترکیب با پروتون هایی که در بخش داخلی راکیزه قرار دارند، مولکول های آب را تشکیل می دهند. 3) با توجه به شکل زنجیره انتقال الکترون در غشای داخلی میتوکندری (شکل ۸ فصل ۵ زیست دوازدهم)، پروتون ها (یون های \\(H^+\\)) در سه محل متفاوت (محل قرارگیری پمپ های پروتئینی) از یک زنجیره انتقال الکترون غشای درونی، از بخش داخلی میتوکندری به فضای بین دو غشای آن، پمپ می شوند. 4) در غشاهای یاخته ای، پروتئین های مختلفی وجود دارند که در انتقال فعال (جابه جایی برخلاف شیب غلظت) نقش دارند. این پروتئین ها، می توانند از منابع انرژی مختلفی استفاده کنند، مثل ATP؛ مثلا در غشای میتوکندری، پروتئینی وجود دارد که پیرووات را با انتقال فعال وارد میتوکندری می کند. این پروتئین از انرژی الکترون ها، برای این جابه جایی استفاده نمی کند.', '2026-02-05 17:20:29'),
(951, 968, 'گزینه&laquo;3&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) نادرست-\\(NADH\\) در فرایند گلیکولیز در مادۀ زمینه سیتوپلاسم تولید می شود و از آن جایی که در زنجیره مصرف می شود باید بتواند وارد میتوکندری شود که برای ورود به زنجیره انتقال الکترون، از هر دو غشای میتوکندری (چهار لایه فسفولیپیدی) عبور می کند. در مورد \\(FADH_2\\) نیز میتوان گفت، چون فقط در چرخه کربس تولید می شود و در خود میتوکندری نیز اکسایش می یابد از غشاهای میتوکندری عبور نمی کند. ب) درست ـ با اکسایش هر \\(NADH\\) و هر \\(FADH_2\\)، دو الکترون به اجزای غشای درونی میتوکندری آزاد می شود. الکترونهای \\(NADH\\) به جزء اول زنجیره وارد و تا انتهای آن جابه جا می شوند. الکترونهای \\(FADH_2\\) نیز به جزء دوم زنجیره وارد و از آن جا تا انتهای زنجیره جابه جا می شوند. ج) نادرست ـ یون اکسید در ترکیب با پروتون هایی که در بخش داخلی راکیزه قرار دارند، مولکول آب را تشکیل می دهد. با این اوصاف، برای تشکیل ،آب نیازی به دریافت مجدد الکترون توسط یون اکسید نیست! دقت کنید خود یون اکسید به دنبال دریافت الکترون های حاصل از اکسایش \\(NADH\\) و \\(FADH_2\\) توسط \\(O_2\\)تشکیل می شود. د) درست ـ با توجه به شکل زنجیره انتقال الکترون در فصل ۵ کتاب درسی زیست شناسی (۳)، مولکولهای \\(NADH\\) و \\(FADH_2\\) هنگام اکسایش، الکترون های خود را به ترتیب به اولین و دومین جزء زنجیره انتقال الکترون می دهند. اولین جزء ،زنجیره، نوعی پروتئین سراسری است که با تمام قسمت های هر دو لایه فسفولیپیدی غشای درونی میتوکندری تماس دارد؛ هم چنین دومین جزء این زنجیره، مولکول کوچکی است.', '2026-02-05 17:20:29'),
(952, 969, 'گزینه&laquo;4&raquo; فقط مورد &laquo;ب&raquo; به درستی بیان شده است. از بین مراحل کلی تنفس هوازی، قند کافت نخستین مرحله تنفس هوازی است و در ماده زمینه سیتوپلاسم انجام می شود. سایر مراحل آن در میتوکندری انجام می شوند. بررسی همه موارد: الف) تولید و مصرف مولکول شش کربنه در چرخه کربس صورت می گیرد، اما مثلن در اکسایش پیرووات و زنجیره انتقال الکترون خیر! ب) در مرحله اکسایش پیرووات فقط یک نوع حامل الکترون (\\(NADH\\)) و در چرخه کربس انواعی از حاملین الکترون (\\(NADH\\) و \\(FADH_2\\)) تولید می شوند. در سایر مراحل هم حامل الکترونی تولید نمی شود. در زنجیره انتقال الکترون، حامل های الکترونی مصرف میشوند. ج) تولید مولکول \\(CO_2\\) در دو مرحله اکسایش پیرووات و چرخه کربس دیده می شود. در اکسایش پیرووات، از پیرووات \\(CO_2\\) آزاد می شود و در چرخه کربس هم طی دو مرحله از ترکیبات شش کربنی و پنج کربنی، دی اکسید کربن آزاد می شود. د) در چرخه کربس و فعالیت آنزیم \\(ATP\\)ساز، با افزوده شدن فسفات به آدنوزین دی فسفات، مولکول \\(ATP\\) تولید می شود. در چرخه کربس، ساخت \\(ATP\\) به روش در سطح پیش ماده و در انتهای تنفس یاخته ای، از طریق اکسایشی است.', '2026-02-05 17:20:29'),
(953, 970, 'گزینه&laquo;1&raquo; دومین عضو زنجیره انتقال الکترون، فقط در مجاورت اسیدهای چرب فسفولیپیدهای غشایی قرار دارد، پس خیلی آب گریز است و به عنوان آب گریزترین عضو زنجیره انتقال الکترون شناخته می شود. این عضو مستقیمن الکترونهای \\(FADH_2\\) را دریافت می کند و باعث اکسایش آن می شود. مولکول های \\(FADH_2\\) برخلاف \\(NADH\\)، فقط به دنبال واکنش های چرخه کربس تولید می شوند. \\(NADH\\) طی قند کافت و اکسایش پیرووات هم، می تواند تولید شود. بررسی سایر گزینه ها: 2) آخرین پمپ پروتونی زنجیره انتقال الکترون، با انتقال الکترون ها به اکسیژن منجر به تولید یون اکسید می شود که این یون با دریافت \\(H^+\\)، سبب تولید آب در بخش داخلی میتوکندری می شود. از طرفی، آنزیم \\(ATP\\) ساز نیز، به دلیل تولید \\(ATP\\)، باعث تولید مولکول آب، در درون میتوکندری خواهد شد. می دانیم فرایند تولید ATP، نوعی واکنش سنتز آبد هی بوده و با تولید آب همراه است. 3) چهارمین عضو این زنجیره، پمپ پروتئینی سراسری نمی باشد و توانایی دریافت و از دست دادن الکترون را دارد، اما این مولکول، توانایی جابه جایی یون های هیدروژن در خلاف جهت شیب غلظت را ندارد. 4) طبق شکل کتاب درسی، بخش برجسته آنزیم \\(ATP\\)ساز در بخش داخلی راکیزه قرار دارد، اما دقت داشته باشید که مجموعه آنزیمی \\(ATP\\) ساز، در خارج از زنجیره انتقال الکترون قرار دارد! این مجموعه، یون های هیدروژن را از فضای بین دو غشای راکیزه، با روش انتشار تسهیل شده به بخش داخلی راکیزه منتقل می کند و با استفاده از انرژی حاصل از جابه جایی این یون ها، با متصل کردن فسفات به \\(ADP\\) سبب تولید \\(ATP\\) در بخش داخلی راکیزه خواهد شد.', '2026-02-05 17:20:29'),
(954, 971, 'گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) هم در قند کافت و هم در چرخه کربس مولکول های دوفسفاته مصرف می شوند، مثل ADP یا \\(NAD^+\\) چرخه کربس در راکیزه رخ می دهد و قند کافت در ماده زمینه ای سیتوپلاسم رخ می دهد. ب) چرخه کربس برای شروع شدن، به استیل کوآنزیم \\(A\\) نیاز دارد و برای تشکیل این مولکول هم پیرووات لازم است که در انتهای قندکافت تولید می شود. پیرووات با انتقال فعال به راکیزه وارد می شود، یعنی با کمک پروتئین های غشایی راکیزه. هم چنین برای انجام شدن قند کافت و واکنش های چرخه کربس به \\(NAD^+\\) و یا \\(FAD\\) نیز نیاز است. این ترکیبات می توانند در پی وقوع زنجیره انتقال الکترون (اکسایش \\(NADH\\) و \\(FADH_2\\) به دنبال فعالیت اجزای غشای راکیزه) تولید شوند. در چرخه کربس مولکولی شش کربنی مصرف می شود و طی آن \\(NADH\\) هم تولید می شود. در قند کافت نیز قند شش کربنی (گلوکز یا فروکتوز فسفاته) مصرف می شود و در طی آن \\(NADH\\) تولید می شود. ج) در چرخه کربس انواعی از حامل های الکترونی تولید می شود (\\(FADH_2\\) و \\(NADH\\)). تولید این حامل های الکترون، نیازمند فعالیت آنزیم های متفاوت است (چراکه آنزیم ها عملکرد اختصاصی دارند و آنزیمی که \\(NADH\\) می سازد، نمی تواند \\(FADH_2\\) بسازد)، اما در قند کافت فقط \\(NADH\\) تولید می شود، پس نیازمند یک نوع آنزیم برای تولید آن می باشیم. چرخه کربس به دلیل تولید تعداد و انواع حامل های الکترونی بیشتر سهم بیشتری در تولید \\(ATP\\) طی تنفس یاخته ای دارد، چراکه این حامل های الکترونی طی زنجیره انتقال الکترون، اکسایش می یابند و از انرژی حاصل از انتقال الکترون هایشان، شیب \\(H^+\\) ایجاد می شود که در تولید \\(ATP\\) نقش دارد؛ اصلن هدف از واکنش هایی از تنفس یاخته ای که در راکیزه رخ می دهند، تولید \\(ATP\\) بیشتر در یاخته است. د( هم در قند کافت و هم در چرخه کربس، تعداد اتم های کربن نوعی واکنش دهنده کاهش پیدا می کند. در قندکافت، فروکتوز فسفاته که شش کربن دارد به دو قند سه کربنی می شکند. در کربس هم ترکیب شش کربنی به پنج کربنی و پنج کربنی هم به چهار کربنی تبدیل می شود. در انتهای قندکافت \\(ATP\\) تولید می شود که در مرحله اول قند کافت مصرف می شود؛ هم چنین در چرخه کربس هم مولکول اولیه (ترکیب چهار کربنی) بازسازی می شود.', '2026-02-05 17:20:29'),
(955, 972, 'گزینه&laquo;3&raquo; بخش های ۱ تا ۴ به ترتیب عبارت اند از: پیرووات، کربن دی اکسید، \\(NAD^+\\) و \\(NADH\\). \\(NAD^+\\)مولکولی دونوکلئوتیدی است که با دریافت الکترون و پروتون به حامل الکترون تبدیل می شود. دقت کنید \\(NAD^+\\) اکسایش نمی یابد (الکترون از دست نمی دهد)، بلکه کاهش می یابد.\\(NADH\\) توان اکسایش دارد. بررسی سایر گزینه ها: 1) در یاخته های یوکاریوتی، اکسایش پیرووات در راکیزه انجام می شود، پس پیرووات تولید شده در قندکافت، برای وارد شدن به راکیزه باید از غشاهای آن عبور کند. 2) تشکیل بی کربنات و اوره در بدن انسان وابسته به مصرف \\( CO_2\\) است که طی این واکنش ها، کربن دی اکسید می تواند به ترتیب، به جایگاه اتصال خود در آنزیم کربنیک انیدراز و آنزیمی که در کبد آمونیاک و \\( CO_2\\) را ترکیب می کند، متصل شود؛ این جایگاه اتصال، همان جایگاه فعال آنزیم است. 4) الکترون های مولکول \\(NADH\\) باعث فعالیت پمپ های زنجیره انتقال الکترون می شوند. در نتیجه فعالیت این زنجیره، پروتون ها در فضای بین دو غشای راکیزه تجمع می یابند که به دلیل شیب غلظتی \\(H\\)، تمایل دارند به بخش داخلی راکیزه برگردند که این واقعه از طریق انتشار تسهیل شده رخ می دهد. در زمان ورود این پروتون ها از این فضا به بخش داخلی، از طریق کانال آنزیم \\(ATP \\)ساز، انرژی لازم برای تشکیل پیوند فسفات - فسفات توسط آنزیم فراهم می شود و مولکول \\(ATP \\) تشکیل می شود.', '2026-02-05 17:20:29'),
(956, 973, 'گزینه&laquo;1&raquo; طبق متن کتاب، یاخته های بدن ما به طور معمول از گلوکز و ذخیره قندی کبد (گلیکوژن) برای تأمین انرژی استفاده می کنند. در صورتی که این منابع کافی نباشند، آن ها برای تولید ATP به سراغ تجزیه چربی ها و پروتئین ها می روند. گوارش شیمیایی هر دو گروه مولکول های زیستی، در روده باریک (بخش لوله ای شکل دستگاه گوارش) تکمیل می شود. بررسی سایر گزینه ها: 2) تجزیه پروتئین ها منجر به تحلیل و ضعیف شدن ماهیچه ها و هم چنین تضعیف سیستم ایمنی میشود؛ لذا علایم بیماری های خودایمنی کاهش پیدا می کند، چون این بیماری ها در نتیجه فعالیت سیستم ایمنی رخ می دهند. این مورد ارتباطی به تجزیه چربی ها ندارد. 3) میزان تولید \\(ATP \\) به ازای تجزیه کامل یک مولکول گلوکز در بهترین شرایط در یک یاخته یوکاریوتی، حداکثر ۳۰ مولکول \\(ATP \\) است. این موضوع درباره چربی ها و پروتئین ها صادق نیست. 4) طبق فصل ۱ زیست دهم، شبکه آندوپلاسمی در ساخت این مولکول های زیستی نقش دارد. شبکه آندوپلاسمی زبر در ساخت پروتئین ها و شبکه آندوپلاسمی صاف در ساخت چربی ها مؤثر است. دقت کنید همۀ پروتئین های یاخته، توسط شبکه آندوپلاسمی زیر ساخته نمی شوند فقط گروهی از آن ها مثل ترشحی ها توسط این شبکه ساخته می شوند. گروهی دیگر از پروتئین ها توسط ریبوزوم های آزاد در سیتوپلاسم ساخته می شوند، مثل آنزیم های درون یاخته ای! که درون هسته (به عنوان مثال) فعالیت میکنند.', '2026-02-05 17:20:29'),
(957, 974, 'گزینه&laquo;2&raquo; منظور صورت سؤال، فرایند قندکافت در تارهای ماهیچه ای تند است. پیرووات، ترکیب آلی بدون فسفاتی است که در قندکافت، تولید می شود. طبق شکل کتاب درسی، پیرووات در پی مصرف اسید دوفسفاته (ترکیب غیر نوکلئوتیدی و فسفاته) ایجاد می شود. بررسی سایر گزینه ها: 1) ترکیبات آلی نیتروژن داری که در قندکافت مصرف می شوند شامل \\(ATP \\)\\(NAD^+\\) و \\(ADP\\) است. هم زمان با مصرف \\(ATP \\)، فروکتوز فسفاته (ترکیب شش کربنی دوفسفاته) و هم زمان با مصرف \\(NAD^+\\) ، ترکیب اسید سه کربنی دوفسفاته و \\(NADH\\) دوفسفاته تولید می شود، اما دقت کنید که در آخرین واکنش گلیکولیز که \\(ADP\\) مصرف می شود، هیچ مولکول دوفسفاته ای تولید نخواهد شد و تنها مولکول های سه فسفاته (\\(ATP \\)) و مولکول های بدون فسفات (پیرووات) تولید می شود. 3) منظور از مصرف قند دوفسفاته، مصرف فروکتوز فسفاته است. در گلیکولیز، با مصرف فروکتوز فسفاته، قندهای سه کربنی فسفاته تولید می شود، نه \\(ATP \\)، تولید \\(ATP \\) در قندکافت به دنبال مصرف اسید دوفسفاته و در مراحل انتهایی آن رخ می دهد. 4) ترکیبات شیمیایی با دو گروه فسفات که در قندکافت تولید می شوند شامل \\(ADP\\)، فروکتوز فسفاته، اسید سه کربنی دوفسفاته و \\(NADH\\) است. در این بین فقط هم زمان با تشکیل اسید سه کربنی دوفسفاته (و\\(NADH\\))، تعدادی الکترون با کاهش تولید \\( NADH^+\\) سبب تولید می شوند.', '2026-02-05 17:20:29'),
(958, 975, 'گزینه&laquo;1&raquo; طبق متن کتاب، هر دو نوع تخمیر الکلی و لاکتیکی در گیاهان قابل انجام هستند. در هر دو نوع تخمیر، تولید مولکول های \\(ATP \\) فقط طی قندکافت (نخستین مرحله) صورت می گیرد. می دانید که در قندکافت، در انتها ۴ مولکول \\(ATP \\) تولید می شود، اما چون در واکنش ابتدایی آن، ۲ مولکول \\(ATP \\) مصرف می شود، طی این فرایند به طور خالص ۲ مولکول \\(ATP \\) تولید می شود. بررسی سایر گزینه ها: 2) در هر دو نوع تخمیر فقط یک نوع حامل الکترون (\\(NADH\\)) تولید و مصرف می شود. ۳) در تخمیر الکلی، الکترون های \\(NADH\\) به طور مستقیم به مولکول اتانال منتقل می شوند. ۴) طبق متن کتاب، تخمیر در محیط کم اکسیژن و یا بدون اکسیژن انجام می شود. هم چنین یاخته هایی مانند گویچه های قرمز بالغ در انسان، حتی در شرایطی که اکسیژن اطرافشان کافی باشد نیز تخمیر انجام می دهند، زیرا فاقد میتوکندری اند. (تنفس هوازی در آنها رخ نمی دهد.)', '2026-02-05 17:20:29'),
(959, 976, 'گزینه&laquo;3&raquo; در تخمیر الکلی، طی مرحله قندکافت، \\(NAD^+\\) با دریافت الکترون از قند فسفاته، کاهش می یابد و به NADH تبدیل می شود. طی مرحله اکسایش پیرووات هم، NADH تشکیل می شود که در این جا هم \\(NAD^+\\) از ماده آلی، الکترون می گیرد. بررسی سایر گزینه ها: 1) در تخمیر الکلی برخلاف تنفس هوازی، مولکول های پیرووات، اتانال و اتانول (انواعی از مولکول های آلی بدون فسفات) در ماده زمینه ای سیتوپلاسم تشکیل می شوند؛ اما در تنفس هوازی در یک یاخته گیاهی، طی قندکافت، فقط پیرووات را به عنوان ماده آلی بدون فسفات تولید شده در ماده زمینه ای سیتوپلاسم میشناسیم. سایر مراحل تنفس یاخته ای هم، در راکیزه رخ می دهند. 2) این مورد در خصوص تخمیر لاکتیکی برخلاف تخمیر الکلی صادق است. در تخمیر الکلی، پیرووات ابتدا یک مولکول کربن دی اکسید خود را از دست خواهد داد و اتانال با \\(NADH\\) مبادله الکترون انجام می دهد. 4) اتانال و اتانول، ترکیب های دوکربنی هستند که در فرایند تخمیر الکلی در ماده زمینه ای سیتوپلاسم ساخته می شوند. به دنبال مصرف اتانال، اتانول و \\(NAD^+\\) تولید می شود یعنی \\(ATP \\) بیشتری در یاخته ساخته نمی شود. اتانول هم باید از یاخته دور شود چراکه ماده سمی است و مصرف نمی شود. بنیان استیل، در فرایند اکسایش پیرووات در بخش داخلی میتوکندری یاخته گیاهی تولید می گردد و در ادامه وارد چرخه کربس می شود (به شکل استیل کوآنزیم A). این فرایندها منجر به تولید \\(ATP \\) بیشتر در یاخته می شوند.', '2026-02-05 17:20:29'),
(960, 977, 'گزینه&laquo;1&raquo; مولکولی که مستقیمن نوعی پمپ پروتئینی در غشای داخلی راکیزه را کاهش می دهد، \\(NADH\\) است که در تخمیر نیز الکترون از دست می دهد و اکسایش می یابد. دقت کنید \\(FADH_2\\) سبب کاهش یافتن جزئی از زنجیره می شود که پمپ پروتئینی نیست. بررسی سایر گزینه ها: 2) برای پیرووات و گروهی از ترکیبات شرکت کننده در کربس صادق است؛ این ترکیبات با از دست دادن کربن دی اکسید، به ترکیبی با تعداد کربن کم تر تبدیل می شوند. 3) برای پیرووات که از تغییر اسید سه کربنی دوفسفاته تولید می شود. صادق است، ولی مثلا برای \\(FADH_2\\) صادق نیست. 4) این مورد درباره ترکیباتی مثل \\(FADH_2\\) و \\(NADH\\) صادق است که هنگام تشکیل آن ها، \\(FAD\\) و \\(NAD^+\\)، علاوه بر الکترون، پروتون نیز دریافت می کنند.', '2026-02-05 17:20:29'),
(961, 978, 'گزینه&laquo;4&raquo; تخمیر الکلی سبب ورآمدن خمیر نان می شود و از تخمیر لاکتیکی برای تولید محصولات لبنی استفاده می شود. در تخمیر الکلی، نوعی ترکیب آلی دوکربنه (اتانال) تولید و سپس مصرف می شود، اما در تخمیر لاکتیکی ترکیب دوکربنه ای تولید یا مصرف نمی شود. بررسی سایر گزینه ها: 1) پارانشیم هوادار سبب تأمین اکسیژن برای یاخته های گیاهان می شود، به عبارتی به علت توانایی ذخیره اکسیژن در گیاه توسط این بافت، احتمال وقوع هر دو نوع تخمیر در گیاهان آبزی کاهش می یابد. 2) در تخمیر الکلی برخلاف تخمیر لاکتیکی، کربن دی اکسید تولید می شود؛ اما دقت کنید که هر دو نوع تخمیر در ماده زمینه سیتوپلاسم انجام می شوند، نه راکیزه. 3) در تخمیر الکلی ضمن کاهش ترکیبی دو کربنه (اتانال)، \\(NAD^+\\) بازتولید می شود. این مورد ویژگی تخمیر لاکتیکی است.', '2026-02-05 17:20:29'),
(962, 979, 'گزینه&laquo;1&raquo; صورت سؤال فرایندهایی از تنفس هوازی از زمان مصرف فروکتوز فسفاته تا انتهای قندکافت و هم چنین فرایند اکسایش پیرووات را شامل می شود. می دانیم که طی واکنش های سنتز آب دهی، مولکول آب تولید می شود. در این فاصله، به عنوان مثال، در آخرین مرحله قندکافت، \\(ATP\\) تولید می شود؛ که تولید \\(ATP\\) با تولید آب همراه است. هم چنین در مرحله سوم قندکافت (یعنی قبل از تولید \\(ATP\\)) تولید می شود؛ دقت کنید طی اکسایش پیرووات هم، \\(NADH\\) تولید می شود که بعد از آن، استیل کوآنزیم \\(A\\) به دنبال نوعی واکنش سنتز آب دهی، تولید می شود. بررسی سایر گزینه ها: 2) در بازه زمانی ذکر شده، آخرین \\(NAD^+\\) در فرایند اکسایش پیرووات مصرف می شود و مطابق شکل کتاب درسی، این مورد پس از آزاد شدن \\(CO_2\\) در فرایند اکسایش پیرووات صورت می گیرد. 3) مصرف فسفات آزاد در مرحله سوم قندکافت و همراه با مصرف قند فسفاته در این فرایند، صورت می گیرد. به عبارتی این فسفات آزاد، به قند فسفاته متصل می شود و اسید دوفسفاته را می سازد. 4) تولید اسید دوفسفاته پیش از مصرف \\(ADP\\) (تولید \\(ATP\\)) و در مرحله سوم قند کافت انجام می شود.', '2026-02-05 17:20:29');
INSERT INTO `descriptive_answers_tam24` (`id`, `question_id`, `answer_text`, `created_at`) VALUES
(963, 980, 'گزینه&laquo;4&raquo; NADH نوعی مولکول حامل الکترون است که انرژی نیز دارد؛ این مولکول طی قندکافت و در مرحله سوم آن تشکیل می شود، به عبارتی نمی تواند همراه با تولید پیرووات تشکیل شود. الکترون های پرانرژی خروجی از NADH (به دنبال اکسایش یافتن آن طی تنفس یاخته ای) مستقیمن به نوعی پمپ پروتون (نه پمپ الکترون) در غشای داخلی راکیزه منتقل میشوند. بررسی سایر گزینه ها: 1) تولید NADH در گلیکولیز، در مرحله سوم رخ می دهد. در مرحله چهارم و پس از تولید NADH، هر اسید سه کربنی دوفسفاته در طی دو مرحله، فسفات های خود را به دو مولکول ADP می دهد و تبدیل به پیرووات می شود. 2) در اکسایش پیرووات ابتدا با شکسته شدن پیوند کربن - کربن در مولکول پیرووات، یک اتم کربن به صورت مولکول کربن دی اکسید از ساختار پیرووات خارج شده و سپس، مولکول NADH تولید می گردد. در ادامه، با اتصال کوآنزیم A به مولکول دوکربنی استیل (که در واکنش قبلی تشکیل شده است) مولکول استیل کوآنزیم A ایجاد می شود. 3) در اثر اکسایش NADH، دو الکترون و دو یون هیدروژن (پروتون) در بخش داخلی راکیزه تولید می شود.', '2026-02-05 17:20:29'),
(964, 981, 'گزینه&laquo;2&raquo; در صورت کمبود یا نبود \\(O_2\\) در یاخته ماهیچه ای، این یاخته می رود سراغ تخمیر لاکتیکی که طی آن، در نهایت لاکتیک اسید تولید می شود. لاکتیک اسید در واقع فراورده نهایی ناشی از تخمیر لاکتیکی و تجزیه مستقل از اکسیژن گلوکز است؛ تجمع لاکتیک اسید در ماهیچه ها، موجب تحریک گیرنده های درد (فاقد پوشش پیوندی) در عضله اسکلتی می شود. بررسی سایر گزینه ها: 1) به طور کلی چه در حالت انقباض ماهیچه و چه در حالتی که ماهیچه در حالت استراحت به سر می برد، یاخته های ماهیچه اسکلتی، همواره برای فعالیت خود، در حال مصرف \\(ATP\\) می باشند. پس چه زمانی که گلوکز به صورت هوازی و یا تخمیری تجزیه می شود و چه زمانی که اسید چرب (در حالت انقباض های طولانی) مصرف می شود؛ یاخته در نهایت \\(ATP\\) تولید می کند و آن را مصرف می کند. به عبارتی این مواد مغذی طی واکنش هایی در یاخته تبدیل به \\(ATP\\) می شوند و این \\(ATP\\) به عنوان شکل رایج انرژی در یاخته مصرف می شود. 3) ماده فسفات داری که در عضلات اسکلتی به عنوان منبع انرژی مصرف می شود، می تواند \\(ATP\\) یا مثلا کراتین فسفات (\\(CP\\)) باشد، اما به طور کلی مصرف \\(ATP\\) در هر حالتی در حال انجام است و مصرف کراتین فسفات نیز ارتباطی با فعالیت شدید ماهیچه ندارد!. 4) دقت کنید مطابق سؤال کنکور سراسری ۱۴۰۱ تیرماه، ممکن است تار ماهیچه ای، اسید چرب را طی تنفس هوازی مصرف کند و در پی مصرف آن \\(FADH_2\\) و \\(NADH\\) تولید کند.', '2026-02-05 17:20:29'),
(965, 982, 'گزینه&laquo;4&raquo; خوردن میوه ها و سبزیجات در حفظ سلامت بدن نقش دارند. این مواد غذایی دارای پاداکسنده هایی مانند کاروتنوئیدها هستند. پاداکسنده ها در واکنش با رادیکال های آزاد، کمبود الکترونی آن ها را جبران می کنند، به عبارتی خودشان فداکاری میکنند و الکترون از دست می دهند و این الکترون به رادیکال آزاد می رسد و دیگر کمبود الکترونی نخواهد داشت، پس این گونه مانع از اثر تخریبی آن ها بر مولکول های زیستی و در نتیجه تخریب بافت های بدن می شوند. در واقع فعالیت پاداکسنده ها ارتباطی به تولید یا عدم تولید یون اکسید ندارد. در صورت استفاده از پاداکسنده، هم چنان یون اکسید و حتی رادیکال آزاد تولید می شود، اما این رادیکال ها، بیشتر از قبل، خنثی می شوند. بررسی سایر گزینه ها: 1) نقص در ژن های پروتئین های زنجیره انتقال الکترون می تواند منجر به تولید پروتئین های معیوب شود. راکیزه ای که این پروتئین های معیوب را داشته باشد در مبارزه با رادیکالهای آزاد عملکرد مناسبی ندارد؛ در نتیجه میزان تجمع رادیکالهای آزاد در یاخته افزایش می یابد. رادیکالهای آزاد باعث آسیب به دنای یاخته (جهش) می شوند. این آسیب می تواند در نتیجه دریافت الکترون توسط رادیکال آزاد از دنای یاخته باشد. 2) گاز کربن مونواکسید علاوه بر کاهش ظرفیت حمل اکسیژن در خون (به علت اتصال به جایگاه \\(O_2\\) در هموگلوبین)، سبب توقف واکنش مربوط به انتقال الکترون ها به اکسیژن نیز می شود. سیانید نیز با مهار واکنش نهایی مربوط به انتقال الکترون ها به \\(O_2\\) می تواند زنجیره انتقال الکترون را مهار کند (مختل کردن پمپ سوم زنجیره). در نتیجه هر دو ماده با متوقف کردن زنجیره انتقال الکترون، تولید یون اکسید را کاهش می دهند. وجود این یون هم برای تشکیل آب، ضروری است پس تولید آب در راکیزه مختل می شود. 3) محصول نهایی تخمیر الکلی، الکل (اتانول) است. مطالعات نشان می دهد که الکل سرعت تشکیل رادیکال های آزاد از اکسیژن را افزایش می دهد و مانع از عملکرد راکیزه در جهت کاهش آن ها می شود.', '2026-02-05 17:20:29'),
(966, 983, 'گزینه&laquo;1&raquo; در تخمیر لاکتیکی، حین تبدیل قندهای سه کربنی تک فسفاته به اسیدهای سه کربنی دوفسفاته، اسیدهای سه کربنی دوفسفاته به پیرووات و مولکول پیرووات به لاکتیک اسید (مجموعن سه واکنش)، تغییری در تعداد اتم های کربن ایجاد نمی شود. حتمن به یاد دارید که تخمیر لاکتیکی با قندکافت شروع می شد، اما در تخمیر الکلی و تنفس هوازی، تنها دو واکنش اول که مربوط به گلیکولیز است، قابل مشاهده است و بعد از آن پیرووات به ترکیبی با تعداد اتم های کربن کم تر تبدیل می شود. در تمامی مراحل مربوط به این نوع روش تأمین انرژی در یاخته، (مراحل گلیکولیز و مرحله کاهش پیرووات)، ترکیب(های) آلی فسفات دار هم تولید و هم مصرف می شوند !مثلا در زمان کاهش یافتن پیرووات، \\(NAD^+\\) تولید شده و \\(NADH\\) مصرف می شود که هر دو فسفات دارند. بررسی سایر گزینه ها: ۲) محصول نهایی در تخمیر لاکتیکی، لاکتات است که تعداد کربن برابری با پیرووات دارد. ۳) در مرحله انتهایی قندکافت، \\(ATP\\) تولید می شود که فقط در یاخته های زنده رخ می دهد، در حالی که جانداران، یاخته های مرده هم دارند مثل آوندهای چوبی گیاهان یا اپیدرم پوست در انسان! 4) در طی تخمیر لاکتیکی، برای بازسازی \\(NAD^+\\)، پیرووات کاهش پیدا می کند؛ نه اکسایش!', '2026-02-05 17:20:29'),
(967, 984, 'گزینه&laquo;2&raquo; موارد دوم و سوم درست هستند. مورد اول: در تخمیر لاکتیکی، تبدیل پیرووات به لاکتات با کاهش یافتن پیرووات (دریافت الکترون توسط پیرووات) همراه است. این فرایند اکسایش محسوب نمی شود. مورد دوم: تبدیل پیرووات به بنیان استیل در فرایند اکسایش پیرووات انجام می شود و با تولید \\(NADH\\) همراه است. یاخته های شش ریشه درخت حرا دارای تنفس هوازی هستند. مورد سوم: گویچه های قرمز انسان فقط توانایی انجام تخمیر لاکتیکی را دارند و در این فرایند ابتدا قندکافت (نخستین مرحله تنفس یاخته ای) رخ می دهد، طی قندکافت، در مرحله تبدیل قند فسفاته به اسید دوفسفاته، \\(NADH\\) نیز تولید می شود. \\(NADH\\) به دنبال دریافت الکترون ها توسط \\(NAD^+\\) (کاهش این مولکول) تشکیل می شود، پس مولکولی باید اکسایش یافته باشد تا الکترون های لازم را تأمین کند و آن ماده کسی نیست جز قند فسفاته! مورد چهارم: رادیکالهای آزاد، مولکول هایی با الکترون های جفت نشده هستند یعنی کمبود الکترون دارند و در واکنش با پاداکسنده ها (مثل کاروتنوئیدها)، کمبود الکترون خود را با دریافت الکترون از این مولکول ها جبران میکنند، در واقع کاهش می یابند و پاداکسنده ها، اکسایش می یابند.', '2026-02-05 17:20:29'),
(968, 985, 'گزینه&laquo;3&raquo; در یاخته های بدن انسان، تنفس یاخته ای هوازی و تخمیر لاکتیکی صورت می گیرد، که هر دو، با تجزیه گلوکز همراه است. طی قند کافت که در هر دو فرایند مشترک است، تجزیه گلوکز به دنبال مصرف مولکول \\(ATP\\) در نخستین مرحله قند کافت مشاهده می شود. پذیرنده نهایی الکترون در تنفس هوازی، مولکول اکسیژن (\\(O_2\\)) و در تخمیر لاکتیکی، مولکول پیرووات می باشد. اکسیژن با گرفتن الکترون به یون اکسید (اتم اکسیژن با دو بار منفی) تبدیل می شود. در تخمیر لاکتیکی، پیرووات با دریافت الکترون، به لاکتات (نوعی ترکیب یونی با بار منفی) تبدیل می شود. (ترکیب یونی بودن و بار منفی داشتن لاکتات با توجه به شکل ۱۱ فصل ۵ زیست دوازدهم قابل استنباط است، همچنین می دانیم لاکتات بنیان اسید لاکتیک است که یون هیدروژن خود را از دست داده است.) بررسی سایر گزینه ها: 1) در ساختار مولکول اکسیژن، فقط عنصر \\(O\\) (اکسیژن) شرکت دارد؛ در صورتی که در ساختار پیرووات، عناصر ،\\(C\\)\\(H\\) و \\(O\\) حضور دارند. 2) در مرحله نهایی قند کافت، پیرووات تولید می شود، قند کافت هم در تنفس یاخته ای رخ می دهد و هم در تخمیر لاکتیکی! در طی قند کافت، اکسیژن نه تولید و نه مصرف می گردد. 4) مولکول اکسیژن برای ورود به میتوکندری، از طریق انتشار ساده از غشاهای خارجی و داخلی میتوکندری عبور می کند؛ اما دقت کنید مولکول پیرووات از طریق انتقال فعال وارد راکیزه می شود و در آنجا اکسایش می یابد.', '2026-02-05 17:20:29'),
(969, 986, 'گزینه&laquo;3&raquo; موارد دوم سوم و چهارم به درستی بیان شده است. بررسی همه موارد: مورد اول: نادرست؛ سیانید با قرار گرفتن در جایگاه فعال آنزیم (پمپ سوم زنجیره انتقال الکترون )، مانع فعالیت آن می شود. کربن مونواکسید هم می تواند مانند سیانید فعالیت این پمپ را مختل کند و مانع رسیدن الکترون ها به اکسیژن شود. اما دقت کنید کربن مونواکسید با اتصال به هموگلوبین، مانع اتصال \\(O_2\\) به آن نیز می شود، چراکه جایگاه اتصال \\(O_2\\) و کربن مونواکسید در هموگلوبین، یکسان است در نتیجه ظرفیت حمل اکسیژن در خون را نیز کاهش می دهد که به دنبال آن تنفس یاخته ای را مختل می کند هموگلوبین، نوعی آنزیم نیست! مورد دوم درست؛ سیانید همانند \\(CO\\)، واکنش مربوط به انتقال الکترون ها به \\(O_2\\) را مهار و در نتیجه باعث توقف زنجیره انتقال الکترون می شود. سیانید و مونواکسید کربن به طور مستقیم فعالیت پمپ سوم زنجیره را مختل می کنند، اما به دنبال این اختلال، در ادامه سایر بخش های زنجیره و تنفس یاخته ای نیز مختل می شود و در نهایت به دلیل توقف واکنش های تنفس هوازی، یاخته می میرد. مورد سوم: درست؛ طبق متن کتاب درسی، هر دو ماده میت وانند واکنش مربوط به انتقال الکترون ها به \\(O_2\\) را مهار کنند. مورد چهارم: درست؛ دقت کنید هر دو ماده در توقف زنجیره انتقال الکترون در راکیزه نقش دارند؛ پس در نهایت از ساخت اکسایشی مولکول های \\(ATP\\) توسط آنزیم \\(ATP\\) ساز نیز ممانعت به عمل می آورند. فعالیت آنزیم \\(ATP\\) ساز وابسته به شیب غلظت \\(H^+\\) است که در نتیجه فعالیت پمپ های پروتئینی زنجیره ایجاد می شود، پس وقتی شیب \\(H^+\\) نباشد، این آنزیم هم کار نمی کند و تولید اکسایشی \\(ATP\\) هم متوقف می شود.', '2026-02-05 17:20:29'),
(970, 987, 'گزینه&laquo;1&raquo; همه یاخته های مذکور، یاخته هایی زنده و فعال و دارای تنفس هوازی و(اجد میتوکندری) هستند؛ بنابراین با انجام قند کافت، اکسایش پیرووات و چرخۀ کربس، مولکول گلوکز را تا تشکیل مولکول های \\(CO_2\\) تجزیه می کنند. بررسی سایر گزینه ها: ۲) اولین مولکولی که در واکنش های تنفس یاخته ای (طی گلیکولیز)، دچار اکسایش می شود، نوعی قند سه کربنی (قند فسفاته) است که الکترون خود را به مولکول \\(NAD^+\\) می دهد و سبب ایجاد حامل الکترون (\\(NADH\\)) و مولکول اسید دوفسفاته می شود؛ پس این مورد درباره هیچ یک از این یاخته ها صادق نیست. ۳) همۀ یاخته های زنده و دارای سوخت و ساز، در طی مرحله نخست تنفس یاخته ای (قند کافت)، \\(ATP\\) را در سطح پیش ماده تولید می کنند. اما دقت کنید که در صورت داشتن تنفس هوازی در یاخته، تولید \\(ATP\\) به صورت اکسایشی (استفاده از فسفات آزاد) هم صورت م یگیرد. بنابراین می توان گفت که در همۀ یاخته های مورد سؤال، تنها بخشی از \\(ATP\\) مورد نیاز یاخته، از طریق برداشته شدن گروه فسفات از یک ترکیب فسفات دار (در سطح پیش ماده) تولید می شود. 4) به منظور ساخت اکسایشی \\(ATP\\) در میتوکندری های یاخته های مذکور، علاوه بر اجزای زنجیره انتقال الکترون، پروتئین \\(ATP\\) ساز نیز فعالیت می کند که از اجزای سازنده زنجیره محسوب نمی شود. اجزای زنجیره انتقال الکترون، با فعالیت خود شیب \\(H^+\\) لازم برای فعالیت آنزیم \\(ATP\\) ساز را فراهم می کنند.', '2026-02-05 17:20:29'),
(1065, 1066, 'با استفاده از فرمول $v = (F × t) / m$ داریم:\r\n\r\n$v = (6 × 4) / 2 = 12 m/s$\r\n\r\nپس گزینه 3 صحیح است.', '2026-02-09 19:05:58'),
(1066, 1065, 'گزینه&laquo;3&raquo; علاوه بر باکتری های شیمیوسنتز کننده که در نبود نور، واکنش های اکسایش و کاهش را انجام می دهند، او گلنا نیز می تواند در نبود نور این واکنش ها را انجام دهد؛ مثلا طی چرخه کربس یا زنجیره انتقال الکترون میتوکندری. اوگلنا یوکاریوت است که در هسته و میتوکندری های خود توان همانندسازی دنا را دارد. بررسی سایر گزینه ها: 1) سیانوباکتری ها هم تثبیت کننده کربن هستند و هم تثبیت کننده نیتروژن. این جانداران کلروفیل aدارند. باکتریوکلروفیل مربوط به باکتری های گوگردی است. 2) طی چرخۀ کربس، کربن دی اکسید آزاد می شود. او گلنا نوعی جاندار یوکاریوتی است که چرخه کربس هم انجام می دهد. این جاندار در صورت نبود نور در محیط، می تواند از مواد آلی تغذیه کند و فتوسنتز انجام نمی دهد. سیانوباکتری های همزیست هم، می توانند از مواد آلی جاندار دیگر (فتوسنتز کننده) استفاده کنند. 4) در فتوسنتز کننده های اکسیژن را (مثل گیاهان و سیانوباکتری ها)، از آب به عنوان منبع الکترون استفاده می شود؛ الکترون های حاصل از تجزیه آب در نهایت به \\(NADP^+\\)پذیرندۀ الکترون منتقل میشوند و \\(NADPH\\)(حامل الکترون و منبع الکترون کالوین) تولید می شود.', '2026-02-09 19:07:44'),
(1074, 1059, 'گزینه&laquo;3&raquo; مطابق شکل ۱۳ کتاب درسی در فصل ۷ زیست دوازدهم، در ساختار فعال مولکول انسولین، دو گروه کربوکسیل و دو گروه آمین مشاهده می شود. همچنین میوزین پروتئینی دورشته ای و دارای ساختار چهارم است؛ لذا در ساختار نهایی خود بیش از یک گروه کربوکسیل آزاد دارد زیرا می دانیم که هر زنجیره پلی پپتیدی دارای یک انتهای آمینی آزاد و یک انتهای کربوکسیلی آزاد است. بررسی سایر گزینه ها: 1) زیر واحدهای هموگلوبین در ساختار دوم فقط ساختار مارپیچی پیدا می کنند و ساختار صفحه ای ندارند. 2) همه گروه هایR آمینواسیدهای آب گریز (نه هر آمینواسیدی)! در ساختار سوم به هم نزدیک می شوند تا در معرض آب نباشند. آمینواسیدها می توانند گروه های R با خاصیت متفاوت داشته باشند، آب گریزها در بخش های داخلی پروتئین قرار می گیرند و آبدوست ها در بخش های خارجی. 4) در ساختار دوم پروتئین، پیوندهای هیدروژنی بین اتم اکسیژن گروه CO و اتم هیدروژن گروه NH آمینواسیدهای غیرمجاور تشکیل می شود. اتم N گروه آمین در پیوندهای پپتیدی شرکت می کند.', '2026-02-10 16:10:57'),
(1075, 1062, 'گزینه&laquo;4&raquo; ﻿در مرحله آغاز و پایان ترجمه، هیچگاه رنای ناقل در جایگاه های A و E ریبوزوم دیده نمی شود. در مرحله آغاز، زیرواحد بزرگ ریبوزوم به زیرواحد کوچک آن متصل می شود و در مرحله پایان ترجمه، زیرواحد بزرگ ریبوزوم از زیرواحد کوچک آن جدا خواهد شد؛ در واقع تمایل زیرواحدهای ریبوزوم برای اتصال به هم تغییر می کند. بررسی سایر گزینه ها: 1) مولکول پلی پپتیدی مورد نظر می تواند دو نوع مولکول مختلف باشد؛ یکی رشته پلی پپتیدی در حال ساخت که به رنای ناقل موجود در جایگاه A اتصال دارد و طی مرحله طویل شدن و با حرکت رناتن وارد جایگاه P می شود. دیگری نیز ممکن است پروتئین(های) مربوط به عوامل آزاد کننده باشد که نوعی مولکول پلی پپتیدی است و در مرحله پایان در جایگاه A قرار می گیرد. با قرارگیری پروتئین آزاد کننده در جایگاه A ، دیگر حرکتی توسط رناتن بر روی رنای پیک صورت نمی گیرد، چراکه ترجمه تمام می شود. 2) در مرحله طویل شدن، رنای ناقل فاقد آمینواسید در جایگاه E قرار می گیرد. توجه کنید که در هیچ یک از مراحل ترجمه، امکان این که به صورت همزمان جایگاه های A و E رناتن توسط رناهای دارای توالی پادر مزه اشغال شوند، وجود ندارد! جایگاه E و P می توانند همزمان با هم اشغال شوند اما A و E نه! ۳) در مرحله طویل شدن، امکان اشغال همزمان دو جایگاه رناتن با رنای ناقل وجود دارد؛ در فرایند ترجمه، هر آمینواسید جدید به انتهای کربوکسیل (نه آمین) مربوط به آمینواسید قبلی در رشته پلی پپتیدی در حال ساخت، متصل می گردد. انتهای آمین رشته پلی پپتیدی در حال ساخت آزاد می باشد.', '2026-02-10 16:20:31'),
(1077, 1063, 'گزینه&laquo;4&raquo; بررسی همه گزینه ها: 1) در همه یاخته های یوکاریوتی هسته دار، رونویسی یک ژن خاص در هسته، توسط یکی از سه نوع آنزیم رنابسپاراز موجود در این بخش، انجام می شود؛ بنابراین همۀ یاخته های یوکاریوتی هسته دار، چنین ویژگی دارند. 2) در همه یاخته های یوکاریوتی هسته دار، درون هسته انواع مختلف رنا تولید می شود که در ادامه این رناها با عبور از منافذ هسته به فضای درون سیتوپلاسم وارد می شوند. دقت کنید رناهای تولید شده درون میتوکندری و کلروپلاست در خود این اندامک ها، فعالیت می کنند. ۳) در همه یاخته های یوکاریوتی هسته دار، بخش هایی از رشته الگوی دنا (توالی های اگزونی) با رنای پیک بالغ، پیوند هیدروژنی تشکیل می دهند. از آنجایی که رونوشت اینترون ها از رنای پیک نابالغ حذف می شود تا رنای بالغ ساخته شود، می توان گفت اتصالی بین این بخش ها با توالی شان در دنا رخ نمی دهد. 4) در گیاهان \\( C_4\\)، روزنه های هوایی، در طول روز می توانند باز باشند، پس در طی روز که فتوسنتز انجام می شود از \\( H_2O\\) به عنوان منبع الکترون در فتوسنتز استفاده می شود. دقت کنید در یاخته های میانبرگ گیاهان \\( C_4\\) و \\(CAM\\)و همچنین یاخته های غلاف آوندی گیاهان \\( C_4\\) ،، کلروپلاست، تیلاکوئید و زنجیره های انتقال الکترون دیده می شود؛ اما دقت کنید که گیاهان \\(CAM\\) در طی شب روزنه های هوایی خود را باز می کنند و در این زمان از آب به عنوان منبع الکترون فتوسنتز استفاده نمی شود، زیرا واکنش های وابسته به نور (تیلاکوئیدی) در طی روز انجام می شود. این وقایع در گیاهان \\( C_4\\) رخ می دهد، پس این گزینه با در نظر گرفتن هر کدام از حالات صحيح است.', '2026-02-10 16:22:34'),
(1078, 1064, 'گزینه&laquo;4&raquo; بررسی همه موارد الف) نادرست؛ در زنجیره انتقال الکترون میتوکندری، آخرین عضوی که در غشا قرار دارد، نوعی پمپ است، بنابراین در تماس با سرهای آب دوست هر دو لایه فسفولیپیدی سازنده غشا است. در زنجیره انتقال الکترون بین دو فتوسیستم، طبق شکل کتاب درسی، آخرین عضو، جزئی است که در فضای درون تیلاکوئید قرار دارد و فقط در تماس با سرهای آب دوست لایه داخلی غشای فسفولیپیدی قرار دارد. ب) نادرست؛ نخستین عضو در زنجیره انتقال الکترون میتوکندری، نوعی پمپ است، بنابراین با انتقال پروتون ها از عرض غشاء میزان pH دو سوی غشا را تغییر می دهد؛ اما دقت کنید که نخستین عضو در زنجیره انتقال الکترون بین دو فتوسیستم، تنها الکترون را به جزء دوم (پمپ پروتونی) منتقل می کند و خودش پروتونی جابه جا نمی کند و تغییری در میزان pH ایجاد نمی کند. ج) نادرست؛ در زنجیره انتقال الکترون میتوکندری، الکترون ها از پمپ سوم زنجیره به O2 می رسند، پس این پمپ الکترون ها را به مولکولی غیر نیتروژن دار منتقل می کند. د) درست؛ با توجه به شکل زنجیره انتقال الکترون غشای داخلی میتوکندری، پمپ های پروتونی در سراسر عرض غشا استقرار یافته اند. است. همچنین در زنجیره انتقال الکترون بین فتوسیستم ها، پمپ پروتونی به طور کامل در ضخامت غشا استقرار یافته است، اما سایر اجزاء این گونه نیستند.', '2026-02-11 20:26:02'),
(1079, 1061, 'گزینه&laquo;2&raquo; مطابق اطلاعات کتاب درسی در فصل ششم زیست شناسی 3 ، گیاهان \\(CAM\\) و \\(C_4\\) توانایی انجام فتوسنتز، در شرایط دشوار را دارا هستند در گیاهان \\(C_4\\)، در یاخته های میانبرگ، مرحلۀ اول تثبیت کربن رخ می دهد و چرخۀ کالوین در یاخته های غلاف آوندی رخ می دهد، اما در گیاهان \\(CAM\\) هر دو مرحله تثبیت کربن، در یاخته میانبرگ رخ می دهد. بررسی سایر گزینه ها: 1) هر دو نوع گیاهان \\(CAM\\) و \\(C_4\\)، تثبیت کربن در مرحله اول را بدون فعالیت روبیسکو انجام می دهند؛ در این مرحله نوعی آنزیم کربوکسیلاز اختصاصی شرکت می کند که \\(CO_2\\) جو را به اسید سه کربنی متصل می کند و ترکیبی چهار کربنی می سازد. 3) هم در گیاهان \\(CAM\\) و هم در گیاهان C4، نخستین ترکیب تولیدی در پی تثبیت کربن، نوعی ترکیب چهار کربنی است. 4) آبسیزیک اسید در دما و نور زیاد، ترشح می شود و سبب بسته شدن روزنه های هوایی در گیاه می شود. هم در گیاهان \\(CAM\\) و هم \\(C_4\\)، تثبیت دومرحله ای که رخ می دهد، سبب می شود، در شرایط بسته بودن روزنه های هوایی، مقدار \\(CO_2\\) در مجاور آنزیم روبیسکو، همچنان بالا باشد و چرخۀ کالوین رخ دهد. در گیاهان \\(CAM\\)، همواره چرخۀ کالوین در زمان بسته بودن روزنه های هوایی رخ می دهد (یعنی طی روز که این روزنه ها بسته هستند، چون در شب روزنه های هوایی آنها باز است) و در گیاهان \\(C_4\\) هم، اگر دما و نور خیلی زیاد شود، روزنه های هوایی بسته می شوند که در این شرایط \\(CO_2\\) به گیاه وارد نمی شود؛ پس مرحلۀ اول تثبیت کربن رخ نمی دهد اما مرحله دوم به علت سازوکاری که این گیاهان دارند همچنان قابل رخ دادن است. پس در هر دو گروه، امکان انجام بخشی از مراحل تثبیت کربن، در زمان افزایش هورمون آبسیزیک اسید وجود دارد.', '2026-02-11 20:26:45'),
(1080, 1060, 'گزینه&laquo;1&raquo; همه گزینه ها به نادرستی بیان شده اند. بررسی همه موارد الف) این مورد فقط برای دنابسپار از صادق است، زیرا رشته دنای ساخته شده به رشته الگو متصل باقی می ماند، اما رنای ساخته شده از دنا، جدا می شود. ب) دنابسپاراز و رنا بسپار از نوعی پروتئین هستند و فاقد قند پنج کربنه می باشند. دقت کنید در محصول عملکرد این دو آنزیم یعنی دنا و رنا، قند پنج کربنی دیده می شود. آمینواسیدها از واحدهای قندی تشکیل نشده اند. ج) این مورد، فقط برای رنابسپار از صادق است که برای شروع رونویسی و ادامۀ آن، پیوندهای هیدروژنی بین دو رشته دنا را می شکند؛ اما دنا بسپار از توانایی تخریب پیوندهای هیدروژنی را ندارد و هنگام همانندسازی، آنزیم هلیکاز این پیوندها را می شکند. د) هر دو مولکول توسط رناتن های آزاد در سیتوپلاسم ساخته می شوند، به رناتن های متصل به شبکه آندوپلاسمی؛ زیرا پروتئین هایی هستند که درون هسته فعالیت می کنند.', '2026-02-11 20:36:07'),
(1081, 1058, 'گزینه&laquo;4&raquo; تعداد آمینواسیدهای اینترفرون حاصل از یاخته های بدن انسان، مهندسی پروتئین و مهندسی ژنتیک، همگی یکسان و برابر است، زیرا تغییری در تعداد کدون های رنای پیک سازنده آنها داده نمی شود، بلکه تفاوت اینترفرون مهندسی پروتئین شده با آنها در نوع یکی از آمینواسیدهاست. بررسی سایر گزینه ها: 1) طبق متن کتاب درسی، در مهندسی ژنتیک به علت ایجاد پیوندهای نادرست در ساختار اینترفرون، این پروتئین نسبت به پروتئین تولید شده توسط رناتن های بدن انسان، فعالیت ضدویروسی کمتری دارد. 2) در مهندسی پروتئین یک آمینواسید را جایگزین آمینواسید دیگری در پروتئین طبیعی می کنند تا از این طریق، پیوندهای صحیح تری نسبت به مهندسی ژنتیک ایجاد شود و پروتئینی با عملکرد مشابه پروتئین طبیعی ایجاد شود. ۳) فعالیت ضدویروسی اینترفرون تولید شده با مهندسی پروتئین به اندازۀ فعالیت اینترفرون طبیعی می باشد، اما نسبت به پروتئین طبیعی پایدارتر است و از آن می توان برای تهیه دارو استفاده کرد.', '2026-02-11 20:36:54'),
(1082, 1057, 'گزینه&laquo;1&raquo; با اتصال مالتوز به پروتئین فعال کننده (نوعی مولکول واجد پیوندهای هیدروژنی)، این پروتئین به جایگاه اتصال فعال کننده (توالی قبل از راه انداز) متصل می شود. بررسی سایر گزینه ها: 2) قبل از اتصال لاکتوز به پروتئین مهارکننده، آنزیم رنابسپاراز به توالی راه انداز ت(والی قرار گرفته در پشت اپراتور) متصل شده است. با اتصال لاکتوز به مهار کننده، مهار کننده از اپراتور جدا می شود و زمینه حرکت آنزیم بر روی ژن ها فراهم می شود. ۳) در تنظیم مثبت رونویسی مالتوز به پروتئین فعال کننده و در تنظیم منفی رونویسی لاکتوز به پروتئین مهارکننده متصل می گردد. دقت کنید که این پروتئین ها هیچ کدام آنزیم نبوده و جایگاه فعال نیز ندارند. 4) دقت داشته باشید که هیچ یک از این ترکیب های قندی (مالتوز و لاکتوز) به دنا متصل نمی شود؛ بلکه این ها به پروتئین هایی متصل می شوند که این پروتئین ها، به توالی دنا متصل می شوند.', '2026-02-11 20:37:22'),
(1083, 1056, 'گزینه&laquo;4&raquo; همه موارد به نادرستی بیان شده است. (الف) اگر جهش کوچک از نوع اضافه به گونه ای رخ دهد که توالی پایان رونویسی در بخشی جلوتر نسبت به قبل (توالی پایان رونویسی زودتر از موعد) ایجاد شود، آنگاه امکان تشکیل رنای پیک کوتاه تر وجود دارد. ب) طبق کتاب جهش دو پارتیمین به دلیل تغییری که در دنا می دهد، همانندسازی را با اختلال مواجه می کند و باعث می شود آنزیم بسپاراز نتواند کار خود را به درستی انجام دهد. این جهش با تغییر توالی نوکلئوتیدی دنا همراه نیست. ج) قبل از کدون آغاز، توالی(هایی) وجود دارد که موجب هدایت زیرواحد کوچک رناتن به سمت رنای پیک و در نتیجه شروع ترجمه می شوند. اگر جهش در این توالی ها رخ داده باشد و عملکرد آنها را مختل کرده باشد، علیرغم سالم بودن کدون آغاز، همچنان ترجمه نمی تواند انجام شود. همچنین ممکن است جهش در ساختار رنای رناتنی یا پروتئین های سازندۀ رناتن باشد و در نتیجه رنای پیک، به علت اختلال عملکرد رناتن، ترجمه نشود. د) اگر نوعی جهش باعث تبدیل یک کدون پایان به کدون پایان دیگری شود، طول رنای پیک تغییر نمی کند. همچنین دقت کنید که طول رنای پیک به محل شروع رونویسی و توالی پایان رونویسی نیز ارتباط دارد.', '2026-02-11 20:38:15'),
(1084, 1055, 'گزینه&laquo;4&raquo; در یوکاریوت ها و پروکاریوت ها، در هر دوراهی همانندسازی، یک آنزیم هلیکاز وجود دارد که با اثر بر دنای اولیه موجب شکسته شدن پیوندهای هیدروژنی ساختار آن می شود. بررسی سایر گزینه ها: 1) یکی از راه های تنظیم بیان ژن در یوکاریوت ها، تغییر در فشردگی فام تن هاست اما یاخته های پروکاریوتی فاقد پروتئین های هیستون و در نتیجه نوکلئوزوم می باشند. 2) در یوکاریوت ها فقط ساخت مولکول های \\(NADH\\) می تواند در ماده زمینه ای سیتوپلاسم انجام شود و \\(FADH_2\\) در میتوکندری تولید می شود. در پروکاریوت ها هر دو نوع ناقل الکترون در ماده زمینه ای سیتوپلاسم تولید می شوند، چراکه اصلا راکیزه ندارند؛ پس استفاده از جمله &laquo;انواعی از مولکول های حامل الکترون!&raquo; در خصوص یاخته های یوکاریوتی نادرست است. ۳) در پروکاریوت ها برخلاف یوکاریوت ها، توالی افزاینده وجود ندارد. عوامل رونویسی متصل به این توالی با ایجاد خمیدگی در مولکول \\(DNA\\)، عوامل رونویسی متصل به توالی راه انداز را در مجاورت عوامل رونویسی متصل به توالی افزاینده قرار می دهند و از این طریق سرعت رونویسی افزایش می یابد.', '2026-02-11 20:44:35'),
(1085, 1054, 'گزینه&laquo;2&raquo; موارد &laquo;الف&raquo; و &laquo;د&raquo; صحیح است. در دوران جنینی، مغز قرمز استخوان، کبد و طحال تولید یاخته های خونی و گرده ها را انجام می دهند که از بین آنها، مغز قرمز استخوان و طحال نوعی اندام لنفی هستند. الف) گروهی از گویچه های قرمز، روزانه تخریب می شوند؛ تخریب یاخته های خونی قرمز آسیب دیده و مرده در طحال و کبد انجام می شود. آهن آزاد شده در این فرایند یا در کبد ذخیره می شود و یا همراه خون به مغز قرمز استخوان می رود و در ساخت دوباره گویچه های قرمز مورد استفاده قرار می گیرد؛ بنابراین هر دو اندام ذکر شده همانند کبد (اندام سازنده لیپوپروتئین ها) به نوعی بر میزان آهن خون تأثیر گذارند. ب) یاخته های بنیادی، یاخته هایی تمایز نیافته با توانایی تقسیم و تولید چندین نوع یاخته مختلف هستند؛ مطابق اطلاعات کتاب درسی، در مغز قرمز استخوان برخلاف طحال یاخته های بنیادی وجود دارد که انواع مختلفی از یاخته ها مثل خونی و غیرخونی را می سازند. ج) به عنوان مثال لنف خارج شده از مغز قرمز استخوان دست راست، وارد مجرای لنفی راست می شود. د) ماکروفاژها و یاخته های دارینه ای حاصل تغییر شکل و تمایز مونوسیت های بافت پیوندی خون هستند. هر دو می توانند در مبارزه بدن با ویروس ها نقش داشته باشند؛ ماکروفاژها با فاگوسیتوز آنها (مثلا به دنبال اتصال آنها به پادتن ها) یاخته های دارینه ای با بلعیدن آنها و ارائه آنتی ژن های آنها به یاخته های غیر فعال! ماکروفاژها و یاخته های دارینه ای، در دستگاه لنفی بدن دیده می شوند.', '2026-02-11 20:45:32'),
(1086, 1053, 'گزینه&laquo;3&raquo; مربوط به انتقال الکترون ها به \\(O_2\\) را مهار می کنند و این گونه به صورت غیر مستقیم سبب توقف زنجیره انتقال الکترون و ساخته شدن اکسایشی ATP نیز می شوند. دقت کنید که این مولکول ها مستقیماً بر همۀ پروتئین های پمپ کنندۀ پروتون ها به فضای بین دو غشای راکیزه (میتوکندری) اثر نمی گذارند. اثر مستقیم آنها بر پمپ سوم زنجیره است اما، پمپ های اول و دوم، می توانند تا مدتی پس از اثر سیانید و مونواکسید کربن، به پمپ \\(H^+\\) بپردازند، اما در نهایت فعالیت آنها هم متوقف می شود. بررسی سایر گزینه ها: 1) پیرووات محصول نهایی قندکافت است که در ماهیچه ها، طی تخمیر لاکتیکی می تواند کاهش یابد و به لاکتیک اسید تبدیل شود. در تخمیر، مولكول \\(ATP \\) تنها از طریق یک روش و آن هم از طریق سطح پیش ماده (در طی گلیکولیز) تولید می شود. 2) اکسایش مولکول های ناقل الکترون مثل \\(NADH\\) و \\(FADH_2\\) در زنجیره انتقال الکترون رخ می دهد؛ در نتیجه فعالیت این زنجیره، گاهی ممکن است در بخش انتهایی زنجیره، به دنبال انتقال الکترون ها به \\(O_2\\) به جای \\(O^{2-}\\)، رادیکال های آزاد تشکیل شود که واکنش پذیری بالا دارند. 4) در غشای داخلی میتوکندری، آنزیم \\(ATP \\) ساز با جابه جایی پروتون ها از فضای بین دو غشا به بخش داخلی میتوکندری، سبب تولید مولکول های \\(ATP \\) (مولکول های زیستی پرانرژی) می شود. دقت کنید که تولید \\(ATP \\) از \\(ADP\\) و فسفات با تولید مولکول آب همراه است. آنزیم \\(ATP \\) ساز، کانالی دارد که پروتون ها را در جهت شیب غلظتشان جابه جا می کند و با استفاده از انرژی حاصل از این جابه جایی، \\(ATP \\) می سازد.', '2026-02-11 20:45:52'),
(1087, 1052, 'گزینه&laquo;1&raquo; منظور از صورت سؤال، آنزیم های آمیلاز و لیزوزیم است که دارای جایگاه فعال می باشند. تنها مورد &laquo;ب&raquo; صحیح است. بررسی همه موارد الف) نادرست؛ آنزیم آمیلاز بر روی نشاسته در دهان تأثیر می گذارد و آن را به مولکول های کوچک تر (نه تک پار) تبدیل می کند. همچنین لیزوزیم نیز آنزیم گوارش دهنده تا حد مونومر نمی باشد، بلکه آنزیمی است که دیواره باکتری ها را تجزیه می کند. دقت کنید آنزیم ها، طی واکنش، مصرف نمی شوند، بلکه فقط سبب تبدیل واکنش دهنده ها به فراورده ها می شوند. ب) درست؛ این آنزیم ها در بزاق وجود دارند و بزاق هم، توسط غدد بزاقی بزرگ و کوچک تولید می شود. هر غدۀ برون ریز در بدن انسان، در نهایت ترشحات خود را به درون ساختار مجرا یا مجراهایی وارد می کند. ج) نادرست؛ شبکه عصبی روده ای در انسان از مری تا مخرج گسترش یافته است و بنابراین تأثیری بر ترشحات غدد بزاقی در حفره دهانی ندارد. پل مغزی، ترشح بزاق را کنترل می کند. د) نادرست؛ آسیاب شدن غذا به ذره های بسیار کوچک برای فعالیت بهتر آنزیم های گوارشی (آمیلاز) بر غذا لازم است. این مورد درباره لیزوزیم صادق نیست.', '2026-02-11 20:46:50'),
(1088, 1051, 'گزینه&laquo;3&raquo; منظور از یاخته های با توانایی تراگذری (دیاپدز)، گویچه های سفید است. این یاخته ها برای هورمون انسولین گیرنده دارند، انسولین سبب ورود گلوکز به یاخته ها می شود. پس تحت تأثیر انسولین میزان نفوذپذیری غشای آن ها به قند گلوکز تنظیم می شود. همچنین همه یاخته های زنده بدن دارای گیرنده هورمون تیروئیدی نیز هستند و تحت تأثیر این هورمون فعالیت خود را تغییر می دهند، مثلا در صورت افزایش سوخت و ساز یاخته ها، برای افزایش تجزیه گلوکز، لازم است میزان گلوکز بیشتری را به خود وارد و سپس مصرف کنند. بررسی سایر گزینه ها: 1) فقط گروهی از گویچه های سفید توانایی انجام تقسیم میتوز را دارند. لنفوسیت های B و T اولیه و خاطره توانایی انجام تقسیم میتوز را دارند، اما مثلا نوتروفیل ها، تقسیم نمی شوند. 2) ورود پیرووات به راکیزه با انتقال فعال و توسط پمپ های پروتئینی انجام می شود. کانال های پروتئینی مربوط به فرایند انتشار تسهیل شده هستند. 4) گویچه های سفید دفاع غیر اختصاصی (مثل نوتروفیل ها و مونوسیت ها)، فاقد گیرنده پادگنی هستند.', '2026-02-11 20:51:37'),
(1089, 1050, 'گزینه&laquo;3&raquo; منظور رنای ناقل (tRNA) است. طی ترجمه، اولین رنای ناقل مستقر شده در رناتن، مکمل کدون AUG است و توالی UAC دارد. این رنا وارد جایگاه A رناتن نمی شود و فقط در جایگاه های P و E قابل مشاهده است. طی مرحله طویل شدن، رناهای ناقل مختلف با توالی های آنتی کدونی متفاوت، ابتدا وارد جایگاه A شده و در آن مستقر می شوند و در ادامه از سایر جایگاه های رناتن نیز، می گذرند. رنای ناقل با توالی آنتی کدونی UGA مکمل كدون ACU است که این توالی مربوط به کدون پایان نیست و برای یک آمینواسید است؛ پس این رنای ناقل می تواند در مرحله طویل شدن از هر سه جایگاه رناتن بگذرد. بررسی سایر گزینه ها: 1) رمزها و در نتیجه رمزه ها و پادرمزه ها (آنتی کدون ها) از نظر توالی نوکلئوتیدی در همۀ جانوران مشابه هستند و یک معنی را می دهند، یعنی در همه AUG معرف متیونین است. 2) طی فرایند رونویسی هم نوکلئوتیدهای این رنا با رشته الگوی مکمل دنا، پیوند هیدروژنی برقرار کرده اند اما هنوز تاخوردگی مولکول رنا آغاز نشده است. 4) در یک انتهای رنای ناقل، یک توالی سه نوکلئوتیدی مشاهده می شود که از طریق یک نوکلئوتید خود به آمینواسید متصل است (دارای عملکردی متفاوت با سایر توالی ها). این توالی در رناهای مختلف مشابه است، چراکه طبق متن کتاب، رناهای ناقل فقط از نظر توالی پادرمزه متفاوت هستند.', '2026-02-11 20:52:18'),
(1090, 1049, 'گزینه&laquo;3&raquo; بر اساس شکل و مطالب کتاب درسی، در آخرین مرحله ساخت انسولین به روش مهندسی ژنتیک، ترکیب زنجیره های A و B برای تولید انسولین فعال صورت می گیرد که همراه با تشکیل پیوندهای شیمیایی غیر پپتیدی بین دو بسپار (پلیمر) زیستی (همان زنجیره های A و B ) است (رد گزینه ۴) دقت کنید که در این روش ساخت، جداشدن زنجیره C و تبدیل پیش انسولین به انسولین دیده نمی شود (رد گزینه 1 ) در آخرین مرحله از مراحل ژن درمانی که در کتاب درسی مطرح شده، تولید پروتئین یا مولکول مورد نظر در درون یاخته های تغییر یافته، در بدن فرد رخ می دهد که به نحوی همان فعالیت ژن سالم در هسته نوعی یاخته تراژنی (یاخته های تغییر یافته) است. (رد گزینه۲)', '2026-02-11 20:57:30'),
(1091, 1048, 'گزینه&laquo;3&raquo; در شارش ژنی، تعدادی از افراد یک جمعیت به جمعیت دیگر مهاجرت می کنند، پس تعداد دگره ها در جمعیت مبدأ کاهش می یابد؛ در نتیجه ممکن است فراوانی نسبی دگره های باقی مانده تغییر کنند (ممکن است افزایش یا کاهش یابد). همچنین با ورود این دگره ها به جمعیت مقصد، فراوانی نسبی آنها در جمعیت مقصد هم، ممکن است افزایش یابد. در پی رانش دگره ای نیز، در جمعیت برجای مانده از جمعیت اولیه، فراوانی نسبی دگره های باقی مانده تغییر می یابد و ممکن است کم یا زیاد شوند؛ مثلا فرض کنید در جمعیت اولیه a۱۰ و A۱۰ داریم که فراوانی نسبی هر کدام ۵۰ درصد است اما به دلیل رانش، همۀ aها حذف می شود و فراوانی نسبی A در جمعیت باقی مانده ۱۰۰ درصد خواهد شد! بررسی سایر گزینه ها: 1) انتخاب طبیعی همانند شارش ژن، می تواند سبب کاهش گوناگونی دگره ای و کاهش گوناگونی افراد در جمعیت مبدأ شود. در شارش ژنی به دلیل جابه جایی افراد و در انتخاب طبیعی به دلیل حذف افراد ناسازگار! 2) جهش می تواند با افزودن الل های جدید، خزانه ژن را غنی تر کند و گوناگونی را در جمعیت افزایش دهد. الل جدید ایجاد شده به دنبال جهش، در شرایط محیطی مثلا جدید می تواند سازگارتر از الل یا الل های قبلی عمل کند و یا حتی ناسازگار باشد. دقت داشته باشید که انتخاب طبیعی نمی تواند باعث ایجاد الل جدید شود. ۴) جهش (تغییر ماندگار دنا) و شارش ژن می توانند موجب افزایش تنوع الل ها در خزانه ژنی یک جمعیت شوند؛ جهش با ایجاد این الل ها شارش با آوردن آن ها از جمعیتی به جمعیت دیگر! از این رو توان بقا در شرایط محیطی جدید افزایش خواهد یافت. هر چه تنوع بیشتر، شانس و بقا بیشتر!', '2026-02-11 20:57:46'),
(1092, 1047, 'گزینه&laquo;4&raquo; مطابق فعالیت کتاب درسی در صفحه ۸۱ زیست شناسی (۳)، در این آزمایش هم اسپیروژیر و هم باکتری هوازی وجود دارد که هر دو دارای رنا (نوکلئیک اسید خطی) هستند. این در حالی است که باکتری هوازی فاقد اندامک های دوغشایی است. دقت کنید در یوکاریوت ها نیز، همۀ اندامک ها، غشادار نیستند مثلا رناتن ها، اندامک های بدون غشا هستند که هم در یوکاریوت ها و هم در پروکاریوت ها وجود دارند. بررسی سایر گزینه ها: 1) در این آزمایش، اسپیروژیر (نوعی جلبک سبز) دارای راکیزه و توانایی تولید اکسایشی ATP در آن است که طول آن با توجه به شکل کتاب، بزرگتر از ۱۰۰ میکرومتر می باشد. 2) باکتری های هوازی، فاقد عوامل رونویسی هستند؛ این عوامل برای تسهیل سرعت و یا افزایش مقدار رونویسی به توالی های خاصی از دنا متصل می شوند، اکسایش پیرووات در این یاخته ها، درون سیتوپلاسم انجام می شود. ۳) اسپیروژیر دارای افزاینده است؛ طبق شکل کتاب درسی، در طول موج های ۵۰۰ تا ۶۰۰ نانومتر، میزان فتوسنتز این جلبک کم است، پس هم چنان اکسیژن تولید می کند اما خیلی کم!', '2026-02-11 20:58:09'),
(1093, 1046, 'گزینه&laquo;4&raquo; در قندکافت و تخمیر لاکتیکی (ابتدای آن با قندکافت شروع می شود) فروکتوز شش کربنۀ دوفسفاته تبدیل می شود به قند سه کربنی تک فسفاته. در اکسایش پیرووات، پیرووات سه کربنه به استیل دوکربنه تبدیل می شود. در چرخۀ کالوین نیز، مولکول شش کربنه ناپایدار اولیه به دو اسید سه کربنه تبدیل می شود. پس در همه این فرایندها اتفاق مورد نظر رخ می دهد. بررسی سایر گزینه ها: 1) در چرخۀ کالوین، تبدیل اسیدهای سه کربنی تک فسفاته به قندهای سه کربنی تک فسفاته، با افزایش فسفات های آزاد محیط همراه خواهد بود. اما در سایر فرایندها، این اتفاق نمی افتد. ب) در قندکافت، تبدیل گلوکز به فروکتوز فسفاته و تبدیل قندهای سه کربنی تک فسفاته به اسید سه کربنی دوفسفاته رخ می دهد. طی اکسایش پیرووات، تعداد فسفات های پیرووات افزایش نمی یابد. پیرووات بدون فسفات به استیل بدون فسفات تبدیل می شود در چرخه کالوین هم، مولکول آغازگر، ریبولوز بیس فسفات است که طی تبدیل آن به اسید سه کربنی تعداد فسفات هایش! افزایش نمی یابد. ۳) در قندکافت، تبدیل قند به اسید رخ می دهد؛ اما مثلا طی چرخۀ کالوین، اسید سه کربنی به قند سه کربنی تبدیل می شود. از طرفی این مورد طی اکسایش پیرووات هم رخ نمی دهد.', '2026-02-11 20:58:36'),
(1094, 1045, 'گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. بررسی همه موارد الف) تبدیل دیسک حلقوی باکتری به دنای خطی، می تواند به کمک برش در جایگاه تشخیص آنزیم توسط آنزیم برش دهنده صورت بگیرد. آنزیم برش دهنده، در جایگاه تشخیص خود، پیوندهای فسفودی استر (نوعی پیوند اشتراکی) خاصی را بین نوکلئوتیدهای موجود در هر رشته از این جایگاه برش می دهد؛ اما شکسته شدن پیوندهای هیدروژنی بین دو رشته دنا در منطقه تشخیص، بدون دخالت آنزیم رخ می دهد. ب) در هر جایگاه تشخیص، تعداد نوکلئوتیدهای پورین دار و پیریمیدین دار برابر (هر کدام پنج نوکلئوتید) است، زیرا در ساختار دنا در مقابل هر باز آلی تک حلقه ای، یک باز آلی دو حلقه ای قرار گرفته است. در هر نوکلئوتید پورین دار، سه حلقه آلی و در هر نوکلئوتید پیریمیدین دار دو حلقه آلی دیده می شود. بنابراین حداکثر ۲۵ حلقه آلی در ساختار توالی دنای قرار گرفته در جایگاه تشخیص قابل مشاهده است. ج) آنزیم برش دهنده، با برش در دنا، می تواند در هر سمت، انتهای چسبنده ایجاد کند. انتهاهای چسبنده تک رشته ای هستند. طی تشکیل دنای نوترکیب، بعد از این که ژن خارجی دارای انتهای چسبنده مشابه با ناقل، به دلیل رابطه مکملی در کنار هم قرار گرفتند (تشکیل پیوندهای هیدروژنی) پیوند فسفودی استر (اتصال ژن خارجی به ناقل) با کمک تشکیل پیوند فسفودی استر توسط لیگاز رخ می دهد. دقت کنید اتصال دو انتهای چسبنده به هم، توسط پیوندهای هیدروژنی صورت می گیرد که برای تشکیل به لیگاز نیاز ندارند. لیگاز دو سر ژن را به دنای ناقل وصل می کند نه دو انتهای چسبنده را به هم. د) تعداد نوکلئوتیدهای انتهای چسبنده حتما عددی زوج است این تعداد نمی تواند عدد پنج باشد.', '2026-02-11 20:59:11'),
(1095, 1044, 'گزینه&laquo;3&raquo; دو نوع واکنش مختلف، می تواند توسط روبیسکو انجام شود ۱) ترکیب شدن ریبولوز بیس فسفات با \\(CO_2\\) (فعالیت کربوکسیلازی) ۲) ترکیب شدن ریبولوز بیس فسفات با اکسیژن (فعالیت اکسیژنازی) تولید گروه کربوکسیل در ریبولوز بیس فسفات فقط در فعالیت کربوکسیلازی روبیسکو صورت می گیرد. بررسی سایر گزینه ها: 1) محصول هر دو واکنش، نوعی ترکیب آلی ناپایدار است و تجزیه می گردد. محصول واکنش کربوکسیلازی، ترکیب اسیدی شش کربنه است که به دو ترکیب سه کربنه تجزیه می شود و این دو ترکیب در چرخه کالوین به قند فسفاته تبدیل می شوند که این قند هم به ریبولوزفسفاتی تبدیل می شود که برای تولید ریبولوزبیس فسفات مصرف می شود. مولکول پنج کربنی حاصل از فعالیت اکسیژنازی روبیسکو نیز ناپایدار است و به دو مولکول سه کربنی و دوکربنی تجزیه می شود. مولکول سه کربنی برای بازسازی ریبولوز بیس فسفات به مصرف می رسد. 2) در هر دو واکنش یک مولکول آلی (ریبولوز بیس فسفات) و یک مولکول معدنی با دو اتم اکسیژن (کربن دی اکسید طی کربوکسیلازی و یا مولکول اکسیژن طی اکسیژنازی) در جایگاه فعال روبیسکو قرار می گیرند. 4) در هر دو واکنش بر تعداد اتم های اکسیژن ریبولوز بیس فسفات افزوده می شود؛ در طی کربوکسیلازی، گروه کربوکسیل با دو اتم اکسیژن (به دلیل اضافه شدن \\(CO_2\\)) و در طی اکسیژنازی نیز اتم(های) اکسیژن مصرف می شوند.', '2026-02-11 20:59:30'),
(1097, 1042, 'گزینه&laquo;3&raquo; نخستین مرحله تنفس یاخته ای، قند کافت است که در همۀ یاخته های زنده رخ می دهد. در تمام مراحل قندکافت، ترکیبات فسفات دار هم تولید و هم مصرف می شوند. این موضوع در شکل ۴ صفحه ۶۶ زیست شناسی۳، مشخص است. بررسی سایر گزینه ها: 1) ترکیب های نوکلئوتیدداری که در کالوین شرکت می کنند \\(ATP\\) و \\(NADPH\\) است. در حالی که \\(NADP^+\\) آخرین دریافت کننده الکترون در واکنش های وابسته به نور فتوسنتز می باشد. اگرچه این مورد در خصوص یاخته های انسانی نیز صادق نیست. 2) تولید کننده ها می توانند یوکاریوتی و یا پروکاریوتی باشند. باکتری های فتوسنتز کننده فاقد ساختارهای غشادار در درون خود هستند. همچنین این مورد دربارۀ هسته یاخته های یوکاریوتی نیز نادرست است. ۴) در خصوص یاخته های کبدی صادق نیست زیرا رنگیزه فتوسنتزی ندارند. مولکول های رنگی که در گیاهان دیده می شود مثل کاروتنوئیدها، خاصیت آنتی اکسیدانی دارد.', '2026-02-11 21:00:27'),
(1098, 1041, 'گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. منظور از صورت سؤال، چرخه های آنزیمی کربس و کالوین است. بنابراین باید به دنبال گزینه ای باشیم که فقط در خصوص یکی از این چرخه ها صادق باشد. بررسی همه موارد الف) در هر دو فرآیند، در ابتدا نوعی مولکول شش کربنی تولید می شود که در ادامه تجزیه می گردد. در کالوین، مولکول شش کربنی به دو مولکول سه کربنی شکسته می شود؛ در کربس نیز مولکول شش کربنی با از دست دادن کربن دی اکسید به مولکول پنج کربنی تبدیل می گردد. در هر دوتا، نوعی پیوند بین دو کربن، تجزیه شده است. ب) در چرخه کالوین، مولکول های قندی سه کربنی برای بازسازی ریبولوزبیس فسفات به مصرف می رسند (با تشکیل ریبولوز فسفات). اما در چرخه کربس، مولکول چهار کربنی تشکیل می شود که طی تغییراتی به مولکول چهار کربنی ابتدای چرخه تبدیل می شود. ج) مولکول پنج کربنی در کربس، با از دست دادن کربن خود (با آزادسازی \\(CO_2\\) ) به مادۀ چهار کربنی تبدیل می شود، پس تعداد کربن های آن کاهش می یابد. دقت داشته باشید در چرخۀ کالوین نیز ماده پنج کربنی که با دریافت کربن، شش کربنی می شود، فسفات دار می باشد. پس این گزینه، در مورد هیچ یک از چرخه ها صدق نمی کند. د) در چرخه کربس برخلاف کالوین، حامل های الکترونی تولید می شوند؛ نه این که اکسایش یابند و یون هیدروژن آزاد کنند. در کالوین \\(NADPH\\) با از دست دادن الکترون و یون هیدروژن، سبب کاهش یافتن ترکیبات سه کربنی می شوند.', '2026-02-11 21:00:49'),
(1099, 1040, 'گزینه&laquo;3&raquo; ناقل همسانه سازی می تواند پلازمید حلقوی باشد که پس از انتقال به یاخته میزبان، همچنان در خارج از فام تن های اصلی یاخته قرار بگیرد و به طور مستقل از دنای میزبان همانندسازی کند یا رونویسی شود. به عبارتی این ناقل های همسانه سازی، ممکن است محتوای وراثتی خودشان را به دنای اصلی یاخته میزبان وارد کنند و یا نکنند، اگر نکنند! این ناقل برای همانندسازی و رونویسی به آنزیم های میزبان وابسته است اما به عوامل رونویسی نیاز ندارد، اما اگر محتوای وراثتی ناقل با دنای هسته ای میزبان، ادغام شود، در این شرایط رونویسی شدن آن ممکن است نیازمند عوامل رونویسی باشد مثل مادۀ وراثتی ویروس که خودش نمی تواند به تنهایی فعالیت کند. پس بعضی از این ناقل ها، ویژگی مورد نظر را دارند. بررسی سایر گزینه ها: 1) زمانی که بخش های زیادی از دنای اصلی یاخته میزبان غیر فشرده است یعنی می تواند در حال همانندسازی باشد. دقت کنید ناقلین همسانه سازی، می توانند مستقل از فام تن اصلی، همانندسازی کنند و تکثیر شوند، مثلا دیسک یک مولکول دنای دورشته ای و خارج فام تنی است که معمولا درون باکتری ها و بعضی قارچ ها مثل مخمرها وجود دارد و می تواند مستقل از ژنوم میزبان همانندسازی کند. ۲) در همۀ ناقل ها، ژن خارجی برای این که بتواند در توالی نوکلئوتیدی ناقل جای بگیرد، ابتدا لازم است تا تعدادی از پیوندهای فسفو دیاستر در ناقل شکسته شود. به عبارتی باید جایگاهی برای قرارگیری ژن خارجی ایجاد شود، مثلا با ایجاد انتهای چسبنده مشابه با دو سر ژن خارجی در ناقل! که لازمه آن شکسته شدن دنا است. 4) دیسک می تواند یک دنای حلقوی خارج فام تنی باشد که در مهندسی ژنتیک با استفاده از آنزیم های برش دهنده، می توان آن را به یک قطعه دنای خطی تبدیل کرد که دارای دو انتهای چسبنده است. اما دقت کنید که مادۀ وراثتی موجود در یک ویروس لزوما حلقوی نیست بلکه طبق شكل مقابل می تواند ساختاری خطی داشته باشد.', '2026-02-11 21:01:06'),
(1100, 1039, 'گزینه&laquo;3&raquo; در چرخه کالوین از ترکیب کربن دی اکسید (نوعی ماده معدنی) و ریبولوزبیس فسفات، نوعی ترکیب شش کربنی ناپایدار تشکیل می شود که تجزیه می شود. در تنفس نوری نیز از ترکیب اکسیژن (نوعی ماده معدنی) و ریبولوزبیس فسفات، ترکیب پنج کربنی ناپایدار تشکیل می شود که به دو ترکیب سه و دو کربنی تجزیه می شود. بررسی سایر گزینه ها: 1) در واکنش های چرخۀ کالوین، از تجزیه ترکیب شش کربنی ناپایدار، دو ترکیب سه کربنی ایجاد می شود. در واکنش های تنفس نوری نیز، ریبولوز بیس فسفات پس از ترکیب با اکسیژن، به دو ترکیب دوکربنی و سه کربنی تبدیل می شود که ترکیب سه کربنی، صرف بازسازی مجدد ریبولوز بیس فسفات می شود. 2) در واکنش های چرخه کالوین، حامل های الکترونی (NADPH) مصرف می شوند. بنابراین تعداد پذیرنده های الکترونی در فضای بستره افزایش می یابد. حامل های الکترونی، طی واکنش های وابسته به نور فتوسنتز تولید می شوند. 4) در هیچ کدام از واکنش های چرخۀ کالوین و تنفس نوری تولید ATP (رایج ترین شکل انرژی در یاخته) رخ نمی دهد. تولید ATP در فتوسنتز، طی واکنش های وابسته به نور رخ می دهد.', '2026-02-11 21:01:21'),
(1101, 1038, 'گزینه&laquo;4&raquo; اندامک های حاوی دنای حلقوی، کلروپلاست و میتوکندری هستند. در غشای تیلاکوئید همانند غشای درونی راکیزه، مجموعه ای پروتئینی به نام آنزیم ATP ساز وجود دارد، آنزیم ATP ساز موجود در کلروپلاست، پروتون ها را با عبور از کانال خود، از فضای درون تیلاکوئید به بستره کلروپلاست جابه جا می کند. در حالی که آنزیم ATP ساز میتوکندری، پروتون ها را از فضای بین دو غشای آن به بخش داخلی میتوکندری وارد می کند. داخلی ترین فضا در کلروپلاست فضای درون تیلاکوئید است. پس این گزینه، فقط درباره آنزیم ATP ساز میتوکندری صحیح است. بررسی سایر گزینه ها: 1) در راکیزه با ورود پروتون ها از بخش داخلی به فضای بین دو غشا، تراکم آنها در این فضا نسبت به بخش داخلی افزایش می یابد. پروتون ها براساس شیب غلظت تمایل دارند که به سمت بخش داخلی برگردند، اما تنها راه پیش روی پروتون ها برای برگشتن به این بخش، مجموعه ای پروتئینی به نام آنزیم ATP ساز است. پس پروتون ها، از کانالی که در این مجموعه قرار دارد، عبور می کنند و انرژی لازم برای ساخت ATP را فراهم می کنند. آنزیم ATP ساز غشای تیلاکوئید نیز، پروتون ها را براساس شیب غلظت از فضای درون تیلاکوئید به بستره سبز دیسه وارد می کند و ATP می سازد. 2) آنزیم ATP ساز میتوکندری با روش اکسایشی، ATP را با استفاده از یون فسفات و انرژی حاصل از انتقال الکترون ها می سازد. به ساخته شدن ATP در واکنش های نوری فتوسنتز و توسط مجموعه پروتئینی آنزیم ATP ساز موجود در غشای تیلاکوئید نیز، ساخته شدن نوری ATP می گویند، زیرا حاصل فرآیندی است که در اثر نور اتفاق می افتد. ۳) طبق شكل ۸ صفحه ۷۰ و شکل ۶ صفحه ۸۳ کتاب زیست شناسی ۳، بخش ATP ساز هیچ یک از این مجموعه های پروتئینی در میان فسفولیپیدهای غشایی قرار نگرفته است بلکه کانال آنها در این بخش قرار دارد.', '2026-02-11 21:01:44'),
(1102, 1037, 'گزینه&laquo;1&raquo; همان طور که در نمودار مشاهده می کنید، کمترین میزان فتوسنتز در محدوده طول موج های ۴۰۰ تا ۷۰۰ نانومتر (بنفش تا نارنجی نور مرئی)، در طول موجی حدودا ۵۷۰ نانومتر است. با توجه به نمودار طیف جذبی رنگیزه های فتوسنتزی متوجه می شویم که تنها سبزینه a و b در این طول موج قادر به جذب نور هستند. (هر چند این جذب بسیار اندک است)؛ سبزینه ها به رنگ سبز دیده می شوند؛ پس می توانند این پرتوها را بازتاب دهند. بررسی سایر گزینه ها: 2) فتوسنتز کننده ها انواع مختلفی دارند مثل گیاهان فتوسنتز کننده و اوگلنا که دارای سبزینه های a و b هستند. سیانوباکتری ها هم سبزینه a دارند اما دقت کنید باکتری های گوگردی هم فتوسنتز می کنند اما رنگیزه فتوسنتزی آنها باکتریوکلروفیل است. 3) کاروتنوئیدها در یاخته های گیاهی علاوه بر سبز دیسه در رنگ دیسه ها نیز مشاهده می شوند؛ سبزینه ها هم در کلروپلاست وجود دارند. اما یاخته های گیاهی، آمیلوپلاست هم دارند که این پلاست ها، فاقد رنگیزه هستند. 4) حداکثر جذب نوری سبزینه a در مرکز واکنش فتوسیستم های ۱ و ۲ با هم متفاوت است. حداکثر جذب این سبزینه در فتوسیستم ۲، در ۶۸۰ نانومتر و در فتوسیستم ۱، در ۷۰۰ نانومتر است.', '2026-02-11 21:01:58'),
(1103, 1036, 'گزینه&laquo;1&raquo; همه موارد به نادرستی بیان شده اند. الف) در هر سه نوع گیاه \\(C_3\\)،\\(C_4\\) و \\(CAM\\)، آنزیم روبیسکو می تواند، هنگام بسته بودن روزنه های هوایی فعالیت خود را ادامه دهد. در گیاهان \\(C_4\\) و CAM که به دلیل سازوکاری که دارند در مجاورت این آنزیم \\(CO_2\\) بالا خواهد بود، پس همچنان می تواند به فعالیت خود ادامه دهد. در گیاه \\(C_3\\)، نیز، وقتی روزنه هایی هوایی بسته هستند روبیسکو می تواند فعالیت اکسیژنازی داشته باشد. گیاهان \\(C_3\\) سازوکاری برای مقاومت در برابر تنفس نوری ندارد. ب) گیاهان \\(C_4\\) و \\(CAM\\)، کربن دی اکسید را ابتدا در ترکیبی چهار کربنه ذخیره می کنند. دقت کنید که هر سه نوع گیاه، می توانند در میتوکندری یاخته های خود طی چرخۀ کربس، به تولید و مصرف نوعی ترکیب چهار کربنه بپردازند. ج) در گیاهان \\(C_3\\) و \\(C_4\\) روزنه های هوایی در طول روز باز هستند. تورژسانس یاخته های نگهبان روزنه، سبب بازشدن آنها می شود. مولکول \\(CO_2\\) علاوه بر اندامک میتوکندری (طی مراحل اکسایش پیرووات و چرخۀ کربس در تنفس یاخته ای و تنفس نوری)، در ماده زمینه سیتوپلاسم نیز طی تخمیر الکلی قابل تولید است. د) در گیاهان \\(C_3\\) و \\(CAM\\) همۀ یاخته های کلروپلاست دار به مصرف ریبولوز بیس فسفات می پردازند (به علت انجام کالوین در هر دو یا تنفس نوری در گیاهان \\(C_3\\)) اما در گیاهان \\(C_4\\)، یاخته های میانبرگ با وجود این که کلروپلاست دارند، به انجام چرخۀ کالوین و مصرف ریبولوز بیس فسفات نمی پردازند؛ زیرا در این یاخته ها، مرحله اول تثبیت کربن دی اکسید رخ می دهد که توسط آنزیمی غیر از روبیسکو است و چرخۀ کالوین در یاخته های غلاف آوندی رخ می دهد. در گیاهان \\(CAM\\)، اسید سه کربنه حاصل از تجزیه ترکیب چهار کربنی تولید شده در شب، وارد کالوین می شود. اما دقت کنید که طی روز در این گیاهان، قندکافت هم رخ می دهد و حتی ممکن است تخمیر لاکتیکی هم رخ دهد. اسید دوفسفاته تولیدی در قندکافت و یا لاکتیک اسید تولیدی وارد چرخه کالوین نمی شوند.', '2026-02-11 21:02:19'),
(1104, 1035, 'گزینه&laquo;2&raquo; در نبود یا کمبود \\(O_2\\)، یاخته های گیاهی می توانند با استفاده از تخمیر، ATP مورد نیاز خود را بسازند. در واکنش های گلیکولیز که بخشی از فرایند تخمیر محسوب می شود، گلوکز که ترکیبی شش کربنی است، به فروکتوز دوفسفاته تبدیل شده و این قند، به دو ترکیب سه کربنی تک فسفاته تجزیه می شود. در چرخۀ کالوین نیز، با اتصال \\(CO_2\\) به ریبولوز بیس فسفات، ترکیبی شش کربنی و ناپایدار (که دوفسفاته است) تولید می شود، که به دو اسید سه کربنی تجزیه می شود. بررسی سایر گزینه ها: 1) اکسایش استیل کوآنزیم A یعنی چرخه کربس؛ در چرخه کربس ابتدا نوعی ترکیب شش کربنی (به دنبال ترکیب استیل کوآنزیم A با مولکول چهار کربنی) و همچنین در چرخۀ کالوین نیز، ابتدا مولکول شش کربنی ناپایدار از ترکیب کربن دی اکسید و ترکیب پنج کربنی تولید می شود. 3) در چرخۀ کالوین با مصرف اسیدهای سه کربنی، قندهای سه کربنی تک فسفاته تولید می شوند که گروهی از این مولکول ها می توانند در تولید مولکول های پنج کربنی آغازگر چرخه مصرف شوند. در گلیکولیز نیز مولکول های قند فسفاته (سه کربنی و تک فسفاته) در دومین گام فرایند تولید و در سومین گام مصرف می شوند. 4) پیش ماده های کربنیک انیدراز، آب و کربن دی اکسید هستند. در چرخۀ کالوین کربن دی اکسید مصرف می شود نه تولید اما در چرخه کربس \\(CO_2\\) تولید می شود. دقت کنید در هر دو فرایند به دلیل وقوع واکنش های سنتز آبدهی، تعدادی مولکول آب تولید خواهد شد.', '2026-02-11 21:02:58'),
(1105, 1034, 'گزینه&laquo;1&raquo; همه موارد به درستی بیان شده اند. بررسی همه موارد: الف) در تولید گیاهان تراژنی مثل پنبۀ مقاوم به آفت، بررسی دقیق ایمنی زیستی گیاه ایجاد شده ضروری است. چراکه این تغییر نباید به محیط پیرامون و یا جانداران دیگر آسیب برساند. ب) در مهندسی ژنتیک برای تولید گیاه مقاوم به خشکی یا شوری باید ژن یا ژن هایی که در این مقاومت نقش دارند از گیاهانی که به طور طبیعی مقاوم هستند جدا شده (مثلا گیاهان خودرو و در مناطق بیابانی) و با استفاده از روش های مهندسی ژنتیک، در ساختار نوعی مولکول دنا قرار بگیرند و در نهایت به گیاه منتقل شوند. ج) اتیلن در رسیدن میوه ها نقش دارد. به دنبال افزایش اتیلن میوه ها زودتر می رسند. برای تنظیم سرعت رسیدن میوه ها بررسی ژن های مربوط به تولید اتیلن و یا گیرنده آن ضروری است. این موضوع در زیست شناسی یازدهم بیان شده است. مثلا اگر گیاهی تولید شود که اتیلن بیشتری تولید کند، میوه ها زودتر می رسند و یا گیاهی داشته باشیم که گیرنده اتیلن آن غیرفعال شده باشد، در این حالت می توان مانع از رسیدگی سریع میوه ها و یا خراب شدن آنها شد. د) در اصلاح بذر به کمک مهندسی ژنتیک، بخشی از یک مولکول دنا یا محتوای وراثتی که حاوی ویژگی های مطلوب است (محتوای وراثتی متفاوت با یاخته هدف دارد.) به یاخته هدف منتقل می شود که به دنبال رشد آن، گیاهی حاصل می شود که ویژگی های مطلوب ما را دارد.', '2026-02-11 21:03:16'),
(1106, 1033, 'گزینه&laquo;3&raquo; در تنفس یاخته ای، پمپ های زنجیره انتقال الکترون، پروتون ها را از بخش داخلی میتوکندری به فضای بین دو غشا جابه جا می کنند. این جابه جایی از طریق انتقال فعال و به دنبال مصرف انرژی حاصل از جابه جایی الکترون ها رخ می دهد. اما پیرووات هم، از طریق انتقال فعال از ماده زمینه سیتوپلاسم به میتوکندری وارد می شود. این انتقال فعال از طریق پروتئین هایی غیر از اجزای زنجیره انتقال الکترون انجام می گیرد. بررسی سایر گزینه ها: 1) گیرنده نهایی الکترون در تخمیر لاکتیکی، پیرووات است که نوعی بنیان اسیدی آلی سه کربنی می باشد. 2) در گلیکولیز، تولید اسید دوفسفاته (نوعی ماده سه کربنی) با ساخته شدن NADH (حاوی انرژی) همراه است. از طرفی، مصرف شدن این اسید طی قند کافت نیز منجر به تولید مولکول های ATP (حاوی انرژی) خواهد شد. 4) ATP می تواند در چرخۀ کالوین و یا قندکافت مصرف شود. به دنبال افزایش O2 ، ممکن است تنفس یاخته ای هم انجام شود که در این شرایط قندکافت هم رخ می دهد و در مرحله اول آن ATP مصرف می شود.', '2026-02-11 21:04:01'),
(1107, 1032, 'گزینه&laquo;3&raquo; باکتری های فتوسنتز کننده که سبب افزایش اکسیژن محیط می شوند، اکسیژن زا هستند که منبع الکترون آنها در فتوسنتز، آب (نوعی مولکول غیرآلی) است. بررسی سایر گزینه ها: 1) بعضی از سیانوباکتری ها طی فرایندهای تثبیت نیتروژن، نیتروژن جو (\\(N_2\\)) را به شکل یون آمونیوم (NH4+) تثبیت می کنند. سیانوباکتری ها فتوسنتز کننده هستند و برای ساخت مواد آلی از مواد معدنی از انرژی نور خورشید بهره می برند. 2) باکتری های گوگردی ارغوانی و سبز، گروهی از باکتری های فتوسنتز کننده غیر اکسیژن زا هستند که منبع الکترون در آن ها ترکیبی به غیر از آب (H2 S) است. رنگیزه فتوسنتزی این باکتری ها، باکتریوکلروفیل است. این گزینه را به دو حالت می توان رد کرد اولا، طبق این جمله، گروهی از باکتری ها وجود دارند که فتوسنتز کننده غیر اکسیژن زا هستند ولی خب گوگردی نیستند و ممکن است باکتریوکلروفیل نداشته باشند. از طرفی، باکتریوکلروفیل همه طیف های نوری را جذب نمی کند (مثل سایر رنگیزه ها در طول موج های خاصی، جذب نوری دارد). 4) همۀ جانداران تولید کننده (فتوسنتز کننده و شیمیوسنتز کننده)، از کربن دی اکسید برای تولید مواد آلی (تبدیل کربن به مواد قندی) می کنند. دقت کنید جذب نور توسط فتوسیستم ها، مربوط به جانداران فتوسنتز کننده است و در شیمیوسنتز کننده ها جذب انرژی نور توسط فتوسیستم ها مشاهده نمی شود. این جانداران در تاریکی و با استفاده از انرژی واکنش های اکسایشی، مواد آلی تولید می کنند.', '2026-02-11 21:04:12');
