(4921, 564, 'شناخت بیشتر تعامل های سودمند یا زیان مند بین عوامل زنده و غیرزنده محیط با گیاهان نهان دانه، به افزایش محصولات آن کمک خواهد کرد.', 0),
(4922, 564, 'در پزشکی شخصی با بهره گیری از مولکول دنا از روش های درمانی متفاوتی برای درمان افراد مبتلا به یک نوع بیماری خاص استفاده می شود.', 0),
(4923, 564, 'یکی از شرایط بررسی ساختارها و فرایندهای زیستی توسط پژوهشگران علوم تجربی، قابلیت مشاهده و اندازه گیری آنها است.', 0),
(4924, 564, 'هر نوع سوخت با منشأ مولکول های زیستی، مانع از افزایش کربن دی اکسید جو، آلودگی هوا و در نهایت مانع گرمایش زمین می شود.', 1),
(4925, 567, 'انواعی از مونوساکاریدها در توده غذایی درون آن - دریافت بی کربنات از کبد', 0),
(4926, 567, 'تولید پروتئازهای گوارشی غیر فعال - چین خوردگی های غیردائمی در درونی ترین فضای آن', 1),
(4927, 567, 'امکان تغییر فشار اسمزی توده بلعیده شده - حرکات آهسته و جلوبرنده مدفوع جامد', 0),
(4928, 567, 'یاخته های تولید کننده کلسترول و فسفولیپید - تولید نمک های صفراوی مؤثر در هضم چربی ها', 0),
(4929, 544, 'مواد در خلاف جهت شیب غلظت انتقال می یابند.', 1),
(4930, 544, 'با افزایش و یا کاهش سطح غشای یاخته همراه است.', 0),
(4931, 544, 'انرژی مورد نیاز آن همواره از مولکول ATP تأمین می شود.', 0),
(4932, 544, 'نتیجه نهایی آن، یکسان شدن غلظت ماده در دو سوی غشاست.', 0),
(4933, 540, 'هر ماهیچه بین دنده ای که به پرده های جنب نزدیک تر است، دنده ها را به سمت بالا و جلو جابه جا می کند.', 0),
(4934, 540, 'فقط برخی از ماهیچه هایی که به استخوان های دنده اتصال دارند، در کشیده شدن سطوح پایینی (تحتانی) ریه ها به سمت پایین نقش دارند.', 1),
(4935, 540, 'هر ماهیچه ای که بر تغییر وضعیت اندام های درون حفره شکمی تأثیرگذار است، فشار هوای درون شش ها را کاهش می دهد.', 0),
(4936, 540, 'فقط برخی از ماهیچه هایی که در افزایش حجم قفسه سینه دخیل هستند، منجر به بزرگ شدن شش ها می شوند.', 0),
(4937, 538, 'پس از ورود حجم هوای جاری می توان با دم عمیق وارد ریه ها کرد، بسیار بیشتر از حجم هوای درون شش ها پس از یک دم عادی است.', 0),
(4938, 538, 'با انقباض ماهیچه&zwnj;های شکمی در مجرای تنفسی فرد جابه&zwnj;جا می&zwnj;شود، تبادل گازها را در فاصله بین دو تنفس امکان&zwnj;پذیر می&zwnj;کند.', 0),
(4939, 538, 'بعد از پایان یک بازدم عمیق، در بخش مبادله&zwnj;ای باقی می ماند، کم تر از دو برابر حجم هوای وارد شده به شش ها طی یک دم عادی است.', 0),
(4940, 538, 'شخص می&zwnj;تواند پس از شروع متسع کردن شش تا حداکثر ممکن وارد شش&zwnj;ها کند، به کمک دم&zwnj;سنج قابل تعیین است.', 1),
(4941, 532, 'در مجاورت بخش محدب معده، سیاهرگی قرار دارد که خون خارج&zwnj;شده از اندام دارای دو بخش برون&zwnj;ریز و درون&zwnj;ریز را دریافت می&zwnj;کند.', 0),
(4942, 532, 'سیاهرگ فوق کبدی از به هم پیوستن دو سیاهرگ در خارج از کبد ایجاد می&zwnj;شود که سیاهرگ قطورتر، به بنداره انتهای مری نزدیک&zwnj;تر است.', 0),
(4943, 532, 'نقطه اتصال سیاهرگ&zwnj;های روده باریک به یکدیگر نسبت به محل دو شاخه شدن سیاهرگ باب، فاصله بیشتری از بنداره قرار گرفته در انتهای معده دارد.', 0),
(4944, 532, 'سیاهرگ خارج شده از اندام لنفی تخریب&zwnj;کننده گویچه قرمز، با عبور از جلوی معده، در مجاورت محل اتصال مجاری لنفی به&zwnj;هم، با سیاهرگ معده یکی می&zwnj;شود.', 1),
(4945, 526, 'باریک&zwnj;ترین بخش استخوان جناغ نسبت به ماهیچه دیافراگم در سطح پایین&zwnj;تری قرار دارد.', 0),
(4946, 526, 'محل دو&zwnj;شاخه&zwnj;شدن نای، پایین&zwnj;تر از محل اتصال دنده اول به استخوان جناغ قرار گرفته است.', 0),
(4947, 526, 'بخش بالایی استخوان منفرد قفسه سینه، چند&zwnj;ضلعی بوده و قاعده بزرگ&zwnj;تر آن در سطح بالاتری قرار دارد.', 0),
(4948, 526, 'غضروف دنده&zwnj;های ۶ تا ۱۰، به غضروف دنده بالاتر از خود متصل شده و به واسطۀ غضروف دنده ۵ به جناغ متصل می&zwnj;شوند.', 1),
