(4957, 528, 'در غدد روده. همانند غدد معده، فراوان&zwnj;ترین یاخته&zwnj;ها دارای هسته&zwnj;ای در راس خود هستند.', 0),
(4958, 528, 'غدد معده برخلاف غدد روده، در افزایش خاصیت قلیایی سد حفاظتی فاقد نقش هستند.', 1),
(4959, 528, 'غدد روده همانند غدد بزاقی، گلوکز موجود در لوله گوارش را مستقیماً افزایش می&zwnj;دهند.', 0),
(4960, 528, 'غدد بزاقی برخلاف غدد معده، تحت تأثیر دستگاه عصبی خود مختار قرار می&zwnj;گیرند.', 0),
(4961, 523, 'هوا با فشار همراه با مواد خارجی از طریق بینی به بیرون رانده می&zwnj;شود.', 0),
(4962, 523, 'به عنوان برخی از سازوکارهای نخستین خط دفاعی بدن محسوب می&zwnj;شوند.', 1),
