(4964, 523, 'به وقوع پیوستن آن&zwnj;ها، نیاز به انقباض ماهیچه&zwnj;های بین دنده&zwnj;ای خارجی و شکمی دارد.', 0),
(4965, 506, 'تجمع آن در بخش&zwnj;های مختلف بدن، امکان آزاد شدن نوعی پیک شیمیایی در محل مفاصل را افزایش می&zwnj;دهد.', 1),
(4966, 506, 'همراه با گلوکز از فواصل میان زوائد پامانند یاخته&zwnj;های پودوسیت در بخشی قیف&zwnj;مانند عبور می&zwnj;کند.', 0),
(4967, 506, 'تولید آن در نوعی اندام با دو لوب نامتقارن در سمت راست بدن صورت می&zwnj;گیرد.', 0),
(4968, 506, 'تشکیل آن با کاهش همزمان دو مادۀ دفعی بدن به شکل همزمان همراه است.', 0),
(4969, 502, 'همه یاخته&zwnj;های دارای غشای پایۀ مشترک با یاخته&zwnj;های دیواره مویرگ&zwnj;های اطراف حبابک، با منافذ رابط در میان حبابک&zwnj;ها مجاورت دارند.', 0),
(4970, 502, 'همه یاخته&zwnj;های دارای شبکه&zwnj;ای از کیسه&zwnj;ها و لوله&zwnj;های غشایی در سیتوپلاسم، توانایی تولید مولکول&zwnj;های سازنده غشای پایه را دارند. کنند.', 0),
(4971, 502, 'همه یاخته&zwnj;های دارای زوائد ریز در سطح غشایی خود، با ترشح نوعی ماده در تسهیل تبادل گازهای تنفسی شرکت می&zwnj;کنند.', 0),
(4972, 502, 'همۀ یاخته&zwnj;های دارای گیرنده برای پیک&zwnj;های شیمیایی دوربرد، توانایی عبور انواعی از گازهای تنفسی از غشای خود را دارند.', 1),
(4973, 503, 'هر رگی که محتویات خود را به کبد وارد می&zwnj;کند، می&zwnj;تواند حاوی مواد جذب شده از بخش&zwnj;هایی از لوله گوارش باشد.', 0),
(4974, 503, 'هر رگی که محتویات نوعی اندام لنفی را از جلوی معده عبور می&zwnj;دهد، می&zwnj;تواند مواد دفعی انحنای کوچک&zwnj;تر معده را نیز دریافت کند.', 0),
(4975, 503, 'هر رگ متصل به روده باریک که توانایی حمل پیک&zwnj;های شیمیایی دوربرد را دارد، می&zwnj;تواند محتویات خروجی از نوعی اندام لنفی را نیز دریافت کند.', 0),
(4976, 503, 'هر رگ مرتبط با کبد که در تغییر ترکیبات موجود در این اندام مؤثر است، می&zwnj;تواند حاوی پیک&zwnj;های شیمیایی ترشح&zwnj;شده از یاخته&zwnj;های درون&zwnj;ریز باشد.', 1),
(4977, 504, 'بزرگ&zwnj;ترین ماهیچه تنفسی فرد در کمترین فاصله ممکن تا قلب قرار دارد.', 1),
(4978, 504, 'حجمی در حدود ۳۵۰۰ میلی&zwnj;لیتر از ظرفیت کل شش&zwnj;های فرد خالی مانده است.', 0),
(4979, 504, 'طول ماهیچه&zwnj;های بین دنده&zwnj;ای خارجی تحت اثر دستگاه عصبي پیکری کاهش یافته است.', 0),
(4980, 504, 'استخوان&zwnj;های دنده فرد در نمای جلویی بدن، به مستقیم&zwnj;ترین حالت قرارگیری خود قابل مشاهده هستند.', 0),
(4981, 500, 'اولین بخش لوله&zwnj;ای آن پیچ&zwnj;خوردگی&zwnj;هایی دارد که نسبت به بخش لوله هنله به لگنچه نزدیک&zwnj;تر است.', 0),
(4982, 500, 'در هر بخش لوله&zwnj;ای و فاقد پیچ&zwnj;خوردگی آن، قطر به طور پیوسته از بالا به پایین تغییر پیدا می&zwnj;کند.', 0),
(4983, 500, 'هر بخش قطور هنله، محتویات خود را از بخشی پیچ&zwnj;خورده دریافت یا به آن وارد می&zwnj;کند.', 1),
(4984, 500, 'اولین بخش آن سرخرگ آوران و و ایران را به طور کامل در خود جای داده است.', 0),
