(25567, 5552, 'فرمول شیمیایی ترکیب یونی حاصل به‌صورت $A_2D_3$ است.', 0),
(25568, 5552, 'عنصر A می‌تواند عنصری فلزی مانند Al، Fe یا Cr باشد.', 0),
(25569, 5552, 'در ترکیب یونی حاصل، آنیون و کاتیون می‌توانند آرایش الکترونی یکسانی داشته باشند.', 0),
(25570, 5552, 'به ازای دادوستد ۶ مول الکترون، یک مول ترکیب یونی تشکیل می‌شود.', 0),
(25571, 5553, 'هرچه دمای ستاره‌ای بیشتر باشد، شرایط تشکیل عنصرهای سنگین‌تر مثل آهن و طلا فراهم می‌شود.', 0);
INSERT INTO `options_tam24` (`id`, `question_id`, `option_text`, `is_correct`) VALUES
(25572, 5553, 'ایزوتوپ‌های یک عنصر در خواص فیزیکی وابسته به جرم، مانند چگالی با یکدیگر تفاوت دارند.', 0),
(25573, 5553, 'در بین ایزوتوپ‌های ساختگی هیدروژن، نیم‌عمر $^5_1H$ از بقیه بیشتر است.', 0),
(25574, 5553, 'همۀ هسته‌هایی که نسبت شمار نوترون‌ها به پروتون‌های آن‌ها برابر یا بیش از ۱/۵ باشد، ناپایدارند و با گذشت زمان متلاشی می‌شوند.', 0),
(25575, 5554, 'مدل بور با موفقیت توانست طیف نشری خطی هیدروژن و چند عنصر ساده دیگر را توجیه کند.', 0),
(25576, 5554, 'ساده‌ترین اتم، تنها دارای یک ذره باردار و یک ذره خنثی است.', 0),
(25577, 5554, 'در مدل ساختار لایه‌ای اتم، لایه‌ها از هسته به سمت بیرون شماره‌گذاری شده و شمارۀ هر لایه را با n نمایش می‌دهند.', 1),
(25578, 5554, 'نیلزبور به دنبال توجیه طیف نشری خطی هیدروژن، ساختار لایه‌ای را برای اتم ارائه کرد.', 0),
