(47436, 6366, 'بیشتر نفت صادراتی کشور ایران، از نوع C است.', 0),
(47437, 6366, 'نفت B را می‌توان در دستهٔ نفت سبک قرار داد.', 1),
(47438, 6366, 'قیمت نفت D، در مقایسه با دیگر نفت‌ها بیشتر است.', 0),
(47439, 6366, 'به منظور تهیهٔ سوخت هواپیما، پالایش نفت A، مناسب‌تر است.', 0),
(47440, 6365, 'مجموع عددهای به کار رفته در نام آیوپاک آن، برابر با ۹ است.', 0),
(47441, 6365, 'برای سوختن کامل هر مول از آن در STP، به ۴۰ مول گاز اکسیژن نیاز است.', 0),
(47442, 6365, 'شمار اتم‌های هیدروژن در یکی از شاخه‌های فرعی آن، با شمار اتم‌های کربن زنجیر اصلی برابر است.', 1),
(47443, 6365, 'تفاوت شمار اتم‌های هیدروژن و کربن در آن، با مجموع شمار اتم‌ها در مولکول بنزآلدهید برابر است.', 0),
