(48868, 8444, 'عامل محافظت کننده از کلیه که دارای بافت استخوانی است، به یک میزان از دو کلیه محافظت می‌کند.', 0),
(48869, 8444, 'عامل محافظت کننده از کلیه، از یاخته‌هایی با توانایی تولید انواعی از رشته‌های پروتئینی تشکیل شده است.', 0),
(48870, 8444, 'بخش متصل به لگنچه، در دیواره خود دارای یاخته‌هایی ماهیچه‌ای است که ظاهری منشعب و دوکی دارند.', 0),
(48871, 8444, 'شبکه مویرگی در ارتباط با گردیزه، برخلاف شبکه مویرگی موجود در کبد بین دو بخش با خون روشن قرار گرفته است.', 0),
(48872, 8445, 'در فرایند تراوش برخلاف بازجذب، ورود مواد به درون گردیزه می‌تواند بدون هیچ انتخابی صورت گیرد.', 0),
(48873, 8445, 'در فرایند بازجذب همانند ترشح، شبکه مویرگی دورلوله‌ای به طور حتم نقش مستقیم ایفا می‌کند.', 0),
(48874, 8445, 'در فرایند ترشح همانند تراوش، ورود مواد به درون بخش‌های مختلف گردیزه باعث افزایش حجم ادرار می‌گردد.', 0),
(48875, 8445, 'در فرایند تراوش برخلاف ترشح، ورود مواد به طور حتم از طریق نوعی شبکه مویرگی به درون گردیزه‌ها صورت می‌گیرد.', 0),
(48876, 8446, 'در رشته‌های بلند، اندامک‌های تولید کننده $CO_{2}$ وجود دار', 0),
(48877, 8446, 'محل ذخیره اطلاعات یاخته، به صورت کشیده، مشاهده می‌شود.', 0),
(48878, 8446, 'فضای میان رشته‌ها در جابه‌جایی مواد بین مویرگ و بافت نقش دارد.', 0),
(48879, 8446, 'هسته‌ای دارند که معمولاً در مرکز یاخته قرار گرفته است.', 0),
(48880, 8447, 'همانند – از یک سمت به کلافک برخورد می‌کند.', 0),
(48881, 8447, 'همانند – دارای خون با $CO_{2}$ کم و $O_{2}$ زیاد است.', 0),
(48882, 8447, 'برخلاف – خون را به درون کلافک وارد می‌کند.', 0),
(48883, 8447, 'برخلاف – به مویرگ بین لوله‌های پیچ‌خورده منتهی می‌شود.', 0),
(48884, 8448, 'بیشتری – بیشتری – سرخرگ آوران', 0),
(48885, 8448, 'کمتری – برابری – مویرگ‌های کلافک', 0),
(48886, 8448, 'بیشتری – کمتری – سرخرگ وابران', 0),
(48887, 8448, 'کمتری – بیشتری – سرخرگ کلیوی', 0),
(48888, 8449, 'ترکیب شیمیایی مایع اطراف سلول‌ها حدوداً ثابت است.', 0),
(48889, 8449, 'کلیه راست به دلیل موقعیت قرارگیری کبد با تعداد دنده‌های بیشتری محافظت می‌شود.', 0),
(48890, 8449, 'هر دو کلیه در مجموع از حدود یک میلیون گردیزه تشکیل شده‌اند.', 0),
(48891, 8449, 'سرخرگ کلیه تنها در بخش مرکزی به انشعابات کوچک‌تر تقسیم می‌شود.', 0),
(48892, 8450, 'همانند شبکه مویرگی اول مویرگ‌های پیوسته دارد.', 0),
(48893, 8450, 'برخلاف شبکه مویرگی اول، فشار خون در طول آن متفاوت است.', 0),
(48894, 8450, 'در اطراف لوله پیچ خورده دور و نزدیک دارای خون روشن است.', 0),
(48895, 8450, 'در سراسر لوله هنله برخلاف مجرای جمع‌کننده ادرار دیده می‌شود.', 0),
(48896, 8451, 'ارسال پیام تحریکی اعصاب خودمختار توسط ریشه شکمی نخاع', 0),
(48897, 8451, 'کاهش میزان انقباض یاخته‌های بنداره موجود در ابتدای میزراه', 0),
(48898, 8451, 'هدایت پیام عصبی به نخاع توسط ریشه پشتی عصب نخاعی', 0),
(48899, 8451, 'تحریک نورون‌های حرکتی مرتبط با بنداره خارجی میزراه', 0),
(48900, 8452, 'در هر مرحله‌ای که با ورود مواد به بخشی از گردیزه در ناحیه قشری کلیه همراه است، فعالیت یاخته‌های پودوسیت دیده می‌شود.', 0),
(48901, 8452, 'در هر مرحله‌ای که جابه‌جایی یک‌طرفه مواد بین خون و گردیزه انجام می‌شود، خروج خوناب از داخل کلافک رخ می‌دهد.', 0),
(48902, 8452, 'در هر مرحله‌ای که در جهت مخالف فرایند بازجذب رخ می‌دهد، تمامی مواد جابه‌جا شده از خوناب منشأ گرفته‌اند.', 0),
(48903, 8452, 'در هر مرحله‌ای که مواد دفعی به نفرون وارد می‌شوند، نوعی شبکه مویرگی مرتبط با سرخرگ وابران نقش ایفا می‌کند.', 0),
(48904, 8453, 'تنها - واجد انواع یاخته های مختلف با اشکال گوناگون در ساختار خود است.', 0),
(48905, 8453, 'بیش از- از یاخته های منشعبی تشکیل شده که ماده زمینه ای را ترشح می کنند.', 0),
(48906, 8453, 'تنها - ماده زمینه ای فراوانی دارند که فاصله بین یاخته های پیوندی را پر کرده است.', 0),
(48907, 8453, 'بیش از - دارای یاخته هایی با هسته غیرمرکزی و فضای بین سلولی متغیر است.', 0),
(49000, 8477, 'مولکولی با نقش و واحد سازنده مشابه گلیکوژن را تجزیه می‌کنند.', 0),
(49001, 8477, 'در بعضی از دیسه (پلاست)های خود، انواعی از رنگیزه‌ها را نگه می‌دارند.', 0),
(49002, 8477, 'بیشتر مواد مغذی مورد نیاز خود را از طریق ریشه از خاک جذب می‌کنند.', 0),
(49003, 8477, 'بیشتر حجم همه یاخته‌های زنده آن توسط واکوئولی درشت اشغال شده است.', 0),
(49016, 8481, 'افتراق - وجود یاخته‌های پارانشیمی و از نوع نرده‌ای', 0),
(49017, 8481, 'اشتراک - تغییر نوع بافت پوششی به دنبال افزایش سن گیاه', 0),
(49018, 8481, 'اشتراک - وجود فضاهایی هوادار در مجاورت یاخته‌های روپوستی', 0),
(49019, 8481, 'افتراق - پوشیده شدن روزنه‌های هوایی با پوستکی لیپیدی و ضخیم', 0),
(49024, 8483, 'برگ - توانایی بازگشت به حالت اولیه، پس از وارد شدن نیرو بیشتر', 0);
