(59409, 10323, 'نتیجۀ نهایی آن، یکسان‌شدن غلظت ماده در دو سوی غشاست.', 0),
(59410, 10324, 'اثر عوامل غیرزنده - جاندارانی با ژن‌های گوناگون در اجتماعات متفاوت با یکدیگر تعامل پیچیده دارند.', 0),
(59411, 10324, 'امکان تولیدمثل و زادآوری - جاندارانی هم‌گونه مشاهده می‌گردند که در یک مکان و زمان خاص زندگی می‌کنند.', 0),
(59412, 10324, 'تعامل گونه‌های مختلف جانوری - اثر عواملی مانند دما و نور بر فعالیت‌های درون‌یاخته‌ای جانور قابل مشاهده نیست.', 1),
(59413, 10324, 'ارتباط میان یاخته‌ها درون ترکیبی مایع - دستگاه‌های مجزای پیکر آن با تولید و ترشح موادی بر عملکرد یکدیگر اثرگذار هستند.', 0),
(59414, 10325, 'هر مولکول زیستی واجد عنصر فسفر، نوعی نوکلئیک اسید و دارای همۀ انواع عناصر موجود در پروتئین‌ها است.', 0),
(59415, 10325, 'هر مولکول زیستی که در جوانۀ جو یافت می‌شود، تنوع عناصر یکسان با مهم‌ترین لیپید ذخیره‌کنندۀ انرژی دارد.', 0),
(59416, 10325, 'هر مولکول متشکل از چندین گلوکز در سیب‌زمینی، در کاغذسازی و تولید پارچه‌ها مورد استفاده قرار می‌گیرد.', 0),
(59417, 10325, 'هر مولکول لیپیدی مورد استفاده برای تولید هورمون‌ها، توسط شبکۀ آندوپلاسمی فاقد رناتن تولید شده است.', 1),
(59418, 10326, 'شناخت بیشتر تعامل‌های سودمند یا زیان‌مند بین عوامل زنده و غیرزندۀ محیط با گیاهان نهان‌دانه، به افزایش محصولات آن کمک خواهد کرد.', 0),
(59419, 10326, 'در پزشکی شخصی با بهره‌گیری از مولکول دنا از روش‌های درمانی متفاوتی برای درمان افراد مبتلا به یک نوع بیماری خاص استفاده می‌شود.', 0),
(59420, 10326, 'یکی از شرایط بررسی ساختارها و فرایندهای زیستی توسط پژوهشگران علوم تجربی، قابلیت مشاهده و اندازه‌گیری آن‌ها است.', 0),
(59421, 10326, 'هر نوع سوخت با منشأ مولکول‌های زیستی، مانع از افزایش کربن دی‌اکسید جو، آلودگی هوا و در نهایت مانع گرمایش زمین می‌شود.', 1),
(59422, 10327, 'فقط یک لایه یاختۀ پوششی آن در تماس با غشای پایه قرار دارد، هستۀ همۀ یاخته‌ها تقریباً در یک سطح قرار گرفته است', 0),
(59423, 10327, 'طول، عرض و ارتفاع یاخته‌ها با هم تقریباً برابر است، هستۀ گرد هر یاخته در بخش مرکزی آن مشاهده خواهد شد', 1),
(59424, 10327, 'طول همۀ یاخته‌های تشکیل‌دهندۀ آن از قطرشان بیشتر است، در ساخت مخاط سرتاسر لولۀ گوارش به کار رفته است', 0),
(59425, 10327, 'همۀ یاخته‌های آن در تماس مستقیم با غشای پایه هستند، اندازۀ هستۀ یاخته‌های آن تقریباً با یکدیگر برابر است', 0),
