(60516, 10601, 'در دوران جنینی برخلاف بلوغ در تولید کوچک‌ترین یاخته‌های خونی نقش دارد.', 0),
(60517, 10601, 'نوعی ماده معدنی حاصل از تخریب گویچه‌های قرمز می‌تواند در آن ذخیره شود که به‌عنوان کوآنزیم برخی کاتالیزورهای زیستی عمل می‌کند.', 0),
(60518, 10601, 'تحت‌تأثیر آن اندام لوبیایی‌شکل پشت حفره شکمی که در سمت چپ قرار دارد از محافظت توسط دنده یازدهم خارج می‌شود.', 0),
(60519, 10601, 'در آن مویرگ‌هایی یافت می‌شود که غشای پایه ناقص داشته و فاصله بین یاخته‌های سنگ‌فرشی آن به‌صورت حفره درآمده است.', 0),
(60520, 10602, 'امکان دارد که در بخشی از چرخه، دریچه‌های دهلیزی - بطنی هم‌زمان با دریچه‌های سینی باز باشند.', 0),
(60521, 10602, 'امکان دارد که در بخشی از چرخه، دریچه‌های دهلیزی - بطنی با دریچه‌های سینی هم‌زمان بسته باشند.', 0),
(60522, 10602, 'امکان ندارد که در بخشی از چرخه، دریچه‌های دهلیزی - بطنی بسته و هم‌زمان سینی‌ها باز باشند.', 0),
(60523, 10602, 'امکان ندارد که در بخشی از چرخه، دریچه‌های دهلیزی - بطنی باز و هم‌زمان سینی‌ها بسته باشند.', 0),
(60524, 10603, 'مجموع زمان انقباض بطنی و استراحت عمومی برابر با زمان استراحت دهلیز است.', 0),
(60525, 10603, 'تعداد قطعات سازنده هر دریچه سینی برابر با تعداد سیاهرگ‌های واردکننده خون به حفره دهلیز چپ است.', 0),
(60526, 10603, 'ماهیچه قلبی در تمام طول زندگی هیچ‌گاه استراحتی پیوسته همانند استراحت ماهیچه اسکلتی نخواهد داشت.', 0),
(60527, 10603, 'به‌طور میانگین در حالت استراحت فرد، در هر دقیقه 10 لیتر خون از قلب وارد رگ‌ها می‌شود.', 0),
(60528, 10604, 'گویچه سفید - بزرگ‌ترین اندازه را در میان کل گویچه‌های خونی دارد - دارای زوائد سیتوپلاسمی است', 0),
(60529, 10604, 'دارای هسته با بیش از یک قسمت - در خون یافت می‌شود - دانه‌هایی در سیتوپلاسم خود دارد', 0),
(60530, 10604, 'حاصل از یاخته بنیادی میلوئیدی - درشت‌ترین دانه‌ها را دارد - دارای هسته دوقسمتی دمبلی است', 0),
(60531, 10604, 'منشأ تولید قطعات بی‌رنگ و بی‌هسته - در رگ‌ها دیده نمی‌شود - شباهت زیادی به یاخته بنیادی دارد', 0),
(60532, 10605, 'هیچ‌یک از مسیرهای بین‌گرهی، در انتقال جریان الکتریکی به دهلیز چپ نقشی ندارند.', 0),
(60533, 10605, 'دسته تارهای تخصص‌یافته‌ای که از گره بزرگ‌تر منشأ می‌گیرند، توانایی شروع پیام‌های الکتریکی را ندارند.', 0),
(60534, 10605, 'دسته‌هایی از تارهای عضلانی تخصص‌یافته، جریان الکتریکی را از گره سینوسی - دهلیزی به دهلیز چپ هدایت می‌کنند.', 0),
(60535, 10605, 'اغلب دسته‌های تارهای تخصص‌یافته موجود در دیواره دهلیزها، در انتقال جریان الکتریکی به گره دهلیزی - بطنی نقش دارند.', 0),
(60536, 10606, 'جریان مواد به درون مویرگ، قبل و بعد از این نقطه مشاهده می‌شود.', 0),
(60537, 10606, 'در نقطه مجاور قبل از آن، کمترین میزان خروج مواد از مویرگ مشاهده می‌شود.', 0),
(60538, 10606, 'با دور شدن از این نقطه، به‌تدریج از میزان ورود مواد به درون مویرگ کاسته می‌شود.', 0),
(60539, 10606, 'در دو سمت این نقطه، مقادیر یکسانی از مواد بین خون و مایع بین‌یاخته‌ای مبادله می‌شود.', 0),
(60540, 10607, 'منحصراً در سمت چپ بدن قابل مشاهده است', 0),
(60541, 10607, 'خون آن در ابتدا از راه سیاهرگ باب به کبد وارد می‌شود', 0),
(60542, 10607, 'در هر رگی که در ارتباط با آن قرار دارد، گویچه‌های قرمزی فاقد هسته و کروی مشاهده می‌شوند', 0),
(60543, 10607, 'در جلوگیری از خیز (ادم) و تورم بافت‌های بدن مؤثر است', 0),
(60544, 10608, 'همانند - می‌تواند گویچه‌های سفید بدون دانه تولید کند.', 0),
(60545, 10608, 'برخلاف - در تولید قطعات یاخته‌ای بی‌رنگ، نقش دارند.', 0),
(60546, 10608, 'همانند - می‌تواند یاخته بدون هسته تولید کند.', 0),
(60547, 10608, 'برخلاف - از یاخته بنیادی مغز استخوان به‌وجود می‌آید.', 0),
(60548, 10609, 'در خون یک انسان سالم به‌طور طبیعی پروتئین‌های فیبرین و پروترومبین، عامل ایجادکننده فشار اسمزی خوناب هستند.', 0),
(60549, 10609, 'آنزیم پروترومبیناز همانند فیبرین یک عامل فعال‌کننده پروتئین‌ها است که تنها از گرده‌های آسیب‌دیده رها می‌شود.', 0),
(60550, 10609, 'در خون‌ریزی‌های شدید فیبرین در حضور یون K باعث ایجاد لخته و جلوگیری از خون‌ریزی بیشتر می‌شود.', 0),
(60551, 10609, 'در خون‌ریزی‌های شدید برای فرایند انعقاد هم به عوامل آلی و هم به عوامل معدنی نیاز است.', 0),
(60552, 10610, '«الف» برخلاف تارهای صوتی نتیجه چین‌خوردگی بافتی است که فاصله بین یاخته‌های آن کم است.', 0),
(60553, 10610, 'دریچه «ب» همانند «د» توسط طناب‌های ارتجاعی به برآمدگی‌های ماهیچه‌ای درون بطن اتصال دارند.', 0),
(60554, 10610, 'رگ‌های غذادهنده قلب بعد از دریچه «ج» قرار دارد.', 0),
(60555, 10610, 'تحریک اعصاب دریچه «د» همانند «ب» می‌تواند سبب باز یا بسته شدن این دو دریچه شود.', 0),
