(60571, 10614, 'الف و ب و ج و د', 0),
(60572, 10615, 'بلافاصله در سطح جلویی بطن‌ها قرار گرفته است. - لنف خود را به مجرای لنفی راست تخلیه می‌کند.', 0),
(60573, 10615, 'قابلیت ترشح پیک‌های شیمیایی دوربرد را دارد. - مجرای لنفی چپ از سطح عقبی‌تر از نیمهٔ راست آن عبور می‌کند.', 0),
(60574, 10615, 'از دو لوب با اندازه‌های گوناگون تشکیل شده است. - در سطح پایین‌تر از محل اتصال دو سیاهرگ زیرترقوه‌ای به هم، قرار دارد.', 0),
(60575, 10615, 'محل افزوده‌شدن پروتئین به غشای بعضی لنفوسیت‌ها می‌باشد. - کاملاً در سطح بالاتر از محل منشعب‌شدن نای دیده می‌شود.', 0),
(60576, 10616, 'در نقطهٔ C برخلاف A، فشار خون در بزرگ‌ترین سرخرگ خروجی از قلب در حال افزایش است.', 0),
(60577, 10616, 'در نقطهٔ A برخلاف B، دریچه‌های دهلیزی‌بطنی از بازگشت خون به حفرات دهلیزی جلوگیری می‌کنند.', 0),
(60578, 10616, 'در نقطهٔ B همانند D، به دنبال انقباض یاخته‌های دیوارهٔ دهلیزها، خون درون بطن‌های قلب تجمع پیدا می‌کند.', 0),
(60579, 10616, 'در نقطهٔ D همانند C، فقط برخی دریچه‌های بین حفرات قلب، اجازهٔ عبور خونی با غلظت $CO_2$ زیاد از خود را می‌دهند.', 0),
(60580, 10617, 'رشته‌های کشسان سرخرگ آئورت تخریب شوند، اختلاف فشار خون آن، در زمان انقباض و استراحت بطن کاهش می‌یابد.', 0),
(60581, 10617, 'ماهیچه‌های صاف سرخرگ‌های کوچک، دیرتر از حالت معمول از انقباض خارج شوند، مصرف $ATP$ در کبد تحریک می‌شود.', 0),
(60582, 10617, 'در پی مصرف ترکیبات نمکی، فشار خون دچار تغییر شود، احتمال تجمع مایع در فضای بین یاخته‌های اندام‌های فرد زیاد می‌شود.', 0),
(60583, 10617, 'مقدار رشته‌های کشسان سرخرگ‌های کوچک بیشتر از حالت عادی شود، مقاومت دیوارهٔ آن‌ها در برابر جریان خون کاهش پیدا می‌کند.', 0),
(60584, 10618, '1', 0),
(60585, 10618, '2', 0),
(60586, 10618, '3', 0),
(60587, 10618, '4', 0),
(60588, 10619, 'هستهٔ تکی خمیده یا لوبیایی - زوائد سیتوپلاسمی کوتاه‌تری', 0),
(60589, 10619, 'بیش‌ترین نسبت حجم هسته به سیتوپلاسم یاخته را - منشأ متفاوتی', 0),
(60590, 10619, 'سیتوپلاسم با دانه‌های ریز - هسته‌ای با بیش‌ترین تعداد قسمت', 0),
(60591, 10619, 'هستهٔ با قسمت‌های روی هم افتاده - درون سیتوپلاسم خود دانه‌های درشت‌تری', 0),
(60592, 10620, 'یک بطن خون را از قلب خارج می‌کند، خون با خروج از اندام تنفسی به سمت یاخته‌های سایر بخش‌های بدن هدایت می‌شود.', 0),
(60593, 10620, 'دو دهلیز خون را از رگ(های) خونی دریافت می‌کنند، حفظ فشار خون در سامانهٔ گردشی آن‌ها نسبت به سایرین آسان‌تر است.', 0),
(60594, 10620, 'بطن خون را از مدخل‌های بیشتری دریافت می‌کند، سه نوع خون مختلف از نظر کیفیت اکسیژن و کربن دی اکسید وجود دارد.', 0),
(60595, 10620, 'یک دیواره جدایی کامل بطن‌ها را ایجاد می‌کند، بطن‌ها خون پر اکسیژن و بدون $CO_2$ را با فشار متفاوتی از خون تیره پمپ می‌کنند.', 0),
(60596, 10621, 'همهٔ - بخشی از ترکیبات تراوش‌شده به فضای بین یاخته‌ها، در همان محل بازجذب می‌گردد.', 0),
(60597, 10621, 'فقط بعضی از - به علت ارتباط تنگاتنگ بین یاخته‌های خود، ورود و خروج مواد را به شدت تنظیم می‌کنند.', 0),
(60598, 10621, 'فقط بعضی از - دارای شبکه‌ای ناقص از رشته‌های پروتئینی و گلیکوپروتئینی در زیر یاخته‌های پوششی خود هستند.', 0),
(60599, 10621, 'همهٔ - ماهیچه‌های نازک و جریان خون کند، امکان تبادل مناسب مواد در فاصلهٔ بین دو نوع رگ خونی را فراهم می‌کند.', 0),
(60600, 10622, 'رگ‌های خونی حاوی خون روشن، تنها در لایهٔ میانی خود رشته‌های کشسان دارند.', 0),
(60601, 10622, 'رگ‌های واجد دریچه در ابتدای خود، بریدگی آن‌ها باعث می‌شود تا خون با سرعت زیاد از آن‌ها خارج گردد.', 0),
(60602, 10622, 'بزرگ‌ترین رگ‌های خونی واجد خون تیره، دیواره‌ای با کشسانی زیاد داشته که تغییر حجم آن به صورت نبض در طول آن حس می‌شود.', 0),
(60603, 10622, 'پرتعدادترین رگ‌های خونی، به دسته‌ای از رگ‌ها تعلق دارند که بیشتر به صورت گرد بوده و در قسمت‌های سطحی بدن دیده می‌شوند.', 0),
(60604, 10623, 'همهٔ - با تغییر در میزان تولید تکانه‌های الکتریکی طبیعی در گره مجاور دریچه سه لختی، در تغییر برون ده قلبی نقش دارند.', 0),
(60605, 10623, 'یکی از - ضمن تأثیر بر رگ‌های کوچک با فضای درونی وسیع، تنظیم جریان موضعی بافت‌ها را انجام می‌دهد.', 0),
(60606, 10623, 'یکی از - می‌تواند در برخورد با مواد شیمیایی فشارخون برخی رگ‌های بدن را حفظ کند.', 0),
(60607, 10623, 'همهٔ - با آزادشدن ترکیبات شیمیایی به درون رگ‌های خونی، همراه هستند.', 0);
