INSERT INTO `options_tam24` (`id`, `question_id`, `option_text`, `is_correct`) VALUES
(62604, 11040, '۱) فقط اگر مسئول حفظ هم‌ایستایی باشند، توانایی عبور یون‌های مختلفی از غشای خود را دارند.', 0),
