(66143, 11876, 'چهار', 0),
(66144, 11877, 'گریفیت همانند مزلسون و استال، از نوعی باکتری کروی با پوششی در اطراف غشای یاخته‌ای استفاده کرد.', 0),
(66145, 11877, 'ایوری و همکارانش همانند مزلسون و استال، مواد باکتریایی را با استفاده از گریزانه (سانتریفیوژ) با سرعت بالا، از یکدیگر جدا کردند.', 1),
(66146, 11877, 'ویلکینز و فرانکلین برخلاف واتسون و کریک، تصویری تهیه کردند که در آن، رشته‌های دنا (DNA) به‌صورت خطوط پیوسته دیده می‌شدند.', 0),
(66147, 11877, 'مزلسون و استال برخلاف واتسون و کریک، مطالعه‌ای داشتند که با استفاده از نتایج آن، همانندسازی دنا (DNA) تا حد زیادی قابل توضیح است.', 0),
(66148, 11878, 'در همانندسازی نیمه‌حفاظتی همانند همانندسازی حفاظتی، دو مولکول دنا (DNA)ی حاصل همانندسازی، چگالی یکسانی دارند.', 0),
(66149, 11878, 'در همانندسازی غیرحفاظتی برخلاف همانندسازی نیمه‌حفاظتی، دو رشتهٔ سازندهٔ هر مولکول دنا (DNA)ی جدید وزن برابری دارند.', 1),
(66150, 11878, 'در همانندسازی پراکنده همانند همانندسازی نیمه‌حفاظتی، تغییری در وزن دو رشتهٔ پلی‌نوکلئوتیدی دنا (DNA)ی اولیه ایجاد می‌شود.', 0),
(66151, 11878, 'در همانندسازی حفاظتی برخلاف همانندسازی پراکنده، توالی نوکلئوتیدی رشته‌های دارای وزن برابر در دنا (DNA)ی جدید یکسان است.', 0),
(66152, 11879, 'کنار هم قرار گرفتن قسمت‌های مختلف پروتئین به‌صورت به هم پیچیده، مربوط به ساختار سوم است.', 1),
(66153, 11879, 'تشکیل پیوندهای هیدروژنی بین بخش‌های مختلف پلی‌پپتید، فقط در ساختار دوم رخ می‌دهد.', 0),
(66154, 11879, 'تغییر آمینواسید در ساختار اول آن‌ها، تأثیری بر فعالیت پروتئین ندارد.', 0),
(66155, 11879, 'پیدایش ثبات نسبی پروتئین، در ساختار نهایی آن‌ها رخ می‌دهد.', 0),
(66156, 11880, 'تأثیر آن در شکل‌دهی پروتئین به ماهیت شیمیایی گروه $\\text{R}$ بستگی دارد.', 0),
(66157, 11880, 'با استفاده از روش‌های شیمیایی می‌توان جایگاه هر اتم آن‌ها را مشخص کرد.', 0),
(66158, 11880, 'ویژگی‌های منحصربه‌فرد آن‌ها مربوط به گروه $\\text{R}$ متصل به کربن مرکزی می‌باشد.', 1),
(66159, 11880, 'فقط از طریق دو نوع از گروه‌های متصل به کربن مرکزی می‌توانند پیوند هیدروژنی تشکیل دهند.', 0),
(66160, 11881, '۱', 0),
(66161, 11881, '۲', 1),
(66162, 11881, '۳', 0),
(66163, 11881, '۴', 0),
(66164, 11882, 'نوکلئیک‌اسیدهای خود را درون فضایی با قطر حدود ۴۰۰ نانومتر نگه‌داری می‌کند.', 1),
(66165, 11882, 'از طریق خارجی‌ترین پوشش خود می‌تواند به سطح یاخته‌های پوششی بچسبد.', 0),
(66166, 11882, 'در اطراف غشای خود، دو پوشش با ضخامت و جنس متفاوت دارد.', 0),
(66167, 11882, 'همانند نوع غیربیماری‌زا، ژن‌هایی مؤثر در بیماری‌زایی دارد.', 0),
(66168, 11883, 'از آنزیم تخریب کنندهٔ پروتئین استفاده شد، توانستند - پروتئین‌ها مادهٔ وراثتی نیستند.', 1),
(66169, 11883, 'مواد عصارهٔ باکتری‌ها به‌صورت لایه‌لایه جدا شدند، نتوانستند - عامل اصلی انتقال صفات وراثتی، مولکول دنا (DNA) است.', 0),
(66170, 11883, 'نوکلئیک‌اسیدهای عصارهٔ استخراج‌شده از باکتری‌ها را تخریب کردند، توانستند - مادهٔ وراثتی می‌تواند به یاختهٔ دیگری منتقل شود.', 0),
(66171, 11883, 'عصارهٔ باکتری‌های پوشینه‌دار (کپسول‌دار) را به محیط کشت اضافه کردند، توانستند - اطلاعات وراثتی در دنا (DNA) ذخیره می‌شوند.', 0),
(66172, 11884, 'بررسی تصاویر تهیه‌شده با پرتو ایکس ابعاد دو رشتهٔ سازندهٔ دنا را مشخص کرد.', 0),
(66173, 11884, 'پس از ارائهٔ مدل مولکولی مشخص شد که رشته‌های سازندهٔ دنا حالت مارپیچی دارند.', 0),
(66174, 11884, 'بررسی دناهای جانداران مختلف نشان داد که بین باز آلی آدنین و تیمین، رابطهٔ مکملی وجود دارد.', 0),
(66175, 11884, 'پژوهش‌های امروزی نشان داده است قدرت پیوند بین‌نوکلئوتیدی در ستون‌ها بیشتر از پله‌ها می‌باشد.', 1),
(66176, 11885, 'جدا شدن پروتئین‌های هیستون از رشته‌های فامینه (کروماتین) باز شده', 0),
(66177, 11885, 'شکسته‌شدن پیوندهای هیدروژنی بین بیش از یک جفت باز مکمل توسط نوعی آنزیم', 1),
(66178, 11885, 'تشکیل پیوندهای فسفودی‌استر توسط انواعی از آنزیم‌ها و به‌ویژه دنابسپاراز (DNAپلی‌مراز)', 0),
(66179, 11885, 'شکسته‌شدن پیوند فسفودی‌استر بین نوکلئوتید غیرمکمل و رشتهٔ نوکلئوتیدی در حال ساخت', 0),
(66180, 11886, 'هلیکاز برخلاف نوعی آنزیم، می‌تواند پیچ‌وتاب فامینه (کروماتین) را باز کند.', 0),
(66181, 11886, 'دنابسپاراز (DNAپلی‌مراز) برخلاف هلیکاز، می‌تواند پیوندهای بین‌نوکلئوتیدی را بشکند.', 0),
(66182, 11886, 'نوعی آنزیم برعکس هلیکاز، در تشکیل پیوند هیدروژنی بین بازهای آلی مکمل نقش دارد.', 0),
(66183, 11886, 'انواعی از آنزیم‌ها همراه با دنابسپاراز، می‌توانند در تشکیل رشتهٔ پلی‌نوکلئوتیدی جدید مؤثر باشند.', 0),
(66184, 11887, 'در هر دور چرخش کامل رشته‌های این مولکول، ۱۰ جفت باز آلی مشاهده می‌شود.', 0),
(66185, 11887, 'مجموع «آدنین و تیمین» در این مولکول برابر با مجموع «سیتوزین و گوانین» است.', 0),
(66186, 11887, 'بیان‌شدن هر بخشی از این مولکول می‌تواند به تولید رنا (RNA) یا پلی‌پپتید بینجامد.', 0),
(66187, 11887, 'پیچیدن دو رشته به دور محوری فرضی باعث ایجاد شیارهایی هم‌اندازه در طول مولکول می‌شود.', 0),
(66188, 11888, 'با هر کدام از عوامل دیگر متصل به کربن مرکزی، از نظر ویژگی‌ها متفاوت هستند.', 0),
(66189, 11888, 'جایگاه هر اتم آن‌ها با استفاده از تصاویر حاصل از پرتوهای ایکس قابل‌تشخیص است.', 1),
(66190, 11888, 'ماهیت شیمیایی آن‌ها به نحوهٔ اثرگذاری آمینواسید در شکل‌دهی پروتئین مؤثر است.', 0),
(66191, 11888, 'در یکی از سطوح ساختاری پروتئین، می‌توانند پیوندی با انرژی پیوند کم تشکیل دهند.', 0),
(66192, 11889, 'می‌توانند یک گروه $\\text{OH}$ را به اتم کربن متصل کنند.', 0),
(66193, 11889, 'بهترین فعالیت را در خارج از محدودهٔ $\\text{pH}$ طبیعی خون دارند.', 0),
(66194, 11889, 'شکل بخشی از ساختار سوم آن‌ها مشابه شکل پروتئین‌های غذا است.', 1),
(66195, 11889, 'در دمای ۳۰ درجهٔ سانتی‌گراد، به‌طور برگشت‌پذیری غیرفعال می‌شوند.', 0),
(66196, 11890, 'ایوری و همکارانش همانند گریفیت، باکتری‌های کپسول‌دار کشته‌شده را در مجاورت باکتری‌های بدون کپسول زنده قرار دادند.', 0),
(66197, 11890, 'گریفیت برخلاف مزلسون و استال، از نوعی باکتری استفاده کرد که در اطراف غشای یاخته‌ای آن، پوششی دیگر نیز وجود داشت.', 0),
(66198, 11890, 'واتسون و کریک برخلاف ویلکینز و فرانکلین، متوجه شدند در مولکول دنا (DNA)، دو رشتهٔ پلی‌نوکلئوتیدی در مقابل یکدیگر قرار دارند.', 1),
(66199, 11890, 'مزلسون و استال همانند ایوری و همکارانش، عصارهٔ استخراج‌شده از باکتری را در محلولی از سزیم کلرید و در سرعتی بسیار بالا گریز دادند.', 0),
(66200, 11891, 'با شروع تا خوردن رشتهٔ پلی‌پپتید، ساختار پروتئین به ثبات نسبی می‌رسد.', 0),
(66201, 11891, 'با نزدیک‌شدن گروه‌های $\\text{R}$ آمینواسیدهای آن‌ها به یکدیگر، شکل خاصی در پلی‌پپتید ایجاد می‌شود.', 0),
(66202, 11891, 'به‌واسطهٔ تشکیل پیوندهای اشتراکی و غیراشتراکی، به‌صورت به‌هم‌پیچیده در کنار هم نگه داشته شده‌اند.', 1),
(66203, 11891, 'با تشکیل پیوندهای غیراشتراکی بین گروه‌های تشکیل‌دهندهٔ پیوند اشتراکی، الگویی از پیوند هیدروژنی شکل گرفته است.', 0),
(66204, 11892, 'نوعی بسپار (پلیمر) زیستی را به تک‌پار (مونومر)های سازنده تبدیل می‌کنند.', 0),
(66205, 11892, 'در بخشی از لولهٔ گوارش پستانداران دارای معدهٔ چهارقسمتی قابل‌تولید هستند.', 0),
(66206, 11892, 'هر ماده‌ای که شکلی مکمل جایگاه فعال آن‌ها دارد، پیش‌مادهٔ آنزیم محسوب می‌شود.', 0),
(66207, 11892, 'انرژی فعال‌سازی واکنش اضافه‌شدن هیدروژن به نوعی مولکول زیستی را کم می‌کنند.', 0),
(66208, 11893, 'توالی «۱» نسبت به توالی «۲»، پایداری بیشتری در مقابل گرما دارد.', 1),
(66209, 11893, 'رشتهٔ مقابل توالی «۱» و «۲»، از نظر تعداد بازهای آلی پورین، یکسان هستند.', 0),
(66210, 11893, 'توالی «۱» و «۲»، از نظر تعداد پیوندهای فسفودی‌استر تشکیل‌شده، یکسان هستند.', 0),
(66211, 11893, 'رشتهٔ مقابل توالی «۱» نسبت به رشتهٔ مقابل توالی «۲»، حلقه‌های آلی بیشتری دارد.', 0),
(66212, 11894, 'شرایط مختلف با تعداد متفاوتی تشکیل - همزمان با تشکیل پیوندهای فسفودی‌استر، پیوندهای پپتیدی نیز تشکیل', 0),
(66213, 11894, 'چندین نقطه متفاوت تشکیل - رونویسی از ژن سازندهٔ آنزیم رنابسپاراز را به کمک رنابسپارازهای متنوعی انجام', 0),
(66214, 11894, 'نقطهٔ مقابل نقطهٔ پایان همانندسازی ایجاد - رنای تازه‌رونویسی‌شده، پیش از آغاز فعالیت ابتدا تغییر شکل', 0),
(66215, 11894, 'شرایطی به یکدیگر نزدیک - به کمک سازوکارهای ویژه‌ای، طول عمر رناهای پیک سیتوپلاسمی را تغییر', 1),
(66216, 11895, 'هر نوکلئوتید دارای بازهای آلی پورینی، توسط حلقهٔ پنج‌ضلعی خود به قندی پنج‌کربنه متصل شده است.', 0),
(66217, 11895, 'آخرین نوکلئوتید اضافه شده به این رشته، دارای گروه هیدروکسیل آزاد در ساختار قند پنج‌کربنهٔ خود است.', 1),
(66218, 11895, 'هر نوکلئوتید دارای یک حلقهٔ آلی، نوعی باز آلی شش‌ضلعی متصل به حلقهٔ پنج‌کربنهٔ قند دئوکسی‌ریبوز را دارد.', 0),
(66219, 11895, 'اولین نوکلئوتید قرار گرفته در ساختار این رشته، دارای فسفات آزاد متصل به حلقهٔ پنج‌ضلعی از طریق پیوند اشتراکی است.', 0),
(66220, 11896, 'اگر همانندسازی دنا به‌صورت حفاظتی انجام شود، در حد فاصل دقیقهٔ چهلم تا شصتم، بر ضخامت نوارهای موجود در بالای لوله افزوده خواهد شد.', 0),
(66221, 11896, 'اگر همانندسازی دنا به‌صورت نیمه‌حفاظتی انجام شود، در حد فاصل دقیقهٔ چهلم تا شصتم، تعداد رشته‌های دنای دارای چگالی متوسط ثابت خواهد ماند.', 0),
