(67312, 12169, 'قبل از اتصال رنابسپاراز ۱ به راه‌انداز مربوط به ژن آن، پروتئین‌هایی که توسط رناتن‌های آزاد ساخته شده‌اند، به راه‌انداز متصل می‌شوند.', 0),
(67313, 12169, 'رونوشت هر بیانه ژن آن به‌صورت کامل ترجمه می‌شود، در صورتی که رونوشت هر میانه آن به‌صورت کامل ترجمه نمی‌شود.', 0),
(67314, 12169, 'در مرحله طویل شدن رونویسی ژن آن ممکن است، چندین نوع رنابسپاراز هم‌زمان در حال حرکت بر روی یک ژن باشند.', 0),
(67315, 12169, 'در مرحله طویل شدن ترجمه رنای پیک آن، حداقل یک و حداکثر دو محصول حاصل از فعالیت رنابسپاراز ۳ درون رناتن یافت می‌شود.', 0),
(67316, 12170, 'رونویسی که زنجیره‌ای از رنا تولید - قطعاً پیوندهای ضعیفی بین دئوکسی‌ریبونوکلئوتیدها شکل می‌گیرد', 0),
(67317, 12170, 'همانندسازی که پیچ‌وتاب فامینه باز - همواره در نواحی نوکلئوزوم، هیستون‌ها از مولکول دنا جدا می‌شوند', 0),
(67318, 12170, 'بلوغ رنای پیک اولیه که تغییراتی در این مولکول ایجاد - ممکن است منجر به شکستن پیوند فسفودی‌استر نشود', 0),
(67319, 12170, 'پروتئین‌سازی که حداقل یک رمزه (کدون) ترجمه - تشکیل پیوند پپتیدی در یکی از جایگاه‌های رناتن دور از انتظار نیست', 0),
(67320, 12171, 'رشته الگو با رنای ساخته شده از روی آن و رشته رمزگذار مکمل است.', 0),
(67321, 12171, 'در دنای اصلی، محصول اولیه و نهایی ژن می‌توانند هم‌زمان ساخته شوند.', 0),
(67322, 12171, 'به‌دنبال حذف میانه‌ها (اینترون‌ها) نوعی رنای یکپارچه ساخته می‌شود.', 0),
(67323, 12171, 'با تغییر در تعداد جایگاه آغاز همانندسازی، سرعت و مقدار همانندسازی را تغییر می‌دهند.', 0),
(67324, 12172, 'در عدم حضور لاکتوز در محیط برخلاف عدم حضور مالتوز، اولین رخداد مرحله آغاز رونویسی انجام می‌گیرد.', 0),
(67325, 12172, 'در مرحله آغاز رونویسی از ژن پروتئین فعال‌کننده برخلاف مرحله آغاز ترجمه رنای پیک این پروتئین، پیوند هیدروژنی تشکیل می‌شود.', 0),
(67326, 12172, 'تعداد جایگاه آغاز همانندسازی دنای متصل به غشای آن بسته به مراحل رشدونمو تنظیم می‌شود.', 0),
(67327, 12172, 'در مرحله پایان ترجمه رنای پیک پروتئین مهارکننده، امکان شکست پیوند اشتراکی برخلاف پیوند هیدروژنی وجود دارد.', 0),
(67328, 12173, 'وقوع جهش در توالی راه‌انداز ممکن است منجر به افزایش تولید آنزیم‌های مربوط به تجزیه مالتوز شود.', 0),
(67329, 12173, 'برای تجزیه قند مصرفی ترجیحی آن، سه ژن توسط یک آنزیم رنابسپاراز به‌دنبال هم رونویسی می‌شوند.', 0),
(67330, 12173, 'جهش در ژن سازنده نوعی پروتئین مهارکننده، ممکن است منجر به عدم اتصال آن به توالی راه‌انداز شود.', 0),
(67331, 12173, 'اتصال رنابسپاراز به راه‌انداز در حضور مالتوز، منجر به رونویسی از سه توالی ژنی مشابه به‌دنبال هم می‌شود.', 0),
(67332, 12174, 'رنابسپاراز پس از رسیدن به توالی پایان رونویسی در نخستین ژن به فعالیت خود ادامه می‌دهد.', 0),
(67333, 12174, 'نوعی پروتئین همراه با دی‌ساکارید متصل به آن، به نوعی توالی تنظیمی در دنای حلقوی متصل می‌شود.', 0),
(67334, 12174, 'برای بیان ژن‌ها، اتصال بسپاری آمینواسیدی به بخشی از دنا که با ژن‌ها فاصله‌دارد، الزامی است.', 0),
