(68457, 12456, 'کاهش ریبونوکلئوتیدهای یوراسیل‌دار در رنای پیک ساخته‌شده', 0),
(68458, 12457, 'در اندام‌های جلویی برخی از مهره‌داران، مشترک هستند- دارای طرح ساختاری یکسانی هستند', 1),
(68459, 12457, 'ردپای تغییر گونه‌ها در طول سالیان زیاد هستند- در همهٔ جانوران، فاقد هرگونه فعالیتی هستند', 0),
(68460, 12457, 'نشان‌دهندهٔ روش‌های متفاوت سازش جانوران هستند- دارای عملکرد متفاوتی در محیط هستند', 0),
(68461, 12457, 'توسط پژوهشگران برای رده‌بندی جانداران استفاده می‌شوند- دارای کار متفاوتی در جانداران هستند', 0),
(68462, 12458, 'انتخاب طبیعی می‌تواند در تداوم تنوع در جمعیت نقش داشته باشد.', 0),
(68463, 12458, 'شارش ژن، هم در جمعیت مبدأ و هم مقصد، فراوانی دگره‌ها را تغییر می‌دهد.', 0),
(68464, 12458, 'آمیزش غیرتصادفی، برخلاف جهش می‌تواند فراوانی ژن‌نمودها (ژنوتیپ‌ها) را تغییر دهد.', 1),
(68465, 12458, 'رانش دگره‌ای، در یک جمعیت، بلافاصله به‌دنبال رانش قبلی، می‌تواند در تغییر فراوانی دگره‌ها، مؤثرتر باشد.', 0);
