(69539, 12727, 'به ازای خروج هشت فسفات از چرخه کالوین در میانهٔ آن، 8 یون هیدروژن توسط فتوسیستم 2 تولید', 0),
(69540, 12727, 'به ازای خروج 2 قند سه کربنی از چرخه 18 گروه فسفات در مرحله اول فتوسنتز مصرف', 0),
(69541, 12728, 'در گیاه 2 همانند گیاه 1، تشکیل ترکیب چهارکربنی طی واکنش‌هایی در اندامک(های) دوغشایی ممکن است.', 0),
(69542, 12728, 'گیاه 1 برخلاف گیاه 2 هنگام باز بودن روزنه هوایی، کربن‌دی‌اکسید تولید نمی‌کند.', 0),
(69543, 12728, 'در گیاه 1 برخلاف گیاه 2، تقسیم بندی زمانی تثبیت کربن به افزایش بازدهی فتوسنتز کمک می‌کند.', 0),
(69544, 12728, 'گیاه 2 نسبت به گیاه 1 در ابتدا، بیشتر تحت تأثیر تغییرات کربن‌دی‌اکسید محیط قرار می‌گیرد.', 0),
(69545, 12729, 'طی واکنش‌های اکسایش کاهش، نوعی مادۀ کربن‌دار را تولید می‌کنند.', 0),
(69546, 12729, 'در پی تثبیت نوعی گاز جو، در مادهٔ زمینه‌ای خود قندهای سه کربنه ایجاد نمی‌کنند.', 0),
(69547, 12729, 'به ازای تولید هر مولکول گلوکز، به جای مولکول اکسیژن، 6 اتم گوگرد تولید می‌شود.', 0),
(69548, 12729, 'باکتریوکلروفیل در غشای تیلاکوئید، از هیدروژن سولفید به عنوان منبع الکترون استفاده می‌کند.', 0),
(69549, 12730, 'به منظور انجام هر تغییر تعداد اتم‌های کربن مولکول‌های شرکت‌کننده، وجود ترکیبات کاهنده انرژی فعال‌سازی ضروری است.', 0),
(69550, 12730, 'هر مادهٔ آلی شرکت‌کننده در واکنش تغییر ماهیت شیمیایی مولکول‌های سه کربنی اسیدی، گروه فسفات دارد.', 0),
(69551, 12730, 'به ازای مصرف هر دو $NADPH$ در چرخه، در انتها دو مولکول آغازگر چرخه ساخته می‌شود.', 0),
(69552, 12730, 'تولید هر ترکیب دوفسفاته با تشکیل مولکول‌های پیش‌مادهٔ آنزیم روبیسکو همراه است.', 0),
(69553, 12731, 'مولکول‌هایی دارند که تغییر ماندگار آن‌ها موجب تغییر خزانهٔ ژنی می‌شود.', 0),
(69554, 12731, 'قابلیت دریافت ریزکیسه‌های حاوی پروتئین‌های تولیدی رناتن‌های غیرآزاد را دارند.', 0),
(69555, 12731, 'ترکیباتی با بیش از یک -COO دارند که در همه یاخته‌های واجد قندکافت مشاهده می‌شوند.', 0),
(69556, 12731, 'به کمک مولکول‌های زیستی نیتروژن‌دار، از طریق کاهش انرژی فعال‌سازی، واکنش‌های انجام‌نشدنی را ممکن می‌سازند.', 0),
(69557, 12732, 'داشتن مولکول‌های زیستی حاوی عناصر اکسیژن و نیتروژن - حداکثر جذب نوری رنگیزه‌ها در مراکز واکنش', 0),
(69558, 12732, 'نقش در تولید مولکول‌های $ATP$ و $NADPH$ در بستره - توانایی تولید پذیرنده نهایی الکترون در تنفس هوازی', 0),
(69559, 12732, 'وجود رنگیزه‌هایی که در خارج از طیف مرئی هم توانایی جذب دارند - تأمین کمبود الکترونی از الکترون‌های برانگیخته', 0),
(69560, 12732, 'تعداد زیرواحدهای سازنده - انتقال الکترون‌های برانگیخته به ترکیبی متصل به بخش داخلی غشای تیلاکوئید', 0),
(69561, 12733, 'نخستین رنگیزه‌ای هستند که جذب نور را آغاز می‌کنند و دو قله در نمودار جذب آن‌ها تشکیل می‌شود.', 0),
(69562, 12733, 'در طیف نور مرئی، دو مرتبه میزان جذب آن‌ها با رنگیزه‌هایی که نور زرد و نارنجی را بازتاب می‌کنند، برابر می‌شود.', 0),
(69563, 12733, 'در بازه طول موجی 400 تا 500 نانومتر، نسبت به سایر رنگیزه‌های موجود در تیلاکوئید، بیشترین میزان جذب نور را دارند.', 0),
(69564, 12733, 'در طول موج 500 نانومتر کمترین میزان جذب و در طول موج 400 نانومتر، بیشترین میزان جذب را در بین انواع رنگیزه‌ها دارد.', 0),
(69565, 12734, 'به منظور تولید هر ترکیب سه‌کربنه، باید نوعی پیش‌ماده فسفات‌دار در جایگاه فعال نوعی آنزیم درون‌یاخته‌ای قرار بگیرد.', 0),
(69566, 12734, 'بلافاصله بعد از خروج قند تک فسفاته از چرخه، ترکیبی آزاد می‌شود که در سومین مرحله از تجزیه گلوکز مصرف می‌گردد.', 0),
(69567, 12734, 'به منظور تولید قندهای سازنده‌ی گلوکز در چرخه، ابتدا نوعی واکنش انرژی‌زا و سپس نوعی واکنش اکسایشی انجام می‌شود.', 0),
(69568, 12734, 'در جریان بازسازی مولکول‌های پذیرنده‌ی $CO_2$ از قندهای سه‌کربنه، در ابتدا مولکول‌های آدنوزین‌تری‌فسفات مصرف نمی‌شود.', 0),
(69569, 12735, 'در پهنک برگ خود تنها دارای یک نوع یاخته‌ی میانبرگ هستند- در محیطی با نور و دمای بالا، واکنش اکسیژنازی روبیسکو مهار می‌شود.', 0),
(69570, 12735, 'اولین ترکیب پایدار حاصل از تثبیت $CO_2$، چهارکربنی است- همزمان با ورود دی‌اکسیدکربن جو به برگ، چرخه مستقل از نور انجام می‌شود.', 0),
(69571, 12735, 'تثبیت $CO_2$ در دو مرحله با تقسیم‌بندی مکانی انجام می‌شود- در هر غلظتی از $CO_2$ جو، میزان فتوسنتز بالاتری از گیاهان $C_3$ دارند.', 0),
(69572, 12735, 'عصاره برگ آن در روشنایی صبح نسبت به سایر گیاهان اسیدی‌تر است- واکوئل‌های موجود در یاخته‌ها، حاوی ترکیبات نگه‌دارنده آب هستند.', 1),
(69573, 12736, 'گازی بی‌رنگ با بویی شبیه تخم‌مرغ گندیده را مصرف نماید، بخشی از انرژی مورد نیاز از واکنش‌های اکسایشی تامین می‌شود.', 0),
(69574, 12736, 'با از دست‌دادن کلروپلاست‌های خود از مواد آلی تغذیه نماید، توانایی حذف بخش‌هایی از مولکول‌های حاصل از رونویسی وجود دارد.', 0),
(69575, 12736, 'در اطراف دهانه‌های آتشفشان‌های زیر آب زندگی کند، جذب $CO_2$ و تبدیل آن به مولکول‌های آلی بدون نیاز به رنگیزه انجام می‌شود.', 0),
(69576, 12736, 'به کمک پیکر رشته‌ای خود به جذب فسفات برای گیاهان کمک کند، در واکنش‌هایی قند را به اسید و یا اسید را به قند تبدیل کند.', 0),
(69577, 12737, 'بعد از خروج قند تک فسفاته از چرخه، شکستن پیوند کربن و فسفات حین تبدیل قند سه‌کربنی به مولکول پنج‌کربنی', 0),
(69578, 12737, 'قبل از تشکیل نخستین ترکیب کربوهیدراتی، افزایش میزان یون‌های هیدروژن موجود در فضای بستره سبزدیسه', 0),
(69579, 12737, 'بعد از شکل‌گیری هر ترکیب اسیدی سه کربنی، تولید نوعی مولکول آلی دو فسفاته در مجاورت ساختارهای رناتنی', 0),
(69580, 12737, 'قبل از تولید هر ترکیب سه‌کربنی فسفات‌دار، اتصال پیش‌ماده آلی به جایگاه فعال اختصاصی نوعی آنزیم پروتئینی', 1),
(69581, 12738, 'برخلاف یاخته‌های میانبرگ گیاهان CAM، فقط دارای یک نوع آنزیم تثبیت‌کننده کربن می‌باشد.', 0),
(69582, 12738, 'همانند یاخته‌های میانبرگ گیاهان $C_4$، قادر به مصرف ریبولوزبیس فسفات در واکنش‌های اکسیژنازی است.', 0),
(69583, 12738, 'برخلاف یاخته‌های غلاف آوندی گیاهان $C_4$، فاقد آنزیم مصرف‌کننده اسیدی سه کربنی در فرایند فتوسنتز است.', 0),
