(76668, 13227, 'در تبدیل هر مولکول پارازایلن به هر مولکول ترفتالیک اسید، ۱۲ واحد تغییر عدد اکسایش دارد.', 0),
(76669, 13227, 'واکنش تبدیل پارازایلن به ترفتالیک اسید به کمک $KMnO_4$ غلیظ با بازده بالایی انجام می‌شود.', 0),
(76670, 13227, 'واکنش تولید متانول از کربن مونوکسید و گاز هیدروژن انرژی فعال‌سازی نسبتاً بالایی دارد.', 0),
(76671, 13227, 'گاز متان را فقط می‌توان از منابع زیرزمینی تهیه کرد.', 1),
(76672, 13228, '۱', 0),
(76673, 13228, '۲', 0),
