(76675, 13228, '۴', 0),
(76676, 13229, 'کاهش حجم ظرف در تعادل $N_2O_4(g) \\rightleftharpoons 2NO_2(g)$ باعث افزایش مول و غلظت همه گازها می‌شود.', 0),
(76677, 13229, 'کاهش دما در تعادل $2SO_3(g) + q \\rightleftharpoons 2SO_2(g) + O_2(g)$ باعث کاهش سرعت رفت و کاهش ثابت تعادل می‌شود.', 1),
(76678, 13229, 'افزایش فشار در تعادل $H_2(g) + I_2(g) \\rightleftharpoons 2HI(g)$ بر جابه‌جایی و شدت رنگ مخلوط تعادلی بی‌اثر است.', 0),
(76679, 13229, 'ورود گاز $Ar$ به تعادل $NH_3(aq) + H_2O(l) \\rightleftharpoons NH_4^+(aq) + OH^-(aq)$ باعث جابه‌جایی تعادل در جهت رفت می‌شود.', 0),
(76680, 13230, 'در فرآیند تبدیل اکسید نیتروژن به فرآورده‌های بی‌خطر در مبدل کاتالیستی خودروی بنزینی، عدد اکسایش نیتروژن افزایش می‌یابد.', 0),
(76681, 13230, 'از روش طیف‌سنجی فرابنفش می‌توان برای شناسایی آلاینده‌های هوا استفاده کرد.', 0),
(76682, 13230, 'نخستین آلاینده‌ای که در هوای شهرهای بزرگ شروع به افزایش می‌کند انحلال‌پذیری بیشتری از نیتروژن در آب دارد و در اثر انحلال خود، به آب خاصیت اسیدی می‌دهد.', 0),
(76683, 13230, 'در ساعات میانی روز با کاهش مقدار گاز قهوه‌ای رنگ در هوا، مقدار اوزون افزایش می‌یابد.', 1);
