INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(328, 'نوعی بافت پیوندی، در همۀ لایه&zwnj;های دیواره مری وجود دارد .کدام موارد مشخصه&zwnj;های این بافت را به درستی بیان می&zwnj;کنند؟ الف: فقط بعضی از یاخته&zwnj;های بافت پیوندی بخش&zwnj;های رشته&zwnj;ای متصل به محل قرارگیری هسته دارند. ب: فقط بعضی از رشته&zwnj;های ضخیم آن دسته&zwnj;های چندتایی از رشته&zwnj;ها را تشکیل داده&zwnj;اند. ج: فقط بعضی از یاخته&zwnj;های ساکن در این بافت هسته&zwnj;ای کوچک و حاشیه&zwnj;ای دارند. د: فقط بعضی از رشته&zwnj;های پروتئینی ماده زمینه&zwnj;ای باریک و کشسان هستند.', 1, 4, 12, 8, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:35:25', 5, 'done'),
(329, 'چند مورد درباره دوره کار قلب یک انسان سالم و در حالت استراحت، صحیح است؟ الف: زمانی که جریان الکتریکی در دیواره های کناری بطنها منتشر میشود انقباض بطنها از قسمت پایین شروع میشود. ب: زمانی که موج P در نوار قلب ثبت میشود دریچه های سینی از بازگشت خون به بطنها جلوگیری میکنند. ج: زمانی که تارهای شبکه هادی در سراسر دیواره دهلیز چپ تحریک ،شدند دهلیزها در حال انقباض هستند. د: زمانی که صدای دوم قلب شنیده میشود خون وارد بطنها میشود.', 1, 4, 15, 20, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:35:51', 5, 'done'),
(330, 'مطابق مطالب فصل ۴ کتاب درسی دهم و با توجه به تنوع گردش مواد در جانداران بخش مشخص شده با شماره ............، معادل ساختاری در ............ است که ............', 1, 4, 15, 26, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:35:36', 5, 'done'),
(331, 'در فردی سالم و بالغ چند مورد فقط در رابطه با بعضی از اندامهای دستگاه گوارش که خون تیره آنها به سیاهرگ باب کبدی وارد میگردد، صحیح است؟', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:36:04', 5, 'done'),
(332, 'مطابق شکل کتاب درسی درباره گردش خون ماهی کدام گزینه ویژگی نوعی شبکه مویرگی را نشان میدهد که در فاصله نزدیک تری تا بزرگترین باله پیکر جانور قرار گرفته است؟', 1, 4, 15, 26, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:36:17', 5, 'done'),
(333, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان، ........... اندامهایی که در دوران جنینی یاخته های خونی را میساختند، ........... &raquo;', 1, 4, 15, 24, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 18:27:37', 3, 'done'),
(334, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;با توجه به نوار قلب نشان داده شده در شکل مقابل که مربوط به یک انسان سالم و بالغ در حالت استراحت است، میتوان گفت که در نقطه ...................&raquo;', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:34:56', 5, 'done'),
(335, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در بدن انسان، نوعی بافت که ........، از یاخته هایی تشکیل شده است که ...................&raquo;', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:34:45', 5, 'done'),
(336, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;در بخشی از لوله گوارش انسان که.................&raquo; الف: گوارش شیمیایی کربوهیدراتها آغاز می شود، فقط نشاسته توسط آنزیمهای پروتئینی تجزیه می شود. ب: قوی ترین آنزیم های گوارشی عمل می کنند، فقط بی کربنات اندامهای مرتبط با لوله در خنثی سازی اسید نقش دارد. ج: مراحل پایانی گوارش غذا انجام می شود، فقط مونوساکاریدهای حاصل از واکنش آب کافت (هیدرولیز) جذب میشوند. د: برای نخستین بار آنزیم های غیر فعال وارد لوله میشوند، فقط یاخته های پوششی سطحی در تشکیل لایه ژله ای چسبناک نقش دارند.', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:34:28', 5, 'done'),
(337, 'با توجه به مطالب کتاب درسی درباره گردش خون دستگاه گوارش انسان، کدام عبارت صحیح نیست؟', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:35:11', 5, 'done'),
(338, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در بدن انسان در نوعی فرایند تهویه ششی که.................، به طور حتم .................&raquo;', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:34:15', 5, 'done'),
(339, 'کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;در یک انسان بالغ، ................. می تواند.................،، باشد.&raquo;', 1, 4, 15, 23, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 18:29:27', 3, 'done'),
(340, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;بعد از خونریزی در پی آسیب دیدن دیواره رگ، بلافاصله پس از ................، به طور حتم ..............&raquo;', 1, 4, 15, 25, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:33:54', 5, 'done'),
(341, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان ..................، می تواند منجر به .................... شود.&raquo;', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:51:23', 5, 'done'),
(342, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;وجه .................... دو مرحله از فرایند تشکیل ادرار که دقیقاً در جهت مخالف یکدیگر انجام می&zwnj;شوند این است که ....................&raquo;', 1, 4, 16, 29, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:33:18', 5, 'done'),
(343, 'کدام عبارت، درباره شکل مقابل که بخشی از یکی از دستگاه&zwnj;های بدن انسان را نشان می&zwnj;دهد، کدام یک درست است؟', 1, 4, 13, 10, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:33:10', 5, 'done'),
(344, 'چند مورد دربارۀ شکل مقابل نادرست است؟ الف: رگ &laquo;۱&raquo; همانند رگ &laquo;۲&raquo; در تشکیل نوعی شبکه مویرگی نقش دارد. ب: رگ &laquo;۲&raquo; همانند رگ &laquo;۳&raquo;، حامل خون با مقدار بالای کربن دی&zwnj;اکسید است. ج: رگ &laquo;۴&raquo; برخلاف رگ &laquo;5&raquo;، می&zwnj;تواند در افزایش مواد دفعی در نفرون مؤثر باشد. د: رگ &laquo;۵&raquo; برخلاف رگ &laquo;۴&raquo;، مستقیماً تمام مواد خارج شده از لوله&zwnj;های ادرارساز را دریافت می&zwnj;کند.', 1, 4, 16, 28, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:32:47', 5, 'done'),
(345, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;در فردی سی ساله که قد وی ۲۰۰ سانتیمتر و وزنش کمی بیشتر از .................... کیلوگرم می&zwnj;باشد، به طور حتم .................... است.&raquo;', 1, 4, 13, 12, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:32:27', 5, 'done'),
(346, 'کدام گزینه برای تکمیل عبارت زیر درباره شکل مقابل مناسب است؟ &laquo;دو ویژگی .................... بخش .................... این است که ....................&raquo;', 1, 4, 12, 6, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:32:18', 5, 'done'),
(347, 'چند مورد در خصوص بخشی از یاخته جانوری که شکل، اندازه و کار آن را مشخص و فعالیت&zwnj;های یاخته را کنترل می&zwnj;کند، درست است؟ الف: در بخش&zwnj;هایی از آن غشای بیرونی آن در امتداد غشای شبکه آندوپلاسمی زیر قرار دارد. ب: فضای درونی شبکه آندوپلاسمی زیر می&zwnj;تواند مستقیما در ارتباط با فضای درونی هسته قرار بگیرد. ج: در بخشی از آن اجتماع رشته&zwnj;های باریک سازنده مادۀ وراثتی ساختاری کروی را تشکیل داده است. د: برقراری ارتباط بین هسته و سیتوپلاسم از طریق منافذ احاطه&zwnj;شده توسط تعدادی پروتئین انجام می&zwnj;شود.', 1, 4, 12, 6, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:13:06', 5, 'done'),
(348, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;درباره نوعی حرکت لوله گوارش که ....................، می&zwnj;توان گفت که به طور حتم ....................&raquo;', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:12:38', 5, 'done'),
(349, 'کدام عبارت درباره بدن انسان، نادرست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:12:13', 5, 'done'),
(350, 'چند مورد، درباره یاخته&zwnj;های سازنده غده&zwnj;های بخش بالایی معده درست است؟ الف: بزرگ&zwnj;ترین یاخته&zwnj;ها، در سمت مجرای غده دارای چین&zwnj;خوردگی غشایی و دو فرورفتگی هستند. ب: فراوان&zwnj;ترین یاخته&zwnj;ها، در یک غده فقط در مجاورت یاخته&zwnj;های مشابه یا یاخته&zwnj;های اسیدساز قرار می&zwnj;گیرند. ج: در عمقی&zwnj;ترین یاخته&zwnj;ها، هسته به صورت عمود بر غشای قاعده یاخته و ریز کیسه&zwnj;های ترشحی در نزدیکی مجرای غده قرار دارند. د: در کم تعدادترین یاخته&zwnj;ها، هسته کروی&zwnj;شکل و راکیزه (میتوکندری)ها در نزدیکی سطح منحنی غشا و دور از مجرای غده هستند.', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:11:32', 5, 'done'),
(351, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;مجموعه ترکیباتی که .................. می&zwnj;شود می&zwnj;توانند..................&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:12:28', 5, 'done'),
(352, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در همه افراد بالغ .................. می&zwnj;شود.&raquo;', 1, 4, 13, 10, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:12:00', 5, 'done'),
(353, 'چند مورد درباره بدن انسان نادرست است؟ الف: هر یاخته&zwnj;ای که گلیکوژن در آن ذخیره می&zwnj;شود، در ذخیره آهن و برخی ویتامین&zwnj;ها نیز نقش دارد. ب: هر اندامی که خون خارج شده از آن ابتدا به کبد می&zwnj;رود در فرایند گوارش جذب یا دفع مواد نقش مستقیم دارد. ج: هر عصب دستگاه عصبی خودمختار که بر فعالیت&zwnj;های گوارشی مؤثر است، بر عملکرد شبکه&zwnj;های عصبی تأثیر می&zwnj;گذارد. د: هر بافتی که مولکول&zwnj;های حاصل از گوارش چربی&zwnj;ها را ذخیره می&zwnj;کند می&zwnj;تواند مقدار زیادی کلسترول را با پروتئین ترکیب کند.', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:11:22', 5, 'done'),
(354, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;بلافاصله پس از ورود محتویات لوله گوارش به بخش کیسه&zwnj;ای شکل آن، ..................&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:10:44', 5, 'done'),
(355, 'کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;نوعی غده بزاقی که ترشحات آن .................. به طور حتم ..................&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:32:00', 5, 'done'),
(356, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;با توجه به روش&zwnj;های ورود مواد به یاخته و خروج از آن می&zwnj;توان گفت در نوعی روش انتقال مواد که در نتیجه آن..................، به طور حتم .................. می&zwnj;شود.&raquo;', 1, 4, 12, 7, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:10:23', 5, 'done'),
(357, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;در بدن انسان، در پی ................. می&zwnj;شود&raquo;. الف: رسیدن غذا به حلق انقباض غیرارادی ماهیچه&zwnj;های حلق باعث آغاز بلع ب: پایان بلع، بنداره (اسفنکتر) انتهای مری شل شده و غذا وارد معده ج: شروع فرایند بلع، با فشار نوعی ماهیچه مخطط غذا به عقب رانده د: ورود غذا به مری، حرکت کرمی در لوله گوارش شروع', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:10:11', 5, 'done'),
(358, 'کدام عبارت درباره بافت&zwnj;های بدن انسان که در اندام&zwnj;ها و دستگاه&zwnj;های بدن به نسبت&zwnj;های متفاوت وجود دارند، درست است؟', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:09:35', 5, 'done'),
(359, 'کدام گزینه، درباره غشای یاخته&zwnj;های پوششی دیواره مویرگ&zwnj;های خونی درست است؟', 1, 4, 12, 6, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:09:59', 5, 'done'),
(360, 'چند مورد دربارۀ ساختار لایه&zwnj;های لوله گوارش نادرست است؟ الف: در همه بخش&zwnj;های مری فعالیت لایه مخاطی همانند لایه ماهیچه&zwnj;ای می&zwnj;تواند تحت تأثیر اعصاب خودمختار قرار بگیرد. ب: در همه اندام&zwnj;های جذب&zwnj;کننده لایه زیر مخاطی برخلاف لایه بیرونی می&zwnj;تواند در تماس با ماهیچه حلقوی قرار بگیرد. ج: در همه اندام&zwnj;های سازنده آنزیم گوارشی لایه ماهیچه&zwnj;ای همانند لایه زیر مخاطی شبکه&zwnj;ای از یاخته&zwnj;های عصبی دارد. د: در همه اندام&zwnj;های دارای ماده مخاطی لایه بیرونی برخلاف لایه مخاطی در تشکیل بخشی از صفاق نقش دارد.', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:09:23', 5, 'done'),
(361, 'کدام عبارت، درباره انسان درست است؟', 1, 4, 15, 21, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:09:11', 5, 'done'),
(362, 'چند مورد، درباره اعمال دستگاه تنفس انسان به درستی بیان شده است؟ الف: در افراد مصرف&zwnj;کننده دخانیات یاخته&zwnj;های مژک&zwnj;دار مخاط تنفسی از بین می&zwnj;روند. ب: در سرفه همانند بلع، زبان کوچک به سمت بالا حرکت می&zwnj;کند. ج: در تکلم پرده&zwnj;های صوتی در شکل&zwnj;دهی به صدا نقش دارند. د: در عطسه برخلاف سرفه، ذرات از بینی خارج می&zwnj;شوند.', 1, 4, 14, 17, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:08:54', 5, 'done'),
(363, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در ............... مویرگ&zwnj;هایی وجود دارند که...............&raquo;', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:08:44', 5, 'done'),
(364, 'چند مورد درباره بخش مبادله&zwnj;ای دستگاه تنفس انسان درست است؟ الف: یاخته&zwnj;هایی با زائده&zwnj;های سطحی در اواخر دوران جنینی فعالیت خود را بیشتر می&zwnj;کنند. ب: یاخته&zwnj;هایی با ظاهر سنگ&zwnj;فرشی، در بعضی قسمت&zwnj;ها از یاخته&zwnj;های مشابه خود فاصله دارند. ج: یاخته&zwnj;هایی با اندازه بسیار درشت در دیواره حبابک، دارای ویژگی بیگانه&zwnj;خواری و توانایی حرکت هستند. د: یاخته&zwnj;هایی با تعداد خیلی زیاد در دیواره حبابک، در بخش&zwnj;هایی به غشای پایه مشترک با مویرگ اتصال دارند.', 1, 4, 14, 14, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:10:33', 5, 'done'),
(365, 'چند مورد درباره حمل گازها در خون صحیح است؟ الف: در انتقال بخش عمده&zwnj;ای از اکسیژن و کربن دی&zwnj;اکسید گویچه&zwnj;های قرمز مؤثر هستند. ب: کربن دی&zwnj;اکسید برخلاف اکسیژن توسط آنزیمی درون گویچه قرمز مصرف می&zwnj;شود. ج: حمل کربن دی&zwnj;اکسید نسبت به اکسیژن در خون ارتباط کمتری با هموگلوبین دارد. د: اکسیژن همانند کربن دی&zwnj;اکسید به مقدار اندکی در خوناب (پلاسما) حل می&zwnj;شود.', 1, 4, 14, 15, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:08:29', 5, 'done'),
(366, 'چند مورد درباره سازوکار انجام دم و بازدم در انسان درست است؟ الف: برای جابه&zwnj;جایی حجمی از هوا که بیشتر از حجم جاری است، به طور حتم نوعی ماهیچه بین دنده&zwnj;ای منقبض می&zwnj;شود. ب: برای اینکه تبادل گازها در فاصله بین دو تنفس امکان&zwnj;پذیر باشد، لازم است که سوراخی در قفسه سینه ایجاد نشده باشد. ج: برای اینکه حجمی معادل ظرفیت حیاتی از دستگاه تنفس خارج شود، به طور حتم همه ماهیچه&zwnj;های بازدمی باید منقبض شوند. د: برای اینکه فقط حجم باقی&zwnj;مانده در شش&zwnj;ها باقی بماند، قطعاً لازم است پس از یک دم عمیق، هوا با یک بازدم عمیق از شش&zwnj;ها خارج شود.', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:08:06', 5, 'done'),
(367, 'کدام عبارت، درباره شکل مقابل که مربوط به یکی از مجاری بخش هادی دستگاه تنفس انسان می&zwnj;باشد، درست است؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:08:16', 5, 'done'),
(368, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول در بدن انسان رگ&zwnj;هایی به مویرگ&zwnj;ها منتهی می&zwnj;شوند که ...............&raquo;', 1, 4, 15, 22, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:07:53', 5, 'done'),
(369, 'چند مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;در سراسر قسمت&zwnj;های سازنده بخشی از دستگاه تنفس انسان که هوا را به درون و بیرون دستگاه تنفسی هدایت می&zwnj;کنند، ...............&raquo; الف: مانعی در برابر ورود ناخالصی&zwnj;های هوا دیده می&zwnj;شود. ب: یاخته&zwnj;های بافت غضروفی در دیواره قابل مشاهده هستند. ج: شبکه وسیعی از رگ&zwnj;های خونی در گرم کردن هوا نقش دارند. د: یاخته&zwnj;های مژک&zwnj;داری وجود دارند که مواد ضدمیکروبی ترشح می&zwnj;کنند.', 1, 4, 14, 14, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:07:44', 5, 'done'),
(370, 'در فردی که دچار گازگرفتگی شده است وقوع کدام مورد دور از انتظار است؟', 1, 4, 14, 15, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:31:37', 5, 'done'),
(371, 'کدام عبارت، درباره قلب انسان و رگ&zwnj;های متصل به آن صحیح است؟', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:07:30', 5, 'done'),
(372, 'با توجه به فعالیت کتاب درسی درباره تشریح شش گوسفند، چند مورد درست است؟ الف: به دلیل ساختار غضروفه&zwnj;ای نایژه اصلی، بریدن نایژه اصلی به سادگی بریدن نای نیست. ب: ششی که دارای دو لپ (لوب) است، قبل از نایژه اصلی، انشعاب دیگری نیز از نای دریافت می&zwnj;کند. ج: غضروف&zwnj;های موجود در دیواره نایژه اصلی در ابتدا به صورت حلقه کامل و بعد به صورت قطعه&zwnj;قطعه است. د: در مقطع عرضی شش، نوعی سوراخ با لبه غیر زبر که همیشه باز است، مربوط به دهانه نوعی سرخرگ است.', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:31:14', 5, 'done'),
(373, 'کدام عبارت، درباره ساختار بافتی قلب انسان درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:29:59', 5, 'done'),
(374, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در یک انسان بالغ و سالم که در حالت استراحت است، در مرحله ای از چرخه ضربان قلب که ...............، برخلاف سایر مراحل، ...............&raquo; الف: بسیار زودگذر است - حجم خون در بطن&zwnj;ها افزایش می&zwnj;یابد. ب: حدود 0/3 ثانیه طول می&zwnj;کشد - یکی از صداهای قلبی شنیده می&zwnj;شود. ج: سیستول بطن&zwnj;ها رخ می&zwnj;دهد - خون بزرگ سیاهرگ&zwnj;ها وارد دهلیز راست می&zwnj;شود. د: نیمی از دوره کار قلب را به خود اختصاص می&zwnj;دهد - تمام قلب در حال استراحت است.', 1, 4, 15, 20, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:07:17', 5, 'done'),
(375, 'در ارتباط با قلب انسان، کدام عبارت نادرست است؟', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:30:27', 5, 'done'),
(376, 'کدام گزینه، برای تکمیل عبارت زیر درباره شکل مقابل مناسب است؟ &laquo;در فاصله بین پایان ثبت موج ............... تا شروع ثبت موج............... در نوار قلب یک انسان سالم، ............... &raquo;', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:33:44', 5, 'done'),
(377, 'کدام گزینه عبارت زیر را درباره مراکز عصبی تنظیم&zwnj;کننده تنفس در انسان به درستی کامل می&zwnj;کند؟ &laquo;نوعی مرکز عصبی که ................ می&zwnj;تواند ..................&raquo;', 1, 4, 14, 17, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 18:30:09', 3, 'done'),
(378, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;یاخته مشخص شده با شماره ............... یاخته مشخص شده با شماره ...............&raquo;', 2, 4, 23, 91, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:30:15', 5, 'done'),
(379, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان در گردش خون عمومی ................ گردش خون ششی، همه ................&raquo;', 1, 4, 15, 19, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:50:14', 5, 'done'),
(380, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;ماهیچه&zwnj;های قلب با رگ&zwnj;های ویژه&zwnj;ای تغذیه می&zwnj;شوند که ................&raquo; الف: از بالای دریچه سینی سرخرگ آئورت منشعب شده&zwnj;اند. ب: نیازهای تنفسی و غذایی همه یاخته&zwnj;های پوششی دیواره قلب را نیز برطرف می&zwnj;کنند. ج پس از رفع نیاز یاخته&zwnj;های قلبی، به صورت یک سیاهرگ به دهلیز راست متصل می&zwnj;شوند. د: رسوب کلسترول لیپوپروتئین کم&zwnj;چگال (LDL) در دیواره آن&zwnj;ها، عملکرد آن&zwnj;ها را مختل می&zwnj;کند.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:50:05', 5, 'done'),
(381, 'کدام عبارت درباره رگ&zwnj;های اکلیلی (کرونری) قلب انسان نادرست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:49:53', 5, 'done'),
(382, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;یاخته بنیادی میلوئیدی برخلاف یاخته بنیادی لنفوئیدی، می&zwnj;تواند بلافاصله پس از تقسیم سیتوپلاسم خود یاخته&zwnj;ای را ایجاد کند که ..............&raquo; الف: بدون تقسیم هسته، سیتوپلاسم خود را قطعه&zwnj;قطعه می&zwnj;کند. ب: نوعی گویچه سفید است و سیتوپلاسم بدون دانه دارد. ج: درون خود، ژن&zwnj;های لازم برای تولید هموگلوبین را دارد. د: اطلاعات وراثتی را در چند هسته نگه&zwnj;داری می&zwnj;کند.', 1, 4, 15, 24, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:07:01', 5, 'done'),
(383, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان، .............. اندام&zwnj;هایی که در دوران جنینی یاخته&zwnj;های خونی را می&zwnj;ساختند، ..............&raquo;', 1, 4, 15, 24, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:49:22', 5, 'done'),
(384, 'کدام عبارت، درباره شکل مقابل صحیح است؟', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:49:13', 5, 'done'),
(385, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در واکنش خلاصه شده تنفس یاخته ای، فقط یکی از .............. &raquo;', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:49:02', 5, 'done'),
(386, 'کدام عبارت، درباره صداهای قلب انسان درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:05:55', 5, 'done'),
(387, 'چند مورد، درباره دوره کار قلب یک انسان سالم و در حالت استراحت، صحیح است؟ الف: زمانی که جریان الکتریکی در دیواره&zwnj;های کناری بطن&zwnj;ها منتشر می&zwnj;شود، انقباض بطن&zwnj;ها از قسمت پایین شروع می&zwnj;شود. ب: زمانی که موج P در نوار قلب ثبت می&zwnj;شود، دریچه&zwnj;های سینی از بازگشت خون به بطن&zwnj;ها جلوگیری می&zwnj;کنند. ج: زمانی که تارهای شبکه هادی در سراسر دیواره دهلیز چپ تحریک شدند، دهلیزها در حال انقباض هستند. د: زمانی که صدای دوم قلب شنیده می&zwnj;شود خون وارد بطن&zwnj;ها می&zwnj;شود.', 1, 4, 15, 20, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:48:53', 5, 'done'),
(388, 'کدام عبارت درباره انسان نادرست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:48:41', 5, 'done'),
(389, 'با توجه به مطالب کتاب درسی، کدام عبارت درباره آزمایشی که به منظور مقایسه مقدار نسبی کربن دی&zwnj;اکسید در هوای دمی و بازدمی انجام می&zwnj;شود، صحیح است؟', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:48:01', 5, 'done'),
(390, 'با توجه به مطالب کتاب درسی، درباره عواملی که به جریان خون در سیاهرگ&zwnj;ها کمک می&zwnj;کنند، کدام عبارت صحیح است؟', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:47:52', 5, 'done'),
(391, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;یاخته&zwnj;های بخشی از نفرون که بلافاصله بعد از بخش قیف مانند آن قرار گرفته اند، .............. &raquo; الف: راکیزه (میتوکندری) های عمودی در نزدیکی غشای مجاور فضای درون لوله دارند. ب: در مجاورت غشای دارای ریزپرز، هسته&zwnj;ای کروی شکل دارند. ج: گلوکز و آمینواسید را وارد مویرگ&zwnj;های دور لوله&zwnj;ای می&zwnj;کنند. د: جابه&zwnj;جایی مواد را فقط بر اساس اندازه انجام می&zwnj;دهند.', 1, 4, 16, 29, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:48:29', 5, 'done'),
(392, 'با توجه به مطالب کتاب درسی دربارۀ ساختارهای محافظت&zwnj;کننده از کلیه در انسان، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;نوعی ساختار محافظت&zwnj;کننده از کلیه که ...............، به طور حتم ...............&raquo;', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:46:55', 5, 'done'),
(393, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان، ............... نسبت به ............... است.&raquo;', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:05:40', 5, 'done'),
(394, 'کدام عبارت درباره شکل مقابل درست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:46:48', 5, 'done'),
(395, 'چند مورد، درباره فراوان ترین مادۀ دفعی آلی در ادرار انسان سالم، درست است؟ الف: از کلافک (گلومرول) به فضای درون کپسول بومن ترشح می&zwnj;شود. ب: در نتیجه تجزیه موادی مانند آمینواسیدها تولید می&zwnj;شود. ج: انباشته شدن آن و دفع با فواصل زمانی امکان&zwnj;پذیر است. د: تمایل زیادی به رسوب کردن و تشکیل بلور دارد.', 1, 4, 16, 30, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:47:09', 5, 'done'),
(396, 'کدام عبارت درباره دستگاه ادراری در انسان نادرست است؟', 1, 4, 16, 28, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:46:27', 5, 'done'),
(397, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان، در نتیجه ............... انتظار می&zwnj;رود که ...............&raquo;', 1, 4, 16, 30, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:46:36', 5, 'done'),
(398, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;همه موادی که وارد فضای درون نفرون می&zwnj;شوند، ...............&raquo; الف: به روش فعال و با صرف انرژی زیستی از غشا عبور می&zwnj;کنند. ب: از نوعی شبکه مویرگی به درون نفرون وارد می&zwnj;شوند. ج: ابتدا به قسمتی از بخش لوله ایلوله&zwnj;ای نفرون وارد می&zwnj;شوند. د: از طریق مجرای جمع&zwnj;کننده وارد لگنچه می&zwnj;شوند.', 1, 4, 16, 29, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:05:29', 5, 'done'),
(399, 'کدام عبارت، درباره شکل مقابل درست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:46:11', 5, 'done'),
(400, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ در فردی که ...............، انتظار می&zwnj;رود در کلیه ها، ............... یابد.&raquo;', 1, 4, 16, 30, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:45:55', 5, 'done'),
