(402, 'کدام مورد، عبارت زیر را به طور صحیحی کامل می&zwnj;کند؟ &laquo;در نوزاد انسان پس از آن&zwnj;که ...............&raquo;', 1, 4, 16, 30, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:45:26', 5, 'done'),
(403, 'چند مورد در ارتباط با دفع آب از طریق کلیه&zwnj;ها درست است؟ الف: دفع آب از کلیه&zwnj;ها به میزان زیادی به غلظت مواد حل شده در خوناب بستگی دارد. ب: می&zwnj;تواند با حل کردن مقداری مادۀ دفعی نیتروژن&zwnj;دار در خود، امکان ایجاد سنگ کلیه را کاهش دهد. ج: هورمون ضدادراری باعث کاهش فشار اسمزی خون در رگی می&zwnj;شود که با بخش صعودی لوله هنله مجاورت دارد. د: آب، پس از عبور از دریچه ای که حاصل چین خوردگی مخاط است، به بخشی وارد می&zwnj;شود که فعال&zwnj;کننده سازوکار تخلیه ادرار می&zwnj;باشد.', 1, 4, 16, 30, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:45:14', 5, 'done'),
(404, 'کدام مورد دربارۀ مرحله بازجذب در فرایند تشکیل ادرار، درست است؟', 1, 4, 16, 29, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:44:42', 5, 'done'),
(405, 'در ارتباط با موقعیت قرارگیری اندام&zwnj;های سازنده دستگاه گوارش انسان، کدام موارد به طور صحیحی مطرح شده&zwnj;اند؟ الف: مجرایی درون پانکراس که ترشحات صفراوی را نیز دریافت می&zwnj;کند پایین&zwnj;تر از مجرای دیگر پانکراس قرار دارد. ب: قسمتی از روده بزرگ که بالاتر از همه قسمت&zwnj;های دیگر آن قرار دارد، در مجاورت بخش محدب معده قرار گرفته است. ج: لوله طویلی که با حفره دهانی در ارتباط است پس از طی مسیر در قفسه سینه به سمت قسمت بزرگ&zwnj;تر کبد متمایل می&zwnj;شود. د: قسمتی از دوازدهه که اولین محل ورود پروتئازهای پانکراس است، بالاتر از محل اتصال دوازدهه به قسمت بعدی روده می&zwnj;باشد.', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:04:42', 5, 'done'),
(406, 'پس از ورود غذا به حفره دهانی انسان، کدام گزینه، ترتیب وقایع رخ داده تا زمان ورود توده غذایی به معده را به درستی بیان می&zwnj;کند؟ الف: ارسال پیام از مغز و شروع ارادی بلع ب: ورود غذا به مری ج: شروع حرکات کرمی د: فشار زبان به توده غذا', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:05:03', 5, 'done'),
(407, 'کدام عبارت دربارۀ لوله گوارش انسان درست است؟', 1, 4, 13, 10, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:44:35', 5, 'done'),
(408, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ طی فرایند تشکیل ادرار در کلیه&zwnj;های یک انسان سالم همه ...............&raquo;', 1, 4, 16, 29, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:44:20', 5, 'done'),
(409, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان، زمانی که ماهیچه میان&zwnj;بند (دیافراگم) بیشترین ...............دارد...............&raquo;', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:03:51', 5, 'done'),
(410, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;با توجه به شکل مقابل، هنگامی که پیام الکتریکی مربوط به انقباض یاخته&zwnj;های ماهیچه&zwnj;ای در بخش ............... قرار دارد، برخلاف زمانی که پیام الکتریکی مربوط به انقباض یاخته&zwnj;های ماهیچه&zwnj;ای در بخش C قرار دارد، ...............&raquo;', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:03:32', 5, 'done'),
(411, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;یک انسان سالم ............... یاخته هایی که ...............&raquo; الف: فقط بعضی از - ۹۲ فام&zwnj;تن (کروموزوم) دارند به رشته&zwnj;های کلاژن متصل شده&zwnj;اند. ب: همه ـ ظاهر دوکی&zwnj;شکل دارند، در حضور یون کلسیم، طول خود را کوتاه&zwnj;تر می&zwnj;کنند. ج: همه - پیام انقباض را به یاخته&zwnj;های مجاور خود انتقال می&zwnj;دهند، رشته&zwnj;های سیتوپلاسمی کوتاه و بلند دارند. د: فقط بعضی از - دارای مژک در سطح خود هستند، گلیکوپروتئین موسین را تولید و ترشح می&zwnj;کنند.', 1, 4, 12, 8, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:03:11', 5, 'done'),
(412, 'با توجه به شکل مقابل که نوار قلب یک انسان سالم در حالت استراحت را نشان می&zwnj;دهد، کدام عبارت درست است؟', 1, 4, 15, 20, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:03:21', 5, 'done'),
(413, 'چند مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول در بدن انسان، از بین رگ&zwnj;های خونی که سه لایه مختلف در دیواره خود دارند، آن&zwnj;هایی که ...............، نسبت به نوع دیگر رگ&zwnj;های خونی که اندازه مشابهی دارند، ...............&raquo;', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:02:43', 5, 'done'),
(414, 'کدام عبارت درباره ساختار بافتی قلب انسان درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:03:40', 5, 'done'),
(415, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در نخستین مرحله تشکیل ادرار در کلیه&zwnj;های انسان ............... هر مرحله&zwnj;ای از فرایند تشکیل ادرار که ...............&raquo;', 1, 4, 16, 29, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:50:25', 5, 'done'),
(416, 'در دوران جنینی انسان، اندام&zwnj;های مختلفی می&zwnj;توانند یاخته&zwnj;های خونی را تولید کنند. چند مورد فقط درباره ساختار و عملکرد بعضی از این اندام&zwnj;ها در انسان بالغ، درست است؟ الف: خون سیاهرگی آن&zwnj;ها به طور مستقیم به سمت قلب نمی&zwnj;رود. ب: در از بین بردن میکروب&zwnj;های بیماری&zwnj;زا و یاخته&zwnj;های سرطانی نقش دارند. ج: گیرنده پیک شیمیایی تولید شده توسط گروه ویژه&zwnj;ای از یاخت&zwnj;های کلیه را دارند. د: در مجاورت مویرگ&zwnj;های خونی آن&zwnj;ها درشت&zwnj;خوارها به پاکسازی گویچه&zwnj;های قرمز مرده می&zwnj;پردازند.', 1, 4, 15, 24, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:44:08', 5, 'done'),
(417, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;هر نوع مولکولی در غشای یاخته که ...............، متعلق به گروهی از مولکول&zwnj;های زیستی است که قطعاً ...............&raquo;', 1, 4, 12, 6, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:02:30', 5, 'done'),
(418, 'در بعضی از قسمت&zwnj;های لوله گوارش که بعد از حلق قرار گرفته&zwnj;اند، یاخته&zwnj;های ماهیچه&zwnj;ای موجود در لایه ماهیچه&zwnj;ای، از نظر نوع یا نحوه سازمان&zwnj;یابی با لایه ماهیچه&zwnj;ای روده متفاوت هستند. کدام عبارت دربارۀ همۀ این قسمت&zwnj;ها صادق است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:01:56', 5, 'done'),
(419, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در دستگاه گوارش انسان، گروهی از یاخته&zwnj;های پوششی که ...............، به طور حتم ...............&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-11 22:01:39', 5, 'done'),
(420, 'کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول در غده&zwnj;های معده انسان، ............... یاخته&zwnj;ها می&zwnj;توانند ...............&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:43:40', 5, 'done'),
(421, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در دیواره قسمتی از مری که در نزدیکی معده قرار دارد، همۀ یاخته&zwnj;های نوعی بافت که ............... وجود دارد به طور حتم ...............&raquo;', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:43:16', 5, 'done'),
(422, 'با توجه به مطالب کتاب درسی درباره غدد بزاقی در انسان، چند مورد درست است؟ الف: غده&zwnj;ای که ترشحات آن از طریق مجرایی افقی به قسمت بالای زبان می&zwnj;ریزد، روی ماهیچه کشیده شده بین دو فک قرار دارد. ب: غده&zwnj;ای که مجرای حامل ترشحات آن از پشت غدۀ دیگر عبور می&zwnj;کند، در سطح داخلی و زیر فک پایین قرار دارد. ج: غده&zwnj;ای که بین غده&zwnj;های بزاقی بزرگ کمترین اندازه را دارد، در فاصله کمتری نسبت به لب&zwnj;های پایین قرار دارد. د: غده&zwnj;ای که ترشحات آن وارد چند مجرای عمودی می&zwnj;شود، روی ماهیچه چسبیده به فک پایین قرار دارد.', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:42:54', 5, 'done'),
(423, 'با توجه به اطلاعات کتاب درسی، کدام گزینه در خصوص ماده&zwnj;ای که خارج از لوله گوارش و درون کبد ساخته شده و به گوارش چربی&zwnj;های درون روده باریک کمک می&zwnj;کند، نادرست است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:43:29', 5, 'done'),
(424, 'در نزدیکی کبد انسان، اندام&zwnj;های کیسه&zwnj;ای شکلی وجود دارند که مربوط به قسمتی از دستگاه گوارش می&zwnj;باشند. کدام ویژگی این اندام&zwnj;ها را از یکدیگر متمایز می&zwnj;سازد؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:42:45', 5, 'done'),
(425, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;مطابق مطالب کتاب درسی در انسان، ............. عواملی که در گوارش نهایی کیموس نقش دارند، .............&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:42:32', 5, 'done'),
(426, 'چند مورد، ویژگی مشترک همه ماهیچه&zwnj;های حلقوی است که در دیواره لوله گوارش وجود دارند و بر میزان انتقال مواد به بخش&zwnj;های بعدی تأثیر می&zwnj;گذارند؟ الف: یاخته&zwnj;هایی دوکی&zwnj;شکل و تک&zwnj;هسته&zwnj;ای دارند. ب: در تماس با لایه زیر مخاط لوله گوارش قرار دارند. ج: ارتباطی ویژه با یاخته&zwnj;های اصلی بافت عصبی دارند. د: فقط پس از ورود غذا به درون لوله گوارش منقبض می&zwnj;شوند.', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:27', 1, '2026-02-12 09:42:16', 5, 'done'),
