(430, 'کدام مورد عبارت زیر را به درستی کامل می&zwnj;کند؟ &laquo;در بدن انسان هر زمان که .............، به طور حتم.............&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:40:52', 5, 'done'),
(431, 'در شکل زیر، انواع لایه&zwnj;های مختلف سازنده دیواره لوله گوارش (از مری تا مخرج) نشان داده شده است. کدام عبارت درباره این لایه&zwnj;ها به درستی بیان شده است؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:41:21', 5, 'done'),
(432, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;مطابق مطالب کتاب درسی، در دستگاه تنفسی نوعی جانور که معده چهار قسمتی دارد، .............&raquo;', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:40:14', 5, 'done'),
(433, 'کدام عبارت درباره حفره&zwnj;ای در بدن هیدر که گوارش مواد غذایی درون آن انجام می&zwnj;شود، درست است؟', 1, 4, 13, 13, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:39:49', 5, 'done'),
(434, 'با توجه به مطالب کتاب درسی درباره آزمایشی که طی آن، بررسی می&zwnj;شود که &laquo;آیا هوای دمی با هوای بازدمی متفاوت است؟&raquo;، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در ظرفی که ................، برخلاف ظرف دیگر، به طور حتم ................&raquo;', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:39:41', 5, 'done'),
(435, 'مطابق مطالب فصل سوم کتاب درسی دهم، گروهی از جانوران علاوه بر لوله گوارش، دارای یکی از چهار روش اصلی برای تنفس هستند. کدام مورد یا موارد ویژگی مشترک این جانوران را به درستی بیان می&zwnj;کند؟ الف: در اثر تشکیل مخرج جریان یک&zwnj;طرفه مواد در لوله هضم&zwnj;کننده غذا امکان&zwnj;پذیر شده است. ب: ترشحات گروهی از یاخته&zwnj;های دستگاه تنفسی شرایط لازم برای تبادل گازهای تنفسی را فراهم می&zwnj;کند. ج: تبدیل بسپار (پلیمرهای غذا به واحدهای سازنده فقط در خارج از یاخته ها و با کمک آنزیمهای گوارشی انجام می&zwnj;شود. د: تشکیل ساختارهای تنفسی بر اساس ویژگی رشد و نمو در دوران جنینی و با کمک اطلاعات دنا (DNA) به پایان می&zwnj;رسد.', 1, 4, 14, 18, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:41:11', 5, 'done'),
(436, 'کدام عبارت، درباره دستگاه گوارش پرندۀ دانه&zwnj;خوار درست است؟', 1, 4, 13, 13, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:39:24', 5, 'done'),
(437, 'کدام مورد درباره دستگاه گوارش بدن انسان درست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:39:18', 5, 'done'),
(438, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در بدن انسان در فرایند ................، انتظار میرود که ...............&raquo; الف: عطسه برخلاف سرفه &ndash; ناخالصی&zwnj;های نای از بدن خارج شوند. ب: ریفلاکس برخلاف بلع - انقباض بنداره انتهای مری کم شود. ج: بلع همانند سرفه - زبان کوچک به سمت بالا حرکت کند. د: عطسه برخلاف بلع - اپی گلوت به سمت بالا حرکت کند.', 1, 4, 14, 17, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:32:09', 5, 'done'),
(439, 'چند مورد، درباره فرایندهای تهویه ششی نادرست است؟ الف: ماهیچه&zwnj;هایی که به مهره&zwnj;های کمری متصل می&zwnj;شوند، فقط در بازدم عمیق نقش دارند. ب: ماهیچه&zwnj;هایی که به ترقوه متصل هستند، هم در دم عادی و هم در دم عمیق مؤثر می&zwnj;باشند. ج: ماهیچه&zwnj;هایی که فقط در تنفس عمیق نقش دارند، در خارج از دیواره قفسه سینه قرار دارند. د: ماهیچه&zwnj;هایی که هم به دنده و هم به جناغ متصل هستند، می&zwnj;توانند دنده&zwnj;ها را به عقب یا جلو جابه&zwnj;جا کنند.', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:39:05', 5, 'done'),
(440, 'خون سیاهرگی گروهی از اندام&zwnj;های موجود در حفره شکمی فقط پس از عبور از شبکه مویرگی کبدی وارد بزرگ سیاهرگ زیرین می&zwnj;شود. کدام عبارت، درباره گردش خون این اندام&zwnj;ها درست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:31:47', 5, 'done'),
(441, 'کدام عبارت، دربارۀ لوله گوارش انسان درست است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:31:32', 5, 'done'),
(442, 'کدام موارد درباره بخش مبادله&zwnj;ای دستگاه تنفس درست است؟ الف: باکتری&zwnj;هایی که پس از ورود به بخش مبادله&zwnj;ای نابود می&zwnj;شوند، به طور حتم بیگانه&zwnj;خواری شده&zwnj;اند. ب: ماده&zwnj;ای که در سطح فضای درونی حبابک قرار دارد، ممکن است باز شدن حبابک طی فرایند دم را دشوارتر کند. ج: یاخته&zwnj;هایی با ظاهری بسیار متفاوت در دیواره حبابک، ممکن است در نوزاد تازه متولد شده فعالیت کافی نداشته باشند. د: حبابکی که به آخرین انشعاب از انشعابات نای متصل است به طور حتم درون ساختاری شبیه به خوشه انگور قرار دارد.', 1, 4, 14, 14, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:38:15', 5, 'done'),
(443, 'با توجه به شکل زیر که حجم های مختلف تنفسی را در دم&zwnj;نگاره (اسپیروگرام) یک فرد بالغ و سالم طی یک دقیقه نشان می&zwnj;دهد، کدام عبارت درست است؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:31:24', 5, 'done'),
(444, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;نوعی مولکول گازی که ...................، برخلاف ماده&zwnj;ای که از نظر انواع عناصر سازنده با این مولکول گازی متفاوت است و جزء گازهای تنفسی محسوب می&zwnj;شود، ...................&raquo;', 1, 4, 14, 15, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:38:56', 5, 'done'),
(445, 'چند مورد، درباره جذب مواد در روده باریک انسان نادرست است؟ الف: هر مولکولی که وارد مویرگی با انتهای بسته در پرز روده می&zwnj;شود، در نهایت با مولکولی دارای پیوند پپتیدی ترکیب می&zwnj;شود. ب: هر ماده جذب&zwnj;شده در روده که برای تولید مواد دیگر در کبد استفاده می&zwnj;شود، توسط سیاهرگ باب وارد کبد می&zwnj;شود. ج: هر مولکول زیستی که می&zwnj;تواند وارد سیتوپلاسم یاخته پرز روده شود، فراورده نوعی آنزیم دستگاه گوارش است. د: هر ویتامینی که با کمک مواد ترشح&zwnj;شده در بخشی از دستگاه گوارش جذب می&zwnj;شود، قطعاً در کبد ذخیره می&zwnj;شود.', 1, 4, 13, 10, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:41:01', 5, 'done'),
(446, 'هنگام مشاهده فضای درونی یک حبابک در برش عرضی، انواع مختلفی از یاخته&zwnj;ها دیده می&zwnj;شوند. چند مورد، درباره این یاخته&zwnj;ها درست است؟ الف: هر یاخته&zwnj;ای در دیواره حبابک، که بزرگ&zwnj;ترین یاخته دیواره محسوب می&zwnj;شود در مجاورت یک منفذ قرار دارد. ب: هر یاخته&zwnj;ای که ظاهری سنگفرشی دارد، ممکن است روی غشای پایه&zwnj;ای مشترک با غشای پایه مویرگ قرار داشته باشد. ج: هر یاخته&zwnj;ای که به باز شدن آسان&zwnj;تر حبابک کمک می&zwnj;کند، هسته&zwnj;ای بیضی&zwnj;شکل در مرکز خود دارد. د: هر یاخته&zwnj;ای که سطحی ناصاف دارد، جزء کم&zwnj;تعدادترین یاخته&zwnj;های دیواره حبابک محسوب می&zwnj;شود.', 1, 4, 14, 14, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:31:15', 5, 'done'),
(447, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در گاو، ...................، به طور حتم، قبل از ................... و بعد از ...................رخ می&zwnj;دهد.&raquo;', 1, 4, 13, 13, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:38:24', 5, 'done'),
(448, 'مطابق مطالب کتاب درسی، در بدن انسان گذرگاهی ماهیچه&zwnj;ای وجود دارد که می&zwnj;توان آن را به یک چهارراه تشبیه کرد. کدام عبارت، ویژگی مشترک ساختارهایی است که در یک دوراهی در انتهای این گذرگاه واقع شده&zwnj;اند؟', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:37:42', 5, 'done'),
(449, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در فردی که در حال ................... است به طور حتم ...................&raquo;', 1, 4, 14, 17, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:38:04', 5, 'done'),
(450, 'در گروهی از جانوران، تبادل گازی یاخته&zwnj;های بدن با محیط اطراف به واسطه شش انجام می&zwnj;شود. کدام ویژگی، فقط درباره بعضی از این جانوران صادق است؟', 1, 4, 14, 18, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:40:11', 5, 'done'),
(451, 'کدام عبارت درباره دستگاه تنفس انسان درست است؟', 1, 4, 14, 14, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:40:22', 5, 'done'),
(452, 'بخشی از دستگاه تنفس انسان، هوا را به درون و بیرون دستگاه تنفسی هدایت می&zwnj;کند. کدام ویژگی درباره ساختارهای موجود در این بخش در سراسر مسیر عبور هوا درست است؟', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:40:41', 5, 'done'),
(453, 'کدام عبارت، درباره انشعابات نای در شش انسان به درستی مطرح شده است؟', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:40:32', 5, 'done'),
(454, 'کدام مورد یا موارد، برای تکمیل عبارت زیر مناسب است؟ &laquo;اگر فردی که دو متر قد دارد، برای مدتی طولانی وزنی کمی بیشتر از ................... کیلوگرم را داشته باشد، در این صورت، می&zwnj;توان گفت که در این فرد، ................... انتظار است.&raquo; الف: ۱۲۰ ـ فعالیت غیر طبیعی ژن آنزیم&zwnj;های لیپیدساز، قابل ب: ۶۰ - بروز اختلال در عملکرد دستگاه گردش خون، دور از ج: ۸۰ - آسیب دیدن ریزپرزهای روده تحت تأثیر پروتئین گلوتن، قابل د: ۱۰۰ - اختلال در ترشح هورمون&zwnj;های بخش درون ریز پانکراس، دور از', 1, 4, 13, 12, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:39:24', 5, 'done'),
(455, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در دستگاه تنفسی هر انسان بالغ، ...................&raquo;', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:38:40', 5, 'done'),
(456, 'کدام عبارت، درباره وقایعی که در فاصله بین زمان عبور مواد از بنداره (اسفنکتر) انتهای روده باریک تا دفع مدفوع رخ می&zwnj;دهند، درست است؟', 1, 4, 13, 10, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:39:07', 5, 'done'),
(457, 'شکل مقابل، سطحی از قلب گوسفند را نشان می&zwnj;دهد. چند مورد از ویژگی&zwnj;های زیر این سطح از قلب را از سطح دیگر آن متمایز می&zwnj;سازد؟ الف: سطح آن نسبتا صاف و تخت است. ب: اغلب رگ&zwnj;های کرونری آن حامل خون روشن هستند. ج: رگ&zwnj;های کرونری آن به صورت عمودی طی مسیر می&zwnj;کنند. د: در فاصله کمتری نسبت به استخوان جناغ سینه قرار دارد.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:38:42', 5, 'done'),
(458, 'کدام مورد، درباره فردی که دومین عمل موفقیت&zwnj;آمیز پیوند قلب مصنوعی در ایران روی وی انجام شد، نادرست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:38:51', 5, 'done'),
(459, 'در سطحی از قلب انسان که به استخوان جناغ سینه نزدیک&zwnj;تر است، سرخرگ&zwnj;های کرونری وجود دارند. کدام گزینه، برای تکمیل عبارت زیر درباره این سرخرگ&zwnj;ها درست است؟ &laquo;سرخرگی که به صورت کاملاً مستقیم طی مسیر می&zwnj;کند، ................... سرخرگی که به صورت مایل طی مسیر می&zwnj;کند، ...................&raquo;', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:37:07', 5, 'done'),
(460, 'چند مورد درباره قلب انسان درست است؟ الف: دریچه سینی سرخرگ ششی نسبت به دریچه سه لختی، پایین&zwnj;تر است. ب: در بطن چپ نسبت به بطن راست، تعداد طناب&zwnj;های ارتجاعی کم&zwnj;تر است. ج: قسمت پایینی دیواره بین بطنی نسبت به قسمت بالایی آن، ضخیم&zwnj;تر است. د: تعداد منافذ سیاهرگی دهلیز چپ دو برابر منافذ سیاهرگی دهلیز راست است.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:38:31', 5, 'done'),
(461, 'کدام عبارت دربارۀ ساختارهای نشان داده شده در شکل مقابل درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:36:54', 5, 'done'),
(462, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;با در نظر گرفتن یک دوره کار قلب که از ابتدای مرحله استراحت عمومی آغاز شده است و تا انتهای مرحله انقباض بطن&zwnj;ها ادامه پیدا می&zwnj;کند، می&zwnj;توان گفت که صدای مشابه &laquo;تاک&raquo; که از قلب شنیده می&zwnj;شود، .................. صدای شبیه بوم، ..................&raquo;', 1, 4, 15, 20, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:32:45', 3, 'done'),
(463, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;در دیواره قلب یک انسان بالغ، .................. رشته&zwnj;های کلاژنی که ..................&raquo; الف: همه ـ در بافت متصل به بافت پوششی قرار دارند، جزء برون&zwnj;شامه یا پیراشامه هستند. ب: همه - در لایه ماهیچه قلب قرار دارند، به تمام یاخته&zwnj;های ماهیچه&zwnj;ای این لایه متصل هستند. ج: فقط بعضی از در دیواره قلب وجود دارند، در بافتی هستند که در تماس مستقیم با یاخته&zwnj;های سنگفرشی است. د: فقط بعضی از - در نزدیکی مایع محافظت&zwnj;کننده از قلب هستند، قسمتی از بافت پیوندی متراکم می&zwnj;باشند.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:05:16', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(464, 'در ارتباط با یاخته&zwnj;های ماهیچه&zwnj;ای که در اندام&zwnj;های حفره قفسه سینه و یا دیواره جلویی آن وجود دارند، کدام عبارت درست است؟', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:05:02', 5, 'done'),
(465, 'در یک مرد سالم که در حالت استراحت قرار دارد، با توجه به مطالب کتاب درسی درباره وقایعی که طی دو چرخۀ ضربان قلب متوالی رخ می&zwnj;دهند، کدام گزینه می&zwnj;تواند عبارت زیر را به درستی کامل کند؟ &laquo;فقط در ............... مرحله ای از چرخه ضربان قلب که ...............مرحله چرخه قرار دارد ...............&raquo;', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:04:33', 5, 'done'),
(466, 'با توجه به شکل زیر که نوار قلب یک انسان سالم را نشان می&zwnj;دهد، کدام عبارت درباره نقاط مشخص شده در شکل درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:04:23', 5, 'done'),
(467, 'کدام موارد برای تکمیل عبارت زیر مناسب هستند؟ &laquo;در بدن مردی بالغ و سالم، نوعی رگ خونی که................&raquo; الف: حامل خون تیره است، به طور حتم قادر به جای دادن بیشتر حجم خون درون خود است. ب: خون غنی از اکسیژن را حمل می&zwnj;کند، ممکن است فضای داخلی وسیع و دیوارهای با مقاومت کم داشته باشد. ج: خون را وارد یک شبکه مویرگی می&zwnj;کند، ممکن است دهانه&zwnj;ای گرد داشته باشد که در نبود خون نیز باز می&zwnj;ماند. د: خون را از یک شبکه مویرگی خارج می&zwnj;کند، به طور حتم رشته&zwnj;های کشسان زیادی همراه لایه ماهیچه&zwnj;ای خود دارد.', 1, 4, 15, 22, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:30:53', 5, 'done'),
(468, 'مطابق کتاب درسی، دو عامل در تنظیم جریان خون در مویرگ&zwnj;ها نقش دارند. کدام ویژگی، عامل کم اهمیت&zwnj;تر را از عامل اصلی تنظیم جریان خون در مویرگ&zwnj;ها متمایز می&zwnj;سازد؟', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:04:49', 5, 'done'),
(469, 'چند مورد دربارۀ همۀ مویرگ&zwnj;های موجود در بدن انسان درست است؟ الف: حفظ فشار اسمزی درون آن&zwnj;ها بر عهده آلبومین می&zwnj;باشد. ب: بخشی از مواد موجود در فضای میان بافتی می&zwnj;توانند وارد آن&zwnj;ها شوند. ج: نوعی بافت پیوندی به صورت منظم و یک&zwnj;طرفه درون آن&zwnj;ها جریان دارد. د: یاخته&zwnj;های سنگفرشی با فضای بین یاخته&zwnj;ای اندک دیواره آن&zwnj;ها را تشکیل می&zwnj;دهند.', 1, 4, 15, 22, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:37:58', 5, 'done'),
(470, 'با توجه به مطالب کتاب درسی درباره تبادل مواد در انواع مویرگ&zwnj;ها کدام عبارت درست است؟', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:04:41', 5, 'done'),
(471, 'چند مورد درباره بدن انسان درست است؟ الف: كولون پایین رو برخلاف کولون بالارو، محتویات لنفی خود را مستقیماً وارد ضخیم&zwnj;ترین مجرای لنفی می&zwnj;کند. ب: مجرای لنفی راست برخلاف مجرای لنفی چپ، هنگام طی مسیر در قفسه سینه دارای گره&zwnj;هایی در مسیر خود است. ج: مجرای لنفی راست بلافاصله پس از جدا شدن از مجرای لنفی چپ، از مجاورت اندامی دارای مویرگ&zwnj;های ناپیوسته عبور می&zwnj;کند. د: در نزدیکی یکی از دو سر استخوان ران برخلاف سر دیگر، گره&zwnj;های لنفی جمع شده&zwnj;اند و محتویات لنفی هر دو سر به مجرای لنفی چپ می&zwnj;ریزند.', 1, 4, 15, 21, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:38:14', 5, 'done'),
(472, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;مطابق مطالب کتاب درسی، هر ................ که برای ساخته شدن گویچه&zwnj;های قرمز در مغز استخوان لازم است، ................&raquo; الف: ماده غیر&zwnj;آلی ـ حاصل تجزیه گروه هم در طحال یا کبد می&zwnj;باشد. ب: مولکول غیر&zwnj;زیستی &ndash; می&zwnj;تواند در شرایطی، به عملکرد نوعی آنزیم کمک کند. ج: ویتامین از خانواده B- در سبزیجات با برگ سبز تیره به فراوانی یافت می&zwnj;شود. د: ماده مؤثر در کارکرد صحیح فولیک&zwnj;اسید - توسط یاخته&zwnj;های پرز روده جذب می&zwnj;شود.', 1, 4, 15, 24, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:37:28', 5, 'done'),
(473, 'چند مورد درباره یاخته های خونی سفید درست است؟ الف: همه یاخته&zwnj;های دارای دانه&zwnj;های درشت برخلاف همه یاخته&zwnj;های فاقد دانه، هسته دو&zwnj;قسمتی دارند. ب: همه یاخته&zwnj;های دارای دانه&zwnj;های روشن برخلاف همۀ یاخته&zwnj;های دارای دانه&zwnj;های تیره، هسته چند&zwnj;قسمتی دارند. ج: همه یاخته&zwnj;های دانه&zwnj;دار برخلاف همۀ یاخته&zwnj;های دارای هسته تکی، حاصل تقسیم یاخته بنیادی میلوئیدی هستند. د: همه یاخته&zwnj;های حاصل از تقسیم یاخته بنیادی لنفوئیدی برخلاف همه یاخته&zwnj;های حاصل از تقسیم یاخته بنیادی میلوئیدی اندازه&zwnj;ای کوچک دارند.', 2, 4, 23, 91, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:37:46', 5, 'done'),
(474, 'کدام عبارت، درباره دستگاه گردش خون انسان نادرست است؟', 1, 4, 15, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:34:06', 3, 'done'),
(475, 'کدام عبارت، درباره اجزایی از خون که در نتیجه قطعه&zwnj;قطعه شدن مگاکاریوسیت&zwnj;ها تولید می&zwnj;شوند، درست است؟', 1, 4, 15, 25, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:30:28', 5, 'done'),
(476, 'با توجه به شکل مقابل که بخشی از دستگاه دفع ادرار یک جانور را نشان می&zwnj;دهد، کدام عبارت درست است؟', 1, 4, 16, 31, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:37:14', 5, 'done'),
(477, 'چند مورد، برای تکمیل عبارت زیر نامناسب است؟ &laquo;در هر یک از بخش&zwnj;های کلیه که قسمتی از فرایند تشکیل ادرار، درون آن رخ می&zwnj;دهد و ................&raquo; الف: مستقیماً در ارتباط با یک شبکه مویرگی قرار دارد، در بخش قشری کلیه است. ب: به شکل لوله&zwnj;ای مستقیم است، ضخامت یکسانی در بخش&zwnj;های مختلف خود ندارد. ج: درون یکی از هرم&zwnj;های کلیه دیده می&zwnj;شود، محل انجام فرایند بازجذب است. د: بیشترین میزان پیچ&zwnj;خوردگی را دارد، بین دو بخش لوله&zwnj;ای قرار گرفته است.', 1, 4, 16, 27, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:03:54', 5, 'done'),
(478, 'کدام عبارت، درباره ساختار درونی کلیه یک انسان سالم و بالغ درست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:03:37', 5, 'done'),
(479, 'با توجه به مطالب کتاب درسی درباره مراحل فرایند تشکیل ادرار، کدام مورد یا موارد درست هستند؟ الف: مرحله&zwnj;ای که در جهت مخالف مرحله&zwnj;ای دیگر انجام می&zwnj;شود، معمولاً نیازمند صرف انرژی زیستی است. ب: مرحله&zwnj;ای که در تنظیم میزان pH خون، نقش مهم&zwnj;تری دارد، همواره وابسته به شبکه مویرگی دورلوله&zwnj;ای است. ج: مرحله&zwnj;ای که باعث ورود مواد سمی به درون گردیزه (نفرون) می&zwnj;شود، فقط در مجاورت یاخته&zwnj;های سنگفرشی نفرون رخ می&zwnj;دهد. د: مرحله&zwnj;ای که غلظت مواد تراوش شده را تغییر داده و باعث ایجاد ترکیب نهایی ادرار می&zwnj;شود، فقط در ساختارهای لوله&zwnj;ای&zwnj;شکل رخ می&zwnj;دهد.', 1, 4, 16, 29, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:30:19', 5, 'done'),
(480, 'پس از فعال شدن سازوکار تخلیه ادرار در یک نوزاد یک ماهه، کدام اتفاق زودتر از سایرین رخ می&zwnj;دهد؟', 1, 4, 16, 30, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:37:01', 5, 'done'),
(481, 'با در نظر گرفتن همه وظایفی که کلیه برای انجام دادن نقش اساسی خود در هم&zwnj;ایستایی (هومئوستازی) دارد، کدام عبارت، درست است؟', 1, 4, 16, 29, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:38:20', 5, 'done'),
(482, 'کدام عبارت، درباره دستگاه دفع ادرار انسان، نادرست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:03:28', 5, 'done'),
(483, 'کدام گزینه&zwnj; برای تکمیل عبارت زیر نامناسب است؟ &laquo;ماده&zwnj;ای درون ادرار یک انسان بالغ و سالم که .................&raquo;', 1, 4, 16, 30, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:04:02', 5, 'done'),
(484, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در یک لپ (لوب) کلیه، بخشی.................، به طور حتم.................&raquo;', 1, 4, 16, 28, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:03:06', 5, 'done'),
(485, 'در یک انسان بالغ، همۀ انواع ساختارهایی که دارای نقش در محافظت از کلیه هستند، چه مشخصه&zwnj;ای دارند؟', 1, 4, 16, 27, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:38:00', 5, 'done'),
(486, 'کدام عبارت درباره انسان درست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:02:52', 5, 'done'),
