(546, 'براساس مطلب کتاب درسی، شروع یکی از انواع حرکات ایجاد شده در طول لوله گوارش بدون دخالت شبکه های یاخته های عصبی صورت می گیرد. کدام گزینه فقط در خصوص این نوع از حرکات صدق می کند؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:58:04', 5, 'done'),
