(602, 'مطابق با مطلب کتاب درسی، کدام مورد، ویژگی مشترک مهره دارانی است که به منظور تنظیم فشار اسمزی مایعات بدن خود، علاوه بر کلیه ها، از ساختارهای مرتبط با دستگاه گوارش، برای دفع محلول غلیظ نمک استفاده می کنند؟', 1, 4, 15, 26, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:26:53', 5, 'done'),
(603, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در پیکر نوعی اسفنج مطرح شده در کتاب درسی، یاخته هایی که منافذ ورود آب را تشکیل می دهند ............. یاخته های حرکت دهنده آب در حفره میانی، ........... .&raquo;', 1, 4, 14, 18, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 09:56:47', 5, 'done'),
(604, 'طبق اطلاعات کتاب درسی، همه جانورانی که تعامل مستقیمی میان سامانه تنظیم اسمزی و بخشی از روده آن ها وجود دارد، چه مشخصه ای دارند؟', 1, 4, 16, 31, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:08:02', 5, 'done'),
(605, 'درستی یا نادرستی هر یک از ویژگی های زیر در خصوص دستگاه گردش خون ماهی، به ترتیب کدام است؟ حجم بخشی که بلافاصله قبل از سرخرگ شکمی قرار دارد، نسبت به بالاترین حفره قلبی بیشتر است. حفره ای از قلب با بیشترین فاصله از باله شکمی، در سطح بالاتری نسبت به حفره دیگر قلب قرار دارد. خون ورودی به بخش مخروطی شکل جلوی بطن، اکسیژن کم تری نسبت به خون خروجی از آبشش ها دارد. جابه جایی خون میان شبکه های مویرگی آبششی و عمومی بدن فقط به واسطه یک بار عبور خون از قلب بین این دو شبکه انجام می شود.', 1, 4, 15, 26, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:27:08', 5, 'done'),
(606, 'کدام ویژگی، ماهی های آب شیرین را از ماهی های آب شور متمایز می سازد؟', 1, 4, 16, 31, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:07:47', 5, 'done'),
(607, 'مطابق با مطلب کتاب درسی، ویژگی مشترک همۀ مهره دارانی که می توانند نمک اضافه را از طریق غدد نمکی نزدیک چشم یا زبان، به صورت قطره های غلیظ دفع کنند، کدام است؟', 1, 4, 16, 31, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:07:29', 5, 'done'),
(608, 'مطابق با مطلب کتاب درسی، گروهی از بی مهرگان مویرگ ندارند و همولنف مستقیماً به فضای بین یاخته های بدن آن ها وارد می شود و در مجاورت آن ها جریان می یابد. اگر این جانوران واجد تنفس نایدیسی باشند، کدام ویژگی زیر در خصوص آن ها نادرست است؟', 1, 4, 15, 26, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:07:19', 5, 'done'),
(609, 'کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;با توجه به اطلاعات کتاب درسی، هر نوع روش تنفسی در جانوران که اکسیژن رسانی به یاخته ها را می تواند با دخالت مویرگ های خونی انجام دهد، برخلاف هر نوع روش تنفسی که همواره تبادل گازها با محیط در آن، بدون نیاز به کمک مویرگ ها انجام می پذیرد، .............. .&raquo;', 1, 4, 14, 18, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:07:09', 5, 'done'),
(610, 'مطابق با مطلب کتاب درسی، انواعی از جانوران خشکی زی می توانند رفتاری را بروز دهند که در آن بقا و موفقیت تولیدمثلی جانور دیگری را با هزینه کاسته شدن از احتمال بقا و تولیدمثل خود، افزایش می دهند. کدام مورد ویژگی مشترک جمعیت این جانوران است؟', 3, 4, 35, 169, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 20:56:28', 4, 'done'),
(611, 'با توجه به شکل مقابل که بخشی از دستگاه گوارش بدن نوعی مهره دار را نشان می دهد، کدام عبارت صحیح است؟', 1, 4, 13, 13, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:06:57', 5, 'done'),
(612, 'مطابق با اطلاعات کتاب درسی در خصوص قسمت&zwnj;های مختلف دستگاه گوارش انسان، کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;هر قسمتی از دستگاه گوارش که آنزیم&zwnj;های ................... موجود در لوله گوارش را می&zwnj;سازد به طور حتم ...................&raquo;', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:32:24', 5, 'done'),
(613, 'در بدن یک انسان سالم و بالغ اندام&zwnj;هایی وجود دارند که به طور مستقیم غلظت اوره موجود در خون را تغییر می&zwnj;دهند. کدام مورد، فقط درخصوص برخی از این اندام&zwnj;ها درست است؟', 1, 4, 15, 24, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:06:45', 5, 'done'),
(614, 'در خصوص مقایسۀ لایه&zwnj;های تشکیل&zwnj;دهنده دیواره قلب، کدام مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول در بدن انسان ................... یاخته&zwnj;های لایه&zwnj;ای از قلب که................... . &raquo;', 1, 4, 15, 19, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:31:58', 5, 'done'),
(615, 'پسری ۱۵ ساله در پی آزمایش ادرار خود متوجه وجود مقداری گلوکز در آن شده است. درخصوص این فرد چند مورد می&zwnj;تواند درست باشد؟ الف: وجود نوعی ماده سمی با اثر بر راکیزه&zwnj;های گردیزه، باعث توقف بازجذب فعال مواد شده است. ب: مقدار نسبت ATP به ADP در یاخته&zwnj;های عصبی قرار گرفته در مرکز تشنگی در هیپوتالاموس افزایش می&zwnj;یابد. ج: میزان تولید کربن دی&zwnj;اکسید در یاخته&zwnj;های بدن، به علت اختلال در فعالیت گیرنده&zwnj;های پروتئینی غشا کاهش می&zwnj;یابد. د: نوعی نقص در ژن&zwnj;های مربوط به پمپ هیدروژن در یاخته&zwnj;های گردیزه، باعث افزایش سرعت تشکیل رادیکال&zwnj;های آزاد شده است.', 1, 4, 16, 30, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:06:21', 5, 'done');
