(618, 'مطابق مطالب کتاب درسی، کدام مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول در بدن انسان، هر مرحله از تشکیل ادرار که .................. . &raquo;', 1, 4, 16, 29, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:29:55', 5, 'done'),
