(621, 'کدام عبارت درباره یک گردیزه (نفرون) کلیه انسان و گردش خون آن، نادرست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:29:31', 5, 'done'),
(622, 'مطابق مطلب کتاب درسی، در پرده صفاق متصل&zwnj;کننده روده&zwnj;ها به یکدیگر، سرخرگی وجود دارد که انشعابات آن، خون&zwnj;رسانی روده&zwnj;ها را برعهده دارند. کدام عبارت درباره این سرخرگ درست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:29:17', 5, 'done'),
(623, 'مشاهده کدام مورد در بدن یک انسان بالغ غیر&zwnj;ممکن است؟', 1, 4, 15, 23, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:44:03', 3, 'done'),
(624, 'انشعابی از نایژه اصلی در شش چپ انسان، در نهایت نایژک&zwnj;های مبادله&zwnj;ای در قسمت میانی شش را می&zwnj;سازد. کدام عبارت درباره این انشعاب از نایژه اصلی درست است؟', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:31:18', 5, 'done'),
(625, 'کدام مورد، ویژگی مشترک همۀ اجزای سازنده لخته خون است؟', 1, 4, 15, 25, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:45:30', 3, 'done'),
(626, 'مطابق با اطلاعات کتاب درسی، اندام&zwnj;هایی در دستگاه گوارش انسان (به جز روده) که با ترشح آنزیم می&zwnj;توانند باعث شکل&zwnj;گیری مجدد گروه کربوکسیل آزاد در آمینواسیدها شوند چه ویژگی مشترکی دارند؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:31:35', 5, 'done'),
(627, 'در ارتباط با نموداری که دم سنج (اسپیرومتر) از دم و بازدم&zwnj;های یک فرد رسم کرده است، کدام عبارت درست می&zwnj;باشد؟', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:46:09', 3, 'done'),
(628, 'با توجه به مطالب کتاب درسی و شکل زیر که ساختار لوله گوارش یک جانور را نشان می&zwnj;دهد، کدام عبارت درست است؟', 1, 4, 15, 26, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:24:26', 5, 'done'),
(629, 'در شکل زیر، محدوده&zwnj;های مختلفی از منحنی نوار قلب یک انسان سالم (در حالت استراحت) نشان داده شده است. با توجه به شکل، کدام عبارت درست است؟', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:24:14', 5, 'done'),
(630, 'کدام عبارت، درباره ساختار و عملکرد کلیه&zwnj;های انسان درست است؟', 1, 4, 16, 27, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:24:34', 5, 'done'),
(631, 'کدام عبارت، درباره بدن انسان نادرست است؟', 1, 4, 13, 11, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 20:56:53', 4, 'done'),
(632, 'مطابق با اطلاعات کتاب درسی، کدام مورد ویژگی مشترک جانوران و گیاهان را نشان می&zwnj;دهد؟', 1, 4, 12, 5, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:24:03', 5, 'done'),
(633, 'در خصوص نوعی بافت که سطح بدن و سطح حفره&zwnj;ها و مجاری درون بدن را می&zwnj;پوشاند، کدام مورد صحیح است؟', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:23:36', 5, 'done'),
(634, 'با توجه به سه نوع بافت پیوندی سست، متراکم و چربی، در کدام مورد، هر دو ویژگی مطرح شده، مربوط به یک نوع بافت هستند؟', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:26:37', 5, 'done'),
(635, 'در خصوص انواع مختلف مولکول&zwnj;های زیستی، کدام مورد یا موارد برای تکمیل عبارت زیر مناسب هستند؟ &laquo;هر مولکول زیستی که .................. به طور حتم .................. .&raquo; الف: بیشترین تنوع عناصر را دارد - به شکل مولکولی پیچ&zwnj;خورده و نربانی&zwnj;شکل قرار دارد ب: توسط یاخته&zwnj;های جانوری زنده تولید می&zwnj;شود - دارای اتم هیدروژن در ساختار خود است ج: در ساخت غشای یاخته&zwnj;ها نقش دارد - اسیدهای چرب متقارن آن به ترکیب گلیسرول و فسفات متصل است د: می&zwnj;تواند انرژی فعال&zwnj;سازی واکنش&zwnj;ها در یاخته&zwnj;های بدن را کاهش دهد - امکان مشاهده چندین زیرواحد یکسان در طول خود را دارد', 1, 4, 12, 5, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:23:29', 5, 'done'),
(636, 'کدام مورد در ارتباط با همۀ ساختارهای کیسه&zwnj;مانند که در یک یاخته زنده مشاهده می&zwnj;شوند، به طور حتم صحیح است؟', 1, 4, 12, 6, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 20:57:09', 4, 'done'),
(637, 'با توجه به لیپیدهایی که تصویر آن&zwnj;ها در گفتار دوم فصل اول کتاب درسی آورده شده، چند مورد از موارد زیر درست است؟ الف: وجه تمایز آن&zwnj;ها، ساختار خمیده و غیر&zwnj;مستقیم اسیدهای چرب است. ب: وجه اشتراک آن&zwnj;ها، تعداد اسیدهای چرب متصل به گلیسرول است. ج: وجه اشتراک آن&zwnj;ها، اتصال اسیدهای چرب به ساختاری کروی است. د: وجه تمایز آن&zwnj;ها، اتصال مولکول گلیسرول به گروه فسفات است.', 1, 4, 12, 5, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:49:33', 3, 'done'),
(638, 'در خصوص مقایسه انواع بافت پیوندی سست و متراکم، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول، در بافت پیوندی سست .................. بافت پیوندی متراکم، ..................&raquo;', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:26:30', 5, 'done'),
(639, 'در ارتباط با اندامک&zwnj;های قابل مشاهده در یک یاخته جانوری، چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;هر اندامکی که .................. به طور حتم ..................است.&raquo; الف: در اتصال مستقیم با غشا خارجی هسته قرار دارد - دارای شبکه گسترده&zwnj;ای از کیسه&zwnj;ها در سراسر سیتوپلاسم ب: در بسته&zwnj;بندی و ترشح مواد به خارج از یاخته نقش دارد ـ به شکل کیسه&zwnj;&zwnj;هایی متصل به&zwnj;هم قابل مشاهده ج: در ساخت اجزای تشکیل&zwnj;دهنده غشای یاخته&zwnj;ای نقش دارد - دارای غشا در ساختار خود د: دو غشای فسفولیپیدی در ساختار خود دارد - دارای نقش در تأمین انرژی یاخته', 1, 4, 12, 6, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:26:21', 5, 'done'),
(640, 'به طور طبیعی، در خصوص ترتیب وقایع مربوط به دستگاه گوارش انسان، کدام عبارت نادرست است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:28:12', 5, 'done'),
