(643, 'در خصوص لایه&zwnj;ای از لوله گوارش که دارای شبکه عصبی است و فاصله کمتری از صفاق دارد، کدام مورد درست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:23:14', 5, 'done'),
