(649, 'در ارتباط با شبکه&zwnj;های عصبی روده&zwnj;ای و دستگاه عصبی خودمختار، کدام عبارت در مقایسه با سایر عبارات، مشخصه شبکه&zwnj;ای متفاوت را بیان می&zwnj;کند؟', 1, 4, 13, 11, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:22:38', 5, 'done'),
(650, 'مطابق مطالب کتاب درسی، کدام مورد ویژگی مشترک حجم&zwnj;های تنفسی را که با انقباض ماهیچه&zwnj;های بین دنده&zwnj;ای خارجی همراه است را بیان می&zwnj;کند؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:22:25', 5, 'done'),
(651, 'در خصوص نایژه اصلی که درون ششی با دو لوب انشعاب می&zwnj;یابد، کدام مورد یا موارد زیر درست است؟ الف: در مقایسه با نایژه دیگر تعداد حلقه&zwnj;های غضروفی آن کمتر است. ب: فاصله حلقه&zwnj;های غضروفی آن در مقایسه با نایژه دیگر، بیشتر است. ج: در مقایسه با نایژۀ دیگر زودتر انشعابات تنفسی دیگر را ایجاد می&zwnj;کند. د: زاویه&zwnj;ای که این نایژه با نای می&zwnj;سازد، در مقایسه با نایژه دیگر کمتر است.', NULL, 4, 14, 14, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:22:14', 5, 'done'),
(652, 'در ارتباط با گردش خون دستگاه گوارش یک فرد سالم، کدام مورد درست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:21:49', 5, 'done'),
(653, 'در فردی سالم و ایستاده، خطی فرضی و عمودی در وسط بدن رسم کرده و بدن را به دو نیمۀ راست و چپ تقسیم می&zwnj;کنیم. در کدام مورد، هر دو بخش ذکر شده در یک نیمه از بدن قرار دارد؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:11:02', 5, 'done'),
(654, 'با توجه به نمودار زیر که منحنی اسپیروگرام در فردی سالم را نشان می&zwnj;دهد، کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور طبیعی، در هنگام ثبت نقطه .................. در این منحنی، به طور حتم .................. قابل مشاهده است.', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:21:24', 5, 'done'),
