(656, 'مطابق مطالب کتاب درسی، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان به منظور انجام هر نوع عمل.................. .&raquo;', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 22:21:01', 5, 'done'),
