(663, 'دسته&zwnj;ای از رگ&zwnj;ها ساختار خاصی دارند که باعث می&zwnj;شود با ورود خون، قطر آن&zwnj;ها تغییر زیادی نکند و در برابر جریان خون مقاومت کنند. کدام عبارت، در ارتباط با این رگ&zwnj;ها صحیح است؟', 1, 4, 15, 22, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:26:00', 5, 'done'),
(664, 'در ارتباط با مقایسه میان انواع مختلف یاخته&zwnj;های خونی سفید، کدام مورد صحیح است؟', 2, 4, 23, 91, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:25:43', 5, 'done'),
(665, 'در دستگاه گردش خون انسان، سه نوع رگ در شبکه&zwnj;ای مرتبط به هم وجود دارد. در کدام عبارت هر دو مورد، مربوط به یک نوع از این رگ&zwnj;ها هستند؟', 1, 4, 15, 22, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:25:27', 5, 'done'),
