(667, 'دو مورد ذکر شده در کدام گزینه، تأثیر متفاوتی بر کاهش یا افزایش احتمال بروز خیز (ادم) دارند؟', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:27:58', 5, 'done'),
(668, 'چند مورد از موارد زیر، درخصوص ساختار بافتی قلب صحیح است؟ الف: درون&zwnj;شامه برخلاف لایه میانی، در استحکام دریچه&zwnj;های قلبی نقش دارد. ب: لایه میانی همانند درون&zwnj;شامه&zwnj;، یاخته&zwnj;هایی در تماس با رشته&zwnj;های پروتئینی دارد. ج: هر بافت پیوندی متراکم موجود در لایه&zwnj;های قلب باعث استحکام دریچه&zwnj;های قلبی می&zwnj;شود. د: تعداد یاخته&zwnj;های ماهیچه&zwnj;ای متصل به رشته&zwnj;های کلاژن بیشتر از یاخته&zwnj;های ماهیچه&zwnj;ای فاقد این اتصال است.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:28:40', 5, 'done'),
(669, 'مطابق شکل زیر که نوار قلب فردی سالم را نشان می&zwnj;دهد، کدام مورد درست است؟', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:27:34', 5, 'done'),
