(671, 'به طور طبیعی در خصوص دستگاه لنفی یک فرد بالغ کدام مورد درست است؟', 1, 4, 15, 21, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:27:44', 5, 'done'),
(672, 'به علت کاهش شدید فشار خون و جهت حرکت خون در سیاهرگ&zwnj;ها که در بیشتر آن&zwnj;ها به سمت بالا است، لازم است عواملی به جریان خون در سیاهرگ&zwnj;ها کمک کنند. کدام مورد در ارتباط با دو عاملی که به کمک یکدیگر، تأثیر نهایی خود را اعمال می&zwnj;کنند صحیح است؟', 1, 4, 15, 22, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:28:57', 5, 'done'),
(673, 'خون نوعی بافت پیوندی است که به طور منظم در رگ&zwnj;های خونی جریان دارد و دارای دو بخش است. کدام مورد درخصوص بخش&zwnj;های خون در فردی سالم درست است؟', 1, 4, 15, 24, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-11 21:23:28', 5, 'done'),
