(716, 'براساس اطلاعات کتاب درسی، تشکیل ساقه ها و ریشه هایی با قطر زیاد، در نهان دانگان دولپه ای حاصل فعالیت انواعی از مریستم ها است. کدام گزینه زیر مشخصه آن دسته از مریستم هایی است که با کندن پوست درختان در معرض آسیب های محیطی قرار می گیرند؟', 1, 4, 17, 38, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:17:19', 5, 'done'),
(717, 'کدام مورد، در ارتباط با یاخته های گیاهی زنده و فعال صحیح است؟', 1, 4, 17, 33, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 10:19:58', 5, 'done'),
(718, 'براساس مطالب کتاب درسی، گیاهان علفی نهان دانه که در بخش مرکزی ریشه خود، فقط یاخته های زنده دارند. برخلاف گیاهان علفی که پوستی ضخیم در ریشۀ خود دارند، چه مشخصه ای دارند؟', 1, 4, 17, 39, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 18:57:17', 3, 'done'),
(719, 'مطابق اطلاعات کتاب درسی، کدام گزینه، در خصوص انتقال مواد در عرض ریشه گیاهان نهان دانه علفی درست است؟', 1, 4, 18, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:28', 1, '2026-02-12 19:05:40', 3, 'done'),
(720, 'کدام عبارت، فقط در خصوص برخی از مراحل الگوی جریان فشاری ارنست مونش صادق است که طی آن ها، تبادل آب میان انواع یاخته های آوندی فاقد هسته مشاهده می شود؟', 1, 4, 18, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:06:19', 3, 'done'),
(721, 'مطابق با اطلاعات کتاب درسی، گروهی از گیاهان نهان دانه علفی می توانند یاخته های چوبی شده دوکی شکل و دراز فراوانی را در مرکزی ترین قسمت ریشه خود جای دهند. کدام موارد ویژگی مشترک این گروه از گیاهان است؟ الف: بخش پوست در ریشه آن ها کاملاً مشخص و ضخیم است. ب: برگ های پهن و ریشه ای غیر مستقیم با انشعابات فرعی فراوان ایجاد می کنند ج: دسته های آوندی چوب و آبکش ساقه بر روی دوایر متحدالمرکز قرار دارند. د: در ساقه، آوندهای آبکش نسبت به آوندهای چوبی، فاصله کمتری از روپوست دارند.', 1, 4, 17, 39, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:09:13', 3, 'done'),
(722, 'کدام ویژگی، یاخته های رایج ترین بافت سامانه زمینه ای در نهان دانگان را از یاخته هایی از این سامانه که معمولاً زیر روپوست قرار می گیرند، متمایز می سازد؟', 1, 4, 17, 34, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:12:42', 3, 'done'),
(723, 'در خصوص ساختارهای بین یاخته ای کانالی شکل، مربوط به منطقه ای از برگ گیاه لوبیا (در حد فاصل روپوست بالایی و پایینی) که جابه جایی مواد مغذی بین یاخته های زنده مجاور را تسهیل می نمایند، چند مورد زیر درست است؟ الف: دو امتداد آن ها به پروتوپلاست ختم می شود. ب: می توانند منافذ بزرگی با امکان عبور ویروس های گیاهی باشند. ج: در بخش های خاصی از دیواره نسبت به سایر بخش ها فراوان تر هستند. د: نازک ترین بخش یک دیواره یاخته ای در ساختار آن ها دیده می شود.', 1, 4, 17, 32, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:14:44', 3, 'done'),
(724, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور طبیعی در یک گیاه نهان دانه علفی، هر مریستمی که ................ .&raquo;', 1, 4, 17, 38, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:15:43', 3, 'done'),
(725, 'با توجه به مطلب کتاب درسی، در ارتباط با یک یاخته گیاهی زنده و فعال، &laquo;درستی&raquo; یا &laquo;نادرستی&raquo; هر یک از عبارت های زیر به ترتیب کدام است؟ لیگنین پس از برون رانی از غشای پروتوپلاست، ممکن است با عبور از هر بخش حاوی پکتین در دیواره یاخته ای، به دیواره پسین افزوده شود. سیتوپلاسم یاخته، ممکن است در بخش هایی با مسن ترین بخش دیواره و جوان ترین بخش دیواره در مجاورت باشد. غشای پروتوپلاست، ممکن است در بخش هایی با تیغه میانی و در بخش هایی با دیواره حاوی پکتین و سلولز در تماس باشد. غشای پروتوپلاست، ممکن است در بخش هایی با بخش (های) قادر به گسترش و کشش و در بخش هایی با ساختار چند لایه دیواره یاخته ای در تماس باشد.', 1, 4, 17, 32, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:18:52', 3, 'done'),
(726, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;نوعی کامبیوم در پیکر یک درخت ۸ ساله که ................ نوع دیگر کامبیوم، ............... .&raquo;', 1, 4, 17, 38, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:22:25', 5, 'done'),
(727, 'براساس اطلاعات کتاب درسی، کدام گزینه، عبارت زیر را به طور مناسب کامل می کند؟ &laquo;همۀ گیاهانی که با دو گروه مهم باکتری های تثبیت کننده نیتروژن رابطه همزیستی دارند، .............. .&raquo;', 1, 4, 18, 172, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 21:01:39', 4, 'done'),
(728, 'کدام گزینه عبارت زیر را به طور نامناسب تکمیل می کنند؟ &laquo;در گروهی از گیاهان روی زمین، انواعی از روزنه وجود دارد که نوعی از آن ها در انتها یا لبه برگ ها قرار دارد و این روزنه ها نوعی از فرایندهای گیاهی را انجام می دهند. اگر شرایط محیطی ایجاد کننده این فرایند مشابه شرایط ایجاد شبنم باشد، به دنبال ........... و امکان خروج قطرات آب از برگ از طریق این روزنه ها وجود دارد&raquo;.', 1, 4, 18, 173, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 21:00:47', 4, 'done'),
(729, 'با توجه به گیاهان مطرح شده در فصل (۷) زیست شناسی (۱)، کدام مورد زیر فقط در خصوص برخی از گیاهانی که همه یا بخشی از آب و مواد غذایی خود را از گیاهان فتوسنتز کننده دریافت می کنند، صحیح است؟', 1, 4, 18, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 19:39:19', 3, 'done'),
