(744, 'در گروهی از نهان دانگان دولپه ای که توانایی چندین سال عمر را دارند، به دنبال تقسیم برخی مریستم ها، ساقه هایی با قطر (ضخامت) بسیار زیاد تشکیل می شوند. کدام مورد در خصوص این مریستم ها صادق است؟', 1, 4, 17, 38, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 21:01:18', 4, 'done'),
(745, 'براساس اطلاعات کتاب درسی در خصوص گیاهان نهان دانه، کدام گزینه صحیح است؟', 2, 4, 26, 41, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:37:10', 5, 'done'),
(746, 'در نوعی گیاه نهان دانۀ دولپه، در آینده نوعی مریستم ایجاد و فعال خواهد شد. در خصوص این نوع مریستم چند مورد به طور حتم صحیح است؟ الف: سبب تغییر در نوع سامانه پوششی گیاه می گردد. ب: سبب بروز ویژگی (های) مشترک بین جانداران می شود. ج: از تقسیم آن یاخته هایی با دیواره نخستین نازک تولید می شود. د: در افزایش قطر زیاد ساقه و ریشه گیاه نقش مهمی را ایفا می کند.', 1, 4, 17, 38, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-20 13:45:29', 3, 'done'),
(747, 'با توجه به ساختار دیواره یاخته ای در یاخته های زنده کلانشیمی و آن دسته از ترکیبات آلی که منشأ تشکیل دو بخش اصلی این ساختار هستند، کدام مورد نادرست است؟', 1, 4, 17, 32, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-20 13:47:53', 3, 'done'),
(748, 'مطابق اطلاعات کتاب درسی، گروهی از جانداران فتوسنتز کننده در مناطقی زندگی می کنند که از نظر نیتروژن فقیر هستند. مشخصه مشترک این جانداران کدام است؟', 3, 4, 28, 149, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-20 13:52:23', 3, 'done'),
(749, 'مطابق جانوران مطرح شده در کتاب درسی، کدام گزینه ویژگی مشترک جانوران مهاجمی را، که توسط مورچه های همزیست با درخت آکاسیا مورد حمله قرار می گیرند، به درستی بیان می کند؟ الف: در محل مویرگ ها، ترکیباتی را وارد مایع بین یاخته ای می کنند. ب: در هر چشم آن ها، قرنیه و گیرنده های نوری، دارای تماس مستقیم با یکدیگر هستند. ج: در بخش جلویی طناب عصبی خود، ساختار یا ساختارهای برجسته عصبی دارند. د: اعصاب خارج شده از اندام های حرکتی، می تواند به طور مستقیم وارد طناب عصبی شود.', 2, 4, 19, 61, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-20 13:53:19', 3, 'done'),
(750, 'مطابق اطلاعات کتاب درسی و در خصوص نوعی گیاه دو لپه، کدام ویژگی یا ویژگی ها را می توان فقط به دو نوع از یاخته های بالغی نسبت داد که توسط بخش مشخص شده در شکل مقابل تولید می شوند؟ الف: نبود مرکز تنظیم ژنتیک یاخته ب: از دست دادن دیواره عرضی بین یاخته ای ج: نبود کانال های سیتوپلاسمی در دیواره یاخته ای د: حمل برخی مواد به دنبال خروج بخار آب از منفذ بین یاخته های نگهبان روزنه', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(751, 'با توجه به مطالب مطرح شده در کتاب درسی، کدام مورد نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(752, 'با توجه به مطالب کتاب درسی، دربارۀ اندامک هایی که در یک یاخته گیاهی می توانند ساختار کیسه ای شکل داشته باشند، چند مورد عبارت زیر را به درستی تکمیل می کند؟ &laquo;هر یک از آن ها که ................. .&raquo; الف: دارای پروتئین های ساخته شده توسط رناتن ها هستند، فاقد آنزیم های تجزیه کننده مواد هستند ب: به سمت بخش های دیگر یاخته جابه جا می شوند، در پی تغییر موقعیت نوعی ساختار فسفولیپیدی ایجاد شده اند ج: بیش از یک بخش کیسه مانند دارد، از طریق کانال های پروتئینی غشای خود، موادی را به درون خود وارد می کند د: می توانند در طول حیات یاخته، اندازه های متفاوتی داشته باشند، قابلیت ذخیره ترکیبات رنگی را درون خود دارند', 1, 4, 12, 6, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:36:37', 5, 'done'),
(753, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول، فقط بعضی از روش های انتقال مواد در عرض ریشه گیاه دولپه که برای انجام شدن آن ها، حضور یاخته های زنده الزامی است، . ...............&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(754, 'در ریشه نوعی گیاه با برگ های باریک و دراز، یاخته هایی مشاهده می شوند که در زیر میکروسکوپ، ظاهری نعلی یا U شکل دارند. کدام موارد زیر مشخصه این یاخته ها است؟ الف: در خارجی ترین لایه بخش آوندی ریشه قرار دارند. ب: انتقال آب و مواد محلول را به آوندهای چوبی انجام می دهند. ج: در آن ها، آب و مواد محلول آماده جابه جایی برای مسیرهای طولانی می شوند. د: فقط در یکی از دیواره های خود فاقد نواری از جنس چوب پنبه (سوبرین) هستند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(755, 'کدام ویژگی را می توان به نوعی گیاه علفی چندین ساله که به منظور تولید میوه، برخی مواد جذب شده از طریق ریشه را به دسته های آوندی مستقر در چند حلقه در ساقه، منتقل می کند، نسبت داد؟', 1, 4, 17, 39, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 21:02:12', 4, 'done'),
(756, 'در خصوص مسن ترین لایه از دیواره یاخته ای که می تواند در یاخته های گیاهی مطرح شده در کتاب درسی وجود داشته باشد، چند مورد زیر درست است؟ الف: ساخته شدن آن می تواند بدون ترشح موادی به خارج از پروتوپلاست یاخته صورت گیرد. ب: به طور حتم به دنبال تقسیم یاخته، در همه بخش های دیواره بین دو یاخته حاصل از تقسیم، مشاهده می شود. ج: ممکن است در بخشی از مراحل رشد یاخته های واجد دیواره پسین، در تماس مستقیم با فسفولیپیدهای غشا باشد. د: ممکن است از به هم پیوستن گروهی از ریزکیسه ها در محلی غیر از وسط یاخته، پس از تقسیم سیتوپلاسم تشکیل گردد.', 1, 4, 17, 32, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 21:01:56', 4, 'done'),
(757, 'کدام مورد، مشخصه مشترک همۀ بخش&zwnj;های لوله گوارش انسان است که مواد جذب نشده در فاصله بین عبور از بنداره انتهای روده باریک تا بنداره خارجی مخرج، از آن&zwnj;ها عبور می&zwnj;کنند؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:17:52', 5, 'done'),
(758, 'در پوست تنه یک درخت پنج ساله، یاخته هایی دیده می شوند که مرکز اصلی تنظیم ژنتیک خود را از دست داده اند. کدام مورد فقط در خصوص برخی از این یاخته ها صادق است؟', 1, 4, 17, 38, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:36:11', 5, 'done'),
(759, 'مطابق مطالب کتاب درسی دربارۀ اندامک&zwnj;های درون سیتوپلاسم یک یاخته جانوری، کدام دو ویژگی مربوط به یکی از این اندامک&zwnj;ها هستند؟', 1, 4, 12, 6, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:13:24', 5, 'done'),
(760, 'با توجه به مطالب کتاب درسی درباره مراحل جذب و گوارش مواد در دستگاه گوارش انسان، کدام عبارت درست است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:12:23', 5, 'done'),
(761, 'کدام مورد، درباره حرکات لوله گوارش درست است؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:17:38', 5, 'done'),
(762, 'کدام عبارت، درباره بنداره (اسفنکتر) انتهای مری نادرست است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:13:16', 5, 'done'),
(763, 'مطابق با اطلاعات کتاب درسی&zwnj;، کدام مورد، درباره لیپیدهایی که بیشترین فراوانی را در بین لیپیدهای رژیم غذایی دارند، درست است؟', 1, 4, 12, 5, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:12:49', 5, 'done'),
(764, 'با توجه به مطالب کتاب درسی درباره روش&zwnj;های عبور مواد از غشای یاخته، کدام مورد درست است؟', 1, 4, 12, 7, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:17:21', 5, 'done'),
(765, 'دو لایه دارای شبکه یاخته&zwnj;های عصبی در دیواره ابتدای مری، با کدام مشخصه مشترک از یکی از لایه&zwnj;های فاقد شبکه یاخته&zwnj;های عصبی متمایز می&zwnj;شوند؟', 1, 4, 13, 2, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:17:02', 5, 'done'),
(766, 'کدام ویژگی، نمی&zwnj;تواند یک نوع بافت ماهیچه&zwnj;ای بدن انسان را از هر دو نوع بافت ماهیچه&zwnj;ای دیگر متمایز کند؟', 1, 4, 12, 8, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:12:58', 5, 'done'),
(767, 'چند مورد، ویژگی متمایز کننده بخش انتهایی روده باریک از بخش ابتدایی آن در انسان است؟ الف: ساختاری پر پیچ و خم دارد. ب: در نیمه راست بدن قرار دارد. ج: نوعی اتصال با روده بزرگ دارد. د: سیاهرگی مشترک با کولون بالارو تشکیل می،دهد.', 1, 4, 13, 2, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:16:44', 5, 'done'),
(768, 'کدام مورد، مشخصة مشترک یاخته هایی در غده معده است که به عنوان بزرگترین یاخته های این غده محسوب می شوند؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:35:46', 5, 'done'),
(769, 'در یک فرد بالغ، در کدام، مورد یاخته های دستگاه عصبی خودمختار، نقشی ندارند؟', 1, 4, 13, 11, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:16:28', 5, 'done'),
(770, 'با توجه به مراحل حرکت و گوارش تودة غذا از زمان شروع بلع تا زمان ورود به دوازدهه، در کدام گزینه، ترتیب وقایع درست است؟', 1, 4, 13, 9, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:16:12', 5, 'done'),
(771, 'مواد گوناگونی که از یاخته های پوششی پرز روده عبور میکنند، در نهایت وارد مویرگهای پرز میشوند. کدام مورد، در خصوص همۀ این مویرگها درست است؟', 1, 4, 13, 10, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:16:01', 5, 'done'),
(772, 'با توجه به شکل مقابل که ساختار بافتی بخشی از بدن انسان را نشان می دهد، کدام مورد درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-29 21:35:25', 4, 'done');
