(773, 'کدام مورد مشخصة شاخه ای از سرخرگ ششی انسان است که طول کمتری دارد؟', 1, 4, 15, 19, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:35:14', 5, 'done'),
(774, 'با در نظر گرفتن همۀ لوب های سازندۀ شش های انسان، کدام مشخصه، بزرگترین لوب را از کوچکترین لوب متمایز می سازد؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:35:29', 5, 'done'),
(775, 'با توجه به شکل زیر که مربوط به نمایی از برش طولی قلب انسان میباشد، کدام مورد درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-29 21:36:24', 4, 'done'),
(776, 'مطابق مطالب کتاب درسی، در مغز انسان، نوعی مرکز عصبی وجود دارد که میتواند باعث توقف ارسال پیام انقباض از بصل النخاع به دیافراگم شود. کدام مورد، دربارۀ این مرکز عصبی، به طور حتم، درست است؟', NULL, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-03-20 13:46:21', 3, 'done'),
(777, 'با توجه به مطالب کتاب درسی دربارة دریچه های قلب انسان کدام مورد درست است؟', 1, 4, 15, 19, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:35:04', 5, 'done'),
(778, 'کدام ویژگی، دربارة تعداد بیشتری از یاخته های ضخیم ترین لایة دیواره قلب صادق است؟', 1, 4, 15, 19, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:34:55', 5, 'done'),
(779, 'با توجه به نوار قلب تهیه شده از یک فردِ سالم در حالت استراحت، کدام عبارت درست است؟', 1, 4, 15, 20, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:34:47', 5, 'done'),
(780, 'با در نظر گرفتن کل اجزای سازندة بخش هادی دستگاه تنفسی انسان، کدام مشخصه، فقط دربارة ابتدای این بخش صادق است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(781, 'کدام مورد، درباره پروتئینی که گویچة قرمز سرشار از آن میباشد، درست است؟', 1, 4, 14, 15, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:34:40', 5, 'done'),
(782, 'کدام عبارت دربارة فرایند نفس کشیدن درست است؟', 1, 4, 14, 14, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:15:39', 5, 'done'),
(783, 'چند مورد، مشخصۀ نزدیک ترین انشعاب سرخرگ تاجی (کرونری) به دریچة سینی سرخرگ ششی است؟ الف: به سمت سطح پشتی قلب می رود. ب: در خون رسانی به بطن چپ نقش دارد. ج: مسیری مستقیم را در کنار نوعی سیاهرگ طی می کند. د: منفذ مرتبط با آن در سرخرگ آئورت، عقب تر از منفذ مشابه در سمت مقابل است.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:15:29', 5, 'done'),
(784, 'دربارۀ فردی که مبتلا به نوع شدیدی از بیماری سینه پهلو شده است و تب بالایی دارد، کدام مورد درست می باشد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(785, 'چند مورد، در ارتباط با شکل زیر که نوار قلب فردی سالم را نشان می دهد، درست است؟ (فقط نقاط مشخص شده در شکل را در نظر بگیرید و با یکدیگر مقایسه کنید.) الف: فقط در نقطة &laquo;۱&raquo;، جریان الکتریکی در تارهای میان گرهی منتشر می شود. ب: فقط در نقطة &laquo;۳&raquo;، پایین ترین تارهای ماهیچه ای قلب منقبض می شوند. ج: فقط در نقطة &laquo;۲&raquo;، خون سیاهرگی وارد دهلیزهای قلب نمی شود. د: فقط در نقطة &laquo;۴&raquo;، صدایی واضح اما کوتاه از قلب شنیده می شود.', 1, 4, 15, 20, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 22:15:08', 5, 'done'),
(786, 'اگر مقداری پپسینِ استخراج شده از معدة انسان را در ظرفی حاوی سفیدة تخم مرغ و دارای pH خنثی قرار دهیم و در شرایط مختلف، ساختار و عملکرد آنزیم را بررسی کنیم، کدام مورد درست است؟', NULL, 4, 13, 9, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:34:13', 5, 'done'),
(787, 'اختلال در خون رسانی قسمتی از شبکة هادی قلب انسان می تواند منجر به توقف یا تأخیر در ارسال پیام الکتریکی در بخشی از قلب و تغییر فعالیت آن شود. در کدام مورد، محل وقوع عارضه و تأثیر آن با یکدیگر مطابقت دارند؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:33:17', 5, 'done'),
(788, 'کدام مورد، جزء مشخصه های متمایز کننده آخرین انشعاب مجاری تنفسی از نایژه اصلی محسوب نمیشود؟', 1, 4, 14, 14, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:33:28', 5, 'done'),
(789, 'در یک نمونه تهیه شده از شش گوسفند و مجاری تنفسی آن، مری نیز وجود دارد. اگر شش ها را طوری در دست بگیریم که نای رو به بالا باشد و مری دیده نشود، کدام مورد درست است؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:32:46', 5, 'done'),
(790, 'کدام ویژگی درباره بطن های قلب انسان صادق است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:32:34', 5, 'done'),
(791, 'کدام مورد یا موارد، دربارة همه صداهایی که از قلب یک فرد بالغ شنیده می شوند، به طور حتم درست است؟ الف: در اثر بسته شدن همزمان دو دریچه قلبی ایجاد می شوند. ب: پس از پایان مرحلة انقباض قسمتی از قلب شنیده می شوند. ج: با قرار دادن گوشی پزشکی روی قفسه سینه شنیده می شوند. د) با افزایش تعداد ضربان قلب، فاصلة بین صداها نیز افزایش می یابد.', 1, 4, 15, 19, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:31:59', 5, 'done'),
(792, 'با توجه به شکل زیر که بخشی از اسپیروگرام یک فرد سالم و بالغ را نشان می دهد، کدام عبارت درست است؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:31:35', 5, 'done'),
(793, 'با توجه به مطالب کتاب درسی درباره تشریح قلب گوسفند، کدام عبارت صحیح است؟', 1, 4, 15, 19, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:31:26', 5, 'done'),
(794, 'بخش مبادله ای دستگاه تنفسی انسان با حضور اجزایی کوچک مشخص می شود. کدام مورد، مشخصۀ همۀ این اجزا را به درستی بیان میکند؟', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:32:27', 5, 'done'),
(795, 'با توجه به نقش دو نوع ماهیچه بین دنده ای در فرایندهای تهویه ششی کدام مورد به طور حتم درست است؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:31:19', 5, 'done'),
(796, 'کدام مورد، ویژگی حجمی از هواست که فقط در محاسبه ظرفیت تام شش ها کاربرد دارد؟', 1, 4, 14, 16, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:31:12', 5, 'done'),
(797, 'چند مورد دربارة استخوان ها و ماهیچه های مرتبط با دستگاه تنفسی انسان درست است؟ (فرد ایستاده و در حال بازدم است و از نمای روبه رو به بدن وی نگاه می کنیم.) الف: همه دنده های هم سطح با شُش همانند بعضی از دنده های پایین تر از شُش، به جناغ متصل می شوند. ب: پایین ترین قسمت جناغ برخلاف بالاترین قسمت آن، سطح مفصلی برای دنده ها ندارد. ج: نیمة راست پردة ماهیچه ای نسبت به نیمۀ چپ آن، در سطح بالاتری قرار گرفته است. د: بالاترین قسمت دیافراگم هم سطح با پایین ترین قسمت استخوان جناغ است.', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:30:46', 5, 'done'),
(798, 'مطابق مطالب کتاب درسی درباره آزمایش مربوط به مقایسه هوای دمی و بازدمی، اگر انتهای کوتاه لوله مرکزی در ظرف &laquo;۱&raquo; و انتهای بلند آن در ظرف &laquo;۲&raquo; قرار داشته باشد و فردی سالم از طریق لوله مرکزی نفس بکشد، کدام مورد به طور حتم درست است؟', 1, 4, 14, 14, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:30:23', 5, 'done'),
(799, 'با توجه به مطالب کتاب درسی دربارة حجم ها و ظرفیت های تنفسی و با در نظر گرفتن دم و بازدم های متوالی یک انسان بالغ، وقوع چند مورد در فرد سالم، امکان پذیر نیست؟ الف: حجم هوایی که وارد دستگاه تنفسی می شود، از حجم جاری بیشتر و از حجم ذخیرة دمی کمتر باشد. ب: در یک دم و بازدم متوالی، ماهیچه های گردنی منقبض نشوند اما ماهیچه های شکمی منقبض شوند. ج: بدون انجام حداکثر بازدم، کل هوای درون شُش ها تخلیه شود و شُش ها کاملاً جمع شوند. د: پس از انجام حداکثر دم، دم بعدی قبل از خروج حجم ذخیرة بازدمی آغاز شود.', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:30:36', 5, 'done'),
(800, 'با توجه به مطالب کتاب درسی دربارة حجم ها و ظرفیت های تنفسی و با در نظر گرفتن دم و بازدم های متوالی یک انسان بالغ، وقوع چند مورد در فرد سالم، امکان پذیر نیست؟ الف: حجم هوایی که وارد دستگاه تنفسی می شود، از حجم جاری بیشتر و از حجم ذخیرة دمی کمتر باشد. ب: در یک دم و بازدم متوالی، ماهیچه های گردنی منقبض نشوند اما ماهیچه های شکمی منقبض شوند. ج: بدون انجام حداکثر بازدم، کل هوای درون شُش ها تخلیه شود و شُش ها کاملاً جمع شوند. د: پس از انجام حداکثر دم، دم بعدی قبل از خروج حجم ذخیرة بازدمی آغاز شود.', 1, 4, 14, 16, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 10:31:06', 5, 'done'),
(801, 'از آمیزش بین دو گل مغربی (مطرح شده در کتاب درسی) که به دو گونه مختلف تعلق دارند ساقه رویانی با ژنوتیپ BBDحاصل شده است. بر این اساس، کدام ژنوتیپ های زیر، به ترتیب برای &laquo;یاخته های محل قرارگیری و پذیرش دانه گرده رسیده&raquo; و &laquo;آندوسپرم تشکیل شده در دانه با فرض گیاه مادۀ بیان شده&raquo;، غیرممکن است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(802, 'کدام گزینه درباره فردی که گروه خونی A- دارد، قطعاً درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(803, 'ویژگی مشترک بیماری های ژنتیکی &laquo;شایع ترین نوع هموفیلی&raquo; و &laquo;فنیل کتونوری&raquo; مطرح شده در کتاب درسی، در کدام گزینه آمده است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(804, 'در یک خانواده، از والدین سالم، پسری فاقد کربوهیدرات های \\(A\\) و \\(B\\) در غشای گویچه های قرمز بالغ خود و فاقد توانایی ساختن عامل انعقادی شماره \\(VIII\\)(هشت) و دختری دارای هر دو کربوهیدرات \\(A\\) و \\(B\\) در غشای گویچه های قرمز بالغ و فاقد آنزیم تجزیه کننده آمینواسید فنیل آلانین متولد شده اند. تولد کدام فرزند در این خانواده غیر محتمل است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(805, 'در گیاه لوبیا، ژن نمود (ژنوتیپ) برگ های رویانی به صورت AB است. کدام مورد به ترتیب از راست به چپ، در ارتباط با ژن نمود (ژنوتیپ) آندوسپرم این دانه، پوسته دانه و دانه گرده گرده افشانی شده ای که در تشکیل این دانه شرکت داشته، محتمل است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(806, 'در ارتباط با صفات گروه های خونی در انسان (مطرح شده در کتاب درسی)، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در بدن هر انسانی که ......... دارد، ............... یافت می گردد.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(807, 'مطابق اطلاعات کتاب درسی در خصوص رنگ گلبرگ گل های میمونی، به دنبال آمیزش هر دو نوع از این گیاهان، فقط گیاه(هایی) پدید می آید که رنگ گلبرگ های متفاوتی با گلبرگ های گل گیاه خرزهره دارد. کدام مورد به ترتیب از راست به چپ، در ارتباط با ژن نمود(ژنوتیپ) پوسته دانه حاصل از آمیزش این دو نوع گیاه و یاخته سازنده لوله گردۀ مربوط به همین گیاه، غیر محتمل است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(808, 'برای بروز علائم مربوط به برخی بیماری های ژنتیکی مرتبط با ژن های درون هسته (مستقل از جنس و وابسته به \\(X\\)) در مردان، وجود یک دگره (الل) بیماری زا در ژنوتیپ آنها همواره کافی است. کدام مورد، ویژگی مشترک این بیماری ها را نشان می دهد؟ (علائم بیماری در شرایط محیطی معمول بروز می یابد.)', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(809, 'مطابق با اطلاعات کتاب درسی، کدام گزینه زیر درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(810, 'با توجه به این که صفت رنک در نوعی ذرت، صفتی با سه جایگاه ژنی است که هر کدام دو دگره دارد، برای نشان دادن ژن ها در این سه جایگاه از حروف بزرگ و کوچک A،B و C استفاده می کنیم. نظر به این که صفات چند جایگاهی، رخ نمودهای پیوسته ای دارند و نمودار توزیع فراوانی آنها شبیه به زنگوله است، کدام مورد عبارت زیر را به طور مناسب کامل می کند؟ &laquo;ذرت هایی که فقط دارای یک جایگاه ژنی خالص بارز و یک جایگاه ژنی نهفته هستند در نمودار فراوانی، به اندازۀ بیش از یک ستون با همه ذرت هایی که می توانند ............ داشته باشند، فاصله دارند.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(811, 'با توجه به صفت رنگ ذرت مطرح شده در کتاب درسی، کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;در صورتی که آندوسپرم یک دانه ذرت ................ نوع دگره (الل) در ژن نمود (ژنوتیپ) خود داشته باشد، ................. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(812, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ به طور معمول همۀ صفات ژنتیکی که............. قابل انتقال باشند، قطعاً در فامتن یا دنایی دارای جایگاه ژنی هستند که', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(813, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در صورتی که در یک خانواده، امکان مشاهده ............... در بین فرزندان وجود داشته باشد، به طور حتم ............... .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(814, 'فرض کنید صفت طول شاخک در جمعیتی از زنبورهای عسل صفتی مستقل از جنس، تک جایگاهی و دارای سه شکل بلند، متوسط و کوتاه باشد. اگر این صفت دارای دو دگره (الل) مربوط به کوتاهی و بلندی شاخک باشد که بین آنها رابطه بارزیت ناقص برقرار است، در این صورت کدام موارد زیر، در این جمعیت غیر ممکن است؟ الف: زنبور نر با شاخک کوتاه، والد زنبور کارگری با شاخک متوسط باشد. ب: زنبور نر با شاخک متوسط، از زنبور ماده ای با شاخک بلند متولد شود. ج: زنبور کارگر با شاخک بلند، از زنبور ملکه ای با شاخک کوتاه متولد شود. د: زنبور ماده ای با شاخک متوسط، فاقد توانایی تولید زنبوری با شاخک متوسط باشد.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(815, 'با توجه به دو صفت فنیل کتونوری و هموفیلی در انسان (در شرایط معمول)، کدام مورد برای همه حالات محتمل است؟ (فنیل کتونوری نوعی بیماری مستقل از جنس نهفته است).', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(816, 'با فرض این که نوعی بیماری ژنتیکی وجود دارد که افراد ناخالص، ناقل بیماری محسوب نمی شوند و همۀ دختران متولد شده از هر پدر مبتلا به این بیماری، بیمار خواهند بود، اما هر پسر متولد شده از مادری بیمار، لزوماً بیمار نخواهد بود. کدام مورد زیر در خصوص این بیماری صادق است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(817, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo; با در نظر گرفتن همۀ بیماریهای مطرح شده در بخش ژنتیک (فصل سوم) کتاب درسی، فقط در یک نوع از این بیماری ها امکان تولد ..................... وجود دارد.&raquo; الف: دختری به ظاهر سالم و ناقل بیماری، از پدر و مادری بیمار ب: پسری با ژن نمود (ژنوتیپ) مشابه پدر، از پدری بیمار و مادری سالم ج: دختری خالص، از پدری سالم و مادری مبتلا به بیماری د: پسری با رخ نمود(فنوتیپ) مشابه با مادر، از پدری سالم و مادری بیمار', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(818, 'با توجه به قوانین وراثت در جمعیت انسان ها، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;صفت یا بیماری که .......................، به طور حتم ............................. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(819, 'با نوجه به انواع روش های ممکن برای وراثت بیماری های ژنتیکی در انسان، کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;با فرض این که ............... از نظر ابتلا به نوعی بیماری ................. باشد؛ به طور حتم ................. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(820, 'با توجه به مطالب کتب درسی، کدام مورد، عبارت زیر را به طور مناسب کامل می کند؟ &laquo;با توجه به نتیجه مطالعات هر دانشمندی یا دانشمندانی که ............. را مشخص کرد، می توان بیان داشت که .............. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(821, 'از ازدواج مردی مبتلا به بیماری فنیل کتونوری و دارای گروه خونی AB با زنی سالم و دارای گروه خونیO ، دختری مبتلا به فنیل کتونوری و پسری هموفیل متولد گردید. در این خانواده براساس مربع پانت، پیش بینی می کنید که شانس تولد کدام یک از فرزندان زیر نسبت به فرزند مبتلا به فنیل کتونوری بیشتر باشد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(822, 'با توجه به نمودار توزیع فراوانی رنگ ذرت (صفت چند جایگاهی) در کتاب درسی، چند مورد، برای تکمیل عبارت زیر نادرست است؟ &laquo;به طور معمول، ............ ژن نمود (ژنوتیپ)ها در بخش .............. ژن نمود (ژنوتیپ)ها در بخش ................. .&raquo; الف: همه - ۲ همانند فقط برخی از ـ ۱، در صورت خود لقاحی می توانند دانه های کاملاً قرمز تولید کنند. ب: فقط برخی از - ۱ همانند همه &ndash; ۲، در هر جایگاه ژنی، دگره (الل) بارز دارند. ج: همه ـ ۱ همانند فقط برخی از &ndash; ۲، تنها در یک جایگاه ژنی ناخالص هستند. د: فقط برخی از - ۲ همانند همه - ۱ تنها در دو جایگاه ژنی خالص هستند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(823, 'مطابق اطلاعات کتاب درسی در گروهی از جانوران، یک فرد بالغ می تواند طی تولید مثل جنسی، به تنهایی اقدام به زادآوری کند. با در نظر گرفتن این جانوران، در صورتی که این فرد در خصوص رنگ پوست خود ژن نمود (ژنوتیپ) AaBb داشته باشد، تولد کدام مورد غیرممکن است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(824, 'کدام عبارت، درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(825, 'با فرض این که در نوعی گیاه نهان دانه دیپلوئید، ژنوتیپ یاخته های درون دانه ABB، باشد، در کدام گزینه جهت تشکیل این درون دانه، هر دو ژنوتیپ به ترتیب برای ژنوتیپ بخش پذیرندۀ دانۀ گرده و گردۀ نارس غیر محتمل هستند؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(826, 'مشخص شده است که در انسان، صفت رویش مو روی لاله گوش را نوعی ژن مستقل از جنس کنترل می کند که فنوتیپ موی رویش یافته، در مردان با ژنوتیپ های Rr و RR و در زنان، با ژنوتیپ RR ظاهر می شود. اگر مردی فاقد مو روی لاله گوش با زنی با رخ نمود (فنوتیپ) مشابه ازدواج کند و صاحب پسری واجد مو روی لاله گوش شود، کدام گزینه درباره این خانواده درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(827, 'در یک خانواده، از پدر و مادری سالم، پسری هموفیل متولد شده است. در صورتی که فرزند بعدی این خانواده، پسری مبتلا به فاویسم باشد و تولید لخته خون را بدون مشکل انجام دهد. با وقوع کراسینگ اور در فام تن های جنسی طی گامت زایی، تولد چند مورد در این خانواده محتمل است؟ (فرض کنید بیماری فاویسم نوعی بیماری نهفته است که به طور طبیعی، مردان نمی توانند ناقل آن باشد.) الف: دختری سالم و ناقل یکی از دو بیماری ب: پسری مبتلا به هر دو بیماری و دارای عامل انعقادی \\(VIII\\) ج: پسری سالم از نظر هر دو بیماری د: دختری سالم و ناقل هر دو بیماری', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(828, 'با توجه به این که صفت رنگ ذرت، صفتی با سه جایگاه ژنی است که هر کدام دو دگره دارد، برای نشان دادن ژن ها در این سه جایگاه از حروف بزرگ و کوچک A ،B و C استفاده می کنیم. با توجه به ذرت های دارای رنگ هایی به جز کاملاً سفید و کاملاً قرمز، در خصوص ذرت هایی که در ژن نمود خود، تعداد دگره های نهفته کم تری نسبت به دگره های بارز دارند، ........... قابل انتظار ........... .', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(829, 'از ازدواج مردی مبتلا به هموفیلی و سالم از نظر بیماری فنیل کتونوری و واجد فقط یک نوع کربوهیدرات گروه خونی در سطح گویچه های قرمز خود و فاقد پروتئین D با زنی که برای هر دو بیماری ناقل بوده و واجد گروه خونی B مثبت است، تولد کدام فرزند محتمل است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(830, 'در گیاه پیاز، ژن نمود یاخته های زنده لپه، ABاست. کدام مورد به ترتیب از راست به چپ، در ارتباط با ژن نمود آندوسپرم این دانه، یاخته های پوسته دانه، یاخته سازنده گرده نارس و یاخته خورشی که در تشکیل این دانه شرکت داشته، محتمل است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(831, 'چند مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;در نوعی گیاه دولپه ای با گل های کامل که به دنبال خود لقاحی، ژن نمود (ژنوتیپ) AAaBbb را در یاخته های آندوسپرمی خود نشان می دهد، ................ متفاوت در ارتباط با صفت رنگ گلبرگ، داشته باشند. الف: تخم زاهای موجود در هر تخمک، نمی توانند ژن نمود (ژنوتیپ) ب: یاخته های مولد گرده های نارس در پرچم ها می توانند ژن نمود (ژنوتیپ) ج: انواع هسته های موجود در لوله گرده، نمی توانند رخ نمود (فنوتیپ) د: یاخته های تک لاد (هاپلوئید) تولید شده در یک تخمک، می توانند رخ نمود (فنوتیپ)', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(832, 'در خصوص صفت رنگ نوعی ذرت (مطرح شده در کتاب درسی)، به دنبال لقاح بین ذرت هایی که در دو آستانه نمودار زنگوله ای قرار می گیرند، نوعی ذرت حاصل می شود. کدام مورد را نمی توان مشخصۀ مشترک سایر ذرت هایی دانست که رنگی مشابه با ذرت حاصل از این لقاح دارند؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(833, 'کدام مورد یا موارد را می توان در ارتباط با پسربچه ای سالم از نظر بیماری هموفیلی و واجد گروه خونی A- ، با قاطعیت بیان داشت؟ الف: حداقل در یکی از فام تن (کروموزوم)های جنسی موجود در بدن مادر آن، دگره ای (اللی) بارز قرار گرفته است. ب: بر روی کروموزوم های شماره ۹ آن، دگره های مربوط به تولید آنزیم متصل کننده کربوهیدرات گروه خونی قرار دارد. ج: تبدیل پروتئین فیبرینوژن به رشته های نامحلول فیبرین در خوناب مادر آن، بدون هرگونه اختلالی صورت می گیرد. د: بر روی بزرگ ترین کروموزوم های موجود در کاریوتیپ او، در مجموع، دو نسخه مشابه از الل های گروه خونی Rh دیده می شود.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(834, 'صفت رنگ در نوعی ذرت، صفتی با سه جایگاه ژنی است که هر کدام دو دگره (الل) دارند. با توجه به نمودار توزیع فراوانی رخ نمود (فنوتیپ)ها در کتاب درسی، کدام دوژن نمود (ژنوتیپ) با فاصله یکسانی از زاده های حاصل از لقاح دو ذرت با ژن نمود (ژنوتیپ)های AABBcc و aabbCC قرار دارند؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(835, 'با در نظر گرفتن دو بیماری &laquo;هموفیلی&raquo; و &laquo;کم خونی داسی شکل&raquo; کدام گزینه، عبارت زیر را به طور نامناسب کامل می کند؟ &laquo;به طور معمول در صورت ازدواج ........................... تولد پسری مبتلا به هر دو بیماری و فاقد کربوهیدرات های A و B در سطح گویچه های قرمز بالغ خود، غیر ممکن است.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(836, 'در خصوص بیماری های مطرح شده در بخش ژنتیک (فصل سوم) کتاب درسی دوازدهم، کدام گزینه، برای تکمیل متن زیر نامناسب است؟ &laquo;در خانواده ای که والدین و دو فرزند آنها از لحاظ گروه خونی ABO ژنوتیپ های متفاوتی دارند و ژنوتیپ پدر نیز در خصوص این صفت ناخالص است، دخترانی متولد شده اند که از نظر بیماری های مذکور، سالم و مشابه پدر خود هستند. در چنین شرایطی، اگر مادر خانواده .................. .&raquo;', 3, 4, 30, 162, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:55:50', 4, 'done'),
(837, 'همه موارد برای تکمیل عبارت زیر مناسب است؛ به جز: &laquo;در مطالعه دو بیماری هموفیلی و کم خونی داسی شکل، با فرض این که فقط ..................... در شرایط محیطی معمولی از نظر هر دو صفت بیمار و والد دیگر کاملاً سالم باشد، در شرایط معمول به طور حتم تولد فرزند ..................... از نظر هر دو صفت، برای همه حالات .................است.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(838, 'در جمعیت زنبورهای عسل، صفت رنگ بال نوعی صفت تک جایگاهی با دو دگره با رابطه هم توانی است که در ایجاد خطوط خاکستری و خال های زرد نقش دارد و صفت طول شاخک نوعی صفت تک جایگاهی و دارای دگره هایی با رابطه بارزیت ناقص است. تولد چند مورد از زاده های زیر در آمیزش مطرح شده محتمل است؟ (زنبور ملکه دارای بال هایی با خطوط خاکستری و خال های زرد و شاخک کوتاه و زنبور نر دارای شاخک بلند و بال هایی با خال های زرد است.) زنبوری نازا با شاخک کوتاه و بالی با خال های زرد زنبوری فاقد توانایی انجام میوز ۱ با شاخک هایی با طول متوسط زنبوری هاپلوئید و دارای شاخک هایی با طول بلند و خطوط خاکستری بر روی بال زنبوری زیستا و زایا و دارای شاخک هایی با طول متوسط و بال هایی با خطوط خاکستری و خال دار', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(839, 'در گیاه لوبیا، ژن نمود (ژنوتیپ) لپه های دانه، به صورت AB است. کدام مورد به ترتیب از راست به چپ، در ارتباط با ژن نمود آندوسپرم این دانه و یاخته سازنده گرده نارس و پوسته دانه، غیر محتمل است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(840, 'در یک خانواده، از پدر و مادری سالم، پسری هموفیل و مقاوم در برابر ابتلا به مالاریا متولد شده است. اگر فرزند دوم خانواده، به دلیل داشتن گویچه های قرمز غیر طبیعی، در کودکی بمیرد و پدر و مادر از نظر هر الل مربوط به گروه خونی ABO با یکدیگر متفاوت باشند، در صورت عدم وقوع کراسینگ اور در فام تن های والدین، تولد چند مورد در این خانواده محتمل است؟ (پدر و مادر از نظر ژنوتیپ های گروه خونی، خالص هستند.)', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(841, 'با توجه به این که صفت رنگ در نوعی ذرت، صفتی با سه جایگاه ژنی است که هر کدام دو دگره (الل) دارد، برای نشان دادن ژن ها در این سه جایگاه از حروف بزرگ و کوچک B، A و C استفاده می کنیم. نظر به این که صفات چندجایگاهی، رخ نمود (فنوتیپ)های پیوسته ای دارند و نمودار توزیع فراوانی این رخ نمود (فنوتیپ)ها شبیه به زنگوله است، کدام مورد عبارت زیر را به طور مناسب کامل می کند؟ &laquo;می توان گفت ................ ذرت هایی که از آمیزش دو ذرت در ستون های .................... ایجاد می شوند .................... .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(842, 'مطابق با مطلب کتاب درسی، انواعی از جانوران خشکی زی می توانند رفتاری را بروز دهند که در آن بقا و موفقیت تولیدمثلی جانور دیگری را با هزینه کاسته شدن از احتمال بقا و تولیدمثل خود، افزایش می دهند. کدام مورد ویژگی مشترک جمعیت این جانوران است؟', 3, 4, 35, 169, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:54:41', 4, 'done'),
(843, 'در خصوص اجتماع مورچه های برگ بر، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ مورچه های کارگری که کار دفاع را انجام می دهند، .................. مورچه های کارگری که برگ ها را برش می دهند، ................. .&raquo;', 3, 4, 35, 169, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:54:20', 4, 'done'),
(844, 'جانوران در اثر تجربه هایی که در محیط کسب می کنند، می توانند رفتارهای خود را به طور نسبتاً پایداری تغییر دهند. هر نوعی از این رفتارها که ................. .', 3, 4, 35, 167, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:54:08', 4, 'done'),
(845, 'پژوهشگران ارتباط یک ژن را با رفتار مراقبت از زاده ها در موش ماده بررسی کرده اند. براساس این رفتار و ژن های مرتبط با آن،کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول، در ................ موش های مادر .....................&raquo;', 3, 4, 35, 167, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:53:48', 4, 'done'),
(846, 'کدام موارد زیر معرف نوعی رفتار هستند که می تواند با بروز نوعی پاسخ غریزی و همچنین یک بازتاب طبیعی همراه باشد؟ الف: رفتار شقایق دریایی که به حرکت مداوم آب پاسخ نمی دهد و بازوهای خود را منقبض نمی کند. ب: شامپانزه از تکه های چوب یا سنگ برای شکستن پوسته سخت میوه ها استفاده می کند. ج: رفتار سگ در آزمایش پاولوف که پس از شرطی شدن، در پاسخ به شنیدن صدای زنگ بروز می یابد. د: رفتار موش گرسنه در جعبه اسکینر که با فشردن اهرم، غذا دریافت کرده است.', 3, 4, 35, 167, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:53:18', 4, 'done'),
(847, 'کدام عبارت درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(848, 'با توجه به رفتار زادآوری در جانداران مختلف مطرح شده در فصل ۸ زیست شناسی3 ، کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در نوعی جاندار که .................... انتخاب جفت برعهده جانداری است که .................... .&raquo;', 3, 4, 35, 168, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:53:03', 4, 'done'),
(849, 'کدام گزینه، در خصوص رفتار غذایابی در جانوران مختلف درست است؟', 3, 4, 35, 168, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:52:08', 4, 'done'),
(850, 'مطابق کتاب درسی، کلاغ ها برای دستیابی به تکه گوشت آویزان به انتهای نخ رفتاری را بروز می دهند. کدام عبارت درباره رفتار این پرنده درست است؟', 3, 4, 35, 167, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:51:42', 4, 'done'),
(851, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;با فرض این که .............. از بروز رفتار دگرخواهی خودداری کنند، .................. .&raquo;', 3, 4, 35, 169, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:52:28', 4, 'done'),
(852, 'کدام عبارت درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(853, 'مطابق اطلاعات فصل ۸ زیست شناسی دوازدهم، خفاش های خون آشام رفتاری را بروز می دهند که در افزایش بقای جمعیت آن ها و خویشاوندان آنها نقش دارد. با توجه به این جمله می توان گفت این رفتار ................... .', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(854, 'در خصوص انواع رفتارهای مطرح شده در کتاب درسی، کدام مورد درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(855, 'با توجه به مطلب کتاب درسی در فصل هشتم زیست شناسی دوازدهم، کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;پس از بازگشت زنبور عسل یابنده منبع غذایی جدید به کندو سایر زنبورهای کارگر، ................ .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(856, 'با توجه به اطلاعات کتاب درسی، در خصوص مزیت زندگی گروهی در کبوترها کدام مورد صحیح است؟', 3, 4, 35, 169, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:51:11', 4, 'done'),
(857, 'برای وقوع گروهی از رفتارهای جانوری، برهم کنش ژن های جانور و تجربه های ناشی از اثرهای محیطی ضروری نیست. کدام گزینه درباره این رفتارها درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(858, 'در ارتباط با ساده ترین نوع یادگیری که در نوعی جانور فاقد مغز و دستگاه عصبی مرکزی هم می تواند دیده شود، کدام مورد صادق است؟', 3, 4, 35, 167, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-04-05 22:35:46', 5, 'done'),
(859, 'مطابق با جانوران مطرح شده در فصل ۸ کتاب درسی دوازدهم، در گروهی از جانوران مهره دار با توجه به نوع نظام جفت گیری، یکی از والدین پرورش و نگه داری زاده ها را انجام می دهد. کدام مورد ویژگی مشترک این گروه از جانوران است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(860, 'در خصوص رفتارهای جانوری، کدام یک از موارد زیر درست است؟ الف: تخم گذاری لاک پشت های دریایی ماده در ساحل، نوعی شارش ژن است. ب: نوعی منبع غذایی مورچه های برگ بر، می تواند گلوکز را به شکل گلیکوژن ذخیره کند. ج: فهم و درک انتخاب طبیعی در پاسخ به پرسش های نوع اول رفتارشناسان مؤثر است. د: هر رفتار غذایابی برگزیده شده توسط انتخاب طبیعی، مواد مورد نیاز جانور را تأمین می کند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(861, 'مطابق با اطلاعات کتاب درسی، گروهی از جانوران می توانند بدون لقاح، از طریق دو برابر کردن تعداد کروماتیدهای موجود در هسته یاخته جنسی خود، تولیدمثل کنند. ویژگی مشترک این جانوران کدام است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(862, 'میوه های نارس معمولاً مزه های ناخوشایندی دارند؛ در نتیجه دانه های نارس درون آن ها، تا زمان رسیدن میوه از خورده شدن به وسیله جانوران حفظ می شوند. امتناع از خوردن این میوه ها، در نتیجه بروز نوعی رفتار در جانوران است. چند مورد درباره این رفتار صحیح است؟ الف: دارای ژن یا ژن هایی است که برای بیان شدن نیازمند وجود برخی پروتئین ها هستند. ب: می توانند منجر به هدایت جانور به سمت رفتار غذایابی بهینه جهت کسب انرژی شوند. ج: به طور حتم تحت تأثیر عاملی قرار می گیرد که فراوانی نسبی برخی فنوتیپ ها را کاهش می دهد. د: جانور در پی انجام آزمون و خطاهای متعدد، برای رفتار جدید خود به طور آگاهانه برنامه ریزی می کند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(863, 'مطابق اطلاعات کتاب درسی، گروهی از جانداران فتوسنتز کننده در مناطقی زندگی می کنند که از نظر نیتروژن فقیر هستند. مشخصه مشترک این جانداران کدام است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(864, 'از آمیزش بین دو گل مغربی (مطرح شده در کتاب درسی) که به دو گونه مختلف تعلق دارند ساقه رویانی با ژنوتیپ BBD حاصل شده است. بر این اساس، کدام ژنوتیپ های زیر، به ترتیب برای &laquo;یاخته های محل قرارگیری و پذیرش دانه گرده رسیده&raquo; و &laquo;آندوسپرم تشکیل شده در دانه با فرض گیاه مادۀ بیان شده&raquo;، غیرممکن است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(865, 'اطلاعات اولیه در مورد مادۀ وراثتی از فعالیت ها و آزمایش های باکتری شناسی انگلیسی به نام گریفیت به دست آمد. با توجه به آزمایش های گریفیت کدام مورد زیر درست است؟', 3, 4, 28, 145, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:50:07', 4, 'done'),
(866, 'کدام عبارت نادرست است؟', 3, 4, 28, 152, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:50:41', 4, 'done'),
(867, 'برای تکمیل عبارت زیر کدام مورد مناسب است؟ &laquo; در یاخته های تشکیل دهنده مورولا، هر مولکول حاوی اطلاعات وراثتی که ............... .&raquo;', 3, 4, 28, 146, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:49:43', 4, 'done'),
(868, 'با توجه به مطالب کتاب درسی در مورد نوکلئوتیدهای به کار رفته در ساختار دنا و رنا، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در ساختار هر نوکلئوتیدی که ............... مشاهده می گردد، .............. نیز یافت می شود.&raquo;', 3, 4, 28, 146, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:49:56', 4, 'done'),
(869, 'کدام موارد برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول، در هر جانداری که دنا(DNA)ی اصلی آن ............... به طور حتم ............... .&raquo; الف: به ناحیه خاصی از غشای یاخته ای متصل است ـ در هر دوراهی همانندسازی دو آنزیم دنابسپاراز به ساخت رشته های جدید می پردازند. ب: واجد گروه فسفات در یک انتها و گروه OH در انتهای دیگر هر رشته خود است - جایگاه آغاز و پایان همانندسازی این مولکول دنا درمقابل یکدیگر قرار دارد. ج: به شکل فام تن (کروموزوم) سازمان یافته است ـ تعداد جایگاه آغاز همانندسازی می تواند بسته به مراحل رشد و نمو تنظیم شود. د: به صورت دوجهتی همانندسازی می شود - آغاز همانندسازی در چندین جایگاه در هر فام تن (کروموزوم) انجام می پذیرد.', 3, 4, 28, 149, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:48:52', 4, 'done'),
(870, 'به طور معمول در یاخته های انسانی و با در نظر گرفتن انواع آمینواسیدهایی که می توانند در ساختمان پروتئین ها شرکت کنند. کدام مورد نادرست است؟ &laquo;هر گروهی در ساختار عمومی آمینواسیدها که .............. .&raquo;', 3, 4, 28, 151, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:50:20', 4, 'done'),
(871, 'با توجه به طرح های پیشنهادی همانندسازی، کدام مورد زیر ویژگی مشترک روش همانندسازی حفاظتی و همانندسازی نیمه حفاظتی است؟', 3, 4, 28, 150, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:48:02', 4, 'done'),
(872, 'با توجه به مطلب کتاب درسی، در فاصله ای که برای نخستین بار پیوند اشتراکی در سطوح ساختاری هموگلوبین ایجاد می شود تا تشکیل مجدد پیوند اشتراکی در سطح ساختاری دیگر، کدام اتفاق زیر رخ می دهد؟', 3, 4, 28, 151, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:47:52', 4, 'done'),
(873, 'با توجه به فرایند ساخته شدن مولکول دنای جدید از روی دنای قدیمی درون هسته یک یاخته پوششی روده باریک انسان، چند مورد در خصوص آنزیم های دخیل در این فرایند، صادق است؟ هر آنزیمی که باعث رفع اشتباهات در حین همانندسازی میشود میتواند بین نوکلئوتیدهای A دار و Tدار، پیوند ایجاد کند. هر آنزیمی که نوکلئوتیدها را براساس رابطه مکملی مقابل هم قرار میدهد در واحدهای تکرارشونده خود قندی پنج کربنی دارد. هر آنزیمی که در محل خاصی از دنا ساختار مانند به وجود میآورد در ابتدا پروتئین های متصل به دنا را جدا می کند. هر آنزیمی که حین همانندسازی از آنزیم مشابه خود دور می شود می تواند عمل ویرایش مولکول ساخته شده را به انجام برساند.', 3, 4, 28, 148, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:47:41', 4, 'done'),
(874, 'کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;مطابق با مطالب کتاب درسی نوعی آنزیم که برای ................. مورد استفاده قرار می گیرد به طور حتم ...................... .&raquo;', 3, 4, 28, 152, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:47:25', 4, 'done'),
(875, 'در فرایند همانندسازی مولکول دنا (DNA)ی خطی در پارامسی، پس از تشکیل دوراهی های همانندسازی، ابتدا کدام مورد به وقوع می پیوندد؟', 3, 4, 28, 148, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:45:36', 4, 'done'),
(876, 'با توجه به اطلاعات کتاب درسی و با در نظر گرفتن اتفاقاتی که در ارتباط با آزمایش های ایوری و همکارانش رخ داد و با فرض این که در این آزمایش ها تنها از عصاره استخراج شده از باکتری های کشته شده پوشینه دار و باکتری های زنده فاقد پوشینه استرپتوکوکوس نومونیا استفاده شد؛ می توان بیان داشت طی هر آزمایشی که در آن ............... به طور حتم ................. .', 3, 4, 28, 145, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:48:10', 4, 'done'),
(877, 'مطابق با آزمایش های مزلسون و استال، ویژگی نمونه های تهیه شده در سه زمان متفاوت &laquo;بعد از بیست دقیقه&raquo;، &laquo;بعد از چهل دقیقه&raquo; و &laquo;صفر دقیقه&raquo;، به ترتیب در کدام گزینه زیر بیان شده است؟ الف: در همه دنا (DNA)های موجود، فقط یکی از دو رشته دنا (DNA) واجد ایزوتوپ سنگین نیتروژن هستند. ب: در نیمی از دنا (DNA)های موجود، هر دو رشته دنا (DNA) واجد ایزوتوپ سبک نیتروژن هستند. ج: در همه دنا (DNA)های موجود، هر دو رشته دنا (DNA) واجد ایزوتوپ سنگین نیتروژن هستند. د: نیمی از دنا (DNA)های موجود، دارای چگالی سنگین بوده و نواری در پایین لوله تشکیل میدهند. ه: همه دنا (DNA)های موجود، حداقل دارای رشته های با ایزوتوپ سبک نیتروژن بوده و در بیش از یک بخش لوله، نواری از دنا تشکیل می شود. و) همه دنا (DNA)های موجود، دارای چگالی متوسط بوده و نواری در میانه لوله تشکیل می دهند.', 3, 4, 28, 150, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:45:53', 4, 'done'),
(878, 'با توجه به ساختار نشان داده شده در شکل مقابل و آن دسته از برهم کنش هایی که منشأ اصلی تشکیل این ساختار هستند، کدام مورد نادرست است؟', 3, 4, 28, 151, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:46:38', 4, 'done'),
(879, 'در خصوص بسپارهایی (پلیمرهایی) که سرعت واکنش هایی را که در بدن موجودات زنده انجام شدنی هستند، افزایش می دهند کدام مورد درست است؟', 3, 4, 28, 152, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:46:25', 4, 'done'),
(880, 'مطابق با اطلاعات کتاب درسی، کدام دو ویژگی، در مورد هر واحد تکرار شونده در ساختار مولکول های حامل اطلاعات وراثتی در یوکاریوت ها، درست است؟', 3, 4, 28, 146, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:47:02', 4, 'done'),
(881, 'به طور معمول، کدام دو ویژگی، در مورد فقط یک سطح ساختاری یکسان از سطوح ساختاری پروتئین ها صادق است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(882, 'در کدام گزاره های زیر، دو مورد بیان شده تعداد متفاوتی با یکدیگر دارند؟ الف: تعداد آنزیم های هلیکاز در یک دوراهی همانندسازی و تعداد پیوندهای هیدروژنی بین یک جفت نوکلئوتید گوانین دار و سیتوزین دار ب: تعداد جایگاه آغاز همانندسازی دنای اصلی در اغلب پروکاریوت ها و تعداد آنزیم های دنابسپاراز در هر ساختار Y شکل همانندسازی ج: تعداد حلقه های آلی در نوکلئوتیدهای گوانین دار و تعداد رشته های تشکیل دهنده هر نوع نوکلئیک اسید حلقوی د: تعداد سطوح ساختاری پروتئین هموگلوبین و تعداد ظرفیت کربن مرکزی در ساختار همه انواع آمینواسیدها', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(883, 'مطابق با اطلاعات کتاب درسی، دو نوع مولکول غیر آنزیمی، واجد گروه هم متصل به زنجیره (های) آمینواسیدی هستند. این دو مولکول از نظر............ با هم متفاوت هستند و از لحاظ ................. به یکدیگر شباهت دارند.', 3, 4, 28, 151, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:45:05', 4, 'done'),
(884, 'کدام مورد مربوط به تنظیم بیان ژن های درون هسته یوکاریوت ها، در مراحل پس از رونویسی است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(885, 'مطابق با اطلاعات کتاب درسی، پس از آن که رنای پیک بالغ با رشته الگوی آن در دنا مجاورت داده شود، بخش هایی از این رشته دنا که در تشکیل پیوند هیدروژنی با رشته رنا شرکت دارند، ....................... بخش هایی که به صورت حلقه هایی بیرون از مولکول دورشته ای قرار می گیرند، ................. .', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(886, 'مطابق با اطلاعات کتاب درسی، در گروهی از یاخته ها که به وسیله غشاها به بخش های مختلفی تقسیم شده اند، عواملی وجود دارند که به منظور شروع فرایند رونویسی و شناسایی راه انداز توسط آنزیم رنابسپار از فعالیت می کنند. کدام مورد دربارۀ این عوامل نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(887, 'کدام عبارت در خصوص همه جانداران تک یاخته ای، صحیح است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(888, 'با توجه به شکل مقابل که مربوط به فرایندی در یک یاخته یوکاریوتی فعال است، کدام عبارت صحیح است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(889, 'چند مورد زیر در خصوص مراحل ساخت و سرنوشت پروتئین ها در یک یاخته یوکاریوتی صادق است؟( با فرض این که فقط پروتئین هایی که توسط رناتن های همان یاخته ساخته شده اند، مد نظر قرار گیرند.) الف: پروتئین هایی که توسط رناتن های آزاد در سیتوپلاسم تولید می گردند، به طور حتم توالی های آمینواسیدی به منظور هدایت به سمت نوعی ساختار دوغشایی دارند. ب: پروتئین هایی که در واکوئول یا کافنده تن ها قرار دارند، ممکن است با همکاری بیش از یک رناتن متصل به غشای شبکه آندوپلاسمی زیر ایجاد شده باشند. ج: رشته های پلی پپتیدی که درون نوعی اندامک واجد کیسه های غشادار دچار تاخوردگی می شوند به طور حتم درون سیتوپلاسم یا خارج یاخته فعالیت می کنند. د: رشته های پلی پپتیدی که از منافذ مرتبط کننده سیتوپلاسم و هسته عبور می کنند، ممکن است در پی اتصال یک اندامک به نوعی غشای زیستی تک لایه تولید شوند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(890, 'مطابق شکل زیر و با توجه به فرایندهایی که میزان رونویسی از یک ژن خاص و تولید محصول نهایی آن را تنظیم می کنند، کدام مورد صحیح است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(891, 'با توجه به فرایندهای تنظیم بیان ژن در پروکاریوت ها که در کتاب درسی آمده است، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;در باکتری اشرشیاکلای (E.coli) در عدم حضور گلوکز و با افزودن لاکتوز به محیط کشت، به دنبال ............. قابل انتظار است.&raquo;', 3, 4, 29, 159, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:44:27', 4, 'done'),
(892, 'با توجه به مطالب کتاب درسی، کدام موارد، وجه اشتراک دو نوع تنظیم مثبت و منفی در باکتری اشرشیاکلای است؟ الف: پروتئین متصل شده به نوعی دی ساکارید، به توالی تنظیمی در مجاورت راه انداز ژن متصل می شود. ب: در حضور نوعی قند، رونویسی با پیوستن رنابسپار از به راه انداز مشترک چند ژن، آغاز می شود. ج: در نتیجه ترجمه محصول رونویسی، بسپارهایی با ساختارهای متفاوت از هم تولید می شوند. د: برای بیان ژن نوعی پروتئین تنظیم کننده دارای تمایل یکسانی برای اتصال به قند و دنا است.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(893, 'در مراحلی از فرایند رونویسی در استرپتوکوکوس نومونیا، بعد از بازشدن دو رشته ژن، باز آلی آدنین متصل به دئوکسی ریبوز، می تواند با دو نوع باز آلی پیوند هیدروژنی تشکیل دهد. کدام عبارت، فقط در خصوص برخی از این مراحل صادق است؟', 3, 4, 29, 153, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:44:00', 4, 'done'),
(894, 'طی فرایند ترجمه رنای پیک (mRNA) مربوط به پروتئین میوگلوبین در عضلات اسکلتی، چند مورد، فقط در برخی از شرایط اتفاق می افتد؟ الف: بلافاصله پس از خروج tRNA از جایگاه E، جایگاه A آماده پذیرش tRNA متصل به آمینواسید می باشد. ب: اندکی پس از تشکیل پیوند پپتیدی در یکی از جایگاه های رناتن، رنای ناقل بدون آمینواسید از جایگاه E خارج می شود. ج: بعد از شکستن پیوند بین زنجیره آمینواسیدی و tRNA ، رنای ناقل فاقد آمینواسید به جایگاه E منتقل می شود. د: کمی پیش از تشکیل شدن پیوند پپتیدی، نوعی پیوند اشتراکی در جایگاه میانی رناتن (ریبوزوم) شکسته می شود.', 3, 4, 29, 156, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:43:17', 4, 'done'),
(895, 'براساس مطلب کتاب درسی، در خصوص هر فرایندی که در سر اسپرم های در حال تشکیل، از نوکلئوتیدها به عنوان الگو برای ساخت نوعی بسپار زیستی استفاده می شود، کدام مورد، به طور حتم صادق است؟', 3, 4, 29, 156, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:43:05', 4, 'done'),
(896, 'کدام گزینه در خصوص رنای ناقل (tRNA) نادرست است؟', 3, 4, 29, 156, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:43:45', 4, 'done'),
(897, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در هر مرحله ای از فرایند ترجمه رنای پیک تک ژنی که ................ .&raquo;', 3, 4, 29, 156, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:42:03', 4, 'done'),
