(900, 'مطابق با اطلاعات کتاب درسی، در خصوص یکی از انواع فرایندهای تنظیم بیان ژن در مرحله رونویسی یک یاخته پروکاریوتی که مالتوز در این فرایند نقش مهمی دارد، کدام مورد درست است؟', 3, 4, 29, 159, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:44:12', 4, 'done'),
(901, 'با توجه به جانداران مطرح شده در کتاب درسی ،کدام مورد زیر صحیح است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(902, 'هر نوع کاتالیزور زیستی درون هسته یک یاخته فعال جانوری که فعالیت بسپارازی دارد و در ساختار نهایی محصول نوکلئیک اسیدی آن پیوند هیدروژنی یافت نمی شود، چه مشخصه ای دارد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(903, 'با توجه به موارد مطرح شده در زیر، چند مورد به ترتیب از راست به چپ &laquo;در خصوص رنای ناقل &raquo;،&laquo;(tRNA)رنای پیک(mRNA) &raquo;و &laquo;رنای رناتن (rRNA)&raquo; می تواند صحیح باشد؟ واجد ساختار سه بعدی و شکل فضایی معین توانایی نگه داری اطلاعات درون خود بسپارهایی (پلیمرهایی) از واحدهای تکرارشونده حامل اطلاعات چندین ژن در یک رشته نوکلئیک اسیدی حضور در هر دو زیرواحد سازنده رناتن (ریبوزوم) یا تماس مستقیم با آن ها', 3, 4, 29, 156, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:41:22', 4, 'done'),
(904, 'کدام مورد باعث می شود تا جمعیتی از جانوران، در تعادل ژنی باقی بماند؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(905, 'مطابق اطلاعات کتاب درسی، گروهی از جهش های متأثر از عوامل جهش زا در یاخته های پوششی پوست، تغییری در تعداد نوکلئوتیدهای محتوای وراثتی هسته ای ایجاد نمی کنند. کدام گزینه، در خصوص این جهش ها درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(906, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;تغییر فراوانی دگرهای اگر بر اثر .................... رخ دهد، به طور حتم................ را در پی خواهد داشت.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(907, 'در خصوص پدیده چلیپایی شدن (کراسینگ اور)، کدام گزینه همواره درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(908, 'چند مورد را می توان به تغییرات مربوط به مولکول های زیستی در افراد مبتلا به بیماری کم خونی داسی شکل نسبت داد؟ الف: قرارگیری آمینواسید گلوتامیک اسید به جای والین در زنجیره بتای هموگلوبین ب: تغییر در تعداد پیوندهای هیدروژنی بین نوکلئوتیدهای ژن مربوط به ساخت زنجیره بتا ج: کاهش تعداد حلقه های کربن دار در رنای پیک حاصل از ژن تغییر یافته نسبت به حالت سالم د: تغییر ساختار چهارم هموگلوبین در نتیجه تغییر در ساختار اول نیمی از زنجیره های پلی پپتیدی آن', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(909, 'مطابق با مطلب کتاب درسی، در اوایل دهه ۱۹۰۰ دانشمندی به نام هوگو دووری که با گیاهان گل مغربی کار می کرد، متوجه شد که یکی از گل های مغربی ظاهری متفاوت با بقیه دارد. گیاه ذکر شده فاقد کدام مشخصه زیر است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(910, 'از نظر تعداد توالی های حفظ شده در DNA ، کدام زوج جاندار بیشترین تعداد توالی های مشابه را دارند؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(911, 'جهش ها براساس عوامل ایجاد کننده آن ها به چند دسته تقسیم می شوند. چند مورد درباره جهشی درست است که در اثر عواملی با تشکیل دوپار (دیمر) تیمین درون نوعی ژن یاخته های پوست انسان همراه است؟ الف: باعث تشکیل پیوندهای هیدروژنی میان دو نوکلئوتید پیریمیدینی در یک رشته دنا (DNA) می شود. ب: باعث اختلال در حرکت آنزیم دنابسپار از بر روی نوکلئوتیدهای مولکول دنا (DNA) می شود. ج: ممکن است سبب القای فعالیت آنزیم های تجزیه کننده پروتئین ها در یاخته شود. د: ناشی از مصرف ترکیباتی نظیر بنزوپیرن در دود سیگار و قلیان است.', 3, 4, 31, 123, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:40:25', 4, 'done'),
(912, 'طبق اطلاعات کتاب درسی، به منظور بروز گونه زایی رخ داده در شکل زیر در یک جمعیت، همواره لازم است تا ............ .', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(913, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;با توجه به ناهنجاری های مطرح شده در کتاب درسی، اگر در پی نوعی از جهش های بزرگ و ساختاری از یک فام تن طبیعی و مضاعف نشده ............... قطعه ای جدا و....................، به طور حتم ............... .&raquo;', 3, 4, 31, 121, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:39:35', 4, 'done'),
(914, 'کدام مورد نادرست است؟', 3, 4, 31, 125, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:39:48', 4, 'done'),
(915, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول در فرایند اسپرم زایی انسان، در هر یاخته ای که............. است، امکان وقوع .................. نیز وجود دارد.&raquo;', 3, 4, 31, 126, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:39:18', 4, 'done'),
(916, 'مطابق اطلاعات کتاب درسی و در خصوص شواهد تغییر گونه ها، کدام مورد نادرست است؟', 3, 4, 31, 127, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:38:33', 4, 'done'),
(917, 'طبق اطلاعات کتاب درسی، چند مورد، مشخصۀ همۀ جهش های کوچکی را بیان می کند که می توانند بر طول رشته پلی پپتیدی مربوط به ساخت نوعی آنزیم درون یاخته ای اثرگذار باشند؟ الف: به طور حتم با تغییر توالی سه نوکلئوتیدی مربوط به کدون پایان همراه هستند. ب: به طور حتم، مدت زمان تبدیل پیش ماده به فراورده توسط آنزیم را به شدت تغییر می دهند. ج: فقط در برخی مواقع، می توانند توالی نوکلئوتیدی مولکول خطی تولید شده، در پی الگو قرارگیری دنا را، تغییر دهند. د: ممکن نیست توالی سه نوکلئوتیدی کدون آغاز را که به آمینواسید متیونین ترجمه می شود، تغییر دهند.', 3, 4, 31, 120, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:37:46', 4, 'done'),
(918, 'کدام مورد، برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول در فرایند زامه (اسپرم) زایی یک مرد بالغ، در صورت جدانشدن فام تن (کروموزوم)ها فقط در مرحلهٔ ................ گامت هایی که نهایتاً حاصل می شوند، در صورت لقاح یافتن با گامت ماده، طبیعی یاخته تخمی با تعداد فام تن (کروموزوم)های .............. تولید می کنند.&raquo; (با در نظر گرفتن این موضوع که طی آنافاز ۲، جدانشدن فام تن ها، فقط در یکی از یاخته ها رخ می دهد.)', 3, 4, 31, 128, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:37:32', 4, 'done'),
(919, 'عوامل برهم زننده تعادل جمعیت ها به پنج دسته تقسیم می شوند. در زیر توصیفاتی آورده شده است که هر کدام را می توان به یک یا تعدادی از این عوامل نسبت داد. کدام گزینه این توصیفات را براساس امکان نسبت دادن آن ها به تعداد بیشتری از این عوامل، مرتب کرده است؟ (بدون در نظر گرفتن شرایط گونه زایی) الف: موجب افزودن دگره جدید به خزانه ژنی یک جمعیت می شود. ب: در صورت وقوع به صورت مستقیم بر خزانه ژنی دو جمعیت تأثیر می گذارد. ج: می تواند با افزایش فراوانی نسبی برخی از دگره ها در جمعیت همراه باشد. د: منجر به کاهش تفاوت های فردی در افراد موجود در یک جمعیت خواهد شد.', 3, 4, 31, 125, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:38:05', 4, 'done'),
(920, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول هر نوع سازوکار ایجاد کننده گونه جدید که .............. .&raquo;', 3, 4, 31, 128, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:36:45', 4, 'done'),
(921, 'به دنبال وقوع جهش های کوچک بر روی توالی های تنظیمی مؤثر در رونویسی از ژن(های) عوامل رونویسی در جانداران، چند پیامد زیر غیر ممکن است؟ الف: افزایش میزان ترجمه رنا(های) پیک این پروتئین ها قبل از پایان کامل رونویسی آن ها ب: کاهش میزان تمایل آنزیم رنابسپاراز برای اتصال به توالی(های) موجود در پیش از ژن ج: افزایش مدت زمان اتصال پروتئین ها به توالی مؤثر در خمیده شدن بخشی از ساختار دنا هنگام رونویسی د: عدم تغییر در میزان همۀ واکنش های آنزیمی یاخته به دلیل عدم تغییر در توالی آمینواسیدی پروتئین های حاصل از بیان ژن ها', 3, 4, 29, 161, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:36:15', 4, 'done'),
(922, 'در یک یاخته بنیادی میلوئیدی انسان، در صورت وقوع جهشی کوچک از نوع............. در توالی ژن(های) ............... به طور حتم ............... .', 3, 4, 31, 120, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:40:03', 4, 'done'),
(923, 'اگر در خانواده ای که والدین از نظر صفت کم خونی ناشی از گویچه های قرمز داسی شکل در شرایط طبیعی، فنوتیپ سالم را بروز می دهند، گویچه های قرمز فرزند دختر فقط در صورت قرارگیری در محیط کم اکسیژن داسی شکل شوند و فرزند پسر خانواده به علت داشتن هموگلوبین های تغییر شکل یافته، در سنین کودکی از دنیا رفته باشد؛ در یک منطقه مالاریاخیز تولد چند مورد زیر در این خانواده محتمل است؟ پسری مقاوم نسبت به ابتلا به بیماری مالاریا دختری در معرض خطر ابتلا به بیماری مالاریا دختری کاملاً سالم از نظر کم خونی داسی شکل با ژن نمود شبیه به پدر پسری با احتمال بقای بیشتر (از نظر ابتلا به مالاریا) و ژن نمود متفاوت از مادر', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(924, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول ............... نوکلئوتیدهای مشترک بین رمزه (کدون) آغاز و همه رمزه های پایان، ................... .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(925, 'در خصوص پسری با &laquo;توانایی ساخت پروتئین غشایی مربوط به گروه خونی و دارای بیش از یک نوع دگره (الل) در جایگاه (های) ژن گروه خونی ABO&raquo;، کدام یک از گزینه های زیر را با قاطعیت می توان بیان داشت؟', 3, 4, 30, 162, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:35:57', 4, 'done'),
(926, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در باکتری اشرشیاکلای ................می تواند از پیامدهای نوعی جهش کوچک در .................. موجود در محتوای وراثتی این یاخته باشد.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(927, 'کدام گزینه عبارت زیر را به طور مناسب کامل میکند؟ &laquo;با توجه به مطالب کتاب درسی، نخستین دانشمند یا دانشمندانی که به ................... پی بردند، ................. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(928, 'کدام مورد، در ارتباط با ژنگان (ژنوم) هر انسان سالم و بالغ درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(929, 'کدام گزینه، در خصوص نوکلئوتیدهای موجود در یاخته زنده نگهبان روزنه، درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(930, 'در خصوص رناتن (ریبوزوم)های یک یاخته یوکاریوتی کدام مورد نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(931, 'با توجه به دو صفت داسی شکل شدن گویچه های قرمز و هموفیلی در انسان، از ازدواج هر زن با فنوتیپ سالم و مرد با فنوتیپ بیمار، برای هر دو صفت، تولد کدام فرزند در تعداد حالت بیشتری قابل انتظار است؟ (فرد در شرایط اکسیژن طبیعی محیط زندگی می کند.)', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(932, 'مطابق با اطلاعات کتاب درسی، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول، .............. جاندارانی که از یک مولکول رنای پیک، بیش از یک رشته پلی پپتیدی قابل تولید است، ................. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(933, 'مطابق مطلب کتاب درسی، نوعی عامل خارج کننده جمعیت از حالت تعادل، با ایجاد دگره (الل)های جدید در افراد، در فرایندهای گونه زایی نقش مؤثری دارد. کدام مورد دربارۀ این عامل در طبیعت صحیح است؟', 3, 4, 31, 125, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:34:16', 4, 'done'),
(934, 'با توجه به اطلاعات کتاب درسی، گروهی از کاتالیزورهای زیستی سیتوپلاسم می توانند با فعالیت خود، سبب افزایش تعداد آمینواسید حمل شده توسط رنای ناقل گردند. ویژگی مشترک این مولکول ها کدام است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(935, 'کدام عبارت فقط در خصوص یکی از انواع مختلف طرح های پیشنهادی همانندسازی دنا (مطرح شده در کتاب درسی) صادق است؟ (با فرض این که یک دور همانندسازی یک مولکول دنا (DNA)ی سنگین که فقط دارای N15 است، در محیط کشت دارای 14N صورت بگیرد.', 3, 4, 28, 146, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:33:08', 4, 'done'),
(936, 'کدام گزینه عبارت زیر را به شیوه متفاوتی از نظر درستی یا نادرستی نسبت به سایر گزینه ها کامل می کند؟ &laquo;در هر سطحی از سطوح ساختاری رنگدانه ذخیره کننده اکسیژن در تارهای ماهیچه اسکلتی که ............... به طور حتم ............... .&raquo;', 3, 4, 28, 151, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-12 20:33:32', 4, 'done'),
(937, 'در کدام گزینه هر دو ویژگی را نمی توان به یک نوع جهش یکسان از انواع جهش های بزرگ نسبت داد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(938, 'با توجه به اطلاعات کتاب درسی، کدام یک از موارد زیر در ارتباط با هر دانشمندی صحیح است که از آزمایشات آن اطلاعاتی درباره مولکول منتقل کننده اطلاعات وراثتی قبل از کشف نوع آن، به دست آمد؟ الف: در سومین آزمایش خود با روش هایی، گروهی از مولکول های زیستی باکتری های پوشینه دار را تخریب نمود. ب: در یکی از آزمایشات خود به کمک گریزانه (سانتریفیوژ) با سرعت بالا مولکول های زیستی را به طور لایه لایه جدا کرد. ج: مولکول های زیستی باکتری های پوشینه دار کشته شده را در مجاورت باکتری های بدون پوشینه زنده قرار داد. د: در آخرین آزمایش خود پس از پوشینه دار شدن باکتریهای فاقد پوشینه با تزریق آنها به موش سبب مرگ این جانور شد.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(939, 'کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;مطابق شکل مقابل، ................. از رویداد نشان داده شده، به دنبال ........... می شود.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(940, 'در خصوص مولکول های زیستی، پروتئین هایی که در یاخته های بدن انسان، سبب کاهش انرژی لازم برای شروع واکنش های شیمیایی می شوند، چند مورد غیر ممکن است؟ الف: بدون وجود کوآنزیم ها ممکن است زمان انجام واکنش (های) شیمیایی را کاهش دهند. ب: با قرارگیری ماده(های) سمی در جایگاه فعال آن ها، فعالیت عادی خود را ادامه دهند. . ج: پس از بهبود تب شدید، از حالت غیر فعال مجدداً به حالت فعال و اولیه خود بازگردند. د: در یاخته ای فعالیت کنند که توسط اطلاعات وراثتی همان یاخته تولید نشده باشند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(941, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در هر جانداری که می تواند ............... .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(942, 'طبق مطلب کتاب درسی، پس از شروع همانندسازی در بخشی از دنا، کدام مورد در خصوص آنزیم هایی صحیح است که در محل دوراهی های همانندسازی وجود دارند؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(943, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;در مرحله ای از فرایند رونویسی که بین نخستین نوکلئوتید رشته الگو با نوکلئوتید مکمل آن در دنا، پیوندهای هیدروژنی برقرار می شود، ................&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(944, 'در خصوص جهشی که سبب داسی شکل شدن گویچه های قرمز انسان می شود، کدام موارد زیر نادرست هستند؟ الف: برخلاف جهش کوچک حذف، فاقد توانایی تغییر چارچوب خواندن دنا است. ب: همانند جهش کوچک اضافه، وقوع آن با بررسی کاریوتیپ، غیر قابل تشخیص است. ج: برخلاف جهش خاموش، می تواند سبب تغییر در توالی رنای حاصل از ژن شود. د: همانند جهش بی معنا، در شرایطی طول پلی پپتید حاصل از ژن را تغییر می دهد', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(945, 'درباره شواهد تغییر گونه ها، کدام مورد نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(946, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در ساختار دوم هر یک از زیرواحدهای هموگلوبین ............. زنجیره ای پلی پپتیدی که در ساختار دوم خود، فقط دارای ساختارهای صفحه ای ............... می باشد.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(947, 'با توجه به اطلاعات کتاب درسی و با در نظر گرفتن اتفاقاتی که در یک جمعیت فراوانی نسبی دگره ها یا ژن نمودها را از نسلی به نسل دیگر، تغییر می دهند، کدام مورد به طور حتم درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(948, 'مطابق با مطلب کتاب درسی، فرایندهای رونویسی و ترجمه در یوکاریوت ها، هر کدام از سه مرحله تشکیل شده اند. بر این اساس تعداد مراحلی از فرایند ترجمه که طی آنها .............، برابر با تعداد مراحلی از فرایند رونویسی است که در آنها ............ صورت می گیرد.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(949, 'با توجه به مثال های کتاب درسی در خصوص تنظیم بیان ژن در مرحله رونویسی در باکتری اشرشیاکلای، کدام مورد برای تکمیل عبارت زیر لزوماً درست نیست؟ &laquo;در صورت قرارگیری باکتری اشرشیاکلای در محیطی که ........... دارد، ............ امکان پذیر می شود.&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(950, 'مطابق اطلاعات کتاب درسی، چند مورد را می توان مشخصه مشترک همه پروتئین هایی در یاخته یوکاریوتی دانست که پس از اتصال به مولکول دنا، می توانند منجر به کاهش فاصله میان بخش هایی از این مولکول شوند؟ الف: اندازه کوچک تری نسبت به رنابسپار از متصل به توالی راه انداز دارند. ب: توسط رناتن (ریبوزوم) های آزاد موجود در سیتوپلاسم یاخته ساخته می شوند. ج: با اتصال به بخشی از دنا منجر به افزایش میزان رونویسی از ژن خواهند شد. د: بیان یک ژن خاص در مادۀ وراثتی هسته را در مرحله رونویسی تنظیم می نماید.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(951, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;طی ترجمه رنای پیک مربوط به زنجیره های بتای هموگلوبین، در فردی که مبتلا به کم خونی داسی شکل است برخلاف فرد کاملاً سالم، به دنبال ............... .&raquo; (با فرض این که در ۱۰ آمینواسید ابتدایی زنجیره بتای هموگلوبین هر دو فرد، هیچ آمینواسید تکراری وجود نداشته باشد.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(952, 'با توجه به مطالب کتاب درسی، در یک منطقه مالاریاخیز، مادر یک خانواده برخلاف پدر خانواده در برابر مالاریا مقاوم نیست و هر دو از نظر سایر بیماریهای ژنتیکی سالم هستند. در صورتی که دختری با محدودیت در تغذیه از شیر مادر در این خانواده متولد شود. تولد کدام فرزندان ممکن خواهد بود؟ الف: دختری ناقل دو نوع بیماری ژنتیکی متفاوت ب: پسری واجد گویچه های قرمز کاملاً طبیعی در جریان خون ج: دختری دارای بیش از یک دگره Hbs در برخی از یاخته های پیکری بدن د: پسری با توانایی تجزیه فنیل آلانین و واجد گویچه های قرمز ممانعت کننده از هر گونه ورود انگل مالاریا', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(953, 'مطابق اطلاعات کتاب درسی، مشخصه مشترک انواع نوکلئیک اسیدهای واجد پیوند هیدروژنی موجود در سیتوپلاسم یک یاخته یوکاریوتی، کدام است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(954, 'چند مورد، برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول ............... جانداران مطرح شده در کتاب درسی که تعریف ارنست مایر از گونه برای آن ها صادق ............. .&raquo; الف: همه - است، پیش از زادآوری، نیازمند حضور یاخته جنسی فردی دیگر از گونه خود هستند ب: فقط بعضی از - است، به کمک فضاهای سیناپسی، پیام های شیمیایی را بین یاخته های مختلف جابه جا می کنند ج: همه &ndash; نیست، ساختاری فسفولیپیدی دارند که عبور مواد از یاخته به فضای بین یاخته ای را تنظیم میکند د: فقط بعضی از - نیست، به کمک اطلاعات موجود در ساختارهای دوغشایی، هم ایستایی خود را حفظ می کنند', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(955, 'با توجه به ساختار آمینواسید سرین که در شکل زیر نشان داده شده است، کدام گزینه به ترتیب، درستی یا نادرستی موارد ذکر شده را در ارتباط با بخش مشخص شده، به درستی بیان کرده است؟ در بین آمینواسیدهای موجود در طبیعت، تنها بیست نوع ساختار شیمیایی برای آن وجود دارد. . طی تشکیل ساختار خطی پروتئین ها، OH این گروه با H گروهی دیگر، مولکول آب را می سازد. تغییر pH می تواند با تأثیر بر پیوندهای حاصل از این بخش، سبب تغییر شکل آنزیم شود. . در انسان، تنوع فرمول شیمیایی این بخش ها می تواند با تنوع پادرمزه (آنتی کدون )ها برابر باشد.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(956, 'مطابق اطلاعات کتاب درسی، کدام ویژگی، انواع مختلف فرایندهای گونه زایی را از یکدیگر متمایز می سازد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(957, 'با توجه به اطلاعات کتاب درسی، در چند مورد ویژگی مشترک همۀ مولکول های پروتئینی که به رنابسپار از برای اتصال به توالی راه انداز کمک می کنند، بیان شده است؟ الف: عواملی در یاخته، میزان تمایل پیوستن آنها به راه انداز را تغییر می دهد. ب: نسبت به رنابسپاراز، در بخش دورتری از توالی ژن به دنا (DNA) متصل می گردند. ج: به منظور تنظیم بیان ژن، می توانند به مولکول (هایی) با یک نوع مونوساکارید متصل شوند. د: پس از اتصال به رنابسپاراز، همراه با آن به توالی خاصی از دنا متصل می شوند.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(958, 'کدام عبارت درست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(959, 'چند مورد، به منظور تکمیل عبارت زیر مناسب است؟ &laquo;فقط بعضی از پروتئین هایی که ............. نقش دارند، توسط اندامک های بدون غشای متصل به شبکه آندوپلاسمی یاخته، تولید می شوند.&raquo; الف: در جلوگیری از تقسیم بیرویه یاخته ها ب: با قرارگیری در ریزکیسه ها، در تأمین نیازهای یاخته ج: در بروز نوعی تغییر در ساختار فسفولیپیدی احاطه کننده سیتوپلاسم د: در کاهش انرژی فعال سازی واکنش های شیمیایی در سیتوپلاسم یاخته', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(960, 'فرایند چگونگی مقاوم شدن جمعیت باکتری ها نسبت به پادزیست، نشان دهنده کدام یک از موارد زیر است؟ الف: تغییر جانداران در گذر زمان ب: تأثیر انتخاب طبیعی بر گوناگونی در جمعیت ج: الزام وجود تفاوت های فردی در جمعیت برای پایدار ماندن آن د: تعیین کننده بودن نقش محیط در میزان فراوانی صفات منتقل شده به نسل بعد', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(961, 'در خصوص روش های مختلف ساخت ATP، کدام گزینه برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول، تولید ATP در طی فرایند ............. به روشی است که ............. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(962, 'با توجه به اطلاعات کتاب درسی، ویژگی مشترک همۀ ترکیبات آلی که در اولین مرحله تنفس هوازی گروه(های) فسفات دریافت می کنند، کدام است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(963, 'در کدام یک از گزینه های زیر ،تعداد \\(CO_2\\) بیشتری آزاد می شود؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(964, 'مطابق با مطلب کتاب درسی، با افزوده شدن گروه فسفات در سه مرحله به نوعی مولکول آلی، شکل رایج انرژی در یاخته، می تواند تولید گردد. در خصوص این فرایندها، کدام مورد نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(965, 'در یک یاخته پوششی پرز روده باریک در حد فاصل زمانی که یک ترکیب شش کربنه قندی و فسفاته در طول واکنش هایی مجددا به نوعی ترکیب شش کربنه تبدیل می گردد. به ترتیب از راست به چپ چه مواردی تولید و چه مواردی مصرف می گردد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(966, 'مطابق با اطلاعات کتاب درسی، اولین مرحله از تنفس هوازی از چهار مرحله جزئی تر تشکیل شده است. کدام مورد، در خصوص تعداد مراحل کمتری از این فرایند صادق می باشد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(967, 'نوعی اندامک دوغشایی در یاخته های یوکاریوتی وجود دارد که همراه با یاخته و نیز مستقل از آن تقسیم می شود و تجزیه کامل گلوکز و تأمین انرژی در آن وابسته به حضور اکسیژن است. اندامک مورد نظر فاقد کدام مشخصه زیر است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(968, 'مطابق اطلاعات کتاب درسی، کدام موارد را می توان ویژگی مشترک حاملین الکترونی دانست که به دنبال اکسایش نوعی مولکول شش کربنی، در بخش داخلی راکیزه یک یاخته کبدی زنده و فعال ساخته می شوند؟ الف: توانایی عبور از چهار لایه فسفولیپیدی غشاهای راکیزه ب: آزاد کردن دو الکترون به اجزای غشای درونی راکیزه به دنبال اکسایش یافتن ج: مؤثر در تشکیل مولکول های آب با انتقال الکترون های آنها به یون اکسید د: انتقال مستقیم الکترون های آن ها به مولکولی واجد تماس با هر دو لایه فسفولیپیدی غشای چین خورده راکیزه', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(969, 'با توجه به مراحل کلی تنفس هوازی، چند مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول،................. مراحلی که در راکیزه (میتوکندری) انجام می شوند، ............ رخ می دهد.&raquo; الف: در همه ـ تولید و مصرف نوعی ترکیب آلی شش کربنه ب: فقط در یکی از ــ تولید انواعی از مولکول های حامل الکترون ج: در همه ـ آزاد شدن مولکول کربن دی اکسید از ترکیب(های) آلی د: فقط در یکی از ـ افزوده شدن گروه فسفات به مولکول آدنوزین دی فسفات', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(970, 'در خصوص زنجیره انتقال الکترون در یک یاخته کبدی انسان، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;جزئی که به عنوان ............. شناخته می شود، ........... .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(971, 'چند مورد عبارت زیر را به درستی کامل می کند؟ &laquo;در یاخته های یوکاریوتی، در فرایندهایی از تنفس یاخته ای هوازی، علاوه بر وقوع واکنش های تجزیه کننده گلوکز، مولکول(های) \\(ATP\\) نیز تولید می شوند. هر یک از این فرایندها که ................. .&raquo; الف: طی آن مولکول های دوفسفاته مصرف می شود، در مادۀ زمینه سیتوپلاسم یاخته رخ می دهد ب: به فعالیت پروتئین های غشایی راکیزه وابسته است، با مصرف مولکولی شش کربنی، طی واکنش(هایی) \\(NADH\\) می سازد ج: از بیش از یک نوع آنزیم برای انجام واکنش های اکسایش و کاهش استفاده می کند، سهم کمتری در تولید \\(ATP\\) یاخته دارد د: با تغییر تعداد اتم کربن نوعی مولکول آلی همراه است، مولکولی را می سازد که در اولین واکنش این فرایند نیز مصرف می شود', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(972, 'با توجه به شکل زیر که بخشی از واکنش های تنفس یاخته ای در یک تار ماهیچه توام را نشان می دهد، کدام گزینه نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(973, 'مطابق متن کتاب درسی، &laquo;در صورتی که منابعی که یاخته های بدن انسان به طور معمول از آنها برای تأمین انرژی استفاده می کنند، کافی نباشند، یاخته ها برای تولید \\(ATP \\) به سراغ تجزیه گروه های دیگری از مولکول های زیستی می روند.&raquo; کدام مورد در خصوص این گروه های دیگر مولکول های زیستی صحیح است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(974, 'در نخستین مرحله تنفس یاخته ای در تارهای ماهیچه ای که مسئول انجام انقباضات سریع اند، همزمان با .......... هر نوع ترکیب ........... .', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(975, 'مطابق اطلاعات کتاب زیست شناسی 3، کدام مورد، در خصوص هر نوع تخمیر قابل انجام در گیاهان، صحیح است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(976, 'در طی روش(های) مختلف تأمین کننده \\(ATP \\) در یک یاخته گیاهی، محصول نهایی قند کافت به ترکیبی دوکربنی تبدیل می شود. کدام مورد در خصوص این روش(ها) در یاخته گیاهی به طور حتم صادق است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(977, 'در فرایندهای مربوط به تنفس یاخته ای در انسان، مولکول هایی تولید می شوند که تنها در شرایط هوازی اکسایش می یابند. کدام مورد در خصوص همۀ این مولکول ها نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(978, 'کدام ویژگی، تخمیر مؤثر در ورآمدن خمیر نان را از تخمیر مؤثر در تولید محصولات لبنی، در یوکاریوت ها متمایز می سازد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(979, 'در هر یاخته غده تیروئید انسان، به منظور تغییر مولکول فروکتوز فسفاته تا زمان ورود استیل کوآنزیم \\(A\\) به چرخه کربس لازم است تا ............... به وقوع به پیوندد.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(980, 'در یکی از مراحل گلیکولیز نوعی مولکول حامل الکترون تشکیل می شود. این مولکول هیچگاه همراه با تولید پیرووات تشکیل نمی گردد. این مولکول حامل الکترون، نمی تواند کدام ویژگی دیگر زیر را داشته باشد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(981, 'کدام مورد در ارتباط با نحوه تأمین انرژی انقباض توسط تارهای ماهیچه ای اسکلتی به درستی بیان شده است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(982, 'کدام گزینه در خصوص نوعی یاخته فعال جانوری، نادرست است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(983, 'نوعی از روش های تأمین انرژی در یاخته های یوکاریوتی که در بیش از دو واکنش آن، ترکیبات سه کربنی، بدون تغییر در تعداد اتم های کربن خود به ترکیبات دیگری تبدیل می شوند، چه مشخصه ای دارد؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(984, 'چند مورد، معرف نوعی واکنش اکسایشی در جانداران است؟ تبدیل پیرووات به لاکتات در ماده زمینه سیتوپلاسم سیانوباکتری تبدیل پیرووات به بنیان استیل در یاخته های شش ریشه درختان حرا تبدیل قند فسفاته به اسید دوفسفاته در سیتوپلاسم گویچه قرمز انسان تبدیل رادیکال آزاد اکسیژن به مولکول اکسیژن طی واکنش با کاروتنوئیدها در کبد انسان', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(985, 'گلوکز جذب شده از لوله گوارش انسان درون یاخته ها می تواند در حضور ماده (های) دیگری، تجزیه شود و در تأمین انرژی مورد نیاز بدن مؤثر باشد. کدام مورد، درباره هر ماده ای که در مجموعه این واکنش های تأمین کننده انرژی، به عنوان &laquo;پذیرندۀ نهایی الکترون&raquo; شناخته می شود، صادق است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(986, 'مطابق با اطلاعات کتاب درسی مواد سمی از جمله سیانید و مونواکسید کربن وجود دارند که سبب توقف تنفس یاخته ای و مرگ یاخته می شوند، چند مورد ویژگی مشترک این مواد را نشان می دهد؟ فقط با قرار گرفتن در جایگاه فعال نوعی آنزیم، در انجام تنفس یاخته ای اختلال ایجاد می کنند. به طور حتم در یک یا تعدادی از واکنش های تنفس هوازی اختلال ایجاد می کنند. می توانند واکنش مربوط به انتقال الکترون ها به مولکول \\(O_2\\) را مهار کنند. نتیجه نهایی عملکرد آنها می تواند مانع از ساخت اکسایشی مولکول های \\(ATP\\) شود.', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(987, 'مواد زائد دفعی حاصل از یاخته های هسته دار انسان می تواند با دخالت گروهی از یاخته های گردیزه (نفرون) از خون به مجاری ادراری راه یابند و از بدن دفع شوند. کدام ویژگی درباره همه این یاخته ها صادق است؟', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, NULL, NULL, 'free'),
(988, 'به ترتیب هر یک از عبارات زیر مربوط به کدام قسمت جدول است؟ (بهترین گزینه را انتخاب کنید) عدم استفاده از انرژی ذخیره شده در مولکول NADH برای تولید ATP شکست پیوند کربن - کربن و آزادسازی مولکول کربن دی اکسید از آن توقف واکنش انتقال الکترون ها به گیرنده نهایی آن در حضور سیانید مبادله الکترون آن با نوعی ترکیب دونوکلئوتیدی', 3, 4, 32, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:16:33', 5, 'done'),
(989, 'کدام گزینه، متن زیر را به طور نامناسب کامل می کند؟ &laquo;طی مراحل تنفس در یاخته عصبی انسان، به ازای تجزیه یک مولکول گلوکز، از مرحله تغییر مولکول قند سه کربنی فسفاته تا تشکیل ترکیب شش کربنی و آزاد شدن کوآنزیم \\(A\\) در چرخه کربس، به ترتیب از راست به چپ، دو مولکول ............. مصرف و دو مولکول ................ تولید می شود.&raquo;', 3, 4, 32, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:16:38', 5, 'done'),
(990, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در یک فرد سالم، هنگام هر نوع روش تأمین \\(ATP\\) در .................، به دنبال افزایش .............. در یاخته، ............... می شود.&raquo;', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:15:45', 5, 'done'),
(991, 'در غشای چین خورده میتوکندری، پروتئین (های) سراسری وجود دارند که الکترون های جدا شده از انواع مختلف حامل های الکترونی را از خود عبور می دهند. چند مورد، فقط در مورد یکی از آنها درست است؟ الف) در اکسایش \\(FADH_2\\) برخلاف \\(NADH\\) نقش دارد. ب) آخرین پذیرنده الکترون در تنفس یاخته ای محسوب می شود. ج) در تأمین شیب پروتونی لازم برای فعالیت آنزیم \\(ATP\\) ساز نقش دارد. د) الکترون ها را به مولکولی انتقال می دهد که توانایی پمپ \\(H^+\\) را ندارد.', 3, 4, 32, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:15:25', 5, 'done'),
(992, 'مرحله ای از واکنش های تنفس یاخته ای هوازی ماهیچه های قلبی انسان در ماده زمینه ای سیتوپلاسم انجام می شود. با درنظر گرفتن این مرحله، کدام گزینه نسبت به سایرین زودتر رخ می دهد؟', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:15:08', 5, 'done'),
(993, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;در انسان، .............. مولکول های رادیکال آزاد تولید شده در پی ترکیب اکسیژن با الکترون(ها) درون راکیزه (میتوکندری)، به طور حتم .............. .&raquo;', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:14:59', 5, 'done'),
(994, 'مطابق اطلاعات کتاب درسی، کدام مورد نادرست است؟', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:14:51', 5, 'done'),
(995, 'در یک یاخته گیاهی، کدام ویژگی، اندامک تولید کننده \\(ATP\\) به روش نوری را از اندامک سازنده این مولکول به روش اکسایشی، متمایز می سازد؟', 3, 4, 33, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:14:39', 5, 'done'),
(996, 'کدام گزینه با در نظر گرفتن نمودار کتاب درسی در خصوص طیف جذبی رنگیزههای فتوسنتزی نادرست است؟ &laquo; در حد فاصل طول موج .............. میزان جذب ............... است.&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:14:25', 5, 'done'),
(997, 'چند مورد از موارد زیر، می تواند سبب کاهش میزان فتوسنتز در گیاهان نهان دانه علفی C3 شود؟ الف: افزایش میزان مولکول اکسیژن در برگ ب: افزایش هورمون آبسیزیک اسید در برگ ج: کاهش میزان کربن دی اکسید درون کلروپلاست د: کاهش نور دریافتی توسط آنتن های گیرنده نور سبزدیسه', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:14:12', 5, 'done'),
(998, 'مطابق اطلاعات کتاب درسی، در یک گیاه نهان دانه کدام ویژگی، انواع مختلف سامانه های تبدیل انرژی (فتوسیستم) موجود در غشای یک تیلاکوئید را از یکدیگر متمایز می سازد؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:14:04', 5, 'done'),
(999, 'طبق شکل های کتاب درسی، کدام یک از موارد زیر ویژگی مشترک پروتئین های غشایی را که در اندامک های دو غشایی یاخته های میانبرگ گل رز به تولید ATP می پردازند، بیان می کند؟ الف: بخش حجیم تر آنها، در بین فسفولیپیدهای نوعی غشای زیستی قرار دارد. ب: بر فشار اسمزی محل قرارگیری مولکول(های) دنای حلقوی، مؤثر هستند. ج: جایگاه فعال مربوط به مولکول ADP، در درونی ترین فضای محصور شده با غشا قرار گرفته است. د: یون های \\(H^+\\) را با انتشار تسهیل شده، به محل قرارگیری رناتن ها وارد می کنند.', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:13:55', 5, 'done'),
(1000, 'مطابق با مطالب کتاب درسی، در &laquo;یاخته های غلاف آوندی برگ گیاه ذرت، نوعی ترکیب شیمیایی دارای نوکلئوتید، با دریافت الکترون های برانگیخته در فضای بستره سبزدیسه، کاهش می یابد&raquo;؛ کدام عبارت دربارۀ این ترکیب نادرست است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:13:35', 5, 'done'),
(1001, 'در خصوص واکنش های مستقل از نور فتوسنتز در گیاه نهان دانه \\(C_3\\)، کدام مورد غیرممکن است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:13:25', 5, 'done'),
(1002, 'کدام مورد، در خصوص همه جانداران تولید کننده مطرح شده در کتاب درسی صحیح است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:13:15', 5, 'done'),
(1003, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;با توجه به واکنش های وابسته به نور در غشای تیلاکوئید کلروپلاست های پارانشیم برگ لوبیا، هر جزئی که ................ .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:13:04', 5, 'done'),
(1004, 'در شرایطی که دمای بالا و شدت نور زیاد در محیط زندگی گل رز وجود دارد. فرایندی در یاخته های فتوسنتز کننده رخ می دهد که از عمل کربوکسیلازی روبیسکو ممانعت می کند. چند مورد در خصوص این فرایند، درست است؟ الف: همانند تخمیر لاکتیکی، با مصرف شدن مولکول های کربن دار دوفسفاته همراه خواهد بود. ب: همانند چرخه کربس، در طی آن نوعی ترکیب پنج کربنی تولید شده و پیوند میان برخی کربن های آن شکسته می شود. ج: همانند تخمیر الکلی، با تولید نوعی مولکول دوکربنی همراه است که پیش ماده آنزیمی در خارج از میتوکندری می باشد. د: همانند چرخۀ کالوین، ترکیب ناپایداری تولید می کند که مولکول سه کربنی لازم برای بازسازی ریبولوز بیس فسفات را خواهد ساخت.', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:12:38', 5, 'done'),
(1005, 'در کدام گزینه، هر دو ویژگی را می توان فقط به یکی از انواع گیاهان (مطرح شده در کتاب درسی) با توانایی فتوسنتز در شرایط دشوار، نسبت داد؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:11:44', 5, 'done'),
(1006, 'با توجه به فرایندهای سوخت وسازی یاخته در گیاهان، کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;مطابق توضیحات کتاب زیست شناسی 3 ، همۀ گیاهانی که می توانند کربن دی اکسید جو را ابتدا به صورت ترکیبی چهار کربنی در یاخته های میانبرگ خود تثبیت نمایند، ................ .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:12:27', 5, 'done'),
(1007, 'در خصوص فرایندهای مرحله مستقل از نور فتوسنتز که در میانبرگ اسفنجی فعال گیاه گل رز می تواند رخ دهد، کدام مورد نادرست است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:12:07', 5, 'done'),
(1008, 'مطابق با شکل زیر، چند مورد در خصوص هر ماده اسیدی سه کربنه که طی تثبیت کربن، در کلروپلاست یاخته مورد نظر تولید می گردد. صحیح است؟ الف: تولید آن فقط در طول روز قابل انتظار است. ب: ابتدا با دریافت الکترونهای \\(NADPH\\) ،کاهش می یابد. ج: نمی تواند در آینده، در جایگاه فعال آنزیم تثبیت کننده \\(CO_2\\) قرار گیرد. د: در پی اتصال \\(2CO_2\\) به نوعی ترکیب شیمیایی توسط روبیسکو حاصل شده است.', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:11:33', 5, 'done'),
(1009, 'کدام مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;در گیاهان نهان دانه ای که تثبیت کربن در آنها فقط با چرخۀ کالوین انجام می شود و اولین ماده آلی پایدار ساخته شده طی تثبیت کربن، ترکیبی سه کربنی است؛ در طی واکنش های تثبیت کربن .............، به طور حتم ................... .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:11:54', 5, 'done'),
(1010, 'در خصوص مقایسه اندام های گیاهان نهان دانۀ تک لپه و دولپه، کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟ &laquo;مطابق اطلاعات کتاب درسی، آن دسته از گیاهانی که می توانند ............ داشته باشند، در ساختار برگ آن ها ............... .&raquo;', 1, 4, 17, 39, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:11:19', 5, 'done'),
(1011, 'درستی و نادرستی هر یک از گزاره ها برای تکمیل عبارت زیر به ترتیب کدام است؟ &laquo;مطابق اطلاعات کتاب درسی، فقط برخی از جانداران تک یاخته ای تولید کننده مواد آلی از مواد معدنی که در غشای یاخته ای اطراف خود ................. رنگیزه های جذب کننده نور می باشند، ................. .&raquo; الف: فاقد ـ قادر به تثبیت کربن دی اکسید به صورت ترکیبات آلی کربن دار هستند ب: واجد ـ الکترون های برخی ترکیبات نوکلئوتیدی را به نوعی ماده آلی یا معدنی منتقل می کنند ج: فاقد ـ انرژی مورد نیاز برای ساختن مواد آلی از مواد معدنی را از واکنش های اکسایش به دست می آورند د: واجد ـ با مصرف نوعی مولکول شش کربنی در غیاب اکسیژن، ترکیب (های) سه کربنی مختلفی تولید می کنند', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:10:59', 5, 'done'),
(1012, 'مطابق اطلاعات کتاب درسی در یک یاخته غلاف آوندی در گیاه ذرت، تبدیل یک ترکیب سه کربنی به نوعی ترکیب آلی دیگر، با اکسایش مولکول حامل الکترون همراه است. کدام مورد، در خصوص این واکنش به طور حتم صادق است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:10:47', 5, 'done'),
(1013, 'با توجه به اطلاعات کتاب درسی، مهندسی ژنتیک از چهار مرحله کلی تشکیل شده است. ویژگی مشترک اولین و دومین مرحله، کدام است؟', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:10:30', 5, 'done'),
(1014, 'با توجه به مراحل ژن درمانی مطرح شده در کتاب درسی، در چهارمین مرحله، کدام مورد انجام می شود؟', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:10:18', 5, 'done'),
(1015, 'شکل مقابل، مربوط به یکی از فرایندهای انجام شده در مهندسی ژنتیک مطرح شده در کتاب درسی است. کدام مورد پس از رویداد نشان داده شده در شکل به وقوع می پیوندد؟ (روش جداسازی یاخته های تراژنی استفاده از پادزیست است.)', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:09:59', 5, 'done'),
(1016, 'یکی از کاربردهای زیست فناوری در سال های اخیر، تهیه واکسن علیه بیماری ویروسی بوده است. با توجه به اطلاعات کتاب درسی، چند مورد در خصوص این دستاورد(ها) صحیح است؟ الف: بررسی ساختار سه بعدی پروتئین های ویروسی فقط با روش های بیوانفورماتیک امکان پذیر است. ب: روش های بیوانفورماتیک شناسایی بخشی از ژنوم عامل بیماری زا را که مربوط به ساخته شدن آنتی ژن های سطحی است، تسهیل می کند. ج: بخشی از ژنوم ویروس را که در ساخت مولکول های اختصاصی آن نقش دارد، می توان به یاخته ای با توانایی همانندسازی و رونویسی منتقل کرد. د: با استفاده از نوعی از این دستاوردها، می توان عملکرد متنوع ترین گروه مولکول های زیستی را با مطالعه ژنوم عامل بیماری زا به دست آورد.', 3, 4, 34, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:09:46', 5, 'done'),
(1017, 'در یک ماهیچه اسکلتی، انواعی از فرایندهای مؤثر در تولید \\(ATP \\)، می توانند منجر به تولید محصولات اسیدی شوند. در خصوص این فرایندها، کدام عبارت به درستی بیان شده است؟', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:09:18', 5, 'done'),
(1018, 'طی تلاش هایی که در سال ۱۹۸۳ به منظور تولید هورمون انسولین فعال به روش مهندسی ژنتیک، برای اولین بار صورت گرفت، مرحله ای که در آن ...................... شد، بلافاصله ................. مرحله ای انجام شد که در آن ....................... صورت گرفت.', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:09:08', 5, 'done'),
(1019, 'مطابق با اطلاعات کتاب درسی در یک یاخته میانبرگ گیاه لوبیا، انواعی از مولکول های حامل با از دست دادن \\(2e^-\\) و\\(2H^+\\) در نوعی اندامک دوغشایی، اکسایش می یابند. ویژگی مشترک همه انواع این مولکول ها کدام مورد زیر است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:08:54', 5, 'done'),
(1020, 'با توجه به واکنش های ساخته شدن قند از ماده معدنی در چرخه ای از واکنش های آنزیمی در گیاه گل رز، کدام گزینه زیر درست است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:08:39', 5, 'done'),
(1021, 'مطابق اطلاعات کتاب درسی، در خصوص دوره های زیست فناوری، چند مورد نادرست است؟ الف: در دوره زیست فناوری کلاسیک برخلاف سنتی، از فرایندهای مستقل از اکسیژن برای تولید محصول استفاده شد. ب: در دوره زیست فناوری نوین برخلاف کلاسیک، امکان تولید مواد دارویی به کمک برخی ریز جانداران فراهم گردید. ج: در دوره زیست فناوری نوین همانند کلاسیک، امکان تکثیر ریز جانداران در محیط کشت مناسب وجود دارد. د: در دوره زیست فناوری کلاسیک همانند نوین، عواملی برای کاهش انرژی فعال سازی واکنش ها تولید شدند.', 3, 4, 34, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:08:26', 5, 'done'),
(1022, 'کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟ &laquo;در زنجیره های انتقال الکترون در غشای تیلاکوئید نوعی یاخته پارانشیمی، یکی از ناقل های الکترونی که ............. است، با .................. نقش دارد.&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:08:10', 5, 'done'),
(1023, 'نوعی روش تأمین کننده ATP در جانداران تک یاخته ای و پریاخته ای با مصرف نوعی قند آغاز می شود. این روش نمی تواند به ایجاد رادیکال های آزاد اکسیژن ختم شود. کدام مورد، ویژگی مشترک همه انواع این روش را نشان می دهد؟', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:07:56', 5, 'done'),
(1024, 'کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟ &laquo;در درون ساختار راکیزه (میتوکندری) های یاخته های پیکری انسان، یکی از دلایل .... است.&raquo;', 3, 4, 32, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:07:45', 5, 'done'),
(1025, 'برای تکمیل عبارت زیر کدام گزینه نامناسب است؟ &laquo;برگ گیاهان نهان دانه ساختاری تخصص یافته برای فتوسنتز است. براساس اطلاعات کتاب درسی، در همۀ گیاهان نهان دانه ای که ................. به طور حتم، .................. .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:07:24', 5, 'done'),
(1026, 'در خصوص فرایند فتوسنتز در یاخته های کلروپلاست دار گیاه ادریسی، کدام مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;در واکنش های وابسته به نور ................. واکنش های مستقل از نور، ................. .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:05:48', 5, 'done'),
(1027, 'چند مورد، برای تکمیل عبارت زیر مناسب است؟ &laquo;در یاخته های میانبرگ گیاه آناناس، ممکن است نوعی ماده تولید شده در ................ .&raquo; الف: چرخه کالوین، به عنوان پذیرنده نهایی در زنجیره انتقال الکترون غشای تیلاکوئید دچار اکسایش شود ب: واکنش های وابسته به نور، به عنوان پذیرنده نهایی الکترون طی فرایند مؤثر در ساخت اکسایشی انرژی زیستی استفاده شود ج: چرخۀ کالوین، به دنبال ورود یون های هیدروژن به بخش داخلی راکیزه (میتوکندری) به عنوان پیش ماده مصرف شود د: اکسایش پیرووات، به منظور تولید قندهای سه کربنی در بستره سبزدیسه (کلروپلاست) دچار اکسایش شود', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:05:35', 5, 'done'),
(1028, 'مطابق با کتاب درسی، در خصوص پروتئین های مطرح شده در فصل ۷ زیست دوازدهم که به کمک مهندسی پروتئین میزان پایداری آنها تغییر کرده است، کدام مورد صحیح است؟ &laquo;یکی از این پروتئین ها که ................ نقش دارد، ..................... .&raquo;', 3, 4, 34, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:29', 1, '2026-02-11 21:05:21', 5, 'done'),
(1029, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;متخصصان مهندسی بافت در زمینه تولید اعضا از منابع یاخته ای استفاده می کنند که در محیط کشت سریع تکثیر می شوند. نوعی از این منابع که .................... بعد از جداسازی و کشت ................. .&raquo;', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:05:08', 5, 'done'),
(1030, 'در ارتباط با اجزای غشاهای راکیزه و کلروپلاست (مطرح شده در کتاب درسی) موجود در یاخته غلاف آوندی گیاه ذرت، کدام مورد درست است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:04:53', 5, 'done'),
(1031, 'با فرض وجود دما و نور زیاد در اطراف گیاه گل رز، در خصوص یاخته های میانبرگ فتوسنتز کننده، کدام موارد برای تکمیل عبارت زیر مناسب است؟ &laquo;در هر نوع تنفس که در حضور مقادیر بالای اکسیژن، موجب کاهش میزان فرآورده های آلی فتوسنتز می شود، ................ .&raquo; الف: تعداد گروه فسفات در نوعی نوکلئوتید افزایش می یابد ب: نوعی ترکیب آلی دارای دو اتم کربن تولید و مصرف خواهد شد ج: تولید کربن دی اکسید در اندامکی دوغشایی و فاقد کلروفیل رخ می دهد د: مصرف نوعی ترکیب آلی پنج کربنه در اندامک سیتوپلاسمی صورت می گیرد', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:04:42', 5, 'done'),
(1032, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول هر نوع باکتری زنده و فعالی که ..................... .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:04:12', 5, 'done'),
(1033, 'براساس مطلب کتاب درسی، کدام عبارت در خصوص برگ گیاه خرزهره نادرست است؟', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:04:01', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(1034, 'در کتاب درسی، تعدادی از دستاوردهای زیست فناوری در حوزه کشاورزی آمده است. در این خصوص کدام مورد(ها)، عبارت زیر را به طور مناسب کامل می کند؟ &laquo;به منظور ................ ضروری است که .................. .&raquo; الف: تولید پنبه مقاوم به آفت - ایمنی زیستی آن به طور دقیق بررسی شود ب: تولید گیاهان مقاوم به خشکی و شوری - ژن یا ژن هایی خاص از نوعی دنا جدا شود ج: تنظیم سرعت رسیدن میوه ها &ndash; ژن های مربوط به تولید اتیلن یا گیرنده آن بررسی شود د: اصلاح بذر برای تولید گیاهان مطلوب - نوعی محتوای ژنی متفاوت به یاخته گیاهی منتقل شود', 3, 4, 34, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:03:16', 5, 'done'),
(1035, 'واکنش های تثبیت کربن در یک یاخته فتوسنتز کننده در برگ گیاه لوبیا، چه مشخصه ای دارند؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:02:58', 5, 'done'),
(1036, 'چند مورد برای تکمیل عبارت مقابل مناسب است؟ &laquo;مطابق کتاب درسی ............... گیاهانی که در آنها ................ .&raquo; الف: در همه - روبیسکو هنگام بسته بودن روزنه هوایی می تواند فعالیت خود را ادامه دهد، سازوکاری برای کاهش انجام تنفس نوری وجود دارد ب: فقط در بعضی از \\(CO_2\\) ابتدا به صورت مولکول چهار کربنه تثبیت می شود، تولید و مصرف ترکیب(های) چهار کربنی در یاخته های میانبرگ قابل انتظار است ج: در همه ـ یاخته های نگهبان روزنه در طول روز دچار تورژسانس می شوند، هر مولکول \\(CO_2\\) تولید شده در روز، در نوعی اندامک دوغشایی تولید شده است د: فقط در بعضی از - مصرف ریبولوز بیس فسفات در همه یاخته های کلروپلاست دار انجام می گیرد، هر اسید سه کربنه تولید شده طی روز در چرخۀ کالوین کلروپلاست مصرف می شود', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:02:19', 5, 'done'),
(1037, 'در محدوده آبی تا نارنجی نور مرئی، همه رنگیزه هایی که قادرند در محدوده طول موجی که یک گیاه کم ترین میزان اکسیژن را در آن تولید می کند، جذب نور داشته باشند، به طور حتم .................. .', 3, 4, 33, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:01:58', 5, 'done'),
(1038, 'مطابق اطلاعات کتاب درسی، دو نوع کاتالیزور زیستی می توانند با قرارگیری در بخشی از ساختار غشای اندامک های حاوی دنای حلقوی آدنوزین تری فسفات را بسازند. کدام مورد می تواند این آنزیم ها را از یکدیگر متمایز سازد؟', 3, 4, 33, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:01:44', 5, 'done'),
(1039, 'با توجه به فعالیت های آنزیم روبیسکو در یک یاخته میانبرگ، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در واکنش های چرخۀ کالوین ................. تنفس نوری، ................. .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:01:21', 5, 'done'),
(1040, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول .............. ساختارهایی که می توانند در فرایند مهندسی ژنتیک، به عنوان ناقل، قطعه ای از دنای مورد نظر را به یاخته یوکاریوتی میزبان منتقل کنند، ................ .&raquo;', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:01:06', 5, 'done'),
(1041, 'براساس مطلب کتاب درسی، چند مورد فقط در خصوص بعضی از انواع چرخه های آنزیمی انجام شده در یاخته میانبرگ نرده ای گیاه لوبیا صادق است که در یک ساختار دوغشایی دارای دنا، در شرایط مساعد محیطی انجام می شوند؟ الف: با تجزیه پیوند بین دو کربن، در یک ترکیب آلی شش کربنی همراه است. ب: مولکول های سه کربنی برای بازسازی ترکیب آلی ابتدایی چرخه به مصرف می رسند. ج: مصرف نوعی مولکول پنج کربنی فاقد فسفات، فقط با تولید ماده ای با اتم های کربن بیشتر همراه است. د: مولکول های حامل الکترون طی آزادسازی یون(های) هیدروژن، سبب کاهش یافتن برخی مولکول های آلی می شوند.', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:00:49', 5, 'done'),
(1042, 'مطابق مطالب کتاب درسی، ویژگی مشترک جاندارانی که یاخته هایی دارند که ضمن انجام فعالیت های سوخت و سازی خود، با مصرف مولکول کربن دی اکسید می توانند نوعی ماده آلی را تولید کنند، کدام است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:00:27', 5, 'done'),
(1043, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ &laquo;به طور معمول، ................ زنجیره های انتقال الکترون که در بخش مشخص شده در شکل، قابل مشاهده اند، ................. .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 21:06:35', 5, 'done'),
(1044, 'همه موارد ذکر شده ویژگی مشترک واکنش هایی هستند که میزان انرژی فعال سازی آنها در بستره کلروپلاست می تواند توسط روبیسکو کاهش یابد؛ به جز ................ .', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:59:30', 5, 'done'),
(1045, 'چند مورد برای تکمیل عبارت زیر مناسب است؟ &laquo;طبق مطلب کتاب درسی، نوعی آنزیم پروتئینی برش دهنده مورد استفاده در مهندسی ژنتیک که جایگاه تشخیص آن هشت پیوند فسفو دی استر در ساختار خود دارد، ............. .&raquo; الف: می تواند هنگام تبدیل دیسک باکتری به یک قطعه دنای خطی، پیوندهای هیدروژنی را تجزیه کند ب: نمیت واند دارای بیش از ۲۵ حلقه آلی کربن دار در توالی دنای قرار گرفته در جایگاه تشخیص اختصاصی خود باشد ج: می تواند توالی تک رشته ای را پدید آورد که طی شرایطی، به کمک آنزیم لیگاز، به انتهای چسبنده دیگری متصل شود د: نمی تواند دقیقاً نیمی از تعداد نوکلئوتیدهای جایگاه تشخیص را در انتهای چسبنده حاصل از فعالیت خود جای دهد', 3, 4, 34, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:59:11', 5, 'done'),
(1046, 'مطابق اطلاعات کتاب درسی و در خصوص یک یاخته نگهبان روزنه، کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول فقط در گروهی از فرایندهای درون یاخته ای که در طی آنها، تعداد الکترون های نوعی مولکول سه کربنی، طی واکنش های اکسایش و کاهش دچار تغییر می شود، .............. .&raquo;', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:58:36', 5, 'done'),
(1047, 'مطابق فعالیت کتاب درسی و در خصوص جانداران شرکت کننده در آزمایش تأثیر طول موج های مختلف نور بر فتوسنتز، کدام مورد درست است؟', 3, 4, 33, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:58:09', 5, 'done'),
(1048, 'در خصوص عوامل برهم زننده تعادل در یک جمعیت، کدام مورد زیر صحیح است؟', 3, 4, 31, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:57:46', 5, 'done'),
(1049, 'با توجه به فرایندهای مطرح شده در فصل ۷ زیست شناسی دوازدهم، اتفاقی که در مرحله نهایی از &laquo;مراحل ساخت انسولین توسط مهندسی ژنتیک&raquo; و &laquo;مراحل ژن درمانی&raquo; رخ می دهد، به ترتیب در کدام گزینه زیر آمده است؟', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:57:30', 5, 'done'),
(1050, 'در فرایند ترجمه، نوعی رنا می تواند آمینواسید را به سمت رناتن جابه جا کند. کدام گزینه ویژگی این نوع از رنا (RNA) را به درستی بیان کرده است؟', 3, 4, 29, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:52:18', 5, 'done'),
(1051, 'کدام مورد، دربارۀ همۀ یاخته های خونی با توانایی تراگذری (دیاپدز)، صادق است؟', 2, 4, 23, 91, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:51:37', 5, 'done'),
(1052, 'چند مورد، درباره هر نوع ترکیب شیمیایی موجود در بزاق انسان که &laquo;از پیوند میان آمینواسیدها به وجود می آید و می تواند جایگاه فعالی برای اتصال نوعی مادۀ دیگر داشته باشد. درست است؟ الف: در واکنش تبدیل مولکول های درشت به تکپارهای سازنده آن، دست نخورده باقی می ماند. ب: پس از ترشح، از طریق مجرا یا مجراهایی به فضای درون حفره دهانی تخلیه می شود. ج: می تواند تحت تأثیر پیام های عصبی شبکه های عصبی روده ای ترشح گردد. د: آسیاب شدن غذا به ذره های بسیار کوچک برای فعالیت بهتر آن لازم است.', 1, 4, 13, 9, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:46:50', 5, 'done'),
(1053, 'کدام مورد، در خصوص فرایندهای تأمین انرژی از مولکول های گلوکز در یک تار ماهیچه ای ذوزنقه ای، نادرست است؟', 3, 4, 32, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:45:52', 5, 'done'),
(1054, 'مطابق با اطلاعات کتاب درسی، چند مورد در خصوص هر اندام متعلق به دستگاه لنفی انسان بالغ صحیح است که در دوران جنینی، می تواند یاخته های خونی و گرده (پلاکت)ها را بسازد؟ الف: همانند اندام سازنده لیپوپروتئین ها، به نوعی بر میزان آهن خون تاثیرگذار است. ب: یاخته هایی تمایز نیافته با توانایی تقسیم و تولید چندین نوع یاخته پیکری را دارد. ج: لنف خارج شده از آن، فقط از طریق مجرای لنفی چپ به سیاهرگ زیرترقوه ای می ریزد. د: یاخته های تغییر شکل یافته بافت پیوندی خون در آن، در مبارزه با ویروس ها نقش دارند.', 1, 4, 15, 21, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:45:32', 5, 'done'),
(1055, 'مطابق اطلاعات کتاب درسی، گروهی از جانداران فتوسنتز کننده در مناطقی زندگی می کنند که از نظر نیتروژن فقیر هستند. مشخصه مشترک این جانداران کدام است؟', 1, 4, 18, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:44:35', 5, 'done'),
(1056, 'با توجه به انواع جهش های غیر بزرگ، چند مورد به درستی بیان شده است؟ الف: هر جهشی که با کاهش طول رنای پیک همراه است، لزوماً به دنبال حذف نوکلئوتید(هایی) در دنا رخ داده است. ب: هر جهشی که مانع حرکت نوعی آنزیم بسپار از بر روی توالی دنا می شود، توالی نوکلئوتیدی دنا را تغییر داده است. ج: هر جهشی که موجب عدم ترجمه یک رنای پیک می شود، به دنبال تغییر در رمز مربوط به آمینواسید متیونین رخ داده است. د: هر جهشی که با تغییر نوکلئوتیدهای مربوط به کدون پایان همراه است، طول رنای پیک حاصل از رونویسی را تغییر می دهد.', 3, 4, 31, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:38:15', 5, 'done'),
(1057, 'در خصوص انواع مختلف تنظیم بیان ژن در پروکاریوت ها (مطرح شده در کتاب درسی)، کدام مورد درست است؟', 3, 4, 29, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:37:22', 5, 'done'),
(1058, 'کدام مورد برای تکمیل عبارت زیر نامناسب است؟ &laquo;به طور معمول .......................، مولکول اینترفرون تولید شده با .............. را از اینترفرون تولیدشده با ..................، متمایز می سازد.&raquo;', 3, 4, 34, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:36:54', 5, 'done'),
(1059, 'کدام مورد، عبارت زیر را به طور مناسب تکمیل می کند؟ &laquo;به طور طبیعی در بدن انسان، در ساختار مولکول انسولین همانند مولکول .................... .&raquo;', 1, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-10 16:10:57', 2, 'done'),
(1060, 'با توجه به اطلاعات کتاب درسی، چند مورد در خصوص هر کاتالیزور زیستی موجود در هسته اوگلنا صحیح است که برای تولید نمودن نوعی رشته پلی نوکلئوتیدی، تنها از روی بخشی از یک رشته مولکول دنا (DNA) الگوبرداری می کند؟ الف: مولکولی را می سازد که به رشته الگو متصل باقی می ماند. ب: در ساختار واحدهای تکرارشونده خود دارای نوعی قند پنج کربنه است. ج: ابتدا پیوندهای هیدروژنی را در بخش کوچکی از مولکول دنا (DNA) می شکند. د: ضمن ساخته شدن، ابتدا انتهای آمینی آن وارد فضای داخلی شبکه آندوپلاسمی می شود.', 3, 4, 29, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:36:07', 5, 'done'),
(1061, 'مطابق گیاهان مطرح شده در فصل ششم زیست شناسی 3 ، کدام ویژگی می تواند انواع مختلف گیاهان با توانایی فتوسنتز کافی در شرایط دشوار را از یکدیگر متمایز سازد؟', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:26:45', 5, 'done'),
(1062, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟ &laquo;در هر مرحله ای از فرایند ترجمه یک رنای پیک تک ژنی که ................. .&raquo;', NULL, 4, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-10 16:20:31', 2, 'done'),
(1063, 'کربن دی اکسید حاصل از تثبیت اولیه کربن در یاخته های میانبرگ، می تواند با محصول چرخه ای از واکنش ها ترکیب شود و در تولید قند مورد نیاز گیاه در نوعی یاخته مؤثر باشد. کدام ویژگی فقط درباره بعضی از این یاخته ها صادق است؟', 1, 3, NULL, NULL, 2, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, NULL, NULL, 'free'),
(1064, 'مطابق با اطلاعات کتاب درسی، در یک یاخته فعال پارانشیمی، در انواعی از زنجیره های انتقال الکترون، از انرژی الکترون های پرانرژی برای پمپ کردن پروتون ها استفاده می شود. ویژگی مشترک این زنجیره ها کدام یک از موارد زیر است؟ الف: آخرین عضو زنجیره، در تماس با سرهای آب دوست هر دو لایه فسفولیپیدی غشا است. ب: نخستین عضو زنجیره، میزان pH دو سوی غشا را دستخوش تغییر قرار می دهد. ج: هر ترکیب انتقال دهنده الکترون، الکترون را به مولکولی نیتروژن دار انتقال می دهد. د: فقط برخی از اعضای زنجیره در سراسر عرض غشا استقرار یافته اند.', 3, 4, 33, NULL, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-11 20:26:02', 5, 'done'),
(1065, 'کدام گزینه جمله زیر را به درستی تکمیل می کند؟ &laquo;نوعی جاندار تثبیت کننده کربن دی اکسید جو که می تواند .............. .&raquo;', 1, 4, NULL, NULL, 2, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-05 17:20:30', 1, '2026-02-09 19:07:44', 7, 'done'),
(1066, 'یک جسم با جرم 2 کیلوگرم تحت تأثیر نیروی ثابت 6 نیوتن روی سطح بدون اصطکاک قرار دارد. اگر جسم در ابتدا ساکن باشد، تندی آن پس از 4 ثانیه چقدر است؟\r\n\r\n(فرمول: $ v = (F × t) / m $)', 1, 2, NULL, NULL, 1, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-07 19:15:09', 1, '2026-02-09 19:05:58', 5, 'done'),
(1067, '۱-  بر روی ۷ کارت، اعداد $\\{2,3,4,5,6,7,8\\}$ نوشته شده است و با ۳ تا از این ۷ کارت عدد سه رقمی می‌سازیم. احتمال اینکه این عدد بر ۳ بخش‌پذیر باشد، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:47:27', 6, 'done'),
(1068, ' از جعبه‌ای که در آن ۵ سیب قرمز سالم، ۴ سیب زرد سالم و یک سیب ناسالم وجود دارد، سه سیب به تصادف برمی‌داریم. چقدر احتمال دارد که هم سیب قرمز سالم و هم زرد سالم برداریم؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:48:06', 6, 'done'),
(1069, ' اگر احتمال مبتلا نشدن به یک مریضی ۸۰ درصد باشد و به شرط ابتلا به آن مریضی، احتمال درمان آن ۶۰ درصد و به شرط ابتلا و درمان شدن، احتمال اینکه تا ده سال آینده دوباره به آن مریضی مبتلا شود ۷۵ درصد باشد، احتمال اینکه شخص به آن مریضی مبتلا و درمان شود و تا ده سال آینده به آن مریضی مبتلا نشود چند درصد است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:50:48', 6, 'done'),
(1070, '  احتمال این‌که در پرتاب دو تاس، تفاضل دو عدد رو شده ۲ یا ۳ باشد، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:49:38', 6, 'done'),
(1071, ' در یک جعبه ۸ سیب سالم و ۴ سیب فاسد قرار دارد. اگر به تصادف ۳ سیب از جعبه خارج کنیم، با کدام احتمال لااقل دو سیب خارج شده سالم است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:52:26', 6, 'done'),
(1072, '  از مجموعه اعداد $\\{1,2,3,...,50\\}$ به تصادف دو عدد انتخاب می‌شود. با کدام احتمال این دو عدد متوالی‌اند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:53:39', 6, 'done'),
(1073, '  از پنج دانش‌آموز انتخابی، با کدام احتمال، ماه تولد حداقل دو نفر آنان یکسان است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:53:16', 6, 'done'),
(1074, '  احتمال قبولی فردی در یک آزمون نظری 8/0 و در یک آزمون عملی 7/0 است. با کدام احتمال، لااقل در یکی از این دو آزمون قبول می‌شود؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-21 13:54:20', 6, 'done'),
(1075, 'برای دو پیشامد $A$ و $B$ از یک فضای نمونه‌ای، کدام رابطه ممکن است نادرست باشد؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-25 13:32:56', 6, 'done'),
(1076, '  در یک کارخانه، درصد تولیدی با ماشین‌های $A$ و $B$ و $C$ به ترتیب ۳۰ و ۲۵ و ۴۵ می‌باشد. احتمال معیوب بودن کالای تولیدی به ترتیب ۳ و ۴ و ۲ درصد است اگر کالای انتخابی معیوب باشد با کدام احتمال محصول ماشین $A$ است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-25 13:33:46', 6, 'done'),
(1077, '  ارقام دو رقمی بر روی ۹۰ گوی مساوی نوشته شده و داخل ظرفی قرار دارند. به تصادف ۲ گوی بیرون می‌آوریم، با کدام احتمال مجموع این دو عدد زوج است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-25 13:34:11', 6, 'done'),
(1078, 'در پرتاب یک تاس اگر ۶ ظاهر نشود دوسکه پرتاب می‌کنیم با کدام احتمال لااقل یکی از سکه‌ها «رو» می‌آید؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:01:22', 2, 'done'),
(1079, ' دانش‌آموزی به ۵ پرسش ۵ گزینه‌ای به تصادف پاسخ می‌دهد. با کدام احتمال فقط به ۲ پرسش جواب صحیح داده است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:07:44', 2, 'done'),
(1080, 'احتمال این‌که یک تیم ورزشی اصلی‌ترین رقیب خود را ببرد $\\frac{1}{5}$ است. احتمال قهرمانی تیم $\\frac{1}{3}$، که در صورت برنده شدن بر اصلی‌ترین رقیب، احتمال قهرمانی آن به $\\frac{2}{5}$ افزایش پیدا می‌کند. احتمال پیروزی بر رقیب یا قهرمان شدن کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:07:36', 2, 'done'),
(1081, 'در پرتاب دو تاس، با کدام احتمال مجموع دو عدد رو شده مضرب ۳ است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:08:28', 2, 'done'),
(1082, ' در ریزش یک ساختمان، بنابر نظریه کارشناسی، ۵۰ درصد عدم نظارت، ۳۰ درصد سستی پی و ۲۰ درصد غیرایمنی دیوار بوده است بنابر تجربه‌های گذشته احتمالات این ۳ عامل به‌ترتیب 1/0 و 6/0و 3/0 می‌باشد. با کدام احتمال علت ریزش عدم نظارت بوده است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:08:37', 2, 'done'),
(1083, 'اگر $P(A \\cup B\') = \\%60$، $P(B \\cup A\') = \\%80$  و $ 3 P(A’)=5 P(B’) $  باشد، احتمال اینکه حداقل یکی از $A$ یا $B$ رخ دهد کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:04:21', 2, 'done'),
(1084, 'در ردیف سمت راست ۵ کتاب فیزیک و در ردیف سمت چپ ۳ کتاب ریاضی داریم که ۳ کتاب فیزیک و ۳ کتاب ریاضی کتاب درسی سه سال دوره دوم دبیرستان هستند. سه جفت کتاب (ریاضی - فیزیک) به تصادف درست می‌کنیم، چقدر احتمال دارد که کتاب‌های درسی سه سال دوره دوم را انتخاب کرده باشیم؟', 2, 1, 52, 224, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:08:51', 2, 'done'),
(1085, 'از بین ۵ مهره آبی، ۴ مهره قرمز و ۳ مهره سبز، ۳ مهره به تصادف خارج می‌کنیم. چقدر احتمال دارد که حداقل یک مهره آبی باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:07:27', 2, 'done'),
(1086, 'از بین اعداد ۳ رقمی، عددی به تصادف اختیار می‌کنیم. چقدر احتمال دارد که فقط بر یکی از اعداد ۳ یا ۷ بخش‌پذیر باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:08:13', 2, 'done'),
(1087, 'در کیسه اول ۴ مهره سفید و ۵ مهره سیاه و در کیسه دوم ۴ مهره سفید و ۲ مهره سیاه قرار دارد. از کیسه اول و دوم به تصادف ۳ و ۴ مهره برداشته و در کیسه دیگری قرار می‌دهیم. از کیسه آخر به تصادف مهره‌ای برمی‌داریم. چقدر احتمال دارد مهره سفید باشد؟', 3, 1, 53, 225, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:06:26', 2, 'done'),
(1088, 'دو پیشامد مستقل $A$ و $B$ به ترتیب ۳ و ۴ عضو دارند و اجتماع آن‌ها ۵ عضو دارد. با این شرایط، احتمال آن‌که نه $A$ و نه $B$ اتفاق بیفتند، چقدر است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:07:05', 2, 'done'),
(1089, ' اگر $A$ و $B$ دو پیشامد از فضای نمونه‌ای $S$ باشند و $A \\subseteq B$، چند مورد از موارد زیر الزاماً درست است؟\r\n\r\nالف)  $P(A) \\leq P(B)$\r\n\r\nب)  $P(A - B) = 0$\r\n\r\nج)  $P(B - A) \\neq 0$\r\n\r\nد)  $P(B - A) = P(B) - P(A)$\r\n\r\nه) $P(A \\cap B) = P(A)$\r\n\r\nو)  $P(A\') \\geq P(B\')$', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:09:22', 2, 'done'),
(1090, 'احتمال آن که علی در رشته پزشکی در کنکور ۹۹ قبول شود، سه برابر احتمال آن است که دوستش حسن قبول شود. اگر احتمال آن‌که حداقل یکی از آن‌ها در رشته پزشکی قبول شوند، برابر $\\frac{7}{12}$ باشد، حسن با چه احتمالی در این رشته قبول خواهد شد؟', 2, 1, 52, 223, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:11:27', 2, 'done'),
(1091, 'در کیسه‌ای ۳ مهره سفید، ۴ مهره آبی و ۵ مهره قرمز وجود دارد. ۶ مهره از این کیسه برمی‌داریم. چقدر احتمال دارد که حداقل ۲ مهره سفید باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:13:05', 2, 'done'),
(1092, 'در یک امتحان، اگر نسبت احتمال جواب درست دادن به جواب نادرست هر کدام از ۲ سؤال برابر ۳ باشد، چند درصد احتمال دارد که حداقل به یک سؤال امتحان دو سؤالی جواب درست دهیم؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:12:35', 2, 'done'),
(1093, '۳ پسر و ۴ دختر از بین ۴ کلاه پسرانه و ۶ کلاه دخترانه، هر کدام به تصادف یک کلاه برمی‌دارند. احتمال این‌که پسرها کلاه پسرانه و دخترها کلاه دخترانه انتخاب کرده باشند، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:13:32', 2, 'done'),
(1094, 'درون کیسه‌ای ۳ مهره آبی، ۴ مهره قرمز و ۵ مهره سیاه وجود دارد. از این کیسه سه مهره به تصادف خارج می‌کنیم. با کدام احتمال مهره‌های خارج شده فقط از دو رنگ متفاوت هستند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:13:54', 2, 'done'),
(1095, 'در پرتاب دو تاس، اگر تفاضل اعداد رو شده مضرب ۳ باشد، با کدام احتمال یکی از اعداد رو شده ۲ است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:15:05', 2, 'done'),
(1096, 'احتمال رخداد پیشامد $B$ سه برابر احتمال رخداد پیشامد $A$ و $P(A\') + P(A|B) = 1$ است. اگر احتمال آن که حداقل یکی از پیشامدهای $A$ و $B$ رخ دهد $\\frac{7}{12}$ باشد، احتمال رخداد پیشامد $B$ کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:15:34', 2, 'done'),
(1097, 'احتمال این که فردی مبتلا به ویروس کرونا باشد 02/0 است. آزمایش تشخیص بیماری برای ۹۷٪ افراد بیمار، مثبت می‌باشد ولی در ۵٪ موارد نیز نتیجه آزمایش افراد سالم، مثبت بوده است. اگر فردی به تصادف انتخاب شود با کدام احتمال نتیجه آزمایش او مثبت است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:16:06', 2, 'done'),
(1098, ' ۴ مرد و ۳ زن به تصادف در یک ردیف می‌نشینند. اگر هیچ دو زنی در کنار هم نباشند، با کدام احتمال، مردان و زنان یک در میان نشسته‌اند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:16:42', 2, 'done'),
(1099, ' دو تاس سیاه و سفید را پرتاب می‌کنیم. پیشامد آن که «عدد رو شده تاس سفید ۲ باشد» با کدام‌یک از پیشامدهای زیر مستقل است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:17:07', 2, 'done'),
(1100, 'دو ظرف یکسان داریم. ظرف اول شامل ۶ مهره سبز و ۴ مهره آبی و ظرف دوم شامل ۵ مهره سبز و تعدادی مهره آبی است. از ظرف اول یک مهره انتخاب کرده، در ظرف دوم قرار می‌دهیم. سپس یک مهره از ظرف دوم خارج می‌کنیم. اگر احتمال خارج شدن مهره سبز $\\frac{28}{65}$ باشد، در ظرف دوم در ابتدا چند مهره وجود دارد؟', 3, 1, 53, 225, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:17:39', 2, 'done'),
(1101, 'احتمال این که رضا یک مسأله ریاضی را حل کند، سه برابر دوست وی است. احتمال این که مسأله توسط رضا یا دوستش حل شود $\\frac{20}{27}$ می‌باشد. با کدام احتمال هر دو نفر مسأله را حل می‌کنند؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:18:10', 2, 'done'),
(1102, 'در جعبه اول ۸ لامپ سالم و ۴ لامپ معیوب، در جعبه دوم ۶ لامپ سالم و ۲ لامپ معیوب و در جعبه سوم ۴ لامپ سالم و ۲ لامپ معیوب قرار دارد. به تصادف از جعبه اول ۴ لامپ و از جعبه دوم ۶ لامپ بیرون آورده و در جعبه سوم می‌ریزیم. سپس یک لامپ به تصادف از جعبه سوم خارج می‌کنیم. با چه احتمالی لامپ خارج شده از جعبه سوم معیوب است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:18:35', 2, 'done'),
(1103, 'در جعبه‌ای $n$ مهره سفید و $(n-2)$ مهره زرد وجود دارد. دو مهره به تصادف از جعبه خارج می‌کنیم. اگر احتمال هم‌رنگ بودن مهره‌ها برابر $\\frac{1}{2}$ باشد، تعداد مهره‌های داخل جعبه کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:19:12', 2, 'done'),
(1104, 'دو تاس را پرتاب می‌کنیم. کدام دو پیشامد مستقل از یکدیگر هستند؟', 2, 1, 52, 223, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:19:35', 2, 'done'),
(1105, 'اگر $P(A) = \\frac{3}{8}$ و $P(A\' \\cap B) = \\frac{5}{12}$ باشد، مقدار $P(B|A\')$ کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:23:25', 2, 'done'),
(1106, 'از مجموعه اعداد چهار رقمی زوج ساخته شده با ارقام $0, 1, 2, 3, 4$ (بدون تکرار ارقام) یک عدد به طور تصادفی انتخاب می‌کنیم. احتمال آن که این عدد کوچک‌تر از ۳۲۰۰ باشد کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:24:06', 2, 'done'),
(1107, 'احتمال این‌که تیراندازی به هدف بزند $\\frac{1}{4}$ و احتمال آن‌که این تیرانداز در مسابقات نفر اول شود $\\frac{1}{3}$ است. اما اگر این تیرانداز به هدف زده باشد، احتمال آن‌که در مسابقات نفر اول شود برابر $\\frac{1}{2}$ خواهد شد. احتمال این‌که حداقل یکی از دو اتفاق نفر اول شدن یا خوردن تیر به هدف برای این تیرانداز بیفتند، کدام است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:26:34', 2, 'done'),
(1108, 'در جعبه‌ای ۵ مهره قرمز و ۷ مهره آبی موجود است. بدون نگاه کردن ۲ مهره به تصادف از جعبه خارج می‌کنیم و کنار می‌گذاریم. سپس از بین باقی‌مانده‌های مهره‌ها ۲ مهره بیرون می‌آوریم. احتمال آن‌که هر دو مهره هم‌رنگ باشند، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:28:35', 2, 'done'),
(1109, ' هر یک از اعداد اول کوچک‌تر از ۳۰ را روی یک کارت نوشته و آن‌ها را درون جعبه‌ای قرار می‌دهیم. به تصادف از این جعبه چهار کارت برمی‌داریم. با کدام احتمال بزرگ‌ترین و کوچک‌ترین اعداد خارج شده به‌ترتیب ۲۳ و ۷ هستند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:29:34', 2, 'done'),
(1110, ' سه ماشین $A_1$ و $A_2$ و $A_3$ هر کدام به‌ترتیب ۵۰ و ۳۰ و ۲۰ درصد از قطعات یک ربات را می‌سازند و به‌ترتیب ۳ و ۴ و ۵ درصد قطعات تولیدی آن‌ها خراب است. اگر یک قطعه از ربات را به‌طور تصادفی برداریم و خراب باشد، احتمال آن‌که این قطعه خراب توسط ماشین $A_2$ تولید شده باشد چقدر است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:30:05', 2, 'done'),
(1111, '  اگر $a, b, c \\in \\{1, 2, 3, 4\\}$ معادله درجه دومی به‌صورت $ax^2 + bx + c = 0$ نوشته‌ایم. احتمال این‌که مجموع ریشه‌های این معادله از حاصل‌ضرب ریشه‌هایش دو واحد کمتر باشد، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:30:43', 2, 'done'),
(1112, 'علی، امیر و رضا به همراه ۳ دوست خود کنارهم نشسته‌اند. احتمال اینکه امیر بین علی و رضا (بدون فاصله) نشسته باشد، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:28:00', 2, 'done'),
(1113, ' در خانواده‌ای ۴ فرزندی می‌دانیم حداقل ۲ فرزند، پسر هستند. احتمال اینکه فرزند آخر دختر باشد، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:31:14', 2, 'done'),
(1114, 'چند درصد احتمال دارد که با انتخاب تصادفی یک عدد در بین تمام اعداد چهار رقمی، مجموع دو رقم وسط ۱۰ باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:31:42', 2, 'done'),
(1115, ' برای دو پیشامد $A$ و $B$ در فضای نمونه‌ای $S$ و $P(A) = 0/4$، $P(B|A) = 0/25$ و $P(B - A) =0/2 $ است. مقدار $P(B|A\')$ و $P(A\'|B\')$ به‌ترتیب از راست به چپ در کدام گزینه آمده است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:32:31', 2, 'done'),
(1116, 'مدرسه $A$ چهار برابر مدرسه $B$ دانش‌آموز دارد. ۲۵ درصد دانش‌آموزان مدرسه $A$ و ۱۵ درصد دانش‌آموزان مدرسه $B$ معدل بالای ۱۹ دارند. اگر همه‌ دانش‌آموزان این دو مدرسه در یک سالن حاضر باشند و به تصادف یکی از آن‌ها را انتخاب کنیم، چند درصد احتمال دارد که معدل بالای ۱۹ داشته باشد؟', 3, 1, 53, 225, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:33:06', 2, 'done'),
(1117, ' احتمال شیوع یک بیماری در جامعه‌ای 12/0 و احتمال بهبود یافتن فرد مبتلا به این بیماری 6/0 است. احتمال اینکه فردی از این جامعه به این بیماری مبتلا شود و بهبود یابد، چند درصد است؟', 2, 1, 52, 224, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:33:36', 2, 'done'),
(1118, ' هریک از اعداد اول کوچک‌تر از ۴۰ را روی یک کارت نوشته و آن‌ها را درون جعبه‌ای قرار می‌دهیم. به‌طور تصادفی از این جعبه پنج کارت برمی‌داریم. با کدام احتمال بزرگ‌ترین و کوچک‌ترین اعداد خارج‌شده به‌ترتیب ۳۱ و ۱۳ هستند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:34:01', 2, 'done'),
(1119, ' نقطه $A$ در صفحه مختصات مفروض است. طول این نقطه از مجموعه $\\{0, 1, 2, 3, 4\\}$ و عرض آن از مجموعه $\\{-2, -1, 0, 1, 2, 3\\}$ انتخاب می‌شود. اگر نقطه $A\'$، قرینه نقطه $A$ نسبت به نیمساز ربع دوم و چهارم مختصات باشد، احتمال آن که طول پاره‌خط $AA\'$ برابر صفر نشود، چند درصد است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-20 12:08:40', 1, '2026-03-23 18:34:30', 2, 'done'),
