(1162, ' تابع $f(x)=[\\frac{x-2}{x}]+|2x|$ مفروض است. اگر $\\lim_{x\\to(-\\frac{1}{2})^+}$ $f(x)=a$ و $\\lim_{x\\to(-\\frac{1}{2})^-}$ $f(x)=b$ باشد، حاصل $a^2-b^2$ کدام است؟ ( [ ] علامت جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:05:33', 6, 'done'),
(1163, '6- اگر $\\lim_{x\\to-1} f(x)=0$ و $\\lim_{x\\to-1} \\frac{x^2-1}{f(x)}=a$ و $a<0$ باشد، نمودار $f(x)$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, NULL, NULL, 'free'),
(1164, ' اگر $\\lim_{x\\to0^+} \\frac{\\sqrt{1}-\\sqrt{1-kx^2}}{x}=\\frac{1}{\\sqrt{k}}$ باشد، مقدار $k$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:06:54', 6, 'done'),
(1165, ' حاصل $\\lim_{x\\to(\\frac{1}{2})^+} \\frac{4x+\\sqrt{2x-1}-2}{x^2-\\sqrt[3]{1-2x}-\\frac{1}{4}}$ کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:11:29', 6, 'done'),
(1166, ' حاصل $\\lim_{x\\to(\\frac{3\\pi}{4})^+} \\frac{\\sqrt{1+\\sin 2x}}{\\cos 2x}$ کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:12:40', 6, 'done'),
(1167, ' با توجه به نمودار تابع $f(x)$، حاصل $\\lim_{x\\to1} \\frac{f^{-1}(2\\sqrt{x})-2}{f(4x)-3}$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:13:29', 6, 'done'),
(1168, ' حاصل $\\lim_{x\\to1^-} \\frac{\\sqrt{x^2+3}-\\sqrt{3x+1}}{\\sqrt{x+1}-2\\sqrt{x}}$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:14:01', 6, 'done'),
(1169, ' تابع $f(x)=([x]-a)[x]$ در یک نقطه از بازه $(\\-frac{1}{2},\\frac{5}{3})$ ناپیوسته است. مجموع مقادیر متمایز $a$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:14:20', 6, 'done'),
(1170, 'اگر $\\lim_{x\\to\\frac{1}{2}} \\frac{1-2\\sin^2(2x)}{ax^2+bx-1}=-\\infty$ باشد، آنگاه حاصل $b-a$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:14:52', 6, 'done'),
(1171, 'اگر $f\\!\\left(2x-\\frac{\\pi}{6}\\right)=\\dfrac{\\tan\\!\\left(x+\\frac{\\pi}{6}\\right)}{2[x]-3}$ باشد، حاصل $\\lim_{x\\to(\\frac{\\pi}{2})^+} f(x)$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:15:16', 6, 'done'),
(1172, 'به ازای چند مقدار $a$ نمودار تابع $f(x)=\\dfrac{x+a}{x^2-2ax+2a+3}$ در اطراف نقطه $x=k$ به صورت مقابل است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-25 14:19:05', 6, 'done'),
(1173, ' با توجه به نمودار $f(x)$، نمودار تابع $g(x)=\\dfrac{2x}{f(x)}$ در اطراف نقطه موردنظر چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, NULL, NULL, 'free'),
(1174, '۱۷- حاصل کدام‌یک از حدود زیر درست نمی‌باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, NULL, NULL, 'free'),
(1175, 'اگر $\\lim_{x \\to -\\infty} \\frac{ax^n + 2x^3 + 1}{2x^m + x + 5} = 3$ باشد، مقدار $a + m$ کدام گزینه نمی‌تواند باشد؟ $(m, n \\in \\mathbb{N})$', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:49:27', 2, 'done'),
(1176, 'بزرگترین بازه‌ای که تابع $y = f(x)$ در آن پیوسته است به صورت $[a, b)$ می‌باشد. ضابطه $f(x)$ کدام می‌تواند باشد؟', 2, 1, 44, 208, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:50:22', 2, 'done'),
(1177, ' اگر $\\lim_{x \\to -\\infty} \\frac{x^2 + 3x - \\frac{1}{x}}{x + 2} + ax + b = a + 5$ باشد، حاصل $a + b$ کدام است؟ $(a, b \\in \\mathbb{R})$', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:50:00', 2, 'done'),
(1178, 'نمودار دو تابع $f$ و $g$ به‌صورت مقابل است. حاصل چه تعداد از حدهای زیر به درستی محاسبه شده است؟\r\n\r\nالف) $\\lim_{x \\to (-2)^+} (g \\circ f)(x) = 2$\r\n\r\nب) $\\lim_{x \\to 5^+} (f \\circ g)(x) = 6$\r\n\r\nپ) $\\lim_{x \\to 1^-} g(f(4 - x)) = 3$', 2, 1, 44, 192, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:51:58', 2, 'done'),
(1179, ' نمودار دو تابع $f$ و $g$ به‌صورت مقابل است. اگر $h(x) = \\begin{cases} \\frac{|f(x) - g(x)|}{f^2(x) - g^2(x)} & ; f(x) > g(x) \\\\ \\frac{|f(x) - g(x)|}{f(x) - g(x)} & ; f(x) \\le g(x) \\end{cases}$ باشد، حاصل $\\lim_{x \\to 2^+} h(x) + \\lim_{x \\to 9^+} h(x)$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:51:56', 6, 'done'),
(1180, ' نمودار تابع خطی $f$ و تابع درجه دوم $g$ به‌صورت مقابل است. حاصل $\\lim_{x \\to 2} \\frac{g(x)+1}{xf^{-1}(x)-2}$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:52:41', 6, 'done'),
(1181, ' اگر $\\lim_{x \\to -\\infty} \\frac{x^2 - 4x + 1}{ax^2 - \\sin 2x} = -\\frac{1}{2}$ باشد، حاصل $\\lim_{x \\to (\\frac{5\\pi}{4})^+} \\frac{\\tan x}{1 + a \\sin^2 x}$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:53:13', 6, 'done'),
(1182, ' به‌ازای کدام مقدار $a$ تابع $f(x) = \\begin{cases} \\frac{a}{x^2 - 4} & ; x < 1 \\\\ 2a + \\sin(\\pi x + \\frac{\\pi}{6}) & ; x \\ge 1 \\end{cases}$ فقط در یک نقطه ناپیوسته است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:54:05', 2, 'done'),
(1183, ' اگر نمودارهای توابع $f(x)$ و $g(x)$ به صورت مقابل باشند، حاصل عبارت $\\lim_{x \\to 1^+} \\frac{xf([g(x)]) - 1}{f(g(x))}$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:53:55', 6, 'done'),
(1184, ' اگر باقیمانده تقسیم چندجمله‌ای $f(x+1)$ بر $x+2$ و $x-2$ به ترتیب $-1$ و $3$ باشد، حاصل $\\lim_{x \\to -1} 5f(2-x) - \\lim_{x \\to 0^+} 2f([x-1])$ کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-23 10:09:14', 5, 'done'),
(1185, 'حاصل $\\lim_{x \\to 4} \\frac{5 - \\sqrt{x^2 + 2\\sqrt{x} + 5}}{x + [x^2 - 8x + 12]}$ کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:55:16', 2, 'done'),
(1186, 'اگر $9 = \\lim_{x \\to -\\infty} \\frac{a(x-1)^3 + b(2x+1)^3}{\\sqrt{x^2+1} \\times \\sqrt{4x^2-x}}$ باشد، حاصل $\\lim_{x \\to -\\infty} \\frac{x + \\sqrt{a^2 x^2 + 1}}{bx}$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:55:51', 2, 'done'),
(1187, ' هرگاه تابع $f(x)$ یک تابع خطی و $\\lim_{x \\to -3} \\frac{|2x^2| + f(x)}{x^2 - 9} = \\frac{4}{3}$ باشد، آنگاه حاصل $\\lim_{x \\to \\frac{5\\pi}{3}} f(\\cos x)$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:56:35', 2, 'done'),
(1188, ' اگر $0 = \\lim_{x \\to 2} \\frac{x^3 + ax^2 + bx}{x - 2}$ باشد، حاصل $\\lim_{x \\to -\\infty} \\frac{bx + \\sqrt{-ax^2 + 10}}{(a + b)x^2 + 3x + 1}$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:56:55', 2, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(1189, ' با توجه به نمودار توابع $f$ و $g$ حاصل $\\lim_{x \\to 1^+} \\frac{2f(x) - 3}{g(x) + 1}$ کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:54:25', 6, 'done'),
(1190, 'چندجمله‌ای $p(x) = x^8 + ax^5 – x^2+2$ بر $x+1$ بخش‌پذیر است. باقی‌مانده تقسیم چندجمله‌ای $p(3-x) + p(x-1)$ بر $x-2$ کدام است؟', 3, 1, 48, 387, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:57:29', 2, 'done'),
(1191, ' هیچ همسایگی راست نقطه $a$ در دامنه $\\frac{\\sqrt{4x - x^2}}{x - [x]} = f(x)$ قرار ندارد ولی یک همسایگی چپ آن در دامنه این تابع قرار دارد. مقدار $\\lim_{x \\to \\frac{a}{2}^-} xf(x)$ کدام است؟', 2, 1, 44, 198, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:58:10', 2, 'done'),
(1192, 'تابع $f(x) = \\frac{x^3 + ax + 2a}{x^2 - 3x + 2}$ فقط در یک نقطه حد ندارد. مجموع مقادیر ممکن $a$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:58:29', 2, 'done'),
(1193, 'اگر $f(x+2^x) = x^3 - 2^x$ باشد، مقدار $\\lim_{x \\to 6} \\frac{f(x)}{f(x-5)}$ کدام است؟', 2, 1, 44, 191, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:59:09', 2, 'done'),
(1194, 'اگر تابع $f$ در نقطه $x=3$ حد داشته باشد و $\\lim_{x \\to 3} (f^2(x) - 4f(x)) = -4$ باشد، مقدار $\\lim_{x \\to 3} \\frac{x^2 + 1}{f(x)}$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 21:59:40', 2, 'done'),
(1195, ' تابع $f(x) = x^2[-x] + [2x]$ در چند نقطه صحیح حد دارد؟', 2, 1, 44, 192, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 22:00:07', 2, 'done'),
(1196, 'مقدار $\\lim_{x \\to 1^+} (2x+1)[\\frac{x+5}{x^2-x-2}]$ کدام است؟', 2, 1, 44, 191, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 22:00:31', 2, 'done'),
(1197, ' اگر $f(x) = \\frac{4x-1}{x^3-6x}$ باشد، مقدار $\\lim_{x \\to 0} \\frac{1}{x} f(x) f(\\frac{2}{x})$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 22:20:09', 2, 'done'),
(1198, ' اگر $\\lim_{x \\to 2} \\frac{ax^2-x+2-4a}{x^2+4ax+b} = -\\frac{5}{8}$ باشد، مقدار $b-a$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 22:20:47', 2, 'done'),
(1199, 'مقدار $\\lim_{x \\to 1^+} \\frac{3x\\sqrt{x-1} - (x+2)\\sqrt{x^2-1}}{\\sqrt{x^3-1}}$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:10:55', 2, 'done'),
(1200, ' تابع $f(x) = \\begin{cases} \\frac{ax+b}{\\sqrt{x}-2} & ; x \\neq 4 \\\\ 8 & ; x = 4 \\end{cases}$ روی بازه $[0, +\\infty)$ پیوسته است. مقدار $a+b$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:54:54', 6, 'done'),
(1201, ' تابع $f(x) = ([x] + [-x])[\\sqrt{x}]$ در چند نقطه از بازه $(0, 8)$ حد دارد ولی پیوسته نیست؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:55:11', 6, 'done'),
(1202, ' مقدار $\\lim_{x \\to 16^-} \\frac{\\sqrt{x}-4}{\\sqrt{x-4\\sqrt[4]{x}+4}}$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:55:34', 6, 'done'),
(1203, ' اگر $+\\infty = \\lim_{x \\to \\frac{\\pi}{4}} \\frac{k[\\frac{8x}{\\pi}] - k^2}{\\sin x - \\cos x}$ باشد، مجموعه مقادیر ممکن $k$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:56:10', 6, 'done'),
(1204, '۴۷- نمودار تابع $f(x) = \\frac{1}{\\sqrt{x} + \\sqrt{2-x} - 2}$ در اطراف خط $x=1$ چگونه است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:56:47', 6, 'done'),
(1205, ' اگر $\\lim_{x \\to +\\infty} \\frac{(a-2b)x^3 + bx^2 + x}{ax^2 - bx - 1} = \\frac{a^2 + 1}{4}$ باشد، مقدار $ab$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:57:01', 6, 'done'),
(1206, ' نمودار تابع $f(x) = \\frac{x^2 - x}{x^2 + kx + 1}$ در بی‌نهایت به صورت مقابل است. مجموعه مقادیر ممکن $k$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:57:14', 6, 'done'),
(1207, ' اگر $f(x) = \\frac{4x|x| + k^2x^2 + 1}{x^2 - 3x + 2}$ و $\\lim_{x \\to 1^+} (fof)(x) = 5$ باشد، مقدار $f(\\frac{k^2}{3})$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:57:38', 6, 'done'),
(1208, ' اگر $f(x) = \\frac{x^3}{x^2 + 1}$ و $g(x) = \\frac{x^3 + kx^2 + 1}{x^2 - x}$ و $\\lim_{x \\to +\\infty} (f(x) - g(x)) = 3$ باشد، مقدار $k$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:57:52', 6, 'done'),
(1209, ' اگر $f(x) = \\frac{x}{\\sqrt{x + 2x + k}}$ و $\\lim_{x \\to +\\infty} f^{-1}(x) = 4$ باشد، مقدار $k$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-26 23:58:05', 6, 'done'),
