(1224, ' اگر تابع $f(x) = \\begin{cases} [-x] + a & ; x > 1 \\\\ b & ; x = 1 \\\\ \\frac{x^3 + cx^2 + dx}{(x - 1)^2} & ; x < 1 \\end{cases}$ در نقطه $x = 1$ پیوسته باشد، حاصل $2a-3b+c-d$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 01:19:57', 2, 'done'),
(1225, '۶۸- باقی‌مانده تقسیم چندجمله‌ای $f(x)$ بر $x^2+2x-3$ برابر $1-4x$ است. اگر چندجمله‌ای $f(x-5)+af(x-1)$ بر $x-2$ بخش‌پذیر باشد، $a$ کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-23 10:10:37', 5, 'done'),
(1226, ' اگر $x-a$ بر $f(x)=2x^3-2ax^2+2x-4$ بخش‌پذیر باشد، باقی‌مانده $f(x+a)$ بر $x-1$ کدام است؟', 3, 1, 48, 387, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 01:20:39', 2, 'done'),
(1227, '۷۰- نمودار سهمی $y=f(x)$ به شکل روبه‌رو است. اگر $+\\infty = \\lim_{x \\to 4} \\frac{1}{a-f(x+b)}$ باشد، مقدار $a-b$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 10:24:35', 6, 'done'),
(1228, ' اگر $b = \\lim_{x \\to 2} \\frac{\\sqrt{ax+1}-3}{2x^2-x-6}$، عدد حقیقی باشد، $ab$ کدام است؟', 2, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 01:23:04', 2, 'done'),
(1229, '۷۲- قسمتی از نمودار $f(x)=\\frac{x^2+ax+b}{x+\\sqrt{x+2}}$ به شکل مقابل است. مقدار $a+b-x_0$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 10:25:51', 6, 'done'),
