(1235, ' اگر توابع $f$ و $g$ در نقطه $x=1$ دارای حد باشند و $7= \\lim_{x \\to 1} (2f(x) + g(x))$ و $1= \\lim_{x \\to 1} (g(x) - f(x))$ باشد، حاصل $\\lim_{x \\to 3} g(3x-8)$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 01:25:41', 2, 'done'),
