(1239, 'اگر $f(x) = 2x[\\frac{-1}{x}] + |3-x|$ باشد، حاصل $\\lim_{x \\to +\\infty} f(x)$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:26:02', 1, '2026-03-27 01:27:20', 2, 'done'),
