(1356, '45- اعداد طبیعی فرد را طوری دسته‌بندی می‌کنیم که تعداد جملات هر دسته برابر شماره آن دسته باشد، یعنی $\\{1\\}$، $\\{3,5\\}$، $\\{7,9,11\\}$، … . در این صورت جمله آخر واقع در دسته شماره چهل، کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:05:46', 6, 'done'),
(1357, 'می‌خواهیم از بین $n$ دانش‌آموز یک کلاس، 3 نفر A و B و C را برای تیم فوتبال انتخاب کنیم به‌طوری که A و B انتخاب شوند. تعداد حالت‌ها برابر با 84 است. تعداد دانش‌آموزان کلاس چند نفر است؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:07:15', 6, 'done'),
(1358, ' از 4 شهر از هر شهر 5 نفر در مسابقه‌ای شرکت کرده‌اند. به چند طریق می‌توان 3 نفر از بین آن‌ها انتخاب کرد به‌طوری که حداکثر 1 نفر از یک شهر باشند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:07:31', 6, 'done'),
(1359, '48- با حروف کلمه «هوش‌یابی» و بدون تکرار حروف چند کلمه 7 حرفی می‌توان نوشت که با حرف «ن» شروع و به حرف «د» ختم شود؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:07:46', 6, 'done'),
(1360, '49- فرض کنیم هفت نفر می‌خواهند سخنرانی کنند به‌طوری که بین دو نفر خاص، دقیقاً سه نفر سخنرانی داشته باشند. در این صورت این هفت نفر به چند صورت مختلف می‌توانند سخنرانی کنند؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:08:09', 6, 'done'),
(1361, 'در چند جایگشت از حروف کلمه «Premier» حداقل یک حرف بین دو «r» فاصله وجود دارد؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:08:34', 6, 'done'),
(1362, 'با به‌هم وصل کردن نقاط شکل مقابل، چند چهارضلعی محدب شامل ضلع‌های $AC$ یا $AB$ می‌توان رسم کرد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:08:49', 6, 'done'),
(1363, ' با ارقام متمایز 0 و 1 و 2 و 3 و 4 و 5 و 6 و 7 و 8 و 9 چند عدد طبیعی مضرب 5 بیش‌تر از 100 و فاقد رقم تکراری می‌توان ساخت؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:09:42', 6, 'done'),
(1364, '53- با 5 نفر پسر و 8 نفر دختر، چند طریق می‌توان چهار نفره گروه تشکیل داد به‌طوری که اعضای آن‌ها هم‌جنس نباشند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:10:01', 6, 'done'),
(1365, '54- از 3 آلمانی و 4 فرانسوی به چند طریق می‌توانند وارد یک ساختمان شوند به‌طوری که بین هر دو ایرانی یک فرانسوی باشد؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:10:17', 6, 'done'),
(1366, ' به چند طریق می‌توان 6 عدد متمایز را درون 4 جعبه‌ی مختلف قرار داد به‌طوری که در هر جعبه‌ای حداقل یک عدد قرار گیرد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:28:50', 1, '2026-03-27 13:10:34', 6, 'done'),
(1367, '۱- در چند جایگشت از حروف کلمه «کتابخانه» عبارت «کتاب» وجود دارد اما «خانه» وجود ندارد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 13:10:49', 6, 'done'),
(1368, '۲- حروف کلمه «سراخلف»، چند کلمه ۶ حرفی می‌توان نوشت، به‌طوری‌که دقیقاً شامل سه حرف تکراری باشد؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 13:11:13', 6, 'done'),
(1369, '۳- تمام اعداد چهاررقمی با ارقام غیرتکراری را به‌ترتیب از کوچک به بزرگ نوشته‌ایم. عدد ۲۰۱۳ چندمین عدد این لیست است؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:43:50', 6, 'done'),
(1370, '۴- فرض کنید فضای نمونه‌ای S یک داده تصادفی به‌صورت $S=\\{a,b,c,d,e,f,g,h,i\\}$ و $A=\\{f,g,h,i\\}$ یک پیشامد از این فضای نمونه‌ای باشد. چند پیشامد ناسازگار با A می‌توان یافت که در S وجود دارند؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:44:57', 6, 'done'),
(1371, '۶ توپ قرمز یکسان و ۳ توپ زرد یکسان داریم. به چند طریق می‌توان این ۹ توپ را کنار هم قرار داد، به‌طوری‌که هیچ دو توپ زردی کنار یکدیگر قرار نگیرند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:45:33', 6, 'done'),
(1372, ' اگر $A=\\{۱،۲،۳،۴،۵\\}$ چند تابع وجود دارد که دامنه و برد آن A باشد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:46:12', 6, 'done'),
(1373, '۷- در شکل روبرو، به چند مثلث می‌توان رسم کرد که رأس‌های آن از نقاط مشخص شده باشد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:46:30', 6, 'done'),
(1374, '۸- در شکل روبرو اگر تمام پاره‌خط‌های کوچک بردار است، در این شکل چند مربع وجود دارد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:46:41', 6, 'done'),
(1375, '۹- چند عدد چهار رقمی با ارقام متمایز وجود دارد که بزرگترین رقم آن ۲ رقم، رقم سمت چپ آن باشد؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:47:12', 6, 'done'),
(1376, '۱۰- یک مربی فوتبال به چند طریق می‌تواند از بین شش بازیکن دفاعی که در تمامی پست‌های دفاعی می‌توانند بازی کنند، ۴ بازیکن را برای بازی در چهار پست مختلف دفاع انتخاب کند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:47:30', 6, 'done'),
(1377, '۱۱- به چند طریق می‌توان با استفاده از ۵ رنگ مختلف برای پرچم سه نوار افقی ساخت به‌گونه‌ای که نوارهای مجاور هم‌رنگ نباشند؟', 1, 1, 2, 266, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:47:44', 6, 'done'),
(1378, '۱۲- به چند طریق می‌توان ۳ کتاب ریاضی متمایز و ۴ کتاب داستان متمایز را در یک قفسه کنار هم قرار داد به‌شرطی که کتاب‌های ریاضی کنار هم و کتاب‌های داستان کنار هم باشند؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:48:58', 6, 'done'),
(1379, ' مجموعه $A=\\{۱،۲،۳،۴،۵،۶،۷\\}$ چند زیرمجموعه شامل ۲ و ۳ و فاقد ۷ دارد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:49:12', 6, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(1380, '۱۴- با ارقام ۱،۲،۳،۷،۸ چند عدد سه‌رقمی زوج با ارقام غیرتکراری می‌توان نوشت؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:49:37', 6, 'done'),
(1381, '۱۵- اگر مجموعه اعداد طبیعی فرد را به‌گونه‌ای دسته‌بندی کنیم که در آن تعداد اعداد هر دسته برابر شماره آن دسته باشد، عدد ۸۱ در دسته بیستم قرار دارد؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:49:49', 6, 'done'),
(1382, '۱۶- در چند جایگشت از حروف «گزینه دو»، عبارت «دو» به کار رفته است؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:29:13', 1, '2026-03-27 17:50:34', 6, 'done'),
(1383, ' هر یک از میوه‌های گوجه‌سبز، آلبالو و زردآلو را بین سه نفر با لباس‌های سبز، زرد و قرمز پخش می‌کنیم. با کدام احتمال هر فرد میوه همرنگ با لباسش را دریافت کرده است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:51:00', 6, 'done'),
(1384, ' از کیسه‌ای که در آن ۵ مهره با شماره‌های ۱،۲،۳،۴،۵ قرار دارد، به طور متوالی سه مهره با جایگذاری بیرون می‌آوریم و اعداد مهره‌ها را کنار هم می‌نویسیم. با کدام احتمال عدد سه‌رقمی حاصل از 3۴۱ کمتر است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:51:16', 6, 'done'),
(1385, ' حروف کلمه HELENA را کنار هم چیده ایم. با کدام احتمال دو حرف E کنار هم قرار می‌گیرند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:51:33', 6, 'done'),
(1386, ' در پرتاب سه تاس با هم چقدر احتمال دارد مجموع سه عدد رو شده ۱۴ و حاصل ضرب آن‌ها مضرب ۳ باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:51:44', 6, 'done'),
(1387, ' از بین ۴ دکتر، ۴ متخصص بیهوشی و ۴ تکنسین اتاق عمل، ۵ نفر را به تصادف انتخاب می‌کنیم. با کدام احتمال از هر سه رشته افرادی را انتخاب کرده‌ایم؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:52:00', 6, 'done'),
(1388, ' اگر A و B دو پیشامد در یک فضای نمونه‌ای باشند، به طوری که $4P(A)=3P(B)=6P(A\\cap B)=1$، آنگاه حاصل $P(B\'|A\')$ کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:52:16', 6, 'done'),
(1389, ' با ارقام ۱،۲،۳،۴ عددی دو رقمی می‌سازیم، اگر اول نباشد با کدام احتمال فرد است؟ (تکرار ارقام مجاز است.)', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:52:30', 6, 'done'),
(1390, ' احتمال آن که فردی ناراحتی قلبی پیدا کند $0.25$، احتمال آن که ناراحتی کلیه پیدا کند $0.36$ و احتمال آن که هر دو بیماری را پیدا کند $0.12$ است. اگر بدانیم او ناراحتی قلبی یا کلیه دارد، با کدام احتمال قلب او سالم ولی کلیه او ناراحت است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:52:57', 6, 'done'),
(1391, ' یک تاس و یک سکه را در نظر بگیرید. اگر هر کدام از آن‌ها را دو بار پرتاب کنیم، احتمال آن که تاس حداقل یک بار مضرب ۳ یا سکه هر دو بار رو ظاهر شود، کدام است؟', 3, 1, 52, 224, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:53:51', 6, 'done'),
(1392, ' در فضای نمونه‌ای هم‌شانس $S$، پیشامدهای $\\{1,2,3,4\\}$ و $\\{2,3,5\\}$ مستقل‌اند. احتمال پیشامد $\\{1,5\\}$ کدام است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:54:22', 6, 'done'),
(1393, ' کتاب‌های درسی فیزیک ۱ و ۲ و ۳ و شیمی ۱ و ۲ و ۳ و فارسی ۱ و ۲ و ۳ را در کتابخانه به طور تصادفی کنار هم می‌چینیم. با کدام احتمال، کتاب‌های شیمی کنار هم و کتاب‌های فارسی از راست به چپ به ترتیب پایه هستند؟ (کتاب‌های فارسی لزوماً کنار هم نیستند.)', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 17:58:38', 6, 'done'),
(1394, ' کیسه‌ای شامل ۱۲ مهره از رنگ‌های قرمز، سبز، آبی و زرد با تعداد مساوی است. اگر ۳ مهره از این کیسه بیرون بیاوریم، با کدام احتمال در مهره‌های انتخابی قرمز هست یا زرد نیست؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 18:14:16', 6, 'done'),
(1395, ' یک پنالتی‌زن در حالت عادی هر توپ را با احتمال $\\frac{1}{2}$ گل می‌کند، اما وقتی یک توپ گل نمی‌شود، از احتمال گل شدن توپ بعدی $\\frac{1}{10}$ کم می‌شود. با کدام احتمال در ۳ ضربه متوالی فقط یکی گل می‌شود؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 18:15:13', 6, 'done'),
(1396, ' در ظرفی ۴ مهره سفید و ۳ مهره سیاه داریم. ۲ مهره به تصادف و به طور همزمان از آن بیرون می‌آوریم و به تعداد مهره‌های سیاه خارج‌شده سکه می‌اندازیم. با کدام احتمال هم رو و هم پشت دیده می‌شوند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 18:16:11', 6, 'done'),
(1397, ' درون کیسه $A$، ۳ مهره سفید و ۲ مهره سیاه، درون کیسه $B$، ۲ مهره سفید و ۴ مهره سیاه و درون کیسه $C$، ۴ مهره سفید و ۲ مهره سیاه قرار دارد. یکی از کیسه‌ها را به تصادف انتخاب و مهره‌ای خارج می‌کنیم. اگر مهره سفید باشد، آن را در کیسه دیگری که مهره سفید بیشتری دارد قرار داده و اگر مهره سیاه باشد، آن را در کیسه دیگری که مهره سیاه بیشتری دارد قرار می‌دهیم. دوباره مهره‌ای از کیسه‌ای که تعداد مهره‌های بیشتری دارد خارج می‌کنیم. با کدام احتمال این مهره سفید است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 18:16:51', 6, 'done'),
(1398, 'در کیسه اول ۸ مهره سیاه، در کیسه دوم ۸ مهره سفید و در کیسه سوم ۵ مهره سیاه و ۳ مهره سفید داریم. به تصادف یکی از این کیسه‌ها را انتخاب و دو مهره از آن خارج می‌کنیم. احتمال آن که در میان این دو مهره، مهره سفید داشته باشیم کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 18:17:50', 6, 'done'),
(1399, ' دو تاس را با هم پرتاب می‌کنیم. اگر مجموع دو عدد رو شده از ۹ بیشتر بود، یک عدد طبیعی یک رقمی و اگر از ۹ کمتر بود، یک عدد طبیعی دو رقمی انتخاب می‌کنیم. با کدام احتمال، عدد انتخاب‌شده اول است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 11:42:28', 1, '2026-03-27 18:18:07', 6, 'done'),
(1400, 'حاصل عبارت $\\frac{(3+\\sqrt{5})^{\\frac{1}{2}}+(2+\\sqrt{3})^{\\frac{1}{2}}}{2+\\sqrt{3}+\\sqrt{5}}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:18:53', 6, 'done'),
(1401, 'اگر $A=\\sqrt[3]{12}\\times\\sqrt[5]{54}\\times\\sqrt[3]{\\sqrt{6}}$ آن‌گاه حاصل $(5+2\\sqrt{A})^{-0.5}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:19:05', 6, 'done'),
(1402, 'اگر $x^2-3x+1=0$ باشد، آن‌گاه حاصل عبارت $\\frac{x^4}{x^4-x^2+1}-\\frac{4x^3}{x^4+x^2+1}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:19:27', 6, 'done'),
(1403, 'اگر $a$ و $b$ دو عدد حقیقی بزرگ‌تر از یک باشند و $a^3=2+b^3$ باشد، حاصل $\\frac{a^2+a+1}{b^2-b+1}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:19:39', 6, 'done'),
(1404, 'حاصل عبارت $\\left(\\frac{4}{(\\sqrt{5}+1)(\\sqrt[4]{5}+1)(\\sqrt[8]{5}+1)(\\sqrt[16]{5}+1)}+1\\right)^{48}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:20:10', 6, 'done'),
(1405, 'اگر $A=2-\\sqrt{3}$ و $B=\\sqrt{\\sqrt[3]{3\\sqrt{3}}}$ به طوری که $A^{\\frac{1}{2}}B^k=\\sqrt{3}-1$، مقدار $k$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:20:22', 6, 'done'),
(1406, 'فرض کنید $\\frac{6-\\sqrt{2}}{\\sqrt{2}-1}=x^4+3x^2+\\frac{1}{x^2}$ باشد، مقدار $x^4+2x+\\frac{1}{x^2}$ برابر با کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:20:34', 6, 'done'),
(1407, 'حاصل $\\left(\\frac{3+\\sqrt{5}}{2}\\right)^6+\\left(\\frac{3-\\sqrt{5}}{2}\\right)^6$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:20:44', 6, 'done'),
(1408, 'اگر $3\\sqrt{x+3}-3\\sqrt{x}=6$ آن‌گاه $3\\sqrt{x^2+6x+9}+3\\sqrt{x^2+3x}$ با کدام گزینه برابر است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:21:09', 6, 'done'),
(1409, 'اگر $A=\\frac{(\\sqrt{2}-1)^{-1}}{1+\\sqrt[3]{\\sqrt{2}-1}}+\\frac{\\sqrt{2}+1}{1+\\sqrt[3]{\\sqrt{2}+1}}$ و $B=\\frac{1+\\sqrt{3}+\\sqrt{2}}{1+\\sqrt{3}-\\sqrt{2}}$، آن‌گاه جزء صحیح $A-B$ برابر است با:', 1, 1, 60, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:21:36', 6, 'done'),
(1410, 'چند عدد صحیح بین ریشه‌های دوم $\\sqrt[3]{\\frac{1}{2\\sqrt{2}}}\\sqrt{12-8\\sqrt{2}}+\\sqrt[3]{2}\\sqrt{10+7\\sqrt{2}}$ هستند؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:21:52', 6, 'done'),
(1411, 'معادله $(3^x-4)^3+(4^x-2)^3=(4^x+3^x-6)^3$ چند جواب حقیقی دارد؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:05:02', 1, '2026-03-27 18:22:13', 6, 'done'),
(1412, 'اگر خطوط مماس بر تابع $f(x)$ در دو نقطه $A$ و $B$ به ترتیب $y=2x-10$ و $y=\\frac{m+1}{m-1}x$ باشد، مقدار $m$ کدام می‌تواند باشد؟', 1, 1, 57, 236, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:22:58', 6, 'done'),
(1413, 'اگر $\\lim_{x\\to1}\\frac{f(x)-f(-1)}{x+1}+\\lim_{h\\to0}\\frac{f(-1+h)-f(-1)}{2h}=6$ باشد، حاصل $\\lim_{x\\to1}\\frac{f(x)-f(-1)}{\\sqrt{x}-1}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:23:17', 6, 'done'),
(1414, 'معادله خط مماس بر نمودار تابع $f(x)=\\sqrt{x+1}$ در نقطه برخورد با محور $y$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:23:33', 6, 'done'),
(1415, 'خط سهمی $y=p=ax^2-4ax+m$ را در دو نقطه $A$ و $B$ قطع کرده است. اگر شیب خط مماس در نقطه $B$ برابر $\\frac{7}{3}$ باشد، شیب خط مماس در نقطه $A$ چقدر است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:25:46', 6, 'done'),
(1416, 'مجموع شیب‌های خطوط مماس در نقاط $A$ و $B$ برابر $4$ است. اگر اندازه شیب خط مماس در نقطه $A$ دو برابر اندازه شیب خط مماس در نقطه $B$ باشد، حاصل‌ضرب شیب‌های خطوط مماس در $A$ و $B$ چقدر است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:26:02', 6, 'done'),
(1417, 'معادله خط مماس بر نمودار تابع $f(x)=x\\sqrt{x+1}$ در مبدأ مختصات کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:26:23', 6, 'done'),
(1418, 'در صورتی که $\\lim_{h\\to0}\\frac{h}{f(1+h)-f(1)}+\\lim_{x\\to1}\\frac{f(x)-f(1)}{x-1}=\\frac{5}{4}$ باشد، مجموع مقادیر ممکن برای $\\lim_{x\\to1}\\frac{f(x)-f(1)}{\\sqrt{x}-1}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:26:37', 6, 'done'),
(1419, 'از نقطه $A(-1,0)$ خطی مماس بر تابع $f(x)=\\sqrt{x}$ رسم کرده‌ایم. عرض نقطه تماس کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:27:06', 6, 'done'),
(1420, 'در چند نقطه از نمودار تابع $f(x)=|\\sin x|$ در بازه $( -\\pi , 2\\pi )$ داریم $f\'(x)=0$ ؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:27:49', 6, 'done'),
(1421, 'در صورتی که $\\lim_{h\\to0}\\frac{f(x+h)-f(x)}{h}=\\frac{3}{x^2}$ باشد، مقدار $\\lim_{x\\to2}\\frac{f(x)-f(2)}{x-2}$ چقدر است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:28:05', 6, 'done'),
(1422, 'مجموع طول نقاطی که خط مماس بر نمودار تابع $y=x^3-kx^2-k^2x$ و موازی خط $y=4x-1$ باشد برابر $2$ است. حاصل‌ضرب طول‌های آن نقاط چقدر است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:28:55', 6, 'done'),
(1423, 'اگر $f(x)=\\frac{-1}{(x+1)^2}$ باشد، جواب‌های نامعادله $(f(x))^2f\'(x)<f^2(x)$ کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:29:10', 6, 'done'),
(1424, 'اگر $(f+f\')(1)=3$ و $(f+f\')(1)=-6$ باشد، مشتق تابع $g(x)=f^2(x)$ در نقطه $x=1$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:29:41', 6, 'done'),
(1425, 'اگر $f(1)=f\'(1)-4=0$ باشد، مشتق تابع $g(x)=f(x-4f(\\sqrt{x}))$ در $x=1$ چقدر است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:30:08', 6, 'done'),
(1426, 'خط $2x+3y=4$ بر نمودار تابع متناوب و مشتق‌پذیر $f(x)$ در نقطه‌ای به طول $a$ مماس است. اگر دوره تناوب تابع $f(x)$ برابر $3$ باشد، مقدار $\\frac{f\'(3)+1}{f\'(5)}$ چقدر است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:30:47', 6, 'done'),
(1427, 'شیب خط مماس بر تابع $f(x)=\\frac{|4x+2|-|x|}{|x|-1}$ در نقطه $x=-\\frac{7}{4}$ چقدر است؟ (دامنه را جزء صحیح است.)', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:32:04', 6, 'done'),
(1428, 'مشتق راست تابع $f(x)=|8-x^2|(1+\\frac{1}{x})$ در $x=3$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:32:25', 6, 'done'),
(1429, 'دامنه تابع $f(x)=\\begin{cases}ax^2+bx & x\\ge1 \\\\\\ \\sqrt{x-1} & 0<x<1\\end{cases}$ مشتق‌پذیر روی بازه $(0,+\\infty)$ است. $f\'(1)$ چقدر است؟', 3, 1, 49, 214, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:33:16', 6, 'done'),
(1430, 'دو تابع $f(x)$ و $g(x)$ خطی هستند. اختلاف آهنگ متوسط تابع $(fg)(x)$ در بازه $[1,\\frac{1}{3}]$ و آهنگ لحظه‌ای در نقطه $x=\\frac{1}{12}$ چقدر است؟', 3, 1, 49, 215, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:33:33', 6, 'done'),
(1431, 'در صورتی که $f(x)=(x^2-1)\\sqrt[3]{x+1}$ باشد، حاصل $f\'(1)+f\'(-1)$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:38:27', 6, 'done'),
(1432, 'نمودار تابع $y=f(x)$ به شکل روبه‌رو است. مجموع ریشه‌های حقیقی معادله $(f(x))\'(x)=-xf(x)^2$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:38:52', 6, 'done'),
(1433, 'اگر $\\frac{f\'(3)-5}{f(3)+1}=4$ باشد، حاصل $\\lim_{h\\to0}\\frac{f(3+h)-3}{h^2+h}\\times\\lim_{x\\to3}\\frac{x^2-4}{f\'(x)-3f(x)}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:39:04', 6, 'done'),
(1434, 'اگر $\\lim_{x\\to4}\\frac{f(x)-f(4)}{f(x)+x-f(x)-4}=\\frac{3}{4}$ باشد، مقدار $\\lim_{h\\to0}\\frac{f(4+h)-f(4)}{2h}$ چقدر است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:39:16', 6, 'done'),
(1435, 'اگر $g(x)=(x^3-1)f(x)$ و $f(x)=\\begin{cases}x+3 & x=1 \\\\ x+x^2 & x\\ne1\\end{cases}$ باشد، $g\'(1)$ کدام است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:39:31', 6, 'done'),
(1436, 'اگر $g(x)=x^3+ax$ و $g\'(1)=3$ باشد، $g\'(1)g\'(-1)$ چقدر است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:39:46', 6, 'done'),
(1437, 'خط $L$ بر تابع $f(x)$ در نقطه $A$ مماس شده است. اگر طول نقاط $A$ و $B$ به ترتیب $1$ و $5$ باشند، حاصل $3f\'(1)+f(5)$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-27 18:40:38', 6, 'done'),
