(1439, 'مشتق چپ تابع $f(x)=\\frac{\\sqrt{x}-x^2}{1+x}$ در $x=1$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-26 22:26:22', 4, 'done'),
(1440, 'معادله نیم‌مماس راست تابع $f(x)=|-x||9-x^2|$ در $x=4$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 19:19:10', 1, '2026-03-26 22:25:35', 4, 'done'),
