(1538, ' اگر از نقاط شکل زیر به عنوان رئوس چندضلعی استفاده کنیم، تعداد چهارضلعی‌ها چقدر بیش‌تر از تعداد مثلث‌ها خواهد بود؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:40:02', 6, 'done'),
(1539, ' در پرتاب سه تاس، پیشامد ان که ضرب اعداد رو شده مضرب 5 باشد، چند عضو دارد؟', 1, 1, 2, 263, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:40:28', 6, 'done'),
(1540, ' اگر ضرایب $a$ و $b$وc $ $ در معادله $ax^2+bx+c=0$ از مجموعه $A={-5,-4,-3,\\ldots\\7}$ انتخاب کنیم. در چند حالت معادله مذکور دارای دو ریشهٔ مختلف‌العلامت است، در حالی که اندازهٔ ریشهٔ منفی بزرگ‌تر است؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:41:26', 6, 'done'),
(1541, ' با ارقام ۱،۲،۳،…،۹ چند عدد ۴ رقمی می‌توان ساخت به طوری که تعداد ارقام زوج آن از تعداد ارقام فرد آن بیش‌تر باشد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:41:38', 6, 'done'),
(1542, ' فرض کنید $a,b,c\\in\\{1,2,…,9\\}$، چند معادله درجه دوم به صورت $ax^2+bx-c=0$ می‌توان نوشت که فاصله حاصل‌ضرب ریشه‌های هر معادله با جمع ریشه‌های آن معادله، دو واحد باشد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:41:55', 6, 'done'),
(1543, ' به چند طریق می‌توان ۵ کتاب متمایز را بین ۳ نفر توزیع کرد، به شرط آن که هر نفر حداقل یک کتاب دریافت کند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:42:07', 6, 'done'),
(1544, '۲۲- با حروف کلمه «بورانی»، چند کلمه شش حرفی بدون تکرار حروف می‌توان نوشت به طوری که با حرف نقطه‌دار شروع و به حرف نقطه‌دار ختم شود؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:42:17', 6, 'done'),
(1545, ' به چند طریق می‌توان ۷ دانش‌آموز از ۱۱ دانش‌آموز یک کلاس را به اردو برد به طوری که ۳ نفر از آن‌ها نمی‌خواهند هرسه با هم در اردو باشند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:42:43', 6, 'done'),
(1546, ' با حروف کلمه «مامان»، چند کلمه ۴ حرفی می‌توان نوشت؟', 1, 1, 2, 266, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:44:00', 6, 'done'),
(1547, ' با ارقام ۴،۵،۶،۳،۲،۱، چند عدد ۵ رقمی بدون تکرار ارقام می‌توان نوشت که تعداد ارقام زوج آن بیش‌تر از ارقام فرد باشد؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:44:22', 6, 'done'),
(1548, ' از بین 4 دانش‌آموز کلاس دهمی، ۵ دانش‌آموز کلاس یازدهمی و ۳ دانش‌آموز کلاس دوازدهمی، به چند طریق می‌توان ۳ نفر انتخاب کرد به طوری که حداقل 2 تای آن‌ها هم پایه باشند؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:45:54', 6, 'done'),
(1549, ' به چند طریق می‌توان 9 جایزه متمایز جشنواره را بین ۳ تیم تقسیم نمود، به طوری که تعداد جایزه‌های هر یک از تیم‌ها برابر باشد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:46:15', 6, 'done'),
(1550, '۲۸- اگر $a$ و b$$ و $c$ اعداد طبیعی یک‌رقمی باشند، چند معادله درجه دوم به فرم $ax^2-bx-2c=0$ وجود دارد که یک ریشه آن $\\frac{-2c}{a}$ باشد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:46:36', 6, 'done'),
(1551, ' با اعداد 5،5،7،۷،۹،۹، چند عدد شش‌رقمی می‌توان ساخت که در آن ۷۹۵ دیده شود؟', 1, 1, 2, 264, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:46:45', 6, 'done'),
(1552, ' خانواده‌ای، آنقدر فرزندآوری می‌کند تا برای سومین بار صاحب فرزند پسر شود. اگربا به دنیا آوردن نهمین فرزند به خواسته خود برسد، چند حالت وجود دارد؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:47:40', 6, 'done'),
(1553, ' یک تیم ملی فوتبال ۱۱ نفره فوتبال که افراد کنعانی، چشمی و خلیل‌زاده جز آن‌ها هستند را در نظر بگیرید. به چند طریق می‌توان از آن‌ها یک گروه ۷ نفره انتخاب کنیم به طوری که اگر کنعانی در گروه باشد، خلیل‌زاده نیز باشد و اگر چشمی انتخاب شود، خلیل زاده انتخاب نشود؟', 1, 1, 2, 265, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 22:02:41', 1, '2026-03-27 21:48:38', 6, 'done'),
(1554, ' تابع با ضابطه در چند نقطه از بازه حد ندارد؟', 2, 1, 44, 191, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:22', 1, '2026-03-27 21:49:32', 6, 'done'),
(1555, 'حاصل کدام است؟ ( [ ]، نماد جزء صحیح است.)', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 21:50:06', 6, 'done'),
(1556, 'حدهای راست و چپ تابع در دو نقطه، 2 واحد اختلاف دارند. فاصله بین این دو نقطه کدام است؟ ( [ ]، نماد جزء صحیح است.)', 2, 1, 44, 191, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 21:50:52', 6, 'done'),
(1557, 'اگر و به طوری که در حد داشته باشد، مقدار کدام است؟ ( [ ]، نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 21:59:27', 6, 'done'),
(1558, '-5نمودار تابع با ضابطه رسم شده است. کدام گزینه صحیح نیست؟ ( [ ]، نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:04:59', 6, 'done'),
(1559, '-6با توجه به نمودار تابع . حاصل کدام است؟ ( [ ]، نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:05:14', 6, 'done'),
(1560, '-7حد عبارت وقتی کدام است؟ ( [ ]، نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:06:01', 6, 'done'),
(1561, '-8اگر آنگاه حاصل کدام است؟ ( [ ]، نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:06:23', 6, 'done'),
(1562, '9- حاصل کدام است؟', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:06:39', 6, 'done'),
(1563, ' اگر $a = \\lim_{x \\to 3} \\frac{x^2 - [x+1]}{2x - \\sqrt{x-1}}$، آن‌گاه حاصل $\\lim_{x \\to a^-} [\\frac{x}{3}]$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', 3, 1, 48, 195, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:06:59', 6, 'done'),
(1564, ' با توجه به نمودار تابع خطی $g$، حاصل $\\lim_{x \\to 1} \\frac{g(2x)}{g^{-1}(x)}$ کدام است؟', 2, 1, 44, 191, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:17:21', 6, 'done'),
(1565, ' اگر حاصل $\\lim_{x \\to -1} \\frac{x^2 - ax - b}{x^2 - x - 2}$ برابر 3 باشد، مقدار $ab$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, '2026-03-27 22:17:45', 6, 'done'),
(1566, '13- اگر تابع $f$ در $x=2$ حد داشته باشد و $\\lim_{x \\to 2^+} \\frac{x^2 f(x) - 4f(x)}{x^2 + 3x - 10} = 4$، آن‌گاه حاصل $\\lim_{x \\to 2} \\frac{x - |x|}{f(x) - [x]}$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1567, '14- اگر $ab = \\lim_{x \\to 2} \\frac{\\sqrt{x - a} - a}{x - 2}$، آن‌گاه $b$ کدام است؟ ($a, b \\in R$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(1568, '15- نمودار تابع با ضابطه $y = f(x)$ رسم شده است. حاصل $\\lim_{x \\to 2^-} \\frac{|3 - f(x)|}{\\sqrt{1 + f(x)}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1569, '16- تابع $f(x) = \\begin{cases} (x+1)[x] & -2 < x < 0 \\\\ ax^2 + b & |x+1| \\ge 1 \\end{cases}$ در تمام نقاط $R$ پیوسته است. مقدار $ab$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1570, '17- تابع $f(x) = (x+1)|x|[x]$ در بازه $(-2, k)$ پیوسته است. حداکثر مقدار $k$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1571, '18- نمودار تابع درجه دوم $f$ محور $x$ها را در نقاط با طول‌های $1-$ و $5$ قطع می‌کند. اگر تابع $g(x) = \\begin{cases} 2x-1 & x > 3 \\\\ f(x) & x \\le 3 \\end{cases}$ در $x=3$ پیوسته باشد، خط $x=1$ نمودار تابع $g$ را با کدام عرض قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1572, '19- کدام تابع روی مجموعه $R$ پیوسته است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1573, '20- چهارمین نقطه ناپیوستگی تابع $f(x) = [\\log_2(2x+1)]$ با طول مثبت کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1574, '21- در تابع $f(x) = \\begin{cases} 2^x & x > 2 \\\\ [\\sqrt{x}] & x < 2 \\end{cases}$، اختلاف حدهای چپ و راست تابع در $x=2$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1575, '22- حاصل $\\lim_{x \\to -2^+} \\frac{|x^3| + |x| - 6}{2[|x|] + x}$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1576, '23- نمودار تابع $f$ مطابق شکل داده شده است. اگر $\\lim_{x \\to a^+} f(-x) = -a - 1$ باشد، مقدار $a$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1577, '24- نمودار تابع درجه‌دوم $f$ و تابع خطی $g$ به شکل زیر هستند. حاصل $\\lim_{x \\to 3} (\\frac{f}{g})(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1578, '25- نمودار تابع $f(x) = \\frac{ax+b}{x^2-1}$ در همسایگی $x=1$ داده شده است. مقدار $a-b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1579, '26- اگر $f(x) = \\begin{cases} x+a & x^2 < 2x \\\\ bx^2-x-1 & x^2 \\ge 2x \\end{cases}$ روی $R$ پیوسته باشد، حاصل $a-b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1580, '27- تابع $f(x) = a[x] - [x^2]$ در $x=2$ پیوسته است. مقدار $a$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1581, '28- تابع $f(x) = (x^2 - ax - b)[\\frac{1}{x}]$ در بازه $(0, 8)$ پیوسته است. حاصل $ab$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1582, '29- مجموعه جواب‌های نامعادله $|2x+a| < b$ یک همسایگی چپ 7 و یک همسایگی راست 3 است. حاصل $2a-b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1583, '30- اگر باقی‌مانده تقسیم $f(x) = x^3+ax^2-x-b$ بر $x-1$ و $x+2$ به ترتیب از راست به چپ 2 و 3- باشد، باقی‌مانده تقسیم $f(f(x))$ بر $x+2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1584, '31- حاصل $\\lim_{x \\to \\frac{\\pi}{3}} \\frac{3 - \\tan^2 x}{\\sin 2x - \\sin x}$ چند برابر $\\sqrt{3}$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1585, '32- تابع با ضابطه $f(x) = \\begin{cases} \\frac{2-\\sqrt{x}}{\\sqrt{x+12}-4} & x \\ne 4 \\\\ a & x = 4 \\end{cases}$ برای $x > 0$ تعریف شده است. اگر $f$ پیوسته باشد، مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1586, '33- نمودار تابع $f(x) = \\frac{[x]+|-x|}{x^2+2x+1}$ در همسایگی $x = -1$ شبیه کدام گزینه است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1587, '34- اگر $f(x) = \\frac{x^2}{x-1}$ باشد، $\\lim_{x \\to 0^-} f(f(x+1))$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1588, '35- حاصل $\\lim_{x \\to (\\frac{\\pi}{4})^+} \\frac{[\\tan x] - [\\cot x]}{\\sin x - \\cos x}$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1589, '36- اگر $c$ عددی صحیح باشد و $\\lim_{x \\to 2^+} \\frac{x+c}{x^2+ax+b} = -\\infty$، حداکثر مقدار $a+b+c$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1590, '37- حد تابع $f(x) = \\frac{ax - \\sqrt{x^2+x+b}}{x-3}$ وقتی $x \\to -\\infty$ برابر 2 است. اگر حد تابع $f$ در $x=3$ موجود باشد، مقدار آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1591, '38- توابع $f(x) = \\sqrt{x^2+4x}$ و $g(x) = x-2$ مفروض‌اند. حاصل $\\lim_{x \\to -\\infty} (\\frac{f}{g})(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1592, '39- اگر $f(x) = [\\frac{3x^2+1}{x^2-1}]$، حاصل $\\lim_{x \\to +\\infty} f(x)$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1593, '40- اگر $f(x) = \\frac{\\sqrt{1-\\cos x}}{\\sin x}$ و $g(x) = \\frac{2x}{x^2+1}$، حاصل $\\lim_{x \\to 0^-} (f \\circ g)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1594, '41- اگر $a = 3 - \\sqrt{2}$ باشد، حاصل $\\lim_{x \\to \\infty} (a-1)^x + \\lim_{x \\to 0^+} \\log_{(1+a)} x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1595, '42- با توجه به نمودار تابع $f$، حاصل $\\lim_{x \\to 1^-} f^{-1}(x) + [\\lim_{x \\to 0^+} \\frac{1}{f^{-1}(x)}]$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1596, '43- در یکی از ریشه‌های معادله درجه‌دوم $5x^2 + ax - 2b = 0$، تابع $f(x) = \\frac{2x^2 - ax - b}{x+1}$ حد دارد ولی ناپیوسته است. جزء صحیح ریشه دیگر معادله درجه‌دوم کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1597, '44- تابع $f(x) = \\begin{cases} \\frac{\\sin^2 \\frac{\\pi}{x}}{x^2-3x+2} & 1 < x \\le 2 \\\\ \\frac{a(4-x^2)}{|x^2-3x+2|} & 2 < x < 6 \\\\ b([x]-[\\frac{1}{x-1}]) & x \\ge 6 \\end{cases}$ روی بازه $[2, 6]$ پیوسته است. مقدار $8a^2b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1598, '45- اگر $\\lim_{x \\to (\\frac{\\pi}{2})^-} (\\frac{b - 2ax}{a \\cos 2x - \\sin x}) = -\\infty$، آن‌گاه بزرگ‌ترین مقدار صحیح قابل قبول برای $b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1599, '46- حاصل $\\lim_{x \\to (-2)^-} \\frac{(-1)^{[x]}(1 - \\cos \\pi x)}{\\sin \\pi x}$ کدام است؟ ($[.]$، نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1600, '47- اگر $f(x) = a + x(x-b)$ و $\\lim_{x \\to 1} \\frac{|f(x)|}{x-1} = 0$، آن‌گاه حاصل $\\lim_{x \\to -\\infty} (x + \\sqrt{f(x)-x})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1601, '48- نمودار تابع درجه‌دوم $f$ رسم شده است. اگر $g(x) = \\frac{x}{x-2}$، آن‌گاه حد تابع $(f \\circ g)(x)$ وقتی $x \\to 2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:14:23', 1, NULL, NULL, 'free'),
(1602, ' اگر میانگین و واریانس داده‌های $x_۱, x_۲, \\dots, x_{۱۰}$ به‌ترتیب برابر ۵ و ۴ باشد، ضریب تغییرات داده‌های $۳x_۱ + ۲, ۳x_۲ + ۲, \\dots, ۳x_{۱۰} + ۲$ کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:19:52', 4, 'done'),
(1603, ' کدام‌یک از متغیرهای زیر کیفی ترتیبی است؟', 2, 1, 1, 259, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:20:20', 4, 'done'),
(1604, ' اگر واریانس داده‌های $۴, a - ۲$ و $b + ۶$ برابر صفر باشد، مقدار $ab$ کدام است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:22:08', 4, 'done'),
(1605, ' ضریب تغییرات داده‌های آماری زیر تقریباً کدام است؟\n\n$۸, ۸, ۸, ۹, ۹, ۹, ۹, ۹, ۹, ۱۲, ۱۲, ۱۲, ۱۲, ۱۲, ۱۲$', 2, 1, 1, 262, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:45:45', 4, 'done'),
(1606, 'انحراف معیار تعدادی داده آماری صد برابر ضریب تغییرات آن‌ها است. مجموع آن‌ها کدام می‌تواند باشد؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:46:09', 4, 'done'),
(1607, ' در داده‌های آماری $۱, ۲, ۱۲, ۱۳, ۵, ۸, ۱۰, ۵, ۷, ۱۲, ۲$ به داده‌های بیشتر از چارک اول و کمتر از چارک سوم ۵ برابر میانه را اضافه می‌کنیم. انحراف معیار داده‌های آماری بین چارک اول و سوم بعد از این کار و بدون مرتب کردن مجدد داده‌ها چند برابر $\\sqrt{۰/۱}$ است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:22:40', 4, 'done'),
(1608, ' میانگین و انحراف معیار ۱۲ دادهٔ آماری به‌ترتیب برابر ۱۶ و ۲ است. اگر یکی از داده‌ها از ۱۸ به ۱۷ و دادهٔ دیگر از ۱۵ به ۱۶ تغییر کند، واریانس جدید داده‌ها کدام است؟', 2, 1, 1, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-02-25 23:48:55', 5, 'done'),
(1609, ' نمرات مهارت برای کارگر «الف»، $۸۰, ۸۲/۵, ۸۰, ۷۷/۵, ۶۵$ و برای کارگر «ب»، $۸۰, ۷۵, ۷۰, ۶۵$ و $۶۰$ بوده است. دقت عمل کدام بیشتر است؟', 2, 1, 1, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-02-25 23:49:11', 5, 'done'),
(1610, ' چه تعداد از متغیرهای زیر کمی پیوسته است؟\n\nالف) سرعت یک خودرو\n\nب) تعداد ماهی‌های یک دریا\n\nپ) جنسیت افراد\n\nت) وزن یک شخص', 1, 1, 1, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-02-25 23:45:03', 5, 'done'),
(1611, ' اگر واریانس داده‌های $۲a-۱, ۳b+۱, ۴c+۳$ و $۷$ برابر صفر باشد، ضریب تغییرات داده‌های $a-۱, b^۲$ و $۵c^۳$ کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:39:14', 4, 'done'),
(1612, ' چه تعداد از متغیرهای زیر کیفی ترتیبی هستند؟\n\nالف) تعداد کتاب‌های مطالعه‌شده\n\nب) وزن سیب‌های یک باغ\n\nج) میزان رضایت افراد از یک فیلم\n\nد) میزان بارندگی برحسب میلی‌متر\n\nهـ) مراحل رشد گیاه\n\nو) تعداد تصادف در طول یک ماه', 2, 1, 1, 259, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:46:28', 4, 'done'),
(1613, ' اگر میانگین و انحراف معیار داده‌های $a-۵, b-۴$ و $c-۷$ برابر صفر باشد، ضریب تغییرات داده‌های $۲a-۹, ۳b-۱۰$ و $۵c-۲۹$ چقدر است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:22:59', 4, 'done'),
(1614, 'میانگین و واریانس ۴ دادهٔ آماری به‌ترتیب برابر ۴ و ۲/۵ و میانگین و واریانس ۵ دادهٔ آماری دیگر به‌ترتیب ۴ و ۳ می‌باشد. تمام داده‌ها را در یک گروه قرار می‌دهیم. انحراف معیار این گروه چند است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:23:32', 4, 'done'),
(1615, ' در داده‌های آماری ۲۶، ۲۷، ۲۶، ۳۵، ۲۲، ۲۶، ۲۶، ۳۴، ۳۰، انحراف معیار $Q_۱, Q_۲$ و $Q_۳$ تقریباً کدام است؟ ($Q_۱, Q_۲$ و $Q_۳$ به‌ترتیب چارک‌های اول تا سوم هستند.)', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:24:17', 4, 'done'),
(1616, ' ده عدد با میانگین $\\bar{x}$ و واریانس ۴ داریم. چند عدد برابر با میانگین به آن‌ها اضافه کنیم تا واریانس داده‌ها به ۲ برسد؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:42:37', 4, 'done'),
(1617, 'میانگین داده‌های مثبت $x_۱, \\dots, x_n$ برابر $\\bar{x}$ است. اگر به هریک از داده‌ها $k\\bar{x}$ اضافه کنیم، ضریب تغییرات داده‌های جدید $\\frac{۱}{۹}$ ضریب تغییرات داده‌های اولیه می‌شود. عدد $k$ کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, '2026-03-27 21:24:39', 4, 'done'),
(1618, '۱۷- ضریب تغییرات تعدادی داده ۰/۰۸ است. اگر به هر کدام از آن‌ها ۵ واحد اضافه شود، ضریب تغییرات ۰/۰۷۵ خواهد شد. میانگین داده‌های اولیه کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-22 23:24:35', 1, NULL, NULL, 'free'),
(1619, ' در یک روستا با جمعیت ۵۰۰ نفر، جهت بررسی وضعیت بیماری کرونا از $\\frac{1}{4}$ افراد آن روستا تست کرونا گرفته شده است. با مثبت شدن تست کرونای $\\frac{1}{2}$ افراد تست شده، به ترتیب از راست به چپ اندازهٔ جامعه، حجم نمونه و متغیر در این بررسی کدام است؟', 2, 1, 1, 259, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:40:02', 4, 'done'),
(1620, ' کدام گزینه دارای دقیقاً دو متغیر کمی پیوسته و دقیقاً یک متغیر کیفی اسمی است؟', 2, 1, 1, 259, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:24:59', 4, 'done'),
(1621, ' اختلاف میانگین داده‌های $۱۱/۴, ۱۲/۱, ۱۲/۲, ۱۳/۲, ۱۳/۱, ۱۴/۲$ از میانهٔ آنها چقدر است؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:25:18', 4, 'done'),
(1622, ' تفاضل پنج دادهٔ آماری از میانگین آنها به‌صورت $x-۱, ۰, ۶, x+۱۱, x$ می‌باشد. در این‌صورت دامنهٔ تغییرات این داده‌ها برابر کدام گزینه است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:43:03', 4, 'done'),
(1623, ' داده‌های زیر نرخ تورم در ۱۰ سال اخیر است. ضریب تغییرات داده‌های کمتر از چارک دوم کدام است؟\n\n$۱۰, ۲۰, ۳۰, ۴۰, ۵۰, ۶۰, ۷۰, ۸۰, ۹۰, ۱۰۰$', 2, 1, 1, 262, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:46:50', 4, 'done'),
(1624, ' در ۶۰ دادهٔ آماری، میانگین ۳ و انحراف معیار ۱/۲ محاسبه شده است. اگر به تمام داده‌ها ۹ واحد اضافه شود، ضریب تغییرات داده‌ها چه تغییری می‌کند؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:25:41', 4, 'done'),
(1625, ' در یک شرکت تجاری دو کارمند به‌طور آزمایشی برای جذب در یک پست مشغول به کار هستند، میانگین و واریانس ساعات مفید کاری در طول هفته برای فرد اول به‌ترتیب از راست به چپ ۵۶ و ۱۶ و برای فرد دوم به‌ترتیب ۴۹ و ۹ است. کدام کارمند برای استخدام مناسب‌تر است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:25:59', 4, 'done'),
