(1651, ' اگر میانگین داده‌های $x_۱ - ۱$ و $x_۲ - ۱$ و $\\dots, x_n - ۱$ و همچنین واریانس داده‌های $x_۱ + ۳$ و $x_۲ + ۳$ و $\\dots, x_n + ۳$ برابر ۹ باشند، ضریب تغییرات داده‌های $۳x_۱ - ۵$ و $۳x_۲ - ۵$ و $\\dots, ۳x_n - ۵$ کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:38:07', 4, 'done'),
(1652, ' اگر میانگین و واریانس نمرات دانش‌آموزان سه کلاس $A$، $B$ و $C$ به‌صورت زیر باشد، یک معلم ترجیح می‌دهد در کدام کلاس تدریس کند؟ ($\\sqrt{۵} \\simeq ۲/۲۵$) «ملاک معلم این است که کلاسی که نمرات دانش‌آموزان پراکندگی کمتری دارند انتخاب کند.»\n\n\\begin{center}\n\n\\begin{tabular}{|c|c|c|c|}\n\n\\hline\n\n& $A$ & $B$ & $C$ \\\\ \\hline\n\nمیانگین & ۱۸ & ۱۹ & ۱۷ \\\\ \\hline\n\nواریانس & ۴ & ۹ & ۵ \\\\ \\hline\n\n\\end{tabular}\n\n\\end{center}', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:36:46', 4, 'done'),
(1653, ' یک جامعه با اندازهٔ ۱۲ و واریانس ۱۲/۶، با جامعهٔ دیگری با اندازهٔ ۲۴ و واریانس ۷/۲، تشکیل جامعهٔ جدیدی داده‌اند. اگر میانگین این دو جامعه یکسان باشد، انحراف معیار جامعهٔ جدید کدام است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-22 23:24:57', 1, '2026-03-27 21:36:23', 4, 'done'),
