(1693, ' با فرض $f(x) = 2x + \\sqrt{x + 3}$، جواب نامعادله $f^{-1}(2x) \\leq 6$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:27:01', 6, 'done'),
(1694, ' تابع $f(x) = \\frac{3x + a}{x - 1}$ وارون خودش را در نقطه‌ای روی خط $y = 2x - 5$ قطع می‌کند. مقدار $a$ چه عددی است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:27:14', 6, 'done'),
