(1697, ' با فرض $f(x) = \\frac{1}{3-x}$، هرگاه $f^{-1}(x)-f(x+k)$ تابعی ثابت باشد، $k$ چه عددی است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:28:25', 6, 'done'),
(1698, ' هرگاه $f(x) = \\frac{3}{2x-1}$ باشد، به طوری که $f^{-1}(x-a)=f(x)+b$، مقدار $a+b$ چه عددی است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:28:41', 6, 'done'),
(1699, 'هرگاه $f(x) = 2x+3|x-1|$ و $g(x) = \\sqrt{2x-x^2}$ باشد، دامنه تعریف تابع $gof(x)$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:28:59', 6, 'done'),
(1700, ' هرگاه $f(x) = \\frac{x}{2x+1}$ باشد، به طوری که $fog(x) = (\\frac{1}{f}of)(x)$، ضابطه $g^{-1}(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:29:13', 6, 'done'),
(1701, 'هرگاه $ 6 x+1 = (2)f^{-1}(2x)-f(2x)$ باشد، ضابطه وارون تابع $y=4f(3x)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:29:39', 6, 'done'),
(1702, ' نمودار تابع $f(x) = x^2+\\sqrt{x-1}$ را نسبت به خط $y=x$ قرینه کرده و نمودار به دست آمده را $k$ واحد به سمت چپ انتقال می‌دهیم اگر نمودار حاصل نمودار تابع $y=f(x)$ را در نقطه‌ای به طول $x=2$ قطع کند، مقدار $k$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:30:09', 6, 'done'),
(1703, ' هرگاه تابع $f(x) = 3x+\\sqrt{x+2}$ با برد $[-2 , 8]$ باشد، نقطه میانی دامنه تعریف آن کدام است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:30:38', 6, 'done'),
(1704, ' هرگاه $f(x) = \\sqrt{4-x}$ و $g(x) = fof(x)$ باشد، نمودار $y = gog^{-1}(x) + g^{-1}og(x)$ یک پاره‌خط به طول $d$ است. مقدار $d$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:31:01', 6, 'done'),
(1705, ' چه تعداد از روابط زیر بیانگر یک تابع می‌باشد؟\n\nالف)  $\\sin y = x$\n\nب)  $y(x-1) = 0$\n\nپ) $x^2+y^2-2y+6x+10 = 0$\n\nت)  $f(x) = \\begin{cases} x^2 & , x \\geq 1 \\\\ [-x]+1 & , x \\leq 1 \\end{cases}$', 1, 1, 41, 175, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:31:21', 6, 'done'),
(1706, ' چه تعداد از جفت توابع زیر با یکدیگر برابرند؟\n\nالف) $\\begin{cases} f(x)=\\sqrt{x^2} \\\\ g(x)=x\\sqrt{x} \\end{cases}$\n\nب) $\\begin{cases} f(x)=[x^2] \\\\ g(x)=[x]^2 \\end{cases}$\n\nپ)  $f(x)=x^2+x$ و $g(x)=\\begin{cases} \\frac{x^3-x}{x-1} & , x\\neq 1 \\\\ 2 & , x=1 \\end{cases}$\n\nت)  $\\begin{cases} f(x)=\\log \\frac{x-1}{x} \\\\ g(x)=2 \\log \\sqrt{\\frac{x-1}{x}} \\end{cases}$', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:31:36', 6, 'done'),
(1707, ' اگر $f(x)=\\frac{x+1}{x+2}$ و $g=\\{(-2, 3), (1, -2), (0, -1), (-\\frac{3}{5}, \\frac{1}{2}), (-1, 2)\\}$ باشد، برد تابع $y = \\frac{f+g^{-1}}{g^{-1}+2}$ شامل چند عضو است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:32:00', 6, 'done'),
(1708, ' اگر در تابع $f$ برای هر $x_1, x_2 \\in D_f$ رابطه $x_1 > x_2 \\Rightarrow f(x_2) < f(x_1)$ برقرار باشد، دامنه تابع $y = \\sqrt{f(x^2)-f(x+2)}$ است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:32:22', 6, 'done'),
(1709, ' اگر $f(x)=\\sqrt{x+3}$ باشد و نمودار دو تابع $f^{-1}$ و $g(x)=4x+1$ در ۲ نقطه A و B است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:33:08', 6, 'done'),
(1710, ' اگر $g(x)=\\sqrt{x-1}$ و $f(x)=3-2g(x)$ باشند، معادله $(fof^{-1})(x)=g(2x)+g(x)$ چند جواب دارد؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-26 19:36:05', 4, 'done'),
(1711, ' اگر $g(x)=2x+1$ و $(fog)(x)=8x^2+6x+5$ باشند، معادله $(gof)(x)=6x+f(x)$ دارای چند جواب صحیح است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:33:27', 6, 'done'),
(1712, ' برد تابع $y = \\frac{3^x-3}{3^{x+1}+1}$ شامل چند عدد صحیح است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:33:51', 6, 'done'),
(1713, 'چه تعداد از روابط زیر می‌تواند بیانگر ضابطه یک تابع باشد؟\n\nالف)  $|x-1|+|y+1|-1=0$\n\nب)  $|-x^2|+(y-1)^2=\\frac{1}{2}$\n\nج)  $\\sin|x|+\\cos^2 y=1$\n\nد)  $[[x]+y]=0$', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:34:17', 6, 'done'),
(1714, ' هرگاه نمودار تابع $f(x-4)$ بر نیمساز ربع دوم و چهارم منطبق باشد و $fog(x+2)=-x^2$ باشد، ضابطه $ 2 f(x) – g(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:34:39', 6, 'done'),
(1715, ' اگر $f(x)=\\sqrt{x^2-4x}$ و دامنه تعریف تابع $y=\\sqrt{f(2x-1)-f(1-x)}$ بازه $[a, b]$ باشد، حاصل $b-a$ کدام است؟', 3, 1, 43, 189, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:35:05', 6, 'done'),
(1716, ' اگر $f(x)=2+\\sqrt{x-1}$ باشد و داشته باشیم $5 \\times 9^{g(x)} = \\log(x)$ و $f^{-1}$، ضابطه تابع $g(x)$ کدام می‌تواند باشد؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:35:26', 6, 'done'),
(1717, '  اگر $fog^{-1} = \\{(1, 5), (2, 4), (5, 0), (7, 2)\\}$ و $f(x)=2-x$ باشد، حاصل $g \\circ f^{-1}(1) + g \\circ f^{-1}(0)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:35:39', 6, 'done'),
(1718, ' اگر $f^{-1}(x) = 3^{x+1}$ باشد، دامنه تابع $g(x+1)$ شامل چند عدد طبیعی است؟ $g(x) = \\sqrt{\\frac{f(x-1)}{\\sqrt{7x-x^2- 6}}}$', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:36:08', 6, 'done'),
(1719, ' اگر تابع $\\{(2, 1), (6, -5), (1, 3), (8, 10)\\} = f$ و $g(x) = \\frac{\\sqrt{2-\\sqrt{x-2}}}{x^2-4}$ باشد، برد تابع $(\\frac{f-g}{g})(x)$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:36:27', 6, 'done'),
(1720, ' اگر $f(x)=x+2 $ و $|g \\circ f(x)| = |f(x)-1| - |f(x)-4|$ باشد، آنگاه در بازه‌ای که تابع $y=fog(x)$ اکیداً صعودی است، وارون تابع $y$ کدام است؟', 3, 1, 43, 189, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 15:36:54', 6, 'done'),
(1721, ' اگر مجموعه $\\{(2, b^+1), (3, 3), (2, 5), (1, a^2), (b, 4), (1, 9), (a, 2)\\} = f$ تابع باشد، در این صورت $(b-a)$ کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:02:06', 6, 'done'),
(1722, ' اگر $\\{(a, 2), (4, 3), (4, a^2-2a), (-1, a^2)\\} = f$ تابع باشد، در این صورت مجموع ریشه‌های معادله $x^4-6x^3+a^2x^2=0 $ کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:02:18', 6, 'done'),
(1723, '  در کدام‌یک از رابطه‌های زیر، $y$ تابعی از $x$ است؟ (نماد $[x]$ به معنی جزء صحیح $x$ می‌باشد.)', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:02:35', 6, 'done'),
(1724, ' دامنه تابع $f(x) = \\sqrt{(\\sqrt{9-x^2})-8}$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:02:46', 6, 'done'),
(1725, ' اگر شکل مقابل، نمودار $y=f(x)$ باشد، دامنه تابع $y=\\sqrt{xf(x)}$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:03:02', 6, 'done'),
(1726, ' اگر تابع با ضابطه $f(x) = \\begin{cases} \\frac{x^2-ax+b}{x-2} & x \\neq 2 \\\\ 2c+4 & x = 2 \\end{cases}$ یک تابع همانی باشد، حاصل $(a+b+c)$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:03:13', 6, 'done'),
(1727, 'اگر $\\{(2, 4), (-6, 5), (-5, 4), (6, 7)\\} = f$ و $g(x) = \\sqrt[3]{x}-x$ و $f(g(a))=5 $ باشد، در این صورت $a^2+1$کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:03:59', 6, 'done'),
(1728, ' در صورتی که نمودار $f$ مطابق شکل زیر باشد، دامنه تعریف تابع با ضابطه $y = \\sqrt{f(2x+1)-f(x+3)}$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:04:10', 6, 'done'),
(1729, ' به ازای کدام مقدار $a$، برد تابع $f(x) = (x-a) \\times \\frac{|x|}{x}$، مجموعه اعداد حقیقی ($\\mathbb{R}$) است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:04:21', 6, 'done'),
(1730, 'اگر $f(x) = \\frac{3x+1}{2x-1}$، مقدار $f^{-1}(f(2)+1)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:04:38', 6, 'done'),
(1731, 'اگر تابع با ضابطه $f(x) = x^2-2ax$ در بازه $[3, +\\infty)$ یک‌به‌یک باشد، حداکثر مقدار $a$ کدام است؟', 2, 1, 42, 181, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:38:29', 2, 'done'),
(1732, ' ضابطه معکوس تابع $f(x) = \\sqrt{x+2}-4$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:38:48', 2, 'done'),
(1733, ' نمودار تابع با ضابطه $f(x) = \\frac{3x+7}{x-3}$ مفروض است. طول نقاط تلاقی $f$ با $f^{-1}$ کدام است؟', 2, 1, 42, 181, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:39:06', 2, 'done'),
(1734, ' اگر $f = \\{(2, 1), (3, 2), (4, -1), (5, 5)\\}$ و $g = \\{(3, 2), (5, 3), (4, 4), (7, 1)\\}$، در این صورت $(g^{-1}of^{-1}) + g^{-1}$ کدام است؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:39:54', 2, 'done'),
(1735, ' اگر $f(x) = \\sqrt{x-1}$ و $g(x) = \\log(x^2+3x)$، در این صورت دامنه $fog$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:40:19', 2, 'done'),
(1736, ' اگر $f(x+1) = \\frac{x^2+3x-7}{x+3}$، در این صورت مقدار $fof(-1)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:40:40', 2, 'done'),
(1737, 'اگر $f(x) = \\frac{x+3}{x-2}$ و $g = \\{(-1, 4), (3, 2), (2, -1)\\}$، در این صورت حاصل‌ضرب اعضای دامنه تابع $gof$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:41:33', 2, 'done'),
(1738, ' اگر نمودار تابع با ضابطه $f(x) = |x+3|-1$ را $3$ واحد به سمت راست و $2$ واحد به سمت پایین انتقال دهیم، به تابعی چون $g$ خواهیم رسید. مجموع طول و عرض نقطه تلاقی $f$ و $g$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:42:04', 2, 'done'),
(1739, '  نمودار منحنی به معادله $y=x^3+6x^2+12x+10$ شبیه کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:05:13', 6, 'done'),
(1740, ' تابع با دامنه $\\mathbb{R}$ با ضابطه $y=f(x)$ اکیداً صعودی است. دامنه تابع $g(x)=\\sqrt{f(2x+2)-f(x-1)}$ کدام است؟', 3, 1, 43, 189, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:42:49', 2, 'done'),
(1741, ' با فرض $f(x)=x^3-6x^2+12x$، مقدار تابع $g(x)=x^2+x-2g(2)$ به ازای $x=f(2-\\sqrt[3]{9})$ کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:44:05', 2, 'done'),
(1742, ' دامنه تابع خطی $y=\\sqrt[3]{x^3+ax^2+bx-8}$ به صورت $[a, b]$ است. برد این تابع کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:44:37', 2, 'done'),
(1743, 'با فرض $f(x)=2x+[x]$ و $g(x)=x-[x]-2$، اگر تابع $(f+g)(x)$ با دامنه $[a, b]$ تابع همانی باشد، $a+b$ کدام است؟', 1, 1, 41, 267, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:49:05', 2, 'done'),
(1744, ' اگر دامنه تابع $f(x)=\\frac{x^2+1}{2x^2+(\\log_a 3)x+ab}$ به صورت $\\mathbb{R}-\\{-1\\}$ باشد، $b$ کدام است؟', 1, 1, 41, 267, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:47:51', 2, 'done'),
(1745, 'با فرض $f(x)=x-\\sqrt{3-x}$ و $g(x)=x+\\sqrt{3-x}$، تعداد جواب‌های معادله $(f.g)(x)=5x+2$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:48:35', 2, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(1746, ' قرینه نمودار تابع $y=\\sqrt{2x+3}$ را نسبت به محور $y$ها تعیین کرده و سپس ۱ واحد به سمت راست منتقل می‌کنیم. اگر تابع به وجود آمده از این فرآیند را $f(x)$ بنامیم، فاصله نقطه تلاقی نمودار $f$ و خط $y=x+5$ از نقطه $(-1, 1)$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:49:58', 2, 'done'),
(1747, '۹۰- اگر نمودار تابع $y=f(1-x)$ به صورت مقابل باشد، تعداد جواب‌های معادله $x^2+f(x)=1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:52:46', 2, 'done'),
(1748, ' تعداد جواب‌های معادله $x^2|x-1|=1$ کدام است؟', 2, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:52:40', 2, 'done'),
(1749, ' اگر $f(x)=x^2-x$ باشد، حاصل‌ضرب جواب‌های معادله $fof(x)=6$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:53:37', 2, 'done'),
(1750, 'اگر $f(x)=x-3[\\frac{x}{3}]$ و $g(x)=x^2-2x$ باشند، برد تابع $gof(x)$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:53:56', 2, 'done'),
(1751, ' اگر $f(x+2)=x^2-3 $ و $f(g(x))=x^2+2x-2 $ باشند، ضابطه تابع $(f+g)(x)$ کدام گزینه می‌تواند باشد؟', 3, 1, 43, 187, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:55:03', 2, 'done'),
(1752, ' مجموع طول نقاط برخورد نمودار تابع $f(x)=2-(x-2)^3 $ و وارون آن، کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:58:25', 2, 'done'),
(1753, ' با فرض $f(x)=\\frac{1-x}{x-2}$، ضابطه تابع $g$ کدام باشد تا دو تابع $fog$ و $gof$ همانی باشند؟', 1, 1, 41, 267, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 18:59:07', 2, 'done'),
(1754, ' نمودار تابع $y=||x+3|-|x-1||$ در بازه $[a, b]$ اکیداً نزولی است. ضابطه وارون تابع در این بازه کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:05:32', 6, 'done'),
(1755, ' با فرض $f(x)=\\frac{x-3}{x+1}$ و $(gof)^{-1}=\\frac{x-1}{6}$، نمودار تابع $f(g(x))$ از کدام ناحیه محورهای مختصات نمی‌گذرد؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:05:49', 6, 'done'),
(1756, ' با فرض $f(x)=1+\\sqrt[3]{x-2}$ و $g(x)=x^3-3x^2+3x$، نمودار تابع $f^{-1}og^{-1}(x)$ از کدام ناحیه محورهای مختصات نمی‌گذرد؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:06:15', 6, 'done'),
(1757, ' اگر $x_1 $ و $x_2 $ جواب‌های معادله $10^{x^2-x}=2 $ باشند، $x_1+x_1x_2+x_2 $ کدام است؟', 2, 1, 63, 253, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 19:01:08', 2, 'done'),
(1758, ' نمودار توابع $f(x)=a^x$ و $g(x)=(1-2a)^{-x}$ نسبت به محور $y$ها قرینه هستند. فاصله نقطه تلاقی تابع $g(x)$ و تابع $y=f(x)-\\frac{8}{3}$ از نقطه $(-1,1)$ کدام است؟', 2, 1, 63, 253, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-28 19:02:27', 2, 'done'),
(1759, ' نمودار وارون تابع $f(x)=a+2^{x-b}$ به صورت مقابل است. حاصل $f(\\log_23)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 11:00:04', 1, '2026-03-29 12:06:33', 6, 'done'),
