(1900, ' اگر $3f\'(2)-5=\\frac{f(2)+1}{f(1)-2}=4$ باشد، حاصل $\\lim_{h\\to 0}\\frac{f(2+h)-3}{h^2+h}\\times\\lim_{x\\to 2}\\frac{x^2-4}{2f\'(x)-3f(x)}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:18:55', 2, 'done'),
(1901, 'اگر $\\lim_{x\\to 4}\\frac{f(x)-f(4)}{f(x)+x-f(4)-4}=\\frac{3}{4}$ باشد، مقدار $\\lim_{h\\to 0}\\frac{f(4+h)-f(4)}{2h}$ چقدر است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:20:28', 2, 'done'),
(1902, ' اگر $f(x)=\\begin{cases}x+x^3+1 & x=1\\\\ x+x^2 & x\\ne 1\\end{cases}$ و $g(x)=(x^2-1)f(x)$ باشد، $g\'(1)$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:22:00', 2, 'done'),
(1903, ' اگر در تابع $g(x)=x^3+ax$ ، $g\'(0)=3$ باشد، $g\'(1)g\'(-1)$ چقدر است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:22:36', 2, 'done'),
(1904, 'خط $L$ بر تابع $f(x)$ در نقطه $A$ مماس شده است. اگر طول نقاط $A$ و $B$ به ترتیب 1 و 5 باشد، حاصل $f\'\'(1)+f(1)$ کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 12:41:53', 6, 'done'),
(1905, ' چند نقطه بر تابع $y=x^3+3x^2+3x$ وجود دارد که مماس در آن‌ها موازی خط $3x+4y=7$ باشد؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 12:42:18', 6, 'done'),
(1906, 'مشتق چپ تابع $f(x)=\\frac{\\sqrt{x}|1-x^3|}{1+x}$ در $x=1$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:23:01', 2, 'done'),
(1907, 'معادله نیم‌مماس راست تابع $f(x)=|-x||16-x^2|$ در $x=4$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:23:39', 2, 'done'),
(1908, 'اگر $\\lim_{x\\to 3}\\frac{f(x)-f(3)+2x-6}{x^2-9}=1$ باشد، مشتق تابع $y=xf(3x)$ در $x=1$ کدام است؟ $(3,4)\\in f(x)$', 3, 1, 49, 209, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:24:13', 2, 'done'),
(1909, 'فقط در یک نقطه از دامنه تابع $f(x)=\\sqrt{mx^2+\\frac{x}{2}-1}$ مشتق وجود ندارد. در همین نقطه معادله خط مماس کدام می‌تواند باشد؟', 3, 1, 49, 214, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:25:43', 2, 'done'),
(1910, ' در صورتی که $f(x)=(\\sqrt{x+2}-\\sqrt{x-1})^{1401}$ و $g(x)=(\\sqrt{x+2}+\\sqrt{x-1})^{1400}$ مقدار مشتق تابع $h(x)=(fg)(x)$ در نقطه‌ای به طول $2$ چند برابر $3^{1400}$ است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:26:33', 2, 'done'),
(1911, 'دو تابع $f(x)=x^2+1$ و $g(x)=-x^2+bx+c$ در نقطه‌ای به طول $1$ بر هم مماس‌اند. شیب خط مماس بر تابع $g(x)$ در نقطه‌ای به طول $2$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:27:29', 2, 'done'),
(1912, 'اگر خط مماس بر تابع $g(x)$ در نقطه $(1,4)$ بر خط مماس بر تابع $f(x)$ در نقطه‌ای به طول $4$ عمود باشد، با شرط این‌که $(fog)(x)=2\\sqrt{x}+2ax-1$ ، مقدار $a$ چقدر است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:51:24', 2, 'done'),
(1913, ' در صورتی که $2f(2)=2f\'(2)=6$ باشد، حاصل $A=\\lim_{x\\to2}\\frac{2f^2(x)-4x}{x^2-2x}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:51:55', 2, 'done'),
(1914, 'خط مماس بر تابع $f(x)=\\sqrt[3]{\\left(\\frac{2x+1}{x-2}\\right)^3}$ در نقطه‌ای به طول $-3$ ، واقع بر آن محور عرض‌ها را با کدام عرض قطع می‌کند؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:52:33', 2, 'done'),
(1915, 'اگر $f(x^2-4)=xg(2x+1)$ و $g(3)=g\'(3)=1$ باشد، مقدار $f\'(-3)$ کدام است؟', NULL, 1, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:53:02', 2, 'done'),
(1916, 'در صورتی که $f(x)=\\frac{1}{\\sqrt[3]{x}}$ باشد، مشتق تابع $g(x)=\\frac{x}{f\'(x)}$ به ازای $x=8$ کدام است؟', NULL, 1, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:54:21', 2, 'done'),
(1917, ' در کدام نقطه از منحنی $y=\\frac{1}{4}(x-1)^4+\\frac{1}{7}$ خط مماس بر منحنی، بر خط $8y+x=14$ عمود است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:55:16', 2, 'done'),
(1918, 'به ازای کدام مقادیر $a$ که تابع $f(x)=\\frac{x(x-4)+4}{[x]^2+a^2}$ در $x=2$ مشتق‌پذیر است؟', 3, 1, 49, 214, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:56:23', 2, 'done'),
(1919, 'آهنگ متوسط تابع $f(x)=\\frac{1}{\\sqrt{x}}$ در بازهٔ $[1,9]$ برابر آهنگ لحظه‌ای تابع در $x=c$ است. cکدام است؟', NULL, 1, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:56:47', 2, 'done'),
(1920, 'در مورد تابع $f(x)=\\begin{cases}|x-1| & x\\le1 \\\\ x^3+1 & x>1\\end{cases}$ کدام گزینه صحیح است؟', 3, 1, 49, 214, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:57:27', 2, 'done'),
(1921, ' هر دو تابع $f(x)=\\frac{x^3}{3}+4x+k$ و $g(x)=2x^2-1$ بر یک خط در یک نقطه مماس هستند. مقدار $k$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:51:54', 4, 'done'),
(1922, ' شیب خط مماس بر تابع $f(x)=x^2\\log ₄x-2\\log₂ x$ در نقطه‌ای به طول $2$ واقع بر منحنی کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:52:15', 4, 'done'),
(1923, ' اگر $f(x)=\\sqrt{x}+3x+\\sin 4$ باشد مقدار $f\'\'(16)$ کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:52:42', 4, 'done'),
(1924, ' اگر $f\'(x)=\\sin\\frac{\\pi x}{4}+\\log_2 x$ باشد حاصل $\\lim_{h\\to0}\\frac{f(2+h)-f(2)}{20h}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:53:05', 4, 'done'),
(1925, 'تابع چندجمله‌ای $f(x)$ را بر $x^2+x+1$ تقسیم کرده‌ایم. خارج قسمت و باقی‌مانده به‌ترتیب $kx^2+x+k$ و $x-2$ است. اگر باقی‌مانده تقسیم $f(x)$ بر $x-1$ برابر $-3$ باشد، $k$ کدام است؟', 3, 1, 48, 387, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:58:15', 2, 'done'),
(1926, '۴۹- اگر $f(x)=\\frac{1}{\\sqrt{x^2+1}}$ باشد، مشتق تابع $g(x)=\\frac{1}{f\'(x)}$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:53:55', 4, 'done'),
(1927, '۵۰- در صورتی که $f(x)=3x+2$ باشد، مشتق تابع $g(x)=f(xf(x))+f\\left(\\frac{x}{f(x)}\\right)$ در نقطه $x=2$ چند برابر $3$ است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:53:32', 4, 'done'),
(1928, ' اگر $f$ و $g$ روی $\\mathbb{R}$ مشتق‌پذیر باشند و همچنین $g(2)+3f\'(3)+5g\'(2)+4=7$ باشد، مشتق تابع $h(x)=f(g(x))$ در $x=2$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:54:29', 4, 'done'),
(1929, '۵۲- اگر $f(x)=\\frac{2x+3}{x+1}$ باشد، $f^{-1}(x)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:56:49', 4, 'done'),
(1930, '۵۴- کدام تابع در $x=2$ گوشه‌دار است؟', 3, 1, 50, 217, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:54:52', 4, 'done'),
(1931, ' اگر خط $\\Delta$ با شیب $3$ در نقطه $(2,5)$ بر تابع $g(x)$ مماس باشد، حاصل $\\lim_{x\\to2}\\frac{x^3-8}{5-g(x)}$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:55:18', 4, 'done'),
(1932, ' خطی که از دو نقطه $A(3,-1)$ و $B(2,-4)$ می‌گذرد بر تابع $f(x)$ در نقطه‌ای به عرض $20$ مماس است. حاصل $\\lim_{x\\to10}\\frac{f^2(x)-20f(x)}{2x-20}$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:57:34', 4, 'done'),
(1933, '۵۷- خط $L$ طبق شکل زیر در نقطه $B$ بر تابع $\\sqrt{x}$ مماس است. مساحت مستطیل $OABC$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:56:06', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(1934, ' تابع $f(x)=\\begin{cases}ax^3+x^2 & x\\ge1 \\\\ 4x+2b & x<1\\end{cases}$ در $x=1$ مشتق‌پذیر است. مقدار $\\frac{f(0)}{f\'(2)}$ چقدر است؟', 3, 1, 49, 214, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 21:01:56', 4, 'done'),
(1935, 'اگر $\\frac{x+2}{x-3}=\\frac{2x-6}{x+2}+\\frac{3x+6}{x-3}$ باشد، آنگاه $f\'(1)$ برابر است با:', NULL, 1, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:59:02', 2, 'done'),
(1936, 'اگر $f(x+1)=g(x)+h(x)-x$ و $\\lim_{h\\to0}\\frac{g(3)-g(h+3)}{h}=3$ و $\\lim_{x\\to4}\\frac{f(x)-f(4)}{x-4}=-8$ و $f$ و $g$ مشتق‌پذیر باشند، آنگاه $h\'(3)$ برابر است با:', 3, 1, 49, 209, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 01:59:47', 2, 'done'),
(1937, 'اگر $f(a)=2$ و $f\'(a)=1$ و $g(a)=-1$ و $g\'(a)=-2$ باشند، آنگاه حاصل $\\lim_{x\\to a}\\frac{g(x)f(a)-g(a)f(x)}{x-a}$ برابر است با:', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-29 02:01:01', 2, 'done'),
(1938, ' اگر $f(x)=(x^2-1)(x^2+x+1)(x^2-x+1)$ باشد، آنگاه $f\'\'(\\sqrt{2})$ برابر است با:', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 21:18:10', 4, 'done'),
(1939, ' اگر $f$ تابعی مشتق‌پذیر و $2x^4-x^3+mx^2+nx+p=(x-3)f(x)$ و $f\'(3)=95$ باشد، آنگاه مقدار $m$ برابر است با:', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:16:24', 1, '2026-03-27 20:58:12', 4, 'done'),
(1940, ' در یک دایره، طول کمان روبه‌رو به زاویهٔ $160^\\circ$ برابر $16\\pi$ است. شعاع دایره کدام است؟', 2, 1, 46, 202, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:00:58', 4, 'done'),
(1941, ' برد تابع $y = 2\\sin x - 1$ کدام است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 20:58:51', 4, 'done'),
(1942, ' در چهارضلعی روبه‌رو $AB = AD$ و $BC = CD$ و زاویهٔ $A$ قائمه است. اگر طول قطر $AC$ برابر $5\\sqrt{2}$ و مساحت چهارضلعی برابر $30$ باشد، طول ضلع $AB$ کدام است؟', 1, 1, 45, 201, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-29 12:42:53', 6, 'done'),
(1943, 'دربارهٔ تابع خطی $f$ می‌دانیم $f(5) = f(-1) + 2\\sqrt{3}$. زاویه‌ای که این خط با جهت مثبت محور طول‌ها می‌سازد کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-29 02:01:58', 2, 'done'),
(1944, ' اگر $\\alpha$ زاویه‌ای در ربع اول به‌گونه‌ای باشد که $\\sin \\alpha - \\cos \\alpha = 0/2$، مقدار $\\sin \\alpha + \\cos \\alpha$ کدام است؟', 1, 1, 45, 201, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:01:29', 4, 'done'),
(1945, ' مقدار عددی عبارت $A = \\cos 10^\\circ + \\cos 20^\\circ + \\cos 30^\\circ + \\cdots + \\cos 170^\\circ + \\cos 180^\\circ$ کدام است؟', 2, 1, 46, 203, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:03:29', 4, 'done'),
(1946, ' اگر $\\alpha$ زاویه‌ای در ربع سوم به‌گونه‌ای باشد که $\\cos \\alpha = -\\frac{\\sqrt{17}}{17}$، مقدار $\\cot(\\alpha - \\frac{\\pi}{2})$ کدام است؟', 2, 1, 46, 203, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:04:33', 4, 'done'),
(1947, ' اگر $\\cot \\alpha = 10$، مقدار عددی عبارت $A = \\frac{2\\cos(\\frac{\\pi}{2} - \\alpha) - \\sin(\\frac{\\pi}{2} + \\alpha)}{\\cos(\\frac{3\\pi}{2} - \\alpha) + 3\\sin(\\pi + \\alpha)}$ کدام است؟', 2, 1, 46, 203, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:04:06', 4, 'done'),
(1948, 'نمودار تابع $y = 1 + \\cos(x + \\frac{6\\pi}{5})$ در کدام گزینه به‌درستی رسم شده است؟', 3, 1, 47, 206, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:09:18', 4, 'done'),
(1949, ' مقدار عددی کسر $\\frac{\\sin 378^\\circ + 3\\cos 108^\\circ}{\\sin 198^\\circ + 2\\cos 288^\\circ}$ کدام است؟', 2, 1, 46, 203, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:25:30', 1, '2026-03-27 21:04:58', 4, 'done'),
