(2055, ' اگر مجموعهٔ $M$ مجموعهٔ مرجع و $A$ مجموعه‌ای نامتناهی و $A \\subseteq B$ باشد، آنگاه کدام مجموعه، مجموعه‌ای متناهی است؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:51:14', 4, 'done'),
(2056, 'با توجه به الگوی زیر، تعداد مربع‌ها در جملهٔ هشتم دنباله کدام است؟\n\n\\begin{center}\n\n\\end{center}', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:51:42', 4, 'done'),
(2057, ' اگر $a + b$ و $۲b - ۳a$ و $۳a - b$ سه جملهٔ اول یک دنبالهٔ حسابی و $a + ۲b$ و $۲(b - a)$ و $b - ۲$ سه جملهٔ اول یک دنبالهٔ هندسی باشند، نسبت جملهٔ دهم دنبالهٔ هندسی به جملهٔ شانزدهم دنبالهٔ حسابی کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:53:51', 4, 'done'),
(2058, ' حاصل‌جمع سه عدد $a, b, c$ که جملات متوالی یک دنباله هندسی نه صعودی و نه نزولی‌اند برابر ۲۸ است. اگر جملات $c, a, b - ۱۶$ تشکیل یک دنباله حسابی بدهند، اختلاف قدرنسبت‌های دو دنباله حسابی و هندسی کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:54:59', 4, 'done'),
(2059, 'دنباله حسابی ... , ۲۳ , ۱۷ , ۱۱ , ۵ چند جمله ۴ رقمی دارد؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:52:23', 4, 'done'),
(2060, 'دنباله‌ای با الگوی زیر را در نظر بگیرید. تعداد دایره‌های توپر در جمله بیستم چند درصد تمام دایره‌های موجود در همان جمله است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:52:45', 4, 'done'),
(2061, ' مجموع کوچک‌ترین جملهٔ دنبالهٔ $a_n = ۲n^۲ - ۳۵n + ۱۷$ با جملهٔ چهلم دنبالهٔ بازگشتی $b_{n+۱} = b_n + (n + ۱) ; b_۱ = ۱$ کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:56:05', 4, 'done'),
(2062, ' اضلاع یک مثلث قائم‌الزاویه، سه جمله متوالی از یک دنباله هندسی کاهشی هستند. قدرنسبت دنباله کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:53:13', 4, 'done'),
(2063, ' در یک الگوی خطی جملهٔ سوم ۱۴ و جملهٔ هفتم ۲۶ است. حاصل‌جمع بزرگ‌ترین جملهٔ دو رقمی و کوچک‌ترین جملهٔ چهار رقمی این دنباله کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:54:35', 4, 'done'),
(2064, ' اگر دنبالهٔ $t_n: ۶, x, x + y, ۱۸, y + z, ۳۶, \\dots$ یک دنبالهٔ درجه دوم باشد، حاصل $t_{۱۶} + x + y + z + t_۸$ کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-29 15:20:37', 6, 'done'),
(2065, ' اعداد ۱۴ و ۱۷/۲ به‌ترتیب جملات پنجم و هفتم یک دنباله درجه دوم هستند. اگر ضریب بزرگ‌ترین درجه جمله عمومی $\\frac{۱}{۷۰}$ قرینه جمله پنجم باشد، آنگاه مقدار بزرگ‌ترین جمله این دنباله چقدر است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:54:18', 4, 'done'),
(2066, ' در یک دنبالهٔ حسابی، مجموع سه جمله اول ۳ و مجموع سه جمله بعدی آن ۳۹ است. کدام جمله این دنباله حسابی برابر با یازدهمین جمله دنباله با الگوی زیر است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:55:18', 4, 'done'),
(2067, 'دنبالهٔ $a_n$، یک دنبالهٔ حسابی و تابع $f(x)$، یک تابع نمایی است. اگر نقاط $A(a_۱, a_۲)$، $B(a_۴, a_۶)$ و $C(a_۷, a_۸)$ به‌ترتیب روی تابع $f(x)$ قرار داشته باشند، چندمین جملهٔ دنبالهٔ $a_n$ برابر با صفر است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-27 21:56:49', 4, 'done'),
(2068, ' در یک مدرسهٔ ۸۰ نفری، ۴۵ درصد از دانش‌آموزان عضو هیچ‌کدام از گروه‌های ورزش و موسیقی نیستند. اگر ۷۵ درصد از دانش‌آموزان گروه ورزش، عضو گروه موسیقی هم باشند و ۳۰ درصد از دانش‌آموزان گروه موسیقی، عضو گروه ورزش هم باشند، دقیقاً چند نفر فقط عضو یکی از این دو گروه هستند؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-29 15:20:50', 6, 'done'),
(2069, ' در یک مدرسهٔ ۳۰ نفری، ۱۵ نفر عضو تیم فوتبال و ۲۰ نفر عضو تیم بسکتبال هستند. چه تعداد از دانش‌آموزان این مدرسه، عضو هیچ کدام از این دو تیم نیستند؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 12:37:22', 1, '2026-03-29 15:21:16', 6, 'done'),
(2070, 'اگر اختلاف ریشه‌های ششم عدد $\\alpha$ برابر با عدد $1$ و اختلاف ریشه‌های چهارم آن برابر با $\\beta$ باشد، حاصل $\\frac{\\alpha}{\\beta^2}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:21:42', 6, 'done'),
(2071, 'حاصل عبارت $\\sqrt{6}\\cdot\\sqrt{7+4\\sqrt{3}}$ به کدام عدد صحیح نزدیک‌تر است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:22:12', 6, 'done'),
(2072, 'اگر $(8\\sqrt[3]{4\\sqrt{2}})^{\\frac{3}{2}}=(\\sqrt[n]{2})^m$ آن‌گاه حاصل $\\frac{m}{n}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:22:27', 6, 'done'),
(2073, 'اگر $a+b=3$ و $a^3+b^3=18$، آن‌گاه حاصل $\\frac{1}{1+a^8}+\\frac{1}{1+b^8}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:22:38', 6, 'done'),
