(2075, 'جذر عدد $8+\\sqrt{8}+\\sqrt{20}+\\sqrt{40}$ برابر با $1+\\sqrt{2}+\\sqrt{a}$ است. $a$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:23:04', 6, 'done'),
