(2077, '$\\alpha$ و $\\beta$ ریشه‌های دوم عدد $A=16+8\\sqrt{3}$ هستند. حاصل $|\\alpha|+|\\beta|-\\frac{A}{2}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:23:29', 6, 'done'),
(2078, 'اگر $A=\\sqrt{12-\\sqrt{7}}-\\sqrt{5-\\sqrt{7}}$ و $B=3+\\sqrt{7}$ باشند، آنگاه حاصل $\\sqrt[4]{B}\\times\\sqrt{A}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:23:48', 6, 'done'),
(2079, 'اگر $\\sqrt[3]{x}-\\sqrt[3]{x-36}=3$ باشد، آنگاه حاصل $x-\\frac{1}{x}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:23:58', 6, 'done'),
(2080, 'اگر $a$ و $b$ به ترتیب ریشه بزرگتر و ریشه کوچکتر معادله $(x+1)(x+3)=2$ باشند، حاصل $\\frac{a}{b}-7$ کدام است؟', 1, 1, 64, 240, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:24:33', 6, 'done'),
(2081, 'اگر $a=\\frac{1}{\\sqrt[3]{4}+\\sqrt[3]{2}+1}$ باشد، حاصل عبارت $\\frac{1}{3}a^3+a^2+a$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:25:02', 6, 'done'),
(2082, 'اگر $a+b+c=7$ و $a^2+b^2+c^2=31$ و $abc=-5$ باشد، حاصل عبارت $\\frac{1}{a}+\\frac{1}{b}+\\frac{1}{c}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:25:19', 6, 'done'),
(2083, 'در شکل زیر، عدد $x$ از محور بالا به مربع و ریشه‌های دوم و مربع خود روی محور پایین وصل شده است. اگر $\\frac{b}{ac^2}=-\\frac{1}{8}$ باشد، مقدار $\\sqrt[3]{x}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:25:33', 6, 'done'),
(2084, 'اگر $A=\\frac{\\sqrt{8\\sqrt[3]{A}}\\times2^{-\\frac{1}{2}}}{\\sqrt[3]{4\\sqrt{2}}\\times8^{-\\frac{2}{3}}}$ باشد، مقدار $A^{5}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:25:48', 6, 'done'),
(2085, 'اگر $\\sqrt{x-a}+\\sqrt{x-3}=4$ و $a+\\sqrt{x-a}-\\sqrt{x-3}=4$ باشد، مقدار $a$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:26:05', 6, 'done'),
(2086, 'اگر $A$ و $B$ دو عدد طبیعی باشند به طوری که $(\\sqrt{3}-\\sqrt{2})^{3}=A\\sqrt{3}-B\\sqrt{2}$ آنگاه $\\frac{B}{A}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:26:27', 6, 'done'),
(2087, 'اختلاف ریشه‌های چهارم عدد $28-16\\sqrt{3}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:26:38', 6, 'done'),
(2088, 'با فرض $A=\\frac{8+3\\sqrt{3}}{3+\\sqrt{3}}+\\frac{3\\sqrt{3}-8}{7+2\\sqrt{3}}$ ، حاصل $A+\\sqrt{3}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:26:54', 6, 'done'),
(2089, 'حاصل $\\frac{1}{\\sqrt[3]{4}}+\\frac{1.5}{\\sqrt[3]{2}+1}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 13:13:29', 1, '2026-03-29 15:27:03', 6, 'done'),
(2090, '  به ترتیب با کدام انتقال‌ها نمودار $y=x^2+6x-1$ به روی نمودار $y=x^2-4x+3$ منطبق می‌شود؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:27:17', 6, 'done'),
(2091, 'کدام جملات زیر درست است؟\n\nالف) از مجموعه $A=\\{1,3,5,7\\}$ به مجموعه $B=\\{a,b,c\\}$، تعداد ۸۱ تابع می‌توان تعریف کرد.\n\nب) از مجموعه $A=\\{1,3,5,7,9\\}$ به مجموعه $B=\\{a,b,c,d,e,f\\}$، تعداد ۱۲۰ تابع یک به یک می‌توان تعریف کرد.\n\nج) در دامنه معکوس تابع $f(x) = \\begin{cases} 4x^2+2x & x>0 \\\\ -3x^2+4x & x<-1 \\end{cases}$ تعداد ۸ نقطه صحیح وجود ندارد.', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:27:53', 6, 'done'),
(2092, '  اگر $f(x)=2x+\\sqrt{2x}$ باشد، ضابطه تابع حاصل $f^{-1}(x)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:28:14', 6, 'done'),
(2093, '  کدام تابع ثابت نیست؟ ($[\\text{ }]$) علامت جزء صحیح است.\n\nالف)  $y=[x]+[-x]$\n\nب)  $y=\\sqrt{-|x|^2+2|x|-2}$\n\nج)  $|y|+|2x|=|x|+x-1$', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:28:26', 6, 'done'),
(2094, '  نمودارهای $f(x)=2^{-x}$ و $g(x)=|x|$ در چند نقطه متقاطع‌اند؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:29:05', 6, 'done'),
(2095, '  به ازای کدام مقدار $m$، رابطه $\\{(3,1),(2,m),(5,1),(2,3),(0,4),(m^2-2,2)\\}$ یک تابع است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:29:18', 6, 'done'),
