(2097, '  دامنه تابع $f(x)=\\frac{\\sqrt{x+2}-\\sqrt{2-x}}{\\sqrt{x^2-4}}$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:29:49', 6, 'done'),
(2098, '  برد تابع $f(x)=x-[x]$ کدام است؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:30:05', 6, 'done'),
(2099, '  نمودار تابع $y=x^2+x$ را یک واحد به طرف $x$های مثبت و سپس ۲ واحد به طرف بالا انتقال می‌دهیم معادله منحنی حاصل کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:30:17', 6, 'done'),
(2100, '  اگر $f(x+\\frac{1}{x})=x^3+\\frac{1}{x^3}$ باشد، دامنه تابع $f(x)$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 15:30:35', 6, 'done'),
(2101, '۱۲-  ضابطه معکوس تابع $f(x)=\\frac{3^x+3^{-x}}{2}$ با شرط $x>0$ به صورت $log_3^U$ است. $U$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, NULL, NULL, 'free'),
(2102, '۱۳-  اگر $f(x)=(1-x^2)^{-\\frac{1}{2}}$ و $g(x)=(x-1)^{\\frac{1}{2}}$ باشند، دامنه تابع $fog$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, NULL, NULL, 'free'),
(2103, 'اگر $f(x)=x^2-x$ و $g(x)=2x-5$ باشد، نمودارهای دو تابع $fog, gof$ با کدام طول‌ها متقاطع‌اند؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:37:23', 4, 'done'),
(2104, ' ضابطه وارون تابع $f(x)=\\frac{x}{\\sqrt{1+x^2}}$ برابر کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:37:51', 4, 'done'),
(2105, ' مقدار $m$ برای اینکه رابطه $R=\\{(1,1),(2,m^2-5),(2m-2,2),(m^2-2m,1),(2,3-2m)\\}$ تابع باشد، کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:38:38', 4, 'done'),
(2106, ' اگر $f(x)=\\frac{2x-6}{x+2}$ و $g(x)=2x+1$، طول نقطه تلاقی نمودارهای دو تابع $fog$ و $g^{-1}$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:39:43', 4, 'done'),
(2107, '  اگر در حالت $a>1$ نمودار تابع $f(x)=x^3-3x^2+x+a$ محور $x$ها را در نقطه به طول $a$ قطع کند، کدام تابع زیر را در دو نقطه روی محور $x$ها قطع می‌کند؟', 1, 1, 64, 240, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:51:34', 6, 'done'),
(2108, '  اگر $2x^2-3x-1=f(2x-1)$ باشد، آنگاه $f(\\frac{1-\\sqrt{5}}{2})$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:51:48', 6, 'done'),
(2109, '  اگر $f(x)$ و $g(x)$ به ترتیب توابع خطی و سهمی، $2xf(x)-g(x)=x-1$، $g(3)-g(2)=5$ و $g(4)-g(3)=7$ باشد، $g(5)$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:52:14', 6, 'done'),
(2110, ' برد تابع $f(x) = \\begin{cases} 3x-1 & x > 1 \\\\ x+2 & -3 < x \\le 1 \\\\ -x+3 & -6 < x \\le -3 \\end{cases}$ کدام است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:52:25', 6, 'done'),
(2111, ' اگر نمودار تابع $y=x^2$ را یک واحد به چپ و یک واحد به پایین برده و در راستای محور $y$ها انبساط ۲ برابر کرده و قدر مطلق عرض هر نقطه را لحاظ کرده و $f(x)$ بنامیم، سپس نمودار $y=|x-1|$ را ۲ واحد به چپ برده، انبساط نسبت به محور $y$ها با ضریب ۲/۵ کنیم و یک واحد بالا ببریم و $g(x)$ بنامیم، مجموع طول‌های برخورد به ازای $|x+1| \\ge \\frac{3}{2}$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:40:13', 4, 'done'),
(2112, '  اگر $f(x)=x+\\sqrt{x^2-1}$؛ $x < -1$ باشد، $f^{-1}(x)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:52:38', 6, 'done'),
(2113, '  کدام گزاره زیر درست است؟\n\nالف) اگر $f(x)=x^2-x$ و $fog(x)=4x^2+2x$ باشد آنگاه $g(x)=2x+1$ است.\n\nب) به ازای هر دو تابع $g$ و $f$ که $f \\ne g$ باشد، آنگاه $fog(x) \\ne gof(x)$.\n\nپ) اگر $f(x)$ دارای دامنه $(-3, 2]$ باشد، آنگاه دامنه $3f(|x-1|)+2$ برابر $[-1, 3]$ است.', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:52:57', 6, 'done'),
(2114, ' کدام تابع در بازه $(1, +\\infty)$ نزولی است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:47', 1, '2026-03-29 21:53:10', 6, 'done'),
(2115, ' نمودار زیر مربوط به کدام تابع در بازه $[-1, 1]$ است؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:53:38', 6, 'done'),
(2116, '  اگر $f(x)=\\sqrt{8x+9}$ و $g = \\{(3, 7), (5, 2), (7, 8), (9, 10)\\}$ باشند، با شرط $5 = (f^{-1}og^{-1})(k)$ مقدار $k$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:53:52', 6, 'done'),
(2117, ' اگر نقطه $A(3,2)$ بر نمودار تابع وارون $f(x)=x^3-x+k$ واقع باشد، مقدار $f(0)+f(-1)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:54:04', 6, 'done'),
(2118, '  اگر نمودار تابع $(f^{-1}of)(x)$ به‌صورت زیر باشد، آنگاه ضابطه $f(x)$ کدام مورد می‌تواند باشد؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:54:28', 6, 'done'),
(2119, '  اگر $f(x)=x^2-4x+7$ و $(fog)(x)=x^2+2x+4$ باشد، حاصل جمع دو ضابطه ممکن برای $g(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:54:51', 6, 'done'),
(2120, '  در نمودار وارون تابع $f(x)=\\frac{1}{x}$ با دامنه $[-5,5]-\\{0\\}$، کدام عدد در دامنه $f^{-1}(x)$ حضور ندارد؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:55:05', 6, 'done'),
(2121, ' چند تابع یک به یک از مجموعه $\\{a,b,c,d\\}$ به مجموعه $\\{1,2,3,4,5\\}$ می‌توان تعریف کرد که شامل زوج مرتب $(a,1)$ نباشد؟', 2, 1, 42, 181, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:55:21', 6, 'done'),
(2122, 'اگر $f$ و $g$ با دامنه $R$ به ترتیب اکیداً صعودی و اکیداً نزولی باشند و محور $x$ها را به ترتیب در -۱ و ۴ و یکدیگر را در ۲ قطع کنند، دامنه تابع $\\sqrt{\\frac{f(x)g(x)}{f(x)-g(x)}}$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:55:45', 6, 'done'),
(2123, '  اگر $f(x)=\\sqrt{x-x^2}$ و $g(x)=[x+1]+[-x-1]$ باشد، آنگاه مساحت ناحیه بین $gof$ و محور $x$ها کدام است؟ ($[\\text{ }]$ علامت جزء صحیح می‌باشد.)', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:55:59', 6, 'done'),
(2124, '  برد تابع $f(x) = \\begin{cases} -2x+15 & \\text{ ; } 3 \\le x \\le 7 \\\\ (x-2)^2 & \\text{ ; } -1 < x < 3  \\\\ -2 x-10 & \\text{ ; } -5 \\le x \\le -1 \\end{cases}$ شامل چند عدد صحیح است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:56:14', 6, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(2125, ' اگر $f(x)=2x-1$ باشد، حاصل $[f+(fof^{-1})](\\frac{3}{2})$ کدام است؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:56:28', 6, 'done'),
(2126, ' اگر $f(x)=\\frac{1}{\\sqrt{x+1}}+1$ و $fog(x)=\\frac{x-1}{x+1}$ باشد، $g(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:56:48', 6, 'done'),
(2127, 'نمودار تابع $y=x^2+3x+5$ را ۷ واحد به طرف $y$های منفی، سپس ۱ واحد به طرف $x$های مثبت انتقال می‌دهیم. نمودار جدید در بازه $(1,3)$ زیر تابع خطی $y=f(x)$ قرار دارد. $f(2)$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:57:14', 6, 'done'),
(2128, '  در شکل مقابل اگر $f(x)$ و $g(x)$ توابع درجه دوم و $f(x)-g(x)=3x^2+mx+n$ باشد، مقدار $m$ کدام است؟', 1, 1, 64, 240, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:58:03', 6, 'done'),
(2129, '  اگر $f(x)=2x+1$ و $g^{-1}(x)=\\frac{2x+4}{x-3}$ باشد، حاصل $(g+f^{-1})(3)$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:58:24', 6, 'done'),
(2130, '  دامنه تابع $f(x)=\\frac{c}{\\sqrt{ax^2+bx+1}}$ بازه $(-\\frac{1}{2},+\\infty)$ است. اگر $f(4)=2$ باشد، مقدار $b+c$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:58:37', 6, 'done'),
(2131, '  مساحت نواحی محدود به نمودارهای دو تابع $y=|x-1|+2$ و $y=-\\frac{1}{2}x+3$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:58:56', 6, 'done'),
(2132, '  اگر $f(x)=\\frac{9^x-1}{3^x}$ باشد، مقدار $f^{-1}(4)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:59:19', 6, 'done'),
(2133, '  فرض کنید $f(x)=\\frac{x-2}{2x-7}$ و $g(x)=x+3$ باشند. اگر مجموعه جواب نامعادله $1 < fog(x) < 3$ به صورت $(a,b)$ باشد، بیشترین مقدار $b-a$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:59:32', 6, 'done'),
(2134, '  اگر تابع $f(x)=\\frac{3x+4}{x+m}$ از نقطه $(-10,2)$ بگذرد، تابع $fof^{-1}(x)+f^{-1}(x)=y$ نیمساز ناحیه اول و سوم را با کدام طول قطع می‌کند؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 21:59:49', 6, 'done'),
(2135, ' اگر $g(x)=\\frac{x}{x+3}$ و $(g^{-1}of)^{-1}(x)=\\frac{1}{x+1}$ باشند، آنگاه $f(3)$ کدام است؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:00:01', 6, 'done'),
(2136, '  اگر $f(x)=2x-8$ و $g(x)=x+\\sqrt{x}$ باشند، تابع $fog^{-1}(x)$ محور $x$ها را با کدام طول قطع می‌کند؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:00:12', 6, 'done'),
(2137, '  اگر $f(x)=x^2-3x-2$ و $x \\ge 2$ باشد، نمودارهای دو تابع $y=f^{-1}(x)$ و $g(x)=x-2$ در نقطه $A$ متقاطع‌اند. فاصله نقطه $A$ از مبدأ مختصات کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:00:24', 6, 'done'),
(2138, '  دو تابع $(fof^{-1})(x)$ و $(f^{-1}of)(x)$ مساوی‌اند. ضابطه تابع $f(x)$ کدام می‌تواند باشد؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:00:41', 6, 'done'),
(2139, 'اگر $g(x)=\\frac{x+2}{x+3}$ و $(g^{-1}of)^{-1}(x)=\\frac{1}{x}$ باشند، مجموع طول نقاطی که تابع $y=f(x)$ نیمساز ناحیه اول و سوم را قطع می‌کند، کدام است؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:00:51', 6, 'done'),
(2140, '  اگر $f(x)=(x-1)|x-3|$ و $g(x)=2x-2$ باشند، مجموع جواب‌های معادله $gof(x)=0$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:01:05', 6, 'done'),
(2141, '  کدام رابطه، یک تابع است؟', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:01:17', 6, 'done'),
(2142, '  برد تابع $f(x) = \\frac{x^2+3}{\\sqrt{x^2+2}}$ کدام است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:01:30', 6, 'done'),
(2143, '  تابع وارون تابع $f(x)=4x^2-4x-2$ با شرط $x \\le 0$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:01:43', 6, 'done'),
(2144, ' اگر $f(x)=\\sqrt{x+2\\sqrt{x-1}}$ و $g(x)=\\sqrt{x-2\\sqrt{x-1}}$ و $1 \\le x \\le 2$ باشد، ضابطه تابع $f(x)+g(x)$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:01:54', 6, 'done'),
(2145, '  کدام تابع، تابعی یک به یک است؟', 2, 1, 42, 181, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:02:09', 6, 'done'),
(2146, 'در شکل زیر، نمودار دو تابع $f$ و $g$ رسم شده است. اگر کمترین مقدار تابع $g$ برابر ۲- باشد، دامنه تابع $(fog)(x)$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:02:37', 6, 'done'),
(2147, 'نمودار تابع $f(x)=|x+1|-|x-3|$ در کدام فاصله اکیداً نزولی است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:02:50', 6, 'done'),
(2148, ' اگر نقطه $A(3,2)$ بر نمودار تابع وارون $f(x)=x^3-x+2k-17$ واقع باشد، مقدار $f(-2)-f(2)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:03:04', 6, 'done'),
(2149, ' اگر دامنه تابع وارون تابع $f(x)=2k-\\sqrt{x-2}$ به صورت $(-\\infty,3]$ باشد، حاصل $f(3)+f^{-1}(1)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:03:20', 6, 'done'),
(2150, 'دامنه تابع $f(x)=\\sqrt{1-log(x^2-2x)}$ شامل چند عدد صحیح است؟', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:03:40', 6, 'done'),
(2151, ' اگر $f(3x^2-|x|)=|-x|+4x$ یک تابع همانی باشد، تعداد نقاط تلاقی نمودارهای توابع $f$ و $g(x)=|x|$ کدام است؟', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:04:51', 6, 'done'),
(2152, ' اگر $f(x)=2+\\sqrt{2x-k}$، تساوی $fof^{-1}(x)=f^{-1}of(x)$ به ازای تمام $x$های متعلق به دامنه $f$ برقرار است. اگر نقطه $A$، محل تقاطع منحنی‌های $f$ و $f^{-1}$ با طول کمتر و نقطه $B$، متناظر با نقطه $A$ روی نمودار $g(x)=-2f(3-x)+4$ باشد، طول پاره‌خط $AB$ کدام است؟', 3, 1, 43, 190, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:05:09', 6, 'done'),
(2153, ' تابع $f(x) = (m+4)x^2 + (n+1)x + m - n + 2k$ برروی مجموعه اعداد حقیقی وارون‌پذیر است و وارون خود را در نقطه $(-1, 7)$ قطع می‌کند. مساحت محصور بین نمودار $f^{-1}$ و محورهای مختصات کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:05:23', 6, 'done'),
(2154, ' نمودار تابع وارون‌پذیر $f(x) = \\frac{m^2x + m + 6}{-9x + 2m - 15}$ نسبت به خط $y=x$ متقارن است. چند مقدار متمایز برای $m$ وجود دارد؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:05:33', 6, 'done'),
(2155, ' تابع $f(x) = \\begin{cases} x-[x] & -1 \\le x < 0 \\\\ x-1-[x] & 0 \\le x < 1 \\end{cases}$ مفروض است. توابع $f(x)$ و $fof(x)$ در فاصله $[-1, 1)$ به لحاظ یکنوایی به ترتیب چگونه‌اند؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:05:46', 6, 'done'),
(2156, ' تابع $f(x) = ax + 3|2x-1| + b$ در بازه $(-\\infty, \\frac{1}{2})$ یک تابع همانی است. اگر $S(a,b)$ رأس یک سهمی باشد که محور $y$ها را در نقطه‌ای با عرض ۴۶ قطع می‌کند، آنگاه این سهمی محور $x$ها را در نقاط $x_1$ و $x_2$ قطع می‌کند. حاصل $x_1^2 + x_2^2$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:06:19', 6, 'done'),
