(2163, ' $f$ و $g$ دو تابع درجه ۲ و $(f+g)(x)=3x$ و $(f-g)(x)=4x^2+5x$ هستند. اگر ضابطه $(f \\times g)$ به‌صورت $ax^4+bx^3+cx^2$ بیان شود، حاصل $a+b+c$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-23 19:30:48', 1, '2026-03-29 22:10:09', 6, 'done'),
