(2292, ' اگر $\\sin\\alpha = 2\\cos\\alpha$ و $\\pi < \\alpha < \\frac{3\\pi}{2}$ آنگاه مقدار $\\sin2\\alpha + \\cos4\\alpha$ کدام است؟', 3, 1, 47, 205, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:39:34', 6, 'done'),
(2293, ' مجموعه تمام جواب‌های متمایز معادلۀ $\\cos(\\frac{17\\pi}{8}+x).\\cos(\\frac{3\\pi}{8}-x) = \\cos^{2}(\\frac{\\pi}{3})$  در بازه $[-\\pi,\\pi]$ کدام است؟', 3, 1, 47, 207, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:39:47', 6, 'done'),
(2294, ' نمودار تابع $f(x) = a + b\\cos(\\frac{\\pi}{2}x)$ مطابق شکل زیر در بازه $[0,4]$ در نظر بگیرید. حاصل $f(\\frac{8}{3})+f(\\frac{4}{3})$ کدام است؟', 3, 1, 47, 206, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:40:31', 6, 'done'),
(2295, 'در شکل زیر، پاره‌خط $AB$ موازی محور عرض‌ها و طول آن برابر با دو واحد است. طول نقطه $B$ چند برابر عرض نقطه $A$ است؟', 3, 1, 47, 205, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:40:52', 6, 'done'),
(2296, 'حاصل عبارت $\\frac{1}{\\cos^{2} x} - \\frac{3\\tan^{2} x}{\\cos^{2} x}$ چند واحد از حاصل عبارت $\\frac{\\tan^{2} x - \\sin^{2} x}{\\cot^{2} x - \\cos^{2} x}$ بیشتر است؟', 1, 1, 45, 201, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:41:47', 6, 'done'),
(2297, ' در شکل زیر، خط $L$ بر دایره مثلثاتی در نقطه $P$ مماس است. $k$ کدام است؟', 1, 1, 45, 200, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:42:06', 6, 'done'),
(2298, ' در شکل زیر یک 6 ضلعی منتظم درون دایره‌ای به مساحت $4\\pi$ محاط شده است. مساحت 5 ضلعی هاشورخورده کدام است؟', 2, 1, 46, 203, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:42:30', 6, 'done'),
(2299, 'شکل زیر، نمودار $f(x) = a \\sin(\\pi x)\\cos(\\pi x)\\cos(2\\pi x) + b$ است. اگر ارتفاع و میانه نظیر ضلع $AC$ در مثلث $ABC$ برهم منطبق باشند، $\\frac{a}{b}$ کدام است؟', 3, 1, 47, 206, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 15:16:26', 1, '2026-04-04 11:42:39', 6, 'done'),
(2300, ' اگر مثلث قائم‌الزاویه زیر را یک بار حول $AB$ و بار دیگر حول $BC$ دوران دهیم، نسبت حجم دو جسم به‌دست آمده چقدر است؟ ($b > a$)', 3, 1, 56, 231, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-04 11:43:25', 6, 'done'),
(2301, ' در مکعب مستطیل توپر شکل زیر داریم: $FA=AG=EB , \\frac{CI}{CK} = \\frac{JD}{DL} = \\frac{1}{2} , FG=6 , HG=IH=2$ مساحت سطح مقطع صفحه‌ای که از دو ضلع $AB$ و $CD$ می‌گذرد، چقدر است؟', 3, 1, 56, 231, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:25:02', 6, 'done'),
(2302, '۳- در بیضی شکل زیر $AA\' = 2FF\'$ است. محیط مثلث $MFF\'$ چند برابر $OF$ است؟ ($F$ و $F\'$ کانون‌های بیضی هستند.)', 3, 1, 56, 232, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:39:57', 4, 'done'),
(2303, '۴ - $y=ax-1$ معادله قطر بزرگ و $x+2y=0$ معادله قطر کوچک یک بیضی است. اگر دو نقطه $A(2,3)$، $B(-1,-3)$ روی بیضی قرار گیرند، مجموع فواصل هر نقطه روی بیضی از دو کانون بیضی چقدر است؟', 3, 1, 56, 232, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:40:24', 4, 'done'),
(2304, ' خروج از مرکز یک بیضی ثلث نسبت اقطار آن است. خروج از مرکز بیضی کدام می‌تواند باشد؟', 3, 1, 56, 233, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:40:46', 4, 'done'),
(2305, ' چهار خط $4x+2y=10$، $4x+2y=0$، $x-2y=1$ و $x-2y=2$ بر بیضی مماس‌اند، فاصله کانونی بیضی کدام است؟', 3, 1, 56, 232, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:41:27', 4, 'done'),
(2306, ' نقاط برخورد دو خط $y=1$ و $y=5$ با دایره $(x-2)^2+(y-3)^2=16$ رئوس یک چهارضلعی هستند، مساحت چهارضلعی کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:42:03', 4, 'done'),
(2307, 'دایره $x^2+y^2-4x-6y+4a=0$ بر محور $x$ها در نقطه $A$ مماس است. اگر این دایره محور $y$ها را در نقاط $B$ و $C$ قطع کند، مساحت مثلث $ABC$ چقدر است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:42:28', 4, 'done'),
(2308, 'کوتاه‌ترین فاصله نقطه $A(0,-1)$ از نقاط دایره $x^2+y^2-4x-8y+k=0$ برابر ۶ است. مقدار $k$ کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 20:43:11', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(2309, ' به ازای چند مقدار $m$ معادله $(m^2-m+1)x^2+(2m^2-6m+5)y^2+4x+y+2m=0$ یک دایره است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 21:18:53', 4, 'done'),
(2310, ' فاصله نقطه تماس خط $y=x-1$ و دایره $x^2+y^2+2x+y+\\frac{1}{8}=0$ از مبدأ مختصات کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 21:19:21', 4, 'done'),
(2311, ' معادله وتر مشترک دو دایره $x^2+y^2+mx+y=3$ و $x^2+y^2+4x+2y=3$ به صورت $y=6x$ است، مقدار $m$ چقدر است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 21:19:47', 4, 'done'),
(2312, ' اگر $M(1,-1)$ درون دایره $x^2+y^2+x+2y+m=0$ قرار گیرد، حدود $m$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 21:20:08', 4, 'done'),
(2313, ' قطری از دایره $x^2+y^2+4x-8y-1=0$ که با جهت مثبت محور xها زاویه $30^\\circ$ می‌سازد، از کدام نقطه می‌گذرد؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 21:20:48', 4, 'done'),
(2314, 'دو دایره به معادلات $x^2+y^2=4x-2y-1$ و $x^2+y^2=2(5x+3y)-k$ بر هم مماس بیرون‌اند، مقدار $k$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-03-29 21:21:11', 4, 'done'),
(2315, ' شیب خط گذرا از دو نقطه $A(4, 4m)$ و $B(2, m^2+3)$، مثبت است. حدود $m$ کدام است؟', 1, 1, 57, 236, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:25:28', 6, 'done'),
(2316, ' با توجه به شکل زیر، مجموع طول و عرض نقطه $H$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:25:56', 6, 'done'),
(2317, ' مثلث $ABC$ با رئوس $A(m, 3)$، $B(7, 3)$ و $C(2, 6)$ در رأس $A$ قائمه است. محیط مثلث کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:26:16', 6, 'done'),
(2318, ' دو نقطه $B$ و $A$ روی نیمساز ربع اول قرار دارند. اگر $C(4,0)$ و مساحت مثلث $ABC$ برابر ۸ باشد، قدرمطلق تفاضل طول‌های دو نقطه $A$ و $B$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:26:29', 6, 'done'),
(2319, ' اگر فاصلهٔ دو نقطهٔ $(x, 2)$ و $(3, -1)$ کم‌تر از ۵ باشد، $x$ کدام می‌تواند باشد؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:26:40', 6, 'done'),
(2320, ' مجموع طول و عرض نقطه برخورد میانه‌های مثلث $ABC$، با رئوس $A(-1, 3)$، $B(0, 4)$ و $C(-3, -6)$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:26:52', 6, 'done'),
(2321, '۲۲ - فاصلهٔ نقطهٔ $A$ واقع بر خط $y=3x-1$ از خط $3x+4y+4=0$ برابر ۶ است. عرض منفی $A$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:27:08', 6, 'done'),
(2322, ' مساحت مثلثی که سه رأس آن $A(1,1)$، $B(0,-2)$ و $C(2,4)$ است، کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:27:18', 6, 'done'),
(2323, 'معادلهٔ دو ضلع مقابل یک مربع $mx+(m+1)y=m$ و $6x+8y=0$ است، مساحت مربع چقدر است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:27:34', 6, 'done'),
(2324, 'اگر نقطهٔ $A(\\frac{4-a}{4+a}, 3-a)$ در ناحیهٔ چهارم مختصات قرار گیرد، حدود $a$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:27:53', 6, 'done'),
(2325, 'در بیضی شکل زیر حاصل‌ضرب اندازهٔ دو قطر برابر ۶۴ و مساحت مثلث BFA برابر ۴ است. خروج از مرکز بیضی کدام است؟ (F کانون بیضی است.)', 3, 1, 56, 233, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:28:10', 6, 'done'),
(2326, ' اگر $(3, 2)$ و $(-5, 2)$ دو کانون بیضی و اندازهٔ قطر بزرگ بیضی ۱۲ باشد، کم‌ترین عرض نقطه‌های روی بیضی کدام است؟', 3, 1, 56, 232, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:29:00', 6, 'done'),
(2327, ' معادلهٔ قطری از دایره $x^2+y^2+4x-6y=100$ که موازی خط $\\frac{x}{2}+y=12$ باشد، کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:29:30', 6, 'done'),
(2328, 'فرض کنید خطوط $x=y$ و $2x+3y=10$ قطرهای یک دایره و خط $3x-4y+8=0$ بر این دایره مماس می‌باشد. شعاع دایره چند برابر ۰/۶ است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:29:51', 6, 'done'),
(2329, ' اگر نقطهٔ $A(-1, 2)$ درون دایره $x^2+y^2-2(x+2y)=m$ قرار داشته باشد، حدود $m$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:30:07', 6, 'done'),
(2330, ' معادلهٔ وتر مشترک دو دایره متقاطع $\\begin{cases} x^2+y^2=2(x+y) \\\\ x^2+y^2=2(3x+y)+4 \\end{cases}$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:30:24', 6, 'done'),
(2331, 'هرگاه دو خط $3x+ay=10$ و $6x-9y=b$ دو ضلع مقابل یک مربع با مساحت ۱۳ باشند، مجموع مقدارهای ممکن برای $b$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:31:05', 6, 'done'),
(2332, '۳۳ - در مثلث $ABC$، با رئوس $A(-1, 2)$، $B(0, 3)$ و $C(4, -1)$، نقطهٔ $D$ وسط میانهٔ $AM$ قرار دارد. اندازهٔ $BD$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:31:19', 6, 'done'),
(2333, ' دو نقطهٔ $A(-2, 5)$ و $B(0, 3)$ با بیش‌ترین فاصله روی محیط یک دایره قرار دارند. شعاع این دایره کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:31:42', 6, 'done'),
(2334, ' معادلهٔ دایره‌ای که مرکز آن $O(1, 2)$ و بر محور yها مماس باشد، کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:32:15', 6, 'done'),
(2335, ' اگر معادله $x^2+y^2-3x-5y+k=0$ دایره باشد، چند عدد طبیعی $k$ به دست می‌آید؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:32:52', 6, 'done'),
(2336, ' اگر مرکز دایره $x^2+y^2+(\\frac{m-1}{m+1})x+mny=m^2+n^2$ به صورت $(-1, -\\frac{1}{6})$ باشد، شعاع دایره چقدر است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:33:06', 6, 'done'),
(2337, ' اگر نقطه $A(1, -1)$ درون و نقطه $B(-1, 2)$ بیرون دایره $x^2+y^2-6x-2y+m=0$ قرار داشته باشد، حدود $m$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:33:31', 6, 'done'),
(2338, ' معادله دایره‌ای که مرکز آن $W(2, -1)$ و بر خط $3x+4y-1=0$ مماس باشد، کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:33:43', 6, 'done'),
(2339, 'اوضاع نسبی دو دایره $\\begin{cases} x^2+y^2-4x-2y-4=0 \\\\ x^2+y^2+4x-4y-1=0 \\end{cases}$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:33:55', 6, 'done'),
(2340, 'دایره $x^2+y^2=4$ از خط $x+y=2$ وتری به طول $L$ جدا می‌کند. $L$ کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:34:30', 6, 'done'),
(2341, ' حجم حاصل از دوران مستطیل شکل زیر حول خط $d$ برابر $2\\pi$ است. مساحت مستطیل چقدر است؟', 3, 1, 56, 231, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:39:25', 1, '2026-04-05 11:34:45', 6, 'done'),
