(2396, ' فاصلۀ کانونی یک بیضی افقی برابر $12$ و مرکز آن نقطۀ $(-7, 3)$ است. اگر خروج از مرکز این بیضی برابر $0.6$ باشد، کدام‌یک از خطوط افقی زیر بر این بیضی مماس است؟', 3, 1, 56, 233, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:06:21', 6, 'done'),
(2397, ' دایره‌ای به مرکز $(-2, 3)$ روی خط $3x + 4y - 1 = 0$ وتری به طول $16$ ایجاد می‌کند. این دایره روی محور عرض‌ها وتری با کدام طول جدا می‌کند؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:06:41', 6, 'done'),
(2398, ' اگر $A(0, 2a)$ و $B(4a, 0)$ دو سر یک پاره‌خط باشند به طوری که عمودمنصف $AB$ محور عرض‌ها را در نقطه‌ای به عرض $-6$ قطع کند، مقدار $a$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:07:10', 6, 'done'),
(2399, ' قطرهای یک بیضی برابر $6$ و $10$ است. دایره‌ای که $FF\'$ قطری از آن باشد، بیضی را در $M$ قطع کرده است. فاصلۀ $M$ تا کانون نزدیک‌تر آن کدام است؟', 3, 1, 56, 232, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:07:31', 6, 'done'),
(2400, ' دو ضلع مقابل یک مربع روی خطوط $3x - 2y + 1 = 0$ و $y = ax + b$ قرار گرفته است. اگر مساحت این مربع $\\frac{9}{11}$ باشد، مقدار $b$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:08:22', 6, 'done'),
(2401, ' دو دایرۀ $x^2 + y^2 + 2x + 4y = 4$ و $x^2 + y^2 - 4y - 4x = k$ مماس خارجی هستند. مقدار $k$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:08:36', 6, 'done'),
(2402, ' دایره‌ای که با کمترین مساحت از دو نقطۀ $A(-4, 5)$ و $B(2, 1)$ می‌گذرد، محور طول‌ها را با کدام طول قطع می‌کند؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 20:53:26', 1, '2026-04-07 12:08:55', 6, 'done'),
(2403, ' چه تعداد از موارد زیر نادرست است؟\n\n الف) اشتراک دو مجموعه نامتناهی، مجموعه‌ای متناهی است. \n\nب) اگر $A \\subset B$ و $A$ نامتناهی باشد، آنگاه $B$ نامتناهی است. \n\nپ) مجموعه $[-2,110] \\cap \\mathbb{Z}$ $ مجموعه‌ای متناهی است.\n\n ث) مجموعه درخت‌های جنگل‌های آمازون مجموعه‌ای نامتناهی است.', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:09:13', 6, 'done'),
(2404, ' اگر $|A|=25$ و $|B|=13$ باشد. ۱۵ عضو به مجموعه $A$ اضافه می‌کنیم، اگر به اشتراک آنها ۶ عضو اضافه شود، اجتماع مجموعۀ جدید $A$ و مجموعۀ $B$ چند عضو دارد؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:09:23', 6, 'done'),
(2405, ' در الگوی هندسی زیر در مرحلۀ هشتم به تعداد دایره‌های موجود، چند دایره اضافه کنیم تا تعداد دایره‌ها برابر ۱۲۸ شود؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:09:43', 6, 'done'),
(2406, ' مجموع بیشترین و کمترین جمله دنبالۀ ۵ تایی کدام است؟ ([$\\ ]$ نماد جزء صحیح است.)', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:10:07', 6, 'done'),
(2407, ' در الگوی درجه دوم که جملات اول و دوم و سوم آن به ترتیب از راست به چپ ۱ و ۴ و ۱ هستند، اختلاف جمله‌های دوازدهم و دهم از همدیگر چقدر است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:10:17', 6, 'done'),
(2408, '۶- توان‌های طبیعی عدد ۲ را به‌صورت $\\ldots,(2),(4,8),(16,32,64)$ دسته‌بندی کرده‌ایم. واسطۀ حسابی جملات اول و آخر دستۀ هفتم کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:10:46', 6, 'done'),
(2409, '۷- بین دو عدد ۲ و ۴۷، $n$  واسطۀ حسابی طوری قرار می‌دهیم که بزرگ‌ترین واسطه، ۶ برابر کوچک‌ترین واسطه شود. $n$ کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:11:02', 6, 'done'),
(2410, '۸- اگر ۱ و $a$ و ۷۷ و ۲ به‌ترتیب جملات غیرمتوالی یک دنبالۀ هندسی باشند و رابطۀ $81(2-5)+2(-5)+27(2-5)$ برقرار باشد، مقدار $|16:7|$ چقدر است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:11:21', 6, 'done'),
(2411, ' در دنبالۀ هندسی با جملۀ عمومی که رابطۀ آن برقرار است، اگر شرط داده شده برقرار باشد، جملۀ چندم دنباله با قدر نسبت آن برابر است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:11:38', 6, 'done'),
(2412, ' در دنباله‌ای با جملات غیر صفر، جملات اول تا سوم تشکیل دنباله حسابی و جملات دوم تا چهارم تشکیل دنباله هندسی می‌دهند. اگر مجموع جملات اول و چهارم برابر با ۲ و مجموع جملات دوم و سوم برابر با ۳ باشد، قدر نسبت دنباله هندسی چند برابر قدر نسبت دنباله حسابی است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:12:01', 6, 'done'),
(2413, 'چه تعداد از مجموعه‌های زیر متناهی هستند؟ \n\nالف$A={x \\mid x \\in Z , x^2 \\ge 100}$ (ب$B={x \\mid x \\in A , \\sqrt{-x} > 4}$ (پ$C={x \\mid x \\in B , 72/x \\in Z}$ (ت$D={x \\mid x \\in C , x/5 \\in Z}$', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:12:14', 6, 'done'),
(2414, ' در یک کلاس ۴۵ نفری، تعداد کسانی که اقوامشان قبلاً به کرونا مبتلا شده‌اند ۱.۵ برابر کسانی است که خودشان به کرونا مبتلا شده‌اند. اگر تعداد کسانی که فقط خودشان به کرونا مبتلا شده‌اند، ۱۰ نفر باشد و تعداد کسانی که نه خودشان و نه اقوامشان به کرونا مبتلا شده‌اند، ۸ نفر باشد، تعداد کسانی که هم اقوامشان و هم خودشان به کرونا مبتلا شده‌اند، کدام است؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:12:25', 6, 'done'),
(2415, ' مجموع 101 جمله اول دنبالۀ  $a_{n+1}=-a_n+(-1)^n$با فرض $a_1=3$کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:12:41', 6, 'done'),
(2416, '۱۴- اگر سه جملۀ متوالی $a$, $a+b$, $a,b$ یک دنباله هندسی باشند، اگر $a$ و $b$ علامت‌های مختلف داشته باشند، اختلاف قدر نسبت‌های دنباله حسابی و هندسی کدام است؟ (جملات را از چپ به راست بخوانید.)', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:12:55', 6, 'done'),
(2417, '۱۵$A$- و $B$ زیرمجموعه‌هایی از مجموعه مرجع هستند. اگر$n(U)=80$ ، $n(A\' \\cap B\')=20$ ، $n(A\' \\cap B)=10$ و $n(A \\cap B\')=30$  باشد، آنگاه مقدار $n(A \\cap B)$کدام است؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:13:05', 6, 'done'),
(2418, ' با توجه به الگوی زیر، تعداد دایره‌های شکل هشتم چند تا از دایره‌های شکل چهارم بیشتر است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:13:15', 6, 'done'),
(2419, 'در دنباله $a_n=\\frac{1}{\\sqrt{n+3}+\\sqrt{n+1}}$ مجموع جملات با شمارۀ فرد از جملۀ اول تا سی‌ام را $A$ می‌نامیم. همچنین مجموع جملات با شمارۀ زوج از جملۀ اول تا بیست و پنجم را $B$ می‌نامیم. حاصل $\\frac{A}{B}$ کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:13:26', 6, 'done'),
(2420, ' اگر اضلاع مثلث قائم‌الزاویه‌ای با مساحت ۲۴ تشکیل دنبالۀ حسابی دهند، ارتفاع وارد بر وتر این مثلث کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:13:40', 6, 'done'),
(2421, 'اعداد طبیعی زوج را از کوچک به بزرگ به طریقی دسته‌بندی می‌کنیم که تعداد جملات هر دسته برابر با شمارۀ آن دسته باشد. واسطۀ هندسی مثبت هشتمین جملۀ دستۀ شانزدهم و نهمین جملۀ دستۀ هجدهم کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:14:16', 6, 'done'),
(2422, 'بین دو عدد مثبت که اختلاف آن‌ها ۳۵ است، ۳ واسطۀ هندسی مثبت درج می‌کنیم. اگر واسطۀ حسابی بزرگ‌ترین و کوچک‌ترین جملۀ درج شده برابر ۱۵ باشد، مجموع جملات درج شده چقدر است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:14:36', 6, 'done'),
(2423, 'اگر $n(U)=80$ ، $n(A\'∩B\')=20$ ، $n(A\'∩B)=10$ و $n(A∩B\')=30$ باشد، آنگاه مقدار $n(A∩B)$ کدام است؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:14:46', 6, 'done'),
(2424, 'دنباله‌های $A: 21,24,27,...$ و $B: 17,22,27,...$ مفروض هستند. دنبالۀ حاصل از جملات مشترک این دو دنباله چند جمله کمتر از ۱۰۰۰ دارد؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:15:03', 6, 'done'),
(2425, 'اگر به هر یک از اعداد ۱ ، ۳ و ۶ مقدار $a$ را اضافه کنیم، به همین ترتیب جملات متوالی یک دنبالۀ هندسی با قدر نسبت $r$ را تشکیل می‌دهند. حاصل $r-a$ کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:15:23', 6, 'done'),
(2426, '25 -فرض کنید $A_k=[-2k,20-k]$ باشد که در آن $k \\in {1,2,\\dots,10}$ در این صورت $|\\bigcup_{k=1}^{10} A_k - \\bigcap_{k=1}^{10} A_k|$ شامل چند عدد صحیح است؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:15:42', 6, 'done'),
(2427, 'در یک مدرسه با ۵۰ دانش‌آموز، ۲۵ دانش‌آموز در مسابقات ورزشی و ۳۰ دانش‌آموز در مسابقات هنری شرکت کرده‌اند. حداکثر تعداد دانش‌آموزانی که می‌توانند در هر دو مسابقه شرکت کرده باشند چند برابر حداکثر تعداد دانش‌آموزهایی است که می‌توانند فقط در یک مسابقه شرکت کرده باشند؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:15:50', 6, 'done'),
(2428, 'جمله اول و دوم یک دنباله حسابی به ترتیب جملات چهارم و ششم دنباله درجه دوم $...,9,12,14$ هستند. جمله دهم این دنباله حسابی کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:16:03', 6, 'done'),
(2429, ' اگر $a_1=\\cos(92\\pi)$ و $a_{n+1}=2a_n^2-1$ و $a_6=1$ باشد، $m$ کدام گزینه نمی‌تواند باشد؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:16:16', 6, 'done'),
(2430, '۲۹- جمله سیزدهم یک دنباله حسابی ۳۰ می‌باشد. اگر تفاضل مربع جمله یازدهم از مربع جمله پانزدهم برابر ۱۲۰ باشد، جمله بیستم آن کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:16:30', 6, 'done'),
(2431, '۳۰- سه عدد تشکیل دنباله حسابی می‌دهند. مجموع آن‌ها برابر ۱۵ و حاصل جمع مکعبات این سه عدد برابر ۶۴۵ است. حاصل ضرب این سه عدد کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:16:47', 6, 'done'),
(2432, '۳۱- اگر دنباله‌های $A={8,10,12,...}$ و $B={6,10,14,...}$ و $C={5,10,15,...}$ مفروض باشد، آنگاه دنباله حاصل از جملات مشترک این سه دنباله چند جمله سه‌رقمی دارد؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:17:06', 6, 'done'),
(2433, '۳۲- در یک دنباله هندسی با قدر نسبت منفی، جمله دوم ۳۵ واحد کمتر از جمله اول و جمله سوم ۵۶۰ واحد بیشتر از جمله چهارم است. مجموع چهار جمله اول این دنباله کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:17:17', 6, 'done'),
(2434, '۳۳- جمله شانزدهم دنباله حسابی $...,\\sqrt{2},4/\\sqrt{2},6/\\sqrt{2}$ با جمله چندم دنباله هندسی   $...,2/\\sqrt{2},2,2\\sqrt{2}$ برابر است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:17:45', 6, 'done'),
(2435, '۳۴- در یک دنباله حسابی با جملات متمایز، جملات چهارم، نهم و سیزدهم سه جمله متوالی از دنباله‌ای هندسی هستند. چندمین جمله این دنباله حسابی برابر با صفر است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:17:57', 6, 'done'),
(2436, '۳۵- در یک کلاس، ۴۰٪ دانش‌آموزان عضو گروه سرود و ۸۰٪ عضو گروه موسیقی هستند. چند درصد دانش‌آموزان این کلاس فقط عضو گروه سرود هستند؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:18:09', 6, 'done'),
(2437, '۳۶- در یک دنباله هندسی با جملات مثبت داریم: $a_7+a_8+a_9=113/3$ و $1/a_3+1/a_4+1/a_5=21/4$، جمله ششم این دنباله کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:18:26', 6, 'done'),
(2438, '۳۷- در یک مدرسه با ۵۰ دانش‌آموز، ۲۵ دانش‌آموز در مسابقات ورزشی و ۳۰ دانش‌آموز در مسابقات هنری شرکت کرده‌اند. حداکثر تعداد دانش‌آموزانی که می‌توانند در هر دو مسابقه شرکت کرده باشند چند برابر حداکثر تعداد دانش‌آموزهایی است که می‌توانند فقط در یک مسابقه شرکت کرده باشند؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:18:35', 6, 'done'),
(2439, '۳۸- در الگوی $t_n$ که جملات آن به صورت $...,57,36,20,9,3$ است، حاصل $t_{29}-t_{26}$ کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:18:52', 6, 'done'),
(2440, '۳۹- بین جملات ششم و هشتم یک دنباله هندسی با جملات مثبت و غیرثابت، ۴۹ عدد به گونه‌ای درج کرده‌اند که جملات حاصل تشکیل دنباله حسابی با قدر نسبت $d>0$ بدهند. اگر جملات پنجم و ششم همین دنباله هندسی، جملات متوالی از یک دنباله حسابی با قدر نسبت $d$ باشند، قدر نسبت دنباله هندسی کدام است؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-24 21:14:29', 1, '2026-04-07 12:19:04', 6, 'done'),
(2441, ' حاصل $\\lim_{x \\to 3^-} \\frac{[x]\\sqrt{x^2-6x+9}}{x^2-5x+6}$ کدام است؟ ($[ ]$، نماد جزء صحیح است.)', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:19:41', 6, 'done'),
(2442, ' اگر نمودار تابع $f$ به صورت زیر باشد و داشته باشیم $g(x)=f(2-3x)$، آنگاه کدام گزینه صحیح می‌باشد؟', 2, 1, 44, 191, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:20:10', 6, 'done'),
(2443, ' اگر شکل روبه‌رو تابع $f$ باشد، حاصل $\\lim_{x \\to (-1)^-} \\frac{f(x+1)}{f(2-x)}$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:20:37', 6, 'done'),
(2444, ' در صورتی که تابع $f(x) = \\begin{cases} ax^2+bx-3 & |x-3| \\le 1 \\\\ 2ax+b & |x-3| > 1 \\end{cases}$ در تمامی نقاط دارای حد باشد، مقدار $\\frac{b}{a}$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:20:59', 6, 'done'),
(2445, ' اگر تابع $f(x)=[x]a+[-2x]x$ در $x=2$ دارای حد باشد، آنگاه $\\lim_{x \\to 3^+} f(x)$ کدام است؟ ($[ ]$، نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:21:28', 6, 'done'),
