(2451, ' اگر تابع $f(x)=(2x^2-mx+n)[\\sqrt{x}]$ در نقاط $x=1$ و $x=4$ پیوسته باشد، آن‌گاه $m+n$ کدام است؟ ($[ ]$، نماد جزء صحیح است.)', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:55:31', 6, 'done'),
