(2455, ' تابع $f(x)=[x]+[0/2x^2]$ در چند نقطه به طول صحیح پیوسته است؟ ($[ ]$، نماد جزء صحیح است.)', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:57:34', 6, 'done'),
(2456, ' تابع $f(x) = \\begin{cases} \\frac{\\sqrt{6-\\sqrt[3]{x}}-2}{a(x-8)} & x \\ne 8 \\\\ |x-7| & x=8 \\end{cases}$ در $x=8$ پیوسته است. مقدار $a$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:57:45', 6, 'done'),
