(2458, ' اگر به ازای $m, n \\in \\mathbb{N}$ داشته باشیم: $\\lim_{x \\to +\\infty} \\frac{ax^n+2x^3+x-1}{x^m-3x-4}=2$، حاصل $a+m$ کدام نمی‌تواند باشد؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 12:58:21', 6, 'done'),
