(2465, ' اگر نمودار تابع $f(x)=\\frac{x-a}{x^3-bx^2+cx+d}$ به‌صورت زیر باشد، حاصل $ab-cd$ کدام است؟', 2, 1, 44, 198, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:01:27', 6, 'done'),
