(2470, ' اگر $f(x) = \\begin{cases} x^2 - 10 & x > 0 \\\\ x + 1 & x \\le 0 \\end{cases}$ باشد، آنگاه تابع $(fof)(x)$ در چند نقطه از دامنه اش ناپیوسته است؟', 3, 1, 48, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:03:06', 6, 'done'),
(2471, ' باقی‌مانده تقسیم چندجمله‌ای $P(x)$ بر $x^2 - 4x + 3$ برابر $ 3 x - 2$ است. باقی‌مانده تقسیم چندجمله‌ای $P(x + 1) - P(x - 1)$ بر $x - 2$ چقدر است؟', 3, 1, 48, 387, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:03:17', 6, 'done'),
(2472, ' اگر $f(x + 1) = \\sqrt{x + 2} + 2$ باشد، حاصل $\\lim_{x \\to 3} \\frac{f^{-1}(x)}{\\sqrt{2x + 3} - 3}$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:04:02', 6, 'done'),
(2473, ' هر گاه $\\lim_{x \\to a^-} \\frac{\\sqrt[3]{x - 1} - b}{|x - a|} = \\frac{-1}{3}$ باشد، مقدار $a$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:04:25', 6, 'done'),
(2474, ' اگر $+\\infty = \\lim_{x \\to \\frac{\\pi}{2}} \\frac{b + 3}{a \\sin x - b}$، چند مقدار صحیح برای $a$ وجود دارد؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:04:39', 6, 'done'),
(2475, ' اگر نمودار تابع $f$ به‌صورت زیر باشد، حاصل $\\frac{\\lim_{x \\to -\\infty} (fof)(x)}{\\lim_{x \\to +\\infty} (fof)(x)}$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:04:50', 6, 'done'),
(2476, ' اگر $-7 = \\lim_{x \\to +\\infty} \\frac{a(2x - 1)^2 + b(x + 3)^2}{8x + 10}$ باشد، $a + b$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:05:03', 6, 'done'),
(2477, ' حاصل $\\lim_{x \\to +\\infty} (\\sqrt{x + 1} + \\sqrt{x})(\\sqrt{x^2 + 3\\sqrt{x}} - x)$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:05:18', 6, 'done'),
(2478, ' اگر تابع $f(x) = \\begin{cases} \\frac{\\sqrt{\\sqrt{x}-2}-1}{\\sqrt{x}-|\\sqrt{x}|-1} & 4 < x < 9 \\\\ a & x = 9 \\\\ \\frac{ax^2+3}{1-2x^2} & x > 9 \\end{cases}$ در نقطۀ $x=9$ پیوستگی چپ داشته باشد، حاصل $\\lim_{x \\to +\\infty} f(x)$ کدام است؟ ($[ ]$ نماد جزء صحیح است.)', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:05:32', 6, 'done'),
(2479, ' تابع $f(x) = (x-1)[x^2]$ در بازۀ $[-\\frac{1}{2}, k)$ پیوسته است. بیشترین مقدار $k$ کدام است؟ ($[ ]$ نماد جزء صحیح است.)', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:05:45', 6, 'done'),
(2480, ' اگر $-1 = \\lim_{h \\to 0} \\frac{f(2+h)}{h}$ باشد، کدام شکل برای $f$ مناسب است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:06:00', 6, 'done'),
(2481, ' اگر نمودار تابع $f(x)$ به‌صورت زیر باشد، مقدار مشتق $g(x) = \\frac{2x-2}{f(x)+3}$ در $x=1$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:06:15', 6, 'done'),
(2482, ' در تابع $f(x) = \\log |x-1|$ به‌ازای کدام محدوده از $a$، حاصل $\\frac{f(a)}{f\'(a)}$ منفی است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:06:41', 6, 'done'),
(2483, ' در تابع با ضابطۀ $f(x) = \\begin{cases} 5x-3 & x \\ge 1 \\\\ 3x-1 & x < 1 \\end{cases}$ حاصل $\\lim_{h \\to 0^-} \\frac{f(1+h)-f(1-2h)}{h}$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:06:57', 6, 'done'),
(2484, ' حاصل $\\lim_{x \\to 0} \\frac{[1-\\cos x]}{x^2}$ کدام است؟ ($[ ]$ نماد جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:08:09', 6, 'done'),
(2485, ' نمودار تابع $f(x) = \\begin{cases} ax-x^2 & x < 1 \\\\ \\sqrt{x+b}-1 & x > 1 \\end{cases}$ در شکل زیر رسم شده است. مقدار $f(\\frac{-2b}{a})$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:08:38', 6, 'done'),
(2486, ' مقدار $a$ کدام باشد تا تابع $f(x) = \\begin{cases} a & x=1 \\\\ \\frac{|x-2|-|x-3|}{1-x^2} & x \\ne 1 \\end{cases}$ در $x=1$ پیوسته باشد؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:08:54', 6, 'done'),
(2487, ' اگر تابع $f(x) = ([x]-a)[2x]$ در $x=2$ پیوسته باشد، حاصل $\\lim_{x \\to a^-} f(x)$ کدام است؟ ($[ ]$ نماد جزء صحیح است.)', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:09:04', 6, 'done'),
(2488, ' حاصل $\\lim_{x \\to \\frac{5\\pi}{4}} \\frac{[\\sin x]+2}{\\cos 2x-1}$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:09:17', 6, 'done'),
(2489, ' اگر $\\lim_{x \\to 3} \\frac{x-\\sqrt{x+b}}{x-3}$ برابر عدد حقیقی $a$ باشد، $a+b$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:09:34', 6, 'done'),
(2490, ' شکل مقابل مربوط به تابع $f(x) = \\frac{x+1}{4x^3+ax^2+bx+c}$ است. $b$ کدام است؟', 3, 1, 48, 196, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:09:59', 6, 'done'),
(2491, ' دامنۀ تابع $f(x) = \\frac{\\sqrt{1-x^2}}{x-\\frac{1}{2}[2x]}$ در نقطۀ $x=m$ دارای همسایگی محذوف و در نقطۀ $x=n$ دارای همسایگی یک طرفه است. $m \\times n$ کدامیک از مقادیر زیر نمی‌تواند باشد؟', 2, 1, 44, 198, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:10:13', 6, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(2492, ' با فرض $f(x) = \\frac{2-\\sqrt[3]{2x+6}}{x-(a+1)\\sqrt{x}+a}$، اگر $ 1 = \\lim_{x \\to 1} f(x)$ باشد، $[a]$ کدام است؟ ($[ ]$ علامت جزء صحیح است.)', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 21:36:37', 1, '2026-04-07 13:10:26', 6, 'done'),
(2493, ' $f(x)$ تابع سهمی درجه دوم، $f(1)$ مقداری صحیح، $\\lim_{x \\to 1} |f(x)| = 3$ و $\\lim_{x \\to -1^+} |f(x)| = 10$ و $|f(x)|$ در $x = -1$ حد ندارد. مقدار $f(4)$ کدام است؟ ($[ ]$ علامت جزء صحیح است.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:10:50', 6, 'done'),
(2494, ' کدام جمله‌های زیر درست است؟\n\nالف) توابع $f$ و $g$ وجود دارند که در $x=a$ یکی ناپیوسته و دیگری پیوسته باشند و $f+g$ در $x=a$ پیوسته باشد.\n\nب) توابع $f$ و $g$ وجود دارند که در $x=a$ یکی ناپیوسته و دیگری پیوسته باشند و $\\frac{f}{g}$ در $x=a$ پیوسته باشد.\n\nج) توابع $f$ و $g$ وجود دارند که هر دو در $x=a$ ناپیوسته باشند و $|f|$ در $x=a$ پیوسته باشد.\n\nد) توابع $f$ و $g$ وجود دارند که هر دو در $x=a$ تعریف نشده باشند و $\\frac{f}{g}$ در $x=a$ پیوسته باشد.', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:11:02', 6, 'done'),
(2495, ' به ازای کدام مقدار $a$، تابع $f(x) = \\begin{cases} \\frac{x - |x|}{x^3 + x} & ; x \\neq 0 \\\\ a & ; x = 0 \\end{cases}$ در نقطه $x=0$ از چپ پیوسته است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:11:12', 6, 'done'),
(2496, ' حد عبارت $\\frac{4x - 7 - [2x]}{2 + x - \\sqrt{5x + 10}}$ وقتی $x \\to 3^-$، کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:11:26', 6, 'done'),
(2497, ' حد عبارت $\\frac{\\sqrt[3]{5+\\sqrt{x+1}}-2}{\\sqrt{2x}-4}$، وقتی $x \\to 8$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:11:42', 6, 'done'),
(2498, ' به ازای کدام مقدار $a$، تابع $f(x) = \\begin{cases} \\frac{|x| \\sin 2x}{x^2} & ; x \\neq 0 \\\\ a - 1 & ; x = 0 \\end{cases}$ در $x=0$ از چپ پیوسته است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:11:53', 6, 'done'),
(2499, ' اگر تابع $f(x)$ به شکل زیر باشد، در کدام‌یک از توابع زیر در نقطه $x_0$ حد تابع موجود ولی تابع پیوسته نیست؟\n\nالف)  $x_0 = 2, y = |f(x)|$\n\nب) $x_0 = 2, y = |[f(x)]|$\n\nپ) $x_0 = 0, y = [f(x)]$\n\n\n\nت) $x_0 = -1, y = |f(x)|$', 2, 1, 44, 208, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:12:07', 6, 'done'),
(2500, ' تابع $f(x)$ که در $x=0$ حد دارد و $\\sqrt{f(x)}$ تعریف شده است ولی $\\sqrt{f(x)}$ حد چپ و راست ندارد، کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 13:12:19', 6, 'done'),
(2501, ' اگر $f(x) = \\begin{cases} \\sqrt{x} & x \\ge 0 \\\\ g(x) & x < 0 \\end{cases}$ باشد، به ازای کدام تابع $g(x)$، تابع $f(x)$ در $x=0$ پیوستگی راست دارد، در هر همسایگی $x=0$ تعریف شده ولی حد چپ ندارد؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:02:56', 6, 'done'),
(2502, ' کدام‌یک از گزینه‌های زیر درست است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:03:28', 6, 'done'),
(2503, ' حاصل $\\lim_{x \\to -\\infty} (3x + \\sqrt{9x^2 - 2x})$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:03:39', 6, 'done'),
(2504, ' در مورد تابع جزء صحیح با ضابطه $f(x) = [-\\sin x]$ کدام بیان، درست است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:03:49', 6, 'done'),
(2505, ' حد عبارت $\\frac{x^3 - 8x^2 + 2x - 16}{6 \\sqrt[3]{x} - 12}$، وقتی $x \\to 8$، کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:04:04', 6, 'done'),
(2506, ' حد عبارت $\\frac{x^4 + 4x - 8}{x^2 + 2 \\left[ \\frac{1}{x} \\right]}$ وقتی $x \\to (-2)^-$ چقدر است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:04:27', 6, 'done'),
(2507, ' اگر نمودار $f$ در همسایگی $x=0$ به صورت زیر باشد، آن‌گاه نمودار تابع $y = \\frac{1}{\\sqrt{1-f}}$ در همسایگی $x=0$ کدام مورد می‌تواند باشد؟', 2, 1, 44, 198, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:04:38', 6, 'done'),
(2508, ' اگر نمودار تابع $f$ به شکل مقابل باشد، حاصل $\\lim_{x \\to 3^-} [f(x) + f(|x|)]$ کدام است؟ ($[ ] $علامت جزء صحیح می‌باشد.)', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:04:55', 6, 'done'),
(2509, ' به ازای کدام مقدار $a+b$، تابع با ضابطه $f(x) = \\begin{cases} a \\frac{x}{|x|} + b \\cos bx & ; x < 0 \\\\ 2 & ; x = 0 \\\\ \\frac{|\\tan(x + \\frac{\\pi}{4}) - \\cot(x + \\frac{\\pi}{4})|}{a \\sin x} & ; x > 0 \\end{cases}$ در $x=0$ پیوسته است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:05:12', 6, 'done'),
(2510, '  حاصل $\\lim_{x \\to -\\infty} \\frac{3x^2 + x + x\\sqrt{9x^2 + x}}{4x + 1 + |3x - 4|}$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:05:27', 6, 'done'),
(2511, ' اگر نمودار $f(x) = \\frac{4x^2 + ax^2 + bx + 1}{x + c}$ به شکل زیر باشد، $a+b+c$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:05:52', 6, 'done'),
(2512, ' حاصل $\\lim_{x \\to -\\infty} \\frac{x - |x|}{x + 1}$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:06:04', 6, 'done'),
(2513, ' حاصل $\\lim_{x \\to 1} \\frac{\\sqrt{x} - \\sqrt{2x - 1}}{2x - \\sqrt{x + 3}}$ کدام است؟', 2, 1, 44, 193, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:06:25', 6, 'done'),
(2514, ' اگر تابع $y = (x^2 + ax + b)[x]$ در بازه $(1, 4)$ پیوسته باشد، $a + b$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:06:35', 6, 'done'),
(2515, ' تابع $f(x) = [5x]$ در چند نقطه از بازه $[-2, 2]$ ناپیوسته است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:06:44', 6, 'done'),
(2516, ' اگر حاصل حد عبارت $(\\sqrt{x^2 + 3x} - \\sqrt{x^2 - 3x})$ وقتی $x \\to +\\infty$ را برابر $m$ و وقتی $x \\to -\\infty$ برابر $n$ در نظر بگیریم، مقدار $m - n$ کدام است؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:06:58', 6, 'done'),
(2517, ' اگر $n$ عدد طبیعی باشد، حاصل $\\lim_{x \\to +\\infty} \\frac{x - x^n + 7x^n}{2x^n + 5x - 7}$ کدام مورد نمی‌تواند باشد؟', 3, 1, 48, 197, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:07:13', 6, 'done'),
(2518, ' اگر $f(x) = 3[x] + (2a - 1)[-x]$ و $\\lim_{x \\to 2} f(x) = b$ باشد، مقدار $a + b$ کدام است؟', 2, 1, 44, 192, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:07:28', 6, 'done'),
(2519, ' تابع $f(x) = \\begin{cases} \\frac{x^3 + a}{x - 2} & x \\neq 2 \\\\ bx + 2 & x = 2 \\end{cases}$ در مجموعه اعداد حقیقی پیوسته است. مقدار $a - b$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 22:33:01', 1, '2026-04-07 16:08:16', 6, 'done'),
