(2673, ' جمعیت شهری به‌طور ثابت سالی یک درصد کاهش می‌یابد. با این روند، در چند سال جمعیت این شهر به نصف مقدار فعلی می‌رسد؟ (در صورت داده شده $\\log2=0/3$ و $\\log99=1/995$)', 2, 1, 63, 258, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:24:39', 1, '2026-04-09 19:22:32', 6, 'done'),
(2674, 'برای رسم نمودار تابع $g(x) = 2^{x-1}$ از نمودار $f(x) = 2^{x}$ کدام‌یک از تبدیلات زیر درست است؟', 2, 1, 63, 251, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:22:44', 6, 'done'),
(2675, ' اگر $8^(a-2)=5$، آنگاه حاصل $\\log_{2} 20$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:23:51', 6, 'done'),
(2676, 'مقدار عددی عبارت $A = 3\\log 20-2\\log 60 + \\log 45$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:24:06', 6, 'done'),
(2677, ' مقدار عددی عبارت $\\frac{2 + \\log_{6} 4}{\\log_{6} 12}$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:24:18', 6, 'done'),
(2678, ' حاصل‌ضرب جواب‌های معادله نمایی $4^{x+1} + 2 = 9\\times 2^{x}$ کدام است؟', 2, 1, 63, 253, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:24:30', 6, 'done'),
(2679, 'نیمه‌عمر ماده‌ای $900$ سال است. پس از تقریباً چند سال فقط $20\\%$ از جرم اولیه این ماده باقی می‌ماند؟ ($\\log 2 \\simeq 0/3$)', 2, 1, 63, 258, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:24:54', 6, 'done'),
(2680, ' دامنه تابع $y =\\frac{\\log (x-3)}{\\log_{3}(6-x)}$ شامل چند عدد صحیح است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:26:53', 6, 'done'),
(2681, ' دو تابع $f(x) = 2 - \\log_{4}(x-3)$ و $g(x) = \\log_{4}(2x-2) $ یکدیگر را در نقاطی با کدام عرض قطع می‌کنند؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-09 19:27:08', 6, 'done'),
(2682, ' اگر نمودار دو تابع $f(x)=(\\frac{k-1}{x})^x$ و $g(x)=(\\frac{2k-1}{8})^x$ بصورت روبه‌رو باشند، دقیق‌ترین محدوده برای $k$ کدام است؟', 2, 1, 63, 251, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:22:03', 6, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(2683, ' حاصل‌ضرب ریشه‌های معادله $(\\log_{2} x)^2 + \\log_{2} x^2 - 8$ کدام است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:22:13', 6, 'done'),
(2684, ' اگر $a=\\log 2$ و $b=\\log 3$ حاصل $\\log \\frac{\\sqrt{75}}{72}$ بر حسب $a$ و $b$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:22:26', 6, 'done'),
(2685, ' معادله لگاریتمی $\\log x + \\log (x-1) - \\log (x+2) = \\log (x+3)$ چند ریشه حقیقی دارد؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:22:35', 6, 'done'),
(2686, ' نمودار تابع $y = \\log_a (x - 2)$ از نقطه $(\\frac{17}{4},- 2)$ عبور می‌کند. مقدار $a$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:22:46', 6, 'done'),
(2687, ' معادله $9^x = 3^{x^2 - 4x}$ چند ریشه دارد؟', 2, 1, 63, 253, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:22:56', 6, 'done'),
(2688, ' اگر $a = \\log 20$ و $b = \\log 30$ مقدار $\\log 15$ بر حسب $a$ و $b$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:23:04', 6, 'done'),
(2689, ' معادله $\\log_{x} (x^3 - 2x)=2$ چند ریشه حقیقی دارد؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:23:13', 6, 'done'),
(2690, ' اگر $a = \\log 4$ و $b = \\log 27$ حاصل $\\log_{12} 25$ بر حسب $a$ و $b$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:23:28', 6, 'done'),
(2691, 'کدام نقطه زیر روی تابع $y = \\sqrt{3^{x}}$ قرار دارد؟', 2, 1, 63, 251, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:23:40', 6, 'done'),
(2692, ' معادله $\\log_4 (\\log_4 (x^2 + 3)) = 0$ چند ریشه حقیقی دارد؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:23:59', 6, 'done'),
(2693, 'اگر شدت زلزله‌ای 3 برابر افزایش یابد، انرژی آزادشده در زلزله چند برابر می‌شود؟', 2, 1, 63, 258, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:24:09', 6, 'done'),
(2694, 'اگر $\\log_{5} 10 = m$، آنگاه حاصل $\\sqrt[4]{25^{m-1}}$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:24:24', 6, 'done'),
(2695, ' اگر در تابع نمایی با ضابطه $f(x) = a \\times b^x$ داشته باشیم $f^{-1}(\\frac{1}{3}) = -1$ و $f^{-1}(72) =2$، مقدار $ab$ کدام است؟', 2, 1, 63, 251, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:24:35', 6, 'done'),
(2696, 'حاصل $5^{\\log_{25} 9} - \\log_{3} \\sqrt{27} + \\log_{7} 8 \\times \\log_{2} \\sqrt[3]{49}$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:24:52', 6, 'done'),
(2697, ' اگر $a = \\log_{6} 2 \\times \\log{6} 3$ و مقدار $\\log_6 12 \\times \\log_6 18$ برحسب $a$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:25:01', 6, 'done'),
(2698, 'اگر در معادله لگاریتمی $\\log(1 - x) = \\log(4 - x) - \\log(1 – 4x)$ صدق کند، حاصل $\\log_{0/5} (2x + 5)$ چیست؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:25:25', 6, 'done'),
(2699, ' اگر نمودار $y = \\log_{0/5} (x + a) + b$ به‌صورت روبه‌رو باشد، حاصل $2a + 3b$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:25:42', 6, 'done'),
(2700, ' ریشه دوم مثبت $8^x + 1$ با ریشه سوم $ (\\frac{1}{2})^{2x}$ برابر است. حاصل $\\log_{\\sqrt{3}} (26x+27)$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:27:44', 6, 'done'),
(2701, ' اگر $x = -3$ ریشه معادله $\\log_{0.5} (x^2 + \\sqrt{a}) = \\log_{0.5} (a - x) - 1$ باشد، ریشهٔ دیگر این معادله کدام است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:27:55', 6, 'done'),
(2702, 'اگر $\\sqrt{3^{a}} = 5$ و آنگاه حاصل عبارت $\\log_{125} 9 + 4^{\\log_{2} a} $ براساس $a$ کدام است؟', 2, 1, 63, 253, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:28:18', 6, 'done'),
(2703, 'یک تودهٔ باکتری پس از $t$ ساعت دارای جرم $m(t) = \\sqrt[3]{t} + kt^2$ گرم است. اگر آهنگ رشد جرم تودهٔ باکتری در لحظهٔ $t = 8$ برابر $\\frac{193}{12}$ باشد، $k$ کدام است؟', 2, 1, 63, 258, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:28:55', 6, 'done'),
(2704, ' از دو معادله: $4^x = 2^x=56$ و $\\log(x -2) + \\log(x^4 + y) = 2$ کدام مقدار $y$ است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:29:42', 6, 'done'),
(2705, ' شکل روبه‌رو نمودار $f(x) = -1 + \\log_{b} (2x - a)$ است. این تابع خط $y = 3$ را با کدام طول قطع می‌کند؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:30:48', 6, 'done'),
(2706, ' جمع جواب‌های معادله $\\log_{3} (9^x + 8) = 4 + x$ چه عددی است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:30:57', 6, 'done'),
(2707, ' با فرض $\\log 2=0/3$، چقدر به بزرگیِ زلزله اضافه شود تا انرژی آزادشده آن 64 برابر شود؟', 2, 1, 63, 258, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:31:06', 6, 'done'),
(2708, ' هر گاه معادله $(9)^{ -2+3x} = (9)^{2x-x^2}$ دارای ریشه‌های $\\alpha$ و $\\beta$ باشد، مقدار $\\log_{2}(\\frac{2}{\\alpha} + \\frac{2}{\\beta})$ تقریباً چه عددی است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:29:09', 1, '2026-04-10 16:31:27', 6, 'done'),
(2709, ' ۲۰۰ کیلوگرم محلول آب نمک با غلظت ۴ درصد و ۳۰۰ کیلوگرم آب نمک با غلظت ۶ درصد را به همراه ۱۴ کیلوگرم نمک خالص، در یک ظرف جدید می‌ریزیم چند کیلوگرم از آب آن تبخیر کنیم تا غلظت نهایی ۱۰ درصد شود؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:32:52', 6, 'done'),
(2710, ' هرگاه $P(x) = \\frac{ax - 1}{a - x}$ به‌طوریکه جدول تعیین علامت آن به‌صورت مقابل باشد، حدود $a$ کدام است؟', 1, 1, 57, 236, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:33:09', 6, 'done'),
(2711, 'اختلاف جواب‌های معادله‌ی $\\sqrt{x^2 + 3x - 1} + \\sqrt{x^2 + 3x + 7} = 4$ چقدر است؟', 2, 1, 58, 238, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:34:42', 6, 'done'),
(2712, ' دو شخص $A$ و $B$ دیواری را با هم در ۱۸ ساعت رنگ می‌زنند. بعد از ۱۲ ساعت کار مشترک $A$ کار را رها می‌کند و $B$ مابقی دیوار را در ۱۸ ساعت رنگ می‌زند. اگر $B$ پس از ۱۲ ساعت کار مشترک، کار را رها می‌کرد، $A$ مابقی دیوار را در چند ساعت رنگ می‌زد؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:35:00', 6, 'done'),
(2713, ' مجموعه جواب نامعادله‌ی $|\\frac{2x + 1}{ax - 2}| > 1$ به‌صورت $(b, \\infty)$ است. حاصل $a + b$ کدام است؟', 1, 1, 57, 236, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:35:16', 6, 'done'),
(2714, ' جدول تعیین علامت عبارت $P = (x + 1)(2x^2 + ax + 3a)$ به‌صورت مقابل است. حاصل $a + b$ کدام است؟', 1, 1, 57, 236, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:35:40', 6, 'done'),
(2715, ' نمودار سهمی $f(x) = -ax^2 + bx + a$ شکل روبه‌رو است. جمع مربع ریشه‌های $f(x) = 0$ چه عددی است؟', 2, 1, 64, 241, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:36:15', 6, 'done'),
(2716, ' در شکل مقابل، نمودار سهمی $y = x^2 - ax$ و خط $y = a$ رسم شده است. اگر مساحت مثلث $ABC$ برابر ۱ باشد، حاصل $a^2 + 4a$ کدام است؟', 2, 1, 64, 241, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:36:49', 6, 'done'),
(2717, ' نمودار سهمی $f(x) = ax^2 + bx - 3c$ به‌صورت مقابل است. اگر $f(\\frac{c}{a}) = -8$ باشد، مقدار $a$ کدام است؟', 1, 1, 64, 237, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:37:45', 6, 'done'),
(2718, 'اگر $\\alpha, \\beta$ ریشه‌های معادله‌ی $x^2 - x - 4 = 0$ و $\\frac{2}{\\alpha^2 + \\alpha} , \\frac{2}{\\beta^2 + \\beta}$ ریشه‌های معادله‌ی $x^2 + mx + n = 0$ باشند، حاصل $m + n$ کدام است؟', 2, 1, 64, 241, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:38:11', 6, 'done'),
(2719, ' اگر $x^2 + kx + 1 = 0$ و $x^2 - \\frac{1}{x^2} = 3\\sqrt{5}$ باشد، مقدار مثبت $k$ کدام است؟', 2, 1, 64, 240, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:38:58', 6, 'done'),
(2720, ' در معادله درجه دوم $f(x) = ax^2 + bx - 2 = 0$ یکی از ریشه‌ها، سه برابر ریشه‌ی دیگر است. عرض رأس سهمی $f$ کدام است؟', 2, 1, 64, 237, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:39:16', 6, 'done'),
(2721, ' قدر مطلق تفاضل ریشه‌های معادله‌ی $2x - 2 = \\sqrt{2x^2 - x - 2}$ چه عددی است؟', 2, 1, 58, 238, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:39:38', 6, 'done'),
(2722, ' هرگاه $f(x) = \\frac{2x + 4}{x - 2}$ در بازه $(-\\infty, \\alpha)$ در نابرابری $f(x) < 2$ صدق کند، حداکثر مقدار $\\alpha$ کدام است؟', 1, 1, 57, 236, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:39:59', 6, 'done'),
(2723, ' اگر $A = \\frac{3}{\\sqrt[3]{4} - \\sqrt[3]{2} + 1}$ باشد، حاصل $(A - 1)^9$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:40:14', 6, 'done'),
(2724, ' اگر $A = \\frac{\\sqrt[3]{2} \\times \\sqrt[6]{3^5} \\times \\sqrt[5]{4}}{6^{\\frac{11}{15}}}$ باشد، حاصل $\\frac{1}{A^{10} + 1}$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-24 23:53:07', 1, '2026-04-10 16:40:25', 6, 'done'),
