(2861, 'واریانس و میانگین ده داده آماری به ترتیب $4$ و $6$ می‌باشد. اگر به هر یک از داده‌ها $5$ واحد اضافه کرده و حاصل را در $2$ ضرب کنیم، ده داده جدید به دست می‌آید. ضریب تغییرات داده‌های جدید چقدر است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 19:32:04', 6, 'done'),
(2862, 'در یک بیمارستان، دو گروه پرستار هستند. گروه اول قد و گروه دوم وزن نوزادان را اندازه‌گیری می‌کنند. میانگین نمرات مسئولیت‌پذیری و واریانس در گروه اول به ترتیب $95$ و $25$ و در گروه دوم نیز $84$ و $16$ می‌باشد. کدام گروه بهتر است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:14:34', 6, 'done'),
(2863, 'به ترتیب «مجموعه تمام افراد یا اشیایی که درباره یک یا چند ویژگی آن‌ها تحقیق صورت می‌گیرد ............» و «در علم آمار، به مرحله بعد از جمع‌آوری اعداد، ............ می‌گویند.»', 1, 1, 1, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:14:53', 6, 'done'),
(2864, 'در داده‌های $16,47,38,22,31,18,27,14,45,23,35,29,22$ انحراف معیار داده‌های بین چارک اول و سوم تقریباً کدام است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:15:04', 6, 'done'),
(2865, 'در داده‌های آماری $42,22,21,20,18,17,15,14,12,10,8,7$ واریانس داده‌های بین چارک اول و سوم کدام است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:15:14', 6, 'done'),
(2866, 'در داده‌های آماری $20,16.5,13,12,14.5,18,15,16,18.5$ داده‌های بزرگ‌تر از چارک سوم و کوچک‌تر از چارک اول را حذف می‌کنیم. ضریب تغییرات داده‌های باقی‌مانده کدام است؟ ($\\sqrt{6}\\approx 2/4$)', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:15:25', 6, 'done'),
(2867, 'انحراف معیار داده‌های جدول زیر، $13$برابر ضریب تغییرات آنها است. چارک سوم داده‌ها کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:15:36', 6, 'done'),
(2868, ' در داده‌های زیر اختلاف میانگین و چارک سوم داده‌ها کدام است؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:15:47', 6, 'done'),
(2869, ' میانگین داده‌های $x_1,x_2,\\dots,x_n$ برابر $8$ و ضریب تغییرات این داده‌ها برابر $0.5$ است. واریانس داده‌های $\\frac{1}{2}x_1+1,\\frac{1}{2}x_2+2,\\dots,\\frac{1}{2}x_n+1$ کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:16:33', 6, 'done'),
(2870, ' اگر مجموع مربعات $20$ داده آماری برابر $320+$20\\bar{x}^2باشد، انحراف معیار داده‌ها کدام است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:16:55', 6, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(2871, 'واریانس و میانگین $10$ داده آماری به ترتیب $9$ و $20$ است. اگر به هر یک از داده‌ها $5$ واحد اضافه کرده و سپس حاصل را در عدد $4$ ضرب کنیم، ضریب تغییرات داده‌های جدید کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:17:45', 6, 'done'),
(2872, ' تعداد تصادفات اتومبیل‌ها در $15$ روز اول فروردین در شهری به‌صورت زیر گزارش شده است:\n\n$19,31,26,19,32,41,43,3416,27,14,23,15,10,12$\n\nواریانس داده‌های بین چارک اول و سوم پس از حذف میانه کل داده‌ها کدام است؟', 2, 1, 1, 261, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:17:56', 6, 'done'),
(2873, ' مجموع چارک‌های اول و سوم در داده‌های آماری $(16 2),(16 3) , $ (16 13),\\dots,(16 4) برابر با نصف کدام گزینه است؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:18:30', 6, 'done'),
(2874, ' داده‌های متمایز $x_1,x_2,\\dots,x_n$ از کوچک به بزرگ نوشته شده‌اند. به داده اول ($x_1$)، $m$ واحد اضافه می‌کنیم و دامنه تغییرات ثابت می‌ماند. $m>0$، کدام است؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:18:57', 6, 'done'),
(2875, 'واریانس و میانگین $10$ داده آماری به‌ ترتیب $9$ و $20$ است. اگر به هر یک از داده‌ها $5$ واحد اضافه و سپس حاصل را در عدد $4$ ضرب کنیم، ضریب تغییرات داده‌های جدید کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:19:08', 6, 'done'),
(2876, ' در داده‌های آماری $3,4,5,9,8,11,17,9,6,4,3,2$  ضریب تغییرات داده‌های بین چارک اول و چارک سوم کدام است؟', 2, 1, 1, 262, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:19:21', 6, 'done'),
(2877, ' در داده‌های $10,4,5,7,6,12,2$  ضریب تغییرات چند برابر $\\sqrt{\\frac{10}{7}}$ است و با حذف داده‌های کوچک‌تر از چارک اول و داده‌های بزرگ‌تر از چارک سوم، دامنه تغییرات چند درصد کاهش می‌یابد؟', 2, 1, 1, 262, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:19:46', 6, 'done'),
(2878, 'اگر $x$ عددی طبیعی و میانه داده‌های $12,6,8,15,4,x,13,3$برابر $7$ باشد، آنگاه چند مقدار متمایز برای $x$ وجود دارد؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:19:57', 6, 'done'),
(2879, ' در آزمایش پرتاب دو تاس، احتمال اینکه مجموع دو تاس مساوی $n$ شود، برابر با $\\frac{5}{36}$ است. $n$ داده آماری موجود است و میانه آنها یکی از خود داده‌هاست، احتمال اینکه با حذف یکی از داده‌ها، چارک دوم تغییر کند، کدام است؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:20:25', 6, 'done'),
(2880, ' چارک دوم تعدادی داده آماری برابر $4$ است. قرینه میانگین داده‌های کوچک‌تر از میانه، $8$ واحد کوچک‌تر از میانگین داده‌های بزرگ‌تر از میانه است. اگر تعداد داده‌ها فرد باشد، میانگین کل داده‌ها کدام است؟', 2, 1, 1, 260, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:10:29', 1, '2026-04-10 23:20:36', 6, 'done'),
(2881, ' ظرفی شامل 4 مهره آبی و 2 مهره قرمز است. در کدام حالت تعداد عضوهای فضای نمونه‌ای بیشتر است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:21:06', 6, 'done'),
(2882, ' اگر $P(A)=0.3$ و $P(A \\cap B)=0.1$ باشد، آنگاه حاصل $P(A\' \\cup B)$ کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:21:19', 6, 'done'),
(2883, ' یک سکه را پنج بار پرتاب می‌کنیم. احتمال اینکه «2 رو» یا «2 پشت»، به‌صورت متوالی ظاهر نشوند، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:21:38', 6, 'done'),
(2884, ' چهار سکه و دو تاس را با هم پرتاب می‌کنیم. به چه احتمالی هر چهار سکه یکسان و هر دو عدد رو شده تاس برابر ظاهر می‌شوند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:21:50', 6, 'done'),
(2885, ' از هر کدام از شهرهای تبریز، تهران، شیراز و اصفهان، 3 نفر در یک جلسه شرکت کرده‌اند. می‌خواهیم 5 نفر را به عنوان هیأت مدیره انتخاب کنیم. چقدر احتمال دارد که 2 نفر از یک شهر، 2 نفر از شهر دیگر و یک نفر از شهر دیگری باشند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:22:08', 6, 'done'),
(2886, ' در پرتاب دو تاس با هم، چقدر احتمال دارد مجموع ارقام رو شده زوج یا مضرب 5 باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:22:32', 6, 'done'),
(2887, ' با کنار هم قرار دادن حروف و ارقام Covid19 یک رمز شامل 3 حرف و 2 رقم می‌سازیم. چند درصد احتمال دارد که بین دو رقم رمز حتما یک حرف قرار بگیرد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:22:51', 6, 'done'),
(2888, ' یک تاس سفید و یک تاس سیاه را می‌اندازیم. اگر مجموع دو تاس 8 باشد، احتمال اینکه تاس سفید عددی اول باشد، چقدر است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:23:10', 6, 'done'),
(2889, '9 توپ یکسان را پرتاب می‌کنیم به‌طوری که هر یک حتما داخل یکی از سوراخ‌های $4 \\times 4$ زیر قرار می‌گیرد. با چه احتمالی این سه توپ در یک ردیف و یا در یک ستون قرار دارند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:23:29', 6, 'done'),
(2890, ' روی تاس اعداد $1و1,2,3,3,4,5$ و روی تاس دیگر اعداد $1,2,3,3,3,5$ حک شده است. این دو تاس را با هم پرتاب می‌کنیم. احتمال آنکه مجموع اعداد رو شده 4 باشد، چقدر است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:23:44', 6, 'done'),
(2891, ' در جعبه‌ای 8 مهره داریم که 2 تای آنها سفید است. مهره‌ها را یکی یکی خارج می‌کنیم تا زمانی که هر دو مهره سفید خارج شود. احتمال آنکه این آزمایش با خروج 5 مهره پایان یابد، چقدر است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:24:04', 6, 'done'),
(2892, ' از مجموعه اعداد طبیعی یک رقمی، ۶ عدد متمایز به تصادف انتخاب می‌کنیم. با کدام احتمال مجموع اعداد انتخابی زوج است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:24:23', 6, 'done'),
(2893, ' احتمال برخورد تیری به هدف $0.75$ است. حداقل چند تیر باید پرتاب شود تا احتمال برخورد حداقل یک تیر به هدف بالای $98$ درصد باشد؟', 2, 1, 52, 224, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:24:56', 6, 'done'),
(2894, ' ۳ تاس را پرتاب می‌کنیم، با چه احتمالی مجموع 2 تاس برابر با سوم است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:25:19', 6, 'done'),
(2895, ' اگر $P(A)=0.6$ و $P(B\')=0.7$ و $P(A\' \\cup B)=0.5$ باشد، $P(B|A´)$ کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:25:32', 6, 'done'),
(2896, ' احتمال مبتلا شدن به یک بیماری خاص برای فردی که واکسن زده $0.2$ و برای فردی که واکسن نزده $0.6$ است. تا این لحظه $75$ درصد افراد جامعه واکسن زده‌اند. چقدر احتمال دارد که در این جامعه یک فرد مبتلا نشود؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:25:46', 6, 'done'),
(2897, ' از مجموعه  $\\{202,202,203 ,\\dots,800\\}$ عددی به تصادف انتخاب می‌کنیم، با کدام احتمال این عدد بر ۳ بخش‌پذیر است ولی مضرب 5 نیست یا بر 3 بخش‌پذیر است ولی مضرب 5 است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:26:06', 6, 'done'),
(2898, ' ظرف اول شامل ۵ مهره سفید و ۳ مهره سیاه و ظرف دوم شامل ۶ مهره سفید و ۵ مهره سیاه است. یک ظرف را به تصادف انتخاب کرده و مهره‌ای را از آن برمی‌داریم. اگر بخواهیم احتمال سیاه و سفید بودن مهره برابر باشد، چند مهره سیاه باید به ظرف دوم اضافه کنیم؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:28:48', 6, 'done'),
(2899, 'پدر و مادر علی دارای ۳ فرزند هستند. اگر علی خواهر داشته باشد، چقدر احتمال دارد که دارای برادر بزرگتر از خود باشد؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:29:07', 6, 'done'),
(2900, ' برای تابع درجه دوم $f(x)=ax^2+bx+c$ ضرایب $a,b,c$ را به‌طور تصادفی از مجموعه $A=\\{±3,±2,±1,0, \\}$ انتخاب می‌کنیم. احتمال اینکه نمودار تابع بدست آمده بصورت مقابل باشد کدام است؟ ( $a,b,c$ متمایزند.)', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:29:22', 6, 'done'),
(2901, ' در پرتاب یک تاس قرمز و یک تاس آبی، اگر $A$ پیشامد آن باشد که تاس آبی عدد 4 بیاید و $B$ پیشامد آن باشد که مجموع دو تاس برابر$k$  باشد، آنگاه برای کدام مقدار$k$ که در گزینه‌های آمده، دو پیشامد مستقل هستند؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:29:40', 6, 'done'),
(2902, ' در یک خانواده ۵ فرزندی که فرزندان اول و آخر غیر هم‌جنس هستند. احتمال اینکه خانواده دارای 2 فرزند پسر باشد، کدام است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:30:05', 6, 'done'),
