(2938, ' اگر $P(A - B) = 0.5$ و $P(B) = 0.4$ و $P(A) = 0.7$  و بدانیم حداقل یکی از دو پیشامد AوB رخ داده است، با کدام احتمال هر دو پیشامد رخ داده‌اند؟', 2, 1, 52, 222, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:39:41', 6, 'done'),
(2939, ' در یک مسابقه، احتمال آن که تیراندازی یک هدف را بزند، برابر با $0.7$ و احتمال آن که دو هدف متوالی را بزند، برابر $0.65$  است. اگر تیرانداز هدف دوم را زده باشد، با کدام احتمال هدف اول را هم زده است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:40:08', 6, 'done'),
(2940, ' تاسی را پرتاب می‌کنیم. اگر مضرب ۳ ظاهر شود سه سکه، در غیر این صورت  دو سکه پرتاب می‌کنیم. احتمال اینکه دقیقاً یک بار رو ظاهر شود کدام است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:40:24', 6, 'done'),
(2941, 'در یک شهر \\frac{2}{5}/ مردم واکسن زده‌اند و احتمال انتقال نوعی بیماری به افرادی که واکسنی نزده‌اند، سه برابر احتمال انتقال آن به افرادی است که واکسن زده‌اند. اگر احتمال سالم ماندن افراد در این شهر \\frac{۶۷}{۱۰۰} باشد، آن‌گاه احتمال انتقال بیماری به افرادی که واکسن نزده‌اند کدام است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:40:38', 6, 'done'),
(2942, 'اگرA و B دوپیشامد مستقل باشند به‌طوری $P(B\'|A) = \\frac{1}{5}$ و $3P(A \\cap B) = P(B)$، که آنگاه $P(B - A)$، کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, '2026-04-10 23:40:56', 6, 'done'),
(2943, '63-در جعبه‌ای ۶ مهره قرمز، ۴ مهره آبی و ۳ مهره زرد دیده می‌شود. با چشمان بسته، یکی‌یکی و به طور متوالی ۴ مهره خارج می‌کنیم. با کدام احتمال تقریبی، تعداد مهره‌های زرد انتخاب شده بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2944, '64- احتمال ایمنی فردی در برابر ویروس نوع A،$0.4$ و در برابر ویروس نوع B،$0.5$ است. اگر ایمنی فرد در برابر ویروس نوع A ایمن باشد، احتمال ایمنی او در برابر ویروس نوع B برابر با $0.75$ است. با فرض اینکه این فرد در برابر ویروس نوع A ایمن نباشد، احتمال اینکه در برابر ویروی نوع B نیز ایمن نباشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2945, '65-در رأی‌گیری انتخابات یک مدرسه، احتمال پیروزی سارا برابر با $\\frac{2}{5}$ می‌باشد. اگر سارا بتواند از علی در تعداد رأی جلو بیفتد، این احتمال به $\\frac{1}{2}$ افزایش می‌یابد.اگر احتمال پیروزی علی در این رأی‌گیری$\\frac{2}{3}$  باشد، با چه احتمالی علی از سارا در تعداد رای جلو می‌افتد( فرض بر این است که تعداد ذای‌های سارا و علی به هیچ‌وجه برابر نخواهد شد و رای‌گیری فقط بین این دو نفر است)؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2946, '66-دو تاس سالم را با هم پرتاب می‌کنیم. تا برای اولین بار هر دو عدد رو شده زوج باشد، با کدام احتمال حداکثر در سه پرتاب نتیجه مطلوب حاصل می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2947, '67-2 درصد افراد جامعه‌ای دانشجو هستند. در یک نمونه از آزمایش فهمیدند اگر فردی دانشجو باشد، به احتمال $۷۰٪$ به مسافرت علاقه‌مند است و اگر دانشجو نباشد، به احتمال ۴۰٪$$ به مسافرت علاقه‌مند نیست. یک فرد از بین افراد علاقه‌مند به مسافرت انتخاب می‌کنیم؛ با کدام احتمال فرد انتخاب شده دانشجو است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2948, '68-در پرتاب دو تاس،اگر پبشامد اینکه دو عدد رو شده اول باشند را $A$ و پیشامد اینکه محموع دو عدد رو شده $7$ باشند راB  بنامیم. کدام گزینه صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2949, '69-سه تاس را پرتاب می‌کنیم. احتمال اینکه بزرگترین عدد رو شده مضربی از کوچکترین عدد رو شده باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2950, '70-دو ظرف مشابه داریم. اولی شامل ۵ مهره آبی و ۴ مهره قرمز و دومی شامل ۳ مهره آبی و 4 مهره قرمز است. از ظرف اول دو مهره خارج می‌کنیم و در ظرف دوم می‌اندازیم، سپس از ظرف دوم مهره‌ای خارج می‌کنیم. با کدام احتمال، این مهره آبی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2951, '71-از بین مربع‌هایی که در شکل زیر مشاهده می‌شوند، یکی را به تصادف انتخاب می‌کنیم. احتمال اینکه نقطه M یکی از رأس‌های مربع انتخاب شده باشد، چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2952, '72-احتمال رخداد پیشامدهای A و B به ترتیب $0.4$ و $0.3$ است. اگر پیشامد A رخ دهد، احتمال رخداد B، $0.4$ افزایش می‌یابد. اگر پیشامد B رخ ندهد، با چه احتمالی پیشامد A رخ نمی‌دهد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2953, '73-یک تاس سالم را سه بار متوالی پرتاب می‌کنیم. اگر مجموع سه عدد ظاهر شده ۱۶ باشد، با کدام احتمال تاس اول و سوم یکسان ظاهر شده‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2954, '74-دو نفر با هم مسابقه هدف‌گیری با کمان اجرا می‌کنند. احتمال به هدف زدن نفر اول $0.8$ و نفر دوم $0.6$ است. ابتدا نفر اول و بعد نفر دوم و به همین ترتیب، مسابقه تا زمان به هدف زدن ادامه می‌یابد. با چه احتمالی نفر دوم در پرتاب دوم بازی را می‌برد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2955, '75-اگر A و B دو پیشامد مستقل از فضای نمونه‌ای بوده و تعداد اعضای A و B و $A-B\'$ به ترتیب ۲۰ و ۱۶ و ۵ باشند، فضای نمونه‌ای این پدیده تصادفی چند عضو دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2956, '76-از جعبه‌ای شامل ۳ مهره سفید، ۵ مهره سیاه و ۷ مهره قرمز ابتدا ۲ مهره بدون رویت خارج می‌کنیم، سپس از ۱۳ مهره باقیمانده، ۲ مهره دیگر خارج می‌کنیم. احتمال اینکه ۲ مهره اخیر هم‌رنگ باشند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2957, '77-دو کارخانه داریم که تولیدات کارخانه اول $2$ برابر کارخانه دوم است. احتمال تولید کالای معیوب توسط کارخانه اول $\\frac{1}{100}$ و توسط کارخانه دوم $\\frac{2}{100}$ است. یک کالا به تصادف از تولیدات این دو کارخانه انتخاب می‌کنیم، احتمال اینکه معیوب باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2958, '78-ده درصد چینی‌ها و سی درصد ایرانی‌ها قد بالای $۱۷۰$ سانتی‌متر دارند. در جمعی از $3$ ایرانی و $5$ چینی، $2$ نفر را به تصادف انتخاب می‌کنیم. با کدام احتمال هر دو قد بالای $170\\text{ cm}$ دارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 12:47:42', 1, NULL, NULL, 'free'),
(2959, 'اگر مجموع ریشه‌های کوچکترین مضرب مشترک دو عبارت $x^3-3x^2-4a^2x+12a^2$ و $x^3-bx^2-9x+4b$ برابر با $-6$ باشد، کمترین مقدار عبارت $x^2+bx+b+1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2960, 'اگر $x=2$ یکی از ریشه‌های معادله  $9ax^2-3bx+2a=0$باشد، ریشه دیگر کدام است؟ $(a,b\\neq0)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2961, 'چند جمله زیر در مورد سهمی $y=ax^2+bx+c$ درست است؟\n\nهرگاه راس سهمی در $(2,3)$ و از نقطه $(-1,-3)$بگذرد، $a=1$ است.\n\n  هرگاه a=2 ، b=-8 و یکی از صفرهای تابع 2 واحد از صفر دیگر تابع بیشتر باشد، $c=6$ است.\n\nهرگاه محور $x$ ها را در دو نقطه به طول های $3$ و$-2$ و محور $y$ها را در $8$ قطع کند،$a=-\\frac{4}{3} \n\n\n\nاگر $a=-3$ ، $\\delta>0$ و صفرهای تابع  6واحد اختلاف داشته باشند، سهمی دارای بیشترین مقدار27 است.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2962, 'به ازای کدام مقدار $a$، معادله درجه دوم $(a+1)x^2+a(a^2-9)x+2=0$ دو ریشه حقیقی قرینه دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2963, 'چند سه‌جمله‌ای به صورت $x^2+ax+b$ وجود دارد که ریشه آن $a$ و $b$ باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2964, 'قرینه منحنی $y=\\log_2(2x+1)$ نسبت به نیمساز ناحیه اول خط قائم $x=2$ را با کدام عرض قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2965, 'به ازای کدام مقدار $m$، منحنی $y=(m-2)x^2-x+m$ بالاتر از خط $y=2(x-1)$ قرار گرفته و مماس بر آن است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2966, 'اگر اعداد مثبت $a,b,c,d$ در رابطه $abcd=1$ صدق کنند، کمترین مقدار $(1+a)(1+b)(1+c)(1+d)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2967, 'جواب معادله $\\sqrt{x-2+\\sqrt{2x-5}}+\\sqrt{x+2+3\\sqrt{2x-5}}=\\sqrt{2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2968, 'اگر دو سهمی $f(x)$ و $g(x)$ به شکل زیر در دو نقطه یکدیگر را قطع کنند، مقدار $f(4)-g(4)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2969, 'مجموع ریشه‌های معادله $16{|2^x-1|-11|x|}=5x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2970, 'اگر $\\alpha$ و $\\beta$ ریشه‌های معادله $x^2-4x-2=0$ باشند، حاصل $\\alpha^3+18\\beta$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2971, 'معادله $\\left|\\frac{1}{2}x\\right|=\\frac{2}{5}x$ چند ریشه دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2972, 'اگر $a>b$ و $\\sqrt{a}+\\sqrt{b}=4$ و $ab=9$ باشد، حاصل $a\\sqrt{a}-b\\sqrt{b}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2973, 'اگر ریشه معادله $x^2+bx+a=6$ برابر $-\\frac{a}{2}+3$ و ریشه معادله $bx^2-ax-2=0$ برابر $\\frac{1}{2}$ باشد، $a+b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2974, 'مجموع ارقام ریشه معادله $\\sqrt{x+\\sqrt{4/5x-41}}=15$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2975, 'اگر $\\alpha$ و $\\beta$ ریشه‌های غیرحقیقی معادله $x^2-\\sqrt{17}x+9=0$ باشند، حاصل $(\\alpha-\\beta)^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2976, 'اگر ریشه حقیقی و قابل قبول معادله $\\sqrt{x+1}-\\sqrt{2x-5}=1$ برابر طول رأس سهمی $f(x)=-x^{2}+kx+8$ باشد، بیشترین مقدار تابع سهمی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2977, 'اگر $\\sqrt{x+2}+\\sqrt{x-4}=3$ حاصل عبارت $\\sqrt{x+2}-\\sqrt{x-4}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2978, 'به ازای چه مقدار صحیح $k$ نمودار سهمی $y=kx^{2}-kx-4$ همواره پایین محور $x$ها است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2979, 'نمودار یک سهمی از نقاط $(1,-2)$ و $(2,-3)$ گذشته و محور$y$ ها را در نقطه‌ای به عرض $1$ قطع می‌کند. مجموع طول و عرض رأس این سهمی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2980, 'اگر $M=(\\sqrt{2}-\\sqrt{3}+\\sqrt{2+\\sqrt{3}})\\times \\sqrt[3]{2\\sqrt{2}}$ باشد، مقدار $M^{2}$ در کدام مورد درست بیان شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2981, 'فاصله بین دو شهر $240$ کیلومتر است. راننده‌ای این مسیر را در رفت و برگشت با سرعت ثابت طی می‌کند. اگر در مسیر برگشت سرعت را $10$ کیلومتر بر ساعت بیشتر کند $20$ دقیقه زودتر به مقصد می‌رسد. سرعت مسیر رفت چند کیلومتر بر ساعت بوده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2982, 'در یک قطعه زمین اگر $35$ درخت میوه با فاصله‌های مساوی کاشته شود، پس از رشد کافی از هر درخت بطور متوسط $90$ کیلوگرم میوه برداشت می‌شود و به ازای هر درخت اضافی که کاشته شود، دو کیلوگرم از متوسط محصول هر درخت کم می‌شود. حداکثر برداشت میوه با این شرایط چند کیلوگرم است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2983, 'معادله$2-|^{x}|=\\log_{2}|x|$ چند ریشه حقیقی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2984, 'اگر کل مجموعه جواب نامعادله $-2<\\frac{ax+1}{2x+b}<5$ به صورت $R-[1,3]$ باشد، حاصل $\\frac{a}{b}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2985, 'اگر $a=\\sqrt{4+\\sqrt{7}}-\\sqrt{4-\\sqrt{7}}$ باشد، حاصل $\\sqrt{a^{3}+a^{2}+1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2986, 'سهمی $y=mx^{2}+(2m-4)x+5+m$ فقط از ناحیه چهارم محورها‌ی مختصات نمی‌گذرد. $m$ چند مقدار صحیح می‌تواند اختیار کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2987, 'اگر $\\alpha$ و $\\beta$ ریشه‌های معادله $3x^{2}-x-1=0$ باشند، معادله زیر ریشه‌های $\\{\\alpha^{2}+\\beta,\\alpha+\\beta^{2}\\}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2988, 'چند مقدار صحیح در نامعادله $4|x-3|+2|x+1| \\le x$ صدق می‌کنند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2989, 'در معادله درجه دوم $mx^2-x-6=0$، یک ریشه از 2 برابر ریشه دیگر 5 واحد بیشتر است. مقدار $m$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2990, '۳۶- حاصل عبارت $(\\sqrt{3}+\\sqrt{5})(\\sqrt[4]{9}+1)^{-1}(\\sqrt{5}+\\sqrt{22}+\\sqrt{5}\\times\\sqrt{5}-\\sqrt{22}+\\sqrt{5})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2991, '۳۷- حاصل ضرب ریشه‌های حقیقی معادله $(x^2-3x)^2+5(x^2-3x)+4=0$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2992, '۳۸- اگر $\\frac{1}{\\beta}$ و $\\frac{1}{\\alpha}$ صفرهای تابع $f(x)=x^2-4x+2$ باشند، مقدار $f(\\alpha+\\beta)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2993, '۳۹- اگر $\\alpha$ و $\\beta$ ریشه‌های معادله $x^2+x-1=0$ باشند، به ازای کدام مقدار $m$ تساوی $\\alpha\\sqrt{m+\\beta}+\\beta\\sqrt{m+\\alpha}=\\sqrt{5}$ برقرار است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2994, '۴۰- مجموعه جواب نامعادله $\\frac{-x^2+3x-2}{x^3-1}>1$ به صورت $(a,b)$ است. مقدار $\\frac{a+b}{2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2995, '۴۱- حاصل عبارت $13\\times\\left(\\frac{2(2-\\sqrt{2})^0.5}{19-8\\sqrt{3}}\\right)^{\\frac{1}{2}}\\times\\sqrt[4]{3+2\\sqrt{2}}$کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2996, '۴۲- اگر $\\alpha$ ریشه معادله $\\left(\\frac{x^2-1}{x}\\right)^2-2x+\\frac{2}{x}+1=0$ باشد، حاصل $\\frac{1+\\alpha^4}{\\alpha^2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2997, '۴۳- اگر $\\alpha$ ریشه معادله $\\left(\\frac{x-1}{x}\\right)^2+3-\\frac{2}{x}=0$ باشد، حاصل $(8\\alpha^{-1})^0.5$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2998, '۴۴- مساحت محدود بین دو نمودار $f(x)=|x-1|$ و $g(x)=8-|x-5|$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(2999, '۴۵- اگر $A=\\sqrt{\\frac{36}{\\sqrt[3]{9}}}\\3\\sqrt[3]{3}$ باشد، عدد $\\left(\\frac{1}{2A}\\right)^{-2}$ حداقل چند واحد از مربع یک عدد طبیعی کمتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3000, '۴۶- فرض کنید $\\alpha$ و $\\beta$ ریشه‌های معادله $x^2+(2-m)x+m-3=0$ باشند. اگر بزرگترین بازه برای $m$ به طوری که رابطه $\\alpha^2\\beta+\\alpha\\beta^2<0$ همواره برقرار است، بازه $(a,b)$ باشد، مقدار $a+b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3001, '۴۷- دو شرکت راهسازی $A$ و $B$ پروژه‌ای را با هم در 18 روز به پایان می‌رسانند. اگر هر یک از آن‌ها به تنهایی این پروژه را انجام دهد، شرکت $A$، 15 روز زودتر از شرکت $B$ پروژه را تمام خواهد کرد. اگر پس از سه روز کار مشترک، شرکت $B$ از انجام کار انصراف دهد، چند روز دیگر طول می‌کشد تا شرکت $A$ پروژه را به اتمام برساند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3002, '۴۸- مجموعه جواب نامعادله $\\left|\\frac{x-4}{2x-3}\\right|>1$ به صورت $(a,b)-\\{x_0\\}$ است. بیشترین مقدار $b-a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3003, '۴۹- حاصل عبارت $\\frac{1}{\\sqrt{5}-\\sqrt{3}+\\sqrt{2}}\\cdot(2\\sqrt{3}-3\\sqrt{2}-\\sqrt{30})^{-1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3004, '۵۰- حاصل عبارت $\\sqrt{4+\\sqrt{7}}-\\sqrt{4-\\sqrt{7}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3005, '۵۱- مجموعه جواب نامعادله $2x^2-4x+4-5|x-1|\\ge0$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3006, '۵۳- اگر $x_1$ و $x_2$ ریشه‌های معادله درجه دوم $x^2-3x+1=0$ باشند، مقدار $x_2\\sqrt{x_1}+x_1\\sqrt{x_2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3007, '۵۴- ساده شده عبارت $\\frac{x\\sqrt{x+\\sqrt{x}}}{\\sqrt{x}-\\sqrt{x}}\\times\\frac{x-1}{x+\\sqrt{x}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3008, '۵۵- علامت عبارت $P(x)=\\frac{(x^2-x+1)^3|1-x^2|\\sqrt{16-x^2}}{-x^4(x-1)^5(x^2+2x-3)^3}$ در کدام بازه همواره مثبت است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3009, '۵۶- معادله درجه دوم $\\frac{ax^2}{4}+(a-2)x+1=0$ دارای دو ریشه حقیقی با علامت‌های مختلف است. اگر قدر مطلق ریشه منفی معادله بزرگتر از ریشه مثبت معادله باشد، حدود a کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3010, '۵۷- معادله قدر مطلقی $|5-2x|+|3+2y|=17$ به ازای چند عدد صحیح x جواب دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3011, '۵۸- نمودار سهمی $y=ax^2+bx+C$ محور x ها را در نقاط$3pm\\sqrt{2}$ و محور $y$ ها را با عرض $-14$ قطع می کند. حاصل $a^2+b^2+c^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3012, '۵۹- ریشه‌های کدام معادله درجه 2، از سه برابر ریشه‌های معادله$2\\sqrt{2t-1}-t=1$ به اندازه هشت واحد کمتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3013, '۶۰- اگر $x+y=19$ و $xy=9$ باشد، حاصل $x\\sqrt{x}+y\\sqrt{y}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3014, '۶۲- دو تاس را پرتاب می‌کنیم و مجموع اعداد ظاهر شده را به جای m در معادله $2x^2-2mx+7m-26=0$ قرار می‌دهیم. چقدر احتمال دارد که ریشه‌های معادله، دو عدد فرد متوالی باشند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3015, '۶۳- واسطه هندسی منفی بین ریشه‌های معادله $\\sqrt{2x^2-6x+8}=3x-x^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3016, '۶۴- اگر $x+\\frac{1}{x}=3$ آنگاه $B=x^2+\\frac{1}{x^2}$ است. با فرض $A=\\frac{3\\sqrt{3}-8}{7+2\\sqrt{3}}+\\sqrt{7+4\\sqrt{3}}$ حاصل $A^2+B+1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3017, '۶۵- چند عدد صحیح در تساوی قدرمطلقی $|x^2-5x-24|=24+5x-x^2$ صدق می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3018, '۶۶- اگر $\\alpha$ و $\\beta$ ریشه‌های معادله $4x^2+6x-1=0$ باشند، آنگاه ریشه‌های معادله $ax^2+bx+c=0$ به صورت $\\alpha+3\\beta$ و $\\beta+3\\alpha$ خواهند بود. اگر $a,b,c$ اعداد طبیعی باشند، حاصل $a+b+c$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3019, '۶۷- قطاری فاصله 340 کیلومتری بین دو شهر را با سرعت ثابت به صورت رفت و برگشت طی می‌کند. اگر در مسیر رفت سرعت قطار 20 کیلومتر بر ساعت بیشتر باشد، 36 دقیقه زودتر می‌رسد. سرعت قطار در مسیر برگشت چند کیلومتر بر ساعت بوده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3020, '۶۸- با فرض $x=\\sqrt[4]{7-4\\sqrt{3}}$ مقدار $(x+\\frac{1}{x}+\\sqrt{3})^2(x+\\frac{1}{x}-\\sqrt{2})^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3021, '۶۹- معادله $2x^2-x+a-1=0$ حداقل یک ریشه و معادله $ax^2+x-\\frac{1}{4}=0$ حداکثر یک ریشه دارد. با فرض اینکه $b$ حداکثر و $c$ حداقل مقدار $a$ باشد، حاصل ضرب وارون ریشه‌های معادله $acx^2-abx+1=0$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3022, '۷۰- اگر $x=3+2\\sqrt{2}$ باشد، حاصل $\\sqrt{x^2+5}-\\sqrt{x^{-2}+5}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3023, '۷۱- اگر $\\frac{27-8x^3}{3x+1}\\ge0$ باشد، مجموعه مقادیر $[2-5x]$ چند عضو دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3024, '۷۲- معادله $\\frac{2\\sqrt{x+4}}{x^2-16}=1$ چند جواب حقیقی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3025, '73- یک تاس را پرتاب می‌کنیم و عدد رو شده را به جای $m$ در معادله $x^{4}-2(m-2)x^{2}+14=m$ قرار می‌دهیم. احتمال اینکه معادله دارای 4 ریشه حقیقی متمایز باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:03', 1, NULL, NULL, 'free'),
(3026, '74- رئوس سهمی‌های $f(x)=2x^{2}+bx+c$ و $g(x)=-x^{2}+4x+k$ برهم منطبق‌اند. به ازای چند مقدار صحیح منفی برای $k$، نمودار تابع $y=(2c-4)x^{2}+2bx+6$ خط $y=2$ را قطع نمی‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:04', 1, NULL, NULL, 'free'),
(3027, '75- اگر معادله درجه دوم $x^{2}-(1+\\log a)x+\\log a=0$ فقط یک ریشه داشته باشد. تعداد ریشه‌های معادله $3^{\\log \\sin x}\\times 2^{\\log \\cos x}=\\frac{a}{10}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 13:52:04', 1, NULL, NULL, 'free'),
(3028, '1- اگر $P(x) = x^3 - x^2 - m + 1$ بر $x + 2$ بخش‌پذیر باشد، باقیمانده عبارت $P(x)P(x+1)$ بر $x - 1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3029, '2- اگر $f(x) = x^3 + 2x + m$ بر $x+1$ بخش‌پذیر باشد، حاصل $\\lim_{x \\to -1} \\frac{f(x)}{x^3 + x^2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3030, '3- اگر $\\lim_{x \\to 2} \\frac{[-x] + m - 1}{4 - x^2} = +\\infty$ باشد، حدود $m$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3031, '4- نمودار تابع $f(x)$ به صورت زیر است. حد راست تابع $g(x) = (f \\circ (f+2))(x)$ در نقطه $x = -1$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3032, '5- حاصل $\\lim_{x \\to 5} \\frac{\\tan(x-5)}{x^2 - 3x - 10}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3033, '6- حد چپ تابع $f(x) = \\frac{|1-x|+|1+x|}{|2x|-|x^2-1|}$ در نقطه‌ی $x=-1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3034, '7- حاصل $\\lim_{x \\to \\infty} \\frac{2\\sqrt{x+1}-\\sqrt{x+4}}{1-\\sqrt{x+1}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3035, '8- اگر $\\lim_{x \\to \\frac{\\pi}{4}} \\frac{a\\cos{2x}}{\\sin{x}-\\cos{x}} = \\sqrt{2}$ باشد، مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3036, '9- در صورتی که $\\lim_{x \\to -1} \\frac{\\sqrt{4|x|}-2}{ax+b} = \\frac{1}{2a+1}$ باشد، مقدار $3a$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3037, '10- اگر $\\lim_{x \\to 2} \\frac{4-x}{mx^2+nx-3} = \\frac{1}{m+n}$ باشد، حاصل $\\frac{m}{n}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3038, '11- اگر $x^2 + bx - 2 = 0$ و $\\lim_{x \\to 1} (ax^3 - 2x + b) = 7$ باشد، حاصل $\\lim_{x \\to 1^+} (ab[x])$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3039, '12- حد راست تابع $f(x) = |x| - |x^2|$ در $x = 2$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3040, '13- حد راست تابع $f(x) = |x| - |x^2|$ در $x = 2$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3041, '14- نمودار تابع $f(x)$ به صورت زیر است. اگر $a = 5$ و $\\lim_{x \\to a^-} f(x) = 15$ باشد، مجموع مقادیر ممکن برای $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3042, '15- اگر تابع $f(x) = \\begin{cases} ax - 1 & x > 1 \\\\ x^2 - |x| & x < 1 \\end{cases}$ حد داشته باشد، حاصل $\\lim_{x \\to 2} \\sqrt{f(x)}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3043, '16- مقدار $\\lim_{x \\to \\infty} \\frac{1 - \\sqrt{x+1}}{x+x^2}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(3044, '24- مقدار حد راست تابع $f(x)=\\frac{1-\\sqrt{2x}}{x-x^3}$ در $x \\to 1^+$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3045, '25- مقدار $\\lim_{x \\to +\\infty} \\frac{x}{x+4}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3046, '30- اگر $f(x) = \\sqrt{x}$ و $g(x) = \\frac{9x}{\\sqrt{x^2+1}}$ باشد، حاصل $\\lim_{x \\to +\\infty} \\frac{g(x)}{f(g(x))}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3047, '32- حاصل $\\lim_{x \\to 1^+} \\frac{[x]}{x^2 - 5x + 11x^3}$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3048, '33- در صورتی که $\\lim_{x \\to -\\infty} [x] = -\\infty$ باشد، حدود $a$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3049, '34- اگر $\\lim_{x \\to 1} \\frac{x^2 - x}{ax^3 - 3x^2 + 3x - a} = +\\infty$ باشد، مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3050, '35- مقدار $\\lim_{x \\to 2} \\frac{\\sin (x-2)}{|x - 4|}$ به ترتیب از راست و چپ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3051, '36- اگر نمودار $f(x)$ به صورت زیر باشد، کدام حد زیر درست محاسبه شده است؟ \n\n$$f(x) =\\begin{cases} 1 - 2x & x > 1 \\\\ 0 & x \\leq 1 \\end{cases}$$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3052, '37- حد تابع $f(x) = \\frac{x}{1 - \\sin x}$ در $x \\to \\frac{\\pi}{2}^+$ و حد تابع $g(x) = \\frac{1 - x}{| \\cos x |}$ در $x \\to \\frac{\\pi}{2}^-$ به ترتیب از راست به چپ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3053, '38- در صورتی که $\\lim_{x \\to 3} \\frac{x^3 + x^2 - 36}{\\sqrt{x + 1} - 2} = 120$ باشد، حاصل $\\lim_{x \\to 3} [\\frac{x^3 + x^2 - 36}{\\sqrt{x + 1} - 2}]$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3054, '39- اگر باقی مانده تقسیم $P(x)$ بر $x^2 + 3x + 2$ برابر $x+4$ باشد، باقی مانده تقسیم $P(x)$ بر $x - 1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3055, '40- اگر $f(x) = 3 - 2|x|$ باشد، حاصل $\\lim_{x \\to 2^+} \\frac{f(x) + 1}{f(x) + |x + 2|}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3056, '41- مقدار $\\lim_{x \\to 2^+} \\frac{2x^2 - 3x - 2}{x^2 - |x|}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3057, '42- در صورتی که $f(x) = 3x + \\sqrt{x^2 + 8}$ باشد، حاصل $\\lim_{x \\to 1} \\frac{f(x)}{x + 1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3058, '43- اگر $f(x) = \\frac{|x-2|}{x-2}$ باشد، کدام تابع زیر در $x = 2$ پیوسته است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3059, '44- مقدار $\\lim_{x \\to \\pi} \\frac{[-x] + 5 + \\cos x}{x^3 - 2 + \\cos^3 x}$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3060, '45- مقدار $\\lim_{x \\to 1^+} \\frac{\\sqrt{x} - 1}{[x] - 1}$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3061, '46- تابع $f(x) = \\frac{x + 1}{ax^3 + bx^2 - 1}$ در $x = 2$ و $x = 3$ ناپیوسته است. مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3062, '47- مقدار $\\lim_{x \\to \\frac{\\pi}{6}} \\frac{-3}{\\sin x - \\frac{1}{2}}$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3063, '48- نمودار تابع $f$ به صورت سهمی در شکل زیر داده شده است. حاصل $\\lim_{x \\to 1} \\frac{f(x)}{x^3 + 1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3064, '49- اگر $\\lim_{x \\to 2^+} (|x|-f(x))=4$ و $\\lim_{x \\to 2^+} (f(x)+g(x))=1$ باشد، حاصل $\\lim_{x \\to 2^+} f(x)g(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3065, '50- مقدار $\\lim_{x \\to \\frac{\\pi}{4}} \\frac{1+\\cos 4x}{3\\sin^2 2x+\\sin 2x-4}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3066, '51- پیوستگی توابع $f(x)=\\left[-\\frac{1}{x}\\right]+x$ و $g(x)=\\begin{cases} |x-2| & x \\neq 2 \\\\ x^2-4 & x = 2 \\end{cases}$ در $x=1$ کدام است؟ ([] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3067, '52- اگر $f(x)=x^4-x^3+1$ باشد، باقی مانده تقسیم $(fof)(x)$ بر $x+1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3068, '53- اگر درجه چندجمله‌ای $f(x) = a(x+1)^3 + (2a-6)(x-1)^3$ برابر ۲ باشد، حاصل $\\lim_{x \\to +\\infty} \\frac{a f(2x)}{x}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3069, '54- در صورتی که $\\lim_{x \\to 2} f(x) = -2$ و $\\lim_{x \\to 2} \\frac{f(g(x))}{g(x)+1} = 5$ باشد، حاصل $\\lim_{x \\to 2^-} g(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3070, '55- اگر باقیمانده تقسیم $P(x) = x^3 - x - k$ بر $x-2$ برابر ۱ باشد، حاصل $\\lim_{x \\to 3} \\frac{P(x) - 19}{9 - x^2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3071, '56- حاصل $\\lim_{n \\to +\\infty} \\frac{n^{2n+1} - 3^n}{n^{2n-1} - 3^{-n}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 14:30:00', 1, NULL, NULL, 'free'),
(3072, '۱- زاویه ۱ رادیان تقریبا چند درجه و چه کسری از دایره مثلثاتی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3073, '۲- به ازای کدام مقدار $x$ رابطه $tan(x+\\frac{\\pi}{18}) = cot(\\frac{9\\pi}{4}+x)$ برقرار است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3074, '۳- اگر $x-y=3\\pi$ باشد، کدام گزینه صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3075, '۴- تعداد نقاط برخورد نمودار توابع $y=sin(\\pi-x)$ و $y=cos(x-\\frac{\\pi}{2})$ در بازه $[0,3\\pi]$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3076, '۵- اگر $x$ و $y$ دو زاویه حاده باشند و داشته باشیم $sin6x=cos8x$ و $cos12y+cos2y=0$، در این صورت حاصل $tan(x+y-90^\\circ)$ کدام نمی‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3077, '۶- در مثلث قائم‌الزاویه $ABC$ اگر $tanB=\\frac{5}{4}$ باشد، $sinB$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3078, '۷- برای حفظ تعادل یک دکل مخابراتی مطابق شکل از کابل‌هایی استفاده شده است. برای این کار چند متر کابل قابل کار رفته است؟ $(sin35^\\circ=\\frac{\\sqrt{3}}{2})$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3079, '۸- اگر $45^\\circ < \\alpha < 90^\\circ$ باشد، حاصل $\\frac{|sinx-cosx|}{cosx}-|cotx-tanx|$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3080, '۹- با توجه به دایره مثلثاتی مقابل، $tan\\theta+cos\\theta$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3081, '۱۰- در شکل زیر معادله خط $L_1$ به صورت $y=4-mx$ و معادله خط $L_2$ به صورت $y=x\\sqrt{3}+n$ است. سه‌تایی $(m,n,\\alpha)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3082, '۱۱- اگر $tan\\theta<0$ و $sin\\theta-cos\\theta<0$ آنگاه $\\theta$ در کدام ربع مختصاتی قرار دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
