(3138, '69- بیشترین مقدار تابع $f(x)=a-3\\sin\\left(\\frac{\\pi x}{a}\\right)$ سه برابر کمترین مقدار آن است. دوره تناوب کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3139, '70- یکی از جواب‌های معادله $-\\cos(5\\pi+5x)=\\sin(3\\pi-x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3140, '71- تابع $f(x)=3\\cos 2x$ در چند نقطه از بازه $[0,2\\pi]$ ماکزیمم می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3141, '72- اگر $3\\sin^2 x+4\\cos^2 x=\\frac{3}{2}$ باشد، مقدار $\\cos^2 x+\\tan^2 x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3142, '73- در صورتی که $\\tan\\theta(\\tan\\theta+4)=-4$ باشد، $A=\\frac{\\sin\\theta+\\cos\\theta}{\\cos\\theta-\\sin\\theta}$ حاصل چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3143, '74- اگر $\\alpha$ زاویه‌ای باشد که کتانژانت آن با سینوس آن برابر باشد، مقدار $2\\cos^2\\alpha$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3144, '۷۵- در مثلث ABC ضلع AC را به چهار قسمت مساوی و ضلع AB را به دو قسمت مساوی تقسیم‌بندی کرده‌ایم. مساحت چهارضلعی DBCG چند برابر مساحت مثلث DEF است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3145, '۷۶- خلاصه شده عبارت $B=\\frac{1}{\\cos^{4}x}-(\\tan^{2}x+2)^{2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3146, '۷۷- اگر $\\,\\tan^{3}x+3\\tan^{2}x+\\tan x+3=0\\,$ و $\\, (1+\\cos^{2}\\alpha)\\sin x=1 \\,$ باشد، $x$ در کدام ناحیه مثلثاتی قرار دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3147, '۷۸- اگر $f(x)=\\sin(5x-\\frac{\\pi}{6})+2\\cos(x+\\frac{\\pi}{3})$ باشد، $f(\\pi)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3148, '۷۹- شکل مقابل مربوط به تابع $y=\\sin x$ است. مساحت قسمت رنگی چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3149, '۸۰- پنج کمان ایجاد شده در دایره زیر با هم برابرند. اندازه کمان $ACB$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3150, '۸۱- مقدار عددی $\\left[\\frac{\\sin 1}{\\sin 2}\\right]-\\left[-\\frac{\\sin 1}{\\sin 2}\\right]$ کدام است؟ (واحدها رادیان و $[\\,]$ علامت جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3151, '۸۲- دامنه تابع $y=\\frac{1}{\\sqrt{\\cos x-\\sin x}}$ در بازه $(0،3\\pi)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3152, '۸۳- کمترین مقدار تابع $y=\\frac{4}{2+\\sin^2 x}$ چقدر بیشتر از بیشترین مقدار $t=\\frac{1}{4+\\sin^2 x}$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3153, '۸۴- با توجه به دایره مثلثاتی شکل زیر، خط گذرا از دو نقطه $B$ و $C$ محور $x$ها را به چه طولی قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3154, '۸۵- مقدار عددی $A=\\cos(102^\\circ)\\sin(87^\\circ)+\\sin\\frac{7\\pi}{3}\\cos\\frac{13\\pi}{6}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3155, '۸۶- در دایره مثلثاتی زیر مختصات نقطه $B$ به صورت $(\\frac{4}{5}،m)$ است. مقدار $A=m\\tan^2\\alpha+\\cot(\\pi-\\alpha)$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3156, '۸۷- نمودار تابع $f(x)=\\frac{|x|}{x}\\cos x$ در کدام مجموعه نقاط زیر یک‌به‌یک است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3157, '۸۸- اگر بیشترین مقدار تابع $f(x)=\\sqrt{3a+1}+a\\sin\\left(\\frac{ax}{a+1}\\right)$ برابر ۳ باشد، دوره تناوب کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3158, '۸۹- اگر دوره تناوب تابع $f(x)=(\\tan^2 x+\\cot^2 x)^{-1}\\cos 4x$ برابر $8\\pi$ باشد، دوره تناوب $g(x)=\\cos^2(ax)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3159, '۹۰- شکل زیر قسمتی از تابع $f(x)=a+bsin(\\frac{3\\pi}{2}-cx)$ است. حاصل $ab+b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3160, '۹۱- اگر $\\frac{\\pi}{4}<x<\\frac{3\\pi}{4}$ و $tan\\,x=1-m$ باشد، حدود $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3161, '۹۲- یکی از دسته جواب‌های معادله $cos\\,x-sin(\\frac{\\pi}{2}-x)cos^{2}(\\frac{7\\pi}{2}+x)=\\frac{1}{8}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3162, '۹۳- معادله $3sin^{2}x-5sin\\,x=2$ در بازه $[-pi,3\\pi]$ چند جواب دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3163, '۹۴- در صورتی که $\\frac{sin\\,x}{sin\\,x+cos\\,x}=5$ باشد، حاصل $\\sqrt{\\frac{1-cos\\,2x}{1+cos\\,2x}}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 15:09:55', 1, NULL, NULL, 'free'),
(3164, '1- سکه‌ای را به هوا پرتاب می‌کنیم. اگر رو بیاید دو سکه دیگر و اگر پشت بیاید یک تاس را پرتاب می‌کنیم. فضای نمونه‌ای این پیشامد چند عضو دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3165, '2- می‌خواهیم با حروف $a,b,c,d,e,f$ یک کلمه 6 حرفی بدون تکرار حروف بنویسیم. تعداد حالاتی که حرف $a$ قبل از حروف $,e,d$ و نه بلافاصله قبل از آن‌ها آمده است، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3166, '3- با حروف کلمه «خارچی» یک کلمه 5 حرفی بدون تکرار حروف می‌نویسیم. با کدام احتمال حروف اول و آخر نقطه دارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3167, '4-  3 دانش‌آموز رشته ریاضی و 4 دانش‌آموز رشته تجربی در یک صف کنار هم ایستاده‌اند. با کدام احتمال دانش‌آموزان هم رشته کنار هم ایستاده‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3168, '5- سه کتاب ریاضی و سه کتاب فیزیک را در یک قفسه کنار هم می‌چینیم. با کدام احتمال کتاب‌های ریاضی و فیزیک یکی در میان قرار گرفته‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3169, '6- در پرتاب دو تاس احتمال این که مجموع دو تاس بزرگ‌تر از 5 باشد یا هر دو زوج باشند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3170, '7- می‌خواهیم زیرمجموعه‌ای 4 عضوی از مجموعه $\\{a,b,c,d,e,f,g\\}$ انتخاب کنیم. احتمال این که این زیرمجموعه شامل حداقل یکی از دو عضو $a$ یا $b$ باشد و شامل $c$ نباشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3171, '8- تاس را پرتاب می‌کنیم. اگر 4 ظاهر شود برنده‌ایم و اگر 4 ظاهر نشود مجدداً تاس را پرتاب می‌کنیم و به همین ترتیب ادامه می‌دهیم. احتمال این که حداکثر در سه پرتاب برنده شویم، چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3172, '9- در یک کیسه 2 مهره قرمز و  4مهره آبی وجود دارد. یک مهره به تصادف از کیسه خارج می‌کنیم و آن را مشاهده می‌کنیم سپس آن را به کیسه برمی‌گردانیم. اگر این کار را سه بار انجام دهیم با چه احتمالی 2 بار مهره قرمز مشاهده کرده‌ایم؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3173, '10- علی و حسن به همراه 5 نفر از دوستان خود دور یک میز گرد نشسته‌اند. چقدر احتمال دارد علی و حسن کنار هم نباشند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3174, '11- اگر $S=\\{a,b,c,d,e,f\\}$ فضای نمونه‌ای یک آزمایش باشد و $A=\\{a,b,c\\}$ و $B=\\{b,d\\}$ و $C=\\{d\\}$ باشد، چند تا از گزاره‌های زیر درست است؟\n\nالف) A و C ناسازگارند            ب)  B و C مستقل‌اند            پ) A و B مستقل‌اند\n\nت) C و B ناسازگارند            الف)  C و  Aوابسته‌اند            ج) $P(B|C)=1$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3175, '12- علی دو مسابقه پیش رو دارد اگر احتمال پیروزی در مسابقه اول $0.8$ باشد و احتمال برد در مسابقه دوم به شرط پیروزی در مسابقه اول $0.6$ باشد. احتمال این که علی در مسابقه اول پیروز شود و مسابقه دوم را ببازد، چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3176, '13- پنج سکه را پرتاب کرده‌ایم. اگر حداقل دو تای آن‌ها رو ظاهر شده باشد، با کدام احتمال حداقل یکی از سکه‌های دیگر پشت ظاهر می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3177, '14- اگر $P(A|B)=\\frac{1}{3}$ و $P(B-A)=0.2$ و $P(A-B)=0.5$ باشد، $P(A\\cup B)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3178, '15- احتمال قبولی علی در درس‌های ریاضی و ادبیات و شیمی به ترتیب $0.6$ و $0.7$ و $0.8$ است. احتمال قبولی علی حداقل در یکی از این دروس کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3179, '16- کدام گزینه یک افراز روی مجموعه $S=\\{a,b,c,d,e\\}$ درست کرده‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3180, '17- در یک دبیرستان دوره دوم بیست دانش‌آموز سال دوازدهم و سی دانش‌آموز سال یازدهم و پنجاه دانش‌آموز سال دهم حضور دارند. اگر 0.8 دانش‌آموزان سال دوازدهم و 0.7 دانش آموزان سال یازدهم و 0.6 دانش آموزان سال دهم معدل بالای $18$ داشته باشند. با انتخاب یک دانش‌آموز از این مدرسه با چه احتمالی معدل بالای 18 خواهد داشت؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3181, '18- در یک دانشگاه نسبت دانشجویان پسر به دختر برابر $\\frac{2}{3}$ است. اگر $10$ درصد دانشجویان پسر و بیست درصد دانشجویان دختر بیشتر از صد واحد درسی را گذرانده باشند، با انتخاب یک دانشجو به تصادف با چه احتمالی او بیشتر از صد واحد درسی را گذرانده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3182, '19- جعبه A شامل $3$ مهره قرمز و $2$ مهره آبی است و جعبه B شامل $4$ مهره قرمز و $3$ مهره آبی است. یک مهره از ظرف A خارج می‌کنیم و در ظرف B قرار می‌دهیم سپس $2$ مهره از ظرف B خارج می‌کنیم. احتمال این که دو مهره آخر هم‌رنگ باشند، چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3183, '20- $40$ درصد کارکنان یک شرکت را مردان و بقیه را زنان تشکیل داده‌اند. $80$ درصد مردان و $50$ درصد زنان بیمه دارند. یکی از کارکنان این شرکت را انتخاب کرده‌ایم اگر بیمه داشته باشد با چه احتمالی مرد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3184, '21- احتمال بارندگی در $2$ روز اول هفته $0.8$ و در سایر روزهای هفته $0.6$ است. با کدام احتمال در هفته آینده روز بارانی نخواهیم داشت؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3185, '22- در کیسه A، $10$ مهره قرمز و $20$ مهره سفید و در کیسه B، $8$ مهره قرمز و $4$ مهره سفید داریم. از کیسه A، $6$ مهره و از کیسه B  5 مهره به تصادف برمی‌داریم و در کیسه خالی C می‌ریزیم و به تصادف مهره‌ای از کیسه C خارج می‌کنیم. به کدام احتمال مهره خارج شده از کیسه C، قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3186, '23- تعداد دانش‌آموزان تجربی یک دبیرستان 3 برابر تعداد دانش‌آموزان رشته ریاضی همان دبیرستان است. 20 درصد دانش‌آموزان تجربی و 10 درصد دانش‌آموزان ریاضی بیماری دارند. یک دانش‌آموز به تصادف انتخاب می‌شود. با کدام احتمال بیمار است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3187, '24- ظرف A شامل 5 مهره قرمز و 4 مهره آبی و ظرف B شامل 4 مهره قرمز و 1 مهره آبی است. یک مهره از هر ظرف به تصادف خارج می‌کنیم. هرگاه مهره خارج شده قرمز باشد به کدام احتمال از ظرف B خارج شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3188, '25- در یک جعبه 3 مهره سفید و 6 مهره قرمز داریم. به تصادف مهره‌ای از جعبه خارج کرده پس از مشاهده رنگ آن، آن را به جعبه بر می‌گردانیم و مجدداً مهره دیگری خارج می‌کنیم. به کدام احتمال فقط یکبار مهره قرمز خارج شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3189, '26- در یک کلاس n دانش‌آموز ریاضی و 8 دانش‌آموز تجربی داریم. یک دانش‌آموز به تصادف از کلاس خارج می‌کنیم و به جای آن 4 دانش‌آموز از رشته دیگر اضافه می‌کنیم. اگر اکنون یک دانش‌آموز از این کلاس انتخاب کنیم، به احتمال $\\frac{26}{45}$ از رشته تجربی خواهد بود. عدد n کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3190, '27- از میان  10لامپ‌ یک جعبه، 3 تای آن‌ها معیوب است. هرگاه سه لامپ متوالی بدون جایگذاری از جعبه خارج کنیم، با کدام احتمال لااقل به یک لامپ معیوب می‌رسیم؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3191, '28- اگر A و B دو پیشامد ناسازگار با شرط $P(A|B\')=2P(B|A\')=\\frac{1}{2}$ برقرار باشند، مقدار $\\frac{P(A)}{P(B)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3192, '29- یک عدد سه رقمی با تکرار ارقام انتخاب می‌کنیم. اگر بدانیم مضرب 5 است، با کدام احتمال مضرب 3 نمی‌باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3193, '30- در ظرف اول 6 مهره سفید و 3 مهره سیاه و در ظرف دوم 4 مهره سفید و 5 مهره سیاه قرار دارند. یک مهره به دلخواه از ظرف اول به ظرف دوم انتقال می‌دهیم سپس از ظرف دوم دو مهره با هم خارج می‌کنیم. به کدام احتمال لااقل یکی از دو مهره سفید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3194, '31- 4 مرد و 3 زن در یک ردیف کنار هم ایستاده‌اند. اگر بدانیم هیچ دو زنی کنار هم نیستند، به کدام احتمال زنان یک در میان هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3195, '32- احتمال موفقیت رضا در آزمون فیزیک سه برابر احتمال موفقیت او در آزمون شیمی است. او به احتمال $frac{13}{16}$\\ لااقل در یکی از دو آزمون موفقیت داشته است. به کدام احتمال او فقط در شیمی موفقیت داشته است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3196, '33- احتمال قبولی A و B در یک آزمون به ترتیب $frac{1}{2}$\\ و $\\frac{2}{3}$ است. احتمال قبولی لااقل یکی از آن‌ها چند برابر احتمال قبولی دقیقاً یکی از آن‌ها می‌باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:25', 1, NULL, NULL, 'free'),
(3197, '34- هرگاه A و B دو پیشامد مستقل از هم باشند و $P(A-B)=3P(A\\cap B)$، مقدار $P(B|A)$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3198, '35- اگر دو تاس را با هم پرتاب کنیم، تعداد m پیشامد می‌توان تعریف کرد که با پیشامد هر دو زوج ناسازگار باشد. log m کدام است؟($ log2=0.3 $)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3199, '36- هفت نفر به تصادف در یک صف قرار گرفته‌اند. به چه احتمالی دو نفر خاص از آن‌ها، در ردیف اول و دوم صف قرار ندارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3200, '37- در یک خانواده دارای سه فرزند، اگر فرزند اول دختر باشد به احتمال P1 دو فرزند دیگر پسر هستند و اگر یکی از فرزندان دختر باشد، به احتمال P2 دو فرزند دیگر پسر هستند، مقدار $P1x P2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3201, '38- در یک خانواده با دو فرزند، احتمال مبتلای فرزند اول به ویروس کرونا 0.4 و احتمال مبتلای بودن فرزند دوم به ویروس آنفولانزا 0.7 است. به چه احتمالی لااقل یکی از دو فرزند مبتلا هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3202, '39- اگر A و B دو پیشامد از فضای نمونه‌ای و $P(A\') + P(B\') = \\frac{37}{30}$ و  $P(B|A) = \\frac{3}{7}$ و $P(A|B\') = \\frac{2}{3}$ باشد، احتمال آن‌که فقط پیشامد A رخ دهد چند است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3203, '40- 3 تاس را پرتاب می‌کنیم. اگر بدانیم مجموع اعداد رو شده فرد است، به چه احتمالی حداقل روی یکی از تاس‌ها عدد ۱ ظاهر شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3204, '41- در یک کلاس 6 دانشجوی پسر و 4 دانشجوی دختر وجود دارد و یکی از دانشجویان از کلاس خارج می‌شود. اگر از ۹ نفر باقی‌مانده دو نفر را انتخاب کنیم، به چه احتمالی هر دو از آن‌ها دختر هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3205, '42- در یک کیسه 2n+1 مهره آبی و n+2 مهره قرمز وجود دارد، اگر یک مهره از این کیسه خارج کنیم به احتمال $\\frac{5}{12}$ قرمز خواهد بود. 3 مهره پشت سرهم و بدون جایگذاری از این کیسه خارج می‌کنیم، به چه احتمالی فقط مهره دوم آبی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3206, '43- احتمال آن‌که تیم فوتبال استقلال تیم پرسپولیس را شکست دهد برابر $\\frac{2}{3}$ و احتمال قهرمان شدن آن برابر $\\frac{1}{4}$ است و در صورتی که تیم پرسپولیس را شکست دهد به $\\frac{1}{3}$ افزایش خواهد یافت. اگر استقلال قهرمان شود، به کدام احتمال تیم پرسپولیس را شکست داده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3207, '44- در هر یک از 3 طبقه موجود در یک ساختمان، پدر و مادری به همراه 3 و 2 و 1  فرزندشان زندگی می‌کنند. احتمال انتخاب هر طبقه متناسب با تعداد اعضای خانواده‌هاست. یک طبقه را انتخاب کرده و یک نفر را تصادفی بیرون می‌آوریم. به چه احتمالی پدر یک خانواده انتخاب شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3208, '45- احتمال آن‌که فرزند یک خانواده بیماری ارثی داشته باشد $0.4$ و همین احتمال برای فرزند پسر برابر $0.6$ است. مادر فرزند بیماری به دنیا آورده است. به کدام احتمال فرزند پسر بوده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3209, '46- در ظرف A، 4 مهره قرمز و 3 مهره سفید و در ظرف B، 3 مهره قرمز و 4 مهره سفید داریم. تاسی را رها می‌کنیم. اگر مضرب 3 بیاید، مهره‌ای از A در غیر این صورت مهره‌ای از B خارج می‌کنیم. به کدام احتمال مهره خارج شده سفید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3210, '48- در یک دبیرستان، با سه رشته ریاضی، تجربی و انسانی که طرفیت آنها به ترتیب  25 ،15 و 20 نفر می‌باشد. به ترتیب 5، 7 و 9 نفر عینکی هستند. دانش‌آموزی به تصادف از این دبیرستان انتخاب کنیم، اگر بدانیم عینکی است به کدام احتمال رشته انسانی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3211, '50- اگر از کیسه‌ای که مجموعاً شامل 6 مهره آبی و سبز است، 2 مهره پشت سر هم به تصادف و بدون جایگذاری خارج کنیم، به احتمال $\\frac{8}{15}$ همرنگ نخواهند بود. به چه احتمالی مهره اول آبی و مهره دوم سبز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3212, '51- احتمال صعود تیم ملی ایران به دور دوم مسابقات جام جهانی فوتبال برابر $\\frac{1}{5}$ است، ولی اگر رقیب اول را شکست دهد این احتمال به $\\frac{9}{10}$ افزایش پیدا خواهد کرد. اگر احتمال شکست دادن رقیب برابر $\\frac{4}{10}$ باشد، به چه احتمالی این رقیب را شکست می‌دهد ولی صعود نمی‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3213, '52- در یک اتاق 5 آقا و 3 بانو وجود دارد. به تصادف، شخصی را از آن ها انتخاب کرده و پس از مشاهده، آن شخص را با دو شخص هم جنس دیگر با او به اتاق برمی‌گردانیم و مجدداً شخصی را از آن اتاق خارج می‌کنیم. به چه احتمالی فقط یک بانو از اتاق خارج شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3214, '54- سه عدد از اعداد طبیعی1  تا 50 را به تصادف انتخاب می‌کنیم. چقدر احتمال دارد که این اعداد دنباله‌ای هندسی با قدر نسبت بزرگ‌تر از یک تشکیل دهند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3215, '55- احتمال این‌که علی در آزمون ریاضی و آزمون فیزیک قبول شود به ترتیب $\\frac{1}{6}$ و $\\frac{1}{5}$ است. اگر در آزمون ریاضی قبول شود، احتمال قبولی او در آزمون فیزیک دو برابر می‌شود. چقدر احتمال دارد که علی حداقل در یکی از دو آزمون قبول شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3216, '56- همه توابع به صورت $f:A \\to B$ که در آن A={a,b,c} و B={1,2,3,4,5} است را تعریف کرده‌ایم و از میان آن‌ها یکی را به تصادف انتخاب می‌کنیم. چقدر احتمال دارد تابع موردنظر یک‌به‌یک باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3217, '57- در کیسه A، 3 مهره قرمز و 4 مهره آبی و در کیسه B، 5 مهره قرمز و 3 مهره آبی قرار دارد. از کیسه A مهره‌ای به تصادف خارج و در کیسه B می‌اندازیم و سپس مهره‌های کیسه B را متوالیاً و بدون جایگذاری خارج می‌کنیم. چقدر احتمال دارد مهره‌های اول و سوم هم‌رنگ باشند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:14:26', 1, NULL, NULL, 'free'),
(3218, '۱- احتمال انتقال نوعی بیماری در یک خانواده به نوزاد پسر $0.07$ و به نوزاد دختر $0.05$ است. با چه احتمالی نوزاد آن‌ها به این بیماری مبتلا نمی‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3219, '۲- سه ظرف یکسان داریم. در اولین ظرف $14$ مهره قرار دارد که $5$ تای آن‌ها قرمز است. در ظرف دوم همه مهره‌ها قرمزند و در ظرف سوم $7$ مهره قرار دارد که $2$ تای آن‌ها قرمز است. با چشمان بسته ظرفی را انتخاب و از درون آن مهره‌ای خارج می‌کنیم. احتمال قرمز بودن مهره انتخابی چقدر بیشتر از احتمال قرمز نبودن آن است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3220, '۳- بهروز در مسابقه شرکت کرده است که در آن سه بسته سؤال یکی شامل ریاضی، یکی شامل فیزیک و یکی هم شامل زیست‌شناسی وجود دارد. اگر بسته سؤال ریاضی را به او بدهند به احتمال $0.6$ برنده خواهد شد. اگر بسته سوال فیزیک را به او بدهند به احتمال $0.3$ بازنده خواهد شد و اگر بسته سؤال زیست‌شناسی را به او بدهند به احتمال $0.8$ برنده خواهد شد. در صورتی که با چرخاندن عقربه چرخان در شکل نوع سوال مشخص شود، بهروز با چه احتمالی برنده خواهد شد؟ (Oمرکز دایره است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3221, '۴- دو ظرف یکسان داریم. در ظرف اول $10$ مهره آبی و $8$ مهره قرمز و در ظرف دوم $20$ مهره قرمز وجود دارد. از ظرف اول مهره‌ای انتخاب می‌کنیم و در ظرف دوم قرار می‌دهیم، سپس مهره‌ای از ظرف دوم برمی‌داریم. با چه احتمالی این مهره قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3222, '۵- تاسی را پرتاب می‌کنیم. اگر عدد کمتر از $3$ رو شد، از درون جعبه‌ای که شامل $4$ لامپ معیوب و $2$ لامپ سالم است لامپی را انتخاب می‌کنیم و اگر عدد تاس بیشتر از $2$ رو شد، از درون جعبه‌ای که شامل $3$ لامپ معیوب و $3$ لامپ سالم است لامپی را انتخاب می‌کنیم. با چه احتمالی لامپ انتخابی معیوب است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3223, '۶- یک سکه را پرتاب می‌کنیم. اگر رو بیاید دو سکه دیگر پرتاب می‌کنیم. در این آزمایش احتمال اینکه دقیقاً یک سکه پشت ظاهر شود چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(3224, '۷- مدرسه A چهار برابر مدرسه B دانش‌آموز دارد.$25$ درصد از دانش‌آموزان مدرسه A و $80$ درصد از دانش‌آموزان مدرسه B در رشته تجربی تحصیل می‌کنند. اگر همه دانش‌آموزان دو مدرسه در یک محوطه جمع شوند و به تصادف یکی از آن‌ها را انتخاب کنیم، با چه احتمالی رشته این دانش‌آموز تجربی نیست؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3225, '۸- درون جعبه A سه مهره سفید و دو مهره قرمز و درون جعبه B دو مهره سفید و دو مهره قرمز قرار دارد. اگر احتمال انتخاب جعبه A برابر با $P(A)$ و احتمال انتخاب جعبه B برابر با $P(B)$ باشد، رابطه $P(A)=3P(B)$2 برقرار است. به تصادف یکی از دو جعبه را انتخاب و از آن یک مهره انتخاب می‌کنیم، با چه احتمالی آن مهره سفید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3226, '۹- درون کیسه‌ای $n$ مهره سفید و $n$ مهره قرمز وجود دارد. مهره‌ای به تصادف انتخاب می‌کنیم و بدون نگاه کردن به رنگ آن، آن را کنار می‌گذاریم. سپس مهره دیگری به تصادف انتخاب می‌کنیم. با چه احتمالی مهره دوم قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3227, '۱۰- درون کیسه‌ای $4$ مهره آبی و $5$ مهره قرمز قرار دارد. مهره‌ای به تصادف انتخاب می‌کنیم. آن مهره را همراه یک مهره هم‌رنگ خودش به کیسه برمی‌گردانیم. سپس دوباره به تصادف مهره‌ای انتخاب می‌کنیم. با چه احتمالی مهره جدید قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3228, '۱۱- در ظرفی دو مهره آبی و سه مهره قرمز وجود دارد دو تاس پرتاب می‌کنیم. اگر مجموع دو تاس $8$ باشد، دو مهره از ظرف انتخاب می‌کنیم. در غیر این صورت سه مهره از ظرف انتخاب می‌کنیم. با چه احتمالی مهره‌های انتخابی هم‌رنگ‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3229, '۱۲- درون ظرف اول $2$ سیب و $2$ گلابی و در ظرف دوم $3$ سیب و یک گلابی قرار دارد. تاسی را پرتاب می‌کنیم؛ اگر زوج آمد یک میوه از ظرف اول را به ظرف دوم منتقل می‌کنیم، اگر فرد آمد یک میوه از ظرف دوم برمی‌داریم و به ظرف اول منتقل می‌کنیم. اکنون ظرفی با میوه بیشتر را انتخاب و از آن میوه‌ای خارج می‌کنیم. با چه احتمالی این میوه سیب است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3230, '۱۳- سه ظرف داریم. در ظرف اول $6$ مهره آبی و در ظرف دوم $6$ مهره قرمز و در ظرف سوم $2$ مهره آبی و $4$ مهره قرمز قرار دارد. به تصادف از یک ظرف سه مهره انتخاب می‌کنیم. با چه احتمالی $2$ مهره قرمز و یک مهره آبی انتخاب کرده‌ایم؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3231, '۱۴- $60$ درصد دانشجویان سال اول دختر و بقیه پسر هستند $60$ درصد دختران و $50$ درصد پسران تمام واحدهای درسی خود را پاس کرده‌اند، چند درصد دانشجویان کل واحدهای درسی خود را پاس کرده‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3232, '۱۵- احتمال انتقال ویروس کرونا به افراد واکسن زده $0.02$ و به افراد دیگر $0.4$ است. $\\frac{3}{5}$کارمندان یک شرکت واکسن زده‌اند. اگر فرد حامل ویروس کرونا با یکی از کارمندان ملاقات کند با چه احتمالی این بیماری منتقل می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3233, '۱۶- اگر یک تاس را بیندازیم و پیشامدهای «رو شدن عدد بزرگتر از $5$»، «رو شدن عدد کوچکتر از $3$» و «رو شدن عدد $4$ یا $5$» را به ترتیب $A$، $B$ و $C$ بنامیم، کدام دو پیشامد ناسازگارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3234, '۱۷- درون جعبه‌ای $3$ مهره آبی و $4$ مهره قرمز قرار دارد. از این جعبه سه مهره انتخاب می‌کنیم. با چه احتمالی مهره‌های قرمز بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3235, '18- در پرتاب یک تاس و $n$ سکه، تعداد اعضای فضای نمونه 48 است. در پرتاب $n+1$ سکه، فضای نمونه چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3236, '19- دو تاس را پرتاب می‌کنیم با چه احتمالی مجموع اعداد رو شده مضرب 3 است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3237, '20- اگر 6 نفر که دو نفر آن‌ها برادرند کنار هم در یک ردیف قرار بگیرند، چقدر احتمال دارد که دو برادر در دو انتهای ردیف قرار گیرند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3238, '- خانواده‌ای چهار فرزند دارد. چقدر احتمال دارد که تعداد دخترها و پسرها با هم برابر باشند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3239, '22- اگر $A$ و $B$ دو پیشامد ناسازگار و $P(A \\cup B) = 3P(B)$ باشد، $\\frac{P(B)}{P(A)}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3240, '23- با جایگشت ارقام عدد 32485 اعداد 5 رقمی نوشته‌ایم. یکی از آن‌ها را به تصادف انتخاب می‌کنیم. با چه احتمالی آن عدد فرد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3241, '24- اگر $a, b \\in \\{1, 2, 3, 4\\}$ باشد و معادله $ax^2 + bx + 4 = 0$ ریشه حقیقی نداشته باشد، با چه احتمالی دلتای معادله بیشتر از -16 است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3242, '25- در پرتاب دو تاس، اگر $A$ پیشامد هر دو تاس اعداد برابر و $B$ پیشامد هر دو تاس اعداد اول باشد، پیشامدی که $A$ رخ دهد و $B$ رخ ندهد، چند عضو دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3243, '26- دو تاس را با هم پرتاب می‌کنیم با چه احتمالی هر دو تاس عدد اول می‌آید؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3244, '27- احتمال قهرمانی تیم فوتبال ایران در آسیا 0.4 و احتمال قهرمانی تیم بسکتبال ایران در آسیا 0.7 است. با چه احتمالی حداقل یکی از تیم‌ها قهرمان می‌شوند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3245, '28- سکه‌ای را آنقدر پرتاب می‌کنیم تا «رو» بیاید. با چه احتمالی این اتفاق در چهارمین پرتاب رخ می‌دهد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3246, '29- احتمال قبول شدن سارینا در درس ریاضی دو برابر احتمال قبول شدن ساینا در درس ریاضی است. اگر با احتمال 0.88 حداقل یکی از این دو نفر در درس ریاضی قبول شوند، با چه احتمالی سارینا در درس ریاضی قبول می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3247, '30- دو تاس را می‌ریزیم. اگر حداقل عدد یک تاس زوج نباشد، با کدام احتمال جمع دو عدد رو شده مضرب 3 است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3248, '31- درون کیسه‌ای سه مهره آبی و چهار مهره قرمز قرار دارد. مهره‌ای را انتخاب می‌کنیم و به همراه آن یک مهره همرنگ به کیسه برمی‌گردانیم. سپس مهره دیگری را انتخاب می‌کنیم. با چه احتمالی این مهره آبی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3249, '32- درون دو جعبه به ترتیب 30 و 20 عدد لامپ یکسان قرار دارد. در جعبه اول 4 لامپ معیوب و در جعبه دوم 5 لامپ معیوب وجود دارد. از جعبه اول 10 لامپ و از جعبه دوم 12 لامپ را انتخاب می‌کنیم و در جعبه جدیدی قرار می‌دهیم. سپس از این جعبه لامپی را انتخاب می‌کنیم. با چه احتمالی این لامپ معیوب است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3250, '33- درون کیسه‌ای سه مهره آبی و چهار مهره زرد قرار دارد. مهره‌ای را انتخاب می‌کنیم و مهره‌ای انتخابی را به همراه دو مهره همرنگ خود درون کیسه برمی‌گردانیم و مهره دیگری را انتخاب می‌کنیم. با چه احتمالی این مهره زرد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3251, '34- درون جعبه A، 10 پرتقال وجود دارد که دوتای آن‌ها خراب است و درون جعبه B، 20 پرتقال قرار دارد که 4 تای آن‌ها خراب است. یکی از جعبه‌ها را به تصادف انتخاب و از آن یک پرتقال انتخاب می‌کنیم. با چه احتمالی پرتقال انتخابی خراب است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3252, '35- سه مهره از کیسه A شامل 5 مهره آبی و 5 مهره قرمز، و دو مهره از کیسه B که شامل 5 مهره قرمز است بیرون می‌آوریم و در کیسه C قرار می‌دهیم. حال از کیسه C مهره‌ای به تصادف انتخاب می‌کنیم. با چه احتمالی این مهره قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3253, '36- در جعبه A، 4 مهره قرار دارد که یکی از آن‌ها قرمز است. در جعبه B، 5 مهره قرار دارد که دوتای آن‌ها قرمز است. جعبه‌ای را انتخاب و از درون آن مهره‌ای را انتخاب می‌کنیم. اگر مهره انتخابی قرمز باشد، با چه احتمالی از جعبه B بوده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3254, '37- جمعیت کشور ایران در سال 1401، هشتاد و پنج میلیون نفر بوده است که 43 میلیون نفر آن‌ها زن بودند و الباقی آن را مردان تشکیل می‌دهند. اگر 90درصد زنان و 80 درصد مردان در اثر تورم سالانه متضرر شده باشند، با چه احتمالی فرد انتخابی از کل کشور در اثر تورم متضرر شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3255, '38- سه ظرف یکسان داریم. درون ظرف اولی سه مهره قرمز و 2 مهره آبی، درون دومی 4 مهره قرمز و یک مهره آبی و درون سومی 5 مهره قرمز وجود دارد. احتمال انتخاب هر ظرف متناسب با تعداد مهره‌های درون آن است. ظرفی را انتخاب و از آن مهره‌ای بیرون می‌کشیم. با چه احتمالی این مهره آبی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3256, '39- احتمال تولد فرزند دختر در یک خانواده دو برابر احتمال تولد فرزند پسر است و همچنین احتمال انتقال نوعی بیماری ارثی به فرزند پسر 0.2 و به فرزند دختر 0.1 است. در این خانواده فرزندی متولد می‌شود. با چه احتمالی این فرزند به بیماری مبتلا است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3257, '40- در ظرف A چهار مهره آبی و چهار مهره قرمز و در ظرف B سه مهره قرمز و تعدادی مهره آبی وجود دارد. یکی از ظرف‌ها را به تصادف انتخاب و از آن مهره‌ای بیرون می‌کشیم. اگر احتمال قرمز بودن آن $\\frac{1}{2}$ باشد، تعداد مهره‌های ظرف B چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3258, '۴۱- یک سکه را پرتاب می‌کنیم؛ اگر رو بیاید، دو تاس و اگر پشت بیاید، سه تاس پرتاب می‌کنیم. با چه احتمالی مجموع اعداد رو شده در تاس‌ها کمتر از $5$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3259, '۴۲- در ظرفی 20 مهره سفید و 30 مهره سیاه قرار دارد. یک مهره انتخاب می‌کنیم و بدون نگاه کردن به رنگ آن، آن را کنار می‌گذاریم. حال مهره دیگری انتخاب می‌کنیم. با چه احتمالی آن مهره سفید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3260, '43- $60$ درصد جمعیت یک روستا مرد و $40$ درصد زن هستند. $30$ درصد زنان و $70$ درصد مردان باسوادند. اگر یکی از افراد روستا را انتخاب کنیم، با چه احتمالی باسواد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3261, '۴۴- تاسی را آنقدر پرتاب می‌کنیم تا عدد زوج ظاهر شود. با چه احتمالی حداکثر در پرتاب چهارم نتیجه حاصل می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3262, '۴۵- در ظرف اول سه مهره آبی و در ظرف دوم چهار مهره قرمز و یک مهره آبی وجود دارد. تاسی را پرتاب می‌کنیم؛ اگر عدد اول آمد از ظرف اول و اگر عدد اول نیامد از ظرف دوم مهره‌ای انتخاب می‌کنیم. با چه احتمالی آن مهره آبی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3263, '۴۶- شاهین در یک مسابقه شرکت کرده است. اگر سؤالات ریاضی انتخاب شود با احتمال $0.8$ و اگر فیزیک انتخاب شود با احتمال $0.6$ و اگر زیست انتخاب شود با احتمال $0.5$ برنده خواهد شد. نوع سؤالات شاهین به چرخاندن عقربه شکل زیر انتخاب می‌شود. با چه احتمالی شاهین در مسابقه برنده می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3264, '۴۷- تاسی را پرتاب می‌کنیم. اگر 1 بیاید، دو سکه و اگر 3 و 5 بیاید یک سکه و اگر زوج بیاید، یک تاس دیگر پرتاب می‌کنیم. با چه احتمالی حداقل یک بار سکه رو می‌آید؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3265, '۴۸- با ارقام عدد ۱۲۳۴۵، اعداد پنج رقمی ساخته‌ایم؛ یکی از آن‌ها را انتخاب می‌کنیم. با چه احتمالی ارقام یکی در میان زوج و فرد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3266, '۴۹- در پرتاب دو تاس، احتمال رو شدن دو عدد فرد چند برابر احتمال رو شدن حداقل یک عدد فرد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3267, '۵۰- از بین اعداد دورقمی طبیعی، یک عدد انتخاب می‌کنیم. با چه احتمالی این عدد بر $3$ بخش‌پذیر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3268, '۵۱- خانواده‌ای دو فرزند دارد. با چه احتمالی فرزندان غیرهم‌جنس‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3269, '۵۲- با حروف کلمه descartes کلمات $9$ حرفی می‌سازیم. با چه احتمالی دو حرف s کنار هم قرار می‌گیرند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3270, '۵۳- سام و سپهر به همراه چهار دوست دیگرشان به ترتیب وارد یک اتاق می‌شوند. با چه احتمالی سام و سپهر پشت سر هم وارد اتاق می‌شوند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3271, '۵۴- درون کیسه‌ای $3$ مهره آبی و $4$ مهره قرمز وجود دارد .دو مهره همزمان انتخاب می‌کنیم. با چه احتمالی هر دو مهره همرنگ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3272, '۵۵- با ارقام مجموعه $A=\\{3,4,5,6,7,8}\\$ اعداد چهاررقمی بدون تکرار ارقام می‌سازیم. یکی از آن‌ها را انتخاب می‌کنیم. با چه احتمالی در این عدد حداقل دو رقم زوج وجود دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3273, '۵۶- عددی سه‌رقمی با ارقام زوج طبیعی بدون تکرار ساخته‌ایم احتمال آنکه عدد ساخته شده کمتر از $312$ باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3274, '۵۷- دو تاس را پرتاب می‌کنیم. با چه احتمالی رقم تاس اول بزرگ‌تر از رقم تاس دوم نیست؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3275, '۵۸- اگر $a,b \\in \\{1,2,3,4,5\\}$ و معادله درجه دوم $ax^2+bx+1=0$ ریشه حقیقی داشته باشد، با کدام احتمال $a=b$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3276, '۵۹- دو پیشامد $A$ و $B$ مستقل‌اند. اگر $P(A\\cap B)=\\frac{1}{6}$ و $P(A\\cap B\')=\\frac{5}{6}$ باشد، $P(A)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3277, '۶۰- خانواده‌ای چهار فرزند دارد. احتمال آنکه فرزند چهارم دختر باشد چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3278, '۶۱- خانواده‌ای دارای سه فرزند است. اگر یکی از فرزندان دختر باشد، با چه احتمالی این خانواده فرزند پسر ندارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3279, '۶۲- اگر $2(p(A))^2+2(P(B))^2=5P(A)P(B)$ باشد، مقدار $\\frac{P(A|B)}{P(B|A)}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3280, '۶۳- درون کیسه‌ای $5$ مهره قرمز و $6$ مهره آبی وجود دارد. به صورت متوالی سه مهره و بدون جایگذاری انتخاب می‌کنیم. با چه احتمالی هر سه مهره قرمزند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3281, '۶۴- درون جعبه‌ای $4$ گوی آبی و $5$ گوی قرمز وجود دارد. دو گوی متوالی و بدون جایگذاری انتخاب می‌کنیم. با چه احتمالی گوی اول آبی و گوی دوم قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3282, '۶۵- درون کیسه‌ای $4$ مهره آبی و $10$ مهره قرمز قرار دارد. یک مهره انتخاب می‌کنیم و پس از مشاهده رنگ آن، $3$ مهره مخالف رنگ آن به کیسه برمی‌گردانیم. سپس یک مهره انتخاب می‌کنیم. با چه احتمالی این مهره قرمز است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3283, '۶۶- مینا و سحر در یک مسابقه تنیس با هم مسابقه می‌دهند. احتمال برد مینا در بازی اول $\\frac{4}{5}$ است. اگر مینا بازی اول را ببرد، احتمال برد او در بازی دوم $\\frac{5}{6}$ خواهد بود و اگر مینا اولین بازی را ببازد، احتمال برد او در بازی دوم $\\frac{2}{3}$ است. در صورتی که مینا حداقل یکی از دو بازی را ببرد با چه احتمالی هر دو بازی را می‌برد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3284, '۶۷- در ظرف $A$ تعداد $2$ مهره سفید و $3$ مهره سیاه و در ظرف $B$ تعداد $3$ مهره سفید و $2$ مهره سیاه و در ظرف $C$ تعداد $3$ مهره سفید و $1$ مهره سیاه وجود دارد. 4 مهره از ظرف $A$ و 2 مهره از ظرف $B$ برداشته و داخل ظرف C قرار می‌دهیم و سپس یک مهره از ظرف $C$ خارج می‌کنیم. به چه احتمالی این مهره سفید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:23:36', 1, NULL, NULL, 'free'),
(3285, '۱- بین نقاط مشخص‌شده در شکل روبه‌رو، کدام نقطه مشتق بزرگ‌تری دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3286, '۲- اگر دربارهٔ تابع پیوسته f بدانیم $\\lim_{h\\to0}\\frac{f(x+h)-f(x)}{h}=-4$، معادلهٔ خط مماس بر نمودار تابع f در نقطه‌ای با طول ۳ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3287, '۳- دربارهٔ تابع f می‌دانیم $f\'(2)=f(2)=2$، حاصل $\\lim_{x\\to2}\\frac{x^3(x)-2x}{x-2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3288, '۴- اگر f تابعی با تعریف $f(x)=\\sqrt{x}-\\sqrt{x-3}$ باشد، حاصل $f\'(-6)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3289, '۵- تابع در نقطهٔ $x=1$ پیوسته است، اما مشتق‌پذیر نیست. نماد جزء صحیح است [ ]، kدام تابع می‌تواند این ویژگی را داشته باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3290, '۶- مشتق تابع $y=(x^3+\\Delta x)^3$ در نقطه‌ای به طول ۴ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3291, '۷- اگر n عددی طبیعی باشد، حاصل $\\lim_{x\\to+\\infty}\\frac{x^n-1}{x^n+x-1}$ برابر کدام‌یک از گزینه‌های زیر نمی‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3292, '۸- اگر $f(x)=x^{2\\Delta x^3}+y^x+yx$، حاصل $\\lim_{x\\to+\\infty}\\frac{f(x)+f(-x)}{f(x)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3293, '۹- حاصل $\\lim_{x\\to-\\infty}\\frac{1/x+2/x^2}{x+1/x}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3294, '۱۰- اگر $f(x)=\\sqrt{x}+x+\\frac{1}{x}-x^3$، حاصل $\\lim_{x\\to+\\infty}f(x)$ و $\\lim_{x\\to-\\infty}f(x)$ به‌ترتیب کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3295, '۱۱- اگر g و f دو تابع مشتق‌پذیر باشند به‌گونه‌ای که $f(2)=g(2)=2$ و $f\'(2)=-3$ و $g\'(2)=2$، مقدار $\\left(\\frac{f}{g}\\right)\'(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3296, '۱۲- اگر $f(x)=\\frac{x^2+x+۲}{\\sqrt{x}-x}$، مقدار $\\lim_{x\\to1}\\frac{f(x)+f\'(x)}{x-1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3297, '۱۳- مقدار مشتق تابع $f(x)=(x^4-Δx+۴)$ در نقطه‌ای به‌طول ۴ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3298, '۱۴- اگر $f(x)=[x-۵]\\times[x-۵]$، مقدار $f\'\'(۵)$ کدام است؟ (نماد [ ] جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3299, '۱۵- تابع $f(x)=|x+۳|\\times|x-۳|$ در نقطه‌ای به طول a مشتق‌ناپذیر است. مقدار $f\'_+(a)-f\'_-(a)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3300, '۱۶- اگر $f(x)=\\frac{x^2+y^3-\\sqrt{x}}{yx^3+\\Delta x-1}$، حاصل $\\lim_{x\\to+\\infty}f\'(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3301, '۱۷- مطابق شکل زیر، خط ℓ با معادله y = 2x + b بر هر دو تابع f و g مماس است. مقدار k کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3302, '۱۸- اگر\\[f(x)=\\frac{x^5}{10}+\\frac{x^4}{6}+\\frac{x^3}{3}+\\frac{x^2}{2}+\\frac{x}{4}\n\n\\]\n\nآنگاه مقدار \\(f\'\'(2)\\) کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3303, '۱۹- نمودار تابع f در شکل زیر رسم شده است. به‌ازای چند مقدار متمایز از a، حد\n\n\\[\\lim_{x\\to a}\\frac{f(x)-f(a)}{x-a}\\]وجود ندارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3304, '۲۰- آهنگ تغییر متوسط تابع $f(x)=\\sqrt{x}$ در بازهٔ $[1,27]$ از آهنگ لحظه‌ای تغییر تابع در نقطه‌ای به طول ۸ چقدر کمتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3305, '۲۱- متحرکی روی خط حرکت می‌کند که فاصلهٔ آن از مبدأ از رابطه\\[S(t)=-3t^2+8t\\]به‌دست می‌آید. در کدام لحظه، سرعت لحظه‌ای این متحرک مساوی سرعت متوسط آن روی بازه \\([0,10]\\) است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3306, '۲۲- اگر \\(f(x)=\\sqrt[3]{(x^2-1)^3}\\)، حاصل \\(f\'(-2)\\) کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3307, '۲۵- اگر $f(x)=|x(x-[x])|$ آنگاه حاصل $f\'_+(-7)$ کدام است؟ ( [ ] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3308, '۲۶- معادله نیم‌مماس چپ تابع $y=|x^2-4x|+2x$ در نقطه‌ای با طول $4$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3309, '۲۷- اگر $f(x)=\\frac{x^2-1}{2x-5}$ و $g(x)=f(x-\\sqrt{x-1})$ حاصل $g\'(5)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3310, '۲۸- خط $y=15-4x$ بر نمودار تابع $f$ در نقطه‌ای با طول $3$ مماس است. مقدار $(f\\circ f)\'(3)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3311, '۲۹- تابع مشتق تابع $f$ با ضابطهٔ $f(x)=(x^{۲}+۲x+۴)(x^{۲}−۲x+۴)(x^{۲}−۴)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3312, '۳۰- تابع $f$ با ضابطهٔ زیر روی مجموعهٔ اعداد حقیقی مشتق‌پذیر است. مقدار $b$ کدام است؟\n\n$$f(x)=\\begin{cases}\\dfrac{a}{1-x} & x>۲\\\\b+۷ & x=۲\\\\\\sqrt{-۲x+c} & x<۲\\end{cases}$$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3313, '31- اگر $f(x)=\\begin{cases}2x+1 & x\\ge1 \\\\ 3x-2 & x<1\\end{cases}$ و $g(x)=\\begin{cases}x^2-3x+1 & x\\ge1 \\\\ x^2 & x<1\\end{cases}$، مقدار $(g \\circ f)\'(1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3314, '۳۲- برای تابع $f$ در شکل روبه‌رو داریم: $f\'(3)=-2$ و $f(3)=5$. اگر خط $d$ در نقطه $A$ بر $f$ مماس باشد، عرض نقطه $B$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3315, '۳۳- در شکل روبه‌رو نمودار تابع $f$ رسم شده است. اگر شیب نمودار در نقطه $A$ را $m_1$، شیب نمودار در نقطه $B$ را $m_2$ و شیب خط $AB$ را $m_3$ بنامیم، کدام گزینه درست است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3316, '۳۴- اگر $ \\lim_{x \\to 2} \\frac{f(x)-f(2)}{x-2} = g(x) = f\'(x) + x - 1 $، مشتق تابع $g$ در نقطه‌ی $x=2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3317, '۳۵- در مورد تابع مشتق‌پذیر $f$ می‌دانیم $ \\lim_{x \\to 3} \\frac{f(x)+5}{x-3} = -۲ $. معادله‌ی خط مماس بر نمودار تابع $f$ در نقطه‌ای به طول ۳ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3318, '۳6- در کدام نقطه از تابع $y = \\frac{1}{2x + 1}$، خط مماس بر خط $y = 2x + 5$ عمود است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3319, '۳7- با توجه به نمودار تابع $f$ و خط مماس بر $f$ در $x = -1$، مقدار $\\lim_{h \\to 0} \\frac{f(-1 - 2h) - f(-1)}{h}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3320, '۳8- اگر $f(x) = \\frac{x - 1}{x + 2}$، حاصل $\\lim_{h \\to 0} \\frac{f(2 + h) - f(2)}{3h}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3321, '۳۹- به ازای کدام مقادیر $a$ و $b$ تابع $f(x) = \\begin{cases} 2ax^2 - bx & x \\le 2 \\\\ bx - 8 & x > 2 \\end{cases}$ در $x = 2$ مشتق‌پذیر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3322, '40-  در شکل داده‌شده، نمودار تابع $f$ و خط $d$ مماس بر این تابع در نقطه‌ای به طول ۴ رسم شده است. اگر $f(4) = 5$ و $f(1) = 2$ باشد، آنگاه مقدار $f\'(4)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:37', 1, NULL, NULL, 'free'),
(3323, '۴۱- اگر $f(x) = \\frac{x^2}{2x + y}$ آنگاه $f\'(1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3324, '۴۲- اگر $f(x) = |x - \\lfloor x + 1 \\rfloor|$ حاصل $\\lim_{h \\to 0^-} \\frac{f(1 + h) - f(1)}{h}$ کدام است؟ $\\lfloor \\ \\rfloor$) نماد جزء صحیح است', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3325, '۴3- در تابع یا ضابطه $f(x) = x|x - f|$ حاصل $f\'_+(2) - f\'_-(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3326, '۴۴-  در شکل روبه‌رو نمودار تابع $f(x) = \\frac{7x + 1}{x - 1}$ و خط مماس بر آن در نقطه‌ی $A$ به طول ۸ رسم شده است. اگر $f\'(2) = -3$، طول پاره‌خط BC کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3327, '۴۵-  تابع در $x=2$ مشتق‌پذیر است. اگر $\\lim_{h \\to 0} \\frac{f^2(2-h)-8}{h}=12$ باشد، مقدار مشتق تابع $y = x f(\\frac{6}{x})$ در $x=3$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3328, '۴۶- - تابع $y=\\begin{cases} ax^3+bx+x^2-1 & x \\le 1 \\\\ bx^2+4x^2-3 & x>1 \\end{cases}$ در $R$ مشتق‌پذیر است. حاصل $a+b^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3329, '۴۸- در نقاط $A$ و $B$ واقع بر منحنی $y=\\frac{x+3}{x-2}$ دو مماس رسم می‌کنیم. اگر خطوط مماس بر خط $x-5y+1=0$ عمود باشند، فاصله بین دو نقطه $A$ و $B$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3330, '۵۰- گنجایش ظرفی ۵۰ لیتر مایع است. در لحظه $t=0$ سوراخی در ظرف ایجاد می‌شود. اگر حجم باقی‌مانده در ظرف پس از $t$ ثانیه از رابطه $V = 50(1 - \\frac{t^2}{8})$ باشد، نصف آهنگ تغییر متوسط حجممخططیر لحضهای آن در بازه $[0, \\sqrt{8}]$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3331, '۵۱- نمودار تابع $f(x) = y$ به صورت روبه‌رو است. آنگاه طول پاره‌خط $AB$ چند برابر عرض نقطه‌ی $A$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3332, '۵۲- مشتق تابع $f(x) = x \\sqrt{\\frac{3x-1}{x-2}}$ در نقطه $x=3$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3333, '۵۳- اگر نمودار دو تابع $f$ و $g$ به صورت روبه‌رو باشد و $h(x) = (\\frac{f}{g})(x)$، آنگاه $h\'(1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3334, '۵۴-  برای تابع $f(x) = \\begin{cases} \\frac{3x^2-2x+1}{x-2} & x \\ge 1 \\\\ \\frac{2x+1}{x-2} & x < 1 \\end{cases}$ ، حاصل $A = \\lim_{h \\to 0} \\frac{f(1-h^2)-f(1+h^2)}{h^2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3335, '۵۵ - اگر خط $2y+3x=4$ در نقطه $x=-2$ بر تابع $y=f(x^2-x)$ مماس باشد، عرض از مبدأ خط مماس بر تابع $y=f(x)$ در نقطه $x=6$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3336, '۵6 - اگر $f(x)=\\frac{x^4}{6}-3x^2+5x$ آنگاه حاصل $f\'\'(-3)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3337, '۵۷-  اگر $f(x)=\\frac{1}{\\sqrt{1-3x}}$، آهنگ تغییر متوسط تابع $f$ در بازه $[-4,0]$ از آهنگ تغییر لحظه‌ای تابع در $x=-4$ چقدر بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3338, '۵۸- اگر $f(x)$ تابعی پیوسته باشد و $\\lim_{x \\to 2} \\frac{f(x)-7}{x^2-4}=3$، مشتق تابع $y=x f(\\frac{1}{x})$ در نقطه $x=\\frac{1}{2}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3339, '۵۹-  خودرویی در امتداد خط راست طبق معادله $s(t)=-8t^2+mt$ حرکت می‌کند که در آن $0 \\le t \\le 6$ بر حسب ثانیه است. اگر سرعت متوسط خودرو در بازه $[3,6]$ برابر 10 باشد، سرعت لحظه‌ای خودرو در $t=5$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 17:53:38', 1, NULL, NULL, 'free'),
(3340, 'معادله $x^2+ax-b=0$ را به روش مربع کامل حل کرده‌ایم، در یک مرحله عبارت $(x-1)^2=5$ به دست آمده است، مقدار $a+b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3341, 'اگر $\\alpha$ ریشۀ معادلۀ $3=2x^2-x$ باشد، حاصل $A=(2\\alpha^2-\\alpha-3)^{1401}+(\\frac{2\\alpha^2}{\\alpha+3})^{2021}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3342, 'اگر معادلۀ $mx^2+mx+m-3=0$ ریشۀ مکرر مرتبه دوم داشته باشد، مقدار m کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3343, 'اگر مجموع مربعات سه عدد طبیعی متوالی دو برابر مربع بزرگ‌ترین آن‌ها باشد، عدد کوچک‌تر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3344, 'مقدار ماکزیمم تابع $y=(1+k)x^2-4x+k$ برابر 1- است، k کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3345, 'اگر جواب نامعادلۀ $|x^2-4x|<x$ به صورت $(a,b)$ باشد، وسط بازه کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3346, 'سهمی $y=-x^2+mx+m$ فقط از دو ناحیه مختصات می‌گذرد و برخوردی با محور xها ندارد، حدود m کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3347, 'اگر مجموعه جواب معادلۀ $x^2-x-1=0$ به صورت $\\{\\alpha,\\beta\\}$ باشد، مجموعه جواب کدام معادله $\\{\\alpha^2+\\beta^2, \\alpha^2\\beta^2\\}$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3348, 'اگر $\\alpha$ و $\\beta$ ریشه‌های معادلۀ $x+2=2x^2$ باشد، حاصل $|\\beta^3-\\alpha^3|$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3349, 'شکل زیر مربوط به تابع $y=-x^2+4x+5$ است. مساحت ذوزنقۀ ABCO چقدر است؟ (خط L موازی محور xهاست)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3350, 'اگر مساحت مثلث ABC و مستطیل DEFG هر دو ماکزیمم شود، مقدار m کدام است؟ (اطلاعات شکل: ارتفاع مثلث $x$ و قاعده $8-x$؛ ابعاد مستطیل $2x-m$ و $\\frac{m}{2}$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3351, 'اگر سهمی $y_1=mx^2+x+m-1$ محور xها را در دو طرف محور yها قطع کند، آن‌گاه در مورد سهمی $y_2=x^2-4x+m-1$ کدام جمله صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3352, 'اگر $\\alpha$ و $\\beta$ ریشه‌های حقیقی و متمایز معادلۀ $x^2+(m-1)x+1=0$ و رابطۀ $\\alpha^3\\beta+\\alpha\\beta^3>-2$ بین آن‌ها برقرار باشد، حدود m کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3353, 'حاصل‌ضرب ریشه‌های معادلۀ $x^2(x^2+2x+1)-14x^2-14x+24=0$ از مجموع ریشه‌های آن چقدر بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3354, 'با توجه به چندجمله‌ای درجه دوم $P(x)=ax^2+bx+c$ $(a \\neq 0, a,b,c \\in \\mathbb{R})$، برای حل معادلۀ $P(x)=0$ به شیوهٔ مربع کامل، $P(x)$ را به شکل $P(x)=a[(x+\\frac{b}{2a})^2+\\square]$ می‌نویسیم. $\\square$ در کدام گزینه به درستی نشان داده شده است؟ ($\\Delta=b^2-4ac$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3355, 'مجموعه جواب کدام نامعادله بر روی محور زیر نمایش داده شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3356, 'سهمی f را k واحد به سمت راست و $k^2$ واحد به بالا انتقال می‌دهیم و تابع g به دست می‌آید. اگر $g(4)=19$ باشد، مقدار k کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3357, 'اگر بزرگ‌ترین مجموعه جواب نامعادلۀ $\\frac{(x^2+3x+1)(x^2+3x+5)}{-2x^2+3x-4} > 0$، برابر $(a,b)$ باشد، مقدار ab کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3358, 'در معادلۀ درجه‌دوم $3x^2-8x-1=0$، نسبت مجموع ریشه‌ها به حاصل‌ضرب ریشه‌ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3359, 'نمودار تابع خطی f و سهمی g در شکل زیر رسم شده است. حاصل $f(-1)$ کدام است؟ (S رأس سهمی است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3360, '۲۱ - اگر جدول تعیین علامت عبارت $f(x)=(x+2)(2x^2+ax+b)$ به صورت زیر باشد، آن‌گاه $\\frac{a+b}{2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3361, '۲۲ - فاصله نقطه‌ای از سهمی $y=x^2$ از نقطه $A(0, 1)$ برابر $\\sqrt{13}$ است، مجموع طول و عرض نقطه مورد نظر چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
