(3363, '۲۵ - اگر $X=\\sqrt[4]{4\\sqrt[3]{16}}(\\frac{1}{4})^{-\\frac{1}{4}}$ باشد، حاصل $(\\frac{1}{X})^{\\frac{-3}{4}}$ چند برابر $\\sqrt{2}$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
