(3365, '۲۷ - اگر $a-b=\\sqrt{3}$ و $a^2+b^2=7$، آن‌گاه $a^3-b^3$ برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
