(3397, '۵۹- اگر یکی از ریشه‌های معادلهٔ $x^2-2x=3$ برابر $p-1$ باشد، مقدار p کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3398, '۶۰- کم‌ترین مقدار سهمی به معادلهٔ $y=ax^2+bx+c$ که از نقاط $(1, 0)$، $(-1, -6)$ و $(2, 6)$ عبور می‌کند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3399, '۶۱- جواب نامعادلهٔ $\\frac{2x^2-x-15}{3x^2-x-10} < 0$ با شرط $x > 1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3400, '۶۲- در کدام بازه نامعادلهٔ $|x-3x^2| < 2x$ برقرار است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3401, '۶۳- به ازای کدام مقدار m هر دو عبارت $\\begin{cases} y_1=x^2+x+m \\\\ y_2=2x^2+x+m \\end{cases}$ همواره مثبت هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3402, '۶۴- تعداد ریشه‌های معادلهٔ $4+(x^2+4x^{-2})=3(x+\\frac{2}{x})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3403, '۶۵- ثلث ریشه معادلهٔ $10 = \\sqrt[6]{x+1} + 2\\sqrt[3]{x+1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 19:23:19', 1, NULL, NULL, 'free'),
(3404, 'قرينه نقطه $A(a,3)$ نسبت به نقطه $B(2,1+ b)$، نقطه $A\'(3,a-1)$ است. مقدار $b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3405, 'در شکل رسم شده، مساحت ناحيه سایه خورده کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3406, 'نقطه $(a,2a)$ مرکز دایرة گذرنده بر دو نقطه $(1,1)$ و $(4,-2)$ است. شعاع این دایره کدام میباشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3407, 'مساحت متوازی الاضلاع محدود به معادله خطوط $x =5$ و $y=x+4$ نيمساز ناحيه اول برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(3408, 'هرگاه معادلات اضلاع $AB$ و $AC$ و $BC$ به ترتیب $y-2x+3=0 $ ، $2x+3y+1=0 $ و $3x-4y+2=0 $ باشند، در مثلث $ABC$ طول ارتفاع $AH$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3409, 'در شکل زير، خط $d$ به معادله $9-kx=(k+1)y$ رسم شده است. مجموع مقادير قابل قبول برای $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3410, 'معادله دو ضلع مجاور يک مستطيل $x-my=2$ و $2mx+my=3$ و نقطه $A(2,1)$ يک رأس آن است. مساحت اين مستطيل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3411, '8_قرينه نقطه $A(1,k)$ نسبت به خط $x+y=2$ ، روی محور عرض‌ها است$k$.  کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3412, '9_در شکل زیر، چهارضلعی $ABCD$ یک مربع است. مجموع مختصات رأس $D$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3413, 'سه نقطه $A(0, 1)$، $B(4, 1)$ و $C(0, 2)$ رأس‌های یک مثلث‌اند. اگر نیمساز بزرگ‌ترین زاویه این مثلث، ضلع روبه‌روی خود را در $D(\\alpha, \\beta)$ قطع کند، $alpha + beta$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3414, 'مطابق شکل، سطح تیره‌شده را حول $AB$ دوران می‌دهیم. حجم حاصل چند برابر $\\pi$ است؟ (مثلث متساوی‌الاضلاع است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3415, 'دایره‌ای به شعاع ۵ را حول یکی از قطرهایش دوران می‌دهیم و شکل حاصل از دوران را با صفحه‌ای به فاصله ۲ از مرکز دایره برش می‌زنیم. مساحت مقطع حاصل، چند برابر مساحت دایره است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3416, 'حجم حاصل از دوران ذوزنقه قائم‌الزاویه $ABCD$ حول $AD$ چند برابر $\\pi/a^3$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3417, 'یک صفحه مایل مطابق شکل، مکعبی به ضلع ۸ را طوری قطع کرده که مساحت مقطع برابر ۸۰ و $AC$ موازی $BG$ است. اگر $AB = 1$، آنگاه حجم قسمتی از مکعب که پایین صفحه قرار می‌گیرد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3418, 'از درون مکعب توپری به ابعاد ۲، بزرگ‌ترین مخروط قائم ممکن که قاعده آن روی یکی از وجوه مکعب قرار دارد را بیرون می‌آوریم. سطح مقطع جسم باقی‌مانده با صفحه‌ای که از وسط محور مخروط، موازی با قاعده آن می‌گذرد، کدام است؟ $(\\pi \\approx 3.14)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3419, 'از دوران یک مثلث قائم‌الزاویه حول وتر آن دو مخروط با قاعده‌های مشترک به وجود می‌آید که حجم یکی دو برابر دیگری است. اگر مساحت این قاعده مشترک برابر $36\\pi$ باشد، مساحت مثلث کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3420, 'صفحه‌ای تمام مولدهای یک سطح مخروطی را قطع کرده است، مقطع حاصل چه تعداد از شکل‌های دایره، بیضی و سهمی می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3421, 'مجموع فواصل نقطه متغیر $M$ از نقاط $(1-, 6)$ و $-1),-2)$ برابر ۱۰ است. بیشترین فاصله نقطه $M$ از محور $x$ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3422, 'اگر کانون‌ها و دو سر قطر کوچک یک بیضی را به هم وصل کنیم، یک چهارضلعی با محیط ۲۰ و مساحت ۲۴ تشکیل می‌شود. خروج از مرکز بیضی کشیده‌تر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3423, 'پاره‌خط واصل دو کانون یک بیضی، از هر سر قطر کوچک آن با زاویه $$\\150^circ رؤیت می‌شود. خروج از مرکز این بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3424, 'دایره به مرکز $(4,0)$ و مماس بر نیمساز ربع اول، خط $y=-2$ را با کدام طول قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3425, 'دایره $C\'$ در درون دایره $C$ با مرکز $(-1, 1)$ بر آن مماس است. اگر طول خط ‌المرکزین دو دایره برابر ۲ و مساحت محدود بین دو دایره برابر $$\\16 pi باشد، معادله دایره $C$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3426, '23_خط $ $3x-4y=5\\sqrt{3} وتری به طول $\\frac{k}/{2}$ روی دایره $x^2+y^2=k$ جدا می‌کند. اختلاف مقادیر ممکن برای $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3427, 'تمام خط‌هایی که سطح دایره‌ای به معادله $ax^2+2y^2+bx+cy=0$ را به دو قسمت مساوی تقسیم می‌کنند، از نقطه $(-1,2)$ می‌گذرند. شعاع این دایره کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3428, 'دایره گذرنده از مبدأ مختصات و دو نقطه $(2,0)$ و $(0,4)$ را در نظر بگیرید. معادله خط مماس بر این دایره در مبدأ مختصات کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3429, 'طول قطر یک مستطیل برابر با $d$ است. اگر حجم شکل حاصل از دوران این مستطیل حول یکی از ضلع‌هایش، بیشترین مقدار ممکن باشد، طول ضلع دیگر آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3430, 'از داخل یک استوانه قائم با شعاع قاعده و ارتفاع برابر، بزرگ‌ترین مخروط قائم را جدا کرده و شکل حاصل را با صفحه‌ای موازی با قاعده‌های استوانه و فاصله برابر از آن‌ها برش می‌زنیم. مساحت مقطع حاصل چند برابر مساحت قاعده استوانه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3431, '28_ زاویه‌های مثلثی با اعداد ۱، ۱ و ۴ متناسب و طول بزرگ‌ترین ضلع آن ۳ است. حجم حاصل از دوران این مثلث حول این ضلع چند برابر $\\pi$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:32', 1, NULL, NULL, 'free'),
(3432, 'دو نقطه $A$ و $A\'$ دو سر قطر بزرگ یک بیضی با فاصله کانونی ۲ و مرکز $O$ است. خطی که در کانون بیضی بر $AA\'$ عمود می‌شود، از دایره‌ای به قطر $AA\'$ و مرکز $O$، وتری به طول  $1.5$جدا می‌کند. خروج از مرکز بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:33', 1, NULL, NULL, 'free'),
(3433, 'دو نقطه $(-5,1)$ و $(11,1)$ دو سر کوچک‌ترین قطر یک بیضی هستند که طول بلندترین قطر آن ۲۰ است. اختلاف طول و عرض یکی از کانون‌های این بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:33', 1, NULL, NULL, 'free'),
(3434, '31خط به معادله $x+y=1$ از دایره به معادله $x^2+y^2-4y+a=0$ وتری جدا می‌کند که طول آن با شعاع دایره برابر است. $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:33', 1, NULL, NULL, 'free'),
(3435, 'منحنی به معادله $ (2x-1)^2+(2y+1)^2 =2$، محور $y$ها را در نقطه‌ای با عرض منفی قطع می‌کند و معادله خط مماس بر منحنی در این نقطه، به صورت $ax+by+2=0$ است. حاصل $a+b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:33', 1, NULL, NULL, 'free'),
(3436, 'دایره‌ای که بر دایره $x^2+y^2=1$ مماس داخل و بر دایره $x^2+y^2-6x+8=0$ مماس خارج است، خط\n\n $y= $ را با کدام طول مثبت قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:19:33', 1, NULL, NULL, 'free'),
(3437, 'خط به معادلهٔ $(k-1)x+2y=k$ از مبدأ مختصات به فاصلهٔ $0.5$ است. مجموع مقادیر ممکن برای $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3438, '2قرینهٔ نقطهٔ $M(3a+1,a+3)$ نسبت به نقطهٔ $N(2a,2-a)$ روی خط $6=$2x-3y قرار دارد. طول پاره‌خط $MN$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3439, '3اگر دو ضلع مقابل از مربعی منطبق بر خطوط $$2y=3-kx و $x-3y=1$ باشد، مساحت دایرهٔ مماس بر اضلاع این مربع کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3440, '4مساحت مثلثی که یک ضلع آن بر روی محور $y$ها و دو ضلع دیگر آن بر روی خطوط به معادلهٔ $$2y-4x+4=0 و $y=x+4$ قرار دارد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3441, '5دو نقطه بر روی خط $$2x+y=1 وجود دارد که فاصلهٔ آن‌ها از خط $d$ که شیب آن $2$ بوده و از نقطهٔ $(1,2)$ می‌گذرد، برابر $\\sqrt{5}$ است. فاصلهٔ این دو نقطه از همدیگر چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3442, '6اگر $A(k,2k-1)$ و $B(1,6)$ و $C(-1,2)$ رئوس مثلث قائم‌الزاویهٔ $ABC$ ($\\hat{A}=90^\\circ$) باشد، اندازهٔ ارتفاع وارد بر وتر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3443, '7دو ضلع متوازی‌الاضلاع $ABCD$ بر روی خط‌های $y=-2x+2$ و $y=x+2$ قرار دارند. اگر نقطه به مختصات $(-4,8)$ یک رأس متوازی‌الاضلاع باشد، طول قطر کوچک‌تر آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3444, '8صفحهٔ $P$ کره‌ای به مرکز $O$ و شعاع $13$ را قطع کرده است. اگر فاصلهٔ $O$ تا صفحهٔ $P$ برابر $12$ باشد، مساحت مقطع ایجاد شده کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3445, '9از داخل کره‌ای توپر به شعاع $3$ یک مخروط قائم طوری خالی شده است که نسبت ارتفاع آن به قطر کره $\\frac{2}/{3}$ است. حال صفحهٔ $P$ را موازی قاعده مخروط طوری رسم می‌کنیم که از مرکز کره بگذرد. در این‌صورت مساحت شکل ایجاد شده روی صفحهٔ $P$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3446, '10حجم جسم حاصل از دوران شکل مقابل به اندازهٔ $$ 180^\\circ درجه حول خط $AH$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3447, '11در شکل زیر، $ABCD$ و $A\'B\'C\'D\'$ مستطیل‌هایی هم‌مرکز به طول‌های $4$ و $3$ و عرض‌های $2$ و $1$ هستند. حجم حاصل از دوران این شکل حول محور $d$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3448, '12اگر نقاط $A(-3,0)$ ، $B(0,4)$ و $C(-6,4)$ رئوس مثلث $ABC$ باشند، آنگاه حجم حاصل از دوران این مثلث حول محور $y$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3449, '13یک استوانهٔ قائم با شعاع قاعده $3$ و ارتفاع $8$ مفروض است. اگر صفحهٔ $P$ با این استوانه به‌گونه‌ای مایل برخورد کند که بزرگ‌ترین بیضی ممکن ایجاد شود، خروج از مرکز این بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3450, '14اگر $A(2,-1)$ و $A\'(-6,-1)$ دو سر قطر بزرگ یک بیضی و $F(1,-1)$ یکی از کانون‌های آن باشد، مساحت چهارضلعی که رأس‌های آن، کانون‌ها و دو سر قطر کوچک بیضی است، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3451, '15دو سر قطر بزرگ یک بیضی نقاط $(2,4)$ و $(2,-2)$ هستند و این بیضی بر محور $y$ها مماس است. خروج از مرکز این بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3452, '16مختصات دو سر قطر بزرگ یک بیضی $(3,5)$ و $(3,-1)$ و خروج از مرکز آن $\\frac{1}/{2}$ است. این بیضی محورهای مختصات را در چند نقطه قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3453, '17یک بیضی که قطر بزرگ آن $4$ برابر قطر کوچکش است درون دایره به مرکز $O(-1,2)$ در دو نقطه به آن مماس شده است. اگر دایره و بیضی هم‌مرکز باشند و نقطه $M(1,6)$ واقع بر دایره باشد، فاصلهٔ کانونی بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3454, '18در بیضی افقی مقابل $PF\'$ نصف فاصلهٔ کانونی است. نسبت اندازهٔ قطر کوچک به قطر بزرگ بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3455, '19نقاطی که مجموع فواصل آن‌ها از دو نقطهٔ $(-6,2)$ و $(2,2)$ برابر $10$ باشد، روی یک منحنی قرار دارند. در این منحنی بیشترین مقدار $y$ و کم‌ترین مقدار $x$ چقدر با هم اختلاف دارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3456, '20بیضی زیر به طول قطرهای $8$ و $6$ را در نظر بگیرید. اگر فاصلهٔ نقطهٔ $M$ از مرکز بیضی برابر با $\\sqrt{7}$ باشد، حاصل $MF.MF\'$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3457, '21دو نقطه $(2,3)$ و $(4,1)$ روی محیط یک دایره به معادله $x^2+y^2+ax+by+c=0$ قرار داشته و بیشترین فاصله ممکن را از هم دارند. مقدار $c$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3458, '22وضعیت دو دایره $x^2+y^2+6x+8y=0$ و $x^2+y^2-4x+6y+12=0$ نسبت به هم چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3459, '23کمترین فاصله ممکن برای نقطه‌ای روی دایره $x^2+y^2+8x+6y-11=0$ از نقطه‌ای روی دایره $x^2+y^2-12x-10y+25=0$، برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3460, '24فاصله مرکز دایره‌ای به شعاع $$4\\sqrt{2} که بر نیمسازهای ناحیه اول و دوم مختصات مماس است، از نقطه $(3,4)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3461, '25خط به معادله $y=\\frac{3}{4}x+\\frac{7}{4}$ در برخورد با دایره به معادله $x^2+y^2+6x-4y+a=0$ وتری به اندازه $\\sqrt{20}$ ایجاد می‌کند. مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3462, '26خطوط $x+2y+2=0$ و $$2x+4y-1=0 بر دایره‌ای به مرکز $O(\\alpha,\\beta)$ مماسند. اگر معادله یکی از قطرهای این دایره نیمساز ربع دوم و چهارم باشد، مقدار $\\alpha-\\beta$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3463, '27از نقطه $A(4,1)$، خطی مماس بر دایره $C:x^2+y^2-2x-4y=0$ رسم می‌کنیم. معادله این خط مماس کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
