(3465, '29اگر فاصله نقطه $M(x,y)$ از نقطه $A(6,0)$ دو برابر فاصله‌اش از نقطه $B(0,3)$ باشد، مسیر حرکت $M$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3466, '30خط $y=mx+h$ همزمان بر دو دایره $C:x^2+y^2+4x-6y+9=0$ و $C\':x^2+y^2-2x+2y-47=0$ در یک نقطه مشترک مماس است $m$. کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3467, '31اگر $A\\begin{bmatrix} 3 \\\\ -2 \\end{bmatrix}$ و $B\\begin{bmatrix} -1 \\\\ 2 \\end{bmatrix}$ باشند، در این‌صورت فاصله نقطه‌ای به طول ۴ روی خط $y-2x+3=0$ از عمودمنصف پاره‌خط $AB$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3468, '32در بیضی مقابل طول قطر بزرگ $ $2a است. اگر دایره به قطر $FF\'$ (کانون‌ها) از رئوس غیرکانونی $(B\',B)$ عبور کند، مساحت مثلث $BAF$ چند برابر $\\frac{a^2}{4}$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3469, '33طول قطر بزرگ یک بیضی با خروج از مرکز $\\frac{5}{7}$ برابر $7$ است. اگر نقطه $M$ روی بیضی و به فاصله $\\frac{5}{2}$ از مرکز بیضی باشد، فاصله نقطه $M$ از نزدیک‌ترین کانون بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3470, '34در شکل زیر، ناحیه هاشورخورده را حول محور عرض‌ها دوران می‌دهیم، حجم حاصل چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
