(3476, '40نقاط $A(x, y)$ و $B(-2, 3)$ و $C(2, 0)$ سه رأس مثلث $ABC$ هستند. اگر خط $y = -2x + 3$ از رأس $A$ عبور کند و اندازه ارتفاع $AH$ برابر $2/2$ باشد، مقادیر ممکن برای طول نقطه $A$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3477, '41مخروطی قائم به شعاع قاعده $$۳ و ارتفاع $$3\\sqrt{3} را با صفحه‌ای که شامل رأس و مرکز قاعده مخروط می‌باشد، قطع می‌دهیم. محیط مقطع حاصل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3478, '42 یک شش‌ضلعی منتظم به طول ضلع $$۴ را حول یکی از قطرهای بزرگ آن دوران می‌دهیم. حجم حاصل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3479, '43بیضی افقی در ناحیه دوم بر هر دو محور مختصات مماس است. اگر مرکز این بیضی روی خط $$2y - x = 1 بوده و خروج از مرکز آن $\\frac{\\sqrt{3}}{2}$ باشد، مساحت مستطیل حاصل از برخورد خطوط مماس بر بیضی در رئوس آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3480, '44 فرض کنید $F$ و $F\'$ کانون‌های یک بیضی به طول قطر بزرگ $$5\\sqrt{3} باشند $M$. نقطه‌ای روی بیضی است، به‌گونه‌ای که $MF$ و $MF\'$ برهم عمودند. اگر $MF \\times MF\' = 13$ باشد، آنگاه فاصله دو کانون این بیضی از هم کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3481, '45 در یک بیضی با قطر بزرگ $ $10 و کانون‌های $F \\begin{vmatrix} -1 \\\\ 3 \\end{vmatrix}$ و $F\' \\begin{vmatrix} K \\\\ -2 \\end{vmatrix}$، اگر $M \\begin{vmatrix} 2 \\\\ -1 \\end{vmatrix}$ درون بیضی واقع باشد، چند مقدار صحیح مورد قبول برای $K$ پیدا می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3482, '46مجذور شعاع دایره‌ای که از سه نقطه $(-4, 2)$، $(2, -2)$ و $(0, 0)$ می‌گذرد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3483, '47 دایره‌ای به معادله $x^2 + y^2 - 2x - 3 = 0$ روی خط‌های $y = kx$ و $y + 2x = 1$ وترهای مساوی ایجاد می‌کند. مقدار $k$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3484, '48 اگر دو دایره $(x - a)^2 + (y - 5)^2 = 4$ و $x^2 + y^2 + 2x - 4y = a^2 - 5$ نسبت به هم مماس خارج باشند، آنگاه فاصله بین مرکزهای دو دایره کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3485, '49در دو دایره یکی به مرکز $O_1(-3, 2)$ و شعاع $$۵ و دیگری به مرکز $O_2(5, 8)$ و شعاع $$۷، فاصله مبدأ مختصات از خط شامل وتر مشترک دو دایره کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3486, '50شعاع دایره‌ای که بیانگر نقاطی باشد که فاصله آن‌ها از نقطه $A(-3, -1)$، نصف فاصله آن‌ها از نقطه $B(-6, -5)$ باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3487, '51 نقطه $A$ روی خط $d$ مفروض است. مساحت نقاطی از صفحه که از نقطه $A$ به فاصله کمتر از $4$ واحد و از خط $d$ به فاصله بیشتر از $2$ واحد هستند، چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3488, '52 اگر $A$ و $B$ دو نقطه ثابت در صفحه باشند، مجموعه نقاطی مانند $M$ که در تساوی $\\frac{AM - 4MB}{2AM + 3MB} = \\frac{-3}{5}$ صدق کند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3489, '53 اگر ذوزنقه قائم‌الزاویه $ABCD$ را حول ضلع $CD$ دوران دهیم، حجم جسم حاصل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3490, '54در بیضی با کانون‌های $F$ و $F\'$ و مرکز $O$، محیط مثلث‌های $ABF$ و $CFF\'$ با هم برابر است. خروج از مرکز بیضی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:32', 1, NULL, NULL, 'free'),
(3491, '55 دو سر قطر دایره‌ای به شعاع $4$ مختصات دو سر کانون‌های بیضی $F$ و $F\'$ به خروج از مرکز $0.8$ است. اگر نقطه $M$ یکی از نقاط برخورد دایره و بیضی باشد، مساحت مثلث $MFF\'$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:33', 1, NULL, NULL, 'free'),
(3492, '56 مطابق شکل زیر، دایره‌ای درون مربع $ABCD$ محاط شده است. اگر مختصات نقاط $A$ و $B$ به ترتیب برابر $(-1, 4)$ و $(1, -2)$ باشد، معادله دایره به کدام صورت است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:33', 1, NULL, NULL, 'free'),
(3493, '57شعاع کوچک‌ترین دایره‌ای که بر محور $y$ها و خط $$3y + 4x = 0 مماس است و از نقطه $(4, -1)$ می‌گذرد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:33', 1, NULL, NULL, 'free'),
(3494, '58 نقطه $A(-1, 4)$ مرکز یک دایره است که بر روی خط $$2x - 3y + 1 = 0 وتری به طول $$2\\sqrt{7} جدا می‌کند. این دایره خط $y = 2$ را با کدام طول، قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:33', 1, NULL, NULL, 'free'),
(3495, '59در داخل بیضی به کانون‌های $F(5, 1)$ و $F\'(-1, 1)$ و رأس کانونی $A(6, 1)$، دایره‌ای مماس بر بیضی در دو سر قطر کوچک رسم شده است. وضعیت این دایره نسبت به دایره به معادله $x^2 + y^2 = 2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:50:33', 1, NULL, NULL, 'free'),
(3496, '۱- اگر $A=\\{ (a,a+1) | a \\in \\{0,1\\} \\}$، $B=\\{ (a,a+b) | a,b \\in \\{0,1\\} \\}$ باشد، تعداد اعضای مجموعۀ $A \\cup B$ چندتا است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3497, '۲- مجموعه‌های $A=[1,2)$ ، $B=\\{ x | (1-2x) \\in A \\}$ و $C=(0,1)$ مفروض است. اگر $A \\cup B \\cup C = (a,b)$ باشد، $b-a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3498, '۳- در دنبالۀ هندسی $z, x-5, x+1, y, \\frac{x}{2}$ حاصل $xyz$ چقدر است؟ $(x \\in \\mathbb{Z})$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3499, '۴- در الگوی زیر اگر $t_n$ تعداد کل دایره‌ها و $b_n$ تعداد دایره‌های رنگ‌نشده باشد، الگوی $t_n + b_n$ در شکل دهم چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3500, '۵- اگر $A$ مجموعۀ مضرب‌های طبیعی عدد ۱۲، $B$ مجموعۀ مضرب‌های طبیعی عدد ۴ و $C$ مجموعۀ مضرب‌های عدد ۵ باشد، کدام مجموعۀ زیر در $\\mathbb{N}$ متناهی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3501, '۶- اگر $A_n = [ n+1 , -\\frac{1}{n} )$ باشد، مجموعه‌ی $(A_1 \\cup A_2) - A_3$ شامل چند عدد صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3502, '۷- حاصل مجموعه‌ی $(B \\cap C) \\cup (A-B) \\cup (B-C)$ برابر با کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3503, '۸- اگر $[7,16) = [9,3a+1) \\cup (a-2b, 7]$ باشد، $b-a$ با شرط $b \\in \\mathbb{Z}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3504, '۹- اگر اشتراک دو بازه‌ی $(2, 3x+y+1]$ و $[2x+y, 8)$ برابر $\\{4\\}$ باشد، حاصل $y^x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3505, '۱۰- حاصل $A \\cap (A\' \\cup B)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3506, '۱۱- در یک کلینیک پزشکی ۱۵ نفر دارای بیماری قلبی و ۲۰ نفر دارای دیابت می‌باشند. اگر ۵ نفر دارای دیابت و بیماری قلبی باشند، این کلینیک چند نفر بیمار قلبی یا دیابتی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3507, '۱۲- اختلاف تعداد دایره‌های توپر و توخالی در شکل نهم الگوی زیر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3508, ' اعداد $5x-5$ و $3x$، $2x+1$ به ترتیب جمله‌های چهارم، پنجم و ششم یک دنبالۀ حسابی هستند. جمله بیست و یکم این دنباله کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 20:53:02', 4, 'done'),
(3509, 'مجموع سه عدد که تشکیل دنبالۀ هندسی می‌دهند ۲۸ و حاصل‌ضرب آن‌ها ۵۱۲ می‌باشد. قدرنسبت کدام می‌تواند باشد؟', 1, 1, 59, 244, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 20:53:29', 4, 'done'),
(3510, ' چندمین جمله از دنباله‌ی $...,\\frac{1}{9},-\\frac{1}{3},1$ برابر $\\frac{1}{729}$ است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:09:05', 4, 'done'),
(3511, ' در یک دنباله‌ی حسابی، جمله‌ی هفتم بیست واحد از جمله‌ی پنجم بیش‌تر است. حاصل $A = \\frac{t_5+t_3-2t_1+1}{t_4+t_{10}-2t_5-20}$ کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:09:27', 4, 'done'),
(3512, 'اگر $t_n = (-2k+4)n^2+(k-3)n+2k-1$ یک الگوی خطی باشد، حاصل‌ضرب ۸ جمله‌ی اول دنباله‌ی $a_n = (-1)^{n+1} \\frac{kn}{n+1}$ کدام است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:09:56', 4, 'done'),
(3513, 'دنباله‌ی حسابی با مشخصات $t_1=2$ و $t_{24}-t_{48}=-2$، چند جمله‌ی مثبت دارد؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:10:35', 4, 'done'),
(3514, 'بین دو عدد ۱۳۰ و ۱۵۰، چهار عدد قرار می‌دهیم که با دو عدد اولیه تشکیل دنبالۀ حسابی بدهند. اگر دنباله از کوچک به بزرگ مرتب شده باشد، مجموع دومین و چهارمین جمله کدام است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:13:13', 4, 'done'),
(3515, 'جملات اول، دوم و چهارم یک دنباله درجه دوم به ترتیب ۳-، ۱ و ۲۷ است. مجموع جملات سوم و پنجم چقدر است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:11:05', 4, 'done'),
(3516, ' اگر $A$ و $B$ دو مجموعه جدا از هم و $n(B)=8-3n(A)$ باشد، حداقل مقدار $n(A \\cup B)$ چقدر است؟', 1, 1, 61, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:12:50', 4, 'done'),
(3517, ' اگر قدرنسبت دنباله‌های حسابی $..., x, 2y, ...$ و $..., y, \\frac{3}{x}$ با هم برابر باشند، مقدار $xy-x^2$ چقدر است؟ $(x \\neq 0)$', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:13:44', 4, 'done'),
(3518, ' جملات دوم و چهارم الگوی مربعی به ترتیب برابر جملات سوم و هفتم یک دنباله حسابی است. قدرنسبت دنبالۀ حسابی چقدر است؟', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:14:08', 4, 'done'),
(3519, '۲۴- دنباله $a_n = 3n^2-5n-50$ چند جمله منفی دارد؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:14:38', 4, 'done'),
(3520, ' جملات اول، دوم و چهارم یک دنباله درجه دوم به ترتیب ۳-، ۱ و ۲۷ است. مجموع جملات سوم و پنجم چقدر است؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:15:02', 4, 'done'),
(3521, '۲۶- اگر $A$ و $B$ دو مجموعه جدا از هم و $n(B)=8-3n(A)$ باشد، حداقل مقدار $n(A \\cup B)$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3522, ' اگر قدرنسبت دنباله‌های حسابی $..., x, 2y, ...$ و $..., y, \\frac{3}{x}$ با هم برابر باشند، مقدار $xy-x^2$ چقدر است؟ $(x \\neq 0)$', 1, 1, 59, 243, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, '2026-03-29 21:15:23', 4, 'done'),
(3523, '۲۸- جملات دوم و چهارم الگوی مربعی به ترتیب برابر جملات سوم و هفتم یک دنباله حسابی است. قدرنسبت دنبالۀ حسابی چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3524, '۲۹- دنباله $a_n = 3n^2-5n-50$ چند جمله منفی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3525, '۳۰- اگر $t_n$ دنبالۀ خطی و $a_n$ دنبالۀ درجه دوم و همچنین، $a_3=0$، $t_1=a_1+1=-1$، $a_5=t_5-3=7$ باشد، آن‌گاه مجموع جملات نودم و صد و یکم دنبالۀ $..., a_3, t_3, a_2, t_2, a_1, t_1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3526, '۳۱- در یک کلاس ۲۲ نفری ۱ نفر هم به فوتبال و هم والیبال علاقه‌مند است. اگر ۹ نفر به والیبال علاقه‌مند باشند، چند نفر به فوتبال علاقه‌مندند؟ (۳ نفر به هیچ‌کدام از دو رشته علاقه‌ای ندارند)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3527, '۳۲- اگر $\\{ p \\} = (-\\infty, k+2] \\cap [\\frac{15}{k}, 10)$ باشد، $|p+k|$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3528, '۳۳- در دنبالۀ حسابی $..., x+2, 6, 3m, y, 21, ...$ مجموع جملات دهم و یازدهم چند برابر مجموع جملات دوم، سوم و چهارم است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 20:57:26', 1, NULL, NULL, 'free'),
(3529, '۱- اگر A و B دو پیشامد مستقل در فضای نمونه‌ای S باشند، به‌طوری که $P(A) = 0.25$ و $P(B) = 0.6$، احتمال پیشامد $A\' \\cup B\'$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3530, '۲- دو مکعب داریم. روی سه وجه از مکعب اول عدد «۱» و روی سه وجه دیگر عدد «۲» حک شده است. همچنین روی سه وجه از مکعب دوم، عدد «۰» و روی سه وجه دیگر «۱-» حک شده است. این دو مکعب را با هم پرتاب می‌کنیم. احتمال آنکه مجموع اعداد روشده برابر «۱» شود کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3531, '۳- در آزمایش پرتاب دو تاس دو پیشامد «مجموع دو تاس برابر ۵ بودن» و «زوج بودن هر دو تاس» نسبت به هم چگونه هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3532, '۴- یک خانواده با سه فرزند را در نظر بگیرید. پیشامد «بیشتر بودن تعداد پسرها از دخترها» از کدام‌یک از پیشامدهای زیر مستقل است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3533, '۵- احتمال برد تیم ملی والیبال ایران در یک بازی ۰/۵۶ است و اگر ایران دست اول را ببرد، احتمال برد کل بازی به ۰/۷ افزایش می‌یابد. همچنین احتمال برد دست اول در این بازی برای تیم ایران ۰/۴ است. احتمال آنکه ایران دست اول بازی را ببازد و در کل برنده‌ی بازی شود، چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3534, '۶- در یک کیسه سه مهرهٔ آبی با شماره‌های ۱ تا ۳، سه مهرهٔ قرمز با شماره‌های ۱ تا ۳ و سه مهرهٔ زرد با شماره‌های ۱ تا ۳ وجود دارد. به‌طور تصادفی سه مهره از این ۹ مهره را خارج می‌کنیم. اگر حاصل جمع اعداد روی مهره‌های خارج‌شده برابر ۶ باشد، احتمال هم‌رنگ بودن مهره‌ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3535, '۷- از میان ۶ جفت جوراب متمایز، دو لنگه به تصادف انتخاب می‌کنیم. احتمال اینکه این دو لنگه، جفت یکدیگر باشند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3536, '۸- دو پیشامد A و B مستقل از یکدیگر هستند. اگر $P(A|B) = \\frac{1}{3}$ و $P(B|A) = \\frac{1}{4}$، حاصل $P(A \\cup B)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3537, '۹- در جعبه‌ای ۴ مهرهٔ آبی و تعدادی مهرهٔ قرمز وجود دارد. از این جعبه ۲ مهره به‌تصادف و با هم خارج می‌کنیم؛ احتمال آنکه حداقل یکی از مهره‌ها آبی باشد، برابر $\\frac{6}{7}$ است. اگر از این جعبه ۱ مهره خارج کنیم، چقدر احتمال دارد، این مهره آبی باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3538, '۱۰- در جعبهٔ A، سه مهرهٔ سفید و دو مهرهٔ قرمز و در جعبهٔ B، چهار مهرهٔ قرمز و n مهرهٔ سفید داریم. اگر $P(C)$ احتمال خارج‌شدن مهرهٔ سفید از جعبهٔ A و $P(D)$ احتمال خارج‌شدن مهرهٔ قرمز از جعبهٔ B باشد، می‌دانیم $P(C) - P(D) = \\frac{1}{5}$. عدد طبیعی n کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, NULL, NULL, 'free'),
(3539, 'از یک ظرف شامل ۲ مهرهٔ زرد، ۳ مهرهٔ سبز و ۵ مهرهٔ آبی، سه مهره را به‌صورت متوالی و بدون جای‌گذاری خارج می‌کنیم. اگر مهرهٔ اول زرد باشد، احتمال آنکه مهرهٔ سوم خارج‌شده سبز باشد، کدام است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 11:24:29', 2, 'done'),
(3540, 'دانش‌آموزان سال دوازدهم مدرسه‌ای در رشتهٔ ریاضی یا تجربی تحصیل می‌کنند. اگر ۶۰ درصد از دانش‌آموزان رشتهٔ ریاضی، ۸۰ درصد از دانش‌آموزان رشتهٔ تجربی و ۶۵ درصد از کل دانش‌آموزان در امتحانات نهایی قبول شده باشند، چند درصد از دانش‌آموزان سال دوازدهم مدرسه در رشتهٔ تجربی تحصیل می‌کنند؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 11:19:55', 2, 'done'),
(3541, 'فردی در جیب خود سه سکه دارد. هر دو طرف یکی از سکه‌ها رو، هر دو طرف سکهٔ دیگر پشت و یک طرف سکهٔ آخر رو و طرف دیگر آن پشت است. وی به تصادف دو سکه از جیب خود خارج کرده و پرتاب می‌کند. احتمال آنکه یکی از سکه‌ها رو و دیگری پشت بیاید چقدر است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 11:14:08', 2, 'done'),
(3542, 'دو جعبه داریم که در جعبهٔ اول ۶ مهرهٔ سفید و ۳ مهرهٔ سیاه و در جعبهٔ دوم ۴ مهرهٔ سفید و ۵ مهرهٔ سیاه قرار دارند. از جعبهٔ اول سه مهره به دلخواه خارج و در جعبهٔ دوم می‌اندازیم. سپس مهره‌ای از جعبهٔ دوم خارج می‌کنیم. با کدام احتمال مهرهٔ خارج‌شده سیاه است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 11:08:12', 2, 'done'),
(3543, 'تاس سالمی را سه بار پرتاب می‌کنیم. اگر بدانیم مجموع اعداد روشده یک عدد زوج است، احتمال اینکه لااقل یکی از اعداد روشده ۶ باشد، کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:36:33', 2, 'done'),
(3544, 'دو عدد متمایز دورقمی به‌تصادف انتخاب کرده‌ایم. اگر بدانیم تفاضل آن‌ها عددی فرد است، احتمال اینکه یکی از آن‌ها بر ۱۰ بخش‌پذیر باشد، کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:35:59', 2, 'done'),
(3545, 'یک کارخانهٔ اتومبیل‌سازی سه نوع اتومبیل B ،A و C را تولید می‌کند. نصف تولیدات این کارخانه مدل A است و به‌ترتیب ۰/۸، ۰/۵ و ۰/۴ از تولیدات مدل‌های B ،A و C به رنگ سفید هستند. اگر یک اتومبیل از این کارخانه به‌تصادف انتخاب کنیم به احتمال ۰/۶۳ سفید است. چند درصد از تولیدات این کارخانه اتومبیل مدل B می‌باشد؟', 3, 1, 53, 225, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:35:23', 2, 'done'),
(3546, 'احتمال موفقیت رضا در کنکور ۵۰ درصد و احتمال اینکه او در آزمون گزینه‌دو شرکت کند ۲۵ درصد است. اگر او در گزینه‌دو شرکت نکند احتمال اینکه در کنکور موفق نشود ۶۰ درصد است. اگر او در آزمون گزینه‌دو شرکت کند چقدر احتمال دارد در کنکور موفق شود؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:34:37', 2, 'done'),
(3547, 'در ظرف A، ۳ مهرهٔ سفید و ۲ مهرهٔ سیاه و در ظرف B، ۲ مهرهٔ سفید و تعدادی مهرهٔ زرد قرار دارد. از ظرف A دو مهره انتخاب می‌کنیم و در ظرف B قرار می‌دهیم و از ظرف B یک مهره به‌تصادف خارج می‌کنیم. اگر احتمال سفید بودن مهرهٔ خارج‌شده از ظرف B برابر $\\frac{8}{15}$ باشد، در این ظرف چند مهرهٔ زرد قرار دارد؟', 3, 1, 53, 225, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:33:17', 2, 'done'),
(3548, 'سه تاس را هم‌زمان پرتاب می‌کنیم. احتمال آنکه حاصل‌ضرب اعداد روشدهٔ دوتا از آن‌ها برابر دیگری باشد، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:32:33', 2, 'done'),
(3549, 'در یک کلاس ۲۰ دانش‌آموز حضور دارند که نمرهٔ ریاضی هیچ دونفری از آن‌ها یکسان نیست. به‌طور تصادفی از دو دانش‌آموز نمرهٔ ریاضی آن‌ها را می‌پرسیم. اگر نمرهٔ ریاضی دانش‌آموز اول بیشتر از دانش‌آموز دوم باشد، احتمال آنکه دانش‌آموز اول بالاترین نمرهٔ ریاضی را در کل کلاس کسب کرده باشد، کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:31:31', 2, 'done'),
(3550, 'دو پیشامد A و B مستقل بوده و $P(A \\cap B) = 0.4$ و $P(A - B) = 0.2$. مقدار $P(A \\cup B\')$ کدام است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:30:37', 2, 'done'),
(3551, 'دو ظرف داریم. یکی شامل ۴ مهرهٔ سفید و ۲ مهرهٔ سیاه و دیگری شامل یک مهرهٔ سفید و ۵ مهرهٔ سیاه است. ۸ مهرهٔ جدید که ۶ تا از آن‌ها سفید و ۲ تای دیگر سیاه است را به‌تصادف به دو قسمت مساوی تقسیم کرده و هر قسمت را در یکی از دو ظرف می‌ریزیم. سپس یکی از دو ظرف را به‌صورت تصادفی انتخاب کرده و از آن مهره‌ای خارج می‌کنیم. احتمال آنکه مهرهٔ انتخابی سفید باشد چند درصد است؟', 3, 1, 53, 225, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:29:59', 2, 'done'),
(3552, 'در جعبه‌ای ۴ مهرهٔ آبی و تعدادی مهرهٔ قرمز وجود دارد. از این جعبه ۲ مهره به‌تصادف و با هم خارج می‌کنیم؛ احتمال آنکه حداقل یکی از مهره‌ها آبی باشد، برابر $\\frac{6}{7}$ است. اگر از این جعبه ۱ مهره خارج کنیم، چقدر احتمال دارد، این مهره آبی باشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:27:42', 2, 'done'),
(3553, 'در جعبهٔ A، سه مهرهٔ سفید و دو مهرهٔ قرمز و در جعبهٔ B، چهار مهرهٔ قرمز و n مهرهٔ سفید داریم. اگر $P(C)$ احتمال خارج‌شدن مهرهٔ سفید از جعبهٔ A و $P(D)$ احتمال خارج‌شدن مهرهٔ قرمز از جعبهٔ B باشد، می‌دانیم $P(C) - P(D) = \\frac{1}{5}$. عدد طبیعی n کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:19:56', 2, 'done'),
(3554, 'اگر A و B دو پیشامد مستقل از فضای نمونهٔ S باشند، حاصل $P((A - B) | A)$ کدام است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:17:24', 2, 'done'),
(3555, 'از مجموعهٔ $\\{1, 2, 3, \\dots, 200\\}$ به‌تصادف یک عدد انتخاب می‌کنیم. چقدر احتمال دارد این عدد مضرب ۳ باشد ولی مضرب ۵ نباشد؟', 1, 1, 51, 221, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:14:13', 2, 'done'),
(3556, 'در کیسه‌ای ۵ مهرهٔ قرمز و ۴ مهرهٔ آبی موجود است. از این کیسه ۳ مهره به تصادف خارج می‌کنیم. با کدام احتمال دقیقاً دو مهره همرنگ است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:13:16', 2, 'done'),
(3557, 'در پرتاب دو تاس احتمال آنکه مجموع دو تاس ۶ یا هر دو فرد باشند، کدام است؟', 1, 1, 51, 221, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:12:51', 2, 'done'),
(3558, 'احمد به احتمال ۰/۶ در تیم والیبال مدرسه و به احتمال ۰/۷ در گروه سرود مدرسه انتخاب می‌شود. احتمال آنکه فقط در گروه سرود مدرسه انتخاب شود، چقدر است؟', 2, 1, 52, 223, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:06:31', 2, 'done'),
(3559, 'اگر A و B دو پیشامد از فضای نمونه‌ای S به‌گونه‌ای باشند که $P(A) = 0.4$ و $P(B|A) = 0.7$، احتمال رخداد پیشامد A - B کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:06:07', 2, 'done'),
(3560, 'ارقام ۱ تا ۷ را روی هفت کارت نوشته‌ایم. به‌طور تصادفی سه تا از کارت‌ها را انتخاب می‌کنیم. اگر مجموع ارقام روی سه کارت فرد باشد، احتمال آنکه حاصل‌ضرب آن‌ها نیز فرد باشد، کدام است؟', 2, 1, 52, 222, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:05:22', 2, 'done'),
(3561, ' در آزمایش تصادفی پرتاب یک تاس، فرض کنید پیشامد A ظاهر شدن عددی فرد، پیشامد B ظاهر شدن عددی مضرب ۴ و پیشامد C ظاهر شدن عددی کوچک‌تر از ۵ باشد. در کدام‌یک از گزینه‌ها، پیشامدهای داده‌شده مستقل از یکدیگر هستند؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:59:17', 5, 'done'),
(3562, ' احتمال آنکه یک پدر و پسر به یک بیماری ویروسی مبتلا شوند، به‌ترتیب برابر ۰/۴ و ۰/۲ است. اگر پسر به این ویروس مبتلا شود، احتمال ابتلای پدر به ۰/۷ افزایش پیدا می‌کند. می‌دانیم پسر به این ویروس مبتلا نشده است، احتمال ابتلای پدر چقدر است؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:58:49', 5, 'done'),
(3563, ' فرض کنید A و B دو پیشامد مستقل از هم باشند به‌گونه‌ای که احتمال رخداد B، $\\frac{3}{2}$ برابر احتمال رخداد A است. اگر احتمال رخداد لااقل یکی از این دو پیشامد با احتمال رخ ندادن A برابر باشد، احتمال رخداد B کدام است؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:58:24', 5, 'done'),
(3564, ' در کیسه‌ای ۶ مهرهٔ سفید و ۴ مهرهٔ سیاه موجود است. به چند طریق می‌توانیم ۳ مهره از کیسه خارج کنیم به‌طوری که همهٔ مهره‌ها از یک رنگ نباشند؟', 1, 1, 2, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:57:49', 5, 'done'),
(3565, ' سکه‌ای را ۳ بار پرتاب می‌کنیم. اگر پیشامد A «حالت‌هایی که سکه‌ها یکسان ظاهر شوند»، پیشامد B «حالت‌هایی که دقیقاً ۲ سکه رو ظاهر شود» و پیشامد C «حالت‌هایی که دقیقاً یکی از سکه‌ها پشت ظاهر شود» باشد، کدام گزینه درست است؟', 1, 1, 51, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:56:33', 5, 'done'),
(3566, ' ۳ تاس را به‌ترتیب پرتاب می‌کنیم. احتمال آنکه مجموع اعداد روشدهٔ دو تاس اول برابر تاس سوم باشد، کدام است؟', 1, 1, 51, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:55:59', 5, 'done'),
(3567, ' اگر A و B دو پیشامد مستقل از فضای نمونه‌ای S باشند، به گونه‌ای که $P(A|B) = 0.6$ و $P(B|A) = 0.7$، مقدار $P(A \\cup B)$ کدام است؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:52:02', 5, 'done'),
(3568, ' دو تاس را با هم پرتاب می‌کنیم، اگر اعداد روشده بزرگ‌تر از ۲ باشند، چقدر احتمال دارد مجموع کمتر از ۱۰ باشد؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:51:44', 5, 'done'),
(3569, 'در یک مسابقهٔ اتومبیل‌رانی احتمال اینکه یک اتومبیل دچار نقص فنی نشود و به خط پایان نیز برسد، برابر ۰/۷۵ است و احتمال اینکه یک اتومبیل دچار نقص فنی شود، برابر ۰/۱۵ است. اگر بدانیم یک اتومبیل دچار نقص فنی نشده است، با چه احتمالی به خط پایان می‌رسد؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:51:26', 5, 'done'),
(3570, ' در جعبهٔ A، ۳ مهرهٔ قرمز و ۴ مهرهٔ آبی و در جعبهٔ B، ۲ مهرهٔ قرمز و ۵ مهرهٔ آبی وجود دارد. یکی از دو جعبه را به تصادف انتخاب کرده، یک مهره به تصادف از آن خارج می‌کنیم. چقدر احتمال دارد که این مهره قرمز رنگ باشد؟', 3, 1, 53, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:51:06', 5, 'done'),
(3571, ' احتمال بهبود هر بیمار پس از ابتلا به نوعی بیماری خطرناک ۰/۳۸ است. اگر یک بیمار در سه ماههٔ اول بیماری به پزشک مراجعه کند، احتمال بهبود او به ۰/۸ افزایش می‌یابد. طبق تحقیقات ۳۰ درصد مبتلایان به این بیماری در سه ماههٔ اول به پزشک مراجعه می‌کنند. می‌دانیم فرد بیماری در سه ماههٔ اول به پزشک مراجعه نکرده است، احتمال بهبود او کدام است؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:50:36', 5, 'done'),
(3572, ' سارا در یک مسابقه شرکت کرده است. سه بسته سؤال که یکی شامل سؤال‌های ادبیات، یکی ریاضی و یکی تاریخ است، وجود دارد. اگر بستهٔ سؤال‌های ادبیات را به او بدهند، به‌احتمال ۸۰ درصد برنده خواهد شد. اگر بستهٔ سؤال‌های ریاضی را به او بدهند، به‌احتمال ۵۰ درصد و اگر بستهٔ سؤال‌های تاریخ را به او بدهند، به‌احتمال ۷۰ درصد برنده خواهد شد. اگر با چرخاندن عقربهٔ چرخان در شکل زیر نوع سؤال‌ها مشخص شود، تعیین کنید او به چه احتمالی برنده خواهد شد؟', 3, 1, 53, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:49:59', 5, 'done'),
(3573, 'سه ظرف مشابه هم داریم. در ظرف اول ۱۲ مهرهٔ سفید، در ظرف دوم ۶ مهرهٔ سیاه، در ظرف سوم ۴ مهرهٔ سفید و ۳ مهرهٔ سیاه داریم. به تصادف از یک ظرف دو مهره هم‌زمان خارج می‌کنیم. به کدام احتمال لااقل یک مهرهٔ سفید خارج شده است؟', 2, 1, 52, 224, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:04:42', 2, 'done'),
(3574, '۴ مرد و ۳ زن در یک ردیف کنار هم ایستاده‌اند. اگر بدانیم هیچ دو زنی کنار هم نیستند، به کدام احتمال زنان یک‌درمیان هستند؟', 1, 1, 51, 221, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 08:03:50', 2, 'done'),
(3575, 'در پرتاب دو تاس سالم احتمال آنکه جمع اعداد روشده برابر ۵ شود، برابر احتمال آن است که جمع اعداد روشده k را نشان دهد. مقدار k کدام است؟', 1, 1, 52, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 02:00:43', 5, 'done'),
(3576, ' دو ظرف داریم که در ظرف اول ۶ مهرهٔ سفید و ۳ مهرهٔ سیاه و در ظرف دوم ۴ مهرهٔ سفید و ۵ مهرهٔ سیاه قرار دارند. یک مهره به دلخواه از ظرف اول به ظرف دوم انتقال می‌دهیم، سپس از ظرف دوم دو مهره با هم خارج می‌کنیم. به کدام احتمال لااقل یکی از دو مهره سفید است؟', 3, 1, 53, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 02:00:26', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(3577, ' از ۱۰ لامپ موجود در یک جعبه ۳ تای آن‌ها معیوب است؛ هرگاه سه لامپ متوالی و بدون جای‌گذاری از جعبه خارج کنیم، با کدام احتمال لااقل به یک لامپ معیوب می‌رسیم؟', 2, 1, 52, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 02:00:03', 5, 'done'),
(3578, ' ۴ دانش‌آموز کلاس دوم و ۵ دانش‌آموز کلاس سوم قرار است کنار هم در یک ردیف بایستند. تعداد حالاتی که دانش‌آموزان کلاس دوم یک‌درمیان هستند چند برابر تعداد حالاتی است که دانش‌آموزان کلاس سوم کنار هم هستند؟', 1, 1, 2, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 21:01:24', 1, '2026-02-26 01:47:22', 5, 'done'),
(3579, ' نسبت طول اضلاع یک مستطیل $0.75$ و طول قطر آن $x$ است. ضابطه تابعی که مساحت این مستطیل را برحسب $x$ بیان می‌کند، کدام است؟', 1, 1, 41, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:45:46', 5, 'done'),
(3580, 'اگر $f = \\{(x, y) \\mid x, y \\in \\mathbb{Z}, x^2 |y| = 12\\}$، آنگاه با حذف حداقل چند زوج مرتب، $f$ تبدیل به تابع می‌شود؟', 1, 1, 41, 175, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:44:47', 5, 'done'),
(3581, ' نمودار تابع با ضابطه $f(x) = -x^2 + kx + m$ را در امتداد محور $x$ها، 2 واحد در جهت منفی انتقال می‌دهیم. نمودار به‌دست‌آمده، نمودار $f$ را در نقطه $(1, 3)$ قطع می‌کند. مقدار $k + 2m$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:42:16', 5, 'done'),
(3582, '\nاگر $f = \\{(-1, 2), (2, 4), (3, 3), (0, 1)\\}$ آن‌گاه با توجه به نمودار تابع $g$، حاصل $f(g(0)) + g(f(3))$ \n\nکدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:41:33', 5, 'done'),
(3583, '\n\nبه ازای چند مقدار $m$، رابطة $f = \\{(m, 3m+1), (2m, -1), (2, 7), (3, 7)\\}$ تابع نیست؟', 1, 1, 41, 175, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:41:02', 5, 'done'),
(3584, '\n\nتابع $f$ با ضابطة $f(x) = x^2$ و دامنۀ $A$ و برد $B = \\{0, 1, 4\\}$ مفروض است. چند حالت برای مجموعة $A$ وجود دارد؟', 1, 1, 41, 176, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:40:32', 5, 'done'),
(3585, '\n\nدامنۀ تابع‌های $f$ و $g$ با ضابطه‌های $f(x) = 2x-1$ و $g(x) = a-x$ بازة $[0, 1]$ است. اگر اشتراک برد این دو تابع بازة $[0, 2]$ باشد، مقدار $a$ کدام است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:31:05', 5, 'done'),
(3586, 'اندازه وتر یک مثلث قائم‌الزاویه، $a$ و اندازه یکی از اضلاع قائمه آن $\\sqrt{2a - 1}$ است. ضابطه تابعی که اندازه ضلع دیگر زاویه قائمه را برحسب $a$ بیان می‌کند، کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:04:40', 5, 'done'),
(3587, ' اگر تابع $f$ با ضابطه $f(x) = (a^2 - 2)x + |ax + 1|$ روی زیرمجموعه‌ای از دامنه‌اش، ثابت باشد، حاصل‌ضرب تمام مقادیر قابل قبول برای $a$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 01:03:28', 5, 'done'),
(3588, ' اگر $f(x) = x^2 + kx$، به طوری که $y = 8 - f(x) + f(4 - x)$ ضابطه یک تابع ثابت باشد، آنگاه مقدار $k$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 00:54:19', 5, 'done'),
(3589, ' اگر $f$ یک تابع خطی و $2f(x) + f(-x) = 2x - 9$، آنگاه $f(5)$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 00:34:10', 5, 'done'),
(3590, ' خط $y = k$ نمودار $f(x) = \\begin{cases} |x - 1| - 1 & ; & x \\le 1/5 \\\\ -x^2 + 4x - 6 & ; & x > 1/5 \\end{cases}$ را در دو نقطه قطع می‌کند. $k$ کدام می‌تواند باشد؟', 1, 1, 41, 176, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:40:23', 1, '2026-02-26 00:33:29', 5, 'done'),
(3591, '. تابع ثابت $f = \\{(1,-1), (3,-a-3), (6,b-3a)\\}$ و تابع همانی $g(x) = \\alpha x + (\\beta - \\beta)$ را در نظر بگیرید. حاصل $\\frac{g(b+\\beta)}{a+\\alpha}$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-26 00:18:31', 5, 'done'),
(3592, 'مطابق شکل، مساحت مستطیل مشخص‌شده، تابعی از طول نقطۀ A است. ضابطۀ این تابع کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-26 08:03:00', 2, 'done'),
(3593, 'اگر $f$ تابع همانی باشد و $f(2a+f(a)) = a^2-4$، آن گاه مجموع مقادیر قابل قبول برای $a$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-26 08:02:35', 2, 'done'),
(3594, 'تابع با ضابطۀ $f(x) = x^2$ و دامنۀ $D$ را در نظر بگیرید. اگر برد این تابع، مجموعۀ $\\{0,2,4\\}$ باشد، تعداد اعضای مجموعۀ $D$ چند مقدار مختلف می‌تواند داشته باشد؟', 1, 1, 41, 176, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-26 00:00:54', 5, 'done'),
(3595, ' تابع خطی $f$ با دامنۀ $[-2, 4]$ و برد $[0, 3]$ مفروض است. مجموعۀ مقادیر ممکن برای $f(0)$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-26 00:00:11', 5, 'done'),
(3596, '۶- برد تابع درجه‌دوم $f(x) = ax^2 - 4x + 2a$ برابر $(-\\infty, a]$ است. با برداشتن نقطه‌ای با کدام طول از دامنۀ این تابع، برد آن تغییر می‌کند؟', 2, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:59:15', 5, 'free'),
(3597, '. اگر $f(x) = \\frac{ax+a-6}{a-8x}$ ضابطه یک تابع به شکل $f(x) = b$ باشد، حداقل مقدار $ab$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:57:07', 5, 'done'),
(3598, ' تابع $f$ با ضابطه $f(x) = (ax+6)^2 - (3x+2a)^2$ مفروض است. اگر $g$ یک تابع خطی و $y = f(x) + g(x)$ ضابطه یک تابع همانی باشد، مقدار $g(a)$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:56:24', 5, 'done'),
(3599, ' تابع همانی $f$ و تابع $g$ با ضابطه $g(x) = x+|x|$ را در نظر بگیرید. ابتدا نمودار هر دو تابع را در راستای محور قائم یک واحد به بالا و سپس فقط تابع $g$ را در راستای محور $x$ یک واحد به سمت راست منتقل می‌کنیم. مساحت ناحیه محدود بین نمودارهای به‌دست‌آمده کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:54:54', 5, 'done'),
(3600, 'اگر $f$ یک تابع خطی و $2f(x) + f(-x) = 2x - 9$ باشد، مقدار $f(5)$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:51:56', 5, 'done'),
(3601, '. برد یک تابع خطی با دامنه $[-1, 2)$ به صورت $(0, 3]$ است. مقدار این تابع به ازای $x = 2 - \\sqrt{2}$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:50:43', 5, 'done'),
(3602, 'نمودار تابع $y = |x - a| + b$ را دو واحد به سمت راست و سپس یک واحد به پایین می‌بریم. ضابطه تابع جدید $y = |x - b| + 2a$ است. مقدار تابع جدید به ازای $x = 5$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-25 22:51:54', 1, '2026-02-25 23:27:05', 5, 'done'),
(3603, '1- هرگاه میانگین $6$ عدد طبیعی متوالی $2.5$ برابر دامنه تغییرات باشد، بزرگ‌ترین عدد، چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3604, '2- میانگین $5$ عدد برابر $9$ است. اگر یک عدد برابر به داده‌ها اضافه شود، میانگین جدید $12$ خواهد شد. مقدار یکی از اعداد جدید چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3605, '3- در $17$ داده آماری، میانگین داده‌های بیشتر از چارک سوم برابر $10$و میانگین داده‌های کمتر از چارک اول برابر $2$ است. اگر میانگین سایر داده‌ها همان میانگین کل باشد، میانگین کل چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3606, '4- واریانس $6$ داده آماری $4$ است. اگر $4$ داده برابر با میانگین داده‌ها به آن‌ها اضافه کنیم، واریانس ده داده چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3607, '5- اگر میانگین طول ضلع مربع‌هایی $25$ و میانگین مساحت مربع‌ها $627.25$ باشد، ضریب تغییرات طول ضلع مربع‌ها چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3608, '6- چه تعداد از متغیرهای زیر کمی از نوع پیوسته هستند؟\n\nتندی حرکت خودرو- رنگ چشم افراد- رتبه کنکور- نمره آخرین آزمون- گروه خونی افراد-دمای هوای داخل یک کلاس- مقیاس ارزیابی تحصیلی (ضعیف، خوب، عالی)- میزان تحصیلات یک فرد- مدت زمان پاسخگویی به سوالات امتحان', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3609, '7- اگر میانه داده‌های مقابل برابر $28$ باشد، آن‌گاه میانگین آن‌ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3610, '8- واریانس و ضریب تغییرات $20$ داده آماری به ترتیب $64$ و $0.4$ است. اگر داده‌های $15$ و $21$ را از میان داده‌ها حذف کرده و داده‌های $12$ و $24$ به آن‌ها اضافه کنیم، به واریانس داده‌های جدید چه مقدار اضافه می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3611, '9- اگر میانگین داده‌های $x_1+1,x_2+1,\\ldots,x_n+1$ برابر $11$ و واریانس داده‌های $x_1-3,x_2-3,\\ldots,x_n-3$ برابر $9$ باشد، ضریب تغییرات داده‌های 3x_1-1,3x_2-1,\\ldots,3x_n-1$ $کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3612, '10- اگر میانگین و انحراف معیار داده‌های $x_1,x_2,\\ldots,x_{10}$ به ترتیب $8$ و $1$ باشد، ضریب تغییرات داده‌های $$2_1+1,2x_2+1,\\ldots,2x_{10}+1 کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3613, '11- کلاس A با میانگین نمرات $10$ و کلاس B با میانگین نمرات $12$ پس از ادغام با هم در یک کلاس با میانگین $11.5$ قرار گرفته‌اند. جمعیت کلاس B چند برابر جمعیت کلاس A است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3614, '12- به هر یک از داده‌های $2,3,3,5,4,7,6$ سه برابر میانگین را اضافه کرده‌ایم، واریانس آن‌ها چقدر بیشتر شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3615, '13- واریانس اعداد $2,2,3,3,3$ واریانس اعداد $2,2,2,3,3$چقدر اختلاف دارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3616, '14- در داده‌های $10,19,13,16,4,8,3,6,2,9,7$میانگین داده‌های بیشتر از چارک سوم و میانگین داده‌های کمتر از چارک اول چقدر اختلاف دارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3617, '15- ده عدد با میانگین $\\bar{x}$ و واریانس $4$ داریم. چند عدد برابر با میانگین به آن‌ها اضافه کنیم تا واریانس داده‌ها به $2$ برسد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3618, '16- اگر ضریب تغییرات داده‌هایی $0.08$باشد به طوری که به هر کدام از آن‌ها $5$ واحد اضافه شود ضریب تغییرات $0.075$ خواهد شد. میانگین داده‌های اولیه چه عددی بوده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3619, '17- در یک گروه $36$ داده داریم، میانگین اعداد کمتر از چارک اول و بیشتر از چارک سوم به ترتیب اعداد $22$ و $30$ هستند. اگر میانگین تمام اعداد $27.5$باشد، میانگین بین چارک اول و چارک سوم چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3620, '18- اگر میانگین داده‌های مثبت $x_1, \\ldots, x_n$ برابر $\\bar{x}$ باشد، به هر یک از داده‌ها $k\\bar{x}$ اضافه کرده‌ایم، به طوری که ضریب تغییرات داده‌های جدید $\\frac{1}{9}$ ضریب تغییرات داده‌های اولیه شده است. عدد $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
(3621, '19- نوع کدام متغیر با دیگر گزینه‌ها فرق دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:23:40', 1, NULL, NULL, 'free'),
