(3639, '۱۰- نوع چند تا از متغیرهای زیر درست بیان شده است؟\n\nالف) کیفیت یک هلو (کیفی ترتیبی)\n\nج) دمای هوا در قله (کمی گسسته)\n\nب) اقوام ایرانی (کیفی اسمی)\n\nد) طول قد قوی‌ترین پلنگ جهان (کمی گسسته)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:29:07', 1, NULL, NULL, 'free'),
(3640, '۱۱- اگر میانگین داده‌های $6,5,b+1,a,4$برابر $4$ باشد، میانگین داده‌های $4,a^2,b^2,2ab$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:29:07', 1, NULL, NULL, 'free'),
