(3646, '۱۷- اگر واریانس دمای هوای شهری در یک هفته $25$ درجهٔ سانتی‌گراد به توان $2$ باشد، دمای این شهر در آن هفته چند درجهٔ فارنهایت به توان $2$ است؟ (راهنمایی $F = \\frac{۹}{۵}C + ۳۲$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:29:07', 1, NULL, NULL, 'free'),
(3647, '۱۸- سن سه دانش‌آموز امسال $14,15,16$ سال است. ضریب تغییرات سن آن‌ها $10$ سال دیگر تقریباً چقدر است؟ ($\\sqrt{\\frac{۲}{۳}} \\approx ۰/۸$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:29:07', 1, NULL, NULL, 'free'),
(3648, '۱۹- ۹ دادهٔ آماری را به صورت صعودی مرتب کرده‌ایم:\n\n$۲۴, x, ۴۸, ۵۳, ۲x - ۱, ۷۴, ۸۴, ۳x - ۶, ۹۳$\n\nاگر میانگین چارک اول و سوم نیم واحد بیشتر از چارک دوم باشد، میانهٔ داده‌ها چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:29:07', 1, NULL, NULL, 'free'),
