(3750, '66- تابع $f$ پیوسته است به طوری که $\\lim_{x\\to2}\\frac{f(x)-2}{x^2-4}=\\frac{3}{8}$، مقدار $\\lim_{h\\to0}\\frac{f(2+2h)-f(2)}{h}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3751, '67- در شکل مقابل، نمودار تابع $f(x)=x(x-a)$ و خط مماس بر آن رسم شده است. مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3752, '69- اگر $f(x)=\\frac{\\sqrt{1-\\cos x}}{\\sqrt{\\sin x+\\cos x}-\\sqrt{\\cos x-\\sin x}}$ باشد، حاصل $\\lim_{x\\to-\\infty}f(\\frac{1}{x})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3753, 'اگر $f(x)=\\frac{x^7-4}{x+2[\\frac{x}{x}]}$، حاصل $f\'_+(2)-f\'_-(2)$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3754, 'اگر تابع $f(x)=\\begin{cases}ax^3+\\frac{1}{\\sqrt{x}} & x \\ge 1 \\\\ \\sqrt{x}+\\frac{b}{x} & x < 1 \\end{cases}$ در $x=1$ مشتق‌پذیر باشد، مقدار $f\'(\\frac{a}{b})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3755, 'اگر تابع $f(x)=a-\\sqrt[3]{ax+2}$ در $x=-2$ دارای مماس قائم باشد، شیب خط مماس بر تابع در $x=-3$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3756, '75- تابع $f(x)=\\left[\\frac{4}{\\sqrt{x}+1}\\right]$ در بازه $(0,a)$ مشتق‌پذیر است. حداکثر مقدار $a$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3757, '77- اگر $f$ تابعی پیوسته باشد به طوری که $lim_{x→−1}\\frac{f^2(x+1)+1}{x^2+x−1}=4$، مشتق $f(x^2−2\\sqrt{x})$ به ازای $x=1$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3758, '79- نمودار سهمی $f$ و تابع خطی $g$ در شکل مقابل آورده شده است. مشتق $(f∘g)^2$ به ازای $x=2$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3759, '81- اگر $f(x)=1$, $g(x)=1$, $f\'(1)=3$, $g\'(1)=−9$، مشتق $(f+g)∘f$ به ازای $x=1$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3760, '۸۲- هرگاه $f(x)=2x^3+ax+b$ به طوری که تساوی $f\'of(x)=8x^3-12x-3$ برقرار باشد، مقدار $f\'of(2)$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3761, '۸۳- اگر $f$ و $g$ توابعی مشتق‌پذیر باشند به طوری که $g\'(x+\\frac{1}{\\sqrt{x}})=kf\'(x^2)$ و $g\'(3)=f(x+\\sqrt{x+1})$، مقدار $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3762, '۸۴- اگر $f(x)=\\frac{1}{3}x^3-2x^2+3x-5$ باشد، آنگاه به موازات کدام خط می‌توان بر نمودار تابع $f$ خطی مماس رسم کرد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3763, '۸۵- نمودار تابع $f(x)=\\frac{1}{x^n}$ در شکل مقابل رسم شده است. اگر $OH=4AM$، عدد طبیعی $n$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(3764, '۸۶- شکل مقابل، بخشی از نمودار $f$ است. شیب خط مماس بر نمودار تابع $y=xf(\\frac{r}{\\sqrt{x}})$ در $x=4$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3765, 'تابع $f(x)=x-\\sqrt{x}$ با دامنه $[1,9]$ داده شده است. خطی که نقاط ابتدا و انتهای نمودار تابع را به هم وصل می‌کند، به موازات مماس در نقطه‌ای به طول $\\alpha$ است، $f(\\alpha)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3766, 'هرگاه $f(x)=x^4-6x^2+4$ و $g(x)=2x^3+\\frac{1}{x}$ ، مقدار $f\'(3)$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3767, 'هرگاه $f(x)=\\frac{2x}{x+4}$ مقدار $\\alpha$ کدام باشد تا تساوی $f\'(\\alpha)=f\'(-\\alpha-4)$ برقرار شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3768, 'تابع $y=\\frac{\\sqrt{x}-\\sqrt{2x}}{x}$ در چند نقطه از $\\mathbb{R}$ مشتق‌پذیر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3769, '۹۳- تابع $f(x)=\\begin{cases}|x|-1 & x>1 \\\\ x^2+ax+b & x\\le1\\end{cases}$ در $\\mathbb{R}$ مشتق‌پذیر است. حاصل $a-b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3770, '۹۴- اگر $f(x)=\\frac{x^2+ax+b}{2x-[x]}$ و $f\'_+(1)-f\'_-(1)=3$ باشد، مقدار $b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3771, '96- اگر تابع $f$ در $x=4$ پیوسته و $\\lim_{x \\to 2}\\frac{f(x)-4}{x-2\\sqrt{x}}=\\frac{2}{3}$ و $g(x)=2x-\\sqrt{x+1}$ باشد، مشتق تابع $y=f\\circ g(x)$ در نقطه $x=3$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3772, '97- در شکل مقابل، نمودار تابع $y=\\sqrt{x+a}$ و خط $d$ مماس بر آن رسم شده است. به ازای کدام مقدار $a$، سه پاره‌خط $OA$ و $OB$ و $BC$ برابرند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3773, '98- اگر $f(x)=x^3-2x+2$ باشد، مشتق تابع $f\\circ f$ در $x=1$ چند برابر مشتق تابع $f\\circ f\'$ در $x=1$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3774, '۹۹- آهنگ تغییر متوسط تابع $f(x)=x^3-3x^2+2$ در بازه $[1,3]$ با آهنگ تغییر لحظه‌ای آن در نقاط $x=\\alpha$ و $x=\\beta$ برابر است. آهنگ تغییر لحظه‌ای $f$ در نقطه $\\alpha+\\beta$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3775, '۱۰۱- اگر $f(x)=\\begin{cases}\\sqrt{x}&x\\ge1\\\\ \\frac{۱}{x}&x<1\\end{cases}$ باشد، حاصل $\\lim_{h\\to0}\\frac{f(1)-f(1-h^2)}{h^2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3776, '۱۰۲- تابع $f(x)=a(x+1)(x-2)^2$ مفروض و $g(x)$ سهمی است. اگر مماس‌های $f$ و $g$ در $x=-1$ بر هم عمود باشند، $g\'(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3777, 'اگر $f(x)=k(x-3)(x-2)^2[-x]$ و $f\'_+(a)-f\'_-(a)=1$ باشد، مقدار $a+k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3778, 'با فرض $f(x)=\\frac{\\sqrt{(x-2)^3}+1}{x-1}$، حاصل $f\'(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3779, '111- در شکل زیر، نمودار تابع $f$ و خط مماس بر آن در $x=2$ رسم شده است. اگر $\\lim_{h\\to0}\\frac{f(2+h)-f(2)}{3h}=\\frac{1}{2}$ باشد، مقدار $f(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3780, '114- اگر $f(x)=x\\sqrt{3}+\\frac{8}{x}$ باشد، مقدار $f\'(2)$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3781, '115- اگر $f(x)=(x+2)\\sqrt[3]{x+2}$ باشد، مقدار $\\lim_{h\\to0}\\frac{f^{2}(h-1)+f(h-1)-2}{h(1-h^{2})}$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, NULL, NULL, 'free'),
(3782, 'خط مماس بر نمودار تابع $f(x) = \\frac{x-2}{\\sqrt{x}}$ در نقطه ای به طول ۱=x، نیمساز ناحیه دوم و چهارم را در نقطه M قطع می کند. فاصله M تا مبدأ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, '2026-02-26 11:59:09', 2, 'done'),
(3783, 'آهنگ تغییر متوسط لحظه ای تابع $f(x) = 2x - \\sqrt{x}$ در بازه [1,a] با آهنگ تغییر لحظه ای تابع در $x=a$ برابر است. مقدار $a$ کدام است؟', 3, 1, 49, 215, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:55:46', 1, '2026-02-26 11:58:17', 2, 'done'),
(3784, ' دامنه تعریف تابع $f(x) = \\sqrt{2 - \\log_2 (x-6)}$، شامل چند عدد صحیح است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:46:17', 4, 'done'),
(3785, '۲- نمودار تابع $f(x) = -a + 2^{ax-b}$ به صورت زیر است. مقدار $f(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3786, 'هرگاه $f(x) = x - [x]$ باشد، حاصل $f(\\log_2 24)$ با $f(\\log_2 n)$ برابر است، مقدار $n$ کدام است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:46:47', 4, 'done'),
(3787, 'حاصل ضرب ریشه‌های معادله $\\log_x 16 + 3 = \\log_2 x$، چند برابر حاصل جمع ریشه‌های آن است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:47:28', 4, 'done'),
(3788, ' هرگاه به بزرگی زلزله‌ای $2$ واحد اضافه کنیم، انرژی آزاد شده آن چند برابر خواهد شد؟', 2, 1, 63, 258, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:47:58', 4, 'done'),
(3789, 'هرگاه $n$ گرم نمک را به مقدار معینی آب اضافه کنیم، مقدار نمک حل نشده در آب بعد از $t$ دقیقه، از رابطه $f(t) = n(0.8)^t$ بدست می‌آید. حداقل پس از چند دقیقه، مقدار نمک حل نشده کمتر یا برابر $20$ درصد مقدار نمک اولیه است؟ ($\\log 2 \\simeq 0.3$)', 2, 1, 63, 258, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:48:27', 4, 'done'),
(3790, ' اگر $\\log_{ba} a = 2$، مقدار $\\log_b a$ کدام است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:48:59', 4, 'done'),
(3791, ' اگر یکی از ریشه‌های معادله $2\\log_x a + 3\\log_a \\sqrt{x} = 4$ برابر $4$ باشد، مقدار $\\log_{\\sqrt{2}} a$ کدام است؟', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:49:34', 4, 'done'),
(3792, 'جواب معادله $3^{1+2x} = 4^{1-x}$ به صورت $\\log_6 \\alpha$ است. مقدار $\\alpha$ کدام است؟', 2, 1, 63, 253, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:50:05', 4, 'done'),
(3793, '۱۰- نمودار تابع $f(x) = a + b(2^{1-x})$ به شکل مقابل است. ضابطه $f^{-1}(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3794, ' تابع $f(x) = 2^{ax+b}$ از نقطه $(1, \\frac{1}{2})$ عبور می‌کند. اگر $f^{-1}(8) = 5$ باشد، حاصل $a-b$ چقدر است؟', 2, 1, 63, 251, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:52:23', 4, 'done'),
(3795, ' دامنه تابع با ضابطه $f(x) = \\log_4 (|x^2 - 2| - x)$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, '2026-03-29 20:50:59', 4, 'done'),
(3796, '۱۳- اگر $\\log_2 3 = a$ و $\\log_8 b = \\frac{2}{3}(1+a)$ باشد، مقدار $\\log(3b-8)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3797, '۱۴- اگر $(\\frac{125}{8})^{x^2} = (0.4)^{2x-1}$ باشد، $\\log_8 (9x+1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3798, '۱۵- شکل زیر، نمودار تابع $y = -1 + \\log_b (2x+a)$ است. این منحنی خط $y=1$ را با کدام طول قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3799, '۱۶- تابع $y = 2^{x+|x|}$ را $3$ واحد در امتداد محور $x$ها در جهت منفی و سپس در امتداد محور $y$ها $2$ واحد در جهت منفی انتقال می‌دهیم. منحنی حاصل، محور $x$ها را با کدام طول قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3800, '۱۷- اگر در معادله $2\\log_x a + \\log_a \\sqrt{x} = 2$، مقدار $x$ برابر $9$ باشد، مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3801, '۱۸- توابع $f(x) = 3 - 2^{x+1}$ و $g(x) = \\frac{5 - 2^{2x+1}}{3}$ در نقاطی به طول $\\alpha$ و $\\beta$ متقاطع هستند. مقدار $f(\\alpha) + g(\\beta)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3802, '۱۹- اگر $\\log_{ab} ac = 2$ و $\\log_c ac = 3$، مقدار $\\log_c b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3803, '۲۰- هرگاه $2\\log \\frac{x-y}{2} = \\log x + \\log y$، مقدار $\\frac{x}{y} + \\frac{y}{x}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3804, '۲۱- هرگاه $9\\sqrt{3} = 27^{1-3x}$، مقدار لگاریتم $72x+4$ در کدام پایه برابر $2$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3805, '۲۲- به ازای کدام مقدار $a$، عدد $x=3$ در معادله $\\log_a (3x+7) = 1 + \\log_a (x-1)$ صدق می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3806, '۲۳- هرگاه لگاریتم $2\\sqrt[3]{16}$ در پایه $4\\sqrt{2}$ برابر $a$ باشد، لگاریتم $15a+2$ در پایه $\\sqrt[4]{2}$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3807, '۲۴- نمودار تابع $f(x) = a - \\log_2 (b-3x)$ شکل روبه‌رو است. مقدار $\\log_a (b+2)$ چه عددی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3808, '۲۵- اگر $\\alpha$ جواب معادله $2(\\log_3 x)(\\log_{12} x) = \\log_3 x + \\log_{12} x$ باشد، مقدار $\\log_2 (2\\alpha+4)$ چه عددی است؟ ($\\log x \\neq 0$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3809, '۲۶- هرگاه $f(x) = \\log_2 (8-2^x)$ به طوری که $f^{-1}(x) = \\log_2 (a-b^x)$، مقدار $ab$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3810, '۲۷- $24$ گرم از عنصری در اختیار داریم، به طوری که هر $15$ روز $\\frac{1}{20}$ جرم باقی مانده را از دست می‌دهد. پس از طی تقریباً چند روز فقط $6$ گرم از عنصر باقی خواهد ماند؟ ($\\log 19 \\simeq 1.278 , \\log 2 \\simeq 0.3$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3811, '۲۸- اگر $3\\log c = 4\\log b = 6\\log a$ باشد، مقدار $\\log_{ab} c$ کدام است؟ (تمامی لگاریتم‌ها تعریف شده هستند)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3812, '۲۹- جواب معادله $\\log_3 (\\frac{8 - \\log_5 x}{\\log_5 x}) = 1$ ($x>0$) چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3813, '۳۰- اگر مجموع جواب‌های معادله $a^x + 27a^{-x} - 12 = 0$ برابر $-3$ باشد، مقدار $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3814, '۳۱- اگر $\\log_{24} 3 = a$ و $\\log_{24} 4 = b$ باشد، حاصل $\\log_{24} 8$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3815, '۳۲- از تساوی $3^{x+1} = 12^{x-1}$ مقدار $2^{1-x} + \\frac{1}{2^{1-x}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3816, '۳۳- اگر $\\log 3 = a$ و $\\log 7 = b$ باشد، جواب معادله $3^{x+2} = 7^x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3817, '۳۴- اگر $\\log_6 5 = a$ و $\\log_3 2 = b$ باشند، مقدار $\\log_3 5$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3818, '۳۵- حاصل عبارت $\\frac{1}{\\log_{(\\sqrt{3}-1)} 4} + \\frac{1}{\\log_{(\\sqrt{3}+1)} 4}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 11:59:00', 1, NULL, NULL, 'free'),
(3819, '۶۹- اگر $\\sin x + 2\\cos x = 1$ باشد، مقدار $\\tan x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:48', 1, NULL, NULL, 'free'),
(3820, '۷۰- نقاط $A$ و $B$ به ترتیب در نواحی دوم و چهارم روی دایره مثلثاتی قرار دارند. اگر $\\sin A = \\frac{1}{3}$ و $\\cos B = \\frac{\\sqrt{2}}{3}$ باشد، طول پاره‌خط $AB$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3821, '۷۱- قسمتی از نمودار تابع $f(x) = \\frac{\\sin 2x - \\cos x}{\\cos x}$ در شکل زیر رسم شده است. شیب خط گذرنده از دو نقطه $A$ و $B$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3822, '۷۲- در شکل زیر، نمودار تابع $f(x) = a \\tan(\\frac{b\\pi}{3} x)$ رسم شده است. مقادیر $b$ و $a$ کدام می‌توانند باشند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3823, '۷۳- دامنه تابع $f(x) = \\frac{\\tan(\\frac{\\pi + \\pi x}{2})}{\\sqrt{16 - x^2}}$ شامل $n$ بازه به طول‌های مساوی $a$ است. اگر تابع $g(x) = a \\tan nx$ روی بازه $(0, C)$ اکیداً صعودی باشد، حداکثر مقدار $C$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3824, '۷۴- اگر $\\sin x - \\cos x = \\frac{\\sqrt{3}}{2}$ باشد، آن‌گاه مقدار $\\cos 8x$ چقدر از $\\frac{1}{2}$ بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3825, '۷۵- اگر $f(x) = -1 + \\sin^2 x$ و $g(x) = x^2 + x$ باشد، حاصل $(g \\circ f)(\\frac{\\pi}{16})$ را به صورت $\\frac{-1}{a} + \\frac{\\sqrt{2}}{b}$ نوشته‌ایم. نمودار تابع $h(x) = -4 + b \\cos ax$ در بازه $(0, 2\\pi)$ چند بار از حالت نزولی به صعودی، تغییر یکنوایی می‌دهد؟ ($a, b \\in \\mathbb{Z}$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3826, '۷۶- از معادله $\\cos 3x + \\sin x = 0$ مجموع جواب‌ها در فاصله $(0, 3\\pi)$ چند برابر $\\pi$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3827, '۷۷- مجموع جواب‌های معادله $\\frac{1}{\\sin 2x} - \\frac{1}{\\cos 4x} = 0$ در بازه $[0, \\pi]$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3828, '۷۸- طول پاره‌خطی که امتداد جواب‌های معادله مثلثاتی $\\tan^2 x + 6\\cot^2 x = 5$ روی نیمه بالایی محور $\\tan$ها در دایره مثلثاتی ایجاد می‌کند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3829, '۷۹- اگر $x = 2k\\pi - \\frac{3\\pi}{2}$ یک دسته از جواب‌های معادله $3\\sin x + \\cos 2x = a$ باشد، مساحت شکل حاصل از وصل کردن تمام جواب‌های این معادله در دایره مثلثاتی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3830, '۸۰- دو ناظر $A$ و $B$ یک برج $112$ متری را به ترتیب با زاویه‌های $40^\\circ$ و $80^\\circ$ نسبت به افق مشاهده می‌کنند؛ به‌طوری‌که بار اول، هر دو در یک طرف برج و بار دیگر یکی در یک طرف و دیگری در طرف دیگر قرار دارد. نسبت فاصله‌های $A$ و $B$ (از یکدیگر) در این دو وضعیت کدام است؟ (فرض: $\\tan 80^\\circ = 5.6 , \\tan 40^\\circ = 0.8$ و از قد افراد صرف نظر کنید.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3831, '۸۱- اگر $\\cot x = \\frac{m+1}{m}$ و $\\sin x = \\frac{m}{m+2}$ باشد، چند مقدار قابل قبول و غیرصفر برای $m$ به‌دست می‌آید؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3832, '۸۲- اگر $\\tan 37^\\circ = \\frac{3}{4}$ باشد، حاصل عبارت $\\frac{\\sin 1027^\\circ + \\tan 577^\\circ - \\sin 1673^\\circ}{\\tan^2(-953^\\circ) - \\cos(-847^\\circ)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3833, '۸۳- حاصل عبارت $A = \\frac{\\cos 2x}{\\tan x + \\cot x}$ به ازای $x = \\frac{\\pi}{32}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3834, '۸۴- شکل زیر نمودار تابع $y = a|\\sin(b\\pi x) - c|$ را در یک دوره تناوب آن نشان می‌دهد. در صورتی‌که $b > 0$ و $0 < c < 1$ باشد، حاصل $ac + b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3835, '۸۵- اگر شکل زیر نمودار تابع $y = 1 - 2(\\sin \\frac{\\pi}{2}x - \\cos \\frac{\\pi}{2}x)^2$ باشد، مساحت حاصل از رسم مثلث $ABC$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3836, '۸۶- معادله مثلثاتی $\\cos(\\pi \\sin(4\\pi x)) = \\frac{1}{2}$ در بازه $[0, \\frac{3}{2}]$ چند جواب دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, NULL, NULL, 'free'),
(3837, 'جواب کلی معادله‌ی مثلثاتی $\\sin^4 x - \\cos^4 x = \\sin^2 \\frac{5\\pi}{4}$، به کدام صورت است؟', 3, 1, 47, 207, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, '2026-02-26 12:08:47', 2, 'done'),
(3838, 'مجموع جواب‌های معادله مثلثاتی $3\\sin^2 2x - 8\\cos^2 x + 1 = 0$ در بازه $[0, 2\\pi]$ کدام است؟', 3, 1, 47, 207, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:01:49', 1, '2026-02-26 12:04:49', 2, 'done'),
(3839, '۱ - اگر $f(3) = -g(3) = 2$ و $f\'(3) = 2g\'(3) = -1$ باشند، آن‌گاه حاصل $(\\frac{2f + 3g}{g})\'(3)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3840, '۲ - در تابع با ضابطه $f(x) = \\frac{16}{x^2}$ آهنگ متوسط تابع از $x_1 = 2$ تا $x_2 = 4$ چقدر از آهنگ لحظه‌ای آن تابع در $x = \\sqrt[3]{8}$ بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3841, '۳ - اگر $f(x^3 + 5x) = x^8 + x^4 - 1$ باشد، حاصل $f\'(6)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3842, '۴ - در جدول مقابل بعضی از مقادیر تابع $f$ آمده است. نمودار تابع $f$ در بازه $[2, 6]$ به‌صورت کدام گزینه می‌تواند باشد؟\n\n| $x$ | $2$ | $3$ | $4$ | $5$ | $6$ |\n\n|---|---|---|---|---|---|\n\n| $f(x)$ | $12$ | $20$ | $26$ | $30$ | $32$ |', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3843, '۵ - اگر $f(x^2 - x) = (f \\circ g)(x^3)$، $g(1) = 0$ و $f\'(0) \\neq 0$ باشد، آن‌گاه شیب خط مماس بر $g$ در نقطه‌ای به طول یک کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3844, '۶ - اگر معادله خط مماس بر منحنی $f(x)$ در نقطه‌ای به طول $x = -1$ واقع بر آن، $y = 3x + 4$ باشد، آن‌گاه عرض از مبدأ خط مماس بر منحنی $g(x) = f(17 - 2x^2)$ در نقطه به طول $x = 3$ روی آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3845, '۷- اگر $f(x) = (x[x]|x| + 1)^2$، حاصل $\\lim_{h \\to 0^+} \\frac{f(-2+h) - f(-2)}{h}$ کدام است؟ ($[\\ ]$ : نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3846, '۸ - اگر $f(x) = \\frac{x}{\\sqrt{4 - x^2}}$ و $g(x) = \\frac{2x}{\\sqrt{1 + x^2}}$، تابع $y = f\'(g(x)).g\'(x)$ در دامنه‌اش چگونه تابعی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3847, '۹ - در تابع $f(x) = \\begin{cases} |x^2 - 3| & , x \\le 0 \\\\ \\sqrt[3]{x} + 2 & , x > 0 \\end{cases}$ چند نقطه عضو دامنه تابع مشتق نیستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3848, '۱۰- در شکل زیر نمودار توابع چندجمله‌ای $f$ و $g$ داده شده است. اگر $h(x) = \\frac{f(2x-1)}{g(x^2-x)}$ باشد، حاصل $h\'(3)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3849, '۱۱- اگر تابع $f(x) = (x^2 + x - 2)|x^2 + 2x - 3|$ در نقطه $x = m$ مشتق‌ناپذیر باشد، حاصل $\\frac{f\'_+(m)}{f\'_-(m)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3850, '۱۲- تابع با ضابطه $f(x) = [\\frac{x-1}{x^2-x}]$ در کدام بازه مشتق‌پذیر است؟ ($[\\ ]$: نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3851, '۱۳- اگر $f(x) = \\sqrt{2x - 3} + \\sqrt{6 - x}$ و $g(x) = \\sqrt{2x - 3} - \\sqrt{6 - x}$ باشد، آن‌گاه حاصل $f\'g + g\'f$ به ازای $x = 2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3852, '۱۴- اگر $f(x) = |x^2 - 2x|$ باشد، نمودار توابع $f$ و $f\'$ در چند نقطه متقاطع‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3853, '۱۵- اگر $f(x) = \\frac{12x}{\\sqrt{7x+2} + \\sqrt{x+2}}$ و $g(x) = x^3 + 3x - 2$ باشد، خط مماس بر تابع $fog$ در نقطه‌ای به طول ۱ واقع بر آن، محور عرض‌ها را با کدام عرض قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3854, '۱۶- تابع $f(x) = |x^3 - 1|$ در $x = a$ مشتق‌ناپذیر و در $x = b$ دارای مشتق صفر است. مساحت ناحیه محدود به نیم‌خط‌های مماس راست و چپ در $x = a$ و خط مماس در $x = b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3855, '۱۷ - نمودار تابع $f$ به شکل مقابل است. کدام تابع در $x = 0$ مشتق‌پذیر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3856, '۱۸- اگر $f$ تابع درجه دوم و $g(x) = \\begin{cases} f(x) & , x \\ge 1 \\\\ f\'(x) & , x < 1 \\end{cases}$ مشتق‌پذیر باشد، کدام درست است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3857, '۱۹- مشتق تابع $y = \\sqrt[3]{\\frac{\\sqrt{x} + x + 2}{-x + 5}}$ به ازای $x = 4$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3858, '۲۰ - فرض کنید $f(x) = 2 + \\sqrt{x+1}$، مقدار مشتق تابع $f\'of^{-1}$ در نقطه $x = 3$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3859, '۲۱ - شکل زیر نمودار تابع $y = f(x)$ است. اگر $g(x) = \\frac{(x-4)f(x)}{[-x]}$ باشد، $g\'_+(-2) - g\'_-(-2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3860, '۲۲ - تابع با ضابطه $f(x) = \\begin{cases} x^2 - \\sqrt{4x+m} & , x \\ge 0 \\\\ x + \\frac{n}{x-1} & , x < 0 \\end{cases}$ بر روی مجموعه اعداد حقیقی مشتق‌پذیر است. حاصل $\\frac{m}{n}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3861, '۲۳ - اگر تابع $f(x) = (3x^2 - ax + 1)|x^2 - x^3|$ در تمام نقاط مشتق‌پذیر باشد، $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3862, '۲۴ - اگر $f(x) = \\begin{cases} 3x + 1 & x \\ge 1 \\\\ x^2 + x + 2 & x < 1 \\end{cases}$ باشد، آنگاه مشتق تابع $\\frac{fof(x)}{f(x) + 1}$ در نقطه $x = 1$، برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3863, '۲۵ - اگر $f(x) = \\frac{x-1}{x-2}$ و مقدار $(gof)\'(3)$ برابر ۶ باشد، مقدار $(fog)\'(2)$ کدام است؟ (تابع $g$ همواره مشتق‌پذیر است و $g(2) = -1$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3864, '۲۶ - نمودار تابع $g$ به صورت زیر است. اگر $f(x) = x^3 \\times g^2(3-x)$، مقدار $f\'(1)$ برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3865, '۲۷ - اگر $f(x) = \\frac{2x-5}{x^2-5x+4}$ باشد، آنگاه حاصل $f\'\'(5)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3866, '۲۸ - آهنگ متوسط تغییر تابع $f(x) = \\sqrt{2x^2-2}$ نسبت به متغیر $x$ روی بازه $[1, 3]$، چند برابر آهنگ لحظه‌ای تابع در $x = 4$ می‌باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3867, '۲۹ - اگر $f(x) = \\begin{cases} x^3 - 3x^2 & , x < 1 \\\\ a + \\frac{b}{x} & , x \\ge 1 \\end{cases}$ بر $\\mathbb{R}$ مشتق‌پذیر باشد، خط مماس بر آن در $x = 2$، محور عرض‌ها را با کدام عرض قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3868, '۳۰ - اگر $f(x) = (\\frac{x}{[x]} + 1)^3$ باشد، آنگاه حاصل $\\lim_{h \\to 0^+} \\frac{f(2+h)-f(2)}{h}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3869, '۳۱ - چند خط موازی محورهای مختصات بر $f(x) = \\sqrt[3]{x^2 - 4x - 5}$ مماس می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3870, '۳۲ - اگر $f(x) = \\frac{x}{x^3 + x^2 + 2}$ باشد، آنگاه حاصل $\\frac{f\'(2)}{f^2(2)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3871, '۳۳ - برای تابع مشتق‌پذیر $f$، اگر $\\lim_{x \\to -1} \\frac{4x+4}{f(x)-4} = 2$ باشد، آنگاه مشتق تابع $y = x^2 f(\\frac{1}{x})$ در $x = -1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3872, '۳۴ - اگر $f(4) = 2$، $f\'(4) = 3$ و $g(x) = f(2f(x^2))$ باشد، مقدار $g\'(2)$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3873, '۳۵ - اگر $f(x) = \\begin{cases} \\sqrt{x+2} & ; x \\ge -2 \\\\ -\\sqrt{-x-2} & ; x < -2 \\end{cases}$ باشد، نمودار تابع $y = f^{-1}(x)$ در $x = 0$ چه وضعیتی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3874, '۳۶ - خط $8y - 5x = 16$ نمودار تابع $f(x) = \\sqrt{5x+1}$ را در دو نقطه $x_1$ و $x_2$ قطع می‌کند. آهنگ تغییر متوسط $f$ در فاصله $[x_1, x_2]$ با آهنگ لحظه‌ای آن در نقطه‌ای با کدام طول برابر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3875, '۳۷- نمودار تابع $g(x)$ به صورت مقابل است. اگر $f(x) = \\frac{2x^2 - 18}{x + g(x)}$ و $f\'(3) = \\frac{4}{3}$ باشد، مقدار $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3876, '۳۸- مطابق شکل خط $d$ در نقطه $x = 2$ بر نمودار تابع $f$ مماس است. حاصل $\\lim_{x \\to 0} \\frac{f(2+3x) - 3}{x}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3877, '۳۹- برای تابع $f$ در شکل زیر داریم: $f(4) = 25$ و $f\'(4) = 1/5$. با توجه به شکل، مقدار $f(5)$ کدام گزینه می‌تواند باشد؟ (خط بر تابع $f$ در نقطه $A$ مماس است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3878, '۴۰ - به ازای چند مقدار صحیح $k$، تابع $f(x) = |x^2 - (2k+1)x + k + 5|$ در تمام نقاط دامنه، مشتق‌پذیر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3879, '۴۱ - در تابع $f(x) = \\begin{cases} 2x^2 + 3 & , x \\ge 1 \\\\ 5x & , x < 1 \\end{cases}$ حاصل $\\lim_{\\Delta x \\to 0^-} \\frac{f(1+\\Delta x) - f(1-\\Delta x)}{\\Delta x}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3880, '۴۲ - اختلاف مشتق چپ و راست تابع $y = x|x-2|$ در نقطه مشتق‌ناپذیر آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3881, '۴۳ - تابع با ضابطه $f(x) = ||x| + |x-2| - 3|$ در چند نقطه از $\\mathbb{R}$ مشتق‌ناپذیر بوده و مشتق راست از مشتق چپ کم‌تر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3882, '۴۴ - خط مماس بر تابع $f(x) = 2x^3 - 9x^2 + 12x + 6$ در محل برخورد آن با محور $y$ها، نمودار تابع را در یک نقطه دیگر با کدام عرض قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3883, '۴۵ - ضابطه تابع $f$ با دامنه $\\mathbb{R} - \\{\\pm 1\\}$ به‌صورت $f(x) = x^2 f(x) + x - 3$ مفروض است. مقدار $f\'(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3884, '۴۶ - اگر $f(x) = \\frac{2x^2\\sqrt{-x}}{2x^2+x}$ آنگاه حاصل $\\lim_{x \\to -1} \\frac{f(x) - 2}{3(x+1)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3885, '۴۷ - در نقاط $x = \\alpha$ و $x = \\beta$ بر روی منحنی تابع $f(x) = x^2 + 1$ مماس‌هایی بر آن رسم می‌کنیم. اگر این دو مماس برهم عمود باشند، آن‌گاه عرض محل برخورد این دو خط کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3886, '۴۸ - شکل زیر، بخشی از نمودار توابع $f$ و $g(x) = \\frac{5x-1}{x+1}$ است. اگر $m = (f \\circ g)\'(1)$، حاصل $\\lim_{h \\to 0} \\frac{f(2+2h) - f(2+mh)}{3h^2 - h}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3887, '۴۹- مشتق تابع با ضابطه $f(x) = (\\sqrt{\\frac{3x^2+2x}{x+1}})^3$ در نقطه $x=1$ تقریباً کدام است؟ $(\\sqrt{2/5} = 1/58)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3888, '۵۰- تعداد نقاط مشتق‌ناپذیری تابع $f(x) = |x^4 - |x||$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3889, '۵۱- در تابع با ضابطه $f(x) = \\begin{cases} x - \\frac{1}{x} & , x \\ge 1 \\\\ x^2 + ax + b & , x < 1 \\end{cases}$، مقدار $f\'(1)$ موجود است. $f(1-\\sqrt{2})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3890, '۵۲- چند خط موازی محورهای مختصات بر $f(x) = \\sqrt[3]{x^2-4x-5}$ مماس می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3891, '۵۳- با در نظر گرفتن تابع $f(x) = |2x^2+3x-2| [\\frac{6}{x+4}]$، حاصل $\\lim_{h \\to 0} \\frac{f(-2+3|h|) - f(-2-4|h|)}{2|h|}$ کدام است؟ ([ ] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3892, '۵۴- با توجه به نمودار تابع $f(x) = \\sqrt{x}$ فاصله دو خط موازی زیر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3893, '۵۵- اگر $f(x) = \\sqrt{x-1}$ و $g(x) = \\frac{1}{x^2+1}$ باشد، حاصل $f\'(2) \\times g\'(f(2))$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3894, '۵۶- اگر $k f(3x+4) = g(x^2-3x+1)$، $f\'(1) = -1$ و $g\'(5) = 6$ باشد، مقدار $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3895, '۵۷- مقدار مشتق تابع $y = \\frac{\\sqrt[3]{(x^2+7x)^2}}{\\sqrt{x}+1}$ به ازای $x=1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3896, '۵۸- اگر نمودار دو تابع $f$ و $g$ به‌صورت زیر باشند و $r(x) = f(g(x))$، آنگاه $r\'(4)$ برابر است با:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3897, '۵۹- متحرکی با معادله مکان - زمان به صورت $S(t) = -4t^2 + 12t + 1$ مفروض است. در لحظه‌ای که سرعت متحرک ۲ برابر قرینه سرعتش در لحظه $t=0$ است، مکان متحرک چقدر با مکان اولیه (در $t=0$) فاصله دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3898, '۶۰- اگر خط مماس بر منحنی $y = f(x)$ در نقطه‌ای به طول $k$ واقع بر آن، عمود بر خط به معادله $\\frac{y-1}{3} + \\frac{2x+1}{4} = -1$ باشد، حاصل $\\lim_{h \\to 0} \\frac{f(k+4h)-f(k)}{3h}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3899, '۶۱- تابع $f(x) = \\begin{cases} \\frac{|2x^2-6x+4|}{x-3} & , x > -1 \\\\ [x-1]\\sqrt[3]{x+2} & , -3 < x \\le -1 \\end{cases}$ در چند نقطه روی بازه $(-3, +\\infty)$ مشتق‌پذیر نیست؟ ([ ] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3900, '۶۲- در تابع $f(x) = \\begin{cases} \\sqrt[3]{x+7} & , x \\ge 1 \\\\ \\frac{[x+1]}{2x-\\frac{3}{2}} & , x < 1 \\end{cases}$، حاصل $\\lim_{h \\to 0^-} \\frac{f(1-h)-f(1+h)}{5h}$ کدام است؟ ([ ] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3901, '۶۳- در تابع $f(x) = [\\frac{3x}{2}] \\sqrt{(2x-4)^2 + x^2 - 4x + 4}$، $f\'_-(2)$ چند برابر $\\sqrt{5}$ است؟ ([ ] نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3902, '۶۴- اگر $g(x) = x^2f(x)+2$ و $g\'(1) = f(1)+1 = 5$ باشد، آن‌گاه مشتق تابع $\\frac{g(x)}{f(x)}$ در $x=1$ برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3903, '۶۵- اگر $f(x) = \\sqrt{2x+3}$ آن‌گاه مشتق تابع $f(xf(x))$ در نقطه $x=1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3904, '۶۶- در تابع $f(x) = \\frac{2x-3}{5x+1}$، حاصل عبارت $1 - \\frac{f.f\'\'}{(f\')^2}$ به ازای $x=1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3905, '۶۷- نقطه $A$ به طول $1$ و نقطه $B$ به طول $a$ واقع بر نمودار $y=x^3$ مفروض‌اند. به ازای چند مقدار $a$، آهنگ متوسط تابع $f(x)=x^3$ در بازه ($1$ و $a$)، چهار برابر آهنگ لحظه‌ای این تابع در نقطه وسط این بازه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3906, '۶۸- در نمودار زیر، خطوط مماس در نقاط $A$ و $B$ به ترتیب موازی خط (a-1)y + 2ax - 1 = 0$$ و نیمساز ربع دوم مختصات می‌باشند. حدود $a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
(3907, '۶۹- نمودار تابع $y=f(x)$ به‌صورت مقابل است. اگر $g(x) = \\frac{5x^2-20}{\\sqrt{x+7}} f(x)$ باشد، مقدار $g\'(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, NULL, NULL, 'free'),
