(3909, 'تابع $f(x) = (x-8)^2([\\frac{x}{2}] - [\\frac{x}{3}])$ در بازه $(0,10)$ در چند نقطه به طول صحیح مشتق‌پذیر است؟ ($[\\ ]$: نماد جزء صحیح است.)', 3, 1, 49, 214, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, '2026-02-26 12:18:48', 2, 'done'),
(3910, 'اگر تابع $f$ در $x=a$ پیوسته باشد و $f\'_+(a) = -\\infty$ و $f\'_-(a) = +\\infty$، آن‌گاه نمودار تابع $y = \\frac{1}{f(x)}$ در همسایگی $x=a$ کدام است؟ ($f(a) \\ne 0$)', 3, 1, 49, 214, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:08:03', 1, '2026-02-26 12:18:14', 2, 'done'),
