(3943, 'در شکل زیر فاصله‌ی رأس $B$ در مربع $ABCD$ تا مبدأ مختصات $10$ است. مساحت مربع کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:42:05', 2, 'done'),
(3944, 'مرکز دایره‌ گذرا بر دو نقطه $A(1,1)$ و $B(4,-2)$ و خط $y=2x$ واقع است. مساحت دایره کدام است؟', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:41:14', 2, 'done'),
(3945, 'دایره‌ای به مرکز $(-1,-1)$ و معادله‌ی گسترده‌ی آن $x^2+y^2+ax+bX+c=0$ با دایره‌ی $x^2+y^2-4x-6y-3=0$ مماس درون آن باشد، مقدار $a+b+c$ کدام است؟', 3, 1, 56, 235, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:37:07', 2, 'done'),
(3946, 'نقطه‌ی $M$ روی یک بیضی که با کانون‌های $F$ و $F\'$ قرار دارد. اگر محیط مثلث $MFF\'$ برابر $32$ و مجموع فواصلF  از دو نقطه‌ی انتهایی قطر کوچک $20$ باشد، مقدار خروج از مرکز بیضی چقدر با اندازه قطر کوچک بیضی تفاوت دارد ؟', 3, 1, 56, 233, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:37:33', 2, 'done'),
(3947, 'دو خط به معادلات‌ $y=\\sqrt{3}x+a$ و $y+\\sqrt{3}x=b$ مطابق شکل زیر متقاطعند. اگر فاصله‌ی نقطه $M$ به طول یک واقع بر محور Xها، از این دو خط به ترتیب برابربا $2$ واحد و $3$ واحد باشد، $a+b$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:27:22', 2, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(3948, 'نقطه‌ی $M$ روی بیضی به کانون‌های $F$ و $F\'$ قرار دارد. اگر محیط مثلث $MFF\'$ برابر $32$ و مقدار خروج از مرکز بیضی $0.6$ باشد، اندازه‌ی قطر کوچک بیضی چند است؟', 3, 1, 56, 233, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:24:46', 2, 'done'),
(3949, 'مجموع مساحت دو دایره‌ای که در ناحیه‌ی اول دستگاه مختصات بر محورهای مختصات و خط $$3x+4y=24 مماس هستند، کدام است؟  $\\pi$) را برابر $3$ فرض کنید', 3, 1, 56, 234, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, '2026-02-26 12:23:40', 2, 'done'),
(3950, '36در شکل زیر، قسمتی از دو دایره درون یک مثلث قائم‌الزاویه قرار گرفته است. به‌ازای کدام مقدار $m$، خط غیرافقی $y=mx+10$ بر دایره هاشور خورده، مماس است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 12:20:10', 1, NULL, NULL, 'free'),
(3951, '۱- اگر $A=(-\\infty,-2]$ و $B=[-3,5)$ و مجموعهٔ مرجع برابر کل اعداد حقیقی باشد، آنگاه حاصل $A\'\\cap B\'$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3952, '۲- در یک دنبالهٔ حسابی جملهٔ هفتم برابر صفر است. جملهٔ دوازدهم این دنباله چند برابر جملهٔ پنجم آن است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3953, '۳- مجموع سه عدد که تشکیل دنبالهٔ هندسی می‌دهند برابر $105$ و حاصل‌ضرب آن‌ها برابر $27$ است. بزرگ‌ترین عدد در این سه عدد چند برابر کوچک‌ترین آن‌ها است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3954, '۴- در هر کدام از اشکال زیر طول هر کدام از پاره‌خط‌های کوچک برابر یک است. مطابق این الگو، مساحت ناحیهٔ سایه‌زده در شکل مرحلهٔ چهارم کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3955, '۵- اگر $A$ مجموعه‌ای متناهی و $B$ مجموعه‌ای نامتناهی باشد، کدام مجموعه حتماً نامتناهی است؟ (مجموعهٔ مرجع را مجموعهٔ اعداد حسابی در نظر بگیرید.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3956, '۶- اگر $A=[-2,0)$ و $B=(-1,4]$ باشد، آنگاه مجموعهٔ $(A-B)\\cup(B-A)$ شامل چند عدد صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3957, '۷- با توجه به الگوی زیر، برای $72$ کاشی تیره، چند کاشی سفید لازم است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3958, '8- اگر  $A=\\{x\\mid -4<3x-1\\le 5\\}$  و  $B=\\{x\\mid -x\\in A\\}$  آنگاه حاصل  $A-B$  کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3959, '۹- اگر $t_n=(3a-6)n^2+(a+4)n+a+3$ یک الگوی خطی باشد، جملهٔ نهم آن از جملهٔ پنجم آن چقدر بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3960, '۱۰- بین دو عدد $4$ و $324$ عدد مثبت چنان درج شده است که پنج عدد حاصل تشکیل یک دنبالهٔ هندسی داده‌اند. مجموع این سه عدد کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3961, '۱۱- در یک دنبالهٔ حسابی غیرثابت، جملات اول، هفتم و شصت‌ویکم، جملات متوالی یک دنبالهٔ هندسی هستند. جملهٔ نهم دنبالهٔ حسابی چند برابر دوم آن است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3962, '۱۲- در هر یک از شکل‌های زیر، مربع‌های کوچک به ابعاد $۱×۱$ است. تعداد مربع‌های سفید در شکل دهم، $۱۲۰$ تا است. تعداد مربع‌های کوچک سفید در شکل دوازدهم، چند تا است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3963, '۱۳- مجموعه‌های $A=\\{x\\in\\mathbb{R}\\mid -۵\\le x\\le r\\}$، $B=\\{x\\in\\mathbb{R}\\mid -۱<x\\le y\\}$ و $C=(۴,+\\infty)$ و $A\\cap(B-C)$ مفروض‌اند. مجموعهٔ $A\\cap(B-C)$ شامل چند عدد است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3964, '۱۴- در یک دنبالهٔ حسابی، مجموع سه جملهٔ اول $۳$ و مجموع سه جملهٔ بعدی $۳۹$ است. حاصل‌ضرب قدرنسبت و جملهٔ اول این دنبالهٔ حسابی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3965, '۱۵- اگر در یک مجموعهٔ مرجع ۴۰ عضوی، $n(A)=۱۰$ و $n(A\'\\cap B\')=۲۶$ باشد، تعداد اعضای مجموعهٔ $B-A$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3966, '۱۶- با توجه به الگوی روبه‌رو، در شکل دهم اختلاف تعداد مربع‌های رنگ‌شده و سفید کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3967, '۱۷- حاصل‌ضرب سه جملهٔ ابتدایی دنبالهٔ $۳،۹،۲۷,...$ برابر $۳^n$ است. عدد طبیعی $n$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3968, '۱۸- در دنبالهٔ با جملات $۴،۸،۱۴،۲۳،۰۰۰$ جملهٔ هفتم کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3969, '۱۹- اگر دنبالهٔ $(a,b,c)$ حسابی و $a=b-۲$, $b=c-۴$ و $a,b,c$ هندسی باشد، حاصل $c-a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3970, '۲۰- اگر $U=\\{۱,۲,۳,۴,۵,۶,۷,۸,۹\\}$ و $A=\\{۱,۳,۷\\}$ و $B=\\{۲,۴,۷,۵\\}$ و $C\'=\\{۱,۲,۵,۷,۹\\}$ آنگاه $(A\\cup C\')\\cap B$ چند عضو دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3971, '۲۱- بین دو عدد $-12$ و $a$به تعداد ۹ واسطۀ حسابی درج می‌کنیم. اگر واسطۀ چهارم عدد صفر باشد، مقدار $a$ به کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3972, '۲۲- در یک کلاس ۳۲ نفره، ۱۷ نفر به خطاطی و ۲۱ نفر به نقاشی علاقه‌مند هستند. حداکثر و حداقل تعداد افرادی از این کلاس که به هر دو رشته علاقه‌مندند، به‌ترتیب کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3973, '۲۳- مطابق الگوی زیر، تعداد دایره‌های توپر در شکل مرحله سیزدهم کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3974, '۲۴- در دنباله هندسی $a_n$ داریم: $a_1=a_2$ و $a_3=a_4$، $a_1a_2=a_3a_4=3$، مجذور قدرنسبت این دنباله کدام است؟ $(a_1 \\neq a_2 \\neq a_3 \\neq a_4)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3975, '۲۵- اگر $A$ و $B$ دو زیرمجموعه از مجموعه مرجع $U$ باشند، به‌گونه‌ای که $n(U)=25$ و $n(A-B)=12$ و $n((A \\cup B)\')=5$، تعداد اعضای مجموعه $B$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3976, 'اگر $A=\\sqrt[3]{\\sqrt{2}+\\sqrt{2}}+1$ و $B=\\sqrt[3]{\\sqrt{2}-1}$، حاصل $(A^2-B^2)(A^4+A^2B^2+B^4)$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, '2026-02-26 13:05:29', 2, 'done'),
(3977, 'با توجه به الگوی زیر در شکل چندم، تعداد دایره‌ها برابر ۱۱۷ می‌شود؟', 1, 1, 59, 242, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, '2026-02-26 13:04:50', 2, 'done'),
(3978, '۲۸- دنباله $a,a+3,a+6,\\dots$ هندسی و دنباله $a,a+9,\\dots$ حسابی است. نسبت جمله ششم دنباله هندسی به جمله ششم دنباله حسابی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3979, '۲۹- هرگاه $A$ و $B$ دو مجموعه غیرتهی و جدا از هم باشند، کدام رابطه نادرست است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3980, '۳۰- در الگوی زیر، تعداد نقاط توپر در مرحله دهم از تعداد نقاط توپر مرحله نهم چه تعداد بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3981, '۳۱- هرگاه $a\\neq4$، به‌ترتیب واسطه حسابی و واسطه هندسی دو عدد متمایز ۲ و $b$ باشند، مقدار $b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3982, '۳۲- در یک کلاس ۴۵ نفری، ۲۷ نفر به فوتبال و ۲۱ نفر به والیبال علاقه‌مند هستند. اگر ۵ نفر به هیچ‌یک از دو ورزش علاقه‌ای نداشته باشند، چند نفر فقط به والیبال علاقه‌مند هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3983, '۳۳- اگر اعداد $x+2,x+1,y$ تشکیل دنباله حسابی و اعداد $x,y,xy$ تشکیل دنباله هندسی با جملات غیرصفر بدهند، مجموع جملات پنجم این دو دنباله کدام است؟ $(x,y\\neq0)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3984, '۳۴- با توجه به الگوی داده‌شده، در مرحله‌ای که $47.5\\%$ درصد نقاط توپر می‌باشند، تعداد نقاط توخالی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3985, '۳۵- اگر $A\\subseteq B\'$ باشد، ساده‌شدهٔ عبارت $(A-B)\\cup(A\\cap B)\'$ کدام است؟ (M مجموعهٔ مرجع است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3986, '۳۶- با توجه به الگوی زیر، اختلاف تعداد دایره‌ها در دو مرحلهٔ متوالی $20$ واحد است. جمع تعداد دایره‌ها در این دو مرحله کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3987, '۳۷- در یک دنبالهٔ حسابی غیرثابت اگر $a_1=8$ و جملات دوم، ششم و هشتم آن تشکیل دنبالهٔ هندسی دهند، جملهٔ پنجم دنبالهٔ حسابی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:03:31', 1, NULL, NULL, 'free'),
(3988, '2- کدامیک از موارد زیر از سایر گزینه‌ها کوچک‌تر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(3989, '3- اگر $a=\\cot 15^\\circ$ باشد، آنگاه حاصل $\\frac{2\\sin 105^\\circ+\\cos255^ 255^\\circ}{\\sin 345^\\circ+3\\sin 525^\\circ}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(3990, '4- در دایره مثلثاتی مقابل، طول پاره‌خط $AB$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
