(4042, '۵۸- شکل مقابل نمودار تابع $f(x)=a\\cos(bx-\\frac{2\\pi}{3})+1$ است. اگر مساحت مثلث $ABC$ برابر $\\frac{3\\sqrt{3}}{2}$ واحد مربع باشد، حاصل $a+\\frac{XD}{\\pi}-b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(4043, '۵۹- تابع $y=a-b\\sin(2x-\\frac{\\pi}{12})$ با فرض $a>0$ و $b>0$ در نقاط $x_1$ و $x_2$ در بازه $(0,\\frac{2\\pi}{3})$ به ترتیب دارای مینیمم و ماکزیمم است. حاصل $x_2-x_1$ چند است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
