(4045, '61- اگر $4 = \\frac{\\cos x}{1 + \\sin x} + \\frac{4 \\cos x}{1 - \\sin x}$ باشد، حاصل $2 \\cos(\\frac{\\pi}{2} + x) + \\sin(\\frac{9\\pi}{2} - x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(4046, 'در مربع مقابل، یک ربع دایره به مرکز $A$ و یک دایره به مرکز $P$ رسم شده‌اند. حاصل $\\frac{\\sin \\beta}{\\sin \\alpha}$ کدام است؟', 1, 1, 45, 199, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, '2026-02-27 23:50:21', 2, 'done'),
(4047, '۶۳- حاصل $tan22.5^\\circ$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(4048, '۶۴- معادله $cosx \\times sin\\frac{x}{2} = cosx \\times cos\\frac{x}{2}$ در فاصله $(0,2\\pi)$ چند جواب دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(4049, '۶۵- چند مقدار صحیح می‌تواند داشته باشد تا معادله $6cos^2x+(1-7a)cos2x=5a$ در بازه $(-\\frac{\\pi}{9},\\frac{\\pi}{18})$ جواب داشته باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
