(4051, '۶۷- مقدار عددی عبارت $-\\frac{y\\sin\\Delta x+\\cos fx}{3\\sin\\Delta x+y\\cos fx}$ برای $x=\\frac{\\pi}{18}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, NULL, NULL, 'free'),
(4052, 'اگر نمودار تابع $y=a+b\\sin(\\frac{x}{\\pi})$ به صورت زیر باشد، حاصل $\\frac{b+c}{a}$ کدام است؟', 3, 1, 47, 206, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 13:18:26', 1, '2026-02-27 23:44:13', 2, 'done'),
