(4054, '۲- عددی منفی وجود دارد که از نصف مربع خود، ۲ واحد کمتر است. آن عدد کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
