(4056, '۴- خط $y = 2$ بر سهمی $y = 2x^2 + kx + 20$ در ربع اول مماس است. مقدار $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4057, '۵- اگر $\\alpha$ و $\\beta$ ریشه‌های معادله درجه دوم $x^2 + x - 3 = 0$ باشند، حاصل $(1 + \\frac{3}{\\alpha})^2 + (1 + \\frac{3}{\\beta})^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4058, '۶- مجموع دو عدد برابر ۲ و مجموع مکعبات آن‌ها برابر ۴ است. آن دو عدد کدام هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
