(4065, '۱۳- اگر ساده شده عبارت $\\frac{1}{\\sqrt[3]{x} + 2} \\times \\frac{\\sqrt[3]{x^2} - \\sqrt[3]{x}}{\\sqrt[3]{x^2} - \\sqrt[3]{x}}$ به صورت $\\frac{f(x)}{x + 8}$ باشد، عبارت جبری $f(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4066, '۱۴- اگر $a$ و $b$ دو عدد حقیقی دلخواه مثبت باشند، مقدار $\\frac{\\sqrt{a} \\sqrt[3]{b}}{\\sqrt{b} \\sqrt[3]{a}}$ برابر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
