(4090, '۳۸- طول یک مستطیل، از دو برابر عرض آن یک واحد بیشتر است. اگر مساحت این مستطیل ۳۶ باشد، مربع اندازه قطر آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
