(4092, '۴۰- مقادیر تابع $f(x) = -\\frac{1}{2}x^2 + 2x + 6$، در بازه $(a, b)$ بزرگ‌تر از ۷ می‌باشد. بیشترین مقدار $b - a$، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4093, '۴۱- طول یک مستطیل ۳ سانتی‌متر بیشتر از ۴ برابر عرض آن است. اگر مساحت این مستطیل ۴۵ سانتی‌متر مربع باشد، اندازه قطر این مستطیل چند سانتی‌متر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4094, '۴۲- فاصله رئوس دو سهمی $y = (x - 3)^2 + 5$ و $y = -2x^2 + 12x - 5$ از یکدیگر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4095, '۴۳- مجموعه جواب نامعادله $\\frac{(x + 2)^2 - 4}{(2 - 6x)^3} \\le 0$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4096, '۴۴- اگر جدول تعیین علامت عبارت $P(x) = mx^2 + (m^2 + 2)x + 2m$ به صورت زیر باشد، مقدار عددی $m + n$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4097, '۴۵- اگر ضابطه سهمی مقابل به صورت $f(x) = ax^2 + bx + c$ باشد، کدام گزینه درست است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4098, '۴۶- مجموع ریشه‌های معادله $\\frac{1}{x^2 - 1} + \\frac{3}{2x^2 - 2} = \\frac{5}{6}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4099, '۴۷- معادله درجه‌دومی که ریشه‌های آن دو واحد از ریشه‌های معادله $x^2 - 3x - 2 = 0$ بیشتر باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4100, '۴۸- به ازای کدام مقدار $k$، مجموع معکوس ریشه‌های معادله $2x^2 + (2k - 1)x - k = 0$ برابر $\\frac{7}{3}$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4101, '۴۹- نمودار سهمی $f(x) = ax^2 + bx + c$ به صورت زیر است. مقدار $f(8)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4102, '۵۰- اگر $x = 4$ یکی از جواب‌های معادله $\\sqrt{5x - x^2} = x + a$ باشد، جواب دیگر آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4103, '۵۱- اگر سه ماشین چمن‌زنی $A$، $B$ و $C$ با هم کار کنند، می‌توانند در $\\frac{12}{7}$ ساعت چمن یک زمین فوتبال را کوتاه کنند. با فرض اینکه سرعت کار ماشین $A$ دو برابر ماشین $B$ و سرعت کار ماشین $B$ دو برابر ماشین $C$ باشد، ماشین $A$ به تنهایی در چند ساعت می‌تواند چمن این زمین را کوتاه کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4104, '۵۲- معادله $\\frac{x}{x + 1} = \\frac{x + 1}{x - 4} - \\frac{5}{x^2 - 3x - 4}$ دارای چند جواب است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4105, '۵۳- استادیومی به شکل مستطیل با دو نیم‌دایره در دو انتهای آن در حال ساخت است. اگر محیط استادیوم ۱۵۰۰ متر باشد، طول مستطیل چقدر باشد تا مساحت مستطیل حداکثر مقدار ممکن شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4106, '۵۴- اگر $x$ ریشه پنجم عدد $8\\sqrt[4]{4}$ باشد، مقدار $A$ از رابطه $x\\sqrt{A} = 4\\sqrt[15]{8^{11}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4107, '۵۵- اگر $x\\sqrt{x} + \\frac{2}{x\\sqrt{x}} = 4$، مقدار $A = x^4\\sqrt{x} + \\frac{8}{x^4\\sqrt{x}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4108, '۵۶- شکل روبه‌رو نمودار تابع $y = ax^2 + bx + c$ است. مقدار $b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4109, '۵۷- حاصل‌جمع تمام اعداد صحیحی که در نامعادله $\\frac{7 - x}{x^2 - 9} \\le -1$ صدق می‌کنند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4110, '۵۸- نمودار سهمی $y = ax^2 + bx + c$ در شکل زیر رسم شده است. با توجه به این نمودار چه تعداد از مقادیر $a$، $b$، $c$ و $\\Delta$ مثبت هستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4111, '۵۹- مجموع ریشه‌های معادله $\\frac{9^x}{27^{x^2}} = \\sqrt{3}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4112, '۶۰- فرض کنید $\\alpha$ و $\\beta$ ریشه‌های معادله $x^2 - (m + 1)x + 1 = 0$ باشند. اگر $\\alpha\\sqrt{\\alpha} + \\beta\\sqrt{\\beta} = \\sqrt{5}$، آنگاه $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4113, '۶۱- قایقی با سرعت پاروزنی ثابت یک مسیر ۴۰۰ متری در یک رودخانه را رفته و با همان سرعت پاروزنی ثابت برگشته است. اگر سرعت آب رودخانه ۲۰ متر بر دقیقه باشد، سرعت خود قایق چند متر بر دقیقه باشد تا اختلاف زمان رفت و برگشت ۵ دقیقه شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4114, '۱- اگر تعیین علامت عبارات $A = ax + 8$ و $B = bx + a - 1$ به صورت زیر باشد، $a + b$ کدام است؟\n\n$\\begin{array}{c|ccc} x & & -2a & \\\\ \\hline A & + & 0 & - \\end{array}$\n\n$\\begin{array}{c|ccc} x & & a + b & \\\\ \\hline B & - & 0 & + \\end{array}$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4115, '۲- مجموع ریشه‌های حقیقی معادله $\\sqrt{x^2 + 3x + 5} + 3x + x^2 = 3$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4116, '۳- جواب نامعادله $x^2 + 2x + 4 < |x^2 - 8|$ به صورت $(a, b)$ است. بیشترین مقدار $b - a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4117, ' دو کارگر قرار است دیواری را بسازند. اگر هر یک به تنهایی کار کنند کارگر اول ۷ روز زودتر از کارگر دوم کار را تمام می‌کند و اگر بخواهند با هم کار کنند دیوار در ۱۲ روز ساخته می‌شود. کارگر دوم به تنهایی چند روزه می‌تواند دیوار را بسازد؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, '2026-04-05 21:15:22', 5, 'done'),
(4118, 'مجموع جواب نامعادله $1 \\le \\frac{4x^2 + 6x - 3}{3x^2 + 4x - 4}$ را به صورت $|3x + a| \\ge b$ نوشته‌ایم، حاصل $b - a$ کدام است؟', 2, 1, 58, 239, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, '2026-04-05 21:14:58', 5, 'done'),
(4119, 'اگر معادله $x - 3 = \\sqrt{ax + 9}$ دارای جواب باشد، آنگاه $a$ به کدام مجموعه تعلق دارد؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, '2026-04-05 21:14:44', 5, 'done'),
(4120, 'مجموعه جواب نامعادله $|\\frac{2x + 1}{3x - 2}| > 1$ کدام است؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, '2026-04-05 21:14:30', 5, 'done'),
(4121, '۸- به ازای چند مقدار $m$، مجموعه جواب معادله $\\frac{m}{2x} = \\frac{3 - x}{2x - x^2}$ برابر تهی می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4122, '۹- اگر برای $x > -3$ مجموعه جواب نامعادله $\\frac{x^3 + ax^2 + bx + c}{x + 4} > 0$ برابر $(-\\infty, -2) \\cup \\{1\\}$ باشد، مقدار $b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4123, '۱۰- اگر مجموعه جواب نامعادله $\\frac{1}{x^2 - 2x + 3} + \\frac{3}{x^2 + 2x + 3} \\le \\frac{4}{x}$ به صورت $(a, b] \\cup [c, +\\infty)$ باشد، حاصل $b + c$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4124, '۱۱- نمودار یک سهمی محور $x$ ها را در نقاط ۲ و ۶ قطع کرده و از نقطه $(\\frac{5}{2}, -7)$ نیز می‌گذرد. بیشترین مقدار این سهمی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4125, '۱۲- اگر معادله $mx(x+1) = -1$ دارای دو ریشه‌ی منفی باشد، مقادیر قابل قبول برای $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4126, '۱۳- اگر از هر کدام از ریشه‌های معادله $x^2 - 5x - k = 0$، یک و نیم واحد کم کنیم، حاصل ضرب ریشه‌ها چه تغییری خواهد کرد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4127, '۱۴- در یک مثلث قائم‌الزاویه، طول ضلع متوسط از دو برابر طول ضلع کوچک مثلث، یک واحد کمتر و طول وتر از دو برابر طول ضلع کوچک مثلث، یک واحد بیشتر است. محیط مثلث کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4128, '۱۵- به ازای چند مقدار صحیح $a$، نمودار تابع $y = (a - 1)x^2 - (a + 1)x + a + 1$ از بیش از دو ناحیه محورهای مختصات عبور می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4129, '۱۶- حاصل‌ضرب ریشه‌های حقیقی معادله $(x^2 + x + 7)(x + 3)(x - 2) = 30$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4130, '۱۷- مطابق شکل مستطیلی در ناحیه دوم، بر محورهای مختصات منطبق و یکی از رئوس آن روی منحنی $y = (x + 2)^2$ در حال حرکت است. کمترین مقدار محیط این مستطیل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4131, '۱۸- در معادله درجه دوم $2mx^2 - 6x + 5 = 0$ اگر یکی از ریشه‌ها سه برابر ریشه دیگر باشد، مقدار $m$ کدام است؟ ($m \\ne 0$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:13', 1, NULL, NULL, 'free'),
(4132, '۱۹- اگر دو معادله $x^2 - x + k = 0$ و $x^2 + 3x - k = 0$ یک ریشه مشترک غیر صفر داشته باشند، حاصل‌ضرب ریشه‌های غیرمشترک کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4133, '۲۰- اگر $\\alpha = \\frac{r}{\\sqrt{r^2 + 1}}$ و $\\beta = \\frac{r}{\\sqrt{r^2 - 1}}$ ریشه‌های معادله $x^2 - bx + 3 = 0$ باشند، حاصل $br^2$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4134, '۲۱- اگر $x - \\frac{1}{x} = 1$ باشد، حاصل $\\frac{x^4 + 3x^2 + 4}{x^2 - x + 2}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4135, '۲۲- اگر حاصل کسر $\\frac{x^{0/5}}{\\sqrt{3} - \\sqrt{2} + 1}$ به صورت $\\sqrt{2} - \\sqrt{6} + 2$ باشد، مقدار $x$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4136, '۲۳- اگر حاصل $\\sqrt{3\\sqrt[3]{20 + k\\sqrt{2}} + \\sqrt{3 - 2\\sqrt{2}}}$ عددی گویا باشد، $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(4137, '۲۴- حاصل عبارت $\\frac{2 + \\sqrt{3}}{\\sqrt{2} + \\sqrt{2 + \\sqrt{3}}} + \\frac{2 - \\sqrt{3}}{\\sqrt{2} - \\sqrt{2 - \\sqrt{3}}}$ برابر با کدام گزینه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4138, '۲۵- نمودار سهمی $f(x) = -\\frac{1}{2}x^2 + ax + b$ به صورت زیر است. قدر مطلق تفاضل صفرهای این سهمی کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4139, '۲۶- در شکل مقابل سهمی $y = x^2 - 2x$ رسم شده است. مساحت مربع سایه زده شده کدام است؟ (دو رأس مربع روی محور $x$ ها و دو رأس دیگر روی سهمی‌اند.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4140, '۲۷- اگر بین ریشه‌های $x_1, x_2$ از معادله $x^2 - 3x - 2m + 1 = 0$ رابطه $2x_1 - 3x_2 = 6$ برقرار باشد، $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4141, '۲۸- معادله $x^4 - (m^2 - 1)x^2 + m - 3 = 0$ چهار ریشه حقیقی دارد که مجموع مربعات آن‌ها برابر ۳۰ است. چند مقدار برای $m$ وجود دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4142, '۲۹- به ازای چند مقدار صحیح $m$، مجموعه جواب نامعادله $(8x + 2)(3x^2 + 2mx + m) > 0$ به صورت $(-\\frac{1}{4}, +\\infty)$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4143, '۳۰- اگر جواب نامعادله $\\frac{2x - a}{x + b} \\ge 3$ بازه $[3, 10)$ باشد، حاصل $a - b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4144, '۳۱- مجموعه جواب نامعادله $x - 3 < \\frac{2x + 1}{x - 1}$ برای $x > 1$ بازه $(a, b)$ است. حاصل $\\frac{a + b}{2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4145, '۳۲- جدول تعیین علامت عبارت $f(x) = \\frac{(m^2 - 2)x^2 - (3m + 1)x - 4}{x - 3\\sqrt{x} + 2}$ به صورت زیر است. مقدار $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4146, '۳۳- مجموع جواب‌های معادله $3 = \\frac{(3x+4)^2(x-2)^2}{16} + \\frac{16}{(2x+5)^2(2x-3)^2}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4147, '۳۴- معادله $\\frac{m}{x - 1} = \\frac{x}{x + 1} + \\frac{-x^2 + 3x + 3}{x^2 - 1}$ جواب حقیقی ندارد. مجموع مقادیر حقیقی m کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4148, '۳۵- ۴۰ کیلوگرم محلول آب نمک با غلظت ۱۵ درصد داریم. می‌خواهیم با افزودن ۷ کیلوگرم نمک و تبخیر مقداری از آب محلول غلظت آن را به ۴۰ درصد برسانیم. در این صورت، جرم محلول چند کیلوگرم کاهش می‌یابد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4149, '۳۶- تعداد و علامت ریشه‌های معادله $\\sqrt{x + 17} = x + 2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4150, 'اگر $x_1$ و $x_2$ ریشه‌های معادله $x^2 - (m + 5)x + 2m - 3 = 0$ و $|x_1| < |x_2|$ و $x_1 x_2 < 0$ باشد، آن‌گاه m چند مقدار صحیح می‌تواند داشته باشد؟', 1, 1, 64, 241, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:35:06', 5, 'done'),
(4151, '۳۸- اگر ریشه‌های معادله $x^2 - 3x - 1 = 0$ به صورت $\\frac{1}{\\beta - 1}$ و $\\frac{1}{\\alpha - 1}$ باشند، معادله‌ای که ریشه‌هایش به صورت $2\\beta$ و $2\\alpha$ باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4152, '۳۹- ریشه‌های معادله $x + \\frac{a}{x + 2} = b$ دو برابر ریشه‌های معادله $x + \\frac{1}{x + 1} = \\frac{3}{2}$ است، مقدار $a + b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4153, '۴۰- برای انجام کاری اگر ۲ کارگر از ۳ کارگر موجود را انتخاب کنیم، این کار ممکن است ۳/۵ یا ۴/۵ یا ۳/۷۵ روز طول بکشد. این ۳ کارگر با هم این کار را تقریباً در چند روز انجام خواهند داد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4154, '۴۱- به ازای کدام مقدار a، یکی از ریشه‌های معادله $\\frac{a}{6} = \\frac{1}{x} + \\frac{1}{x + 1}$ از ۵ برابر ریشه دیگر، ۵ واحد بیشتر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4155, '۴۲- قدر مطلق تفاضل جواب‌های معادله $2x^2 +  x + 4 \\sqrt{2x^2 + x} = 5$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4156, '۴۳- اگر $x = m$ ریشه معادله $1 = \\sqrt{x+2} - \\sqrt{3x-5}$ باشد، $m^2 - 6m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4157, '۴۴- ریشه‌های معادله $x^2 + bx + 6 = 0$ اعداد $\\beta - 1$ و $\\alpha$ هستند. اگر ریشه‌های معادله $x^2 + 4x + c = 0$ اعداد $\\alpha$ و $\\beta$ باشند، $b + c$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4158, '۴۵- به ازای چند مقدار طبیعی $m$، نمودار سهمی $y = -x^2 + 2mx + m - 2$ از ناحیه دوم مختصاتی عبور نمی‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4159, '۴۶- اگر در تابع $y = k - x^2$ نقطه A رأس تابع و نقاط C و B محل تقاطع سهمی با خط $y = x$ بوده و مساحت مثلث ABC برابر ۳ باشد، $k$ چقدر است؟ ($k > 0$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4160, '۴۷- سجاد و احسان برای این‌که از مدرسه به خانه‌های خود بازگردند، باید مسیر ۷۲۰ متری مدرسه تا اولین ایستگاه متروی نزدیک را طی کنند. یک روز که هر دو این مسیر را می‌رفتند، سجاد ۱۰۰ قدم بیشتر از احسان برداشت، زیرا هر قدم او ۱۰ سانتی‌متر کوتاه‌تر از احسان بود. طول قدم سجاد چقدر بوده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4161, '۴۸- معادله $1 = \\frac{-x}{4-x^2} + \\frac{x+k}{x+2}$ فاقد جواب است. حاصل‌ضرب مقادیر $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4162, '۴۹- نسبت عدد $\\sqrt{\\frac{1}{2} + \\frac{\\sqrt{2 - \\sqrt{3}}}{2}}$ به $\\sqrt{6}$، برابر چه توانی از ۲ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4163, '۵۰- اگر $x + y = 4$ و $xy = 1$، حاصل $x\\sqrt{x} + y\\sqrt{y}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4164, '۵۱- در یک مثلث قائم‌الزاویه به وتر $\\sqrt{8}$، اختلاف طول دو ضلع قائمه برابر ۲ می‌باشد. مجذور ضلع کوچک‌تر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4165, '۵۲- معادله $-(x^2 - 3x + 2)(x^2 - 7x + 12) = 1$ چند ریشه حقیقی متمایز دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4166, '۵۳- نمودار سهمی‌های $y = -2x^2 + bx + c$ و $y = x^2 - 4x - b$ در شکل روبه‌رو رسم شده است. رأس دو سهمی از هم چقدر فاصله دارند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4167, '۵۴- محدوده $(-3, b)$ بزرگ‌ترین بازه‌ای است که نمودار $f(x) = -x^2 + ax + 7$ بالاتر از نمودار $g(x) = -x + 1$ قرار دارد. حاصل $a + b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4168, '۵۵- مجموعه جواب نامعادله $x^2 + x + \\frac{3}{x^2 + x + 1} < 3$ شامل چند عدد صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4169, '۵۶- مجموعه جواب نامعادله $x + |x - 1| - |x + 1| < 0$ به صورت $(-\\infty, a) \\cup (b, c)$ است حاصل $a + b + c$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4170, '۵۷- اگر جدول تعیین علامت عبارت $P(x) = \\frac{x^2 + ax + b}{x + c}$ به صورت زیر باشد، مقدار $\\frac{a + b}{c}$ کدام است؟\n\n$\\begin{array}{c|ccccc} x & & -1 & & 2 & \\\\ \\hline P(x) & - & 0 & + & \\text{ن. ت} & + \\end{array}$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4171, '۵۸- معادله $\\frac{2x^2}{x^3 - x} = \\frac{2}{x - 1} + \\frac{1}{x} + \\frac{1}{x + 1}$ چند جواب دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4172, '۵۹- مجموع جواب‌های معادله $x^2 - 3x - 3\\sqrt{x^2 - 3x + 1} + 3 = 0$ برابر با کدام گزینه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4173, '۶۰- مجموعه جواب نامعادله $x^4 - 5x^2 + 4 \\le 0$ به صورت $[a, b] \\cup [c, d]$ است. بیشترین مقدار $b - a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4174, '۶۱- معادله $\\frac{\\sqrt{x + 5}}{\\sqrt{x} + \\sqrt{x + 3}} = \\frac{\\sqrt{x} - \\sqrt{x + 3}}{3 - \\sqrt{x + 5}}$ از نظر تعداد و علامت ریشه (یا ریشه‌ها) چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4175, '۶۲- تابع $f(x) = \\frac{x^2 + ax + 1}{x^2 + x + 1}$ همواره زیر خط $y = 3$ قرار می‌گیرد، اگر بیشترین بازه ممکن برای $a$ به صورت $(m, n)$ باشد، $m + n$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4176, '۶۳- اگر $a$ و $b$ به ترتیب از راست به چپ بزرگترین و کوچکترین عدد صحیحی باشند که در نامساوی $\\frac{3}{4} < \\frac{x + 4}{2x + 3} < 1$ صدق می‌کنند، حاصل $\\frac{a + 4}{2b + 3}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4177, '۶۴- به‌ازای چند مقدار صحیح $a$، معادله $\\frac{x + 1}{x - a} = \\frac{2x + 3}{2ax - 1}$ دارای جواب حقیقی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4178, '۶۵- معادله $\\sqrt{x - 5} + \\sqrt{10 - x} = \\sqrt{3 + \\sqrt{x - 5}} + \\frac{\\sqrt{2}}{2}$ چند ریشه حقیقی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4179, '۶۶- یک استخر توسط یک شیر دو حالته (کم‌فشار و پرفشار) پر می‌شود. اگر شیر ۲ ساعت روی حالت کم‌فشار و ۳ ساعت روی حالت پرفشار باشد، استخر پر می‌شود. اگر نصف استخر را در ابتدا با حالت کم‌فشار و در ادامه نصف دیگر آن را با حالت پرفشار پر کنیم، ۵ ساعت و ربع طول می‌کشد. زمان پرشدن استخر در حالت کم‌فشار چند ساعت بیشتر از حالت پرفشار است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4180, '۶۷- نامعادله $x^2 - |x - 3| + |x + 3| < 3$ در بازه $(a, b)$ برقرار است. نقطه وسط این بازه کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4181, '۶۸- مجموعه جواب نامعادله $3 > |\\frac{x + 1}{2x - 1}| > 1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4182, '۶۹- موقعیت مدرسه‌ای به شکل زیر است. مدیر مدرسه می‌خواهد با کشیدن دیواری به طول ۸۵ متر (مانند نقطه‌چین داخل شکل) قسمتی مستطیل‌شکل به مدرسه اضافه کند. حداکثر مساحت اضافه شده به مدرسه، چند متر مربع است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4183, '۷۰- در سهمی زیر، مقدار $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4184, '۷۳- از معادله $\\frac{x + 1}{x - 1} + \\frac{2}{x} = \\frac{k}{x^2 - x}$ فقط یک جواب برای $x$ به‌دست آمده است. چند مقدار برای $k$ وجود دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4185, '۷۴- دو ظرف حاوی محلول آب‌نمک با جرم برابر و غلظت ۴۰٪ داریم. در طی دو آزمایش مختلف با هر کدام، در ظرف اول ۳ کیلوگرم نمک به محلول اضافه می‌کنیم و در ظرف دوم ۲ کیلوگرم از محلول را تبخیر می‌کنیم. در صورتی که غلظت نهایی هر دو محلول به‌دست آمده یکسان باشد، جرم آب در هر یک از محلول‌های اولیه برحسب کیلوگرم کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4186, '۷۵- اگر $\\alpha > 0$ ریشه معادله $x + \\sqrt{3x^2 - 7x - 1} = 7$ باشد، مقدار $\\sqrt{\\alpha - 3}$ به کدام عدد طبیعی نزدیک‌تر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4187, '۷۶- در معادله $x^2 + 5x + 10 = 2\\sqrt{x^2 + 5x + 13}$، مجموع ریشه‌ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4188, '۷۷- اگر $0 < a < 1$ باشد، آنگاه حاصل عبارت $A = |a - \\sqrt[3]{a}| - |a - \\sqrt{a}| + |a - 1| + |\\sqrt{a} - \\sqrt[3]{a}|$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4189, '۷۸- حاصل عبارت $A = (\\sqrt{3} + \\sqrt{2} + \\sqrt{6})(\\sqrt{3} + \\sqrt{2} - \\sqrt{6}) + 1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
(4190, '۸۰- حاصل $(1 + \\sqrt[3]{x} + \\sqrt[3]{x^2})(\\sqrt[3]{x} - 1)(\\sqrt[3]{x^2} - \\sqrt[3]{x} + 1)(\\sqrt[3]{x} + 1)$ به ازای $x = \\sqrt{3}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, NULL, NULL, 'free'),
