(4192, 'اگر $5a^2 + 4b^2 - 4ab - 4a + 1 = 0$ باشد، حاصل $\\sqrt{a + b}$ به کدام عدد نزدیک‌تر است؟', 1, 1, 64, 240, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:34:37', 5, 'done'),
(4193, ' اگر $a = \\sqrt[3]{5 + 2\\sqrt{6}} + \\sqrt[3]{5 - 2\\sqrt{6}}$ باشد، مقدار $a^3 - 3a$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:34:03', 5, 'done'),
(4194, ' حاصل عبارت $(\\frac{2\\sqrt{3} + 1}{11})^{-1} (\\frac{1}{1 + \\sqrt{3} - \\sqrt{5}} - \\frac{1}{1 + \\sqrt{3} + \\sqrt{5}})$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:33:53', 5, 'done'),
(4195, ' اگر $a = \\sqrt[3]{14 + 3\\sqrt{3}}$ و $b = \\sqrt[3]{14 - 3\\sqrt{3}}$ باشد، حاصل $(a^2 + b^2 - ab)(a^2 + b^2 + ab)$ کدام است؟', 1, 1, 60, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:32:28', 5, 'done'),
(4196, '۸۶- اگر $x = \\frac{1 + \\sqrt{5}}{2}$ حاصل $\\sqrt{x - \\frac{1}{x}} + \\sqrt{1 - \\frac{1}{x}}$ کدام است؟', 2, 1, 58, 238, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:32:16', 5, 'done'),
(4197, ' یکی از ریشه‌های معادله $x^2 - x = k$ از دو برابر ریشه‌ی دیگر، ۳ واحد بیش‌تر است. عدد اختلاف دو ریشه، چند برابر مقدار $k$ است؟', 2, 1, 64, 241, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:32:02', 5, 'done'),
(4198, '۲- اگر $\\alpha - ۱$ و $\\beta + ۱$ ریشه‌های معادله $2x^2 - 3x - 1 = 0$ باشند، ریشه‌های کدام معادله $\\alpha$ و $\\beta + ۲$ است؟', 2, 1, 64, 241, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:31:50', 5, 'done'),
(4199, '۳- اگر $\\alpha$ و $\\beta$ ریشه‌های معادله $x^2 + x - 1 = 0$ باشند، حاصل $\\frac{1}{(1 + \\alpha)^3} + \\frac{1}{(1 + \\beta)^3}$ کدام است؟', 2, 1, 64, 241, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:31:33', 5, 'done'),
(4200, 'اگر $\\alpha$ ریشه‌ی بزرگ‌تر و $\\beta$ ریشه‌ی کوچک‌تر معادله $x(x - 2) = 6$ باشد، حاصل $\\alpha\\sqrt{\\beta+3}$ کدام است؟', 1, 1, 64, 241, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:31:19', 5, 'done'),
(4201, 'از معادله $x^2 + m = \\sqrt{m^2x^2 + 1}$، دو جواب برای $x$ به دست می‌آید. در مجموعه‌ی مقادیر قابل قبول برای $m$، چند عدد طبیعی وجود دارد؟', 1, 1, 64, 240, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:30:14', 5, 'done'),
(4202, ' در سهمی شکل زیر $CD$ با $AB$ موازی و طول $CD$ دو برابر طول $AB$ است. نسبت صفر بزرگ‌تر سهمی به صفر کوچک‌تر آن کدام است؟', 1, 1, 64, 237, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:31:07', 5, 'done'),
(4203, ' در شکل مقابل، نمودار سهمی $y = ax^2 + bx + c$ و خط $y = 2x$ رسم شده‌اند. مقدار $b$ کدام است؟', 1, 1, 64, 237, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:30:58', 5, 'done'),
(4204, ' خط $y = k$ بر نمودار سهمی $y = x^2 + mx + m$ مماس است. ................. مقدار $k$ برابر با ................. است.', 1, 1, 64, 237, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:30:49', 5, 'done'),
(4205, ' به جای $A$ کدام‌یک از عبارت‌های زیر قرار بگیرد تا معادله $\\frac{x + 1}{2x - 2} - \\frac{A}{x^2 - 1} = \\frac{x - 1}{2x + 2}$ جواب داشته باشد؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:30:34', 5, 'done'),
(4206, ' یاسمن به تنهایی کاری را در ۶۰ روز انجام می‌دهد. اگر یاسمن و کیمیا با هم آن کار را انجام دهند، ۵ روز زودتر از زمانی که کیمیا به تنهایی آن کار را انجام دهد، کار را تمام می‌کنند. کیمیا به تنهایی کار را در چند روز تمام می‌کند؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:30:24', 5, 'done'),
(4207, ' مجموع عددی با دو برابر جذرش برابر با $۵/۲۵$ است. اختلاف این عدد با جذرش کدام است؟', 2, 1, 58, 238, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:24:05', 5, 'done'),
