(4209, ' نمودار سهمی $y = ax^۲ + bx + c$ داده شده است. چه تعداد از پارامترهای $a$، $b$، $c$ و $\\Delta$ مثبت هستند؟', 1, 1, 64, 237, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:23:30', 5, 'done'),
(4210, ' نمودار تابع $f(x) = m(x - ۲)(x - ۱) + x - ۱$ بر محور $x$ها مماس است. طول نقطه‌ی تماس کدام است؟', 1, 1, 64, 237, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:36:14', 1, '2026-04-05 22:21:56', 5, 'done'),
