(4230, ' تابع $y = -2x^2 + 24x - 1$ با دامنه $(-\\infty, k]$، اکیداً صعودی است. حدود $k$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:15:59', 5, 'done'),
(4231, ' اگر $f(x) = \\begin{cases} x^2 - 2 & x \\ge 0 \\\\ x^2 - 2x & x < 0 \\end{cases}$ و $g(x) = \\begin{cases} \\sqrt{x} - 2 & x > 1 \\\\ 6 - x & x \\le 1 \\end{cases}$، حاصل $(f \\circ g)(4) + (g \\circ f)(1 - \\sqrt{2})$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:15:51', 5, 'done'),
(4232, '۶ - $f$ یک تابع خطی با عرض از مبدأ ۴ و $g$ یک تابع خطی با شیب ۵ است. اگر بدانیم $(f \\circ g)(x) = -10x + 6$، عرض از مبدأ تابع $g$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:15:42', 5, 'done'),
(4233, ' اگر $f = \\{(1, -2), (3, -4), (-2, 2), (-3, -4), (2, 5)\\}$ و $g = \\{(-2, -3), (3, 1), (2, -1), (5, 2), (7, 3)\\}$، آنگاه حاصل‌ضرب اعضای برد تابع $(f \\circ g)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:15:23', 5, 'done'),
