(4235, ' اگر $f(x) = \\sqrt{x + 2}$ و دامنه تابع $g$ برابر $D_g = [-5, 4)$ باشد، دامنه تابع $g \\circ f$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:14:03', 5, 'done'),
(4236, ' اگر $f(x) = \\frac{x + 2}{2x + 3}$، $g(x) = \\frac{12x}{2x - 5}$ و دامنه تابع $f \\circ g$ برابر $R - \\{a, b\\}$ باشد، مقدار $a + b$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:13:53', 5, 'done'),
(4237, ' اگر تابع $f = \\{(2, -1), (1, m^2), (-3, 10 - 5m), (-2, m + 4)\\}$ نزولی باشد، دقیق‌ترین محدوده $m$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:13:43', 5, 'done'),
