(4239, ' اگر تابع $f(x) = \\begin{cases} 2x - 1 & x \\ge 3 \\\\ kx + 2 & x < 3 \\end{cases}$، اکیداً صعودی باشد، دقیق‌ترین محدوده $k$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:13:24', 5, 'done'),
(4240, ' اگر $f(x) = \\frac{x + 2}{2x - 1}$ و $(f \\circ g)(x) = 3(\\frac{x - 2}{x + 3})$، آنگاه مجموع جواب‌های معادله $(g \\circ f)(x) = g(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:13:15', 5, 'done'),
(4241, ' اگر $f$ تابعی اکیداً صعودی با دامنه $(-\\infty, 6)$ باشد، مجموعه جواب نامعادله $f(|x| + x) < f(|x| - 1)$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:13:05', 5, 'done'),
(4242, 'اگر $f = \\{(2, -1), (-4, 2), (-1, -2), (0, 1), (-2, 0), (-3, 4)\\}$، آنگاه تابع $\\frac{f^{-1}}{f}$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:12:26', 5, 'done'),
