(4255, ' اگر $f(x) = 4 - [x]$، آنگاه تابع $f \\circ f$ کدام است؟ ($[ \\ \\ ]$ نماد جزء صحیح است.)', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:07:20', 5, 'done'),
(4256, '۳۰ - اگر $f(x) = \\frac{x + 3}{2x - 1}$ و $(f \\circ g)(x) = 3x - 2$، آنگاه مقدار $g^{-1}(-3)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:32', 1, '2026-04-05 22:07:10', 5, 'done'),
