(4288, '۶۲ - کدام گزینه نمودار تابع $f(x) = \\begin{cases} -x^2 + 1 & x < 0 \\\\ |x + 1| - 1 & x \\ge 0 \\end{cases}$ را به‌درستی نشان می‌دهد؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 22:02:06', 5, 'done'),
(4289, ' اگر $f(x) = \\begin{cases} 2ax + 5b & x \\ge 2 \\\\ -2x^2 + 1 & -1 \\le x \\le 2 \\\\ b - ax & x \\le -1 \\end{cases}$ یک تابع باشد، مقدار $ab$ کدام است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:25:51', 5, 'done'),
(4290, '۶۴ - اگر $p(x)$ رابطه محیط مستطیل روبه‌رو را به‌صورت تابعی از $x$ بیان کند، $p(1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, NULL, NULL, 'free'),
(4291, ' ضابطه وارون تابع $f(x) = \\frac{-7x + 3}{5}$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:25:36', 5, 'done'),
(4292, ' نمودار تابع $f$ به‌شکل روبه‌رو است. این تابع با کدام‌یک از توابع زیر برابر است؟', 2, 1, 42, 179, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:25:27', 5, 'done'),
(4293, '۶۷ - نمودار تابع $y = [x] + 2$ در بازه $[-1, 2)$ کدام است؟ ($[ \\ \\ ]$ نماد جزء صحیح است.)', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:25:15', 5, 'done'),
(4294, ' اگر تابع درجه‌دوم $f(x) = 3x^2 - (a - 1)x + 5$ در بازه $[2, +\\infty)$ یک‌به‌یک باشد، حداکثر $a$ کدام است؟', 2, 1, 42, 181, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:25:07', 5, 'done'),
(4295, ' اگر تابع $f = \\{(2, 2), (-3, 4), (3a, 2), (a + 2b, 4)\\}$ یک‌به‌یک باشد، وارون تابع $g(x) = bx + a$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:24:58', 5, 'done'),
(4296, 'اگر $f(x)$ یک تابع خطی باشد و $f(3) = 10$ و $f^{-1}(-2) = -3$، حاصل $f^{-1}(4)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:24:46', 5, 'done'),
(4297, ' اگر فاصله دو خط موازی $y = ax + b$ و $y = 3x + 1$ برابر $\\frac{\\sqrt{10}}{2}$ باشد، کمترین مقدار $a + b$ کدام است؟', 2, 1, 55, 230, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:24:23', 5, 'done'),
(4298, ' در تابع همانی $f = \\{(2, 1 - a), (2a, b)\\}$، مقدار $a + b$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:24:08', 5, 'done'),
(4299, ' اگر $f(x) = \\frac{x^2 + 6x + 5}{x^2 + 6x + 7}$، حاصل $f(-3 - \\sqrt{3})$ کدام است؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:23:57', 5, 'done'),
(4300, ' برد تابع $f(x) = \\begin{cases} x^2 & x \\ge 1 \\\\ 3x + 1 & 0 \\le x < 1 \\\\ -|x| - 1 & x < 0 \\end{cases}$ کدام است؟', 1, 1, 41, 177, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:23:47', 5, 'done'),
(4301, ' نمودار تابع $f(x) = -|x + 3| + 1$ با کدام انتقال از هر چهار ناحیه مختصات عبور می‌کند؟', 1, 1, 41, 184, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:23:36', 5, 'done'),
(4302, ' اگر نمودار تابع $y = (x + a)^3 + 8$ به‌صورت روبه‌رو باشد، مقدار $a - b$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:21:13', 5, 'done'),
(4303, ' اگر $f(g(x)) = \\frac{5x - 1}{13}$ و $g(x) = \\sqrt[3]{x} + 1$، مقدار $f(3)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:21:05', 5, 'done'),
(4304, ' اگر تابع $f = \\{(1, m), (5, 7m + 2), (3, 2m + 1)\\}$ صعودی باشد، حدود $m$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:20:54', 5, 'done'),
(4305, ' کدام‌یک از توابع زیر هم صعودی و هم نزولی است؟ ($[ \\ \\ ]$ نماد جزء صحیح است.)', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:20:36', 5, 'done'),
(4306, '۸۰ - نمودار تابع $f(x) = x^3 + 3x^2 + 3x + 2$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:20:27', 5, 'done'),
(4307, ' اگر $f(x) = \\sqrt[3]{x - 1}$ و $D_g = [-2, 3]$، دامنه تابع $y = g \\circ f(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:20:16', 5, 'done'),
(4308, ' اگر $f = \\{(7, 8), (5, 3), (9, 8), (11, 4), (0, 7)\\}$ و $g = \\{(5, 7), (8, 1), (3, 5), (1, 0), (4, -2)\\}$، مجموع اعضای برد تابع $g \\circ f$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:20:08', 5, 'done'),
(4309, 'اگر $f(x) = \\sqrt{1 - x^2}$، نمودار تابع $y = (f \\circ f)(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:19:59', 5, 'done'),
(4310, ' اگر $f(x) = x^2 + 5x + 3$ و $g(x) = 1 - x$، ریشه بزرگ‌تر معادله $(f \\circ g)(x) = g(x)$، چند برابر ریشه کوچک‌تر آن است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:19:48', 5, 'done'),
(4311, ' اگر تابع $y = f(x)$ یک تابع اکیداً صعودی با دامنه $\\mathbb{R}$ باشد و $f(-1) = 0$، دامنه تابع $g(x) = \\sqrt{\\frac{f(x)}{x^2 - 9}}$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:19:36', 5, 'done'),
(4312, 'توابع $f$ و $g$ با دامنه $\\mathbb{R}$ را در نظر بگیرید. اگر $f$ اکیداً صعودی و $g$ اکیداً نزولی باشد، کدام‌یک از توابع زیر اکیداً نزولی است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:19:14', 5, 'done'),
(4313, '۸۷ - اگر تابع $f(x) = (x^2 - 2x + 1)|x - 1|$ در بازه $[a, +\\infty)$ اکیداً یکنوا باشد، حداقل مقدار $a$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:18:57', 5, 'done'),
(4314, ' نمودار تابع $y = \\sqrt{x + a} + b$ به‌صورت روبه‌رو است. حاصل $a \\times b$ کدام است؟', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:18:47', 5, 'done'),
(4315, 'مقدار $[|-2x|] + |[-x]|$ به‌ازای $x = \\frac{1}{3}$ چقدر است؟ ($[ \\ \\ ]$ نماد جزء صحیح است.)', 2, 1, 42, 180, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:18:40', 5, 'done'),
(4316, ' اگر $f = \\{(3, -1), (2, 2), (-1, 0), (0, -5), (1, 5)\\}$ و $g = \\{(-1, 2), (2, -1), (0, 3), (-2, 3), (1, -5)\\}$، دامنه تابع $\\frac{f^{-1} + g}{f + g}$ چند عضو دارد؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:18:29', 5, 'done'),
(4317, ' اگر $f = \\{(1, 2), (2, 3), (3, 4), (4, 2)\\}$ و $g(x) = \\frac{x + 5}{x^2 - 8}$ دو تابع باشند، مقدار $(\\frac{f + g}{g - f})(3)$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:18:20', 5, 'done'),
(4318, ' اگر دامنه تابع $f(x) = \\frac{x^2 + 2}{x^2 + bx + c}$ به‌صورت $D_f = \\mathbb{R} - \\{5\\}$ باشد، اشتراک دامنه و برد تابع $g(x) = b - \\sqrt{x + c}$ کدام است؟', 2, 1, 42, 180, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:18:12', 5, 'done'),
(4319, ' برد تابع با ضابطه $f(x) = x - [x + 1]$ کدام است؟ ($[ \\ \\ ]$ نماد جزء صحیح است.)', 2, 1, 42, 180, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:17:57', 5, 'done'),
(4320, 'تابع $f = \\{(2m, 3), (6, 6), (m^2 - 3, 3)\\}$ یک‌به‌یک است. معکوس آن کدام است؟', 2, 1, 42, 181, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:17:41', 5, 'done'),
(4321, ' اگر $f(x) = \\frac{3x^2 - x - 2}{x + 2}$ و $g(x) = \\frac{x - 1}{x + 2}$، برد تابع $\\frac{f}{g}$ کدام است؟', 2, 1, 42, 183, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:17:24', 5, 'done'),
(4322, ' تابع خطی $f(x) = ax + b$ وارون خود را فقط در نقطه‌ای به طول $-4$ قطع می‌کند. اگر مجموع عرض از مبدأ دو تابع $f$ و $f^{-1}$ برابر ۲ باشد، مقدار $a + b$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 21:13:58', 5, 'done'),
(4323, ' نمودار تابع $f(x)$ در شکل روبه‌رو رسم شده است. تابع $f$ در کدام‌یک از بازه‌های زیر، نزولی است ولی اکیداً نزولی نیست؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 20:00:52', 5, 'done'),
(4324, '۹۸ - نمودار تابع $y = -(x + 2)^3 + 1$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 20:00:41', 5, 'done'),
(4325, '۹۹ - اگر $f(x) = x^2 + 2x + 2$ و $g(x) = 2x - 5$، ریشه‌های معادله $(f \\circ g)(x) = (g \\circ f)(x)$ کدام‌اند؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 20:00:31', 5, 'done'),
(4326, ' اگر $f(x) = 2x - 3$، مقدار $(f^{-1} \\circ f^{-1})(5)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 20:00:18', 5, 'done'),
(4327, ' با فرض $x \\ge 3$، ضابطه وارون تابع $f(x) = x^2 - 6x + 1$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 20:00:06', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(4328, ' کدام‌یک از توابع زیر غیریکنوا است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:59:57', 5, 'done'),
(4329, '۱۰۳ - اگر $f(x) = \\sqrt{x^2 - x}$ و $g(x) = x - 3$، دامنه تابع $f \\circ g$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:59:42', 5, 'done'),
(4330, ' اگر $f(x) = \\sqrt{x - 1} + \\frac{|x|}{x}$، ضابطه $f^{-1}$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:59:31', 5, 'done'),
(4331, ' اگر $f(x) = 3 - \\sqrt{x + 2}$، نمودار تابع $y = (f \\circ f^{-1})(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:59:21', 5, 'done'),
(4332, ' شکل روبه‌رو نمودار تابع $y = f(\\frac{x}{2})$ است. دامنه تابع با ضابطه $g(x) = \\sqrt{x - f^{-1}(x)}$ کدام بازه است؟', 2, 1, 42, 180, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:59:04', 5, 'done'),
(4333, 'در شکل زیر نمودار دو تابع $y = f(x)$ و $y = f(\\frac{2x}{3})$ رسم شده است. مقدار $a + b + c + d$ کدام است؟', 3, 1, 43, 194, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:58:43', 5, 'done'),
(4334, ' اگر $f(x) = \\frac{x + 1}{x - 1}$ و $(f \\circ g)(x) = \\frac{x^2 + 2}{x^2 + 1}$ مقدار $g(1)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:58:29', 5, 'done'),
(4335, ' اگر $f(x) = -x^3 - 2x + 15$، مجموعه جواب نامعادله $f(f(x)) < f(-2x - 12)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:58:20', 5, 'done'),
(4336, '۱۱۰ - نمودار تابع $y = f(2x)$ به‌صورت روبه‌رو است. نمودار تابع $y = -2f(x-1) $ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:58:03', 5, 'done'),
(4337, 'اگر $f(x) = 2x + 5$ و $g(x) = 7x - 1$، جواب معادله $(f \\circ g)(x) = 10x + 27$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:57:57', 5, 'done'),
(4338, 'اگر $f(x) = 3 - \\sqrt{x - 1}$ و $f^{-1}(a) = 1$، مقدار $a$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:57:50', 5, 'done'),
(4339, ' تابع $f(x) = |2x - 4| + x$ در یک بازه صعودی است. ضابطه وارون تابع $f$ در این بازه کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:57:41', 5, 'done'),
(4340, '۱۱۴ - نمودار تابع $y = f(x)$ به‌صورت روبه‌رو است. نمودار تابع $y = 3x - (f \\circ f^{-1})(x)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:57:25', 5, 'done'),
(4341, ' اگر دامنه تابع $f(x)$ برابر $[-4, 6]$ و برد آن برابر $[2, 12]$ باشد، اشتراک دامنه و برد تابع $g(x) = \\frac{-f(2x) + 4}{2}$ کدام است؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:57:14', 5, 'done'),
(4342, ' شکل روبه‌رو نمودار تابع $y = f(x)$ است. نمودار کدام‌یک از توابع زیر، با نمودار تابع $f$ برخورد نمی‌کند؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:57:00', 5, 'done'),
(4343, ' اگر $f(x) = 9x^2 + 7$ و $g(x) = 3x^2 - 2$، مقدار $f^{-1} \\circ g^{-1}(1)$ کدام است؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:56:48', 5, 'done'),
