(4345, '۲- نمودار تابع $y = x^2 + |x| + 1$ به کدام صورت است؟', 2, 1, 58, 239, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:56:30', 5, 'done'),
