(4347, ' نمودار تابع با ضابطه $y = (x - a)^3 + b$ به‌صورت مقابل است. حاصل $a.b$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:56:07', 5, 'done'),
(4348, ' در تابع درجه سوم $f(x) = -x^3 + ax^2 + x + 2$، رابطه‌ی $f(-\\frac{3}{2}) - f(2) + f(-\\frac{3}{2}) = 5$ برقرار است. مقدار $f(2) + f(1)$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:56:00', 5, 'done'),
(4349, 'اگر $f(x)$ یک تابع خطی و $f(-3) + f(3) = 1$ و $f(2) = 4$ باشد، آنگاه نمودار تابع $f$ محور $y$ها را با چه عرضی قطع می‌کند؟', 1, 1, 41, 178, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:55:49', 5, 'done'),
(4350, ' تابع $f(x) = \\frac{3x^2 + ax + b}{2x^2 + cx + d}$ یک تابع ثابت با ضابطه $y = k$ و دامنه $R - \\{-3\\}$ است. حاصل $\\frac{a - b + c - d}{k}$ کدام است؟', 1, 1, 41, 178, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:55:39', 5, 'done'),
(4351, ' نمودار تابع $f(x) = 6x^2 - x^3 - 12x$ شبیه کدام گزینه است؟', 3, 1, 42, 179, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:55:27', 5, 'done'),
(4352, ' در تابع با ضابطه $f(x) = ax^3 - x + c$ اگر داشته باشیم: $f(-1) + f(1) = 2$ و $f(2) = 13$؛ آنگاه حاصل $f(a \\times c)$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:55:16', 5, 'done'),
(4353, ' در تابع با ضابطه $f(x) = ax^5 + bx^3 + 3x + c$ اگر داشته باشیم: $f(1) = 0$ و $f(-1) = -2$؛ آنگاه حاصل $3(a + b) + 2c$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:55:08', 5, 'done'),
(4354, ' نمودار تابع $y = 2 - x^3$ از کدام ناحیه‌ی دستگاه مختصات عبور نمی‌کند؟', 3, 1, 43, 185, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:55:00', 5, 'done'),
(4355, ' نمودار تابع $f(x) = x^3$ در بازه‌ی $(-\\infty, a)$ بالای نمودار تابع $g(x) = x^2$ قرار ندارد. بیشترین مقدار $a$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:54:52', 5, 'done'),
(4356, ' نمودار تابع با ضابطه‌ی $f(x) = x^3$ با انتقال‌های افقی و قائم بر نمودار تابع $g(x) = x^3 + 3x^2 + 3x$ منطبق می‌شود. در این انتقال، نقطه به طول ۲ واقع بر نمودار $f$ به نقطه‌ای با کدام عرض بر نمودار تابع $g$ قرار می‌گیرد؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:54:43', 5, 'done'),
(4357, ' نمودار تابع با ضابطه‌ی $f(x) = -(x - 1)^3 + a$ همواره به ازای هر مقدار $x$ از ناحیه‌ی سوم عبور نمی‌کند. حدود $a$ کدام است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-26 16:55:33', 1, '2026-04-05 19:54:36', 5, 'done'),
