(4667, ' در مثلث $ABC$، نقاط $M$ و $N$ روی ضلع‌های $AB$ و $AC$ به‌گونه‌ای قرار گرفته‌اند که $\\frac{AM}{BM} = \\frac{1}{2}$ و $\\frac{AN}{CN} = \\frac{1}{3}$. اگر از دو نقطۀ $M$ و $N$ به موازات اضلاع $AC$ و $AB$ دو خط رسم کنیم تا ضلع $BC$ را در $Q$ و $P$ قطع کنند، ضلع $BC$ چند برابر $PQ$ است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:31:51', 5, 'done'),
(4668, ' در ذوزنقۀ زیر، اندازۀ قاعده‌ها برابر ۶ و ۸ است. اگر $M$ و $N$ وسط دو ساق ذوزنقه باشند، اندازۀ $MN$ چند برابر $EF$ است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:31:35', 5, 'done'),
(4669, 'در مثلث $ABC$ با طول اضلاع $AB = 2\\sqrt{2}$، $AC = \\sqrt{2}$ و $BC = \\sqrt{6}$ اگر $CH$ ارتفاع وارد بر ضلع $AB$ باشد، اندازۀ $AH$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:31:18', 5, 'done'),
(4670, 'در ذوزنقۀ $ABCD$، از نقطۀ $O$ محل تلاقی قطرها، خطی موازی قاعده‌ها رسم کرده‌ایم تا ساق‌ها را در $M$ و $N$ قطع کند. اگر مساحت مثلث $OCD$، $۲/۲۵$ برابر مساحت مثلث $OAB$ باشد، نسبت $\\frac{MN}{CD}$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:31:01', 5, 'done'),
(4671, ' اگر $\\frac{a}{10+a} = \\frac{b}{8+b}$ ، مقدار $\\frac{a}{b}$ کدام است؟', 2, 1, 54, 227, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:30:49', 5, 'done'),
(4672, 'در شکل روبه‌رو، $PQ || BC$ . طول پاره‌خط $PQ$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:30:31', 5, 'done'),
(4673, 'در شکل روبه‌رو، $CD$ نیمساز زاویۀ $C$ است. اگر $DE || BC$، حاصل $2DE + 3BC$ چقدر است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:29:35', 5, 'done'),
(4674, 'در مثلث $ABC$، داریم $NP || MB$ و $MN || AB$ . طول $AM$ چقدر است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:29:19', 5, 'done'),
(4675, ' با توجه به شکل روبه‌رو، حاصل $AC + DE$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:29:02', 5, 'done'),
(4676, ' در ذوزنقه $ABCD$، پاره‌خط $MN$ با قاعده‌های $AB$ و $CD$ موازی است. مقدار $x$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:28:50', 5, 'done'),
(4677, ' در مثلث قائم‌الزاویه $ABC$، داریم: $\\frac{BC}{AC} = \\frac{5}{3}$. اگر ارتفاع $AH$ را رسم کنیم، حاصل $\\frac{BH}{CH}$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:28:06', 5, 'done'),
(4678, ' در شکل روبه‌رو، از نقطه دلخواه N بر روی میانه AM، پاره‌خط NP را به موازات AB و پاره‌خط NQ را به موازات AC رسم می‌کنیم. حاصل $\\frac{BM}{CM} + \\frac{MP}{MQ}$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:27:49', 5, 'done'),
(4679, ' کدام گزینه دارای مثال نقض نیست؟', 2, 1, 54, 226, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:27:36', 5, 'done'),
(4680, 'هر سه ضلع مثلث $A\'B\'C\'$ با 3 ضلع مثلث $ABC$ موازی است. اگر $B\'C\' = 4$ ، $BC = 7$ و مثلث $A\'B\'C\'$ به‌طور کامل درون مثلث $ABC$ قرار داشته باشد، مساحت ناحیۀ محدود بین دو مثلث، چند برابر مساحت مثلث کوچک‌تر است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:27:23', 5, 'done'),
(4681, ' در شکل روبه‌رو، $AH$ ارتفاع وارد بر وتر مثلث $ABC$ می‌باشد، حاصل $\\frac{1}{AH + AB}$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:27:09', 5, 'done'),
(4682, 'در شکل روبه‌رو فاصلۀ نقطۀ $O$ تا نقطۀ $A$ کدام است؟', 2, 1, 54, 226, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:26:56', 5, 'done'),
(4683, ' در شکل روبه‌رو، $\\hat{N} = \\hat{C}$ . مقدار $x + y$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:25:04', 5, 'done'),
(4684, ' در مستطیل $ABCD$ مطابق شکل امتداد $AN$ و $BM$ یکدیگر را قطع کرده‌اند. مساحت مثلث $OAB$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:24:49', 5, 'done'),
(4685, 'طول و عرض مستطیل $ABCD$ به ترتیب برابر 8 و 6 است. فاصلۀ رأس $A$ از قطر $BD$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:24:36', 5, 'done'),
(4686, ' در شکل روبه‌رو مقدار x کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:24:20', 5, 'done'),
(4687, 'در ذوزنقۀ $ABCD$، ساق $AD$ را به سه قسمت مساوی تقسیم کرده‌ایم. اگر چهار پاره‌خط افقی موجود در شکل موازی باشند و نسبت دو قاعدۀ ذوزنقۀ $ABCD$ برابر $\\frac{1}{7}$ باشد، نسبت دو مساحت سایه‌زده کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:23:52', 5, 'done'),
(4688, ' در شکل روبه‌رو، دو پاره‌خط $AB$ و $CD$ موازی هستند. اگر مساحت دو مثلث $AOD$ و $DOC$ به‌ترتیب برابر $6$ و $18$ باشد، مساحت چهارضلعی $ABCD$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:23:42', 5, 'done'),
(4689, ' در مستطیل روبه‌رو دو پاره‌خط $AN$ و $DM$ بر هم عمود هستند. اگر $BM = 5$ و $CN = 1$، طول $MN$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:23:29', 5, 'done'),
(4690, ' در شکل روبه‌رو، مساحت ذوزنقۀ ABMN دو برابر ذوزنقۀ NMCD است. طول پاره‌خط MN کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:23:13', 5, 'done'),
(4691, 'در مثلث زیر خط $AD$ نیمساز رأس $A$ است. از نقطۀ $D$ خطی به موازات $AB$ رسم کرده‌ایم تا ضلع $AC$ را در $E$ قطع کند، اگر $AC = 30$ ، اندازه $EC$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:22:58', 5, 'done'),
(4692, 'در یک ذوزنقۀ متساوی‌الساقین اگر طول قاعده‌ها ۱۸ و ۳۰ و اندازۀ ساق آن ۱۰ باشد، امتداد ساق‌ها یکدیگر را در نقطۀ A قطع می‌کنند. فاصلۀ A تا قاعدۀ بزرگ‌تر ذوزنقه کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:22:45', 5, 'done'),
(4693, 'در شکل روبه‌رو عمودمنصف ضلع $AC$ ضلع $BC$ را در نقطۀ $D$ قطع می‌کند. طول پاره‌خط $BD$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:22:11', 5, 'done'),
(4694, ' در شکل روبه‌رو، قاعدۀ بزرگ ذوزنقه ۴ برابر قاعدۀ کوچک آن است. مساحت مثلث OAB چه کسری از مساحت ذوزنقه است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:21:49', 5, 'done'),
(4695, 'در شکل روبه‌رو اگر $AC = ۲BC$ و دو زاویۀ مشخص‌شده برابر هم باشند، مقدار $\\frac{y}{x}$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:21:34', 5, 'done'),
(4696, ' در شکل روبه‌رو چهارضلعی MNPB متوازی‌الاضلاع است و MB = ۲MA. مساحت مثلث سایه‌خورده چه کسری از مساحت مثلث ABC است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:11:00', 5, 'done'),
(4697, 'در مثلثی، اندازه دو ضلع $5$ و $13$ و تانژانت زاویه بین این دو ضلع $2/4$ است. نیمساز زاویه کوچکتر، مثلث را به دو جزء تقسیم می‌کند. مساحت جزء کوچکتر، چند درصد مساحت کل مثلث است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:10:43', 5, 'done'),
(4698, 'کدام جملات زیر درست است؟\n\nالف) هرگاه مثلث متساوی‌الاضلاع را به سه مثلث هم‌نهشت تقسیم کنیم، بزرگترین زاویه مثلث‌ها برابر $120^\\circ$ است.\n\nب) هرگاه در مثلث متساوی‌الساقین، زاویه بین دو ساق، $1$ رادیان باشد، قاعده بزرگترین ضلع است.\n\nج) در هر مثلث، نقاط تلاقی عمود منصف‌ها، مرکز دایره‌ای است که از سه راس مثلث می‌گذرد.\n\nد) در مثلث قائم‌الزاویه، زاویه بین دو نیمساز غیر قائمه $135^\\circ$ است.', 2, 1, 54, 226, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:10:30', 5, 'done'),
(4699, 'در شکل مقابل دو پاره‌خط موازی‌اند. $x$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:10:18', 5, 'done'),
(4700, 'در مثلث قائم‌الزاویه $ABC$ داریم: $\\hat{A} = 90^\\circ$، ضلع $AC = 11$ و $cos C = \\frac{11}{\\sqrt{170}}$. کوچکترین ضلع آن کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:09:55', 5, 'done'),
(4701, ' در صفحه یک مثلث چند نقطه وجود دارد که از هر سه ضلع آن به یک فاصله است؟', 2, 1, 54, 226, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:09:38', 5, 'done'),
(4702, ' اگر در مثلث قائم‌الزاویه‌ای وتر $7/5$، ارتفاع وارد بر وتر $3/6$ باشد، ضلع متوسط مثلث کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:09:27', 5, 'done'),
(4703, ' در مثلث $ABC$، فاصله پای ارتفاع واقع بر ضلع بزرگتر $BC = 10$، تا ضلع کوچکتر $AC = 2$ برابر واحد است. از $B$ بر امتداد $AC$، عمود $BH$ را رسم می‌کنیم. مساحت مثلث $BCH$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:09:15', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(4704, ' متوازی‌الاضلاع $ABCD$ با دو ضلع $12$ و $2$ زاویه $30^\\circ$ مفروض است. از رأس $C$ در خارج متوازی‌الاضلاع خطی رسم می‌کنیم، تا امتداد ضلع‌های $AB$ و $CD$ را به ترتیب در نقطه $K$ و $L$ قطع کند. حاصل $\\frac{BK}{AK} + \\frac{DL}{AL}$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:09:05', 5, 'done'),
(4705, ' در مثلث به اضلاع $1$، $\\sqrt{3}$ و $2$، طول نیمساز کوچک‌تر کدام است؟', 2, 1, 54, 226, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:08:53', 5, 'done'),
(4706, 'در مثلث $ABC$، $M$ و $N$ روی $AB$ و $BC$، $\\frac{AM}{MB} = \\frac{1}{3}$ و $\\frac{BN}{NC} = \\frac{1}{4}$ است. از $M$ خط $MP$ را به موازات $BC$ رسم می‌کنیم، مساحت مثلث $NPC$ چند برابر $AMP$ است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:08:45', 5, 'done'),
(4707, ' مطابق شکل اگر $AP = 1$ و $PN = 3$ و $NC = x$ و $PM || NB$ و $MN || BC$ باشد، نسبت $\\frac{BC}{MN}$ کدام است؟', 2, 1, 54, 228, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:08:28', 5, 'done'),
(4708, ' برای رسم یک خط موازی با خط داده شده از نقطه‌ای غیر واقع بر آن به کمک خط‌کش و پرگار، رسم چند کمان (دایره) با پرگار لازم است؟', 2, 1, 54, 226, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:08:17', 5, 'done'),
(4709, ' در شکل زیر $\\frac{AM}{MB} = \\frac{2}{3}$ و چهارضلعی $BMNF$ متوازی الاضلاع است. مساحت مثلث هاشورزده چند درصد مساحت مثلث $ABC$ است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:08:01', 5, 'done'),
(4710, ' نقطه $M$ روی نیم‌دایره‌ای به قطر $AB$ قرار دارد. اگر فاصله $M$ تا پاره‌خط $AB$ برابر $13/44$ و فاصله‌اش از دورترین سر قطر برابر $48$ باشد، طول قطر نیم دایره کدام است؟', 2, 1, 54, 226, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:07:46', 5, 'done'),
(4711, ' اگر در صفحه ذوزنقه‌ای که دو نیمساز زاویه‌های حاده یکدیگر را روی قاعده مقابل قطع می‌کنند، از برخورد دو ساق مثلث متساوی‌الاضلاع ایجاد شود، مساحت مثلث بزرگتر چند برابر مساحت ذوزنقه است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:07:26', 5, 'done'),
(4712, ' در شکل مقابل $x$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:07:09', 5, 'done'),
(4713, 'در مثلث $ABC$، دو ارتفاع $BH$ و $CH\'$ در نقطه $O$ همدیگر را قطع می‌کنند. اگر $OH = 2$، $OH\' = 4$ و $BH = 7$ باشد، ارتفاع وارد بر ضلع $AB$ کدام است؟', 2, 1, 54, 229, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:06:41', 5, 'done'),
(4714, 'در مستطیلی به اضلاع 8 و 15، اگر از یک راس بر قطر، ارتفاعی رسم شود، طول قطعه بزرگتر ایجاد شده بر قطر تقریباً کدام است؟', 2, 1, 54, 226, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 12:02:24', 1, '2026-04-05 17:06:26', 5, 'done'),
