(4816, '۷۶- اگر $f(x)=x^3+2|x|$ و $g(x)=|x|$ باشد، کدام گزینه در مورد تابع $\\frac{f}{g}$ صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4817, '۷۷- نمودار تابع $f(x)$ به صورت زیر است. نمودار تابع $g(x) = \\frac{|f(x)|}{f(x)}x^2$ چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4818, '۷۸- در مورد تابع $y = 3^{x+|x-1|}$ چندتا از جملات زیر صحیح است؟\n\nالف) روی $\\mathbb{R}$ اکیداً صعودی است.\n\nب) در بازه $(1, -\\infty)$ هم صعودی و هم نزولی است.\n\n\n\nج) در بازه $[1, +\\infty)$ صعودی است.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4819, '۷۹- اگر $f(x) = \\begin{cases} 2 & x > 0 \\\\ -1 & x < 0 \\end{cases}$ و $g(x) = 1-x$ باشد، نمودار تابع $g \\circ f$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4820, '۸۰- در صورتی که $(f \\circ g)(x) = \\frac{x}{x+1}$ و $g(x) = \\sqrt[3]{x}-1$ باشد، مقدار $f(\\sqrt{2})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4821, '۸۱- $f(x)$ کدام یک از توابع زیر باشد تا $[f(x)]$ تابع ثابت باشد؟ ($[ ]$ نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4822, '۸۲- اگر نمودار تابع $f(x)$ به صورت شکل مقابل باشد، نمودار تابع $g(x) = f(\\frac{x}{2})$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4823, '۸۳- اگر $f(x) = (a^2+3a-9)x$ تابع همانی و $g(x) = (a+c+1)x+ac$ تابع ثابت باشد، مجموع مقادیر ممکن برای $ac$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4824, '۸۴- اگر f تابع همانی و g یک تابع خطی و هم‌چنین رأس سهمی $y = (fg)(x)$ نقطه $(2 , -1)$ باشد، $\\frac{(f+g)(1)}{(f-g)(1)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4825, '۸۵- با فرض $f(x) = \\sqrt{x^2-x}$ و $g(x) = \\sqrt{x-x^2}$ و $f+g = \\{(m, n), (p, q)\\}$، مقدار $m+n+p+q$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4826, '۸۶- دامنه تابع $f(x) = \\sqrt{4x-x^2} - \\frac{x}{\\sqrt{x-3}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4827, '۸۷- برد تابع $f(x)$ به صورت $[0, k]$ و برد تابع $-2 f(x)$ به صورت $[0, 3 k+1]$ است. مقدار k کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4828, '۸۸- اگر $f = \\{(x, x+1) | x \\in \\mathbb{N}, x < 4\\}$ باشد، حاصل‌ضرب اعضای برد تابع $\\frac{f^2}{f+1}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4829, '۸۹- اگر نمودار دو تابع $f(x)$ و $g(x)$ به صورت زیر باشد، دامنه $(f \\circ g)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4830, '۹۰- اگر $f = \\{(x, 2x-1) | x \\in \\mathbb{N}, x \\leq 4\\}$ و $g = \\{(1, -1), (49, 2), (25, \\frac{a}{2})\\}$ و حاصل‌ضرب اعضای برد تابع $g \\circ f^2$ برابر -4 باشد، مقدار $g(25)$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4831, '۹۱- نمودار تابع $y = x^3$ را ابتدا یک واحد به سمت xهای منفی منتقل و سپس طول نقاط را نصف می‌کنیم تا تابع $h(x)$ به دست آید. تابع $h(x)$، تابع $g(x) = 7x^3+9x^2+3x+4$ را در یک نقطه با کدام طول قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4832, '۹۲- اگر $f(x) = x^2+x$ و $g(x) = x-1$ باشد، کوچک‌ترین ریشه معادله $(f \\circ g)(x) \\sqrt{(f \\circ g)(x)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4833, '۹۳- اگر برد تابع $g(x) = 2f(x-1)-1$ برابر $[-1 , 3]$ و برد تابع $g(1-3x)$ برابر $[a, a+b]$ باشد، مقدار b کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4834, '۹۴- اگر $f(x)$ به صورت شکل زیر باشد، مجموع صفرهای تابع $g(x) = f(\\frac{x}{2}) f(2x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4835, '۹۵- اگر نمودار $f(x)$ به صورت مقابل و $g(x) = f(2x)$ و $h(x) = \\cos x$ باشد، برد تابع $(g \\circ h)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4836, '۹۶- برد تابع $y = |x^2 - 2x|$ با شرط $ 0 \\leq x \\leq 3$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4837, '۹۷- وارون تابع $f(x) = x^5 + x + a - 1$ از نقطه $(2 , -1)$ می‌گذرد. اگر تابع f وارون خود را در نقطه $(b, b)$ قطع کند، مقدار $b^5$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4838, '۹۸- اگر $f(x) = \\sqrt{2x - 5} + \\frac{m}{2}$ و $(f^{-1} \\circ f)(x) = (f \\circ f^{-1})(x)$ باشد، مقدار m کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4839, '۹۹- در صورتی که $f(x) = \\sqrt{x-1} + 2$ و $g(x) = \\sqrt{2-x} + 3$ و $(g^{-1} \\circ f)(\\frac{a}{3}) = -7 $ باشد، $f(a-1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4840, '۱۰۰- اگر $h(x) \\cdot f(2x+1) - f(x-1) = 1$، $h(x) = \\frac{2x}{3x+1}$ باشد، مقدار $h^{-1}(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4841, '۱۰۱- تابع $f(x) = |x+2| - |x-2| - x$ در یک بازه صعودی اکید است. دامنه $f^{-1}(x)$ در این بازه کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4842, '۱۰۲- اگر $f(x) = \\frac{x}{x-1}$ باشد، نمودار تابع $(f \\circ f)(x)$ و $f^{-1}(x)$ در دو نقطه به طول‌های a و b متقاطع‌اند، $a+b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4843, '۱۰۳- اگر $f(x) = 3^{x+1} + 2$ و $f^{-1}(x) = A + \\log_B h(x)$ باشد، حاصل $A+B+h(4)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4844, '۱۰۴- تابع $f(x)$ با دامنه $\\mathbb{R}$ مفروض است. اگر به‌ازای هر x از دامنه $f(x+0/1) = f(x)$ باشد و هم‌چنین $g(x) = f(x) - f(2x) + x$، مقدار $g(63/1)$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4845, '۱۰۵- اگر $f(x) = \\sqrt[3]{x} + \\frac{2}{\\sqrt{x}}$ باشد، مقدار $f^{-1}(3) \\cdot f^{-1}(2)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4846, '۱۰۶- وارون تابع $f(x) = 3x - \\frac{2}{x}$ با دامنه $x < -1$، خط $y = x + 1$ را با چه طولی قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4847, '۱۰۷- اگر تابع پیوسته $f$ روی $\\mathbb{R}$ اکیداً صعودی و $f(-2) = 0$ باشد، دامنه تابع $y = \\sqrt{-xf(x)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4848, '۱۰۸- نمودار $f(x) = a(x + c)^3 - b$ به صورت شکل زیر است. طول نقطه برخورد تابع $g(x) = c(x + b + 1)^3 – 27 a$ با محور $x$ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4849, '۱۰۹- اگر تابع نمایی $f(x) = (\\frac{1+k}{4+k} + \\sin k)^x$ اکیداً نزولی باشد، حدود $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4850, '۱۱۰- در صورتی که $f(x) = \\begin{cases} 1 & x > 1 \\\\ -1 & x < 1 \\end{cases}$ و $g(x) = x^2 - 5$ باشد، نمودار تابع $(f \\circ g)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4851, '۱۱۱- اگر $f = \\{(1, 5), (3, a), (b, 5), (1, -1)\\}$ و $g = \\{(4, 1), (8, 3), (3, 3)\\}$ باشد و $(f \\circ f \\circ g) \\in (4, 5)$ و $(f \\circ g \\circ g) \\in (8, 9)$ باشد، حاصل $\\sqrt{5ab}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4852, '۱۱۲- اگر نقطه $ (11, 1) $روی وارون تابع $f(x) = ax^3 + x + a^2$ قرار گیرد، مقدار $a^2 + 1$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4853, '۱۱۳- اگر بزرگ‌ترین درجه چندجمله‌ای $P(x) = (x+1)^n - (x-2)^4 + 1$ برابر $n$ و ضریب بزرگ‌ترین درجه برابر $a$ باشد، $n+a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4854, '۱۱۴- تابع $f(x) = (a-2)x^3 - a^2x + 8$ فقط از نواحی دوم و چهارم عبور می‌کند، $\\frac{f(2)}{1+\\sqrt{2}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4855, '۱۱۵- کدام تابع از ناحیه اول عبور نمی‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4856, '۱۱۶- نمودار توابع $\\begin{cases} f(x) = -x^3 - 3x^2 - 3x \\\\ g(x) = \\log_2 x \\end{cases}$ در چه نقطه (نقاطی) متقاطع‌اند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4857, '۱۱۷- اگر تابع $f(x) = (1-x)^3 + m$ صعودی اکید باشد، حدود کامل $m$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4858, '۱۱۸- کدام تابع روی $\\mathbb{R}$ صعودی اکید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4859, '۱۱9- تابع $g(x) = \\begin{cases} 2x+5 & x \\le -2 \\\\ 3x-2 & x \\ge 1 \\end{cases}$ روی دامنه خود چگونه تابعی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4860, '۱20- کدام تابع زیر صعودی اکید است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4861, '121- وسیع‌ترین بازه‌ای که تابع $y = |x-1| - |x| + 2x$ در آن صعودی اکید باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4862, '۱۲2- اگر تابع $f(x) = \\begin{cases} \\sqrt{x} & 0 < x \\le 4 \\\\ ax+x+2 & 4 < x < 5 \\\\ b-1 & x \\ge 5 \\end{cases}$ در بازه $(0, +\\infty)$ ثابت باشد، $a+b$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4863, '۱۲3- اگر تابع $f(x) = \\frac{1-a}{4+a}x+a-1$ صعودی اکید باشد، این تابع از کدام ناحیه صفحات مختصات نمی‌گذرد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4864, '۱۲4- نمودار تابع $f(x)$ به صورت زیر است، تابع $f(1-x)$ به ترتیب از راست به چپ در کدام بازه صعودی اکید و در کدام بازه نزولی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4865, '۱۲5- اگر تابع نمایی $y = (\\frac{1-a}{a+1})^x$ صعودی اکید باشد، تابع $y = (a+1)^x$ چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4866, '۱۲6- تابع $y = |x|(x-1)$ در فاصله $[0, a]$ نزولی اکید است. حداکثر مقدار $a$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4867, '۱۲7- کدام تابع روی بازه‌های $(0, +\\infty)$ و $(-\\infty, 0)$ صعودی اکید است اما روی $\\mathbb{R} - \\{0\\}$ غیریکنوا است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4868, '۱۲8- اگر $f(x) = \\sqrt{1-x}$ باشد، جواب معادله $\\sqrt[2]{(f \\circ f)(x)} = f(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4869, '۱۲9- نمودار $f(x)$ به صورت زیر است و تابع $g(x) = f(1-2x)$ محور عرض‌ها را در نقطه $A$ قطع کرده است. فاصله نقطه $A$ از نقطه $B(-1, 0)$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4870, '۱30- اگر $f(x) = \\frac{\\log(x-2)}{x+1}$ و $g(x) = \\sqrt{x^2-4}$ باشد، دامنه تابع $(f \\circ g)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4871, '۱۳1- مساحت محدود به تابع $f(x) = 1 - ||x|-3|$ و محور $x$ها چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4872, '۱۳2- اگر $f(x) = x^3 + x$ و $g(x) = 4x$ باشد، مجموعه جواب نامعادله $(f \\circ g)(x) - (g \\circ f)(x) > 60$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4873, '۱۳3- اگر $f(x) = \\sqrt{x(2^{x^2} \\log_2 7) (3^x \\log_3 12) (6^x \\log_6 12)}$ و $g(x) = \\log_2(x^21)$ باشد، دامنه تابع $(f \\circ g)(x)$ از چند بازه تشکیل شده است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4874, '۱۳4- اگر $f(x) = \\frac{|x|}{x}$ و $g(x) = \\sqrt{x} + 1$ باشد، نمودار تابع $(g \\circ f)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4875, '۱۳5- اگر نمودار تابع $f(x) = \\sqrt{x}$ را ابتدا دو واحد در جهت $x$های مثبت و سپس ۳ واحد در راستای $y$های مثبت انتقال دهیم، نمودار حاصل تابع $g(x) = x+m$ را در نقطه‌ای به طول ۶ قطع می‌کند، تابع $(g \\circ g)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4876, '۱۳6- نمودار توابع $f(x) = \\cos(\\frac{1}{2}x)$ و $g(x) = |x|$ در ......... نقطه از بازه ......... متقاطع‌اند.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4877, '۱۳7- اگر $\\{(x, 2x^2-|x|) : x \\in \\mathbb{N}, -1 \\le x+1 \\le 5\\}$ و $g = \\{(\\frac{1}{3}, 4), (2, 8), (6, \\frac{1}{3})\\}$ باشد، حاصل ضرب اعضای دامنه و برد $g \\circ f$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4878, '۱۳8- به ازای چند مقدار $m$، درجه چندجمله‌ای $f(x) = x^{4-m} + 2$ از درجه چندجمله‌ای $g(x) = 2x^{2m-8} – 8 $ کوچک‌تر نیست؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4879, '۱۳9- معادله $|x+3|+x^2 = 1$ چند ریشه دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4880, '۱40- اگر تابع $f(x) = \\begin{cases} \\log x & x \\ge 1 \\\\ x+k & x \\le 0 \\end{cases}$ غیریکنوا باشد، حدود $k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4881, '۱۴1- تابع $y = (x^2+4x+3) \\frac{|x|}{x}$ در بازه $[a, b]$ نزولی اکید است. حداکثر مقدار $b-a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4882, '۱۴2- تابع $f(x) = \\sin 2x : x \\in [0, \\pi]$ در $n$ بازه و تابع $g(x) = \\cos \\frac{x}{2} : x \\in [0, 2\\pi]$ در $m$ بازه نزولی اکیدند. $m+n$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4883, '۱۴3- دامنه تابع $f(x) = \\frac{1}{x^3-3x^2-4x+k}$ به صورت $\\mathbb{R} - \\{-2, a, b\\}$ است. مقدار $a^2+b^2$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4884, '۱۴4- کدام تابع زیر ثابت نیست؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4885, '۱۴5- در شکل زیر سهمی $h(x) = x(2-x)$ و دو تابع خطی $f$ و $g$ در رأس سهمی متقاطع‌اند. دامنه تابع $m(x) = \\sqrt{f(x)+1} + \\sqrt{g(x)-1} + \\sqrt{h(x)-\\frac{3}{4}}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4886, '۱۴6- اگر $f(x) = x-|x|$ و $g(x) = 2x^2$ باشد، برد تابع $(\\frac{f}{g})(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4887, '۱۴7- اگر $f(x) = \\frac{2x-3}{3x-2}$ باشد، $(f \\circ f)(x) + (f \\circ f)(2x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4888, 'اگر $f(x) = x - [x]$ و $g(x) = \\sqrt{x+1}$ باشد، برد $(g \\circ f)(x)$ کدام است؟ ( [ ] نماد جزء صحیح است.)', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:02:39', 2, 'done'),
(4889, 'اگر $f(\\frac{x}{x^2+1}) = x^2 + \\frac{1}{x^2}$ باشد، $f(\\frac{1}{3})$ چقدر است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:03:38', 2, 'done'),
(4890, 'با توجه به ماشین مقابل اگر $f(x-1) = x+2$ باشد، $g(\\frac{1}{4})$ چقدر است؟\r\n\r\n$(x+1) \\rightarrow \\boxed{f} \\rightarrow \\boxed{g} \\rightarrow \\frac{1}{x}$', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:04:38', 2, 'done'),
(4891, '۱۵1- اگر $f(x) = x|x-2|$ باشد، نمودار $|f(x)|$ در کدام فاصله وارون‌پذیر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4892, 'اگر $f(x) = \\begin{cases} \\frac{2+x}{3} + a & x > 1 \\\\ x^2 + x & 0 < x \\le 1 \\end{cases}$ وارون‌پذیر و $(f \\circ f)^{-1}(2) = 1$ باشد، $a$ کدام است؟', 2, 1, 42, 181, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:09:44', 2, 'done'),
(4893, 'در صورتی که $f(x) = \\frac{\\sqrt{1-x}}{2}$ و $g(x) = \\frac{1}{1-x^2}$ باشد، آنگاه $D_{f \\circ g} \\cap D_{g \\circ f}$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:13:46', 2, 'done'),
(4894, '۱۵4- اگر $f(x)$ به صورت زیر باشد، $D_{f \\circ f}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4895, 'تابع $f(x) = |8x^3 + 12x^2 + 6x - 1|$ در بازه $[a, +\\infty)$ صعودی اکید است، حداقل مقدار $a$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:14:20', 2, 'done'),
(4896, ' اگر $x-[2-x] = 3$ باشد، وارون تابع $f(x) = |x-5|+x$ کدام است؟ ( [ ] نماد جزء صحیح است.)', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:17:37', 2, 'done'),
(4897, ' کدام تابع وارون‌پذیر نیست؟', 2, 1, 42, 182, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:18:04', 2, 'done'),
(4898, 'ضابطه وارون تابع $f(x) = |x| \\sqrt{-x} + 2$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:18:37', 2, 'done'),
(4899, '۱۵9- ضابطه وارون تابع زیر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4900, ' وارون تابع $f(x) = \\log_2(\\frac{2^x+1}{2^x-1})$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:06:46', 2, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(4901, ' اگر ورودی و خروجی دستگاه زیر با هم برابر باشند آن‌گاه $g(\\frac{1}{2})$ چقدر است؟\r\n\r\nورودی $\\rightarrow \\boxed{\\frac{1}{1+\\sqrt{x}}} \\rightarrow \\boxed{g(x)} \\rightarrow$ خروجی', 3, 1, 43, 190, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:19:26', 2, 'done'),
(4902, 'اگر نقطه $A(m, m-4)$ روی وارون تابع $f(x) = x^3+x-68$ قرار گیرد، مقدار $m$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:20:32', 2, 'done'),
(4903, '۱۶3- نمودار تابع $f(x)$ به صورت مقابل است. دامنه تابع $g(x) = \\sqrt{(x^2+1) \\cdot f^{-1}(x)}$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4904, 'اگر دامنه وارون تابع $f(x) = \\sqrt{x-2m}+2$ به صورت $[3, \\infty)$ باشد، $f^{-1}(1)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:21:04', 2, 'done'),
(4905, ' اگر تابع $f = \\{(m+n+1, 1), (0, -5), (m^2-\\sqrt{n}, -5), (2, 4), (m^2+\\sqrt{n}, 4)\\}$ یک‌به‌یک باشد، مقدار $ 2 m-n$ کدام می‌تواند باشد؟', 2, 1, 42, 181, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:21:34', 2, 'done'),
(4906, 'اگر $f(x) = 2x-b$ و $g(x) = x^2+3x-c$ و داشته باشیم $(f-g)(1)=4$، حاصل $(f-g)(2)$ چقدر است؟', 1, 1, 41, 175, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:22:09', 2, 'done'),
(4907, '۱۶7- اگر $f(x) = x^2 - 4$ و $g(x) = x - 2$ باشد، نمودار تابع $h(x) = |x| \\cdot (\\frac{f}{g})(x)$ چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4908, 'اگر $f(x) = x + 2$ و $g(x) = \\frac{x+3}{x-1}$ باشد، در چه بازه‌ای نمودار تابع $(f \\circ g)(x)$ پایین‌تر از نمودار تابع $(g \\circ f)(x)$ قرار می‌گیرد؟', 3, 1, 43, 187, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:26:21', 2, 'done'),
(4909, 'حدود $k$ کدام باشد تا تابع $g(x) = |x^2 - |x|| - k + 2$ محور $x$ها را در چهار نقطه قطع کند؟', 1, 1, 41, 184, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:27:56', 2, 'done'),
(4910, 'اگر بیشترین مقدار تابع $f(x) = (1 + \\frac{1}{m}) \\sin x + \\frac{2m+1}{m}$ برابر ۵ باشد، کم‌ترین مقدار تابع $g(x) = \\frac{m+1}{\\sqrt{m}} \\cos 2x - \\sqrt{2}$ چقدر است؟', 3, 1, 47, 206, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:29:16', 2, 'done'),
(4911, '۱۷1- اگر $f(x) = 2x - |x - 1|$ و $g(x) = |x + 2| - 2x$ باشد، تابع $h(x) = f(x) + g(x)$ در کدام فاصله اکیداً صعودی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4912, 'ضابطه وارون تابع $f(x) = x + 2\\sqrt{x}$ با شرط $x \\ge 4$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:29:51', 2, 'done'),
(4913, 'اگر $g(x) = \\frac{1}{4x-1}$ و $h(x) = \\sqrt{x-1}$ و $D_{g \\circ h} = [1, +\\infty) - \\{a\\}$ باشد، مقدار $ 16 a+1$ چقدر است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:30:23', 2, 'done'),
(4914, 'اگر $f(x) = \\begin{cases} 2x+1 & x \\ge 1 \\\\ x-1 & x < 1 \\end{cases}$ و $(f^{-1} \\circ f^{-1})(4) = 2+k$ باشد، مقدار $k$ کدام است؟', 3, 1, 43, 190, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:31:04', 2, 'done'),
(4915, ' اگر $f^{-1}(x) = \\log \\frac{1-x}{1+x}$ باشد، $f(2x)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:31:50', 2, 'done'),
(4916, 'اگر $x = \\frac{\\pi}{4}$ طول نقطه مینیمم تابع $f(x) = 2 \\cos(\\frac{3x}{x} + a)$ باشد، کدام نقطه نیز طول مینیمم تابع $f(x)$ خواهد بود؟', 3, 1, 47, 206, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:32:24', 2, 'done'),
(4917, 'کدام ترتیب زیر برای رسم تابع $g(x) = f(1-x) + 2$ از روی تابع $f(x)$ صحیح نیست؟', 1, 1, 41, 184, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:33:14', 2, 'done'),
(4918, 'به ازای یک مقدار صحیح $a$ تابع $f(x) = |(a+1)x+1| - \\frac{x}{2}$ اکیداً نزولی است، $f(2)$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:34:29', 2, 'done'),
(4919, '۱۷9- اگر $f(x)$ به صورت زیر باشد، نمودار تابع $g(x) = f(x) - f(2-x)+1$ چگونه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4920, '۱80- قسمتی از نمودار تابع $f(x) = a \\sin(bx + \\frac{\\pi}{4}) + c$ در شکل زیر آمده است. مقدار $\\frac{abc}{\\pi}$ چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4921, '۱۸1- اگر $f(x) = \\begin{cases} x & 0 \\le x < 1 \\\\ 1 & 1 \\le x < 2 \\end{cases}$ و $f(x) = f(x+2)$ باشد، مساحت بین تابع $f$ و خط $x+y=8$ و محور $x$ها چقدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, NULL, NULL, 'free'),
(4922, 'اگر $f(x) = \\tan(\\pi \\sqrt{x})$ باشد، با شرط $x \\le 36$ چند عدد صحیح در دامنه تابع $f$ قرار ندارند؟', 3, 1, 47, 206, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:35:35', 2, 'done'),
(4923, 'اگر درجه تابع $y = (3x^3 - 1)^3 - mx(x^4-1)^2 + 3$ نسبت به $x$، ۹ نباشد، درجه آن چند است؟', 3, 1, 43, 185, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:39:48', 2, 'done'),
(4924, 'اگر تابع $y = x - 2|k| + |x-1| + x$ صعودی اکید باشد، حدود $k$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:40:19', 2, 'done'),
(4925, 'اگر $f(x) = -x^2 + 1$ و $g(x) = \\begin{cases} 1 & x > 0 \\\\ 0 & x < 0 \\end{cases}$ باشد، برد $(f \\circ g)(x)$ کدام است؟', 3, 1, 43, 188, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:40:47', 2, 'done'),
(4926, ' اگر $f(x) = f^{-1}(x) = \\frac{ax+3}{x+a-1}$ باشد، $f(2) + f^{-1}(2)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:41:39', 2, 'done'),
(4927, 'اگر $f$ تابع همانی و $g$ تابع خطی غیر ثابت باشد، کدام تابع قطعاً غیر یکنواست؟', 3, 1, 43, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:42:18', 2, 'done'),
(4928, ' اگر تابع $f(x) = \\begin{cases} a - 2x^2 & x \\ge 0 \\\\ (2a - 1)x + 2 & x < 0 \\end{cases}$ اکیداً یکنوا باشد، حدود $a$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:43:15', 2, 'done'),
(4929, ' اگر وارون تابع $f(x) = x + 4\\sqrt{x}$ به صورت $f^{-1}(x) = x + a + b\\sqrt{x + 4}$ باشد، دوتایی $(a, b)$ کدام است؟', 2, 1, 42, 182, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:45:02', 2, 'done'),
(4930, ' اگر $f(x) = \\log_2 x$، ریشه معادله $(f^{-1} \\circ f)(x) = (f \\circ f^{-1})(x) - 4 - x^2$ کدام است؟', NULL, 1, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:47:28', 2, 'done'),
(4931, ' تابع درجه دوم $f(x) = a(x + 1)^2 + bx - k$ در نقطه‌ای به طول ۴- بر محور $x$ها مماس است. در صورتی که تابع $g(x) = 2x^2 + f(x)$ روی $\\mathbb{R}$ اکیداً نزولی باشد، $(f + g)(1)$ کدام است؟', 3, 1, 43, 186, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:48:23', 2, 'done'),
(4932, 'دامنه تابع $f(x) = \\frac{\\log(2x^2 + 7x + 5)}{\\sqrt{1 - x} + 6}$ کدام است؟', 1, 1, 41, 176, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:48:45', 2, 'done'),
(4933, 'اگر $f(x) = 2x + |x - 1|, x \\in [0, 2]$، در کدام بازه نمودارهای دو تابع $(f \\circ f^{-1})(x)$ و $(f^{-1} \\circ f)(x)$ بر هم منطبق‌اند؟', 3, 1, 43, 190, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:49:50', 2, 'done'),
(4934, ' تابع $f(x) = x^2 + x + 1$ را دو واحد به سمت $x$های منفی و یک واحد به سمت $y$های مثبت انتقال می‌دهیم تا تابع $g(x)$ به دست آید. وسیع‌ترین بازه‌ای که تابع $h(x) = (f + g)(x)$ زیر تابع $y = x^2$ قرار نمی‌گیرد، کدام است؟', 1, 1, 41, 267, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:06:18', 1, '2026-03-29 03:50:38', 2, 'done'),
(4935, ' اگر $f(x)=\\left\\lfloor-\\frac{5}{x}\\right\\rfloor|x^2-3x|$\r\n\r\n، مقدار $f\'(2)$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:51:42', 2, 'done'),
(4936, 'اگر $f(x)=\\sqrt{2-\\sqrt{4-9x^2}}$ مقدار $f\'_{-}(0)$ کدام است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:52:44', 2, 'done'),
(4937, 'مماس‌های رسم شده بر نمودار تابع $f(x)=|x|\\sqrt{x-a}$ در مبدأ مختصات بر هم عمود هستند. مقدار $a$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:53:11', 2, 'done'),
(4938, ' اگر $f(x)=2x^2-\\frac{1}{\\sqrt{x}}$، مشتق تابع $f\'of$ به ازای $x=1$ کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:53:46', 2, 'done'),
(4939, ' برای تابع پیوسته f، شرط $\\lim_{x \\to 1} \\frac{f(x)+1}{x^3-1} = -\\frac{2}{3}$ برقرار است. هرگاه $(gof)\'(1)=3$ باشد، مقدار $g\'(-1)$ کدام است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:54:48', 2, 'done'),
(4940, 'هرگاه $f$ تابعی یک‌به‌یک، $f(1)=1$ و $fof(x)=x^3+\\frac{2}{x}$، مقدار $f\'(1)$ کدام می‌تواند باشد؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:55:42', 2, 'done'),
(4941, 'تابع $f(x)=x+\\sqrt{x}$ با دامنه $[0,4]$ مفروض است. خط مماس بر $f$ در نقطه A با کدام طول به موازات وتری است که نقاط ابتدا و انتهای دامنه تابع را به هم وصل می‌کند؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:56:26', 2, 'done'),
(4942, 'با فرض $f(x)=2x^2+mx-3$ و $x \\in [-1,\\alpha]$، مقدار $\\alpha$ کدام باشد تا آهنگ تغییر متوسط تابع، در بازه داده شده، برابر آهنگ لحظه‌ای تابع $f(x)$ در $x=1$ باشد؟', 3, 1, 49, 215, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:57:13', 2, 'done'),
(4943, '۲۶- نمودار f به صورت مقابل است. به ازای کدام مقدار a تابع $g(x) = \\begin{cases} fof^{-1}(x-1) & x \\ge -1 \\\\ \\frac{1}{2}f^{-1}(x^2+a) & x < -1 \\end{cases}$ در $\\mathbb{R}$ پیوسته است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, NULL, NULL, 'free'),
(4944, '$f$ تابعی پیوسته است، به طوری که $\\lim_{h \\to 0} \\frac{f(3x-2h)-f(3x)}{h}=\\frac{1}{2x+1}$، مشتق $f(\\frac{4x}{x-1})$ به ازای $x=-1$ کدام است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:57:54', 2, 'done'),
(4945, 'هرگاه f تابعی پیوسته باشد و $\\lim_{x \\to 1} \\frac{f(x)+2}{x^2-1} = \\frac{3}{2}$، به طوری که $(gof)\'(1)=4$، مشتق $g(\\frac{2}{x})$ به ازای $x=-1$ چه عددی است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:58:55', 2, 'done'),
(4946, 'هرگاه $f(x)=(x-3|x|)[-7x]$، حاصل $f\'_{+}(0)-f\'_{-}(0)$ چه عددی است؟', 2, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 03:59:47', 2, 'done'),
(4947, '31- نمودار توابع خطی $y=f(x)$ و $y=g(x)$ طبق شکل روبه‌رو است. مشتق $fog$ در $x=2$ چند برابر مشتق $gof$ در $x=2$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, NULL, NULL, 'free'),
(4948, ' آهنگ تغییر متوسط $f(x)=x+\\frac{4}{x}$ در بازه $[1, \\alpha]$ با آهنگ تغییر لحظه‌ای در $x=3$ برابر است. مقدار $\\alpha$ کدام است؟', 3, 1, 49, 215, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:00:10', 2, 'done'),
(4949, 'اگر $f(x)=\\sqrt[3]{\\frac{2x+1}{x+2}}$، مشتق $f(\\frac{2}{x})$ به ازای $x=2$ چه عددی است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:00:38', 2, 'done'),
(4950, 'با فرض $f(x)=x-\\frac{a}{x}$ و $g(2x)=f(x^2)$، اگر $g\'\'(-2)=-3$ باشد، مقدار $a$ کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:01:04', 2, 'done'),
(4951, 'با فرض $f(x)=\\frac{x}{x+1}$، اگر در نقطه‌ای که مشتق اول و مشتق دوم با هم برابر هستند، بر $f$ مماس رسم کنیم، عرض از مبدأ خط مماس کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:01:32', 2, 'done'),
(4952, ' آهنگ تغییر متوسط تابع $f(x)=x^2+\\frac{k}{x}$، در بازه $[1,4]$ با آهنگ تغییر لحظه‌ای در $x=3$ برابر است، مقدار $k$ کدام است؟', 3, 1, 49, 215, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:02:01', 2, 'done'),
(4953, ' تابع $f(x)=\\begin{cases} |x| & |x|<1 \\\\ x^3+ax+b & |x|\\ge 1 \\end{cases}$ در $\\mathbb{R}$ پیوسته است. حاصل $2a-b$ کدام است؟', 2, 1, 44, 208, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:02:30', 2, 'done'),
(4954, '۶۸ - نمودار تابع $f$ در شکل مقابل داده شده است. اگر $(f\' - f)(a)$ عددی مثبت باشد، طول کدام یک از نقاط داده شده، $a$ است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, NULL, NULL, 'free'),
(4955, 'اگر $f\'(x)=\\frac{x^2}{x+2}$ به طوری که $g(x)=f(x+\\sqrt{x^2+3})$، مقدار $g\'(1)$ چه عددی است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:03:14', 2, 'done'),
(4956, 'با فرض $f(x)=\\left(\\frac{2x-3}{x-2}\\right)^2$، حاصل مشتق تابع $y=x\\sqrt[3]{f(x)}$ در نقطه $x=1$ چقدر است؟', 3, 1, 49, 210, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:04:08', 2, 'done'),
(4957, 'خط مماس بر تابع $y=\\frac{1}{x}$ در $x=2$، خط مماس بر این تابع در $x=a$ را در نقطه‌ای به طول $-4$ قطع می‌کند. $a$ کدام است؟', 3, 1, 49, 211, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:04:39', 2, 'done'),
(4958, '۱۰۳- نمودار مشتق تابع $y=f(x)$ در همسایگی $x=-1$ به صورت مقابل است. ضابطهٔ $f(x)$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, NULL, NULL, 'free'),
(4959, 'تابع $f(x)=x|x|[x]$ در فاصله $(-2,2)$ به ترتیب از راست به چپ در چند نقطه مشتق اول و مشتق دوم ندارد؟', 3, 1, 49, 214, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:05:03', 2, 'done'),
(4960, ' آهنگ متوسط تابع $f(x)=ax^2+bx+c$ در فاصله $[2,4]$ از آهنگ لحظه‌ای آن در $x=2$ ، $4$ واحد بیشتر است. آهنگ لحظه‌ای $f\'(x)$ در $x=2$ کدام است؟', 3, 1, 49, 215, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:05:27', 2, 'done'),
(4961, 'اگر $f(x)=\\sqrt[3]{x^2+1}$ و $g(x)=\\sqrt{x-1}$ باشد، حاصل $g\'^2(x)f\'\'\\circ g(x)+g\'\'(x)f\'\\circ g(x)$ در $x=8$ کدام است؟', 3, 1, 49, 213, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:06:42', 2, 'done'),
(4962, 'شیب خطی که از دو نقطه $A(3,f(3))$ و $B(x,f(x))$ می‌گذرد را محاسبه کرده و به جواب $\\frac{2-\\sqrt{x+1}}{4(x-3)}$ رسیده‌ایم. مشتق تابع $f(x)$ در $x=3$ کدام است؟', 3, 1, 49, 209, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:07:41', 2, 'done'),
(4963, '۱۱۲- با توجه به نمودار تابع $f(x)=\\sin x$ کدام‌یک از مقادیر زیر منفی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, NULL, NULL, 'free'),
(4964, ' اگر $y=2x-3$، خط مماس بر نمودار تابع $y=g(x)$ در نقطه‌ای به طول ۲ باشد و $\\lim_{x\\to 1}\\frac{f(x)-f(1)}{2x^2-3x+1}=\\frac{-4}{3}$ باشد، مقدار $(f \\circ g)\'(2)$ چه عددی است؟', 3, 1, 49, 212, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 15:20:02', 1, '2026-03-29 04:08:18', 2, 'done'),
(4965, ' اگر $2^{x-1}-2^{5-x}=31.5$ باشد، لگاریتم $$x+2 در پایه $4$ کدام است؟', 2, 1, 63, 253, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 19:04:49', 1, '2026-03-29 04:08:48', 2, 'done'),
(4966, 'برد تابع $f(x)=\\log_{\\frac{1}{3}}(\\sqrt{x}+9)$ کدام است؟', 2, 1, 63, 255, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 19:04:49', 1, '2026-02-27 22:58:39', 2, 'done'),
(4967, 'اگر مجموع لگاریتم ریشه‌های معادله $\\frac{1}{2} ،x^2-4x+a=0$ برابر لگاریتم مجموع ریشه‌های آن باشد، $a$ کدام است؟ (لگاریتم‌ها در مبنای $10$ می‌باشند.)', 2, 1, 63, 256, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-02-27 19:04:49', 1, '2026-02-27 22:54:47', 2, 'done'),
