(5019, 'غلظت یک داروی شیمیایی در خون، t ساعت پس از تزریق از رابطهٔ $c(t)=\\frac{3t}{t^3+54}$ به‌دست می‌آید. حداکثر مقدار غلظت دارو در خون کدام است؟', 3, 1, 50, 219, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, '2026-03-29 04:23:49', 2, 'done'),
(5020, '36. اگر $x=2$ طول یکی از نقاط بحرانی تابع $f(x)=ax+\\sqrt{5-x^2}$ باشد، مقدار a کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5021, '37. اگر تابع $f(x)=ax+bx^3$در نقطهٔ $A(1, -4)$ دارای اکسترمم نسبی باشد، کدام گزینه صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5022, '38. تابع $f(x)=x\\sqrt{32-x^2}$ در بازهٔ $(-a, a)$ صعودی اکید است. بیشترین مقدار a کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5023, '39. اگر مینیمم مطلق تابع $f(x)=x+2-\\sqrt{x}+a$ برابر $-\\frac{5}{4}$ باشد، مقدار a کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5024, '40. حداکثر مساحت یک مستطیل که دو رأس آن روی سهمی $y=9-x^2$ در ناحیه‌های اول و دوم قرار داشته و دو رأس دیگر آن روی محور طول‌ها می‌باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5025, '41. مطابق شکل، یک مستطیل که یک ضلع آن روی محور طول‌ها است، درون یک نیم‌دایره به شعاع ۶ قرار دارد. بیشترین مساحت این مستطیل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5026, '42. در شکل مقابل $AB = BC = AE = 1$ است. حجم شکل حاصل از دوران قسمت سایه‌زده، حول ضلع AE، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5027, '43. اگر بیشترین مقدار تابع $f(x)=2x+k-\\sqrt{5-x^2}$ برابر $4\\sqrt{5}$ باشد، جزء صحیح کمترین مقدار تابع f کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5028, '44. اگر اکسترمم نسبی تابع $y=ax+b\\sqrt{x}$ روی خط $y=x$ قرار داشته باشد، زوج‌مرتب $(a, b)$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5029, '45. حاصل‌ضرب کمترین و بیشترین مقدار تابع $f(x)=2\\sqrt{x}+\\sqrt{a-2x}$ برابر $4\\sqrt{3}$ است، مقدار a کدام است؟ $(a > 0)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:06:35', 1, NULL, NULL, 'free'),
(5030, '۱ تابع $f(x) = 3x^4 - x^3$ در کدام بازه صعودی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5031, '۲ مجموع ماکزیمم و مینیمم مطلق تابع $f(x) = x^2(x + 3) + 1$ در بازه $[-1, 1]$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5032, '۳ اگر تابع با ضابطه $f(x) = \\frac{ax + 6}{x + a + 1}$ در فاصله $(0, +\\infty)$ اکیداً نزولی باشد، چند مقدار صحیح برای $a$ وجود دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5033, '۴ نقاط بحرانی تابع با ضابطه $f(x) = |x - 20|\\sqrt[3]{x^2}$ سه رأس یک مثلث هستند. مساحت این مثلث کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5034, '۵ تابع $f(x) = |2x^2 - 1| + \\sqrt{|x|}$ چند نقطه بحرانی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5035, '۶ اگر $f(x) = x^3 - 4x + 1$ و $g(x) = 2(1 - \\cos x)(1 + \\cos x)$، آن‌گاه مجموع بیشترین و کم‌ترین مقدار تابع $y = (fog)(x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5036, '۷ مطابق شکل، نمودار مشتق تابع $f$ رسم شده است. اگر $AB = BC = 3$ و فاصله بین نقاط مینیمم نسبی تابع $f$ برابر با ۱۰ باشد، اختلاف مقادیر $f(A)$ و $f(C)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5037, '۸ نمودار تابع با ضابطه $f(x) = x^3 + ax^2 + bx + c$ به شکل زیر است. طول نقطه ماکزیمم نسبی تابع $f$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5038, '۹ اگر $f(x) = x + a$ و $g(x) = \\frac{x}{x^2 + x + 1}$، آن‌گاه تابع $f.g$ فقط یک نقطه اکسترمم نسبی خواهد داشت؛ طول این نقطه کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5039, '۱۰ اگر $M(2, 3)$ نقطه اکسترمم تابع با ضابطه $f(x) = ax + \\frac{b}{x - 1}$ باشد، برد تابع شامل چند عدد صحیح نیست؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5040, '۱۲ می‌خواهیم مخزنی به شکل مکعب‌مستطیل با قاعده مربع به حجم ۱۰ متر مکعب و در باز بسازیم. قیمت مصالح مورد نیاز کف برای هر متر مربع ۱۰۰ هزار تومان و برای دیوارهای کناری ۴۰ هزار تومان است. حداقل هزینه مصالح مورد نیاز برای ساخت این مخزن چند میلیون تومان است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5041, '۱۳ اگر مخروطی که فاصله رأس از نقاط محیط قاعده آن ثابت و برابر ۶ است، بیشترین مقدار حجم را داشته باشد، نسبت قطر قاعده به ارتفاع آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5042, '۱۴ بیشترین فاصله نقاط تابع $f(x) = x^3$ و $0 \\leq x \\leq 1$ از نیمساز ناحیه اول کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5043, '۱۵ یک ضلع مستطیلی بر محور xها و دو سر ضلع دیگر آن بر نمودارهای دو تابع $f(x) = \\sqrt{x}$ و $g(x) = \\sqrt{3 - x}$ قرار دارد. اگر سطح این مستطیل در ناحیه محدود به نمودارهای f، g و محور xها واقع باشد، بیشترین مقدار مساحت آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5044, '۱۶ نمودار مشتق تابع $f(x) = ax^4 + bx^2 + c$ رسم شده است. اگر عرض‌های نقاط بحرانی تابع f برابر با $1-$ و $1$ باشد، مساحت مثلثی که رأس‌های آن نقاط بحرانی تابع f هستند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5045, '۱۷ طول نقطه بحرانی تابع $f(x) = \\frac{1}{2}\\sqrt{x^2 + 9} - \\frac{1}{4}x$ در سمت راست محور yها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5046, '۱۸ اگر ماکزیمم و مینیمم مطلق تابع $g(x) = x^3 + 2x - 5$ در بازه $[-2, 1]$ را به ترتیب S و L بنامیم، مقدار $S - L$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5047, '۲۰ یک استوانه قائم، درون یک نیمکره به شعاع $2\\sqrt{3}$ قرار دارد. اگر حجم استوانه ماکزیمم باشد، سطح جانبی آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5048, '۲۱ اگر $x > 1$، آن‌گاه کم‌ترین مقدار عبارت $\\log_{\\sqrt{x}} 3 + 3\\log_9 x^3$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5049, '۲۲ در یک مثلث قائم‌الزاویه، مجموع وتر و یک ضلع قائم برابر ۹ است. ماکزیمم مساحت این مثلث کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5050, '۲۳ تابع $f(x) = x^2 - 2|x - 1|$ در بازه $(a, +\\infty)$ اکیداً یکنوا است. حداقل مقدار a کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5051, '۲۴ یکی از نقاط اکسترمم نسبی تابع $f(x) = x^3 + ax^2 + 9x + b$ بر خط $x = -1$ و نقطه اکسترمم نسبی دیگر بر خط $y = -1$ واقع است. حاصل $f\'\'(b)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5052, '۲۵ رأس یک مثلث متساوی‌الساقین، روی مبدأ مختصات قرار دارد و دو سر قاعده آن، روی منحنی $y = 6 - x^2$ هستند. بیشترین مساحت این مثلث کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5053, '۲۶ تابع $f(x) = (x^2 + a)\\sqrt[3]{x} + bx$ نقطه بحرانی ندارد. مجموعه مقادیر قابل قبول برای b کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5054, '۲۷ مستطیل‌هایی که مجموع طول قطر و یک ضلع آن‌ها ۶ است را در نظر می‌گیریم، ماکزیمم مساحت مستطیل‌هایی که طول اضلاع آن‌ها، مجذور اضلاع مستطیل مفروض‌اند، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5055, '۲۸ نمودار تابع $f(x) = x + a + \\sqrt[3]{1 + bx}$ به صورت مقابل است. عرض نقطه ماکزیمم نسبی چه قدر است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5056, '۲۹ در شکل مقابل اگر مثلث ABC متساوی‌الساقین و قاعده آن $BC = 12$ و ارتفاع وارد بر قاعده $AH = 10$ باشد، ماکزیمم مساحت مستطیل GFED برابر با کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5057, '۳۰ اگر تابع $f(x) = -2x^3 + 6x + 1$ روی بازه $(a, b)$ اکیداً صعودی باشد، بیشترین مقدار $b - a$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5058, '۳۱ بزرگ‌ترین بازه‌ای که تابع $f(x) = (x + a)\\sqrt{4 - x}$ روی آن نزولی اکید است، به صورت $[-3a, b]$ است. حاصل $a + b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5059, '۳۲ تابع $f(x) = \\frac{x^2 + 36}{\\sqrt{x + 3}}$ روی بازه $[a, +\\infty)$ اکیداً صعودی است. اگر مقدار a کم‌ترین مقدار ممکن باشد، مقدار $f(a)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5060, '۳۳ فاصله نقطه ماکزیمم نسبی نمودار تابع $f(x) = \\frac{x^2 + 3x}{x^2 + x + 2}$ از محور x کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5061, '۳۴ تابع f یک تابع چندجمله‌ای درجه‌سوم است که نمودار آن در شکل زیر رسم شده است. اگر خط $y = -2x - 2$ از اکسترمم‌های آن عبور کند، مقدار $f(1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5062, '۳۵ مختصات نقطه ماکزیمم نسبی تابع $f(x) = ax^2 - b|x|$ به صورت $(-2, 4)$ است. حاصل $a + b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5063, '۳۶ تابع $f(x) = \\frac{1 - x|x|}{x^2 + 4}$ چند نقطه بحرانی دارد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5064, '۳۷ اگر $x = 2$ طول نقطه بحرانی تابع $f(x) = ax + \\sqrt{5 - x^2}$ باشد، مقدار مینیمم مطلق آن کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5065, '۳۸ کدام عبارت در مورد تابع \n\n$f(x) = \\begin{cases} x^3 & ; 0 < x < \\sqrt{2} \\\\ 2\\sqrt{2} & ; x = 0 \\\\ 1 - x^2 & ; -\\sqrt{2} < x < 0 \\end{cases}$\n\nصحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5066, '۳۹ اگر اختلاف مقادیر ماکزیمم و مینیمم مطلق تابع $f(x) = ax(x^2 + 3x - 9)$ در بازه $[-4, 4]$ برابر ۵۴ باشد، مجموع مقادیر ماکزیمم و مینیمم نسبی این تابع کدام است؟ $(a > 0)$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5067, '۴۰ مساحت تمام مستطیل‌هایی را که مطابق شکل، محدود به نمودارهای دو تابع $y = \\sqrt{x}$ و $y = \\sqrt{6 - x}$ و محور xها هستند، حساب کرده‌ایم. بیشترین مقدار این مساحت‌ها کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5068, '۴۱ خط d محورهای مختصات را در نقاط $(8, 0)$ و $(0, 4)$ قطع کرده است، بیشترین مساحت مستطیل کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5069, '۴۲ تابع $f(x) = \\frac{x^4 + 8}{x^2 - 1}$ روی بازه $(0, \\alpha)$ اکیداً نزولی است. اگر $\\alpha$ بیشترین مقدار قابل قبول باشد، حاصل $f(\\alpha + 1)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5070, '۴۳ به ازای چند مقدار صحیح m، نقطه مینیمم نسبی تابع f با ضابطه $f(x) = \\frac{m - 5}{x^2 + 2x + m}$، مینیمم مطلق تابع هم می‌باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5071, '۴۴ سرعت شخص درون محوطه مستطیلی پارک برابر ۱ و روی محیط آن $\\sqrt{5}$ متر بر ثانیه است. کم‌ترین زمان برای رسیدن از نقطه A به نقطه C چند ثانیه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5072, '۴۵ مانند شکل زیر، یک رأس مستطیل روی نمودار $y = \\sqrt{4 - 2x}$ و رأس دیگر روی خط گذرنده از $(0, 2)$ و $(-1, 0)$ قرار دارد و دو رأس دیگر روی محور x است. بیشترین مساحت این مستطیل، به ازای کدام مقدار عرض آن حاصل می‌شود؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:17', 1, NULL, NULL, 'free'),
(5073, '۱- کدام گزینه همواره صحیح است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5074, '۲- حاصل ضرب مقادیر ماکزیمم و مینیمم مطلق تابع $f(x) = \\sqrt{4x^2 - 16x + 25}$ در بازه $[0, 3]$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5075, '۳- در شکل مقابل چند نقطه وجود دارد که اکسترمم نسبی هستند ولی اکسترمم مطلق نیستند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5076, '۴- نمودار مشتق تابع پیوسته $f$، به صورت مقابل است. تابع $f$ چند نقطه اکسترمم نسبی دارد؟ (دامنه تابع $f$، $\\mathbb{R}$ می‌باشد.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5077, '۵- اگر تابع $f(x) = \\begin{cases} 2x^3 - ax & x < 2 \\\\ bx + 4c & x \\ge 2 \\end{cases}$ فقط در $x = \\pm 1$ نقطه بحرانی داشته باشد، حاصل $2c + b + a$ برابر کدام گزینه است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5078, '۶- مساحت مثلثی که رئوس آن برابر نقاط اکسترمم نسبی تابع $f(x) = (1-x)\\sqrt[3]{x^2}$ می‌باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5079, '۷- در تابع با ضابطه $f(x) = x|x^2 - 12|$، شیب پاره‌خط بین نقطه ماکزیمم نسبی مشتق‌پذیر و نقطه مینیمم نسبی مشتق‌ناپذیر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5080, '۸- در تابع $f(x) = \\frac{-x^2 + 2ax + 6}{x - b}$ اگر $x = 2$ نقطه بحرانی آن باشد ولی اکسترمم نسبی آن نباشد، $a+b$ را $\\alpha$ می‌نامیم. مقدار $\\alpha$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5081, '۹- مجموع طول نقاط ماکزیمم نسبی و ماکزیمم مطلق و عرض نقاط مینیمم نسبی و مینیمم مطلق در نمودار زیر کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5082, '۱۰- اختلاف طول نقطه ماکزیمم و مینیمم تابع زیر کدام است؟\n\n$f(x) = \\frac{1}{3}x^3 + \\frac{1}{2}x^2 - 20x$', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5083, '۱۱- تابع $f(x) = \\frac{1}{2}x^4 - x^2 + 1$ در بازه $(-\\infty, a] \\cup [b, -a]$ نزولی است. حاصل $a-b$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5084, '۱۲- اگر مشتق تابع $f$ به صورت $f\'(x) = 3x^3(4 - 2x)^2(x+1)$ باشد، این تابع به ترتیب دارای چند نقطه ماکزیمم و مینیمم نسبی است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5085, '۱۳- به ازای مقداری منفی و صحیح از $a$، نمودار تابع $f(x) = \\frac{1}{3}x^3 + (a-2)x^2 + 9x + b$ روی $\\mathbb{R}$ اکیداً صعودی می‌باشد. $f\'(1)$ در این حالت کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5086, '۱۴- شکل زیر نمودار تابع به معادله $y = ax^3 + bx^2 - 8$ است. $a \\times k$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5087, '۱۵- تابع $f(x) = (-1)^{[x]} \\times (x - [x])$ مفروض است. کدام مورد درست است؟ ($[ ]$ : نماد جزء صحیح است.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5088, '۱۶- در تابع با ضابطه‌ی $f(x) = x|x| - 2x$، فاصله‌ی دو نقطه‌ی ماکزیمم نسبی و مینیمم نسبی آن، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5089, '۱۷- در مورد تابع $f(x) = \\frac{x}{|x|}(\\sqrt{4-x} + \\sqrt{2x+4})$ کدام مورد درست است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5090, 'دو برابر عددی از عدد دیگر ۶ واحد بیشتر است، اگر حاصل‌ضرب آن‌ها مینیمم باشد، مجموع آن دو عدد کدام است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:22:44', 3, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5091, ' از میان مثلث‌هایی که مجموع طول قاعده و ارتفاع وارد بر آن ۱۶ سانتی‌متر است، مثلثی را اختیار کرده‌ایم که مساحت آن ماکزیمم است. مساحت این مثلث چند سانتی‌متر مربع است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:18:13', 3, 'done'),
(5092, 'کمترین فاصله نقطه $A(4, 0)$ از نقاط منحنی به معادله $y = \\sqrt{2x + 9}$ کدام است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:17:09', 3, 'done'),
(5093, '۲۱- بیشترین مساحت مستطیلی که دو ضلع آن بر روی محورهای مختصات و رأس چهارم آن، بر روی منحنی به معادله‌ی $y = \\sqrt{12 - x}$، در ناحیه‌ی اول واقع شود، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5094, ' بیشترین مساحت زمینی مستطیل شکل که می‌توان آن را توسط یک طناب، از زمینی که یک طرف آن رودخانه است محصور نمود، ۶۴۸ متر مربع است، طول طناب چند متر است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:15:16', 3, 'done'),
(5095, 'می‌خواهیم یک استوانه‌ی قائم بسازیم که حجم آن برابر $54\\pi$ باشد. شعاع قاعده‌ی استوانه چقدر باشد تا مساحت کل آن مینیمم شود؟', 3, 1, 50, 220, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:13:34', 3, 'done'),
(5096, '۲۵- خط مماس بر نمودار تابع $f(x) = -\\frac{1}{3}x^3 + 2x^2 - x$ با بیشترین شیب ممکن، محور $y$ ها را با کدام عرض قطع می‌کند؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-19 23:03:38', 2, 'done'),
(5097, 'تابع $f(x) = \\frac{x^2}{4} - a\\sqrt{x+2}$ در فاصله $[2, +\\infty)$ اکیداً صعودی است و در هیچ‌یک از زیر مجموعه‌های بازه $(-2, 2)$ اکیداً صعودی نیست. $a$ چه مقداری خواهد بود؟', 3, 1, 50, 216, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:13:02', 3, 'done'),
(5098, ' تابع $f(x) = (x-1)^2 \\sqrt[3]{x-a}$ دارای ۳ نقطه بحرانی به طول‌های ۱، $a$ و ۷ می‌باشد، مساحت مثلثی که با این ۳ نقطه بحرانی تشکیل می‌شود، کدام است؟', 3, 1, 50, 217, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:11:26', 3, 'done'),
(5099, ' اگر $A(1, 2)$ در $f(x) = ax + \\frac{b}{x+1}$ اکسترمم نسبی داشته باشد، عرض اکسترمم دیگر آن کدام است؟', 3, 1, 50, 218, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, '2026-03-20 14:10:14', 3, 'done'),
(5100, '۲۹- نمودار مشتق تابع پیوسته $f(x)$ به صورت مقابل است. طول نقطه $\\min$ نسبی تابع $g(x) = -f(2-x)$ کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:45', 1, NULL, NULL, 'free'),
(5101, 'اگر مجموع یک قطر و یک ضلع مستطیل برابر ۹ باشد، بیشترین مساحت این مستطیل کدام است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-20 14:09:04', 3, 'done'),
(5102, '۳۱- شخصی با سرعت ۴ متر بر ثانیه از نقطه P به نقطه B رفته و سپس با سرعت ۱۲ متر بر ثانیه به نقطه C می‌رود. حداقل زمان ممکن برای این حرکت تقریباً چند ثانیه است؟ ($\\sqrt{2} \\simeq 1/4$)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, NULL, NULL, 'free'),
(5103, 'نمودار تابع $f$ به صورت روبه‌رو است. تعداد نقاط بحرانی تابع $f$ چند برابر تعداد نقاط مینیمم نسبی آن می‌باشد؟', 3, 1, 50, 217, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-22 17:44:09', 5, 'done'),
(5104, ' اگر مقدار ماکزیمم و مینیمم مطلق تابع $f(x) = x^3 - 3x + k - 6$ در بازه $[0, 3]$ قرینه هم باشند، مقدار $k$ کدام است؟', 3, 1, 50, 219, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-20 14:07:51', 3, 'done'),
(5105, ' مجموع طول نقاط بحرانی تابع با ضابطه $f(x) = \\sqrt[3]{x(x^2 - 7)}$ کدام است؟', 3, 1, 50, 217, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-20 14:06:41', 3, 'done'),
(5106, '۳۵- تعداد مقادیر صحیح ممکن برای $k$ که به‌ازای آن تابع $f(x) = \\frac{kx - 6}{-x + k + 5}$ در بازه $(-1, 4)$ اکیداً نزولی باشد، کدام است؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-11 22:20:22', 2, 'done'),
(5107, ' به ازای کدام مقدار $a$، نقطه مینیمم نسبی تابع $f(x) = \\frac{x^2 + ax + 9}{x^2 + x + 3}$ روی محور طول‌هاست؟', 3, 1, 50, 218, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-20 14:05:03', 3, 'done'),
(5108, '۳۹- تابع $f(x) = \\begin{cases} mx - [mx] ; [mx] = 2k \\\\ mx - [mx] - 1 ; [mx] = 2k + 1 \\end{cases}$ روی بازه $(0, 8)$، دارای ۱۵ نقطه بحرانی است. اگر $k \\in \\mathbb{Z}$ باشد، آن‌گاه مقدار $m$ کدام می‌تواند باشد؟', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-11 13:42:08', 2, 'done'),
(5109, ' اگر $A(3, -\\frac{25}{3})$ نقطه مینیمم نسبی تابع $f(x) = ax^3 - x^2 - 3x + b$ باشد، مختصات ماکزیمم نسبی $f(x)$ کدام است؟', 3, 1, 50, 218, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-10 16:28:55', 2, 'done'),
(5110, 'اگر $\\{-\\frac{1}{2}, 2\\}$ مجموعه نقاط بحرانی تابع $f(x) = ax^3 - bx^2 - 2x + 1$ باشد، مقدار مینیمم مطلق این تابع در بازه $[0, 3]$ کدام است؟', 3, 1, 50, 219, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-10 16:22:53', 2, 'done'),
(5111, ' کمترین فاصله نقاط منحنی $y = \\sqrt{x+2}$ از مبدأ مختصات کدام است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-10 16:39:26', 2, 'done'),
(5112, ' اگر نقطه $(-2, 29)$ اکسترمم نسبی تابع $f(x) = x^3 + ax^2 + bx + 1$ باشد، حاصل $a+b$ کدام است؟', 3, 1, 50, 218, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-10 16:31:05', 2, 'done'),
(5113, 'مطابق شکل مثلث $OAB$ در منحنی $y = \\sqrt{2 - x^2}$ به گونه‌ای قرار گرفته است که یک رأس آن روی مبدأ مختصات و دو رأس دیگر آن روی منحنی قرار دارد. اگر مساحت قسمت هاشور خورده کمترین مقدار ممکن باشد، اندازه میانه وارد بر ضلع $AB$ کدام است؟', 3, 1, 50, 220, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-02 11:07:46', 1, '2026-03-10 16:28:43', 2, 'done'),
(5114, ' با توجه به شکل‌های زیر که سه عنصر از دوره سوم جدول دوره‌ای را نشان می‌دهند، کدام موارد از مطالب زیر درست است؟\n\n\n\n\n\nالف) مولکول عنصر $C$، در دمای $200^{\\circ}C$، می‌تواند با گاز هیدروژن واکنش دهد.\n\nب) رسانایی الکتریکی عنصر $A$، بیشتر از رسانایی الکتریکی سومین عنصر گروه چهاردهم جدول تناوبی است.\n\nپ) طول موج نور ساطع‌شده از واکنش عنصر $X_{19}$ و $C$، بلندتر از طول موج نور ساطع‌شده از واکنش عناصر $A$ و $C$ است.\n\nت) در اتم عنصر $B$، شمار الکترون‌های موجود در زیرلایه $n=3, l=0$، $1/5$ برابر شمار الکترون‌های موجود در زیرلایه $l=1$ است.', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:47:04', 4, 'done'),
(5115, ' عنصر $X$ در دوره پنجم قرار دارد و دارای دو الکترون ظرفیتی است. اگر شعاع اتمی این عنصر برابر ۲۱۵ پیکومتر باشد، شعاع اتمی عنصرهای $Y_{37}$ و $Z_{20}$، به ترتیب از راست به چپ، کدام اعداد بر حسب پیکومتر می‌توانند باشند؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:47:09', 4, 'done'),
(5116, ' کدام مطلب نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:32:55', 4, 'done'),
(5117, ' با توجه به نمودار زیر که تغییرات شعاع اتمی سه عنصر نخست دوره‌های دوم و سوم جدول تناوبی را نشان می‌دهد، کدام موارد از مطالب داده شده نادرست است؟\n\nالف) عنصر $F$ در دوره دوم قرار دارد و عدد اتمی آن برابر ۵ است.\n\nب) واکنش‌پذیری عنصر $B$ از واکنش‌پذیری عنصرهای $A$ و $E$، بیشتر است.\n\nپ) نسبت شمار آنیون به شمار کاتیون در اکسید عنصر $C$، سه برابر نسبت شمار کاتیون به شمار آنیون در اکسید عنصر $D$ است.\n\nت) مجموع اعداد کوانتومی اصلی و فرعی الکترون‌های عنصر $E$، با مجموع اعداد کوانتومی اصلی و فرعی الکترون‌های ظرفیت عنصر $B$ برابر است.', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:00', 4, 'done'),
(5118, ' نمودار زیر، روند کلی واکنش‌پذیری چهار عنصر متوالی دوره دوم جدول تناوبی را نشان می‌دهد؛ با توجه به این نمودار، می‌توان دریافت که ..................... .', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:05', 4, 'done'),
(5119, ' اگر تفاوت تعداد نوترون‌ها و الکترون‌ها در یون $^{106}X^{2+}$ برابر تعداد عناصر با نماد شیمیایی دوحرفی موجود در ردیف چهارم جدول تناوبی باشد، بین این عنصر و سومین فلز قلیایی جدول دوره‌ای، چند عنصر وجود دارد؟', 2, 3, 68, 277, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:09', 4, 'done'),
(5120, ' ۱۰ گرم از یک فلز قلیایی یا قلیایی خاکی به طور کامل با آب واکنش می‌دهد. اگر پس از انجام واکنش، $18/5$ گرم هیدروکسید فلز تولید شود، فلز مورد نظر کدام است؟ ($Li=7, Na=23, Mg=24, Ca=40 : g.mol^{-1}$) (فرآورده دیگر واکنش، گاز هیدروژن است.)', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:13', 4, 'done'),
(5121, ' با توجه به واکنش‌های زیر، کدام مورد درست است؟\n\nI) $FeCl_2(aq) + 2NaOH(aq) \\rightarrow X + 2NaCl(aq)$\n\nII) $Y + 3NaOH(aq) \\rightarrow 3NaCl(aq) + Fe(OH)_3(s)$\n\nIII) $2Fe_2O_3(s) + 3C(s) \\rightarrow 4Z(s) + 3CO_2(g)$', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:17', 4, 'done'),
(5122, ' اگر در نمونه‌ای ناخالص از کلسیم کربنات به جرم ۲۵۰ گرم، ۳۶ گرم کلسیم وجود داشته باشد، درصد خلوص این نمونه کدام است و اگر به این نمونه، ۱۶۰ گرم کلسیم کربنات با خلوص $37/5\\%$ اضافه کنیم، به تقریب چند درصد جرم نمونه نهایی را ناخالصی تشکیل می‌دهد؟ (در ناخالصی‌ها، کلسیم وجود ندارد و $Ca=40, O=16, C=12 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:21', 4, 'done'),
(5123, ' با توجه به معادله داده شده، اگر ۱۶۰ گرم هیدرویدیک اسید با مقدار کافی پتاسیم پرمنگنات واکنش دهد و جرم فرآورده اکسیژن‌دار تولیدی برابر $1/8$ گرم باشد، بازده درصدی واکنش کدام است؟ ($H=1, O=16, I=127 : g.mol^{-1}$) (معادله واکنش موازنه نشده است.)\n\n$KMnO_4(s) + HI(aq) \\rightarrow MnI_2(aq) + H_2O(l) + KI(aq) + I_2(s)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:26', 4, 'done'),
(5124, ' با توجه به نمودار زیر که مربوط به تغییرات شعاع اتمی عناصر در دوره سوم است، کدام موارد درست است؟\n\nالف) جمع جبری بار یون‌های پایدار عنصرهای مورد نظر برابر صفر است. \n\nب) حالت فیزیکی عناصر $F$ و $G$ در دمای اتاق، برخلاف رنگ آن‌ها متفاوت است.\n\nپ) آرایش یون پایدار عنصر $D$ همانند عنصر $E$ به گاز نجیب آرگون می‌رسد.\n\nت) عنصر $F$ به شکل آزاد در طبیعت یافت می‌شود و اتم آن، ۶ الکترون ظرفیتی دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:31', 4, 'done'),
(5125, ' کدام موارد از مطالب زیر، به یقین درست‌اند؟\n\nالف) اولین هالوژن جدول دوره‌ای که لایه الکترونی چهارم آن اشغال می‌شود، در دمای $25^{\\circ}C$ با گاز هیدروژن واکنش می‌دهد.\n\nب) آرایش الکترونی کاتیون‌های حاصل از فلزهای واسطه به آرایش الکترونی گاز نجیب نمی‌رسند.\n\nپ) بدون در نظر گرفتن گاز نجیب، در عناصر دوره دوم جدول، بیشترین اختلاف شعاع اتمی بین لیتیوم و فلوئور است.\n\nت) مجموع $(n+l)$ الکترون‌های ظرفیتی عنصر گازی دوره چهارم جدول برابر ۳۳ است.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:36', 4, 'done'),
(5126, ' اگر در واکنش مقدار کافی کربن با $Fe_2O_3$ که برای استخراج آهن در فولاد مبارکه استفاده می‌شود، ۲۸ تن آهن تولید شود، به تقریب چند تن آهن (III) اکسید با خلوص ۷۵ درصد، مصرف شده است؟ ($Fe=56, O=16, C=12 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:40', 4, 'done'),
(5127, ' با توجه به جایگاه چند عنصر که در جدول تناوبی زیر نشان داده شده است، کدام گزینه درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:45', 4, 'done'),
(5128, ' کدام مورد درست است؟ ($X$ = فلز واسطه، $Y$ = فلز اصلی)', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:50', 4, 'done'),
(5129, ' اگر $m$ گرم نیتروگلیسیرین با خلوص ۶۰ درصد مطابق واکنش زیر تجزیه شود و حجم گاز نیتروژن تولیدشده برابر $3/6$ لیتر باشد، $m$ کدام است؟ (بازده واکنش ۸۰ درصد و حجم مولی گازها در شرایط واکنش، $22/7$ لیتر است. $H=1, C=12, N=14, O=16 : g.mol^{-1}$)\n\n$C_3H_5(NO_3)_3(s) \\rightarrow H_2O(g) + CO_2(g) + N_2(g) + O_2(g)$ (معادله واکنش موازنه شود.)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:55', 4, 'done'),
(5130, ' توصیف زیر نشان‌دهنده ویژگی‌های یکی از عناصر جدول تناوبی است. ویژگی ذکر شده در کدام گزینه، در مورد آن درست است؟\n\n«عنصری با سطح صیقلی که در واکنش با فلوئور، الکترون از دست می‌دهد و شمار الکترون‌های ظرفیتی آن برابر شمار الکترون‌های ظرفیتی عنصری زردرنگ و جامد از دوره سوم است و آرایش یون پایدار اولین عنصر هم‌دسته با آن به گاز نجیب آرگون می‌رسد.»', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:33:59', 4, 'done'),
(5131, ' در اثر واکنش ۵ گرم کلسیم کربنات با مقدار کافی محلول هیدروکلریک اسید، به تقریب چند مولکول در فرآورده‌ها تولید می‌شود؟ (۲۰ درصد نمونه کلسیم کربنات را ناخالصی تشکیل می‌دهد و بازده درصدی واکنش برابر ۶۰ درصد است. $Ca=40, O=16, C=12 : g.mol^{-1}$) (معادله موازنه شود.)\n\n$CaCO_3(s) + HCl(aq) \\rightarrow CaCl_2(aq) + CO_2(g) + H_2O(l)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:04', 4, 'done'),
(5132, ' اگر جرم برابری گلوکز در واکنش‌های سوختن (واکنش I) و تخمیر بی‌هوازی آن (واکنش II) شرکت کند و اختلاف حجم کربن دی‌اکسید تولیدی در این دو واکنش برابر ۲۰ لیتر باشد، اختلاف جرم الکل و آب تولیدی در آن‌ها چند گرم خواهد بود؟ (بازده واکنش (I) دو برابر واکنش (II) است و حجم مولی گازها در شرایط واکنش، ۲۵ لیتر است. $H=1, C=12, O=16: g.mol^{-1}$)\n\nI) $C_6H_{12}O_6 + 6O_2 \\rightarrow 6CO_2 + 6H_2O$\n\nII) $C_6H_{12}O_6 \\rightarrow 2CO_2 + 2C_2H_5OH$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:09', 4, 'done'),
(5133, ' دانشجویی در آزمایشگاه یک نوار منیزیم را وارد محلول هیدروکلریک اسید می‌کند. با توجه به جدول زیر که پس از ناپدیدشدن نوار منیزیم به دست آمده است، جرم نوار منیزیم اولیه بر حسب گرم و بازده درصدی واکنش کدام است؟\n\n($Mg=24: g.mol^{-1}$)\n\n$Mg(s) + 2HCl(aq) \\rightarrow MgCl_2(aq) + H_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:14', 4, 'done'),
(5134, '۲۲- عنصر $A$ یکی از شبه‌فلزهای جدول تناوبی است. اگر در گروه شامل $A$، فقط یک عنصر نافلزی $X$ وجود داشته باشد، کدام مطلب درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:45:04', 5, 'done'),
(5135, ' اگر محلولی حاوی ۶ گرم سدیم هیدروکسید، $0/05$ مول کلریدی از آهن را رسوب دهد، رنگ رسوب تولیدشده و شمار الکترون‌ها با $l=2$ در کاتیون آهن موجود در محلول، کدام است؟ ($H=1, O=16, Na=23: g.mol^{-1}$)', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:19', 4, 'done'),
(5136, ' یک کود شیمیایی دارای آمونیوم سولفات ($(NH_4)_2SO_4$) و مقداری ناخالصی است. اگر درصد خلوص یون سولفات در این کود برابر $60\\%$ باشد، یک کیلوگرم از این کود، چند گرم نیتروژن برای گیاه تأمین می‌کند؟ (در ناخالصی‌ها یون سولفات و نیتروژن وجود ندارد؛ $S=32, O=16, N=14, H=1: g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:26', 4, 'done'),
(5137, ' درستی یا نادرستی مطالب زیر درباره نخستین فلز واسطه جدول دوره‌ای، به ترتیب چگونه است؟\n\n- در اتم آن، ۷ زیرلایه از الکترون پر شده‌اند.\n\n- تفاوت عدد اتمی آن با نخستین فلز قلیایی جدول، برابر عدد اتمی سومین گاز نجیب جدول است.\n\n- شمار الکترون‌های ظرفیتی آن با شمار الکترون‌های ظرفیتی نخستین عنصر دسته $p$ برابر است.\n\n- کاتیون حاصل از آن به آرایش پایدار گاز نجیب نمی‌رسد.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:30', 4, 'done'),
(5138, ' با توجه به معادله زیر، از تجزیه $4/05$ گرم واکنش‌دهنده (آمونیوم دی‌کرومات) با خلوص $60\\%$، چند لیتر گاز تولید می‌شود؟ (در شرایط انجام واکنش، حجم مولی گازها برابر ۲۵ لیتر است. معادله واکنش موازنه شود.)\n\n($Cr=52, O=16, N=14, H=1: g.mol^{-1}$)\n\n$(NH_4)_2Cr_2O_7(s) \\rightarrow N_2(g) + Cr_2O_3(s) + H_2O(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:35', 4, 'done'),
(5139, ' با توجه به واکنش‌های (I) تا (IV)، کدام موارد از مطالب زیر، درست است؟ ($Cu=64, F=19, Al=27, Li=7: g.mol^{-1}$)\n\nI) $Li + AlCl_3 \\rightarrow LiCl + Al$\n\nII) $C+S_8 \\rightarrow CS_2$\n\nIII) $Cu_2S + O_2 \\rightarrow Cu + SO_2$\n\nIV) $Al + CuSO_4 \\rightarrow Cu + Al_2(SO_4)_3$\n\nالف) مجموع ضرایب واکنش‌دهنده‌ها در واکنش‌های (II) و (IV)، یکسان است.\n\nب) اگر در واکنش (I) به جای $Li$ از $Ti$ استفاده کنیم، واکنش با سرعت کم‌تری انجام می‌شود.\n\nپ) آرایش الکترونی یون مس شرکت‌کننده در واکنش‌های (III) و (IV)، یکسان است.\n\nت) از واکنش ۹ گرم فلز آلومینیم با خلوص ۹۰ درصد با مقدار کافی محلول مس (II) سولفات، $8/28$ گرم فلز مس آزاد می‌شود.', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:40', 4, 'done'),
(5140, ' اگر $n+l$ برای $n$ الکترون بیرونی‌ترین زیرلایه اتم عنصر نافلزی $X$ برابر ۳ و مجموع $n+l$ برای همه الکترون‌های ظرفیتی آن برابر ۱۹ باشد، چند مورد از مطالب زیر به یقین در رابطه با عنصر $X$ درست است؟\n\n- در دوره سوم قرار دارد و $a=5$ است.\n\n- در دمای اتاق به صورت مولکول‌های دواتمی پایدار است.\n\n- در مقایسه با کلر، واکنش‌پذیری بیشتری دارد.\n\n- شعاع اتمی آن در مقایسه با گوگرد کوچک‌تر است.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:44', 4, 'done'),
(5141, ' اگر برای تهیه $3/01 \\times 10^{23}$ مولکول کربن مونواکسید مطابق واکنش زیر، به ۱۶ گرم $MO$ نیاز باشد، جرم مولی فلز $M$ چند گرم بر مول است؟ (بازده واکنش را ۷۵ درصد در نظر بگیرید؛ $O=16: g.mol^{-1}$)\n\n$2MO(s) + C(s) \\rightarrow 2M(s) + CO_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:48', 4, 'done'),
(5142, ' در دما و فشار یکسان، جرم یکسانی از دی‌نیتروژن پنتاکسید و آلومینیم در واکنش‌های زیر به طور کامل مصرف می‌شوند. اگر حجم گاز تولیدشده در واکنش II، چهار برابر حجم گاز اکسیژن تولیدشده در واکنش I باشد، نسبت بازده درصدی واکنش I به II کدام است؟ ($N=14, O=16, Al=27: g.mol^{-1}$)\n\nI) $2N_2O_5(s) \\rightarrow 4NO_2(g) + O_2(g)$\n\nII) $2Al(s) + 6HCl(aq) \\rightarrow 2AlCl_3(aq) + 3H_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:52', 4, 'done'),
(5143, ' دانش‌آموزی ترکیبی را به اشتباه ۵-اتیل-۲، ۴-دی‌متیل هگزان نام‌گذاری کرده است. نام درست ترکیب و شمار گروه‌های $CH_2$ آن کدام است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:34:57', 4, 'done'),
(5144, ' در دو ظرف جداگانه مول‌هایی برابر از یک آلکین و اتن را با مقدار کافی کلر واکنش می‌دهیم. اگر جرم فرآورده حاصل از واکنش آلکین با کلر به تقریب $2/12$ برابر جرم فرآورده حاصل از واکنش اتن با کلر باشد، شمار پیوندهای یگانه کربن - کربن این آلکین کدام است؟\n\n($C=12, Cl=35/5, H=1: g.mol^{-1}$)\n\n$C_nH_{2n-2} + 2Cl_2 \\rightarrow C_nH_{2n-2}Cl_4$\n\n$C_2H_4 + Cl_2 \\rightarrow C_2H_4Cl_2$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:02', 4, 'done'),
(5145, '۳۳- نام ساختار زیر کدام است و در آن، چند پیوند اشتراکی یگانه بین اتم‌ها وجود دارد؟\r\n\r\n$(CH_3)_3CH(CH_2)_2CH(C_2H_5)CH_3$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:47:58', 5, 'done'),
(5146, '۳۴- کدام مورد درست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:48:04', 5, 'done'),
(5147, ' در صنعت برای تهیه اتانول از هیدروکربنی گازی‌شکل که به عنوان عمل‌آورنده در کشاورزی کاربرد دارد، استفاده می‌شود. اگر اتانول مورد نیاز برای تهیه ۱ لیتر محلول ۶۰ درصد جرمی آن را بخواهیم از واکنش این هیدروکربن با آب به دست آوریم، به چند لیتر هیدروکربن گازی نیاز است؟ (چگالی محلول ضدعفونی‌کننده اتانول در آب را $0/92 g.mL^{-1}$ و حجم مولی گازها را ۲۴ لیتر در نظر بگیرید و $H=1, C=12, O=16 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:06', 4, 'done'),
(5148, ' با توجه به ساختارهای زیر، کدام گزینه درست است؟ ($H=1, C=12, O=16 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:11', 4, 'done'),
(5149, ' نام کدام آلکان‌ها با فرمول ارائه‌شده مطابقت دارد و اختلاف جرم مولی آن‌ها بر حسب گرم کدام است؟\n\n($H=1, C=12 : g.mol^{-1}$)\n\nالف) ۲، ۵-دی‌متیل هگزان $(CH_3)_2CH(CH_2)_2C(CH_3)_3$\n\nب) ۳، ۵-دی اتیل، ۲، ۳-دی‌متیل هپتان\n\n\n\nپ) ۲-اتیل، ۲، ۵-دی‌متیل هپتان $H_3C-CH-CH-CH_3$\n\n$C_2H_5 C_2H_5 C_2H_5$\n\nت) ۲، ۳، ۸، ۸-تتری‌متیل دکان $(CH_3)_3C(CH_2)_4CH(CH_3)CH(CH_3)_2$', 2, 3, 68, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:15', 4, 'done'),
(5150, ' با توجه به نمودار زیر که تغییر نقطه جوش آلکان‌های راست‌زنجیر را برحسب شمار اتم‌های کربن آن‌ها در فشار یک اتمسفر نشان می‌دهد، چند مورد از مطالب زیر درست‌اند؟ ($C=12, H=1: g.mol^{-1}$)\n\n- اگر آلکان A، ۶۷ پیوند اشتراکی داشته باشد، در دمایی به جوش می‌آید که ید می‌تواند با گاز هیدروژن واکنش دهد. \n\n- در دمای $420K$، سه آلکان به حالت گاز می‌باشند.\n\n- در دمایی که اوکتان به جوش می‌آید، آب نیز به حالت بخار یافت می‌شود.\n\n- با کاهش تعداد پیوندهای $C-C$، اختلاف نقطه جوش دو آلکان متوالی افزایش می‌یابد.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:22', 4, 'done'),
(5151, ' کدام گزینه در رابطه با واکنش نشان داده شده در شکل زیر، درست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:26', 4, 'done'),
(5152, ' از سوختن کامل یک مول از نوعی هیدروکربن، $89/6$ لیتر گاز در شرایط STP تولید می‌شود. کدام گزینه درباره این هیدروکربن نمی‌تواند درست باشد؟ (درصد جرمی کربن در این هیدروکربن، ۶ برابر هیدروژن است و $C=12, O=16, H=1 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:30', 4, 'done'),
(5153, ' مخلوطی به حجم ۱۰۰ لیتر از گازهای اتان و اتین را با مقدار کافی هیدروژن در یک ظرف دربسته ترکیب می‌کنیم تا واکنش(های) مربوطه به طور کامل انجام شود. چنان‌چه حجم مولی گازها برابر ۲۰ لیتر بر مول باشد، جرم مخلوط نهایی چند گرم خواهد بود؟ ($C=12, H=1: g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:36', 4, 'done'),
(5154, ' کدام موارد از مطالب زیر از نظر علمی صادق است؟\n\nالف) در صورتی که عنصر $X$ دارای رسانایی الکتریکی باشد، همه عنصرهای هم‌دوره و پیش از $X$ نیز رسانای الکتریسیته هستند.\n\nب) در صورتی که عنصرهای یک گروه، همگی رسانای الکتریسیته باشند، آن عناصر به یقین در دسته $p$ قرار ندارند.\n\nپ) خواص شیمیایی همانند خواص فیزیکی عناصر، در جدول تناوبی به صورت دوره‌ای تکرار می‌شوند.\n\nت) تنها گروهی در جدول تناوبی که عناصر آن همه حالت‌های فیزیکی در شرایط اتاق را شامل می‌شوند، شمار برابری عنصر مایع و گازی در خود دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:40', 4, 'done'),
(5155, '۴۳- توصیف زیر نشان‌دهنده یکی از عنصرهای جدول دوره‌ای است. کدام ویژگی در مورد این عنصر درست می‌باشد؟\r\n\r\n«عنصری از دسته $p$ که شمار الکترون‌های ظرفیت اتم آن، برابر مجموع اعداد کوانتومی اصلی و فرعی الکترون‌های ظرفیتی دومین فلز جدول تناوبی عنصرها است و تفاوت عدد اتمی آن با فلز به‌کاررفته در بدنه دوچرخه برابر ۸ است.»', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:49:42', 5, 'done'),
(5156, ' کدام موارد از مقایسه‌های زیر درست‌اند؟\n\nالف) رسانایی الکتریکی: چهارمین عنصر گروه چهاردهم > چهاردهمین عنصر دوره چهارم.\n\nب) نسبت شمار الکترون‌های با $n=3$ به شمار الکترون‌های با $l=2$: $Zn > Cr$.\n\nپ) شمار عنصرهای دارای سطح صیقلی: دوره سوم = گروه چهاردهم.\n\nت) شمار الکترون‌ها با $l=2$: فلزی واسطه که در تلویزیون رنگی کاربرد دارد > زنگ آهن.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:45', 4, 'done'),
(5157, '۴۶- کدام مطلب نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:50:12', 5, 'done'),
(5158, ' با توجه به اطلاعات داده‌شده در مورد گونه‌های A تا E، کدام گزینه نادرست است؟\n\nA: سومین عنصر تناوب سوم که خاصیت شکنندگی دارد.\n\nB: نخستین عنصری که سه لایه الکترونی پرشده از الکترون دارد.\n\nC: عنصری هم‌دوره با چهارمین فلز قلیایی خاکی که ۵ الکترون ظرفیتی با $l=1$ دارد.\n\nD: اولین عنصری که دو زیرلایه نیمه‌پر دارد.\n\nE: دومین عنصر دسته $p$', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:49', 4, 'done'),
(5159, ' محلولی حاوی یون‌های $Fe^{2+}$ و $Fe^{3+}$ در اختیار داریم. با اضافه‌کردن $27/2$ گرم سدیم هیدروکسید به این محلول، همه یون‌های آهن رسوب می‌کنند. اگر $14/4$ درصد جرمی رسوب حاصل‌شده سبزرنگ باشد، جرم رسوب قرمز آجری چند گرم است؟ ($Fe=56, Na=23, O=16, H=1: g.mol^{-1}$)', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:53', 4, 'done'),
(5160, ' چند مورد از عبارت‌های زیر نادرست است؟ ($A, B, X, Y$ فلزند.)\n\n$A + X_2O \\rightarrow AO + X$\n\n$XCl + B \\rightarrow BCl_2 + X$\n\n$BF_3 + Y \\rightarrow \\text{انجام نمی‌شود.}$\n\n- $B$ می‌تواند $Al$ و $Y$ می‌تواند $Zn$ باشد.\n\n- واکنش‌پذیری $A$ از $X$ و $B$ بیشتر است.\n\n- اگر عنصر $X$ در دسته $s$ باشد، عنصر $A$ به یقین جزء عنصرهای اصلی است.\n\n- استخراج عنصر $B$ از سنگ معدن آن به مراتب دشوارتر از $Y$ و $X$ است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:35:57', 4, 'done'),
(5161, ' مقدار معین سدیم نیترات مطابق معادله موازنه نشده زیر در ظرفی در باز تجزیه می‌شود. اگر در شرایط معین بازده واکنش ۶۰ درصد باشد و $9/6$ درصد از جرم مواد موجود در ظرف کاسته شود، درصد خلوص سدیم نیترات کدام است؟ (معادله موازنه شود.) ($Na=23, O=16, N=14 : g.mol^{-1}$)\n\n$NaNO_3(s) \\rightarrow NaNO_2(s) + O_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:01', 4, 'done'),
(5162, 'جرم‌های یکسانی از زنگ آهن با خلوص ۹۶ درصد و گلوکز با خلوص ۶۰ درصد مطابق واکنش‌های موازنه نشده I و II در دو ظرف در باز به طور جداگانه وارد واکنش می‌شوند. اگر در پایان واکنش کاهش جرم سامانه II، $\\frac{۲}{۳}$ برابر کاهش جرم سامانه I باشد، بازده درصدی واکنش I به تقریب چند برابر بازده درصدی واکنش II است؟ ($Fe=56, O=16, C=12, H=1 : g.mol^{-1}$)\n\nI) $Fe_2O_3(s) + C(s) \\rightarrow Fe(s) + CO_2(g)$\n\nII) $C_6H_{12}O_6(aq) \\rightarrow C_2H_5OH(aq) + CO_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:06', 4, 'done'),
(5163, ' مقداری از آلکان $X$ را در حضور اکسیژن کافی به طور کامل می‌سوزانیم. اگر جرم آب تولیدشده در این فرایند، $1/5$ برابر جرم آلکان مصرف‌شده باشد، چند ساختار مختلف می‌توان برای آلکان $X$ در نظر گرفت؟ ($O=16, C=12, H=1 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:13', 4, 'done'),
(5164, '۵۳- مجموع شماره شاخه‌های فرعی در نام‌گذاری کدام‌یک از آلکان‌های زیر براساس قواعد آیوپاک، کم‌تر است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:56:13', 5, 'done'),
(5165, ' با توجه به شکل‌های زیر که مربوط به دو آلکان راست‌زنجیر A و B در شرایط یکسان است، کدام مطلب نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:18', 4, 'done'),
(5166, ' اگر در اثر سوختن کامل نمونه‌ای شامل یک مول آلکان A و یک مول آلکین B که تعداد کربن برابری دارند، در مجموع ۱۴۴ گرم آب تولید شود، چند مورد از مطالب زیر درست است؟ ($Br=80, O=16, C=12, H=1 : g.mol^{-1}$)\n\n- از آلکان A می‌توان به عنوان سوخت فندک استفاده کرد.\n\n- اگر آلکان A و آلکین B راست‌زنجیر باشند، شمار گروه‌های $CH_3$ در آن‌ها برابر نخواهد بود.\n\n- در مجموع در اثر انجام دو واکنش، $179/2$ لیتر گاز در شرایط استاندارد تولید می‌شود.\n\n- اگر نمونه اولیه با استفاده از برم به طور کامل سیر شود، جرم نمونه به تقریب $3/86$ برابر می‌شود.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:23', 4, 'done'),
(5167, ' نام ساختار داده شده کدام است و جرم مولی آن، به تقریب، چند برابر جرم مولی «۳-اتیل-۲ و ۴-دی متیل پنتان» است؟ ($C=12, H=1: g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:29', 4, 'done'),
(5168, ' در نمونه‌ای شامل $8/1$ گرم از ترکیب مقابل، چند مول اتم کربن وجود دارد؟ ($C=12, H=1: g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:35', 4, 'done'),
(5169, ' اگر از سوختن کامل مخلوطی از اتن و اتین، $19/04$ لیتر گاز اکسیژن در شرایط STP، مصرف شده و حجم گاز کربن دی‌اکسید حاصل، $5/6$ لیتر کم‌تر از حجم گاز اکسیژن مصرفی باشد، در مخلوط اولیه جرم اتن چند برابر جرم اتین بوده است؟ ($C=12, H=1: g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:44', 4, 'done'),
(5170, ' اگر جرم مخلوطی از گازهای اتن و اتان در واکنش با مقدار کافی بخار آب، ۴۵ درصد افزایش پیدا کند، به ترتیب از راست به چپ درصد حجمی گاز اتن در مخلوط، چند برابر درصد حجمی گاز اتان بوده و یک نمونه ۵ گرمی از این مخلوط، شامل چند اتم هیدروژن است؟ ($O=16, C=12, H=1: g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:48', 4, 'done'),
(5171, ' چند مورد از مطالب زیر در مورد سیکلوهگزان، درست است؟\n\n- شمار پیوندهای $C-C$ در ساختار آن، برابر با شمار این پیوندها در ساختار نفتالن است.\n\n- همانند بنزن، در نفت خام وجود دارد، اما برخلاف آن، غیرآروماتیک است.\n\n- فرمول مولکولی آن مشابه ۱-هگزن بوده، اما نسبت به آن، واکنش‌پذیری کم‌تری دارد.\n\n- مجموع شمار اتم‌ها در هر واحد از آن، برابر با شمار اتم‌ها در هر واحد نفتالن است.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-09-29 15:36:52', 4, 'done'),
(5172, ' از واکنش ۱۲ گرم از یک هیدروکربن با $13/44$ لیتر گاز کلر در شرایط STP، یک ترکیب سیرشده حاصل می‌شود. فرمول مولکولی این ترکیب کدام است و $0/05$ مول از این هیدروکربن، با چند گرم گاز هیدروژن، به طور کامل سیر می‌شود؟ ($C=12, H=1: g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:13:48', 1, '2026-03-22 11:57:31', 5, 'done'),
(5173, ' به ترتیب از راست به چپ، چه تعداد از عناصر دورۀ سوم و گروه چهاردهم (تا دورۀ ششم) جدول تناوبی، در حالت جامد سطح درخشان دارند؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:36:56', 4, 'done'),
(5174, ' با توجه به جدول زیر که نمایانگر عناصر دورۀ سوم جدول تناوبی می‌باشد، چند مورد از عبارت‌های زیر درست هستند؟\n\nالف) $۳۷/۵$ درصد از این عناصر سطح براق و صیقلی دارند.\n\nب) تعداد عناصری که رسانایی گرمایی مناسبی دارند با عناصری که فاقد این ویژگی هستند برابر است.\n\nپ) در میان این عناصر، یک عنصر وجود دارد که سطح درخشانی داشته و در عین حال همواره در واکنش با دیگر عناصر الکترون به اشتراک می‌گذارد.\n\nت) در میان این عنصرها، دو عنصر نافلزی که رنگ مشابهی دارند، حالت فیزیکی یکسانی در دما و فشار اتاق دارند.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:01', 4, 'done'),
(5175, ' در دما و فشار اتاق، در ردیف سوم جدول دوره‌ای عنصرها، شمار فلزها چند برابر مجموع شمار عناصر نافلزی جامد و شبه‌فلزی است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:05', 4, 'done'),
(5176, ' عناصر $A$، $B$، $C$، $D$، $E$ و $F$ به‌ترتیب از راست به چپ، ۶ عنصر متوالی در چهار دورۀ اول جدول تناوبی هستند. اگر عنصر $D$، رسانای جریان الکتریکی نبوده و تمایل به گرفتن الکترون نداشته باشد، چند مورد از عبارت‌های زیر نادرست است؟ (نماد عنصرها فرضی است.)\n\n- اختلاف شعاع اتمی بین $E$ و $F$ از اختلاف شعاع اتمی بین $B$ و $C$ کمتر است.\n\n- $C$ برخلاف $B$ می‌تواند رسانایی الکتریکی داشته باشد.\n\n- اندازۀ بار یون پایدار $A$ با مجموع بار یون‌های پایدار $E$ و $F$ برابر است.\n\n- در شرایط یکسان، واکنش‌پذیری $E$ از $F$ بیشتر است.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:09', 4, 'done'),
(5177, ' با توجه به جدول زیر که بخشی از دوره‌های عنصرها را نشان می‌دهد، کدام گزینه در مورد مقایسۀ شعاع اتمی عناصر درست است؟ (نماد عنصرها فرضی است.)', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:13', 4, 'done'),
(5178, ' با توجه به آرایش الکترونی لایۀ ظرفیت یون‌های تک‌اتمی زیر، عبارت کدام گزینه درست است؟ (نماد عنصرها فرضی است.)\n\n$A^{۳+} : ۳s^۲ ۳p^۶$ , $B^{۳-} : ۳s^۲ ۳p^۶$ , $C^{۳+} : ۲s^۲ ۲p^۶$ , $D^{۲-} : ۲s^۲ ۲p^۶$', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:18', 4, 'done'),
(5179, ' حجم گاز کلر تولید شده از واکنش $۲۱۷/۵$ گرم نمونۀ ناخالص $MnO_۲$ با خلوص $۸۰$ درصد با مقدار کافی $HCl$، مطابق معادلۀ موازنه نشدۀ زیر برابر ۴۴۳۷۵ میلی‌لیتر می‌باشد. چگالی گاز کلر در شرایط آزمایش با یکای $g.L^{-۱}$ کدام است؟ ($Mn = ۵۵ , O = ۱۶ , Cl = ۳۵/۵ : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:22', 4, 'done'),
(5180, ' اگر برای تولید $۲۲/۴$ کیلوگرم آهن مطابق واکنش زیر، ۵۰ کیلوگرم آهن (III) اکسید ناخالص لازم باشد، درصد خلوص آهن (III) اکسید کدام است؟ (بازده درصدی واکنش برابر ۸۰ درصد است.) ($Fe = ۵۶ , O = ۱۶ : g.mol^{-1}$)\n\n$Fe_۲O_۳(s) + Ti(s) \\rightarrow Fe(s) + TiO_۲(s)$ (معادلۀ واکنش موازنه شود.)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:27', 4, 'done'),
(5181, ' کدام گزینه در رابطه با «واکنش ترمیت» درست است؟ ($Fe = ۵۶ , Al = ۲۷ : g.mol^{-1}$)', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:31', 4, 'done'),
(5182, ' مطابق معادلۀ نمادی (موازنه نشده) واکنش $Fe_۲O_۳(s) + C(s) \\xrightarrow{\\Delta} Fe(s) + CO_۲(g)$، از واکنش $۸۰۰$ گرم $Fe_۲O_۳$ با خلوص $۸۰$ درصد با مقدار کافی $C(s)$، چند لیتر گاز کربن دی‌اکسید در شرایط STP تولید می‌شود؟ ($Fe = ۵۶ , O = ۱۶ : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:36', 4, 'done'),
(5183, ' همۀ عبارت‌های زیر درست‌اند، به‌جز ...', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:42', 4, 'done'),
(5184, ' کدام موارد از مطالب زیر در رابطه با جدول مقابل که قسمتی از جدول دوره‌ای را نشان می‌دهد، درست است؟ (نماد عنصرها فرضی هستند.)\n\nالف) عنصر $E$ در واکنش با گاز اکسیژن یک ترکیب یونی با فرمول شیمیایی $E_۲O_۳$ تولید می‌کند. \n\nب) خصلت نافلزی عنصر $B$ از عنصر $C$ کمتر و از عنصر $F$ بیشتر است.\n\nپ) در دو عنصر از عناصر موجود در این جدول، همۀ زیرلایه‌های اشغال شده از الکترون پر هستند.\n\nت) در تشکیل یک مول ترکیب حاصل از واکنش شیمیایی بین $E$ و $C$، ۵ مول الکترون مبادله می‌شود.', 2, 3, 68, 279, NULL, NULL, NULL, NULL, NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:37:56', 4, 'done'),
(5185, ' کدام مطلب نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:01', 4, 'done'),
(5186, ' با توجه به جدول روبه‌رو، کدام‌یک از مقایسه‌های زیر درست است؟ (نماد عنصرها فرضی است.)', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:07', 4, 'done'),
(5187, ' در واکنش «$\\dots \\rightarrow M + X_۲$»، $M$ فلزی قلیایی و $X$ عنصری از گروه ۱۷ جدول دوره‌ای است مجموع عدد اتمی $M$ و $X$ کدام‌یک از اعداد زیر باشد تا شدت واکنش بیشتر باشد؟ ($M$ و $X$ در دوره‌های دوم تا پنجم جدول دوره‌ای قرار دارند.)', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:12', 4, 'done'),
(5188, ' چند مورد از عبارت‌های زیر نادرست است؟\n\nالف) با افزایش $n+l$ بیرونی‌ترین زیرلایه در گروه ۱ جدول دوره‌ای، واکنش‌پذیری آن‌ها کاهش می‌یابد.\n\nب) در هر دوره از جدول دوره‌ای، با افزایش عدد اتمی، شعاع اتمی کاهش یافته و شمار لایه‌های الکترونی ثابت می‌ماند.\n\nپ) هالوژنی که تفاوت عدد اتمی آن با سبک‌ترین گاز نجیب، برابر عدد اتمی نخستین عنصر گروه ۱۵ جدول دوره‌ای است، نسبت به سایر هالوژن‌ها واکنش‌پذیری بیشتری دارد.\n\nت) در بین عنصرها با نماد فرضی $A_۸$، $D_{۱۹}$، $E_{۳۵}$ و $C_{۱۷}$ کمترین شعاع اتمی مربوط به $C_{۱۷}$ می‌باشد.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:17', 4, 'done'),
(5189, ' با توجه به آرایش الکترونی گونه‌های داده شده، کدام گزینه درست است؟ (نماد عنصرها فرضی است.)\n\n$A : [Ne] ۳s^۲$ , $B : [Ne] ۳s^۲ ۳p^۵$ , $C^{۲-} : [Ar]$ , $D^{۳+} : [Ne]$', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:22', 4, 'done'),
(5190, ' همۀ گزینه‌های زیر درست‌اند، به‌جز ...', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:28', 4, 'done'),
(5191, ' کدام گزینه درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:42:22', 4, 'done'),
(5192, ' توصیف زیر بیان‌کنندۀ یکی از عناصر جدول تناوبی عنصرهاست. کدام ویژگی در مورد آن درست است؟\n\n«عنصری از دستۀ $p$ که شمار الکترون‌های با $l=۰$ آن برابر شمار الکترون‌های ظرفیت آن است و با نخستین شبه‌فلز گروه ۱۴ در یک دوره قرار دارد.»', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:34', 4, 'done'),
(5193, ' هر یک از نمادهای فرضی $A$، $D$ و $E$ به یکی از عنصرهای دورۀ سوم جدول دوره‌ای مربوط است. با توجه به جدول زیر کدام گزینه درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:38', 4, 'done'),
(5194, ' با توجه به عنصرهای داده شده، کدام مطلب داده شده درست است؟ (نماد عنصرها فرضی است.)', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:43', 4, 'done'),
(5195, ' نسبت شمار الکترون‌های با $l=۰$ به $l=۲$ در یون فلزی $A^{۲+}$ از دورۀ چهارم جدول تناوبی برابر $۱/۵$ می‌باشد. کدام مطلب زیر درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:49', 4, 'done'),
(5196, ' چند مورد از عبارت‌های زیر در مورد آزمایش شناسایی یون‌های آهن (II) و آهن (III) با استفاده از محلول کلرید آن‌ها و محلول سدیم هیدروکسید درست است؟\n\nآ) رسوب آهن (II) هیدروکسید تولید شده به رنگ قرمز - قهوه‌ای خواهد بود.\n\nب) همۀ فراورده‌های تولید شده در این دو واکنش با یکدیگر کاملاً متفاوت هستند.\n\nپ) آرایش الکترونی فشردۀ کاتیون رسوب سبز‌رنگ به صورت $[Ar] ۳d^۶$ است.\n\nت) تعداد مول مصرفی از $NaOH$ به ازای یک مول نمک آهن (III) بیشتر از مقدار مصرف آن به ازای یک مول نمک آهن (II) است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:54', 4, 'done'),
(5197, ' با توجه به واکنش‌های زیر، عبارت کدام گزینه نادرست است؟\n\n$I) MnO + Cr \\xrightarrow{\\Delta}$ واکنش انجام نمی‌شود.\n\n$II) Ca + MnO \\xrightarrow{\\Delta} CaO + Mn$\n\n$III) ۲Cr + ۳CuO \\xrightarrow{\\Delta} Cr_۲O_۳ + ۳Cu$\n\n$IV) Ag + CuO \\xrightarrow{\\Delta}$ واکنش انجام نمی‌شود.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:38:58', 4, 'done'),
(5198, ' چند مورد از عبارت‌های زیر درست است؟\n\nآ) هرگاه در ترکیب $Fe(OH)_n$ کاتیون آهن دارای ۶ الکترون با $l=۲$ باشد، $n$ برابر ۲ و این ترکیب قرمز - قهوه‌ای رنگ خواهد بود.\n\nب) در بین فلزهای نقره، آهن، سدیم، مس و لیتیم، کمترین و بیشترین واکنش‌پذیری به‌ترتیب مربوط به نقره و سدیم می‌باشد.\n\nپ) به‌طور کلی در هر واکنش شیمیایی که به‌طور طبیعی انجام می‌شود، واکنش‌پذیری فراورده‌ها از واکنش‌دهنده‌ها کمتر است.\n\nت) به دلیل واکنش‌پذیری بیشتر سدیم در مقایسه با آهن، برای تولید صنعتی آهن از سدیم استفاده می‌شود.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:01', 4, 'done'),
(5199, ' اتم عنصر $A$ دارای ۱۴ الکترون با $l=۱$ می‌باشد. کدام گزینه دربارۀ آن نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:05', 4, 'done'),
(5200, ' یون‌های $A^{۳+}$، $B^{۲-}$، $C^{-}$ و $D^{+}$ همگی آرایش الکترونی سومین گاز نجیب را دارند. کدام گزینه درباره این عناصر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:10', 4, 'done'),
(5201, ' کدام گزینۀ زیر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:14', 4, 'done'),
(5202, ' اتم عنصر $M$ دارای ۷ الکترون با $l=۰$ می‌باشد. کدام گزینه در مورد آن درست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:56:55', 4, 'done'),
(5203, ' با توجه به واکنش «$\\dots \\rightarrow M(s) + Fe_۲O_۳(s) \\xrightarrow{\\Delta}$»، چند مورد از عبارت‌های زیر، جملۀ داده شده را به‌درستی تکمیل می‌کنند؟\n\n«اگر این واکنش انجام‌پذیر باشد، $M$ ...»\n\nالف) می‌تواند نخستین عنصر گروه ۱۴ جدول دوره‌ای باشد.\n\nب) نمی‌تواند عنصری باشد که به شکل کلوخه‌ها و رگه‌های زرد لابه‌لای خاک یافت می‌شود.\n\nپ) می‌تواند عنصری فلزی از دورۀ سوم با کمترین یا بیشترین شعاع اتمی در بین فلزات دورۀ سوم باشد.\n\nت) نمی‌تواند نخستین عنصری باشد که سومین لایۀ الکترونی اتم آن دارای ۱۸ الکترون است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:57:31', 4, 'done'),
(5204, ' با توجه به شکل مقابل که بخشی از جدول تناوبی می‌باشد، چند مورد از عبارت‌های زیر نادرست هستند؟ (نماد عناصر فرضی می‌باشند.) \n\n- واکنش‌پذیری $B$ از $Z$ بیشتر و رسانایی الکتریکی $E$ از $D$ بیشتر است.\n\n- شعاع اتمی عنصر $Z$ از $X$ بیشتر و خصلت فلزی $A$ از $X$ بیشتر است.\n\n- عنصر $E$ حالت فیزیکی متفاوتی با عناصر هم‌دورۀ خود دارد و در دمای اتاق به آرامی با گاز هیدروژن واکنش می‌دهد.\n\n- در دورۀ سوم با صرف‌نظر از گاز نجیب، کمترین تفاوت شعاع اتمی بین عناصر $C$ و $Z$ است.\n\n- یکی از دگرشکل‌های عنصر $F$، در زیر آب نگهداری می‌شود.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:57:42', 4, 'done'),
(5205, ' مقدار ۱۰ گرم پتاسیم کلرات را حرارت می‌دهیم تا ۴۹ درصد آن طبق معادلۀ موازنه شدۀ $۲KClO_۳(s) \\rightarrow ۲KCl(s) + ۳O_۲(g)$ تجزیه شود. در پایان واکنش، جرم مخلوط جامد باقی‌مانده در ظرف، چند گرم است؟ $(O=۱۶, Cl=۳۵/۵, K=۳۹: g.mol^{-۱})$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:57:51', 4, 'done'),
(5206, ' مطابق واکنش زیر، اگر در اثر تخمیر بی‌هوازی $۱۰۸ g$ گلوکز با خلوص $\\%۲۵$، $۹/۲۴ g$ از جرم مواد موجود در ظرف کاسته شود، بازده درصدی واکنش چقدر است؟ (ناخالصی‌ها واکنش نمی‌دهند، واکنش موازنه شود، $C=۱۲, H=۱, O=۱۶: g.mol^{-۱}$)\n\n$C_۶H_{۱۲}O_۶(aq) \\rightarrow C_۲H_۵OH(aq) + CO_۲(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:08', 4, 'done'),
(5207, ' چه تعداد از موارد زیر درست است؟\n\nالف) با توجه به واکنش ترمیت، نقطه ذوب آهن از آلومینیم اکسید بیشتر است.\n\nب) واکنش هوازی تخمیر گلوکز به‌صورت مقابل است: $C_۶H_{۱۲}O_۶(aq) \\rightarrow ۲C_۲H_۵OH(aq) + ۲CO_۲(g)$\n\nپ) روش استفاده از گیاهان برای استخراج یکی از عناصری که آرایش الکترونی آن از قاعده آفبا پیروی نمی‌کند، به صرفه است.\n\nت) در استخراج $۱۰۰ kg$ آهن تقریباً $۳۰۰ kg$ منابع معدنی استفاده می‌شود.', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:15', 4, 'done'),
(5208, ' غلظت یون نیکل در یک نمونه گیاهی $۱۲۰۰ ppm$ است. از سوزاندن ۵ تن از آن نمونه گیاه، چند گرم نیکل استخراج می‌شود؟ (بازده استخراج نیکل $\\%۷۵$ است.)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:22', 4, 'done'),
(5209, ' به $۳۴/۲ g$ آلومینیم سولفات $(Al_۲(SO_۴)_۳)$ که ۱۰ درصد ناخالصی دارد، مقداری گرما می‌دهیم تا واکنش موازنه نشدۀ تجزیه $Al_۲(SO_۴)_۳(s) \\rightarrow Al_۲O_۳(s) + SO_۳(g)$ انجام شود. با فرض بازدهی ۷۵ درصد برای این واکنش، چند گرم فراورده گوگرددار تولید می‌شود؟\n\n(ناخالصی‌ها در واکنش شرکت نمی‌کنند، $Al=۲۷, S=۳۲, O=۱۶: g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:28', 4, 'done'),
(5210, ' چند گرم آلومینیم با خلوص $\\%۷۵$ را با هیدروکلریک اسید کافی واکنش دهیم تا گاز به‌دست آمده بتواند با $۱/۴$ گرم کربن مونوکسید واکنش کامل دهد؟ $(H=۱, O=۱۶, C=۱۲, Al=۲۷: g.mol^{-۱})$\n\n$Al(s) + HCl(aq) \\rightarrow AlCl_۳(aq) + H_۲(g)$ (موازنه شود)\n\n$H_۲(g) + CO(g) \\rightarrow CH_۳OH(l)$ (موازنه شود)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:35', 4, 'done'),
(5211, ' به ظرف سر باز حاوی $Fe_۲O_۳$ خالص مقدار کافی گاز $CO$ وارد می‌کنیم تا واکنش زیر با بازده $\\%۵۰$ انجام شود. اگر کاهش جرم ظرف واکنش ۹۶ گرم باشد، درصد جرمی فلز آهن جامد در مخلوط نهایی به تقریب چقدر می‌باشد؟\n\n$Fe_۲O_۳(s) + ۳CO(g) \\rightarrow ۲Fe(s) + ۳CO_۲(g)$\n\n$(Fe=۵۶, C=۱۲, O=۱۶: g.mol^{-۱})$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:44', 4, 'done'),
(5212, ' از تجزیۀ $m$ گرم پتاسیم نیترات با خلوص ۸۰ درصد مقدار $a$ مول پتاسیم اکسید تولید شده است. این مقدار پتاسیم اکسید به‌طور کامل با آب واکنش داده و سپس حجم محلول حاصل را به ۵۰۰ میلی‌لیتر رسانده‌ایم. اگر مولاریتۀ محلول حاصل برابر $۰/۴$ مول بر لیتر باشد، مقدار $m$ برحسب گرم و حجم گاز اکسیژن تولید شده در شرایط STP برحسب لیتر به‌ترتیب از راست به چپ کدام است؟ (ناخالصی‌ها در واکنش شرکت نکرده‌اند.)\n\n$(H=۱, N=۱۴, O=۱۶, K=۳۹: g.mol^{-۱})$\n\n$KNO_۳(s) \\rightarrow K_۲O(s) + N_۲(g) + O_۲(g)$ (معادلۀ موازنه شود.)\n\n$K_۲O(s) + H_۲O(l) \\rightarrow KOH(aq)$ (معادلۀ موازنه شود.)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:58:55', 4, 'done'),
(5213, ' در واکنش $۲HX \\rightarrow H_۲ + X_۲$ ، $X_۲$ یک هالوژن می‌باشد. با توجه به آن کدام مطلب نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:02', 4, 'done'),
(5214, ' هرگاه واکنش ترمیت را به‌صورت $M(s) + Fe_۲O_۳(s) \\rightarrow M_xO_y(s) + Fe(l)$ نشان دهیم. چند مورد از مطالب زیر دربارۀ آن درست است؟\n\nالف) مجموع ضرایب استوکیومتری مواد پس از موازنه با مجموع ضرایب استوکیومتری مواد در معادلۀ موازنه‌شدۀ سوختن کامل متان، برابر است.\n\nب) فلز $M$ با نخستین شبه‌فلز گروه ۱۴ جدول تناوبی هم‌دوره است.\n\nپ) اگر به‌جای $M$، فلز منیزیم قرار گیرد، واکنش با شدت کمتری انجام خواهد شد.\n\nت) مجموع شمارۀ گروه‌های دو عنصر $M$ و $Fe$ با عدد اتمی نخستین عنصر واسطه یکسان است.\n\nث) واکنش‌پذیری فلز $M$ از هر یک از فلزهای نقره، مس و باریم کمتر است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:09', 4, 'done'),
(5215, ' مقدار $۳۰ g$ آلومینیم ناخالص و $۳۰ g$ منیزیم ناخالص، به‌طور جداگانه با مقدار کافی هیدروکلریک اسید واکنش داده‌اند. اگر حجم گاز هیدروژن تولید شده در شرایط STP در هر دو واکنش یکسان باشد، نسبت درصد خلوص آلومینیم به درصد خلوص منیزیم کدام است؟\n\n(ناخالصی‌ها در واکنش شرکت نکرده‌اند.) $(Mg=۲۴, Al=۲۷: g.mol^{-۱})$\n\n$Al(s) + HCl(aq) \\rightarrow AlCl_۳(aq) + H_۲(g)$ (معادلۀ واکنش‌ها موازنه شود.)\n\n$Mg(s) + HCl(aq) \\rightarrow MgCl_۲(aq) + H_۲(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:16', 4, 'done'),
(5216, ' چگالی یک آلکان مایع $۰/۶۴۵ g.L^{-۱}$ می‌باشد. چنانچه برای سوختن کامل ۸۰ لیتر از آن $۶۳۸/۴$ لیتر هوا در شرایط STP لازم باشد، فرمول مولکولی آلکان موردنظر کدام است؟ (فرض کنید ۲۰ درصد حجم هوا اکسیژن باشد.) $(C=۱۲, H=۱: g.mol^{-۱})$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:23', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5217, ' چند مورد از مطالب زیر درست‌اند؟\n\nالف) در آلکان‌های مایع، با افزایش گران‌روی، میزان فراریت آن‌ها کاهش می‌یابد.\n\nب) آلکان با جرم مولی $۵۸ g.mol^{-۱}$ در دما و فشار اتاق به حالت گاز وجود دارد.\n\nپ) تعداد خطوط مورد استفاده در فرمول پیوند ـ خط مولکول ۲، ۵- دی‌متیل دکان برابر ۱۲ می‌باشد.\n\nت) در مولکول نخستین آلکان راست زنجیر که در دمای اتاق به‌صورت مایع است، ۱۶ جفت الکترون پیوندی بین اتم‌ها وجود دارد.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:30', 4, 'done'),
(5218, '46- کدام‌یک از نمودارهای زیر ویژگی نشان داده شده در برابر شمار اتم‌های کربن در آلکان‌ها را به نادرستی نشان می‌دهد؟\r\n\r\n(نمودارها تقریبی رسم شده‌اند.)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:38', 4, 'done'),
(5219, ' دمای جوش سه آلکان راست زنجیر B ،A و C داده شده است. با توجه به این جدول، کدام گزینه در مورد آن‌ها نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:46', 4, 'done'),
(5220, ' چگالی یک آلکان گازی در شرایطی که حجم مولی گازها ۲۵ لیتر بر مول می‌باشد، برابر $۷/۶۴ g.L^{-۱}$ است. از سوختن کامل ۱۳۲ گرم از این آلکان، چند گرم گاز کربن دی‌اکسید آزاد می‌شود؟ $(C=۱۲, H=۱, O=۱۶: g.mol^{-۱})$', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 14:59:53', 4, 'done'),
(5221, ' چند آلکان ۱۱ کربنه با ساختار متفاوت، دارای زنجیر اصلی ۷ کربنه و دو شاخه اتیل می‌توان رسم کرد؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:00', 4, 'done'),
(5222, ' به‌ترتیب از راست به چپ، نام آلکان زیر کدام است و با سوختن کامل $۰/۵$ مول از این آلکان در شرایطی که چگالی گاز اکسیژن برابر با $۱/۲۸ g.L^{-۱}$ است، اختلاف حجم گاز اکسیژن مصرف شده با مجموع حجم گازهای تولید شده (کربن دی‌اکسید و بخار آب) برابر با چند لیتر می‌شود؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:08', 4, 'done'),
(5223, ' نسبت شمار اتم‌های هیدروژن به کربن در یک آلکان برابر ۲/۵ است. چند مورد از مطالب زیر در مورد این آلکان درست است؟ $(C=۱۲, H=۱, O=۱۶: g.mol^{-۱})$\n\n- در دمای ۲۹۵ کلوین و فشار یک اتمسفر به‌صورت گازی می‌باشد.\n\n- نقطه جوش آن از پنتان کم‌تر است.\n\n- شمار اتم‌های هیدروژن در آن با شمار اتم‌های کربن در ۳، ۳- دی‌اتیل هگزان برابر است.\n\n- تفاوت جرم مولی آن با جرم مولی کربن دی‌اکسید برابر ۱۴ گرم بر مول می‌باشد.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:15', 4, 'done'),
(5224, ' چند مورد از مطالب زیر در رابطه با آلکان $CH_۳CH(CH_۳)CH(C_۲H_۵)(CH_۲)_۲CH_۳$ درست است؟ $(C=۱۲, H=۱: g.mol^{-۱})$\n\nالف) ۵۷ گرم از آن، $30.1 \\times ۱۰^{۲۲}$ مولکول دارد.\n\nب) نام این ترکیب براساس قواعد آیوپاک، به‌صورت ۳- اتیل- ۲، ۲- دی‌متیل بوتان است.\n\nپ) این ترکیب دارای دو اتم کربن است که به هیچ اتم هیدروژنی متصل نشده است.\n\nت) تعداد پیوندهای اشتراکی در آن ۵ برابر تعداد گروه‌های $CH_۲$ می‌باشد.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:22', 4, 'done'),
(5225, ' با توجه به واکنش داده شده، چند مورد از مطالب زیر درست‌اند؟ $(C=۱۲, H=۱: g.mol^{-۱})$\n\nالف) ترکیب A برخلاف ترکیب B، محلول برم مایع را بی‌رنگ می‌کند. \n\nب) نسبت جرمی C به H در ترکیب B کمتر از این نسبت در ترکیب A است.\n\nپ) برای نام‌گذاری ترکیب B شماره‌گذاری اتم‌های کربن زنجیر اصلی از دو طرف، تفاوتی ندارد.\n\nت) با مصرف ۱۱/۲ لیتر گاز هیدروژن در شرایط STP، ۴۳ گرم فراورده تولید می‌شود.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:28', 4, 'done'),
(5226, ' چند مورد از مطالب زیر درست‌اند؟ $(C=۱۲, H=۱, O=۱۶: mol^{-۱})$\n\nالف) تفاوت شمار پیوندهای اشتراکی در سومین عضو خانواده آلکین‌ها و دومین عضو خانواده آلکن‌ها برابر یک است.\n\nب) گاز عمل آورنده در کشاورزی با محلول برم مایع واکنش می‌دهد و آن را بی‌رنگ می‌نماید.\n\nپ) از واکنش ساده‌ترین آلکن با آب در محیط بازی، اتانول به‌دست می‌آید.\n\nت) تفاوت جرم مولی نفتالن و سیکلوهگزان با جرم مولی یکی از فراورده‌های حاصل از سوختن کامل آن‌ها برابر است.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:18', 4, 'done'),
(5227, 'از سوختن کامل $۰/۲$ مول از یک آلکان $۲۶/۴$ گرم کربن دی‌اکسید تولید شده است. کدام مطلب دربارۀ این آلکان نادرست است؟ $(C=۱۲, O=۱۶: g.mol^{-۱})$', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:36', 4, 'done'),
(5228, ' جرم $۰/۳$ مول از هیدروکربن $C_xH_y$ برابر $۲۵/۲$ گرم است. اگر نسبت جرمی کربن به هیدروژن در آن برابر ۶ باشد، کدام مطلب دربارۀ این هیدروکربن همواره درست است؟ $(H=۱, C=۱۲: g.mol^{-۱})$', 3, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-03-22 12:08:38', 5, 'done'),
(5229, ' اگر مجموع اعداد کوانتومی اصلی و فرعی برای الکترون‌های لایۀ ظرفیت عنصر A از دوره سوم جدول تناوبی برابر ۶ باشد، کدام عبارت درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:43', 4, 'done'),
(5230, ' با توجه به چهار عضو اول خانواده هالوژن‌ها، کدام موارد زیر درست هستند؟\n\nالف) واکنش‌پذیرترین نافلز جدول دوره‌ای در این گروه قرار دارد.\n\nب) در واکنش سدیم با عناصر این گروه، اگر به جای نافلز گاز از برم استفاده کنیم، شدت واکنش بیشتر می‌شود.\n\nپ) در دما و فشار اتاق تعداد عناصر گازی با مجموع تعداد عناصر جامد و مایع این گروه برابر است.\n\nت) ید در دمای اتاق به آرامی با گاز هیدروژن واکنش می‌دهد.\n\nث) شعاع اتمی، واکنش‌پذیری و دمای ذوب ید در مقایسه با برم به ترتیب بیشتر، کمتر و بیشتر است.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:50', 4, 'done'),
(5231, ' اطلاعات زیر در رابطه با هالوژن‌های B ،A و C داده شده است که در دما و فشار اتاق حالت‌های فیزیکی متفاوتی داشته، و به‌صورت متوالی در گروه خود قرار گرفته است.\n\nI) $A_۲ + ۲NaC(aq) \\rightarrow C_۲ + ۲NaA(aq)$\n\nII) $B_۲ + ۲NaA(aq) \\rightarrow A_۲ + ۲NaB(aq)$\n\nIII) $C_۲ + ۲NaA(aq) \\rightarrow$ واکنش نمی‌دهد\n\nبا توجه به آن‌ها، چه تعداد از موارد زیر در رابطه با هالوژن‌های مورد نظر درست بیان شده است؟\n\nآ) در آرایش الکترونی اتم A، زیرلایه‌های d خالی از الکترون هستند.\n\nب) بیش از ۴۰ درصد از الکترون‌های اتم B در لایه ظرفیت قرار دارد.\n\nپ) هالوژن C در دمای $۳۰۰^\\circ C$ با گاز هیدروژن واکنش می‌دهد.\n\nت) تفاوت عدد اتمی A و B برابر با ۱۸ است.\n\nث) مجموع n الکترون‌های لایه ظرفیت اتم C برابر با ۴۰ است.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:00:57', 4, 'done'),
(5232, ' ترکیب یونی دوتایی حاصل از دو عنصر X و Y را در نظر بگیرید که فرمول شیمیایی آن شامل سه یون است اگر آرایش الکترونی یکی از یون‌ها به نئون و دیگری به آرگون رسیده باشد، چه تعداد از موارد زیر همواره درست است؟\n\n* عنصرهای سازنده این ترکیب یونی در دو دوره متوالی جدول دوره‌ای قرار دارند.\n\n* ترکیب یونی حاصل، براساس عناصر جدول تناوبی، دو ترکیب متفاوت می‌باشد. (با در نظر گرفتن همه حالات برای X و Y)\n\n* یکی از این دو عنصر در دما و فشار اتاق مولکول‌های دو اتمی تشکیل می‌دهند.\n\n* اختلاف عدد اتمی این دو عنصر برابر ۵ است.\n\n* اتم هر یک از دو عنصر X و Y فاقد الکترون با عدد کوانتومی $l=۲$ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-03-22 12:10:05', 5, 'done'),
(5233, 'با توجه به انجام شدن واکنشهای I و II و انجام ناپذیر بودن واکنش III، چند مورد از مطالب زیر نادرست اند؟\n\nI) $AO + B \\rightarrow B_2O + A$\n\nII) $A + CuSO_4 \\rightarrow ASO_4 + Cu$\n\nIII) $B_2O + Zn \\rightarrow ZnO + B$\n\n- مجموع ضرایب مواد در معادله موازنه شده (I)، ۲/۵ برابر مجموع ضرایب فرآورده ها در واکنش (II) است.\n\n- شرایط نگهداری عنصر A نسبت به طلا دشوارتر است.\n\n- واکنش $B + Cu(NO_3)_2 \\rightarrow Cu + BNO_3$ به طور طبیعی انجام می پذیرد.\n\n- عنصر A می تواند عنصر Mg باشد.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:04', 4, 'done'),
(5234, ' درباره دو واکنش داده شده چند مورد از مطالب زیر درست است؟ ($C=12 , O=16 , H=1 , Na=23 , Fe=56 : g.mol^{-1}$)\n\nI) $FeO + 2Na \\xrightarrow{\\Delta} Na_2O + Fe$\n\nII) $C_6H_{12}O_6 \\xrightarrow{\\Delta} 2C_2H_5OH + 2CO_2$\n\nآ) در واکنش (I)، از نقره نیز می توان برای استخراج آهن استفاده کرد.\n\nب) به ازای مصرف ۱۱۵ گرم سدیم با خلوص ۴۰ درصد، ۵۶ گرم آهن تولید می شود.\n\nپ) نسبت درصد جرمی کربن در گلوکز به درصد جرمی کربن در اتانول، بیشتر از یک است.\n\nت) به ازای مصرف ۱۸۰ گرم گلوکز با بازده ۵۰ درصد، ۴۴ گرم کربن دی اکسید تولید می شود.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:10', 4, 'done'),
(5235, ' از تجزیه ۵۲/۵ گرم سدیم هیدروژن کربنات ($NaHCO_3$) با خلوص ۸۰ درصد چند لیتر گاز $CO_2$ با چگالی $1/1 g.L^{-1}$ تولید می شود و برای تولید همین مقدار گاز $CO_2$ در همان شرایط، به تقریب چند مول هگزان باید با گاز اکسیژن واکنش دهد؟ (بازده درصدی واکنش هگزان با اکسیژن ۷۵ درصد است.) (گزینه ها را از راست به چپ بخوانید.) ($Na=23 , C=12 , H=1 , O=16 : g.mol^{-1}$)\n\n(واکنش ها موازنه شوند.)\n\n$NaHCO_3(s) \\rightarrow Na_2CO_3(s) + CO_2(g) + H_2O(g)$\n\n$C_6H_{14}(l) + O_2(g) \\rightarrow CO_2(g) + H_2O(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:18', 4, 'done'),
(5236, ' در کدام یک از گزینه های زیر نام آلکان با ساختار رسم شده مطابقت ندارد؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:24', 4, 'done'),
(5237, ' جرم مولی آلکین X ، $\\frac{۲}{۵}$ جرم مولی آلکان Y است. اگر برای سوزاندن کامل یک مول از آلکان Y و آلکین X در مجموع ۱۵ مول اکسیژن لازم باشد، در مخلوطی شامل نیم مول از هر کدام از این دو هیدروکربن، چند پیوند کربن - کربن یگانه وجود دارد؟ ($C=12 , H=1 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:30', 4, 'done'),
(5238, ' با توجه به واکنش های روبه رو همه عبارت های زیر درست اند، به جز ...\n\n$I) C_2H_4(g) + H_2O(l) \\xrightarrow{\\text{کاتالیزگر}} A$\n\n$II) C_2H_4(g) + Br_2(l) \\rightarrow B$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:36', 4, 'done'),
(5239, ' چند مورد از عبارت های زیر با توجه به ترکیب داده شده نادرست است؟ ($C=12 , H=1 : g.mol^{-1}$)\n\nالف) نام آن ۳- اتیل - ۵ متیل هپتان است.\n\nب) جرم مولی آن ۳/۵۵ برابر جرم مولی پروپین است.\n\nپ) فرمول مولکولی آن با فرمول مولکولی ۲-۳ دی متیل اوکتان یکسان است.\n\nت) شمار گروه های $CH_2$ در مولکول آن ۱/۲ برابر شمار گروه های $CH_3$ است.\n\nث) اختلاف شمار پیوندهای کوالانسی با شمار پیوندهای C-C برابر ۲۱ است.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:42', 4, 'done'),
(5240, ' اگر نسبت جرم کربن به جرم هیدروژن در یک آلکان شاخه دار برابر با ۵/۴ باشد و دو شاخه فرعی متیل و یک شاخه فرعی اتیل در ساختار آن وجود داشته باشد، با توجه به ساختارهای متفاوت قابل رسم برای آن، کدام گزینه درست است؟ ($C=12 , H=1 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:48', 4, 'done'),
(5241, ' مطابق واکنش زیر (که یکی از واکنش های کتاب درسی است) کدام موارد از عبارت های زیر درست است؟\n\n\n\n\n\n\n\nآ) با ریختن قطعات خراشیده شده یک میخ آهنی زنگ زده در محلول $HCl$ محلولی سبز رنگ ایجاد می شود.\n\nب) واکنش مرحله ۱ به صورت: $Fe_2O_3(s) + HCl(aq) \\rightarrow FeCl_3(aq) + H_2O(l)$ می باشد.\n\nپ) محلول B همان محلول بی رنگ سدیم هیدروکسید است.\n\nت) رسوب A رسوب قهوه ای رنگ آهن (III) کلرید است.\n\nث) واکنش مرحله ۲ به صورت: $FeCl_3(aq) + NaOH(aq) \\rightarrow Fe(OH)_3(s) + NaCl(aq)$ می باشد.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:01:57', 4, 'done'),
(5242, ' توصیف زیر برای یکی از عنصرهای جدول به کار رفته است. کدام گزینه ویژگی این عنصر را به درستی بیان می کند؟\n\n«عنصری از دسته p که مجموع اعداد کوانتومی اصلی و فرعی الکترون های ظرفیتی آن برابر ۱۴ و هم چنین تعداد لایه های آن یک واحد کمتر از تعداد لایه های سومین عنصر هالوژن جدول تناوبی است.»', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:19', 4, 'done'),
(5243, ' اگر ۰/۰۴ مول هیدروکلریک اسید ($HCl$) با فلز روی واکنش دهد، نمک حاصل در واکنش با نقره نیترات با بازدهی ۸۸ درصد به تقریب چند گرم ماده نامحلول در آب تولید می کند؟ ($Ag=108 , Cl=35.5 : g.mol^{-1}$) (واکنش ها موازنه نیستند.)\n\n$Zn(s) + HCl(aq) \\rightarrow ZnCl_2(aq) + H_2(g)$\n\n$ZnCl_2(aq) + AgNO_3(aq) \\rightarrow AgCl(s) + Zn(NO_3)_2(aq)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:22', 4, 'done'),
(5244, ' اگر بازده درصدی واکنش تجزیه سدیم هیدروژن کربنات برابر ۸۰ درصد باشد، بر اثر تجزیه ۲۱ گرم نمونه ناخالص این نمک که شامل ۴۰٪ ناخالصی است، چند لیتر گاز با مولکول های قطبی آزاد می شود؟ (چگالی گاز کربن دی اکسید برابر $2/2 g.L^{-1}$ می باشد.) ($Na=23 , C=12 , H=1 , O=16 \\frac{g}{mol}$) (موازنه شود)\n\n$NaHCO_3(s) \\rightarrow Na_2CO_3(s) + CO_2(g) + H_2O(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:25', 4, 'done'),
(5245, ' ۵۰۰ گرم $Fe_2O_3$ و کربن خالص به نسبت های استوکیومتری، در ظرفی وارد واکنش می شوند، اگر جرم مخلوط جامد واکنش به ۴۱۲g برسد، درصد خلوص آهن آزاد در مخلوط جامد واکنش در این لحظه چند است؟ ($C=12 , O=16 , Fe=56 : g.mol^{-1}$)\n\n$2Fe_2O_3(s) + 3C(s) \\rightarrow 4Fe(s) + 3CO_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:31', 4, 'done'),
(5246, ' کدام موارد درست است؟\n\nآ) یکی از فراورده های پتروشیمی با خاصیت اسیدی، به عنوان کاتالیزگر در واکنش تولید اتانول از اتن نقش دارد.\n\nب) واکنش با برم مایع، یکی از روش های شناسایی اتیلن از استیلن است.\n\nپ) نخستین عضو خانواده سیکلوآلکان ها و دومین عضو خانواده آلکن ها، هم پار یکدیگر می باشند.\n\nت) شمار پیوندهای دوگانه کربن - کربن نفتالن، دو برابر بنزن است.', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:38', 4, 'done'),
(5247, ' با توجه به شکل های مقابل، چند مورد از عبارت های بیان شده صحیح اند؟\n\n- نقطه جوش آلکان B بیشتر از آلکان A است. \n\n- شمار پیوندهای C-H در آلکان A کمتر از آلکان B است.\n\n- اگر آلکان B دارای ۱۱ اتم کربن باشد، آلکان A حداقل دارای ۱۲ اتم کربن است.\n\n- نیروی بین مولکولی و گران روی آلکان B بیشتر از آلکان A است.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:39:26', 4, 'done'),
(5248, ' نام کدام آلکان زیر براساس قواعد آیوپاک درست نوشته شده است و در ساختار این ترکیب چند جفت الکترون پیوندی وجود دارد؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:45', 4, 'done'),
(5249, ' چند مورد از مطالب زیر، نادرست است؟\n\nآ) در ساختار ماده ای که به عنوان ضد بید برای نگهداری فرش و لباس کاربرد دارد، شمار پیوندهای C-C، ۰/۷۵ برابر شمار پیوندهای C-H است.\n\nب) نسبت شمار اتم های هیدروژن به شمار اتم های کربن در سیکلوهگزان و گاز عمل آورنده در کشاورزی یکسان است.\n\nپ) سیکلوآلکان ها ترکیباتی سیرشده بوده و در هیچ واکنش شیمیایی شرکت نمی کنند.\n\nت) بنزن یک هیدروکربن سیرنشده است و در اثر واکنش کامل یک مول از آن با ۳ مول گاز هیدروژن به سیکلوهگزان تبدیل می شود.\n\nث) سرگروه ترکیب های آروماتیک و چهارمین عضو خانواده سیکلوآلکان ها از جمله هیدروکربن های سازنده نفت خام می باشند.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:51', 4, 'done'),
(5250, 'آلکین A را در مقدار کافی اکسیژن سوزانده ایم. اگر نسبت جرم کربن دی اکسید تولید شده به جرم آلکین اولیه، برابر ۳/۳ باشد، به ترتیب از راست به چپ در ساختار این آلکین چند پیوند اشتراکی وجود دارد و در فرایند سیر شدن کامل این آلکین، چند درصد به جرم مولی آن افزوده می شود؟ (گزینه ها را از راست به چپ بخوانید.) ($C=12 , H=1 , O=16 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:14:36', 1, '2026-09-29 15:02:59', 4, 'done'),
(5251, ' از واکنش موازنه‌نشده $LiOH(s) + CO_2(g) \\rightarrow Li_2CO_3(s) + H_2O(g)$ برای جذب گاز $CO_2$ تولید شده در فضاپیماها استفاده می‌شود. اگر درصد خلوص لیتیم هیدروکسید مصرف شده ۶۰٪ باشد، برای جذب ۲۰۱/۶ لیتر گاز $CO_2$ به چند گرم از این ماده نیاز است و طی این فرایند، چند گرم بخار آب تولید می‌شود؟ ($H=1$ و $Li=7$ و $O=16 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:08', 4, 'done'),
(5252, ' چند مورد از موارد زیر، درباره عناصر جدول تناوبی، به یقین درست است؟\n\nآ: عدد اتمی شبه‌فلز هر گروه نسبت به همه عناصر فلزی موجود در آن گروه، کمتر است.\n\nب: اگر $Z$ شبه‌فلز باشد، عنصر هم‌گروه آن در دوره بعد، در واکنش‌های شیمیایی الکترون از دست می‌دهد.\n\nپ: اگر نافلز $Y$ در لایه ظرفیت خود دو الکترون داشته باشد، سایر عناصر هم‌گروه آن تمایل به انجام واکنش شیمیایی ندارند.\n\nت: اگر یون $X^-$ به آرایش هشت تایی رسیده باشد، همه عناصر هم‌گروه آن، در دوره خود بیشترین خاصیت نافلزی را دارند.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:15', 4, 'done'),
(5253, ' جرم اتم‌های کربن موجود در یک نمونه از $MgCO_3$، با جرم اتم‌های کربن موجود در ۹۲ گرم اتانول با خلوص ۸۰٪ برابر است. بر اثر تجزیه‌ی این نمونه از منیزیم کربنات طی واکنش $MgCO_3(s) \\rightarrow MgO(s) + CO_2(g)$، چند گرم منیزیم اکسید تولید می‌شود؟ ($H=1$ و $C=12$ و $O=16$ و $Mg=24 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:22', 4, 'done'),
(5254, ' چند مورد از مطالب زیر در مورد اولین فلز دسته $p$ نادرست است؟\n\nالف: شمار آنیون و شمار کاتیون در نمونه فسفات آن، برابر است.\n\nب: شعاع اتمی آن از سایر فلزهای هم‌دوره خود کوچک‌تر است.\n\nپ: کمترین واکنش‌پذیری را میان فلزهای هم‌گروهی خود دارد.\n\nت: یونی پایدار با آرایش گاز نجیب قبل از خود در جدول تناوبی دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:27', 4, 'done'),
(5255, ' اگر یک فلز قلیایی به هنگام تشکیل یون پایدار، به تقریب ۹ درصد از الکترون‌های خود را از دست بدهد، این فلز در واکنش با کلر چه نوری ساطع می‌کند؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:32', 4, 'done'),
(5256, 'چند مورد از مطالب زیر در مورد فلزهای قلیایی درست است؟\n\nالف: واکنش‌پذیری هر فلز قلیایی از فلز قلیایی خاکی هم‌دوره خود بیشتر است.\n\nب: شعاع اتمی هر یک از آن‌ها از شعاع اتمی فلز قلیایی خاکی هم‌دوره خود بزرگ‌تر است.\n\nپ: فلزهای قلیایی برخلاف فلزهای قلیایی خاکی در هر دوره جدول تناوبی، یک عضو دارد.\n\nت: یون پایدار همه فلزهای قلیایی همانند همه فلزهای قلیایی خاکی، آرایش هشت‌تایی دارند.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:39', 4, 'done'),
(5257, 'براساس شکل زیر که بخشی از جدول تناوبی را نشان می‌دهد، کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:45', 4, 'done'),
(5258, 'با توجه به جدول زیر کدام‌یک از مطالب زیر درست هستند؟\n\n\n\n\n\nالف: در آرایش الکترونی عنصر $A$، ۶۷ درصد الکترون‌ها $n+l=3$ دارند.\n\nب: اختلاف شعاع اتمی دو عنصر $D$ و $A$، از اختلاف شعاع اتمی دو عنصر $X$ و $Z$ بیشتر است.\n\nپ: عنصر $Z$ را که در بیرونی‌ترین زیرلایه خود، ۵ الکترون دارد، در آزمایشگاه زیر آب نگه می‌دارند.\n\nت: عنصر $M$ نسبت به عنصر $B$ واکنش‌پذیری کمتر و نسبت به عنصر $G$ خصلت نافلزی کمتر دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:03:54', 4, 'done'),
(5259, ' کدام‌یک از مطالب زیر با توجه به جدول تناوبی زیر نادرست است؟\n\n\n\n\n\n\n\nالف: عنصر $M$ همانند عنصر $Z$ در واکنش با نافلزها الکترون به اشتراک می‌گذارد.\n\nب: عنصر $Y$ شعاع اتمی کوچک‌تری از گالیم و واکنش‌پذیری بیشتری از گوگرد دارد.\n\nپ: عنصر $X$ اولین فلز واسطه است و در ساخت تلویزیون رنگی از آن استفاده می‌شود.\n\nت: تفاوت شمار الکترون‌های عنصر $E$ با $n+l=4$، با شمار الکترون‌های عنصر $J$ با $l=1$ برابر ۲ است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:00', 4, 'done'),
(5260, 'کدام مورد در مورد اولین عنصری که دو زیرلایه با تعداد الکترون فرد دارد، نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:06', 4, 'done'),
(5261, ' اگر ۸۰ گرم از یک فلز قلیایی خاکی در واکنش با تیتانیم(III) کلرید، به‌تقریب ۲۹ گرم فلز تولید کند، جرم مولی این فلز قلیایی خاکی چقدر است؟\n\n($Ti=48 g.mol^{-1}$)', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:12', 4, 'done'),
(5262, ' از تخمیر محلول ۴۵ درصد جرمی گلوکز برای تولید اتانول استفاده می‌شود. اگر درصد جرمی الکل در محلول نهایی به ۱۰ برسد، بازده واکنش انجام‌شده به‌تقریب چند درصد است؟ ($H=1, C=12, O=16 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:17', 4, 'done'),
(5263, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:23', 4, 'done'),
(5264, ' اگر جرم‌هایی برابر از آهن (II) اکسید و آهن (III) اکسید در واکنش با کربن مطابق واکنش‌های موازنه‌نشده زیر، مقدار برابری گاز تولید کنند، درصد خلوص نمونه آهن (II) اکسید چند برابر نمونه آهن (III) اکسید است؟\n\n($O=16, Fe=56 : g.mol^{-1}$)\n\n$I) FeO(s) + C(s) \\rightarrow CO_2(g) + Fe(s)$\n\n$II) Fe_2O_3(s) + C(s) \\rightarrow CO_2(g) + Fe(s)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:28', 4, 'done'),
(5265, ' اگر درصد جرمی نیتروژن در نمونه‌ای کود ناخالص آمونیوم سولفات برابر ۴/۲ درصد باشد، درصد خلوص این آمونیوم سولفات در این نمونه چند درصد است؟ ($H=1, N=14, O=16, S=32 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:34', 4, 'done'),
(5266, 'اگر ۶۰ درصد از حجم مخلوط گازی از متان و اتان را گاز اتان تشکیل دهد، درصد جرمی کربن در این مخلوط گازی به‌تقریب چقدر است؟\n\n($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:43', 4, 'done'),
(5267, ' تولید گاز $SO_3$ از عناصر سازنده طی دو واکنش متوالی زیر صورت می‌گیرد. اگر بازده واکنش اول و دوم به‌ترتیب برابر ۴۰ و ۵۰ درصد باشد، برای تولید ۴۰۰ گرم گاز گوگرد تری‌اکسید از مقدار کافی گوگرد به چند گرم گاز اکسیژن نیاز است؟ ($O=16, S=32 : g.mol^{-1}$)\n\n$I) S(s) + O_2(g) \\rightarrow SO_2(g)$\n\n$II) 2SO_2(g) + O_2(g) \\rightarrow 2SO_3(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:48', 4, 'done'),
(5268, 'در واکنش ۸۰ گرم از یک نمونه ناخالص مس با مقدار کافی نیتریک اسید مطابق واکنش زیر، مجموع تعداد اتم‌های اکسیژن موجود در کل فراورده‌ها برابر $3/612 \\times 10^{24}$ است. درصد خلوص این نمونه مس چقدر بوده است؟\n\n($Cu=64 g.mol^{-1}$)\n\n$Cu(s) + 4HNO_3(aq) \\rightarrow Cu(NO_3)_2(aq) + 2NO_2(g) + 2H_2O(l)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:04:56', 4, 'done'),
(5269, ' اگر در نمونه‌ای ناخالص از آمونیوم نیترات به جرم ۳۲۰ گرم، درصد جرمی اتم اکسیژن برابر با ۴۵ باشد. درصد خلوص این نمونه چقدر است و چند مول یون در آن وجود دارد؟ (ناخالصی این نمونه آمونیوم نیترات، ترکیب یونی نیست.\n\n($H=1, N=14, O=16 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:05:07', 4, 'done'),
(5270, 'اگر پتاسیم نیترات تولیدشده از واکنش ۲۷۶ گرم پتاسیم کربنات با محلول $HNO_3$ مطابق معادله زیر با بازده ۶۰ درصد، در واکنش موازنه‌نشده $KNO_3(s) \\rightarrow K_2O(s) + N_2(g) + O_2(g)$ با بازده ۵۰ درصد، مصرف شود، چند مول گاز اکسیژن تولید می‌کند؟ ($C=12, O=16, K=39 : g.mol^{-1}$)\n\n$K_2CO_3(s) + 2HNO_3(aq) \\rightarrow 2KNO_3(s) + CO_2(g) + H_2O(l)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:05:12', 4, 'done'),
(5271, ' کدام‌یک از مطالب زیر در مورد واکنش تخمیر گلوکز با بازده ۷۰ درصد نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:05:18', 4, 'done'),
(5272, ' در اثر سوختن ۱/۵ مول از یک هیدروکربن، ۳۳۶ لیتر گاز کربن دی‌اکسید در شرایط $STP$ و ۲۱۶ گرم آب تولید شده است. مجموع تعداد اتم‌ها در هر مولکول این هیدروکربن چقدر است؟ ($H=1, C=12, O=16 : g.mol^{-1}$)', 2, 3, 68, 282, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:05:23', 4, 'done'),
(5273, ' در واکنش موازنه‌نشده $C(s) + H_2O(l) \\rightarrow CH_4(g) + CO(g)$ با بازده ۶۰ درصد، برای تولید یک گرم گاز متان به چند گرم کربن نیاز بوده و درصد جرمی متان در مخلوط گازی فراورده‌ها به تقریب چند درصد است؟\n\n($H=1, C=12, O=16 : g.mol^{-1}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:05:28', 4, 'done'),
(5274, ' اگر درصد جرمی کربن در هیدروکربنی ۶ برابر هیدروژن باشد، حجم کربن دی‌اکسید حاصل از سوختن هر گرم از این هیدروکربن در شرایط استاندارد چند لیتر است؟ ($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:05:34', 4, 'done'),
(5275, ' یک نمونه کلسیم کربنات ناخالص در اثر گرما مطابق واکنش (موازنه‌نشده) $CaCO_3(s) \\rightarrow CaO(s) + CO_2(g)$ به‌طور کامل تجزیه می‌شود. اگر درصد جرمی کلسیم اکسید در جامد باقی‌مانده برابر ۷۰ باشد، درصد خلوص نمونه کلسیم کربنات به تقریب چند درصد بوده است؟\n\n($C=12, O=16, Ca=40 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:16:54', 4, 'done'),
(5276, ' کدام‌یک از مطالب زیر در مورد ترکیب مقابل درست است؟ ($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:17:18', 4, 'done'),
(5277, ' واکنش ناخواسته به هنگام سوختن کامل متان، سوختن ناقص آن و تولید کربن مونواکسید است. اگر در سوختن یک نمونه متان، ۲۱۶ گرم آب تولید و ۱۱/۴ مول گاز اکسیژن مصرف شود، بازده واکنش سوختن کامل متان چند درصد است؟ ($H=1, O=16 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:17:35', 4, 'done'),
(5278, ' درصد جرمی هیدروژن در ساده‌ترین آلکان شاخه‌دار به تقریب چند درصد است؟ ($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:17:47', 4, 'done'),
(5279, ' نام ترکیب مقابل بر اساس قواعد آیوپاک کدام است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:20:26', 4, 'done'),
(5280, ' کدام یک از مطالب زیر در مورد واکنش فلز آلومینیم با محلول مس(II) نیترات درست هستند؟\n\nالف: مجموع غلظت کاتیون‌ها در محلول واکنش در طول انجام فرایند افزایش می‌یابد.\n\nب: اگر به جای فلز آلومینیم از فلز آهن استفاده شود، شدت انجام واکنش کمتر می‌شود.\n\nپ: در یون تولیدشده، نسبت شمار الکترون‌ها با $l=1$ به شمار الکترون‌ها با $l=0$ برابر ۱/۵ است.\n\nت: اگر این واکنش به‌طور طبیعی انجام نشود، می‌توان گفت واکنش‌پذیری فلز آلومینیم بیشتر از فلز مس است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 15:06:09', 4, 'done'),
(5281, ' اگر جرم ۴۲ گرم از یک نمونه آلکنی، پس از انجام واکنش با مقدار کافی گاز هیدروژن، به ۴۲/۷۵ گرم برسد، در ساختار این آلکن چند اتم هیدروژن وجود دارد؟ ($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:20:46', 4, 'done'),
(5282, ' اگر در واکنش سوختن یک مول از آلکنی، ۷/۵ مول گاز اکسیژن مصرف و ۴/۵ مول آب تولید شود، بازده این واکنش چند درصد بوده و برای جذب $CO_2$ تولیدشده در این واکنش، به چند گرم کلسیم اکسید نیاز است؟ ($O=16, Ca=40 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:21:35', 4, 'done'),
(5283, ' اگر درصد جرمی هیدروژن در مخلوطی از اتان و پروپین برابر ۱۶ درصد باشد، برای سوختن ۱۰۰ گرم از این مخلوط، به چند مول گاز اکسیژن نیاز است؟ ($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:22:00', 4, 'done'),
(5284, ' کدام‌یک از مطالب زیر در مورد ترکیب مقابل درست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:23:00', 4, 'done'),
(5285, 'کدام‌یک از مطالب زیر نادرست است؟\n\nالف: فراورده واکنش گاز اتن با برم مایع قرمز رنگ، ۱،۲-دی برمو اتان است.\n\nب: کاتالیزگر واکنش گاز هیدروژن با ۱-هگزن، فلزی از گروه ۱۰ جدول تناوبی است.\n\nپ: تعداد پیوندهای $H-C$ موجود در اتانول یک واحد کمتر از این تعداد در ۲-بوتین است.\n\nت: گاز اتن به‌عنوان عمل‌آورنده در کشاورزی کاربرد دارد و در ساختار آن هر اتم کربن ۳ پیوند کووالانسی دارد.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:23:22', 4, 'done'),
(5286, ' چند مورد از مطالب زیر در مورد ترکیب مقابل درست است؟ ($H=1, C=12 : g.mol^{-1}$)\n\nالف: هر مولکول این ماده، ۱۴ اتم هیدروژن در ساختار خود دارد. \n\nب: در ساختار آن سه اتم کربن به هیچ هیدروژنی متصل نیستند.\n\nپ: هر گرم از این ماده به تقریب با ۶۰ میلی‌گرم هیدروژن واکنش می‌دهد.\n\nت: فراورده حاصل از واکنش آن با هیدروژن، ۳،۳،۵-تری‌متیل هپتان نام دارد.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:23:46', 4, 'done'),
(5287, ' در ظرفی مخلوطی به حجم ۳۳۶ لیتر از دو گاز اتن و اتین در شرایط $STP$ در اختیار داریم. اگر این مخلوط گاز با ۲۴ مول گاز هیدروژن به‌طور کامل واکنش دهد، چند درصد از حجم مخلوط گازی اولیه را اتن تشکیل می‌دهد؟', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:24:20', 4, 'done'),
(5288, ' کدام‌یک از مطالب زیر در مورد سیکلوهگزان نادرست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:24:35', 4, 'done'),
(5289, ' اگر درصد جرمی گوگرد در نمونه‌ای ناخالص از مس(II) سولفات برابر ۸ درصد باشد، درصد خلوص مس(II) سولفات در این نمونه چند درصد است و محلولی که از انحلال ۳۰۰ گرم از این ماده ایجاد می‌شود، با چند گرم آهن واکنش می‌دهد؟ ($O=16, S=32, Fe=56, Cu=64 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:24:53', 4, 'done'),
(5290, '40- کدام‌یک از مطالب زیر در مورد کاربردی‌ترین فلز نادرست هستند؟\r\n\r\nالف: اکسیدی از این فلز که در فرایند ترمیت به کار می‌رود، به‌عنوان رنگ قرمز نقاشی کاربرد دارد.\r\n\r\nب: در واکنش تولید هر مول از این فلز از سنگ معدن آن، ۰/۷۵ مول گاز گلخانه‌ای تولید می‌شود.\r\n\r\nپ: در هیدروکسیدی از این فلز که به رنگ سبز است، نسبت شمار کاتیون به آنیون برابر ۲ است.\r\n\r\nت: در واکنش با محلول هیدروکلریک اسید، کاتیونی با ۵ الکترون با $n+l=5$ تولید می‌کند.', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:26:06', 4, 'done'),
(5291, ' نمونه‌ای ۴۰۰ گرمی از پتاسیم کلرات ناخالص بر اساس معادله موازنه نشده $KClO_3(s) \\rightarrow KCl(s) + O_2(g)$ در اثر گرما تجزیه می‌شود. اگر طی این فرایند، جرم توده جامد موجود در ظرف به اندازه ۲۸/۸ درصد کاهش یابد، درصد خلوص پتاسیم کلرات چقدر است؟ ($O=16, Cl=35/5, K=39 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:26:37', 4, 'done'),
(5292, ' با توجه به جدول مقابل چند مورد از مطالب زیر درست است؟\n\nالف: در واکنش عنصر $A$ با گاز کلر، نوری به رنگ زمرد تولید می‌شود. \n\nب: در میان عناصر مشخص‌شده بیشترین شعاع اتمی متعلق به عنصر $B$ است.\n\nپ: واکنش عنصر $Y$ با گاز هیدروژن در دمای $-200^\\circ C$ به سرعت انجام می‌شود.\n\nت: عنصر $M$ نسبت به عنصر $D$ واکنش‌پذیری کمتر دارد و بار یون پایدار آن بیشتر است.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:27:12', 4, 'done'),
(5293, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-03-22 12:31:11', 5, 'done'),
(5294, ' یک نمونه آلکین در واکنش با بخار برم، ترکیبی آلی تولید می‌کند که درصد جرمی عنصر برم در آن به تقریب برابر ۸۰ درصد است. در ساختار آلکین اولیه چند اتم هیدروژن وجود دارد؟ ($H=1, C=12, Br=80 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:27:27', 4, 'done'),
(5295, ' کدام‌یک از مطالب زیر در مورد ترکیب آلی مقابل نادرست است؟ ($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:27:55', 4, 'done'),
(5296, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:30:57', 4, 'done'),
(5297, ' یک نمونه ۲۵۰ گرمی از آلومینیم سولفات با خلوص ۸۵/۵ درصد را وارد یک ظرف سر باز کرده و آن را بر اساس معادله موازنه نشده زیر تجزیه می‌کنیم. پس از پایان واکنش، درصد جرمی اتم‌های آلومینیم در مخلوط جامد باقیمانده در ظرف واکنش چقدر می‌شود؟ ($O=16$ و $Al=27$ و $S=32 : g.mol^{-1}$)\n\n$Al_2(SO_4)_3(s) \\rightarrow Al_2O_3(s) + SO_3(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:31:14', 4, 'done'),
(5298, ' نمونه ناخالصی از کلسیم کربنات را بر اساس معادله زیر تجزیه می‌کنیم. اگر طی این فرایند ۵۰۰g کلسیم اکسید با خلوص ۵۶٪ به‌دست آمده باشد، درصد خلوص نمونه اولیه کلسیم کربنات به تقریب چقدر بوده و حجم گاز کربن دی‌اکسید تولید شده در این فرایند در شرایط استاندارد برابر با چند لیتر می‌شود؟\n\n($C=12$ و $O=16$ و $Ca=40 : g.mol^{-1}$)\n\n$CaCO_3(s) \\rightarrow CaO(s) + CO_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:31:28', 4, 'done'),
(5299, ' کدام موارد از عبارت‌های زیر درست است؟\n\nالف: در تناوب سوم جدول دوره‌ای، بیشترین تفاوت شعاع اتمی دو عنصر متوالی مربوط به عناصر فسفر و سیلیسیم است.\n\nب: در یکی از گروه‌های جدول دوره‌ای که شامل ۶ عنصر می‌شود، عناصری با هر سه حالت فیزیکی وجود دارد.\n\nپ: اغلب فلزهای اصلی با از دست دادن الکترون، به آرایش الکترونی گاز نجیب قبل از خود می‌رسند.\n\nت: آرایش الکترونی یون روی، مشابه به آرایش الکترونی کاتیون موجود در ترکیب $CuS$ است.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:31:46', 4, 'done'),
(5300, ' مقدار ۲۴۰ گرم متانول با خلوص ۵۰٪ را طبق معادله (موازنه نشده) $CH_3OH(g) \\rightarrow 2H_2(g) + CO(g)$ تجزیه کرده و گاز $CO$ حاصل از آن را بر اساس معادله موازنه نشده $Fe_2O_3(s) + CO(g) \\rightarrow Fe(s) + CO_2(g)$، با آهن(III) اکسید وارد واکنش می‌کنیم. طی این فرایند، چند گرم فلز آهن تولید می‌شود؟\n\n($H=1$ و $C=12$ و $O=16$ و $Fe=56 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:32:05', 4, 'done'),
(5301, ' اگر مخلوطی به جرم ۲۵ گرم از $Fe_2O_3$ و $Na_2O$ با مقدار کافی کربن گرما داده شود، ۱۳۴۴ میلی‌لیتر گاز کربن دی‌اکسید در شرایط $STP$ تولید می‌شود. درصد جرمی سدیم اکسید در مخلوط اولیه چقدر بوده و درصد جرمی تقریبی فلز آهن در مخلوط نهایی به ترتیب از راست به چپ کدام است؟\n\n($H=1$ و $O=16$ و $Na=23$ و $Fe=56 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:32:21', 4, 'done'),
(5302, ' اگر آرایش الکترونی یون‌های $A^-$، $B^{2+}$، $C^+$ و $D^{2-}$ به زیرلایه الکترونی $4p^6$ ختم شود، چند مورد از مطالب زیر درباره این چهار عنصر درست است؟\n\nالف: عنصر $A$ نسبت به عنصر گالیم شعاع اتمی کوچک‌تری داشته و واکنش‌پذیری این عنصر از عنصر $D$ بیشتر است.\n\nب: از بین عناصر هم‌دوره با اسکاندیم، شعاع اتمی عنصری که یون آن قدر مطلق بار بزرگ‌تری دارد، بیشتر است.\n\nپ: عنصر $A$ در دمای اتاق به آرامی با گاز هیدروژن واکنش می‌دهد.\n\nت: خصلت فلزی عنصر $B$ از عنصر $C$ بیشتر است.', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:32:44', 4, 'done'),
(5303, 'از واکنش آمونیاک با اوزون، سه ترکیب آمونیوم نیترات، گاز اکسیژن و آب تولید می‌شود. اگر بازده واکنش برابر $\\%80$ باشد، برای تهیه نمک موجود در $250$ گرم محلول $\\%24$ جرمی آمونیوم نیترات، به چند لیتر اوزون در شرایط $STP$ نیاز است؟\n\n$aNH_3(g) + 4O_3(g) \\rightarrow bNH_4NO_3(s) + 4O_2(g) + cH_2O(g)$\n\n($O = 16$ و $N = 14$ و $H = 1 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:33:02', 4, 'done'),
(5304, ' در واکنش $4NH_3(g) + 5O_2(g) \\rightarrow 4NO(g) + 6H_2O(l)$، به ازای مصرف شدن $85$ گرم گاز آمونیاک با خلوص $\\%40$، چند لیتر گاز اکسیژن در شرایط استاندارد مصرف شده و چند گرم فراورده مایع تولید می‌شود؟\n\n(بازده درصدی واکنش انجام شده را برابر با $\\%50$ در نظر بگیرید. $O = 16$ و $N = 14$ و $H = 1 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:33:17', 4, 'done'),
(5305, ' کدام مورد از عبارت‌های داده شده نادرست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:33:34', 4, 'done'),
(5306, '56- جرم مولی یک آلکن، ۳۳/۳ درصد از جرم مولی سیکلوهگزان بیشتر است. از واکنش فراورده گازی حاصل از سوختن کامل ۴۴/۸ گرم از این آلکن در شرایط استاندارد با مقدار کافی کلسیم اکسید، چند گرم کلسیم کربنات به‌دست می‌آید؟\r\n\r\n(بازده واکنش دوم را برابر با ۸۰ درصد در نظر بگیرید. $Ca = 40$ و $O = 16$ و $C = 12$ و $H = 1 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:34:00', 4, 'done'),
(5307, ' کدام عبارت زیر نادرست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-17 20:15:12', 1, '2026-09-29 16:34:24', 4, 'done'),
(5308, ' اتیلن‌گلیکول و اوره در چه تعداد از موارد زیر، مشابه یکدیگرند؟\n\n- شمار عنصرهای سازنده مولکول\n\n- نوع نیروی جاذبه بین مولکولی غالب\n\n- نسبت شمار اتم‌های کربن به اکسیژن\n\n- شمار جفت‌الکترون‌های ناپیوندی در ساختار لوویس\n\n- انحلال‌پذیری در آب', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:40:41', 4, 'done'),
(5309, ' چند مورد از مطالب زیر، در مورد نمک سدیم اسید چرب، نادرست است؟\n\n- ساختار آن را می‌توان به صورت الگوی \n\n\n\nنشان داد.\n\n- مخلوط آن با آب، مخلوطی ناهمگن ولی پایدار است.\n\n- مخلوط آن با آب، رنگ کاغذ pH را آبی می‌کند.\n\n- دارای دو بخش کاتیونی و آنیونی است که بخش آنیونی آن، کاملاً ناقطبی می‌باشد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:40:33', 4, 'done'),
(5310, '3- مخلوط A پایدار است و مخلوط B، نور را پخش می‌کند. کدام مطلب در مورد این مخلوط‌ها، به یقین درست است؟', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:14:10', 4, 'done'),
(5311, 'با توجه به ساختار پاک‌کننده داده‌شده، چند مورد از مطالب زیر، درست است؟\n\n\n\n$(S = 32, Na = 23, O = 16, C = 12, H = 1: g.mol^{-1})$\n\n- این ترکیب، از مواد پتروشیمیایی مانند بنزن، طی واکنش‌های پیچیده در صنعت تولید می‌شود.\n\n- بر اثر واکنش با آلاینده‌های نامحلول در آب مانند چربی‌ها، باعث پخش‌شدن آن‌ها در آب و زدودن آلودگی‌ها می‌شود.\n\n- تفاوت جرم مولی آن با جرم مولی صابون جامد هم‌کربن آن با زنجیر هیدروکربنی سیرشده، برابر ۴۲ گرم است.\n\n- در بخش قطبی آن، ۹ جفت‌الکترون ناپیوندی وجود دارد و بخش ناقطبی آن، سبب پخش چربی‌ها در آب می‌شود.\n\n- با یون‌های $Ca^{2+}$ و $Mg^{2+}$ موجود در آب سخت واکنش داده اما رسوبی ایجاد نمی‌کند.', 3, 3, 71, 268, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:26', 4, 'done'),
(5312, ' چند مورد از مطالب زیر، درست است؟\n\n- در گذشته برای شست‌وشوی آسان‌تر ظرف‌های چرب، از خاکستر و آب گرم استفاده می‌کردند.\n\n- شوینده‌ها براساس خواص اسیدی و بازی عمل می‌کنند.\n\n- اسیدها با همه فلزها واکنش می‌دهند و در تماس با پوست، سوزش ایجاد می‌کنند.\n\n- محلول اغلب اسیدها و بازها، رسانای جریان برق هستند و میزان رسانایی آن‌ها با یکدیگر متفاوت است.\n\n- بازها در سطح پوست همانند صابون، احساس لیزی ایجاد می‌کنند اما به آن آسیب نمی‌رسانند.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:31', 4, 'done'),
(5313, ' کدام موارد از مطالب زیر، درست‌اند؟\n\nالف) شیمی‌دان‌ها پیش از شناخته‌شدن اسیدها و بازها، با برخی از واکنش‌های آن‌ها آشنا بودند.\n\nب) تعریف آرنیوس برای اسیدها یا بازها، به محلول‌های آبی محدود می‌شود.\n\nپ) چنان‌چه در یک سامانه غلظت مولی یون‌های هیدرونیوم و هیدروکسید با هم برابر باشد، آن سامانه حالت خنثی دارد.\n\nت) از دید آرنیوس، جامدهای یونی اکسیژن‌دار، اسید به شمار می‌آیند.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:38', 4, 'done'),
(5314, ' با توجه به شکل‌های زیر که مربوط به چند محلول اسیدی یا بازی است، کدام عبارت درست است؟ (هر ذره نشان داده شده در شکل‌ها را معادل $0.02$ مول در نظر بگیرید.)', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:43', 4, 'done'),
(5315, ' چند مورد از مطالب زیر، درست است؟\n\n- سطح بیرونی یک قطره چربی که به وسیله پاک‌کننده‌های صابونی یا غیرصابونی در آب پخش شده است، دارای بار مثبت است.\n\n- در صورت اضافه‌کردن مقداری منیزیم کلرید به مخلوطی از آب و صابون و روغن، اجزای سازنده مخلوط از هم جدا می‌شوند.\n\n- در پاک‌کننده‌های صابونی، بین سر آب‌دوست و آب‌گریز، پیوند یونی وجود دارد.\n\n- نسبت استوکیومتری کاتیون به آنیون در صابون جامد و پاک‌کننده‌های غیرصابونی سدیم‌دار، یکسان است.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:48', 4, 'done'),
(5316, ' چند مورد از مطالب زیر درباره مخلوط سدیم هیدروکسید و پودر آلومینیم، نادرست است؟\n\n• از این مخلوط به منظور باز کردن لوله‌ها یا مسیرهایی که بر اثر ایجاد رسوب و تجمع چربی‌ها بسته شده‌اند، استفاده می‌شود.\n\n• با افزودن این مخلوط به آب، دمای آب و مواد موجود در مخلوط افزایش می‌یابد.\n\n• این مخلوط برخلاف پاک‌کننده‌های غیرصابونی، خاصیت خورندگی دارد.\n\n• گاز اکسیژن حاصل از افزودن این مخلوط به آب، قدرت پاک‌کنندگی آن را افزایش می‌دهد.\n\n• برهم‌کنش میان ذره‌ها، تشابه عملکرد این مخلوط و صابون، در پاک‌کردن آلاینده‌هاست.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:52', 4, 'done'),
(5317, ' چند مورد از مطالب زیر، درست است؟\n\n• صابون مراغه افزودنی شیمیایی ندارد و به دلیل خاصیت اسیدی، برای موهای چرب استفاده می‌شود.\n\n• تشکیل کف کم، هنگام استفاده از پاک‌کننده‌های صابونی در آب اهواز، یک شاهد عینی برای سختی پایین آب آشامیدنی این شهر محسوب می‌شود.\n\n• همه اتم‌های اکسیژن در ساختار صابون‌ها و پاک‌کننده‌های غیرصابونی، دارای ۳ جفت الکترون ناپیوندی هستند.\n\n• برای جلوگیری از ایجاد لکه بر روی لباس‌ها در هنگام شست‌وشوی آن‌ها در آب سخت، می‌توان نمک‌های فسفات‌دار را به شوینده‌های صابونی اضافه کرد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:39', 4, 'done'),
(5318, ' با توجه به داده‌های جدول زیر که در دمای اتاق اندازه‌گیری شده‌اند، درستی یا نادرستی مطالب زیر، به ترتیب کدام است؟\n\n\n\n• در غلظت یکسان، مقایسه سرعت واکنش ۴ قطعه نوار منیزیم یکسان با محلول ۴ اسید به صورت $\\text{HD} < \\text{HC} < \\text{HB} < \\text{HA}$ است.\n\n• اگر HD فورمیک اسید باشد، HC را می‌توان استیک اسید در نظر گرفت.\n\n• در دمای اتاق، در محلول‌هایی با pH یکسان، غلظت مولکول‌های یونیده‌نشده HC، ۱۰ برابر غلظت مولکول‌های یونیده‌نشده HD است.\n\n• در حجم و غلظت یکسان محلول‌ها، در دمای اتاق، حجم گاز تولیدشده پس از پایان واکنش m گرم فلز منیزیم با محلول ۴ اسید، یکسان است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:44', 4, 'done'),
(5319, ' چند مورد از مطالب زیر، نادرست است؟\n\n• به موادی مانند اتانول و شکر که انحلال آن‌ها در آب به صورت مولکولی است، غیرالکترولیت و به محلول آن‌ها، محلول غیرالکترولیت گفته می‌شود.\n\n• معادله انحلال یونی آلومینیم نیترات در آب به صورت $\\text{Al(NO}_3\\text{)}_3\\text{(s)} \\rightarrow \\text{Al}^{3+}\\text{(l)} + 3\\text{NO}_3^-\\text{(l)}$ است.\n\n• فلزها و گرافیت، رسانای الکترونی هستند و رسانایی آن‌ها برخلاف محلول آبی سدیم کلرید، توسط الکترون‌ها انجام می‌شود.\n\n• اگر در دما و غلظت یکسان، رسانایی الکتریکی محلول A کم‌تر از محلول B باشد، به یقین شمار یون‌ها در محلول A کم‌تر از شمار یون‌ها در محلول B است.', 3, 3, 71, 270, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:49', 4, 'done'),
(5320, ' چند مورد از مطالب زیر، درست است؟\n\n• در واکنش‌های برگشت‌پذیر، همه واکنش‌دهنده(ها) به فراورده(ها) تبدیل نمی‌شود.\n\n• در محلول هیدروفلوئوریک اسید، در یک گستره زمانی معین، شمار مولکول‌های اسید یونیده‌شده با شمار مولکول‌های اسید تولیدشده از پیوستن یون‌های هیدرونیوم و فلوئورید به یکدیگر، برابر است.\n\n• در واکنش در حال تعادل $\\text{A(g)} \\rightleftharpoons \\text{2B(g)}$، سرعت مصرف واکنش‌دهنده با سرعت مصرف فراورده برابر است.\n\n• خواص و ویژگی‌های ظاهری یک سامانه تعادلی با گذشت زمان تغییر می‌کند.', 3, 3, 71, 271, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:54', 4, 'done'),
(5321, ' چه تعداد از مطالب داده‌شده، درباره مواد زیر درست است؟\n\n\n\n• نام ترکیب‌های (II) و (V) به ترتیب سود سوزآور و جوهرنمک است که از نظر شیمیایی فعال هستند و خاصیت خورندگی دارند.\n\n• از واکنش مواد (II) و (III) می‌توان ماده (IV) را تهیه کرد و فراورده دیگر این واکنش، مولکول متانول است.\n\n• (IV) و (I) به ترتیب پاک‌کننده‌های صابونی و غیرصابونی هستند که ردپای کربن دی‌اکسید در فرایند تولید (I) از (IV) بیشتر است.\n\n• مواد (I) و (IV) براساس برهم‌کنش میان ذره‌ها عمل می‌کنند، اما مواد (II) و (V) افزون بر این برهم‌کنش، با آلاینده‌ها واکنش نیز می‌دهند.\n\n• مخلوط آلومینیم و ترکیب (II) که به شکل محلول عرضه می‌شود، برای بازکردن مجاری مسدودشده در صنعت مورد استفاده قرار می‌گیرد.', 3, 3, 71, 268, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:59', 4, 'done'),
(5322, ' با توجه به شکل‌های مقابل که محلول‌های اسیدی با غلظت معین و حجم مشخص ($1$ دسی‌لیتر) را در دمای $25^\\circ C$ نشان می‌دهند، چند مورد از مطالب زیر درست است؟\n\n\n\n• اگر یک pHسنج دیجیتال را در محلول شماره ۱ قرار دهیم، عدد ۹ روی صفحه نمایشگر آن مشاهده می‌شود.\n\n• اگر با افزودن آب مقطر، حجم محلول‌های ۲ و ۳ به ۱۰۰۰ میلی‌لیتر برسد، pH هر دو محلول، یک واحد افزایش می‌یابد.\n\n• pH محلول و درجه یونش اسید در ظرف ۱ بیشتر از ظرف ۲ است.\n\n• رسانایی الکتریکی مخلوط ظرف ۱ و ۲ از ظرف ۳ بیشتر بوده و تعداد یون‌های چنداتمی در ظرف ۲ از بقیه بیشتر است.', 3, 3, 71, 272, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:04', 4, 'done'),
(5323, ' چند مورد از مطالب زیر، درست است؟\n\n• جیوه و گرافیت دو نمونه از رساناهای الکترونی هستند.\n\n• رسانایی الکتریکی محلول $0.05$ مولار سدیم کلرید در آب، کم‌تر از محلول $0.1$ مولار آن در آب است.\n\n• محلول آمونیاک در آب مانند محلول اتانول در آب، فاقد رسانایی الکتریکی است.\n\n• همه محلول‌های یونی مانند محلول سدیم هیدروکسید در آب، رسانایی الکتریکی بالایی دارند.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:13:09', 4, 'done'),
(5324, ' در کدام گزینه، مقایسه قدرت اسیدها درست است و نام اسید قوی‌تر به درستی آمده است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:13', 4, 'done'),
(5325, ' چند مورد از مطالب زیر، درست است؟\n\n• اسیدها و بازها با ثابت یونش کوچک، الکترولیت ضعیف به شمار می‌روند.\n\n• واکنش‌هایی که می‌توانند در هر دو جهت رفت و برگشت انجام شوند، به یقین تعادلی هستند.\n\n• در محلول $0.1$ مولار نیترواسید، غلظت یون هیدرونیوم برابر $0.1\\text{mol.L}^{-1}$ است.\n\n• بر اثر ورود منیزیم کافی به محلول‌های HF و HCl با pH و حجم یکسان، حجم گاز تولیدشده در محلول HCl بیشتر است.', 3, 3, 71, 271, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:17', 4, 'done'),
(5326, ' با توجه به شکل‌های زیر که مربوط به دو محلول الکترولیت ($\\text{HA}$ و $\\text{HX}$) است، کدام مطلب نادرست است؟\n\n(هر ذره را معادل $0.01$ مول و حجم هر دو محلول را $200\\text{mL}$ در نظر بگیرید.)', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:12:22', 4, 'done'),
(5327, ' کدام موارد از مطالب زیر درست است؟\n\nالف) یون‌های حاصل از یونش دو ماده مختلف، می‌توانند با یکدیگر واکنش داده و مولکول خنثی تولید کنند.\n\nب) لوله‌بازکن‌ها، محلول‌هایی غلیظ از بازهای قوی هستند که فراورده‌هایی محلول در آب یا گازی تولید می‌کنند.\n\nپ) فراورده محلول حاصل از واکنش پاک‌سازی اسیدهای چرب از لوله‌ها با یک محلول بازی قوی، خود نوعی پاک‌کننده است.\n\nت) همه داروهای ضداسید، به صورت سوسپانسیون مصرف می‌شوند.', 3, 3, 71, 274, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:43', 1, '2026-10-12 22:11:50', 4, 'done'),
(5328, '-کدام موارد از عبارت‌های زیر درست است؟ ($C=12, H=1, N=14, O=16 : g.mol^{-1}$)\n\nآ) اتیلن‌گلیکول همانند اتانول دارای مولکول‌های ناقطبی است و به هر نسبتی در آب حل می‌شود.\n\nب) صابون ماده‌ای است که هم در چربی و هم در آب حل می‌شود.\n\nپ) نسبت مجموع تعداد اتم‌های گلوکز به مجموع تعداد اتم‌های اوره در جرم‌های برابری از آن‌ها، برابر یک است.\n\nت) بنزین، روغن زیتون و وازلین در آب مخلوط ناهمگن به‌وجود می‌آورند.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:11:55', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5329, ' با توجه به شکل زیر، چند مورد از مطالب داده شده، جملۀ زیر را به درستی کامل می‌کند؟\n\n\n\n«(در) ظرف سمت .......................... ، ..........................»\n\n* چپ، ذره‌های سازنده شامل توده‌های مولکولی با اندازه‌های متفاوت است.\n\n* راست، یک مخلوط پایدار و به ظاهر همگن است.\n\n* چپ، همانند شکل سمت راست مخلوط پایدار است و ته‌نشین نمی‌شود.\n\n* راست، برخلاف رنگ‌های پوششی با گذشت زمان ته‌نشین نمی‌شود.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:06:54', 4, 'done'),
(5330, ' چند مورد از مطالب زیر دربارۀ ساختار داده شده درست است؟ ($C=12, H=1, O=16 : g.mol^{-1}$)\n\n\n\nآ) نیروی بین‌مولکولی غالب در آن از نوع واندروالسی است.\n\nب) زنجیر هیدروکربنی اسید چرب سازندۀ آن دارای $18$ اتم کربن است.\n\nپ) جرم مولی الکل سازندۀ آن $92$ گرم بر مول است.\n\nت) از واکنش آن با سه مول سدیم هیدروکسید، سه مول نمک سدیم اسید چرب یکسان به دست می‌آید.\n\nث) فرمول مولکولی هر سه اسید چرب سازندۀ آن به صورت $C_{18}H_{36}O_2$ است.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:00', 4, 'done'),
(5331, ' کدام گزینه نادرست است؟ ($K=39, S=32, N=14, Na=23, H=1, C=12, O=16 : g.mol^{-1}$)', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:08', 4, 'done'),
(5332, 'همۀ گزینه‌های زیر درست هستند، به‌جز:', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:12', 4, 'done'),
(5333, ' چند مورد از عبارت‌های زیر درست است؟\n\nآ) در بخش قطبی یک صابون جامد (پس از ورود به آب)، شش جفت الکترون ناپیوندی وجود دارد.\n\nب) در حالت خالص، قسمت کاتیونی صابون‌ها، تعیین‌کننده حالت فیزیکی صابون در دمای اتاق هستند.\n\nپ) میزان چسبندگی لکه‌های چربی به پارچه‌های نخی، بیشتر از پارچه‌های پلی‌استری است.\n\nت) روغن زیتون، هیدروکربنی سیرنشده است که سه گروه استری در ساختار خود دارد.\n\nث) رفتار سوسپانسیون‌ها و کلوئیدها در برابر نور، مشابه است.', 3, 3, 71, 268, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:17', 4, 'done'),
(5334, ' چند مورد از عبارت‌های زیر نادرست است؟\n\nآ) آرنیوس نخستین کسی بود که اسیدها و بازها را بر یک مبنای علمی توصیف کرد.\n\nب) شیمیدان‌ها پیش از آن‌که ویژگی‌های اسیدها و بازها شناخته شود، با ساختار آن‌ها آشنا بودند.\n\nپ) یافته‌های تجربی آرنیوس نشان داد که محلول اسیدها و بازها رسانای جریان برق هستند و میزان رسانایی آن‌ها با یکدیگر یکسان نیست.\n\nت) با حل شدن اسیدها یا بازها در آب، مقدار یون‌های موجود در آب افزایش می‌یابد.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:21', 4, 'done'),
(5335, ' چند مورد از اکسیدهای زیر، باز آرنیوس به شمار می‌روند و براساس نظریۀ آرنیوس .......................... دربارۀ میزان اسیدی یا بازی بودن محلول‌ها اظهار نظر کرد. (گزینه‌ها را از راست به چپ بخوانید.)\n\na) $BaO$    b) $CO_2$    c) $Li_2O$    d) $Na_2O$    e) $SO_2$', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:26', 4, 'done'),
(5336, ' کدام یک از گزینه‌های زیر نادرست است؟', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:29', 4, 'done'),
(5337, ' با توجه به ترکیب‌های (1) و (2) که در آن‌ها $R$ و $R\'$ یک زنجیر آلکیلی است، کدام موارد زیر درست می‌باشند؟\n\n$(C=12, H=1, O=16, S=32, Na=23 : g.mol^{-1})$\n\n$R\' - C_6H_4 - SO_3Na$ (2          $R - COONa$ (1\n\nآ) اگر $R$ در ترکیب (1) دارای 17 اتم کربن باشد، در آب دارای یون کلسیم، پاک‌کنندگی خوبی نخواهد داشت.\n\nب) اگر $R\'$ در ترکیب (2) دارای 2 اتم کربن باشد، در آب دارای یون منیزیم، پاک‌کنندگی خوبی خواهد داشت.\n\nپ) ترکیب (1) فرمول کلی پاک‌کننده صابونی و ترکیب (2) فرمول کلی پاک‌کننده غیرصابونی است.\n\nت) اگر $R$ در ترکیب (1) دارای 17 و $R\'$ در ترکیب (2) دارای 12 کربن باشد، اختلاف جرم مولی دو ترکیب برابر جرم مولی دومین آلکن خواهد شد.', 3, 3, 71, 268, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:33', 4, 'done'),
(5338, ' چند مورد از عبارات زیر، نادرست است؟\n\n* در واکنش مخلوط آلومینیم و سدیم هیدروکسید با آب، گرماگیر بودن واکنش، منجر به افزایش قدرت پاک‌کنندگی آن می‌شود.\n\n* پیش از شناسایی ساختار اسیدها و بازها، شیمیدان‌ها افزون بر ویژگی‌های اسیدها و بازها، با اغلب واکنش‌های آنها نیز آشنا بودند.\n\n* افزودن برخی اکسیدها مانند $SO_2$ و $N_2O_5$ به آب، علاوه بر تولید $H^+$، موجب افزایش غلظت یون‌های سولفات و نیترات می‌گردد.\n\n* به موادی مانند $NaCl(s)$ الکترولیت و به موادی مانند شکر که انحلال آن‌ها در آب به شکل مولکولی است، غیرالکترولیت می‌گویند.', 3, 3, 71, 270, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:37', 4, 'done'),
(5339, ' کدام گزینه همواره درست است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:41', 4, 'done'),
(5340, ' با توجه به محلول‌های هیدروکلریک‌اسید و هیدروفلوئوریک‌اسید با غلظت و دمای یکسان، کدام‌یک از عبارت‌های زیر درست است؟\n\n\n\n$pH$\n\n$[H_3O^+]$\n\nآ) شمار مولکول‌های $HCl$ از شمار مولکول‌های $HF$ بیش‌تر است زیرا اسید قوی‌تری است.\n\nب) در محلول هر ظرف، غلظت کاتیون و آنیون حاصل از یونش با هم برابر است.\n\nپ) نمودار $pH$ نسبت به غلظت یون هیدرونیوم در محلول هیدروکلریک‌اسید در دمای اتاق به صورت مقابل است.\n\nت) مقایسه غلظت گونه‌های موجود در محلول هیدروفلوئوریک‌اسید به صورت زیر است:\n\n$[HF]$ یونیده نشده $> [F^-] = [H^+] > [OH^-]$\n\nث) با حل شدن گاز هیدروژن کلرید در آب، هر مولکول آن یک یون هیدرونیوم در آب آزاد می‌کند.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:46', 4, 'done'),
(5341, ' با توجه به جدول داده شده، چه تعداد از نتیجه‌گیری(ها) در دمای اتاق نادرست است؟\n\n\n\nآ) در محلول $0/5$ مولار هیدروبرمیک‌اسید، غلظت یون هیدرونیوم $0/5$ مولار است.\n\nب) در محلول $0/3$ مولار هیدروسیانیک‌اسید، $[CN^-] = 0/3$ است.\n\nپ) در محلول $0/05$ مولار هیدرویدیک‌اسید، $[HI] = [H^+] = [I^-]$ است.\n\nت) در محلول $0/03$ مولار هیدروفلوئوریک‌اسید، $[HF] > [H^+] = [F^-]$ است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:51', 4, 'done'),
(5342, ' کدام مطلب درست است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:07:56', 4, 'done'),
(5343, ' چند مورد از عبارت‌های زیر دربارۀ واکنش‌های تعادلی درست است؟\n\nآ) در یک واکنش برگشت‌پذیر تعادلی، ابتدا واکنش‌دهنده‌ها تا حد امکان مصرف می‌شوند، سپس فرایند مصرف شدن فراورده‌ها در جهت عکس واکنش رخ می‌دهد.\n\nب) حضور هم‌زمان مواد واکنش‌دهنده و فراورده در مخلوط پایانی یک واکنش را می‌توان نشانه‌ای از برگشت‌پذیر بودن آن دانست.\n\nپ) در هنگام تعادل، سرعت واکنش رفت و سرعت واکنش برگشت یکسان نیست.\n\nت) در هنگام تعادل، غلظت واکنش‌دهنده‌ها و فراورده‌ها با هم برابر است.\n\nث) مقدار عددی ثابت تعادل در دمای ثابت به مقدار اولیه واکنش‌دهنده‌ها یا فراورده‌ها بستگی ندارد.', 3, 3, 71, 271, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:08:00', 4, 'done'),
(5344, ' شکل زیر تغییرات غلظت یون‌های هیدرونیوم و هیدروکسید را هنگام افزودن هریک از موارد 1 و 2 به آب خالص نشان می‌دهد، با توجه به آن کدام گزینه نادرست است؟ (دما را $25^{\\circ}C$ در نظر بگیرید.)', 3, 3, 71, 272, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:08:07', 4, 'done'),
(5345, ' چند مورد از مطالب زیر دربارۀ محلول‌های آبی داده شده با حجم، دما و $pH$ یکسان درست است؟\n\nمحلول (1): سدیم هیدروکسید           محلول (2): آمونیاک\n\n* ثابت تعادل محلول (1) بزرگ‌تر از ثابت تعادل محلول (2) بوده و باز محلول (1) جزو بازهای قوی به‌شمار می‌رود.\n\n* رسانایی الکتریکی محلول (1) در مقایسه با محلول (2) بیشتر است.\n\n* از محلول (1) می‌توان به عنوان لوله‌بازکن استفاده کرد.\n\n* غلظت یون هیدروکسید در محلول (1) بیشتر از محلول (2) است.', 3, 3, 71, 273, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:08:11', 4, 'done'),
(5346, ' در ارتباط با واکنش «خنثی‌سازی»، چند مورد از مطالب زیر، درست است؟\n\n* این واکنش مبنایی برای کاربرد شوینده‌ها و پاک‌کننده‌ها است.\n\n* یون‌های هیدرونیوم در واکنش با یون‌های هیدروکسید، به مولکول‌های آب تبدیل می‌شوند.\n\n* برخلاف یون‌های هیدرونیوم و هیدروکسید، سایر یون‌ها همواره به‌صورت دست‌نخورده در محلول باقی می‌مانند.\n\n* لوله‌بازکن در واکنش با رسوب‌های مسدودکننده صرفاً از طریق فراورده‌های محلول در آب، سبب جرم‌گیری می‌شود.', 3, 3, 71, 274, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:08:15', 4, 'done'),
(5347, ' کدام مورد، نادرست است؟', 3, 3, 71, 274, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 22:08:20', 4, 'done'),
(5348, ' کدام‌یک از عبارت‌های داده شده درست هستند؟\n\nالف) روغن زیتون همانند قندهای موجود در عسل، حاوی مولکول‌هایی است که تعداد زیادی گروه هیدروکسیل دارند و قطبی محسوب می‌شوند.\n\nب) انحلال‌پذیری وازلین در هگزان بیشتر از انحلال‌پذیری اتانول در هگزان است.\n\nج) وازلین و بنزین در هگزان به خوبی حل می‌شوند.\n\nد) اتیلن‌گلیکول، اوره و نمک خوراکی، در آب حل می‌شوند که عامل آن وجود گروه هیدروکسیل در ساختار آن‌ها می‌باشد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:55:40', 4, 'done'),
(5349, ' کدام گزینه نادرست است؟\n\n\n\n(مشابه امتحان نهایی خرداد 99، شهریور 1400، هماهنگ کشوری دی 1401)\n\n(1)\n\n(2)\n\n(3)\n\n(4) $- A^- Na^+$', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:55:49', 4, 'done'),
(5350, ' کدام موارد از مطالب زیر نادرست است؟\n\n(مشابه امتحان هماهنگ کشوری شهریور 1401، شهریور 1400 و دی 99)\n\nآ) مخلوط آب و روغن و صابون یک مخلوط به ظاهر همگن است.\n\nب) ذره‌های سازنده سوسپانسیون، توده‌های مولکولی با اندازه متفاوت است.\n\nپ) در آب سخت یون‌های کلسیم و منیزیم به مقادیر چشمگیری وجود دارد.\n\nت) قدرت پاک‌کنندگی صابون و پاک‌کننده‌های غیرصابونی یکسان است.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:55:56', 4, 'done'),
(5351, ' چند مورد از موارد زیر صحیح‌اند؟\n\n• نوع نیروهای بین مولکولی که مولکول‌های عسل با آب تشکیل می‌دهند مشابه نیروهای بین مولکولی گریس با مولکول‌های آب است.\n\n• زمانی‌که صابون در محیط آب حل شود پس از تفکیک یونی، بخش کاتیونی آن با لکه‌های چربی جاذبه قوی برقرار می‌کند.\n\n• تمام ویژگی‌های کلوئیدها مشابه محلول‌ها می‌باشد زیرا اندازه ذرات سازنده آن‌ها تقریباً برابر است.\n\n• نسبت شمار اتم‌های هیدروژن به کربن در یک مول اتیلن گلیکول بیش‌تر از همین نسبت در یک مول وازلین می‌باشد.\n\n• افزودن نمک‌های سولفات به صابون مانع از تشکیل رسوب‌های کلسیم و منیزیم در آب سخت می‌شود.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:02', 4, 'done'),
(5352, ' چند مورد از عبارت‌های زیر صحیح است؟\n\n(مشابه امتحان نهایی خرداد 1403، خرداد 1399 و شهریور 1399)\n\nآ) قدرت پاک‌کنندگی صابون به عوامل گوناگونی مانند نوع پارچه، مقدار و نوع صابون بستگی دارد.\n\nب) چربی‌ها یک استر سنگین به‌حساب می‌آیند.\n\nپ) برای زدودن رسوب تشکیل شده بر روی دیوارۀ سماور باید از یک پاک‌کننده غیرصابونی استفاده کرد.\n\nت) به پاک‌کننده‌های صابونی کلر می‌افزایند تا خاصیت ضدعفونی‌کنندگی آن بیشتر شود.\n\nث) میزان چسبندگی لکه‌های چربی بر روی پارچه نخی کمتر از پارچه‌های پلی‌استری است.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:08', 4, 'done'),
(5353, ' مقدار یکسانی صابون جامد را در ظرف 1 و 2 که دارای نمونه‌هایی از آب مقطر یا آب دریا است می‌ریزیم تا پس از هم زدن، محلول آب و صابون مطابق شکل روبه‌رو تهیه شود. کدام موارد از عبارت‌های زیر درست است؟\n\n\n\nآ) پس از شستن لباس با محلول ظرف 2 روی لباس مقداری لکه سفید رنگ باقی می‌ماند.\n\nب) ظرف 1 در ابتدا آب دریا داشته چون ارتفاع کف ایجاد شده در آن بیشتر است.\n\nپ) در ظرف 2 بخشی از کاتیون‌های صابون به‌صورت رسوب درآمده و ته‌نشین می‌شوند.\n\nت) اگر به‌جای صابون از پاک‌کننده غیرصابونی استفاده شود، ارتفاع کف در دو ظرف یکسان خواهد شد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:14', 4, 'done'),
(5354, ' در تبدیل یک اسید چرب به صابون جامد کدام‌یک از تغییرات زیر صورت نمی‌گیرد؟\n\nآ) ثابت ماندن شمار زوج الکترون‌های ناپیوندی\n\nب) افزایش انحلال‌پذیری در آب\n\nپ) تغییر نوع نیروی بین ذره‌ای غالب از واندروالسی به جاذبة یونی\n\nت) افزایش جرم مولی', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:19', 4, 'done'),
(5355, 'کدام‌یک از گزینه‌های زیر درست است؟', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:26', 4, 'done'),
(5356, 'چند مورد از موارد زیر جزء شباهت‌های پاک‌کننده‌های صابونی و غیرصابونی است؟\n\nآ) محلول بودن بخش آب‌گریز در چربی\n\nب) ساختار بخش آنیونی\n\nپ) رسوب کردن در واکنش با یون $Ca^{2+}$ و $Mg^{2+}$\n\nت) پایدار نمودن چربی در آب\n\nث) تعداد اتم‌های اکسیژن موجود در ساختار آنها', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:30', 4, 'done'),
(5357, 'کدام‌یک از گزینه‌های زیر در مورد پاک‌کننده‌ها صحیح است؟', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:35', 4, 'done'),
(5358, 'چند مورد از عبارت‌های زیر در رابطه با ساختار داده شده صحیح است؟\n\n\n\n(مشابه امتحان نهایی خرداد ۹۸ و شهریور ۹۹)\n\n$(C=12, O=16, H=1, Na=23, S=32: g.mol^{-1})$\n\n• درصد جرمی اتم‌های کربن در این پاک‌کننده تقریباً ۶۲٪ است.\n\n• هنگام انجام عمل پاک کردن چرک لباس که از جنس چربی است، بخش B با چربی‌ها واکنش شیمیایی می‌دهد و آن‌ها را می‌زداید.\n\n• بخش A، قسمت چربی‌گریز این پاک‌کننده است.\n\n• قدرت پاک‌کنندگی این نوع پاک‌کننده نسبت به پاک‌کننده‌ای با فرمول کلی $RCOONa$ ، بیشتر است.', 3, 3, 71, 268, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:42', 4, 'done'),
(5359, 'چه تعداد از عبارت‌های زیر درست است؟\n\n• محلول اغلب اسیدها و بازها، رسانای جریان برق هستند، در حالی‌که رسانایی آن‌ها با یکدیگر متفاوت است.\n\n• آرنیوس نخستین کسی بود که تفاوت رسانایی محلول‌های آبی $Li_2O$ و $N_2O_5$ و واکنش بین آن‌ها را توجیه کرد.\n\n• سفیدکننده‌ها برخلاف پاک‌کننده‌های غیرصابونی، علاوه بر ایجاد برهم‌کنش، با آلاینده‌های موجود واکنش نیز می‌دهند.\n\n• همه اکسیدهای نافلزی حاصل از عناصر دوره دوم، اسید آرنیوس به شمار رفته و در محلول آن‌ها غلظت یون هیدرونیوم از یون هیدروکسید بیشتر است.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:56:48', 4, 'done'),
(5360, 'همه عبارت‌های زیر درست‌اند؛ به‌جز ...', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:07', 4, 'done'),
(5361, 'کدام موارد از عبارت‌های زیر درست است؟ (مشابه امتحان نهایی خرداد ۱۴۰۱ و هماهنگ کشوری شهریور ۱۴۰۰ و ۱۴۰۱)\n\nالف) مخلوط پایدار شده آب و روغن با استفاده از صابون، نمونه‌ای از سوسپانسیون است.\n\nب) ذرات پخش شده در کلوئیدها و محلول‌ها برخلاف سوسپانسیون‌ها پایدار هستند.\n\nپ) ذره‌های سازنده سوسپانسیون ذرات ریزماده می‌باشند که همانند کلوئید پایدار هستند.\n\nت) آب گل آلود همانند شربت معده یک سوسپانسیون است.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:11', 4, 'done'),
(5362, 'چه تعداد از موارد زیر درست است؟ $(S=32, Na=23, O=16, C=12, H=1:g.mol^{-1})$\n\n\n\nساختار (b): $CH_3(CH_2)_{14}COONa$\n\nالف) در ساختار (a) سه اتم کربن می‌توان یافت که به هیچ اتم هیدروژنی متصل نیستند.\n\nب) نسبت شمار جفت‌الکترون‌های پیوندی به شمار جفت‌الکترون‌های ناپیوندی در آنیون ترکیب (b)، برابر ۹/۸ است.\n\nپ) ساختار (a) از مواد پتروشیمیایی طی واکنش‌های پیچیده، در صنعت تولید می‌شود و قدرت پاک‌کنندگی آن نسبت به ساختار (b) در آب سخت بیشتر است.\n\nت) رفتار نور در شیر، ژله و رنگ پوششی مشابه است و ذره‌های سازنده سوسپانسیون، ذرات ریزماده هستند که ته‌نشین می‌شوند.', 3, 3, 71, 268, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:16', 4, 'done'),
(5363, 'درستی یا نادرستی عبارات زیر به ترتیب در کدام گزینه ذکر شده است؟ (مشابه امتحان نهایی خرداد ۱۳۹۹)\n\n• نوعی اکسید فلزی برای کاهش میزان اسیدی بودن خاک به آن افزوده می‌شود.\n\n• محلول آبی سدیم کلرید حاوی یون‌هایی است که با جنبش‌های آزادانه و منظم در سرتاسر آن پراکنده‌اند.\n\n• به فرایندی که در آن یک ترکیب مولکولی در آب به یون‌های مثبت و منفی سازنده خود تبدیل می‌شود، یونش می‌گویند.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:21', 4, 'done'),
(5364, 'چند مورد از مطالب زیر، نادرست است؟\n\n• آرنیوس نخستین کسی بوده که اسیدها و بازها را بر یک مبنای علمی توصیف کرد.\n\n• شیمیدان‌ها پیش از آنکه با ویژگی اسیدها و بازها آشنا شوند، با ساختار آن‌ها آشنا شده بودند.\n\n• تعداد مول یون‌های حاصل از حل شدن ۱ مول $N_2O_5$ در آب با تعداد مول یون‌های حاصل از حل شدن ۱ مول $K_2O$ در آب برابر است.\n\n• اغلب داروها ترکیب‌های شیمیایی با خاصیت اسیدی یا بازی هستند.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-03-22 13:03:17', 5, 'done'),
(5365, ' با توجه به شکل‌های زیر، کدام موارد زیر صحیح هستند؟ (درجه یونش محلول $HA$ دو برابر درجه یونش محلول $HX$ است.)\n\n\n\n(مشابه امتحان نهایی خرداد ۱۴۰۲)\n\nالف) pH محلول $HX$ یک واحد بیشتر از محلول $HA$ است.\n\nب) غلظت یون $H^+$ در هر دو محلول برخلاف تعداد یون $H^+$ آنها، با هم برابر است.\n\nپ) اگر $HA$ یک اسید قوی باشد، آنگاه pH محلول $HX$، $0/7$ است.\n\nت) اگر $HX$ فورمیک‌اسید باشد، $HA$ می‌تواند استیک‌اسید باشد.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:26', 4, 'done'),
(5366, ' چند مورد از عبارت‌های زیر صحیح است؟\n\n(مشابه امتحان نهایی خرداد ۱۴۰۲ و هماهنگ کشوری شهریور ۱۴۰۰)\n\n• در دمای اتاق رسانایی الکتریکی محلول $0/1$ مولار $BaCl_2$ با محلول $0/1$ مولار $Al(NO_3)_3$ برابر است.\n\n• برای یک سامانه تعادلی در دمای ثابت، در هنگام برقراری تعادل، غلظت تعادلی گونه‌های شرکت‌کننده ثابت است.\n\n• در محلول‌های یک مولار $HCl$ و $HF$، غلظت یون کلرید کمتر از غلظت یون فلوئورید است.\n\n• در شرایط یکسان دما و غلظت، هرچه ثابت یونش یک اسید بیشتر باشد، pH محلول آن اسید بیشتر است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:32', 4, 'done'),
(5367, ' کدام‌یک از موارد زیر نادرست می‌باشند؟\n\nالف) سدیم هیدروکسید جامد، یک باز آرنیوس به‌شمار می‌رود، زیرا در آب طی یونش باعث تولید یون هیدروکسید می‌شود.\n\nب) $K_2O$، کربن دی‌اکسید و دی‌نیتروژن پنتااکسید به ترتیب باز، باز و اسید آرنیوس هستند.\n\nج) نمودار وابستگی درصد یونش و غلظت اسید $HF$ به‌صورت روبه‌رو است.\n\n\n\nد) در محلول آب گازدار، غلظت یون هیدروکسید $10^6$ برابر غلظت یون هیدرونیوم است.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:38', 4, 'done'),
(5368, ' با توجه به جدول داده شده و شکل‌های زیر در شرایط یکسان، کدام نتیجه‌گیری می‌تواند درست باشد؟', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:43', 4, 'done'),
(5369, ' کدام عبارت نادرست است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:48', 4, 'done'),
(5370, ' در دما و فشار یکسان، رسانایی الکتریکی محلول $0/2$ مولار از کدام ترکیب در مقایسه با بقیه بیشتر است؟\n\n', 3, 3, 71, 270, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:54', 4, 'done'),
(5371, ' کدام گزینه نادرست است؟\n\n', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:57:59', 4, 'done'),
(5372, 'محلول‌های $0/1$ مولار استیک‌اسید، هیدروسیانیک‌اسید و هیدروکلریک‌اسید در دمای اتاق را در نظر بگیرید. چند مورد از مطالب زیر درباره آن‌ها درست است؟\n\n\nالف) مقایسه pH این محلول‌ها به‌صورت «$HCN > CH_3COOH > HCl$» است.\n\nب) رسانایی الکتریکی دو محلول از آنها از رسانایی الکتریکی محلول $0/1$ مولار $HF$ کمتر است.\n\nپ) شمار مولکول‌ها در محلول هیدروسیانیک‌اسید در مقایسه با دو محلول دیگر (در شرایط و حجم یکسان) بیشتر است.\n\nت) برای خنثی کردن ۲۰۰ میلی‌لیتر از هر سه محلول، مقدار یکسانی سدیم هیدروکسید خالص لازم است.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:04', 4, 'done'),
(5373, ' با توجه به دو محلول زیر و با در نظر گرفتن اینکه درجه یونش آمونیاک چهار برابر درجه یونش متیل‌آمین است، چند مورد نادرست است؟ (هر مولکول متیل‌آمینی که یونیده شود، یک یون هیدروکسید در محلول آزاد می‌شود.)\n\n\n\nالف) شمار مولکول‌های یونیده نشده در محلول متیل‌آمین بیشتر از محلول آمونیاک است.\n\nب) pH محلول آمونیاک از pH محلول متیل‌آمین بیشتر است.\n\nپ) غلظت یون هیدرونیوم در محلول متیل‌آمین کمتر از محلول آمونیاک است.\n\nت) با افزودن همزمان هر دو محلول در یک ظرف دیگر، ثابت یونش آمونیاک بیشتر از متیل‌آمین تغییر خواهد کرد.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:09', 4, 'done'),
(5374, ' اختلاف شمار عبارات صحیح و عبارات نادرست چند واحد است؟ $[\\log 3 \\simeq 0/5]$\n\n• اگر غلظت یون هیدرونیوم در شیره معده برابر $0/03$ مول بر لیتر باشد، pH آن برابر $1/5$ است.\n\n• در تمام محلول‌های آبی خنثی، غلظت یون هیدرونیوم و هیدروکسید یکسان بوده و برابر با $10^{-7}$ مولار است.\n\n• در واکنش‌های برگشت‌پذیر، واکنش‌های رفت و برگشت همزمان و به‌طور پیوسته انجام می‌شوند تا اینکه غلظت واکنش‌دهنده‌ها و فرآورده‌ها برابر شوند.\n\n• اسیدهای ضعیف در آب به میزان جزئی یونیده می‌شوند و قسمت عمده مولکول‌های اسید یونیده نمی‌شود.\n\n• پاک‌کننده‌ای به‌فرم کلی $RC_6H_4SO_3^-Na^+$ قدرت پاک‌کنندگی بیشتری از پاک‌کننده‌های صابونی دارد.', 3, 3, 71, 270, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:20', 4, 'done'),
(5375, ' اگر نمودار زیر نشان‌دهنده ثابت یونش چند اسید تک‌پروتون‌دار در دمای اتاق باشد، کدام مورد صحیح است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:24', 4, 'done'),
(5376, ' مول‌های برابری از نیتریک‌اسید (I) و نیترواسید (II) در حجم‌های برابری از محلول آبی در دمای یکسان حل شده است. چند مورد از عبارت‌های زیر درباره این دو محلول درست‌اند؟\n\nالف) محلول (I) رسانایی بیشتری از محلول (II) دارد.\n\nب) تعداد ذرات در محلول (I) از تعداد ذرات محلول (II) بیشتر است.\n\nپ) با گرم کردن دو محلول، اختلاف غلظت یون هیدرونیوم دو محلول کاهش می‌یابد.\n\nت) در تهیه این محلول‌ها، جرم بیشتری از حل‌شونده در محلول (I) حل شده است.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:29', 4, 'done'),
(5377, ' چند مورد از عبارت‌های زیر نادرست است؟\n\n• مقدار pH یک نمونه از شیر ترش شده، همانند خون موجود در رگ‌ها و هم‌چنین یک نمونه آب گازدار، کوچکتر از ۷ است.\n\n• نسبت غلظت یون هیدرونیوم به یون هیدروکسید در یک نمونه از محلول لوله‌بازکن، بیشتر از یک نمونه محلول شیشه‌پاک‌کن است.\n\n• از واکنش محلول $HCl$ با سود، محلولی ایجاد شده که در هیچ‌یک از یون‌های موجود در آن پیوند اشتراکی وجود ندارد.\n\n• در دمای اتاق اگر در خاکی غلظت یون هیدرونیوم برابر با $10^{-6}$ مول بر لیتر باشد، گل ادریسی در آن خاک به‌رنگ آبی شکوفا می‌شود.', 3, 3, 71, 272, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:34', 4, 'done'),
(5378, ' در دمای یکسان، محلول I حاوی اسید ضعیف $HA$ با $K_a=4 \\times 10^{-8}$ و محلول II حاوی اسید ضعیف $HD$ با $K_a=9 \\times 10^{-4}$ می‌باشد؛ کدام گزینه نادرست است؟', 3, 3, 71, 272, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:15:59', 1, '2026-10-12 21:58:39', 4, 'done'),
(5379, ' چند مورد از مطالب زیر نادرست است؟ ($H=1$ و $C=12$ و $O=16 : g.mol^{-1}$)\n\n- جرم مولی استر سه عاملی که در زنجیر آلکیل اسید چرب سازنده آن 14 اتم کربن وجود دارد برابر 764 گرم بر مول است.\n\n- اختلاف شمار پیوندهای اشتراکی در ساختار مولکول‌های اوره و اتیلن گلیکول برابر اختلاف شمار اتم‌های سازنده این دو ماده است.\n\n- شاخص امید به زندگی در دوره زمانی 1390 تا 1395 برای بیشتر مردم جهان در حدود 50 تا 60 سال بوده است.\n\n- شمار اتم‌های هیدروژن در فرمول شیمیایی وازلین نصف همین شمار در فرمول شیمیایی روغن زیتون است و هر دو ماده در هگزان حل می‌شوند.\n\n- لکه عسل به راحتی با آب شسته می‌شود، زیرا عسل حاوی مولکول‌های قطبی است که در ساختار خود شمار قابل توجهی گروه عاملی مشابه گروه عاملی موجود در جوهر سرکه دارد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:58:44', 4, 'done'),
(5380, ' مخلوط $A$ نوعی مخلوط پایدار و ناهمگن است. کدام‌یک از موارد بیان شده در مورد این مخلوط درست است؟\n\nالف) نور را پخش می‌کند.\n\nب) شیر و ژله نمونه‌هایی از مخلوط $A$ هستند.\n\nج) با افزودن صابون به مخلوط آب و روغن می‌توان مخلوط $A$ را ایجاد کرد.\n\nد) ذره‌های سازنده آن شامل توده‌های مولکولی و یون‌ها با اندازه‌های متفاوت است.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:58:48', 4, 'done'),
(5381, ' چند مورد از مطالب زیر نادرست است؟\n\nالف) پارچه پلی‌استر در مقایسه با پارچه نخی، جاذبه‌ای قوی‌تر با لکه چربی برقرار می‌کند.\n\nب) وجود آنزیم در صابون سبب می‌شود که قدرت پاک‌کنندگی آن افزایش یابد.\n\nج) برای افزایش قدرت پاک‌کننده‌های غیرصابونی باید به آن‌ها نمک فسفات‌دار افزود.\n\nد) قدرت پاک‌کنندگی صابون بدون آنزیم در دمای $40^\\circ C$ از صابون آنزیم‌دار در دمای $30^\\circ C$ برای نوع یکسانی از پارچه، بیشتر است.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:58:52', 4, 'done'),
(5382, 'چند مورد از عبارت‌های زیر درست هستند؟\n\nالف) برای از بین بردن جوش‌های صورت، استفاده از صابون‌های گوگرددار توصیه می‌شود.\n\nب) برای افزایش قدرت ضدعفونی‌کنندگی صابون به آن کلر اضافه می‌کنند.\n\nج) پاک‌کننده‌های غیرصابونی به دلیل تشکیل گاز در آب از قدرت پاک‌کنندگی بالایی برخوردار هستند.\n\nد) صابون مراغه که از جوشاندن پیه گوسفند و سود سوزآور در دیگ آب تهیه می‌شود برای موهای چرب مناسب است.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:58:56', 4, 'done'),
(5383, ' کدام‌یک از عبارت‌های زیر درست است؟\n\nالف) برای زدودن رسوب جداره کتری ($CaCO_3$) نمی‌توان از پاک‌کننده‌های غیرصابونی استفاده کرد.\n\nب) پودر لوله‌بازکن مخلوطی از سدیم و آلومینیم هیدروکسید جامد است.\n\nج) از واکنش پودر لوله‌بازکن با آب گازی به‌دست می‌آید که آرایش الکترون ـ نقطه‌ای آن به‌صورت $: \\ddot{X} - \\ddot{X} :$ است.\n\nد) برای باز کردن لوله‌ها و مسیرهایی که در اثر تجمع چربی بسته شده‌اند می‌توان از محلول جوهر نمک استفاده کرد.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:01', 4, 'done'),
(5384, ' چند مورد از عبارت‌های زیر در مورد بازهای آرنیوس نادرست هستند؟\n\nالف) پس از حل شدن در آب، غلظت یون هیدرونیوم را در آب افزایش می‌دهند.\n\nب) برخی از آنها در ساختار خود گروه هیدروکسیل ($OH$) دارند.\n\nج) به طور کامل یا جزئی در آب به یون تبدیل می‌شوند.\n\nد) محلول آنها در مقایسه با محلول‌های اسیدی از رسانایی الکتریکی بیشتری برخوردارند.', 3, 3, 71, 273, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:05', 4, 'done'),
(5385, ' به ترتیب از راست به چپ کدام‌یک از واکنش‌های زیر امکان توجیه ویژگی اسیدی و بازی مواد را مطابق با نظریه آرنیوس ندارد و شمار یون‌ها در محلول آبی به‌دست آمده در کدام واکنش بیشتر است؟\n\na) $N_2O_5(s) + H_2O(l) \\rightarrow 2HNO_3(aq)$\n\nb) $NH_3(g) + HCl(g) \\rightarrow NH_4Cl(s)$\n\nc) $BaO(s) + H_2O(l) \\rightarrow Ba(OH)_2(aq)$', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:09', 4, 'done'),
(5386, ' چه تعداد از عبارت‌های زیر درست هستند؟\n\n- نسبت شمار عنصرها به شمار اتم‌ها در اوره برابر با همین نسبت در فرمیک اسید است.\n\n- پاک‌کننده‌های غیرصابونی قدرت پاک‌کنندگی بیشتری نسبت به صابون‌ها دارند و فرمول کلی آن ها $RC_6H_4SO_3Na$ است.\n\n- فرمول مولکولی اسید چرب سازنده نوعی روغن با زنجیرهای هیدروکربنی یکسان و سیرنشده می‌تواند به صورت $C_{18}H_{33}COOH$ باشد.\n\n- فرمول شیمیایی صابون مایع نیتروژن‌داری که زنجیر هیدروکربنی سیرشده آن دارای 37 اتم هیدروژن باشد به صورت $C_{19}H_{37}CO_2N$ است.\n\n- نسبت جرم مولی اتیلن گلیکول به مجموع جرم مولی مواد تشکیل‌دهنده پودر لوله‌بازکن به تقریب برابر 0.92 است.\n\n($H=1, C=12, O=16, Na=23, Al=27 : gmol^{-1}$)', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:14', 4, 'done'),
(5387, 'نمودارهای زیر غلظت نسبی گونه‌های موجود در محلول در اسید $HA$ و $HX$ را در شرایط یکسان دما، حجم و غلظت نشان می‌دهند. کدام نتیجه‌گیری به درستی بیان شده است؟\n\n\n\n1) $pH$ محلول اسید $HA$، کوچک‌تر از $pH$ محلول اسید $HX$ است.\n\n2) غلظت یون هیدروکسید در محلول $HX_{(aq)}$، 5 برابر غلظت این یون در محلول $HA_{(aq)}$ است.\n\n3) اگر $A$ و $X$ دو عنصر از گروه 17 جدول تناوبی باشند، جرم مولی $HA$ به یقین از جرم مولی $HX$ بیشتر است.\n\n4) اگر غلظت مولار $HA$ پیش از یونش برابر 1.5 باشد، آن گاه ثابت یونش $HA$ برابر 0.075 است.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:18', 4, 'done'),
(5388, ' چند مورد از عبارت‌های داده شده درست است؟\n\n- با تغییر دما اختلاف $pH$ محلول مولار $HCl_{(aq)}$ و $HF_{(aq)}$ تغییر چندانی نمی‌کند.\n\n- اگر با افزودن آب، حجم محلول حاوی یک اسید $n$ برابر شود، $pH$ آن به اندازه $\\log n$ افزایش می‌یابد.\n\n- بر پایه مدل آرنیوس می‌توان تفاوت غلظت مولی یون هیدرونیوم حاصل از انحلال مول برابری از گازهای $CO_2$ و $SO_2$ در آب را توجیه کرد.\n\n- در شرایطی که $pH$ و حجم دو محلول آبی جداگانه از نیتریک اسید و نیترو اسید با هم برابر باشد، شمار گونه‌های موجود در محلول نیتریک اسید کمتر است.\n\n- در شرایطی که $pH$ و حجم دو محلول آبی جداگانه از فرمیک اسید و استیک اسید با هم برابر باشد، حجم گاز حاصل از واکنش مقدار معینی فلز منیزیم با این دو محلول برابر خواهد بود.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:23', 4, 'done'),
(5389, ' 1.25 گرم اسید $HA$ را در $50 mL$ آب و 2.4 گرم اسید $HB$ را در $60 mL$ آب به طور جداگانه حل می‌کنیم اگر غلظت یون\n\n($HA=50, HB=100 : gmol^{-1}$) و از تغییر حجم محلول‌ها صرف نظر کنید.)\n\n- رسانایی الکتریکی محلول $HA$ کمتر از $HB$ است؛ زیرا درجه یونش آن کوچک تر است.\n\n- درجه یونش $HB$ به میزان 25 درصد بیشتر از درجه یونش $HA$ است.\n\n- مجموع شمار گونه‌های حل شده در محلول $HA$ بیشتر از محلول $HB$ است.\n\n- اگر مجموع غلظت مولی یون‌ها در محلول اسید $HB$ برابر با $0.3 mol.L^{-1}$ باشد، درصد یونش اسید $HA$ برابر 30 است.\n\n- با قرار دادن محلول‌ها در مدار الکتریکی زیر شدت روشنایی لامپ در محلول $HB$ بیشتر از محلول $HA$ خواهد بود\n\n\n\n.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:27', 4, 'done'),
(5390, ' جدول زیر غلظت تعادلی گونه‌های موجود در دو محلول جداگانه از هیدروفلوئوریک اسید با غلظت‌های آغازی گوناگون را در دمای $25^\\circ C$ نشان می‌دهد. چند مورد از مطالب بیان شده درست است؟\n\n\n\n.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:34', 4, 'done'),
(5391, 'چند مورد از عبارت‌های زیر نادرست است؟\n\n- با افزودن الکترولیت‌های قوی به آب خالص، رسانایی الکتریکی آب به مقدار چشمگیری افزایش می‌یابد.\n\n- با افزایش غلظت یک اسید ضعیف، درجه یونش آن کاهش ولی ثابت یونش آن افزایش می‌یابد.\n\n- حجم گاز آزاد شده از واکنش دو نوار منیزیم یکسان با محلول‌هایی از هیدروبرمیک اسید و فورمیک اسید در شرایط یکسان دما، حجم و غلظت برابر است.\n\n- در محلولی از $HF(aq)$ با $pH=1/5$ و $\\alpha=0/024$ غلظت تعادلی $HF(aq)$ برابر $1/22$ مولار است.\n\n- در دمای ثابت با ۴ برابر کردن غلظت اولیه اسید بسیار ضعیف $HA$، درصد یونش آن به تقریب، نصف می‌شود.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:39', 4, 'done'),
(5392, 'کدام یک از عبارت‌های زیر به درستی بیان شده است؟', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:43', 4, 'done'),
(5393, 'با توجه به شکل زیر، کدام مورد یا موارد صحیح است؟ $(\\log 2=0/3, \\log 3=0/5) (Na=23, O=16, H=1 : g.mol^{-1})$\n\n\n\nالف: در دمای اتاق، $pH$ محلول به دست آمده از انحلال $0/4$ گرم سود سوزآور در یک لیتر آب، از $pH$ هر دو محلول بیشتر است.\n\nب: غلظت یون هیدروکسید در ظرف (ب) برابر $0/25$ مول بر لیتر است.\n\nپ: در شرایط یکسان از نظر دما و غلظت، محلول (ب) شمار بیشتری از یون هیدرونیوم در هر لیتر خود را دارد.\n\nت: در شرایط یکسان از نظر دما و حجم، محلول (آ) رسانایی الکتریکی بیشتری نسبت به محلول (ب) دارد.\n\nث: اگر مقدار عددی ثابت یونش آمونیاک برابر $1/8 \\times 10^{-5}$ باشد، آن‌گاه غلظت مولی آمونیاک در ظرف (آ) برابر $0/14$ مولار است.', 3, 3, 71, 273, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:48', 4, 'done'),
(5394, 'چه تعداد از موارد زیر، عبارت: «مصرف جرم یکسانی از .............. در مقایسه با .............. در واکنش با اسید معده، تأثیر .............. بر افزایش $pH$ معده خواهد داشت» را به درستی کامل می‌کند؟ $(H=1, C=12, O=16, Na=23, Cl=35/5 : g.mol^{-1})$\n\n- $Mg(OH)_2$ - $NaHCO_3$ - کمتری\n\n- $NaHCO_3$ - $Al(OH)_3$ - بیشتری\n\n- $NaHCO_3$ - $Na_2CO_3$ - بیشتری\n\n- $Mg(OH)_2$ - $Al(OH)_3$ - کمتری', 3, 3, 71, 274, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:52', 4, 'done'),
(5395, 'چه تعداد از عبارت‌های زیر نادرست است؟\n\n- برای حل شدن یک ماده در یک حلال، باید میان ذره‌های حل شونده و حلال در محلول، جاذبه قوی برقرار شود.\n\n- عسل دارای مولکول‌های قطبی بوده و به دلیل تشکیل پیوندهای هیدروژنی با آب، به خوبی در آن حل می‌شود.\n\n- اتیلن گلیکول شامل یون‌های مثبت و منفی بوده و به همین دلیل در آب حل می‌شود.\n\n- موادی که ذره‌های سازنده آن‌ها، اندازه‌های مشابهی دارند، می‌توانند در یکدیگر حل شوند.\n\n- گشتاور دوقطبی مولکول اوره بزرگ‌تر از صفر بوده و در آب حل می‌شود.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 21:59:57', 4, 'done'),
(5396, 'کدام‌یک از مطالب زیر در ارتباط با مخلوط پودر آلومینیم و سدیم هیدروکسید که نوعی پاک کننده به شمار می‌رود، درست است؟', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:01', 4, 'done'),
(5397, 'برای تهیه نوعی صابون نیتروژن‌دار از لینولئیک اسید با فرمول مولکولی $C_{18}H_{32}O_2$ استفاده می‌شود. کدام مطلب در مورد این صابون درست است؟ $(O=16, N=14, C=12, H=1 : g.mol^{-1})$', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:06', 4, 'done'),
(5398, 'چه تعداد از ویژگی‌های زیر در تولید و ساخت انواع پاک کننده‌های غیرصابونی نقش مهمی داشته است؟\n\n- حفظ قدرت پاک کنندگی در آب‌های سخت\n\n- سهولت تولید و در دسترس بودن مواد اولیه برای ساخت آن‌ها\n\n- عدم توازن میان عرضه و تقاضای جهانی برای تولید صابون\n\n- قدرت خورندگی بیشتر در مقایسه با صابون برای پاک کردن لکه‌های چربی و روغن', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:10', 4, 'done'),
(5399, 'در ساختار یک پاک کننده غیرصابونی جامد، ۱۱ گروه $-CH_2-$ و ۳۱ پیوند کربن - هیدروژن وجود دارد. تمام عبارت‌های زیر در ارتباط با این پاک کننده نادرست‌اند، به جز .............. $(Na=23, S=32, O=16, C=12, H=1 : g.mol^{-1})$', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:36', 4, 'done'),
(5400, 'در دمای یکسان، مقدار مول‌های برابری از $N_2O_5$ و اکسیدی از یک فلز قلیایی را به طور جداگانه و به ترتیب در ظرف‌های (I) و (II) در مقدار معینی آب حل کرده و درنهایت حجم هرکدام از محلول‌ها را به یک لیتر می‌رسانیم. در ارتباط با این ظرف‌ها، چند مورد از مطالب زیر درست است؟\n\n- در محلول ظرف (II) برخلاف ظرف (I)، یون هیدرونیوم وجود ندارد.\n\n- شمار آنیون‌های موجود در محلول (II) بیشتر از محلول (I) است.\n\n- با ایجاد مدار الکتریکی در هرکدام از ظرف‌ها و ایجاد جریان الکتریکی، نور لامپ ظرف (I)، بیشتر از ظرف (II) خواهد بود.\n\n- اگر به ظرف (II) مقداری چربی اضافه شود، امکان تشکیل نمک اسید چرب وجود دارد.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:42', 4, 'done'),
(5401, 'ذره‌های سازنده مخلوط‌های $A$، $B$ و $C$ به ترتیب «توده‌های مولکولی»، «یون‌ها» و «ذره‌های ریز ماده» هستند. کدام‌یک از مطالب زیر در ارتباط با این مخلوط‌ها نادرست است؟', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:46', 4, 'done'),
(5402, 'کدام مطالب زیر در ارتباط با آرنیوس و مدل وی درباره اسیدها و بازها درست است؟\n\nآ) براساس مدل آرنیوس، می‌توان اسید و باز را تشخیص داد اما نمی‌توان درباره میزان اسیدی یا بازی بودن یک محلول اظهارنظر کرد.\n\nب) مطابق این مدل، اگر یک ماده اسید نباشد، به یقین یک باز است.\n\nپ) آرنیوس نخستین کسی بود که ویژگی‌های اسیدها و بازها را شناخت.\n\nت) یافته‌های آرنیوس نشان داد که محلول اسیدها و بازها رسانای جریان برق هستند اما میزان رسانایی آن‌ها با یکدیگر متفاوت است.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:51', 4, 'done'),
(5403, 'کدام‌یک از گزینه‌ها از نظر درستی یا نادرستی مشابه عبارت زیر است؟\n\n«مخلوطی از سدیم جامد و آلومینیم هیدروکسید، به عنوان پودر لوله بازکن به کار می‌رود.»', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:00:56', 4, 'done'),
(5404, 'چه تعداد از عبارت‌های زیر در ارتباط با پاک کننده‌های (I) و (II)، نادرست است؟\n\n$(I) C_{17}H_{35}COONa$ , $(II) C_{12}H_{25}C_6H_4SO_3Na$\n\n- برای مقایسه قدرت پاک کنندگی دو ترکیب می‌توان میزان واکنش‌پذیری آن‌ها را با یک آلاینده مشخص، مورد آزمایش قرار داد.\n\n- پاک کننده (II) در مراغه به طور طبیعی و بدون افزودنی شیمیایی قابل تولید است.\n\n- در ساختار هر کدام از دو پاک کننده، سه پیوند دوگانه وجود دارد.\n\n- اساس پاک کنندگی دو ترکیب یکسان بوده و آلاینده‌ها را به محلول‌های پایدار تبدیل می‌کنند.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:02:03', 4, 'done'),
(5405, 'غلظت یون هیدروکسید در محلول‌های $a$ مولار اسید $HA$ و $b$ مولار اسید $HB$ با هم برابر است. چه تعداد از عبارت‌های زیر در ارتباط با این دو اسید، نادرست است؟ (دما $25^{\\circ}C$ بوده و $a > b$ است.)\n\n- رسانایی الکتریکی محلول $HA$ بیشتر از محلول $HB$ است.\n\n- سرعت واکنش محلول $HA$ با فلز منیزیم بیشتر از محلول $HB$ با همان قطعه از فلز منیزیم است.\n\n- درجه یونش اسید $HA$ بزرگ‌تر از درجه یونش اسید $HB$ است.\n\n- ثابت یونش اسید $HB$ کوچک‌تر از ثابت یونش اسید $HA$ است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:02:07', 4, 'done'),
(5406, 'با فرض شرایط یکسان از نظر دما و غلظت، کدام مقایسه‌های زیر درست است؟\n\nآ) رسانایی الکتریکی محلول آبی: هیدروکلریک اسید = سولفوریک اسید\n\nب) شمار مولکول‌های دو اتمی در محلول آبی: هیدروفلوئوریک اسید > هیدروبرمیک اسید\n\nپ) سرعت واکنش با یک گرم پودر لیتیم: استیک اسید < فورمیک اسید\n\nت) شمار یون‌های هیدروکسید در محلول آبی: نیترواسید > نیتریک اسید', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:02:12', 4, 'done'),
(5407, 'باتوجه به این‌که در دمای معین، ثابت یونش اسید ضعیف $HA$ کوچک‌تر از ثابت یونش اسید ضعیف $HB$ بوده و $HZ$ یک اسید قوی است، کدام عبارت‌های زیر درست هستند؟\n\nآ) $pH$ محلول مولار $HA$ از $pH$ محلول مولار $HB$ بیشتر است.\n\nب) رسانایی الکتریکی محلول $HZ$ ، بیشتر از دو محلول دیگر و شمار مولکول‌ها در محلول اسید $HA$ ، کم‌تر از دو محلول دیگر است.\n\nپ) اگر غلظت سه محلول با هم برابر باشد، حجم گاز حاصل از واکنش یک لیتر از هرکدام از این محلول‌ها با مقدار یکسانی پودر آهن، برابر خواهد بود.\n\nت) فرایند یونش $HA$ و $HB$ در آب تعادلی بوده و با افزایش مقدار آن‌ها در محلول، درجه یونش آن‌ها به درجه یونش $HZ$ نزدیک می‌شود.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:13', 1, '2026-10-12 22:02:16', 4, 'done'),
(5408, ' با توجه به شکل مقابل، کدام موارد از مطالب زیر درست هستند؟\n\n\n\nآ: مواد $A$ و $B$ به ترتیب می‌توانند معادل با نمونه‌هایی از اتیلن‌گلیکول و آب باشند.\n\nب: اگر $A$ و $B$ معادل با هگزان و آب باشند، یک نمونه چربی در حلال با چگالی کمتر حل می‌شود.\n\nپ: مخلوط $(I)$ مانند مخلوطی از برم در هگزان، یک نوع مخلوط ناهمگن به شمار می‌رود.\n\nت: اگر $A$ و $B$ معادل آب و روغن باشند، صابون می‌تواند مخلوط $(I)$ را به مخلوط $(II)$ تبدیل کنند.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:23', 4, 'done'),
(5409, ' کدام موارد از عبارت‌های زیر درست است؟\n\nآ: آب، یک حلال قطبی است و پاک‌کنندۀ مناسبی برای لکه‌های شیرینی مانند آب قند و شربت آبلیمو به شمار می‌رود.\n\nب: نسبت شمار جفت الکترون‌های پیوندی به ناپیوندی در اوره، با نسبت شمار اتم‌ها به شمار عناصر در آن یکسان است.\n\nپ: مولکول‌های روغن زیتون، نامحلول در آب بوده و همانند ذرات وازلین، از دو بخش قطبی و ناقطبی تشکیل شده‌اند.\n\nت: معروف‌ترین صابون سنتی ایران به حالت جامد بوده و بخاطر افزودنی‌های مناسب، در شستن موی چرب کاربرد دارد.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:28', 4, 'done'),
(5410, ' چه تعداد از محلول‌های زیر در برخورد با کاغذ $pH$، رنگ آن را از زرد به آبی تغییر می‌دهند؟\n\nآ: محلول حاصل از انحلال لیتیم اکسید در آب\n\nب: یک نمونه از محلول جوهر نمک\n\nپ: یک نمونه از محلول سرکه سفید\n\nت: محلول حاصل از انحلال صابون مایع در آب\n\nث: محلول حاصل از انحلال پودر آهک در آب', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:32', 4, 'done'),
(5411, ' کدام‌یک از عبارت‌های داده شده نادرست است؟', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:36', 4, 'done'),
(5412, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ: هر ترکیب شیمیایی که امکان برقرار شدن پیوند هیدروژنی بین مولکول‌های آن وجود داشته باشد، محلول در آب است.\n\nب: چسبندگی چربی به پارچه پلی‌استری کم‌تر از پارچه نخی بوده و ذرات چربی از روی این پارچه راحت‌تر پاک می‌شود.\n\nپ: با گذاشتن مخلوط آب، روغن و صابون در یک محیط ثابت، ذرات صابون موجود در مخلوط به مرور ته‌نشین می‌شوند.\n\nت: مخلوطی از پودر آلومینیم و سدیم هیدروکسید، همانند سفیدکننده‌ها، یک پاک‌کننده خورنده به شمار می‌رود.\n\nث: افزودن آنزیم‌های مناسب، همانند افزایش دمای آب، موجب افزایش قدرت پاک‌کنندگی صابون‌ها می‌شود.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:40', 4, 'done'),
(5413, ' ساختار بخش آنیونی نوعی پاک‌کننده به صورت زیر است:\n\n\n\nنسبت شمار اتم‌های هیدروژن به کربن در ساختار این پاک‌کننده کدام است و ذرات این پاک‌کننده پس از ورود به مخلوط آب و روغن، از چه سمتی به طرف ذرات آب جهت‌گیری پیدا می‌کنند؟', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:46', 4, 'done'),
(5414, ' کدام موارد از عبارت‌های زیر نادرست است؟\n\nآ: کلوئیدها از توده‌های مولکولی با اندازه‌های متفاوت تشکیل شده‌اند و کمتر از سوسپانسیون‌ها نور را پخش می‌کنند.\n\nب: جوهر نمک، همانند سفیدکننده‌ها، علاوه بر ایجاد برهمکنش، با آلاینده‌های موجود در محیط واکنش نیز می‌دهد.\n\nپ: آرنیوس با تحقیق روی رسانایی محلول‌هایی با حلال آلی، یک مبنای علمی برای توصیف اسیدها و بازها ارائه کرد.\n\nت: همه اکسیدهای نافلزی حاصل از عناصر دوره دوم، اسید آرنیوس به شمار رفته و $pH$ محلول را کاهش می‌دهند.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:50', 4, 'done'),
(5415, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ: در ساختار ترکیب الکلی که به عنوان ضدیخ کاربرد دارد، $9$ پیوند اشتراکی و $4$ جفت الکترون ناپیوندی یافت می‌شود.\n\nب: شاخص امید به زندگی نشان می‌دهد با توجه به خطرات موجود در زندگی، انسان‌ها حداقل چند سال عمر می‌کنند.\n\nپ: حداقل یکی از اتم‌های کربن موجود در ساختار پاک‌کننده‌های غیرصابونی به هیچ اتم هیدروژنی متصل نشده‌است.\n\nت: چربی‌ها، مخلوط اسیدهای چرب و استرهای بلند زنجیر بوده و نیروی بین مولکولی غالب آن‌ها وان‌دروالسی است.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:02:57', 4, 'done'),
(5416, ' کدام موارد از عبارت‌های داده شده درست هستند؟\n\nآ: رنگ‌های پوششی از ذرات ریز ماده ساخته شده و با قرار دادن یک نمونه از آن‌ها در مکان ثابت، ته‌نشین می‌شوند.\n\nب: گاز تولید شده در واکنش مخلوط آلومینیم و سدیم هیدروکسید با آب، از واکنش سدیم با آب نیز تولید می‌شود.\n\nپ: در مخلوطی از آب، صابون و روغن، ذرات صابون از سمت دم هیدروکربنی خود در مجاورت با روغن قرار می‌گیرند.\n\nت: نیترواسید، ثابت یونش بزرگ‌تر از یک مول بر لیتر داشته و برخلاف نیتریک‌اسید، یک اسید ضعیف به شمار می‌رود.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:01', 4, 'done'),
(5417, ' به شرط یکسان بودن غلظت اسیدها، سرعت تولید فراورده گازی در واکنش میان مواد موجود در کدام گزینه در دمای داده شده نسبت به سایر موارد کمتر است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:05', 4, 'done'),
(5418, ' کدام یک از عبارت‌های زیر درست است؟', 3, 3, 71, 272, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:10', 4, 'done'),
(5419, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ: دی‌نیتروژن پنتاکسید، در دمای اتاق به حالت جامد بوده و با حل شدن نیم مول از آن در آب، $2$ مول یون تولید می‌شود.\n\nب: اتانول، یک ترکیب بی‌رنگ بوده و رسانایی الکتریکی محلول آبی آن در مقایسه با محلول شکر در آب بیشتر است.\n\nپ: با قرار دادن محلول هیدروکلریک اسید در مسیر یک مدار، یون‌های $Cl^-$ به سمت قطب مثبت حرکت می‌کنند.\n\nت: اسید معده موجب فعال کردن آنزیم‌های مورد نیاز برای تجزیه مواد غذایی موجود در معده انسان می‌شود.\n\nث: در دمای یکسان، رسانایی محلول یک اسید قوی، همواره بیشتر از محلول یک اسید ضعیف است.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:14', 4, 'done'),
(5420, ' همه عبارت‌های داده شده درست هستند، بجز .........', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:18', 4, 'done'),
(5421, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ: اگر $[H^+]$ در محلول یک اسید تک‌پروتون‌دار با غلظت اولیه اسید برابر باشد، ثابت یونش آن اسید بسیار بزرگ است.\n\nب: با افزودن مقداری آب خالص به محلولی از نیترواسید، درجه یونش اسید مورد نظر در محلول افزایش پیدا می‌کند.\n\nپ: اگر غلظت یون هیدروکسید در یک محلول اسیدی $2$ برابر شود، $pH$ این محلول $1$ واحد افزایش پیدا می‌کند.\n\nت: محلول حاصل از انحلال اسیدهای ضعیف مثل هیدروسیانیک اسید در آب، یک سامانه تعادلی خواهد بود.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:22', 4, 'done'),
(5422, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ: با یونیده شدن همه اسیدهایی که طی واکنش تعادلی در محلول یونش می‌یابند، یک آنیون چنداتمی ایجاد می‌شود.\n\nب: در دما و غلظت یکسان، قدرت اسیدی محلول نیتریک اسید بیشتر از قدرت اسیدی محلولی از نیترواسید است.\n\nپ: محلولی آبی که $[H^+]$ در آن برابر $10^{-7} \\times 3$ مولار است، در برخورد با کاغذ $pH$ حتما رنگ آن را قرمز می‌کند.\n\nت: تفاوت غلظت مولی یون‌های هیدروژن و هیدروکسید در باران اسیدی نسبت به باران معمولی بیشتر است.\n\nث: رسانایی محلول یک مولار کروم $(III)$ نیترات از رسانایی محلول یک مولار پتاسیم سولفات بیشتر است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:27', 4, 'done'),
(5423, ' با توجه به اطلاعات موجود در جدول زیر، با ریختن محلول هیدروبرمیک اسید بر روی مقداری جوش شیرین، گاز ......... آزاد شده و واکنش ......... در مقایسه با واکنش دیگر با سرعت بیشتری انجام می‌شود.', 3, 3, 71, 274, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:32', 4, 'done'),
(5424, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ: اسید معده محتوی مقداری سولفوریک اسید بوده و برگشت آن به مری، سبب ایجاد سوزش و درد در ناحیه سینه می‌شود.\n\nب: اگر مقداری هیدروژن کلرید را در محلولی از استیک اسید حل کنیم، غلظت یون استات در محلول تغییر نخواهد کرد.\n\nپ: مقدار $pH$ یک نمونه از شیر ترش‌شده، همانند خون موجود در رگ‌ها و یک نمونه از آب گازدار، کوچک‌تر از $7$ است.\n\nت: پس از انحلال دو مول دی‌نیتروژن پنتاکسید جامد در آب، چهار مول یون در محلول مورد نظر تولید می‌شود.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:36', 4, 'done'),
(5425, ' کدام موارد از عبارت‌های زیر درست است؟\n\nآ: سدیم هیدروکسید، یک ترکیب یونی چندتایی بوده و با انحلال در آب، یونش یافته و $[OH^-]$ را در محلول افزایش می‌دهد.\n\nب: با قرار گرفتن محلول $HCN$ در مسیر مدار الکتریکی، یون‌هایی با یک پیوند سه‌گانه به سمت قطب مثبت حرکت می‌کنند.\n\nپ: با انحلال گاز آمونیاک در محلولی از سود، رسانایی الکتریکی این محلول آبی، همانند مقدار $pH$ آن افزایش خواهد یافت.\n\nت: ثابت یونش یک اسید خاص در دمای ثابت، در مقیاس $mol.L^{-1}$ گزارش شده و به مقدار آغازی آن اسید بستگی دارد.', 3, 3, 71, 270, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:40', 4, 'done'),
(5426, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ: نیمی از اتم‌های $H$ موجود در ساختار استیک اسید می‌توانند در قالب یون هیدرونیوم وارد محلول شوند.\n\nب: در واکنش میان اسیدهای چرب با محلول آبی سدیم هیدروکسید، نوعی رسوب به حالت جامد ایجاد می‌شود.\n\nپ: نسبت شمار اتم‌ها به شمار عناصر در واحد فرمولی جوش‌شیرین از مقدار این نسبت در اسید سرکه بزرگ‌تر است.\n\nت: در برخی از انواع ضداسیدهای معده‌ای، ماده نامحلول در آبی وجود دارد که هر مول از آن با $2$ مول $HCl$ واکنش می‌دهد.\n\nث: اغلب اسیدهایی که در زندگی روزانه با آن‌ها سروکار داریم، همانند اسیدهای چرب، در دسته اسیدهای ضعیف قرار دارند.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:44', 4, 'done'),
(5427, 'کدام‌یک از عبارت‌های داده شده درست است؟', 3, 3, 71, 272, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:49', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5428, ' چند مورد از مطالب زیر درست هستند؟\n\nآ: قدرت پاک‌کنندگی صابون در آب دریا کمتر از قدرت پاک‌کنندگی آن در آب چشمه است.\n\nب: در اوره، شمار اتم‌هایی که در تشکیل پیوند هیدروژنی شرکت می‌کنند، $1/5$ برابر اتیلن گلیکول است.\n\nپ: قدرت پاک‌کنندگی صابون روی پارچه با الیاف طبیعی نخی، بیشتر از پارچه با الیاف مصنوعی پلی‌استری است.\n\nت: در سال‌های اخیر، میزان افزایش امید به زندگی در نواحی برخوردار جهان، از نواحی کم‌برخوردار بیشتر بوده است.\n\nث: افزودن آنزیم به صابون، نسبت به افزایش دمای آب به اندازه $10^\\circ C$، تاثیر بیشتری بر قدرت پاک‌کنندگی آن دارد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:54', 4, 'done'),
(5429, ' کدام موارد از مطالب داده شده، در مورد ساختار زیر نادرست است؟ $(H=1, C=12, O=16, K=39 : g.mol^{-1})$\n\n\n\nآ: در ساختار این ترکیب آلی، مجموعا $45$ جفت الکترون پیوندی میان اتم‌های کربن وجود دارد.\n\nب: شمار پیوندهای $C-H$ در ساختار این ماده، به تقریب $7/7$ برابر شمار پیوندهای کربن-اکسیژن است.\n\nپ: از واکنش یک مول از این ماده با محلول پتاسیم هیدروکسید، $264$ گرم صابون مایع سیرنشده تولید می‌شود.\n\nت: یک لیتر محلول سدیم هیدروکسید با $pH = 13$، به تقریب با $25/9$ گرم از این ماده، به طور کامل واکنش می‌دهد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:03:59', 4, 'done'),
(5430, 'چند مورد از مطالب زیر، درست است؟\n\nآ: مخلوطی از چند ماده به حالت مایع که نور را در خود پخش می‌کند، قطعا یک مخلوط ناهمگن است.\n\nب: با ثابت قرار دادن یک نمونه از شیر، به مرور زمان مواد موجود در آن رسوب خواهند کرد.\n\nپ: ذرات موجود در یک نمونه از کلوئیدها، توده‌های مولکولی با اندازه‌های یکسان هستند.\n\nت: سرم فیزیولوژی، برخلاف شربت معده، پیش از مصرف نیاز به تکان‌دادن ندارد.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:06', 4, 'done'),
(5431, ' کدام یک از مطالب زیر درست است؟\n\nآ: در ساختار صابون‌ها، همانند پاک‌کننده‌های غیرصابونی، نسبت شمار آنیون به کاتیون برابر یک است.\n\nب: در ساختار آنیون صابون، $4$ جفت الکترون ناپیوندی وجود دارد و بخش ناقطبی این ماده، همواره بدون شاخه است.\n\nپ: در هر اسید چرب تشکیل‌دهنده چربی کوهان شتر، $38$ اتم هیدروژن وجود داشته و این ماده، ترکیبی سیرشده است.\n\nت: در واحد فرمولی همه صابون‌هایی با زنجیره کربنی سیرشده، شمار اتم‌های $H$ کمتر از دو برابر شمار اتم‌های کربن است.', 3, 3, 71, 268, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:10', 4, 'done'),
(5432, ' کدام موارد از مطالب زیر درست هستند؟\n\nآ: رسوب تشکیل‌شده بر دیواره کتری‌ها را با استفاده از مخلوط صابون و جوش‌شیرین پاک می‌کنند.\n\nب: افزودن یون فسفات به صابون و استفاده از پاک‌کننده غیرصابونی در سفر دریایی، یک مشکل مشابه را حل می‌کنند.\n\nپ: صابون کلردار و صابون گوگرددار، به ترتیب برای از بین بردن جوش‌های صورت و قارچ‌های پوستی استفاده می‌شود.\n\nت: برخی از فراورده‌های واکنش گرماده میان پودر لوله بازکن و مواد مسدودکننده لوله، خود خاصیت پاک‌کنندگی دارند.', 3, 3, 71, 268, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:17', 4, 'done'),
(5433, ' کدام یک از مطالب زیر درست است؟', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:23', 4, 'done'),
(5434, '27- چند مورد از مطالب زیر درست است؟\n\nآ: اگر $pH$ محلول اسید ضعیف $HA$ و اسید قوی $HB$ برابر باشد، مقدار رسانایی این دو محلول نیز به یک اندازه است.\n\nب: در غلظت مولی برابر، رسانایی الکتریکی محلول آبی یک نمک، به یقین کمتر از محلول یک اسید قوی نیست.\n\nپ: واکنش $HF(aq) + Cl^-(aq) \\rightleftharpoons HCl(aq) + F^-(aq)$ با غلظت برابر از هر ماده، به سمت راست پیش می‌رود.\n\nت: در محلول مولار دو عضو اول خانواده اسیدهای آلی، غلظت اسید یونیده نشده در محلول ساده‌ترین اسید، بیشتر است.', 3, 3, 71, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, NULL, NULL, 'free'),
(5435, ' کدام موارد از مطالب زیر، در مورد یک لیتر از محلول‌های دو اسید $HF$ و $HCN$ درست هستند؟\n\nآ: اگر $pH$ دو محلول برابر باشد، محلول $HF$ با مقدار بیشتری از فلز منیزیم واکنش می‌دهد.\n\nب: اگر غلظت دو اسید برابر باشد، درصد یونش در محلول $HCN$ در مقایسه با محلول $HF$ بیشتر است.\n\nپ: اگر غلظت دو اسید برابر باشد، در واکنش با فلز منیزیم، محلول $HF$ در مقایسه با محلول $HCN$ گرم‌تر خواهد شد.\n\nت: اگر $pH$ دو محلول برابر باشد، غلظت آنیون در محلول‌ها برابر و درصد یونش در محلول $HF$ بیشتر از محلول $HCN$ است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:32', 4, 'done'),
(5436, ' چند مورد از مطالب زیر درست است؟\n\nآ: در همه محلول‌های آبی، یون‌های هیدرونیوم و یون هیدروکسید وجود دارند.\n\nب: نیترواسید، برخلاف نیتریک اسید، یک اسید با معادله یونش برگشت‌پذیر است.\n\nپ: در یک نمونه سرکه، رابطه $[OH^-] < [H^+] = [\\text{یون استات}] < [\\text{استیک اسید}]$ برقرار است.\n\nت: اسیدهای مورد استفاده برای تولید پلی‌استرها، همانند سولفوریک اسید، دو هیدروژن اسیدی دارند.', 3, 3, 71, 270, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:35', 4, 'done'),
(5437, ' چند مورد از مطالب زیر درست است؟\n\nآ: در ساختار همه بازهای آرنیوس، به یقین اتم اکسیژن وجود دارد.\n\nب: همه اسیدهای آرنیوس، همانند همه بازهای آرنیوس، الکترولیت هستند.\n\nپ: همه اسیدهای آرنیوس به هنگام حل شدن در آب، غلظت یون هیدروژن را افزایش می‌دهند.\n\nت: بر اساس مدل آرنیوس، در شرایط یکسان هر چه یک باز یون $OH^-$ بیشتری تولید کند، قوی‌تر است.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:42', 4, 'done'),
(5438, ' کدام موارد از مطالب زیر درست هستند؟\n\nآ: با $8$ برابر شدن غلظت اسید ضعیف در آب، $pH$ محلول به تقریب $0/45$ واحد کاهش می‌یابد.\n\nب: با افزودن آب به محلول باز ضعیف، غلظت یون هیدرونیوم و مقدار ثابت یونش افزایش می‌یابد.\n\nپ: اگر به یک لیتر محلول حاوی باز قوی $10$ لیتر آب اضافه کنیم، $pH$ محلول یک واحد کاهش می‌یابد.\n\nت: اگر با اضافه کردن آب به محلول یک اسید ضعیف، $pH$ یک واحد افزایش یابد، درجه یونش $10$ برابر شده است.', 3, 3, 71, 272, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:46', 4, 'done'),
(5439, ' کدام یک از مطالب زیر نادرست است؟', 3, 3, 71, 273, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:51', 4, 'done'),
(5440, ' با توجه به شکل مقابل که نمایشی از ذرات اسید در دو محلول را نشان می‌دهد، کدام یک از مطالب زیر درست هستند؟ (هر ذره معادل $x$ مول بر لیتر است.)\n\n\n\nآ: مقدار $K_a$ برای محلول اسید قوی‌تر $6/25$ برابر محلول اسید ضعیف‌تر است.\n\nب: مقدار $pH$ محلول اسید قوی‌تر $0/4$ واحد کمتر از محلول اسید ضعیف‌تر است.\n\nپ: غلظت یون هیدروکسید در محلول اسید ضعیف‌تر، $4$ برابر محلول اسید قوی‌تر است.\n\nت: درجه یونش در محلول اسید قوی‌تر، $30$ درصد بیشتر از محلول اسید ضعیف‌تر است.', 3, 3, 71, 271, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:04:57', 4, 'done'),
(5441, ' چند مورد از مطالب زیر درست است؟\n\nآ: در باران اسیدی، همانند باران معمولی، مولکول یونش‌نیافته‌ای از اسیدها دیده نمی‌شود.\n\nب: در محلول آبی سدیم هیدروژن کربنات، غلظت یون هیدروکسید بیشتر از یون هیدرونیوم است.\n\nپ: روزانه دو تا سه لیتر شیره معده در بدن انسان تولید می‌شود که $pH$ آن از $pH$ معده در حالت استراحت بیشتر است.\n\nت: باز موجود در شیر منیزی، برخلاف باز موجود در محلول شیشه‌پاک‌کن، در آب به طور کامل یونش می‌یابد.', 3, 3, 71, 269, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-17 20:16:27', 1, '2026-10-12 22:05:02', 4, 'done'),
(5487, ' کدام گزینه به درستی بیان شده است؟\n\n۱) پاسخ به پرسش بنیادی «هستی چگونه پدید آمده است؟» در قلمرو علوم تجربی می‌گنجد.\n\n۲) همه دانشمندان بر این باورند که سرآغاز کیهان با انفجاری مهیب همراه بوده که طی آن انرژی عظیمی آزاد شده است.\n\n۳) دو فضاپیمای وویجر ۱ و ۲ مأموریت داشتند با گذر از کنار سیاره‌های گازی، شناسنامه فیزیکی و شیمیایی آن‌ها را تهیه و ارسال کنند.\n\n۴) پس از پدید آمدن ذرات زیراتمی، با گذشت زمان و افزایش دما، مجموعه‌های گازی به نام سحابی ایجاد شدند.', 1, 3, 65, 275, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-03-22 17:32:31', 5, 'done'),
(5488, '۲- کدام‌یک از گزینه‌های زیر درست است؟\n\n۱) در میان ایزوتوپ‌های هیدروژن، نسبت شمار ایزوتوپ‌های ساختگی به شمار ایزوتوپ‌های طبیعی ناپایدار آن برابر ۴ است.\n\n۲) یون تکنسیم با یون یدید اندازه مشابهی دارد، از این‌رو از تکنسیم ($^{۹۹}_{۴۳}Tc$) برای تصویربرداری غده تیروئید استفاده می‌شود.\n\n۳) $^{۲۳۵}_{۹۲}X$ یکی از ایزوتوپ‌های عنصری است که شناخته‌شده‌ترین فلز پرتوزاست و مقدار این ایزوتوپ در مخلوط طبیعی آن حدود $۰/۷\\%$ است.\n\n۴) جدول دوره‌ای عنصرها، از ۷ دوره و ۱۸ گروه تشکیل شده است که عنصرهای موجود در یک گروه خواص فیزیکی و شیمیایی یکسانی دارند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5489, '۳- چند مورد از مطالب زیر نادرست است؟\n\nالف) هیدروژن، ۵ ایزوتوپ ناپایدار دارد که همگی ساختگی هستند.\n\nب) کاتیون عنصری که در هسته خود ۳۱ ذره باردار دارد، باری مشابه کاتیون $^{۱۳}Al^{۳+}$ دارد.\n\nپ) اگر موج B مربوط به رنگ زرد باشد، موج A می‌تواند مربوط به رنگ سبز باشد.\n\n\n\nت) اگر اکسیژن دارای سه ایزوتوپ $^{۱۶}O$، $^{۱۷}O$ و $^{۱۸}O$ باشد، با این ایزوتوپ‌ها، می‌توان ۶ مولکول $O_۳$ با جرم مولی متفاوت تشکیل داد.\n\nث) تعداد خطوط رنگی طیف نشری خطی فراوان‌ترین عنصر سیاره مشتری، بیش‌تر از این تعداد در طیف نشری خطی دومین عنصر فراوان این سیاره است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5490, '۴- کدام گزینه صحیح است؟\n\n۱) عدد آووگادرو ($N_A$) تقریباً برابر با معکوس میانگین جرم اتمی هیدروژن در مقیاس گرم است.\n\n۲) جرم اتمی میانگین هیدروژن دقیقاً با سنجه‌ای که معادل $\\frac{۱}{۱۲}$ جرم اتم کربن - ۱۲ است، برابر می‌باشد.\n\n۳) یکای جرم اتمی، رایج‌ترین یکای اندازه‌گیری جرم در آزمایشگاه شناخته می‌شود.\n\n۴) در هر خانه از جدول تناوبی، نام عنصر به همراه نماد شیمیایی، عدد اتمی و عدد جرمی آن به چشم می‌خورد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5491, '۵- در یون فرضی $X^{۴+}$، شمار نوترون‌ها ۱/۵ برابر شمار الکترون‌ها و ۱/۳۸ برابر شمار پروتون‌ها است. در اتم آن، چند ذره زیراتمی باردار وجود دارد؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5492, '۶- چه تعداد از موارد زیر صحیح است؟\n\nالف) در جدول تناوبی، ۹ گروه چهار عضوی وجود دارد که همه آن‌ها مربوط به یک دسته هستند.\n\nب) در دسته f جدول دوره‌ای عنصرها ۲۸ عنصر وجود دارد.\n\nپ) در دوره‌های ۲ و ۳ جدول دوره‌ای، در مجموع ۸ عنصر وجود دارد که نماد شیمیایی آن‌ها دو حرفی است.\n\nت) نخستین عنصری که توسط بشر ساخته شده است در دسته d جدول دوره‌ای جای دارد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5493, '۷- جرم یک اتم از ایزوتوپی $۱/۳۲۸ \\times ۱۰^{-۲۲}$ گرم است، اگر تعداد نوترون‌های آن ۴۵ باشد نماد این ایزوتوپ ... است و جرم آن به تقریب ... برابر جرم ایزوتوپ $^{۱۲}C$ است. (جرم اتمی را معادل عدد جرمی در نظر بگیرید.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5494, '۸- چند مورد از گزینه‌های زیر در مورد ایزوتوپ‌های هیدروژن درست است؟\n\n● در تمام رادیوایزوتوپ‌های هیدروژن رابطه $\\frac{Z}{n} < \\frac{۲}{۳}$ برقرار است. (n تعداد نوترون و Z عدد اتمی است.)\n\n● در رادیوایزوتوپ‌ها، همواره با افزایش تعداد نوترون‌ها، نیمه‌عمر کاهش می‌یابد.\n\n● درصد فراوانی ایزوتوپ $^۱H$ در طبیعت برابر $۹۹/۹۸۵\\%$ است.\n\n● در ناپایدارترین ایزوتوپ هیدروژن، مجموع ذرات زیراتمی برابر ۸ واحد است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5495, '۹- جرم‌های برابری از گازهای گوگرد دی‌اکسید ($SO_۲$) و متان ($CH_۴$) را در اختیار داریم. نسبت تعداد اتم‌های موجود در گوگرد دی‌اکسید به تعداد اتم‌های موجود در متان کدام است؟ ($C=۱۲, H=۱, O=۱۶, S=۳۲ : g.mol^{-۱}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5496, '۱۰- چند مورد از عبارات زیر نادرست است؟\n\n● ۲۸ درصد از عناصر جدول تناوبی ساختگی هستند.\n\n● در ایزوتوپ‌های طبیعی منیزیم، با افزایش عدد جرمی، درصد فراوانی در طبیعت کاهش می‌یابد.\n\n● در سومین رادیوایزوتوپ هیدروژن از نظر پایداری، اختلاف تعداد ذرات زیراتمی درون هسته برابر با ۵ می‌باشد.\n\n● با افزایش گلوکز حاوی اتم پرتوزا (گلوکز نشان‌دار) در توده سرطانی، امکان تصویربرداری از توده سرطانی فراهم می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5497, '۱۱- کدام مطلب نادرست است؟ ($^{۱۶}_{۸}O, ^{۳۵}_{۱۷}Cl, ^{۲}_{۱}H, ^{۱۴}_{۷}N$)\n\n۱) تعداد الکترون‌های هر یون $ClO^-$ بیش از ۲/۵ برابر تعداد الکترون‌های هر یون $NH_۴^+$ است.\n\n۲) در عنصر $^{۷۹}M$، اختلاف نوترون‌ها و پروتون‌ها برابر ۱۱ است و این اتم در هسته خود ۳۴ پروتون دارد.\n\n۳) $۹/۰۳ \\times ۱۰^{۲۰}$ اتم آهن برابر با ۰/۰۱۵ مول آهن است.\n\n۴) پایداری هسته ایزوتوپی از هیدروژن که ۵ نوترون دارد، بیشتر از ایزوتوپی از آن با عدد جرمی ۴ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5498, '۱۲- اگر نیم‌مول اتم A و ۱ مول اتم E به همراه $۱۲/۰۴ \\times ۱۰^{۲۳}$ عدد اتم D درون ظرفی دربسته قرار گیرند و جرم کل اتم‌ها برابر ۸۵ گرم باشد و در مجموع ۴۲/۵ مول ذره زیراتمی باردار درون هسته‌ها موجود باشد، مقدار y چند است؟ ($^x_y A, ^{۲x}_y D, ^{۴x}_y E$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5499, '۱۳- جاهای خالی عبارات زیر با عبارت‌های موجود در کدام گزینه به درستی کامل می‌شود؟\n\nآ) هرچه طول موج پرتویی بیشتر باشد، زاویه انحراف آن پس از عبور از منشور ... است.\n\nب) رنگ شعله مس (II) نیترات با رنگ شعله مس (II) کلرید ... است.\n\nپ) پرتویی که طول موج ... دارد، انرژی ... با خود حمل می‌کند.\n\n۱) کمتر – متفاوت – کوتاه‌تر – بیشتری\n\n۲) بیشتر – یکسان – بلندتر – بیشتری\n\n۳) بیشتر – متفاوت – کوتاه‌تر – کمتری\n\n۴) کمتر – یکسان – بلندتر – کمتری', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5500, '۱۴- اتم‌های موجود در یک مکعب به ابعاد ۴ سانتی‌متر از فلز منگنز، به تقریب دارای چند مول الکترون ظرفیتی است؟ (جرم هر سانتی‌متر مکعب از فلز منگنز را برابر ۷/۵ گرم در نظر بگیرید. $^{۲۵}Mn = ۵۵ : g.mol^{-۱}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5501, '۱۵- کدام موارد از مطالب زیر، درست می‌باشند؟\n\nآ) انرژی نور نیلی از نور نارنجی کمتر است.\n\nب) به هنگام عبور نور خورشید از منشور و تجزیه آن، میزان انحراف نور آبی از نور زرد بیشتر است.\n\nپ) طول موج نور زرد از طول موج نور سبز، بلندتر است.\n\nت) در بین پرتوهای الکترومغناطیس، پرتو گاما بیشترین انرژی و ریزموج‌ها بیشترین طول موج را دارند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5502, '۱۶- چه تعداد از عبارت‌های زیر درست است؟\n\n● اغلب ایزوتوپ‌هایی که نسبت پروتون به نوترون آن‌ها کوچکتر یا مساوی $\\frac{۲}{۳}$ باشد، ناپایدار هستند.\n\n● رادیوایزوتوپ‌های هیدروژن، نیمه‌عمری کمتر از یک ثانیه دارند.\n\n● تعداد خطوط مرئی در طیف نشری خطی هر عنصر متفاوت از عنصر دیگری است.\n\n● طول موج پرتو منتشر شده از کنترل تلویزیون می‌تواند $۳۰۰nm$ باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5503, '۱۷- کدام گزینه به درستی بیان نشده است؟\n\n۱) ایزوتوپ‌های یک عنصر در خواص فیزیکی وابسته به جرم مانند چگالی با یکدیگر تفاوت دارند.\n\n۲) اغلب هسته‌هایی که نسبت عدد اتمی به عدد جرمی‌شان برابر یا کمتر از ۰/۴ است، پرتوزا و ناپایدارند.\n\n۳) میزان انحراف امواج مرئی هنگام عبور از منشور با طول موج‌شان رابطه عکس و با انرژی‌شان رابطه مستقیم دارد.\n\n۴) ریزموج‌ها طول موج بیشتری نسبت به امواج فروسرخ و رادیویی دارند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5504, '۱۸- چند عبارت نادرست بین عبارت‌های زیر وجود دارد؟ ($O=۱۶, S=۳۲ : g.mol^{-۱}$)\n\n● دانشمندان با دستگاهی به نام طیف‌سنج از پرتوهای گسیل شده از مواد، اطلاعات ارزشمندی درباره آن‌ها به دست می‌آورند.\n\n● جرم اتمی $^۷Li$ تقریباً ۷ گرم است.\n\n● $۹/۰۳ \\times ۱۰^{۲۲}$ مولکول $SO_۳$، شامل ۱۲ گرم از آن است.\n\n● پس از تزریق گلوکز نشان‌دار، تجمع آن فقط در توده سرطانی شکل می‌گیرد.', 1, 3, 65, 275, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5505, '۱۹- عنصر A دارای ۳ ایزوتوپ است. در ایزوتوپ سنگین آن با عدد جرمی ۴۴، اختلاف تعداد نوترون‌ها و پروتون‌های آن برابر ۴ است، ایزوتوپ متوسط ۲ نوترون بیشتر از تعداد پروتون‌هایش دارد و ایزوتوپ سبک آن که درصد فراوانی آن برابر ۶۰ است، تعداد پروتون و نوترون برابر دارد. به ازای هر ایزوتوپ متوسط چند ایزوتوپ سبک وجود دارد؟ (جرم اتمی میانگین A برابر $۴۱amu$ است.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5506, '۲۰- چه تعداد از موارد زیر درست است؟\n\nالف) نور خورشید گستره‌ای پیوسته از پرتوهای الکترومغناطیسی است که بیش‌ترین طول موج در آن مربوط به نور قرمز است.\n\nب) هرچه طول موج یک پرتو مرئی بیش‌تر باشد، در هنگام عبور از منشور میزان شکست آن کم‌تر است.\n\nپ) با افزایش عدد اتمی عناصر، تعداد خطوط طیف نشری خطی آن‌ها نیز افزایش می‌یابد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5507, '۲۱- کدام‌یک از عبارت‌های زیر درست است؟\n\nالف) انرژی الکترون‌ها در اتم با فاصله آن‌ها از هسته اتم رابطه عکس دارد.\n\nب) الکترون هنگام انتقال از لایه‌ای به لایه دیگر، انرژی را به‌صورت پیمانه‌ای جذب یا نشر می‌کند.\n\nپ) الکترون‌های برانگیخته در اتم، ناپایدارتر بوده و با آزاد کردن انرژی به حالت پایه و پایداری برمی‌گردند.\n\nت) حداکثر گنجایش الکترونی زیرلایه‌ها از رابطه $۴l+۲$ (l عدد کوانتومی فرعی) به‌دست می‌آید.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5508, '۲۲- کدام گزینه جای خالی را به درستی تکمیل می‌کند؟\n\n«مطابق اصل آفبا، ...........»\n\n۱) سه زیرلایه الکترونی با $n+l=۳$ وجود دارد.\n\n۲) اگر $n+l$ برای دو یا چند زیرلایه یکسان باشد، زیرلایه با n بزرگ‌تر، انرژی کم‌تری دارد.\n\n۳) هریک از اتم‌های کروم ($Z=۲۴$) و اسکاندیم ($Z=۲۱$) در بیرونی‌ترین زیرلایه خود تنها یک الکترون دارد.\n\n۴) پر شدن زیرلایه‌ها تنها به عدد کوانتومی اصلی (n) وابسته نیست.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5509, '۲۳- با توجه به شکل، کدام گزینه درست است؟\n\n۱) هر بخش پررنگ در این شکل، نشان‌دهنده مهم‌ترین بخش از یک لایه الکترونی است که الکترون‌های آن لایه، تمام وقت خود را در آن فاصله از هسته سپری می‌کنند.\n\n۲) این مدل برای توجیه و علت ایجاد طیف نشری خطی اتم هیدروژن توسط بور ارائه شد.\n\n۳) کوانتومی بودن دادوستد انرژی هنگام انتقال الکترون از یک لایه به لایه دیگر را می‌توان از این شکل استنباط کرد.\n\n۴) مطابق این مدل، الکترون‌ها در اتم برای تبادل انرژی هنگام انتقال بین لایه‌ها، با محدودیت مشابهی همانند بالا رفتن از سطح شیب‌دار و سربالایی روبه‌رو هستند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5510, '۲۴- اگر عنصر X متعلق به دوره چهارم جدول تناوبی باشد و شمار الکترون‌های بیرونی‌ترین زیرلایه آن، نصف شمار الکترون‌های نخستین زیرلایه اشغال‌شده آن باشد، چند مورد از مطالب زیر می‌تواند درباره این عنصر درست باشد؟\n\n● شمار الکترون‌های ظرفیتی آن می‌تواند برابر ۵ باشد.\n\n● شمار الکترون‌های با $l=۱$ و $n=۲$، دو برابر شمار الکترون‌های با $n=۴$ است.\n\n● این عنصر می‌تواند با از دست دادن سه الکترون به آرایش هشت‌تایی گاز نجیب برسد.\n\n● خواص شیمیایی این عنصر با خواص شیمیایی عنصری با عدد اتمی ۶ مشابه است.\n\n● نماد شیمیایی این عنصر می‌تواند به‌صورت تک‌حرفی باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5511, '۲۵- کدام گزینه نادرست است؟\n\n۱) شمار الکترون‌های ظرفیتی $^۳۵Br$ با شمار زیرلایه‌های پر شده آن برابر است.\n\n۲) قاعده آفبا آرایش الکترونی اتم همه عنصرها را به درستی پیش‌بینی می‌کند و هر زیرلایه‌ای که $n+l$ کوچکتر داشته باشد، زودتر پر می‌شود.\n\n۳) ترتیب پر شدن زیرلایه‌های $۴f$، $۶p$، $۵d$ و $۶s$ به‌صورت $۶s \\rightarrow ۴f \\rightarrow ۵d \\rightarrow ۶p$ می‌باشد.\n\n۴) شمار الکترون‌ها با $l=۰$ در اتم $^۱۴X$، ۰/۷۵ برابر شمار الکترون‌های با $l=۱$ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5512, '۲۶- چند مورد از عبارت‌های زیر جمله داده شده را به درستی تکمیل می‌کند؟\n\n«در دوره چهارم جدول تناوبی، ...........»\n\n● در آرایش الکترونی اتم پنج عنصر، زیرلایه نیمه‌پر وجود دارد.\n\n● دوازده عنصر با تعداد الکترون ظرفیتی متفاوت وجود دارد.\n\n● از چپ به راست، الکترون‌های ظرفیتی عنصرها همواره افزایش می‌یابد.\n\n● تنها دو عنصر با نماد تک‌حرفی وجود دارد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5513, '۲۷- عنصر A با عنصر $^۵۰B$ هم‌گروه و با اولین عنصری که زیرلایه $۳d$ نیمه‌پر دارد هم‌دوره است. اگر در اتم A شمار الکترون‌های زیرلایه‌هایی با $l=۱$ را با x و شمار الکترون‌های زیرلایه‌هایی را که مجموع عدد کوانتومی اصلی و فرعی آن‌ها حداقل برابر ۵ است را با y نشان دهیم، کدام‌یک از روابط زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5514, '۲۸- آرایش الکترونی بیرونی‌ترین زیرلایه یون‌های تک‌اتمی $A^{۳-}$ و $B^{۳+}$ و $C^{۲+}$ به ترتیب به $۴p^۶$ و $۳p^۶$ و $۳d^۴$ ختم می‌شود، کدام گزینه نادرست است؟ (نمادها فرضی هستند.)\n\n۱) عنصر A دارای ۱۵ الکترون با $l=۱$ است.\n\n۲) مجموع $n+l$ الکترون‌های ظرفیتی اتم عنصر C برابر با ۲۹ است.\n\n۳) بیرونی‌ترین زیرلایه در عنصر B، دارای عدد کوانتومی $n=۳$ و $l=۲$ می‌باشد.\n\n۴) در اتم C، نسبت شمار الکترون‌ها با $l=۰$ به شمار الکترون‌ها با $l=۲$ برابر ۱/۴ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5515, '۲۹- همه‌ گزینه‌های زیر نادرست‌اند، به‌جز ...........\n\n۱) هر ترکیب یونی از نظر بار الکتریکی خنثی است، زیرا شمار کاتیون‌ها و آنیون‌های آن با هم برابر است.\n\n۲) اتم فلزها در شرایط مناسب با تشکیل پیوندهای اشتراکی می‌توانند مولکول‌های دو یا چند اتمی بسازند.\n\n۳) عدد جرمی ایزوتوپ‌های یک عنصر متفاوت است، بنابراین آرایش الکترونی همه‌ ایزوتوپ‌های یک عنصر متفاوت خواهد بود.\n\n۴) عنصر $^{۲۷}X$ به عناصر دسته d جدول تعلق دارد و در دوره چهارم و گروه ۹ جدول قرار گرفته است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5516, '۳۰- اتم عنصری در آرایش الکترونی خود دارای ۱۶ الکترون با $l=۱$ است، چه تعداد از موارد زیر در رابطه با این عنصر درست است؟\n\n● آرایش الکترون-نقطه‌ای آن مشابه آرایش الکترون-نقطه‌ای یون $S^{۲-}$ است.\n\n● اتم این عنصر در شرایط مناسب می‌تواند با به اشتراک گذاشتن الکترون به آرایش گاز نجیب برسد.\n\n● این عنصر در خانه ۳۴ جدول دوره‌ای جای دارد.\n\n● در آرایش یون پایدار آن، هشت الکترون با $n=۴$ وجود دارد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5517, '۳۱- درباره دو عنصر $X_۷$ و $Y_{۲۰}$ کدام مطلب نادرست است؟\n\n۱) شمار الکترون‌های لایه ظرفیت X و Y، به ترتیب برابر ۳ و ۲ است.\n\n۲) فرمول شیمیایی ترکیب یونی حاصل از واکنش دو عنصر، $Y_۳X_۲$ است.\n\n۳) هنگام تشکیل پیوند یونی بین اتم‌های X و Y به ازای تولید ۱ مول، شش مول الکترون دادوستد می‌شود.\n\n۴) X و Y هنگام تشکیل پیوند، به ترتیب یون‌های $X^{۳-}$ و $Y^{۲+}$ را تشکیل می‌دهند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5518, '۳۲- نسبت شمار کاتیون‌ها به شمار آنیون‌ها، در فرمول شیمیایی ........... از بقیه بزرگ‌تر و این نسبت در ........... از بقیه کوچک‌تر است. (گزینه‌ها را به ترتیب از راست به چپ بخوانید.)\n\na) سدیم فسفید\n\nb) باریم سولفید\n\nc) پتاسیم اکسید\n\nd) کلسیم برمید', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5519, '۳۳- نمودار زیر مجموع اندازه بار کاتیون و آنیون ترکیب‌های یونی حاصل از عنصرهای اصلی چهار دوره اول جدول تناوبی را نشان می‌دهد. چند مورد از عبارت‌های زیر درست است؟\n\n● در ترکیب AE کاتیون و آنیون قطعاً به آرایش گاز نجیب می‌رسند.\n\n● ترکیب XY می‌تواند کلسیم فسفید باشد.\n\n● اگر کاتیون و آنیون DZ هم‌الکترون باشند، بین عناصر D و Z در جدول تناوبی، ۵ عنصر وجود دارد.\n\n● در تمام این ترکیب‌های یونی، مجموع بار الکتریکی کاتیون‌ها با مجموع قدرمطلق بار الکتریکی آنیون‌ها برابر است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5520, '۳۴- چند مورد از مطالب زیر درست است؟\n\n● در آرایش الکترونی اتم $^{۲۹}Cu$، شمار الکترون‌های با $n+l=۴$، ۰/۸ برابر شمار الکترون‌های با $n+l=۵$ است.\n\n● مجموع شماره دوره و گروه نخستین عنصری که از قاعده آفبا پیروی نمی‌کند، برابر با شماره گروه عنصر $^{۲۸}Ni$ است.\n\n● شمار یون‌های تک‌اتمی پایدار در عنصرهای دوره سوم، ۱/۵ برابر این شمار در دوره دوم است.\n\n● عدد اتمی عنصری از دوره چهارم با آرایش الکترون-نقطه‌ای $\\cdot\\dot{X}\\cdot$، ۳ برابر عدد اتمی عنصری از دوره سوم با آرایش الکترون-نقطه‌ای $\\cdot\\dot{X}\\cdot$ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5521, '۳۵- کدام ردیف‌های جدول زیر درست‌اند؟\n\n| ردیف | سؤال | پاسخ |\n\n| :--- | :--- | :--- |\n\n| آ | عدد اتمی نخستین عنصری که در لایه سوم خود ۱۳ الکترون دارد، چند است؟ | ۲۵ |\n\n| ب | نسبت تعداد الکترون‌های با $l = ۰$ به تعداد الکترون‌های با $l = ۲$ در عنصری که در خانه ۲۹ جدول تناوبی جای دارد، چند است؟ | ۰/۷ |\n\n| پ | در آرایش الکترونی اتم چند عنصر از دوره چهارم جدول تناوبی، ۸ الکترون با $l = ۰$ وجود دارد؟ | ۱۵ |\n\n| ت | در کاتیون $^{۳۱}M^{۳+}$، تعداد الکترون‌های با $l = ۲$ چند برابر تعداد الکترون‌های با عددهای کوانتومی $l = ۰$ و $n = ۳$ است؟ | ۵ |', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5522, '۳۶- کدام موارد از مطالب زیر نادرست است؟\n\nآ) در ایزوتوپ‌های منیزیم، همواره عدد جرمی بزرگ‌تر یا مساوی با دو برابر عدد اتمی است.\n\nب) با افزایش عدد اتمی گازهای نجیب، درصد فراوانی آن‌ها در سیاره مشتری کاهش می‌یابد.\n\nپ) نیم‌عمر هریک از رادیوایزوتوپ‌های هیدروژن کمتر از یک ثانیه است.\n\nت) از $^{۲۳۵}_{۹۲}U$ به‌عنوان سوخت در راکتورهای اتمی استفاده می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5523, '۳۷- کدام گزینه نادرست است؟ ($Fe=۵۶, Cu=۶۴ : g.mol^{-۱}$)\n\n۱) شمار اتم‌ها در ۸ گرم مس با شمار اتم‌ها در ۷ گرم آهن یکسان است.\n\n۲) اگر از هر ۲۰ اتم عنصر $X$، ۱۶ اتم $^{۱۱}X$ و بقیه $^{۱۰}X$ باشند، جرم اتمی میانگین آن برابر $۱۰/۸ amu$ خواهد بود.\n\n۳) طول موج پرتوهای فروسرخ از طول موج پرتوهای گاما بزرگ‌تر است.\n\n۴) به‌طور میانگین جرم هر اتم هیدروژن برابر $۱/۶۶ \\times ۱۰^{-۲۴}$ گرم و سبک‌ترین ایزوتوپ آن فاقد نوترون است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5524, '۳۸- چند مورد از گونه‌های زیر جزو ایزوتوپ‌های $^{۳۲}Ge$ هستند؟ (تمام گونه‌ها در حالت خنثی هستند.)\n\n● گونه A که عدد جرمی آن برابر ۷۶ و اختلاف شمار الکترون‌ها و نوترون‌ها در آن برابر ۱۲ است.\n\n● گونه B که مجموع شمار ذرات داخل هسته آن برابر ۷۵ و اختلاف شمار ذرات زیراتمی باردار و ذرات زیراتمی بدون بار آن برابر ۲۴ است.\n\n● گونه C که در آرایش الکترونی اتم آن ۱۰ الکترون با $l=۱$ و ۴ الکترون ظرفیتی و در هسته آن ۴۰ نوترون وجود دارد.\n\n● گونه D که هم‌دوره فراوان‌ترین عنصر موجود در کره زمین و هم‌گروه با کربن است و شمار نوترون‌های آن ۱۰ عدد بیش‌تر از شمار پروتون‌ها است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5525, '۳۹- اگر تفاوت شمار الکترون‌ها و نوترون‌ها در یون $A^{۲+}$، ۷ برابر تعداد نوترون‌های سنگین‌ترین ایزوتوپ طبیعی هیدروژن باشد و همچنین مجموع تعداد پروتون‌ها و نوترون‌های عنصر A، ۲۴ برابر تعداد نوترون‌های ایزوتوپ ساختگی هیدروژن با بیش‌ترین نیم‌عمر باشد، عدد اتمی عنصر A کدام است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5526, '۴۰- یون $X^{۲+}$ دارای ۱۰ الکترون است. اگر عنصر X با جرم اتمی میانگین $۲۴/۳ amu$، سه ایزوتوپ طبیعی داشته باشد که یکی از آن‌ها دارای ۱۲ نوترون و دیگری دارای ۱۳ نوترون باشد، تعداد نوترون‌های ایزوتوپ سوم کدام است؟ (شکل زیر نمایش بخشی از یک نمونه طبیعی عنصر X است.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5527, '۴۱- چند مورد از مطالب زیر درست است؟\n\n● هر زیرلایه با اعداد کوانتومی n و l مشخص می‌شود.\n\n● ترتیب پر شدن زیرلایه‌ها، تنها به عدد کوانتومی اصلی وابسته است.\n\n● از رابطه $a = ۴l + ۲$، گنجایش الکترونی زیرلایه‌ها (a) را می‌توان معین کرد.\n\n● در اتم $^{۲۹}Cu$، نسبت شمار الکترون‌های دارای $l = ۲$ به $l = ۱$، برابر ۰/۷ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5528, '۴۲- کدام عبارت نادرست است؟\n\n۱) پاسخ سؤالاتی مانند «چرا آتشفشان رخ می‌دهد» برخلاف پاسخ «هستی چگونه پدید آمده است؟» در قلمرو علم تجربی می‌گنجد.\n\n۲) آخرین تصویری که وویجر ۲ پیش از خروج از سامانه خورشیدی از کره زمین گرفته است، از فاصله حدود ۷ میلیارد کیلومتری بوده است.\n\n۳) فراوان‌ترین عنصر سیاره مشتری برخلاف فراوان‌ترین عنصر سیاره زمین یک نافلز است.\n\n۴) درون ستاره‌ها در دماهای بسیار بالا، عناصر سبک‌تر به عناصر سنگین‌تر تبدیل می‌شوند و انرژی بسیار زیادی آزاد می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5529, '۴۳- کدام موارد از مطالب زیر درست هستند؟\n\nآ) عناصر مشترکی که در سیاره مشتری و زمین دیده می‌شوند توزیع همگون عناصر در جهان هستی را نشان می‌دهد.\n\nب) سحابی‌ها مجموعه‌های گازی‌شکل هستند که بعدها سبب تشکیل ستاره‌ها و کهکشان‌ها شدند.\n\nپ) گازهای هیدروژن و هلیم با گذشت زمان و افزایش دما، مجموعه‌هایی به نام سحابی را ایجاد کردند.\n\nت) درون ستاره‌ها، در دماهای بالا واکنش‌های هسته‌ای رخ می‌دهد و عناصر سنگین از عناصر سبک‌تر ایجاد می‌شوند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5530, '۴۴- همۀ عبارت‌های زیر درست‌اند؛ به‌جز ...........\n\n۱) ایزوتوپ‌های یک عنصر همگی خواص فیزیکی یکسانی دارند و در جدول دوره‌ای عنصرها تنها یک مکان را اشغال می‌کنند.\n\n۲) ایزوتوپی از لیتیم که نسبت شمار پروتون به نوترون آن برابر ۰/۷۵ است درصد فراوانی بیشتری دارد.\n\n۳) در بین ایزوتوپ‌های طبیعی هیدروژن، تنها یک رادیوایزوتوپ وجود دارد.\n\n۴) ایزوتوپ‌های ناپایدار اغلب بر اثر تلاشی افزون بر ذره‌های پرانرژی، مقدار زیادی انرژی نیز آزاد می‌کنند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5531, '۴۵- چه تعداد از مطالب زیر نادرست است؟\n\n● تکنسیم شناخته‌شده‌ترین فلز پرتوزایی است که بسته به نیاز درون مولد هسته‌ای تولید و بلافاصله مصرف می‌شود.\n\n● ایزوتوپی از اورانیوم که فراوانی آن در مخلوط طبیعی کمتر از ۰/۷٪ است به عنوان سوخت در راکتورهای اتمی استفاده می‌شود.\n\n● رادیوایزوتوپ‌ها اگرچه خطرناک هستند اما دانشمندان با پیشرفت دانش و فناوری، از آن‌ها در کشاورزی و پزشکی استفاده می‌کنند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5532, '۴۶- عبارت کدام گزینه درست است؟\n\n۱) اعضای بدن با عدم جذب گلوکز نشان‌دار و با جذب گلوکز معمولی، نشان می‌دهند که دارای یاخته‌هایی با رشد غیرعادی هستند.\n\n۲) نیم‌عمر، مدت زمانی است که نصف ماده اولیه تجزیه می‌شود و با میزان پایداری ایزوتوپ رابطه عکس دارد.\n\n۳) همه تکنسیم موجود در جهان باید به‌طور مصنوعی ساخته شود و زمان ماندگاری آن زیاد است.\n\n۴) منظور از غنی‌سازی ایزوتوپی افزایش درصد ایزوتوپ مورد نظر در مخلوط عنصر مورد نظر است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5533, '۴۷- چند مورد از عبارت‌های زیر درست هستند؟\n\n● اگر عنصر فرضی $A^{۳-}$ دارای ۳۴ الکترون بوده و اختلاف شمار نوترون‌ها و پروتون‌ها در آن برابر ۲ باشد، می‌تواند با $^{۶۴}_{۳۱}P$ ایزوتوپ باشد.\n\n● $^{۲۶}_{۱۲}Mg$ همانند $^{۲۵}_{۱۲}Mg$ با سرعت برابری با هیدروکلریک اسید واکنش می‌دهد ولی فراوانی $^{۲۵}_{۱۲}Mg$ کمتر است.\n\n● مقایسه نیم‌عمر رادیوایزوتوپ‌های هیدروژن به‌صورت $^۷H > ^۶H > ^۴H > ^۵H > ^۳H$ است.\n\n● رادیوایزوتوپ طبیعی هیدروژن و پایدارترین ایزوتوپ منیزیم، ۱۰ نوترون اختلاف دارند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5534, '۴۸- تعداد الکترون‌های دو ذره باردار $X^+$ و $Y^-$ با یکدیگر برابر است و عدد جرمی X به اندازه ۴ واحد بیشتر از Y است. اختلاف شمار نوترون‌ها و شمار پروتون‌های آن‌ها به ترتیب از راست به چپ کدام است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5535, '۴۹- کدام گزینه نادرست است؟\n\n۱) برای تعیین جرم اتم‌ها از مقیاس جرم نسبی استفاده می‌شود.\n\n۲) با تعریف $amu$ جرم اتمی دیگر عناصر و ذرات زیراتمی اندازه‌گیری می‌شود.\n\n۳) $\\frac{۱}{۱۲}$ جرم اتمی میانگین ایزوتوپ‌های کربن به‌عنوان یکای جرم اتمی در نظر گرفته شده و با $amu$ نشان داده می‌شود.\n\n۴) جرم اتمی هیدروژن برابر $۱/۰۰۸ amu$ می‌باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5536, '۵۰- چه تعداد از عبارات بیان شده، جمله زیر را به نادرستی تکمیل می‌کنند؟\n\n« ........... برخلاف ........... »\n\n● در رادیوایزوتوپ‌های هیدروژن - نخستین عنصر ساخت بشر، نسبت شمار نوترون‌ها به پروتون‌ها بیش از ۱/۵ می‌باشد.\n\n● طلای تولید شده توسط انسان - طلای استخراج شده از طبیعت، دارای خواص فیزیکی و شیمیایی متفاوتی می‌باشد.\n\n● گلوکز نشان‌دار - گلوکز معمولی، در محل یاخته‌هایی با رشد سریع و غیرعادی بیش‌تر جذب می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5537, '۵۱- کدام عبارت درست است؟\n\n۱) هر ستون از جدول تناوبی، شامل عنصرهایی با خواص فیزیکی و شیمیایی مشابه است که گروه نام دارد.\n\n۲) تفاوت شمار عنصرهای دوره ششم و دوره سوم جدول تناوبی، سه برابر شمار عنصرهای دوره دوم جدول است.\n\n۳) در دوره دوم جدول تناوبی، چهار عنصر دارای نماد شیمیایی دو حرفی هستند.\n\n۴) با پیمایش هر گروه از بالا به پایین، خواص عنصرها به‌طور مشابه تکرار می‌شود، از این رو، جدول تناوبی عنصرها نامیده می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5538, '۵۲- با توجه به شکل مقابل که به خانه عنصر اکسیژن در جدول دوره‌ای تعلق دارد، کدام موارد زیر درست هستند؟\n\nآ) x عددی است که می‌تواند برای برخی عناصر اعشاری هم باشد.\n\nب) A نماد شیمیایی را نشان می‌دهد که یک یا دو حرفی است.\n\nپ) y عددی است که مانند x برای همه عناصر جدول همواره عدد غیر اعشاری است.\n\nت) در بعضی عناصر عدد x می‌تواند از عدد y بزرگ‌تر باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5539, '۵۳- کدام گزینه درست است؟\n\n۱) خواص شیمیایی عنصرهایی که در یک دوره از جدول تناوبی جای دارند، مشابه است.\n\n۲) شیمی‌دان‌ها ۱۱۸ عنصر شناخته شده را براساس معیارهای مختلفی در جدولی با چیدمان ویژه کنار هم قرار داده‌اند.\n\n۳) اتم عنصر $_{۳۱}Ga$ می‌تواند به کاتیونی مشابه $_{۱۳}Al^{۳+}$ در ترکیب‌ها تبدیل شود.\n\n۴) هر خانه از جدول دوره‌ای به یک عنصر معین تعلق دارد و حاوی اطلاعات شیمیایی آن عنصر مانند عدد اتمی، جرم اتمی میانگین، نماد شیمیایی، شمار ذرات زیراتمی و نام عنصر می‌باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5540, '۵۴- با استفاده از ایزوتوپ‌های پایدار هیدروژن و ایزوتوپ‌های کربن ($^{۱۲}C, ^{۱۳}C$)، به ترتیب چند نوع مولکول اتین با فرمول مولکولی $C_۲H_۲$ می‌توان ساخت و چند مولکول اتین با جرم مولی متفاوت می‌توان نوشت؟ (عدد جرمی برابر با جرم اتمی فرض شود.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5541, '۵۵- با توجه به جدول زیر، جرم مولکولی میانگین ترکیب $A_۳B_۲$ چند $amu$ است؟ (عدد جرمی برابر با جرم اتمی فرض شود.)\n\n| ایزوتوپ | $^{۴۰}A$ | $^{۴۲}A$ | $^{۴۴}A$ | $^{۶۵}B$ | $^{۶۷}B$ |\n\n| :--- | :--- | :--- | :--- | :--- | :--- |\n\n| درصد فراوانی | ۲۵ | ۴۰ | ۳۵ | ۶۴ | ۳۶ |', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5542, '۵۶- سه ترازوی A و B و C به ترتیب اعداد ۱ و ۲ و ۳ را برحسب $amu$ نشان می‌دهند، چه تعداد از عبارت‌های زیر می‌تواند درست باشد؟\n\nالف) ترازوی A جرم هر کدام از ذرات زیراتمی درون هسته را به‌طور تقریبی نشان می‌دهد.\n\nب) ترازوی B مجموع جرم ذرات دارای بار موجود در هسته هلیم را به‌طور تقریبی نشان می‌دهد.\n\nپ) ترازوی C جرم تقریبی سومین عنصر جدول دوره‌ای را نشان می‌دهد.\n\nت) ترازوی C جرم تقریبی سنگین‌ترین ایزوتوپ طبیعی هیدروژن را نشان می‌دهد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5543, '۵۷- اگر شمار کل الکترون‌ها در ۹/۶ گرم یون $SO_۴^{۲-}$، نصف شمار کل اتم‌ها در ۱۵۲ گرم گاز $N_۲O_x$ باشد، مقدار x کدام است؟ ($N=۱۴, O=۱۶, S=۳۲ : g.mol^{-۱}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5544, '۵۸- چند مورد از موارد زیر درست است؟\n\n● ایزوتوپی از کلر که دارای ۱۸ نوترون است، نسبت به ایزوتوپ دیگر فراوان‌تر است.\n\n● دقت باسکول‌های تنی تا یک‌صدم تن و دقت ترازوی زرگری تا یک‌دهم گرم است.\n\n● لیتیم دارای دو ایزوتوپ طبیعی $^۶Li$ و $^۷Li$ است.\n\n● در مقیاس $amu$، جرم پروتون و نوترون تقریباً برابر $۱ amu$ و جرم الکترون در حدود $۰/۰۰۰۵ amu$ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5545, '۵۹- مخلوطی از هگزان ($C_۶H_{۱۴}$) و استون ($C_۳H_۶O$) به جرم ۱۷/۳ گرم در اختیار است. اگر تعداد اتم‌های اکسیژن در این مخلوط برابر $۹/۰۳ \\times ۱۰^{۲۲}$ باشد، تعداد اتم‌های کربن در این مخلوط برابر چند مول است؟ ($C=۱۲, O=۱۶, H=۱ : g.mol^{-۱}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5546, '۶۰- نمونه‌ای از عنصر فرضی X به شکل مقابل در اختیار داریم. اگر در طی فرآیندی n عدد از ایزوتوپ‌های سبک‌تر را از این نمونه خارج کنیم، جرم اتمی میانگین این عنصر به اندازه $۰/۲۵ amu$ تغییر می‌کند. جرم اتمی میانگین عنصر X در نمونه اولیه و مقدار n به ترتیب از راست به چپ در کدام گزینه آمده است؟ (جرم اتمی برابر عدد جرمی فرض شود.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5547, '61- شمار اتم‌های اکسیژن موجود در یک نمونه گاز گوگرد تری‌اکسید ($SO_3$) که در آن $0/2$ مول اتم گوگرد وجود دارد، با مجموع شمار اتم‌های نیتروژن موجود در $3/01 \\times 10^{22}$ مولکول گاز $N_2O_5$ و شمار اتم‌های هیدروژن موجود در ............... گرم اتانوئیک اسید ($CH_3COOH$) برابر است. ($S=32, O=16, N=14, C=12, H=1: g.mol^{-1}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5548, '62- همۀ عبارت‌های زیر درست‌اند، به‌جز ...............', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5549, '63- عبارت کدام گزینه درست است؟ ($Cu=64, Al=27, H=1: g.mol^{-1}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5550, '64- عنصر $M$ در حالت آزاد به‌صورت مولکول‌های دو اتمی بوده و جرم $3/01 \\times 10^{18}$ مولکول آن برابر $0/0805$ گرم است. اگر عنصر $M$ دارای دو ایزوتوپ $^{80}M$ و $^{82}M$ باشد، درصد فراوانی ایزوتوپ سبک‌تر چند برابر درصد فراوانی ایزوتوپ سنگین است؟ (عدد جرمی را هم‌ارز جرم اتمی در نظر بگیرید.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, NULL, NULL, 'free'),
(5551, '65- چند مورد از عبارت‌های زیر درست است؟ (نمادهای A و B فرضی هستند.)\n\n● برای رسم آرایش الکترونی فشردۀ اتم $_{56}B$ از گاز نجیب $_{36}Kr$ استفاده می‌شود.\n\n● اتم $_{35}A$ در شرایط مناسب به یون پایدار $A^+$ تبدیل می‌شود.\n\n● فرمول شیمیایی ترکیب یونی حاصل از واکنش اتم $_{35}A$ با اتم $_{56}B$ به‌صورت $AB_2$ است.\n\n● نسبت تعداد الکترون‌های با $n=3$ به تعداد الکترون‌های با $n=2$ در اتم $_{35}A$، برابر $2/25$ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-03 23:06:16', 3, 'free'),
(5552, '66- شکل زیر مربوط به چگونگی تشکیل یک ترکیب یونی است. با توجه به آن کدام مطلب نادرست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-03 23:07:56', 3, 'free'),
(5553, '67- کدام گزینه نادرست است؟', 1, 3, 65, 275, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-03 23:10:09', 3, 'free'),
(5554, '68- کدام گزینه درست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:13:45', 3, 'free'),
(5555, '69- عنصر فرضی A دارای ۲ ایزوتوپ با جرم‌های $56/8 amu$ و $58/8 amu$ است. اگر درصد فراوانی ایزوتوپ سنگین‌تر از دو برابر درصد فراوانی ایزوتوپ سبک‌تر به میزان %۲۰ کمتر باشد، در ۷ گرم از نمونۀ خالص از ترکیب یونی $A_2Se_3$ به‌تقریب چند یون وجود دارد؟ ($Se = 79 g.mol^{-1}$)', 1, 3, 65, 275, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:14:08', 3, 'free'),
(5556, '70- در گونۀ $^{31}X^q$، اختلاف تعداد نوترون‌ها و الکترون‌ها و مجموع تعداد ذرات زیراتمی به ترتیب برابر با 2 و 49 است. عنصر X در واکنش با عنصر $_{17}Y$ با رعایت قاعدۀ هشت‌تایی، طی تشکیل پیوند ...............، ترکیبی با فرمول شیمیایی ............... ایجاد می‌کند.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:14:42', 3, 'free'),
(5557, '71- اگر عنصر X در گروه 16، با عنصری که آرایش بیرونی‌ترین زیرلایۀ اتم آن $3p^5$ است هم‌دوره باشد، کدام موارد زیر دربارۀ آن درست است؟ (کامل‌ترین گزینه را انتخاب کنید.)\n\nآ) بیرونی‌ترین لایۀ اتم آن دارای 4 الکترون است.\n\nب) در ساختار لوویس ترکیب آن با هیدروژن دو جفت الکترون ناپیوندی وجود دارد.\n\nپ) فرمول شیمیایی ترکیب آن با $_{13}Al$ به‌صورت $Al_3X_2$ است.\n\nت) نسبت تعداد الکترون‌های با $l=0$ به تعداد الکترون‌های با $l=1$ در آرایش الکترونی اتم آن برابر $0/6$ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:15:10', 3, 'free'),
(5558, '72- کدام‌یک از عبارت‌های زیر درست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:15:30', 3, 'free'),
(5559, '73- چند مورد از عبارت‌های زیر نادرست است؟\n\nآ) اگر ترکیب مس (II) سولفات را روی شعله قرار دهیم رنگ شعله سبز می‌شود.\n\nب) طیف نشری خطی لیتیوم دارای خطوط رنگی بیشتری نسبت به هلیم (He) در ناحیۀ مرئی است.\n\nپ) انرژی برخلاف ماده در نگاه ماکروسکوپی، پیوسته اما در نگاه میکروسکوپی گسسته یا کوانتومی هستند.\n\nت) مدل اتمی بور عمر زیادی داشت و گام بسیار مهمی برای بهبود نگرش دانشمندان نسبت به ساختار اتم برداشت.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:15:45', 3, 'free'),
(5560, '74- همۀ موارد زیر درست می‌باشند، به‌جز:', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:16:04', 3, 'free'),
(5561, '۷۵- کدام عبارت درست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:16:21', 3, 'free'),
(5562, '۷۶- تعداد الکترون‌های کاتیون در ترکیب $M(OH)_{3}$ با تعداد الکترون‌های عنصر A از دورۀ چهارم و گروه ۵ یکسان است. چند مورد از عبارت‌های زیر درست است؟\n\nآ) عدد اتمی عنصر A برابر ۲۳ است.\n\nب) در اتم A، ۱۷ الکترون با عدد کوانتومی $l \\geq 1$ وجود دارد.\n\nپ) عدد اتمی عنصر M برابر ۲۶ و فرمول یکی از اکسیدهای آن به‌صورت $M_{2}O_{3}$ است.\n\nت) آرایش الکترونی کاتیون در $A_{2}O_{3}$ به‌صورت $[Ar]3d^{2}$ است.\n\nث) اختلاف تعداد نوترون‌ها در $^{51}A$ و $^{56}M$ برابر ۵ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:20', 1, '2026-09-12 12:16:39', 3, 'free'),
(5563, '۷۷- کدام موارد از عبارت‌های زیر نادرست هستند؟ (کامل‌ترین گزینه را انتخاب کنید.)\n\nآ) در عناصر دورۀ سوم جدول دوره‌ای، زیرلایه‌های $3s$، $3p$ و $3d$ از الکترون پر می‌شوند.\n\nب) انرژی زیرلایۀ $4f$ از $5d$ کمتر است.\n\nپ) در دورۀ چهارم جدول دوره‌ای، چهار عنصر وجود دارد که آخرین زیرلایۀ آن‌ها نیمه‌پر است.\n\nت) عناصر دستۀ $s$، ۱۳ عنصر از جدول دوره‌ای را شامل می‌شوند.\n\nث) الکترون‌های ظرفیتی به الکترون‌های موجود در زیر لایه(هایی) با بزرگترین ضریب $(n)$ گفته می‌شود.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:17:22', 3, 'free'),
(5564, '۷۸- با توجه به جدول زیر، چه تعداد از مطالب بیان شده درست‌اند؟ (نمادها فرضی هستند.)\n\n| عنصر | A | B | C | D |\n\n| :--- | :---: | :---: | :---: | :---: |\n\n| آرایش الکترونی لایهٔ ظرفیت | $2s^{2}2p^{4}$ | $3s^{1}$ | $2s^{2}2p^{3}$ | $4s^{2}$ |\n\n● نسبت شمار کاتیون به شمار آنیون در ترکیب یونی حاصل از B و C برابر این نسبت در لیتیم نیترید است.\n\n● فرمول شیمیایی ترکیب حاصل از واکنش دو عنصر A و B به‌صورت $B_{2}A$ است.\n\n● آرایش الکترون – نقطه‌ای عنصر C به‌صورت $\\cdot \\ddot{C} \\cdot$ است و با از دست دادن ۳ الکترون به آرایش گاز نجیب قبل خود می‌رسد.\n\n● عنصر D متعلق به گروه ۲ و دورهٔ چهارم جدول است و فرمول شیمیایی سولفید آن به‌صورت $DS_{2}$ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:17:37', 3, 'free'),
(5565, '۷۹- منیزیم‌اکسید ................ کلسیم نیترید یک ترکیب یونی دوتایی است و اگر شمار الکترون‌های مبادله‌شده در تشکیل آن‌ها یکسان باشد، جرم کلسیم نیترید به‌دست آمده به‌تقریب چند برابر جرم منیزیم‌اکسید است؟\n\n$(Ca=40, Mg=24, N=14, O=16: g.mol^{-1})$', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:17:49', 3, 'free'),
(5566, '۸۰- با توجه به اطلاعات جدول داده شده، چند مورد از مطالب زیر نادرست است؟\n\n| A | D | M | X | Y |  |\n\n| :---: | :---: | :---: | :---: | :---: | :--- |\n\n| 8 | 18 | 18 | 13 | 18 | تعداد الکترون‌های با $n=3$ |\n\n| 2 | 6 | 7 | 1 | 2 | تعداد الکترون‌های با $n=4$ |\n\n● اختلاف عدد اتمی عناصر A و X با اختلاف عدد اتمی عناصر Y و D برابر است.\n\n● در میان این عناصر، تعداد الکترون‌های با $l=0$ در عنصر X با این تعداد در سایر عنصرها متفاوت است.\n\n● نسبت تعداد الکترون‌های با $n=3$ و $l=2$ به تعداد الکترون‌های با $n=4$ و $l=0$ در یون پایدار عناصر X و Y یکسان است.\n\n● نسبت تعداد کاتیون‌ها به آنیون‌ها در ترکیب حاصل از عناصر A و D مشابه این نسبت در ترکیب حاصل از عناصر M و $ _{19}K $ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 11:58:56', 3, 'free'),
(5567, '۸۱- کدام مطلب، دربارۀ اتم درست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:18:04', 3, 'free'),
(5568, '۸۲- کدام موارد از مطالب زیر، درست‌اند؟\n\nآ) طول موج نور بنفش از طول موج نور سبز، کوتاه‌تر است.\n\nب) انرژی هر رنگ نور مرئی، با طول موج آن نسبت مستقیم دارد.\n\nپ) نوارهای رنگی در طیف نشری خطی اتم هیدروژن، ناشی از انتقال الکترون‌ها از لایه‌های بالاتر به لایهٔ $n=2$ است.\n\nت) هر چه فاصلهٔ میان لایه‌های انتقال الکترون در اتم برانگیختهٔ هیدروژن بیش‌تر باشد، طول موج نور، بلندتر است.', 1, 3, 65, 278, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:18:17', 3, 'free'),
(5569, '۸۳- شمار پروتون‌های یون $^{۷۲}M^{2+}$ برابر ۰/۸ شمار نوترون‌های آن است. عنصر M با کدام عنصر در جدول تناوبی هم‌دوره است و در این یون، چند لایه از الکترون پر شده است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:18:30', 3, 'free'),
(5570, '۸۴- با کدام گزینه‌ها، مفهوم علمی جملۀ زیر به‌درستی کامل می‌شود؟\n\n«در میان عنصرهای واسطۀ دورۀ چهارم جدول تناوبی، دو عنصر وجود دارند که در اتم آن‌ها .............»\n\nآ) ده الکترون، عددهای کوانتومی $n=3$ و $l=2$ دارند.\n\nب) یک الکترون، عددهای کوانتومی $n=3$ و $l=0$ دارد.\n\nپ) در آخرین لایۀ الکترونی، تنها یک الکترون وجود دارد.\n\nت) دوازده الکترون، عددهای کوانتومی $n=3$ و $l=1$ دارند.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:18:47', 3, 'free'),
(5571, '۸۵- در اتم کدام عنصر، شمار الکترون‌های دارای عدد کوانتومی $l=1$، برابر مجموع شمار الکترون‌های دارای عددهای کوانتومی $l=0$ و $l=2$ است و شمار الکترون‌های ظرفیتی این عنصر، با شمار الکترون‌های لایۀ ظرفیت اتم کدام عنصر، برابر است؟ (گزینه‌ها را از راست به چپ بخوانید.)', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:18:56', 3, 'free'),
(5572, '86 - آرایش الکترونی اتم عنصر A به $3p^4$ و یون $X^{2+}$ به $3d^{10}$ ختم می‌شود. کدام موارد از مطالب زیر، درباره آن‌ها درست است؟\n\nآ) X، فلزی اصلی از گروه 2 و دوره 4 جدول تناوبی است.\n\nب) تفاوت شمار الکترون‌های اتم A و اتم X، برابر 13 است.\n\nپ) ترکیب این دو عنصر با یکدیگر، می‌تواند به صورت XA وجود داشته باشد.\n\nت) A، نافلزی هم‌گروه با عنصر $_{34}D$ و هم‌دوره با عنصر $_{13}E$ در جدول تناوبی است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:19:41', 3, 'free'),
(5573, '87 - فرمول شیمیایی چند ترکیب یونی زیر، درست است؟\n\n- منیزیم نیترید: $Mg_3N_2$\n\n- گالیم کلرید: $GaCl_2$\n\n- مس (II) سولفید: $Cu_2S$\n\n- کبالت (III) سولفات: $CO_2(SO_4)_3$\n\n- باریم سیانید: $Ba(CN)_2$\n\n- روی فسفات: $Zn_3(PO_4)_2$', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:21:27', 3, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5574, '88 - با توجه به داده‌های جدول زیر، چند مورد از مطالب زیر درست است؟ (عنصرهای $X$ ،$E$ ،$D$ و $A$ در دورهٔ چهارم جدول تناوبی جای دارند.)\n\n| ردیف | ویژگی‌ها | $X^{3+}$ | $_{33}E^{3-}$ | $_{29}D^{2+}$ | $A^-$ |\n\n| :--- | :--- | :--- | :--- | :--- | :--- |\n\n| 1 | شمار الکترون‌های آخرین لایه اشغال شده | 14  | 8 | 17 | 8 |\n\n| 2 | شمار الکترون‌های دارای عدد کوانتومی $l=2$ | 6 | a | b | 10 |\n\n| 3 | نسبت شمار الکترون‌های دارای عدد کوانتومی $l=1$ به $l=0$ | 2 | 2.25 | 2 | 2.25 |\n\n- عدد اتمی عنصر $A$، برابر مجموع عددهای ردیف دوم جدول است.\n\n- تفاوت عدد اتمی عنصر $X$ با فلز قلیایی هم‌دوره‌اش، برابر 8 است.\n\n- عنصر $E$ در واکنش با عنصر $_{13}M$، ترکیبی با فرمول شیمیایی $ME$ تشکیل می‌دهد.\n\n- بار کاتیون $D$ در ترکیب‌هایش، همانند بار کاتیون عنصر 31 جدول تناوبی در ترکیب‌هایش است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:00:06', 3, 'free'),
(5575, '89 - اگر فرمول شیمیایی فسفات فلزی به صورت $X_3(PO_4)_2$ باشد، فرمول شیمیایی سولفید و نیترید آن، به‌ترتیب از راست به چپ کدام‌اند و این فلز در کدام گروه جدول تناوبی ممکن است جای داشته باشد؟', 1, 3, 65, 278, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:23:56', 3, 'free'),
(5576, '90 - عنصر X دارای 10 الکترون با عدد کوانتومی n = 3 و l = 2 و عنصر Y دارای 7 الکترون با l = 1 می‌باشد، اختلاف عدد اتمی X و Y برابر ............... و اختلاف شماره گروه آن‌ها در جدول تناوبی برابر ............... می‌باشد.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:24:32', 3, 'free'),
(5577, '91 - کدام گزینه نادرست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:25:46', 3, 'free'),
(5578, '92 - با توجه به جدول زیر، اگر عدد اتمی عنصری از رابطهٔ $Z = \\frac{5b + 4d}{5c + 2a}$ به‌دست آید، مجموع $n + l$ آخرین زیرلایه آن کدام گزینه است؟\n\n| نماد اتم | تعداد لایه‌های پر شده از الکترون در حالت پایه | تعداد الکترون‌های ظرفیت |\n\n| :--- | :--- | :--- |\n\n| $_{30}Zn$ | a | b |\n\n| $_{15}P$ | c | d |', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:26:13', 3, 'free'),
(5579, '93 - مطابق شکل مقابل که طرحواره‌ای از سطوح انرژی لایه‌های الکترونی اتم هیدروژن است، چند مورد از عبارات زیر، به نادرستی بیان شده است؟\n\n- در میان 6 انتقال رخ داده، نور نشر شده حاصل از دو انتقال دارای طول موجی کمتر از 400 نانومتر می‌باشد.\n\n- رنگ نور نشر شده حاصل از انتقال E، مشابه رنگ شعله مس (II) سولفات بوده و دارای انرژی بیشتری نسبت به انتقال C است.\n\n- در میان انتقال‌های رخ داده، پرتوی حاصل از انتقال‌های الکترونی A و B، به‌ترتیب دارای بیشترین و کمترین فاصله بین هر دو قعر متوالی موج می‌باشند.\n\n- مجموع طول موج نور حاصل از انتقال‌های B و D با طول موج نور حاصل از انتقال ایجادکننده رنگ بنفش در طیف نشری خطی، برابر است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:26:27', 3, 'free'),
(5580, '94- اگر تفاوت شمار نوترون‌ها و الکترون‌ها در یون تک‌اتمی $^{58}X^{2+}$، برابر 5 باشد، چند مورد از موارد زیر دربارهٔ اتم عنصر X درست است؟\n\nالف) تعداد الکترون‌های با l = 2 در آرایش الکترونی آن، نصف تعداد الکترون‌های با l = 1 در آرایش الکترونی عنصر سلنیم ($_{34}Se$) است.\n\nب) تعداد الکترون‌های ظرفیت آن، دو برابر تعداد الکترون‌های ظرفیت عنصر فسفر ($_{15}P$) است.\n\nپ) مجموع n و l برای آخرین زیرلایه در آرایش الکترونی آن، برابر 5 است.\n\nت) با عنصر کلسیم، هم‌دوره و با عنصری با عدد اتمی 46، هم‌گروه است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:26:43', 3, 'free'),
(5581, '95- اتم عنصری از دورهٔ چهارم جدول تناوبی دارای 5 الکترون ظرفیت است. کدام گزینه نمی‌تواند در مورد اتم این عنصر درست باشد؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:01:16', 3, 'free'),
(5582, '96 - چند مورد نادرست است؟\n\n- هر ترکیبی که تنها از دو عنصر ساخته شده باشد، ترکیب یونی دوتایی نامیده می‌شود.\n\n- نسبت تعداد کاتیون به تعداد آنیون در سدیم‌اکسید، 4 برابر این نسبت در کلسیم کلرید است.\n\n- در ترکیب‌های یونی، حاصل‌ضرب بار کاتیون در تعداد آن، با قرینه حاصل‌ضرب بار آنیون در تعداد آن، برابر است.\n\n- همهٔ فلزهای اصلی با عدد اتمی کمتر از 18، با از دست دادن الکترون‌های زیرلایهٔ آخر خود به آرایش گاز نجیب می‌رسند.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-03 23:55:22', 3, 'free'),
(5583, '97 - دربارهٔ عناصر $_{13}A$، $_6D$، $_{17}E$ و $_8G$ چند مورد از مطالب زیر نادرست است؟\n\n- مدل فضاپرکن ترکیب حاصل از عناصر D و G به‌صورت  می‌باشد.\n\n- فرمول مولکولی ترکیب حاصل از ترکیب عناصر D و هیدروژن، شامل 4 اتم است.\n\n- دو مورد از این عناصر، در دما و فشار اتاق، به شکل مولکول‌های دواتمی دیده می‌شوند.\n\n- شمار مول الکترون‌های مبادله شده در اثر تشکیل یک مول ترکیب A با G، برابر شمار الکترون‌های ظرفیتی D است.\n\n- نسبت شمار جفت‌الکترون‌های ناپیوندی به پیوندی در مولکول حاصل از اتم‌های E در دما و فشار اتاق، برابر 3 است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:27:06', 3, 'free'),
(5584, '98 - با توجه به شکل زیر، کدام موارد زیر درست‌اند؟\n\nآ) بخش (a)، به جذب انرژی هنگام انتقال به لایهٔ سوم مربوط است که نسبت به بخش (c)، طول موج بیشتری دارد.\n\nب) بخش‌های (d) و (c)، انتقالاتی هستند که در طیف نشری خطی عنصرها در ناحیهٔ مرئی قرار می‌گیرند.\n\nپ) انرژی جذب شده در بخش (a)، بیشتر از انرژی جذب شده در بخش (d) می‌باشد.\n\nت) در اتم هیدروژن، میزان انحراف پرتوی (c) پس از عبور منشور از میزان انحراف نور حاصل از رنگ قرمز بیشتر است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:27:19', 3, 'free'),
(5585, '99 - کدام موارد از مطالب زیر درست می‌باشند؟\n\nآ) مقایسهٔ انرژی زیرلایه‌های $7p < 6d < 5f$ درست است.\n\nب) مجموعه‌ای از زیرلایه‌ها با l برابر، یک لایهٔ الکترونی را تشکیل می‌دهند.\n\nپ) مقدار l در هر لایهٔ الکترونی از صفر تا n را شامل می‌شود.\n\nت) پنجمین زیرلایهٔ الکترونی، ظرفیت پذیرش حداکثر 18 الکترون را دارد.\n\nث) لایهٔ چهارم عنصرهای دورهٔ چهارم جدول تناوبی، حداکثر 8 الکترون دریافت می‌کنند.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:27:27', 3, 'free'),
(5586, '101 - عنصر X، نخستین عنصر دارای سه زیرلایهٔ شش الکترونی و عنصر Y نخستین عنصر با 5 زیرلایهٔ دو الکترونی است، عبارت کدام گزینه نادرست است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:11:37', 3, 'free'),
(5587, '۱۰۲- چند مورد درست است؟\n\nالف) حداکثر شمار الکترون‌ها در هر لایه الکترونی، از رابطه $(2+4l)$ به دست می‌آید.\n\nب) براساس قاعده آفبا، زیرلایه $6s$ پس از زیرلایه $4f$ پر می‌شود.\n\nپ) شمار الکترون‌های دارای $l=2$ در $_{32}Ge$، نصف همین شمار در عنصر زیرین آن در جدول تناوبی است.\n\nت) در کروم، تعداد الکترون‌های دارای $l=2$، نصف تعداد الکترون‌های دارای $l=0$ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-12 12:28:22', 3, 'free'),
(5588, '۱۰۳- اگر در ترکیب‌های شیمیایی زیر، تعداد کاتیون‌ها را با $C$ و تعداد آنیون‌ها را با $\\alpha$ نشان دهیم، به ترتیب بیشترین و کمترین مقدار $\\frac{\\alpha}{C}$ برای کدام‌یک از مواد زیر است؟\n\n(آلومینیم سولفید، منیزیم فسفید، کلسیم نیترید، پتاسیم برمید، لیتیم اکسید)', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:13:58', 3, 'free'),
(5589, '۱۰۴- با توجه به شکل زیر که بخشی از جدول تناوبی عنصرها را نشان می‌دهد، چند مورد از مطالب زیر نادرست است؟ (نمادها فرضی‌اند.)\n\n● در صورت تشکیل یون مجموع بار یون‌های پایدار مربوط به عنصرهای A، B، D، G، E و H برابر ۱ است.\n\n● در یون پایدار عنصر G، همۀ لایه‌ها و زیرلایه‌های اشغال شده از الکترون، پر هستند.\n\n● عنصرهای A، B و G، به ترتیب با از دست دادن ۱، ۲ و ۳ الکترون به آرایش الکترونی گاز نجیب قبل از خود دست می‌یابند.\n\n● در صورت تشکیل یون مجموع بار یون‌های حاصل از عناصر مشخص شده‌ای که عدد اتمی آن‌ها با شمارۀ گروه‌شان یکسان است، برابر صفر است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:14:20', 3, 'free'),
(5590, '۱۰۵- آرایش الکترونی چند درصد از عنصرهای موجود در دوره‌های اول تا چهارم جدول تناوبی به زیرلایۀ s ختم می‌شود و در چه تعداد از عنصرهای تناوب چهارم جدول تناوبی، تنها یک زیرلایۀ نیمه‌پر وجود دارد؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:15:00', 3, 'free'),
(5591, '۱۰۶- چند مورد از مطالب زیر، دربارۀ $_{43}^{99}Tc$ درست‌اند؟\n\n- در تصویربرداری از غدۀ تیروئید، کاربرد دارد.\n\n- نخستین عنصری است که در واکنشگاه هسته‌ای ساخته شد.\n\n- اندازۀ یون آن درست به اندازۀ یون یدید است و در تیروئید جذب می‌شود.\n\n- زمان ماندگاری آن اندک است و نمی‌توان مقدار زیادی از آن را تولید و انبار کرد.', 1, 3, 65, 275, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:15:21', 3, 'free'),
(5592, '۱۰۷- کدام گزینه نادرست است؟', 1, 3, 65, 275, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:15:43', 3, 'free'),
(5593, '۱۰۸- یون‌های فرضی $A^+$ و $B^{5+}$ تعداد الکترون‌های یکسانی دارند و اختلاف تعداد نوترون‌های آن‌ها برابر ۷ است. عدد جرمی عنصر B کدام است؟', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:16:09', 3, 'free'),
(5594, '۱۰۹- چند مورد از عبارت‌های زیر درست‌اند؟\n\nآ) ایزوتوپ‌های منیزیم به هنگام واکنش با اکسیژن، ترکیب‌هایی با فرمول شیمیایی مشابهی را ایجاد می‌کنند.\n\nب) اگر در $^{200}Hg$ اختلاف تعداد p و n برابر ۴۰ باشد، تعداد الکترون در یون $Hg^{2+}$ برابر ۷۸ است.\n\nپ) در طیف نشری خطی لیتیم و هیدروژن در ناحیهٔ مرئی، چهار خط رنگی وجود دارد.\n\nت) شعلهٔ ترکیب‌های لیتیم و لامپ نئون مورد استفاده در ساخت تابلوهای تبلیغاتی، به رنگ سرخ است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:19:14', 3, 'free'),
(5595, ' تعداد ذرات سازنده در یک نمونه کلسیم برمید برابر $36/12 \\times 10^{24}$ ذره است. جرم نمونهٔ کلسیم برمید چند برابر نمونه‌ای از گاز متان است که دارای $24/08 \\times 10^{24}$ اتم هیدروژن می‌باشد؟ ($Ca=40, Br=80, C=12, H=1 : g.mol^{-1}$)', 1, 3, 65, 275, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5596, ' مجموع ذرات زیراتمی باردار عنصری در حالت خنثی، ۱۰ برابر تعداد نوترون‌های پایدارترین ایزوتوپ ساختگی هیدروژن است، اگر تعداد نوترون‌های آن نصف تعداد نوترون‌های نخستین عنصر ساخت بشر باشد، عدد جرمی این عنصر چند است؟', 1, 3, 65, 275, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5597, '۱۱۲- با توجه به شکل روبه‌رو، که مربوط به ایزوتوپ‌های لیتیم هست، چند مطلب نادرست است؟ (جرم پروتون و نوترون $1amu$ و عدد جرمی برابر با جرم مولی فرض شود.)\n\n● شمار کل ذرات بنیادی خنثی در تصویر برابر ۱۹۷ است.\n\n● مجموع جرم این اتم‌ها برابر با $347amu$ است.\n\n● $13/88$ گرم فلز لیتیم دارای $7/224 \\times 10^{22}$ اتم $^6_3Li$ است.\n\n● همۀ اتم‌های موجود در تصویر، رفتار شیمیایی و فیزیکی یکسانی دارند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5598, '113- چه تعداد از عبارت‌های زیر نادرست است؟\n\n● ایزوتوپ‌های یک عنصر، طیف نشری خطی متفاوتی دارند.\n\n● طول موج رنگ شعلهٔ سدیم سولفات کوچک‌تر از رنگ شعلهٔ لیتیوم سولفات است.\n\n● تعداد خطوط موجود در ناحیهٔ مرئی طیف نشری خطی هلیم بیشتر از لیتیوم است.\n\n● اختلاف تعداد نوترون و پروتون در ناپایدارترین ایزوتوپ طبیعی منیزیم و پایدارترین ایزوتوپ کلر یکسان است.\n\n● جرم اتمی سبک‌ترین ایزوتوپ هیدروژن از جرم یک پروتون بیشتر و از جرم یک نوترون کمتر است.', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:19:03', 3, 'free'),
(5599, '114- چند مورد از مطالب زیر درست است؟\n\n- همه نمک‌ها شعله رنگی دارند.\n\n- در بخش مرئی طیف نشری خطی هیدروژن، با افزایش طول موج فاصله میان دو خط متوالی افزایش می‌یابد.\n\n- رنگ نشرشده از شعله سدیم نیترات، فقط باریکه بسیار کوتاهی از گستره طیف مرئی را دربر می‌گیرد.\n\n- با افزایش عدد اتمی عنصر، تعداد خطوط ناحیه مرئی در طیف نشری خطی آن بیشتر می‌شود.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:18:52', 3, 'free'),
(5600, ' فلوئور در طبیعت دارای یک ایزوتوپ با جرم اتمی 19 گرم بر مول است. عنصر X نیز دو ایزوتوپ دارد که مجموع جرم دو ایزوتوپ برابر 140 و اختلاف تعداد نوترون‌های آن‌ها برابر 2 است. در صورتی‌که 12/68 گرم از ترکیب یونی $XF_3$ دارای $24/08 \\times 10^{22}$ یون باشد، درصد فراوانی ایزوتوپ سنگین X کدام است؟ (جرم اتمی را هم‌ارز با عدد جرمی در نظر بگیرید.)', 1, 3, 65, 275, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5601, '116- کدام موارد زیر را به کمک مدل اتمی بور نمی‌توان توضیح داد؟\n\nآ) در اتم هیدروژن، انرژی لازم برای انتقال الکترون از لایه‌ای به لایه دیگر کوانتومی است.\n\nب) به کمک این مدل، طیف نشری خطی لیتیم را می‌توان توضیح داد.\n\nپ) در اتم هیدروژن، با جذب مقدار معینی انرژی، الکترون از لایه‌ای به لایه بالاتر انتقال می‌یابد.\n\nت) جابه‌جایی الکترون در بین لایه‌های مختلف موجب ایجاد هفت خط رنگی در طیف نشری خطی سدیم می‌شود.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:18:43', 3, 'free'),
(5602, '117- در بین عنصرهای دوره چهارم جدول دوره‌ای ..........', 1, 3, 65, 278, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, '2026-09-14 19:19:53', 3, 'free'),
(5603, '118- چند مورد از مطالب زیر نادرست است؟\n\n● در مدل کوانتومی برای مشخص کردن هر زیرلایه از دو عدد کوانتومی n و l استفاده می‌شود.\n\n● از رابطه $a=4l+2$ گنجایش الکترونی لایه‌ها (a) را می‌توان به‌دست آورد.\n\n● پنجمین نوع زیرلایه یک اتم، ظرفیت پذیرش حداکثر 22 الکترون را دارد.\n\n● لایه چهارم دارای چهار زیرلایه از نوع s، p، d و f است.\n\n● در یک اتم زیرلایه‌ای نمی‌توان یافت که عدد کوانتومی اصلی و فرعی آن برابر باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5604, '119- با توجه به جدول روبه‌رو که مربوط به پایدارترین ایزوتوپ عنصرهای A و B و C از دوره چهارم جدول دوره‌ای است، چند مورد از مطالب زیر درست است؟ (نمادها فرضی است.)\n\n● میان دو عنصر A و B در جدول تناوبی 7 عنصر وجود دارد.\n\n● در یک مول از اکسید عنصر C، 3 مول یون وجود دارد.\n\n● تفاوت عدد جرمی دو عنصر A و C برابر 19 است.\n\n● تفاوت شمار الکترون‌های ظرفیت دو عنصر A و B برابر تعداد الکترون‌های آخرین زیرلایه $15^P$ است.\n\n\n\n| ویژگی | A | B | C |\n\n| :--- | :---: | :---: | :---: |\n\n| شمار نوترون | 39 | 28 | 20 |\n\n| نسبت شمار الکترون‌های ظرفیتی به شمار الکترون‌های لایه دوم | 0/375 | 0/75 |0/125|\n\n| شمار الکترون با $l=0$ | 8 | 7 | 7 |', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5605, '120- اتم عنصر E از دوره چهارم جدول دوره‌ای دارای 15 الکترون با $l=1$ است. اگر شمار ذره‌های خنثی در این اتم برابر 42 باشد، چند مورد از مطالب بیان شده زیر، درست‌اند؟ (عدد جرمی هم‌ارز جرم اتمی فرض شود.)\n\nآ) در آرایش الکترونی اتم E، شمار الکترون‌های ظرفیت آن نصف شمار الکترون‌های با $l=2$ است.\n\nب) شمار زیرلایه‌های الکترونی اشغال شده اتم آن، دو برابر شمار لایه‌های الکترونی کاملاً پر است.\n\nپ) ساختار الکترون-نقطه‌ای آن مشابه ساختار الکترون-نقطه‌ای $7^N$ است.\n\nت) جرم $1/204 \\times 10^{23}$ اتم آن برابر 15 گرم است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5606, '121- چند مورد از مطالب زیر درباره تشکیل پیوند یونی بین دو عنصر $12^X$ و $7^Y$ نادرست است؟\n\n● در طی تشکیل کاتیون $X^{2+}$ از اتم X، شعاع آن کاهش می‌یابد.\n\n● فرمول شیمیایی ترکیب حاصل از این دو عنصر به‌صورت $X_2Y_3$ است.\n\n● با تشکیل یک مول ترکیب یونی $X_3Y_2$، شش مول الکترون جابه‌جا می‌شود.\n\n● Y و $Y^{3-}$ به سبب داشتن شمار لایه‌های برابر، شعاع برابری دارند.\n\n● یون‌های ایجاد شده هنگام تشکیل ترکیب، هم‌الکترون هستند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5607, '122- کدام موارد از عبارت‌های زیر درست‌اند؟\n\nآ) در اتم X از دوره چهارم جدول دوره‌ای حداکثر 8 الکترون با $n+l$ برابر 4 وجود دارد.\n\nب) شمار الکترون‌های با $l=1$ در اتم $35^{Br}$ با شماره گروه عنصر $53^A$ یکسان است. (نماد $53^A$ فرضی است.)\n\nپ) نسبت شمار کاتیون به آنیون در منیزیم نیترید و آلومینیوم اکسید یکسان و برابر 1/5 می‌باشد.\n\nت) 75 درصد از مجموع الکترون‌های ظرفیتی اتم‌های N و H در مولکول $NH_3$ از نوع پیوندی می‌باشند.\n\nث) در تشکیل یک مول از فسفید اتم فلز $20^M$ تعداد 4 مول الکترون بین اتم‌ها دادوستد می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5608, ' در آرایش الکترون-نقطه‌ای عنصر X از دوره چهارم، بیشترین شمار تک‌الکترون دیده می‌شود و در آرایش الکترونی اتم آن 10 الکترون با $l=2$ وجود دارد و همچنین عنصر Y در همان تناوب با گرفتن یک الکترون به آرایش گاز نجیب پس از خود می‌رسد. چند مورد از مطالب زیر درباره این دو عنصر نادرست است؟\n\n● نماد شیمیایی یون پایدار این دو عنصر $X^{4+}$ و $Y^+$ است.\n\n● در ساختار الکترون-نقطه‌ای ترکیب $XY_4$، اتم مرکزی فاقد الکترون ناپیوندی است.\n\n● در آرایش الکترونی لایه ظرفیت عنصر X برخلاف اتم Y، زیرلایه‌های نیمه‌پر وجود دارد.\n\n● شمار الکترون‌های ظرفیت اتم X برابر با شمار الکترون‌های بیرونی‌ترین زیرلایه عنصر Y است.', 1, 3, 65, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:21', 1, NULL, NULL, 'free'),
(5609, 'کدام‌یک از عبارت‌های داده شده نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5610, 'در یک نمونه منیزیم که از ایزوتوپ‌های طبیعی این عنصر تشکیل شده است، درصد فراوانی ${}^{25}Mg$ برابر ۵۰٪ بوده و فراوانی سبک‌ترین ایزوتوپ، ۴ برابر فراوانی سنگین‌ترین ایزوتوپ است. جرم اتمی میانگین این نمونه از اتم‌های منیزیم کدام است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5611, 'کدام‌یک از عبارت‌های زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5612, 'با توجه به شکل داده شده که اساس استفاده از رادیوایزوتوپ‌ها را برای تشخیص توده سرطانی نشان می‌دهد، چند مورد از مطالب زیر، نادرست است؟\n\n\n\nآ) A و B به ترتیب گلوکز معمولی و گلوکز حاوی اتم پرتوزا را نشان می‌دهند.\n\nب) برخلاف گلوکز معمولی، ذرات گلوکز نشان‌دار در توده سرطانی تجمع می‌کنند.\n\nپ) C دستگاهی است که پرتوهای حاصل از گلوکز نشان‌دار را آشکار می‌سازد.\n\nت) جرم مولی مولکول‌های A در مقایسه با جرم مولی ذرات B متفاوت خواهد بود.\n\nث) گلوکز نشان‌دار، شامل اتم‌هایی می‌شود که همانند اتم ${}^{99}Tc$ پرتوزا هستند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5613, 'نمونه‌ای از هیدروژن، شامل مخلوطی از ایزوتوپ‌های ${}^{1}H, {}^{2}H$ و ${}^{3}H$ می‌شود. اگر جرم این ایزوتوپ‌ها در نمونه اولیه برابر باشد، با گذشت $۲/۸ \\times ۱۰^{-xx}$ ثانیه از ابتدای کار، درصد فراوانی ${}^{1}H$ در مخلوط مورد نظر تقریبا چقدر تغییر می‌کند؟ (جرم مولی هر ایزوتوپ برابر با جرم اتمی آن بوده و نیم‌عمر ایزوتوپ‌های ${}^{1}H$ و ${}^{2}H$ به ترتیب برابر $...$ و $۱/۴ \\times ۱۰^{-xx}$ ثانیه است.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5614, 'کدام موارد از عبارت‌های زیر درست است؟\n\nآ) جدول دوره‌ای امروزی شامل ۸ دوره و ۱۸ گروه بوده و ۱۱۸ عنصر مختلف را در خود جای داده است.\n\nب) همه اتم‌های تکنسیم موجود در جهان به‌طور مصنوعی و با استفاده از واکنش‌های هسته‌ای تولید شده است.\n\nپ) عدد جرمی با نماد A مشخص شده و در اغلب ایزوتوپ‌های ناپایدار، مقدار آن برابر یا بیش از ۲/۵ برابر عدد اتمی است.\n\nت) از همه‌ی ایزوتوپ‌های شناخته‌شده‌ترین عنصر فلزی پرتوزا، می‌توان به عنوان سوخت در راکتورهای اتمی استفاده کرد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5615, 'کدام یک از مطالب داده شده نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5616, 'چه تعداد از مطالب زیر درست است؟\n\nآ) ۷۵ درصد از کل عنصرهای موجود در دوره سوم جدول تناوبی، نماد شیمیایی دو حرفی دارند.\n\nب) در همه ایزوتوپ‌های طبیعی کلر، شمار نوترون‌های موجود در هسته بیشتر از شمار پروتون‌ها است.\n\nپ) همه عناصری که در یک گروه از جدول دوره‌ای قرار می‌گیرند، دارای خواص فیزیکی یکسانی هستند.\n\nت) عنصری با عدد اتمی ۳۴، متعلق به تناوب چهارم بوده و با عنصر ${}_{52}Te$ در یک گروه مشابه قرار می‌گیرد.\n\nث) فراوان‌ترین ایزوتوپ پایدار هیدروژن، فاقد نوترون بوده و جرم آن بیشتر از هر واحد از مقیاس جرم اتمی است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5617, 'عنصر ${}^{..}X$ دارای ۲ ایزوتوپ متفاوت است که در هسته‌ی یکی از آن ها ۲۱ نوترون و در هسته‌ی دیگری، ۲۳ نوترون وجود دارد. اگر جرم اتمی میانگین این عنصر برابر با ۴۴/۲amu باشد، فراوانی ایزوتوپ سنگین‌تر چند برابر فراوانی ایزوتوپ دیگر است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5618, 'کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5619, 'ایزوتوپ X، متعلق به دومین عنصر فراوان موجود در سیاره مشتری بوده و عدد جرمی آن برابر با ۳ است. اگر جرم هر پروتون ۱۸۴۰ برابر جرم الکترون و جرم هر نوترون نیز ۱۸۵۰ برابر جرم الکترون در نظر گرفته شود، جرم هر اتم X حدودا چند برابر جرم ${}^{3}H$ خواهد بود؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5620, 'در یک نمونه‌ی طبیعی از لیتیم، ............. ایزوتوپ پایدار وجود داشته و در صورت پاشیدن مقداری از گرد این عنصر بر روی شعله‌ی آتش، رنگ شعله ............. شده و در صورت عبور دادن نور حاصل از این شعله از یک منشور، طیف نشری-خطی با ............. نوار رنگی در ناحیه‌ی مرئی تشکیل می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5621, 'جرم‌های برابر از متانول و آمونیوم نیترات در اختیار داریم. اگر تفاوت شمار اتم‌های هیدروژن موجود در این دو ماده برابر با $1/806 \\times 10^{24}$ عدد باشد، در این نمونه از متانول چند گرم اکسیژن وجود خواهد داشت؟ $(H=1, C=12, N=14, O=16: g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5622, 'کدام موارد از عبارت‌های زیر درست است؟\n\nآ) پروتون با نماد ${}_{1}^{1}p$ مشخص شده و همانند نوترون، جرم هر ذره از آن بیشتر از یک $amu$ است.\n\nب) نمونه‌هایی با جرم برابر از گازهای اوزون و اکسیژن، شامل شمار برابری از اتم‌های اکسیژن می‌شوند.\n\nپ) بار یون تک‌اتمی حاصل از عنصری با عدد اتمی ۳۵، مشابه بار یون حاصل از عنصری با عدد اتمی ۷ است.\n\nت) در هسته ایزوتوپی از کربن که در ایجاد مقیاس $amu$ کاربرد دارد، تعداد ذرات زیراتمی باردار و بدون بار برابر است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5623, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5624, 'یک عنصر از جدول دوره‌ای، با گاز کریپتون در یک تناوب قرار داشته و شمار الکترون‌هایی با $l=1$ در آن، دو برابر شمار الکترون‌هایی با $l=0$ است. اگر تفاوت شمار نوترون‌ها و پروتون‌ها در هسته‌ی هر اتم از این عنصر برابر با ۱۱ عدد باشد، عدد جرمی اتم‌های این عنصر چقدر می‌شود؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5625, 'کدام موارد از عبارت‌های داده شده درست هستند؟\n\nآ) در ساختار لایه‌ای اتم، احتمال حضور الکترون پیرامون هسته، در یک فضای محدود بیشتر از سایر نقاط است.\n\nب) در ۸ مورد از عناصر موجود در تناوب چهارم جدول دوره‌ای، لایه‌ی الکترونی $n=3$ کاملا پر از الکترون است.\n\nپ) پرتو ایجاد شده با انتقال $e$ از لایه $n=4$ به $n=2$ در اتم هیدروژن، در مقایسه با پرتو زرد انرژی کمتری دارد.\n\nت) در عناصر دوره پنجم، زیرلایه $4f$ خالی از الکترون بوده و این زیرلایه پس از زیرلایه $5d$ شروع به پر شدن می‌کند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5626, 'کدام یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5627, 'جرم‌های برابر از لیتیم اکسید و ۱-پروپانول در اختیار داریم. اگر شمار اتم‌های اکسیژن موجود در این دو نمونه از ماده به اندازه‌ی $4/515 \\times 10^{23}$ عدد با هم تفاوت داشته باشد، در مراحل تولید نمونه‌ی لیتیم اکسید از عناصر سازنده‌ی آن، چند مول الکترون بین اتم‌ها مبادله شده و با سوزاندن کامل نمونه‌ی ۱-پروپانول، چند گرم گاز کربن دی‌اکسید تولید می‌شود؟\n\n$(Li=7, H=1, C=12, O=16: g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5628, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) دانشمندان برای یافتن انواع فلزهای موجود در ظروف سفالی قدیمی، از نمونه این مواد طیف نشری تهیه می‌کنند.\n\nب) اگر تعداد الکترون‌های ظرفیت اتمی کمتر یا برابر ۳ باشد، آن اتم در شرایط مناسب به کاتیون تبدیل می‌شود.\n\nپ) عنصر ${}_{33}As$ با عنصر ${}_{7}N$ در یک گروه مشابه و با عنصر ${}_{23}V$ در یک تناوب مشابه از جدول دوره‌ای قرار دارد.\n\nت) بیرونی‌ترین زیرلایه الکترونی در برخی از یون‌ها، برخلاف اتم‌های خنثی، می‌تواند زیرلایه‌ای با $l=2$ باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5629, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5630, 'مقدار اتم‌های موجود در ساختار یک نمونه‌ی ۶/۳ گرمی از ترکیب $Na_2SO_3$ برابر با ۰/۳ مول است. بر این اساس، در ساختار یک نمونه‌ی ۱۸/۱ گرمی از ترکیب $NaClO_x$، چند گرم اکسیژن وجود دارد؟\n\n$(Na=23, S=32, Cl=35/5, O=16 : g.mol^{-1})$', 1, 3, 65, 275, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5631, 'با توجه به اطلاعات جدول زیر، چند مورد از عبارت‌های داده شده درست هستند؟\n\n\n\nعنصر A: آرایش الکترونی لایه ظرفیت $...p^{4}$\n\nعنصر B: آرایش الکترونی لایه ظرفیت $3d^{5}4s^{...}$\n\nعنصر C: آرایش الکترونی لایه ظرفیت $5s^{1}$\n\nعنصر D: آرایش الکترونی لایه ظرفیت $3d^{10}4s^{1}$)\n\nآ) هر اتم از عنصر A فاقد زیرلایه‌های الکترونی با عدد کوانتومی فرعی $l=2$ است.\n\nب) فرمول نیترید عنصر D، به صورت DN و فرمول اکسید عنصر C نیز به صورت $C_2O$ است.\n\nپ) ۷۵ درصد از عنصرهای موجود در جدول داده شده، چکش‌خوار بوده و سطح درخشان دارند.\n\nت) برای تشکیل یک مول نمک از واکنش میان دو عنصر A و C، یک مول الکترون مبادله می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5632, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5633, 'جرم برابر از ایزوتوپ‌های A و B در اختیار داریم. اگر با گذشتن ۱۸۰۰ ثانیه از ابتدای کار، جرم باقیمانده از ایزوتوپ A، چهار برابر جرم باقیمانده از ایزوتوپ B شده باشد، نیم‌عمر ایزوتوپ ناپایدارتر برابر چند دقیقه است؟ (نیم‌عمر ایزوتوپ A، دو برابر نیم‌عمر ایزوتوپ B باشد.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5634, 'چه تعداد از عبارت‌های زیر درست هستند؟ $(Fe=56, Si=28, O=16 : g.mol^{-1})$\n\nآ) پرسش («هستی چگونه پدید آمده است؟»)، پرسشی بنیادی بوده و در قلمرو علوم تجربی نمی‌گنجند.\n\nب) بر اثر انفجار بزرگ یا مهبانگ، ابتدا ذرات زیراتمی و پس از آن، عناصر موجود در تناوب اول به وجود آمدند.\n\nپ) تعداد نوترون‌ها در هر اتم ${}^{99}Tc$، ۱۴ برابر تعداد آن‌ها در سبک‌ترین ایزوتوپ ساختگی از عنصر هیدروژن است.\n\nت) در ترکیبی با فرمول شیمیایی $Fe_2SiO_4$، درصد جرمی دومین عنصر فراوان موجود در زمین بیشتر از ۱۵٪ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5635, 'کدام یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5636, 'در یک نمونه لیتیم که از ایزوتوپ‌های طبیعی این عنصر تشکیل شده است، درصد فراوانی ایزوتوپ سبک‌تر به اندازه ۶۰٪ کمتر از ایزوتوپ دیگر است. در یک نمونه از لیتیم سولفات که با استفاده از این نمونه لیتیم تهیه شده است، درصد جرمی اتم‌های فلزی تقریبا چقدر می‌شود؟ $(Li=?, S=32, O=16 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5637, 'کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) مرگ ستاره‌ها اغلب با انفجاری همراه است که سبب پراکنده شدن عناصر تشکیل شده در آن ستاره در فضا می‌شود.\n\nب) نخستین عنصر تولید شده در واکنشگاه هسته‌ای، یک نافلز بوده و از آن در تصویربرداری پزشکی استفاده می‌شود.\n\nپ) فضاپیماهای وویجر مأموریت داشتند شناسنامه‌ی فیزیکی و شیمیایی سیاره اورانوس را تهیه کرده و ارسال کنند.\n\nت) چون توده‌های سرطانی بدن فقط گلوکز پرتوزا را جذب می‌کنند، می‌توان موقعیت آن‌ها را در بدن مشخص کرد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5638, 'نمونه‌ای از عنصر A، شامل ایزوتوپ‌های ${}^{A}A$ و ${}^{A+2}A$ شده و در آن، فراوانی ایزوتوپ ${}^{A+2}A$، ۱/۵ برابر ایزوتوپ دیگر است. اگر نیمی از اتم‌های ${}^{A}A$ موجود در این نمونه را از آن خارج کنیم، درصد فراوانی این ایزوتوپ در نمونه مورد نظر چند برابر می‌شود؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5639, 'کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) از ایزوتوپ ${}^{235}U$ به عنوان سوخت هسته‌ای استفاده شده و درصد جرمی آن در اورانیم غنی شده کمتر از ۰/۷٪ است.\n\nب) مجموع شماره تناوب و شماره گروه عنصری که در هر اتم خود ۳۳۶ ذره زیراتمی باردار دارد، برابر با ۲۵ است.\n\nپ) عناصری با عدد اتمی ۹ و ۵۳، در واکنش با فلزها تعداد الکترون برابری از دست داده و یون ایجاد می‌کنند.\n\nت) مقدار چگالی یک نمونه از اتم‌های ${}^{54}Fe$، متفاوت از مقدار چگالی یک نمونه از اتم‌های ${}^{56}Fe$ است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5640, '۳۴- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5641, '۳۵- نمونه‌ای از گاز کلر به جرم ۱۶۱/۱ گرم که از ایزوتوپ‌های طبیعی این عنصر تشکیل شده است، با ۸۴ گرم فلز آهن بر اساس معادله موازنه نشده زیر به طور کامل واکنش می‌دهد. تفاوت درصد فراوانی ایزوتوپ‌های موجود در این نمونه از گاز کلر برابر با چند درصد بوده و جامد تولید شده در این فرایند، با چند لیتر محلول ۱/۸ مولار سود به طور کامل واکنش می‌دهد؟\n\n$(Fe=56 g.mol^{-1})$\n\n$Fe(s) + Cl_r(g) \\rightarrow FeCl_r(s)$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5642, '۳۶- کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) تعداد عناصر موجود در گروه ۱۶ جدول دوره‌ای، ۲ برابر تعداد عناصری از دوره سوم است که نماد یک‌حرفی دارند.\n\nب) عنصری که با ${}_{82}Pb$ در یک تناوب و با ${}_{16}S$ در یک گروه قرار می‌گیرد، ۸۴ پروتون در هسته‌ی هر اتم خود دارد.\n\nپ) استفاده از یکاهایی مثل شانه و دست برای شمارش تخم مرغ و قاشق و چنگال، محاسبه را آسان‌تر می‌کند.\n\nت) دقت اندازه‌گیری باسکول‌های تنی تا یک دهم تن بوده و دقت ترازوی زرگری نیز تا یک صدم گرم است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5643, '۳۸- اگر در یون تک‌اتمی با نماد ${}^{57}A^{3+}$، شمار نوترون‌های موجود در هسته ۱/۲۵ برابر شمار الکترون‌ها باشد، در یک نمونه ۱۱/۴ گرمی از این یون چند مول الکترون وجود داشته و تفاوت شمار الکترون‌ها و نوترون‌های موجود در یون ${}^{59}A^{2+}$ کدام است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5644, '۳۹- کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5645, '۴۰- جرم اتم‌های X موجود در نمونه‌ای از اکسید $X_2O_5$، ۴/۲۵ برابر جرم اتم‌های اکسیژن موجود در این اکسید است. شمار اتم‌های اکسیژن در ساختار یک نمونه ۵۰/۴ گرمی از این اکسید، چند برابر شمار اتم‌های اکسیژن موجود در یک نمونه ۱/۶ گرمی از گاز $SO_3$ می‌شود؟ $(S=32, O=16 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5646, '۴۱- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5647, '۴۲- یک نمونه ۲۸ گرمی از مس(II) اکسید، تقریبا شامل ............ اتم اکسیژن در ساختار خود شده و جرم اتم‌های مس موجود در این نمونه، ............ برابر جرم اتم‌های مس در ۲۸ گرم مس(I) سولفات بوده و با پاشیدن گرد این ماده بر روی شعله آتش، شعله مورد نظر ............ رنگ می‌شود. $(Cu=64, S=32, O=16 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5648, '۴۳- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5649, '۴۴- چه تعداد از عبارت‌های زیر درست است؟\n\nآ) هر چه به هسته اتم نزدیک‌تر شویم، انرژی الکترون‌های موجود در لایه‌های متوالی به یکدیگر نزدیک‌تر می‌شود.\n\nب) مجموع تعداد عناصر موجود در دسته‌ی p جدول دوره‌ای امروزی، ۰/۹ برابر تعداد عناصر دسته‌ی d است.\n\nپ) الکترون در حالت برانگیخته ناپایدار بوده و همواره پس از نشر یک پرتو مرئی، به حالت پایه باز می‌گردد.\n\nت) نور خورشید، به رنگ سفید دیده شده و فقط شامل پرتوهایی با طول موج ۴۰۰ تا ۷۰۰ نانومتر می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5650, '۴۵- در شرایط یکسان، حجم‌های برابر از گازهای متانول و نیتروژن دی‌اکسید در اختیار داریم به صورتی که شمار اتم‌های اکسیژن موجود در نمونه نیتروژن دی‌اکسید به اندازه $3/01 \\times 10^{22}$ عدد بیشتر از شمار اتم‌های اکسیژن موجود در نمونه متانول است. با استفاده از این نمونه متانول، چند گرم متیل بوتانوآت می‌توان تهیه کرد؟ $(H=1, C=12, O=16 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5651, '۴۶- عدد اتمی فلز قلیایی خاکی که در تناوب ششم از جدول دوره‌ای قرار می‌گیرد، چند برابر عدد اتمی فراوان‌ترین گاز نجیب موجود در سیاره مشتری بوده و بین این عنصر فلزی و عنصر آلومینیم، چند عنصر دیگر در جدول دوره‌ای قرار گرفته است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5652, '۴۷- کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5653, '۴۸- در ساختار یون ${}^{65}X^{3+}$، شمار الکترون‌ها به اندازه ۲۵٪ کمتر از شمار نوترون‌ها است. عنصر X با کدام یک از عناصر داده شده در یک گروه مشابه قرار داشته و در آرایش الکترونی این عنصر، چند الکترون با $n+l=5$ وجود دارد؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5654, '۴۹- در اتم فلز واسطه X از تناوب چهارم، ۲۰ درصد از الکترون‌ها در زیرلایه‌ای با $l=2$ قرار گرفته‌اند. اگر جرم اتمی میانگین این عنصر برابر با $54/2 amu$ باشد، درصد فراوانی ایزوتوپ سنگین‌تر این عنصر در نمونه مورد نظر چقدر خواهد بود؟ (عنصر X، ۲ ایزوتوپ مختلف دارد که در هسته یکی از آن‌ها ۲۸ و در هسته دیگری، ۳۰ نوترون یافت می‌شود.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5655, '۵۰- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, NULL, 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5656, '۵۱- شمار الکترون‌های پیوندی موجود در لایه ظرفیتی اتم‌ها در ۲/۴ گرم از اولین عضو خانواده آلکان‌ها، چند برابر شمار اتم‌های موجود در ۰/۲۴ گرم از فراوان‌ترین گاز نجیب موجود در سیاره مشتری است؟ $(H=1, He=4, C=12, Ar=40 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5657, '۵۲- در واکنش تولید نمونه‌ای از پتاسیم سولفید، $3/612 \\times 10^{23}$ الکترون بین اتم‌ها مبادله شده است. تفاوت شمار مول‌های آنیون و کاتیون در این ماده چقدر بوده و جرم ترکیب تولید شده با توجه به اطلاعات موجود در جدول زیر برابر با چند گرم می‌شود؟\n\n\n\nایزوتوپ: ${}^{39}K$, ${}^{41}K$, ${}^{32}S$, ${}^{34}S$\n\nدرصد فراوانی: ۹۰, ۱۰, ۸۰, ۲۰)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5658, '۵۳- کدام موارد از عبارت‌های زیر درست است؟\n\nآ) اتم‌های نافلزی در شرایط مناسب با تشکیل پیوندهای اشتراکی می‌توانند مولکول‌های دو یا چند اتمی را بسازند.\n\nب) اگر آرایش الکترونی فلز اصلی X به $4s^2$ ختم شود، از واکنش این عنصر با برم، ترکیب $X_2Br$ ایجاد می‌شود.\n\nپ) ۴۰٪ از الکترون‌های موجود در آرایش الکترون-نقطه‌ای مولکول $N_2$، فقط به یک اتم نیتروژن تعلق دارند.\n\nت) نیمی از عناصر موجود در دوره‌ی دوم، در دما و فشار اتاق به شکل مولکول‌های دواتمی یافت می‌شوند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5659, '۵۴- کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5660, '۵۵- در یک نمونه از فلز منیزیم، درصد فراوانی ایزوتوپ ${}^{24}Mg$ برابر با ۲۰٪ بوده و به ازای هر اتم ${}^{25}Mg$ نیز ۴ اتم از ایزوتوپ ${}^{26}Mg$ وجود دارد. چند گرم از این نمونه فلز منیزیم با ۶۴ گرم اکسیژن به طور کامل واکنش داده و طی این فرایند، چند الکترون بین گونه‌ها مبادله می‌شود؟ $(O=16 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:44', 1, NULL, NULL, 'free'),
(5661, '۵۶- چه تعداد از مطالب داده شده درست هستند؟\n\nآ) مجموعه‌های گازی که کهکشان‌ها و ستاره‌ها را ایجاد می‌کنند، با استفاده از گازهای هیدروژن و هلیم ساخته شده‌اند.\n\nب) در روند تشکیل عناصر، هیدروژن به هلیم تبدیل شده و عنصر هلیم نیز فقط می‌تواند به عناصر فلزی تبدیل شود.\n\nپ) در واکنش‌های شیمیایی که در اطراف ما رخ می‌دهند، انرژی مبادله شده بسیار کمتر از واکنش‌های هسته‌ای است.\n\nت) شیمی‌دان‌ها ماده‌ای را عنصر می‌نامند که یک نمونه از آن، فقط از یک نوع اتم با جرم یکسان تشکیل شده باشد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5662, '۵۷- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5663, '۵۸- شمار اتم‌های هیدروژن موجود در یک نمونه ۳۴ لیتری از گاز آمونیاک با چگالی $2g.L^{-1}$، با شمار پیوندهای اشتراکی موجود در ساختار چند گرم گاز متان برابر خواهد بود؟ $(H=1, C=12 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5664, '۵۹- چه تعداد از مطالب داده شده درست هستند؟\n\nآ) از آنجا که نیم‌عمر تکنسیوم کم است، نمی‌توان مقادیر زیادی از این عنصر را تهیه و برای مدت طولانی نگهداری کرد.\n\nب) عنصری که آرایش الکترونی آن به $3p^6$ ختم می‌شود، نافلز بوده و رادیوایزوتوپ‌های آن در ایران تولید می‌شوند.\n\nپ) با پیشرفت علم شیمی و فیزیک، می‌توان طلا تولید کرد اما هزینه تولید آن زیاد بوده و صرفه اقتصادی ندارد.\n\nت) گلوکز پرتوزا حاوی اتم‌هایی است که بر اثر تلاشی، افزون بر ذرات پرانرژی، مقدار زیادی انرژی آزاد می‌کنند.\n\nث) تناوب هفتم جدول دوره‌ای، در ساختار خود ۳۲ عنصر جای داده و به عنصری با عدد اتمی ۱۱۶ ختم می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5665, '۶۰- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5666, '۶۱- کدام‌یک از مطالب زیر درست است؟ $(O=16, N=14 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5667, '۶۲- تفاوت شمار الکترون‌ها و نوترون‌ها در یون ${}^{126}X^{2-}$، ۲/۵ برابر تفاوت شمار الکترون‌ها و نوترون‌ها در یون ${}^{55}Mn^{3+}$ است. در ساختار اتم X، چند لایه الکترونی کاملا پر وجود داشته و مجموع شماره دوره و گروه عنصر X، چند برابر مجموع شماره دوره و گروه عنصر ${}_{21}Sc$ خواهد بود؟ (گزینه‌های داده شده را از راست به چپ بخوانید.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5668, '۶۳- جدول زیر، اطلاعات مربوط به ایزوتوپ‌های مختلف موجود در نمونه‌هایی از کلسیم و فلوئور را نشان می‌دهد:\n\n\n\nکلسیم: ${}^{42}Ca$ ۱۰٪، ${}^{44}Ca$ ۱۵٪، ${}^{40}Ca$ ۷۵٪\n\nفلوئور: ${}^{19}F$ ۹۰٪، ${}^{18}F$ ۱۰٪)\n\nجرم مولی یک نمونه از کلسیم فلوئورید که با استفاده از ایزوتوپ‌های بالا تولید می‌شود، برابر با چند $g.mol^{-1}$ بوده و در آرایش الکترونی کاتیون موجود در این ترکیب، چند الکترون با $l=0$ وجود خواهد داشت؟', 1, 3, 65, 275, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5669, '۶۴- کدام موارد از مطالب داده شده درست هستند؟\n\nآ) در همه ایزوتوپ‌های طبیعی کلر، مجموع شمار ذرات زیراتمی موجود در هسته بیشتر از ۲ برابر شمار الکترون‌ها است.\n\nب) با دادن انرژی به الکترون موجود در اتم H، محدوده‌ای که احتمال حضور $e^-$ در آن وجود دارد بزرگ‌تر می‌شود.\n\nپ) رنگ زرد، از جمله رنگ‌های سازنده رنگین کمان بوده و در مقایسه با پرتوهای سبز، طول موج کوتاه‌تری دارد.\n\nت) نور خورشید سفید رنگ بوده و با استفاده از پرتوهایی ساخته شده است که با خود انرژی حمل می‌کنند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5670, '۶۵- چه تعداد از مطالب داده شده درست هستند؟\n\nآ) اگر مقداری از محلول یک نمک حاوی کاتیون فلزی را با افشانه روی شعله بپاشیم، رنگ و دمای شعله تغییر می‌کند.\n\nب) نیلز بور با بررسی تعداد و جایگاه خطوط رنگی در طیف نشری هیدروژن، اطلاعاتی از ساختار اتم H به دست آورد.\n\nپ) نیمی از الکترون‌های موجود در اتم Be، همه وقت خود را در ناحیه مربوط به لایه‌ای با $n=2$ سپری می‌کنند.\n\nت) اگر نور نشر شده از شعله لیتیم سولفات را از یک منشور عبور دهیم، یک طیف با ۴ خط رنگی ایجاد می‌شود.\n\nث) مدل لایه‌ای، طیف نشری فلز سدیم را توجیه کرده و مطابق آن، هسته اتم بیشتر حجم آن را اشغال می‌کند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5671, '۶۶- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5672, '۶۷- در کدام‌یک از عناصر زیر، شمار الکترون‌های موجود در لایه $n=3$ معادل با نصف حداکثر گنجایش الکترونی این لایه بوده و شماره گروه این عنصر، چند برابر شماره تناوب آن خواهد بود؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5673, '۶۸- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5674, '۶۹- نمونه‌ای از ${}^{238}Pu$، شامل ۴ مول اتم می‌شود. پس از گذشتن ۲۴۰ سال، چند گرم پلوتونیم از نمونه اولیه باقی مانده و شمار نوترون‌های موجود در پلوتونیم باقیمانده، چند برابر شمار نوترون‌های موجود در ۲ مول از فراوان‌ترین ایزوتوپ طبیعی لیتیم خواهد بود؟ (نیم‌عمر ${}^{238}Pu$ برابر با ۸۰ سال بوده و جرم مولی هر ایزوتوپ را معادل با جرم اتمی آن در نظر بگیرید.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5675, '۷۰- در یک نمونه از ترکیب $SF_x$ به جرم ۵۴ گرم، تفاوت شمار اتم‌های گوگرد و فلوئور برابر با $9/03 \\times 10^{23}$ عدد است. جرم یک نمونه از آلومینیم اکسید که در ساختار آن $x$ مول یون اکسید وجود دارد برابر با چند گرم می‌شود؟ $(S=32, O=16, F=19, Al=27 : g.mol^{-1})$', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5676, '۷۱- چه تعداد از مطالب داده شده درست هستند؟\n\nآ) با تابش نور، برخلاف گرما دادن، می‌توان الکترون موجود در اتم هیدروژن را به لایه‌های الکترونی بالاتر انتقال داد.\n\nب) در اتم H، با انتقال الکترون از لایه $n=6$ به لایه‌ای که گنجایش ۸ الکترون را دارد، پرتو بنفش گسیل می‌شود.\n\nپ) فلز منیزیم، تنها عنصر از جدول دوره‌ای است که شمار الکترون‌هایی با $l=1$ و $l=0$ در اتم‌های آن برابر است.\n\nت) برای نوشتن آرایش الکترونی فشرده عنصری از گروه دوم با عدد اتمی ۳۷، از نماد گاز کریپتون استفاده می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5677, '۷۲- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5678, '۷۳- اتم ${}_{27}Co^{3+}$، دارای ............ الکترون با $l=1$ بوده و شمار الکترون‌های ظرفیتی موجود در اتم آن، با شمار زیرلایه‌های پر شده از الکترون در اتم ............ برابر خواهد بود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5679, '۷۴- مخلوطی که شامل جرم برابر از نقره نیترات ($AgNO_3$) و سدیم نیترات ($NaNO_3$) می‌شود، در اختیار داریم. اگر در مخلوط مورد نظر مجموعا $4/515 \\times 10^{23}$ اتم نیتروژن وجود داشته باشد، جرم این مخلوط جامد برابر با جرم چند مول گاز آمونیاک خواهد بود؟ ($Ag=108, Na=23, N=14, O=16, H=1 : g.mol^{-1}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5680, '۷۵- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5681, '۷۶- چه تعداد از مطالب داده شده درست هستند؟ ($Na=23, S=32 : g.mol^{-1}$)\n\nآ) بررسی‌ها نشان می‌دهد اتم‌های همه عناصر، می‌توانند به صورت یون در ترکیب‌های گوناگون و طبیعی یافت شوند.\n\nب) در واکنش تولید ۳۹ گرم سدیم سولفید از عناصر سازنده آن، یک مول الکترون بین گونه‌ها مبادله خواهد شد.\n\nپ) ترکیبی با فرمول $NaN_3$، سدیم نیترید نام داشته و لایه دوم الکترونی در کاتیون آن کاملا پر الکترون است.\n\nت) در واکنش بین دو اتم فلوئور که منجر به تشکیل مولکول $F_2$ می‌شود، هر اتم یک $e^-$ به اشتراک می‌گذارد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5682, '۷۷- کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5683, '۷۸- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5684, '۷۹- در یک نمونه از اتم‌های منیزیم که از ایزوتوپ‌های طبیعی این عنصر تشکیل شده است، درصد فراوانی ${}^{25}Mg$ برابر ۴۰ درصد بوده و فراوانی سبک‌ترین ایزوتوپ، ۴ برابر فراوانی سنگین‌ترین ایزوتوپ است. جرم ۵ مول از این نمونه منیزیم، به اندازه چند گرم کمتر از جرم ۲ مول فلز مس است؟ ($Cu=63/5 g.mol^{-1}$)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5685, '۸۰- عدد اتمی دومین عنصری از جدول دوره‌ای که در تناوب ششم قرار می‌گیرد، چند برابر عدد اتمی فراوان‌ترین گاز نجیب موجود در سیاره مشتری بوده و بین این عنصر و عنصر ${}_{13}Al$، چند عنصر دیگر در جدول دوره‌ای قرار گرفته است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5686, '۸۱- چه تعداد از عبارت‌های زیر درست است؟\n\nآ) با استفاده از علوم تجربی، نمی‌توان به پرسش ((جهان هستی چگونه پدید آمده است؟)) پاسخ داد.\n\nب) عناصر سنگین از جمله طلا، طی واکنش‌های هسته‌ای و از عناصری مثل لیتیم و کربن تولید می‌شوند.\n\nپ) بر اثر انفجار بزرگ یا مهبانگ، ابتدا ذرات زیراتمی و پس از آن، عناصر موجود در تناوب اول به وجود آمدند.\n\nت) تعداد نوترون‌های موجود در اتم ${}^{14}_{6}C$، ۴ برابر تعداد آن‌ها در سبک‌ترین ایزوتوپ ساختگی از هیدروژن است.\n\nث) فضاپیماهای وویجر ماموریت داشتند ترکیب‌های شیمیایی اتمسفر سیاره مشتری و درصد فراوانی آن‌ها را تهیه کنند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5687, '۸۲- در یون ${}^{2x+2}_{x}X^{2+}$، اختلاف شمار نوترون‌های موجود در هسته و الکترون‌ها برابر با $2 + \\frac{x}{2}$ است. عنصر X معادل با کدام‌یک از عناصر زیر می‌تواند باشد و این عنصر، با چه عنصری از تناوب چهارم در یک گروه مشابه قرار می‌گیرد؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5688, '۸۳- در مخلوطی از اتم‌های ${}^{1}H, {}^{2}H, {}^{3}H$، جرم این ایزوتوپ‌ها با هم برابر است. تا لحظه‌ای که جرم ایزوتوپ ${}^{2}H$ نسبت به نمونه اولیه نصف می‌شود، درصد فراوانی ایزوتوپ ${}^{1}H$ در مخلوط مورد نظر تقریبا چقدر افزایش می‌یابد؟ (جرم مولی هر ایزوتوپ برابر با جرم اتمی آن بوده و نیم‌عمر ایزوتوپ‌های ${}^{7}H$ و ${}^{5}H$ به ترتیب برابر با $10^{-23} \\times 2/8$ و $10^{-22} \\times 1/4$ ثانیه است.)', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5689, '۸۴- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5690, '۸۵- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5691, '۸۶- چه تعداد از عبارت‌های زیر درست است؟\n\nآ) اندازه یون یدید با یون تکنسیم برابر بوده و به همین خاطر، از یون تکنسیم در تصویربرداری تیروئید استفاده می‌شود.\n\nب) از همه ایزوتوپ‌های شناخته شده‌ترین عنصر فلزی پرتو‌زا، می‌توان به عنوان سوخت در راکتورهای اتمی استفاده کرد.\n\nپ) در یون ${}^{33}X^{3-}$، اگر تعداد الکترون‌ها و نوترون‌ها برابر باشد، شماره گروه عنصر X، ۵ برابر شماره تناوب آن می‌شود.\n\nت) چون خواص شیمیایی ایزوتوپ‌ها به مقدار A آن‌ها بستگی دارد، ایزوتوپ‌های لیتیم واکنش‌پذیری متفاوتی دارند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5692, '۸۷- در یک نمونه‌ی لیتیم که از اتم‌های طبیعی این عنصر ساخته شده است، به ازای هر اتم از ایزوتوپ سبک‌تر، ۴ اتم از ایزوتوپ سنگین‌تر وجود دارد. جرم یک نمونه از این فلز که شامل $1/204 \\times 10^{21}$ اتم می‌شود، برابر با چند میلی‌گرم بوده و این مقدار از فلز لیتیم، در هسته اتم‌های خود شامل چند مول پروتون می‌شود؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5693, '۸۸- با توجه به اطلاعات جدول زیر، جرم مولکولی میانگین ترکیب $BBr_3$ بر حسب amu کدام است؟ (جرم اتمی هر ایزوتوپ را با عدد جرمی آن معادل در نظر بگیرید.)\n\n(جدول: ایزوتوپ‌ها ${}^{10}B$ (۲۰٪), ${}^{11}B$ (۸۰٪) و ${}^{79}Br$ (۵۵٪), ${}^{81}Br$ (۴۵٪))', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5694, '۸۹- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5695, '۹۱- چه تعداد از عبارت‌های زیر درست است؟\n\nآ) دقت اندازه‌گیری باسکول‌های تنی تا یک صدم تن بوده و دقت ترازوی زرگری نیز تا یک صدم گرم است.\n\nب) جرم هسته‌ی هر یون {}^{58}_{28}Ni^{3+} تقریبا ۲۳۲۰ برابر جرم الکترون‌های موجود در ساختار این یون است.\n\nپ) هر چه طول موج یک پرتو کم‌تر باشد، زاویه انحراف آن پس از عبور از منشور، بیشتر خواهد بود.\n\nت) طول موج پرتوهای فرابنفش و فروسرخ، به ترتیب بیشتر از ۷۰۰nm و کم‌تر از ۴۰۰nm است.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5696, '۹۲- جرم‌های برابر از ساده‌ترین عضو خانواده آلکان‌ها و آمونیوم نیترات (NH_4NO_3) در اختیار داریم. اگر تفاوت شمار اتم‌های هیدروژن موجود در این دو ماده برابر با ۲/۴۰۸ \\times 10^{24} عدد باشد، در نمونه آلکان چند گرم کربن وجود خواهد داشت؟\n\n(O=16, N=14, C=12, H=1 : g.mol^{-1})', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5697, '۹۳- کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5698, '۹۴- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5699, '۹۵- چگالی بلور کلسیم اکسید برابر با ۳/۳۶ g.cm^{-3} است. در مراحل تولید یک نمونه از این ترکیب به حجم ۳۰cm^3، چند مول الکترون بین گونه‌های شرکت‌کننده در واکنش مبادله شده و شمار الکترون‌هایی با l=0 در ساختار کاتیون‌های سازنده این ماده، چند برابر شمار این الکترون‌ها در اتم گالیم است؟ (Ca=40, O=16 : g.mol^{-1})', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5700, '۹۶- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) تفاوت سطح انرژی لایه‌های الکترونی n=6 و n=7 در اتم هیدروژن، کمتر از لایه‌های n=3 و n=4 است.\n\nب) در ۶ مورد از عناصر موجود در تناوب چهارم جدول دوره‌ای، لایه‌ی الکترونی n=3 کاملا پر از الکترون است.\n\nپ) پرتو حاصل از انتقال الکترونی از لایه n=4 به n=2 در اتم H، نسبت به پرتو زرد انرژی بیشتری دارد.\n\nت) گاز نئون در ساختار لامپ‌های استفاده شده برای ساختن انواعی از تابلوهای تبلیغاتی سرخ‌فام وجود دارد.\n\nث) با استفاده از نور، می‌توان دمای شعله‌های بسیار داغ و یا دمای سطحی ستاره‌ها را تعیین کرد.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5701, '۹۷- کدام‌یک از مطالب زیر درست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5702, '۹۸- جرم اتم‌های فلزی موجود در ۱۴ گرم از ترکیب یونی حاصل از واکنش میان فلز کلسیم و گاز اکسیژن، تقریبا چند برابر جرم اتم‌های اکسیژن موجود در یک نمونه ۴۵ گرمی از اوره است؟\n\n(Ca=40, O=16, N=14, C=12, H=1 : g.mol^{-1})', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5703, '۹۹- مخلوطی که شامل جرم‌های برابر از اتانول و فورمیک اسید می‌شود، در اختیار داریم. اگر در این مخلوط مجموعا ۳/۶۱۲ \\times 10^{23} اتم کربن وجود داشته باشد، جرم این مخلوط برابر با چند گرم می‌شود؟\n\n(H=1, C=12, O=16 : g.mol^{-1})', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5704, '۱۰۰- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) مدل بور، همانند مدل لایه‌ای اتم‌ها، توانایی توجیه طیف نشری خطی هیدروژن را داشت.\n\nب) آرایش الکترون نقطه‌ای همه عناصر موجود در یک گروه از جدول دوره‌ای، مشابه یکدیگر است.\n\nپ) برای نوشتن آرایش الکترونی فشرده فسفر و بور، به ترتیب از نماد عناصر آرگون و هلیم استفاده می‌شود.\n\nت) لایه‌هایی با $n=2$ و $n=3$، لایه‌های یکپارچه‌ای نبوده و هر کدام از آن‌ها از دو زیرلایه مجزا تشکیل شده‌اند.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5705, '۱۰۱- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5706, '۱۰۲- اگر عنصر $A$ دارای ۱۶ الکترون با عدد کوانتومی فرعی $l=1$ بوده و شکل روبه‌رو، توصیفی از عنصر $B$ باشد، کدام گزینه فرمول ترکیب حاصل از این دو عنصر را به درستی نشان می‌دهد؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5707, '۱۰۳- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5708, '۱۰۴- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) شمار الکترون‌های موجود در یون برمید، با شمار الکترون‌های موجود در یون پتاسیم برابر است.\n\nب) تعداد اتم‌ها در یک نمونه ۷۲ گرمی از گاز اوزون با تعداد اتم‌ها در ۷۲ گرم گاز اکسیژن برابر است.\n\nپ) ۲۵٪ از کل الکترون‌های موجود در هر مولکول اکسیژن، در تشکیل پیوند اشتراکی شرکت کرده‌اند.\n\nت) آلومینیوم اکسید جامد نارسانا بوده و در مراحل تولید هر مول از آن، ۶ مول الکترون بین مواد مبادله می‌شود.', 1, 3, 65, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:45:45', 1, NULL, NULL, 'free'),
(5709, 'براساس اطلاعات جدول داده‌شده، مقدار $a$ و $b$ در کدام گزینه قابل قبول است؟ (اطلاعات، مربوط به لایه تروپوسفر است.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5710, 'چند مورد از مطالب زیر، درست است؟\n\n\n\n- فراوان ترین ترکیب موجود در هوای پاک و خشک، تأثیر زیادی در شرایط آب و هوایی نقاط گوناگون زمین دارد.\n\n- حدود ۸۵ درصد از جرم کل هواکره تا ارتفاع 11.5 کیلومتری از سطح زمین قرار دارد.\n\n- برای سبک ترین گاز نجیب، منابع زمینی از هواکره سرشارتر و برای تولید آن در مقیاس صنعتی مناسب تر است.\n\n- دو جزء اصلی سازنده هوا، در هر سه لایه اول هواکره حضور دارند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5711, 'با توجه به جدول داده شده، چند مورد از مطالب زیر نادرست است؟\n\n\n\n- بین درصد حجمی دومین و سومین گاز سازنده هوای پاک و خشک و ترتیب خروج آن ها از هوای مایع در ستون تقطیر جزء به جزء، رابطه معکوس وجود دارد.\n\n- در دمایی که به اندازه  $106^{\\circ}C$ سردتر از دمای چگالش کربن دی اکسید است، فقط یکی از عنصرهای نیتروژن، اکسیژن و آرگون به حالت مایع وجود دارد.\n\n- اختلاف درصد حجمی اولین گاز و سومین گازی که در تقطیر جزء به جزء هوای مایع با دمای  $-200^{\\circ}C$ از ستون تقطیر جدا می شوند، در هواکره تقریباً برابر ۵۷ درصد است.\n\n- کربن دی اکسید در دمایی که $78$K کم تر از نقطه انجماد رطوبت هوا است، به صورت مایع وجود دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5712, 'در فرمول شیمیایی چه تعداد از ترکیب های زیر، نسبت شمار اتم ها به شمار عنصرها، بزرگ تر از این نسبت در نیتریدی از فلز کروم با کم ترین بار الکتریکی کاتیون است؟\n\n- فسفر تری برمید\n\n- نقره سولفید\n\n- منگنز (IV) اکسید\n\n- آلومینیم فسفید\n\n- ید پنتافلوئورید\n\n- کربن دی سولفید', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5713, 'با توجه به جدول داده شده که برخی از ویژگی های چند عنصر را نشان می دهد، چند مورد از مطالب داده شده، درست اند؟\n\n\n\n- شمار الکترون های پیوندی در مولکول های $DB_3$ و ساده ترین ترکیب هیدروژن دار عنصر $A$، برابر است.\n\n $A$ و $D$ می توانند ترکیب مولکولی با فرمول $AD_2$ تشکیل دهند.\n\n- با توجه به این که در ساختار یون $\\begin{bmatrix} O-X=O \\end{bmatrix}^-$، همه اتم ها از قاعده هشتایی پیروی می کنند، $X$ می تواند عنصر $A$ باشد.\n\n- شمار جفت الکترون های ناپیوندی در ساختار مولکول $ADB$، دو برابر شمار این جفت الکترون ها در مولکول $AB$ است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5714, 'در ساختار لوویس کدام مولکول، اتم مرکزی فاقد جفت الکترون ناپیوندی است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5715, 'در کدام واکنش زیر پس از موازنه، مجموع ضرایب مواد شرکت کننده، کم تر است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5716, 'کدام گزینه نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5717, 'اگر با سوختن گاز پروپان مطابق واکنش زیر، گازهای $CO$، $H_2O$ و $CO_2$ تولید شود و $ b > a $ باشد، کدام گزینه درست است؟\n\n$4C_3H_8(g) + 19O_2(g) \\rightarrow aX(g) + bY(g) + 16H_2O(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5718, 'کدام موارد از مطالب زیر، نادرست اند؟\n\nالف) زمین بخش قابل توجهی از گرمای جذب شده را به صورت امواجی با انرژی کم تر از پرتویی با طول موج ۷۰۰ نانومتر، از دست می دهد.\n\nب) اگر هواکره وجود نداشت، میانگین دمای کره زمین به ۲۹۱ کلوین کاهش می یافت.\n\nپ) گازهای گلخانه ای مانع خروج بخش قابل توجهی از گرمای آزادشده از زمین می شوند.\n\nت) در سده اخیر با افزایش مقدار کربن دی اکسید در هواکره، میانگین جهانی سطح آب های آزاد افزایش یافته است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5719, 'چند مورد از مطالب زیر درباره گازهای نجیب، درست است؟\n\n- به دسته $p$ جدول دوره ای تعلق دارند و در طبیعت به شکل تک اتمی یافت می شوند.\n\n- بیرونی ترین لایه الکترونی اشغال شده آن ها، به طور کامل پر است.\n\n- شمار عناصر بین گازهای نجیب دوره های سوم و چهارم برابر با شمار عناصر بین گازهای نجیب دوره های چهارم و پنجم جدول دوره ای است.\n\n- در چهارمین عضو آن ها، شمار الکترون ها با $n+l=5$ دو برابر شمار الکترون ها با $n+l=4 $ است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5720, 'در دوره سوم جدول تناوبی، اختلاف شماره گروه عنصرهایی با یک الکترون جفت نشده در آرایش الکترون - نقطه ای، چند برابر اختلاف شماره گروه عنصرهایی با سه الکترون جفت نشده در آرایش الکترون - نقطه ای است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5721, 'با توجه به آرایش الکترون – نقطه‌ای عنصرهای A تا D که به دسته s یا p جدول دوره‌ای تعلق دارند، چند مورد از مطالب زیر درست است؟\n\n\n\n- از واکنش دو عنصر A و D، ترکیبی یونی با فرمول AD حاصل می‌شود.\n\n- نماد یون پایدار عنصر C، به صورت $C^{-2}$ است.\n\n- در تشکیل هر مول ترکیب یونی حاصل از واکنش عنصرهای B و D، ۲ مول الکترون مبادله می‌شود.\n\n- نسبت شمار جفت‌الکترون‌های ناپیوندی به پیوندی در مولکول $CD_2$، برابر ۴ است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5722, 'اگر آرایش الکترونی $X^{-2}$ به  $2p^6$ و آرایش الکترونی $Y^{+3}$ به $3d^3$ ختم شود، کدام مطلب درباره عنصرهای X و Y درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5723, 'چند مورد از مطالب زیر درست است؟\n\n- کلسیم اکسید از نظر نسبت شمار کاتیون به آنیون، مشابه با سدیم سولفید است.\n\n- برای تشکیل ترکیب‌هایی مانند آلومینیم اکسید و هیدروژن کلرید، اتم‌ها باید با یکدیگر الکترون دادوستد کنند.\n\n- فرمول ترکیب حاصل از واکنش دو عنصر $X_{35}$ و $Y_{55}$ به صورت YX است.\n\n- فلزهای گروه ۱۳ جدول تناوبی با از دست دادن سه الکترون به آرایش گاز نجیب قبل از خود می‌رسند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5724, 'اگر در مخلوطی به جرم ۵۰ گرم از اکسیدهای مس با ظرفیت‌های متداول آن،  41.6گرم مس وجود داشته باشد، چند درصد جرم مخلوط را اکسید مس با جرم مولی کم‌تر تشکیل می‌دهد؟ $(O=16 , Cu=64 : g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5725, 'چند مورد از مطالب زیر درست است؟\n\n\n\n- کاتیون و آنیون سازنده منیزیم فسفید برخلاف کاتیون و آنیون سازنده پتاسیم کلرید، آرایش الکترونی یکسانی دارند.\n\n- در بیرونی‌ترین زیرلایه یون پایدار عنصری با عدد اتمی ۲۰، ۶ الکترون با $n+l=4$ وجود دارد.\n\n- آرایش الکترونی  $1s^2 2s^2 2p^6$ را می‌توان به یک اتم خنثی، به یک کاتیون و یا به یک آنیون پایدار نسبت داد.\n\n- اگر یون $X^{-2}$ دارای ۱۸ الکترون باشد، در آرایش الکترون – نقطه‌ای اتم X، دو جفت‌الکترون وجود دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5726, 'کدام مطلب درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5727, 'در جرم یکسان، نسبت شمار الکترون‌های مبادله‌شده در تشکیل سدیم فسفید به شمار الکترون‌های مبادله‌شده در تشکیل منیزیم سولفید از عنصرهای سازنده، کدام است؟ $(Na=23, Mg=24, P=31, S=32 : g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5728, 'کدام موارد از مطالب زیر دربارهٔ عنصرهایی از جدول تناوبی که در دما و فشار اتاق به شکل مولکول‌های دواتمی وجود دارند، نادرست‌اند؟\n\nالف) همهٔ آن‌ها جزء عنصرهای نافلزی بوده و به دستهٔ p جدول تعلق دارند.\n\nب) اغلب این عنصرها با تشکیل یون و یا اشتراک گذاشتن الکترون، به آرایش هشت‌تایی گاز نجیب هم‌دورهٔ خود می‌رسند.\n\nپ) در ساختار مولکول‌های دواتمی مربوط به این عنصرها، تنها پیوند یگانه یا دوگانه وجود دارد.\n\nت) در بیرونی‌ترین زیرلایهٔ اشغال‌شدهٔ ۴ عنصر از میان آن‌ها، ۵ الکترون وجود دارد', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5729, 'کدام موارد از مطالب زیر درست‌اند؟\n\nالف) فلز آلومینیم در طبیعت به شکل بوکسیت( $Al_2O_3$ خالص) وجود دارد.\n\nب) واکنش سوختن گوگرد و تبدیل آن به گوگرد دی‌اکسید، نخستین مرحلهٔ تهیهٔ سولفوریک‌اسید در صنعت است.\n\nپ) نوع فرآورده‌ها در واکنش سوختن سوخت‌های فسیلی، به مقدار سوخت بستگی دارد.\n\nت) فلزهایی مانند سدیم، منیزیم و آهن در شرایط مناسب با گاز اکسیژن می‌سوزند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5730, 'اگر درصد جرمی هیدروژن در ترکیب $C_xH_4$ برابر ۱۰ و درصد جرمی گوگرد در ترکیب $SO_y$ برابر ۵۰ باشد؛ نام چه تعداد از ترکیب‌های داده‌شده درست است؟ $(S=32, O=16, C=12, H=1 : g.mol^{-1})$\n\nالف) $MnO_y$ :  اکسید (II) منگنز \n\nب) $NF_x$ : مونونیتروژن تری‌فلوئورید\n\nپ) $Cu_xP_y$ :  فسفید(II) مس\n\nت) $N_yO_{(x+y)}$ : دی‌نیتروژن پنتااکسید', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5731, 'با توجه به مدل فضاپرکن مولکول‌های داده‌شده، کدام مطلب درست است؟ (مقیاس نسبی شعاع گوی‌ها الزاماً برای همهٔ گزینه‌ها رعایت نشده است.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5732, 'کدام مطلب نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5733, 'اگر ساختار لوویس مولکول‌های $HXO_3$ و $SOY_2$ به صورت زیر باشد، نسبت شمار جفت‌الکترون‌های ناپیوندی به پیوندی در ساختار مولکول $XOY$ کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5734, 'در تشکیل  $4.515\\times 10^{23}$ مولکول آمونیاک، چند مول جفت‌الکترون بین اتم‌ها به اشتراک گذاشته می‌شود و این شمار الکترون در تشکیل چند گرم فرمالدهید ($CH_2O$)، بین اتم‌ها به اشتراک گذاشته می‌شود؟\n\n$(H=1, C=12, O=16: g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5735, 'با توجه به معادله واکنش‌های داده‌شده، چند مورد از مطالب زیر درست است؟\n\nI) $KNO_3(s) \\xrightarrow{600^{\\circ}C} K_2O(s) + N_2(g) + O_2(g)$\n\nII) $K_2Cr_2O_7(s) \\to K_2CrO_4(s) + Cr_2O_3(s) + O_2(g)$\n\nIII) $C_2H_4(g) + Cl_2(g) \\xrightarrow{FeCl_3(s)} C_2H_4Cl_2(g)$\n\nIV) $2ClF_3(g) + 2NH_3(g) \\to N_2(g) + 6HF(g) + X(g)$\n\n$\\bullet$ ضریب $O_2$ در معادله‌های موازنه‌شدهٔ واکنش‌های (I) و (II) با هم برابر است.\n\n$\\bullet$ نماد $\\xrightarrow{FeCl_3(s)}$ در واکنش (III)، نشان می‌دهد که این واکنش در حضور کاتالیزگر آهن تری کلرید انجام می‌شود.\n\n$\\bullet$ مادۀ X در معادلۀ موازنه‌شدهٔ واکنش (IV)، گاز کلر است.\n\n$\\bullet$ نماد $\\xrightarrow{600^{\\circ}C}$ در واکنش (I)، نشان می‌دهد که با انجام این واکنش، دما به $600^{\\circ}C$ می‌رسد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5736, 'مطابق شکل زیر، مقداری محلول هیدروکلریک اسید به فلز منیزیم اضافه شده تا واکنش:\n\n $Mg(s)+2HCl(aq) \\rightarrow MgCl_2(aq)+H_2(g)$ انجام شود. گاز هیدروژن تولیدشده در این واکنش به ظرفی حاوی ۶ گرم گاز اکسیژن وارد و بر اثر جرقه، منفجر می‌شود. اگر طی این فرایند، همۀ گاز هیدروژن اولیه مصرف و 4.5 گرم آب تولید شده باشد، به تقریب چند درصد از گاز اکسیژن اولیه، در واکنش شرکت نکرده است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5737, 'پس از موازنۀ معادلۀ واکنش زیر، کدام نسبت بزرگ‌تر است؟\n\n$aLiAlH_4(s) + bH_2O(l) \\rightarrow cLiOH(aq) + dAl(OH)_3(s) + eH_2(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5738, 'اگر ضریب گاز کربن دی‌اکسید در معادلۀ واکنش (I)، 2.4 برابر ضریب آن در معادلۀ واکنش (II) باشد، ضریب استوکیومتری گاز اکسیژن در معادلۀ واکنش (II)، چند برابر ضریب گاز اکسیژن در معادلۀ واکنش (I) است و مجموع شمار اتم‌ها در فرمول مولکولی هیدروکربن شرکت‌کننده در واکنش (II) کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:02', 1, NULL, NULL, 'free'),
(5739, '1- کدام مطلب درباره لیتیم سولفات، درست است؟ (1mol S = 32 g S, 1mol O = 16 g O, 1mol Li = 7 g Li)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5740, '2- کدام مطلب درباره اولین عنصر گروه هجدهم جدول دوره‌ای عناصر، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5741, '3- کدام مطلب، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5742, '4- سالانه در جهان، پنجاه‌هزار میلیون قرص آسپیرین با بهره‌گیری از استوکیومتری واکنش در شرکت‌های دارویی تولید می‌شود. اگر هر قرص شامل 486 میلی‌گرم آسپیرین و 8/97 میلی‌گرم کدئین باشد، در مجموع چند مول از مواد زیر مصرف می‌شود؟ (1mol H = 1 g H, 1mol C = 12 g C, 1mol N = 14 g N, 1mol O = 16 g O)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5743, '5- عنصر گوگرد، در دمای اتاق به حالت جامد و شامل مولکول‌های هشت اتمی است. با توجه به این که در مولکول گوگرد، هر اتم، تنها با دو اتم دیگر پیوند داشته و همه اتم‌ها از قاعده هشت‌تایی پیروی می‌کنند، کدام مطلب نادرست است؟ (1mol Ag = 108 g Ag, 1mol S = 32 g S)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5744, '6- درباره ترکیب آلی اکسیژن‌دار زیر، کدام مطلب درست است؟ (1mol H = 1 g H, 1mol C = 12 g C, 1mol O = 16 g O)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5745, '7- پس از موازنه واکنش‌های زیر، کدام مطلب درست است؟\n\nI) NiO(s) + ClF$_3$(l) → NiF$_2$(s) + Cl$_2$(g) + O$_2$(g)\n\nII) C$_x$H$_y$(g) + NO(g) → CO$_2$(g) + H$_2$O(g) + N$_2$(g)\n\nIII) FeTiO$_3$(s) + C(s) + Cl$_2$(g) → FeCl$_3$(s) + TiCl$_4$(l) + CO(g)\n\nIV) As$_2$O$_3$(s) + KI(aq) + HCl(aq) → AsI$_3$(s) + KCl(aq) + H$_2$O(l)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5746, '8- کدام مطلب درباره آهک، نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5747, '9- فسفر سفید، یکی از آلوتروپ‌های فسفر است که شامل مولکول‌های چهار اتمی بوده و در هر اتم با سه پیوند، به سه اتم دیگر متصل شده است. با پیروی از قاعده هشت‌تایی، در ساختار لوویس مولکول فسفر سفید، تفاوت شمار الکترون‌های پیوندی و ناپیوندی موجود در لایه ظرفیت اتم‌ها، برابر با کدام عدد بوده و کدام مطلب درباره این آلوتروپ فسفر، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5748, '11- فرمول کلی زغال‌سنگ را به صورت C$_{13}$H$_9$O$_6$NS برآورد می‌کنند. اگر در شرایط معین، از سوختن 46/5 کیلوگرم زغال‌سنگ، 1688/5 کیلوگرم فرآورده حاصل شود، معادله موازنه‌شده سوختن آن در این شرایط کدام است؟ (S = 32, O = 16, N = 14, C = 12, H = 1 : g mol$^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5749, '12- با رعایت قاعده هشت‌تایی، در لایه ظرفیت اتم‌های چند گرم آمونیوم کربنات، یک مول الکترون ناپیوندی وجود دارد؟ (O = 16, N = 14, C = 12, H = 1 : g mol$^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5750, '13- چند مورد از مطالب زیر، درباره اوزون، درست است؟\n\n• در لایه بالایی هوا کره، یافت می‌شود.\n\n• دگرشکلی از اکسیژن در هوا کره است.\n\n• بیشترین مقدار آن در لایه تروپوسفر، وجود دارد.\n\n• نقش محافظ را در جلوگیری از رسیدن پرتوهای فرابنفش به سطح زمین، دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5751, '14- مجموع ضرایب استوکیومتری مواد در معادله واکنش: PCl$_5$(g) + P$_4$O$_{10}$(s) → POCl$_3$(l)، پس از موازنه، کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5752, '15- بوکسیت، اکسید .......... با فرمول .......... است که در .......... می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5753, '16- 1/36 کیلوگرم آمونیاک را از واکنش چند لیتر گاز هیدروژن در شرایط STP با مقدار اضافی گاز نیتروژن می‌توان تهیه کرد؟ (NH$_3$ = 17 g.mol$^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5754, '17- چه تعداد از عبارت‌های زیر درباره کربن مونوکسید، درست است؟\n\n• گازی بی‌رنگ، بی‌بو، بسیار سمی و دارای چگالی بیش‌تر از هوا است.\n\n• در صورت کم بودن میزان اکسیژن در محیط، تنها فرآورده واکنش سوختن سوخت‌های فسیلی است.\n\n• در ساختار لوویس آن، چهار الکترون ناپیوندی وجود دارد.\n\n• میل ترکیبی هموگلوبین خون با این گاز بسیار زیاد و بیش از 200 برابر اکسیژن است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5755, '18- مولکول .......... مانند مولکول .......... دارای .......... جفت الکترون پیوندی است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5756, '19- اگر دمای یک نمونه گاز آرگون در فشار ثابت، از 77°C به 425 کلوین افزایش یابد، حجم گاز چند درصد افزایش می‌یابد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5757, '20- براساس واکنش موازنه نشده: NaN$_3$(s) → Na(s) + N$_2$(g)، از تجزیه 14/95 گرم NaN$_3$ چند لیتر گاز N$_2$ آزاد می‌شود؟ (Na = 23, N = 14 : g.mol$^{-1}$ ، چگالی نیتروژن = 0/92 g.L$^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5758, '21- در مورد معادله‌های نمادی زیر که در آنها حالت فیزیکی تمام مواد گاز است، کدام گزینه نادرست می‌باشد؟\n\n1) N$_2$ + O$_2$ → NO\n\n2) NO + O$_2$ → NO$_2$\n\n3) NO$_2$ + O$_2$ → NO + O$_2$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5759, '22- چند مورد از جمله‌های زیر نادرست است؟\n\n• نئون، دومین گاز نجیب است که در هوای پاک و خشک، بیشترین درصد حجمی را دارد.\n\n• با افزایش ارتفاع در لایه تروپوسفر، شیب کاهش فشار به تدریج کم می‌شود.\n\n• با افزایش ارتفاع از سطح کره زمین تا ارتفاع 500 کیلومتری، دمای هواکره در چهار مرحله، °C 0 می‌شود.\n\n• جاذبه زمین، مولکول‌های هواکره را پیرامون خود نگهداشته و آنها را در سراسر هواکره توزیع می‌کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5760, '23- چند مورد از جمله‌های زیر درست است؟\n\n• هر چه ضخامت سیم کمتر باشد، مقاومت آن در برابر جریان الکتریکی بیشتر است.\n\n• آلومینیوم اکسید، جامدی با ساختار متخلخل و پایدار است که محکم به سطح فلز آلومینیوم می‌چسبد.\n\n• در واکنش ترمیت، نسبت عدد اکسایش گونه کاهنده به گونه اکسنده، صفر است.\n\n• نور حاصل از سوختن گوگرد نسبت به نور حاصل از سوختن فلز سدیم، طول موج کمتری دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5761, '24- معادله زیر مربوط به بی‌رنگ شدن محلول پتاسیم پرمنگنات در واکنش با اگزالیک اسید در حضور سولفوریک اسید است. پس از موازنه این معادله، مجموع ضرایب مواد شرکت‌کننده در آن کدام است؟\n\nKMnO$_4$(aq) + H$_2$C$_2$O$_4$(aq) + H$_2$SO$_4$(aq) → K$_2$SO$_4$(aq) + MnSO$_4$(aq) + CO$_2$(g) + H$_2$O(l)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5762, '25- چند مورد از جمله‌های زیر نادرست است؟\n\n• در معادله نمادی سوختن کامل متان، تفاوت شمار اتم‌های اکسیژن در طرفین معادله، صفر است.\n\n• اگر در معادله واکنشی، مجموع تعداد اتم‌ها در طرفین معادله برابر باشد، آن معادله موازنه شده است.\n\n• واکنش تشکیل زنگار از فلز آهن، از قانون پایستگی جرم پیروی می‌کند.\n\n• معادله نمادی افزون بر نمایش فرمول شیمیایی مواد، می‌تواند حالت فیزیکی آنها و نیز اطلاعاتی درباره شرایط واکنش ارائه کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5763, '26- چه تعداد از مطالب زیر، درست هستند؟\n\n• عنصر اکسیژن در آب کره، در ساختار مولکول‌های آب و در زیست‌کره در ساختار همه مولکول‌های زیستی یافت می‌شود.\n\n• فراوان‌ترین گاز نجیب هواکره را می‌توان از تقطیر جزء به جزء هوای مایع تهیه کرد.\n\n• هر چه مقدار گازهای گلخانه‌ای در هواکره بیشتر باشد، دمای زمین بالاتر می‌رود.\n\n• طلا و پلاتین به حالت آزاد در طبیعت یافت می‌شوند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5764, '27- در واکنش Ca(OH)$_2$(aq) + b H$_3$PO$_4$(aq) → a Ca$_3$(PO$_4$)$_2$(s) + H$_2$O(l) ، پس از موازنه، نسبت $\\frac{a}{b}$ کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5765, '۲۸- اگر در فشار ثابت، دمای یک نمونه گاز به حجم ۴۰۰ میلی‌لیتر از ۴۷°C به ۵۵°C برسد، حجم گاز چند درصد افزایش می‌یابد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5766, '۲۹- با توجه به جدول زیر چند ردیف به‌صورت نادرست بیان شده است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5767, '۳۰- اتم مرکزی کدام ترکیب فاقد جفت الکترون ناپیوندی است و در مجموع کدام ترکیب دارای بیشترین جفت الکترون ناپیوندی است؟ (گزینه‌ها را از راست به چپ بخوانید.) SO₂ ، NO₂F ، O₃ ، SOF₂ ، NOCl', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5768, '۳۱- کدام گزینه در مورد مجموع ضرایب فرآورده‌های گازی واکنش‌های زیر پس از موازنه درست است؟\n\nA) $KNO_۳(s) \\rightarrow K_۲O(s) + N_۲(g) + O_۲(g)$\n\nB) $C_۲H_۵N_۳O_۹(l) \\rightarrow CO_۲(g) + H_۲O(g) + N_۲(g) + O_۲(g)$\n\nC) $(NH_۴)_۲Cr_۲O_۷(s) \\rightarrow Cr_۲O_۳(s) + N_۲(g) + H_۲O(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5769, '۳۲- چه تعداد از گزینه‌های زیر درباره بیشترین ترکیب سازنده هوای پاک و خشک، درست‌اند؟\n\n- در دمای $۷۸^\\circ C-$. به حالت جامد در می‌آید.\n\n- مقدار کمتری از آن در صورت استفاده از گاز طبیعی، به جای نفت خام برای تولید برق، وارد هواکره خواهد شد.\n\n- در ساختار لوییس آن، چهار جفت الکترون ناپیوندی وجود دارد.\n\n- در نیروگاه‌ها و مراکز صنعتی برای تبدیل به مواد معدنی، با کلسیم اکسید یا منیزیم اکسید واکنش داده می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5770, '۳۳- نسبت شمار کاتیون به آنیون در هر واحد فرمولی آمونیوم سولفات، برابر نسبت شمار آنیون به کاتیون در هر واحد فرمولی در چه تعداد از گونه‌های زیر است؟\n\n*منیزیم کربنات *آهن (II) فسفید *پتاسیم نیترات *کلسیم برمید', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5771, '۳۴- چه تعداد از موارد زیر درباره مولکول اوزون، درست است؟\n\n- دگرشکلی از اکسیژن است و از مولکول اکسیژن ناپایدارتر است.\n\n- امکان جهت‌گیری در میدان الکتریکی برای آن وجود ندارد.\n\n- در ساختار لوییس آن سه جفت الکترون پیوندی و شش الکترون ناپیوندی وجود دارد.\n\n- نقطهٔ جوش آن از اکسیژن، بیشتر است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5772, '۳۵- چند متر مکعب فرآورده گازی با چگالی $1.2 \\ \\mathrm{g\\,L^{-1}}$ از واکنش $5.1$ گرم گاز آمونیاک با مقدار کافی از $N_2O(g)$ حاصل می‌شود؟ $(N=14, H=1 \\ : \\ \\mathrm{g\\,mol^{-1}})$\n\n$3N_2O(g) + 2NH_3(g) \\rightarrow 4N_2(g) + 3H_2O(l)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5773, '۳۶- در اثر تجزیه کامل $X$ گرم از ماده واکنش‌دهنده مطابق واکنش موازنه‌نشده $(NH_4)_2Cr_2O_7(s) \\rightarrow Cr_2O_3(s) + N_2(g) + H_2O(g)$، جرم مواد جامد باقی‌مانده در ظرف واکنش $150$ گرم کاهش می‌یابد؛ $X$ برحسب گرم کدام است؟ $(Cr=52, O=16, N=14, H=1 \\ : \\ \\mathrm{g\\,mol^{-1}})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5774, '۳۷- اگر با بازیافت هر تن آهن، ردپای کربن دی‌اکسید به میزان $200$ گرم کاهش یابد، با بازیافت تقریبی سالانه چند میلیون تن آهن، از انتشار $0.1\\times10^6$ مترمکعب کربن دی‌اکسید در هوا جلوگیری می‌شود؟ شرایط را استاندارد فرض کنید. $(O=16, C=12 \\ : \\ \\mathrm{g\\,mol^{-1}})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5775, '۳۸- دمای هوا در انتهای یکی از لایه‌های هواکره در یک سیاره فرضی به حدود $-150^\\circ C$ می‌رسد. اگر ارتفاع تقریبی این لایه $25$ کیلومتر باشد و با افزایش ارتفاع در این لایه به‌ازای هر کیلومتر، دما در حدود $15^\\circ C$ افت کند، دمای پایین‌ترین قسمت این لایه تقریباً چند کلوین است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5776, '۳۹- شمار جفت الکترون‌های ناپیوندی در چه تعداد از ترکیبات زیر، برابر با شمار جفت الکترون‌های ناپیوندی در $CH_2S$ است؟\n\nSCO * $CS_2$ * HCN * CO *', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5777, '۴۰- مجموع ضرایب استوکیومتری فرآورده‌ها در دو واکنش زیر پس از موازنه، کدام است؟\n\n$Ca_3P_2(s) + H_2O(l) \\rightarrow Ca(OH)_2(aq) + PH_3(g)$\n\n$K_2CrO_4(aq) + Pb(NO_3)_2(aq) \\rightarrow PbCrO_4(s) + KNO_3$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5778, '۴۱- پس از موازنه واکنش (I) و (II)، نسبت مجموع ضرایب استوکیومتری واکنش‌دهنده‌ها در واکنش (I) به مجموع ضرایب فرآورده‌ها در واکنش (II) کدام است و اگر در واکنش (II)، ۰/۱ مول از گاز اکسیژن مصرف شود، در مجموع به تقریب چند لیتر گاز در شرایط STP تولید می‌شود؟\n\n(I) $KNO_۳(s) + KI(s) + HCl(aq) \\rightarrow KCl(aq) + NO(g) + H_۲O + I_۲$\n\n(II) $NH_۴CH_۳COO(s) + O_۲ \\rightarrow N_۲(g) + CO_۲(g) + H_۲O(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5779, '۴۲- یک کیلوگرم از $P_4O_{10}$ در یک مخزن دارای یک متر مکعب آب مقطر، حل شده است. برای خنثی‌سازی کامل آن، چند گرم آهک $CaO(s)$ لازم است؟ (معادلات موازنه شوند) $(P=31 , O=16 , Ca=40 , H=1 : g.mol^{-1})$\n\n۱) $P_۴O_{۱۰} + H_۲O \\rightarrow H_۳PO_۴$\n\n۲) $H_۳PO_۴ + CaO \\rightarrow Ca_۳(PO_۴)_۲ + H_۲O$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5780, '۴۳- برای پاکسازی هوای یک شهر از $CO_2$ تولید شده از یک خودرو که در سال $20000$ کیلومتر مسافت را با مصرف متوسط $10 \\, kg$ از $C_8H_{18}$ در هر $100$ کیلومتر طی می‌کند، به تقریب چند درخت با قطر $22 \\, cm$ باید وجود داشته باشد؟ (واکنش سوختن $C_8H_{18}$ را کامل فرض کنید؛ هر درخت با این قطر سالانه $20 \\, kg$ از $CO_2$ را جذب می‌کند.) $(C=12 , H=1 , O=16 : g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5781, '۴۴- در یک ظرف دربسته، $5/6$ لیتر گاز اکسیژن در شرایط STP وارد شده و در شرایط مناسب طی واکنش (موازنه نشده) $O_2 \\rightleftharpoons O_3$ تبدیل به اوزون شده است. اگر در این ظرف شمار اتم‌های اکسیژن مربوط به مولکول‌های اوزون برابر $6/02 \\times 10^{23}$ باشد، به تقریب چند درصد از مولکول‌های اکسیژن به اوزون تبدیل شده‌اند؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5782, '۴۵- چند مورد از عبارت‌های زیر، درست‌اند؟\n\n- در میان ۷ گاز اصلی سازندهٔ هوا کره (هوای پاک و خشک)، چهار گاز نجیب وجود دارد.\n\n- اوزون، گازی با مولکول‌های سه اتمی است که در لایه‌های بالایی هواکره (استراتوسفر) مانند پوششی کره زمین را احاطه کرده است.\n\n- هلیم گازی بی‌بو با رنگ زرد کم‌رنگ است که در جوشکاری و غواصی به کار می‌رود.\n\n- در ضمن سرد کردن هوا برای تهیه هوای مایع، برخی از اجزای آن به صورت جامد جدا می‌شوند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5783, '۴۶- از سوزاندن ناقص متان، برای تهیه متانول در صنعت استفاده می‌شود. برای تهیه هر کیلوگرم متانول، چند لیتر گاز متان در شرایط STP لازم است؟ $(C=12 , H=1 , O=16 : g.mol^{-1})$\n\n$CH_۴ + O_۲ \\rightarrow CO + H_۲O$\n\n$CO + H_۲ \\rightarrow CH_۳OH$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5784, '۴۸- در چند مورد از ترکیبات جدول زیر، نام و فرمول شیمیایی ترکیب، به‌درستی نوشته شده است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5785, '۴۹- در ترکیب زیر، با رعایت قاعده هشت‌تایی، چند جفت الکترون ناپیوندی وجود دارد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5786, '۵۰- شمار عنصرهایی که در دما و فشار اتاق به شکل مولکول‌های دو اتمی وجود دارند چند برابر عنصرهایی از دسته d دوره چهارم جدول دوره‌ای است که در لایه سوم خود ۱۸ الکترون دارند؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5787, '۵۱- کدام عبارت زیر، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5788, '۵۲- گاز به‌دست‌آمده از واکنش چند گرم منیزیم با مقدار کافی از HCl با ۸ گرم گاز اکسیژن، به طور کامل واکنش می‌دهد؟ (معادله واکنش‌ها موازنه شوند)\n\n$Mg(s) + HCl(aq) \\rightarrow MgCl_۲(aq) + H_۲(g)$; $H_۲(g) + O_۲(g) \\rightarrow H_۲O(g)$; $Mg=۲۴, O=۱۶: g.mol^{-۱}$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5789, '۵۳- در ساختار لوویس چه تعداد از گونه‌های زیر، نسبت شمار جفت الکترون‌های پیوندی به شمار الکترون‌های ناپیوندی، برابر $\\frac{1}{2}$ است؟\n\n*کربن دی سولفید *فسفر پنتکلرید *هیدروژن سیانید *گوگرد دی اکسید', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5790, '۵۴- در هر واحد فرمولی از آمونیوم دی‌کرومات با رعایت قاعده هشت‌تایی، در مجموع، چه تعداد پیوند اشتراکی وجود دارد؟ (ساختار یون دی‌کرومات بصورت داده شده است.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5791, '۵۵- چند گرم گاز اکسیژن بر اثر جذب کامل گاز کربن دی‌اکسید موجود در $\\frac{2}{5}$ لیتر از یک نمونه هوا توسط Na$_2$O$_2$ طبق واکنش موازنه نشده، تولید می‌شود؟ (O = 16 ، C = 12 g·mol$^{-1}$) (در هر دسی‌لیتر از این نمونه هوا، $4/4\\times10^{-3}$ گرم کربن دی‌اکسید وجود دارد.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5792, '۵۶- حجم یک نمونه گاز تک اتمی در دمای .......... درجه سلسیوس برابر ۲ لیتر است. همین نمونه گاز در فشار ثابت و دمای ۸۵۰ کلوین، حجمی برابر ۲۷۵۰ میلی‌لیتر را اشغال می‌کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
