(5795, '۵۹- در واکنش (موازنه شود) $B_2O_3(s) + Cl_2(g) \\xrightarrow{\\Delta} BCl_3(l) + O_2(g)$ ، به ازای مصرف چند کیلوگرم ماده جامد، $67.2$ لیتر گاز اکسیژن در شرایط استاندارد تولید می‌شود؟ $(B=11,\\ O=16\\ :\\ g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5796, '۶۰- بر اثر استفاده از خودرویی که به طور میانگین سالانه مسافتی حدود ۲۲۰۰۰ کیلومتر طی می‌کند، سالانه به تقریب چند کیلوگرم $CO_2(g)$ وارد هواکره می‌شود؟ برچسب آلودگی این خودرو، ۱۲۰ گرم کربن دی‌اکسید به ازای طی یک کیلومتر است. $(O=16,\\ C=12\\ :\\ g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5797, '۶۱- در ارتفاعات بالای هواکره، کدام گونه وجود ندارد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5798, '۶۲- نام یا فرمول شیمیایی درست ترکیبات زیر به ترتیب از راست به چپ کدام است؟\n\n* دی نیتروژن تترا اکسید * کروم (VI) اکسید * $MnO_۳$ * $AlH_۳$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5799, '۶۳- در ساختار لوویس زیر با رعایت قاعده هشت‌تایی، شمار جفت الکترون‌های ناپیوندی، کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5800, '۶۴- مجموع ضرایب استوکیومتری در کدام دو معادله پس از موازنه، برابر است؟\n\nآ) $KMnO_4 + H_2C_2O_4 + H_2SO_4 \\rightarrow MnSO_4 + H_2O + CO_2 + K_2SO_4$\n\nب) $Ca_3N_2 + H_2O \\rightarrow Ca(OH)_2 + NH_3$\n\nپ) $NH_3 + O_2 \\rightarrow N_2 + H_2O$\n\nت) $C_{10}H_{20} + O_2 \\rightarrow CO + H_2O$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5801, '۶۵- چه تعداد از ویژگی‌های زیر، در اوزون نسبت به اکسیژن، بیشتر است؟ قطبیت مولکول * شدت رنگ در حالت مایع * واکنش‌پذیری * انحلال‌پذیری در آب * شمار جفت الکترون‌های ناپیوندی در ساختار لوویس', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5802, '۶۶- کدام موارد از مطالب زیر درباره گاز کربن مونوکسید، درست هستند؟ آ) میل ترکیبی هموگلوبین خون با آن بسیار زیاد و بیش از ۲۰ برابر اکسیژن است. ب) بی‌رنگ، بسیار سمی و دارای بویی بسیار اندک است. پ) چگالی آن کمتر از هوا و قابلیت انتشار آن در محیط بسیار زیاد است. ت) در ساختار الکترون - نقطه‌ای آن همانند گاز نیتروژن، سه جفت الکترون پیوندی وجود دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5803, '۶۷- مخلوطی از $NO(g)$ و $NO_2(g)$ جرمی معادل $80\\ g$ دارد. اگر برای تبدیل کامل نیتروژن مونوکسید به $NO_2$ ، $11.2\\ L$ گاز اکسیژن لازم باشد، درصد حجمی $NO$ در مخلوط، به تقریب کدام است؟ (شرایط را استاندارد در نظر بگیرید. معادله موازنه شود: $NO(g)+O_2(g)\\rightarrow NO_2(g)$ ، $(O=16,\\ N=14\\ :\\ g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5804, '۶۸- اگر درصد حجمی گاز هلیم در هوا در شرایط $STP$ ، $0/0005\\%$ باشد، در هر مترمکعب هوا، به تقریب چند اتم هلیم و چند لیتر از آن وجود دارد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5805, '۶۹- مجموع ضرایب واکنش‌دهنده‌ها در واکنش زیر، پس از موازنه، کدام است؟ کربن مونوکسید + فسفر $(P_4)$ + $CaSiO_3$ → کربن + سیلیسیم دی‌اکسید + کلسیم فسفات', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5806, '۷۰- با حل شدن $0/01$ مول از کدام ترکیب، $pH$ آب خالص $(5/5\\ لیتر)$ بیشتر جابه‌جا می‌شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
