(5815, '۷۹- نسبت ضریب استوکیومتری $H_2O$ در معادله موازنه شده (I) به (II)، کدام است؟<br>(I) $V_2O_5 + H_2 \\rightarrow V_2O_3 + H_2O$<br>(II) $C_5H_{11}NH_2 + O_2 \\rightarrow CO_2 + H_2O + NO_2$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5816, '۸۰- چه تعداد از مطالب زیر، درست‌اند؟\n\n● ۲۲ گرم گاز کربن دی‌اکسید در شرایط استاندارد، حجمی معادل ۱۱/۲ لیتر را اشغال می‌کند. (O=16, C=12 : g.mol^-1)\n\n● طبق قانون آووگادرو، یک مول از گازهای مختلف در دما و فشار ثابت، حجم ثابت و برابری دارند.\n\n● با افزایش فشار ۱۲ لیتر گاز آرگون از ۳ اتمسفر به ۴ اتمسفر در دمای ثابت، حجم گاز ۲۵ درصد کاهش می‌یابد.\n\n● برای یافتن رابطه بین حجم و مقدار یک نمونه گاز، باید دما و فشار ثابت باشد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, NULL, NULL, 'free'),
(5817, '۸۱- مطالب زیر درباره هلیم درست هستند، به جز:', 1, 3, 66, 314, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, '2026-09-14 19:22:15', 3, 'free'),
(5818, '۸۲- کدامیک از موارد زیر، درست هستند؟\n\nالف) هنگامی که تابش فرابنفش به مولکول اوزون می‌رسد، پیوند اشتراکی بین دو تا اتم اکسیژن می‌شکند.\n\nب) اوزون تروپوسفری یک ماده آلاینده سمی و خطرناک است.\n\nپ) شدت رنگ اوزون مایع از اکسیژن مایع، بیشتر است.\n\nت) واکنش‌پذیری و نقطه جوش گاز اوزون از گاز اکسیژن، بیشتر است.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, '2026-09-14 19:24:44', 3, 'free'),
(5819, '۸۳- از مخلوط کردن یک لیتر محلول هیدروکلریک اسید ۵ مولار با مقدار کافی از یک محلول مایع سفیدکننده (NaClO)، چند لیتر گاز در شرایط استاندارد تولید می‌شود؟\n\n(HCl(aq)+NaClO(aq) → NaCl(aq)+Cl_2(g)+H_2O(l) : معادله موازنه شود)', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, '2026-09-14 19:25:13', 3, 'free'),
(5820, '۸۴- از واکنش ۱/۶ لیتر گاز آمونیاک با HCl کافی طبق واکنش: NH_3(g)+HCl(g)→NH_4Cl(s)، ۴/۲۸ گرم گرد سفید آمونیوم کلرید به دست آمده است. چگالی گاز آمونیاک در شرایط آزمایش، چند گرم بر لیتر است؟\n\n(Cl=35/5, N=14, H=1 : g.mol^-1)', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:19', 1, '2026-09-14 19:25:38', 3, 'free'),
