(5831, '11- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:27:23', 3, 'free'),
(5832, '12- چه تعداد از عبارت‌های زیر در ارتباط با اوزون درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5833, '13- برای تولید هر مول اوزون تروپوسفری به چند مول گاز نیتروژن نیاز است؟ (فرض کنید هیچ‌کدام از اکسیدهای نیتروژن در لایه تروپوسفر وجود ندارند.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5834, '14- در شرایطی که چگالی گاز آمونیاک $0.68\\ g.L^{-1}$ است، $750\\ \\text{cm}^3$ از گاز $XO_2$ جرمی معادل $4.92$ گرم دارد. جرم مولی X چند گرم بر مول است؟ $(O=16 , N=14 , H=1\\ g.mol^{-1})$', 1, 3, 66, 315, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:28:10', 3, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5835, '15- در هر کدام از گزینه‌های زیر، جایگاه یک عنصر در جدول دوره‌ای آورده شده که مولکول دو اتمی آن در دما و فشار اتاق به حالت گازی یافت می‌شود. یک گرم از کدامیک از آن‌ها در شرایط یکسان، حجم بیشتری را اشغال می‌کند؟', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:28:40', 3, 'free'),
(5836, '16- در واکنش تجزیه پتاسیم پرمنگنات در یک ظرف سرباز، در یک بازه زمانی معین حجم گاز اکسیژن در شرایط استاندارد از mL1342 به 2238 mL رسیده است. در همین مدت، جرم مواد موجود در ظرف چند گرم کاهش یافته است؟ $(K=39 , Mn=55 , O=16\\ g.mol^{-1})$ (واکنش موازنه شده نیست.) $KMnO_4(s)\\xrightarrow{\\Delta}K_2MnO_4(s)+MnO_2(s)+O_2(g)$', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:30:18', 3, 'free'),
(5837, '17- $m$ گرم گاز اکسیژن و $m$ گرم گاز نیتروژن را در شرایط STP وارد یک ظرف سربسته می‌کنیم. پس از گذشت $5$ ساعت، حجم گازهای درون ظرف برابر 840 L اندازه‌گیری شده است. $m$ کدام است؟ (در طول $5$ ساعت، دما و فشار ثابت است.) $(O=16 , N=14\\ g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5838, '18- کدامیک از مطالب زیر درست است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:35:10', 3, 'free'),
(5839, '19- مجموع ضرایب استوکیومتری اجزای واکنش پس از موازنه کدام است؟ $N_2O_4+KI\\rightarrow KNO_3+NO+I_2$', 1, 3, 66, 315, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:35:36', 3, 'free'),
(5840, '20- از بین گازهای زیر کدامیک به مقدار کمتری در لایه تروپوسفر وجود دارد؟', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-14 19:35:57', 3, 'free'),
(5841, '21- مقایسه میان نسبت شمار الکترون‌های ناپیوندی به الکترون‌های پیوندی سه گونه $(a)\\,N_2O_4$ و $(b)\\,C_2F_2$ و $(c)\\,C_2O_4^{2-}$، به کدام صورت درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5842, '22- یک گرم از هر یک از گازهای کربن دی‌اکسید، کربن مونوکسید، اکسیژن و نیتروژن را در دمای 25°C در چهار بادکنک وارد کرده و سپس آن‌ها را تا دمای -90°C سرد می‌کنیم. کدامیک از بادکنک‌ها از نظر کاهش حجم، شباهت بیشتری با بادکنک حاوی دی‌نیتروژن مونوکسید دارد؟ (C = 12 , N = 14 , O = 16 g.mol$^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5843, '23 - چه تعداد از عبارت‌های زیر درست است؟\n\n• کربن مونوکسید، گازی بی‌رنگ، بدبو و بسیار سمی است.\n\n• با افزایش مقدار کربن دی‌اکسید محلول در آب و کاهش pH ، اسکلت آهکی مرجان‌ها از بین می‌رود.\n\n• نخستین فلز دوره سوم با شعله زردرنگ و دومین فلز این دوره با شعله سفیدرنگ می‌سوزد.\n\n• آثار زیان‌بار باران اسیدی بر روی پوست، دستگاه تنفس و چشم‌ها به سرعت قابل تشخیص است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5844, '24- اگر درصد جرمی عنصر X در اکسیدی از آن با فرمول $X_2O_3$ برابر با $36.8$ باشد، درصد جرمی X در اکسید $X_2O$ کدام است؟ (O = 16 g.mol$^{-1}$)', 1, 3, 66, 315, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-06 19:48:20', 3, 'free'),
(5845, '25 - چه تعداد از عبارت‌های زیر نادرست است؟\n\n• رنگ نقره سولفید به نقره شباهت بیشتری دارد تا به سولفور (گوگرد).\n\n• با مصرف غذا و استفاده از وسایل الکتریکی، مقداری کربن دی‌اکسید وارد هواکره می‌شود.\n\n• اگر از باد به عنوان منبع تولید برق استفاده شود، هیچ‌گونه کربن دی‌اکسیدی وارد هواکره نمی‌شود.\n\n• بخش عمده‌ای از پرتوهای خورشیدی که به سمت زمین تابیده می‌شود به وسیلهٔ هواکره جذب می‌شود.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-06 19:49:29', 3, 'free'),
(5846, '27- در هوای پاک و خشک لایهٔ تروپوسفر، درصد حجمی کدام دو گاز تفاوت بیشتری با هم دارند؟', 1, 3, 66, 314, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-09-06 19:50:09', 3, 'free'),
(5847, '28- کدامیک از گزینه‌های زیر با بقیه هم‌خوانی ندارد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5848, '29 - نمونه‌ای از هوای مایع با دمای $-200^\\circ C$ تهیه شده است که شامل سه گاز اصلی است. اگر به تدریج دمای هوای مایع را افزایش دهیم ابتدا گاز A ، سپس گاز X و در نهایت گاز D جدا می‌شود. چه تعداد از عبارت‌های زیر درست است؟\n\n• فراوانی گاز A در هواکره بیشتر از دو گاز دیگر است.\n\n• فراوانی گاز X در هواکره کم‌تر از دو گاز دیگر است.\n\n• مقایسه میان واکنش‌پذیری آن‌ها به صورت $X < A < D$ است.\n\n• تفاوت نقطهٔ جوش گاز X با گاز D ، کم‌تر از تفاوت نقطهٔ جوش X با A است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5849, '30 - چه تعداد از عبارت‌های زیر درست است؟\n\n• یکی از دلایل لایه‌ای بودن هواکره، روند تغییر فشار در آن است.\n\n• در لایه‌های بالایی هواکره اکسیژن به شکل اتمی و نیز به شکل یون‌های تک‌اتمی و چنداتمی یافت می‌شود.\n\n• برای نگه‌داری نمونه‌های بیولوژیک در پزشکی از گاز نیتروژن استفاده می‌شود.\n\n• از 200 میلیون سال پیش تاکنون، نسبت گازهای سازندهٔ هواکره تقریباً ثابت مانده است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5850, '31 - بر اثر تجزیه کامل 8 گرم کلسیم کربنات ($CaCO_3$)،$4.816 \\times 10^{22}$مولکول کربن دی‌اکسید و مقداری آهک به دست آمده است. شمار یون‌های موجود در آهک تولیدشده کدام است؟ ($Ca=40, C=12, O=16: g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5851, '32 - چه تعداد از عبارت‌های زیر درست است؟\n\n• سنگ‌های متخلخل در زیرزمین، میدان‌های فعال گاز و چاه‌های نفت جاهای مناسبی برای دفن گاز $CO_2$ هستند.\n\n• اوزون در مقایسه با اکسیژن واکنش‌پذیرتر بوده و نقطه جوش بالاتری دارد.\n\n• اتانول و روغن‌های گیاهی نمونه‌هایی از سوخت سبز هستند.\n\n• در یک روز زمستانی که حداقل و حداکثر دمای محیط برابر با $$1.5^\\circ C و $$8^\\circ C است، دمای میانگین درون گلخانه باید در حدود $$20^\\circ C باشد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5852, '33 - در کدام‌یک از واکنش‌های زیر پس از موازنه، ضریب یا مجموع ضریب‌های عنصر به حالت آزاد بزرگ‌تر است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5853, '34 - عنصرهای D ، X ، A و E در آخرین زیرلایه اتم خود به ترتیب 2، 3، 4 و 5 الکترون دارند. اگر نوع زیرلایه‌ها یکسان باشد، برای نام‌گذاری ترکیب حاصل از کدام دو عنصر از پیشوند «تری» استفاده می‌شود؟ (هر چهار عنصر در دوره سوم جدول دوره‌ای جای دارند.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5854, '35 - چه تعداد از عبارت‌های زیر درست است؟\n\n• در صنعت برای تبدیل $CO_2$ به مواد معدنی، این گاز را با $MgO$ یا $CaO$ واکنش می‌دهند.\n\n• تفاوت رفتار اوزون و اکسیژن را می‌توان به تفاوت ساختار این دو ماده نسبت داد.\n\n• هنگامی که پرتوهای خورشیدی به سطح زمین تابیده می‌شود، بخش عمده آن به وسیلهٔ زمین و بقیهٔ آن به وسیلهٔ هواکره جذب می‌شود.\n\n• در سده گذشته به طور کلی مساحت برف در نیمکره شمالی و میانگین جهانی سطح آب‌های آزاد به ترتیب کاهش و افزایش یافته‌اند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5855, '36 - اگر در هر کدام از یون‌های زیر، تمامی اتم‌ها قاعده هشت‌تایی را رعایت کنند، تفاوت بار الکتریکی دو یون کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5856, '37 - چه تعداد از عبارت‌های زیر در ارتباط با هیدروژن درست است؟\n\n• با این‌که تولید گاز هیدروژن صرفه اقتصادی ندارد برخی از کشورها برای تولید آن، سرمایه‌گذاری هنگفتی می‌کنند.\n\n• هیدروژن فراوان‌ترین عنصر در زمین است که به شکل ترکیب‌های گوناگون یافت می‌شود.\n\n• بر اثر سوختن آن، گاز گلخانه‌ای تولید می‌شود.\n\n• مانند سوخت‌های فسیلی می‌تواند با اکسیژن بسوزد و نور و گرما تولید کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5857, '38- چه تعداد از عبارت‌های زیر در ارتباط با واکنش  که در لایه اوزون انجام می‌شود، درست است؟\n\nمقدار انرژی مصرف شده در جهت (1) بیشتر از مقدار انرژی آزاد شده در جهت (2) است.\n\nبا انجام واکنش در جهت (1)، اکسیژن اتمی ابتدا تولید و سپس مصرف می‌شود.\n\nدر جهت (1)، پرتوهایی با طول موج کمتر از $ $400 nm و در جهت (2) پرتوهایی با طول موج بیشتر از  700nm مصرف می‌شود.\n\nعامل طبیعی انجام واکنش در جهت (1)، رعد و برق است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5858, '39 - چه تعداد از عبارت‌های زیر در ارتباط با پلاستیک‌های سبز درست است؟\n\n• دست‌کم از سه عنصر تشکیل شده‌اند.\n\n• همانند پلاستیک‌های معمولی (با پایهٔ نفتی) جزو پلیمرها طبقه‌بندی می‌شوند.\n\n• تمامی آن‌ها از نشاسته ساخته می‌شوند.\n\n• در مدت‌زمان نسبتاً کوتاهی با تجزیه به عنصرهای سازنده به طبیعت بازمی‌گردند.\n\n• به عنوان کیسهٔ زباله و برای بسته‌بندی مواد خوراکی می‌توان از آن‌ها استفاده کرد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5859, '40 - تبدیل گاز نیتروژن به اوزون تروپوسفری طی سه مرحله انجام می‌شود. چه تعداد از عبارت‌های زیر در ارتباط با این سه مرحله درست است؟\n\n• گاز اکسیژن در مرحله‌های دوم و سوم مصرف می‌شود.\n\n• به‌ازای مصرف هر مول گاز نیتروژن، 2 مول اوزون تروپوسفری تولید می‌شود.\n\n• به‌ازای تولید هر مول اوزون تروپوسفری، 2 مول گاز اکسیژن مصرف می‌شود.\n\n• گاز قهوه‌ای‌رنگ نیتروژن دی‌اکسید در یک مرحله تولید و بلافاصله در مرحلهٔ بعد، مصرف می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5860, '41 - مخلوطی از دو ترکیب کربن مونوکسید و کربن دی‌اکسید به جرم 1.08 گرم درون یک ظرف قرار دارند. با اکسایش کامل کربن مونوکسید درون ظرف، تنها ترکیب درون ظرف، کربن دی‌اکسید به جرم 1.38گرم خواهد بود. نسبت مولی گاز سنگین‌تر به گاز سبک‌تر در مخلوط اولیه کدام است؟ ($C=12, O=16: g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5861, '42 - دی‌برمید عنصر X در حضور گاز کلر به طور کامل به دی‌کلرید تبدیل می‌شود. وقتی 31.80گرم از $XBr_2$ واکنش می‌دهد، 18.45گرم $XCl_2$ تولید می‌شود. جرم مولی X چند گرم بر مول است؟ ($Br=80, Cl=35/5: g.mol^{-1}$)\n\n$XBr_2 + Cl_2 \\rightarrow XCl_2 + Br_2$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5862, '43 - چه تعداد از عبارت‌های زیر درست است؟ ($C=12, O=16, N=14: g.mol^{-1}$)\n\n• بزرگ‌ترین چالش هابر در فرایند تهیهٔ آمونیاک، پیدا کردن کاتالیزگر مناسب برای انجام واکنش بود.\n\n• فراوان‌ترین جزء سازندهٔ هواکره در مقایسه با اکسیژن از نظر شیمیایی غیرفعال و واکنش‌ناپذیر است.\n\n• هر یک از فرایندهای تهیهٔ $H_2SO_4$ و $HNO_3$ ، شامل چندین واکنش گازی متوالی است.\n\n• در دما و فشار ثابت، چگالی گازهای کربن مونوکسید و نیتروژن با هم برابر است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5863, '44 - فلزهای قلیایی (گروه اول) در حضور آب واکنش شیمیایی زیر را انجام می‌دهند:\n\n$2M(s) + 2H_2O(l) \\rightarrow 2MOH(aq) + H_2(g)$\n\nدر شرایط معین از واکنش 3.56 گرم پتاسیم با آب 1.94 لیتر گاز هیدروژن تولید شده است. تحت همان شرایط 8.4گرم از یک فلز قلیایی دیگر، 1342 میلی‌لیتر گاز هیدروژن تولید کرده است. جرم مولی فلز قلیایی مورد نظر چند گرم بر مول است؟ ($K=39g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5864, '45- در ساختار یون زیر، تمام اتم‌ها قاعده هشت‌تایی را رعایت کرده‌اند و بار الکتریکی یون(q) برابر با جمع جبری بار الکتریکی یون‌های فسفات، کربنات و نیترات است. اتم X به کدام گروه جدول دوره‌ای تعلق دارد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5865, '46- تمام کربن موجود در نمونه‌ای از پتاسیم کربنات به جرم 20.7 گرم به وسیله فرایندهایی به $K_2Zn_3[Fe(CN)_6]_2$ تبدیل شده است. جرم فرآورده تولیدشده چند گرم است؟ $(K=39,\\ Fe=56,\\ C=12,\\ N=14,\\ O=16,\\ Zn=65\\ g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5866, '47 - پس از موازنه با کوچک‌ترین اعداد صحیح، نسبت ضریب آمونیاک در واکنش (I) به ضریب این ماده، در واکنش (II) کدام است؟\n\nI) $N_2H_4 + NaOCl \\rightarrow NaCl + N_2 + NH_3 + H_2O$\n\nII) $(NH_4)_2SiF_6 + NH_3 + 2H_2O \\rightarrow SiO_2 + NH_4F$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5867, '48 - در چه تعداد از گونه‌های زیر تمامی پیوندها یگانه (ساده) است؟ ($Se_{34}$)\n\n$NOF_3$ •        $SeO_3^{2-}$ •        $Cl_2O$ •        $ClO_3^-$ •', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5868, '49 - چه تعداد از عبارت‌های زیر درست است؟\n\n• از دیدگاه اقتصادی استفاده از گاز طبیعی به عنوان سوخت در مقایسه با زغال‌سنگ، یک مزیت محسوب می‌شود.\n\n• حجم مولی گازها می‌تواند در دما و فشاری غیر از شرایط STP نیز $$22.4 L.mol^{-1} باشد.\n\n• به طور معمول اکسیدهای بازی جزو ترکیب‌های یونی هستند.\n\n• در بین گازهایی که از تقطیر جزء به جزء هوای مایع ($-200^\\circ C$) به دست می‌آید، ارزش اقتصادی هر لیتر از گازی که در انتها جدا می‌شود بیشتر است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5869, '50 - چه تعداد از عبارت‌های زیر درست است؟\n\n• فراوان‌ترین ترکیب سازنده هوای پاک و خشک در لایه تروپوسفر، یک گاز با مولکول‌های دو اتمی است.\n\n• فشار گاز اکسیژن در سطح زمین برابر atm 1 بوده و با افزایش ارتفاع، کاهش می‌یابد.\n\n• برای کنترل میزان اسیدی بودن آب دریاچه‌ها و افزایش بهره‌وری در کشاورزی از سنگ آهک استفاده می‌شود.\n\n• در برخی ترکیب‌های دارای کروم این فلز به شکل‌هایی غیر از کاتیون $Cr^{+2}$ یا $Cr^{+3}$ وجود دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5870, '51 - اگر در مخلوطی از گازهای اوزون و نیتروژن، درصد حجمی گاز سنگین‌تر 60 درصد باشد، چگالی این مخلوط گازی در شرایط STP چند گرم بر لیتر است؟ ($N=14, O=16: g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5871, '52 - چه تعداد از عبارت‌های زیر در ارتباط با فرایند هابر نادرست است؟\n\n• هابر واکنش میان گازهای $N_2$ و $H_2$ را بارها در دماها و فشارهای گوناگون انجام داد تا بتواند شرایط بهینه آن را پیدا کند.\n\n• برای جداسازی آمونیاک ابتدا مخلوط واکنش را تا دمای معینی سرد کرده، سپس به آرامی آن را گرم می‌کنند.\n\n• ترتیب نقطه جوش اجزای واکنش مورد نظر مشابه جرم مولی آن‌ها است.\n\n• یکی از چالش‌های این فرایند این بود که در دما و فشار بالا واکنش مورد نظر انجام نمی‌شد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5872, '53 - با توجه به شکل‌های داده‌شده، نقطه جوش سه ماده X ، Y و Z برحسب درجه سلسیوس به ترتیب کدام می‌تواند باشد؟ (گزینه‌ها را از راست به چپ بخوانید.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5873, '54 - در ساختار لوویس چه تعداد از گونه‌های زیر فقط یک پیوند دوگانه وجود دارد؟\n\n$NOCl, NO_3^-, NO_2^-, SO_3^{2-}, SOF_2, SCO$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5874, '55 - مجموع ضرایب اجزای واکنش زیر، پس از موازنه با کوچک‌ترین اعداد صحیح، کدام است؟\n\n$Ca_5(PO_4)_3F + H_2SO_4 \\rightarrow HF + CaSO_4 + Ca(H_2PO_4)_2$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5875, '56 - در شرایطی که چگالی گاز کربن دی‌اکسید $ $1.76 g.L^{-1} است، 800 سانتی‌متر مکعب از گاز $X_2O_3$، جرمی معادل 2.304 گرم دارد. جرم مولی X چند گرم بر مول است؟ ($C=12, O=16: g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5876, '57 - اگر مخلوطی شامل گازهای آرگون، نیتروژن، هلیم، اکسیژن، کربن دی‌اکسید و بخار آب را تا دمای $^\\circ $-230C سرد کنیم، شمار گونه‌های جامد و مایع در نمونه نهایی در کدام گزینه به درستی آمده است؟ (گزینه‌ها را به ترتیب از راست به چپ بخوانید.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5877, '58 - چه تعداد از عبارت‌های زیر درست است؟\n\n• هلیم گازی بی‌رنگ و بی‌بو است که در جوشکاری و کپسول غواصی به کار می‌رود.\n\n• در لایه تروپوسفر برخلاف لایه بعدی (استراتوسفر)، با افزایش ارتفاع از سطح زمین، دما کاهش می‌یابد.\n\n• مطالعات نشان می‌دهد که از 200 میلیون سال پیش تا کنون، نسبت گازهای سازنده هواکره هیچ گونه تغییری نکرده است.\n\n• اگر نمونه‌ای از هوا را آنقدر سرد کنیم که هوای مایع به دست آید، برخی از اجزای آن به صورت جامد جدا می‌شوند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5878, '59 - درصد فراوانی کدام‌یک از گازهای نجیب زیر در هوای پاک و خشک لایه تروپوسفر کم‌تر است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5879, '60 - نام چند ترکیب شیمیایی زیر با فرمول آن مطابقت دارد؟\n\n• $N_2O$ : دی‌نیتروژن اکسید\n\n• $Co_3N_2$ : کبالت (II) نیترید\n\n• $ZnO$ : روی (II) اکسید\n\n• $CrCl_3$ : کروم (III) کلرید\n\n• $SiBr_4$ : سیلیسیم تترا برم', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5880, '61 - در واکنش........... a واکنش b ، پس از موازنه، مجموع ضرایب فراورده‌ها ........... مجموع ضرایب واکنش‌دهنده‌هاست.\n\na) $Si_2H_6 + KOH + H_2O \\rightarrow K_2SiO_3 + H_2$\n\nb) $SO_2 + NaClO_3 + H_2SO_4 \\rightarrow ClO_2 + NaHSO_4$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5881, '62 - در ساختار لوویس چه تعداد از گونه‌های زیر تمامی پیوندها به صورت یگانه است؟\n\n• $SO_3^{2-}$\n\n• $HClO_4$\n\n• $NOCl$\n\n• $PO_4^{3-}$\n\n• $SOCl_2$\n\n• $H_2SO_4$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5882, '63 - استفاده از ........... به عنوان سوخت در مقایسه با ........... با توجه به ........... یک مزیت محسوب می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5883, '64 - کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5884, '65 - چه تعداد از عبارت‌های زیر درست است؟\n\n• دلیل وجود اکسیژن در ساختار پلاستیک‌های سبز این است که از مواد گیاهی مانند نشاسته ساخته می‌شوند.\n\n• در ساختار سوخت سبز سه عنصر C ، H و O وجود دارد و این مواد اولیه به وسیله جانداران ذره‌بینی به عنصرهای سازنده خود تجزیه می‌شوند.\n\n• بخش عمده‌ای از پرتوهای خورشیدی که به زمین تابیده می‌شود به وسیله زمین جذب شده و بخش کوچکی نیز توسط هواکره جذب می‌شود.\n\n• لایه هواکره از گرم شدن کره زمین جلوگیری کرده و سرعت گرمایش جهانی را کاهش می‌دهد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5885, '66 - چه تعداد از عبارت‌های زیر نادرست است؟\n\n• بیشتر نافلزها و شمار کمی از فلزها قابلیت این را دارند که با گاز اکسیژن بسوزند.\n\n• منیزیم با شعله سفیدرنگ و گوگرد با شعله آبی‌رنگ می‌سوزد.\n\n• باران‌های اسیدی شامل اسیدهای $H_2SO_4$ و $HNO_3$ بوده و pH آن‌ها همانند باران معمولی کم‌تر از 7 است.\n\n• گوگرد در اثر سوختن به $SO_3$ تبدیل شده که این واکنش، مرحله نخست تهیه صنعتی سولفوریک اسید است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5886, '67 - چه تعداد از موارد پیشنهادشده جمله زیر را به درستی کامل می‌کنند؟\n\n«بین مقدار ........... موجود در هواکره و ........... ، رابطه ........... وجود دارد.»\n\n• بخار آب ـ دمای کره زمین ـ مستقیم\n\n• کربن دی‌اکسید ـ میانگین جهانی سطح آب‌های آزاد ـ مستقیم\n\n• کربن دی‌اکسید ـ مساحت برف در نیم‌کره شمالی ـ وارونه\n\n• کربن دی‌اکسید ـ pH آب دریاها و اقیانوس‌ها ـ وارونه', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5887, '68 - چه تعداد از عبارت‌های زیر در ارتباط با اوزون تروپوسفری و واکنش تولید آن در هوای آلوده و در حضور نور خورشید درست است؟\n\n• وجود اوزون تروپوسفری در هوایی که تنفس می‌کنیم سبب آسیب دیدن ریه‌ها و بیماری‌های عصبی می‌شود.\n\n• در واکنش تولید آن در هوای آلوده به‌ازای تولید یک مول اوزون، یک مول گاز اکسیژن مصرف می‌شود.\n\n• همراه با تولید اوزون تروپوسفری، مقداری گاز قهوه‌ای‌رنگ نیتروژن دی‌اکسید نیز تولید می‌شود.\n\n• نقطه آغاز تولید اوزون تروپوسفری، واکنش میان گازهای نیتروژن و اکسیژن درون موتور خودرو در دمای بالا است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5888, '69 - کدام مطالب زیر درست هستند؟\n\nآ) خواص و رفتار یک ماده ارتباطی با ساختار آن ماده ندارد.\n\nب) با وجود گازهای گلخانه‌ای، زمین بخش ناچیزی از گرمای جذب شده را می‌تواند به صورت تابش فروسرخ از دست بدهد.\n\nپ) تولید فراوان‌ترین عنصر در جهان و حمل و نقل و نگهداری آن بسیار پرهزینه است.\n\nت) برای تبدیل $CO_2$ به مواد معدنی، می‌توان از فراورده حاصل از سوختن فلزهای کلسیم و منیزیم استفاده کرد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5889, '70 - تمام آلومینیم موجود در نمونه‌ای از آلومینیم سولفات به جرم 10.26 گرم به وسیله فرایندهایی به $Na_3AlF_6$ تبدیل شده است. جرم فراورده به دست آمده چند گرم است؟ ($Al=27 , S=32 , O=16 , Na=23 , F=19 : g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5890, '71 - اغلب فلزها در حضور محلول هیدروکلریک اسید واکنش زیر را انجام می‌دهند:\n\nهیدروژن + کلرید فلز $\\rightarrow$ هیدروکلریک اسید + فلز\n\nدر شرایط معین از واکنش 0.84 گرم منیزیم با هیدروکلریک اسید، 1.05 لیتر گاز هیدروژن تولید شده است. تحت همان شرایط 1.68گرم از یک فلز دیگر که کاتیون مشابه منیزیم تشکیل می‌دهد، 450 میلی‌لیتر گاز هیدروژن تولید کرده است. جرم مولی فلز مورد نظر چند گرم بر مول است؟ ($Mg=24 g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5891, '72 - چه تعداد از عبارت‌های زیر درست است؟\n\n• اگر در دما و فشار ثابت، شمار مول‌های یک گاز دو برابر شود، حجم آن نیز دو برابر می‌شود.\n\n• واکنش میان گازهای نیتروژن و هیدروژن در دما و فشار اتاق، تنها در حضور کاتالیزگر یا جرقه انجام می‌شود.\n\n• ارزش اقتصادی هر لیتر گاز نیتروژن بیشتر از هر لیتر گاز آرگون است.\n\n• فرایند تهیه سولفوریک اسید شامل چندین واکنش گازی متوالی است که یکی از آن‌ها تبدیل گاز گوگرد تری‌اکسید به گوگرد دی‌اکسید است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5892, '73 - اگر نسبت شمار اتم‌های اکسیژن در سولفاتی از فلز آهن )ترکیب (X به شمار اتم‌های اکسیژن در نیتراتی از فلز مس )ترکیب (Y برابر با 2 باشد، نسبت شمار کاتیون‌های X به شمار آنیون‌های Y کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5893, '74 - چه تعداد از عبارت‌های زیر درست است؟\n\n• حتی در دمای -200 °C نیز برخی از اجزای هواکره هم‌چنان به حالت گاز هستند.\n\n• در ارتفاع‌های بالاتر از 100 کیلومتری از سطح زمین، گونه‌های O ، $O_2^+$ و $O^+$ وجود دارند.\n\n• گیاهان با بهره‌گیری از نور خورشید و مصرف کربن دی‌اکسید هواکره، اکسیژن مورد نیاز خود را تولید می‌کنند.\n\n• یافته‌های تجربی نشان می‌دهد که حدود 7 درصد جرمی از مخلوط گاز طبیعی را هلیم تشکیل می‌دهد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5894, '75 - چه تعداد از مطالب زیر در ارتباط با گازهای آرگون و هلیم درست‌اند؟\n\n• گازهای Ar و He به ترتیب نخستین و سومین گاز نجیب فراوان لایه تروپوسفر هستند.\n\n• نقطه جوش He پایین‌تر از نقطه جوش Arاست.\n\n• با این که در یک گروه از جدول دوره‌ای جای دارند اما شمار الکترون‌های ظرفیتی آن‌ها متفاوت است.\n\n• برای تهیه گازهای Ar و He به ترتیب تقطیر جزء به جزء هوای مایع و تقطیر جزء به جزء گاز طبیعی به روش‌های دیگر برتری دارد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5895, '76 - چه تعداد از موارد زیر جزو کاربردهای سبک‌ترین گاز نجیب به شمار می‌رود؟\n\n• پر کردن بالن‌های هواشناسی\n\n• جوشکاری\n\n• نگهداری نمونه‌های بیولوژیک در پزشکی\n\n• در کپسول غواصی\n\n• تمیز کردن قطعات الکترونیکی در دستگاه‌های تصویربرداری', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5896, '77 - از هوای مایع به ترتیب گازهای A ، B و C جدا می‌شود. چه تعداد از عبارت‌های زیر در ارتباط با آن‌ها درست است؟\n\n• فراوانی گاز A در لایه تروپوسفر، بیشتر از دو گاز دیگر است.\n\n• گازهای A و B در دو گروه متوالی از جدول دوره‌ای جای دارند.\n\n• واکنش‌پذیری گاز A از گاز C کم‌تر و از گاز B بیشتر است.\n\n• تفاوت نقطه جوش گازهای A و B ، کم‌تر از تفاوت نقطه جوش گازهای B و C است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5897, '78 - چه تعداد از عبارت‌های زیر درست است؟\n\n• گازهای $NO$ ، $NO_2$ و $C_xH_y$ جزو آلاینده‌هایی هستند که از اگزوز خودروها خارج می‌شوند.\n\n• پرتوهای خورشیدی پس از برخورد به زمین دوباره با انرژی کم‌تر به هواکره برمی‌گردند.\n\n• در 150 سال گذشته میانگین جهانی سطح آب‌های آزاد در حدود cm 200 افزایش یافته است.\n\n• سوزاندن یک گرم گاز طبیعی در مقایسه با یک گرم بنزین، گرمای بیشتری تولید می‌کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5898, '79 - هنگامی که پرتوهای خورشیدی به سمت زمین تابیده می‌شود، بخش عمده‌ای از این پرتوها به وسیله ........... جذب شده و مابقی به وسیله ...........', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5899, '80 - چه تعداد از عبارت‌های زیر در ارتباط با فلز منیزیم درست است؟\n\n• برای نام‌گذاری اکسید آن برخلاف اکسید فلز روی از اعداد رومی استفاده نمی‌شود.\n\n• با شعلۀ سفیدرنگ می‌سوزد.\n\n• در صورتی که اکسید آن را در آب حل کنیم، محلولی با خاصیت بازی به دست می‌آید و در دمای اتاق pH آن بزرگ‌تر از 7 است.\n\n• اکسید آن با گاز کربن دی‌اکسید واکنش داده و ترکیبی به دست می‌آید که فرمول شیمیایی آن شامل 5 اتم است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5900, '81 - چه تعداد از عبارت‌های زیر درست است؟\n\n• فرمول ترکیب دوتایی حاصل از Si و O همانند ترکیب دوتایی حاصل از Cr و Brمی‌تواند به صورت $A B_2$ یا $A_2 B$ باشد.\n\n• آثار زیان‌بار باران اسیدی بر روی پوست و دستگاه تنفس، برخلاف چشم‌ها به سرعت قابل تشخیص است.\n\n• گوگرد با شعله آبی رنگ می‌سوزد و به گوگرد دی‌اکسید تبدیل می‌شود.\n\n• یک گرم گاز کربن مونوکسید در مقایسه با یک گرم هوا، حجم بیشتری اشغال می‌کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5901, '82 - در واکنش زیر، ضریب استوکیومتری هیدروکسید پس از موازنه با کوچک‌ترین اعداد صحیح کدام است؟ (راهنمایی: برای موازنه واکنش‌های با ذره‌های باردار، مجموع بارهای الکتریکی در هر سمت باید با سمت دیگر برابر باشد.)\n\n$OH^- + FeHPO_4 + OCl^- \\rightarrow Fe(OH)_3 + PO_4^{3-} + Cl^- + H_2O$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5902, '83 - در کدام مولکول نسبت تعداد کل جفت الکترون‌های ناپیوندی لایهٔ ظرفیت همه اتم‌ها به تعداد کل جفت الکترون‌های پیوندی از بقیه کم‌تر است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5903, '84 - چه تعداد از مطالب زیر در ارتباط با اکسیدهای نیتروژن ($NO_x$) درست است؟\n\n• جایی که رعد و برق ایجاد می‌شود، دما به اندازه‌ای بالا است که این ترکیب‌ها تشکیل می‌شوند.\n\n• در فرایند تشکیل اوزون تروپوسفری، اکسید سنگین‌تر نیتروژن به اکسید سبک‌تر آن تبدیل می‌شود.\n\n• هوای آلوده کلان شهرها اغلب به دلیل وجود هر کدام از این اکسیدها به رنگ قهوه‌ای روشن دیده می‌شود.\n\n• در ساختار لوییس هیچ‌کدام از این دو ترکیب، اتم نیتروژن قاعده هشتایی را رعایت نمی‌کند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5904, '85 - چه تعداد از عبارت‌های زیر درست است؟\n\n• گاز آلایندهٔ گوگرد دی‌اکسید منشأ طبیعی نداشته و تنها در نتیجهٔ فعالیت‌های صنعتی وارد هواکره می‌شود.\n\n• در ساختار پلاستیک‌های سبز، علاوه بر کربن و هیدروژن، عنصرهای اکسیژن و نیتروژن نیز وجود دارند.\n\n• هنگامی که به شکر گرما داده می‌شود، دچار تغییر فیزیکی شده و رنگ آن تغییر می‌کند.\n\n• سوختن، واکنش شیمیایی است که در آن، یک ماده با اکسیژن به سرعت واکنش می‌دهد و بخشی از انرژی شیمیایی آن به صورت گرما و نور آزاد می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5905, '86 - چه تعداد از موارد زیر در راستای توسعهٔ پایدار بوده و جزو اهداف شیمی سبز است؟\n\n• سرمایه‌گذاری هنگفت برای تولید فراوان‌ترین عنصر جهان\n\n• تولید پلاستیک‌های زیست تخریب‌پذیر\n\n• اختصاص بخش‌های وسیعی از زمین‌های کشاورزی برای کشت سویا\n\n• تبدیل فراوان‌ترین ترکیب موجود در هوای پاک و خشک لایه تروپوسفر به مواد معدنی', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5906, '87 - چه تعداد از عبارت‌های زیر در ارتباط با اوزون درست است؟\n\n• در دمای $$-160^{\\circ}C حالت فیزیکی آن متفاوت با حالت فیزیکی اکسیژن است.\n\n• در ساختار لوییس آن شمار جفت الکترون‌های ناپیوندی برابر با شمار الکترون‌های پیوندی آن است.\n\n• بخش قابل توجهی از اوزون تروپوسفری در طول روز تشکیل می‌شود.\n\n• مقدار آن در لایۀ تروپوسفر ناچیز، اما در لایۀ استراتوسفر غلظت آن بیشتر از گاز اکسیژن است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5907, ' چگالی مخلوطی از گازهای فلوئور و هلیم با درصدهای حجمی 20 و 80 درصد در دمای $$91°Cو فشار $$2.66 atmچند گرم بر لیتر خواهد بود؟ ($He=4, F=19 : g.mol^{-1}$)', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, '2026-03-22 17:45:44', 5, 'done'),
(5908, '89 - اگر سوخت اتومبیل را $C_8H_{18}$ با چگالی 0.7 گرم بر میلی‌لیتر در نظر بگیریم و مصرف متوسط سوخت 7 لیتر به ازای هر 100 کیلومتر باشد، در مسافت 300 کیلومتر چند کیلوگرم گاز $CO_2$ تولید می‌شود؟ ($C=12, H=1, O=16 : g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5909, '90 - جرم مخلوطی از گازهای هلیم و نئون در دما و فشار معین،20.0 گرم است. اگر به این مخلوط 40.0 گرم گاز نئون اضافه کنیم و دما و حجم را ثابت نگه داریم، فشار گاز دو برابر می‌شود. در مخلوط اولیه چند گرم نئون وجود دارد؟ ($He=4, Ne=20 : g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5910, '91 - چه تعداد از عبارت‌های زیر نادرست است؟\n\n• پلاستیک‌های سبز پلیمرهایی زیست تخریب‌پذیر هستند و بر پایهٔ موادی مانند اتانول و روغن‌های گیاهی ساخته شده‌اند.\n\n• فلز پلاتین کاتالیزگر مناسبی برای واکنش سوختن گاز هیدروژن است.\n\n• رنگ نقره سولفید بیشتر به رنگ نقره شباهت دارد تا رنگ گوگرد.\n\n• برای واکنش‌هایی که با آزادکردن گرما همراه هستند نیز نماد «$\\xrightarrow{\\Delta}$» می‌تواند به کار رود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5911, '92 - تفاوت ضریب اکسیژن در واکنش‌های زیر پس از موازنه با کوچک‌ترین اعداد صحیح کدام است؟\n\n$I) CH_4 + NH_3 + O_2 \\rightarrow HCN + H_2O$\n\n$II) Ni(CO)_4 + HNO_3 + O_2 \\rightarrow Ni(NO_3)_2 + CO_2 + H_2O$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5912, '93 - مخلوطی از گازهای NO وCO مطابق معادلۀ واکنش زیر با هم واکنش می‌دهند. اگر مجموع مول‌های مخلوط اولیه به اندازهٔ 5 مول کاهش یابد، چند مول گاز ارزان‌تر تولید شده است؟\n\n$CO(g) + NO(g) \\rightarrow CO_2(g) + N_2(g)$ (موازنه شود)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5913, '94 - در کدام مولکول تفاوت میان جفت الکترون‌های ناپیوندی لایهٔ ظرفیت همهٔ اتم‌ها با تعداد کل جفت الکترون‌های پیوندی، عدد بزرگ‌تری است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5914, '95 - برای تولید هر گرم اوزون تروپوسفری به چند میلی‌لیتر از اکسید قهوه‌ای‌رنگ نیتروژن (با فرض شرایط استاندارد) نیاز است؟ ($O=16g.mol^{-1}$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5915, '96- اکسید چه تعداد از عنصرهای زیر در صورتی که در آب حل شود، می‌تواند موجب کاهش $pH$ شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5916, '97- جرم دو لیتر گاز نیتروژن در شرایط $STP$ چند برابر جرم نیم‌لیتر گاز اکسیژن در دمای $$91° C و فشار $ atm 0.75\\, $ است؟ $(N=14 , O=16:g.mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:44', 1, NULL, NULL, 'free'),
(5917, '۱- کدام گزینه در مورد ترکیبی با بیشترین درصد حجمی در هوای پاک و خشک، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5918, '۲- کدام گزینه نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5919, '۳- کدام عبارت‌ها درست هستند؟\n\nالف) آهن، تنها فلزی است که در طبیعت بیش از یک نوع اکسید دارد.\n\nب) اکسیژن در زیست‌کره در ساختار همۀ مولکول‌های زیستی یافت می‌شود.\n\nپ) جداسازی هلیم از گاز طبیعی تاکنون انجام نشده است.\n\nت) در بین ۶ گاز فراوان‌تر هواکره، گازهای نجیب (کمیاب) وجود ندارند.\n\nث) هلیم، آرگون و کربن مونوکسید، گازهایی بی‌رنگ و بی‌بو هستند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5920, '۴- با توجه به قاعدۀ هشتایی، ساختار لوویس چه تعداد از گونه‌های شیمیایی زیر درست است؟\n\n الف $SO_3$ (، ب $HCN$(، پ $AsF_3$ (، ت $CO$(، ث $HNO_3$', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:52:08', 3, 'free'),
(5921, '۵- با توجه به اینکه در ساختار یون‌های زیر، همۀ اتم‌ها از قاعدۀ هشتایی پیروی می‌کنند، در کدام گزینه، اتم X دارای ۵ الکترون با عدد کوانتومی فرعی برابر با ۱ در لایۀ ظرفیت خود است؟', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:52:31', 3, 'free'),
(5922, '۶- در کدام واکنش پس از موازنۀ معادلۀ آن، ضریب استوکیومتری مادۀ عنصری (عنصر آزاد)، بزرگ‌تر است؟', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:52:50', 3, 'free'),
(5923, '۷- یک مول آسپارتام با ۱۶ مول گاز اکسیژن می‌سوزد و ۱۴ مول گاز کربن دی‌اکسید، 1 مول گاز نیتروژن و ۹ مول بخار آب تولید می‌کند. در هر مولکول آسپارتام، چند جفت الکترون ناپیوندی وجود دارد؟', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:53:15', 3, 'free'),
(5924, '۸- چند مورد از مطالب زیر، درست است؟\n\nالف) ردپای دی‌اکسید کربن  نشان می‌دهد در تولید یک محصول یا بر اثر انجام یک فعالیت، چه مقدار از این گاز تولید و وارد هواکره می‌شود.\n\n ب) در تولید برق به روش‌های گوناگون، کمترین ردپای کربن دی‌اکسید در استفاده از گرمای زمین است. \n\nپ) با افزایش ردپای کربن دی‌اکسید، مساحت برف در نیمکرۀ شمالی و میانگین دمای کرۀ زمین افزایش می‌یابد. \n\nت) با حذف اثر گلخانه‌ای بر روی زمین، دمای کرۀ زمین به میزان $18$^\\circ C$$ کاهش می‌یابد.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:53:52', 3, 'free'),
(5925, '۹- بر اساس جدول زیر، اگر در یک کارخانه امکان استفاده از سوخت‌های متفاوت باشد، به ازای مقدار معینی انرژی، هزینۀ به کار رفته ناشی از مصرف گاز طبیعی به تقریب چند برابر مصرف زغال سنگ است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5926, '۱۰- کدام مورد از مطالب زیر، درست است؟\n\nالف) نقطه جوش اوزون از نیتروژن، بیشتر است.\n\nب) دگرشکل‌ها، دارای فرمول ساختاری متفاوت و فرمول شیمیایی یکسان هستند.\n\nپ) هیدروژن، فراوان‌ترین عنصر در جهان است که اغلب به شکل آزاد یافت می‌شود.\n\nت) از واکنش یک اکسید نافلزی با یک اکسید فلزی، می‌توان ترکیب یونی به‌دست آورد.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:57:53', 3, 'free'),
(5927, '۱۱- در دما و فشار معین، ۵۰۰ سی‌سی گاز اوزون شامل $22^10\\times612/3$ اتم اکسیژن است. چگالی گاز اوزون در این دما و فشار چند$g \\cdot L^{-1}$ است؟\n\n$(O=۱۶ : g \\cdot mol^{-1})$', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:58:31', 3, 'free'),
(5928, '۱۲- ۲۰ گرم مخلوطی از کربن و گوگرد برای سوختن کامل به ۴۰ گرم گاز اکسیژن نیاز دارند. نسبت مولی کربن به گوگرد در مخلوط داده‌شده کدام است؟\n\n $(C=12,\\ O=16,\\ S=32\\ g\\cdot mol^{-1})$', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 19:59:59', 3, 'free'),
(5929, '۱۴- برای تبدیل کامل$8/44$  لیتر گاز $N_2$ در دمای $91^\\circ C$ و فشار $2atm$ به گاز آمونیاک، چند لیتر گاز هیدروژن با چگالی  g\\cdot L^{-1}$0/08$ لازم است؟ ($H=1 g\\cdot mol^{-1}$)', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:00:20', 3, 'free'),
(5930, '۱۵- چند مورد از مطالب زیر، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5931, '۱۶- در ساختار مولکول‌های کدام گزینه، شمار جفت الکترون‌های ناپیوندی متفاوت است؟', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:00:47', 3, 'free'),
(5932, '۱۷- پس از کامل کردن موازنۀ معادلۀ شیمیایی زیر، مقدار عددهای $a$ ، $b$و$x$ به ترتیب از راست به چپ، کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5933, '۱۹- برای مقایسه انرژی سوختی (گرمای آزادشده به ازای یک گرم) سوخت‌های بنزین، زغال‌سنگ، هیدروژن و گاز طبیعی، کدام عبارت درست است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:01:49', 3, 'free'),
(5934, '۲۰- چند مورد از مطالب زیر، درست است؟\n\nالف) به هر یک از شکل‌های مولکولی یا بلوری یک ترکیب، دگرشکل گفته می‌شود.\n\n ب) ملاحظات زیست محیطی، اجتماعی و اقتصادی،  رئوس  اصلی توسعۀ پایدار هستند.\n\nت) پخش عمدۀ پرتوهای فروسرخ گسیل شده از زمین، توسط گازهای گلخانه‌ای جذب می‌شود. \n\nپ) برای تبدیل $CO$ به مواد معدنی،می‌توان از اکسیدهای منیزیم و کلسیم استفاده کرد.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:02:42', 3, 'free'),
(5935, '۲۱- کدام نمونه گاز در فشار $2$ اتمسفر و دمای $30$ درجۀ سلسیوس، حجم کمتری اشغال می‌کند؟\n\n $(C=12, O=16, S=32 : g \\cdot mol^{-1})$', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:03:02', 3, 'free'),
(5936, '۲۲- با توجه به واکنش‌های زیر، نیتروژن مونوکسید تولیدشده در واکنش $6/5$لیتر گاز نیتروژن با مقدار کافی گاز اکسیژن (در شرایط استاندارد) را از واکنش چند گرم گاز نیتروژن دی‌اکسید با مقدار کافی آب می‌توان به‌دست آورد؟ (معادلۀ واکنش‌ها موازنه شود.) \n\n$(N=14, O=16 : g \\cdot mol^{-1})$ \n\n$N_2(g) + O_2(g) \\rightarrow NO(g)$ \n\n$NO_2(g) + H_2O(l) \\rightarrow HNO_3(aq) + NO(g)$', 1, 3, 66, 315, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:04:19', 3, 'free'),
(5937, '۲۳- یک انسان بالغ روزانه به تقریب $5/2$ مول گلوکز مصرف می‌کند. برای این منظور حجم هوای ورودی به ریۀ انسان در شرایط $STP$ چند لیتر است و اگر حجم هوای خروجی (بازدم) را به‌تقریب با حجم هوای ورودی به ریه (دم) یکسان در نظر بگیریم، درصد حجمی گاز اکسیژن در هوای خروجی کدام است؟ ($20$ درصد حجم هوا را گاز اکسیژن تشکیل می‌دهد و فرض کنید فقط $40$ درصد گاز اکسیژن ورودی در فرایند اکسایش گلوکز مصرف می‌شود.) $C_6H_{12}O_6(aq) + 6O_2(g) \\rightarrow 6CO_2(g) + 6H_2O(l)$', 1, 3, 66, 315, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:04:38', 3, 'free'),
(5938, '۲۴- چند مورد از مطالب داده شده، دربارۀ عنصرهای نشان‌داده‌شده در جدول زیر، درست است؟ \n\n- از میان آن‌ها، $4$ عنصر به دستۀ $p$ تعلق دارند.\n\n - در دما و فشار اتاق، عنصرهای «Z» و «W» به‌صورت مولکول‌های دو اتمی وجود دارند.\n\n - فرمول ترکیب هیدروژن‌دار عنصر «X» به‌صورت $H_2X$ است.\n\n - در دما و فشار اتاق، عنصر «E» گازی بی‌رنگ و سمّی است.', 1, 3, 66, 312, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:06:02', 3, 'free'),
(5939, '۲۵- کدام مطلب نادرست است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:06:49', 3, 'free'),
(5940, '۲۶- چند مورد از مطالب زیر دربارۀ گازی که بیشترین درصد حجمی را در هوای پاک و خشک دارد، درست است؟\n\n- ساختار مولکول آن به‌صورت $\\ddot{\\text{X}}=\\ddot{\\text{X}}$ است.\n\n- جانداران ذره‌بینی، این گاز را برای مصرف گیاهان در خاک تثبیت می‌کنند.\n\n- در $4/0$ مول از آن$23^10\\times816/4$  اتم وجود دارد.\n\n- یکی از کاربردهای آن، نگهداری نمونه‌های بیولوژیک در پزشکی است', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:13:11', 3, 'free'),
(5941, '۲۷- با توجه به جدول زیر، کدام موارد از مطالب داده‌شده درست است؟\n\nالف) نسبت شمار آنیون به کاتیون در ترکیب‌های (۱) و (۲) برابر با ۳ است.\n\nب) نام ترکیب (۴)، آهن سولفید و فرمول ترکیب (۳)، $SiBr_ 4$است.\n\nپ) در ترکیب (۲)، همۀ اتم‌ها به آرایش گاز نجیب دورۀ دوم جدول دوره‌ای رسیده‌اند.\n\nت) مجموع شمار اتم‌ها در فرمول شیمیایی ترکیب‌های (۱) و (۳) با مجموع شمار اتم‌ها در فرمول شیمیایی ترکیب‌های (۲) و (۴) برابر است', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5942, '- در ساختار لوویس آن، در مجموع ۱۴ الکترون پیوندی و ناپیوندی وجود دارد.\n\n- گازی بی‌رنگ، بی‌بو و سنگین‌تر از هوا است که سرعت انتشار آن در محیط زیاد است.\n\n- میل ترکیبی آن با هموگلوبین خون بیش از ۲۰۰ برابر اکسیژن است.\n\n- رنگ زرد شعلۀ سوختن سوخت‌های فسیلی می‌تواند دلیلی بر سوختن ناقص و تولید این گاز باشد.\n\n- شمار جفت الکترون‌های ناپیوندی در ساختار آن با شمار این جفت الکترون‌ها در ساختار کربن دی‌اکسید برابر است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5943, '۲۹- شمار یون‌ها در یک واحد فرمولی از ترکیب مس ($\\text{X}$) نیترید با شمار یون‌ها در یک واحد فرمولی از ترکیب کروم ($\\text{Y}$) سولفید برابر است. بر این اساس، حاصل $\\frac{\\text{Y}}{\\text{X}}$ و فرمول شیمیایی ترکیب نیکل ($\\text{X}$) فسفید کدام است؟', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:14:14', 3, 'free'),
(5944, '۳۴- کدام موارد از مطالب زیر، درست است؟ \n\nالف) افزایش میانگین جهانی دما، میانگین جهانی سطح آب‌های آزاد و مساحت برف در نیم‌کرۀ شمالی، از نتایج تشدید اثر گلخانه‌ای مربوط به افزایش مقدار گاز کربن دی‌اکسید در هواکره هستند. \n\nب) در نتیجۀ وجود اثر گلخانه‌ای در کرۀ زمین (در مقایسه با نبود آن)، تفاوت حداقل و حداکثر دمای شبانه‌روز، کاهش و میانگین دمای سطح زمین افزایش یافته است.\n\nپ) برخی از پرتوهای خورشیدی پس از ورود به هواکره و برخورد با سطح زمین، به‌صورت پرتوهایی با انرژی و طول موج کمتر، دوباره به هواکره بازمی‌گردند.\n\nت) در هر مولکول اوزون، شمار جفت الکترون‌های اشتراکی با شمار اتم‌ها یکسان و نصف شمار جفت الکترون‌های ناپیوندی است.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:14:58', 3, 'free'),
(5945, '۳۵- چند مورد از مطالب زیر، درست است؟ \n\n- سوخت‌های سبز برخلاف سوخت‌های فسیلی، باعث تولید گازهای گلخانه‌ای نمی‌شوند.\n\n - پلاستیک‌های سبز، پلیمرهایی هستند که بر پایۀ مواد گیاهی ساخته می‌شوند و در ساختار آن‌ها، اکسیژن نیز وجود دارد. - قیمت تمام‌شده پلاستیک‌ها با پایۀ نفتی، بسیار کمتر از پلاستیک‌های زیست‌تخریب‌پذیر است.\n\n - سوخت‌های سبز زیست‌تخریب‌پذیرند و از پسماندهای گیاهی مانند نیشکر به‌دست می‌آیند.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:15:34', 3, 'free'),
(5946, '۳۶- برای سوختن کامل ۴۵ گرم گلوکز، چند لیتر هوا در شرایط $STP$ لازم است؟ (۲۰ درصد حجمی هوا را اکسیژن در نظر بگیرید.) \n\n$(H=1, C=12, O=16 : g \\cdot mol^{-1})$', 1, 3, 66, 315, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:15:50', 3, 'free'),
(5947, '۳۹- کدام نمونه گاز، فشار بیشتری دارد؟', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:16:29', 3, 'free'),
(5948, '۴۰- در شرایطی معین، فراورده‌های حاصل از سوختن پروپان، گازهای کربن مونوکسید، کربن دی‌اکسید و بخار آب است. اگر نسبت مولی $CO$ به $CO_2$ تولیدی، برابر$2/0$  باشد، به‌ازای سوختن $22$ گرم پروپان، چند لیتر گاز اکسیژن با چگالی  $1/6g \\cdot L^{-1}$ مصرف می‌شود؟\n\n $(H=1, C=12, O=16 : g \\cdot mol^{-1})$', 1, 3, 66, 315, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:17:55', 3, 'free'),
(5949, '۴۱- بدن انسان جهت تأمین قسمتی از انرژی مورد نیاز خود از اکسایش گلوکز استفاده می‌کند و در هر دقیقه $0/01$مول اکسیژن برای فرایند اکسایش مصرف می‌کند. اگر در یک فضاپیما جهت تصفیۀ هوا، $644$ گرم لیتیم پراکسید $(Li_2O_2)$ موجود باشد، با توجه به واکنش‌های زیر، به‌تقریب چند درصد کربن دی‌اکسید تولید شده از اکسایش گلوکز در طول یک شبانه روز تصفیه می‌شود؟ \n\n$(Li=7, C=12, O=16 : g \\cdot mol^{-1})$ \n\n$C_6H_{12}O_6(aq) + 6O_2(g) \\rightarrow 6CO_2(g) + 6H_2O(l)$\n\n $2Li_2O_2(aq) + 2CO_2(g) \\rightarrow 2Li_2CO_3(aq) + O_2(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, NULL, NULL, 'free'),
(5950, '۴۲- چه تعداد از عبارت‌های زیر دربارۀ گاز کربن مونوکسید درست است؟ -\n\n رنگ زرد شعلۀ یک وسیلۀ گازسوز، نشان‌دهندۀ سوختن ناقص و تولید این گاز است.\n\n - میل ترکیبی این گاز با هموگلوبین خون در حدود ۲۰ برابر اکسیژن است.\n\n - نسبت شمار جفت الکترون‌های پیوندی به ناپیوندی در ساختار آن برابر ۲ است.\n\n - چگالی این گاز از هوا بیشتر و قابلیت انتشار آن در محیط بسیار کم است.', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:55', 1, '2026-09-06 20:19:09', 3, 'free'),
(5951, '۴۳- اگر اتم A دارای یک الکترون با $l=0$ و اتم B دارای ۲ الکترون با $l=1$ باشد، ساختار لوویس ترکیب حاصل از A و B کدام است؟', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, '2026-09-06 20:20:16', 3, 'free'),
(5952, '۴۴- نسبت ضریب بخار آب در معادلۀ نمادی موازنه شدۀ واکنش «II» به ضریب بخار آب در معادلۀ نمادی موازنه شدۀ واکنش «I» کدام است؟ \n\nگاز کربن دی‌اکسید + گاز متان $\\rightarrow$ بخار آب + کربن جامد \n\nگاز اکسیژن + گاز آمونیاک $\\rightarrow$ گاز نیتروژن مونوکسید + بخار آب', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, '2026-09-06 20:20:52', 3, 'free'),
(5953, '۴۵- در اکسیدی از کروم، به‌ازای هر ۲۶ گرم فلز، ۱۲ گرم نافلز وجود دارد. مجموع شمار اتم‌ها در یک واحد فرمولی از این اکسید کدام است؟\n\n $(O=16, Cr=52 : g \\cdot mol^{-1})$', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, '2026-09-06 20:21:35', 3, 'free'),
(5954, '۴۶- مخزنی به حجم $5/1$ لیتر حاوی گاز هلیم، تحت فشار ۴۰ اتمسفر است. در دمای ثابت، از گاز این مخزن برای پُر کردن بادکنک در فشار ۱ اتمسفر استفاده می‌کنند. اگر برای باد کردن یک بادکنک به‌طور کامل به ۲۰۰ سی‌سی گاز نیاز باشد، شمار بادکنک‌هایی که به‌طور کامل باد می‌شوند، کدام است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, NULL, NULL, 'free'),
(5955, '۴۷- با توجه به واکنش‌های زیر، کدام مطلب نادرست است؟\n\n I) $N_2 + O_2 \\rightarrow NO$\n\n II) $NO + O_2 \\rightarrow NO_2$\n\n III) $NO_2 + O_2 \\rightarrow NO + O_3$', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, '2026-09-06 20:22:48', 3, 'free'),
(5956, '۴۸- یک گرم از چهار فلز کلسیم (a)، سدیم (b)، پتاسیم (c) و منیزیم (d) را در شرایط یکسان دما و فشار، به چهار بالون حجمی شامل حجم‌های مساوی از محلول ۱ مولار هیدروکلریک اسید وارد می‌کنیم. بادکنکی را به بالون‌ها می‌بندیم تا گاز هیدروژن آزادشده از واکنش به درون بادکنک وارد شود. مقایسۀ حجم بادکنک‌ها در کدام گزینه به‌درستی انجام شده است؟ (فراوردۀ دیگر واکنش‌ها، کلرید فلز است.) \n\n$(Na=23, Mg=24, K=39, Ca=40 : g \\cdot mol^{-1})$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, NULL, NULL, 'free'),
(5957, '۴۹- در شرایط معیّن، پتاسیم کلرات ($KClO_3$) مطابق معادلۀ زیر تجزیه می‌شود. اگر از تجزیۀ $75/36$ گرم از این ماده، ۹ لیتر گاز تولید شود، حجم مولی گازها در این شرایط چند لیتر بر مول است؟\n\n $(KClO_3 = 122/5 g \\cdot mol^{-1})$\n\n $2KClO_3(s) \\rightarrow 2KCl(s) + 3O_2(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(5958, '۵۰- گاز کربن دی‌اکسید تولیدشده از تجزیۀ $68/1$ گرم سدیم هیدروژن کربنات را مطابق معادله‌های زیر، به‌طور کامل وارد محلول لیتیم پراکسید ($Li_2O_2$) می‌کنیم. حجم گاز اکسیژن تولیدشده پس از پایان این فرایند در شرایط STP چند لیتر است؟\n\n $(H=1, C=12, O=16, Na=23 : g \\cdot mol^{-1})$\n\n I) $NaHCO_3(s) \\rightarrow Na_2CO_3(s) + H_2O(g) + CO_2(g)$\n\n II) $2Li_2O_2(aq) + 2CO_2(g) \\rightarrow 2Li_2CO_3(aq) + O_2(g)$ \n\n(معادلۀ واکنش‌ها موازنه شوند).', 1, 3, 66, 315, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:46:56', 1, '2026-09-06 20:24:33', 3, 'free'),
(5959, '۱- همه عبارت‌های داده شده درست هستند، بجز ..................', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-09-06 20:25:03', 3, 'free'),
(5960, '۲- در لایه‌ای از هواکره که در ارتفاع ۱۳ تا ۵۱ کیلومتری از سطح زمین قرار گرفته است، به ازای هر کیلومتر افزایش ارتفاع، دما به اندازه‌ی $1.5^\\circ C$ تغییر می‌کند. اگر دما در میانه‌ی این لایه برابر با $-23^\\circ C$ باشد، دمای ابتدا و انتهای این لایه به ترتیب از راست به چپ در مقیاس سلسیوس کدام است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-09-06 20:25:42', 3, 'free'),
(5961, '۳- هلیم، .................. گاز نجیب فراوان موجود در هواکره است که به دسته‌ی .................. از جدول تناوبی تعلق داشته و یک نمونه از آن .................. بوده و مقدار آن در لایه‌های زیرین پوسته‌ی زمین، .................. از مقدار آن در هواکره است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5962, '۴- در یک مخلوط گازی به جرم ۷۲ گرم، درصد جرمی گاز آرگون، ۴ برابر درصد جرمی هلیم است. دمای این مخلوط را تا $-200^\\circ C$ کاهش داده و مایع تولید شده را از آن خارج می‌کنیم. شمار ذرات موجود در ماده‌ی گازی باقیمانده، با شمار اتم‌های هیدروژن موجود در چند گرم اتیلن‌گلیکول برابر است؟ ($g.mol^{-1}$ : $H=1$ و $He=4$ و $C=12$ و $O=16$ و $Ar=40$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5963, '۵- کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) گیاهان گازهای کربن دی‌اکسید و نیتروژن مورد نیاز خود را از هوا جذب کرده و گاز اکسیژن را تولید می‌کنند.\n\nب) فراوان‌ترین ترکیب گازی در هوای پاک و خشک تروپوسفر، در صنعت سرماسازی برای انجماد غذا کاربرد دارد.\n\nپ) اولین گازی که با افزایش دمای هوای مایع از آن خارج می‌شود، در ساختار مولکولی خود یک پیوند سه‌گانه دارد.\n\nت) هلیم در میدان‌های گازی وجود داشته و از آن برای پر کردن بالن هواشناسی و کپسول غواصی استفاده می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5964, '۶- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5965, '۷- مخلوطی از جوش شیرین و منیزیم کربنات را بر اساس معادله‌های موازنه نشده زیر، در یک ظرف سربسته به طور کامل تجزیه می‌کنیم. اگر پس از پایان این فرایند، درصد حجمی بخار آب در مخزن واکنش برابر با ۳۰٪ باشد، درصد جرمی منیزیم کربنات در مخلوط اولیه چقدر بوده است؟ ($g.mol^{-1}$ : $H=1$ و $C=12$ و $O=16$ و $Na=23$ و $Mg=24$)\n\n$NaHCO_3(s) \\rightarrow Na_2CO_3(s) + H_2O(g) + CO_2(g)$\n\n$MgCO_3(s) \\rightarrow MgO(s) + CO_2(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5966, '۸- کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) در اکسیدی از مس که آرایش الکترونی کاتیون آن به $3d^{10}$ ختم می‌شود، شمار آنیون‌ها و کاتیون‌ها برابر است.\n\nب) نسبت شمار جفت الکترون‌های پیوندی به ناپیوندی در مولکول‌های $NO_2Cl$ و $CH_2Cl_2$ با هم برابر است.\n\nپ) سنگ معدن بوکسیت، شامل اکسیدی از یک عنصر دسته $p$ به همراه برخی از ناخالصی‌ها می‌شود.\n\nت) فراورده‌های حاصل از سوختن چربی‌ها، در واکنش سوختن زغال‌سنگ نیز تولید می‌شوند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5967, '۹- مولکول $COCl_2$، دارای .................. جفت الکترون ناپیوندی در ساختار خود بوده و شمار پیوندهای اشتراکی موجود در ساختار آن، .................. برابر شمار این پیوندها در هر مولکول آمونیاک بوده و تعداد پیوندهای یگانه‌ی موجود در آن نیز با شمار این پیوندها در مولکول .................. برابر است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5968, '۱۰- پس از موازنه معادله واکنش‌های زیر، نسبت مجموع ضرایب استوکیومتری واکنش‌دهنده‌ها در واکنش $(II)$ به مجموع ضرایب واکنش‌دهنده‌ها در واکنش $(I)$ چقدر بوده و اگر در واکنش $(II)$، ۶۱/۸ گرم ترکیب محلول در آب تشکیل شود، چند لیتر گاز در شرایط استاندارد طی این واکنش تولید می‌شود؟ ($g.mol^{-1}$ : $Na=23$ , $Br=80$)\n\n$I)\\ Cl_3CCO_2H(aq) + CaCO_3(s) \\xrightarrow{\\Delta} Ca(Cl_3CCO_2)_2(aq) + CO_2(g) + H_2O(l)$\n\n$II)\\ CO(NH_2)_2(aq) + NaBrO(aq) \\xrightarrow{\\Delta} NaBr(aq) + N_2(g) + CO_2(g) + H_2O(l)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5969, '۱۱- همه عبارت‌های زیر درست هستند، بجز ..................', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5970, '۱۲- به منظور تولید ۱/۵ مول فراورده در واکنش سوختن کامل اتانول، به چند گرم گاز اکسیژن نیاز است و به کمک این مقدار گاز اکسیژن، چند مول گلوکز طبق واکنش موازنه نشده زیر به طور کامل اکسایش می‌یابد؟ ($O=16\\ g.mol^{-1}$)\n\n$C_6H_{12}O_6(aq) + O_2(g) \\rightarrow CO_2(g) + H_2O(l)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5971, '۱۳- فلز مس، بر اساس معادله موازنه نشده $Cu(s) + HNO_3(aq) \\rightarrow Cu(NO_3)_2(aq) + NO_2(g) + H_2O(l)$ با محلول نیتریک اسید واکنش می‌دهد. ضریب آب در معادله موازنه شده این واکنش، چند برابر ضریب آب در واکنش سوختن پروپان بوده و به ازای تولید هر مول آب در این واکنش، چند لیتر گاز $NO_2$ در شرایط STP تولید می‌شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5972, '۱۴ - چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) گاز گوگرد تری‌اکسید حاصل از آتشفشان‌ها و کارخانه‌ها، سبب ایجاد باران‌های اسیدی می‌شود.\n\nب) پرتوهای فروسرخ گسیل شده از سطح زمین، طول موج کمتری نسبت به پرتوهای خورشید دارند.\n\nپ) ردپای کربن دی اکسید در تولید برق با استفاده از زغال‌سنگ، از ردپای حاصل از نفت خام بیش‌تر است.\n\nت) استفاده از نماد ($\\xrightarrow{\\Delta}$) در معادله‌ی یک واکنش، به معنای گرماده بودن واکنش شیمیایی مورد نظر است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5973, '۱۵ - یک نمونه ۵۴ گرمی از دی‌نیتروژن پنتاکسید جامد را بر اساس معادله موازنه نشده زیر به طور کامل تجزیه کرده و فراورده‌های گازی حاصل را با ۸ گرم گاز اکسیژن مخلوط می‌کنیم. درصد حجمی گازی که واکنش‌پذیری کمتری دارد، در مخلوط گازی ایجاد شده چقدر می‌شود؟ ($g.mol^{-1}$ : $N=14$ و $O=16$) معادله موازنه نشده واکنش : $N_2O_5(s) \\rightarrow N_2(g) + O_2(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5974, '۱۶- معادله موازنه نشده واکنش تجزیه‌ی پتاسیم نیترات به صورت $KNO_3(s) \\rightarrow K_2O(s) + N_2(g) + O_2(g)$ است. اگر تفاوت جرم فراورده‌های گازی تولید شده در واکنش تجزیه مقداری از این ماده برابر با ۱۳ گرم باشد، جرم پتاسیم نیترات تجزیه شده برابر با چند گرم می‌شود؟ ($g.mol^{-1}$ : $N=14$ و $O=16$ و $K=39$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5975, '۱۷- کدام‌یک از مطالب زیر درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5976, '۱۸- کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) افزودن برخی از مواد مثل آهک به خاک، سبب می‌شود تا مقدار و نوع مواد معدنی در دسترس گیاهان تغییر کند.\n\nب) اگر فرمول شیمیایی نیترید یک فلز به صورت $X_3N_2$ باشد، این فلز می‌تواند متعلق به گروه ۱۱ جدول دوره‌ای باشد.\n\nپ) مقدار گاز اوزون در لایه استراتوسفر زمین نسبتا ثابت بوده و این ماده پس از میعان، به صورت بی‌رنگ دیده می‌شود.\n\nت) لایه اوزون، بخشی از استراتوسفر با بیشترین غلظت گاز $O_3$ بوده و به طور کامل مانع عبور پرتوهای فرابنفش می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5977, '۱۹- در مخلوط همگنی از گازهای هلیم و نیتروژن، درصد جرمی گاز نیتروژن $2.8$ برابر درصد حجمی این گاز است. در شرایط استاندارد، چگالی این مخلوط گازی چند برابر چگالی یک نمونه از دومین گاز نجیب فراوان موجود در هواکره خواهد بود؟ ($g.mol^{-1}$ : $He=4$ و $N=14$ و $Ne=20$ و $Ar=40$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5978, '۲۰- کدام‌یک از عبارت‌های داده شده نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5979, '۲۱- لایه‌های تروپوسفر و استراتوسفر از هواکره، به ترتیب در ارتفاع‌های ۱۱/۵ و ۲۴/۱ کیلومتری از سطح زمین به پایان می‌رسند. اگر میانگین دما در سطح زمین در حدود $14^\\circ C$ در نظر گرفته شود و به ازای هر کیلومتر افزایش ارتفاع در لایه استراتوسفر، ۵ درجه سلسیوس تغییر دما رخ دهد، دما در انتهای لایه استراتوسفر برابر با چند کلوین می‌شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5980, '۲۲- کدام‌یک از مطالب زیر درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5981, '۲۳- چه تعداد از عبارت‌های داده شده درست است؟\n\nآ) اکسیژن، در ساختار همه‌ی مولکول‌های زیستی وجود داشته و به صورت یون $O^+$ نیز در هواکره یافت می‌شود.\n\nب) جاذبه‌ی زمین، گازهای موجود در هواکره را در اطراف خود نگه داشته و مانع خروج این مواد از اتمسفر می‌شود.\n\nپ) تهیه‌ی سبک‌ترین گاز نجیب با استفاده از مخلوط گاز طبیعی مقرون به صرفه‌تر از تهیه‌ی آن با استفاده از هواکره است.\n\nت) بررسی یخ‌های قطبی نشان می‌دهد که طی $2 \\times 10^5$ سال گذشته، درصد حجمی گاز $O_2$ در هواکره کاهش یافته است.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5982, '۲۴- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5983, '۲۵- آلیاژی از طلا و نقره به جرم ۱۶۰ گرم را از سطح زمین تا ارتفاع ۵ کیلومتری لایه‌ی تروپوسفر بالا می‌بریم. اگر این آلیاژ فلزی در طول مدت زمان افزایش ارتفاع ۱/۰۲ کیلوژول انرژی با محیط اطراف خود مبادله کرده باشد، درصد جرمی فلز کاهنده‌تر در این ماده چقدر خواهد بود؟ (گرمای ویژه طلا و نقره به ترتیب برابر با ۰/۱۳ و ۰/۲۴ ژول بر گرم بر درجه‌ی سانتی‌گراد است.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5984, '۲۶- کدام‌یک از مطالب زیر درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5985, '۲۷- شمار جفت الکترون‌های ناپیوندی موجود در ساختار ترکیب آلی سازنده محلول ضدیخ، با شمار جفت الکترون‌های پیوندی موجود در ترکیب‌های داده شده در کدام‌یک از گزینه‌های زیر برابر است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5986, '۲۸- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5987, '۲۹- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5988, '۳۰- جدول زیر، اطلاعات مربوط به سوختن زغال‌سنگ و گاز طبیعی را نشان می‌دهد:\n\n| | سوخت A | سوخت B |\n\n|---|---|---|\n\n| گرما (کیلوژول بر گرم) | ۳۰ | ۵۴ |\n\n| قیمت (ریال به ازای هر گرم) | ۴ | ۵ |\n\nاگر برای تامین انرژی مورد نیاز جهت ذوب $6kg$ آهن، به مخلوطی از ذغال‌سنگ و گاز طبیعی به جرم ۴۵ گرم نیاز داشته باشیم، جهت تامین این مقدار سوختن، چند ریال هزینه مصرف شده است؟ (برای ذوب هر گرم آهن، به ۲۴۵ ژول انرژی نیاز است.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5989, '۳۱- کدام موارد از عبارت‌های زیر درست است؟ ($g.mol^{-1}$ : $N=14$ و $O=16$)\n\nآ) بخاطر عدم انحلال اکسیدهای اسیدی مثل $SO_2$ در باران معمولی، این باران‌ها خاصیت اسیدی ندارند.\n\nب) کربن مونوکسید، بسیار سمی بوده و میل ترکیبی هموگلوبین خون با آن، کمتر از گاز اکسیژن است.\n\nپ) در یک نمونه‌ی $2.2$ گرمی خالص از گاز دی‌نیتروژن مونوکسید، $0.8$ گرم اتم اکسیژن وجود دارد.\n\nت) رنگ شعله حاصل از سوختن گوگرد، مشابه رنگ شعله سوختن کامل گاز شهری خواهد بود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5990, '۳۲- پس از موازنه معادله کدام موارد از واکنش‌ها، مجموع ضریب‌های استوکیومتری فراورده‌ها کوچک‌تر از مجموع ضریب‌های استوکیومتری واکنش‌دهنده‌ها می‌شود؟\n\nآ) اتانول $+ O_2 \\rightarrow CO_2 + H_2O$\n\nب) نیتریک اسید $+ Cu \\rightarrow Cu(NO_3)_2 + NO + H_2O$\n\nپ) آمونیاک $+ CH_4 + O_2 \\rightarrow HCN + H_2O$\n\nت) منیزیم نیترید $+ H_2 \\rightarrow NH_3 + Mg$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5991, '۳۳- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5992, '۳۴- یک نمونه‌ی ناخالص از منیزیم به جرم ۱۱۸ گرم را در مجاورت با مقدار کافی از گاز اکسیژن قرار می‌دهیم. اگر طی این فرایند جرم نمونه‌ی مورد نظر به ۱۵۴ گرم رسیده باشد، در واکنش انجام شده تقریبا چند مولکول اکسیژن مصرف شده و این تعداد اتم اکسیژن، در ساختار مولکولی چند گرم استیک اسید یافت می‌شود؟ ($g.mol^{-1}$ : $H=1$ و $C=12$ و $O=16$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5993, '۳۵- کدام‌یک از مطالب زیر درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5994, '۳۶- جدول زیر، اطلاعات مربوط به اجزای تشکیل‌دهنده یک مخلوط گازی را نشان می‌دهد:\n\n| گاز | نقطه جوش ($^\\circ C$) | درصد جرمی در نمونه هوای مایع |\n\n|---|---|---|\n\n| اکسیژن | -۱۸۳ | ۲۳/۲ |\n\n| نیتروژن | -۱۹۶ | ۷۲/۲ |\n\n| هیدروژن | -۲۵۳ | ۳/۲ |\n\n| آرگون | -۱۸۶ | ۱/۴ |\n\nاگر دمای این مخلوط گازی را تا ۸۰ کلوین پایین بیاوریم، درصد جرمی ماده‌ای با واکنش‌پذیری بیشتر در مخلوط مایع ایجاد شده برابر با چند درصد می‌شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5995, '۳۷- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5996, '۳۸- مخلوطی از فلزهای سدیم و پتاسیم به جرم ۱۵۰ گرم، با مقدار کافی گاز اکسیژن واکنش داده و طی این فرایند، مجموع جرم مواد جامد موجود در ظرف واکنش ۱/۳۲ برابر می‌شود. سدیم اکسید تولید شده طی این فرایند با چند لیتر گاز کربن دی‌اکسید در شرایط STP به طور کامل واکنش می‌دهد؟ ($g.mol^{-1}$ : $O=16$ و $Na=23$ و $K=39$)\n\n$Na_2O(s) + CO_2(g) \\rightarrow Na_2CO_3(s)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5997, '۳۹- در یک نمونه از گاز متان، تفاوت شمار اتم‌های هیدروژن و کربن برابر با $3/612 \\times 10^{23}$ عدد است. این مقدار از گاز متان، در حضور چند گرم اکسیژن به طور کامل سوخته و طی این فرایند، چند لیتر گاز $CO_2$ با چگالی $0/5\\ g.L^{-1}$ تولید می‌شود؟ ($g.mol^{-1}$ : $C=12$ و $O=16$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5998, '۴۰- پس از موازنه معادله واکنش $P_4O_{10}(s) + NaOH(aq) \\rightarrow Na_3PO_4(aq) + H_2O(l)$، مجموع ضرایب فراورده‌ها در این واکنش با شمار جفت الکترون‌های ناپیوندی در مولکول کدام ماده برابر می‌شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(5999, '۴۱- کدام‌یک از مطالب زیر، درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6000, '۴۲- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) هواکره، حاوی برخی یون‌ها بوده، گرمای خورشید را در خود نگه می‌دارد و آب را در سرتاسر سیاره ما توزیع می‌کند.\n\nب) هلیم، در گاز طبیعی یافت شده و همانند خورشید، در ژرفای زمین نیز طی واکنش‌های هسته‌ای تولید می‌شود.\n\nپ) آرگون، به عنوان محیط بی‌اثر در جوشکاری فلزها کاربرد داشته و همانند گاز $CO$، گازی بی‌رنگ و بی‌بو است.\n\nت) در فرایند تقطیر یک نمونه از هوا، گاز $CO_2$ اولین ماده‌ای است که با کاهش دمای هوا تغییر حالت می‌دهد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6001, '۴۳- به ازای هر ۲ کیلومتر افزایش ارتفاع در طول لایه تروپوسفر یک نقطه از زمین، فشار هوا $0.75$ برابر می‌شود. در ارتفاعی که دمای هوا به $-20^\\circ C$ می‌رسد، فشار هوا برابر با چند اتمسفر است؟ (دما و فشار هوا در سطح زمین در نقطه مورد نظر، به ترتیب برابر با ۱۶ درجه سانتی‌گراد و $0.96$ اتمسفر است.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6002, '۴۴- کدام‌یک از عبارت‌های داده شده درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6003, '۴۵- در یک کارخانه، از مخلوط نفت و زغال‌سنگ برای تامین $10^4$ کیلووات‌ساعت انرژی مصرفی در هر روز استفاده می‌شود. اگر از دودکش‌های این کارخانه در طول هر هفته $54.6$ تن گاز $CO_2$ خارج شود، چند درصد از برق مصرف شده در این کارخانه توسط سوزاندن زغال‌سنگ تامین می‌شود؟ (به ازای تولید هر کیلووات‌ساعت انرژی با استفاده از زغال‌سنگ و نفت، به ترتیب $0.9$ و $0.7$ کیلوگرم گاز $CO_2$ تولید می‌شود.)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6004, '۴۶- چه تعداد از عبارت‌های داده شده درست هستند؟ ($g.mol^{-1}$ : $Cl=35.5$ و $Cr=52$)\n\nآ) نسبت شمار آنیون‌ها به کاتیون‌ها در کلسیم سولفید، برابر با یکی از اکسیدهای موجود در سنگ معدن آهن است.\n\nب) برای تولید صنعتی سولفوریک اسید، گوگرد را در حضور گاز اکسیژن کافی سوزانده و گاز $SO_3$ را بدست می‌آورند.\n\nپ) گرد آهن در شرایط مناسب با اکسیژن به سرعت واکنش داده و بخشی از انرژی شیمیایی موجود در آن آزاد می‌شود.\n\nت) اگر در $31.7g$ از کلرید کروم، $10.4g$ فلز وجود داشته باشد، آرایش الکترونی کاتیون در این ماده به $3d^3$ ختم می‌شود.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6005, '۴۷- کدام‌یک از عبارت‌های داده شده نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6006, '۴۸- اطلاعات داده شده در کدام ردیف از جدول زیر کاملا درست است؟\n\n| ردیف | نام ترکیب | فرمول شیمیایی | شماره گروه اتم مرکزی | نسبت جفت الکترون‌های ناپیوندی به جفت الکترون‌های پیوندی |\n\n|---|---|---|---|---|\n\n| ۱ | کربن دی‌سولفید | $CS_2$ | ۱۴ | ۲ |\n\n| ۲ | هیدروژن سیانید | $HCN$ | ۱۵ | ۰/۲۵ |\n\n| ۳ | فسفر پنتاکلرید | $PCl_5$ | ۱۵ | ۳ |\n\n| ۴ | ژرمانیم تترافلوئورید | $GeF_4$ | ۱۴ | ۱/۵ |', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6007, '۴۹- در مخلوطی از آمونیاک و اکسیژن، یک جرقه ایجاد می‌کنیم تا کل گاز آمونیاک موجود در مخلوط به طور کامل اکسایش پیدا کند. اگر طی این فرایند ۲۵٪ از گاز اکسیژن موجود در مخلوط مصرف شده باشد، درصد حجمی گاز آمونیاک در مخلوط اولیه چقدر بوده است؟\n\nمعادله واکنش موازنه شود $NH_3(g) + O_2(g) \\rightarrow NO(g) + H_2O(g)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6008, '۵۰- واکنش سوختن یک نمونه ۶۶ گرمی پروپان بر اساس معادله $C_3H_8(g) + 5O_2(g) \\rightarrow 3CO_2(g) + 4H_2O(l)$ تا جایی پیش می‌رود که جرم گاز $CO_2$ تولید شده ۶ برابر جرم گاز پروپان باقیمانده شود. بخار آب تولید شده در طول این بازه زمانی، بر اثر سوختن چند مول گاز هیدروژن تولید می‌شود؟ ($g.mol^{-1}$ : $H=1$ و $C=12$ و $O=16$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6009, '۵۱- یک نمونه از سدیم نیترات، در ساختار خود دارای $3/612 \\times 10^{22}$ اتم اکسیژن است. اگر این نمونه از سدیم نیترات را بر اساس معادله موازنه نشده $NaNO_3(s) \\rightarrow Na_2O(s) + O_2(g) + N_2(g)$ به طور کامل تجزیه کنیم، طی این فرایند چند میلی‌لیتر گاز نیتروژن در شرایط استاندارد تولید می‌شود؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6010, '۵۲- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) اکسیدهای نیتروژن وارد شده به هواکره، در نهایت به نیتریک اسید تبدیل شده و باران‌های اسیدی را ایجاد می‌کنند.\n\nب) از آتشفشان، همانند دودکش کارخانه، اکسیدی از گوگرد خارج می‌شود که ۳ پیوند اشتراکی در ساختار خود دارد.\n\nپ) باران‌های اسیدی، بر بدن انسان‌ها تاثیر داشته و گاهی باعث ایجاد خشکی و ترک‌خوردگی پوست بدن می‌شوند.\n\nت) با گرما دادن به شکر، این ماده طی یک تغییر فیزیکی ذوب شده و طی این فرایند، رنگ شکر تغییر خواهد کرد.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6011, '۵۳- کدام‌یک از عبارت‌های داده شده نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6012, '۵۵- واکنش موازنه نشده $Li_2CO_3(s) + NH_3(g) \\rightarrow LiOH(s) + CH_4N_2O(s)$، در شرایطی انجام می‌شود که چگالی گاز نیتروژن برابر با $1.4\\ g.L^{-1}$ است. به ازای مصرف ۱۲۰ لیتر گاز آمونیاک در این واکنش، چند گرم لیتیم هیدروکسید جامد تولید خواهد شد؟ ($g.mol^{-1}$ : $H=1$ و $Li=7$ و $N=14$ و $O=16$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6013, '۵۶- کدام‌یک از عبارت‌های داده شده در رابطه با واکنش زیر نادرست است؟\n\n$HCN(aq) + HNO_3(aq) \\rightarrow CO_2(g) + NO(g) + H_2O(l)$', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6014, '۵۷- یک نمونه ۴۰ گرمی از ماده $A$، با مقداری از ماده $Z$ واکنش داده و ۶۴ گرم ترکیب $AZ_2$ را ایجاد می‌کند. برای مصرف شدن ۱۴۴ گرم ترکیب $Z$ در واکنش موازنه نشده $B(s) + Z(s) \\rightarrow B_2Z_3(s)$، به چند گرم از ماده $B$ نیاز خواهیم داشت؟ ($g.mol^{-1}$ : $B=45$ و $A=80$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6015, '۵۹- کدام‌یک از عبارت‌های داده شده نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6016, '۶۰- ۱۹۲ گرم متانول را بر اساس معادله موازنه نشده $CH_3OH(l) \\rightarrow H_2(g) + CO(g)$ تجزیه کرده و گاز هیدروژن حاصل از آن را با مقدار کافی گاز نیتروژن وارد واکنش می‌کنیم. طی این فرایند، چند گرم آمونیاک تولید شده و جرم گاز کربن مونوکسید تولید شده در واکنش اول، چند برابر جرم نیتروژن مصرف شده در واکنش دوم خواهد بود؟ ($g.mol^{-1}$ : $H=1$ و $C=12$ و $N=14$ و $O=16$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6017, '۶۱- واکنش شیمیایی $CuO(s) + H_2(g) \\rightarrow Cu(s) + H_2O(g)$ را با استفاده از یک نمونه گاز هیدروژن که شامل $3/01 \\times 10^{23}$ اتم می‌شود، آغاز می‌کنیم. طی انجام این فرایند، مجموع جرم مواد جامد موجود در ظرف واکنش به اندازه چند گرم تغییر می‌کند؟ ($g.mol^{-1}$ : $H=1$ و $O=16$ و $Cu=64$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6018, '۶۲- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) مطابق قانون پایستگی جرم، شمار مول اتم‌های هر عنصر در دو سمت معادله واکنش با هم برابر خواهد بود.\n\nب) تولید خودرو و سوخت با کیفیت، از جمله راهکارهای شیمی سبز برای محافظت از طبیعت به شمار می‌رود.\n\nپ) برای جداسازی فراورده حاصل فرایند هابر، همانند فرایند تولید هوای مایع، دما را تا $-200^\\circ C$ کاهش می‌دهند.\n\nت) مخلوطی از گازهای نیتروژن و هیدروژن، در حضور جرقه و کاتالیزگر مناسب، با یکدیگر وارد واکنش خواهند شد.\n\nث) در شرایط اتاق، نمونه‌هایی از کلر و برم، برخلاف یک نمونه از ید، به شکل ظرف محتوی خود درآمده و تراکم‌پذیرند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6019, '۶۴- اگر دمای هوا در ارتفاع ۱ کیلومتری تروپوسفر در مقیاس کلوین، ۱/۱۲ برابر دمای هوا در ارتفاع ۶ کیلومتری این لایه در مقیاس کلوین باشد، دمای سطحی زمین در مقیاس سلسیوس برابر با چند درجه‌ی سانتی‌گراد بوده و در ارتفاع چند کیلومتری از سطح زمین، دمای هوا به $-35^\\circ C$ می‌رسد؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6020, '۶۵- کدام‌یک از مطالب زیر درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6021, '۶۶- در دمای $-200^\\circ C$، نمونه‌های $A$ و $B$ از هوای مایع با جرم ۱۰۰ و ۱۵۰ گرم تهیه شده است. اگر درصد جرمی اکسیژن در این نمونه‌ها به ترتیب برابر ۲۳/۲٪ و ۲۴/۶٪ باشد، با مخلوط کردن این دو نمونه و رساندن دما به $-191^\\circ C$، درصد جرمی اکسیژن در مخلوط نهایی تقریبا چقدر می‌شود؟ (درصد جرمی آرگون در مخلوط اولیه از هوای مایع برابر ۱/۵٪ است.)\n\n| گاز | نقطه جوش ($^\\circ C$) |\n\n|---|---|\n\n| اکسیژن | -۱۸۳ |\n\n| نیتروژن | -۱۹۶ |\n\n| آرگون | -۱۸۶ |', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6022, '۶۷- کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6023, '۶۸- کدام‌یک از مطالب زیر درست است؟', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6024, '۶۹- یک نمونه ۱۵۰ گرمی از پتاسیم نیترات را به طور کامل تجزیه می‌کنیم تا به پتاسیم اکسید جامد و گازهای نیتروژن و اکسیژن تبدیل شود. جرم فراورده جامد تولید شده تقریبا چند برابر تفاوت جرم گازهای حاصل از این واکنش است؟\n\n($g.mol^{-1}$ : $N=14$ و $O=16$ و $K=39$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6025, '۷۰- در واکنش سوختن کامل ۲۴ گرم اتان، چند لیتر گاز کربن دی‌اکسید در شرایط STP تولید شده و گاز اکسیژن مورد نیاز برای انجام این فرایند، با تجزیه چند گرم هیدروژن پراکسید بر اساس معادله موازنه نشده زیر تولید می‌شود؟\n\n$H_2O_2(aq) \\rightarrow H_2O(l) + O_2(g)$\n\n($g.mol^{-1}$ : $H=1$ و $C=12$ و $O=16$)', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6026, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) گاز گوگرد تری‌اکسید، یکی از آلاینده‌هایی است که بر اثر سوختن زغال سنگ در مجاورت $O_2$ تولید می‌شود.\n\nب) پس از موازنه‌ی معادله‌ی $CS_2 + O_2 \\rightarrow CO_2 + SO_2$، مجموع ضرایب مواد در این واکنش برابر با ۶ می‌شود.\n\nپ) نسبت شمار الکترون‌های پیوندی به الکترون‌های ناپیوندی در مولکول‌هایی از اوزون و اکسیژن برابر است.\n\nت) شمار الکترون‌های کاتیون در آهن$(II)$ سولفید دو برابر شمار الکترون‌های کاتیون در منیزیم نیترید است.\n\nث) در آرایش الکترونی کاتیون‌های سازنده‌ی مس$(I)$ سولفید، هیچ الکترونی در لایه $n=4$ وجود ندارد.', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:30:20', 5, 'done'),
(6027, ' شمار پیوندهای دوگانه در ساختار مولکول استیک اسید، با مولکول .................. برابر بوده و نسبت میان شمار الکترون‌های پیوندی به شمار الکترون‌های ناپیوندی در هر مولکول این ماده، با مقدار این نسبت در کدام .................. برابر است.', 1, 3, 66, 312, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:30:02', 5, 'done'),
(6028, '۷۳- چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) شمار پیوندهای اشتراکی در مولکول اوره، ۲ برابر شمار این پیوندها در فراوان‌ترین ترکیب سازنده هوای خشک است.\n\nب) با توجه به معادله $A(g) + 2B(g) \\xrightarrow{Sb} C(g)$، از سرب به عنوان کاتالیزگر در این واکنش استفاده می‌شود.\n\nپ) فرمول شیمیایی فسفید فقط شش مورد از فلزهای موجود در جدول تناوبی امروزی به صورت $M_3P_2$ است.\n\nت) بخاطر عدم انحلال اکسیدهای اسیدی مثل $SO_2$ در باران معمولی، این باران‌ها خاصیت اسیدی ندارند.', 1, 3, 66, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, NULL, NULL, 'free'),
(6029, ' کدام‌یک از مطالب داده شده نادرست است؟ ($g.mol^{-1}$ : $N=14$ و $O=16$)', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:29:30', 5, 'done'),
(6030, ' بر اثر تجزیه ۲۳۷ گرم از ترکیب $XMnO_4$ بر اساس معادله موازنه نشده زیر، ۱۲ لیتر گاز اکسیژن با چگالی $2\\ g.L^{-1}$ تولید شده است. جرم منگنز(II) اکسید تولید شده برابر با چند گرم بوده و درصد جرمی کربن در ترکیب $XHCO_3$ برابر با چند درصد می‌شود؟ ($g.mol^{-1}$ : $H=1$ و $C=12$ و $O=16$ و $Mn=55$)\n\n$XMnO_4(s) \\rightarrow MnO_2(s) + X_2MnO_4(s) + O_2(g)$', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:29:21', 5, 'done'),
(6031, ' کدام‌یک از مطالب داده شده نادرست است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:29:10', 5, 'done'),
(6032, ' در شرایط استاندارد، چگالی مخلوطی از گازهای نئون و اکسیژن، برابر با $1.25\\ g.L^{-1}$ است. با استفاده از گاز اکسیژن موجود در یک نمونه ۲۱۰ گرمی از این مخلوط گازی، چند گرم گاز $SO_2$ را می‌توان به طور کامل به $SO_3$ تبدیل کرد؟ ($g.mol^{-1}$ : $O=16$ و $Ne=20$ و $S=32$)', 1, 3, 66, 315, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:29:00', 5, 'done'),
(6033, ' در کارخانه‌ای که از گاز طبیعی برای تولید برق استفاده می‌کند، میانگین برق مصرفی ماهانه برابر ۲۶۴۰ کیلووات ساعت است. حداقل چند درخت برای از بین بردن کامل ردپای $CO_2$ تولیدی سالانه از این کارخانه نیاز بوده و در صورتی که برای تولید برق این کارخانه، انرژی خورشیدی جایگزین گاز طبیعی شود، مقدار $CO_2$ تولیدی در حدود چند درصد کاهش می‌یابد؟ (هر درخت، به طور متوسط ۴۴ کیلوگرم $CO_2$ در سال مصرف می‌کند.)\n\n| منبع تولید انرژی | مقدار $CO_2$ تولید شده (کیلوگرم) به ازای هر کیلووات ساعت برق مصرفی |\n\n|---|---|\n\n| گاز طبیعی | ۰/۳۵ |\n\n| انرژی خورشیدی | ۰/۰۵ |', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:28:14', 5, 'done'),
(6034, ' کدام یک از مطالب داده شده نادرست است؟', 1, 3, 66, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-20 22:47:20', 1, '2026-03-21 21:21:39', 4, 'done'),
(6035, ' با توجه به جدول داده‌ شده، چند مورد از مطالب زیر درست است؟\n\n\n\n\n\n\n\n• همهٔ عنصرهای سازندهٔ ترکیب (الف)، نافلزند و در هر واحد فرمولی از این ترکیب، ۱۴ اتم وجود دارد.\n\n• از واکنش ترکیب‌های (ب) و (ت) در حالت محلول، رسوبی با نسبت شمار آنیون به کاتیون برابر 2/3 تولید می‌شود.\n\n• نام ترکیب (ث)، روی (II) هیدروکسید است و در ساختار آنیون سازندهٔ آن، ۳ جفت‌الکترون ناپیوندی وجود دارد.\n\n• ترکیب (پ) جزء مواد محلول در آب است و با کاهش دما، انحلال‌پذیری آن افزایش می‌یابد.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:21:11', 4, 'done'),
(6036, ' به دودکش یک واحد صنعتی، در هر دقیقه ۵۰ لیتر گاز با چگالی  2g.L^{-1} وارد می‌شود. اگر میزان آلایندهٔ گوگرد دی‌اکسید در ورودی دودکش برابر ۴٫۳% جرمی باشد و در یک شیفت ۸ ساعتهٔ کارخانه، ۱۰۰۰ گرم منیزیم اکسید در فیلتر دودکش مصرف شود، غلظت SO_2 در گازهای خروجی از دودکش چند ppm خواهد بود؟\n\n\n\n (S=۳۲,Mg=۲۴,O=۱۶ : g.mol^{-1})\n\nMgO(s) + SO_2(g) ???? MgSO_3(s)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:57', 4, 'done'),
(6037, ' با توجه به شکل، اگر هر گوی معادل 0.01 مول ماده و حجم محلول سمت راست   mL ۲۰۰و حجم محلول سمت چپ  100mL باشد، کدام موارد از مطالب زیر درست است؟ (حل‌شونده، مس (II) سولفات است(.\n\n\n\n (Cu=۶۴,S=۳۲,O=۱۶ : g.mol^{-1})\n\n\n\nالف) غلظت مولار محلول سمت راست برابر 0.45 مول بر لیتر است.\n\nب) جرم حل‌شونده در محلول سمت چپ  g25.6 است.\n\nپ) با افزودن دو محلول به یکدیگر، غلظت مولی محلول نهایی بیشتر از غلظت مولی محلول سمت راست خواهد بود.\n\nت) با افزودن مقداری باریم کلرید به محلول سمت راست، غلظت یون SO_4^{-2}(aq) تغییر چندانی نمی‌کند.', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:49', 4, 'done'),
(6038, ' ۷۵ میلی‌لیتر محلول ۲ مولار سدیم سولفات و ۵۰ میلی‌لیتر محلول سدیم هیدروکسید با چگالی 1.2گرم بر میلی‌لیتر و ۱۷۵ میلی‌لیتر آب‌مقطر با یکدیگر مخلوط شده‌اند. اگر در محلول حاصل، غلظت یون سدیم 1.5 مولار باشد، درصد جرمی محلول سدیم هیدروکسید کدام بوده است؟\n\n(Na=۲۳,O=۱۶,H=۱ : g.mol^{-1})', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:39', 4, 'done'),
(6039, ' ۱۰۰ میلی‌لیتر محلول باریم کلرید را تا ۵۰۰ میلی‌لیتر رقیق می‌کنیم. اگر ۲۰۰ میلی‌لیتر از محلول رقیق شده با 7.1 گرم سدیم سولفات به طور کامل واکنش دهد، غلظت محلول غلیظ باریم کلرید چند mol.L^{-1} است و چند گرم رسوب تولید می‌شود؟  \n\n((گزینه‌ها را از راست به چپ بخوانید\n\n Ba = ۱۳۷ , Cl = 35.5 , S = ۳۲ , Na = ۲۳ , O = ۱۶ : g.mol^{-1}\n\n(معادله واکنش موازنه شود)\n\n Na_2SO_4(aq) + BaCl_2(aq) ???? BaSO_4(s) + NaCl(aq)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:29', 4, 'done'),
(6040, ' با توجه به جدول‌های زیر که انحلال‌پذیری دو نمک فرضی A و B را در دماهای مختلف theta نشان می‌دهند، کدام مطلب نادرست است؟.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:21', 4, 'done'),
(6041, ' درصد جرمی محلول سیرشدهٔ پتاسیم نیترات در دمای $\\theta_1 ^\\circ C$ برابر با $37.5$ است. اگر ۲۴۰ گرم محلول سیرشدهٔ این نمک را تا دمای $\\theta_2 ^\\circ C$ سرد کنیم، $0.45$ مول نمک رسوب می‌کند. حاصل $\\theta_1 - \\theta_2$ کدام است؟\n\n$(KNO_3 \\simeq ۱۰۰ g.mol^{-1})$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:13', 4, 'done'),
(6042, ' کدام موارد از مطالب زیر، نادرست‌اند؟ $(Cl = 35.5 , F = ۱۹ , H = ۱ : g.mol^{-1})$\n\nالف) در شرایط یکسان، گاز هیدروژن کلرید نسبت به گاز فلوئور، آسان‌تر مایع می‌شود.\n\nب) با نزدیک‌کردن یک میلهٔ شیشه‌ای مالش داده‌شده با موی سر، به باریکهٔ آب، مولکول‌های آب از سمت اتم‌های اکسیژن خود به سوی میله جذب می‌شوند.\n\nپ) بین مولکول‌های دواتمی عنصرهای گروه ۱۷ در دوره‌های دوم تا پنجم، ید بیشترین نقطهٔ جوش را دارد و جهت‌گیری آن در میدان الکتریکی محسوس‌تر است.\n\nت) $H_2O$ و $H_2S$ هر دو مولکول‌هایی قطبی و خمیده هستند و در دمای اتاق، حالت فیزیکی یکسانی دارند.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:20:03', 4, 'done'),
(6043, ' در چه تعداد از موارد زیر، مقایسهٔ نقطهٔ جوش دو ماده همانند مقایسهٔ جرم مولی آن‌ها است؟\n\n• $HBr , HCl$\n\n• $PH_3 , NH_3$\n\n• $CH_3COCH_3 , C_2H_5OH$\n\n• $SiH_4 , CH_4$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:19:53', 4, 'done'),
(6044, ' چند مورد از مطالب زیر، نادرست است؟\n\n• در ساختار یخ، هر اتم اکسیژن حداکثر می‌تواند با ۴ پیوند هیدروژنی به ۴ اتم هیدروژن متصل شود.\n\n• در حالت مایع، مولکول‌های آب با یکدیگر پیوندهای هیدروژنی قوی دارند و نمی‌توانند جابه‌جا شوند.\n\n• شمار پیوندهای هیدروژنی بین مولکول‌ها در یک نمونه آب با دمای  $40^\\circ C$، کم‌تر از همان نمونه بخار آب با دمای   $100^\\circ C$ است.\n\n• در ساختار یخ، حلقه‌های شش‌ضلعی وجود دارد و اتم‌های هیدروژن در رأس این حلقه‌ها قرار دارند.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:19:42', 4, 'done'),
(6045, ' آهن (II) کربنات و آمونیوم سولفات، در کدام مورد مشابه هستند؟', 1, 3, 67, 317, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:19:33', 4, 'done'),
(6046, 'با توجه به شکل‌های داده‌ شده که محلول‌هایی از کلسیم کلرید و باریم کلرید را نشان می‌دهند، کدام مطلب درست است؟.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:19:25', 4, 'done'),
(6047, ' کدام موارد از مطالب زیر، درست است؟\n\nالف) اگر فرمول هیدروکسید فلزی از دستهٔ s جدول دوره‌ای به صورت MOH باشد، فرمول فسفید و کربنات آن به ترتیب به صورت $M_3P$ و $M_2CO_3$ است.\n\nب) تفاوت جرم مولی یون‌های نیترات و نیترید، بیشتر از تفاوت جرم مولی یون‌های سولفات و سولفید است.\n\nپ) اگر فرمول شیمیایی پتاسیم کرومات به صورت $K_2CrO_4$ باشد، در هر واحد فرمولی از منیزیم کرومات، ۶ اتم وجود دارد.\n\nت) شمار پیوندهای اشتراکی در هر واحد فرمولی از آمونیوم نیترات، دو برابر شمار پیوندهای اشتراکی در ساختار یون $ClO_3^-$ است    .', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:19:14', 4, 'done'),
(6048, ' در ۳۹۰ کیلوگرم محلول ۷۷۷ ppm کلسیم کلرید، چند مول یون کلرید وجود دارد؟ ($Ca = ۴۰ , Cl = 35.5: g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:19:06', 4, 'done'),
(6049, ' یک صافی تصفیهٔ آب آشامیدنی حداکثر ظرفیت جذب $2.5$ مول یون نیترات را از آب دارد. با به کار بردن دو عدد از این صافی‌ها، حداکثر می‌توان در چند لیتر از آب شهری غلظت یون نیترات را از $۱۱۰ ppm$ به $۱۰ ppm$ رساند؟ \n\n($۱ g.mL^{-1} =$ چگالی آب $, O = ۱۶ , N = ۱۴ : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:18:57', 4, 'done'),
(6050, ' چند مورد از مطالب زیر در رابطه با استخراج منیزیم از آب دریا درست است؟\n\n• در یکی از مراحل آن، فرایند $MgCl_2(aq) \\rightarrow MgCl_2(s)$ انجام می‌شود.\n\n• در مرحلهٔ پایانی، با عبور جریان برق از محلول منیزیم کلرید، فلز منیزیم و گاز کلر تهیه می‌شود.\n\n• در مرحلهٔ نخست استخراج، منیزیم را به صورت مادهٔ نامحلول در آب رسوب می‌دهند.\n\n• از فلز تولیدشده در این فرایند، در تهیهٔ آلیاژها، شربت معده و ... استفاده می‌شود.', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:18:19', 4, 'done'),
(6051, ' به ۳۴۰ گرم محلول نقره نیترات مقدار لازم سدیم کلرید جامد اضافه می‌کنیم تا به طور کامل با هم واکنش دهند. اگر درصد جرمی یون سدیم در محلول به‌دست‌آمده در پایان واکنش، پس از جداکردن رسوب، برابر با ۳ باشد، درصد جرمی محلول اولیهٔ نقره نیترات به تقریب کدام است؟ \n\n($Ag = ۱۰۸ , Na = ۲۳ , O = ۱۶ , N = ۱۴ : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:17:52', 4, 'done'),
(6052, ' اگر هر ذرهٔ حل‌شونده در محلول‌های نشان داده‌ شده، هم‌ارز با $0.05$ مول باشد، چند مورد از مطالب زیر دربارهٔ آن‌ها درست است؟ (چگالی همهٔ محلول‌ها را برابر در نظر بگیرید.)\n\n\n\n• با اضافه‌ کردن محلول‌های (۱) و (۳) به یکدیگر، محلولی حاصل می‌شود که غلظت مولی آن با غلظت اولیهٔ هر دو محلول برابر است.\n\n• در صورت افزودن محلول‌های (۱) و (۲) به یکدیگر، غلظت مولی A افزایش و غلظت مولی B ثابت می‌ماند.\n\n• اگر جرم مولی $XO_3^-$ دو برابر جرم مولی A باشد، درصد جرمی محلول‌های (۱) و (۴) برابر است.\n\n• در صورت افزودن  $150mL$ آب به ظرف (۱)، غلظت مولی محلول حاصل به ۱ مولار می‌رسد.', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:17:39', 4, 'done'),
(6053, ' جدول مقابل سطح قند خون ناشتای افراد را برحسب عدد گلوکومتر نشان می‌دهد:\n\n\n\nحداقل شمار مول‌های گلوکز در خون یک فرد دیابتی کدام است و اگر غلظت گلوکز در خون یک فرد برابر با \n\n$۵ \\times ۱۰^{-۳}$ مولار باشد، این فرد در چه وضعیتی قرار دارد؟ (متوسط حجم خون یک انسان بالغ ۵ لیتر است) \n\n$O = ۱۶ , C = ۱۲ , H = ۱ : g.mol^{-1}$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:17:28', 4, 'done'),
(6054, ' اگر معادلهٔ انحلال‌پذیری دو نمک A و B به ترتیب به صورت $S_A = -0.23\\theta + 3.6$ و $S_B = 0.25\\theta + 1.2$ باشد، در چه دمایی برحسب درجهٔ سلسیوس، انحلال‌پذیری دو نمک با هم برابر خواهد بود؟ ($\\theta$ برحسب $^\\circ C$ است.)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:17:20', 4, 'done'),
(6055, ' نمونه‌ای از سدیم سولفات که در آن  $9.03\\times ۱۰^{۲۲}$ یون وجود دارد، مطابق معادلهٔ زیر با ۲۵۰ میلی‌لیتر محلول کلسیم کلرید به طور کامل واکنش می‌دهد. غلظت مولی محلول کلسیم کلرید کدام است؟\n\n$Na_2SO_4(aq) + CaCl_2(aq) \\rightarrow CaSO_4(s) + 2NaCl(aq)$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:17:09', 4, 'done'),
(6056, ' چند مورد از مطالب زیر، درست است؟\n\n• شکل مقابل را می‌توان به پیوند هیدروژنی میان مولکول‌های آب، در حالت جامد نسبت داد.\n\n• مولکول‌های هیدروژن سولفید همانند مولکول‌های آب، ساختار خمیده و قطبی دارند.\n\n• پیوند هیدروژنی، قوی‌ترین نیروی جاذبه بین مولکولی در موادی است که در ساختار خود اتم هیدروژن دارند.\n\n• در دمای صفر درجه سلسیوس و فشار ۱ اتمسفر، در جرم یکسانی از آب و یخ، حجم یخ بیشتر است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:57', 4, 'done'),
(6057, ' چند مورد از مطالب زیر، درست است؟ ($O = ۱۶ , C = ۱۲ , H = ۱ : g.mol^{-1}$)\n\n• گشتاور دوقطبی هگزان برخلاف اتانول و استون، به تقریب برابر با صفر است.\n\n• چربی‌ها، رنگ‌ها و لاک‌ها، اغلب ناقطبی هستند و در استون که حلال قطبی است، حل نمی‌شوند.\n\n• جرم مولی استون از اتانول بیشتر است، از این رو نقطه جوش بالاتری نسبت به اتانول دارد.\n\n• اتانول برخلاف استون و هگزان، به هر نسبتی در آب حل می‌شود.\n\n• با افزودن آب و هگزان به یکدیگر، مخلوطی ناهمگن تشکیل می‌شود که آب به دلیل جرم مولی کم‌تر، بر روی هگزان قرار می‌گیرد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:47', 4, 'done'),
(6058, ' با توجه به نمودار داده شده، کدام مطلب درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:39', 4, 'done'),
(6059, ' کدام مطلب در رابطه با انحلال سدیم کلرید در آب، نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:27', 4, 'done'),
(6060, 'در $500$ گرم آب در دمای  $20^{\\circ}C$ و فشار $3$ اتمسفر،  $1.505\\times 10^{22}$ مولکول نیتروژن مونوکسید حل شده است. در این شرایط چند میلی‌گرم دیگر از این گاز را می‌توان در آب حل کرد؟ (انحلال‌پذیری نیتروژن مونوکسید در آب در دمای  $20^{\\circ}C$ و فشار $1$ اتمسفر برابر $0.075$ گرم است. )$O=16 , N=14 : g.mol^{-1}$', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:21', 4, 'done'),
(6061, ' کدام مطلب درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:12', 4, 'done'),
(6062, ' چند مورد از مطالب زیر، نادرست است؟\n\n• متورم شدن زردآلوی خشک در آب درون لیوان را می‌توان به خاصیت گذرندگی (اسمز) مربوط دانست.\n\n• آب تصفیه‌شده به هر سه روش تقطیر، اسمز معکوس و صافی کربن را باید قبل از مصرف، کلرزنی کرد.\n\n• حرکت خودبه‌خودی مولکول‌های آب از محیط رقیق به غلیظ را اسمز معکوس می‌نامند.\n\n• در تصفیه آب به روش صافی کربن، از سه آلاینده (ترکیب‌های آلی فرار، حشره‌کش‌ها و فلزهای سمی)، تنها دو مورد را می‌توان حذف کرد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:16:03', 4, 'done'),
(6063, ' عنصر اکسیژن می‌تواند با گوگرد، آنیون‌های چنداتمی مختلفی از جمله سولفات $(SO_4)^{-2}$  و سولفیت ($SO_3^{-2}$) تشکیل دهد. مجموع شمار اتم‌ها در هر واحد فرمولی از سدیم سولفات، چند برابر مجموع شمار اتم‌ها در هر واحد فرمولی از کلسیم سولفیت است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:15:53', 4, 'done'),
(6064, ' در واکنش کامل $0.6$ مول از یک آنیون چنداتمی با $7.2$ گرم کاتیون منیزیم، $44.4$ گرم ترکیب یونی تولید می‌شود. این آنیون کدام است؟ $(S=۳۲, P=۳۱, Mg=۲۴, O=۱۶, N=۱۴, C=۱۲ : \\text{g.mol}^{-۱})$', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:15:31', 4, 'done'),
(6065, ' چند مورد از مطالب زیر، درست است؟\n\n• حلال جزئی از محلول است که درصد جرمی آن از حل‌شونده بیشتر است.\n\n• محلول $0.2$ مولار سدیم هیدروکسید نشان می‌دهد که در $0.2$ لیتر از این محلول، $۱$ مول سدیم هیدروکسید وجود دارد.\n\n• در اثر مخلوط کردن $۱۰۰$ میلی‌لیتر محلول $0.3$ مولار مس (II) سولفات با $۴۰۰$ میلی‌لیتر محلول $0.3$ مولار آن، رنگ محلول روشن‌تر می‌شود.\n\n• در یک کیلوگرم آب دریا که غلظت یون کلسیم در آن برابر   $400\\text{ ppm}$ است، $۴۰$ میلی‌گرم از این یون وجود دارد.', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:15:18', 4, 'done'),
(6066, ' کدام مورد جزء محلول‌ها به شمار نمی‌آید؟', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:15:02', 4, 'done'),
(6067, ' مجموع غلظت یون‌های کلسیم و نیترات در محلولی از کلسیم نیترات، برابر $0.09$ مولار است. در $۱۵۰$ میلی‌لیتر از محلول، چند میلی‌مول کلسیم نیترات وجود دارد؟', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:14:40', 4, 'done'),
(6068, ' اگر $31.2$ گرم آلومینیم هیدروکسید با $۲۰۰$ میلی‌لیتر محلول سولفوریک اسید به طور کامل واکنش دهد، غلظت محلول سولفوریک اسید چند مولار است؟ \n\n$(Al=۲۷, O=۱۶, H=۱ : \\text{g.mol}^{-۱})$\n\n(معادله واکنش موازنه شود.) $Al(OH)_۳(s) + H_۲SO_۴(aq) \\rightarrow Al_۲(SO_۴)_۳(aq) + H_۲O(l)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:14:27', 4, 'done'),
(6069, ' چند مورد از مطالب زیر، درست است؟\n\n• انحلال‌پذیری را می‌توان برابر با مقدار جرم حل‌شونده به ازای $۱۰۰$ گرم حلال در یک محلول سیرشده در نظر گرفت.\n\n• با افزایش دما، میزان انحلال‌پذیری پتاسیم کلرید در آب کاهش می‌یابد.\n\n• وابستگی انحلال‌پذیری سدیم نیترات به دما در مقایسه با پتاسیم نیترات، بیشتر است.\n\n• کلسیم سولفات، یک نمک کم‌محلول و باریم سولفات، یک نمک نامحلول در آب به حساب می‌آید.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:14:16', 4, 'done'),
(6070, ' محلولی به جرم 256.5 گرم و شامل 56.5 گرم لیتیم سولفات در دمای 10 درجه سانتی گراد در اختیار است. اگر این محلول تا دمای  70 درجه سانتی گراد گرم شود، چند گرم از این نمک در ته ظرف رسوب می‌کند؟)انحلال‌پذیری لیتیم سولفات در دماهای  10 درجه سانتی گراد و  70 درجه سانتی گراد به ترتیب برابر با ۳۵ و ۲۵ گرم است.(', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:14:04', 4, 'done'),
(6071, ' اگر نقطه جوش کلر (Cl_2) در فشار یک اتمسفر برابر با  -34 درجه سانتی گراد باشد، کدام اعداد را به ترتیب از راست به چپ، می‌توان به نقطه جوش استون، ید و اتانول (برحسب درجه سلسیوس) نسبت داد؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:13:54', 4, 'done'),
(6072, ' کدام گزینه درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:13:28', 4, 'done'),
(6073, ' چند مورد از مطالب زیر درباره آب و هیدروژن سولفید، درست است؟\n\n• با وجود این‌که جرم مولی هیدروژن سولفید از جرم مولی آب بیشتر است، اما آب نقطه جوش بالاتری نسبت به هیدروژن سولفید دارد.\n\n• مدل فضاپرکن و شمار جفت‌الکترون‌های پیوندی مولکول‌های آب و هیدروژن سولفید با یکدیگر مشابه است.\n\n• هیدروژن سولفید در دمای اتاق به حالت گاز و گشتاور دوقطبی مولکول‌های آن کمتر از نصف گشتاور دوقطبی مولکول‌های آب است.\n\n• نیروی بین مولکولی آب و هیدروژن سولفید به دلیل داشتن اتم‌های هیدروژن در ساختار خود، از نوع پیوند هیدروژنی است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:21', 1, '2026-03-21 21:13:16', 4, 'done'),
(6074, ' کدام عبارت درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:13:10', 4, 'done'),
(6075, ' معادلۀ «انحلال‌پذیری - دما» برای نمک A در آب به صورت $S = 0/97\\theta + 25$ است. اگر نسبت انحلال‌پذیری نمک A به نمک B در دماهای $0^\\circ C$ و $40^\\circ C$ به ترتیب برابر ۱ و ۲/۴۶ باشد، نسبت غلظت مولار محلول سیر شدۀ B به غلظت مولار محلول سیرشدۀ A در دمای $50^\\circ C$، به تقریب کدام است؟ (جرم مولی نمک A و B به ترتیب برابر ۳۳۰ و ۱۱۰ گرم در نظر گرفته شود؛ از تغییر حجم آب در اثر حل کردن نمک، چشم‌پوشی شود؛ معادلۀ «انحلال‌پذیری - دما» در آب برای نمک B به صورت خطی است).', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:12:59', 4, 'done'),
(6076, ' با توجه به شکل زیر که مربوط به واکنش محلول سدیم سولفات و باریم کلرید است، عبارت کدام گزینه نادرست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:12:51', 4, 'done'),
(6077, ' کدام عبارت در رابطه با پیوندهای مختلف آب، درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:10:54', 4, 'done'),
(6078, ' چه تعداد از ویژگی‌های زیر، بین اتانول و استون مشترک است؟\n\n• محلول بودن در آب\n\n• داشتن نقطۀ جوش پایین‌تر از آب\n\n• داشتن گشتاور دوقطبی بزرگ‌تر از صفر\n\n• شمار اتم‌های کربن\n\n• قابلیت تشکیل پیوند هیدروژنی با آب', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:10:47', 4, 'done'),
(6079, '۸- کدام گزینه نادرست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:10:40', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6080, '۹- اگر نیروی جاذبۀ بین مولکولی در حلال خالص با A...A، در حل‌شونده خالص با B...B و در مخلوط حاصل از آنها با A...B نشان داده شود، در چند مورد از مخلوط‌های زیر رابطۀ $A...B < \\frac{A...A + B...B}{2}$ برقرار است؟\r\n\r\nآ) باریم سولفات در آب\r\n\r\nب) آمونیوم سولفات در آب\r\n\r\nپ) ید در هگزان\r\n\r\nت) نقره کلرید در آب\r\n\r\nث) پتاسیم‌هیدروکسید در آب', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:10:28', 4, 'done'),
(6081, ' جدول زیر، به آزمایش انحلال قرص جوشان در آب و در دماهای داده شده مربوط است. چند مورد از مطالب زیر، درست است؟\n\n\n\n\n\n\n\n\n\nآزمایش | مقدار قرص جوشان | دمای آب ($^\\circ C$)\n\n۱ | یک قرص | ۰\n\n۲ | نصف قرص (پودر) | ۰\n\n۳ | یک قرص | ۲۵\n\n۴ | نصف قرص (پودر) | ۲۵\n\n• سرعت واکنش در آزمایش ۳، از آزمایش ۱ بیشتر است.\n\n• سرعت واکنش در آزمایش ۲، نصف سرعت واکنش در آزمایش ۱، است.\n\n• آزمایش ۴، در قیاس با ۳ آزمایش دیگر، بیشترین سرعت واکنش را دارد.\n\n• با کامل شدن واکنش‌ها، حجم گاز جمع‌آوری شده در آزمایش ۲، نسبت به ۳ آزمایش دیگر، کمتر است.', 1, 3, 67, 291, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:10:18', 4, 'done'),
(6082, ' کدام دو مورد از عبارت‌های زیر درست است؟\n\nآ) پیوند هیدروژنی بین یک مولکول آب و یک مولکول اتانول، قوی‌تر از پیوند هیدروژنی بین دو مولکول آب است.\n\nب) طبق قانون هنری، انحلال‌پذیری گازها با افزایش دما کاهش می‌یابد.\n\nپ) انحلال‌پذیری گاز $CO_2$ به دلیل گشتاور دوقطبی بزرگتر از صفر و جرم مولی بیشتر، در فشار یک اتمسفر و در هر دمایی بیشتر از گاز $NO$ است.\n\nت) چگالی یخ به دلیل وجود فضاهای خالی بین آرایش منظم شش‌ضلعی مولکول‌های $H_2O$، کمتر از چگالی آب است.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:09:27', 4, 'done'),
(6083, ' چه تعداد از عبارت‌های زیر نادرست است؟\n\n• در مخلوط آب و هگزان، برخلاف محلول استون و آب، اجزای مخلوط، هیچ اختلاطی با یکدیگر ندارند.\n\n• در حالت مایع، مولکول‌های آب، پیوندهای هیدروژنی ضعیفی دارند و به همین علت روی هم می‌لغزند و جابه‌جا می‌شوند.\n\n• در انحلال ید در هگزان، رنگ مخلوط بنفش است و مولکول‌های حل‌شونده، ماهیت خود را در محلول حفظ می‌کنند.\n\n• با اضافه کردن سدیم سولفات به آب، قدرت نیروی جاذبه یون – دوقطبی در محلول بیشتر از میانگین قدرت پیوند یونی در سدیم‌سولفات و پیوندهای هیدروژنی در آب خواهد بود.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:09:19', 4, 'done'),
(6084, ' در دمای $15^\\circ C$ و فشار ۲ اتمسفر، $0/035$ گرم گاز اکسیژن در $500g$ آب حل شده و محلولی سیرشده به‌دست آمده است. در این دما انحلال‌پذیری گاز اکسیژن در فشار ۵ اتمسفر کدام است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:09:11', 4, 'done'),
(6085, ' اگر در دمای $20^\\circ C$ انحلال‌پذیری گاز NO در فشار $9atm$ برابر ۶ میلی‌گرم در $100g$ آب باشد، غلظت NO در همان دما و فشار $3atm$ در محلول سیرشدۀ آن به‌تقریب چند ppm است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:58', 4, 'done'),
(6086, ' معادلۀ انحلال‌پذیری (S) گاز نیتروژن برحسب فشار (P) در دمای اتاق از رابطۀ $S(\\frac{g}{100gH_2O}) = 7/5 \\times 10^{-3} P$ پیروی می‌کند. با کاهش فشار از ۵ اتمسفر به یک اتمسفر، به‌تقریب چند میلی‌مول گاز نیتروژن به ازای هر کیلوگرم آب از این محلول خارج می‌شود؟ $(N=14 : g.mol^{-1})$', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:52', 4, 'done'),
(6087, ' با توجه به نمودار زیر که تأثیر فشار بر انحلال‌پذیری چند گاز را در آب $20^\\circ C$ نشان می‌دهد، کدام موارد از مطالب زیر، درست است؟ $(H=1, C=12, N=14, O=16, Ar=40 : g.mol^{-1})$\n\nآ) تمامی این گازها بدون انجام واکنش شیمیایی در آب حل می‌شوند.\n\nب) در تمام موارد با افزایش جرم مولی گازها در فشار ثابت، شیب نمودار بیش‌تر شده است.\n\nپ) غلظت گاز آرگون در فشار $5atm$ برابر $300ppm$ است.\n\nت) با افزایش فشار گاز متان از $2atm$ به $6atm$، مقدار $0/05$ گرم دیگر از این گاز در نیم‌کیلوگرم محلول وارد می‌شود.\n\nث) در فشار $3atm$ به‌تقریب می‌توان $1/1$ گرم گاز $NO$ در $0/6$ لیتر آب حل نمود. (چگالی آب برابر با $1g.cm^{-3}$ است.)', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:46', 4, 'done'),
(6088, '۱۷- نمودار زیر رابطۀ گشتاور دو‌قطبی چند ترکیب آلی با جرم مولی یکسان را با نقطۀ جوش (K) آن‌ها نشان می‌دهد. عبارت کدام گزینه نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:38', 4, 'done'),
(6089, ' چند مورد از مطالب زیر نادرست است؟\n\n● اغلب واکنش‌های شیمیایی درون بدن انسان، در محلول‌های آبی انجام می‌شود.\n\n● در اثر انحلال نیمی از ترکیب‌های «شکر، اوزون، اتیلن‌گلیکول و سدیم هیدروکسید» در آب، ماهیت ساختاری ماده تغییر نمی‌کند.\n\n● نیروی غالب در فرایند انحلال چربی در هگزان و سدیم کلرید در آب، به ترتیب از نوع واندروالسی و یون – دوقطبی است.\n\n● با انحلال یک مول از هریک از ترکیب‌های آمونیوم نیترات و پتاسیم سولفات در آب، چهار مول یون آزاد می‌شود.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:25', 4, 'done'),
(6090, ' کدام‌یک از عبارت‌های زیر درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:17', 4, 'done'),
(6091, ' تمام عبارت‌ها درست هستند، به‌جز ................', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:08:08', 4, 'done'),
(6092, ' چه تعداد از عبارت‌های زیر درست است؟\n\n● ردپای آب نشان می‌دهد که هر فرد چه مقدار از آب‌های قابل استفاده و در دسترس را مصرف می‌کند و در نتیجه چه مقدار از حجم منابع آبی کاسته می‌شود.\n\n● از آمونیوم نیترات در کودهای شیمیایی و از کلسیم سولفات برای گچ گرفتن اندام‌های شکسته شده استفاده می‌شود.\n\n● هرچه میزان نمک حل‌شده در آب بیشتر باشد، گاز کمتری در آن محلول حل می‌شود.\n\n● با افزایش گشتاور دوقطبی در مواد آلی، نیروهای بین مولکولی قوی‌تر شده و نقطۀ جوش افزایش می‌یابد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:59', 4, 'done'),
(6093, '۲۲- کدام‌یک از عبارت‌های زیر درست است؟\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nآ) برای تهیۀ آب شیرین از آب دریا می‌توان از فناوری شکل فوق استفاده کرد.\r\n\r\nب) از بخش B، آب شیرین خارج می‌شود.\r\n\r\nپ) با گذشت زمان، غلظت نمک‌ها در آب در بخش A کاهش می‌یابد.\r\n\r\nت) چنانچه در آب شور ورودی، فلزات سمی وجود داشته باشند، در نهایت از بخش A خارج می‌شوند.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:47', 4, 'done'),
(6094, ' چند مورد از عبارات زیر به درستی بیان شده‌اند؟\n\n● نیاز روزانه بدن هر فرد بالغ به یون سدیم دو برابر یون پتاسیم است.\n\n● به فرایند انتشار مولکول‌های آب از محیط غلیظ به محیط رقیق نسبت به یک غشای نیمه‌تراوا، گذرندگی (اسمز) می‌گویند.\n\n● از تبخیر و میعان متوالی آب تحت عنوان روش تقطیر برای تهیۀ آب شیرین از آب دریا می‌توان استفاده کرد.\n\n● صافی کربن و اسمز معکوس نسبت به تقطیر روش مناسب‌تری برای تهیۀ آب آشامیدنی هستند و قبل از مصرف نیاز به کلرزنی ندارند.\n\n● انحلال‌پذیری گاز اکسیژن در آب آشامیدنی نسبت به آب دریا کمتر بوده و با افزایش دما کاهش می‌یابد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:39', 4, 'done'),
(6095, ' در مورد شکل روبه‌رو چند مورد درست است؟\n\n\n\n\n\n\n\nالف) این روش اسمز نام دارد و یک روش تهیه آب شیرین از آب دریا است.\n\nب) با گذشت زمان ارتفاع آب در قسمت‌های سمت راست و چپ شکل، به ترتیب کاهش و افزایش می‌یابند.\n\nپ) در شاخه سمت چپ لوله با گذشت زمان غلظت نمک افزایش می‌یابد.\n\nت) اگر به طریقی بتوانیم به مولکول‌های آب موجود در شاخه سمت چپ یک نیروی خارجی اعمال کنیم می‌توانیم آب شیرین تهیه کنیم.\n\nث) در غشای نیمه‌تراوا همه ذرات حتی یون‌ها هم می‌توانند جابه‌جا شوند.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:31', 4, 'done'),
(6096, ' $400$ میلی‌لیتر محلول $\\%17$ جرمی $AgNO_3$ با چگالی $1.5 g.mL^{-1}$ در بازوی A و $200$ میلی‌لیتر محلول سدیم کلرید شامل $11.7$ گرم حل‌شونده در بازوی B وجود دارد. چند میلی‌لیتر آب باید جابه‌جا شود تا پدیدۀ اسمز متوقف شود؟\n\n$(Ag=108, N=14, O=16, Na=23, Cl=35.5 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:23', 4, 'done'),
(6097, ' مخلوط ماده‌های ................ و ................ یک مخلوط ................ است، چون در آن جاذبه‌های حل‌شونده با حلال ................ از میانگین جاذبه‌ها در حلال خالص و حل‌شونده خالص است.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:16', 4, 'done'),
(6098, ' کدام مطلب در مورد پیوند هیدروژنی میان مولکول‌های آب نادرست است؟ (کامل‌ترین گزینه را انتخاب کنید.)\n\nآ) در طی انجماد آب، با تشکیل پیوندهای هیدروژنی بیش‌تر و ایجاد فضاهای خالی نامنظم، حجم آن افزایش می‌یابد.\n\nب) بیش‌ترین تعداد پیوند هیدروژنی میان مولکول‌های آب مربوط به حالت فیزیکی جامد است.\n\nپ) مولکول‌های آب در حالت بخار، به‌دلیل نبود پیوند هیدروژنی میان مولکول‌ها، حرکت‌های آزادانه و منظم دارند.\n\nت) در ساختار یخ، آرایش مولکول‌های آب به شکل حلقه‌های شش‌ضلعی مسطح گسترش یافته است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:07:06', 4, 'done'),
(6099, ' در یک واحد صنعتی روزانه از ۵ مخزن آب مکعبی‌شکل به ضلع ۴ متر استفاده می‌شود. اگر غلظت یون کلرید مورد نیاز برای این مخازن $142 ppm$ باشد، مقدار کل کلسیم کلرید لازم برای استفاده روزانه حدوداً چند کیلوگرم است؟ (چگالی آب را $1 g.mL^{-1}$ در نظر بگیرید.)\n\n$(Ca = 40, Cl = 35.5 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:06:49', 4, 'done'),
(6100, ' نمودار انحلال‌پذیری برخی نمک‌ها مطابق شکل زیر است، محلول سیرشده‌ای از نمک $KNO_3$ را از دمای $45^\\circ C$ تا $34^\\circ C$ سرد می‌کنیم. از انحلال رسوب تشکیل شده در ۳۰ گرم آب با دمای $52^\\circ C$ محلولی سیرشده حاصل می‌شود. در محلول سیرشدۀ اولیه، اختلاف جرم آب و $KNO_3$ چند گرم است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:06:35', 4, 'done'),
(6101, ' کدام عبارت درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:06:27', 4, 'done'),
(6102, ' اگر ۹۰ گرم محلول سیرشدۀ کلسیم برمید را به ۱۲۰ میلی‌لیتر محلول $43/5$ درصد جرمی لیتیم برمید اضافه کنیم، غلظت مولی یون برمید در محلول حاصل کدام است؟ (انحلال‌پذیری کلسیم برمید را در شرایط آزمایش ۱۵۰ گرم در ۱۰۰ گرم آب در نظر بگیرید؛ چگالی هر دو محلول اولیه را یکسان و برابر با $1/5$ گرم بر میلی‌لیتر فرض کنید.)\n\n$(Br = 80, Ca = 40, Li = 7 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:06:19', 4, 'done'),
(6103, ' چند مورد از مطالب زیر دربارۀ مولکول‌های اتانول و استون درست است؟\n\n- هر دو ترکیب جزو حلال‌های آلی اکسیژن‌دار هستند.\n\n- فقط یکی از آن‌ها قادر است با آب پیوند هیدروژنی برقرار نماید.\n\n- از اتانول در صنایع آرایشی و بهداشتی و از استون به عنوان حلال برخی چربی‌ها، رنگ‌ها و لاک‌ها، استفاده می‌شود.\n\n- تفاوت شمار پیوندهای کووالانسی در مولکول آن‌ها برابر ۲ است.\n\n- مجموع شمار اتم‌های کربن اتانول و استون برابر اتم‌های کربن هگزان است.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:06:11', 4, 'done'),
(6104, ' با توجه به جدول مقابل و با فرض این‌که نمودار انحلال‌پذیری همۀ این مواد جامد به‌صورت خطی است، چند مورد از عبارت‌های زیر درست است؟\n\n\n\n| ماده | معادلۀ انحلال‌پذیری |\n\n| :---: | :---: |\n\n| A | $S = 0/8\\theta + 72$ |\n\n| B | $S = 0/4\\theta + 17$ |\n\n| C | $S = -0/16\\theta + 45$ |\n\n| D | $S = 0/1\\theta + 33$ |\n\n- در بازۀ دمایی صفر تا $100^\\circ C$، انحلال‌پذیری مادۀ A در هیچ دمایی با انحلال‌پذیری مواد B و C برابر نیست.\n\n- تأثیر دما بر انحلال‌پذیری مادۀ C کم‌تر از سایر مواد است.\n\n- در دمای حدود $46^\\circ C$، نمودار انحلال‌پذیری مواد C و D با هم برخورد می‌کنند.\n\n- انحلال‌پذیری مادۀ A در دمای $30^\\circ C$، $2/4$ برابر انحلال‌پذیری مادۀ D در دمای $70^\\circ C$ است.\n\n- درصد جرمی مادۀ B در محلول سیرشده‌ای از این ترکیب در دمای $55^\\circ C$، حدوداً برابر ۲۸ درصد است.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:06:05', 4, 'done'),
(6105, ' چه تعداد از مطالب زیر نادرست است؟\n\nآ) هر فرد بالغ، روزانه به‌طور میانگین $1/5$ تا ۳ لیتر آب را به شکل‌های مختلف از دست می‌دهد.\n\nب) نمی‌توان محلول سیرشده‌ای از اتانول یا استون در آب تهیه کرد.\n\nپ) مولکول‌های $H_2O$ در حالت بخار جدا از هم هستند، گویی پیوندهای هیدروژنی میان آن‌ها وجود ندارد.\n\nت) نحوۀ جهت‌گیری مولکول‌های آب در میدان الکتریکی نشان می‌دهد که اتم بزرگ‌تر، سر مثبت مولکول را تشکیل می‌دهد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:05:53', 4, 'done'),
(6106, ' همۀ موارد زیر نادرست‌اند، به‌جز ................\n\n۱) هرگاه محلول باریم کلرید به محلول سدیم سولفات اضافه شود، رسوب زردرنگ باریم سولفات تشکیل می‌شود.\n\n۲) آب اقیانوس‌ها و دریاها مخلوط‌های همگنی هستند که در آن آب حلال و یون‌ها و مولکول‌ها حل‌شونده محسوب می‌شوند.\n\n۳) زمین از دیدگاه شیمیایی پویاست و بخش‌های گوناگون آن تنها برهم‌کنش‌های شیمیایی با یکدیگر دارند.\n\n۴) در آب دریا، در میان آنیون‌ها، $Cl^-$ و در میان کاتیون‌ها، $Ca^{2+}$ بیش‌ترین مقدار را دارند.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:05:33', 4, 'done'),
(6107, ' چه تعداد از مطالب زیر درست است؟\n\nآ) جرم کل آب‌های موجود در کرۀ زمین در حدود $15 \\times 10^{20}$ کیلوگرم است که تقریباً ۷۵% سطح زمین را فرا گرفته است.\n\nب) سالانه با حل شدن میلیاردها تن مواد مختلف در آب‌کره، جرم کل مواد حل شده افزایش می‌یابد.\n\nپ) جانداران آبزی، لاشۀ گیاهان و فعالیت‌های آتشفشانی، به ترتیب تنها روی هواکره، سنگ‌کره و هواکره تأثیر می‌گذارند.\n\nت) با توجه به مقدار یون‌های حل شده در آب دریا، احتمال تشکیل کلسیم سولفات با تبخیر آب دریا بیشتر از منیزیم کلرید است.\n\nث) از بین منابع آب موجود در آب‌کره، سهم آب اقیانوس‌ها تقریباً ۴۵ برابر سهم کوه‌های یخ است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:05:26', 4, 'done'),
(6108, ' کدام گزینه نادرست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:05:19', 4, 'done'),
(6109, ' چه تعداد از موارد زیر صحیح است؟\n\nآ) هنگام تشکیل برف و باران تقریباً تمام مواد حل شده در آب، از آن جدا می‌شود که الگویی برای تهیۀ آب مقطر است.\n\nب) $BaCl_2$ ترکیبی بوده که محلول در آب است و برای شناسایی آنیون و کاتیون آن می‌توان به ترتیب از محلول‌های نقره نیترات و سدیم سولفات استفاده کرد.\n\nپ) نسبت تعداد اتم‌ها به عنصرها در ترکیب آمونیوم سولفات، ۱۰ برابر نسبت تعداد عنصرها به اتم‌ها در ترکیب لیتیم فسفات است.\n\nت) محلول از دو جزء حلال و حل‌شونده تشکیل شده است که حلال جرم بیشتری دارد و حل‌شونده را در خود حل می‌کند.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:05:11', 4, 'done'),
(6110, ' مقدار اضافی از گاز کلر مطابق واکنش موازنه نشده زیر باید با چند کیلوگرم محلول سود که غلظت یون $Na^+(aq)$ در آن برابر $11500 ppm$ است واکنش دهد تا $70/2$ گرم $NaCl$ حاصل شود؟\n\n$(H=1, Cl=35/5, Na=23, O=16: g.mol^{-1})$\n\n$Cl_2(g) + NaOH(aq) \\rightarrow NaClO_3(aq) + NaCl(aq) + H_2O(l)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:57', 4, 'done'),
(6111, ' ۵۰ گرم نمک X را در ۱۰۰ گرم آب $60^\\circ C$ حل کرده و محلول را تا دمای $10^\\circ C$ سرد می‌کنیم. اگر در دمای جدید درصد جرمی محلول سیرشدۀ نمک X برابر ۲۰ درصد باشد، برای انحلال دوبارۀ رسوب ایجاد شده در این فرایند، چند گرم آب $10^\\circ C$ نیاز است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:48', 4, 'done'),
(6112, ' مقداری مادۀ ناخالص A را به‌طور کامل در آب مقطر حل نموده و ۷۵ گرم محلول سیرشده در دمای $60^\\circ C$ تهیه می‌کنیم. اگر این محلول را تا دمای $35^\\circ C$ سرد کنیم ۵ گرم رسوب خالص A تولید می‌شود. درصد خلوص مادۀ A در ابتدا کدام بوده است و غلظت مولی مادۀ A در محلول نهایی به چه عددی می‌رسد؟ (فرض کنید ناخالصی‌ها در آب حل می‌شوند و انحلال‌پذیری مادۀ A در دمای $60^\\circ C$ و $35^\\circ C$ به ترتیب ۴۰ گرم و ۳۰ گرم در ۱۰۰ گرم آب است و $A = 75 g.mol^{-1}$ و $1/4 g.mL^{-1} =$ چگالی محلول نهایی) (گزینه‌ها را از راست به چپ بخوانید.)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:39', 4, 'done'),
(6113, ' با توجه به داده‌های جدول زیر، انحلال‌پذیری نمک‌های $KCl$ و $Li_2SO_4$ در چه دمایی یکسان است و مقدار انحلال‌پذیری این دو نمک در این دما، چقدر است؟ (نمودار انحلال‌پذیری $KCl$ و $Li_2SO_4$ در آب را خطی فرض کنید.) (گزینه‌ها را از راست به چپ بخوانید.)\n\n\n\n| نمک | انحلال‌پذیری در دمای $0^\\circ C$ $(\\frac{g}{100g \\text{ آب}})$ | تغییرات انحلال‌پذیری به‌ازای افزایش هر $10^\\circ C$ |\n\n| :---: | :---: | :---: |\n\n| $KCl$ | ۲۷ | ۳ |\n\n| $Li_2SO_4$ | ۳۶ | ۱/۵- |', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:26', 4, 'done'),
(6114, ' برای رسوب‌دادن تمام یون‌های نقرۀ موجود در ۵۰ میلی‌لیتر محلول نقره نیترات با چگالی $1/7g.mL^{-1}$ و غلظت $6 \\times 10^5 ppm$، به‌تقریب چند میلی‌لیتر محلول $35/1$ درصد جرمی سدیم کلرید با چگالی $1/5g.mL^{-1}$ لازم است؟\n\n$(Ag=108, Cl=35/5, N=14, Na=23, O=16: g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:17', 4, 'done'),
(6115, ' ۷۵۰ گرم محلول سدیم هیدروکسید با غلظت ۸ مول بر لیتر و چگالی ۱/۲۵ گرم بر میلی‌لیتر در اختیار است. با اضافه کردن محلول دیگری از سدیم هیدروکسید به آن غلظت مولی آن ۲ مول بر لیتر کاهش می‌یابد. اگر حجم محلول اضافه شده ۴۰۰ میلی‌لیتر و چگالی آن برابر ۱/۲ گرم بر میلی‌لیتر باشد، درصد جرمی محلول اضافه شده کدام است؟\n\n$(Na=23, O=16, H=1: g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:09', 4, 'done'),
(6116, '۴۵- کدام مورد، جملۀ داده شده را به درستی کامل می‌کند؟ $(N=14, O=16: g.mol^{-1})$\r\n\r\n«.......................... از .......................... فرّارتر است؛ زیرا ..........................»', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:04:02', 4, 'done'),
(6117, ' کدام موارد از مطالب زیر، درست است؟\n\nآ) در مواد مولکولی ناقطبی با افزایش جرم مولی، نیروهای بین مولکولی افزایش می‌یابد.\n\nب) با این‌که جرم مولی گازهای $N_2$ و $CO$ برابر است، $CO$ زودتر از $N_2$ به مایع تبدیل می‌شود.\n\nپ) آب و هیدروژن سولفید، هر دو مولکول‌های خمیده، قطبی و نقطۀ جوش نزدیک به یکدیگر دارند.\n\nت) چون جرم مولی $F_2$ از جرم مولی $HCl$ بیشتر است، نقطۀ جوش آن از نقطۀ جوش $HCl$، بالاتر است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:03:34', 4, 'done'),
(6118, '۴۷- کدام گزینه دربارۀ مولکول‌هایی با ساختار لوویس زیر نادرست است؟\r\n\r\n\r\n\r\n$H-\\ddot{X}-H \\quad , \\quad :\\ddot{Y}-H \\quad , \\quad \\ddot{O}=Z=\\ddot{O}$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:03:22', 4, 'done'),
(6119, '۴۸- کدام موارد (مورد) درست است؟\r\n\r\nآ) آب، تنها ماده‌ای است که به هر سه حالت جامد، مایع و گاز (بخار) می‌تواند وجود داشته باشد.\r\n\r\nب) با آن‌که میلۀ شیشه‌ای از لحاظ بار الکتریکی خنثی است، اما بر اثر مالش به موی خشک دارای بار الکتریکی منفی خواهد شد و مولکول‌های آب را به دلیل قطبی بودن منحرف می‌کند.\r\n\r\nپ) رفتار مولکول‌های آب در میدان الکتریکی، از ویژگی‌های فیزیکی آن سرچشمه می‌گیرد.\r\n\r\nت) نیروهای بین مولکولی به برهم‌کنش‌های میان مولکول‌های سازندۀ یک ماده گفته می‌شود و تنها به میزان قطبی بودن مولکول‌ها و جرم آن‌ها بستگی دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:03:13', 4, 'done'),
(6120, '۴۹- در جدول زیر که مربوط به حلال‌های آلی مختلف است، چند نادرستی علمی وجود دارد؟ $(O=16, C=12, H=1: g.mol^{-1})$\r\n\r\n\r\n\r\n| نام حلال | جرم مولی $(g.mol^{-1})$ | تعداد پیوند کووالانسی | انحلال در آب | $\\mu(D)$ | کاربرد |\r\n\r\n| :---: | :---: | :---: | :---: | :---: | :---: |\r\n\r\n| اتانول | ۴۶ | ۹ | به هر نسبتی حل می‌شود | $> 0$ | حلال در تهیۀ مواد دارویی، بهداشتی و آرایشی |\r\n\r\n| استون | ۷۴ | ۱۰ | کم | $> 0$ | حلال چربی، رنگ‌ها و انواع لاک‌ها |\r\n\r\n| هگزان | ۸۶ | ۱۸ | نامحلول | $\\simeq 0$ | حلال مواد قطبی و رقیق‌کنندۀ رنگ |', 1, 3, 67, 320, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-09-07 02:00:03', 3, 'done'),
(6121, ' کدام عبارت درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:02:48', 4, 'done'),
(6122, ' چند مورد از عبارت‌های زیر درست است؟\n\n• نیمی از مخلوط‌های زیر، همگن می‌باشند.\n\n(اتانول در آب، سدیم‌نیترات در آب، نقره کلرید در آب، باریم‌سولفات در آب، آمونیوم‌سولفات در آب، ید در هگزان)\n\n• انحلال اتانول در آب از نوع مولکولی بوده و علت انحلال‌پذیری اتانول در آب، تشابه نیروهای بین مولکولی آن‌هاست.\n\n• انحلال فقط ۳ مورد از ترکیب‌های روبه‌رو در آب، به صورت مولکولی است (اتانول، استون، سدیم‌نیترات، سدیم سولفید، باریم‌کلرید، شکر)\n\n• $CaCl_2$ برخلاف اتانول و استون، در هنگام انحلال در آب، ویژگی‌های ساختاری خود را حفظ نمی‌کند.', 1, 3, 67, 320, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:02:38', 4, 'done'),
(6123, ' چند مورد از مطالب زیر به درستی بیان شده است؟\n\nآ) ماهی‌ها با عبور دادن آب از درون آبشش‌های خود، یون‌های اکسید موجود در آب را جذب می‌کنند.\n\nب) از واکنش قرص جوشان با آب، گازی ناقطبی آزاد می‌شود که انحلال‌پذیری بیشتری نسبت به $NO$ در آب دارد.\n\nپ) افزودن نمک برخلاف افزودن یخ به نوشیدنی گازدار، باعث کاهش مقدار گاز حل‌شده در آن می‌شود.\n\nت) نیاز روزانۀ بدن هر فرد بالغ به یون سدیم، به اندازۀ نصف نیاز روزانۀ بدن هر فرد بالغ به یون پتاسیم است.\n\nث) در ساختار یخ، اتم‌هایی از آب که در محلول آب و نمک سدیم‌کلرید، به سمت یون $Cl^-$ جهت‌گیری می‌کنند، در رأس حلقه‌های شش‌ضلعی قرار دارند.', 1, 3, 67, 320, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:01:35', 4, 'done'),
(6124, '۵۳- با توجه ترکیب‌های مولکولی و میدان الکتریکی داده شده چند مورد از مطالب زیر درست است؟\r\n\r\n(آ) $SO_2$ ، (ب) $HCN$\r\n\r\n\r\n\r\n• ترکیب (آ) همانند ترکیب داخل میدان، در میدان الکتریکی جهت‌گیری خواهد کرد.\r\n\r\n• در شرایط یکسان، ترکیب (ب) نسبت به ترکیب داخل میدان، در دمای پایین‌تری به حالت مایع تبدیل خواهد شد.\r\n\r\n• گشتاور دوقطبی ($\\mu$) مولکول (آ) برخلاف مولکول نشان داده شده در میدان الکتریکی برابر صفر می‌باشد.\r\n\r\n• مولکول (ب) همانند مولکول (آ)، یک ترکیب قطبی می‌باشد.\r\n\r\n• با قرار گرفتن مولکول‌هایی مانند کربن تتراکلرید و آمونیاک در میدان الکتریکی، جهت‌گیری آن‌ها همانند مولکول نشان داده شده در میدان خواهد بود.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-09-07 02:00:26', 3, 'done'),
(6125, ' چه تعداد از عبارت‌های زیر نادرست است؟\n\n• ردپای آب نشان می‌دهد که هر فرد چه مقدار از تمام آب‌های جهان را مصرف می‌کند و در نتیجه چه مقدار از حجم منابع آبی کاسته می‌شود.\n\n• از آمونیوم نیترات در کودهای شیمیایی و از کلسیم سولفات برای گچ گرفتن اندام‌های شکسته‌شده استفاده می‌شود.\n\n• هرچه میزان نمک حل‌شده در آب بیشتر باشد، گاز کمتری در آن محلول وجود دارد.\n\n• هر فرد بالغ، روزانه به‌طور میانگین ۱۵۰۰ تا ۳۰۰۰ میلی‌لیتر آب را به‌صورت ادرار، تعریق پوستی، بخار آب در بازدم و ... از دست می‌دهد.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:01:01', 4, 'done'),
(6126, ' با توجه به شکل روبه‌رو، چه تعداد از موارد زیر درست است؟\n\n\n\n• پس از گذشت مدتی، سطح محلول سمت راست به دلیل پدیدۀ اسمز، افزایش می‌یابد.\n\n• با اعمال نیرو در لولۀ سمت راست، پدیدۀ اسمز معکوس رخ می‌دهد و آب از محیط غلیظ وارد محیط رقیق‌تر\n\n• پس از گذشت مدتی، سطح محلول در لولۀ سمت چپ افزایش می‌یابد.\n\n• با اعمال نیرو در لولۀ سمت چپ، می‌توان محلول را از مواردی مانند حشره‌کش‌ها و میکروب‌ها در صورت وجود، تصفیه نمود.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:00:51', 4, 'done'),
(6127, ' انحلال‌پذیری گاز اکسیژن در دمای $0^\\circ C$ و فشار $3atm$ برابر $0/06$ گرم در $100$ گرم آب است. اگر ۳ تن آب را در شرایط فوق از گاز اکسیژن اشباع کنیم و سپس فشار را به $1atm$ برسانیم، چند لیتر گاز اکسیژن از محلول خارج می‌شود؟ $(O=16g.mol^{-1})$', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:00:43', 4, 'done'),
(6128, 'جدول روبه‌رو، انحلال‌پذیری دو گاز را برحسب گرم در $100$ گرم آب در فشار یکسان نشان می‌دهد. با توجه به آن، چه تعداد از موارد زیر نادرست است؟ ($N=14 , O=16 : g.mol^{-1}$) (روند تغییرات میزان انحلال‌پذیری گازها را برحسب دما، یکنواخت در نظر بگیرید.) (چگالی آب $1$ گرم بر میلی‌لیتر فرض شود.)\n\n\n\n| دما | $15^\\circ C$ | $25^\\circ C$ | $35^\\circ C$ |\n\n|---|---|---|---|\n\n| A | $0/171$ | $0/128$ | $0/099$ |\n\n| $NO$ | $0/008$ | $0/006$ | $0/005$ |\n\n\n\n• با توجه به مقادیر داده شده، گاز A می‌تواند $CO_2$ باشد.\n\n• اگر $1kg$ آب سیرشده از گاز $NO$ را از دمای $15^\\circ C$ به $35^\\circ C$ برسانیم (با فرض تشکیل نشدن حالت فراسیرشده) در شرایط استاندارد، $2/24$ میلی‌لیتر گاز خارج می‌شود.\n\n• در دمای $20^\\circ C$، محلول حاوی $0/342$ گرم گاز A در $200$ گرم آب، یک محلول سیرشده است.\n\n• اگر در ۲ لیتر آب حاوی $NO$ در دمای $25^\\circ C$، $0/12$ گرم $NO$ وجود داشته باشد، یک محلول سیرشده داریم.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:00:32', 4, 'done'),
(6129, ' چند مورد از مطالب زیر درست است؟\n\n• در ترکیب‌های هیدروژن‌دار گروه ۱۵، با افزایش جرم مولی، قدرت نیروهای بین مولکولی افزایش می‌یابد.\n\n• هنگام انجماد آب، تعداد پیوندهای هیدروژنی آب، افزایش می‌یابد.\n\n• با کاهش فشار، انحلال‌پذیری گاز $NO$، بیشتر از گاز $O_2$ کاهش می‌یابد.\n\n• هر دو مولکول $H_2O$ و $H_2S$ ساختار خمیده دارند، ولی حالت فیزیکی آن‌ها در دما و فشار اتاق، متفاوت است.\n\n• به دلیل بیشتر بودن جرم مولی $HBr$، نقطۀ جوش آن بیشتر از $HF$ است.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:00:16', 4, 'done'),
(6130, ' چند مورد از مطالب زیر، درست است؟\n\n• به دلیل شباهت ساختاری $NH_3$ و $PH_3$ ، ویژگی‌های فیزیکی و شیمیایی آن‌ها کاملاً مشابه است.\n\n• هرگاه یک مول استون در یک مول آب حل شود، محلول حاصل سیرشده خواهد بود.\n\n• در دما و فشار یکسان، انحلال‌پذیری گاز اکسیژن در آب دریا، کمتر از آب خالص است.\n\n• با این‌که $N_2$ و $CO$ جرم مولی برابر دارند، گاز $CO$ آسان‌تر از گاز $N_2$ به مایع تبدیل می‌شود.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 21:00:07', 4, 'done'),
(6131, ' با توجه به نمودار مقابل چند مورد از عبارت‌های زیر نادرست است؟ (جرم مولی هر سه ماده آلی A و B و C با هم برابر است.)\n\n\n\nآ) مخلوط مادۀ A و بنزین برخلاف مخلوط ید در هگزان، یک مخلوط ناهمگن است.\n\nب) مادۀ C نمی‌تواند متان یا هگزان باشد.\n\nپ) قدرت نیروی بین مولکولی در مادۀ C، بیشتر از B و در B، بیشتر از A است.\n\nت) A و B در دمای اتاق، گازی‌شکل هستند.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:56:14', 4, 'done'),
(6132, ' چند مورد از عبارت‌های زیر نادرست است؟\n\nآ) اگر مولکول $AH_{3}$ در میدان الکتریکی جهت‌گیری کند، می‌توان دریافت که عنصر A متعلق به گروه ۱۵ است.\n\nب) مولکول $SF_{2}$ برخلاف مولکول $SO_{2}Cl_{2}$، در میدان الکتریکی جهت‌گیری می‌کند.\n\nپ) در ترکیب‌های هیدروژن‌دار گروه ۱۶ جدول دوره‌ای، گشتاور دوقطبی مولکول‌ها با کاهش عدد اتمی اتم مرکزی افزایش می‌یابد.\n\nت) همه مولکول‌های V شکل، قطبی هستند.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:56:02', 4, 'done'),
(6133, ' در چند مورد از مخلوط‌های زیر، رابطهٔ زیر برقرار است؟\n\n«میانگین نیروی پیوند هیدروژنی در حلال و پیوندهای یونی در حل‌شونده < نیروی جاذبهٔ یون - دوقطبی در محلول»\n\nآ) استون در آب      ب) ید در هگزان      پ) کلسیم فسفات در آب\n\nت) منیزیم سولفات در آب      ث) باریم کلرید در آب      ج) اتیلن گلیکول در استون\n\nچ) سدیم نیترات در هگزان      هـ) نقره کلرید در آب', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:55:52', 4, 'done'),
(6134, ' چه تعداد از عبارت های زیر در مورد روش های تصفیه آب (تقطیر، صافی کربن و اسمز معکوس) نادرست بیان شده است؟\n\n- تمامی موادی که با روش صافی کربن از آب حذف می شوند، با روش تقطیر نیز از آب جدا می شوند.\n\n- آبی که به روش اسمز معکوس تهیه می شود، پس از کلرزنی فاقد آلودگی بوده و قابل شرب است.\n\n- با هر سه روش، می توان حشره کش ها و آفت کش ها را از آب حذف کرد.\n\n- تنها با یکی از روش ها، نمی توان نافلزهای موجود در آب را از آن جدا کرد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:55:40', 4, 'done'),
(6135, '64- نمودار زیر انحلال پذیری سه گاز را که با آب واکنش شیمیایی نمی دهند، در دمای $20^\\circ C$ نشان می دهد. کدام مطلب درباره آن نادرست است؟ ($N = 14, O = 16 : g.mol^{-1}$)', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-09-07 01:57:24', 3, 'done'),
(6136, ' چند مورد از مطالب زیر درست است؟\n\n- در دما و فشار ثابت، از میان گازهای $CO_2$، $NO$، $N_2$ و $O_2$، بیشترین انحلال‌پذیری مربوط به گازی است که انحلال آن در آب، تنها جنبه فیزیکی دارد.\n\n- در روش تقطیر برای تصفیه آب، از فرآیندهای تبخیر و میعان کمک گرفته می‌شود.\n\n- با توجه به شکل مقابل که مربوط به تولید آب شیرین است، قسمت A ورود آب شور و قسمت C خروج محلول غلیظ را نشان می‌دهد.\n\n- درصد جرمی نمک‌ها در قسمت C این دستگاه، بیشتر از قسمت A است.\n\n- در این دستگاه، تولید آب شیرین به کمک فرایند خودبه‌خودی اسمز معکوس انجام می‌شود.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:55:21', 4, 'done'),
(6137, ' با توجه به نمودار داده شده، اگر 300 گرم محلول سیرشده $O_2$ را از دمای $35^\\circ C$ به $17^\\circ C$ برسانیم، به‌تقریب چند لیتر گاز اکسیژن دیگر می‌توانیم در آب حل کنیم؟ (چگالی گاز نیتروژن در همین شرایط برابر $1/4 g.L^{-1}$ است.) ($N = 14, O = 16 : g.mol^{-1}$)', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:55:13', 4, 'done'),
(6138, ' اگر انحلال پذیری مس (II) سولفات در دمای $80^\\circ C$ برابر 80 گرم در 100 گرم آب باشد، چند میلی لیتر آب بین دو طرف لوله تا رسیدن به تعادل جابه جا می شود و اختلاف ارتفاع دو محلول در دو شاخه لوله بعد از برقراری تعادل، چند سانتی متر می شود؟ (قطر هر دو لوله یکسان و برابر $4cm$ است. $ \\pi \\simeq 3 $) ($Cu = 64, S = 32, O = 16 : g.mol^{-1}$) (گزینه ها را از راست به چپ بخوانید.)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:54:55', 4, 'done'),
(6139, ' همه‌ی عبارت‌های زیر درست‌اند، به جز .............', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:54:42', 4, 'done'),
(6140, ' به ۲۰۰ گرم محلول سدیم هیدروکسید با درصد جرمی a، آب مقطر افزوده و حجم محلول را به ۲ لیتر رسانده‌ایم. اگر غلظت مولی یون سدیم در محلول پایانی برابر $0/۲۵$ مول بر لیتر باشد، مقدار a کدام است؟ ($H=1, O=16, Na=23 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:54:33', 4, 'done'),
(6141, ' به ۵۰۰ گرم محلول $280ppm$ کلسیم کربنات چند گرم آب اضافه کنیم تا غلظت کاتیون‌های آن برابر $28ppm$ شود؟ (فرض کنید که تمام $CaCO_3$ در آب به طور کامل حل می‌شود) ($Ca=40, O=16, C=12 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:54:24', 4, 'done'),
(6142, ' نوعی از ماهی تنها در شرایطی زندگی می‌کند که غلظت گاز اکسیژن محلول در آب حداقل $8ppm$ باشد. اگر یک حوضچه به ابعاد ۱۲، ۱۰ و ۸ متر که ۷۵ درصد حجم آن را آب اشغال کرده است، محل زندگی این ماهی باشد، حداقل چند لیتر اکسیژن در شرایط STP باید در آن حل شده باشد؟ $(\\rho_{\\text{آب}} = 1 \\frac{kg}{L} , O = 16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:54:11', 4, 'done'),
(6143, ' $300mL$ محلولی از سود به غلظت $4/5$ مولار و درصد جرمی ۴۵ درصد موجود است. این محلول حاوی چند گرم آب است؟ $(Na = 23 , O = 16 , H = 1 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:54:02', 4, 'done'),
(6144, ' با توجه به نمودار زیر، چند مورد از عبارت‌های زیر درست است؟\n\nآ) نقطه‌های B و C به ترتیب می‌تواند محلولی فراسیرشده و سیرنشده از پتاسیم کلرید در دمای $50^\\circ C$ را نشان دهد.\n\nب) وابستگی انحلال‌پذیری سدیم کلرید به دما از سدیم نیترات کمتر است.\n\nپ) با سرد کردن $300g$ محلول سیرشده KCl از دمای $75^\\circ C$ به دمای $45^\\circ C$ مقدار ۶۰ گرم رسوب تولید می‌شود.\n\nت) چگالی محلول سیرشده سدیم نیترات در دمای $20^\\circ C$ از سایر این محلول‌ها در این دما بیشتر است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:53:53', 4, 'done'),
(6145, ' با توجه به داده‌های جدول زیر، در یک محلول سیرشده پتاسیم کلرید در دمای $25^\\circ C$، نسبت شمار مول‌های حلال به حل‌شونده به تقریب کدام است؟ $(H=1, O=16, Cl=35/5, K=39 : g.mol^{-1})$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:53:44', 4, 'done'),
(6146, ' کدام مورد نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:53:26', 4, 'done'),
(6147, ' به $50$ گرم محلول $40$ درصد جرمی کلسیم برمید با چگالی $1/2 g.mL^{-1}$ مقدار کافی آمونیوم فسفات اضافه کنیم. غلظت آمونیوم برمید تشکیل شده چند مولار است؟ (از تغییر حجم محلول صرف‌نظر شود و معادله واکنش موازنه شود.)\n\n$(Ca=40, Br=80, N=14, H=1 : g.mol^{-1})$\n\n$CaBr_2(aq) + (NH_4)_3PO_4(s) \\rightarrow NH_4Br(aq) + Ca_3(PO_4)_2(s)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:53:17', 4, 'done'),
(6148, ' در دمای $10^\\circ C$، محلول فراسیرشده‌ای از سدیم نیترات به جرم $304$ گرم را در اختیار داریم. پس از زدن یک ضربه به محلول موردنظر، نمک ته‌نشین شده حاصل از این فرایند را براساس معادله موازنه شده زیر تجزیه می‌کنیم. اگر مجموع حجم گازهای تولید شده در شرایط استاندارد برابر با $15/68$ لیتر باشد، در محلول اولیه چند گرم نمک وجود داشته است؟ (در دمای $10^\\circ C$ انحلال‌پذیری سدیم نیترات برابر با $80$ گرم در $100$ گرم آب است.) $(Na=23, O=16, N=14 : g.mol^{-1})$\n\n$4NaNO_3(s) \\rightarrow 2Na_2O(s) + 5O_2(g) + 2N_2(g)$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:34', 1, '2026-03-21 20:53:07', 4, 'done'),
(6149, ' در دو دسی‌لیتر محلول آلومینیم سولفات، ۴۳۲ میلی‌گرم یون سولفات وجود دارد. غلظت یون آلومینیم در این محلول چند مولار است؟   $ (Al = 27 , S = 32 , O = 16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:58', 4, 'done'),
(6150, ' در محلولی از سولفات فلز $M$، غلظت نمک برابر $100ppm$ است. اگر شمار مول‌های نمک در ۶۰۰ گرم از محلول برابر $1/5 \\times 10^{-4}$ باشد، $M$ کدام فلز است؟$ (S = 32 , O = 16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:49', 4, 'done'),
(6151, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• حلال جزیی از محلول است که جرم آن از دیگر اجزای محلول، بیشتر است.\n\n• در سرم فیزیولوژی، ضدیخ و گلاب، آب نقش حلال را دارد.\n\n• زیست‌کره شامل سه سامانه آب‌کره، هواکره و سنگ‌کره است.\n\n• جانداران آبزی سالانه مقادیر زیادی کربن دی‌اکسید موجود در آب‌کره را مصرف می‌کنند.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:35', 4, 'done'),
(6152, ' کدام‌یک از عبارت‌های زیر در ارتباط با دو ترکیب کلسیم فسفات $(a)$ و باریم سولفات $(b)$ نادرست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:28', 4, 'done'),
(6153, ' در چه تعداد از ترکیب‌های یونی زیر، فراوانی کاتیون در آب دریا، در مقایسه با آنیون، بیشتر است؟\n\n• سدیم کلرید • منیزیم سولفات • پتاسیم برمید • کلسیم کربنات', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:21', 4, 'done'),
(6154, '۶- اگر ۳۰۰ میلی‌لیتر محلول 31/5 درصد جرمی نیتریک اسید با چگالی $1/2 g.mL^{-1}$ با ۵۰۰ میلی‌لیتر محلول ۴ مولار هیدروبرمیک اسید مخلوط شود، این محلول با چند کیلوگرم محلول $684ppm$ باریم هیدروکسید به طور کامل واکنش می‌دهد؟\r\n\r\n$(H=1, N=14, O=16, Ba=137 : g.mol^{-1})$\r\n\r\n(واکنش موازنه شده نیست.) $HX (aq) + Ba(OH)_2(aq)  \\rightarrow  BaX_2(aq)  + H_2O(l)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:15', 4, 'done'),
(6155, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• با عبور آب از صافی کربن،‌ ترکیب‌های آلی فرار جدا می‌شوند.\n\n• با روش اسمز معکوس می‌توان فلزهای سمی و نافلزها را از آب جدا کرد.\n\n• با انجام روش تقطیر می‌توان حشره‌کش‌ها و آفت‌کش‌ها را از آب جدا کرد.\n\n• آب تصفیه شده در هر سه روش تقطیر، اسمز معکوس و صافی کربن را باید پیش از مصرف، کلرزنی کرد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:52:01', 4, 'done'),
(6156, ' ترکیبی از کلر و فلوئور با فرمول $ClF_x$ در دمای $182^{\\circ}C$ با اورانیوم واکنش می‌دهد. بر اثر واکنش مقدار معینی از این ترکیب با اورانیوم، 7/40 گرم اورانیوم هگزا فلوئورید و  $2016mL$ گاز کلر مونوفلوئورید در دمای $182^{\\circ}C$ و فشار $1/11 atm$ تشکیل می‌شود. مقدار $x$ کدام است؟ $(U=238, F=19 : g.mol^{-1})$', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:51:53', 4, 'done'),
(6157, ' برای تهیه دو دسی‌لیتر محلول $100ppm$ از یون منیزیم، چند میلی‌لیتر محلول 0/2 مولار منیزیم نیترات لازم است؟ (چگالی محلول نهایی را $1 g.mL^{-1}$ در نظر بگیرید.) $(Mg=24, N=14, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:51:14', 4, 'done'),
(6158, ' گشتاور دوقطبی چه تعداد از مولکول‌های زیر بزرگ‌تر از صفر است؟\n\n$O_2, OCl_2, SF_4, ClF_3, PCl_3, CS_2, SO_2Cl_2, CH_2Cl_2 $', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:51:06', 4, 'done'),
(6159, ' در بین چهار ترکیب آمونیاک، اتانول، استون و هیدروژن سولفید، نقطه جوش آب با نقطه جوش کدام ترکیب‌ها به ترتیب بیش‌ترین و کم‌ترین اختلاف را دارد؟ (گزینه‌ها را از راست به چپ بخوانید.)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:50:58', 4, 'done'),
(6160, ' اگر درصد جرمی استیک اسید در سرکه 4/2 و چگالی محلول $1 g.mL^{-1}$ باشد، چند میلی‌لیتر آب به ۱۰ میلی‌لیتر سرکه در دمای ثابت اضافه کنیم تا غلظت مولی استیک اسید در محلول جدید برابر $0/5 mol.L^{-1}$ شود؟ (حجم محلول را برابر مجموع حجم آب و سرکه و جرم مولی استیک اسید را $60 g.mol^{-1}$ در نظر بگیرید.)', 1, 3, 67, 318, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:50:49', 4, 'done'),
(6161, ' محلولی از حل کردن 0/3288 گرم $(NH_4)_2Ce(NO_3)_6 $ در 2/5 لیتر آب تهیه شده است. غلظت یون آمونیوم در این محلول چند ppm است؟ $(N=14, H=1, Ce=140, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:50:39', 4, 'done'),
(6162, ' ترتیب $O_2 > N_2 > H_2 $ را به کدام ویژگی‌های زیر می‌توان نسبت داد؟\n\na) نقطه جوش\n\nb) انحلال‌پذیری در آب', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:50:30', 4, 'done'),
(6163, ' درصد مولی گاز نئون در هوا 0/0018درصد است. این معادل چند ppm حجمی است؟ $(Ne=20 g.mol^{-1}, d_{Ne}=0/785 g.L^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:50:20', 4, 'done'),
(6164, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• فراوان‌ترین آنیون چند اتمی موجود در آب دریا، یک یون پنج اتمی با دو بار منفی است.\n\n• یون‌های $Cl^-, Ca^{2+}, Mg^{2+}, OH^-, Fe^{2+}$ و $NO^- _3$ از جمله یون‌های موجود در آب‌های آشامیدنی و شیرین هستند.\n\n• اگر جرم‌های برابر از اتانول و استون را با یکدیگر مخلوط کنیم، استون نقش حلال را دارد.\n\n• کلسیم سولفات و کلسیم فسفات به ترتیب جزو مواد کم‌محلول و نامحلول در آب طبقه‌بندی می‌شوند.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:47:34', 4, 'done'),
(6165, ' اگر چهار دسی‌لیتر محلول $ 1/5 $ مولار پتاسیم هیدروکسید را به دو دسی‌لیتر محلول $ 18 $ درصد جرمی باریم هیدروکسید با چگالی $ 1/14 g.mL^{-1}$ اضافه کنیم، غلظت مولی یون هیدروکسید در محلول نهایی چند مولار خواهد بود؟\n\n$(Ba=137, O=16, H=1 : g.mol^{-1})$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:47:01', 4, 'done'),
(6166, ' اگر معادله انحلال‌پذیری نمک $A$ در آب برحسب دما (در مقیاس درجه سلسیوس) به صورت $S=1/4\\theta + 14 $ و غلظت مولی محلول سیرشده آن در دمای $ 40^{\\circ}C$ برابر $ 5 mol.L^{-1}$ باشد، چگالی محلول سیرشده آن در دمای $ 40^{\\circ}C$ چند گرم بر میلی‌لیتر است؟ $(A=100 g.mol^{-1})$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:46:47', 4, 'done'),
(6167, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• نوشیدن آب شور باعث افزایش تشنگی می‌شود زیرا آب شور طی فرایند اسمز، بخشی از آب بدن را جذب می‌کند.\n\n• اگر فشار گازهای $NO$ و $CO_2$ از یک اتمسفر به دو اتمسفر افزایش یابد، انحلال‌پذیری گاز ناقطبی $CO_2$ در آب در مقایسه با گاز قطبی $NO$ بیشتر زیاد می‌شود.\n\n• گشتاور دوقطبی هر کدام از مولکول‌های ید و هگزان دقیقاً برابر با صفر بوده و به همین دلیل در یکدیگر به خوبی حل می‌شوند.\n\n• انحلال‌پذیری $NaNO_۳$ در آب $ 0^{\\circ}C$ بیشتر از نمک‌های $KNO_3$ و $NaCl$ است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:46:37', 4, 'done'),
(6168, ' بین چهار ماده آمونیاک (a)، اتانول (b)، استون (c) و هیدروژن فلوئورید (d)، نقطه جوش کدام دو ترکیب تفاوت بیشتری با هم دارد؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:47:14', 4, 'done'),
(6169, ' ۳۲ گرم مس (II) اکسید با نسبت استوکیومتری از محلول سولفوریک اسید وارد واکنش شده و در نتیجه واکنش زیر انجام می‌شود. اگر جرم آب موجود در محلول در پایان واکنش برابر ۶۶ گرم باشد، درصد جرمی محلول سولفوریک اسید کدام است؟ $(Cu=64, H=1, O=16, S=32 : g.mol^{-1})$\n\n$CuO(s) + H_2SO_4(aq) \\rightarrow CuSO_4(aq) + H_2O(l)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:40:08', 4, 'done'),
(6170, ' در مولکول $PF_3Cl$ با جانشین کردن $Cl$ به وسیله اتم $F$، مقدار گشتاور دوقطبی مولکول ...........', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:39:54', 4, 'done'),
(6171, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• کلسیم سولفات جزو مواد کم‌محلول در آب بوده و به عنوان گچ شکسته‌بندی به کار می‌رود.\n\n• از نظر جداسازی آلاینده‌هایی مانند حشره‌کش‌ها، فلزهای سمی و ترکیب‌های آلی فرار از آب، روش‌های اسمز معکوس و صافی کربن مشابه هم عمل می‌کنند.\n\n• روزنه‌های بسیار ریز دیواره یاخته‌ها در گیاهان فقط اجازه گذر به برخی از ذره‌ها و مولکول‌های کوچک مانند آب و یون‌ها را می‌دهند.\n\n• هر فرد ماهانه کمی بیشتر از ۱۰ متر مکعب آب شامل نوشیدن، پخت و پز، نظافت، شستشو و ... مصرف می‌کند.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:39:41', 4, 'done'),
(6172, ' غلظت یون کلسیم در محلولی از کلسیم نیترات برابر $ 1200\\ ppm$ است. درصد جرمی کلسیم نیترات در این محلول کدام است؟ $(N=14, Ca=40, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:39:30', 4, 'done'),
(6173, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• برای جداسازی منیزیم از آب دریا، ابتدا آن را به صورت منیزیم اکسید رسوب می‌دهند.\n\n• برای شناسایی یون $(aq)\\ Cl^-$ می‌توان از محلول بی‌رنگ نقره نیترات استفاده کرد.\n\n• میانگین قدرت پیوند یونی در $MgSO_4$ و پیوندهای هیدروژنی در آب کمتر از نیروی جاذبه یون - دوقطبی در محلول آن است.\n\n• در شرایط یکسان، گاز کربن مونوکسید در مقایسه با گاز نیتروژن، آسان‌تر به مایع تبدیل می‌شود.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:39:21', 4, 'done'),
(6174, 'محلولی از حل کردن $ 0/342 $گرم منیزیم فورمات در $ 1/20 $ لیتر آب تهیه می‌شود. غلظت یون فورمات در محلول حاصل برحسب $ppm$ کدام است؟ $(C=12, H=1, Mg=24, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:39:13', 4, 'done'),
(6175, ' نقطه جوش کدام‌یک از ترکیب‌های زیر، بالاتر از بقیه است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:39:02', 4, 'done'),
(6176, ' اگر تفاوت شمار الکترون‌ها و نوترون‌ها در اتم $^{123}A$ برابر ۲۳ باشد، هر واحد فرمولی از نیترات فلز $A$ و فسفات فلز $A$ به ترتیب شامل چند یون است؟ (گزینه‌ها را از راست به چپ بخوانید.)', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:53', 4, 'done'),
(6177, ' در دمای ثابت، فشار هر کدام از گازهای $NO$، $N_2$ و $O_2$ را از $ 2\\ atm$ به $ 8\\ atm$ افزایش می‌دهیم. مقدار انحلال‌پذیری کدام گاز افزایش کم‌تری می‌یابد؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:47', 4, 'done'),
(6178, ' ۱۳ گرم سدیم نیترات را در ۱۷/۲۵ گرم آب $ 35^\\circ C$ حل کرده و سپس محلول حاصل را تا دمای $ 10^\\circ C$ سرد می‌کنیم. اگر درصد جرمی سدیم در محلول $ 10^\\circ C$ برابر با 11/5باشد، چند گرم از نمک رسوب کرده است؟ $(Na=23, N=14, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:38', 4, 'done'),
(6179, ' دو کیلوگرم محلول آلومینیوم نیترات با غلظت$ 6390\\ ppm$ را با شش کیلوگرم محلول پتاسیم نیترات مخلوط می‌کنیم. اگر در محلول نهایی غلظت یون نیترات $ 3255\\ ppm$ باشد، درصد جرمی محلول اولیه پتاسیم نیترات کدام است؟ $(K=39, N=14, O=16, Al=27 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:31', 4, 'done'),
(6180, ' در کدام گزینه ترکیبی که جرم مولی بیشتری دارد، گشتاور دوقطبی آن نیز بیشتر است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:24', 4, 'done'),
(6181, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• برای شناسایی یون $(aq)\\ Ag^+$ می‌توان از مقداری نمک خوراکی استفاده کرد.\n\n• فراوان ترین یون چند اتمی در آب دریا از ۵ اتم تشکیل شده است.\n\n• یون‌های حل شده در آب آشامیدنی بدون مزه هستند و با افزایش مقدار آن‌ها، مزه آب تغییر نمی‌کند.\n\n• گلاب مخلوطی همگن از چند ماده در یک حلال آلی است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:10', 4, 'done'),
(6182, ' به ۶ دسی‌لیتر محلول $ 0/002 $ مولار نیتریک اسید مقدار 21/6میلی‌گرم دی‌نیتروژن پنتاوکسید اضافه کرده و تمام آن حل می‌شود. غلظت یون نیترات محلول جدید برحسب $ppm$ کدام است؟ $(N=14, O=16 : g.mol^{-1}, d_محلول =1 \\ g.mL^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:38:02', 4, 'done'),
(6183, ' اگر چگالی محلول ۲ مولار اتانول در آب، $ 0/92 \\ g.cm^{-3}$ باشد، درصد جرمی اتانول در این کدام است؟ (جرم مولی اتانول $ 46\\ g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:37:53', 4, 'done'),
(6184, ' کدام‌یک از مطالب زیر نادرست است؟\n\n۱) خواص محلول‌ها به خواص حلال، حل‌شونده و مقدار هر یک از آن‌ها بستگی دارد.\n\n۲) در استخراج فلز منیزیم از آب دریا، علاوه بر این فلز به حالت مذاب، گاز کلر نیز به نسبت مولی برابر به دست می‌آید.\n\n۳) بیش از ۵۰٪ از سدیم کلریدی که در جهان مصرف می‌شود، صرف تولید ۵ ماده می‌شود.\n\n۴) محلول ۵ درصد جرمی سیتریک اسید در آب، همان سرکه خوراکی است که خاصیت اسیدی ملایم داشته و به عنوان چاشنی در غذاها مصرف می‌شود.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:33:22', 4, 'done'),
(6185, ' در یک آزمایشگاه شیمی دو محلول با مشخصات زیر موجود است:\n\nA: محلول کلسیم برمید با درصد جرمی ۲۰ و چگالی 1/25 گرم بر میلی‌لیتر\n\nB: محلول کلسیم برمید با درصد جرمی ۴۰ و چگالی 1/50 گرم بر میلی‌لیتر\n\nاگر جرم‌های مساوی از این دو محلول را با هم مخلوط کنیم، مولاریته محلول نهایی کدام است؟ (از تغییر حجم در اثر مخلوط کردن چشم‌پوشی کنید.) $(Ca=40, Br=80 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:33:09', 4, 'done'),
(6186, ' اگر دو لیتر محلول 1/42٪ جرمی سدیم سولفات را با سه لیتر محلول 2/34٪ جرمی نمک خوراکی را با هم مخلوط کنیم، غلظت یون سدیم در مخلوط نهایی چند $ppm$ است؟ (چگالی هر کدام از محلول‌ها $ 1\\ g.mL^{-1}$ در نظر گرفته شود.)\n\n$(Na=23, O=14, S=32, Cl=35/5 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:32:59', 4, 'done'),
(6187, 'کدام مطالب زیر درست‌اند؟\n\nآ) در دما و فشار اتاق هر دو ترکیب $PH_3$ و $AsH_3$ گازی‌شکل بوده و نقطه جوش آن‌ها کم‌تر از $NH_3$ است.\n\nب) در ساختار یخ، اطراف هر مولکول آب، ۶ پیوند هیدروژنی تشکیل می‌شود.\n\nپ) اگر محلول سیرشده‌ای از لیتیوم سولفات را به اندازه کافی سرد کنیم، مقداری از حل‌شونده آن ته‌نشین می‌شود.\n\nت) اتانول در مقایسه با استون، نقطه جوش بالاتر و جرم مولی کم‌تری دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:32:49', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6188, ' در چه تعداد از شکل‌های زیر، جهت‌گیری یا عدم جهت‌گیری مولکول‌ها در میدان الکتریکی به درستی نشان داده شده است؟\n\n(اشکال مربوط به مولکول‌های $CO_2$، $O_2$، $H_2O$ و $HCl$)', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:32:40', 4, 'done'),
(6189, ' معادله انحلال‌پذیری دو نمک سدیم نیترات و پتاسیم کلرید برحسب دما (در مقیاس درجه سلسیوس) به صورت زیر است. با توجه به این معادله‌ها چه تعداد از عبارت‌های پیشنهادشده درست هستند؟\n\n$NaNO_3 : S = 0/8\\theta + 72$ \n\n$KCl : S = 0/3\\theta + 27$\n\n• اگر ۱۰۰ گرم محلول سیرشده $NaNO_3$ را از دمای $ 35^\\circ C$ تا $ 15^\\circ C$ سرد کنیم، حداکثر ۸٪ جرم محلول اولیه ته‌نشین می‌شود.\n\n• اگر در دمای $ 80^\\circ C$، مقدار ۱۵۰ گرم سدیم نیترات جامد را با ۱۰۰ گرم آب مخلوط کنیم یک محلول فراسیر شده به دست می‌آید.\n\n• در دمای $ 60^\\circ C$ غلظت درصد جرمی محلول پتاسیم کلرید به تقریب برابر با ۳۱٪ است.\n\n• در هیچ دمایی انحلال‌پذیری این دو نمک با هم برابر نیست.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:32:23', 4, 'done'),
(6190, ' اگر انحلال‌پذیری ترکیب یونی A در دماهای $ 20^\\circ C$ و $ 45^\\circ C$ به ترتیب برابر ۹۹ و ۱۲۹ گرم در ۱۰۰ گرم آب باشد، در 527/5گرم از محلول A در دمای $ 30^\\circ C$ حداکثر چند گرم از این ترکیب حل شده است؟ (فرض کنید انحلال‌پذیری این نمک در آب با دما، رابطه خطی دارد.)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:32:08', 4, 'done'),
(6191, ' چه تعداد از مطالب زیر درست است؟\n\n• در دما و فشار اتاق، حالت‌های فیزیکی مولکول‌های قطبی آب و هیدروژن سولفید، متفاوت است.\n\n• در ساختار یخ، آرایش مولکول‌های آب به گونه‌ای است که در آن، اتم‌های اکسیژن در رأس حلقه‌های شش‌ضلعی قرار دارند.\n\n• به دلیل وجود پیوندهای هیدروژنی، ساختارهای آب و یخ منظم هستند.\n\n• گشتاور دوقطبی هگزان به طور دقیق برابر با صفر نیست.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:31:59', 4, 'done'),
(6192, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• اگر جرم مولی مولکول قطبی A بیشتر از مولکول قطبی B باشد، لزوماً نیروی بین مولکولی A قوی‌تر از B نیست.\n\n• در مخلوط برم و هگزان، نیروی جاذبه بین مولکول‌های هگزان و برم، بیشتر از میانگین نیروهای جاذبه در برم خالص و هگزان خالص است.\n\n• گاز اکسیژن در مقایسه با گاز نیتروژن، سخت‌تر به مایع تبدیل می‌شود.\n\n• این‌که خیار در آب شور چروکیده می‌شود، نمونه‌ای از فرایند اسمز معکوس است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:31:50', 4, 'done'),
(6193, ' با توجه به نمودار داده‌شده چه تعداد از عبارت‌های زیر درست است؟ (جرم مولی هر سه ماده آلی B ،A و C با یک‌دیگر برابر است.)\n\n• مولکول‌های B و C در میدان الکتریکی جهت‌گیری می‌کنند.\n\n• در شرایط یکسان A در مقایسه با B و C، انحلال‌پذیری بیشتری در هگزان دارد.\n\n• قطبیت هیچ‌کدام از مولکول‌های B ،A و C بیشتر از مولکول آب نیست.\n\n• B می‌تواند اتانول باشد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:31:42', 4, 'done'),
(6194, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• در فشار یک اتمسفر و در هر دمایی، انحلال‌پذیری گاز $CO_2$ در آب بیشتر از گاز $NO$ است.\n\n• در دمای $ 20^\\circ C$، انحلال‌پذیری گاز $O_2$ در فشار $2 atm$ در آب، دو برابر انحلال‌پذیری گاز $O_2$ در فشار $ 1 atm$ است.\n\n• در دمای $ 20^\\circ C$، انحلال‌پذیری گاز $O_2$ در فشار $ 2 atm$ در آب، بیشتر از دو برابر انحلال‌پذیری گاز $N_2$ در فشار $ 1 atm$ است.\n\n• در فشار $ 2 atm$، انحلال‌پذیری گاز $O_2$ در آب $ 20^\\circ C$، کم‌تر از انحلال‌پذیری گاز $O_2$ در آب $ 10^\\circ C$ است.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:31:32', 4, 'done'),
(6195, '۴۸- برای جدا کردن ترکیب‌های آلی فرار از آب آلوده کدام روش (های) تصفیه کارایی دارد؟\r\n\r\na) تقطیر\r\n\r\nb) صافی کربن\r\n\r\nc) اسمز معکوس', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-09-07 01:58:06', 3, 'done'),
(6196, '۴۹- کدام‌یک از مطالب زیر در ارتباط با فرایند استخراج منیزیم از آب دریا نادرست است؟\r\n\r\n۱) در مرحله نخست، منیزیم را به صورت ماده جامد و نامحلول منیزیم هیدروکسید رسوب می‌دهند.\r\n\r\n۲) منیزیم هیدروکسید را طی فرایندی به منیزیم کلرید تبدیل می‌کنند.\r\n\r\n۳) با استفاده از جریان برق، محلول منیزیم کلرید را به عنصرهای سازنده آن تجزیه می‌کنند.\r\n\r\n۴) در پایان علاوه بر منیزیم مذاب، گاز کلر نیز به دست می‌آید.', 1, 3, 67, 303, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-09-07 01:58:43', 3, 'done'),
(6197, ' اگر مولکول $AD_2$ ساختار خمیده (V شکل) داشته باشد، چند مورد از مطالب زیر درباره آن درست است؟\n\n• گشتاور دو قطبی آن بزرگ‌تر از صفر است.\n\n• عنصرهای D و A می‌توانند در یک دوره جدول تناوبی جای داشته باشند.\n\n• عنصرهای D و A می‌توانند در یک گروه جدول تناوبی جای داشته باشند.\n\n• در لایه ظرفیت اتم مرکزی در این مولکول می‌تواند، ۱، ۲ یا ۴ الکترون ناپیوندی وجود داشته باشد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:30:14', 4, 'done'),
(6198, ' درصد جرمی محلول 1/24مولار پتاسیم یدید با چگالی $ 1/15\\ g.mL^{-1}$ کدام است؟ $(K=39, I=127 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:30:01', 4, 'done'),
(6199, ' اگر ۷۵ گرم محلول سیرشده از یک نمک بادمای $ 75^\\circ C$ را گرما دهیم تا آب خود را از دست بدهد و ۲۵ گرم نمک خشک به دست آید و ۵۰ گرم از همان محلول سیرشده در دمای $ 0^\\circ C$، دارای 13/5 گرم نمک خشک باشد، ضریب $\\theta$ در معادله خطی انحلال‌پذیری (S) برای این نمک به تقریب کدام است؟', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:29:52', 4, 'done'),
(6200, ' اگر غلظت یون فسفات در محلولی از پتاسیم فسفات برابر $ 3800\\ ppm$ باشد، غلظت یون پتاسیم در این محلول چند مولار است(d_محلول = 1\\ g.mol^{-1}, K=39, P=31, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:29:40', 4, 'done'),
(6201, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ) در شرایط یکسان، انحلال‌پذیری کلسیم سولفات در آب، کم‌تر از انحلال‌پذیری آمونیوم نیترات است.\n\nب) مواد شیمیایی موجود در آب دریا را می‌توان به روش‌های فیزیکی یا شیمیایی از آن جدا کرد.\n\nپ) در مجموعه‌ای از مولکول‌های آب، هر جفت اتم هیدروژن با یک نیروی جاذبه قوی از سوی یک اتم اکسیژن در مولکول همسایه جذب می‌شود.\n\nت) در دمای $ 25^\\circ C$، نیروی جاذبه بین مولکولی HF در حدی قوی است که می‌تواند مولکول‌های HF را کنار یک‌دیگر نگاه دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:29:31', 4, 'done'),
(6202, ' چگالی آب هنگام یخ زدن، ........... می‌یابد، زیرا ........... .', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:29:19', 4, 'done'),
(6203, ' با استفاده از روش تقطیر که برای تصفیه آب به کار می‌رود، چه تعداد از مواد زیر که در آب آلوده موجودند از آن جدا نمی‌شوند؟\n\n• نافلزها • حشره‌کش‌ها • ترکیب‌های آلی فرار • میکروب‌ها • فلزهای سمی', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:29:08', 4, 'done'),
(6204, ' اگر ۵۴ گرم محلول سیرشده نقره نیترات در آب $ 60^\\circ C$ را تا دمای $ 20^\\circ C$ سرد کنیم، مقداری نقره نیترات ته‌نشین می‌شود. به تقریب چند گرم آب $ 20^\\circ C$ باید به این ظرف اضافه کنیم تا دوباره کل نقره نیترات ته‌نشین شده در محلول حل شود؟ (حلالیت نقره نیترات در دماهای $ 60^\\circ C$ و $ 20^\\circ C$ به ترتیب ۲۴۰ و ۲۱۶ گرم در ۱۰۰ گرم آب است.)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:29:00', 4, 'done'),
(6205, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• برای شناسایی یون کلسیم می‌توان از محلول پتاسیم فسفات استفاده کرد.\n\n• یکی از مراحل تهیه آب آشامیدنی، اضافه کردن مقدار زیادی یون فلوئورید به آن است.\n\n• سرم فیزیولوژی و دریاها به ترتیب جزو مخلوط‌های همگن و ناهمگن هستند.\n\n• در آمونیوم سولفید هر دو نوع پیوند یونی و کووالانسی وجود دارد.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:28:50', 4, 'done'),
(6206, ' برای نوشتن فرمول شیمیایی ترکیب ............. ، ترکیب ............. از پرانتز استفاده می‌شود.', 1, 3, 67, 317, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:28:40', 4, 'done'),
(6207, ' در محلولی از کلسیم نیترات به جرم $ 125 g$، جرم کلسیم حل شده در آن برابر $ 0/02 $ گرم است. غلظت نیترات در این محلول چند $ppm$ است؟ $(Ca=40, N=14, O=16 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:28:29', 4, 'done'),
(6208, ' چه تعداد از عبارت‌های زیر درست است؟ $(C=12, O=16, N=14 : g.mol^{-1})$\n\n• در فرمول مولکولی شکر، شمار اتم‌های هیدروژن دو برابر شمار اتم‌های اکسیژن است.\n\n• گاز نیتروژن در مقایسه با گاز کربن مونوکسید، سخت‌تر به مایع تبدیل می‌شود.\n\n• هر مولکول HF همانند هر مولکول $NH_3$ حداکثر با دو مولکول مانند خود پیوند هیدروژنی تشکیل می‌دهد.\n\n• یون سدیم فراوان‌ترین یون حل‌شده در آب دریا است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:28:16', 4, 'done'),
(6209, ' ۴۰۰ گرم محلول 7/5 درصد جرمی آمونیوم نیترات به طور کامل خشک شده است. شمار یون‌های موجود در ماده جامد به دست آمده کدام است؟ $(N=14, O=16, H=1 : g.mol^{-1})$', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:27:56', 4, 'done'),
(6210, ' ۲۵۰ میلی‌لیتر از محلول حاصل از انحلال $ 0/4 $ مول از یدید یک فلز با فرمول $M_x I_y$ در ۸۰۰ میلی‌لیتر آب، با 62/5 میلی‌لیتر محلول آبی ۴ مولار نقره نیترات به طور کامل واکنش می‌دهد. فرمول یدید کدام است؟\n\n$M_x I_y + AgNO_3 \\to Ag_x I_n + M(NO_3)_y$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:27:44', 4, 'done'),
(6211, ' چه تعداد از عبارت‌های زیر درست است؟\n\n• تهیه و تولید سود سوزآور، گاز هیدروژن و سدیم کربنات، جزو کاربردهای نمک خوراکی به شمار می‌آید.\n\n• اگر در دمای معین، ۱۰۰ گرم آب را با مقداری بیشتر از انحلال‌پذیری یک نمک مخلوط کنیم، یک محلول فراسیرشده به دست می‌آید.\n\n• با افزایش دما، انحلال‌پذیری گاز اکسیژن در آب، مشابه انحلال‌پذیری لیتیوم سولفات در آب کاهش می‌یابد.\n\n• مولکول دی‌نیتروژن مونوکسید برخلاف گوگرد تری‌اکسید، قطبی بوده و در میدان الکتریکی جهت‌گیری می‌کند.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:48', 1, '2026-03-21 20:27:34', 4, 'done'),
(6212, ' چند مورد از مطالب زیر، درست است؟\n\nالف) زیست‌کره شامل جانداران روی کره زمین است و در واکنش‌های آن‌ها، درشت مولکول‌ها نقش اساسی ایفا می‌کنند.\n\nب) آب‌کره از مولکول‌های کوچک و درشت مانند یون‌ها، آب و ... تشکیل شده است.\n\nپ) آب آشامیدنی، مخلوطی زلال و همگن است که حاوی مقدار زیادی از یون‌های گوناگون است.\n\nت) در واکنش سدیم فسفات با محلول سدیم کلرید، یک ماده محلول و یک رسوب سفیدرنگ حاصل می‌شود.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:27:21', 4, 'done'),
(6213, ' با توجه به شکل روبه‌رو، چند مورد از مطالب داده‌شده، درست است؟ (N = 14 , O = 16 , Na = 23 , Cl = 35.5 , $Ag = 108 : g.mol^{-1}$)\n\nالف) شکل هندسی یون چند اتمی موجود در محلول مشابه با یون کربنات است.\n\nب) در واکنش 170 گرم نقره نیترات با 58.5 گرم سدیم کلرید، 143.5 گرم رسوب سفیدرنگ تولید می‌شود.\n\nپ) در فرمول هر دو فرآورده واکنش، نسبت شمار کاتیون به آنیون برابر با 1 است.\n\nت) در واکنش موازنه‌شده، مجموع شمار اتم‌ها در واکنش‌دهنده‌ها با مجموع شمار اتم‌ها در فرآورده‌ها، برابر است.', 1, 3, 67, 317, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:27:13', 4, 'done'),
(6214, ' برای چه تعداد از ترکیب‌های زیر، رابطهٔ $\\frac{\\text{اتم ها شمار}}{\\text{عنصرها شمار}} \\ge 3.5$ برقرار است؟ a) آمونیوم کربنات b) آلومینیم سولفات c) آهن (III) سولفات d) منیزیم نیترات e) آهن (II) فسفات f) آهن (II) نیترید', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:27:01', 4, 'done'),
(6215, ' درصد جرمی سدیم هیپوکلریت (NaClO) در نوعی محلول سفیدکننده برابر با 4.2 است. در نیم لیتر از این محلول به تقریب چند مول NaClO وجود دارد؟ (O = 16 , Na = 23 , $Cl = 35.5 : g.mol^{-1}$) (چگالی محلول را 1.5 $g.cm^{-3}$ در نظر بگیرید.)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:26:51', 4, 'done'),
(6216, ' در یک کانال تصفیه آب آشامیدنی به‌ازای هر دو متر مکعب آب، 4 مول یون منیزیم وجود دارد. اگر بخواهیم غلظت این یون را به مقدار استاندارد آن (30 ppm) برسانیم، به چند گرم سود سوزآور نیاز داریم؟ (فرض کنید که در این نمونه آب، یون‌های دیگر وجود ندارند و چگالی آب را 1 $g.mL^{-1}$ در نظر بگیرید.) (H = 1 , O = 16 , Na = 23 , $Mg = 24 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:26:41', 4, 'done'),
(6217, ' متوسط حجم خون یک انسان بالغ 5 لیتر است و هر واحد انسولین، 360 میلی‌گرم قند خون را کاهش می‌دهد. اگر دستگاه گلوکومتر قند خون فردی را 150 نشان دهد و مقدار استاندارد قند خون 70 تا 110 باشد، حداقل چند واحد انسولین نیاز است تا میزان قند خون به محدوده استاندارد برگردد؟', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:26:31', 4, 'done'),
(6218, ' انحلال‌پذیری نمکی در دمای 50°C برابر با 1.08 گرم به‌ازای 100 گرم حلال است. اگر چگالی محلول سیرشده این نمک در این دما $1.1 \\; g.mL^{-1}$ و جرم مولی نمک $54 \\; g.mol^{-1}$ باشد، غلظت مولی محلول به تقریب کدام است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:26:22', 4, 'done'),
(6219, ' اگر $500$ گرم از محلول سیرشدهٔ یک نمک را از دمای $50^{\\circ}C$ تا $30^{\\circ}C$ سرد کنیم، $100$ گرم رسوب تشکیل می‌شود. اگر انحلال‌پذیری نمک موردنظر در دمای $30^{\\circ}C$ برابر $100$ گرم باشد، انحلال‌پذیری این نمک در دمای $60^{\\circ}C$ کدام است؟ (تغییرات انحلال‌پذیری برحسب دما به‌صورت خطی است.)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:26:13', 4, 'done'),
(6220, ' چند مورد از مطالب زیر، درست است؟\n\nالف) در مرحلهٔ نخست تهیهٔ منیزیم از آب دریا، منیزیم را به‌صورت مادهٔ جامد و نامحلول $Mg(OH)_2$ رسوب می‌دهند.\n\nب) در دمای مشخصی در محدودهٔ صفر تا $100^{\\circ}C$، انحلال‌پذیری هریک از نمک‌های $KNO_3$، $NaNO_3$ و $KCl$ با انحلال‌پذیری نمک $Li_2SO_4$ یکسان می‌شود.\n\nپ) $HCl(g)$ برخلاف $F_2(g)$، در میدان الکتریکی جهت‌گیری می‌کند و نسبت به $F_2(g)$ آسان‌تر به حالت مایع تبدیل می‌شود.\n\nت) در مواد مولکولی با جرم مولی متفاوت، ماده با مولکول‌های قطبی همواره نقطهٔ جوش بالاتری دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:26:04', 4, 'done'),
(6221, ' چند مورد از مطالب زیر، درست است؟\n\nالف) نقطهٔ جوش $HF$ از $H_2O$ کمتر و از $NH_3$ بیشتر است.\n\nب) گشتاور دوقطبی مولکول‌های $H_2O$ و $H_2S$ به تقریب برابر و حدود $1$ دبای است.\n\nپ) میان مولکول‌های متیل آمین ($CH_3NH_2$)، پیوند هیدروژنی وجود دارد.\n\nت) در شرایط یکسان، یخ نسبت به آب هم‌جرم خود، حجم بیشتر و چگالی کمتری دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:25:52', 4, 'done'),
(6222, ' با اضافه شدن کدام ترکیب به آب، نیروی جاذبه در محلول از میانگین جاذبه در حلال و حل‌شوندهٔ خالص قوی‌تر خواهد بود؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:25:42', 4, 'done'),
(6223, ' کدام موارد از مطالب زیر، درست است؟\n\nالف) شمار اتم‌های هیدروژن در ساختار هگزان بیشتر از دو برابر شمار اتم‌های هیدروژن در ساختار اتانول است.\n\nب) تفاوت مقدار گشتاور دوقطبی ید و آب، بیشتر از تفاوت مقدار گشتاور دوقطبی ید و هگزان است.\n\nپ) جرم مولی و نقطهٔ جوش استون بیشتر از اتانول است.\n\nت) دمای جوش فسفین ($PH_3$) بیشتر از آمونیاک است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:25:34', 4, 'done'),
(6224, ' چند مورد از مطالب زیر، درست است؟\n\nالف) از اتانول و استون، نمی‌توان محلول سیرشده در آب تهیه کرد.\n\nب) با فرض یکسان بودن چگالی متانول و اتانول، در محلول حاصل از اضافه شدن حجم برابر از آن‌ها با یکدیگر، اتانول نقش حلال را دارد.\n\nپ) انحلال‌پذیری گازها در آب در دمای ثابت، با افزایش فشار به‌صورت خطی افزایش می‌یابد.\n\nت) با اینکه کربن دی‌اکسید یک مولکول ناقطبی است، اما در شرایط یکسان، انحلال‌پذیری آن در آب از نیتروژن مونوکسید بیشتر است.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:25:24', 4, 'done'),
(6225, ' با توجه به نمودار زیر که انحلال‌پذیری گاز اکسیژن در آب دریا و آب آشامیدنی را نشان می‌دهد، اگر دو کیلوگرم آب آشامیدنی از دمای $5^{\\circ}C$ تا دمای $30^{\\circ}C$ گرم شود، حجم گاز اکسیژن آزادشده از آن در شرایط STP به تقریب چند میلی‌لیتر است؟ ($O=16\\ g\\cdot mol^{-1}$)\n\n[تصویر نمودار انحلال‌پذیری برحسب دما]', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:25:13', 4, 'done'),
(6226, ' کدام گزینه درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:25:02', 4, 'done'),
(6227, ' چند مورد از مطالب زیر، درست است؟\n\nالف) در واکنش‌های زیست‌کره که شامل نمک‌ها و ماسه‌ها است، درشت مولکول‌ها نقش اساسی ایفا می‌کنند.\n\nب) برهم‌کنش‌های میان بخش‌های مختلف کره زمین، تنها از نوع شیمیایی است.\n\nپ) کوه‌های یخ، بیشترین بخش منابع غیراقیانوسی آب را تشکیل می‌دهند.\n\nت) آب اقیانوس‌ها و دریاها که برای مصارف خانگی مناسب نیستند، در صنعت و کشاورزی استفاده می‌شوند.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:24:52', 4, 'done'),
(6228, ' در چند مورد، نام ماده با فرمول شیمیایی آن هم‌خوانی ندارد؟\n\nالف) مس سولفید: $CuS$\n\nب) کلسیم برمید: $CaBr_2$\n\nپ) آهن (III) کلرید: $Fe_2Cl$\n\nت) آلومینیم تری فلوئورید: $AlF_3$\n\nث) منیزیم (II) اکسید: $MgO$\n\nج) کروم (III) سولفات: $Cr(SO_4)_3$', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:24:43', 4, 'done'),
(6229, ' جرم $Cl^-$ و $Na^+$ در نمونه‌ای از آب دریا به جرم یک کیلوگرم به ترتیب برابر با 19000 و 11500 میلی‌گرم است. اگر 71 درصد یون $Cl^-$ موجود در 5 تن آب دریا در فرایند تبلور به $NaCl(s)$ تبدیل شود، چند مول $NaCl$ حاصل می‌شود و غلظت $Na^+$ در نمونه باقی‌مانده به تقریب چند ppm است؟ ($Na=23 , Cl=35/5 : g\\cdot mol^{-1}$، چگالی آب = $1g\\cdot mL^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:24:30', 4, 'done'),
(6230, ' برای تهیه محلول 3/4 درصد جرمی از سدیم نیترات، حداکثر چند گرم آب خالص را باید به 20 میلی‌لیتر محلول 1 مولار سدیم نیترات با چگالی 1/05 گرم بر میلی‌لیتر اضافه کنیم؟ ($Na=23 , O=16 , N=14 : g\\cdot mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:24:21', 4, 'done'),
(6231, ' اوزون می‌تواند مطابق واکنش زیر با آب واکنش دهد. اگر 5 درصد اوزون حل شده در آب به هیدروژن پراکسید تبدیل شود، برای تهیه 300 میلی‌لیتر محلول 0/2 مولار هیدروژن پراکسید، چند لیتر گاز اوزون در فشار 4atm و دمای $91^{\\circ}C$ لازم است؟ (از تغییر حجم چشم‌پوشی کنید.)\n\n$O_3(g) + H_2O(l) \\rightarrow H_2O_2(aq) + O_2(g)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:24:11', 4, 'done'),
(6232, ' اگر 50 گرم پتاسیم کلرید خالص را با 300 گرم محلول 16/67 درصد جرمی آن در دمای $30^{\\circ}C$ مخلوط کرده و مخلوط را به‌اندازۀ کافی هم بزنیم، 10 گرم از پتاسیم کلرید ته ظرف باقی می‌ماند. بر این اساس، انحلال‌پذیری پتاسیم کلرید در دمای $30^{\\circ}C$ کدام است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:23:45', 4, 'done'),
(6233, ' کدام موارد از مطالب زیر، درست است؟\n\nالف) نقطه جوش $HF$ نسبت به $H_2O$ کمتر و نسبت به $NH_3$ بیشتر است.\n\nب) $HCl(g)$ نسبت به $F_2(g)$ آسان‌تر به مایع تبدیل می‌شود، زیرا نیروهای بین‌مولکولی در آن ضعیف‌تر است.\n\nپ) در شرایط یکسان، انحلال‌پذیری $CO_2(g)$ در آب نسبت به $NO(g)$ کمتر ولی نسبت به $N_2(g)$ بیشتر است.\n\nت) نقطه جوش اتانول نسبت به استون بیشتر و نسبت به آب کمتر است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:21:31', 4, 'done'),
(6234, ' با اضافه کردن چه تعداد از ترکیب‌های زیر به آب، جاذبه در محلول از میانگین جاذبه در حلال و حل‌شونده خالص، قوی‌تر خواهد بود؟\n\n«$BaSO_4$ ، $Ca_3(PO_4)_2$ ، $CH_3COCH_3$ ، $MgCl_2$ ، $C_6H_{14}$ ، $C_2H_5OH$»', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:21:22', 4, 'done'),
(6235, ' با توجه به شکل داده شده که مربوط به فرایند انحلال سدیم کلرید در آب است، کدام گزینه نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:21:13', 4, 'done'),
(6236, ' کدام گزینه نادرست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:21:02', 4, 'done'),
(6237, ' چند مورد از مطالب زیر، درست است؟\n\n- زیست‌کره شامل جانداران روی کرۀ زمین است و در واکنش‌های آن‌ها مولکول‌های کوچک مانند آب و کربن دی‌اکسید، نقش اساسی ایفا می‌کنند.\n\n- سالانه میلیاردها تن مواد گوناگون از سنگ‌کره وارد آب‌کره می‌شوند؛ ازاین‌رو جرم کل مواد حل‌شده در آب‌های کرۀ زمین، بسیار افزایش یافته است.\n\n- آب باران در هوای پاک تقریباً خالص است و هنگام تشکیل برف و باران، تقریباً همۀ مواد حل‌شده در آب از آن جدا می‌شود.\n\n- رسوب نقره کلرید از واکنش محلول نقره نیترات با محلول سدیم کلرید تشکیل می‌شود و این ترکیب، مانند رسوب باریم سولفات، سفیدرنگ است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:20:54', 4, 'done'),
(6238, ' کدام مطلب دربارۀ یون‌های حل‌شده در آب دریا درست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:20:43', 4, 'done'),
(6239, 'کدام مورد در یک واحد فرمولی از کلسیم فسفات، کمتر از آمونیوم سولفات است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:20:34', 4, 'done'),
(6240, ' اگر فرمول شیمیایی سزیم سلنیت به‌صورت $Cs_2SeO_3$ و فرمول شیمیایی سدیم وانادات به‌صورت $Na_3VO_4$ باشد، نسبت شمار آنیون به کاتیون در آلومینیم سلنیت چند برابر نسبت شمار عنصرها به شمار اتم‌ها در آمونیوم وانادات است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:20:27', 4, 'done'),
(6241, ' نسبت جرم آنیون به کاتیون در هر مول از سدیم فسفات کدم است و در $0/25$ مول از این ماده، چند کاتیون وجود دارد؟\n\n$(O=16 \\text{ , } Na=23 \\text{ , } P=31 : g\\cdot mol^{-1})$', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:20:14', 4, 'done'),
(6242, ' اگر محتویات دو ظرف روبه‌رو را به هم اضافه کنیم، پس از انجام واکنش رسوب زرد‌رنگی تولید می‌شود. با توجه به آن کدام گزینه درست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:20:06', 4, 'done'),
(6243, ' ۲ لیتر گاز متان و ۵ لیتر گاز اکسیژن را در یک سامانه قرار می‌دهیم تا در واکنش سوختن، هر دو به‌طور کامل مصرف شوند. اگر فرآورده‌های این فرایند $CO(g)$ ، $CO_2(g)$ و $H_2O(g)$ باشند، درصد جرمی کربن مونوکسید در مخلوط گازی حاصل به تقریب کدام است؟', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:19:54', 4, 'done'),
(6244, ' فرمول سولفات، نیترات و فسفات آهن (III) به ترتیب کدام است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:19:43', 4, 'done'),
(6245, ' به 200 میلی‌لیتر از محلول 0/4 مولار یک نمک، چند میلی‌لیتر محلول 2 مولار آن را اضافه کنیم تا غلظت نمک در محلول حاصل، 1 مولار باشد؟', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:19:32', 4, 'done'),
(6246, ' اگر در نوعی آب آشامیدنی غلظت یون کلسیم برابر $400 ppm$ باشد، غلظت این یون در آب چند مولار است و یون کلسیم موجود در 6 تن از این آب با چند مول سدیم فسفات به‌طور کامل واکنش می‌دهد؟ ($Ca=40 g\\cdot mol^{-1}$ ، چگالی محلول $= 1 g\\cdot mL^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:19:11', 4, 'done'),
(6247, ' 5 لیتر گاز هیدروژن کلرید، حداکثر چند میلی‌لیتر محلول $18/5 g\\cdot L^{-1}$ کلسیم هیدروکسید را خنثی می‌کند؟ (چگالی گاز هیدروژن کلرید در شرایط آزمایش برابر $1/46 g\\cdot L^{-1}$ است.) ($H=1 , O=16 , Cl=35/5 , Ca=40 : g\\cdot mol^{-1}$)\n\n$HCl(g) + Ca(OH)_{2}(aq) \\rightarrow CaCl_{2}(aq) + H_{2}O(l)$ (معادله واکنش موازنه شود.)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:19:20', 4, 'done'),
(6248, ' نمودار انحلال‌پذیری برحسب دما یک نمک مطابق شکل زیر است. 305 گرم محلول سیرشده این نمک در دمای $45^{\\circ}C$ شامل چند گرم از این نمک است و اگر در دمای $60^{\\circ}C$، 80/25 گرم نمک در 125 گرم آب حل شده باشد، در این حالت چه نوع محلولی در ظرف خواهیم داشت؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:18:45', 4, 'done'),
(6249, ' محلولی شامل 60 درصد جرمی حل‌شونده است. اگر با 5 برابر شدن مقدار حلال در این محلول، یک محلول سیرشده حاصل گردد، انحلال‌پذیری حل‌شونده در این شرایط، چند گرم به‌ازای 100 گرم حلال است؟', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:18:34', 4, 'done'),
(6250, ' چند مورد از مطالب زیر، درست است؟\n\n- مولکول‌های قطبی مانند آب و کربن دی‌اکسید، در میدان الکتریکی جهت‌گیری می‌کنند.\n\n- با افزایش جرم مولی مولکول‌ها، گشتاور دوقطبی آن‌ها افزایش می‌یابد.\n\n- گشتاور دوقطبی مولکول‌ها را با یکای دبای ($\\mu$) گزارش می‌کنند.\n\n- نقطه جوش مواد مولکولی با گشتاور دوقطبی مولکول آن‌ها، رابطه مستقیم دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:18:25', 4, 'done'),
(6251, ' انحلال‌پذیری یک نمک در دمای معین برابر با 150 گرم است. اگر با تغییر دمای نیم کیلوگرم از محلول سیرشده این نمک، 50 درصد از نمک رسوب کند، انحلال‌پذیری نمک در دمای نهایی، کدام است؟ (فرض کنید با تغییر دما، جرم آب تغییری نمی‌کند.)', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:18:14', 4, 'done'),
(6252, ' چه تعداد از عبارت‌های زیر در مورد پیوند هیدروژنی درست است؟\n\n- پیوند هیدروژنی میان مولکول‌های آب، قوی‌تر از پیوند هیدروژنی میان مولکول‌های هیدروژن سولفید است.\n\n- پیوند هیدروژنی میان مولکول‌های آب، قوی‌تر از پیوند کووالانسی میان هیدروژن و اکسیژن است.\n\n- پیوند هیدروژنی را می‌توان قوی‌ترین جاذبه واندروالس بین مولکول‌ها دانست.\n\n- نیروهای بین‌مولکولی اتانول به‌دلیل تشکیل پیوند هیدروژنی، قوی‌تر از نیروهای بین‌مولکولی استون است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:18:04', 4, 'done'),
(6253, ' در کدام شرایط داده شده، انحلال‌پذیری گاز HCl در آب بیشتر است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:17:56', 4, 'done'),
(6254, ' شکل زیر مربوط به یک غشاء نیمه‌تراوا است. کدام گزینه درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:17:45', 4, 'done'),
(6255, ' کدام عبارت‌ها در مورد سدیم نیترات درست هستند؟\n\nالف) در آب، محلول و میانگین قدرت پیوند یونی در آن و پیوندهای هیدروژنی در آب، بزرگ‌تر از نیروی جاذبهٔ یون- دوقطبی است.\n\nب) در یک واحد فرمولی از این نمک، 3 پیوند اشتراکی وجود دارد.\n\nپ) رنگ شعلهٔ این ترکیب همانند رنگ شعلهٔ فلز سدیم، زرد است.\n\nت) در این نمک، همهٔ اتم‌ها به آرایش گاز نجیب رسیده‌اند.\n\nث) انحلال آن در آب در دماهای بالاتر، بهتر انجام می‌شود و می‌توان با افزایش دما، محلولی فراسیرشده از آن تهیه کرد.', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:17:32', 4, 'done'),
(6256, ' کدام مطلب درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:11:58', 1, '2026-03-21 20:17:17', 4, 'done'),
(6257, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:17:06', 4, 'done'),
(6258, 'در محلولی از سدیم کلرید با چگالی $1.25 g.mL^{-1}$، غلظت یون کلرید برابر با $7100 ppm$ است. اگر یک نمونه $2$ لیتری از این محلول را با $3$ لیتر محلول $0.5$ مولار سدیم کلرید مخلوط کنیم، غلظت مولی محلول نهایی برابر با چند $mol.L^{-1}$ شده و هر لیتر از این محلول، با چند لیتر محلول $0.8$ مولار نقره نیترات به طور کامل واکنش می‌دهد؟ ($Cl = 35.5 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:16:55', 4, 'done'),
(6259, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) طی مخلوط کردن $460$ گرم اتانول خالص با $90$ گرم آب، نوعی محلول آبی ایجاد می‌شود که همگن است.\n\nب) ماهی‌ها با عبور دادن آب از درون آبشش‌های خود، اکسیژن مولکولی حل شده در آب را جذب خواهند کرد.\n\nپ) بین ترکیب‌های هیدروژن‌دار عناصر گروه $17$، کمترین نقطه جوش متعلق به ترکیبی است که در معده ترشح می‌شود.\n\nت) با انحلال سدیم کلرید در آب، یون‌هایی با تعداد لایه الکترونی بیشتر، از سمت اتم $O$ مولکول‌های آب جذب می‌شوند.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:16:44', 4, 'done'),
(6260, 'در دمای $0^\\circ C$، حداکثر $12$ گرم گاز نیتروژن در فشار $8 atm$، در $60$ لیتر آب خالص حل می‌شود. اگر فشار محلول مورد نظر را به اندازه $2 atm$ کاهش بدهیم، در شرایط مورد نظر چند لیتر گاز از محلول خارج می‌شود؟ ($N = 14 : g.mol^{-1}$)', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:16:31', 4, 'done'),
(6261, 'کدام‌یک از مطالب زیر درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:16:21', 4, 'done'),
(6262, 'برای تولید محلولی از سدیم سولفات به جرم $5$ کیلوگرم و چگالی $1.25 g.mL^{-1}$ که غلظت یون سدیم در آن برابر $460 ppm$ باشد، به چند میلی‌لیتر محلول سدیم سولفات با غلظت $0.4$ مولار نیاز داشته و هر لیتر از محلول نهایی تولید شده با چند میلی‌لیتر محلول $0.5$ مولار باریم کلرید به طور کامل واکنش می‌دهد؟ ($Na = 23 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:15:54', 4, 'done'),
(6263, 'انحلال‌پذیری گاز $H_2S$ در دمای اتاق و در فشار $3$ اتمسفر برابر $1.02 g$ در $100$ گرم آب است. $301$ گرم محلول سیرشده از این ترکیب در دما و فشار اتاق، تقریبا با چند میلی‌لیتر محلول $0.2$ مولار آهن(II) سولفات واکنش کامل می‌دهد؟ ($Fe=56 , S=32 , O=16 , H=1 : g.mol^{-1}$)\n\n$FeSO_4(aq) + H_2S(aq) \\rightarrow FeS(s) + H_2SO_4(aq)$', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:15:35', 4, 'done'),
(6264, 'کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) استون به هر نسبتی در آب حل شده و در این فرایند، مولکول‌های حل‌شونده ماهیت خود را حفظ می‌کنند.\n\nب) تاثیر تغییر دما بر انحلال‌پذیری اکسیژن در آب، همانند تاثیر دما بر انحلال‌پذیری لیتیم سولفات است.\n\nپ) به ازای یک مقدار مشخص از افزایش فشار، انحلال‌پذیری گاز $N_2$ نسبت به $O_2$ بیشتر تغییر می‌کند.\n\nت) بیش از $50\\%$ آب موجود در بدن، بیرون سلول‌ها و باقی آن در مایع‌های درون سلولی جریان دارد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:15:20', 4, 'done'),
(6265, 'مخلوطی از منیزیم سولفات و مس(II) سولفات به جرم $60$ گرم را در مقداری آب حل کرده و حجم محلول را با استفاده از آب خالص به $8$ لیتر می‌رسانیم. اگر غلظت مولی آنیون در محلول نهایی برابر با $0.05$ مولار شده باشد، درصد جرمی مس در مخلوط نمک‌های اولیه چقدر بوده است؟ ($O=16 , Mg=24 , S=32 , Cu=64 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:15:01', 4, 'done'),
(6266, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:14:50', 4, 'done'),
(6267, 'در محلولی از منیزیم سولفات با چگالی $1.2 g.mL^{-1}$، غلظت $ppm$ یون منیزیم برابر با $5000$ واحد است. هر لیتر از این محلول آبی با چند میلی‌لیتر محلول $0.8$ مولار آمونیوم هیدروکسید به طور کامل واکنش می‌دهد؟ ($O=16 , Mg=24 , S=32 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:14:39', 4, 'done'),
(6268, '$100$ گرم محلول $21\\%$ جرمی سدیم کلرید را با $150$ گرم محلول $25\\%$ جرمی از این ماده مخلوط می‌کنیم. برای تهیه $3$ لیتر محلول آبی که غلظت مولی یون سدیم در آن برابر با $0.02$ مول بر لیتر باشد، باید چند گرم از محلول تولید شده را با مقدار کافی آب خالص مخلوط کنیم؟ ($Na=23 , Cl=35.5 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:14:30', 4, 'done'),
(6269, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:14:19', 4, 'done'),
(6270, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) منابع غیراقیانوسی، سهم کمی از آب‌های کره زمین را شامل شده و همه آن‌ها در دسته آب‌های شیرین قرار می‌گیرند.\n\nب) تهیه آب آشامیدنی و آب قابل استفاده در کشاورزی، صنعت و دیگر حوزه‌ها، یکی از چالش‌های اساسی در جهان است.\n\nپ) آمونیوم کربنات، یک ترکیب یونی چندتایی بوده و اتم‌های سازنده یون‌های آن، همگی در یک صفحه قرار می‌گیرند.\n\nت) کلسیم فسفات، یک ترکیب یونی نامحلول در آب بوده و نسبت شمار آنیون‌ها به کاتیون‌ها در آن برابر با $1.5$ است.\n\nث) هنگام تشکیل باران، تقریباً همه مواد حل‌شده در آب از آن جدا شده و نمونه‌ای از فرایند تقطیر انجام می‌شود.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:14:07', 4, 'done'),
(6271, 'کدام‌یک از مطالب زیر نادرست است؟ ($H=1 , C=12 , O=16 : g.mol^{-1}$)', 1, 3, 67, 317, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:13:55', 4, 'done'),
(6272, 'انحلال‌پذیری گاز اکسیژن در دمای $25^\\circ C$ و فشار $9$ اتمسفر برابر با $0.04$ گرم در $100$ گرم آب است. اگر فشار گاز اکسیژن بر روی یک محلول سیرشده $120$ کیلوگرمی از این گاز را از $6 atm$ به $3 atm$ برسانیم، با استفاده از گاز اکسیژن آزاد شده از محلول، چند گرم گاز متان را می‌توانیم به طور کامل بسوزانیم؟ ($H=1 , C=12 , O=16 : g.mol^{-1}$)', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:13:44', 4, 'done'),
(6273, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) آمونیوم سولفات، در ساختار خود فاقد اتم فلزی بوده و عناصر گوگرد و نیتروژن را در اختیار گیاهان قرار می‌دهد.\n\nب) خون، محلولی با خاصیت بازی بوده و هنگام بیماری، توازن غلظت برخی از گونه‌های موجود در آن به هم می‌خورد.\n\nپ) تبلور، از جمله روش‌های شیمیایی است که با استفاده از آن، سدیم کلرید موجود در آب دریا را می‌توان استخراج کرد.\n\nت) اگر در $1$ کیلوگرم از آب آشامیدنی $20$ میلی‌گرم یون فلوئورید وجود داشته باشد، غلظت این یون برابر $2 ppm$ می‌شود.\n\nث) حالت فیزیکی در سرتاسر محلول‌ها یکنواخت بوده و خواص این مواد به خواص حلال، حل‌شونده و مقدار آن‌ها بستگی دارد.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:13:35', 4, 'done'),
(6274, 'در فرایند تولید مقداری پتاسیم کلرید از عناصر سازنده آن، $3.612 \\times 10^{23}$ الکترون بین گونه‌ها مبادله شده است. در این واکنش، چند گرم گاز کلر مصرف شده و اگر در دمای آزمایش، مقدار انحلال‌پذیری پتاسیم کلرید برابر با $29.8$ گرم در $100$ گرم آب باشد، با استفاده از نمک تولید شده چند گرم محلول سیرشده می‌توان تهیه کرد؟ ($K=39 , Cl=35.5 : g.mol^{-1}$)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:13:22', 4, 'done'),
(6275, 'با قرار گرفتن مولکول‌های گاز $A$ در یک میدان الکتریکی، ذرات سازنده این ماده جهت‌گیری پیدا می‌کنند. اگر با انحلال این گاز در آب، محلولی ایجاد شود که رسانایی الکتریکی آن مشابه به محلول استون در آب باشد، ماده $A$ معادل با کدام‌یک از ترکیب‌های زیر می‌تواند باشد؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:12:58', 4, 'done'),
(6276, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:12:46', 4, 'done'),
(6277, 'کدام‌یک از مطالب زیر درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:12:27', 4, 'done'),
(6278, 'در محلول غلیظی از سدیم نیترات در آب، شمار اتم‌های اکسیژن $8$ برابر شمار یون‌های سدیم است. اگر چگالی این محلول آبی برابر با $1.75 g.mL^{-1}$ باشد، غلظت مولی نمک حل شده در این محلول چقدر خواهد بود؟ ($H=1$ و $N=14$ و $O=16$ و $Na=23 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:11:01', 4, 'done'),
(6279, 'در شرایط استاندارد، یک نمونه از گاز هیدروژن یدید به حجم $33.6$ لیتر را در مقداری آب حل کرده و حجم محلول را با استفاده از آب خالص به $640$ میلی‌لیتر می‌رسانیم. اگر چگالی محلول ایجاد شده برابر با $1.25 g.mL^{-1}$ باشد، درصد جرمی حل‌شونده در این محلول چقدر می‌شود؟ ($H=1$ و $I=127 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:10:46', 4, 'done'),
(6280, 'یک نمونه $500$ میلی‌لیتری از محلول مولار پتاسیم کلرید را با $2$ لیتر آب خالص مخلوط می‌کنیم. مقدار $400$ میلی‌لیتر از محلول تولید شده طی این فرایند، با چند لیتر محلول $0.05$ مولار نقره نیترات به طور کامل واکنش داده و طی این فرایند، چند گرم فراورده رسوبی تولید می‌شود؟ ($Cl=35.5$ و $Ag=108 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:10:32', 4, 'done'),
(6281, 'کدام موارد از عبارت‌های داده شده درست هستند؟\n\nآ) تنها ماده‌ای که به هر سه حالت جامد، مایع و گاز در طبیعت یافت می‌شود، از مولکول‌های Vشکل ساخته شده است.\n\nب) سیلیسیم تتراکلرید، در ساختار خود $8$ جفت الکترون ناپیوندی داشته و نسبت به متان دمای جوش بالاتری دارد.\n\nپ) بین نمونه‌هایی از $HF$ و $HCl$ مایع، ترکیبی با ثابت یونش اسیدی بزرگ‌تر، دمای جوش بالاتری خواهد داشت.\n\nت) اگر اتم‌های اکسیژن موجود در مولکول $CO_2$ را با اتم گوگرد جایگزین کنیم، دمای جوش آن افزایش می‌یابد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:08:28', 4, 'done'),
(6282, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:08:09', 4, 'done'),
(6283, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) بخش عمده از جرم بدن، توسط آب تشکیل شده و همین آب، در دفع مواد زائد تولید شده توسط سلول‌ها نقش دارد.\n\nب) نیروهایی که ذرات سازنده گازها به یکدیگر وارد می‌کنند، همانند پیوند هیدروژنی، نوعی نیروی بین مولکولی است.\n\nپ) استون با فرمول شیمیایی $C_3H_6O$، حلال برخی از چربی‌ها بوده طی این فرایند، محلول‌های غیرآبی ایجاد می‌شود.\n\nت) روزانه، کمتر از نیم لیتر از آب موجود در بدن توسط ادرار، تعرق پوستی و بخار آب موجود در بازدم، از دست می‌رود.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:07:44', 4, 'done'),
(6284, 'محلولی از منیزیم کلرید با درصد جرمی $1.9\\%$ و چگالی $1.25 g.mL^{-1}$ در اختیار داریم. غلظت مولی یون کلرید در این محلول برابر با چند مول بر لیتر بوده و آب موجود در $0.4$ لیتر از این محلول را بر اثر تجزیه چند گرم هیدروژن پراکسید می‌توان بدست آورد؟ ($H=1$ و $O=16$ و $Mg=24$ و $Cl=35.5 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:07:56', 4, 'done'),
(6285, 'نمودار مقابل، روند تغییر انحلال‌پذیری چند نمک در آب را نشان می‌دهد:\n\n\n\nبا توجه به داده‌های موجود در این نمودار، درصد جرمی محلول سیرشده پتاسیم نیترات در چه دمایی برابر با $20\\%$ بوده و اگر دمای $169$ گرم محلول سیرشده لیتیم سولفات را از $40^\\circ C$ به $10^\\circ C$ برسانیم، طی این فرایند چند گرم رسوب در کف محلول ته‌نشین می‌شود؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:07:27', 4, 'done'),
(6286, 'شمار جفت الکترون‌های ناپیوندی موجود در ساختار یون سولفات، .................... برابر شمار این جفت الکترون‌ها در مولکول .................... بوده و نحوه جهت‌گیری ذرات سازنده این یون در حضور یک میدان الکتریکی نیز مشابه به نحوه جهت‌گیری مولکول .................... در حضور یک میدان الکتریکی است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:07:16', 4, 'done'),
(6287, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:06:21', 4, 'done'),
(6288, 'معادله انحلال‌پذیری($S$) نمک $KClO_3$ در آب بر حسب تغییر دما($\\theta$) به صورت $S = 0.005 \\theta^2 + 6.5$ است. اگر $498$ گرم محلول سیرشده $KClO_3$ در دمای $60^\\circ C$ را با مقدار کافی محلول هیدروکلریک اسید وارد واکنش کنیم، چند لیتر گاز کلر با چگالی $2.84 g.L^{-1}$ تولید می‌شود؟ ($O=16$ و $Cl=35.5$ و $K=39 : g.mol^{-1}$)\n\nمعادله واکنش موازنه شود     $KClO_3(aq) + HCl(aq) \\rightarrow KCl(aq) + Cl_2(g) + H_2O(l)$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:05:59', 4, 'done'),
(6289, 'در یک نمونه $33.6$ گرمی از منیزیم کربنات، چند مول کاتیون وجود داشته و درصورت واکنش کامل این مقدار از ماده مورد نظر با $250$ میلی‌لیتر محلول $3.2$ مولار هیدروکلریک اسید($d = 1 g.mL^{-1}$)، درصد جرمی یون کلرید در محلول نهایی ایجاد شده تقریبا برابر با چند درصد می‌شود؟ ($H=1$ و $C=12$ و $O=16$ و $Mg=24$ و $Cl=35.5 : g.mol^{-1}$)\n\nمعادله واکنش موازنه شود     $MgCO_3(s) + HCl(aq) \\rightarrow MgCl_2(aq) + CO_2(g) + H_2O(l)$', 1, 3, 67, 318, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:05:47', 4, 'done'),
(6290, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:05:33', 4, 'done'),
(6291, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) ردپای آب، فقط شامل آب‌هایی می‌شود که هر فرد برای نوشیدن، نظافت و سایر فعالیت‌های روزانه استفاده می‌کند.\n\nب) با قرار دادن خیار در آب شور، مولکول‌های آب وارد یاخته‌های خیار شده و این میوه به تدریج متورم خواهد شد.\n\nپ) در دستگاه اسمز معکوس، محلول غلیظی تولید می‌شود که نسبت به آب شور اولیه، غلظت نمک کمتری دارد.\n\nت) حشره‌کش‌ها، آفت‌کش‌ها و فلزهای سمی، برخلاف میکروب‌های آب، توسط صافی کربن از آن جدا می‌شوند.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:05:18', 4, 'done'),
(6292, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:07:05', 4, 'done'),
(6293, '$0.05$ مول سدیم هیدروکسید را در مقداری آب حل کرده و حجم محلول مورد نظر را به اضافه کردن آب خالص به آن، به $5$ لیتر می‌رسانیم. اگر چگالی محلول حاصل از این فرایند برابر با $1.15$ گرم بر میلی‌لیتر شده باشد، غلظت یون سدیم در این محلول برابر با چند $ppm$ شده و هر لیتر از این محلول، با چند مول دی‌نیتروژن پنتاکسید واکنش می‌دهد؟\n\n($Na = 23 g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:04:59', 4, 'done'),
(6294, 'نام‌های ذکر شده در کدام دو ردیف از جدول زیر، برای همه‌ی گونه‌های داده شده به ترتیب از راست به چپ، درست است؟\n\n\n\nردیف ۱) فرمول شیمیایی ترکیب‌ها: $C_{10}H_8 - NaN_3 - KBr$ / نام ترکیب‌ها: پتاسیم برمید - سدیم نیترید - نفتالن\n\nردیف ۲) فرمول شیمیایی ترکیب‌ها: $COF_2 - Fe(NO_3)_2 - K_2S$ / نام ترکیب‌ها: پتاسیم سولفید - آهن($II$) نیترات - کربونیل فلوئورید\n\nردیف ۳) فرمول شیمیایی ترکیب‌ها: $N_2O - CO(NH_2)_2 - VO$ / نام ترکیب‌ها: وانادیم($II$) اکسید - اوره - دی‌نیتروژن مونوکسید\n\nردیف ۴) فرمول شیمیایی ترکیب‌ها: $N_2O_5 - Mn_3(PO_4)_4 - Li_2CO_3$ / نام ترکیب‌ها: لیتیم کربنات - منگنز($IV$) فسفات - نیتروژن پنتاکسید', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:06:51', 4, 'done'),
(6295, 'در $400$ گرم محلول آلومینیم سولفات، تفاوت شمار آنیون‌ها و کاتیون‌ها برابر $1.806 \\times 10^{21}$ است. اگر به این محلول، $142 mg$ سدیم سولفات جامد اضافه کنیم، غلظت یون سولفات در محلول نهایی چند $ppm$ خواهد بود؟ (از تغییر حجم محلول صرف‌نظر کرده و چگالی محلول را برابر $1 g.mL^{-1}$ در نظر بگیرید؛ $O = 16$ و $Na = 23$ و $S = 32 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:04:11', 4, 'done'),
(6296, 'تقریباً چند مول منیزیم نیترات را به $200$ گرم محلول منیزیم نیترات $\\%20w/w$ اضافه کنیم تا درصد جرمی نمک در محلول مورد نظر $2.5$ برابر حالت اولیه شود؟ ($N = 14$ و $O = 16$ و $Mg = 24 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:04:02', 4, 'done'),
(6297, 'کدام‌یک از عبارت‌های زیر درست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:10:18', 4, 'done'),
(6298, 'پاسخ درست پرسش‌های زیر در کدام گزینه آمده است؟ (فرمول شیمیایی آلومینیم پرمنگنات و آلومینیم کرومات، به ترتیب به صورت $Al(MnO_4)_3$ و $Al_2(CrO_4)_3$ است. $O = 16$ و $K = 39$ و $Cr = 52 : g.mol^{-1}$)\n\nآ) نسبت شمار اتم‌های فلزی به شمار اتم‌های نافلزی در پتاسیم پرمنگنات، چند برابر این نسبت در آمونیوم کرومات است؟\n\nب) تفاوت جرم عناصر فلزی و نافلزی موجود در $0.2$ مول پتاسیم کرومات، برابر با چند گرم می‌شود؟', 1, 3, 67, 317, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:03:49', 4, 'done'),
(6299, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:03:33', 4, 'done'),
(6300, 'چه تعداد از عبارت‌های زیر درست است؟\n\nآ) اغلب قنات‌ها و رودخانه‌ها داری آب شور بوده و به همین خاطر، از آن‌ها نمی‌توان در صنایع استفاده کرد.\n\nب) با دو برابر شدن جرم حلال موجود در یک محلول آبی، درصد جرمی حل‌شونده در آن محلول نصف می‌شود.\n\nپ) همه کاتیون‌های تک‌اتمی موجود در یک نمونه از آب آشامیدنی به آرایش الکترونی یک گاز نجیب رسیده‌اند.\n\nت) حدود نیمی از سدیم کلرید جداسازی شده از آب دریا، در تهیه گاز $Cl_2$، سدیم، سود سوزآور و گاز $H_2$ به کار می‌رود.\n\nث) منیزیم، عنصر فلزی از گروه دوم است که در تهیه آلیاژها و شربت‌معده کاربرد داشته و تنها منبع تهیه آن، آب دریا است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:03:23', 4, 'done'),
(6301, 'کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) زیست‌کره، شامل جانداران کره زمین شده و در واکنش‌های انجام شده در آن، درشت‌مولکول‌ها نقش اساسی ایفا می‌کنند.\n\nب) با انحلال هر مول آلومینیم سولفات در آب، همانند هر مول کلسیم هیدروکسید، دو مول آنیون وارد محلول خواهد شد.\n\nپ) نسبت میان شمار اتم‌ها به شمار عناصر در واحد فرمولی سدیم‌فسفات، $1.6$ برابر نمک منیزیم‌هیدروکسید است.\n\nت) نقره نیترات، یک ترکیب یونی چندتایی بوده و با انحلال در آب، یک محلول زرد رنگ را ایجاد می‌کند.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:03:08', 4, 'done'),
(6302, 'با حل کردن $0.2$ مول نمک $MSO_4$ در $108.8$ گرم آب خالص، محلول $20$ درصد جرمی از این نمک به دست می‌آید. درصد جرمی فلز $M$ در ترکیب حاصل از این فلز با یون فسفات، تقریباً چقدر می‌شود؟ ($O = 16$ و $S = 32 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:02:57', 4, 'done'),
(6303, 'نمونه‌ای از سدیم نیترات را بر اساس معادله موازنه نشده $NaNO_3(s) \\rightarrow Na_2O(s) + O_2(g) + N_2(g)$ تجزیه کرده و گازهای حاصل از این فرایند را در مقداری آب حل می‌کنیم تا محلولی به حجم $15L$ و چگالی $1.04 g.mL^{-1}$ بدست بیاید. اگر تفاوت غلظت $ppm$ گازهای اکسیژن و نیتروژن در محلول نهایی برابر با $250$ واحد باشد، جرم سدیم اکسید تولید شده طی این فرایند برابر با چند گرم می‌شود؟ ($N = 14$ و $O = 16$ و $Na = 23 : g.mol^{-1}$)', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:02:41', 4, 'done'),
(6304, 'نسبت شمار جفت الکترون‌های پیوندی به ناپیوندی در ساختار یون سولفات، مشابه به مقدار این نسبت در مولکول .................... بوده و ساختار فضایی این یون، مشابه به ساختار فضایی .................... است.', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:02:28', 4, 'done'),
(6305, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:02:16', 4, 'done'),
(6306, 'با توجه به واکنش‌های زیر، اگر $200 mL$ محلول $18.9\\%$ جرمی نیتریک اسید با چگالی $1 g.mL^{-1}$ با مقدار کافی گاز $NO$ واکنش دهد، چند گرم گاز $NO_2$ تشکیل شده و این مقدار گاز $NO_2$، در شرایط استاندارد با چند لیتر گاز کربن مونوکسید به طور کامل واکنش می‌دهد؟ ($H = 1$ و $N = 14$ و $O = 16 : g.mol^{-1}$)\n\nمعادله واکنش‌ها موازنه شود.\n\n$HNO_3(aq) + NO(g) \\rightarrow NO_2(g) + H_2O(l)$\n\n$NO_2(g) + CO(g) \\rightarrow N_2(g) + CO_2(g)$', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:01:47', 4, 'done'),
(6307, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:02:02', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6308, 'برای تهیه $2.5$ لیتر محلول سیرشده لیتیم سولفات با چگالی $1.1 g.mL^{-1}$ در دمای $70^\\circ C$، به چند مول از این ترکیب یونی نیاز داریم؟ (انحلال‌پذیری لیتیم سولفات در دمای $70^\\circ C$ برابر با $25$ گرم در $100$ گرم آب است.)\n\n($Li = 7$ و $O = 16$ و $S = 32 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:01:36', 4, 'done'),
(6309, 'چند مول آب از $216 mL$ محلول $53$ درصد جرمی سدیم کربنات با چگالی $1.2 g.mL^{-1}$ خارج شود تا غلظت مولی محلول مورد نظر به $8$ مولار برسد و با استفاده از این مقدار آب، چند گرم محلول $40\\%$ جرمی کلسیم کلرید می‌توان ایجاد کرد؟ (خروج آب از محلول اولیه، تاثیری بر چگالی این محلول ندارد. $H = 1$، $C = 12$، $O = 16$، $Na = 23 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:01:25', 4, 'done'),
(6310, 'کدام‌یک از مطالب زیر در مورد فراورده‌های واکنش روبه‌رو، نادرست است؟\n\n$CaCl_2(aq) + Na_2SO_4(aq) \\rightarrow \\cdots$', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:01:14', 4, 'done'),
(6311, 'محلول‌های مجزایی از منیزیم سولفات و آمونیوم نیترات با درصد جرمی و چگالی برابر در اختیار داریم. اگر تفاوت غلظت مولی کاتیون‌ها در این دو محلول برابر با $0.2 mol.L^{-1}$ باشد، نیم لیتر از محلول منیزیم سولفات با چند لیتر محلول $0.4$ مولار پتاسیم هیدروکسید به طور کامل واکنش خواهد داد؟\n\n($H = 1$ و $N = 14$ و $O = 16$ و $Mg = 24$ و $S = 32 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:10:03', 4, 'done'),
(6312, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) با کاهش دمای محلول سیرشده‌ای از پتاسیم نیترات، یک محلول فراسیرشده از این ماده بدست می‌آید.\n\nب) دستگاه‌های اندازه‌گیری قند خون، غلظت گلوکز را در مقیاس میلی‌گرم در هر لیتر خون نشان می‌دهند.\n\nپ) آب آشامیدنی محلولی زلال و همگن بوده و حاوی مقدار کمی از یون‌های سدیم، کلرید، هیدروکسید و ... است.\n\nت) گاز هیدروژن کلرید، یک اسید قوی بوده و یک نمونه از آن در مقایسه با گاز فلوئور، در دمای بالاتری میعان می‌شود.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:00:43', 4, 'done'),
(6313, 'کدام‌یک از مطالب زیر درست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:00:12', 4, 'done'),
(6314, 'اگر $0.25$ مول آمونیوم سولفات در یک نمونه $117$ گرمی از آب خالص حل شود، غلظت کاتیون برحسب $ppm$ و غلظت مولی تقریبی یون سولفات در محلول، به ترتیب از راست به چپ کدام است؟ (از تغییر حجم آب چشم‌پوشی شود.)\n\n($S = 32$ و $O = 16$ و $N = 14$ و $H = 1 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:59:53', 4, 'done'),
(6315, 'معادله‌ی انحلال‌پذیری لیتیم سولفات بر حسب تغییر دمای محلول به صورت $S = 33 - 0.15\\theta$ است. دمای محلول سیرشده‌ای از این ماده را از $20^\\circ C$ به اندازه $55^\\circ C$ افزایش داده و رسوب تولید شده را با $3$ لیتر محلول $0.5$ مولار باریم کلرید به طور کامل وارد واکنش می‌کنیم. جرم محلول اولیه لیتیم سولفات برابر با چند کیلوگرم بوده و در انتهای این فرایند، چند گرم رسوب تولید شده است؟ ($Li = 7$ و $O = 16$ و $S = 32$ و $Ba = 137 : g.mol^{-1}$)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:59:39', 4, 'done'),
(6316, 'کدام‌یک از عبارت‌های زیر در مورد یون فسفات درست است؟', 1, 3, 67, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:59:24', 4, 'done'),
(6317, 'نمودار مقابل را در نظر بگیرید:\n\n\n\nبا توجه به نمودار، تاثیر تغییر دما بر انحلال‌پذیری .................... مورد از مواد داده شده مشابه تاثیر دما بر انحلال‌پذیری لیتیم سولفات بوده و معادله انحلال‌پذیری .................... ماده را می‌توان به صورت $S = a\\theta + b$ نشان داد و نقطه‌ی A نیز یک محلول فراسیرشده از ترکیب .................... را نشان می‌دهد.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:58:57', 4, 'done'),
(6318, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) بین نمونه‌هایی از $PH_3$ ، آمونیاک و $AsH_3$، با افزایش جرم مولی، قدرت نیروهای بین مولکولی مرتباً افزایش می‌یابد.\n\nب) عضوی از خانواده هالوژن‌ها که در دمای اتاق حالت مایع دارد، در هر اتم خود دارای $18$ الکترون با $n=3$ است.\n\nپ) ذرات سازنده سیلیسیم تتراکلرید، برخلاف فسفر تری‌برمید در میدان الکتریکی جهت‌گیری پیدا نمی‌کند.\n\nت) بین دو ماده مولکولی با نقطه جوش بسیار نزدیک، ماده با جرم مولی بیشتر، قطبیت پایین‌تری دارد.\n\nث) از بین دو مولکول قطبی اتانول و استون، مولکولی با جرم مولی کمتر، نقطه جوش بالاتری دارد.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:58:41', 4, 'done'),
(6319, 'معادله انحلال‌پذیری نمک $M$ به صورت $S_M = 39 - 0.2\\theta$ است. برای تهیه آب مورد نیاز جهت ساختن $112.5$ گرم محلول سیرشده از این نمک در دمای $70^\\circ C$، باید چند گرم گاز متان را در حضور مقدار کافی گاز اکسیژن بسوزانیم و طی این فرایند، چند گرم گاز کربن دی‌اکسید تولید می‌شود؟ ($H = 1$ و $C = 12$ و $O = 16 : g.mol^{-1}$)', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 20:00:56', 4, 'done'),
(6320, 'درصد جرمی سدیم هیدروکسید در محلولی از این ماده با چگالی $1.05 g.mL^{-1}$ برابر با $20\\%$ است. غلظت مولی این محلول برابر با چند $mol.L^{-1}$ بوده و در صورت تبخیر شدن نیمی از آب موجود در این محلول، درصد جرمی حل‌شونده در آن چند برابر می‌شود؟ ($H = 1$ و $O = 16$ و $Na = 23 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:58:28', 4, 'done'),
(6321, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:58:17', 4, 'done'),
(6322, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:58:00', 4, 'done'),
(6323, 'درصد جرمی یون نیترات در محلولی از سدیم نیترات برابر با $12.4$ است. برای تهیه سدیم نیترات مورد نیاز جهت تولید $40$ لیتر گاز اکسیژن با چگالی $1.2 g.L^{-1}$ طی واکنش موازنه نشده $NaNO_3(s) \\rightarrow NaNO_2(s) + O_2(g)$، به چند کیلوگرم از این محلول نیاز داریم؟ ($N = 14$ و $O = 16$ و $Na = 23 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:57:23', 4, 'done'),
(6324, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) نیتروژن مونوکسید، از جمله گازهایی است که با آب واکنش داده و محیط را اسیدی می‌کند.\n\nب) بنزین، نوعی ترکیب آلی بوده و ماهیت نیروهای بین مولکولی در آن از نوع وان‌دروالسی است.\n\nپ) میزان قطبیت مولکول‌های آب و قدرت نیروهای بین مولکولی در آن، نزدیک به دو برابر ذرات $H_2S$ است.\n\nت) یون پتاسیم، در آب آشامیدنی یافت شده و غلظت آن در محلول مولار پتاسیم سولفات، برابر $2$ مول بر لیتر است.', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:57:09', 4, 'done'),
(6325, 'با افزودن چه تعداد از مواد زیر به آب، میانگین جاذبه در نمونه‌های مجزایی از ماده مورد نظر و آب، از جاذبه بین ذرات سازنده آن ماده و آب بیشتر است؟\n\nالف) نقره کلرید\n\nب) ید\n\nپ) لیتیم سولفات\n\nت) آمونیوم فسفات\n\nث) آهن($II$) هیدروکسید\n\nج) منیزیم هیدروکسید', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:57:39', 4, 'done'),
(6326, 'اگر تفاوت شمار کاتیون‌ها و آنیون‌ها در $400$ میلی‌لیتر از محلول آمونیوم سولفات برابر با $2.408 \\times 10^{21}$ باشد، با اضافه کردن $100$ میلی‌لیتر آب مقطر به این محلول، غلظت یون آمونیوم در محلول مورد نظر به اندازه چند $ppm$ تغییر می‌کند؟ (چگالی محلول را برابر با $1 g.mL^{-1}$ در نظر بگیرید؛ $H = 1$ و $N = 14$ و $O = 16$ و $S = 32 : g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:56:56', 4, 'done'),
(6327, 'کدام‌یک از مطالب زیر نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:56:40', 4, 'done'),
(6328, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) گاز $PH_3$ از مولکول‌های غیرمسطح ساخته شده و گشتاور دوقطبی آن در مقایسه با مولکول $NH_3$ کمتر است.\n\nب) همانند گاز $NO$، تاثیر دما بر انحلال‌پذیری نمک لیتیم سولفات، با معادله خطی با شیب منفی قابل توصیف است.\n\nپ) در محلول سرکه، همه ذرات حل‌شونده ویژگی‌های ساختاری خود را حفظ کرده و بین ذرات $H_2O$ قرار می‌گیرند.\n\nت) با افزایش درصد جرمی نمک‌های حل شده در یک نمونه آب دریا، انحلال‌پذیری گاز اکسیژن در آب افزایش می‌یابد.\n\nث) با بردن میله شیشه‌ای مالیده شده به موی سر به طرف باریکه آب، اتم $O$ مولکول آب به سمت میله جهت‌گیری می‌کنند.', 1, 3, 67, 319, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:56:00', 4, 'done'),
(6329, 'انحلال‌پذیری نمک $K_2Cr_2O_7$ در آب در دماهای $60^\\circ C$ و $80^\\circ C$ به ترتیب برابر $40 g$ و $70 g$ در $100 g$ آب است. اگر $425$ گرم از محلول سیرشده این ترکیب را از دمای $80^\\circ C$ تا دمای $60^\\circ C$ سرد کرده و رسوب حاصل از این فرایند را مطابق معادله زیر با هیدروکلریک اسید وارد واکنش کنیم، به طور تقریبی چند لیتر گاز در شرایط $STP$ آزاد خواهد شد؟\n\n($K = 39$ و $O = 16$ و $Cr = 52 : g.mol^{-1}$)\n\n$K_2Cr_2O_7(s) + 14HCl(aq) \\rightarrow 2CrCl_3(aq) + 3Cl_2(g) + 2KCl(aq) + 7H_2O(l)$', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:54:49', 4, 'done'),
(6330, 'در محلولی از سدیم کلرید با چگالی $1.25 g.mL^{-1}$، غلظت یون سدیم برابر با $4600 ppm$ است. یک نمونه‌ی $2$ لیتری از این محلول را با $3$ لیتر محلول $0.5$ مولار سدیم کلرید مخلوط می‌کنیم. غلظت مولی محلول نهایی برابر با چند $mol.L^{-1}$ شده و هر لیتر از این محلول، با چند میلی‌لیتر محلول $2$ مولار نقره نیترات به طور کامل واکنش می‌دهد؟ (حجم محلول نهایی را برابر با $5$ لیتر در نظر بگیرید. $Na = 23 g.mol^{-1}$)', 1, 3, 67, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:55:20', 4, 'done'),
(6331, 'کدام‌یک از مطالب زیر در رابطه با گاز کربن دی‌اکسید نادرست است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 21:27:47', 5, 'done'),
(6332, 'چند مورد از مطالب زیر، در مورد اسمز معکوس نادرست است؟\n\nآ) طی این فرایند، ذرات آب از محلول غلیظ به سمت محلول رقیق، به صورت خود به خودی حرکت می‌کند.\n\nب) توانایی تصفیه‌ی آن در آب، همانند صافی کربن بوده و در مقایسه با روش تقطیر، بیشتر است.\n\nپ) برخلاف روش تقطیر، میکروارگانیسم‌های مضر موجود در آب را نیز جداسازی می‌کند.\n\nت) در این فرایند، محلول غلیظ مصرف شده به مرور غلیظ‌تر خواهد شد.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:54:03', 4, 'done'),
(6333, 'مقایسه نقطه جوش کدام مواد به صورت نادرست نوشته شده است؟', 1, 3, 67, 319, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:53:49', 4, 'done'),
(6334, 'انحلال‌پذیری گاز هیدروژن سولفید در دمای $25^\\circ C$ و فشار $1.5atm$ برابر $0.51$ گرم در $100$ گرم آب است. $200$ گرم محلول سیرشده از این ترکیب در دمای $25^\\circ C$ و فشار $5atm$، تقریباً با چند میلی‌لیتر محلول $0.2$ مولار آهن($III$) سولفات مطابق با معادله زیر واکنش کامل می‌دهد؟ ($H=1$ و $O=16$ و $S=32$ و $Fe=56 : g.mol^{-1}$)\n\n$Fe_2(SO_4)_3(aq) + 4H_2S(aq) \\rightarrow 5S(s) + 2FeSO_4(aq) + 4H_2O(l)$', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:51:34', 4, 'done'),
(6335, 'شکل روبه‌رو، نمودار انحلال‌پذیری ($S$) سه گاز $N_2$، $O_2$ و $NO$ را بر حسب فشار ($P$) نمایش می‌دهد. کدام‌یک از موارد زیر با توجه به نمودار داده شده درست است؟', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:51:04', 4, 'done'),
(6336, 'چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) با افزودن مقدار اندکی ید به آب، برخلاف افزودن هگزان به آب، نوعی محلول همگن پدید می‌آید.\n\nب) با استفاده از صافی‌های کربن، برخلاف روش تقطیر، نمی‌توان فلزهای سمی موجود در آب را از آن جدا کرد.\n\nپ) با انداختن خیار در آب شور، مولکول‌های آب طی فرایند اسمز وارد سلول‌های خیار شده و خیار متورم می‌شود.\n\nت) در محلولی با غلظت $ppm$ برابر از یون‌های $Ca^{2+}$ و $Mg^{2+}$، غلظت مولی یون منیزیم بیشتر از یون دیگر خواهد بود.\n\nث) دیواره یاخته‌های گیاهی، روزنه‌های بسیار کوچکی دارد که به یون‌های مختلف از جمله یون سدیم اجازه عبور نمی‌دهند.', 1, 3, 67, 320, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-21 12:12:21', 1, '2026-03-21 19:50:35', 4, 'done'),
(6337, '۱- چه تعداد از موارد زیر، عبارت «عنصری از گروه ۱۴ که ..................» را به درستی کامل می‌کنند؟\n\n* دارای عدد اتمی ۵۰ است، در اثر ضربه تغییر شکل می‌دهد\n\n* دارای سطحی براق است، رسانایی الکتریکی بالایی دارد\n\n* حاصل $(n+l)$ بیرونی‌ترین زیرلایۀ آن برابر ۷ است، در واکنش با دیگر اتم‌ها الکترون از دست می‌دهد\n\n* سومین عنصر گروه محسوب می‌شود، شکننده بوده و رفتار شیمیایی آن همانند نافلزهاست', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, '2026-09-29 16:35:17', 4, 'free'),
(6338, '۲- کدام مطلب دربارۀ روندهای تناوبی در جدول دوره‌ای، نادرست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, '2026-09-29 16:36:24', 4, 'free'),
(6339, '۳- عنصرهای A، B، C، D و E، به ترتیب از راست به چپ، ۵ عنصر فلزی متوالی از یک دوره جدول دوره‌ای هستند. چه تعداد از نمودارهای زیر برای این عنصرها درست است؟ (فقط روند کلی کمیت‌ها مد نظر است.)\n\nواکنش‌پذیری\n\nA B C D E\n\nشمار لایه‌های الکترونی اشغال‌شده\n\nA B C D E\n\nشمار الکترون‌های ظرفیتی\n\nA B C D E\n\nشعاع اتمی\n\nA B C D E', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6340, '۴- با توجه به شکل‌های داده‌شده که واکنش سه عنصر نخست فلزهای قلیایی با گاز کلر را نشان می‌دهند، کدام موارد از مطالب زیر درست است؟\n\nالف) عنصر a شعاع اتمی بزرگ‌تری نسبت به شبه‌فلزهای گروه ۱۴ جدول دوره‌ای دارد.\n\nب) عنصر b با از دست دادن یک الکترون به آرایش هشت‌تایی گاز نجیب قبل از خود می‌رسد.\n\nپ) عنصر c با سومین فلز قلیایی خاکی جدول دوره‌ای، هم‌دوره است.\n\nت) مجموع عددهای اتمی عنصرهای b و c با عدد اتمی شبه‌فلز دورۀ سوم برابر است.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, '2026-09-29 16:59:44', 4, 'free'),
(6341, '۵- با توجه به جدول داده‌شده که مربوط به شرایط واکنش هالوژن‌های دوره‌های دوم تا پنجم جدول تناوبی با گاز هیدروژن است، کدام مطلب درست است؟\n\nهالوژن | شرایط واکنش با گاز هیدروژن | شعاع اتمی (pm)\n\nA | در دمای $۲۰۰^\\circ C$ هم به سرعت واکنش می‌دهد. | $r_1$\n\nX | در دمای بالاتر از $۴۰۰^\\circ C$ واکنش می‌دهد. | $r_2$\n\nZ | | ۹۹\n\nD | | ۱۱۴', 2, 3, 68, 404, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, '2026-09-29 17:03:24', 4, 'free'),
(6342, '۶- اگر آرایش الکترونی یون‌های $A^{2-}$، $B^{2+}$ و $X^{3+}$ به ترتیب به زیرلایه‌های $4p^6$، $3p^6$ و $3d^3$ ختم شود، چند مورد از مطالب زیر درست است؟\n\n* اختلاف عدد اتمی عنصرهای A و B برابر ۱۴ است.\n\n* آرایش الکترونی کاتیون در ترکیب $K_2O$ مشابه آرایش $B^{2+}$ است.\n\n* در آرایش الکترونی اتم X، هشت الکترون دارای $l=0$ هستند.\n\n* اتم A با نافلزی جامد و زردرنگ، هم‌گروه و با نافلزی مایع هم‌دوره است.\n\n* اتم X در دوره‌ای قرار دارد که در این دوره هشت عنصر دارای ۱۰ الکترون با $l=2$ هستند.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, '2026-09-29 17:01:21', 4, 'free'),
(6343, '۷- کدام موارد از مطالب زیر دربارۀ عنصر واسطه‌ای از دورۀ چهارم که حاصل $(n+l)$ الکترون‌های ظرفیتی آن برابر ۲۳ است، درست است؟\n\nالف) شمار الکترون‌های ظرفیت آن با سیزدهمین عنصر دستۀ p جدول دوره‌ای برابر است.\n\nب) دارای دو کاتیون پایدار $A^{2+}$ و $A^{3+}$ است.\n\nپ) پنجمین عنصر دورۀ چهارم جدول دوره‌ای محسوب می‌شود.\n\nت) ترکیب‌های آن برخلاف عنصر $_{۲۸}X$، رنگی است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6344, '۸- کدام موارد از مطالب زیر نادرست است؟\n\nالف) بازتاب زیاد پرتوهای خورشیدی، رسانایی الکتریکی بالا در شرایط دمایی گوناگون، چکش‌خوار و سخت بودن از جمله ویژگی‌های طلا است.\n\nب) فلزی که در سطح جهان بیشترین مصرف سالانه را در بین صنایع گوناگون داراست، اغلب در طبیعت به شکل اکسید یافت می‌شود.\n\nپ) در میان فلزها تنها استخراج طلا از خاک معدن هماهنگ با توسعۀ پایدار است.\n\nت) برخی عنصرها مانند سدیم و اکسیژن به دلیل واکنش‌پذیری بالا، به شکل آزاد در طبیعت وجود ندارند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6345, '۹- با توجه به واکنش‌های داده‌شده، کدام گزینه درست است؟\n\nI) $FeCl_2(aq) + NaOH(aq) \\rightarrow Fe(OH)_2(s) + NaCl(aq)$\n\nII) $Fe(s) + CuSO_4(aq) \\rightarrow FeSO_4(aq) + Cu(s)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6346, '۱۰- با توجه به واکنش‌های داده‌شده، چند مورد از مطالب زیر درست است؟\n\n(A، B و C فلز هستند و X نافلزی است که آنیون دو بار منفی تشکیل می‌دهد.)\n\nالف) $AX + B \\rightarrow$ انجام نمی‌شود.\n\nب) $AX + ۲C \\rightarrow C_۲X + A$\n\n* مقایسۀ دشواری استخراج فلزها از سنگ معدن آن‌ها به صورت $B > A > C$ است.\n\n* اگر A فلزی اصلی و از دورۀ چهارم جدول تناوبی باشد، B می‌تواند عنصر واسطۀ هم‌دوره با آن باشد.\n\n* واکنش فلز B با نمک فلز C، به طور طبیعی انجام می‌شود.\n\n* A، B و C به ترتیب می‌توانند آهن، نقره و منیزیم باشند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6347, '۱۱- اگر نسبت شمار آنیون‌ها به کاتیون‌ها در مخلوطی از آهن (II) اکسید و آهن (III) اکسید برابر $۱/۲۵$ باشد، درصد خلوص نمونه برحسب آهن (III) اکسید به تقریب کدام است؟ ($Fe = ۵۶, O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6348, '۱۲- دانشجویی در آزمایشگاه، آهن (III) اکسید را با مقدار کافی کربن در شرایط مناسب وارد واکنش کرده و نتیجۀ زیر را به دست آورده است. با توجه به این آزمایش، چند مورد از مطالب زیر را می‌توان استنباط کرد؟\n\n$۲Fe_۲O_۳(s) + ۳C(s) \\rightarrow ۴Fe(s) + ۳CO_۲(g)$\n\n($Fe = ۵۶, O = ۱۶ : g.mol^{-۱}$)\n\nجرم واکنش‌دهنده $Fe_۲O_۳$ (گرم) | جرم آهن به‌دست‌آمده (گرم)\n\n۴۰ | ۱۹/۶\n\n* ۱۲ گرم از آهن (III) اکسید وارد واکنش نشده است.\n\n* خلوص نمونۀ آهن (III) اکسید برابر ۷۰ درصد بوده است.\n\n* دانشجو نتوانسته است ۸/۴ گرم از آهن تولیدشده را جداسازی و جمع‌آوری کند.\n\n* با انجام واکنش، حداقل ۵/۸۸ لیتر گاز کربن دی‌اکسید در شرایط STP تولید شده است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6349, '۱۳- اگر مطابق واکنش زیر، به ازای مصرف ۱۴۶ گرم HCl، ۶ لیتر گاز تولید شود، بازده درصدی واکنش کدام است و طی این فرایند، چند گرم آب تولید می‌شود؟ (حجم مولی گازها در شرایط واکنش، ۲۴ لیتر است.)\n\n($Cl = ۳۵/۵, O = ۱۶, H = ۱ : g.mol^{-۱}$)\n\n$KMnO_۴(s) + HCl(aq) \\rightarrow KCl(aq) + MnCl_۲(aq) + Cl_۲(g) + H_۲O(l)$ (معادلۀ موازنه شود.)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6350, '۱۴- فلز مس را علاوه بر سنگ معدن می‌توان از گیاهان (گیاه‌پالایی) نیز استخراج کرد. با توجه به جدول داده‌شده، برای این‌که میزان فلز مس استخراج‌شده از ۱۰ تن سنگ معدن با میزان فلز استخراج‌شده از گیاه‌پالایی برابر باشد، به چند متر مربع زمین برای کاشت گیاه نیاز است؟ (فرض کنید ۸۴ درصد فلز موجود در سنگ معدن قابل استخراج است و در هر هکتار زمین، می‌توان ۲۰ تن گیاه برداشت کرد و هر هکتار معادل با ده هزار متر مربع است.)\n\nدرصد فلز مس در سنگ معدن | بیشترین مقدار فلز در یک کیلوگرم گیاه (گرم)\n\n۰/۵ | ۱۴', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6351, '۱۵- مالتوز ($M = ۳۴۲ g.mol^{-۱}$)، مطابق واکنش: $C_{۱۲}H_{۲۲}O_{۱۱}(aq) + H_۲O(l) \\rightarrow ۲C_۶H_{۱۲}O_۶(aq)$\n\nبه گلوکز تبدیل می‌شود. اگر نیمی از گلوکز تولیدشده در این واکنش به ازای مصرف $۶۸/۴$ گرم مالتوز، در واکنش:\n\n$C_۶H_{۱۲}O_۶(aq) \\rightarrow ۲C_۲H_۵OH(aq) + ۲CO_۲(g)$ مصرف شود، چند گرم اتانول تولید خواهد شد؟ (بازده واکنش‌های انجام‌شده را به ترتیب برابر با ۴۰ و ۷۵ درصد در نظر بگیرید، $O = ۱۶, C = ۱۲, H = ۱ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6352, '۱۶- دو نمونۀ ناخالص پتاسیم نیترات با جرم برابر، در دو ظرف وارد شده و واکنش‌های زیر انجام می‌شود:\n\nI) $۴KNO_۳(s) \\rightarrow ۲K_۲O(s) + ۲N_۲(g) + ۵O_۲(g)$\n\nII) $۲KNO_۳(s) \\rightarrow ۲KNO_۲(s) + O_۲(g)$\n\nاگر پس از انجام واکنش‌ها، میزان کاهش جرم مادۀ جامد در دو ظرف برابر باشد، درصد خلوص پتاسیم نیترات واردشده به ظرف (I)، چند برابر درصد خلوص پتاسیم نیترات واردشده به ظرف (II) است؟ ($K = ۳۹, O = ۱۶, N = ۱۴ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6353, '۱۷- چند مورد از مطالب زیر، دربارۀ فلزها و منابع آن‌ها درست است؟\n\n* با توجه به فرایند استخراج فلزها و بازگشت آن‌ها به طبیعت با فرایند خوردگی و فرسایش، فلزها جزء منابع تجدیدپذیر محسوب می‌شوند.\n\n* غلظت گونه‌های فلزی موجود در کف اقیانوس‌ها نسبت به ذخایر زمینی آن‌ها بیشتر است.\n\n* در استخراج فلزها تنها درصد کمی از سنگ معدن به فلز تبدیل می‌شود.\n\n* بازیافت فلزها نسبت به استخراج آن‌ها از سنگ معدن، با تولید گازهای گلخانه‌ای کم‌تر، ولی از بین رفتن بیشتر گونه‌های زیستی همراه است.\n\n* گونه‌های فلزی بستر دریاها، در برخی مناطق حاوی سولفید چندین فلز واسطه و در برخی مناطق دیگر به صورت کلوخه‌ها و پوسته‌هایی غنی از فلزهای دیگر یافت می‌شوند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6354, '۱۸- چه تعداد از مقایسه‌های زیر دربارۀ آلکان‌های راست‌زنجیری با مشخصات داده‌شده، درست است؟\n\n($C = ۱۲, H = ۱ : g.mol^{-۱}$)\n\nI) آلکانی با نسبت شمار اتم‌های هیدروژن به کربن برابر $۲/۵$\n\nII) آلکانی با ۲۵ پیوند اشتراکی\n\nIII) آلکانی با جرم مولی $۸۶ g.mol^{-۱}$\n\n* قدرت نیروهای بین مولکولی: $I > III > II$\n\n* تمایل به جاری‌شدن در حالت مایع: $I > II > III$\n\n* تفاوت نقطۀ جوش: $(I و II) < (III و I)$\n\n* شمار پیوندهای $C - H$: $III > II > I$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6355, '۱۹- اگر فرمول مولکولی ترکیب: $(C_۲H_۵)_۲CH(CH_۲)_xC(CH_۳)_۳$ با ۵- متیل دکان یکسان باشد، نام این ترکیب کدام است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6356, '۲۰- چند مورد از مطالب زیر، درست است؟\n\n* وازلین و گریس را به ترتیب می‌توان آلکان‌هایی با ۱۸ و ۲۵ اتم کربن در نظر گرفت.\n\n* قرار دادن فلزها در آلکان‌های مایع سبب خوردگی آن‌ها می‌شود.\n\n* نام آلکانی با ساختار پیوند-خط [شکل] ، ۴- اتیل - ۳- متیل هگزان است.\n\n* در آلکان‌های راست‌زنجیر ۱ تا ۵ کربنی، پیشوندی که شمار اتم‌های کربن را معلوم کند، وجود ندارد.\n\n* همۀ هیدروکربن‌ها از دو عنصر کربن و هیدروژن تشکیل شده‌اند؛ از این‌رو رفتار مشابهی دارند.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, '2026-10-01 10:27:13', 4, 'free'),
(6357, '۲۱- در برج تقطیر نفت خام، از بالا به پایین، دما .................... می‌یابد و از قسمت‌های بالاتر برج، مولکول‌هایی با .................... بیشتر خارج می‌شوند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6358, '۲۲- کدام مطلب دربارۀ دومین عضو خانوادۀ آلکین‌ها، نادرست است؟ ($H = ۱ , C = ۱۲ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6359, '۲۳- $m$ گرم از یک آلکن با $۴/۴۸$ لیتر گاز هیدروژن در شرایط STP به طور کامل واکنش داده و به ۲، ۲- دی‌متیل پنتان تبدیل می‌شود. $m$ کدام است و کدام ساختار را می‌توان به آلکن مورد نظر نسبت داد؟ ($H = ۱ , C = ۱۲ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6360, '۲۴- اگر در ساختار یک هیدروکربن حلقوی با دو حلقۀ شش‌ضلعی و ۳ پیوند دوگانه، نسبت شمار اتم‌های کربن به شمار اتم‌های هیدروژن برابر $۰/۷۵$ باشد، کدام موارد از مطالب زیر، در رابطه با این هیدروکربن به یقین درست است؟\n\n(در ساختار هیدروکربن مورد نظر، پیوند سه‌گانه وجود ندارد.)\n\nالف) فرمول مولکولی آن $C_{۱۵}H_{۲۰}$ است.\n\nب) در ساختار آن، دو اتم کربن وجود دارند که به هیچ اتم هیدروژنی متصل نیستند.\n\nپ) شمار اتم‌های هیدروژن در فرمول مولکولی آن، با مجموع شمار اتم‌ها در فرمول مولکولی یک آلکین ۶ کربنه، برابر است.\n\nت) بر اثر سوختن کامل $۰/۵$ مول از آن، $۱۳۴/۴$ لیتر گاز $CO_۲$ در شرایط STP آزاد می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6361, '۲۶- چند مورد از مطالب زیر درست است؟ ($H = ۱ , C = ۱۲ : g.mol^{-۱}$)\n\n* شمار اتم‌های هیدروژن در نمونه‌هایی به جرم یکسان از ۲ - پنتن و ۱ - بوتین، با هم برابر است.\n\n* جداکردن نمک‌ها، اسیدها و آب از نفت خام، پس از پالایش نفت خام در برج تقطیر صورت می‌گیرد.\n\n* هگزان و ۱ - هگزن دو مایع بی‌رنگ هستند و آن‌ها را به روش شیمیایی نمی‌توان از هم شناسایی کرد.\n\n* سوخت هواپیما به طور عمده از نفت سفید که مخلوطی از آلکان‌هاست، تهیه می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:29', 1, NULL, NULL, 'free'),
(6362, 'با توجه به داده‌های جدول زیر که «برآورد مقدار برخی عنصرها در جهان» را نشان می‌دهد، به دو پرسش بعدی پاسخ دهید.\r\n\r\n\r\n\r\n| $_{82}\\text{Pb}$ | $_{50}\\text{Sn}$ | $_{29}\\text{Cu}$ | $_{49}\\text{In}$ | $_{92}\\text{U}$ | $_{22}\\text{Ti}$ | عنصر |\r\n\r\n|---|---|---|---|---|---|---|\r\n\r\n| $1/44 \\times 10^8$ | $1/12 \\times 10^7$ | $9/37 \\times 10^8$ | $6/0 \\times 10^3$ | $3/30 \\times 10^6$ | $1/53 \\times 10^5$ | مقدار (تن) |\r\n\r\n\r\n\r\n۱- در رابطه با این عنصرها، چه تعداد از مطالب زیر، نادرست‌اند؟\r\n\r\n- هیچ دو عنصری، در یک گروه از جدول دوره‌ای قرار ندارند.\r\n\r\n- تنها یکی از این عنصرها، با گاز نجیب کریپتون، هم‌دوره است.\r\n\r\n- هیچ یک از این عنصرها، به دستهٔ f جدول دوره‌ای تعلق ندارد.\r\n\r\n- در نوشتن آرایش الکترونی فشردهٔ اتم نیمی از این عنصرها، از گاز نجیب آرگون استفاده می‌شود.', 2, 3, 68, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:39:39', 4, 'done'),
(6363, 'اگر شمار اتم‌های تشکیل دهندهٔ عنصری که کمترین مقدار را به خود اختصاص داده، برابر با $3/16 \\times 10^{31}$ باشد، جرم یک مول از این عنصر، به تقریب، برابر با چند گرم است؟', 2, 3, 68, 277, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:39:47', 4, 'done'),
(6364, ' واکنش تخمیر بی‌هوازی گلوکز، منجر به تشکیل اتانول و گاز کربن دی‌اکسید می‌شود. گاز حاصل از تخمیر ۳ تن گلوکز با بازده ۶۰ درصد را، از سوختن کامل چند کیلوگرم سیکلوهگزان، می‌توان به‌دست آورد؟\n\n($1 \\text{ mol H} = 1 \\text{ g H} , 1 \\text{ mol C} = 12 \\text{ g C} , 1 \\text{ mol O} = 16 \\text{ g O}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:39:52', 4, 'done'),
(6365, ' کدام مطلب دربارهٔ هیدروکربنی با فرمول «نقطه ـ خط» روبه‌رو، درست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:39:57', 4, 'done'),
(6366, ' با توجه به داده‌های جدول زیر که در آن، درصد اجزای سازندهٔ چهار نوع نفت خام «A، B، C و D» مقایسه شده‌اند، کدام مطلب درست است؟\n\n\n\n| نوع نفت خام | بنزین و خوراک پتروشیمی | گازوئیل | نفت سفید | نفت کوره |\n\n|---|---|---|---|---|\n\n| A | ۲۱ | ۲۰ | ۱۳ | ۴۶ |\n\n| B | ۲۱ | ۲۱ | ۱۵ | ۴۳ |\n\n| C | ۲۳ | ۲۴ | ۱۵ | ۳۸ |\n\n| D | ۱۸ | ۱۸ | ۱۱/۵ | ۵۲/۵ |', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:02', 4, 'done'),
(6367, ' فرمول شیمیایی ترکیبی $C_{57}H_xO_6$ است. اگر گرمای لازم برای افزایش دمای یک گرم و یک مول از آن، به اندازهٔ یک کلوین، به ترتیب برابر با ۱/۹۷ و ۱۷۴۱/۴۸ ژول باشد، مقدار x کدام است؟\n\n$(1 \\text{ mol H} = 1 \\text{ g H} , 1 \\text{ mol C} = 12 \\text{ g C} , 1 \\text{ mol O} = 16 \\text{ g O})$', 2, 3, 68, 285, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:08', 4, 'done'),
(6368, ' کدام مطلب، نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:14', 4, 'done'),
(6369, ' با توجه به نمودار زیر که مربوط به عنصرهای هم دوره با گاز نجیب آرگون می‌باشد، کدام مطلب درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:20', 4, 'done'),
(6370, ' دربارهٔ عنصر طلا با آرایش الکترونی فشردهٔ $[_{54}Xe] 4f^{14} 5d^{10} 6s^1$، چند مورد از مطالب زیر، نادرست است؟\n\n- با محلول آبی حاوی یون‌های منیزیم واکنش می‌دهد.\n\n- در دورهٔ ششم جدول دوره‌ای عنصرها قرار داشته و با عنصر روی، هم گروه است.\n\n- رسانایی الکتریکی بالایی داشته و در شرایط دمایی گوناگون، این ویژگی را حفظ می‌کند.\n\n- مجتمع طلای زرشوران در اصفهان و موته در آذربایجان غربی، از معادن استخراج این عنصر در ایران هستند.', 2, 3, 68, 280, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:24', 4, 'done'),
(6371, ' اگر در واکنش ترمیت که معادلهٔ آن به صورت $2Al(s) + Fe_2O_3(s) \\rightarrow Al_2O_3(s) + 2Fe(l)$ است، به جای آهن (III) اکسید، از وانادیم (V) اکسید استفاده شود، با استفاده از چند گرم وانادیم (V) اکسید با خلوص ۹۶/۲ درصد، می‌توان ۳۷/۷۴ گرم فلز وانادیم به‌دست آورد؟ $(O=16 , V=51 : g.mol^{-1})$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:28', 4, 'done'),
(6372, ' با توجه به فرمول نقطه ـ خط هیدروکربن‌های زیر، چند مورد از مطالب پیشنهاد شده، درست است؟\n\n- ترکیب (۳) با مونومر تشکیل دهندهٔ پلی‌استیرن همپار است.\n\n- ترکیب‌های (۱) و (۲)، دارای فرمول مولکولی یکسان هستند.\n\n- در یکی از این ترکیب‌ها، برخلاف دو ترکیب دیگر، عدد اکسایش اتم‌های کربن برابر است.\n\n- شمار اتم‌های تشکیل دهندهٔ ترکیب (۱)، پنج واحد بیشتر از شمار اتم‌های تشکیل دهندهٔ پارازایلن است.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:32', 4, 'done'),
(6373, ' با توجه به عدد اتمی عنصرهای داده شده، کدام عنصر جزو فلزهای اصلی است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:36', 4, 'done'),
(6374, ' نام درست آلکانی با فرمول\n\n$CH_3 - CH - CH_2 - CH_2 - CH_3$\n\n$|$\n\n$CH_2 - CH_3$\n\n، کدام است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:40', 4, 'done'),
(6375, ' یک نمونه ناخالص از $CdCO_3$ به وزن ۱۰۷/۵ گرم، در اثر تجزیهٔ گرمایی کامل، ۱۱/۲ لیتر گاز در شرایط STP تولید می‌کند. درصد خلوص $CdCO_3$ کدام است؟ (ناخالصی در اثر گرما تجزیه نمی‌شود. $Cd=112 , O=16 , C=12 : g.mol^{-1}$)\n\n$CdCO_3(s) \\rightarrow CdO(s) + CO_2(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:44', 4, 'done'),
(6376, ' چگالی یک گاز در شرایط STP برابر $2/5 g.L^{-1}$ است. ۰/۰۵ مول از آن در این شرایط، به ترتیب از راست به چپ، چند گرم جرم و چند لیتر حجم دارد؟', 2, 3, 68, 315, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:00', 4, 'done'),
(6377, ' مجموع ضریب‌های استوکیومتری مواد پس از موازنهٔ معادلهٔ واکنش زیر، کدام است و اگر در این واکنش ۰/۵ مول نیتریک اسید مصرف شود، چند مول $PbO_2(s)$، تشکیل می‌شود؟\n\n$Pb_3O_4(s) + HNO_3(aq) \\rightarrow Pb(NO_3)_2(aq) + PbO_2(s) + H_2O(l)$', 2, 3, 68, 313, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:10', 4, 'done'),
(6378, ' از واکنش برم مایع با اتن، کدام ترکیب به دست می‌آید؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:15', 4, 'done'),
(6379, ' اگر ۲/۴ گرم اکسیژن در واکنش تبدیل به اوزون شرکت کند، چند مولکول اوزون به وجود می‌آید؟\n\n$(O=16: g.mol^{-1})$', 2, 3, 68, 314, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:21', 4, 'done'),
(6380, ' در مولکول ۲، ۲، ۵ - تری‌متیل هگزان، چند اتم کربن هر یک به سه اتم هیدروژن متصل‌اند؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:26', 4, 'done'),
(6381, ' با افزایش طول زنجیر هیدروکربنی در الکل‌ها، .......... غلبه می‌کند و ویژگی ناقطبی الکل ............... می‌یابد.', 2, 3, 68, 307, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:31', 4, 'done'),
(6382, ' کدام عنصر در گروه چهاردهم جدول دوره‌ای، در اثر ضربه تغییر شکل می‌دهد، اما خرد نمی‌شود و رسانایی گرمایی و الکتریکی بالایی دارد؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:36', 4, 'done'),
(6383, ' اگر بازده درصدی واکنش: $C_2H_4(g) + H_2O(l) \\xrightarrow{H_2SO_4} C_2H_5OH$ برابر ٪۸۵ باشد، از هر لیتر گاز $C_2H_4$ در شرایط استاندارد، به تقریب چند گرم اتانول به دست می‌آید؟ $(C_2H_5OH = 46 \\text{ g.mol}^{-1})$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:41', 4, 'done'),
(6384, ' از سوختن کامل ۲/۲۵ مول از یک آلکن راست زنجیر، ۱۲۱/۵ گرم آب به دست آمده است. تعداد اتم‌های هیدروژن این هیدروکربن، کدام است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:47', 4, 'done'),
(6385, ' کدام مطلب در مورد فراوردهٔ حاصل از واکنش گاز اتن با برم مایع، نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:52', 4, 'done'),
(6386, ' چه تعداد از عبارت‌های زیر، درست‌اند؟\n\n* نفت خام مخلوطی از هیدروکربن‌های گوناگون، برخی نمک‌ها، اسیدها، آب و... است.\n\n* هر گاه مقدار متان در هوای معدن به بیش از ۵ درصد برسد، احتمال انفجار وجود دارد.\n\n* زغال سنگ می‌تواند به عنوان سوخت، جایگزین نفت شود.\n\n* حدود ۶۶ درصد انتقال سوخت به مراکز توزیع، از طریق خطوط لوله انجام می‌شود.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:09:57', 4, 'done'),
(6387, ' کدام مقایسه در مورد روند واکنش‌پذیری عنصرهای دوره دوم جدول دوره‌ای عنصرها در شرایط یکسان، درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:03', 4, 'done'),
(6388, 'عنصرهای A و B متعلق به تناوب سوم بوده و از واکنش میان آنها، یک ترکیب یونی تولید می‌شود که فرمول شیمیایی آن شامل چهار اتم است. کدام گزینه در مورد عنصرهای A و B درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:10', 4, 'done'),
(6389, ' کدام گزینه نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:16', 4, 'done'),
(6390, ' کدام نامگذاری مطابق قواعد آیوپاک نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:21', 4, 'done'),
(6391, ' کدام گزینه نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:27', 4, 'done'),
(6392, ' گازهای خروجی از نیروگاه‌ها را از روی کلسیم اکسید عبور می‌دهند تا با گاز گوگرد دی‌اکسید واکنش داده، آن را به دام اندازد. اگر کلسیم اکسید ۳۵٪ خالص با گاز گوگرد دی‌اکسید به طور کامل واکنش بدهد، چند درصد بر جرم آن افزوده می‌شود؟ ناخالصی‌ها در واکنش شرکت نمی‌کنند.\n\n$(Ca=40, S=32, O=16: gmol^{-1})$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:33', 4, 'done'),
(6393, ' چه تعداد از ترکیب‌های a تا c با ترکیب (شکل وسط)، همپار است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:38', 4, 'done'),
(6394, ' برای سوختن کامل ۰/۲ مول از یک هیدروکربن سیرشده، ۳۲ گرم اکسیژن لازم است. این هیدروکربن کدام است؟ (معادلهٔ موازنه نشدهٔ عمومی سوختن هیدروکربن‌های سیر شده به این صورت است:\n\n$(O=16g.mol^{-1} : C_nH_{2n+2}(g) + O_2(g) \\longrightarrow CO_2(g) + H_2O(g)$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:43', 4, 'done'),
(6395, '۳۴- اگر در یک لولهٔ آزمایش تولید آمونیاک تحت شرایط ویژه، با توجه به جدول زیر، از واکنش ۳ مول گاز هیدروژن با مقدار کافی $N_2$، ۶/۸ گرم آمونیاک تولید شود، واکنش در کدام دما بر حسب درجهٔ سلسیوس، انجام شده است؟\r\n\r\n$(NH_3=17g.mol^{-1} ; N_2(g) + 3H_2(g) \\longrightarrow 2NH_3(g))$\r\n\r\n| دما ($^\\circ C$) | ۱۰۰ | ۲۰۰ | ۳۰۰ | ۴۰۰ |\r\n\r\n|---|---|---|---|---|\r\n\r\n| بازدهٔ درصدی | ۱۰ | ۱۵ | ۲۰ | ۲۵ |', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-03-28 14:15:44', 5, 'done'),
(6396, ' با توجه به معادلهٔ واکنش $C_8H_{10} + 4KMnO_4 \\xrightarrow{\\Delta} C_8H_6O_4 + 4MnO_2 + 4KOH$، اگر بازدهٔ واکنش ۶۰ درصد باشد، به تقریب چند گرم $C_8H_{10}$ با خلوص ۷۴ درصد برای تهیهٔ ۷۵ گرم $C_8H_6O_4$ خالص، نیاز است؟', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:48', 4, 'done'),
(6397, ' با افزایش عدد اتمی در گروه اول جدول دوره‌ای، چه تعداد از موارد زیر، کاهش می‌یابد؟\n\n* شعاع اتمی\n\n* جرم اتمی میانگین\n\n* واکنش‌پذیری\n\n* نسبت شمار الکترون ظرفیتی به شمار پروتون', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:40:49', 4, 'done'),
(6398, ' از واکنش ۴۶ گرم از آمونیوم دی هیدروژن فسفات ($(NH_4)H_2PO_4$)، که به صورت صنعتی به عنوان کود در کشاورزی استفاده می‌شود، با مقدار کافی از محلول سدیم هیدروکسید در شرایط استاندارد، ۵/۶ لیتر فرآوردهٔ گازی تولید شده است. درصد خلوص این کود شیمیایی، کدام است؟\n\n$(P=31, O=16, N=14, H=1: g.mol^{-1}) : (NH_4)H_2PO_4(s) + 3NaOH(aq) \\longrightarrow Na_3PO_4(aq) + 3H_2O(l) + NH_3(g))$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:55', 4, 'done'),
(6399, ' ۵۰۰ میلی‌لیتر محلول هیدروکلریک اسید ۰/۲ مولار با چند گرم آهن با خلوص ۸۰ درصد به طور کامل واکنش می‌دهد؟ (ناخالصی‌ها وارد واکنش نمی‌شوند، معادله موازنه شود: $Fe=56g.mol^{-1} : Fe(s) + HCl(aq) \\longrightarrow FeCl_2(aq) + H_2(g)$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:10:59', 4, 'done'),
(6400, ' مقدار گرم فرآوردهٔ جامد به دست آمده از واکنش ۶۰ میلی‌لیتر محلول ۰/۲ مولار پتاسیم هیدروکسید با مقدار کافی از محلول مس (II) نیترات با بازدهٔ ۸۶ درصد، به کدام عدد نزدیک‌تر است؟ (معادله موازنه شود: $Cu=64, O=16, H=1: g.mol^{-1} ; KOH(aq) + Cu(NO_3)_2(aq) \\longrightarrow Cu(OH)_2(s) + KNO_3(aq)$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:04', 4, 'done'),
(6401, ' کدام موارد از مطالب زیر، درست‌اند؟\n\nآ) کمتر از ۵۰ درصد عنصرهای دوره چهارم جدول دوره‌ای عناصر، جزو عنصرهای اصلی هستند.\n\nب) در واکنش $Na(s)$ با $FeO(s)$، واکنش‌پذیری فراورده‌ها از واکنش‌دهنده‌ها، کمتر است.\n\nپ) تبدیل ماده به انرژی تنها منبع حیات بخش انرژی در زمین است.\n\nت) معمولاً هر چه فلزی واکنش‌پذیرتر باشد، استخراج آن، راحت‌تر است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:12', 4, 'done'),
(6402, ' از واکنش کامل $۱۱/۲g$ فلز آهن $۸۵$ درصد خالص با مقدار کافی از محلول هیدروکلریک اسید، چند لیتر گاز هیدروژن به دست می‌آید؟ ($Fe = ۵۶, H = ۱ : g.mol^{-۱} ; d_{H_۲} = ۰/۰۸g.L^{-۱} ; Fe(s) + ۲HCl(aq) \\longrightarrow FeCl_۲(aq) + H_۲(g)$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:16', 4, 'done'),
(6403, '۴۲- اگر از واکنش $۳۴$ گرم سیلیسیم تتراکلرید با مقدار کافی از فلز منیزیم، $۴/۲$ گرم سیلیسیم به دست آید، بازده درصدی واکنش کدام است؟ ($Si = ۲۸, Cl = ۳۵/۵ : g.mol^{-۱} , SiCl_۴(l) + ۲Mg(s) \\longrightarrow ۲MgCl_۲(s) + Si(s)$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, NULL, NULL, 'free'),
(6404, ' واکنش بی‌هوازی تخمیر گلوکز: $C_۶H_{۱۲}O_۶(aq) \\longrightarrow ۲C_۲H_۵OH(aq) + ۲CO_۲(g)$ ، از جمله واکنش‌های انجام شده در فرایند تولید سوخت سبز با استفاده از بقایای گیاهان است. اگر به ازای هر تن از یک نمونه پسماند گیاهی، $۵۶۰۰۰$ لیتر گاز کربن دی اکسید در شرایط استاندارد به دست آید، درصد خلوص گلوکز در این نمونه، کدام است؟ (بازده درصدی این واکنش را صددرصد فرض کنید؛ $O = ۱۶, C = ۱۲, H = ۱ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:22', 4, 'done'),
(6405, ' اگر در واکنش ترمیت ($۲Al(s) + Fe_۲O_۳(s) \\longrightarrow ۲Fe(l) + Al_۲O_۳(s)$)، بازده درصدی واکنش $۸۰$ ٪ باشد، برای تولید $۱۵۴$ گرم آهن، چند گرم آلومینیم خالص لازم است؟ ($Fe = ۵۶, Al = ۲۷ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:27', 4, 'done'),
(6406, ' اگر به جای همه اتم‌های هیدروژن در مولکول نفتالن، گروه متیل قرار گیرد، کدام مورد درباره مولکول حاصل نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:32', 4, 'done'),
(6407, ' همه موارد زیر جزو ویژگی‌های عنصر سرب هستند، به جز:', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:39', 4, 'done'),
(6408, ' آرایش الکترونی لایه ظرفیت عنصری که هم‌گروه $P_{۱۵}$ و در دوره پنجم جای دارد، کدام است و کدام نوع اکسید را می‌تواند تولید کند؟', 2, 3, 68, 311, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:44', 4, 'done'),
(6409, ' برم با گاز هیدروژن .................... واکنش می‌دهد.', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:51', 4, 'done'),
(6410, ' برای خنثی کردن کامل $۲۰۰\\text{mL}$ از محلول سولفوریک اسید با غلظت $۰/۰۵$ مولار، چند گرم سدیم هیدروژن کربنات با خلوص $٪۷۰$ لازم است؟ (اسید با ناخالصی واکنش نمی‌دهد. $Na = ۲۳, H = ۱, C = ۱۲, O = ۱۶ : g.mol^{-۱}$)\n\nمعادله موازنه شود $NaHCO_۳ + H_۲SO_۴ \\longrightarrow Na_۲SO_۴ + H_۲CO_۳$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:11:58', 4, 'done'),
(6411, ' نام هیدروکربن سیر شده خطی که تعداد اتم‌های کربن آن با نفتالن برابر بوده و بیشترین تعداد ممکن از گروه‌های متیل را داشته باشد، کدام است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:02', 4, 'done'),
(6412, ' چه تعداد از موارد زیر، با افزایش شعاع اتمی در گروه اول جدول دوره‌ای، افزایش می‌یابد؟\n\n* خاصیت فلزی           * ظرفیت شیمیایی\n\n* واکنش‌پذیری با اکسیژن      * تعداد لایه‌های اشغال شده از الکترون', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:07', 4, 'done'),
(6413, '۵۲- کدام فرمول مولکولی را می‌توان به هیدروکربن غیرحلقوی سیر شده‌ای که به تعداد مشابه با سیکلو هگزان، گروه $CH_۲$ داشته و شامل سه گروه $CH_۳$ است، نسبت داد؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-03-28 13:49:58', 5, 'done'),
(6414, ' چه تعداد از موارد زیر، نادرست هستند؟\n\n* گران‌روی آلکان‌ها، مستقل از جرم مولی آن‌ها است.\n\n* عنصر اصلی سازنده سلول‌های خورشیدی از واکنش سیلیس با کربن تهیه می‌شود.\n\n* آلکان‌ها، واکنش‌پذیری زیادی به جز در واکنش سوختن، ندارند.\n\n* در ساختار سرگروه ترکیب‌های آروماتیک، ۹ پیوند ساده و سه پیوند دوگانه وجود دارد.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:13', 4, 'done'),
(6415, ' از سوختن کامل $۰/۲$ مول از چه تعداد از ترکیبات زیر در اکسیژن کافی، یک مول آب تولید می‌شود؟\n\n* ۲- متیل پروپان         * هگزان\n\n* پروپان         * ۲- متیل بوتان', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:18', 4, 'done'),
(6416, ' کدام عبارت، نادرست است؟\n\n۱) پسماند سرانه تولید فولاد، ۴۰ کیلوگرم است.\n\n۲) در مولکول ۲، ۲، ۴- تری متیل پنتان، ۵ گروه $CH_۳$ وجود دارد.\n\n۳) بیش از ٪۹۰ از نفتی که از چاه‌های نفت بیرون کشیده می‌شود به عنوان سوخت در وسایل نقلیه استفاده می‌شود.\n\n۴) در استخراج فلز، تنها درصد کمی از سنگ معدن به فلز تبدیل می‌شود.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:23', 4, 'done'),
(6417, ' از تجزیه کامل نیم گرم از $KClO_۳$ با خلوص ۴۰٪ طبق معادله: $۲KClO_۳(s) \\xrightarrow{\\Delta} ۲KCl(s) + ۳O_۲(g)$ به تقریب چند گرم توده جامد ناخالص بر جای می‌ماند؟ (گرما بر ناخالصی جامد بی‌تأثیر است؛ $K = ۳۹, Cl = ۳۵/۵, O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:30', 4, 'done'),
(6418, ' اگر همه گروه‌های هیدروژن روی حلقه بنزن با گروه اتیل جایگزین شوند، فرمول شیمیایی ترکیب به دست آمده کدام است و از سوختن $۰/۲$ مول از آن، چند گرم آب تولید می‌شود؟ ($H = ۱, O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:36', 4, 'done'),
(6419, ' هیدروکربن خطی دارای ۸ اتم کربن، یک پیوند سه‌گانه و یک پیوند دوگانه کربن - کربن دارد. جرم مولی (g) این هیدروکربن و درصد جرمی عنصر کربن در آن کدام است؟ ($C = ۱۲, H = ۱ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:41', 4, 'done'),
(6420, ' در دوره سوم جدول دوره‌ای، تفاوت شمار عنصرهای نافلزی و شبه فلزی، کدام است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:46', 4, 'done'),
(6421, ' چه تعداد از موارد زیر، درست هستند؟\n\n* کم‌ترین تفاوت شعاع اتمی در بین عنصرهای دوره سوم جدول دوره‌ای، مربوط به دو عنصر گوگرد و کلر است.\n\n* رسانایی الکتریکی بالای سیلیسیم، باعث کاربرد فراوان آن در صنعت الکترونیک شده است.\n\n* فلز طلا به اندازه‌ای چکش‌خوار و نرم است که چند گرم از آن را می‌توان با چکش‌کاری به صفحه‌ای با مساحت چند متر مربع تبدیل کرد.\n\n* عنصری که آرایش الکترونی آخرین زیر لایه‌ی اتم آن به $۳p^۵$ ختم می‌شود، رسانایی گرمایی ندارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:12:51', 4, 'done'),
(6422, ' نسبت شمار کاتیون به آنیون در هر واحد فرمولی از ترکیبی که برای جذب گوگرد دی‌اکسید خارج شده از نیروگاه‌ها به کار می‌رود، .................. است.', 2, 3, 68, 314, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:00', 4, 'done'),
(6423, ' یک کارخانه روزانه ۲۰ تن پساب آلوده به یون $Pb^{۲+}$ با غلظت $۱۵۰۰\\text{ppm}$ تولید می‌کند. در بخش تصفیه پساب، اگر ٪۹۵ سرب به صورت سرب (II) سولفات رسوب‌گیری شود، هر روز به تقریب چند کیلوگرم از این ماده تولید می‌شود؟ (چگالی پساب: $d \\approx ۱g.mL^{-۱}$ و $O = ۱۶, S = ۳۲, Pb = ۲۰۷ : g.mol^{-۱}$)', 2, 3, 68, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:06', 4, 'done'),
(6424, 'کدام عبارت، نادرست است؟\n\n۱) تفاوت شعاع اتمی دو عنصر $_{۱۶}S$ و $_{۱۷}Cl$ در دوره سوم جدول دوره‌ای از تفاوت شعاع اتمی دو عنصر $_{۱۳}Al$ و $_{۱۴}Si$، کمتر است.\n\n۲) در یک آلکان ۵ کربنی با حداکثر ممکن از شاخه‌های جانبی، حداکثر ۴ گروه $CH_۳$ می‌تواند وجود داشته باشد.\n\n۳) در آرایش الکترونی هالوژنی که در دمای $۲۰۰^\\circ C$ با هیدروژن واکنش می‌دهد و در دمای پایین‌تر نمی‌تواند با هیدروژن واکنش دهد، ۱۲ الکترون با عدد کوانتومی $n+l=۵$ وجود دارد.\n\n۴) آرایش الکترونی فشرده‌ی فلزهای قلیایی خاکی به‌صورت $[X]ns^۲$ است که $X$ گاز نجیب دوره قبل آن‌ها است.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:12', 4, 'done'),
(6425, ' چه تعداد از موارد زیر، درست است؟\n\n* طلا رسانایی الکتریکی بالایی دارد و این رسانایی را در شرایط دمایی گوناگون، حفظ می‌کند.\n\n* شمار الکترون‌های لایه‌ی ظرفیت فلز دسته‌ی p دوره‌ی سوم جدول دوره‌ای، برابر ۳ است.\n\n* کاتیون در $Mn_۲O_۳$ به آرایش الکترونی گاز نجیب نرسیده است.\n\n* آلکان‌ها علی‌رغم داشتن هیدروژن در ساختار خود، توانایی تشکیل پیوند هیدروژنی را ندارند.\n\n* در هر آلکان راست زنجیر هر اتم کربن به یک یا دو اتم کربن دیگر متصل است.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:16', 4, 'done'),
(6426, ' تفاوت مجموع شمار اتم‌ها در فرمول مولکولی پروپین و فرمول مولکولی نفتالن، کدام است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:22', 4, 'done'),
(6427, ' به تقریب چند کیلوگرم آهن از واکنش ۴۳۰ کیلوگرم آهن (III) اکسید با خلوص ۵۱ درصد با مقدار کافی از گاز کربن مونوکسید در شرایطی که بازده واکنش ٪۷۷ است، به‌دست می‌آید؟ (معادله موازنه شود: $Fe = ۵۶, O = ۱۶ : g.mol^{-۱} : Fe_۲O_۳(s) + CO(g) \\longrightarrow Fe(s) + CO_۲(g)$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:28', 4, 'done'),
(6428, ' از واکنش $۰/۵\\text{kg}$ فلز آلومینیوم ناخالص با مقدار کافی از $Fe_۲O_۳$ طی واکنش ترمیت در شرایط معین ($۲Al(s) + Fe_۲O_۳(s) \\longrightarrow Al_۲O_۳(s) + ۲Fe(l)$)، ۶۴ گرم از فرآورده مذاب به‌دست آمده است. درصد خلوص فلز آلومینیوم به تقریب کدام است؟ (ناخالصی‌ها وارد واکنش نمی‌شوند؛ $Fe = ۵۶, Al = ۲۷, O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:34', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6429, ' چند مورد از عبارت‌های زیر، درست است؟\n\n* سیکلوهگزان شامل ۱۲ پیوند $C-H$ است.\n\n* در ۲- متیل پروپان، یکی از اتم‌های کربن به ۳ اتم کربن دیگر متصل است.\n\n* گران‌روی وازلین از گریس بیشتر است.\n\n* اوکتان از دکان فرارتر است.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:38', 4, 'done'),
(6430, ' از واکنش $۰/۲$ مول از ۲-بوتن با آب در مجاورت اسید و سپس واکنش الکل به‌دست‌آمده با مقدار کافی از استیک اسید، چند گرم از استر مربوطه به‌دست می‌آید؟ (ضریب استوکیومتری همه مواد در واکنش‌های انجام‌شده برابر یک است.) ($C = ۱۲, O = ۱۶, H = ۱ : g.mol^{-۱}$ ؛ بازده درصدی واکنش را ٪۷۰ در نظر بگیرید.)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:41:02', 4, 'done'),
(6431, ' کدام عبارت، درست است؟\n\n۱) همه فلزها در حالت‌های کلی رفتارهای مشابهی دارند، اما تفاوت‌های قابل توجهی نیز میان آن‌ها وجود دارد.\n\n۲) شعاع اتمی، یک راه دقیق بررسی فعالیت شیمیایی و حالت فیزیکی اتم‌ها و یون‌ها در یک دوره است.\n\n۳) روندهای تناوبی در جدول براساس کمیت‌های وابسته به اتم قابل توضیح نیست.\n\n۴) منیزیم در اثر ضربه تغییر شکل نمی‌دهد ولی خرد می‌شود.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:44', 4, 'done'),
(6432, ' در کدام ترکیب، یون فلز مورد نظر را می‌توان به‌صورت آرایش الکترونی مشابه گاز نجیب در نظر گرفت؟\n\n۱) $_{۲۴}Cr$ در $CrO_۳$\n\n۲) $_{۲۵}Mn$ در $MnO_۴^-$\n\n۳) $_{۲۶}Fe$ در $Fe_۲O_۳$\n\n۴) $_{۳۰}Zn$ در $ZnF_۲$', 2, 3, 68, 280, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:48', 4, 'done'),
(6433, ' برای سوختن کامل ۲۰ گرم از ترکیب زیر، به تقریب چند مول گاز اکسیژن لازم است و چند لیتر گاز $N_۲$ در شرایط استاندارد تولید می‌شود؟ ($H = ۱, C = ۱۲, N = ۱۴, O = ۱۶ : g.mol^{-۱}$)\n\n$+ O_۲ \\longrightarrow CO_۲ + H_۲O + N_۲$', 2, 3, 68, 311, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:13:54', 4, 'done'),
(6434, ' برای تعیین درصد مس (II) اکسید در یک نمونه بازیافتی، ۵ گرم از آن را طبق واکنش زیر در $۲۵۰\\text{mL}$ اسید یک مولار حل می‌کنند. اگر غلظت یون‌های مس در محلول اسیدی به $۰/۰۵$ مولار برسد، درصد $CuO$ در نمونه کدام است؟\n\n($Cu = ۶۴, O = ۱۶ : g.mol^{-۱}$) معادله موازنه شود: $CuO(s) + HCl(aq) \\longrightarrow CuCl_۲(aq) + H_۲O(l)$', 2, 3, 68, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:00', 4, 'done'),
(6435, ' گاز طبیعی شامل ٪۷ هلیم و ٪۹۳ متان و هوا شامل ٪۲۱ اکسیژن است (درصد حجمی). درصد حجمی گاز هلیم در خروجی بخاری خانگی پس از سوختن کامل با نسبت استوکیومتری دقیق متان و اکسیژن، به تقریب کدام است؟ (شرایط STP)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:05', 4, 'done'),
(6436, 'کدام موارد درباره ترکیب زیر، درست هستند؟\n\nآ) شمار جفت الکترون‌های ناپیوندی آن با شمار الکترون‌های پیوندی در یون آمونیوم است.\n\nب) در مولکول آن، گروه عامل کتونی و آمیدی وجود دارد.\n\nج) هیدروکربن سیر نشده خطی با شمار اتم‌های یکسان کربن با آن، شامل ۲۲ هیدروژن می‌تواند باشد.\n\nد) از سوختن کامل هر مول از آن، ۴۴۰ گرم $CO_۲$ تولید می‌شود. ($C = ۱۲, O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:18', 4, 'done'),
(6437, ' از واکنش کامل ۲۰ گرم از ترکیب زیر با مقدار کافی از برم، به تقریب چند گرم فرآورده به‌دست می‌آید؟\n\n(معادله کامل و موازنه شود؛ $C = ۱۲, H = ۱, Br = ۸۰ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:23', 4, 'done'),
(6438, ' چند مورد از مطالب زیر، درست‌اند؟\n\n* رفتارهایی مانند شکل‌پذیری، رسانایی الکتریکی و گرمایی و تمایل به اشتراک گذاشتن الکترون در پیوندها، جزو ویژگی‌های رفتاری فلزهاست.\n\n* ۱، ۲ - دی برمو اتان و اتانول ترکیبات مولکولی بی‌رنگ هستند.\n\n* تفاوت شعاع اتمی گوگرد با کلر نسبت به تفاوت شعاع اتمی فسفر با آلومینیم، کمتر است.\n\n* در یک دوره از جدول تناوبی از چپ به راست، علاوه بر شعاع اتمی، خاصیت فلزی نیز کاهش می‌یابد.\n\n* محلول یون‌های $Cu^{۲+}$ و $Ag^+$ با فلز آهن وارد واکنش می‌شوند، ولی واکنش‌پذیری منیزیم و آلومینیم از آهن بیشتر است.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:28', 4, 'done'),
(6439, ' اگر بازده واکنش (موازنه شود) $C_۸H_{۱۰} + KMnO_۴ \\longrightarrow C_۸H_۶O_۴ + KOH + MnO_۲$، ۴۵ درصد باشد، از واکنش ۱۵۰ گرم $C_۸H_{۱۰}$ با خلوص ۶۸ درصد با مقدار کافی از پتاسیم پرمنگنات به تقریب چند گرم $C_۸H_۶O_۴$ تولید می‌شود؟ ($C = ۱۲, O = ۱۶, H = ۱ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:33', 4, 'done'),
(6440, ' نمونه‌ای از سنگ $CaC_۲$ ناخالص به جرم $۰/۸$ کیلوگرم طبق معادله $CaC_۲(s) + H_۲O(l) \\longrightarrow CaO(s) + C_۲H_۲(g)$ در اثر تماس با آب، ۵۶ لیتر گاز اتین در شرایط STP تولید می‌کند. درصد خلوص آن کدام است؟ ($Ca = ۴۰, C = ۱۲ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:42', 4, 'done'),
(6441, ' چه تعداد از مطالب زیر، درست است؟\n\n* از سال ۲۰۰۵ تاکنون میزان تولید یا مصرف نسبی سالانه مواد معدنی همواره از فلزها و سوخت‌های فسیلی بیشتر بوده است.\n\n* دو نافلز از چهار عنصر اول گروه هفدهم جدول دوره‌ای، در دمای اتاق با گاز هیدروژن واکنش نمی‌دهند.\n\n* گرما دادن به مواد و افزودن آن‌ها به یکدیگر سبب تغییر و گاهی بهبود خواص می‌شود.\n\n* در گروه ۱۴ جدول دوره‌ای دو عنصر شبه فلز وجود دارد و زیرلایه 3d در هشت عنصر دوره چهارم جدول، کاملاً از الکترون پر شده است.\n\n* آهن فلزی است که در سطح جهان بیشترین مصرف سالانه را در بین صنایع گوناگون دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:47', 4, 'done'),
(6442, ' عناصر با اعداد اتمی ۱۴ و ۳۲، در چند مورد با هم تفاوت دارند؟\n\n* شمار الکترون‌ها در آخرین زیرلایه اشغال شده از الکترون\n\n* رسانایی الکتریکی کم\n\n* شماره دوره در جدول تناوبی\n\n* به اشتراک گذاشتن الکترون در واکنش با عنصرهای دیگر', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:52', 4, 'done'),
(6443, ' یک نمونه ۲۰ گرمی از مس (II) اکسید ناخالص در اثر واکنش کامل با مقدار کافی از گاز هیدروژن در شرایط معین، ۳ گرم کاهش جرم پیدا می‌کند. درصد خلوص این اکسید در این نمونه، کدام است؟ (ناخالصی‌ها وارد واکنش نمی‌شوند؛ $Cu = ۶۴, O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:14:57', 4, 'done'),
(6444, ' از سوختن کامل ۸ مول از یک آلکان راست زنجیر، ۱۲۹۶ گرم آب به‌دست آمده است. مجموع شمار اتم‌ها در ساختار این هیدروکربن، کدام است؟ ($O = ۱۶, C = ۱۲, H = ۱ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:02', 4, 'done'),
(6445, ' مخلوطی از ۱-پنتن و ۲-متیل پنتان، با ۸ گرم برم مایع به‌طور کامل واکنش می‌دهد. درصد جرمی ۲-متیل پنتان در مخلوط پایانی حدود ٪۳۶ است. جرم مخلوط اولیه بر حسب گرم، به تقریب کدام است؟\n\n($Br = ۸۰, C = ۱۲, H = ۱ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:06', 4, 'done'),
(6446, ' چه تعداد از مطالب زیر، درست است؟\n\n* سوخت هواپیما به‌طور عمده از نفت سفید تهیه می‌شود که شامل آلکان‌هایی با ده تا پانزده کربن است.\n\n* یکی از راه‌های بهبود کارایی زغال‌سنگ به دام انداختن گاز گوگرد دی‌اکسید خارج‌شده از نیروگاه‌ها با عبور گازهای خروجی از روی کلسیم اکسید است.\n\n* اولین عنصر جدول دوره‌ای که سومین لایه اتم آن کاملاً از الکترون پر می‌شود، در گروه یازدهم جدول قرار دارد.\n\n* در نفت سبک و سنگین کشورهای عربی و نفت برنت دریای شمال، درصد نفت کوره از درصد گازوئیل موجود در آن‌ها بیشتر است.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:11', 4, 'done'),
(6447, ' دو عنصر $X$ و $Y$ در یک گروه از جدول تناوبی جای دارند. اگر عنصر $X$ آسان‌تر از $Y$ با برم ترکیب یونی تشکیل دهد، چه تعداد از موارد زیر، نادرست‌اند؟\n\n* $X$ می‌تواند منیزیم و $Y$ می‌تواند کلسیم باشد.\n\n* شمار الکترون‌های لایه آخر $X$ از $Y$ بیشتر است.\n\n* $X$ و $Y$ هم‌گروه کربن بوده و به‌ترتیب در دوره‌های سوم و چهارم قرار دارند.\n\n* شعاع اتمی $X$ از $Y$ بزرگ‌تر است.\n\n* آرایش الکترونی $X$ و $Y$ به $ns^۲np^۳$ ختم می‌شود.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:16', 4, 'done'),
(6448, ' از تخمیر هر کیلوگرم ضایعات گیاهی که شامل ۱۵ درصد جرمی گلوکز است، یک کیلوگرم اتانول ۶ درصد جرمی طبق واکنش (موازنه شود) $C_۶H_{۱۲}O_۶(aq) \\longrightarrow CO_۲(g) + C_۲H_۵OH(aq)$ به دست می‌آید. بازده درصدی این واکنش، به کدام عدد نزدیک‌تر است؟ ($H=۱, C=۱۲, O=۱۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:27', 4, 'done'),
(6449, ' در ساختار کدام هیدروکربن، نسبت شمار گروه‌های $CH_۲$ به کربن‌های متصل به ۳ اتم کربن دیگر، برابر $۰/۷۵$ است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:31', 4, 'done'),
(6450, ' در مجموعه عنصرهایی که با عدد اتمی ۷ شروع و به عدد اتمی ۳۰ ختم می‌شود، .................... عنصر شبه‌فلز و .................... نافلز وجود دارد.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:37', 4, 'done'),
(6451, ' برای تهیهٔ تقریبی چند گرم اتانول با توجه به واکنش: $C_۲H_۴(g) + H_۲O(l) \\longrightarrow C_۲H_۵OH(l)$، ۹ لیتر گاز اتیلن با خلوص ۸۰ درصد در شرایط STP، لازم است؟ ($H=۱, C=۱۲, O=۱۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:42', 4, 'done'),
(6452, ' با استفاده از یک مخزن نیمه صنعتی گاز پروپان که دارای $۵/۵$ کیلوگرم از آن است به‌تقریب چند کیلوگرم آب را از دمای $۱۵^{\\circ}C$ تا $۷۰^{\\circ}C$ می‌توان گرم کرد؟ (آنتالپی سوختن پروپان $-۲۰۵۶ kJ.mol^{-۱}$ است؛ بازده درصدی فرآیند را ٪۶۰ در نظر بگیرید. $C_{H_۲O} = ۴/۲ J.g^{-۱}.^{\\circ}C^{-۱}, H=۱, C=۱۲ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:52', 4, 'done'),
(6453, ' درصد فراوانی چه تعداد از اجزای سازنده نفت سنگین ایران نسبت به نفت برنت دریای شمال، بیشتر است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:15:59', 4, 'done'),
(6454, ' کدام گزینه نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:16:08', 4, 'done'),
(6455, ' چند مورد از عبارت‌های زیر درست است؟\n\n* در گروه چهاردهم جدول دوره‌ای عناصر دو عنصر وجود دارند که رفتار شیمیایی آن‌ها همانند نافلزات و خواص فیزیکی آن‌ها بیشتر به فلزات شبیه است.\n\n* عنصری که برای تهیه فلز سیلیسیم از سیلیس استفاده می‌کنند، دارای کمترین واکنش‌پذیری در دورهٔ خود است.\n\n* شعاع اتمی با فعالیت شیمیایی عناصر در هر گروه رابطهٔ مستقیم دارد.\n\n* فرآورده واکنش بی‌هوازی تخمیر گلوکز با فرآورده گاز اتن در مخلوط آب و اسید یکسان است.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:16:15', 4, 'done'),
(6456, ' اگر شعاع اتمی تقریبی ۴ عنصر متوالی از دورهٔ سوم جدول دوره‌ای به‌صورت زیر باشد، کدام گزینه درست است؟\n\n$A: ۱۶۰ pm \\quad B: ۱۴۶ pm \\quad C: ۱۸۸ pm \\quad D: ۱۱۸ pm$', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:16:21', 4, 'done'),
(6457, ' ۱۶/۲۵ گرم سدیم آزید با ۲۰٪ ناخالصی را تجزیه می‌کنیم. اگر ۰/۲۵ مول فرآورده تولید شود، بازده درصدی واکنش چند است؟ (واکنش موازنه شود.) ($Na=۲۳, N=۱۴ : g.mol^{-۱}$)\n\n$NaN_۳(s) \\rightarrow Na(s) + N_۲(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:16:26', 4, 'done'),
(6458, ' با توجه به فرمول نقطه - خط هیدروکربن‌های زیر چند مورد از عبارت‌های داده‌شده درست است؟\n\n(تصاویر مولکول‌ها: A: سیکلوهگزان با یک گروه متیل، B: آلکان شاخه‌دار، C: آلکن شاخه‌دار، D: آلکن شاخه‌دار)\n\n* ترکیب D گرانروی بیشتری نسبت به ترکیب C دارد.\n\n* سه ترکیب از بین ترکیبات بالا سیرنشده هستند.\n\n* ترکیب C با ترکیب A همپاره است.\n\n* نام ترکیب B، ۳، ۵ و ۶- تری متیل هپتان است.\n\n* ترکیب A نمی‌تواند برم را بی‌رنگ کند.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:26:49', 1, '2026-09-29 15:16:30', 4, 'done'),
(6459, 'کدام‌یک از مطالب داده شده نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:16:35', 4, 'done'),
(6460, ' یک نمونه‌ی ۲۵۰ گرمی از آلومینیم سولفات با خلوص ۸۵/۵ درصد را وارد یک ظرف سر باز کرده و آن را بر اساس معادله‌ی موازنه نشده‌ی زیر تجزیه می‌کنیم. پس از پایان واکنش، درصد جرمی اتم‌های آلومینیم در مخلوط جامد باقیمانده در ظرف واکنش چقدر می‌شود؟ ($O = ۱۶$ و $Al = ۲۷$ و $S = ۳۲ : g.mol^{-۱}$)\n\n$Al_۲(SO_۴)_۳(s) \\rightarrow Al_۲O_۳(s) + SO_۳(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:16:40', 4, 'done'),
(6461, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:16:44', 4, 'done'),
(6462, ' چند مورد از مطالب زیر دربارهٔ سومین عنصر موجود در گروه چهاردهم جدول دوره‌ای درست است؟\n\nآ) این عنصر ۴ الکترون ظرفیتی دارد و برخلاف گرافیت، رسانای گرما بوده و همانند فلز قلع، دارای سطحی صیقلی است.\n\nب) همانند عنصری با ۱۴ ذرهٔ زیراتمی باردار در هسته خود، تمایل دارد الکترون‌های ظرفیتی خود را به اشتراک بگذارد.\n\nپ) با یک فلز قلیایی خاکی هم دوره است که در مقایسه با استرانسیم شعاع اتمی بیش‌تری دارد.\n\nت) هیچ یک از عناصر هم‌دوره با این عنصر، در طبیعت به شکل آزاد یافت نمی‌شوند.\n\nث) در دمای اتاق، حالت جامد داشته و واکنش‌پذیری کمتری نسبت به فلوئور دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:16:49', 4, 'done'),
(6463, ' برای استخراج آهن موجود در ۱۴۴ گرم $Fe_۲O_۳$ طی واکنش موازنه نشده‌ی $Fe_۲O_۳(s) + C(s) \\rightarrow Fe(s) + CO_۲(g)$، به چند گرم گرافیت با خلوص ۶۰٪ نیاز بوده و طی این فرایند، جرم مواد جامد موجود در ظرف واکنش به اندازه‌ی چند گرم کاهش پیدا می‌کند؟ ($C = ۱۲ : g.mol^{-۱}$ و $O = ۱۶$ و $Fe = ۵۶$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:16:53', 4, 'done'),
(6464, ' کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) عنصری از گروه ۱۷ که دارای کوچک‌ترین شعاع اتمی است، در دمای اتاق به سرعت با گاز هیدروژن واکنش می‌دهد.\n\nب) اگر عدد جرمی $Sr$ برابر با ۸۸ باشد، در یون پایدار این عنصر تفاوت شمار نوترون‌ها و الکترون‌ها برابر ۱۵ است.\n\nپ) سیلیسیم، یک عنصر شبه‌فلزی از تناوب سوم بوده و خواص فیزیکی آن مشابه به عناصر ید و سلنیم است.\n\nت) در ۴ مورد از عناصر موجود در تناوب چهارم، بیرونی‌ترین زیرلایه الکترونی فقط شامل ۱ الکترون می‌شود.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:16:58', 4, 'done'),
(6465, ' گاز گوگرد دی‌اکسید مورد نیاز در واکنش موازنه نشده $SO_۲(g) + O_۲(g) \\rightarrow SO_۳(g)$، با استفاده از واکنش زیر تولید می‌شود. اگر درصد پیشرفت واکنش‌های مرحله اول و دوم به ترتیب برابر با ۲۰٪ و ۵۰٪ باشد، به منظور تولید ۶۰ گرم گاز $SO_۳$ به چند گرم گوگرد با خلوص ۶۴٪ نیاز داریم؟ ($O = ۱۶$ و $S = ۳۲ : g.mol^{-۱}$)\n\nمعادله موازنه نشده واکنش مرحله اول: $S_۸(s) + O_۲(g) \\rightarrow SO_۲(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:17:04', 4, 'done'),
(6466, ' چه تعداد از عبارت‌های داده شده درست است؟\n\nآ) در جدول ژانت، همانند جدول تناوبی امروزی، همه عناصر موجود در یک گروه تعداد الکترون ظرفیتی برابری دارند.\n\nب) فلز قلیایی که از سامانه واکنش آن با کلر نور بنفش گسیل می‌شود، در برخی از صابون‌های مایع وجود دارد.\n\nپ) رنگ آبی فیروزه، رنگ سبز زمرد و رنگ سرخ یاقوت به دلیل وجود یون‌هایی از فلزهای دسته $d$ است.\n\nت) مقدار $l$ بیرونی‌ترین زیرلایه در هر فلز از تناوب چهارم که زیرلایه $۳d$ آن کاملا پر باشد، صفر است.', 2, 3, 68, 280, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:17:10', 4, 'done'),
(6467, ' واکنش موازنه نشده‌ی $SF_۴(g) + H_۲O(l) \\rightarrow SO_۲(g) + HF(g)$، با مصرف شدن ۶۰ گرم گاز $SF_۴$ با خلوص ۹۰٪ انجام شده است. اگر طی این فرایند ۱۲ گرم گاز هیدروژن فلوئورید تولید شده باشد، بازده درصدی واکنش انجام شده چقدر می‌شود؟ ($H = ۱$ و $F = ۱۹$ و $S = ۳۲ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:17:17', 4, 'done'),
(6468, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:17:35', 4, 'done'),
(6469, ' برای تهیهٔ مس خام از سنگ معدن سرچشمهٔ کرمان، واکنش موازنه نشده $Cu_۲S + O_۲ \\rightarrow Cu + SO_۲$ انجام می‌شود. با مصرف ۴ تن مس ($I$) سولفید با خلوص ۷۵٪، چند تن فلز مس تولید شده و برای به دام انداختن گاز $SO_۲$ تولید شده در این فرایند، به چند تن کلسیم اکسید نیاز است؟ (بازدهٔ واکنش تهیهٔ مس خام را برابر با ۸۰٪ در نظر بگیرید.)\n\n($Cu = ۶۴ , Ca = ۴۰ , S = ۳۲ , O = ۱۶ : g.mol^{-۱}$)\n\n$SO_۲(g) + CaO(s) \\rightarrow CaSO_۳(s)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:15', 4, 'done'),
(6470, ' کدام موارد از عبارت‌های زیر درست است؟\n\nآ) طلا، یک فلز واسطه است که رسانایی الکتریکی بالایی داشته و این رسانایی را در شرایط دمایی گوناگون حفظ می‌کند.\n\nب) بین عناصر $Ni$، $Cu$ و $Zn$، استخراج فلزی توسط گیاهان به‌صرفه است که در آرایش الکترونی ۹ الکترون با $l = ۲$ دارد.\n\nپ) اکسیدی از آهن که به عنوان رنگ قرمز نقاشی به‌کار می‌رود، در واکنش ترمیت مصرف شده و آهن مذاب تولید می‌کند.\n\nت) اسکاندیم در ساختار تلویزیون‌های رنگی وجود داشته و در آرایش الکترونی هر اتم آن ۶ الکترون با $l = ۰$ وجود دارد.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:20', 4, 'done'),
(6471, ' معادله‌ی واکنش‌های زیر را در نظر بگیرید:\n\nواکنش نمی‌دهد $\\rightarrow DCl_۲(s) + Z(s)$\n\n$ACl_۲(s) + Z(s) \\rightarrow A(s) + ZCl_۲(s)$\n\nبا توجه به معادله‌ی این واکنش‌ها، با استفاده از عنصر فلزی $D$، ............. عنصر $A$ را از ساختار $ACl_۲$ خارج کرد و از بین این سه عنصر فلزی، تامین شرایط مورد نیاز برای نگهداری فلز ............. دشوارتر از سایر فلزها است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:24', 4, 'done'),
(6472, ' اگر بازده درصدی واکنش تجزیه‌ی آمونیوم نیترات بر اساس معادله موازنه نشده زیر برابر با ۴۵٪ باشد، بر اثر تجزیه‌ی یک نمونه‌ی ۴۰۰ گرمی با خلوص ۴۰٪ از این ماده، چند لیتر فرآورده گازی در شرایط استاندارد تولید می‌شود؟\n\n($H = ۱$ و $N = ۱۴$ و $O = ۱۶ : g.mol^{-۱}$)\n\n$NH_۴NO_۳(s) \\rightarrow N_۲(g) + O_۲(g) + H_۲O(l)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:29', 4, 'done'),
(6473, ' کدام‌یک از مطالب داده شده نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:33', 4, 'done'),
(6474, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:37', 4, 'done'),
(6475, ' حجم‌های برابر از گازهای پروپین و اکسیژن را وارد یک مخزن کرده و با زدن یک جرقه، این مخلوط را مشتعل می‌کنیم. اگر گاز پروپین باقیمانده در مخزن در شرایط استاندارد با ۲۱ گرم گاز هیدروژن به طور کامل واکنش بدهد، چند گرم گاز کربن دی‌اکسید در واکنش سوختن تولید شده است؟ ($H = ۱$ و $C = ۱۲$ و $O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:42', 4, 'done'),
(6476, ' کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) هگزان، یک مایع بی‌رنگ بوده و در مقایسه با یک نمونه‌ی خالص از اوکتان، میزان فراریت کمتری دارد.\n\nب) استنشاق آلکان‌ها بر شش‌ها تأثیر چندانی نداشته و تنها سبب کاهش مقدار $O_۲$ در هوای دم می‌شود.\n\nپ) نفت خام، محتوی مقداری نمک و اسید بوده و همه هیدروکربن‌های موجود در آن با برم واکنش می‌دهند.\n\nت) فرآورده واکنش میان گاز اتن و آب، از حلال‌های صنعتی بوده و در تهیه مواد دارویی و بهداشتی کاربرد دارد.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:48', 4, 'done'),
(6477, '۱۹- چگالی بخار نوعی آلکن در دمای $۰^\\circ C$ و فشار ۱ اتمسفر برابر با $۲/۵ g.L^{-۱}$ است. در واکنش سوزاندن یک نمونه ۷ گرمی از این ترکیب با خلوص ۶۰٪، چند گرم گاز اکسیژن مصرف می‌شود و برای ترکیب مورد نظر، چند ساختار مولکولی متفاوت می‌توان در نظر گرفت؟ ($H = ۱$ و $C = ۱۲ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-03-28 13:05:13', 5, 'done'),
(6478, '۲۰- ترکیبی با ساختار زیر را در نظر بگیرید:\r\n\r\n$CH_۳-CH(CH_۳)-CH(CH_۳)-CH_۲-CH_۲-CH_۲-CH(Cl)-CH(CH_۳)-CH_۲-CH_۳$\r\n\r\n(ساختار شیمیایی در تصویر ارائه شده است)\r\n\r\nنام‌گذاری درست این ترکیب بر اساس قواعد آیوپاک به چه صورت بوده و مقدار گرانروی آلکان راست‌زنجیری که با این ترکیب شمار اتم‌های کربن برابری دارد، در مقایسه با گریس چگونه است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-03-28 13:04:50', 5, 'done'),
(6479, ' چه تعداد از عبارت‌های زیر درست هستند؟\n\nآ) در فرایند جوش کاربیدی، دمای لازم برای جوش دادن فلزات با سوختن نوعی هیدروکربن سیرنشده تامین می‌شود.\n\nب) شمار پیوندهای کربن-هیدروژن موجود در ۳-اتیل هگزان، با شمار این پیوندها در هر مولکول ۲-نونین برابر است.\n\nپ) دکین، همپار ترکیب حاصل از هیدروژن‌دار شدن نفتالن بوده و نسبت شمار اتم‌های $H$ به $C$ در آن برابر ۱/۸ است.\n\nت) هر مول از ساده‌ترین آلکانی که در دمای اتاق به حالت مایع وجود دارد، در واکنش با ۸ مول گاز اکسیژن می‌سوزد.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:52', 4, 'done'),
(6480, ' اگر گاز کربن‌دی‌اکسید حاصل از سوختن کامل ۱۶۰ گرم از دومین عضو خانواده آلکین‌ها در مجاورت با مقدار کافی منیزیم اکسید قرار بگیرد، چند گرم فراورده طی این فرایند به دست می‌آید؟ (بازده درصدی واکنش میان منیزیم اکسید و کربن‌دی‌اکسید را برابر با ۸۵٪ در نظر بگیرید. $H=۱, C=۱۲, O=۱۶, Mg=۲۴ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:19:57', 4, 'done'),
(6481, ' همه عبارت‌های داده شده درست هستند، بجز .................\n\n۱) شمار اتم‌های کربن موجود در ساختار نمونه‌هایی به جرم برابر از ۲-بوتن و سیکلوهگزان، با هم برابر خواهد بود.\n\n۲) نسبت شمار اتم‌ها به شمار عناصر در مولکول اتن، برابر با مقدار این نسبت در واحد فرمولی آمونیوم نیترات است.\n\n۳) نیمی از اتم‌های کربن موجود در ساختار مولکول ۳-اتیل-۲،۳-دی‌متیل هگزان، به ۳ اتم هیدروژن متصل شده‌اند.\n\n۴) نام‌گذاری ۲-متیل-۳-اتیل بوتان، بر اساس قواعد آیوپاک به درستی برای یک ترکیب آلکانی انجام شده است.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:02', 4, 'done'),
(6482, ' مخلوطی از گازهای پنتان و ۲-بوتن به جرم ۲۰ گرم، در شرایط مناسب با مقدار کافی گاز هیدروژن واکنش داده و جرم آن به ۲۰/۴ گرم می‌رسد. درصد جرمی ترکیبی با واکنش‌پذیری کمتر در مخلوط اولیه چقدر بوده است؟\n\n($H = ۱$ و $C = ۱۲ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:06', 4, 'done'),
(6483, ' اگر اتم‌های هیدروژن موجود در هیدروکربنی که از آن به عنوان عامل عمل‌آورنده در کشاورزی استفاده می‌شود را با گروه‌های اتیل جایگزین کنیم، فرمول شیمیایی ترکیب حاصل به صورت ............. شده و اگر این ترکیب را با بخار آب وارد واکنش کنیم، ترکیبی بدست می‌آید که در ساختار هر مولکول خود ............. پیوند اشتراکی دارد.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:11', 4, 'done'),
(6484, ' چه تعداد از عبارت‌های زیر درست هستند؟\n\nآ) نفت سنگین کشورهای عربی نسبت به نفت برنت دریای شمال چسبنده‌تر بوده و قیمت پایین‌تری دارد.\n\nب) همه‌ی اکسیدهای تولید شده بر اثر سوختن زغال سنگ، با انحلال در آب یک محلول اسیدی ایجاد می‌کنند.\n\nپ) با حرکت از سمت پایین به طرف بالا در برج تقطیر نفت خام، میزان فراریت مواد جدا شده از نفت افزایش پیدا می‌کند.\n\nت) نفت کوره از جمله مواد موجود در نفت خام است که نسبت به نفت سفید تمایل کمتری به جاری شدن و بخار شدن دارد.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:17', 4, 'done'),
(6485, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:22', 4, 'done'),
(6486, ' در شرایط استاندارد، در مخلوطی از گازهای فلوئور و کلر، درصد حجمی گازی که با واکنش‌پذیری کمتر، ۱/۲ برابر درصد حجمی گاز دیگر است. چگالی این مخلوط برابر با چند گرم بر لیتر بوده و با استفاده از گاز کلر موجود در ۲۴/۶۴ لیتر از آن، چند لیتر محلول آبی با غلظت ۱۴۲۰ppm از کلر می‌توان تهیه کرد؟ ($F=۱۹$ و $Cl=۳۵/۵ : g.mol^{-۱}$)', 2, 3, 68, 318, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:28', 4, 'done'),
(6487, ' چه تعداد از عبارت‌های زیر درست هستند؟\n\nآ) سومین عنصر فراوان در سیاره زمین، همانند سومین عنصر فراوان در سیاره مشتری، در حالت جامد شکننده است.\n\nب) همهٔ موادی که در مراحل ساختن یک دوچرخه مورد استفاده قرار می‌گیرند، از کره‌ی زمین بدست می‌آیند.\n\nپ) فلزها سطحی درخشان داشته و در سال‌های اخیر، میزان استخراج آن‌ها کمتر از مواد معدنی بوده است.\n\nت) فقط یکی از عناصر موجود در گروه چهاردهم جدول تناوبی، در هیچ شرایطی رسانایی الکتریکی ندارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:52', 1, '2026-09-29 15:20:32', 4, 'done'),
(6488, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:20:36', 4, 'done'),
(6489, 'یک نمونه‌ی ۱۲۰ گرمی از برم، در دمای اتاق حالت ............. داشته و در دمای ............. درجه سانتی‌گراد با مقدار کافی از گاز هیدروژن واکنش داده و طی این فرایند، جرم فراورده تولید شده به اندازه ............. درصد بیشتر از جرم هالوژن مصرف شده است. ($H = ۱$ و $Br = ۸۰ : g.mol^{-۱}$)', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:20:40', 4, 'done'),
(6490, ' کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) شمار فلزهای موجود در گروه چهاردهم، ۱/۵ برابر شمار عناصری از تناوب سوم است که در شرایط اتاق حالت گاز دارند.\n\nب) جدول ژانت شامل ۵ دسته‌ی $s$، $p$، $d$، $f$ و $g$ شده و برخلاف جدول دوره‌ای امروزی، با مدل کوانتومی هم‌خوانی ندارد.\n\nپ) شمار عناصر موجود در دسته‌ی $d$ جدول دوره‌ای امروزی بیشتر از شمار عناصر موجود در دسته‌ی $p$ آن است.\n\nت) هسته اتم منیزیم، در مقایسه با هسته اتم گوگرد، نیروی جاذبه قوی‌تری به الکترون‌های ظرفیتی وارد می‌کند.', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:20:45', 4, 'done'),
(6491, ' جرم اتم‌های کربن موجود در نمونه‌ای از گاز کربن مونوکسید، برابر با جرم اتم‌های کربن موجود در ۱۴/۵ گرم استون است. این نمونه کربن مونوکسید، با چند گرم آهن($III$) اکسید بر اساس معادله‌ی زیر واکنش داده و طی این فرایند، چند گرم فلز آهن بدست می‌آید؟ ($H = ۱$ و $C = ۱۲$ و $O = ۱۶$ و $Fe = ۵۶ : g.mol^{-۱}$)\n\n$Fe_۲O_۳(s) + CO(g) \\rightarrow Fe(l) + CO_۲(g)$ : معادله موازنه نشده واکنش', 2, 3, 68, 280, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:20:49', 4, 'done'),
(6492, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:20:53', 4, 'done'),
(6493, ' واکنش $۲NaN_۳(s) \\rightarrow ۲Na(s) + ۳N_۲(g)$، در یک ظرف سرباز در حال انجام شدن است. اگر در طول انجام شدن این واکنش، مجموع جرم مواد جامد موجود در ظرف به اندازه ۸/۴ گرم کاهش پیدا کرده باشد، جرم واکنش‌دهنده مصرف شده برابر با چند گرم بوده و فلز حاصل از این فرایند، در واکنش با مقدار کافی آب چند گرم فراورده گازی تولید می‌کند؟ ($H = ۱$ و $N = ۱۴$ و $Na = ۲۳ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:20:57', 4, 'done'),
(6494, ' کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) داشتن جلا، رسانایی گرمایی و قابلیت ورقه و مفتول شدن، از جمله خواص فیزیکی فلزها به شمار می‌روند.\n\nب) منیزیم، دومین عنصر از خانواده‌ی فلزهای قلیایی بوده و در مقایسه با کلسیم، واکنش‌پذیری کمتری دارد.\n\nپ) سدیم نسبت به آهن، نرم‌تر بوده و برخلاف آهن، در مجاورت هوا سریعا واکنش داده و سطح آن تیره می‌شود.\n\nت) همه‌ی عنصرهایی از دوره‌ی سوم جدول تناوبی که رسانایی الکتریکی دارند، در دسته عناصر فلزی قرار خواهند گرفت.', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:41:06', 4, 'done'),
(6495, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:03', 4, 'done'),
(6496, ' یک نمونه از عنصر موجود در تناوب چهارم که تعداد الکترون‌هایی با $n=۳$ در آن ۹ برابر تعداد الکترون‌هایی با $n=۴$ است، در ساختار خود مجموعا شامل $۱/۲۰۴ \\times ۱۰^{۲۳}$ اتم می‌شود. این عنصر با چند لیتر محلول هیدروکلریک اسید با $pH=۱$ به طور کامل واکنش می‌دهد؟', 2, 3, 68, 278, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:07', 4, 'done'),
(6497, ' اگر در یون تک‌اتمی با نماد $^{۵۷}A^{۳+}$، شمار نوترون‌های موجود در هسته ۱/۲۵ برابر شمار الکترون‌ها باشد، در لایه $n=۳$ این یون چند الکترون وجود داشته و تفاوت شمار الکترون‌ها و نوترون‌های موجود در ساختار یون $^{۵۹}A^{۲+}$ کدام است؟', 2, 3, 68, 277, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:13', 4, 'done'),
(6498, ' کدام موارد از عبارت‌های زیر درست هستند؟\n\nآ) برای استخراج مقدار کمی طلا، حجم انبوهی از خاک معدن استفاده شده و به همین دلیل، پسماند زیادی تولید می‌شود.\n\nب) تفاوت شعاع اتمی عناصر آلومینیم و سیلیسیم، در مقایسه با تفاوت شعاع اتمی گوگرد و کلر، بیشتر است.\n\nپ) برای نوشتن آرایش الکترونی فشرده عناصر واسطه تناوب چهارم، از نماد گاز کریپتون استفاده می‌شود.\n\nت) خاصیت نافلزی عنصری با $Z=۳۴$ در مقایسه با خاصیت نافلزی عنصری با $Z=۵۱$ کمتر است.', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:17', 4, 'done'),
(6499, ' جرم اتم‌های $X$ موجود در نمونه‌ای از اکسید $X_۲O_۳$ برابر جرم اتم‌های اکسیژن موجود در این اکسید است. شمار اتم‌های اکسیژن در ساختار یک نمونه ۵۰/۴ گرمی از این اکسید، چند برابر شمار اتم‌های اکسیژن موجود در یک نمونه ۳/۲ گرمی از گاز $SO_۲$ می‌شود؟ ($O=۱۶$ و $S=۳۲ : g.mol^{-۱}$)', 2, 3, 68, 311, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:21', 4, 'done'),
(6500, ' کدام‌یک از مطالب زیر نادرست است؟ ($Cl = ۳۵/۵$ و $Fe = ۵۶ : g.mol^{-۱}$)', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:27', 4, 'done'),
(6501, ' از واکنش $SiO_۲(s) + ۲C(s) \\rightarrow Si(l) + ۲CO(g)$ برای تهیه‌ی سیلیسیم مورد نیاز برای ساخت قطعات الکترونیکی استفاده می‌شود. به ازای مصرف ۴۵ گرم $SiO_۲$ با خلوص ۸۰٪ در این واکنش، چند گرم کربن با خلوص ۴۵٪ مصرف شده و طی این فرایند، چند مولکول از فراورده گازی تولید می‌شود؟ ($C = ۱۲$ و $O = ۱۶$ و $Si = ۲۸ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:33', 4, 'done'),
(6502, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:37', 4, 'done'),
(6503, ' واکنش‌های مقابل را در نظر بگیرید:\n\n$Ag(s) + ۲HNO_۳(aq) \\rightarrow AgNO_۳(aq) + NO_۲(g) + H_۲O(l)$\n\n$۲NO(g) + O_۲ \\rightarrow ۲NO_۲(g)$\n\nدر واکنش ۲۶۲/۵ گرم نیتریک اسید ۶۰٪ خالص با فلز نقره، چند مول نقره نیترات تشکیل شده و گاز $NO_۲$ تولید شده در این واکنش را از واکنش چند لیتر نیتروژن مونوکسید با اکسیژن در شرایط $STP$ می‌توان تهیه کرد؟\n\n($H = ۱$ و $N = ۱۴$ و $O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:44', 4, 'done'),
(6504, ' مقداری از گاز گوگرد تری‌اکسید با خلوص ۴۰٪ را بر اساس معادله موازنه نشده $SO_۳(g) \\rightarrow SO_۲(g) + O_۲(g)$ به طور کامل تجزیه می‌کنیم. جرم گاز $SO_۳$ ناخالص اولیه، چند برابر جرم گاز اکسیژن تولید شده طی این فرایند است؟ (بازده واکنش انجام شده را برابر با ۵۰٪ در نظر بگیرید. $O = ۱۶$ و $S = ۳۲ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:48', 4, 'done'),
(6505, ' در کدام یک از گزینه‌های زیر، مجموع اعداد کوانتومی اصلی و فرعی برای بیرونی‌ترین زیرلایه الکترونی در گونه سمت چپ، کمتر از مقدار این مولفه برای گونه سمت راست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:53', 4, 'done'),
(6506, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:21:58', 4, 'done'),
(6507, ' برای مصرف ۴۰ لیتر بخار آب با چگالی $۰/۹ g.L^{-۱}$ در واکنش موازنه نشده $H_۲S_۲O_۷(l) + H_۲O(g) \\rightarrow H_۲SO_۴(l)$، به چند مول $H_۲S_۲O_۷$ نیاز بوده و اگر فراورده حاصل از این واکنش، بر اساس معادله موازنه نشده زیر با $K_۲Cr_۲O_۷$ واکنش دهد، چند لیتر گاز اکسیژن در شرایط استاندارد تولید می‌شود؟ (بازده واکنش سولفوریک اسید با $K_۲Cr_۲O_۷$ برابر ۲۵٪ است.)\n\n$H_۲SO_۴ + K_۲Cr_۲O_۷ \\rightarrow Cr_۲(SO_۴)_۳ + H_۲O + K_۲SO_۴ + O_۲ \\quad (O = ۱۶ \\text{ و } H = ۱ : g.mol^{-۱})$', 2, 3, 68, 281, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:41:12', 4, 'done'),
(6508, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ) حدود نیمی از نفتی که از چاه‌های نفت بیرون کشیده می‌شود، به عنوان سوخت در وسایل نقلیه استفاده می‌شود.\n\nب) عنصر اصلی سازنده نفت خام، یک نافلز بوده و نسبت به سایر عناصر هم‌دوره خود واکنش‌پذیری کمتری دارد.\n\nپ) شمار پیوندهای اشتراکی موجود در مولکول استیلن، ۱/۲۵ برابر شمار این پیوندها در هیدروژن سیانید است.\n\nت) نوعی آلکان که از آن برای پر کردن فندک استفاده می‌شود، در دما و فشار اتاق به حالت گاز دیده می‌شود.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:05', 4, 'done'),
(6509, ' ترکیبی با ساختار مقابل را در نظر بگیرید:\n\nنام این ترکیب به صورت ............. بوده و شمار اتم‌های کربن موجود در ساختار مولکولی این ماده با شمار اتم‌های هیدروژن در ............. برابر است.\n\n         $CH_۳$      $CH_۳$  $C_۲H_۵$\n\n         |         |     |\n\n$CH_۳ - C - CH_۲ - CH - C - CH_۳$\n\n         |               |\n\n         $C_۲H_۵$          $C_۲H_۵$', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:09', 4, 'done'),
(6510, ' آلومینیم سولفات بر اساس معادله $Al_۲(SO_۴)_۳(s) \\rightarrow Al_۲O_۳(s) + ۳SO_۳(g)$ با بازده ۳۰٪ تجزیه می‌شود. اگر گاز گوگرد تری‌اکسید حاصل از تجزیه ۵۷ گرم آلومینیم سولفات را با ۰/۷۵ مول گاز گوگرد دی‌اکسید مخلوط کنیم، درصد جرمی اتم‌های گوگرد در مخلوط گازی ایجاد شده چقدر می‌شود؟ ($O=۱۶$ و $S=۳۲$ و $Al=۲۷ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:15', 4, 'done'),
(6511, ' کدام موارد از عبارت‌های زیر درست است؟\n\nآ) برای آلکانی با فرمول مولکولی $C_۵H_{۱۲}$، نمی‌توان ایزومری با شاخه‌ی فرعی اتیل رسم کرد.\n\nب) با افزایش دمای مخلوط مایعی از اتان و پروپان، ابتدا پروپان تغییر حالت داده و از مخلوط خارج می‌شود.\n\nپ) وازلین از جمله ترکیب‌های سیرنشده بوده و از آن می‌توان برای محافظت از فلزها در برابر خوردگی استفاده کرد.\n\nت) نفت خام، یک مایع غلیظ سیاه یا قهوه‌ای متمایل به سبز است که از آن برای تولید برخی از داروها استفاده می‌شود.', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:19', 4, 'done'),
(6512, ' یک نمونه ۶۵ گرمی از ساده‌ترین آلکان شاخه‌داری که دارای یک شاخه‌ی فرعی اتیل باشد را به طور کامل می‌سوزانیم. گاز کربن دی‌اکسید تولید شده در این فرایند، با چند گرم کلسیم اکسید با خلوص ۲۸٪ به طور کامل واکنش می‌دهد؟\n\n($Mg=۲۴$ و $O=۱۶$ و $C=۱۲$ و $H=۱ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:24', 4, 'done'),
(6513, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:29', 4, 'done'),
(6514, ' ۲۴۰ گرم متانول با خلوص ۵۰٪ را بر اساس معادله $CH_۳OH(g) \\rightarrow ۲H_۲(g) + CO(g)$ تجزیه کرده و گاز کربن مونوکسید حاصل از آن را بر اساس معادله موازنه نشده $Fe_۲O_۳(s) + CO(g) \\rightarrow Fe(s) + CO_۲(g)$، با آهن(III) اکسید وارد واکنش می‌کنیم. طی این فرایند، چند گرم فلز آهن تولید می‌شود؟ ($H=۱$ و $C=۱۲$ و $O=۱۶$ و $Fe=۵۶ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:34', 4, 'done'),
(6515, ' در شرایطی که حجم مولی گازها برابر $۳۰ L.mol^{-۱}$ است، ۴۹ گرم پتاسیم کلرات را بر اساس معادله زیر تجزیه می‌کنیم. اگر بازده واکنش انجام شده برابر با ۲۵٪ باشد، طی این فرایند چند لیتر گاز اکسیژن تولید شده و با استفاده از نمک تولید شده، چند لیتر محلول ۰/۰۵ مولار از یون کلرید می‌توان تهیه کرد؟ ($O=۱۶$ و $Cl=۳۵/۵$ و $K=۳۹ : g.mol^{-۱}$)\n\n$KClO_۳(s) \\rightarrow KCl(s) + O_۲(g)$ معادله واکنش موازنه شود', 2, 3, 68, 281, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:41:17', 4, 'done'),
(6516, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:40', 4, 'done'),
(6517, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) تأمین نیازهای جامعه و تولید انواع دستگاه‌ها و ابزارآلات، سبب افزایش تقاضا برای استفاده از منابع زمینی شده است.\n\nب) هر عنصر از گروه چهاردهم جدول دوره‌ای که لایه الکترونی $n=۲$ آن کاملا پر باشد، سطحی صیقلی خواهد داشت.\n\nپ) تفاوت شعاع اتمی نافلزترین عنصر از تناوب دوم با عنصر گوگرد، کمتر از تفاوت شعاع اتمی این عنصر با سدیم است.\n\nت) اگر عناصر $A$ و $B$ متعلق به تناوب ششم باشند، این دو عنصر قطعا تعداد الکترون برابر با $n=۴$ خواهند داشت.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:45', 4, 'done'),
(6518, ' اطلاعات داده شده در چند مورد از ردیف‌های جدول زیر، به صورت نادرست آورده شده است؟\n\nردیف | ترکیب | زیرلایه‌ای که آرایش الکترونی کاتیون موجود در ترکیب به آن ختم می‌شود | عنصری که با استفاده از آن، فلز موجود در ترکیب استخراج می‌شود\n\n۱ | آهن(III) اکسید | $۳d^۵$ | کربن\n\n۲ | پتاسیم کربنات | $۳p^۶$ | روی\n\n۳ | مس(I) سولفید | $۳d^{۱۰}$ | اکسیژن\n\n۴ | تیتانیم(IV) کلرید | $۴s^۲$ | منیزیم', 2, 3, 68, 280, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:22:52', 4, 'done'),
(6519, ' در نمونه‌ای از متانول به جرم ۲۵۰ گرم، تفاوت شمار اتم‌های کربن و هیدروژن برابر با $۳/۶۱۲ \\times ۱۰^{۲۴}$ عدد است. درصد خلوص متانول چقدر بوده و با سوزاندن کامل این مقدار از الکل مورد نظر، چند لیتر فراورده گازی در شرایط استاندارد تولید می‌شود؟\n\n(ناخالصی‌های موجود در نمونه متانول، فاقد اتم کربن و هیدروژن هستند. $H=۱$ و $C=۱۲$ و $O=۱۶ : g.mol^{-۱}$)', 2, 3, 68, 283, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:23:01', 4, 'done'),
(6520, ' کدام موارد از عبارت‌های داده شده درست هستند؟\n\nآ) هر عنصر جامد از جدول دوره‌ای که در واکنش با نافلزها الکترون به اشتراکی می‌گذارد، در اثر ضربه چکش خرد می‌شود.\n\nب) اولین فلز واسطه، نسبت به نیکل شعاع کوچک‌تری داشته و یکی از خواص فیزیکی آن، داشتن رسانایی گرمایی است.\n\nپ) شارل ژانت با کنار هم چیدن عناصر شناخته شده در زمان خود، توانست عناصری با $Z > ۱۱۸$ را نیز طبقه‌بندی کند.\n\nت) کاتیون حاصل از فلز قلیایی که طی واکنش آن با گاز کلر نور زرد رنگ گسیل می‌شود، در صابون مایع وجود دارد.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:23:05', 4, 'done'),
(6521, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:23:14', 4, 'done'),
(6522, ' مطابق واکنش موازنه نشده $Cu_۲S(s) + O_۲(g) \\rightarrow Cu(s) + SO_۲(g)$، یک نمونه ۱۲۰ گرمی از گاز اکسیژن با خلوص ۸۰٪ را به طور کامل با مقدار کافی مس(I) سولفید با خلوص ۳۲٪ وارد واکنش می‌کنیم. جرم نمونه مس(I) سولفید مصرف شده در این فرایند برابر با چند گرم است؟ ($O=۱۶$ و $S=۳۲$ و $Cu=۶۴ : g.mol^{-۱}$)', 2, 3, 68, 281, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:23:22', 4, 'done'),
(6523, ' مخلوطی از آب و کربن دی‌سولفید به جرم ۵۶ گرم، مطابق معادله $CS_۲(l) + ۲H_۲O(l) \\rightarrow CO_۲(g) + ۲H_۲S(g)$ با یکدیگر واکنش داده و طی این فرایند، کل مواد واکنش‌دهنده به فراورده تبدیل می‌شوند. گاز $CO_۲$ تولید شده طی این فرایند، بر اثر سوزاندن چند گرم بنزن در واکنشی با بازده ۵۰٪ تولید می‌شود؟\n\n($H=۱$ و $C=۱۲$ و $O=۱۶$ و $S=۳۲ : g.mol^{-۱}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 11:59:26', 4, 'done'),
(6524, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 11:59:59', 4, 'done'),
(6525, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:00:28', 4, 'done'),
(6526, ' چه تعداد از عبارت‌های داده شده درست هستند؟ ($He=۴$ و $O=۱۶ : g.mol^{-۱}$)\n\nآ) اگر در شرایط $STP$، ۴۴/۸ لیتر گاز هلیم را با یک مول اکسیژن مخلوط کنیم، درصد خلوص اکسیژن به ۸۰٪ می‌رسد.\n\nب) عنصری که در شرکت‌های فولاد برای استخراج آهن کاربرد دارد، در ساختار همه ترکیب‌های زیستی یافت می‌شود.\n\nپ) زنگ آهن، در محلول $HCl$ حل شده و طی واکنش محلول حاصل با محلول سود، رسوبی سبزرنگ ایجاد می‌شود.\n\nت) فراورده آلی حاصل از تخمیر بی‌هوازی گلوکز در واکنش با پروپانوئیک اسید، متیل پروپانوات را تولید می‌کند.\n\nث) فلز مس، در کف اقیانوس‌ها یافت شده و از گیاهان نیز می‌توان برای استخراج آن از خاک استفاده کرد.', 2, 3, 68, 403, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:00:52', 4, 'done'),
(6527, ' یک نمونه ۵۰۵ گرمی از پتاسیم نیترات با خلوص ۲۵٪ را بر اساس معادله زیر، در شرایط استاندارد به طور کامل تجزیه می‌کنیم. اگر تفاوت حجم فراورده‌های گازی تولید شده طی این فرایند برابر با ۱۰/۵ لیتر باشد، بازده درصدی واکنش انجام شده برابر با چند درصد می‌شود؟ ($N=۱۴$ و $O=۱۶$ و $K=۳۹ : g.mol^{-۱}$)\n\n$۴KNO_۳(s) \\rightarrow ۲K_۲O(s) + ۵O_۲(g) + ۲N_۲(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:44:19', 4, 'done'),
(6528, ' یک نمونه ۱۵۰ گرمی از گاز متان با خلوص ۴۲٪ را با یک نمونه ۱۰۰ گرمی از این ماده با خلوص ۱۷٪ مخلوط می‌کنیم. گاز متان موجود در ۱۲۰ گرم از مخلوط گازی نهایی ایجاد شده را با استفاده از چند گرم اکسیژن می‌توان به طور کامل سوزاند؟\n\n($C=۱۲$ و $O=۱۶ : g.mol^{-۱}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:44:44', 4, 'done'),
(6529, ' ترکیبی با ساختار زیر را در نظر بگیرید:\n\nنام این ترکیب بر اساس قواعد آیوپاک به چه صورت بوده و شمار پیوندهای اشتراکی موجود در ساختار این ماده، چند برابر شمار پیوندهای اشتراکی در دومین عضو خانواده آلکین‌ها است؟\n\n(ساختار شیمیایی)\n\n         $CH_۳ - CH_۲$            $CH_۳$\n\n                   |              |\n\n           $CH - CH_۲ - C - CH_۲ - CH_۳$\n\n           |              |\n\n         $CH_۳ - CH_۲$      $CH - CH_۳$\n\n                          |\n\n                         $CH_۳$', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:44:59', 4, 'done'),
(6530, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:45:11', 4, 'done'),
(6531, ' کدام موارد از عبارت‌های داده شده درست هستند؟\n\nآ) کمتر از ۱۰٪ نفت خام استخراج‌شده، به عنوان ماده اولیه برای تولید کالاهای مختلف از جمله مواد منفجره مصرف می‌شود.\n\nب) بین نمونه‌هایی از هگزان و اوکتان، برای رسم ساختار پیوند-خط ترکیبی با گرانروی بیشتر، به ۵ خط راست نیاز است.\n\nپ) مدل فضاپرکن، ساختار دقیق مولکول‌های مختلف و شمار پیوندهای بین اتم‌های سازنده مولکول‌ها را نشان می‌دهد.\n\nت) مولکول نونان دارای ۲۰ اتم هیدروژن بوده و دمای جوش آن به دکان در مقایسه با اوکتان نزدیک‌تر خواهد بود.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:45:24', 4, 'done'),
(6532, ' نوعی هیدروکربن، در ساختار خود دارای یک حلقه کربنی، یک پیوند سه‌گانه و دو پیوند دوگانه است. اگر درصد جرمی اتم‌های کربن در این هیدروکربن برابر با ۹۰٪ باشد، برای سوزاندن کامل هر مول از این هیدروکربن به چند لیتر گاز اکسیژن با چگالی ۱/۶ گرم بر لیتر نیاز داریم؟ ($O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 406, NULL, NULL, NULL, NULL, NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:45:37', 4, 'done'),
(6533, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nآ) ۳-اتیل-۲،۲-دی‌متیل پنتان، ۹ پیوند $C - C$ در ساختار خود داشته و درصد جرمی کربن در آن با نونان برابر است.\n\nب) در ساختار گرافیت، همانند مولکول‌های بنزن و اتن، هر اتم کربن توسط ۴ پیوند به ۳ اتم دیگر متصل شده است.\n\nپ) یک نمونه از ۲-بوتن، در حضور کاتالیزگری با خاصیت اسیدی، با آب واکنش داده و ۲-بوتانول را تولید می‌کند.\n\nت) هر مول از ترکیب هیدروکربنی که توسط موز نرسیده آزاد می‌شود، با ۲ مول گاز هیدروژن واکنش می‌دهد.\n\nث) مولکول متان، ناقطبی بوده و برخلاف مولکول کربن مونوکسید، به هموگلوبین خون متصل نمی‌شود.', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 19:45:52', 4, 'done'),
(6534, ' جرم یک مخلوط گازی از ۲-بوتن و متان، پس از واکنش با بخار برم از ۲۵ گرم به ۶۵ گرم می‌رسد. بر اثر سوزاندن گاز متان موجود در مخلوط نهایی، چند لیتر گاز کربن دی‌اکسید در شرایط استاندارد تولید خواهد شد؟\n\n($H = ۱$ و $C = ۱۲$ و $Br = ۸۰ : g.mol^{-۱}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:01:12', 4, 'done'),
(6535, ' کدام‌یک از مطالب زیر درست است؟ ($H = ۱$ و $C = ۱۲$ و $O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:01:29', 4, 'done'),
(6536, ' در شرایط استاندارد، یک نمونه ۵۶ لیتری از گاز اتن را با مقدار کافی آب وارد واکنش می‌کنیم. طی این فرایند، چند گرم آب مصرف شده و با استفاده از الکل تولید شده، چند لیتر محلول ۰/۴ مولار از اتانول در آب را می‌توان تهیه کرد؟\n\n($H = ۱$ و $C = ۱۲$ و $O = ۱۶ : g.mol^{-۱}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:01:45', 4, 'done'),
(6537, ' کدام‌یک از مطالب زیر نادرست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:01:57', 4, 'done'),
(6538, ' یک نمونه ۱۹۲ گرمی از گاز متان را در واکنش $۲CH_۴(g) \\rightarrow C_۲H_۶(g) + H_۲(g)$ شرکت داده و از گاز هیدروژن تولید شده طی این فرایند، برای تبدیل مقداری نفتالن به یک ترکیب سیرشده در واکنشی با بازده ۵۰٪ استفاده می‌کنیم. جرم فراورده واکنش دوم، چند برابر جرم گاز اتان تولید شده در واکنش اول خواهد بود؟ ($H = ۱$ و $C = ۱۲ : g.mol^{-۱}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:02:20', 4, 'done'),
(6539, ' چه تعداد از مطالب زیر درست است؟\n\nآ) گرما دادن به مواد مختلف و افزودن آنها به یکدیگر، سبب تغییر و گاهی بهبود خواص این مواد می‌شود.\n\nب) فلز قلع رسانایی گرمایی و الکتریکی بالایی داشته و شعاع اتم‌های آن بزرگ‌تر از شعاع اتم‌های سرب است.\n\nپ) وسایل شیشه‌ای را به کمک شن و ماسه و قاشق چای‌خوری را نیز با استفاده از سنگ معدن آهن تولید می‌کنند.\n\nت) فلزها دارای سطحی درخشان بوده و در سال‌های اخیر، میزان استخراج آن‌ها نسبت به مواد معدنی کمتر بوده است.', 2, 3, 68, 402, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:02:46', 4, 'done'),
(6540, ' در یک کارگاه، روزانه از مخلوطی به جرم ۶۲ کیلوگرم از منیزیم‌اکسید و کلسیم اکسید برای تبدیل گاز $CO_۲$ حاصل از سوختن ۳۲ کیلوگرم گاز متان با خلوص ۶۲/۵٪ به مواد معدنی استفاده می‌شود. شمار یون‌های فلز با شعاع بزرگ‌تر چند برابر شمار یون‌های فلز دیگر است؟ ($H = ۱$ و $C = ۱۲$ و $O = ۱۶$ و $Mg = ۲۴$ و $Ca = ۴۰ : g.mol^{-۱}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:03:06', 4, 'done'),
(6541, ' نمونه ناخالصی از کلسیم کربنات را بر اساس معادله $CaCO_۳(s) \\rightarrow CaO(s) + CO_۲(g)$ تجزیه می‌کنیم. اگر طی این فرایند ۵۰۰g کلسیم اکسید ۵۶٪ خالص بدست آمده باشد، درصد خلوص نمونه اولیه کلسیم کربنات به تقریب چقدر بوده و حجم گاز $CO_۲$ تولید شده در این فرایند برابر چند لیتر می‌شود؟ (چگالی گاز $CO_۲$ برابر با ۲/۲ گرم بر لیتر است.)\n\n($C = ۱۲$ و $O = ۱۶$ و $Ca = ۴۰ : g.mol^{-۱}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:03:18', 4, 'done'),
(6542, ' شمار عناصری از تناوب چهارم که در آرایش الکترونی خود دارای ۲ الکترون در زیرلایه $۴s$ هستند، چند برابر شمار عناصری از این تناوب است که در آرایش الکترونی آن‌ها همه‌ی زیرلایه‌های اشغال شده از الکترون، کاملا پر هستند؟', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:03:42', 4, 'done'),
(6543, ' در میان عناصر دوره چهارم جدول تناوبی که در آرایش الکترونی آن‌ها زیرلایه نیمه‌پر وجود دارد، .....................', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:03:58', 4, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6544, ' با توجه به جدول داده شده، چند مورد از عبارت‌های زیر درست است؟\n\n| دوره | گروه ۱۳ | گروه ۱۴ | گروه ۱۵ | گروه ۱۶ |\n\n|---|---|---|---|---|\n\n| ۳ | A | X | D | Y |\n\nآ) در دمای اتاق، عنصر $Y$ جامدی زرد رنگ و شکننده بوده و جریان الکتریسیته را عبور نمی‌دهد.\n\nب) از میان این عناصر، ۲ مورد با نماد دو حرفی نوشته شده و ۲ مورد نیز در اثر ضربه خرد می‌شوند.\n\nپ) ترکیب مولکولی حاصل از عنصر $D$ با کلر، یک ماده قطبی بوده و دارای یک جفت الکترون ناپیوندی است.\n\nت) خصلت نافلزی عنصر $Y$ بیشتر از $D$ بوده و در آرایش الکترون-نقطه‌ای اتم آن، ۶ الکترون جفت شده وجود دارد.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:04:27', 4, 'done'),
(6545, ' واکنش $۲NaN_۳(s) \\rightarrow ۲Na(s) + ۳N_۲(g)$، در یک ظرف سرباز در حال انجام است. اگر در طول این واکنش جرم مواد جامد موجود در ظرف به اندازه ۱۶/۸ گرم کاهش پیدا کرده باشد، جرم $NaN_۳$ مصرف شده برابر با چند گرم بوده و فلز سدیم تولید شده طی این فرایند، در واکنش با مقدار کافی هیدروکلریک اسید منجر به تولید چند گرم گاز هیدروژن می‌شود؟\n\n($H = ۱$ و $N = ۱۴$ و $Na = ۲۳ : g.mol^{-۱}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:04:58', 4, 'done'),
(6546, ' نمک موجود در ۶ لیتر محلول مولار پتاسیم نیترات را استخراج کرده و طبق معادله موازنه نشده زیر در واکنشی با بازده $20\\%$ تجزیه می کنیم. پس از افزودن مقداری ناخالصی به فراورده جامد تولید شده در این واکنش، درصد خلوص این ماده به $40\\%$ می رسد. جرم ناخالصی اضافه شده به ماده مورد نظر برابر با چند گرم بوده است؟\n\n$KNO_3(s) \\rightarrow K_2O(s) + O_2(g) + N_2(g) \\quad (K=39 \\text{ و } O=16 \\text{ و } N=14 : g.mol^{-1})$', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:05:10', 4, 'done'),
(6547, ' کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:05:22', 4, 'done'),
(6548, ' مقداری سدیم نیترات را بر اساس معادله موازنه نشده $NaNO_3(s) \\rightarrow NaNO_2(s) + O_2(g)$ تجزیه کرده و فراورده‌ی جامد حاصل از آن را در ۲۶۲۲ گرم آب حل می‌کنیم. اگر درصد جرمی $NaNO_2$ در محلول حاصل از این فرایند برابر ۵٪ باشد، جرم سدیم نیترات تجزیه شده برابر با چند گرم بوده است؟ (بازده درصدی واکنش را برابر ۲۵٪ در نظر بگیرید.)\n\n$(Na = 23 \\text{ و } O = 16 \\text{ و } N = 14 : g.mol^{-1})$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:05:38', 4, 'done'),
(6549, ' چه تعداد از عبارت‌های زیر درست هستند؟\n\nآ) گاز قطبی تولیدشده در واکنش میان مس(I) سولفید با اکسیژن را می‌توان توسط کلسیم کربنات به دام انداخت.\n\nب) تامین شرایط مورد نیاز برای نگهداری پتاسیم، دشوارتر از تامین شرایط مورد نیاز برای نگهداری فلز روی است.\n\nپ) با استفاده از کربن، می‌توان عناصر فلزی نقره، سدیم و آهن را از ترکیب‌های حاوی این عناصر استخراج کرد.\n\nت) تیتانیم، یک فلز واسطه محکم و با چگالی بالا بوده و در ساخت بدنه دوچرخه از آن استفاده می‌شود.', 2, 3, 68, 403, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:06:00', 4, 'done'),
(6550, ' نمونه‌ای از گاز آمونیاک، شامل $1/505 \\times 10^{24}$ اتم نیتروژن در ساختار خود می‌شود. این مقدار گاز آمونیاک در حضور چند گرم گاز اکسیژن سوخته و اگر بازده درصدی واکنش برابر $80\\%$ باشد، تفاوت جرم فراورده‌های حاصل از سوختن این گاز برابر چند گرم می‌شود؟ ($H=1$ و $C=12$ و $N=14$ و $O=16 : g.mol^{-1}$)\n\nمعادله واکنش موازنه شود $NH_3(g) + O_2(g) \\rightarrow N_2(g) + H_2O(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:06:16', 4, 'done'),
(6551, ' کدام‌یک از عبارت‌های زیر نادرست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:06:43', 4, 'done'),
(6552, ' چه تعداد از مطالب زیر نادرست است؟\n\nآ) داشتن جلا، رسانایی گرمایی و قابلیت ورقه و مفتول شدن، از جمله خواص فیزیکی فلزها به شمار می‌روند.\n\nب) فلز منیزیم، دومین عنصر از خانواده فلزهای قلیایی بوده و در مقایسه با کلسیم، واکنش‌پذیری کمتری دارد.\n\nپ) طلا، عنصر واسطه‌ای است که خاصیت چکش‌خواری داشته و تنها فلزی است که به حالت آزاد در طبیعت وجود دارد.\n\nت) از واکنش نافلز مایع دوره چهارم با فلزی از دوره سوم با کمترین خاصیت فلزی، ترکیبی با فرمول $MX_3$ بدست می‌آید.', 2, 3, 68, 403, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:07:07', 4, 'done'),
(6553, ' کدام‌یک از عبارت‌های زیر نادرست است؟', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:28:30', 4, 'done'),
(6554, ' اگر بازده درصدی واکنش تجزیه سدیم هیدروژن کربنات برابر ۷۰ درصد باشد، بر اثر تجزیه ۴۲ گرم نمونه ناخالص از این نمک که شامل ۴۰٪ ناخالصی است، چند لیتر گاز با مولکول‌های قطبی و حجم مولی $24 L.mol^{-1}$ آزاد می‌شود؟\n\n$(Na=23 \\text{ و } O=16 \\text{ و } C=12 \\text{ و } H=1 : g.mol^{-1})$\n\nواکنش داده شده را موازنه کنید.\n\n$NaHCO_3(s) \\xrightarrow{\\Delta} Na_2CO_3(s) + CO_2(g) + H_2O(g)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-09-29 15:28:37', 4, 'done'),
(6555, ' ۲۰۰ گرم منیزیم برمید ۲۵٪ خالص را با مقداری از این ماده با خلوص ۶۰٪ مخلوط می‌کنیم. اگر درصد خلوص منیزیم برمید در مخلوط نهایی برابر با ۴۶٪ شده باشد، در این مخلوط چند مول منیزیم برمید وجود خواهد داشت و در واکنش تولید این مقدار ترکیب یونی از عناصر سازنده خود، چند الکترون بین گونه‌ها مبادله می‌شود؟ $(Mg=24 \\text{ و } Br=80 : g.mol^{-1})$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:08:52', 4, 'done'),
(6556, ' کدام موارد از مطالب زیر درست است؟\n\nآ) تهیه سوخت سبز از تخمیر بی‌هوازی گلوکز منجر به تولید یک گاز گلخانه‌ای شده و باعث گرم شدن زمین می‌شود.\n\nب) در برخی مناطق از اقیانوس‌ها، کلوخه‌ها و پوسته‌های غنی از پنجمین فلز واسطه جدول دوره‌ای یافت می‌شود.\n\nپ) فلزی که بین صنایع گوناگون بیشترین مصرف سالانه را در جهان دارد، نسبت به روی واکنش‌پذیرتر است.\n\nت) بار الکتریکی کاتیون پایدار حاصل از نخستین فلز واسطه موجود در جدول دوره‌ای برابر با $2+$ است.', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:09:28', 4, 'done'),
(6557, ' عدد اکسایش ........................ درصد از اتم‌های کربن موجود در هر مولکول ۳-اتیل-۲،۲،۴-تری‌متیل پنتان، برابر با ۳- بوده و شمار پیوندهای $C - C$ موجود در این مولکول، ........................ برابر شمار پیوندهای اشتراکی موجود در مولکول استیلن است.', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:09:42', 4, 'done'),
(6558, ' در یک نمونه ناخالص ۵۰۰ گرمی از ترکیب $CuFeS_n$، درصد جرمی فلز مس برابر ٪۳۲ است. مقدار $n$ در فرمول شیمیایی این ماده کدام است و بر اثر واکنش کامل نیمی از این نمونه با مقدار کافی اکسیژن، چند لیتر گاز $SO_2$ در شرایط $STP$ تولید می‌شود؟ (درصد ناخالصی در نمونه $CuFeS_n$ برابر با ٪۸ بوده و محصولات حاصل از واکنش این ماده با گاز اکسیژن، معادل با $Cu_2S$، $FeS$ و $SO_2$ هستند. $g.mol^{-1}$ : $S = 32$ و $Fe = 56$ و $Cu = 64$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:10:05', 4, 'done'),
(6559, ' کدام‌یک از مطالب زیر نادرست است؟\n\n۱) در ساختار دومین عضو خانواده آلکن‌ها، اتم‌های کربنی وجود دارد که به یک، دو و سه اتم $H$ متصل شده‌اند.\n\n۲) کربوهیدرات‌ها و آمینواسیدها، موادی هستند که از اتصال اتم‌های کربن به اتم‌های سایر عناصر حاصل می‌شوند.\n\n۳) عنصر اصلی سازنده نفت خام، یک نافلز از دسته $p$ بوده و در مقایسه با عنصر نیتروژن واکنش‌پذیری کمتری دارد.\n\n۴) حجمی از نفت خام که به عنوان سوخت کاربرد دارد، تقریبا ۲ برابر حجمی از آن است که در پتروشیمی مصرف می‌شود.', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:10:25', 4, 'done'),
(6560, ' از تجزیه ۸۰/۸ گرم پتاسیم نیترات با خلوص ۳۷/۵ درصد، چند لیتر فراورده گازی آزاد شده و درصد جرمی گاز اکسیژن آزاد شده، در میان فراورده‌های گازی بدست آمده به تقریب کدام است؟ (حجم مولی گازها در شرایط آزمایش برابر با ۲۰ لیتر بر مول است. $g.mol^{-1}$ : $N = 14$ و $O = 16$ و $K = 39$)\n\n$KNO_3(s) \\rightarrow K_2O(s) + N_2(g) + O_2(g)$ (معادله واکنش را موازنه کنید.)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:10:43', 4, 'done'),
(6561, ' مخلوطی از گازهای اتان و پروپن به جرم ۲۰ گرم، در شرایط مناسب با مقدار کافی بخار آب واکنش داده و جرم آن به ۲۷/۲ گرم می‌رسد. درصد جرمی گاز اتان مخلوط اولیه چقدر بوده و با استفاده از الکل تولید شده، چند لیتر محلول ۰/۱ مولار از این ماده را می‌توان تهیه کرد؟ ($g.mol^{-1}$ : $H = 1$ و $C = 12$ و $O = 16$)', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:11:02', 4, 'done'),
(6562, ' کدام‌یک از مطالب زیر نادرست است؟\n\n۱) بنزن، همانند سیکلودکان، یک نوع هیدروکربن حلقوی بوده و برخلاف این ماده، می‌تواند با بخار برم واکنش دهد.\n\n۲) هر مول از ساده‌ترین آلکانی که در دمای اتاق به حالت مایع وجود دارد، در واکنش با ۶/۵ مول گاز $O_2$ می‌سوزد.\n\n۳) دمای جوش یک نمونه گریس، همانند چسبندگی این ماده، در مقایسه با یک نمونه از وازلین کمتر خواهد بود.\n\n۴) شستن مداوم دست‌ها با بنزین، برخلاف استنشاق مقدار ناچیز بخار این ماده، به بدن انسان آسیب می‌رساند.', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:11:20', 4, 'done'),
(6563, '95- ترکیبی با ساختار مقابل را در نظر بگیرید:\n\nنام‌گذاری این ترکیب بر اساس قواعد آیوپاک به چه صورت بوده و شمار اتم‌های کربن موجود در ساختار آن با شمار اتم‌های هیدروژن در کدام ماده برابر است؟\n\n      $C_2H_5$\n\n      |\n\n$CH_3 - C - CH_2$       $C_2H_5$\n\n      |             |\n\n      $CH_2 - CH - C - CH_3$\n\n             |    |\n\n             $CH_3$ $CH_2$\n\n                  |\n\n                  $CH_3$', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:12:49', 4, 'free'),
(6564, '96- چه تعداد از عبارت‌های زیر درست هستند؟\n\nآ) در شرایط اتاق، نقطه جوش هگزان بالاتر از آب بوده و از آن برای حفاظت از فلزها در برابر خوردگی استفاده می‌شود.\n\nب) آلکین‌ها واکنش‌پذیری بالایی داشته و یکی از اعضای خانواده آن‌ها به نام اتیلن در جوش کاربیدی کاربرد دارد.\n\nپ) نام‌گذاری ۲-متیل-۲-اتیل بوتان، بر اساس قواعد آیوپاک به درستی برای یک ترکیب آلکانی انجام شده‌است.\n\nت) شمار اتم‌های کربن موجود در ساختار نمونه‌هایی به جرم برابر از ۲-بوتن و سیکلوهگزان، با هم برابر است.\n\nث) تعداد پیوندهای اشتراکی موجود در هر مولکول پنتان، ۲ برابر شمار این پیوندها در متانول است.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:13:11', 4, 'free'),
(6565, '۹۷- جرم مولی یک آلکن، ۱/۳۳ برابر جرم مولی سیکلوهگزان است. از واکنش گاز کربن‌دی‌اکسید حاصل از سوختن کامل ۴۴/۸ گرم از این آلکن با مقدار کافی کلسیم اکسید، چند گرم کلسیم کربنات به دست می‌آید؟ (بازده درصدی واکنش دوم را برابر با ۸۰ درصد در نظر بگیرید؛ $g.mol^{-1}$ : $H = 1$ و $C = 12$ و $O = 16$ و $Ca = 40$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:13:39', 4, 'free'),
(6566, '۹۸- برای سوزاندن کامل ۰/۰۵ مول از یک هیدروکربن که سه حلقه کربنی در ساختار خود دارد، ۰/۸۵ مول گاز اکسیژن مصرف می‌شود. اگر فرمول مولکولی این هیدروکربن به صورت $C_{14}H_n$ باشد، چند پیوند دوگانه در ساختار این ترکیب وجود داشته و از سوختن کامل آن چند گرم آب تولید می‌شود؟ ($g.mol^{-1}$ : $H = 1$ و $C = 12$ و $O = 16$)', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:15:58', 4, 'free'),
(6567, '۹۹- کدام‌یک از مطالب زیر نادرست است؟ ($g.mol^{-1}$ : $C = 12$ و $O = 16$)\n\n۱) روش اتصال اتم‌های کربن در گرافیت به یکدیگر مشابه نحوه اتصال اتم کربن به سایر اتم‌ها در اتن است.\n\n۲) برم در دمای $250^\\circ C$ با گاز هیدروژن واکنش داده و از آن برای تشخیص آلکن‌ها از آلکان‌ها استفاده می‌شود.\n\n۳) با سوختن یک مول از سیکلوآلکانی که در ساختار خود ۱۵ پیوند اشتراکی دارد، ۲۲۰ گرم $CO_2$ آزاد می‌شود.\n\n۴) زغال سنگ، نوعی سوخت فسیلی بوده و طبق پیش‌بینی‌ها، منابع آن نسبت به منابع نفتی، زودتر به پایان می‌رسند.', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:16:32', 4, 'free'),
(6568, '۱۰۰- چه تعداد از عبارت‌های زیر درست هستند؟\n\nآ) ماده‌ای که بخش عمده سوخت هواپیما را تشکیل می‌دهد، نسبت به نفت‌کوره در نقاط بالاتری از برج تقطیر خارج می‌شود.\n\nب) نفتالن، جامدی سفیدرنگ با ۵ پیوند اشتراکی $C = C$ بوده و به عنوان ضدبید برای نگهداری فرش به کار می‌رفته است.\n\nپ) آرایش الکترونی عنصری که در ساختار همه فراورده‌های حاصل از سوختن زغال‌سنگ وجود دارد، به $2p^4$ ختم می‌شود.\n\nت) نفت سنگین کشورهای عربی نسبت به نفت برنت دریای شمال چسبنده‌تر بوده و قیمت یک نمونه از آن بالاتر است.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:27:53', 1, '2026-10-01 12:16:51', 4, 'free'),
(6569, '1-چند درصد از عناصر اصلی که $n+l$ برای بیرونی ترین زیرلایه الکترونی آنها برابر با $4$ است، در حالت جامد سطحی صیقلی داشته و چکش خوار هستند؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:17:17', 4, 'free'),
(6570, '2-از واکنش ترمیت برای جوشکاری ریل قطار استفاده می شود. اگر مجموع جرم فراورده های تولید شده در این واکنش برابر با $96/3$ گرم باشد، جرم فلز مصرف شده در آن برابر با چند گرم خواهد بود؟ ($O = 16$ ، $Al = 27$ و $Fe = 56 : g.mol^{-1}$)', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:17:54', 4, 'free'),
(6571, '3-چند مورد از عبارت های زیر در رابطه با عناصر موجود در جدول دوره ای درست است؟\n\nآ: شمار عناصر نافلزی موجود در تناوب سوم، دو برابر شمار عناصر شبه فلزی موجود در گروه چهاردهم است.\n\nب: از میان همه عناصر موجود در جدول تناوبی، فقط برخی از عناصر نافلزی به شکل آزاد در طبیعت وجود دارند.\n\nپ: سدیم یک فلز قلیایی بوده و به هنگام واکنش آن با گاز کلر، نور زرد رنگ از سامانه واکنش گسیل می شود.\n\nت: سدیم در مقایسه با آلومینیم شعاع اتمی بزرگتری داشته و برخلاف آلومینیم، واکنش پذیری بالایی دارد.', 2, 3, 68, 402, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:18:19', 4, 'free'),
(6572, '\n\nاگر دو واکنش زیر، انجام پذیر باشند، کدام مطلب درست است؟ (عناصر $A$، $X$ و $M$، همگی فلز هستند.)\n\n$I) X_2O(s) + M(s) \\rightarrow MO(s) + 2X(s)$\n\n$II) ACl(s) + X(s) \\rightarrow XCl(s) + A(s)$', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:18:49', 4, 'free'),
(6573, '5-\n\nاز واکنش موازنه نشده $LiOH(s) + CO_2(g) \\rightarrow Li_2CO_3(s) + H_2O(g)$ برای جذب گاز $CO_2$ تولید شده در فضاپیماها استفاده می شود. اگر درصد خلوص لیتیم هیدروکسید مصرف شده $60\\%$ باشد، برای جذب $201/6$ لیتر گاز $CO_2$ به چند گرم از این ماده نیاز است و طی این فرایند، چند گرم بخار آب تولید می شود؟ ($H=1$ و $Li=7$ و $O=16 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:19:14', 4, 'free'),
(6574, '\n\nکدام مطلب زیر نادرست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:19:46', 4, 'free'),
(6575, '\n\nکدام یک از مقایسه های زیر درست اند؟\n\nآ: شمار جفت الکترون های ناپیوندی در ترکیب با هیدروژن: $Cl > S$\n\nب: رسانایی الکتریکی یک نمونه از ماده مورد نظر در حالت جامد: ید < ژرمانیم\n\nپ: خصلت نافلزی اتم های سازنده: $_{33}As > _{34}Se$\n\nت: گشتاور دوقطبی مولکول: $SeO_2 > CO_2$', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:21:48', 4, 'free'),
(6576, '\nکدام یک از ویژگی های زیر، درباره گروهی از عنصرهای موجود در جدول تناوبی که در واکنش های شیمیایی فقط می توانند الکترون به اشتراک بگذارند، درست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:22:14', 4, 'free'),
(6577, ' در گروه هالوژن ها، با حرکت از سمت پایین به بالا در جدول تناوبی، چند مورد از ویژگی های زیر کاهش پیدا می کند؟\n\n- تمایل به تشکیل یون هالید\n\n- تعداد ذره زیراتمی با نماد $_+^1p$\n\n- شعاع اتمی ذرات هالوژن\n\n- مقدار $n+l$ بیرونی ترین زیرلایه', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:23:01', 4, 'free'),
(6578, '10- تعداد الکترون های ظرفیتی عنصر $^{34}X$ برابر با تعداد الکترون های ظرفیت نخستین عنصر از تناوب چهارم است که از قاعده آفبا پیروی نمی کند. اگر عنصر $X$ هم دوره با هالوژنی باشد که در دمای اتاق، به آرامی با گاز هیدروژن واکنش می دهد، نسبت تعداد ذرات زیراتمی بدون بار در هسته اتم این عنصر به تعداد الکترون در یون پایدار حاصل از آن، کدام است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:23:49', 4, 'free'),
(6579, ' چند مورد از موارد زیر، درباره عناصر جدول تناوبی، به یقین درست است؟\n\nآ: عدد اتمی شبه فلز هر گروه نسبت به همه عناصر فلزی موجود در آن گروه، کمتر است.\n\nب: اگر $Z$ شبه فلز باشد، عنصر هم گروه آن در دوره بعد، در واکنش های شیمیایی الکترون از دست می دهد.\n\nپ: اگر نافلز $Y$ در لایه ظرفیت خود دو الکترون داشته باشد، سایر عناصر هم گروه آن تمایل به انجام واکنش شیمیایی ندارند.\n\nت: اگر یون $X^-$ به آرایش هشت تایی رسیده باشد، همه عناصر هم گروه آن، در دوره خود بیشترین خاصیت نافلزی را دارند.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:24:21', 4, 'free'),
(6580, '12- اگر عنصر واسطه $^{57}X$، با تنها نافلز مایع جدول تناوبی هم دوره بوده و تفاوت تعداد نوترون و پروتون در اتم آن، $0/1$ برابر شمار ذرات زیراتمی بدون بار در هسته آن باشد، آرایش الکترونی کاتیون این عنصر در ترکیب .................. به صورت .................. است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6581, ' نمونه 720 گرمی از $CaCO_3(s)$ را وارد یک ظرف سرباز می کنیم تا بر اساس معادله $CaCO_3(s) \\rightarrow CaO(s) + CO_2(g)$ تجزیه شود. پس از تجزیه چند گرم از این ماده، درصد جرمی اتم های کلسیم در مخلوط جامد باقیمانده به $57/6\\%$ می رسد؟ ($C=12 \\,\\, , \\,\\, O=16 \\,\\, , \\,\\, Ca=40 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:26:38', 4, 'free'),
(6582, '14- کدام یک از مقایسه‌های زیر در رابطه با عناصر آهن و پتاسیم به صورت نادرست انجام شده است؟', 2, 3, 68, 403, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:26:57', 4, 'free'),
(6583, '15- جرم اتم‌های کربن موجود در یک نمونه از $MgCO_3$، با جرم اتم‌های کربن موجود در 92 گرم اتانول با خلوص $80\\%$ برابر است. بر اثر تجزیه‌ی این نمونه از منیزیم کربنات طی واکنش $MgCO_3(s) \\rightarrow MgO(s) + CO_2(g)$، چند گرم منیزیم اکسید تولید می‌شود؟ ($H=1 \\text{ و } C=12 \\text{ و } O=16 \\text{ و } Mg=24 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:27:28', 4, 'free'),
(6584, '16- کدام عبارت نادرست است؟', 2, 3, 68, 404, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:30:18', 4, 'free'),
(6585, '17- مقدار ۲۵/۲ گرم از آلکنی که تعداد پیوندهای $C-H$ در آن ۳ برابر تعداد پیوندهای $C-C$ است، به صورت جداگانه یکبار به صورت ناقص و یکبار به صورت کامل سوزانده می‌شود. تفاوت حجم اکسیژن مصرف شده طی این دو فرایند(پس از تبدیل به شرایط STP) برابر چند لیتر است؟ (از سوختن ناقص هیدروکربن‌ها، گاز کربن‌مونوکسید تولید می‌شود.) ($H=1 \\text{ و } C=12 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:30:56', 4, 'free'),
(6586, '18- کدام یک از موارد زیر، نادرست است؟ ($C=12 \\text{ , } H=1 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:31:32', 4, 'free'),
(6587, '19- کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:32:05', 4, 'free'),
(6588, '20- مخلوطی از $2$،$2$-دی‌متیل بوتان و $2$-هگزن به جرم $25$ گرم، با $3360$ میلی‌لیتر گاز کلر در شرایط $STP$ و در مجاورت کاتالیزگر $FeCl_3$ به طور کامل واکنش می‌دهد. درصد جرمی هیدروکربن با واکنش‌پذیری کمتر در مخلوط اولیه و جرم ترکیب کلردار در مخلوط نهایی به ترتیب کدام است؟ ($Cl = 35/5 , C = 12 , H = 1 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:32:55', 4, 'free'),
(6589, '21- کدام‌یک از عبارت‌های زیر در رابطه با نفت خام نادرست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:28:08', 4, 'free'),
(6590, '22- کدام موارد از عبارت‌های زیر درست است؟\n\nآ: نام ترکیب مقابل بر اساس قواعد آیوپاک به صورت $2$-اتیل-$3$،$5$-دی‌متیل هگزان است.\n\nب: در ساختار دی‌متیل پروپان، یکی از اتم‌های کربن به هیچ اتم هیدروژنی متصل نشده است.\n\nپ: در فرمول پیوند-خط مولکول‌های $3$-اتیل-$2$،$4$-دی‌متیل پنتان، $9$ خط راست دیده می‌شود.\n\nت: ساده‌ترین آلکان، موجب انفجار در معادن زغال‌سنگ شده و گشتاور دوقطبی آن برابر صفر است.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:33:30', 4, 'free'),
(6591, '23- شمار پیوندهای اشتراکی موجود در هر مولکول $2$-اوکتن، چند برابر شمار این پیوندها در هر مولکول هیدروژن سیانید است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 10:25:13', 4, 'free'),
(6592, '24- یک نمونه $12$ گرمی از مولکول‌های $2$-متیل بوتان را در حضور مقدار کافی گاز اکسیژن می‌سوزانیم. بخار آب تولید شده در این فرایند، بر اثر تجزیه چند گرم سدیم هیدروژن کربنات بر اساس معادله موازنه نشده زیر تولید می‌شود؟\n\n$(Na = 23 , O = 16 , C = 12 , H = 1 : g.mol^{-1})$\n\nمعادله واکنش : $NaHCO_3(s) \\rightarrow Na_2CO_3(s) + H_2O(g) + CO_2(g)$', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:34:15', 4, 'free'),
(6593, '25- چه تعداد از عبارت‌های داده شده درست است؟\n\nآ: $2$-هگزن، یک مایع زردرنگ است که در حضور فلز نیکل، با گاز هیدروژن وارد واکنش می‌شود.\n\nب: از محلول سولفوریک اسید، برای افزایش سرعت واکنش تولید اتانول از گاز اتن استفاده می‌شود.\n\nپ: در ساختار هر ترکیب آلکینی، حداقل یکی از اتم‌های کربن به هیچ اتم هیدروژنی متصل نشده است.\n\nت: اتانول، یک ماده بی‌رنگ و فرار بوده که به هر نسبتی در آب حل می‌شود و در تهیه مواد دارویی کاربرد دارد.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:36:18', 4, 'free'),
(6594, '26- همه عبارت‌های زیر درست هستند؛ بجز ..........................', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 10:25:57', 4, 'free'),
(6595, '27- برای تامین گاز کلر مورد نیاز برای واکنش با $14$ گرم گاز $2$-بوتن، باید چند لیتر محلول $0.2$ مولار هیدروکلریک اسید را بر اساس معادله موازنه‌نشده زیر با مقدار کافی گاز فلوئور وارد واکنش کنیم؟ $(C=12, H=1 : g.mol^{-1})$\n\nمعادله واکنش: $HCl(aq) + F_2(g) \\rightarrow HF(aq) + Cl_2(g)$', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:37:23', 4, 'free'),
(6596, '28- چند مورد از مطالب زیر درست است؟ $(C=12, H=1 : g.mol^{-1})$\n\nآ: بیش از نیمی از نفت خامی که از چاه بیرون کشیده می‌شود، برای تامین الکتریسیته و گرما به کار می‌رود.\n\nب: نیم مول از ترکیب $C_nH_{2n-2}$ می‌تواند حداکثر با $2$ مول بخار برم و حداقل با $1$ مول بخار برم واکنش دهد.\n\nپ: در بنزن، برخلاف $1$-اوکتن، تعداد اتم‌های کربن متصل به سه اتم از تعداد اتم‌های کربن متصل به چهار اتم بیشتر است.\n\nت: جرم مولی سومین عضو خانواده سیکلوآلکان‌ها، $2$ برابر جرم مولی چهارمین عضو خانواده آلکین‌ها خواهد بود.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:37:50', 4, 'free'),
(6597, '29- عنصر $X$ در جدول تناوبی، نوعی فلز از دسته $p$ است که کاتیون پایدار آن، به آرایش گاز نجیب می رسد. چند مورد از موارد زیر درباره عنصر $X$، درست است؟\n\nآ: در دوره ای که عنصر $X$ جای دارد، دو عنصر در دما و فشار اتاق، به حالت گاز یافت می شوند.\n\nب: عنصر بالای $X$، برخلاف عنصری که در سمت راست عنصر $X$ قرار گرفته، نوعی شبه فلز است.\n\nپ: کوچک ترین عدد اتمی در میان فلزهای موجود در دسته $p$، متعلق به این عنصر است.\n\nت: این عنصر، با نخستین عنصر شبه فلزی گروه 14 و با نخستین عنصر واسطه هم دوره است.', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:38:19', 4, 'free'),
(6598, '30- از واکنش مقداری آهن (III) اکسید دارای 25 گرم ناخالصی با مقدار کافی کربن مونواکسید طبق معادله موازنه نشده زیر، مجموع جرم مواد جامد به اندازه 4/5 گرم کاهش می یابد. درصد خلوص آهن (III) اکسید در نمونه اولیه کدام است و برای جذب گاز کربن دی اکسید حاصل به چند گرم منیزیم اکسید نیاز است؟ ($O=16 , Mg=24$ و $Fe=56 : g.mol^{-1}$)\n\n$Fe_2O_3(s) + CO(g) \\rightarrow Fe(s) + CO_2(g)$\n\n$MgO(s) + CO_2(g) \\rightarrow MgCO_3(s)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:38:51', 4, 'free'),
(6599, '31- نام آلکانی با ساختار مقابل کدام است و جرم مولی این ماده، به تقریب چند برابر جرم مولی دی‌متیل اتر است؟\n\n($O=16$ و $C=12$ و $H=1 : g.mol^{-1}$)\n\n[تصویر ساختار آلکان]', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:39:24', 4, 'free'),
(6600, '32- با توجه به معادله موازنه نشده زیر، اگر از تجزیه 10 گرم $NaHCO_3$، مقدار 3/1 گرم فراورده گازی تولید شود، بازده درصدی واکنش کدام است؟ ($H=1 , C=12$ و $O=16$ و $Na=23 : g.mol^{-1}$)\n\n$NaHCO_3(s) \\xrightarrow{\\Delta} Na_2CO_3(s) + H_2O(g) + CO_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:40:53', 4, 'free'),
(6601, '33- در اثر سوختن کامل 0/2 مول از نوعی هیدروکربن در دمای اتاق، 88 گرم گاز کربن دی‌اکسید و 14/4 گرم آب تولید می‌شود. اگر 2/56 گرم از این هیدروکربن با 9/6 گرم برم مایع به‌طور کامل واکنش دهد، کدام مورد نادرست است؟ (هیدروکربن مورد نظر فاقد پیوند سه‌گانه است. $H=1$ و $C=12$ و $O=16$ و $Br=80 : g.mol^{-1}$)', 2, 3, 68, 406, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:42:22', 4, 'free'),
(6602, '34- کدام موارد زیر در ارتباط با دوره چهارم جدول تناوبی درست است؟\n\nآ: تنها عنصر از این تناوب که در شرایط اتاق به حالت مایع یافت می‌شود، دارای 5 الکترون ظرفیتی در ساختار خود است.\n\nب: در این دوره، عنصر با بیشترین خصلت فلزی نسبت به عنصر با بیشترین خصلت نافلزی، شعاع اتمی بزرگ‌تری دارد.\n\nپ: هر عنصر از این دوره که در حالت جامد جریان برق را از خود عبور می‌دهد، در اثر ضربه خرد نمی‌شود.\n\nت: چهارمین عنصر این دوره، چگالی کمی دارد و واکنش‌پذیری آن در مقایسه با فلز قلیایی هم‌دوره خود کم‌تر است.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:42:42', 4, 'free'),
(6603, '35- در کدام‌یک از عناصر زیر، شمار الکترون‌های موجود در لایه $n=3$ معادل با نصف شمار این الکترون‌ها در ساختار هر اتم سلنیم است و شماره گروه این عنصر، چند برابر شماره تناوب آن خواهد بود؟', 2, 3, 68, 403, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 19:43:24', 4, 'free'),
(6604, '36- در یک واحد صنعتی تولید هیدروفلوئوریک اسید، در هر ثانیه 570 گرم آب در شرایط مناسب وارد مخزنی از گاز فلوئور می‌شود. در صورتی که بازده این فرایند برابر با 75 درصد باشد، تولید هیدروفلوئوریک اسید در این واحد، برابر با چند تن در هر ساعت است؟\n\n(معادله واکنش موازنه شود. $H=1 , O=16 , F=19 : g.mol^{-1}$)\n\n$F_2(g) + H_2O(l) \\rightarrow HF(aq) + O_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:28:34', 4, 'free'),
(6605, '37- کدام مطلب زیر درست است؟', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:31:12', 4, 'free'),
(6606, '38- یک نمونه 250 گرمی از آلومینیم سولفات با خلوص 85/5 درصد را وارد یک ظرف سر باز کرده و آن را بر اساس معادله موازنه نشده زیر تجزیه می‌کنیم. پس از پایان واکنش، درصد جرمی اتم‌های آلومینیم در مخلوط جامد باقیمانده در ظرف واکنش چقدر می‌شود؟ ($O=16$ و $Al=27$ و $S=32 : g.mol^{-1}$)\n\n$Al_2(SO_4)_3(s) \\rightarrow Al_2O_3(s) + SO_3(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:31:33', 4, 'free'),
(6607, '39- نمونه ناخالصی از کلسیم کربنات را بر اساس معادله زیر تجزیه می‌کنیم. اگر طی این فرایند $500 g$ کلسیم اکسید با خلوص %56 به‌دست آمده باشد، درصد خلوص نمونه اولیه کلسیم کربنات به تقریب چقدر بوده و حجم گاز کربن دی‌اکسید تولید شده در این فرایند در شرایط استاندارد برابر با چند لیتر می‌شود؟\n\n($C=12$ و $O=16$ و $Ca=40 : g.mol^{-1}$)\n\n$CaCO_3(s) \\rightarrow CaO(s) + CO_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:32:11', 4, 'free'),
(6608, '40- کدام مطلب زیر نادرست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:32:44', 4, 'free'),
(6609, '41- کدام موارد از عبارت‌های زیر درست است؟\n\nالف: در تناوب سوم جدول دوره‌ای، بیشترین تفاوت شعاع اتمی دو عنصر متوالی مربوط به عناصر فسفر و سیلیسیم است.\n\nب: در یکی از گروه‌های جدول دوره‌ای که شامل 6 عنصر می‌شود، عنصری با هر سه حالت فیزیکی وجود دارد.\n\nپ: اغلب فلزهای اصلی با از دست دادن الکترون، به آرایش الکترونی گاز نجیب قبل از خود می‌رسند.\n\nت: آرایش الکترونی یون روی، مشابه به آرایش الکترونی کاتیون موجود در ترکیب $CuS$ است.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:36:14', 4, 'free'),
(6610, '42- آزید، یک یون چنداتمی با فرمول شیمیایی $N_3^-$ است. یک نمونه ناخالص سدیم آزید به جرم ۵/۲ کیلوگرم را با بازده ٪۲۰ تجزیه می‌کنیم. اگر طی این فرایند، ۱۵۰ لیتر فراورده گازی در شرایطی که حجم مولی گازها برابر $25 L$ است تولید شده باشد، درصد ناخالصی در ماده اولیه چقدر بوده است؟ ($N=14$ و $Na=23 : g.mol^{-1}$)\n\nسدیم آزید $\\rightarrow$ فلز سدیم + گاز نیتروژن', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:36:43', 4, 'free'),
(6611, 'چه تعداد از عبارت‌های زیر درست است؟\n\nالف: با توجه به ویژگی‌های منحصربه‌فرد طلا، از آن در ساخت لباس فضانوردی و قطعاتی از کامپیوتر استفاده می‌شود.\n\nب: اگر فلز $X$ با اکسید فلز $Y$ به‌طور طبیعی واکنش ندهد، نگهداری فلز $Y$ در طبیعت دشوارتر از فلز $X$ است.\n\nپ: پتاسیم، سریع‌تر از لیتیم با گاز کلر واکنش داده و از سامانه واکنش آن، نور زردرنگ گسیل می‌شود.\n\nت: با استفاده از کربن، عناصر فلزی موجود در اکسیدهای $Na_2O$ و $CuO$ را می‌توان استخراج کرد.', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:37:06', 4, 'free'),
(6612, '44- مقدار 240 گرم متانول با خلوص ۵۰٪ را طبق معادله $CH_3OH(g) \\rightarrow 2H_2(g) + CO(g)$ تجزیه کرده و گاز $CO$ حاصل از آن را بر اساس معادله موازنه نشده $Fe_2O_3(s) + CO(g) \\rightarrow Fe(s) + CO_2(g)$، با آهن(III) اکسید وارد واکنش می‌کنیم. طی این فرایند، چند گرم فلز آهن تولید می‌شود؟\n\n($H=1$ و $C=12$ و $O=16$ و $Fe=56 : g.mol^{-1}$)', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:37:25', 4, 'free'),
(6613, 'کدام مطلب زیر نادرست است؟', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:40:40', 4, 'free'),
(6614, 'کدام‌یک از عناصر زیر، در مقایسه با سایر عناصر داده شده شعاع اتمی کوچک‌تری دارد؟', 2, 3, 68, 402, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:41:12', 4, 'free'),
(6615, 'کدام موارد از عبارت‌های زیر درست است؟\n\nالف: عدد کوانتومی اصلی برای بیرونی‌ترین زیرلایه الکترونی همه عناصر واسطه تناوب چهارم با هم برابر است.\n\nب: با ریختن قطعات خراشیده شده یک میخ آهنی زنگ‌زده در محلولی از $HCl$، محلولی قرمز رنگ ایجاد می‌شود.\n\nپ: فلزی که در جهان بیشترین مصرف سالانه را در بین صنایع دارد، در طبیعت اغلب به شکل اکسید یافت می‌شود.\n\nت: شبه‌فلزها چون مرزی بین فلزها و نافلزها قرار داشته و خواص شیمیایی آن‌ها مشابه با خواص شیمیایی فلزها است.', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:41:41', 4, 'free'),
(6616, 'اگر مخلوطی به جرم ۲۵ گرم از $Fe_2O_3$ و $Na_2O$ با مقدار کافی کربن گرما داده شود، ۱۳۴۴ میلی‌لیتر گاز کربن دی‌اکسید در شرایط $STP$ تولید می‌شود. درصد جرمی سدیم اکسید در مخلوط اولیه چقدر بوده و درصد جرمی تقریبی فلز آهن در مخلوط نهایی به ترتیب از راست به چپ کدام است؟\n\n$(Fe = 56 \\text{ و } Na = 23 \\text{ و } O = 16 \\text{ و } H = 1 : g.mol^{-1})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:42:17', 4, 'free'),
(6617, '49-شمار عناصری از جدول دوره‌ای امروزی که زیرلایه $3d$ آن‌ها کاملاً پر از الکترون است، چند برابر شمار عناصری از این جدول است که در دسته $p$ آن قرار می‌گیرند؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:42:40', 4, 'free'),
(6618, 'مقدار ۵۰۵ گرم پتاسیم نیترات با خلوص ۲۵٪ را طبق معادله زیر، در شرایط استاندارد به‌طور کامل تجزیه می‌کنیم. اگر تفاوت حجم فراورده‌های گازی تولید شده طی این فرایند برابر ۱۰/۵ لیتر باشد، بازده درصدی واکنش انجام شده برابر چند درصد می‌شود؟ $(K = 39 \\text{ و } O = 16 \\text{ و } N = 14 : g.mol^{-1})$\n\n$4KNO_3(s) \\rightarrow 2K_2O(s) + 5O_2(g) + 2N_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:43:35', 4, 'free'),
(6619, '51-در یک آزمایشگاه صنعتی، از واکنش آمونیاک با کربونیل کلرید $(COCl_2)$، اوره و آمونیوم کلرید به‌عنوان فراورده با بازده ۸۰٪ به‌دست می‌آیند. اگر بازده این واکنش نصف شده و درصد خلوص واکنش‌دهنده‌های مصرف شده نیز نصف شود، جرم فراورده‌های تولید شده به اندازه چند درصد کاهش می‌یابد؟\n\n$(Cl = 35/5 \\text{ و } O = 16 \\text{ و } N = 14 \\text{ و } C = 12 \\text{ و } H = 1 : g.mol^{-1})$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:44:14', 4, 'free'),
(6620, '52- با توجه به جدول زیر که بخشی از جدول تناوبی عنصرها را نمایش می‌دهد، کدام عبارت بیان شده درست است؟ (نمادها فرضی هستند.)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6621, '53- کدام مطلب زیر در مورد چهار عنصر اول از گروه ۱۴ در جدول دوره‌ای عنصرها، نادرست است؟ $(Al = 27, O = 16 : g.mol^{-1})$', 2, 3, 68, 402, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:44:56', 4, 'free'),
(6622, '54- چند مورد از نمودارهای زیر در مورد ویژگی مطرح شده بر حسب شماره گروه برای چهار عنصر از دوره سوم جدول تناوبی، درست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:48:02', 4, 'free'),
(6623, ' کدام عبارت زیر، درست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:48:40', 4, 'free'),
(6624, '56- کدام یک از موارد زیر درست است؟\n\nالف) برای شناسایی کاتیون $Fe^{3+}(aq)$ موجود در یک محلول آبی می‌توان از تشکیل رسوب سبز رنگ در اثر مجاورت آن محلول با پتاسیم هیدروکسید استفاده کرد.\n\nب) در آرایش الکترونی کاتیون پایدار فلزی که در تلویزیون رنگی و برخی شیشه‌ها وجود دارد، شمار الکترون‌های با $l=1$ دو برابر شمار الکترون‌های با $l=0$ است.\n\nپ) شمار زیرلایه‌های پر شده از الکترون، در آرایش الکترونی کاتیون ترکیب یونی $MnCO_3$ برابر ۵ است.\n\nت) در چهار عنصر واسطه از دوره چهارم، نسبت عدد اتمی به شمار الکترون‌ها در زیرلایه‌هایی با $l=1$، عددی صحیح است.', 2, 3, 68, 403, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:49:02', 4, 'free'),
(6625, '57- ۱۴/۲ گرم آلومینیم نیترات با خلوص ۸۰ درصد مطابق واکنش موازنه نشده زیر به میزان ۷۵ درصد تجزیه می‌شود. درصد جرمی اکسیژن در مخلوط جامد برجای مانده به تقریب کدام است؟ (ناخالصی‌ها جامد و تجزیه نشده‌اند و فاقد اتم اکسیژن هستند.)\n\n$(Al = 27, O = 16, N = 14 : g.mol^{-1})$\n\n$Al(NO_3)_3(s) \\rightarrow Al_2O_3(s) + NO_2(g) + O_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:49:52', 4, 'free'),
(6626, '58- $0/18$ مول گاز فسفر پنتاکلرید در ظرفی سربسته، بر اثر حرارت به گازهای کلر و فسفر تری کلرید تجزیه می‌شود. اگر بازده درصدی واکنش برابر ۸۰ باشد، مجموع شمار مولکول‌های گازی درون ظرف در پایان واکنش چه مضربی از عدد آووگادرو خواهد بود؟', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:50:33', 4, 'free'),
(6627, ' نمونه‌هایی با جرم‌های برابر از $I_2O_5$ و $CuO$، در واکنش‌های زیر شرکت می‌کنند. اگر میزان کاهش جرم مواد جامد در این دو واکنش با یکدیگر برابر باشد، نسبت درصد خلوص $I_2O_5$ به درصد خلوص $CuO$ کدام است؟\n\n$(I = 127, Cu = 64, O = 16, C = 12, H = 1 : g.mol^{-1})$\n\n$I) \\ I_2O_5(s) + 5CO(g) \\rightarrow I_2(s) + 5CO_2(g)$\n\n$II) \\ CuO(s) + H_2(g) \\rightarrow Cu(s) + H_2O(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:53:27', 4, 'free'),
(6628, 'از تجزیه گرمایی مقداری پتاسیم پرمنگنات ۶۰ درصد خالص ($KMnO_4$) طبق واکنش (I)، ۳۵ گرم اکسید فلز واسطه به دست آمده است. اگر گاز اکسیژن حاصل از این فرایند، در یک ظرف در بسته وارد واکنش با گلیسرین ($C_3H_5(OH)_3$) در واکنش (II) شود و در پایان، ۱۳ درصد از اکسیژن وارد شده در ظرف واکنش (II) باقی بماند، چند مول گلیسرین در این فرایند مصرف می‌شود؟ (معادله‌ها موازنه شوند)\n\n$(K = 39, O = 16, Mn = 55 : g.mol^{-1})$\n\n$I) \\ KMnO_4 \\rightarrow K_2MnO_4 + MnO_2 + O_2$\n\n$II) \\ C_3H_5(OH)_3 + O_2 \\rightarrow CO_2 + H_2O$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:54:03', 4, 'free'),
(6629, ' کدام مطلب درست است؟', 2, 3, 68, 404, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 12:54:37', 4, 'free'),
(6630, '62- چند مورد از عبارت‌های زیر در مورد عنصر «کربن» درست است؟\n\n- در خانه شماره ۶ جدول دوره‌ای جای داشته و اتم آن در آخرین زیرلایه خود چهار الکترون دارد.\n\n- اتم آن در ترکیب‌های شیمیایی فقط توانایی تشکیل پیوند اشتراکی را دارد.\n\n- این اتم در هیدروکربن‌های پایدار و شناخته شده الکترون ناپیوندی ندارد.\n\n- از این عنصر تاکنون دو دگرشکل طبیعی شناخته شده است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6631, '63- کدام عبارت زیر درست است؟ ($C = 12, H = 1 : g.mol^{-1}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6632, '64- با توجه به ساختارهای داده شده چند مورد از مطالب زیر درست است؟\n\n\n\nالف) ترکیب a با d و ترکیب b با c ایزومر (همپار) است.\n\nب) شمار پیوندهای کووالانسی در ترکیب d برابر ۴۶ است.\n\nپ) مجموع اعداد به کار رفته در نام‌گذاری آیوپاک ترکیب b برابر ۲۱ است.\n\nت) نام ترکیب a ، ۳ و ۳ - دی اتیل - ۸ و ۸ - دی‌متیل نونان است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6633, '65- دمای جوش سه آلکان راست زنجیر A ، B و C داده شده است. با توجه به این جدول کدام مطالب زیر در مورد آن‌ها نادرست است؟\n\n\n\n\n\nآ) شمار پیوندهای اشتراکی در آلکان B، بیشتر از مجموع شمار اتم‌ها در آلکان A است.\n\nب) در دمای اتاق، با قرار دادن یک فلز در آلکان B یا C، می‌توان از خوردگی آن جلوگیری کرد. \n\nپ) بیش‌ترین درصد جرمی اتم کربن، مربوط به سبک‌ترین آلکان، یعنی آلکان A است.\n\nت) در دما و فشار اتاق، می‌توان شکل (II) را به آلکان B و شکل (I) را به آلکان C نسبت داد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6634, '66- مول‌های برابر از دو آلکان A و B به ترتیب به صورت کامل و ناقص می‌سوزند. اگر نسبت جرم آب تولیدی به اکسید کربن حاصل از سوختن آلکان‌های A و B به ترتیب برابر با $0/45$ و $0/75$ باشد؛ کدام یک از مقایسه‌های زیر در رابطه با این دو آلکان نادرست است؟ (فرآورده واکنش‌های سوختن تنها شامل یک اکسید کربن است.) ($C = 12, O = 16, H = 1 : g.mol^{-1}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6635, '67- شمار اتم‌های هیدروژن در آلکین $A$، $9$ واحد بیشتر از شمار اتم‌های کربن در آلکن $B$ و شمار اتم‌های هیدروژن در آلکن $B$، $2$ واحد بیشتر از شمار اتم‌های کربن در آلکین $A$ است. از واکنش کامل $140$ گرم آلکن $B$ با برم مایع، چند گرم فرآورده به دست می‌آید؟ ($H=1, C=12, Br=80 : g.mol^{-1}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6636, '68- تفاوت شمار اتم‌های هیدروژن و کربن در نوعی آلکان برابر $9$ است. چند ساختار شاخه‌دار برای آلکان می‌توان درنظر گرفت که نام آن به «پنتان» ختم شده و مجموع شمار شاخه‌های فرعی آن یک عدد زوج باشد؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6637, '69- چند مورد از ویژگی‌های بیان شده را می‌توان به سیکلوآلکان‌ها نسبت داد؟ ($n$ شمار اتم‌های کربن در مولکول است.)\n\n* شمار پیوندهای اشتراکی در آن‌ها برابر $3n$ است.\n\n* فرمول همگانی و واکنش‌پذیری آن‌ها مشابه آلکن‌ها است.\n\n* هر یک از اتم‌های کربن به دو اتم هیدروژن متصل شده‌اند.\n\n* برای سوختن کامل هر مول از آن‌ها به $\\frac{3n}{2}$ مول گاز اکسیژن نیاز است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6638, '70- مخلوطی از بنزن و سیکلوهگزان به جرم $88/8$ گرم داریم اگر مقدار مول گاز اکسیژن مصرفی برای سوختن کامل هر یک از این دو هیدروکربن برابر باشد، این مخلوط با چند گرم هیدروژن به‌طور کامل واکنش داده تا به حالت سیر شده درآید؟\n\n($H=1, C=12 : g.mol^{-1}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6639, '71- چند مورد از مطالب زیر نادرست است؟\n\n* در فرآیند شناسایی یون $Fe^{3+}$ در زنگ آهن، رسوب آجری رنگ $Fe(OH)_3$ فراورده واکنش جوهر نمک با محلول آهن (III) کلرید است.\n\n* اگر شمار الکترون‌های با $n+l=5$ در آرایش الکترونی اتم عنصری برابر با $10$ باشد، این عنصر توانایی تشکیل دو نوع کاتیون پایدار و طبیعی را دارد.\n\n* فلز طلا ویژگی‌های منحصر به فردی مثل رسانایی الکتریکی، بازتاب زیاد پرتوهای خورشیدی و ویژگی‌های مشترک با فلزات مثل چکش‌خواری و سخت بودن را دارد.\n\n* کاتیونی از منگنز که کربنات آن در طبیعت به شکل کانی صورتی رنگ وجود دارد، دارای آرایش الکترونی مشابه با آرایش الکترونی یون $Cr^{2+}$ است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6640, '72- جرم‌های برابری از پتاسیم نیترات و کلسیم کربنات که هر دو نمونه حاوی مقداری ناخالصی هستند را در ظرفی سربسته حرارت می‌دهیم تا طبق معادله‌های موازنه نشده زیر تجزیه شوند. اگر در پایان واکنش، $40$ درصد حجمی مخلوط گازهای حاصل را کربن دی اکسید تشکیل داده باشد، نسبت درصد خلوص پتاسیم نیترات به درصد خلوص کلسیم کربنات به تقریب کدام است؟\n\n$(Ca=40, K=39, C=12, O=16, N=14:g.mol^{-1})$\n\n$KNO_3(s) \\rightarrow K_2O(s) + N_2(g) + O_2(g)$\n\n$CaCO_3(s) \\rightarrow CaO(s) + CO_2(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6641, '73- با توجه به نمودار داده‌شده، کدام موارد از مطالب زیر درست است؟\n\nالف) تفاوت شعاع اتمی بین عناصر گروه $15$ و $16$ کمتر از گروه $1$ و $2$ است.\n\nب) میزان تمایل فسفر به تشکیل یون پایدار بیشتر از گوگرد است.\n\nپ) جاذبه هسته بر روی الکترون‌های لایه ظرفیت کلر بیشتر از سدیم است.  ت) تعداد لایه‌های الکترونی اشغال‌شده در گوگرد بیشتر از منیزیم است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6642, '74- با توجه به واکنش‌های زیر، کدام گزینه درست است؟ \n\n$I) Ti + MgCl_2 \\rightarrow \\text{واکنش نمی‌دهد}$\n\n$II) Fe_2O_3 + Ti \\rightarrow TiO_2 + Fe$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6643, '75- چند مورد از عبارت‌های زیر درباره هیدروکربنی به نام 3، 4- دی‌متیل هگزان، درست است؟\n\n- فرمول مولکولی آن $C_8H_{14}$ است.\n\n- دارای 7 پیوند کووالانسی $C-C$ است.\n\n- در مولکول آن، شمار گروه‌های $CH_3$ دو برابر $CH_2$ است.\n\n- یک هیدروکربن سیرشده محلول در آب است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6644, '76- با توجه به فرمول ساختاری داده شده، چند مورد از عبارت‌های زیر درست است؟\n\n- گروه‌های عاملی 1 و 2، به ترتیب گروه آمینی و هیدروکسیل هستند.\n\n- این ترکیب آلی، جزء دسته مواد آروماتیک طبقه‌بندی می‌شود.\n\n- گروه‌های عاملی 3 و 4، به ترتیب در زردچوبه و دارچین نیز وجود دارند.\n\n- فرمول مولکولی آن $C_{19}H_{24}N_2O_3$ است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6645, '77- چند مورد از مطالب زیر درباره فراورده واکنش روبه‌رو، درست است؟\n\n(واکنش تبدیل یک آلکن شاخه‌دار با گاز $H_2$ در حضور کاتالیزگر $Ni(s)$ به آلکان)\n\n- نام آن، 2-اتیل-4-متیل هگزان است. \n\n- فرمول مولکولی آن، $C_9H_{20}$ است.\n\n- در ساختار آن، 4 گروه $CH_3$ وجود دارد.\n\n- برای سوختن کامل 1 مول از آن، به 14 مول گاز اکسیژن نیاز است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6646, ' چه تعداد از عبارت‌های زیر در مورد تقطیر جزءبه‌جزء نفت خام و شکل روبه‌رو که مربوط به جداسازی چهار جزء: بنزین و خوراک پتروشیمی، گازوئیل، نفت کوره و نفت سفید از نفت خام می‌باشد، درست است؟\n\n- در برج تقطیر از بالا به پایین دما در حال کاهش است، به همین دلیل گازهای سبک از قسمت بالای برج خارج می‌شوند.\n\n- از بخش‌های (1) و (2) به ترتیب نفت کوره و گازوئیل خارج می‌شوند.\n\n- از بخش (3)، نفت سفید، شامل آلکان‌هایی با ده تا پانزده اتم کربن خارج می‌شود.\n\n- دلیل جداسازی اجزای نفت خام در برج تقطیر، تفاوت زیاد نقاط جوش آن‌ها با یکدیگر است.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:02:53', 4, 'free'),
(6647, ' عنصر X نافلزترین عنصر جدول دوره‌ای و Y فلزی از گروه اول با کمترین خصلت فلزی است. کدام گزینه زیر، در مورد این دو عنصر نادرست است؟', 2, 3, 68, 402, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:03:52', 4, 'free'),
(6648, ' مطابق واکنش زیر، $12/5$ گرم پتاسیم کلرات ناخالص در مدت $25$ ثانیه به‌طور کامل تجزیه می‌شود. در صورتی که ناخالصی‌ها $20$ درصد از کل نمونه را تشکیل داده باشند، سرعت متوسط تولید گاز اکسیژن چند لیتر بر دقیقه است؟ (حجم یک مول از گازهای مختلف در شرایط آزمایش، $24/5$ لیتر است.) $(KClO_3 = 122/5 g.mol^{-1})$ (معادله واکنش موازنه شود.)\n\n$KClO_3(s) \\rightarrow KCl(s) + O_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:04:25', 4, 'free'),
(6649, ' چه تعداد از عبارت‌های زیر در مورد فلز آهن ($_{26}Fe$) و یون‌های پایدار آن، درست است؟\n\n- آهن در طبیعت دو اکسید طبیعی با نسبت شمار آنیون به کاتیون $1$ و $\\frac{2}{3}$ دارد.\n\n- فلز آهن به هنگام تشکیل کاتیون، ابتدا از زیرلایه $3d$ و سپس از زیرلایه $4s$، الکترون از دست می‌دهد.\n\n- کاتیون دو بار مثبت آهن، آرایش الکترونی مشابه گاز نجیب قبل از خود را دارد.\n\n- فلز آهن بعد از آلومینیم، بیشترین مصرف سالانه را در بین صنایع گوناگون دارد.\n\n- کاتیون پایدار آهن با بار بیشتر، دارای $5$ الکترون با $n+l=5$ است.', 2, 3, 68, 403, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:04:51', 4, 'free'),
(6650, 'کدام عبارت‌ها درست هستند؟\n\nالف) نفت خام مخلوطی از هیدروکربن‌ها است؛ ترکیب‌هایی که در ساختار خود اتم‌های $C$، $H$ و $O$ دارند.\n\nب) حدود $20$ درصد از نفت خام مصرفی در دنیا برای تولید الیاف، شوینده‌ها، مواد آرایشی و بهداشتی، رنگ، پلاستیک و... به کار می‌رود.\n\nپ) کربن، عنصر اصلی سازنده نفت خام است و در لایه ظرفیت خود چهار الکترون دارد.\n\nت) ترکیب‌های شناخته‌شده از اتم کربن، از مجموع ترکیب‌های شناخته شده از دیگر عنصرهای جدول دوره‌ای بیشتر است.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:05:59', 4, 'free'),
(6651, 'کدام عبارت‌ها در مورد واکنش‌های زیر درست هستند؟\n\n$I) CH_2=CH_2 + H_2O \\xrightarrow{H_2SO_4} ..............$\n\n$II) CH_2=CH_2 + Br_2 \\rightarrow ..............$\n\nالف) فراورده واکنش (I)، ترکیبی با $8$ پیوند کووالانسی است و به هر نسبتی در آب حل می‌شود.\n\nب) فراورده واکنش (II)، ترکیبی سیرنشده با نام $1$، $2$- دی‌برمواتان است.\n\nپ) فراورده واکنش (I)، یک ترکیب آلی اکسیژن‌دار و یکی از مهم‌ترین حلال‌های صنعتی است.\n\nت) فراورده واکنش (II)، یک ترکیب آلی قرمزرنگ با نام $1$، $2$- دی‌برمواتان است.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:06:37', 4, 'free'),
(6652, '84- چند مورد از عبارت‌های زیر درست است؟\n\n- نام آلکانی با ساختار (تصویر خط‌پیوند)، $2$، $2$، $3$- تری‌متیل پنتان است.\n\n- اتانول با فرمول مولکولی $C_2H_6O$، یک ترکیب فرّار است و به هر نسبتی در آب حل می‌شود.\n\n- $2$- بوتن یک آلکین سیرنشده است که در فرمول آن، تعداد اتم‌های هیدروژن دو برابر تعداد اتم‌های کربن است.\n\n- هگزن و سیکلو هگزان فرمول مولکولی یکسانی دارند.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:09:36', 4, 'free'),
(6653, '85- کدام‌یک از عبارت‌های زیر درست است؟\n\nالف) خصلت فلزی سیلیسیم بیشتر از خصلت فلزی عنصر فسفر است.\n\nب) در گروه $14$، رسانایی الکتریکی از بالا به پایین در حال افزایش است.\n\nپ) خواص فیزیکی $Si$ بیشتر شبیه فلز $Sn$ است، در حالی که خواص شیمیایی آن بیشتر شبیه نافلز $C$ است.\n\nت) شبه‌فلز $Si$ مرز بین فلز $Ge$ و نافلز $C$ است.', 2, 3, 68, 402, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:11:52', 4, 'free'),
(6654, ' کدام عبارت‌ها درست هستند؟\n\nالف) هیچ‌یک از فلزهای واسطه با تشکیل یون پایدار به آرایش گاز نجیب نمی‌رسند.\n\nب) هرچه ماده‌ای سریع‌تر و شدیدتر واکنش دهد، فعالیت شیمیایی بیشتری دارد.\n\nپ) در هر واکنش شیمیایی که به‌طور طبیعی انجام می‌شود، واکنش‌پذیری فراورده‌ها بیشتر از مواد اولیه است.\n\nت) هرچه واکنش‌پذیری فلزی بیشتر باشد، استخراج آن دشوارتر است.', 2, 3, 68, 404, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:12:30', 4, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6655, ' هرگاه بازده درصدی واکنش آلومینیم با مقدار کافی هیدروکلریک اسید برابر با $80$ درصد باشد، مطابق شکل (که حجم گاز جمع‌آوری شده $24 mL$ است)، چند گرم فلز آلومینیم در این واکنش مصرف شده است؟ (چگالی گاز هیدروژن تولیدشده $0/8 g\\cdot L^{-1}$ است.) ($Al=27 : g\\cdot mol^{-1}$) (معادله واکنش موازنه شود.)\n\n$Al(s) + HCl(aq) \\rightarrow AlCl_3(aq) + H_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:15:05', 4, 'free'),
(6656, '88- هرگاه مطابق معادله زیر، در اثر واکنش $64$ گرم آهن (III) اکسید در حضور مقدار کافی کربن مونوکسید، $12$ گرم از جرم مواد جامد کاسته شود، درصد خلوص نمونه جامد اولیه کدام است؟ (ناخالصی‌ها وارد واکنش نمی‌شوند.) ($C=12, O=16, Fe=56 : g\\cdot mol^{-1}$)\n\n$Fe_2O_3(s) + 3CO(g) \\rightarrow 2Fe(s) + 3CO_2(g)$', 2, 3, 68, 405, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:15:30', 4, 'free'),
(6657, ' با توجه به نمودار داده شده (روند تغییرات نقطه جوش آلکان‌های راست‌زنجیر)، چند مورد از مطالب زیر درست است؟ ($H=1, C=12 : g\\cdot mol^{-1}$)\n\n- در دمای $100^{\\circ}C-$، آلکانی با جرم مولی $58 g\\cdot mol^{-1}$، به حالت گاز نمی‌باشد.\n\n- حالت فیزیکی $16$ آلکان راست‌زنجیر اول در دمای $300^{\\circ}C$، با حالت فیزیکی متان در دمای $150^{\\circ}C-$ متفاوت است.\n\n- آلکان راست‌زنجیری با $16$ پیوند اشتراکی، همانند آلکان راست‌زنجیری با $8$ اتم هیدروژن، در دمای $22^{\\circ}C$ مایع است.\n\n- هر چه جرم مولی آلکان‌های راست‌زنجیر افزایش می‌یابد، اختلاف نقطه جوش دو آلکان متوالی کمتر می‌شود.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:18:41', 4, 'free'),
(6658, '90- کدام‌یک از عبارت‌های زیر در مورد ترکیب روبه‌رو نادرست است؟\n\n$$\n\n\\begin{matrix}\n\nCH_3-CH_2 & & CH_3-CH_2 \\\\\n\n| & & | \\\\\n\nCH_3-C- & CH_2 & -C-CH_3 \\\\\n\n| & & | \\\\\n\nCH_3-CH_2 & & CH_3-CH-CH_3\n\n\\end{matrix}\n\n$$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6659, ' چه تعداد از عبارت‌های زیر درست است؟\n\n- فرمول مولکولی آلکانی با نام «$3$ - اتیل - $4$، $3$ - دی‌متیل هگزان»، $C_9H_{20}$ است.\n\n- اتین ترکیبی سیرنشده است و می‌تواند بر اثر واکنش با برم مایع، فراورده‌ای بی‌رنگ ایجاد کند.\n\n- سومین عضو خانواده آلکین‌ها با چهارمین عضو خانواده آلکان‌ها تعداد کربن برابری دارد.\n\n- کوچک‌ترین عضو خانواده آلکن‌ها، در جوشکاری فلزات کاربرد دارد.', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:19:16', 4, 'free'),
(6660, ' کدام مطلب درباره آلکان‌ها درست است؟', 2, 3, 68, 406, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-10-01 13:24:36', 4, 'free'),
(6661, '93- چند مورد از مطالب زیر، درباره عنصرهای جدول تناوبی درست است؟\n\n- خاصیت نافلزی عنصرهای گروه $16$ در مقایسه با عنصرهای گروه $14$ بیش‌تر است.\n\n- روند تغییر واکنش‌پذیری عنصرهای گروه‌های $2$ و $17$ با افزایش عدد اتمی، عکس یکدیگر است.\n\n- یک فلز قلیایی در مقایسه با سایر فلزهای هم دوره خود، فعالیت شیمیایی و پایداری بیش‌تری دارد.\n\n- تفاوت شمار الکترون‌ها و نوترون‌ها در اتم $_{36}^{84}A$، با عدد اتمی عنصر گروه $2$ از دوره سوم برابر است.\n\n- عنصر $M$ با عدد اتمی $29$ یکی از عنصرهای گروه $11$ است و به‌صورت کاتیون‌های $M^+$ و $M^{2+}$ در ترکیب‌های خود وجود دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6662, '94- اگر جرم گاز کربن دی‌اکسید آزاد شده از تجزیه گرمایی $10$ گرم کلسیم کربنات، برابر جرم گاز کربن دی‌اکسید آزاد شده از سوختن کامل $0/03$ مول گاز پروپان باشد، بازده درصدی واکنش تجزیه گرمایی کلسیم کربنات کدام است؟ ($H=1, C=12, O=16, Ca=40 : g\\cdot mol^{-1}$)\n\n$CaCO_3(s) \\rightarrow CaO(s) + CO_2(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6663, '95- چند مورد از مطالب زیر درست است؟ ($H=1, C=12, O=16 : g\\cdot mol^{-1}$)\n\n- اتانوئیک اسید، همپار اتیل متانوات است.\n\n- تفاوت جرم مولی نفتالن و پنتین، برابر جرم مولی متیل متانوات است.\n\n- در مولکول آلکان‌های شاخه‌دار، برخی از اتم‌های کربن با سه یا چهار اتم کربن دیگر، پیوند دارند.\n\n- نفت خام، مخلوطی از هیدروکربن‌های سیر شده و سیرنشده حلقوی، راست زنجیر و شاخه‌دار است.\n\n- فرمول «پیوند - خط»، همان فرمول ساختاری است که در آن از چگونگی اتصال اتم‌های کربن و هیدروژن چشم‌پوشی می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6664, '96- با توجه به واکنش زیر، چند گرم سدیم سولفیت ($Na_2SO_3$) $63$ درصد خالص لازم است تا $0/5$ مول گوگرد دی‌اکسید تولید شود و در این واکنش چند گرم محلول هیدروکلریک اسید $50$ درصد جرمی مصرف می‌شود؟ (گزینه‌ها را از راست به چپ بخوانید.) (معادله واکنش موازنه شود.) ($Cl=35/5, S=32, Na=23, O=16, H=1 : g\\cdot mol^{-1}$)\n\n$Na_2SO_3(aq) + HCl(aq) \\rightarrow NaCl(aq) + SO_2(g) + H_2O(l)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6665, '97- چه تعداد از عبارت‌های زیر درست است؟\n\n- در آلکان‌ها با افزایش درصد جرمی هیدروژن، فراریت کاهش می‌یابد.\n\n- اختلاف نقطۀ جوش دو آلکان راست‌زنجیر متوالی با افزایش تعداد کربن، کاهش می‌یابد.\n\n- آلکان راست‌زنجیری که شمار پیوندهای $C-H$ آن $\\frac{10}{3}$ برابر شمار پیوندهای $C-C$ است، در دمای اتاق به حالت گازی می‌باشد.\n\n- برای آلکانی با $25$ پیوند اشتراکی، دو ساختار می‌توان رسم کرد که یک شاخۀ فرعی اتیل و یک شاخۀ فرعی متیل داشته باشد.\n\n- آلکانی با فرمول $C_3H_7(CH_2)_3CH_3$ را به دو طریق می‌توان نام‌گذاری کرد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6666, '98- همۀ عبارت‌های زیر نادرست‌اند، به‌جز ............', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6667, '99- اگر مجموع اعداد کوانتومی اصلی و فرعی برای الکترون‌های لایۀ ظرفیت عنصر $A$ از دورۀ سوم جدول تناوبی برابر $6$ باشد، کدام عبارت درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6668, '100- با توجه به چهار عضو اول خانوادۀ هالوژن‌ها، کدام موارد زیر درست هستند؟\n\nالف) واکنش‌پذیرترین نافلز جدول دوره‌ای در این گروه قرار دارد.\n\nب) در واکنش سدیم با عناصر این گروه، اگر به جای نافلز کلر از برم استفاده کنیم، شدت واکنش بیشتر می‌شود.\n\nپ) در دما و فشار اتاق تعداد عناصر گازی با مجموع تعداد عناصر جامد و مایع این گروه برابر است.\n\nت) ید در دمای اتاق به آرامی با گاز هیدروژن واکنش می‌دهد.\n\nث) شعاع اتمی، واکنش‌پذیری و دمای ذوب ید در مقایسه با برم به ترتیب بیشتر، کمتر و بیشتر است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6669, '101- اطلاعات زیر در رابطه با هالوژن‌های $A$، $B$ و $C$ است که در دما و فشار اتاق حالت‌های فیزیکی متفاوتی داشته، و به‌صورت متوالی در گروه خود قرار گرفته است.\n\n$I) A_2 + 2NaC(aq) \\rightarrow C_2 + 2NaA(aq)$\n\n$II) B_2 + 2NaA(aq) \\rightarrow A_2 + 2NaB(aq)$\n\n$III) C_2 + 2NaA(aq) \\rightarrow \\text{واکنش نمی‌دهد}$\n\nبا توجه به آن‌ها، چه تعداد از موارد زیر در رابطه با هالوژن‌های مورد نظر درست بیان شده است؟\n\nآ) در آرایش الکترونی اتم $A$، زیرلایه‌های $d$ خالی از الکترون هستند.\n\nب) بیش از $40$ درصد از الکترون‌های اتم $B$ در لایۀ ظرفیت قرار دارد.\n\nپ) هالوژن $C$ در دمای $200^{\\circ}C$ با گاز هیدروژن واکنش می‌دهد.\n\nت) تفاوت عدد اتمی $A$ و $B$، برابر با $18$ است.\n\nث) مجموع $l$ و $n$ الکترون‌های لایۀ ظرفیت اتم $C$ برابر با $40$ است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6670, '102- ترکیب یونی دوتایی حاصل از دو عنصر $X$ و $Y$ را در نظر بگیرید که فرمول شیمیایی آن شامل سه یون است. اگر آرایش الکترونی یکی از یون‌ها به نئون و دیگری به آرگون رسیده باشد، چه تعداد از موارد زیر همواره درست است؟\n\n- عنصرهای سازندۀ این ترکیب یونی در دو دورۀ متوالی جدول دوره‌ای قرار دارند.\n\n- ترکیب یونی حاصل، براساس عناصر جدول تناوبی، دو ترکیب متفاوت می‌باشد. (با در نظر گرفتن همه حالات برای $X$ و $Y$)\n\n- یکی از این دو عنصر در دما و فشار اتاق مولکول‌های دو اتمی تشکیل می‌دهند.\n\n- اختلاف عدد اتمی این دو عنصر برابر $5$ است.\n\n- اتم هریک از دو عنصر $X$ و $Y$ فاقد الکترون با عدد کوانتومی $l=2$ است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6671, '103- با توجه به انجام شدن واکنش‌های $I$ و $II$ و انجام‌ناپذیر بودن واکنش $III$، چند مورد از مطالب زیر نادرست‌اند؟\n\n$I) AO + 2B \\rightarrow B_2O + A$\n\n$II) A + CuSO_4 \\rightarrow ASO_4 + Cu$\n\n$III) B_2O + Zn \\rightarrow ZnO + B$\n\n- مجموع ضرایب مواد در معادلۀ موازنه شده ($I$)، $2/5$ برابر مجموع ضرایب فرآورده‌ها در واکنش ($II$) است.\n\n- شرایط نگهداری عنصر $A$ نسبت به طلا دشوارتر است.\n\n- واکنش $2B + Cu(NO_3)_2 \\rightarrow 2BNO_3 + Cu$ به طور طبیعی انجام می‌پذیرد.\n\n- عنصر $A$ می‌تواند عنصر $Mg$ باشد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6672, '104- کدام گزینه درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6673, '105- دربارۀ دو واکنش داده شده چند مورد از مطالب زیر درست است؟ ($C=12, O=16, H=1, Na=23, Fe=56 : g.mol^{-1}$)\n\n$I) FeO + 2Na \\xrightarrow{\\Delta} Na_2O + Fe$\n\n$II) C_6H_{12}O_6 \\xrightarrow{\\Delta} 2C_2H_5OH + 2CO_2$\n\nآ) در واکنش ($I$)، از نقره نیز می‌توان برای استخراج آهن استفاده کرد.\n\nب) به ازای مصرف $115$ گرم سدیم با خلوص $40$ درصد، $56$ گرم آهن تولید می‌شود.\n\nپ) نسبت درصد جرمی کربن در گلوکز به درصد جرمی کربن در اتانول، بیشتر از یک است.\n\nت) به ازای مصرف $180$ گرم گلوکز با بازده $50$ درصد، $44$ گرم کربن دی‌اکسید تولید می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6674, '106-چند مورد از عبارت‌های زیر درست‌اند؟\n\n• به طور کلی سهولت استخراج فلزات با واکنش‌پذیری آن‌ها رابطه معکوس دارد.\n\n• با افزودن محلول سدیم هیدروکسید به محلول کلرید فلز آهن با بار الکتریکی بزرگ‌تر، رسوب سبز رنگ تشکیل می‌شود.\n\n• در واکنش میخ آهنی با محلول مس (II) سولفات، یکی از شواهد تجربی برای واکنش‌پذیری بیشتر آهن نسبت به مس این می‌تواند باشد که با گذشت زمان رنگ محلول آبی می‌شود.\n\n• هرگاه در لایه آخر کاتیون فلز واسطه $X$ ($X^{2+}$) از دوره چهارم، ۱۱ الکترون وجود داشته باشد، مجموع $n+l$ الکترون‌های ظرفیتی اتم عنصر $X$، برابر عدد اتمی این عنصر است.\n\n• بین عنصر $X_{21}$ و $Y_{32}$، ۱۰ عنصر فلزی و جامد وجود دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6675, '107-از تجزیه $52/5$ گرم سدیم هیدروژن کربنات ($NaHCO_3$) با خلوص ۸۰ درصد چند لیتر گاز $CO_2$ با چگالی $1/1 g.L^{-1}$ تولید می‌شود و برای تولید همین مقدار گاز $CO_2$ در همان شرایط، به تقریب چند مول هگزان باید با گاز اکسیژن واکنش دهد؟ (بازده درصدی واکنش هگزان با اکسیژن ۷۵ درصد است.) ($Na=23, C=12, H=1, O=16: g.mol^{-1}$) (گزینه‌ها را از راست به چپ بخوانید)\n\n(واکنش‌ها موازنه شوند.)\n\n\n\n$NaHCO_3(s) \\rightarrow Na_2CO_3(s) + CO_2(g) + H_2O(g)$\n\n$C_6H_{14}(l) + O_2(g) \\rightarrow CO_2(g) + H_2O(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6676, '108-کدام موارد زیر درست است؟\n\nالف) در جدول دوره‌ای عناصر، همه عنصرهایی که آرایش الکترونی لایه ظرفیت اتم آن‌ها مشابه است، در یک گروه جای گرفته‌اند.\n\nب) عنصرهای گروه ۱۴ جدول دوره‌ای، از بالا به پایین شامل نافلز، شبه‌فلز و فلز بوده و هیچ‌کدام در واکنش با دیگر اتم‌ها الکترون نمی‌گیرند.\n\nپ) شبه‌فلزها همانند مرزی بین فلزها و نافلزها قرار دارند. خواص فیزیکی شبه‌فلزها بیشتر به فلزها شبیه بوده، در حالی که رفتار شیمیایی آن‌ها همانند نافلزها است.\n\nت) بیشتر عنصرهای جدول دوره‌ای را فلزها تشکیل می‌دهند که همگی در سمت چپ و مرکز جدول قرار دارند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6677, '109-کدام مورد درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6678, '110-نمودار مقابل برآورد میزان تولید یا مصرف نسبی برخی مواد را در جهان نشان می‌دهد. با توجه به این نمودار، کدام مورد نادرست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6679, '111-چند مورد از مطالب زیر در مورد عنصرهای جدول دوره‌ای، درست است؟\n\n• رسانایی الکتریکی در عنصرهای گروه ۱۴ از بالا به پایین، به طور یکنواخت، افزایش می‌یابد.\n\n• خاصیت چکش‌خواری در عنصرهای دوره سوم از چپ به راست، به طور یکنواخت، کاهش می‌یابد.\n\n• رسانایی گرمایی در عنصرهای دوره سوم از چپ به راست، به طور یکنواخت، کاهش می‌یابد.\n\n• تمایل به از دست دادن الکترون در عنصرهای گروه ۱۴ از پایین به بالا کاهش می‌یابد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6680, '112-در هر دوره از جدول دوره‌ای، از چپ به راست از خاصیت .................. کاسته و به خاصیت .................. افزوده می‌شود. در گروه‌های ۱۵، ۱۶ و ۱۷، عنصرهای .................. خاصیت نافلزی بیشتری دارند؛ زیرا از بالا به پایین خاصیت .................. زیاد می‌شود.', 2, 3, 68, 279, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-03-28 23:35:56', 5, 'done'),
(6681, '113-با توجه به نمودار زیر که واکنش‌پذیری عنصرهای دوره دوم جدول تناوبی را به صورت نامرتب نشان می‌دهد، کدام مورد نادرست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6682, '114-کدام مورد درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6683, '115-یاقوت همان آلومینیم اکسید است که در ساختار آن برخی از یون‌های آلومینیم (${}_{13}Al^{3+}$) با یون‌های کروم (III) (${}_{24}Cr^{3+}$) جایگزین شده و رنگ سرخ زیبای یاقوت را ایجاد کرده‌اند. مجموع اعداد کوانتومی اصلی و فرعی الکترون‌های بیرونی‌ترین زیرلایه کاتیون‌های موجود در ساختار یاقوت کدام است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6684, '116-با توجه به آرایش الکترونی ذره‌های پایدار داده‌شده، کدام‌یک از عبارت‌های زیر نادرست است؟\n\n\n\n$A: [Ar]$ , $B: [Ar] 3d^4$ , $C: [Ar] 3d^6$ , $D: [Ar] 3d^9$\n\nالف) آرایش‌های الکترونی داده‌شده، همگی مربوط به کاتیون‌های فلزهای واسطه هستند.\n\nب) عنصر مربوط به ذره $B$ می‌تواند در گروه ۶ یا ۷ جدول دوره‌ای حضور داشته باشد.\n\nپ) تفاوت اعداد اتمی عنصرهای $B$ و $C$ می‌تواند برابر ۴ باشد.\n\nت) عنصر $D$ به یقین در دوره چهارم و گروه ۱۱ جدول دوره‌ای حضور دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6685, '117-با توجه به واکنش‌های موازنه نشده زیر که به طور طبیعی انجام می‌شوند، کدام مورد نادرست است؟\n\n\n\nI) $Al + CuSO_4 \\rightarrow Al_2(SO_4)_3 + Cu$\n\nII) $Fe + Cu(NO_3)_2 \\rightarrow Fe(NO_3)_2 + Cu$\n\nIII) $Cr + FeSO_4 \\rightarrow Cr_2(SO_4)_3 + Fe$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6686, '118-جرم‌های برابری از پتاسیم نیترات ($KNO_3$) ناخالص و پتاسیم کلرات ($KClO_3$) ناخالص، در دو ظرف جداگانه، مطابق واکنش‌های موازنه نشده زیر تجزیه می‌شوند. اگر در دما و فشار اتاق، حجم گاز آزادشده از دو واکنش یکسان باشد، نسبت درصد خلوص پتاسیم نیترات به درصد خلوص پتاسیم کلرات به تقریب کدام است؟ ($K = 39, Cl = 35/5, O = 16, N = 14: g.mol^{-1}$)\n\n\n\n$KNO_3(s) \\rightarrow KNO_2(s) + O_2(g)$\n\n$KClO_3(s) \\rightarrow KCl(s) + O_2(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6687, '119-دانشجویی در آزمایشگاه، واکنش زیر را سه بار در شرایط ایمن انجام داده است:\n\n\n\n$Fe_2O_3(s) + C(s) \\rightarrow Fe(s) + CO_2(g)$ (معادله واکنش موازنه شود.)\n\nاو هر بار ۴۰ گرم آهن (III) اکسید را با مقدار کافی کربن در شرایط مناسب وارد واکنش نموده است. جدول زیر نتایج آزمایش‌های او را نشان می‌دهد:\n\nشماره آزمایش	جرم واکنش‌دهنده $Fe_2O_3$ (گرم)	جرم فرآورده جامدی که دانشجو به دست آورده است. (گرم)\n\n\n\n۱	۴۰	۱۹/۵\n\n۲	۴۰	۱۹/۶\n\n۳	۴۰	۱۹/۷\n\nبا توجه به داده‌های جدول بالا، بازده درصدی واکنش کدام است؟ ($Fe = 56, O = 16: g.mol^{-1}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6688, ' یکی از واکنش‌هایی که در صنعت جوشکاری از آن استفاده می‌شود، واکنش ترمیت است. با توجه به معادلهٔ این واکنش، چه تعداد از عبارت‌های زیر درست است؟ ($Fe=56, Al=27, O=16 : g \\cdot mol^{-1}$)\n\n(واکنش موازنه نشده: $Al(s) + Fe_2O_3(s) \\rightarrow Al_2O_3(s) + Fe(l)$)\n\n- فعالیت شیمیایی آهن کم‌تر از آلومینیم است.\n\n- با توجه به حالت فیزیکی مواد موجود در واکنش، می‌توانیم نقطهٔ ذوب آلومینیم را بالاتر از آهن بدانیم.\n\n- از واکنش $70$ گرم سنگ آهن با خلوص $80$ درصد، $39/2$ گرم فلز مذاب تولید می‌شود.\n\n- اگر بازده درصدی واکنش کم‌تر از $50$ درصد باشد، جرم فراوردهٔ عنصری تولیدشده کم‌تر از جرم واکنش‌دهندهٔ عنصری واردشده به واکنش خواهد بود.', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:29:46', 4, 'done'),
(6689, '121-کالکوزیت از مهم‌ترین سنگ معدن‌های مس بوده که به صورت مس $(I)$ سولفید وجود دارد. در روش استخراج مس از کالکوزیت، ابتدا آن را با گاز اکسیژن واکنش داده تا مس $(I)$ اکسید و گاز گوگرد دی‌اکسید تولید شود، سپس مس $(I)$ اکسید را با کربن پودرشده واکنش داده تا فلز مس به همراه گاز کربن مونوکسید آزاد شود. اگر ۳۰ تن از کالکوزیت در واکنش دومرحله‌ای بالا استفاده شود و در نهایت ۲۹۳۷ کیلوگرم فلز مس آزاد شود، درصد خلوص فلز مس در نمونه کالکوزیت اولیه کدام است؟ $(Cu = ۶۴, S = ۳۲ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6690, '122-کدام‌یک از عبارت‌های زیر درست است؟\n\nالف) در همه عنصرهای دسته $d$، شماره گروه آن‌ها با مجموع شمار الکترون‌های $ns$ و $(n-1)d$ در آرایش الکترونی برابر است.\n\nب) واکنش بی‌هوازی تخمیر گلوکز، از جمله واکنش‌هایی است که برای تهیه سوخت سبز به کار می‌رود.\n\nپ) به دلیل غلظت بیشتر برخی گونه‌های فلزی، مانند منگنز، کبالت، آلومینیم و مس، می‌توان آن‌ها را از کف اقیانوس استخراج کرد.\n\nت) با توجه به استخراج فلزها از سنگ معدن و بازگشت فلزها از طریق خوردگی و فرسایش به طبیعت، می‌توان فلزها را منابعی تجدیدپذیر دانست.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6691, '123-چند مورد از مطالب زیر در رابطه با ارزیابی چرخه عمر، درست است؟\n\n• برای ارزیابی میزان تأثیر یک فراورده بر روی محیط زیست در مدت طول عمر آن به کار می‌رود.\n\n• شامل ارزیابی از چهار مرحله استخراج و تولید مواد خام برای تولید یک فراورده، توزیع، مصرف و دفع آن است.\n\n• شامل بررسی و ارزیابی میزان آب و انرژی مصرفی و سهم حمل‌ونقل در همه مراحل است.\n\n• حاصل تلاش برای یافتن شاخص‌هایی است که کمک می‌کنند صنایع گوناگون در مسیر بهره‌گیری از دانش فنی و تخصصی سازگارتر با محیط زیست حرکت کنند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6692, '124-کدام مطلب درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6693, '125-نمودار زیر، ترتیب نقطه جوش آلکان‌های راست‌زنجیر را نشان می‌دهد. با توجه به آن، کدام مطلب نادرست است؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6694, '126-در چه تعداد از هم‌پارهای هپتان، فقط دو شاخه فرعی متیل وجود دارد؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6695, '127-اگر در ساختار آلکانی، فقط شش گروه $CH_۲$، دو گروه $CH$ و یک گروه $C$ وجود داشته باشد، چه تعداد از مطالب زیر، در مورد آن درست است؟\n\n• نقطه جوش آن به یقین کمتر از دکان راست‌زنجیر است.\n\n• این ترکیب دارای چهار شاخه فرعی متیل بوده و فاقد شاخه فرعی اتیل است.\n\n• شمار پیوندهای کربن - هیدروژن در ساختار آن، ۱۱ واحد بیشتر از شمار اتم‌های کربن است.\n\n• نام این ترکیب به یقین «۲، ۳، ۳، ۴ - تترامتیل پنتان» است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6696, '128-مخلوطی از دو آلکان به مقدار ۱ مول در اختیار داریم. اگر تفاوت جرم مولی آن‌ها برابر ۲۸ گرم بر مول بوده و در اثر سوختن کامل آن‌ها، ۳۳/۶ لیتر گاز کربن دی‌اکسید در شرایط STP تولید شود، چند درصد حجمی این مخلوط را آلکان سبک‌تر تشکیل داده است؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6697, '129-کدام مطلب نادرست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6698, '130-در اثر انجام کامل واکنش‌های زیر، نسبت شمار پیوندها به اتم‌های کربن در محصولات واکنش‌های $a$، $b$ و $c$، به ترتیب کدام است؟\n\n\n\n$a$) آب + اتیلن $\\rightarrow$\n\n$b$) برم + پروپن $\\rightarrow$\n\n$c$) هیدروژن + استیلن $\\rightarrow$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6699, '131- اگر از واکنش یک هیدروکربن با $12$ گرم برم، $13/5$ گرم محصول سیرشده تولید شود، هیدروکربن مورد نظر، کدام‌یک از ترکیب‌های زیر می‌تواند باشد؟ ($Br=80, C=12, H=1 : g \\cdot mol^{-1}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6700, '132- کدام موارد زیر، درست است؟ الف) در جوشکاری کاربیدی، از سوختن گاز استیلن، دمای لازم برای جوش‌دادن قطعه‌های فلزی تأمین می‌شود. ب) سیکلو (cyclo) پیشوندی به معنای حلقوی است که برای نام‌گذاری همهٔ ترکیب‌های آلی حلقوی به کار می‌رود. پ) نفتالن نوعی ترکیب آروماتیک بوده که نسبت شمار پیوندهای دوگانهٔ کربن - کربن به شمار پیوندهای کربن - هیدروژن در آن، برابر $0/5$ است. ت) در پالایش نفت خام با استفاده از تقطیر جزء‌به‌جزء، هیدروکربن‌های نفت را به صورت مخلوط‌هایی با فرّاریت نزدیک به هم جدا می‌کنند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6701, '133-با توجه به جدول مقابل که بخشی از جدول تناوبی است، هر یک از توصیف‌های زیر (به ترتیب از راست به چپ) را به کدام عنصر نشان داده‌شده در آن می‌توان نسبت داد؟\n\n• هالوژنی که در دمای ۱۷۳ کلوین می‌تواند با گاز هیدروژن واکنش دهد.\n\n• عنصر اصلی که شعاع اتمی آن، از هر دو شبه‌فلز گروه ۱۴، بزرگ‌تر است.\n\n• اتمی که آرایش یون سه بار مثبت آن، مشابه گاز نجیب نیست.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6702, '134-کدام گزینه در مورد نفت خام درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6703, '135-۶۸/۸ گرم $Cu_۲FeS_۲$ با خلوص ۷۵ درصد، با چند لیتر گاز اکسیژن در شرایط STP واکنش می‌دهد و گاز تولیدشده، در واکنش با مقدار کافی کلسیم اکسید با بازدهی ۸۰ درصد، چند گرم فراورده تولید می‌کند؟\n\n\n\n(معادله واکنش‌ها موازنه شود؛ $O = ۱۶, S = ۳۲, Ca = ۴۰, Fe = ۵۶, Cu = ۶۴ : g.mol^{-۱}$)\n\nI) $Cu_۲FeS_۲(s) + O_۲(g) \\rightarrow Cu(s) + FeO(s) + SO_۲(g)$\n\nII) $SO_۲(g) + CaO(s) \\rightarrow CaSO_۳(s)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6704, '136-با توجه به دو فرایند زیر، کدام موارد از مطالب داده‌شده درست است؟\n\n$a$) تخمیر بی‌هوازی گلوکز\n\n$b$) استخراج مس از مس $(I)$ سولفید در معدن مس سرچشمه کرمان\n\nالف) هر دو واکنش، روی محیط زیست تأثیر زیان‌باری دارند.\n\nب) مجموع ضرایب استوکیومتری مواد در معادله موازنه شده واکنش $b$، بیشتر از $a$ است.\n\nپ) فراورده گازی هر دو واکنش، در سوختن زغال‌سنگ نیز تولید می‌شود.\n\nت) واکنش‌دهنده مورد استفاده برای استخراج آهن از سنگ معدن آن در شرکت فولاد مبارکه، همان واکنش‌دهنده مورد استفاده در فرایند $(b)$ است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6705, '137-مخلوطی از گازهای اتیلن و استیلن که در مجموع ۲۰۰ لیتر حجم دارند را با مقدار کافی برم مایع وارد واکنش می‌کنیم. اگر با جذب ۱۶۰۰ گرم برم مایع، هر دو گاز اتیلن و استیلن به طور کامل به ترکیبات سیرشده تبدیل شوند، درصد مولی گاز استیلن در مخلوط اولیه کدام است؟ (حجم مولی گازها را در شرایط آزمایش ۲۵ لیتر در نظر بگیرید. $H = ۱, C = ۱۲, Br = ۸۰ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6706, '138-کدام موارد از مطالب زیر، درست است؟\n\nالف) رابطه نقطه جوش آلکان‌های راست‌زنجیر با تعداد اتم‌های کربن آن‌ها، همانند رابطه واکنش‌پذیری فلزهای قلیایی خاکی با شعاع اتمی آن‌ها است.\n\nب) نام ترکیب $CH_۳CH(CH_۳)(CH_۲)_۲CH(C_۲H_۵)_۲$، ۳ - اتیل - ۶ - متیل اوکتان است.\n\nپ) برای سوختن کامل دو مول از آلکنی که در ساختار پیوند - خط آن، ۴ خط وجود دارد، به ۶ مول گاز اکسیژن نیاز است.\n\nت) شمار اتم‌های هیدروژن مولکول نفتالن، چهار برابر شمار اتم‌های کربنی در آن است که به هیچ اتم هیدروژنی متصل نیستند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6707, '139-کدام موارد از عبارت‌های زیر صحیح است؟\n\nالف) نفت خام مایع غلیظ سیاه رنگ یا قهوه‌ای متمایل به سبز است که به عنوان سوخت فسیلی به کار می‌رود.\n\nب) بیش از ده درصد از نفت خام مصرفی در دنیا برای تولید الیاف، پارچه و شوینده‌ها و ... به کار می‌رود.\n\nپ) نقش نخست نفت خام در دنیای کنونی، ماده اولیه برای تهیه بسیاری از مواد و کالاهای صنایع گوناگون است.\n\nت) روزانه بیش از $۱/۲\\times ۱۰^{۱۰}$ لیتر نفت خام در دنیا به شکل‌های گوناگون مصرف می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6708, '140-چند مورد از مطالب زیر درست است؟\n\nالف) بیش از ۹۰ درصد نفت خام دنیا در مصرف انرژی کاربرد دارد.\n\nب) نفت خام یکی از سوخت‌های فسیلی است که به شکل مایع غلیظ سیاه‌رنگ وجود دارد.\n\nپ) عنصر کربن در ششمین خانه جدول قرار دارد و در لایه ظرفیت خود ۴ الکترون دارد.\n\nت) ترکیب‌های شناخته شده از کربن، از مجموع ترکیب‌های شناخته شده از دیگر عنصرهای جدول بیشتر است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6709, '141-کدام موارد از عبارت‌های مطرح شده، عبارت زیر را به نادرستی تکمیل می‌کنند؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$\n\nدر نمودار مقابل، $x$ و $y$ می‌توانند به ترتیب ... و ... باشند. (در نمودار مقابل نزولی یا صعودی بودن و روند کلی مدنظر است و خطی یا سهمی بودن آن مورد توجه نباشد.)\n\n\n\nالف) شمار پیوندهای $C-H$ در آلکن‌ها - درصد جرمی کربن در آن‌ها\n\nب) شمار اتم‌های هیدروژن در یک آلکان راست‌زنجیر - تفاوت نقطه جوش آن آلکان با آلکان بعدی\n\nپ) شمار پیوندهای کووالانسی در آلکان‌ها - گرانروی\n\nت) جرم مولی در آلکین‌ها - دمایی که در آن میعان می‌یابند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6710, '142-چند مورد از عبارات زیر صحیح است؟\n\nالف) رابطه بین نقطه جوش آلکان‌های راست‌زنجیر و جرم مولی آن‌ها، مستقیم است.\n\nب) آلکان‌ها به دلیل ناقطبی و نامحلول بودن در آب می‌توانند برای حفاظت از خوردگی فلزها استفاده شوند.\n\nپ) تجزیه نشان می‌دهد که گشتاور دوقطبی مولکول‌های سازنده چربی‌ها برابر صفر است.\n\nت) پس از شستن دست با بنزین، پوست دست حالت چرب‌مانندی به خود می‌گیرد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6711, '143-درصد جرمی کربن در یک آلکان راست‌زنجیر، ۹٪ بیشتر از درصد جرمی این عنصر در هر مولکول از گاز مرداب است. کدام مورد درباره این آلکان درست است؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6712, '144-در اتم $X$ تعداد الکترون‌های موجود در زیرلایه $4p$، دو برابر تعداد الکترون‌های موجود در زیرلایه $4s$ است و در اتم $Y$ تعداد الکترون‌های موجود در زیرلایه $3d$، ۵ برابر تعداد الکترون‌های موجود در زیرلایه $4s$ است. کدام‌یک از عبارت‌های زیر در مورد ۲ عنصر $X$ و $Y$ درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6713, '145-کدام‌یک از گزینه‌های زیر نادرست است؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6714, '146-اگر در واکنش سوختن پنتان، $\\frac{۲}{۵}$ اتم‌های کربن به جای تبدیل شدن به کربن دی‌اکسید به کربن مونوکسید تبدیل شود، مجموع ضرایب استوکیومتری مواد واکنش‌دهنده کدام است و به ازای مصرف ۰/۴۲ مول گاز اکسیژن در شرایط STP، نسبت جرم تقریبی گاز(های) قطبی تولید شده به جرم گاز(های) ناقطبی تولید شده چقدر است؟ $(C = ۱۲, O = ۱۶ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6715, '147-کدام مورد، نادرست است؟ (در عناصر ذکر شده، گاز نجیب را در نظر نگیرید.)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6716, '148-نمونه‌ای به جرم ۱۶/۸ گرم از یک فلز قلیایی ($M$) در واکنش با مقدار کافی گاز کلر، ترکیبی یونی به جرم 10۲ گرم ایجاد می‌کند. چند مورد از عبارت‌های زیر در رابطه با این فلز درست است؟ $(Li = ۷, Na = ۲۳, K = ۳۹, Cl = ۳۵/۵ : g.mol^{-۱})$\n\n- نور آزاد شده طی این واکنش، انرژی کمتری نسبت به پرتو سبزرنگ دارد.\n\n- شعاع اتمی آن از شعاع اتمی فلز کلسیم، بیشتر است.\n\n- این عنصر در جدول تناوبی، با اولین شبه‌فلز گروه ۱۴ در یک تناوب قرار دارد.\n\n- نماد این عنصر به صورت تک‌حرفی بوده و ۱۹ ذره زیراتمی باردار در هسته هر اتم خود دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6717, '149-چند مورد از عبارت‌های زیر درست است؟\n\n- آلومینیم فلزی از دسته $p$ جدول دوره‌ای بوده و با از دست دادن ۳ الکترون به آرایش الکترونی گاز نجیب دوره قبل از خود می‌رسد.\n\n- همه عناصر گروه دوم جدول دوره‌ای، فلز هستند و فقط در تشکیل ترکیب یونی نقش دارند.\n\n- $CaCl_۲$ به دلیل آنکه از ۳ یون تشکیل شده است، جز ترکیب‌های یونی دوتایی به حساب نمی‌آید.\n\n- هر ترکیب یونی از لحاظ بار الکتریکی خنثی است، زیرا مجموع شمار کاتیون و آنیون در آن‌ها برابر است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6718, '150-مخلوطی از ۵ مول گاز متان و استیلن در اختیار داریم و آن را با ۴ مول گاز هیدروژن به طور کامل واکنش می‌دهیم تا ماده‌ی سیرنشده‌ای در مخلوط باقی نماند. فشار مخلوط مواد بعد از انجام واکنش، چند برابر فشار مخلوط اولیه است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6719, '151-در محلولی از کلسیم برمید به جرم ۲۰۰ گرم، غلظت مولی یون برمید برابر ۳/۵ مولار است. با استفاده از آب موجود در این محلول، چند گرم اتن را می‌توان در شرایط مناسب به اتانول تبدیل کرد؟ $(H=۱, C=۱۲, Ca=۴۰, Br=۸۰ : g.mol^{-۱}, d_{\\text{محلول}}=۱/۲۵ g.mL^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6720, 'با توجه به ساختار پیوند - خط مقابل، کدام‌یک از موارد داده شده درست است؟\n\nالف: از میان پیوندهای یگانه موجود در ساختار، آنتالپی پیوند $C-H$ از بقیه بیشتر است.\n\nب: مجموع شمار اتم‌ها در هر مولکول از آن، با عدد اتمی تنها نافلز مایع در دمای اتاق برابر است.\n\nپ: گروه عاملی موجود در آن را می‌توان در ساختار سلولز نیز مشاهده کرد.\n\nت: آلکانی راست‌زنجیر با شمار اتم‌های کربن برابر با این مولکول، نسبت به آلکانی با ۲۸ پیوند $C-H$، گرانروی بیشتری دارد.', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:29:50', 4, 'done'),
(6721, '153-در کدام‌یک از گزینه‌های زیر نام آلکان با ساختار رسم شده مطابقت ندارد؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6722, '154-جرم مولی آلکین $X$، $\\frac{۲}{۵}$ جرم مولی آلکان $Y$ است. اگر برای سوزاندن کامل یک مول از آلکان $Y$ و آلکین $X$ در مجموع ۱۵ مول اکسیژن لازم باشد، در مخلوطی شامل نیم مول از هر کدام از این دو هیدروکربن، چند پیوند کربن - کربن یگانه وجود دارد؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6723, '155-با توجه به واکنش‌های روبه‌رو همه عبارت‌های زیر درست‌اند، به‌جز ...\n\n\n\n$I) C_۲H_۴(g) + H_۲O(l) \\xrightarrow{\\text{کاتالیزگر}} A$\n\n$II) C_۲H_۴(g) + Br_۲(l) \\longrightarrow B$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6724, '156-چند مورد از عبارت‌های زیر با توجه به ترکیب داده شده نادرست است؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$\n\n[ساختار پیوند-خط یک آلکان]\n\nالف) نام آن ۳-اتیل - ۵ متیل هپتان است.\n\nب) جرم مولی آن ۳/۵۵ برابر جرم مولی پروپین است.\n\nپ) فرمول مولکولی آن با فرمول مولکولی ۳- ۳دی متیل اوکتان یکسان است.\n\nت) شمار گروه‌های $CH_۳$ در مولکول آن $۱/۲$ برابر شمار گروه‌های $CH_۲$ است.\n\nث) اختلاف شمار پیوندهای کووالانسی با شمار پیوندهای $C - C$ برابر ۲۱ است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6725, '157-اگر نسبت جرم کربن به جرم هیدروژن در یک آلکان شاخه‌دار برابر با ۵/۴ باشد و دو شاخه فرعی متیل و یک شاخه فرعی اتیل در ساختار آن وجود داشته باشد، با توجه به ساختارهای متفاوت قابل رسم برای آن، کدام گزینه درست است؟ $(C = ۱۲, H = ۱ : g.mol^{-۱})$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6726, '158-همه گزینه‌های زیر نادرست هستند، به جز:', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6727, '159-چند مورد از عبارت‌های زیر درست است؟\n\n- در عنصرهای گروه ۱۷ جدول دوره‌ای، با افزایش عدد اتمی واکنش‌پذیری کاهش می‌یابد.\n\n- در دوره سوم، با افزایش عدد اتمی، جاذبه هسته روی الکترون‌های آخرین لایه افزایش و شعاع اتمی کاهش می‌یابد.\n\n- فلز طلا واکنش‌پذیری کمی دارد و فقط با برخی از گازهای موجود در هوا کره واکنش می‌دهد.\n\n- رسوب حاصل از واکنش محلول آهن (II) کلرید با محلول سدیم هیدروکسید، به رنگ قرمز مایل به قهوه‌ای است.\n\n- آخرین عنصر واسطه هر دوره در گروه ۱۰ جدول دوره‌ای جای دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6728, '160-جرم‌های برابری از منیزیم سولفات و کلسیم کربنات ناخالص را در شرایط استاندارد تجزیه می‌کنیم اگر جرم گاز گوگرد تری‌اکسید تولید شده در واکنش اول برابر با ۷۵ درصد جرم گاز تولید شده در واکنش دوم باشد، درصد خلوص نمونه منیزیم سولفات چه قدر می‌باشد؟ (درصد خلوص کلسیم کربنات را ۸۰٪ در نظر بگیرید)\n\n\n\n$(O = ۱۶, C = ۱۲, Ca = ۴۰, Mg = ۲۴, S = ۳۲ : g.mol^{-۱})$\n\n$MgSO_۴(s) \\rightarrow MgO(s) + SO_۳(g)$\n\n$CaCO_۳(s) \\rightarrow CaO(s) + CO_۲(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6729, '161-مجموع اعداد به کار رفته در نام‌گذاری به روش آیوپاک در یک آلکان شاخه‌دار که فقط یک شاخه فرعی متیل و یک شاخه فرعی اتیل دارد، برابر ۷ است؛ اگر نام این آلکان به هگزان ختم شود، چند مورد از مطالب گفته شده درباره آن درست است؟\n\n- در ساختار آن ۲ گروه $CH_۲$ یافت می‌شود.\n\n- تعداد هیدروژن‌های آن، نصف تعداد هیدروژن‌ها در فرمول تقریبی گریس است.\n\n- تمایل به جاری شدن آن از یک آلکان راست‌زنجیر با ۳۷ جفت الکترون پیوندی کمتر است.\n\n- با تعویض شاخه فرعی متیل و اتیل با یکدیگر، نام این آلکان تغییر نمی‌کند.\n\n- نسبت به «۳، ۳- دی‌اتیل - ۲- متیل پنتان»، تمایل بیشتری برای تبدیل شدن به حالت گازی دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6730, '162-از میان مطالب زیر چند مورد درست است؟\n\n- زغال‌سنگ می‌تواند به عنوان سوخت جایگزین نفت شود، اما باعث تشدید اثر گلخانه‌ای می‌شود.\n\n- به منظور حذف کربن و ناخالصی‌های دیگر می‌توان از شستشوی زغال‌سنگ استفاده کرد.\n\n- برای به دام انداختن $SO_۲$ حاصل از سوختن زغال‌سنگ می‌توان از $CaSO_۳$ استفاده کرد.\n\n- متان گازی بی‌رنگ و سبک با بوی نافذ است که اگر درصد آن در هوای معدن به ۵ درصد یا بیشتر برسد احتمال انفجار وجود دارد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6731, '163-کدام‌یک از مطالب داده شده نادرست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6732, '164-با توجه به شکل زیر که تعدادی از عنصرهای جدول دوره‌ای را نشان می‌دهد، چه تعداد از موارد زیر صحیح است؟\n\n(نماد عنصرها فرضی است.)\n\n\n\nآ) عنصر G فعال‌ترین نافلز جدول دوره‌ای عنصرها است.\n\nب) مقایسه خصلت فلزی: $E < A < B$\n\nپ) خواص فیزیکی و شیمیایی عنصر E به ترتیب بیشتر شبیه عنصرهای G و C است.\n\nت) عنصر F برخلاف عنصر H دارای سطح براق است و جریان برق و گرما را عبور می‌دهد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6733, '165-کدام موارد از مطالب زیر، درست‌اند؟\n\nآ) معمولاً، هرچه واکنش‌پذیری فلزی بیشتر باشد، استخراج آن، دشوارتر است.\n\nب) واکنش‌پذیری هر عنصر، به معنای تمایل اتم آن به انجام واکنش شیمیایی است.\n\nپ) در واکنش: $FeO(s)$ با $Na(s)$، واکنش‌پذیری فراورده‌ها از واکنش‌دهنده‌ها بیشتر است.\n\nت) در واکنش: $Na_۲O(s)$ با $C(s)$، واکنش‌پذیری واکنش‌دهنده‌ها از فراورده‌ها بیشتر است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6734, '166-مطابق واکنش زیر (که یکی از واکنش‌های کتاب درسی است) کدام موارد از عبارت‌های زیر درست است؟\n\n\n\nآ) با ریختن قطعات خراشیده شده یک میخ آهنی زنگ زده در محلول $HCl$ محلولی سبزرنگ ایجاد می‌شود.\n\nب) واکنش مرحله ۱ به صورت: $Fe_۲O_۳(s) + HCl(aq) \\rightarrow FeCl_۳(aq) + H_۲O(l)$ می‌باشد.\n\nپ) محلول B همان محلول بی‌رنگ سدیم کلرید است.\n\nت) رسوب A رسوب قهوه‌ای رنگ آهن (III) کلرید است.\n\nث) واکنش مرحله ۲ به صورت: $FeCl_۳(aq) + NaOH(aq) \\rightarrow Fe(OH)_۳(s) + NaCl(aq)$ می‌باشد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6735, '167-چه تعداد از موارد زیر نادرست هستند؟\n\n- در هر گروه از بالا به پایین فعالیت شیمیایی رو به افزایش است.\n\n- اگر X با ششمین عنصر جدول (Z)، ترکیب $ZX_۲$ تشکیل دهد، X در گروه ۱۶ است.\n\n- هشت عنصر در دوره چهارم زیرلایه $l=۲$ کاملاً پر دارند.\n\n- منگنز (II) کربنات و بلور سنگ فیروزه، همرنگ هستند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6736, '168-کدام‌یک از مطالب زیر درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6737, '169-توصیف زیر برای یکی از عنصرهای جدول به کار رفته است. کدام گزینه ویژگی این عنصر را به درستی بیان می‌کند؟\n\n«عنصری از دسته p که مجموع اعداد کوانتومی اصلی و فرعی الکترون‌های ظرفیتی آن برابر ۱۴ و هم‌چنین تعداد لایه‌های آن یک واحد کمتر از تعداد لایه‌های سومین عنصر هالوژن جدول تناوبی است.»', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6738, '170-اگر ۰/۰۴ مول هیدروکلریک‌اسید ($HCl$) با فلز روی واکنش دهد، نمک حاصل در واکنش با نقره نیترات با بازدهی ۸۸ درصد به تقریب چند گرم ماده نامحلول در آب تولید می‌کند؟ (واکنش‌ها موازنه نیستند.) ($Ag = ۱۰۸, Cl = ۳۵/۵ : g.mol^{-۱}$)\n\n\n\n$Zn(s) + HCl(aq) \\rightarrow ZnCl_۲(aq) + H_۲(g)$\n\n$ZnCl_۲(aq) + AgNO_۳(aq) \\rightarrow AgCl(s) + Zn(NO_۳)_۲(aq)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6739, '171-اگر بازده درصدی واکنش تجزیه سدیم هیدروژن کربنات برابر ۸۰ درصد باشد، بر اثر تجزیه ۲۱ گرم نمونه ناخالص این نمک که شامل ۴۰٪ ناخالصی است، چند لیتر گاز با مولکول‌های قطبی آزاد می‌شود؟ (چگالی گاز کربن دی‌اکسید برابر $۲/۲ \\frac{g}{L}$ می‌باشد.)\n\n(موازنه شود)\n\n\n\n$(Na = ۲۳, C = ۱۲, H = ۱, O = ۱۶ : \\frac{g}{mol})$\n\n$NaHCO_۳(s) \\rightarrow Na_۲CO_۳(s) + CO_۲(g) + H_۲O(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6740, '172- $500$ گرم $Fe_2O_3$ و کربن خالص به نسبت‌های استوکیومتری، در ظرفی وارد واکنش می‌شوند، اگر جرم مخلوط جامد واکنش به $412g$ برسد، درصد خلوص آهن آزاد در مخلوط جامد واکنش در این لحظه چند است؟ ($C=12, O=16, Fe=56 : g \\cdot mol^{-1}$)\n\n$2Fe_2O_3(s) + 3C(s) \\rightarrow 4Fe(s) + 3CO_2(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6741, '173-کدام عبارت‌ها درست هستند؟\n\nآ) علاوه بر هیدروکربن‌های زنجیره‌ای، هیدروکربن‌های حلقوی نیز در نفت خام وجود دارند.\n\nب) مولکول شمار زیادی از مواد مانند کربوهیدرات‌ها، چربی‌ها، آمینواسیدها، آنزیم‌ها و پروتئین‌ها شامل اتم‌های کربن هستند که به سایر اتم‌ها اتصال پیدا کرده‌اند.\n\nپ) گرافیت و الماس، هیدروکربن‌هایی هستند که درصد خلوص کربن در آن‌ها بسیار زیاد است.\n\nت) تفاوت مدل فضاپرکن با مدل گلوله - میله آن است که در مدل گلوله - میله تنها اتم‌های H نشان داده نمی‌شوند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6742, '174-کدام گزینه نادرست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6743, '175-کدام موارد درست است؟\n\nآ) یکی از فراورده‌های پتروشیمی با خاصیت اسیدی، به عنوان کاتالیزگر در واکنش تولید اتانول از اتن نقش دارد.\n\nب) واکنش با برم مایع، یکی از روش‌های شناسایی اتیلن از استیلن است.\n\nپ) نخستین عضو خانواده سیکلوآلکان‌ها و دومین عضو خانواده آلکن‌ها، هم‌پار یکدیگر می‌باشند.\n\nت) شمار پیوندهای دوگانه کربن - کربن نفتالن، دو برابر بنزن است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6744, '176-درستی یا نادرستی چند عبارت داده شده مشابه عبارت زیر است؟\n\n«ارزیابی چرخه عمر اصطلاحی است که برای ارزیابی میزان تأثیر یک فرآورده بر روی محیط‌زیست در مدت طول عمر آن به کار می‌رود.»\n\n• غلظت گونه‌های فلزی موجود در کف اقیانوس‌ها نسبت به ذخایر زمینی آن‌ها بیشتر است.\n\n• بازیافت فلزها از جمله آهن سبب کاهش سرعت گرمایش جهانی می‌شود.\n\n• در ساختار فضاپرکن هیدروژن سیانید ($HCN$)، پیوند سه‌گانه قابل مشاهده است.\n\n• آلکان راست‌زنجیر $C_{۱۰}H_{۲۲}$ در مقایسه با $C_۶H_{۱۴}$ آسان‌تر جاری می‌شود.\n\n• اتم کربن علاوه بر اشتراک الکترون با اتم‌های دیگر می‌تواند با تشکیل آنیون تک‌اتمی به آرایش پایدار برسد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6745, '177-همه موارد زیر نادرست‌اند، به‌جز:', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6746, '178-با توجه به شکل‌های مقابل، چند مورد از عبارت‌های بیان شده صحیح‌اند؟\n\n• نقطه جوش آلکان B بیشتر از آلکان A است.\n\n• شمار پیوندهای C-H در آلکان A کمتر از آلکان B است.\n\n• اگر آلکان B دارای ۱۱ اتم کربن باشد، آلکان A حداقل دارای ۱۲ اتم کربن است.\n\n• نیروی بین مولکولی و گران‌روی آلکان B بیشتر از آلکان A است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6747, '179-نام کدام آلکان زیر براساس قواعد آیوپاک درست نوشته شده است و در ساختار این ترکیب چند جفت الکترون پیوندی وجود دارد؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6748, '180-چند مورد از مطالب زیر، نادرست است؟\n\nآ) در ساختار ماده‌ای که به عنوان ضد بید برای نگهداری فرش و لباس کاربرد دارد، شمار پیوندهای $C-C$، $۰/۷۵$ برابر شمار پیوندهای $C-H$ است.\n\nب) نسبت شمار اتم‌های هیدروژن به شمار اتم‌های کربن در سیکلوهگزان و گاز عمل‌آورنده در کشاورزی یکسان است.\n\nپ) سیکلوآلکان‌ها ترکیباتی سیرشده بوده و در هیچ واکنش شیمیایی شرکت نمی‌کنند.\n\nت) بنزن یک هیدروکربن سیرنشده است و در اثر واکنش کامل یک مول از آن با ۳ مول گاز هیدروژن به سیکلوهگزان تبدیل می‌شود.\n\nث) سرگروه ترکیب‌های آروماتیک و چهارمین عضو خانواده سیکلوآلکان‌ها از جمله هیدروکربن‌های سازنده نفت خام می‌باشند.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6749, '181-آلکین A را در مقدار کافی اکسیژن سوزانده‌ایم. اگر نسبت جرم کربن دی‌اکسید تولید شده به جرم آلکین اولیه، برابر $۳/۳$ باشد، به ترتیب از راست به چپ در ساختار این آلکین چند پیوند اشتراکی وجود دارد و در فرایند سیر شدن کامل این آلکین، چند درصد به جرم مولی آن افزوده می‌شود؟ $(C = ۱۲, H = ۱, O = ۱۶ : g.mol^{-۱})$ (گزینه‌ها را از راست به چپ بخوانید.)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6750, '182-از واکنش سوختن کامل مخلوطی از یک آلکان (دارای a کربن)، آلکن (دارای b کربن) و آلکین (دارای c کربن)، با نسبت‌های مولی مختلف در شرایط مناسب، داده‌های جدول زیر حاصل شده است. کدام مقایسه درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6751, '183-کدام مورد نادرست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6752, '184-کدام‌یک از مطالب زیر در رابطه با پنج عنصر ابتدایی گروه ۱۴ جدول دوره‌ای درست است؟\n\nالف) هر پنج عنصر جریان الکتریکی را از خود عبور می‌دهند و در دما و فشار اتاق به حالت جامد هستند.\n\nب) خواص شیمیایی عنصر اول و دوم به هم شبیه بوده و هر دو می‌توانند جریان گرما را از خود عبور دهند.\n\nپ) ۶۰٪ از این عناصر در اثر ضربه چکش خرد می‌شوند و توانایی تشکیل پیوند اشتراکی را دارند.\n\nت) از واکنش این عناصر (با فرم کلی X) با گاز هیدروژن، مولکول‌هایی با فرمول $XH_۴$ حاصل می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6753, '185-اگر بدانیم مطابق واکنش ترمیت، برای تولید ۱۶۸ گرم آهن ناخالص به ۴۸۰ گرم آهن (III) اکسید ناخالص نیاز باشد، نسبت درصد خلوص آهن (III) اکسید ناخالص به آهن ناخالص کدام است؟ (در شرایط انجام واکنش، بازده درصدی واکنش را ۲۵٪ در نظر بگیرید. $Fe = ۵۶ , O = ۱۶ : g.mol^{-۱}$)\n\n \n\n(معادله واکنش موازنه شود) $Al(s) + Fe_۲O_۳(s) \\rightarrow Al_۲O_۳(s) + Fe(l)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6754, '186-با توجه به معادله واکنش‌های زیر، چند مورد از عبارت‌های داده شده نادرست است؟ (A ،B ،C و D عناصر فرضی هستند.)\n\n \n\nI) $A + BSO_۴ \\rightarrow B + ASO_۴$\n\nII) $A + DSO_۴ \\rightarrow$ در جهت طبیعی واکنش نمی‌دهد\n\nIII) $B + CSO_۴ \\rightarrow C + BSO_۴$\n\nIV) $E + ASO_۴ \\rightarrow$ در جهت طبیعی واکنش نمی‌دهد\n\n• ترتیب مقایسه واکنش‌پذیری عناصر، برخلاف میزان دشواری استخراج و نگهداری آن‌ها به‌صورت $D > A > B > C$ است.\n\n• در واکنش‌های I و III، واکنش‌پذیری مواد سمت چپ بیشتر از مواد سمت راست است.\n\n• واکنش $B + ESO_۴ \\rightarrow$ ممکن است به‌طور خودبه‌خودی انجام نشود.\n\n• واکنش $D + ESO_۴ \\rightarrow$ به‌طور حتم به‌صورت طبیعی انجام می‌شود.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6755, '187-نقره سولفید در طبیعت به‌صورت کانی آرژنتیت یافت می‌شود. در ۳۰۰ گرم کانه ناخالص که ۶۲٪ آن نقره سولفید است، چند گرم نقره یافت می‌شود؟ (در ناخالصی، اتم نقره وجود ندارد.) ($Ag = ۱۰۸, S = ۳۲ : g.mol^{-۱}$)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6756, '188-کدام موارد از مطالب زیر نادرست است؟\n\nالف) برخلاف فلزهای طلا، پلاتین و نقره، مس هرگز در طبیعت به حالت آزاد یافت نمی‌شود.\n\nب) طلا همانند برخی از دیگر فلزات، به شکل کلوخه‌ها یا رگه‌های زرد در لابه‌لای خاک یافت می‌شود.\n\nپ) هشتمین فلز واسطه، در سطح جهان بیشترین مصرف سالانه را در بین صنایع گوناگون دارد.\n\nت) یکی از حوزه‌های پر کاربرد و اقتصادی علم شیمی، یافتن راه‌های گوناگون و مناسب برای استخراج و تولید عنصرها از طبیعت است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6757, '189-چند مورد از مطالب زیر درست است؟\n\n• نزدیک به ۳۰/۵٪ از عناصر موجود در جدول تناوبی متعلق به دسته p بوده که نزدیک به ۳/۳٪ کمتر از درصد عناصر واسطه در جدول است.\n\n• با افزایش نیروهای بین مولکولی در میان هالوژن‌ها، دمای لازم برای واکنش با گاز $H_۲$ همانند تمایل به تشکیل آنیون، افزایش می‌یابد.\n\n• سه مورد از عناصری که بین دو عنصر تناوب دوم و سوم گروه ۱۵ جدول دوره‌ای قرار می‌گیرند، رسانای قوی جریان برق هستند.\n\n• اگر مجموع مقدار n+l برای الکترون‌های ظرفیتی یک فلز قلیایی خاکی برابر ۸ باشد، شعاع اتمی آن از شعاع اتمی $_{۳۸}Sr$ کوچک‌تر و از شعاع اتمی $_{۱۹}K$ بزرگ‌تر است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6758, '190-خروج گاز، ............ تشکیل رسوب نشان دهنده تغییر شیمیایی بوده و مقدار طول موج نور حاصل از واکنش پتاسیم با گاز کلر، ............ از مقدار طول موج نور حاصل از واکنش سدیم با آن است.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6759, '191-اگر در واکنش‌های پی‌درپی زیر، ۵/۶ لیتر گاز نیتروژن در شرایط استاندارد وارد ظرف واکنش شود، در پایان فرآیند چند گرم گاز نیتروژن دی‌اکسید تولید می‌شود؟ (بازده هر دو واکنش برابر ۵۰٪ است.) $(N = 14, O = 16 : g \\cdot mol^{-1})$ $I) N_2(g) + O_2(g) \\rightarrow 2NO(g)$ $II) 2NO(g) + O_2(g) \\rightarrow 2NO_2(g)$', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6760, '192-چهار عنصر $A$، $B$، $C$ و $D$ از گروه فلزهای قلیایی و قلیایی خاکی را در نظر بگیرید. اگر عدد کوانتومی اصلی برای آخرین الکترون دو عنصر $A$ و $B$ برابر ۳ و برای دو عنصر $C$ و $D$ برابر ۴ باشد، کدام مورد درست است؟ (نماد عناصر، فرضی هستند.)', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6761, '193-کدام مورد، درست است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6762, '194-یکی از روش‌های بیرون کشیدن فلز از لابه‌لای خاک، استفاده از گیاهان است. در این روش در معدن یا خاک دارای فلز، گیاهانی را می‌کارند که می‌توانند آن فلز را جذب کنند. سپس گیاه را برداشت می‌کنند، می‌سوزانند و از خاکستر حاصل، فلز را جداسازی می‌کنند. در جدول زیر، داده‌هایی دربارهٔ این روش ارائه شده است. با توجه به آن:\n\nالف) مقدار جرم طلای پالایش شده در ۲۰ تن گیاه با مقدار جرم روی بیرون کشیده شده در چند تن گیاه برابر است؟\n\nب) ده کیلوگرم از گیاهی که برای پالایش نیکل به‌کار می‌رود، حدود ۱/۹ کیلوگرم خاکستر می‌دهد، درصد جرمی فلز نیکل در این خاکستر کدام است؟', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6763, '195-کدام‌یک از مطالب زیر نادرست است؟\n\nالف) هر عنصر فلزی که شمار الکترون‌های با $l = 0$ در آرایش الکترونی آن فرد باشد، در گروه فلزهای قلیایی قرار می‌گیرد.\n\nب) چهارمین عنصر موجود در تناوب سوم، دارای ۸ الکترون با $l = 1$ بوده و دارای رسانایی الکتریکی است.\n\nپ) با افزایش عدد اتمی گازهای نجیب، درصد فراوانی آن‌ها در هوای پاک و خشک افزایش می‌یابد.\n\nت) عدد کوانتومی فرعی برای بیرونی‌ترین زیرلایه اشغال شده در عناصر فلزی می‌تواند برابر با ۱ باشد.', 2, 3, 68, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, NULL, NULL, 'free'),
(6764, 'فلز کروم دارای دو اکسید با فرمول‌های $CrO$ و $Cr_2O_3$ است. اگر یکی از اکسیدهای کروم بتواند با ۲/۳ گرم فلز سدیم واکنش دهد و طی واکنش، ۲/۶ گرم فلز کروم تولید کند، در هر واحد از یون کروم موجود در ترکیب، ................ الکترون در زیرلایه $d$ وجود داشته و جرم ترکیب یونی حاصل طی واکنش برابر ................ گرم است. $(O = 16 , Cr = 52 , Na = 23 : g \\cdot mol^{-1})$', 2, 3, 68, 280, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:29:54', 4, 'done'),
(6765, 'در بین عناصر واسطه تناوب چهارم، چند درصد از عناصر نماد تک حرفی دارند و شمار عناصری از آن‌ها که در آرایش الکترونی اتم خود، زیرلایه تک الکترونی دارند، چند برابر شمار الکترون‌های ظرفیتی عنصر اول این مجموعه است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:29:58', 4, 'done'),
(6766, 'جدول مقابل، بخشی از جدول تناوبی عناصر را نمایش می‌دهد. چه تعداد از موارد زیر درباره عناصر موجود در جدول، درست است؟ (نماد عناصر، فرضی هستند.)\n\n \n\n- عنصری با بیشترین خصلت نافلزی در جدول، دارای کمترین شعاع اتمی است.\n\n- ترتیب قدرت رسانایی الکتریکی سه عنصر $A$، $E$ و $D$ به‌صورت $E < D < A$ است.\n\n- اختلاف شعاع اتمی دو عنصر $L$ و $D$، از اختلاف شعاع اتمی دو عنصر $C$ و $D$ بیشتر است.\n\n- ۷۵ درصد از این عناصر، می‌توانند الکترون‌های ظرفیتی خود را با سایر اتم‌ها به اشتراک بگذارند.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:02', 4, 'done'),
(6767, 'میخی زنگ زده که آغشته به محلول آهن $(II)$ کلرید است را در مقدار کافی از محلول $HCl$ وارد می‌کنیم تا همه زنگ آهن مصرف شود. سپس محلول سدیم هیدروکسید با مقدار کافی را به ظرف واکنش اضافه می‌کنیم تا تمام کلریدهای آهن موجود، به‌طور کامل مصرف شوند. اگر جرم رسوب‌های حاصل (که متمایل به آجری است) برابر ۷/۳۲ گرم و اختلاف جرم رسوب‌های رنگی تولید شده برابر ۵/۵۲ گرم باشد، جرم میخ زنگ زده اولیه چند گرم بوده است؟ (فرض کنید که در شرایط واکنش، $HCl$ با $FeCl_2$ واکنش نمی‌دهد و ۵۰ درصد جرم میخ، زنگ زده است.)\n\n$(Fe = 56 , O = 16 , H = 1 : g \\cdot mol^{-1})$', 2, 3, 68, 281, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:07', 4, 'done'),
(6768, 'کدام آرایش الکترونی مربوط به یون فلز واسطه است؟', 2, 3, 68, 280, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:13', 4, 'done'),
(6769, 'در کدام گزینه شمار موارد نادرست با موارد درست برابر است؟\n\nالف) شمار عناصر فلزی موجود در دسته $s$ جدول تناوبی، ................ برابر شمار عناصر موجود در دسته $p$ این جدول است.\n\nب) خاصیت فلزی عنصر $_{38}Sr$ در مقایسه با خاصیت فلزی عنصر $_{37}Rb$، ................ است.\n\nپ) با افزایش عدد اتمی عناصر موجود در گروه ۱۴، تمایل این عناصر به تشکیل پیوندهای اشتراکی ................ پیدا می‌کند.\n\nت) از میان عناصر کلسیم، منیزیم و استرانسیم، اتم‌های ................ در واکنش با اکسیژن راحت‌تر الکترون از دست می‌دهند.', 2, 3, 68, 279, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:21', 4, 'done'),
(6770, ' مجموع ضرایب استوکیومتری مواد بعد از موازنه واکنش زیر چقدر است و اگر با مصرف $0/5$ مول $Pb_3O_4$ طی واکنش، $47/8$ گرم $PbO_2$ تولید شود، بازده درصدی واکنش کدام است؟ ($O=16 , Pb=207 : g \\cdot mol^{-1}$)\n\n$Pb_3O_4(s) + HNO_3(aq) \\rightarrow Pb(NO_3)_2(aq) + PbO_2(s) + H_2O(l)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:25', 4, 'done'),
(6771, ' نمونه‌ای از سنگ معدن حاوی تیتانیم ($IV$) اکسید به جرم $1/6$ کیلوگرم مطابق با واکنش موازنه نشده زیر با فلز آهن واکنش می‌دهد. اگر جرم مواد یونی پس از انجام واکنش، $320$ گرم تغییر کرده باشد، چند درصد از جرم این نمونه سنگ معدن را تیتانیم ($IV$) اکسید تشکیل داده است؟ ($Fe=56 , Ti=48 , O=16 : g \\cdot mol^{-1}$)\n\n$TiO_2(s) + Fe(s) \\rightarrow Fe_2O_3(s) + Ti(s)$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:29', 4, 'done'),
(6772, 'مجموع اعداد اتمی پنج عنصر متوالی در جدول تناوبی برابر عدد اتمی عنصری از دوره ششم و هم‌گروه با عنصر تکنسیم است. کدام مطلب در مورد این عنصرها درست است؟', 2, 3, 68, 279, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:34', 4, 'done'),
(6773, 'کدام‌یک از واکنش‌های زیر در جهت رفت انجام‌پذیر نیست؟', 2, 3, 68, 281, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:37', 4, 'done'),
(6774, 'در مخلوطی از کلسیم‌کربنات و منیزیم‌سولفات به جرم ۶۰ گرم، نسبت مجموع جرم آنیون‌ها به مجموع جرم کاتیون‌ها برابر ۲/۷۵ است. درصد خلوص منیزیم‌سولفات در مخلوط کدام است؟ $(C = 12 , O = 16 , Mg = 24 , S = 32 , Ca = 40 : g \\cdot mol^{-1})$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:41', 4, 'done'),
(6775, 'اگر در واکنش تخمیر بی‌هوازی گلوکز و تبدیل آن به اتانول، جرم گاز کربن دی‌اکسید تولید شده با جرم گلوکز باقی‌مانده برابر باشد، بازده درصدی واکنش به تقریب کدام است؟ $(H = 1 , C = 12 , O = 16 : g \\cdot mol^{-1})$', 2, 3, 68, 281, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:45', 4, 'done'),
(6776, 'کدام‌یک از گزینه‌های زیر از نظر درستی یا نادرستی مشابه عبارت زیر است؟\n\n«در ساختار تمام ترکیب‌های یونی، دست‌کم یک نوع کاتیون فلزی وجود دارد.»', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:48', 4, 'done'),
(6777, 'برای جذب کامل گاز $CO_2$ حاصل از سوختن آلکانی شاخه‌دار به ۳۵۰ گرم کلسیم اکسید ۸۰ درصد خالص نیاز است. کدام نام را می‌توان به این آلکان نسبت داد؟ $(H = 1 , C = 12 , Ca = 40 : g \\cdot mol^{-1})$', 2, 3, 68, 283, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:52', 4, 'done'),
(6778, 'میان جرم مولی نفتالن $(M_1)$ و جرم مولی هیدروکربنی سیرنشده $(M_2)$ رابطه $M_1 = 2M_2 + 20$ برقرار است. کدام مطلب در مورد این هیدروکربن سیرنشده نمی‌تواند درست باشد؟ $(H = 1 , C = 12 : g \\cdot mol^{-1})$', 2, 3, 68, 283, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 00:28:31', 1, '2026-09-29 15:30:56', 4, 'done'),
(6779, '۱- با توجه به واکنش موازنه نشده زیر کدام مطلب درست است؟\r\n\r\n$C_6H_5CH_3 + H_2SO_4 + KMnO_4 \\rightarrow C_6H_5COOH + K_2SO_4 + MnSO_4 + H_2O$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:15:00', 5, 'done'),
(6780, ' چه تعداد از عبارت‌های داده شده درست هستند؟\n\nالف: گاز تولید شده در واکنش فلز روی با محلول هیدروکلریک اسید، در واکنش جوش شیرین با این اسید نیز تولید می‌شود.\n\nب: پس از انداختن یک قطعه فلز مس در محلول روی سولفات، رسانایی این محلول به‌تدریج افزایش پیدا خواهد کرد.\n\nپ: در آرایش الکترونی کاتیون حاصل از واکنش منیزیم با محلول هیدروکلریک اسید، ۴ الکترون با $l=0$ وجود دارد.\n\nت: گونه کاهنده مصرف شده در واکنش آهن با محلول مس$(II)$ سولفات، متعلق به گروه شماره ۶ جدول دوره‌ای است.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:14:50', 5, 'done'),
(6781, ' بین فلزهای آهن و روی، یک قطعه به جرم 2/6 گرم از فلزی که ذرات آن تمایل بیشتری به از دست دادن الکترون دارند، با چند میلی‌لیتر محلول هیدروکلریک اسید با $pH=1$ به‌طور کامل واکنش می‌دهد و طی این فرایند، چند میلی‌لیتر گاز هیدروژن در شرایط استاندارد تولید می‌شود؟ $(Fe=56, Zn=65: g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:14:37', 5, 'done'),
(6782, ' واکنش‌های الکتروشیمیایی زیر و تغییر دمای ایجاد شده در ظرف مربوط به هر واکنش را در نظر بگیرید:\n\n$(X(s) + Mn^{2+}(aq) \\rightarrow \\Delta\\theta = 0^\\circ C)$\n\n$(Y(s) + Mn^{2+}(aq) \\rightarrow \\Delta\\theta = 18^\\circ C)$\n\n$(Z(s) + Mn^{2+}(aq) \\rightarrow \\Delta\\theta = 9^\\circ C)$\n\nکدام گزینه مقایسه قدرت کاهندگی گونه‌ها را به‌درستی نشان می‌دهد؟ (شرایط انجام واکنش‌ها را یکسان فرض کنید.)', 3, 3, 73, 301, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:14:24', 5, 'done'),
(6783, ' کدام‌یک از مطالب زیر نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:14:11', 5, 'done'),
(6784, 'کدام موارد از عبارت‌های داده شده درست هستند؟\n\nالف: نیم‌واکنش کاهش در فرایند تولید نمک خوراکی از عناصر سازنده آن به‌صورت $ 2 Cl^-(s) \\rightarrow Cl_2(g) + 2 e^-$ است.\n\nب: گاز اکسیژن در واکنش با یک نمونه از فلز پلاتین، از هر اتم فلزی ۲ الکترون گرفته و موجب اکسایش آن می‌شود.\n\nپ: فلزها دارای انرژی ذخیره شده بوده و با اتصال آن‌ها در شرایط مناسب به یکدیگر، می‌توان این انرژی را آزاد کرد.\n\nت: منیزیم در حضور گاز اکسیژن با تولید یک نور زرد رنگ خیره‌کننده سوخته و به منیزیم اکسید تبدیل می‌شود.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:13:59', 5, 'done'),
(6785, 'کدام‌یک از مطالب زیر درست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:13:39', 5, 'done'),
(6786, 'مقدار $48/5 $ گرم از یک نمونه آلیاژ مس و روی، در مقدار کافی از محلول هیدروکلریک اسید انداخته شده است. اگر در پایان این واکنش، مقدار $11/2 $ لیتر گاز در شرایط $STP$ آزاد شود، به ازای هر اتم مس موجود در این آلیاژ، چند اتم روی وجود دارد؟ $(Cu=64, Zn=65 : g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:13:27', 5, 'done'),
(6787, ' در واکنش تولید هر مول آلومینیوم اکسید از عناصر سازنده آن، چند مول الکترون بین گونه‌ها مبادله می‌شود؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:13:07', 5, 'done'),
(6788, ' کدام فلز زیر در مجاورت با محلول روی سولفات، دمای این محلول آبی را به مقدار بیشتری افزایش می‌دهد؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:12:53', 5, 'done'),
(6789, 'چه تعداد از عبارت‌های داده شده در رابطه با فلز سدیم درست هستند؟\n\nالف: این فلز، طی یک واکنش اکسایش-کاهش، با آب واکنش داده و محلول بازی را ایجاد می‌کند.\n\nب: این فلز بسیار نرم بوده و آرایش الکترونی آن به یک زیرلایه تک‌الکترونی ختم خواهد شد.\n\nپ: این عنصر فلزی، با فسفر هم‌تناوب بوده و با عنصر $_{56}X$ در یک گروه مشابه قرار دارد.\n\nت: اگر یک قطعه آن را در محلول مس$(II)$ سولفات بیندازیم، رنگ محلول از بین می‌رود.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:12:45', 5, 'done'),
(6790, ' اگر با وارد کردن تیغه‌ای ۱۰ گرمی از جنس فلز روی درون بشر حاوی محلول مس$(II)$ سولفات، $1/806 \\times 10^{22}$ الکترون بین گونه‌های اکسنده و کاهنده مبادله شود، جرم تیغه .................... گرم .................... پیدا می‌کند. (فرض کنید تمام فلز تولید شده بر روی تیغه رسوب کند. $(Cu=64, Zn=65 : g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:12:31', 5, 'done'),
(6791, ' یک تیغه از جنس فلز منیزیم را در محلول ۲ لیتری از مس$(II)$ سولفات با غلظت اولیه $ 0/5 $ مول بر لیتر و چگالی $1/005 $ گرم بر میلی‌لیتر قرار می‌دهیم. پس از مبادله $3/01 \\times 10^{23}$ الکترون بین گونه‌های اکسنده و کاهنده، غلظت کاتیون مس در محلول مورد نظر برابر با چند $ppm$ می‌شود؟ $(Mg=24, Cu=64 : g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:12:21', 5, 'done'),
(6792, ' پس از موازنه معادله $ClO_4^-(aq) + H^+(aq) + e^- \\rightarrow ClO_3^-(aq) + H_2O(l)$، ضریب الکترون در معادله این نیم‌واکنش، چند برابر ضریب گاز اکسیژن در معادله موازنه شده واکنش سوختن پروپان می‌شود؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:12:06', 5, 'done'),
(6793, ' کدام‌یک از مطالب زیر نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:11:45', 5, 'done'),
(6794, 'کدام‌یک از مطالب زیر نادرست است؟', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:11:31', 5, 'done'),
(6795, ' چه تعداد از مطالب زیر درست است؟\n\nالف: در واکنش یک تیغه فلزی از جنس مس با محلول روی سولفات، فرآورده‌هایی با پایداری بیشتر تولید می‌شوند.\n\nب: با کاهش قدرت کاهندگی فلز به‌کار رفته در ساخت آند یک سلول گالوانی، مقدار $emf$ سلول کاهش پیدا می‌کند.\n\nپ: عنصر فلزی به‌کار رفته در ساخت قطب منفی سلول گالوانی آلومینیوم-مس، در دسته $p$ جدول تناوبی قرار می‌گیرد.\n\nت: از واکنش سوختن منیزیم، به‌عنوان منبع تولید نور استفاده شده و در این فرایند، شعاع گونه اکسنده افزایش می‌یابد.', 3, 3, 73, 301, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:11:17', 5, 'done'),
(6796, ' در یک سلول گالوانی، نیم‌واکنش‌هایی با معادله‌های کاهشی زیر در حال انجام شدن است. درباره واکنش اکسایش-کاهش کلی بین گونه‌های داده شده، کدام مطلب نادرست است؟\n\n$Fe^{3+}(aq) + e^- \\rightarrow Fe^{2+}(aq) \\quad E^\\circ = +0/77V$\n\n$Fe^{2+}(aq) + 2e^- \\rightarrow Fe(s) \\quad E^\\circ = -0/44V$', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:11:02', 5, 'done'),
(6797, 'درصد جرمی فلز نقره در یک قطعه از آلیاژ قلع و نقره برابر ۶۰٪ است. اگر بر اثر واکنش کامل این قطعه با محلول سولفوریک اسید، $ 12/4 L$ گاز تولید شود، جرم این قطعه برابر با چند گرم است؟ (در شرایط آزمایش، حجم هر مول ماده گازی برابر با ۳۱ لیتر است $Sn = 118 : g \\cdot mol^{-1}$ و $Cu = 64$)', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:10:50', 5, 'done'),
(6798, ' در سلول گالوانی استاندارد آلومینیوم-نقره، اگر پس از گذشت مدت زمان معین از شروع به‌کار سلول، غلظت مولی یونی با قدرت اکسندگی کمتر در محلول حاوی خود به $ 1/4 $ مول بر لیتر برسد، در طول این مدت چند گرم از جرم تیغه آندی کاسته شده است؟ (حجم محلول آندی برابر $ 250 mL$ و حجم محلول کاتدی برابر $ 750 mL$ است. $Al = 27$ و $Ag = 108 : g \\cdot mol^{-1}$)', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:10:28', 5, 'done'),
(6799, ' محلول آبی نقره نیترات را در ظرف ساخته شده از کدام فلز زیر می‌توان نگهداری کرد؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:10:18', 5, 'done'),
(6800, ' کدامیک از مطالب زیر در رابطه با سلول گالوانی استاندارد هیدروژن-مس نادرست است؟', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:10:07', 5, 'done'),
(6801, ' شکل زیر ساختار یک سلول گالوانی را نشان می‌دهد. با توجه به شکل، کدام عبارت نادرست است؟ $(E^\\circ(Ag^+/Ag)=+0.78V \\ \\ , \\ \\ E^\\circ(Cu^{2+}/Cu)=+0.34V)$', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:09:59', 5, 'done'),
(6802, ' چند مورد از مطالب زیر نادرست است؟\n\nالف: سوختن هیدروژن در سلول سوختی، منجر به تولید بخار آب شده و این فرآیند بازدهی نزدیک به $ % 60 $  دارد.\n\nب: از سلول‌های گالوانی، برخلاف سلول‌های الکترولیتی، برای تولید انرژی الکتریکی مشاهده می‌شود.\n\nپ: در سلول گالوانی قلع-نقره، در محل الکترود قلع، کاتیون حاصل از فلز قلع مصرف می‌شود.\n\nت: در هر واکنش اکسایش-کاهش، شمار الکترون‌های ظرفیت اتم‌ها دچار تغییر می‌شود.', 3, 3, 73, 301, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:09:48', 5, 'done'),
(6803, ' در مدار خارجی سلول گالوانی آلومینیوم-آهن که با استفاده از دو نیم‌سلول استاندارد ساخته شده، تعداد $ 3/612\\times10^{23}$ الکترون جاری شده است. اگر حجم هر یک از الکترولیت‌های آندی و کاتدی در سلول برابر $ 2 $ لیتر باشد، تفاوت غلظت کاتیون در دو محلول در پایان این فرآیند چقدر خواهد شد؟ (دیواره متخلخل سلول فقط به آنیون اجازه عبور می‌دهد.) $(E^\\circ(Fe^{2+}/Fe)=-0.44V \\ \\ , \\ \\ E^\\circ(Al^{3+}/Al)=-1.66V)$', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-28 11:09:29', 5, 'done'),
(6804, ' در واکنش سوختن کامل یک نمونه از پروپان، مجموع عدد اکسایش اتم‌های کربن به اندازه چند واحد تغییر می‌کند؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:13', 4, 'done'),
(6805, ' کدام مطلب زیر نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:18', 4, 'done'),
(6806, ' کدام موارد از عبارت‌های زیر درست است؟\n\nالف: در نیروگاه‌های حرارتی، بخار آب حاصل از سوزاندن سوخت، توربین را حرکت داده و برق تولید می‌کند.\n\nب: اکسیژن در واکنش با نافلزها، ترکیب‌های مولکولی را تولید کرده و عدد اکسایش آن همواره کاهش می‌یابد.\n\nپ: کاتد سلول سوختی هیدروژن-اکسیژن، در ساختار خود حاوی کاتالیزگر بوده و بخار آب از آن خارج می‌شود.\n\nت: سلول‌های سوختی، نوعی سلول گالوانی بوده و برخلاف باتری‌ها، توانایی ذخیره کردن انرژی شیمیایی را ندارند.', 3, 3, 73, 302, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:22', 4, 'done'),
(6807, ' کدام مطلب زیر درست است؟', 3, 3, 73, 303, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:26', 4, 'done'),
(6808, ' در مدار خارجی یک سلول سوختی هیدروژن-اکسیژن، $ 1/505 \\times 10^{25}$ الکترون مبادله شده است. در این سلول، چند لیتر گاز اکسیژن در شرایط STP مصرف شده و با استفاده از آب تولید شده در این سلول، چند گرم محلول $ 28\\%$ جرمی منیزیم کلرید می‌توان تولید کرد؟ ($H = 1$ و $O = 16 : g.mol^{-1}$)', 3, 3, 73, 302, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:32', 4, 'done'),
(6809, ' شمار اتم‌های کربن با عدد اکسایش منفی در ساختار مولکول مقابل، چند برابر شمار این اتم‌های کربن در ساختار الکل معمولی است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:36', 4, 'done'),
(6810, ' با توجه به نیم‌واکنش‌های کاهشی زیر که مربوط به نمونه‌ای از سلول‌های نور الکتروشیمیایی است، چند مورد از مطالب داده شده نادرست هستند؟ (نیم‌واکنش‌ها موازنه نشده‌اند. $Si = 28 , O = 16 : g.mol^{-1}$)\n\n$SiO_2(s) + H^+(aq) + e^- \\rightarrow Si(s) + H_2O(l) \\quad ; \\quad E^\\circ = -0/84 V$\n\n$H_2O(l) + e^- \\rightarrow H_2(g) + OH^-(aq) \\quad ; \\quad E^\\circ = -0/83 V$\n\nالف: در این سلول، یک شبه‌فلز نقش کاهنده و $H_2O$ نقش اکسنده را ایفا می‌کند.\n\nب: سوخت رایج‌ترین نوع از سلول‌های سوختی، به کمک این سلول قابل تهیه است.\n\nپ: در محلول اطراف آند این سلول، برخلاف محلول اطراف کاتد سلول برقکافت آب، $[OH^-]$ به مرور کاهش می‌یابد.\n\nت: بر اثر افزایش جرم آند این سلول به مقدار $ 5/6 $ گرم، $ 7/84 $ لیتر گاز $H_2$ با حجم مولی $ 28 $ لیتر بر مول آزاد می‌شود.', 3, 3, 73, 303, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:41', 4, 'done'),
(6811, ' کدام مطلب زیر نادرست است؟', 3, 3, 73, 303, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:48', 4, 'done'),
(6812, ' در فرایند خوردگی یک قطعه آهنی، $1680$ میلی‌لیتر گاز اکسیژن در شرایط STP مصرف شده و زنگ آهن نیز پس از تولید، فرو ریخته است. طی این فرایند، جرم تیغه آهنی به اندازه چند گرم کاسته شده است؟ ($Fe = 56 : g.mol^{-1}$)', 3, 3, 73, 304, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:53', 4, 'done'),
(6813, ' الکتریسیته حاصل از اکسید شدن $3$ گرم منیزیم در سلول گالوانی منیزیم - آلومینیم، چند گرم نقره را در یک سلول آبکاری نقره، به جسم مورد نظر می‌تواند انتقال دهد؟ ($Mg = 24$ و $Ag = 108 : g.mol^{-1}$)', 3, 3, 73, 305, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:42:57', 4, 'done'),
(6814, ' کدام موارد از عبارت‌های زیر درست است؟\n\nالف: ترتیب قدرت اکسندگی یون‌های آهن($II$)، قلع($II$) و منیزیم به‌صورت $Mg^{2+} > Sn^{2+} > Fe^{2+}$ است.\n\nب: با قرار دادن یک قطعه آهن در محلول موجود در اطراف آند سلول برقکافت آب، تیغه آهنی خورده می‌شود.\n\nپ: اگر یک قطعه منیزیمی را در تماس با یک جسم مسی قرار بدهیم، جسم مسی در برابر خوردگی محافظت می‌شود.\n\nت: از ورقه‌های آهنی که سطح آن‌ها با لایه‌ی نازک سرب پوشانده شده است، برای ساختن قوطی کنسرو استفاده می‌شود.', 3, 3, 73, 304, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-10-12 22:43:02', 4, 'done'),
(6815, ' کدام مطلب زیر نادرست است؟', 3, 3, 73, 305, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:37:51', 4, 'done'),
(6816, ' چه تعداد از عبارت‌های زیر درست است؟\n\nدر برخی از واکنش‌های شیمیایی، اتم‌های نافلزی با گرفتن یک یا چند الکترون، کاهش یافته و به آنیون تبدیل می‌شوند.\n\nدر نیم واکنش موازنه شده اکسایش اتم‌های اسکاندیم، الکترون ضریب $ 3 $ داشته و در سمت راست معادله قرار دارد.\n\nحضور همزمان گونه‌های اکسنده و کاهنده برای انجام یک واکنش اکسایش - کاهش لازم است.\n\nدر واکنش میان فلز روی و گاز اکسیژن، اتم‌های روی به عنوان عامل اکسنده ایفای نقش می‌کنند.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:37:30', 4, 'done'),
(6817, '41- جدول زیر داده‌هایی را از قرار دادن چهار تیغه فلزی درون محلول $Au(NO_3)_3$ در دمای $ 25^\\circ C$ نشان می‌دهد. با توجه به آن، کدام مطالب درست است؟ ($A$؛ $B$، $C$ و $D$ نمادهای فرضی هستند)\r\n\r\nنماد فلز | شماره گروه | شماره دوره | دمای مخلوط واکنش پس از مدتی ($^\\circ C$)\r\n\r\n$A$ | $8$ | $4$ | $27$\r\n\r\n$B$ | $12$ | $4$ | $28$\r\n\r\n$C$ | $13$ | $3$ | $\\theta$\r\n\r\n$D$ | $11$ | $5$ | $26$\r\n\r\nآ) دمای $\\theta$ بالاتر از $ 28^\\circ C$ است.\r\n\r\nب) قدرت اکسندگی کاتیون $Au^{3+}$ بیشتر از قدرت اکسندگی کاتیون‌های چهار فلز $A$، $B$، $C$ و $D$ است.\r\n\r\nپ) بیشترین شمار الکترون‌های مبادله شده میان تیغه و محلول $Au^{3+}$، مربوط به تیغه $C$ است.\r\n\r\nت) اگر تیغه $D$ را درون محلول هرکدام از کاتیون‌های $A$، $B$ و $C$ قرار دهیم، واکنشی رخ نمی‌دهد.', 3, 3, 73, 301, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:36:59', 4, 'done'),
(6818, ' چه تعداد از عبارت‌های زیر درست است؟\n\nبا دو تیغه مسی و میوه‌ای مانند لیمو می‌توان نوعی باتری ساخت و با آن یک لامپ LED را روشن کرد.\n\nهر نیم‌واکنش اکسایش، هم از نظر جرم و هم از نظر بار الکتریکی باید موازنه باشد.\n\nاگر مجموع $l.n$ تمام الکترون‌های اتم عنصری از دوره سوم جدول برابر $ 34 $ باشد، اتم این عنصر در واکنش‌های اکسایش - کاهش اغلب کاهنده است.\n\nمعادله نیم‌واکنش کاهش در واکنش میان فلز پتاسیم و گاز کلر به صورت $Cl_2(g) + 2e^- \\rightarrow 2Cl^-(g)$ است.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:36:43', 4, 'done'),
(6819, ' کدام‌یک از مطالب زیر نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:36:31', 4, 'done'),
(6820, '44- کدام مطلب زیر درست است؟\r\n\r\nآ) دو رکن اساسی تحقق فناوری‌هایی مانند اتاق باتری، سمعک و قطار برقی، دستیابی به مواد مناسب و تأمین انرژی است.\r\n\r\nب) اندازه‌گیری pH یک محلول به کمک pH سنج دیجیتال و تولید سلول سوختی جزو قلمروهای الکتروشیمی هستند.\r\n\r\nپ) انرژی الکتریکی تولید شده در الکتروشیمی با وجود تحمیل هزینه‌های اقتصادی بالا، پاک است.\r\n\r\nت) در گذشته برای عکاسی از واکنشی به عنوان منبع نور استفاده می‌شد که کاتیون و آنیون فراورده آن، هر دو به آرایش الکترونی یک گاز نجیب می‌رسند.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:36:13', 4, 'done'),
(6821, ' چه تعداد از موارد زیر جزو ویژگی‌های هر واکنش اکسایش - کاهش است؟\n\nآ) انجام این واکنش‌ها با آزاد شدن مقداری انرژی همراه است.\n\nب) شمار الکترون‌های ظرفیتی اتم‌ها در این واکنش‌ها تغییر می‌کند.\n\nپ) دست‌کم یکی از اجزای این واکنش‌ها، ترکیب یونی است.\n\nت) گونه‌های اکسنده و کاهنده، دو عنصر متفاوت هستند.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:35:56', 4, 'done'),
(6822, '46- کدام‌یک از مطالب زیر نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:35:47', 4, 'done'),
(6823, ' کدام مطالب زیر در ارتباط با واکنش فلز روی با محلول مس ($II$) سولفات درست است؟\n\nآ) می‌توان این واکنش را به گونه‌ای انجام داد تا همراه با تولید گرما، از الکترون‌های داد و ستد شده برای ایجاد جریان الکتریکی استفاده کرد.\n\nب) با گذشت زمان به تدریج از شدت رنگ محلول موجود در ظرف کاسته می‌شود.\n\nپ) در این واکنش ابتدا اتم‌های روی اکسایش یافته و پس از آن، یون‌های مس کاهش می‌یابند.\n\nت) در این واکنش همانند واکنش سوختن گاز شهری، فراورده‌ها پایدارتر از واکنش‌دهنده‌ها هستند.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:35:34', 4, 'done'),
(6824, ' کدام عبارت نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:35:21', 4, 'done'),
(6825, ' کدام عبارت نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:35:08', 4, 'done'),
(6826, ' تیغه‌ای از جنس فلز روی در محلول مس ($II$) سولفات قرار داده می‌شود. کدام گزینه در ارتباط با این سامانه نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:34:35', 4, 'done'),
(6827, ' کدام عبارت نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:34:21', 4, 'done'),
(6828, ' بر اساس واکنش زیر، اگر $ 0/25 $ مول الکترون مبادله شود، چه تغییری در جرم محلول ایجاد می‌شود؟\n\n$(Mg = 24 , Cl = 35/5 , Fe = 56 g \\cdot mol^{-1})$\n\n$Mg(s) + FeCl_2(aq) \\rightarrow MgCl_2(aq) + Fe(s)$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:34:07', 4, 'done'),
(6829, '53- یک قطعه فلز روی را درون محلول هیدروکلریک اسید قرار می‌دهیم. چه تعداد از عبارت‌های زیر در مورد این آزمایش درست است؟ (دما را ثابت در نظر بگیرید و از تغییرات حجم صرف‌نظر شود.)\r\n\r\nفلز روی کاهنده و یون هیدرونیوم اکسنده است.\r\n\r\nبا گذشت زمان، غلظت یون هیدروکسید افزایش می‌یابد.\r\n\r\nمیزان رسانایی الکتریکی محلول کمتر می‌شود.\r\n\r\nبا گذشت زمان، pH محلول کاهش می‌یابد.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:33:36', 4, 'done'),
(6830, ' چند مورد از مطالب زیر درمورد الکتروشیمی و کاربردهای آن درست است؟\n\nباتری یکی از فراورده‌های مهم صنعتی است که در محل مورد نیاز، با انجام واکنش‌های شیمیایی، الکتریسیته را تولید و مصرف می‌کند.\n\nالکتروشیمی شاخه‌ای از دانش شیمی است که در افزایش بازده مصرف انرژی، نقش بسزایی دارد.\n\nدستیابی به مواد مناسب و تأمین انرژی، دو رکن اساسی تحقق فناوری‌هایی هستند که افزایش سطح رفاه و آسایش را برای بشر امروز به دنبال داشته‌اند.\n\nپر کاربردترین شکل انرژی در زندگی امروز، انرژی الکتریکی است.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:33:08', 4, 'done'),
(6831, ' کدام مطلب نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:33:19', 4, 'done'),
(6832, '56- کدام مطلب درمورد واکنش تنها نافلز مایع در دمای اتاق با فلز قلیایی هم‌دوره با آن در جدول تناوبی درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6833, ' مجموع $n+l$ تمام الکترون‌های عنصری از دوره سوم جدول تناوبی برابر $ 46 $ است. کدام‌یک از مطالب زیر درمورد این عنصر درست است؟\n\nالف) با گرفتن دو الکترون به آرایش پایدار گاز نجیب قبل از خود می‌رسد.\n\nب) در برابر فلزها همواره نقش اکسندگی دارد.\n\nپ) حالت فیزیکی آن با حالت فیزیکی دو عنصر قبل و بعد از آن در جدول تناوبی یکسان است.\n\nت) با وارد کردن آن به محلول آبی‌رنگ مس ($II$) سولفات، تغییری در شدت رنگ محلول رخ نمی‌دهد.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:32:37', 4, 'done'),
(6834, ' قرار دادن کدام تیغه در محلول $Au^{3+}(aq)$ سبب می‌شود که شمار الکترون‌های بیشتری میان تیغه و محلول مبادله شود؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:32:25', 4, 'done'),
(6835, ' با توجه به واکنش‌های موازنه نشده زیر کدام مطلب به یقین درست است؟\n\n$I) Al(s) + V^{3+}(aq) \\rightarrow Al^{3+}(aq) + V^{2+}(aq)$\n\n$II) Mg(s) + HCl(aq) \\rightarrow MgCl_2(aq) + H_2(g)$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:31:54', 4, 'done'),
(6836, ' چند مورد از مطالب زیر نادرست هستند؟\n\nدر گذشته برای عکاسی از سوختن فلز $Mn$ به‌عنوان منبع نور استفاده می‌شد.\n\nهرچه تغییر دمای مخلوط حاصل از قرار دادن یک تیغه فلزی درون یک محلول الکترولیت بیشتر باشد، شمار الکترون‌های بیشتری میان آن‌ها مبادله شده است.\n\nبا قرار دادن الیاف آهن درون محلول آبی مس ($II$)، تغییری در رنگ محلول ایجاد نمی‌شود.\n\nواکنش فلز روی با محلول هیدروکلریک اسید نمونه‌ای از واکنش‌های اکسایش - کاهش است که آنیون کلرید در آن نقش اکسنده را دارد.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:31:34', 4, 'done'),
(6837, ' تیغه‌ای آلومینیمی به جرم $ 40 $ گرم را درون $ 500 $ میلی‌لیتر محلول $ 2 $ مولار مس ($II$) قرار می‌دهیم. اگر در پایان واکنش و با بی‌رنگ شدن کامل محلول، $ 80 $ درصد از اتم‌های مس بر سطح تیغه نشسته باشند، جرم تیغه چند درصد و چگونه تغییر می‌کند؟\n\n$(Al = 27 , Cu = 64 : g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:31:16', 4, 'done'),
(6838, ' اگر شمار الکترون‌های مبادله‌شده در واکنش تیغه‌ای از جنس فلز روی با یک لیتر محلول هیدروفلوئوریک اسید $ 0/5 $ مولار و $pH = 3/5$ ، برابر $ 9/632 \\times 10^{22}$ باشد، در این مدت‌زمان چند گرم گاز دو اتمی آزادشده است؟\n\n$(H=1 , F=19 : g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:27:32', 4, 'done'),
(6839, ' چه تعداد از عبارت‌های زیر درست است؟\n\nالف) تندر و آذرخش بیانگر جاری شدن انرژی الکتریکی میان سامانه واکنش و محیط پیرامون است.\n\nب) باتری‌ها و سلول‌های سوختی، تأمین انرژی را در موضوع الکتروشیمی برعهده دارند.\n\nپ) برای تولید مواد در مبحث الکتروشیمی از روش‌های برقکافت و آبکاری استفاده می‌شود.\n\nت) در چراغ خورشیدی علاوه بر لامپ LED، سلول خورشیدی و باتری قابل‌شارژ نیز وجود دارد.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:27:06', 4, 'done'),
(6840, ' واکنش $FeCl_3(aq) + KI(aq) \\rightarrow FeCl_2(aq) + I_2(s) + KCl(aq)$، به‌طور طبیعی انجام‌پذیر است. براساس آن کدام عبارت درست است؟ (معادله موازنه شود.)', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:26:55', 4, 'done'),
(6841, '65- براساس معادله موازنه شده، در کدام واکنش تعداد الکترون کمتری مبادله می‌شود؟', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:26:41', 4, 'done'),
(6842, ' قطعه‌ای از جنس فلز روی به جرم $ 30 $ گرم را درون محلولی از مس ($II$) سولفات با غلظت $ 0/2 $ مولار و حجم $ 1500 $ میلی‌لیتر قرار می‌دهیم. پس از پایان واکنش، چند درصد از جرم قطعه روی کاسته می‌شود؟ (تمامی یون‌های مس به‌طور کامل مصرف شده و اتم‌های مس بر سطح قطعه روی نمی‌نشینند.)\n\n$(Cu = 64, Zn = 65 : g \\cdot mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:26:30', 4, 'done'),
(6843, ' با توجه به مقایسه قدرت کاهندگی فلزها، کدام واکنش به‌طور طبیعی انجام می‌شود و مخلوط واکنش با افزایش دمای بیشتری همراه خواهد بود؟ (حجم محلول‌ها در همه واکنش‌ها یکسان)', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:26:17', 4, 'done'),
(6844, ' کدام مورد، نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:25:59', 4, 'done'),
(6845, ' با توجه به شکل زیر، چند مورد از مطالب زیر درست است؟\n\n (شکل اتم‌های A و B با لایه‌های الکترونی)\n\nاتم A با گرفتن دو الکترون، به آرایش گاز نجیب می‌رسد.\n\nاتم B یک عنصر اکسنده قوی است و واکنش‌پذیری بالایی دارد.\n\nتبدیل اتم A به یون پایدار آن به صورت: $A + 2e^- \\rightarrow A^{2-}$ ، انجام می‌شود.\n\nدر واکنش A با B، به ازای انتقال دو مول الکترون، یک مول فراورده تشکیل می‌شود.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:25:39', 4, 'done'),
(6846, ' کدام مورد، نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:25:26', 4, 'done'),
(6847, 'کدام مورد درست است؟ $(Cl = 35/5, Na = 23 : g.mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:25:14', 4, 'done'),
(6848, ' با توجه به واکنش‌های زیر که در شرایط یکسان، به طور خودبه‌خودی انجام می‌شوند، کدام مطالب نادرست است؟ $(Zn = 65 \\text{ g.mol}^{-1})$\n\n\n\nالف) $Al(s) + Cu^{2+}(aq) \\rightarrow$\n\nب) $Cu^{2+}(aq) + Mn(s) \\rightarrow Cu(s) + Mn^{2+}(aq)$\n\nپ) $Zn(s) + V^{3+}(aq) \\rightarrow Zn^{2+}(aq) + V^{2+}(aq)$', 3, 3, 73, 301, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:25:00', 4, 'done'),
(6849, '74- اگر واکنش‌های a و d انجام‌پذیر و واکنش‌های b و c انجام‌ناپذیر باشند، کدام مطلب نادرست است؟ (معادله واکنش‌ها موازنه شود.)\r\n\r\na) $Fe^{3+}(aq) + Sn^{2+}(aq) \\rightarrow Fe^{2+}(aq) + Sn^{4+}(aq)$\r\n\r\nb) $Cr^{3+}(aq) + Fe^{2+}(aq) \\rightarrow Cr(s) + Fe^{3+}(aq)$\r\n\r\nc) $NiSO_4(aq) + Pb(s) \\rightarrow Ni(s) + PbSO_4(s)$\r\n\r\nd) $Cl_2(g) + NaBr(aq) \\rightarrow NaCl(aq) + Br_2(l)$', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:24:46', 4, 'done'),
(6850, ' تیغه‌هایی از فلزهای $D$، $C$، $B$، $A$ در $ 4 $ آزمایش جداگانه در محلول‌هایی که فقط حاوی یک نوع کاتیون فلزهای ذکر شده در شرایط یکسان می‌باشد را قرار می‌دهیم. با بررسی نمودار تقریبی غلظت بر حسب زمان چند مورد از مطالب زیر نادرست است؟\n\nغلظت (مول بر لیتر) / زمان / $[A^{2+}]$ / $[B^{3+}]$\n\nغلظت (مول بر لیتر) / زمان / $[B^{2+}]$ / $[D^+]$\n\nغلظت (مول بر لیتر) / زمان / $[A^{3+}]$ / $[C^{2+}]$\n\nغلظت (مول بر لیتر) / زمان / $[B^{2+}]$ / $[C^{3+}]$\n\n• واکنش $A + B^{3+} \\rightarrow$ انجام‌پذیر است و پس از تکمیل معادلۀ واکنش و موازنه آن، اختلاف ضریب کاهنده با ضریب رسوب ایجادشده برابر $2$ می‌باشد.\n\n• اگر تیغۀ $D$ در محلول حاوی کاتیون $A^{2+}$ قرار بگیرد، به مرور زمان ظرف واکنش گرم‌تر می‌شود.\n\n• با قراردادن تیغۀ $B$ در هر یک از محلول‌های حاوی کاتیون‌های $D^+$ و $C^{2+}$، جرم تیغه تغییر می‌کند.\n\n• واکنش $C + B^{3+} \\rightarrow$ انجام‌ناپذیر است، زیرا قدرت کاهندگی $B$ از $C$ بیشتر است.', 3, 3, 73, 301, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:24:35', 4, 'done'),
(6851, ' کدام‌یک از عبارت‌های زیر نادرست است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:23:30', 4, 'done'),
(6852, ' کدام گزینه از نظر درستی یا نادرستی با سایر گزینه‌ها متفاوت است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:23:20', 4, 'done'),
(6853, ' کدام گزینه صحیح است؟\n\n۱) نقش قلع در هر دو واکنش $ 2Sn(s) + O_2(g) \\rightarrow 2SnO(s)$ و $SnCl_2(aq) + F_2(g) \\rightarrow SnF_2(aq) + Cl_2(g)$ یکسان است.\n\n۲) در واکنش $Zn$ با محلول $CuSO_4$ ابتدا اتم‌های روی، طی نیم‌واکنش $Zn(s) \\rightarrow Zn^{2+}(aq) + 2 e^-$ اکسایش یافته و سپس نیم‌واکنش $Cu^{2+}(aq) + 2e^- \\rightarrow Cu(s)$ رخ می‌دهد.\n\n۳) در یک واکنش اکسایش - کاهش، فلزی که قدرت کاهندگی بیشتری دارد، می‌تواند با برخی از کاتیون‌های فلزی واکنش دهد و آنها را به اتم‌های فلزی بکاهد.\n\n۴) در واکنش فلز روی با محلول هیدروکلریک اسید، اتم‌های روی دچار اکسایش می‌شوند و باعث کاهش یون‌های کلرید در محلول می‌شوند.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:23:08', 4, 'done'),
(6854, ' چند مورد از عبارت‌های زیر، در مورد سوختن منیزیم، درست‌اند؟\n\nالف) در گذشته برای عکاسی به عنوان منبع نور استفاده می‌شده است.\n\nب) گونه کاهنده در واکنش، دارای ۳ زیرلایه ۲ الکترونی در آرایش الکترونی خود است.\n\nپ) مجموع ضرایب مواد در معادله موازنه شده با مجموع ضرایب مواد شرکت‌کننده در واکنش سوختن ساده‌ترین آلکان برابر است.\n\nت) با دادوستد $ 6/02 \\times 10^{23}$ الکترون ۱ مول جامد یونی تولید می‌شود.\n\nث) از فرآورده حاصل از واکنش سوختن این عنصر، برای تبدیل گاز $CO_2$ تولید شده در نیروگاه‌ها به منیزیم کربنات استفاده می‌شود.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:14:41', 4, 'done'),
(6855, ' چند مورد از موارد زیر صحیح است؟\n\nالف) در واکنش فلز روی با اکسیژن، هر یک از مولکول‌های اکسیژن ۲ الکترون گرفته و کاهش می‌یابند.\n\nب) واکنش تولید رسوب نقره کلرید از نقره نیترات و سدیم کلرید از نوع اکسایش - کاهش است.\n\nپ) اتم‌های کلر در واکنش $Ca(s) + Cl_2(g) \\rightarrow CaCl_2(s)$ به عنوان گونه اکسنده کاهش می‌یابند.\n\nت) در واکنش تولید نمک خوراکی از عنصرهای سازنده، هر مولکول کلر با گرفتن ۲ الکترون به یون‌های کلرید کاهش می‌یابد.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:14:24', 4, 'done'),
(6856, ' کدام‌یک از مطالب زیر در مورد واکنش بین فلز آلومینیوم و گاز اکسیژن درست است؟\n\n۱) نام فرآورده تولید شده آلومینیوم (III) اکسید است که نسبت شمار آنیون به کاتیون در آن برابر 1/5 است.\n\n۲) این فرایند با شکسته شدن پیوند کووالانسی و تشکیل پیوند یونی همراه است.\n\n۳) نیم‌واکنش کاتدی به شکل $O_2(g) + 4e^- \\rightarrow 2O^{2-}(s)$ و نیم‌واکنش اکسایش به شکل $Al(s) \\rightarrow Al^{3+}(aq) + 3e^-$ است.\n\n۴) اتم آلومینیوم با از دست دادن سه الکترون به آرایش پایدار گاز نجیب آرگون می‌رسد.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:14:12', 4, 'done'),
(6857, ' کدام گزینه درست نیست؟\n\n۱) اکسیژن نافلزی فعال است که با اکثر فلزات واکنش می‌دهد.\n\n۲) اکسیژن اغلب مواقع در نقش اکسنده ظاهر می‌شود.\n\n۳) در تمام واکنش‌های اکسایش - کاهش آزادسازی انرژی رخ می‌دهد.\n\n۴) گونه کاهنده با از دست دادن الکترون، اکسایش می‌یابد.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:14:04', 4, 'done'),
(6858, ' چند مورد از عبارت‌های مطرح شده جملۀ زیر را به درستی تکمیل می‌کند؟\n\n«در هر واکنش شیمیایی از نوع اکسایش - کاهش .........»\n\n• همواره برخی از کاتیون‌های فلزی که قدرت کاهندگی بیشتری دارند، به اتم‌های فلز کاهش می‌یابند.\n\n• گونه‌های اکسنده و کاهنده ۲ عنصر متفاوت هستند.\n\n• افزون بر داد و ستد الکترون، انرژی (گرما) نیز آزاد می‌شود.\n\n• حداقل یکی از اجزای شرکت‌کننده در واکنش ترکیب یونی است.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:13:51', 4, 'done'),
(6859, ' با توجه به شکل زیر، چند مورد از عبارت‌های زیر درست است؟\n\n$ 2 e^-, 8e^-, 18e^-, 2e^-$\n\n\n\n$ 2 e^-, 6e^-$\n\n$A$\n\n$B$\n\n$ 2 e^-$\n\n$ 2 e^-, 8e^-, 18e^-$\n\n$ 2 e^-, 8e^-$\n\nالف) در شرایط یکسان، واکنش‌پذیری عنصر $B$ از $F$، بیشتر است.\n\nب) $A$ عنصری فلزی است و در این واکنش نقش کاهنده دارد.\n\nپ) فرمول مولکولی ترکیب شیمیایی حاصل از یون $A$ و $B$، به‌صورت $AB$ است.\n\nت) $B$ عنصری نافلزی است و در این واکنش اکسایش یافته است.\n\nث) در این واکنش اکسایش - کاهش، فرایندهای اکسایش و کاهش به‌طور همزمان رخ می‌دهند.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:13:39', 4, 'done'),
(6860, ' پس از موازنه واکنش‌ها در کدام واکنش نسبت ضریب گونه اکسنده به گونه کاهنده، بیشترین مقدار است؟', 3, 3, 73, 300, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:13:24', 4, 'done'),
(6861, ' چه تعداد از موارد زیر دربارۀ واکنش تیغه‌ای از جنس روی با محلول مس (II) سولفات صحیح است؟ $(Zn = 65, Cu = 64 : g.mol^{-1})$\n\n$Zn(s) + CuSO_4(aq) \\rightarrow Cu(s) + ZnSO_4(aq)$\n\nالف) در این واکنش فلز روی عامل کاهنده و یون مس عامل اکسنده است.\n\nب) با کاهش تدریجی غلظت یون $Cu^{2+}$، از شدت رنگ آبی محلول کاسته و جرم تیغه فلزی افزایش می‌یابد.\n\nپ) کاهش جرم ناشی از واکنش کامل یک تیغه 325 گرمی از فلز روی با محلول مس (II) سولفات حداقل 5 گرم است.\n\nت) نیم‌واکنش موازنه شده اکسایش در این فرایند به‌صورت $Zn(s) \\rightarrow Zn^{2+}(aq) + e^-$ است.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:13:12', 4, 'done'),
(6862, ' با توجه به جدول زیر که داده‌هایی را از قرار دادن برخی تیغه‌های فلزی درون محلول مس (II) سولفات در دمای $ 20^\\circ C$ نشان می‌دهد، کدام گزینه نادرست است؟\n\n| نام فلز | نشانه شیمیایی فلز | دمای مخلوط واکنش پس از مدتی $(^\\circ C)$ |\n\n|---|---|---|\n\n| آهن | $Fe$ | ۲۳ |\n\n| طلا | $Au$ | ۲۰ |\n\n| روی | $Zn$ | ۲۶ |\n\n| مس | $Cu$ | ۲۰ |', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:12:59', 4, 'done'),
(6863, ' چند مورد از مطالب زیر درباره الکتروشیمی درست است؟\n\n• تعامل میان شیمی و الکتریسیته است.\n\n• اساس عملکرد آن مبتنی بر قانون بقای انرژی است.\n\n• به بررسی فرایندهایی می‌پردازد که با تبادل الکترون همراهاند.\n\n• به بررسی انرژی مبادله شده در واکنش‌های شیمیایی می‌پردازد.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:12:49', 4, 'done'),
(6864, ' اگر مقایسه قدرت کاهندگی چند فلز به‌صورت $A > D > B > C$ باشد، چند مورد از مطالب زیر به درستی بیان شده‌اند؟\n\n• واکنش $... \\rightarrow D(s) + C(NO_3)_2(aq)$ انجام‌پذیر است و با انجام آن گرما از سامانه به محیط جاری می‌شود.\n\n• اگر B فلز مس باشد، C می‌تواند اولین فلز دسته p جدول تناوبی باشد.\n\n• محلول حاوی یون‌های $A^{2+}$ را می‌توان در ظرف‌های از جنس هر سه فلز B ،C و D نگهداری کرد.\n\n• اگر واکنش $... \\rightarrow M(s) + BCl_2(aq)$ انجام‌پذیر باشد، واکنش $... \\rightarrow D(s) + MCl_2(aq)$ نیز انجام‌پذیر است.', 3, 3, 73, 301, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:12:39', 4, 'done'),
(6865, ' فلز Al می‌تواند فلز Mn را از محلول آبی دارای یون‌های $Mn^{2+}(aq)$ خارج کند. فلز Mn نیز می‌تواند فلز V را از محلول آبی دارای یون‌های $V^{2+}(aq)$ خارج کند. با توجه به این داده‌ها، در کدام گزینه قدرت اکسندگی گونه‌ها درست مقایسه شده است؟', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:12:27', 4, 'done'),
(6866, ' کدام موارد از مطالب زیر، نادرست هستند؟\n\nالف) در واکنش فلزات مختلف با محلول مس (II) سولفات در دما و غلظت یکسان، هرچه $\\Delta\\theta$ محلول پس از مدت زمان معین بیشتر باشد، نشانگر کاهش انرژی سامانه و ایجاد پایداری بیشتر است.\n\nب) واکنش $x_2(g) + 4e^- \\rightarrow 2x^{2-}(s)$ از نوع کاهش می‌باشد.\n\nپ) عنصر A که دومین عنصر جدول با ۱۸ الکترون در لایه سوم است، در واکنش با $O_2$ از الکترون‌های لایه سوم و چهارم خود برای مبادله الکترون استفاده می‌کند و دچار اکسایش می‌شود.\n\nت) در هر واکنش شیمیایی هنگامی‌که بار الکتریکی یک گونه مثبت‌تر می‌شود، یعنی اکسایش رخ داده است.', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:12:17', 4, 'done'),
(6867, ' چند مورد از عبارت های زیر نادرست است؟ \n\nالف) در اثر قرار دادن یک تیغه Al در $CuSO_4 (aq)$ دمای آن افزایش می یابد. زیرا سامانه واکنش همه انرژی خود را به شکل گرما به محیط میدهد.\n\nب) در واکنش فلز روی با گاز اکسیژن مجموع ضرایب گونه های شرکت کنند در نیم واکنش کاهش برابر 4 است\n\nپ) در واکنش $ Fe(NO_3)_2 + AgNO_3\\rightarrow Fe(NO_2)_3 + Ag$ یون $Fe^{2+}$ نقش اکنسده را دارد.\n\nت) در واکنش موازنه نشده $KMnO_4 + HCl \\rightarrow Cl_2 + KCl+ H_2 O$ ، $ %62/5 $ از یون های کلرید در نقش کاهنده وارد عمل می شوند.', 3, 3, 73, 300, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:12:05', 4, 'done'),
(6868, 'اگر تیغه‌ای از جنس $Ni$ درون محلول نقره نیترات قرار گیرد، با مبادله $ 3/01 \\times 10^{23}$ الکترون بین آن‌ها و با فرض این‌که تنها ۲۰ درصد از یون‌های نقره بر روی تیغه رسوب کند، جرم تیغه چه تغییری می‌کند؟ $(Ni=58, Ag=108 : g.mol^{-1})$\n\n$Ni + 2Ag^+ \\rightarrow Ni^{2+} + 2Ag$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:11:47', 4, 'done'),
(6869, ' در واکنش تیغه آلومینیمی با محلول مس (II) سولفات با حجم ۲ لیتر، در مدت معین جرم تیغه به اندازه 27/6 گرم افزایش یافته است. اگر بدانیم غلظت پایانی محلول مس (II) سولفات برابر $ 1/7 mol.L^{-1}$ باشد، غلظت اولیه محلول چند مولار و مقدار مول مصرفی فلز آلومینیم چند مول است؟ $(Cu=64, Al=27 : g.mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:11:32', 4, 'done'),
(6870, ' تیغه ۳۵ گرمی از فلز کروم را وارد محلولی از $X(NO_3)_n$ می‌کنیم. مدتی پس از شروع واکنش، ۶۰ درصد از فلز X تولید شده روی تیغه رسوب کرده و جرم آن ۴۸ درصد افزایش می‌یابد. اگر در این مدت $ 5/418 \\times 10^{23}$ الکترون بین گونه‌های اکسنده و کاهنده مبادله شود، نسبت عددی جرم مولی فلز X به n کدام است؟ $(Cr=52 : g.mol^{-1})$\n\n(معادله واکنش موازنه شود) $Cr(s) + 3X(NO_3)_n(aq) \\rightarrow nCr(NO_3)_3(aq) + 3X(s)$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:11:20', 4, 'done'),
(6871, ' با توجه به پتانسیل‌های کاهشی استاندارد داده شده، کدام موارد از مطالب زیر درست است؟\n\n$(E^\\circ(Fe^{2+} / Fe) = -0.44V, E^\\circ(Cu^{2+} / Cu) = +0.34V, E^\\circ(Ag^+ / Ag) = +0.8V)$\n\nالف: در سلول گالوانی تشکیل شده از نیم‌سلول‌های مس و نقره، آنیون‌ها به سمت نیم‌سلول نقره حرکت می‌کنند.\n\nب: قوی‌ترین اکسنده، $Ag^+$ و قوی‌ترین کاهنده، $Fe$ است.\n\nپ: پتانسیل سلول گالوانی استاندارد «آهن - مس» کمتر از دو برابر پتانسیل ایجاد شده در سلول گالوانی استاندارد «مس - نقره» است.\n\nت: فلز نقره نسبت به فلز مس تمایل بیشتری برای از دست دادن الکترون دارد.', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:11:00', 4, 'done'),
(6872, ' تیغه‌ای به جرم ۵۴ گرم از جنس آلومینیم را وارد محلولی از $Cu^{2+}$ می‌کنیم. پس از گذشت ۱۰ دقیقه از شروع واکنش تعداد یون‌های موجود در محلول $ 3/612 \\times 10^{23}$ عدد تغییر می‌کند. در این لحظه چند درصد تیغه آلومینیمی دست نخورده باقی مانده است؟ $(Cu = 64, Al = 27 : g.mol^{-1})$', 3, 3, 73, 300, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:10:46', 4, 'done'),
(6873, ' با توجه به سلول گالوانی زیر، کدام مطلب درست است؟', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:10:28', 4, 'done'),
(6874, ' با توجه به جدول زیر کدام مورد، نادرست است؟\n\nنیم‌واکنش کاهش / $E^\\circ(V)$\n\n$A^+(aq) + e^- \\rightarrow A(s)$ / $+1.33$\n\n$B^{2+}(aq) + 2e^- \\rightarrow B(s)$ / $+0.87$\n\n$C^{3+}(aq) + e^- \\rightarrow C^{2+}(aq)$ / $-0.12$\n\n$D^{3+}(aq) + 3e^- \\rightarrow D(s)$ / $-1.59$', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:10:15', 4, 'done'),
(6875, '101- در سلول گالوانی $Fe - Ag$ اگر مجموع افزایش جرم الکترودهای آند و کاتد برابر $ 0/32 $ گرم باشد، تعداد الکترون‌های جابه‌جا شده از مدار بیرونی سلول چقدر است و کدام نمودار مربوط به تغییر غلظت الکترولیت‌ها بر حسب زمان در سلول استاندارد «آهن - نقره» است؟\r\n\r\n$(E^\\circ(Fe^{2+} / Fe) = -0.44V, E^\\circ(Ag^+ / Ag) = +0.8V, Fe = 56, Ag = 108 : g.mol^{-1})$', 3, 3, 73, 301, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, '2026-03-27 23:09:40', 4, 'done'),
(6876, '102- کدام موارد در ارتباط با واکنش میان اولین فلز جدول دوره‌ای (عنصر A) و واکنش‌پذیرترین نافلز جدول دوره‌ای (عنصر B) درست است؟\n\nالف: در این واکنش عنصر A، اکسنده و عنصر B کاهنده است.\n\nب: نیم‌واکنش اکسایش واکنش انجام گرفته به‌صورت $A(s) \\rightarrow A^+(s) + e^-$ است.\n\nپ: در این واکنش عنصر A، به آرایش الکترونی گاز نجیبی از دسته p می‌رسد.\n\nت: اختلاف عدد اتمی این دو عنصر برابر با عدد اتمی عنصر مشهور به سرب مداد است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6877, '۱۰۳ - با توجه به نمودار زیر که هر خط آن نشان‌دهنده ی یک سلول گالوانی است، کدام گزینه نادرست است؟\n\n$E^\\circ (V)$\n\n$Ag^+ / Ag$\n\n$Cu^{2+} / Cu$\n\n$Fe^{2+} / Fe$\n\n$Zn^{2+} / Zn$\n\n$Mg^{2+} / Mg$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6878, '۱۰۴ - در سلول گالوانی «منیزیم-آلومینیوم» پس از گذشت ۱۵ دقیقه، ۸۰ درصد از جرم تیغه آندی کم و $ 4/32$  گرم به جرم تیغه کاتدی افزوده شده است. اگر فرض کنیم جرم اولیه تیغه‌ها با هم برابر باشد، مجموع جرم تیغه‌ها پس از گذشت ۱۵ دقیقه از انجام واکنش چند گرم خواهد بود و سرعت متوسط تولید آلومینیوم در این بازه زمانی چند مول بر ساعت است؟ $(Al=27, Mg=24 : g \\cdot mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6879, '106- با توجه به جدول زیر که سری الکتروشیمیایی را به صورت نامنظم نمایش می‌دهد، چند مورد از مطالب داده شده، نادرست است؟\n\nنیم‌واکنش کاهش / $E^\\circ(V)$\n\n$A^+(aq) + e^- \\rightarrow A(s)$ / $+0.8$\n\n$M^{3+}(aq) + 3e^- \\rightarrow M(s)$ / $-1.66$\n\n$N^{2+}(aq) + 2e^- \\rightarrow N(s)$ / $-0.44$\n\n$B^{2+}(aq) + 2e^- \\rightarrow B(s)$ / $-0.76$\n\n$ 2 C^+(aq) + 2e^- \\rightarrow C_2(g)$ / $0.00$\n\n• $M$ قوی‌ترین کاهنده و $A$ قوی‌ترین اکسنده می‌باشد.\n\n• گونه $N$ می‌تواند سبب کاهش یون $B^{2+}$ شود.\n\n• سلول «$M - A$» در بین سلول‌های ساخته شده از جدول، بیشترین ولتاژ را دارد.\n\n• در سلول گالوانی «$M - C_2$»، فلز $M$ قطب منفی سلول به‌حساب می‌آید و $C_2$، کاتد است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6880, '107- چند مورد از عبارت‌های زیر درست است؟\n\n• با فرو بردن دو تیغه از جنس مس درون لیمو، می‌توان باتری لیمویی ساخت.\n\n• چراغ خورشیدی متشکل از لامپ LED، سلول خورشیدی و باتری قابل شارژ است.\n\n• شکل روبه‌رو قلمرو الکتروشیمی در تولید مواد را نشان می‌دهد.\n\n• باتری مولدی است که در آن بخشی از انرژی شیمیایی مواد به انرژی الکتریکی تبدیل می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6881, '108- با توجه به عناصر مشخص شده در بخشی از جدول تناوبی زیر، چند مورد از عبارت‌های داده شده درست است؟ ($E^\\circ$ عنصر C از $E^\\circ$ عنصر Y بیشتر است.)\n\n• در میان عناصر مشخص شده، کمترین $E^\\circ$ به عنصر O و بیشترین $E^\\circ$ مربوط به عنصر C است.\n\n• محلولی از یون‌های عنصر A را می‌توان در ظرفی از جنس فلز X نگهداری کرد.\n\n• سلول گالوانی متشکل از عناصر Y و Z، emf بزرگتری از سلول گالوانی متشکل از عناصر A و C دارد.\n\n• در صورت قرار دادن تیغه‌هایی از جنس عناصر مشخص شده در محلول کاتیون عنصر B، تنها در یک ظرف تغییرات دمایی مشاهده می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6882, '109- با توجه به شکل مقابل چند مورد از مطالب زیر درست است؟\n\n• در این واکنش، B همان عنصر اول گروه شانزدهم جدول است و نقش اکسنده را دارد.\n\n• در آرایش الکترونی A، ۳ لایه پر از الکترون وجود دارد.\n\n• C و $Cu^+$ آرایش الکترونی یکسانی دارند.\n\n• اکسنده این واکنش نافلزی فعال است که با تمام فلزها واکنش می‌دهد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6883, '110- با استفاده از دو عنصر X و Y که قدرمطلق پتانسیل کاهشی آنها در زیر آمده است، یک سلول گالوانی تشکیل می‌دهیم. اگر نمودار تغییرات غلظت برخی گونه‌ها به‌صورت نمودار زیر باشد، کدام گزینه می‌تواند نیروی الکتروموتوری این سلول را نشان دهد؟\n\n\n\n$X^{2+} + 2e^- \\rightarrow X \\quad |E^\\circ| = 0.25 V$\n\n$Y^{2+} + 2e^- \\rightarrow Y \\quad |E^\\circ| = 0.34 V$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6884, '111- یک سلول گالوانی استاندارد تشکیل شده از نیم‌سلول‌های روی و SHE شروع به کار می‌کند. هنگامی که pH محلول الکترولیت مربوط به SHE، به 0/4 واحد می‌رسد، چند گرم از تیغه روی کاسته می‌شود؟ (حجم محلول الکترولیت مربوط به SHE را ثابت و برابر ۳ لیتر در نظر بگیرید و فرض کنید دیواره متخلخل، فقط کاتیون‌ها را می‌تواند از خود عبور دهد.)\n\n$(Zn = 65 g \\cdot mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6885, '112- در دو آزمایش جداگانه، 0/5 لیتر محلول0/5 مولار آهن (II) سولفات با یک تیغه آلومینیمی به جرم 2 g  (آزمایش ۱) و تیغه‌ای از جنس روی به جرم  2 g (آزمایش ۲) واکنش می‌دهد. اگر بدانیم در هر دو آزمایش تیغه‌های فلزی به‌طور کامل مصرف می‌شوند، کدام موارد از مطالب زیر درست است؟ $(Al = 27, Zn = 65 : g \\cdot mol^{-1})$\n\nالف) آهنگ تغییر رنگ محلول آهن (II) سولفات در آزمایش (۱) بیشتر است.\n\nب) تغییر دمای مخلوط واکنش و نیز گرمای مبادله شده در آزمایش (۱) بیشتر است.\n\nپ) شمار الکترون‌های مبادله شده میان گونه‌های اکسنده و کاهنده در آزمایش (۱)، 1/5 برابر آزمایش (۲) است.\n\nت) جرم فلز آهن تولید شده در دو آزمایش برابر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6886, '113- کدام‌یک از موارد زیر، نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6887, '115- کدام گزینه نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6888, '117- در صورت برابر بودن شمار الکترون‌های مبادله شده بین گونه‌های اکسنده و کاهنده در ظرف‌های زیر، واکنش انجام شده در کدام ظرف شدیدتر خواهد بود و نسبت تغییر جرم تیغه‌ها در ظرف (II) به ظرف (I) به ترتیب چقدر است؟\n\n$(Fe = 56, Zn = 65, Mg = 24, Ag = 108 : g \\cdot mol^{-1})$\n\n$(E^\\circ(Mg^{2+} / Mg) = -2.37 V, E^\\circ(Zn^{2+} / Zn) = -0.76 V, E^\\circ(Fe^{2+} / Fe) = -0.44 V, E^\\circ(Ag^+ / Ag) = +0.8 V)$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6889, '118- با توجه به شکل زیر که الگویی کلی از واکنش‌های الکتروشیمیایی را نشان می‌دهد، کدام‌یک از مطالب زیر درست است؟\n\nالف: گونه‌های A و B به ترتیب می‌توانند عناصر روی و اکسیژن باشند که به ترتیب نقش کاهنده و اکسنده را دارند.\n\nب: اگر فرآیند C در نیم‌سلول یک سلول گالوانی انجام شود، جرم الکترود در آن به یقین کاهش می‌یابد.\n\nپ: فرآیندهای C و D به ترتیب مشابه با نیم‌واکنش منیزیم در دوربین عکاسی و نیم‌واکنش یون‌های مس (II) در ظرفی حاوی تیغه روی است.\n\nت: اگر شکل مقابل مربوط به سلول گالوانی «منیزیم - نقره» باشد، ذرات A و B به ترتیب اتم‌های منیزیم و نقره می‌باشند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6890, '119- کدام مورد، درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6891, '120- با توجه به شکل مقابل که مربوط به سلول گالوانی (روی - قلع) می‌باشد، کدام‌یک از مطالب داده شده درست است؟\n\n$(E^\\circ(Zn^{2+} / Zn) = -0/76 V, E^\\circ(Sn^{2+} / Sn) = -0/14 V, Zn = 65, Sn = 119 : g \\cdot mol^{-1})$\n\nالف: در این سلول، A و B به ترتیب می‌توانند $SO_4^{2-}$ و $Zn^{2+}$ باشند که از طریق دیواره متخلخل به ترتیب وارد الکترولیت کاتدی و آندی شوند.\n\nب: در این سلول، جهت حرکت الکترون در مدار خارجی (سیم) از الکترود روی به سمت الکترود قلع بوده و عددی که ولت‌سنج نمایش می‌دهد، برابر $+0/62 $ ولت است.\n\nپ: به ازای هر کاهش جرم ۱۳۰ گرمی الکترود آندی، در آند و کاتد در مجموع ۱۱۶ گرم افزایش جرم خواهیم داشت.\n\nت: به ازای افزایش جرم ۲۳۸ گرمی تیغه کاتدی، $ 2/408 \\times 10^{24}$ الکترون بین گونه‌های اکسنده و کاهنده مبادله شده است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6892, '121- تیغه‌ای به جرم ۳۹ گرم از روی با درصد خلوص $ %33/33 $ را در یک نمونه از محلول نقره نیترات وارد می‌کنیم. اگر پس از گذشت ۳۰۰ ثانیه، جرم تیغه به $ 54/1 $ گرم افزایش یافته باشد، درصد خلوص روی در تیغه جدید به تقریب کدام است و اگر واکنش با همین سرعت ادامه پیدا کند، چند دقیقه دیگر طول می‌کشد تا جرم تیغه به حداکثر میزان خودش برسد؟ (ناخالصی‌ها در واکنش شرکت نمی‌کنند، $Ag = 108, Zn = 65 : g \\cdot mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6893, '122- اگر نمودار تغییر غلظت یون‌ها در سلول گالوانی $(X-Y)$ به‌صورت مقابل باشد، کدام مورد درست است؟\n\n۱) واکنش $X + Y \\rightarrow X^{n+} + Y^{m+}$ در حال انجام است.\n\n۲) اندازه بارها با هم برابر است $(n=m)$.\n\n۳) فلز Y آند و فلز X کاتد است.\n\n۴) اگر فلز X بتواند در واکنش با محلول هیدروکلریک اسید، گاز $H_2$ تولید کند، فلز Y نیز به‌یقین می‌تواند با این اسید واکنش دهد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6894, '123- چند مورد از مطالب زیر در ارتباط با دیواره متخلخل و عوامل مؤثر بر ولتاژ سلول‌های گالوانی درست است؟\n\n$(E^\\circ_{(Zn^{2+}/Zn)} = -0/76 V, E^\\circ_{(Cu^{2+}/Cu)} = +0/34 V)$\n\n$\\bullet$ با حذف دیواره متخلخل، واکنش اکسایش - کاهش همچنان در سلول انجام می‌شود، اما ولتاژ آن قابل اندازه‌گیری نیست.\n\n$\\bullet$ با افزودن مقداری روی کلرید به سلول گالوانی $Zn-Cu$ ، ولتاژ سلول افزایش می‌یابد.\n\n$\\bullet$ در صورتیکه دیواره متخلخل برداشته شود، لامپ در مدار بیرونی روشن می‌ماند اما از شدت نور آن کاسته می‌شود.\n\n$\\bullet$ با تعویض الکترود کاتدی به الکترودی با مقدار پتانسیل کاهشی بیشتر، مقدار emf سلول افزایش می‌یابد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6895, '124- کدام مورد در رابطه با واکنش‌های اکسایش - کاهش، نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6896, '125- با توجه به وقایع ذکر شده در رابطه با سه فلز A ، B و C، کدام مورد به یقین درست است؟\n\n$(C = 137 , B = 65 : g \\cdot mol^{-1})$\n\nI) در واکنش فلز A با هیدروکلریک اسید $ 0/5 $ مولار، گاز هیدروژن آزاد می‌شود.\n\nII) با قرار دادن تیغه فلزی B در محلول $CSO_4$، دمای محلول تغییر نمی‌کند.\n\nIII) با حرکت الکترون‌ها از الکترود B به سمت الکترود SHE در سلول گالوانی متشکل از آنها، مقدار عددی emf، مثبت است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6897, '126- در سلول گالوانی استاندارد $Mg - Ag$، اگر پس از گذشت مدت زمان معین، $ 45/15 \\times 10^{22}$ الکترون از سیم رابط دو نیم‌سلول عبور کند، غلظت یون نقره باقی‌مانده در الکترولیت کاتدی سلول به چند مولار می‌رسد؟ (حجم الکترولیت کاتدی را ۱ لیتر در نظر بگیرید.)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6898, '127- کدام مورد درست است؟ $(O = 16 , H = 1 : g \\cdot mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6899, '128- چند مورد از عبارت‌های داده شده در رابطه با فرآیند انجام گرفته در شکل‌های زیر نادرست است؟\n\n$\\bullet$ این شکل‌ها نشان می‌دهند که برای خوردگی آهن، وجود آب و اکسیژن الزامی است.\n\n$\\bullet$ در شکل سمت راست، ذره‌های x و y با یون هیدروکسید به ترتیب رسوب‌های آجری و سبز رنگ تشکیل می‌دهند.\n\n$\\bullet$ در شکل سمت چپ، نیم‌واکنش آندی زیر قطره آب جایی که غلظت $O_2$ زیاد است، انجام می‌گیرد.\n\n$\\bullet$ اگر به همراه مولکول‌های $O_2$، مولکول‌های $NO_2$ نیز حضور داشته باشند، سرعت واکنش صورت گرفته کاهش می‌یابد.\n\n$\\bullet$ طی نیم‌واکنش M، یون‌هایی تولید می‌شوند که رنگ کاغذ pH را در آب به آبی تغییر می‌دهند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6900, '129- در ساختار زیر، مجموع عدد اکسایش اتم‌هایی که با ستاره مشخص شده‌اند، کدام است؟\n\n[image: structure with stars on S, the CH2 group next to S, the Nitrogen atom, and the Carbonyl carbon]', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6901, '131- با توجه به نیم‌واکنش‌های داده شده، کدام‌یک از مطالب زیر در ارتباط با سلول نور الکتروشیمیایی درست است؟\n\n$SiO_2(s) + 4H^+(aq) + 4e^- \\rightarrow Si(s) + 2H_2O(l) \\quad , \\quad E^\\circ = -0/84 V$\n\n$ 2 H_2O(l) + 2e^- \\rightarrow H_2(g) + 2OH^-(aq) \\quad , \\quad E^\\circ = -0/83 V$\n\nالف) با این که emf این سلول پایین است، اما بازده و سرعت بالا، استفاده از این سلول را توجیه می‌کند.\n\nب) به ازای تولید یک مول فرآورده جامد مطابق واکنش کلی این سلول، ۴ مول الکترون مبادله می‌شود.\n\nپ) نیم‌واکنش کاهش این سلول همانند نیم‌واکنش کاهش سلول برقکافت آب است.\n\nت) در اثر آغشته شدن کاغذ pH با محلول اطراف آند، کاغذ pH به رنگ آبی در می‌آید.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6902, '132- در اثر خراش قطعه‌ای از قوطی کنسرو تن ماهی و زنگ زدن آن در محیط اسیدی، جرم قوطی به اندازه $2/24 $ گرم کاهش می‌یابد. با در نظر گرفتن نیم‌واکنش‌های زیر در این فرآیند، چند لیتر گاز با چگالی $ 1/6 $ گرم بر لیتر مصرف شده و emf سلول تشکیل شده مابین کاتد و آند در این واکنش کدام است؟\n\n$(Sn = 119, Fe = 56, O = 16 : g \\cdot mol^{-1})$\n\n$O_2(g) + 4H^+(aq) + 4e^- \\rightarrow 2H_2O(l) \\quad E^\\circ = 1/23 V$\n\n$O_2(g) + 2H_2O(l) + 4e^- \\rightarrow 4OH^-(aq) \\quad E^\\circ = 0/4 V$\n\n$Sn^{2+}(aq) + 2e^- \\rightarrow Sn(s) \\quad E^\\circ = -0/14 V$\n\n$Fe^{2+}(aq) + 2e^- \\rightarrow Fe(s) \\quad E^\\circ = -0/44 V$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6903, '133- جواب درست دو عبارت زیر به ترتیب در کدام گزینه آمده است؟\n\nI) اتم کلر در ساختار $HClO_4$، نقش .................... را دارد.\n\nII) تیغه‌های گرافیتی در قطب .................... سلول هال، تغییر جرم می‌دهند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6904, '134- یک قاشق از جنس فلز کروم به جرم $ 8/8 $ گرم را به عنوان کاتد در یک سلول الکترولیتی که حاوی محلول $CuSO_4$ است، قرار می‌دهیم تا در فرآیند آبکاری شرکت کند. پس از مبادله $ 21/07 \\times 10^{22}$ الکترون از مدار بیرونی سلول، درصد جرمی فلز مس در قاشق پس از آبکاری چقدر می‌شود؟ $(Cr = 52 , Cu = 64 : g \\cdot mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6905, '135- با توجه به شکل زیر که مربوط به آبکاری یک قاشق فولادی با فلز نقره است، کدام‌یک از مطالب داده شده درست است؟\n\nالف) قاشق فولادی، آند سلول و تیغه نقره‌ای، کاتد سلول است.\n\nب) آنیون‌های موجود در محلول به سمت نقره حرکت می‌کنند.\n\nپ) نمونه $X^+$ می‌تواند $Ag^+(l)$ باشد.\n\nت) نمودار غلظت $X^+$ برحسب پیشرفت واکنش به‌صورت شکل داده شده است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6906, '138- چند مورد از مطالب زیر درست است؟\n\n$\\bullet$ در سلول مربوط به برقکافت سدیم کلرید مذاب، مجموع سطح انرژی مواد فرآورده کمتر از سطح انرژی واکنش‌دهنده است.\n\n$\\bullet$ در سلول مربوط به برقکافت $MgCl_۲(l)$، تنوع ایزوتوپ‌های طبیعی در ماده تولید شده در آند، کمتر از ماده تولید شده در کاتد است.\n\n$\\bullet$ پر مصرف‌ترین فلز در جهان دچار خوردگی شده و ماهانه، ۲۰ درصد از فلز تولید شده جایگزین قطعه‌های خورده شده می‌شود.\n\n$\\bullet$ ماده‌ای که در ساخت الکترود اغلب سلول‌های الکترولیتی کاربرد دارد، برای تعیین جرم اتمی سایر عناصر استفاده می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6907, '139- در واکنش موازنه نشده: $Fe_2O_3(s) + H_2(g) \\rightarrow Fe(s) + H_2O(l)$، پس از مدت زمان مشخص، مجموع جرم مواد جامد موجود در ظرف به اندازه ۱۶۸ گرم کاهش می‌یابد. اگر آب تولید شده در این فرآیند را در واکنشی با بازده ۴۰ درصد برقکافت کنیم، چند گرم فرآورده گازی در اطراف آند سلول مربوط به برقکافت، تولید می‌شود؟ $(H = 1, O = 16, Fe = 56 : g \\cdot mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6908, '140- اگر الکترون‌های مبادله شده بین گونه‌های اکسنده و کاهنده را به‌ازای مصرف 5/6 لیتر گاز $H_2$  (پس از تبدیل به شرایط STP) در سلول سوختی $H_2 - O_2$ به واکنش زیر انتقال دهیم، جرم آهن (II) سولفات مصرف شده در واکنش چند گرم است؟ $(Fe = 56 , S = 32 , O = 16 : g \\cdot mol^{-1})$\n\n(واکنش موازنه شود.) $KMnO_4 + H_2SO_4 + FeSO_4 \\rightarrow K_2SO_4 + MnSO_4 + Fe_3(SO_4)_3 + H_2O$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6909, '141- کدام مطالب زیر درباره فرآیند خوردگی آهن، حلبی و آهن گالوانیزه نادرست است؟\n\nالف) نسبت شمار آنیون به کاتیون در اولین رسوب تشکیل شده در فرآیند خوردگی آهن، برابر ۲ است.\n\nب) فلزی که به عنوان روکش در حلبی استفاده می‌شود بعد از خراش در سطح حلبی، نقش آند را خواهد داشت.\n\nپ) با قرار دادن الکترودی از جنس آهن سفید در محلول $CuSO_4$، دمای محلول افزایش می‌یابد.\n\nت) در فرآیند خوردگی آهن، به‌ازای تولید یک مول الکترون در آند، $ 0/5 $ مول آب در کاتد مصرف می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6910, '142- چهار قطعه آهنی یکسان را به صورت جداگانه در ۴ ظرف زیر وارد می‌کنیم، پس از ایجاد خراش در سطح آهن، سرعت خوردگی آن در کدام ظرف بیشتر است؟\n\n$\\bullet$ ظرف ۱) قرار دادن آهن در ۵۰۰ میلی‌لیتر محلول پروپانوئیک اسید 0/2  مولار\n\n$\\bullet$ ظرف ۲) روکش‌دار کردن آهن با فلز نقره و قرار دادن در ۵۰۰ میلی‌لیتر محلول پروپانوئیک اسید 0/2 مولار\n\n$\\bullet$ ظرف ۳) روکش‌دار کردن آهن با فلز نقره و قرار دادن آن در ۵۰۰ میلی‌لیتر محلول فورمیک اسید 0/2 مولار\n\n$\\bullet$ ظرف ۴) قرار دادن آهن در ۵۰۰ میلی‌لیتر هگزان در دما و فشار اتاق', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6911, '143- پس از موازنه واکنش‌های داده شده، مشخص کنید که در کدام واکنش نسبت ضریب گونه کاهنده به اکسنده برابر با بیشترین مقدار است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6912, '144- چند مورد از مطالب زیر در ارتباط با سلول سوختی هیدروژن-اکسیژن از نظر درستی یا نادرستی مطابق جمله زیر است؟ $(H = 1, O = 16 : g \\cdot mol^{-1})$\n\n«اکسایش هیدروژن در سلول سوختی، بازدهی نزدیک به ۶۰ درصد دارد.»\n\n$\\bullet$ جهت حرکت یون‌های هیدرونیوم در غشای مبادله کننده یون هیدرونیوم همانند جهت حرکت الکترون‌ها در مدار بیرونی از آند به کاتد است.\n\n$\\bullet$ در شرایط یکسان، نسبت چگالی گونه کاهنده به اکسنده در این سلول برابر با $\\frac{1}{16}$ است.\n\n$\\bullet$ نیروی بین مولکولی در بین ذرات گاز خارج شده از کاتد سلول، شبیه به نیروی بین مولکول‌های متانول است.\n\n$\\bullet$ این سلول می‌تواند ردپای کربن دی‌اکسید را کاهش دهد و برخلاف باتری‌ها انرژی شیمیایی را در خود ذخیره نمی‌کند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6913, '145- با توجه به فرمول $X(NH_4)_2XMnO_4$، X کدام عنصر می‌تواند باشد؟ ($Mo$ در جدول تناوبی در پایین عنصر کروم قرار داشته و در این ترکیب، دارای حداکثر عدد اکسایش ممکن است.)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6914, '146- مقدار قدر مطلق پتانسیل کاهشی استاندارد سه عنصر X، Y و Cu به صورت زیر است:\n\n$Y^{3+} + 3 e^- \\rightarrow Y : E^0 = 1/18 V , X^{2+} + 2 e^- \\rightarrow X : E^۰ = 0/14 V , Cu^{2+} + 2e^- \\rightarrow Cu : E^0 = 0/34 V$\n\nاگر نیم‌سلول Y را به نیم‌سلول هیدروژن متصل کنیم، pH محلول الکترولیت در نیم‌سلول هیدروژن افزایش می‌یابد و با اتصال دو نیم‌سلول X و مس، حرکت الکترون‌ها از نیم‌سلول X به مس است. بر این اساس، کدام‌یک از مطالب زیر درست است؟\n\nالف) با اتصال نیم‌سلول X و SHE، مقدار pH محلول الکترولیت در SHE، کاهش می‌یابد.\n\nب) با اتصال دو نیم‌سلول Y و مس، $Y^{3+}$ با گذر از دیواره متخلخل به سمت نیم‌سلول مس حرکت می‌کند.\n\nپ) ترتیب قدرت اکسندگی گونه‌ها به صورت $Y^{3+} > X^{2+} > Cu^{2+}$ است.\n\nت) مقدار نیروی الکتروموتوری سلول گالوانی متشکل از X و Y برابر با 1/32 ولت است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6915, '147- کدام‌یک از موارد زیر درباره فرآیند خوردگی آهن درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6916, '148- چند مورد از عبارت‌های زیر درست است؟\n\n$\\bullet$ عنصری که ۸ الکترون در زیرلایه p اتم خود دارد.\n\n$\\bullet$ یکی از عناصر اصلی در ساخت چراغ‌های خورشیدی است.\n\n$\\bullet$ در هسته اتم پایدارترین ایزوتوپ عنصری که کمترین $E^0$ را در میان فلزها دارد، ۴ نوترون موجود است.\n\n$\\bullet$ مجموع عدد اکسایش اتم‌های کربن ستاره‌دار در مولکول مقابل برابر با صفر است.\n\n$\\bullet$ بر اثر خراش در سطح حلبی، فلز واسطه اکسید شده و الکترون از دست می‌دهد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6917, '149- در ارتباط با فرآیند آبکاری فلز Y به وسیله فلز X، کدام‌یک از مطالب زیر نادرست است؟\n\nالف: فلز X در آند (قطب منفی) اکسایش یافته و کاتیون‌های آن روی جسم Y (قطب مثبت) می‌نشیند.\n\nب: معادله کلی واکنش به صورت $X_{(s,آند} \\rightarrow X_{(s, کاتد )}$  است.\n\nپ: در سلول مربوط به این فرآیند، نیم‌واکنش اکسایش همانند نیم‌واکنش کاهش، مربوط به فلز X است.\n\nت: فرآیند انجام شده در آبکاری، خودبه‌خودی بوده و با کمک یک ولتاژ خارجی انجام می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6918, '۱۵۰-  مخلوطی از آهن (II) کلرید و منگنز (II) فلوئورید مذاب را در یک سلول الکترولیتی وارد می‌کنیم. نسبت جرم محصول تولید شده در آند به جرم محصول تولید شده در کاتد این سلول به تقریب چند گرم است؟\n\n$(Fe = 56, Mn = 55, Cl = 35/5, F = 19 : g \\cdot mol^{-1})$\n\n$(E^\\circ(F_2/F^-) = +2/87V, E^\\circ(Cl_2/Cl^-) = +1/36V, E^\\circ(Mn^{2+}/Mn) = -1/18V, E^\\circ(Fe^{2+}/Fe) = -0/44V)$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6919, '۱۵۱ - آلیاژی از جنس فلزهای $A$ و $B$ را به درون محلولی با مقدار کافی از $C^{2+}$ وارد می‌کنیم. اگر با گذشت زمان شمار اتم‌های فلزی به کار رفته در ساختار تیغه افزایش یابد و قدرت کاهندگی یکی از دو فلز $A$ و $B$ از فلز $C$ بیشتر باشد، کدام مورد نادرست است؟ (فلزهای $A$ و $B$ در ترکیب‌های یونی تنها به شکل $A^+$ و $B^{3+}$ دیده می‌شوند و تمام فلز تولید شده بر روی سطح تیغه می‌نشینند.)\n\n۱) اگر قدرت کاهندگی فلز $Fe$ از فلز $A$ کمتر باشد، واکنش $C(s) + FeSO_4(aq) \\rightarrow$ به‌طور طبیعی انجام می‌شود.\n\n۲) مجموع ضرایب استوکیومتری فرآورده‌ها و واکنش‌دهنده‌ها در واکنش انجام شده برابر است.\n\n۳) با پیشرفت واکنش انجام شده به میزان ۵۰٪، به ازای ضرایب، $ 12/04 \\times 10^{23}$ الکترون بین گونه کاهنده و اکسنده مبادله می‌شود.\n\n۴) واکنش: $ 3 A(s) + B^{3+}(aq) \\rightarrow B(s) + 3A^+(aq)$ می‌تواند در یک سلول گالوانی انجام شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6920, '۱۵۲ - تیغه‌ای از جنس فلز نقره را به ظرف حاوی مقدار کافی از محلول $AuCl_3$ وارد می‌کنیم. چند مورد از مطالب زیر در این رابطه درست است؟ $(Ag = 108 g \\cdot mol^{-1})$\n\n• قبل از شروع واکنش، از محتویات موجود در ظرف می‌توان به عنوان نیم‌سلول نقره در سلول گالوانی نقره - طلا استفاده کرد.\n\n• رسانایی الکتریکی محلول با گذشت زمان کاهش می‌یابد و فرآورده‌های تولید شده در واکنش به حالت جامد دیده می‌شوند.\n\n• اگر دمای اولیه محلول برابر $\\theta$ باشد، دمای نهایی محلول پس از انجام واکنش می‌تواند برابر $\\theta + 10$ باشد.\n\n• هنگامی که ۸۱۰ گرم فلز نقره مصرف شود، از شمار یون‌های موجود در محلول به میزان $ 1/505 \\times 10^{24}$ واحد کم می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6921, '۱۵۳ - با توجه به اطلاعات جدول مقابل در مورد میزان گازهای وارد شده و خارج شده از یک سلول سوختی $H_2 - O_2$، $x$ بر حسب گرم کدام است؟ $(O = 16, H = 1 : g \\cdot mol^{-1})$\n\n| نوع گاز | مقدار گاز (بر حسب گرم) |\n\n| :--- | :--- |\n\n| آند (گاز ورودی به آند) | $m$ |\n\n| آند (گاز خروجی از آند) | $\\frac{m}{2}$ |\n\n| کاتد (گاز ورودی به کاتد) | $x$ |\n\n| کاتد (گاز خروجی از کاتد) | $ 5 m$ |', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6922, '155- با توجه به ساختار نشان داده شده، کدام گزینه درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6923, '156- با توجه به معادله موازنه نشده زیر، کدام گزینه نادرست است؟\n\n$S_2O_5^{2-} + MnO_4^- + H^+ \\rightarrow S_2O_3^{2-} + Mn^{2+} + H_2O$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6924, '157- ۵۰ گرم آلیاژی از نقره و روی را در محلولی از هیدروکلریک اسید می‌اندازیم. در شرایطی که چگالی گاز حاصل از واکنش $ 0/12 g.L^{-1}$ است، 4/5 لیتر گاز آزاد می‌شود. درصد جرمی نقره در این آلیاژ به تقریب برابر چند است؟\n\n$(E^\\circ \\frac{Zn^{2+}}{Zn} = -0/76 V, E^\\circ \\frac{Ag^+}{Ag} = +0/8 V)$\n\n$(Ag = 108, Zn = 65, H = 1g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6925, '158- با توجه به واکنش زیر که به‌طور طبیعی انجام می‌شود، کدام گزینه عبارت زیر را به درستی تکمیل می‌کند؟\n\n$Cu + HNO_3 \\rightarrow Cu(NO_3)_2 + NO + H_2O$\n\nدر این واکنش فلز مس با از دست دادن الکترون دچار ................. شده و لذا یک ................. است. همچنین از هر ۸ یون نیترات در واکنش دهنده، ................. آن دچار ................. شده و لذا ................. است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6926, '159- با توجه به معادله زیر که به‌طور طبیعی انجام می‌گیرد، چند اشتباه در عبارات پس از آن یافت می‌شود؟\n\n$Al(s) + CuSO_4(aq) \\rightarrow Al_2(SO_4)_3 (aq) + Cu(s) \\quad  و  \\quad \\Delta H < 0$ \n\nدر این واکنش فلز آلومینیوم کاهنده‌تر از مس است. از آن‌جا که $\\Delta H < 0$ است، پس واکنش گرماده بوده و دمای مخلوط واکنش افزایش می‌یابد.\n\nبا انجام واکنش در یک سلول گالوانی می‌توان کاری کرد که گرمای آزاد شده در واکنش به انرژی الکتریکی تبدیل شود. همچنین از انجام این واکنش می‌توان نتیجه گرفت که فلزات اصلی، کاهندگی بیشتری از فلزات واسطه دارند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6927, '160- در واکنش تیغه روی با محلولی از نقره نیترات، اگر در پایان واکنش 2/15  گرم بر جرم تیغه افزوده شده باشد، چند الکترون در این فرآیند مبادله شده است؟ (۵۰٪ اتم‌های نقره تولید شده به فلز روی می‌چسبند.)\n\n$(Zn = 65 g.mol^{-1} \\quad و \\quad Ag = 108 g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6928, '161- با توجه به سلول گالوانی روی - مس، کدام عبارت‌ها درست است؟\n\nالف) مانند همه سلول‌های گالوانی دیگر، جرم آند در آن کاهش و جرم کاتد افزایش می‌یابد.\n\nب) جهت حرکت الکترون‌ها از آند به کاتد است.\n\nپ) در محلول پیرامون آند، غلظت کاتیون از آنیون بیشتر می‌شود.\n\nت) مانند همه سلول‌های گالوانی دیگر، emf سلول عددی بزرگ‌تر از صفر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6929, '162- درباره سلول گالوانی هیدروژن - مس چند مورد درست است؟ ($E^\\circ(\\frac{Cu^{2+}}{Cu}) = +0/34 V$)\n\nالف) با گذشت زمان، pH محلول آندی کاهش می‌یابد.\n\nب) در معادله موازنه شده واکنش سلول به‌ازای مصرف هر مول فلز مس، ۲ مول الکترون مبادله می‌شود.\n\nپ) با گذشت زمان، pH محلول کاتدی کاهش می‌یابد.\n\nت) از انجام این واکنش متوجه می‌شویم که فلز مس با محلول اسیدهای مختلف واکنش نمی‌دهد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6930, '163- کدام مورد از عبارت‌های زیر در رابطه با برقکافت آب نادرست است؟\n\nالف) در برقکافت آب محیط اطراف الکترود A اسیدی و محیط اطراف الکترود B بازی است.\n\nب) با توجه به شکل گاز تولید شده در A و B به ترتیب $H_2$ و $O_2$ می‌تواند باشد.\n\nپ) C و D قطب‌های + و - باطری هستند.\n\nت) جهت حرکت الکترون‌ها از الکترود A به B است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6931, '164- با توجه به $E^\\circ$ های داده شده، کدام‌یک از واکنش‌های زیر به‌صورت طبیعی انجام می‌شود؟\n\n$E^\\circ(\\frac{Sn^{4+}}{Sn^{2+}}) = +0/15 V$ و $E^\\circ(\\frac{Sn^{2+}}{Sn}) = -0/14 V$ و $E^\\circ(\\frac{Cr^{3+}}{Cr^{2+}}) = -0/427 V$ و $E^\\circ(\\frac{Cu^{2+}}{Cu}) = +0/34 V$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6932, '165- میزان تغییر عدد اکسایش در کدام مورد زیر با تغییر عدد اکسایش کربن هنگام سوختن ناقص متان برابر است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6933, '168- درباره فرآیند خوردگی آهن کدام مورد درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6934, '169- اگر از الکترون‌های مبادله شده در سلول سوختی متان، برای استخراج فلز آلومینیم در فرآیند هال استفاده شود، از اکسایش چند تن متان با بازدهی ۶۰٪، می‌توان 5/4 تن فلز آلومینیم استخراج کرد؟ ($C=12, H=1, Al=27 g.mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6935, '170- کدام گزینه جاهای خالی را در عبارت زیر به درستی کامل می‌کند؟\n\nباتری‌های روی نقره از جمله باتری‌های .................... هستند که در آنها فلز روی نقش .................... و فلز نقره نقش .................... را دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6936, '171- در مورد سلول نور الکتروشیمیایی کدام مورد صحیح است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:23', 1, NULL, NULL, 'free'),
(6937, '172- چند مورد از موارد زیر، درباره سلول گالوانی استاندارد «$Li - Ag$» درست است؟ ($Li = 7, Ag = 108 g.mol^{-1}$)\n\nالف) جرم تیغه $Li$ برخلاف $Ag$، کاهش می‌یابد.\n\nب) اگر جرم اولیه الکترودها برابر باشد، با عبور $ 12/04\\times 10^{21}$ الکترون از مدار خارجی، اختلاف جرم دو تیغه برابر $ 2/3 g$ می‌شود.\n\nپ) جهت حرکت الکترون‌ها در مدار خارجی برخلاف جهت حرکت یون $Ag^{+}$ از دیواره متخلخل است.\n\nت) چگالی فلز موجود در کاتد از فلز موجود در آند کمتر است.\n\nث) نمودار غلظت کاتیون برحسب زمان در محلول آند و کاتد، قرینه یکدیگر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6938, '174- با توجه به ساختار بنداموستین که به عنوان داروی شیمی درمانی به کار می‌رود، کدام مورد نادرست است؟\n\n$CH_3$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6939, '175- اگر از $C_8H_{18}$ به جای $H_2$ در سلول سوختی استفاده شود و نیم‌واکنش موازنه نشده اکسایش به‌صورت زیر باشد، تعداد الکترون حاصل از اکسایش ۴ گرم گاز $H_2$ را از چند گرم $C_8H_{18}$ می‌توان تهیه کرد؟ ($C=12, H=1 g.mol^{-1}$)\n\n$C_8H_{18} + H_2O \\rightarrow CO_1 + H^+ + e^-$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6940, '176- در رابطه با سلول آبکاری کدام مورد صحیح است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6941, '177- در اثر خراش قطعه‌ای حلبی، در محیط مرطوب، با مصرف 26/88 لیتر گاز اکسیژن در شرایط STP، از کدام فلز و چند گرم خورده می‌شود؟\n\n($Fe=56 g.mol^{-1} , Sn=119 g.mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6942, '178- در کدام گزینه کربنی وجود دارد که فقط نقش اکسنده دارد؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6943, '179- از برقکافت 1/8 گرم آب در سلول برقکافت، pH محلول اطراف کاتد چند درصد و چگونه تغییر می‌کند؟ (حجم اطراف کاتد را ۱۰۰ ml در نظر بگیرید.) ($H_2O=18 g.mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6944, '180- مجموع ضرایب معادله زیر پس از موازنه کدام است و در این واکنش چند مول الکترون مبادله شده است؟\n\n$Pb_3O_4 + HNO_3 \\rightarrow Pb(NO_3)_2 + PbO_2 + H_2O$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6945, '181- کدام مورد در رابطه با فرآیند هال نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6946, '182- اگر در سلول گالوانی استاندارد تشکیل شده از فلز M و فلز نقره به ازای مصرف 5/4 گرم فلز M، $ 3/612 \\times 10^{22}$ الکترون مبادله شود، مجموع ضرایب معادله واکنش فلز با یون نقره کدام است؟ (جرم مولی فلز M برابر مجموع اعداد کوانتومی اصلی و فرعی الکترون‌های دومین فلز قلیایی است)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6947, '183- کدام مطلب در مورد عدد اکسایش اتم‌ها درست است؟\n\nا) تفاوت بالاترین و پایین‌ترین عدد اکسایش اتم اکسیژن در ترکیب‌ها برابر ۴ است.\n\nب) عدد اکسایش اتم فسفر در $Na_4P_2O_7$ با عدد اکسایش یکی از اتم‌های نیتروژن در آمونیوم‌نیترات برابر است.\n\nپ) مجموع عدد اکسایش اتم‌های کربن در بنزوئیک‌اسید با عدد اکسایش اتم کربن در ترکیب $CaC_2$ برابر است.\n\nت) پایین‌ترین عدد اکسایش تمام فلزها برابر صفر و بالاترین عدد اکسایش آن‌ها برابر با شمار الکترون‌های ظرفیتی اتم آن‌هاست.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6948, '184- در سلول گالوانی تشکیل شده از دو نیم‌سلول A و M، جرم الکترود در نیم‌سلول A ثابت است ولی از جرم الکترود در نیم‌سلول M کاسته می‌شود. بر این اساس کدام مطلب درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6949, '185- برای استخراج هر کیلوگرم منیزیم از یک مترمکعب از آب دریا به تقریب به چند لیتر محلول سود سوزآور با $pH=12/7$ نیاز است و به ازای تولید این مقدار منیزیم، به تقریب چند لیتر گاز کلر در شرایط استاندارد به دست می‌آید؟ ($Mg = 24 g.mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6950, '186- درباره واکنش زیر پس از موازنه چند مورد از مطالب بیان شده درست است؟\n\n$MnO_4^{-}(aq) + C_2O_4^{2-}(aq) + H^{+}(aq) \\rightarrow Mn^{2+}(aq) + CO_2(g) + H_2O(l)$\n\nا) به ازای مصرف هر مول گونه اکسنده، ۵ مول گونه کاهنده مصرف می‌شود.\n\nب) مجموع ضرایب استوکیومتری برای مواد واکنش‌دهنده و فرآورده برابر است.\n\nپ) تفاوت ضریب استوکیومتری گونه کاهنده و $CO_2(g)$ با تغییر عدد اکسایش گونه اکسنده برابر است.\n\nت) در ساختار لوویس یون کاهنده، همه اتم‌ها به آرایش هشت‌تایی رسیده‌اند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6951, ' اگر در یک ورقه حلبی خراشیده شده که در معرض هوا و رطوبت قرار گرفته است، $ 3/84 \\times 10^5$ کولن بار الکتریکی میان فلز و گاز اکسیژن مبادله شود، به تقریب چند گرم رسوب براساس معادله کلی واکنش تشکیل می‌شود؟ (بار الکتریکی هر الکترون برابر $ 1/6 \\times 10^{-19}$ کولن است.)\n\n($H = 1, O = 16, Fe = 56, Sn = 119 : g.mol^{-1}$)', 3, 3, 73, 304, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, '2026-03-28 11:06:38', 5, 'done'),
(6952, '188- با توجه به شکل کدام نتیجه‌گیری نادرست است؟\n\n$Cu^{2+}(aq) + 2e^- \\rightarrow Cu(s) \\quad E^\\circ = +0/34 V$\n\n$O_2(g) + 4H^+(aq) + 4e^- \\rightarrow 2H_2O(l) \\quad E^\\circ = +1/23 V$\n\n$ 2 H_2O(l) + 2e^- \\rightarrow 2OH^- + H_2(g) \\quad E^\\circ = -0/83 V$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:24', 1, NULL, NULL, 'free'),
(6953, '۱ - در نمونه‌ای خاک، درصد جرمی آب و آهن ($III$) اکسید به ترتیب برابر با ۲۰ و ۳۰ درصد است، به طوری که با تبخیر ۴۰۰ گرم از آب موجود در آن، درصد جرمی فلز آهن، به اندازهٔ ۴/۲ درصد تغییر می‌کند. برای مصرف کامل آهن ($III$) اکسید موجود در مخلوط نهایی در واکنش ترمیت، به چند گرم فلز آلومینیم نیاز داریم؟ (واکنش موازنه شود) $Fe_2O_3(s) + Al(s) \\rightarrow Al_2O_3(s) + Fe(l)$ $(O = 16 , Al = 27 , Fe = 56 : g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6954, '۲ - نمونه‌ای از سولفات مس آبدار $(CuSO_4.xH_2O)$ دارای ۲۵/۶ درصد جرمی مس، ۱۲/۸ درصد جرمی گوگرد و ۵۷/۶ درصد جرمی اکسیژن است. این نمونه را حرارت می‌دهیم تا تمام آب موجود در ساختار خود را از دست بدهد. جرم نمونه پس از حرارت‌دادن، به چند درصد جرم نمونهٔ اولیه می‌رسد؟ $(H = 1 , O = 16 , S = 32 , Cu = 64 : g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6955, '۳ - چند مورد از مطالب زیر در ارتباط با شکل‌های داده‌شده که آلوتروپ‌های مختلف از فراوان‌ترین و اصلی‌ترین عنصر موجود در نفت خام را نشان می‌دهند، نادرست است؟ - در دمایی که یک نمونه از مادهٔ B شروع به ذوب‌شدن می‌کند، یک نمونه $H_2O$ به حالت بخار یافت می‌شود. - مادهٔ A نوعی رسانای الکترونی بوده و قدرت پیوندهای کربن - کربن در آن بیشتر از مادهٔ B است. - در ساختار مادهٔ A، هر اتم کربن با ۳ اتم کربن دیگر و در ساختار مادهٔ B، هر اتم کربن با ۴ اتم کربن دیگر پیوند برقرار می‌کند. - مادهٔ B ناپایدارتر از مادهٔ A بوده و در حجم یکسان، شمار اتم‌های کربن بیشتری در مقایسه با مادهٔ A دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6956, '۴ - با توجه به شعاع‌های اتمی داده‌شده، ضخامت گرافن در حدود چند $pm$ می‌تواند باشد؟ | $Si$ | $B$ | $N$ | $O$ | اتم | | ۱۱۸ | ۸۵ | ۷۵ | ۷۳ | شعاع اتمی ($pm$) |', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6957, '۵ - کدام‌یک از مطالب زیر دربارهٔ گرافن درست است؟ الف) شمار پیوندهای کووالانسی در یک گرم از دو مادهٔ گرافن و گرافیت با هم برابر است. ب) شمار جفت‌الکترون‌های پیوندی پیرامون هر اتم کربن در گرافن، کمتر از الماس است. پ) گرافن همانند گرافیت، جامدی کووالانسی با چینش دوبعدی اتم‌هاست و همانند آن سطحی کدر داشته و رسانای جریان الکتریکی است. ت) گرافن، تک‌لایه‌ای از گرافیت است که در آن هر اتم کربن بین سه حلقهٔ شش‌گوشه، مشترک است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6958, '۶ - کدام گزینه، تنها شامل موادی است که می‌توان برای توصیف آن‌ها از واژه‌های «مادهٔ مولکولی»، «فرمول مولکولی» و «نیروهای بین مولکولی» استفاده کرد؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6959, '۷ - اگر شمار اتم‌های کلر در دو نمونهٔ جامد، اولی شامل مخلوطی از $KClO_3$ و $KCl$ با نسبت مولی ۳ به ۲ و دومی شامل $Ca(ClO_3)_2$ خالص، برابر باشد، نسبت جرم نمونهٔ اول به نمونهٔ دوم به تقریب کدام است؟ $(O = 16 , Cl = 35/5 , K = 39 , Ca = 40 : g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6960, '۸ - چند مورد از مطالب زیر درست است؟ - اگر در سیلیس، اتم‌های $Si$ را با اتم‌های $C$ جایگزین کنیم، پیوندهای کووالانسی ضعیف‌تر شده و نقطهٔ ذوب و جوش نیز کاهش می‌یابد. - در هر مول از سیلیس همانند کربن دی‌اکسید، چهار مول جفت‌الکترون پیوندی وجود دارد. - سیلیسیم کاربید، که به عنوان یک سایندهٔ ارزان در تهیهٔ سنباده کاربرد دارد، مانند عنصرهای سازندهٔ خود در حالت خالص، جزء جامدهای کووالانسی است. - شمار اتم‌های اکسیژن در ساختار هر واحد یون سیلیکات، برابر با عدد اکسایش اتم مرکزی در این آنیون است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6961, '۹ - درستی یا نادرستی کدام گزینه در ارتباط با یخ و یخ خشک، با سایر گزینه‌ها متفاوت است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6962, '۱۰ - کدام مطلب، نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6963, '۱۱ - ۱۰ گرم از یک آلیاژ فلزی حاوی عناصر روی، قلع، سرب و مقداری ناخالصی، در واکنش با نیتریک اسید غلیظ به طور کامل حل شده و نیترات‌های فلزی مربوطه را تولید می‌کند. پس از انجام واکنش و خشک‌کردن محلول حاصل، ۳/۱۵ گرم روی نیترات، ۷/۳۴ گرم قلع (IV) نیترات و ۹/۹۳ گرم سرب (II) نیترات به دست می‌آید. درصد جرمی ناخالصی به تقریب کدام است؟ ($Pb = 207 , Sn = 119 , Zn = 65 , O = 16 , N = 14 : g.mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6964, '۱۲ - اگر فرمول شیمیایی پتاسیم تتراتیونات به‌صورت $K_2S_4O_x$ باشد، در واحد فرمولی آلومینیم تتراتیونات، چند اتم اکسیژن وجود داشته و درصد جرمی گوگرد در آن به تقریب چه‌قدر است؟ ($S = 32 , Al = 27 , O = 16 : g.mol^{-1}$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6965, '۱۳ - $A$ و $D$ دو نافلز از دوره سوم جدول تناوبی هستند. اگر در مولکول $ACl_3$، همه اتم‌ها از آرایش هشت‌تایی پیروی کنند و اسید اکسیژن‌دار $D$ یک اسید قوی غیرتک‌پروتون‌دار باشد، چند مورد از مطالب زیر درست است؟ - در مولکول $AOF_3$، اتم $A$ فاقد الکترون ناپیوندی و دارای بار جزئی مثبت است. - اکسیدهای اتم $D$، همگی مولکول‌های ناقطبی هستند. - در نقشه پتانسیل الکتروستاتیکی $AH_3$، اتم $A$ به رنگ آبی نمایش داده می‌شود. - رنگ اتم مرکزی در ترکیب $DBr_2$ با رنگ اتم مرکزی در ترکیب $A_4O_{10}$ در نقشه پتانسیل الکتروستاتیکی، می‌تواند یکسان باشد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6966, '۱۴ - براساس اطلاعات زیر، کدام موارد از مطالب زیر درست است؟ - اتم $X$ دارای ۱۴ الکترون با $n+l=5$ و عنصری اصلی است. - اتم $Y$ در ترکیب یونی $LiY$، بیشترین آنتالپی فروپاشی در میان هالیدهای لیتیم را دارد. - اتم $Z$ در ترکیب‌های $ZY_2$ و $K_2Z$ دارای عدد اکسایش ۲+ و ۲- است و این اعداد، بیشینه و کمینه اعداد اکسایش این عنصر هستند. الف) در ترکیب $XY_2$، روی اتم مرکزی یک جفت‌الکترون ناپیوندی وجود دارد و به همین دلیل ترکیبی قطبی است. ب) ترکیب $Z$ با هیدروژن می‌تواند به‌گونه‌ای باشد که در آن دو اتم $Z$ با بار جزئی $\\delta-$ به هم متصل باشند. پ) آنتالپی فروپاشی شبکه ترکیب یونی حاصل از $Mg$ و $X$، بیشتر از ترکیب یونی حاصل از $Mg$ و $Z$ است. ت) در ترکیب‌های مولکولی دارای اتم $Y$، این اتم در نقشه پتانسیل الکتروستاتیکی به رنگ قرمز دیده می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6967, '۱۵ - کدام مورد درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6968, '۱۶ - براساس شکل‌های زیر که مربوط به مدل فضاپرکن چند ترکیب است، چند مورد از موارد زیر درست است؟ الف) ب) پ) ت) - در ترکیب (الف)، دو اتم مرکزی می‌توانند با پیوند سه‌گانه به یکدیگر متصل باشند و این مدل مربوط به یک ترکیب آلی ناقطبی باشد. - اگر اتم‌های کناری در ترکیب (ب) هیدروژن باشند، بار جزئی اتم مرکزی منفی خواهد بود. - ترکیب (پ) می‌تواند مربوط به یکی از ترکیب‌های اکسیژن دی‌فلوئورید یا آب باشد. - اگر در ترکیب (ت) دو نافلز از گروه ۱۶، اتم‌های کناری باشند و همه اتم‌ها از آرایش هشت‌تایی پیروی کنند، نافلز با کوچک‌ترین شعاع اتمی در نقشه پتانسیل الکتروستاتیکی، دارای رنگ قرمز خواهد بود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6969, '۱۷ - چند مورد از مطالب زیر درست است؟ - مس یک جامد فلزی است و جاذبه‌های موجود در بلور آن از جاذبه یون‌ها در بلور سدیم کلرید، قوی‌تر است. - اکسیژن نسبت به نیتروژن، نقطه جوش بالاتر و نقطه ذوب کم‌تری دارد. - هیدروژن فلوئورید در مقایسه با هیدروژن کلرید، در گستره دمایی بیشتری به حالت مایع است. - آب در مقایسه با هیدروژن فلوئورید، نقطه جوش بالاتری دارد و در گستره دمایی بیشتری به حالت مایع است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6970, '۱۸ - چه تعداد از مقایسه‌های زیر درست است؟ - شعاع: $Na^+ < Cl < Na < Cl^-$ - شعاع: $P^{3-} > S^{2-} > Cl^- > K^+ > Ca^{2+}$ - چگالی بار: $Mg^{2+} > Ca^{2+} > K^+ > Li^+$ - چگالی بار: $O^{2-} > S^{2-} > K^+$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6971, '۱۹ - براساس عناصر موجود در جدول زیر، کدام مورد نادرست است؟ (نماد عنصرها فرضی است.) ۱ ۲ ۱۳ ۱۴ ۱۵ ۱۶ ۱۷ ۱۸ ۱ ۲ B I J L ۳ D E M Q ۴ G Z', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6972, '۲۰ - کدام روند در مورد آنتالپی فروپاشی شبکه بلور ترکیب‌های داده‌شده، درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6973, '۲۱ - در کدام گزینه، نمودار رسم‌شده نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6974, '۲۲ - در واکنش موازنه نشدهٔ زیر: $V^{n+}(aq) + Zn(s) \\rightarrow V^{m+}(aq) + Zn^{2+}(aq)$ اگر ۱۰۰ میلی‌لیتر محلول ۰/۲ مولار وانادیم، با ۱/۳ گرم فلز روی واکنش دهد، چه تعداد از موارد زیر می‌تواند درست باشد؟ ($Zn = 65 : g.mol^{-1}$) - اختلاف n و m، برابر با ۲ است. - رنگ محلول می‌تواند از آبی به بنفش تغییر کند. - اگر محلول پایانی سبزرنگ باشد، عدد اکسایش وانادیم در $VO_2^+$ با n برابر است. - محلول پایانی ممکن است آبی‌رنگ باشد. - $V^{m+}$ می‌تواند آرایش الکترونی یک گاز نجیب را داشته باشد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6975, '۲۳ - کدام موارد از مطالب زیر دربارهٔ فلزی که در دورهٔ ۴ و گروه ۴ جدول تناوبی قرار دارد، درست است؟ الف) نسبت به فولاد، مقاومت گرمایی بالاتر و چگالی کم‌تری دارد. ب) برای تهیهٔ آن می‌توان از واکنش $TiCl_4$ با فلز منیزیم در حضور گاز اکسیژن یا نیتروژن استفاده کرد. پ) آلیاژ آن با فلزی که مجموع اعداد کوانتومی الکترون‌های لایهٔ ظرفیت آن برابر با ۴۸ است، به آلیاژ هوشمند معروف است. ت) سازه‌های فلزی در ارتودنسی نمونه‌ای از کاربرد این فلز به صورت ترکیب یونی است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6976, '۲۴ - اگر اتم‌های X و Y در ساختارهای زیر، بالاترین عدد اکسایش خود را داشته باشند، اعداد موجود در کدام گزینه را به ترتیب می‌توان به اعداد اتمی عنصر X و Y نسبت داد؟ (همهٔ اتم‌ها از قاعدهٔ هشت‌تایی پیروی می‌کنند.) $\\left[ O-\\overset{\\overset{O}{|}}{\\underset{\\underset{O}{|}}{X}}-O-\\overset{\\overset{O}{|}}{\\underset{\\underset{O}{|}}{X}}-O \\right]^{2-}$ و $\\left[ O-\\overset{\\overset{O}{||}}{Y}-\\overset{\\overset{O}{||}}{Y}-O \\right]^{2-}$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6977, '۲۵ - جدول زیر، درصد جرمی مواد سازندهٔ نوعی خاک رس را نشان می‌دهد. اگر درصد جرمی سیلیس، پس از پخت سفالینهٔ تهیه‌شده از این نمونه خاک رس، ۱۰ درصد افزایش یابد، درصد جرمی سدیم موجود در این خاک رس چند درصد خواهد شد؟ $(Na = 23 , O = 16 : g.mol^{-1})$ | ناخالصی‌های دیگر | $Na_2O$ | $Fe_2O_3$ | $H_2O$ | $Al_2O_3$ | $SiO_2$ | ماده | | ۰/۷ | ۶/۲ | ۲۳/۱ | ۲۵ | ۵ | ۴۰ | درصد جرمی |', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6978, '۲۶ - چند مورد از مطالب زیر، نادرست است؟ - اگر شمار اتم‌های کربن در یک نمونهٔ الماس و گرافیت با یکدیگر برابر باشد، حجم نمونهٔ گرافیتی بیشتر از الماس خواهد بود. - در ساختار یخ خشک، هر اتم اکسیژن به دو اتم هیدروژن با پیوند اشتراکی و به دو اتم هیدروژن با پیوند هیدروژنی متصل است. - کوارتز از جمله نمونه‌های خالص سیلیس به شمار می‌رود و در ساختار آن، هر اتم عنصر شبه‌فلزی به دو اتم عنصر نافلزی متصل است. - در مولکول‌های خطی سه‌اتمی، هستهٔ اتم‌ها بر روی یک خط راست قرار دارد و این مولکول‌ها در میدان الکتریکی جهت‌گیری نمی‌کنند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6979, '۲۷ - کدام موارد از مطالب زیر، درست است؟ الف) شکل زیر می‌تواند مربوط به مدل فضاپرکن نیتروژن تری‌فلوئورید باشد و علامت بار جزئی اتم مرکزی در آن با مولکول آمونیاک، متفاوت است. ب) توزیع الکترون‌ها در ساختار دی‌متیل اتر، برخلاف پروپان، نامتقارن و غیریکنواخت است و هر دو ماده در دما و فشار اتاق، مایع هستند. پ) حضور جفت‌الکترون‌های ناپیوندی روی اتم‌های اطراف در مولکول‌های چنداتمی، توزیع یکنواخت بارهای الکتریکی را به هم می‌زند. ت) در مولکول گوگرد تری‌اکسید همانند مولکول نیتروژن دی‌اکسید، اتم مرکزی دارای بار جزئی مثبت است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6980, '۲۸ - با توجه به نمودار زیر که نقطه‌های ذوب و جوش چند ماده و گسترهٔ دمایی مایع‌بودن آن‌ها را در فشار یک اتمسفر نشان می‌دهد، کدام مطلب نادرست است؟ دما ($^\\circ C$) ۲۵۰۰ : نقطهٔ جوش C ۱۰۸۳ : نقطهٔ ذوب C ۱۰۰ : نقطهٔ جوش B ۰ : نقطهٔ ذوب B -۱۸۳ : نقطهٔ جوش A -۲۱۸ : نقطهٔ ذوب A', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6981, '۲۹ - کدام موارد زیر، در مورد پرتوهای خورشیدی و استفاده از این پرتوها برای تولید برق به کمک شاره‌ها، درست است؟ الف) شارهٔ بسیار داغ، قبل از تبادل گرمایی با شارهٔ مولکولی، وارد منبع ذخیرهٔ انرژی الکتریکی می‌شود. ب) دمای شاره‌ای که گسترهٔ دمایی مایع کم‌تری دارد، در سردکننده تا نقطهٔ ذوب پایین می‌آید. پ) در این فرایند، تغییر شیمیایی وجود ندارد و به کمک خورشید که بزرگ‌ترین منبع انرژی برای زمین است، حتی در روزهای ابری و شب‌هنگام نیز، برق تولید می‌شود. ت) شارهٔ یونی برخلاف شارهٔ مولکولی، در این فرایند همواره به حالت مایع است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6982, '۳۰ - اگر شمار الکترون‌های خارج‌شده از دریای الکترونی ($N.e^-$)، با شمار الکترون‌های مبادله‌شده هنگام تشکیل ترکیب یونی منیزیم فلوئورید برابر باشد، برای فروپاشی این مقدار از منیزیم فلوئورید، به تقریب چند کیلوژول گرما لازم است؟ ($\\Delta H (MgF_2(s))=3000\\ kJ.mol^{-1}$، جرم هر الکترون $0/0005\\ amu$ و هر $amu$ را معادل $1/66\\times 10^{-24}$ گرم در نظر بگیرید.) $E = 10^{-4}\\ g$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(6983, '۳۱ - اگر به محلول آمونیوم وانادات ($NH_4VO_3$)، مقدار زیادی فلز قلع به همراه مقدار کافی از هیدروکلریک اسید بیفزاییم، در نهایت محلول حاصل چه رنگی خواهد شد؟ (محلول دارای کاتیون‌های قلع، بی‌رنگ و شفاف است.) $VO_3^-(aq) + 4H^+(aq) + e^- \\rightarrow VO^{2+}(aq) + 2H_2O(l) \\quad E^\\circ = 1/00\\ V$ $VO^{2+}(aq) + 2H^+(aq) + e^- \\rightarrow V^{3+}(aq) + H_2O(l) \\quad E^\\circ = 0/347\\ V$ $V^{3+}(aq) + e^- \\rightarrow V^{2+}(aq) \\quad E^\\circ = -0/26\\ V$ $Sn^{2+}(aq) + 2e^- \\rightarrow Sn(s) \\quad E^\\circ = -0/13\\ V$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6984, '۳۲ - تفاوت آنتالپی فروپاشی کدام دو ترکیب یونی از بقیه، بیشتر است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6985, '۳۳ - محلول‌های حاوی کروم با عدد اکسایش ۶+، به رنگ نارنجی و با عدد اکسایش ۳+، به رنگ سبز هستند. با انجام واکنش زیر، در ابتدا رنگ محلول از نارنجی به قهوه‌ای و سپس با اضافه‌کردن مقدار بیشتری از محلول $FeSO_4$، رنگ محلول به سبز تغییر می‌کند. به تقریب چند میلی‌لیتر از محلول آهن (II) سولفات با غلظت ۰/۵ مولار باید با ۲۵ میلی‌لیتر محلول ۲۰ درصد جرمی پتاسیم دی‌کرومات ($K_2Cr_2O_7$) واکنش دهد تا محلول حاصل، سبز رنگ شود؟ (معادله واکنش در محیط اسیدی انجام‌شده و موازنه نشده است. چگالی محلول‌ها را ۱ گرم بر میلی‌لیتر در نظر بگیرید و $Fe=56, K=39, Cr=52, O=16, S=32: g.mol^{-1}$) $K_2Cr_2O_7(aq) + FeSO_4(aq) + H_2SO_4(aq) \\rightarrow Cr_2(SO_4)_3(aq) + Fe_2(SO_4)_3(aq) + K_2SO_4(aq) + H_2O(l)$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6986, '۳۴ - درستی یا نادرستی کدام گزینه با سایر گزینه‌ها متفاوت است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6987, '۳۵ - با توجه به نمودار، آنتالپی فروپاشی شبکه بلور لیتیم فلوئورید برحسب کیلوژول بر مول کدام است؟ آنتالپی $Li^+(g)+F(g)+e^-$ $Li(g)+F(g)$ $515 kJ$ $Li^+(g)+F^-(g)$ $330 kJ$ $Li(g)+\\frac{1}{2}F_2(g)$ $78 kJ$ $Li(s)+\\frac{1}{2}F_2(g)$ $160 kJ$ $617$ $LiF(s)$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6988, '۳۶ - کدام گزینه، ترتیب مورد انتظار برای آنتالپی فروپاشی شبکه را به درستی نشان داده است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6989, '۳۷ - کدام موارد زیر درست است؟ الف) دریای الکترونی با جابه‌جایی یکنواخت الکترون‌ها میان کاتیون‌های فلزی، نیروی یکنواختی به آن‌ها اعمال کرده و سبب حفظ چیدمان آن‌ها می‌شود. ب) نوع نیروهای جاذبه میان ذرات سازنده در کلسیم اکسید، اتانول و اتان به ترتیب یونی، هیدروژنی و وان‌دروالسی است. پ) برخی از خواص فیزیکی عنصرهای دوره‌های چهارم و پنجم گروه ۱۴ جدول تناوبی را می‌توان با مدل دریای الکترونی توجیه کرد. ت) جامدی سفید رنگ با نقطه ذوب ۳۰۰۰ درجه سلسیوس که با عبور جریان برق از آن به دو عنصر $X$ و $M$ تجزیه می‌شود، می‌تواند ساختاری شبیه الماس داشته باشد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:01:57', 1, NULL, NULL, 'free'),
(6990, '۱- پاسخ صحیح عبارت‌های زیر به ترتیب از راست به چپ در کدام گزینه آمده است؟ $(S = ۳۲, O = ۱۶ : g.mol^{-1})$\n\nالف) مولکولی چهار اتمی که در میدان الکتریکی جهت‌گیری می‌کند کدام است؟\n\nب) در مولکول $SO_۳$ تراکم بار الکتریکی منفی روی کدام اتم بیشتر است؟\n\nپ) نسبت درصد جرمی اکسیژن به گوگرد در مولکول گوگرد دی اکسید کدام است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6991, '۲- فرمول ساختاری یون تیوسولفات به شکل زیر است. با رعایت قاعدۀ هشت‌تایی، به ترتیب از راست به چپ بار الکتریکی این یون $(q)$ و نسبت تعداد الکترون‌های ناپیوندی به جفت الکترون‌های پیوندی کدام است؟\n\n(تصویر ساختار لوویس یون تیوسولفات)\n\n$\\begin{bmatrix} O \\\\ | \\\\ O-S-S \\\\ | \\\\ O \\end{bmatrix}^q$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6992, '۳- چه تعداد از عبارت‌های زیر در مورد خاک رس درست است؟\n\nآ) بیشترین درصد جرمی در بین ترکیب‌های سازنده آن مربوط به ترکیبی مولکولی است که در دما و فشار اتاق به حالت جامد دیده می‌شود.\n\nب) هر سه نوع اکسید فلزی، شبه‌فلزی در بین اجزای سازنده آن یافت می‌شوند.\n\nپ) از عبارت «فرمول مولکولی» نمی‌توان برای توصیف ترکیبی که عامل ایجاد رنگ سرخ آن است، استفاده کرد.\n\nت) بیشترین کاهش درصد جرمی بر اثر حرارت دادن آن، مربوط به ماده‌ای است که همه عنصرهای سازنده آن نافلز هستند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6993, '۴- کدام موارد درست بیان شده‌اند؟\n\nآ) $Si$ ساختاری شبیه به الماس دارد و آنتالپی پیوند $Si-Si$ از $C-C$ بیشتر است.\n\nب) علامت بار جزئی اتم مرکزی در دو ترکیب $OF_۲$ و $CO_۲$ متفاوت است.\n\nپ) در ساختار سیلیس پیوند میان همه اتم‌های سازنده از نوع اشتراکی است و درجه سختی آن از الماس کمتر است.\n\nت) گرافن، تک لایه‌ای از گرافیت است که اتم‌های کربن میان سه حلقه شش ضلعی مشترک هستند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6994, '۵- درصد جرمی سیلیس و آب در یک نمونه خاک رس به ترتیب برابر با ۳۶ و ۲۷/۲ درصد است. در اثر جذب مقداری رطوبت، درصد جرمی سیلیسیم در خاک رس ۱/۸ درصد تغییر می‌کند. درصد جرمی آب در این نمونه خاک رس چقدر شده و برای استخراج ۷۰ گرم سیلیسیم ۶۶ درصد خالص مطابق واکنش زیر، به چند گرم از این خاک رس جدید نیاز است؟ $(Si = ۲۸, O = ۱۶ : g.mol^{-1})$ (گزینه‌ها را از راست به چپ بخوانید.)\n\n$SiO_۲(s) + ۲C(s) \\xrightarrow{\\Delta} Si(l) + ۲CO(g)$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6995, '۶- کدام‌یک از مطالب زیر عبارت داده شده را به درستی تکمیل می‌کند؟\n\n«در ساختار مولکول ............ ، ............ مولکول ............ : ............»\n\nالف) هیدروژن سولفید – برخلاف – آمونیاک – اتم مرکزی دارای بار جزئی مثبت $(\\delta^+)$ می‌باشد.\n\nب) کربن مونوکسید – همانند – گوگرد دی اکسید – افزودن یک اتم اکسیژن، موجب کاهش قطبیت می‌گردد.\n\nپ) کربونیل سولفید – همانند – دی نیتروژن مونوکسید – اتم‌ها بر یک خط راست قرار گرفته و تفاوت آنتالپی پیوندها اندک است.\n\nت) گوگرد دی اکسید – برخلاف – گوگرد تری اکسید – نسبت تعداد الکترون‌های ناپیوندی به پیوندی با تعداد اتم‌های کناره برابر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6996, '۷- چه تعداد از عبارت‌های زیر نادرست هستند؟\n\nالف) کوارتز از جمله نمونه‌های ناخالص سیلیس است.\n\nب) نقشه تقریبی پتانسیل الکترواستاتیکی کربونیل سولفید به صورت رو به رو است. (شکل مولکول با بارهای جزئی)\n\nپ) $SiO_۲(s)$ سخت و دیرگداز است در حالی که $CO_۲(s)$ در دمای اتاق تصعید می‌شود.\n\nت) مدل گلوله و میله برای نشان دادن گرافن به شکل رو به رو است. (شکل ساختار لایه‌ای گرافیت)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6997, '۸- با توجه به اطلاعات جدول رو به رو، پاسخ صحیح پرسش‌های (الف)، (ب) و (پ) به ترتیب از راست به چپ در کدام گزینه آمده است؟\n\n| ماده | نقطه ذوب $(^\\circ C)$ | نقطه جوش $(^\\circ C)$ |\n\n| :---: | :---: | :---: |\n\n| $KBr$ | ۷۳۴ | ۱۴۳۵ |\n\n| $P_۴$ | ۴۴ | ۲۸۰ |\n\n| $NaCl$ | ۸۰۱ | ۱۴۱۳ |\n\n\n\nالف) کدام ماده در گسترهٔ دمایی بیشتری به حالت مایع باقی می‌ماند؟\n\nب) در فناوری تولید انرژی الکتریکی از پرتوهای خورشیدی، کدام ماده برای جذب انرژی مناسب نمی‌باشد؟\n\nپ) قوی‌ترین نیروی جاذبه میان ذره‌های سازنده در کدام ماده وجود دارد؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6998, '۹- درباره خاک رس، درستی یا نادرستی عبارات به ترتیب در کدام گزینه آمده است؟\n\nالف) با حل شدن خاک رس در آب، محلول حاصل خاصیت اسیدی دارد.\n\nب) در ساختار خاک رس، انواع ترکیبات در ۴ دسته‌بندی جامدهای بلوری یافت می‌شود.\n\nپ) بیشترین درصد جرمی در سفال کامل خشک شده، مربوط به یک جامد کووالانسی با درصد جرمی بیشتر از ۵۰٪ است.\n\nت) مقایسه ترتیب نقطه ذوب ۴ گروه جامد بلوری به کار رفته همانند درصد فراوانی این مواد در طبیعت است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(6999, '۱۰ - چند مورد از مطالب زیر درست است؟\n\n- سیلیسیم خالص به دلیل داشتن خواص نوری ویژه در ساخت منشورها و عدسی‌ها به کار می‌رود.\n\n- با وجود نسبت زیروند دو به یک در فرمول مولکولی سیلیس، هر اتم $Si$ با چهار اتم اکسیژن پیوند اشتراکی تشکیل می‌دهد.\n\n- از آنجا که ضخامت گرافیت به اندازه یک اتم کربن است، می‌توان آن را یک گونه شیمیایی دو بعدی دانست.\n\n- با لحاظ بزرگتر بودن آنتالپی پیوند $C-C$ نسبت به $Si-Si$، می‌توان گفت الماس نسبت به سیلیسیم خالص نقطه ذوب بالاتری دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7000, '۱۱ - کدام یک از گزینه‌های زیر درست است؟\n\nالف) در مولکول‌های کربونیل سولفید و گوگرد تری اکسید، اتم‌های مرکزی هر دو، بار جزئی با علامت یکسانی دارند.\n\nب) همه مولکول‌های با ساختار $V$ شکل ، قطبی به شمار می‌روند.\n\nپ) اگر مولکول $AB_۲$ در میدان جهت‌گیری نکند، قطعاً در نقشه پتانسیل الکترواستاتیکی آن یک رنگ دیده می‌شود.\n\nت) اگر آرایش الکترونی اتم $X$ به $۲p^۲$ و اتم $Y$ به $۳p^۵$ ختم شود، مولکول $XY_۴$ در میدان جهت‌گیری ندارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7001, '۱۲ - کدام گزینه درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7002, '۱۳ - با توجه به شکل مقابل چه تعداد از موارد زیر درست هستند؟\n\n- $a$ مانند $b$ مولکولی قطبی است و گشتاور دو قطبی $b$ به یقین بزرگ‌تر است.\n\n- $A$ در مولکول $b$ برخلاف $E$ در مولکول $a$ جفت الکترون ناپیوندی دارد.\n\n- در نقشه پتانسیل الکترواستاتیکی مولکول $b$، رنگ قرمز حتماً مربوط به اتم $A$ است.\n\n- مولکول $a$ ، مولکولی خطی است از این رو دمای جوش پایین‌تری دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7003, '۱۴ - کدام یک از عبارت‌های زیر درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7004, '۱۵ - در کدام یک از موارد زیر مقایسه درستی بین شعاع یون‌های داده شده صورت نگرفته است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7005, '۱۶ - چه تعداد از مقایسه‌های زیر به درستی انجام شده است؟\n\n- چگالی بار یون: $Na^+ < O^{۲-} < Mg^{۲+}$\n\n- شعاع یونی: $K^+ < Cl^- < P^{۳-}$\n\n- آنتالپی فروپاشی شبکه: $KBr < NaF < CaO$\n\n- نقطه ذوب: $K_۲O < CaO < Al_۲O_۳$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7006, '۱۷ - عبارت کدام گزینه درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7007, '۱۸- چند مورد از عبارت‌های زیر نادرست است؟ (وانادیم در دورۀ ۴ و گروه ۵ جدول تناوبی قرار دارد.)\n\nآ) $Fe_۲O_۳$ و $TiO_۲$ و دوده از جمله رنگ‌دانه‌های معدنی هستند که به ترتیب رنگ‌های سفید، قرمز و سیاه ایجاد می‌کنند.\n\nب) محلولی از نمک وانادیم $(III)$ به رنگ زرد است.\n\nپ) مهم‌ترین دلیل استفاده از تیتانیم در ساخت موتور جت، مقاومت بالاتر آن در برابر خوردگی نسبت به فولاد است.\n\nت) در آرایش الکترونی یونی از وانادیم که محلول آن سبز رنگ است، ۲ الکترون با $l=۱$ وجود دارد.\n\nث) در تهیۀ آلیاژ نیتینول از عنصرهای واسطه دورهٔ چهارم استفاده می‌شود که اکسید یکی از آن‌ها به عنوان رنگ‌دانهٔ سفید استفاده می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7008, '۱۹- کدام گزینه صحیح است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7009, '۲۰- چند مورد از عبارت‌های زیر به درستی بیان شده‌اند؟\n\nالف) در واکنش محلولی از نمک وانادیم $(V)$ با فلز روی، وانادیم $(V)$ نقش کاهنده دارد.\n\nب) در ساختار فلز مس، الکترون‌های ظرفیتی، دریای الکترونی را می‌سازند.\n\nج) اگر نسبت بار به شعاع یون $Ca^{+۲}$ برابر با $۲/۰۱ \\times ۱۰^{-۲} pm^{-۱}$ باشد، شعاع این یون $۱۹۸ pm$ است.\n\nد) تیتانیم همانند فولاد، مقاومت عالی در برابر سایش دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7010, '۲۱- کدام گزینه درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7011, '۲۲- کدام گزینه از نظر درستی یا نادرستی با سایر گزینه، متفاوت است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7012, '۲۳- کدام گزینه زیر درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7013, '۲۴- کدام موارد از عبارت‌های زیر درست است؟\n\nالف) اگر شعاع یون فلوئورید برابر $۱۳۳ pm$ و شعاع یون سولفید برابر $۱۸۴ pm$ باشد، چگالی بار یون فلوئورید از سولفید بیشتر است.\n\nب) جاذبۀ میان کاتیون و آنیون در ترکیب $CaO$ کمتر از $MgO$ می‌باشد.\n\nپ) اگر انرژی فروپاشی شبکه بلور $NaF$ و $KCl$ به‌ترتیب از راست به چپ به صورت تقریبی برابر $۹۰۰ kJ$ و $۷۰۰ kJ$ باشد، انرژی فروپاشی شبکه بلور $KF$ می‌تواند $۸۰۰ kJ$ باشد.\n\nت) برای آنتالپی فروپاشی شبکه بلور، ترکیب‌های یونی دوتایی حاصل از یک نوع فلز، همواره یک مقدار معین وجود دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7014, '۲۵- تیغه‌ای از فلز آلومینیم به جرم ۴/۳۲ گرم را در ۴۰۰ میلی‌لیتر محلول زردرنگ ۵/۲۵ درصد جرمی از نمک فرضی $(VO_۲)_nX$ با چگالی ۱/۲ گرم بر میلی‌لیتر قرار داده‌ایم تا به طور کامل با هم واکنش دهند. کدام‌یک از موارد زیر می‌توانند نشان‌دهندۀ رنگ محلول حاصل و نسبت عددی جرم مولی آنیون $X$ به $n$ باشند؟ $(V=۵۰, Al=۲۷, O=۱۶: g.mol^{-۱})$\n\nالف) سبز - ۲۳\n\nب) آبی - ۲۹/۵\n\nپ) بنفش - ۷۵/۵\n\nت) سبز - ۵۹', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7015, '۲۶- کدام گزینه به نادرستی بیان شده است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7016, '۲۷ - با توجه به جدول زیر که آنتالپی فروپاشی شبکه را برای برخی ترکیب‌های یونی، برحسب $kJ.mol^{-۱}$ نشان می‌دهد، پاسخ صحیح پرسش (الف) و پاسخ نادرست پرسش (ب) به ترتیب از راست به چپ در کدام گزینه آمده است؟\n\n<br>\n\n| آنیون | $F^-$ | $O^{۲-}$ |\n\n| :---: | :---: | :---: |\n\n| **کاتیون** | | |\n\n| $Na^+$ | $۹۲۶$ | $x$ |\n\n| $Mg^{۲+}$ | $۲۹۶۵$ | $۳۷۹۸$ |\n\n<br>\n\nالف) $x$، کدام عدد برحسب $kJ.mol^{-۱}$ می‌تواند باشد؟\n\nب) نقطه ذوب $MgF_۲$ بیشتر است یا $MgO$؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7017, '۲۸ - کدام موارد از عبارت‌های زیر به درستی بیان شده‌اند؟\n\nالف) برخی رفتارهای فیزیکی فلزها وابسته به الکترون‌های ظرفیتی آن‌ها است.\n\nب) نسبت چگالی فولاد به چگالی تیتانیم کمتر از یک است.\n\nج) اگر شعاع اتم عنصر $X$ ، $۱۴۹pm$ و شعاع یونی آن $۸۶pm$ باشد، عنصر $X$ یک فلز است.\n\nد) محلولی از نمک وانادیم (II) و محلولی از نمک وانادیم (IV) به ترتیب به رنگ بنفش و آبی دیده می‌شوند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7018, '۲۹ - کدام گزینه نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7019, '۳۰ - کدام مورد زیر درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7020, '۳۱ - کدام گزینه از نظر درستی یا نادرستی مانند جمله زیر است؟ $(O=۱۶, Al=۲۷ g.mol^{-۱})$\n\n«در واکنش مربوط به تولید ۵۱ گرم از ترکیب $Al_۲O_۳$ ، $۳/۰۱ \\times ۱۰^{۲۳}$ الکترون بین گونه‌های اکسنده و کاهنده مبادله می‌شود.»', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7021, '۳۲ - کدام گزینه زیر نادرست است؟ $(H=۱, C=۱۲ : g.mol^{-۱})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7022, '۳۳ - کدام گزینه زیر درست است؟ $(C=۱۲, O=۱۶, H=۱ : g.mol^{-۱})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7023, '۳۴ - اگر در مدل دریای الکترونی مربوط به $۳/۶$ گرم از فلز $X$، تفاوت شمار الکترون‌ها و کاتیون‌ها برابر با $۹/۰۳ \\times ۱۰^{۲۲}$ باشد؛ چند درصد از الکترون‌های اتم $X$ در مدل دریای الکترونی آن شرکت نمی‌کنند؟ ($X$ یک فلز اصلی متعلق به دسته $s$ می‌باشد و شماره دوره آن کمتر یا مساوی ۴ است.) $(Li=۷, Be=۹, Na=۲۳, Mg=۲۴, K=۳۹, Ca=۴۰ : g.mol^{-۱})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7024, '۳۵ - در کدام گزینه، ترکیب قطبی و نقشه پتانسیل الکترواستاتیکی آن ماده به درستی نشان داده شده است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7025, '۳۶- کدام مورد (موارد) از عبارت های بیان شده درست است؟\n\nآ) جامد کووالانسی مجموعه‌ای از اتم‌های بسیاری است که با هم پیوندهای اشتراکی دارند.\n\nب) نیروی بین مولکولی غالب در همهٔ ترکیبات آلی، از نوع وان‌دروالسی یا هیدروژنی است.\n\nپ) همهٔ مولکول‌های سه اتمی که در میدان الکتریکی جهت‌گیری می‌کنند، ساختاری خمیده دارند.\n\nت) در همهٔ مولکول‌های دو اتمی جور هسته، تراکم الکترون در اطراف هستهٔ یکی از اتم‌ها است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7026, '۳۷- با توجه به نقشه پتانسیل الکتروستاتیکی مولکول کربونیل سولفید $(SCO)$، اگر اتم گوگرد را در این مولکول با اتم اکسیژن جایگزین کنیم، کدام گزینه در رابطه با مولکول جدید صحیح نیست؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7027, '۳۸- کدام گزینه صحیح است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7028, '۳۹- تغییر روند در کدام‌یک از گزینه‌ها به درستی ذکر شده است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7029, '۴۰- کدام مطلب زیر درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7030, '۴۱- با توجه به نقشه پتانسیل الکتروستاتیکی مولکول روبه رو کدام گزینه درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7031, '۴۲- کدام گزینه درستی یا نادرستی عبارت‌های زیر را با اشتباهات کمتری نشان می‌دهد؟\n\n- گوگرد دی اکسید $(SO_۲)$ یک ترکیب مولکولی ناقطبی است که اتم مرکزی آن دارای بار جزئی مثبت است.\n\n- $HF$ نسبت به $NaCl$ در گسترهٔ دمایی کمتری به حالت مایع است و نیروی جاذبه میان ذرات سازنده آن ضعیف‌تر است.\n\n- آنتالپی فروپاشی شبکه پتاسیم برمید $(KBr)$ بیشتر از آنتالپی فروپاشی شبکه پتاسیم فلوئورید $(KF)$ است.\n\n- نیتینول آلیاژی از نیکل و وانادیم است که در ساخت فراورده‌های صنعتی و پزشکی کاربرد دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7032, '۴۳- با توجه به جدول زیر، کدام عبارت درست است؟\n\n(جدول: $Si-O: X$, $Si-C: ۳۰۱$, $C-C: ۳۴۸$, $Si-Si: ۲۲۶$ میانگین آنتالپی پیوند $(kJ.mol^{-۱})$)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7033, '۴۴- چند مورد از مطالب زیر صحیح هستند؟\n\n• $SiO_۲(s)$ سخت و دیرگداز است در حالی که $CO_۲(s)$ در دمای اتاق تصعید می‌شود.\n\n• کوارتز از جمله نمونه‌های ناخالص سیلیس است.\n\n• در نقشهٔ پتانسیل الکتروستاتیکی علامت $(\\delta^-)$ نشان دهندهٔ تراکم بیشتر بار الکتریکی منفی است.\n\n• اگر به جای یون کلرید در سدیم کلرید جامد، یون برمید جایگزین شود، انرژی لازم برای فروپاشی شبکهٔ ترکیب جدید کمتر می‌گردد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7034, '۴۵- با توجه به اطلاعات جدول، کدام عبارت‌ها صحیح است؟\n\n(جدول: $NaCl$: ذوب ۸۰۱ جوش ۱۴۶۵، $P_۴$: ذوب ۴۴ جوش ۲۸۰، $H_۲O$: ذوب ۰ جوش ۱۰۰، $KBr$: ذوب ۷۳۴ جوش ۱۴۳۵)\n\nآ) آنتالپی فروپاشی شبکه نمک طعام از پتاسیم برمید بیشتر است.\n\nب) مواد $KBr$ و $H_۲O$ در فناوری تولید انرژی الکتریکی از پرتوهای خورشیدی برای جذب انرژی مناسب هستند.\n\nپ) نقطهٔ ذوب $LiCl$ از $KBr$ بیشتر است، چون آنتالپی فروپاشی شبکه بلور آن بیشتر است.\n\nت) اختلاف نقطهٔ ذوب $NaBr$ و $KBr$ از بازه مایع بودن آب بیشتر است.\n\nث) در نقشه پتانسیل الکتروستاتیکی آب، اتم اکسیژن دارای بار جزئی منفی $(\\delta^-)$ است، پس احتمال حضور جفت الکترون پیوندی پیرامون هسته آن بیشتر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:02:36', 1, NULL, NULL, 'free'),
(7035, '۱- یک نمونه $3$ گرمی از آلیاژی که شامل فلزهای آلومینیم، کروم، کبالت و نیکل است، در طی چند واکنش شیمیایی به طور کامل مصرف و به $1/32$ گرم آلومینیم اکسید، $3/15$ گرم کبالت (II) سولفات، $1/02$ گرم نیکل (II) کربنات و $1/19$ گرم کروم (II) فسفات تبدیل شده است. درصد جرمی کبالت در آلیاژ اولیه کدام است؟ $(C=12, O=16, Al=27, P=31, S=32, Ni=58, Co=59 : g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7036, '۲- کدام مطالب زیر در ارتباط با دو عنصر کربن و سیلیسیم، نادرست است؟ آ) در ساختار تمام جامدهای کووالانسی، دست کم یکی از این دو عنصر یافت می‌شود. ب) هر دو عنصر به شکل خالص در طبیعت یافت می‌شوند. پ) سیلیسیم و پایدارترین دگرشکل کربن، جریان برق را از خود عبور می‌دهند. ت) باتوجه به بلندتر بودن طول پیوند $Si-Si$ در مقایسه با طول پیوند $C-C$، سیلیسیم ناپایدارتر از کربن است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7037, '۳- مولکول‌های کلروفرم و کربن تتراکلرید، در چه تعداد از موارد زیر با یکدیگر تفاوت دارند؟ • شمار پیوندهای اشتراکی • جهت‌گیری در میدان الکتریکی • حالت فیزیکی در دما و فشار اتاق • نوع و مقدار بار جزئی اتم مرکزی', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7038, '۴- چه تعداد از عبارت‌های زیر در ارتباط با الماس و گرافیت، درست است؟ • در آلوتروپی که چگال‌تر است، هر اتم کربن به شمار اتم‌های کربن کم‌تری متصل است. • گرمای سوختن مولی آلوتروپی که رسانای گرما می‌باشد، بیشتر است. • گرافن، تک لایه‌ای از گرافیت است که ضخامت آن به اندازه یک اتم کربن بوده و برخلاف گرافیت، شفاف و انعطاف‌پذیر است. • با قرار دادن گرد گرافیت بین دو تکه نوارچسب و سپس جدا کردن یکی از نوارچسب‌ها و تکرار این کار، پیوندهای اشتراکی کربن - کربن میان لایه‌ها شکسته می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7039, '۵- عنصرهای $A$، $D$، $X$، $E$ و $G$ پنج عنصر متوالی در جدول دوره‌ای هستند و عدد اتمی $G$ بیشتر از چهار عنصر دیگر است. اگر مجموع اعداد اتمی این عنصرها برابر با $65$ باشد، کدام‌یک از مطالب زیر درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7040, '۶- مولکول $AX_2$ در میدان الکتریکی جهت‌گیری می‌کند و هر دو عنصر سازنده آن متعلق به دوره دوم جدول تناوبی هستند. چه تعداد از عبارت‌های زیر در ارتباط با آن همواره درست است؟ (نماد عنصرها فرضی است.) • شکل هندسی مولکول، خمیده ( V شکل ) است. • اتم مرکزی، دست کم دارای یک جفت الکترون ناپیوندی است. • تفاوت عدد اتمی عنصرهای $A$ و $X$، برابر با یک است. • در نقشه پتانسیل الکتروستاتیکی این مولکول، تراکم رنگ سرخ در اطراف اتم مرکزی بیشتر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7041, '۷- چه تعداد از عبارت‌های زیر در ارتباط با مواد مولکولی، به یقین درست است؟ (از گازهای نجیب چشم‌پوشی کنید.) • واحدهای سازنده این مواد، مجزا بوده و شامل دو یا چند اتم با پیوندهای اشتراکی هستند. • در هیچ‌کدام از حالت‌های جامد، مایع و محلول در آب، نمی‌توانند جریان برق را از خود عبور دهند. • اگر یک ماده در دما و فشار اتاق، گازی شکل باشد، جزو مواد مولکولی است. • رفتار فیزیکی این مواد به نوع و قدرت نیروهای بین مولکولی و پیوندهای اشتراکی موجود در ساختار مولکول، وابسته است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7042, '۸- باتوجه به شکل مقابل که نمایی از فناوری تولید انرژی الکتریکی از پرتوهای خورشیدی را نشان می‌دهد، کدام مطالب زیر درست است؟ آ) فرمول شیمیایی شاره استفاده شده در قسمت‌های $A$ و $B$ یکسان بوده و دما در قسمت $A$ بالاتر از قسمت $B$ است. ب) فرمول شیمیایی شاره استفاده شده در قسمت‌های $C$ و $D$ یکسان بوده و دما در قسمت $D$ بالاتر از قسمت $C$ است. پ) در این فرایند از دو شاره استفاده می‌شود که در یک چرخه، تبخیر و میعان می‌شوند. ت) در این فناوری، هیچ فرایند شیمیایی صورت نمی‌گیرد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7043, '۹- باتوجه به عدد اتمی عنصرهای $A=8$، $X=9$، $D=12$، $G=15$، $J=16$ و $L=17$، کدام مطالب زیر درست است؟ (نماد عنصرها فرضی است.) آ) در مولکول $DL_2$، هسته اتم‌های سازنده بر روی یک خط راست قرار دارند. ب) در نقشه پتانسیل الکتروستاتیکی مولکول‌های $LX_2$ و $GL_3$، رنگ اتم‌های $L$ متفاوت است. پ) نقشه پتانسیل الکتروستاتیکی مولکول‌های $JA_3$ و $GX_3$ از نظر شکل ظاهری مشابه هم است. ت) نقشه پتانسیل الکتروستاتیکی مولکول‌های $JA_2$ و $JX_2$ از نظر شکل ظاهری شبیه مولکول آب است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7044, '۱۰- باتوجه به شکل زیر که درصد بازتاب یا عبور طول موج پرتوهای الکترومغناطیسی در گستره مرئی را توسط سه رنگدانه دوده، $TiO_2$ و $Fe_2O_3$ نشان می‌دهد، کدام مطلب نادرست است؟ $(O=16, Ti=48, Fe=56 : g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7045, '۱۱- کدام عبارت‌ها در ارتباط با محلول حاوی نمکی از یون وانادیم $(_{23}V)$ با عدد اکسایش $+x$، درست است؟ $(Mg = 24 g.mol^{-1})$ آ) اگر شمار الکترون‌ها در بیرونی‌ترین زیرلایه یون $V^{x+}$، برابر با $\\frac{1}{4}$ بار الکتریکی آن باشد، رنگ این محلول مشابه رنگ $CuSO_4(aq)$ است. ب) اگر یون $V^{x+}$ نتواند تیغه روی را اکسید کند، رنگ محلول آن، مشابه رنگ کم‌ترین طول موج در ناحیه مرئی طیف نشری خطی عنصر هیدروژن است. پ) اگر $x$، بزرگ‌ترین مقدار ممکن را داشته باشد، هر مول از یون وانادیم در این حالت می‌تواند با مبادله $1/806 \\times 10^{24}$ الکترون، حداکثر $36$ گرم فلز منیزیم را به کاتیون پایدارش تبدیل کند. ت) اگر رنگ محلول وانادیم، مشابه رنگ رسوب آهن (II) هیدروکسید باشد، آرایش الکترونی یون وانادیم، مشابه آرایش الکترونی اتم سومین فلز قلیایی خاکی است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7046, '۱۲ - کدام مطالب زیر در ارتباط با آلیاژ هوشمند نیتینول درست است؟ آ) دومین و هشتمین فلز دسته $d$، عناصر سازنده آن به شمار می‌روند. ب) با توجه به برابر بودن مجموع بار الکتریکی کاتیون‌ها با مجموع بار الکتریکی آنیون‌ها، در این آلیاژ همانند فلزهای خالص، خنثی است. پ) این آلیاژ در ساخت قاب عینک، بدنه دوچرخه و استنت برای رگ‌ها به کار می‌رود. ت) رسانایی الکتریکی و رفتار در برابر ضربه برای هرکدام از عنصرهای سازنده آن با مدل دریای الکترونی قابل توجیه است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7047, '۱۳ - پاسخ پرسش‌های زیر در کدام گزینه به درستی آمده است؟ آ) بین فلزهای قلیایی و قلیایی خاکی از دوره‌های دوم و سوم جدول دوره‌ای که یون پایدار تشکیل می‌دهند، کدام‌یک شعاع یونی کوچک‌تری دارد؟ ب) شعاع اتمی یک فلز در مقایسه با شعاع یونی نافلز هم دوره با آن چگونه است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7048, '۱۴ - با توجه به داده‌های جدول زیر که مربوط به آنتالپی فروپاشی شبکه بلور چند ترکیب یونی است، چه تعداد از عبارت‌های پیشنهاد شده درست است؟ | کاتیون / آنیون | $F^-$ | $O^{2-}$ | | :---: | :---: | :---: | | $Na^+$ | ۹۲۶ | a | | $Mg^{2+}$ | b | ۳۷۰۴ | - مقدار $b$ بزرگ‌تر از $a$ است. - گرمای مبادله شده در واکنش $Na^+(g) + Cl^-(g) \\rightarrow NaCl(s)$ کم‌تر از ۹۲۶ کیلوژول است. - مقایسه میان شعاع یون‌ها و چگالی بار آن‌ها به ترتیب به صورت $Mg^{2+} < Na^+ < F^- < O^{2-}$ و $F^- < Na^+ < O^{2-} < Mg^{2+}$ است. - اگر به نمونه‌هایی از سدیم فلوئورید و منیزیم اکسید به میزان یکسانی گرما بدهیم تا به یون‌های سازنده گازی تبدیل شوند، شمار الکترون‌های مبادله شده در نمونه $MgO$، دو برابر نمونه $NaF$ است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7049, ' چه تعداد از مطالب زیر در ارتباط با پتاسیم سیلیکات (a) و آمونیوم سولفید (b)، درست است؟ - نسبت عدد کوئوردیناسیون آنیون به عدد کوئوردیناسیون کاتیون در a، دو برابر همین نسبت در b است. - نسبت شمار اتم‌ها به شمار عنصرها در a، بزرگ‌تر از همین نسبت در b است. - هر دو ترکیب در حالت جامد، شکننده و در حالت مایع، رسانای جریان برق هستند. - نسبت بار به شعاع برای آنیون b، بزرگ‌تر از همین نسبت برای کاتیون a است.', 3, 3, 73, 298, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7050, '۱۶ - چه تعداد از موارد پیشنهاد شده، عبارت زیر را به درستی کامل می‌کند؟ «آنتالپی فروپاشی .......................، با افزایش .......................، کاهش می‌یابد.» - هالیدهای پتاسیم – نقطه ذوب و جوش هالوژن - برمید فلزهای قلیایی – واکنش‌پذیری فلز قلیایی - ترکیب‌های یونی پتاسیم و نافلزهای دوره دوم جدول تناوبی – واکنش‌پذیری نافلزها - اکسید فلزهای دوره سوم جدول تناوبی – واکنش‌پذیری فلزها', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7051, '۱۷ - کدام مطالب زیر نادرست است؟ آ) در ساختار فراوان‌ترین اکسید سازنده پوسته جامد زمین، حلقه‌های ۶ گوشه و ۱۲ گوشه متشکل از پل‌های $Si - O - Si$ دیده می‌شود. ب) در جرم‌های برابر از گرافیت و الماس، شمار جفت الکترون‌های پیوندی، برابر، اما حجم و سختی دگرشکل ناپایدارتر، بیشتر است. پ) گرافن تک‌لایه‌ای از گرافیت به ضخامت یک اتم کربن است که شامل حلقه‌هایی به هم چسبیده، مشابه حلقه بنزن است. ت) در ساختار هر مولکول یخ، مجموع جفت الکترون‌های پیوندی و ناپیوندی، برابر با حداکثر شمار پیوند هیدروژنی قابل تشکیل توسط آن مولکول است. ث) ترکیب‌هایی که در دما و فشار اتاق به حالت مایع هستند، تنوع و شمار بیشتری نسبت به مواد کووالانسی دارند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7052, '۱۸ - با توجه به شکل مقابل که بخشی از جدول تناوبی را نشان می‌دهد، چه تعداد از عبارت‌های پیشنهاد شده درست است؟ \n\nتاکنون هیچ یونی از عنصرهای $G$ و $J$ شناخته نشده است. - ترکیب سه‌تایی از عنصرهای $A$، $X$ و $G$ می‌تواند ساختار خطی داشته باشد. - برای عنصر $L$ در ترکیبات مختلف، چهار نوع عدد اکسایش مختلف می‌توان در نظر گرفت. - اکسیدی از فلز $D$ وجود دارد که همه طول موج‌ها را بازتاب می‌دهد. - آلیاژی از فلزهای $L$ و $E$ وجود دارد که در موتور جت و پروانه کشتی اقیانوس‌پیما از آن استفاده می‌شود.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7053, '۱۹ - چه تعداد از عبارت‌های زیر نادرست است؟ - پیوندهای کووالانسی موجود در سیلیس، مستحکم‌تر از پیوندهای کووالانسی موجود در کربن دی‌اکسید هستند. - تیتانیم در برابر سایش، مقاوم است، در صورتی که فولاد در برابر سایش از مقاومت ضعیفی برخوردار است. - اگر شمار الکترون‌های کاتیون $A$، کم‌تر از شمار الکترون‌های کاتیون $B$ باشد، چگالی بار کاتیون $A$ بیش‌تر است. - تفاوت شعاع یون‌های $K^+$ و $F^-$، بیش‌تر از تفاوت شعاع یون‌های $Li^+$ و $Cl^-$ است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7054, '۲۰ - نسبت شمار عبارت‌های درست به شمار عبارت‌های نادرست در کدام گزینه آمده است؟ - سیکلوهگزان از نظر قطبیت، شبیه به کلروفرم است. - بار جزئی اتم‌های کناری در مولکول‌های $OF_2$ و $SCl_2$، منفی است. - شمار جفت الکترون‌های پیوندی در کربونیل سولفید و اکسید ناقطبی شانزدهمین عنصر جدول دوره‌ای، با هم برابر، اما شکل هندسی آن‌ها متفاوت است. - هر مولکول از ترکیب حاصل از دو عنصر نخست گروه چهاردهم، شامل دو اتم است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7055, '21-کدام مطلب نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7056, '22-با توجه به جدول زیر، کدام مورد همواره درست است؟ | ویژگی | ماده | |---|---| | ترکیبی شامل اتم‌های بسیاری است که با پیوند اشتراکی به هم متصل شده‌اند. | A | | یک ترکیب آلی است. | B | | یک ترکیب یونی است که فلز و نافلز سازنده آن در دوره سوم جدول تناوبی جای دارند. | C | | فلزی واسطه از دوره چهارم جدول تناوبی است. | D |', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:09', 1, NULL, NULL, 'free'),
(7057, '۱- مقدار $\\frac{۰/۴}{ }$ مول آهن را با چند گرم فلز مس مخلوط کنیم تا درصد جرمی آهن در نمونه ایجاد شده برابر با $۷۰$ درصد شود؟ $(Fe=56\\,g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7058, '۲- در آلیاژی از آهن و روی، درصد جرمی فلز با قدرت کاهندگی بیشتر، برابر با $۴۶/۵$ است. یک نمونه $۴۰$ گرمی از این آلیاژ فلزی با چند لیتر محلول هیدرویدیک اسید با $pH=۱/۳$ به‌طور کامل واکنش می‌دهد؟ $(Zn=65 \\ و \\ Fe=56\\,g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7059, '۳- چند مورد از مطالب زیر، درست‌اند؟ $(O=16,\\ C=12,\\ H=1:\\ g.mol^{-1})$ الف: آلوتروپ ناپایدارتر کربن، رسانای الکتریکی بوده و در ساختار $۱۵$ گرم آن، $۳/۰۱\\times10^{23}$ پیوند اشتراکی وجود دارد. ب: پختن نان بر روی دانه‌های سنگ نشان از مقاومت گرمایی فراوان‌ترین اکسید موجود در پوسته جامد زمین دارد. پ: اگر اتم‌های فلوئورِ مولکول $CF_{4}$ با اتم‌های $H$ جایگزین شوند، عدد اکسایش اتم مرکزی در این ماده تغییر نمی‌کند. ت: درصد جرمی اکسیژن در ساختار مولکول گلوکز، از درصد جرمی آن در الکل موجود در محلول ضدیخ بیشتر است.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7060, '۴- کدام عبارت زیر نادرست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7061, '۵- یک نمونه $۸۰$ گرمی از فلز روی با خلوص $۳۳/۵$ را در مجاورت با مقداری $MnO_{2}$ قرار می‌دهیم تا بر اساس معادله موازنه‌نشده $MnO_{2}(s)+Zn(s)\\rightarrow ZnO(s)+Mn_{2}O_{3}(s)$ به‌طور کامل مصرف شود. چند گرم لیتیم اکسید را به روی اکسید تولیدشده اضافه کنیم تا درصد جرمی روی اکسید در نمونه برابر با $۸۱$ شود؟ $(Zn=65 \\ و \\ O=16:\\ g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7062, '۶- کدام مورد در رابطه با دو عنصر $X_{8}$ و $Y_{9}$ درست است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7063, '۷- کدام موارد از عبارت‌های داده شده درست هستند؟ الف: در دمای اتاق، حالت فیزیکی شاره یونی استفاده‌شده در نیروگاه خورشیدی، همانند یک نمونه از ید است. ب: در نیروگاه خورشیدی، از یک ترکیب حاوی مولکول‌های مجزا، برای جذب گرمای خورشید استفاده می‌شود. پ: بزرگ‌ترین منبع انرژی برای زمین، انرژی خود را توسط پرتوهای الکترومغناطیسی به سمت زمین گسیل می‌کند. ت: در نیروگاه خورشیدی، ماده‌ای که در طول شب انرژی گرمایی خورشید را ذخیره می‌کند، دمایی کمتر از $1000K$ دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7064, '۸- مقدار $۱۷/۵$ درصد از کل جرم ترکیب $X_{4}(SiO_{4})_{3}$ را شبه‌فلز تشکیل داده است. جرم اتمی فلز $X$ چند $amu$ است و اگر شمار نوترون‌ها در اتم این عنصر $۳$ واحد بیشتر از شمار پروتون‌ها باشد، شماره گروه عنصر $X$ چند برابر شماره گروه فراوان‌ترین فلز اصلی موجود در سیاره زمین می‌شود؟ $(Si=28 \\ و \\ O=16:\\ g.mol^{-1})$ (عدد جرمی را برابر با جرم اتمی در نظر بگیرید.)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7065, '۹- کدام ترکیب یونی زیر در مقایسه با سایر ترکیب‌های داده شده دارای آنتالپی فروپاشی شبکه کوچک‌تری است؟', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7066, '۱۰- آنتالپی سوختن متانول برابر با $-729/6\\ kJ.mol^{-1}$ است. برای تأمین انرژی مورد نیاز جهت تولید $1$ مول یون گازی مجزا بر اثر فروپاشی شبکه بلور سدیم اکسید، تقریباً باید چند گرم متانول را به‌طور کامل بسوزانیم؟ (آنتالپی فروپاشی شبکه سدیم اکسید برابر با $2508$ کیلوژول بر مول است.) $(O=16 \\ و \\ C=12 \\ و \\ H=1:\\ g.mol^{-1})$', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7067, '۱۱- در عنصر $X$ با عدد اتمی کمتر از $36$، تعداد الکترون با $l=0$ و $l=1$ با یکدیگر برابر است. در رابطه با این عنصر، کدام عبارت می‌تواند درست باشد؟ الف: چگالی بار یون پایدار آن از چگالی بار یون فلوئورید بیشتر است. ب: یون تک‌اتمی حاصل از این عنصر، معادل با دومین کاتیون فراوان در آب دریا است. پ: حالت فیزیکی آن نسبت به عناصر هم‌گروه خود متفاوت بوده و مشابه عنصر پس از خود است. ت: واکنش‌پذیری کمتری نسبت به عنصر قبل از خود دارد و در واکنش با گاز زردرنگ کلر، $2$ الکترون از دست می‌دهد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7068, '۱۲- 25 گرم مخلوطی از گرد طلا و کلسیم را در 100 میلی‌لیتر محلول سولفوریک اسید وارد می‌کنیم تا واکنش کامل انجام شود. اگر در طول واکنش، غلظت مولی محلول از 0/8 مولار به 0/5 مولار برسد، درصد جرمی طلا در این نمونه چقدر بوده و چند مول فلز کلسیم در آن وجود داشته است؟ (Ca=40 g.mol⁻¹)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7069, '۱۳- دمای ماده‌ای که در حالت جامد نارسانا است را تا حدود 1535°C افزایش می‌دهیم تا حالت فیزیکی آن از جامد به مایع تبدیل شود. اگر این ماده در حالت مذاب جریان برق را از خود عبور دهد، ............', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7070, '۱۴- کدام موارد از عبارت‌های زیر درست است؟  \n\nالف) سیلیس یک ماده دیرگداز با درجه سختی بالا بوده و در حالت مذاب، برخلاف فلزها جریان الکتریسیته را عبور نمی‌دهد.  \n\nب) شمار اتم‌های اکسیژن در ساختار هر حلقه چندضلعی موجود در بلور سیلیس، 2 برابر شمار اتم‌های سیلیسیم است.  \n\nپ) گرافیت سطحی کدر و ساختاری لایه‌ای داشته و لایه‌های آن به وسیله نیروی واندروالسی روی هم قرار گرفته‌اند.  \n\nت) الماس، در مقایسه با سیلیسیم کاربید درجه سختی کمتری داشته و نسبت به گرافیت چگالی بیشتری دارد.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7071, '۱۵- آهن موجود در 500 گرم آهن(III) اکسید را استخراج کرده و آن را با مقدار کافی منیزیم مخلوط می‌کنیم. اگر درصد جرمی منیزیم در آلیاژ تولید شده برابر با 30% باشد، برای تولید آلیاژ مورد نظر چند مول منیزیم مصرف شده است؟ (Fe=56 , Mg=24 , O=16 g.mol⁻¹)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7072, '۱۶- بر اثر سوختن ترکیب مقابل، بخار آب به همراه گازهای CO₂ و SO₂ تولید می‌شود. اگر 36/5 گرم از این ترکیب را به طور کامل بسوزانیم، چند گرم فرآورده با گشتاور دوقطبی بزرگ‌تر از صفر تولید خواهد شد؟ (S=32 , O=16 , C=12 , H=1 g.mol⁻¹)', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7073, '۱۷- کدام موارد از عبارت‌های زیر درست است؟  \n\nالف) اگر آرایش الکترونی کاتیون یک فلز واسطه به زیرلایه‌ای با l=2 ختم شود، بار این کاتیون به یقین بیشتر از +1 است.  \n\nب) ماده‌ای که در حالت مذاب نارسانا بوده و در حالت جامد نیز سخت است، به یقین متعلق به دسته d نخواهد بود.  \n\nپ) وانادیم قدرت کاهندگی کمتری نسبت به روی داشته و محلول نمک آن با عدد اکسایش +5 زرد رنگ است.  \n\nت) پس از دوره برنز، در دوره سنگی، جوامع بشری مختلف دچار دگرگونی و رشد چشمگیر شدند.', 3, 3, 73, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, NULL, NULL, 'free'),
(7074, ' اگر گرمای حاصل از سوختن 11/5 گرم اتانول بتواند مقداری پتاسیم برمید را به یک مول از یون‌های گازی سازنده تبدیل کند، آنتالپی سوختن اتانول چند کیلوژول بر مول است؟ (آنتالپی فروپاشی شبکه بلور KBr برابر 690 kJ/mol است) (O=16 , C=12 , H=1 g.mol⁻¹)', 3, 3, 73, 298, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, '2026-03-29 17:31:35', 4, 'done'),
(7075, ' کدام موارد از عبارت‌های زیر درست است؟  \n\nالف) افزایش تفاوت نقطه ذوب و جوش مواد، به معنای افزایش قدرت نیروهای بین ذرات سازنده آن‌ها است.  \n\nب) مولکولی با نقشه پتانسیل الکترواستاتیکی مقابل، در حضور میدان الکتریکی جهت‌گیری می‌کند.  \n\nپ) توزیع بار الکتریکی در اطراف اتم مرکزی در ساختار مولکول CCl₄ نامتقارن است.  \n\nت) عدد کوردیناسیون یون Cl⁻ در بلور NaCl برابر با شمار جفت الکترون ناپیوندی در SO₃ است.', 3, 3, 73, 297, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, '2026-03-27 23:08:59', 4, 'done'),
(7076, ' بار الکتریکی یون مقابل چند برابر بار الکتریکی یون سولفات بوده و نسبت شمار اتم‌ها به شمار عناصر در ساختار ترکیب حاصل از این یون با یون آمونیوم چقدر خواهد شد؟', 3, 3, 73, 317, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, '2026-03-28 14:13:53', 5, 'done'),
(7077, ' مقداری منیزیم اکسید با خلوص 50% را با 120 گرم کلسیم کربنات مخلوط می‌کنیم. اگر درصد جرمی ذرات منیزیم در مخلوط حاصل از این فرآیند برابر با 6% باشد، جرم نمونه منیزیم اکسید چقدر بوده است؟ (Mg=24 , O=16 g.mol⁻¹)', 3, 3, 73, 295, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, '2026-03-27 23:08:23', 4, 'done'),
(7078, ' با توجه به داده‌های موجود در جدول زیر، کدام مطلب نادرست است؟ میانگین آنتالپی پیوند (kJ.mol⁻¹) برای پیوندهای Si-O=x ، Si-C=301 ، C-C=348 و Si-Si=226 داده شده است.', 3, 3, 73, 296, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, '2026-03-26 21:17:33', 5, 'done'),
(7079, ' در رابطه با بلور منیزیم فلوئورید، کدام‌یک از عبارت‌های زیر درست است؟  \n\nالف) معادله فروپاشی شبکه بلور آن به صورت MgF₂(s) → Mg²⁺(g) + 2F⁻(g) + 2968 kJ است.  \n\nب) اگر یون فلوئورید را با یون کلرید جایگزین کنیم، آنتالپی فروپاشی شبکه کاهش می‌یابد.  \n\nپ) با انحلال این ماده در آب، همانند استون، رسانایی الکتریکی محلول افزایش می‌یابد.  \n\nت) این ماده در مقایسه با Al₂O₃ دمای ذوب پایین‌تری دارد.', 3, 3, 73, 298, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-22 22:03:30', 1, '2026-03-26 21:10:46', 5, 'done'),
(7080, 'کدام یک از اثرهای زیر در مدل‌سازی پرتاب توپ بسکتبال قابل چشم‌پوشی است؟\n\nالف) مقاومت هوا و اثر وزش باد\n\nب) نیروی گرانشی وارد بر توپ\n\nپ) جهت حرکت و اندازه سرعت اولیه توپ\n\nت) تغییر نیروی گرانش به دلیل تغییر ارتفاع توپ', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:03:20', 1, '2026-03-26 21:10:22', 5, 'done'),
(7081, 'در کدام‌یک از گزینه‌های زیر، کمیت اصلی یا کمیت برداری وجود ندارد؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:03:20', 1, '2026-03-26 21:10:14', 5, 'done'),
(7082, 'وسیله‌های نشان داده شده در شکل‌های «الف» و «ب» به ترتیب ...................... و ...................... هستند و دقت ریزسنج، ...................... میکرومتر است.', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:03:20', 1, '2026-03-26 20:29:26', 5, 'done'),
(7083, 'اگر تندی نور در خلأ را $3 \\times 10^8 m/s$ در نظر بگیریم، این مقدار چند یکای نجومی بر ساعت ($AU/h$) است؟ (یکای نجومی، فاصله متوسط زمین تا خورشید و تقریباً $150$ میلیون کیلومتر است.) .', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:03:20', 1, '2026-03-26 21:10:06', 5, 'done'),
(7084, 'استخری به ابعاد $6m \\times 4m \\times 3m$ را با شلنگ آبی که آهنگ خروج آب از آن ثابت است، پر می‌کنیم. اگر استخر در $12$ ساعت پر شود، آهنگ خروج آب از شلنگ چند لیتر بر دقیقه است؟.', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:03:20', 1, '2026-03-26 21:09:58', 5, 'done'),
(7085, 'در آزمایشی، طول یک جسم چندین بار اندازه‌گیری شده و مقدار‌های $13/2$، $20/2$، $19/6$، $28/2$، $21/1$ و $20/7$ برحسب میلی‌متر ثبت شده است. نتیجهٔ اندازه‌گیری‌ای که باید گزارش شود، به صورت نمادگذاری علمی در SI کدام است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:03:20', 1, '2026-03-26 21:09:51', 5, 'done'),
(7086, ' چند عدد از یکاهای اصلی SI دارای پیشوند یکا هستند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:09:42', 5, 'done'),
(7087, ' کدام دسته از یکاهای زیر همگی از یکاهای اصلی SI هستند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:09:32', 5, 'done'),
(7088, '۳- چند مورد از عبارت‌های زیر صحیح است؟ الف) کمیت‌هایی که با نماد AU و ly نمایش داده می‌شود، هر دو کمیت‌هایی از جنس طول هستند. ب) ساعت‌های اتمی دقت بسیار زیادی دارند. ج) اختروش‌ها در دورترین محل قابل مشاهده کیهان قرار دارند. د) ستاره‌های کوتوله سفید چگالی بسیار کمی دارند.', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-09-23 18:26:00', 4, 'done'),
(7089, '۴- در تساوی مقابل حاصل $a+b+c+d$ کدام است؟ $10^a \\frac{\\text{N}^2 \\cdot \\mu\\text{g}}{\\text{J}^b} = \\frac{\\text{s}^2}{10^c \\text{m}^d}$ ($\\text{N}$، $\\text{g}$، $\\text{J}$، $\\text{s}$ و $\\text{m}$ به ترتیب یکاهای نیوتون، گرم، ژول، ثانیه و متر است.)', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:09:14', 5, 'done'),
(7090, '۵- طول جسمی $0/000180 \\times 10^{-3} \\text{Mm}$ اندازه‌گیری شده است. طول این جسم برحسب $\\mu\\text{m}$ و به صورت نمادگذاری علمی، برابر کدام گزینه است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:09:08', 5, 'done'),
(7091, '۶- حاصل عبارت زیر بیانگر کدام کمیت فیزیکی است و مقدار آن در SI کدام است؟ $\\frac{1/835 \\times 10^5 \\text{mm} + 0/865 \\times 10^{-4} \\text{Mm}}{0/05 \\times 10^{-9} \\text{Ms}^2 + 0/04 \\times 10^{-21} \\text{Ts}^2}$', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:09:02', 5, 'done'),
(7092, '۷- یکای فرعی $\\text{ng} \\cdot \\text{cm}^{-1} \\cdot \\mu\\text{s}^{-2}$ معادل کدام یک از گزینه‌های زیر است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-09-23 18:25:32', 4, 'done'),
(7093, ' در رابطه $AB + \\text{aA}^2 = \\text{d}$، اگر $\\text{d}$ نماد جابه‌جایی و $\\text{a}$ نماد شتاب باشد، $\\text{A}$ و $\\text{B}$ به ترتیب چه کمیت‌هایی هستند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:08:44', 5, 'done'),
(7094, '۹- اگر در تساوی فیزیکی $\\text{P} = 500\\text{v}^2 + 10^4\\text{h}$، کمیت‌های $\\text{P}$، $\\text{v}$ و $\\text{h}$ به ترتیب فشار، تندی و ارتفاع باشند، یکای عدد $500$ برحسب یکاهای اصلی SI کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:08:37', 5, 'done'),
(7095, '۱۰- داخل کره‌ای به شعاع $3\\text{cm}$، حفره‌ای کروی به شعاع $2\\text{cm}$ وجود دارد. وقتی حفره را از مایعی به چگالی $5/7 \\frac{\\text{g}}{\\text{cm}^3}$ پر کنیم، جرم کره ۴۰ درصد افزایش می‌یابد. چگالی ماده سازنده کره چند $\\frac{\\text{g}}{\\text{cm}^3}$ است؟ ($\\pi = 3$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:08:24', 5, 'done'),
(7096, '۱۱- نمودار جرم برحسب حجم یک مایع مطابق شکل زیر است. اگر یک ظرف استوانه‌ای به شعاع مقطع $10\\text{cm}$ و ارتفاع $24\\text{cm}$ را از این مایع پر کنیم، جرم مایع داخل ظرف چند $\\text{kg}$ خواهد شد؟ ($\\pi \\simeq 3$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-09-23 18:25:08', 4, 'done'),
(7097, '۱۲- کدام یک از تبدیل یکاهای زیر نادرست است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:08:06', 5, 'done'),
(7098, '۱۳- شکل زیر نشان‌دهنده یک ......................... است و دقت اندازه‌گیری آن ......................... دسی‌متر است.', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:57', 5, 'done'),
(7099, '۱۴- مطابق شکل‌های زیر در ظرف‌های استوانه‌ای جرم‌های مساوی از سه مایع مخلوط نشدنی $\\text{C}$، $\\text{D}$ و $\\text{E}$ ریخته‌ایم. اگر حجم یکسانی از این سه مایع را درون یک ظرف بریزیم نحوه قرارگیری مایع‌ها درون ظرف مطابق کدام شکل است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:51', 5, 'done'),
(7100, '۱۵- نمودار تغییرات جرم برحسب حجم برای دو جسم $\\text{A}$ و $\\text{B}$ مطابق شکل روبه‌رو است. اگر چگالی جسم $\\text{B}$ برابر $5 \\frac{\\text{g}}{\\text{cm}^3}$ باشد، مکعب تو‌پری از جسم $\\text{A}$ به جرم $500\\text{g}$، چه حجمی برحسب سانتی‌متر مکعب دارد؟', 1, 2, 75, 324, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:42', 5, 'done'),
(7101, '۱۶- مقادیر اندازه‌گیری شده توسط سه وسیله دیجیتالی $\\text{A}$، $\\text{B}$ و $\\text{C}$ برابر $6/460 \\times 10^3 \\text{dm}$، $5/3 \\times 10^4 \\mu\\text{m}$ و $8/7 \\times 10^{-3} \\text{hm}$ است. در این صورت، دقت اندازه‌گیری وسیله $\\text{A}$، ......................... برابر دقت اندازه‌گیری وسیله $\\text{B}$ و دقت اندازه‌گیری وسیله $\\text{C}$، ......................... برابر دقت اندازه‌گیری وسیله $\\text{B}$ است. (به ترتیب از راست به چپ)', 1, 2, 75, 323, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:33', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7102, '۱۷- از لوله مخزن نفت‌کش با شعاع مقطع $0/1\\text{m}$، نفت با آهنگ $21/6 \\times 10^8$ میلی‌متر مکعب بر دقیقه خارج می‌شود و به درون یک تانکر $36000$ لیتری کاملاً خالی وارد می‌شود. چند ثانیه طول می‌کشد تا این تانکر پر شود؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:25', 5, 'done'),
(7103, '۱۸- ظرفی به جرم $150$ گرم را روی ترازو قرار می‌دهیم. ظرف را یکبار از مایعی به چگالی $\\rho_1$ و بار دیگر از مایعی به چگالی $\\rho_2$ به طور کامل پر می‌کنیم. اگر عدد ترازو در دو حالت به ترتیب $0/65\\text{kg}$ و $0/9\\text{kg}$ باشد، نسبت $\\frac{\\rho_1}{\\rho_2}$ چقدر است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:18', 5, 'done'),
(7104, '۱۹- در مخلوط آب و $90\\text{g}$ یخ، پس از مدتی تمام یخ ذوب می‌شود. حجم مخلوط چگونه تغییر می‌کند؟ ($\\rho_{\\text{آب}} = 1 \\frac{\\text{g}}{\\text{cm}^3}$ و $\\rho_{\\text{یخ}} = 0/9 \\frac{\\text{g}}{\\text{cm}^3}$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:08', 5, 'done'),
(7105, '۲۰- جرم یکسانی از دو مایع $\\text{A}$ و $\\text{B}$ را درون دو ظرف خالی کاملاً مشابه می‌ریزیم، ۲۵ درصد از حجم مایع $\\text{A}$ و ۲۰ درصد از حجم مایع $\\text{B}$ از دو ظرف سرریز می‌شوند. اگر این دو مایع را با هم مخلوط کنیم، چگالی مخلوط چند برابر چگالی مایع $\\text{A}$ است؟ (در اثر مخلوط‌کردن دو مایع تغییر حجم نداریم.)', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:07:02', 5, 'done'),
(7106, '۲۱- کدام گزینه در مورد علم فیزیک، صحیح است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:54', 5, 'done'),
(7107, '۲۲- کدام‌یک از اعداد گزینه‌های زیر معادل بقیه نیست؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:47', 5, 'done'),
(7108, '۲۳- کمیت فرعی $\\text{X}$، در رابطه «$\\text{نیرو} = \\frac{\\text{X} \\times \\text{سطح}}{\\text{زمان}}$» صدق می‌کند. یکای کمیت $\\text{X}$ در SI کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:40', 5, 'done'),
(7109, '۲۴- یک کشتی مسافربری با تندی $160$ گره دریایی در حال حرکت است. این کشتی فاصله بین دو شهر را که $6000$ مایل است، در چند گیگا ثانیه طی می‌کند؟ (هر گره دریایی $0/5 \\frac{\\text{m}}{\\text{s}}$ و هر مایل در دریا برابر با $1800$ متر است.)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:32', 5, 'done'),
(7110, '۲۵- آلیاژی از دو فلز به چگالی‌های $\\rho_1 = 12 \\frac{\\text{g}}{\\text{cm}^3}$ و $\\rho_2 = 18 \\frac{\\text{g}}{\\text{cm}^3}$ ساخته شده است. اگر چگالی این آلیاژ $13/5 \\frac{\\text{g}}{\\text{cm}^3}$ و حجم آن $200\\text{cm}^3$ باشد، چه کسری از جرم آلیاژ از فلز $\\rho_1$ ساخته شده است؟ (تغییر حجم نداریم.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:27', 5, 'done'),
(7111, '۲۶- در سقوط آزاد سنگ و سقوط آزاد یک برگ کاغذ، نیروی مقاومت هوا .........................', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:19', 5, 'done'),
(7112, '۲۷- کار یک کمیت ......................... است و یکای آن برحسب یکاهای اصلی در SI، ......................... است.', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:11', 5, 'done'),
(7113, '۲۸- در مدت ۲۰ دقیقه، ۶ سانتی‌متر از طول یک نخ می‌سوزد. آهنگ سوختن نخ برحسب میکرومتر بر میلی‌ثانیه کدام است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:06:02', 5, 'done'),
(7114, ' در شکل‌های زیر، دقت اندازه‌گیری ابزارهای اندازه‌گیری (الف، (ب) و (پ)، به ترتیب از راست به چپ کدام است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:05:56', 5, 'done'),
(7115, ' درون ظرفی با گنجایش $1\\text{L}$ مقدار $980\\text{cm}^3$ آب وجود دارد. اگر قطعه توپر فلزی با چگالی $4 \\frac{\\text{g}}{\\text{cm}^3}$ را به طور کامل درون آن ظرف فرو ببریم، $20\\text{cm}^3$ آب از ظرف سرریز می‌شود. جرم قطعه فلز چند گرم است؟ ($\\rho_{\\text{آب}} = 1 \\frac{\\text{g}}{\\text{cm}^3}$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:05:47', 5, 'done'),
(7116, ' نمودار تغییرات جرم برحسب حجم برای دو جسم $\\text{A}$ و $\\text{B}$ مطابق شکل زیر است. اگر چگالی جسم $\\text{A}$ برابر $15 \\frac{\\text{g}}{\\text{cm}^3}$ باشد، حجم شمشی از جنس $\\text{B}$ به جرم $2250\\text{g}$ چند $\\text{cm}^3$ است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:04:33', 5, 'done'),
(7117, ' $m_1$ گرم از ماده $\\text{A}$ را با $m_2$ گرم از ماده $\\text{B}$ به گونه‌ای مخلوط می‌کنیم که چگالی مخلوط ۴ گرم بر سانتی‌متر مکعب شود. اگر چگالی ماده $\\text{A}$ برابر $3 \\frac{\\text{g}}{\\text{cm}^3}$ و چگالی ماده $\\text{B}$ برابر $7 \\frac{\\text{g}}{\\text{cm}^3}$ باشد، آن‌گاه حاصل $\\frac{m_2}{m_1}$ کدام است؟ (مخلوط کردن دو ماده $\\text{A}$ و $\\text{B}$ باعث تغییر حجم آن‌ها نمی‌شود.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:04:23', 5, 'done'),
(7118, ' دو کره همگن $\\text{A}$ و $\\text{B}$ دارای جرم‌های یکسان هستند. کره $\\text{A}$ توپر و کره $\\text{B}$ توخالی است. اگر شعاع خارجی دو کره برابر باشد و شعاع داخلی کره $\\text{B}$، $\\frac{1}{3}$ شعاع خارجی آن باشد، چگالی ماده سازنده کره $\\text{A}$ چند برابر چگالی ماده سازنده کره $\\text{B}$ است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:04:14', 5, 'done'),
(7119, '۳۴- دو قطعه فلزی $\\text{A}$ و $\\text{B}$ با حجم ظاهری یکسان در اختیار داریم که یکی توپر و دیگری دارای حفره است. اگر جرم و چگالی ماده سازنده قطعه $\\text{A}$ به ترتیب $\\frac{2}{3}$ و ۲ برابر جرم و چگالی ماده سازنده قطعه $\\text{B}$ باشد، در کدام قطعه حفره وجود دارد و حجم این حفره چند برابر حجم ماده سازنده آن قطعه است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:04:06', 5, 'done'),
(7120, ' در کدام‌یک از موارد زیر، همه کمیت‌ها فرعی هستند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:03:58', 5, 'done'),
(7121, ' جرم یک قطعه سنگ قیمتی ۲۰۰ قیراط و هر قیراط معادل ۲۰۰ میلی‌گرم است. جرم این سنگ چند گرم است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:03:50', 5, 'done'),
(7122, 'مقدار $0/0012\\text{ng} \\cdot \\frac{\\text{mm}^2}{\\mu\\text{s}^3}$ را با استفاده از تبدیل یکا و برحسب نمادگذاری علمی می‌توان به صورت $a \\times 10^b \\text{kg} \\cdot \\frac{\\mu\\text{m}^2}{\\text{ns}^3}$ نوشت. در این صورت، حاصل $a+b$ کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:03:41', 5, 'done'),
(7123, ' کدام‌یک از گزینه‌های زیر صحیح است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:30', 1, '2026-03-26 21:03:33', 5, 'done'),
(7124, ' در شکل‌های (الف) و (ب)، دقت اندازه‌گیری‌ها به ترتیب ......................... است و خط‌کش ......................... دقیق‌تر است.', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:03:26', 5, 'done'),
(7125, ' با هدف کاهش خطا در اندازه‌گیری جرم، یک دانش‌آموز جرم یک جسم را ۸ بار توسط یک ترازوی دیجیتال (رقمی) با دقت $0/1$ گرم، اندازه گرفته و نتایج را در جدول زیر ثبت نموده است. جرم این جسم چند گرم است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:03:19', 5, 'done'),
(7126, '۴۲- معادله مسافت طی شده توسط یک خودرو در SI به صورت $\\text{d} = \\text{Av}^2 + \\text{BF}$ است. اگر $\\text{v}$ و $\\text{F}$ به ترتیب تندی خودرو و نیروی خالص وارده بر خودرو باشند، یکاهای کمیت‌های $\\text{A}$ و $\\text{B}$ در SI به ترتیب از راست به چپ کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:03:09', 5, 'done'),
(7127, ' ارتفاع یک مخروط توپر به چگالی $\\rho_1$ برابر طول ضلع یک مکعب توپر به چگالی $\\rho_2$ است. اگر شعاع قاعده مخروط، نصف طول ضلع مکعب و جرم این دو با هم برابر باشد، $\\frac{\\rho_1}{\\rho_2}$ کدام است؟ ($\\pi \\simeq 3$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:03:00', 5, 'done'),
(7128, ' جرم یک ظرف فلزی توخالی ۳۰۰ گرم است. اگر این ظرف را پر از مایعی به چگالی $1/2 \\text{g/cm}^3$ نماییم، جرم مجموعه ۵۴۰ گرم و در صورتی که پر از نوعی روغن نماییم، جرم مجموعه ۴۶۰ گرم می‌شود. چگالی این روغن چند گرم بر لیتر است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:53', 5, 'done'),
(7129, ' جواهرفروشی در ساختن یک قطعه جواهر به جای طلای خالص، مقداری نقره نیز به کار برده است. اگر حجم قطعه ساخته شده، ۵ سانتی‌متر مکعب و چگالی آن $13/6 \\text{g/cm}^3$ باشد، جرم نقره به کار رفته، چند گرم است؟ (چگالی نقره و طلا به ترتیب $10 \\text{g/cm}^3$ و $19 \\text{g/cm}^3$ فرض شود.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:43', 5, 'done'),
(7130, ' در کدام گزینه همه کمیت‌ها، اصلی هستند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:35', 5, 'done'),
(7131, ' مخزن مکعب‌شکلی به حجم $216 \\text{m}^3$، توسط شیر $\\text{A}$، از یک مایع پر می‌شود. اگر آهنگ تغییر ارتفاع مایع مخزن $0/05$ دسی‌متر بر دقیقه باشد، آهنگ خروج مایع از شیر $\\text{A}$ چند کیلوگرم بر ثانیه است؟ ($\\rho_{\\text{مایع}} = 1/5 \\frac{\\text{g}}{\\text{cm}^3}$)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:27', 5, 'done'),
(7132, ' اگر یک بطری خالی را با آب پر کنیم، جرم بطری و آب داخل آن $300\\text{g}$ است و چنان‌چه همان بطری را با روغن پر کنیم، جرم بطری و روغن داخل آن $280\\text{g}$ می‌شود. جرم بطری خالی چند گرم است؟ ($\\rho_{\\text{آب}} = 1 \\frac{\\text{g}}{\\text{cm}^3}$ و $\\rho_{\\text{روغن}} = 0/8 \\frac{\\text{g}}{\\text{cm}^3}$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:20', 5, 'done'),
(7133, ' حاصل $2 \\frac{\\text{J} \\cdot \\text{ms}^2}{\\text{g} \\cdot \\mu\\text{m}}$ مطابق کدام گزینه است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:13', 5, 'done'),
(7134, ' حجم ظرف استوانه‌ای شکلی که مساحت قاعده آن $0/04 \\text{m}^2$ است، برابر $25/4 \\text{L}$ می‌باشد. ارتفاع این ظرف چند اینچ است؟ (هر اینچ برابر $2/54$ سانتی‌متر است)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:02:02', 5, 'done'),
(7135, ' جرم یک کره توپر به شعاع $\\text{r}$، با جرم یک استوانه حفره‌دار که ارتفاع و شعاع قاعده آن نیز هر کدام برابر $\\text{r}$ است، یکسان می‌باشد. اگر چگالی ماده‌ای که کره از آن ساخته شده، $\\frac{2}{3}$ برابر چگالی ماده‌ای باشد که استوانه از آن ساخته شده است، حجم حفره چه کسری از حجم ظاهری استوانه است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:55', 5, 'done'),
(7136, ' یکای فرعی و یکای SI کمیت نیرو به ترتیب از راست به چپ کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:47', 5, 'done'),
(7137, ' شکل (الف) صفحه نمایش یک کولیس رقمی و شکل (ب) یک خط‌کش مدرج را نشان می‌دهد. دقت کولیس و خط‌کش برحسب سانتی‌متر به ترتیب کدام است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:39', 5, 'done'),
(7138, ' مخلوطی از آب و یخ به حجم $150 \\text{cm}^3$ در اختیار داریم. اگر تمام آب موجود در مخلوط یخ بزند، حجم مخلوط به $160 \\text{cm}^3$ خواهد رسید. جرم اولیه یخ چند گرم بوده است؟ ($\\rho_{\\text{یخ}} = 0/9 \\frac{\\text{g}}{\\text{cm}^3} ، \\rho_{\\text{آب}} = 1 \\frac{\\text{g}}{\\text{cm}^3}$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:32', 5, 'done'),
(7139, ' درون مکعبی به جرم $900$ گرم و چگالی ماده سازنده $9 \\frac{\\text{g}}{\\text{cm}^3}$ که طول هر ضلع آن $5\\text{cm}$ است، حفره‌ای وجود دارد. حداکثر چند گرم از یک مایع به چگالی $2 \\frac{\\text{g}}{\\text{cm}^3}$ را می‌توان درون این حفره ریخت؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:22', 5, 'done'),
(7140, ' اگر هر فرسنگ ۶۰۰۰ ذرع و هر ذرع ۱۰۴ سانتی‌متر باشد، ۳۱۲ کیلومتر چند فرسنگ است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:13', 5, 'done'),
(7141, ' شیر $\\text{A}$ یک استخر خالی به حجم ۱۵۰۰ مترمکعب را در مدت زمان ۳۰ ساعت پر می‌کند. اگر پس از پر شدن $\\frac{1}{3}$ حجم استخر توسط شیر $\\text{A}$، شیر $\\text{B}$ را هم باز کنیم، استخر ۱۵ ساعت دیگر پر می‌شود. آهنگ خروج آب از شیر $\\text{B}$ برحسب یکای لیتر بر دقیقه کدام است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:08', 5, 'done'),
(7142, ' مطابق شکل زیر، درون یک استوانه توخالی تا ارتفاع $10\\text{cm}$ از مایعی به چگالی $5 \\frac{\\text{g}}{\\text{cm}^3}$ می‌ریزیم. اگر $\\frac{4}{5}$ از حجم مایع درون ظرف را خالی کنیم، مجموع جرم ظرف و مایع درون آن، نصف می‌شود، جرم ظرف چند گرم است؟ ($\\pi \\simeq 3$)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:01:01', 5, 'done'),
(7143, ' حاصل کمیت $A = 10^{28} \\frac{\\text{ng.cm}^2}{\\text{Ts}^2}$ مطابق کدام گزینه است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:00:53', 5, 'done'),
(7144, ' دو ظرف مشابه را جداگانه از مایع‌های A و B پر کرده‌ایم. درون مایع A یک گلوله آلومینیمی توپر به جرم $m$ و درون مایع B یک گلوله آلومینیمی توپر دیگر به جرم $\\frac{1}{4} m$ می‌اندازیم. جرم بیرون‌ریخته شده از مایع A، دو برابر جرم بیرون‌ریخته شده از مایع B خواهد بود. اگر جرم مساوی از این دو مایع را با یکدیگر مخلوط کنیم، چگالی مخلوط این دو مایع چند برابر چگالی مایع A است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:00:45', 5, 'done'),
(7145, ' درون کره‌ای آهنی به چگالی $8 \\frac{\\text{g}}{\\text{cm}^3}$، حفره‌ای به حجم $200 \\text{cm}^3$ وجود دارد. اگر این کره را درون ظرفی که از الکل پر شده است، فرو ببریم، $800 \\text{g}$ الکل از ظرف سرریز می‌شود. جرم کره آهنی چند کیلوگرم است؟ (چگالی الکل $0/8 \\frac{\\text{g}}{\\text{cm}^3}$ است و مایع به درون حفره کره وارد نمی‌شود.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:00:38', 5, 'done'),
(7146, '۶۲- فشار وارد بر سطحی به‌صورت $9 \\times 10^9 \\frac{\\text{mg}}{(\\text{mm})(\\text{ms})^2}$ بیان شده است. مقدار این فشار در SI برابر چند پاسکال است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:00:30', 5, 'done'),
(7147, ' سال نوری (Ly) تقریباً برابر با ................... است. (تندی نور در خلأ $3 \\times 10^8$ متر بر ثانیه و یکسال تقریباً برابر با $3 \\times 10^7$ ثانیه است.)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:00:23', 5, 'done'),
(7148, ' شکل (الف) یک خط‌کش مدرج و شکل (ب) صفحه نمایش یک کولیس رقمی است. به ترتیب از راست به چپ، دقت خط‌کش مدرج و کولیس رقمی چند میلی‌متر است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 21:00:04', 5, 'done'),
(7149, ' گلوله فلزی تو‌پری به جرم ۱۶۰ گرم را به ترتیب در دو ظرف پر از آب و الکل می‌اندازیم. اگر اختلاف جرم مایعات بیرون‌ریخته شده از ظرف‌ها ۲۰ گرم باشد، چگالی گلوله چند کیلوگرم بر لیتر است؟ (چگالی آب $1 \\frac{\\text{g}}{\\text{cm}^3}$ و چگالی الکل $0/8 \\frac{\\text{g}}{\\text{cm}^3}$ است.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:52', 5, 'done'),
(7150, ' کدام‌یک از کمیت‌های زیر هم از نظر «اصلی یا فرعی» بودن و هم از نظر «نرده‌ای یا برداری» بودن با کمیت «تندی» متفاوت است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:43', 5, 'done'),
(7151, ' در رابطه $x = aA^2 + AB$، نماد $x$ کمیت جابه‌جایی و $a$ نماد کمیت شتاب است. به ترتیب A و B کدام‌یک از کمیت‌های زیر می‌توانند باشند؟ [تمامی کمیت‌ها برحسب یکای SI هستند.]', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:36', 5, 'done'),
(7152, '۶۸- کدام‌یک از گزینه‌های زیر را در جای خالی قرار دهیم تا تساوی برقرار شود؟\r\n\r\n$2/5 \\times 10^5 \\frac{\\mu\\text{J}}{\\text{ns}} = \\dots\\dots \\frac{\\text{mm}^2}{\\mu\\text{s}^3}$', 1, 2, 75, 322, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:30', 5, 'done'),
(7153, ' جرم جسمی ۴۸۰ گندم و ۵ سیر است. جرم این جسم چند گرم است؟ ($4/6 \\text{g} = 1 \\text{مثقال}$ ، $1 \\text{سیر} = 16 \\text{مثقال}$ ، $1 \\text{مثقال} = 96 \\text{گندم}$ است.)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:19', 5, 'done'),
(7154, ' ۲ لیتر آب را با چند کیلوگرم الکل مخلوط کنیم تا چگالی مخلوط ۸۵۰ گرم بر لیتر شود؟ ($\\rho_{\\text{آب}} = 1 \\frac{\\text{kg}}{\\text{L}}$ و $\\rho_{\\text{الکل}} = 0/8 \\frac{\\text{kg}}{\\text{L}}$ و از تغییر حجم مخلوط در اثر ترکیب دو مایع صرف‌نظر شود.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:11', 5, 'done'),
(7155, '۷۲- چگالی ماده A، ۲۰ درصد بیشتر از چگالی ماده B است. کره‌ای به شعاع R از جنس ماده A و استوانه‌ای به شعاع سطح مقطع R و ارتفاع $\\frac{1}{2} R$ از جنس ماده B در اختیار داریم که جرم یکسانی دارند و یکی از آنها حتماً توپر است. کدام گزینه در مورد کره و استوانه درست است؟', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:59:02', 5, 'done'),
(7156, ' نمودار جرم برحسب حجم برای دو مایع A و B، مطابق شکل زیر است. اگر جرم مساوی از این دو مایع را با یکدیگر مخلوط کنیم، چگالی مخلوط حاصل، چند برابر چگالی مایع B خواهد شد؟ (در اثر مخلوط شدن دو مایع تغییر حجم ناچیز است.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:58:56', 5, 'done'),
(7157, ' دقت یک خط‌کش مدرج $1 \\text{mm}$ و یک کولیس رقمی $0/1 \\text{mm}$ است. به ترتیب کدام‌یک از طول‌های زیر توسط این خط‌کش و کولیس اندازه‌گیری شده‌اند؟', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:58:48', 5, 'done'),
(7158, ' ۲۰۰۰ میکروگرم از مایع A، $80 \\text{mm}^3$ فضا اشغال می‌کند و $40 \\mu\\text{L}$ از مایع B، $50 \\text{mg}$ جرم دارد. اگر چگالی ماده C برابر $2 \\frac{\\text{Mg}}{\\text{m}^3}$ باشد و بخواهیم حجم برابر از این سه مایع را درون ظرفی بریزیم، کدام گزینه ترتیب قرارگیری مایع‌ها را در ظرف به‌درستی نشان می‌دهد؟ (۳ مایع مخلوط‌نشدنی هستند.)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:58:38', 5, 'done'),
(7159, ' یک گلوله تفنگ با تندی زیاد و در راستای افقی، از دهانه تفنگی شلیک می‌شود و بر دیوار مقابل در فاصله ۵ متری تفنگ برخورد می‌کند. کدام‌یک از عبارت‌های زیر در مدل‌سازی حرکت این گلوله، نادرست است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:58:26', 5, 'done'),
(7160, ' چه تعداد از گزاره‌های زیر درست هستند؟\n\nالف) مدل‌ها و نظریه‌های فیزیکی در طول زمان همواره معتبر هستند.\n\nب) ویژگی آزمون‌پذیری و اصلاح نظریه‌های فیزیکی، نقطه قوت دانش فیزیک است.\n\nج) در هنگام مدل‌سازی یک پدیده فیزیکی باید اثرهای کلی را نادیده بگیریم تا مسئله ساده و آرمانی گردد.', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:58:18', 5, 'done'),
(7161, '۷۸- مصرف بنزین یک خودروی سواری در شرایط جاده‌ای هموار، ثابت و برابر $15 \\frac{\\text{km}}{\\text{L}}$ است. اگر در جاده هموار زیر در نقطه A در داخل باک این اتومبیل، ۶ گالن بنزین وجود داشته باشد، این اتومبیل بعد از شروع از نقطه A، در کدام نقطه متوقف می‌شود؟ (اتومبیل فقط به سمت راست حرکت کرده و برنمی‌گردد؛ در ضمن هر گالن را برابر $4/5$ لیتر و هر مایل (mile) را برابر با $1/5 \\text{km}$ در نظر بگیرید.)', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:58:09', 5, 'done'),
(7162, ' در تندی‌سنج شکل زیر، نسبت دقت شمارنده (۱) به دقت شمارنده (۲) کدام است؟ (mph مخفف «مایل بر ساعت» و هر مایل تقریباً ۱۸۰۰ متر است.)', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:57:55', 5, 'done'),
(7163, ' دو مکعب فلزی با اضلاع خارجی برابر در اختیار داریم. حفره‌ای کروی درون مکعب اول به‌گونه‌ای قرار دارد که شعاع حفره کروی با طول ضلع حفره مکعبی درون مکعب دوم برابر و هر دو نصف طول ضلع بیرون مکعب‌ها هستند. اگر چگالی ماده سازنده مکعب اول نصف چگالی ماده سازنده مکعب دوم باشد، جرم مکعب دوم چند برابر جرم مکعب اول است؟ ($\\pi = 3$)', 1, 2, 75, 324, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:57:48', 5, 'done'),
(7164, ' یکی از بزرگ‌ترین الماس‌های موجود در ایران، دریای نور به جرم ۱۸۲ قیراط است. جرم این الماس در SI چقدر است؟ (هر قیراط معادل ۲۰۰ میلی‌گرم است.)', 1, 2, 75, 322, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:57:37', 5, 'done'),
(7165, '82- یکای فرعی فشار کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:57:18', 5, 'done'),
(7166, 'بزار زیر یک وسیلهٔ اندازه‌گیری طول است. این وسیله چه نام دارد و دقت اندازه‌گیری آن کدام است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:57:10', 5, 'done'),
(7167, ' جواهرفروشی در ساختن یک قطعه جواهر به‌جای طلای خالص، مقداری نقره به‌کار برده است. اگر حجم قطعهٔ ساخته شده، $5$ سانتی‌متر مکعب و چگالی آن $13/6 \\frac{g}{cm^3}$ باشد، جرم نقرهٔ به‌کار رفته، چند گرم است؟ (چگالی نقره و طلا به ترتیب $10 \\frac{g}{cm^3}$ و $19 \\frac{g}{cm^3}$ فرض شود و تغییر حجم نداریم.)', 1, 2, 75, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:59', 5, 'done'),
(7168, '85- در یک آزمایش، جرم و حجم یک جسم جامد را مطابق شکل زیر، پیدا می‌کنیم. با توجه به داده‌های روی شکل، چگالی جسم در SI چقدر است؟\r\n\r\n$11/5 g$\r\n\r\n$18/5 mL$\r\n\r\n$23/1 mL$', 1, 2, 75, 324, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:52', 5, 'done'),
(7169, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ) یکای نجومی و سال نوری به ترتیب از جنس کمیت‌های طول و زمان هستند.\n\nب) در فیزیک به هر چیزی که بتوان آن را اندازه گرفت، کمیت فیزیکی گفته می‌شود.\n\nپ) تمام کمیت‌هایی که با یکاهای اصلی بیان می‌شوند، نرده‌ای هستند.\n\nت) بار الکتریکی یک جسم و شدت روشنایی جزو کمیت‌های اصلی هستند.', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:42', 5, 'done'),
(7170, '87- معادله مکان متحرکی در SI به صورت $x = \\frac{1}{2} AFa + Bva$ است. اگر F، a و v به ترتیب نیروی خالص وارد بر متحرک، شتاب و تندی متحرک باشد، یکای کمیت‌های A و B در SI به ترتیب از راست به چپ کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:34', 5, 'done'),
(7171, ' در مخزن شکل مقابل به ابعاد $5m \\times 4m \\times 3m$، آهنگ ورود و خروج آب از لوله‌های ورودی و خروجی مخزن به ترتیب $720$ دسی‌متر مکعب بر دقیقه و $6 \\times 10^6$ میلی‌متر مکعب بر ثانیه است. اگر در ابتدا مخزن خالی باشد، پس از چند ثانیه، مخزن به‌طور کامل پر می‌شود؟ (فاصلهٔ لولهٔ خروجی از کف مخزن ۳ متر است.)\n\nلوله ورودی\n\n$3m$\n\n$4m$\n\n$5m$\n\nلوله خروجی', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:26', 5, 'done'),
(7172, '89- در یک آزمایش، برای اندازه‌گیری جرم یک تلفن همراه که توسط یک دانش‌آموز با استفاده از یک ابزار دیجیتال انجام شده، مقادیر زیر برحسب گرم به‌دست آمده است:\r\n\r\n$96/9$ و $80/5$ و $97/7$ و $98/1$ و $97/3$\r\n\r\nدقت اندازه‌گیری برحسب کیلوگرم چقدر است و کدام مقدار به‌عنوان جرم تلفن همراه، گزارش می‌شود؟', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:08', 5, 'done'),
(7173, ' طول اندازه‌گیری شدۀ یک جسم توسط یک ابزار دقیق اندازه‌گیری دیجیتال به‌صورت $41/0004 mm$ گزارش شده است. دقت اندازه‌گیری این ابزار، چند نانومتر است؟', 1, 2, 75, 323, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:56:02', 5, 'done'),
(7174, ' اگر $A = 10^{-3} \\frac{N.ms}{\\mu g}$ باشد، در این صورت، A کمیتی ........................ و مقدار آن برحسب یکای SI برابر با ........................ است.', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:55:54', 5, 'done'),
(7175, ' کدام گزینه درست است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:49:23', 5, 'done'),
(7176, ' جرم یک زنبور عسل $0/00015 kg$ است. اگر جرم این زنبور برحسب میکروگرم و نمادگذاری علمی به‌صورت $a \\times 10^b \\mu g$ بیان شود، حاصل a+b کدام است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:49:14', 5, 'done'),
(7177, '94- در رابطه $A = BC + B^2E$، اگر A کمیت آهنگ مصرف انرژی و B کمیت سرعت در SI باشد، در این صورت یکای C و E به ترتیب از راست به چپ در SI کدام‌اند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:48:54', 5, 'done'),
(7178, ' بی‌تو یو بر ساعت $(\\frac{btu}{h})$ در دستگاه‌های تهویه مطبوع یکای واحد تولید انرژی در واحد زمان می‌باشد. توان تولیدی یک دستگاه کولر گازی برابر با $18000 \\frac{btu}{h}$ می‌باشد. این یکا برحسب میلی‌ژول بر میکروثانیه کدام است؟ $(1 btu = 250 cal , 1 cal = 4/2 J)$', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:48:43', 5, 'done'),
(7179, ' یکای کدام‌یک از کمیت‌های زیر برحسب یکاهای اصلی $\\frac{kg.m^2}{A.s^2}$ است؟', 1, 2, 75, 321, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:48:31', 5, 'done'),
(7180, ' مقدار $0/00024 \\mu N.Tm$ برحسب $\\frac{Mg.mm^2}{ns^2}$ کدام است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:48:21', 5, 'done'),
(7181, '98- اگر نوعی جلبک در استخری با آهنگ $2 \\frac{cm}{day}$ رشد کند و بعد از گذشت هر روز، سرعت رشدش ۲ برابر شود، آهنگ رشد آن در روز هفتم چند میلی‌متر بر میکروساعت است؟', 1, 2, 75, 322, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:49:04', 5, 'done'),
(7182, '99- شکل‌های (الف) و (ب) اعدادی است که به ترتیب یک ریزسنج و یک کولیس رقمی در اندازه‌گیری دو جسم، نشان می‌دهند. دقت ابزارهای (الف) و (ب) به ترتیب از راست به چپ برابر با چند میلی‌متر است؟\r\n\r\n(الف) $20/083 mm$\r\n\r\n(ب) $16/67 mm$', 1, 2, 75, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:48:10', 5, 'done'),
(7183, '100- یکای نجومی (Au) و سال نوری (Ly) به ترتیب از چپ به راست از جنس کدام کمیت‌ها هستند؟', 1, 2, 75, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:31', 1, '2026-03-26 20:47:58', 5, 'done'),
(7184, '1- کدامیک از عبارت‌های زیر درست است؟', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:47:47', 5, 'done'),
(7185, ' دو کره $A$ و $B$ با شعاع‌های مختلف در یک محیط مایع شناورند. شعاع کره $A$ برابر $8$ و شعاع کره $B$ برابر $12$ است. اگر جرم مخصوص مایع $ρ$ باشد، فشار وارد بر نقاطی از سطح کره $B$ نسبت به سطح کره $A$ چند برابر است؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:47:32', 5, 'done'),
(7186, ' تغییرات فشار نسبت به عمق برای یک سیال در شکل نشان داده شده است. اگر عمق استوانه‌ای از آب $4 \\, cm$ باشد، اختلاف فشار در کف و سطح چقدر است؟ ($g = 10 \\, N/kg$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:47:05', 5, 'done'),
(7187, ' فشار هوا در ارتفاع‌های مختلف نسبت به سطح زمین چگونه تغییر می‌کند؟ (چگالی هوا $ρ$ و شتاب گرانش $g = 10 \\, N/kg$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:46:54', 5, 'done'),
(7188, ' در یکی از شاخه‌های لوله مقداری جیوه قرار دارد. در یکی از شاخه‌های لوله فشار آب می‌ریزیم تا ارتفاع آن ۳۴ cm شود. اختلاف ارتفاع جیوه در دو شاخه چند سانتی‌متر می‌شود؟ (چگالی جیوه و آب به ترتیب $13.6 \\, g/cm^3$ و $1 \\, g/cm^3$ است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:46:46', 5, 'done'),
(7189, ' در شکل زیر استوانه‌ای پر از آب و روغن نشان داده شده است. اگر حجم مساوی از مایع موجود در لوله در شاخه راست بریزیم، در شاخه سمت چپ $3 \\, cm$ مایع بالا می‌آید. چگالی مایع اضافه‌شده چند گرم بر سانتی‌متر مکعب است؟ (سطح مقطع شاخه سمت راست $3$ برابر سطح مقطع شاخه سمت چپ است. $g = 10 \\, m/s^2$، چگالی آب و روغن به ترتیب $1 \\, g/cm^3$ و $0.8 \\, g/cm^3$ است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:46:40', 5, 'done'),
(7190, ' در شکل زیر فشار پیمانه‌ای گاز محبوس در لوله $48 \\, cmHg$ است. چگالی مایع چند واحد SI است؟ (چگالی جیوه $13.6 \\, g/cm^3$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:46:29', 5, 'done'),
(7191, ' در شکل زیر، بارومتر (جیوسنج) جیوه‌ای در سطح تراز دریا قرار دارد. اگر در همین شرایط به جای جیوه از مایعی با چگالی $\\frac{1}{5}$ چگالی جیوه استفاده شود، فشار در انتهای بسته لوله چند کیلوپاسکال تغییر می‌کند؟ ($g = 10 \\, N/kg$، $ρ_{Hg} = 13600 \\, kg/m^3$، $P_0 = 75 \\, cmHg$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:46:19', 5, 'done'),
(7192, ' در شکل روبه‌رو لوله‌ای نشان داده شده است که حاوی حجم مساوی از آب و روغن است. فشار پیمانه‌ای هوای درون دهان شخص چند کیلوپاسکال است؟ ($g = 10 \\, m/s^2$، چگالی آب و روغن به ترتیب $1 \\, g/cm^3$ و $0.8 \\, g/cm^3$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:46:08', 5, 'done'),
(7193, ' در شکل زیر، اگر فشار پیمانه‌ای مخزن $A$ ۵ برابر فشار پیمانه‌ای مخزن $B$ باشد، نسبت $\\frac{h_2}{h_1}$ کدام است؟', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:45:59', 5, 'done'),
(7194, ' در شکل (۱) جسم درون مایعی به چگالی $ρ_1$ غوطه‌ور است و در شکل (۲) همان جسم درون مایعی به چگالی $ρ_2$ قرار دارد. اگر $ρ_1 > ρ_2$ باشد، نیروی شناوری وارد بر جسم در این دو شکل به‌ترتیب $F_1$ و $F_2$ است. کدام مقایسه درست است؟', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:45:52', 5, 'done'),
(7195, '15- بادکنکی از هوا پر شده روی زمین در ترازو حساس قرار داده شده و وزن آن $0.2 \\, N$ نشان می‌دهد. کدام گزاره زیر درست است؟ ( $g = 10 \\, N/kg$ و فشار هوای محیط در اطراف بادکنک یکسان است.)', 1, 2, 76, 323, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:06:47', 1, '2026-03-26 20:45:45', 5, 'done'),
(7196, ' کدام‌یک از عبارت‌های زیر دربارۀ پلاسما نادرست است؟\n\nالف) اغلب در دماهای بسیار زیاد ایجاد می‌شود.\n\nب) مادۀ درون ستارگان از پلاسما تشکیل شده است.\n\nپ) بخش اندکی از فضای بین ستاره‌ای از پلاسما تشکیل شده است.\n\nت) اکثر سیارات از پلاسما ساخته شده‌اند.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:04', 1, '2026-03-26 20:45:35', 5, 'done'),
(7197, ' شکل مقابل خروج قطره‌های روغن را از دهانۀ قطره‌چکانی نشان می‌دهد. با افزایش دمای روغن، قطره‌ها .............................. می‌شوند چون افزایش دما، نیروی هم‌چسبی مولکول‌های مایع را ......................... می‌دهد.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:45:28', 5, 'done'),
(7198, ' مطابق شکل زیر، جرم m و 8m از دو مایع مختلف را به‌ترتیب درون دو ظرف مکعب شکل A و B می‌ریزیم. اگر فشار پیمانه‌ای حاصل از مایع در کف ظرف‌ها با یکدیگر برابر باشد، حجم ظرف B چند برابر حجم ظرف A است؟ (ظرف‌ها در ابتدا خالی هستند.)', 1, 2, 76, 326, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:45:22', 5, 'done'),
(7199, ' با توجه به شکل زیر، کدام گزینه در مورد مقایسۀ چگالی اجسام با هم درست است؟', 1, 2, 76, 324, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:45:11', 5, 'done'),
(7200, ' در یک ظرف استوانه‌ای مقداری آب به جرم m و مقداری جیوه به جرم 5m ریخته شده است. جمع ارتفاع این دو مایع 74cm است. چند سانتی‌متر جیوه به‌درون ظرف اضافه کنیم تا فشار در ته ظرف ده درصد افزایش یابد؟ $(P_{\\circ} = 76 cmHg , \\rho_{Hg} = 13/5 \\frac{g}{cm^3} , \\rho_{water} = 1 \\frac{g}{cm^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:45:02', 5, 'done'),
(7201, ' در شکل مقابل آب و جیوه در حال تعادل‌اند، فشار هوای حبس شده در محفظه چند cmHg است؟ $(\\rho_{water} = 1 \\frac{g}{cm^3} , \\rho_{Hg} = 13/6 \\frac{g}{cm^3} , P_{\\circ} = 76 cmHg)$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:44:55', 5, 'done'),
(7202, '7- مطابق شکل زیر، در یک لوله Uشکل مایعی با چگالی $6\\frac{g}{cm^3}$ در حال تعادل است. به شاخه سمت راست، مایعی مخلوط نشدنی با چگالی $3\\frac{g}{cm^3}$ اضافه می‌کنیم تا کاملاً پر شود. پس از برقراری تعادل، اختلاف سطح مایع‌ها در دو شاخه چند سانتی‌متر خواهد شد؟ (مساحت سطح مقطع شاخه‌های سمت راست و چپ به ترتیب $4cm^2$ و $2cm^2$ است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:44:39', 5, 'done'),
(7203, ' در لوله افقی زیر، جریان آب با تندی $2/5\\frac{cm}{s}$ و v به ترتیب در قسمت باریک با قطر 4cm و قسمت پهن‌تر با شعاع $r\'$ در جریان است. اگر یک ذره فاصله MN را در مدت $137s$ بپیماید، $r\'$ چند سانتی‌متر است؟ (جریان را در هر قسمت لایه‌ای فرض کنید.)', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:44:31', 5, 'done'),
(7204, ' در شکل زیر، فشار نقطه B، $1/7$ برابر فشار نقطه A است. فشار هوای محیط چند سانتی‌متر جیوه است؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:44:19', 5, 'done'),
(7205, '10- مطابق شکل زیر، جرم یکسانی از مایع‌های A و B را در یک ظرف می‌ریزیم و در این حالت برآیند نیرویی که از طرف دو مایع به جداره‌های ظرف وارد می‌شود برابر F و فشار ناشی از دو مایع در کف ظرف برابر P است. اگر دو مایع را با هم مخلوط کنیم تا مخلوطی همگن تشکیل شود، در این حالت نیرویی که مایع به جداره ظرف وارد می‌کند برابر $F\'$ و فشار مایع جدید در کف ظرف برابر $P\'$ است. کدام گزینه در مورد مقایسه آن‌ها صحیح است؟ (حین مخلوط کردن دو مایع تغییر حجم نداریم.)', 1, 2, 76, 327, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:44:13', 5, 'done'),
(7206, '11- اگر یک لوله مویین را که دو طرف آن باز است به‌طور قائم در جیوه فرو ببریم، به صورت کدام‌یک از شکل‌های زیر در می‌آید؟', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:44:01', 5, 'done'),
(7207, '12- ابعاد ظرف استوانه‌ای B، دو برابر ابعاد ظرف استوانه‌ای A است. ظرف A را پر از آب می‌کنیم و هم‌جرم با آب در استوانه B جیوه می‌ریزیم. فشاری که آب بر کف ظرف A وارد می‌کند، چند برابر فشاری است که جیوه بر کف ظرف B، وارد می‌کند؟ $(\\rho_{water} = 13/6 \\rho_{Hg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:43:53', 5, 'done'),
(7208, ' در یک لوله استوانه‌ای که مساحت قاعده آن $5cm^2$ است، $136$ گرم جیوه و $136$ گرم آب می‌ریزیم. اگر چگالی جیوه و چگالی آب به‌ترتیب $13/6g/cm^3$ و $1g/cm^3$ باشد، فشار در ته لوله چند پاسکال است؟ $(g = 10m/s^2 ، P_{\\circ} = 76cmHg)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:43:41', 5, 'done'),
(7209, ' در شکل مقابل، اگر بیشینه نیرویی که کف ظرف می‌تواند از طرف جیوه تحمل کند، $135$ نیوتون باشد، حداکثر چند سانتی‌متر جیوه می‌توان به ارتفاع جیوه در لوله اضافه کرد، تا ظرف نشکند؟ $(g = 10m/s^2 ، \\rho_{Hg} = 13500kg/m^3$، سطح کف ظرف $= 20cm^2)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:43:33', 5, 'done'),
(7210, ' در شکل روبه‌رو، اگر فشار هوا $10^5$ پاسکال و چگالی جیوه $13600kg/m^3$ باشد، فشار گاز درون ظرف، چند پاسکال است؟ $(g = 10N/kg)$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:43:26', 5, 'done'),
(7211, '17- یک نی پلاستیکی را مطابق شکل زیر از وسط می‌بریم و بدون اینکه دو قسمت آن کاملاً از هم جدا شوند، آن را 90 درجه تا کرده و درون آب قرار می‌دهیم. حال اگر از قسمت افقی آن در جهت نشان داده شده بدمیم، فشار هوا داخل نی قائم، چگونه تغییر می‌کند و سطح آب داخل آن چگونه جابه‌جا می‌شود؟', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:43:12', 5, 'done'),
(7212, ' در مکانی که فشار هوا $1/026 \\times 10^5 Pa$ است، اگر از عمق 10 سانتی‌متری مایعی، به عمق 53 سانتی‌متری برویم، فشار $1/5$ برابر می‌شود. چگالی مایع چند گرم بر سانتی‌متر مکعب است؟ $(g=10\\frac{m}{s^2})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:43:02', 5, 'done'),
(7213, '19- در شکل زیر، ارتفاع آب در هر شاخه لوله برابر 20 سانتی‌متر است. درون یکی از شاخه‌ها به آرامی روغن می‌ریزیم تا طول ستون روغن به 25 سانتی‌متر برسد. در حالت تعادل، ارتفاع آب در شاخه مقابل چند سانتی‌متر خواهد شد؟ (چگالی آب و روغن به ترتیب $1g/cm^3$ و $0/6g/cm^3$ است و قطر لوله در همه جا یکسان است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:42:54', 5, 'done'),
(7214, '20- در شکل زیر، دو مایع به حالت تعادل قرار دارند. اگر چگالی آن‌ها $\\rho_1 = 1/2 \\frac{g}{cm^3}$ و $\\rho_2 = 1 \\frac{g}{cm^3}$ باشد. فشار پیمانه‌ای گاز چند پاسکال است؟ $(g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:42:46', 5, 'done'),
(7215, '21- یک ظرف شیشه‌ای را به‌طور کامل روغن اندود کرده و از آب پر می‌کنیم و سپس سطح داخلی یک لوله مویین را نیز روغن اندود کرده و داخل ظرف شیشه‌ای فرو می‌بریم. کدام شکل نحوه قرار گرفتن آب درون ظرف شیشه‌ای و لوله مویین را به درستی نشان می‌دهد؟', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:41:38', 5, 'done'),
(7216, ' مطابق شکل مقابل، درون یک ظرف خالی، 180 گرم روغن با چگالی $0/6\\frac{kg}{L}$ می‌ریزیم. اگر سطح مقطع قسمت‌های پهن و باریک ظرف به ترتیب برابر $12cm^2$ و $5cm^2$ باشد، نیروی وارد بر کف ظرف از طرف روغن چند نیوتون خواهد بود؟ $(g=10\\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:41:12', 5, 'done'),
(7217, '23- در شکل زیر، دو مایع مخلوط نشدنی (1) و (2) با چگالی‌های $\\rho_1 = 1/6\\frac{g}{cm^3}$ و $\\rho_2 = 0/8\\frac{g}{cm^3}$ به حالت تعادل داخل لوله Uشکلی که سطح مقطع آن در تمام نقاط یکسان و برابر $5cm^2$ است. قرار دارند. اگر 24 گرم از مایع سومی به چگالی $\\rho_3$ را داخل شاخه سمت چپ بریزیم، سطح مایع (1) در طرف راست چند cm بالا می‌آید؟ $(\\rho_1 < \\rho_3)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:57', 5, 'done'),
(7218, ' جسم‌های (1) و (2) دارای حجم‌های برابر هستند ولی چگالی جسم (2) از چگالی جسم (1) بیشتر است. اگر جسم‌های (1) و (2) را به طور کامل درون مایعی فرو برده و رها کنیم تا دو جسم به حالت تعادل برسند، جسم (2) درون مایع غوطه‌ور می‌ماند و جسم (1) به سطح مایع آمده و شناور می‌شود. اگر نیروی شناوری وارد بر دو جسم را در حالت تعادل دو جسم با $F_b$ نشان دهیم، کدام گزینه درست است؟', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:44', 5, 'done'),
(7219, '26- در شکل مقابل لوله‌ای به‌صورت وارونه درون یک ظرف که از مایعی با چگالی $6/8\\frac{g}{cm^3}$ پرشده است، قرار دارد. اگر مساحت انتهای لوله $5cm^2$ باشد، چه نیرویی برحسب نیوتون از طرف گاز به انتهای بسته لوله وارد می‌شود؟ $(P_{\\circ} = 76 cmHg , \\rho_{Hg} = 13/6 \\frac{g}{cm^3} , g = 10 \\frac{m}{s^2})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:38', 5, 'done'),
(7220, '27- در شکل روبه‌رو، قطر قاعده شاخه سمت چپ 2 برابر قطر قاعده شاخه سمت راست است. اگر شیر ارتباط بین دو شاخه را باز کنیم، سطح آب چند سانتی‌متر پایین می‌آید؟ $(\\rho_{oil} = 0/8 \\frac{g}{cm^3} , \\rho_{water} = 1 \\frac{g}{cm^3}$ و حجم لوله رابط دوشاخه ناچیز است.)', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:30', 5, 'done'),
(7221, '28- دو لوله موئین شیشه‌ای تمیز یکی در ظرف آب و دیگری در ظرف جیوه به‌طور عمود قرار دارند. اگر قطر لوله‌های موئین کاهش یابند، اختلاف ارتفاع آب و جیوه درون لوله‌ها با سطح آب و جیوه درون ظرف به‌ترتیب از راست به چپ چگونه تغییر می‌کند؟', 1, 2, 76, 321, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:23', 5, 'done'),
(7222, '29- مطابق شکل مقابل، جریانی پایا از لوله‌های به‌هم پیوسته مقابل عبور می‌کند. سطح مقطع لوله‌های B و C با هم برابر و 2 برابر سطح مقطع لوله A است. اگر تندی آب در لوله C، $1/5$ برابر تندی آب در لوله A باشد، تندی آب در لوله B چند برابر تندی آب در لوله A است؟', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:13', 5, 'done'),
(7223, '30- نمودار حجم برحسب جرم دو مایع A و B مطابق شکل زیر است. اگر جرم یکسانی از این دو مایع را در دو شاخه لوله Uشکل زیر که محتوی مایع C است، بریزیم، پس از رسیدن به تعادل نحوه قرار گرفتن مایع‌ها مطابق کدام گزینه است؟ $(\\rho_B < \\rho_C < \\rho_A$، سطح مقطع لوله در سراسر طول آن یکسان است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:40:07', 5, 'done'),
(7224, ' چه تعداد از عبارت‌های زیر درست است؟\n\nالف) تمام جامدهای بی‌شکل از سرد شدن سریع مایع به‌دست می‌آیند.\n\nب) اگر قطعه‌های یک شیشه شکسته را آن‌قدر گرم کنیم که نرم شود، می‌توان آن‌ها را به‌هم چسباند، که علت آن، افزایش نیروی هم‌چسبی با افزایش دما است.\n\nپ) کروی بودن قطره‌های آب در حال سقوط، ناشی از نیروی جاذبه زمین است.\n\nت) نفوذ آب در منافذ بتن به دلیل اثر مویینگی است.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:57', 5, 'done'),
(7225, '32- در ظرف استوانه‌ای شکل زیر، دو مایع با چگالی‌های $\\rho_1$ و $\\rho_2$ روی هم قرار دارند. این دو مایع را مخلوط می‌کنیم تا بدون کاهش حجم یک مایع همگن جدید به‌دست آید. در این حالت، فشار در نقطه‌های A و B نسبت به قبل از مخلوط کردن مایع‌ها، چگونه تغییر می‌کند؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:50', 5, 'done'),
(7226, ' در شکل زیر، فشارسنج پیمانه‌ای چه فشاری را برحسب سانتی‌متر جیوه نشان می‌دهد؟ $(\\rho_{\\text{جیوه}} = 13/6\\frac{g}{cm^3} , \\rho_{\\text{مایع}} = 2/5\\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:40', 5, 'done'),
(7227, ' فشار هوا در سطح دریاچه‌ای $70cmHg$ است. در عمق چند متری از سطح این دریاچه، فشار کل برابر $120cmHg$ است؟ $(\\rho_{\\text{آب}} = 1\\frac{g}{cm^3} , \\rho_{\\text{جیوه}} = 13/6\\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:33', 5, 'done'),
(7228, ' در شکل مقابل، فشار در نقطة A ، برابر $105cmHg$ می‌باشد. ارتفاع h چند سانتی‌متر است؟ $(P_{\\circ} = 76cmHg , \\rho_{\\text{آب}} = 1\\frac{g}{cm^3} , \\rho_{\\text{جیوه}} = 13/5\\frac{g}{cm^3} , g=10\\frac{m}{s^2})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:24', 5, 'done'),
(7229, ' در شکل زیر، لوله‌ای که مساحت انتهای آن $2cm^2$ است، درون جیوه قرار گرفته است. اگر نیرویی که به انتهای بسته لوله از طرف جیوه وارد می‌شود، برابر $6/8N$ باشد، طولی از لوله که خارج از جیوه قرار دارد، چند سانتی‌متر است؟ $(P_{\\circ} = 75cmHg , g=10\\frac{m}{s^2} , \\rho_{\\text{جیوه}} = 13/6\\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:14', 5, 'done'),
(7230, ' در شکل زیر، مایع تراکم‌ناپذیر در لوله جریان ملایم و لایه‌ای دارد. اگر قطر مقطع لوله در قسمت (1) 25 درصد بیشتر از قطر مقطع لوله در قسمت (2) باشد و تفاوت تندی آن در مقاطع (1) و (2) $90\\frac{cm}{s}$ باشد، تندی جریان مایع در مقطع (2) چند متر بر ثانیه است؟', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:39:03', 5, 'done'),
(7231, ' مطابق آزمایش شکل زیر قطره‌های روغن با دو دمای متفاوت از دهانه قطره‌چکان خارج می‌شوند. با افزایش دما نیروی هم‌چسبی مولکول‌های مایع ........................ می‌یابد و در شکل ........................ دمای روغن پایین‌تر است.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:51', 5, 'done'),
(7232, '39- با استفاده از یک آلیاژ فلزی به جرم $980g$ و چگالی $2/5\\frac{g}{cm^3}$ یک پوسته کروی توخالی به شعاع داخلی $3cm$ می‌سازیم. این پوسته را یک‌بار درون ظرف حاوی مایع A و بار دیگر درون ظرف حاوی مایع B رها می‌کنیم. تا آلیاژ درون دو ظرف به تعادل برسد. اگر نمودار حجم برحسب جرم دو مایع مطابق شکل مقابل باشد، نیروی شناوری وارد بر پوسته درون ظرف A ........................ وزن پوسته و نیروی شناوری وارد بر پوسته درون ظرف B ........................ وزن پوسته است. $(\\pi=3)$', 1, 2, 76, 328, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:44', 5, 'done'),
(7233, ' مطابق شکل زیر، دو مایع به چگالی‌های $3/4\\frac{g}{cm^3}$ و $6/8\\frac{g}{cm^3}$ درون ظرفی ریخته شده‌اند. با فرض آن‌که فشار هوا در محل برابر با $75/25$ سانتی‌متر جیوه باشد، فشار کل وارد بر کف ظرف چند سانتی‌متر جیوه است؟ $(g=10\\frac{N}{kg} , \\rho_{\\text{جیوه}} = 13/6\\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:35', 5, 'done'),
(7234, ' مطابق شکل زیر، در ظرفی آب وجود دارد و سطح مقطع قسمت باریک و پهن ظرف به ترتیب $5cm^2$ و $20cm^2$ است. اگر به آب درون ظرف، $1/35kg$ جیوه اضافه کنیم، نیرویی که از طرف آب بر کف ظرف وارد می‌شود چند نیوتون و چگونه تغییر می‌کند؟ (جیوه در کف ظرف کاملاً پخش می‌شود. $g=10\\frac{N}{kg} , \\rho_{\\text{جیوه}} = 13/5\\frac{g}{cm^3} , \\rho_{\\text{آب}} = 1\\frac{g}{cm^3}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:27', 5, 'done'),
(7235, ' در شکل زیر، فشار هوا $75cmHg$ می‌باشد. فشار گاز مخزن را با استفاده از شیر خروجی چند سانتی‌متر جیوه و چگونه تغییر دهیم تا در همان محل، اختلاف ارتفاع آزاد جیوه در دو طرف لوله Uشکل، دوباره $45cm$ شود؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:18', 5, 'done'),
(7236, ' از عبارت‌های زیر چند عبارت درست است؟\n\nآ) اگر مقداری جیوه را روی سطح افقی شیشه‌ای بریزیم، جیوه روی سطح شیشه را تر می‌کند.\n\nب) کشش سطحی در مایع‌ها، نوعی نیروی هم‌چسبی بین مولکول‌های مایع است.\n\nپ) دگرچسبی، نیرویی است که مولکول‌های یک ماده را به‌سوی مولکول‌های مادة مجاور می‌کشد.\n\nت) وقتی لولۀ موئین را وارد یک ظرف آب کنیم، سطح آب درون لوله از سطح آب درون ظرف پایین‌تر قرار می‌گیرد.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:08', 5, 'done'),
(7237, '44- مطابق شکل دو استوانه توخالی قائم هم‌مرکز که شعاع آن‌ها به ترتیب $5cm$ و $10cm$ هستند، در اختیار داریم. مقدار جرم 500 گرم از یک مایع به چگالی $4\\frac{g}{cm^3}$ را یک‌بار در فضای بین دو استوانه و بار دیگر درون استوانه داخلی می‌ریزیم. اگر فشار وارد بر سطح از طرف مایع در حالت اول و دوم به‌ترتیب برابر $P_1$ و $P_2$ باشد. $\\frac{P_1}{P_2}$ کدام است؟ $(g=10\\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:38:00', 5, 'done'),
(7238, ' در شکل زیر، سطح مقطع شاخۀ سمت راست لوله دو برابر سطح مقطع شاخۀ سمت چپ آن است. فشار پیمانه‌ای گاز درون مخزن حداکثر چند سانتی‌متر جیوه افزایش یابد تا مایع از شاخۀ سمت راست، سرریز نشود؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:37:44', 5, 'done'),
(7239, ' اگر با استفاده از یک شیر، قطر مقطع گذر آب در لوله‌ای را $\\frac{1}{3}$ برابر کنیم، تندی آب خروجی چند درصد افزایش می‌یابد؟ (جریان آب لایه‌ای و پایا است.)', 1, 2, 76, 329, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:37:36', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7240, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ) کشش سطحی، ناشی از هم‌چسبی مولکول‌های سطح مایع است.\n\nب) پدیده پخش فقط در گازها مشاهده می‌شود.\n\nپ) نیروی دگرچسبی به سبب تماس دو ماده یکسان با یکدیگر و از نوع نیروی جاذبه است.\n\nت) سطح جیوه در لوله مویین، برآمده است و ارتفاع جیوه درون لوله، بالاتر از سطح جیوه درون ظرف قرار دارد.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:37:27', 5, 'done'),
(7241, ' نمودار جرم برحسب حجم دو مایع مخلوط‌نشدنی A و B به‌صورت زیر است. اگر مطابق شکل، در ظرف استوانه‌ای شکل به سطح مقطع $25cm^2$ تا ارتفاع $20cm$ از مایع A بریزیم، چند گرم از مایع B به آن اضافه کنیم تا فشار کل در ته ظرف $103kPa$ شود؟ $(g=10\\frac{N}{kg} , P_{\\circ} = 10^5Pa)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:37:20', 5, 'done'),
(7242, ' مطابق شکل زیر، دو مایع مخلوط‌نشدنی داخل لوله Uشکل به حال تعادل قرار دارند. اگر فشار پیمانه‌ای نقطۀ A برابر $2176$ پاسکال باشد، فشار پیمانه‌ای نقطۀ B چند سانتی‌متر جیوه است؟ $(\\rho_{Hg} = 13/6\\frac{g}{cm^3} , g=10\\frac{m}{s^2})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:37:11', 5, 'done'),
(7243, ' مطابق شکل زیر یک لوله U شکل که شعاع شاخۀ سمت چپ آن 2 برابر شعاع شاخۀ سمت راست آن است، به یک مخزن گاز وصل شده است و درون لوله یک مایع با چگالی $6/8\\frac{g}{cm^3}$ وجود دارد. حداکثر چند سانتی‌متر جیوه فشار گاز درون مخزن می‌تواند افزایش یابد تا مایع از شاخۀ سمت راست بیرون نریزد؟ $(\\rho_{\\text{جیوه}} = 13/6\\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:37:01', 5, 'done'),
(7244, ' در شکل زیر آب در یک لوله افقی به‌صورت پایا در جریان است و سطح مقطع قسمت A برابر $40cm^2$ و سطح مقطع قسمت B برابر $5cm^2$ است. اگر آب با آهنگ $0/8 \\frac{L}{s}$ جریان داشته باشد، تندی آب در قسمت A چند $\\frac{m}{s}$ است؟', 1, 2, 76, 329, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:36:54', 5, 'done'),
(7245, ' یک مکعب مستطیل فلزی به ابعاد $8cm \\times 5cm \\times 4cm$ که درون آن یک حفره توخالی دارد، بر روی یکی از وجه‌هایش روی سطح افقی قرار می‌گیرد. اگر بیشترین فشاری که این مکعب مستطیل بر سطح افقی وارد می‌کند، $3900$ پاسکال باشد، حجم حفرۀ توخالی چند سانتی‌متر مکعب است؟ (چگالی فلز سازنده مکعب مستطیل $6/5\\frac{g}{cm^3}$ است و $g=10\\frac{N}{kg}$ است.)', 1, 2, 76, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:36:28', 5, 'done'),
(7246, '53- سه کره توپر و مشابه به شعاع $5cm$ و جرم $1200g$ را درون سه ظرف که از مایع‌های B ،A و C با چگالی $\\rho_A = 3/5\\frac{g}{cm^3}$، $\\rho_B = 1/5\\frac{g}{cm^3}$ و $\\rho_C = 3\\frac{g}{cm^3}$ پر شده‌اند، رها می‌کنیم. اگر اثر نیروی شناوری وارد بر کره‌ها بعد از تعادل، به ترتیب $F_B$ ،$F_A$ و $F_C$ باشد، کدام گزینه در مورد مقایسه این سه نیرو صحیح است؟ $(\\pi=3)$', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:36:18', 5, 'done'),
(7247, ' با جرم برابر از طلا و نقره، آلیاژی ساخته‌ایم و 380 گرم از این آلیاژ را داخل ظرفی پر از روغن به چگالی $880\\frac{kg}{m^3}$ می‌اندازیم. وزن روغن بیرون ریخته از ظرف چند نیوتون است؟ $(\\rho_{\\text{نقره}} = 11\\frac{g}{cm^3} , \\rho_{\\text{طلا}} = 19\\frac{g}{cm^3} , g=10\\frac{m}{s^2})$', 1, 2, 76, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:36:09', 5, 'done'),
(7248, ' مقداری آب روی سطح شیشه‌ای چرب و مقداری جیوه روی سطح شیشه تمیز می‌ریزیم. کدام‌یک از موارد زیر صحیح است؟', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:56', 5, 'done'),
(7249, ' چه تعداد از عبارت‌های زیر به‌درستی بیان شده است؟\n\nالف) هنگامی‌که یک لیوان پر از آب را کج می‌کنیم، آب به راحتی از آن می‌ریزد. این مشاهده ما را به این نتیجه می‌رساند که مولکول‌های مایع بر روی هم می‌لغزند.\n\nب) با برداشتن در شیشه عطر، تمام فضای اتاق خوشبو می‌شود؛ زیرا تندی حرکت مولکول‌های عطر نسبت به تندی مولکول‌های هوا بسیار زیاد است.\n\nپ) مولکول‌های مایع به‌صورت منظم و متقارن در کنار یکدیگر قرار دارند.\n\nت) عامل ایجاد فرآیند پخش مولکول‌های شکر در آب، حرکت نامنظم و کاتوره‌ای مولکول‌های آب است.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:48', 5, 'done'),
(7250, ' در صورتی که چند قطره از مایعی را بر روی سطح یک شیشه خشک و تمیز بریزیم، مایع به شکل زیر بر روی سطح شیشه قرار می‌گیرد. در صورتی که لوله مویینی از جنس این شیشه را در داخل ظرفی دارای همین مایع قرار دهیم، سطح مایع در لوله ... از سطح آزاد آن در ظرف است و با افزایش قطر داخلی لوله مویین، سطح مایع در لوله ... می‌آید.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:41', 5, 'done'),
(7251, ' اگر در ارتفاع‌های $h$، $2h$، $3h$ و $4h$ فشار هوا به‌ترتیب $p_1$، $p_2$، $p_3$ و $p_4$ و چگالی هوا به‌ترتیب $\\rho_1$، $\\rho_2$، $\\rho_3$ و $\\rho_4$ باشد، چه تعداد از موارد زیر در مورد مقایسه فشار و چگالی هوا در این نقاط صحیح است؟\n\nالف) $p_1 > p_2 > p_3 > p_4$\n\nب) $\\rho_4 > \\rho_3 > \\rho_2 > \\rho_1$\n\nپ) $p_1 - p_2 = p_3 - p_4$\n\nت) $p_1 - p_2 > p_3 - p_4$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:33', 5, 'done'),
(7252, ' درون ظرفی استوانه‌ای به مساحت قاعده $5cm^2$ تا ارتفاع $25cm$ مایعی به چگالی $4 \\frac{g}{cm^3}$ وجود دارد. اگر $55cm^3$ از مایعی به چگالی $2 \\frac{g}{cm^3}$ اضافه کنیم، فشار کل وارد بر کف ظرف چند درصد افزایش می‌یابد؟ $(P_\\circ = 10^5 Pa , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:27', 5, 'done'),
(7253, ' در شکل زیر، مایع‌های A و B درون لوله‌ها در حال تعادل‌اند. فشار پیمانه‌ای گاز درون مخزن چند سانتی‌متر جیوه است؟ $(g = 10 \\frac{N}{kg} , \\rho_A = 6/8 \\frac{g}{cm^3} , \\rho_B = 3/4 \\frac{g}{cm^3} , \\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:19', 5, 'done'),
(7254, '63- مطابق شکل، لوله استوانه‌ای A به قطر $2cm$ و طول $92cm$ را به اندازه $2cm$ در ظرف محتوی جیوه فرو برده‌ایم و ارتفاع جیوه درون این لوله $76cm$ می‌شود. اگر لوله استوانه‌ای B که قطر آن $1/5cm$ و طول آن $80cm$ است را به اندازه $3cm$ در ظرف محتوی جیوه در همان مکان فرو ببریم ارتفاع جیوه در این لوله چند سانتی‌متر خواهد بود؟ (نحوه فروبردن لوله‌ها به داخل جیوه، مشابه آزمایش توریچلی است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:12', 5, 'done'),
(7255, ' در شکل زیر، اگر در هر دقیقه ۲۵ لیتر آب با تندی $2 \\frac{m}{s}$ از سطح مقطع دهانه M عبور نماید و مساحت مقطع دهانه M، ۴ برابر مساحت مقطع دهانه N باشد در این صورت به ترتیب از راست به چپ در هر دقیقه چند لیتر آب و با تندی چند $\\frac{m}{s}$ از سطح مقطع دهانه N عبور می‌کند؟ (جریان آب درون لوله لایه‌ای و یکنواخت است.)', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:35:05', 5, 'done'),
(7256, '65- نمودار حجم برحسب جرم دو فلز A و B مطابق شکل زیر است. دو کره فلزی با حجم ظاهری یکسان را درون ظرفی شامل مایع با چگالی $2/5 \\frac{g}{cm^3}$ رها می‌کنیم تا به تعادل برسد. اگر ۶۰ درصد از حجم ظاهری کره‌ها را حفره توخالی تشکیل داده باشد و نیروی شناوری وارد بر کره‌های A و B به ترتیب $F_A$ و $F_B$ باشد، کدام گزینه صحیح است؟ ($W$ وزن کره‌ها است.)', 1, 2, 76, 328, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:34:51', 5, 'done'),
(7257, '66- مطابق شکل زیر، درون لوله U شکل دو مایع B و C در حال تعادل‌اند و مساحت سطح مقطع شاخه سمت چپ و راست به ترتیب $4 cm^2$ و $1 cm^2$ است. اگر در شاخه سمت چپ $32 cm^3$ از مایع B اضافه کنیم، پس از ایجاد تعادل، چند گرم از مایع C در شاخه سمت راست لبریز می‌شود؟ $(\\rho_B = 3 \\frac{g}{cm^3} , \\rho_C = 1/5 \\frac{g}{cm^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:34:34', 5, 'done'),
(7258, ' چه تعداد از پدیده‌های زیر بیان‌گر کشش سطحی آب است؟\n\nالف) تشکیل حباب آب و صابون\n\nب) تشکیل قطرات کروی آب در حال سقوط آزاد\n\nپ) راحت‌تر شسته شدن ظروف چرب با آب گرم\n\nت) نشستن حشرات روی سطح آب', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:34:23', 5, 'done'),
(7259, ' ابعاد مکعب مستطیل توپر $4cm \\times 6cm \\times 7cm$ و چگالی ماده سازنده آن $5 \\frac{g}{cm^3}$ است. وقتی این مکعب مستطیل را از بزرگ‌ترین وجه روی سطح افقی قرار می‌دهیم، وزنه چند نیوتونی بر روی آن قرار دهیم تا فشاری که بر سطح افقی وارد می‌کند، هم اندازه فشاری باشد که زمانی که از روی کوچکترین وجه روی سطح افقی قرار می‌گیرد، به سطح وارد می‌کند؟ $(g = 10 \\frac{N}{kg})$', 1, 2, 76, 326, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:34:17', 5, 'done'),
(7260, ' مطابق شکل زیر، مکعبی به ضلع $30cm$ درون مایعی غوطه‌ور است. اگر اختلاف نیروی وارد بر وجه‌های بالا و پایین مکعب $0/54kN$ باشد، چگالی مایع چند $\\frac{kg}{m^3}$ است؟ $(g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:34:08', 5, 'done'),
(7261, '70- در لوله U شکل زیر، قطر مقطع لوله سمت چپ، ۲ برابر قطر لوله سمت راست است. اگر از سمت راست تا ارتفاع $5cm$ روغن با چگالی $0/8 \\frac{g}{cm^3}$ اضافه کنیم، پس از رسیدن به تعادل، اختلاف ارتفاع آب در دو شاخه چند سانتی‌متر می‌شود؟ $(\\rho_{\\text{آب}} = 1 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:58', 5, 'done'),
(7262, ' در شکل مقابل، بیش‌ترین فشاری که ته لوله قائم از طرف مایع درون آن می‌تواند تحمل کند تا نشکند برابر با $20400 Pa$ است. اگر فشار هوا $75 cmHg$ باشد، طول لوله بیرون از سطح آزاد جیوه را از وضعیت نشان داده شده، حداکثر چند درصد کاهش دهیم تا لوله نشکند؟ $(g = 10 \\frac{N}{kg} , \\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:53', 5, 'done'),
(7263, ' در شکل مقابل، آب و روغن در لوله U شکلی به سطح مقطع $2 cm^2$ به حال تعادل قرار دارند. در شاخه سمت راست، چند گرم از مایع سوم به چگالی $\\rho$ بریزیم تا سطح آب در دو طرف لوله یکسان شود؟ $(\\rho < \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:46', 5, 'done'),
(7264, ' در شکل زیر، جرم یکسانی از دو مایع به چگالی‌های $\\rho_1$ و $\\rho_2 = 1/6 \\frac{g}{cm^3}$ داخل لوله U شکل به حال تعادل قرار دارند. فشارسنج پیمانه‌ای متصل به مخزن گاز، چند سانتی‌متر جیوه را نشان می‌دهد؟ (شعاع لوله در سمت چپ، ۲ برابر شعاع لوله در سمت راست و در قسمت افقی شعاع لوله ناچیز است. $\\rho_{Hg} = 13/5 \\frac{g}{cm^3} , g = 10 \\frac{m}{s^2}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:38', 5, 'done'),
(7265, ' در شکل زیر، فشار هوای داخل لوله آزمایش، $74/5 cmHg$ است. چگالی مایع چند گرم بر سانتی‌متر مکعب است؟ $(P_\\circ = 95200 Pa , \\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:31', 5, 'done'),
(7266, ' در جاده‌ای با یک ماشین سواری در حال رانندگی هستید و از روبه‌رو یک تریلی از کنارتان رد می‌شود. هنگامی‌که دو ماشین از کنار هم می‌گذرند به دلیل ... فشار هوای بین دو ماشین، طبق ... ماشین شما کمی به سمت تریلی منحرف می‌گردد.', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:25', 5, 'done'),
(7267, ' مطابق شکل زیر، جریان یکنواخت و لایه‌ای آب به‌صورت پایا از بخش ۱ لوله وارد و از بخش ۲ خارج می‌شود. شعاع سطح مقطع لوله در بخش ۱ و ۲ به ترتیب ۴ و ۲ سانتی‌متر می‌باشد. اگر اختلاف تندی شاره در بخش‌های ۱ و ۲، $15 \\frac{cm}{s}$ باشد، در هر ساعت چند لیتر آب از لوله باریک خارج می‌شود؟ $(\\pi \\simeq 3)$', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:19', 5, 'done'),
(7268, ' یک قطره از مایع A را روی سطح مسطح B می‌ریزیم. اگر نیروی دگرچسبی بین مایع A و سطح B کمتر از نیروی هم‌چسبی بین مولکول‌های A باشد، مایع A ........................', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:12', 5, 'done'),
(7269, ' نمودار فشار برحسب عمق از سطح یک مایع، مطابق شکل زیر است. جرم هر لیتر از این مایع چند کیلوگرم است؟ $(\\rho = 13/6 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:33:02', 5, 'done'),
(7270, ' در شکل زیر، اگر فشار هوای داخل لوله برابر با $60 cmHg$ باشد، فشار هوای محل آزمایش چند سانتی‌متر جیوه است؟ $(\\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3} , \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:53', 5, 'done'),
(7271, ' در شکل زیر، مقدار x چند سانتی‌متر است؟ $(\\rho_{\\text{آب}} = 10^3 \\frac{kg}{m^3} , P_\\circ = 10^5 Pa)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:47', 5, 'done'),
(7272, ' فشار در $\\frac{1}{3}$ عمق دریاچه‌ای $\\frac{3}{5}$ فشار در ته آن است. عمق این دریاچه چند متر است؟ $(P_\\circ = 10^5 Pa , \\rho_{\\text{آب}} = 10^3 \\frac{kg}{m^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:40', 5, 'done'),
(7273, ' در شکل زیر، فشار پیمانه‌ای گاز محبوس درون مخزن چند $cmHg$ است؟ $(\\rho_{\\text{آب}} = 1 \\frac{g}{cm^3} , \\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:34', 5, 'done'),
(7274, ' در شکل زیر مساحت درپوش $4cm^2$ است. نیروی وارد بر درپوش از طرف آب چند نیوتون است؟ $(g = 10 \\frac{N}{kg} , P_{\\text{گاز}} = 70cmHg , \\rho_{\\text{جیوه}} = 13/5 \\frac{g}{cm^3} , \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3})$', 1, 2, 76, 326, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:28', 5, 'done'),
(7275, ' در شکل مقابل، طول قسمتی از لوله که بیرون از جیوه قرار دارد $0/5$ متر است. اگر زاویه لوله از راستای قائم را $7$ درجه کاهش دهیم، نیرویی که از طرف جیوه بر انتهای بسته لوله وارد می‌شود، چند نیوتون و به چه صورت تغییر می‌کند؟ (فشار هوا در محل $75cmHg$، چگالی جیوه $13/6$ گرم بر سانتی‌متر مکعب، سطح مقطع انتهای لوله $10cm^2$ ، $\\sin 37^\\circ = \\cos 53^\\circ = 0/6$ و $g = 10 \\frac{N}{kg}$ است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:17', 5, 'done'),
(7276, 'شکل زیر، دو مایع به حالت تعادل قرار دارند، اگر چگالی آنها $\\rho_1 = 1/2 \\frac{g}{cm^3}$ و $\\rho_2 = 1 \\frac{g}{cm^3}$ باشد، فشار پیمانه‌ای گاز چند سانتی‌متر جیوه است؟ $(g = 10 \\frac{N}{kg} , \\rho_{\\text{جیوه}} = 13/5 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:32:01', 5, 'done'),
(7277, ' مطابق شکل زیر، در دو لوله استوانه‌ای مرتبط به‌هم تا سطح A\'A آب وجود دارد، اگر سطح مقطع یکی از استوانه‌ها $300 cm^2$ و سطح مقطع دیگری $100 cm^2$ باشد، در لوله سمت چپ چند گرم نفت اضافه کنیم تا آب در لوله سمت راست، نسبت به حالت اولیه، $3/6 cm$ بالا رود؟ $(\\rho_{\\text{نفت}} = 0/8 \\frac{g}{cm^3} , g = 10 \\frac{m}{s^2} , \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:31:53', 5, 'done'),
(7278, '101- هنگامی که یک لیوان پر از آب را کج می‌کنیم، آب به راحتی از آن می‌ریزد. این مشاهده ما را به این نتیجه می‌رساند که مولکول‌های مایع:', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:31:46', 5, 'done'),
(7279, ' درون یک ظرف استوانه‌ای که مساحت قاعده آن $5cm^2$ و روی یک سطح افقی قرار دارد، مقدار $20cm^3$ آب وجود دارد. اگر بر روی آب $8/75cm^3$ نفت بریزیم، بعد از تعادل فشار کل در کف ظرف چند میلی‌متر جیوه خواهد شد؟ $(P_\\circ = 76cmHg , \\rho_{\\text{جیوه}} = 13/5 \\frac{g}{cm^3} , \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3} , \\rho_{\\text{نفت}} = 0/8 \\frac{g}{cm^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:31:36', 5, 'done'),
(7280, '103- ارتفاع قله‌ای از سطح زمین $h$ است. اگر فشار هوا در ارتفاع $\\frac{h}{2}$ از سطح زمین $\\frac{3}{2}$ فشار هوا در بالای آن قله باشد و چگالی متوسط مولکول‌های هوا $1/25 \\frac{kg}{m^3}$ باشد، $h$ چند متر است؟ $(P_\\circ = 10^5 Pa , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:31:30', 5, 'done'),
(7281, ' در شکل زیر، مایع‌های درون لوله‌های U شکل در حال تعادل هستند. اگر فشار پیمانه‌ای مخزن A، $40kPa$ باشد، $h$ چند سانتی‌متر است؟ $(g = 10 \\frac{N}{kg} , P_\\circ = 101kPa)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:31:20', 5, 'done'),
(7282, ' در شکل زیر آب و نفت درون لوله U شکل در حال تعادل‌اند. اگر شیر ارتباط بین دو لوله را باز کنیم، نفت در لوله سمت چپ چند سانتی‌متر نسبت به حالت اولیه بالاتر می‌رود؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 21:17:17', 5, 'done'),
(7283, ' مطابق شکل زیر، داخل ظرفی تا ارتفاع $h$، مایعی ریخته‌ایم و ظرف روی یک ترازو قرار دارد. اگر مقداری از همان مایع به ظرف اضافه کنیم، نیروی وارد از طرف مایع به کف ظرف $20N$ افزایش می‌یابد. در این حالت، عددی که ترازو نشان خواهد داد، چند نیوتون افزایش می‌یابد؟ (مساحت دهانه باریک ظرف $20cm^2$، مساحت کف ظرف $100cm^2$ و با ریختن مایع درون ظرف، مایع از آن سرریز نمی‌شود.)', 1, 2, 76, 327, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 21:17:10', 5, 'done'),
(7284, ' در شکل زیر، دو مایع با چگالی‌های $\\rho_1$ و $\\rho_2$ داخل لوله U شکل متصل به یک مخزن گاز، در حال تعادل قرار دارند. اگر فشارسنج متصل به مخزن، $5cmHg$ را نشان دهد، اختلاف چگالی دو مایع چند گرم بر سانتی‌متر مکعب است؟ (سطح مقطع لوله در دو طرف یکسان و در لوله رابط ناچیز و چگالی جیوه $13/6 \\frac{g}{cm^3}$ است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 21:16:58', 5, 'done'),
(7285, ' در لوله U شکلی که مساحت مقطع آن در تمام قسمت‌ها یکسان و برابر $2cm^2$ است، مایعی به چگالی $1/2 \\frac{g}{cm^3}$ به حال تعادل قرار دارد. چند گرم مایع به چگالی $0/8 \\frac{g}{cm^3}$ را به آرامی به سمت چپ لوله اضافه کنیم تا ارتفاع مایع در سمت راست به $17cm$ برسد؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 21:16:51', 5, 'done'),
(7286, ' مطابق شکل زیر لوله‌ای استوانه‌ای شکل به طول $50cm$ درون یک ظرف حاوی دو مایع A و B قرار دارد. به‌طوری‌که طول قسمتی از لوله که درون مایع A قرار دارد $10cm$ است. اگر فشار هوای محیط $76$ سانتی‌متر جیوه باشد، فشار نقطه C چند سانتی‌متر جیوه است؟ $(\\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3} , \\rho_A = 6/8 \\frac{g}{cm^3} , \\rho_B = 1/7 \\frac{g}{cm^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:27:47', 5, 'done'),
(7287, ' در شکل زیر، فشار پیمانه‌ای نقطه A، ۳ برابر فشار پیمانه‌ای نقطه B است. اختلاف فشار کل دو نقطه A و B چند سانتی‌متر جیوه خواهد بود؟ $(\\rho_{\\text{مایع}} = 3/4 \\frac{g}{cm^3} , \\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3} , P_\\circ = 76 cmHg)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:27:34', 5, 'done'),
(7288, ' در شکل زیر، سطح مقطع لوله U شکل در طرف راست $4cm^2$ و در طرف چپ $2cm^2$ و جرم مایع‌ها با هم برابر است. اگر شیر رابط را باز کنیم، مایع (۲) در سمت راست، $2/5cm$ بالا می‌آید. حجم مایع (۱) چند سانتی‌متر مکعب است؟ (از حجم لوله رابط صرف‌نظر کنید.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:05', 1, '2026-03-26 20:27:23', 5, 'done'),
(7289, 'نیروی بین مولکول های آب در سطح آن از نوع ............. و نیروی بین مولکول های آب در تماس با دیواره ظرف شیشه ای از نوع ............. است.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:27:16', 5, 'done'),
(7290, 'افزایش دما، نیروی هم چسبی بین مولکول های مایع را ............. می کند و هرچه قطره های در حال سقوط از قطره چکان دارای دمای بیشتری باشند، حجم آن ها ............. است.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:27:07', 5, 'done'),
(7291, 'اگر بخواهیم فاصله بین مولکول های مایع را کم کنیم، نیروی بین مولکولی به صورت ............. ظاهر می شود و اگر بخواهیم فاصله بین مولکول های مایع را زیاد کنیم، نیروی بین مولکولی به صورت ............. ظاهر می شود و نیروی بین مولکولی ............. است.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:59', 5, 'done'),
(7292, 'شکل های (الف) و (ب) به ترتیب جلوه هایی از کدام پدیده های فیزیکی هستند؟', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:53', 5, 'done'),
(7293, 'دریچه ای با مساحت $100 cm^2$ در عمق $100$ متری آب قرار دارد. بزرگی نیرویی که آب بر سطح دریچه وارد می کند، چند کیلونیوتون است؟ \r\n\r\n($g=10 \\frac{N}{kg}$ , $\\rho$ آب $=1000 \\frac{kg}{m^{3}}$ , $P_0=10^{5} Pa$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:45', 5, 'done'),
(7294, 'در لوله $U$شکل روبه رو، قطر مقطع لوله های استوانه ای شکل $2 cm$ و $4 cm$ است و آب در دو شاخه در حال تعادل است. چنانچه $600 cm^{3}$ روغن به یکی از شاخه ها اضافه کنیم، فشار در بخش افقی لوله چند پاسکال افزایش می یابد؟ \r\n\r\n($g=10 \\frac{N}{kg}$ , $\\rho$ روغن $=0/8 \\frac{g}{cm^{3}}$ , $\\rho$ آب $=1 \\frac{g}{cm^{3}}$ , $\\pi=3$ و قطر مقطع بخش افقی لوله ناچیز است.)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:36', 5, 'done'),
(7295, 'هرچه قدر از آسمان به سطح زمین نزدیک تر شویم، چگالی هوا و فشار هوا به ترتیب چگونه تغییر می کنند؟', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:27', 5, 'done'),
(7296, 'لوله جوسنجی به شکل استوانه با طول   $1m$ و سطح مقطع  $0.5cm^2$ را پر از جیوه نموده و مانند شکل، به صورت وارون وارد ظرفی حاوی جیوه می کنیم. اگر فشار هوا در محل  $94.5kPa$ باشد، پس از به تعادل رسیدن، چند سانتی متر مکعب جیوه از لوله خارج شده است؟\r\n\r\n $(g = 10 \\frac{N}{kg} , \\rho_{\\text{جیوه}} = 13/5 \\frac{g}{cm^}3}{)$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:17', 5, 'done'),
(7297, 'لوله $U$شکل زیر، حاوی آب و روغن است. اگر فشار در نقاط $A$ و $B$ به ترتیب $105 kPa$ و $106 kPa$ باشد، فشار پیمانه ای مخزن گاز چند کیلوپاسکال است؟ \r\n\r\n($\\rho$ آب $=1 \\frac{g}{cm^3}$ و $\\rho$ روغن $=0/8 \\frac{g}{cm^3}$ ، $g=10 \\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:10', 5, 'done'),
(7298, 'در شکل روبه رو، جسم (۱) درون آب غوطه ور بوده و جسم (۲) روی سطح آب شناور است. اگر جرم آن ها یکسان باشد، کدام مقایسه درباره بزرگی نیروی شناوری وارد بر هر جسم و چگالی آن ها درست است؟', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:26:03', 5, 'done'),
(7299, 'در شکل روبه رو، آب به صورت لایه ای در لوله جریان دارد و تندی آب هنگام ورود آب از بخش پهن به بخش باریک ۴۴ درصد تغییر می کند. اگر قطر مقطع بخش باریک لوله  $5cm$ باشد، شعاع بخش پهن لوله چند میلی متر بیشتر از شعاع بخش باریک آن است؟', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:55', 5, 'done'),
(7300, 'چه تعداد از گزاره های زیر، نادرست بیان شده اند؟\r\n\r\nالف) حرکت نامنظم مولکول های آب و برخورد آن ها با ذرات جوهر، سبب پخش جوهر موجود در آب می شود.\r\n\r\nب) پدیده پخش در گازها سریع تر از پدیده پخش در مایع ها اتفاق می افتد.\r\n\r\nپ) فاصله ذرات مایع و فاصله ذرات جامد تقریباً یکسان و در حدود یک آنگستروم است.\r\n\r\nت) فلزها، نمک ها، الماس و یخ همگی جامدهای بلورین اند.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:45', 5, 'done'),
(7301, 'جاهای خالی در موارد (الف)، (ب) و (پ) به ترتیب با کدام گزینه به درستی کامل می شوند؟\r\n\r\nالف) ایستادن یا راه رفتن حشرات روی سطح آب به دلیل ............. است.\r\n\r\nب) نفوذ آب در منافذ دیوارهای گلی به دلیل ............. است.\r\n\r\nپ) افزایش دمای آب سبب ............. نیروی هم چسبی بین مولکول های آب می شود.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:37', 5, 'done'),
(7302, 'فشار کل در چه عمقی از آب یک استخر برابر با یک متر جیوه است؟\r\n\r\n $(P_0 = 75 cmHg , g = 10 \\frac{N}{kg} , \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3}$ و $\\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:30', 5, 'done'),
(7303, 'در لوله Uشکل داده شده که سطح مقطع همه قسمت های آن یکسان است، آب، روغن و جیوه در حال تعادل اند. اگر اختلاف فشار نقاط A و B برابر با  $5040Pa$ باشد، ارتفاع جیوه در لوله چند سانتی متر است؟\r\n\r\n\r\n\r\n $(\\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3} , \\rho_{\\text{آب}} = 1 \\frac{g}{cm^3} , \\rho_{\\text{روغن}} = 0/8 \\frac{g}{cm^3} , g = 10 \\frac{N}{kg})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:21', 5, 'done'),
(7304, 'شکل های زیر، دو بارومتر را در یک مکان نشان می دهند که درون آن ها به ترتیب مایع با چگالی های $\\rho_1$ و $\\rho_2$ وجود دارد. اگر سطح مقطع لوله بارومتر (۱) دو برابر سطح مقطع لوله بارومتر (۲) باشد و ارتفاع $h_1$ نیز دو برابر ارتفاع $h_2$ باشد، $\\rho_1$ چند برابر $\\rho_2$ است؟', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:12', 5, 'done'),
(7305, 'درون یک لوله Uشکل با سطح مقطع یکنواخت  $1cm^2$، جیوه به حال تعادل است. مطابق شکل، شخصی در شاخه سمت چپ، طوری می دمد که جیوه در شاخه سمت راست در آستانه خروج از لوله قرار می گیرد. در این حالت اندازه نیرویی که از طرف هوای درون ریه شخص بر سطح جیوه وارد می شود، چند نیوتون است؟\r\n\r\n\r\n\r\n $(P_{\\text{هوای محیط}} = 70 cmHg , g = 10 \\frac{N}{kg} , \\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3})$', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:25:02', 5, 'done'),
(7306, 'آب در لوله استوانه ای روبه رو به صورت لایه ای در جریان است. اگر قطر بخش پهن لوله $d_1 = 10 cm$ و قطر بخش باریک آن $d_2 = 2 cm$ باشد، تندی آب در بخش باریک لوله چند متر بر ثانیه است؟', 1, 2, 76, 329, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:16:03', 5, 'done'),
(7307, 'مطابق شکل، درب شیشه‌ای قابلمه‌ای به جرم $200g$ و سطح مقطع $200cm^2$، مانع خروج بخار آب درون قابلمه می‌شود. فشار بخار آب درون قابلمه حداکثر تا چند اتمسفر می‌تواند بالا برود؛ به طوری که درب قابلمه هم‌چنان روی قابلمه باقی بماند؟\r\n\r\n ($1atm = 100kPa$ = فشار هوای محیط، $g = 10\\frac{m}{s^2}$ و از تماس لبه‌های درب با دهانه قابلمه صرف‌نظر کنید.)', 1, 2, 76, 326, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:15:53', 5, 'done'),
(7308, 'چه تعداد از مواد زیر، پلاسما محسوب می‌شوند؟\r\n\r\nالف) ماده درون ستارگان\r\n\r\nب) آتش\r\n\r\nپ) ماده داخل لامپ‌های مهتابی', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:15:25', 5, 'done'),
(7309, 'مطابق شکل، آب در یک لوله افقی با آهنگ شارش حجمی $6\\frac{L}{s}$ به‌صورت لایه‌ای جریان دارد. اگر قطر مقطع قسمت‌های باریک و پهن لوله به‌ترتیب $10cm$ و $20cm$ باشد، تندی حرکت آب در قسمت کم‌فشار لوله چند متر بر ثانیه است؟ ($\\pi = 3$)', 1, 2, 76, 329, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:14:11', 5, 'done'),
(7310, 'درون یک ظرف استوانه‌ای بلند مطابق شکل، مایعی با چگالی $1.2\\frac{g}{cm^3}$ تا ارتفاع $20cm$ ریخته شده است و فشار در کف ظرف $P_1$ است. با اضافه‌کردن مقدار دیگری از همان مایع، چند سانتی‌متر دیگر به ارتفاع مایع درون ظرف باید اضافه شود تا فشار در کف ظرف به $1.03P_1$ برسد؟ \r\n\r\n($P_{\\text{هوا}} = 97/6kPa$ و $g = 10\\frac{m}{s^2}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:14:01', 5, 'done'),
(7311, 'درون لوله Uشکل داده شده، آب و جیوه وجود دارد و یک سر لوله به یک مخزن گاز متصل است. اگر فشار هوای محیط $P_0 = 96/12 kPa$ باشد، فشار گاز درون مخزن چند کیلوپاسکال است؟ \r\n\r\n($\\rho_{\\text{آب}} = 1 \\frac{g}{cm^3}$، $\\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3}$ و $g = 10\\frac{m}{s^2}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:54', 5, 'done'),
(7312, 'در لوله U شکل روبه‌رو که حاوی آب است، سطح مقطع لوله در همه‌جای آن یکسان و برابر $2cm^{2}$ است. شخصی با دمیدن در یک شاخه آن، سطح آب را در آن شاخه به‌اندازه $5cm$ پایین می‌آورد. بزرگی نیروی واردشده از طرف هوای درون ریه شخص بر سطح آب چند نیوتون است؟ \r\n\r\n($P_\\circ = 10^5 Pa$ ، $g = 10 \\frac{m}{s^2}$ و $\\rho_{\\text{آب}} = 1 \\frac{g}{cm^3}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:42', 5, 'done'),
(7313, 'ظرفی مطابق شکل در اختیار داریم که مساحت سطح بخش پهن و باریک آن به‌ترتیب $10cm^2$ و $5cm^2$ است. اگر به اندازه $3400g$ جیوه درون ظرف بریزیم، بزرگی نیرویی که جیوه بر کف ظرف وارد می‌کند، چند نیوتون است؟\r\n\r\n ($g = 10 \\frac{m}{s^2}$ ، $\\rho_{\\text{جیوه}} = 13/6 \\frac{g}{cm^3}$ و $P_\\circ = 98/2 kPa$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:34', 5, 'done'),
(7314, 'دو مایع مخلوط‌نشدنی (۱) و (۲) مانند شکل، درون ظرفی استوانه‌ای قرار دارند و فشار در نقطه B درون مایع (۲)، دو برابر فشار نقطه A درون مایع (۱) است. چگالی مایع (۲) چند گرم بر سانتی‌متر مکعب است؟ \r\n\r\n($g = 10 \\frac{m}{s^2}$ و $P_\\circ = 10^5 Pa$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:25', 5, 'done'),
(7315, 'آهنگ شارش حجمی آب در یک لوله با مقطع دایره‌ای، $ \\frac{m^3}{s}$0.012 است. اگر تندی آب در این لوله $10 \\frac{m}{s}$ باشد، قطر مقطع لوله چند میلی‌متر است؟ ($\\pi = 3$)', 1, 2, 76, 329, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:16', 5, 'done'),
(7316, 'چه تعداد از موارد زیر درست است؟\r\n\r\nالف) فاصله ذرات جسم جامد در حدود یک آنگستروم و فاصله ذرات مایع در حدود یک نانومتر است.\r\n\r\nب) کروی بودن قطره‌های آب در حال سقوط ناشی از نیروی کشش سطحی بین مولکول‌های آب است.\r\n\r\nپ) افزایش دما باعث افزایش نیروی هم‌چسبی مولکول‌های مایع می‌شود.\r\n\r\nت) افزودن مایع شوینده به آب باعث افزایش نیروی کشش سطحی در مایعات می‌شود.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:07', 5, 'done'),
(7317, 'در یک استوانه، تا ارتفاع $h$ از مایعی به چگالی $\\rho$ ریخته‌ایم. قطعه فلز توپری به چگالی $10\\rho$ را به آرامی درون استوانه می‌اندازیم و سطح مایع به‌اندازه $\\frac{h}{5}$ بالاتر می‌آید. جرم قطعه فلز چند برابر جرم مایع است؟', 1, 2, 76, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:13:00', 5, 'done'),
(7318, 'درون مکعبی فلزی به ضلع $5cm$ و جرم $718g$، حفره‌ای کروی به شعاع $2cm$ وجود دارد. اگر این حفره را از آب پر کنیم، چگالی این جسم (مکعب حاوی آب) چند گرم بر سانتی‌متر مکعب ($\\frac{g}{cm^3}$) می‌شود؟\r\n\r\n ($\\rho_{\\text{آب}} = 1 \\frac{g}{cm^3}$ و $\\pi = 3$)', 1, 2, 76, 324, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:12:47', 5, 'done'),
(7319, 'چه تعداد از جملات زیر درست است؟\r\n\r\nالف) فاصله میانگین مولکول‌های گاز در مقایسه با اندازه آن‌ها خیلی بیشتر است.\r\n\r\nب) تراکم‌پذیری مایع‌ها از گازها خیلی بیشتر است.\r\n\r\nپ) دلیل پخش ذرات جوهر در آب، حرکت‌های نامنظم مولکول‌های آب و برخورد آن‌ها با ذرات جوهر است.\r\n\r\nت) مولکول $NaCl$ یک جامد بی‌شکل است.', 1, 2, 76, 325, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:12:34', 5, 'done'),
(7320, 'ماده درون ستارگان جزو کدام‌یک از حالت‌های ماده است؟', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:12:26', 5, 'done'),
(7321, 'شکل داده‌شده، می‌تواند نشان‌دهنده لوله شیشه‌ای مویینی باشد که درون ............ قرار دارد و در آن نیروی هم‌چسبی بین مولکول‌های مایع، ............ از نیروی دگرچسبی میان مولکول‌های مایع و سطح لوله است.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:12:19', 5, 'done'),
(7322, 'وقتی مقداری از مایع A را روی سطح جسم B قرار می‌دهیم، سطح آن را تر می‌کند. حال اگر یک لوله مویین از جنس B بسازیم و درون یک ظرف از مایع A قرار دهیم، در این صورت سطح مایع درون لوله ............', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:12:09', 5, 'done'),
(7323, 'چه تعداد از گزاره‌های زیر درست است؟\r\n\r\nالف) فشار در عمق معینی از یک مایع، به چگالی مایع بستگی دارد.\r\n\r\nب) فشار وارد بر سطحی که درون مایعی در عمق $h$ قرار دارد، به جهت‌گیری آن سطح بستگی دارد.\r\n\r\nپ) نیروی وارد بر سطح کوچکی که درون مایعی در عمق $h$ قرار دارد، به مساحت آن سطح بستگی دارد.', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:12:01', 5, 'done'),
(7324, 'در مخزنی حاوی یک مایع مطابق شکل، اگر فشار در نقطه A برابر $1.08\\times 10^{5} Pa$ و در نقطه B برابر $1.4 \\times 10^5 Pa$ باشد، چگالی مایع چند گرم بر سانتی‌متر مکعب است؟ ($g = 10 \\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:11:55', 5, 'done'),
(7325, 'مطابق شکل، مقداری آب، روغن و جیوه درون لوله Uشکلی ریخته شده که سطح مقطع آن در دو شاخه متفاوت است. دو سطح جیوه درون لوله در یک تراز قرار دارند و شاره‌ها در حال تعادل هستند. چگالی روغن چند گرم بر سانتی‌متر مکعب ($\\frac{g}{cm^3}$) است؟ \r\n\r\n($\\rho_{\\text{آب}} = 1 \\frac{g}{cm^3}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:11:46', 5, 'done'),
(7326, 'در شکل روبه‌رو فشار گاز محبوس در لوله سمت چپ، چند پاسکال است؟\r\n\r\n ($g = 10 \\frac{N}{kg}$ و $\\rho_{\\text{جیوه}} = 13600 \\frac{kg}{m^3}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:11:29', 5, 'done'),
(7327, 'مطابق شکل، لوله Uشکلی به یک مخزن گاز متصل بوده و اختلاف سطح جیوه در دو طرف لوله برابر $h_1 = 20cm$ است. اگر با افزایش دمای گاز، اختلاف سطح جیوه در دو طرف لوله به $h_2 = 30cm$ برسد، فشار پیمانه‌ای گاز درون مخزن چند کیلوپاسکال و چگونه تغییر می‌کند؟ \r\n\r\n($g = 10 \\frac{N}{kg}$ و $\\rho_{\\text{جیوه}} = 13600 \\frac{kg}{m^3}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:11:22', 5, 'done'),
(7328, 'مطابق شکل، از شیر آبی که مساحت دهانه آن $A_1=2cm^{2}$ است، آب با تندی $4\\frac{m}{s}$ خارج می‌شود. اگر بدانیم تندی آب پس از $x$ متر سقوط از رابطه $v_2^{2}-v_1^{2}=2gx$ به‌دست می‌آید ($v_1$ تندی اولیه و $v_2$ تندی ثانویه است)، مساحت سطح مقطع آب در $45cm$ پایین‌تر از دهانه شیر ($A_2$)، چند سانتی‌متر مربع خواهد بود؟ ($g=10\\frac{N}{kg}$ و جریان آب را به‌صورت لایه‌ای در نظر بگیرید.)', 1, 2, 76, 329, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:11:16', 5, 'done'),
(7329, 'شکل روبه‌رو، مدلی از ساختار یک ........................ است که در این مدل، اگر ذرات جسم نسبت به وضعیت تعادل جابه‌جا شوند، فنرها آن‌ها را به حالت اولیه برمی‌گردانند تا جسم ........................ را حفظ کند.', 1, 2, 76, 325, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:11:05', 5, 'done'),
(7330, 'جسمی توپر مطابق شکل، درون دریاچه‌ای به‌صورت عمودی در حالت تعادل قرار دارد. مساحت سطح بالایی آن دو برابر مساحت سطح پایینی آن است ($A_1=2A_2$). اگر نیرویی که از طرف مایع به سطح بالایی و پایینی وارد می‌شود برابر باشد، ارتفاع $h$ چند متر خواهد بود؟\r\n\r\n ($\\rho_{\\text{آب}}=1000\\frac{kg}{m^{3}}$ و $g=10\\frac{N}{kg}$ و $P_0=10^{5}Pa$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:10:56', 5, 'done'),
(7331, 'مطابق شکل، لوله مایل بلندی حاوی مایعی با چگالی  $0.9\\frac{g}{cm^3}$ است. فشار در کف این لوله چند کیلوپاسکال است؟ \r\n\r\n($P_{\\text{هوا}}=10^{5}Pa$ و $g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:10:46', 5, 'done'),
(7332, 'مطابق شکل، درپوشی به وزن $200N$ و سطح مقطع $100cm^{2}$ را روی سطح آب ظرفی می‌گذاریم؛ به‌طوری که کاملاً دهانه ظرف را می‌بندد. اگر فشار هوای محیط $10^{5}Pa$ باشد، فشار در چه فاصله‌ای از درپوش ($h$) برابر $1/4\\times 10^5Pa$ خواهد بود؟\r\n\r\n ($\\rho_{\\text{آب}}=1000\\frac{kg}{m^{3}}$ و $g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:10:37', 5, 'done'),
(7333, 'دو مایع مخلوط‌نشدنی مطابق شکل، در ظرف U شکلی قرار دارند. $P_A-P_B$ چند پاسکال است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:10:29', 5, 'done'),
(7334, 'در لوله U شکل زیر، آب و جیوه در تعادل هستند و مساحت سطح مقطع شاخه سمت راست $2cm^{2}$ و مساحت سطح مقطع شاخه سمت چپ $1cm^{2}$ است. چند سانتی‌متر مکعب آب به شاخه سمت راست اضافه نماییم تا فشار در نقطه A به‌اندازه $2cmHg$ بیشتر شود؟ \r\n\r\n($\\rho_{\\text{جیوه}}=13/6\\frac{g}{cm^{3}}$ و $\\rho_{\\text{آب}}=1\\frac{g}{cm^{3}}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:10:17', 5, 'done'),
(7335, 'در لوله U شکل روبه‌رو با سطح مقطع $2cm^{2}$، حجم‌های مساوی از آب و روغن ریخته‌ایم. نیرویی که هوای درون ریه شخص بر سطح روغن وارد می‌کند، چند نیوتون بیشتر از نیرویی است که هوای محیط بر سطح آب وارد می‌کند؟\r\n\r\n ($P_{\\text{هوای محیط}}=10^{5}Pa$ و $g=10\\frac{m}{s^{2}}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:10:09', 5, 'done'),
(7336, 'لوله‌ای مطابق شکل، درون ظرف پر از آبی قرار دارد. با سرد شدن هوای محبوس درون لوله، سطح آب درون لوله بالا می‌آید؛ به‌طوری که $10cm$ بالاتر از سطح آب درون ظرف قرار می‌گیرد. اگر فشار هوای محبوس در لوله در اثر سرد شدن $4kPa$ کاهش یافته باشد، $h$ چند سانتی‌متر است؟\r\n\r\n ($\\rho_{\\text{آب}}=1000\\frac{kg}{m^{3}}$ و $g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:09:59', 5, 'done'),
(7337, 'مقداری آب و جیوه در ظرفی مطابق شکل ریخته شده‌اند. اگر فشار هوای محیط  ^{5}Pa$ $10 باشد، فشار در نقطه A چند پاسکال است؟ \r\n\r\n($\\rho_{\\text{آب}}=1000\\frac{kg}{m^{3}}$ و $\\rho_{\\text{جیوه}}=13600\\frac{kg}{m^{3}}$ ، $g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:09:48', 5, 'done'),
(7338, 'مطابق شکل، سه جسم در ظرف آبی قرار دارند. با توجه به نیروهای وارد بر اجسام (نیروی شناوری و نیروی وزن) کدام‌یک از گزینه‌های زیر به‌ترتیب توصیف درستی از وضعیت سه جسم A، B و C است؟', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:09:39', 5, 'done'),
(7339, 'در شکل روبه‌رو، فشار هوای محیط$9.6\\times 10^{4}Pa$است. اگر در این لوله مایعی با چگالی $\\rho=1/2\\frac{g}{cm^{3}}$ باشد، ارتفاع مایع در لوله نسبت به سطح مایع درون ظرف ($x$) چقدر است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:09:31', 5, 'done'),
(7340, 'ارتفاع دو شهر شیراز و یاسوج از سطح دریا به‌ترتیب $1500$ متر و $1800$ متر است. اگر چگالی میانگین هوا تا ارتفاع ۳ کیلومتری از سطح دریای آزاد حدوداً $\\overline{\\rho}=1/01\\frac{kg}{m^{3}}$ باشد، فشار هوای شیراز ........................ از فشار هوای یاسوج ........................ است. ($g=10\\frac{N}{kg}$)', 1, 2, 76, 327, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:09:22', 5, 'done'),
(7341, 'دو جسم (۱) و (۲) با نخی به هم متصل هستند و مجموعه به حال غوطه‌ور درون آب قرار دارد. $F_1$ و $F_2$ نیروهای شناوری و $W_1$ و $W_2$ وزن آن‌ها و $\\rho_1$ و $\\rho_2$ چگالی آن‌ها است و از طرف دو جسم بر نخ نیرو وارد می‌شود. کدام گزینه نادرست است؟', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:09:12', 5, 'done'),
(7342, 'جوسنج روبه‌رو فشار هوا را چند سانتی‌متر جیوه نشان می‌دهد؟', 1, 2, 76, 327, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:08:58', 5, 'done'),
(7343, 'یک جسم را که چگالی آن کمتر از چگالی آب است، درون آب می‌اندازیم. این جسم ........................ و در این حالت بزرگی نیروی شناوری وارد بر آن، ........................', 1, 2, 76, 328, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-24 20:08:21', 1, '2026-03-26 20:08:44', 5, 'done'),
(7344, ' تندی جسمی به جرم $ 8\\text{ kg}$، $ 36\\text{ km/h}$ افزایش می‌یابد. اگر در اثر این تغییر، انرژی جنبشی آن $ 1/6\\text{ kJ}$ تغییر کند، تندی اولیه جسم چند کیلومتر بر ساعت است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 20:08:33', 5, 'done'),
(7345, ' در شکل زیر جسم تحت تأثیر نیروی $\\vec{F}$ که اندازه آن، برابر وزن جسم است، روی سطح شیب‌دار به سمت بالا در حال حرکت است. در یک جابه‌جایی معین، نسبت کار انجام‌شده توسط نیروی $\\vec{F}$ به کار انجام‌شده توسط نیروی وزن جسم کدام است؟ ($\\cos 53^\\circ = 0/6$)', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 20:08:23', 5, 'done'),
(7346, 'خودرویی به جرم یک تن با تندی$ 54\\text{ km/h}$ در مسیری مستقیم در حال حرکت است. نیروی خالص وارد بر خودرو با فرض ثابت‌بودن، چند نیوتون و در چه جهتی باشد تا پس از $10\\text{ m}$ جابه‌جایی، انرژی جنبشی خودرو به $ 100\\text{ kJ}$ برسد؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 20:08:09', 5, 'done'),
(7347, 'دو جسم A و B به جرم‌های $m_A = m$ و $m_B = 2m$ روی سطح افقی بدون اصطکاکی ساکن هستند. اگر به این دو جسم به ترتیب نیروهای خالص و افقی $ 2\\vec{F}$ و $\\vec{F}$ وارد شود، پس از جابه‌جایی یکسان آن‌ها، تندی جسم A چند برابر تندی جسم B خواهد بود؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:54:53', 5, 'done'),
(7348, 'جسمی تحت تأثیر نیروی خالص و ثابت $\\vec{F}$ شروع به حرکت می‌کند. اگر کار کل انجام‌شده روی جسم در ثانیه اول حرکت $ 10\\text{ J}$ باشد، کار کل انجام‌شده روی آن در ثانیه دوم حرکت چند ژول است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:54:45', 5, 'done'),
(7349, 'مطابق شکل جعبه ساکنی به جرم $ 4\\text{ kg}$ را روی سطح افقی توسط نیروی $\\vec{F}$ می‌کشیم. پس از $ 5\\text{ m}$ جابه‌جایی، نیروی $\\vec{F}$ قطع شده و جعبه پس از طی $ 2/5\\text{ m}$ دیگر متوقف می‌شود. اگر بزرگی نیروی اصطکاک وارد بر جعبه $\\frac{1}{5}$ وزن جعبه باشد، اندازه نیروی $\\vec{F}$ چند نیوتون است؟ ($g = 10\\text{ N/kg}$)', 1, 2, 77, 332, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:54:35', 5, 'done'),
(7350, 'مطابق شکل، جسمی را با تندی ثابت از یک سطح شیبدار بالا می‌کشیم. برای این جسم کدام موارد الزاماً درست است؟\n\nالف) تغییرات انرژی مکانیکی برابر با منفی کار نیروی وزن است.\n\n\n\nب) کار نیرویی که سطح به جسم وارد می‌کند، صفر است.\n\nپ) کار نیروی خالص برابر با تغییر انرژی درونی جسم و سطح است.\n\nت) انرژی مکانیکی جسم افزایش می‌یابد.', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:54:11', 5, 'done'),
(7351, 'در شکل زیر گلوله‌ای از نقطه A رها شده و از دو نقطه B و C به ترتیب با تندی‌های $ 6\\text{ m/s}$ و $ 8\\text{ m/s}$ عبور می‌کند. کار نیروی اصطکاک در مسیر BC چند برابر کار این نیرو در مسیر AB است؟ ($g = 10\\text{ N/kg}$ و مقاومت هوا ناچیز است.)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:53:24', 5, 'done'),
(7352, 'در شکل زیر تندی توپ از لحظه پرتاب تا رسیدن به سبد $ 2\\text{ m/s}$ تغییر می‌کند. اگر کار نیروی مقاومت هوا تا رسیدن توپ به سبد، $\\frac{1}{4}$ کار نیروی وزن باشد، توپ با تندی چند متر بر ثانیه وارد سبد می‌شود؟ ($g = 10\\text{ N/kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:53:07', 5, 'done'),
(7353, 'بالنی با سرعت ثابت $ 20\\text{ m/s}$ در راستای قائم به سمت بالا حرکت می‌کند. هنگامی که بالن در ارتفاع ۱۰۰ متری سطح زمین قرار دارد، گلوله‌ای از آن رها می‌شود. در لحظه‌ای که تندی گلوله نصف تندی آن در لحظه برخورد با سطح زمین است، ارتفاع گلوله از سطح زمین چند متر است؟ ($g = 10\\text{ N/kg}$ و مقاومت هوا ناچیز است.)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:52:50', 5, 'done'),
(7354, 'گلوله‌ای به جرم $ 200\\text{ g}$ با تندی $ 20\\text{ m/s}$ از سطح زمین در راستای قائم به سمت بالا پرتاب می‌شود. اگر گلوله با تندی $ 10\\text{ m/s}$ به سطح زمین برگردد، تندی آن در نصف ارتفاع اوج هنگام پایین‌آمدن چند متر بر ثانیه است؟ (بزرگی نیروی مقاومت هوا در طی مسیر رفت و برگشت را ثابت در نظر بگیرید و $g = 10\\text{ m/s}^2$ است.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:52:27', 5, 'done'),
(7355, 'در شکل دو جسم مشابه A و B به جرم $ 2\\text{ kg}$ را در شرایط خلاء به ترتیب در راستای قائم و روی سطح شیبداری با تندی $v$ به سمت بالا پرتاب می‌کنیم. اگر اندازه نیروی اصطکاک بین جسم B و سطح شیبدار ثابت و برابر $ 6\\text{ N}$ باشد و جسم A تا ارتفاع ۲ متری نقطه پرتاب بالا رود، جسم B چه مسافتی را روی سطح شیبدار بالا می‌رود؟ ($g = 10\\text{ N/kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:52:14', 5, 'done'),
(7356, ' توان خودرویی به جرم $ 1500\\text{ kg}$ برابر با $ 160\\text{ hp}$ است. خودرو در یک جاده افقی حرکت می‌کند و طی مدت $ 5\\text{ s}$ تندی آن از $ 72\\text{ km/h}$ به $ 108\\text{ km/h}$ می‌رسد. بازده خودرو در هنگام انجام این کار چند درصد است؟ ($ 1\\text{ hp} = 750\\text{ W}$ و از نیروهای اتلافی صرف نظر کنید.)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:52:02', 5, 'done'),
(7357, ' یک پمپ الکتریکی با توان ورودی $ 6\\text{ kW}$ در مدت $ 4 $ دقیقه، $ 3\\text{ m}^3$ آب را با تندی ثابت از چاهی به عمق $6$ متر از سطح زمین به منبع آبی به ارتفاع $18$ متر از سطح زمین منتقل می‌کند. بازده این پمپ چند درصد است؟ ($g = 10\\text{ m/s}^2$ و چگالی آب $ 1\\text{ g/cm}^3$ است.)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:51:55', 5, 'done'),
(7358, 'در نیروگاه سوخت فسیلی شکل زیر با سوختن هر لیتر گازوئیل $ 30\\text{ MJ}$ انرژی گرمایی تولید می‌شود. برای این‌که یک لامپ رشته‌ای $100$ واتی به مدت $ 6\\text{ h}$ روشن بماند، در نیروگاه چند لیتر گازوئیل مصرف می‌شود؟', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:51:48', 5, 'done'),
(7359, 'اگر تندی یک جسم $ 10\\text{ km/h}$ افزایش یابد، انرژی جنبشی جسم $44$ درصد تغییر می‌کند. تندی نهایی جسم، چند کیلومتر بر ساعت خواهد بود؟', 1, 2, 77, 330, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:51:32', 5, 'done'),
(7360, 'مطابق شکل‌های زیر، شخصی در حالت اول با طنابی بلند (شکل ۱) و در حالت دوم با طنابی کوتاه‌تر (شکل ۲) جعبه‌ای را روی سطح افقی بدون اصطکاک از حال سکون با نیروی ثابت می‌کشد. اگر جابه‌جایی جعبه و کاری که شخص روی جعبه انجام می‌دهد در دو حالت یکسان باشد، کدام مقایسه درباره اندازه نیروی شخص ($F$) و تندی نهایی جعبه ($v$) در دو حالت درست است؟', 1, 2, 77, 331, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:51:22', 5, 'done'),
(7361, 'جسمی روی سطح بدون اصطکاکی مطابق شکل زیر، از نقطه A با تندی $ 4\\text{ m/s}$ پرتاب می‌شود و با تندی $ 10\\text{ m/s}$ از نقطه C عبور می‌کند. ارتفاع نقطه C از سطح زمین چند متر است؟ ($g = 10\\text{ m/s}^2$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:51:00', 5, 'done'),
(7362, 'مطابق شکل روبه‌رو جسمی به جرم $ 2\\text{ kg}$ از پایین سطح شیب‌دار بدون اصطکاکی با تندی $ 4\\text{ m/s}$ به سمت بالا پرتاب می‌شود. انرژی جنبشی جسم پس از طی مسافت $ 0/6\\text{ m}$ به چند ژول می‌رسد؟ (سطح افقی را مبدأ انرژی پتانسیل گرانشی در نظر بگیرید. $g = 10\\text{ N/kg}$ ، $\\cos 53^\\circ = 0/6$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:50:48', 5, 'done'),
(7363, 'مطابق شکل زیر به یک جعبه ساکن، نیروی افقی $F = 45\\text{ N}$ اثر می‌کند و پس از $ 12\\text{ m}$ جابه‌جایی، تندی جسم به $ 6\\text{ m/s}$ می‌رسد. در این جابه‌جایی چند ژول از انرژی مکانیکی جسم به انرژی درونی جسم و محیط تبدیل شده است؟', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:50:35', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7364, 'جسمی به جرم $ 40\\text{ kg}$ از ارتفاع ۲۰۰ متری سطح زمین با تندی $ 5\\text{ m/s}$ پرتاب می‌شود. اگر تندی جسم در لحظه برخورد به زمین $ 15\\text{ m/s}$ باشد، کار انجام‌شده روی جسم توسط نیروی مقاومت هوا، از لحظه رهاشدن تا لحظه رسیدن آن به زمین چند کیلوژول است؟ ($g = 10\\text{ N/kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:50:21', 5, 'done'),
(7365, 'گلوله‌ای را با تندی $ 20\\text{ m/s}$ در راستای قائم و به سمت بالا پرتاب می‌کنیم. این گلوله با تندی $ 18\\text{ m/s}$ به محل پرتاب بازمی‌گردد. با فرض برابربودن کار نیروی مقاومت هوا در مسیر رفت و مسیر برگشت، حداکثر ارتفاعی که گلوله نسبت به محل پرتاب بالا می‌رود، چند متر است؟ ($g = 10\\text{ N/kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:50:09', 5, 'done'),
(7366, 'جسمی را مطابق شکل روبه‌رو، روی سطح شیب‌داری از نقطه A رها می‌کنیم. اگر مسافت طی‌شده در سطح شیب‌دار در قسمت AB، دو برابر قسمت BC و تندی جسم در نقطه B، $ 4\\text{ m/s}$ باشد، تندی جسم در نقطه C چند متر بر ثانیه است؟ (ضریب اصطکاک جنبشی برای تمام سطح یکسان است.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:49:52', 5, 'done'),
(7367, 'تندی خودرویی به جرم $ 900\\text{ kg}$ در مسیری افقی و در مدت $ 3\\text{ s}$ از $ 54\\text{ km/h}$ به $ 90\\text{ km/h}$ می‌رسد. در این مدت، توان متوسط موتور این خودرو حداقل چند اسب بخار است؟ ($ 1\\text{ hp} = 750\\text{ W}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:49:38', 5, 'done'),
(7368, ' یک پمپ آب در هر دقیقه، $ 600\\text{ kg}$ آب را از چاهی به عمق $ 12\\text{ m}$ به سطح زمین آورده و آن را با تندی $ 4\\text{ m/s}$ پرتاب می‌کند. توان خروجی این پمپ چند کیلووات است؟ ($g = 10\\text{ m/s}^2$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:06', 1, '2026-03-26 19:49:30', 5, 'done'),
(7369, ' خلبان یک هواپیمای اطفای حریق، در اثر تخلیه آب مخزن، جرم هواپیما را ۵۰ درصد کاهش می‌دهد. اگر خلبان تندی هواپیما را ۲۰ درصد افزایش دهد، انرژی جنبشی هواپیما چند درصد و چگونه تغییر می‌کند؟', 1, 2, 77, 330, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:49:22', 5, 'done'),
(7370, '۴- برای این‌که کار نیروی خالص وارد بر یک جسم در جابه‌جایی از نقطه ۱ تا نقطه ۲ صفر باشد در این‌صورت الزاماً ...................', 1, 2, 77, 367, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:49:06', 5, 'done'),
(7371, ' مطابق شکل‌های زیر، جسم A را از پایین سطح شیبدار با تندی $v$ به‌سمت بالا و جسم B را روی سطح افقی با تندی $v$ پرتاب می‌کنیم. اگر جرم دو جسم با هم برابر باشند، از لحظه پرتاب تا لحظه توقف، نسبت جابه‌جایی جسم A روی سطح شیب‌دار به جابه‌جایی جسم B روی سطح افقی چه‌قدر است؟ ($g = ۱۰ \\frac{N}{kg}$ و نیروی اصطکاک روی هر دو سطح را $۱۰\\%$ وزن جسم درنظر بگیرید.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:48:55', 5, 'done'),
(7372, ' مطابق شکل زیر، جسمی به جرم $۲kg$ از نقطه A با تندی $۱۰ \\frac{m}{s}$ روی سطح افقی پرتاب و در ادامه وارد سطح شیب‌دار بدون اصطکاک می‌شود. اگر در هر متر جابه‌جایی روی سطح افقی AB، $۴$ ژول از انرژی جسم به انرژی درونی تبدیل شود، حداکثر جابه‌جایی جسم روی سطح شیب‌دار چند متر است؟ ($\\sin ۵۳^{\\circ} = ۰/۸ , g = ۱۰ \\frac{m}{s^۲}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:48:39', 5, 'done'),
(7373, '۷- جسمی به جرم $۲kg$ با تندی $۱۰ \\frac{m}{s}$ از سطح زمین در راستای قائم به طرف بالا پرتاب می‌شود و حداکثر تا ارتفاع $۴$ متر بالا می‌رود. در مسیر بازگشت، با در نظر گرفتن سطح زمین به عنوان مبدأ انرژی پتانسیل گرانشی، در چه ارتفاعی از سطح زمین برحسب متر، انرژی پتانسیل گرانشی جسم $\\frac{۴}{۵}$ برابر انرژی جنبشی آن است؟ ($g=۱۰\\frac{m}{s^۲}$ و نیروی مقاومت هوا را در کل مسیر ثابت در نظر بگیرید.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:48:17', 5, 'done'),
(7374, ' پمپی در مدت $۵$ دقیقه، مقداری مایع را تا ارتفاع $۲۰$ متر بالا برده و آن را با تندی $۲۰\\sqrt{۳} \\frac{m}{s}$ از دهانه لوله‌ای بیرون می‌ریزد. اگر توان خروجی پمپ $۴۰۰ W$ و بازده آن $۷۵$ درصد باشد، حجم مایعی که در این مدت از دهانه لوله به بیرون می‌ریزد، چند متر مکعب است؟ ($\\rho_{\\text{مایع}} = ۲/۲۵ \\frac{g}{cm^۳} , g=۱۰\\frac{N}{kg}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:48:07', 5, 'done'),
(7375, ' مطابق شکل زیر جسم $M$ به جرم $۱/۵ kg$ روی سطح افقی بدون اصطکاکی به سمت چپ در حال حرکت است. اگر پس از $۲۰ m$ جابه‌جایی به سمت چپ، تندی جسم از $۸ \\frac{m}{s}$ به $۴ \\frac{m}{s}$ برسد، کار نیروی $F_1$ در این جابه‌جایی برحسب ژول کدام است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:47:58', 5, 'done'),
(7376, ' گلوله‌ای به جرم $۵۰۰$ گرم را از ارتفاع $h$ از سطح زمین با انرژی جنبشی $۲۶ J$ در راستای قائم به سمت بالا پرتاب می‌کنیم. این گلوله حداکثر تا ارتفاع $\\frac{۵h}{۴}$ از سطح زمین بالا می‌رود و سپس به سطح زمین باز می‌گردد. اگر نیروی مقاومت هوا وجود نداشته باشد، انرژی جنبشی گلوله در لحظه رسیدن به سطح زمین چند ژول می‌شود؟ (اندازه نیروی مقاومت هوا را در حالت اول ثابت و برابر $۱/۵ N$ در نظر بگیرید. $g=۱۰ \\frac{N}{kg}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:47:47', 5, 'done'),
(7377, ' در شرایط خلأ، جسمی از ارتفاع $۱/۲۵$ متری سطح زمین رها می‌شود و پس از برخورد به زمین تا ارتفاع $۰/۸ m$ برمی‌گردد. تندی جسم در برخورد به زمین چند درصد کاهش می‌یابد؟', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:47:29', 5, 'done'),
(7378, '۱۲- در شکل مقابل، اگر اندازه نیرو و زاویه بین نیرو و جابه‌جایی هر کدام $۵۰$ درصد افزایش یابد، کار این نیرو در همان جابه‌جایی چند برابر می‌شود؟', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:47:18', 5, 'done'),
(7379, ' در شرایط خلأ و از سطح زمین جسمی به جرم $۴ kg$ را با تندی $۱۵ \\frac{m}{s}$ در امتداد قائم رو به بالا پرتاب می‌کنیم. انرژی مکانیکی آن در لحظه‌ای که فاصله آن تا سطح زمین $\\frac{۲}{۳}$ ارتفاع اوج است، چند ژول است؟ ($g=۱۰ \\frac{N}{kg}$ و سطح زمین را مبدأ انرژی پتانسیل گرانشی در نظر بگیرید.)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:47:07', 5, 'done'),
(7380, '۱۴- اتومبیلی به وزن ۸۰۰۰ نیوتون در یک مسیر مستقیم در حال حرکت است. اگر تندی این اتومبیل در مدت ۲۰ ثانیه از $۲۰\\frac{m}{s}$ به $۴۰\\frac{m}{s}$ برسد، توان متوسط برایند نیروهای وارد بر این اتومبیل چند کیلووات است؟ ($g=۱۰\\frac{N}{kg}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:46:50', 5, 'done'),
(7381, '۱۵- یک پمپ با توان مصرفی $۲۰ kW$ مایع ساکنی را از عمق ۵ متری زمین تا سطح زمین بالا آورده و با تندی $۱۰\\frac{m}{s}$ خارج می‌کند. اگر در مدت ۰/۹ ثانیه، $۱۰^۵ cm^۳$ مایع توسط این پمپ به بیرون کشیده شود، بازده آن چند درصد است؟ ($g=۱۰\\frac{m}{s^۲}$، $\\rho_{\\text{مایع}} = ۰/۹\\frac{g}{cm^۳}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:46:43', 5, 'done'),
(7382, '۱۶- وقتی کار نیروی خالص وارد بر جسمی در یک مسیر صفر باشد، کدام‌یک از موارد زیر در مورد این جسم، الزاماً صحیح است؟\r\n\r\nالف) سرعت جسم ثابت است.\r\n\r\nب) تغییر انرژی جنبشی جسم صفر است.\r\n\r\nپ) نیروی خالص وارد بر جسم صفر است.\r\n\r\nت) تغییر انرژی پتانسیل جسم صفر است.', 1, 2, 77, 367, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:46:34', 5, 'done'),
(7383, '۱۷- مطابق شکل مقابل، جسمی به جرم $۲kg$ توسط نیروی ثابت $F = ۱۸/۴ N$ از حال سکون روی سطح شیب‌دار شروع به حرکت می‌کند و پس از ۵ متر جابه‌جایی روی سطح، تندی آن به $۴\\frac{m}{s}$ می‌رسد. در این جابه‌جایی، چند ژول از انرژی جسم به انرژی درونی جسم و سطح تبدیل شده است؟ ($\\cos ۳۷^{\\circ} = ۰/۸ , g = ۱۰\\frac{m}{s^۲}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:46:09', 5, 'done'),
(7384, ' مطابق شکل مقابل، جسمی به جرم $m$ تحت تأثیر نیروی $\\vec{F}$ از حال سکون روی سطح افقی دارای اصطکاکی شروع به حرکت می‌کند و پس از طی مسافت $۴m$، انرژی جنبشی آن به $۲۴J$ می‌رسد. اگر بزرگی نیروی اصطکاک وارد بر جسم $۳N$ باشد، اندازه $\\vec{F}$ چند نیوتون است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:43:38', 5, 'done'),
(7385, ' در شکل زیر، نمودار انرژی جنبشی برحسب تندی برای جسمی به جرم $۲kg$، نشان داده شده است. اگر تندی این جسم به $v+۳۰$ متر بر ثانیه برسد، انرژی جنبشی آن چند ژول می‌شود؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:43:27', 5, 'done'),
(7386, '۲۰- مطابق شکل زیر، شخصی، سنگی به جرم $۵۰g$ را از پشت بام برجی به ارتفاع $۴۰m$، با تندی $۱۰\\frac{m}{s}$ پرتاب می‌کند. اگر سنگ با تندی $۲۰\\frac{m}{s}$ به سطح زمین برخورد کند، کار نیروی مقاومت هوا از لحظه پرتاب سنگ تا لحظه رسیدن آن به زمین چند ژول است؟ ($g=۱۰\\frac{m}{s^۲}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:36:44', 5, 'done'),
(7387, '۲۱- می‌خواهیم جسم کوچکی به جرم ۲۰۰ گرم را در دو آزمایش از سطح زمین بلند کنیم. در آزمایش اول می‌خواهیم آن را به اندازه ۱ متر از سطح زمین بلند کرده و با تندی ۴ متر بر ثانیه رو به بالا پرتاب کنیم. در آزمایش دوم می‌خواهیم آن را تا ارتفاعی بلند کرده و دوباره به حالت سکون برسانیم. ارتفاع جسم در آزمایش دوم چند متر باشد تا کار انجام شده توسط دست در هر دو آزمایش برابر گردد؟ ($g=۱۰\\frac{N}{kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:35:49', 5, 'done'),
(7388, '۲۲- توان ورودی موتوری $۵kW$ و بازده آن ۸۰ درصد است. این موتور جرثقیلی با بازده ۲۵ درصد را به کار می‌اندازد. این جرثقیل در مدت چند ثانیه جسمی به جرم $۲۵۰kg$ را با تندی ثابت تا ارتفاع ۱۲ متری بالا می‌برد؟ ($g=۱۰\\frac{m}{s^۲}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:34:54', 5, 'done'),
(7389, '۲۳- انرژی جنبشی جسمی $۳۶۰۰J$ است. اگر به تندی اولیه این جسم $۶\\frac{m}{s}$ اضافه شود، انرژی جنبشی‌اش در حالت جدید $۳/۲۴ \\times ۱۰^۴ J$ می‌شود. تندی اولیه جسم چند متر بر ثانیه بوده است؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:34:47', 5, 'done'),
(7390, '۲۴- چه تعداد از عبارت‌های زیر درست است؟\r\n\r\nالف) اگر کار برایند نیروهای وارد بر جسمی صفر باشد، الزاماً برایند نیروهای وارد بر آن جسم نیز صفر است.\r\n\r\nب) اگر کار برایند نیروهای وارد بر جسمی منفی باشد، الزاماً تندی جسم کاهش یافته است.\r\n\r\nپ) در حرکت ماهواره‌ها به دور زمین، انرژی جنبشی آن‌ها ثابت می‌ماند.\r\n\r\nت) همواره کار نیروی عمودی سطح برابر صفر است.', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:34:38', 5, 'done'),
(7391, ' چهار جسم با جرم‌های ($m_A=۴۰g, m_B=۲۰۰g, m_C=۱۶kg, m_D=۴kg$) با تندی‌های ثابت ($v_A=۴\\frac{m}{s}, v_B=۰/۸\\frac{m}{s}, v_C=۵\\frac{cm}{s}, v_D=۰/۲\\frac{m}{s}$) در حرکت هستند. انرژی جنبشی کدام جسم بزرگتر است؟', 1, 2, 77, 330, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:34:28', 5, 'done'),
(7392, '۲۶- نیروی $\\vec{F} = ۶۰\\vec{i} (N)$ به جسمی به جرم $۶kg$ وارد می‌شود و آن را روی سطح افقی به اندازه $\\Delta\\vec{x} = ۵\\vec{i}(m)+۴\\vec{j}(m)$ جابه‌جا می‌کند. کار نیروی $\\vec{F}$ در این جابه‌جایی چند ژول است؟', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:34:15', 5, 'done'),
(7393, '۲۷- مطابق شکل مقابل جسمی به جرم $m$ تحت تأثیر نیروهای $\\vec{F_۱}$ و $\\vec{F_۲}$ از حال سکون شروع به حرکت می‌کند. اگر نیروی اصطکاک وارد بر جسم $۱/۵N$ باشد، انرژی جنبشی جسم پس از طی مسافت ۴ متر چند ژول می‌شود؟ ($|\\vec{F_۱}| = ۱۵N , |\\vec{F_۲}| = ۱۸N , \\cos ۵۳^{\\circ} = ۰/۶$)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:34:02', 5, 'done'),
(7394, ' اگر کار نیروی خالص وارد بر جسمی به جرم $۲kg$ برابر $۲۷J$ و تندی اولیه جسم $۳\\frac{m}{s}$ باشد، پس از انجام این کار بر روی جسم، تندی آن به چند $\\frac{m}{s}$ می‌رسد؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:33:51', 5, 'done'),
(7395, '۲۹- مطابق شکل زیر، جعبه‌ای را با نیروی ثابت $\\vec{F}$ بر روی سطح افقی به اندازه $۱۲m$ جابه‌جا می‌کنیم. در این حالت کار انجام شده بر روی جعبه $W$ است. اگر بدون آنکه اندازه نیرو تغییر کند، زاویه بین بردار نیرو و جابه‌جایی را ۷ درجه کاهش دهیم، پس از چند متر جابه‌جایی، باز هم کار انجام شده بر روی جعبه برابر $W$ است؟ (اصطکاک ناچیز و $\\cos ۵۳^{\\circ} = ۰/۶$ است.)', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:33:42', 5, 'done'),
(7396, ' گلوله‌ای به جرم ۲۰۰g را از سطح زمین با تندی $۲۰\\frac{m}{s}$ در راستای قائم رو به بالا پرتاب می‌کنیم. اگر مقاومت هوا در مقابل حرکت گلوله ناچیز باشد، گلوله حداکثر تا ارتفاع ۲۰m بالا می‌رود. انرژی مکانیکی گلوله در ارتفاع ۱۸ متری سطح زمین، چند ژول است؟ ($g=۱۰\\frac{m}{s^۲}$ و سطح زمین را به عنوان مرجع انرژی پتانسیل گرانشی درنظر بگیرید.)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:33:28', 5, 'done'),
(7397, ' در شرایط خلأ جسمی از ارتفاعی رها می‌شود. انرژی جنبشی آن در نقطه‌ای که دو سوم مسیر را طی کرده است، چند برابر انرژی جنبشی آن در سطح زمین است؟', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:33:17', 5, 'done'),
(7398, ' مطابق شکل، یک موتور الکتریکی، بالای یک سطح شیب‌دار نصب شده است و از آن برای بالا کشیدن باری به جرم ۲ تن استفاده می‌شود. اگر این موتور بار را با تندی ثابت $۲۰\\frac{m}{s}$ بالا بکشد و $\\frac{۱}{۵}$ کار نیروی آن صرف غلبه بر اصطکاک گردد، توان این موتور چند کیلووات است؟ ($g=۱۰\\frac{m}{s^۲}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:33:08', 5, 'done'),
(7399, '۳۳- مطابق شکل، گلوله‌ای به جرم $۰/۲kg$ از نقطه A درون نیم‌کره‌ای به شعاع ۲ متر رها می‌شود. اگر انرژی تلف شده در ضمن حرکت از نقطه A تا B برابر ۲۵ درصد انرژی گلوله در نقطه A باشد، تندی گلوله هنگام عبور از نقطه B چند متر بر ثانیه است؟ ($g=۱۰\\frac{m}{s^۲}$ و $۰/۶=\\cos۵۳^\\circ, ۰/۸=\\cos۳۷^\\circ$ مبدأ پتانسیل گرانشی)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:32:51', 5, 'done'),
(7400, ' مطابق شکل زیر، جسمی به جرم $۲kg$ با تندی اولیه $۶\\frac{m}{s}$ از پایین سطح شیبداری به سمت بالا پرتاب می‌شود. اگر بیشترین ارتفاع جسم از نقطه پرتاب، ۱/۳۵ متر باشد، نیروی اصطکاک وارد بر جسم چند برابر وزن جسم است؟ ($\\sin ۳۷^{\\circ} = ۰/۶ , g = ۱۰\\frac{m}{s^۲}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:32:34', 5, 'done'),
(7401, ' اتومبیلی به جرم $۱۲۰۰kg$ روی مسیر مستقیم با شتاب ثابت در حرکت است و در مدت ۵ ثانیه تندی اتومبیل از $۳۶\\frac{km}{h}$ به $۷۲\\frac{km}{h}$ می‌رسد. اگر در این مدت توان متوسط نیروی موتور $۷۲kW$ باشد، اندازه کار نیروهای اتلافی چند کیلو ژول است؟', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:32:23', 5, 'done'),
(7402, '۳۶- جسمی به جرم $۴kg$ با تندی $۱۰\\frac{m}{s}$ از سطح زمین و در راستای قائم رو به بالا پرتاب می‌شود و با تندی $۴\\sqrt{۵}\\frac{m}{s}$ دوباره به زمین برمی‌گردد. در مسیر برگشت، وقتی جسم ۲۰ درصد از مسیر خود را طی می‌کند، تندی آن چند $\\frac{m}{s}$ خواهد شد؟ (نیروی مقاومت هوا در کل مسیر ثابت و $g=۱۰\\frac{m}{s^۲}$ است.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:32:05', 5, 'done'),
(7403, ' جسمی به جرم $4kg$ از بالاترین نقطه یک سطح شیب‌دار به طول $15$ متر تحت تأثیر نیروی $F$ و از حال سکون شروع به حرکت کرده و با تندی $6\\frac{m}{s}$ به پایین سطح می‌رسد. اگر بزرگی نیروی اصطکاک وارد بر جسم معادل $36N$ باشد، بزرگی نیروی $F$ چند نیوتن است؟ ($g=10\\frac{m}{s^2}, \\sin 37=0/6$)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:31:52', 5, 'done'),
(7404, ' گلوله $A$ به جرم $m$ از ارتفاع $80$ متری از سطح زمین رها می‌شود. اگر بخواهیم گلوله $B$ به جرم $4m$ را از ارتفاع $h$ با تندی اولیه $10\\frac{m}{s}$ در راستای قائم به طرف پایین پرتاب کنیم، مقدار $h$ چند متر باشد تا دو گلوله با انرژی جنبشی یکسان به زمین برخورد کنند؟ (مقاومت هوا ناچیز و $g=10\\frac{N}{kg}$ است.)', 1, 2, 77, 334, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:31:38', 5, 'done'),
(7405, '۳۹- گلوله‌ای به جرم $500$ گرم را با تندی اولیه $24\\frac{m}{s}$ از سطح زمین و در راستای قائم به سمت بالا پرتاب می‌کنیم. اگر نیروی مقاومت هوای وارد بر گلوله در طول مسیر حرکت آن ثابت و برابر $1N$ باشد، در چه ارتفاعی از سطح زمین و در مسیر بازگشت، انرژی جنبشی و انرژی پتانسیل گرانشی گلوله با هم برابر می‌شود؟ ($g=10\\frac{N}{kg}$ و سطح زمین را مبدأ انرژی پتانسیل گرانشی در نظر بگیرید.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:31:00', 5, 'done'),
(7406, ' نمودار سرعت - زمان جسمی به جرم $4kg$ که تحت تأثیر نیروی افقی $F$ روی یک سطح افقی بدون اصطکاک در حال حرکت است، مطابق شکل زیر است. اگر کار برایند نیروهای وارد بر این جسم در بازه زمانی صفر تا $12s$ برابر $+450J$ و اختلاف تندی جسم در ابتدا و انتهای این بازه زمانی برابر $5\\frac{m}{s}$ باشد، مسافت طی شده توسط جسم در این مدت، چند متر است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:31:27', 5, 'done'),
(7407, ' یک پمپ آب با توان $0/2kW$ که به مدت $\\frac{5}{3}$ دقیقه روشن می‌شود، $40$ لیتر آب ساکن را از عمق $20$ متری سطح زمین بالا آورده و با تندی $10\\frac{m}{s}$ درون مزرعه پرتاب می‌کند. بازده پمپ چقدر است؟ ($\\rho_{\\text{آب}} = 1\\frac{g}{cm^3}, g=10\\frac{N}{kg}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:31:12', 5, 'done'),
(7408, ' در شکل زیر، نمودار توان مفید یک دستگاه برحسب زمان نشان داده شده است. اگر توان متوسط کل مصرفی این دستگاه در مدت زمان $20$ ثانیه $1000W$ باشد، بازده آن چند درصد است؟', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:18:27', 5, 'done'),
(7409, ' جسمی به جرم $2kg$ را با تندی $4\\frac{m}{s}$ در راستای قائم به طرف بالا پرتاب می‌کنیم. وقتی جسم به نقطه پرتاب برمی‌گردد، تندی آن به $\\frac{1}{3}$ مقدار اولیه خود می‌رسد. ارتفاع اوج جسم از محل پرتاب چند متر بوده است؟ ($g=10\\frac{N}{kg}$ و نیروی مقاومت هوا در مسیر رفت و برگشت ثابت فرض می‌شود.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:17:59', 5, 'done'),
(7410, ' مطابق شکل زیر، جسمی به جرم $m$ را از نقطه $A$ با تندی $6\\frac{m}{s}$ به طرف بالای سطح شیب‌دار پرتاب می‌کنیم. این جسم در نقطه $B$ متوقف شده و در بازگشت، با تندی $4\\frac{m}{s}$ به نقطه $A$ برمی‌گردد. فاصله $A$ تا $B$ چند متر است؟ ($g=10\\frac{m}{s^2}$ و بزرگی نیروی اصطکاک در مسیر رفت و برگشت یکسان است.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:17:49', 5, 'done'),
(7411, ' مطابق شکل زیر، جسمی به جرم $2kg$ تحت اثر نیروی $F=40N$ قرار می‌گیرد. اگر معادله سرعت - زمان این جسم در SI به‌صورت $v=5t-3$ باشد، اندازه کار نیروی اصطکاک در بازه زمانی $t_1=1s$ تا $t_2=2s$ چند ژول است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:17:36', 5, 'done'),
(7412, ' مطابق شکل زیر جسمی به جرم $m$ روی سطح افقی دارای اصطکاکی به اندازه $d$ به سمت راست جابه‌جا می‌شود. اگر کار نیروی $\\vec{F}_1$ طی این جابه‌جایی $2$ برابر کار کل انجام شده بر روی جسم باشد، بزرگی نیروی $\\vec{F}_2$ چند برابر بزرگی نیروی اصطکاک وارد بر جسم است؟ ($|\\vec{F}_1|=2|\\vec{F}_2|, \\cos 53^\\circ = 0/6$)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:17:17', 5, 'done'),
(7413, ' گلوله‌ای از ارتفاع $20$ متری سطح زمین، با سرعت اولیه $4\\frac{m}{s}$ در راستای قائم رو به پایین پرتاب می‌شود. بعد از چند متر پایین رفتن گلوله، انرژی جنبشی آن $6$ برابر انرژی جنبشی اولیه می‌شود؟ ($g=10\\frac{m}{s^2}$ و از مقاومت هوا صرف‌نظر شود.)', 1, 2, 77, 334, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:17:02', 5, 'done'),
(7414, ' خودرویی به جرم $900kg$ در یک جاده افقی و از حال سکون شروع به حرکت می‌کند. اگر توان متوسط خودرو برابر $27$ کیلووات باشد، تندی آن پس از $15s$ به چند کیلومتر بر ساعت می‌رسد؟ (از نیروی مقاومت هوا و اصطکاک صرف‌نظر شود.)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:16:51', 5, 'done'),
(7415, ' شخصی توپی به جرم $1/5kg$ را از روی زمین برمی‌دارد و تا ارتفاع $12m$ بالا می‌برد و سپس آن را پرتاب می‌کند. اگر کل کار انجام شده توسط شخص روی توپ برابر با $192J$ باشد، تندی پرتاب توپ چند متر بر ثانیه بوده است؟ ($g=10\\frac{N}{kg}$ و از مقاومت هوا صرف‌نظر شود.)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:16:42', 5, 'done'),
(7416, ' مطابق شکل زیر، گلوله‌ای به جرم $2kg$ از مکان $(1)$ درون کره‌ای با تندی $2\\frac{m}{s}$ رو به پایین پرتاب می‌شود. در مکانی که برای اولین بار حاصل‌ضرب مقدار انرژی پتانسیل گرانشی و انرژی جنبشی گلوله بیشینه می‌شود، تندی گلوله چند $\\frac{m}{s}$ است؟ ($g=10\\frac{m}{s^2}$ و اتلاف انرژی نداریم)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:16:20', 5, 'done'),
(7417, ' مطابق شکل زیر، جسمی با تندی $v$ از پایین سطح شیب‌داری به سمت بالا پرتاب می‌شود. اگر در قسمتی از مسیر کار نیروی اصطکاک $25$ درصد اندازه کار نیروی وزن باشد، نسبت تغییرات انرژی پتانسیل گرانشی به تغییرات انرژی جنبشی در این جابه‌جایی چقدر است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:16:11', 5, 'done'),
(7418, ' از ارتفاع $30$ متری سطح زمین گلوله‌ای به جرم $500g$ را با تندی اولیه $20\\frac{m}{s}$ در راستای قائم به سمت بالا پرتاب می‌کنیم. اگر حداکثر ارتفاع گلوله از سطح زمین $45m$ باشد، تندی گلوله در لحظه برخورد با زمین چند $\\frac{m}{s}$ است؟ ($g=10\\frac{m}{s^2}$ و نیروی مقاومت هوای وارد بر گلوله را در طول مسیر حرکت ثابت در نظر بگیرید.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:15:52', 5, 'done'),
(7419, ' در شکل زیر، نمودار نیروی خالص وارد بر جسمی به جرم $1/5kg$، برحسب زمان رسم شده است. اگر این جسم در مبدأ زمان با تندی $8\\frac{m}{s}$ در خلاف جهت محور $x$ در حال حرکت باشد، توان متوسط نیروی خالص وارد بر آن در بازه زمانی صفر تا $14s$ چند وات است؟', 1, 2, 77, 370, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:15:30', 5, 'done'),
(7420, ' یک بالابر، باری به جرم $150kg$ را با تندی ثابت در راستای قائم بالا می‌برد. اگر توان مصرفی بالابر $500$ وات و بازده آن $75$ درصد باشد، تندی بار چند سانتی‌متر بر ثانیه است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:15:12', 5, 'done'),
(7421, ' در شرایط خلأ گلوله‌ای به جرم $m$ را از ارتفاع $10$ متری سطح زمین با تندی $5\\frac{m}{s}$ به سمت پایین پرتاب می‌کنیم. در چه ارتفاعی از سطح زمین برحسب متر انرژی پتانسیل گرانشی گلوله $4$ برابر انرژی جنبشی آن است؟ ($g=10\\frac{N}{kg}$ و مبدأ انرژی پتانسیل گرانشی را سطح زمین در نظر بگیرید.)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:15:02', 5, 'done'),
(7422, ' کدام‌یک از موارد زیر صحیح است؟\n\nالف) در حرکت یکنواخت بر روی خط راست در هر بازه زمانی دلخواه کار برایند نیروهای وارد بر جسم برابر صفر است.\n\nب) اگر برایند نیروهای وارد بر یک جسم در یک بازه زمانی مشخص صفر نباشد، الزاماً حرکت جسم در این بازه زمانی شتابدار است.\n\nپ) در حرکت شتابدار جسم بر روی خط راست در هیچ بازه زمانی کار برایند نیروهای وارد بر جسم نمی‌تواند صفر باشد.', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:14:52', 5, 'done'),
(7423, ' نمودار مکان - زمان متحرکی به جرم $500$ گرم که روی محور $x$ در حال حرکت است، مطابق شکل زیر است. اگر بزرگی شتاب متوسط متحرک در بازه زمانی صفر تا $4s$ برابر $2/5\\frac{m}{s^2}$ باشد، کار برایند نیروهای وارد بر جسم در این بازه زمانی، چند ژول است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:14:45', 5, 'done'),
(7424, ' مطابق شکل زیر، جسمی را با سرعت اولیه $20\\frac{m}{s}$ از پایین سطح شیب‌داری به طرف بالای سطح پرتاب می‌کنیم. اگر به ازای هر متری که جسم بر روی سطح شیب‌دار بالا می‌رود، $2$ درصد از انرژی اولیه جسم به‌صورت گرما تلف شود، این جسم حداکثر چه مسافتی برحسب متر را بر روی سطح شیب‌دار بالا خواهد رفت؟ ($\\sin 37^\\circ=0/6, g=10\\frac{m}{s^2}$ و مکان اولیه جسم را به عنوان مبدأ انرژی پتانسیل گرانشی در نظر بگیرید.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:14:31', 5, 'done'),
(7425, ' مطابق شکل زیر سه جسم $A$، $B$ و $C$ روی سطح افقی بدون اصطکاکی از حال سکون شروع به حرکت می‌کنند. در یک جابه‌جایی یکسان، اگر کار انجام شده توسط هر یک از این سه نیرو روی اجسام، $W_A$، $W_B$ و $W_C$ باشد، کدام گزینه در مورد مقایسه این سه کار صحیح است؟ ($|\\vec{F}_A|=|\\vec{F}_B|=|\\vec{F}_C|$)', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:14:20', 5, 'done'),
(7426, ' جسمی به جرم $2kg$ با سرعت ثابتی به بزرگی $v_1$ در حال حرکت است. اگر اندازه‌ی سرعت این جسم $8\\frac{m}{s}$ افزایش یابد، انرژی جنبشی آن $4$ برابر می‌شود. انرژی جنبشی جسم قبل از افزایش سرعت چند ژول بوده است؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:14:10', 5, 'done'),
(7427, ' جسمی از ارتفاع $30$ متری سطح زمین، بدون سرعت اولیه رها می‌شود و با سرعت $20\\frac{m}{s}$ به سطح زمین می‌رسد. اگر کار نیروی مقاومت هوا روی جسم طی این جابه‌جایی برابر با $30J$ باشد، جرم جسم چند کیلوگرم است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:13:58', 5, 'done'),
(7428, ' اتومبیلی به جرم یک تُن با سرعت $72\\frac{km}{h}$ در مسیری مستقیم و افقی در حال حرکت است. چه نیروی افقی‌ای برحسب نیوتون و در چه جهتی به اتومبیل وارد شود تا پس از $20m$ جابه‌جایی، انرژی جنبشی اتومبیل به $150kJ$ برسد؟ (از اصطکاک صرف‌نظر شود.)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:13:47', 5, 'done'),
(7429, ' مطابق شکل مقابل، جسمی به جرم $m=2kg$ با سرعت $5\\frac{m}{s}$ بر روی سطح شیب‌داری به‌سمت پایین پرتاب می‌شود و بعد از طی مسافت $20$ متر با سرعت $13\\frac{m}{s}$ به پایین سطح شیب‌دار می‌رسد. اندازه کار نیروی اصطکاک روی جسم در این مسیر چند ژول است؟ ($g=10\\frac{N}{kg}$، $\\sin 37^\\circ=0/6$ و در تمام این مدت جسم روی سطح شیبدار است.)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:13:40', 5, 'done'),
(7430, ' برای آن‌که تندی یک خودرو از حال سکون به $v$ برسد، باید به اندازه $0/01L$ سوخت مصرف شود. برای آن‌که تندی خودرو از $v$ به $2v$ برسد، چند لیتر سوخت لازم است؟ (از اتلاف انرژی صرف‌نظر کنید و فرض کنید تمام انرژی بدست آمده از سوخت صرف افزایش انرژی جنبشی خودرو می‌شود.)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:13:31', 5, 'done'),
(7431, ' مطابق شکل زیر، جسمی به جرم $2kg$ از نقطۀ $A$ و از حال سکون رها می‌شود و با تندی $20\\frac{m}{s}$ از نقطۀ $C$ می‌گذرد. تغییر انرژی پتانسیل گرانشی جسم در جابه‌جایی از نقطۀ $B$ تا $C$ چند ژول است؟ ($g=10\\frac{N}{kg}$ و نیروی اصطکاک و نیروی مقاومت هوا ناچیز است.)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:13:22', 5, 'done'),
(7432, ' جسمی به جرم $m=500g$ روی سطح افقی دارای اصطکاکی تحت تأثیر نیروی $\\vec{F}_1$ با تندی ثابت $10\\frac{m}{s}$ در حال حرکت است. اگر در لحظۀ $t_1$ نیروی $\\vec{F}_2 = -2\\vec{F}_1$ به جسم وارد شود، در لحظۀ $t_2$ تندی جسم بدون تغییر جهت آن $6\\frac{m}{s}$ می‌شود. کار نیروی اصطکاک در بازۀ $t_1$ تا $t_2$ چند ژول است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:13:09', 5, 'done'),
(7433, ' جسمی به جرم $m$ از پایین سطح شیب‌دار بدون اصطکاکی با تندی $18\\frac{m}{s}$ به‌سمت بالا پرتاب می‌شود. نسبت انرژی جنبشی جسم به انرژی پتانسیل گرانشی آن پس از طی مسافت $4/8m$ کدام است؟ (سطح زمین را مبدأ انرژی پتانسیل گرانشی درنظر بگیرید و $g=10\\frac{N}{kg}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:12:55', 5, 'done'),
(7434, ' نمودار سرعت - زمان جسمی به جرم $m$ که روی محور $x$ ها از حال سکون شروع به حرکت می‌کند، مطابق شکل زیر است. کار برایند نیروهای وارد بر جسم بین لحظات صفر تا $2s$ چند برابر کار برایند نیروهای وارد بر جسم بین لحظات $2s$ تا $4s$ است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:12:39', 5, 'done'),
(7435, ' شخصی آجری به جرم $2kg$ را از روی سطح زمین و از حال سکون در راستای قائم بالا می‌برد و سپس با سرعت ثابت $0/5\\frac{m}{s}$، در راستای افق و به اندازه $12m$ آن‌را جابه‌جا می‌کند. اگر اندازۀ جابه‌جایی کل آجر برابر با $15$ متر باشد، کار کل انجام شده توسط شخص طی این جابه‌جایی چند ژول است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:12:28', 5, 'done'),
(7436, ' در شرایط خلأ، جسمی را از ارتفاع $h$ از سطح زمین در راستای قائم به‌سمت بالا پرتاب می‌کنیم. در لحظه‌ای که انرژی جنبشی جسم $20$ درصد نسبت به لحظۀ پرتاب کاهش یابد، انرژی پتانسیل گرانشی آن $40$ درصد نسبت به حالت اول تغییر می‌کند. نسبت انرژی پتانسیل گرانشی اولیۀ جسم به انرژی جنبشی اولیۀ آن کدام است؟', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:12:11', 5, 'done'),
(7437, ' مطابق شکل زیر، جسمی به جرم $m$ درون نیم‌کره‌ای صیقلی به شعاع $R$، از نقطه‌ی $A$، تا نقطۀ $B$ جابه‌جا می‌شود. کار نیروی وزن در این جابه‌جایی برابر با کدام گزینه است؟ ($g$ شتاب گرانشی است.)', 1, 2, 77, 333, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:11:59', 5, 'done'),
(7438, '۷۲- کاهش انرژی پتانسیل گرانشی جسمی بر اثر سقوط از ارتفاع $6$ متری، برابر با $40$ ژول و افزایش انرژی جنبشی آن، برابر با $25$ ژول است. متوسط نیروی مقاومت هوا در برابر حرکت این جسم چند نیوتون است؟', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:11:00', 5, 'done'),
(7439, ' در شکل زیر، هواپیمایی که در ارتفاع $180$ متری از سطح زمین و با تندی $25\\frac{m}{s}$ در حال پرواز است، بسته‌ای را برای کمک به آسیب‌دیدگان زلزله رها می‌کند. اگر تنها نیروی مؤثر در حرکت بسته، نیروی وزن باشد، تندی آن هنگام برخورد به زمین چند متر بر ثانیه است؟ ($g=10\\frac{m}{s^2}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:10:51', 5, 'done'),
(7440, '۷۴- اگر بازده یک پمپ برحسب درصد برابر $\\eta$ باشد، در هر دقیقه رابطه نسبت انرژی تلف شده در این مجموعه به انرژی خروجی پمپ کدام است؟', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:10:23', 5, 'done'),
(7441, ' گلوله‌ای را با تندی اولیۀ $v$ در امتداد قائم به سمت بالا پرتاب می‌کنیم و گلوله تا ارتفاع $3$ متری بالا می‌رود. اگر در این مدت $40$ درصد انرژی جنبشی اولیۀ گلوله صرف غلبه بر مقاومت هوا شود، $v$ چند متر بر ثانیه است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:10:15', 5, 'done'),
(7442, ' مطابق شکل زیر، جسمی به جرم $m=200g$ روی سطح شیب‌دار از ارتفاع $4$ متری سطح زمین با تندی $10\\frac{m}{s}$ به طرف پایین پرتاب می‌شود. اگر مسافت طی شده توسط جسم از لحظۀ پرتاب تا لحظه‌ای که برای اولین بار روی سطح شیب‌دار طرف مقابل متوقف می‌شود $22m$ باشد، کار نیروی اصطکاک در این مدت چند ژول است؟ ($g=10\\frac{N}{kg}$، $\\sin 53^\\circ=0/8$، $\\sin 30^\\circ=0/5$)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:10:01', 5, 'done'),
(7443, ' در شرایط خلأ، گلوله‌ای را از ارتفاع $30$ متری سطح زمین با سرعت $20\\frac{m}{s}$ در راستای قائم به طرف بالا پرتاب می‌کنیم. تا لحظه‌ای که گلوله به سطح زمین باز گردد، کار نیروی وزن در بازۀ زمانی بالا رفتن گلوله، چند برابر کار نیروی وزن در بازۀ زمانی پایین آمدن آن است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:09:49', 5, 'done'),
(7444, ' مطابق شکل زیر، جسمی به جرم $m=2/5kg$، تحت تأثیر نیروی افقی $\\vec{F}$ قرار دارد. تندی آن در مدت زمان $4s$ از $2\\frac{m}{s}$ به $8\\frac{m}{s}$ می‌رسد. اگر توان متوسط نیروی $\\vec{F}$ در این بازۀ زمانی $40W$ باشد، کار نیروی اصطکاک در این مدت چند ژول است؟ (تندی جسم در طول مسیر حرکت هم‌جهت با نیروی $\\vec{F}$ است.)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:09:32', 5, 'done'),
(7445, ' یک پمپ آب در هر دقیقه ۲ تُن آب را از چاهی به عمق $10m$ به سطح زمین می‌آورد و آن را با تندی $20\\frac{m}{s}$ به بیرون می‌ریزد. اگر توان مصرفی پمپ $12/5kW$ باشد، بازده پمپ چند درصد است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:09:24', 5, 'done'),
(7446, ' شخصی در مدت زمان $30$ ثانیه جسمی به جرم $400$ گرم را از روی سطح زمین و از حال سکون بلند می‌کند و تا ارتفاع $100$ سانتی‌متری بالا برده و با تندی $10\\frac{m}{s}$ آن را پرتاب می‌کند. توان متوسط این شخص در این مدت چند وات است؟ (از نیروهای اتلافی صرف نظر کنید و $g=10\\frac{N}{kg}$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:09:16', 5, 'done'),
(7447, ' جسم A، به جرم $2m$ از ارتفاع ۵ متری سطح زمین با تندی $10\\frac{m}{s}$ پرتاب می‌شود و جسم B به جرم $4m$ از ارتفاع ۲۰ متری سطح زمین رها می‌شود. نسبت انرژی جنبشی جسم B به انرژی جنبشی A در لحظۀ رسیدن به زمین برابر با کدام گزینه است؟ (از مقاومت هوا صرف‌نظر شود و $g=10\\frac{N}{kg}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:09:09', 5, 'done'),
(7448, ' با توجه به شکل زیر، چند درصد از انرژی مفید خروجی از نیروگاه به لامپ می‌رسد؟', 1, 2, 77, 336, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:08:58', 5, 'done'),
(7449, ' اگر تندی جسمی به جرم $10kg$ در مدت $56$ ثانیه، به اندازۀ $20\\frac{m}{s}$ افزایش یابد، انرژی جنبشی آن ۳۶ برابر می‌شود. توان متوسط برایند نیروهای وارد بر جسم در این مدت چند وات است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:08:49', 5, 'done'),
(7450, ' گلوله‌ای فلزی از سطح زمین با تندی $20$ متر بر ثانیه رو به بالا پرتاب می‌شود. اگر نیروی مقاومت هوا، نصف نیروی وزن جسم باشد، در مسیر بالا رفتن در چه ارتفاعی از سطح زمین بر حسب متر، مقدار انرژی جنبشی گلوله یک چهارم انرژی پتانسیل گرانشی آن می‌شود؟ ($g=10\\frac{N}{kg}$ و سطح زمین را مبدأ انرژی پتانسیل گرانشی در نظر بگیرید.)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:08:39', 5, 'done'),
(7451, '۸۵- مطابق شکل زیر، گلوله‌ای به جرم $200g$ از نقطۀ (۱) به نقطۀ (۲) بر روی سطح شیب‌داری حرکت می‌کند. اگر در این حرکت، انرژی جنبشی گلوله $10J$ افزایش یابد، اندازۀ نیروی اصطکاک چند نیوتون است؟ ($\\sin 37^\\circ=0/6$، $g=10\\frac{N}{kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:08:27', 5, 'done'),
(7452, 'از بالای ساختمانی به ارتفاع $10m$، جسمی به جرم $2kg$ رها می‌شود. اگر این جسم با تندی $10\\frac{m}{s}$ به زمین برخورد کند، متوسط نیروی مقاومت هوا در طول مسیر حرکت آن چند نیوتن است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:08:12', 5, 'done'),
(7453, ' دو پمپ آب با توان الکتریکی و بازده برابر روی یک چاه آب به عمق $10$ متر قرار دارند. اگر پمپ اول در مدت ۲ دقیقه بتواند ۱۰ لیتر آب را از عمق چاه با تندی ثابت به سطح زمین بیاورد، پمپ دوم در مدت چند دقیقه می‌تواند ۵ لیتر آب را از عمق همین چاه به سطح زمین آورده و با تندی $10\\frac{m}{s}$ به بیرون بریزد؟ ($g=10\\frac{N}{kg}$ و چگالی آب را $1\\frac{g}{cm^3}$ در نظر بگیرید.)', 1, 2, 77, 336, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:08:02', 5, 'done'),
(7454, ' در شکل زیر، نمودار انرژی جنبشی خودرویی برحسب مربع تندی آن، نشان داده شده است. تندی این خودرو چند متر بر ثانیه باشد تا انرژی جنبشی آن برابر با $5kJ$ شود؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:07:52', 5, 'done'),
(7455, ' در شکل زیر، نیروی $\\vec{F}$ به جسمی به جرم $m$ وارد می‌شود و کار این نیرو در جابه‌جایی $\\vec{d}$ روی سطح افقی برابر $W$ است. اگر با تغییر دادن جهت نیرو، زاویۀ بین بردار نیرو و جابه‌جایی را بدون تغییر اندازۀ آن‌ها، ۱۶ درجه افزایش دهیم، کار نیروی $\\vec{F}$ به اندازۀ $60J$ تغییر می‌کند. $W$ چند ژول است؟ ($\\cos 53^\\circ=0/6$)', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:07:43', 5, 'done'),
(7456, ' جسمی بر روی یک سطح افقی بدون اصطکاک، ساکن است. این جسم توسط نیروی افقی و ثابت F روی سطح مسافت d را طی می‌کند و سپس وارد سطح دارای اصطکاک می‌شود و در این مسیر توسط همان نیروی F، مسافت 2d را طی می‌کند. اگر اندازۀ انرژی جنبشی در انتهای حرکت، ۲۰ درصد بیشتر از اندازۀ انرژی جنبشی در انتهای مسیر بدون اصطکاک باشد، نسبت اندازۀ نیروی اصطکاک جنبشی به نیروی F کدام است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:07:28', 5, 'done'),
(7457, ' شخصی به جرم $100kg$ درون آسانسوری قرار دارد و آسانسور از حال سکون و با شتاب ثابت $2\\frac{m}{s^2}$ رو به پایین شروع به حرکت می‌کند. کار نیرویی که کف آسانسور در ۲ ثانیۀ اول حرکت بر روی شخص انجام می‌دهد، چند ژول است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 367, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:07:15', 5, 'done'),
(7458, ' مطابق شکل زیر، گلوله‌ای به جرم $1kg$ با سرعت اولیۀ $v_0=20\\frac{m}{s}$ تحت زاویۀ $\\theta$ رو به بالا پرتاب می‌شود. اگر این گلوله با تندی $v=10\\frac{m}{s}$ از نقطۀ A (نقطۀ اوج) بگذرد، کار برایند نیروهای وارد بر گلوله از لحظۀ پرتاب تا لحظۀ رسیدن به نقطۀ اوج چند ژول است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:06:41', 5, 'done'),
(7459, ' دو قایق مخصوص، روی سطح افقی یخ زده و بدون اصطکاک دریاچه‌ای مطابق شکل زیر، قرار دارند. جرم یکی از قایق‌ها، ۴ برابر دیگری است. قایق‌ها تحت اثر نیروی مساوی باد شروع به حرکت می‌کنند و از خط پایان به فاصلۀ d می‌گذرند. درست پس از عبورشان از خط پایان، تندی قایق سبک‌تر، چند برابر تندی قایق دیگر است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:06:29', 5, 'done'),
(7460, ' شخصی جعبه‌ای را با نیروی یکسان F در دو حالت «الف» و «ب» روی سطح افقی به سمت راست جابه‌جا می‌کند. اگر اندازۀ کاری که شخص در هر دو حالت انجام می‌دهد بایکدیگر برابر باشد، نسبت جابه‌جایی جعبه در حالت «الف» به جابه‌جایی جعبه در حالت «ب» کدام است؟ ($\\cos 60^\\circ=\\frac{1}{2}$)', 1, 2, 77, 331, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:06:15', 5, 'done'),
(7461, ' در شکل زیر انرژی جنبشی جسمی به جرم $m=400g$ طی جابه‌جایی ۸۰ سانتی‌متر به سمت چپ، ۴ ژول تغییر می‌کند. اگر سطح افقی دارای اصطکاک باشد، کار نیروی اصطکاک طی این جابه‌جایی چند ژول است؟ ($\\sqrt{3}=1/7$)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:06:04', 5, 'done'),
(7462, ' چند مورد از گزاره‌های زیر صحیح است؟\n\nآ) در حرکت روی سطح افقی کار نیروی عکس‌العمل سطح همواره برابر صفر است.\n\nب) در حرکت ماهواره‌ها به دور زمین، کار نیروی گرانش وارد بر ماهواره برابر صفر است.\n\nپ) اگر تندی جسمی افزایش یابد، الزاماً بر روی جسم کار انجام شده است.\n\nت) اگر جهت بردار سرعت جسم تغییر کند، الزاماً بر روی جسم کار انجام شده است.', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:05:49', 5, 'done'),
(7463, ' گلوله‌ای به جرم $200g$ را با تندی اولیۀ $50\\frac{m}{s}$ از ارتفاع ۲۰ متری سطح زمین به سمت پایین پرتاب می‌کنیم. اگر مسافت طی شده توسط گلوله از لحظۀ پرتاب تا لحظه‌ای که پس از اولین برخورد به سطح زمین به ارتفاع اوج می‌رسد ۳۸ متر باشد، کار نیروی وزن وارد بر گلوله طی این جابه‌جایی چند ژول است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 333, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:05:36', 5, 'done'),
(7464, ' مطابق شکل زیر، جسمی به جرم m از نقطۀ A بدون سرعت اولیه رها می‌شود و حداکثر تا نقطۀ B بالا می‌رود. اگر اندازۀ کار نیروی اصطکاک در مسیر AB، $\\frac{3}{5}$ برابر انرژی پتانسیل گرانشی جسم در نقطۀ A باشد، نسبت $\\frac{h_A}{h_B}$ کدام است؟ (ارتفاع‌های $h_A$ و $h_B$ از مبدأ پتانسیل محاسبه شده‌اند.)', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:05:24', 5, 'done'),
(7465, ' در شرایط خلأ، جسمی را از سطح زمین به طرف بالا پرتاب می‌کنیم. اگر در ارتفاع $h_1$، انرژی پتانسیل گرانشی جسم ۳ برابر انرژی جنبشی آن و در ارتفاع $h_2$، انرژی پتانسیل گرانشی ۷ برابر انرژی جنبشی آن باشد، نسبت تندی جسم در ارتفاع $h_2$ به تندی در ارتفاع $h_1$ برابر با کدام گزینه است؟', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:05:07', 5, 'done'),
(7466, ' مطابق شکل زیر، جسمی از نقطۀ A روی یک سطح بدون اصطکاک رها می‌شود و به سمت نقاط B و C حرکت می‌کند. اگر تندی جسم در نقطۀ C، دو برابر تندی آن در نقطۀ B باشد، ارتفاع $h_C$ چند متر است؟ ($g=10\\frac{m}{s^2}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:04:55', 5, 'done'),
(7467, ' مطابق شکل زیر، جسمی به جرم m را از پایین سطح شیب‌داری با تندی اولیۀ $V=11\\frac{m}{s}$ به سمت بالای سطح شیب‌دار پرتاب می‌کنیم و با تندی $9\\frac{m}{s}$ مجدداً به نقطۀ پرتاب باز می‌گردد. حداکثر جابه‌جایی جسم روی سطح شیب‌دار از لحظۀ پرتاب، چند متر است؟ ($\\sin 30^\\circ=0/5$، $g=10\\frac{N}{kg}$)', 1, 2, 77, 332, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:04:44', 5, 'done'),
(7468, ' چند تعداد از عبارت‌های زیر در رابطه با مفاهیم دماسنجی درست است؟\n\nآ) صفر کلوین کمترین دمای ممکن است.\n\nب) برای دما حد بالایی وجود ندارد.\n\nپ) تغییر کمیت دماسنجی، اساس کار دماسنج‌ها است.\n\nت) یکی از مزایای دماسنج ترموکوپل، دقت بالای اندازه‌گیری آن است.', 1, 2, 77, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:04:27', 5, 'done'),
(7469, ' در آونگ شکل زیر، گلوله‌ای به جرم $200g$ به یک نخ سبک به طول $1m$ متصل شده است و از نقطۀ A با تندی $6\\frac{m}{s}$ عبور می‌کند. تندی گلوله در لحظه‌ای که زاویۀ آونگ با راستای قائم ۳۷ درجه می‌شود، چند متر بر ثانیه است؟ (مقاومت هوا ناچیز است، $\\sin 37^\\circ=0/6$ ، $g=10\\frac{N}{kg}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:04:18', 5, 'done'),
(7470, ' گلوله‌ای از نقطۀ A با تندی اولیۀ v پرتاب می‌شود. اگر گلوله در سمت مقابل مسیر، حداکثر $15m$ بالا رود و انرژی تلف شدۀ گلوله در این مسیر ۲۵ درصد انرژی جنبشی اولیه باشد، مقدار v چند $\\frac{m}{s}$ است؟ \n\n\n\n($g=10\\frac{N}{kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:04:05', 5, 'done'),
(7471, ' مطابق شکل زیر، جسمی به جرم $1kg$ از پایین سطح شیبداری تحت تأثیر نیروی ثابت $F=10N$ شروع به حرکت می‌کند و وقتی به ارتفاع ۳ متری نسبت به نقطۀ شروع حرکت می‌رسد، تندی‌اش به $5\\frac{m}{s}$ می‌رسد. بزرگی کار نیروی سطح روی جسم در این جابه‌جایی چند ژول است؟ ($g=10\\frac{m}{s^2}$)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:03:56', 5, 'done'),
(7472, ' مطابق شکل زیر توپی با تندی اولیۀ $12\\frac{m}{s}$ به سمت حلقۀ بسکتبال پرتاب می‌شود. اگر کار نیروی مقاومت هوا تا لحظۀ رسیدن به حلقه، $\\frac{1}{6}$ انرژی جنبشی اولیۀ توپ باشد، تندی توپ در لحظۀ ورود به حلقه چند متر بر ثانیه است؟ ($g=10\\frac{m}{s^2}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:03:41', 5, 'done'),
(7473, ' گلوله‌ای به جرم $200g$ را از سطح زمین با تندی $30\\frac{m}{s}$ در راستای قائم به سمت بالا پرتاب می‌کنیم. اگر از لحظۀ پرتاب تا لحظه‌ای که گلوله از ارتفاع ۱۵ متری سطح زمین عبور می‌کند، انرژی جنبشی آن ۴۰ درصد کاهش‌یافته باشد، کار نیروی مقاومت هوا در طی این جابه‌جایی، چند ژول است؟ ($g=10\\frac{N}{kg}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:03:29', 5, 'done'),
(7474, ' مطابق شکل زیر، توپی با تندی $10\\frac{m}{s}$ از نقطۀ A پرتاب می‌شود و با تندی $6\\frac{m}{s}$ به نقطۀ B می‌رسد و از آن می‌گذرد. انرژی تلف شدۀ جسم در طول مسیر ACB، چند برابر انرژی جنبشی آن در نقطۀ A است؟ ($g=10\\frac{m}{s^2}$)', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:03:16', 5, 'done'),
(7475, ' در شکل زیر، جسمی به جرم $1/5kg$ تحت تأثیر نیروی افقی $\\vec{F}$ با تندی ثابت از سطح شیبداری به طول $2m$ در مدت $4s$ بالا می‌رود. اگر نیروی اصطکاک وارد بر جسم $5N$ باشد، توان متوسط نیروی F طی این جابه‌جایی چند وات است؟ ($g=10\\frac{N}{kg}$ , $\\sin 37^\\circ=0/6$)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:03:03', 5, 'done'),
(7476, ' مطابق شکل زیر، جسمی به جرم $20kg$ را توسط نیروی افقی $\\vec{F}=200N$ از حال سکون به حرکت در می‌آوریم. در دو ثانیۀ دوم حرکت، اندازۀ کار نیروی سطح بر جسم چند برابر اندازۀ کار نیروی F بر جسم است؟ (ضریب اصطکاک جنبشی ۰/۲ و $g=10\\frac{N}{kg}$ است.)', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:31', 1, '2026-03-26 19:02:48', 5, 'done'),
(7477, ' جسم A با جرم $m$ و تندی $v$ دارای انرژی جنبشی # 1000\\text{ J}$ است. انرژی جنبشی جسم B که جرم آن $10$ درصد بیشتر و تندی آن $10$ درصد کمتر از جسم A است، برحسب ژول کدام است؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:02:04', 5, 'done'),
(7478, ' مطابق شکل، جسمی به جرم $ 2\\text{ kg}$ روی سطح افقی بدون اصطکاک در حرکت است. در فاصله A تا B، نیروی ثابت افقی $F = 60\\text{ N}$ بر آن وارد می‌شود و تندی جسم را از $v_A = 10\\frac{\\text{m}}{\\text{s}}$ به $v_B = 20\\frac{\\text{m}}{\\text{s}}$ می‌رساند و در فاصله B تا C، تحت تأثیر نیروی ثابت افقی $F\'$، تندی آن از $v_B = 20\\frac{\\text{m}}{\\text{s}}$ به $v_C = 30\\frac{\\text{m}}{\\text{s}}$ می‌رسد. اگر $AB = BC$ باشد، نیروی $F\'$ چند نیوتون از نیروی $F$ بیشتر است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:01:50', 5, 'done'),
(7479, ' در شکل روبه‌رو، شخصی جعبه‌ای را از حال سکون روی سطح افقی با نیروی ثابت و افقی $F = 160\\text{ N}$ حرکت می‌دهد. اگر ضریب اصطکاک جنبشی جعبه با سطح افقی $\\mu_k = 0/25$ بوده و کار کل نیروها روی جعبه در طی جابه‌جایی به‌اندازه $ 20\\text{ m}$ روی سطح افقی برابر $ 1200\\text{ J}$ باشد، جرم جعبه چند کیلوگرم است؟ $(g = 10\\frac{\\text{N}}{\\text{kg}})$', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:01:34', 5, 'done'),
(7480, 'مطابق شکل، جسمی به جرم $ 2/9\\text{ kg}$ از نقطه A روی سطح شیبدار به طرف بالا پرتاب می‌شود. اگر بزرگی نیروی اصطکاک جنبشی وارد بر جسم برابر $ 20\\text{ N}$ و کار کل نیروها روی جسم از نقطهٔ A تا نقطه B برابر $-1640\\text{ J}$ باشد، فاصله A تا B چند متر است؟ $(\\sin\\theta = \\frac{20}{29} \\text{ ، } g = 10\\frac{\\text{m}}{\\text{s}^2} \\text{ و } \\cos\\theta = \\frac{21}{29})$', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:01:22', 5, 'done'),
(7481, ' نیروی ثابت F به جسمی به جرم $ 4\\text{ kg}$ وارد می‌شود و آن را مطابق شکل از نقطه (1) به نقطه (2) منتقل می‌کند؛ به‌طوری که تندی آن را از $v_1 = 20\\frac{\\text{m}}{\\text{s}}$ در نقطه (1) به $v_2 = 30\\frac{\\text{m}}{\\text{s}}$ در نقطه (2) می‌رساند. اگر کار نیروی اصطکاک در این جابه‌جایی $ -1000\\text{ J}$ باشد، کار نیروی F در جابه‌جایی از نقطه (1) تا نقطه (2) چند ژول است؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 332, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:01:06', 5, 'done'),
(7482, 'کدام موارد نادرست بیان شده‌اند؟\n\nالف) وقتی کار نیروی وزن یک جسم در یک جابه‌جایی معین مثبت است، انرژی پتانسیل گرانشی جسم کاهش یافته است.\n\nب) کار نیروی وزن یک جسم در جابه‌جایی از یک نقطه تا نقطهٔ دیگر، به مسیری که جسم پیموده است، بستگی ندارد.\n\nپ) انرژی‌های پتانسیل گرانشی، کشسانی و الکتریکی به مکان اجسام یک سامانه نسبت به یکدیگر بستگی دارند.\n\nت) برای هر جسمی که در حال سقوط به طرف زمین است، هرچقدر انرژی پتانسیل گرانشی جسم کاهش یابد، به همان اندازه بر انرژی جنبشی جسم افزوده می‌شود.', 1, 2, 77, 333, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:00:43', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7483, 'دو جسم (1) و (2) مطابق شکل، به ترتیب از ارتفاع‌های $h_1$ و $h_2$ و از حال سکون رها می‌شوند تا روی سطوح شیب‌دار و بدون اصطکاک حرکت کنند. جسم (1) در عبور از نقطه A دارای انرژی جنبشی$ 650\\text{ J}$ و جسم (2) در عبور از نقطه C دارای انرژی جنبشی $ 440\\text{ J}$ است و هر دو جسم در عبور از نقطه B دارای انرژی جنبشی $ 400\\text{ J}$ هستند. ارتفاع $h_2$ چند متر بیشتر از ارتفاع $h_1$ است؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 334, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:00:34', 5, 'done'),
(7484, 'مطابق شکل، جسمی به جرم $ 2\\text{ kg}$ را از نقطه A با تندی $ 10\\frac{\\text{m}}{\\text{s}}$ روی سطح شیب‌دار به طرف پایین پرتاب می‌کنیم. جسم پس از پایین آمدن، مسیر افقی را طی می‌کند و حداکثر می‌تواند تا همان ارتفاع روی سطح شیب‌دار مقابل ( نقطه D) بالا برود. اگر $AB = BC = CD$ و کار نیروی اصطکاک به‌طور متوسط به ازای هر متر مسافت طی‌شده برابر $-2\\text{ J}$ باشد، ارتفاع $h$ برحسب متر کدام است؟ $(\\sin 37^\\circ = 0/6 \\text{ و } g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 335, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 19:00:00', 5, 'done'),
(7485, 'موتور خودرویی به‌طور متوسط نیروی $ 1492\\text{ N}$ وارد می‌کند و خودرو را در هر دقیقه به‌اندازه $ 1/8\\text{ km}$ در امتداد نیرو جلو می‌برد. توان متوسط نیروی موتور برحسب اسب بخار کدام است؟ $(1\\text{ hp} = 746\\text{ W})$', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:59:45', 5, 'done'),
(7486, 'تلمبه‌ای در مدت $5$ دقیقه، $60$ تن آب را تا ارتفاع $ 12\\text{ m}$ از سطح زمین بالا می‌برد. اگر توان تلف‌شده (هدررفته) آن $ 1000\\text{ W}$ باشد، بازده تلمبه چند درصد است؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 336, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:59:34', 5, 'done'),
(7487, 'جرم جسم A دو برابر جرم جسم B و تندی آن نصف تندی جسم B است. اگر اختلاف انرژی جنبشی آن‌ها $ 1000\\text{ J}$ باشد، انرژی جنبشی جسم B چند ژول است؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:59:24', 5, 'done'),
(7488, 'در شکل داده‌شده، جسمی به جرم $ 2\\text{ kg}$ روی یک سطح افقی بدون اصطکاک با تندی $v = 20\\frac{\\text{m}}{\\text{s}}$ به‌طرف چپ در حرکت است. این جسم در نقطه A، مطابق شکل تحت تأثیر دو نیروی ثابت و افقی $F_1 = 30\\text{ N}$ و $F_2 = 20\\text{ N}$ قرار می‌گیرد. کار نیروی $F_1$ از نقطه A تا نقطه‌ای که جسم متوقف می‌شود، چند ژول است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:59:15', 5, 'done'),
(7489, 'دو گلوله که جرم هریک $ 2\\text{ kg}$ است، در اختیار داریم. یکی را از ارتفاع $200$ متری از سطح زمین رها می‌کنیم و دومی را از سطح زمین به‌طور قائم به‌طرف آسمان پرتاب می‌کنیم. هنگامی که دو گلوله از ارتفاع H از سطح زمین عبور می‌کنند، انرژی جنبشی هریک برابر با $ 3000\\text{ J}$ است. تندی اولیه گلوله دوم هنگام پرتاب از سطح زمین برحسب متر بر ثانیه کدام است؟ (مقاومت هوا ناچیز است و $g = 10\\frac{\\text{N}}{\\text{kg}}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:26:17', 5, 'done'),
(7490, 'در شکل زیر، جسمی به جرم $ 2\\text{ kg}$ را از حال سکون توسط نخی با نیروی ثابت $F = 20\\text{ N}$ روی سطح افقی از نقطه A تا نقطه B می‌کشیم؛ به‌طوری که تندی جسم در نقطه B به $ 20\\frac{\\text{m}}{\\text{s}}$ می‌رسد. هنگامی که جسم به نقطه B می‌رسد، نخ پاره می‌شود و جسم به حرکت خود ادامه می‌دهد و در نقطه C می‌ایستد. اگر $AB = 40\\text{ m}$ باشد، کار نیروی اصطکاک در فاصله AB چند برابر کار نیروی اصطکاک در فاصله BC است؟ $(\\cos 37^\\circ = 0/8)$', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:25:55', 5, 'done'),
(7491, 'فوتبالیستی مطابق شکل، توپی به جرم $ 500\\text{ g}$ را از سطح زمین(نقطهA) با تندی $ 30\\frac{\\text{m}}{\\text{s}}$ شوت می‌کند؛ به‌طوری که بیشترین فاصله توپ از سطح زمین به $ 20\\text{ m}$ می‌رسد (نقطه B). اگر انرژی درونی توپ و هوا در مسیر AB، به‌علت اثر نیروی مقاومت هوا به‌اندازه $  25\\text{ J}$ افزایش یافته باشد، تندی توپ در نقطه B چند متر بر ثانیه است؟ $(g = 10\\frac{\\text{N}}{\\text{kg}})$', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:25:48', 5, 'done'),
(7492, 'تلمبه‌ای با توان متوسط ورودی $ 8\\text{ kW}$ و بازده $75$ درصد، برای بالابردن $ 12\\text{ m}^3$ آب تا ارتفاع $ 24\\text{ m}$ به کار گرفته شده است. برای این منظور، تلمبه چند دقیقه باید کار کند؟ $(\\rho_{\\text{آب}} = 1000\\frac{\\text{kg}}{\\text{m}^3} \\text{ و } g = 10\\frac{\\text{N}}{\\text{kg}})$', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:25:35', 5, 'done'),
(7493, 'مطابق شکل، جعبه‌ای به جرم $ 5\\text{ kg}$ با نیروی ثابت $F = 50\\text{ N}$ ، از نقطه A تا نقطه B روی یک سطح افقی کشیده می‌شود؛ به طوری که تندی جعبه از $ 2\\frac{\\text{m}}{\\text{s}}$ در نقطه A به $ 10\\frac{\\text{m}}{\\text{s}}$ در نقطه B می‌رسد. اگر نیروی اصطکاک ثابت و برابر با $f_k = 8\\text{ N}$ و فاصله A تا B برابر $ 10\\text{ m}$ باشد، $\\cos \\theta$ کدام است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:25:26', 5, 'done'),
(7494, 'ورزشکاری به جرم $ 80\\text{ kg}$ از ارتفاع $ 4/5\\text{ m}$ نسبت به سطح یک تشک بزرگ، خود را رها می‌کند. اگر ضخامت عادی تشک $ 2\\text{ m}$ باشد و کمترین ضخامت آن به دلیل فشردگی توسط ورزشکار به $ 0/5\\text{ m}$ برسد، بزرگی نیرویی که تشک بر ورزشکار وارد می‌کند، چند نیوتون است؟ ($g = 10\\frac{\\text{N}}{\\text{kg}}$ و اثر مقاومت هوا بر ورزشکار را ناچیز و نیروی تشک بر ورزشکار را ثابت فرض کنید.)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:25:16', 5, 'done'),
(7495, 'مطابق شکل، یک شخص در بار اول، توپی به جرم $ 400\\text{ g}$ را از نقطه A به ارتفاع $ 20\\text{ m}$ از سطح زمین به‌طور مایل و با تندی $v_0$ پرتاب می‌کند؛ به طوری که توپ در نقطه B با تندی $ 30\\frac{\\text{m}}{\\text{s}}$ به سطح زمین برخورد می‌کند. در بار دوم، این شخص توپ را با همان تندی $v_0$ ولی به‌طور قائم به طرف آسمان پرتاب می‌کند. اگر کار نیروی مقاومت هوا روی توپ در پرتاب اول از نقطه A تا B، $-30\\text{ J}$ و در پرتاب دوم از نقطه A تا بالاترین نقطه (نقطه اوج توپ) $-10\\text{ J}$ باشد، در پرتاب دوم توپ حداکثر چند متر از نقطه پرتاب بالاتر می‌رود؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 335, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:25:04', 5, 'done'),
(7496, 'توان متوسط ورودی موتور بالابری $ 50\\text{ kW}$ و بازده آن $80$ درصد است. این موتور بسته‌ای به جرم $ 10^4\\text{ kg}$ را در مدت چند ثانیه از سطح زمین تا ارتفاع $ 20\\text{ m}$ بالا می‌برد؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 336, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:24:53', 5, 'done'),
(7497, 'جسم کوچکی به جرم $ 0/5\\text{ kg}$ را مطابق شکل، از نقطه A با تندی $v_A = 20\\frac{\\text{m}}{\\text{s}}$ روی سطح شیب‌دار به طرف پایین پرتاب می‌کنیم. جسم پایین آمده و پس از پیمودن مسیر افقی $BC = 6\\text{ m}$ روی سطح شیب‌دار روبه‌رو بالا می‌رود. اگر بزرگی کار نیروی اصطکاک روی جسم به ازای پیمودن هر متر مسافت برابر با $ 2\\text{ J}$ باشد، جسم حداکثر تا چه ارتفاعی برحسب متر (h) بالا می‌رود؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:24:45', 5, 'done'),
(7498, 'موتور یک ماشین اسباب‌بازی با توان ورودی $ 8\\text{ W}$، آن را با تندی ثابت $ 0/6\\frac{\\text{m}}{\\text{s}}$ در یک مسیر مستقیم و افقی به جلو می‌برد. اگر مجموع بزرگی نیروهای اصطکاک و مقاومت هوا در مقابل آن $ 6\\text{ N}$ باشد، بازده موتور این ماشین چند درصد است؟', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:24:33', 5, 'done'),
(7499, 'یک پمپ با توان متوسط مصرفی $300$ وات و بازده $60$ درصد در مدت $2$ دقیقه، چند کیلوگرم آب را از چاهی در عمق $10$ متری بالا کشیده و با تندی $4$ متر بر ثانیه بیرون می‌ریزد؟ $(g = 10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:24:25', 5, 'done'),
(7500, 'کدام گزینه مقایسه درستی از انرژی جنبشی چهار جسم نشان داده‌شده در شکل است؟', 1, 2, 77, 330, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:24:18', 5, 'done'),
(7501, 'مطابق شکل، گلوله‌ای که با نخ از سقف آویزان است را از نقطه (۱) رها می‌کنیم تا در طرف دیگر به نقطه (۲) برسد. اگر مقاومت هوا و اصطکاک ناچیز باشد، کدام گزینه در مورد کار نیروی وزن و کار نیروی کشش نخ در این مسیر درست است؟', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:24:08', 5, 'done'),
(7502, 'مطابق شکل، جرم m تحت تأثیر نیروی F از نقطه A به نقطهB منتقل شده و کار نیروی اصطکاک در این جابه‌جایی W است. اگر جسم توسط همان نیروی F مجدداً به نقطه A بازگردانده شود، کار نیروی اصطکاک در مسیر بازگشت و در کل رفت و برگشت به‌ترتیب از راست به چپ کدام است؟ (بزرگی نیروی اصطکاک ثابت است.)', 1, 2, 77, 331, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:23:43', 5, 'done'),
(7503, 'مطابق شکل، جسمی به جرم $m$، از پایین سطح شیب‌داری با تندی $ 10\\frac{\\text{m}}{\\text{s}}$، مماس بر سطح به‌سمت بالا پرتاب می‌شود و تا ارتفاع ۳ متری از نقطه پرتاب بالا می‌رود. اگر اندازه نیروی اصطکاک هنگام بالا و پایین رفتن گلوله روی سطح ثابت باشد، جسم با چه تندی‌ای برحسب متر بر ثانیه به پایین سطح شیب‌دار برمی‌گردد؟ ($g=10\\frac{\\text{N}}{\\text{kg}}$)', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:23:31', 5, 'done'),
(7504, ' آن را فشرده می‌کند. اگر جابه‌جایی جسم از لحظه برخورد به فنر تا لحظه توقف $ 4\\text{cm}$ و کار نیروی فنر روی آن $W_{\\text{فنر}}=-60\\text{J}$ باشد، بزرگی نیروی اصطکاک جسم با سطح در این جابه‌جایی چند نیوتون است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:23:17', 5, 'done'),
(7505, 'جسمی را از ارتفاع ۲ متری سطح زمین تا ارتفاع ۱۰ متری بالا می‌بریم. یک بار مبدأ انرژی پتانسیل را سطح زمین در نظر می‌گیریم و تغییرات انرژی پتانسیل گرانشی جسم را حساب می‌کنیم ($\\Delta U_1$). بار دیگر مبدأ انرژی پتانسیل گرانشی را در ارتفاع ۲ متری از سطح زمین در نظر می‌گیریم و تغییرات انرژی پتانسیل گرانشی جسم را حساب می‌کنیم ($\\Delta U_2$). نسبت $\\frac{\\Delta U_2}{\\Delta U_1}$ کدام است؟', 1, 2, 77, 333, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:23:06', 5, 'done'),
(7506, '31-مطابق شکل، جسمی روی سطح شیب‌دار بدون اصطکاکی از نقطه A رها می‌شود، در نقطه B به فنری برخورد کرده و آن را فشرده می‌کند و نهایتاً در نقطه C برای لحظه‌ای متوقف می‌شود. اگر U مجموع انرژی پتانسیل گرانشی و انرژی پتانسیل کشسانی باشد، مقدار U در مسیر A تا C چگونه تغییر می‌کند؟ (فرض کنید در برخورد جسم به فنر اتلاف انرژی نداریم.)', 1, 2, 77, 334, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:22:55', 5, 'done'),
(7507, 'در شکل زیر، گلوله‌ای به جرم $m$ از نقطه A از حال سکون رها شده و روی مسیر دایره‌ای شکل به شعاع ۳ متر به حرکت درمی‌آید. اگر کل مسیر بدون اصطکاک باشد، در فاصله بین نقاط B و C، تندی گلوله چند متر بر ثانیه تغییر می‌کند؟ ($g=10\\frac{\\text{m}}{\\text{s}^2}$ و $\\sqrt{3}=1/7$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:22:44', 5, 'done'),
(7508, 'جسمی به جرم $ 0/5\\text{ kg}$ از پایین سطح شیب‌داری با تندی $ 20\\frac{\\text{m}}{\\text{s}}$ پرتاب شده و مسیری مطابق شکل را پیموده است. اگر اندازه نیروی اصطکاک در مسیر AB برابر $ 1/9\\text{ N}$ و مقاومت هوا در برابر حرکت جسم ناچیز باشد، تندی جسم در لحظه برخورد به زمین (نقطه C) چند متر بر ثانیه است؟ $(g=10\\frac{\\text{m}}{\\text{s}^2})$', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:16:20', 5, 'done'),
(7509, 'جسمی از ارتفاع ۴ متری سطح زمین، مطابق شکل الف رها می‌شود و پس از برخورد با فنر و فشردن کامل آن، مجموعه به‌صورت شکل ب درمی‌آید. اگر اندازه کار نیروی وزن در این جابه‌جایی $ 2\\text{ J}$ و اندازه کار نیروی مقاومت هوا، $ 0/1 $ اندازه کار نیروی وزن باشد، جرم جسم و بیشینه انرژی پتانسیل فنر به‌ترتیب کدام است؟ $(g=10\\frac{\\text{N}}{\\text{kg}})$', 1, 2, 77, 333, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:15:37', 5, 'done'),
(7510, 'خودرویی با توان متوسط $ 100\\text{ hp}$ توسط نیروی ثابت پیشرانی که وارد می‌کند، با تندی ثابت $ 30\\frac{\\text{m}}{\\text{s}}$ در جهت نیروی پیشران حرکت می‌کند (هر ثانیه ۳۰ متر در جهت نیروی پیشران به جلو می‌رود). اندازه نیروی پیشران خودرو چند نیوتون است؟ $(1\\text{hp}=750\\text{ W})$', 1, 2, 77, 336, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:15:16', 5, 'done'),
(7511, 'بالابری که مجموع جرم اتاقک و بار درون آن $ 900\\text{ kg}$ است، در مدت ۴۵ ثانیه با تندی ثابت، $ 60\\text{ m}$ بالا می‌رود. اگر توان ورودی موتور بالابر $ 20\\text{ kW}$ باشد، بازده آن چند درصد است؟ $(g=10\\frac{\\text{N}}{\\text{kg}})$', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:15:03', 5, 'done'),
(7512, 'متحرکی با تندی $ 10\\frac{\\text{m}}{\\text{s}}$ در حال حرکت است. به تندی این جسم چقدر اضافه شود تا انرژی جنبشی آن ۹ برابر شود؟', 1, 2, 77, 330, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:14:53', 5, 'done'),
(7513, 'نمودار تغییرات تندی یک متحرک برحسب زمان مطابق شکل است. کار کل انجام‌شده روی این متحرک در بازه زمانی $t=0$ تا $t=5\\text{s}$ چند برابر کار کل انجام‌شده در بازه زمانی $t=5\\text{s}$ تا $t=15\\text{s}$ است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:14:36', 5, 'done'),
(7514, 'مطابق شکل به جسم ساکنی به جرم $m$ در نقطه O، نیروی ثابت و افقی $F = 30\\text{ N}$ وارد می‌شود و پس از طی مسیر افقی $OA = 4\\text{ m}$ تندی جسم به $v$ می‌رسد. در نقطه A این نیرو حذف شده و جسم پس از طی مسیر $AB = 1\\text{ m}$ از نقطه B وارد مسیری می‌شود که در آن اصطکاک وجود دارد (اصطکاک در مسیر OB قابل چشم‌پوشی است). اگر تندی جسم در نقطه C برابر $\\frac{v}{2}$ باشد، اندازه نیروی اصطکاک در مسیر BC چند نیوتون است؟', 1, 2, 77, 332, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:14:24', 5, 'done'),
(7515, 'توپی را به‌طور قائم از سطح زمین با تندی $v_0$ به‌طرف آسمان پرتاب می‌کنیم؛ به‌طوری که حداکثر تا ارتفاع $ 45\\text{ m}$ از سطح زمین بالا می‌رود. در چند متری از سطح زمین، تندی توپ به $\\frac{1}{3}v_0$ می‌رسد؟ (مقاومت هوا ناچیز و $g = 10\\frac{\\text{m}}{\\text{s}^2}$ است.)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:14:05', 5, 'done'),
(7516, 'گلوله‌ای با جرم $ 200\\text{ g}$ به فنر سبکی که طول عادی خود را دارد، متصل شده و از نقطه A رها می‌شود. با پایین آمدن گلوله، فنر کشیده شده و گلوله نهایتاً در نقطه B در ارتفاع $h$ متر پایین‌تر از نقطه A برای لحظه‌ای متوقف می‌شود. اگر انرژی پتانسیل کشسانی سامانه جرم - فنر در نقطه B برابر $ 3\\text{ J}$ باشد، $h$ چند متر است؟ (نیروهای اتلافی ناچیز است و $g = 10\\frac{\\text{N}}{\\text{kg}}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:13:51', 5, 'done'),
(7517, 'توپ ساکنی به جرم $m$ از ارتفاع ۲ متری سطح زمین رها می‌شود و پس از برخورد با زمین حداکثر تا ارتفاع ۱ متر بالا می‌آید. اگر ۲۰ درصد از انرژی تلف شده طی این مسیر، صرف گرم شدن توپ شده باشد، دمای توپ چند درجه سلسیوس افزایش یافته است؟ ($g = 10\\frac{\\text{m}}{\\text{s}^2}$ و $c_{\\text{توپ}} = 200\\frac{\\text{J}}{\\text{kg}\\cdot{}^\\circ\\text{C}}$)', 1, 2, 77, 334, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:13:36', 5, 'done'),
(7518, 'توان متوسط موتور یک خودرو با جرم $ 746\\text{ kg}$ برابر $ 30\\text{ hp}$ است. این خودرو در چند ثانیه می‌تواند تندی خود را از $ 36\\frac{\\text{km}}{\\text{h}}$ به $ 72\\frac{\\text{km}}{\\text{h}}$ برساند؟ ($ 1\\text{hp} = 746\\text{ W}$ و از تمام اتلاف‌های ناشی از اصطکاک صرف‌نظر شود.)', 1, 2, 77, 336, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:04:47', 1, '2026-03-26 18:13:10', 5, 'done'),
(7519, ' اندازه شعاع یک توپ فلزی از جنس A با شعاع یک حفره فلزی از جنس B یکسان است. برای اینکه توپ از حفره عبور کند، چه تعداد از گزاره‌های زیر می‌تواند راه حل مناسب باشد؟ ($\\alpha_A > \\alpha_B$)\n\n- دمای هر دو را به یک اندازه زیاد کنیم.\n\n- دمای هر دو را به یک اندازه کم کنیم.\n\n- A را سرد و B را گرم کنیم.\n\n- A را گرم و B را سرد کنیم.', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:55', 5, 'done'),
(7520, ' یک تانکر حمل سوخت، ۲۰۰۰۰ لیتر بنزین بارگیری کرده است. اگر دمای هوا در محل تحویل سوخت، $۳۰ K$ بیشتر از محلی باشد که سوخت، بارگیری شده است، راننده چند لیتر سوخت در محل جدید تحویل می‌دهد؟ ($\\frac{۱}{^\\circ F} \\times ۱۰^{-۴} \\times ۵ = \\text{ضریب انبساط حجمی بنزین}$)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:46', 5, 'done'),
(7521, ' نمودار تغییرات دما برحسب گرمای داده شده به جسمی به جرم $۲/۵ kg$، مطابق شکل مقابل است. اگر به این جسم $۹ kJ$ گرما بدهیم، دمای آن چند درجهٔ فارنهایت تغییر می‌کند؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:37', 5, 'done'),
(7522, ' یک گرمکن با توان ورودی $۱/۶ kW$ و بازده ۷۵ درصد، چند دقیقه کار کند تا $۸۰۰ g$ یخ در دمای $-۲۰^\\circ C$ را به آب $۶۰^\\circ C$ تبدیل کند؟ (گرمای نهان ذوب یخ $۳۳۶ \\frac{kJ}{kg}$ و گرمای ویژهٔ آب و یخ نیز به ترتیب برابر $۴۲۰۰ \\frac{J}{kg.K}$ و $۲۱۰۰ \\frac{J}{kg.K}$ است.)', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:29', 5, 'done'),
(7523, ' درون ظرفی $۲۰۰ g$ یخ $-۲۰^\\circ C$ وجود دارد. چند کیلوژول گرما به این یخ داده شود تا فقط $۵۰ g$ آب $۱۰۰^\\circ C$ درون ظرف باقی بماند؟ ($c_{\\text{یخ}} = ۲۱۰۰ \\frac{J}{kg^\\circ C} , c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg^\\circ C} , L_F = ۳۳۶۰۰۰ \\frac{J}{kg} , L_V = ۲۲۵۶۰۰۰ \\frac{J}{kg}$)', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:21', 5, 'done'),
(7524, ' کره‌ای فلزی به جرم $۶۴ g$ و شعاع $۲ cm$ در دمای $۲۹۳ K$ قرار دارد. اگر دمای گلوله به $۱۵۸^\\circ F$ برسد، چگالی آن چند $\\frac{kg}{m^۳}$ و چگونه تغییر می‌کند؟ ($\\alpha \\simeq ۱۰^{-۵} \\frac{۱}{K}$ و $\\pi \\simeq ۳$)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:12', 5, 'done'),
(7525, ' مطابق شکل زیر، دو میلهٔ افقی بر روی یک سطح افقی بدون اصطکاک قرار دارند. هنگامی‌که دمای میله‌ها به اندازهٔ $۵۰^\\circ C$ افزایش می‌یابد، فاصلهٔ آنها از هم تقریباً به صفر می‌رسد. $l$ چند متر است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:12:04', 5, 'done'),
(7526, ' در ظرفی $۸۷۰$ گرم آب صفر درجهٔ سلسیوس داریم. یک قطعه فلز به جرم $۵۸۰$ گرم با دمای $۴۲$ درجهٔ سلسیوس را درون آب می‌اندازیم. پس از برقراری تعادل، دمای مجموعه چند درجه سلسیوس می‌شود؟ (اتلاف گرما ناچیز، $c_{\\text{فلز}} = ۷۰۰ \\frac{J}{kg.K}$ و $c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.K}$ است.)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:11:53', 5, 'done'),
(7527, ' چند مورد از عبارت‌های زیر نادرست است؟\n\nالف) سهم ارتعاش اتم‌ها در رسانش گرمایی فلزات بیشتر از الکترون‌های آزاد است.\n\nب) روش همرفت در انتقال گرما، بر اثر کاهش چگالی شاره در اثر افزایش دما صورت می‌گیرد.\n\nپ) به‌طور عمده انتقال گرما از مرکز خورشید به سطح آن از طریق رسانش صورت می‌گیرد.\n\nت) کلم اسکانک به دلیل بالا رفتن دمایش، انرژی خود را از طریق تابش فرابنفش از دست می‌دهد.', 1, 2, 78, 341, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:11:45', 5, 'done'),
(7528, ' درون چالهٔ کوچکی، مقداری آب $۰^\\circ C$ وجود دارد. اگر در اثر تبخیر سطحی، بخشی از آب تبخیر شده و بقیهٔ آن یخ بزند، چند درصد از آب، یخ زده است؟ (تبادل گرما با محیط ناچیز و $L_V = ۷ L_F$ است.)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:11:35', 5, 'done'),
(7529, ' ۸۰ درصد از حجم یک ظرف به حجم ۲ لیتر را از مایعی با ضریب انبساط حجمی $۶ \\times ۱۰^{-۳} (^\\circ C)^{-۱}$ پر می‌کنیم. اگر دمای ظرف و مایع هم‌دمای آن را $۶۰^\\circ C$ بالا ببریم، مقدار $۳۲ cm^۳$ مایع از ظرف سرریز می‌شود. ضریب انبساط طولی ظرف در SI کدام است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:11:25', 5, 'done'),
(7530, ' $۰/۵$ کیلوگرم یخ $۰^\\circ C$ را داخل مقداری آب $۵۰^\\circ C$ می‌اندازیم. اگر پس از رسیدن به تعادل گرمایی، جرم آب داخل ظرف ۶۵۰ گرم باشد، چند درصد از یخ ذوب شده است؟ ($L_f = ۳۳۶ \\frac{J}{g} , c_{\\text{آب}} = ۴/۲ \\frac{J}{g.K}$)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:11:15', 5, 'done'),
(7531, ' کدام‌یک از عبارت‌های زیر نادرست است؟', 1, 2, 78, 341, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:11:07', 5, 'done'),
(7532, ' فلزی به جرم $۶۰۰ g$ با دمای $۶۰^\\circ C$ را درون $۱۰۰ g$ آب با دمای $۲۰^\\circ C$ قرار می‌دهیم. اگر نصف گرمایی که فلز از دست می‌دهد به محیط اطراف منتقل شود، دمای تعادل چند درجهٔ سلسیوس خواهد بود؟ ($c_{\\text{فلز}} = ۴۰۰ \\frac{J}{kg.^\\circ C} , c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C}$)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:10:53', 5, 'done'),
(7533, ' در وسط یک صفحهٔ فلزی نازک به ضریب انبساط سطحی $\\frac{۱}{^\\circ C} \\times ۲/۸ \\times ۱۰^{-۵}$ دایره‌ای به شعاع $۲۰ cm$ را در دمای صفر درجهٔ سلسیوس خارج نموده‌ایم. اگر دمای صفحه را به آرامی از $۰^\\circ C$ به $۱۵۰^\\circ C$ برسانیم، قطر دایره چند میلی‌متر خواهد شد؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:10:44', 5, 'done'),
(7534, ' مطابق شکل زیر، درون ظرفی تا ارتفاع $۴۰ cm$ از مایعی به چگالی $۲/۴ \\frac{g}{cm^۳}$ و ضریب انبساط حجمی $۴ \\times ۱۰^{-۳} \\frac{۱}{K}$ ریخته شده است. اگر دمای مایع ۹۰ درجهٔ فارنهایت افزایش یابد، نیروی وارد بر کف ظرف از طرف مایع چند نیوتون افزایش می‌یابد؟ (مساحت مقطع قسمت بالا و پایین به ترتیب برابر $۱۰ cm^۲$ و $۵۰ cm^۲$ و از انبساط ظرف صرف‌نظر شود و $g = ۱۰ \\frac{m}{s^۲}$)', 1, 2, 78, 338, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:10:35', 5, 'done'),
(7535, ' گرم‌کنی با توان ثابت P، دمای $۲ kg$ آب را در مدت ۵ دقیقه، $۲۰^\\circ C$ بالا می‌برد. اگر همان گرم‌کن دمای $۳ kg$ مایعی را در مدت ۱۰ دقیقه به همان اندازه بالا ببرد، نسبت گرمای ویژهٔ مایع به گرمای ویژهٔ آب کدام است؟', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:10:23', 5, 'done'),
(7536, ' نمودار تغییرات دمایی جسم جامدی، مطابق شکل زیر است. اگر به این جسم $۵۰۴ kJ$ گرما بدهیم، چند گرم از آن به‌صورت جامد باقی می‌ماند؟ (گرمای ویژهٔ جسم جامد $۲/۱ \\frac{kJ}{kg^\\circ C}$ است.)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:10:13', 5, 'done'),
(7537, ' کدام‌یک از عبارت‌های زیر صحیح است؟', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:09:56', 5, 'done'),
(7538, ' توان ورودی یک گرمکن الکتریکی $۲ kW$ است. اگر بازده این گرمکن برابر با ۸۰ درصد باشد، در مدت ۷ ساعت چند کیلوگرم یخ صفر درجهٔ سلسیوس را به آب با دمای $۴۰^\\circ C$ تبدیل می‌کند؟ ($L_F = ۳۳۶ \\frac{kJ}{kg} , c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg^\\circ C}$)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:09:46', 5, 'done'),
(7539, ' نمودار مساحت سطح یک کره برحسب دمای آن، مطابق شکل زیر است. اگر دمای کره را به $۷۷^\\circ F$ برسانیم، شعاع آن نسبت به شعاعی که در دمای $۰^\\circ C$ داشته است، چند درصد افزایش می‌یابد؟', 1, 2, 78, 338, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:09:36', 5, 'done'),
(7540, ' اگر دمای دو کرهٔ هم‌جنس توپر A و توخالی B را به یک اندازه افزایش دهیم، شعاع آنها به یک اندازه افزایش می‌یابد. حال اگر به این دو کره به یک اندازه گرما دهیم، تغییر دمای کرهٔ A، $\\frac{۷}{۸}$ برابر تغییر دمای کرهٔ B می‌شود. در صورتی‌که، شعاع کرهٔ A برابر $۱۰ cm$ باشد، حجم حفرهٔ درون کره B چند سانتی‌متر مکعب است؟ ($\\pi \\simeq ۳$)', 1, 2, 78, 338, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:09:25', 5, 'done'),
(7541, ' اگر به مقداری آب صفر درجهٔ سلسیوس Q ژول گرما بدهیم، دمای آب را به ۱۰۰ درجهٔ سلسیوس می‌رساند. اگر $۴۶۵ kJ$ گرما به همان مقدار آب ۴۰ درجهٔ سلسیوس بدهیم، ۱۰۰ گرم از آب بخار می‌شود. Q چند کیلوژول است؟ ($L_V = ۲۲۵۰ \\frac{kJ}{kg}$)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:09:11', 5, 'done'),
(7542, ' داخل ظرف عایقی مقدار $\\frac{۶۴}{۹۰} kg$ یخ با دمای $-۲۰^\\circ C$ موجود است. حداقل چندگرم بخار آب جوش در فشار ۱ اتمسفر وارد ظرف کنیم تا تمام یخ موجود در ظرف ذوب شده و به آب $۰^\\circ C$ تبدیل شود؟ ($L_V = ۲۲۶۸ \\frac{kJ}{kg} , L_F = ۳۳۶ \\frac{J}{kg^\\circ C} , c_{\\text{یخ}} = ۲۱۰۰ \\frac{J}{kg.^\\circ C} , c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C}$)', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:08:57', 5, 'done'),
(7543, ' ۸۰۰ گرم آب $۲۰^\\circ C$ را با $۳۰۰g$ یخ صفر درجهٔ سلسیوس مخلوط می‌کنیم. پس از ایجاد تعادل چند گرم یخ ذوب نشده در ظرف باقی می‌ماند؟ $(c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg^\\circ C} , L_F = ۳۳۶۰۰۰ \\frac{J}{kg})$', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:08:46', 5, 'done'),
(7544, ' کدام‌یک از گزینه‌های زیر نادرست است؟', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:08:36', 5, 'done'),
(7545, ' اگر m گرم آب با دمای $\\theta_1$ را با 2m گرم آب با دمای $\\theta_2$ مخلوط کنیم، دمای تعادل مجموعه $۵۵^\\circ C$ خواهد شد. اگر 2m گرم آب با دمای $\\theta_1$ را با m گرم آب با دمای $\\theta_2$ مخلوط شوند دمای تعادل $۴۰^\\circ C$ خواهد شد. حاصل عبارت $\\theta_2 + \\theta_1$ برابر با چند درجهٔ سلسیوس است؟ (از مبادلهٔ گرما با محیط صرف‌نظر شود.)', 1, 2, 78, 339, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:08:27', 5, 'done'),
(7546, ' جسم جامدی با گرمای نهان ویژهٔ ذوب $L_F = ۷۵ \\times ۱۰^۳ \\frac{J}{kg}$ را با یک گرمکن ۲۰۰ واتی حرارت داده‌ایم اگر نمودار تغییرات دمای این جسم برحسب زمان، مطابق شکل مقابل باشد، گرمای ویژهٔ این جسم در حالت جامد چند واحد SI است؟', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:08:14', 5, 'done'),
(7547, ' چه تعداد از عبارت‌های زیر درست است؟\n\nآ) در هر فرایند انتقال گرما، فقط یکی از روش‌های انتقال گرما (رسانش، همرفت و تابش گرمایی) دخالت دارند.\n\nب) در رساناهای فلزی، سهم الکترون‌های آزاد در رسانش گرما بیشتر از اتم‌هاست.\n\nپ) انتقال گرما در مایعات و گازها براثر کاهش چگالی شاره با افزایش دما صورت می‌گیرد.\n\nت) تابش گرمایی سطوح تیره، ناصاف و مات بیشتر است.', 1, 2, 78, 341, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:07:53', 5, 'done'),
(7548, ' اگر دمای جسمی بر حسب درجهٔ فارنهایت ۹ درصد کاهش یابد، دمای آن به اندازهٔ ۷ کلوین تغییر می‌کند. دمای جسم در ابتدا چند درجهٔ سلسیوس بوده است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:07:43', 5, 'done'),
(7549, ' یک گلولهٔ فلزی توپر به شعاع $۲cm$ و جرم $۲۰۰g$ در دمای $۴۰^\\circ C$ قرار دارد. دمای گلوله را به چند درجهٔ سلسیوس برسانیم تا چگالی آن $۰/۰۳ \\frac{g}{cm^۳}$ کاهش یابد؟ $(\\alpha_{\\text{فلز}} = ۴ \\times ۱۰^{-۵} \\frac{۱}{^\\circ C} , \\pi = ۳)$', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:07:31', 5, 'done'),
(7550, ' اگر به ۱۰۰ گرم آب صفر درجهٔ سلسیوس، $۲۱۰۰J$ گرما بدهیم، حجم آب چگونه تغییر می‌کند؟ $(c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C})$', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:07:18', 5, 'done'),
(7551, ' قطعهٔ فلزی با ظرفیت گرمایی $۸۰ \\frac{J}{^\\circ C}$ را درون مقداری آب می‌اندازیم. اگر دمای اولیهٔ قطعه فلز و آب به ترتیب ۱/۶ برابر دمای تعادل و ۰/۲ برابر دمای تعادل باشد و $\\frac{۱}{۸}$ گرمایی که قطعه فلز از دست می‌دهد به محیط اطراف داده شود، جرم آب چند گرم بوده است؟ $(c_{\\text{آب}} = ۴/۲ \\frac{J}{g.^\\circ C})$', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:04:35', 5, 'done'),
(7552, ' ۵۰۰ گرم یخ $۰^\\circ C$ را درون ۵۰۰ گرم آب $۰^\\circ C$ قرار می‌دهیم. اگر یک گرمکن با توان مصرفی $۱۰۰۰W$ و بازده ۸۰ درصد به مدت ۳۱۵s به مخلوط آب و یخ گرما دهد، دمای این مخلوط به چند درجهٔ سلسیوس می‌رسد؟ $(c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C} , L_F = ۳۳۶۰۰۰ \\frac{J}{kg})$', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:04:24', 5, 'done'),
(7553, ' شکل زیر موقعیت دو جسم A و B با حجم‌های یکسان را درون یک ظرف حاوی آب صفر درجهٔ سلسیوس نشان می‌دهد و در این حالت نیروی شناوری وارد بر دو جسم به‌ترتیب برابر $F_A$ و $F_B$ است. اگر دمای آب ۳ درجهٔ سلسیوس افزایش یابد، پس از رسیدن مجموعه به حال تعادل نیروی شناوری وارد بر دو جسم به‌ترتیب $F\'_A$ و $F\'_B$ می‌شود. در مورد مقایسهٔ این نیروها کدام گزینه صحیح است؟ (از تغییر حجم جسم‌های A و B در اثر تغییر دما صرف‌نظر کنید.)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:04:09', 5, 'done'),
(7554, ' نمودار تغییرات طول دو میلهٔ A و B برحسب دما به‌صورت زیر است. ضریب انبساط طولی میلهٔ B چند برابر ضریب انبساط طولی میلهٔ A است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:03:50', 5, 'done'),
(7555, ' اگر دمای یک ورقهٔ فلزی را $۵۰^\\circ C$ افزایش دهیم، مساحت آن ۲ درصد افزایش می‌یابد. اگر با این ورقه، مکعبی بسازیم و دمایش را $۲۰۰^\\circ C$ افزایش دهیم، حجم آن چند درصد افزایش می‌یابد؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:03:41', 5, 'done'),
(7556, ' در یک کتری برقی با توان $۲kW$ و بازده ۸۰ درصد آب در حال جوشیدن است. در مدت ۲۲۶/۸s چند گرم آب به بخار تبدیل می‌شود؟ $(L_V = ۲۲۶۸ \\frac{J}{g})$', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:03:31', 5, 'done'),
(7557, ' برای آشکارسازی تابش‌های ........................ از ابزاری به‌نام دما‌نگار استفاده می‌شود. در روز باد از سمت ........................ می‌وزد.', 1, 2, 78, 341, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:03:20', 5, 'done'),
(7558, ' اختلاف دمای دو جسم A و B، ۱۸ درجهٔ سلسیوس است. اگر دمای جسم B برحسب کلوین، ۴ برابر دمای جسم A برحسب درجهٔ سلسیوس باشد، دمای جسم B چند درجهٔ فارنهایت می‌تواند باشد؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:03:02', 5, 'done'),
(7559, ' تفاوت طول دو میلهٔ هم‌دما و هم‌جنس A و B برابر $۶۰cm$ است. اگر این دو میله را به دنبال هم قرار داده و دمای آن‌ها را $۲۰۰^\\circ C$ افزایش دهیم، مجموع طول دو میله $۳/۰۰۱۸m$ می‌شود. طول اولیهٔ میلهٔ کوچک‌تر چند متر بوده است؟ $(\\alpha = ۳ \\times ۱۰^{-۶} \\frac{۱}{K})$', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:02:51', 5, 'done'),
(7560, ' در شکل زیر، اگر ضریب انبساط طولی فلز (۱) سه برابر ضریب انبساط طولی فلز (۲) باشد و این دو فلز در دمای $۵^\\circ C$ قرار داشته باشند، به ترتیب در دماهای $۸۰^\\circ C$ و $-۲۰^\\circ C$ ، جهت خم شدن شکل به کدام سمت خواهد بود؟ (دو میله به هم متصل هستند.)', 1, 2, 78, 338, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:02:40', 5, 'done'),
(7561, ' درون دو ظرف مشابه آب و روغن با دمای $۱^\\circ C$ وجود دارد، به‌طوری که قسمت پایین دو ظرف مطابق شکل از این دو مایع به‌طور کامل پرشده است. اگر دمای هر دو مایع را $۳^\\circ C$ افزایش دهیم، نیرویی که از طرف آب و روغن به کف ظرف وارد می‌شود به‌ترتیب از راست به چپ چگونه تغییر می‌کند؟ (از تغییر حجم ظرف صرف‌نظر کنید.)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:02:26', 5, 'done'),
(7562, ' یک گلولهٔ مسی به جرم $۵۰۰g$ و دمای $۸۰^\\circ C$ را درون ظرف محتوی $۱۰۰g$ آب صفر درجهٔ سلسیوس می‌اندازیم. اگر پس از برقراری تعادل گرمایی، دمای نهایی مجموعه به $۱۰^\\circ C$ برسد، ظرفیت گرمایی ظرف چند ژول بر درجهٔ سلسیوس است؟ $(c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C} , c_{\\text{مس}} = ۴۰۰ \\frac{J}{kg.^\\circ C}$ و انرژی گرمایی به محیط منتقل نمی‌شود.)', 1, 2, 78, 339, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:02:12', 5, 'done'),
(7563, ' توسط یک گرم‌کن ۵۶۰ واتی به مخلوطی از آب و یخ در حال تعادل که شامل، ۲۵۰ گرم یخ و ۵۵۰ گرم آب است، به مدت ۴ دقیقه گرما می‌دهیم. در این حالت دمای نهایی آب چند درجهٔ سلسیوس خواهد شد؟ $(c_{\\text{آب}} = ۴/۲ \\frac{J}{g.K} , L_F = ۳۳۶ \\frac{J}{g})$', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:01:59', 5, 'done'),
(7564, ' گرمایی که صرف تبدیل ۴ کیلوگرم یخ $-۱۰^\\circ C$ به ۲ کیلوگرم آب $۱۰۰^\\circ C$ می‌شود، دمای چند کیلوگرم آب $۳۰^\\circ C$ را می‌تواند به $۵۰^\\circ C$ برساند؟ ($c_{\\text{آب}} = ۴/۲ \\frac{kJ}{kg^\\circ C}$ ، $c_{\\text{یخ}} = ۲/۱ \\frac{kJ}{kg^\\circ C}$ ، $L_F = ۳۳۶ \\frac{kJ}{kg}$ و $L_V = ۲۲۶۸ \\frac{kJ}{kg}$)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:01:46', 5, 'done'),
(7565, ' دو ورقه مربع‌شکل ضخیم هم‌جنس در اختیار داریم، به‌طوری‌که ابعاد ورقهٔ بزرگتر دو برابر ابعاد ورقهٔ کوچکتر است. اگر به هر دو ورقه گرمای یکسانی بدهیم، افزایش سطح ورقهٔ بزرگتر چند برابر افزایش سطح ورقهٔ کوچکتر است؟ (ابعاد: طول، عرض، ارتفاع)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:01:32', 5, 'done'),
(7566, ' کدام‌یک از گزینه‌های زیر در مورد تف‌سنج صحیح نیست؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:01:22', 5, 'done'),
(7567, ' درون گرماسنجی با ظرفیت گرمایی $۱۵۰ \\frac{J}{^\\circ C}$ مقدار $۰/۵ kg$ آب با دمای $۱۰^\\circ C$ وجود دارد. یک قطعه مس به جرم $۰/۶ kg$ و دمای $۱۲۰^\\circ C$ را وارد گرماسنج می‌کنیم. اگر در این حالت دمای تعادل مجموعه $۲۰^\\circ C$ شود، گرمای ویژهٔ مس چند $\\frac{J}{kg.^\\circ C}$ است؟ ($c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C}$)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:01:12', 5, 'done'),
(7568, ' به مکعب فلزی توخالی که حجم ظاهری آن $۳۲۰ cm^۳$ و جرم آن $۹۰۰ g$ است، گرما می‌دهیم تا دمای آن $۱۵۰^\\circ C$ افزایش یابد. اگر چگالی بخش فلزی مکعب $۹۰ \\frac{kg}{m^۳}$ تغییر کند، حجم حفرهٔ درون مکعب چند سانتی‌متر مکعب افزایش می‌یابد؟ ($\\alpha = ۴ \\times ۱۰^{-۵} \\frac{۱}{^\\circ C}$)', 1, 2, 78, 338, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:00:55', 5, 'done'),
(7569, ' هنگامی‌که دمای یک جسم را برحسب درجهٔ سلسیوس سه برابر می‌کنیم، دمای جسم برحسب کلوین ۵۰ درصد افزایش می‌یابد. دمای اولیهٔ جسم چند کلوین بوده است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:00:42', 5, 'done'),
(7570, ' در شکل مقابل، یک دماسنج ترموکوپل نمایش داده شده است. چه تعداد از گزاره‌های زیر در مورد این دماسنج درست بیان شده است؟\n\n\n\nالف) این دماسنج امروزه جزو دماسنج‌های معیار به‌شمار می‌آید.\n\nب) کمیت دماسنجی این دماسنج، جریان الکتریکی است.\n\nپ) گسترهٔ دماسنجی این دماسنج به جنس سیم‌های آن بستگی دارد.\n\nت) به دلیل جرم کوچک محل اتصال، خیلی سریع با دستگاهی که دمای آن اندازه‌گیری می‌شود به حالت تعادل گرمایی می‌رسد.', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:00:26', 5, 'done'),
(7571, ' در فشار یک اتمسفر، دماسنجی دمای ذوب یخ را $-۱۰$ و دمای جوش آب را ۱۹۰ نشان می‌دهد. این دماسنج دمای جسمی که $۳۰۰ K$ است را چه عددی نشان خواهد داد؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:00:17', 5, 'done'),
(7572, ' چند مورد از عبارت‌های زیر در مورد دماسنج نشان داده شده صحیح است؟\n\nالف) جزو دماسنج‌های معیار به‌شمار می‌رود.\n\nب) با افزایش دما طول ستون جیوه در شاخهٔ سمت چپ کاهش می‌یابد.\n\nپ) این دماسنج کاربرد فراوانی در صنعت و آزمایشگاه‌ها دارد.\n\nت) حداکثر دمای اندازه‌گیری شده توسط این دماسنج $۲۵^\\circ C$ است.', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 18:00:05', 5, 'done'),
(7573, ' به ازای ۱۰ واحد تغییرات دما در یک دماسنج که به‌صورت خطی مدرج شده است، دماسنج با درجه‌بندی سلسیوس، ۱۵ واحد تغییر می‌کند. اگر این دماسنج در فشار یک اتمسفر، دمای $۶۰^\\circ C$ را عدد ۲۰ نمایش دهد، در چه دمایی برحسب درجهٔ سلسیوس و در همین فشار، این دماسنج و دماسنج سلسیوس عددی یکسان را نمایش می‌دهند؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:59:57', 5, 'done'),
(7574, ' کدام عبارت‌های زیر درست‌اند؟\n\nالف) گسترهٔ دماسنجی یک ترموکوپل به جنس سیم‌های آن بستگی دارد و مزیت آن که باعث شده امروزه مورد استفاده قرار گیرد، دقت بسیار بالای آن است.\n\nب) اگر دمای جسمی برحسب درجهٔ سلسیوس دو برابر شود دمای این جسم، برحسب کلوین، کمتر از دو برابر می‌شود.\n\nپ) اساس کار دماسنج نواری دو فلزه مبتنی بر تغییر مقاومت الکتریکی با تغییر دما است.\n\nت) آب به دلیل انبساط غیرعادی خود، در دمای $۴^\\circ C$ بیشترین چگالی را دارد.', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:59:48', 5, 'done'),
(7575, ' اگر دمای جسمی برحسب درجهٔ سلسیوس سه برابر شود، دمای آن برحسب درجهٔ فارنهایت ۷۲ درصد افزایش می‌یابد. دمای اولیهٔ جسم برحسب کلوین چقدر است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:59:38', 5, 'done'),
(7576, ' دماسنجی خطی که روش مدرج کردن آن معلوم نیست، دمای $۵^\\circ C$ را ۵۰ درجه و دمای $-۲۰^\\circ C$ را ۱۰ درجه نشان می‌دهد، این دماسنج در چه دمایی برحسب درجهٔ فارنهایت، با دماسنج فارنهایت عدد یکسانی را نشان می‌دهد؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:59:26', 5, 'done'),
(7577, ' در یک دماسنج، نمودار تغییرات دما برحسب ارتفاع ستون جیوه، مطابق شکل زیر است. اگر این دماسنج را در مخلوط آب و یخ در فشار یک اتمسفر قرار دهیم، ارتفاع ستون جیوه در آن چند میلی‌متر خواهد بود؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:59:16', 5, 'done'),
(7578, ' ضریب انبساط طولی یک فلز $\\alpha = ۴/۵ \\times ۱۰^{-۵} \\frac{۱}{^\\circ C}$ است. ضریب انبساط طولی این فلز برحسب یکای $\\frac{۱}{^\\circ F}$ برابر کدام گزینه است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:59:04', 5, 'done'),
(7579, ' اگر دمای یک میلهٔ مسی را $۱۰۰^\\circ C$ افزایش دهیم، طول آن ۰/۱۶ درصد افزایش می‌یابد. در صورتی‌که دمای یک کرهٔ مسی را $۵۰^\\circ C$ افزایش دهیم، حجم آن چند برابر می‌شود؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:58:52', 5, 'done'),
(7580, ' در شکل زیر، نمودار طول دو میلهٔ A و B برحسب تغییرات دما، نشان داده شده است. کدام‌یک از گزینه‌های زیر در مورد مقایسهٔ ضریب انبساط طولی ($\\alpha$) دو میله درست است؟ (دو خط A و B با هم موازی‌اند.)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:58:42', 5, 'done'),
(7581, ' مطابق شکل زیر، محفظه‌ای شیشه‌ای را که در دمای $۱۰^\\circ C$ گنجایشی برابر $۲۰۰ cm^۳$ دارد با گلیسیرین با همان دما پر کرده‌ایم. با توجه به نمودار حجم محفظه برحسب دمای آن، دمای ظرف و گلیسیرین را به چند درجهٔ سلسیوس برسانیم، تا $۴ cm^۳$ گلیسیرین از ظرف بیرون بریزد؟ (ضریب انبساط حجمی گلیسیرین برابر $۵ \\times ۱۰^{-۴} \\frac{۱}{K}$ است.)', 1, 2, 78, 338, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:58:30', 5, 'done'),
(7582, ' ورقهٔ نازک مربع شکلی به ضلع $۱۲ cm$ که در وسط آن حفرهٔ دایره‌ای به شعاع $۴ cm$ وجود دارد، در اختیار داریم. دمای ورقه را به‌طور یکنواخت ۵۰ درجهٔ سلسیوس افزایش می‌دهیم. اگر چگالی فلز، ۰/۶ درصد تغییر کند، افزایش مساحت قسمت فلزی ورقه چند میلی‌متر مربع بیشتر از افزایش مساحت حفرهٔ دایره‌ای شکل است؟ ($\\pi = ۳$)', 1, 2, 78, 338, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:58:17', 5, 'done'),
(7583, ' دمای یک کرهٔ فلزی توپر به شعاع ۵ سانتی‌متر را ۸۰ درجهٔ فارنهایت افزایش می‌دهیم. اگر حجم کره ۱۵ میلی‌متر مکعب افزایش یابد، سطح کره چند سانتی‌متر مربع افزایش می‌یابد؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:57:49', 5, 'done'),
(7584, ' بیشترین دمای هوای شهر تهران در روز ۲۰ آذرماه، $۳۰^\\circ C$ و کمترین دمای آن در این روز $۵^\\circ C$ است. اختلاف این دو دما برحسب کلوین و درجهٔ فارنهایت به ترتیب کدام است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:57:39', 5, 'done'),
(7585, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«دماسنج ........................ به دلیل ........................ از مجموعه دماسنج‌های معیار کنار گذاشته شده است.»', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:57:28', 5, 'done'),
(7586, ' با دو دماسنج سلسیوس و فارنهایت دمای جسمی را اندازه گرفته‌ایم. اگر اندازهٔ عددی که دماسنج فارنهایت نشان می‌دهد، ۳۰ درصد بیشتر از عددی باشد که دماسنج سلسیوس نشان می‌دهد، این دما چند کلوین است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:57:16', 5, 'done'),
(7587, ' درون یک ظرف استوانه‌ای شکل با انبساط ناچیز، تا ارتفاع H مایعی با ضریب انبساط حجمی $\\beta$ قرار دارد. اگر دمای مایع تغییر کند، نسبت تغییر ارتفاع مایع به تغییر دمای آن برحسب کلوین کدام است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:57:02', 5, 'done'),
(7588, ' یک ظرف به حجم ۵ لیتر را از مایعی به ضریب انبساط حجمی $۶ \\times ۱۰^{-۴} \\frac{۱}{K}$ پر کرده‌ایم. اگر دمای ظرف و مایع را $۵۰^\\circ C$ افزایش دهیم، هیچ مایعی از ظرف خارج نمی‌شود و همچنان ظرف لبریز از مایع است. در این حالت سطح خارجی ظرف چند درصد منبسط شده است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 17:56:40', 5, 'done'),
(7589, ' درون یک مکعب فلزی با ضریب انبساط طولی $۱۰^{-۶} \\frac{۱}{K}$، یک حفرهٔ خالی کروی به شعاع $۱۰ cm$ وجود دارد. اگر دمای مکعب $۴۵^\\circ F$ افزایش یابد، تغییر حجم کره چند لیتر است؟ ($\\pi = ۳$)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:16:31', 5, 'done'),
(7590, ' اگر دمای یک میلهٔ فلزی به طول L را به اندازهٔ $\\theta$ بالا ببریم، به طول آن ۱۰ درصد اضافه می‌شود. اگر دمای یک صفحهٔ مربع شکل به ضلع ۴L از همان جنس را $۲\\theta$ بالا ببریم، مساحت آن چند درصد افزایش پیدا می‌کند؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:16:16', 5, 'done'),
(7591, ' چگالی یک قطعه فلز در دمای $۳۰^\\circ F$ برابر $۱۰ \\frac{g}{cm^۳}$ است. چگالی آن در دمای $۳۰۰^\\circ F$ چند واحد SI است؟ ($\\alpha_{\\text{فلز}} = ۲ \\times ۱۰^{-۵} \\frac{۱}{K}$)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:16:07', 5, 'done'),
(7592, ' درون ظرفی به حجم $۳۰۰ cm^۳$ مقدار $۲۹۰ cm^۳$ از یک مایع در دمای $۱۰^\\circ C$ وجود دارد. اگر دمای ظرف و مایع را به $۷۰^\\circ C$ برسانیم، $۲/۹۶ cm^۳$ مایع از ظرف سرریز می‌شود. ضریب انبساط طولی ظرف برحسب یکای SI کدام است؟ (ضریب انبساط حجمی مایع $۹ \\times ۱۰^{-۴} \\frac{۱}{K}$ است.)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:15:59', 5, 'done'),
(7593, ' جسمی درون ظرفی حاوی آب $۲۰^\\circ C$ به‌طور کامل غوطه‌ور است. این جسم را یکبار در ظرف A شامل آب $۱۰^\\circ C$ و بار دیگر در ظرف B شامل آب $۴^\\circ C$ قرار می‌دهیم پس از به تعادل رسیدن جسم در دو ظرف، وضعیت قرارگیری آن مطابق کدام گزینه است؟ (از تغییرات حجم جسم در اثر تغییر دما صرف‌نظر کنید.)', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:15:50', 5, 'done'),
(7594, ' درون دو سیلندر مشابه، مقدار برابری از یک مایع در دمای یکسان ریخته‌ایم و به دو مجموعه با توان ثابت و مساوی، گرما می‌دهیم. اگر جرم پیستون روی هر دو سیلندر یکسان و مطابق شکل، روی سیلندر (۲) وزنه‌ای به جرم m قرار داشته باشد، کدام گزینه درست خواهد بود؟ (اتلاف انرژی نداریم.)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:15:24', 5, 'done'),
(7595, ' ظرفیت گرمایی جسم A به اندازهٔ ۳۰۰ واحد SI از ظرفیت گرمایی جسم B بیشتر است. اگر به دو جسم گرمای مساوی بدهیم، افزایش دمای جسم B، ۴ برابر افزایش دمای جسم A خواهد بود. ظرفیت گرمایی جسم A چند واحد SI است؟ (با دادن گرما به جسم A و B تغییر حالت رخ نمی‌دهد.)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:15:08', 5, 'done'),
(7596, ' نمودار گرمای داده شده برحسب تغییر دمای دو جسم A و B به‌صورت زیر است. اگر جرم جسم A، دو برابر جرم B و مقدار گرمای داده شده به جسم B چهار برابر گرمای داده شده به جسم A باشد، افزایش دمای جسم A چند برابر جسم B است؟ (با دادن گرما به جسم A و B تغییر حالت رخ نمی‌دهد.)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:15:00', 5, 'done'),
(7597, ' از ظرفی که حاوی مخلوطی از آب و یخ است، با آهنگ $۲۵ \\frac{J}{s}$ گرما می‌گیریم. اگر پس از ۵۶ دقیقه، $۰/۸ kg$ یخ $-۱۰^\\circ C$ در ظرف داشته باشیم، جرم یخ اولیه چند گرم بوده است؟ ($c_{\\text{یخ}} = ۲/۱ \\frac{kJ}{kg.K}$ ، $L_F = ۳۳۶ \\frac{kJ}{kg}$)', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:14:52', 5, 'done'),
(7598, ' گرمای لازم برای تبدیل $۲۰۰ g$ آب $۱۰۰^\\circ C$ به $۲۰۰ g$ بخار آب $۱۰۰^\\circ C$ در فشار یک اتمسفر، چند برابر گرمای لازم برای تبدیل $۴۰۰ g$ یخ $۰^\\circ C$ به $۴۰۰ g$ آب $۰^\\circ C$ است؟ ($L_V = ۲۲۶۸ \\frac{J}{g}$ ، $L_F = ۳۳۶ \\frac{J}{g}$)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:14:45', 5, 'done'),
(7599, ' یک کتری برقی با توان مصرفی $۲ kW$ در مدت ۱۴s، دمای $۴۰۰ g$ آب را از $۳۲^\\circ C$ به $۴۲^\\circ C$ می‌رساند. بازده کتری را چند درصد افزایش دهیم تا در نصف مدت زمان فوق، دمای $۴۰۰ g$ آب را از $۵۰^\\circ C$ به $۵۷/۵^\\circ C$ برساند؟ ($c = ۴۲۰۰ \\frac{J}{kg.^\\circ C}$)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:14:36', 5, 'done'),
(7600, ' دو مایع مختلف با جرم‌های $m_۱ = ۲m_۲$ را به نوبت در یک جایخی با توان ثابت قرار می‌دهیم تا تبدیل به جامد گردند. نمودار دما برحسب زمان برای این دو مایع به‌صورت زیر است. اگر $c_۱$ و $c_۲$ گرمای ویژهٔ دو مایع و $c\'_۱$ و $c\'_۲$ گرمای ویژهٔ آنها در حالت جامد باشند، کدام رابطه صحیح است؟', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:14:23', 5, 'done'),
(7601, ' یک قطعهٔ یخ با دمای $۰^\\circ C$ را در $۷۵۰ g$ آب $۲۰^\\circ C$ می‌اندازیم. بعد از تعادل گرمایی، $۳۷/۵ g$ یخ ذوب نشده باقی می‌ماند. حجم اولیهٔ یخ چند لیتر بوده است؟ ($c_{\\text{آب}} = ۴/۲ \\frac{J}{g.K}$ ، $L_F = ۳۳۶ \\frac{J}{g}$ و چگالی یخ $۰/۹ \\frac{g}{cm^۳}$ است.)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:14:14', 5, 'done'),
(7602, ' نمودار تغییرات دما برحسب گرمای داده شده به جسمی، مطابق شکل زیر است. اگر یک کیلوگرم از جرم این جسم کم شود، ظرفیت گرمایی آن ۲۰ درصد کاهش می‌یابد. گرمای ویژهٔ آن در SI برابر با کدام گزینه است؟', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:13:53', 5, 'done'),
(7603, ' درون یک کتری برقی با توان ثابت $۳/۶ kW$، $۴۰۰ g$ آب $۴۰^\\circ C$ موجود است. پس از گذشت چند ثانیه $۱۰۰ g$ آب درون ظرف باقی می‌ماند؟ ($c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C}$ و $L_V = ۲۲۵۶ \\frac{J}{g}$ از تبادل گرما با محیط صرف‌نظر کنید.)', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:13:44', 5, 'done'),
(7604, ' یک قطعه یخ را درون یک گرمکن الکتریکی با توان گرمایی ثابت قرار داده و آن را روشن می‌کنیم. اگر نمودار تغییرات دمای این قطعه یخ برحسب زمان به‌صورت شکل زیر باشد، به ترتیب از راست به چپ دمای اولیهٔ قطعه یخ $(\\theta_0)$ برحسب درجهٔ سلسیوس و لحظهٔ $t\'$ (برحسب دقیقه) کدام است؟ $(c_{\\text{یخ}} = ۲/۱ \\frac{J}{g.K} , c_{\\text{آب}} = ۴/۲ \\frac{J}{g.K} , L_F = ۳۳۶ \\frac{J}{g})$', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:13:36', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7605, ' چه تعداد از عبارت‌های زیر درست بیان شده‌اند؟\n\nالف) در اجسام تیره جذب گرمایی ضعیف‌تر و بازتابش قوی‌تر است.\n\nب) همهٔ اجسام فقط در دماهای بالا در حال تابش از سطح خود هستند.\n\nپ) تف‌سنج تابشی به‌عنوان دماسنج معیار برای اندازه‌گیری دماهای بالا انتخاب شده است.\n\nت) در انتقال گرما به روش تابش گرمایی نیازی به محیط مادی نداریم.', 1, 2, 78, 341, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:13:18', 5, 'done'),
(7606, ' نمودار دمای جسم جامدی به جرم m و گرمای ویژه $۲۰۰ \\frac{J}{kg.^\\circ C}$ برحسب گرمای داده شده به آن مطابق شکل زیر است. اگر گرمای نهان ذوب جسم برابر با $L_F$ باشد، m و $L_F$ به ترتیب برحسب یکای SI کدام‌اند؟', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:13:10', 5, 'done'),
(7607, ' چه تعداد از عبارت‌های زیر درست است؟\n\nالف) افزایش فشار وارد بر یخ، نقطهٔ ذوب آن را کمی بالا می‌برد.\n\nب) شیشه نقطهٔ ذوب مشخصی دارد.\n\nپ) با ریختن الکل در آب، نقطهٔ انجماد آن کاهش می‌یابد.\n\nت) گرمایی که جسم جامد در نقطهٔ ذوب خود می‌گیرد تا به مایع تبدیل شود، سبب تغییر دمای آن نمی‌شود.', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:13:01', 5, 'done'),
(7608, ' دمای m گرم از مادهٔ A با گرفتن گرمای Q به اندازهٔ $\\theta$ و دمای $\\frac{m}{۲}$ گرم از مادهٔ B با گرفتن گرمای 2Q به اندازهٔ $۲\\theta$ بالا می‌رود. به ترتیب از راست به چپ، ظرفیت گرمایی و گرمای ویژهٔ A چند برابر B است؟ (تغییر حالت نداریم.)', 1, 2, 78, 339, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:12:51', 5, 'done'),
(7609, ' دمای جسمی $۳۶^\\circ F$ است. اگر دمای این جسم برحسب فارنهایت را ۱۰ درصد افزایش دهیم، افزایش دمای آن برحسب کلوین کدام است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:12:43', 5, 'done'),
(7610, ' یک دماسنج سلسیوس و یک دماسنج فارنهایت را درون یک ظرف حاوی الکل قرار می‌دهیم. اگر عددی که دماسنج سلسیوس نشان می‌دهد، ۸ واحد کم‌تر از عددی باشد که دماسنج فارنهایت نشان می‌دهد، دمای الکل چند کلوین است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:12:33', 5, 'done'),
(7611, ' دمای جسمی توسط دماسنج فارنهایت و یک دماسنج مجهول اندازه‌گیری می‌شود و هر دو دماسنج عدد ۵۰ را نشان می‌دهند. اگر دمای جسم $۹^\\circ F$ افزایش یابد، دماسنج مجهول دمای جسم را ۶۰ درجه نشان می‌دهد. دماسنج مجهول دمای جسمی با دمای $-۱۰^\\circ C$ را چند درجه نشان می‌دهد؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:12:24', 5, 'done'),
(7612, ' دماسنجی ساخته‌ایم که دمای $۲۰^\\circ C$ را ۴۵ درجه و دمای یخ در حال ذوب را ۱۵ درجه نشان می‌دهد. در کدام دما برحسب درجهٔ سلسیوس، مقداری که این دماسنج نشان می‌دهد ۲ برابر دما برحسب درجهٔ سلسیوس است؟ (رابطهٔ بین دو مقیاس خطی است.)', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:12:12', 5, 'done'),
(7613, ' دمای ۱۲۲ درجهٔ فارنهایت معادل با چند درجهٔ سلسیوس و چند کلوین است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:12:03', 5, 'done'),
(7614, 'طول اولیهٔ دو میلهٔ A و B در دمای $۳۰^\\circ C$ با هم برابر است. دمای دو میله را به چند درجهٔ سلسیوس برسانیم تا اندازهٔ اختلاف طول آن‌ها $۴ \\times ۱۰^{-۴}$ برابر طول اولیهٔ آن‌ها شود؟ $(\\alpha_B = ۱/۲ \\times ۱۰^{-۵} \\frac{۱}{K} , \\alpha_A = ۱/۶ \\times ۱۰^{-۵} \\frac{۱}{K})$', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 21:11:55', 5, 'done'),
(7615, ' در مدت زمان ۶۷۰s، توسط یک گرمکن الکتریکی، 1kg یخ $۰^\\circ C$ را به آب $۸۰^\\circ C$ تبدیل می‌کنیم. توان این گرمکن چند کیلووات است؟ $(c_{\\text{آب}} = ۴/۲ \\frac{kJ}{kg.^\\circ C} , L_F = ۳۳۴ \\frac{kJ}{kg})$', 1, 2, 78, 340, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 20:31:06', 5, 'done'),
(7616, ' مقدار گرمایی که دمای 2kg آب را از $۳۰^\\circ C$ تا $۸۰^\\circ C$ می‌رساند، چند کیلوگرم یخ با دمای $-۱۰^\\circ C$ را می‌تواند به بخار آب $۱۰۰^\\circ C$ تبدیل کند؟ $(c_{\\text{یخ}} = ۲۱۰۰ \\frac{J}{kg.^\\circ C} , L_F = ۳۳۶ \\frac{kJ}{kg} , L_V = ۲۲۶۸ \\frac{kJ}{kg} , c_{\\text{آب}} = ۴۲۰۰ \\frac{J}{kg.^\\circ C})$', 1, 2, 78, 340, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 20:30:55', 5, 'done'),
(7617, ' در کدام گزینه تمام فرایندها گرماده هستند؟', 1, 2, 78, 340, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 20:30:42', 5, 'done'),
(7618, ' اگر دمای جسمی بر حسب درجهٔ فارنهایت ۱۰ درصد کاهش یابد، دمای آن بر حسب درجهٔ سلسیوس $\\frac{۲۵}{۹} ^\\circ C$ تغییر می‌کند. دمای اولیهٔ جسم چند کلوین بوده است؟', 1, 2, 78, 337, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-26 20:30:28', 5, 'done'),
(7619, ' به کرهٔ فلزی توپر A به جرم ۵۰۰g به اندازهٔ Q گرما می‌دهیم تا شعاع آن ۰/۴ درصد افزایش یابد. اگر گرمای ویژهٔ A و ضریب انبساط طولی آن به ترتیب ۱۲۰۰ و $۱۰^{-۴}$ واحد SI باشند، Q چند ژول بوده است؟', 1, 2, 78, 338, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-25 18:05:18', 1, '2026-03-27 23:07:56', 4, 'done'),
(7620, ' با توجه به سری الکتریسیته مالشی روبه‌رو، در اثر مالش دو جسم A و C با یکدیگر، $5 \\times 10^{13}$ الکترون و در اثر مالش دو جسم B و D با یکدیگر، $15 \\times 10^{13}$ الکترون بین آن‌ها مبادله می‌شود. اگر دو جسم B و C را با هم تماس دهیم، مجموع بار الکتریکی خالص آن‌ها چند میکروکولن خواهد شد؟ (جسم‌های B و C رسانا و A و D نارسانا هستند و $e = 1/6 \\times 10^{-19} C$)\n\nانتهای مثبت سری\n\nA\n\nB\n\nC\n\nD\n\nانتهای منفی سری', 2, 2, 79, 342, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:07:38', 4, 'done'),
(7621, 'دو ذره (۱) و (۲) با بارهای الکتریکی $q_1 = 2 \\mu C$ و $q_2 = -4 \\mu C$ در فاصله ثابتی از هم قرار دارند. چند الکترون از ذره (۲) به دیگری منتقل کنیم تا اندازه نیروی الکتریکی‌ای که دو ذره به هم وارد می‌کنند، ۶ برابر شود؟ ($e = 1/6 \\times 10^{-19} C$)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:07:24', 4, 'done'),
(7622, 'دو بار الکتریکی نقطه‌ای $q_1 = 2 \\mu C$ و $q_2 = 3 \\mu C$ در فاصله ثابتی از هم قرار دارند. اگر نیرویی که بار $q_1$ به بار $q_2$ وارد می‌کند، در SI به صورت $\\vec{F} = 12\\vec{i} - 18\\vec{j}$ باشد، میدان الکتریکی حاصل از بار $q_2$ در محل بار $q_1$ در SI کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:07:09', 4, 'done'),
(7623, '4-مطابق شکل روبه‌رو دو ذره باردار با بار $q_1$ و $q_2$ در نقطه‌های M و N قرار دارند. اگر $\\vec{E}$ بردار میدان الکتریکی حاصل از این دو بار در نقطه‌ای روی عمودمنصف پاره‌خط MN باشد، میدان الکتریکی خالص در کدام نقطه می‌تواند برابر صفر باشد؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:06:54', 4, 'done'),
(7624, '5-دو ذره با بار $q_1$ و $q_2 = 2q_1$ در فاصله معینی از هم قرار دارند. بار نقطه‌ای $q$ را در مکانی قرار می‌دهیم که نیروی الکتریکی خالص وارد بر آن صفر باشد. در این حالت، اگر میدان الکتریکی حاصل از بار $q$ در محل بارهای $q_1$ و $q_2$ به ترتیب $\\vec{E}_1$ و $\\vec{E}_2$ باشد، کدام درست است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:06:44', 4, 'done'),
(7625, '6-در شکل روبه‌رو، چهار ذره باردار در رأس‌های یک مربع به ضلع $ 1 cm$ قرار دارند. اگر نیروی الکتریکی خالص وارد بر بار $q_4$ برابر صفر باشد، اندازه نیروی الکتریکی خالص وارد بر بار $q_2$ چند نیوتون است؟ ($k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:05:19', 4, 'done'),
(7626, '7-چهار بار الکتریکی نقطه‌ای مطابق شکل زیر ثابت شده‌اند. اگر اندازه نیروی الکتریکی خالص وارد بر بار $q_4$ برابر $ 10^{-8} N$ باشد، اندازه نیروی الکتریکی خالص وارد بر بار $q_2$ چند نیوتون می‌تواند باشد؟ ($k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:05:08', 4, 'done'),
(7627, ' در شکل روبه‌رو بار الکتریکی $q$ در مبدأ مختصات صفحه $xy$ قرار دارد و بردار میدان الکتریکی ناشی از آن در نقطه $A$ به صورت $\\vec{E} = (50\\sqrt{2} N/C)\\vec{i} + (50\\sqrt{2} N/C)\\vec{j}$ است. بردار میدان الکتریکی حاصل از بار $q$ در نقطه $B$، در $SI$ کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:04:52', 4, 'done'),
(7628, '9-در شکل روبه‌رو میدان الکتریکی خالص در نقطه $M$، برابر صفر و بردار میدان الکتریکی ناشی از بار $q_2$ در نقطه $M$، برابر $\\vec{E}$ است. اگر بار $q_2$ از مرکز دایره به نقطه $A$ منتقل شود، اندازه میدان الکتریکی برایند در نقطه $M$، چند $E$ می‌شود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:04:38', 4, 'done'),
(7629, ' مطابق شکل روبه‌رو، چهار بار نقطه‌ای روی چهار رأس مربعی به ضلع $30 cm$ قرار دارند. اگر بزرگی میدان الکتریکی خالص در مرکز مربع $10^6 N/C$ باشد، اندازه نیروی الکتریکی خالص وارد بر بار $q_1$ چند نیوتون است؟ $(k = 9 \\times 10^9 \\frac{N.m^2}{C^2})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 23:04:24', 4, 'done'),
(7630, ' اگر بار الکتریکی $-50 mC$ را از پایانه مثبت یک باتری $12$ ولتی به پایانه منفی آن منتقل کنیم، انرژی پتانسیل الکتریکی آن چند میلی‌ژول و چگونه تغییر می‌کند؟', 2, 2, 79, 345, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:27:27', 4, 'done'),
(7631, ' در صفحه مختصات شکل روبه‌رو میدان الکتریکی یکنواخت $\\vec{E} = (-2/5 \\times 10^4 N/C)\\vec{j}$ وجود دارد. اگر پتانسیل الکتریکی نقاط $A$ و $B$ به ترتیب $V_A$ و $V_B$ باشد، $V_A - V_B$ برحسب ولت کدام است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:27:15', 4, 'done'),
(7632, ' مطابق شکل یک کره باردار، روی یک پایه عایق قرار دارد. بار $q = -4 \\mu C$ را از نقطه $A$ تا نقطه $B$ جابه‌جا می‌کنیم. اگر کاری که میدان حاصل از بار کره در این جابه‌جایی انجام می‌دهد، برابر $ 0/2 mJ$ باشد، علامت بار کره کدام و $V_A - V_B$ چند ولت است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:27:05', 4, 'done'),
(7633, ' در شکل روبه‌رو، اختلاف پتانسیل دو صفحه موازی با بارهای هم‌اندازه و ناهمنام برابر $160 V$ است. ذره‌ای با بار الکتریکی $4 mC$ و جرم $2 g$ را از نقطه $A$ با تندی $20 m/s$ به سمت راست پرتاب می‌کنیم. با چشم‌پوشی از نیروی وزن و مقاومت هوا، کدام اتفاق رخ می‌دهد؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:26:53', 4, 'done'),
(7634, '  مطابق شکل، یک کره فلزی توپر بین دو صفحه فلزی قرار دارد. کدام‌یک از عبارت‌های زیر درباره این شکل درست است؟ (نقطه‌های $M$ و $N$ روی سطح کره فلزی قرار دارند.)\n\nالف) پتانسیل الکتریکی نقطه $M$ برابر پتانسیل الکتریکی نقطه $N$ است.\n\nب) میدان الکتریکی در تمام فضای بین دو صفحه یکنواخت است.\n\nپ) میدان الکتریکی خالص در داخل کره فلزی صفر است.\n\nت) بار الکتریکی القاشده روی کره در اطراف نقطه $N$، منفی است.', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:26:40', 4, 'done'),
(7635, ' پتانسیل الکتریکی دو صفحه خازنی برابر $-3 V$ و $9 V$ و بار الکتریکی ذخیره‌شده در این دو صفحه به ترتیب $-24 \\mu C$ و $+24 \\mu C$ است. ظرفیت خازن چند میکروفاراد است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:26:29', 4, 'done'),
(7636, ' مساحت هر یک از صفحه‌های یک خازن تخت $12 cm^2$ است و خازن از ماده دی‌الکتریک انعطاف‌پذیری به ثابت $\\kappa = 2$ پر شده است. اگر فاصله بین صفحه‌های خازن از $6 mm$ به $4 mm$ برسد، ظرفیت خازن چند پیکوفاراد و چگونه تغییر می‌کند؟ $(\\epsilon_\\circ = 8/85 \\times 10^{-12} F/m)$', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:26:20', 4, 'done'),
(7637, '18- ظرفیت یک خازن تخت $8 \\mu F$ است. بار $-4 \\mu C$ از صفحه منفی خازن به صفحه مثبت آن منتقل می‌شود. در این تغییر، انرژی ذخیره‌شده در خازن $24 \\mu J$ تغییر می‌کند. بار اولیه خازن چند میکروکولن بوده است؟ (خازن از باتری جدا است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:25:57', 4, 'done'),
(7638, ' مدار یک فلاش عکاسی، انرژی را با اختلاف پتانسیل $200 V$ در یک خازن با ظرفیت $8 mF$ ذخیره می‌کند. اگر همه این انرژی در مدت $ 0/2 s$ آزاد شود، توان متوسط خروجی فلاش چند کیلووات است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:25:46', 4, 'done'),
(7639, ' بار الکتریکی ذخیره‌شده روی صفحه‌های خازنی برابر $10^3 \\mu C$ است. اگر مطابق شکل روبه‌رو، ذره‌ای به جرم $4 g$ و بار $8 \\mu C$ به موازات دو صفحه افقی این خازن پرتاب شود، بدون انحراف به حرکت خود ادامه می‌دهد. ظرفیت این خازن چند میکروفاراد است؟ $(g = 10 \\frac{N}{kg})$', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:25:38', 4, 'done'),
(7640, ' اگر اختلاف پتانسیل بین دو صفحه یک خازن از $47 V$ به $32 V$ برسد، در هر صفحه $ 7/5 \\times 10^{13}$ الکترون افزوده یا کاسته می‌شود. ظرفیت خازن چند فاراد است؟ $(e = 1/6 \\times 10^{-19} C)$', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:25:26', 4, 'done'),
(7641, ' در مدار شکل زیر، فاصله بین صفحات خازن $4 mm$، مساحت هر یک از صفحات آن $80 cm^2$ و بین صفحات آن هواست. برای این‌که بار الکتریکی ذخیره‌شده در خازن $ 10/8 nC$ افزایش یابد، فاصله بین صفحات خازن باید چند میلی‌متر و چگونه تغییر کند؟ $(\\epsilon_\\circ = 9 \\times 10^{-12} \\frac{C^2}{N.m^2})$', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:25:17', 4, 'done'),
(7642, '23- خازن مسطحی با دی‌الکتریک هوا به یک باتری بسته شده است و اندازه میدان الکتریکی بین صفحات آن برابر $E$ است. در همین حالت، فاصله بین صفحات خازن را $2$ برابر می‌کنیم، سپس خازن را از باتری جدا کرده و فاصله بین صفحات را به مقدار اولیه می‌رسانیم. اندازه میدان الکتریکی بین صفحات خازن در این حالت چند برابر $E$ است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:25:09', 4, 'done'),
(7643, ' برای راه‌اندازی یک دستگاه الکتریکی باید انرژی الکتریکی با آهنگ متوسط $10 kW$ توسط یک خازن در آن تخلیه شود. اگر ولتاژ متصل به دستگاه $200 V$ و مدت‌زمان تخلیه انرژی $ 0/5 ms$ باشد، باید از خازنی با ظرفیت چند میلی‌فاراد استفاده شود؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:24:57', 4, 'done'),
(7644, ' خازنی که فضای بین صفحات آن هوا است، به باتری متصل و انرژی ذخیره‌شده در آن $U$ است. اگر بدون جداکردن آن از باتری، فضای بین صفحات خازن را با عایقی با ثابت دی‌الکتریک $K$ به طور کامل پر کنیم، انرژی الکتریکی ذخیره‌شده در خازن $U\'$ می‌شود و اگر خازن را ابتدا از باتری جدا کرده و سپس فضای بین صفحاتش را با ماده‌ای با ثابت دی‌الکتریک $K$ به طور کامل پر کنیم، انرژی ذخیره‌شده در آن $U\'\'$ می‌شود. حاصل $\\frac{U\'\'}{U\'}$ کدام است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:24:46', 4, 'done'),
(7645, ' دانش‌آموزی یک میله فلزی از جنس برنج را با یک دستکش عایق نسبتاً ضخیم، در دست گرفته و به موهای خود مالش می‌دهد، سپس آن را به الکتروسکوپ نشان داده شده در شکل روبه‌رو نزدیک می‌کند. در این صورت:', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:24:34', 4, 'done'),
(7646, '27- دو کره رسانای کوچک با بارهای الکتریکی $q_1 = +8 \\mu C$ و $q_2 = +4 \\mu C$ به فاصله $1 m$ از یکدیگر قرار دارند. چه تعداد الکترون از کره با بار $q_1$ برداریم و به دیگری منتقل کنیم تا در همان فاصله قبلی، بزرگی نیروی رانشی آن‌ها بر هم به اندازه $ 0/108 N$ کم شود؟ $(k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$ و $e = 1/6 \\times 10^{-19} C)$', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:24:24', 4, 'done'),
(7647, ' در شکل زیر، نیروی الکتریکی خالص وارد بر هر بار الکتریکی صفر است. اگر نسبت $\\frac{q_1}{q_3}$ برابر $4$ باشد، نسبت $\\frac{q_3}{q_2}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:24:12', 4, 'done'),
(7648, '29- در شکل زیر، اگر نیروی الکتریکی خالص وارد بر بار $q_0$ ، $\\vec{F}_t = (+2\\mu N)\\vec{i}$ باشد، $q_2$ چند نانوکولن است؟ $(k = 9 \\times 10^9 \\frac{N.m^2}{C^2})$', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:24:03', 4, 'done'),
(7649, '30- در شکل زیر، بزرگی میدان الکتریکی حاصل از دو بار نقطه‌ای $q_1$ و $q_2$ در نقطه $M$ برابر $E$ است. اگر بار $q\' = -16 \\mu C$ را به بار $q_1$ اضافه کنیم، بزرگی میدان الکتریکی خالص در نقطه $M$ چند $E$ می‌شود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:23:51', 4, 'done'),
(7650, '31-  چهار بار نقطه‌ای مطابق شکل ثابت شده‌اند. اندازه میدان الکتریکی حاصل از چهار بار در نقطه $O$ برابر $400 N/C$ است. اندازه بار $q_3$ چند نانوکولن می‌تواند باشد؟ $(k = 9 \\times 10^9 \\frac{N.m^2}{C^2})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:23:41', 4, 'done'),
(7651, ' بردار میدان حاصل از بار الکتریکی $q$ در نقطه $A$ به صورت $\\vec{E}_A = (2 \\times 10^5 N/C)\\vec{i} + (-1/5 \\times 10^5 N/C)\\vec{j}$ است. اگر بار $q = -5 \\mu C$ را در نقطه $B$ (وسط پاره‌خط $OA$) قرار دهیم، نیروی وارد بر این بار برحسب بردارهای یکه کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:23:28', 4, 'done'),
(7652, ' در شکل مقابل، بار $q_2$ به بار $q_1$ نیروی الکتریکی $\\vec{F}_{21} = (+0/6\\sqrt{2} \\mu N)\\vec{i} + (+0/6\\sqrt{2} \\mu N)\\vec{j}$ را وارد می‌کند. اگر بار $q_2$ را از مبدأ مختصات به نقطه $A$ منتقل کنیم، بزرگی میدان الکتریکی در مبدأ مختصات چند نیوتون بر کولن خواهد شد؟ $(k = 9 \\times 10^9 \\frac{N.m^2}{C^2})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:23:17', 4, 'done'),
(7653, '34- دو خط میدان الکتریکی حاصل از دو بار $q$ و $q\'$ که در فاصله $r$ از یکدیگر قرار دارند، مطابق شکل زیر است. اگر $\\alpha > \\beta$ باشد، کدام مقایسه بین اندازه و نوع بارهای $q$ و $q\'$ درست است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:23:05', 4, 'done'),
(7654, '35- شکل زیر، آرایش خط‌های یک میدان الکتریکی را نشان می‌دهد. از نقطه $D$ یک الکترون از حال سکون رها می‌شود و توسط میدان الکتریکی، تا نقطه $A$ شتاب می‌گیرد. کدام رابطه درباره تغییر انرژی پتانسیل الکتریکی الکترون در این جابه‌جایی درست است؟', 2, 2, 79, 345, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:22:28', 4, 'done'),
(7655, ' مطابق شکل، ذره‌ای به جرم $1 g$ و بار الکتریکی $-6/25 mC$ را با تندی $500 m/s$ در جهت نشان داده شده از نقطه $A$ در میدان الکتریکی یکنواخت پرتاب می‌کنیم؛ بار در نقطه $B$ می‌ایستد و برمی‌گردد. اختلاف پتانسیل نقطه‌های $A$ و $B$ ( $V_A - V_B$ ) چند کیلوولت است؟ (از وزن ذره و نیروی مقاومت هوا چشم‌پوشی کنید.)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:22:09', 4, 'done'),
(7656, ' در شکل زیر، ذره بارداری به جرم $1 g$ را در میدان الکتریکی یکنواختی از حال سکون رها می‌کنیم. اگر بار ذره $-1 \\mu C$ و بزرگی میدان الکتریکی $2000 V/m$ باشد؛ تندی این ذره پس از $1 m$ جابه‌جایی به چند متر بر ثانیه خواهد رسید؟ $(g = 10 m/s^2)$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:21:59', 4, 'done'),
(7657, ' اگر ولتاژ دو سر خازنی $20$ درصد افزایش و بار الکتریکی روی صفحه‌های آن $20$ درصد کاهش یابد، انرژی پتانسیل الکتریکی ذخیره‌شده در آن چگونه تغییر می‌کند؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:21:47', 4, 'done'),
(7658, ' خازنی را با یک باتری ۸ ولتی شارژ و سپس آن را از باتری جدا می‌کنیم؛ اگر $+1/2 \\mu C$ بار الکتریکی از صفحه منفی جدا و به صفحه مثبت منتقل کنیم، با این کار، انرژی ذخیره‌شده در خازن ۴۴ درصد افزایش می‌یابد. ظرفیت خازن چند میکروفاراد است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:21:38', 4, 'done'),
(7659, ' مساحت هر یک از صفحات یک خازن تخت $5 cm^2$ و ظرفیت آن $8 nF$ است. فضای بین دو صفحه خازن از عایقی با ثابت دی‌الکتریک ۱۰ پر شده است. اگر بزرگی میدان الکتریکی بین دو صفحه از $2 \\times 10^7 V/m$ بیشتر شود، پدیده فروریزش رخ می‌دهد. بیشینه باری که می‌تواند در این خازن ذخیره شود، چند میکروکولن است؟ $(\\varepsilon_0 = 9 \\times 10^{-12} \\frac{C^2}{N.m^2})$', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:25:59', 1, '2026-03-27 22:21:31', 4, 'done'),
(7660, 'با توجه به جدول سری الکتریسیته مالشی (تریبوالکتریک) شکل مقابل، یک میله شیشه ای را با پارچه پشمی مالش می دهیم، چه تعداد از عبارت های زیر در مورد آنها صحیح است؟ (میله و پارچه در ابتدا بدون بار الکتریکی هستند. $e=1/6 \\times 10^{-19} C$) الف) جرم پارچه پشمی کاهش می یابد. ب) بار خالص میله شیشه ای می تواند $q=3/2 \\times 10^{-20} C$ شود. پ) همواره مجموع بارهای خالص پارچه پشمی و میله شیشه ای صفر است. ت) بار خالص پارچه پشمی می تواند $q=+8\\mu C$ شود.', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:09', 1, '2026-03-27 22:21:22', 4, 'done'),
(7661, 'دو گوی رسانای کوچک و یکسان A و B دارای بار الکتریکی $q_A=-2q$ و $q_B=4q$ در فاصله مشخصی از هم قرار دارند و در این حالت نیرویی که گوی A به گوی B وارد می کند برابر $\\vec{F}$ است. دو گوی را با هم تماس داده و سپس در همان مکان های قبلی قرار می دهیم. اگر نیرویی که گوی A به گوی B در حالت جدید وارد می کند برابر $\\vec{F}\'$ باشد، کدام گزینه صحیح است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:09', 1, '2026-03-27 22:21:15', 4, 'done'),
(7662, 'دو باتری $20$ ولت و $40$ ولتی در اختیار داریم. پایانه های مثبت باتری ها را به هم متصل کرده و پایانه منفی باتری $40$ ولتی را به زمین متصل می کنیم. در این حالت پتانسیل الکتریکی پایانه مثبت و منفی باتری $20$ ولتی به ترتیب از راست به چپ چند ولت می شود؟', 2, 2, 79, 346, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:09', 1, '2026-03-27 22:21:03', 4, 'done'),
(7663, 'در شکل زیر مراحل انجام آزمایش چگونگی توزیع بارهای الکتریکی در اجسام رسانا به صورت نامرتب نشان داده شده است. در کدام گزینه ترتیب این شکل ها از راست به چپ به درستی مشخص شده است؟', 2, 2, 79, 342, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:20:50', 4, 'done'),
(7664, 'در شکل زیر با بستن کلیدهای $k_1$ و $k_2$ و در حضور میله های باردار با بار منفی چه اتفاقی در کره های رسانای A و B رخ می دهد؟', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:20:26', 4, 'done'),
(7665, 'یک ذره باردار با بار $-4\\mu C$ از مجاورت پایانه منفی یک باتری تا پایانه مثبت آن منتقل شده و انرژی جنبشی آن $0/8$ میلی ژول تغییر می کند. اگر پایانه مثبت این باتری را به نقطه ای با پتانسیل الکتریکی $50$ ولت متصل کنیم، پتانسیل الکتریکی پایانه منفی این باتری چند ولت خواهد شد؟ (تنها نیروی موثر وارد بر ذره، نیروی میدان الکتریکی است.)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:20:13', 4, 'done'),
(7666, 'در فضای میدان الکتریکی یکنواختی به بزرگی $3 \\times 10^4 \\frac{N}{C}$ که جهت آن قائم و رو به بالا است، ذره باردار $q=+4\\mu C$ از حال سکون رها می شود. اگر جرم ذره $2000$ میلی گرم باشد، انرژی جنبشی ذره پس از طی مسافت $20cm$ چند میلی ژول است؟ $(g=10 \\frac{N}{kg})$', 2, 2, 79, 345, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:19:58', 4, 'done'),
(7667, 'در جابه جایی بار الکتریکی $q$ از نقطه A تا نقطه B در اطراف کره باردار با بار الکتریکی Q، کار میدان الکتریکی منفی بوده است. اگر تغییرات پتانسیل الکتریکی بار و تغییرات انرژی پتانسیل بار در این جابه جایی را به ترتیب $\\Delta V$ و $\\Delta U$ بنامیم، کدام یک از گزینه های زیر می تواند صحیح باشد؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:19:45', 4, 'done'),
(7668, 'دو بار الکتریکی $q_1 = 80\\mu C$ و $q_2 = -50\\mu C$ در فاصله d از هم قرار دارند، و بزرگی برآیند میدان الکتریکی حاصل از دو بار در وسط فاصله آنها برابر با $E_1$ است. اگر $25$ درصد از بار $q_1$ را برداریم و به بار $q_2$ منتقل کنیم، برآیند میدان های الکتریکی در وسط این دو بار $E_2$ می شود. $\\frac{E_2}{E_1}$ کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:19:35', 4, 'done'),
(7669, 'مطابق شکل زیر سه بار $q\'$، $q$ و $-q$ در سه رأس یک مثلث قائم الزاویه متساوی الساقین و بار $q\'\'$ در وسط وتر آن ثابت شده اند. اگر مطابق شکل برآیند نیروهای الکتریکی وارد بر بار $q\'\'$ موازی با ضلع بالایی مثلث باشد، $\\frac{q\'}{q}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:18:46', 4, 'done'),
(7670, 'نمودار میدان الکتریکی حاصل از یک بار الکتریکی نقطه ای به جرم $4mg$ بر حسب فاصله از آن، مطابق شکل زیر است. اگر این بار در یک میدان الکتریکی یکنواخت قائم به بزرگی E به حالت تعادل قرار داشته باشد، E چند $\\frac{N}{C}$ است؟ $(g=10\\frac{N}{kg} , k=9\\times 10^9 \\frac{N\\cdot m^2}{C^2})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:18:29', 4, 'done'),
(7671, 'در شکل زیر سه بار الکتریکی نقطه ای در جای خود بر روی محیط یک دایره ثابت شده اند. برآیند میدان های الکتریکی ناشی از آنها در نقطه A چند $kN/C$ و جهت آن به کدام سمت است؟ $(k=9\\times 10^9\\frac{N\\cdot m^2}{C^2})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:18:20', 4, 'done'),
(7672, 'در شکل زیر پنج بار الکتریکی روی رئوس و وسط ضلع یک مربع ثابت شده اند. اگر اندازه بارهای الکتریکی با هم برابر و جهت میدان الکتریکی برآیند ناشی از آنها در مرکز مربع به صورت نشان داده شده باشد، علامت بارهای $q_1$، $q_2$، $q_3$، $q_4$ و $q_5$ به ترتیب از راست به چپ کدام می تواند باشد؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:18:08', 4, 'done'),
(7673, 'مطابق شکل زیر دو بار الکتریکی نقطه ای $q_1$ و $q_2$ بر روی محور x ثابت شده اند و میدان الکتریکی خالص ناشی از آنها در نقطه A برابر با صفر است. اگر بار الکتریکی $q_3=24\\mu C$ را در نقطه A قرار دهیم، بردار میدان الکتریکی آن در نقطه ای که بار الکتریکی $q_1$ در آن قرار دارد، در SI کدام است؟ $(k=9 \\times 10^9 \\frac{N\\cdot m^2}{C^2})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:17:59', 4, 'done'),
(7674, 'مطابق شکل زیر بار $q\'$ میان دو بار هم اندازه و ناهمنام ثابت شده است. چند برابر بار مثبت $q$ را به هر دو بار اضافه کنیم تا اندازه برآیند نیروهای الکتریکی وارد بر بار $q\'$، بدون تغییر جهت آن ۲۰ درصد کاهش یابد؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:17:44', 4, 'done'),
(7675, 'مطابق شکل زیر دو بار الکتریکی $q_1$ و $q_2 = (q_1 - 4)\\mu C$ در مکان های مشخص ثابت شده اند. $q_1$ چند میکروکولن باشد تا میدان الکتریکی کل در نقطه M برابر صفر شود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:17:29', 4, 'done'),
(7676, 'مطابق شکل زیر درون یک کره رسانای توخالی بدون بار یک گوی فلزی با بار $q>0$ از یک نخ عایق و سبک آویزان می کنیم. اگر این کره در یک میدان الکتریکی خارجی یکنواخت افقی قرار گیرد. در این صورت گوی فلزی .....................', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:17:20', 4, 'done'),
(7677, ' ذره ای باردار را در راستای یک میدان الکتریکی افقی یکنواخت از نقطه $M$ با تندی $v$ پرتاب می کنیم و با تندی $\\frac{v}{2}$ از نقطه $N$ عبور می کند. اگر جهت حرکت ذره باردار در نقطه $P$ تغییر کند، در این صورت نسبت اختلاف پتانسیل بین نقاط $M$ و $N$ ($V_M - V_N$) به اختلاف پتانسیل بین نقاط $N$ و $P$ ($V_P - V_N$) کدام است؟ (از نیروی وزن ذره صرف نظر کنید)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:16:48', 4, 'done'),
(7678, ' مطابق شکل، دو بار الکتریکی $q_1$ و $q_2$ در مجاورت هم قرار گرفته اند و خطوط میدان الکتریکی آنها رسم شده است. میدان الکتریکی خالص ناشی از آنها در کدام نقطه بر روی خط واصل آنها می تواند صفر باشد؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:16:30', 4, 'done'),
(7679, ' مطابق شکل زیر دو صفحه رسانای باردار به اختلاف پتانسیل ثابت $360V$ متصل شده است. فاصله بین دو صفحه را $3mm$ افزایش می دهیم، اگر اختلاف پتانسیل نقاط $A$ و $B$ ($V_B - V_A$) در حالت اول $V_{BA}$ و در حالت دوم $V\'_{BA}$ باشد، حاصل $V\'_{BA} - V_{BA}$ چند ولت است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:16:19', 4, 'done'),
(7680, ' یک خازن که فاصله بین صفحات آن هوا است را به اختلاف پتانسیل ثابتی متصل می کنیم. با اعمال کدام تغییر در این خازن، انرژی ذخیره شده در خازن کاهش می یابد؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:16:06', 4, 'done'),
(7681, ' خازن تختی با صفحات دایره ای شکل در اختیار داریم. اگر قطر صفحات خازن را نصف و اختلاف پتانسیل دو سر آن را $\\frac{1}{4}$ برابر کنیم، ظرفیت خازن چند برابر خواهد شد؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:15:53', 4, 'done'),
(7682, ' ظرفیت خازنی $25\\mu F$ است. اگر اختلاف پتانسیل دو سر خازن را $20$ درصد افزایش دهیم بار ذخیره شده در آن $32\\mu C$ افزایش می یابد. اختلاف پتانسیل اولیه دو سر خازن چند ولت است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:15:44', 4, 'done'),
(7683, ' خازن تختی که دی الکتریک آن هواست به مولد وصل و دارای انرژی $U$ است. اگر در این حالت فاصله بین دو صفحه خازن را $3$ برابر کرده و سپس آن را از مولد جدا نموده و پس از آن بین دو صفحه خازن را با عایقی به ضریب دی الکتریک $2$ پر کنیم، انرژی آن چند $U$ می شود؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:15:29', 4, 'done'),
(7684, ' صفحات خازن تختی به شکل دایره به شعاع $2cm$ بوده و فاصله بین دو صفحه $5mm$ است و در فضای بین دو صفحه دی الکتریکی با ثابت $25$ قرار دارد. اگر $0/27\\mu J$ انرژی در خازن ذخیره شده باشد، اختلاف پتانسیل بین دو صفحه آن چند ولت است؟ ($\\pi = 3$ و $\\varepsilon_0 = 9 \\times 10^{-12} \\frac{F}{m}$)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:15:20', 4, 'done'),
(7685, ' خازن تختی که فاصله صفحات آن $0/5mm$ و مساحت هر یک از صفحات آن $80cm^2$ است را از باتری جدا کرده و سپس $25$ درصد از بار صفحه مثبت آن را به صفحه منفی منتقل می کنیم. اگر بزرگی میدان الکتریکی بین صفحات خازن $125 \\frac{kN}{C}$ تغییر کند، انرژی ذخیره شده در خازن در حالت اولیه چند میکروژول است؟ ($\\varepsilon_0 = 9 \\times 10^{-12} \\frac{F}{m}$ و بین صفحات خازن هوا است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:14:51', 4, 'done'),
(7686, ' ظرفیت خازنی $2\\mu F$ است. اختلاف پتانسیل بین دو صفحه آن را یک ولت افزایش می دهیم، انرژی آن $5 \\times 10^{-6} J$ افزایش می یابد. اختلاف پتانسیل اولیه این خازن چند ولت بوده است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:14:31', 4, 'done'),
(7687, ' فاصله بین صفحات خازنی $5mm$، مساحت هر یک از صفحه های آن $40cm^2$ و بین صفحات آن هوا است. اگر فاصله بین صفحات خازن $4mm$ کاهش یابد، ظرفیت خازن چند پیکوفاراد افزایش می یابد؟ ($\\varepsilon_0 = 9 \\times 10^{-12} C^2 / N.m^2$)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:13:30', 4, 'done'),
(7688, ' یک خازن تخت به یک باتری بسته شده است. پس از مدتی، در حالی که خازن همچنان به باتری متصل است، فاصله بین صفحه های خازن را دو برابر می کنیم. کدام موارد زیر درست است؟ الف) میدان الکتریکی میان صفحه ها نصف می شود. ب) اختلاف پتانسیل میان صفحه ها نصف می شود. پ) ظرفیت خازن دو برابر می شود. ت) بار روی صفحه ها نصف می شود.', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:13:20', 4, 'done'),
(7689, ' دو سر خازنی را که دی الکتریک آن هوا است به دو سر یک باتری وصل می کنیم. در این حالت انرژی ذخیره شده در آن $U$ می شود. اگر در حالتی که خازن به باتری وصل است، فاصله بین دو صفحه آن را $n$ برابر کنیم، انرژی آن $U\'$ می شود ولی اگر خازن اولیه را از باتری جدا کنیم و سپس فاصله بین دو صفحه را $n$ برابر کنیم، انرژی آن $U\'\'$ می شود. نسبت $\\frac{U\'\'}{U\'}$ چقدر است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:13:11', 4, 'done'),
(7690, ' ظرفیت خازنی $5$ میکروفاراد و بار الکتریکی آن $q$ است. اگر $3mC$ بار الکتریکی را از صفحه منفی جدا کرده و به صفحه مثبت منتقل کنیم. انرژی ذخیره شده در خازن به اندازه $4/5J$ افزایش می یابد. $q$ چند میلی کولن است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:13:03', 4, 'done'),
(7691, ' با توجه به این که بار الکتریکی هر الکترون برابر $1/6 \\times 10^{-19}$ کولن است، وقتی که جریانی به شدت یک آمپر از مداری می گذرد، در هر ثانیه چند الکترون از این مدار خواهد گذشت؟', 2, 2, 79, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:12:52', 4, 'done'),
(7692, ' در شکل زیر، بار الکتریکی کره رسانای $A$ بعد از برقراری جریان بدون تغییر علامت $75$ درصد کاهش می یابد و جریان متوسط عبوری از سیم در حین هم پتانسیل شدن کره ها برابر $30mA$ است. اگر مدت زمان برقراری جریان $0/2ms$ باشد، در این صورت اندازه بار کره $A$ قبل از برقراری جریان چند میکروکولن بوده است؟', 2, 2, 79, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:11:47', 4, 'done'),
(7693, ' کره رسانایی با بار منفی روی یک پایه عایق قرار دارد. اگر از این کره تعداد $1/5 \\times 10^{13}$ الکترون بگیریم، اندازه بار آن $3$ برابر شده و علامت بار آن تغییر می کند. اگر قبل از گرفتن الکترون این کره را با یک سیم رسانا به زمین متصل می کردیم تعداد ......................... الکترون از ......................... به ......................... منتقل می شد. ($e = 1/6 \\times 10^{-19} C$)', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:11:24', 4, 'done'),
(7694, ' یک کره کوچک فلزی از جنس $A$ را با یک کره کوچک غیرفلزی از جنس $G$ مالش می دهیم و سپس کره کوچک فلزی باردار $A$ را با کره کوچک فلزی $C$ تماس می دهیم. با توجه به موقعیت این کره ها در جدول سری الکتریسیته مالشی، در کدام آرایش، کره $C$ می تواند تعادل داشته باشد؟ (تمام کره ها در ابتدا خنثی هستند.) انتهای مثبت سری A B C D E F G انتهای منفی سری', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:08:46', 4, 'done'),
(7695, ' مطابق شکل زیر، چهار بار الکتریکی نقطه ای بر روی قطر و رئوس مربعی به ضلع $a$ قرار دارند. برآیند میدان های الکتریکی بارها در مرکز مربع مطابق کدام گزینه است؟ ($AB=BC=CD=DE$)', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:08:37', 4, 'done'),
(7696, 'مطابق شکل زیر، سه بار الکتریکی نقطه‌ای روی یک خط راست ثابت شده‌اند و نیروی خالص وارد بر بار $Q$ از طرف دو بار دیگر برابر با $\\vec{F}$ است. اگر نیروی خالص وارد بر بار $q$ از طرف دو بار دیگر برابر با $-\\frac{2}{3}\\vec{F}$ باشد، حاصل $|\\frac{Q}{q}|$ کدام است؟', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:08:28', 4, 'done'),
(7697, 'ذره‌ای به جرم ۲۵۰ گرم و بار الکتریکی $-5\\mu C$ از نقطه $A$ که پتانسیل الکتریکی آن $2kV$ است، رها می‌کنیم تا به نقطه $B$ برسد و در ادامه، ذره باردار از نقطه $B$ به نقطه $C$ با پتانسیل الکتریکی $6kV$ می‌رسد. اگر در جابه‌جایی از نقطه $A$ تا نقطه $B$ کار میدان الکتریکی برابر $5mJ$ باشد، تندی این ذره در نقطه $C$ چند برابر تندی این ذره در نقطه $B$ است؟ (از نیروی وزن و اصطکاک صرف‌نظر شود.)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:08:19', 4, 'done'),
(7698, 'خازن پرشده‌ای را از مولد جدا کرده و فاصله بین صفحات خازن را با دی‌الکتریکی با ثابت ۸ پر می‌کنیم، انرژی ذخیره شده در خازن چند برابر می‌شود؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:08:06', 4, 'done'),
(7699, 'در شکل زیر، دو صفحه رسانای موازی افقی در فاصله $4mm$ از یکدیگر قرار دارند و به اختلاف پتانسیل $V$ متصل شده‌اند. ذره‌ای با بار الکتریکی $5\\mu C$ و جرم $0/4$ گرم بین دو صفحه در حال تعادل قرار دارد. $V$ برحسب ولت کدام است؟ ($g = 10 \\frac{N}{kg}$)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:07:53', 4, 'done'),
(7700, 'اگر یک میله شیشه‌ای خنثی را با یک پارچه ابریشمی خالص خنثی مالش دهیم، پس از مالش بار الکتریکی یکی از آن‌ها ۱ پیکوکولن می‌شود. در این‌صورت شیشه به تعداد .............. الکترون .............. است. ($e = 1/60 \\times 10^{-19} C$)', 2, 2, 79, 342, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:07:42', 4, 'done'),
(7701, 'سه کره رسانای کوچک و مشابه $A$، $B$ و $C$ به ترتیب دارای بارهای $q_A = 9\\mu C$، $q_B = 8\\mu C$ و $q_C = -6\\mu C$ روی یک خط راست مطابق شکل زیر روی پایه‌های عایقی قرار دارند. ابتدا کره $B$ را با کره $C$ تماس داده و جدا می‌کنیم و سپس کره $B$ را با کره $A$ تماس می‌دهیم و در انتها سه کره را در مکان قبلی خود قرار می‌دهیم. برایند نیروی الکتریکی وارد بر کره $B$ در حالت جدید چند برابر حالت قبلی است؟ (شعاع کره‌ها در مقایسه با فاصله بین کره‌ها قابل صرف‌نظر است.)', 2, 2, 79, 342, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:07:32', 4, 'done'),
(7702, 'دو بار الکتریکی $q_1 = 3\\mu C$ و $q_2 = -27\\mu C$ به ترتیب در نقاطی با مختصات $(-4cm, 4cm)$ و $(6cm, -6cm)$ قرار دارند. بار $q_3 = 2nC$ را در چه نقطه‌ای قرار دهیم تا نیروی خالص وارد بر آن صفر شود؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:07:16', 4, 'done'),
(7703, 'مطابق شکل، دو بار نقطه‌ای در فاصله $d$ از یکدیگر قرار داشته و میدان خالص حاصل از این دو بار در نقطه $M$، برابر $\\vec{E}$ است. اگر بار $q_2$ را حذف کنیم، میدان الکتریکی خالص در این نقطه برابر $-\\frac{1}{3}\\vec{E}$ خواهد شد. در صورتی که نیمی از بار $q_1$ را به $q_2$ منتقل کنیم، میدان الکتریکی حاصل از بار $q_2$ در محل بار $q_1$ چند برابر میدان حاصل از بار $q_1$ در محل بار $q_2$ می‌شود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:07:01', 4, 'done'),
(7704, 'اندازه میدان الکتریکی ناشی از یک ذره دارای بار الکتریکی $q = 2\\mu C$، در نقطه معین $P$ برابر $E$ می‌باشد. اگر $6/25 \\times 10^{12}$ الکترون از ذره بگیریم و فاصله ذره از نقطه $P$ را ۲۵ درصد افزایش دهیم، میدان الکتریکی ناشی از این ذره در نقطه $P$ چند درصد تغییر می‌کند؟ ($e = 1/6 \\times 10^{-19} C$)', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 22:06:49', 4, 'done'),
(7705, 'مطابق شکل در سه رأس از چهار رأس یک مستطیل بارهای $q_1$، $q_2$ و $q_3$ قرار گرفته‌اند. اگر نیروی الکتریکی خالص وارد بر بار $q_2$، بردار $\\vec{F}$ باشد، نسبت $\\frac{q_3}{q_1}$ کدام یک از گزینه‌های زیر می‌باشد؟ ($\\sin 37^\\circ = 0/6$)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:57:00', 5, 'done'),
(7706, 'مطابق شکل زیر، در یک میدان الکتریکی یکنواخت $E = 2 \\times 10^3 \\frac{N}{C}$، پروتونی را از نقطه $A$ رها می‌کنیم. اگر پروتون با تندی $2 \\times 10^5 \\frac{m}{s}$ به صفحه منفی برخورد کند، فاصله نقطه $A$ از صفحه مثبت چند سانتی‌متر است؟ (جرم پروتون $1/6 \\times 10^{-27} kg$ و بار پروتون $1/6 \\times 10^{-19} C$ است. از وزن پروتون و اتلاف انرژی صرف‌نظر نمایید.)', 2, 2, 79, 346, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:56:50', 5, 'done'),
(7707, 'مطابق شکل زیر، ذره‌ای به جرم $m$ و بار $q > 0$ را از نقطه $A$ در راستای قائم به سمت بالا با تندی اولیه $v_A$ پرتاب می‌کنیم. مقایسه تندی و بزرگی شتاب ذره در نقاط $A$ و $B$ مطابق کدام گزینه است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:56:34', 5, 'done'),
(7708, 'ذره‌ای به جرم $0/8g$ و بار الکتریکی $-12\\mu C$ در یک میدان الکتریکی یکنواخت قائم در نقطه $A$ رها می‌شود. بزرگی نیروی خالص وارد بر ذره برابر ۲ میلی‌نیوتون و جهت آن به سمت پایین است. اگر ذره در مبدأ زمان از نقطه $A$ رها شود و $0/2$ ثانیه پس از آن از نقطه $B$ عبور کند، $V_B - V_A$ (اختلاف پتانسیل نقاط $A$ و $B$) چند ولت است؟ ($g = 10 \\frac{N}{kg}$)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:56:16', 5, 'done'),
(7709, 'چه تعداد از عبارت‌های زیر در مورد میدان یکنواخت شکل زیر، درست بیان شده است؟ الف) در جابه‌جایی الکترون از نقطه $a$ تا نقطه $b$، انرژی پتانسیل الکتریکی الکترون کاهش می‌یابد. ب) کار نیروی میدان الکتریکی در جابه‌جایی الکترون از نقطه $a$ تا نقطه $c$ مثبت است. پ) اختلاف پتانسیل الکتریکی بین دو نقطه $b$ و $c$ ($V_b - V_c$) بزرگ‌تر از اختلاف پتانسیل الکتریکی بین دو نقطه $a$ و $c$ ($V_a - V_c$) است. ت) انرژی پتانسیل الکتریکی الکترون در جابه‌جایی از نقطه $c$ تا نقطه $a$ کاهش می‌یابد.', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:56:01', 5, 'done'),
(7710, 'مطابق شکل زیر، دو بار الکتریکی در فاصله $r$، نیروی جاذبه $F$ بر یکدیگر وارد می‌کنند. اگر با ثابت بودن فاصله، ۲۵ درصد از بار $q_1$ را به $q_2$ انتقال دهیم، نیروی جاذبه بین دو بار چند درصد و چگونه تغییر می‌کند؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:55:49', 5, 'done'),
(7711, 'دو بار الکتریکی نقطه‌ای $q_1$ و $q_2 = 2q_1$ در فاصله $r$ از هم قرار دارند و به هم نیروی دافعه وارد می‌کنند. چند درصد از بار $q_2$ را به $q_1$ منتقل کنیم تا در همان فاصله، نیروی دافعه بین بارهای الکتریکی بیشینه شود؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:55:41', 5, 'done'),
(7712, 'در شکل روبه‌رو، برایند نیروهای الکتریکی وارد بر هر یک از بارها صفر است. اگر بار $q_4 = 1\\mu C$ در نقطه $O$ قرار گیرد، نیروی الکتریکی وارد بر آن چند نیوتون است؟ ($k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:55:31', 5, 'done'),
(7713, 'مطابق شکل زیر، در چهار رأس یک مربع به ضلع ۲۰ سانتی‌متر، بارهای الکتریکی نقطه‌ای قرار داده‌ایم. اگر بار $q_0 = -10 \\mu C$ را در مرکز مربع قرار دهیم، اندازۀ نیروی برایند وارد بر آن چند نیوتون و در کدام جهت خواهد بود؟ $(k=9\\times 10^9 N\\cdot m^2/C^2)$', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:55:17', 5, 'done'),
(7714, 'میدان الکتریکی حاصل از بار $q$ در نقطۀ A که در فاصلۀ ۳۰ سانتی‌متری آن قرار دارد برابر $10^5 N/C$ است. اگر بار $q\'$ در نقطۀ A قرار گیرد، نیرویی برابر $0/02 N$ از طرف میدان به آن وارد می‌شود. اندازه‌های $q$ و $q\'$ به ترتیب از راست به چپ چند میکروکولن‌اند؟ $(k=9\\times 10^9 N\\cdot m^2/C^2)$', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:54:57', 5, 'done'),
(7715, 'مطابق شکل زیر، دو ذرۀ باردار $q_1 = -2q$ و $q_2 = 6q$ در فاصلۀ $3r$ از هم قرار دارند و بزرگی میدان الکتریکی خالص (برایند) ناشی از دو ذره در نقطۀ O برابر $E_1$ است. اگر ۵۰ درصد از بار $q_2$ به $q_1$ منتقل شود، بزرگی میدان الکتریکی خالص (برایند) در نقطۀ O برابر $E_2$ می‌شود. $\\frac{E_2}{E_1}$ کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:54:37', 5, 'done'),
(7716, 'در شکل مقابل، ۳ بار الکتریکی در نقاط مشخص‌شده قرار دارند. بردار میدان الکتریکی در مبدأ دستگاه مختصات در SI کدام است؟ $(k=9\\times 10^9 N\\cdot m^2/C^2)$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:54:24', 5, 'done'),
(7717, 'مطابق شکل، در میدان الکتریکی یکنواخت $10^5 N/C$ ذره‌ای با بار الکتریکی $q = -5 \\mu C$ در نقطۀ B بدون سرعت اولیه رها می‌شود. وقتی این ذره در مسیر مستقیم ۲۰ سانتی‌متر جابه‌جا شده و به نقطۀ A می‌رسد، انرژی جنبشی آن چند ژول می‌شود؟ (از اثر گرانش و نیروهای مقاوم در مقابل حرکت ذره صرف‌نظر شود.)', 2, 2, 79, 345, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:54:11', 5, 'done'),
(7718, 'در یک میدان الکتریکی یکنواخت، ذرۀ بارداری به جرم $0/1$ گرم از نقطه‌ای به پتانسیل الکتریکی $+100$ ولت از حال سکون به حرکت درمی‌آید و با سرعت ۱۰ متر بر ثانیه به نقطۀ دیگری به پتانسیل الکتریکی $-100$ ولت می‌رسد. اگر در این مسیر نیروی مؤثر وارد بر ذره فقط حاصل از میدان الکتریکی باشد، بار الکتریکی ذره چند میکروکولن است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:53:57', 5, 'done'),
(7719, 'مطابق شکل، دو کرۀ فلزی مجزا و توخالی مشابه و خنثی داریم. در مرکز کرۀ سمت راست بار مثبت و هم‌چنین بر سطح شمارۀ (۳) از کرۀ سمت چپ بار مثبت قرار می‌دهیم. پس از ایجاد تعادل، بار هر یک از سطوح (۱)، (۲)، (۳) و (۴) به‌ترتیب از راست به چپ کدام است؟', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:53:43', 5, 'done'),
(7720, 'مطابق شکل زیر، دو بار الکتریکی $q_A$ و $q_B$ در فاصلۀ d از یکدیگر ثابت شده‌اند و نیروی الکتریکی وارد بر بار $q_A$ از طرف بار $q_B$ برابر با بردار $\\vec{F}$ است. اگر با ثابت‌ماندن بار $q_B$ بار $q_A$ را در راستای خط واصل دو بار، به اندازۀ $\\frac{d}{2}$ از بار $q_B$ دور کنیم، نیروی وارد بر بار $q_B$ در این حالت مطابق کدام گزینه است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:53:22', 5, 'done'),
(7721, 'مطابق شکل زیر، ۳ کرۀ رسانای مشابه A، B و C کنار یکدیگر قرار دارند و در ابتدا بار کرۀ A برابر $18\\mu C$ و کره‌های B و C خنثی هستند. ابتدا کلید $K_1$ را می‌بندیم تا تعداد $n_1$ الکترون از سیم اتصال بین کره‌های A و B منتقل شود. در ادامه کلید $K_1$ را باز و کلید $K_2$ را می‌بندیم و تعداد $n_2$ الکترون از سیم اتصال بین کره‌های B و C منتقل می‌شود. در این حالت حاصل $\\frac{n_1}{n_2}$ کدام است؟ (فرض کنید بار الکتریکی روی سیم‌های رابط باقی نمی‌مانند.)', 2, 2, 79, 342, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:53:12', 5, 'done'),
(7722, 'در شکل زیر، بار الکتریکی $-q$ را یک بار با شتاب ثابت و بار دیگر با سرعت ثابت از نقطۀ A تا نقطۀ B، جابه‌جا می‌کنیم. در این دو حالت تغییر انرژی پتانسیل الکتریکی بار چگونه است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:52:49', 5, 'done'),
(7723, 'یک ذرۀ باردار با بار $-4 \\mu C$ از مجاورت پایانۀ منفی یک باتری تا پایانۀ مثبت آن منتقل شده و انرژی جنبشی آن $0/8$ میلی‌ژول تغییر می‌کند. اگر پایانۀ مثبت این باتری را به زمین متصل کنیم، پتانسیل الکتریکی پایانۀ منفی این باتری چند ولت خواهد شد؟ (تنها نیروی مؤثر وارد بر ذره، نیروی میدان الکتریکی است.)', 2, 2, 79, 346, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:52:37', 5, 'done'),
(7724, 'مطابق شکل زیر، دو بار الکتریکی نقطه‌ای $q_1$ و $q_2$ بر روی محور x ثابت شده‌اند و میدان الکتریکی خالص ناشی از آن‌ها در نقطۀ A برابر با صفر است. اگر بار الکتریکی $q_3 = 24\\mu C$ را در نقطۀ A قرار دهیم، بردار میدان الکتریکی حاصل از آن در محل بار الکتریکی $q_1$ در SI کدام است؟ $(k=9\\times 10^9 N\\cdot m^2/C^2)$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:52:19', 5, 'done'),
(7725, 'مطابق شکل مقابل یک خازن باردار به ظرفیت $5 \\mu F$ از مولد جدا شده است و اختلاف پتانسیل نقاط A و B برابر با $15V$ است. اگر فاصلۀ صفحات خازن را ۲۰ درصد افزایش دهیم، انرژی ذخیره شده در خازن چند ژول تغییر می‌کند؟ (فضای بین صفحات خازن هواست.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:52:10', 5, 'done'),
(7726, 'در فضای میدان الکتریکی یکنواختی به بزرگی $3 \\times 10^4 \\frac{N}{C}$ که جهت آن قائم و رو به بالا است، ذرۀ باردار $q = +4\\mu C$ از حال سکون رها می‌شود. اگر جرم ذرۀ $2000$ میلی‌گرم باشد، انرژی جنبشی ذره پس از طی مسافت $20 cm$ چند میلی‌ژول است؟ $(g=10 \\frac{N}{kg})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:52:01', 5, 'done'),
(7727, 'ذره‌ای با بار الکتریکی $q = -6 \\mu C$ را در نقطۀ A با پتانسیل الکتریکی $|V_A| = 11 V$ رها می‌کنیم. اگر انرژی جنبشی این ذره در نقطۀ B برابر $0/12$ میلی‌ژول و $|V_A| > |V_B|$ باشد، پتانسیل الکتریکی نقطۀ B چند ولت است؟ (تنها نیروی وارد بر ذره نیروی الکتریکی است.)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:51:46', 5, 'done'),
(7728, ' بار نقطه ای $q = -4\\mu C$ در صفحه مختصات $xoy$، در مکان $(-4cm, 2cm)$ قرار دارد. بزرگی میدان الکتریکی حاصل از بار $q$ در کدام یک از مختصات مشخص شده در گزینه ها برابر با $2 \\times 10^7 \\frac{N}{C}$ می شود؟ ($k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:51:35', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7729, ' در شکل زیر سه ذره باردار $q_1$، $q_2$ و $q_3$ روی خط راستی قرار دارند و به بار $q_2$ نیروی الکتریکی خالص $F$ وارد می شود اگر روی خط واصل بارها، بار $q_1$ را به اندازه $\\frac{3r}{4}$ و بار $q_3$ را به اندازه $\\frac{2r}{3}$ به بار $q_2$ نزدیک کنیم، نیروی خالص وارد بر بار $q_2$ چند برابر $F$ می شود؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:51:26', 5, 'done'),
(7730, ' مطابق شکل زیر، سه ذره باردار در سه رأس یک مثلث قائم الزاویه قرار دارند. اگر نیروی خالص الکتریکی وارد بر بار $q_2$، موازی خط واصل بارهای $q_1$ و $q_3$ باشد، حاصل $\\frac{q_3}{q_1}$ کدام است؟ ($\\cos 53^\\circ = 0/6$)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:51:16', 5, 'done'),
(7731, ' اگر اختلاف پتانسیل الکتریکی دو سر یک خازن را $7/5 V$ افزایش دهیم، بار الکتریکی ذخیره شده در آن $30\\mu C$ و انرژی الکتریکی ذخیره شده در آن $187/5\\mu J$ تغییر می کند. ظرفیت خازن بر حسب میکروفاراد و بار نهایی آن بر حسب میکروکولن به ترتیب از راست به چپ کدام است؟ (پدیده فرشکست رخ نمی دهد.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:51:02', 5, 'done'),
(7732, ' در یک میدان الکتریکی ذره باردار $q = -5\\mu C$ از نقطه $A$ با پتانسیل الکتریکی $-80 V$ به نقطه $B$ با پتانسیل الکتریکی $-120 V$ منتقل می شود. اگر تنها نیروی مؤثر وارد بر ذره، نیروی الکتریکی باشد، انرژی جنبشی ذره چند میلی ژول و چگونه تغییر می کند؟', 2, 2, 79, 346, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:50:44', 5, 'done'),
(7733, ' مطابق شکل، بین دو صفحه موازی و رسانای $M$ و $N$، یک میدان الکتریکی یکنواخت وجود دارد به گونه ای که $V_M - V_N = 10 V$ است. در این حالت، کدام گزینه در مورد پتانسیل الکتریکی نقاط $A$ و $B$ صحیح است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:50:26', 5, 'done'),
(7734, ' خازنی به ظرفیت $36\\mu F$ که بین صفحات آن هوا قرار دارد، به مولدی متصل است. پس از پر شدن خازن بار ذخیره شده در آن $30\\mu C$ می شود. اگر این خازن را از مولد جدا کنیم و بین صفحات آن دی الکتریکی قرار دهیم، اختلاف پتانسیل دو سر آن $10$ درصد تغییر می کند. در این حالت، انرژی خازن چند میکروژول و چگونه تغییر می کند؟', 2, 2, 79, 348, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:50:14', 5, 'done'),
(7735, ' خازن تختی را به وسیله یک مولد پر کرده و از مولد جدا نموده و سپس یک دی الکتریک با ثابت $K=4$ بین صفحه های آن وارد می کنیم به طوری که تمام فضای بین دو صفحه پر شود. اگر در این حالت، انرژی خازن $300\\mu J$ تغییر کند، انرژی اولیه آن چند میکروژول بوده است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:50:04', 5, 'done'),
(7736, ' قطر مقطع سیم $A$ دو برابر قطر مقطع سیم $B$، مقاومت ویژه سیم $A$، $4$ برابر مقاومت ویژه سیم $B$ و چگالی سیم $A$، $\\frac{1}{3}$ چگالی سیم $B$ است. اگر جرم دو سیم با هم برابر و مقاومت الکتریکی سیم $B$ برابر $240 \\Omega$ باشد، مقاومت الکتریکی سیم $A$ چند اهم است؟', 2, 2, 79, 350, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:49:55', 5, 'done'),
(7737, ' مطابق شکل زیر، دو کره رسانای فلزی کاملاً مشابه، اولی دارای بار $q_1$ و دومی دارای بار $q_2 = -12\\mu C$، بر روی پایه های عایقی قرار دارند. اگر این دو کره را با بستن کلید $K$، توسط سیم فلزی به یکدیگر وصل کنیم، $0/001s$ طول می کشد تا هم پتانسیل شوند. در صورتی که در این مدت جریان الکتریکی متوسط $4$ میلی آمپر از سیم بگذرد، بار $q_1$ چند میکروکولن می تواند باشد؟', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:49:01', 5, 'done'),
(7738, ' در شکل زیر، بخشی از جدول سری الکتریسیته مالشی (تریبوالکتریک) را مشاهده می کنید. اگر پارچه ای از جنس ابریشم را به آلومینیوم و قطعه ای کاغذی را به یک قطعه چوب مالش داده، سپس قطعه آلومینیمی را در کنار قطعه چوب قرار دهیم، به ترتیب از راست به چپ نوع بار قطعه آلومینیمی و نوع نیروی الکتریکی که قطعه آلومینیمی و قطعه چوبی به یکدیگر وارد می کنند، کدام است؟ انتهای مثبت سری ابریشم آلومینیم پوست انسان کاغذ چوب پارچه کتان انتهای منفی سری', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:48:46', 5, 'done'),
(7739, ' مطابق شکل زیر، سه بار الکتریکی $q_1$، $q_2$ و $q_3$ در سه نقطه، در صفحه $xy$ ثابت شده اند. اگر بردار برآیند نیروهای الکتریکی وارد بر بار $q_2$ در سوی مثبت محور $x$ باشد، در این حالت نسبت $\\frac{q_3}{q_1}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:48:38', 5, 'done'),
(7740, ' مطابق شکل مقابل، ذره بارداری با بار الکتریکی $q = +20\\mu C$ را از نقطه $A$ با پتانسیل $50V$ و از مجاورت کره باردار تا نقطه $B$ جابه جا می کنیم. اگر در این جابه جایی انرژی پتانسیل الکتریکی ذره $5mJ$ تغییر کند، پتانسیل نقطه $B$ چند ولت است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:47:02', 5, 'done'),
(7741, ' هنگامی که اختلاف پتانسیل بین دو صفحه یک خازن که فاصله بین صفحات آن هوا است را $200$ ولت افزایش دهیم، اندازه بار روی هر صفحه خازن $1/8$ نانوکولن اضافه می شود. اگر فاصله بین صفحات $0/2$ میلی متر باشد، مساحت هر یک از صفحات خازن چند سانتی متر مربع است؟ ($\\varepsilon_0 = 9 \\times 10^{-12} \\frac{F}{m}$)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:46:52', 5, 'done'),
(7742, ' مطابق شکل زیر، دو صفحه یک خازن تخت افقی به پایانه های یک باتری متصل شده است. اگر صفحه پایینی این خازن را کمی به سمت پایین جابه جا کنیم، پس از برقراری تعادل الکتریکی، چه تعداد از کمیت های زیر کاهش می یابد؟ آ) اختلاف پتانسیل الکتریکی بین نقطه های $A$ و $B$ ($V_A - V_B$) ب) پتانسیل الکتریکی نقطه $B$ ($V_B$) پ) بار ذخیره شده در خازن ت) پتانسیل الکتریکی صفحه مثبت', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:46:42', 5, 'done'),
(7743, ' مطابق شکل زیر، دو کره فلزی کاملاً مشابه که بر روی پایه های عایقی قرار دارند را با یک سیم رسانا به هم متصل می کنیم. اگر بعد از مدت $0/02s$، دو کره هم پتانسیل شوند، در این مدت چند میکروآمپر - ساعت بار الکتریکی از سیم عبور می کند؟', 2, 2, 79, 347, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:46:33', 5, 'done'),
(7744, ' بار الکتریکی $q$ روی محور $x$ و در مکان $x = +10cm$ ثابت شده است و میدان الکتریکی آن در مکان $x_1 = -20cm$ برابر $\\vec{E}$ است. میدان الکتریکی حاصل از همان بار $q$ در مکان $x_2 = +25cm$، مطابق کدام گزینه است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 23:21:10', 5, 'done'),
(7745, 'کره کوچک و توپر فلزی A با بار الکتریکی $q_A$ در میدان الکتریکی قائم $\\vec{E}_A$ به حالت تعادل قرار دارد. اگر کره کوچک و توپر فلزی B که شعاع آن دو برابر شعاع کره A و بار الکتریکی آن برابر $q_B = -4q_A$ است را در میدان الکتریکی یکنواخت $\\vec{E}_B = -4\\vec{E}_A$ رها کنیم، چه اتفاقی برای آن می‌افتد؟ (کره‌های A و B هم‌جنس‌اند و g شتاب گرانشی است.)', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:44:51', 5, 'done'),
(7746, 'خازنی را که دی‌الکتریک آن هوا است به‌وسیله یک مولد پر نموده و سپس از مولد جدا می‌کنیم. اگر در این حالت فاصله بین صفحه‌های خازن را نصف کنیم، به ترتیب از راست به چپ، اختلاف پتانسیل الکتریکی و میدان الکتریکی بین دو صفحه خازن چند برابر می‌شود؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:44:41', 5, 'done'),
(7747, 'فاصله بین صفحات یک خازن باردار جداشده از باتری $0/3$ میلی‌متر است. اگر ۶ میکروکولن بار از صفحه مثبت خازن به صفحه منفی آن منتقل کنیم، بزرگی میدان الکتریکی بین صفحات خازن، ۲۴۰ واحد SI تغییر می‌کند. ظرفیت خازن چند میکروفاراد است؟ (فاصله بین صفحات خازن خلأ است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:44:26', 5, 'done'),
(7748, 'بار الکتریکی $q = -34\\mu C$ در صفحه مختصات در نقطه $(5cm, 4cm)$ و $A$ قرار دارد. بزرگی میدان الکتریکی حاصل از این بار در نقطه $(-6cm, -3cm)$ و $B$ چند نیوتون بر کولن است؟ ($k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:44:09', 5, 'done'),
(7749, 'اگر بار $q = -5\\mu C$ از نقطه‌ای با پتانسیل الکتریکی $-200V$ به نقطه‌ای با پتانسیل الکتریکی $-600V$ جابه‌جا شود، انرژی پتانسیل الکتریکی آن ........................ میلی‌ژول ........................ می‌یابد.', 2, 2, 79, 346, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:43:58', 5, 'done'),
(7750, 'اگر مساحت سطح مشترک صفحات خازنی را نصف و اختلاف پتانسیل بین صفحات آن را ۲۰ درصد کاهش دهیم، بار الکتریکی ذخیره شده در خازن چند درصد و چگونه تغییر می‌کند؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:43:46', 5, 'done'),
(7751, 'دو گوی سبک و رسانای A و B را به‌وسیله نخ سبکی از سقف آویزان می‌کنیم. اگر یک میله پلاستیکی با بار منفی را به گوی A نزدیک کنیم، آن را می‌رباید و اگر میله را به B نزدیک کنیم، آن را می‌راند. کدام گزینه در مورد این دو گوی درست است؟', 2, 2, 79, 342, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:43:37', 5, 'done'),
(7752, 'اگر تعداد $2 \\times 10^{14}$ الکترون به جسمی با بار $q$ بدهیم بزرگی بار جسم $1/5$ برابر مقدار اولیه شده و نوع بار آن عوض می‌شود. بار $q$ برحسب میکروکولن کدام است؟ ($e = 1/6 \\times 10^{-19} C$)', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:43:26', 5, 'done'),
(7753, 'چهار گلوله یکسان از جنس شیشه، سرب، آلومینیم و نقره در اختیار داریم. گلوله‌های شیشه‌ای و آلومینیمی را با پارچه ابریشمی مالش می‌دهیم و گلوله‌های سربی و نقره‌ای را با پارچه کتان مالش می‌دهیم. به‌طوری که اندازه بار تمام گوی‌ها یکسان شود. اگر این چهار گلوله را روی خط راست و در چهار نقطه که فاصله هر دو نقطه مجاور با یکدیگر یکسان است، ثابت کنیم، در کدام‌یک از گزینه‌های زیر برایند نیروهای الکتریکی وارد بر گوی آلومینیومی از طرف سه گوی دیگر بیشینه و به‌سمت راست است؟ (سری تریبوالکتریک: انتهای مثبت سری -> شیشه، سرب، ابریشم، آلومینیوم، پارچه کتان، نقره <- انتهای منفی سری)', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:43:14', 5, 'done'),
(7754, 'مطابق شکل زیر، سه بار الکتریکی نقطه‌ای $q_1$ ، $q_2$ و $q_3$ در سه نقطه روی خط راست قرار دارند و برایند نیروهای الکتریکی وارد بر هر کدام از این سه بار الکتریکی برابر صفر است. بار $q_2$ چند میکروکولن است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:43:01', 5, 'done'),
(7755, 'دو بار هم‌نام $q$ و $q\'$ در فاصله معینی از یکدیگر ثابت شده‌اند. اگر ۲۰ درصد از بار $q$ را برداریم و به بار $q\'$ اضافه کنیم و بارها را در همان مکان‌های قبلی ثابت کنیم، بزرگی نیرویی که دو بار به یکدیگر وارد می‌کنند، ۱۶ درصد کاهش می‌یابد، نسبت $\\frac{q\'}{q}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:42:50', 5, 'done'),
(7756, 'مطابق شکل، بار الکتریکی نقطه‌ای $q = -4\\mu C$ در میدان یکنواخت $E = 5 \\times 10^5 \\frac{N}{C}$ در مسیر ABCDE از A به‌سمت E جابه‌جا می‌شود. انرژی پتانسیل الکتریکی این بار طی این جابه‌جایی چند ژول و چگونه تغییر می‌کند؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:42:42', 5, 'done'),
(7757, 'در شکل زیر سه ذره باردار در رئوس مربعی ثابت شده‌اند. اگر بزرگی نیروی الکتریکی که دو بار $q$ و $-q$ به هم وارد می‌کنند، برابر F باشد، برایند نیروهای الکتریکی وارد بر بار $-3q$ چند برابر F است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:42:21', 5, 'done'),
(7758, 'مطابق شکل زیر، برایند نیروهای الکتریکی که دو ذره باردار $q_1$ و $q_2$ به بار $q_3$ وارد می‌کنند، برابر F است. $q_2$ چند میکروکولن است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:42:11', 5, 'done'),
(7759, 'نمودار تغییرات میدان الکتریکی حاصل از بار نقطه‌ای $q$ برحسب فاصله از آن مطابق شکل زیر است. به‌ترتیب از راست به چپ $r_1$ چند سانتی‌متر و اندازه بار $q$ چند میکروکولن است؟ ($k = 9 \\times 10^9 \\frac{N.m^2}{C^2}$)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 23:25:23', 5, 'done'),
(7760, 'در شکل روبه‌رو، پتانسیل الکتریکی نقطه A چند ولت است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:41:44', 5, 'done'),
(7761, 'میدان الکتریکی بین صفحه‌های یک خازن تخت با دی‌الکتریک شیشه برابر $2 \\times 10^4 \\frac{N}{C}$ است. اگر پس از جداکردن خازن از مولد، شیشه را از بین صفحه‌های خازن خارج کنیم، میدان الکتریکی بین صفحه‌ها $10^5 \\frac{N}{C}$ می‌شود. ثابت دی‌الکتریک شیشه چقدر است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:41:31', 5, 'done'),
(7762, 'فاراد (یکای ظرفیت خازن) معادل کدام‌یک از یکاهای زیر نیست؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:41:19', 5, 'done'),
(7763, ' خازنی را توسط یک باتری پر نموده و سپس از باتری جدا می کنیم. در این حالت می خواهیم با وارد کردن یک ماده عایق (دی الکتریک) بین صفحات خازن، انرژی ذخیره شده در آن را افزایش دهیم. کدام یک از دی الکتریک های زیر باعث افزایش بیشتر این انرژی می شود؟ (در هر حالت، کل ضخامت خازن را دی الکتریک پر می کند.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 23:29:05', 5, 'done'),
(7764, ' ثابت دی الکتریک یک یاخته عصبی (نورون) $6$، ضخامت سلولی آن $10 nm$ و مساحت سطح آن $100 \\mu m^2$ است. برای آن که اختلاف پتانسیل $200 mV$ در دو سر این نورون ایجاد شود، تعداد کل یون های لازم کدام است؟ (فرض کنید هر یون فقط یک بار یونیده می شود و $e = 1/6 \\times 10^{-19} C$ ، $\\varepsilon_0 = 9 \\times 10^{-12} \\frac{F}{m}$ است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:41:03', 5, 'done'),
(7765, ' در شکل زیر، اگر مساحت هر یک از صفحات خازن برابر $25 cm^2$ و انرژی ذخیره شده در آن $36 pJ$ باشد، پتانسیل الکتریکی نقطه $A$ چند ولت است؟ (در بین صفحات خازن هوا است و $\\varepsilon_0 = 9 \\times 10^{-12} \\frac{F}{m}$ می باشد.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:40:51', 5, 'done'),
(7766, ' شکل مقابل، جدول سری الکتریسیته مالشی (تریبو الکتریک) برای چند جسم رسانا را نشان می دهد. اگر جسم های خنثی $F$ و $C$ از این جدول را با جسم های دیگر مالش دهیم، پس از به دست آوردن بار الکتریکی، یکدیگر را دفع می کنند. در این حالت، جسم $C$ ممکن است با کدام یک از اجسام مالش داده شده باشد؟ انتهای مثبت سری A B C D E F انتهای منفی سری', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:40:42', 5, 'done'),
(7767, ' جسمی دارای بار منفی است. اگر به این جسم $5 \\times 10^{13}$ الکترون بدهیم، اندازه بار الکتریکی آن $3$ برابر می شود. بار اولیه جسم چند میکروکولن بوده است؟ ($e = 1/6 \\times 10^{-19} C$)', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:40:34', 5, 'done'),
(7768, ' مطابق شکل زیر، دو گوی $A$ و $B$ از دو ریسمان عایق آویزان و در حال تعادل اند. جرم گوی $A$ برابر $2m$ و جرم گوی $B$ برابر $m$ است. اگر $q_A = 3 \\mu C$ و $q_B = 1 \\mu C$ باشد، کدام گزینه در مورد اندازه نیروی الکتریکی وارد بر گوی ها و زاویه راستای هر نخ با راستای قائم درست است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:40:23', 5, 'done'),
(7769, ' در شکل زیر، نیروی خالص وارد بر هر یک از بارهای الکتریکی نقطه ای که روی یک خط واقع شده اند، صفر است. نسبت $\\frac{q_1}{q_2}$ کدام است؟', 2, 2, 79, 342, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:40:08', 5, 'done'),
(7770, ' در شکل مقابل، برآیند میدان های الکتریکی حاصل از دو بار الکتریکی نقطه ای $q_1$ و $q_2$ در رأس قائمه مثلث برابر $\\vec{E}$ است. $q_2$ چند میکروکولن است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:39:57', 5, 'done'),
(7771, ' نمودار میدان الکتریکی حاصل از بار نقطه ای $q$ بر حسب فاصله از آن مطابق شکل مقابل است. اندازه $r$ بر حسب سانتی متر و اندازه نیروی وارد بر بار $9 \\mu C$ که در فاصله $30 cm$ از بار $q$ قرار دارد، چند نیوتون است؟ ($k = 9 \\times 10^9 \\frac{N \\cdot m^2}{C^2}$)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:39:48', 5, 'done'),
(7772, ' مطابق شکل مقابل، ذره ای به جرم $10^{-8} g$ و بار الکتریکی $+10^{-15} C$ از نقطه $A$ درون میدان الکتریکی یکنواختی به بزرگی $1/2 \\times 10^5 \\frac{N}{C}$ و از حال سکون رها می شود و با تندی $0/4 \\frac{m}{s}$ به صفحه بالایی می رسد. فاصله نقطه $A$ از صفحه پایینی چند سانتی متر است؟ ($g = 10 \\frac{N}{kg}$ و از اتلاف انرژی صرف نظر کنید.)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:39:38', 5, 'done'),
(7773, ' میدان الکتریکی در فاصله $30$ سانتی متری از بار $q$ برابر $36 \\frac{N}{C}$ است. چند سانتی متر دیگر از بار فوق دور شویم تا میدان الکتریکی برابر $16 \\frac{N}{C}$ شود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:39:25', 5, 'done'),
(7774, ' دو کره رسانای باردار با بار $q_A = 3 \\mu C$ و $q_B = 54 \\mu C$، مطابق شکل زیر، ثابت اند. اگر کره $B$ را با کره رسانای مشابه خنثی تماس دهیم و آن را در جای قبلی خود قرار دهیم میدان در چند سانتی متری نقطه $A\'$ صفر می شود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:39:16', 5, 'done'),
(7775, ' پتانسیل نقطه $A$ برابر $-100 V$ و پتانسیل نقطه $B$ برابر $+100 V$ است. اگر بار $q = 4 \\mu C$ را از نقطه $A$ تا نقطه $B$ جابه جا کنیم، کار میدان الکتریکی در این جابه جایی چند ژول است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:38:52', 5, 'done'),
(7776, ' جسم $A$، جسم $B$ را دفع می کند و جسم $B$ نیز جسم $C$ را دفع می کند. اگر جسم $C$، جسم $D$ را جذب کند، چه تعداد از عبارت های زیر در مورد این اجسام درست است؟ (هر سه جسم روی پایه های عایق قرار دارند.) الف) بار جسم های $A$ و $B$ همنام است. ب) جسم $A$، جسم $D$ را جذب می کند. پ) جسم $B$، قطعاً باردار است. ت) جسم $D$، الزاماً جسم $B$ را دفع می کند.', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:38:33', 5, 'done'),
(7777, ' مطابق شکل زیر، کره رسانای $A$ نزدیک میله با بار مثبت قرار دارد. اگر کلید $K$ را بسته و سپس باز کنیم، کدام گزینه در مورد این مجموعه درست است؟', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:38:20', 5, 'done'),
(7778, ' مطابق شکل زیر، سه گوی فلزی باردار $A$، $B$ و $C$ در راستای قائم در حال تعادل اند. اگر جرم گوی $B$ برابر $60g$ باشد، جرم گوی $C$ چند گرم است؟ ($g = 10 \\frac{N}{kg}$ و از نیروی الکتریکی وارد بر $q_C$ از طرف $q_A$ صرف نظر کنید.)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:38:11', 5, 'done'),
(7779, 'در شکل زیر چهار بار الکتریکی نقطه‌ای در فاصله‌های مساوی از یکدیگر روی محیط دایره‌ای ثابت شده‌اند. اگر نیروی الکتریکی خالص وارد بر بار $q_4$ برابر صفر باشد، بار $q_2$ چند میکروکولن است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:37:56', 5, 'done'),
(7780, 'به بار الکتریکی $q_1 = +1\\text{C}$ در فاصله $r$ متری از بار $q_2 = 4\\mu\\text{C}$ نیروی $F$ وارد می‌شود. اندازه نیروی وارد بر بار $q_1$ در فاصله $2r$ متری از بار $q_3 = 16\\mu\\text{C}$، چند برابر $F$ است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:37:45', 5, 'done'),
(7781, 'چه تعداد از عبارات زیر نادرست است؟ الف) میدان الکتریکی خالص درون رساناها و نارساناها در حال تعادل صفر است. ب) پتانسیل الکتریکی در نقاط نوک تیز سطح جسم رسانای باردار از نقاط دیگر همواره بیشتر است. پ) شخصی که در داخل اتومبیل یا هواپیما است معمولاً از خطر آذرخش در امان است. ت) بار الکتریکی اضافی داده شده به یک رسانا فقط روی سطح خارجی آن توزیع می‌شود. ث) بنا به آزمایش فاراده، تراکم بار الکتریکی در نقاط نوک تیز سطح جسم رسانای باردار از نقاط دیگر بیشتر است.', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:37:30', 5, 'done'),
(7782, 'مطابق شکل زیر، بار $q = -50\\mu\\text{C}$ را در میدان الکتریکی یکنواخت $E = 6 \\times 10^5 \\frac{\\text{N}}{\\text{C}}$ ابتدا از A تا B و سپس از B تا C جابه‌جا می‌کنیم. بزرگی نیروی الکتریکی وارد بر بار $q$ و تغییر انرژی پتانسیل الکتریکی آن در مسیر A تا C به ترتیب از راست به چپ در SI کدام است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:37:18', 5, 'done'),
(7783, 'میدان الکتریکی یکنواختی در راستای محور y است. بار الکتریکی $q = -4\\mu\\text{C}$ روی خط راست در دستگاه مختصات از مکان $A(4\\text{cm}, 5\\text{cm})$ به مکان $B(4\\text{cm}, -10\\text{cm})$ و سپس به مکان $C(-16\\text{cm}, -10\\text{cm})$ جابه‌جا می‌شود و انرژی پتانسیل الکتریکی آن طی این جابه‌جایی $18$ میلی‌ژول افزایش می‌یابد. اندازه میدان الکتریکی برحسب یکای SI و جهت آن مطابق کدام گزینه است؟', 2, 2, 79, 345, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:37:05', 5, 'done'),
(7784, 'در یک نقطه از فضا بر بار $-2$ میکروکولن نیروی $\\vec{F} = (8\\hat{j} - 6\\hat{i}) \\times 10^{-4}$ در SI وارد می‌شود. میدان الکتریکی در این نقطه برحسب $\\frac{\\text{N}}{\\text{C}}$ کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:36:47', 5, 'done'),
(7785, 'نمودار انرژی ذخیره شده در دو خازن تخت مربع شکل A و B برحسب بار ذخیره شده در آن‌ها مطابق شکل زیر است. اگر ابعاد خازن A دو برابر ابعاد خازن B باشد، فاصله بین صفحات خازن A چند برابر فاصله بین صفحات خازن B است؟ (بین صفحات خازن‌ها هوا است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:36:38', 5, 'done'),
(7786, 'یک خازن تخت با دی‌الکتریک را پس از این‌که به‌طور کامل پر گردید، از مولد جدا نموده و سپس فاصله بین صفحات آن را دو برابر می‌کنیم. در این حالت، کدام‌یک از موارد زیر درست است؟ آ) اختلاف پتانسیل بین صفحات نصف می‌شود. ب) انرژی ذخیره شده در خازن نصف می‌شود. پ) میدان الکتریکی بین صفحات خازن ثابت می‌ماند. ت) بار الکتریکی خازن ثابت می‌ماند.', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:36:30', 5, 'done'),
(7787, 'نمودار بار الکتریکی ذخیره شده در یک خازن برحسب اختلاف پتانسیل بین دو صفحه آن مطابق شکل زیر است. اگر $3\\text{mC}$ بار از صفحه مثبت خازن جدا کرده و به صفحه منفی آن انتقال دهیم، انرژی خازن $4/5\\text{J}$ تغییر می‌کند. بار الکتریکی اولیه خازن چند میلی‌کولن بوده است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:36:17', 5, 'done'),
(7788, 'مطابق شکل زیر، یک یاخته عصبی (نورون) را با یک خازن تخت مدل‌سازی کرده‌ایم، به‌طوری‌که غشای سلول نقش دی‌الکتریک را داشته باشد. اگر ثابت دی‌الکتریک غشای سلول برابر $\\kappa = 4$، ضخامت غشا برابر $10\\text{nm}$ و مساحت غشا را $10^{-10}\\text{m}^2$ در نظر بگیریم، بار روی صفحات خازن، برای آن‌که یک اختلاف پتانسیل $100\\text{mV}$ ایجاد شود، چند پیکوکولن است؟ $(\\varepsilon_0 = 9 \\times 10^{-12} \\frac{\\text{F}}{\\text{m}})$', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:36:07', 5, 'done'),
(7789, 'اگر اختلاف پتانسیل دو سر خازن تختی را $1\\text{V}$ کاهش دهیم، بار ذخیره شده در آن $8\\mu\\text{C}$ کاهش می‌یابد. اگر به دو سر این خازن اختلاف پتانسیل $10\\text{V}$ اعمال کنیم، انرژی ذخیره شده در آن چند میکروژول می‌شود؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:35:58', 5, 'done'),
(7790, 'برای دو خازن A و B، هنگامی‌که بار ذخیره شده هر کدام $24\\mu\\text{C}$ است، اختلاف پتانسیل دو سر خازن B، $4$ ولت بیشتر از اختلاف پتانسیل دو سر خازن A می‌باشد. همچنین، هنگامی‌که اختلاف پتانسیل دو سر هر خازن $5$ ولت است، انرژی ذخیره شده در خازن B، $37/5\\mu\\text{J}$ کمتر از انرژی خازن A می‌باشد. در صورتی‌که فاصله صفحات خازن A را دو برابر و مساحت صفحاتش را چهار برابر کنیم، ظرفیت جدید خازن A چند میکروفاراد می‌شود؟ (بین صفحات هر دو خازن هوا وجود دارد.)', 2, 2, 79, 348, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:35:49', 5, 'done'),
(7791, 'صفحات خازنی تخت با دی‌الکتریک هوا به باتری با ولتاژ ثابت متصل بوده و انرژی ذخیره شده در آن برابر U است. ابتدا فاصله دو صفحه خازن را $\\frac{5}{6}$ برابر می‌کنیم، سپس آن را از باتری جدا کرده و دوباره فاصله صفحه‌ها را به حالت اول برگردانده و فضای بین صفحات را با عایقی با ثابت دی‌الکتریک $\\kappa$ پر می‌کنیم. اگر در این حالت انرژی خازن نسبت به حالت اول (U) $68$ درصد کاهش یابد، $\\kappa$ کدام است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:35:38', 5, 'done'),
(7792, 'در شکل زیر سه بار الکتریکی نقطه‌ای در مکان‌های خود روی یک خط ثابت شده‌اند. بزرگی برآیند نیروهای الکتریکی وارد بر بار $q_3$ هم‌اندازۀ نیروی الکتریکی است که بار $q_1$ بر بار $q_3$ وارد می‌کند. در این‌صورت بار $q_2$ چند میکروکولن است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:35:28', 5, 'done'),
(7793, 'در یک میدان الکتریکی، بار $q = +5\\mu\\text{C}$ را از نقطۀ A با پتانسیل $-18\\text{V}$ رها می‌کنیم و به نقطۀ B می‌رود. اگر در این جابه‌جایی انرژی پتانسیل الکتریکی ذره، $180\\mu\\text{J}$ تغییر کند، پتانسیل الکتریکی نقطۀ B چند ولت است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:35:18', 5, 'done'),
(7794, 'مطابق شکل، سه بار الکتریکی بر روی محیط دایره‌ای قرار گرفته‌اند و بزرگی میدان الکتریکی خالص حاصل از این سه بار در نقطۀ A برابر $E_1$ است. اگر فقط علامت بار $q_2$ عوض شود، آن‌گاه بزرگی میدان الکتریکی خالص در نقطۀ A برابر $E_2$ می‌شود. $\\frac{E_2}{E_1}$ کدام است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:35:07', 5, 'done'),
(7795, 'فاصلۀ صفحات یک خازن تخت به ظرفیت $10$ میکروفاراد برابر یک میلی‌متر است. این خازن را به‌وسیلۀ یک مولد $100$ ولتی شارژ کرده و سپس از مولد جدا می‌کنیم. اگر فاصلۀ میان صفحات را $0/2$ میلی‌متر افزایش دهیم، انرژی الکتریکی ذخیره‌شده در خازن چند ژول تغییر می‌کند؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:32:50', 5, 'done'),
(7796, 'دو بار الکتریکی نقطه‌ای $q_1 = 25\\mu\\text{C}$ و $q_2 > 0$ به ترتیب در نقاط $(4\\text{cm}, 3\\text{cm})$ و $(-6\\text{cm}, 8\\text{cm})$ قرار دارند. برایند نیروهای وارد بر بار $q_3 = 1\\mu\\text{C}$ که در مبدأ مختصات قرار دارد، $150\\text{N}$ است. اندازۀ بار $q_2$ چند میکروکولن است؟ $(\\cos 37^\\circ = 0/8 , k = 9 \\times 10^9 \\frac{\\text{N}\\cdot\\text{m}^2}{\\text{C}^2})$', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:32:39', 5, 'done'),
(7797, 'ذره‌ای با بار الکتریکی $4\\mu\\text{C}$ و جرم $0/5$ میلی‌گرم در یک میدان الکتریکی یکنواخت از حال سکون رها می‌شود و تندی آن پس از طی مسافت $20$ سانتی‌متر $50 \\frac{\\text{m}}{\\text{s}}$ می‌شود. اگر در جهت خطوط این میدان الکتریکی به اندازۀ $80$ سانتی‌متر جابه‌جا شویم، پتانسیل الکتریکی چند ولت کاهش می‌یابد؟ (از نیروی وزن وارد بر ذره صرف نظر کنید.)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:32:28', 5, 'done'),
(7798, 'خازن تختی به اختلاف پتانسیل ثابتی متصل است و انرژی ذخیره‌شده در آن در این حالت برابر $U$ است. اگر همزمان ابعاد صفحات خازن را $50$ درصد افزایش دهیم و فاصلۀ بین صفحات خازن را $64$ درصد کاهش دهیم، اختلاف پتانسیل بین صفحات خازن را چند درصد تغییر دهیم تا انرژی ذخیره‌شده در خازن تغییر نکند؟ (در هر دو حالت بین صفحات خازن، هوا است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:32:17', 5, 'done'),
(7799, 'در شکل زیر، بار هریک از گلوله‌های نارسانا برابر $3\\mu\\text{C}$ و جرم هریک $50\\text{g}$ است. اگر گلولۀ B را از فاصلۀ $90$ سانتی‌متری گلولۀ A رها کنیم، شتاب آن در لحظۀ رها شدن چند متر بر مربع ثانیه و جهت این شتاب به کدام سمت است؟ (اصطکاک گلوله با دیوارۀ ظرف ناچیز و $k = 9 \\times 10^9 \\frac{\\text{N}\\cdot\\text{m}^2}{\\text{C}^2}$ و $g = 10 \\frac{\\text{N}}{\\text{kg}}$ است.)', 2, 2, 79, 343, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:32:09', 5, 'done'),
(7800, 'سه بار نقطه‌ای $q_1$، $q_2$ و $q_3$ در سه رأس یک مربع ثابت شده‌اند و میدان الکتریکی برایند ناشی از سه بار در رأس چهارم مربع مشخص شده است. اگر بزرگی میدان برایند برابر با $2/6 \\times 10^6$ نیوتون بر کولن باشد، بزرگی نیروی الکتریکی که بارهای $q_2$ و $q_3$ به‌هم وارد می‌کنند، چند نیوتون است؟ $(\\sqrt{2} = 1/4 , k = 9 \\times 10^9 \\frac{\\text{N}\\cdot\\text{m}^2}{\\text{C}^2} , q_1 = -0/4\\mu\\text{C})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:31:52', 5, 'done'),
(7801, 'اگر بار الکتریکی یک خازن را $20$ درصد افزایش و ظرفیت آن را $25$ درصد کاهش دهیم، اختلاف پتانسیل دو سر خازن چگونه تغییر می‌کند؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:31:38', 5, 'done'),
(7802, 'دو کرۀ مشابه فلزی دارای بار هم‌نام $q_1$ و $q_2$ ($q_1 > q_2$) در فاصلۀ مشخص از یکدیگر قرار دارند. دو کره را با هم تماس می‌دهیم و فاصلۀ آن‌ها را نصف می‌کنیم. اگر نیروی الکتریکی که دو کره به یکدیگر در حالت جدید وارد می‌کنند $6$ برابر حالت قبل باشد، حاصل $\\frac{q_1}{q_2}$ کدام است؟', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:31:29', 5, 'done'),
(7803, 'دو بار الکتریکی $q_1 = -4\\mu\\text{C}$ و $q_2 = 3\\mu\\text{C}$ به ترتیب در نقاط $(10\\text{cm}, 0)$ و $(0, -10\\text{cm})$ در صفحۀ مختصات xy قرار گرفته‌اند و میدان الکتریکی برایند $\\vec{E}$ در مبدأ مختصات ایجاد کرده‌اند. مقدار $q_1$ چند درصد باید تغییر کند تا بردار برایند $\\vec{E}$ را به اندازۀ $16^\\circ$ و به صورت ساعتگرد بچرخاند؟ $(\\sin 37^\\circ = 0/6)$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:31:16', 5, 'done'),
(7804, 'اختلاف پتانسیل دو سر خازن شارژ شده‌ای به ظرفیت $1/5$ میکروفاراد که از مولد جدا شده است، برابر $8$ ولت است. اگر از صفحۀ مثبت خازن تعداد $5 \\times 10^{13}$ الکترون به صفحۀ منفی خازن منتقل کنیم، فاصلۀ بین صفحات خازن را چند برابر نماییم تا انرژی ذخیره‌شده در خازن تغییر نکند؟ $(e = 1/6 \\times 10^{-19}\\text{C}$ و فاصلۀ بین صفحات خازن هوا است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:27:10', 1, '2026-03-27 21:31:04', 5, 'done'),
(7805, 'دو ذره با بار الکتریکی مشابه $+q$ در فاصله $r$ از یکدیگر، نیروی الکتریکی به بزرگی $0/144N$ بر هم وارد می کنند. اگر بخواهیم اندازه نیروی بین آنها به مقدار معینی افزایش یابد، یا باید بار $1\\mu C$ به بار هر یک از دو ذره بیفزاییم یا آنکه فاصله آنها را $20cm$ کاهش دهیم. $(k=9\\times 10^{9}\\frac{N\\cdot m^{2}}{C^{2}})$ فاصله $r$ بر حسب متر کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:27:20', 5, 'done'),
(7806, 'سه بار الکتریکی نقطه ای $q_{1}=+2\\mu C$ ، $q_{2}=+8\\mu C$ و $q_{3}$، مطابق شکل در سه گوشه یک مثلث قائم الزاویه قرار دارند. اگر بزرگی نیرویی که دو بار الکتریکی $q_{1}$ و $q_{2}$ بر هم وارد می کنند با بزرگی نیرویی که دو بار الکتریکی $q_{2}$ و $q_{3}$ بر هم وارد می کنند، برابر باشد، بار الکتریکی $q_{3}$ به اندازه چند میکروکولن از بار الکتریکی $q_{1}$ بیشتر است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:27:10', 5, 'done'),
(7807, 'مطابق شکل، سه بار الکتریکی نقطه ای $q_{1}=+1\\mu C$ ، $q_{2}=+1\\mu C$ و $q_{3}$ در سه رأس مربعی به ضلع $1m$ واقع اند. اگر میدان الکتریکی خالص آنها در رأس $A$ برابر صفر باشد، بزرگی نیروی الکتریکی خالص وارد بر بار $q_{3}$ چند میلی نیوتون است؟ $(k=9\\times 10^{9}\\frac{N\\cdot m^{2}}{C^{2}})$', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:26:58', 5, 'done'),
(7808, ' دو بار الکتریکی نقطه‌ای $q_{1}=+q$ و $q_{2}=-2q$ مطابق شکل در فاصله $d$ از هم قرار دارند و بزرگی میدان الکتریکی خالص آن‌ها در نقطه $A$ وسط فاصله دو بار، برابر $108\\frac{N}{C}$ است. اگر $AB=\\frac{d}{4}$ باشد، میدان الکتریکی خالص حاصل از این دو بار در نقطه $B$ چند نیوتون بر کولن است؟ $(k=9\\times 10^{9}\\frac{N\\cdot m^{2}}{C^{2}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:26:47', 5, 'done'),
(7809, ' در شکل داده‌شده، در فضایی که نقاط $A$، $B$ و $C$ وجود دارند، میدان الکتریکی یکنواخت برقرار است. هنگامی که بار الکتریکی $q$ را از نقطه $A$ تا نقطه $B$ جابه‌جا می‌کنیم، انرژی پتانسیل الکتریکی آن تغییر نمی‌کند، اما هنگامی که آن را از نقطه $B$ تا نقطه $C$ جابه‌جا می‌کنیم، انرژی پتانسیل الکتریکی آن افزایش می‌یابد. نوع بار $q$ و جهت میدان الکتریکی یکنواخت، مطابق کدام گزینه می‌تواند باشد؟', 2, 2, 79, 345, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:26:20', 5, 'done'),
(7810, ' در یک میدان الکتریکی یکنواخت، ذره‌ای با بار الکتریکی $q$ را از نقطه $A$ و از حال سکون رها می‌کنیم؛ به‌طوری که وقتی به نقطه $B$ می‌رسد، انرژی جنبشی آن $4mJ$ است. اگر تنها نیروی مؤثر بر ذره، نیروی الکتریکی باشد و پتانسیل الکتریکی نقاط $A$ و $B$ به‌ترتیب $-100V$ و $+100V$ باشد، بار الکتریکی $q$ چند میکروکولن است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:26:00', 5, 'done'),
(7811, ' یک بار الکتریکی منفی را از نقطه $A$ تا نقطه $B$ درون یک میدان الکتریکی مطابق شکل، جابه‌جا می‌کنیم. کدام گزینه در مورد کار نیروی میدان الکتریکی در این جابه‌جایی و مقایسه پتانسیل الکتریکی نقاط $A$ و $B$ درست است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:25:45', 5, 'done'),
(7812, ' فاصله صفحه‌های یک خازن تخت با ظرفیت $C=36nF$، برابر $0/2mm$ است و بین آن‌ها عایقی با ثابت دی‌الکتریک $\\kappa=5$ قرار دارد. اگر صفحه‌های خازن مربع شکل باشند، طول ضلع هر صفحه چند سانتی‌متر است؟ $(\\varepsilon_{0}=9\\times 10^{-12} \\frac{F}{m})$', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:25:33', 5, 'done'),
(7813, ' یک خازن باردار با ظرفیت $C=20\\mu F$ در مدت $50ms$ در یک مدار تخلیه می‌شود. اگر توان متوسط تخلیه خازن در این مدت $20kW$ باشد، اندازه بار اولیه هر صفحه آن چند میلی‌کولن بوده است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:25:23', 5, 'done'),
(7814, ' خازن تختی را که بین دو صفحه‌ آن هوا وجود دارد، توسط یک باتری با ولتاژ $8V$ پر می‌کنیم و سپس خازن را از باتری جدا نموده و فاصله صفحه‌های آن را $1/5$ برابر می‌کنیم و یک عایق با ثابت دی‌الکتریک $\\kappa=3$ در بین صفحه‌های آن قرار می‌دهیم. در این حالت، انرژی خازن برابر $U=48\\mu J$ است. بار الکتریکی خازن چند میکروکولن است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:25:13', 5, 'done'),
(7815, ' با توجه به جدول سری الکتریسیته مالشی (تریبوالکتریک) داده‌شده، یک پارچه کتان خنثی را با یک میله شیشه‌ای خنثی مالش داده‌ایم؛ به‌طوری که بین آن‌ها $5 \\times 10^{11}$ الکترون مبادله می‌شود. بار الکتریکی پارچه کتان برحسب نانوکولن کدام است؟ $(e = 1/6 \\times 10^{-19} C)$', 2, 2, 79, 342, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:25:03', 5, 'done'),
(7816, ' در شکل داده‌شده، سه بار الکتریکی نقطه‌ای مثبت روی یک خط راست ثابت شده‌اند. در این حالت، بزرگی نیروی الکتریکی خالص وارد بر بار $q_{2}$، برابر $F$ است. اگر $1\\mu C$ از بار $q_{1}$ برداشته و آن را به بار $q_{2}$ بیفزاییم، بزرگی نیروی الکتریکی خالص وارد بر بار $q_{2}$ همان $F$ باقی می‌ماند، ولی جهت آن تغییر می‌کند. بار $q_{3}$ چند میکروکولن است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:24:52', 5, 'done'),
(7817, ' دو بار الکتریکی نقطه‌ای هم‌اندازه و ناهمنام، مانند شکل در دو گوشه یک مثلث قائم‌الزاویه متساوی‌الساقین ثابت شده‌اند و بزرگی میدان الکتریکی خالص آن‌ها در رأس $A$ برابر با $1000 \\frac{N}{C}$ است. بزرگی میدان الکتریکی خالص این دو بار در نقطه $M$ (وسط خط واصل دو بار) چند نیوتون بر کولن است؟ $(k = 9 \\times 10^{9} \\frac{N\\cdot m^{2}}{C^{2}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:24:38', 5, 'done'),
(7818, ' چهار بار الکتریکی نقطه‌ای هم‌اندازه، مطابق شکل در نقاط $A$، $B$، $C$ و $D$ ثابت شده‌اند. اگر $CM = MD = 1m$ و $AM = BM = d$ باشند و میدان الکتریکی خالص بارها در نقطه $M$ برابر با $\\vec{E} = (+36)\\hat{i} + (+9)\\hat{j} (\\frac{N}{C})$ باشد، بزرگی نیروی الکتریکی بین دو بار واقع در دو نقطه $A$ و $B$، چند نانونیوتون است؟ $(k = 9 \\times 10^{9} \\frac{N\\cdot m^{2}}{C^{2}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:24:27', 5, 'done'),
(7819, ' چه تعداد از موارد زیر، در مورد خطوط میدان الکتریکی درست است؟\n\nالف) در هر نقطه از فضا که تراکم خطوط میدان الکتریکی بیشتر باشد، میدان در آن نقطه قوی‌تر است.\n\nب) خطوط میدان الکتریکی هرگز یکدیگر را قطع نمی‌کنند.\n\nپ) خطوط میدان الکتریکی از بار الکتریکی مثبت خارج و به بار الکتریکی منفی وارد می‌شوند.\n\nت) بردار میدان الکتریکی در هر نقطه از فضا بر خط میدانی که از آن نقطه می‌گذرد، مماس است.', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:24:15', 5, 'done'),
(7820, ' در یک میدان الکتریکی یکنواخت مطابق شکل (جهت خطوط میدان رسم نشده است)، الکترونی را از نقطه $A$ و با تندی $4 \\times 10^{6} \\frac{m}{s}$ در راستای خطوط میدان به طرف چپ پرتاب می‌کنیم. اگر تندی الکترون در نقطه $B$ به صفر برسد، اختلاف پتانسیل الکتریکی نقاط $A$ و $B$ به‌صورت $V_{B} - V_{A}$ چند ولت است؟ $(e = 1/6 \\times 10^{-19} C$ و $m_{e} = 9 \\times 10^{-31} kg$ و تنها نیروی مؤثر بر الکترون، نیروی الکتریکی است.$)$', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:24:03', 5, 'done'),
(7821, ' در شکل داده‌شده، خازن تخت شارژشده‌ای را از باتری جدا کرده و فاصله دو صفحه خازن را کم می‌کنیم. بزرگی میدان الکتریکی بین صفحه‌ها و اندازه اختلاف پتانسیل الکتریکی دو نقطه $A$ و $B$ به‌ترتیب چگونه تغییر می‌کند؟ (فاصله دو نقطه $A$ و $B$ برابر $d_{1}$ و همواره کمتر از فاصله دو صفحه خازن است.)', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:23:33', 5, 'done'),
(7822, ' ظرفیت یک خازن تخت که بین دو صفحه آن هوا وجود دارد، $C = 50 nF$ است و روی یک صفحه آن بار $Q = -8 \\mu C$ وجود دارد. یک الکترون از فاصله بسیار نزدیک به صفحه منفی خازن رها می‌شود. انرژی پتانسیل الکتریکی الکترون از لحظه رها شدن تا لحظه‌ای که به صفحه مثبت خازن می‌رسد، چند ژول و چگونه تغییر می‌کند؟ $(e = 1/6 \\times 10^{-19} C)$', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:23:24', 5, 'done'),
(7823, ' مشخصات چهار خازن تخت که فضای بین دو صفحه آن‌ها را هوا پر کرده است، در جدول زیر آمده است. با توجه به نمودار بار برحسب اختلاف پتانسیل که برای این چهار خازن رسم شده است، خط $d$ مربوط به کدام خازن است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:23:11', 5, 'done'),
(7824, ' دو بار الکتریکی نقطه‌ای $q_{1}$ و $q_{2}$ مطابق شکل روی محور $x$ قرار دارند. میدان الکتریکی خالص این دو بار در نقطه‌های $A$ و $B$ به ترتیب $(9000 \\frac{N}{C})\\vec{i}$ و صفر است. بار $q_{1}$ چند نانوکولن است؟ $(k=9\\times 10^{9} \\frac{N\\cdot m^{2}}{C^{2}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:22:59', 5, 'done'),
(7825, ' یک ذره به جرم $m=0/5g$ و بار الکتریکی $q=-2\\mu C$ را مانند شکل با تندی $v=1000 \\frac{m}{s}$ از نقطه $A$ درون میدان الکتریکی یکنواخت به بزرگی $E=5\\times 10^{6} \\frac{N}{C}$ پرتاب می‌کنیم. هنگامی که ذره به نقطه $B$ می‌رسد، تندی آن به اندازه $10$ درصد تغییر می‌کند. فاصله نقطه $A$ تا نقطه $B$ چند سانتی‌متر است؟ (از نیروی وزن ذره چشم‌پوشی کنید.)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:22:44', 5, 'done'),
(7826, ' ظرفیت یک خازن $6pF$ است. اگر اختلاف پتانسیل دو سر این خازن $150$ ولت افزایش یابد، بار الکتریکی ذخیره‌شده در خازن چند نانوکولن تغییر می‌کند؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:22:32', 5, 'done'),
(7827, ' در شکل روبه‌رو، سه بار نقطه‌ای $q_{1}$، $q_{2}$ و $q_{3}$ روی یک خط راست قرار دارند و برآیند نیروهای الکتریکی وارد بر هریک از آن‌ها برابر با صفر است. نسبت $\\frac{q_{2}}{q_{1}}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:22:19', 5, 'done'),
(7828, ' در شکل داده‌شده، دو بار الکتریکی هم‌اندازه و مثبت بر یکدیگر نیرویی با بزرگی $0/009N$ وارد می‌کنند. بزرگی میدان الکتریکی خالص آن‌ها در نقطه $A$ (روی خط واصل دو بار) چند نیوتون بر کولن است؟ $(k = 9 \\times 10^{9} \\frac{N\\cdot m^{2}}{C^{2}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:22:08', 5, 'done'),
(7829, ' یک ذره باردار به جرم $m=0/02\\text{ g}$ و بار $q=-5\\mu\\text{C}$ را مطابق شکل از نقطه A درون میدان الکتریکی یکنواخت $E=2500\\frac{\\text{N}}{\\text{C}}$ ، از حال سکون رها می کنیم تا تحت تأثیر میدان الکتریکی حرکت کند. اگر تندی بار در نقطه B به $50\\frac{\\text{m}}{\\text{s}}$ برسد، اختلاف پتانسیل الکتریکی بین نقاط A و B به صورت $V_B-V_A$ و فاصلۀ A تا B کدام است؟ (از وزن ذره صرف‌نظر کنید.)', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:21:57', 5, 'done'),
(7830, ' بر اثر مالش یک جسم نایلونی خنثی با یک پارچۀ کتان خنثی، بین آن‌ها $4 \\times 10^{13}$ الکترون مبادله شده است. با توجه به جدول سری الکتریسیته مالشی (تریبوالکتریک)، بار پارچۀ کتان چند میکروکولن خواهد بود؟ $(e=1/6 \\times 10^{-19}\\text{C})$\n\n\n\nانتهای مثبت سری\n\nشیشه\n\nنایلون\n\nابریشم\n\nپارچۀ کتان\n\nانتهای منفی سری', 2, 2, 79, 342, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:20:15', 5, 'done'),
(7831, ' دو کرۀ فلزی کوچک و یکسان A و B را که با بارهای $q_A=5\\mu\\text{C}$ و $q_B=25\\mu\\text{C}$ روی پایه‌های عایقی در فاصلۀ r از یکدیگر قرار دارند، با یک سیم رسانای نازک به هم وصل می‌کنیم و سپس سیم را از آن‌ها جدا می‌کنیم. بزرگی نیروی الکتریکی که دو کره در این حالت به یکدیگر وارد می‌کنند، چند برابر نیروی حالت قبل است؟', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:20:04', 5, 'done'),
(7832, ' سه ذرۀ باردار مطابق شکل، در کنار هم قرار دارند. اندازۀ برایند نیروهای الکتریکی وارد بر ذرۀ $q_1$ چند نیوتون است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:19:44', 5, 'done'),
(7833, ' در شکل روبه‌رو، برایند نیروهای الکتریکی وارد بر هریک از بارهای نقطه‌ای صفر است. بار $q_2$ چند میکروکولن است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:19:18', 5, 'done'),
(7834, ' در شکل روبه‌رو، بار الکتریکی سه گلوله یکسان بوده و گلوله به جرم $m_3$ را ثابت نگه داشته‌ایم. اگر گلوله‌های $m_1$ و $m_2$ درون لولۀ قائم، معلق و در تعادل باشند، نسبت $\\frac{m_2}{m_1}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:19:06', 5, 'done'),
(7835, ' مطابق شکل، شش بار الکتریکی نقطه‌ای روی دایره‌ای به شعاع $r$ ثابت شده‌اند. اگر بزرگی میدان الکتریکی حاصل از بار $+q$ در نقطۀ O (مرکز دایره) برابر $E$ باشد، میدان الکتریکی خالص در این نقطه کدام خواهد بود؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:18:48', 5, 'done'),
(7836, ' مطابق شکل، دو بار الکتریکی نقطه‌ای $q_1=4\\mu\\text{C}$ و $q_2=-4\\mu\\text{C}$ در فاصلۀ 4 متری از یکدیگر ثابت شده‌اند. بزرگی میدان الکتریکی خالص در نقطۀ A، چند برابر بزرگی میدان الکتریکی خالص در نقطۀ B است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:18:37', 5, 'done'),
(7837, ' کره‌ای کوچک به جرم $m$ و بار $-8\\text{nC}$ در یک میدان الکتریکی یکنواخت به بزرگی $2\\times 10^6 \\frac{\\text{N}}{\\text{C}}$ که راستای آن عمود بر سطح زمین است، معلق می‌ماند. جرم کره چند گرم و جهت میدان الکتریکی کدام است؟ $(g=10\\frac{\\text{N}}{\\text{kg}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:18:23', 5, 'done'),
(7838, ' اگر در شکل روبه‌رو، پتانسیل الکتریکی نقطۀ M درون میدان یکنواخت $\\vec{E}$ برابر صفر باشد، کدام گزینه درست است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:18:10', 5, 'done'),
(7839, ' ذرۀ بارداری به جرم $m=0/01\\text{ g}$ و بار $q=-1\\text{ nC}$ در میدان الکتریکی یکنواخت $E=5\\times 10^5 \\frac{\\text{N}}{\\text{C}}$ از حال سکون رها می‌شود. در این صورت، تندی ذره پس از پیمودن چه مسافتی و در کدام جهت به $10\\frac{\\text{m}}{\\text{s}}$ می‌رسد؟ (از اثر نیروی وزن چشم‌پوشی کنید.)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:17:55', 5, 'done'),
(7840, ' بار الکتریکی $q=-3\\mu\\text{C}$ را مطابق شکل درون میدان الکتریکی یکنواختی به‌بزرگی $4\\times 10^4 \\frac{\\text{N}}{\\text{C}}$ در مسیر نشان داده‌شده از A به D جابه‌جا می‌کنیم. تغییر انرژی پتانسیل الکتریکی بار در این جابه‌جایی چند میلی‌ژول است؟', 2, 2, 79, 345, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:17:37', 5, 'done'),
(7841, ' ظرف خنثی و رسانایی با درپوش فلزی روی پایۀ عایقی قرار دارد و روی درپوش آن دستۀ عایقی نصب شده است. یک مکعب فلزی با بار $+Q$ را مطابق شکل درون ظرف قرار می‌دهیم. اگر بار مکعب قبل از بستن درپوش $Q_1$ و پس از بستن درپوش $Q_2$ باشد، کدام گزینه درست است؟', 2, 2, 79, 347, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:17:24', 5, 'done'),
(7842, ' ظرفیت یک خازن تخت با ثابت دی‌الکتریک $k=5$ برابر با $10\\mu\\text{F}$ است. دی‌الکتریک را از بین صفحات برمی‌داریم و فاصلۀ صفحات را $3\\text{mm}$ تغییر می‌دهیم؛ به‌طوری که ظرفیت خازن $8\\mu\\text{F}$ بشود. فاصلۀ بین صفحات خازن در ابتدا چند میلی‌متر بوده است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:16:59', 5, 'done'),
(7843, ' انرژی یک خازن تخت باردار $4/5\\mu\\text{J}$ و میدان الکتریکی بین صفحه‌های آن $5 \\times 10^5 \\frac{\\text{V}}{\\text{m}}$ است. چنانچه مساحت هریک از صفحه‌های آن $40\\text{cm}^2$ باشد، فاصلۀ صفحه‌ها از یکدیگر چند میلی‌متر است؟ $(\\kappa = 1, \\epsilon_0 = 9 \\times 10^{-12} \\frac{\\text{C}^2}{\\text{N}\\cdot\\text{m}^2})$', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:16:48', 5, 'done'),
(7844, ' بار جسم $A$، برابر با $+24\\text{nC}$ و جسم $B$ خنثی است. از جسم $A$، $-16\\text{nC}$ بار الکتریکی به جسم $B$ منتقل می‌کنیم. در این‌صورت، کدام گزینه نادرست است؟ $(e = 1/6 \\times 10^{-19}\\text{C})$', 2, 2, 79, 342, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:16:36', 5, 'done'),
(7845, ' دو گوی رسانای کوچک و یکسان با بارهای $q_1 = -2\\text{nC}$ و $q_2 = 8\\text{nC}$ در فاصلۀ $r$ از یکدیگر قرار دارند و بر یکدیگر نیروی الکتریکی به‌بزرگی $F$ وارد می‌کنند. گوی‌ها را با هم تماس داده و در فاصلۀ $r\'$ از هم قرار می‌دهیم. اگر بزرگی نیروی الکتریکی بین آن‌ها همان $F$ باشد، نسبت $\\frac{r\'}{r}$ کدام است؟', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:15:46', 5, 'done'),
(7846, ' مطابق شکل، سه بار الکتریکی نقطه‌ای $q_1 = 4\\text{nC}$، $q_2 = 2\\text{nC}$ و $q_3 = 5\\text{nC}$ در سه رأس یک مثلث قائم‌الزاویۀ متساوی‌الساقین به طول ضلع $10\\text{cm}$ قرار دارند. نیروی الکتریکی خالص وارد بر بار $q_2$ برحسب بردارهای یکۀ $\\vec{i}$ و $\\vec{j}$ در SI کدام است؟ $(k = 9 \\times 10^9 \\frac{\\text{N}\\cdot\\text{m}^2}{\\text{C}^2})$', 2, 2, 79, 343, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:15:35', 5, 'done'),
(7847, ' دو شمع، یکی در فاصلۀ نزدیک و دیگری در فاصلۀ دور از کلاهک یک مولد وان‌دوگراف که دارای بار الکتریکی منفی است، قرار دارند. چه اتفاقی برای شعلۀ شمع‌ها می‌افتد؟', 2, 2, 79, 344, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:15:19', 5, 'done'),
(7848, ' نمودار اندازۀ میدان الکتریکی حاصل از یک ذرۀ باردار برحسب فاصله از ذره، به‌صورت شکل زیر است. $r_1$ چند سانتی‌متر است؟', 2, 2, 79, 344, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:15:02', 5, 'done'),
(7849, ' روی سطح بادکنکی به‌جرم $10\\text{g}$، بار الکتریکی $-200\\text{nC}$ را ایجاد می‌کنیم و بادکنک را در میدان الکتریکی $E = 6 \\times 10^5 \\frac{\\text{N}}{\\text{C}}$ که جهت آن به‌سمت پایین است قرار می‌دهیم. برایند نیروهای وارد بر آن چه مقدار و به کدام سمت است؟ $(g = 10 \\frac{\\text{N}}{\\text{kg}})$', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:14:50', 5, 'done');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(7850, ' یک گلولۀ کوچک به جرم $8\\text{g}$ و بار $-50\\text{nC}$ درون یک میدان الکتریکی یکنواخت پرتاب می‌شود. اگر تندی گلوله در نقطۀ $\\text{A}$ برابر $10 \\frac{\\text{m}}{\\text{s}}$ و اختلاف تندی آن در نقاط $\\text{A}$ و $\\text{B}$ برابر $2 \\frac{\\text{m}}{\\text{s}}$ باشد، بزرگی میدان الکتریکی چند نیوتون بر کولن است؟ (تنها نیروی مؤثر بر گلوله در طول مسیر را نیروی میدان الکتریکی در نظر بگیرید.)', 2, 2, 79, 344, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:14:39', 5, 'done'),
(7851, ' در میدان الکتریکی یکنواخت شکل زیر، بار الکتریکی $q = -2\\mu\\text{C}$ را از نقطۀ (1) تا نقطۀ (2) جابه‌جا می‌کنیم. اگر کار نیروی الکتریکی وارد بر بار در این جابه‌جایی $3 \\times 10^{-6}\\text{J}$ باشد، اختلاف پتانسیل الکتریکی دو نقطه $(V_1 - V_2)$ چند ولت و جهت میدان الکتریکی کدام است؟', 2, 2, 79, 346, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:14:13', 5, 'done'),
(7852, ' خازن تختی به یک باتری متصل بوده و $190\\text{nC}$ بار در خازن ذخیره شده است. اگر فاصلۀ بین دو صفحۀ خازن 5 درصد کاهش یابد، بار خازن چند نانوکولن اضافه می‌شود؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:14:01', 5, 'done'),
(7853, ' نمودار بار ذخیره‌شده بر روی صفحۀ یک خازن تخت در هنگام پرشدن توسط یک باتری به‌صورت زیر است. ظرفیت خازن و انرژی ذخیره‌شده در خازن تحت اختلاف‌پتانسیل $12\\text{V}$ به‌ترتیب از راست به چپ کدام است؟', 2, 2, 79, 348, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:00', 1, '2026-03-27 21:12:40', 5, 'done'),
(7854, ' در مدار داده‌شده، توان خروجی باتری به ازای دو مقدار مقاومت رئوستای $R_1 = ۱ \\Omega$ و $R_2 = ۷ \\Omega$ یکسان است. اگر مقاومت رئوستا را روی $۶ \\Omega$ تنظیم کنیم، توان خروجی باتری چند وات می‌شود؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:12:28', 5, 'done'),
(7855, ' کدام‌یک از عبارت‌های زیر درباره رسانایی الکتریکی مواد درست است؟ الف) در دمای معمولی (مثلاً $۲۰^{\\circ}C$) مقاومت ویژه نیم‌رساناها از مقاومت ویژه نارساناها کم‌تر است. ب) در برخی مواد مانند سیلیسیوم و ژرمانیوم با کاهش دما، مقاومت ویژه در دمای خاصی به صورت ناگهانی افت می‌کند و به صفر می‌رسد. پ) افزایش طول رسانا یا کاهش مساحت مقطع آن باعث می‌شود، مقاومت ویژه رسانا افزایش یابد. ت) مقاومت ویژه یک نیم‌رسانا با افزایش دما، کاهش می‌یابد.', 2, 2, 80, 350, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:12:18', 5, 'done'),
(7856, ' در مدار داده‌شده، مقاومت الکتریکی لامپ‌های رشته‌ای $A$، $B$ و $C$ به ترتیب $۴ \\Omega$، $۳ \\Omega$ و $۶ \\Omega$ و نیروی محرکه باتری آرمانی $۱۸ V$ است. با بستن کلید $k$، توان مصرفی لامپ $C$ چند وات و چگونه تغییر می‌کند؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:12:08', 5, 'done'),
(7857, ' در مدار داده‌شده اگر توان مصرفی مقاومت $R$ برابر $۴۰ W$ باشد، آمپرسنج آرمانی چند آمپر را نشان می‌دهد؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:11:56', 5, 'done'),
(7858, ' در شکل داده‌شده برای آن که منبع نیروی محرکه الکتریکی بار الکتریکی $+۱ mAh$ را از خود عبور داده و آن را از پایانه منفی به پایانه مثبت خود منتقل کند، باید چند ژول کار انجام دهد؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:11:40', 5, 'done'),
(7859, '6- در مدار داده‌شده، توان خروجی باتری به ازای جریان‌های $۲ A$ و $۸ A$ یکسان است. در حالتی که ولت‌سنج آرمانی عدد صفر را نمایش می‌دهد، توان مصرفی باتری چند وات است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:55:21', 5, 'done'),
(7860, ' در مدار داده‌شده با وصل کلید $k$، جریان عبوری از آمپرسنج آرمانی نصف می‌شود. $R$ چند اهم است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:52:37', 5, 'done'),
(7861, 'در مدار داده‌شده، اگر اختلاف پتانسیل $۳۲۰ V$ بین دو نقطه $a$ و $b$ برقرار شود، جریان چند آمپر از مقاومت $۲۵$ اهمی عبور می‌کند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:52:23', 5, 'done'),
(7862, ' دو سر یک بخاری برقی به اختلاف پتانسیل الکتریکی $۲۲۰ V$ وصل است و جریان الکتریکی $۵ A$ از آن عبور می‌کند. اگر این بخاری در هر شبانه‌روز به مدت $۳ h$ روشن باشد، هزینه یک ماه مصرف برق این بخاری چند تومان است؟ (یک ماه را سی روز در نظر بگیرید و قیمت برق مصرفی به ازای هر کیلووات‌ساعت $۴۰$ تومان است.)', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:52:04', 5, 'done'),
(7863, ' در مدار داده‌شده، اگر یک باتری آرمانی یک بار بین دو نقطه $A$ و $B$ و بار دوم بین دو نقطه $C$ و $D$ بسته شود، جریانی که آمپرسنج آرمانی در حالت دوم نشان می‌دهد، چند برابر مقدار نشان داده شده در حالت اول است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:51:39', 5, 'done'),
(7864, ' در مدار داده‌شده ولت‌سنج آرمانی $۸ V$ را نشان می‌دهد. اگر به جای آن یک آمپرسنج آرمانی قرار دهیم، چند آمپر را نشان خواهد داد؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:51:09', 5, 'done'),
(7865, ' در مدار داده‌شده اگر اختلاف عددی که دو آمپرسنج آرمانی نشان می‌دهند، $۵۰ mA$ باشد، نیروی محرکه باتری چند ولت است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:50:51', 5, 'done'),
(7866, ' در مدار داده‌شده، اگر توان مصرفی مقاومتی که بیشترین توان را مصرف می‌کند، $۷۲۰ W$ باشد، توان مصرفی مقاومتی که کم‌ترین توان را مصرف می‌کند، چند وات است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:50:38', 5, 'done'),
(7867, '۱۴ - در مدار داده‌شده، اگر مقاومت رئوستا را افزایش دهیم، اعدادی که آمپرسنج و ولت‌سنج آرمانی نشان می‌دهند، به ترتیب از راست به چپ چگونه تغییر می‌کنند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:50:28', 5, 'done'),
(7868, ' روی یک باتری آرمانی اعداد $۲/۵ V$ و $۲۰۰۰ mA.h$ نوشته شده است. این باتری را به لامپی به مقاومت الکتریکی $۵ \\Omega$ وصل می‌کنیم. مدت‌زمانی که این باتری لامپ را روشن نگه می‌دارد، چند دقیقه است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:50:18', 5, 'done'),
(7869, ' نمودار جریان برحسب اختلاف پتانسیل یک رسانای فلزی و یک LED مطابق شکل زیر است. هنگام اعمال اختلاف پتانسیل $۲ V$ به دو سر هر یک از آن‌ها، مقاومت الکتریکی LED چند برابر مقاومت الکتریکی رسانای فلزی است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:50:09', 5, 'done'),
(7870, ' سه رسانای مسی استوانه‌ای هم‌دما با سطح مقطع و طول‌های متفاوت نشان داده شده در شکل زیر را به صورت مجزا به اختلاف پتانسیل معینی وصل می‌کنیم. اگر جریان الکتریکی عبوری از رسانای A برابر $I$ باشد، اختلاف جریان عبوری از رساناهای B و C چند $I$ است؟', 2, 2, 80, 350, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:49:55', 5, 'done'),
(7871, ' طول سیم A ، ۳ برابر طول سیم B و جرم سیم A ، ۶ برابر جرم سیم B است. اگر چگالی و مقاومت ویژه فلز سازنده سیم A به ترتیب $\\frac{۳}{۲}$ و $\\frac{۲}{۳}$ برابر چگالی و مقاومت ویژه فلز سازنده سیم B باشد، مقاومت الکتریکی سیم B چند برابر مقاومت الکتریکی سیم A است؟', 2, 2, 80, 350, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:49:41', 5, 'done'),
(7872, '  شکل زیر قسمتی از یک مدار الکتریکی را نشان می‌دهد که در آن پتانسیل الکتریکی نقاط A و B به ترتیب $-۲۰ V$ و $۱۰ V$ است. اگر وسیله الکتریکی (۱) در هر دقیقه $۳ kJ$ انرژی الکتریکی به مدار بدهد، وسیله الکتریکی (۲) در این مدت چند کیلوژول انرژی الکتریکی و چگونه مبادله می‌کند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:13:49', 5, 'done'),
(7873, ' روی دو لامپ A و B به ترتیب اعداد $(۱۰۰ W , ۲۰۰ V)$ و $(۶۰ W , ۱۵۰ V)$ نوشته شده است. این دو لامپ را به ترتیب به اختلاف پتانسیل‌های $V_1$ و $V_2$ وصل می‌کنیم. اگر جریان عبوری از لامپ A ، ۲ برابر جریان عبوری از لامپ B باشد، نسبت $\\frac{V_1}{V_2}$ کدام است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:49:19', 5, 'done'),
(7874, ' در مدار شکل زیر با بستن کلید k مقداری که ولت‌سنج نشان می‌دهد، چند ولت و چگونه تغییر می‌کند؟ (ولت‌سنج و آمپرسنج، آرمانی هستند.)', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:49:09', 5, 'done'),
(7875, ' نمودار اختلاف پتانسیل دو سر باتری‌های A و B برحسب جریان عبوری از آن‌ها به شکل زیر است. توان خروجی بیشینه باتری A چند برابر توان خروجی بیشینه باتری B است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:49:00', 5, 'done'),
(7876, ' اگر جریان عبوری از یک باتری از $۲ A$ به $۳ A$ برسد، توان خروجی آن از $۱۶ W$ به $۱۸ W$ می‌رسد. اگر دو سر این باتری را به دو سر یک مقاومت $۴$ اهمی وصل کنیم، اختلاف پتانسیل دو سر باتری چند ولت می‌شود؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:48:50', 5, 'done'),
(7877, '۲۴ - در مدار شکل زیر اگر مقاومت رئوستا را به تدریج از $۴ \\Omega$ به $۸ \\Omega$ برسانیم، توان خروجی منبع چگونه تغییر می‌کند؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:48:42', 5, 'done'),
(7878, ' در مدار داده‌شده، مقاومت معادل بین دو سر سیم‌های $A$ و $B$ چند اهم است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:48:33', 5, 'done'),
(7879, ' در مدار زیر، اگر کلید $k_1$ باز و کلید $k_2$ بسته باشد، مقاومت معادل مدار برابر $R_{eq}$ و اگر کلید $k_1$ بسته و کلید $k_2$ باز باشد، مقاومت معادل مدار برابر با $R\'_{eq}$ است. نسبت $\\frac{R_{eq}}{R\'_{eq}}$ کدام است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:48:22', 5, 'done'),
(7880, ' در مدار داده‌شده، اگر کلید $k$ را وصل کنیم، اعدادی که آمپرسنج‌های آرمانی $A_1$ و $A_2$ نشان می‌دهند، به ترتیب از راست به چپ چه تغییری می‌کنند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:48:13', 5, 'done'),
(7881, '۲۸ - در شکل داده‌شده، اختلاف پتانسیل الکتریکی دو سر مقاومت $۱۶$ اهمی، $۲$ برابر اختلاف پتانسیل الکتریکی دو سر مقاومت $۱۲$ اهمی است. جریان عبوری از مقاومت $R$ چند آمپر است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:48:00', 5, 'done'),
(7882, ' در مدار داده‌شده، همه مقاومت‌ها $۳$ اهمی‌اند. ولت‌سنج آرمانی چند ولت را نشان می‌دهد؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:47:44', 5, 'done'),
(7883, ' نمودار تغییر ولتاژ دو سر باتری برحسب جریان عبوری از آن در مدار شکل (الف)، مطابق شکل (ب) است. اگر آمپرسنج جریان $۰/۲۵ A$ را نشان دهد، نیروی محرکه این باتری چند ولت است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:47:34', 5, 'done'),
(7884, ' چند لامپ کاملاً مشابه که حداکثر توان قابل تحمل آن‌ها $۱۶ W$ است، مطابق شکل در مداری قرار گرفته‌اند. حداکثر توان این مجموعه، بدون این‌که لامپی آسیب ببیند، چند وات است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:47:20', 5, 'done'),
(7885, ' در شکل داده‌شده، مقداری که ولت‌سنج آرمانی نشان می‌دهد، نصف نیروی محرکه باتری است. R چند اهم است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:47:11', 5, 'done'),
(7886, '۳۳ - در مدار شکل زیر، وقتی مقاومت رئوستا برابر $۴ \\Omega$ است، توان خروجی منبع $P_1$ است. اگر مقاومت رئوستا را $۲۰ \\Omega$ افزایش دهیم، توان خروجی منبع دوباره برابر $P_1$ می‌شود. R چند اهم است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:46:58', 5, 'done'),
(7887, '۳۴ - بیشینه توان قابل تحمل سه مقاومت $۲$، $۳$ و $۶$ اهمی یکسان است. این سه مقاومت را یک بار مطابق شکل (الف) و یک بار مطابق شکل (ب) به هم می‌بندیم. اگر بیشینه توانی که می‌توان از مدار شکل (الف) گرفت تا هیچ مقاومتی آسیب نبیند، $۱۸ W$ باشد، بیشینه توانی که می‌توان از مدار شکل (ب) گرفت، طوری که هیچ مقاومتی آسیب نبیند، چند وات است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:46:47', 5, 'done'),
(7888, '۳۵- روی یک باتری مقدار $۱۲۰۰ mAh$ نوشته شده است. اگر این باتری جریان الکتریکی ثابت $۸۰ \\mu A$ را فراهم سازد، چند دقیقه طول می‌کشد تا خالی شود؟', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:46:25', 5, 'done'),
(7889, '۳۶ - از هر مقطع یک رسانای اهمی، در حالت اول، در مدت $t$، به طور خالص تعداد $N$ الکترون آزاد عبور می‌کند. اگر در حالت دوم، از این رسانا در مدت $۲t$، به طور خالص تعداد $۲N$ الکترون آزاد عبور کند، انرژی الکتریکی مصرفی در رسانا در حالت دوم چند برابر حالت اول است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:46:10', 5, 'done'),
(7890, '۳۷ - در مدار شکل زیر، اگر توان خروجی منبع نیروی محرکه $۹ W$ باشد، جریان الکتریکی عبوری از آن چند آمپر است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:45:58', 5, 'done'),
(7891, '۳۸ - در شکل زیر، دو کره رسانای مشابه روی پایه‌های عایقی قرار دارند. بار الکتریکی کره A برابر $-۲۰ \\mu C$ و کره B بدون بار الکتریکی است. با وصل‌شدن کلید K، در مدت $۴ ms$ دو کره به تعادل الکتریکی می‌رسند. در این مدت، جریان الکتریکی متوسط عبوری از سیم واصل دو کره چند میلی‌آمپر و در چه جهتی است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 21:13:31', 5, 'done'),
(7892, '۳۹ - یک مفتول از جنس طلا به شعاع مقطع $r$ دارای یک روکش یکنواخت آلومینیمی به ضخامت $d$ است. اگر مقاومت الکتریکی مفتول و روکش آن برابر باشد، $\\frac{d}{r}$ کدام است؟ (مقاومت ویژه طلا $۲/۴ \\times ۱۰^{-۸} \\Omega.m$ و مقاومت ویژه آلومینیم $۳ \\times ۱۰^{-۸} \\Omega.m$ است.)', 2, 2, 80, 350, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:45:35', 5, 'done'),
(7893, '۴۰ - دو سیم مسی هم‌جرم A و B به طور جداگانه به اختلاف پتانسیل یکسان و ثابتی وصل هستند. اگر شعاع مقطع سیم A، $n$ برابر شعاع مقطع سیم B باشد، در مدت معین، گرمای تولیدشده توسط سیم A، چند برابر گرمای تولیدشده توسط سیم B است؟', 2, 2, 80, 350, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:45:11', 5, 'done'),
(7894, '۴۱ - در مدار شکل زیر، آمپرسنج آرمانی $۲/۵ A$ را نشان می‌دهد. کار انجام‌شده توسط منبع نیروی محرکه روی هر کدام از الکترون‌های عبوری از آن چند ژول است؟ ($e = ۱/۶ \\times ۱۰^{-۱۹} C$)', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:44:50', 5, 'done'),
(7895, '۴۲ - در مدار شکل زیر، اگر مقاومت الکتریکی پتانسیومتر از $R$ به $۳R$ برسد، عددی که ولت‌سنج آرمانی نشان می‌دهد، $۲$ برابر می‌شود. مقاومت درونی منبع نیروی محرکه چند برابر $R$ است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:44:39', 5, 'done'),
