(7909, ' چهار مقاومت الکتریکی $R_۱ = ۲ \\Omega$، $R_۲ = ۴ \\Omega$، $R_۳ = ۶ \\Omega$ و $R_۴ = ۱۲ \\Omega$ را طوری به هم می‌بندیم که با اتصال آن‌ها به یک باتری با مقاومت درونی $۴ \\Omega$، توان خروجی باتری بیشینه شود. در این مدار کدام مقاومت بیشترین توان الکتریکی را مصرف می‌کند؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:29:24', 1, '2026-03-27 20:29:05', 5, 'done'),
(7910, ' کدام‌یک از گزینه‌های زیر صحیح است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:28:56', 5, 'done'),
(7911, ' سیمی به طول $60 cm$ و قطر مقطع $4 mm$ را به دو سر یک باتری با اختلاف پتانسیل $0/3 mV$ که $900 C$ بار ذخیره شده دارد، متصل می‌کنیم. چند ثانیه پس از برقراری جریان، باتری خالی می‌شود؟ ($\\rho = 10^{-8} \\Omega . m$ مقاومت ویژه سیم و $\\pi = 3$)', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:28:35', 5, 'done'),
(7912, ' کدام‌یک از نمودارهای زیر مربوط به یک دیود نور گسیل است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:28:20', 5, 'done'),
(7913, ' نمودار جریان عبوری برحسب اختلاف پتانسیل دو سیم توپر و هم طول $A$ و $B$، مطابق شکل مقابل است. اگر مقاومت ویژه و چگالی سیم $A$ به ترتیب $2$ و $\\frac{3}{2}$ برابر مقاومت ویژه و چگالی سیم $B$ باشد، در این‌صورت جرم سیم $A$ چند برابر جرم سیم $B$ است؟', 2, 2, 80, 350, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:28:07', 5, 'done'),
(7914, ' در چه تعداد از مدارهای زیر، مقاومت‌های $R_1$ و $R_2$ به‌طور موازی بسته شده‌اند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:27:56', 5, 'done'),
(7915, ' در شکل زیر، هنگامی‌که کلید $k$ باز است، ولت‌سنج ایده‌آل $24$ ولت را نشان می‌دهد و هنگامی‌که کلید بسته است، ولت‌سنج ایده‌آل $21$ ولت را نشان می‌دهد. مقاومت درونی این باتری چند اهم است؟ ($I$، جریان عبوری از مدار را هنگامی که کلید $k$ بسته است نشان می‌دهد.)', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:27:39', 5, 'done'),
(7916, ' توان تولیدی و توان تلف شده در یک باتری به ترتیب $20 W$ و $2 W$ است. اگر مقاومت خارجی $4/5 \\Omega$ باشد، افت پتانسیل درون مولد چند ولت است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:27:28', 5, 'done'),
(7917, ' سه مقاومت مشابه را به‌طور متوالی به اختلاف پتانسیل ثابتی می‌بندیم. در این حالت توان مصرفی مجموعه $20$ وات می‌شود. اگر این سه مقاومت را به‌طور موازی به همان اختلاف پتانسیل ببندیم، توان مصرفی مجموعه چند وات می‌شود؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:27:18', 5, 'done'),
(7918, ' در مدار شکل مقابل، اگر لغزندهٔ رئوستا به سمت چپ حرکت کند، اعدادی که آمپرسنج ایده‌آل و ولت‌سنج ایده‌آل به ترتیب از راست به چپ نشان می‌دهند، چگونه تغییر می‌کند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:27:06', 5, 'done'),
(7919, ' شکل زیر یک مدار الکتریکی را نشان می‌دهد. اگر توان مصرفی مقاومت $R_3$، $6$ برابر توان مصرفی مقاومت $R_2$ باشد، آمپرسنج ایده‌آل چه عددی را برحسب آمپر نشان می‌دهد؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:26:55', 5, 'done'),
(7920, ' در مدار شکل روبه‌رو توان مصرفی در کدام مقاومت از سایر مقاومت‌ها کم‌تر است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:26:42', 5, 'done'),
(7921, ' در شکل زیر مقاومت معادل بین دو نقطه $A$ و $B$ چند اهم است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:26:32', 5, 'done'),
(7922, ' مطابق شکل زیر، چهار لامپ مشابه در مداری قرار دارند و کلید در وضعیت $a$ وصل شده است. اگر کلید را از وضعیت $a$ به وضعیت $b$ تغییر دهیم، نور لامپ‌های ۱ و ۲ چه تغییری خواهند کرد؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:26:22', 5, 'done'),
(7923, ' در مدار شکل زیر تمامی مقاومت‌ها مشابه و مقدار هر یک از آن‌ها برابر $۴\\Omega$ است. آمپرسنج چه عددی را برحسب آمپر نشان می‌دهد؟ (ولت‌سنج و آمپرسنج ایده‌آل است.)', 2, 2, 80, 351, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:26:09', 5, 'done'),
(7924, '  نمودار جریان عبوری برحسب ولتاژ دو سر دو رسانای $A$ و $B$ مطابق شکل مقابل است. از این دو رسانا جریان یکسان $I_۰$ عبور می‌کند، به‌طوری که در مدت زمان $۲$ دقیقه تعداد $۱۲\\times ۱۰^{۱۸}$ الکترون از مقطع هر سیم شارش می‌کند. اگر مقاومت رسانای $B$ برابر $۴k\\Omega$ باشد، مقاومت رسانای $A$ چند کیلو اهم است؟ ($e=۱/۶\\times ۱۰^{-۱۹}C$)', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:59', 5, 'done'),
(7925, ' مقاومت الکتریکی یک سیم فلزی به‌طول $۲۵$ متر و قطر مقطع $۲mm$ برابر $۱۰۰\\Omega$ است. اگر سیم را ذوب کنیم و از آن سیمی به مقاومت $۲۵\\Omega$ بسازیم، سطح مقطع سیم جدید چند میلی‌متر مربع است؟ ($\\pi=۳$)', 2, 2, 80, 350, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:50', 5, 'done'),
(7926, ' شکل زیر قسمتی از یک مدار الکتریکی است. اگر کمترین توان مصرفی در مقاومت‌ها $۴۸W$ باشد، در مدت $۱۰$ ثانیه چند ژول انرژی الکتریکی در مقاومت $۳\\Omega$ مصرف می‌شود؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:43', 5, 'done'),
(7927, '  در شکل مقابل آمپرسنج و ولت‌سنج آرمانی به ترتیب چند آمپر و چند ولت را نشان می‌دهند؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:33', 5, 'done'),
(7928, 'در مدار شکل زیر اگر با حرکت لغزنده مقاومت رئوستا از $۴\\Omega$ به $۱۲\\Omega$ افزایش یابد، توان خروجی مولد چگونه تغییر می‌کند؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:25', 5, 'done'),
(7929, ' در شکل مقابل جریان $I\'$ برابر چند آمپر است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:16', 5, 'done'),
(7930, ' در شکل مقابل، مقاومت معادل بین دو نقطه $A$ و $B$ چند اهم است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:25:07', 5, 'done'),
(7931, ' در شکل مقابل، جریان عبوری از سیم‌های رسانای $A$ و $B$ برحسب اختلاف پتانسیل دو سر آن‌ها نشان داده شده است. دو سر سیم‌های $A$ و $B$ را به چه اختلاف پتانسیلی برحسب ولت متصل کنیم تا در مدت $۱$ دقیقه تعداد الکترون عبوری از مقطع سیم $A$، $۳\\times ۱۰^{۲۱}$ الکترون بیشتر از تعداد الکترون عبوری از مقطع سیم $B$ باشد؟ ($e=۱/۶\\times ۱۰^{-۱۹}C$)', 2, 2, 80, 349, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:24:36', 5, 'done'),
(7932, ' در مدار مقابل مقاومت رئوستا را افزایش می‌دهیم، توان خروجی باتری چگونه تغییر می‌کند؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:24:26', 5, 'done'),
(7933, 'در مدار شکل زیر، توان مصرفی دو مقاومت $R_۱$ و $R_۲$ یکسان است؛ نسبت توان مصرفی مقاومت $R_۳$ به توان مصرفی مقاومت $R_۴$ کدام است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:24:16', 5, 'done'),
(7934, ' در مدار شکل زیر، نسبت جریان عبوری از مولد بعد از بستن کلید $K$ به جریان عبوری از مولد قبل از بستن کلید، کدام است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:24:08', 5, 'done'),
(7935, ' در شکل زیر، حداکثر توان قابل تحمل تمام مقاومت‌ها یکسان است و حداکثر توان مصرفی مجموعه، بدون اینکه مقاومت‌ها آسیب ببینند برابر $۱۳۵W$ است. حداکثر توان قابل تحمل هر یک از مقاومت‌ها چند وات است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:23:53', 5, 'done'),
(7936, ' مقاومت الکتریکی سیم $A$ نصف مقاومت الکتریکی سیم $B$ و اختلاف پتانسیل الکتریکی دو سر آن $۴$ برابر اختلاف پتانسیل دو سر سیم $B$ است. اگر در یک مدت معین $۸\\mu C$ بار الکتریکی از هر مقطع رسانای $B$ عبور کند، در همین مدت، چه تعداد الکترون از هر مقطع سیم $A$ عبور خواهد کرد؟ ($e=۱/۶\\times ۱۰^{-۱۹}C$)', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:23:37', 5, 'done'),
(7937, ' در مدار شکل زیر، اگر انرژی الکتریکی مصرف شده در مقاومت $R_۱$ در مدت $۱۲$ دقیقه، برابر با $۱۲/۹۶$ کیلوژول باشد، نیروی محرکهٔ مولد ($\\varepsilon$) چند ولت است؟', 2, 2, 80, 351, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:23:27', 5, 'done'),
(7938, ' در مدار شکل زیر، ولت‌سنج آرمانی $۸$ ولت و آمپرسنج آرمانی $۱A$ را نشان می‌دهد. در این حالت توان خروجی باتری چند وات است؟', 2, 2, 80, 352, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:23:19', 5, 'done'),
(7939, ' در مدار شکل مقابل، لامپ‌ها مشابه و ولتاژ اسمی آن‌ها $۲۴۰V$ می‌باشد. اگر توان مصرفی لامپ $L_۳$ برابر $\\frac{۴۰۰}{۹}W$ باشد، توان اسمی لامپ‌ها چند وات است؟ (مقاومت لامپ‌ها ثابت فرض شود.)', 2, 2, 80, 352, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:23:08', 5, 'done'),
(7940, ' اگر گفته شود که «آمپر - ساعت باتری (۱)، بیش‌تر از آمپر - ساعت باتری (۲) است.»، کدام نتیجه‌گیری الزاماً در مورد مقایسه این دو باتری صحیح است؟', 2, 2, 80, 349, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:22:58', 5, 'done'),
(7941, 'طرفین وجه‌های یک مکعب مستطیل فلزی با ابعاد $L \\times ۲L \\times ۳L$ را به اختلاف پتانسیل $V$ وصل می‌کنیم. نسبت بیش‌ترین جریان الکتریکی به کم‌ترین جریان الکتریکی کدام است؟', 2, 2, 80, 350, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:22:48', 5, 'done'),
(7942, 'سیم رسانایی را ذوب کرده و با آن سیم جدیدی درست می‌کنیم که طول آن $n$ برابر طول سیم اولیه است. اگر در اثر ذوب کردن سیم، حجم آن تغییر نکرده باشد و نمودار $V-I$ سیم‌ها به‌صورت شکل زیر باشد، $n$ کدام است؟', 2, 2, 80, 350, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-26 17:30:28', 1, '2026-03-27 20:22:36', 5, 'done'),
