(8269, 'امروزه زیست‌شناسی ویژگی‌هایی دارد که آن را به رشته‌ای مترقی، توانا، پویا و امیدبخش تبدیل کرده است. چند مورد در بین همه این ویژگی‌ها، مشترک است؟\n\nالف) بررسی ارتباط بین اجزای جانداران\n\nب) کمک از اطلاعات رشته‌هایی غیر از زیست‌شناسی\n\nج) فناوری‌های اطلاعاتی و ارتباطی و مهندسی ژنتیک', 1, 4, 12, 3, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:07', 1, '2026-03-29 17:22:41', 4, 'done'),
(8270, 'چند مورد از موارد زیر از نظر صحیح یا غلط بودن با عبارت زیر مشابه است؟\n\nداشتن منشأ زیستی، ویژگی مشترک سوخت‌های زیستی و فسیلی است.\n\nالف) انواعی از کربوهیدرات‌ها به مولکول‌های فسفولیپیدی و پروتئینی غشای یاخته جانوری متصل‌اند.\n\nب) زیست کره آخرین سطح حیات است که همه جانداران آن توانایی پاسخ به محرک‌های محیطی را دارند.\n\nج) تولید فرآورده‌های غذایی و دارویی با عواقب زیانبار برای افراد از موارد نقض اخلاق زیستی در علم زیست‌شناسی محسوب می‌شود.\n\nد) استفاده از اطلاعات سایر رشته‌ها برای شناخت بیشتر سامانه‌های زنده تأیید کننده ارتباط بین رشته‌ها می‌باشد.', 1, 4, 12, 3, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:07', 1, '2026-03-29 17:22:10', 4, 'done'),
(8271, 'پس از ورود غذا به حفره دهانی انسان، کدام گزینه، ترتیب وقایع رخ داده تا زمان ورود توده غذایی به معده را به درستی بیان می کند؟\n\n\n\nالف: ارسال پیام از مغز و شروع ارادی بلع\n\nب: ورود غذا به مری\n\nج: شروع حرکات کرمی\n\nد: فشار زبان به توده غذا', 1, 4, 13, 2, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:21:52', 4, 'done'),
(8272, 'نوعی حرکت لوله گوارش که یک حلقه در لوله ظاهر می شود ................... حرکت دیگر ................... .', 1, 4, 13, 2, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:21:43', 4, 'done'),
(8273, 'با توجه به مطالب کتاب درسی در گفتار $2$ فصل $2$ زیست شناسی دهم، کدام گزینه عبارت را به درستی کامل می کند؟\n\n«با در نظر گرفتن یک انسان سالم و بالغ، لیپوپروتئین های کم چگال ($LDL$) ................... لیپوپروتئین های پرچگال ($HDL$)، ...................»', 1, 4, 13, 10, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:21:36', 4, 'done'),
(8274, 'در خصوص اندام های موجود در بدن یک انسان سالم و بالغ، کدام عبارت درست است؟', 1, 4, 13, 2, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:21:26', 4, 'done'),
(8275, 'به طور معمول، در خصوص صفرا کدام مورد نادرست است؟', 1, 4, 13, 9, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:21:10', 4, 'done'),
(8276, 'کدام عبارت در مورد همه ی اندام های دستگاه گوارش که در خنثی کردن کیموس خارج شده از معده دخالت دارند، درست است؟', 1, 4, 13, 9, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:21:00', 4, 'done'),
(8277, 'مطابق اطلاعات کتاب درسی، در خصوص آنزیم های برون یاخته ای ساخته شده توسط روده ها، کدام مورد، برای تکمیل عبارت زیر، مناسب است؟\n\n«به طور معمول، .................. در .................. در آن نقش دارد (دارند).»', 1, 4, 13, 9, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:20:51', 4, 'done'),
