(8303, 'یاخته هایی که در سطح خود دارای گیرنده برای هورمون های ترشح شده از اندام های لوله گوارش هستند، کدام مشخصه را دارند؟', 1, 4, 13, 9, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:15:10', 4, 'done'),
(8304, 'در رابطه با بخش هایی از لوله گوارش که قابلیت جذب مواد را دارند؛ کدام گزینه نادرست است؟', 1, 4, 13, 10, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:14:39', 4, 'done'),
(8305, 'لوزالمعده از طریق دو مجرا ترشحات خود را به دوازدهه می ریزد کدام ویژگی این دو مجرا را از یکدیگر متمایز می کند؟', 1, 4, 13, 9, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:14:57', 4, 'done'),
(8306, 'بر اساس مطلب کتاب درسی در بخش کیسه ای شکل لوله گوارش انسان سالم و بالغ، برخی مواد پس از تماس با کلریدریک اسید، فعال می شوند. کدام عبارت در خصوص این مواد تازه ترشح شده، به درستی بیان شده است؟', 1, 4, 13, 9, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:06:17', 1, '2026-03-29 17:14:21', 4, 'done'),
