(8454, 'با توجه به شکل زیر که تصویر میکروسکوپی بخشی از یک اندام گیاهی علفی می‌باشد، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«با قاطعیت می‌توان گفت که یاخته نشان داده‌شده با شمارهٔ ..................... به‌دلیل ..................... با یاخته شمارهٔ ..................... متفاوت و با یاختهٔ دیگر مشابه است.»', 1, 4, 17, 37, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:55:54', 4, 'done'),
(8455, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در گیاه گندم زراعی، یاخته‌های مریستمی که ..................... .»', 1, 4, 17, 38, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:55:41', 4, 'done'),
(8456, 'در کدام موارد زیر، دو ویژگی بیان‌شده دربارهٔ یکی از انواع یاخته‌های گیاهی است؟\n\nالف: یاخته‌های احاطه‌کنندهٔ دستهٔ آوندی - یاخته‌هایی با طول زیاد و دیوارهٔ پسین ضخیم و چوبی‌شده\n\nب: یاخته‌هایی با هستهٔ درشت مرکزی و فاقد دیوارهٔ ضخیم - یاخته‌های افزایش‌دهندهٔ عرض ساقه در هر نهان‌دانه\n\nج: فراوان‌ترین یاخته‌های تولیدشده توسط کامبیوم بین آوندها - یاخته‌های عبوردهندهٔ شیرهٔ گیاه از صفحات آبکشی\n\nد: یاخته‌های تولیدشده توسط کامبیوم چوب‌پنبه‌ساز به سمت درون - اولین یاخته‌های مشاهده‌شده زیر میکروسکوپ', 1, 4, 17, 37, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:55:20', 4, 'done'),
(8457, 'کدام گزینه جاهای خالی را به درستی پر می‌کند؟\n\n«مشخص شده است که ترکیبات ..................... برخلاف ترکیبات ..................... در پیشگیری از سرطان نقش مثبتی دارند.»', 1, 4, 17, 33, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:55:03', 4, 'done'),
(8458, 'کدام گزینه در ارتباط با یاخته(های) مُسن به درستی بیان شده است؟', 1, 4, 17, 32, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:54:53', 4, 'done'),
(8459, 'کدام گزینه در خصوص برش عرضی ساقهٔ نوعی گیاه دو لپه، صحیح بیان نشده است؟', 1, 4, 17, 37, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:54:41', 4, 'done'),
