(8498, 'در گیاه لوبیا، یاخته‌هایی که به سامانۀ بافت آوندی تعلق دارند و حداقل در یک انتهای خود دوکی شکل هستند، کدام مشخصه را ندارند؟', 1, 4, 17, 36, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:45:26', 4, 'done'),
(8499, 'در ارتباط با گیاهان، چند مورد، عبارت زیر را به‌طور مناسب کامل می‌کند؟\n\n«فقط بعضی از .................... »\n\nالف) کاروتنوئیدها، در رنگ‌دیسه قرار دارند.\n\nب) آنتی‌اکسیدان‌ها، در دیسه‌ها قرار دارند.\n\nج) دیسه‌ها، آنتوسیانین ندارند.\n\nد) دیسه‌ها، رنگیزه ندارند.', 1, 4, 17, 33, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:45:14', 4, 'done'),
(8500, 'در نوعی گیاه نهان‌دانۀ دولپه، در آینده، نوعی مریستم ایجاد و فعال خواهد شد. در خصوص این نوع مریستم چند مورد به طور حتم صحیح است؟\n\nالف) سبب تغییر در نوع سامانۀ پوششی گیاه می‌گردد.\n\nب) سبب بروز ویژگی(های) مشترک بین جانداران می‌شود.\n\nج) از تقسیم آن یاخته‌هایی با دیوارۀ نخستین نازک تولید می‌شود.\n\nد) در افزایش قطر زیاد ساقه و ریشۀ گیاه، نقش مهمی را ایفا می‌کند.', 1, 4, 17, 38, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:45:04', 4, 'done'),
(8501, 'با توجه به مطالب کتاب درسی، دربارۀ اندامک‌هایی که در یک یاختۀ گیاهی می‌توانند ساختار کیسه‌ای‌شکل داشته باشند، چند مورد عبارت زیر را به درستی تکمیل می‌کند؟ «هر یک از آن‌ها که .........»\n\nالف) دارای پروتئین‌های ساخته‌شده توسط رناتن‌ها هستند، فاقد آنزیم‌های تجزیه‌کنندۀ مواد هستند\n\nب) به سمت بخش‌های دیگر یاخته جابه‌جا می‌شوند، در پی تغییر موقعیت نوعی ساختار فسفولیپیدی ایجاد شده‌اند\n\nج) بیش از یک بخش کیسه‌مانند دارد، از طریق کانال‌های پروتئینی غشای خود، موادی را به درون خود وارد می‌کند\n\nد) می‌توانند در طول حیات یاخته، اندازه‌های متفاوتی داشته باشند، قابلیت ذخیرۀ ترکیبات رنگی را درون خود دارند', 1, 4, 17, 33, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:44:37', 4, 'done'),
(8502, 'در خصوص مسن‌ترین لایه از دیوارۀ یاخته‌ای که می‌تواند در یاخته‌های گیاهی مطرح‌شده در کتاب درسی وجود داشته باشد، چند مورد زیر درست است؟\n\nالف) ساخته‌شدن آن می‌تواند بدون ترشح موادی به خارج از پروتوپلاست یاخته صورت گیرد.\n\nب) به طور حتم به دنبال تقسیم یاخته، در همۀ بخش‌های دیوارۀ بین دو یاخته حاصل از تقسیم، مشاهده می‌شود.\n\nج) ممکن است در بخشی از مراحل رشد یاخته‌های واجد دیوارۀ پسین، در تماس مستقیم با فسفولیپیدهای غشا باشد.\n\nد) ممکن است از به هم پیوستن گروهی از ریزکیسه‌ها در محلی غیر از وسط یاخته، پس از تقسیم سیتوپلاسم تشکیل گردد.', 1, 4, 17, 32, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:44:07', 4, 'done'),
(8503, 'در پوست تنۀ یک درخت پنج‌ساله، یاخته‌هایی دیده می‌شوند که مرکز اصلی تنظیم ژنتیک خود را از دست داده‌اند. کدام مورد فقط در خصوص برخی از این یاخته‌ها صادق است؟', 1, 4, 17, 38, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:12', 1, '2026-03-29 17:43:50', 4, 'done'),
(8504, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«همۀ گیاهان فتوسنتزکننده، فسفر مورد نیاز خود را به‌صورتی از خاک به‌دست می‌آورند که ....................»', 1, 4, 18, 172, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:22', 1, '2026-03-29 17:43:33', 4, 'done'),
(8505, 'چند مورد، در رابطه با معمول‌ترین سازگاری برای جذب آب و مواد مغذی در بسیاری از گیاهان دانه‌دار درست است؟\n\nالف: بخش‌هایی از پیکر جاندار تغذیه‌کننده از گیاه، تا محل درون‌پوست ریشه نفوذ می‌کند.\n\nب: برداشت بخش‌های هوایی گیاه، به غنی‌سازی لایۀ سطحی خاک از نیتروژن منجر می‌شود.\n\nج: جاندار تغذیه‌کننده از گیاه، توانایی تشکیل غلاف در مجاورت یاخته‌های زنده و مردۀ گیاه را دارد.\n\nد: در گیاه برخلاف جاندار تغذیه‌کننده از آن، رونویسی از ژن‌های فعال آن به کمک سه نوع رنابسپاراز انجام می‌شود.', 1, 4, 18, 172, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:22', 1, '2026-03-29 17:43:24', 4, 'done'),
(8506, 'کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\n«کودهای .................... از نظر .................... به یکدیگر شباهت داشته و از نظر .................... با یکدیگر تفاوت دارند.»', 1, 4, 18, 171, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:22', 1, '2026-03-29 17:43:13', 4, 'done'),
(8507, 'در خصوص همۀ بخش‌های تشکیل‌دهندۀ خاک، کدام مورد درست است؟', 1, 4, 18, 171, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:22', 1, '2026-03-29 17:43:01', 4, 'done'),
(8508, 'در صورتی که خاک‌ها دچار کمبود باشند، افزودن برخی مواد باعث افزایش حاصل‌خیزی آنان می‌شود. در خصوص این مواد، کدام مورد درست است؟', 1, 4, 18, 171, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-28 22:07:22', 1, '2026-03-29 17:42:50', 4, 'done'),
