(8643, '42-همۀ گیرنده‌هایی که مغز برای حفظ تعادل از آن‌ها پیام دریافت می‌کند، دارای چه مشخصه‌ای هستند؟', 2, 4, 20, 67, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:47:40', 1, '2026-09-17 15:53:29', 2, 'free'),
