(8814, '16-کدام عبارت در رابطه با یک مرد جوان و سالم درست است؟', 2, 4, 25, 101, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, '2026-09-06 18:25:12', 2, 'free'),
(8815, '17-مطابق مطالب کتاب درسی در بدن یک مرد سالم و بالغ، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول غدد برون‌ریزی از دستگاه تولیدمثل که زامه‌ها از درون آن‌ها عبور نمی‌کنند، از نظر ................ با یکدیگر ................ هستند.»', 2, 4, 25, 99, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, '2026-09-06 18:26:14', 2, 'free'),
(8816, '18-کدام گزینه، درباره هر مجرای اسپرم بر در بدن مردی سالم و بالغ، نادرست است؟', 2, 4, 25, 99, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, '2026-09-06 18:27:04', 2, 'free'),
(8817, '19-مطابق با اطلاعات کتاب‌درسی، طی فرایند نمو جنین، در فاصله میان ایجاد اولین پیام الکتریکی توسط گره پیشاهنگ قلب تا مشخص‌شدن اندام‌های جنسی جنین، چند مورد زیر مشاهده می‌شود؟\n\nالف: طناب عصبی پشتی و کلیه‌ها، شروع به تشکیل‌شدن می‌کنند.\n\nب: رگ‌های دستگاه لنفی و روده بزرگ، شروع به نمو می‌کنند.\n\nج: جوانه‌های برخی اندام‌های حرکتی بدن ظاهر می‌شوند.\n\nد: همه اندام‌های بدن جنین شکل مشخص می‌گیرند.', 2, 4, 25, 106, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, '2026-09-06 18:28:02', 2, 'free'),
(8818, '20-در خصوص لقاح و وقایع بعد از آن کدام عبارت صحیح است؟', 2, 4, 25, 106, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8819, '21-کدام گزینه، عبارت زیر را به طور نامناسب کامل می‌نماید؟\n\n«در دستگاه تولیدمثلی یک پسر جوان، نوعی ساختار کیسه مانند ................»', 2, 4, 25, 99, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8820, '22-یاخته‌های تاژک‌دار موجود در لوله مژک‌دار موجود در دستگاه تولیدمثلی زن، با یاخته‌ای لقاح را آغاز می‌کند که در نهایت منجر به ایجاد جنین می‌شود. کدام عبارت، در ارتباط با این یاخته، صادق است؟', 2, 4, 25, 103, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8821, '23-در انسان، پس از جداشدن جدار لقاحی از نوعی توده یاخته‌ای، ابتدا کدام اتفاق قبل از سایرین رخ می‌دهد؟', 2, 4, 25, 105, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
