INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(8848, '50-در خصوص ساختار و عملکرد زامۀ (اسپرم) انسان، کدام مورد نادرست است؟', 2, 4, 25, 100, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8849, '51-مطابق با مطالب کتاب درسی، انواع تقسیم‌های قابل انجام در لوله زامه‌ساز را در نظر بگیرید. در کدام مورد، افزایش تعداد سانترومرها غیرممکن است؟', 2, 4, 25, 100, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8850, 'در دوران بارداری در صورتی که جنین ها به طور کامل از یکدیگر جدا نشوند، به طور حتم ..........................', 2, 4, 25, 106, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8851, '53-پرده ای که در جفت از مخلوط شدن خون مادر و جنین جلوگیری می کند، دارای چه مشخصه ای می باشد؟', 2, 4, 25, 106, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:11', 1, NULL, NULL, 'free'),
(8852, '1-چند مورد، دربارهٔ طول عمر گیاهان نهان‌دانه به‌درستی بیان شده است؟ الف: هر گیاهی که در سال سوم رشد خود مریستم رویشی دارد، گیاه چوبی است. ب: هر گیاهی که در سال دوم رشد خود گلدهی نمی‌کند، گیاه چندساله است. ج: هر گیاهی که در سال اول رشد خود مریستم گل ندارد، گیاه دوساله است. د: هر گیاهی که در سال اول رشد خود گلدهی می‌کند، گیاه یک‌ساله است.', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8853, '2-کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟ «تمام میوه‌های بدون دانه .................... .»', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8854, '3-کدام موارد وجه‌اشتراک دو گیاه شلغم و چغندر قند است؟ الف) هر ساله می‌توانند دانه و میوه تولید می‌کنند. ب) مواد حاصل از فتوسنتز در ریشهٔ آن‌ها ذخیره می‌شود. ج) یک‌سال پس از رشد دانه، مریستم رویشی به زایشی تبدیل می‌شود. د) هر دو ساقه تغییرشکل یافته دارند.', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8855, '4-کدام جمله به‌نادرستی بیان شده است؟', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8856, '5-گیاه خیار همانند گیاه .................... .', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8857, '6-به طور معمول، در خصوص اجزای تشکیل‌دهندهٔ یک گل کامل، چند مورد درست است؟ الف: هر مادگی، یک برچه دارد. ب: هر برچه، یک تخمدان دارد. ج: هر تخمدان، یک تخمک دارد. د: هر برچه، یک خامه و کلاله دارد.', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8858, '7-دو نوع اصلی تولیدمثل در گیاهان به صورت جنسی و غیرجنسی دیده می‌شود. در شرایط طبیعی، با توجه به روش تولید مثلی درخت آلبالوی بالغ چند ساله که سریع‌تر از روش دیگر انجام می‌شود، چند مورد صحیح است؟ الف) همانند روشی که به کمک ساختار تخصص یافته زنبق انجام می‌شود، به کمک نوعی ساختار فاقد پوستک صورت می‌گیرد. ب) برخلاف پیوند زدن، اندام‌های جدید دارای ژن‌نمود کاملاً مشابهی با گیاه اولیه پایه هستند. ج) همانند روش خوابانیدن، برگ و ریشه جدید از محل جوانهٔ گیاه قبلی ایجاد می‌شوند. د) برخلاف قلمه زدن، وجود خاک برای این نوع تولید مثل الزامی است.', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
(8859, '8-درباره فقط بعضی از گیاهانی که دارای سه سامانه بافتی مجزا از یکدیگر هستند، کدام مورد صدق می‌کند؟', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:48:18', 1, NULL, NULL, 'free'),
