(8937, 'مطابق اطلاعات کتاب درسی، در یاخته‌های یوکاریوتی و آزمایش‌هایی که دانشمندان بر روی آن‌ها انجام می‌دهند، می‌توان مولکول‌های دورشته‌ای مشاهده کرد که از واحدهای نوکلئوتیدی ساخته شده‌اند. کدام مورد مشخصه‌ی مشترک همه‌ی این مولکول‌ها را بیان می‌کند؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:22', 1, NULL, NULL, 'free'),
(8938, 'در خصوص توالی و ترتیب مراحل آزمایش های مزلسون و استال، کدام مورد درست است؟\n\nالف: جداسازی باکتری ها از محیط کشت و بررسی پس از دور اول همانندسازی\n\nب: استخراج دنای باکتری و گریز دادن در شیبی از محلول سزیم کلرید با سرعت بالا\n\nج: نشانه گذاری مادۀ وراثتی با استفاده از نوکلئوتیدهای با ایزوتوپ های سنگین نیتروژن\n\nد: انتقال باکتری های با دنای محتوی ایزوتوپ سنگین نیتروژن به محیط کشت محتوی $^{14}N$', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:22', 1, NULL, NULL, 'free'),
(8939, 'کدام عبارت، دربارۀ همۀ انواع رشته‌های پلی‌نوکلئوتیدی، درست است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:22', 1, NULL, NULL, 'free'),
(8940, 'به‌طور معمول در طی همانندسازی دنای یاخته‌های پارانشیمی، فعالیت آنزیم‌هایی پس از باز شدن مارپیچ دنا مشاهده می‌شود. کدام عبارت، در مورد همۀ این آنزیم‌ها صادق است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:22', 1, NULL, NULL, 'free'),
(8941, 'در خصوص کاربرد آنزیم‌ها در صنعت، کدام مورد درست است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:22', 1, NULL, NULL, 'free'),
(8942, 'در پایان تعدادی از آزمایش‌های گریفیت، اختلالی در فرایند تنفس موش‌ها ایجاد نشد. ویژگی مشترک این آزمایش‌ها چه بود؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:22', 1, NULL, NULL, 'free'),
