(8977, 'در خصوص آمینواسیدها، کدام موارد زیر، درست است؟\n\nالف: آخرین آمینواسید موجود در هر زنجیرهٔ پلی‌پپتیدی به هنگام شرکت در تشکیل پیوند پپتیدی، تنها یک هیدروژن از دست می‌دهد.\n\nب: هر رشتهٔ پلی‌پپتیدی که در پروتئین‌ها مشاهده می‌شود، دارای دو آمینواسید در دو انتهای خود با گروه‌های متفاوت می‌باشد.\n\nج: گروه کربوکسیل آمینواسید در ایجاد ویژگی‌های منحصر به فرد در هر آمینواسید موجود در ساختار پروتئین‌ها نقش دارد.\n\nد: گروه R آمینواسید از طریق یک پیوند اشتراکی به کربن مرکزی مربوط به همان آمینواسید متصل می‌شود.', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8978, 'کدام گزینه در ارتباط با دانشمندان و آزمایش‌های آن‌ها صحیح نمی‌باشد؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8979, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در ارتباط با ساختار پروتئین میوگلوبین می‌توان گفت آخرین سطحی که در آن امکان تشکیل پیوندهای اشتراکی وجود دارد ............... اولین سطحی که در آن پیوندهای هیدروژنی برقرار می‌شود ............... »', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8980, 'در ارتباط با نخستین پروتئینی که ساختار آن کشف شد، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در سطحی از سطوح ساختاری که ............... به‌طور حتم ............... »', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8981, 'کدام گزینه در مورد آنزیم(هایی) که در بازکردن پیچ و تاب فامینه نقش دارند، صحیح است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8982, 'کدام گزینه، عبارت زیر را به طور نامناسب تکمیل می‌کند؟\n\n«طی آزمایشی مشابه با آزمایش مزلسون و استال، به دنبال وارد شدن باکتری‌های کشت شده در محیط حاوی ایزوتوپ ۱۴ نیتروژن به محیط حاوی ایزوتوپ ۱۵ نیتروژن و با فرض اینکه هر سه طرح مربوط به شیوهٔ همانندسازی قابل رخ دادن باشند، با گذشت ............... از شروع آزمایش، ممکن است براساس یکی از این طرح‌ها ...............»', 3, 4, 28, 150, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8983, 'هر پروتئینی در بدن انسان که سبب کاهش انرژی فعال سازی واکنش‌ها می‌شود، غالباً چه مشخصه‌ای دارد؟', 3, 4, 28, 152, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8984, 'یک باکتری که در ماده وراثتی خود دارای نوکلئوتیدهای $^{15}N$ است، پس از قرارگیری در محیط حاوی نوکلئوتیدهای $^{14}N$ همانندسازی می‌کند. پس از سانتریفیوژ دناها در صورتی که مدل همانندسازی ............... فرض شود پس از گذشت زمان............... دقیقه تشکیل شدن ............... لوله آزمایش قابل انتظار است.', 3, 4, 28, 150, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8985, 'اگر در آزمایش‌های مزلسون و استال، در دقیقهٔ ۴۰ ام نوارهای تشکیل شده در لولهٔ آزمایش به شکل زیر باشد، آنگاه می‌توان گفت که ...............', 3, 4, 28, 150, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8986, 'کدام مورد جمله زیر را به درستی تکمیل می‌کند؟\n\n«در جاندارانی که مولکول‌های وراثتی آن‌ها در غشا محصور ............... است امکان مشاهده ............... وجود ندارد»', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8987, 'در ساختار ............... پروتئین‌ها برخلاف ساختار ............... آن‌ها ...............', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8988, 'در ارتباط با همانندسازی عامل اصلی انتقال صفات در جاندارانی که دنای اصلی یاخته‌های آن‌ها توسط غشایی از فضای آزاد میان یاخته جدا شده است، کدام گزینه به درستی بیان شده است؟', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(8989, 'دربارهٔ مراحل همانندسازی دنای اصلی در ............... قطعاً می‌توان بیان داشت ...............', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
