(8991, 'در نخستین آزمایشی که ایوری و همکارانش برای شناسایی عامل اصلی انتقال صفات وراثتی انجام دادند، در ابتدا ............... .', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
