(9000, 'کدام عبارت در مورد سطوح مختلف ساختاری پروتئین‌ها صحیح است؟', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9001, 'کدام گزینه درباره هر مولکول عامل اصلی انتقال صفات وراثتی در یک یاخته ترشح کنندهٔ آنزیم‌های غیرفعال لوزالمعده به طور صحیح بیان شده است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9002, 'در یک مولکول پروتئینی، ممکن ............... .', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9003, 'کدام عبارت از لحاظ درستی یا نادرستی همانند عبارت زیر نمی‌باشد؟\n\n«همه سطوح ساختاری در پروتئین‌ها به ساختاری از پروتئین وابسته می‌باشند که بر مبنای، نوع، تعداد، ترتیب و تکرار آمینواسیدها است.»', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9004, 'دئوکسی ریبونوکلئوتیدها برخلاف ریبونوکلئوتیدها، چه مشخصه‌ای دارند؟', 3, 4, 28, 146, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9005, 'حین همانندسازی دنای اصلی عامل سینه پهلو کدام یک از موارد زیر روی می‌دهد؟', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9006, 'اگر توالی بخشی از یک رشتهٔ دنا در ژن سازندهٔ آنزیم پوشینه در باکتری استرپتوکوکوس نومونیای بیماری‌زا در شرایط معمولی به صورت ($OH - AGTAGAC -$ فسفات) باشد، توالی رشتهٔ دیگر کدام است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9007, 'کدام عبارت همواره درباره همه جاندارانی که همانندسازی دوجهتی دارند، درست است؟', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9008, 'هر زیرواحد پروتئینی موجود در ساختار هموگلوبین، چه مشخصه‌ای دارد؟', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9009, 'کدام گزینه در ارتباط با ماده وراثتی اشرشیاکلای درست است؟', 3, 4, 28, 146, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9010, 'کدام گزینه، عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«نوعی ساختار پروتئینی که با ایجاد ............... بین آمینواسیدها شکل می‌گیرد، ...............»', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9011, 'کدام مورد برای تکمیل عبارت مقابل مناسب است؟ «در محل هر دوراهی همانندسازی، ............... .»', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9012, 'با توجه به شکل زیر، کدام گزینه به درستی بیان شده است؟', 3, 4, 28, 152, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9013, 'کدام گزینه مشخصه مهم ترین آنزیمی که در فرآیند همانندسازی به تشکیل رشته پلی‌نوکلئوتیدی جدید در مقابل رشته الگوی دنا میپردازد را بیان نمی کند؟', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9014, 'چه تعداد از گزاره های زیر در رابطه با کاتالیزورهای زیستی به درستی بیان شده است؟\n\nالف- پیش ماده یک آنزیم در شرایطی می تواند فرآورده آن نیز باشد.\n\nب- همه این مولکول ها از ویتامین به عنوان کوآنزیم استفاده می کنند.\n\nج- همه آنزیم های بدن انسان در pH بین ۶ تا ۸ بهترین فعالیت را دارند.\n\nد- افزایش غلظت پیش ماده تا حد مشخص می تواند سرعت واکنش را افزایش دهد.', 3, 4, 28, 152, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9015, 'در ارتباط با عوامل مؤثر بر فعالیت آنزیم های برون یاخته ای می توان بیان کرد همواره ...............', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9016, 'در پایان تعدادی از آزمایش‌های گریفیت، اختلالی در فرایند تنفس موش‌ها ایجاد نشد. ویژگی مشترک این آزمایش‌ها چه بود؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9017, 'واتسون و کریک با ارائهٔ مدل مولکولی خود برای دِنا ($DNA$)، کدام ویژگی مولکول دِنا را برای نخستین بار مشاهده کردند؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9018, 'مطابق با مطالب کتاب درسی، کدام ویژگی آخرین مرحلهٔ آزمایش‌های ایوری و همکارانش را از سومین مرحلهٔ آزمایش‌های گریفیت متمایز می‌سازد؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9019, 'ترتیب نوکلئوتیدها در دو توالی موجود در یک مولکول دنا ($DNA$) به‌صورت $ACCTT$ و $GATCG$ است. اگر توالی نوکلئوتیدی مکمل این توالی‌ها را به‌ترتیب توالی «۱» و «۲» بنامیم، کدام عبارت دربارهٔ این توالی‌ها و مولکول دو رشته‌ای ساخته‌شده توسط آن‌ها درست است؟', 3, 4, 28, 146, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9020, 'کدام عبارت، دربارهٔ ژن، درست است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9021, 'کدام مورد ویژگی مشترک تمامی نوکلئوتیدهای قرارگرفته در ساختار یک رنای پیک سیتوپلاسمی را بیان می‌کند؟', 3, 4, 28, 147, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9022, 'در کدام مورد، نتیجهٔ تحقیقات دانشمند مورد نظر، به‌درستی مطرح شده است؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9023, 'در ارتباط با مولکول‌های زیستی درون یک یاخته که به‌عنوان مولکول‌های مرتبط با ژن شناخته می‌شوند، کدام مورد زیر درست است؟', 3, 4, 28, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9024, 'در ارتباط با پژوهش‌هایی که در تلاش برای کشف ساختار مولکولی دِنا انجام شد، کدام عبارت نادرست است؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9025, 'کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«ایوری و همکارانش، پس از انتقال عصارهٔ باکتری به محیط کشت حاوی باکتری بدون پوشینه، به باکتری‌ها اجازه دادند تا فرصتی برای ....................... داشته باشند.»', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9026, 'در طی فرایند همانندسازی، در محلی که دو رشتهٔ دِنا از هم جدا می‌شوند، دو ساختار $Y$مانند به‌وجود می‌آید. دربارهٔ وقایعی که در فاصلهٔ بین این دو ساختار رخ می‌دهند، کدام مورد زیر درست است؟', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9027, 'چند مورد از ویژگی‌های زیر دربارهٔ همهٔ آمینواسیدهای موجود در طبیعت صادق است؟\n\nالف ـ همواره حداقل یک پیوند دوگانه در ساختار خود دارند.\n\nب ـ تأثیر آن‌ها در شکل‌دهی پروتئین به ماهیت شیمیایی گروه $R$ بستگی دارد.\n\nج ـ گروه کربوکسیل و آمین به دو سمت کربن مرکزی آمینواسید متصل شده‌اند.\n\nد ـ فقط یکی از گروه‌های متصل به کربن مرکزی، در ایجاد ویژگی‌های منحصربه‌فرد آمینواسید نقش دارد.', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9028, 'کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«اگر با استفاده از روش‌های شیمیایی، آمینواسیدهای یک پروتئین را جدا و شناسایی کنیم، می‌توانیم یکی از سطوح ساختاری پروتئین را تشخیص دهیم که ....................... .»', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9029, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«سطحی از سطوح ساختاری پروتئین‌ها که ....................... ، به‌طور حتم ....................... .»', 3, 4, 28, 151, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(9030, 'کدام مورد زیر، دربارهٔ هیچ‌کدام از آنزیم‌های موجود در بدن انسان صادق نیست؟', 3, 4, 28, 152, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9031, 'چند مورد، در ارتباط با عملکرد آنزیم‌ها نادرست است؟\n\nالف ـ جایگاه فعال هر آنزیم، شکلی مناسب برای قرارگیری کامل پیش‌ماده در آن دارد.\n\nب ـ هر آنزیمی که بیش از یک نوع واکنش را سرعت می‌بخشد، عمل غیراختصاصی دارد.\n\nج ـ در همهٔ واکنش‌هایی که آنزیم‌ها سرعت آن‌ها را زیاد می‌کنند، مقداری آنزیم مصرف می‌شود.\n\nد ـ افزایش غلظت هر آنزیمی که روی چند پیش‌مادهٔ خاص مؤثر است، باعث افزایش سرعت تولید فراورده می‌شود.', 3, 4, 28, 152, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9032, 'در ارتباط با دانشمندی که اطلاعات اولیه در مورد ماهیت مادهٔ وراثتی از فعالیت‌ها و آزمایش‌های وی به‌دست آمد، کدام عبارت درست است؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9033, 'اگر ترتیب نوکلئوتیدها در یک رشتهٔ پلی‌نوکلئوتیدی دِنا ($DNA$) به‌صورت $AAGTC$ باشد، کدام عبارت دربارهٔ رشتهٔ مکمل درست است؟', 3, 4, 28, 146, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9034, 'کدام مورد، دربارهٔ تصویری که ویلکینز و فرانکلین با استفاده از پرتو ایکس از دِنا ($DNA$) تهیه کردند، درست است؟', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
(9035, 'در آزمایش‌های گریفیت، اگر در آزمایشی موش‌ها ....................... می‌توان گفت که در نمونهٔ گرفته‌شده از شش موش‌ها، قطعاً ....................... مشاهده ....................... .', 3, 4, 28, 145, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:23', 1, NULL, NULL, 'free'),
