(9111, '۶۸- در یاخته‌هایی که ..................... قابل مشاهده است، خمیدگی در بخشی از مولکول دنا، می‌تواند سرعت رونویسی را افزایش دهد.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9112, '۶۹- با توجه به فرایند تنظیم بیان ژن مثبت و منفی در مرحلهٔ رونویسی جاندار مورد مطالعهٔ مزلسون و استال (مطرح‌شده در کتاب درسی)، کدام مورد یا موارد زیر درست است؟\n\nالف) در هر نوع تنظیم، تمایل پیوستن پروتئین‌های غیرآنزیمی به بخشی از مولکول دیگر، تحت تأثیر عوامل قندی تغییر می‌کند.\n\nب) تنها در نوعی تنظیم، در صورت اتصال بیش از یک پروتئین به توالی‌های نوکلئوتیدی، تولید رنای پیک چندژنی انجام می‌شود.\n\nج) در تنظیم منفی، همانند تنظیم مثبت، هر توالی نوکلئوتیدی که در تنظیم بیان ژن مؤثر است، در بخشی از خود به رنابسپاراز اتصال دارد.\n\nد) در تنظیم مثبت برخلاف تنظیم منفی، توالی نوکلئوتیدی مجاور جایگاه شروع رونویسی، به نوعی پروتئین چسبیده به قند متصل می‌شود.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9113, '۷۰- شکل زیر، مربوط به هستهٔ یکی از یاخته‌های پوششی کبد انسانی سالم است. کدام عبارت درباره این شکل، به طور حتم صحیح است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9114, '۷۱- مطابق اطلاعات کتاب درسی، در ارتباط با تفاوتهای یاخته های پروکاریوتی و یوکاریوتی، کدام موارد درست هستند؟\n\nالف- حذف توالی های معین از رنای پیک ($mRNA$) ساخته شده.\n\nب- ورود پروتئین های ساخته شده به اندامک های غشادار مختلف یاخته ای.\n\nپ- قرارگیری رمزه (کدون) پایان در انتهای رشته پلی نوکلئوتیدی قابل ترجمه.\n\nت- ورود اولین رنای ناقل ($RNA$) حامل آمینواسید متیونین به جایگاه $P$ رناتن.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9115, '۷۲- مطابق با اطلاعات کتاب درسی، به منظور انجام رونویسی در یوکاریوت ها، کدام مورد پیش از سایرین رخ می دهد؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9116, '۷۳- کدام عبارت در ارتباط با ساخت پلی پپتید و نحوه تعیین آمینواسیدهای پلی پپتیدها در جانداران، درست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9117, '۷۴- در ارتباط با رشته‌های سازندۀ ژن یک مولکول رنای پیک ($mRNA$)، کدام عبارت درست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9118, '۷۵- کدام مورد، در ارتباط با مراحل مختلف رونویسی درست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9119, '۷۶- به طور کلی میزان رونویسی از یک ژن در یاخته های یوکاریوت به کدام یک از موارد زیر بستگی دارد؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:30', 1, NULL, NULL, 'free'),
(9120, 'در صورت آمیزش یک گل میمونی صورتی رنگ با گرده رسیده تولیدشده توسط یک گل میمونی قرمزرنگ کدام دو ژن نمود (ژنوتیپ) برای تخم ضمیمه حاصل از این لقاح، محتمل هستند؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9121, 'از ازدواج مرد سالم دارای گروه خونی $A$ و توانایی تولید پروتئین $D$ با زنی که ضمن فقدان فاکتور انعقادی ۸، فاقد توانایی تولید پروتئین $D$ و دارای گروه خونی $B$ می‌باشد، تولد کدام فرزند غیرممکن است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9122, 'کدام مورد یا موارد زیر در ارتباط با نوعی بیماری که با استفاده از آن اهمیت ناخالص‌ها در تداوم گوناگونی جمعیت توضیح داده شده، درست است؟\n\nالف تولد دختری سالم از مادر بیمار و پدر سالم غیرممکن است.\n\nب تولد پسری بیمار از مادر سالم و پدر بیمار غیرممکن است.\n\nج تولد دختری بیمار از مادر و پدر سالم امکان‌پذیر است.\n\nد تولد پسری سالم از مادر و پدر بیمار امکان‌پذیر است', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9123, 'اگر در یک خانواده، ژن‌نمود (ژنوتیپ) پدر و مادر برای صفت کم‌خونی داسی‌شکل متفاوت باشد، کدام مورد می‌تواند نشان‌دهندۀ حالتی دربارۀ خانوادۀ این پدر و مادر باشد که در آن تولد فرزند ذکر شده غیرمحتمل است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9124, 'از ازدواج مردی واجد حداقل یک دگره بارز مربوط به گروه خونی اصلی و دارای گروه خونی $Rh$ مثبت با زنی دارای گروه خونی $A$ و $Rh$ منفی دختری با گروه خونی $AB$ و $Rh$ منفی متولد شده‌است در بارداری بعدی این زن مشاهده کدام مورد زیر در بدن جنین ممکن است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9125, 'در صورت قرارگیری دانه گرده یک گل میمونی صورتی بر روی کلاله یک گل میمونی سفید فنوتیپ رخ‌نمود مورد انتظار برای رویان و ژنوتیپ ژن‌نمود آندوسپرم به ترتیب کدام است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9126, 'با توجه به صفت رنگ نوعی ذرت که در کتاب درسی مطرح شده‌است کدام یک از موارد زیر از نظر فنوتیپ شباهت بیشتری با ذرتی دارد که در ژنوتیپ آن تمام انواع آللهای این صفت دیده می‌شود؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9127, 'کدام مورد به ترتیب از راست به چپ می‌تواند ژنوتیپ یاخته دو هسته‌ای تشکیل‌دهنده گل میمونی صورتی و گرده نارس گل میمونی قرمز باشد؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9128, 'در گیاه لوبیا ژن‌نمود ژنوتیپ ریشه رویانی دانه $AB$ است کدام مورد به ترتیب از راست به چپ در ارتباط با ژن‌نمود درون‌دانه آندوسپرم این دانه یاخته سازنده گرده نارس و یاخته خورشی که در تشکیل این دانه شرکت داشته محتمل است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9129, 'اگر هر ذرتی که تنها دارای سه دگره قرمز در ژنوتیپ خود است با یک ذرت کاملا سفید آمیزش کند، در مجموع طبق قوانین احتمالات امکان ..................... وجود ندارد', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9130, 'در گیاه ذرت اگر ژن‌نمود رویان و اندوخته دانه دارای دو نوع دگره $A$ و $B$ باشد کدام گزینه به ترتیب می‌تواند نشان‌دهنده ژن‌نمود پوسته دانه و یاخته دو هسته‌ای باشد؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9131, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\nدر یک گیاه گل میمونی که ژن‌نمود آن ..................... می‌باشد ..................... یاخته‌هایی که در گل یافت می‌شوند رنگیزه‌های دارند که سبب ظهور رنگی ..................... در گل میمونی می‌گردند', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9132, 'کدام گزینه برای تکمیل گزاره زیر مناسب است؟\n\n»در صورتی که یک موش با ژن‌نمود $BbEe$ با موشی که ژن‌نمود $BbEE$ دارد آمیزش کند امکان مشاهده ..................... در میان زاده‌ها وجود ندارد', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9133, 'به طور طبیعی در نارگیل دیپلوئید ژن‌نمود ..................... می‌تواند $BBB$ باشد و در این صورت ژن‌نمود $ABB$ برای درون‌دانه ..................... است', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9134, 'از آمیزش کدام یک از حالات زیر پیدایش ذرت با رنگ تیره‌تر از ذرت $AaBbCc$ امکان‌پذیر نیست؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9135, 'با در نظر گرفتن نوعی ذرت که رنگ آن صفتی با سه جایگاه ژنی است ذرت حاصل از آمیزش کدام گیاهان می‌تواند رنگ قرمزتری داشته باشد؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9136, 'در یک گیاه آلبالو ژن‌نمود ریشه رویانی دانه $AA$ است کدام مورد به ترتیب از چپ به راست در ارتباط با ژن‌نمود آندوسپرم این دانه و یاخته سازنده گرده نارس و یاخته بافت خورشی که در تشکیل این دانه شرکت داشته است محتمل می‌باشد؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9137, 'با قرار گرفتن دانه گرده ذرت $AABb$ بر روی کلاله ذرت دیگر $aaBb$ به ترتیب کدام ژنوتیپ‌ها برای رویان و آندوسپرم گیاه حاصل مورد انتظار هستند؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9138, '19- کدام گزینه عبارت زیر را به درستی تکمیل می‌کند؟\n\n»دانه‌های نوعی ذرت که دارای درون‌دانه (آندوسپرم) با ژن‌نمود (ژنوتیپ) ..................... هستند، کمترین شباهت از نظر رنگ را با دانه‌های ذرت دارای آندوسپرمی با ژنوتیپ $AAABbbCCc$ دارند', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9139, '20- از آمیزش گل میمونی نر ..................... با گل میمونی ماده ..................... ژن نمود تخم اصلی و ضمیمه می تواند به ترتیب ..................... باشد', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9140, '21- در بررسی دو بیماری هانتینگتون (بیماری مستقل از جنس بارز) و راشیتیسم مقاوم به درمان (بیماری وابسته به X بارز)، به فرض اینکه مادر خانواده خالص و تنها یکی از والدین بیمار باشد، تولد کدام فرزند در همۀ حالات ممکن است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9141, '22- کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«با توجه به آنکه رنگ دانه نوعی ذرت، صفتی با سه جایگاه ژنی است و دو آستانه طیف ژن نمودهای $AABBCC$ و $aabbcc$ را دارند، از آمیزش دو ذرت که هر دو رخ نمودی مشابه با ذرت ..................... دارند، امکان تولید زاده ای که از نظر رخ نمود به ذرت ..................... مشابه باشد وجود ندارد.»', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9142, '23- صفت رنگ در برخی از ذرت ها صفتی پیوسته است که ژن نمود ژنوتیپ های $AABBCC$ و $aabbcc$ رخ نمود (فنوتیپ)های دو آستانه طیف آن را ایجاد می کنند. ذرت های حاصل از آمیزش گیاهی که یاخته های زاینده دانه گرده نارس آن دارای ژن نمود $AABbcc$ می باشند با گیاهی که یاخته های کلاله آن دارای ژن نمود $aaBBC$ هستند، با چند مورد از ذرت های زیر می تواند رنگ نسبتاً یکسانی مشابهی داشته باشد؟\n\nالف- $AaBBCc$ ب- $AaBbCc$ پ- $AaBBCC$ ت- $AaBbcc$', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9143, '24- دو ذرت با رخ نمود (فنوتیپ) متفاوت که تفاوت تعداد دگره (آلل)های نهفته و بارز در ژن نمود (ژنوتیپ) هر یک از ذرت ها برابر ۲ است، با یکدیگر آمیزش می کنند. از نظر صفت رنگ، هیچ یک از ذرت های ایجاد شده با ذرت ..................... یکسان نخواهد بود', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9144, '25- کدام گزینه در ارتباط با فنیل کتونوری (PKU) درست است؟', 3, 4, 30, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:37', 1, NULL, NULL, 'free'),
(9145, '۱- با توجه به مطالب کتاب درسی و شکل زیر که مربوط به بخشی از فرایند چگونگی مقاوم‌شدن باکتری‌ها به پادزیست (آنتی‌بیوتیک) می‌باشد، کدام عبارت، درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9146, '۲- با در نظر گرفتن مطالب کتاب درسی دربارهٔ نوعی بیماری وراثتی مطرح‌شده در فصل چهارم کتاب درسی دوازدهم، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در خانواده‌ای چهار نفره (شامل پدر، مادر، پسر و دختر)، اگر .........................، به‌طور حتم .........................»', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9147, '۳- باتوجه به مطالب کتاب درسی دربارهٔ انواع شواهدی که نشان می‌دهند گونه‌ها در طول زمان تغییر کرده‌اند، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«زیست‌شناسان فقط .........................»', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9148, '۴- کدام موارد، مشخصهٔ مشترک دو سازوکار گونه‌زایی (مطرح‌شده در کتاب درسی) است؟\n\nالف: تغییر در مادهٔ وراثتی نقش به‌سزایی در رخ‌دادن آن‌ها دارد.\n\nب: برای جاندارانی کاربرد دارند که تولیدمثل جنسی دارند.\n\nج: منجر به خروج جمعیت از حالت تعادل می‌شوند.\n\nد: در پیدایش گونه‌های گیاهی جدید نقش دارند.', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9149, '۵- در ارتباط با مطالب عنوان شده در فصل چهارم کتاب درسی دوازدهم، کدام عبارت درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9150, '۶- در کدام مورد، مقایسهٔ درستی بین دنای گونه‌های مختلف صورت گرفته است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9151, '۷- چند مورد از موارد زیر، در ارتباط با شواهد تغییر در گونه‌های جانوری، صحیح است؟\n\nالف: ساختارهای وستیجیال موجود در گروهی از جانوران، ممکن است به‌منظور انجام نقش خود، بزرگ و پیچیده باشند.\n\nب: توالی‌هایی در دنای گربه و دنای ماموت‌ها وجود دارد که از نظر ترتیب نوکلئوتیدهای خود، هیچ تفاوتی با یکدیگر ندارند.\n\nج: با استفاده از ساختارهایی که کار یکسان اما طرح ساختاری متفاوت دارند، جانداران خویشاوند را در یک گروه قرار می‌دهند.\n\nد: مقایسهٔ بالهٔ دلفین و دست گربه، نشان می‌دهند که برای پاسخ به یک نیاز، جانداران به روش‌های مختلفی سازش پیدا کرده‌اند.', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9152, '۸- درخصوص تشریح مقایسه‌ای که شواهدی از تغییر گونه‌ها را ارائه می‌دهد، کدام مورد درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9153, '۹- گروهی از زیست‌شناسان، اجزای پیکر جانداران گونه‌های مختلف را با یکدیگر مقایسه می‌کنند. کدام عبارت، دربارهٔ این زیست‌شناسان درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9154, '۱۰- نوعی جهش کوچک، فقط یک نوکلئوتید ژن زنجیره بتای هموگلوبین را شامل می‌شود. این جهش قطعاً ....................', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9155, ' در پی اثر انتخاب طبیعی در جمعیت‌ها، کدام موارد زیر امکان‌پذیر است؟\n\nالف) ایجاد باکتری مقاوم به پادزیست (آنتی‌بیوتیک) در یک جمعیت فاقد باکتری مقاوم به پادزیست\n\nب) ایجاد جمعیتی که در آن افراد مقاوم به گرما نسبت به جمعیت اولیه بیشتر است.\n\nج) حفظ تنوع اللی در یک جایگاه ژنی در طول زمان\n\nد) افزایش سازش جمعیت با محیط همانند رانش دگره‌ای', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9156, '۱۲- کدام گزینه دربارهٔ عوامل تغییردهندهٔ جمعیت‌ها درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9157, '۱۴- در ارتباط با تشریح مقایسه‌ای جانوران می‌توان گفت اندام‌ها یا ساختارهایی که.', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9158, '۱۵- در همهٔ سازوکارهایی که باعث ایجاد گونه‌های جدید می‌شوند، کدام مورد به‌طور حتم صادق است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9159, '۱۶- با توجه به شواهد تغییر گونه‌ها در کتاب درسی، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n»در طبیعت، همهٔ عواملی که در ......................... نقش دارند،', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9160, '۱۷- چند مورد زیر به ترتیب می‌تواند از پیامدهای جهش در بخش تنظیمی ژن و جهش در خود ژن محسوب شود؟\n\nالف) توقف تولید یک مولکول پروتئینی\n\nب) تغییر شکل سه بعدی نوعی آنزیم پروتئینی\n\nج) افزایش سرعت رونویسی از روی آن ژن\n\nد) تغییر ترتیب نوکلئوتیدهای رنای پیک تولیدی', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9161, '۱۸- کدام گزینه به طور درست بیان شده است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9162, '۱۹- مطابق با مطلب کتاب درسی، شواهدی وجود دارند که نشان می‌دهند گونه‌ها در طول زمان تغییر کرده‌اند. کدام مورد، در خصوص این شواهد نادرست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9163, '۲۰- شواهدی وجود دارند که نشان می‌دهند گونه‌ها در طول زمان تغییر کرده‌اند. کدام گزینه واجد تعبیر درستی در مورد این شواهد است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9164, '۲۱- در خصوص تشریح مقایسه‌ای، از شواهد تغییر گونه‌ها، کدام مورد درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9165, '۲۲- در خصوص شکل زیر که انواع گونه‌زایی را نشان می‌دهد، کدام مورد نادرست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9166, '۲۳- باتوجه‌به مطالب فصل ۴ کتاب دوازدهم، در خصوص سنگواره‌ها، کدام مورد درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9167, '۲۴- در خصوص جهش‌هایی که در مقیاس وسیع‌تری رخ می‌دهند و منجر به ناهنجاری فام‌تنی (کروموزومی) می‌شوند، کدام مورد درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9168, '۲۵- در ارتباط با ساختارهایی که در تشریح مقایسه‌ای بررسی می‌شوند، چند مورد درست است؟\n\nالف: همهٔ ساختارهای همتا طرح ساختاری یکسان دارند.\n\nب: فقط بعضی از ساختارهای آنالوگ عملکردی یکسان دارند.\n\nج: همهٔ ساختارهای آنالوگ طرح ساختاری غیریكسان دارند.\n\nد: فقط بعضی از ساختارهای همتا عملکردی غیریكسان دارند', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9169, '۲۶- طبق مطالب کتاب‌درسی، در ارتباط با عواملی که نشان می‌دهند گونه‌ها در طول زمان تغییر کرده‌اند، کدام مورد درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9170, '۲۷- در خصوص فقط بعضی از عواملی که بدون کاهش تعداد افراد، ممکن است جمعیت را از حالت تعادل خارج کنند، کدام مورد صحیح است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9171, '۲۹- در بررسی عوامل برهم زنندهٔ تعادل در جمعیت گیاهی دوجنسی و با ۲ نوع دگره، تنوع ژنتیکی در این جمعیت کاهش می‌یابد. در این خصوص کدام گزینه، نمی‌تواند درست باشد؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9172, '۳۰- در کدام گزینه، هیچ‌یک از ویژگی‌های ناهنجاری‌های فام‌تنی ممکن در فرد مبتلا به نشانگان داون بیان نشده است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
