(9174, '۳۲- با در نظر گرفتن عواملی که سبب جهش در یاخته‌های بدن انسان می‌شوند، کدام مورد صحیح است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9175, '۳۳- در جمعیت‌های که به تعادل هاردی - واینبرگ رسیده‌اند، کدام مورد همواره رخ می‌دهد؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9176, '۳۴- در گیاه گل‌میمونی، در جمعیتی که در حال تعادل است، فراوانی گل‌های قرمز دو برابر گل‌های صورتی است. فراوانی دگرهٔ رنگ سفید چند درصد است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9177, '۳۵- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n»تغییر فراوانی دگره‌ای اگر بر اثر .................... رخ دهد، به‌طور حتم .................... را در پی خواهد داشت«.', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
