(9184, '۴۲- کدام گزینه، عبارت زیر را به‌طور مناسب کامل می‌کند؟\n\n»عاملی که با .................... باعث خروج جمعیت از حال تعادل می‌شود، به‌طور حتم', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9185, '۴۳- از منظر تشریح مقایسه‌ای، بال کلاغ و بال پروانه مونارک .................... و اندام‌های جلویی دلفین و شیرکوهی', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9186, '۴۴- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n»نوعی از شواهد تغییر گونه‌ها، .................... است، که این مورد (موارد) نشانگر', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
