(9191, '۴۹- کدام گزینه در ارتباط با نوعی جهش که در پی اثر پرتوی فرابنفش بر ماده وراثتی انسان ایجاد می‌شود، صحیح است ؟', 3, 4, 31, 123, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
