(9193, ' کدام مورد برای تکمیل عبارت مقابل مناسب است؟ «معمولاً، هر گیاه .................... که از آمیزش گیاهان گل مغربی مورد مطالعه هوگو دووری ایجاد می‌شود،', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9194, ' بروز هر جهش کوچک در یک ژن، همواره تغییری در ......... ایجاد می‌کند.', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9195, '۵۳- کدام گزینه در ارتباط با عواملی که موجب می‌شوند جمعیت روند تغییر در پیش گیرد درست است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9196, '۵۴- کدام گزینه، دربارهٔ تشریح مقایسه‌ای به طور قطع، درست بیان شده است؟', 3, 4, 31, 127, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9197, ' کدام گزینه، در ارتباط با نوعی پدیدهٔ موثر بر جمعیت که در طی آن در اثر وقوع رویدادهای تصادفی جمعیت را از حالت تعادل خارج می‌شود، به درستی بیان شده‌است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9198, '۵۶- در خصوص شواهدی که بررسی آن‌ها اطلاعاتی را پیرامون تغییر گونه‌ها فراهم می‌کند، با توجه به کتاب درسی چند مورد نادرست است؟\n\nالف) هر یک از این شواهد که برای تشخیص خویشاوندی گونه‌ها کاربرد دارد، می‌تواند به کمک مهندسی ژنتیک نیز مورد بررسی قرار بگیرد.\n\nب) هر یک از ساختارهایی که در تشریح مقایسه‌ای برای رده‌بندی جانداران استفاده می‌شود، اندام‌هایی کارآمد با طرح ساختاری یکسان می‌باشند.\n\nج) هر یک از شواهدی که امکان بررسی تاریخچهٔ تغییر جانوران را فراهم می‌کند، معمولاً حاوی قسمت‌های سخت پیکر جانداران قدیمی است.\n\nد) هر یک از ساختارهایی که نشان‌دهندهٔ سازش جانوران مختلف نسبت به شرایط محیطی هستند، در تشریح مقایسه‌ای فقط شامل اندام‌هایی با کار یکسان می‌شوند.', 3, 4, 31, 127, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9199, ' مطابق اطلاعات کتاب درسی، عواملی منجر به وارد شدن جمعیت‌ها به مسیر تغییر می‌شوند. در خصوص این عوامل کدام مورد نادرست است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9200, ' مطابق اطلاعات کتاب درسی، کدام مشخصه زیر سازوکار گونه‌زایی دگرمیهنی را از هم‌میهنی، متمایز می‌سازد؟', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9201, '۵۹- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، در صورتی که جهش در توالی .................... مربوط به یک ژن مولد پروتئین رخ دهد .................... انتظار می‌رود.»', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9202, ' کدام مورد، عبارت زیر را به درستی کامل می‌کند؟\n\n«جهش کوچکی که .................... نمی‌تواند موجب .................... شود.»', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9203, '۶۱- در خصوص سنگواره‌ها، کدام مورد نادرست است؟', 3, 4, 31, 127, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:44', 1, NULL, NULL, 'free'),
(9204, '1- در کدام فرایند، تولید ATP با روش متفاوتی نسبت به سایر واکنش‌ها صورت می‌گیرد؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9205, '2- در کتاب زیست‌شناسی یازدهم با نمونه‌ای از ساخته‌شدن ATP در سطح پیش‌ماده آشنا شده‌اید. کدام مورد در خصوص این فرایند درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9206, '3- در خصوص دو مولکول نشان داده شده در شکل مقابل، کدام مورد نادرست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free');
