(9207, '4- در ارتباط با اطلاعات کتاب درسی، کدام مورد در تعداد بیشتری از یاخته‌های بدن قابل مشاهده است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9208, '5- در خصوص یاخته‌ای ماهیچه‌ای در بدن انسانی سالم، کدام مورد به‌طور حتم صادق است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9209, '6- در کدام مورد، هر دو روش مطرح شده برای ساخت ATP مشابه هستند؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9210, '7- بعضی از یاخته‌های زنده در شرایط کمبود یا نبود اکسیژن نیز می‌توانند انرژی مورد نیاز خود را تأمین کنند. کدام عبارت، درباره همه روش‌های تأمین انرژی در این شرایط درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9211, '8- مطابق با مطالب کتاب درسی، در یاخته‌های نگهبان روزنه گیاه آلبالو، نوعی ترکیب شیمیایی در بخش‌های مختلفی از یاخته می‌تواند الکترون‌های پرانرژی را از مولکول‌های آلی دریافت کند. کدام عبارت درباره این ترکیب نادرست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9212, '9- کدام مورد ویژگی مشترک انواع تخمیرهای مطرح شده در کتاب درسی را بیان نمی‌کند؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9213, '10- مطابق با شکل زیر در یک یاخته ماهیچه اسکلتی، کدام عبارت درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9214, '11- در خصوص ساختار مولکولی که به‌عنوان شکل رایج و قابل استفاده انرژی در یاخته‌ها مطرح می‌شود، کدام مورد درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9215, '12- در فرایند تجزیه مرحله‌ای گلوکز در یاخته پوششی کبد، پس از تجزیه‌شدن مولکول شش‌کربنی، کدام اتفاق زودتر از سایرین رخ می‌دهد؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9216, '13- در یاخته‌های بدن انسان بخشی از واکنش‌های تجزیه مولکول گلوکز در اندامکی دو غشایی انجام می‌شود. چند مورد از واکنش‌های نامبرده شده در این اندامک‌ها رخ می‌دهد؟\n\nالف) اکسایش نوعی ترکیب سه‌کربنی بدون فسفات\n\nب) مصرف شدن نوعی کربوهیدرات شش‌کربنی دارای فسفات\n\nج) اکسایش نوعی دی‌نوکلئوتید\n\nد) اکسایش قندهای سه‌کربنی دارای فسفات', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9217, '14- کدام مرحله از واکنش‌های تنفس یاخته‌ای هوازی فقط در ماده زمینه‌ای یاخته‌های یوکاریوتی انجام می‌شود؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9218, '15- در فصل ۵ کتاب زیست‌شناسی دوازدهم، از سه روش برای تولید ATP نام‌برده شده است. کدام جمله درباره آنزیم‌های مورد استفاده در این روش‌ها که در یاخته‌های میوگلوبین‌دار باعث تولید ATP می‌شوند، به نادرستی بیان شده است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9219, '16- چند گزینه عبارت زیر را به درستی کامل می‌کند؟\n\n«در اولین مرحله تنفس یاخته‌ای هوازی در بدن انسان ................ .»\n\nالف) کربن دی‌اکسید تولیدی به خون انتشار می‌یابد\n\nب) صرفاً قندهای شش‌کربنه، فسفات‌دار می‌شوند\n\nج) ATP در سطح پیش‌ماده تولید می‌شود\n\nد) نوکلئوتیدهای تولیدی و مصرفی یکسانی شرکت دارند', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9220, '17- در مورد مجموعه آنزیم ATPساز موجود در غشای داخلی راکیزه، چند مورد زیر به مطلب درستی اشاره می‌کند؟\n\nالف) نوعی کانال برای انتقال $H^+$ است و سبب جابه‌جایی $H^+$ برخلاف شیب غلظت می‌شود.\n\nب) به ازای ساخت هر مولکول ATP، مولکول $H_2O$ تولید و مولکول دوفسفاته مصرف می‌کند.\n\nج) تمام آن با هر دو لایه فسفولیپیدی غشاء تماس دارد.\n\nد) بخشی از زنجیره انتقال الکترون بوده و با دریافت الکترون به جابه‌جایی یون‌های $H^+$ می‌پردازد.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9221, '18- جاندار دارای تخمیر لاکتیکی ................ .', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9222, '19- با توجه به واکنش‌های زیر که بخشی از فرایند تنفس یاخته‌ای را نشان می‌دهد، کدام درست است؟\n\n$NAD^+ + 2H^+ + 2e^- \\rightleftharpoons NADH + H^+$', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9223, '20- کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در نخستین مرحله از تنفس یاخته‌ای در پودوسیت‌های انسان، به منظور تولید هر مولکول ................ باید ................ مصرف شود. »', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9224, ' بخشی از تجزیه مولکول گلوکز در یاخته‌های غلاف آوندی در چرخه‌ای انجام می‌شود که درون فضای داخلی راکیزه‌ها قابل رویت است. می‌توان گفت در این چرخه از واکنش‌ها ................ می‌گردد.', 3, 4, 32, 132, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9225, '22- در مورد نوعی مولکول موجود در چرخه کربس که با مولکول حاصل از اکسایش بنیان پیرویک‌اسید ترکیب می‌شود، کدام عبارت صحیح است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9226, '23- کدام مورد در ارتباط با مراحل مختلف نخستین بخش از واکنش‌های تنفس یاخته‌ای در پلاس موسیت‌های انسان صادق است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9227, '24- در ارتباط با واکنش‌های اکسایش استیل‌کوآنزیم A در یاخته کبدی انسان و با توجه به واکنش‌هایی که پس از تولید آخرین مولکول دی‌اکسیدکربن رخ می‌دهد، کدام مورد در یک چرخه پس از سایرین به انجام می‌رسد؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9228, '25- در راکیزه (میتوکندری) یک یاخته جانوری، چند مورد از موارد زیر، تنها پس از تولید مولکول نشان داده شده، رخ می‌دهد؟\n\nالف: انتقال گروه فسفات به مولکول آدنوزین‌تری‌فسفات\n\nب: آزاد شدن اتم کربن از ترکیبی آلی به‌صورت مولکول $CO_2$\n\nج: احیای مولکول $NAD^+$ با دریافت الکترون و تولید $NADH$\n\nد: تشکیل آب، در نتیجه افزوده شدن یون‌های هیدروژن به یون‌های اکسید', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9229, '26- در خصوص فرایند تنفس هوازی در یاخته‌های یوکاریوتی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، در فرایند ................ همانند ................ می-شود.»', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9230, '27- طی فرایندهایی در راکیزه یاخته پوششی انسان، کربن‌دی‌اکسید آزاد می‌شود. کدام مورد، ویژگی مشترک این فرایندها است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9231, '28- طی اولین مرحله تنفس یاخته‌ای در اشرشیا کلای، پس از تأمین انرژی فعال‌سازی، انواعی از مولکول‌های کربن‌دار غیر نوکلئوتیدی تولید یا مصرف می‌شوند. کدام عبارت، درباره این مولکول‌ها درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9232, '29- کدام عبارت درباره چرخه کربس درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9233, '30- چند مورد، درباره واکنش کلی تنفس یاخته‌ای هوازی به‌درستی بیان شده است؟\n\nالف: همه ترکیب‌های دارای اتم اکسیژن، آلی هستند.\n\nب: همه ترکیب‌های غیرآلی، دارای اتم اکسیژن هستند.\n\nج: همه ترکیب‌های دارای اتم کربن، اتم هیدروژن نیز دارند.\n\nد: همه ترکیب‌های دارای عنصر فسفر، نوعی نوکلئوتید هستند.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9234, '31- مطابق متن کتاب درسی، «در صورتی که منابعی که یاخته‌های بدن انسان به طور معمول از آن‌ها برای تأمین انرژی استفاده می‌کنند، کافی نباشند، یاخته‌ها برای تولید ATP به سراغ تجزیه گروه‌های دیگری از مولکول‌های زیستی می‌روند.» کدام مورد در خصوص این گروه‌های دیگر مولکول‌های زیستی صحیح است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9235, '32- در یک یاخته یوکاریوتی کدام یک از واکنش‌های زیر، می‌تواند بدون دخالت محصول رناتن‌های سیتوپلاسمی باشد؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9236, '33- مطابق با مطلب کتاب درسی، در زنجیره انتقال الکترون دو عامل افزایش‌دهنده تراکم یون $H^+$ در بخش داخلی راکیزه وجود دارد. کدام گزینه ویژگی مشترک این دو عامل است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9237, '34- در غشای چین‌خورده میتوکندری (راکیزه) ساختاری پروتئینی وجود دارد که جزء زنجیره انتقال الکترون نبوده اما فعالیتی وابسته به این زنجیره دارد. کدام مورد، درباره آن درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9238, '35- قند فروکتوز می‌تواند در یاخته‌های انسان، توسط واکنش‌هایی تجزیه شده و در تأمین انرژی مؤثر باشد. کدام ویژگی، فقط درباره بعضی از این یاخته‌ها صادق است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9239, '36- کدام ویژگی، تخمیر مؤثر در ورآمدن خمیر نان را از تخمیر مؤثر در تولید محصولات لبنی، در یوکاریوت‌ها متمایز می‌سازد؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9240, '37- در یاخته پودوسیت بدن انسان، فقط در بعضی از محل‌هایی که ریبوزوم‌های سازنده پروتئین‌های موردنیاز میتوکندری حضور دارند، ................', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9241, '38- کدام مورد عبارت زیر را به طور مناسب تکمیل می‌کند؟\n\n«در هیچ یک از مراحل قندکافت، ................ قابل انتظار نیست»', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9242, '39- با توجه به شکل زیر که بخشی از زنجیره انتقال الکترون را نشان می‌دهد، کدام عبارت صحیح است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9243, '40- کدام عبارت تنها در ارتباط با یکی از پروتئین‌های موجود در یک زنجیره انتقال الکترون میتوکندری درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9244, '41- کدام گزینه عبارت زیر را در ارتباط با تنفس یاخته‌ای، به درستی کامل می‌کند؟\n\n«در فرایند ................ همانند ................ بلافاصله ................ »', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9245, '42- در یک تار ماهیچه‌ای متعلق به ماهیچه دو سر، زمانی که اکسیژن حضور ................ امکان ................ وجود ................', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
(9246, '43- هر پروتئینی در زنجیرۀ انتقال الکترون قرار گرفته در غشای داخلی راکیزه که ................، قطعاً ................', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:52:54', 1, NULL, NULL, 'free'),
