(9349, '6- کدام گزینه، جهت تکمیل عبارت زیر مناسب است؟\n\n«(در) رفتاری که ................ .»', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9350, ' با توجه به مطالب کتاب درسی، چند جمله در مورد رفتار جانوران درست بیان شده است؟\n\nالف) رفتار دفاع از قلمرو در جانوران، هزینه‌بر است.\n\nب) خرچنگ‌های ساحلی صدف‌های با اندازه متوسط را ترجیح می‌دهند.\n\nج) به‌طور معمول گاهی جانوران، غذایی را مصرف می‌کنند که هیچ سودی برای آن‌ها ندارد.\n\nد) در همه گونه‌های مختلف در پرندگان هر دو والد هزینه‌های پرورش زاده‌ها را می‌پردازند.', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9351, ' با توجه به مطالب کتاب درسی چند جمله درباره لاک‌پشت‌های دریایی ماده درست است؟\n\nالف) تخم‌های خود را در محیط آب‌های شور رها می‌کنند.\n\nب) به‌دلیل لقاح داخلی، یاخته‌های تخم در بدن این جانور تشکیل می‌شود.\n\nج) به‌نظر می‌رسد میدان مغناطیسی زمین در جهت‌یابی این جانوران نقشی ندارد.\n\nد) این جانور پس از زمستان‌گذرانی در اوایل بهار به سرزمین خود بازمی‌گردد.', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9352, ' پرنده کاکایی پس از آن‌که جوجه‌هایش از تخم بیرون می‌آیند، پوسته‌های تخم را از لانه خارج می‌کند، کدام گزینه، در رابطه با این نوع رفتار پرنده نادرست است؟', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9353, ' چند مورد عبارت زیر را به‌درستی کامل می‌نماید؟\n\n«در رفتار ................ .»\n\nالف) غذایابی ممکن است جانور در محل حضور غذایی با انرژی بیشتر، نوعی غذا با انرژی کمتر را انتخاب نماید\n\nب) رکود تابستانی ممکن است نوعی لاک‌پشت حتی وقتی غذا و آب کافی دریافت می‌کند، رکود تابستانی را نشان دهد\n\nج) زادآوری، انتخاب جفت و نظام جفت‌گیری، به‌منظور دستیابی به موفقیت در زادآوری انجام می‌گیرد\n\nد) قلمروخواهی، قوهای سرخ‌رود مازندران با آواز خواندن سعی می‌کنند از ورود پرنده مزاحم به قلمرو خود جلوگیری کنند', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9354, '11- مطابق اطلاعات کتاب درسی، کدام مورد به ترتیب وجه شباهت و وجه تمایز رفتار فرار کلاغ‌ها از مترسک و رفتار عدم فرار آن‌ها از مترسک ثابت پس از گذر زمان، را نشان می‌دهد؟', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9355, ' در خصوص نوعی نظام جفت‌گیری که والدین برای دستیابی به موفقیت در زادآوری هزینه‌هایی می‌پردازند، کدام عبارت، به‌طور حتم صادق است؟', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
