(9373, '30- در صورتی که ژن مربوط به رفتار ................ که نوعی رفتار غریزی است، دچار جهش شده و غیرفعال شود، ................ مورد انتظار است.', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9374, ' برای این‌که رفتاری توسط انتخاب طبیعی برگزیده شود، به کدام یک از موارد زیر نیاز است؟', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
