(9379, ' در خصوص اجتماع مورچه‌های برگ‌بر، کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«مورچه‌های کارگری که کار دفاع را انجام می‌دهند، ................ مورچه‌های کارگری که برگ‌ها را برش می‌دهند، ................ .»', 3, 4, 35, 169, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9380, '37- بیرون آمدن جوجه‌های کاکایی از تخم سبب آغاز رفتارهایی در پرندهٔ والد و همچنین جوجه‌های تازه متولد می‌شود. کدام ویژگی، دربارهٔ این رفتارها صادق است؟', 3, 4, 35, 167, NULL, NULL, NULL, NULL, NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9381, '38- مطابق کتاب درسی، کلاغ‌ها برای دستیابی به تکه گوشت آویزان به انتهای نخ، رفتاری را بروز می‌دهند. کدام عبارت درباره رفتار این پرنده درست است؟', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9382, '39- پژوهشگران ارتباط یک ژن را با رفتار مراقبت از زاده‌ها در نوعی موش ماده بررسی کرده‌اند که این ژن را ژن B می‌نامیم. در پیکر این موش ماده، اگر ژن B موجود در یاخته‌های مغزی ................ باشد، ممکن نیست ................ .', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9383, '40- کدام مشخصه زیر رفتارهای یادگیری را از رفتارهای کاملاً غریزی در بین جانوران، متمایز می‌سازد؟', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9384, ' درخصوص رفتارهای زادآوری در جانوران، کدام مورد درست است؟', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9385, ' ویژگی مشترک در رفتار زادآوری (تولیدمثل) در همه جانوران کدام است؟', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(9386, ' با توجه به شکل روبه رو، کدام مورد درست است؟', 3, 4, 35, 168, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9387, ' اجتماع مورچه های برگبر از مورچه هایی با شکل، اندازه و کارهای متفاوت تشکیل شده است. کدام مورد در خصوص همه این مورچه ها درست است؟', 3, 4, 35, 169, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9388, '45- مطابق اطلاعات کتاب درسی، کدام گزینه نادرست است؟', 3, 4, 35, 167, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 00:54:06', 1, NULL, NULL, 'free'),
(9389, '1- متحرکی مسیر ABC را در شکل داده شده در مدت 2 min ، با تندی متوسط  3.5 m/s می پیماید. اندازه سرعت متوسط متحرک در این مدت چند متر بر ثانیه است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:34:42', 4, 'free'),
(9390, '2- نمودار مکان - زمان متحرکی، که در راستای محور x حرکت می کند، به شکل داده شده است. چند مورد از عبارت های زیر درباره این متحرک درست است؟\n\n\n\nالف) جهت حرکت متحرک، فقط دو مرتبه، در لحظه های $t_1$ و $t_3$ تغییر می کند.\n\nب) جهت بردار مکان متحرک دو مرتبه، در لحظه های $t_2$ و $t_4$ تغییر می کند.\n\nپ) در بازه زمانی $t_1$ تا $t_3$، اندازه جابه جایی متحرک با مسافت طی شده توسط آن برابر است.\n\nت) در بازه زمانی $t_1$ تا $t_2$، متحرک یک بار از مکان آغازین حرکت خود، عبور می کند.', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:35:13', 4, 'free'),
(9391, '3- نمودار مکان - زمان سه متحرک A ، B و C که بر روی محور x حرکت می کنند، مطابق شکل داده شده است. کدام عبارت ها درباره تندی متوسط $(S_{av})$ و اندازه سرعت متوسط $(V_{av})$ آن ها در بازه زمانی $t_1$ تا $t_2$ درست است؟\n\n\n\nالف) $V_{av, A} = V_{av, B} = V_{av, C}$\n\nب) $S_{av, A} < S_{av, B} < S_{av, C}$\n\nپ) $V_{av, A} = V_{av, B} < V_{av, C}$\n\nت) $S_{av, A} = S_{av, B} < S_{av, C}$', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:35:41', 4, 'free'),
(9392, '4- خودرویی با طی مسیری از شهر A به شهر B می رود و از همان مسیر، در مدت یک ساعت، از شهر B به شهر A بازمی گردد. اگر تندی متوسط خودرو در مسیر رفت 20 m/s و در کل مسیر رفت و برگشت  24 m/s باشد، طول مسیر بین دو شهر چند کیلومتر است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:36:07', 4, 'free'),
(9393, '5- معادله مکان - زمان متحرکی که در راستای محور x حرکت می کند، در SI به صورت $x = 4t^2 - 24t + 27$ است. در کل مدت زمانی که متحرک در حال نزدیک شدن به مکان اولیه خود است، اندازه سرعت متوسط آن چند متر بر ثانیه است؟', 3, 2, 82, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, NULL, NULL, 'free'),
(9394, '6- نمودار مکان - زمان متحرکی که در راستای محور x حرکت می کند، به شکل داده شده است. تندی متحرک در لحظه $t = 8 s$ چند برابر تندی متوسط متحرک در بازه زمانی 2 sتا 12 s است؟ (خط چین رسم شده در لحظه $t = 8 s$ بر نمودار مماس است.)', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:37:20', 4, 'free'),
(9395, '7- نمودار مکان - زمان چهار متحرک که روی محور x حرکت می کنند، به صورت داده شده است. در کدام یک از موارد زیر در بازه زمانی صفر تا t، بردارهای مکان، سرعت و شتاب پیوسته هم جهت است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:37:51', 4, 'free'),
(9396, '8- معادله مکان - زمان متحرکی که در راستای محور x حرکت می کند، در SI به صورت $x = t^3 - 4t + 9$ است. اگر سرعت متوسط متحرک در بازه زمانی صفر تا T، برابر با صفر باشد، سرعت متوسط متحرک در بازه زمانی صفر تا 2T برحسب متر بر ثانیه کدام است؟ $(T \\neq 0)$', 3, 2, 82, 362, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:39:13', 4, 'free'),
(9397, '9- نمودار مکان - زمان متحرکی که در راستای محور x حرکت می کند، به شکل داده شده است. اگر سرعت متوسط متحرک در بازه زمانی $t_1 = 4 s$ تا $t_2$ برابر صفر باشد، تندی متوسط آن در بازه زمانی صفر تا $t_2$ چند متر بر ثانیه است؟', 3, 2, 82, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, NULL, NULL, 'free'),
(9398, '10- متحرکی که روی محور x حرکت می کند، در بازه زمانی معینی در حالی که تندی آن به طور پیوسته در حال کاهش است، از مبدأ مکان عبور می کند. کدام یک از گزینه های زیر درباره حرکت متحرک در این بازه زمانی درست است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:40:43', 4, 'free'),
(9399, '11- سرعت دو متحرک A و B که در راستای محور x حرکت می کنند، در لحظه $t = 2.5 s$ برابر است. اگر شتاب متوسط دو متحرک در 2.5 ثانیه اول به ترتیب $\\vec{i} (2.4 m/s^2)$ و $\\vec{i} (1.8 m/s^2)$ باشد، اختلاف تندی دو متحرک در مبدأ زمان چند متر بر ثانیه می تواند باشد؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:42:22', 4, 'free'),
(9400, '12- نمودار سرعت - زمان متحرکی که روی خط راست حرکت می کند، به شکل داده شده است. اگر اندازه شتاب متحرک در لحظه $t = 10 s$ دو برابر اندازه شتاب آن در لحظه $t = 3 s$ باشد، تندی متحرک در لحظه $t = 10 s$ چند برابر تندی آن در لحظه $t = 3 s$ است؟ (دو خط چین رسم شده، در لحظه های $t = 3 s$ و $t = 10 s$ بر نمودار مماس هستند.)', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:42:54', 4, 'free'),
(9401, '13- نمودار سرعت - زمان متحرکی که در راستای محور x حرکت می کند، به شکل داده شده است. در بازه ای که تندی متحرک در حال افزایش است، شتاب متوسط آن چند متر بر مربع ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:43:18', 4, 'free'),
(9402, '14- نمودار مکان - زمان متحرکی که در راستای محور x حرکت می کند، به شکل داده شده است. اگر مسافت طی شده توسط متحرک در کل حرکت  $50 m$ باشد، اندازه شتاب متوسط متحرک در بازه زمانی $t_1 = 5 s$ تا $t_2 = 25 s$ چند متر بر مربع ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:43:58', 4, 'free'),
(9403, '15- معادله مکان - زمان متحرکی که بر روی محور x حرکت می کند، در SI به صورت $x = -14t + 12$ است. اختلاف اندازه سرعت متوسط متحرک در 0.5 ثانیه پنجم با تندی آن در لحظه $t = 1.5 s$ چند متر بر ثانیه است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:45:04', 4, 'free'),
(9404, '16- متحرکی که با سرعت ثابت روی محور x حرکت می کند، در لحظه های $t_1 = 2 s$ و $t_2 = 5 s$ به ترتیب از مکان های $x_1 = 2 m$ و $x_2 = 17 m$ عبور می کند. بردار مکان این متحرک چند ثانیه در خلاف جهت محور x است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:45:34', 4, 'free'),
(9405, '17- متحرکی در راستای محور x به مدت 2s با سرعت ثابت $v_1 = (5 m/s)\\vec{i}$ و در ادامه به مدت 3 s با سرعت ثابت $v_2 = (-4 m/s)\\vec{i}$ حرکت می کند. سرعت متوسط متحرک در این 5 s در SI کدام است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:46:21', 4, 'free'),
(9406, '18- قطار A به طول $300 m$ با تندی ثابت $ 30 m/s$ و قطار B به طول $400 m$ با تندی ثابت $20 m/s$ روی دو ریل مستقیم، موازی و مجاور به سوی هم در حال حرکت هستند. اگر در مبدأ زمان فاصله آن ها از یکدیگر $1200 m$ باشد، به ترتیب از راست به چپ، پس از چند ثانیه دو قطار به طور کامل از کنار هم عبور می کنند و در این مدت قطار A چند متر جابه جا می شود؟', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:47:01', 4, 'free'),
(9407, '19- نمودار مکان - زمان دو متحرک A و B که در راستای محور x حرکت می کنند، به شکل داده شده است. اگر فاصله دو متحرک در لحظه ای که متحرک A از مبدأ مکان می گذرد $80 m$ باشد، به مدت چند ثانیه فاصله بین این دو متحرک کم تر یا مساوی $200m$ است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:47:15', 4, 'free'),
(9408, '20- مطابق شکل داده شده، دو متحرک (1) و (2) از دو نقطه A و B با تندی های ثابت به سوی یکدیگر حرکت می کنند. اگر تندی متحرک (2)، 2 برابر تندی متحرک (1) باشد، در نقطه M و اگر تندی متحرک (2)، 3 برابر تندی متحرک (1) باشد، در نقطه N از کنار هم می گذرند. فاصله دو نقطه A و B چند متر است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:47:41', 4, 'free'),
(9409, '21- مطابق شکل داده شده متحرک (1) با سرعت اولیه $(4 m/s)\\vec{i}$ و شتاب $(2 m/s^2)\\vec{i}$ از نقطه A می گذرد. یک ثانیه بعد، متحرک (2) حرکت خود را از حال سکون با شتابی به بزرگی $4 m/s^2$ به سمت نقطه A آغاز می کند. در لحظه ای که دو متحرک از کنار هم می گذرند، تندی متحرک (1) چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 08:02:04', 4, 'free'),
(9410, '22- گلوله ای با تندی $40m/s$ به تنه درختی به ضخامت $20 cm$ برخورد کرده و با تندی $10 m/s$ از آن خارج می شود. اگر شتاب حرکت گلوله در تنه درخت ثابت فرض شود، تندی گلوله در لحظه ای که 5 سانتی متر در درون درخت حرکت کرده، چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:48:26', 4, 'free'),
(9411, '23- متحرکی که با شتاب ثابت و سرعت اولیه $v_0$ روی یک خط راست حرکت می کند، در 2 ثانیه سوم حرکت خود، $40 m$ و در 3 ثانیه دوم حرکت خود، $63 m$ را بدون تغییر جهت طی می کند. شتاب حرکت این متحرک در SI کدام است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:48:42', 4, 'free'),
(9412, '24- متحرکی که با شتاب ثابت روی محور x حرکت می کند، در لحظه $t = 0$ در حال حرکت در جهت محور x است. اگر سرعت متوسط این متحرک در 4 ثانیه سوم حرکتش $\\vec{v}_{av} = (-12 m/s)\\vec{i}$ و تندی متوسط آن در همین بازه $15 m/s$ باشد، شتاب این متحرک در SI کدام است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:49:04', 4, 'free'),
(9413, '25- نمودار سرعت - زمان دو متحرک A و B که روی محور x در حال حرکت اند، مطابق شکل داده شده است. اگر دو متحرک در مبدأ زمان در یک نقطه قرار داشته باشند، در لحظه ای که اختلاف تندی آن ها برابر با $10 m/s$ می شود، فاصله دو متحرک از هم برابر با چند متر است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:49:16', 4, 'free'),
(9414, '26- متحرکی که با شتاب ثابت روی محور x حرکت می کند، در لحظه های $t_1 = 3 s$ و $t_2 = 7 s$ از مبدأ مکان عبور می کند. اگر در لحظه ای که متحرک به مکان $x = +4 m$ می رسد، جهت حرکتش عوض شود، معادله حرکت این متحرک در SI کدام است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:49:25', 4, 'free'),
(9415, '27- نمودار مکان - زمان متحرکی که با شتاب ثابت روی محور x حرکت می کند، به صورت شکل داده شده است. اگر تندی متوسط متحرک در 8 ثانیه نخست برابر با $17 m/s$ باشد، تندی آن در لحظه $t = 7 s$ چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:49:37', 4, 'free'),
(9416, '28- نمودار مکان - زمان دو متحرک که با شتاب ثابت و از حال سکون روی محور x شروع به حرکت می کنند، مطابق شکل است. پس از چند ثانیه از شروع حرکت، فاصله دو متحرک از یکدیگر به $20 m$ می رسد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:49:50', 4, 'free'),
(9417, '29- نمودار شتاب - زمان متحرکی مطابق شکل داده شده است. اگر سرعت متوسط متحرک در مدت 10 ثانیه برابر با $9 m/s$ باشد، سرعت اولیه متحرک چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:50:04', 4, 'free'),
(9418, '30- حداکثر اندازه شتاب تندشونده و کندشونده یک اتوبوس به ترتیب $1 m/s^2$ و $5 m/s^2$ است. اگر بیشینه سرعت مجاز در یک خیابان $36 km/h$ باشد، حداقل زمانی که این اتوبوس می تواند مسافت بین دو ایستگاه به فاصله 500 متر را طی کند، چند ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:23:44', 4, 'free'),
(9419, '31- متحرکی که روی محور x با شتاب ثابت $-2 m/s^2$ در حال حرکت است، با سرعت $(-2 m/s)\\vec{i}$ از مکان $x_1 = +3 m$ عبور می کند. در چند متری مبدأ مکان، سرعت متحرک برابر $(-6 m/s)\\vec{i}$ می شود؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:51:08', 4, 'free'),
(9420, '32- متحرکی با شتاب ثابت روی محور x حرکت می کند. اگر جابه جایی این متحرک در سه ثانیه اول و دو ثانیه دوم به ترتیب $(-6 m)\\vec{i}$ و $(-28 m)\\vec{i}$ باشد، بزرگی شتاب متحرک چند متر بر مربع ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:51:24', 4, 'free'),
(9421, '33- نمودار سرعت - زمان متحرکی که روی محور x حرکت می کند، به صورت شکل زیر است. اگر متحرک در 10 ثانیه نخست حرکت، $20 m$ در جهت محور x جابه جا شده باشد، مسافت طی شده توسط متحرک در مدتی که حرکت آن کندشونده است، چند متر است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:27:33', 4, 'free'),
(9422, '34- متحرکی با شتاب ثابت روی محور x در حال حرکت است و در مبدأ زمان در جهت محور x از مبدأ مکان عبور می کند. اگر تندی متوسط متحرک در 9 ثانیه اول $5 m/s$ و سرعت متوسط آن در این مدت $(3 m/s)\\vec{i}$ باشد، سرعت متحرک در لحظه $t = 9 s$ چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:30:38', 4, 'free'),
(9423, '35- معادله سرعت - زمان متحرکی در SI به صورت $v = 2t - 5$ است. سرعت متوسط متحرک در 2 ثانیه دوم حرکت چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:52:10', 4, 'free'),
(9424, '36- متحرکی که روی خط راست در حال حرکت است، در مبدأ زمان با شتاب ثابت شروع به توقف کرده و پس از $9 s$ می ایستد. اگر مجموع مسافت طی شده توسط متحرک در 3 ثانیه ابتدایی و 3 ثانیه انتهایی $90 m$ باشد، مسافت طی شده توسط متحرک در 3 ثانیه میانی چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:52:27', 4, 'free'),
(9425, '37- مطابق شکل زیر، نمودار مکان - زمان متحرکی به صورت سهمی است. سرعت متحرک در لحظه $t = 6 s$ چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:52:43', 4, 'free'),
(9426, '38- نمودار مکان - زمان متحرکی که با شتاب ثابت روی محور x حرکت می کند، در 10 ثانیه نخست حرکتش به شکل زیر است. اگر تندی متوسط متحرک در این مدت، $\\frac{5}{4}$ برابر اندازه سرعت متوسط آن در همین بازه زمانی باشد، اندازه شتاب متحرک چند متر بر مربع ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:36:09', 4, 'free'),
(9427, '39- نمودار سرعت - زمان متحرکی که در راستای محور x حرکت می کند، به شکل زیر است. اگر اندازه سرعت متوسط متحرک در مدتی که در جهت مثبت محور x حرکت می کند، $8 m/s$ باشد، تندی متوسط آن از مبدأ زمان تا اولین لحظه ای که جهت حرکتش تغییر می کند، چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:53:30', 4, 'free'),
(9428, '40- خودرویی با شتاب ثابت a روی محور x شروع به حرکت می کند و پس از مدتی حرکت خود را با سرعت ثابت ادامه می دهد و در نهایت با شتابی به اندازه 2a ترمز کرده و متوقف می شود. اگر مدت زمانی که سرعت خودرو ثابت است با مدت زمانی که حرکت آن کندشونده است، برابر باشد، تندی متوسط خودرو در طی این حرکت چند برابر تندی بیشینه آن است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:37:26', 4, 'free'),
(9429, '41- نمودار شتاب - زمان متحرکی که در راستای محور x حرکت می کند، به شکل زیر است. اگر سرعت متحرک در لحظه $t = 15 s$ برابر $(28 m/s)\\vec{i}$ باشد، اندازه سرعت متوسط آن در بازه زمانی صفر تا $15 s$ چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:38:51', 4, 'free'),
(9430, '42- خودروی A با سرعت ثابت $54 km/h$ در یک مسیر مستقیم به سمت خودروی ساکن B در حال حرکت است. در لحظه ای که خودروی A به فاصله d از خودروی B می رسد، خودروی B با شتاب ثابت $3 m/s^2$ در جهت حرکت خودروی A شروع به حرکت می کند. اگر دو خودرو فقط یک بار به هم برسند، d برابر چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:54:13', 4, 'free'),
(9431, '43- نمودار سرعت - زمان دو متحرک A و B که روی محور x حرکت می کنند، به شکل زیر است. اگر بردار مکان دو متحرک در مبدأ زمان به ترتیب $(10 m)\\vec{i}$ و $(140 m)\\vec{i}$ باشد، در چه لحظه ای برحسب ثانیه دو متحرک به یکدیگر می رسند؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-21 12:54:28', 4, 'free'),
(9432, '44- نمودار مکان - زمان دو متحرک A و B که با شتاب ثابت روی محور x حرکت می کنند، به شکل زیر است. فاصله دو متحرک در لحظه $t = 6 s$ چند برابر فاصله دو متحرک در لحظه $t = 2 s$ است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:44:13', 4, 'free'),
(9433, '45- سرعت دو متحرک A و B که در جهت محور x حرکت می کنند، در بازه زمانی صفر تا T از v به 3v می رسد. اگر نمودارهای شتاب - زمان دو متحرک در این بازه زمانی به شکل های زیر باشد، کدام مورد درباره مقایسه اندازه سرعت متوسط دو متحرک ($v_{av}$) در این مدت درست است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:22:32', 1, '2026-09-18 07:46:03', 4, 'free'),
(9434, '۱- متحرکی که روی محور $x$ در حال حرکت است، مسیری مطابق شکل زیر از نقطه $A$ تا نقطه $B$ می پیماید. بردار مکان این متحرک چند بار تغییر جهت داده است و بردار جابه جایی متحرک در چه جهتی است؟', 3, 2, 82, 362, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:55:26', 4, 'free'),
(9435, '۲- نمودار مکان- زمان جسمی که روی خط راست در حرکت است مطابق شکل زیر است. تندی متوسط این متحرک در مدتی که بردار مکان آن در خلاف جهت محور $x$ است، چند برابر بزرگی سرعت متوسط آن در مدتی است که متحرک در خلاف جهت محور $x$ حرکت می کند؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:55:37', 4, 'free'),
(9436, '۳- سه متحرک $A$، $B$ و $C$ بر روی محور $x$ ها در حال حرکت هستند. در جدول زیر بردار مکان و سرعت این سه متحرک در لحظه های $t_1 = 1 s$ و $t_2 = 2 s$ آورده شده است. تندی متوسط و بزرگی سرعت متوسط چند متحرک در بازه زمانی $t_1 = 1 s$ تا $t_2 = 2 s$ قطعاً با یکدیگر برابر نیست؟\n\nمتحرک A: $t=1$, $\\vec{d}=4\\vec{i}$, $\\vec{v}=5\\vec{i}$ | $t=2$, $\\vec{d}=2\\vec{i}$, $\\vec{v}=10\\vec{i}$\n\nمتحرک B: $t=1$, $\\vec{d}=-5\\vec{i}$, $\\vec{v}=-4\\vec{i}$ | $t=2$, $\\vec{d}=-3\\vec{i}$, $\\vec{v}=-6\\vec{i}$\n\nمتحرک C: $t=1$, $\\vec{d}=2\\vec{i}$, $\\vec{v}=-4\\vec{i}$ | $t=2$, $\\vec{d}=-3\\vec{i}$, $\\vec{v}=-2\\vec{i}$', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:29:07', 4, 'free'),
(9437, '۴- نمودار مکان- زمان متحرکی مطابق شکل مقابل است، در ۷ ثانیه ابتدایی حرکت مدت زمانی که بردار مکان و بردار سرعت متحرک با یکدیگر هم جهت هستند چند برابر مدت زمانی است که بردار سرعت متحرک در خلاف جهت محور $x$ ها و اندازه آن در حال کاهش است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:56:55', 4, 'free'),
(9438, '۵- نمودار سرعت- زمان متحرکی که روی محور $x$ ها در حال حرکت است، مطابق شکل مقابل است. کدام یک از موارد زیر در مورد حرکت متحرک الزاماً صحیح است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:57:11', 4, 'free'),
(9439, '۶- نمودار مکان- زمان متحرکی که روی محور $x$ ها در حال حرکت است، مطابق شکل مقابل است. اگر تندی متوسط متحرک در سه ثانیه اول حرکت $4 \\frac{m}{s}$ و تندی متوسط آن در ۶ ثانیه دوم $13 \\frac{m}{s}$ باشد، تندی متوسط متحرک در ثانیه ۱۲ام حرکت چند $\\frac{m}{s}$ است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:57:25', 4, 'free'),
(9440, '۷- متحرکی که بر روی خط راست حرکت می کند، فاصله بین دو نقطه $A$ و $B$ را با تندی متوسط $36 \\frac{km}{h}$ طی می کند و سپس نصف مسیر را با تندی متوسط $90 \\frac{km}{h}$ برمی گردد. اگر مدت زمان رفت ($t_1$) از مدت زمان بازگشت تا وسط مسیر ($t_2$)، چهار دقیقه بیشتر باشد، کل مدت زمان حرکت متحرک ($t_2 + t_1$) چند دقیقه است؟ (جهت حرکت متحرک در مسیر رفت و برگشت تغییر نکرده است.)', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:29:27', 4, 'free'),
(9441, '۸- متحرکی روی محور $x$ ها از مبدأ مکان و از حال سکون شروع به حرکت می کند. چند مورد از نمودارهای سرعت- مکان زیر می تواند مربوط به این متحرک باشد؟', 3, 2, 82, 362, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:58:18', 4, 'free'),
(9442, '۹- نمودار مکان - زمان متحرکی که روی محور $x$ ها حرکت می‌کند، مطابق شکل مقابل است. اگر تندی متحرک در لحظه $t=20 s$ برابر $2/4 \\frac{m}{s}$ باشد، تندی متوسط متحرک در بازه زمانی صفر تا $20 s$ چند متر بر ثانیه است؟ (خط مماس بر نمودار در لحظه $t=20 s$)', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:58:30', 4, 'free'),
(9443, '۱۰- متحرکی فاصله $A$ تا $B$ را روی مسیر مستقیم در مدت زمان ۳ ثانیه بدون تغییر جهت طی می‌کند. تندی متوسط این متحرک در ثانیه دوم ۲۰ درصد بیشتر از تندی متوسط در ثانیه اول و تندی متوسط در ثانیه سوم ۲۵ درصد بیشتر از تندی متوسط متحرک در ثانیه دوم است. اگر تندی متوسط متحرک در ۲ ثانیه اول حرکت $24/2$ متر بر ثانیه باشد، فاصله $A$ تا $B$ چند متر است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:59:03', 4, 'free'),
(9444, '۱۱- نمودار مکان - زمان متحرکی که روی خط راست حرکت می‌کند، مطابق شکل زیر است. در کدام‌یک از بازه‌های زمانی زیر، تندی متوسط و بزرگی سرعت متوسط با یکدیگر برابر نیستند؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 12:59:15', 4, 'free'),
(9445, '۱۲- متحرکی در مبدأ زمان حرکت خود را از مبدأ مکان در جهت مثبت محور $x$ شروع کرده است و در لحظات $t_1 = 4 s$ و $t_2 = 8 s$ به ترتیب در مکان‌های $x_1 = 10 m$ و $x_2 = 6 m$ قرار دارد. اگر در این ۸ ثانیه جهت حرکت متحرک فقط یک بار تغییر کرده باشد، چه تعداد از عبارت‌های زیر برای چهار ثانیه دوم حرکت این متحرک قطعاً صحیح است؟\n\nالف) بزرگی بردار مکان ابتدا افزایش و سپس کاهش می‌یابد.\n\nب) بردار جابه‌جایی در خلاف جهت محور $x$ است.\n\nپ) در این بازه زمانی جهت حرکت تغییر کرده است.\n\nت) بردار مکان همواره در جهت مثبت محور $x$ است.', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:21:06', 4, 'free'),
(9446, '۱۳- متحرکی در یک مسیر مستقیم از مکان $x_1 = 4 m$ در خلاف جهت محور $x$ ها شروع به حرکت می‌کند و در یک بازه زمانی معین به مکان $x_2 = -2 m$ می‌رسد. اگر در این بازه زمانی، نسبت مسافت طی شده به بزرگی جابه‌جایی $\\frac{11}{3}$ باشد، حداکثر فاصله متحرک از مکان شروع حرکت چند متر می‌تواند باشد؟', 3, 2, 82, 362, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:23:45', 4, 'free'),
(9447, '۱۴- نمودار مکان - زمان متحرکی که روی محور $x$ حرکت می‌کند، مطابق شکل زیر است. اگر در بازه زمانی صفر تا ۱۰ ثانیه، تندی متوسط ۴ برابر اندازه سرعت متوسط متحرک باشد، بیشترین فاصله متحرک از مبدأ مکان در این بازه زمانی ۱۰ ثانیه‌ای چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:00:01', 4, 'free'),
(9448, '۱۵- شکل زیر نمودار مکان - زمان دو متحرک $A$ و $B$ را که با تندی‌های یکسان $3 \\frac{m}{s}$ در حرکت هستند، نشان می‌دهد. فاصله دو متحرک از یکدیگر در مبدأ زمان چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:00:13', 4, 'free'),
(9449, '۱۶- نمودار مکان - زمان متحرکی که بر روی خط راست حرکت می‌کند، مطابق شکل زیر می‌باشد. نسبت بزرگی سرعت متوسط متحرک در ۱۵ ثانیه اول حرکت به بزرگی سرعت متوسط آن در ۱۰ ثانیه دوم کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:00:32', 4, 'free'),
(9450, '۱۷- نمودار مکان - زمان دو متحرک $A$ و $B$ مطابق شکل زیر است. با توجه به نمودار، مسافتی که متحرک $A$ در ثانیه سوم حرکتش طی می‌کند، چند متر بیشتر از مسافتی است که متحرک $B$ در ثانیه پنجم حرکتش طی خواهد کرد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:00:46', 4, 'free'),
(9451, '۱۸- قطاری با تندی ثابت $108 \\frac{km}{h}$ روی مسیر مستقیم در حال حرکت است و از روی یک پل عبور می‌کند. برای این قطار، مدت زمانی که تمام طول قطار روی پل قرار دارد، ۱۵ ثانیه کمتر از بازه زمانی‌ای است که قطار وارد پل شده و به‌طورکامل از آن خارج می‌شود. در این‌صورت طول قطار چند متر است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:01:03', 4, 'free'),
(9452, '۱۹- در شکل زیر، نمودار مکان - زمان متحرک $A$ که با سرعت $2 \\frac{m}{s}$ حرکت می‌کند و متحرک $B$ نشان داده شده است. از مبدأ زمان تا لحظه‌ای که دو متحرک به هم می‌رسند، جابه‌جایی متحرک $B$ چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:01:19', 4, 'free'),
(9453, '۲۱- نمودار مکان - زمان شکل روبه‌رو می‌تواند معرف حرکت کدام متحرک باشد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:01:32', 4, 'free'),
(9454, '۲۲- اگر نمودار شتاب - زمان متحرکی که در امتداد محور $x$ حرکت می‌کند، مطابق شکل باشد، چه تعداد از نمودارهای سرعت - زمان رسم شده می‌تواند متناظر با این نمودار شتاب - زمان باشد؟', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:01:44', 4, 'free'),
(9455, '۲۴- نمودار سرعت - زمان متحرکی که روی خط راست حرکت می‌کند، مطابق شکل زیر است. اگر تندی متوسط این متحرک در ۱۰ ثانیه اول حرکتش برابر $3/5 \\frac{m}{s}$ باشد، بیشینه تندی این متحرک در این مدت زمان چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:31:35', 4, 'free'),
(9456, '۲۵- نمودار شتاب - زمان متحرکی که روی خط راست در حرکت است، مطابق شکل زیر می‌باشد. این متحرک در مبدأ زمان با تندی $5 \\frac{m}{s}$ و از نقطه $x = +10 m$ و در خلاف جهت محور $x$ ها عبور می‌کند. در بازه زمانی $0$ تا $25 s$، این متحرک چند ثانیه در خلاف جهت محور حرکت کرده است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:32:18', 4, 'free'),
(9457, '27- متحرکی با شتاب ثابت در امتداد محور $x$ حرکت می‌کند، در لحظه $t=0$، با تندی $6 \\frac{m}{s}$ از نقطه $A$ و بعد از آن با سرعت $v$ از نقطه $B$ می‌گذرد و در نقطه $C$ متوقف می‌شود. اگر $BC = \\frac{5}{4}AB$ باشد، $v$ چند $\\frac{m}{s}$ است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:02:52', 4, 'free'),
(9458, '29- اگر نمودار مکان - زمان متحرکی که در مسیری مستقیم در حال حرکت است، مطابق سهمی شکل زیر باشد، معادله سرعت - زمان آن در SI کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:03:02', 4, 'free'),
(9459, '31- متحرکی با تندی $10 \\frac{m}{s}$ در مبدأ زمان در خلاف جهت محور $x$ از مکان $x = -8m$ عبور می‌کند. اگر بردار سرعت متوسط متحرک در بازه زمانی صفر تا ۸ ثانیه برابر $\\vec{i} (\\frac{m}{s})$ باشد، تندی متحرک در لحظه‌ای که از مکان $x = 7m$ عبور می‌کند، چند $\\frac{m}{s}$ است؟ (متحرک با شتاب ثابت حرکت می‌کند.)', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:03:15', 4, 'free'),
(9460, '32- معادله مکان متحرکی که روی محور $x$ حرکت می‌کند، در SI به‌صورت $x = t^2 - 3t + 4$ است. در چه لحظه‌ای برحسب ثانیه، سرعت متحرک با سرعت متوسط آن بین لحظه‌های $t=3s$ تا $t=7s$ برابر خواهد شد؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:03:28', 4, 'free'),
(9461, '33- متحرکی با شتاب ثابت به بزرگی $1 \\frac{m}{s^2}$ در امتداد محور $x$ حرکت می‌کند و در لحظه $t=2s$، تندی آن $4 \\frac{m}{s}$ است. کدام‌یک از گزینه‌های زیر می‌تواند نمودار مکان - زمان این متحرک باشد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:03:42', 4, 'free'),
(9462, '34-معادله مکان - زمان متحرکی که روی محور x حرکت می‌کند، در SI به‌صورت $x = 2t^2 - 8t - 25$ است. کدام‌یک از گزینه‌های زیر در مورد حرکت این متحرک صحیح نیست؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:04:03', 4, 'free'),
(9463, '35-معادله مکان متحرکی که روی محور x حرکت می‌کند، در SI به‌صورت $x = t^2 - 4t + 10$ است. در بازه زمانی صفر تا ۶ ثانیه، مسافت طی شده توسط این متحرک چند برابر اندازه جابه‌جایی آن است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:39:12', 4, 'free'),
(9464, '37-دو متحرک A و B که شتابشان ثابت و بزرگی آن‌ها یکسان است، در مبدأ زمان به‌ترتیب از مکان‌های $x_A = 7m$ و $x_B = -20m$ به‌سمت یکدیگر حرکت می‌کنند و پس از ۳ ثانیه به یکدیگر می‌رسند. اگر در هر لحظه‌ای که دو متحرک به‌هم می‌رسند، جهت حرکت آن‌ها عوض شود، فاصله آن‌ها از یکدیگر در لحظه $t = 5s$ چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:42:36', 4, 'free'),
(9465, '38-متحرکی با شتاب ثابت و تندی اولیه $30 \\frac{m}{s}$ ترمز کرده و می‌ایستد. اگر جابه‌جایی متحرک در دو ثانیه اول حرکت ۲۰ برابر جابه‌جایی آن در ثانیه آخر حرکت باشد، کل مسافت پیموده شده از لحظه شروع تا توقف کامل چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:05:19', 4, 'free'),
(9466, '39-نمودار سرعت - زمان متحرکی که روی خط راست حرکت می‌کند، مطابق شکل زیر است. اگر بزرگی شتاب متحرک در $t\'$ ثانیه اول حرکت دو برابر بزرگی شتاب متحرک بعد از لحظه $t\'$ باشد، مسافت طی شده در بازه زمانی که متحرک در خلاف جهت محور در حال حرکت می‌باشد، چند متر است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:05:40', 4, 'free'),
(9467, '40-مطابق شکل زیر، متحرکی مسیر مستقیم A تا B را با شتاب ثابت و بدون تغییر جهت طی می‌کند. فاصله A تا B چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:05:59', 4, 'free'),
(9468, '41-نمودار سرعت زمان متحرکی که روی محور x حرکت می‌کند، مطابق شکل زیر قسمتی از یک سهمی است. کدام‌یک از موارد زیر درست است؟\n\nالف) در بازه زمانی $t_1$ تا $t_3$ شتاب متحرک مثبت است.\n\nب) در بازه زمانی صفر تا $t_2$ تندی متحرک در حال کاهش است.\n\nپ) شتاب متوسط در بازه زمانی $t_1$ تا $t_2$ برابر شتاب متوسط در بازه زمانی $t_2$ تا $t_3$ است.\n\nت) در بازه زمانی $t_1$ تا $t_3$ سرعت متوسط متحرک منفی است.', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:06:16', 4, 'free'),
(9469, '42-شکل زیر، نمودار مکان - زمان متحرکی را نشان می‌دهد که روی محور xها حرکت می‌کند. تندی متوسط این متحرک در کدام بازه زمانی بیشتر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:06:27', 4, 'free'),
(9470, '43-متحرکی روی محور x در حال حرکت است. بردار شتاب متوسط این متحرک در بازه زمانی $t_1 = 0s$ تا $t_2 = 10 s$ برابر با $-10\\vec{i}$ و در بازه زمانی $t_1 = 0s$ تا $t_2 = 20s$ برابر با $-4\\vec{i}$ است. بزرگی شتاب متوسط آن در ۱۰ ثانیه دوم حرکت‌اش، چند متر بر مجذور ثانیه است؟ (تمامی واحدها در SI هستند.)', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:06:58', 4, 'free'),
(9471, '44-دو متحرک از نقطه‌های A و B با سرعت‌های ثابت، به طرف یکدیگر شروع به حرکت می‌کنند و در نقطه O به یکدیگر می‌رسند. اگر مدت زمانی‌که متحرک سریع‌تر، از نقطه O به نقطه مقابل خود (A یا B) می‌رسد برابر $3s$ باشد، مدت زمان رسیدن متحرک دیگر از نقطه O به نقطه مقابلش (A یا B)، چند ثانیه است؟', 3, 2, 82, 362, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:49:33', 4, 'free'),
(9472, '46-نمودار سرعت زمان متحرکی که بر روی محور x حرکت می‌کند، مطابق شکل زیر است. اگر بزرگی جابه‌جایی متحرک تا لحظه $t_1$ برابر $9/6m$ باشد، سرعت متوسط متحرک در بازه زمانی $t_1$ تا $t_3$ چند $\\frac{m}{s}$ است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:08:33', 4, 'free'),
(9473, '47- نمودار مکان - زمان متحرکی که روی خط راست و با شتاب ثابت در حال حرکت است، مطابق شکل زیر می‌باشد. اگر تندی این متحرک در مبدأ زمان برابر $10 \\frac{m}{s}$ باشد، مسافت طی شده توسط آن در بازه زمانی $t_1 = 1s$ تا $t_2 = 5s$ چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:50:51', 4, 'free'),
(9474, 'نمودار سرعت - زمان متحرکی که بر روی خط راست حرکت می‌کند، مطابق شکل زیر است. اگر بزرگی سرعت متوسط این متحرک در بازه زمانی صفر تا $2t_1$ برابر با $5 \\frac{m}{s}$ باشد، سرعت آن در لحظه $4t_1$ چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:52:05', 4, 'free'),
(9475, 'نمودار شتاب - سرعت متحرکی که روی محور xها و از حال سکون شروع به حرکت می‌کند، مطابق شکل مقابل است. تندی متوسط متحرک از لحظه شروع حرکت تا لحظه‌ای که تندی آن برابر $10 \\frac{m}{s}$ می‌شود، چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:53:17', 4, 'free'),
(9476, '50-نمودار سرعت - زمان خودرویی که در راستای محور x حرکت می‌کند، مطابق شکل زیر است. بزرگی شتاب خودرو در لحظه $t_1 = 7s$ چند برابر بزرگی شتاب آن در لحظه $t_2 = 13s$ است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:09:26', 4, 'free'),
(9477, 'دو متحرک A و B با تندی‌های ثابت، در مبدأ زمان به‌ترتیب از مکان‌های $x_A = 5m$ و $x_B = -10m$ در سوی مثبت محور x عبور می‌کنند. اگر فاصله این دو متحرک از یک دیگر در لحظه $t=10s$ برای دومین‌بار برابر $5m$ گردد، در چه لحظه‌ای بر حسب ثانیه، فاصله دو متحرک $20m$ می‌شود؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:55:35', 4, 'free'),
(9478, 'متحرکی با شتاب ثابت $2 \\frac{m}{s^2}$ در جهت محور x، از مبدأ مکان و از حال سکون شروع به حرکت می‌کند. در چه مکانی، تندی متحرک به $16 \\frac{m}{s}$ می‌رسد؟', 3, 2, 82, 366, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:56:05', 4, 'free'),
(9479, 'نمودار سرعت - زمان متحرکی که بر روی محور x حرکت می‌کند، مطابق شکل مقابل است. کدام مورد برای این متحرک درست است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:56:39', 4, 'free'),
(9480, 'نمودار مکان - زمان متحرکی که با شتاب ثابت روی محور xها حرکت می‌کند، مطابق شکل مقابل است. سرعت متوسط این متحرک در ۶ ثانیه اول حرکت چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 08:57:23', 4, 'free'),
(9481, '57- خودرویی با سرعت ثابت $72 \\frac{km}{h}$ بر جاده مستقیمی در حال حرکت است. راننده خودرو مانعی را در فاصله ۱۵۰ متری خود می‌بیند و پس از مدت زمان $t_1$ ثانیه اقدام به ترمز می‌کند و $t_2$ ثانیه بعدی با شتاب ثابت $2 \\frac{m}{s^2}$ از تندی خودرو می‌کاهد. حداقل نسبت $\\frac{t_2}{t_1}$ چقدر باشد تا خودرو به مانع برخورد نکند؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:10:28', 4, 'free'),
(9482, '58-متحرکی بر روی یک مسیر مستقیم با شتاب ثابت $2 \\frac{m}{s^2}$ در حال حرکت است. اگر مسافت طی‌شده توسط متحرک در ۱۰ ثانیه ابتدایی حرکت ۵۰ متر باشد، اندازه جابه‌جایی آن در ۲ ثانیه اول حرکت، چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:00:44', 4, 'free'),
(9483, '59-نمودار شتاب - زمان متحرکی که روی محور x حرکت می‌کند، مطابق شکل زیر است. اگر سرعت متحرک در لحظه $t=2s$ برابر $\\vec{v} = -3\\vec{i} (\\frac{m}{s})$ و در لحظه $t\'$ برابر صفر باشد، سرعت متوسط متحرک در بازه‌ای از زمان که در جهت محور x حرکت می‌کند، چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:01:43', 4, 'free'),
(9484, '60-نمودار سرعت - زمان دو خودروی A و B که هم‌زمان از یک نقطه شروع به حرکت می‌کنند، مطابق شکل زیر است. اگر این دو خودرو در لحظه $t\'$ از کنار هم عبور کنند، $t\'$ در SI کدام است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:12:33', 4, 'free'),
(9485, '61-نمودار مکان - زمان متحرکی که روی محور x ها حرکت می‌کند، مطابق شکل زیر است، اگر اختلاف مسافت طی شده و بزرگی جابه‌جایی در ۶ ثانیه اول حرکت ۱۲ متر باشد، متحرک در لحظه $t=12s$ از چه مکانی بر حسب متر عبور می‌کند؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:03:23', 4, 'free'),
(9486, '63-متحرک A و B روی محور x و هم‌زمان با هم، با سرعت‌های ثابت در حال حرکت هستند. متحرک A در ثانیه دوم حرکت از محل $x_1 = -20m$ تا مبدأ جابه‌جا می‌شود و متحرک B در ۴ ثانیه دوم حرکت از نقطه $x\'_1 = 60m$ به مکان $x\'_2 = 20m$ می‌رود. این دو متحرک در چه لحظه‌ای بر حسب ثانیه در یک مکان قرار دارند؟', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:13:23', 4, 'free'),
(9487, '64-در کدام نمودار، بردار سرعت متحرک در خلاف جهت محور x و بردار شتاب در جهت محور x است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:13:59', 4, 'free'),
(9488, '65-با توجه به نمودار مکان - زمان شکل روبه‌رو، کدام‌یک از گزینه‌های زیر درست است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:14:11', 4, 'free'),
(9489, '66-متحرکی با سرعت v بر مسیری مستقیم در حال حرکت است که ناگهان ترمز می‌کند و با شتاب ثابت متوقف می‌شود. اگر جابه‌جایی متحرک در ثانیه دوم و چهارم حرکت کندشونده اش به ترتیب 12 و 14 متر باشد در این صورت جابه جایی متحرک از لحظه گرفتن ترمز تا توقف چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:14:24', 4, 'free'),
(9490, '67- شکل زیر، جابه‌جایی دو متحرک A و B را در ۵ ثانیه اول حرکتشان نشان می‌دهد. اگر این دو متحرک، هم‌زمان از لحظه $t=0$ شروع به حرکت کرده باشند، در چه لحظه‌ای و در چه مکانی از کنار هم عبور می‌کنند؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:15:02', 4, 'free'),
(9491, '68- نمودار سرعت - زمان متحرکی مطابق سهمی شکل زیر است. شتاب متوسط این متحرک در ثانیه پنجم چند $\\frac{m}{s^2}$ است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:15:32', 4, 'free'),
(9492, '69- در شکل زیر، نمودار شتاب - زمان متحرکی که با سرعت اولیه $2 \\frac{m}{s}$ روی خط راست حرکت می‌کند، نشان داده شده است. مسافت پیموده شده توسط متحرک در مدت زمانی که حرکتش کندشونده است، چند برابر مسافت پیموده شده در مدت زمانی است که حرکتش تندشونده است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:26:46', 4, 'free'),
(9493, '70- شکل زیر، نمودار سرعت - زمان متحرکی را نشان می‌دهد که از مکان $x = -21m$ روی خط راست شروع به حرکت می‌کند. تا لحظه‌ای که سرعت متحرک صفر می‌شود، چند ثانیه در حال دورشدن از مبدأ مکان بوده است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:27:43', 4, 'free'),
(9494, '71-نمودار مکان – زمان متحرکی که با شتاب ثابت روی محور x حرکت می‌کند، مطابق شکل زیر است. اگر تندی متحرک در لحظه $t_1$ برابر $12 \\frac{m}{s}$ باشد، مسافت طی شده توسط متحرک در ۱۰ ثانیه ابتدایی حرکت چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:16:42', 4, 'free'),
(9495, '72-قسمتی از نمودار شتاب – مکان متحرکی که روی محور x حرکت می‌کند، مطابق شکل زیر است. اگر متحرک در لحظه $t=0$ از مبدأ مکان با سرعت $10 \\frac{m}{s}$ عبور کند، تا لحظه‌ای که برای بار دوم به مکان $x=10m$ می‌رسد، چند ثانیه حرکتش، کندشونده بوده است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:30:30', 4, 'free'),
(9496, '73- نمودار سرعت – زمان دو متحرک A و B، مطابق شکل زیر است. اگر دو متحرک در مبدأ زمان، از مبدأ مکان عبور کنند، مجموع مسافت طی شده توسط دو متحرک، در بازه زمانی که به یکدیگر نزدیک می‌شوند، چند متر است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:30:58', 4, 'free'),
(9497, '۷۴- نمودار سرعت زمان متحرکی که روی محور $x$ حرکت می‌کند، مطابق شکل زیر قسمتی از یک سهمی است. کدام‌یک از موارد زیر درست است؟\n\nالف) در بازه زمانی $t_1$ تا $t_2$ شتاب متحرک مثبت است.\n\nب) در بازه زمانی صفر تا $t_1$ تندی متحرک در حال کاهش است.\n\nپ) شتاب متوسط در بازه زمانی $t_1$ تا $t_2$ برابر شتاب متوسط در بازه زمانی $t_2$ تا $t_3$ است.\n\nت) در بازه زمانی $t_1$ تا $t_3$ سرعت متوسط متحرک منفی است.', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:19:23', 4, 'free'),
(9498, '۷۵- شکل زیر، نمودار مکان - زمان متحرکی را نشان می‌دهد که روی محور $x$ها حرکت می‌کند. تندی متوسط این متحرک در کدام بازه زمانی بیشتر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:29:47', 4, 'free'),
(9499, '۷۶- متحرکی روی محور $x$ در حال حرکت است. بردار شتاب متوسط این متحرک در بازه زمانی $t_1 = 0s$ تا $t_2 = 10 s$ برابر با $-10 \\vec{i}$ و در بازه زمانی $t_1 = 0s$ تا $t_3 = 20s$ برابر با $-4 \\vec{i}$ است. بزرگی شتاب متوسط آن در ۱۰ ثانیه دوم حرکت‌اش، چند متر بر مجذور ثانیه است؟ (تمامی واحدها در SI هستند.)', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:20:56', 4, 'free'),
(9500, '۷۷- دو متحرک از نقطه‌های $A$ و $B$ با سرعت‌های ثابت، به طرف یکدیگر شروع به حرکت می‌کنند و در نقطه $O$ به یکدیگر می‌رسند. اگر مدت زمانی که متحرک سریع‌تر، از نقطه $O$ به نقطه مقابل خود ($A$ یا $B$) می‌رسد برابر $3s$ باشد، مدت زمان رسیدن متحرک دیگر از نقطه $O$ به نقطه مقابلش ($A$ یا $B$)، چند ثانیه است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:30:24', 4, 'free'),
(9501, '۷۸- نمودار مکان - زمان دو متحرک $A$ و $B$ مطابق شکل زیر است. این دو متحرک چند ثانیه در فاصله کمتر از ۲۰ متری نسبت به‌هم قرار می‌گیرند؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:36:21', 4, 'free'),
(9502, '۷۹- نمودار سرعت زمان متحرکی که بر روی محور $x$ حرکت می‌کند، مطابق شکل زیر است. اگر بزرگی جابه‌جایی متحرک تا لحظه $t_3$ برابر $9/6 m$ باشد، سرعت متوسط متحرک در بازه زمانی $t_1$ تا $t_3$ چند $\\frac{m}{s}$ است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:22:36', 4, 'free'),
(9503, '۸۰- نمودار مکان - زمان متحرکی که روی خط راست و با شتاب ثابت در حال حرکت است، مطابق شکل زیر می‌باشد. اگر تندی این متحرک در مبدأ زمان برابر $10 \\frac{m}{s}$ باشد، مسافت طی شده توسط آن در بازه زمانی $t_1 = 1s$ تا $t_2 = 5s$ چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:38:22', 4, 'free'),
(9504, '۸۱- نمودار سرعت - زمان متحرکی که بر روی خط راست حرکت می‌کند، مطابق شکل زیر است. اگر بزرگی سرعت متوسط این متحرک در بازه زمانی صفر تا $3t$ برابر با $5 \\frac{m}{s}$ باشد، سرعت آن در لحظه $4t$ چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:30:40', 4, 'free'),
(9505, '۸۳- نمودار مکان - زمان متحرکی که روی محور $x$ها در حال حرکت است، مطابق شکل زیر است. در ۶ ثانیه اول حرکت به ترتیب از راست به چپ چند ثانیه بردار مکان متحرک و بردار سرعت متحرک در جهت مثبت محور $x$ ها است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:24:09', 4, 'free'),
(9506, '۸۴- نمودار شتاب - زمان متحرکی که با سرعت اولیه $v_0 = -20 \\frac{m}{s}$ در مبدأ زمان از مبدأ مکان عبور می‌کند، مطابق شکل زیر است. تندی متوسط متحرک در ۲۰ ثانیه اول حرکت چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:40:01', 4, 'free'),
(9507, '۸۵- نمودار سرعت - زمان متحرکی که در مسیر مستقیم با شتاب ثابت حرکت می‌کند، مطابق شکل زیر است. اگر این متحرک در دو ثانیه اول مسافت $d_1$ و در دو ثانیه آخر مسافت $d_2$ را طی کند، $\\frac{d_1}{d_2}$ کدام است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 09:40:29', 4, 'free'),
(9508, '۸۶- متحرک A از حال سکون و از مبدأ مکان با شتاب ثابت $\\frac{4}{9} \\frac{m}{s^2}$ در جهت مثبت محور $x$ شروع به حرکت می‌کند. دو ثانیه بعد، متحرک B با سرعت ثابت از مبدأ مکان در همان جهت می‌گذرد. حداکثر تندی متحرک B چند متر بر ثانیه باشد تا از متحرک A سبقت نگیرد؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:25:37', 4, 'free'),
(9509, '۸۷- نمودار شتاب - مکان متحرکی که در مبدأ زمان از مبدأ مکان با تندی $10 \\frac{m}{s}$ در خلاف جهت محور $x$ ها حرکت می‌کند، مطابق شکل زیر است. مسافت طی شده توسط متحرک از لحظه $t=0$ تا لحظه‌ای که برای دومین بار متوقف می‌شود، چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:25:57', 4, 'free'),
(9510, '۸۸- نمودار مکان - زمان متحرکی که با شتاب ثابت روی محور $x$ حرکت می‌کند، مطابق شکل زیر است. اگر اختلاف تندی متوسط و بزرگی سرعت متوسط در ۱۲ ثانیه ابتدایی حرکت برابر $1 \\frac{m}{s}$ باشد، تندی متحرک در لحظه $t = 12 s$، چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:26:25', 4, 'free'),
(9511, '۸۹- نمودار مکان - زمان متحرکی که بر روی محور $x$ حرکت می‌کند، مطابق شکل مقابل است و خطوط مماس بر نمودار در مبدأ زمان و لحظه $t = 6s$ رسم شده است. با توجه به نمودار می‌توان گفت، تندی متوسط متحرک در مبدأ مکان ... متر بر ثانیه ... از تندی آن در مبدأ زمان است.', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:26:37', 4, 'free'),
(9512, '۹۰- شکل مقابل، نمودار مکان - زمان متحرکی را نشان می‌دهد که بر روی محور $x$ در حال حرکت است. اگر اندازه سرعت متوسط متحرک در ۶ ثانیه اول حرکت برابر $\\frac{2}{3}$ باشد، تندی متوسط آن در این بازه زمانی چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:26:50', 4, 'free'),
(9513, '۹۲- متحرکی روی محور $x$ مطابق اطلاعات جدول زیر از مکان A به مکان B جابه‌جا می‌شود. اگر متحرک در حین جابه‌جایی تنها یک بار تغییر جهت داده باشد، بردار مکان متحرک در لحظه تغییر جهت کدام می‌تواند باشد؟ (تمام یکاها در SI است.)\n\n| بردار مکان A: $+6 \\vec{i}$ | بردار مکان B: $-8 \\vec{i}$ | سرعت متوسط: $-2 \\vec{i}$ | تندی متوسط: $6$ |', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:27:20', 4, 'free'),
(9514, '۹۳- نمودار سرعت - زمان متحرکی که روی محور $x$ در حال حرکت است، مطابق شکل زیر است. در بازه زمانی صفر تا $t_4$، کدام‌یک از عبارت‌های زیر در مورد این متحرک درست است؟\n\nالف) در بازه زمانی ۰ تا $t_1$ بردارهای سرعت متوسط و شتاب متوسط هم‌جهت‌اند.\n\nب) در لحظه $t_2$ جهت حرکت متحرک تغییر می‌کند.\n\nپ) در بازه زمانی $t_1$ تا $t_3$ بردارهای جابه‌جایی و شتاب متوسط خلاف جهت یکدیگرند.\n\nت) در بازه زمانی $t_3$ تا $t_4$ در هر لحظه بردار شتاب لحظه‌ای و بردار سرعت لحظه‌ای با یکدیگر هم‌جهت‌اند.', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:27:58', 4, 'free'),
(9515, '۹۴- نمودار مکان - زمان متحرکی که بر روی خط راست حرکت می‌کند، مطابق شکل زیر است. اندازه شتاب متوسط متحرک در بازه زمانی $t_1 = 3s$ تا $t_2 = 10s$ چند متر بر مجذور ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:28:20', 4, 'free'),
(9516, '۹۵- نمودار مکان - زمان متحرکی که روی محور $x$ حرکت می‌کند، مطابق شکل زیر است. اگر تندی متوسط متحرک در بازه زمانی صفر تا $15s$ برابر $1/8 \\frac{m}{s}$ باشد، بزرگی شتاب متوسط آن در این بازه زمانی چند متر بر مجذور ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:28:38', 4, 'free'),
(9517, '۹۶- نمودار مکان - زمان دو خودروی A و B که بر روی مسیر مستقیم در حال حرکت هستند، مطابق شکل زیر است. اختلاف زمانی بین دو لحظه‌ای که فاصله دو خودرو از یکدیگر $3m$ می‌شود، چند ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:28:48', 4, 'free'),
(9518, '۹۷- دو خودروی A و B به‌ترتیب با سرعت‌های ثابت $50 \\frac{km}{h}$ و $60 \\frac{km}{h}$ از یک نقطه به سمت مقصدی حرکت می‌کنند. اگر اتومبیل B به مدت ۲۰ دقیقه دیرتر از خودرو A شروع به حرکت کند و ۲۰ دقیقه زودتر از آن به مقصد برسد، نقطه شروع حرکت تا مقصد چند کیلومتر است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:29:06', 4, 'free'),
(9519, '۹۸- دو متحرک در مسیر مستقیم، از یک نقطه با سرعت‌های ثابت یکی $15 \\frac{m}{s}$ و دیگری $25 \\frac{m}{s}$ در خلاف جهت هم حرکت می‌کنند. بعد از چند ثانیه فاصله بین آن‌ها به یک کیلومتر می‌رسد؟', 3, 2, 82, 365, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:29:46', 4, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(9520, '۹۹- شکل زیر نمودار مکان - زمان دو متحرک است که بر روی خط راست حرکت می‌کنند. اگر تندی متحرک A نصف تندی متحرک B باشد، معادله مکان - زمان متحرک B در SI کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:30:02', 4, 'free'),
(9521, '۱۰۰- متحرکی روی خط راست و با شتاب ثابت به‌صورت کندشونده، حرکت می‌کند. کدام مورد نمی‌تواند در مورد این متحرک صحیح باشد؟ ($x_0$: مکان اولیه، $v_0$: سرعت اولیه و $a$: شتاب)', 3, 2, 82, 366, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:30:13', 4, 'free'),
(9522, '۱۰۱- بردار مکان متحرکی که با سرعت ثابت روی محور x در حال حرکت است، در دو لحظه $t_1 = 2s$ و $t_2 = 5 s$ در SI به‌ترتیب به‌صورت $10\\vec{i}$ و $4\\vec{i}$ است. این متحرک، چند ثانیه در حال نزدیک شدن به مبدأ مکان است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:30:42', 4, 'free'),
(9523, '۱۰۲- نمودار مکان - زمان متحرکی که بر روی خط راست حرکت می‌کند، به‌صورت سهمی زیر است. تندی در لحظه $t = 12 s$ چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:30:57', 4, 'free'),
(9524, '۱۰۳- نمودار سرعت - زمان متحرکی که بر روی خط راست حرکت می‌کند، مطابق شکل زیر است. این متحرک در مدت زمان حرکت خود، چند متر در خلاف جهت محور x جابه‌جا شده است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 10:55:32', 4, 'free'),
(9525, '۱۰۴- متحرکی با سرعت اولیه $v_0$ و با شتاب ثابت ترمز می‌کند و در مدت $5s$ متوقف می‌شود. نسبت جابه‌جایی این متحرک در ۲ ثانیه اول حرکت به جابه‌جایی آن در ۳ ثانیه انتهایی آن چقدر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 10:56:17', 4, 'free'),
(9526, '۱۰۵- نمودار معادله مکان - زمان متحرکی که روی خط راست و با شتاب ثابت حرکت می‌کند، مطابق شکل زیر است. اگر سرعت متحرک در لحظه $t=4s$ برابر $10 \\frac{m}{s}$ باشد، تندی متوسط آن در ثانیه هفتم حرکت چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:31:51', 4, 'free'),
(9527, '۱۰۶- قطاری به طول $200m$ که در فاصله $100$ متری (فاصله ابتدای قطار تا پل) یک پل به طول $1300m$ ایستاده است، با شتاب ثابت $0/5 \\frac{m}{s^2}$ به طرف پل شروع به حرکت می‌کند و پس از رسیدن تندی آن به $108 \\frac{km}{h}$ با سرعت ثابت به حرکت خود ادامه می‌دهد. از لحظه ورود قطار به پل تا لحظه خروج کامل آن، چند ثانیه طول می‌کشد؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:32:05', 4, 'free'),
(9528, '۱۰۷- متحرکی با شتاب ثابت روی محور $x$ حرکت می‌کند و در مبدأ زمان از مبدأ مکان با تندی $v_0$ عبور می‌کند و در ادامه، در لحظه $t\'$ با تندی $\\frac{v_0}{2}$ در حال نزدیک شدن به مبدأ مکان است. نسبت مسافت طی شده به بزرگی جابه‌جایی در این بازه زمانی چقدر است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 10:57:58', 4, 'free'),
(9529, '۱۰۸- در شکل زیر، نمودار شتاب - زمان متحرکی که از حال سکون روی محور x شروع به حرکت می‌کند، نشان داده شده است. تندی متوسط این متحرک در بازه زمانی صفر تا $25s$، چند $\\frac{m}{s}$ است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 10:58:12', 4, 'free'),
(9530, '۱۰۹- متحرکی با شتاب ثابت روی محور xها در حال حرکت است. کدام‌یک از گزینه‌های زیر در مورد حرکت این متحرک الزاماً صحیح است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:32:36', 4, 'free'),
(9531, '۱۱۰- نمودار مکان - زمان متحرکی که با شتاب ثابت بر روی خط راست حرکت می‌کند، مطابق شکل زیر است. اگر تندی متوسط متحرک در ۱۰ ثانیه اول حرکت $8/5 \\frac{m}{s}$ باشد، تندی متوسط متحرک در بازه زمانی که بردار مکان متحرک در خلاف جهت محور $x$ است، چند متربرثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 10:58:55', 4, 'free'),
(9532, '۱۱۱- اتومبیلی با تندی ثابت $108 \\frac{km}{h}$ در مسیری مستقیم در حال حرکت است که ناگهان راننده با شتاب ثابت ترمز می‌کند و پس از طی مسافت d متوقف می‌گردد. اگر اتومبیل $\\frac{1}{4}$ انتهای مسیر حرکتش را در مدت $4s$ طی کرده باشد، d چند متر است؟ (مسافتی که اتومبیل قبل از گرفتن ترمز طی می‌کند جزو d حساب نمی‌شود.)', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:33:01', 4, 'free'),
(9533, '۱۱۲- نمودار شتاب - زمان متحرکی که روی محور x حرکت می‌کند و سرعت اولیه آن $\\vec{v}_0 = 10 \\frac{m}{s} \\vec{i}$ است، مطابق شکل زیر می‌باشد. اندازه جابه‌جایی متحرک در ۵ ثانیه آخر حرکت چند برابر اندازه جابه‌جایی آن در ۵ ثانیه اول حرکت است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 10:59:40', 4, 'free'),
(9534, '۱۱۳- متحرکی بر روی محور x در حال حرکت است. اگر این متحرک در لحظه $t_1 = 2s$ از مکان $x_1 = 20m$ ، در لحظه $t_2 = 7s$ از مکان $x_2 = -20m$ و سپس در لحظه $t_3 = 17s$ از مکان $x_3 = -10m$ بگذرد، بزرگی سرعت متوسط آن در بازه زمانی $t_1$ تا $t_3$ چند برابر تندی متوسط آن در همین بازه زمانی است؟ (متحرک فقط در لحظه $t_2$ تغییر جهت داده است.)', 3, 2, 82, 365, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:33:46', 4, 'free'),
(9535, '۱۱۴- نمودار مکان - زمان متحرکی که روی خط راست حرکت می‌کند، مطابق شکل زیر است. در بازه صفر تا $12s$، متحرک چند متر در خلاف جهت محور x حرکت کرده است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-18 11:00:44', 4, 'free'),
(9536, '۱۱۵- نمودار مکان - زمان متحرکی که روی خط راست حرکت می‌کند، مطابق شکل زیر است. در مدت ۲ ثانیه اول، جهت حرکت متحرک ......... بار تغییر کرده است و در بازه زمانی ......... علامت سرعت متوسط منفی است.', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:35:15', 4, 'free'),
(9537, '۱۱۶- متحرکی از حال سکون و در جهت محور x شروع به حرکت می‌کند و در لحظه t متوقف شده و بلافاصله شروع به حرکت می‌کند، کدام‌یک از گزینه‌های زیر می‌تواند نمودار مکان - زمان این متحرک را به‌درستی نشان دهد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:35:40', 4, 'free'),
(9538, '۱۱۷- نمودار مکان - زمان متحرکی که بر روی خط راست حرکت می‌کند، به‌صورت زیر است. اگر سرعت متوسط این متحرک در ۱۰ ثانیه اول حرکت برابر با $-1/5 \\frac{m}{s}$ باشد، تندی متوسط آن در این بازه زمانی چند واحد SI است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:35:57', 4, 'free'),
(9539, '۱۱۸- متحرکی روی محور xها در حال حرکت است و در مبدأ زمان سرعت آن $-20 \\frac{m}{s}$ و ۱۲ ثانیه بعد سرعت آن $-15 \\frac{m}{s}$ است. اگر سرعت متوسط متحرک در این بازه زمانی $4/5 \\frac{m}{s}$ باشد، نمودار مکان - زمان آن مطابق کدام گزینه می‌تواند باشد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:36:17', 4, 'free'),
(9540, '۱۱۹- متحرکی بر روی خط راست در حال حرکت است، کدام‌یک از گزاره‌های زیر نادرست است؟\n\nآ) در هر لحظه بزرگی سرعت لحظه‌ای و تندی لحظه‌ای متحرک با هم برابر است.\n\nب) در هر بازه زمانی دلخواه بردار جابه‌جایی هم‌جهت با بردار سرعت متوسط است.\n\nپ) اگر در یک بازه زمانی تندی متحرک صفر نشود بزرگی سرعت متوسط با تندی متوسط در این بازه زمانی برابر است.\n\nت) بردار مکان و بردار سرعت لحظه‌ای در هر لحظه هم‌جهت هستند.', 3, 2, 82, 362, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:36:31', 4, 'free'),
(9541, '۱۲۰- نمودار مکان - زمان متحرکی که روی محور xها در حال حرکت است، مطابق شکل زیر است. اگر بزرگی سرعت متوسط در بازه زمانی $0$ تا $3t\'$، $3 \\frac{m}{s}$ باشد و تندی متوسط متحرک در بازه زمانی که در جهت منفی محور xها در حال حرکت است، ۲۰ درصد کوچک‌تر از تندی متوسط متحرک در بازه زمانی باشد که متحرک در جهت محور xها در حال حرکت است، در این صورت تندی متوسط متحرک در بازه $0$ تا $3t\'$ چند $\\frac{m}{s}$ است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-21 13:36:53', 4, 'free'),
(9542, '۱۲۱- متحرکی در مبدأ زمان از مکان $x_0 = +15m$ عبور می‌کند، و سرعت متوسط آن در ۲۰ ثانیه اول حرکت $-0/5 \\frac{m}{s}$ است. اگر در این مدت فقط دو بار تندی متحرک در لحظات $t_A = 8s$ و $t_B = 14s$ صفر شود و متحرک در این دو لحظه به ترتیب از مکان‌های $x_A = -20m$ و $x_B = -10m$ عبور کند، چند مورد از گزاره‌های زیر در مورد حرکت متحرک در ۲۰ ثانیه اول حرکت صحیح است؟\n\nآ) بردار مکان متحرک دو بار تغییر جهت داده است.\n\nب) جهت حرکت متحرک دو بار تغییر کرده است.\n\nپ) بزرگترین بازه زمانی که متحرک در جهت مثبت محور xها در حال حرکت است، ۶ ثانیه است.\n\nت) تندی متوسط متحرک $2/5 \\frac{m}{s}$ است.', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:31:17', 4, 'free'),
(9543, '۱۲۲- نمودار مکان - زمان متحرکی مطابق سهمی شکل زیر است. تندی متوسط متحرک در کدام بازه زمانی بیشتر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:04', 1, '2026-09-23 18:31:27', 4, 'free'),
(9544, '1- نمودار مکان - زمان متحرکی که روی محور $x$ حرکت می‌کند، مطابق شکل است. در بازه زمانی صفر تا $t_{1}$، اختلاف تندی متوسط متحرک با بزرگی سرعت متوسط آن برابر $7/5 \\frac{m}{s}$ است. لحظه $t_{1}$ برحسب ثانیه کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:38:01', 4, 'free'),
(9545, '2- شکل روبه‌رو، نمودار مکان - زمان متحرکی را نشان می‌دهد که در امتداد محور $x$ در حرکت است. در کل این حرکت، به مدت چند ثانیه فاصله متحرک از مبدأ مکان بیشتر از $20m$ است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:38:16', 4, 'free'),
(9546, '3- نمودار مکان - زمان متحرکی که در امتداد محور $x$ در حرکت است، مطابق شکل است. اگر بزرگی سرعت متوسط آن در بازه زمانی $t=0s$ تا $t=2s$ با بزرگی سرعت متوسط آن در بازه زمانی $t=2s$ تا $t=4s$ به اندازه $2 \\frac{m}{s}$ اختلاف داشته باشد، مکان متحرک در لحظه $t=4s$ کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:38:39', 4, 'free'),
(9547, '4- نمودار روبه‌رو، مربوط به متحرکی است که در امتداد محور $x$ در حرکت است. اگر تندی لحظه‌ای متحرک همواره $8 \\frac{m}{s}$ باشد، بیشترین فاصله متحرک از مبدأ مکان چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:39:20', 4, 'free'),
(9548, '5- شکل روبه‌رو، نمودار مکان - زمان متحرکی را نشان می‌دهد که روی خط راست حرکت می‌کند. در بازه زمانی صفر تا $t_{1}$، به‌ترتیب چند بار جهت حرکت تغییر کرده و چند بار تندی متحرک صفر شده است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:39:32', 4, 'free'),
(9549, '6- نمودار مکان - زمان اتومبیلی که روی خط راست حرکت می‌کند، مطابق شکل است. اگر تندی متوسط اتومبیل در بازه زمانی $t=0s$ تا $t=12s$، $1/2$ برابر تندی متوسط آن در بازه زمانی $t=0s$ تا $t_{1}$ باشد، در کل حرکت، به مدت چند ثانیه تندی اتومبیل در حال افزایش بوده است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:39:54', 4, 'free'),
(9550, '7- راننده خودرویی با تندی ثابت $126 \\frac{km}{h}$ در حرکت است و مانعی را در $100$ متری خود می‌بیند. اگر راننده با $2s$ تأخیر ترمز کند، در لحظه ترمز گرفتن فاصله او تا مانع چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:40:07', 4, 'free'),
(9551, '8- نمودار مکان - زمان دو متحرک که با سرعت ثابت در امتداد محور $x$ حرکت می‌کنند، مطابق شکل است. لحظه $t_{1}$ برحسب ثانیه کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:40:26', 4, 'free'),
(9552, '9- خودرویی فاصله دو شهر را روی خط راست طی می‌کند؛ به‌طوری که ابتدا به مدت $20$ دقیقه با تندی $40 \\frac{m}{s}$ و بقیه مسیر را با تندی $30 \\frac{m}{s}$ می‌پیماید. چنانچه تندی متوسط آن در کل مسیر $32 \\frac{m}{s}$ باشد، کل زمان حرکت خودرو چند دقیقه است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:41:20', 4, 'free'),
(9553, '10- معادله حرکت متحرکی در SI به‌صورت $x = t^{2} - 4t$ است. سرعت متوسط آن در بازه زمانی $2s = t_{1}$ تا لحظه $t_{2}$ که به مکان $x_{2} = 12m$ می‌رسد، چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:41:34', 4, 'free'),
(9554, '11- نمودار سرعت - زمان متحرکی که روی محور $x$ حرکت می‌کند، مانند شکل است. در کدام بازه زمانی، متحرک با تندی در حال افزایش و در خلاف جهت محور $x$ در حرکت است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:41:56', 4, 'free'),
(9555, '12- متحرکی روی محور $x$، در لحظه $t_{1}$ از مکان $x_{1} = 8m$ با سرعت $v_{1} = 5 \\frac{m}{s}$ در حال عبور است و در لحظه $t_{2}$ از مکان $x_{2} = 56m$ با سرعت $v_{2}$ عبور می‌کند. اگر در بازه زمانی $t_{1}$ تا $t_{2}$، سرعت متوسط و شتاب متوسط آن به‌ترتیب $4/8 \\frac{m}{s}$ و $-3 \\frac{m}{s^{2}}$ باشد، سرعت متحرک در لحظه $t_{2}$ چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:42:47', 4, 'free'),
(9556, '13- نمودار سرعت - زمان متحرکی که در امتداد محور $x$ در حرکت است، به شکل زیر است. اگر بزرگی شتاب متوسط متحرک در بازه زمانی $t_1 = 5s$ تا $t_2 = 8s$ برابر با $4 \\frac{m}{s^2}$ باشد، شتاب متوسط متحرک در بازه زمانی $t=0s$ تا $t_1=5s$ چند متر بر مربع ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:42:58', 4, 'free'),
(9557, '14- کدام گزینه در حرکت بر خط راست، نادرست است؟', 3, 2, 82, 362, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:43:16', 4, 'free'),
(9558, '15- شکل داده‌شده، نمودار سرعت - زمان دو متحرک A و B را که روی محور $x$ حرکت می‌کنند، نشان می‌دهد. کدام گزینه نادرست است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:43:37', 4, 'free'),
(9559, '16- متحرکی روی محور $x$ حرکت می‌کند و در لحظه‌های $t_1 = 0s$ و $t_2 = 3s$ به‌ترتیب از مکان‌های $x_1 = 5m$ و $x_2 = 20m$ عبور می‌کند. اگر تندی متوسط متحرک در بازه زمانی $t_1$ تا $t_2$ برابر با $5 \\frac{m}{s}$ باشد، کدام گزینه درست است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:43:59', 4, 'free'),
(9560, '17- شکل زیر، نمودار مکان - زمان متحرکی است که در امتداد محور $x$ حرکت می‌کند. اگر تندی متوسط متحرک در بازه زمانی صفر تا $5s$ برابر با $5 \\frac{m}{s}$ و تندی متوسط آن در بازه زمانی $5s$ تا $15s$ برابر $4 \\frac{m}{s}$ باشد، تندی متوسط متحرک در بازه زمانی صفر تا $15s$، چند متر بر ثانیه است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:44:21', 4, 'free'),
(9561, '18- شکل روبه‌رو، نمودار مکان - زمان اتومبیلی را نشان می‌دهد که در امتداد محور $x$ در حرکت است. تندی‌سنج اتومبیل در کدام بازه زمانی عدد بیشتری از تندی متوسط اتومبیل در بازه زمانی صفر تا $9s$ را نشان می‌دهد؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:44:41', 4, 'free'),
(9562, '19- نمودار سرعت - زمان دو متحرک A و B مطابق شکل است. شتاب متوسط متحرک A در بازه زمانی صفر تا $6s$ برابر با $a_{av_A}$ و شتاب متوسط متحرک B در بازه زمانی صفر تا $4s$ برابر با $a_{av_B}$ است. اگر $a_{av_A} - a_{av_B} = 1/5 \\frac{m}{s^2}$ باشد، سرعت هر دو متحرک در لحظه $t=0s$ چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:44:55', 4, 'free'),
(9563, '20- نمودار سرعت - زمان متحرکی که روی محور $x$ حرکت می‌کند، مانند شکل است. در کدام بازه زمانی حرکت کندشونده بوده و بزرگی شتاب در آن بازه در حال افزایش است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:45:25', 4, 'free'),
(9564, '21- شکل زیر، نمودار مکان - زمان متحرکی است که در امتداد محور $x$ حرکت می‌کند. شتاب متوسط متحرک در بازه زمانی $t_1 = 2s$ تا $t_2 = 4s$ چند متر بر مربع ثانیه است؟ (شیب دو خط رسم شده برابر است.)', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-23 18:31:53', 4, 'free'),
(9565, '22- نمودار سرعت - زمان متحرکی که روی محور $x$ حرکت می‌کند، به‌صورت روبه‌رو است. این متحرک مسافت $27 m$ را در خلاف جهت محور $x$ و مسافت $36 m$ را با تندی ثابت طی می‌کند. سرعت متوسط متحرک در بازه زمانی $t_1 = 0s$ تا $t_2 = 20s$ چند متر بر ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-18 11:20:34', 4, 'free'),
(9566, '23-معادله حرکت سه متحرک $A$، $B$ و $C$ که در امتداد محور $x$ حرکت می کنند، در $SI$ به صورت زیر است. در لحظه ای که دو متحرک $A$ و $B$ به هم می رسند، فاصله آنها تا متحرک $C$ چند متر است؟\n\n$x_A = 5t + 8 \\quad , \\quad x_B = -4t + 44 \\quad , \\quad x_C = 5t - 24$', 3, 2, 82, 365, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:47:29', 4, 'free'),
(9567, '24-متحرکی با شتاب ثابت روی محور $x$ در حرکت است؛ به طوری که در لحظه $t_1 = 2s$ با تندی $10 \\frac{m}{s}$ در خلاف جهت محور $x$ و در لحظه $t_2 = 8s$ با تندی $14 \\frac{m}{s}$ در جهت محور $x$ در حرکت است. در کدام لحظه جهت حرکت متحرک تغییر می کند؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:47:40', 4, 'free'),
(9568, '25-شکل داده شده، نمودار مکان - زمان متحرکی را نشان می دهد که با شتاب ثابت $-4 \\frac{m}{s^2}$ روی محور $x$ در حرکت است. تندی متحرک هنگامی که از مکان $x = 115m$ عبور می کند، چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:47:57', 4, 'free'),
(9569, '26-مطابق شکل، هواپیمایی با تندی $40 \\frac{m}{s}$ در نقطه $O$ روی باند می نشیند و با پیمودن مسافت $160m$ روی سطح افقی، در نقطه $C$ می ایستد. اگر فاصله $AB = 80m$ را در مدت $4s$ طی کند، فاصله $BC$ چند متر است؟ (حرکت هواپیما روی باند با شتاب ثابت است.)', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:48:44', 4, 'free'),
(9570, '27-شکل روبه رو، نمودار مکان - زمان متحرکی را نشان می دهد که با شتاب ثابت روی محور $x$ در حرکت است. شتاب متحرک چند متر بر مربع ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:49:03', 4, 'free'),
(9571, '28-خودرویی پشت چراغ قرمز ایستاده است. با سبز شدن چراغ، با شتاب ثابت $1.5 \\frac{m}{s^2}$ شروع به حرکت می کند و در همین لحظه کامیونی که با سرعت ثابت $54 \\frac{km}{h}$ در حرکت است، از آن سبقت می گیرد. تا قبل از رسیدن خودرو به کامیون، بیشترین فاصله آنها به چند متر می رسد؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:49:19', 4, 'free'),
(9572, '29-شکل زیر، نمودار سرعت - زمان متحرکی است که روی محور $x$ حرکت می کند و جابه جایی متحرک در بازه زمانی $t_1 = 0s$ تا $t_2 = 20s$ برابر با $420m$ است. شتاب متوسط متحرک در بازه زمانی $t_3 = 4s$ تا $t_4 = 14s$ چند متر بر مربع ثانیه است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-18 11:26:16', 4, 'free'),
(9573, '30-نمودار شتاب - زمان متحرکی که در امتداد محور $x$ حرکت می کند، مانند شکل روبه رو است. با فرض $x_0=0$ و $v_0=0$، نمودار مکان - زمان آن در بازه زمانی صفر تا $6s$ کدام است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-23 18:32:27', 4, 'free'),
(9574, '31-نمودار مکان - زمان متحرکی که در امتداد محور $x$ با شتاب ثابت در حرکت است، مانند شکل زیر است. اگر تندی متحرک در لحظه $t=0s$، $4$ برابر تندی متحرک در لحظه $t=12s$ باشد، سرعت متحرک به مدت چند ثانیه در جهت محور $x$ بوده است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:50:31', 4, 'free'),
(9575, '32-خودرویی در لحظه $t=0s$ از حال سکون و با شتاب ثابت روی خط راست به راه می افتد؛ به طوری که در بازه زمانی $t_1=4.5s$ تا $t_2=6.5s$ مسافت $50m$ را طی می کند. تندی خودرو در لحظه $t=2.2s$ چند متر بر ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:50:56', 4, 'free'),
(9576, '33-شکل داده شده بخشی از نمودار مکان - زمان متحرکی است که با شتاب ثابت روی محور $x$ حرکت می کند. در بازه زمانی صفر تا $t_1$، در مدتی که بردار مکان متحرک در خلاف جهت محور $x$ است، متحرک مسافت $48m$ را طی کرده است. فاصله نقطه ای که متحرک تغییر جهت می دهد تا مبدأ مکان چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:51:07', 4, 'free'),
(9577, '34-هواپیمایی با تندی $50\\frac{m}{s}$ روی باند می نشیند و حرکت خود را با شتاب ثابت کند می کند تا بایستد. اگر زمان پیمودن $49$ مترِ آخر حرکت روی باند $7$ برابر زمان پیمودن $49$ مترِ اول حرکت روی باند باشد، کل مسافتی که هواپیما از لحظه نشستن تا توقف کامل پیموده است، چند متر است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:51:19', 4, 'free'),
(9578, '35- نمودار سرعت- زمان متحرکی که با شتاب ثابت روی محور $x$ حرکت می کند، مطابق شکل است. مسافت طی شده توسط متحرک در مدت زمان صفر تا $t_1$ برابر $520m$ است. لحظه $t_1$ برحسب ثانیه کدام است؟', 3, 2, 82, 364, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:52:04', 4, 'free'),
(9579, '36- نمودار شتاب - زمان متحرکی که روی محور $x$ در حرکت است، مطابق شکل است. سرعت متحرک در لحظه های $t_1 = 0s$ و $t_2 = 15s$ به ترتیب برابر با $\\vec{v}_1 = (-8\\frac{m}{s})\\vec{i}$ و $\\vec{v}_2 = (-17\\frac{m}{s})\\vec{i}$ است. شتاب $a_1$ چند متر بر مربع ثانیه است؟', 3, 2, 82, 366, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:52:32', 4, 'free'),
(9580, '37- معادله حرکت متحرکی روی محور $x$، در SI به صورت $x = -5t^2 + 30t - 40$ است. در چه مکانی برحسب متر، تندی متحرک صفر می شود؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:52:45', 4, 'free'),
(9581, '38- مطابق شکل، دوچرخه سواری روی خط راست از نقطه A تا نقطه B را که فاصله آنها $90m$ است، می پیماید و به نقطه C برمی گردد. دونده ای روی همان خط راست از نقطه A تا نقطه C را طی می کند. اگر تندی متوسط دوچرخه سوار $8\\frac{m}{s}$ و اندازه سرعت متوسط دونده $0/8\\frac{m}{s}$ باشد و مدت زمان حرکت دوچرخه سوار نصف مدت زمان حرکت دونده باشد، فاصله نقطه A تا نقطه C چند متر است؟', 3, 2, 82, 365, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-23 18:33:03', 4, 'free'),
(9582, '39- شکل روبه رو، نمودار مکان - زمان متحرکی را نشان می دهد که روی محور $x$ در حال حرکت است. اگر تندی متحرک در بازه های زمانی ($0s-2s$)، ($2s-5s$) و ($5s-t_1$) به ترتیب $10\\frac{m}{s}$، $5\\frac{m}{s}$ و $7\\frac{m}{s}$ باشد، لحظه $t_1$ برحسب ثانیه کدام است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:54:38', 4, 'free'),
(9583, '40- نمودار مکان - زمان دو متحرک A و B که هر یک با سرعت ثابت در حال حرکت هستند، مطابق شکل است. فاصله دو متحرک از یکدیگر در لحظه $t_1$ چند متر است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:54:50', 4, 'free'),
(9584, '41- شکل روبه‌رو، نمودار مکان- زمان متحرکی است که روی محور $x$ حرکت می‌کند. اگر سرعت متوسط متحرک در بازه زمانی صفر تا $2s$ برابر $14 \\frac{m}{s}$ باشد، تندی متوسط متحرک در بازه زمانی صفر تا $5s$، چند متر بر ثانیه است؟', 3, 2, 82, 363, NULL, NULL, NULL, 'آسان', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:55:02', 4, 'free'),
(9585, '42- خودرویی با تندی $32 \\frac{m}{s}$ روی خط راست در حرکت است. راننده مانعی در فاصله $178m$ تا خود می‌بیند و بلافاصله به مدت $3s$ با شتابی به بزرگی $4 \\frac{m}{s^2}$ ترمز می‌گیرد. مسافت باقیمانده تا مانع را باید حداقل با شتابی به بزرگی چند متر بر مجذور ثانیه ترمز بگیرد تا به مانع برخورد نکند؟', 3, 2, 82, 366, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:55:15', 4, 'free'),
(9586, '43- نمودار مکان - زمان متحرکی که روی محور $x$ با شتابی ثابت به بزرگی $0/8 \\frac{m}{s^2}$ حرکت می‌کند، مطابق شکل است. متحرک با چه سرعتی برحسب متر بر ثانیه از مبدأ مکان عبور می‌کند؟', 3, 2, 82, 363, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-03-30 19:23:30', 1, '2026-09-21 13:55:53', 4, 'free'),
