(10415, '۸۴-با توجه به ساختار لولۀ گوارش در انسان، کدام مورد برای تکمیل عبارت زیر مناسب است؟ «هر نوع شیره گوارشی که به فضای درونی لولۀ گوارش وارد می‌شود............»', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10416, '۸۵-براساس مطلب کتاب درسی، شروع یکی از انواع حرکات ایجاد شده در طول لولۀ گوارش بدون دخالت شبکه‌های یاخته‌های عصبی صورت می‌گیرد. کدام گزینه، فقط در خصوص این نوع از حرکات صدق می‌کند؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10417, '۸۶-در نزدیکی دوازدهه، اندام‌های کیسه‌ای شکل وجود دارد که با این قسمت از روده باریک در ارتباط هستند. کدام موارد و ویژگی مشترک این اندام‌ها را نشان می‌دهد؟\n\nالف) بعضی از یاخته‌های جدار آن توانایی ترشح نوعی یون قلیایی را دارند. \n\nب) اندام واردکننده لیپید به آنها، در تماس با مهم‌ترین ماهیچه تنفس قرار دارد. \n\nج) شیره درون آنها فاقد کانالیزورهای زیستی ایجادکنندۀ تک‌پار آمینو اسید است. \n\nد) مواد درون خود را در نیمۀ راست بدن از طریق یک منفذ مجزا به ابتدایی روده باریک می‌ریزند.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10418, '۸۷-با توجه به شیره‌های گوارشی یک فرد سالم، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ «پروتئازهای ترشحی از معده ........... پروتئازهای ترشحی از لوزالمعده ............»', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10419, '۸۸-به طور معمول در دستگاه گوارش انسان، موارد مطرح‌شده در کدام گزینه ممکن نیست به طور هم‌زمان در ارتباط با یک اندام درست باشند؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10420, '۸۹-لایه‌ای از دیوارۀ لولۀ گوارش که در ایجاد حرکت کرمی‌شکل نقش اصلی را ایفا می‌کند، چه مشخصه‌ای دارد؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10421, '۹۰-براساس مطلب کتاب درسی، چند مورد، مشخصه هر نوع مولکول واجد نیتروژن است که توسط لایۀ مخاطی اندام کیسه‌ای شکل لولۀ گوارش، به محیط خارجی بدن ترشح می‌شود؟\n\nالف) برای گوارش شیمیایی مولکول‌های غذا، آب مصرف می‌کند.\n\n ب) مستقیماً تحت اثرد هورمون‌های موجود در خون ترشح می‌شود.\n\n ج) فقط توسط یاخته‌های بافت پوششی غدد دیواره تولید می‌شوند.\n\n د) ابتدا به صورت فعال به فضای درونی این اندام وارد می‌شوند.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10422, '۹۱-در رابطۀ با لولۀ گوارش انسان و اندام‌های مرتبط، کدام مورد درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10423, '۹۲-براساس مطالب کتاب درسی، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ «در هر بخشی از لولۀ گوارش که ............ قابل مشاهده است، ............ نیز یافت می‌شود.»', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10424, '۹۳-در خصوص بزرگ‌ترین ساختاری که در روده باریک، امکان تخریب آن در اثر پروتئین موجود در گندم وجود دارد، کدام مورد درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10425, '۹۴-براساس مطلب کتاب درسی، چند مورد، برای تکمیل عبارت زیر مناسب است؟ به طور معمول، در طی وقوع ............ حرکات دیوارۀ لولۀ گوارش انسان سالم و بالغ، امکان ............ وجود دارد.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10426, '۹۵-هنگام بلع با فشار زبان، تودۀ غذا به عقب دهان و داخل حلق رانده می‌شود. با رسیدن غذا به حلق، در ادامۀ وقوع کدام‌یک از اتفاق‌های زیر غیرممکن است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10427, '۹۶-با توجه به اجزای سازندۀ شکل زیر، کدام مورد درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10428, '97-در خصوص حرکات منظم لوله گوارش، کدام گزینه از نظر درستی یا نادرستی، با سایرین متفاوت است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10429, '98-در بدن انسانی سالم، هر غدۀ بزاقی بزرگ که در سطح .......... نسبت به زبان واقع شده است .......... .', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10430, '100-در خصوص آزمایش اثر آمیلاز بزاق بر نشاسته، کدام مورد یا موارد صحیح است؟\n\nالف: هر لوله‌ای که حاوی آنزیم‌های مختلف است، دارای معرف زردرنگ است. ب: هر لوله‌ای که به آن محلول لوگول اضافه می‌شود می‌توان مشاهده تغییر رنگ آن بود. ج: هر لوله‌ای که در آن نشاسته دیده می‌شود چند دقیقه قبل از آن محلول لوگول به آن افزوده می‌شود. د: هر لوله‌ای که در حمام آب گرم قرار دارد، آنزیم آمیلاز در آن حدی از ساکارید آبکافت می‌کند.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10431, '102-در خصوص گوارش انواع مولکول‌های زیستی، کدام مورد یا موارد زیر صحیح است؟\n\nالف: پپسین ساخته شده در فضای معده، تحت اثر اسید معده، پیوندهای پپتیدی بین آمینواسیدها را می‌شکند. ب: همه کربوهیدرات‌های وارد شده به فضای لوله گوارش، تحت تأثیر آنزیم‌های لوله گوارش، گوارش خواهند یافت. ج: گروهی از کربوهیدرات‌ها می‌توانند در اولین اندام از لوله گوارش به محیط داخلی وارد شوند. د: محل اصلی جذب مواد، در گوارش شیمیایی فراوان‌ترین لیپید رژیم غذایی نقش دارد.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10432, '103-در ابتدایی‌ترین قسمت از لوله گوارش انسان سالم و بالغ، نوعی ماده شیمیایی غیرفعال مشاهده می‌شود که تحت اثر برخی عوامل دیگر به شکل فعال خود تبدیل می‌شود. دربارۀ این ماده شیمیایی، چند مورد صحیح است؟\n\nالف: نقش مهمی در فرایند گوارش شیمیایی گروهی از درشت‌مولکول‌های بدن انسان ایفا می‌کند. ب: به درون محتویات مویرگ‌های خونی اندام ایجادکننده بافت پوششی درون ریز وارد می‌شود. ج: تحت تأثیر ترشحات نوعی یاخته هورمون‌ساز، امکان تولید و ترشح بیشتر آن فراهم می‌شود. د: با واکنش آب‌کافت (هیدرولیز)، مولکول‌های زیستی درشت را به واحد سازندۀ آن تجزیه می‌کند.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10433, '104-چند مورد مشخصه نوعی ترکیب شیمیایی است که فراوان‌ترین لیپید رژیم غذایی انسان محسوب می‌شود؟\n\nالف: بیشتر در اثر فعالیت کاتالیزور زیستی دوازدهه، با مصرف آب تجزیه می‌شود. ب: در یاخته‌های بدن، از سنتز آبدهی یک گلیسرول و سه اسید چرب ایجاد می‌شود. ج: به کمک ساختارهای لوله‌ای یاخته‌های پوششی در ساختار لیپوپروتئین قرار می‌گیرند. د: ترشحات آنزیمی بزرگ‌ترین غده برون‌ریز بدن، در ریز شدن این ترکیبات نقش مهمی دارد.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10434, '105-در خصوص هورمون‌های مترشحه از دستگاه گوارش انسان و اندام‌های سازندۀ آن‌ها، کدام مورد درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10435, '106-در خصوص ساختار بافتی روده باریک، کدام مورد یا موارد صحیح است؟\n\nالف: بافت پیوندی سست زیرمخاط در تماس با بافت پیوندی سست زیرمخاط قرار می‌گیرد. ب: جدا شدن مویرگ لنفی از رگ لنفی بزرگ‌تر از خود، در لایه زیرمخاطی رخ می‌دهد. ج: در قسمت فوقانی بالاترین مویرگ پرز، هسته‌هایی در بافت پیوندی دیده می‌شوند. د: در اطراف یک مویرگ لنفی در هر پرز، شبکه‌های مویرگی خونی دیده می‌شوند.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10436, '107-در خصوص بررسی موقعیت اندام‌های دستگاه گوارش، کدام مورد درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10437, '108-چند مورد، برای تکمیل عبارت زیر مناسب است؟ هر بخش از لوله گوارش یک فرد سالم که در آن .......... ، ممکن است .......... \n\nالف: جذب اصلی مواد غذایی انجام می‌شود – ترکیبات صفرا را دریافت کند. ب: ترشح گلیکوپروتئین موسین آغاز می‌شود – به محرک‌های محیطی پاسخ دهد. ج: تجزیه پروتئین‌ها به آمینواسیدها انجام می‌شود – حاوی پروتئازهای غیرفعال در فضای خود باشد. د: گوارش شیمیایی کربوهیدرات‌ها آغاز می‌شود – با انواعی از حرکات موجب انتقال غذا به روده کور شود. .', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10438, '109-کدام مورد دربارۀ یاخته‌هایی در لایه مخاطی معده که توانایی تولید موسین را دارند، درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10439, '110-شکل زیر، طرح ساده‌ای از گردش خون دستگاه گوارش را نشان می‌دهد. با توجه به شکل و مطالب کتاب درسی، کدام عبارت درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10440, '111-در صورت مصرف طولانی مدت و زیاد نوعی داروی مهارکننده فعالیت یاخته‌های کناری غدد معده، کدام عارضه دور از انتظار است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10441, '112-شکل زیر مجموعه‌ای از مجاری مربوط به دستگاه گوارش را نشان می‌دهد. کدام مورد درباره بخش‌های مشخص شده نادرست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10442, '113-کدام مورد، برای تکمیل عبارت زیر مناسب است؟ «آن دسته از حرکات لوله گوارش که با ایجاد .......... انقباضی در مجاورت توده غذا همراه است، فقط .......... .»', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10443, '114-با توجه به مطالب کتاب درسی درباره مراحل جذب و گوارش مواد در دستگاه گوارش انسان، کدام عبارت درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10444, '115-کدام عبارت، درباره بنداره (اسفنکتر) انتهای مری نادرست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10445, '116-مطابق با اطلاعات کتاب درسی، کدام مورد درباره لیپیدهایی که بیشترین فراوانی را در بین لیپیدهای رژیم غذایی دارند، درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free');
