(10447, '118-چند مورد، ویژگی متمایزکننده بخش انتهایی روده باریک از بخش ابتدایی آن در انسان است؟ الف) ساختاری پر پیچ‌وخم دارد. ب) در نیمه راست بدن قرار دارد. ج) نوعی اتصال با روده بزرگ دارد. د) سیاهرگی مشترک با کولون بالارو تشکیل می‌دهد.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10448, '119-کدام مورد، مشخصه مشترک یاخته‌هایی در غده معده است که به عنوان بزرگ‌ترین یاخته‌های این غده محسوب می‌شوند؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10449, '120-در یک فرد بالغ، در کدام مورد، یاخته‌های دستگاه عصبی خودمختار، نقشی ندارند؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10450, '121-مواد گوناگونی که از یاخته‌های پوششی پرز روده عبور می‌کنند، در نهایت وارد مویرگ‌های پرز می‌شوند. کدام مورد در خصوص همه این مویرگ‌ها درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10451, '122-کدام مورد، برای تکمیل عبارت زیر مناسب است؟ «آن دسته از حرکات لوله گوارش که با ایجاد .......... انقباضی در مجاورت توده غذا همراه است، فقط .......... .»', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10452, '123-کدام گزینه عبارت زیر را به طور درست تکمیل می‌کند؟ «در ساختار یک غده واقع در بخش‌های بالایی معده در فردی سالم، سطحی‌ترین و عمیق‌ترین یاخته‌ها از نظر .......... با یکدیگر شباهت یا از نظر .......... با یکدیگر تفاوت دارند.»', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10453, '124-کدام مورد درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10454, '125-در ارتباط با بدن انسان، کدام گزینه به طور صحیح بیان شده است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10455, '126-در ارتباط با ترشحات دستگاه گوارش، کدام گزینه به طور صحیح بیان شده است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10456, '127-به طور معمول، کدام دو ویژگی، در مورد یکی از لایه‌های دیواره لوله گوارش انسان، درست است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10457, '128-برای تعیین وزن مناسب از نوعی شاخص عددی استفاده می‌شود که نتایج آن در چهار گروه طبقه‌بندی می‌گردد. با توجه به کتاب درسی، در کدام حالت زیر در یک فرد سالم می‌توان در رابطه با سلامتی و وضعیت بدنی شخص بیان داشت که ..........', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10458, '129-با توجه به مفاهیم کتاب درسی، چند مورد درباره همه موادی که می‌توانند در بزرگ‌ترین اندام محوطه شکمی بدن انسان ذخیره شوند، صادق است؟', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10459, '130-انشعاب سیاهرگی شکل مقابل، به طور عمده محتوی خون خروجی از بخشی از لوله گوارش است که در .......... نقش دارد.', 1, 4, 13, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:39', 1, NULL, NULL, 'free'),
(10460, '1-چند مورد، دربارهٔ حمل گازها در خون صحیح است؟\n\nالف: در انتقال بخش عمده‌ای از اکسیژن و کربن دی‌اکسید، گویچه‌های قرمز مؤثر هستند.\n\nب: کربن دی‌اکسید برخلاف اکسیژن، توسط آنزیمی درون گویچهٔ قرمز مصرف می‌شود.\n\nج: حمل کربن دی‌اکسید نسبت به اکسیژن در خون، ارتباط کمتری با هموگلوبین دارد.\n\nد: اکسیژن همانند کربن دی‌اکسید، به‌مقدار اندکی در خوناب (پلاسما) حل می‌شود.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10461, '2-چند مورد، دربارهٔ اعمال دستگاه تنفس انسان به‌درستی بیان شده است؟\n\nالف: در افراد مصرف‌کنندهٔ دخانیات، یاخته‌های مژک‌دار مخاط تنفسی از بین می‌روند.\n\nب: در سرفه همانند بلع، زبان کوچک به سمت بالا حرکت می‌کند.\n\nج: در تکلم، پرده‌های صوتی در شکل‌دهی به صدا نقش دارند.\n\nد: در عطسه برخلاف سرفه، ذرات از بینی خارج می‌شوند.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10462, '3-چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در سراسر قسمت‌های سازندهٔ بخشی از دستگاه تنفس انسان که هوا را به درون و بیرون دستگاه تنفسی هدایت می‌کنند، ...................»\n\nالف: مانعی در برابر ورود ناخالصی‌های هوا دیده می‌شود.\n\nب: یاخته‌های بافت غضروفی در دیواره قابل‌مشاهده هستند.\n\nج: شبکهٔ وسیعی از رگ‌های خونی در گرم‌کردن هوا نقش دارند.\n\nد: یاخته‌های مژک‌داری وجود دارند که مواد ضدمیکروبی ترشح می‌کنند.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10463, '4-با توجه به فعالیت کتاب درسی دربارهٔ تشریح شش گوسفند، چند مورد درست است؟\n\nالف: به‌دلیل ساختار غضروف‌های نایژهٔ اصلی، بریدن نایژهٔ اصلی به‌سادگی بریدن نای نیست.\n\nب: ششی که دارای دو لُپ (لوب) است، قبل از نایژهٔ اصلی، انشعاب دیگری نیز از نای دریافت می‌کند.\n\nج: غضروف‌های موجود در دیوارهٔ نایژهٔ اصلی، در ابتدا به‌صورت حلقهٔ کامل و بعد به‌صورت قطعه‌قطعه است.\n\nد: در مقطع عرضی شش، نوعی سوراخ با لبهٔ غیر زبر که همیشه باز است، مربوط به دهانهٔ نوعی سرخرگ است.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10464, '5-کدام گزینه، عبارت زیر را دربارهٔ مراکز عصبی تنظیم‌کنندهٔ تنفس در انسان، به‌درستی کامل می‌کند؟\n\n«نوعی مرکز عصبی که ................... می‌تواند ...................»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10465, '6- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در واکنش خلاصه‌شدهٔ تنفس یاخته‌ای، فقط یکی از ...................»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10466, '7- با توجه به مطالب کتاب درسی، کدام عبارت، دربارهٔ آزمایشی که به‌منظور مقایسه مقدار نسبی کربن دی‌اکسید در هوای دمی و بازدمی انجام می‌شود، صحیح است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10467, '8- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«مطابق مطالب کتاب درسی، در دستگاه تنفسی نوعی جانور که معدهٔ چهار قسمتی دارد، ...................»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10468, '9- با توجه به مطالب کتاب درسی دربارهٔ آزمایشی که طی آن، بررسی می‌شود که «آیا هوای دمی با هوای بازدمی متفاوت است؟»، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در ظرفی که ................... برخلاف ظرف دیگر، به‌طور حتم ...................»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10469, '10- کدام موارد، دربارهٔ بخش مبادله‌ای دستگاه تنفس درست است؟\n\nالف: باکتری‌هایی که پس از ورود به بخش مبادله‌ای نابود می‌شوند، به‌طور حتم، بیگانه‌خواری شده‌اند.\n\nب: ماده‌ای که در سطح فضای درونی حبابک قرار دارد، ممکن است باز شدن حبابک طی فرایند دم را دشوارتر کند.\n\nج: یاخته‌هایی با ظاهری بسیار متفاوت در دیوارهٔ حبابک، ممکن است در نوزاد تازه متولدشده فعالیت کافی نداشته باشند.\n\nد: حبابکی که به آخرین انشعاب از انشعابات نای متصل است، به‌طور حتم، درون ساختاری شبیه به خوشهٔ انگور قرار دارد.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10470, '11- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«نوعی مولکول گازی که ..........، برخلاف ماده‌ای که از نظر انواع عناصر سازنده با این مولکول گازی متفاوت است و جزء گازهای تنفسی محسوب می‌شود، ..........»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10471, '12- در گروهی از جانوران، تبادل گازی یاخته‌های بدن با محیط اطراف به‌واسطهٔ شش انجام می‌شود. کدام ویژگی، فقط دربارهٔ بعضی از این جانوران صادق است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10472, '13- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در دستگاه تنفسی هر انسان بالغ، ..........»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10473, '14- نمودار مقابل، تهویهٔ ششی در انسانی سالم و بالغ را نشان می‌دهد. با توجه به این نمودار، کدام گزینه صحیح است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10474, '15- کدام گزینه، عبارت زیر را به‌طور مناسب کامل می‌کند؟\n\n«در انسان، نایژهٔ اصلی متصل به شش دارای لوب‌های بیشتر .......... نایژهٔ اصلی متصل به شش دارای لوب‌های کمتر ..........»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10475, '16- درخصوص اصلی‌ترین ساختار عصبی تنظیم‌کننده تنفس در یک فرد سالم، کدام مورد یا موارد زیر درست است؟\n\nالف: نسبت به بخش حاوی مرکز عصبی تنظیم مدت‌زمان دم، قطر کمتری دارد.\n\nب: در ارسال پیام‌های عصبی تحریکی جهت انقباض ماهیچه‌های ناحیه شکمی، ناتوان است.\n\nج: مرکز تنفسی موجود در آن، تنها تحت تأثیر مرکز تنفسی موجود در اندام بالایی خود مهار می‌شود.\n\nد: برای حرکت استخوان جناغ به سمت داخل، با ارسال پیام‌هایی فعالیت انقباضی دیافراگم را مهار می‌کند.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10476, '17- درخصوص یاخته‌های زنده قابل مشاهده در داخل حبابک‌های موجود در بدن فردی سالم، کدام مورد درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10477, '18- مطابق مطالب کتاب درسی، کدام مورد درخصوص نایژه اصلی واردشده به شش قرارگرفته در مجاور قلب، درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10478, '19- مطابق مطالب کتاب درسی، کدام مورد ویژگی مشترک حجم‌های تنفسی که قسمتی از آن‌ها به بخش مبادله‌ای نمی‌رسد را بیان می‌کند؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10479, '20- چند عبارت، جمله زیر را به‌درستی تکمیل می‌کند؟\n\n«در دستگاه تنفسی، ترشحات مخاطی ..........»\n\nالف) دارای مواد ضدمیکروبی هستند.\n\nب) ناخالصی‌های هوا را به دام می‌اندازند.\n\nج) هوای بخش هادی را مرطوب می‌کنند.\n\nد) از یاخته‌های غیرمژک‌دار ترشح می‌شوند.\n\nهـ) تمام قسمت‌های بخش هادی را می‌پوشانند.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10480, '21- کدام گزینه نادرست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10481, '22-کدام عبارت در رابطه با دستگاه تنفس انسان درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10482, '23-تمام قسمت‌های بخش مبادله‌ای .................... تمام قسمت‌های بخش هادی، ....................', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10483, '24-چند مورد هنگام دم می‌تواند رخ دهد؟\n\nالف) گنبدی شدن میان‌بند (دیافراگم)\n\nب) بالا رفتن دنده‌ها\n\nج) حرکت جناغ به جلو\n\nد) انقباض ماهیچه‌های بین‌دنده‌ای داخلی\n\nهـ) مصرف $ATP$ در ماهیچه‌های گردن', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10484, '25-کدام گزینه در ارتباط با حمل گازهای تنفسی در خون انسان درست است؟', 1, 4, 14, 15, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10485, '26-در ارتباط با حجم‌های تنفسی انسان سالم و بالغ می‌توان گفت هر حجم تنفسی که .................... .', 1, 4, 14, 16, NULL, NULL, NULL, 'آسان', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10486, '27-کدام گزینه در رابطه با اعمال دستگاه تنفسی درست است؟', 1, 4, 14, 17, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10487, '28-در مورد دستگاه تنفس انسان کدام گزینه نادرست است؟', 1, 4, 14, 14, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10488, '29-کدام گزینه عبارت زیر را در رابطه با دستگاه تنفس، قطعاً به‌درستی تکمیل می‌کند؟\n\n«در یک فرد سالم و بالغ، زمانی که .................... ، ماهیچه .................... است.»', 1, 4, 14, 16, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10489, '30-کدام گزینه در رابطه با دستگاه تنفس انسان سالم و بالغ، عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n«اکسیژن در دستگاه تنفس انسان .................... و پس از آن .................... .»', 1, 4, 14, 14, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10490, '31-کدام جمله در مورد حجم‌های تنفس در انسان نادرست می‌باشد؟', 1, 4, 14, 16, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10491, '32-با توجه به برش عرضی نای و مری در انسان، چند مورد از موارد زیر نادرست است؟\n\nالف) پراکنش غدد در تمام بخش‌های زیرمخاط تقریباً یکسان است.\n\nب) ممکن است ضخیم‌ترین لایه در نای با شبکه‌ای از پروتئین‌ها و گیلکوپروتئین‌ها تماس داشته باشد.\n\nج) در فاصله بین مخاط دو اندام، سه لایه ماهیچه‌ای و دو شبکه عصبی وجود دارد.\n\nد) در ناحیه نزدیک به قفسه سینه، اغلب، قطر درونی مری از قطر درونی نای کمتر است.', 1, 4, 14, 14, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10492, '33-چند مورد برای کامل کردن جمله زیر نامناسب است؟\n\n«با توجه به ساختار بافتی دیواره نای انسان، به‌طور حتم هر لایه‌ای که .................... .»\n\nالف) در اتصال با بخشی از لوله گوارش قرار دارد، عمدتاً از یاخته‌های غضروفی تشکیل شده است\n\nب) نقش اصلی را در باز نگه داشتن مسیر عبور هوا دارد، در بخش پشتی نرم‌تر از بخش جلویی است\n\nج) در اتصال مستقیم با لایه غضروفی- ماهیچه‌ای قرار دارد، در ساختار خود دارای رشته‌های کلاژن است\n\nد) دارای یاخته‌های مژک‌دار است، یاخته‌های آن در تماس مستقیم با هوای عبوری قرار می‌گیرند', 1, 4, 14, 14, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10493, '34-کدام گزینه جمله زیر را به‌درستی تکمیل می‌کند؟\n\n«در انسان در نوعی عمل تنفسی که .................... می‌شود، همواره .................... .»', 1, 4, 14, 16, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
