(10515, '56- در خصوص حجم و ظرفیت‌های تنفسی، کدام مورد، برای تکمیل عبارت زیر، نامناسب است؟\n\n«به طور معمول، در یک انسان بالغ و سالم، حجمی از هوا که پس از یک ..................... میزان ..................... است.»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10516, '57- با توجه به این‌که دستگاه تنفس شامل دو بخش عملکردی است، کدام گزینه زیر را فقط می‌توان ویژگی «بخشی که از مجاری تنفسی تشکیل شده است و هوا را به درون و بیرون دستگاه تنفسی هدایت می‌کند.»، دانست؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10517, '58- با توجه به مراکز تنفسی مطرح‌شده در کتاب درسی، کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\n«هر مرکز عصبی تنفس موجود در ساقهٔ مغز که طی تنفس آرام و طبیعی، ..................... .»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10518, '59- کدام عبارت در خصوص ماهیچه‌های اسکلتی شرکت‌کننده در دم و بازدم عمیق، درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10519, '60- کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«در ریهٔ حجیم‌تر انسان، آن دسته از یاخته‌های دیوارهٔ حبابک که واجد ..................... نسبت به دیگر یاخته‌های دیواره هستند، به طور حتم، ..................... .»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10520, '61- باتوجه‌به‌این‌که بیماری «سندروم زجر تنفسی بزرگسالان» دراثر آسیب یاخته‌های دیوارهٔ کیسهٔ حبابکی وشبکهٔ مویرگی اطراف آن‌هارخ می‌دهد،مطابق با اطلاعات کتاب درسی،کدام موارد زیر می‌تواند از نتایج تخریب یاخته‌هایی از دیوارهٔ حبابک‌های ریوی در انسان باشد که زوائدی ریزی در سطح خود دارند؟\n\nالف) تغییر شکل آنزیم‌های مؤثر در انجام تنفس یاخته‌ای         ب) کاهش میزان همهٔ حجم‌های تنفسی در دم‌نگاره (اسپیروگرام) فرد\n\nج) تغییر میزان فعالیت پایین‌ترین مرکز تنفسی، در واحد زمان       د) کاهش قابل ملاحظهٔ میزان ظرفیت تام شش‌های فرد', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10521, '62- با توجه به شکل مقابل، کدام عبارت صحیح است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10522, '63- در خصوص جابه‌جایی و انتشار گازهای تنفسی در خون و شبکه‌های مویرگی بدن، همه موارد زیر صحیح است؛ به جز:', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10523, '64- با توجه به شکل مقابل که اسپیروگرام آقایی 50 ساله و سیگاری را نشان می‌دهد، کدام عبارت، به طور درست بیان شده است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10524, '65- در خصوص ساختار بخش‌های عملکردی دستگاه تنفس در یک فرد سالم و بالغ، کدام مورد نادرست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10525, '66- شکل روبه‌رو نمودار اسپیروگرام یک مرد بالغ و سالم را نشان می‌دهد. با توجه به این موضوع کدام مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«نقطهٔ D از نظر ..................... به نقطهٔ ..................... شباهت و با نقطهٔ ..................... تفاوت دارد.»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10526, '67- در ارتباط با فرایند تنفس، کدام گزینه صحیح بیان شده است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10527, '68- در خصوص نخستین مجرای هادی در دستگاه تنفس انسان سالم و بالغ که به درون شش کوچکتر وارد می‌شود، چند مورد صادق نیست؟\n\nالف: دارای حلقه‌های غضروفی کامل در تمام طول دیوارهٔ خود است.\n\nب: توسط یاخته‌های لایهٔ سطحی خود چند مادهٔ ضد میکروبی می‌سازند.\n\nج: در سطحی بالاتر از شیار(های) بین لوب‌های درون این شش، منشعب می‌شود.\n\nد: می‌تواند در پی فعالیت ماهیچهٔ ناحیهٔ گردن، به ورود هوا به داخل ریه کمک نماید.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10528, '69- در خصوص نمودار دم‌نگاره (اسپیروگرام) یک فرد سالم و بالغ، کدام مورد نادرست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
