(10530, '71- در حبابک‌های موجود در شش‌های انسان، آن دسته از یاخته‌های بالغ و فعالی که می‌توانند از لبهٔ کناری خود در تماس با مولکول‌های هوا باشند، به طور حتم دارای کدام ویژگی هستند؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10531, '72- با توجه به شکل مقابل که نتیجه نوعی آزمایش تنفسی در یک مرد جوان را نشان می‌دهد، در رابطه با بخش ......... در این نمودار، می‌توان گفت .........', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10532, '73- در خصوص مقایسه یاخته‌های موجود در دیواره حبابک، کدام مورد، درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10533, '74- فرایندهای تهویه ششی توسط انواعی از ماهیچه‌های اسکلتی انجام می‌شود. کدام مورد در ارتباط با این فرایندها و ماهیچه‌های مؤثر در آن، برای تکمیل عبارت زیر مناسب است؟\n\n«در انسان، در نوعی فرایند تهویه ششی که .....................، به‌طور حتم .....................»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10534, '75- درباره مراحل انجام تنفس در یک فرد سالم و بالغ، کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«به طور معمول هم‌زمان با ......... حجم قفسه سینه، به طور حتم ......... رخ می‌دهد.»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10535, '76- کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«در ریه بزرگ‌تر انسان سالم و بالغ، یاخته‌هایی از دیواره حبابک‌ها که .........»', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10536, '77- کدام گزینه درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10537, '78- با در نظر گرفتن کل اجزای سازنده بخش هادی دستگاه تنفسی انسان، کدام مشخصه، فقط درباره ابتدای این بخش صادق است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10538, '79- کدام مورد، درباره پروتئینی که گویچه قرمز سرشار از آن می‌باشد، درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10539, '80-در یک نمونه تهیه شده از شش گوسفند و مجاری تنفسی آن، مری نیز وجود دارد. اگر شش ها را طوری در دست بگیریم که نای رو به بالا باشد و مری دیده نشود، کدام مورد درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10540, '81-با توجه به شکل زیر که بخشی از اسپیروگرام یک فرد سالم و بالغ را نشان می دهد، کدام عبارت درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10541, '82-بخش مبادله ای دستگاه تنفسی انسان با حضور اجزایی کوچک مشخص می شود. کدام مورد، مشخصه همه این اجزا را به درستی بیان می کند؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10542, '83-با توجه به نقش دو نوع ماهیچه بین دنده ای در فرایندهای تهویه ششی، کدام مورد، به طور حتم درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10543, '84-مطابق مطالب کتاب درسی درباره آزمایش مربوط به مقایسه هوای دمی و بازدمی، اگر انتهای کوتاه لوله مرکزی در ظرف «$1$» و انتهای بلند آن در ظرف «$2$» قرار داشته باشد و فردی سالم از طریق لوله مرکزی نفس بکشد، کدام مورد به طور حتم درست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10544, '85-با توجه به مطالب کتاب درسی درباره حجم ها و ظرفیت های تنفسی و با در نظر گرفتن دم و بازدم های متوالی یک انسان بالغ، وقوع چند مورد در فرد سالم، امکان پذیر نیست؟\n\nالف: حجم هوایی که وارد دستگاه تنفسی می شود، از حجم جاری بیشتر و از حجم ذخیره دمی کمتر باشد.\n\nب: در یک دم و بازدم متوالی، ماهیچه های گردنی منقبض نشوند اما ماهیچه های شکمی منقبض شوند.\n\nج: بدون انجام حداکثر بازدم، کل هوای درون شش ها تخلیه شود و شش ها کاملاً جمع شوند.\n\nد: پس از انجام حداکثر دم، دم بعدی قبل از خروج حجم ذخیره بازدمی آغاز شود.', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10545, '86-کدام گزینه نادرست است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10546, '87-کدام گزینه در خصوص تشریح شش گوسفند صادق است؟', 1, 4, 14, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10547, '88-با توجه به اسپیروگرام فردی سالم و بالغ، کدام گزینه، عبارت زیر را به درستی تکمیل می کند؟ «همزمان با رسم بخش .....................، ......................... از نظر انقباض یا استراحت ماهیچه های موثر در تنفس، وضعیت ....................... با وضعیت ........................ دارد.»', 1, 4, 14, 16, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10548, '89-کدام موارد، وجه شباهت چهارمین لایه از خارج را در ساختار بافتی دیواره اندام های لوله ای شکل و طویلی که با حفره دهانی انسان در ارتباط هستند، بیان می کند؟', 1, 4, 14, 14, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10549, '90- یکی از ششهای دختری سالم و بالغ، دارای لوبی در ساختار خود است که نسبت به سایر لوبهای هر دو شش، کیسه های حبابکی بیشتری دارد. انشعابی از نای که وارد این لوب میشود درمقایسه با انشعاب ورودی به شش سمت مقابل بدن، چه مشخصه ای دارد؟', 1, 4, 14, 14, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10550, '91- کدام مورد در خصوص حجم های تنفسی، عبارت زیر را به درستی تکمیل می کند؟\n\n«برای ........................... هوای متعلق به ........................... ششهای فرد لازم است تا ...........................»', 1, 4, 14, 16, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10551, '92- شکل مقابل بخشی از اسپیروگرام یک فرد سالم و عادی است. کدام گزینه در ارتباط با شکل به درستی بیان شده است؟', 1, 4, 14, 16, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10552, '93- کدام گزینه، در ارتباط با یک انسان سالم برای تکمیل عبارت زیر نامناسب است؟\n\n«به منظور ........................... حجم قفسه سینه انسان در یک تنفس عادی، لازم ...........................»', 1, 4, 14, 16, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:25:51', 1, NULL, NULL, 'free'),
(10553, '1- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در ................... مویرگ هایی وجود دارند که ...................»', 1, 4, 15, 22, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10554, '2- چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«ماهیچه های قلب با رگ های ویژه ای تغذیه می شوند که ...................»\n\nالف: از بالای دریچه سینی سرخرگ آئورت منشعب شده اند.\n\nب: نیازهای تنفسی و غذایی همه یاخته های پوششی دیواره قلب را نیز برطرف می کنند.\n\nج: پس از رفع نیاز یاخته های قلبی، به صورت یک سیاهرگ به دهلیز راست متصل می شوند.\n\nد: رسوب کلسترول لیپوپروتئین کم چگال (LDL) در دیواره آن ها، عملکرد آن ها را مختل می کند.', 1, 4, 15, 19, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10555, '3- کدام عبارت، درباره شکل مقابل صحیح است؟', 1, 4, 15, 20, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10556, '4- کدام عبارت، درباره صداهای قلب انسان درست است؟', 1, 4, 15, 19, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10557, '5- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«با توجه به شکل مقابل، هنگامی که پیام الکتریکی مربوط به انقباض یاخته های ماهیچه ای در بخش ................... قرار دارد، برخلاف زمانی که پیام الکتریکی مربوط به انقباض یاخته های ماهیچه ای در بخش C قرار دارد، ...................»', 1, 4, 15, 20, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10558, '6- چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول در بدن انسان، از بین رگ های خونی که سه لایه مختلف در دیواره خود دارند، آن هایی که ...................، نسبت به نوع دیگر رگ های خونی که اندازه مشابهی دارند، ...................»\n\n1) حفره داخلی بزرگ تری دارند - در برش عرضی، بیشتر گرد دیده می شوند.\n\n2) در قسمت های عمقی هر اندام قرار گرفته اند - مقاومت کمتری در برابر جریان خون دارند.\n\n3) حتی در نبود خون نیز دهانه ای باز دارند - حجم بیشتری خون را درون خود جای می دهند.\n\n4) دریچه های یک طرفه کننده جریان خون را دارند - لایه ماهیچه ای و پیوندی نازک تری دارند.', 1, 4, 15, 22, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10559, '7- کدام عبارت، درباره ساختار بافتی قلب انسان درست است؟', 1, 4, 15, 19, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10560, '8- در دوران جنینی انسان، اندام های مختلفی می توانند یاخته های خونی را تولید کنند. چند مورد، فقط درباره ساختار و عملکرد بعضی از این اندام ها در انسان بالغ، درست است؟\n\nالف: خون سیاهرگی آن ها به طور مستقیم به سمت قلب نمی رود.\n\nب: در از بین بردن میکروب های بیماری زا و یاخته های سرطانی نقش دارند.\n\nج: گیرنده پیک شیمیایی تولیدشده توسط گروه ویژه ای از یاخته های کلیه را دارند.\n\nد: در مجاورت مویرگ های خونی آن ها، درشت خوارها به پاکسازی گویچه های قرمز مرده می پردازند.', 1, 4, 15, 21, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10561, '9- شکل مقابل، سطحی از قلب گوسفند را نشان می دهد. چند مورد از ویژگی های زیر، این سطح از قلب را از سطح دیگر آن متمایز می سازد؟\n\nالف: سطح آن نسبتاً صاف و تخت است.\n\nب: اغلب رگ های کرونری آن حامل خون روشن هستند. \n\nج: رگ های کرونری آن به صورت عمودی طی مسیر می کنند.\n\nد: در فاصله کمتری نسبت به استخوان جناغ سینه قرار دارد.', 1, 4, 15, 19, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10562, '10- کدام مورد، درباره فردی که دومین عمل موفقیت آمیز پیوند قلب مصنوعی در ایران روی وی انجام شد، نادرست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10563, '11- چند مورد درباره قلب انسان درست است؟\n\nالف: دریچه سینی سرخرگ ششی نسبت به دریچه سه لختی، پایین تر است.\n\nب: در بطن چپ نسبت به بطن راست، تعداد طناب های ارتجاعی کم تر است.\n\nج: قسمت پایینی دیواره بین بطنی نسبت به قسمت بالایی آن، ضخیم تر است.\n\nد: تعداد منافذ سیاهرگی دهلیز چپ دو برابر منافذ سیاهرگی دهلیز راست است.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10564, '12- در سطحی از قلب انسان که به استخوان جناغ سینه نزدیک تر است، سرخرگ های کرونری وجود دارند. کدام گزینه، برای تکمیل عبارت زیر درباره این سرخرگ ها درست است؟\n\n«سرخرگی که به صورت کاملاً مستقیم طی مسیر می کند، ................... سرخرگی که به صورت مایل طی مسیر می کند، ...................»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10565, '13- کدام عبارت، درباره ساختارهای نشان داده شده در شکل مقابل درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10566, '14- چند مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«در دیواره قلب یک انسان بالغ، ................... رشته های کلاژنی که ...................»\n\nالف: همه - در بافت متصل به بافت پوششی قرار دارند، جزء برون شامه یا پیراشامه هستند.\n\nب: همه - در لایه ماهیچه قلب قرار دارند، به تمام یاخته های ماهیچه ای این لایه متصل هستند.\n\nج: فقط بعضی از - در دیواره قلب وجود دارند، در بافتی هستند که در تماس مستقیم با یاخته های سنگفرشی است.\n\nد: فقط بعضی از - در نزدیکی مایع محافظت کننده از قلب هستند، قسمتی از بافت پیوندی متراکم می باشند.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10567, '15-در ارتباط با یاخته‌های ماهیچه‌ای که در اندام‌های حفره قفسه سینه و یا دیواره جلویی آن وجود دارند، کدام عبارت درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10568, '16-با توجه به شکل زیر که نوار قلب یک انسان سالم را نشان می‌دهد، کدام عبارت، درباره نقاط مشخص‌شده در شکل درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10569, '17-کدام عبارت، درباره دستگاه گردش خون انسان نادرست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10570, '18-کدام عبارت، درباره اجزایی از خون که در نتیجه قطعه‌قطعه‌شدن مگاکاریوسیت‌ها تولید می‌شوند، درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10571, '19-کدام موارد، به مشخصه مشترک گره‌های شبکه هادی قلب در فردی سالم و بالغ، به‌درستی اشاره می‌کنند؟\n\nالف: با چهار دسته‌تار از شبکه هادی ارتباط دارند.\n\nب: یاخته‌هایی با یک یا دو هسته و ظاهر منشعب دارند.\n\nج: تحت تأثیر پیام‌های ارسال‌شده از پایین‌ترین بخش مغز قرار می‌گیرند.\n\nد: در دیواره پشتی حفره‌ای از قلب قرار گرفته‌اند که ضخامت دیواره آن از بالا به پایین افزایش می‌یابد.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10572, '20-کدام مورد یا موارد زیر، فقط در یک مرحله از چرخه ضربان قلب مشاهده می‌شوند؟\n\nالف: کاهش فشار خون در بطن‌های چپ و راست\n\nب: امکان تماس خون با قطعات دریچه‌های سینی\n\nج: کشیده‌بودن طناب‌های ارتجاعی موجود در بطن‌ها\n\nد: هدایت پیام در بخش‌های پس از گره کوچک‌تر در شبکه هادی', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10573, '21-مطابق با مطالب کتاب درسی، کدام مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«شکل ................. در یک انسان سالم و بالغ، .................»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10574, '22-هر رگی که خون خود را به بزرگ‌ترین اندام تولیدکننده اریتروپویتین وارد می‌کند، دارای چه مشخصه‌ای است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10575, '23-با توجه به مطالب کتاب درسی در یک انسان سالم و بالغ، چند مورد زیر نادرست است؟\n\nالف: یاخته (ب) نوعی یاخته ایمنی است که در حال بیگانه‌خواری عامل بیگانه می‌باشد.\n\nب: فرایند نشان داده‌شده در یاخته (ب)، در پلاسما به وقوع می‌پیوندد.\n\nج: یاخته (الف)، در تشکیل بخش یاخته‌ای خون فاقد نقش است.\n\nد: در مسیر تولید یاخته (الف)، دو نوع یاخته بنیادی فعالیت دارند.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10576, '24-مطابق با مطالب کتاب درسی در ارتباط با دستگاه گردش خون بدن انسان، کدام مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«از بین رگ‌هایی که در دیواره خود سه لایه دارند، آن‌دسته از رگ‌هایی که ............................، به‌طور حتم ............................»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10577, '25-مطابق شکل زیر که نوار قلب فردی سالم را نشان می‌دهد، کدام مورد، درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10578, '26-در بدن یک انسان سالم و بالغ، اندام‌هایی وجود دارند که به‌طور مستقیم غلظت اوره موجود در خون را تغییر می‌دهند. کدام مورد، فقط درخصوص برخی از این اندام‌ها درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10579, '27-درخصوص مقایسه لایه‌های تشکیل‌دهنده دیواره قلب، کدام مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«به‌طور معمول در بدن انسان، ............................ یاخته‌های لایه‌ای از قلب که ............................ .»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10580, '28-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«بخشی از یک لایه دیواره قلب انسان که ............................ است، به‌طور حتم، ............................ .»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10581, '29-مشاهده کدام مورد در بدن یک انسان بالغ، غیرممکن است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10582, '30-در شکل زیر، محدوده‌های مختلفی از منحنی نوار قلب یک انسان سالم (در حالت استراحت) نشان داده شده است. با توجه به شکل، کدام عبارت درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10583, '31-چند عبارت جمله زیر را به‌درستی تکمیل می‌کند؟\n\n«به‌طور معمول، اگر یک شخص سالم به ارتفاعات صعود کند ............................ »\n\nالف) در بدن او مصرف فولیک اسید و آهن افزایش می‌یابد.\n\nب) میزان تولید اریتروپویتین از کبد و کلیه افزایش می‌یابد.\n\nج) تقسیم یاخته‌های بنیادی در مغز استخوان افزایش می‌یابد.\n\nد) میزان خون بهر فرد کاهش می‌یابد.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10584, '32-یاخته‌های ماهیچه قلبی ............................ یاخته‌های ماهیچه ............................', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10585, '33-کدام عبارت در مورد قلب انسان نادرست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10586, '34-در یک ضربان قلب مدت زمانی که خون به بطن راست وارد می‌شود با مدت زمان ............................ برابر است.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10587, '35- کدام گزینه جهت تکمیل عبارت زیر رابطه با یک انسان سالم مناسب است؟\n\n«نقطه ............ در نوار قلب روبه‌رو می‌تواند بیانگر ............ باشد.»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10588, '36- در انسان، همه رگ‌هایی که خون قلب را به سمت بافت‌های مختلف بدن هدایت می‌کنند، چه مشخصه‌ای دارند؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10589, '37- کدام گزینه در رابطه با مجاری لنفی درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10590, '38- کدام گزینه جمله زیر را به‌نادرستی کامل می‌کند؟\n\n«تمام انواع گویچه‌های سفید که ............»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10591, '39- در رابطه با شبکه هادی قلب، کدام عبارت درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10592, '40- کدام گزینه در مورد یاخته‌های خونی انسان، درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10593, '41- مطابق شکل‌های کتاب درسی، وقتی یکی از سرخرگ‌های کرونری به دو شاخه منشعب می‌شود، یکی از شاخه‌هایش بلافاصله در مجاورت نوعی دریچه قلبی دوباره منشعب می‌شود؛ کدام عبارت در ارتباط با این دریچه صدق می‌کند؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10594, '42- به‌طور طبیعی در ............ مرحله از چرخه ضربان قلب انتظار می‌رود که ابتدا ............ و سپس ............ شود.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10595, '43- کدام مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«هر مرحله‌ای از چرخه فعالیت قلب انسان سالم که در آن ............ می‌یابد، از نظر وضعیت دریچه ............ با نقطه ............ تفاوت دارد.»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10596, '44- در یک فرد بالغ به‌دنبال ............ به ترتیب می‌توان انتظار ............ را داشت.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10597, '45- چند مورد درباره هر مویرگ خونی در بدن انسان درست است؟\n\nالف) بخشی از مواد خارج شده از آن بلافاصله به خوناب باز می‌گردد.\n\nب) اکسیژن مورد نیاز را به بافت وارد و کربن دی‌اکسید را از آن دور می‌کند.\n\nج) در بخش میانی آن، فشار تراوشی خون از فشار اسمزی خوناب بیشتر است.\n\nد) تمام بخش‌های غشای هر یاخته پوششی آن، در تماس با غشای پایه قرار دارد.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10598, '46- کدام مورد برای تکمیل عبارت زیر مناسب نیست؟\n\n«با توجه به فصل 4 کتاب زیست دهم، (در) نوعی مویرگ خونی که فاصله زیاد بین یاخته‌های پوششی آن به‌صورت حفره‌هایی در دیواره مویرگ دیده می‌شود، ............ نوعی مویرگ خونی که منافذ فراوانی در غشای یاخته‌های پوششی خود دارد، ............ .»', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10599, '47- شکل روبه‌رو بخش‌های خون پس از گریزانه را نشان می‌دهد. کدام موارد با توجه به شکل درست است؟\n\nالف) بخش B برخلاف بخش A در حمل گازهای تنفسی دخالت دارد.\n\nب) در صورت آسیب به یاخته‌های دارای ریزپرز جدار حبابک، بخش B افزایش می‌یابد.\n\nج) در صورت آسیب به درشت‌ترین یاخته‌های غدد معدی، بخش B افزایش می‌یابد.\n\nد) در صورت شنیده شدن صداهای غیرعادی از قلب ممکن است حجم بخش B بیشتر از 45 درصد شود.', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10600, '48- کدام مورد در ارتباط با متوقف کردن خروج خون از بخش به‌شدت آسیب‌دیده دیواره سرخرگ انسان صدق نمی‌کند؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10601, '49- اندامی در انسان توانایی تبدیل ماده‌ای معدنی به آلی را دارد. این اندام جزء دستگاه گوارش محسوب می‌شود، اما جزء لوله گوارش نیست. کدام گزینه در مورد آن درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free'),
(10602, '50- کدام گزینه در مورد وضعیت دریچه‌های قلبی در طی چرخه کار طبیعی یک فرد بالغ درست است؟', 1, 4, 15, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:29:53', 1, NULL, NULL, 'free');
