(10749, '44- نخستین اندام از دستگاه دفع ادرار انسان که هم ادرار تولیدشده در کلیه راست و هم ادرار تولیدشده در کلیه چپ را دریافت می‌کند، چه مشخصه‌ای دارد؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10750, '45- در گردیزه‌های انسان، با ورود مایع تراوش شده به لوله پیچ‌خورده قبل از قوس هنله، ابتدا کدام اتفاق قبل از سایرین رخ می‌دهد؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10751, '46- کدام گزینه را در رابطه با گردش خون بخش های گوناگون گردیزه (نفرون) در یک انسان سالم با قاطعیت میتوان بیان داشت؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10752, '47- کدام مورد، برای تکمیل عبارت زیر مناسب است؟ «در بدن هر انسان، کیسه ماهیچه‌ای ذخیره‌کننده ادرار با ............... مرتبط است که ...............»', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10753, '48- مطابق با مطالب کتاب درسی، کدام مورد، برای تکمیل عبارت زیر، نامناسب است؟ «هر یاخته موجود در بخشی از گردیزه که به عنوان یاخته واجد ............... شناخته می‌شود.»', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(10754, '49- چند مورد برای تکمیل عبارت مقابل مناسب است؟ «نوعی بافت پیوندی محافظت کننده کلیه که ............... می‌تواند.\n\nالف) در برابر ضربه به آن محافظت می‌کند- فضای بین یاخته‌ای زیادی داشته باشد\n\nب)در حفظ موقعیت کلیه نقش مهمی دارد-در یاخته های اصلی خود،هسته مرکزی داشته باشد\n\nج) در ماده زمینه‌ای خود، رشته‌های پروتئینی فراوانی دارد - از کلیه چپ بیشتر از کلیه راست محافظت می‌کند\n\nد) به طور مستقیم به بخش قشری لپ های کلیه متصل است - در فرورفتگی‌های سطحی کلیه، وجود داشته باشد', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10755, '50- کدام گزینه، برای تکمیل عبارت زیر، مناسب است؟ در انسان، کلیه راست همانند کلیه چپ .................. و بر خلاف آن .................. .', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10756, '51- کدام مورد برای تکمیل عبارت زیر مناسب است؟ با توجه به مطالب کتاب درسی درباره مراحل تشکیل ادرار، ...................مراحل تشکیل ادرار که .................. .', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10757, '52- با در نظر گرفتن اولین و آخرین بخش لوله‌ای شکل گردیزه، کدام مورد یا موارد زیر، فقط در مورد اولین بخش صحیح است؟\nالف) بیشترین مقدار پیچ‌خوردگی را دارد.\n ب) یاخته‌های مکعبی و تک هسته‌ای در دیواره خود دارد.\nج) به مجرای مرتبط کننده گردیزه‌ها به یکدیگر، اتصال دارد.\nد) مقدار مواد مفید واردشده از آن به مویرگ‌های دور لوله‌ای بیشتر است.', 1, 4, 16, 29, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10758, '53- کدام مورد، مشخصه منحصربه‌فرد مرحله‌ای از تشکیل ادرار است که در جهت مخالف با بازجذب و در بخش‌های مختلفی از گردیزه (نفرون) انجام می‌شود؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10759, '54- در خصوص سیاهرگ کلیه‌ای که نسبت به کلیه دیگر بالاتر است، کدام مورد به‌درستی بیان شده است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10760, '55- در خصوص دو نوع ساختار شبیه به قیف در کلیه انسان سالم، کدام عبارت صحیح است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10761, '56- با توجه به مطلب کتاب درسی، کدام مورد در ارتباط با ساختار نفرون (گردیزه) درست است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10762, '57- با فرض اینکه رگ واردکننده خون به کلافک را «A» و رگ خارج‌کننده خون از آن را «B» در نظر بگیریم، کدام عبارت درست است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10763, '58- کدام مورد برای تکمیل عبارت زیر مناسب است؟ مطابق اطلاعات کتاب درسی در ارتباط با دستگاه دفع ادرار، در نیمه‌ای از بدن انسان که «.................»', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10764, '59- کدام مورد مشخصه‌ی اندامی در بدن انسان را که در هم‌ایستایی نقش اساسی داشته و به حفظ تعادل آب و اسید-باز می‌پردازد، به درستی نشان می‌دهد؟\n\nالف- بازجذب مواد از ادرار را در بخشی آغاز می‌نماید که در یاخته‌های آن، میتوکندری‌ها عمود بر غشا هستند\n\nب- رگ با خون تیره که در جلوی میزنای قرار گرفته است، حاوی مقادیر زیادی از ترکیبات دفعی نیتروژن‌دار می‌باشد\n\nج- در برش طولی اندام ، تیره ترین بخش آن می‌تواند در قسمت‌هایی در مجاورت روشن‌ترین بخش اندام قرار بگیرد\n\nد- به دنبال افت تنفس در فرد،یاخته هایی در بخش قشری اندام،ترشح نوعی یون به درون گردیزه ها را افزایش میدهد', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10765, '60-چند مورد از عبارت زیر را بطور کامل مناسب نمی‌کند؟ در بدن یک فرد سالم، فراوان ترین ماده تشکیل دهنده ادرار همواره بلافاصله پس از خروج از .................... به بخشی وارد می‌شود که .................... \n\nالف) لگنچه - با عبور از روی انشعابات آئورت، ادرار را به بخش پشتی و بالایی مثانه وارد می‌کند. \n\nب) گردیزه - با چندین گردیزه مختلف در ارتباط بوده و قطر آن از بالا به پایین افزایش می یابد. \n\nج) میزنای - با داشتن بنداره ای از نوع ماهیچه صاف،مانع بازگشت ادرار به میزنای میشود \n\nد) مجرای جمع کننده – مشابه قیف بوده و انشعاباتی از رگ های کلیوی از آن عبور می نماید.', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10766, '61- شکل روبه‌رو بخشی از ساختارهای مرتبط با تنظیم اسمزی در گوسفند را نشان می‌دهد. با توجه به این شکل می‌توان گفت بخش ............... معادل بخشی در بدن انسان است که ..................', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10767, '62-در انسان، یکی از بخش های لوله ای سازنده گردیزه(نفرون) ها، فاقد پیچ خوردگی های متعدد در ساختار خود است. کدام گزینه در خصوص این بخش به درستی بیان شده است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10768, '63-کدام مورد برای تکمیل عبارت زیر مناسب است؟ فرایند تشکیل ادرار در بدن انسان شامل سه مرحله است. با توجه به این موضوع می‌توان گفت به دنبال وقوع هر مرحله ای که .................. دور از انتظار نیست.', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10769, '64-در خصوص ترکیب شیمیایی ادرار، کدام موارد زیر نادرست است؟\n\n الف: فراوان‌ترین ماده تشکیل‌دهنده ادرار، در بیشتر موارد به‌صورت غیرفعال در کلیه بازجذب می‌شود. \n\nب: فراوان‌ترین ماده آلی تشکیل‌دهنده ادرار، در صورت رسوب در مفاصل، باعث بیماری نقرس می‌شود. \n\nج: ماده دفعی آلی ساخته شده در کبد، از تجزیه موادی مانند آمینواسید ساخته شده و بسیار سمی است. \n\nد: ماده دفعی نیتروژن‌داری که انحلال‌پذیری اندکی در آب دارد، از ترکیب آمونیاک و کربن دی‌اکسید ساخته می‌شود.', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10770, '65-در خصوص مراحل تشکیل ادرار تا تخلیه آن در فرد بالغ و سالم، کدام مورد محتمل است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10771, '66-در خصوص فرایندهای تشکیل ادرار در انسان، کدام مورد برای تکمیل عبارت زیر مناسب است؟ «به طور معمول، در هر مرحله‌ای از فرایند تشکیل ادرار که .................»', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10772, '67-کدام مورد برای تکمیل عبارت زیر مناسب است؟ «به طور معمول، در کلیه انسان، بخشی که در سمت ................. هر هرم کلیه قرار دارد، .................»', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10773, '68-هر کلیه از حدود یک میلیون ساختار تشکیل شده است که فرایند تشکیل ادرار در آن‌ها انجام می‌شود. در خصوص بخش‌های مختلف در این ساختار، کدام مورد درست است؟', 1, 4, 16, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10774, '69-در خصوص عوامل بیرونی محافظت‌کننده از کلیه‌ها در یک انسان سالم و بالغ، کدام مورد درست است؟', 1, 4, 16, 27, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10775, '70-کدام گزینه در مورد انسان، برای تکمیل عبارت زیر مناسب است؟ «به طور معمول نوعی ماده زائد نیتروژن‌داری که .................»', 1, 4, 16, 30, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10776, '71- کدام موارد تنها در ارتباط با برخی از عوامل حفاظت کننده از اندام‌های لوبیایی شکل بدن انسان به درستی بیان شده است؟ الف) یاخته هایی با هسته کشیده بین رشته های کلاژن دارد. ب) توانایی ترشح ماده زمینه ای و رشته های پروتئینی دارد. ج) به عنوان عایق و ضربه‌گیر در برابر ضربات شدید، عمل می‌کند. د) در عدم  تاخوردگی مجرای میزراه نقش دارد.', 1, 4, 16, 27, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10777, '72- کدام عبارت، در ارتباط با گردش خون کلیه‌ها در یک فرد سالم و بالغ، درست است؟', 1, 4, 16, 28, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10778, '73- کدام عبارت درباره لوله‌هایی در کلیه که در تشکیل ادرار نقش دارند، درست است؟', 1, 4, 16, 28, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10779, '74- کدام عبارت در خصوص تنظیم توازن آب و یون‌ها در بدن انسان، درست است؟', 1, 4, 16, 30, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10780, '75- فرایند تشکیل ادرار شامل سه مرحله است. کدام گزینه ویژگی منحصر به فرد مرحله ای است که بعضی سموم و داروها به وسیله آن دفع می شوند؟', 1, 4, 16, 29, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10781, '76- کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«هر ساختاری از دستگاه دفع ادرار در انسان که ................. نیازمند است، ................. .»', 1, 4, 16, 30, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10782, '77- درباره نوعی آنزیم در بدن انسان که کربن دی اکسید را با ماده ای غیر آلی ترکیب می کند، چند مورد، به طور حتم صحیح است؟\n\nالف: ژن آن در یاخته های بنیادی ساخته می شود.\n\nب: تجمع پیش ماده آن در خون خطرناک است.\n\nج: فراورده این آنزیم، نوعی ترکیب آلی است.\n\nد: در یاخته های هسته دار فعالیت می کند.', 1, 4, 16, 30, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10783, '78- ساختارهایی در اطراف کلیه های انسان وجود دارند که وظیفه محافظت از کلیه ها را برعهده دارند. مشخصه مشترک این ساختارها چیست؟', 1, 4, 16, 27, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10784, '79- در یک فرد بالغ، پس از فعال شدن سازوکار تخلیه ادرار، کدام اتفاق بعد از سایرین رخ می دهد؟', 1, 4, 16, 30, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10785, '80- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در برش طولی کلیه انسان، هر بخشی که ................... است، به طور حتم، ...................»', 1, 4, 16, 27, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10786, '81- با توجه به شکل مقابل که مربوط به بخشی از دستگاه دفع ادرار فردی سالم است، چند مورد درست است؟\n\n\n\nالف: بخش «1» و «4»، نسبت به بخش «3»، مقدار بیشتری اوره دارند.\n\nب: بخش «2» و «3»، نسبت به بخش «1»، ماهیچه صاف کمتری دارند.\n\nج: بخش «1» و «3»، همانند بخش «4»، ماهیچه صاف در دیواره خود دارند.\n\nد: بخش «2» و «3»، برخلاف بخش «4»، مایعی دارای گلوکز را حمل می کنند.', 1, 4, 16, 27, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10787, '82- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در برش طولی ساختار کلیه سه بخش قابل مشاهده است. هر بخش که در تماس با دو بخش دیگر است ...................»', 1, 4, 16, 28, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10788, '83- به منظور انجام ................... مرحله از فرایند تشکیل ادرار، (در) همه یاخته های مؤثر در این فرایند، ...................', 1, 4, 16, 29, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10789, '84- کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«مطابق با کتاب درسی، عوامل مختلفی از کلیه ها محافظت می کنند. نوعی عامل که ................... به طور حتم ...................»', 1, 4, 16, 27, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:30:36', 1, NULL, NULL, 'free'),
(10790, '1- چند مورد، ویژگی مشترک همۀ دیسه (پلاست)های موجود در گیاه سیب زمینی را به درستی بیان می کند؟\n\nالف: تعداد آنها در یاخته ها در طول حیات گیاه متغیر است.\n\nب: حاوی ترکیبات رنگی است که خاصیت پاداکسندگی (آنتی اکسیدانی) دارند.\n\nج: در فضای محصور شده توسط غشای درونی خود، دنا (DNA) دارند.\n\nد: در سامانۀ بافت زمینه ای، فقط در بعضی از یاخته های بافت پارانشیمی وجود دارند.', 1, 4, 17, 33, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10791, '2- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در صورت رنگ آمیزی یاخته های بافت های مختلف گیاهی با رنگ های آبی متیل و کارمن زاجی، دیوارۀ همۀ یاخته هایی که ........................... می شود.»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10792, '3- کدام عبارت، دربارۀ رشد پسین گیاه آلبالو درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10793, '4- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در یک یاختۀ گیاهی، فقط ......................... »', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10794, '5- کدام عبارت، دربارۀ شکل مقابل که مربوط به یک گیاه نهاندانه می باشد، درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10795, '6- با توجه به مطالب کتاب درسی، چند مورد، دربارۀ سازوکارهای رشد در گیاه انجیر معابد، درست است؟\n\nالف: تشکیل استوانه هایی شامل یاخته های آوندی غیرزنده، نقش اصلی را در رشد قطری ساقه دارد.\n\nب: آوندهای چوبی که بیشترین فاصله را تا یاخته های سطحی دارند، در سال اول رشد گیاه تشکیل شده اند.\n\nج: نوعی یاختۀ مریستمی که در یک سمت خود یاختۀ پارانشیمی می سازد، در سمت مقابل نیز یاخته های زنده می سازد.\n\nد: یاخته هایی که لیگنین ساخته و به دیوارۀ خود اضافه می کنند، توسط مریستم های واقع در سامانۀ بافت زمینه ای ساخته می شوند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10796, '7- چند مورد، ویژگی مشترک یاخته های همۀ لایه های بافتی است که در تشکیل پوست درخت آلبالو نقش دارند؟\n\nالف: همواره توسط نوعی مریستم پسین ساخته شده اند.\n\nب: سلولز را به طور غیریکنواخت به دیوارۀ خود اضافه کرده اند.\n\nج: اکسیژن را از طریق برآمدگی های سطح ساقه دریافت می کنند.\n\nد: جزئی از سامانۀ بافت پوششی اندام مسن گیاه محسوب می شوند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10797, '8- در خصوص یاخته های فاقد پروتوپلاست در گیاهی تک لپه، کدام مورد درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10798, '9- با توجه به مقایسۀ میان گیاهان تک لپه و دولپه هم قطر، کدام مورد به تشخیص گیاهی که مقدار پوست بیشتری در ریشۀ خود دارد، از گیاه دیگر کمک می کند؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10799, '10- مطابق با تصویر مقابل که بخشی از گیاه ذرت را ترسیم کرده است، کدام گزینه درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10800, '11- مطابق با تصویر کتاب درسی در فصل 6 زیست شناسی دهم، کدام ویژگی، یاختۀ گیاهی دارای سبزدیسه (کلروپلاست) را از یاختۀ گیاهی دارای رنگ دیسه (کروموپلاست)، متمایز می سازد؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10801, '12- کدام گزینه، عبارت زیر را به درستی کامل می کند؟\n\n«به طور معمول در نوعی گیاه دولپه ای، تراکئیدهای موجود در ساقه، با یاخته های ........................... از نظر ........................... مشابه و از نظر ........................... متفاوت هستند.»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10802, '13- کدام موارد، درخصوص ترتیب و زمان استفاده از مواد لازم برای رنگ آمیزی بافت های آوندی درست است؟\n\nالف: استفاده از محلول رنگ بر (1 تا 2 دقیقه)\n\nب: استفاده از کارمن زاجی (20 دقیقه)\n\nج: استفاده از استیک اسید رقیق (1 تا 2 دقیقه)\n\nد: استفاده از آبی متیل (15 تا 20 دقیقه)', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10803, '14- درخصوص مقایسۀ مریستم های پسین یافت شده در ریشۀ درخت انجیر، کدام عبارت نادرست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10804, '15- مطابق مطالب کتاب درسی، چند مورد برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، در ........................... نوعی گیاه نهان دانۀ علفی و تک لپه، هر سامانۀ بافتی که ........................... دارای یاخته هایی است که ........................... »\n\nالف: ریشۀ ـ فضای اطراف بافت آوندی را پر می کند ـ در دیوارۀ خود لان های منشعب دارند\n\nب: ساقۀ ـ یاخته هایی با سبزدیسۀ فراوان دارد ـ در ترمیم زخم یا جلوگیری از ایجاد آن نقش دارند\n\nج: ریشۀ ـ ساختاری ستاره ای شکل را در مرکز این اندام ایجاد می کند ـ دیوارۀ عرضی خود را از دست می دهند\n\nد: ساقۀ ـ در تشکیل پوست ضخیم بین دسته های آوندی و روپوست شرکت می کند ـ در نوعی سامانۀ بافتی دیگر وجود دارند', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10805, '16- پس از رنگ آمیزی برش های عرضی تهیه شده از ساقه و ریشۀ گیاهان تک لپه ای و دو لپه ای، کدام عبارت، دربارۀ تصاویر مشاهده شده در زیر میکروسکوپ نوری درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
