(10820, '31- کدام گزینه در رابطه با بخشی از گیاه که عملکردی مشابه پوست در جانوران دارد، قطعا درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10821, '32- چند مورد درباره درخت انجیر معابد به درستی بیان شده است؟\n\nالف) ممکن است یک ساقه افقی، چند ساقه عمودی را به هم متصل کرده باشد.\n\nب) امکان مشاهده حفرات بزرگ هوا در بخش های زمینی و هوایی آن وجود ندارد.\n\nج) برای انجام رشد قطری، دارای یاخته مریستمی می شوند.\n\nد) در بخش خارجی روپوست ساقه های جوان آن می توان یاخته هایی زنده و بلند یافت.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10822, '33- در رابطه با دیواره همه یاخته های گیاهی چند مورد یا موارد قطعا درست است؟\n\nالف) در منطقه لان کانال هایی پر از سیتوپلاسم دیده می شود.\n\nب) رشته های سلولز در لایه مجاور تیغه میانی به صورت رشته های موازی دیده می شود.\n\nج) در نزدیک ترین لایه به غشای یاخته ای تراکم رشته های سلولزی بیشتر از دورترین لایه است.\n\nد) پایه گذاری لان همانند پلاسمودسم، هم زمان با تشکیل دیواره است.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10823, '34- مرکزی ترین یاخته در برش عرضی ..................... ، ..................... .', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10824, '35- کدام موارد برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، گیاهی با رگبرگ های منشعب ..................... گیاهی با رگبرگ های موازی ..................... .»\n\nالف) برخلاف - در منطقه مرکزی ریشه دارای یاخته های عناصر آوندی است\n\nب) برخلاف - می تواند در لایه درون پوست (آندودرم) دارای یاخته های معبر باشد\n\nج) نسبت به - تعداد دستجات آوندی کمتری در بخش ساقه دارد\n\nد) همانند - در روپوست زیرین برگ دارای یاخته های تمایزیافته سبزدیسه کلروپلاست دار است', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10825, '36- کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول ..................... یاخته های برگ گیاه ذرت، ..................... .»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10826, '37- در گیاهان نهان دانه، برخی از یاخته های تمایزیافته روپوستی برگ با عملکرد خود سبب تبادل گازهای تنفسی با محیط اطراف خود می شوند. چند جمله در مورد این یاخته ها درست است؟\n\nالف) آرایش شعاعی رشته های سلولزی دیواره یاخته ای از افزایش قطری این یاخته ها جلوگیری می کند.\n\nب) افزایش فشار اسمزی درون این یاخته ها سبب افزایش تعرق در گیاه می شود.\n\nج) افزایش طولی این یاخته ها در پی انباشت ترکیبات آلی و معدنی، درون یاخته صورت می گیرد.\n\nد) با استفاده از فسفات معدنی و واکنش انتقال الکترون ها، ATP می سازند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10827, '38- در گیاهان نهان دانه، سامانه بافتی که فضای بین روپوست و بافت آوندی را پر می کند از سه نوع بافت تشکیل شده است. ویژگی مشترک یاخته های این سه نوع بافت در کدام گزینه به درستی بیان شده است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10828, '39- کدام مورد، عبارت زیر را به درستی کامل می کند؟\n\n«در گیاهی که لپه، مواد غذایی درون دانه (آندوسپرم) موجود در دانه بالغ را به رویان منتقل می کند، ..................... .»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10829, '40- کدام مورد عبارت زیر را به درستی کامل می کند؟\n\n«گیاهی که ..................... .»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10830, '41- کدام گزینه از ویژگی مشترک همه مریستم هایی است که در افزایش قطر ریشه و ساقه گیاهان دولپه ای نقش اصلی را برعهده دارند؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10831, '42- گروهی از گیاهان، بیشترین گیاهان روی زمین محسوب می شوند و توانسته اند پهنه وسیعی از زمین را به خود اختصاص دهند. چند مورد را نمی توان به همه اعضای این گروه نسبت داد؟\n\nالف) هم زمان با کاهش طول روز، بر مقدار کاروتنوئیدهای آن افزوده می شود.\n\nب) تبدیل مریستم رویشی به مریستم زایشی در آن ها به طول روز و شب بستگی دارد.\n\nج) بخش عمده جذب کاروتنوئیدهای موجود در سبزدییسه آن ها در بخش آبی و سبز نور مرئی صورت می گیرد.\n\nد) کربن دی اکسید مورد نیاز خود را عمدتا از طریق یاخته های تمایزیافته اندام های هوایی جذب می کنند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10832, '43- با توجه به مطالب ذکر شده در کتاب درسی زیست شناسی دهم، هر یاخته در گیاهان علفی نهان دانه که در بیش از یک سامانه بافتی دیده می شود، به طور حتم چه ویژگی دارد؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10833, '44- با توجه به شکل های زیر کدام یک از گزینه های زیر به طور درست بیان شده است؟\n\n«شرایطی که در طی آن، یاخته ها در بافت گیاهی با آرایشی مشابه شکل ..................... قرار می گیرند، .....................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10834, '45- مطابق با مطالب کتاب درسی، «نوعی اندامک گیاهی، سبب قرمز شدن ریشه چغندر قرمز شده و نوعی اندامک دیگر در زرد یا نارنجی شدن ریشه هویج نقش دارد.» کدام عبارت فقط درباره یکی از انواع این اندامک ها صدق می کند؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10835, '46- چند مورد، در ارتباط با بخشی از یاخته گیاهی که ساختار لان را تشکیل می دهد، درست است؟\n\nالف) با بخشی از یاخته که دارای فسفولیپیدهای فراوان می باشد، در تماس است.\n\nب) با بخشی از یاخته که دارای کلسترول است، در کنترل تبادل مواد همکاری می کند.\n\nج) علاوه بر پکتین، ترکیباتی دارد که در از بین بردن عوامل بیماری زا نقش ایفا می کنند.\n\nد) علاوه بر مولکول های چسب مانند، پلی ساکاریدی در تیغه میانی دارد که در کاغذسازی به کار می رود.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10836, '47- با توجه به شکل مقابل که قسمتی از نوعی گیاه علفی را نشان می دهد، می توان بیان داشت که یاخته های نشان داده شده با شماره..................... از نظر ..................... دارد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10837, '48- با توجه به سه سامانه بافتی گیاهی مطرح شده در کتاب زیست شناسی دهم، کدام مورد را تنها می توان منحصر به یکی از این سه سامانه بافتی نسبت داد؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10838, '49- کدام گزینه عبارت زیر را به درستی تکمیل می کند؟\n\n«نوعی مریستم در ساختار گیاه آکاسیا ........................ ، این مریستم می تواند ........................ »', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10839, '50- کدام گزینه در ارتباط با گیاه خرزهره، نادرست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10840, '51- با توجه به مطالب کتاب درسی دهم، هر گیاه نهان دانه علفی جوانی که ........................ است، در ریشه خود ........................ دارد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10841, '52- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، ........... مریستم هایی که در تشکیل ساقه ها و ریشه هایی با قطر بسیار زیاد در بعضی از نهاندانگان نقش دارند، ........... خود، یاخته هایی تولید می کنند که ........... »', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10842, '53- کدام گزینه ویژگی محیطی ترین یاخته های موجود در یک دسته آوندی در ریشه گیاه آلبالو را به درستی بیان می کند؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10843, '54- چند مورد یاخته های زنده بالغ موجود در سامانه بافتی زمینه ای در گیاهان نهان دانه علفی را از یکدیگر متمایز می کنند؟\n\nالف: کربوهیدرات های منشعب غشا با کربوهیدرات های دیواره تماس دارند.\n\nب: یاخته هدف عامل رشد تولیدی در محل آسیب بافت گیاهی است.\n\nج: غشا و دیواره یاخته ای آن به صورت چند ضلعی آرایش یافته اند.\n\nد: انواعی اندامک دو غشایی در مرکز پروتوپلاست وجود دارد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10844, '55- کدام گزینه عبارت زیر را به طور مناسب تکمیل می کند؟\n\n«به طور معمول در پیکر گیاه ذرت، هر یاخته ای که .................. »', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10845, '56- به طور معمول، در یک یاخته گیاهی کدام گزینه عبارت زیر را به طور صحیح کامل می نماید؟\n\n« هر لایه ای در حد فاصل بین غشای دو یاخته گیاهی واجد دیواره پسین و مجاور هم که .................. »', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10846, '57- یکی از ویژگی های بعضی از یاخته های گیاهی وجود اندامکی است که دارای نوعی شیره است و بیشتر حجم یاخته را اشغال می کند و در یاخته های پارانشیمی ذخیره کننده مواد نقش مهمی دارد. کدام موارد زیر از وظایف این اندامک گیاهی محسوب می شود؟\n\nالف) جذب آب به منظور رشد یاخته گیاه علفی طی تورژسانس\n\nب) ذخیره کاروتنوئید پاداکسنده کاروتن در یاخته های ریشه هویج\n\nج) ذخیره نوعی ترکیب رنگی با قابلیت تغییر رنگ به دنبال تغییر pH\n\nد) ذخیره ترکیب پروتئینی موثر در رشد دانه جو و گندم و موثر در بروز سلیاک', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10847, '58- کدام گزینه در ارتباط با ضخیم‌ترین بخش از پوست ساقه یک درخت 4 ساله صحیح است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10848, '59- با در نظر گرفتن مطالب مربوط به سازش گیاهان در مناطق گوناگون در فصل 6 زیست 1 ، می‌توان گفت که یکی از شرایط ................. است.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10849, '60- مطابق با اطلاعات کتاب درسی، کدام مورد فقط درباره بعضی از یاخته‌های مریستمی نهاندانگان که بعد از تشکیل ساختار نخستین گیاه به وجود می‌آیند صادق است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10850, '61- در ارتباط با نوعی اندامک در یاخته‌های گیاهی که سبب استوار ماندن اندام‌های علفی گیاه می‌شود، کدام عبارت، صحیح است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10851, '62- نوعی دیسه (پلاست) گیاهی که هنگام مشاهده با میکروسکوپ نوری، به رنگ ................. دیده می‌شود، ................. .', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10852, '63- در ارتباط با یکی از ترکیبات گیاهی که در شیرابه بعضی از گیاهان به فراوانی یافت می‌شود، چند مورد، صحیح است؟\n\nالف: همه آن‌ها در دفاع از گیاهان در برابر گیاه‌خواران، نقش دارند\n\nب: همه آن‌ها، در جلوگیری از تقسیم بی‌رویه و سریع یاخته‌های بدن، نقش دارند.\n\nج: فقط بعضی از آن‌ها، در کاهش تولید پیام عصبی در نوعی گیرنده حس پیکری، نقش دارند.\n\nد: فقط بعضی از آن‌ها، در افزایش تولید دوپامین توسط یاخته‌های سامانه کناره‌ای مغز، نقش دارند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10853, '64- چند مورد، برای تکمیل عبارت زیر، مناسب است؟\n\n«در ساقه هوایی یک گیاه چوبی، هر سامانه بافتی که محتوای یاخته‌های .................... است، ....................»\n\nالف: سبزینه‌دار - در ذخیره مواد، دارای نقش اصلی است.\n\nب: چوبی شده - سبب استحکام و انعطاف‌پذیری می‌شود.\n\nج: پارانشیمی - یاخته‌های سبزینه‌دار در آن مشاهده می‌شود.\n\nد: دارای صفحه آبکشی - در ترابری شیره خام دارای نقش است.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10854, '65- در گیاه آلبالو، سامانه‌های بافتی تشکیل‌دهنده پیکر گیاه که ویژگی‌های آن‌ها در عبارت زیر آمده است، به ترتیب از راست به چپ در یاخته‌های تشکیل‌دهنده خود دارای چه ویژگی‌هایی هستند؟\n\n«تأمین اکسیژن موردنیاز برای گیاهان آبزی + داشتن عملکردی مشابه با پوست جانوران + حضور در مرکز ریشه گیاه گوجه‌فرنگی + تشکیل توده یاخته‌ای در محل آسیب به تنه گیاه»\n\nالف - نفوذپذیری یاخته‌ها نسبت به آب\n\nب - تثبیت کربن‌دی‌اکسید CO2 جو\n\nج- داشتن لان ستاره‌ای شکل در ساختار خود\n\nد - داشتن سیتوپلاسم مشابه با گویچه‌های قرمز', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10855, '66- در خصوص مقاطع عرضی ریشه و ساقه گیاهان گل‌دار فاقد رشد پسین، چند مورد، عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در گیاهانی با ....................، مریستم ....................»\n\nالف) پوست ریشه ضخیم‌تر - چوب‌پنبه‌ساز به سمت خارج، یاخته‌هایی را می‌سازد که دیواره آن‌ها به‌تدریج چوب‌پنبه‌ای می‌شود.\n\nب) ساقه متشکل از دستجات آوندی منظم بر روی یک دایره - نخستین در ریشه، سبب افزایش طول و عرض این اندام می‌شود.\n\nج) تراکم دسته‌های آوندی بیشتر در بخش خارجی ساقه - آوندساز، به شکل حلقه‌ای میان آوند چوبی و آبکش قرار می‌گیرند.\n\nد) ساقه‌ای واجد پوست نازک - نخستین ساقه، حاوی یاخته‌هایی است که بخش اعظم حجم سلولی آن‌ها را هسته تشکیل می‌دهد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10856, '67- در خصوص کامبیوم‌های یک گیاه دولپه‌ای و چوبی، کدام مورد درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10857, '68- کدام مورد، برای تکمیل عبارت زیر، مناسب است؟\n\n«نوعی یاخته گیاهی که .................. است، .................. نوعی یاخته از سامانه بافتی .................. پروتئین ها را با بهره گیری از منافذ هسته در دو طرف آن جابه جا می کند.»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10858, '69- کدام مورد، برای تکمیل عبارت زیر، نامناسب است؟\n\n«به طور معمول، در یک درخت پنج ساله، .................. فقط بعضی از یاخته های بافت زمینه ای، ..................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10859, '70- در خصوص یاخته هایی از سامانه بافت پوششی گیاه که حاصل تمایز در یاخته های این سامانه هستند، چند مورد نادرست است؟\n\nالف: فقط یکی از آن ها، در تأمین مواد معدنی مورد نیاز گیاه نقش مؤثر دارد.\n\nب: همه آن ها، نسبت به یاخته های روپوستی مجاور خود، اندازه بزرگ تری دارند.\n\nج: در برگ، همه آن ها هم سطح با یاخته های سازنده پوستک لیپیدی قرار دارند.\n\nد: در برگ، فقط یکی از آن ها، در سبزدیسه های خود کاروتنوئید نگهداری می کند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10860, '71- مطابق با اطلاعات کتاب درسی، چند مورد نادرست است؟\n\nالف: پلاستیک برای اولین بار از شیرابه نوعی گیاه نهان دانه ساخته شد.\n\nب: جانوران برخلاف گیاهان، برای تأمین انرژی از جایی به جایی دیگر می روند.\n\nج: در بعضی گیاهان، با کاهش نور محیط، مساحت بخش های سبز افزایش می یابد.\n\nد: در شیرابه بعضی گیاهان ماده اعتیادآوری وجود دارد که در درمان سرطان مؤثر است.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10861, '72- مطابق با اطلاعات فصل 6 کتاب درسی دهم، چهار نوع یاخته از سامانه بافت زمینه ای مطرح شده است. کدام مورد فقط در خصوص برخی از این یاخته ها درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10862, '73- مطابق مطالب کتاب درسی، کدام مورد فقط درخصوص یکی از لایه های تشکیل دهنده دیواره یاخته اسکلرانشیمی صحیح است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10863, '74- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«با توجه به شکل کتاب درسی، هر بخشی از دیواره یاخته ای که طی بررسی با میکروسکوپ الکترونی، تیره تر از ......... مشاهده می شود، ......... .»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10864, '75- چند مورد، عبارت زیر را به طور نامناسب کامل می کند؟\n\n«در ساقه ی یک گیاه چوبی و ده ساله، .................. »\n\nالف- یاخته های متعلق به سامانه ی بافت پوششی – معمولاً در یک لایه یاخته ای سازماندهی شده اند.\n\nب- اصلی ترین یاخته های سامانه ی بافت آوندی – می توانند آب را از یاخته های اصلی نوع دیگر دریافت کنند.\n\nج- درونی ترین یاخته های سامانه ی بافت آوندی – در مجاورت یاخته های زنده مربوط به مغز ساقه قرار گرفته اند.\n\nد- مستحکم ترین یاخته های سامانه ی بافت زمینه ای – توسط یاخته های مریستمی خارج از پوست تولید می شوند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10865, '76- با توجه به اطلاعات کتاب درسی زیست شناسی، در برش عرضی ریشه نوعی گیاه نهان دانه، دسته های آوندی به طور منظم بر روی محیط یک دایره قرار دارند. کدام مورد هرگز نمی‌تواند درباره این گیاه واجد گل های دوجنسی صحیح باشد؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10866, '77- چند مورد، معرف رایج ترین بافت موجود در سامانه بافتی واقع در زیر سامانه بافت پوششی در گیاهان است؟\n\nالف: ذخیره کننده مواد آلی موردنیاز رشد توده یاخته ای حاصل از تمایز تخم اصلی\n\nب: ایجاد توده ای از یاخته های هم شکل و مشابه ژنتیکی در محیطی کاملاً سترون\n\nج: تسهیل دسترسی به گاز اکسیژن در گیاه کوچک همزیست با سیانوباکتری\n\nد: ترمیم یاخته های برگ گیاه تنباکو در پی حمله نوزاد کرمی شکل حشره', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10867, '78- در بررسی یاخته های بدون هسته در دسته آوندی در ساقه یک گیاه تک لپه، هر یاخته ای که در تماس مستقیم با یاخته های .................. قرار دارد، نسبت به این یاخته ها ..................', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10868, '79- در خصوص تنها بخش باقی مانده از یاخته گیاهی در بافتی مرده، کدام مورد درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10869, '80- کدام گزینه به طور صحیح بیان شده است؟\n\n\n\n«بعضی از یاخته های بخش .................. یاخته های بخش .................. »', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10870, '81- چند ویژگی، سامانه بافت آوند آبکشی را از سامانه بافت آوند چوبی در یک گیاه نهان دانه تک لپه، متمایز می کند؟\n\nالف: عدم وجود لیگنین در دیواره یاخته های فاقد پروتوپلاست\n\nب: هدایت ترکیبات گیاهی تولیدی یاخته های پارانشیمی\n\nج: مشاهده دیواره عرضی بین یاخته های اصلی آن\n\nد: تولید کمتر توسط کامبیوم چوب آبکش', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10871, '82- درخصوص وسیع ترین بخش ساقه اصلی(تنه) یک درخت ده ساله، کدام مورد، صحیح است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10872, '83- درخصوص مقایسه مریستم های پسین یافت شده در ریشه درخت انجیر، کدام عبارت نادرست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10873, '84- مطابق با اطلاعات کتاب درسی، کدام موارد زیر درباره انواع کامبیوم های موجود در گیاهان درست هستند؟\n\nالف: هر کامبیومی که در سامانه بافت زمینه ای گیاه تشکیل می شود، قادر به ساخت یاخته های زنده در هر دو طرف خود است.\n\nب: فقط بعضی از کامبیوم های گیاه که در تشکیل سامانه بافت آوندی نقش دارند، در برش عرضی ظاهری دایره مانند دارند.\n\nج: هر کامبیومی که قادر به ساخت مقادیر متفاوتی از یاخته های آوندی در ساقه است، در گیاهان دو لپه ای مشاهده می شود.\n\nد: فقط بعضی از کامبیوم هایی که در افزایش قطر ریشه گیاه نقش دارند، در تولید یاخته های پیراپوست نقش دارند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10874, '85- چند مورد، می تواند مربوط به ویژگی مشترک یاخته پارانشیمی و فیبر باشد؟\n\nالف: علاوه بر داشتن ظاهر چندوجهی، در دیواره ضخیم خود، لیگنین رسوب داده است.\n\nب: هیچ گاه، در سامانه بافتی که سراسر گیاه علفی را می پوشاند، مشاهده نمی شود.\n\nج: در یک دسته آوندی، در تماس با یاخته های زنده بافت آوندی قرار می گیرد.\n\nد: در بخش مرکزی یاخته، اندامک های دارای سبزینه (کلروفیل) قرار دارند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10875, '86- مطابق شکل زیر، کدام مورد درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10876, '87- در خصوص نوعی یاخته تمایزیافته روپوستی که برخلاف سایر یاخته های تمایزیافته، در اندام های هوایی گیاهان دولپه جوان، سبزینه دارد، کدام مورد درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10877, '88- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، هر اندامکی در یاخته های گیاه هویج که ..................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10878, '89- در خصوص انواع ترکیبات موجود در یاخته های گیاهان دارای بیشترین تنوع بر روی کره زمین، چند مورد درست است؟\n\nالف: واکوئول و رنگ دیسه گیاهان، دارای ترکیباتی هستند که در پیشگیری و درمان سرطان و نیز بهبود کارکرد مغز نقش دارند.\n\nب: رنگ نارنجی در ریشه هویج و رنگ بنفش در برگ های کلم، به علت وجود ترکیبات رنگی در واکوئول یاخته های آن ها است.\n\nج: هنگام پاییز با کاهش طول روز و کم شدن نور، ضمن تجزیه سبزینه در برگ سبز گیاهان، مقدار کاروتنوئیدها افزایش می یابد.\n\nد: سبزدیسه موجود در یاخته های گیاهی برخلاف رنگ دیسه ها، در نزدیکی و اطراف لایه درونی غشای یاخته ای تجمع یافته اند.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10879, '90- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، اگر .................. درون یاخته گیاهی نسبت به محیط بیرون کمتر باشد، .................. است.»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10880, '91- کدام ویژگی، در یاخته های گیاهی پلاسمودسم را از لان، متمایز می سازد؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10881, '92- در خصوص ترکیبات دیگر در گیاهان، کدام موارد درست است؟\n\nالف: ترکیبات قابل مشاهده در شیرابه بعضی گیاهان به فراوانی، می توانند اثر مخرب بر لوب های مخ داشته باشند.\n\nب: ترکیب شیره نوعی اندامک واجد نقش در تورژسانس و پلاسمولیز، می تواند از بافتی به بافت دیگر فرق کند.\n\nج: ممکن است در مقادیر متفاوت، باعث برهم خوردن تعادل بین تقسیم یاخته ها و مرگ آن ها شود.\n\nد: لاستیک برای اولین بار از شیرابه نوعی گیاه چندساله و دارای رشد پسین ساخته شد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10882, '93- کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«به طور معمول در یک درخت، کامبیوم آوندساز و کامبیوم چوب پنبه ساز از نظر .................. به یکدیگر شباهت و از نظر ..................\n\nبا یکدیگر تفاوت دارند.»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10883, '94- با توجه به شکل های زیر که برش عرضی از مقطع ریشه و ساقه دو گیاه یک ساله را نشان می دهند، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n\n\n«به طور معمول، .................. ممکن است توسط مریستمی صورت گیرد که ..................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10884, '95- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در بررسی مقطع عرضی یک دسته آوندی، همه یاخته هایی که در تماس با .................. هستند، از نظر .................. دارند.»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10885, '96- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«نوعی مریستم پسین که در فاصله بین یاخته هایی فاقد هسته تشکیل می شود، ..................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10886, '97- چند مورد یاخته های زنده بالغ موجود در سامانه بافتی زمینه ای در گیاهان نهان دانه علفی را از یکدیگر متمایز می کنند؟\n\nالف: کربوهیدرات های منشعب غشا با کربوهیدرات های دیواره تماس دارند.\n\nب: یاخته هدف عامل رشد تولیدی در محل آسیب بافت گیاهی است.\n\nج: غشا و دیواره یاخته ای آن به صورت چند ضلعی آرایش یافته اند.\n\nد: انواعی اندامک دو غشایی در مرکز پروتوپلاست وجود دارد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10887, '98- چند مورد زیر می تواند از نتایج وجود دیسه ها در گیاهان مختلف باشد؟\n\nالف) تأمین مواد ضروری برای رشد جوانه ها و تشکیل پایه های جدید\n\nب) ذخیره ترکیبات رنگی موثر در جلوگیری از بروز سرطان\n\nج) داشتن نقش اصلی در افزایش حجم گیاه طی تورژسانس\n\nد) ذخیره پروتئین گلوتن موردنیاز برای رشد و نمو رویان گندم', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10888, '99- با توجه به شکل روبه رو کدام گزینه به طور درست بیان شده است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10889, '100- چند مورد، در ارتباط با فرورفتگی های غارمانند در گیاه خرزهره، درست است؟\n\nالف: پوستک ضخیم، درون این فرورفتگی ها را می پوشاند.\n\nب: بافت زمینه ای هوادار، در تنفس یاخته های آن موثر است.\n\nج: اتمسفر آن، مانع از خروج قطرات مایع آب، از روزنه ها می شود.\n\nد: در ساختار آن، بیش از یک نوع یاخته روپوستی تمایزیافته وجود دارد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10890, '101- چند مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«با بررسی دو یاخته زنده مجاور که هر دو دارای دیواره پسین هستند، می توان گفت بخشی از دیواره یاخته ای که ..................... دارد، .....................»\n\nالف: فقط پکتین - می تواند از دو لایه چسبیده به خود، ضخامت کمتری داشته باشد.\n\nب: پکتین نیز - همراه با رشد پروتوپلاست، اندازه و ابعاد آن زیاد می شود.\n\nج: سلولز نیز - فقط در بخش هایی از یاخته در تماس با غشا است.\n\nد: فقط سلولز - دارای پلی ساکاریدهای موازی و غیرموازی است.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10891, '102- یاخته های مریستم نخستین ریشه .................... یاخته های مریستمی جوانه های قرار گرفته در ساقه ....................', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10892, '103- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در برشی از ساقه درخت سیب، هر لایه ای که از کامبیوم آوندساز ....................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10893, '104- در خصوص انواع یاخته ها در یک دسته آوندی گیاه نهان دانه علفی، کدام مورد نادرست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10894, '105- به طور معمول، در یک یاخته گیاهی کدام گزینه عبارت زیر را به طور صحیح کامل می نماید؟\n\n«هر لایه ای در حد فاصل بین غشای دو یاخته گیاهی واجد دیواره پسین و مجاور هم که ....................»', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10895, '106- کدام مورد در خصوص سامانه ای بافتی در برگ نوعی گیاه که عملکردی مشابه با پوست در جانوران دارد، درست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10896, '107- چند مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در ارتباط با گیاهی که برش عرضی ریشه آن به شکل .................... است، می توان بیان داشت که در برش عرضی ساقه آن، .................... گیاه دیگر .................... »\n\n\n\nالف) B - نسبت به - اندازه و فاصله دستجات آوندی از روپوست بیشتر است.\n\nب) B - برخلاف - در مرکزی ترین قسمت، یاخته های سامانه بافت زمینه ای مشاهده می شوند.\n\nج) A - نسبت به - دستجات آوندی دارای یاخته همراه در مجاورت آوند آبکشی، به تعداد بیشتری وجود دارند.\n\nد) A - همانند - در هر دسته آوندی شیره پرورده درون آوندها نسبت به شیره خام درون آنها به روپوست نزدیکتر است.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(10897, '108- طبق متن کتاب درسی، کدام موارد درباره آزمایش مشاهده ساختارهای نخستین گیاهان در زیر میکروسکوپ نوری صحیح است؟\n\nالف: در پی استفاده از آب مقطر برای سومین بار، برش تهیه شده به مدت 20 دقیقه در آبی متیل قرار می گیرد.\n\nب: مقدار زمان مورد نیاز برای قرار داشتن برش های گیاهی در محلول های کارمن زاجی و رنگ بر تقریباً برابر می باشد.\n\nج: برای مشاهده مطلوب تر نمونه گیاهی، ابتدا از بزرگ نمایی کم و سپس بزرگ نمایی زیاد میکروسکوپ استفاده می شود.\n\nد: استفاده از استیک اسید رقیق بعد از قرارگیری نمونه گیاهی در محلول رنگ بر و قبل از قرارگیری آن در آبی متیل صورت می گیرد.', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10898, '109- کدام گزینه در ارتباط با گیاه خرزهره نادرست است؟', 1, 4, 17, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:07', 1, NULL, NULL, 'free'),
(10899, '1-کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\nدرون نوعی گیاه آبی، .................. رخ می‌دهد.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10900, '2-کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\nوقتی پس از اینکه همه حفره خود را از آب آزاد آکسیژن می‌کند بی حس می‌شود و حفره‌های آن دریده شود، همه مواد .................. که از حفره ایده‌ شده‌اند', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10901, '3-کدام عبارت درباره سیماک‌تری‌ها به‌درستی بیان شده است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10902, '4-چند مورد، دربارهٔ الگوی جریان فشاری برای جابه‌جایی شیرهٔ پرورده که توسط ارنست مونش ارائه شد، درست است؟ الف- آب لازم برای راه‌اندازی جریان توده‌ای در آوند آبکش، فقط از آوند چوبی وارد آوند آبکش شده است. ب- در مرحلهٔ «۱» برخلاف مرحلهٔ «۴»، انتقال فعال همواره توسط یاخته‌ای فتوسنتزکننده انجام می‌شود. ج- در پی کاهش شدید فشار ریشه‌ای، مقدار مواد آلی جابه‌جا شده توسط آوند آبکش کاهش می‌یابد. د- ساکارز بارگیری‌شده توسط آوند آبکش، نقش اصلی را در افزایش حجم آب در آوند آبکش دارد.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10903, '5-کدام عبارت درباره رابطه تعرق و گیاه نادرست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10904, '6-کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\nدر صورت ................. در محیط زندگی یک گیاه گل‌دار علفی، ممکن است «.................»', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10905, '7-کدام عبارت درباره مراحل مدل «ارنست مونش» برای انتقال شیره پرورده در گیاه ارائه کرده، درست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10906, '8-چند مورد دربارهٔ فرایندهای مربوط به تغذیه، جذب و انتقال مواد در گیاهان نهاندانه، درست است؟ الف: در شرایطی، گیاه می‌تواند تعداد یا نوع محل‌های مصرف خود را تغییر دهد. ب: تناوب کشت گیاهان، ممکن است باعث کاهش یا افزایش مواد معدنی در خاک شود. ج: در گیاهان چوبی مسن، دفع آب به‌صورت گاز، فقط از طریق برگ‌های گیاه انجام می‌شود. د: ویژگی‌های خاص مولکول‌های آب، باعث ایجاد جریان توده‌ای در بعضی آوندهای بدون هسته می‌شوند.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10907, '9-کدام مورد یا موارد، دربارهٔ فقط یکی از عناصر مهم شرکت‌کننده در ساختار مولکول‌های وراثتی، درست است؟ الف: در بیشتر کودها وجود دارد. ب: افزایش گیاخاک دسترسی به آن را دشوار می‌کند. ج: ترکیبات آن‌ها به‌طور عمده از خاک جذب می‌شوند. د: میکوریزا به افزایش جذب آن از خاک کمک می‌کند.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10908, 'کدام عبارت درباره خاک و مواد معدنی مورد نیاز گیاهان درست است؟', 1, 4, 18, 170, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10909, '11-کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\nبرای انتقال آب و مواد محلول در طی مسافتی کوتاه در ................. ریشه یک گیاه ................. همه یاخته‌های مرتبط از نظر ................. یکسان هستند.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10910, '12-با توجه به شکل مقابل که قسمتی از ریشه یک گیاه را نشان می‌دهد، کدام عبارت درست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10911, '13-با توجه به اطلاعات کتاب درسی، کدام مورد برای تکمیل عبارت مقابل مناسب است؟ «به‌طور معمول، فقط بعضی از ................. دارند.»', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10912, '14-در خصوص تأمین نیتروژن خاک و نیتروژن مورد نیاز گیاهان، کدام عبارت نادرست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10913, '15-در ارتباط با مطالب کتاب درسی، کدام مورد از نظر درستی یا نادرستی با سایر عبارت متفاوت است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10914, '16-با توجه به مهم‌ترین کودهای مطرح شده در کتاب درسی، مقدار مواد آلی درون خاک به‌دنبال افزودن انواعی از کودها به آن می‌تواند تغییر کند. کدام گزینه درباره این کودها به‌طور صحیح بیان شده است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10915, '17-مطابق مطالب کتاب درسی، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«درخصوص تغییرات میزان نیتروژن، نوعی باکتری که .................، به‌طور حتم .................»', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10916, '18-کدام عبارت درباره خاک و تغذیه گیاهان درست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10917, '19-در شکل زیر، بخشی از یک گیاه نشان داده شده است. کدام موارد، دربارهٔ این گیاه درست است؟ الف: یاختهٔ «۴» نسبت به یاختهٔ «۱»، عمر کوتاه‌تری دارد. ب: نوع پلی‌ساکارید ذخیره‌ای در یاختهٔ «۱» و «۲» یکسان است. ج: یاختهٔ «۳» می‌تواند هم‌سطح با یاخته‌های تار کشندهٔ قرار بگیرد. د: در برش عرضی ساقهٔ این گیاه، دستجات آوندی به‌صورت منظم روی یک حلقه قرار گرفته‌اند.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10918, '20-کدام عبارت درباره همه روزنه‌های موجود در برگ یک گیاه گوجه‌فرنگی درست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10919, '21-چند جمله در مورد گیاخاک (هوموس) درست می‌باشد؟ الف) ترکیبی از مواد آلی و غیرآلی و ریزجانداران (میکروارگانیسم‌ها) است. ب) می‌تواند مانع از شست‌وشوی یون‌های مثبت از خاک شود. ج) مانند کلاهک ریشه موجب تسهیل نفوذ ریشهٔ گیاهان در خاک می‌شود. د) برخی از اجزای آن که منشأ گیاهی دارند، می‌توانند هوازدگی شیمیایی ایجاد کنند.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10920, '22-چند عبارت دربارهٔ گیاخاک درست است؟ الف) باعث نرمی خاک شده و به نفوذ ریشه در خاک کمک می‌کند. ب) از خروج یون‌های منفی از خاک جلوگیری می‌کند. ج) فقط از بقایای گیاهان به‌ویژه اجزای در حال تجزیهٔ آن‌ها تشکیل شده است. د) می‌تواند در اثر پدیدهٔ هوازدگی سنگ‌ها ایجاد شود.', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10921, '23-یکی از معمول‌ترین سازگارها برای جذب آب و مواد معدنی، همزیستی ریشه گیاهان با لایه‌ای از قارچ‌ها است. با توجه به این نوع همزیستی، کدام گزینه درست است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
