(10946, '48-در کدام گزینه، وجه اشتراک همهٔ یاخته‌های لایهٔ آندودرم در همهٔ گیاهان نهان‌دانه به‌درستی ذکر شده است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10947, '49-با توجه به شکل مقابل که بخشی از برش عرضی نوعی گیاه نهان‌دانه است، کدام گزینه صحیح نیست؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
(10948, '50-برای تعیین سرعت حرکت نوعی شیرهٔ گیاهی در نهاندانگان از نشاسته استفاده شد. کدام مورد در رابطه با اصول حرکت این شیرهٔ گیاهی، نادرست بیان شده است؟', 1, 4, 18, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-02 19:31:23', 1, NULL, NULL, 'free'),
