(11025, '40- با توجه به شکل روبه‌رو، در ناحیهٔ مشخص شده، کدام مورد اتفاق نمی‌افتد؟', 2, 4, 19, 55, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11026, ' در مورد مغز انسان، چند مورد درست می‌باشد؟\n\nالف) بطن‌های ۳ و ۴، درون نیمکره‌های مخ قرار دارند.\n\nب) کیاسمای بینایی در پایین تالاموس‌ها قرار دارد.\n\nج) لوب‌های بویایی (پیازهای بویایی) مرکز درک پیام‌های بویایی هستند.\n\nد) هیپوکامپ (اسبک مغز) در تشکیل حافظه نقش دارد.', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11027, ' با توجه به فعالیت کتاب در تشریح مغز گوسفند و در بررسی بخش‌های ....................... .', 2, 4, 19, 57, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:32:17', 2, 'free'),
(11028, ' کدام گزینه برای کامل کردن عبارت زیر مناسب است؟\n\n«در انسان، بخشی از ساقهٔ مغز که ........................ .»', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11029, '44- چه تعداد از عبارت‌های زیر نادرست است؟\n\nالف) مخچه به‌طور متناوب از بخش‌های دیگر مغز پیام دریافت می‌کند.\n\nب) در طی انعکاس عقب‌کشیدن دست، فقط در سه یاختهٔ عصبی، هدایت پیام عصبی انجام می‌گیرد.\n\nج) همهٔ انعکاس‌ها به‌صورت غیرارادی و تحت کنترل اعصاب خودمختار انجام می‌گیرند.\n\nد) به هیچ غدهٔ برون‌ریزی عصب حرکتی پیکری، پیام منتقل نمی‌کند.', 2, 4, 19, 59, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11030, ' با توجه به شکل روبه‌رو که بخش‌هایی از دستگاه عصبی مرکزی انسان را نشان می‌دهد، چند جمله درست است؟\n\nالف) بخش ۲، برخلاف بخش ۴ مرکز بعضی از انعکاس‌های بدن می‌باشد.\n\nب) بخش ۱، همانند بخش ۴ در انتقال اغلب پیام‌های حسی به قشر مخ مؤثر می‌باشد.\n\nج) بخش ۴، همانند بخش ۳ همهٔ پیام‌های حسی بدن را به مغز ارسال می‌کند.\n\nد) بخش ۳، برخلاف بخش ۲ در فعالیت‌های شنوایی و بینایی بدن نقش دارد.', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11031, ' چند مورد می‌تواند جملهٔ زیر را به‌درستی تکمیل نماید؟\n\nبرای بهبود عملکرد مغز (تبدیل مغز الف به ب)، ........................\n\nالف) ترکیبات رنگی ذخیره‌شده در واکوئول‌های موجود در یاخته‌های ریشهٔ کلم بنفش مناسب است.\n\nب) آنتوسیانین موجود در ریشهٔ چغندر قرمز مناسب است.\n\nج) ترکیبات پاد اُکسندهٔ موجود در واکوئول‌های پرتقال توسرخ نقش مثبتی دارند.\n\nد) کاروتن موجود در ریشهٔ گیاه هویج با توجه به نقش آنتی‌اکسیدانی خود، مناسب می‌باشد.', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11032, ' کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«ساختاری که دیوارهٔ عقبی بطن چهارم مغز انسان را تشکیل می‌دهد، فقط ........................ .»', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11033, '48- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در انسان، ........................ یاخته‌های شرکت‌کننده در انعکاس عقب‌کشیدن دست در برخورد با جسم داغ که ........................ .»', 2, 4, 19, 59, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11034, ' هر زمانی که مقدار عبور یون‌های سدیم از عرض غشای نورون افزایش می‌یابد، کدام پدیده قطعاً در حال وقوع است؟', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11035, '50- چند مورد عبارت زیر را به طور صحیح تکمیل نمی‌کند؟\n\n«مطابق شکل روبه‌رو که نمودار پتانسیل عمل نورون رابط را نشان می‌دهد، در لحظهٔ ........................ مشابه لحظهٔ ........................ می‌باشد.»\n\nالف) ۲ - مقدار خروج یونی که تعداد جایگاه‌های بیشتری در پمپ سدیم پتاسیم دارد - ۵ و ۳\n\nب) ۱ - وضعیت کانال‌های واجد دریچه در سمتی دور از کربوهیدرات‌های غشا - ۴ و ۲\n\nج) ۳ - جهت انتشار یون‌های سدیم از محل فسفولیپیدهای غشای نورون - ۲ و ۵\n\nد) ۴ - شدت خروج سدیم از نورون از طریق کانال‌های نشتی - ۱ و ۳', 2, 4, 19, 55, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11036, 'در غشای یاختهٔ عصبی، از پیامدهای سرکوب فعالیت ........................ می‌توان به ........................ اشاره نمود.»', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11037, ' چند مورد عبارت زیر را به طور مناسب کامل می‌نماید؟\n\n«در ساختار هر نیمکرهٔ مخ انسان، هر لوبی که ........................ است، به‌طورحتم با ........................ لوب دیگر آن نیمکره مرز مشترک دارد.»\n\nالف) در مجاورت مخچه قرار گرفته - دو\n\nب) واجد اندازهٔ بزرگ‌تری از سایرین - سه\n\nج) در نمای مغز از بالا غیرقابل مشاهده - سه\n\nد) دارای توان دریافت پیام گیرنده‌های بینایی - دو', 2, 4, 19, 57, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:56:13', 2, 'free'),
(11038, '53- بخش حرکتی دستگاه عصبی محیطی انسان از دو قسمت تشکیل شده است که وظایفی مستقل از یک‌دیگر دارند. چند مورد زیر ویژگی مشترک این دو بخش را نشان می‌دهد؟\n\nالف) نقش در تشکیل بخشی از اعصاب مغزی\n\nب) انقباض غیرارادی ماهیچه‌های با ظاهر تیره و روشن\n\nج) عدم تأثیرگذاری بر آغاز انقباض دهلیزی\n\nد) تأثیر بر ایجاد حرکات گوارشی کرمی‌شکل در مری', 2, 4, 19, 59, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11039, ' مطابق با مطالب کتاب درسی، کدام ویژگی مربوط به همهٔ سیناپس‌های فعالی است که یاخته‌های عصبی به منظور انتقال پیام به یاختهٔ دیگری برقرار می‌کنند؟', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11040, ' کدام عبارت، در ارتباط با یاخته‌های پشتیبان، صحیح است؟', 2, 4, 19, 54, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11041, ' در غشای یک یاختهٔ عصبی حرکتی، در ارتباط با هر مولکول پروتئینی مربوط به ........................، به‌طورقطع می‌توان بیان داشت که ........................ .', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11042, ' بخش خودمختار دستگاه عصبی محیطی، کار ماهیچه‌های صاف، ماهیچهٔ قلب و غده‌ها را تنظیم می‌کند و حاوی دو بخش مختلف است که یک بخش آن در هنگام هیجان به‌صورت غالب عمل می‌کند. چند مورد، در ارتباط با این بخش خودمختار صحیح است؟\n\nالف) نمی‌تواند فعالیت ماهیچه‌ها را به شکل انعکاسی تنظیم کند.\n\nب) تمامی فعالیت‌های این بخش به‌صورت ناآگاهانه انجام می‌شود.\n\nج) مصرف ATP را در ماهیچه‌های حلقوی عنبیه افزایش می‌دهد.\n\nد) فاصلهٔ بین دو قلهٔ متوالی در منحنی اسپیروگرام را کاهش می‌دهد.', 2, 4, 19, 60, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:29:17', 2, 'free'),
(11043, ' کدام عبارت، دربارهٔ شکل مقابل صحیح است؟', 2, 4, 19, 57, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:56:40', 2, 'free'),
(11044, ' باتوجه‌به نمای نیمرخ لوب‌های مخ، در ارتباط با لوبی که مرز مشترک بیشتری با مرکز تنظیم حرکات و فعالیت ارادی ماهیچه‌های بدن دارد، کدام عبارت صحیح است؟', 2, 4, 19, 57, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:58:03', 2, 'free'),
(11045, '60- در ارتباط با یاخته‌های شرکت‌کننده در انعکاس عقب کشیدن دست فرد در برخورد با جسم داغ کدام عبارت، صحیح است؟', 2, 4, 19, 59, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11046, ' به‌منظور جلوگیری از ایجاد اختلال در کار دستگاه عصبی در شرایط غیرطبیعی که ........................ لازم است تا ........................ .', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11047, ' چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، ........................ یاخته‌های بافت عصبی مغز، ........................»\n\nالف: فقط بعضی از - برای بررسی فعالیت‌های آن کاربرد دارند.\n\nب: همهٔ - در حفظ هم‌ایستایی مایع اطراف خود، واجد نقش هستند.\n\nج: فقط بعضی از - با تغییر مقدار یون دو سوی غشا، پیام عصبی تولید می‌کنند.\n\nد: همهٔ - فاقد توان عبور از مرحلهٔ رشد چرخهٔ یاخته‌ای برای مضاعف کردن دنا هستند.', 2, 4, 19, 54, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11048, 'در زمانی که ناقل عصبی تحریکی به گیرندهٔ خود در سطح یاختهٔ عصبی متصل است، گروهی از پروتئین‌ها در غشای یاختهٔ پس‌سیناپسی یون‌ها را بین دو سمت غشای یاخته جابه‌جا می‌کنند. کدام گزینه مشخصهٔ همهٔ این پروتئین‌ها را به طور صحیح بیان می‌کند؟', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11049, ' با توجه به فعالیت فصل ۱ زیست‌شناسی یازدهم، کدام مورد، جملهٔ زیر را به درستی تکمیل می‌کند؟\n\n«در حین تشریح ساختار مغز گوسفند، بلافاصله پس از ........................ دو نیمکرهٔ مخ، ........................ ، دیده می‌شود.»', 2, 4, 19, 57, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:59:52', 2, 'free'),
(11050, ' کدام گزینه دربارهٔ منحنی پتانسیل عمل، عبارت زیر را به درستی تکمیل می‌کند؟\n\n«درون یاختهٔ عصبی تحریک‌شده، همزمان با تغییر پتانسیل از ........................»', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11051, ' کدام ویژگی، فراوان‌ترین یاخته‌های موجود در بافت عصبی انسان را از نوع دیگر یاخته‌های این بافت، متمایز می‌سازد؟', 2, 4, 19, 54, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(11052, ' درخصوص هر مرحله از فعالیت یک یاختهٔ عصبی که در آن مجموع بارهای مثبت داخل یاخته از مجموع بارهای مثبت خارج یاخته بیشتر است، کدام‌یک از اتفاقات زیر مورد انتظار است؟', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11053, ' درخصوص بخشی از ساقهٔ مغز یک فرد سالم که توسط مجرایی به دو بخش تقسیم‌بندی می‌شود، کدام مورد درست است؟', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11054, ' درخصوص مقایسهٔ ساختارهای مختلف مغز انسان، کدام مورد نادرست است؟', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11055, '70- درخصوص مقایسهٔ ساختار عصبی در جانوران مطرح‌شده در کتاب درسی، کدام مورد درست است؟', 2, 4, 19, 61, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11056, ' کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«مطابق با کتاب درسی، بخشی از دستگاه عصبی مرکزی ماهی که ........................ قرار دارد، از لحاظ عملکردی معادل بخشی از دستگاه عصبی انسان است که ........................ .»', 2, 4, 19, 61, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11057, ' کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در یک نقطه از این رشتهٔ عصبی، هرگاه ........................ است، به‌طورحتم ........................»', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11058, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«با توجه به منحنی پتانسیل عمل نشان داده شده در شکل زیر که مربوط به یک یاختهٔ عصبی حرکتی می‌باشد، می‌توان گفت که نقطهٔ ........................ از لحاظ ........................ با نقطهٔ ........................ مشابه می‌باشد، اما از لحاظ ........................ با آن متفاوت است.»', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11059, '74- در فرایند انعکاس عقب‌کشیدن دست، نوعی ناقل عصبی نسبت به سایر ناقلین دخیل در فرایند، مسافت بیشتری را در آسه (آکسون) طی می‌کند. کدام گزینه در خصوص این مولکول شیمیایی و یاختهٔ سازندهٔ آن به درستی بیان شده است؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11060, '75- با توجه به ساختارهای نامگذاری شده در شکل سطح شکمی مغز گوسفند در کتاب درسی زیست یازدهم، کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«مرکزی‌ترین ساختار مشخص در سطح شکمی مغز گوسفند، معادل بخشی از مغز انسان است که ........................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11061, '76- کدام مورد برای تکمیل عبارت مقابل مناسب است؟ « پس از برخورد دست انسان به یک جسم داغ، انعکاسی در بدن وی به راه می‌افتد. مطابق اطلاعات کتاب درسی، هر یاخته عصبی که در این انعکاس...................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11062, '77- کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n« بخشی از مغز گوسفند که در فرایند تشریح بلافاصله در ................... مشاهده می‌شود، معادل بخشی از مغز انسان است که ...................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11063, '78- مطابق اطلاعات کتاب درسی، چند مورد نمی‌تواند یاخته‌های اصلی بافت عصبی را از یاخته‌هایی که آن‌ها را عایق‌بندی می‌کنند، متمایز سازد؟\n\nالف- توانایی تولید نوعی پیک شیمیایی کوتاه‌برد و اثرگذاری بر یاخته‌های مجاور\n\nب- توقف دائمی در یکی از مراحل اینترفاز و عدم استفاده از آنزیم دنابسپاراز در هسته\n\nپ- عدم تماس گروهی از فسفولیپیدها و پروتئین‌های موجود در غشا با مایع بین‌یاخته‌ای\n\nت- تأثیر در تشکیل نمودارهای نامنظم نوار مغزی و دخالت در حفظ هم‌ایستایی مایع اطراف', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11064, '79- کدام مورد درخصوص یاخته‌های شرکت‌کننده در فرایند انعکاس عقب کشیدن دست در برخورد با جسم داغ درست است؟\n\n« هریاختهٔ عصبی که ................... »', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11065, '80- با توجه به اطلاعات کتاب درسی، کدام مورد در رابطه با پرده‌هایی که در حفاظت از مغز و نخاع نقش دارند صادق نیست؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11066, '81- چند مورد، دربارهٔ اولین محل پردازش اطلاعات بینایی در مغز انسان، درست است؟\n\nالف: مرکز عصبی است که سومین بطن مغزی در بالای آن قرار دارد.\n\nب: مرکز عصبی است که بخش عمدهٔ رابط سه‌گوش در بالای آن قرار دارد.\n\nج: در مجاورت ساختارهایی قرار دارد که پیک شیمیایی دوربرد ترشح می‌کنند.\n\nد: محلی است که در آن بخشی از آکسون‌های عصب بینایی یک چشم به نیمکرهٔ مخ مقابل می‌روند.', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11067, '82- کدام گزینه زیر صحیح است؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11068, '83- در ارتباط با دستگاه عصبی مرکزی انسان، کدام گزینه، عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«به طور معمول، مراکز عصبی که در ................... نقش دارند، از نظر ................... مشابه یکدیگر بوده و از لحاظ ................... متفاوت می‌باشند.»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11069, '84- در بافت عصبی انسان یاخته‌هایی فاقد توانایی تولید پیام عصبی وجود دارد. کدام مورد، ویژگی مشترک این یاخته‌ها است؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11070, '85- در خصوص ساختاری از مغز که در ارتباط با قشر مخ قرار داشته و در بروز احساساتی از جمله خشم و لذت نقش ایفا می‌کند، کدام عبارت درست است؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11071, '86- در خصوص هدایت و انتقال پیام عصبی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، اگر ناقل عصبی پس از ترشح به‌نوعی مولکول پروتئینی متصل ........................، قطعاً ........................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11072, '87- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، ساختاری از مغز انسان که دیوارهٔ ........................ پایین‌ترین بطن مغزی را تشکیل می‌دهد، ممکن ........................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11073, '88- کدام گزینه، عبارت زیر را به‌طور نامناسب کامل می‌کند؟\n\n«قسمتی از بخش حرکتی دستگاه عصبی محیطی که ........................، با قسمتی که ........................، از نظر ........................ مشابه است.»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11074, '89- در خصوص منحنی نمودار پتانسیل عمل یک یاختهٔ عصبی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌دنبال تحریک یک یاختهٔ عصبی و ایجاد پتانسیل عمل، ........................، به‌طور حتم ........................ می‌یابد.»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11075, '90- با توجه به مطالب کتاب درسی، یاخته‌های عصبی (نورون‌ها) سه عملکرد اختصاصی دارند. در خصوص این عملکردها، کدام موارد درست است؟\n\nالف: بعضی از یاخته‌های پشتیبان بافت عصبی، تنها یکی از این عملکردها را سریع‌تر می‌کنند.\n\nب: انتقال پیام عصبی نسبت به هدایت آن، باعث مصرف انرژی بیشتری در نورون می‌شود.\n\nج: ممکن نیست تحریک عصبی و انتقال پیام در یک بخش از نوعی نورون رخ دهد.\n\nد: جسم یاخته‌ای نورون‌ها، در انجام همهٔ این عملکردها نقش ایفا می‌کند.', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11076, '91- کدام مورد، دربارهٔ اجزای فرعی مغز یک فرد بالغ، عبارت را به‌طور نامناسب کامل می‌کند؟\n\n«در صورت آسیب به مرکزی عصبی که ........................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11077, '92- مطابق با مطالب کتاب درسی، کدام ویژگی مربوط به همهٔ سیناپس‌های فعالی است که یاخته‌های عصبی به‌منظور انتقال پیام به یاختهٔ دیگری برقرار می‌کنند؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11078, '93- کدام گزینه در ارتباط با مغز گوسفند به‌طور صحیح بیان شده است؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11079, '94- کدام گزینه دربارهٔ منحنی پتانسیل عمل، عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n«درون یاختهٔ عصبی تحریک‌شده، همزمان با تغییر پتانسیل از ........................»', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11080, '95- کدام عبارت، در ارتباط با ساختارهای مغزی انسان، درست است؟', 2, 4, 19, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11081, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در بررسی ساختارهای مغز انسان، در نمای ........................ برخلاف نمای دیگر ........................»', 2, 4, 19, 57, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, '2026-08-25 14:52:04', 2, 'free'),
(11082, ' کدام عبارت، در ارتباط با برخی از اندام‌های دستگاه عصبی غیرمحیطی صحیح می‌باشد؟', 2, 4, 19, 56, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11083, ' با توجه به مغز انسان، چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«........................ بیان‌کنندهٔ ویژگی باشد که متمایز کنندهٔ یک پردهٔ مننژ نسبت به دو پردهٔ دیگر مننژ است.»\n\nالف: قطر لایه، می‌تواند\n\nب: وجود رشته‌های ریز، می‌تواند\n\nج: تماس با مادهٔ سفید، نمی‌تواند\n\nد: وجود حفرات بزرگ در لایه، نمی‌تواند', 2, 4, 19, 56, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11084, ' کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«برای عملکرد صحیح ........................ جهت ........................ لازم است تا ........................ نقش خود را به‌درستی ایفا کنند/کند.»', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11085, '100- کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در آدمی، ........................ در شرایطی ممکن است به‌وسیلهٔ ........................ رخ دهد.»', 2, 4, 19, 59, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11086, ' در بررسی تأثیر نوعی مادهٔ اعتیادآور بر دستگاه عصبی مرکزی، می‌توان گفت که حتی پس از ........................', 2, 4, 19, 58, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11087, 'کدام گزینه، برای تکمیل عبارت نامناسب است؟\n\n«در انسان، بخشی از ساقهٔ مغز که حاوی مرکز غیراصلی تنفس است، نسبت به ........................ »', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11088, ' کدام گزینه، عبارت زیر را به‌طور مناسب تکمیل می‌نماید؟\n\n«در مسیر انعکاس عقب کشیدن دست، نوعی نورون که ........................ می‌نماید.»', 2, 4, 19, 59, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11089, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در انعکاس عقب‌کشیدن دست در برخورد با جسم داغ، ........................ ، پس از ........................ قابل‌مشاهده است.»', 2, 4, 19, 59, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11090, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول در بدن انسان، لوبی از مخ که ........................ »', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11091, ' در خصوص دستگاه عصبی بدن انسان، کدام مورد نادرست است؟', 2, 4, 19, 59, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11092, 'ساختاری از مغز انسان که در امتداد بافت تشکیل‌دهندهٔ بخشی از دیوارهٔ بطن سوم مغز قرار گرفته است، چه مشخصه‌ای دارد؟', 2, 4, 19, 57, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11093, ' مطابق با اطلاعات کتاب‌درسی، عملکرد پمپ سدیم - پتاسیم به‌صورت دومرحله‌ای است. کدام مورد، نمی‌تواند در مرحله‌ای مشاهده شود که دهانهٔ پمپ به سمت داخل یاخته است؟', 2, 4, 19, 55, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11094, ' به‌طور معمول، ........................ یاخته‌هایی که بافت عصبی بخش‌های اصلی مغز انسان را تشکیل می‌دهند، ........................', 2, 4, 19, 54, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:55:59', 1, NULL, NULL, 'free'),
(11095, '5-شکل مقابل، وضعیت چشم یک فرد را هنگام دیدن دو جسم در فاصله متفاوت نشان می‌دهد. در صورتی که در هر دو حالت، محل رسیدن پرتوهای نوری به یکدیگر، روی یک نقطه از شبکیه نباشد، کدام عبارت دربارهٔ این فرد درست است؟ (در هر دو حالت، فرد با چشم غیرمسلح (بدون عینک)، در حال نگاه کردن به جسم است.)', 2, 4, 20, 65, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11096, '6-کدام موارد، درباره پردازش پیام‌های حسی در انسان درست است؟\n\nالف: لوب پس‌سری چپ، فقط بعضی از پیام‌های حسی هر چشم را دریافت می‌کند.\n\nب: یک گیرنده حسی می‌تواند پیام یکسانی را برای مدتی طولانی به مغز ارسال کند.\n\nج: همه پیام‌های حمل‌شده توسط رشته‌های یک عصب، به شکل یکسانی تفسیر می‌شوند.\n\nد: فقط بخش‌های مرتبط با سامانه لیمبیک در پردازش پیام‌های شنوایی و بینایی نقش دارند.\n\n(ماز ۱۴۰۲-۱۴۰۳ - متوسط)', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11097, '7-در فردی جوان، به هنگام عدم استفاده از عینک، امکان به‌هم رسیدن پرتوهای نور اجسام دور در محلی جلوتر از محل تجمع گیرنده‌های نوری وجود دارد. کدام عبارت، در ارتباط با این فرد به‌طور حتم درست است؟\n\n(ماز ۱۴۰۲-۱۴۰۳ - متوسط)', 2, 4, 20, 65, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11098, '8-در خصوص فرایند تطابق، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، با .................. فاصله یک جسم از چشم یک انسان سالم و بالغ، در یک محیط دارای نور ..................، به‌طور حتم .................. .»\n\n(ماز ۱۴۰۲-۱۴۰۳ - متوسط)', 2, 4, 20, 65, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11099, 'مطابق مطالب کتاب درسی، در بدن انسان، گروهی از گیرنده‌های حواس ویژه به وسیله نوعی مولکول شیمیایی تحریک می‌شوند. چند مورد فقط درخصوص برخی از این گیرنده‌ها درست است؟\n\nالف: به دنبال قرارگیری در معرض محرک ثابت، تولید پیام در آن‌ها کاهش می‌یابد.\n\nب: مولکول‌های شیمیایی پس از حل‌شدن در نوعی مایع، به این گیرنده‌ها متصل می‌شوند.\n\nج: پیام‌های تولیدی در آن‌ها، به بخشی از مغز که در ایجاد احساساتی مانند خشم نقش دارد، منتقل می‌شوند.\n\nد: در پی تحریک شدن، پیام را در محل همایه (سیناپس) به دارینه (دندریت) نوعی یاخته عصبی رابط منتقل می‌کنند.\n\n', 2, 4, 20, 69, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11100, '10-درخصوص مقایسه لایه‌های سازنده کره چشم انسان، کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول در چشم انسان، لایه‌ای که بخشی از آن ..................، به‌طور حتم .................. .»\n\n(ماز ۱۴۰۲-۱۴۰۳ - متوسط)', 2, 4, 20, 64, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11101, '11-در خصوص گیرنده‌های حواس پیکری قرارگرفته در بدن انسان، کدام عبارت برای تکمیل عبارت زیر نامناسب است؟\n\n«به‌طور معمول در بدن انسان، فقط برخی از گیرنده‌های حواس پیکری که .................. .»\n\n(ماز ۱۴۰۲-۱۴۰۳ - متوسط)', 2, 4, 20, 63, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
