(11109, '19-کدام گزینه در مورد گیرنده‌هایی که در شکل روبه‌رو مشخص شده‌اند، درست است؟\n\n(گزینه دو ۱۴۰۲)', 2, 4, 20, 67, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11110, 'چه تعداد از موارد زیر برای تکمیل عبارت داده شده، مناسب هستند؟\n\n«در لایه میانی چشم یک انسان سالم، لایه رنگدانه‌دار و پر از مویرگ‌های خونی .................. .»\n\nالف) شامل جسم مژگانی و عنبیه است\n\nب) در تماس مستقیم با مایعی است که در فضای پشت و جلوی عنبیه قابل‌مشاهده است\n\nج) یاخته‌هایی دارد که با شبکه‌ای از رشته‌های پروتئینی و گلیکوپروتئینی در ارتباط هستند\n\nد) به‌طور مستقیم مواد غذایی لازم برای عدسی را فراهم می‌کند.\n\n', 2, 4, 20, 64, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11111, '21-کدام عبارت در ارتباط با داخلی‌ترین لایه چشم راست یک انسان سالم درست می‌باشد؟\n\n(گزینه دو ۱۴۰۲)', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11112, '22-چند مورد عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n«در ارتباط با مایعی که مواد غذایی را برای عدسی و قرنیه فراهم می‌کند، می‌توان گفت .................. .»\n\nالف) همانند ترکیبی که در گردیزه (نفرون‌ها) تشکیل می‌شود، منشأ آن از خون است\n\nب) در جلو و پشت بخش رنگین چشم قابل‌مشاهده است\n\nج) همانند مایع پشت عدسی چشم شفاف است\n\nد) در سمتی از عدسی واقع شده که تحدب عدسی در آن سمت نسبت به سمت مقابل بیشتر است\n\n(گزینه دو ۱۴۰۳ - ۱۴۰۲)', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
