(11133, '43-نوعی گیرنده حسی تماسی در انسان وجود دارد که در پی فشرده‌شدن پوست، تحریک می‌شود. این نوع گیرنده حسی ..................\n\n(ماراتون ۱۴۰۳-۱۴۰۲ - متوسط)', 2, 4, 20, 63, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-08-28 15:01:04', 2, 'free'),
(11134, '44-کدام گزینه عبارت زیر را به شیوه متفاوتی نسبت به سایر گزینه‌ها تکمیل می‌کند؟\n\n«به‌طور معمول در فردی که میزان .................. نسبت به حالت طبیعی، افزایش یافته است؛ .................. »\n\n(ماراتون ۱۴۰۳-۱۴۰۲ - متوسط)', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11135, '45-در ارتباط با نوعی حس پیکری که گیرنده‌های آن، انتهای دارینه آزاد و منشعب هستند، کدام عبارت، صحیح نیست؟\n\n(آرمان ۱۴۰۳-۱۴۰۲ - متوسط)', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11136, '46-بخش‌هایی در کره چشم وجود دارند که ضمن اینکه جزء یکی از لایه‌های کره چشم طبقه‌بندی می‌شوند، در همگرایی پرتوهای نوری نقش دارند. کدام مورد یا موارد، در ارتباط با فقط بعضی از این بخش‌ها، صحیح است؟\n\nالف: در وسط خود دارای سوراخ مردمک است.\n\nب: بیشترین حجم کره چشم را اشغال می‌کند.\n\nج: هنگام دیدن اجسام نزدیک، دچار افزایش ضخامت می‌شود.\n\nد: مواد غذایی را برای دو ساختار یاخته‌ای شفاف کره چشم فراهم می‌کند.', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11137, '47-فردی با وجود داشتن عدسی سالم، اجسام دور را به‌صورت ناواضح مشاهده می‌کند. کدام عبارت، در ارتباط با این فرد صحیح است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11138, '48-کدام مورد به ترتیب در رابطه با بیشترین تعداد از ساختارهای پرده‌مانند مربوط به اندام‌های حسی ویژه انسان و کدام مورد در ارتباط با کمترین تعداد ساختارهای پرده‌مانند ذکرشده، صادق است؟\n\nالف) در تمامی سطوح خود در تماس با نوعی مایع قرار گرفته است.\n\nب) مواد تولیدی خود را مستقیماً با رگ‌های خونی مبادله می‌کنند.\n\nج) در نتیجه ارتعاش خود، نوعی استخوان کوچک را به لرزه درمی‌آورند.\n\nد) در اندام حسی قرار دارند که پیام آن می‌تواند به بخشی در مجاورت اپی‌فیز برود.', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, NULL, NULL, 'free'),
(11139, '49-استخوان‌های کوچک گوش میانی در عملکرد صحیح گیرنده‌های قرارگرفته در لابه‌لای یاخته‌های پوششی گوش درونی نقش دارند. در خصوص این استخوان‌ها کدام مورد یا موارد به درستی بیان شده است؟\n\nالف) بزرگ‌ترین استخوان کوچک گوش میانی، فقط در یک بخش به دیواره گوش میانی اتصال دارد.\n\nب) استخوان سندانی، از بخش پهن خود در مفصل متحرک با استخوان چکشی شرکت دارد.\n\nج) بخش پهن استخوان چکشی، بر روی پرده مایل و سفیدرنگ انتهای مجرای شنوایی قرار دارد.\n\nد) استخوان دارای ظاهر انگشتری‌شکل، پیام عصبی حاصل از ارتعاش امواج صوتی را به گوش درونی می‌برد.', 2, 4, 20, 67, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 15:57:11', 2, 'free'),
(11140, '50-کدام عبارت، مناسب‌ترین گزینه درباره گیرنده‌های چشایی در انسان محسوب می‌شود؟', 2, 4, 20, 69, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 15:57:41', 2, 'free'),
(11141, '51-چند مورد به منظور تکمیل عبارت زیر نامناسب است؟\n\n«در اندامی از یک انسان سالم که گیرنده‌های متعلق به دو نوع حس ویژه را در خود جای داده است، همهٔ ..........................»\n\nالف) مایعاتی که در تحریک گیرنده‌های حس ویژه نقش دارند، مستقیماً با بخشی از ساختار این گیرنده‌ها در تماس هستند.\n\nب) پیام‌های هدایت‌شده توسط اعصاب خروجی از هر یک از این اندام‌ها، در نهایت، تنها در قشر چین‌خورده مخ استفاده می‌شوند.\n\nج) گیرنده‌های تعادلی مژک‌دار در بخشی از طول مجاری نیم‌دایره عمود برهم قابل مشاهده هستند.\n\nد) گیرنده‌های حس ویژه، زوائد مژکی خود را کاملاً درون نوعی ماده ژلاتینی فرو برده‌اند.', 2, 4, 20, 67, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 15:58:08', 2, 'free'),
(11142, '52-کدام گزینه در خصوص گیرنده‌های حس ویژه موجود در اندامی از بدن صحیح است که بیشترین اطلاعات حسی از طریق آن به مغز مخابره می‌شود؟', 2, 4, 20, 64, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 15:59:17', 2, 'free'),
(11143, '53-با توجه به اطلاعات کتاب درسی، کدام عبارت درباره گیرنده‌های حسی که در بخش‌های گوناگون بدن حضور دارند و تحت تأثیر محرک‌ها به تولید پیام عصبی می‌پردازند، نادرست است؟', 2, 4, 20, 63, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:00:15', 2, 'free'),
(11144, '54-کدام مورد، درباره نوعی از گیرنده‌های مکانیکی گوش درونی که هنگام چرخش سر تحت تأثیر حرکت مایع درون این بخش به تولید پیام عصبی می‌پردازد صدق می‌کند؟', 2, 4, 20, 67, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:00:36', 2, 'free'),
(11145, '55-درخصوص انواع گیرنده‌های حواس ویژه انسان که توسط ماده شیمیایی تحریک می‌شوند، چند مورد نادرست است؟\n\nالف: در دهان و برجستگی‌های زبان، بعضی از گیرنده‌ها با دو انشعاب از رشته عصبی در ارتباط هستند.\n\nب: در مجاورت گیرنده‌هایی که ماهیت عصبی دارند، یاخته‌های پوششی با هسته رأسی مشاهده می‌شود.\n\nج: هر یاخته پوششی اطراف گیرنده بویایی که به غشای پایه متصل است، در تماس با مولکول‌های بودار هوا می‌باشد.\n\nد: هسته یاخته‌هایی از جوانه چشایی که فراوانی کمتری دارند، با هسته هر یاخته مجاور خود در یک سطح قرار دارد.', 2, 4, 20, 69, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:01:03', 2, 'free'),
(11146, '56-درخصوص مقایسه لایه‌های سازنده کره چشم انسان، کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول در چشم انسان، لایه‌ای که بخشی از آن .......................... به‌طور حتم .......................... .»', 2, 4, 20, 64, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:01:56', 2, 'free'),
(11147, '57-کدام گزینه در خصوص بخش‌های مختلف گوش انسان درست است؟', 2, 4, 20, 67, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:02:30', 2, 'free'),
(11148, '58-کدام گزینه عبارت زیر را به طور درست تکمیل می‌کند؟\n\n« در ساختار چشم انسان، ماهیچه‌هایی که در تماس با .......................... دیده می‌شوند، .......................... »', 2, 4, 20, 64, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:04:45', 2, 'free'),
(11149, '59-چند مورد برای تکمیل عبارت زیر مناسب است؟\n\n«وجه تشابه .......................... در ساختار گوش انسان در این است که علاوه‌بر .......................... »\n\nالف) همه نورون‌های حاضر در - انتقال پیام به دستگاه عصبی مرکزی، واجد دنای اصلی در حجیم‌ترین بخش خود می‌باشند.\n\nب) بزرگ‌ترین و کوچک‌ترین استخوان‌های کوچک بخش میانی - اتصال به نوعی پرده، به نوعی استخوان مشترک متصل می‌باشند.\n\nج) ماده‌های ژلاتینی - تأثیر در تحریک بخش‌هایی از مغز، به طور کامل اطراف مژک‌های گیرنده‌های حسی ویژه را احاطه کرده‌اند.\n\nد) فراوان‌ترین یاخته‌های مجاری نیم‌دایره و حفرهٔ میانی بخش حلزونی - عدم تولید تحریک الکتریکی، تنها در یک ردیف استقرار یافته‌اند.', 2, 4, 20, 67, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:05:33', 2, 'free'),
(11150, '60-مطابق اطلاعات کتاب درسی، کدام مورد وجه تمایز بخش بالایی عصب خارج‌شده از گوش انسان سالم و بخش پایینی آن را نشان می‌دهد؟', 2, 4, 20, 67, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:08:15', 2, 'free'),
(11151, '61-مطابق با شکل زیر، بیماری چشم فرد با استفاده از نوعی عدسی برطرف می‌شود. در ارتباط با چشم غیرمسلح ( بدون عینک ) در این فرد، کدام مورد صحیح است؟', 2, 4, 20, 65, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:15:07', 2, 'free'),
(11152, '62-کدام گزینه، عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n« هر بیماری مربوط به چشم انسان که در آن پرتوهای نوری مربوط به اجسام ...........»', 2, 4, 20, 65, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:13', 1, '2026-09-17 16:15:54', 2, 'free'),
(11153, '63-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در نوعی بیماری چشم، .......................... ، در این بیماری به طور حتم .......................... .»', 2, 4, 20, 65, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 16:16:19', 2, 'free'),
(11154, '64-کدام گزینه، در خصوص بخش‌های مختلف گوش انسان نادرست است؟', 2, 4, 20, 67, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 16:16:40', 2, 'free'),
(11155, '65-کدام مورد، در خصوص ساختارهای بیضی‌شکل، برجسته و محصورشده در بافت پوششی سنگ‌فرشی چندلایه زبان که در ایجاد پیام چشایی دخالت دارد، نادرست است؟', 2, 4, 20, 69, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 16:18:41', 2, 'free'),
(11156, '66-پس از لرزش پردهٔ انتهای مجرای شنوایی، به منظور بازشدن کانال‌های دریچه‌دار پتاسیمی غشای گیرنده‌های مکانیکی شنوایی، کدام مورد زیر اتفاق می‌افتد؟', 2, 4, 20, 67, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 16:19:01', 2, 'free'),
(11157, '67-مطابق با اطلاعات کتاب درسی، در خصوص مقایسهٔ بیماری‌های چشم انسان، کدام مورد درست است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11158, '68-در خصوص گیرنده‌های حواس پیکری موجود در پوست یک فرد سالم، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌منظور تحریک .......................... همواره لازم است تا ..........................»', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11159, '69-با توجه به مطالب کتاب درسی، همهٔ ساختارهایی از کرهٔ چشم انسان که در تماس با مایع زلالیه برخلاف زجاجیه قرار دارند، چه ویژگی مشترکی با یکدیگر دارند؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11160, '70-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول در انسان، همهٔ گیرنده‌های حس ویژه‌ای که توسط استخوان پهن گیجگاهی محافظت می‌شوند، از نظر .......................... به یکدیگر شباهت و از نظر .......................... با یکدیگر تفاوت دارند.»', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11161, '71-چند مورد به منظور تکمیل عبارت زیر نامناسب است؟\n\n«در اندامی از یک انسان سالم که گیرنده‌های متعلق به دو نوع حس ویژه را در خود جای داده است، همهٔ ..........................»\n\nالف) مایعاتی که در تحریک گیرنده‌های حس ویژه نقش دارند، مستقیماً با بخشی از ساختار این گیرنده‌ها در تماس هستند.\n\nب) پیام‌های هدایت‌شده توسط اعصاب خروجی از هر یک از این اندام‌ها، در نهایت، تنها در قشر چین‌خوردهٔ مخ استفاده می‌شوند.\n\nج) گیرنده‌های تعادلی مژک‌دار در بخشی از طول مجاری نیم‌دایرهٔ عمود برهم قابل مشاهده هستند.\n\nد) گیرنده‌های حس ویژه، زوائد مژکی خود را کاملاً درون نوعی مادهٔ ژلاتینی فرو برده‌اند.', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11162, '72-در خصوص مشاهده اجسام دور و نزدیک در چشم یک فرد سالم، کدام موارد به نادرستی بیان شده‌اند؟\n\nالف) در پی تغییر قطر ساختار شفاف کره چشم، به طور حتم، وضعیت یاخته‌های ماهیچه‌ای بخش مژگانی تغییر می‌کند.\n\nب) در پی تغییر کشیدگی تارهای آویزی، به طور حتم، فاصله بخش رنگین چشم از ساختاری شفاف تغییر می‌کند.\n\nج) کاهش میزان همگرایی پرتوهای نوری، ممکن است منجر به کشیده‌شدن برخی از اجزای لایه میانی چشم شود.\n\nد) کاهش فضای بخش شفاف غیریاخته‌ای چشم، ممکن است منجر به افزایش فشار وارد شده بر زلالیه چشم شود.', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11163, '73-مطابق با متن کتاب درسی سال یازدهم، لازمهٔ درک مزهٔ غذایی، فعالیت گیرنده‌های شیمیایی حس ویژه با یکدیگر است. در خصوص این مطلب، مشخصه مشترک تمام این گیرنده‌ها در کدام گزینه به درستی بیان شده است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11164, '74-کدام عبارت، مناسب‌ترین گزینه دربارهٔ گیرنده‌های چشایی در انسان محسوب می‌شود؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11165, '75-با توجه به شکل زیر و با فرض اینکه مناطق موردنظر در داخل کرهٔ چشم انسان قرار گرفته باشند، کدام عبارت درست است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11166, '76-کدام ویژگی، گیرنده‌های موجود در سقف حفرهٔ بینی را از گیرنده‌های درون جوانهٔ چشایی، متمایز می‌سازد؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11167, '77-کدام مورد یا موارد زیر، در خصوص استخوانی از گوش میانی که ضمن تشکیل مفصل متحرک، در بخشی از ساختار خود، قطر کم‌تری نسبت به سایر استخوان‌های گوش میانی دارد، درست است؟\n\nالف: همانند استخوانی که به انتهای مجرای شنوایی نزدیک‌تر است، به بخشی از سقف گوش میانی متصل است.\n\nب: برخلاف استخوانی که از سایر استخوان‌ها قطر بیش‌تری دارد، ارتعاشات را مستقیماً از پرده صماخ دریافت می‌کند.\n\nج: برخلاف استخوانی که بر روی نوعی دریچه مربوط به گوش قرار دارد، دو مفصل متحرک در گوش میانی تشکیل می‌دهد.\n\nد: همانند استخوانی که از دو محل به سقف گوش میانی انسان متصل است، در ارسال پیام عصبی به گوش درونی دخیل است.', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11168, '78-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در مرکز عصب بینایی چشم راست انسان، دو نوع رگ خونی وجود دارد. (در) رگی که جهت جریان خون در آن .......................... جهت انتشار پیام عصبی در رشته‌های عصب بینایی مجاور است، .......................... رگ دیگر، .......................... .»', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11169, '79-کدام مورد برای تکمیل عبارت زیر نامناسب است؟\n\n«به‌طور معمول فقط بعضی از یاخته‌های ایجاد کنندهٔ پیام عصبی در بدن که .......................... .»', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11170, '80-به طور معمول، کدام دو ویژگی، در مورد یکی از بخش‌های تشکیل دهندهٔ گوش یک فرد سالم و بالغ، درست است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11171, '81-به گذرگاه ماهیچه‌ای در لولهٔ گوارش، حفراتی با توانایی عبور هوای بازدمی از خود، راه دارند که محتوی گیرنده‌هایی از حواس ویژه هستند. ویژگی متمایزکنندهٔ این گیرنده‌ها، کدام یک از موارد زیر است؟\n\nالف: در تماس با یاخته‌هایی دراز و باریک قرار دارند.\n\nب: در تغییر فعالیت یاخته‌های عصبی سامانهٔ کناره‌ای مؤثر هستند.\n\nج: در تحریک بخشی از قشر مخ که مربوط به درک مزه است، مؤثر می‌باشند.\n\nد: اثر محرک را از طریق رشتهٔ عصبی خود، به قسمت‌های دیگری هدایت می‌کنند.', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11172, '82-با توجه به مطالب کتاب درسی، در خصوص گیرنده‌هایی که در بخش‌های مختلف بدن انسان پراکنده‌اند، کدام مورد نادرست است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11173, '85-در خصوص داخلی‌ترین بخش لایهٔ میانی کرهٔ چشم انسان، کدام مورد درست است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11174, '86-باتوجه‌به تصویر زیر که با استفاده از نوعی دستگاه ویژه، هنگام مشاهدهٔ شبکیهٔ چشم از مردمک گرفته شده است، کدام مورد نادرست است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11175, '87-کدام گزینه، عبارت زیر را به طور نامناسب کامل می‌کند؟\n\n«در ساختار گوش درونی انسان، .......................... گیرنده‌های مکانیکی که در مجاورت با مادهٔ ژلاتینی هستند، .......................... .»', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11176, '88-مطابق با شکل زیر، بیماری چشم فردی با استفاده از نوعی عدسی برطرف می‌شود. در ارتباط با چشم غیرمسلح (بدون عینک) در این فرد، کدام مورد صحیح است؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11177, '89-با توجه به مطالب کتاب درسی، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در .......................... افرادی که به‌دلیل نوعی بیماری چشمی .......................... .»', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11178, '90-در چشم یک انسان سالم، پس از برخورد نور به شبکیه کدام اتفاق قبل از سایرین رخ می‌دهد؟', 2, 4, 20, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, NULL, NULL, 'free'),
(11179, '91-با توجه به اطلاعات کتاب درسی، کدام عبارت دربارهٔ گیرنده‌های حسی که در بخش‌های گوناگون بدن حضور دارند و تحت‌تأثیر محرک‌ها به تولید پیام عصبی می‌پردازند، نادرست است؟', 2, 4, 20, 63, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 15:30:24', 2, 'free'),
(11180, '92-با توجه به مطالب کتاب درسی، پس از ورود فردی سالم به محیطی که در آن شرایط جهت انتقال پیام عصبی از بخش سمپاتیک دستگاه عصبی خودمختار به گروهی از ماهیچه‌های عنبیه فراهم می‌شود، نوع ویژه‌ای از گیرنده‌های نوری شبکیه تحریک می‌شوند. کدام عبارت، دربارهٔ این نوع از گیرنده‌های نوری درست است؟', 2, 4, 20, 64, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 15:31:16', 2, 'free'),
(11181, '93-با توجه به اطلاعات جمع‌آوری‌شده از تشریح چشم گاو، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n« در چشم گاو، .......................... معادل بخشی از چشم انسان است که .......................... .»', 2, 4, 20, 66, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:14', 1, '2026-09-17 15:31:51', 2, 'free'),
(11182, '1-با توجه به شکل مقابل که نشان‌دهندۀ تصویری میکروسکوپی از بخشی از یک یاختۀ ماهیچۀ اسکلتی است، کدام عبارت درست است؟', 2, 4, 21, 75, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11183, '2-کدام عبارت، دربارۀ ساختار و اعمال ماهیچه‌های اسکلتی بدن انسان، درست است؟', 2, 4, 21, 75, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11184, '3-چند مورد، برای تکمیل عبارت زیر به‌طور حتم صادق است؟\n\n«در یک انسان بالغ، بخش اعظم ................. استخوان ران از بافتی تشکیل شده است که .................»\n\nالف: سر - به‌دنبال مصرف نوشابه‌های گازدار به مقدار بیشتری تخریب می‌شود.\n\nب: تنه - در مجاورت خود رگ‌های خونی و رشته‌های عصبی و مغز زرد دارد.\n\nج: سر - از میله‌ها و صفحات استخوانی نامنظم تشکیل شده است.\n\nد: تنه - در بین یاخته‌های خود حفره‌های نامنظم زیادی دارد.', 2, 4, 21, 73, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11185, 'چند مورد، دربارۀ انسان درست است؟\n\nالف: بین سنین ۲۰ تا ۵۰ سالگی، شدت تغییرات تراکم استخوان در مردان بیشتر از زنان است.\n\nب: هر یاختۀ سازندۀ یاخته‌های استخوانی جدید، مربوط به بافتی فاقد نمک‌های کلسیم است.\n\nج: در دوران جنینی نسبت به دوران بلوغ، تراکم مادۀ زمینه‌ای استخوان‌ها کمتر است.\n\nد: در فرد مصرف‌کنندۀ سیگار، سرعت تخریب یاخته‌های استخوانی افزایش می‌یابد.', 2, 4, 21, 72, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11186, '5-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در تنۀ استخوان ران، یاخته‌های استخوانی که ................. هستند، به‌طور حتم .................»', 2, 4, 21, 73, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11187, '6-درخصوص انواع بافت‌های قابل مشاهده در استخوان، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در فردی سالم و بالغ، بافتی که بخش عمدۀ ................. به‌طور حتم .................»', 2, 4, 21, 73, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11188, '7-در ارتباط با اطلاعات کتاب درسی، کدام مورد یا موارد برای تکمیل عبارت زیر مناسب هستند؟\n\n«به‌منظور ................. لازم است تا ................. صورت گیرد.»\n\nالف: حفظ دمای بدن در محدودۀ طبیعی - فعالیت سوخت‌وسازی یاخته‌های ماهیچه‌ای چند‌هسته‌ای\n\nب: ساخت یاخته‌های استخوانی - تقسیم و تمایز یاخته‌ها در صفحات غضروفی نزدیک به دو انتهای استخوان‌ها\n\nج: نگهداری بدن به صورت قائم - اتصال ماهیچه‌ها به استخوان‌ها از طریق زردپی و ایجاد انقباضات کنترل‌شده\n\nد: ایجاد پوکی استخوان - افزایش مصرف انواعی از مواد غذایی در جهت جلوگیری از رسوب کلسیم در استخوان', 2, 4, 21, 71, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11189, 'با توجه به اطلاعات کتاب درسی، کدام عبارت دربارۀ پروتئین‌های سازندۀ واحدهای تکراری در ساختار تارچه‌ها درست است؟', 2, 4, 21, 75, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11190, 'کدام عبارت دربارۀ فقط بعضی از ماهیچه‌های اسکلتی بدن انسان درست است؟', 2, 4, 21, 76, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11191, 'نوعی ساختار در مفصل زانو وجود دارد که ممکن است بخشی از آن در اثر کارکرد زیاد، ضربات، آسیب‌ها و بعضی بیماری‌ها تخریب شود ولی بدن دوباره آن را ترمیم کند. چند مورد در ارتباط با این ساختار درست است؟\n\nالف: هر ساختار مفصلی که در تماس با آن قرار دارد، به سطح خارجی استخوان متصل است.\n\nب: هر ساختار مفصلی که فاقد تماس با آن است، یاخته‌هایی با توانایی انجام قندکافت (گلیکولیز) دارد.\n\nج: هر ساختار مفصلی که در تماس با آن قرار دارد، اصطکاک استخوان‌ها در محل مفصل را از بین می‌برد.\n\nد: هر ساختار مفصلی که فاقد تماس با آن است، به نگه‌داشتن استخوان‌ها در کنار یکدیگر کمک می‌کند.', 2, 4, 21, 74, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11192, '11-مطابق با اطلاعات کتاب درسی، کدام مورد در ارتباط با کودکی ۱۰ ساله و چاق که فعالیت بدنی بسیار اندکی دارد، صحیح است؟', 2, 4, 21, 77, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11193, 'درخصوص مراحل انقباض ماهیچۀ چهار سر ران در یک تار ماهیچه‌ای، کدام عبارت صحیح است؟', 2, 4, 21, 76, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11194, 'درخصوص ساختار اسکلت بدن انسان، کدام مورد یا موارد زیر درست است؟\n\nالف: در نمای پشتی، اتصال استخوان ترقوه به زائده‌ای از استخوان کتف مشاهده می‌شود.\n\nب: در نمای جلویی، دو سطح مفصلی استخوان ران برای ایجاد مفصل با درشت‌نی مشاهده می‌شود.\n\nج: در نمای پشتی، محل اتصال دندۀ اول به استخوان جناغ، در سطح بالاتری از محل اتصال ترقوه قرار دارد.\n\nد: در نمای جلویی، محل اتصال استخوان نیم‌لگن به اسکلت محوری، هم‌سطح با مفصل بین دو استخوان نیم‌لگن قرار دارد.', 2, 4, 21, 71, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11195, '14-دربارۀ تغییرات تارهای ماهیچه‌ای در یک دوندۀ دوی صد متر که تمرین‌های ورزشی جدیدی را به‌منظور شرکت در دوی ماراتن انجام می‌دهد، کدام عبارت درست است؟', 2, 4, 21, 77, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11196, 'کدام عبارت، دربارۀ استخوان‌های موجود در ناحیۀ بازو و ساعد انسان، به‌طور حتم، درست می‌باشد؟', 2, 4, 21, 74, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:20', 1, NULL, NULL, 'free'),
(11197, 'با توجه به وقایع یک چرخۀ اتصال سر میوزین به اکتین و سپس جدا شدن آن، کدام گزینه، ترتیب صحیح مراحل را بیان می‌کند؟ (شروع چرخه از زمان اضافه‌شدن ATP است.)\n\nالف: حرکت مستقیم سر میوزین به سمت رشتۀ اکتین\n\nب: ایجاد بیشترین زاویه بین سر میوزین و دم آن\n\nج: وجود کمترین فاصله بین دم میوزین و اکتین\n\nد: وجود کمترین فاصله بین سر میوزین و دم آن', 2, 4, 21, 76, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11198, '17-کدام‌یک از موارد زیر، دربارۀ ساختار گوش درست می‌باشد؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
