(11200, 'کدام عبارت درست است؟', 2, 4, 21, 73, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11201, '20-از میان عبارات زیر، کدام‌یک دربارۀ دستگاه حرکتی انسان درست می‌باشد؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(11202, ' درستی کدام گزینه در رابطه با استخوان‌ها، با سایر گزینه‌ها تفاوت دارد؟', 2, 4, 21, 73, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11203, ' در ساختار ماهیچۀ دوسر بازو، .................', 2, 4, 21, 75, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11204, '23- کدام گزینه در مورد شکل روبه‌رو به‌درستی بیان شده است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11205, ' در مقایسۀ بافت استخوانی فشرده با بافت استخوانی اسفنجی، کدام گزینه درست است؟', 2, 4, 21, 73, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11206, ' به‌طور معمول در بدن انسان نوعی بافت استخوانی که در طول استخوان ران به‌صورت واحدهایی تشکیل شده از تیغه‌های استخوانی مشاهده می‌شود .................', 2, 4, 21, 73, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11207, '26- کدام گزینه از نظر درستی یا نادرستی جملۀ زیر را متفاوت با سایرین کامل می‌کند؟\n\n«با نزدیک شدن فاصلۀ دو خط Z در سارکومر ................. »', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11208, 'کدام موارد جملۀ زیر را به‌درستی کامل می‌نماید؟\n\n«در سازوکار انقباض ماهیچۀ اسکلتی متصل به صلبیه در پی ................. »\n\nالف) مصرف ATP می‌تواند ضمن ثابت ماندن طول نوار تیره، نوار روشن کوتاه گردد\n\nب) ورود ناقل عصبی به تار ماهیچه‌ای، کلسیم به درون تارچه وارد می‌گردد\n\nج) تغییرشکل در ساختار چهارم مولکول میوزین دو خط Z به هم نزدیک می‌شوند\n\nد) ورود کلسیم به درون شبکۀ آندوپلاسمی شیب کلسیم بین طرفین غشای شبکۀ آندوپلاسمی کاهش می‌یابد', 2, 4, 21, 76, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11209, '28- آن دسته از یاخته‌های ماهیچۀ اسکلتی که مدت زمان لازم برای تشکیل و جدا شدن پل‌های اتصال اکتین و میوزین در آن‌ها نسبت به یاخته‌های نوع دیگر ماهیچۀ اسکلتی بیشتر است .................', 2, 4, 21, 77, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11210, ' در مورد شکل روبه‌رو کدام گزینه درست است؟', 2, 4, 21, 77, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11211, '30- چند مورد از عبارت‌های زیر درست است؟\n\nالف) سَرِ برجستۀ بلندترین استخوان بدن، در مفصل گوی و کاسه شرکت دارد.\n\nب) مفصل استخوان‌های جمجمه، فاقد بافت غضروفی است.\n\nج) کپسول مفصلی همانند رباط، نوعی بافت پیوندی رشته‌ای است.\n\nد) بافتِ سطح درونی تنۀ بلندترین استخوان بدن، فاقد سیستم هاورس است.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11212, '31- در دستور انقباض ماهیچه، پس از اتصال ناقلین عصبی به گیرنده‌های خود در سطح یاختۀ ماهیچه‌ای، کدام اتفاق زودتر از سایرین رخ می‌دهد؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11213, '32- کدام عبارت، جملۀ زیر را به‌نادرستی تکمیل می‌نماید؟\n\n«همۀ ماهیچه‌های اسکلتی ................. »', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11214, '33- کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در ماهیچه‌های متصل به استخوان در انسان ................. »', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11215, '34- کدام گزینه جملۀ زیر را به‌درستی کامل می‌کند؟\n\n«در رابطه با اسکلت آدمی می‌توان گفت قطعاً ................. »', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11216, '35- با توجه به ساختار استخوان کدام مورد درست است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11217, '36- کدام گزینه عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n«طی انقباض سارکومر، مرحلۀ نشان داده شده در شکل روبه‌رو، هنگامی مشاهده می‌شود که ................. آن ................. »', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11218, '37- با توجه به شکل مقابل، چند عبارت صحیح است؟\n\nالف) بخش ۳ برخلاف بخش ۲، به بافتی متشکل از انواع یاخته‌ها، مادۀ زمینه‌ای و رشته‌های پروتئینی تعلق دارد.\n\nب) بخش ۱ همانند بخش ۴، در سطح خارجی خود با ساختاری متشکل از بافت پیوندی در تماس است.\n\nج) بخش ۲ همانند بخش ۴، در کاهش اصطکاک استخوان‌ها در محل مفصل نقش ایفا می‌کند.\n\nد) بخش ۳ برخلاف بخش ۲، به کنار یکدیگر ماندن استخوان‌ها کمک می‌کند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11219, '38- کدام گزینه در رابطه با فرایند انقباض ماهیچه‌ها، همواره صحیح است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11220, '39- کدام مورد، عبارت مقابل را به‌طور مناسب کامل می‌کند؟ «در شناگران، فعالیت انقباضی ماهیچه‌ها، بیشتر بر عهدۀ تارهایی است که این تارها، نسبت به یاخته‌های ماهیچه‌ای اسکلتی فراوان‌تر در وزنه‌برداران، ................. کمتری دارند.»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11221, '40- با در نظر گرفتن واحدهای تکرار شوندۀ انقباضی سیتوپلاسم تارهای عضلانی، هر رشتۀ پروتئینی که .................، به‌طور حتم .................', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11222, '41- با توجه به مطالب ذکر شده در کتاب درسی زیست‌شناسی یازدهم، کدام موارد در ارتباط با تنۀ استخوان ران انسان، همواره صادق است؟\n\nالف) خارجی‌ترین یاخته‌ها همانند داخلی‌ترین یاخته‌ها، برای بعضی از هورمون‌های آزاد شده در ناحیۀ گردن گیرنده دارند.\n\nب) داخلی‌ترین یاخته‌ها برخلاف خارجی‌ترین یاخته‌ها، ظاهری انگشتری شکل با هستۀ حاشیه‌ای دارند.\n\nج) خارجی‌ترین یاخته‌ها برخلاف داخلی‌ترین یاخته‌ها، در سطح زیرین خود رشته‌های ریزی دارند.\n\nد) داخلی‌ترین یاخته‌ها همانند خارجی‌ترین یاخته‌ها، فضای بین یاخته‌ای زیادی دارند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11223, '42- با توجه به مطالب کتاب درسی در ارتباط با محل قرارگیری اجزای مختلف اسکلت بدن انسان، کدام مورد به شیوۀ متفاوتی نسبت به سایرین بیان شده است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11224, '43- کدام یک از گزینه‌های زیر با توجه به شکل مقابل، نادرست است؟\n\n۱) بخش ۳ برخلاف بخش ۲، به بافتی متشکل از انواع یاخته‌ها، مادۀ زمینه‌ای و رشته‌های پروتئینی تعلق دارد.\n\n۲) بخش ۱ همانند بخش ۴، در سطح خارجی خود با ساختاری متشکل از بافت پیوندی در تماس است.\n\n۳) بخش ۲ همانند بخش ۴، در کاهش اصطکاک استخوان‌ها در محل مفصل نقشی ایفا می‌کند.\n\n۴) بخش ۳ برخلاف بخش ۲، به کنار یکدیگر ماندن استخوان‌ها در محل مفصل کمک می‌کند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11225, '44- به‌طور معمول، کدام مورد در رابطه با استخوان ران یک کودک ۱۰ ساله صحیح است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11226, '45- کدام موارد زیر، در رابطه با استخوان‌ها و عوامل مؤثر بر تراکم آن‌ها نادرست است؟\n\nالف: نوشیدنی‌های الکلی، دخانیات و نوشابه‌های گازدار با جلوگیری از رسوب کلسیم در استخوان‌ها، باعث پوکی استخوان می‌شوند.\n\nب: نوعی بافت استخوانی که در تصویر رادیوگرافی روشن‌تر است، طی پوکی استخوان آسیب بیشتری را متحمل می‌شود.\n\nج: ترشح مادۀ زمینه‌ای کلسیم‌دار توسط یاخته‌های دوکی شکل استخوانی، پس از سن رشد، متوقف نمی‌شود.\n\nد: در پوکی استخوان، تعداد و اندازۀ حفرات موجود در استخوان‌ها به طرز چشمگیری افزایش می‌یابد.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11227, '46- کدام عبارت، برای تکمیل عبارت زیر نامناسب است؟\n\n«جمجمه از چندین استخوان تشکیل شده است. استخوانی از آن که منحصراً از بزرگ‌ترین لوب مخ محافظت می‌کند، در تماس با استخوانی است که .................»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11228, '47- کدام عبارت، در ارتباط با بخش‌های تشکیل‌دهندۀ مفاصل متحرک، صحیح است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11229, '48- با توجه به شکل‌های زیر که انواع مفصل‌های متحرک را در فرد سالم نشان می‌دهند، کدام مورد نادرست است؟\n\n۱) مفصل «الف»، در محل اتصال سر استخوان بازو به گودی استخوان کتف یافت می‌شود.\n\n۲) مفصل «ج»، به تعداد بسیار زیادی در سمت جلویی بزرگ‌ترین استخوان‌های نامنظم ناحیۀ شکمی قرار می‌گیرد.\n\n۳) مفصل «ب» به همراه نواری متصل به استخوان زند زبرین، به کنار هم ماندن استخوان‌های بازو و ساعد کمک می‌کند.\n\n۴) در همۀ این مفاصل، بخش ترمیم‌شونده و بخش سازندۀ مایع مفصلی، به یاخته‌هایی پهن و نزدیک به هم متصل می‌شوند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11230, '49- در صورتی که جدایی میوزین از اکتین را مرحلۀ اول از مراحل چهارگانۀ انقباض ماهیچه در نظر بگیریم، کدام عبارت به‌درستی بیان شده است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11231, '50- کدام مورد، برای تکمیل عبارت مقابل نامناسب است؟ «اغلب تارهای ماهیچۀ چهارسر ران یک شناگر حرفه‌ای در مقایسه با یک دوندۀ دوی صد متر، .................» (با فرض اینکه دو ورزشکار قبل از شروع تمرینات ورزشی، تودۀ عضلانی مشابهی داشته‌اند.)', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11232, '51- چند مورد، در ارتباط با روش‌های تأمین انرژی انقباض ماهیچه‌های اسکلتی، برای تکمیل عبارت زیر نامناسب است؟\n\n«در روشی که .................، می‌توان ................. را مشاهده کرد.»\n\nالف: تا چند دقیقه، انرژی لازم برای ساخت ATP را فراهم می‌کند - آب‌کافت بسپاری ذخیره‌شده، تحت‌تأثیر هورمون پانکراسی\n\nب: برای انقباض طولانی‌تر قابل استفاده است - به دنبال استفاده از ماده‌ای فاقد فسفات، شرایطی مشابه دیابت شیرین\n\nج: در فعالیت‌های شدید مورد استفاده قرار می‌گیرد - فعالیت فوری نوعی آنزیم کاهندۀ اثرات درد ماهیچه‌ای\n\nد: برای باز تولید سریع ATP انجام می‌شود - تبدیل نوعی مادۀ تک فسفاتۀ انرژی‌زا به کرآتینین', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11233, '52- موارد مطرح‌شده در کدام گزینه عبارت زیر را به طرز مناسبی کامل می‌کنند؟\n\n«هر استخوان ................. که با استخوان ................. مفصل تشکیل می‌دهد، به‌طور حتم .................»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11234, '53- در رابطه با ساختار بلندترین استخوان انسان، چند مورد از عبارت‌های زیر صحیح بیان نشده است؟\n\nالف) هر نوع مغز استخوان در مجاورت مستقیم با نوعی بافت استخوانی قرار دارد که فاقد اجزای میله‌ای و صفحه‌ای نامنظم است.\n\nب) میان هر دو سامانۀ هاورس مجاور، یک لایه از یاخته‌های بافت فشرده دیده می‌شود که در استوانه‌های هاورسی قرار ندارند.\n\nج) در هر مجرایی از بافت فشرده که از عرض استوانۀ هاورس می‌گذرد، نوعی سرخرگ بالاتر از نوعی سیاهرگ قرار دارد.\n\nد) هر یاختۀ دارای زوائد سیتوپلاسمی منشعب در این استخوان، با ترشح مادۀ زمینه‌ای تراکم استخوان را زیاد می‌کند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11235, '54- کدام گزینه در ارتباط با ساختارهای تشکیل شونده از تجمع بافت پیوندی اطراف دسته‌تارهای ماهیچه‌ای در انتهای عضلات صحیح بیان نشده است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11236, '55- کدام گزینه در مورد ساختار سارکومر یک یاختۀ ماهیچۀ اسکلتی به درستی بیان شده است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11237, '56- چه تعداد از موارد داده شده، جملۀ زیر را به نادرستی کامل می‌کند؟\n\n«به‌طور معمول، فقط تارهای ماهیچه‌ای نوع ................. می‌توانند .................»\n\nالف) کند - مولکول‌های پرانرژی را در راکیزه (میتوکندری)های خود تولید نمایند.\n\nب) تند - انرژی حاصل از تجزیۀ گلوکز را به صورت بی‌هوازی بدست آورند.\n\nج) کند - از نوعی رنگدانۀ پروتئینی برای ذخیرۀ اکسیژن استفاده کنند.\n\nد) تند - در ماهیچه‌های اسکلتی افراد وزنه‌بردار حضور داشته باشند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11238, '57- با توجه به مطالب کتاب درسی، برای انقباض ماهیچۀ سه سر بازو، قبل از تغییر زاویۀ بین سر و دم مولکول میوزین، غلظت گروهی از یون‌های مثبت مادۀ زمینه‌ای سیتوپلاسم یاختۀ ماهیچه‌ای افزایش پیدا می‌کند. کدام گزینه در رابطه با همۀ این یون‌ها قطعاً صحیح است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11239, '58- با توجه به انواع مفاصل متحرک مطرح‌شده در کتاب درسی، کدام دو عبارت درست است؟\n\nالف) در هر مفصل متحرک، حفرۀ مفصلی پر از هوا، جلوی درهم فرو رفتن استخوان‌ها را می‌گیرد.\n\nب) فقط در بعضی از مفاصل متحرک، استخوان‌های تقریباً مشابه، در مجاورت یکدیگر لیز می‌خورند.\n\nج) فقط در بعضی از مفاصل متحرک، سطح محدب نوعی استخوان، در نزدیکی سطح مقعر استخوان دیگر قرار می‌گیرد.\n\nد) در هر مفصل متحرک، رباط‌ها دارای رشته‌های پروتئینی محکم هستند و تنۀ استخوان‌ها را به یکدیگر متصل می‌کنند.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11240, '59- کدام عبارت، دربارۀ یاخته‌های استخوانی که در فاصلۀ بین بافت پیوندی سطح خارجی تنۀ استخوان ران و بافت استخوانی اسفنجی قرار دارند، درست است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11241, '60- کدام عبارت در مقایسه با سایر عبارت‌ها، درخصوص تعداد بیشتری از انواع مفاصل بدن صحیح است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11242, '61- با توجه به شکل مقابل، کدام عبارت نادرست است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11243, '62- درخصوص ساختار اسکلت بدن انسان، کدام مورد یا موارد زیر درست است؟\n\nالف: در نمای پشتی، اتصال استخوان ترقوه به زائده‌ای از استخوان کتف مشاهده می‌شود.\n\nب: در نمای جلویی، دو سطح مفصلی استخوان ران برای ایجاد مفصل با درشت‌نی مشاهده می‌شود.\n\nج: در نمای پشتی، محل اتصال دندۀ اول به استخوان جناغ، در سطح بالاتری از محل اتصال ترقوه قرار دارد.\n\nد: در نمای جلویی، محل اتصال استخوان نیم‌لگن به اسکلت محوری، هم‌سطح با مفصل بین دو استخوان نیم‌لگن قرار دارد.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11244, '63- در کدام مورد، هر دو ویژگی ذکرشده، فقط مربوط به یک نوع تار ماهیچه‌ای تند یا کند است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11245, '64- با توجه به شکل ۶ فصل ۳ زیست شناسی یازدهم، کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول ................. استخوان‌هایی که با ................. از جمجمه مفصلی بدون توانایی حرکت می‌سازند، در تشکیل ................. نقش دارند.»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11246, '65- به طور معمول ورزش‌های طولانی مدت در انسان به ترتیب موجب افزایش و کاهش موارد مطرح‌شده در کدام گزینه می‌شود؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11247, '66- کدام مورد تکمیل‌کنندۀ مناسبی برای عبارت زیر است؟\n\n«با توجه به مفاهیم کتاب درسی، آن دسته از تارهای ماهیچه‌ای که به عنوان تارهای غالب در عضلات پای یک دوندۀ ماراتون شناخته می‌شوند، نسبت به تارهای دیگر این عضلات، ................. بیشتر و ................. کمتر دارند.»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11248, '67- به منظور ورود هوای جاری به شش‌های انسان باید گروهی از ماهیچه‌های اسکلتی بدن منقبض شوند. با توجه به این موضوع می‌توان گفت به هنگام انقباض این ماهیچه‌ها، ................. بلافاصله پس از ................. رخ می‌دهد.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11249, '68- چند مورد برای تکمیل عبارت مقابل مناسب است؟ «در بدن انسان، نوعی استخوان ................. مفصل متحرک دارد.»\n\nالف) نامنظم با نوعی استخوان پهن و نوعی استخوان نامنظم دیگر\n\nب) دراز در ناحیۀ ساق پا، با نوعی استخوان کوتاه و نوعی استخوان دراز\n\nج) محافظ اجزای قفسۀ سینه، با نوعی استخوان پهن و نوعی استخوان نامنظم\n\nد) پهن در قفسۀ سینه، با بعضی از استخوان‌های اسکلت محوری و اسکلت جانبی', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11250, '69- کدام گزینه عبارت زیر را به درستی تکمیل می‌کند؟\n\n«در تنۀ استخوان ران یک فرد سالم و بالغ، خارجی‌ترین یاخته‌های بافت استخوانی اسفنجی ................. یاخته‌هایی که بلافاصله در سمت داخلی یاخته‌های به‌هم‌فشرده و پهن و نازک واقع شده‌اند ................. »', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11251, '70- با توجه به شکل مقابل، کدام گزینه صحیح است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11252, '71- با در نظر گرفتن انواع بافت‌های استخوانی در یک فرد بالغ، کدام گزینۀ زیر درست است؟', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11253, '72- کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«آن دسته از تارهای ماهیچۀ اسکلتی که ................. در آن‌ها کم‌تر از سایر تارهاست، .................»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11254, '73- هنگامی که فاصلۀ دو استخوان ساعد و بازو ................. می‌یابد، در ماهیچۀ دوسر بازو ................. می‌شود.', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11255, '74- باتوجه‌به استخوان‌های شرکت‌کننده در تشکیل قفسۀ سینه، کدام گزینه، عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«به طور معمول در انسان، هر استخوانی که .................»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11256, '75- کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«به طور معمول، در تخریب بافت‌های استخوانی در طول زندگی یک فرد سالم، .................»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
(11257, '76- با توجه به شکل ۶ فصل ۳ زیست‌شناسی یازدهم، کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول ................. استخوان‌هایی که با ................. از جمجمه مفصلی بدون توانایی حرکت می‌سازند، در تشکیل ................. نقش دارند.»', 2, 4, 21, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:56:21', 1, NULL, NULL, 'free'),
