(11375, 'کدام گزینه در رابطه با یاختۀ ایمنی زیر به‌درستی بیان شده است؟\n\n«این یاخته، میکروب‌ها را شناسایی می‌کند و با نوعی درون‌بری، آن‌ها را از بین می‌برد. همچنین در رگ لنفی مشاهده می‌شود، اما به‌طور معمول در رگ‌های خونی یافت نمی‌شود.»', 2, 4, 23, 90, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11376, '24-چند مورد دربارۀ دفاع اختصاصی بدن به‌نادرستی بیان شده است؟\n\nالف) لنفوسیتی که گیرندۀ آن مشابه با مولکول آنتی‌ژن است، می‌تواند آنتی‌ژن را شناسایی کند.\n\nب) فاصلۀ بین شناسایی آنتی‌ژن برای اولین بار توسط یاخته خاطره و تقسیم شدن آن، گاه به یک هفته می‌رسد.\n\nج) هر لنفوسیت T کشنده، مشابه روش‌های موجود در خط دوم دفاع غیراختصاصی، تنها یاخته‌های بیگانه را از بین می‌برد.\n\nد) یاخته‌های پادتن‌ساز، (پلاسموسیت‌ها) دستگاه گلژی گسترده‌ای برای ترشح پروتئینی با سه جایگاه اتصال دارند.', 2, 4, 23, 95, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11377, '25-کدام گزینه عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n«مطابق با مطالب کتاب درسی، همۀ یاخته‌هایی که توانایی ترشح هیستامین را دارند ....................... .»', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11378, '26-کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در ارتباط با هر نوع گویچۀ سفید که ....................... می‌توان گفت ....................... .»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11379, '27-کدام عبارت ویژگی همۀ گویچه‌های سفید سالمی است که توانایی بیگانه‌خواری را ندارند، اما با ترشح نوعی پروتئین در دفاع از بدن نقش ایفا می‌کنند؟', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11380, '28-در التهاب به‌دنبال رها شدن هیستامین از نوعی یاخته، گویچه‌های سفید بیشتری به محل آسیب هدایت می‌شوند، کدام گزینه دربارۀ این یاخته‌ها نادرست است؟', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11381, 'در انسان یاخته‌هایی وجود دارند که با ترشح نوعی پروتئین نقش مهمی در مبارزه علیه یاخته‌های سرطانی ایفا می‌کنند. کدام عبارت دربارۀ همۀ این یاخته‌ها درست است؟\n\nالف) با ترشح پروتئینی به‌نام پرفورین در غشای یاخته‌ای میکروب منفذ ایجاد می‌کنند.\n\nب) در انجام عملکرد صحیح خط دوم دفاعی بدن دارای نقش هستند.\n\nج) گیرنده‌های پادگنی (آنتی‌ژنی) دارند که همگی از یک نوع هستند.\n\nد) توانایی عبور از دیوارۀ مویرگ را دارا می‌باشند.', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11382, 'به‌دنبال شناسایی پادگن (آنتی‌ژن) توسط یک لنفوسیت برای اولین بار در بدن، این لنفوسیت تکثیر شده و دو نوع یاخته از آن حاصل می‌شوند، کدام عبارت ویژگی همۀ این یاخته‌هاست؟', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11383, 'با توجه به روش‌های نحوۀ عملکرد پادتن که در کتاب درسی به آن اشاره شده است، کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در ارتباط با روش‌های غیرفعال‌سازی پادگن (آنتی‌ژن) در روش ....................... هر ....................... به یک ....................... متصل است.»', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11384, '32-کدام‌یک از جمله‌های زیر به‌نادرستی بیان شده است؟\n\n«در پاسخ ایمنی ثانویه، ....................... .»', 2, 4, 23, 96, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11385, '33-چند مورد از عبارت‌های زیر دربارۀ دستگاه ایمنی انسان درست است؟\n\nالف) تزریق واکسن و سرم سبب تولید یاختۀ خاطره می‌شود. به همین دلیل دفاع اختصاصی است.\n\nب) تزریق سرم موجب افزایش فعالیت درشت‌خوارها می‌شود.\n\nج) ایمنی حاصل از سرم و واکسن، ایمنی فعال است.\n\nد) لنفوسیت‌ها پس از شناسایی پادگن، به لنفوسیت‌های عمل‌کننده و خاطره تقسیم می‌شوند.', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11386, '34-پرفورین ....................... پروتئین مکمل، .......................', 2, 4, 23, 92, NULL, NULL, NULL, NULL, NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11387, '35-در رابطه با نوعی خط دفاعی در بدن انسان که به‌کمک یاخته‌های خونی، واکنش‌های عمومی اما سریعی را انجام می‌دهد، کدام موارد به مطلب درستی اشاره دارند؟\n\nالف) اگر پادگنی که قبلاً وارد بدن شده است، دوباره به بدن وارد شود، پاسخ سریع‌تر و قوی‌تری نسبت به قبل ایجاد می‌کند.\n\nب) توانایی شناسایی عامل بیگانه را دارد و قادر به تشخیص تفاوت عوامل بیگانه نسبت به یکدیگر می‌باشد.\n\nج) نوعی یاختۀ خونی با هستۀ تکی گرد یا بیضی و دارای سیتوپلاسم بدون دانه می‌تواند در این خط فعالیت داشته باشد.\n\nد) یاخته‌های سالم و یاخته‌های آسیب‌دیده می‌توانند در این خط دفاعی فعالیت داشته باشند و به دفاع کمک کنند.', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11388, 'در دستگاه ایمنی انسان هر یاختۀ سازندۀ پروتئین Y شکل .......................', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11389, '37-کدام گزینه، در مورد بیماری‌های مطرح شده در فصل پنجم زیست‌شناسی سال یازدهم درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11390, '38-کدام گزینه در مورد خطوط دفاعی بدن انسان درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11391, 'با توجه به مطالب کتاب درسی، کدام گزینه در رابطه با عمل بیگانه‌خواری و یاخته‌هایی که بیگانه‌خواری می‌کنند، جهت کامل کردن عبارت زیر مناسب نیست؟\n\n«یاخته‌ای که توانایی بیگانه‌خواری دارد، می‌تواند ....................... .»', 2, 4, 23, 90, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11392, 'کدام گزینه جملۀ زیر را به‌درستی تکمیل می‌کند؟\n\n«هر بیگانه‌خوار موجود در بدن، ....................... »', 2, 4, 23, 90, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11393, '41-کدام گزینه در رابطه با پوست بدن به‌درستی بیان شده است؟', 2, 4, 23, 89, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11394, '42-کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«در بدن یک انسان بالغ، هر یاخته‌ای که ....................... دارد، توان تولید و آزادسازی ....................... .»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11395, 'اینترفرون نوع یک ....................... نوع دو، .......................', 2, 4, 23, 92, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11396, '44-کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«در انسان، لنفوسیتی که در دفاع غیراختصاصی نقش دارد، ....................... یاخته‌ای که مانند نیروی واکنش سریع است، ....................... .»', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11397, 'کدام گزینه بیانگر وجه اشتراک همۀ پروتئین‌های دفاعی بدن انسان که تنها در لنفوسیت‌های هر دو خط دوم و سوم دستگاه ایمنی بدن تولید می‌شوند، نیست؟', 2, 4, 23, 92, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11398, '46-کدام گزینه وجه اشتراک بیماری‌های مطرح‌شده در فصل ۵ زیست‌شناسی یازدهم، به حساب می‌آید؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11399, '47-با توجه به شکل‌های زیر، چند مورد به طور صحیح بیان نشده است؟\n\nالف) یاختۀ (۳) همانند (۴)، به منظور عبور از دیوارۀ رگ‌های خونی فاقد لایۀ ماهیچه‌ای، تغییراتی در شکل ظاهری هسته و سیتوپلاسم خود ایجاد می‌کند.\n\nب) یاختۀ (۴) برخلاف (۲) با ایجاد تغییراتی در سطح غشای خود باعث فراخواندن گویچه‌های سفید به موضع آسیب در جریان التهاب می‌شود.\n\nج) یاختۀ (۱) همانند (۳) می‌تواند در فضای سیتوپلاسمی خود پروتئین‌هایی داشته باشد که دارای ظاهری شبیه حرف Y انگلیسی دارند.\n\nد) یاختۀ (۲) برخلاف (۱)، از یاخته‌های بنیادی لنفوئیدی منشأ گرفته و قادر به ایجاد منفذ در غشای عوامل بیماری‌زای ویروسی است.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11400, 'کدام مورد، عبارت زیر را به‌طور مناسب کامل می‌کند؟\n\n«به‌طور معمول در انسان، ....................... پروتئین‌های دفاعی که می‌توانند طی شرایطی فعالیت یاخته‌های درشت‌خوار را افزایش دهند، ....................... »', 2, 4, 23, 92, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11401, 'کدام گزینه در ارتباط با روش‌های اثرگذاری پادتن‌ها و مقابله با آنتی‌ژن‌ها همواره صادق است؟', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11402, '50-چند مورد در ارتباط با یکی از خطوط دفاعی بدن انسان موسوم به «ورودممنوع»، به نادرستی بیان شده است؟\n\nالف: بخش موجود در زیر لایۀ حاوی عروق خونی در ساختار پوست، دارای سرخرگ سطحی‌تری نسبت به سیاهرگ است.\n\nب: لایۀ حاوی غدد ترشح‌کنندۀ عرق در ساختار پوست، دارای گیرنده‌های دندریتی با انتهای آزاد و غیرآزاد است.\n\nج: میکروب‌های سازش یافتۀ موجود در سطح پوست، با حمله بر میکروب‌های بیماری‌زا، بر آن‌ها پیروز می‌شوند.\n\nد: مادۀ چرب موجود در سطح پوست، به دلیل داشتن اسیدهای چرب، میکروب‌های زنده را نابود می‌کند.', 2, 4, 23, 89, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11403, '51-چند مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«در بدن فردی سالم، به‌منظور ارائۀ آنتی‌ژن توسط یکی از یاخته‌های حاصل از تمایز مونوسیت‌ها به یاخته‌ای غیرفعال و بالغ در گره لنفاوی، لازم است تا .......................»\n\nالف: آنتی‌ژن به سطح نوعی زوائد مشابه بخشی از نورون‌ها، متصل شود.\n\nب: نوعی کیسۀ غشایی مؤثر در جابه‌جایی مواد در سیتوپلاسم یاخته، تشکیل شود.\n\nج: ابتدا، آنتی‌ژن‌های سطحی عامل بیماری‌زا، توسط این یاخته‌های خط دوم دفاعی بدن، شناسایی شود.\n\nد: پس از قرارگیری آنتی‌ژن در سطح غشای یاخته‌های ارائه‌دهنده، این یاخته‌ها از طریق نوعی رگ دریچه‌دار، وارد گره لنفی شوند.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11404, '52-نوعی یاخته ایمنی با هسته گرد در خط دوم دفاعی بدن انسان، با کمک فرایندی منجر به مرگ یاخته‌های جهش یافته در اثر ورود ویروس به بدن می‌شود. در ارتباط با این فرایند، کدام مورد، به‌درستی بیان نشده است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11405, '53-در ارتباط با پروتئین‌های مؤثر در خط دوم دفاعی بدن، چند مورد به نادرستی بیان شده است؟ الف: فعالیت بعضی از آن‌ها در عملکرد آنزیمی برون‌ریزمانند مرگ یاخته‌ای سودمند است. ب: ابتلای یاخته ماهیچه اسکلتی به ویروس HIV فقط موجب مقاومت یاخته‌های ماهیچه‌ای سالم مجاور می‌شود. ج: ابتلای یاخته‌های بدن به عوامل بیماری‌زای غیرزنده، منجر به فعال شدن گروهی از پروتئین‌های خوناب می‌شود. د: اینترفرونی که ممکن است از گروهی از لنفوسیت‌های دفاع اختصاصی و غیر اختصاصی ترشح شود، به طور حتم یاخته‌هایی با زوائد سیتوپلاسمی فراوان را فعال می‌کند.', 2, 4, 23, 94, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11406, 'چند مورد، ویژگی مشترک تمام لنفوسیت‌هایی است که اینترفرون فعال‌کننده درشت‌خوارها را ترشح می‌کنند؟ \n\nالف: پس از تغییر در رمز همانندسازی ژنوم آن‌ها گیرنده‌هایی برای اتصال سطحی با یاخته‌های بزرگ‌تر را به وجود می‌آورند\n\nب: با ترشح مولکول‌هایی در گروهی خاص، حتماً علیه بیماری‌زایی بافت خودی یا غیرخودی را از هم می‌شناسند\n\nج: در خطوط دفاعی که بهترین راه درمان همانند آن میکروب‌ها ارائه نمی‌کنند، به فعالیت می‌پردازند\n\nد: در سرانجام، ترکیبی را که بر انواع یاخته‌های همسایه اثرگذار است، ترشح می‌کنند', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11407, '55-در ارتباط با خطوط دفاعی بدن انسان، کدام مورد یا موارد، به نادرستی بیان شده است؟\n\n«مطابق با مطالب کتاب‌درسی، در نوعی خط دفاعی در بدن انسان که ....................... می‌توان .......................»\n\nالف: مانند یک سد و بهترین راه برای درامان‌ماندن از میکروب‌ها است - چابک‌ترین یاختۀ ایمنی را در آن مشاهده کرد.\n\nب: میکروب‌ها بر اساس ویژگی‌های عمومی شناسایی می‌شوند - یاخته‌ای با هسته‌های چندبخشی را در آن مشاهده کرد.\n\nج: بعضی عوامل از طریق رسوب غیرفعال و نابود می‌شوند - اثرگذاری هیستامین بر روی مویرگ‌های سطحی را مشاهده کرد.\n\nد: در آن پاسخ ثانویه نسبت به پاسخ اولیه، سریع‌تر صورت می‌گیرد - فعال‌شدن بیگانه‌خوارها توسط لنفوسیت‌ها را مشاهده کرد.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11408, 'با توجه به مفاهیم ذکرشده در کتاب درسی، وجه اشتراک «پاسخ دستگاه ایمنی به مولکول بودار بی‌خطر در محیط» و «پاسخ دستگاه ایمنی درپی ورود میکروب از محل بریدگی پوست»، در کدام گزینه به درستی بیان شده است؟', 2, 4, 23, 93, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11409, '57-کدام گزینه، گویچه‌های سفید خونی که بیشترین مقدار طول عمر را دارند، از بیگانه‌خوارهای حاصل از تمایز گویچه‌های سفید واجد بیشترین میزان چین خوردگی در سطح غشا، متمایز می‌کند؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11410, '58-گروهی از مولکول‌های شیمیایی وجود دارند که علائمی به یاخته رسانیده و باعث تحریک شروع مرگ برنامه‌ریزی‌شده در یاخته‌های بدن انسان می‌شوند. ویژگی مشترک این ترکیبات شیمیایی، در کدام موارد به طور صحیح بیان شده است؟\n\nالف) زمینۀ فعالیت گروهی از بیگانه‌خوارها را فراهم می‌کنند.    ب) به دنبال بیان نوعی ژن در همان یاخته تولید می‌شوند.\n\nج) منجر به فعال‌شدن پروتئین‌هایی در یاخته می‌شوند.         د) منجر به بروز پاسخ التهابی در ناحیۀ مدنظر می‌گردند.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11411, '59-با توجه به مطالب کتاب درسی، گروهی از عوامل بیماری‌زا در حد کتاب درسی به درون یاخته‌های بدن وارد می‌شوند. کدام گزینه در ارتباط با این عوامل بیماری‌زا صادق است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11412, 'با در نظر گرفتن مطالب کتاب درسی در خصوص انواع خطوط مبارزه علیه عوامل بیماری‌زا، کدام گزینه وجه شباهت دومین و سومین خط دفاعی در پیکر یک انسان سالم و بالغ را به درستی بیان می‌کند؟', 2, 4, 23, 92, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11413, 'چند مورد از موارد زیر با توجه به روش‌های مطرح‌شده کتاب درسی برای اتصال پادگن به پادتن، نادرست است؟\n\nالف) در هر روشی که موجب ایجاد منفذ در غشای عامل بیگانه می‌گردد، هر پروتئینی که تغییری در ساختار سوم آن ایجاد می‌شود، مستقیماً با پادتن برخورد داشته است.\n\nب) در هر روشی که آنتی‌ژن‌های محلول عامل بیگانه رسوب داده می‌شوند، لزوماً هر پادتن به وسیلۀ هر دو بخش گیرندۀ خود به پادگن متصل می‌شود.\n\nج) در هر روشی که اتصال بیش از یک پادتن به یک عامل بیگانه ممکن است، به‌طورحتم اتصال یک پادتن به بیش از یک عامل بیگانه نیز رخ می‌دهد.\n\nد) در هر روشی که امکان افزایش فعالیت یاخته‌ای با هستۀ بزرگ‌تر نسبت به عامل خارجی وجود دارد، قطعاً نوعی یاختۀ بیماری‌زا به بدن وارد شده است.', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11414, 'مطابق کتاب درسی، دو نوع گویچۀ سفید در حین التهاب به موضع آسیب فراخوانده می‌شوند. کدام گزینه در ارتباط با این یاخته‌ها به طور صحیح بیان نشده است؟', 2, 4, 23, 94, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11415, 'مطابق شکل کتاب درسی، اتصال پادتن به پادگن (آنتی‌ژن)، باعث غیرفعال‌شدن پادگن با ۴ روش می‌شود. درخصوص این روش‌ها کدام مورد نادرست است؟', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11416, '64-پوست یکی از اندام‌های بدن است که لایه‌های بیرونی و درونی آن در جلوگیری از ورود میکروب‌ها به بدن نقش دارند. کدام مشخصه، لایۀ نازک‌تر پوست را از لایۀ دیگر آن متمایز می‌کند؟', 2, 4, 23, 89, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11417, 'مطابق با اطلاعات کتاب درسی، کدام دو مورد، از نظر درستی یا نادرستی، مشابه با عبارت زیر هستند؟\n\n«ایمنی حاصل از سرم، به‌دلیل عدم تأثیر روی فعالیت یاخته‌های ایمنی، ایمنی غیرفعال است.»\n\nالف: قدرت پاسخ ایمنی ثانویه بیش از دو برابر پاسخ ایمنی اولیه است.\n\nب: با پایان پاسخ ایمنی اولیه، سطح ایمنی همچنان بیش از زمان قبل از برخورد است.\n\nج: برای رسیدن به حداکثر قدرت پاسخ ایمنی اولیه از شروع ایجاد شدن بیش از دو هفته زمان نیاز دارد.\n\nد: فاصلۀ زمانی برخورد اول تا ایجاد پاسخ ایمنی اولیه، بیشتر از فاصلۀ برخورد دوم تا آغاز پاسخ ایمنی ثانویه است.', 2, 4, 23, 96, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11418, '66-درخصوص خطوط دفاعی دستگاه ایمنی انسان، چند مورد از موارد زیر درست است؟\n\nالف: در دومین و سومین خط برخلاف اولین خط، همۀ یاخته‌های دخیل در حفظ ایمنی، توانایی مصرف کردن گلوکز را دارند.\n\nب: در دومین و سومین خط همانند اولین خط، امکان مشاهدۀ یاخته‌هایی در تماس با یاخته‌های متحرک وجود دارد.\n\nج: اولین خط برخلاف دومین و سومین خط، علاوه‌بر کشتن میکروب‌ها، توانایی بیرون راندن آن‌ها از بدن را نیز دارد.\n\nد: اولین خط برخلاف دومین و سومین خط، بدون شناسایی هیچ‌کدام از عوامل بیگانه، با آن‌ها مبارزه می‌کند.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11419, '67-درخصوص یاخته‌های مربوط به دستگاه ایمنی، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول در بدن انسان، هریک از یاخته‌هایی که .......................»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11420, 'به‌طور طبیعی در بدن انسان، یاخته‌هایی به‌طور مستقیم از تقسیم لنفوسیت B بالغ‌شده در مغز استخوان ایجاد می‌شوند. کدام موارد زیر، مربوط به ویژگی مشترک این یاخته‌ها است؟\n\nالف: نوعی گیرندهٔ پادگنی (آنتی‌ژنی) در سطح غشای خود دارند.\n\nب: دارای هستهٔ کناری و شبکهٔ آندوپلاسمی گسترده هستند.\n\nج: توانایی تولید پروتئین اینترفرون نوع یک را دارند.\n\nد: در بروز پاسخ ایمنی سریع‌تر و قوی‌تر نقش دارند.', 2, 4, 23, 95, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11421, 'کدام گزینه در خصوص آن دسته از پروتئین‌های دفاعی که با تشکیل منفذ در غشای یاخته‌ها موجب مرگ آن‌ها می‌شوند، نادرست است؟', 2, 4, 23, 92, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11422, '70-چند مورد در ارتباط با پروتئین اصلی دفاع اختصاصی که به صورت محلول در خوناب دیده می‌شود، صادق است؟\n\nالف) ممکن است از یاخته‌هایی با هستهٔ مرکزی که از تقسیم مستقیم یاخته‌های بالغ‌شده در مغز استخوان ایجاد نشده‌اند، ترشح گردد.\n\nب) ممکن است با اثر بر نوعی پروتئین، باعث تحریک تشکیل منافذی متشکل از تنها یک پروتئین در غشای عامل بیماری‌زا شود.\n\nج) ممکن است در نتیجهٔ فعالیت برخی یاخته‌های قابل مشاهده در لایهٔ سطحی پوست، ترشح آن تحریک گردد.\n\nد) ممکن است با اتصال به برخی ترکیبات موجود در خون به حالت نامحلول درآید.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11423, '71-فردی به دنبال گازگرفته‌شدن توسط یک سگ هار به مرکز درمانی مراجعه کرده است. پس از بررسی‌های اولیه مشخص شده که ویروس هاری وارد بدن فرد شده و وی نیازمند مراقبت ویژه است. کدام عبارت در رابطه با اجزای دستگاه ایمنی در بدن این فرد درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11424, '72-در ارتباط با یاخته‌های ایمنی در بدن انسان، کدام مورد درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11425, '73-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در انسان........... گویچه‌های سفیدی که ........... دارند، برخلاف یاخته‌های ...........»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11426, '74-مطابق اطلاعات کتاب درسی، همگام با پیشرفت در روش‌های رنگ‌آمیزی و کار با میکروسکوپ، نوعی ویژگی در گروهی از یاخته‌های بدن کشف شد. کدام مورد در رابطه با یاخته‌هایی که چنین ویژگی دارند درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11427, '75-ایلیا مچنیکوف بر اساس مشاهدات خود، گروهی از یاخته‌های ایمنی را نام‌گذاری کرد. امروزه یاخته‌های مختلفی در این گروه قرار می‌گیرند. کدام گزینه در ارتباط با این یاخته‌ها در انسان صحیح است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11428, '76-مطابق با اطلاعات کتاب درسی، با فرض آن‌که فردی پس از گذشت چهار هفته از مواجه شدن با نوعی عامل بیگانه برای اولین‌بار، مجدداً آلوده به همان عامل بیگانه شده باشد، کدام مورد در ارتباط با فعالیت دستگاه ایمنی این فرد درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11429, '77-در خصوص فعالیت سومین خط دفاعی بدن، چند مورد درست است؟\n\nالف: هر پادتن فقط به یک عامل بیگانه متصل می‌شود.\n\nب: هر میکروب فقط یک نوع لنفوسیت B را تحریک می‌کند.\n\nج: هر لنفوسیت B عمل‌کننده فقط یک نوع گیرندهٔ پادگنی دارد.\n\nد: هر یاختهٔ پادتن‌ساز فقط یک نوع مولکول پادتن را ترشح می‌کند.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11430, '78-وجه مشترک هر دو نوع ایمنی حاصل از سرم و ایمنی حاصل از واکسن در انسان سالم و بالغ، کدام است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11431, '79-کرم کبد نوعی جانور انگل است که برای حیات خود به انسان نیاز دارد. در جهت دفاع بدن در پی ورود لارو این جانور به فضای داخل بدن فردی بالغ که دستگاه ایمنی سالم و فعالی دارد، لازم است تا .............. .', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11432, 'خارجی‌ترین یاخته‌های پوششی موجود در لایهٔ اپیدرم پوست یک فرد سالم چه مشخصه‌ای دارند؟', 2, 4, 23, 89, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11433, 'با توجه به انواع گویچه‌های سفید که شکل آن‌ها در زیر آورده شده است، کدام گزینه می‌تواند به ترتیب ویژگی یاخته‌های B ،A و C را بیان کند؟\n\nالف) پاسخ به مواد حساسیت‌زا\n\nب) توانایی فاگوسیتوز عوامل بیگانه\n\nج) خروج از دیوارهٔ مویرگ‌های خونی\n\nد) تأثیر در افزایش قطر رگ و جریان خون\n\nهـ) شناسایی عامل بیگانه از روی ویژگی‌های عمومی', 2, 4, 23, 91, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11434, '82-در انسان سالم، نوعی یاخته هسته‌دار در حبابک‌ها مشاهده می‌شود و هیچ‌گاه جزء یاخته‌های دیوارهٔ حبابک، طبقه‌بندی نمی‌گردد. کدام مورد، دربارهٔ این یاخته‌ها صادق است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11435, '83-در انسان، با اتصال یاختهٔ کشندهٔ طبیعی به‌نوعی یاختهٔ دیگر، ابتدا کدام اتفاق قبل از سایرین رخ می‌دهد؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11436, '84-یاخته‌های مؤثر در تولیدمثل جنسی، در پی نوعی تقسیم کاهشی به نام کاستمان (میوز) ایجاد می‌شوند. نظر به اینکه کاستمان از دو مرحلهٔ کلی کاستمان ۱ و ۲ تشکیل شده است، چند مورد، عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«در حدفاصل کاستمان ۱ و ۲، وقوع مرحله‌ای از ....................... قابل‌انتظار .......................»\n\nالف: تقسیم یاخته‌ای که در آن، عدد فام‌تنی یاخته دوبرابر می‌شود - نیست.\n\nب: تقسیم یاخته‌ای که در آن، حداکثر طول رشته‌های دوک مشاهده می‌شود - است.\n\nج: اینترفاز که در آن، حداکثر فعالیت دنابسپاراز و هلیکاز در هسته مشاهده می‌شود - است.\n\nد: چرخهٔ یاخته‌ای که در آن، پروتئین‌های اصلی مؤثر در تقسیم یاخته‌ای ساخته می‌شوند - نیست.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11437, '85-با درنظرگرفتن اینکه باهم‌ماندن کروموزوم‌ها در هر حالت، فقط در یک مرحله و فقط برای یک کروموزوم صورت می‌گیرد، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در زمانی که این اختلال در آنافاز میوز ۱ رخ دهد، برخلاف زمانی که در آنافاز میوز ۲ رخ دهد، .......................»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
