(11439, '87-در خصوص پروتئین‌های ترشحی و بیگانه‌خوارها در بدن انسان، کدام مورد درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11440, '88-چند مورد، برای تکمیل عبارت مقابل نامناسب است؟ «در انسان به هنگام التهاب، ...................... یاخته‌هایی که با تولید پیک‌های شیمیایی، گویچه‌های سفید را به موضع آسیب هدایت می‌کنند، ......................»\n\nالف: همهٔ - در هستهٔ خود، ژن مربوط به ساخت پروتئین‌های L مانند مؤثر در ازبین‌بردن عامل بیگانه را دارند.\n\nب: همهٔ - ضمن دارابودن انواعی از آنزیم‌های پروتئینی در مادهٔ زمینهٔ سیتوپلاسم، می‌توانند موادی را به خون وارد کنند.\n\nج: تنها بعضی از - می‌توانند با ترشح نوعی مولکول پروتئینی، در مقاوم شدن یاخته‌های مجاور خود به عامل بیگانه نقش داشته باشند.\n\nد: تنها بعضی از - در ساختار خود، فاقد گیرنده‌های دفاع اختصاصی بوده و عامل بیگانه را بر اساس ویژگی عمومی آن شناسایی می‌کنند.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11441, '89-در خصوص عملکرد بدن انسان در برابر تزریق بعضی از مواد، کدام مورد درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11442, '90-در خصوص یاخته‌های هسته‌دار موجود در شکل زیر، کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«وجه ...................... و یاختهٔ سمت ...................... در این است که ......................»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11443, '91-کدام گزینه در ارتباط با روش‌های اثرگذاری پادتن‌ها و مقابله با آنتی‌ژن‌ها همواره صادق است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11444, '92-کدام ویژگی، لایه داخلی ساختار بافتی پوست انسان را از لایه خارجی آن متمایز می‌سازد؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11445, '93-چند مورد در ارتباط با پروتئین اصلی دفاع اختصاصی که به صورت محلول در خوناب دیده می‌شود، صادق است؟\n\nالف) ممکن است از یاخته‌هایی با هسته مرکزی ترشح شود که از تقسیم مستقیم یاخته‌های بالغ‌شده در مغز استخوان ایجاد نشده‌اند.\n\nب) ممکن است با اثر بر نوعی پروتئین، باعث تحریک ایجاد منافذ متشکل از تنها یک عدد پروتئین در غشای عامل بیماری‌زا شود.\n\nج) ممکن است در نتیجه فعالیت بعضی از یاخته‌های قابل مشاهده در لایه سطحی پوست، ترشح آن تحریک گردد.\n\nد) ممکن است با اتصال به برخی ترکیبات موجود در بخش غیریاخته‌ای خون، به حالت نامحلول درآید.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11446, '94-با توجه به شکل‌های زیر، چند مورد نادرست است؟\n\nالف) یاخته ۳ همانند ۴، به منظور عبور از دیواره مویرگ‌های خونی، تغییراتی در ظاهر هسته و سیتوپلاسم خود ایجاد می‌کند.\n\nب) یاخته ۴ برخلاف ۲، با ایجاد تغییراتی در سطح غشای خود، گویچه‌های سفید را در جریان التهاب به موضع آسیب فرامی‌خواند.\n\nج) یاخته ۱ همانند ۳، می‌تواند در فضای سیتوپلاسمی خود پروتئین‌هایی داشته باشد که دارای ظاهری شبیه به حرف Y هستند.\n\nد) یاخته ۲ برخلاف ۱، از یاخته بنیادی لنفوئیدی منشأ گرفته و قادر به ایجاد منفذ در غشای عوامل بیماری‌زای ویروسی است.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11447, '95-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، (در) نوعی پاسخ بافتی بدن که با ایجاد تورم و قرمزی همراه است، ......................»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11448, '96-با توجه به مطالب کتاب درسی، کدام مورد در ارتباط با مقایسه میان پاسخ ایمنی اولیه و ثانویه در فردی که تاکنون واکسن بیماری را دریافت نکرده، درست است؟ (فرد تا بحال برخوردی با عامل بیماری‌زا نداشته است.)', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11449, '97-کدام گزینه، عبارت زیر را به طور نامناسب کامل می‌نماید؟\n\n«نوعی یاخته خونی که محل تکثیر عامل نقص ایمنی اکتسابی است، در فردی که توسط این عامل آلوده ...................... است، ......................»', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11450, '98-پادتن‌ها، پادگن‌ها را با روش‌های مختلفی بی‌اثر یا نابود می‌کنند. در خصوص این روش‌ها، کدام مورد درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11451, '99-طبق اطلاعات کتاب‌درسی، کدام ویژگی، یاخته‌های ترشح‌کننده‌ی پرفورین در خط سوم دفاعی را از یاخته‌های ترشح‌کننده‌ی آن در خط دوم، متمایز می‌سازد؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11452, '100-کدام مورد در خصوص پروتئین‌های ایمنی بدن انسان، صحیح است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11453, '101-کدام عبارت درست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11454, '102-مطابق با اطلاعات کتاب‌درسی، در خصوص لنفوسیت‌های مربوط به دفاع اختصاصی بدن انسان، کدام مورد نادرست است؟', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11455, '103-در ارتباط با بیماری ایدز و تشخیص آن، چند مورد درست است؟ الف: عامل آن با نابود کردن گروهی از لنفوسیت‌ها، عملکرد سایر لنفوسیت‌های مربوط به خط سوم دفاعی بدن را مختل می‌کند. ب: در منظور تشخیص آن در مراحل اولیه، به‌طور قطع باید به‌دنبال مواد بیگانه موجود در ترشحات خونی فرد مشکوک گشت. ج: در افراد آلوده به ویروس این بیماری، برخی یاخته‌های خون‌ساز خود را به‌دلیل آنزیم‌های هسته‌دار از دست می‌دهند. د: عامل آن ضمن داشتن اندازه بسیار کوچک در تشکیل منافذ سلولی با مولکولی از نوع نوکلئیک‌اسید به‌دیگری کمک می‌کند.', 2, 4, 23, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:30', 1, NULL, NULL, 'free'),
(11456, '1- کدام گزینه، درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11457, '2- با توجه به مطالب کتاب درسی در فصل 6 کتاب یازدهم، چند مورد نادرست است؟\n\nالف: دو جانداری که دارای عدد فام‌تنی یکسان هستند، قطعاً می‌توانند جزئی از یک جمعیت باشند.\n\nب: در همه فام‌تن (کروموزوم)های انسان، سانترومر در فاصله یکسانی از دو انتهای فام‌تن واقع شده است.\n\nج: هر دو فام‌تن (کروموزوم)ی که به همراه یکدیگر چهارتایه (تتراد) تشکیل می‌دهند، قطعاً محتوای ژنی مشابهی دارند.\n\nد: همه یاخته‌هایی که به طور موقت یا دائمی تقسیم نمی‌شوند، قبل از عبور از اولین نقطه وارسی به مرحله $G_0$ وارد می‌شوند.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11458, '3- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در فاصله بین مرحله ................. هر تقسیمی که توسط یکی از یاخته‌های دیواره لوله‌های اسپرم‌ساز یک مرد بالغ انجام می‌شود، .................»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11459, '4- فرایند کاستمان (میوز) از دو مرحله کلی کاستمان 1 و 2 تشکیل شده است. کدام مورد در ارتباط با مقایسه این دو مرحله صحیح است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11460, '5- در مرحله‌ای از تقسیم رشتِمان، رنابسپاراز (RNA پلیمراز)ها کمترین میزان دسترسی را به ماده وراثتی دارند. کدام مورد در ارتباط با این مرحله صحیح است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11461, '6- با توجه به تفاوت‌های بافت‌مردگی و مرگ برنامه‌ریزی‌شده یاخته‌ای، چند مورد فقط درخصوص فرایندی درست است که موجب آسیب به یاخته‌های کبدی در اثر مصرف الکل می‌شود؟\n\nالف: به‌طور غیرتصادفی باعث تخریب تعدادی از یاخته‌ها می‌شود.\n\nب: باعث رهاشدن هیستامین از ماستوسیت‌های آسیب‌دیده می‌شود.\n\nج: در شرایط خاصی باعث تجزیه اجزای یاخته توسط پروتئین‌ها می‌شود.\n\nد: ممکن است تعداد یاخته‌های آسیب‌دیده‌ای که مرده‌اند را افزایش دهد.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11462, '7- درخصوص نشانگان داون که در نتیجهٔ نوعی از جهش‌های بزرگ ایجاد می‌شود، کدام موارد زیر صحیح هستند؟\n\nالف: بالا بودن سن مادر در هنگام بارداری از عوامل بروز این بیماری است.\n\nب: برای تعیین تعداد فام‌تن‌ها در فرد بیمار، می‌توان از کاریوتیپ استفاده کرد.\n\nج: فرد بیمار به‌دلیل چندلادی‌شدن تعداد بیشتری از فام‌تن‌های شماره 21 دارد.\n\nد: در فرد بیمار قطعاً در هنگام تشکیل گامت مادری خطای کاستمانی رخ داده است.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11463, '8- کدام مورد دربارهٔ مراحل چرخهٔ یاخته‌ای در یک یاختهٔ بنیادی میلوئیدی در مغز قرمز استخوان بازو در فردی سالم، نادرست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11464, '9- در ارتباط با تقسیم یاخته‌های بدن انسان و تنظیم آن، چند مورد امکان‌پذیر است؟\n\nالف: فقط یکی از یاخته‌های حاصل از تقسیم میتوز، وارد مرحلهٔ $G_0$ شود.\n\nب: رشته‌های دوک تقسیم بدون اتصال به سانترومر، از مرکز یاخته عبور کنند.\n\nج: همزمان با شکل‌گیری پوشش هسته، حلقهٔ پروتئینی سیتوپلاسمی به غشا متصل شده باشد.\n\nد: یاخته‌ای پوششی پس از آلوده‌شدن به ویروس، توسط رگ‌های لنفی به نواحی دیگر بدن برود.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11465, '10- کدام عبارت، دربارهٔ رشته‌های سازندهٔ دوک تقسیم درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11466, '11- کدام عبارت در مورد شکل روبه‌رو نادرست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:38', 1, NULL, NULL, 'free'),
(11467, '12- در هنگام تقسیم میتوز در یاختهٔ زامه‌زا (اسپرماتوگونی)، ......................', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11468, '13- کدام مورد درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11469, '14- کدام عبارت در مورد افراد مبتلا به نشانگان (سندروم) داون درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11470, '15- در گیاه آلبالو، پس از آن که فام‌تن (کروموزوم)های یاخته تخم حین میتوز، حداکثر فشردگی را پیدا نمودند، ......................', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11471, '16- چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در مرگ برنامه‌ریزی شدهٔ یاخته‌ای برخلاف بافت مردگی، .................... »\n\nالف) پاسخ‌های التهابی رخ می‌دهد.\n\nب) اثرات مثبتی برای بدن ایجاد می‌شود.\n\nج) ابتدا تغییری در غشای یاخته ایجاد می‌شود.\n\nد) یاخته به سبب فعالیت درشت خوارها می‌میرد.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11472, '17- کدام گزینه عبارت زیر را به‌درستی تکمیل می‌کند؟\n\n«در فرایند میتوز در یاختهٔ جانوری، ...................... بلافاصله پیش از مرحله‌ای است که در آن ...................... صورت می‌گیرد.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11473, '18- با توجه به شکل روبه‌رو، چند مورد جملهٔ زیر را به‌طور صحیح تکمیل می‌کند؟\n\n«بلافاصله ................ از مرحلهٔ شکل روبه‌رو ................ .»\n\n\n\nالف) قبل - می‌تواند میانک‌ها (سانتریول‌ها) مضاعف شده باشد\n\nب) بعد - تغییر طول برخی رشته‌های دوک تقسیم منجر به حرکت کروموزوم‌ها به مرکز یاخته می‌شود\n\nج) قبل - می‌تواند میانک‌ها (سانتریول‌ها) در طرفین یاخته قرار گرفته باشد\n\nد) بعد - می‌توان قرارگیری کروموزوم‌ها را در میانهٔ یاخته مشاهده نمود', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11474, '19- کدام‌یک از گزینه‌های زیر درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11475, '20- کدام گزینه در رابطه با تومورهای نشان داده شده در تصویر روبه‌رو به‌درستی بیان شده است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11476, '21- عبارت درست را در مورد تقسیم یاخته‌های جانداران، از میان موارد زیر انتخاب کنید.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11477, '22- چند مورد از موارد زیر نادرست هستند؟\n\nالف) در پروفاز همه تقسیم‌ها، میانک (سانتریول)ها مسئول تولید رشته‌های دوک هستند.\n\nب) در آنافاز همه تقسیم‌ها، مقدار ماده وراثتی یکسان می‌ماند.\n\nج) در متافاز همه تقسیم‌ها، فام‌تن (کروموزوم)ها در یک ردیف در استوای یاخته قرار می‌گیرند.\n\nد) در تلوفاز همه تقسیم‌ها، هر فام‌تن (کروموزوم) با یک مولکول دنا وجود دارد.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11478, '23- چند مورد در ارتباط با پروتئین‌های موجود در شکل روبه‌رو، نادرست است؟\n\nالف) پس از اتصال به دنا باعث ایجاد حالت مارپیچی در آن می‌شوند.\n\nب) تنها پروتئین‌هایی هستند که در اتصال با دنای هسته‌ای قرار می‌گیرند.\n\nج) این پروتئین‌ها توسط رناتن‌های موجود بر روی شبکه آندوپلاسمی تولید می‌شوند.\n\nد) در صورت توقف چرخه یاخته‌ای در مرحلهٔ $G_1$، همگی از مولکول دنا جدا می‌شوند.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11479, '24- کدام گزینه جمله زیر را به‌نادرستی تکمیل می‌کند؟\n\n«به‌طور معمول یاخته‌های هسته‌دار انسان که توانایی تقسیم دارند، دناهای خطی دارند که هریک از آن‌ها در مرحلهٔ ................ چرخهٔ یاخته‌ای، ................»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11480, '25- هر یاخته زنده و هسته‌داری که به‌طور طبیعی در بدن یک انسان سالم و بالغ یافت می‌شود، ................', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11481, '26- در اولین مرحلهٔ چرخهٔ یاخته‌ای که در آن دناهای موجود در هستهٔ یاخته‌های پوششی انسان دارای فشردگی هستند، ................', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11482, '27- بعضی از یاخته‌ها به‌طور موقت تقسیم نمی‌شوند. در صورتی که قرار باشد این یاخته‌ها تقسیم شوند، ابتدا وارد مرحله‌ای می‌شوند که در آن ......... .', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11483, '28- کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟\n\n«با توجه به مراحل مختلف فرایند تقسیم رشتمان (میتوز)، در یک یاختهٔ دولاد (دیپلوئید) «مرحله‌ای که در آن افزایش ابعاد یاخته مشاهده می‌شود» و «مرحله‌ای که تخریب غشای هسته پایان می‌پذیرد» از نظر ................ به یکدیگر شباهت داشته و از نظر ................ تفاوت دارند.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11484, '29- کدام گزینه عبارت زیر را به‌طور مناسب کامل می‌کند؟\n\n«در یک یاختهٔ بافت پوششی در انسان، در پی تجزیهٔ پروتئین‌های اتصالی در ناحیهٔ سانترومر ................ .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11485, '30- در رابطه با مراحل رشد و پخش شدن یاخته‌های سرطانی به نواحی دیگر بدن که در کتاب درسی مطرح شده است، کدام گزینه به‌درستی بیان شده است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11486, '31- در شکل روبه‌رو دو مرحله از تقسیم کاستمان (میوز) طبیعی را مشاهده می‌کنید. در کدام گزینه وقایع رخ داده بین این دو مرحله به‌درستی عنوان شده است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11487, '32- چند مورد جملهٔ زیر را به‌نادرستی تکمیل می‌کند؟\n\n«در انسان هر نوع تغییر در تعداد فام‌تن‌ها که ................ ، به‌طور حتم ................ .»\n\nالف) در مرحلهٔ تجزیهٔ پروتئین اتصالی سانترومرها رخ می‌دهد - نوعی خطای رشتمانی محسوب می‌شود\n\nب) منجر به تشکیل گامت‌هایی با ۴۶ فام‌تن می‌شود - ناشی از اشتباه در مرحلهٔ آنافاز کاستمان ۱ است\n\nج) امکان تولد فرزندی مبتلا به نشانگان داون را فراهم می‌کند - ناشی از جدا نشدن فام‌تن‌های ۲۱ مادر است\n\nد) منجر به تشکیل یاخته‌های فاقد فام‌تن می‌شود - نوعی خطای کاستمانی است که در آنافاز ۲ رخ می‌دهد', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(11488, '33- در جریان تولید یاخته‌های جنسی در یک مرد سالم، پدیدهٔ چلیپایی شدن (کراسینگ‌اور) رخ داده است. کدام گزینه در رابطه با مرحله‌ای که این پدیده در آن رخ داده است، به مطلب درستی اشاره می‌کند؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11489, '34- در مقایسهٔ مراحل کاستمان ۱ و کاستمان ۲ در یک یاختهٔ دولاد کدام موارد به‌درستی بیان شده‌اند؟\n\nالف) در پروفاز ۱ برخلاف پروفاز ۲، فام‌تن‌ها مضاعف شده و فام‌تن‌های دوفامینکی همتا از طول در کنار هم قرار می‌گیرند.\n\nب) در متافاز ۱ همانند متافاز ۲، فام‌تن‌ها در استوای یاخته قرار گرفته و هرکدام به یک رشته دوک متصل می‌شوند.\n\nج) در آنافاز ۱ برخلاف آنافاز ۲، تعداد فام‌تن و سانترومر تغییری نمی‌کند.\n\nد) در تلوفاز ۱ همانند تلوفاز ۲، مرزی بین مادهٔ وراثتی و مادهٔ زمینهٔ سیتوپلاسم تشکیل می‌شود.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11490, '35- در لیپوما ................ ملانوما، ................ .', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11491, '36- کدام گزینه درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11492, '37- چند مورد جملهٔ زیر را دربارهٔ یک یاختهٔ دولاد، به‌درستی تکمیل می‌کند؟\n\n«در همهٔ ................ کروموزوم‌ها دوکروماتیدی هستند.»\n\nالف) آنافازها\n\nب) پروفازها\n\nج) تلوفازها\n\nد) متافازها', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11493, '38- کدام گزینه، عبارت درستی را بیان می‌کند؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11494, '39- کدام گزینه، جهت کامل کردن عبارت زیر مناسب است؟\n\n«در مرحله‌ای از تقسیم ................ ، ................»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11495, '40- چند ویژگی مابین مرحلهٔ آنافاز میوز ۲ و مرحلهٔ آنافاز میتوز تقسیم یک یاختهٔ دیپلوئید جانوری مشترک می‌باشد؟\n\nالف) بلندتر شدن برخی از رشته‌های دوک تقسیم برخلاف برخی دیگر\n\nب) جدا شدن کروماتیدهای خواهری\n\nج) دو برابر شدن تعداد کروموزوم نسبت به تعداد کروموزوم‌های یاختهٔ دیپلوئید اولیه\n\nد) ایجاد حلقهٔ انقباضی اکتین و میوزین', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11496, '41- به‌طور طبیعی در همهٔ انواع یاخته‌ها و همهٔ انواع تقسیم هسته ................ .', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11497, '42- چند مورد از موارد زیر نادرست هستند؟\n\nالف) در مرحلهٔ اول تقسیم رشتمان (میتوز) در یاخته‌های بدون دیواره، سانترومرها مسئول سازمان دادن رشته‌های دوک هستند.\n\nب) در مرحلهٔ قبل از آنافاز کاستمان (میوز) ۱ در یاخته‌های ساقهٔ غدهٔ سیب‌زمینی، رشته‌های دوک به فام‌تن‌های دوفامینکی (کروموزوم‌های دوکروماتیدی) متصل می‌شوند.\n\nج) در پایان مرحلهٔ جدا شدن فامینک (کروماتید)های خواهری در هر نوع تقسیمی، در هر قطب یاخته نیمی از انواع فام‌تن (کروموزوم)ها وجود دارند.\n\nد) در مرحلهٔ پایانی تقسیم میتوز در یاخته‌های پروکاریوتی، کروموزوم‌ها تک‌کروماتیدی‌اند.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11498, '43- کدام گزینه دربارهٔ تقسیم میان‌یاخته در هر یاختهٔ گیاهی به‌درستی بیان شده است؟\n\nالف) رشته‌های دوک سازمان‌یابی شده توسط سانتریول‌ها، در تقسیم میان‌یاخته دخالت دارند.\n\nب) سرعت تشکیل پوشش هسته از سرعت کامل شدن دیوارهٔ جدید بیشتر است.\n\nج) ساختاری در دیواره که پلاسمودسم‌ها به فراوانی در آن وجود دارند، در هنگام تشکیل دیواره پایه‌گذاری می‌شود.\n\nد) با تنگ شدن حلقهٔ انقباضی در این یاخته‌ها، در نهایت دو یاخته از هم جدا می‌شوند.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11499, '44- کدام جمله دربارهٔ یاخته‌هایی که در مرحلهٔ G₀ قرار دارند، به‌درستی بیان شده است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11500, '45- کدام مورد عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در مرحله‌ای که تقسیم سیتوپلاسم در یک یاختهٔ ................ شروع می‌شود، ................ .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11501, '46- با توجه به مطالب کتاب درسی، کدام مورد در رابطه با فام‌تن (کروموزوم)های جانداران مختلف نادرست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11502, '47- چند مورد، عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در مرحلهٔ ................ هر کروموزوم دارای دوکروماتید است.»\n\nالف) پروفاز $2$\n\nب) آنافاز $1$\n\nج) تلوفاز $2$\n\nد) متافاز $2$\n\nه) آنافاز $2$', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11503, '48- چند مورد به منظور تکمیل عبارت زیر نامناسب است؟\n\n«در پیکر یک انسان بالغ، توموری که در مرحلهٔ ................ متاستاز قرار دارد، به طور حتم ................ .»\n\nالف) سوم - برخلاف لیپوما، تحت تاثیر آنزیم پرفورین، عملکرد زیستی آن دستخوش تغییر می‌شود.\n\nب) چهارم - همراه با انواعی از پروتئین‌های خوناب، در نقاط مختلف بدن پراکنده می‌شود.\n\nج) دوم - برخلاف تومورهای خوش‌خیم، عملکرد بافت‌های مجاور را مختل می‌کند.\n\nد) اول - رشد آن به کمک بافت‌برداری قابل کنترل است.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11504, '49- با توجه به نوعی تقسیم دو مرحله‌ای که در تولید یاخته‌های مؤثر در تولیدمثل جنسی انسان نقش دارد، کدام عبارت صحیح است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11505, '50- در رابطه با تومور بدخیم ایجاد شده در دیوارهٔ رودهٔ باریک، کدام گزینه، تکمیل‌کنندهٔ مناسبی برای عبارت زیر است؟\n\n«طبق مطالب کتاب درسی، همزمان با بروز مرحلهٔ ................ رشد و پخش یاخته‌های سرطانی، ................ .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11506, '51- مطابق با مطلب کتاب درسی، حذف یاخته‌های اضافی از بخش‌های عملکردی مانند پرده‌های بین انگشتان پا در پرندگان، مثالی از نوعی فرایند مرگ یاخته‌ای است. کدام ویژگی دربارهٔ این فرایند در بدن انسان، به‌طور حتم صادق است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11507, '52- مطابق با مطلب کتاب درسی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«با در نظر گرفتن مراحل مختلف اینترفاز چرخهٔ یاخته‌ای، می‌توان گفت در مرحله‌ای از آن که ................ می‌شود، ................ .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11508, '53- کدام ویژگی، مرگ برنامه‌ریزی شده را از بافت‌مردگی، متمایز می‌کند؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11509, '54- کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«در تقسیم میتوز یاخته‌های جانوری، مرحله‌ای از میتوز که ................ همانند مرحلهٔ ................ تقسیم میوز ۱ ................ .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11510, '55- در ارتباط با فرایند تقسیم سیتوپلاسم در یک یاختهٔ پارانشیم برگ گیاه زیتون، کدام مورد، به‌درستی بیان شده است؟\n\n«در مرحله‌ای از تقسیم میتوز که تعداد ریزکیسه‌های مربوط به دیواره رو به ................ می‌گذارد، ................ .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11511, '56- مطابق با مطالب کتاب درسی، کدام عبارت دربارهٔ فرایند تقسیم چهار مرحله‌ای سیتوپلاسم در دانهٔ گردهٔ نارس درخت سیب، درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11512, '57- کدام ویژگی، تومور لیپوما را از تومور ملانوما در ناحیهٔ آرنج، متمایز می‌سازد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11513, '58- کدام عبارت در خصوص مراحل رشتمان یک یاختهٔ بنیادی مغز استخوان، درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11514, '59- به‌طور کلی، چرخهٔ یاخته‌ای در یاخته‌های بنیادی مغز استخوان به دو فاز کلی تقسیم می‌شود. با توجه به رویدادهای مختلف آن، کدام مورد برای تکمیل عبارت زیر، مناسب است؟\n\n«در فاز طولانی‌تر چرخه، موارد ................ و ................ فقط مربوط به یک مرحلهٔ مشترک می‌باشند.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11515, '60- در خصوص انواع تومورهای ایجادشده در بدن و روش‌های درمان آن، کدام مورد نادرست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11516, '61- با توجه به مطالب مطرح‌شده در کتاب درسی، درخصوص مراحل فشرده‌شدن فام‌تن (کروموزوم)ها، کدام مورد بعد از سایرین رخ می‌دهد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11517, '62- در ارتباط با تغییر تعداد فام‌تن‌ها به‌دلیل خطا در انجام تقسیمات یاخته‌ای، کدام مورد به‌درستی مطرح شده است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11518, '63- با توجه به فرایندهای بافت‌مردگی و مرگ برنامه‌ریزی شدهٔ یاخته‌ای، کدام مورد فقط درخصوص بافت‌مردگی درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11519, '64- درخصوص مراحل تقسیم سیتوپلاسم در یاخته‌های ساقهٔ گیاه لوبیا، کدام مورد درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11520, '65- درخصوص روش‌های رایج درمان سرطان بدون عمل جراحی، چند مورد درست است؟\n\nالف: فقط در برخی از این روش‌ها، تومور به‌طور مستقیم تحت تأثیر قرار می‌گیرند.\n\nب: در همهٔ این روش‌ها، تهوع و خستگی به‌عنوان عوارض جانبی بروز پیدا می‌کند.\n\nج: فقط در برخی از این روش‌ها، از ترکیبات دارویی برای درمان استفاده می‌شود.\n\nد: در همهٔ این روش‌ها، هر فرد بیمار مجبور به پیوند مغز استخوان می‌شود.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11521, '66- در کدام گزینه، موارد ذکرشده در حدفاصل بین دو نقطهٔ وارسی متوالی رخ نمی‌دهد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11522, '67- مرحله‌ای از تقسیم میتوز در یاخته‌ای گیاهی که کروموزوم‌ها از محل سانترومر دچار خمیدگی می‌شوند، چه مشخصه‌ای دارد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11523, '68- شکل مقابل، نوعی یاخته در حال تقسیم را نشان می‌دهد. در خصوص این یاخته و فرایند تقسیم آن، کدام مورد درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11524, '69- اگر تقسیم سیتوپلاسم مساوی نوعی از یاخته‌های گیاهی را در چهار مرحله در نظر بگیریم، کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\n«به هنگام تقسیم سیتوپلاسم نوعی یاختهٔ میانبرگ لوبیا، هم‌زمان با ......................»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11525, '70- یاخته‌های مریستمی گل قاصد و یاخته‌های بنیادی مغز استخوان انسان در مرحله‌ی مشخصی از تقسیم هسته، تقسیم سیتوپلاسم خود را آغاز می‌کنند. کدام مورد وجه تمایز مرحله‌ای از تقسیم هسته این یاخته‌ها که بلافاصله قبل از مراحل ذکرشده انجام می‌شود را بیان می‌کند؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11526, '71- در چرخهٔ یاخته‌ای زامه‌زا، یکی از نقاط وارسی یاخته را از سلامت دنا مطمئن می‌کند. چند مورد، مشخصهٔ مرحله‌ای از چرخهٔ یاخته‌ای را نشان می‌دهد که یاخته پس از عبور از این نقطهٔ وارسی به آن وارد می‌شود؟\n\nالف- تعداد مولکول‌های دنای یاخته در آن دوبرابر می‌شود.\n\nب- طی آن عدد کروموزومی یاخته تغییری پیدا نمی‌کند.\n\nپ- وضعیت قرارگیری نوکلئوزوم‌ها نسبت هم تغییر می‌کند.\n\nت- پروتئین‌سازی در این مرحله همچنان ادامه پیدا می‌کند.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11527, '72- درخصوص مراحل مختلف تقسیم یاخته‌ای یک یاخته از بدن انسان، کدام مورد به‌طور حتم درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11528, '73- در دیوارهٔ لولهٔ گوارش فردی، توموری متشکل از تعدادی یاخته مشاهده شده است. به‌ترتیب از راست به چپ، در چه صورت می‌توان با قطعیت اظهار داشت که این تومور بدخیم است و از چه روش رایجی می‌توان به‌منظور درمان آن استفاده کرد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11529, '74- کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول در گروهی از یاخته‌های هسته‌دار انسان سالم و بالغ که مضاعف‌شدن دنا (DNA)ی هسته‌ای رخ می‌دهد، حین وقوع مرحلهٔ ...................... در همهٔ تقسیم‌های طبیعی، قطعاً ...................... .»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11530, '75- با توجه به مراحل رشد و پخش یاخته‌های سرطانی در مخاط رودهٔ باریک انسان، پس از آن‌که تودهٔ یاخته‌ای در بافت گسترش یافته است و به لایهٔ ماهیچه‌ای دیواره تهاجم پیدا کند، کدام اتفاق نسبت به سایرین زودتر رخ می‌دهد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11531, '76- در خصوص یک یاختهٔ مریستمی در درخت آلبالو، کدام گزینه، عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«اینترفاز شامل سه مرحلهٔ $\\text{G}_1$، $\\text{S}$ و $\\text{G}_2$ است. در (هر) مرحله‌ای از آن که ...................... می‌شود، می‌توان شاهد ...................... بود.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11532, '77- در خصوص فرایند تقسیم هسته در یاختهٔ پارانشیم برگ گیاه نارگیل، کدام موارد زیر، نادرست است؟\n\nالف: در آخرین مرحله، ریزکیسه‌های تشکیل‌شده توسط شبکهٔ آندوپلاسمی زبر، یک ریزکیسهٔ واحد را تشکیل می‌دهند.\n\nب: در سومین مرحله، سه مجموعه فام‌تن (کروموزوم) توسط رشته‌های دوک تقسیم، به هر کنارهٔ یاخته منتقل می‌گردد.\n\nج: در چهارمین مرحله، یاخته حالت کشیده پیدا کرده و طول برخی از رشته‌های اطراف سانتریول‌ها، افزایش پیدا می‌کند.\n\nد: در اولین مرحله، پوششی متشکل از دولایهٔ فسفولیپیدی، ناپدید شده و نوکلئیک‌اسیدها را به سیتوپلاسم رها می‌کند.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11533, '78- در هر مرحله‌ای از تقسیم رِشتمان (میتوز) یاختهٔ پوششی مری انسانی بالغ که ...................... انتظار است.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11534, '79- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، ...................... توده‌های ایجادشده در اثر تقسیمات تنظیم‌نشده در یک فرد نابالغ، ...................... می‌شود.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11535, '80- در خصوص محتوای وراثتی در یاخته‌های انسان، کدام مورد درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11536, '81- اگر تقسیم سیتوپلاسم مساوی نوعی از یاخته‌های گیاهی را در چهار مرحله در نظر بگیریم، کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\n«به هنگام تقسیم سیتوپلاسم نوعی یاختهٔ میانبرگ لوبیا، هم‌زمان با ...................... »', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11537, '82- با توجه به شکل مقابل، کدام گزینه مرحلهٔ (الف) را از مرحلهٔ (ب) متمایز می‌کند؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11538, '83- کدام عبارت در خصوص مراحل رِشتمان یک یاختهٔ بنیادی مغز استخوان، درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11539, '84- با توجه به شکل‌های ۱ و ۲ که به توده‌های واجد یاخته‌های تغییریافته در بدن انسان تعلق دارد، کدام عبارت زیر صحیح است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11540, '85- به دنبال آغاز تقسیم کاستمان در زام‌یاختهٔ اولیه، کدام مورد پیش از کامل‌شدن پوشش هسته رخ می‌دهد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11541, '86- در خصوص اختلال در تقسیم طبیعی گروهی از یاخته‌های دیوارهٔ رودهٔ باریک و دیده‌شدن شماری از یاخته‌ها در محلی غیر از محل طبیعی خود، کدام مورد، پیش از سایرین رخ می‌دهد؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11542, '87- با توجه‌به شکل مقابل، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، در مرحله‌ای از تقسیم کاستمان که فام‌تن‌هایی به شکل ...................... ، مشاهدهٔ ...................... قابل‌انتظار است.»', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11543, '88- کدام مورد یا موارد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، مرگ برنامه‌ریزی‌شده ...................... بافت‌مردگی، به طور حتم ......................»\n\nالف: همانند - در پاسخ به عامل خارجی رخ می‌دهد.\n\nب: برخلاف - نمی‌تواند به‌صورت تصادفی در یاخته رخ دهد.\n\nج: همانند - برای حذف یاخته‌های پیر، آلوده یا آسیب‌دیده رخ می‌دهد.\n\nد: برخلاف - نیازمند برون‌رانی آنزیم مرگ برنامه‌ریزی‌شده توسط یاختهٔ دیگر است.', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11544, '89- کدام عبارت، در ارتباط با بدن انسان، درست است؟', 2, 4, 24, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:39', 1, NULL, NULL, 'free'),
(11545, 'کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«هر هورمون هیپوفیزی مؤثر بر چرخهٔ جنسی زنان که ......................... می‌شود، به‌طور حتم در مردان، ......................... .»', 2, 4, 25, 104, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11546, '2-چند مورد، ویژگی مشترک یاخته‌هایی است که در انسان، توانایی لقاح با اسپرم را دارند؟\n\nالف: بخش عمده‌ای از سیتوپلاسم یاختهٔ سازندهٔ خود را دریافت کرده است.\n\nب: در صورت آغاز شدن فرایند لقاح، می‌تواند تقسیم دوم میوز را تکمیل کند.\n\nج: یک مجموعه فام‌تن (کروموزوم) دو فامینکی (کروماتیدی) در هستهٔ خود دارد.\n\nد: پس از لقاح، با تقسیمات میتوزی متوالی، تودهٔ یاخته‌ای تمایزیافته‌ای را ایجاد می‌کند.', 2, 4, 25, 103, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11547, '3-کدام عبارت، دربارهٔ مراحل رشد جنین به‌درستی بیان شده است؟', 2, 4, 25, 107, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11548, '4-چند مورد، دربارهٔ دستگاه تولیدمثلی زنان سالم درست است؟\n\nالف: همزمان با شروع بلوغ جنسی، همواره خروج بافت‌های تخریب‌شده از بدن با نظم مشخصی انجام می‌شود.\n\nب: در هر ماهی از دوران زندگی که دیوارهٔ داخلی رحم تخریب می‌شود، فقط یک انبانک (فولیکول) رشد می‌کند.\n\nج: تا قبل از پیر شدن غدد جنسی، تعداد کمی از مام‌یاخته (اووسیت)ها می‌توانند چهارتایه (تتراد) تشکیل دهند.\n\nد: در بخش کوتاهی از یک ماه دوران باروری، امکان دارد که دو نوع مام‌یاخته (اووسیت) به‌طور همزمان در تخمدان دیده شوند.', 2, 4, 25, 102, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11549, '5-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در زنی جوان که وارد مرحلهٔ ......................... شده است، ......................... .»', 2, 4, 25, 108, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11550, '6-چند مورد، ویژگی مشترک یاخته‌هایی است که در انسان، توانایی لقاح با اسپرم را دارند؟\n\nالف: بخش عمده‌ای از سیتوپلاسم یاختهٔ سازندهٔ خود را دریافت کرده است.\n\nب: در صورت آغاز شدن فرایند لقاح، می‌تواند تقسیم دوم میوز را تکمیل کند.\n\nج: یک مجموعه فام‌تن (کروموزوم) دو فامینکی (کروماتیدی) در هستهٔ خود دارد.\n\nد: پس از لقاح، با تقسیمات میتوزی متوالی، تودهٔ یاخته‌ای تمایزیافته‌ای را ایجاد می‌کند.', 2, 4, 25, 103, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11551, '7-کدام عبارت، دربارهٔ مسیر عبور زامه (اسپرم) پس از تولید در لوله‌های زامه (اسپرم)‌ساز درست است؟', 2, 4, 25, 99, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11552, '8-کدام عبارت، دربارهٔ دستگاه تولیدمثلی زنان درست است؟', 2, 4, 25, 102, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, '2026-09-06 18:30:08', 2, 'free'),
(11553, '9-چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور طبیعی، در هر فرد جوان و بالغ، هورمون ......................... .»\n\nالف: $LH$، می‌تواند ترشح هورمون جنسی را افزایش دهد.\n\nب: $FSH$، می‌تواند بر تغذیهٔ یاخته‌های جنسی تأثیر بگذارد.\n\nج: جنسی، می‌تواند بر یاخته‌های خارج از غدد جنسی مؤثر باشد.\n\nد: پرولاکتین، می‌تواند در تنظیم فعالیت‌های تولیدمثلی نقش داشته باشد.', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11554, '10-کدام عبارت، دربارهٔ مراحل رشدونمو جنین انسان درست است؟', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11555, '11-با توجه به شکل مقابل که قسمتی از بدن یک مرد بالغ را نشان می‌دهد، کدام عبارت درست است؟\n\n\n\n۱) اسپرم‌ها می‌توانند از مجرایی درون ساختار «۱» یا «۳» عبور کنند.\n\n۲) بخش «۲» برخلاف بخش «۳»، می‌تواند حرکت اسپرم‌ها را تسهیل کند.\n\n۳) بخش «۱» همانند بخش «۴»، می‌تواند در قسمتی جلوتر از میزنای دیده شود.\n\n۴) بخش «۳» برخلاف بخش «۲»، می‌تواند مستقیماً در تماس با میزراه قرار بگیرد.', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11556, '12-درخصوص وقایع مربوط به برخورد و نفوذ زامه در مام‌یاخته، کدام مورد درست است؟', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11557, '13-همهٔ اندام‌های دستگاه تولیدمثل در مردان که خارج از محوطهٔ شکمی قرار گرفته‌اند و مستقیماً با مجرای زامه‌بر (اسپرم‌بر) نیز در تماس هستند، چه مشخصهٔ مشترکی دارند؟', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11558, '14-با توجه به مطالب کتاب درسی دربارهٔ نقش‌هایی که اندام‌های دستگاه تولیدمثل در زن برعهده دارند، کدام عبارت درست است؟', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11559, '15-با توجه به مطالب کتاب درسی دربارهٔ یاخته‌هایی که در بدن یک زن جوان، مستقیماً در دورهٔ جنسی فعالیت می‌کنند یا در تنظیم آن نقش دارند، کدام مورد، عبارت زیر را به‌درستی کامل می‌کند؟\n\n«همهٔ یاخته‌هایی که .........................، از نظر ......................... مشابه هستند.»', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11560, '16-اگر در روز صفر از یک دورهٔ جنسی زنی جوان، خون‌ریزی دوره‌ای آغاز شود، در این صورت کدام دو رخداد ذکر شده در یکی از گزینه‌های زیر، نمی‌توانند مربوط به یک روز باشند؟', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11561, '17-با توجه به شکل زیر، کدام عبارت درست است؟\n\n\n\n۱) وجه اشتراک «۲» و «۳»، تشکیل شدن توسط یاخته‌های بخش «۵» است.\n\n۲) وجه تمایز «۱» و «۳»، محافظت از جنین در برابر عوامل آسیب‌رسان است.\n\n۳) وجه تمایز «۱» و «۲»، تولید $HCG$ به‌منظور حفظ جسم زرد است.\n\n۴) وجه اشتراک «۱» و فضای «۴»، پر شدن توسط مایعات است.', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11562, '18-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در یک مرد سالم و بالغ، یاخته‌هایی در دستگاه تولیدمثل که ..................، به طور حتم .................. .»', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11563, '19-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در یک مرد بالغ و سالم، هر بخشی از ساختار زامه (اسپرم) که ..................، قطعاً .................. .»', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11564, '20-درخصوص مراحل تخمک‌زایی در یک زن سی ساله و سالم، کدام عبارت نادرست است؟', 2, 4, 25, 103, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11565, '21-مطابق اطلاعات کتاب درسی، کدام گزینه، ترتیب اتفاقات رخ داده در حدفاصل شروع تمایز جفت تا اتمام تمایز آن در فردی سالم را به‌درستی نشان می‌دهد؟\n\nالف: شروع عملکرد اندام‌های مختلف همزمان با رشد سریع آن‌ها ب: آغاز فعالیت انقباضی یاخته‌های ماهیچه‌ای قلب\n\nج: شکل مشخص گرفتن همه اندام‌های مختلف جنین د: مشخص شدن اندام‌های جنسی جنین\n\nه: ظاهر شدن جوانه‌های دست و پا و: شروع نمو رگ‌های خونی و روده', 2, 4, 25, 107, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
