(11600, '56-چند مورد زیر دربارهٔ زنبور به‌درستی بیان شده است؟\n\nالف) همهٔ زنبورهای کارگر مانند ملکه، ماده و $2n$ کروموزومی هستند.\n\nب) همهٔ نرها برخلاف ملکه، $n$ کروموزومی و حاصل بکرزایی هستند.\n\nج) همهٔ زنبورهای کارگر از لقاح اسپرم و تخمک به‌وجود می‌آیند.\n\nد) همهٔ زنبورهای ملکه برخلاف نرها، حاصل تولیدمثل جنسی هستند.', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
(11601, '57-چند مورد می‌تواند موجب ایجاد دوقلوهای هم‌سان شود؟\n\nالف) آزاد شدن هم‌زمان مام‌یاختهٔ ثانویه از هر تخمدان\n\nب) تقسیم شدن تودهٔ درونی بلاستوسیست به دو قسمت\n\nج) لقاح هم‌زمان دو اسپرم با یک مام‌یاختهٔ ثانویه\n\nد) جدا شدن یاخته‌های بنیادی حاصل از تخم', 2, 4, 25, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:57:51', 1, NULL, NULL, 'free'),
