(11775, '81- مطابق مطالب کتاب درسی، کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، بزرگ‌ترین بخش در دانهٔ بالغ ذرت .................. بزرگ‌ترین بخش در دانهٔ بالغ لوبیا ..................»', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11776, '82- در خصوص بزرگ‌ترین یاختهٔ قرارگرفته در کیسهٔ رویانی گیاه آلبالو، چند مورد درست است؟\n\nالف: در هر یک از هسته‌های خود، دارای یک مجموعهٔ فام‌تن (کروموزوم) است.\n\nب: نسبت به یاخته‌های دیگر کیسهٔ رویانی، در فاصلهٔ دورتری از منفذ تخمک قرار دارد.\n\nج: به‌طور مستقیم از تقسیم رشتمان (میتوز) یاختهٔ باقی‌مانده از تقسیم کاستمان (میوز) ایجاد شده است.\n\nد: پس از آمیزش، موجب تشکیل یاخته‌ای می‌شوند که با تقسیمات متوالی خود، ذخیرهٔ غذایی برای رشد رویان را می‌سازد.', 2, 4, 26, 43, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11777, ' درخصوص تشکیل و رویش دانه در گیاهان، کدام مورد نادرست است؟', 2, 4, 26, 45, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11778, '84- درخصوص مقایسهٔ یاخته‌های قرارگرفته در دانهٔ گردهٔ رسیده در گیاه آلبالو، کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\n«به‌طور معمول در دانهٔ گردهٔ رسیده، یاخته‌ای که مقدار .................. سیتوپلاسم دریافت کرده‌است، .................. یاختهٔ دیگر، به‌طور حتم ..................»', 2, 4, 26, 43, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11779, 'درخصوص مقایسهٔ گیاه‌های کدو و آلبالو، چند مورد نادرست است؟\n\nالف: در گیاه کدوی نر، در دومین حلقه از داخل، یاخته‌هایی با سبز‌دیسهٔ فراوان وجود دارد.\n\nب: در گیاه آلبالو، در سومین حلقه از خارج، یاخته‌های جنسی نر و فاقد تاژک تولید می‌شود.\n\nج: در گیاه کدوی ماده، در اولین حلقه از خارج، گلبرگ‌هایی زردرنگ و به‌هم پیوسته مشاهده می‌شود.\n\nد: در گیاه آلبالو، در اولین حلقه از داخل، هر یاختهٔ حاصل از کاستمان (میوز)، توانایی رشتمان (میتوز) دارد.', 2, 4, 26, 42, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11780, '86- درخصوص روشی از تولیدمثل در نهان‌دانگان که با استفاده از بخش‌های رویشی انجام می‌شود، کدام مورد درست است؟', 2, 4, 26, 41, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11781, 'در نوعی گیاه نهان‌دانه، توانایی تولید هر دو نوع گامت نر و ماده وجود دارد. درخصوص اجزای ساختار اختصاص‌یافته برای تولیدمثل جنسی در این گیاه، کدام مورد، به‌طور حتم درست است؟', 2, 4, 26, 42, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
