(11797, ' مشخصۀ مربوط به تکثیر رویشی در گیاه آلبالو، در کدام گزینه به طور صحیح بیان نشده است؟', 2, 4, 26, 41, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11798, ' کدام گزینه، عبارت زیر را به‌طور مناسب کامل می‌کند؟\n\n«در گیاه آلبالو، .................. یاختهٔ (یاخته‌های) قابل مشاهده درون کیسهٔ رویانی تخمک لقاح‌یافته، به‌طورحتم ..................»', 2, 4, 26, 43, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11799, ' در گیاهانی که بیشترین تعداد گونه‌های گیاهی روی زمین را تشکیل داده‌اند، تشکیل نوعی ساختار برای آنها هزینه‌بر است. در خصوص این ساختار در درخت آلبالو، کدام مورد درست است؟', 2, 4, 26, 42, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11800, ' چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«همواره با انجام تقسیم .................. در داخلی‌ترین حلقۀ گل .................. گیاه کدو، یاخته‌هایی تولید می‌شوند که ..................»\n\nالف: میتوز یاخته‌ای هاپلوئید - مادۀ - همگی تعداد کروموزوم برابری با یاختۀ ایجادکنندۀ لولۀ گرده دارند.\n\nب: میتوز یاخته‌ای هاپلوئید - نر - فقط بعضی از آنها با تشکیل دیوارۀ خارجی صاف یا تزئین‌دار، رسیده می‌شوند.\n\nج: میوز یاخته‌ای دیپلوئید - نر - همگی در ابتدا به یکدیگر متصل بوده و در مجموع، اندازۀ برابری با یاختۀ مادری دارند.\n\nد: میوز یاخته‌ای دیپلوئید - مادۀ - فقط بعضی از آنها با رسیدن علائمی به یاخته، پروتئین‌های تجزیه‌کنندۀ خود را طی چند ثانیه فعال می‌کنند.', 2, 4, 26, 43, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11801, '107- فرض می‌کنیم که مادگی گل گیاه کدو، تنها از یک برچه تشکیل شده است. باتوجه‌به توضیحات و به طور معمول، در خصوص بخش حجیم برچۀ یک گل مادۀ کدو که توسط حلقۀ دوم گل محافظت نمی‌شود، کدام مورد نادرست است؟', 2, 4, 26, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11802, ' طبق شکل زیر، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول بخش مشخص‌شده با شمارۀ ..................، معادل بخشی در دانۀ بالغ لوبیا است که ..................»', 2, 4, 26, 45, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11803, ' در خصوص عمر گیاهان، کدام مورد درست است؟', 2, 4, 26, 47, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11804, ' شکل زیر، مرحله‌ای از رویش دانۀ ذرت را نشان می‌دهد. به طور طبیعی، در خصوص فقط یکی از بخش‌های قابل‌مشاهده در این شکل، کدام مورد درست است؟', 2, 4, 26, 45, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 11:58:07', 1, NULL, NULL, 'free'),
(11805, 'با توجه به مطالب کتاب درسی، کدام مورد برای تکمیل عبارت زیر مناسب است؟ «اسیدسالسیلیک ترشح‌شده در گیاهان، .................. در انسان می‌شود.»', 2, 4, 27, 53, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11806, '2-با توجه به مطلب کتاب درسی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟ «نوعی هورمون که در زمینه رویش دانه‌ها اثری مخالف اکسین دارد، .................. نوعی هورمون که .................. می‌شود.»', 2, 4, 27, 51, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11807, '3-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ «دو تنظیم‌کننده رشد در گیاهان در فرآیندهای متفاوتی عمل می‌کنند؛ به‌طوری‌که فقط یکی از این تنظیم‌کننده‌های رشد ..................»', 2, 4, 27, 51, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, '2026-09-03 14:34:05', 2, 'free'),
(11808, '4-کدام عبارت، دربارۀ عوامل محیطی مؤثر بر رشد گیاهان نادرست است؟', 2, 4, 27, 52, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11809, 'کدام عبارت، دربارۀ حرکت در گیاهان درست است؟', 2, 4, 27, 52, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(11810, 'کدام عبارت، دربارۀ روش‌های دفاع گیاهان به‌درستی بیان شده است؟', 2, 4, 27, 53, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11811, '7-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ «نوعی تنظیم‌کنندۀ رشد که در گیاهان وجود دارد و شکل مصنوعی آن برای ساختن سموم کشاورزی به‌منظور از بین بردن گیاهان خودرو کاربرد دارد، ....................... هورمونی که .......................»', 2, 4, 27, 51, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11812, '8-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟ «هر تنظیم‌کنندۀ رشد در گیاهان که ....................... می‌شود، به‌طور حتم .......................»', 2, 4, 27, 51, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11813, '9-نوعی تنظیم‌کنندۀ رشد در گیاه گندم، سبب آزاد شدن و فعالیت آنزیم آمیلاز می‌شود. چند مورد، دربارۀ تنظیم‌کنندۀ رشد دیگری که اثری مخالف دارد، درست است؟ الف: فعالیت نوعی آنزیم تجزیه‌کنندۀ دیواره یاخته‌های روپوستی را مهار می‌کند. ب: می‌تواند باعث خروج پتاسیم از یاخته‌هایی سبزینه‌دار شود. ج: بر میزان فعالیت مریستم‌های نخستین ساقه بی‌تأثیر است. د: از تورژسانس بافت‌های درون دانۀ گیاه جلوگیری می‌کند.', 2, 4, 27, 51, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, '2026-09-03 14:38:03', 2, 'free'),
(11814, '10-در ارتباط با مطالب پاسخ‌هایی از جنس دفاع در گیاهان در کتاب درسی، کدام گزینه برای تکمیل عبارت زیر مناسب است؟ «هر ساختار دفاعی گیاه که .......................، به‌طور حتم .......................»', 2, 4, 27, 53, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, '2026-09-03 14:39:19', 2, 'free'),
(11815, 'مطابق با اطلاعات کتاب درسی، جانوران بالغی که از خورده شدن گیاه تنباکو توسط نوزاد کرمی‌شکل حشرات ممانعت می‌کنند، چه مشخصه‌ای دارند؟', 2, 4, 27, 53, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11816, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟ «به‌طور معمول در صورت افزایش میزان نوعی تنظیم‌کنندۀ رشد گیاهی که .......................»', 2, 4, 27, 51, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11817, '13-مطابق مطالب کتاب درسی، چند مورد برای تکمیل عبارت زیر مناسب است؟ «به‌طور معمول در گیاهان، هورمونی که برای اولین‌بار در نوعی قارچ کشف شد، با هورمونی که .......................، از نظر ....................... مشابه است.» الف: با رشد طولی یاخته، باعث افزایش طول ساقه می‌شود ـ کاربرد در تولید میوه‌های درشت و بدون‌دانه ب: در رشد جوانه‌های جانبی بعد از حذف جوانه رأسی مؤثر است ـ تأثیر بر تولید رشته‌های دوک تقسیم ج: تشکیل لایۀ جداکننده در دمبرگ را تسریع می‌کند ـ داشتن نقش در تولید آنزیم‌های تجزیه‌کنندۀ دیواره د: باعث تورژسانس یاخته‌های تمایزنیافتۀ روپوست می‌شود ـ داشتن نقش بازدارندگی براساس مقدار و محل اثر', 2, 4, 27, 51, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, '2026-09-03 14:41:33', 2, 'free'),
(11818, '14-کدام مورد، برای تکمیل عبارت زیر مناسب است؟ «نوعی مادۀ شیمیایی که به‌عنوان تنظیم‌کنندۀ رشد در گیاهان نیز شناخته می‌شود، می‌تواند .......................؛ در صورتی که ماده‌ای بتواند با اتصال به گیرندۀ این تنظیم‌کننده مانع از اثر آن شود، به‌طور حتم .......................»', 2, 4, 27, 51, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, '2026-09-03 14:41:06', 2, 'free'),
(11819, 'کدام گزینه در ارتباط با پاسخ‌های دفاعی گیاهان درست است؟', 2, 4, 27, 53, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11820, 'هر هورمون گیاهی که ....................... می‌شود، در ....................... نیز دخالت دارد.', 2, 4, 27, 51, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11821, 'کدام گزینه درباره انواع تنظیم‌کننده‌های رشد در گیاهان درست است؟ «در صورت …، می‌توان گفت: … .»', 2, 4, 27, 51, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11822, '18-در رابطه با مطالعات صورت گرفته بر روی پدیده‌ای رایج در گیاهان، کدام مورد درست است؟', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11823, '19-چند مورد عبارت زیر را به درستی تکمیل می کند؟ «هر هورمونی که … نمی‌تواند، … .» الف) موجب رشد طولی یاخته گیاهی می‌شود- سبب تحریک تقسیم یاخته‌ای شود. ب) موجب تولید آنزیم‌های گوارشی در لایه خارجی درون‌دانه (آندوسپرم) می‌شود- سبب توقف رشد جوانه‌های جانبی شود. ج) در تولید ریشه در کشت‌بافت نقش دارد- سبب تحریک ساقه‌زایی در کشت‌بافت شود. د) در چیرگی رأسی در جوانه جانبی کاهش می‌یابد- سبب تحریک رشد طولی یاخته‌های گیاهی شود.', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11824, '20-هورمون گیاهی که … قطعاً … .', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11825, '21-هورمونی که توسط بافت‌های آسیب‌دیده گیاه تولید می‌شود، … .', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11826, '22-کدام مورد نادرست است؟', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11827, '23-کدام مورد درباره نوعی هورمون که تأثیر منفی بر مراحل نمو جنینی در آدمی دارد، صدق نمی کند؟', 2, 4, 27, 49, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11828, '24-کدام گزینه، جهت کامل کردن عبارت زیر مناسب است؟ «اگر … .»', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11829, 'در رابطه با پاسخ به تماس در گیاهان، کدام مورد، درست است؟', 2, 4, 27, 52, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11830, '26-چند مورد عبارت زیر را به درستی تکمیل می کند؟ «پاسخ‌های … می‌توانند ناشی از … باشد.» الف) اندام‌های گیاهی به تماس - تغییر فشار تورژسانس یاخته‌ها ب) گیاهان به نور یک‌جانبه- پاسخ رشدی اندام گیاهی در خلاف سمت محرک ج) دفاعی گیاهان در مقابل میکروب‌ها- تغییر نفوذپذیری غشای یاخته در برابر یون‌ها د) دفاعی گیاهان در برابر میکروب‌ها- ترشح برخی ترکیبات آب‌گریز', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11831, '27-کدام گزینه، جهت تکمیل عبارت زیر مناسب است؟ «ترکیبات … .»', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11832, 'کدام گزینه به درستی بیان شده است؟', 2, 4, 27, 51, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11833, '29-درباره هورمون‌های گیاهی کدام درست است؟', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11834, '30- کدام عبارت دربارۀ گیاهان نادرست است؟', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11835, ' کدام گزینه عبارت زیر را به‌درستی تکمیل می‌کند؟ «یکی از راه‌های .................. گیاه .................. این است که .................. .»', 2, 4, 27, 53, 2, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11836, '32- چند مورد دربارۀ عملکرد تنظیم‌کننده‌های رشد گیاهی به‌درستی بیان شده است؟ الف) هورمون مؤثر در نورگرایی، برای انجام چیرگی رأسی، از جوانۀ انتهایی به جوانۀ جانبی می‌رسد. ب) هورمونی که در نوعی قارچ نیز وجود دارد، باعث افزایش تولید آمیلاز در لایۀ گلوتن‌دار گیاهان هم‌زیست با ریزوبیوم می‌شود. ج) برای تولید ساقه از کال در محیط کشت مناسب و سترون، وجود دو نوع تنظیم‌کنندۀ رشد متفاوت مورد نیاز است. د) برای جلوگیری از خراب شدن میوه‌ها هنگام انتقال، گیرندۀ درون یاخته‌ای نوعی هورمون گازی را با ترکیباتی تخریب می‌کنند.', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11837, '33- هورمونی که سبب تحریک جوانه‌زنی در دانه‌های جو می‌شود در کدام موارد زیر نقش دارد؟ الف) تولید میوه‌های بدون دانه ب) دخالت در نورگرایی ج) ریشه‌زایی و حفظ شادابی د) رشد طولی ساقه و درشت کردن میوه', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11838, ' هر هورمونی که .................. می‌شود، قطعاً .................. .', 2, 4, 27, 49, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11839, ' در رابطه با دفاع گیاهان می‌توان گفت .................. .', 2, 4, 27, 53, 2, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
(11840, '36- نوعی تنظیم‌کنندۀ رشد که به هنگام خورده شدن گیاه تنباکو توسط نوزاد کرمی‌شکل حشره آزاد می‌شود و ردپای آن در چیرگی رأسی هم دیده می‌شود .................. نوعی تنظیم‌کننده که منجر به تسریع تولیدمثل رویشی از نوع قلمه‌زدن می‌شود .................. .', 2, 4, 27, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-04 12:32:54', 1, NULL, NULL, 'free'),
