(12180, '55-در پروتئین‌سازی، کدام عمل درون ریبوزوم صورت نمی‌گیرد؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12181, '56-وقتی که مولکول $mRNA$ از روی رشتهٔ $DNA$ زیر رونویسی می‌گردد، چهارمین نوع آنتی‌کدون که به جایگاه $A$ می‌رود، کدام است؟\n\n$GAG\\cdot CTA\\cdot TAC\\cdot ATG\\cdot CTA\\cdot TAC\\cdot CTA\\cdot AAG\\cdot CAC$', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12182, '57-در فرآیند ترجمهٔ ژن اکتین (نوعی پروتئین تک‌رشته‌ای) در سلول‌های عضلانی انسان و در حین جابه‌جایی ریبوزوم بر روی $mRNA$، .................... .', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12183, '58-دربارهٔ تنظیم بیان ژن در یاخته‌های بدن انسان چند جمله نادرست است؟\n\nالف) همانند سایر یاخته‌های یوکاریوتی، تنظیم بیان ژن نمی‌تواند در خارج از هسته صورت بگیرد.\n\nب) همانند باکتری‌ها برای همهٔ ژن‌ها تنها یک راه‌انداز، رونویسی از چند ژن مجاور را ممکن می‌سازد.\n\nج) برخلاف پروکاریوت‌ها تنظیم بیان ژن می‌تواند با تغییر طول عمر رنای پیک همراه باشد.\n\nد) برخلاف پروکاریوت‌ها علاوه بر راه‌انداز توالی‌های دیگری از دنا در رونویسی دخالت دارند.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12184, '59-چند مورد در ارتباط با یک یاختهٔ یوکاریوتی فعال (یاخته‌ای که پروتئین‌سازی دارد)، درست است؟\n\n«به‌دنبال اتصال رناتن (ریبوزوم) در حال سنتز پروتئین به نوعی غشای زیستی ممکن است، .................... .»\n\nالف) ابتدا انتهای کربوکسیل رشتهٔ پلی‌پپتیدی به درون اندامک غشادار وارد شود\n\nب) نوعی بسپار (پلیمر) از اندامک غشادار خارج شود و وارد اندامک دوغشایی دیگری شود\n\nج) واکنش‌های شیمیایی از نوع سنتز آبدهی به انجام برسد\n\nد) نوعی کاتالیزور زیستی ساخته شود و برای فعالیت به خارج یاخته ترشح شود', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12185, '60-کدام گزینه در مورد نخستین مرحله از فرایند رونویسی در هستهٔ یاختهٔ مبارزه‌کننده با کرم انگلی موجود در محیط داخلی بدن درست است؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12186, '61-کدام گزینه، جهت کامل کردن عبارت زیر مناسب است؟\n\n«در مرحلهٔ طویل شدن رونویسی .................... .»', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12187, '62-کدام موارد می‌تواند جملهٔ زیر را به‌درستی کامل نماید؟\n\n«محصول عملکرد رنابسپاراز .................... محصول عملکرد رنابسپاراز .................... .»\n\nالف) دو برخلاف - پروکاریوتی، برای فعالیت خود، دچار تغییراتی می‌شود\n\nب) دو همانند - سه، در ساخت پروتئین فعال‌کننده نقش دارد\n\nج) پروکاریوتی برخلاف - یک، در محل تولید خود می‌تواند فعالیت نماید\n\nد) دو همانند - سه، برای ساخت رنابسپاراز دو مورد نیاز است', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12188, '63-کدام گزینه، عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در فرایند ترجمهٔ رنای پیک .................... .»', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12189, '64-در نوعی یاختهٔ دفاعی بدن انسان که از آن به‌عنوان نیروی واکنش سریع نام‌برده می‌شود، هر نوکلئیک‌اسیدی که .................... .', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12190, 'با توجه به تنظیم بیان ژن در سطح رونویسی در باکتری اشرشیاکلای، کدام گزینه جملهٔ زیر را به‌درستی کامل می‌نماید؟\n\n«در تنظیم .................... تنظیم .................... .»', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12191, '66-کدام گزینه در مورد تنظیم بیان ژن درست است؟', 3, 4, 29, 161, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12192, '67-می‌توان گفت هر کدون .................... .', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12193, 'در لولهٔ گوارش انسان، امکان مشاهدهٔ دی‌ساکاریدی وجود دارد که واحدهای سازندهٔ آن، یک نوع مونوساکارید با حلقه‌های شش‌کربنه می‌باشند. در نبود گلوکز و وجود این دی‌ساکارید در محیط کشت $E.Coli$، کدام اتفاق روی می‌دهد؟', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:10', 1, NULL, NULL, 'free'),
(12194, '69-در هنگام ترجمهٔ $mRNA$ی مقابل، کدام عبارت نادرست است؟\n\n$GCU \\cdot UAC \\cdot AUG \\cdot CCG \\cdot UAU \\cdot GCC \\cdot AUG \\cdot CUC \\cdot UAG \\cdot ACA$', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12195, '70-در فرایند ترجمه، اولین .................... .', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12196, 'در رابطه با فرایند تنظیم بیان ژن‌ها چند مورد عبارت زیر را به‌درستی تکمیل می‌کنند؟\n\n«هنگامی که .................... قطعاً .................... .»\n\nالف) ژن سازندهٔ آنزیم تجزیه‌کنندهٔ لاکتوز در حال رونویسی است - یک دی‌ساکارید به مهارکننده متصل است\n\nب) یک رنابسپاراز ۳ به راه‌انداز ژن متصل می‌شود - می‌توان گفت رونویسی از ژن انجام خواهد گرفت\n\nج) توالی افزاینده توسط تعدادی پروتئین کوچک اشغال شده است - راه‌انداز نیز به این پروتئین‌ها متصل است\n\nد) رنای پیک هموگلوبین در حال رونویسی است - هیچ رناتنی (ریبوزومی) نمی‌تواند به آن متصل باشد', 3, 4, 29, 161, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12197, '۷۲- چند مورد جملۀ زیر را به‌درستی تکمیل می‌کند؟\n\n«با توجه به مطالب کتاب درسی، در … مرحله از فرایند رونویسی، … .»\n\nالف) اولین - پیوندهای هیدروژنی بین تمام نوکلئوتیدهای دو رشتۀ دنا در محل راه‌انداز شکسته می‌شوند\n\nب) دومین - پیوندهای فسفودی‌استر برخلاف پیوندهای هیدروژنی شکسته نمی‌شوند\n\nج) دومین - پیوندهای هیدروژنی بین دو رشتۀ دنا هم شکسته و هم تشکیل می‌شوند\n\nد) سومین - بر طول رشتۀ پلی‌نوکلئوتیدی ساخته شده توسط رنابسپاراز افزوده نمی‌شود', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12198, '73-کدام گزینه دربارهٔ مرحله‌ای از فرایند رونویسی هر مولکول رنای پیک موجود در راکیزه (میتوکندری) درست است که برای نخستین‌بار در آن، اتصالات هیدروژنی میان نوکلئوتیدهای دنا و رنا به تدریج سست می‌شود؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12199, 'کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«اگر به منظور بررسی تغییرات رنای پیک پس از رونویسی، یک رنای پیک درون سیتوپلاسم را با رشتهٔ الگوی ژن آن در دنا مجاورت دهیم، هر بخشی که به صورت .................... مشاهده می‌شود، به‌طور حتم .................... .»', 3, 4, 29, 154, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12200, '75-کدام مورد، دربارهٔ همهٔ نوکلئیک‌اسیدهایی صحیح است که در یک گیرندهٔ مخروطی شبکیهٔ چشم انسان می‌توانند با بخشی از مولکول رنا پیوند هیدروژنی تشکیل دهند؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12201, '76-کدام گزینه، دربارهٔ زمینه‌های فعالیت مولکول‌های پروتئینی بدن انسان به‌درستی بیان شده است؟', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12202, '77-با توجه به ساختارهای مختلف رنای ناقل در یک یاختهٔ یوکاریوتی، چند مورد عبارت زیر را به نادرستی کامل می‌کند؟\n\n«هر ساختاری از رنای ناقل که توانایی برقراری پیوند هیدروژنی با نوع دیگری از نوکلئیک اسید را .................... ، .................... .»\n\nالف: دارد، زودتر از آمینواسید، به آنزیم متصل‌کنندهٔ رنای ناقل به آمینواسید متصل می‌شود.\n\nب: دارد، توالی محل اتصال آمینواسید و توالی پادرمزه، کمترین فاصله را از یکدیگر دارند.\n\nج: ندارد، تعداد پیوندهای کم انرژی بین نوکلئوتیدی در بازوهای مختلف باهم برابر است.\n\nد: ندارد، بر اساس پادرمزهٔ خود تنها توانایی اتصال به یک نوع آمینواسید خاص را دارد.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12203, '78-کدام یک از گزینه‌های زیر، درست است؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12204, '79-فرایند ترجمه از سه مرحله کلی تشکیل شده است. در مرحله‌هایی از ترجمهٔ رنای پیک اکتین این امکان وجود دارد تا برای مدت زمانی دو جایگاه رناتن از رنای ناقل خالی باشند. کدام گزینه در خصوص تنها یکی از این مراحل صادق است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12205, '80-کدام گزینه عبارت زیر را به نحو متفاوتی نسبت به سایر گزینه‌ها کامل می‌کند؟\n\n«به طور معمول .................... توالی‌های سه نوکلئوتیدی از $mRNA$ که علی‌رغم قرارگرفتن در یکی از جایگاه‌های رناتن (ریبوزوم)، نقشی در قرارگیری آمینواسید جدید در رشتهٔ پلی‌پپتیدی ساخته‌شده ندارند، .................... .»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12206, '81-در خصوص محل پروتئین‌سازی و سرنوشت پروتئین‌های ساخته‌شده در یک یاختهٔ کبدی انسان، کدام موارد زیر درست است؟\n\nالف: رناتن‌ها منحصراً به صورت آزاد در سیتوپلاسم یا چسبیده به غشای شبکهٔ آندوپلاسمی مشاهده می‌شوند.\n\nب: پروتئین‌های ساخته‌شده توسط رناتن‌های آزاد در سیتوپلاسم، همگی وارد ساختاری دوغشایی می‌شوند.\n\nج: ادغام هر ریزکیسهٔ حاوی پروتئین با غشای یاخته، ترشح نوعی پروتئین به خارج یاخته را در پی دارد.\n\nد: فرایند ترجمهٔ یک مولکول رنای پیک، ممکن است به‌طور هم‌زمان توسط چندین رناتن صورت گیرد.', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12207, '82-در خصوص پروتئین‌سازی یک یاختهٔ یوکاریوتی، چند مورد، نادرست است؟\n\n«به منظور ترجمهٔ رنای پیک، .................... از این که $tRNA$ حاوی .................... شود، به‌طور حتم .................... .»\n\nالف: بعد - توالی آمینواسیدی در جایگاه $E$ دیده - جابه‌جایی رناتن رخ می‌دهد.\n\nب: قبل - توالی آمینواسیدی وارد جایگاه $P$ - پیوند پپتیدی در جایگاه $P$ شکسته می‌شود.\n\nج: بعد - توالی آمینواسیدی در جایگاه $A$ مشاهده - رناتن به سوی رمزهٔ پایان $UAG$ پیش می‌رود.\n\nد: قبل - یک آمینواسید در جایگاه $A$ مشاهده - نوعی پیوند کم‌انرژی در جایگاه $E$ شکسته می‌شود.', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12208, 'در کتاب درسی، یکی از روش‌های تغییر در ساختار رنای پیک بیان شده‌است. انجام کدام مورد یا موارد زیر، جهت وقوع چنین فرایندی، به‌طور حتم، ضروری است؟\n\nالف: کاهش طول رشته پلی‌نوکلئوتیدی به‌دنبال جداشدن قسمت‌هایی از آن\n\nب: حذف بخش‌هایی از دنا که الزاماً نسبت به بخش‌های اطراف، اندازه بزرگ‌تری دارند\n\nج: تشکیل ساختمان‌های حلقه‌ای در رنا به دنبال قرارگیری در کنار رشته الگوی دنا\n\nد: شکسته شدن و تشکیل پیوندهای جدید میان گروه‌های قند و فسفات برخی از نوکلئوتیدهای رنا', 3, 4, 29, 154, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12209, '84-با توجه به شکل مقابل، کدام مورد همواره درست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12210, '85-کدام گزینه عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«در ژنگان یک فرد بالغ در صورتی که .......................»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12211, '86-چند مورد عبارت زیر را به طور درست تکمیل می‌کنند؟\n\n«(در) فرایندی که در گفتار ۱ فصل ۲ دوازدهم مطرح شده است و بر روی ژن صورت می‌گیرد، .................... فرایندی که در گفتار ۲ فصل ۲ دوازدهم ذکرشده است، .................... .»\n\nالف) همانند - به‌طور حتم، مونومرهای واجد نیتروژن مصرف می‌شود.\n\nب) برخلاف - به‌طور حتم، همواره محصولی واجد جایگاه فعال تولید می‌گردد.\n\nج) همانند - ممکن است، تنها بخشی از یک نوکلئیک اسید الگو قرار گیرد.\n\nد) برخلاف - ممکن است، محصولی با حساسیت زیاد نسبت به افزایش دما تولید گردد.', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12212, '87-کدام گزینه عبارت زیر را به طور مناسب کامل می‌نماید؟\n\n\n\n«پس از .................... پیوند کم‌انرژی بین پادرمزه رنای ناقل اشاره‌شده در شکل زیر با رمزه مکمل خود در رنای پیک .................... محتمل است.»', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12213, '88-کدام گزینه به‌طور صحیح در رابطه با فرایند ترجمه بیان شده است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12214, '89-کدام گزینه با توجه به تنظیم بیان ژن در یوکاریوت‌ها برای تکمیل عبارت زیر نامناسب است؟\n\n«مولکولی که از دسترسی رنای رناتنی به پیش‌ماده جلوگیری می‌کند .................... مولکولی که از دسترسی رنابسپاراز به پیش‌ماده جلوگیری می‌کند .................... .»', 3, 4, 29, 160, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12215, 'کدام یک از موارد تنظیم بیان ژن، تنها در یوکاریوت‌ها دیده می‌شود؟', 3, 4, 29, 160, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12216, 'کدام گزینه جمله مقابل را به درستی تکمیل می‌کند؟ «با توجه به فرایندهای تنظیم بیان ژن در مرحله رونویسی که در کتاب درسی آمده است، هر پروتئین موثر در تنظیم بیان ژن که .................... .»', 3, 4, 29, 161, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12217, 'چند مورد وجه اشتراک همه توالی‌های غیر از راه‌انداز و مؤثر در تنظیم رونویسی مثبت و منفی باکتری اشرشیاکلای است؟\n\nالف) امکان تماس با پروتئین‌های غیر آنزیمی را دارند.\n\nب) در شرایطی به مولکول حاوی قند حلقوی متصل می‌شوند.\n\nج) با رمز مربوط به متیونین آغازگر تماس دارند.\n\nد) نسبت به هر ژن، پیوند فسفودی‌استر کمتری دارند.', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12218, 'چند مورد از عبارت‌های زیر به طور درست بیان شده است؟\n\nالف) تغییر شکل پروتئین، ممکن است به صورت برگشت پذیر و بدون تغییر پیوندهای پپتیدی صورت گیرد.\n\nب) اختلال در راه‌انداز اپران لک، منجر به تغییر بیان سه ژن مربوط به سنتز لاکتوز در اشرشیاکلای می‌شود.\n\nج) هر توالی متصل به ابتدای هر ژن، جزئی از توالی بین ژنی محسوب شده و از روی آن رونویسی صورت نمی‌گیرد.\n\nد) اتصال عوامل رونویسی به افزاینده، همواره ابتدا باعث خمیدگی در دنا و سپس باعث اتصال رنابسپاراز به راه‌انداز می‌شود.', 3, 4, 29, 161, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12219, 'کدام گزینه عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«اگر در محیطی فاقد گلوکز، باکتری اشرشیاکلای را از محلی که فقط واجد .................... می‌باشد، به محلی که تنها دارای .................... است، منتقل کنیم؛ آن‌گاه .................... .»', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12220, '95-چند مورد در ارتباط با «ویژگی مشترک فرایند رونویسی در همه‌ی یاخته‌هایی که دنای آن‌ها به کمک پروتئین فشرده می‌شود» درست نیست؟\n\nالف- شناسایی اختصاصی بخش‌هایی از ژن توسط کاتالیزورهای زیستی به منظور تعیین محل صحیح شروع رونویسی\n\nب- بررسی رابطه مکملی بین نوکلئوتیدهای رشته‌ی الگو و رنای درحال تشکیل بعد از تشکیل هر پیوند فسفودی استری\n\nپ- فعالیت هم‌زمان تعداد زیادی آنزیم به منظور رونویسی از یک ژن و آغاز ترجمه‌ی رنای پیک قبل از پایان رونویسی\n\nت- الگو قرارگرفتن نخستین نوکلئوتید هر ژن پس از توالی راه‌انداز به‌منظور تولید رشته‌ی کوچکی از رنا در نخستین مرحله', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12221, 'به طور معمول، در همه گزینه‌ها دو ویژگی در مورد یکی از پروتئین‌های موجود در یک یاخته جانوری فعال، درست بیان شده‌اند؛ به جز .................... .', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12222, 'گروهی از جانداران نمی‌توانند مولکول‌های رنا (RNA)ی موجود در دومین مرحله رونویسی را توسط زیرواحدهای تشکیل‌دهنده رناتن به دام بیاندازند. کدام گزینه در خصوص این جانداران درست است؟', 3, 4, 29, 155, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12223, 'در خصوص نخستین مرحله رونویسی در هسته یاخته‌های یوکاریوتی، کدام عبارت صادق است؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12224, '99-مراحلی از فرایند ساخت رشته رنا از روی بخشی از رشته الگوی دنا وجود دارند که شکسته شدن پیوندهای هیدروژنی بین رشته رنای تازه ساخت و رشته الگوی دنا ممکن است. به ترتیب چند مورد (تنها در یکی از این مراحل) و چند مورد در (بیش از یکی از این مراحل) رخ می‌دهد؟\n\nالف) خروج آنزیم تجزیه‌کننده پیوندهای هیدروژنی از حباب رونویسی پیش از خروج رنای پیک از محل حباب\n\nب) جداشدن دو رشته دنا در محل راه‌انداز در پی اتصال آنزیم رونویسی کننده به دنا\n\nج) شکسته شدن پیوند بین گروه فسفات و قند در ساختار ریبونوکلئوتیدها\n\nد) تشکیل پیوند فسفودی استر پس از تشکیل پیوند هیدروژنی', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12225, 'در خصوص آن دسته از پروتئین‌هایی که توسط رناتن‌های متصل به شبکه آندوپلاسمی یک یاخته پادتن‌ساز تولید می‌شوند، کدام مورد نادرست است؟', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12226, 'چند مورد، معرف نوعی تنظیم بیان ژن در یوکاریوت‌ها در مرحله‌ای غیر از رونویسی می‌باشد؟\n\nالف: افزایش تعداد پروتئین‌های کروی در بخشی از فام‌تن به منظور تغییر فشردگی\n\nب: تغییر تمایل پروتئین‌های کروی(به‌جز عوامل رونویسی) به توالی راه‌انداز در ژن\n\nج: ایجاد پیوندهای هیدروژنی به منظور جلوگیری از فعالیت رناتن‌ها\n\nد: سازوکارهای حفاظتی جهت حفظ ساختار رنای پیک', 3, 4, 29, 160, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12227, 'با توجه به مطالب ذکر شده در کتاب درسی، در تنظیم بیان ژن باکتری اشرشیاکلای، کدام ویژگی، تنظیم منفی رونویسی را از تنظیم مثبت رونویسی، متمایز می‌سازد؟', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12228, '103-چند مورد به منظور تکمیل عبارت زیر نامناسب است؟\n\n«با توجه به فرایند ترجمه در پروکاریوت‌ها می‌توان داشت؛ پس از آن که رنای ناقل (tRNA) .................... به‌طور حتم .................... می‌شود.»\n\nالف) به جایگاه A رناتن (ریبوزوم) وارد شود - پیوند بین آمینواسید و نوکلئوتید شکسته\n\nب) حاوی زنجیره پپتیدی در جایگاه P قرار گیرد - رنای ناقل بعدی درون جایگاه A، مستقر\n\nج) دارای پادمزه AAU در جایگاه A قرار گیرد - فعالیت عوامل آزادکننده به منظور پایان ترجمه شروع\n\nد) در مرحله آغاز به جایگاه E منتقل شود - دومین حرکت رناتن (ریبوزوم) در طول مولکول رنای پیک مشاهده', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12229, '104-در باکتری استرپتوکوکوس نومونیا، ساختارهایی در محل یک ژن مشاهده می‌شود که می‌توان آن‌ها را به تسبیح تشبیه کرد. با توجه به این ساختار کدام گزینه برای تکمیل عبارت زیر نامناسب است؟\n\n«در هر ساختار تسبیح‌مانند، .................... .»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12230, '105-کدام مورد در رابطه با همه‌ی یاخته‌های موجود در بافت پشتیبانی کننده از بافت پوششی درست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12231, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در یک یاخته پلاسماسیست، در هر مرحله‌ای از .................... می‌شود، به‌طور طبیعی .................... .»', 3, 4, 29, 154, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12232, 'کدام موارد در رابطه با ریبوزوم‌های آزاد در سیتوپلاسم یاخته‌های زنده به‌طور حتم درست است؟\n\nالف- نمی‌توانند به تولید پروتئین‌هایی بپردازند که به بیرون از یاخته ترشح می‌شوند.\n\nب- رشته‌ی پلی‌پپتیدی تازه‌ساخت را از سمت زیرواحد بزرگ خود وارد سیتوپلاسم می‌نمایند.\n\nج- نمی‌توانند به ترجمه‌ی مولکول رنای پیکی بپردازند که رونویسی از ژن آن هنوز به اتمام نرسیده است.\n\nد- گروهی از پروتئین‌های تولیدی در آن‌ها، به کمک توالی‌های آمینواسیدی خود به سمت هسته هدایت می‌شوند.', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12233, 'چند مورد برای تکمیل عبارت زیر مناسب نیست؟\n\n«مطابق اطلاعات کتاب درسی، همۀ بخش‌های دورشته‌ای در یک دنای هسته‌ای طبیعی، که آنزیم‌های رنابسپاراز از آن‌ها رونویسی نمی‌کنند، قطعاً .........................»\n\nالف- در بخش‌های فشردۀ فام‌تن قرار دارند.\n\nب- دو رشتهٔ آن‌ها در شرایطی از یکدیگر فاصله می‌گیرند.\n\nج- در توالی‌های تنظیمی یا بین‌ژنی قرار دارند.\n\nد- در ساختار خود دارای تعداد برابری از پورین و پیریمیدین هستند.', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12234, 'کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«مطابق اطلاعات کتاب درسی، در ................. مرحله از رونویسی ژن سازندۀ پروتئین کانالی در یک یاختۀ حاصل از تقسیم، قطعاً ..................»', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12235, '110-در خصوص فرایند رونویسی از ژن‌های اپران لک در باکتری E.coli، کدام مورد درست است؟ (حالت جدا بودن مهارکننده از اپراتور را در نظر بگیرید.)\n\n«در مرحله‌ای که .........................»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12236, '111-مطابق با مطالب کتاب درسی، در خصوص گروهی از جانداران صحیح است که بدون نیاز به عوامل رونویسی می‌توانند عمل رونویسی از دنا (DNA) را فقط به کمک نوع خاصی از واکنش‌دهنده‌های زیستی به انجام برسانند؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12237, '112-کدام گزینه عبارت زیر را به طور نادرست کامل می‌نماید؟\n\n«با توجه به فرایند ترجمۀ زنجیرۀ میوگلوبین، در زمانی که ...................... به‌طورحتم، .......................»', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12238, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«با توجه به همانندسازی DNA و فرایندهای پیش از آن در نوعی یاختۀ یوکاریوتی، هر آنزیمی که ..........................»', 3, 4, 28, 148, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12239, '114-نوعی آنزیم در یوکاریوت‌ها باعث اتصال رنای ناقل به آمینواسیدها می‌شود. این آنزیم به طورحتم ..........................', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12240, 'به منظور تکمیل عبارت زیر، کدام مورد یا موارد زیر نامناسب است؟\n\n«در طی مراحل ساخت رشتهٔ پلی پپتیدی در نوعی یاخته پوششی بدن، (در) هر بسپاری که از خارج از ریبوزوم وارد جایگاه A می‌شود، .....................»\n\nالف) بلافاصله منجر به خروج نوعی بسپار از جایگاه دیگر ریبوزوم می‌شود.\n\nب) کنار هم قرارگیری واحدهای نیتروژن‌دار آن طی فرآیندی درون یاخته‌ای و تدریجی رخ داده است.\n\nج) در ساختار خود، واجد فقط یک نوع پیوند اشتراکی خاص است.\n\nد) پیوندهایی سست و کم‌انرژی در بخش‌هایی از ساختار آن مشاهده می‌شود.', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12241, 'با توجه به اطلاعات کتاب درسی در ارتباط با بیان ژن‌های مربوط به تجزیۀ لاکتوز و مالتوز در باکتری اشرشیاکلای، چند مورد تنظیم منفی رونویسی این باکتری را از تنظیم مثبت آن، متمایز می‌کند؟\n\nالف) روشن بودن ژن‌ها در صورت اتصال پروتئین تنظیمی به توالی تنظیمی\n\nب) تغییر میل ترکیبی پروتئین تنظیمی به دنا در پی اتصال به نوعی دی‌ساکارید\n\nج) وجود تنها یک توالی تنظیمی در مسیر رنابسپاراز تا اولین نوکلئوتید قابل رونویسی\n\nد) اتصال پروتئین تنظیمی به توالی تنظیمی در صورت فقدان لاکتوز و مالتوز در اطراف باکتری', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12242, 'مطابق اطلاعات کتاب درسی، «نوع ویژه‌ای از رنا (RNA)ها پس از ورود به سیتوپلاسم یاخته، آمینواسیدها را برای استفاده در پروتئین‌سازی به سمت رناتن (ریبوزوم)ها می‌برند.»، کدام دو ویژگی، درباره این مولکول‌ها، صادق است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12243, 'با توجه به فرایند ترجمه و رناهای ناقلی که مکمل کدون‌های وروردی به ریبوزوم هستند، کدام گزینه به طور صحیح بیان نشده است؟\n\n« حین فرایند ترجمه، هر tRNA که ........................ »', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(12244, 'با توجه به شکل مقابل که رشتهٔ الگوی ژن مربوط به نوعی پروتئین را به همراه رشتهٔ مکمل آن نشان می‌دهد، کدام عبارت به طور صحیحی بیان شده است؟', 3, 4, 29, 154, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12245, 'با توجه به شکل مقابل که نوعی رنای ناقل متصل به رشته‌ی پلی‌پپتیدی را نشان می‌دهد، کدام عبارت درست است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12246, 'در ارتباط با یاخته‌های یوکاریوتی، کدام مورد زیر به طور صحیح بیان نشده است؟', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12247, 'در خصوص پروتئین‌سازی در یاخته‌های پادتن‌ساز، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«بعد از اینکه ..................... می‌شود، به طور حتم .................... مشاهده می‌شود»', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12248, 'گزینه نامناسب برای تکمیل عبارت زیر، کدام است؟\n\n«مطابق با مطالب کتاب درسی، در فرایندهای تنظیم بیان ژن باکتری اشرشیاکلای (E.coli)، ................. تنظیم ................. متمایز می‌سازد.»', 3, 4, 29, 161, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12249, 'فرض می‌کنیم در قطعه‌ای از مولکول دنای یک یاختهٔ جانوری فعال، دو ژن متوالی سازندۀ رنای رناتنی، با فاصله‌ای در پشت سر هم قرار دارند. درخصوص رونویسی از این دو ژن، کدام مورد نادرست است؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12250, 'در جانداران مختلف گروهی از پروتئین‌ها، حداقل بخشی از فعالیت خود را در ماده زمینه‌ای سیتوپلاسم به انجام می‌رسانند. کدام مورد ویژگی مشترک همه انواع ریبوزوم‌هایی است که این پروتئین‌ها را تولید می‌کنند؟', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12251, 'چند مورد در رابطه با هر آنزیم موثر در بیان ژن یا ژن‌های آنزیم برش‌دهنده دنا صادق است؟\n\nالف: به منظور تولید آن، ابتدا بر غلظت فسفات آزاد در سیتوپلاسم افزوده شده است.\n\nب: واحدهای سازنده آن در ریبوزوم‌های آزاد در سیتوپلاسم به یکدیگر متصل می‌گردند.\n\nج: به کمک واحدهای کوچک موجود در ساختار خود به سمت محل فعالیت هدایت می‌شود.\n\nد: در شکستن و تشکیل پیوندهای اشتراکی و غیراشتراکی در مجاورت مولکول دنا دخالت دارد.', 3, 4, 29, 161, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12252, 'در خصوص یاخته‌های پروکاریوتی، کدام یک از موارد زیر صحیح است؟\n\n\n\nالف: از روی همه‌ی مولکول‌های رنای پیک در آن‌ها، قبل از اتمام تولید، رشته پلی‌پپتیدی تولید می‌شود.\n\nب: به‌طور معمول به منظور خاموش نگه داشتن ژن یا ژن‌های خاص، از روی آن رونویسی انجام نمی‌دهند.\n\nج: برخی از رناهای پیک پس از بلوغ می‌توانند بخش کوچک ریبوزوم را به سمت قسمتی از خود هدایت کنند.\n\nد: به منظور تولید پروتئین در سیتوپلاسم آن‌ها، ساختار تسبیح‌مانند می‌تواند بر روی ساختار پرمانند مشاهده شود.', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12253, '128-در خصوص یاختۀ پوشانندۀ بزرگ‌ترین بخش معده در گاو، کدام مورد نادرست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12254, '129-در خصوص فرایند ترجمه در یاخته‌های یوکاریوتی، کدام مورد یا موارد درست است؟\n\nالف: هر رنای ناقل وارد شده به جایگاه A رناتن، در نهایت به جایگاه P آن وارد می‌شود.\n\nب: هر رنای ناقل خارج شده از جایگاه P رناتن، پس از جابه‌جایی رناتن به جایگاه E وارد می‌شود.\n\nج: فقط بعضی از رناهای ناقل وارد شده به جایگاه P رناتن، در ادامه از جایگاه E رناتن عبور می‌کنند.\n\nد: فقط بعضی از رناهای ناقل خارج شده از جایگاه A رناتن، با رمزۀ موجود در جایگاه A آن، پیوند برقرار می‌کنند.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12255, '130-کدام مورد، برای تکمیل عبارت زیر، نامناسب است؟\n\n«به طور معمول، در هر مرحله‌ای از فرایند ساخته‌شدن مولکول رنا که در طی آن .........................»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12256, '131-کدام موارد، برای تکمیل عبارت زیر، نامناسب است؟\n\n«باتوجه‌به مطالب کتاب‌درسی، هر بسپاری که به طور کامل ساخته شده و محصول مستقیم یکی از رشته‌های دنا (DNA) است، به طور حتم ............................»\n\nالف: در میان نوکلئوتیدهای سازندۀ رشتۀ خود، می‌تواند پیوند هیدروژنی برقرار کند.\n\nب: در طی فرایند ساخت آن، فقط یک نوع آنزیم پروتئینی شرکت می‌کند.\n\nج: دارای دو انتهای متفاوت در ساختار مولکولی خود در یاختۀ سازنده است.\n\nد: نوعی فعالیت نوکلئازی در یاخته، می‌تواند منجر به کوتاه‌شدن آن شود.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12257, '132- در خصوص پیوندهای تشکیل شده و شکسته شده در طی فرایند ترجمه، کدام مورد درست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12258, '133- در خصوص یاخته‌هایی که واجد پروتئین‌های هیستون در اطراف دنای اصلی خود هستند، کدام مورد همواره صحیح است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12259, '134- با توجه به مطالب کتاب درسی، در خصوص فرایندهای تنظیم بیان ژن در مرحلهٔ رونویسی، چند مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، در نوعی تنظیم بیان ژن در باکتری اشرشیاکلای که …»\n\nالف: پیوستن قند به پروتئین منجر به آغاز رونویسی می‌شود، آنزیم رنابسپاراز از سه واجد توالی TACTACTAC عبور می‌کند.\n\nب: راه‌انداز در تماس با توالی‌های ژنی نیست، تمایل پیوستن نوعی پروتئین به جایگاه ویژهٔ خود، تحت عواملی تغییر می‌کند.\n\nج: حرکت مجموعهٔ آنزیمی به پیوستن قند به پروتئین وابسته است، شکل سه‌بعدی در نوعی پروتئین دچار تغییراتی می‌شود.\n\nد: نوعی پروتئین با اتصال به توالی ژنی، مانع انجام رونویسی شده است، آنزیم‌های تجزیه‌کنندهٔ قند موجود در شیر تولید می‌شوند.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12260, '135- در خصوص باکتری اشرشیاکلای، کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«به‌طور معمول، در شرایطی که این باکتری از محیط دارای فقط قند … به محیط دارای فقط قند … منتقل شود، می‌توان … را مشاهده کرد.»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12261, '136- در یوکاریوت‌ها، به ترتیب از راست به چپ، کدام مورد یا موارد را می‌توان جزء تنظیم بیان ژن پیش از رونویسی و پس از رونویسی دانست؟\n\nالف: خمیدگی یا عدم خمیدگی در بخشی از مولکول دنا (DNADNADNA) - جدا و حذف‌شدن بخش‌های معین از مولکول دنا (DNADNADNA)\n\nب: اتصال بعضی از رناهای کوچک به مولکول دنا (DNADNADNA) - افزایش میزان پایداری در نوعی مولکول ریبونوکلئیک‌اسیدی\n\nج: تغییر در وضعیت قرارگیری نوکلئوزوم‌ها نسبت به یکدیگر - برقراری پیوند هیدروژنی بین ریبونوکلئوتیدها\n\nد: تنظیم میزان دسترسی آنزیم به پیش‌ماده - اتصال نوعی آنزیم پروتئینی به عوامل رونویسی', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12262, '137- با توجه به مطالب کتاب درسی، در خصوص فرایندهای تنظیم بیان ژن در مرحلهٔ رونویسی در نوعی یاخته، کدام مورد نادرست است؟', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12263, '138- با توجه به دسته‌بندی جانداران به دو دستهٔ پروکاریوت و یوکاریوت، کدام موارد، برای تکمیل عبارت زیر مناسب است؟\n\n«در دسته‌ای از جانداران که … گروه دیگر، می‌توان شاهد … بود.»\n\nالف: پروتئین‌های غشایی توسط ریبوزوم‌های آزاد ساخته می‌شوند، همانند - آغاز پروتئین‌سازی پیش از پایان رونویسی رنای پیک\n\nب: آغاز همانندسازی در چندین نقطه در هر فام‌تن انجام می‌شود، برخلاف - عدم شناسایی راه‌انداز توسط رنابسپاراز به‌تنهایی\n\nج: مولکول‌های وراثتی در غشا محصور نشده‌اند، برخلاف - ساخت پروتئین‌ها به‌طور همزمان توسط مجموعه‌ای از رناتن‌ها\n\nد: سازوکارهایی برای حفاظت رنای پیک در برابر تخریب وجود دارد، همانند - تغییر در پایداری (طول عمر) رنای پیک', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12264, '139- با توجه به شکل زیر، کدام مورد درست است؟\n\n\n\nالف: بخش «6»، نزدیک‌ترین رناتن به انتهای رنای پیک در حال رونویسی در هسته است.\n\nب: مولکول «2»، توسط رنابسپارازی با توانایی شکستن نوعی پیوند اشتراکی ساخته می‌شود.\n\nج: ماهیت مولکولی بخش «4»، مشابه مولکول متصل‌شونده به اپراتور در تنظیم مثبت بیان ژن است.\n\nد: مولکول «3»، بخشی از دنای حاوی ژن‌های مقاومت به پادزیست بوده که توانایی اتصال به غشای یاخته را دارد.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12265, '140- با توجه به شکل‌های زیر که فرایند رونویسی را در یک نورون رابط نخاع نشان می‌دهد، کدام مورد وجه تمایز مراحلی از رونویسی است که رناهای مشخص شده با شماره‌های (1) و (2)، در آن قرار دارند؟\n\n\n\nپیوندهای کم‌انرژی بین نوکلئوتیدهایی با قند متفاوت، شکسته و تشکیل می‌شوند.\n\nرشتهٔ رنای تولید شده، در جهت مخالف حرکت آنزیم از حباب رونویسی خارج می‌شود.\n\nتوالی(های) نوکلئوتیدی در تعیین طول رشتهٔ تولیدی و تنظیم عملکرد آنزیم نقش دارد.\n\nمولکول‌های تولید شده، دستخوش تغییراتی برای انجام عملکرد خود در حین رونویسی می‌شوند.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12266, '141- با صرف‌نظر از جهش‌های کوچک مؤثر بر ساختار پروتئین‌ها، در خصوص فرایند ترجمه و ساختار ریبوزوم، چند مورد، عبارت زیر را به طور مناسب کامل می‌کند؟\n\n«به‌طور معمول، نوعی کدون که …، قطعاً …»\n\nالف: هرگز به جایگاه A وارد نمی‌شود - معرف آمینواسید متیونین است.\n\nب: به هر سه جایگاه وارد می‌شود - معرف نوعی آمینواسید در ساختار پروتئین است.\n\nج: فقط به جایگاه A وارد می‌شود - دارای نوکلئوتیدهای آدنین‌دار و یوراسیل‌دار است.\n\nد: فقط به جایگاه E وارد نمی‌شود - به آخرین رنای ناقل شرکت‌کننده در فرایند ترجمه متصل می‌شود.', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
(12267, '142- شکل زیر، لحظه‌ای را در فرایند ساخت نوعی پلی‌پپتید نشان می‌دهد. کدام گزینه در مورد اتفاقات انجام شده قبل از این لحظه، ترتیب درستی را بیان کرده است؟\n\n\n\nورود عواملی به جایگاه A ریبوزوم و سپس شکستن پیوند اشتراکی بین گروه آمین آمینواسید و رنای ناقل\n\nشکستن پیوند هیدروژنی در جایگاه E و سپس حرکت ریبوزوم به سمت کدون پایان برای آخرین بار\n\nورود ساختاری پروتئینی به جایگاه A و سپس خروج رنای ناقل یکی‌مانده به آخر از جایگاه E\n\nورود ساختاری پلی‌پپتیدی به جایگاه A و سپس خروج پلی‌پپتید از جایگاه P', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 15:57:35', 2, 'free'),
(12268, '143- در خصوص نوعی عامل رونویسی موجود در یاخته‌های انسان که در توالی نوکلئوتیدی محل اتصال رنابسپاراز به دنا، به چندین مولکول بزرگ‌تر از خود متصل می‌شود، کدام موارد درست است؟\n\nالف: تمایل پیوستن آن به راه‌انداز، تحت شرایطی تغییر می‌کند.\n\nب: ممکن است در فاصله‌ای دور از ژن‌ها و راه‌انداز قرار داشته باشد.\n\nج: ضمن اتصال آن به توالی خاصی از دنا، یک خمیدگی در دنا ایجاد می‌شود.\n\nد: ممکن است به همراه دو نوع عامل رونویسی، سرعت رونویسی را افزایش دهد.', 3, 4, 29, 153, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 15:58:47', 2, 'free'),
(12269, '144- کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«در حین فرایند تولید نوکلئیک اسید تک‌رشته‌ای در هستهٔ یک نورون رابط، …»', 3, 4, 29, 153, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 15:59:52', 2, 'free'),
(12270, '145- با توجه به روش‌های تنظیم بیان ژن در گیاهی فتوسنتزکننده، کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«در تنظیم بیان ژن … مرحلهٔ رونویسی، … قابل مشاهده است.»', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:00:12', 2, 'free'),
(12271, '146- در خصوص رناتن‌های تولیدکنندهٔ پروتئین ترشحی در جانداران، کدام مورد درست است؟', 3, 4, 29, 161, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:00:47', 2, 'free'),
(12272, '147- با توجه به مطالب کتاب درسی، در خصوص رنای پیک در یوکاریوت‌ها، کدام مورد نادرست است؟', 3, 4, 29, 154, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:02:18', 2, 'free'),
(12273, '148- در بخشی از فرایند ترجمهٔ یک رنای پیک، دو رنای ناقل متصل به آمینواسید یا زنجیرهٔ آمینواسیدی به‌طور همزمان در جایگاه‌های رناتن (ریبوزوم) مستقر هستند. کدام عبارت، دربارهٔ این بخش از فرایند قطعاً درست است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:02:54', 2, 'free'),
(12274, '149- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«دربارهٔ دو ژن در یک دنای خطی که … می‌توان گفت که به‌طور حتم …»', 3, 4, 29, 153, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:05:14', 2, 'free'),
(12275, '150- کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در هر مرحله‌ای از رونویسی که پیوند بین رشتهٔ دنا با رشتهٔ … می‌شود، …»', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:05:36', 2, 'free'),
(12276, '151- در کدام گزینه، آنزیم سازندهٔ هر دو مادهٔ ذکر شده، می‌تواند دارای توالی آمینواسیدی مشابهی باشد؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:07:20', 2, 'free'),
(12277, '152-در نوعی نوکلئیک‌اسید پارامسی، یک توالی سیتوزین‌دار وجود دارد که مربوط به آمینواسید متیونین است. کدام موارد، در خصوص این توالی، به‌طور حتم صحیح است؟\n\nالف: دارای باز آلی آدنین و قند ریبوز است.\n\nب: توالی مکمل آن در دنا (DNA) وجود دارد.\n\nج: با هر دو انتهای رشته پلی‌نوکلئوتیدی فاصله دارد.\n\nد: توسط رنابسپاراز (RNAپلی‌مراز) سه ساخته شده است.', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:07:57', 2, 'free'),
(12278, '153-اگر زمانی که دنا (DNA) به یک رشته رنا (RNA) متصل است، رناتن (ریبوزوم)ها نیز به این رنا متصل باشد، کدام مورد زیر درست می‌باشد؟', 3, 4, 29, 153, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:08:23', 2, 'free'),
(12279, '154-اگر یک رنای پیک درون سیتوپلاسم را با رشته الگوی ژن آن در دنا مجاورت دهیم، کدام مورد به‌طور حتم درست است؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:11:59', 2, 'free'),
(12280, '155-پروتئین‌های وارد شده به دستگاه گلژی، ممکن است به بخش‌هایی مثل واکوئول یا لیزوزوم بروند. پروتئین‌های وارد شده به این دو اندامک، به‌ترتیب، از نظر کدام ویژگی قطعاً مشابه و از نظر کدام ویژگی قطعاً متفاوت هستند؟', 3, 4, 29, 157, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:13:08', 2, 'free'),
(12281, '156-در کدام گزینه، هر دو مورد ذکر شده در ارتباط با یک یاخته جانوری، با یکدیگر برابر هستند؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:13:47', 2, 'free'),
(12282, '157-مطابق با مطالب کتاب‌درسی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به‌طور معمول، نوعی مولکول تک‌رشته‌ای حامل اطلاعات وراثتی که ....................... به‌طور حتم .......................»', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:15:17', 2, 'free'),
(12283, '158-در خصوص پروتئین‌سازی در نوعی یاخته یوکاریوتی، کدام مورد درست است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:15:41', 2, 'free'),
(12284, '159-در خصوص جایگاه تولید پروتئین در یاخته‌های انسانی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«نوعی پروتئین که ....................... ممکن نیست توسط رناتن‌های ....................... یاخته‌های ....................... تولید شود.»', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:16:19', 2, 'free'),
(12285, '160-مطابق اطلاعات کتاب‌درسی، در باکتری اشرشیاکلای، تنظیم بیان ژن در سطح رونویسی به دو شکل مثبت و منفی انجام می‌شود. کدام یک از اتفاقات زیر، فقط در یک نوع از این تنظیم بیان ژن مشاهده می‌شود؟', 3, 4, 29, 159, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:17:32', 2, 'free'),
(12286, '161-باتوجه‌به شکل زیر که فرایند ترجمه را در نورون رابط نخاع نشان می‌دهد، کدام مورد، به‌طور حتم، درست است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:19:01', 2, 'free'),
(12287, '162-کدام عبارت، در ارتباط با فرایندهای ویرایش و پیرایش درست است؟', 3, 4, 29, 154, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:19:32', 2, 'free'),
(12288, '163-در خصوص پروتئین‌سازی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«هر زمانی که ....................... بلافاصله ....................... می‌شود.»', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:20:34', 2, 'free'),
(12289, '164-مطابق با اطلاعات کتاب درسی، مرحله‌ای از رونویسی ژن رنای پیک که حباب رونویسی از بین می‌رود، برخلاف مرحله‌ای از ترجمه یک رنای پیک که پیوند بین دو نوع رنا در جایگاه P رناتن شکسته می‌شود، چه مشخصه‌ای دارد؟', 3, 4, 29, 153, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:21:18', 2, 'free'),
(12290, '165-درباره همه رمزه‌های موجود در گروهی از ریبونوکلئیک‌اسیدها که هیچ آمینواسیدی را رمز نمی‌کنند، کدام مورد صدق می‌کند؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:21:58', 2, 'free'),
(12291, '166-در خصوص یکی از مراحل فرایند رونویسی از نوعی ژن در استرپتوکوکوس نومونیا که به دفعات زیاد امکان جداشدن دو رشته دنا از یکدیگر و اتصال مجدد آن‌ها به‌هم وجود دارد، کدام مورد درست است؟', 3, 4, 29, 159, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:23:13', 2, 'free'),
(12292, '167-فرض می‌کنیم در قطعه‌ای از مولکول دنای اشرشیاکلای، دو ژن با یک راه‌انداز مشترک و ژن دیگری با یک راه‌انداز اختصاصی، با فاصله‌ای در پشت سر هم قرار دارند. در صورتی که رنابسپارازهای مستقر بر روی هر یک از این دو راه‌انداز به سوی یکدیگر حرکت کنند، کدام مورد درست است؟ (محصول ژن‌های مورد نظر رنا و پلی‌پپتید است.)', 3, 4, 29, 160, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:23:43', 2, 'free'),
(12293, '168-کدام مورد را نمی‌توان درباره پروتئینی با ساختار نهایی سوم که در ماده زمینه‌ای سیتوپلاسم یاخته سازنده خود فعالیت می‌کند، با قاطعیت بیان داشت؟', 3, 4, 29, 157, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:30:01', 2, 'free'),
(12294, '169-کدام عبارت را نمی‌توان درباره دو توالی از رنای ناقل که در اتصال به آمینواسید یا تعیین نوع آمینواسید متصل‌شونده به مولکول رنا نقش دارند، بیان نمود؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:30:24', 2, 'free'),
(12295, '170-کدام مورد، در ارتباط با موجوداتی که می‌توانند سرعت و مقدار پروتئین‌سازی را بسته به نیاز تنظیم کنند، درست است؟', 3, 4, 29, 159, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:31:01', 2, 'free'),
(12296, '171-با توجه به شکل زیر که ساخته‌شدن هم‌زمان چندین رنای پیک از روی دو ژن مجاور را نشان می‌دهد، کدام مورد، قطعی نیست؟', 3, 4, 29, 155, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:32:09', 2, 'free'),
(12297, '172-در خصوص فرایند ترجمه رنای پیک در یاخته میانبرگ لوبیا، کدام مورد زیر، به‌طور حتم صحیح است؟', 3, 4, 29, 156, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:33:32', 2, 'free'),
(12298, '173-کدام ویژگی، تنظیم مثبت رونویسی را از تنظیم منفی در باکتری E.Coli، متمایز می‌سازد؟', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:33:58', 2, 'free'),
(12299, '174-در انسان، به‌منظور تولید نوعی پروتئین ترشحی در یاخته‌های درون‌ریز کبد، پس از شکسته شدن ششمین پیوند اشتراکی در فرایند ترجمه، کدام اتفاق زودتر از سایرین رخ می‌دهد؟', 3, 4, 29, 157, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:34:20', 2, 'free'),
(12300, '175-باکتری اشرشیا کلای برای تجزیهٔ قند لاکتوز به محصولات سه ژن نیاز دارد. کدام مورد، مشخصهٔ مشترک این ژن‌ها را بیان می‌کند؟', 3, 4, 29, 159, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:34:47', 2, 'free'),
(12301, '176-چند مورد، دربارهٔ تنظیم بیان ژن در یک یاختهٔ زنده و فعال نادرست است؟\n\nالف: همهٔ عوامل مؤثر بر تنظیم بیان ژن، اتم کربن دارند.\n\nب: همهٔ مولکول‌های تنظیم‌کنندهٔ بیان ژن، پیوند پپتیدی دارند.\n\nج: همهٔ روش‌های تنظیم بیان ژن، بر مقدار پروتئین‌سازی مؤثر هستند.\n\nد: همهٔ مراحل تنظیم بیان ژن، فقط در تنظیم مقدار استفاده از ژن نقش دارند.', 3, 4, 29, 161, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:36:07', 2, 'free'),
(12302, '177-کدام موارد، برای تکمیل عبارت زیر مناسب هستند؟\n\n«پس از اثر هورمون گاسترین بر یاخته‌های اصلی غدد معده، ..........................»\n\nالف: تعداد هسته‌تن (نوکلئوزوم)ها در مجاورت ژن پپسینوژن، کاهش می‌یابد.\n\nب: ماده‌ای با عبور از منافذ پوشش هسته، بر ژن سازندهٔ پپسینوژن اثر می‌گذارد.\n\nج: رنای ساخته‌شده از ژن پپسینوژن، می‌تواند به رناهای دارای توالی مکمل متصل شود.\n\nد: تمایل عوامل رونویسی برای پیوستن به راه‌انداز مربوط به ژن پپسینوژن بیشتر می‌شود.', 3, 4, 29, 160, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:37:06', 2, 'free'),
(12303, '178-برای تجزیهٔ دی‌ساکاریدها در باکتری اشرشیا کلای، فعال‌شدن گروهی از ژن‌ها ضروری است. کدام مورد، دربارهٔ روش‌های تنظیم رونویسی این ژن‌ها درست است؟', 3, 4, 29, 159, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:37:31', 2, 'free'),
(12304, '179-باتوجه‌به فرایندهای تنظیم بیان ژن که در کتاب‌درسی آمده است، چند مورد زیر درست است؟\n\nالف: در نوعی تنظیم، در پی اتصال انواع مختلفی از مولکول‌های پروتئینی به توالی‌های نوکلئوتیدی، فرایند رونویسی تسریع می‌شود.\n\nب: در نوعی تنظیم، به دنبال اتصال پروتئینی تنظیمی به‌نوعی قند، تمایل پروتئین به مولکولی پلی‌نوکلئوتیدی دچار کاهش می‌شود.\n\nج: در نوعی تنظیم، با اتصال رناهای کوچک به دنا، عمل رونویسی متوقف شده و به دنبال آن، فرایند پروتئین‌سازی نیز مختل می‌شود.\n\nد: در نوعی تنظیم، در پی پیوستن پروتئین به توالی نوکلئوتیدی، پیوستن پروتئین به پروتئین و سپس قند به پروتئین ممکن می‌شود.', 3, 4, 29, 161, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:38:09', 2, 'free'),
(12305, '180-کدام عبارت، در خصوص همهٔ جاندارانی که پیکر متشکل از تنها یک یاخته دارند صحیح است؟', 3, 4, 29, 161, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:38:40', 2, 'free'),
(12306, '181-دربارهٔ همهٔ عوامل رونویسی متصل به راه‌انداز در جریان تنظیم بیان ژن یوکاریوت‌ها در مرحلهٔ رونویسی، کدام مورد صدق می‌کند؟', 3, 4, 29, 153, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:39:00', 2, 'free'),
(12307, '182-در یاخته‌هایی که به وسیلهٔ غشاها به بخش‌های مختلفی تقسیم شده‌اند، کدام عبارت دربارهٔ سازوکارهایی که سبب می‌شوند تنظیم بیان ژن در مراحل غیررونویسی تداوم یابد، نادرست است؟', 3, 4, 29, 153, NULL, NULL, NULL, 'سخت', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, '2026-09-18 16:39:42', 2, 'free'),
(12308, '183-در خصوص یاخته‌هایی که دارای بیش از یک جایگاه آغاز همانندسازی هستند، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«فقط در یاخته‌هایی که ...................»', 3, 4, 29, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:22:11', 1, NULL, NULL, 'free'),
