(12461, 'در مورد اثرات پرتو فرابنفش بر روی مادهٔ وراثتی یاخته، با توجه به مطالب کتاب درسی کدام گزینه به‌درستی بیان شده است؟', 3, 4, 31, 123, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
