(12465, 'شواهدی وجود دارند که نشان می‌دهند، گونه‌ها در طول زمان تغییر کرده‌اند و یکی از این شواهد، سنگواره‌ها هستند. کدام مورد، جزو اطلاعات به‌دست آمده از سنگواره‌های کشف شده، نیست؟', 3, 4, 31, 127, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12466, '76-چند مورد به‌درستی بیان شده است؟\n\nالف) هر جهش مضاعف‌شدگی قطعاً با کاریوتیپ قابل تشخیص است.\n\nب) در هر جهش جابه‌جایی، ناهنجاری قطعاً در دو فام‌تن ایجاد می‌شود.\n\nج) هر جهش بزرگ از نوع حذف قطعاً سبب تغییر در تعداد فام‌تن‌های همتا می‌شود.\n\nد) در هر جهش بزرگی که منجر به ناهنجاری‌های ساختاری فام‌تن شود، قطعاً پیوند فسفودی‌استر شکسته می‌شود.', 3, 4, 31, 121, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12467, '77-با توجه به جهش‌های کروموزومی، چند مورد عبارت زیر را به طور درست کامل می‌کند؟\n\n«به طور معمول، نوعی ناهنجاری ساختاری که .................. ، می‌تواند .................. .»\n\nالف) با شکسته شدن و تشکیل پیوند اشتراکی در کروموزوم‌های همتا همراه است - مخلوطی از دو جهش مختلف محسوب گردد.\n\nب) تنوع ژنی یک کروموزوم را کاهش می‌دهد - شکسته شدن پیوند اشتراکی در بیش از یک کروموزوم را سبب شود.\n\nج) تنها یک کروموزوم را درگیر می‌کند - بدون تغییر محل سانترومر در شکسته شدن پیوندهای اشتراکی مؤثر باشد.\n\nد) تنوع ژنی در دو کروموزوم را تغییر می‌دهد - با تشکیل پیوند اشتراکی در دو کروموزوم همراه باشد.', 3, 4, 31, 121, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12468, 'کدام گزینه وجه مشترک همهٔ تغییرات ماندگاری که در محتوای دنای نوعی یاختهٔ تقسیم‌پذیر صورت می‌گیرند، محسوب می‌شود؟', 3, 4, 31, 122, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12469, 'کدام گزینه در ارتباط با عوامل بر هم زنندهٔ تعادل خزانهٔ ژنی جمعیت، صادق است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12470, 'کدام مورد، ویژگی درستی از نخستین گونه‌زایی مطرح‌شده در کتاب درسی را بیان می‌کند؟', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12471, '81-چند مورد از نظر درستی یا نادرستی، با عبارت زیر در تضاد است؟\n\n«تحت شرایطی ممکن است فعالیت عوامل رونویسی، در فراوان‌ترین یاخته‌های خونی انسان مشاهده شود.»\n\nالف) تنها تعریف گونه در علم زیست‌شناسی، توسط ارنست مایر مطرح شده است.\n\nب) خزانهٔ ژنی تنها شامل همهٔ دگره‌های بارز موجود در جایگاه‌های ژنی افراد می‌باشد.\n\nج) در نتیجهٔ انتخاب شدن افراد سازگارتر، توانایی بقای جمعیت در محیط جدید ممکن است کاهش یابد.\n\nد) ثابت ماندن مجموع تعداد دگره‌ها از نسلی به نسل دیگر، بیانگر جمعیت در حال تعادل ژنی می‌باشد.', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12472, 'چند مورد از گزینه‌های زیر همواره معرّف نوعی یا انواعی از جهش جانشینی محسوب می‌شود؟\n\nالف) هر جهشی که باعث تغییر ترتیب و توالی آمینواسیدها در نوعی پروتئین می‌گردد.\n\nب) هر جهشی که با ثابت ماندن چارچوب خواندن رمزهای DNA همراه است.\n\nج) هر جهشی که علی‌رغم تغییر نوکلئوتیدهایی در دنا، باعث ثابت ماندن تعداد نوکلئوتیدهای رنای اولیه می‌شود.\n\nد) هر جهشی که نوعی کدون پایان ایجاد می‌کند.', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12473, '83-کدام گزینه عبارت زیر را به طور مناسب کامل می‌نماید؟\n\n«در نوعی عامل ذکرشده در کتاب درسی که باعث تداوم گوناگونی در جمعیت می‌شود .................. »', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12474, 'چند مورد، ممکن است نشان‌دهندهٔ پیامدهای جهش ایجاد شده در بخشی از دنا باشد؟\n\nالف: حفظ فعالیت آنزیم با وجود تغییر در جایگاه اختصاصی آن\n\nب: افزایش طول زنجیره‌های پلی‌پپتیدی شرکت‌کننده در میوگلوبین\n\nج: افزایش فعالیت آنزیم کاهندهٔ انرژی آزادشده از فرایند سه مرحله‌ای رونویسی\n\nد: عملکرد طبیعی پروتئین حاصل از ژن علی‌رغم تغییر نوکلئوتیدهای بخشی از ساختار رنا', 3, 4, 31, 123, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12475, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«فقط برخی از عوامل برهم زننده تعادل جمعیت که .................. ، قطعاً .................. »', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12476, '86-در خصوص کراسینگ‌اور و تأثیرات آن بر کروموزوم‌ها در جانداران دیپلوئید، چند مورد به عبارت داده شده را به درستی تکمیل می‌کند؟«به طور معمول، پیامد بروز کراسینگ اور .................. می‌تواند .................. باشد.»\n\nالف) همانند وقوع جهش بین دو کروموزوم غیرهمتا - تغییر در محل سانترومر کروموزوم(ها)\n\nب) برخلاف وقوع جهش بین دو کروموزوم همتا - افزایش گوناگونی و تنوع در جمعیت(ها)\n\nج) برخلاف آرایش متافازی تترادها - افزایش توان بقای جمعیت(ها) در برابر تغییر شرایط محیطی\n\nد) همانند وقوع جهش کوچک از نوع جانشینی - شکسته شدن پیوندهای فسفودی استر در دنا', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12477, 'چند مورد، عبارت زیر را به طور نادرست کامل می‌نماید؟\n\n«در ارتباط با نوعی گونه‌زایی که برای وقوع، به جدایی جغرافیایی نیازمند .................. با قاطعیت می‌توان بیان داشت که .................. »\n\nالف) نیست - به وجود آمدن گامت‌های متفاوت با گامت‌های طبیعی والدین ضروری است.\n\nب) نیست - جهش منجر به جدایی تولیدمثلی ناگهانی بین جمعیت‌ها در طی چند نسل می‌شود.\n\nج) است - تنها عواملی به جداشدن دو گونه از هم کمک می‌کنند که در برهم زدن تعادل خزانهٔ ژنی مؤثرند.\n\nد) است - در نتیجهٔ ایجاد جدایی تولیدمثلی، لقاح بین گامت‌های گونهٔ جدید و گونه(های) اولیه غیرممکن می‌شود.', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12478, 'مطابق با متن کتاب درسی در فصل «۴» سال دوازدهم، کدام گزینه عبارت زیر را به طور درست تکمیل می‌کند؟\n\n«نوعی عامل خارج‌کنندهٔ جمعیت از حال تعادل که در بسیاری از موارد تأثیر فوری بر رخ‌نمود نداشته و ممکن است تشخیص داده نشود .................. عاملی که در حوادثی نظیر زلزله رخ می‌دهد، .................. »', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12479, '89-کدام عبارت درست است؟\n\n«افرادی که .................. »', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12480, 'کدام گزینه برای تکمیل عبارت زیر مناسب است؟\n\n«در روند گونه‌زایی .................. به‌طورحتم .................. »', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12481, 'در ارتباط با کم‌خونی داسی‌شکل، بعضی افراد هستند که می‌توانند دو نوع فنوتیپ را بروز دهند. کدام گزینه در ارتباط با این افراد صحیح است؟', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12482, 'چند مورد نادرست است؟\n\nالف) آمیزش غیرتصادفی همانند انتخاب طبیعی، قطعاً وابسته به بیان ژن‌ها بوده و منجر به سازگاری با محیط می‌شود.\n\nب) جهش ژنی برخلاف انتخاب طبیعی، همواره به صورت غیرمنتظره و سریع باعث تغییر افراد و تغییر فراوانی دگره‌ها می‌شود.\n\nج) شارش ژنی همانند رانش دگره‌ای، لزوماً بر دو جمعیت با اندازه‌های متفاوت اثرگذاشته و فراوانی نسبی دگره‌های آن‌ها را تغییر می‌دهد.\n\nد) شارش ژنی برخلاف انتخاب طبیعی، تفاوت‌های فردی جمعیت مقصد را افزایش داده و در کاهش بقای جمعیت در برابر تغییر شرایط مؤثرند.', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12483, '93-کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، در نوعی تغییر پایدار در مادهٔ وراثتی که .................. می‌شود، به طور حتم چارچوب خواندن دنا تغییر می‌کند.»', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12484, '94-کدام مورد همراه با اتفاق‌افتادن یک جهش، محتمل نیست؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12485, '95-با توجه به مطالب کتاب‌درسی، در خصوص نوعی جهش که در اثر پرتوهای UV (فرابنفش) ممکن است در رشتهٔ الگوی نوعی ژن در یاختهٔ عصبی انسان رخ دهد، چند مورد نادرست است؟\n\nالف: موجب تغییر در وضعیت قرارگیری ستون و پله‌های نردبان دو رشته‌ای دنا می‌شود.\n\nب: موجب برقراری دو پیوند اشتراکی میان دو ضلع غیریگسان از دو باز شش‌ضلعی می‌شود.\n\nج: موجب اختلال در عملکرد آنزیم‌های مؤثر در انجام فرایند همانندسازی و رونویسی می‌شود.\n\nد: موجب کاهش پایداری در بخشی از ساختار مارپیچی و دو رشته‌ای مادهٔ وراثتی در هسته می‌شود.', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12486, '96-کدام عبارت، به طور حتم درست است؟', 3, 4, 31, 124, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12487, 'کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، در هر نوع گونه‌زایی که ..................، به طور حتم .................. »', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12488, 'در خصوص گونه‌زایی، کدام مورد نادرست است؟', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12489, '99-کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«در پی بررسی انواعی از خطاهای میوزی که در یک یاختهٔ اسپرماتوسیت اولیه در بدن مرد بالغ به وقوع می‌پیوندد، می‌توان بیان کرد: با فرض اینکه جدانشدن کروموزوم‌ها در میوز ۱ صورت بگیرد، .................. زمانی که جدانشدن کروموزوم‌ها در میوز ۲ به انجام برسد، .................. تولید می‌شود.»', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12490, 'باتوجه‌به شکل زیر، کدام مورد نادرست است؟', 3, 4, 31, 124, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12491, 'در خصوص پیامدهای جهش، کدام مورد به‌طورقطع درست است؟', 3, 4, 31, 123, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12492, '102-کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«در خصوص سازوکاری که باعث تداوم گونه‌زایی در جمعیت می‌شود و .................. می‌شود، می‌توان بیان داشت که ..................»', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12493, 'نوعی عامل برهم‌زنندهٔ تعادل در جمعیت، می‌تواند با تغییر در افراد و افزایش یا کاهش تفاوت‌های بین آن‌ها، در نحوهٔ بروز انتخاب طبیعی مؤثر باشد. در خصوص این عامل، کدام مورد درست است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12494, 'کدام عبارت، درست است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12495, 'شکل زیر یکی از عوامل برهم‌زنندة تعادل نشان می‌دهد. در خصوص این عامل، کدام مورد درست است؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12496, '106-مطابق با مطالب کتاب‌درسی، کدام مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«جهشی که منجر به .................. می‌شود، از نظر .................. به پدیده‌ای شباهت دارد که ..................»', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12497, 'در خصوص جهش‌هایی که یک یا چند نوکلئوتید را در بر می‌گیرند، کدام مورد نادرست است؟', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12498, 'درخصوص جهش‌هایی که یک یا چند نوکلئوتید را در برمی‌گیرند، کدام مورد درست است؟', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12499, 'بروز یک جهش کوچک در ژن مربوط به یکی از آنزیم‌های راکیزه (میتوکندری)، با تغییر یکی از آمینواسیدهای پروتئین به آمینواسید والین، باعث شده است که راکیزه در مبارزه با رادیکال‌های آزاد، عملکرد مناسبی نداشته باشد. مطابق مطالب کتاب درسی، کدام عبارت، درباره این جهش درست است؟', 3, 4, 31, 120, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12500, 'با توجه به مطالب کتاب درسی دربارهٔ گروهی از ناهنجاری‌های فام‌تنی (کروموزومی) که منجر به تغییر در ساختار فام‌تن‌های طبیعی یک یاختهٔ پیکری بدن مردی بالغ می‌شوند، کدام گزینه، عبارت زیر را به‌درستی کامل می‌کند؟\n\n«در صورتی که جهش .................. شده باشد، دربارهٔ فام‌تن تغییریافته می‌توان گفت که .................. .»', 3, 4, 31, 122, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12501, 'گروهی از جانداران که بر اساس تعریف ارنست مایر متعلق به یک گونه هستند، در تشکیل یک خزانهٔ ژنی شرکت دارند که تغییر در آن مورد انتظار نیست. کدام عبارت، دربارهٔ این جمعیت درست است؟', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12502, 'کدام مورد، مشخصه مشترک همۀ سازوکارهایی است که باعث می‌شوند با وجود انتخاب طبیعی، گوناگونی تداوم داشته باشد اما روی تعادل جمعیت تأثیری ندارند؟', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12503, 'با توجه به مطالب کتاب درسی درباره سازوکارهای گونه‌زایی، نوعی گونه‌زایی که طی چند نسل و به‌صورت تدریجی رخ می‌دهد، برخلاف نوع دیگر گونه‌زایی، به‌طور حتم، چه مشخصه‌ای دارد؟', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12504, 'کدام مورد، برای تکمیل عبارت زیر نامناسب است؟\n\n«در انسان، هر جهش در ساختار فام‌تن (کروموزوم) که ....................... ، به‌طور حتم ....................... .»', 3, 4, 31, 121, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12505, 'هر سازوکاری که وجود آن در یک جمعیت باعث می‌شود تا توانایی بقای جمعیت در شرایط محیطی جدید بالا رود، کدام مشخصهٔ زیر را دارد؟', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12506, 'کدام گزینه، جملهٔ زیر را به‌درستی کامل می‌کند؟\n\n«همۀ ساختارهایی که ....................... برای پاسخ به یک نیاز معین، قطعاً به روش‌های ....................... سازش پیدا کرده‌اند.»', 3, 4, 31, 127, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12507, 'کدام گزینه، با توجه به مطالب کتاب درسی و در خصوص فام‌تن‌هایی مضاعف نشده، برای تکمیل عبارت زیر مناسب است؟\n\n«در یک یاخته پوششی امکان .................. در ناهنجاری ساختاری به غیر از .................. وجود ندارد.»', 3, 4, 31, 121, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12508, 'کدام گزینه، در خصوص دیرینه‌شناسان نادرست است؟', 3, 4, 31, 127, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12509, '119-کدام گزینه، برای تکمیل جملۀ زیر مناسب است؟\n\n«اگر شکل زیر توالی رشتهٔ الگو دنای هموگلوبین و بخش‌های مشخص شده مربوط به رمز ششمین آمینواسید در فردی بالغ باشد در صورتی که به جای علامت سؤال .................. قرار بگیرد، به طور حتم،.................. »', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12510, 'کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟ (مقدار اکسیژن همهٔ مناطق را یکسان در نظر بگیرید.)\n\n«به دنبال مهاجرت فردی .................. شانس بقای وی در جمعیت .................. می‌یابد.»', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12511, '121-کدام عبارت درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12512, 'در چند جمعیت زیر قطعاً زاده‌ها، حاصل آمیزش غیرتصادفی می‌باشند؟\n\nالف: جانورانی که از فرومون برای جفت‌یابی استفاده می‌کنند.\n\nب: زنبورهای عسلی که در یک کندو با یکدیگر زندگی می‌کنند.\n\nج: در جانورانی که هر فرد می‌تواند تخمک‌های خود را بارور کند.\n\nد: در گیاهانی دوجنسی که تنها طی خودلقاحی آمیزش انجام می‌دهند.', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12513, 'کدام دو مورد، در رابطه با جهشی که در اثر UV یا پرتوی فرا بنفش در یاخته‌های پوست انسان رخ می‌دهد، صحیح است؟\n\nالف: دو باز آلی درگیر در جهش، از طریق دو پیوند به هم متصل می‌شوند.\n\nب: در فعالیت یک نوع آنزیم لازم برای ساخت دنای جدید اختلال ایجاد می‌کند.\n\nج: سبب برقراری پیوند اشتراکی بین دو نوع باز آلی مختلف در دو رشتهٔ دنا می‌شود.\n\nد: نوعی جهش کوچک محسوب می‌شود که با شکسته شدن پیوند فسفودی‌استر همراه است.', 3, 4, 31, 123, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12514, 'کدام گزینه، برای تکمیل عبارت مقابل مناسب است؟ «یکی از عوامل .................. است.»', 3, 4, 31, 123, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12515, 'در نوعی گونه‌زایی که تشکیل گونهٔ جدید در .................. نسل به وقوع می‌پیوندند، ..................', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12516, 'گیاهان چندلادی ممکن است به دنبال خطا در تقسیم .................. کاستمان شکل بگیرند و گل مغربی $4n$ به دلیل اینکه .................. گونهٔ جدیدی محسوب می‌شود.', 3, 4, 31, 128, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12517, 'در صورت آمیزش فردی با ژن‌نمود $\\frac{AbCd}{aBCd}$ با فردی با ژن‌نمود $\\frac{abCd}{aBCd}$ ایجاد کدام یک از زاده‌ها غیرممکن است؟ (با فرض امکان وقوع کراسینگ اور بین ژن‌های A یا B)\n\nالف: AabbCcDD\n\nب: AabbCCDD\n\nج: AaBBCCDd\n\nد: AabbCcDd', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12518, 'در خصوص عوامل برهم‌زنندهٔ تعادل جمعیت‌ها، کدام گزینه عبارت زیر را به نادرستی تکمیل می‌کند؟\n\n«اگر در جمعیتی تعداد افرادی که بر اثر وقایع طبیعی می‌میرند .................. از افرادی باشد که زنده می‌مانند ممکن است ..................»', 3, 4, 31, 125, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12519, '129-مطابق اطلاعات کتاب درسی، گروهی از جهش‌های متأثر از عوامل جهش‌زا در یاخته‌های پوششی پوست، تغییری در تعداد نوکلئوتیدهای محتوای وراثتی هسته‌ای ایجاد نمی‌کنند. کدام گزینه، در خصوص این جهش‌ها درست است؟', 3, 4, 31, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12520, 'در خصوص پدیدهٔ چلیپایی‌شدن (کراسینگ‌اور)، کدام گزینه همواره درست است؟', 3, 4, 31, 126, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:45', 1, NULL, NULL, 'free'),
(12521, '1-درخصوص ترتیب وقایع تنفس یاخته‌ای، چند مورد از موارد زیر درست است؟\n\nالف: در فرایند اکسایش پیرووات، آزاد شدن $CO_2$ قبل از آزاد شدن $NADH$ رخ می‌دهد.\n\nب: طی چرخه کربس، تولید هر مولکول چهار کربنی بلافاصله پس از آزادشدن $CO_2$ رخ می‌دهد.\n\nج: طی چرخه کربس، آزاد شدن کوآنزیم $A$ و تولید مولکول شش‌کربنی به‌طور همزمان رخ می‌دهند.\n\nد: طی قندکافت، اضافه‌شدن فسفات به قند فسفاته قبل از اضافه‌شدن $NAD^+$ به مسیر واکنش رخ می‌دهد.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12522, '2-کدام عبارت با توجه به مطالب کتاب درسی در ارتباط با تنفس یاخته‌ای درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12523, '3-مطابق با متن کتاب درسی و واکنش کلی تنفس یاخته‌ای، انرژی ذخیره‌شده در گلوکز برای تشکیل نوعی مولکول به‌کار می‌رود. کدام مورد در این مولکول درست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12524, '4-درخصوص فرایند تجزیهٔ گلوکز در مادهٔ زمینه‌ای سیتوپلاسم نوتروفیل، کدام مورد صادق است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12525, '5-فرایندی که تحت عنوان چرخهٔ کربس در یاخته‌های بدن انسانی سالم انجام می‌شود، چه مشخصه‌ای دارد؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free');
INSERT INTO `questions_tam24` (`id`, `question_text`, `grade_id`, `subject_id`, `topic_id`, `chapter_id`, `major_id`, `academic_year`, `chapter`, `difficulty_level`, `source`, `book`, `status`, `insert_type`, `created_at`, `admin_id`, `last_edit_date`, `last_edit_by`, `edit_status`) VALUES
(12526, '6-کدام موارد، در خصوص یاختهٔ نشان داده شده در شکل درست هستند؟\n\nالف: غشای داخلی در اندامک «؟»، به سمت خارج چین خورده است.\n\nب: همهٔ غشاهای متعلق به اندامک‌هایی از نوع «؟»، حاوی پروتئین هستند.\n\nج: همهٔ روش‌های مطرح‌شده در کتاب درسی برای تولید $ATP$، در این یاخته انجام می‌شوند.\n\nد: همهٔ مراحل نیازمند به اکسیژن در تنفس یاخته‌ای، درون اندامک‌هایی از نوع «؟» انجام می‌شوند.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12527, '7-چند مورد در ارتباط با هر مولکول موجود در مسیر تنفس یاخته‌ای در انسانی سالم که به تعداد نوکلئوتیدهای $NADH$ اتم کربن دارد، درست است؟\n\nالف: فقط درون اندامکی دارای دو غشا تولید می‌شود.\n\nب: تولید آن با آزاد شدن کربن‌دی‌اکسید همراه است.\n\nج: تولید آن در چرخه‌ای از واکنش‌های آنزیمی انجام می‌شود.\n\nد: با کمک مولکول‌های آلی، می‌تواند با مولکولی چهار کربنی ترکیب شود.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12528, 'با توجه به فرایندهای انجام‌شده در تنفس یاخته‌ای هوازی، کدام موارد وجه تمایز میان راکیزه و مادهٔ زمینه‌ای سیتوپلاسم محسوب می‌شوند؟\n\nالف: مولکولی دو فسفاته به مصرف می‌رسد.\n\nب: مولکولی سه‌کربنی و فاقد فسفات تولید می‌شود.\n\nج: الکترون به ماده‌ای غیرنوکلئوتیدی متصل می‌شود.\n\nد: ممکن است از نوعی کوآنزیم برای انجام واکنش استفاده شود.', 3, 4, 32, 131, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12529, '9-مطابق با مطالب مطرح شده در کتاب درسی در ارتباط با فرایندهایی از تنفس یاخته‌ای هوازی که بیش از دو مرحله دارند، کدام مورد به تمایز نوع غیرچرخه‌ای آن از نوع دیگر کمک می‌کند؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12530, '10-در ارتباط با تخمیرهای الکلی و لاکتیکی، کدام مورد، تخمیری که باعث ورآمدن خمیر نان می‌شود را از تخمیر دیگر متمایز می‌کند؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12531, '11-درخصوص دو نوع فرایند تخمیر که انسان در صنایع متفاوت از آن‌ها بهره می‌برد، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«در نوعی تخمیر که .................... برخلاف نوع دیگر، ....................»', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12532, '12-فضایی از راکیزه که از نظر داشتن یا نداشتن مولکول دنا ($DNA$)، مشابه با بخش مشخص شده در شکل زیر است، چند مورد از ویژگی‌های زیر را دارد؟\n\nالف: چرخه‌ای از واکنش‌های آنزیمی در آن انجام می‌شود.\n\nب: محل مصرف یون‌های اکسید و تولید مولکول‌های آب است.\n\nج: بخش مصرف‌کنندهٔ $ADP$ در آنزیم $ATP$ساز را نگهداری می‌کند.\n\nد: ورود $H^+$ از دیگر فضای راکیزه به آن، برخلاف شیب غلظت رخ می‌دهد.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12533, '13-چند مورد درخصوص همهٔ مولکول‌های سه‌کربنی قابل مشاهده در طی تولید انرژی در یاخته‌های ماهیچهٔ اسکلتی، صحیح است؟\n\nالف: پس از تشکیل، از طریق انتقال فعال به میتوکندری وارد می‌شوند.\n\nب: در نتیجهٔ تبادل الکترون با حاملین آن تشکیل شده‌اند.\n\nج: در مادهٔ زمینه‌ای سیتوپلاسم قابل مشاهده هستند.\n\nد: دارای ماهیت شیمیایی مشابهی هستند.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12534, '14-منشأ الکترون‌های انتقال یافته توسط گروهی از اجزای زنجیرهٔ انتقال الکترون در غشای درونی راکیزه (میتوکندری)، دو نوع ترکیب نوکلئوتیدی متفاوت می‌باشد. چند مورد دربارهٔ این اجزا درست است؟\n\nالف: یکی از آن‌ها بین دو پروتئین سراسری غشا قرار گرفته است.\n\nب: یکی از آن‌ها الکترون‌ها را از دو مولکول متفاوت دریافت می‌کند.\n\nج: همهٔ آن‌ها با بخش فسفات‌دار لیپیدهای غشایی در تماس هستند.\n\nد: نیمی از آن‌ها می‌توانند پروتون‌ها را در خلاف جهت شیب غلظت جابه‌جا کنند.', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12535, '15-کدام عبارت، دربارهٔ اولین مرحلهٔ تنفس یاخته‌ای نادرست است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12536, '16-در بررسی تخمیر الکلی و تخمیر لاکتیکی، تعداد خصوصیات منحصر به‌فرد برای تخمیر لاکتیکی، در کدام مورد بیشتر از سایر موارد است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12537, '17-درخصوص ساختار زنجیرهٔ انتقال الکترون در یک یاختهٔ ماهیچهٔ صاف، کدام عبارت صحیح است؟', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
(12538, '18-مطابق نمودار مطرح‌شده در کتاب درسی، کدام مورد برای تکمیل عبارت زیر مناسب است؟\n\n«از بین رنگیزه‌های سبزینهٔ $a$، سبزینهٔ $b$ و کاروتنوئیدها، رنگیزه‌ای که در طول موج .................... نانومتر مقدار جذب بیشتری دارد، ....................»', 3, 4, 32, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:24:57', 1, NULL, NULL, 'free'),
