(12731, '87- در خصوص همهٔ اندامک‌هایی که در یک یاخته میانبرگ گیاه کدو مشاهده می‌شوند و چندین کیسهٔ غشایی دارند، کدام مورد درست است؟', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12732, '88- در یاخته‌های نگهبان روزنه برگ بیدی، هر یک سامانه‌های تبدیل انرژی موجود در یکی از تیلاکوئیدها از نظر ........................ به یکدیگر شباهت و از نظر ........................ با هم تفاوت دارند.', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12733, '89- مطابق اطلاعات کتاب درسی، در محدودهٔ بنفش تا نارنجی نور مرئی، در طول موجی که یک گیاه کمترین میزان گاز اکسیژن را آزاد می‌کند، گروهی از رنگیزه‌های فتوسنتزی قادر به جذب نور خورشید هستند. کدام مورد، درباره این رنگیزه‌ها صحیح است؟', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12734, '90- کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«مطابق اطلاعات کتاب درسی، در چرخه‌ای از واکنش‌های مستقل از نور فتوسنتز که به تثبیت مولکول‌های کربن‌دی‌اکسید در گیاه تره می‌انجامد..............»', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12735, '91- کدام مورد برای تکمیل عبارت مقابل مناسب است؟ «مطابق اطلاعات کتاب درسی، در گیاهانی که ................ به طور قطع.................. »', 3, 4, 33, 142, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12736, '92- مطابق با مطلب کتاب درسی، کدام مورد برای تکمیل عبارت زیر مناسب نیست؟\n\n« در نوعی جاندار که می‌تواند.....................»', 3, 4, 33, 144, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12737, '93- کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n« در چرخه‌ای از واکنش‌های مستقل از نور فتوسنتز که به تولید قند در گیاه برگ بیدی می‌انجامد، می‌توان گفت بلافاصله ........................ مشاهده می‌شود.»', 3, 4, 33, 138, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12738, '94- با توجه به شکل مقابل، کدام مورد در رابطه با یاخته مورد نظر صادق است؟', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12739, ' در گیاه ذرت، طی فرایند(های) تثبیت کربن، اولین ترکیبات پایدار حاصل از طریق پلاسمودسم‌ها به گروهی از یاخته‌های برگ وارد می‌شوند. چند مورد، درباره همه این یاخته‌ها صادق است؟\n\nالف) ژن(های) مربوط به آنزیم آغازگر تثبیت کربن را بیان می‌کنند.\n\nب) بیشترین تراکم سبزدیسه را در بین یاخته‌های برگ دارند.\n\nج) پیوند کربن-کربن را در اسید سه کربنی تجزیه می‌کنند.\n\nد) در تماس با یاخته‌هایی فاقد پروتوپلاست قرار دارند.', 3, 4, 33, 141, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12740, ' مطابق اطلاعات کتاب درسی در رابطه با پروکاریوت‌ها، چند مورد به درستی بیان شده است؟\n\nالف- هر نوع باکتری غیراکسیژن‌زا، به کمک باکتریوکلروفیل به جذب پرتوهای نور می‌پردازد.\n\nب- هر نوع باکتری تثبیت‌کننده نیتروژن، توانایی تولید مولکول $ATP$ در سطح پیش‌ماده را دارد.\n\nپ- هر نوع باکتری تثبیت‌کننده‌ی کربن، باید دارای سامانه‌ای برای تبدیل انرژی نورانی به شیمیایی باشد.\n\nت- هر نوع باکتری اکسیژن‌زا، به دنبال تامین مواد معدنی مورد نیاز برای گیاهان، مواد آلی خود را به دست می‌آورد.', 3, 4, 33, 144, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12741, ' کدام عبارت جمله زیر را به طور صحیح تکمیل می‌کند؟\n\n« باکتری که بتواند برای ساختن ماده آلی از غیرآلی از.................... به عنوان منبع...................استفاده نماید، نمی‌تواند....................»', 3, 4, 33, 144, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12742, '98- با توجه به مطالب کتاب درسی، چند مورد از مطالب زیر، نادرست است؟\n\nالف: برای اندازه‌گیری میزان فتوسنتز گیاهان، می‌توان از اکسیژن مصرف شده و یا کربن‌دی‌اکسید تولید شده استفاده کرد.\n\nب: یکی از ویژگی‌های جانداران فتوسنتزکننده، داشتن مولکول‌های رنگ‌دانه، به‌منظور جذب انرژی نور خورشید است.\n\nج: ویژگی مشترک هر جاندار فتوسنتزکننده، داشتن فتوسیستمی برای تبدیل انرژی نوری به انرژی شیمیایی است.\n\nد: واکنش تثبیت کربن‌دی‌اکسید، فقط در جانداران دارای توانایی جذب و انتقال انرژی نور مشاهده می‌شود.', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12743, ' در خصوص واکنش‌های وابسته به نور در برگ گیاه شمعدانی، کدام گزینه، برای تکمیل عبارت زیر نامناسب است؟\n\n«به طور معمول، در فتوسیستمی که اندازهٔ .................. دارد، الکترون‌های برانگیخته .................. و اولین پروتئینی که پس از آن به طور موقت کاهش می‌یابد، .................. است.»', 3, 4, 33, 136, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12744, '100- کدام گزینه، برای تکمیل عبارت زیر نادرست است؟\n\n«به طور معمول، رنگیزه‌ای که نمودار شمارهٔ «۱» را دارد .................. رنگیزه‌ای که نمودار شمارهٔ «۲» را دارد، ..................»\n\nالف: همانند - در مرکز واکنش سامانهٔ مبدل انرژی نور خورشیدی به شیمیایی، قرار دارد.\n\nب: همانند - با رسیدن هر طول موجی از نور به آنتن‌ها، می‌توانند برانگیخته شوند.\n\nج: برخلاف - نسبت به سبزینهٔ b، در طیف‌های نوری بیشتری، توانایی جذب دارد.\n\nد: برخلاف - به دلیل جذب بخش سبز در نور مرئی، به رنگ سبز دیده می‌شود.', 3, 4, 33, 135, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12745, ' در خصوص سامانه‌های تبدیل انرژی در گیاهان دولپه، کدام مورد صحیح است؟', 3, 4, 33, 136, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12746, ' چند مورد از مطالب زیر، در خصوص واکنش‌های انجام شده در تیلاکوئید نادرست است؟\n\nالف: پرتوهای نور سبز و زرد، تأثیری در تولید $NADPH$ ندارند.\n\nب: اولین پذیرندۀ الکترون از فتوسیستم، در ساختار خود دارای پیوند هیدروژنی است.\n\nج: الکترون حامل انرژی خروجی از $P_{700}$ موجب ساخت $ATP$ در زنجیرۀ انتقال الکترون می‌شود.\n\nد: پروتئین‌های غشایی که بلافاصله قبل و بعد از بزرگ‌ترین فتوسیستم قرار دارند، تنها با بخش آب‌دوست غشا در تماس هستند.', 3, 4, 33, 137, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12747, '103- کدام مورد، دربارهٔ اسپیروژیر، درست است؟', 3, 4, 33, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12748, ' کدام گزینه، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، الکترون‌های کلروفیل (سبزینۀ) a در مرکز واکنش فتوسیستم .................. می‌شوند.»', 3, 4, 33, 137, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12749, ' باتوجه‌به مطالب کتاب‌درسی، در خصوص رنگیزه‌های فتوسنتزی، کدام مورد صحیح است؟', 3, 4, 33, 136, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12750, ' در خصوص واکنش‌های فتوسنتزی مطرح شده در کتاب‌درسی، کدام دو مورد، برای تکمیل عبارت زیر مناسب است؟\n\n«به طور معمول، در واکنش‌های .................. موجود در گل رز، .................. به مصرف می‌رسند.»\n\nالف: مستقل از نور - همۀ ترکیبات نوکلئوتید دار، برای ساخت نوعی قندی سه‌کربنه\n\nب: وابسته به نور - همۀ الکترون‌های یک مولکول آب توسط نوعی پروتئین برای ساخت $NADPH$\n\nج: مستقل از نور - فقط بعضی از قندهای سه‌کربنه تک‌فسفاته، برای ساخت ترکیب پنج‌کربنه تک‌فسفاته\n\nد: وابسته به نور - فقط بعضی از مواد تولیدشده، برای تأمین انرژی در چرخه‌ای از واکنش‌های کلروپلاستی', 3, 4, 33, 138, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12751, ' در خصوص اثرات محیط بر فرایند فتوسنتز، کدام مورد نادرست است؟', 3, 4, 33, 139, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12752, ' در خصوص جذب رنگیزه‌های فتوسنتزی مطرح‌شده در کتاب‌درسی دوازدهم، کدام مورد درست است؟', 3, 4, 33, 136, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12753, ' در خصوص گیاه ذرت، می‌توان گفت .................. نوعی گیاه که مولکول چهار کربنی حاصل از تثبیت اولیۀ کربن در آن، امکان عبور از پلاسمودسم‌ها را ندارد، ..................', 3, 4, 33, 143, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12754, ' باتوجه‌به واکنش‌های یک چرخۀ کالوین در یاخته‌های میانبرگ گیاه خرزهره، کدام مورد نادرست است؟', 3, 4, 33, 138, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12755, ' مطابق با اطلاعات کتاب‌درسی، در خصوص جانداران دارای توانایی تثبیت کربن، کدام مورد درست است؟', 3, 4, 33, 144, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12756, ' در ارتباط با واکنش‌های تثبیت کربن در برگ گیاه خرزهره و باتوجه‌به واکنش‌هایی که پس از تشکیل گروه کربوکسیل رخ می‌دهد، کدام مورد در یک چرخه، پیش از سایرین به انجام می‌رسد؟', 3, 4, 33, 138, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12757, 'مطابق با اطلاعات کتاب‌درسی، کدام عبارت صحیح است؟', 3, 4, 33, 144, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12758, ' باتوجه‌به واکنش‌های یک‌چرخۀ کالوین در برگ گیاه ادریسی، کدام مورد نادرست است؟', 3, 4, 33, 138, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12759, ' کدام مورد یا موارد، بیان‌کنندۀ ویژگی همۀ جاندارانی است که می‌توانند فتوسنتز انجام دهند؟\n\nالف: بخشی از انرژی نور خورشید را با کمک نوعی سبزینه (کلروفیل) جذب می‌کنند.\n\nب: سامانه‌ای برای تبدیل انرژی نورانی به انرژی شیمیایی درون آن‌ها وجود دارد.\n\nج: عدد اکسایش کربن در $CO_2$ را در واکنش‌های مستقل از نور کاهش می‌دهند.\n\nد: طی فرایندی وابسته به نور، اکسیژن مولکولی را تولید می‌کنند.', 3, 4, 33, 144, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12760, ' چند مورد، مشخصۀ مشترک همۀ گیاهانی است که برگ مناسب‌ترین ساختار برای فتوسنتز در آن‌ها می‌باشد؟\n\nالف: یاخته‌های آوندی زندۀ آن‌ها به سمت روپوست زیرین قرار گرفته‌اند.\n\nب: تعداد روزنه‌ها در روپوست زیرین آن‌ها بیشتر از روپوست رویی است.\n\nج: در مجاورت روپوست زیرین آن‌ها، یاخته‌های میانبرگ با فاصله از هم قرار دارند.\n\nد: یاخته‌های پارانشیمی با شکل و اندازۀ مختلف، دارای سبزدیسه (کلروپلاست) هستند.', 3, 4, 33, 135, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12761, ' دربارۀ نوعی سامانۀ تبدیل انرژی در غشای تیلاکوئید یاختۀ میانبرگ گیاه نعنا، کدام عبارت درست است؟', 3, 4, 33, 136, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12762, ' کدام عبارت، دربارۀ مولکول‌های رنگیزۀ موجود در یک فتوسیستم درست است؟', 3, 4, 33, 136, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:25:08', 1, NULL, NULL, 'free'),
(12763, '1-کدام موارد، درباره هر ناقل قابل استفاده در فرایند همسانه‌سازی دنا (DNA) درست است؟ الف: زمانی که یاخته نمی‌خواهد تقسیم شود، آنزیم هلیکاز می‌تواند به آن متصل شود. ب: نوعی توالی دنا (DNA) است که پروتئین هیستون، همراه آن قرار ندارد. ج: معمولاً درون باکتری‌ها و بعضی قارچ‌ها مثل مخمرها وجود دارد. د: معمولاً یک جایگاه تشخیص برای نوعی آنزیم برش‌دهنده دارد.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12764, '2-مطابق مطالب کتاب درسی، دختر بچه‌ای ۴ ساله که دارای نوعی نقص ژنی بود، چه مشخصه‌ای داشت؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12765, '3-پس از اثر نوعی آنزیم برش‌دهنده بر یک ژن، بخشی بدون مکمل در رشتهٔ الگوی ژن ایجاد می‌شود که دارای توالی ATAT است و نوکلئوتید تیمین‌دار آن با نوکلئوتید سیتوزین‌دار پیوند فسفودی‌استر دارد. کدام عبارت، درباره جایگاه تشخیص این آنزیم نادرست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12766, '4-کدام مورد، برای تکمیل عبارت زیر مناسب است؟ «در فرایند همسانه‌سازی دنا (DNA)، در مرحلهٔ ......................... دنیای .........................»', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12767, '5-مطابق با اطلاعات کتاب درسی، تولید انسولین در مهندسی ژنتیک را چهار مرحله و تولید پروتئین‌های انسانی با استفاده از دام‌های تراژنی را پنج مرحله در نظر می‌گیریم. درخصوص مرحله‌ای در این فرایندها که با تولید جاندار تراژنی همراه است، کدام مورد به‌درستی مطرح شده است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12768, '6-با فرض عدم انجام همانندسازی مستقل در راکیزه‌ها، تعداد مراحلی از اولین ژن‌درمانی موفقیت‌آمیز که طی آن، تغییری در تعداد پیوندهای فسفودی‌استر دنا (DNA) ایجاد نمی‌شود، با تعداد کدام مورد برابر است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12769, '7-در ارتباط با کاربردهای مربوط به فناوری‌های نوین زیستی، کدام عبارت صحیح است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12770, '8-در یکی از مراحل مربوط به همسانه‌سازی دنا، علاوه‌بر اینکه انتهاهای چسبنده ایجاد می‌شوند، همه انتهاهای چسبنده از بین می‌روند. چند مورد، درباره این مرحله صحیح است؟ الف: پیوندهای هیدروژنی بدون دخالت آنزیم تشکیل می‌شوند. ب: از آنزیم برش‌دهنده‌ای مشابه با مرحله دیگری استفاده می‌شود. ج: از هیچ‌گونه شوکی به‌منظور تخریب دیواره باکتری استفاده نمی‌شود. د: از آنزیمی استفاده می‌شود که در هیچ‌کدام از مراحل دیگر استفاده نمی‌شود.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12771, '9-درخصوص زیست‌فناوری، کدام مورد به‌طور نادرست بیان شده است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12772, '10-در ارتباط با تولید انسولین، کدام مشخصه، محصول تولید شده به‌وسیله انتقال ژن انسولین انسانی به باکتری را از محصول تولید شده به روش مهندسی ژنتیک متمایز می‌کند؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12773, '11-کدام موارد زیر، از دلایل طراحی و تولید جانوران تراژن در زیست‌فناوری به شمار می‌آیند؟ الف: ساخت داروهای خاص در بدن جانوران ب: مطالعه عملکرد ژن‌های مربوط به عوامل رشد در دام‌ها ج: بررسی نوعی بیماری خودایمنی مؤثر بر دستگاه عصبی مرکزی د: تولید شیر مناسب‌تر برای انسان، در مقایسه با شیر طبیعی دام‌ها', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12774, '12-در خصوص نمونه‌ای از همسانه‌سازی مولکول‌های دنا که چهار مرحله آن در ابتدای فصل هفتم زیست‌شناسی پایه دوازدهم توضیح داده شده، کدام مورد درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12775, '13-درخصوص مراحل انتهایی مربوط به همسانه‌سازی دنا، کدام مورد، از نظر درستی یا نادرستی، با سایر موارد تفاوت دارد؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12776, '14-کدام مورد یا موارد زیر، فقط درخصوص بعضی از انواع ناقل‌های همسانه‌سازی استفاده شده در مهندسی ژنتیک، درست است؟ الف: مولکول دنایی دو رشته‌ای و حلقوی است. ب: ژن مقاومت به پادزیست را نگهداری می‌کند. ج: می‌توانند مستقل از فام‌تن اصلی یاخته تکثیر شوند. د: بیش از یک جایگاه تشخیص برای آنزیم برش‌دهنده دارد.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12777, '15-کدام مشخصه، می‌تواند مهندسی پروتئین را از مهندسی ژنتیک متمایز کند؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12778, '16-درخصوص گیاه پنبه‌ای که با ویژگی مقاومت در برابر آفت تولید شده، کدام مورد نادرست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12779, '17-چند مورد، در ارتباط با یاخته‌های بنیادی توده یاخته‌ای درونی بلاستوسیست صحیح است؟ الف: همانند یاخته‌های تروفوبلاست، در تغذیه یاخته‌های جنینی نقش دارند. ب: برخلاف یاخته‌های تروفوبلاست، فقط یاخته‌های جنینی را تشکیل می‌دهد. ج: همانند یاخته‌های بنیادی بالغ در مغز استخوان، در تولید یاخته‌های دستگاه ایمنی نقش دارند. د: برخلاف یاخته‌های بنیادی کبد، می‌توانند در شرایط آزمایشگاهی، همه یاخته‌های بدن را تولید کنند.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12780, '18-درخصوص یاخته‌های بنیادی بالغ در مغز استخوان، کدام عبارت درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12781, '19-درخصوص مقایسه دوره‌های زیست‌فناوری، کدام عبارت صحیح است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12782, '20-درخصوص پروتئین‌های مطرح شده در کتاب درسی که تنها به کمک روش‌های زیست فناوری تولید می‌شوند، کدام مورد درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12783, '21-مطابق مطالب کتاب درسی درخصوص بررسی سه زنجیرهٔ تشکیل‌دهنده پیش انسولین، کدام مورد برای تکمیل عبارت زیر مناسب است؟ «زنجیره‌ای که بخشی از ژن مربوط به آن ......................... .»', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12784, '22-مطابق با مطالب کتاب درسی، کدام عبارت درخصوص همهٔ دیسک‌ها (پلازمیدها) درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12785, '23-درخصوص مراحل مربوط به همسانه‌سازی دنا، در یکی از مراحل با ایجاد منفذ در غشای باکتری، باکتری دارای دنای نوترکیب تشکیل می‌شود. کدام مورد، می‌تواند ویژگی مشترک مراحل قبل و بعد از این مرحله را بیان کند؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12786, '24-درخصوص کاربردهای زیست فناوری در حوزه‌های پزشکی، کشاورزی و تولید جانوران تراژنی، کدام عبارت صحیح است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12787, '25-درخصوص مقایسهٔ مراحل مربوط به ساخت هورمون انسولین به روش مهندسی ژنتیک، کدام عبارت درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12788, '26-در مرحله‌ای از اولین ژن‌درمانی موفق، ویروس تغییریافته به درون یاختهٔ بیمار منتقل می‌شود. درخصوص مراحل قبل و بعد از این مرحله، کدام مورد نادرست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12789, '27-کدام عبارت، دربارهٔ کاربردهای زیست‌فناوری درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12790, '28-با توجه به شکل زیر که ساختار نوعی دنا (DNA) را نشان می‌دهد، کدام عبارت درست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12791, '29-پزشکان از روش‌های زیست‌فناوری یا محصولات ساخته‌شده با آن، می‌توانند برای درمان بیماران استفاده کنند. با توجه به مطالب کتاب درسی، کدام عبارت دربارهٔ استفاده‌های رشتهٔ پزشکی از زیست‌فناوری نوین درست نیست؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12792, '30-کدام موارد دربارهٔ آنزیم برش‌دهندهٔ EcoRI که قسمتی از سامانهٔ دفاعی نوعی باکتری است، درست می‌باشد؟\n\nالف) نمی‌تواند بر روی مولکول دارای توالی افزاینده اثر نماید.\n\nب) نمی‌تواند پیوند بین قند و فسفات درون نوکلئوتید جایگاه تشخیص خود را بشکند.\n\nج) در هر انتهای چسبندهٔ حاصل از عمل آن همانند جایگاه تشخیص آن، نسبت نوکلئوتید آدنین‌دار به تیمین‌دار، یک است.\n\nد) در بیان ژن آن تنها یک نوع آنزیم دخالت دارد که این آنزیم فاقد توانایی ویرایش است.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12793, '31-کدام گزینه در مورد اولین جانداران تغییریافتهٔ ژنتیکی یا تراژن نادرست است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12794, '32-در کدام مراحل از مهندسی ژنتیک جهت همسانه‌سازی دنا از آنزیمی متعلق به سامانهٔ دفاعی باکتری می‌تواند استفاده شود؟\n\nالف) مرحله‌ای که دنا را به قطعات کوتاه‌تری می‌شکنند و سپس این قطعات را جدا و تشخیص می‌دهند.\n\nب) مرحله‌ای که در آن، دنای نوترکیب از جاگذاری ژن در دنای ناقل ایجاد می‌شود.\n\nج) مرحله‌ای که در آن، به منظور قرار دادن دنای نوترکیب در باکتری میزبان منافذی در دیوارهٔ آن ایجاد می‌شود.\n\nد) مرحله‌ای که در آن، جهت جداسازی یاخته‌های تراژنی دارای دنای نوترکیب از پادزیستی مثل آمپی‌سیلین استفاده می‌شود.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12795, '33-در مرحلهٔ ......................... مهندسی ژنتیک به منظور ......................... ، ......................... .', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12796, '34-کدام گزینه عبارت زیر را به‌درستی کامل می‌کند؟\n\n«به‌منظور تولید آمیلاز مقاوم به گرما به روش مهندسی پروتئین لازم است ......................... .»', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12797, '35-چند مورد عبارت زیر را به‌درستی کامل می‌کند؟\n\n«یاخته‌های بنیادی ......................... توانایی تمایز به ......................... را دارند.»\n\nالف) جنینی مورولا - همهٔ انواع یاخته‌های جنینی و برخی یاخته‌های خارج جنینی\n\nب) بالغ کبدی - تمام یاخته‌های کبدی و مربوط به لوزالمعده\n\nج) جنینی درونی بلاستولا - انواع یاخته‌های بدن جنین\n\nد) بالغ مغز استخوان - تمام بافت‌ها', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12798, '36-کدام یاخته‌ها از نوع بنیادی جنینی‌اند و قادر به تولید یاخته‌های ترشح‌کنندهٔ HCGاند؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12799, '37-کدام‌یک از گزینه‌های زیر از ویژگی‌های یاخته‌ای است که نخستین ژن‌درمانی انسان با کمک آن انجام شد؟', 3, 4, 34, 117, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12800, '38-کدام گزینه در ارتباط با ساختار هورمونی که در پاسخ به افزایش گلوکز خون ترشح می‌شود، نادرست است؟', 3, 4, 34, 117, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12801, '39-کدام‌یک از گزینه‌های زیر اشاره به جانداری تراژن دارد؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12802, '40-شکل زیر مربوط به لولهٔ گوارش جانوری است که دارای طناب عصبی شکمی است. اولین محل تبدیل پیش‌سم غیرفعال به سم فعال کدام گزینه می‌باشد؟', 3, 4, 34, 116, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12803, '41-چند مورد جملهٔ زیر را به‌درستی کامل می‌کند؟\n\n«با استفاده از کاربردهای زیست‌فناوری در پزشکی می‌توان ......................... .»\n\nالف) بیماری‌های ارثی را درمان کرد.\n\nب) بیمارانی که بدون علائم هستند را تشخیص داد.\n\nج) واکسن نوترکیب تولید کرد.\n\nد) بدون وارد کردن میکروب به بدن میزبان، واکسن تولید کرد.', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12804, '42-کدام گزینه در ارتباط با مهندسی ژنتیک درست است؟', 3, 4, 34, 111, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12805, '43-با توجه به مطلب مربوط به مراحل ایجاد گیاهان زراعی تراژنی از طریق مهندسی ژنتیک در کتاب درسی، ......................... انجام می‌شود.', 3, 4, 34, 111, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12806, 'چند مورد، جملهٔ زیر را به‌درستی تکمیل می‌کند؟\n\n«به‌کمک روش‌های مهندسی ژنتیک، ......................... است.»\n\nالف) داروی کاهندهٔ قند خون به‌کمک یاخته‌های فاقد دنای خطی تولید شده\n\nب) نگهداری طولانی‌مدت پروتئینی با فعالیت ضدویروسی، امکان‌پذیر شده\n\nج) مدت زمان فعالیت پلاسمایی نوعی آنزیم تجزیه‌کنندهٔ لخته، افزایش یافته\n\nد) آنزیم مورد استفاده در صنایع غذایی و نساجی، نسبت به گرما مقاوم شده', 3, 4, 34, 119, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12807, 'چند مورد، از اهداف روش‌های معمول در زیست‌فناوری محسوب می‌شود؟\n\nالف) افزایش میزان تمایل آنزیم برای اتصال به پیش‌ماده\n\nب) بررسی دنای حشرات به دام‌افتاده در رزین‌های گیاهی\n\nج) تشخیص ژن‌های جهش‌یافته در بیماران مستعد به ملانوما\n\nد) افزایش پایداری نوعی محصول ژنی با استفاده از نوعی تغییر جزئی', 3, 4, 34, 119, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12808, '46-برای مقاوم کردن گیاه پنبه، ژن سازندهٔ پیش‌سم را از نوعی جاندار استخراج می‌کنند. کدام گزینه دربارهٔ این جاندار درست است؟', 3, 4, 34, 116, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12809, 'یکی از روش‌های تولید پروتئین انسانی، استفاده از دام تراژنی است. کدام گزینه دربارهٔ این روش درست است؟', 3, 4, 34, 118, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12810, '48-با توجه به سه دورهٔ زیست‌فناوری، در دوره‌ای که ......................... استفاده از ......................... دور از انتظار ......................... .', 3, 4, 34, 110, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
