(12815, 'کدام گزینه دربارهٔ فرایندهای مربوط به مهندسی ژنتیک درست است؟', 3, 4, 34, 111, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
