(12821, '59-در رابطه با مهندسی ژنتیک، کدام گزینه به‌درستی بیان شده است؟', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12822, 'کدام گزینه، جملهٔ زیر را نمی‌تواند به‌درستی کامل کند؟\n\n«یاخته‌های بنیادی ......................... .»', 3, 4, 34, 113, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12823, '61-کدام موارد به ترتیب مراحل ساخت داروی $Humulin\\ N$ به روش مهندسی ژنتیک را به‌درستی مشخص می‌کند؟\n\nالف) خالص کردن زنجیره‌های پلی‌پپتیدی\n\n\n\nب) انتخاب یاخته‌های دریافت‌کننده به کمک پادزیست\n\nج) انتقال ژن زنجیره‌های $A$ و $B$ به‌طور جداگانه به دیسک\n\nد) ترکیب زنجیره‌های $A$ و $B$ برای تولید داروی فعال', 3, 4, 34, 117, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12824, '62-مطابق با کتاب درسی، اولین تجربهٔ موفقیت‌آمیز ژن‌درمانی برای معالجهٔ دختربچهٔ مبتلا به نوعی بیماری انجام شد. کدام گزینه دربارهٔ این بیماری نادرست است؟', 3, 4, 34, 117, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12825, 'کدام گزینه در ارتباط با ژن‌درمانی درست است؟', 3, 4, 34, 117, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'فعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
(12826, '64-کدام گزینه جملهٔ زیر را به‌درستی تکمیل می‌کند؟\n\n«انواعی از یاخته‌های بنیادی ......................... که می‌توانند در محیط کشت .........................»', 3, 4, 34, NULL, NULL, NULL, NULL, 'متوسط', NULL, NULL, 'غیرفعال', 'اتوماتیک', '2026-04-05 14:38:34', 1, NULL, NULL, 'free'),
