INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(105, 3, 1, 12.50, 2, 10, 4, 0, 27, '{\"total_questions\":16,\"correct_count\":2,\"incorrect_count\":10,\"unanswered_count\":4,\"accuracy_rate\":12.5,\"score\":0,\"mabhas_stats\":{\"فصل شش یازدهم\":{\"correct\":0,\"incorrect\":4,\"unanswered\":2,\"total\":6},\"فصل دو یازدهم\":{\"correct\":2,\"incorrect\":6,\"unanswered\":2,\"total\":10}}}', '{\"evaluation\":{\"7911\":{\"correct_option_id\":44239,\"descriptive_answer\":{\"text\":\"$2$ - گزینه «$4$» ابتدا مقاومت سیم را به‌دست می‌آوریم: $R = ρ l / A -> l=60cm=0/6m , ρ=10^-8 Ω.m / A=πr^2 , r=D/2=2mm=2×10^-3 m$ $R = 10^-8 × 0/6 / 3×(2×10^-3)^2 = 6×10^-9 / 3×4×10^-6 => R = 10^-3 / 2 Ω$ اکنون با استفاده از قانون اهم جریان عبوری از سیم را محاسبه می‌کنیم: $I = V / R = V=0/3mV=3×10^-4 V / R=10^-3 / 2 Ω -> I = 3×10^-4 / 10^-3 / 2$ $=> I = 2×3×10^-4 / 10^-3 = 0/6 A$ بنابراین مدت زمان تخلیه باتری برابر است با: $I = Δq / Δt -> Δq=900C / I=0/6A -> Δt = 900 / 0/6 = 1500 s$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7913\":{\"correct_option_id\":44231,\"descriptive_answer\":{\"text\":\"$4$ - گزینه «$4$»  ابتدا از روی نمودار با استفاده از قانون اهم نسبت مقاومت الکتریکی سیم $A$ به سیم $B$ را می‌یابیم: $R = V / I -> I_A=I_B=4A / V_A=6V , V_B=2V -> R_A / R_B = V_A / V_B × I_B / I_A$ $=> R_A / R_B = 6 / 2 × 1 = 3$ اکنون با داشتن نسبت مقاومت دو سیم، نسبت حجم آن‌ها را می‌یابیم. ($ρ_A$ و $ρ_B$ مقاومت ویژه هریک از سیم‌ها است.) $R = ρ L / A -> V=AL => A=V/L -> R = ρ L^2 / V$ $L_A=L_B -> R_A / R_B = ρ_A / ρ_B × V_B / V_A$ $R_A/R_B=3 / ρ_A=2ρ_B -> 3 = 2ρ_B / ρ_B × V_B / V_A => V_A / V_B = 2 / 3$ بنابراین با استفاده از رابطه چگالی به‌صورت زیر نسبت $m_A / m_B$ را حساب می‌کنیم: ($ρ_A$ و $ρ_B$ چگالی هریک از سیم‌ها است.) $m = ρV => m_A / m_B = ρ_A / ρ_B × V_A / V_B$ $ρ_A=3/2 ρ_B / V_A/V_B=2/3 -> m_A / m_B = 3/2 ρ_B / ρ_B × 2/3 => m_A / m_B = 1$\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":44230,\"is_answered\":true},\"7914\":{\"correct_option_id\":44225,\"descriptive_answer\":{\"text\":\"$5$ - گزینه «$2$» الف) موازی ب) موازی پ) دو سر $R_1$ اتصال کوتاه است. بنابراین فقط مقاومت $R_2$ در مدار وجود دارد. ت) مقاومت‌ها متوالی‌اند. بنابراین فقط موارد «الف» و «ب» به‌طور موازی بسته شده‌اند. (جریان الکتریکی و مدارهای جریان مستقیم) (فیزیک $2$، صفحه‌های $55$ تا $61$)\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7968\":{\"correct_option_id\":44011,\"descriptive_answer\":{\"text\":\"$59$ - گزینه «$4$» با توجه به این که مقاومت آمپرسنج ایده آل، ناچیز است، ابتدا جریان گذرنده از آمپرسنج را حساب می کنیم: $I = ε / R + r ⇒ I = 10 / 0 + 1 = 10 A$ عددی که ولت سنج ایده آل نشان می دهد، همان اختلاف پتانسیل دو سر مولد است. داریم: $V = ε - rI = 10 - (1)(10) = 0$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":44010,\"is_answered\":true},\"8006\":{\"correct_option_id\":43853,\"descriptive_answer\":{\"text\":\"$97$ - گزینه «$2$» موارد الف و پ نادرست‌اند. آ) دیود نور گسیل یک رسانای غیراُهمی است. پ) مقاومت ویژهٔ نیم‌رساناها با افزایش دما کاهش می‌یابد.\"},\"status\":\"correct\",\"level\":\"آسان\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43853,\"is_answered\":true},\"8045\":{\"correct_option_id\":43697,\"descriptive_answer\":{\"text\":\"136- گزینه «2» ابتدا در حالتی که کلید $K$ باز باشد، مقاومت معادل مدار را می‌یابیم: $Req = R+R+ R / 2 ⇒ Req = 5 / 2 R$ اکنون، جریان اصلی مدار را که از آمپرسنج عبور می‌کند، به‌دست می‌آوریم: $I1 = ε / Req+r → r=0 → I1 = ε / 5 / 2 R ⇒ I1 = 2 / 5 × ε / R$ با توجه به شکل زیر، در حالتی که کلید $K$ بسته باشد، سه مقاومتی که بین نقاط هم‌پتانسیل $A$ قرار گرفته‌اند، به علت اتصال کوتاه از مدار حذف می‌شوند و تنها یک مقاومت $R$ در مدار می‌ماند. بنابراین، مقاومت معادل مدار برابر $R\'eq = R$ خواهد شد. در این حالت داریم: $I2 = ε / R\'eq+r → R\'eq=R / r=0 → I2 = ε / R+0 ⇒ I2 = ε / R$ در آخر داریم: $I2 / I1 = ε / R / 2 / 5 × ε / R ⇒ I2 / I1 = 5 / 2$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43698,\"is_answered\":true},\"8073\":{\"correct_option_id\":43518,\"descriptive_answer\":{\"text\":\"مقاومت $R_1$ با $R_2$ متوالی و معادل آن‌ها ($R_{1,2}$) با مقاومت $R_3$ موازی است و معادل آن‌ها ($R_{1,2,3}$) با $R_4$ متوالی و معادل آن‌ها با $R_5$ موازی است. $R_{1,2,3,4,5}$ با $R_6$ متوالی و درنهایت معادل آن‌ها با $R_7$ موازی است. اگر اندازه هر مقاومت $R$ باشد، داریم:\\r\\n\\r\\n$R_{1,2} = 2 R$\\r\\n\\r\\n$R_{1,2,3} = 2 R × R / 2 R + R = 2 / 3 R$\\r\\n\\r\\n$R_{1,2,3,4} = 2 / 3 R + R = 5 / 3 R$\\r\\n\\r\\n$R_{1,2,3,4,5} = 5 / 3 R × R / 5 / 3 R + R = 5 / 8 R$\\r\\n\\r\\n$R_{1,2,3,4,5,6} = 5 / 8 R + R = 13 / 8 R$\\r\\n\\r\\n$R_{eq} = 13 / 8 R × R / 13 / 8 R + R = 13 / 21 R ⇒ 13 / 21 R = 1/3 ⇒ R = 2/1 Ω$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43516,\"is_answered\":true},\"8077\":{\"correct_option_id\":43501,\"descriptive_answer\":{\"text\":\"تمام وسایل الکتریکی خانگی با ولتاژ $220 V$ کار می‌کنند. به این ترتیب وقتی همه وسایل روشن هستند، به‌طور موازی به یکدیگر متصل‌اند و جریانی که از فیوز در شاخه اصلی می‌گذرد، مجموع جریان‌هایی است که از هر وسیله روشن می‌گذرد.\\r\\n\\r\\n$I$ فیوز $ = I$ اتو $ + I$ بخاری $ + I$ لامپ‌ها\\r\\n\\r\\n$P = VI ⇒ I = P / V ⇒ 15 = 2000 / 220 + 860 / 220 + 40 N / 220 ⇒ 15 = 13 + 2 / 11 N ⇒ N = 11$\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43501,\"is_answered\":true},\"8093\":{\"correct_option_id\":43432,\"descriptive_answer\":{\"text\":\"$R_1,2=(R×R)/(R+R)=R/2$\\r\\n\\r\\n$R_1,2,3=R_3+R_1,2=R+R/2=3/2R$\\r\\n\\r\\n$R_eq=(R_4×R_1,2,3)/(R_4+R_1,2,3)=(R×3/2R)/(R+3/2R)=(3/2R^2)/(5/2R)=3/5R$\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43435,\"is_answered\":true},\"8094\":{\"correct_option_id\":43431,\"descriptive_answer\":{\"text\":\"$P=RI^2 ⇒ 3=3I_3Ω^2 ⇒ I_3Ω=1A$\\r\\n\\r\\n$V_3Ω=V_12Ω ⇒ 3×1=12×I_12Ω ⇒ I_12Ω=0/25A$\\r\\n\\r\\n$I=1+0/25=1/25A$\\r\\n\\r\\n$V$باتری $=ε-rI=40-1/6×1/25=38V$\\r\\n\\r\\n$P$خروجی باتری $=V$باتری$I=38×1/25=47/5W$\\r\\n\\r\\nبه‌عنوان راه‌حل دیگری می‌توان ابتدا مقاومت $R$ را محاسبه کرد و سپس توان خروجی باتری را که برابر با مجموع توان مصرفی در مقاومت‌ها (به‌غیر از مقاومت داخلی است)، به‌دست آوریم.\\r\\n\\r\\nنکته: از ترکیب دو رابطه $V$باتری $=ε-rI$ و $P$خروجی باتری $=V$باتری$I$ می‌توان به رابطه زیر دست یافت که توصیه می‌شود آن را نیز به خاطر بسپارید:\\r\\n\\r\\n$P$خروجی باتری $=εI-rI^2$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43428,\"is_answered\":true},\"8768\":{\"correct_option_id\":53203,\"descriptive_answer\":{\"text\":\"۱ همه موارد نادرست‌ند. \\n\\nالف) یاخته کشنده طبیعی، یاخته‌های سرطانی و آلوده به ویروس را نابود می‌کند. بنابراین فقط در فرد مبتلا به تومور بدخیم، یاخته کشنده طبیعی با یاخته‌های تومور مبارزه می‌کند. \\n\\nب) تومور (فارغ از خوش‌خیم یا بدخیم بودن آن)، توده‌ای است که در اثر تقسیمات تنظیم نشده ایجاد می‌شود. تومورها به دو نوع خوش‌خیم و بدخیم تقسیم می‌شوند. \\n\\nج) نوع خوش‌خیم رشدی کم دارد و یاخته‌های آن در جای خود می‌مانند و منتشر نمی‌شوند. این نوع تومور معمولاً آن‌قدر بزرگ نمی‌شود که به بافت‌های مجاور خود آسیب بزند. البته در مواردی که تومور بیش از اندازه بزرگ شود، می‌تواند در انجام اعمال طبیعی اندام اختلال ایجاد کند. تومور بدخیم یا سرطان به بافت‌های مجاور حمله می‌کند. بنابراین می‌تواند باعث اختلال در بافت‌های سالم بدن شود. \\n\\nد) در تومور خوش‌خیم، یاخته‌های آن در جای خود می‌مانند و منتشر نمی‌شوند. در تومورهای بدخیم، یاخته‌هایی از این تومورها می‌توانند جدا شوند و همراه با جریان خون، یا به‌ویژه لنف به نواحی دیگر بدن بروند، در آنجا مستقر شوند و رشد کنند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل شش یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8770\":{\"correct_option_id\":53212,\"descriptive_answer\":{\"text\":\"۳\\n مورد (ج) و (د) عبارت را به درستی تکمیل می‌کنند.\\n\\n بررسی همۀ موارد: \\nالف تومورهای خوش‌خیم، قابلیت پخش در بدن و انتقال به بافت‌های دوردست (گسترش یاخته‌های سرطانی) را ندارند.\\n\\n ب ملانوما، نوعی تومور بدخیم یاخته‌های رنگ‌دانه‌دار پوست است. یاخته‌های این تومور، همگی تعادل بین تقسیم و مرگ خود را از دست داده‌اند که به شکل تومور درآمده‌اند!\\n\\n ج این مورد عیناً خط کتاب درسیه!\\n\\n د در کتاب درسی می‌خوانیم اگر تعادل بین تقسیم یاخته‌ها و مرگ آنها به هم بخورد، نتیجه می‌تواند ایجاد یک تومور باشد! یعنی ممکن است این تعادل از دست برود، ولی تومور تشکیل نشود! از سوی دیگر در برخی موارد ممکن است میزان مرگ یاخته‌ها بیشتر از میزان تولید آنها باشد که در چنین حالتی هم تعادل بین مرگ و تقسیم بر هم خورده اما توموری ایجاد نمی‌شود.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل شش یازدهم\",\"selected_option_id\":53214,\"is_answered\":true},\"8771\":{\"correct_option_id\":53216,\"descriptive_answer\":{\"text\":\"۴ \\nمرحله سوم اینترفاز، $G2$ است که در آن، ساخت پروتئین‌ها (پلیمرهای آمینواسیدی) افزایش می‌یابد. \\n\\nبررسی سایر گزینه‌ها: \\n۱ اینترفاز کلاً سه مرحله دارد! در پروفاز تقسیم، فامتن‌ها، به‌تدریج با میکروسکوپ نوری قابل رویت می‌شوند. پروفاز جزء اینترفاز نیست!\\n\\n ۳ در مرحله $S$، همانندسازی دنای خطی هسته‌ای (نه حلقوی سیتوپلاسمی) صورت می‌گیرد. خودمونی: بچه‌ها البته همانندسازی دنای سیتوپلاسمی در هر مرحله از اینترفاز ممکنه رخ بده. پس شاید این گزینه یک‌ذره ابهام داشته باشه و باید بتونین بهترین تصمیم رو بگیرین برای جواب به این سؤال! \\n\\n۴ مرحله $G1$، بلندترین (نه کوتاه‌ترین) مرحله اینترفاز است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل شش یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8772\":{\"correct_option_id\":53221,\"descriptive_answer\":{\"text\":\"۵ \\nموارد (الف) و (ب) درست‌ند. \\n\\nبررسی موارد:\\n الف) بالا بودن سن مادران در هنگام بارداری از عوامل مهم بروز این بیماری است؛ زیرا با افزایش سن مادر، احتمال خطای کاستمانی در تشکیل یاخته‌های جنسی وی بیشتر می‌شود.\\n\\n ب) برای تعیین تعداد فامتن‌ها و تشخیص بعضی از ناهنجاری‌های فامتنی، کاریوتیپ تهیه می‌شود.\\n\\n ج) افراد مبتلا به نشانگان داون، در یاخته‌های پیکری خود $47$ فامتن دارند. فامتن اضافی مربوط به شماره $21$ است؛ یعنی یاخته‌های پیکری این افراد $3$ فامتن شماره $21$ دارند. این مشکل به علت باهم ماندن فامتن‌ها و جدانشدن آن‌ها در آنافاز رخ می‌دهد، نه به‌دلیل چندلادی (پلی‌پلوئیدی) شدن.\\n\\n د) علت بروز نشانگان داون آن است که یکی از یاخته‌های جنسی ایجادکننده فرد (نه لزوماً یاخته جنسی مادر)، به‌جای یک فامتن شماره $21$، دارای دو فامتن $21$ بوده است؛ بنابراین ممکن است گامت مادری طبیعی باشد و گامت پدری دو فامتن $21$ داشته باشد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل شش یازدهم\",\"selected_option_id\":53220,\"is_answered\":true},\"8773\":{\"correct_option_id\":53226,\"descriptive_answer\":{\"text\":\"۶ \\nکاریوتیپ تصویری از کروموزوم‌ها در حداکثر فشردگی است که بر اساس طول، شکل و محل سانترومر مرتب شده‌اند. با توجه به شکل مقابل، یازدهمین کروموزوم، مربوط به کروموزوم شماره «$6$» است که در ستون اول از ردیف دوم قرار دارد. همه‌ی کروموزوم‌ها در این تصویر بیشترین فشردگی و در نتیجه بیشترین قطر و کمترین طول ممکن را دارند. \\n\\nبررسی سایر گزینه‌ها: \\n۱ با توجه به شکل، کروموزوم‌های جنسی دقیقاً در زیر سایر کروموزوم‌ها قرار ندارند. \\n\\n۲ کروموزوم $X$ از کروموزوم قبلی خود (شماره $22$) بزرگتر است و تعداد نوکلئوزوم‌های بیشتری دارد. این موضوع در رابطه با کروموزوم $22$ و $21$ هم صادق است. \\n\\n۳ کروموزوم‌های جنسی در ردیف چهارم تصویر قرار دارند و با سایر کروموزوم‌ها در یک ستون قرار نگرفته‌اند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل شش یازدهم\",\"selected_option_id\":53224,\"is_answered\":true},\"8779\":{\"correct_option_id\":53249,\"descriptive_answer\":{\"text\":\"۱۲\\nبه‌طور کلی هر دو نوع تومور خوش‌خیم و بدخیم بر اثر تقسیمات تنظیم نشده ایجاد می‌شوند. بررسی سایر گزینه‌ها:\\n\\nگزینه «۱»: تومور خوش‌خیم معمولاً رشد کمی دارد؛ یعنی سرعت تقسیم یاخته‌های آن کم است.\\n\\nگزینه «۲»: لیپوما نوعی تومور خوش‌خیم است که بر اثر تقسیم یاخته‌های چربی ایجاد می‌شود.\\n\\nگزینه «۴»: گاهی ممکن است تومور خوش‌خیم بیش از اندازه بزرگ شود و در انجام اعمال طبیعی اندام، اختلال ایجاد کند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل شش یازدهم\",\"selected_option_id\":53250,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"7913\":44230,\"7968\":44010,\"8006\":43853,\"8045\":43698,\"8073\":43516,\"8077\":43501,\"8093\":43435,\"8094\":43428,\"8770\":53214,\"8772\":53220,\"8773\":53224,\"8779\":53250},\"totalTimeSpent\":27,\"questionTimes\":{\"7913\":2006,\"7968\":1001,\"8006\":1007,\"8045\":1012,\"8077\":992,\"8093\":1003,\"8094\":1001,\"8770\":2002,\"8772\":1000,\"8773\":4001,\"8779\":1015},\"selectionLog\":[{\"questionId\":8773,\"optionId\":53224,\"timeSpentMs\":4001,\"timestamp\":1781788604188},{\"questionId\":8077,\"optionId\":43501,\"timeSpentMs\":992,\"timestamp\":1781788606307},{\"questionId\":8094,\"optionId\":43428,\"timeSpentMs\":1001,\"timestamp\":1781788608045},{\"questionId\":8772,\"optionId\":53220,\"timeSpentMs\":1000,\"timestamp\":1781788609907},{\"questionId\":7913,\"optionId\":44230,\"timeSpentMs\":2006,\"timestamp\":1781788612148},{\"questionId\":8006,\"optionId\":43853,\"timeSpentMs\":1007,\"timestamp\":1781788613619},{\"questionId\":8770,\"optionId\":53214,\"timeSpentMs\":2002,\"timestamp\":1781788615787},{\"questionId\":8779,\"optionId\":53250,\"timeSpentMs\":1015,\"timestamp\":1781788617389},{\"questionId\":7968,\"optionId\":44010,\"timeSpentMs\":1001,\"timestamp\":1781788618866},{\"questionId\":8045,\"optionId\":43698,\"timeSpentMs\":1012,\"timestamp\":1781788620251},{\"questionId\":8073,\"optionId\":43516,\"timeSpentMs\":0,\"timestamp\":1781788622139},{\"questionId\":8093,\"optionId\":43435,\"timeSpentMs\":1003,\"timestamp\":1781788622700}],\"lobbyCode\":\"VKYE2j0xlA\"}}', '2026-06-18 13:17:06'),
(106, 4, 1, 20.00, 4, 4, 12, 17, 14, '{\"total_questions\":20,\"correct_count\":4,\"incorrect_count\":4,\"unanswered_count\":12,\"accuracy_rate\":20,\"score\":17,\"mabhas_stats\":{\"فصل یک یازدهم\":{\"correct\":2,\"incorrect\":3,\"unanswered\":5,\"total\":10},\"فصل دو یازدهم\":{\"correct\":2,\"incorrect\":1,\"unanswered\":7,\"total\":10}}}', '{\"evaluation\":{\"7633\":{\"correct_option_id\":46107,\"descriptive_answer\":{\"text\":\"گام اول: اندازه میدان الکتریکی یکنواخت بین صفحه‌ها را به دست می‌آوریم:\\r\\n\\r\\n$E = \\\\Delta V / d = 160 / 32 \\\\times 10^{-2} = 500 N/C$\\r\\n\\r\\nگام دوم: به ذره فقط نیروی الکتریکی وارد می‌شود؛ بنابراین تغییر انرژی مکانیکی آن برابر صفر است. به کمک رابطه زیر محاسبه می‌کنیم که ذره پس از طی چه مسافتی متوقف می‌شود (تندی‌اش به صفر می‌رسد):\\r\\n\\r\\n$\\\\Delta U_E = -\\\\Delta K \\\\Rightarrow -|q|Ed\\\\cos\\\\theta = -(0 - K_1) \\\\rightarrow \\\\theta = 180^{\\\\circ} \\\\rightarrow \\\\cos 180^{\\\\circ} = -1 \\\\rightarrow$\\r\\n\\r\\n$\\\\Rightarrow |q|Ed = K_1 \\\\Rightarrow 4 \\\\times 10^{-3} \\\\times 500 \\\\times d = 1/2 \\\\times 2 \\\\times 10^{-3} \\\\times (20)^2 \\\\Rightarrow d = 400 / 2000 = 1/5 m \\\\Rightarrow d = 20 cm$\\r\\n\\r\\nبنابراین ذره پس از طی مسافت $20 cm$ از نقطه $A$، متوقف شده و برمی‌گردد؛ یعنی در فاصله $32 - 20 = 12 cm$ از صفحه مثبت.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":46104,\"is_answered\":true},\"7645\":{\"correct_option_id\":46057,\"descriptive_answer\":{\"text\":\"پاسخ تشریحی گام اول: با توجه به سری الکتریسیته مالشی (تریبوالکتریک) که بخشی از آن در صورت سؤال آمده است، میله برنجی که در بخش پایین‌تری نسبت به موی انسان قرار دارد در اثر مالش، بار منفی پیدا می‌کند؛ پس $1$ و $3$ نادرست هستند. نکته $1$ نیز دلیل دیگری برای نادرست‌بودن $3$ است.\\r\\n\\r\\nگام دوم: با توجه به نکته $2$، این الکتروسکوپ چون بار منفی دارد، در صورتی ورقه‌های آن می‌توانند بسته و مجدداً باز شوند که بار میله برنجی مثبت باشد؛ پس $4$ نیز نادرست است.\\r\\n\\r\\nگام سوم: میله برنجی با بار منفی‌ای که دارد، الکترون‌های بیشتری را به سمت ورقه‌های الکتروسکوپ هدایت می‌کند و در نتیجه رانش الکتریکی بین ورقه‌ها بیشتر شده و از هم بازتر می‌شوند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":46057,\"is_answered\":true},\"7672\":{\"correct_option_id\":45949,\"descriptive_answer\":{\"text\":\"$13$ - گزینه «$2$» (مهدی براتی) چون اندازه هریک از بارهای $q1$ تا $q4$ و فاصله آنها تا مرکز مربع یکسان است، اندازه میدان الکتریکی هریک از این بارها در مرکز مربع یکسان و برابر با نصف اندازه میدان الکتریکی بار $q5$ است. $(|E1| = |E2| = |E3| = |E4| = |E5|/2)$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":45948,\"is_answered\":true},\"7680\":{\"correct_option_id\":45908,\"descriptive_answer\":{\"text\":\"$21$ - گزینه «$1$» (سیده ملیحه میرصالحی) برای پاسخ دادن به این سؤال گزینه ها را بررسی می کنیم: گزینه «$1$»: با کاهش مساحت صفحات خازن، طبق رابطه $C = \\\\kappa\\\\varepsilon_0 A/d$ ، ظرفیت خازن نیز کاهش می یابد، درنتیجه چون $V$ ثابت است، بنابه رابطه $U = 1/2 CV^2$ ، انرژی خازن نیز کاهش خواهد یافت. گزینه های «$2$» و «$3$»: بنا به رابطه $C = \\\\kappa\\\\varepsilon_0 A/d$ ، با کاهش فاصله بین صفحات خازن و یا قرار دادن دی الکتریک بین صفحات، ظرفیت خازن افزایش می یابد. درنتیجه، چون $V$ ثابت است، طبق رابطه $U = 1/2 CV^2$ ، انرژی خازن نیز افزایش خواهد یافت. گزینه «$4$»: با جداکردن خازن از مولد، بار الکتریکی آن ثابت می ماند، درنتیجه طبق رابطه $U = Q^2/2C$ ، چون $Q$ و $C$ ثابت اند، انرژی خازن نیز ثابت خواهد ماند. (الکتریسیته ساکن) (فیزیک $2$، صفحه های $28$ تا $34$)\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":45911,\"is_answered\":true},\"7724\":{\"correct_option_id\":45653,\"descriptive_answer\":{\"text\":\"65- گزینه «2» (مهدی براتی) با توجه به این‌که دو بار الکتریکی $q_1$ و $q_2$ هم‌نام هستند، مطابق شکل زیر، نقطه $A$ بین آن‌ها و نزدیک‌تر به بار با اندازه کوچک‌تر ($q_2$) قرار دارد؛ در این نقطه $\\\\vec{E}_1$ و $\\\\vec{E}_2$ هم‌اندازه و در سوی مخالف‌اند. بنابراین ابتدا فاصله نقطه $A$ از بار $q_1$ را می‌یابیم: $r_1 = x$ $r_2 = 18 - x$ $q_1 = -8\\\\mu C$ $A$ $q_2 = -2\\\\mu C$ $|\\\\vec{E}_1| = |\\\\vec{E}_2| \\\\Rightarrow k |q_1| / r_1^2 = k |q_2| / r_2^2 \\\\Rightarrow 8 / x^2 = 2 / (18 - x)^2$ $\\\\Rightarrow x^2 / (18 - x)^2 = 8 / 2 = 4 \\\\rightarrow$ جذر می‌گیریم $\\\\rightarrow x / (18 - x) = 2$ $\\\\Rightarrow 36 - 2x = x \\\\Rightarrow x = 12cm$ اکنون باید میدان الکتریکی بار $q_3 = 24\\\\mu C$ را (که در نقطه $A$ قرار دارد) در نقطه‌ای که فاصله آن از بار $12cm$ است، به‌دست آوریم و آن را برحسب بردار یکه بنویسیم. دقت کنید چون $q_3 > 0$ است، جهت میدان الکتریکی آن در محل $q_1$ در خلاف جهت محور $x$ است. $|\\\\vec{E}_3| = k |q_3| / r_3^2 \\\\rightarrow r_3 = 12 \\\\times 10^{-2}m , |q_3| = 24 \\\\times 10^{-6}C \\\\rightarrow |\\\\vec{E}| = 9 \\\\times 10^9 \\\\times 24 \\\\times 10^{-6} / (12 \\\\times 10^{-2})^2$ $= 1.5 \\\\times 10^7 N/C \\\\Rightarrow \\\\vec{E} = -1.5 \\\\times 10^7 \\\\vec{i} (N/C)$ (الکتریسیته ساکن) (فیزیک 2، صفحه‌های 10 تا 16)\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":45653,\"is_answered\":true},\"7775\":{\"correct_option_id\":45213,\"descriptive_answer\":{\"text\":\"$116$- گزینه «$2$» (پوریا علاقه‌مند) ابتدا با استفاده از رابطۀ زیر، $WE$ را می‌یابیم و سپس $ΔU$ را پیدا می‌کنیم: $ΔV = VB - VA = 100 - (-100) = 200V$ $ΔV = ΔU / q -> q=4μC=4×10-6C , ΔV=200V -> 200 = ΔU / 4×10-6$ $=> ΔU = 8×10-4 J$ $WE = -ΔU = -8×10-4 J$ (الکتریسیتۀ ساکن) (فیزیک $2$، صفحه‌های $20$ تا $23$)\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7816\":{\"correct_option_id\":44855,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\r\\n\\r\\nبا برداشتن $1\\\\mu C$ از بار $q_{1}$ و افزودن آن به بار $q_{2}$، با توجه به مقادیر بارها، نیروی الکتریکی بین دو بار $q_{1}$ و $q_{2}$ تغییر نمی‌کند، ولی نیروی وارد از طرف $q_{3}$ بر $q_{2}$ افزایش می‌یابد. به این ترتیب، نیروی الکتریکی خالص وارد بر $q_{2}$ در ابتدا باید به طرف راست باشد. شکل‌های زیر، قبل و بعد از تغییر را نشان داده‌اند.\\r\\n\\r\\n$F_{T_{1}} = F_{1,2} - F_{3,2}$ (رابطه 1)\\r\\n\\r\\n$F_{T_{2}} = F_{3,2\'} - F_{1,2\'}$ (رابطه 2)\\r\\n\\r\\nبا توجه به اینکه حاصل‌ضرب بارها در حالت اول و دوم برابر است ($5\\\\times 4 = 4\\\\times 5$)، پس $F_{1,2} = F_{1,2\'}$.\\r\\n\\r\\nاز روابط (1) و (2) نتیجه می‌گیریم:\\r\\n\\r\\n$F_{T_{1}} = F_{T_{2}} = F$\\r\\n\\r\\n$k\\\\frac{5\\\\times 4\\\\times 10^{-12}}{1^{2}} - k\\\\frac{q_{3}\\\\times 4\\\\times 10^{-12}}{3^{2}} = k\\\\frac{q_{3}\\\\times 5\\\\times 10^{-12}}{3^{2}} - k\\\\frac{4\\\\times 5\\\\times 10^{-12}}{1^{2}}$\\r\\n\\r\\n$\\\\Rightarrow 20 - \\\\frac{4}{9}q_{3} = \\\\frac{5}{9}q_{3} - 20 \\\\Rightarrow q_{3} = 40\\\\mu C$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7836\":{\"correct_option_id\":44710,\"descriptive_answer\":{\"text\":\"33- پاسخ: گزینه 3\\r\\n\\r\\n\\r\\n\\r\\n$q_1 = +4 \\\\mu C$\\r\\n\\r\\n$q_2 = -4 \\\\mu C$\\r\\n\\r\\n\\r\\n\\r\\n$E = \\\\frac{k|q|}{r^2} \\\\Rightarrow$\\r\\n\\r\\n$E_A = E_{1A} + E_{2A} = k(\\\\frac{4 \\\\times 10^{-6}}{r^2} + \\\\frac{4 \\\\times 10^{-6}}{r^2}) = k \\\\times 2 \\\\times 10^{-6}$\\r\\n\\r\\n$E_B = E_{2B} - E_{1B} = k(\\\\frac{4 \\\\times 10^{-6}}{r^2} - \\\\frac{4 \\\\times 10^{-6}}{9r^2}) = k \\\\times \\\\frac{8}{9} \\\\times 10^{-6}$\\r\\n\\r\\n$\\\\Rightarrow \\\\frac{E_A}{E_B} = \\\\frac{2}{8/9} = \\\\frac{9}{4}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7839\":{\"correct_option_id\":44692,\"descriptive_answer\":{\"text\":\"36- پاسخ: گزینه 1\\r\\n\\r\\n\\r\\n\\r\\nنیروی وارد بر بار منفی از طرف میدان الکتریکی در خلاف جهت میدان است و چون بار در ابتدا ساکن بوده، میدان، بار را در جهت نیرو (در خلاف جهت میدان) حرکت می‌دهد.\\r\\n\\r\\n\\r\\n\\r\\n$W_E = |q|Ed\\\\cos\\\\theta = (10^{-9})(5 \\\\times 10^5)(d)\\\\cos0^\\\\circ \\\\Rightarrow W_E = 5 \\\\times 10^{-4} \\\\times d$\\r\\n\\r\\n$W_E = \\\\Delta K = \\\\frac{1}{2}mv^2 - \\\\frac{1}{2}mv_0^2 \\\\Rightarrow 5 \\\\times 10^{-4} \\\\times d = \\\\frac{1}{2} \\\\times 0/01 \\\\times 10^{-3} \\\\times 10^2 - 0 \\\\Rightarrow d = 1m$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7843\":{\"correct_option_id\":44668,\"descriptive_answer\":{\"text\":\"40- پاسخ: گزینه 1\\r\\n\\r\\n\\r\\n\\r\\n$\\\\begin{cases} U = \\\\frac{1}{2}CV^2 \\\\\\\\ \\\\\\\\ C = \\\\varepsilon_\\\\circ \\\\frac{A}{d} \\\\\\\\ \\\\\\\\ V = Ed \\\\end{cases} \\\\Rightarrow U = \\\\frac{1}{2}(\\\\varepsilon_\\\\circ \\\\frac{A}{d})(Ed)^2 \\\\Rightarrow U = \\\\frac{1}{2} \\\\varepsilon_\\\\circ E^2 \\\\cdot Ad$\\r\\n\\r\\n\\r\\n\\r\\n$\\\\Rightarrow 4/5 \\\\times 10^{-6} = \\\\frac{1}{2} \\\\times 9 \\\\times 10^{-12} \\\\times (5 \\\\times 10^5)^2 \\\\times 40 \\\\times 10^{-4} \\\\times d \\\\Rightarrow d = 0/001 m = 1 mm$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7872\":{\"correct_option_id\":44599,\"descriptive_answer\":{\"text\":\"گام اول: انرژی گرفته شده یا داده شده به مدار را از نقطه $A$ تا $B$ به دست می آوریم:\\r\\n\\r\\n$\\\\Delta U_{AB} = q \\\\times \\\\Delta V_{AB} = I \\\\times \\\\Delta t \\\\times \\\\Delta V_{AB} = 2\\\\times 60 \\\\times (10-(-20)) = 3600 J = 3/6 kJ$\\r\\n\\r\\nمثبت شدن $\\\\Delta U$ نشان میدهد که این قسمت به مدار انرژی میدهد.\\r\\n\\r\\nگام دوم: مدار در مدت یک دقیقه مجموعا $ 3/6 kJ$ آن توسط وسیله الکتریکی (1) تامین میشود. بنابراین وسیله الکتریکی (2) در این مدت، $ 0/6 kJ$ انرژی به مدار میدهد\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7910\":{\"correct_option_id\":44241,\"descriptive_answer\":{\"text\":\"$1$ - گزینه «$2$» بررسی گزینه‌های نادرست: گزینه «$1$»: جریان الکتریکی عبوری از سیم در جهت میدان الکتریکی درون سیم است. گزینه «$3$»: جهت بردار سرعت سوق در یک رسانای فلزی در حضور میدان الکتریکی درخلاف جهت میدان الکتریکی و خلاف جهت جریان الکتریکی در رسانا است. گزینه «$4$»: در صورتی‌که اختلاف پتانسیل ثابتی به دو سر یک سیم اعمال کنیم جریان الکتریکی ایجاد می‌شود و یک شارش خالص بار از هر مقطع رخ می‌دهد.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7917\":{\"correct_option_id\":44213,\"descriptive_answer\":{\"text\":\"$8$ - گزینه «$2$» در حالت اول مقاومت معادل برابر $Req = 3R$ است و توان مصرفی مجموعه برابر است با: $P = V^2 / Req = V^2 / 3R -> P=20W -> 20 = V^2 / 3R => V^2 / R = 60W$ در حالت دوم با توجه به این‌که $3$ مقاومت به‌طور موازی به یکدیگر وصل شده‌اند، مقاومت معادل آن‌ها برابر با $Req = R / 3$ است و در نتیجه توان مصرفی آن‌ها برابر است با: $P = V^2 / Req = V^2 / R/3 = 3 V^2 / R => P = 3 × 60 = 180W$ (جریان الکتریکی و مدارهای جریان مستقیم) (فیزیک $2$، صفحه‌های $53$ تا $55$)\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7932\":{\"correct_option_id\":44152,\"descriptive_answer\":{\"text\":\"$23$ - گزینه «$1$» می دانیم مقاومت رئوستا بین صفر تا بی نهایت تغییر می کند. بنابراین ابتدا حداکثر و حداقل مقاومت معادل مدار را می یابیم. برای مقاومت های موازی $1\\\\Omega$ و رئوستا ($R$) داریم: $1 / R\' = 1 / 1 + 1 / R \\\\Rightarrow$ $R = 0 \\\\Rightarrow 1 / R\' = 1 + 1 / 0 \\\\Rightarrow 1 / R\' = 1 + \\\\infty \\\\Rightarrow R\' = 1 / 1+\\\\infty = 0$ $R = \\\\infty \\\\Rightarrow 1 / R\' = 1 + 1 / \\\\infty \\\\Rightarrow 1 / R\' = 1 + 0 \\\\Rightarrow R\' = 1\\\\Omega$ $R_{eq(min)} = 0 + 2 = 2\\\\Omega$ , $R_{eq(max)} = 1 + 2 = 3\\\\Omega$ می بینیم مقاومت معادل مدار می تواند از حداقل $2\\\\Omega$ به حداکثر $3\\\\Omega$ برسد. با توجه به این که وقتی مقاومت معادل مدار برابر مقاومت درونی باتری می شود، توان خروجی باتری به بیشینه مقدار خود می رسد، لذا، با افزایش مقاومت رئوستا، مقاومت معادل مدار نیز افزایش می یابد و حداکثر به $R_{eq} = r = 3\\\\Omega$ می رسد. بنابراین توان خروجی مولد پیوسته افزایش می یابد. اگر به نمودار توان خروجی مولد برحسب مقاومت معادل مدار که در بالا رسم شده است دقت کنید، نشان می دهد با افزایش مقاومت معادل از $2\\\\Omega$ به $3\\\\Omega$ توان خروجی باتری نیز افزایش می یابد. دقت کنید، چون مقاومت رئوستا به حداکثر مقدار خود می رسد، لذا مقاومت معادل نمی تواند از $3\\\\Omega$ بیشتر شود. در صورتی که مقاومت معادل از حداقل $2\\\\Omega$ به حداکثر، بیشتر از $3\\\\Omega$ می رسید، توان خروجی باتری، ابتدا افزایش و سپس کاهش می یافت.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7942\":{\"correct_option_id\":44115,\"descriptive_answer\":{\"text\":\"$33$ - گزینه «$4$» چون حجم سیم ثابت است، بنا به رابطه $V = AL$ ، وقتی طول سیم $n$ برابر شود، سطح مقطع $1/n$ برابر خواهد شد. بنابراین داریم: $R2 / R1 = (ρ2 × L2 × A1) / (ρ1 × L1 × A2)$ → $ρ2=ρ1 , L2=nL1$ / $A2=1/n A1$ → $R2 / R1 = 1 × (nL1 / L1) × (A1 / (A1/n))$ ⇒ $R2 / R1 = n^2$ یا می توان گفت، چون حجم سیم ثابت است، داریم: $R2 / R1 = (L2 / L1)^2$ → $L2=nL1$ → $R2 / R1 = (nL1 / L1)^2$ ⇒ $R2 / R1 = n^2$ از طرف دیگر، با توجه به نمودار، به ازای اختلاف پتانسیل $V1$ جریان $I1 = 24A$ و جریان $I2 = 96A$ است. بنابراین داریم: $V = R1 I1 = R2 I2$ ⇒ $R2 / R1 = I1 / I2$ → $R2/R1=n^2$ → $n^2 = 24 / 96 = 1 / 4$ ⇒ $n = 1 / 2$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7979\":{\"correct_option_id\":43966,\"descriptive_answer\":{\"text\":\"70 - گزینه «3»  ابتدا نسبت $RB / RA$ را می‌یابیم. با توجه به نمودار به ازای اختلاف پتانسیل یکسان $V$، جریان الکتریکی مقاومت A برابر $IA = 2A$ و جریان الکتریکی مقاومت B برابر $IB = 4A$ است. بنابراین، با استفاده از قانون اهم می‌توان نوشت: $VA = VB = V => RAIA = RBIB => RA×2 = RB×4$ $=> RB / RA = 2 / 4 = 1 / 2$ اکنون با استفاده از رابطة $R = ρ L / A$ و با توجه به این‌که $A = π D^2 / 4$ است، می‌توان نوشت: $R = ρ L / A = ρ L / π D^2 / 4 => RB / RA = ρB / ρA × LB / LA × (DA / DB)^2 -> ρB=ρA , LA=4LB ->$ $1 / 2 = 1× LB / 4LB × (DA / DB)^2 => (DA / DB)^2 = 2 => DA / DB = √2$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43965,\"is_answered\":true},\"8049\":{\"correct_option_id\":43681,\"descriptive_answer\":{\"text\":\"140- گزینه «2» با افزایش مقاومت R2 ، مقاومت معادل مدار نیز افزایش می یابد و جریان کل مدار یعنی عددی که آمپرسنج نمایش می دهد کاهش می یابد، پس طبق رابطه ی $V = ε - rI$ ، اختلاف پتانسیل دو سر مولد افزایش می یابد، ولی با کاهش جریان، اختلاف پتانسیل دو سر مقاومت R1 طبق رابطه ی $V1 = R1I$ کاهش می یابد، بنابراین اختلاف پتانسیل دو سر بقیه ی مدار، یعنی عددی که ولت سنج نمایش می دهد، افزایش خواهد یافت.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8069\":{\"correct_option_id\":43534,\"descriptive_answer\":{\"text\":\"خوانده آمپرسنج با جریان عبوری از مقاومت $R_4$ برابر است. مقاومت $R_1$ با مقاومت $R_2$ موازی است و معادل آن‌ها با مقاومت $R_3$ متوالی است و معادل این سه مقاومت نیز با مقاومت $R_4$ موازی است.\\r\\n\\r\\n$R_{1,2} = 10 × 10 / 10 + 10 = 5 Ω$\\r\\n\\r\\n$R_{1,2,3} = 5 + 10 = 15 Ω$\\r\\n\\r\\n$R_{eq} = 15 × 10 / 15 + 10 = 6 Ω$\\r\\n\\r\\n$I = E / R_{eq} + r ⇒ I = 40 / 6 + 2 = 5 A$\\r\\n\\r\\n$V$ باتری $ = E - rI ⇒ V$ باتری $ = 40 - 2 × 5 = 30 V$\\r\\n\\r\\nولتاژ دو سر مقاومت $R_4$ با ولتاژ دو سر باتری برابر است.\\r\\n\\r\\n$V_4 = R_4 I_4 ⇒ 30 = 10 I_4 ⇒ I_4 = 3 A$\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43534,\"is_answered\":true},\"8084\":{\"correct_option_id\":43473,\"descriptive_answer\":{\"text\":\"$R = V / I => 400 = 80 / I => I = 0/2A$\\r\\n\\r\\n$I = Δq / Δt => 0/2 = Δq / 9 => Δq = 1/8C$\\r\\n\\r\\n$Δq = 1/8C = 1/8 A s = 1/8 A s x 1h / 3600s = 0/5 x 10 -3 A h = 0/5 m A h$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8101\":{\"correct_option_id\":43398,\"descriptive_answer\":{\"text\":\"چون ولت‌سنج آرمانی است، جریانی از شاخه شامل ولت‌سنج عبور نمی‌کند، بنابراین سه مقاومت $R_2$ ، $R_1$ و $R_3$ متوالی خواهند بود. از طرفی آمپرسنج آرمانی است، پس جریانی از مقاومت 3 اهمی عبور نمی‌کند (اتصال کوتاه)؛ بنابراین مدار به صورت روبه‌رو ساده می‌شود.\\r\\n\\r\\n$R_eq=R_1+R_2+R_3=2+5+1=8Ω$\\r\\n\\r\\n$I=ε/(R_eq+r)=18/(8+1)=2A$ آمپرسنج $2A$ را نشان می‌دهد. $⇒$\\r\\n\\r\\nولت‌سنج $14V$ را نشان می‌دهد. $⇒ V_B-V_A=R_1,2×I=7×2=14V$\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":43398,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"7633\":46104,\"7645\":46057,\"7672\":45948,\"7680\":45911,\"7724\":45653,\"7979\":43965,\"8069\":43534,\"8101\":43398},\"submittedQuestionIds\":[7724,7633,8069,7979,7645,7680,7672,8101,7775,8084,7816,7942,7843,7910,7839,7872,7836,7917,7932,8049],\"totalTimeSpent\":14,\"questionTimes\":{\"7633\":1014,\"7645\":1002,\"7672\":1014,\"7680\":1004,\"7724\":1681,\"7979\":1001,\"8069\":1001,\"8101\":1001},\"selectionLog\":[{\"questionId\":7724,\"optionId\":45653,\"timeSpentMs\":1681,\"timestamp\":1781788762317},{\"questionId\":7633,\"optionId\":46104,\"timeSpentMs\":1014,\"timestamp\":1781788763669},{\"questionId\":8069,\"optionId\":43534,\"timeSpentMs\":1001,\"timestamp\":1781788764965},{\"questionId\":7979,\"optionId\":43965,\"timeSpentMs\":1001,\"timestamp\":1781788766134},{\"questionId\":7645,\"optionId\":46057,\"timeSpentMs\":1002,\"timestamp\":1781788767763},{\"questionId\":7680,\"optionId\":45911,\"timeSpentMs\":1004,\"timestamp\":1781788769220},{\"questionId\":7672,\"optionId\":45948,\"timeSpentMs\":1014,\"timestamp\":1781788770293},{\"questionId\":8101,\"optionId\":43398,\"timeSpentMs\":1001,\"timestamp\":1781788771475}]}}', '2026-06-18 13:19:33'),
(107, 5, 1, 11.11, 1, 8, 0, 0, 85, '{\"total_questions\":9,\"correct_count\":1,\"incorrect_count\":8,\"unanswered_count\":0,\"accuracy_rate\":11.11,\"score\":0,\"mabhas_stats\":{\"شش دوازدهم\":{\"correct\":0,\"incorrect\":3,\"unanswered\":0,\"total\":3},\"هفت دوازدهم\":{\"correct\":1,\"incorrect\":1,\"unanswered\":0,\"total\":2},\"چهار دوازدهم\":{\"correct\":0,\"incorrect\":2,\"unanswered\":0,\"total\":2},\"سه دوازدهم\":{\"correct\":0,\"incorrect\":2,\"unanswered\":0,\"total\":2}}}', '{\"evaluation\":{\"925\":{\"correct_option_id\":6516,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; گویچه قرمز بالغ (کوچک ترین و فراوان ترین یاخته های موجود در خون)، فاقد هسته و دنای خطی بوده و در نتیجه، فاقد توانایی رونویسی از ژن(های) مربوط به گروه خونی هستند. بررسی سایر گزینه ها: 1) این مورد فقط در خصوص گروه خونی AB صادق است. در حالی که فرد می تواند AO و یا BO باشد که در این صورت فقط یکی از این دو کربوهیدرات را در سطح یاخته های خود دارد. 2) اگر این فرد از نظر Rh، ژنوتیپی ناخالص داشته باشد، ممکن است پدری با ژنوتیپ dd و مادری با ژنوتیپ Dd یا DD داشته باشد که در هر دو حالت، این فرد حداقل یک الل D دارد. 3) اگر این فرد از نظر گروه خونی Rh، به صورت خالص (DD) باشد، دگره مربوط به ژن D را بر روی هر دو کروموزوم شماره ۱ خود جای داده است. کروموزوم های شماره ۱ در هر دو جنس، بزرگ ترین کروموزوم هستند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"سه دوازدهم\",\"selected_option_id\":6515,\"is_answered\":true},\"1027\":{\"correct_option_id\":4507,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; گیاه آناناس نوعی گیاه CAM می باشد و در یاخته های میانبرگ خود توانایی تثبیت کربن به روش کالوین را دارد. همچنین یاخته هایی دارد که می توانند تنفس هوازی داشته باشند. موارد &laquo;ب&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. الف) نادرست؛ پذیرنده نهایی در زنجیره انتقال الکترون دوم در غشای تیلاکوئید محصولی از چرخۀ کالوین است؛ یعنی \\\\(NADP^+\\\\) ؛ دقت داشته باشید که این ترکیب با دریافت الکترون های زنجیره انتقال الکترون دچار کاهش نه (اکسایش!) می شود. ب) درست؛ مولکول اکسیژن تولید شده طی تجزیه نوری آب در تیلاکوئید، می تواند از آن خارج شود که پس از خروج، می تواند در میتوکندری به عنوان پذیرنده نهایی الکترون در زنجیره انتقال الکترون مصرف شود. این زنجیره به دلیل ایجاد شیب H+ لازم برای فعالیت آنزیم ATP ساز در تولید اکسایشی ATP در راکیزه نقش دارد. ج) درست؛ مولکول ADP در طی چرخۀ کالوین تولید می شود. این مولکول می تواند ضمن جابه جایی یون های هیدروژن از فضای بین دو غشای میتوکندری به بخش داخلی راکیزه، توسط آنزیم ATP ساز مصرف شود تا ATP تولید شود. د) نادرست؛ محصولات فرایند اکسایش پیرووات شامل NADH، کربن دی اکسید و استیل کوآنزیم A هستند. در حالی که به منظور تولید قند سه کربنی از اسید سه کربنی در طی چرخۀ کالوین، NADPH و ATP مورد استفاده قرار می گیرند. طی کالوین NADPH اکسایش می یابد نه NADH.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":4508,\"is_answered\":true},\"1045\":{\"correct_option_id\":4434,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. بررسی همه موارد الف) تبدیل دیسک حلقوی باکتری به دنای خطی، می تواند به کمک برش در جایگاه تشخیص آنزیم توسط آنزیم برش دهنده صورت بگیرد. آنزیم برش دهنده، در جایگاه تشخیص خود، پیوندهای فسفودی استر (نوعی پیوند اشتراکی) خاصی را بین نوکلئوتیدهای موجود در هر رشته از این جایگاه برش می دهد؛ اما شکسته شدن پیوندهای هیدروژنی بین دو رشته دنا در منطقه تشخیص، بدون دخالت آنزیم رخ می دهد. ب) در هر جایگاه تشخیص، تعداد نوکلئوتیدهای پورین دار و پیریمیدین دار برابر (هر کدام پنج نوکلئوتید) است، زیرا در ساختار دنا در مقابل هر باز آلی تک حلقه ای، یک باز آلی دو حلقه ای قرار گرفته است. در هر نوکلئوتید پورین دار، سه حلقه آلی و در هر نوکلئوتید پیریمیدین دار دو حلقه آلی دیده می شود. بنابراین حداکثر ۲۵ حلقه آلی در ساختار توالی دنای قرار گرفته در جایگاه تشخیص قابل مشاهده است. ج) آنزیم برش دهنده، با برش در دنا، می تواند در هر سمت، انتهای چسبنده ایجاد کند. انتهاهای چسبنده تک رشته ای هستند. طی تشکیل دنای نوترکیب، بعد از این که ژن خارجی دارای انتهای چسبنده مشابه با ناقل، به دلیل رابطه مکملی در کنار هم قرار گرفتند (تشکیل پیوندهای هیدروژنی) پیوند فسفودی استر (اتصال ژن خارجی به ناقل) با کمک تشکیل پیوند فسفودی استر توسط لیگاز رخ می دهد. دقت کنید اتصال دو انتهای چسبنده به هم، توسط پیوندهای هیدروژنی صورت می گیرد که برای تشکیل به لیگاز نیاز ندارند. لیگاز دو سر ژن را به دنای ناقل وصل می کند نه دو انتهای چسبنده را به هم. د) تعداد نوکلئوتیدهای انتهای چسبنده حتما عددی زوج است این تعداد نمی تواند عدد پنج باشد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"هفت دوازدهم\",\"selected_option_id\":4436,\"is_answered\":true},\"1056\":{\"correct_option_id\":4392,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; همه موارد به نادرستی بیان شده است. (الف) اگر جهش کوچک از نوع اضافه به گونه ای رخ دهد که توالی پایان رونویسی در بخشی جلوتر نسبت به قبل (توالی پایان رونویسی زودتر از موعد) ایجاد شود، آنگاه امکان تشکیل رنای پیک کوتاه تر وجود دارد. ب) طبق کتاب جهش دو پارتیمین به دلیل تغییری که در دنا می دهد، همانندسازی را با اختلال مواجه می کند و باعث می شود آنزیم بسپاراز نتواند کار خود را به درستی انجام دهد. این جهش با تغییر توالی نوکلئوتیدی دنا همراه نیست. ج) قبل از کدون آغاز، توالی(هایی) وجود دارد که موجب هدایت زیرواحد کوچک رناتن به سمت رنای پیک و در نتیجه شروع ترجمه می شوند. اگر جهش در این توالی ها رخ داده باشد و عملکرد آنها را مختل کرده باشد، علیرغم سالم بودن کدون آغاز، همچنان ترجمه نمی تواند انجام شود. همچنین ممکن است جهش در ساختار رنای رناتنی یا پروتئین های سازندۀ رناتن باشد و در نتیجه رنای پیک، به علت اختلال عملکرد رناتن، ترجمه نشود. د) اگر نوعی جهش باعث تبدیل یک کدون پایان به کدون پایان دیگری شود، طول رنای پیک تغییر نمی کند. همچنین دقت کنید که طول رنای پیک به محل شروع رونویسی و توالی پایان رونویسی نیز ارتباط دارد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"چهار دوازدهم\",\"selected_option_id\":4390,\"is_answered\":true},\"9293\":{\"correct_option_id\":55301,\"descriptive_answer\":{\"text\":\"سوال در مورد آنزیم روبیسکو است. افزایش دما و نور محیط، از شرایط مساعد برای وقوع تنفس نوری است. در این فرآیند، روبیسکو دارای فعالیت اکسیژنازی است.\\n\\nبررسی سایر گزینه ها :\\n\\n۱ در فعالیت کربوکسیلازی، مولکول ۶ کربنی ناپایدار و در فعالیت اکسیژنازی، مولکول ۵ کربنی ناپایدار تولید می شود.\\n\\n۲ در هر دو فعالیت این آنزیم، $ATP$ تولید نمی شود.\\n\\n۴ روبیسکو فقط در کلروپلاست فعالیت می کند!\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":55300,\"is_answered\":true},\"12334\":{\"correct_option_id\":67968,\"descriptive_answer\":{\"text\":\"اگر ژنوتیپ کیسهٔ گرده $RR$ باشد، ژنوتیپ گامت نر به‌صورت $R$ خواهد بود. همچنین با توجه به ژنوتیپ $WW$ در کلاله، ژنوتیپ یاخته تخم‌زا و یاخته دو هسته‌ای به‌ترتیب، $W$ و $WW$ است. بنابراین، ژنوتیپ درون‌دانه به‌صورت $RWW$ می‌باشد.\\n\\n$1$ دو هسته موجود در ساختار یاخته دو هسته‌ای، از تقسیم میتوز یک یاخته مشابه منشأ می‌گیرند. بنابراین، الل‌های هر دو هسته یکسان است و در ژنوتیپ یاخته دو هسته‌ای، دو الل مشابه باید وجود داشته باشد.\\n\\n$2$ یاختهٔ تخم‌زا، یاخته‌ای هاپلوئید است و در ژنوتیپ آن، فقط یک الل باید وجود داشته باشد.\\n\\n$4$ در ژنوتیپ درون‌دانه، اللی که به‌صورت تکی وجود دارد، مربوط به گامت نر است و باید در ژنوتیپ گیاه نر وجود داشته باشد. بنابراین، ژنوتیپ گامت نر به‌صورت $R$ بوده است اما گیاه نر با ژنوتیپ $WW$، نمی‌تواند گامت نر با ژنوتیپ $R$ تولید کند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"سه دوازدهم\",\"selected_option_id\":67969,\"is_answered\":true},\"12455\":{\"correct_option_id\":68453,\"descriptive_answer\":{\"text\":\"اگر این جدایی جغرافیایی بخواهد منجر به گونه‌زایی دگرمیهنی شود، در صورتی که جمعیتی که از جمعیت اصلی جدا افتاده، کوچک‌تر باشد باید اثر رانش (پدیده‌های تصادفی) را هم در افزایش تفاوت میان خزانۀ ژنی دو جمعیت در نظر گرفت.\\n\\nبررسی سایر گزینه‌ها:\\n\\nگزینۀ $1$: لزومی ندارد که این دو جمعیت دچار جدایی تولیدمثلی شده باشند! چون ممکن است هنوز از یک گونه بوده و دانه‌های گرده‌شان توسط باد، آب یا جانوران گرده‌افشان برای آمیزش موفقیت‌آمیز به جمعیت دیگر منتقل شود!\\n\\nگزینۀ $2$: ممکن است این دو جمعیت دچار گونه‌زایی دگرمیهنی نشده باشند و خزانۀ ژنی مشترک داشته باشند، به این ترتیب ممکن است هنوز توان ایجاد فرزند زیستا و زایا را با هم داشته باشند.\\n\\nگزینۀ $3$: لزومی ندارد که جدایی جغرافیایی حتماً منجر به گونه‌زایی (جدایی خزانۀ ژنی) شود.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"چهار دوازدهم\",\"selected_option_id\":68451,\"is_answered\":true},\"12757\":{\"correct_option_id\":69658,\"descriptive_answer\":{\"text\":\"باکتری نیترات‌ساز، نوعی باکتری شیمیوسنتز‌کننده است که بدون نیاز به رنگیزه‌های نوری و انرژی نور خورشید، با استفاده از انرژی واکنش‌های اکسایش، مادۀ آلی تولید می‌کند. از طرفی باکتری آمونیاک‌ساز نیز جانداری فتوسنتز‌کننده نیست و فاقد توانایی استفاده از رنگیزه‌ها برای تولید مادۀ آلی است.\\n\\nبررسی سایر موارد:\\n\\n۱) درست است که باکتری نیترات‌ساز قادر به شیمیوسنتز است و می‌تواند از انرژی واکنش‌های اکسایش برای تولید مواد آلی استفاده کنند؛ اما دقت کنید که هر یاختۀ زنده توانایی انجام واکنش‌های اکسایش و کاهش را در طی تنفس یاخته‌ای دارد.\\n\\n۳) باکتری گوگردی سبز نوعی یاختۀ فتوسنتز‌کنندۀ غیراکسیژن‌زا و باکتری نیترات‌ساز نیز نوعی یاختۀ شیمیوسنتز‌کننده است. هر دو باکتری در طی واکنش‌های آنزیمی، مواد معدنی کربن‌دار مثل کربن‌دی‌اکسید را تثبیت کرده و عدد اکسایش کربن را کاهش می‌دهند.\\n\\nدرک بهتر: عدد اکسایش کربن در مولکول کربن‌دی‌اکسید بیشترین مقدار ممکن، یعنی ۴+ است؛ بنابراین طی واکنش‌های اکسایش - کاهش، امکان ندارد که عدد اکسایش آن افزایش یابد. پس در طی این نوع واکنش‌ها مثل بعضی از واکنش‌های تثبیت کربن، باید عدد اکسایش کربن کاهش یابد.\\n\\n۴) طبق معادلۀ واکنش زیر که مربوط به فتوسنتز باکتری‌های گوگردی است، در تثبیت کربن این باکتری‌ها آب نیز تولید می‌شود؛ اما باکتری آمونیاک‌ساز اصلاً توانایی تثبیت کربن را ندارد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":69657,\"is_answered\":true},\"12869\":{\"correct_option_id\":70106,\"descriptive_answer\":{\"text\":\"مهندسی پروتئین و مهندسی بافت از علمی به نام بیوانفورماتیک بهره می‌برند. موارد «الف» و «ب» برای تکمیل عبارت مناسب است.\\n\\nبررسی همهٔ موارد:\\n\\nالف با استفاده از مهندسی ژنتیک و به کمک باکتری‌ها می‌توان زنجیره‌های پلی‌پپتیدی انسولین را ساخته و پس از جمع‌آوری، آن‌ها را در آزمایشگاه به یکدیگر متصل کرد. مهندسی ژنتیک از علم بیوانفورماتیک بهره نمی‌برد.\\n\\nزیست دام مطابق متن کتاب‌درسی، مهندسی ژنتیک از علم بیوانفورماتیک بهره نمی‌برد.\\n\\nب در مهندسی بافت می‌توان با استفاده از بافت غضروف، لالهٔ گوش و بینی را بازسازی کرد.\\n\\nج در مهندسی پروتئین می‌توان اینترفرونی را ساخت به اندازهٔ پروتئین طبیعی فعالیت ضدویروسی داشته و در مقایسه با آن پایدارتر است.\\n\\nد امروزه به کمک روش‌های زیست‌فناوری، تولید آمیلازهای مقاوم‌به‌گرما ممکن شده است. مطابق کتاب‌درسی، تولید آمیلازهای مقاوم‌به‌گرما در مهندسی بافت ارتباطی به باکتری‌های گرمادوست ندارد.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"هفت دوازدهم\",\"selected_option_id\":70106,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"925\":6515,\"1027\":4508,\"1045\":4436,\"1056\":4390,\"9293\":55300,\"12334\":67969,\"12455\":68451,\"12757\":69657,\"12869\":70106},\"totalTimeSpent\":85,\"questionTimes\":{\"925\":1004,\"1027\":1012,\"1045\":2014,\"1056\":1000,\"9293\":29000,\"12334\":1010,\"12455\":1001,\"12757\":34989,\"12869\":994},\"selectionLog\":[{\"questionId\":9293,\"optionId\":55300,\"timeSpentMs\":29000,\"timestamp\":1781789612316},{\"questionId\":12869,\"optionId\":70106,\"timeSpentMs\":994,\"timestamp\":1781789614764},{\"questionId\":1045,\"optionId\":4436,\"timeSpentMs\":2014,\"timestamp\":1781789617196},{\"questionId\":1027,\"optionId\":4508,\"timeSpentMs\":1012,\"timestamp\":1781789618837},{\"questionId\":12455,\"optionId\":68451,\"timeSpentMs\":1001,\"timestamp\":1781789620332},{\"questionId\":1056,\"optionId\":4390,\"timeSpentMs\":1000,\"timestamp\":1781789621924},{\"questionId\":925,\"optionId\":6515,\"timeSpentMs\":1004,\"timestamp\":1781789623454},{\"questionId\":12334,\"optionId\":67969,\"timeSpentMs\":1010,\"timestamp\":1781789624700},{\"questionId\":12757,\"optionId\":69657,\"timeSpentMs\":991,\"timestamp\":1781789629540}],\"lobbyCode\":\"G9yBnG6Wy6\"}}', '2026-06-18 13:34:28');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(108, 5, 3, 44.44, 4, 5, 0, 30, 114, '{\"total_questions\":9,\"correct_count\":4,\"incorrect_count\":5,\"unanswered_count\":0,\"accuracy_rate\":44.44,\"score\":30,\"mabhas_stats\":{\"شش دوازدهم\":{\"correct\":1,\"incorrect\":2,\"unanswered\":0,\"total\":3},\"هفت دوازدهم\":{\"correct\":2,\"incorrect\":0,\"unanswered\":0,\"total\":2},\"چهار دوازدهم\":{\"correct\":0,\"incorrect\":2,\"unanswered\":0,\"total\":2},\"سه دوازدهم\":{\"correct\":1,\"incorrect\":1,\"unanswered\":0,\"total\":2}}}', '{\"evaluation\":{\"925\":{\"correct_option_id\":6516,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; گویچه قرمز بالغ (کوچک ترین و فراوان ترین یاخته های موجود در خون)، فاقد هسته و دنای خطی بوده و در نتیجه، فاقد توانایی رونویسی از ژن(های) مربوط به گروه خونی هستند. بررسی سایر گزینه ها: 1) این مورد فقط در خصوص گروه خونی AB صادق است. در حالی که فرد می تواند AO و یا BO باشد که در این صورت فقط یکی از این دو کربوهیدرات را در سطح یاخته های خود دارد. 2) اگر این فرد از نظر Rh، ژنوتیپی ناخالص داشته باشد، ممکن است پدری با ژنوتیپ dd و مادری با ژنوتیپ Dd یا DD داشته باشد که در هر دو حالت، این فرد حداقل یک الل D دارد. 3) اگر این فرد از نظر گروه خونی Rh، به صورت خالص (DD) باشد، دگره مربوط به ژن D را بر روی هر دو کروموزوم شماره ۱ خود جای داده است. کروموزوم های شماره ۱ در هر دو جنس، بزرگ ترین کروموزوم هستند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"سه دوازدهم\",\"selected_option_id\":6516,\"is_answered\":true},\"1027\":{\"correct_option_id\":4507,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; گیاه آناناس نوعی گیاه CAM می باشد و در یاخته های میانبرگ خود توانایی تثبیت کربن به روش کالوین را دارد. همچنین یاخته هایی دارد که می توانند تنفس هوازی داشته باشند. موارد &laquo;ب&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. الف) نادرست؛ پذیرنده نهایی در زنجیره انتقال الکترون دوم در غشای تیلاکوئید محصولی از چرخۀ کالوین است؛ یعنی \\\\(NADP^+\\\\) ؛ دقت داشته باشید که این ترکیب با دریافت الکترون های زنجیره انتقال الکترون دچار کاهش نه (اکسایش!) می شود. ب) درست؛ مولکول اکسیژن تولید شده طی تجزیه نوری آب در تیلاکوئید، می تواند از آن خارج شود که پس از خروج، می تواند در میتوکندری به عنوان پذیرنده نهایی الکترون در زنجیره انتقال الکترون مصرف شود. این زنجیره به دلیل ایجاد شیب H+ لازم برای فعالیت آنزیم ATP ساز در تولید اکسایشی ATP در راکیزه نقش دارد. ج) درست؛ مولکول ADP در طی چرخۀ کالوین تولید می شود. این مولکول می تواند ضمن جابه جایی یون های هیدروژن از فضای بین دو غشای میتوکندری به بخش داخلی راکیزه، توسط آنزیم ATP ساز مصرف شود تا ATP تولید شود. د) نادرست؛ محصولات فرایند اکسایش پیرووات شامل NADH، کربن دی اکسید و استیل کوآنزیم A هستند. در حالی که به منظور تولید قند سه کربنی از اسید سه کربنی در طی چرخۀ کالوین، NADPH و ATP مورد استفاده قرار می گیرند. طی کالوین NADPH اکسایش می یابد نه NADH.\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":4507,\"is_answered\":true},\"1045\":{\"correct_option_id\":4434,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;د&raquo; به درستی بیان شده اند. بررسی همه موارد الف) تبدیل دیسک حلقوی باکتری به دنای خطی، می تواند به کمک برش در جایگاه تشخیص آنزیم توسط آنزیم برش دهنده صورت بگیرد. آنزیم برش دهنده، در جایگاه تشخیص خود، پیوندهای فسفودی استر (نوعی پیوند اشتراکی) خاصی را بین نوکلئوتیدهای موجود در هر رشته از این جایگاه برش می دهد؛ اما شکسته شدن پیوندهای هیدروژنی بین دو رشته دنا در منطقه تشخیص، بدون دخالت آنزیم رخ می دهد. ب) در هر جایگاه تشخیص، تعداد نوکلئوتیدهای پورین دار و پیریمیدین دار برابر (هر کدام پنج نوکلئوتید) است، زیرا در ساختار دنا در مقابل هر باز آلی تک حلقه ای، یک باز آلی دو حلقه ای قرار گرفته است. در هر نوکلئوتید پورین دار، سه حلقه آلی و در هر نوکلئوتید پیریمیدین دار دو حلقه آلی دیده می شود. بنابراین حداکثر ۲۵ حلقه آلی در ساختار توالی دنای قرار گرفته در جایگاه تشخیص قابل مشاهده است. ج) آنزیم برش دهنده، با برش در دنا، می تواند در هر سمت، انتهای چسبنده ایجاد کند. انتهاهای چسبنده تک رشته ای هستند. طی تشکیل دنای نوترکیب، بعد از این که ژن خارجی دارای انتهای چسبنده مشابه با ناقل، به دلیل رابطه مکملی در کنار هم قرار گرفتند (تشکیل پیوندهای هیدروژنی) پیوند فسفودی استر (اتصال ژن خارجی به ناقل) با کمک تشکیل پیوند فسفودی استر توسط لیگاز رخ می دهد. دقت کنید اتصال دو انتهای چسبنده به هم، توسط پیوندهای هیدروژنی صورت می گیرد که برای تشکیل به لیگاز نیاز ندارند. لیگاز دو سر ژن را به دنای ناقل وصل می کند نه دو انتهای چسبنده را به هم. د) تعداد نوکلئوتیدهای انتهای چسبنده حتما عددی زوج است این تعداد نمی تواند عدد پنج باشد.\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"هفت دوازدهم\",\"selected_option_id\":4434,\"is_answered\":true},\"1056\":{\"correct_option_id\":4392,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; همه موارد به نادرستی بیان شده است. (الف) اگر جهش کوچک از نوع اضافه به گونه ای رخ دهد که توالی پایان رونویسی در بخشی جلوتر نسبت به قبل (توالی پایان رونویسی زودتر از موعد) ایجاد شود، آنگاه امکان تشکیل رنای پیک کوتاه تر وجود دارد. ب) طبق کتاب جهش دو پارتیمین به دلیل تغییری که در دنا می دهد، همانندسازی را با اختلال مواجه می کند و باعث می شود آنزیم بسپاراز نتواند کار خود را به درستی انجام دهد. این جهش با تغییر توالی نوکلئوتیدی دنا همراه نیست. ج) قبل از کدون آغاز، توالی(هایی) وجود دارد که موجب هدایت زیرواحد کوچک رناتن به سمت رنای پیک و در نتیجه شروع ترجمه می شوند. اگر جهش در این توالی ها رخ داده باشد و عملکرد آنها را مختل کرده باشد، علیرغم سالم بودن کدون آغاز، همچنان ترجمه نمی تواند انجام شود. همچنین ممکن است جهش در ساختار رنای رناتنی یا پروتئین های سازندۀ رناتن باشد و در نتیجه رنای پیک، به علت اختلال عملکرد رناتن، ترجمه نشود. د) اگر نوعی جهش باعث تبدیل یک کدون پایان به کدون پایان دیگری شود، طول رنای پیک تغییر نمی کند. همچنین دقت کنید که طول رنای پیک به محل شروع رونویسی و توالی پایان رونویسی نیز ارتباط دارد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"چهار دوازدهم\",\"selected_option_id\":4390,\"is_answered\":true},\"9293\":{\"correct_option_id\":55301,\"descriptive_answer\":{\"text\":\"سوال در مورد آنزیم روبیسکو است. افزایش دما و نور محیط، از شرایط مساعد برای وقوع تنفس نوری است. در این فرآیند، روبیسکو دارای فعالیت اکسیژنازی است.\\n\\nبررسی سایر گزینه ها :\\n\\n۱ در فعالیت کربوکسیلازی، مولکول ۶ کربنی ناپایدار و در فعالیت اکسیژنازی، مولکول ۵ کربنی ناپایدار تولید می شود.\\n\\n۲ در هر دو فعالیت این آنزیم، $ATP$ تولید نمی شود.\\n\\n۴ روبیسکو فقط در کلروپلاست فعالیت می کند!\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":55299,\"is_answered\":true},\"12334\":{\"correct_option_id\":67968,\"descriptive_answer\":{\"text\":\"اگر ژنوتیپ کیسهٔ گرده $RR$ باشد، ژنوتیپ گامت نر به‌صورت $R$ خواهد بود. همچنین با توجه به ژنوتیپ $WW$ در کلاله، ژنوتیپ یاخته تخم‌زا و یاخته دو هسته‌ای به‌ترتیب، $W$ و $WW$ است. بنابراین، ژنوتیپ درون‌دانه به‌صورت $RWW$ می‌باشد.\\n\\n$1$ دو هسته موجود در ساختار یاخته دو هسته‌ای، از تقسیم میتوز یک یاخته مشابه منشأ می‌گیرند. بنابراین، الل‌های هر دو هسته یکسان است و در ژنوتیپ یاخته دو هسته‌ای، دو الل مشابه باید وجود داشته باشد.\\n\\n$2$ یاختهٔ تخم‌زا، یاخته‌ای هاپلوئید است و در ژنوتیپ آن، فقط یک الل باید وجود داشته باشد.\\n\\n$4$ در ژنوتیپ درون‌دانه، اللی که به‌صورت تکی وجود دارد، مربوط به گامت نر است و باید در ژنوتیپ گیاه نر وجود داشته باشد. بنابراین، ژنوتیپ گامت نر به‌صورت $R$ بوده است اما گیاه نر با ژنوتیپ $WW$، نمی‌تواند گامت نر با ژنوتیپ $R$ تولید کند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"سه دوازدهم\",\"selected_option_id\":67969,\"is_answered\":true},\"12455\":{\"correct_option_id\":68453,\"descriptive_answer\":{\"text\":\"اگر این جدایی جغرافیایی بخواهد منجر به گونه‌زایی دگرمیهنی شود، در صورتی که جمعیتی که از جمعیت اصلی جدا افتاده، کوچک‌تر باشد باید اثر رانش (پدیده‌های تصادفی) را هم در افزایش تفاوت میان خزانۀ ژنی دو جمعیت در نظر گرفت.\\n\\nبررسی سایر گزینه‌ها:\\n\\nگزینۀ $1$: لزومی ندارد که این دو جمعیت دچار جدایی تولیدمثلی شده باشند! چون ممکن است هنوز از یک گونه بوده و دانه‌های گرده‌شان توسط باد، آب یا جانوران گرده‌افشان برای آمیزش موفقیت‌آمیز به جمعیت دیگر منتقل شود!\\n\\nگزینۀ $2$: ممکن است این دو جمعیت دچار گونه‌زایی دگرمیهنی نشده باشند و خزانۀ ژنی مشترک داشته باشند، به این ترتیب ممکن است هنوز توان ایجاد فرزند زیستا و زایا را با هم داشته باشند.\\n\\nگزینۀ $3$: لزومی ندارد که جدایی جغرافیایی حتماً منجر به گونه‌زایی (جدایی خزانۀ ژنی) شود.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"چهار دوازدهم\",\"selected_option_id\":68450,\"is_answered\":true},\"12757\":{\"correct_option_id\":69658,\"descriptive_answer\":{\"text\":\"باکتری نیترات‌ساز، نوعی باکتری شیمیوسنتز‌کننده است که بدون نیاز به رنگیزه‌های نوری و انرژی نور خورشید، با استفاده از انرژی واکنش‌های اکسایش، مادۀ آلی تولید می‌کند. از طرفی باکتری آمونیاک‌ساز نیز جانداری فتوسنتز‌کننده نیست و فاقد توانایی استفاده از رنگیزه‌ها برای تولید مادۀ آلی است.\\n\\nبررسی سایر موارد:\\n\\n۱) درست است که باکتری نیترات‌ساز قادر به شیمیوسنتز است و می‌تواند از انرژی واکنش‌های اکسایش برای تولید مواد آلی استفاده کنند؛ اما دقت کنید که هر یاختۀ زنده توانایی انجام واکنش‌های اکسایش و کاهش را در طی تنفس یاخته‌ای دارد.\\n\\n۳) باکتری گوگردی سبز نوعی یاختۀ فتوسنتز‌کنندۀ غیراکسیژن‌زا و باکتری نیترات‌ساز نیز نوعی یاختۀ شیمیوسنتز‌کننده است. هر دو باکتری در طی واکنش‌های آنزیمی، مواد معدنی کربن‌دار مثل کربن‌دی‌اکسید را تثبیت کرده و عدد اکسایش کربن را کاهش می‌دهند.\\n\\nدرک بهتر: عدد اکسایش کربن در مولکول کربن‌دی‌اکسید بیشترین مقدار ممکن، یعنی ۴+ است؛ بنابراین طی واکنش‌های اکسایش - کاهش، امکان ندارد که عدد اکسایش آن افزایش یابد. پس در طی این نوع واکنش‌ها مثل بعضی از واکنش‌های تثبیت کربن، باید عدد اکسایش کربن کاهش یابد.\\n\\n۴) طبق معادلۀ واکنش زیر که مربوط به فتوسنتز باکتری‌های گوگردی است، در تثبیت کربن این باکتری‌ها آب نیز تولید می‌شود؛ اما باکتری آمونیاک‌ساز اصلاً توانایی تثبیت کربن را ندارد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":69659,\"is_answered\":true},\"12869\":{\"correct_option_id\":70106,\"descriptive_answer\":{\"text\":\"مهندسی پروتئین و مهندسی بافت از علمی به نام بیوانفورماتیک بهره می‌برند. موارد «الف» و «ب» برای تکمیل عبارت مناسب است.\\n\\nبررسی همهٔ موارد:\\n\\nالف با استفاده از مهندسی ژنتیک و به کمک باکتری‌ها می‌توان زنجیره‌های پلی‌پپتیدی انسولین را ساخته و پس از جمع‌آوری، آن‌ها را در آزمایشگاه به یکدیگر متصل کرد. مهندسی ژنتیک از علم بیوانفورماتیک بهره نمی‌برد.\\n\\nزیست دام مطابق متن کتاب‌درسی، مهندسی ژنتیک از علم بیوانفورماتیک بهره نمی‌برد.\\n\\nب در مهندسی بافت می‌توان با استفاده از بافت غضروف، لالهٔ گوش و بینی را بازسازی کرد.\\n\\nج در مهندسی پروتئین می‌توان اینترفرونی را ساخت به اندازهٔ پروتئین طبیعی فعالیت ضدویروسی داشته و در مقایسه با آن پایدارتر است.\\n\\nد امروزه به کمک روش‌های زیست‌فناوری، تولید آمیلازهای مقاوم‌به‌گرما ممکن شده است. مطابق کتاب‌درسی، تولید آمیلازهای مقاوم‌به‌گرما در مهندسی بافت ارتباطی به باکتری‌های گرمادوست ندارد.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"هفت دوازدهم\",\"selected_option_id\":70106,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"925\":6516,\"1027\":4507,\"1045\":4434,\"1056\":4390,\"9293\":55299,\"12334\":67969,\"12455\":68450,\"12757\":69659,\"12869\":70106},\"totalTimeSpent\":114,\"questionTimes\":{\"925\":2003,\"1027\":1000,\"1045\":2000,\"9293\":51997,\"12334\":33002,\"12455\":1000,\"12757\":1000,\"12869\":3001},\"selectionLog\":[{\"questionId\":9293,\"optionId\":55299,\"timeSpentMs\":15001,\"timestamp\":1781789597731},{\"questionId\":12869,\"optionId\":70106,\"timeSpentMs\":3001,\"timestamp\":1781789607289},{\"questionId\":1045,\"optionId\":4434,\"timeSpentMs\":2000,\"timestamp\":1781789649987},{\"questionId\":1027,\"optionId\":4507,\"timeSpentMs\":1000,\"timestamp\":1781789651229},{\"questionId\":12455,\"optionId\":68450,\"timeSpentMs\":1000,\"timestamp\":1781789652312},{\"questionId\":12757,\"optionId\":69659,\"timeSpentMs\":1000,\"timestamp\":1781789653811},{\"questionId\":1056,\"optionId\":4390,\"timeSpentMs\":0,\"timestamp\":1781789654728},{\"questionId\":925,\"optionId\":6516,\"timeSpentMs\":2003,\"timestamp\":1781789657003},{\"questionId\":12334,\"optionId\":67969,\"timeSpentMs\":1001,\"timestamp\":1781789658403}],\"lobbyCode\":\"G9yBnG6Wy6\"}}', '2026-06-18 13:34:56');
