(134, 35, 104, 0.00, 0, 0, 26, 0, 55, '{\"total_questions\":26,\"correct_count\":0,\"incorrect_count\":0,\"unanswered_count\":26,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"مثلثات يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"توان هاي گويا و عبارت هاي جبري\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مشتق\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مثلثات دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مجموعه ها\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"حد و پيوستگي يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"معادله و نامعادله دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"الگو و دنباله\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"هندسه دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"هندسه تحليلي يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"تابع دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مثلثات دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"تابع يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"معادله و نامعادله يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"تابع دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"كاربرد مشتق\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"احتمال دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"هندسه يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"احتمال يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"حد و پيوستگي دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"شمارش بدون شمردن\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"آمار\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"احتمال دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"نمايي و لگاريتم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"قدرمطلق و جزءصحيح\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"معادله و تابع درجه دوم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1}}}', '{\"evaluation\":{\"1083\":{\"correct_option_id\":34386,\"descriptive_answer\":{\"text\":\"گزینه ۳ درست است.\\r\\n\\r\\nبا توجه به نمودار ون $A \\\\cup B\'$ را رسم می‌کنیم:\\r\\n\\r\\n$\\\\Rightarrow P(A \\\\cup B\') + P(B - A) = 1$\\r\\n\\r\\n$\\\\Rightarrow P(B - A) = P(B) - P(A \\\\cap B) = \\\\frac{40}{100}$\\r\\n\\r\\n$\\\\Rightarrow P(A - B) = P(A) - P(A \\\\cap B) = \\\\frac{20}{100}$\\r\\n\\r\\n$\\\\Rightarrow P(B) - P(A) = \\\\frac{20}{100}$\\r\\n\\r\\n$3(1 - P(A)) = 5(1 - P(B)) \\\\Rightarrow 5P(B) - 3P(A) = 2$\\r\\n\\r\\n$\\\\Rightarrow (5 - 3)P(B) = \\\\frac{140}{100} \\\\Rightarrow P(B) = \\\\%70 \\\\Rightarrow P(A \\\\cap B) = \\\\%30$\\r\\n\\r\\n$\\\\Rightarrow P(A) = \\\\%50 \\\\Rightarrow P(A \\\\cup B) = \\\\%70 + \\\\%50 - \\\\%30 = \\\\%90$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"احتمال دهم\",\"selected_option_id\":null,\"is_answered\":false},\"1135\":{\"correct_option_id\":34683,\"descriptive_answer\":{\"text\":\"گزینه 4 درست است.\\r\\n\\r\\nدر اطراف هفت صفر تعداد 8 لانه وجود دارد.\\r\\n\\r\\nمی‌خواهیم در چهار لانه عدد 1 را قرار بدهیم که تعداد حالات برابر است با:\\r\\n\\r\\n$(8 4)=\\\\frac{8×7×6×5}{1×2×3×4}=70$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"شمارش بدون شمردن\",\"selected_option_id\":null,\"is_answered\":false},\"1199\":{\"correct_option_id\":41902,\"descriptive_answer\":{\"text\":\"گزینه 3 درست است.\\r\\n\\r\\nدر صورت و مخرج کسر عبارت $\\\\sqrt{x-1}$ را جدا می‌کنیم و ساده می‌کنیم:\\r\\n\\r\\n$\\\\lim_{x\\\\to 1^+} \\\\frac{3x\\\\sqrt{x-1} - \\\\sqrt{x-1}\\\\sqrt{x+1}(x+2)}{\\\\sqrt{x-1}\\\\sqrt{x^2+x+1}} = \\\\lim_{x\\\\to 1^+} \\\\frac{\\\\sqrt{x-1}(3x - \\\\sqrt{x+1}(x+2))}{\\\\sqrt{x-1}\\\\sqrt{x^2+x+1}} = \\\\lim_{x\\\\to 1^+} \\\\frac{3x - \\\\sqrt{x+1}(x+2)}{\\\\sqrt{x^2+x+1}}$\\r\\n\\r\\n$= \\\\frac{3 - \\\\sqrt{2} \\\\times 3}{\\\\sqrt{1+1+1}} = \\\\sqrt{3} - \\\\sqrt{6}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"حد و پيوستگي يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1240\":{\"correct_option_id\":42060,\"descriptive_answer\":{\"text\":\"گزینه ۳ درست است.\\r\\n\\r\\n$p(-1) = -2 \\\\Rightarrow a - 1 - 3 = -2 \\\\Rightarrow a = 2$\\r\\n\\r\\n$q(+1) = 0 \\\\Rightarrow b + 2 - 5 = 0 \\\\Rightarrow b = 3$\\r\\n\\r\\n$\\\\lim_{x\\\\to +\\\\infty} \\\\frac{(2x^2 + x - 3)(3x^3 + 2x - 5)}{\\\\sqrt{x^7}(\\\\sqrt{x^2 + 2x\\\\sqrt{x} + x} - \\\\sqrt{x^2 + 2x\\\\sqrt{x} - x})} \\\\sim \\\\lim_{x\\\\to +\\\\infty} \\\\frac{(2x^2)(3x^3)}{\\\\sqrt{x^7}(4x\\\\sqrt{x})} = \\\\lim_{x\\\\to +\\\\infty} \\\\frac{6x^5}{4x^5} = \\\\frac{3}{2}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"حد و پيوستگي دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1270\":{\"correct_option_id\":42146,\"descriptive_answer\":{\"text\":\"پاسخ تشریحی راه اول: گام اول: $gof$ را تشکیل می‌دهیم:\\r\\n\\r\\n$g(f(x)) = 4√1 + (f(x))^2 = 4√1 + x + 2√x = 4√(√x + 1)^2 = √√x + 1$\\r\\n\\r\\n\\r\\n\\r\\nگام دوم: مشتق می‌گیریم:\\r\\n\\r\\n$y = √√x + 1 ⇒ y\' = (√x + 1)\' / 2√√x + 1 = 1 / 2√x / 2√√x + 1$\\r\\n\\r\\n\\r\\n\\r\\nگام سوم: $x = 1$ را قرار می‌دهیم:\\r\\n\\r\\n$y\'(1) = 1 / 2 / 2√2 = 1 / 4√2 = 1 / 2^5/2 = 2^-5/2$\\r\\n\\r\\n\\r\\n\\r\\nپس:\\r\\n\\r\\n$k = -5 / 2$\\r\\n\\r\\n\\r\\n\\r\\nراه دوم: گام اول: مشتق $gof$ در $x = 1$ را به شکل ریاضی می‌نویسیم:\\r\\n\\r\\n$(gof)\'(1) = f\'(1) × g\'(f(1))$\\r\\n\\r\\nگام سوم گام چهارم\\r\\n\\r\\n\\r\\n\\r\\nگام دوم: $f\'$ و $g\'$ را حساب می‌کنیم:\\r\\n\\r\\n$f(x) = √x + 2√x$\\r\\n\\r\\n$u$\\r\\n\\r\\n$(√u)\' = u\' / 2√u$\\r\\n\\r\\n$→ f\'(x) = 1 + 2 × 1 / 2√x / 2√x + 2√x = 1 + 1 / √x / 2√x + 2√x$\\r\\n\\r\\n\\r\\n\\r\\n$g(x) = 4√1 + x^2 = (1 + x^2)^1/4$\\r\\n\\r\\n$(u^n)\' = nu^{n-1}.u\'$\\r\\n\\r\\n$→ g\'(x) = 1 / 4 (1 + x^2)^-3/4 × (2x) = x / 2 (1 + x^2)^-3/4$\\r\\n\\r\\n\\r\\n\\r\\nگام سوم: مقدار $f\'(1)$ برابر است با:\\r\\n\\r\\n$f\'(x) = 1 + 1 / √x / 2√x + 2√x ⇒ f\'(1) = 1 + 1 / 2√1 + 2 = 1 / √3$\\r\\n\\r\\n\\r\\n\\r\\nگام چهارم:\\r\\n\\r\\nمقدار $f(1)$ برابر است با:\\r\\n\\r\\n$f(x) = √x + 2√x ⇒ f(1) = √1 + 2(1) = √3$\\r\\n\\r\\nپس $g\'(f(1))$ یعنی $g\'(√3)$ که برابر است با:\\r\\n\\r\\n$g\'(x) = x / 2 (1 + x^2)^-3/4 ⇒ g\'(√3) = √3 / 2 (1 + 3)^-3/4 = √3 / 2 × (2^2)^-3/4 = √3 / 2 × 2^-3/2 = √3 / 2 × 1 / 2√2 = √3 / 4√2$\\r\\n\\r\\n\\r\\n\\r\\nگام پنجم: مقادیر به‌دست‌آمده را در عبارت گام اول جای‌گذاری می‌کنیم:\\r\\n\\r\\n$(gof)\'(1) = f\'(1) × g\'(f(1)) = 1 / √3 × √3 / 4√2 = 1 / 4√2 = 1 / 2^2 × 2^1/2 = 1 / 2^5/2 = 2^-5/2$\\r\\n\\r\\n$1 / √3$ $√3 / 4√2$\\r\\n\\r\\n\\r\\n\\r\\nپس:\\r\\n\\r\\n$k = -5 / 2$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مشتق\",\"selected_option_id\":null,\"is_answered\":false},\"1311\":{\"correct_option_id\":41735,\"descriptive_answer\":{\"text\":\"28. گزینه 4 درست است.\\r\\n\\r\\n$\\\\log_{\\\\sqrt{x}}(2x) =\\\\frac{\\\\log(2x)}{\\\\log\\\\sqrt{x}} = \\\\frac{\\\\log2+\\\\logx}{\\\\frac{1}{2}\\\\logx} =2(\\\\log_{x}2+1) = 2 \\\\frac{1}{\\\\log_{2}x} + 1) =2(\\\\frac{1}{n}+1) =\\\\frac{2n+2}{n}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"نمايي و لگاريتم\",\"selected_option_id\":null,\"is_answered\":false},\"1409\":{\"correct_option_id\":43242,\"descriptive_answer\":{\"text\":\"با فرض $t=\\\\sqrt{2}-1$\\r\\n\\r\\nداریم:\\r\\n\\r\\n$A=\\\\frac{1}{t}=\\\\sqrt{2}+1$\\r\\n\\r\\nو $B=\\\\sqrt{3}+\\\\sqrt{2}$\\r\\n\\r\\nپس:\\r\\n\\r\\n$A-B=1-\\\\sqrt{3}$\\r\\n\\r\\nجزء صحیح برابر $1-$ است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"توان هاي گويا و عبارت هاي جبري\",\"selected_option_id\":null,\"is_answered\":false},\"1646\":{\"correct_option_id\":45057,\"descriptive_answer\":{\"text\":\"فرض کنیم داده‌های اولیه برابر $a_1, a_2, ..., a_{n-1}, 15$ باشد، بزرگ‌ترین داده 20 واحد و دامنه تغییرات 24 واحد افزایش داشته است، پس کوچک‌ترین داده 4 واحد کم شده است، پس داده‌های جدید به‌صورت: $a_1 - 4, a_2, a_3, ..., 35$ می‌باشد، درنتیجه داریم:\\r\\n\\r\\n$\\\\bar{x}_{قدیم} = \\\\frac{a_1 + a_2 + ... + a_{n-1} + 15}{n}$\\r\\n\\r\\n$\\\\bar{x}_{جدید} = \\\\frac{a_1 - 4 + a_2 + ... + a_{n-1} + 35}{n}$\\r\\n\\r\\n$= \\\\frac{a_1 + a_2 + a_3 + ... + a_{n-1} + 15}{n} + \\\\frac{16}{n} = \\\\bar{x}_{قدیم} + \\\\frac{16}{n}$\\r\\n\\r\\nاما از آن جایی که در تعداد و ترتیب داده‌ها تغییری صورت نگرفته است و این میانگین است که $22 - 20 = 2$ واحد افزایش داشته، پس داریم:\\r\\n\\r\\n$\\\\bar{x}_{جدید} - \\\\bar{x}_{قدیم} = 2 \\\\Rightarrow \\\\frac{16}{n} = 2 \\\\Rightarrow n = 8$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"آمار\",\"selected_option_id\":null,\"is_answered\":false},\"1805\":{\"correct_option_id\":47896,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 1\\r\\n\\r\\nمی‌توانیم وارون تابع را بدست آوریم:\\r\\n\\r\\n$f(x) = x - 3 + 4\\\\sqrt{x - 3} + 4 - 1$\\r\\n\\r\\n$f(x) = (\\\\sqrt{x - 3} + 2)^2 - 1 \\\\Rightarrow y + 1 = (\\\\sqrt{x - 3} + 2)^2 \\\\Rightarrow \\\\pm\\\\sqrt{y + 1} = \\\\sqrt{x - 3} + 2$\\r\\n\\r\\nچون $\\\\sqrt{x - 3} + 2 > 0$ ، پس $\\\\sqrt{y + 1} = \\\\sqrt{x - 3} + 2$ قابل قبول است.\\r\\n\\r\\n$\\\\Rightarrow \\\\sqrt{y + 1} - 2 = \\\\sqrt{x - 3} \\\\Rightarrow x - 3 = (\\\\sqrt{y + 1} - 2)^2$\\r\\n\\r\\n$f^{-1}(x) = (\\\\sqrt{x + 1} - 2)^2 + 3$\\r\\n\\r\\n$f^{-1}(x) = x + 1 + 4 - 4\\\\sqrt{x + 1} + 3 = x - 4\\\\sqrt{x + 1} + 8$\\r\\n\\r\\n$\\\\Rightarrow a = -4, b = 8 \\\\Rightarrow a + b = 4$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1819\":{\"correct_option_id\":47948,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 1\\r\\n\\r\\n$\\\\log_3^{(2x - 1)} < 2 \\\\Rightarrow 0 < 2x - 1 < 3^2 \\\\Rightarrow \\\\frac{1}{2} < x < 5$ (1)\\r\\n\\r\\n$|x^2 - 5x + 2| < 2 \\\\Rightarrow -2 < x^2 - 5x + 2 < 2 \\\\Rightarrow \\\\begin{cases} x^2 - 5x + 2 < 2 \\\\to 0 < x < 5 \\\\text{ (2)} \\\\\\\\ x^2 - 5x + 2 > -2 \\\\to x > 4 \\\\text{ یا } x < 1 \\\\text{ (3)} \\\\end{cases}$\\r\\n\\r\\n$(1) \\\\cap (2) \\\\cap (3) \\\\Rightarrow \\\\frac{1}{2} < x < 1 \\\\cup 4 < x < 5 \\\\Rightarrow$ گزینه 1\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"معادله و نامعادله دهم\",\"selected_option_id\":null,\"is_answered\":false},\"1950\":{\"correct_option_id\":44526,\"descriptive_answer\":{\"text\":\"11- پاسخ: گزینه 3 ▲ مشخصات سؤال: دشوار * صفحه 45 ریاضی 2\\r\\n\\r\\nنکته: $Sin^4 α + Cos^4 α = 1 - 2Sin^2 α Cos^2 α$ , $tan α × Cot α = 1$\\r\\n\\r\\nنکته: $a^3 + b^3 = (a + b)(a^2 - ab + b^2)$\\r\\n\\r\\nابتدا داده مسئله را ساده می کنیم:\\r\\n\\r\\n$Sin^6 α + Cos^6 α = 3/4 ⇒ (Sin^2 α + Cos^2 α)(Sin^4 α - Sin^2 α Cos^2 α + Cos^4 α) = 3/4$\\r\\n\\r\\n$⇒ 1 × (1 - 2Sin^2 α Cos^2 α - Sin^2 α Cos^2 α) = 3/4 ⇒ 1 - 3Sin^2 α Cos^2 α = 3/4$\\r\\n\\r\\n$⇒ 3Sin^2 α Cos^2 α = 1/4 ⇒ Sin^2 α Cos^2 α = 1/12 ⇒ Sin α Cos α = ± 1/2√3$\\r\\n\\r\\nاکنون مقدار $tan^3 α + Cot^3 α$ را محاسبه می کنیم:\\r\\n\\r\\n$tan^3 α + Cot^3 α = Sin^3 α / Cos^3 α + Cos^3 α / Sin^3 α = Sin^6 α + Cos^6 α / Sin^3 α × Cos^3 α = 3/4 / (± 1/2√3)^3 = 3/4 / ± 1/24√3 = ± 3/4 × 24√3 = ± 18√3$\\r\\n\\r\\nاکنون با به توان دو رساندن، مقدار خواسته شده را محاسبه می کنیم:\\r\\n\\r\\n$tan^3 α + Cot^3 α = ± 18√3 ⇒ (tan^3 α + Cot^3 α)^2 = (± 18√3)^2 ⇒ tan^6 α + Cot^6 α + 2tan^3 α × Cot^3 α = 324 × 3$\\r\\n\\r\\ntan^6 α + Cot^6 α + 2 = 972 ⇒ tan^6 α + Cot^6 α = 970$$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2062\":{\"correct_option_id\":45683,\"descriptive_answer\":{\"text\":\"۲۸. گزینه ۴ درست است.\\r\\n\\r\\nسه جمله متوالی دنباله هندسی را $a$, $aq$, $aq^{۲}$ در نظر می‌گیریم. واضح است که این سه عدد در رابطه فیثاغورس صدق می‌کنند. اما دقت کنید که با توجه به این که با یک دنباله هندسی کاهشی مواجهیم، $a$ بزرگ‌ترین ضلع (وتر) بوده و طبق فیثاغورس داریم:\\r\\n\\r\\n$a^{۲} = (aq)^{۲} + (aq^{۲})^{۲} \\\\Rightarrow a^{۲} = a^{۲}q^{۲} + a^{۲}q^{۴} \\\\xrightarrow{\\\\text{تقسیم طرفین بر } a^{۲}} ۱ = q^{۲} + q^{۴}$\\r\\n\\r\\n$\\\\Rightarrow q^{۴} + q^{۲} - ۱ = ۰ \\\\xrightarrow{q^{۲} = t} t^{۲} + t - ۱ = ۰ \\\\Rightarrow t = \\\\frac{-۱ \\\\pm \\\\sqrt{۵}}{۲} \\\\Rightarrow q^{۲} = \\\\frac{-۱ \\\\pm \\\\sqrt{۵}}{۲}$\\r\\n\\r\\nچون $q^{۲}$ مقداری مثبت است، $q^{۲} = \\\\frac{-۱ + \\\\sqrt{۵}}{۲}$ قابل قبول است و از آنجا داریم:\\r\\n\\r\\n$q = \\\\pm \\\\sqrt{\\\\frac{-۱ + \\\\sqrt{۵}}{۲}}$\\r\\n\\r\\nچون $q$ مقداری مثبت است (اضلاع مثلث که نمی‌توانند منفی باشند!) $q = \\\\sqrt{\\\\frac{-۱ + \\\\sqrt{۵}}{۲}}$ قابل قبول است.\\r\\n\\r\\nحالا دقت کنید که عدد $\\\\frac{-۱ + \\\\sqrt{۵}}{۲}$ دقیقاً برعکس عدد طلایی $\\\\frac{۱ + \\\\sqrt{۵}}{۲}$ است، ببینید:\\r\\n\\r\\n$\\\\frac{۱}{\\\\frac{۱ + \\\\sqrt{۵}}{۲}} = \\\\frac{۲}{۱ + \\\\sqrt{۵}} \\\\xrightarrow{\\\\text{ضرب و تقسیم در مزدوج مخرج}} \\\\frac{۲(۱ - \\\\sqrt{۵})}{۱ - ۵} = \\\\frac{-۱ + \\\\sqrt{۵}}{۲}$\\r\\n\\r\\nپس $\\\\frac{-۱ + \\\\sqrt{۵}}{۲}$ یعنی برعکس عدد طلایی یا همان برعکس نسبت طول به عرض در مستطیل طلایی، بنابراین این عدد نسبت عرض به طول در مستطیل طلایی است و لذا $q = \\\\sqrt{\\\\frac{-۱ + \\\\sqrt{۵}}{۲}}$ یعنی جذر نسبت عرض به طول در مستطیل طلایی.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"الگو و دنباله\",\"selected_option_id\":null,\"is_answered\":false},\"2379\":{\"correct_option_id\":73018,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 3\\r\\n\\r\\nمشخصات سؤال: دشوار * صفحه 129 ریاضی 3\\r\\n\\r\\nنکته: مجموع فواصل هر نقطه از بیضی، از دو کانون آن، مقدار ثابتی است که برابر است با طول قطر بزرگ بیضی.\\r\\n\\r\\nنکته: مقدار $\\\\frac{c}{a}$ را خروج از مرکز بیضی می نامند و معمولاً آن را با حرف e نمایش می دهند.\\r\\n\\r\\nطول قطر بزرگ $(AA\')$ برابر 28 است. پس اگر طول MF را x بنامیم طول $MF\'$ برابر $28 - x$ است.\\r\\n\\r\\nمساحت مثلث $MFF\'$ برابر 96 است، پس:\\r\\n\\r\\n$\\\\frac{1}{2} MF \\\\times MF\' = 96 \\\\Rightarrow x \\\\times (28 - x) = 192 \\\\Rightarrow x^2 - 28x + 192 = 0 \\\\Rightarrow (x - 12)(x - 16) = 0 \\\\Rightarrow x = 12 \\\\text{ یا } 16$\\r\\n\\r\\nبنابراین دو ضلع مثلث $MFF\'$ برابر 12 و 16 بوده و اندازه وتر $(FF\' = 2c)$ از رابطه فیثاغورس به دست می آید:\\r\\n\\r\\n$(FF\')^2 = (MF)^2 + (MF\')^2 \\\\Rightarrow (2c)^2 = 12^2 + 16^2 \\\\Rightarrow 4c^2 = 12^2 + 16^2 \\\\Rightarrow c^2 = 6^2 + 8^2 \\\\Rightarrow c = 10$\\r\\n\\r\\nبنابراین خروج از مرکز بیضی برابر است با:\\r\\n\\r\\n$e = \\\\frac{c}{a} = \\\\frac{10}{14} = \\\\frac{5}{7}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"هندسه دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"3516\":{\"correct_option_id\":51782,\"descriptive_answer\":{\"text\":\"چون $A$ و $B$ دو مجموعه جدا از هم هستند. پس $n(A ∩ B) = 0$ و در نتیجه $n(A ∪ B) = n(A) + n(B)$ است. از طرفی $n(A)$ و $n(B)$ اعداد حسابی هستند و فقط حالت های زیر رخ می دهد.\\r\\n\\r\\n$n(B) = 8 - 3n(A)$\\r\\n\\r\\n1) $n(A) = 0 ⇒ n(B) = 8 ⇒ n(A ∪ B) = 8$\\r\\n\\r\\n2) $n(A) = 1 ⇒ n(B) = 5 ⇒ n(A ∪ B) = 6$\\r\\n\\r\\n3) $n(A) = 2 ⇒ n(B) = 2 ⇒ n(A ∪ B) = 4$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مجموعه ها\",\"selected_option_id\":null,\"is_answered\":false},\"3541\":{\"correct_option_id\":17243,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\r\\n\\r\\nنکته: اگر فرض کنیم درحالت کلی $A_1, A_2, ..., A_n$ پیشامدهایی باشند که بر روی فضای نمونه ای S یک افراز تشکیل داده اند و B یک پیشامد دلخواه باشد، رابطه زیر حاصل خواهد شد که به آن قانون احتمال کل می گوییم:\\r\\n\\r\\n$P(B) = \\\\sum_{i=1}^{n} P(B \\\\cap A_i) = \\\\sum_{i=1}^{n} P(A_i)P(B|A_i)$\\r\\n\\r\\nسکه دو طرف رو را A، سکه دو طرف پشت را B و سکه سالم یک طرف رو و یک طرف پشت را C می نامیم. حالت های مختلف در آمدن 2 سکه از این سه سکه به صورت AB و AC و BC است و احتمال هر کدام $1/3$ است.\\r\\n\\r\\n1/3 AB -> احتمال یکی رو، یکی پشت $1 * 1 = 1$\\r\\n\\r\\n1/3 AC -> احتمال یکی رو، یکی پشت $1 * 1/2 = 1/2$\\r\\n\\r\\n1/3 BC -> احتمال یکی رو، یکی پشت $1 * 1/2 = 1/2$\\r\\n\\r\\nبنابر فرمول احتمال کل، احتمال خواسته شده برابر است با:\\r\\n\\r\\n$P = 1/3 * 1 + 1/3 * 1/2 + 1/3 * 1/2 = 1/3 + 1/6 + 1/6 = 2/3$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"احتمال دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"3563\":{\"correct_option_id\":17033,\"descriptive_answer\":{\"text\":\"35 - پاسخ: گزینه 2\\r\\n\\r\\nمشخصات سؤال: دشوار * ریاضی 2 (فصل 7، درس 1)\\r\\n\\r\\nنکته: مستقل بودن A از B معادل است با اینکه: $P(A \\\\cap B) = P(A) . P(B)$\\r\\n\\r\\nنکته: برای هر دو پیشامد A و B از فضای نمونه ای S، همواره تساوی زیر برقرار است:\\r\\n\\r\\n$P(A \\\\cup B) = P(A) + P(B) - P(A \\\\cap B)$\\r\\n\\r\\nبا توجه به اطلاعات مسئله داریم:\\r\\n\\r\\n$P(A \\\\cup B) = P(A\') => P(A) + P(B) - P(A \\\\cap B) = 1 - P(A) => P(A) + P(B) - P(A)P(B) = 1 - P(A) \\\\quad (I)$\\r\\n\\r\\nمی دانیم $P(B) = 3/2 P(A)$ (اگر خواسته مسئله یعنی P(B) را x بنامیم، داریم):\\r\\n\\r\\n$x = 3/2 P(A) => P(A) = 2/3 x$\\r\\n\\r\\n$(I) => 2/3 x + x - 2/3 x \\\\times x = 1 - 2/3 x => 5/3 x - 2/3 x^2 = 1 - 2/3 x \\\\xrightarrow{\\\\times 3} 5x - 2x^2 = 3 - 2x => 2x^2 - 7x + 3 = 0$\\r\\n\\r\\n$=> x = 7 \\\\pm \\\\sqrt{49 - 24} / 2 \\\\times 2 => x = 7+5/4$ یا $x = 7-5/4 => x = 3$ یا $x = 1/2$\\r\\n\\r\\nبا توجه به اینکه x یعنی P(B) همواره عددی در بازه $[0,1]$ است، پس $x=3$ غیرقابل قبول بوده و $x = P(B) = 1/2$ می باشد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"احتمال يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"3838\":{\"correct_option_id\":18250,\"descriptive_answer\":{\"text\":\"88 - گزینه «3»\\r\\n\\r\\nابتدا به کمک روابط $sin^2 2x = 1 - cos^2 2x$ و $cos^2 x = (1 + cos 2x) / 2$ داریم:\\r\\n\\r\\n$3sin^2 2x - 8cos^2 x + 1 = 0 \\\\Rightarrow 3(1 - cos^2 2x) - 8((1 + cos 2x) / 2) + 1 = 0$\\r\\n\\r\\n$\\\\Rightarrow 3 - 3cos^2 2x - 4 - 4cos 2x + 1 = 0 \\\\Rightarrow 3cos^2 2x + 4cos 2x = 0$\\r\\n\\r\\n$\\\\Rightarrow cos 2x(3cos 2x + 4) = 0 \\\\Rightarrow$\\r\\n\\r\\n{\\r\\n\\r\\n$cos 2x = 0$\\r\\n\\r\\n$cos 2x = -4/3 \\\\times$\\r\\n\\r\\n}\\r\\n\\r\\nتوجه شود که $-1 \\\\le cos 2x \\\\le 1$ است بنابراین $cos 2x = -4/3$ غیرقابل قبول است.\\r\\n\\r\\n\\r\\n\\r\\n$cos 2x = 0 \\\\Rightarrow 2x = k\\\\pi + \\\\pi/2 \\\\Rightarrow x = k\\\\pi/2 + \\\\pi/4$\\r\\n\\r\\n\\r\\n\\r\\n| k | 0 | 1 | 2 | 3 |\\r\\n\\r\\n|---|---|---|---|---|\\r\\n\\r\\n| x | $\\\\pi/4$ | $3\\\\pi/4$ | $5\\\\pi/4$ | $7\\\\pi/4$ |\\r\\n\\r\\n\\r\\n\\r\\nمجموع جواب‌ها: $4\\\\pi$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"3947\":{\"correct_option_id\":18747,\"descriptive_answer\":{\"text\":\"با توجه به شکل زیر خط با شیب مثبت $y=3\\\\sqrt{x}+a$ است که با توجه به اینکه از مبدا مختصات می‌گذرد $a=0$ است.\\r\\n\\r\\nخط با شیب منفی نیز $y=-3\\\\sqrt{x}+b$ است.\\r\\n\\r\\n\\r\\n\\r\\n<desc>\\r\\n\\r\\nچون شیب این دو خط قرینه یکدیگر است، زاویه این دو خط با جهت مثبت محور x ها مکمل هم هستند. به عبارتی در مثلث OAB زاویه های ˆO و ˆB برابر اند و این مثلث، متساوی الساقین است. (OA = AB) . می دانیم که در هر مثلث متساوی الساقین، مجموع فواصل هر نقطه روی قاعده از دو ساق، برابر با ارتفاع نظیر ساق است، پس در اینجا ارتفاع نظیر ساق برابر با  2+3 = 5 .\\r\\n\\r\\nحالا اگر این نقطه O(0,0) را روی خط $y+\\\\sqrt{3}x-b=0$ قرار دهیم:\\r\\n\\r\\n$\\\\frac{|0+0-b|}{\\\\sqrt{1+3}}=5 \\\\Rightarrow |b|=10 \\\\Rightarrow b=\\\\pm10$\\r\\n\\r\\nبا توجه به شکل، عرض از مبدا این خط مثبت است پس $b=10$ قابل قبول است.\\r\\n\\r\\n$a+b=0+10=10$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"هندسه تحليلي يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4044\":{\"correct_option_id\":23089,\"descriptive_answer\":{\"text\":\"روش اول: بهتر است به‌جای محاسبۀ طول پاره‌خط BC، طول پاره‌خط‌های OC (واقع در مثلث قائم‌الزاویۀ OCF) را و OB (واقع در مثلث قائم‌الزاویۀ ODB) را حساب کرده و از هم کم کنیم. به شکل زیر دقت کنید (توجه کنید که زاویۀ OCF طبق قاعدۀ خطوط موازی و مورب برابر زاویۀ COD و مساوی $\\\\alpha$ است:\\r\\n\\r\\n\\r\\n\\r\\n در مثلث OCF داریم:\\r\\n\\r\\n $\\\\sin \\\\alpha = \\\\frac{OF}{OC} = \\\\frac{1}{OC} \\\\Rightarrow OC = \\\\frac{1}{\\\\sin \\\\alpha}$ در مثلث ODB داریم:\\r\\n\\r\\n $\\\\cos \\\\alpha = \\\\frac{OD}{OB} = \\\\frac{1}{OB} \\\\Rightarrow OB = \\\\frac{1}{\\\\cos \\\\alpha}$ پس:\\r\\n\\r\\n $BC = OC - OB = \\\\frac{1}{\\\\sin \\\\alpha} - \\\\frac{1}{\\\\cos \\\\alpha}$\\r\\n\\r\\n روش دوم:\\r\\n\\r\\n واضح است که اگر در حالت خاص، $\\\\alpha = 45^\\\\circ$ باشد، شکل مسئله به‌صورت زیر بوده و نقاط B و C و E برهم منطبق می‌شوند، لذا طول پاره‌خط BC برابر صفر بوده و تنها گزینه‌ای که به ازای \\r\\n\\r\\n $\\\\alpha = 45^\\\\circ$برابر صفر می‌شود، گزینۀ «3» است.\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دهم\",\"selected_option_id\":null,\"is_answered\":false},\"4118\":{\"correct_option_id\":72408,\"descriptive_answer\":{\"text\":\"برای حل نامعادله عدد 1 را به طرف دیگر برده مخرج مشترک می‌گیریم. (حواسمان باشد اجازه طرفین وسطین نداریم) $4x2 + 6x - 3 / 3x2 + 4x - 4 - 1 \\\\leq 0 \\\\Rightarrow 4x2 + 6x - 3 - 3x2 - 4x + 4 / 3x2 + 4x - 4 \\\\leq 0$ $\\\\Rightarrow x2 + 2x + 1 / 3x2 + 4x - 4 \\\\leq 0 \\\\Rightarrow (x + 1)2 / (3x - 2)(x + 2) \\\\leq 0 \\\\xrightarrow{تعیین علامت} -2 < x < 2/3$ x | -2 | -1 | 2/3 عبارت | + | ت.ن مضاعف | - | 0 | - | ت.ن | + مجموعه جواب نامعادله $\\\\Rightarrow -2 < x < 2/3$ حال کافی است این مجموعه جواب را به‌صورت یک نامعادله قدر مطلقی بنویسیم: نکته: $\\\\alpha < x < \\\\beta \\\\Rightarrow |x - \\\\frac{\\\\alpha + \\\\beta}{2}| < \\\\frac{\\\\beta - \\\\alpha}{2}$ $-2 < x < 2/3 \\\\Rightarrow |x - \\\\frac{-2 + 2/3}{2}| < \\\\frac{2/3 - (-2)}{2} \\\\Rightarrow |x + 2/3 / 2| < 4/3$ $\\\\times 3 \\\\Rightarrow |3x + 2| < 4 \\\\Rightarrow a = 2, b = 4 \\\\Rightarrow b - a = 0$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"معادله و نامعادله يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4216\":{\"correct_option_id\":72828,\"descriptive_answer\":{\"text\":\"راه اول:\\r\\n\\r\\nگام اول، معادله را استاندارد می‌نویسیم:\\r\\n\\r\\n$(x - 1)^2 + a(x - 3) - 4 = 0 \\\\Rightarrow x^2 - 2x + 1 + ax - 3a - 4 = 0 \\\\Rightarrow 1x^2 + (a - 2)x + (-3a - 3) = 0$\\r\\n\\r\\n$A$ $B$ $C$\\r\\n\\r\\nگام دوم، S و P معادله بالا را حساب می‌کنیم:\\r\\n\\r\\n$S = -B / A = -a + 2$     $P = C / A = -3a - 3$\\r\\n\\r\\nگام سوم، چون یکی از ریشه‌ها 2 برابر دیگری است، پس ریشه‌های معادله را α و 2α می‌گیریم.\\r\\n\\r\\nمجموع α و 2α همان S می‌شود:\\r\\n\\r\\n$S = α + 2α \\\\Rightarrow -a + 2 = 3α (1)$\\r\\n\\r\\nضرب α و 2α همان P می‌شود:\\r\\n\\r\\n$P = α \\\\cdot 2α \\\\Rightarrow -3a - 3 = 2α^2 (2)$\\r\\n\\r\\nگام چهارم، از رابطه (1)، α^2 را حساب می‌کنیم:\\r\\n\\r\\n$-a + 2 = 3α \\\\Rightarrow (-a + 2) / 3 = α \\\\Rightarrow α^2 = (a - 2)^2 / 9$\\r\\n\\r\\nاز رابطه (2)، α^2 را تنها می‌کنیم:\\r\\n\\r\\n$-3a - 3 = 2α^2 \\\\Rightarrow α^2 = (-3a - 3) / 2$\\r\\n\\r\\nگام پنجم، دو مقدار به دست آمده برای α^2 را برابر قرار می‌دهیم:\\r\\n\\r\\n$(a - 2)^2 / 9 = (-3a - 3) / 2 \\\\Rightarrow (a^2 - 4a + 4) / 9 = (-3a - 3) / 2 \\\\Rightarrow 2a^2 - 8a + 8 = -27a - 27 \\\\Rightarrow 2a^2 + 19a + 35 = 0 (Δ = 361 - 280 = 81)$\\r\\n\\r\\nگام ششم، دلتای معادله بالا مثبت است، پس دو مقدار حقیقی برای a وجود دارد. مجموع مقادیر a برابر با S معادله بالاست که می‌شود -19 / 2 یعنی -9/5.\\r\\n\\r\\nراه دوم (تیزبازی!):\\r\\n\\r\\nگام اول، اگر کمی (یا بیشتر!) دقت کنید، می‌فهمید x = 3 ریشه معادله $(x - 1)^2 + a(x - 3) - 4 = 0$ است.\\r\\n\\r\\nگام دوم، چون یکی از ریشه‌ها 2 برابر ریشه دیگر است، پس ریشه دوم یا 6 است یا 3 / 2.\\r\\n\\r\\nگام سوم، x = 6 و x = 3 / 2 را در معادله قرار می‌دهیم:\\r\\n\\r\\n$(x - 1)^2 + a(x - 3) - 4 = 0 \\\\xrightarrow{x=6} 25 + 3a - 4 = 0 \\\\Rightarrow a = -7$\\r\\n\\r\\n$(x - 1)^2 + a(x - 3) - 4 = 0 \\\\xrightarrow{x=3/2} 1/4 - 3/2a - 4 = 0 \\\\xrightarrow{\\\\times 4} 1 - 6a - 16 = 0 \\\\Rightarrow 6a = -15 \\\\Rightarrow a = -2/5$\\r\\n\\r\\nگام چهارم، پس مجموع مقادیر a برابر با -9/5 = (-7) + (-2/5) است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"معادله و تابع درجه دوم\",\"selected_option_id\":null,\"is_answered\":false},\"4224\":{\"correct_option_id\":72800,\"descriptive_answer\":{\"text\":\"راه اول:\\r\\n\\r\\nگزینه‌ها را امتحان می‌کنیم. به ازای هر کدام که حاصل عبارت سمت چپ نامعادله $x|2x - 1| < 1$ برابر با عدد سمت راست (یعنی 1) شد، جواب است:\\r\\n\\r\\n1) $a = 1 \\\\Rightarrow 1|2(1) - 1| = 1 \\\\checkmark$\\r\\n\\r\\n2) $a = 1/2 \\\\Rightarrow 1/2|0| = 0 \\\\times$\\r\\n\\r\\n3) $a = -1/2 \\\\Rightarrow -1/2|2(-1/2) - 1| = -1 \\\\times$\\r\\n\\r\\n4) $a = -1 \\\\Rightarrow -1|2(-1) - 1| = -3 \\\\times$\\r\\n\\r\\nراه دوم:\\r\\n\\r\\nگام اول، ریشه عبارت داخل قدرمطلق را حساب می‌کنیم:\\r\\n\\r\\n$2x - 1 = 0 \\\\Rightarrow x = 1/2$\\r\\n\\r\\nگام دوم، بعد از حذف قدرمطلق، در دو محدوده $x \\\\geq 1/2$ و $x < 1/2$، نامعادله را حل می‌کنیم:\\r\\n\\r\\n$x|2x - 1| < 1 \\\\xrightarrow{x \\\\geq 1/2} x(2x - 1) < 1 \\\\Rightarrow 2x^2 - x - 1 < 0 \\\\xrightarrow{بین ریشه‌ها a+b+c=0} -1/2 < x < 1 \\\\xrightarrow{\\\\cap(x \\\\geq 1/2)} 1/2 \\\\leq x < 1$\\r\\n\\r\\n$x|2x - 1| < 1 \\\\xrightarrow{x < 1/2} x(-2x + 1) < 1 \\\\Rightarrow -2x^2 + x < 1 \\\\Rightarrow 2x^2 - x + 1 > 0 \\\\xrightarrow{\\\\Delta < 0, a > 0} x \\\\in \\\\mathbb{R} \\\\xrightarrow{\\\\cap(x < 1/2)} x < 1/2$\\r\\n\\r\\nگام سوم، بین دو محدوده به دست آمده، اجتماع می‌گیریم:\\r\\n\\r\\nجواب $= [1/2, 1) \\\\cup (-\\\\infty, 1/2) = (-\\\\infty, 1)$\\r\\n\\r\\nپس $a = 1$ است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"قدرمطلق و جزءصحيح\",\"selected_option_id\":null,\"is_answered\":false},\"4506\":{\"correct_option_id\":71610,\"descriptive_answer\":{\"text\":\"گام اول: از تساوی $f(x) = (x - 1)^3 + g(x)$ ، نتیجه می‌گیریم f تابعی درجه 3 است که ضریب $x^3$ در آن یک می‌باشد. $f(x) = x^3 - 3x^2 + 3x - 1 + ax^2 + bx + c = x^3 + (-3 + a)x^2 + (3 + b)x + (c - 1)$ بازشدهٔ آن هم به شکل روبه‌رو است: ضریب $x^3$ ، عدد 1 است (پس در گام بعد، k را 1 می‌گیریم). گام دوم: از نمودار رسم‌شده نتیجه می‌گیریم که مرکز تقارن تابع درجه‌سوم f، نقطهٔ $(-2, 3)$ است، پس ضابطه‌اش به صورت زیر است: $f(x) = k(x - \\\\alpha)^3 + \\\\beta \\\\xrightarrow[k = 1]{\\\\alpha = -2, \\\\beta = 3} f(x) = (x + 2)^3 + 3 = x^3 + 6x^2 + 12x + 11$ گام سوم: ضابطه‌های به دست آمده از گام اول و دوم را برابر قرار می‌دهیم: $x^3 + (-3 + a)x^2 + (3 + b)x + (c - 1) = x^3 + 6x^2 + 12x + 11 \\\\Rightarrow \\\\begin{cases} -3 + a = 6 \\\\Rightarrow a = 9 \\\\\\\\ 3 + b = 12 \\\\Rightarrow b = 9 \\\\\\\\ c - 1 = 11 \\\\Rightarrow c = 12 \\\\end{cases}$ گام چهارم: پس ضابطه g به صورت $g(x) = 9x^2 + 9x + 12$ است و داریم: $g(-1) = 9 - 9 + 12 = 12$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"تابع دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4521\":{\"correct_option_id\":71549,\"descriptive_answer\":{\"text\":\"گام اول: نمودار $y = |x|$ را یک واحد به راست و ۲ واحد به پایین می‌بریم: $y = |x| \\\\xrightarrow{x \\\\rightarrow x - 1} y = |x - 1| \\\\xrightarrow{2 \\\\text{ واحد پایین}} y = |x - 1| - 2$ گام دوم: نمودار $y = -x^2$ را یک واحد به چپ و ۲ واحد به بالا می‌بریم: $y = -x^2 \\\\xrightarrow{x \\\\rightarrow x + 1} y = -(x + 1)^2 \\\\xrightarrow{2 \\\\text{ واحد بالا}} y = -(x + 1)^2 + 2$ گام سوم: برای قطع‌دادن دو تابع به‌دست‌آمده باید ضابطه‌هایشان را برابر قرار دهیم: $\\\\begin{cases} y = |x - 1| - 2 \\\\\\\\ y = -(x + 1)^2 + 2 \\\\end{cases} \\\\Rightarrow |x - 1| - 2 = -(x + 1)^2 + 2 \\\\Rightarrow (x + 1)^2 + |x - 1| = 4$ گام چهارم: راه اول؛ بهترین راه برای حل معادله قبل، چک‌کردن گزینه‌هاست. فقط به ازای $x = -2$ تساوی برقرار است. راه دوم؛ چون جواب منفی را می‌خواهیم؛ پس $x < 0$ و در نتیجه $x - 1 < 0$ ، یعنی عبارت داخل قدرمطلق، قرینه بیرون می‌آید: $(x + 1)^2 + |x - 1| = 4 \\\\xrightarrow{x - 1 < 0} x^2 + 2x + 1 - x + 1 = 4 \\\\Rightarrow x^2 + x - 2 = 0 \\\\xrightarrow[x < 0]{a + b + c = 0} \\\\begin{cases} x_1 = 1 \\\\quad \\\\times \\\\\\\\ x_2 = -2 \\\\quad \\\\checkmark \\\\end{cases}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"تابع دهم\",\"selected_option_id\":null,\"is_answered\":false},\"4732\":{\"correct_option_id\":70676,\"descriptive_answer\":{\"text\":\"گزینه 4 درست است.\\r\\n\\r\\n$(HH\')^2 = AH\' \\\\times H\'C = 12 \\\\times 27 = 2^2 \\\\times 3^4 \\\\Rightarrow HH\' = 2 \\\\times 3^2 = 18$\\r\\n\\r\\nحالا با توجه به موازی بودن $AB, HH\'$، طبق رابطه تالس در مثلث $ABC$ داریم:\\r\\n\\r\\n$CH\'/CA = HH\'/AB \\\\Rightarrow 27/(27+12) = 18/AB \\\\Rightarrow 27/39 = 18/AB \\\\Rightarrow AB = 26$\\r\\n\\r\\nنهایتاً طبق رابطه فیثاغورس داریم:\\r\\n\\r\\n$(BC)^2 = (AB)^2 + (AC)^2 = (26)^2 + (39)^2 = (2 \\\\times 13)^2 + (3 \\\\times 13)^2 = 4 \\\\times 13^2 + 9 \\\\times 13^2 = 13 \\\\times 13^2 = 13^3 \\\\Rightarrow BC = \\\\sqrt{13^3} = 13\\\\sqrt{13}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"هندسه يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"5099\":{\"correct_option_id\":25274,\"descriptive_answer\":{\"text\":\"$f(1) = 2 \\\\Rightarrow a + \\\\frac{b}{2} = 2 \\\\quad f\'(1) = 0 \\\\Rightarrow a - \\\\frac{b}{(1+1)^2} = 0 \\\\Rightarrow b = 4a \\\\Rightarrow a = \\\\frac{2}{3} , b = \\\\frac{8}{3}$\\r\\n\\r\\nپس داریم:\\r\\n\\r\\n$f(x) = \\\\frac{2}{3}x + \\\\frac{\\\\frac{8}{3}}{x+1} \\\\Rightarrow f\'(x) = \\\\frac{2}{3} - \\\\frac{\\\\frac{8}{3}}{(x+1)^2}$\\r\\n\\r\\n$f\'(x) = 0 \\\\Rightarrow (x+1)^2 = 4 \\\\Rightarrow x = -3 \\\\xrightarrow{\\\\text{جایگذاری}} y = \\\\frac{2}{3}(-3) + \\\\frac{\\\\frac{8}{3}}{-2} = -2 - \\\\frac{4}{3} = -\\\\frac{10}{3}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"كاربرد مشتق\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{},\"submittedQuestionIds\":[1950,1409,1270,4044,3516,1199,1819,2062,2379,3947,4506,3838,1805,4118,4521,5099,1083,4732,3563,1240,1135,1646,3541,1311,4224,4216],\"totalTimeSpent\":55,\"questionTimes\":{\"1083\":1004,\"1199\":18001,\"1240\":6002,\"1270\":2000,\"1409\":3000,\"1646\":3001,\"1805\":2002,\"1819\":1001,\"1950\":2629,\"2062\":1001,\"3541\":1000,\"3947\":1001,\"4044\":5000,\"4216\":2004,\"4224\":998,\"4506\":1996,\"5099\":998},\"selectionLog\":[]}}', '2026-08-05 18:58:18'),
(135, 36, 104, 50.00, 1, 1, 0, 47, 12, '{\"total_questions\":2,\"correct_count\":1,\"incorrect_count\":1,\"unanswered_count\":0,\"accuracy_rate\":50,\"score\":47,\"mabhas_stats\":{\"فصل سه دوازدهم\":{\"correct\":1,\"incorrect\":0,\"unanswered\":0,\"total\":1},\"فصل یک یازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1}}}', '{\"evaluation\":{\"5228\":{\"correct_option_id\":32233,\"descriptive_answer\":{\"text\":\"گزینه «4»\\r\\n\\r\\n$25/2 g CxHy = 0/3 mol CxHy × mg CxHy / 1 mol CxHy$\\r\\n\\r\\n$⇒ m = 84 g.mol-1$\\r\\n\\r\\n$CxHy ⇒ \\\\{ 12x + y = 84$\\r\\n\\r\\n$\\\\{ 12x / y = 6 ⇒ x = 6 , y = 12 ⇒ C6H12$\\r\\n\\r\\nبا توجه به فرمول عمومی آلکن ها و سیکلو آلکان ها ($CnH2n$) این هیدروکربن می تواند سیر شده یا سیر نشده باشد؛ بنابراین هیدروکربن با ساختار می تواند همانند ترکیب داده شده دارای فرمول مولکولی $C6H12$ باشد.\\r\\n\\r\\nبررسی گزینه های نادرست:\\r\\n\\r\\n1) تفاوت جرم $C4H10 = 58 g.mol-1 , C6H12 = 84 g.mol-1$ مولی آن ها برابر جرم مولی $C2H2$ است. $C2H2$ ساده ترین آلکین است.\\r\\n\\r\\n2) اگر یک سیکلوآلکان باشد، با برم مایع واکنش نمی دهد.\\r\\n\\r\\n3) اگر آن را سیکلو آلکان در نظر بگیریم دارای 6 پیوند $C-C$ خواهد بود، اما اگر یک آلکن باشد، 4 پیوند $C-C$ خواهد داشت.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":32231,\"is_answered\":true},\"6858\":{\"correct_option_id\":46247,\"descriptive_answer\":{\"text\":\"بررسی عبارت‌ها:\\r\\n\\r\\nعبارت اول: نادرست - ممکن است برخی از کاتیون‌های فلزی که قدرت اکسندگی بیشتری دارند به اتم‌های فلز کاهش یابند.\\r\\n\\r\\nعبارت دوم: نادرست - ممکن است در یک واکنش اکسایش و کاهش، هر دو یک عنصر باشند. به عنوان مثال در واکنش زیر اتم‌های نیتروژن هم با کاهش و هم با افزایش عدد اکسایش همراهند.\\r\\n\\r\\n$NO(g) + NO_2(g) + 2NH_3(g) \\\\rightarrow 2N_2(g) + 3H_2O(g)$\\r\\n\\r\\nعبارت سوم: نادرست - در برخی از واکنش‌های اکسایش - کاهش، افزون بر دادوستد الکترون، انرژی (گرما) نیز آزاد می‌شود.\\r\\n\\r\\nعبارت چهارم: نادرست - جهت انجام یک واکنش اکسایش و کاهش، لزومی به وجود ترکیب یونی در اجزای شرکت‌کننده واکنش نیست، به عنوان مثال در این واکنش هیچ ترکیب یونی مشاهده نمی‌شود.\\r\\n\\r\\n$S(s) + O_2(g) \\\\rightarrow SO_2(g)$\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دوازدهم\",\"selected_option_id\":46247,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"5228\":32231,\"6858\":46247},\"submittedQuestionIds\":[6858,5228],\"totalTimeSpent\":12,\"questionTimes\":{\"5228\":1000,\"6858\":6002},\"selectionLog\":[{\"questionId\":6858,\"optionId\":46247,\"timeSpentMs\":6002,\"timestamp\":1785959935166},{\"questionId\":5228,\"optionId\":32231,\"timeSpentMs\":1000,\"timestamp\":1785959936404}]}}', '2026-08-05 19:59:02'),
(136, 37, 106, 0.00, 0, 4, 4, 0, 12, '{\"total_questions\":8,\"correct_count\":0,\"incorrect_count\":4,\"unanswered_count\":4,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"آمار\":{\"correct\":0,\"incorrect\":4,\"unanswered\":4,\"total\":8}}}', '{\"evaluation\":{\"1603\":{\"correct_option_id\":44741,\"descriptive_answer\":{\"text\":\"نکته: متغیرهایی که قابل اندازه‌گیری نیستند، متغیرهای کیفی و متغیرهایی را که قابل اندازه‌گیری هستند، متغیرهای کمی می‌گویند.\\r\\n\\r\\nنکته: متغیر کیفی را که در آن نوعی ترتیب طبیعی و منطقی وجود دارد، متغیر کیفی ترتیبی می‌گویند.\\r\\n\\r\\nنکته: متغیر کیفی را که ترتیبی نباشد، متغیر کیفی اسمی می‌گویند.\\r\\n\\r\\nنکته: متغیری را که اگر دو مقدار $a$ و $b$ را بتواند اختیار کند، آنگاه هر مقدار بین آن‌ها را نیز بتواند اختیار کند، متغیر کمی پیوسته می‌گویند.\\r\\n\\r\\nنکته: متغیری که کمی پیوسته نباشد، متغیر کمی گسسته می‌گویند.\\r\\n\\r\\nبا توجه به نکات بالا، هریک از گزینه‌ها را بررسی می‌کنیم:\\r\\n\\r\\nگزینه 1: کمی گسسته\\r\\n\\r\\nگزینه 2: کیفی ترتیبی\\r\\n\\r\\nگزینه 3: کمی پیوسته\\r\\n\\r\\nگزینه 4: کیفی اسمی\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"آمار\",\"selected_option_id\":44743,\"is_answered\":true},\"1612\":{\"correct_option_id\":45489,\"descriptive_answer\":{\"text\":\"نکته: متغیرهایی را که قابل اندازه‌گیری هستند، متغیرهای کمی و متغیرهایی را که قابل اندازه‌گیری نیستند، متغیرهای کیفی می‌گویند.\\r\\n\\r\\nنکته: اگر متغیر کمی بتواند دو مقدار $a$ و $b$ را اختیار کند، همچنین هر مقدار بین آن‌ها را نیز بتواند اختیار کند، متغیر کمی پیوسته می‌گویند و متغیر کمی که پیوسته نباشد، متغیر کمی گسسته است.\\r\\n\\r\\nنکته: متغیر کیفی که در آن نوعی ترتیب طبیعی وجود دارد را متغیر کیفی ترتیبی گویند و متغیر کیفی که ترتیبی نباشد، متغیر کیفی اسمی است.\\r\\n\\r\\nبر اساس موارد ذکر شده:\\r\\n\\r\\nالف) متغیر کمی گسسته\\r\\n\\r\\nب) متغیر کمی پیوسته\\r\\n\\r\\nج) متغیر کیفی ترتیبی\\r\\n\\r\\nد) متغیر کمی پیوسته\\r\\n\\r\\nه) متغیر کیفی ترتیبی\\r\\n\\r\\nو) متغیر کمی گسسته\\r\\n\\r\\nدو تا از متغیرها، کیفی ترتیبی هستند.\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"آمار\",\"selected_option_id\":45491,\"is_answered\":true},\"1619\":{\"correct_option_id\":45263,\"descriptive_answer\":{\"text\":\"اندازه یا حجم جامعه: تعداد اعضای جامعه را می‌گویند که در این سؤال برابر کل جمعیت روستا ( 500 نفر) می‌باشد.\\r\\n\\r\\nنمونه: بخشی از جامعه که برای مطالعه انتخاب می‌شود. تعداد اعضای نمونه حجم نمونه را بیان می‌کند بنابراین تعداد اعضای نمونه برابر 125 می‌باشد چون که $1/4$ کل اعضای جامعه جهت تشخیص بیماری کرونا مورد آزمایش قرار گرفته است.\\r\\n\\r\\nمتغیر: ویژگی از اعضای جامعه که مورد بررسی و مطالعه قرار می‌گیرد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"آمار\",\"selected_option_id\":45260,\"is_answered\":true},\"1620\":{\"correct_option_id\":44858,\"descriptive_answer\":{\"text\":\"بررسی همه گزینه‌ها:\\r\\n\\r\\nگزینه «1»: در این گزینه میزان دمای هوا و سرعت حرکت خودرو چون قابل اندازه‌گیری است و هر عددی را می‌پذیرد متغیرهای کمی پیوسته، کیفیت یک محصول (گیلاس) متغیر کیفی ترتیبی و تعداد بیماران کرونایی چون قابل شمارش می‌باشد یک متغیر کمی گسسته و همچنین از آنجایی که درجات نظامی قابل اندازه‌گیری نیست و دارای ترتیب می‌باشد یک متغیر کیفی ترتیبی است.\\r\\n\\r\\nگزینه «2»: وضعیت بهبودی یک بیمار (کیفی ترتیبی) - نوع بارندگی (کیفی اسمی) - جنسیت کارگران (کیفی اسمی) - فشار هوا در نوک قله دماوند (کمی پیوسته) - تعداد دانشگاه‌های ایران (کمی گسسته)\\r\\n\\r\\nگزینه «3»: مراحل تحصیلی (کیفی ترتیبی) - رنگ پوست (کیفی اسمی) - تعداد مسافران یک پرواز (کمی گسسته) - شاخص توده بدن مردم ایران (کمی پیوسته) - قطر تنه درختان (کمی پیوسته)\\r\\n\\r\\nگزینه «4»: امتیازات یک مسابقه والیبال (کمی گسسته) - مقاومت الکتریکی یک رسانا (کمی پیوسته) - ملیت افراد (کیفی اسمی) - سن افراد یک اداره (کمی پیوسته) - شتاب خودرو (کمی پیوسته)\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"آمار\",\"selected_option_id\":null,\"is_answered\":false},\"1635\":{\"correct_option_id\":44959,\"descriptive_answer\":{\"text\":\"بررسی گزینه‌ها:\\r\\n\\r\\nگزینه «1»: جمعیت شهر برحسب تعداد متغیر کمی گسسته است. شدت بارندگی برحسب زیاد، متوسط و کم دسته‌بندی می‌شود، بنابراین متغیر کیفی ترتیبی است.\\r\\n\\r\\nگزینه «2»: درجه حرارت بدن متغیر کمی پیوسته است. رنگ خودرو متغیر کیفی اسمی است.\\r\\n\\r\\nگزینه «3»: نوع آلایندگی هوا متغیر کیفی اسمی است. سطح تحصیلات متغیر کیفی ترتیبی است.\\r\\n\\r\\nگزینه «4»: گروه خونی $(A, B, AB, O)$ متغیر کیفی اسمی است. جنسیت بر اساس مرد یا زن است که در آن ترتیب طبیعی وجود ندارد و این متغیر کیفی اسمی است.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"آمار\",\"selected_option_id\":null,\"is_answered\":false},\"1641\":{\"correct_option_id\":44985,\"descriptive_answer\":{\"text\":\"متغیرهای ذکر شده در گزینه«2» به ترتیب از راست به چپ عبارتند از:\\r\\n\\r\\nگزینه «1»: کیفی اسمی، کیفی اسمی، کمی پیوسته، کمی پیوسته\\r\\n\\r\\nگزینه «2»: کیفی اسمی، کمی پیوسته، کیفی ترتیبی، کمی گسسته\\r\\n\\r\\nگزینه «3»: کمی پیوسته، کمی پیوسته، کیفی اسمی، کیفی ترتیبی\\r\\n\\r\\nگزینه «4»: کیفی اسمی، کمی گسسته، کیفی اسمی، کیفی ترتیبی\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"آمار\",\"selected_option_id\":44986,\"is_answered\":true},\"1642\":{\"correct_option_id\":44989,\"descriptive_answer\":{\"text\":\"وزن یک متغیر کمی پیوسته است. رتبه که با شماره‌گذاری مشخص می‌شود در حقیقت کیفی ترتیبی است و این اعداد صرفاً نشان‌دهنده جایگاه ورزشکار می‌باشند.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"آمار\",\"selected_option_id\":null,\"is_answered\":false},\"1643\":{\"correct_option_id\":45002,\"descriptive_answer\":{\"text\":\"نوع هر یک از متغیرها به شکل زیر است:\\r\\n\\r\\nطول خط‌کش: کمی پیوسته\\r\\n\\r\\nرنگ چشم افراد: کیفی اسمی\\r\\n\\r\\nدرجه افراد در یک ارگان نظامی: کیفی ترتیبی\\r\\n\\r\\nگروه خونی افراد در یک کلاس: کیفی اسمی\\r\\n\\r\\nمیزان فشار هوا در قله: کمی پیوسته\\r\\n\\r\\nتعداد تصادفات در یک شهر: کمی گسسته\\r\\n\\r\\nپس دو مورد کیفی اسمی هستند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"آمار\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"1603\":44743,\"1612\":45491,\"1619\":45260,\"1641\":44986},\"submittedQuestionIds\":[1619,1635,1612,1641,1603,1620,1642,1643],\"totalTimeSpent\":12,\"questionTimes\":{\"1603\":1002,\"1612\":1000,\"1619\":2000,\"1635\":1001,\"1641\":2001},\"selectionLog\":[{\"questionId\":1619,\"optionId\":45260,\"timeSpentMs\":2000,\"timestamp\":1786042811516},{\"questionId\":1612,\"optionId\":45491,\"timeSpentMs\":1000,\"timestamp\":1786042815073},{\"questionId\":1641,\"optionId\":44986,\"timeSpentMs\":2001,\"timestamp\":1786042816473},{\"questionId\":1603,\"optionId\":44743,\"timeSpentMs\":1002,\"timestamp\":1786042817743}]}}', '2026-08-06 19:00:21');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(137, 39, 4, 0.00, 0, 3, 28, 0, 11, '{\"total_questions\":31,\"correct_count\":0,\"incorrect_count\":3,\"unanswered_count\":28,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"فصل یک دهم\":{\"correct\":0,\"incorrect\":2,\"unanswered\":8,\"total\":10},\"فصل یک دوازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":9,\"total\":10},\"فصل دو دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":10,\"total\":10},\"فصل دو دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1}}}', '{\"evaluation\":{\"7086\":{\"correct_option_id\":41452,\"descriptive_answer\":{\"text\":\"یکای جرم در SI ، کیلوگرم kg است که تنها یکای اصلی در SI است که دارای پیشوند یکای k (کیلو) است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7087\":{\"correct_option_id\":41449,\"descriptive_answer\":{\"text\":\"در دستگاه اندازه‌گیری SI ، هفت کمیت طول، جرم، زمان، مقدار ماده، شدت جریان،\\r\\n\\r\\nدما و شدت روشنایی به عنوان کمیت‌های اصلی انتخاب شده‌اند و یکاهای اندازه‌گیری\\r\\n\\r\\nآن‌ها به‌ترتیب متر، کیلوگرم، ثانیه، مول، آمپر، کلوین و کندلا است. بقیۀ کمیت‌ها و\\r\\n\\r\\nیکاهای آن‌ها به عنوان کمیت‌ها و یکاهای فرعی در نظر گرفته می‌شوند.\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41450,\"is_answered\":true},\"7093\":{\"correct_option_id\":41424,\"descriptive_answer\":{\"text\":\"می‌دانیم چند کمیت هنگامی می‌توانند با هم جمع شوند که یکای آنها با هم برابر باشد. بنابراین می‌توان گفت یکای $d$ باید با یکای کمیت‌های $( aA2 )$ و $AB$ برابر باشد در نتیجه می‌توان نوشت:\\r\\n\\r\\n$m = m / s2 × [A]2 => [A]2 = s2 => [A] = s$\\r\\n\\r\\nچون یکای $A$ ، ثانیه است بنابراین $A$ از جنس زمان است. در این حالت داریم:\\r\\n\\r\\n$m = s[B] => [B] = m / s$\\r\\n\\r\\nچون یکای $B$ ، متر بر ثانیه است لذا $B$ از جنس سرعت است و گزینه «$1$» جواب است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7117\":{\"correct_option_id\":41331,\"descriptive_answer\":{\"text\":\"با استفاده از رابطه چگالی مخلوط داریم:\\r\\n\\r\\n$ρ$ مخلوط $= m1 + m2 / V1 + V2 => ρ = m1 + m2 / m1 / ρA + m2 / ρB$\\r\\n\\r\\n$ρA = 3 g / cm3 , ρB = 7 g / cm3 , ρ$ مخلوط $= 4 g / cm3 -> 4 = m1 + m2 / m1 / 3 + m2 / 7$\\r\\n\\r\\n$4 = m1 + m2 / 7m1 + 3m2 / 21 => 4 = 21m1 + 21m2 / 7m1 + 3m2$\\r\\n\\r\\n$=> 28m1 + 12m2 = 21m1 + 21m2$\\r\\n\\r\\n$=> 7m1 = 9m2 => m2 / m1 = 7 / 9$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7130\":{\"correct_option_id\":41278,\"descriptive_answer\":{\"text\":\"کمیت های اصلی عبارتند از:\\r\\n\\r\\n$1$) طول $2$) جرم $3$) زمان $4$) دما $5$) مقدار ماده $6$) جریان الکتریکی $7$) شدت روشنایی\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7134\":{\"correct_option_id\":41263,\"descriptive_answer\":{\"text\":\"ابتدا حجم و مساحت ظرف را برحسب $cm^3$ و $cm^2$ به‌دست می‌آوریم تا ارتفاع\\r\\n\\r\\nآن برحسب $cm$ به‌دست بیاید که بتوانیم آن را ساده‌تر به اینچ تبدیل کنیم. دقت\\r\\n\\r\\nکنید، مساحت ظرف برابر قاعده ضرب در ارتفاع است.\\r\\n\\r\\n$V = 25/4L \\\\times \\\\frac{10^3cm^3}{L} = 25400cm^3$\\r\\n\\r\\n$A = 0/04m^2 \\\\times \\\\frac{10^4cm^2}{1m^2} = 400cm^2$\\r\\n\\r\\n$V = Ah \\\\Rightarrow h = \\\\frac{V}{A} \\\\xrightarrow[A=400cm^2]{V=25400cm^3} h = \\\\frac{25400}{400} = \\\\frac{254}{4} cm$\\r\\n\\r\\nاکنون، سانتی‌متر را به اینچ تبدیل می‌کنیم، چون $1in = 2/54cm$ است، داریم:\\r\\n\\r\\n$h = \\\\frac{254}{4}cm \\\\times \\\\frac{1in}{2/54cm} \\\\Rightarrow h = 25in$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7142\":{\"correct_option_id\":41229,\"descriptive_answer\":{\"text\":\"چون با خالی کردن بخشی از مایع درون ظرف، جرم مایع باقیمانده و ظرف نصف حالت\\r\\n\\r\\nاولیه می‌شود، می‌توان نوشت:\\r\\n\\r\\n($1$) $1/2(m$ ظرف $+$ $m$ اولیه مایع $) = m\'$ مایع باقی‌مانده $+$ $m$ ظرف\\r\\n\\r\\nاز طرف دیگر، چون $4/5$ حجم مایع درون ظرف را خالی نموده‌ایم، $1/5$ حجم آن باقی\\r\\n\\r\\nمی‌ماند، که با توجه به رابطه $m=ρV$ ، جرم مایع باقیمانده نیز $1/5$ جرم اولیه مایع\\r\\n\\r\\nمی‌شود. در این‌صورت با توجه به رابطه ($1$) داریم:\\r\\n\\r\\n($1$) $m\'$ مایع باقیمانده $=$ $1/5m$ اولیه مایع $\\\\rightarrow m$ ظرف $+$ $1/5m$ اولیه مایع\\r\\n\\r\\n$=$ $1/2m$ ظرف $+$ $1/2m$ اولیه مایع\\r\\n\\r\\n$\\\\Rightarrow m$ ظرف $-$ $1/2m$ ظرف $=$ $1/2m$ اولیه مایع $-$ $1/5m$ اولیه مایع\\r\\n\\r\\n$\\\\Rightarrow 1/2m$ ظرف $=$ $3/10m$ اولیه مایع $\\\\Rightarrow m$ ظرف $=$ $3/5m$ اولیه مایع\\r\\n\\r\\n$\\\\Rightarrow m$ ظرف $=$ $3/5ρ$ مایع $V$ اولیه مایع $\\\\rightarrow v=πr^2h \\\\rightarrow$\\r\\n\\r\\n$m$ ظرف $=$ $3/5ρ$ مایع $\\\\times πr^2$ مایع $h$ اولیه مایع $\\\\rightarrow r$ مایع $=$ $2cm , ρ$ مایع $=$ $5 g/cm^3 , h$ اولیه مایع $=$ $10cm \\\\rightarrow$\\r\\n\\r\\n$m$ ظرف $=$ $3/5 \\\\times 5 \\\\times 3 \\\\times 2^2 \\\\times 10 \\\\Rightarrow m$ ظرف $=$ $360g$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7157\":{\"correct_option_id\":41171,\"descriptive_answer\":{\"text\":\"دقت خط‌کش مدرج و کولیس رقمی را به m و cm تبدیل می‌کنیم.\\r\\n\\r\\n$1 mm = 0/1 cm = 0/001 m =$ دقت خط‌کش\\r\\n\\r\\n$0/1 mm = 0/01 cm = 0/0001 m =$ دقت کولیس\\r\\n\\r\\nبا توجه به نتیجه‌های به‌دست آمده خط‌کش اندازه‌های $0/1 cm$ و $0/001 m$ و\\r\\n\\r\\nکولیس $0/01 cm$ و $0/0001 m$ را می‌تواند اندازه‌گیری کند. بنابراین گزینه «۴»\\r\\n\\r\\nصحیح است.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41170,\"is_answered\":true},\"7167\":{\"correct_option_id\":41129,\"descriptive_answer\":{\"text\":\"ابتدا جرم آلیاژ (مجموع جرم طلا و نقره) را به‌دست می‌آوریم:\\r\\n\\r\\n$ρ$ آلیاژ $=$ $mAu + mAg / V$ آلیاژ\\r\\n\\r\\n$ρ$ آلیاژ $= 13/6 g/cm^3$\\r\\n\\r\\n$V$ آلیاژ $= 5 cm^3$\\r\\n\\r\\n$---------------- → 13/6 = mAu + mAg / 5 → mAu + mAg = 68 g$\\r\\n\\r\\n$mAu = ρAu · VAu$\\r\\n\\r\\n$---------------- → ρAu · VAu + ρAg · VAg = 68$\\r\\n\\r\\n$mAg = ρAg · VAg$\\r\\n\\r\\n$ρAu = 19 g/cm^3$\\r\\n\\r\\n$--------------- → \\\\{ 19 VAu + 10 VAg = 68$\\r\\n\\r\\n$ρAg = 10 g/cm^3$             $\\\\{ VAu + VAg = 5$\\r\\n\\r\\n$⇒ VAg = 3 cm^3 , VAu = 2 cm^3$\\r\\n\\r\\nدرنهایت جرم نقره را به‌دست می‌آوریم:\\r\\n\\r\\n$mAg = VAg · ρAg ⇒ mAg = 3 × 10 = 30 g$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7180\":{\"correct_option_id\":41075,\"descriptive_answer\":{\"text\":\"با توجه به این‌که $T=10^{12}$ و $\\\\mu=10^{-6}$ است، با استفاده از تبدیل زنجیره‌ای\\r\\n\\r\\nمی‌توان نوشت:\\r\\n\\r\\n$0/00024 \\\\mu N.Tm = 2/4 \\\\times 10^{-4} \\\\mu N.Tm \\\\times \\\\frac{1 N}{10^6 \\\\mu N} \\\\times \\\\frac{10^{12} m}{1 Tm}$\\r\\n\\r\\n$= 2/4 \\\\times 10^2 N.m$\\r\\n\\r\\nاز طرف دیگر، با توجه به این‌که $1N = 1 kg.\\\\frac{m}{s^2}$ است، داریم:\\r\\n\\r\\n$2/4 \\\\times 10^2 N.m = 2/4 \\\\times 10^2 \\\\frac{kg.m^2}{s^2}$\\r\\n\\r\\n$\\\\frac{M=10^6}{n=10^{-9}} \\\\rightarrow 2/4 \\\\times 10^2 \\\\frac{kg.m^2}{s^2} \\\\times \\\\frac{10^3 g}{1 kg} \\\\times \\\\frac{1 Mg}{10^6 g}$\\r\\n\\r\\n$\\\\times \\\\frac{1 s^2}{(10^9)^2 ns^2} \\\\times \\\\frac{(10^3)^2 mm^2}{1 m^2} = 2/4 \\\\times 10^2 \\\\times 10^3 \\\\times 10^{-18} \\\\frac{Mg.mm^2}{ns^2}$\\r\\n\\r\\n$= 2/4 \\\\times 10^{-13} \\\\frac{Mg.mm^2}{ns^2}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7190\":{\"correct_option_id\":41036,\"descriptive_answer\":{\"text\":\"پاسخ تشریحی با توجه به برابری فشار نقاط هم‌تراز از در یک مایع ساکن داریم:\\r\\n\\r\\n\\r\\n\\r\\n$P_A = P_B \\\\Rightarrow P_{گاز} = \\\\rho gh + P_{\\\\circ} \\\\Rightarrow P_g = \\\\rho gh \\\\xrightarrow[]{P_g = \\\\rho_{Hg} g h_{Hg}} \\\\rho_{Hg} g h_{Hg} = \\\\rho gh$\\r\\n\\r\\n\\r\\n\\r\\n$\\\\Rightarrow 13/6 \\\\times 10^3 \\\\times 8 = \\\\rho \\\\times 40 \\\\Rightarrow \\\\rho = 2720 kg/m^3$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7208\":{\"correct_option_id\":40967,\"descriptive_answer\":{\"text\":\"چون چگالی جیوه از چگالی آب بیش‌تر است جیوه در زیر و آب روی آن قرار می‌گیرد. با توجه به این‌که فشار هوا برحسب سانتی‌متر جیوه داده شده است پس فشار حاصل از جیوه و آب را ابتدا برحسب سانتی‌متر جیوه به‌دست می‌آوریم. دقت کنید که، چون جرم آب و جرم جیوه یکسان است در نتیجه فشار ستون آب و جیوه نیز با یکدیگر برابر است و کافی است فقط ارتفاع ستون جیوه در داخل لوله را به‌دست آوریم و آن را دو برابر کنیم.\\r\\n\\r\\n$P_0 = 76 cmHg$\\r\\n\\r\\n$m_{جیوه} = \\\\rho_{جیوه} V_{جیوه} \\\\Rightarrow 136 = 13/6 \\\\times V_{جیوه} \\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n$h_{جیوه} = \\\\frac{V_{جیوه}}{A} = \\\\frac{10}{5} = 2 cm$\\r\\n\\r\\nپس فشار حاصل از ستون جیوه، معادل $2 cmHg$ است و فشار کل وارد بر کف ظرف برابر است با:\\r\\n\\r\\n$P_{کل} = P_0 + P_{آب} + P_{جیوه} = 76 + 2 + 2 = 80 cmHg$\\r\\n\\r\\nحال فشار معادل $80 cmHg$ را برحسب پاسکال به‌دست می‌آوریم:\\r\\n\\r\\n$P_{کل} = \\\\rho gh = 13600 \\\\times 10 \\\\times 80 \\\\times 10^{-2} = 108800 Pa$\\r\\n\\r\\nدقت کنید، این مسئله را می‌توانیم بدون محاسبه و با رد گزینه حل کنیم. بدین صورت که، فشار هوا به تنهایی $10^5$ پاسکال است. از طرف دیگر، فشار دو مایع، علاوه بر فشار هوا، اضافه می‌شود که تنها گزینه ۴ بیشتر از صد هزار است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7216\":{\"correct_option_id\":40936,\"descriptive_answer\":{\"text\":\"ابتدا حجم روغن ریخته شده در ظرف را محاسبه می‌کنیم. به همین منظور برای سازگاری یکاها، چگالی مایع را برحسب گرم بر سانتی‌متر مکعب به‌دست می‌آوریم:\\r\\n\\r\\n$\\\\rho = 0/6 \\\\frac{kg}{L} \\\\times \\\\frac{10^3 g}{1 kg} \\\\times \\\\frac{1 L}{10^3 cm^3} = 0/6 \\\\frac{g}{cm^3}$\\r\\n\\r\\n$\\\\rho_{روغن} = \\\\frac{m_{روغن}}{V_{روغن}} \\\\Rightarrow V_{روغن} = \\\\frac{m_{روغن}}{\\\\rho_{روغن}} = \\\\frac{180 g}{0/6 \\\\frac{g}{cm^3}} = 300 cm^3$\\r\\n\\r\\nاکنون حجم قسمت پهن ظرف را به‌دست می‌آوریم:\\r\\n\\r\\n$V = Ah = 12 \\\\times 20 = 240 cm^3$\\r\\n\\r\\nهمان‌طور که مشاهده می‌کنید، حجم کل روغن $(V = 300 cm^3)$ از حجم قسمت پهن ظرف $(V = 240 cm^3)$ بیشتر است درنتیجه، روغن وارد قسمت باریک ظرف خواهد شد. در این حالت حجم روغن وارد شده در قسمت باریک ظرف برابر $300 - 240 = 60 cm^3$ است. بنابراین ارتفاع روغن در قسمت باریک لوله برابر است با:\\r\\n\\r\\n$V\' = A\'h\' \\\\Rightarrow 60 = 5h\' \\\\Rightarrow h\' = 12 cm$\\r\\n\\r\\nپس فاصله سطح آزاد روغن از کف ظرف برابر $20 + 12 = 32 cm$ خواهد شد.\\r\\n\\r\\nاکنون با استفاده از رابطه $F = PA$ نیروی وارد بر کف ظرف از طرف روغن را به‌دست می‌آوریم:\\r\\n\\r\\n$F = PA \\\\xrightarrow{P=\\\\rho g(h+h\')} F = 600 \\\\times 10 \\\\times \\\\frac{32}{100} \\\\times 12 \\\\times 10^{-4} = 2/304 N$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7267\":{\"correct_option_id\":40734,\"descriptive_answer\":{\"text\":\"ابتدا به کمک معادله پیوستگی تندی جریان شاره در هر بخش را به‌دست می‌آوریم:\\r\\n\\r\\n$A1v1 = A2v2 => πr12 * v1 = πr22 * v2$\\r\\n\\r\\n$-> (r1=4cm, r2=2cm) -> 16v1 = 4v2 => v2 = 4v1$\\r\\n\\r\\n$v2 - v1 = 15 cm/s => 4v1 - v1 = 15 cm/s => 3v1 = 15 => v1 = 5 cm/s => v2 = 20 cm/s$\\r\\n\\r\\nاکنون به کمک آهنگ جریان شاره داریم:\\r\\n\\r\\n$A2v2 = $حجم / زمان $ : $آهنگ جریان شاره\\r\\n\\r\\n$A2 = πr22 -> (r2=2cm) -> A2 = 12cm2$\\r\\n\\r\\n$-> 12cm2 * 20 cm/s = $حجم $ / 3600s => $حجم $ = 240 * 3600 cm3 = 864000cm3$\\r\\n\\r\\n$1cm3 = 10^-3L => $حجم $ = 864000 * 10^-3L = 864L$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7271\":{\"correct_option_id\":40716,\"descriptive_answer\":{\"text\":\"با توجه به این‌که فشار نقاط هم‌تراز در یک مایع ساکن با هم برابرند، $PA = PB$ و $PC = PD$ می‌باشد. بنابراین می‌توان نوشت:\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n$PA = PB -> (PA=PG1, PB=P0+ρgh1) -> PG1 = P0 + ρgh1$\\r\\n\\r\\n$-> (h1=50cm=0.5m, P0=10^5Pa, ρ=10^3 kg/m3) -> PG1 = 10^5 + 10^3 * 10 * 0.5 = 105000Pa$\\r\\n\\r\\n$PD = PC -> (PD=1.2*10^5Pa, PC=PG1+ρgh2) -> 1.2 * 10^5 = PG1 + ρgh2 -> (h2=x)$\\r\\n\\r\\n$-> 120000 = 105000 + 10^3 * 10 * x -> 15000 = 10000x -> x = 1.5m = 150cm$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7283\":{\"correct_option_id\":41593,\"descriptive_answer\":{\"text\":\"با توجه به رابطه‌های $P = \\\\rho g h$ و $F = PA$ ، نیروی وارد بر کف ظرف از طرف مایع برابر $F = \\\\rho g h A$ می‌باشد که در این‌جا A مساحت کف ظرف است. با توجه به این رابطه، چون A ، $\\\\rho$ و g ثابت‌اند، افزایش نیرو را از رابطه $\\\\Delta F = \\\\rho g A (\\\\Delta h)$ می‌یابیم.\\r\\n\\r\\nاز طرف دیگر، با توجه به این‌که جرم مایع اضافه شده برابر $m = \\\\rho V\' = \\\\rho A\' (\\\\Delta h)$ است، بنابراین $\\\\Delta h = \\\\frac{m}{\\\\rho A\'}$ خواهد بود که در این رابطه $A\'$ مساحت دهانه باریک ظرف است. در این حالت می‌توان نوشت:\\r\\n\\r\\n$\\\\Delta F = \\\\rho g A (\\\\Delta h) \\\\xrightarrow{\\\\Delta h = \\\\frac{m}{\\\\rho A\'}} \\\\Delta F = \\\\rho g A \\\\times \\\\frac{m}{\\\\rho A\'} \\\\Rightarrow \\\\Delta F = \\\\frac{A}{A\'} \\\\times mg$\\r\\n\\r\\n$\\\\xrightarrow{\\\\Delta F = 20 N, A = 100 cm^2 \\\\atop A\' = 20 cm^2} 20 = \\\\frac{100}{20} \\\\times mg \\\\Rightarrow mg = 4N$\\r\\n\\r\\nمی‌بینیم، عدد ترازو به اندازه وزن مایع اضافه شده، یعنی 4N افزایش می‌یابد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7305\":{\"correct_option_id\":40575,\"descriptive_answer\":{\"text\":\"پس از دمیدن شخص در لوله، سطح جیوه در شاخه سمت راست  $10cm$ بالا رفته و در شاخه سمت چپ نیز  $10cm$ پایین می آید؛ به این ترتیب اختلاف ارتفاع جیوه در دو شاخه  $20cm$ است و فشار پیمانه ای ریه شخص به  $20cmHg$ می رسد.\\r\\n\\r\\n\\r\\n\\r\\n$P - P_0 = 20 cmHg ⇒ P = 20 + 70 = 90 cmHg$\\r\\n\\r\\n$P = {F}{A} ⇒ F = PA = (ρgh)$_جیوه$A$\\r\\n\\r\\n$⇒ F = 13600 × 10 × 0/9 × 1 × 10^{-4} ⇒ F = 12/24 N$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7318\":{\"correct_option_id\":40521,\"descriptive_answer\":{\"text\":\"حجم حفره $= 4/3 πr^3 = 4/3 × 3 × (2)^3 = 32 cm^3$\\r\\n\\r\\n$ρ = m / V ⇒ m = ρV ⇒ m$آب $= 1 × 32 = 32 g$\\r\\n\\r\\n$ρ$مکعب حاوی آب $= (m$آب $+ m$فلز$) / V$مکعب $= (32 + 718) / (5)^3 = 750 / 125 = 6 g / cm^3$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7337\":{\"correct_option_id\":40444,\"descriptive_answer\":{\"text\":\"$P_B = P_C = ρ$جیوه$gh_1 + P_0 = 13600 × 10 × 0/05 + 10^{5}$\\r\\n\\r\\n$= 6800 + 10^{5} = 0/068 × 10^5 + 10^{5} = 1/068 × 10^{5} Pa$\\r\\n\\r\\n$P$گاز$ = P_B ⇒ P_A = P$گاز$ + ρ$آب$gh_2 = 1/068 × 10^{5} + 1000 × 10 × 2$\\r\\n\\r\\n$= 1/068 × 10^{5} + 0/2 × 10^{5} = 1/268 × 10^{5} Pa$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7339\":{\"correct_option_id\":40439,\"descriptive_answer\":{\"text\":\"$P_0 = ρgh ⇒ 9/6 × 10^{4} = 1200 × 10 × h ⇒ h = 8 m$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"9608\":{\"correct_option_id\":56553,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\n\\nبا توجه به شیب خط واصل بین دو لحظه صفر تا $t_1$، سرعت متوسط متحرک در بازه زمانی صفر تا $t_1$ منفی است:\\n\\n$v_{av} = \\\\frac{\\\\Delta x}{\\\\Delta t} \\\\Rightarrow -5 = \\\\frac{-10 - 10}{t_1 - 0} \\\\Rightarrow t_1 = 4 s$\\n\\nدر بازه زمانی صفر تا $t_1 = 4 s$ داریم:\\n\\n$\\\\Delta x = \\\\frac{1}{2}at^2 + v_0t \\\\Rightarrow -10 - 10 = \\\\frac{1}{2}a(4)^2 + v_0 \\\\times 4 \\\\Rightarrow -20 = 8a + 4v_0$ (رابطه 1)\\n\\nدر بازه زمانی صفر تا $1/5 s$ داریم:\\n\\n$v = at + v_0 \\\\Rightarrow 0 = 1/5a + v_0$ (رابطه 2)\\n\\nروابط (1) و (2) $\\\\Rightarrow \\\\begin{cases} -20 = 8a + 4v_0 \\\\\\\\ 0 = 1/5a + v_0 \\\\end{cases} \\\\Rightarrow a = -10 \\\\frac{m}{s^2} , v_0 = 15 \\\\frac{m}{s}$\\n\\n$v = at + v_0 \\\\Rightarrow \\\\begin{cases} 10 = -10t + 15 \\\\Rightarrow t = 0/5 s \\\\\\\\ -10 = -10t + 15 \\\\Rightarrow t = 2/5 s \\\\end{cases}$\\n\\nدر بازه زمانی صفر تا $0/5 s$، تندی متحرک از $15 \\\\frac{m}{s}$ به $10 \\\\frac{m}{s}$ می‌رسد. در بازه زمانی $0/5 s$ تا $1/5 s$، تندی متحرک از $10 \\\\frac{m}{s}$ به صفر می‌رسد و در بازه زمانی $1/5 s$ تا $2/5 s$، تندی متحرک از صفر به $10 \\\\frac{m}{s}$ می‌رسد؛ پس به مدت $2 s$ تندی متحرک کمتر از $10 \\\\frac{m}{s}$ بوده است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9610\":{\"correct_option_id\":56561,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\n\\n$v_{(t=5s)} = \\\\frac{100-50}{5-0} = 10 \\\\frac{m}{s}$ : شیب خط مماس\\n\\n$v = at + v_0 \\\\Rightarrow 0 = a \\\\times (7.5 - 5) + 10 \\\\Rightarrow a = -4 \\\\frac{m}{s^2}$\\n\\nدر بازه زمانی $t=0s$ تا $t_2=7.5s$ داریم:\\n\\n$\\\\begin{cases} \\\\Delta x = \\\\frac{1}{2}at^2 + v_0t \\\\\\\\ v = at + v_0 \\\\end{cases} \\\\Rightarrow \\\\Delta x = -\\\\frac{1}{2}at^2 + vt \\\\Rightarrow \\\\Delta x = -\\\\frac{1}{2} \\\\times (-4) \\\\times 7.5^2 + 0 \\\\times 7.5 = 112.5m$\\n\\nچون نمودار منحنی به صورت سهمی است، مسافت طی شده در بازه زمانی $0$ تا $t_1$ ، دو برابر این مقدار است:\\n\\n$\\\\ell = 2 \\\\times 112.5 = 225m$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9611\":{\"correct_option_id\":56563,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 2\\n\\nجهت رو به راست را مثبت فرض می‌کنیم.\\n\\nبرای فاصله $BC$ داریم:\\n\\n$\\\\Delta x_{BC} = \\\\frac{1}{2}at^2 + v_B t \\\\Rightarrow 40 = \\\\frac{1}{2} \\\\times 4 \\\\times 2^2 + v_B \\\\times 2 \\\\Rightarrow v_B = 16 \\\\frac{m}{s}$\\n\\nبرای فاصله $AB$ داریم:\\n\\n$v_B^2 - v_A^2 = 2a\\\\Delta x_{AB} \\\\Rightarrow 16^2 - 0 = 2 \\\\times 4 \\\\times \\\\Delta x_{AB} \\\\Rightarrow \\\\Delta x_{AB} = 32m$\\n\\n$\\\\Delta x_{AC} = 32 + 40 = 72m \\\\Rightarrow AC$ :وسط فاصله   $72\\\\div 2 = 36m$\\n\\n$v^2 - v_A^2 = 2a \\\\times (\\\\frac{1}{2} \\\\Delta x_{AC}) \\\\Rightarrow v^2 - 0 = 2 \\\\times 4 \\\\times 36 \\\\Rightarrow v = 12\\\\sqrt{2} \\\\frac{m}{s}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9624\":{\"correct_option_id\":56610,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 1\\n\\n$\\\\Delta x_{1}=v_{1}\\\\Delta t=20\\\\times 30=600m$\\n\\n$\\\\Delta x_{2}=-v_{2}\\\\Delta t_{2}=-10\\\\times 20=-200m$\\n\\n$\\\\Delta x=\\\\Delta x_{1}+\\\\Delta x_{2}=600+(-200)=400m$\\n\\nمدت زمان کل حرکت برابر است با:\\n\\n$\\\\Delta t=\\\\Delta t_{1}+\\\\Delta t_{2}=30+20=50s$\\n\\n$v_{av}=\\\\frac{\\\\Delta x}{\\\\Delta t}=\\\\frac{400}{50}=8\\\\frac{m}{s}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9632\":{\"correct_option_id\":56644,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 3\\n\\nراه حل اول:\\n\\nمکان دو متحرک در لحظه $t = 10s$ را $x_1$ فرض می‌کنیم و معادله حرکت هر متحرک را می‌نویسیم:\\n\\n$x = vt + x_0 \\\\Rightarrow$\\n\\nمتحرک A: $x_A = \\\\frac{x_1 - 30}{10 - 0}t + 30$\\n\\nمتحرک B: $x_B = \\\\frac{x_1 - (-20)}{10 - 0}t - 20$\\n\\nدر بازه زمانی صفر تا $t = 10s$ فاصله دو متحرک کمتر از $50$ متر است؛ ازاین‌رو پاسخ سؤال پس از لحظه $t = 10s$ بوده که $x_B > x_A$ است.\\n\\n$\\\\frac{x_1 + 20}{10}t - 20 - (\\\\frac{x_1 - 30}{10}t + 30) = 60 \\\\Rightarrow 5t - 50 = 60 \\\\Rightarrow t = 22s$\\n\\n\\n\\nراه حل دوم:\\n\\nدر مدت $10s$ دو متحرک $50m$ به هم نزدیک شده‌اند؛ در نتیجه برای آنکه $60m$ از هم فاصله بگیرند، باید $12s$ بگذرد؛ در نتیجه کل زمان سپری‌شده برابر $22s = 10 + 12$ خواهد شد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9634\":{\"correct_option_id\":56652,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 3\\n\\n$s = \\\\frac{\\\\ell}{\\\\Delta t} \\\\Rightarrow \\\\Delta t = \\\\frac{\\\\ell}{s}$\\n\\nشهر (1) ----- $\\\\ell$ ----- شهر (2)\\n\\n$\\\\left\\\\{ \\\\begin{array}{l} \\\\Delta t_1 = \\\\frac{\\\\ell}{60} + \\\\frac{\\\\ell}{20} = \\\\frac{4\\\\ell}{60} \\\\\\\\ \\\\Delta t_2 = \\\\frac{\\\\ell}{40} + \\\\frac{\\\\ell}{40} = \\\\frac{2\\\\ell}{40} \\\\end{array} \\\\right\\\\} \\\\Rightarrow \\\\Delta t_1 > \\\\Delta t_2$\\n\\n$\\\\Delta t_1 - \\\\Delta t_2 = 2/5 \\\\Rightarrow \\\\frac{4}{60}\\\\ell - \\\\frac{2}{40}\\\\ell = 2/5 \\\\Rightarrow \\\\ell = 150 km$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":56650,\"is_answered\":true},\"9640\":{\"correct_option_id\":56675,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 2\\n\\nهر دو متحرک در کل، مسافت 100 متر را طی کرده‌اند؛ بنابراین داریم:\\n\\n$\\\\ell = v \\\\times t \\\\Rightarrow \\\\begin{cases} 54 = v_1t \\\\\\\\ 46 = v_2t \\\\end{cases} \\\\Rightarrow \\\\frac{v_1}{v_2} = \\\\frac{54}{46} = \\\\frac{27}{23}$\\n\\n$v_1t_1 = v_2t_2 = 100 \\\\Rightarrow \\\\frac{v_1}{v_2} = \\\\frac{t_2}{t_1} = \\\\frac{27}{23} \\\\ \\\\ \\\\ (1) $\\n\\n$t_2 - t_1 = 12 \\\\xrightarrow{(1) } t_2 - \\\\frac{23}{27}t_2 = 12 \\\\Rightarrow \\\\frac{4}{27}t_2 = 12 \\\\Rightarrow t_2 = 81s \\\\ , \\\\ t_1 = 69s$\\n\\n$\\\\ell_{\\\\text{کل}} = v_1t_1 \\\\Rightarrow 100 = v_1 \\\\times 69 \\\\Rightarrow v_1 = \\\\frac{100}{69} \\\\frac{m}{s}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9647\":{\"correct_option_id\":56704,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 3\\n\\nابتدا شتاب ثابت متحرک را در بازه زمانی صفر تا $3s$ محاسبه می‌کنیم.\\n\\n$\\\\begin{cases} \\\\Delta x = \\\\frac{1}{2}at^2 + v_{\\\\circ}t \\\\\\\\ v = at + v_{\\\\circ} \\\\end{cases} \\\\Rightarrow \\\\begin{cases} -24 = \\\\frac{1}{2}a \\\\times 3^2 + v_{\\\\circ} \\\\times 3 \\\\\\\\ 0 = a \\\\times 3 + v_{\\\\circ} \\\\end{cases} \\\\Rightarrow -24 = \\\\frac{9}{2}a - 9a \\\\Rightarrow a = \\\\frac{16}{3} \\\\frac{m}{s^2}$\\n\\nاکنون با رابطه مستقل از زمان، سرعت متحرک در مکان $72 m$ را محاسبه می‌کنیم:\\n\\n$\\\\begin{cases} x_1 = -24 m \\\\\\\\ v_1 = 0 \\\\end{cases} , \\\\begin{cases} x_2 = 72 m \\\\\\\\ v_2 = ? \\\\end{cases}$\\n\\n$v_2^2 - v_1^2 = 2a\\\\Delta x \\\\Rightarrow v_2^2 - 0 = 2 \\\\times \\\\frac{16}{3} \\\\times (72 - (-24)) \\\\Rightarrow v_2 = 32 \\\\frac{m}{s}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9649\":{\"correct_option_id\":56713,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\n\\nحرکت کامیون با سرعت ثابت و حرکت خودرو با شتاب ثابت است. ابتدا محاسبه می‌کنیم که در چه لحظه‌ای تندی خودرو به $40 \\\\frac{m}{s}$ می‌رسد، آنگاه مکان خودرو را در این لحظه محاسبه می‌کنیم و چون در این لحظه خودرو از کامیون سبقت می‌گیرد، مکان کامیون نیز همان است.\\n\\n$x = \\\\frac{1}{2}at^2 + v_{\\\\circ}t + x_{\\\\circ} \\\\Rightarrow \\\\begin{cases} a = 8 \\\\frac{m}{s^2}, v_{\\\\circ} = 0, x_{\\\\circ} = 20m \\\\\\\\ x = 4t^2 + 0 \\\\times t + 20 \\\\end{cases}$\\n\\n$v$ خودرو $= at + v_{\\\\circ} \\\\Rightarrow 40 = 8t + 0 \\\\Rightarrow t = 5s$\\n\\n$x$ خودرو $= 4(5)^2 + 20 = 120m$\\n\\n$x$ کامیون $= vt \\\\Rightarrow 120 = v \\\\times 5 \\\\Rightarrow v = 24 \\\\frac{m}{s}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9655\":{\"correct_option_id\":56737,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\n\\nبا توجه به جهت مثبت انتخاب شده، شتاب B مثبت و شتاب A منفی است. به هم رسیدن دو متحرک یعنی $x_A = x_B$.\\n\\n$\\\\begin{cases} x_A = \\\\frac{1}{2}at^2 + v_{\\\\circ}t + x_{\\\\circ} = -\\\\frac{1}{2} \\\\times 2t^2 + 0 + 125 = -t^2 + 125 \\\\\\\\ x_B = \\\\frac{1}{2}at^2 + v_{\\\\circ}t + x_{\\\\circ} = \\\\frac{1}{2}a_Bt^2 + 0 + 0 = \\\\frac{1}{2}a_Bt^2 \\\\end{cases}$\\n\\n$x_A = x_B \\\\Rightarrow -t^2 + 125 = \\\\frac{1}{2}a_Bt^2 \\\\xrightarrow{t=5s} -25 + 125 = \\\\frac{25}{2}a_B \\\\Rightarrow a_B = \\\\frac{200}{25} = 8 \\\\frac{m}{s^2} \\\\Rightarrow x_B = \\\\frac{1}{2} \\\\times 8 \\\\times t^2 = 4t^2$\\n\\nرسیدن متحرک B به نقطه شروع متحرک A:\\n\\n$x_B = 125 \\\\Rightarrow 4t^2 = 125 \\\\Rightarrow t^2 = \\\\frac{125}{4}$\\n\\nفاصله دو متحرک از یکدیگر $= x_B - x_A = 4t^2 - (-t^2 + 125) = 5t^2 - 125 = 5 \\\\times \\\\frac{125}{4} - 125 = \\\\frac{125}{4} m$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9734\":{\"correct_option_id\":57051,\"descriptive_answer\":{\"text\":\"چون نردبان در آستانه سر خوردن است، نیروی خالص وارد بر آن صفر است. بنابراین، نیروهای وارد بر نردبان را رسم می کنیم، و سپس با توجه به این که، نیروی زمین بر نردبان برابر برآیند دو نیروی $f_{s,\\\\max}$ و $F_{N_2}$ است، به صورت زیر $m$ را پیدا می کنیم:\\n\\n$F_{N_1}$\\n\\n$f_{s,\\\\max}$\\n\\n$mg$\\n\\n$F_{N_2}$\\n\\n$F_{net_y}=0 \\\\Rightarrow F_{N_2}-mg=0 \\\\xrightarrow{g=10N/kg} F_{N_2}=10m$\\n\\n$f_{s,\\\\max}=\\\\mu_sF_{N_2} \\\\xrightarrow{\\\\mu_s=0/5} f_{s,\\\\max}=0/5\\\\times 10m=5m$\\n\\n$R^2=f_{s,\\\\max}^2+F_{N_2}^2 \\\\xrightarrow{R=100\\\\sqrt{5}N} 5\\\\times 10^4=25m^2+100m^2$\\n\\n$\\\\Rightarrow 5\\\\times 10^4=125m^2 \\\\Rightarrow m^2=5\\\\times 10^4/125=10^4/25$\\n\\n$\\\\Rightarrow m=10^2/5 \\\\Rightarrow m=20kg$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"7087\":41450,\"7157\":41170,\"9634\":56650},\"submittedQuestionIds\":[7087,9634,7157,7117,7180,9632,7190,7318,9655,7271,9611,9649,7086,9624,7267,7337,7130,9640,7339,7167,7142,7134,7283,7216,7093,9610,7305,7208,9608,9647,9734],\"totalTimeSpent\":11,\"questionTimes\":{\"7087\":2001,\"7157\":2002,\"9634\":1002},\"selectionLog\":[{\"questionId\":7087,\"optionId\":41450,\"timeSpentMs\":2001,\"timestamp\":1786387229268},{\"questionId\":9634,\"optionId\":56650,\"timeSpentMs\":1002,\"timestamp\":1786387231095},{\"questionId\":7157,\"optionId\":41170,\"timeSpentMs\":2002,\"timestamp\":1786387236175}]}}', '2026-08-10 18:40:38'),
(138, 40, 4, 5.88, 1, 4, 12, 0, 46, '{\"total_questions\":17,\"correct_count\":1,\"incorrect_count\":4,\"unanswered_count\":12,\"accuracy_rate\":5.88,\"score\":0,\"mabhas_stats\":{\"فصل دو دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل چهار یازدهم\":{\"correct\":0,\"incorrect\":2,\"unanswered\":3,\"total\":5},\"فصل یک یازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":4,\"total\":5},\"فصل دو یازدهم\":{\"correct\":1,\"incorrect\":1,\"unanswered\":4,\"total\":6}}}', '{\"evaluation\":{\"495\":{\"correct_option_id\":6415,\"descriptive_answer\":{\"text\":\"غشای پایه در مویرگ&zwnj;های کلافک (مویرگ&zwnj;های منفذدار)، ضخیم است و عبور مولکول&zwnj;های درشت مثل پروتئین&zwnj;ها را محدود می&zwnj;کند. به دنبال تخریب دیواره مویرگ&zwnj;های کلافک، موادی که قبلاً نمی&zwnj;توانستند در اثر تراوش از خون خارج شوند، فرصت خارج شدن از خون را پیدا می&zwnj;کنند و بنابراین پروتئین&zwnj;ها نیز از خون خارج می&zwnj;شوند. با خروج پروتئین&zwnj;ها از خون، فشار اسمزی خون کاهش می&zwnj;یابد. به شکل مقابل توجه کنید، با کاهش فشار اسمزی، (فشار اسمزی کاهش یافته، با خط آبی رنگ در شکل نشان داده شده است) محلی که فشار اسمزی و فشار خون با یکدیگر برابر می&zwnj;شوند، به انتهای مویرگ نزدیک&zwnj;تر می&zwnj;شود. بنابراین در قسمت&zwnj;های بیشتری از مویرگ فشار خون بیشتر از فشار اسمزی خواهد بود و مواد فرصت بیشتری برای خروج از مویرگ&zwnj;های خونی دارند. (حالا میخواد مویرگ&zwnj;های روده باشه یا هر جای دیگه! مهم اینه که فشار اسمزی خون کم شده) 1) با توجه به شماره گذاری&zwnj;های کتاب درسی برای مراحل چرخۀ ضربان قلب، مرحله سوم چرخۀ ضربان قلب، انقباض بطنی است. با کاهش مدت انقباض بطنی، حجم خون خارج شده از بطن&zwnj;ها و در نتیجه فشار خون کاهش می&zwnj;یابد. تراوش به کمک نیروی فشار خون انجام می&zwnj;گیرد و بنابراین با کاهش فشار خون، حجم موادی که طی تراوش از خون خارج می&zwnj;شوند نیز کاهش می&zwnj;یابد. 2) هیپوفیز پسین دو هورمون ضدادراری و اکسی&zwnj;توسین ترشح می&zwnj;کند. به دنبال عدم ترشح هورمون ضدادراری، مقدار زیادی ادرار رقیق از بدن دفع می&zwnj;شود. چنین حالتی به دیابت بی&zwnj;مزه معروف است. کار اصلی دستگاه لنفی، تصفیه و بازگرداندن آب و مواد دیگری است که از مویرگ&zwnj;ها به فضای میان&zwnj;بافتی نشت پیدا می&zwnj;کنند و به مویرگ&zwnj;ها بر نمی&zwnj;گردند. به دنبال عدم ترشح هورمون ضدادراری و دفع مقدار زیادی ادرار رقیق، آب بدن کم می&zwnj;شود! در نتیجه آبی که بخواهد توسط دستگاه لنفی به خون بازگردد نیز کم&zwnj;تر میشود، نه اینکه افزایش پیدا کند. 4) در فرایند انعقاد خونریزی&zwnj;های شدید، پروترومبین و فیبرینوژن که از پروتئین&zwnj;های محلول در خوناب&zwnj;اند، مصرف می&zwnj;شوند. بنابراین در خونریزی&zwnj;های شدید در نقاط مختلف بدن، مقدار زیادی از این پروتئین&zwnj;ها برای تشکیل لخته مصرف می&zwnj;شود و میزان پروتئین&zwnj;های محلول در خوناب کاهش می&zwnj;یابد. با کاهش پروتئین&zwnj;های خوناب، فشار اسمزی خون فشاری که مسبب بازگشت مواد به مویرگ&zwnj;های خونی می&zwnj;شود نیز کاهش می&zwnj;یابد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل چهار یازدهم\",\"selected_option_id\":6413,\"is_answered\":true},\"7865\":{\"correct_option_id\":44414,\"descriptive_answer\":{\"text\":\"گام اول، ابتدا در شکل (الف) نقاط هم پتانسیل را\\r\\n\\r\\nنام گذاری می کنیم تا وضعیت متوالی یا موازی بودن مقاومت ها مشخص\\r\\n\\r\\nشود (توجه کنید که مقاومت آمپرسنج آرمانی صفر است و مانند یک\\r\\n\\r\\nسیم بدون مقاومت در مدار عمل می کند). همین طور که در شکل (ب)\\r\\n\\r\\nنشان داده ایم، هر چهار مقاومت $30Ω$، $6Ω$، $18Ω$ و $24Ω$ با یکدیگر\\r\\n\\r\\nموازی هستند؛ بنابراین اختلاف پتانسیل دو سر آن ها یکسان و برابر با\\r\\n\\r\\nاختلاف پتانسیل دو سر باتری (یعنی $ε$) است.\\r\\n\\r\\nگام دوم. حالا به شکل (پ) نگاه کنید. یکی از آمپرسنج های آرمانی، جریان الکتریکی گذرنده از دو\\r\\n\\r\\nمقاومت $6Ω$ و $30Ω$ و یکی دیگر از آمپرسنج های آرمانی، جریان الکتریکی گذرنده از دو مقاومت $6Ω$\\r\\n\\r\\nو $24Ω$ را نشان می دهد.\\r\\n\\r\\n$I = I6Ω + I24Ω$          $I\' = I6Ω + I30Ω$\\r\\n\\r\\nبا توجه به اختلاف پتانسیل دو سر مقاومت ها، برای محاسبه جریان الکتریکی گذرنده از مقاومت های\\r\\n\\r\\n$24Ω$، $6Ω$ و $30Ω$ می توان نوشت:\\r\\n\\r\\n$I = V / R → V=ε →$\\r\\n\\r\\n$I24Ω = ε / 24$\\r\\n\\r\\n$I6Ω = ε / 6$\\r\\n\\r\\n$I30Ω = ε / 30$\\r\\n\\r\\nبنابراین $I$ و $I\'$ برابر است با:\\r\\n\\r\\n$I = I6Ω + I24Ω → I6Ω=ε/6 , I24Ω=ε/24 → I = ε/6 + ε/24 ⇒ I = 5ε/24$\\r\\n\\r\\n$I\' = I6Ω + I30Ω → I6Ω=ε/6 , I30Ω=ε/30 → I\' = ε/6 + ε/30 ⇒ I\' = ε/5$\\r\\n\\r\\nگام سوم، طبق گفته سؤال اختلاف دو عددی که آمپرسنج های آرمانی نشان می دهند، برابر با $50mA$ است؛ بنابراین داریم:\\r\\n\\r\\n$I - I\' = 50 × 10^-3 → I=5ε/24 , I\'=ε/5 → 5ε/24 - ε/5 = 1/20 ⇒ 25ε - 24ε / 5 × 24 = 1/20 ⇒ ε = 6V$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7928\":{\"correct_option_id\":44169,\"descriptive_answer\":{\"text\":\"$19$ - گزینه «$2$» مقاومت معادل مدار را در دو حالت به‌دست می‌آوریم. چون مقاومت‌ها موازی‌اند، داریم: $1 / R_{eq} = 1 / 12 + 1 / 4 => R_{eq} = 3 Ω$ $1 / R\'_{eq} = 1 / 12 + 1 / 12 => R\'_{eq} = 6 Ω$ چون به‌ازای $R_{eq} = r = 4 Ω$ توان خروجی مولد بیشینه می‌شود، بنابراین با توجه به نمودار توان خروجی برحسب مقاومت معادل مدار، وقتی مقاومت از $3Ω$ به $4Ω$ می‌رسد، توان خروجی افزایش و پس از آن وقتی از $4Ω$ به $6Ω$ می‌رسد، توان خروجی کاهش می‌یابد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":44170,\"is_answered\":true},\"7930\":{\"correct_option_id\":44162,\"descriptive_answer\":{\"text\":\"$21$ - گزینه «$3$» در این‌گونه سؤالات ابتدا باید تک‌تک گره‌ها را نام‌گذاری کنیم. گره محل اتصال حداقل سه سیم است. در این‌جا با نام‌گذاری گره‌ها، مقاومت $4Ω$ بین دو نقطه هم‌پتانسیل قرار می‌گیرد و اتصال کوتاه می‌شود و از مدار حذف می‌شود. بنابراین با رسم مجدد شکل به‌صورت زیر مقاومت معادل را می‌یابیم. $R\' = 24 × 12 / 12 + 24 = 8 Ω , R\'\' = 8 + 8 = 16 Ω , R\'\'\' = 16 / 2 = 8 Ω$ $R_T = 8 + 6 = 14 Ω$\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":44162,\"is_answered\":true},\"7955\":{\"correct_option_id\":44062,\"descriptive_answer\":{\"text\":\"$46$ - گزینه «$3$» در حالت اول، چون $I$ و $R$ معلوم اند، با استفاده از رابطه $P = RI^2$ ، توان خروجی مولد را می یابیم: $P = RI^2 → R=20Ω / I=2A → P = 20 × 4 ⇒ P = 80 W$ در حالت دوم، چون جریان مقاومت $20Ω$ معلوم است، ابتدا جریان مقاومت $80Ω$ را می یابیم سپس از مجموع جریان این دو مقاومت، جریان اصلی مدار را حساب می کنیم و در آخر با محاسبه مقاومت معادل مدار، توان خروجی در مدار دوم را پیدا می کنیم. $V1 = V2 ⇒ R1I1 = R2I2 ⇒ 20 × 1/92 = 80 × I2$ $⇒ I2 = 0/48 A$ $I\' = I1 + I2 = 1/92 + 0/48 ⇒ I\' = 2/4 A$ $R\'eq = R1R2 / R1 + R2 = 20 × 80 / 20 + 80 ⇒ R\'eq = 16Ω$ $P\' = R\'eq I\'^2 = 16 × 5/76 ⇒ P\' = 92/16 W$ در نهایت داریم: $P\' - P = 92/16 - 80 ⇒ P\' - P = 12/16 W$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8043\":{\"correct_option_id\":43704,\"descriptive_answer\":{\"text\":\"134 - گزینه «1» برای محاسبه اختلاف پتانسیل دو سر مقاومت $R1$ باید جریان الکتریکی $I$ معلوم باشد. به همین منظور، ابتدا مقاومتی که بیشترین توان را مصرف می‌کند، می‌یابیم و توان الکتریکی آن را معادل $128W$ در نظر می‌گیریم و جریان الکتریکی $I$ را تعیین می‌کنیم. بنابراین، با توجه به شکل زیر، چون مقاومت‌های $(R3 , R2)$ و $(R5 , R4)$ با هم موازی‌اند، می‌توان نوشت: $VCB = (R2 + R3)I1 = (R4 + R5)I2 ⇒ (18 + 6)I1 = (8 + 4)I2$ $⇒ 24I1 = 12I2 ⇒ I2 = 2I1$ $I = I1 + I2 ⇒ I = I1 + 2I1 ⇒ I = 3I1 ⇒ I1 = 1/3 I , I2 = 2/3 I$ اکنون توان الکتریکی مصرفی هریک از مقاومت‌ها را برحسب جریان $I$ می‌یابیم: $P1 = R1I 2 ⇒ P1 = 2 × I 2 = 2I 2$ $P2 = R2I1 2 = 18 × (1/3 I) 2 ⇒ P2 = 2I 2$ $P3 = R3I1 2 = 6 × (1/3 I) 2 ⇒ P3 = 2/3 I 2$ $P4 = R4I2 2 = 8 × (2/3 I) 2 ⇒ P4 = 32/9 I 2$ $P5 = R5I2 2 = 4 × (2/3 I) 2 ⇒ P5 = 16/9 I 2$ می‌بینیم، مقاومت $R4$ بیشترین توان را مصرف می‌کند. بنابراین می‌توان نوشت: $P4 = 32/9 I 2 → P4=128W → 128 = 32/9 I 2 ⇒ I 2 = 36 ⇒ I = 6A$ در آخر داریم: $V1 = R1I = 2 × 6 ⇒ V1 = 12V$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8065\":{\"correct_option_id\":43548,\"descriptive_answer\":{\"text\":\"دو مقاومت $R1$ و $R2$ با هم موازی‌اند و ولتاژ آن‌ها با هم برابر است. از این‌رو نسبت توان آن‌ها به نسبت معکوس مقاومت آن‌ها است.\\r\\n\\r\\n$P = V 2 / R => P1 / P2 = R2 / R1 => 20 / 30 = R2 / R1 => R2 = 3 / 2 R1$\\r\\n\\r\\n$R1,2 = (R1 R2) / (R1 + R2) = (R1 x 3 / 2 R1) / (R1 + 3 / 2 R1) = 3 / 5 R1$\\r\\n\\r\\nمقاومت معادل $R1$ و $R2$ با مقاومت $R3$ متوالی است و نسبت توان آن‌ها به نسبت مقاومت آن‌ها است.\\r\\n\\r\\n$P = RI 2 => P1,2 / P3 = R1,2 / R3 => (20W + 30W) / 40W = (3 / 5 R1) / R3 => R3 / R1 = 8 / 25$\\r\\n\\r\\nتذکر: با توجه به پایستگی انرژی، توانی که مجموعه‌ای از مقاومت‌ها در یک مدار مصرف می‌کنند، بدون در نظر گرفتن اینکه متوالی، موازی و یا ترکیب آن‌ها به هم متصل‌اند، همواره برابر با جمع جبری توان مصرفی آن‌ها است. به‌عنوان مثال، توان مصرفی کل مدار فوق برابر با $90W$ است.\\r\\n\\r\\n$Pt = 20W + 30W + 40W = 90W$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"9734\":{\"correct_option_id\":57051,\"descriptive_answer\":{\"text\":\"چون نردبان در آستانه سر خوردن است، نیروی خالص وارد بر آن صفر است. بنابراین، نیروهای وارد بر نردبان را رسم می کنیم، و سپس با توجه به این که، نیروی زمین بر نردبان برابر برآیند دو نیروی $f_{s,\\\\max}$ و $F_{N_2}$ است، به صورت زیر $m$ را پیدا می کنیم:\\n\\n$F_{N_1}$\\n\\n$f_{s,\\\\max}$\\n\\n$mg$\\n\\n$F_{N_2}$\\n\\n$F_{net_y}=0 \\\\Rightarrow F_{N_2}-mg=0 \\\\xrightarrow{g=10N/kg} F_{N_2}=10m$\\n\\n$f_{s,\\\\max}=\\\\mu_sF_{N_2} \\\\xrightarrow{\\\\mu_s=0/5} f_{s,\\\\max}=0/5\\\\times 10m=5m$\\n\\n$R^2=f_{s,\\\\max}^2+F_{N_2}^2 \\\\xrightarrow{R=100\\\\sqrt{5}N} 5\\\\times 10^4=25m^2+100m^2$\\n\\n$\\\\Rightarrow 5\\\\times 10^4=125m^2 \\\\Rightarrow m^2=5\\\\times 10^4/125=10^4/25$\\n\\n$\\\\Rightarrow m=10^2/5 \\\\Rightarrow m=20kg$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11030\":{\"correct_option_id\":62565,\"descriptive_answer\":{\"text\":\"\\nموارد «ب و د» درست هستند.\\n\\nبررسی همۀ موارد:\\n\\nالف) نخاع مرکز برخی از انعکاس‌های بدن است.\\n\\nب) تالاموس و نخاع هردو در انتقال پیام‌های حسی به قشر مخ نقش دارند. همۀ پیام حسی از نخاع وارد مغز نمی‌شوند. همۀ پیام حسی نیز از تالاموس نمی‌گذرند.\\n\\nج) برخی از پیام‌های حسی بدن مانند بینایی از نخاع عبور نمی‌کند.\\n\\nد) برجستگی‌های چهارگانه بخشی از مغز میانی بوده، برخلاف هیپوتالاموس در شنوایی و بینایی نقش دارد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11031\":{\"correct_option_id\":62570,\"descriptive_answer\":{\"text\":\"\\nموارد «ب»، «ج» و «د» به‌درستی بیان شده‌اند.\\n\\nآنتوسیانین یکی از ترکیبات رنگی است که در واکوئول ذخیره می‌شود. آنتوسیانین در ریشۀ چغندر قرمز و برگ کلم بنفش و میوه‌هایی مانند پرتقال توسرخ، به مقدار فراوانی وجود دارد.\\nمشخص شده است که ترکیبات رنگی در واکوئول و رنگ‌دیسه، پاد اکسنده (آنتی‌اکسیدان) اند. ترکیبات پاد اکسنده در پیشگیری از سرطان و نیز بهبود کارکرد مغز و اندام‌های دیگر نقش مثبتی دارند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11037\":{\"correct_option_id\":62593,\"descriptive_answer\":{\"text\":\"\\nموارد (ج) و (د) عبارت را به طور مناسب کامل می‌کنند.\\n\\nبررسی همۀ موارد:\\n\\nالف) لوب پس‌سری و لوب گیجگاهی در مجاورت مخچه قرار گرفته است. لوب پس‌سری در مجاورت دو لوب دیگر آن نیمکره و لوب گیجگاهی در مجاورت سه لوب دیگر آن نیمکره قرار گرفته است.\\n\\nب) لوب پیشانی اندازۀ بزرگ‌تری از سایر لوب‌های مخ دارد. این لوب در مجاورت دو لوب دیگر آن نیمکره مخ قرار دارد.\\n\\nج )لوب گیجگاهی در نمای مغز از بالا دیده نمی‌شود. این لوب، در مجاورت سه لوب دیگر از آن نیمکره مخ قرار گرفته است.\\n\\nد )لوب پس‌سری توانایی دریافت پیام از گیرنده‌های بینایی را دارد. این لوب از مخ، با دو لوب دیگر از آن نیمکره مخ در مجاورت است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11088\":{\"correct_option_id\":62799,\"descriptive_answer\":{\"text\":\"\\nهر دو نورون حرکتی این مسیر، متعلق دستگاه عصبی پیکری هستند.\\nرابط‌ها با این نورون‌ها، همایه دارند که پس از در تخلیهٔ سیناپسی میتوانند ناقل‌ها را با تشکیل ریزکیسه و درون‌بری به سیتوپلاسم خود وارد کنند.\\n\\nبررسی سایر گزینه‌ها:\\n\\n$1$ جسم یاخته‌ای نورون حسی، از یک نقطه به دو نوع ساختار رشته‌مانند (دندریت و آکسون) اتصال دارد. این نورون حسی، تحریک می‌شوند نه مهار!\\n\\n$2$ نورون رابط و حرکتی می‌توانند توسط جسم یاخته‌ای خود پیام را دریافت کنند. تنها نورون حسی توسط بلندترین رشتهٔ عصبی خود، پیام عصبی را به ریشهٔ پشتی نخاع وارد می‌کند.\\n\\n$3$ هیچ‌یک از این نورون‌ها توسط دارینهٔ خود به دیوارهٔ نخاع اتصال ندارند!\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11089\":{\"correct_option_id\":62802,\"descriptive_answer\":{\"text\":\"\\nآزادسازی ناقل عصبی در خارج از نخاع، به همایهٔ میان نورون حرکتی و ماهیچهٔ دوسر مربوط است. ابتدا باید پیام عصبی در ریشهٔ شکمی نخاع هدایت شود و سپس با رسیدن به محل همایه، ناقل عصبی خارج شود. برای هدایت پیام در طول رشتهٔ عصبی، بازشدن کانال‌های دریچه‌دار لازم است.\\n\\nبررسی سایر گزینه‌ها:\\n\\n$1$ نخستین ناقل عصبی مهاری، در همایهٔ بین یاختهٔ عصبی رابط و یاختهٔ عصبی مربوط به ماهیچهٔ سه‌سر آزاد می‌شود. در حالی که هدایت پیام در ریشهٔ شکمی نخاع، مربوط به بعد از برقراری این همایه و هدایت پیام به سوی ماهیچه است.\\n\\n$2$ اولین همایه در مادهٔ خاکستری نخاع، بین یاختهٔ عصبی حسی و یاخته‌های عصبی رابط برقرار می‌شود. یاخته‌های عصبی که دارینه‌شان در نخاع حضور دارد، یاختهٔ عصبی رابط و حرکتی هستند. هدایت پیام در هر دو یاختهٔ عصبی مذکور، پس از شکل‌گیری همایه بین یاختهٔ عصبی حسی و رابط است.\\n\\n$4$ همایه‌ای که خارج از دستگاه عصبی مرکزی برقرار می‌شود مربوط به همایهٔ بین یاخته‌های عصبی حرکتی و ماهیچه‌های دوسر و سه‌سر است. دقت کنید انقباض ماهیچهٔ دوسر پس از برقراری همایه است، نه قبل از آن!\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":62803,\"is_answered\":true},\"11328\":{\"correct_option_id\":63759,\"descriptive_answer\":{\"text\":\"\\nتیروئید غدۀ سپری شکل است که در پرکاری آن، به علت متابولسیم بالای بدن، میزان دمای بدن افزایش می یابد. اما باید دقت کنید که در پرکاری تیروئید (نه کم کاری آن!) به علت مصرف زیاد گازهای تنفسی، مقدار مصرف انرژی توسط ماهیچه های تنفسی و میزان تنفس افزایش پیدا می کند. \\n\\nبررسی سایر گزینه ها:\\n $1$ غدۀ متصل به هیپوتالاموس، هیپوفیز است. در صورت پرکاری این غده، هورمون رشد به میزان زیادی ترشح می شود که نتیجۀ آن افزایش طول استخوان ران است که در به تبع آن، فاصلۀ بین دو صفحۀ رشد موجود در ساختار استخوان ران نیز افزایش می یابد. کاهش ترشح هورمون پرولاکتین در کم کاری غدۀ هیپوفیز ممکن است دیده شود که نتیجۀ آن نیز بروز اختلال در عملکرد دستگاه ایمنی است. \\n\\n$2$ غدد پاراتیروئیدی به پشت غدۀ سپری شکل (تیروئید) متصل هستند. در پرکاری غدد پاراتیروئیدی، برداشت کلسیم از استخوان افزایش یافته و در نتیجۀ آن احتمال بروز شکستگی استخوان ها بیشتر می شود. در کاهش فعالیت این غده، غلظت کلسیم خون کاهش می یابد که به دنبال آن، تشکیل لختۀ خون (وابسته به کلسیم!) دچار اختلال می شود و احتمال بروز خون ریزی بیشتر می شود.\\n\\n $3$ غدد فوق کلیوی بر روی اندامی لوبیایی شکل (کلیه) قرار دارند. در پرکاری این غدد، به علت اثر کورتیزول فعالیت دستگاه ایمنی (مثل فعالیت درشت خوارها) دچار اختلال می شود. با کاهش ترشح آلدوسترون در کم کاری غدد فوق کلیوی، دفع سدیم از طریق ادرار افزایش پیدا می کند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل چهار یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11331\":{\"correct_option_id\":63771,\"descriptive_answer\":{\"text\":\" \\nهورمون هایی که به طور مستقیم باعث تنظیم کار غده های جنسی در مرد و زن می شوند، هورمون های محرک غدد جنسی هستند. یعنی $2$ هورمون $LH$ و $FSH$\\n\\n بررسی سایر گزینه ها:\\n $1$ هورمون هایی که به طور مستقیم روی میزان کلسیم موجود در استخوان ها مؤثرند، $3$ هورمون کلسی تونین، هورمون پاراتیروئیدی و هورمون رشد هستند. چطور؟! هورمون کلسی تونین از برداشت کلسیم استخوان ها جلوگیری می کند. هورمون پاراتیروئیدی، کلسیم را از مادۀ زمینه ای استخوان جدا می کند. هورمون رشد باعث ایجاد یاخته های استخوانی جدید توسط صفحات رشد می شود و با این کار، از طریق استخوانی شدن یاخته ها، باعث رسوب کلسیم در مادۀ زمینه ای استخوان می شود.\\n\\n $2$ هورمون هایی که به طور مستقیم از بخش قشری غدۀ فوق کلیه ترشح می شوند :کورتیزول، آلدوسترون و هورمون های جنسی است.\\n\\n $3$ در سطح اطلاعات کتاب درسی، هورمون هایی که به طور مستقیم باعث افزایش قند خون می شوند، حداقل $4$ هورمون گلوکاگون، اپی نفرین، نور اپی نفرین و کورتیزول هستند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل چهار یازدهم\",\"selected_option_id\":63770,\"is_answered\":true},\"11344\":{\"correct_option_id\":63823,\"descriptive_answer\":{\"text\":\"\\n اپی فیز، در سطح زیرین بطن سوم قرار دارد. بطن سوم، بطن مغزی دریافت کنندۀ نوعی مایع از دو بطن مغزی دیگر (بطن های $1$ و $2$) است. \\nهورمونی که میزان ترشح هورمون های محرک جنسی را تنظیم می کند، هورمون آزادکننده و مهارکننده است که بر اپی فیز اثری ندارد.\\n\\n بررسی سایر گزینه ها:\\n $1$ هیپوفیز، در یک گودی از ساختار نوعی استخوان جمجمه قرار دارد. این غده برای هورمون تیروئیدی گیرنده دارد. هورمون تیروئیدی در یاخته های بافت چربی نیز واجد گیرنده می باشد. \\n\\n$2$ غدۀ تیروئید، با نای تماس دارد. نای ساختار حاوی غضروف $C$ شکل در بخش هادی دستگاه تنفسی انسان است. غدۀ تیروئید برای هورمون محرک تیروئیدی گیرنده دارد. این هورمون از هیپوفیز پیشین (بخش جلویی تر هیپوفیز) ترشح می شود. \\n\\n$3$ غدد پاراتیروئیدی پرتعدادترین غدد درون ریز بدن انسان هستند. این غدد، برای هورمون های تیروئیدی گیرنده دارند. افزایش میزان ترشح این هورمون ها سبب افزایش تنفس سلولی و افزایش تولید کربن دی اکسید می شود که در نتیجۀ آن، عملکرد انیدراز کربنیک افزایش می یابد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل چهار یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"11345\":{\"correct_option_id\":63824,\"descriptive_answer\":{\"text\":\"\\n منظور صورت سؤال بیماری های دیابت شیرین و دیابت بی مزه می باشد. در دیابت شیرین، به دلیل مصرف پروتئین ها و آمینواسیدها برای تولید انرژی، تولید آمونیاک و اوره بیشتر می شود. از سوی دیگر، در دیابت شیرین برخلاف دیابت بی مزه به دلیل تخریب پروتئین های ایمنی (تضعیف دستگاه ایمنی) و همچنین به دلیل ورود گلوکز به مجاری ادراری، ریسک بروز عفونت های ادراری بیشتر می شود.\\n\\n بررسی سایر گزینه ها: \\n$2$ دقت کنید در هر دو بیماری ممکن است به علت کاهش حجم آب بدن، ترشح هورمون آلدوسترون بیشتر شود و در نتیجه در چنین شرایطی، میزان بازجذب یون سدیم بیشتر می شود.\\n\\n $3$ دقت کنید در هر دو بیماری بازجذب گلوکز از ادرار دیده می شود؛ اما این بازجذب گلوکز در بیماری دیابت شیرین بیشتر است؛ زیرا میزان گلوکز بیشتری از طریق کلافک، تراوش پیدا کرده است و در نتیجه بدن نیز مقدار بیشتری بازجذب می کند؛ اما هم چنان بخشی از آن در ادرار باقی می ماند.\\n\\n $4$ توجه کنید در هردو بیماری به علت اختلال در میزان آب بدن، احتمال اختلال در هم ایستایی یون های سدیم و پتاسیم وجود دارد و این یون ها در تولید پیام عصبی و برقراری حالت آرامش در نورون ها مؤثر هستند. هم چنین در دیابت شیرین ممکن است یاخته های مغزی نتوانند از گلوکز استفاده کنند و دچار اختلال شوند. از طرف دیگر، هم چنین محصولات اسیدی تولید شده در دیابت شیرین کنترل نشده، می توانند باعث آسیب به یاخته های عصبی شوند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل چهار یازدهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"495\":6413,\"7928\":44170,\"7930\":44162,\"11089\":62803,\"11331\":63770},\"totalTimeSpent\":46,\"questionTimes\":{\"7930\":1001,\"9734\":15977,\"11331\":1001},\"selectionLog\":[{\"questionId\":495,\"optionId\":6413,\"timeSpentMs\":0,\"timestamp\":1786480254358},{\"questionId\":11089,\"optionId\":62803,\"timeSpentMs\":0,\"timestamp\":1786480256226},{\"questionId\":7928,\"optionId\":44170,\"timeSpentMs\":0,\"timestamp\":1786480257183},{\"questionId\":7930,\"optionId\":44162,\"timeSpentMs\":1001,\"timestamp\":1786480258317},{\"questionId\":11331,\"optionId\":63770,\"timeSpentMs\":1001,\"timestamp\":1786480259506}],\"lobbyCode\":\"RAYKkAVwYr\"}}', '2026-08-11 20:31:07');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(139, 41, 108, 60.00, 12, 4, 4, 50, 1188, '{\"total_questions\":20,\"correct_count\":12,\"incorrect_count\":4,\"unanswered_count\":4,\"accuracy_rate\":60,\"score\":50,\"mabhas_stats\":{\"فصل پنج دهم\":{\"correct\":3,\"incorrect\":1,\"unanswered\":0,\"total\":4},\"فصل سه دهم\":{\"correct\":3,\"incorrect\":1,\"unanswered\":0,\"total\":4},\"فصل یک دهم\":{\"correct\":1,\"incorrect\":0,\"unanswered\":1,\"total\":2},\"فصل دو دهم\":{\"correct\":2,\"incorrect\":1,\"unanswered\":2,\"total\":5},\"فصل چهار دهم\":{\"correct\":3,\"incorrect\":1,\"unanswered\":1,\"total\":5}}}', '{\"evaluation\":{\"337\":{\"correct_option_id\":5579,\"descriptive_answer\":{\"text\":\"لیپیدهایی که در روده باریک جذب می شوند، وارد رگ های لنفی میشوند و بنابراین، به سیاهرگ باب کبدی وارد نمی شوند و از مسیری دیگر به کبد می روند علاوه بر این بخشی از لیپیدها نیز در بافت چربی ذخیره می شوند. بررسی سایر گزینه ها: ۱) مقداری از آهن جذب شده در روده، در کبد ذخیره می شود و در نتیجه، در سیاهرگ فوق کبدی (سیاهرگ خروجی از کبد)، نسبت به سیاهرگ (باب کبدی سیاهرگ ورودی به کبد)، مقدار کمتری آهن وجود دارد. 2) خون سیاهرگی پانکراس و معده ابتدا وارد سیاهرگ باب کبدی میشود. ۴) همانطور که در شکل مشخص است، سیاهرگ مربوط به طحال و کولون پایین رو به یکدیگر می پیوندند و یک سیاهرگ مشترک به سیاهرگ باب کبدی می ریزد.\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":5579,\"is_answered\":true},\"475\":{\"correct_option_id\":5371,\"descriptive_answer\":{\"text\":\"در فرایند انعقاد خون بافت&zwnj;های آسیب&zwnj;دیده (مانند یاخته&zwnj;های آسیب&zwnj;دیده دیواره رگ&zwnj;ها) و پلاکت&zwnj;های آسیب&zwnj;دیده، آنزیم پروترومبیناز ترشح می&zwnj;کنند. این آنزیم باعث تجزیه پروترومبین به ترومبین و افزایش مقدار ترومبین در خون می&zwnj;شود. 1) پلاکت&zwnj;ها همانند نوتروفیل&zwnj;ها دانه&zwnj;های کوچک دارند. دقت داشته باشید که پلاکت&zwnj;ها بدون رنگ و بدون هسته می&zwnj;باشند اما یاخته محسوب نمی&zwnj;شوند و قطعات یاخته&zwnj;ای هستند. 2) آنزیم پروترومبیناز ترشح&zwnj;شده از پلاکت&zwnj;ها و همچنین پروتئین&zwnj;های انعقادی خوناب (نظیر فیبرینوژن)، در تشکیل لخته خون مؤثر هستند. 4) پلاکت&zwnj;ها به چند طریق از هدر رفتن خون جلوگیری می&zwnj;کنند. در خونریزی&zwnj;های محدود، که دیواره رگ&zwnj;ها آسیب جزئی می&zwnj;بیند، در محل آسیب پلاکت&zwnj;ها دور هم جمع می&zwnj;شوند، به هم می&zwnj;چسبند و ایجاد درپوش می&zwnj;کنند. اما ویتامین K و یون کلسیم در فرایند تشکیل لخته خون مورد نیاز هستند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":5371,\"is_answered\":true},\"479\":{\"correct_option_id\":5366,\"descriptive_answer\":{\"text\":\"موارد (الف) و (د)، درست هستند. الف) در بیشتر موارد، بازجذب فعال است و با صرف انرژی انجام می&zwnj;گیرد؛ گرچه بازجذب ممکن است غیر&zwnj;فعال باشد. ترشح نیز در بیشتر موارد به روش فعال و با صرف انرژی زیستی انجام می&zwnj;گیرد. ج) یاخته&zwnj;های سنگفرشی در کپسول بومن دیده می&zwnj;شوند و در کپسول بومن، مرحلۀ تراوش انجام می&zwnj;شود که طی آن بخشی از مواد سمی از خون خارج می&zwnj;شوند. اما ترشح نیز که توسط یاخته&zwnj;های مکعبی شکل نفرون انجام می،شود، در دفع بعضی از سموم و داروها نقش دارد. د) دو فرایند بازجذب و ترشح، مایع تراوش شده را هنگام عبور از بخش لوله&zwnj;ای نفرون (لوله پیچ&zwnj;خورده نزدیک، قوس هنله و لوله پیچ&zwnj;خورده دور) و مجرای جمع&zwnj;کننده، تغییر می&zwnj;دهند و آنچه به لگنچه می&zwnj;ریزد، ادرار است. همه این قسمت&zwnj;هایی که در بازجذب و ترشح نقش دارند، ساختار لوله&zwnj;ای دارند.\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":5366,\"is_answered\":true},\"492\":{\"correct_option_id\":6033,\"descriptive_answer\":{\"text\":\"نایژه اصلی متصل به شش دارای لوب&zwnj;های بیشتر، نایژه اصلی راست است که مطابق شکل مقابل، نایژه اصلی راست دارای طول کمتر و قطر بیشتری نسبت به نایژه اصلی سمت مقابل است. 2) می&zwnj;دانیم که تعداد لوب&zwnj;های شش راست، بیشتر از همین تعداد در شش چپ می&zwnj;باشد. در نتیجه میزان هوای ورودی به شش راست مقداری بیشتر از شش چپ می&zwnj;باشد، به همین دلیل می&zwnj;توان گفت میزانی از هوا که توسط نایژه راست منتقل می&zwnj;شود، بیشتر از نایژه چپ می&zwnj;باشد. 3) نایژه اصلی راست در انتهای خود به دو انشعاب اصلی تقسیم می&zwnj;شود، در حالی که نایژه اصلی چپ در انتهای خود به بیش از دو انشعاب ختم می&zwnj;گردد. 4) در هر دو نایژه اصلی مقایسه شده در سؤال، حلقه&zwnj;ها و قطعات غضروفی مشاهده می&zwnj;شود.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":6033,\"is_answered\":true},\"526\":{\"correct_option_id\":4948,\"descriptive_answer\":{\"text\":\"غضروف دنده&zwnj;های ۸ تا ۱۰ به غضروف دنده بالاتر از خود متصل شده و به واسطه غضروف دنده ۷ به جناغ متصل می&zwnj;شوند. دنده&zwnj;های ۶ و ۷ غضروف مستقلی دارن! 1) مطابق با شکل مقابل، در هنگام بازدم باریک&zwnj;ترین بخش جناغ در سطح پایین&zwnj;تری نسبت به ماهیچه دیافراگم قرار دارد. 2) محل دو&zwnj;شاخه&zwnj;شدن نای، در سطح پایین&zwnj;تری نسبت به محل اتصال دندۀ اول به جناغ قرار دارد. 3) جناغ، استخوان منفرد قفسه سینه است. بخش بالایی جناغ به شکل ذوزنقه&zwnj;ای بوده و قاعدۀ بزرگ&zwnj;تری در سمت بالا نسبت به پایین دارد.\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":4948,\"is_answered\":true},\"529\":{\"correct_option_id\":5339,\"descriptive_answer\":{\"text\":\"ممکن است گویچه&zwnj;های قرمز بدون عبور از مجاورت لوله پیچ&zwnj;خورده دور وارد رگ&zwnj;های اطراف لوله هنله شوند. 1) مطابق شکل لوله پیچ&zwnj;خورده نزدیک به قطورترین بخش لوله هنله متصل است. 2) در کپسول بومن یاخته&zwnj;های پودوسیت که هسته درشت&zwnj;تری نسبت به سایر یاخته&zwnj;ها دارند، دارای زوائد کوتاه و پامانند هستند. 4) مطابق با شکل مقابل، یکی از انشعابات سرخرگ وابران، از پشت لوله هنله عبور می&zwnj;کند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":5339,\"is_answered\":true},\"585\":{\"correct_option_id\":5821,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; منظور صورت سؤال، سرخرگ های کوچک قبل از مویرگ های خونی است. سرخرگ های کوچک نسبت به سرخرگ های بزرگ تر، رشته های کشسان کم تر و ماهیچه صاف بیشتری دارند (این نحوه بیان در کنکور دی ماه ۱۴۰۱ هم آمده است). بررسی سایر گزینه ها: 2) این مورد مربوط به گروهی از مویرگ های خونی است. 3) طبق متن کتاب، همۀ سرخرگ های کوچک به مویرگ منتهی می شوند که کوچک ترین رگ های خونی بدن هستند. 4) ساختار سرخرگ های کوچک باعث می شود با ورود خون، قطر آن ها تغییر زیادی نکند و در برابر جریان خون مقاومت کنند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":5821,\"is_answered\":true},\"601\":{\"correct_option_id\":5318,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; ظاهر این گزینه انگار که فقط درباره حشرات است، اما زهی خیال باطل! دقت کنید که علاوه بر حشرات، در جانوری مثل هیدر هم اکسیژن رسانی به یاخته ها، بدون دخالت دستگاه گردش مواد انجام می گیرد. زیرا همۀ یاخته ها می توانند با محیط تبادلات گازی داشته باشند. هیدر فاقد معده و لوله گوارش است. بررسی سایر گزینه ها: 1) تعبير قسمت اول: همۀ جانوران دارای گردش خون مضاعف. (مثل دوزیست بالغ و سایر مهره داران دارای قلب چهار حفره ای). در همه این جانوران، دهلیز راست خون تیره را دریافت می کند. 3) تعبیر قسمت اول: برخی خزندگان و پرندگان دریایی و بیابانی که آب شور مصرف می کنند یا در بیابان زندگی می کنند. همه این جانوران قلب چهار حفره ای دارند و در همۀ آن ها (حتی خزندگانی که جدایی بین بطن های آن ها کامل نیست)، می توان گفت حداقل به دلیل جدایی بین دهلیزها، خون درون این دو قسمت با هم ترکیب نمی شود. 4) تعبير قسمت اول: پستانداران نشخوار کننده. قلب این جانوران چهار حفره و معده آنها چهار قسمت دارد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":5319,\"is_answered\":true},\"622\":{\"correct_option_id\":6204,\"descriptive_answer\":{\"text\":\"انشعاب &laquo;۱&raquo; به دو انشعاب دیگر تقسیم می&zwnj;شود که با حرف A مشخص شده&zwnj;اند. یکی از این انشعاب&zwnj;ها (انشعاب پایینی) به سمت انتهای روده باریک و روده کور می&zwnj;رود و خون&zwnj;رسانی این قسمت&zwnj;ها را برعهده دارد. 1) انتهایی&zwnj;ترین قسمت سرخرگ با شمارۀ &laquo;۴&raquo; مشخص شده است. همانطور که در شکل مشخص است. این قسمت در خون&zwnj;رسانی قسمت&zwnj;های انتهایی روده باریک نقش دارد اما خون&zwnj;رسانی بنداره انتهای روده باریک را انجام نمی&zwnj;دهد. خون&zwnj;رسانی این بنداره مربوط به انشعاب A است. 2) باریک&zwnj;ترین قسمت سرخرگ قسمت &laquo;۴&raquo; و قطورترین قسمت آن، قسمت &laquo;۲&raquo; است. قسمت &laquo;۲&raquo; در خون&zwnj;رسانی کولون بالارو نقش دارد. 3) سرخرگی که خون&zwnj;رسانی آپاندیس را انجام می&zwnj;دهد با شماره &laquo;3&raquo; مشخص شده است. همانطور که در شکل مشخص است، این سرخرگ از پشت سرخرگ مشخص&zwnj;شده با حرف( A سرخرگ تغذیه کننده روده کور) عبور می&zwnj;کند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"627\":{\"correct_option_id\":6394,\"descriptive_answer\":{\"text\":\"همانطور که در شکل مشخص است، پس از یک دم عمیق، فرد می&zwnj;تواند با یک بازدم عادی (در اثر ویژگی کشسانی شش&zwnj;ها) و سپس بازدم عمیق (با کمک انقباض ماهیچه&zwnj;های بین دنده&zwnj;ای داخلی و ماهیچه&zwnj;های شکمی) حجمی از هوا را جابه&zwnj;جا کند که مجموع آن معادل با ظرفیت حیاتی است. 1) حجم ذخیره بازدمی (مربوط به بازدم عمیق در اثر انقباض ماهیچه شکمی)، حدود ۱۲۰۰ تا ۱۳۰۰ میلی&zwnj;لیتر است اما حجم ذخیره دمی (مربوط به دم عمیق در اثر انقباض ماهیچه گردنی)، حدود ۳۰۰۰ میلی&zwnj;لیتر و بیش از دو برابر حجم ذخیره بازدمی می&zwnj;باشد. 3) همانطور که در شکل مشخص است، پایین رفتن نمودار در اثر بازدم عمیق، می&zwnj;تواند بدون رخ دادن دم عمیق رخ دهد. در این حالت، مجموع تغییرات نمودار برابر با حجم جاری و حجم ذخیره بازدمی است. 4) در هنگام دم (هنگامی که دیافراگم به حالت مسطح در می&zwnj;آید) در این حالت، حدود یک سوم از هوای جاری (۱۵۰ میلی&zwnj;لیتر) به بخش&zwnj;های مبادله&zwnj;ای نمی&zwnj;رسد و در بخش هادی باقی می&zwnj;ماند که به آن، هوای مرده می&zwnj;گویند. دقت داشته باشید که به جز نایژک&zwnj;های مبادله&zwnj;ای، سایر نایژک&zwnj;ها مربوط به بخش هادی هستند و بنابراین بخشی از هوای مرده در نایژک&zwnj;ها نیز قرار دارد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":6396,\"is_answered\":true},\"659\":{\"correct_option_id\":6192,\"descriptive_answer\":{\"text\":\"باقی&zwnj;مانده شیره گوارشی موجود در روده باریک ابتدا به روده کور می&zwnj;رود و سپس وارد کولون بالارو می&zwnj;شود. بررسی سایر گزینه&zwnj;ها: 1) حرکات روده بزرگ نسبت به روده باریک کندتر انجام می&zwnj;شود. 2) همۀ یاخته&zwnj;های بدن برای انجام اعمال خود نیاز به تولید آنزیم در سیتوپلاسم خود دارند .در نتیجه هر دو دسته یاخته ذکر شده توانایی تولید آنزیم دارند. 3) یاخته&zwnj;های دیواره روده بزرگ آنزیم گوارشی ترشح نمی&zwnj;کنند اما توجه کنید که پرز مربوط به ساختار دیواره روده باریک است، نه روده بزرگ!\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"662\":{\"correct_option_id\":4748,\"descriptive_answer\":{\"text\":\"در خونریزی&zwnj;های محدود، که دیواره رگ&zwnj;ها آسیب جزئی می&zwnj;بیند، در محل آسیب، گرده&zwnj;ها دور هم جمع می&zwnj;شوند به هم می&zwnj;چسبند و ایجاد درپوش می&zwnj;کنند. در خونریزی&zwnj;های شدیدتر، گرده&zwnj;ها در تولید لخته خون نقش اصلی دارند. گرده ها قطعات یاخته&zwnj;ای بی&zwnj;رنگ و بدون هسته&zwnj;ای هستند که درون خود دانه&zwnj;های زیادی دارند و از گویچه&zwnj;های خون کوچک&zwnj;ترند. گرده&zwnj;ها در مغز استخوان، زمانی تولید می&zwnj;شوند که یاخته&zwnj;های بزرگی به نام مگاکاریوسیت قطعه&zwnj;قطعه و وارد جریان خون می&zwnj;شوند. بررسی سایر گزینه&zwnj;ها: 1) در انعقاد خونریزی&zwnj;های شدید وجود ویتامین K (نه یون K) و یون Ca در انجام روند انعقاد خون و تشکیل لخته لازم است. 2) در انعقاد خون طی خونریزی&zwnj;های محدود گرده&zwnj;ها (قطعات یاخته نه یاخته&zwnj;های خونی) دور هم جمع می&zwnj;شوند به هم می&zwnj;چسبند و ایجاد درپوش می&zwnj;کنند. 3) در خون&zwnj;ریزی&zwnj;های شدیدتر، گرده&zwnj;ها با آزاد کردن مواد و با کمک پروتئین&zwnj;های خوناب مثل فیبرینوژن لخته را ایجاد می&zwnj;کنند تشکیل لخته در محل زخم جلوی خون&zwnj;ریزی را می&zwnj;گیرد. لخته فقط مربوط به انعقاد خون در خون&zwnj;ریزی&zwnj;های شدید است.\"},\"status\":\"correct\",\"level\":\"آسان\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":4748,\"is_answered\":true},\"688\":{\"correct_option_id\":5236,\"descriptive_answer\":{\"text\":\"اگر سرخرگ آوران مسدود شود، خون به کلافک نمی&zwnj;رسد. در نتیجه، حجم خون درون کلافک و همچنین فشار خون درون آن کاهش پیدا می&zwnj;کند. تراوش به دلیل فشار خون انجام می&zwnj;شود، بنابراین کاهش فشار خون، باعث کاهش مقدار تراوش می&zwnj;شود. برعکس، اگر سرخرگ وابران مسدود شود خون در کلافک تجمع می&zwnj;یابد. در نتیجه، حجم خون درون کلافک و همچنین فشار خون درون آن افزایش پیدا می&zwnj;کند. با افزایش فشار خون، مقدار تراوش بالا می&zwnj;رود. بررسی سایر گزینه&zwnj;ها: 1) در سرخرگ وابران به دلیل مقدار آب کمتر و میزان پروتئین برابر با سرخرگ آوران، مقدار فشار اسمزی بیشتر است. 2) مقدار مواد دفعی و همچنین مواد مفید، در سرخرگ آوران بیشتر از سرخرگ وابران است. چون که طی تراوش مواد از کلافک خارج می&zwnj;شوند و خونی که به سرخرگ وابران می&zwnj;ریزد، مقدار کمتری از مواد دفعی و همچنین سایر مواد خارج&zwnj;شده طی تراوش دارد. 3) مطابق شکل ۵ سرخرگ وابران در ابتدا به ۲ شاخه تقسیم می&zwnj;شود. این شاخه&zwnj;ها شبکه مویرگی دور&zwnj;لوله&zwnj;ای را می&zwnj;سازند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":5236,\"is_answered\":true},\"698\":{\"correct_option_id\":5224,\"descriptive_answer\":{\"text\":\"همه موارد نادرست هستند. بررسی موارد: الف) دقت کنید که آب در کلیه همواره به صورت غیر&zwnj;فعال بازجذب می&zwnj;شود. ب) اوریک&zwnj;اسید (نه اوره) با رسوب در مفاصل باعث بیماری نقرس می&zwnj;شود. ج) آمونیاک (نه اوره) در نتیجه تجزیه موادی مانند آمینواسیدها ساخته می&zwnj;شود و بسیار سمی است. د) اوره (نه اوریک&zwnj;اسید) از ترکیب آمونیاک و کربن دی&zwnj;اکسید ساخته می&zwnj;شود.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":5222,\"is_answered\":true},\"764\":{\"correct_option_id\":5190,\"descriptive_answer\":{\"text\":\"در پارامسی، بعد از انجام گوارش در واکوئول گوارشی، مواد گوارش نیافته و دفعی در واکوئول باقی می&zwnj;مانند و واکوئول دفعی تشکیل می&zwnj;شود. برای دفع محتویات این واکوئول به خارج از یاخته، لازم است که واکوئول دفعی به منفذ دفعی در یاخته متصل شود و سپس، محتویات آن از طریق برون&zwnj;رانی (اگزوسیتوز) به خارج از یاخته دفع می&zwnj;شوند. بررسی سایر گزینه&zwnj;ها: 1) مولکول&zwnj;های پروتئینی غشا در انتشار تسهیل&zwnj;شده و انتقال فعال نقش دارند. یون&zwnj;ها، مانند یون سدیم نیز فقط از طریق انتشار تسهیل&zwnj;شده یا انتقال فعال می&zwnj;توانند از عرض غشا عبور کنند و سایر روش&zwnj;های عبور مواد از غشا (انتشار ساده اسمز، درون&zwnj;بری و برون&zwnj;رانی)، نقشی در جابه&zwnj;جایی یون&zwnj;ها ندارند. 3) عبور یک ذره بزرگ از غشای یاخته با روش درون&zwnj;بری (آندوسیتوز) یا برون&zwnj;رانی (اگزوسیتوز) انجام می&zwnj;شود. در برون&zwnj;رانی، ریز&zwnj;کیسه&zwnj;های جدا شده از دستگاه گلژی به سمت غشای یاخته می&zwnj;روند و با پیوستن به غشای یاخته، محتویات خود را به خارج از یاخته می&zwnj;ریزند. اما در درون&zwnj;بری، تشکیل ریزکیسه در اثر جدا شدن قسمتی از غشای یاخته رخ می&zwnj;دهد و دستگاه گلژی نقش مستقیم ندارد. 4) میتوکندری در تأمین انرژی برای یاخته نقش دارد و بنابراین، در انجام فعالیت&zwnj;های انرژی&zwnj;خواه یاخته مؤثر است. انتقال فعال، نوعی روش عبور مواد از عرض غشا است که با کمک پروتئین&zwnj;های غشایی انجام می&zwnj;شود و برای انجام آن، انرژی مورد نیاز است و بنابراین، میتوکندری نیز نقش دارد. اما انتشار تسهیل&zwnj;شده که نوعی روش دیگر عبور مواد از عرض غشا با کمک پروتئین&zwnj;های غشایی است بدون مصرف انرژی زیستی انجام می&zwnj;شود و برای انجام آن نیازی به فعالیت میتوکندری نیست.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":5190,\"is_answered\":true},\"1054\":{\"correct_option_id\":4398,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; موارد &laquo;الف&raquo; و &laquo;د&raquo; صحیح است. در دوران جنینی، مغز قرمز استخوان، کبد و طحال تولید یاخته های خونی و گرده ها را انجام می دهند که از بین آنها، مغز قرمز استخوان و طحال نوعی اندام لنفی هستند. الف) گروهی از گویچه های قرمز، روزانه تخریب می شوند؛ تخریب یاخته های خونی قرمز آسیب دیده و مرده در طحال و کبد انجام می شود. آهن آزاد شده در این فرایند یا در کبد ذخیره می شود و یا همراه خون به مغز قرمز استخوان می رود و در ساخت دوباره گویچه های قرمز مورد استفاده قرار می گیرد؛ بنابراین هر دو اندام ذکر شده همانند کبد (اندام سازنده لیپوپروتئین ها) به نوعی بر میزان آهن خون تأثیر گذارند. ب) یاخته های بنیادی، یاخته هایی تمایز نیافته با توانایی تقسیم و تولید چندین نوع یاخته مختلف هستند؛ مطابق اطلاعات کتاب درسی، در مغز قرمز استخوان برخلاف طحال یاخته های بنیادی وجود دارد که انواع مختلفی از یاخته ها مثل خونی و غیرخونی را می سازند. ج) به عنوان مثال لنف خارج شده از مغز قرمز استخوان دست راست، وارد مجرای لنفی راست می شود. د) ماکروفاژها و یاخته های دارینه ای حاصل تغییر شکل و تمایز مونوسیت های بافت پیوندی خون هستند. هر دو می توانند در مبارزه بدن با ویروس ها نقش داشته باشند؛ ماکروفاژها با فاگوسیتوز آنها (مثلا به دنبال اتصال آنها به پادتن ها) یاخته های دارینه ای با بلعیدن آنها و ارائه آنتی ژن های آنها به یاخته های غیر فعال! ماکروفاژها و یاخته های دارینه ای، در دستگاه لنفی بدن دیده می شوند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8251\":{\"correct_option_id\":51180,\"descriptive_answer\":{\"text\":\"موارد (ب) و (د) عبارت مورد نظر را به درستی تکمیل می کنند.\\n\\nبررسی همه موارد:\\n\\nالف همانطور که می دانید در کل نگری، زیست شناسان نمی توانند ویژگی سامانه های پیچیده را فقط از طریق مطالعه اجزای سازنده آن توضیح دهند و ارتباط بین اجزا مانند خود اجزا در تشکیل جاندار موثر بوده و کل سامانه، چیزی بیشتر از مجموع اجزای سازنده آن است.\\n\\nب در حوزه اخلاق زیستی، وضع قوانینی به منظور جلوگیری از سوءاستفاده ها ضرورت دارد. یکی از این سوءاستفاده ها می تواند تولید عامل بیماری زای مقاوم نسبت به داروهای رایج باشد.\\n\\nج همانطور که در متن کتاب درسی اشاره شده است، در شاخه نگرش بین رشته ای، استفاده از سایر رشته ها مانند مفاهیم مهندسی و آمار، به منظور شناخت بیشتر سامانه های زنده (نه غیرزنده!) صورت می گیرد.\\n\\nد در شاخه فناوری های اطلاعاتی و ارتباطی، انجام محاسبات در کوتاه ترین زمان ممکن، جمع آوری، تحلیل و بایگانی پژوهش های\\nزیست شناختی ممکن است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8281\":{\"correct_option_id\":51060,\"descriptive_answer\":{\"text\":\"پاسخ تشریحی نمک های صفراوی در یاخته های کبد (اندام سازنده صفرا) تولید می شوند. این یاخته ها توان پروتئین سازی دارند که می توانند توسط رناتن های متصل به شبکه آندوپلاسمی زبر ساخته شوند (اتصال رناتن به شبکه آندوپلاسمی).\\r\\n\\r\\nبررسی سایر گزینه ها:\\r\\n\\r\\n$ 1 $ مواد حاصل از گوارش لیپیدها، در کبد و بافت چربی ذخیره می شوند. یاخته های بافت چربی برخلاف کبد، لیپوپروتئین کم چگال تولید نمی کنند.\\r\\n\\r\\n$ 3 $ گلوتن نوعی پروتئین است و قابلیت جذب به صورت مستقیم را ندارد، بلکه اول باید تجزیه شود و سپس آمینواسیدهای سازنده آن قابل جذب هستند.\\r\\n\\r\\n$ 4 $ تولید گلیکوژن در بدن انسان توسط یاخته های ماهیچه ای و هم چنین یاخته های کبدی صورت می گیرد. آهن و برخی ویتامین های جذب شده، در کبد ذخیره می شوند؛ اما در ماهیچه خیر.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":51061,\"is_answered\":true},\"8303\":{\"correct_option_id\":50972,\"descriptive_answer\":{\"text\":\"مقصود صورت سؤال یاخته های اصلی و کناری معده و همچنین یاخته های بخش برون ریز پانکراس می باشد. به دنبال اثر گاسترین، روی یاخته های اصلی، ترشح پپسین، روی یاخته های کناری اسید معده و به دنبال اثر سکرتین روی یاخته های پانکراس بیکربنات افزایش می یابد. در هیچ یک از این حالات آنزیم تجزیه کننده لیپیدها، به دنبال اثر هورمون، تولید نمی شود.\\r\\n\\r\\nبررسی سایر گزینه ها:\\r\\n\\r\\n$ 1 $ در یاخته های کناری کیسه های غشایی به صورت واضح مشاهده نمی شوند. البته این گزینه صرفاً از روی شکل کتاب درسی برداشت شده و گرنه همه یاخته ها دارای کیسه های غشایی هستند.\\r\\n\\r\\n$ 3 $ یاخته های قرار گرفته در پانکراس، فاقد تماس با اسید معده هستند.\\r\\n\\r\\n$ 4 $ هسته ساختاری است که محل ذخیره اطلاعات وراثتی یاخته می باشد. در یاخته های اصلی معده، هسته می تواند به صورت کشیده مشاهده شود.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":50972,\"is_answered\":true},\"8319\":{\"correct_option_id\":50900,\"descriptive_answer\":{\"text\":\"انرژی موجود در مواد مغذی مانند گلوکز ابتدا بایستی در مولکول $ATP$ ذخیره شود. تولید $ATP$ در طی واکنش تنفس یاخته‌ای صورت می‌گیرد. در صورت افزایش تنفس یاخته‌ای و افزایش تولید کربن‌دی‌اکسید و آب، کربنیک اسید بیشتری ایجاد می‌شود و سبب می‌شود که $pH$ بدن تغییر یافته و درنهایت ساختار پروتئین‌های بدن تغییر یابد.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n$1$ ارسطو نمی‌دانست هوا مخلوطی از چند گاز است در نتیجه ترکیب هوای دمی و بازدمی را یکسان در نظر می‌گرفت.\\r\\n\\r\\n$3$ در واکنش تنفس یاخته‌ای آب و کربن‌دی‌اکسید ایجاد می‌شود نه کربنیک اسید.\\r\\n\\r\\n$4$ همواره چه در هوای دمی و چه در هوای بازدمی مقدار گاز اکسیژن بیشتر از کربن‌دی‌اکسید است.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":50900,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"337\":5579,\"475\":5371,\"479\":5366,\"492\":6033,\"526\":4948,\"529\":5339,\"585\":5821,\"601\":5319,\"627\":6396,\"662\":4748,\"688\":5236,\"698\":5222,\"764\":5190,\"8281\":51061,\"8303\":50972,\"8319\":50900},\"submittedQuestionIds\":[479,526,8251,8319,627,622,475,8303,601,492,662,529,764,585,1054,659,698,337,8281,688],\"totalTimeSpent\":1188,\"questionTimes\":{\"337\":55000,\"475\":111000,\"479\":61001,\"492\":13000,\"526\":35000,\"529\":25001,\"585\":71001,\"601\":107000,\"622\":19000,\"627\":50000,\"659\":84999,\"662\":56001,\"688\":33000,\"698\":58000,\"764\":46000,\"1054\":4001,\"8251\":48000,\"8281\":52000,\"8303\":28000,\"8319\":129000},\"selectionLog\":[{\"questionId\":479,\"optionId\":5366,\"timeSpentMs\":61001,\"timestamp\":1786559131528},{\"questionId\":526,\"optionId\":4948,\"timeSpentMs\":35000,\"timestamp\":1786559168161},{\"questionId\":8319,\"optionId\":50900,\"timeSpentMs\":128000,\"timestamp\":1786559338112},{\"questionId\":627,\"optionId\":6396,\"timeSpentMs\":50000,\"timestamp\":1786559393944},{\"questionId\":475,\"optionId\":5371,\"timeSpentMs\":78000,\"timestamp\":1786559489959},{\"questionId\":8303,\"optionId\":50972,\"timeSpentMs\":26000,\"timestamp\":1786559564463},{\"questionId\":601,\"optionId\":5319,\"timeSpentMs\":66000,\"timestamp\":1786559638394},{\"questionId\":492,\"optionId\":6033,\"timeSpentMs\":13000,\"timestamp\":1786559697888},{\"questionId\":662,\"optionId\":4745,\"timeSpentMs\":12000,\"timestamp\":1786559715651},{\"questionId\":662,\"optionId\":4748,\"timeSpentMs\":21001,\"timestamp\":1786559730360},{\"questionId\":529,\"optionId\":5337,\"timeSpentMs\":13000,\"timestamp\":1786559783937},{\"questionId\":529,\"optionId\":5338,\"timeSpentMs\":17001,\"timestamp\":1786559794251},{\"questionId\":529,\"optionId\":5339,\"timeSpentMs\":25001,\"timestamp\":1786559806730},{\"questionId\":764,\"optionId\":5190,\"timeSpentMs\":46000,\"timestamp\":1786559856513},{\"questionId\":585,\"optionId\":5821,\"timeSpentMs\":71001,\"timestamp\":1786559928445},{\"questionId\":698,\"optionId\":5222,\"timeSpentMs\":58000,\"timestamp\":1786560072861},{\"questionId\":337,\"optionId\":5579,\"timeSpentMs\":22000,\"timestamp\":1786560096291},{\"questionId\":337,\"optionId\":5580,\"timeSpentMs\":27000,\"timestamp\":1786560110373},{\"questionId\":337,\"optionId\":5579,\"timeSpentMs\":46000,\"timestamp\":1786560134778},{\"questionId\":8281,\"optionId\":51062,\"timeSpentMs\":31000,\"timestamp\":1786560178760},{\"questionId\":8281,\"optionId\":51061,\"timeSpentMs\":52000,\"timestamp\":1786560205097},{\"questionId\":688,\"optionId\":5236,\"timeSpentMs\":33000,\"timestamp\":1786560241097}]}}', '2026-08-12 18:44:18'),
(140, 42, 65, 50.00, 2, 2, 0, 33, 141, '{\"total_questions\":4,\"correct_count\":2,\"incorrect_count\":2,\"unanswered_count\":0,\"accuracy_rate\":50,\"score\":33,\"mabhas_stats\":{\"فصل سه یازدهم\":{\"correct\":2,\"incorrect\":2,\"unanswered\":0,\"total\":4}}}', '{\"evaluation\":{\"11200\":{\"correct_option_id\":63246,\"descriptive_answer\":{\"text\":\"هر استخوان از دو نوع بافت استخوانی اسفنجی و فشرده تشکیل شده است.\\n\\nعلت نادرستی سایر گزینه ها:\\n\\nگزینه $1$: مفصل استخوان های جمجمه از نوع ثابت است و غضروف ندارد.\\n\\nگزینه $2$: یاخته های بنیادی در مغز استخوان قرار دارند. یاخته های استخوانی بنیادی نبوده و یاخته های خونی تولید نمی کنند.\\n\\nگزینه $4$: غضروف از اصطکاک استخوان ها جلوگیری می کند و رباط به کنار هم ماندن استخوان ها کمک می کند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه یازدهم\",\"selected_option_id\":63245,\"is_answered\":true},\"11202\":{\"correct_option_id\":63252,\"descriptive_answer\":{\"text\":\"علت نادرستی سایر گزینه ها:\\n\\nگزینه $2$: در مجرای هاورس، مغز استخوان وجود ندارد.\\n\\nگزینه $3$: مغز قرمز، یاخته خونی تولید می کند.\\n\\nگزینه $4$: در همه مراحل عمر، تغییرات استخوانی در حال انجام هستند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه یازدهم\",\"selected_option_id\":63252,\"is_answered\":true},\"11205\":{\"correct_option_id\":63267,\"descriptive_answer\":{\"text\":\"در تنه استخوان بازو بافت پیوندی از خارج استخوان را احاطه کرده است که لایه درونی آن حاوی یاخته های پهن و نزدیک به هم است که در تماس بافت استخوانی فشرده است.\\n\\nعلت نادرستی سایر گزینه ها:\\n\\nگزینه $1$: در بافت استخوانی فشرده، یاخته های استخوانی می توانند جزء سامانه هاورس نباشند.\\n\\nگزینه $2$: از یاخته های درون ریز کبد، هورمون اریتروپویتین ترشح می شود که یاخته های بافت استخوانی برای آن گیرنده ندارند.\\n\\nگزینه $3$: کلاژن پروتئین ترشحی و استحکامی است، ولی کلاژن جزء ماده زمینه بافت استخوانی نیست.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه یازدهم\",\"selected_option_id\":63265,\"is_answered\":true},\"11206\":{\"correct_option_id\":63270,\"descriptive_answer\":{\"text\":\"در طول استخوان ران، بافت استخوانی فشرده مشاهده می شود که همانند بافت استخوانی اسفنجی در ماده زمینه ای خود دارای پروتئین (متنوع ترین گروه مولکول های زیستی) و مواد معدنی (نمک های کلسیم دار) است.\\n\\nعلت نادرستی سایر گزینه ها:\\n\\nگزینه $1$: در زیر غضروف محل مفصل استخوان بازو نیز بافت استخوان فشرده وجود دارد.\\n\\nگزینه $2$: مجرای مرکزی استخوان ران مستقیماً با بافت استخوانی اسفنجی احاطه شده است که این بافت از میله ها و صفحه های استخوانی ساخته شده است.\\n\\nگزینه $4$: یاخته های استخوانی در هر دو بافت دارای زواید متعدد و منشعب است.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه یازدهم\",\"selected_option_id\":63270,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"11200\":63245,\"11202\":63252,\"11205\":63265,\"11206\":63270},\"submittedQuestionIds\":[11205,11200,11202,11206],\"totalTimeSpent\":141,\"questionTimes\":{\"11200\":2004,\"11202\":77008,\"11205\":51007,\"11206\":997},\"selectionLog\":[{\"questionId\":11205,\"optionId\":63265,\"timeSpentMs\":51007,\"timestamp\":1786720595763},{\"questionId\":11200,\"optionId\":63245,\"timeSpentMs\":2004,\"timestamp\":1786720607239},{\"questionId\":11202,\"optionId\":63252,\"timeSpentMs\":52006,\"timestamp\":1786720653249},{\"questionId\":11206,\"optionId\":63270,\"timeSpentMs\":997,\"timestamp\":1786720682361}]}}', '2026-08-14 15:16:12'),
(141, 63, 1, 0.00, 0, 1, 9, 0, 1145, '{\"total_questions\":10,\"correct_count\":0,\"incorrect_count\":1,\"unanswered_count\":9,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"فصل دو دهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":9,\"total\":10}}}', '{\"evaluation\":{\"7248\":{\"correct_option_id\":40810,\"descriptive_answer\":{\"text\":\"با توجه به این‌که نیروی هم‌چسبی مولکول‌های آب بیش‌تر از نیروی دگرچسبی مولکول‌های آب و شیشه چرب است و هم‌چنین نیروی هم‌چسبی مولکول‌های جیوه بیش‌تر از نیروی دگرچسبی مولکول‌های جیوه و شیشه تمیز است، بنابراین هیچ‌کدام سطح شیشه‌ها را تر نمی‌کنند.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7252\":{\"correct_option_id\":40793,\"descriptive_answer\":{\"text\":\"ابتدا فشار کل وارد بر کف ظرف در حالت اول را می‌یابیم:\\r\\n\\r\\n$P_1 = P_0 + \\\\rho_1 gh_1 \\\\xrightarrow[P_0 = 10^5 Pa, h_1 = 0/25m]{\\\\rho_1 = 4 \\\\times 10^3 \\\\frac{kg}{m^3}}$\\r\\n\\r\\n$P_1 = 10^5 + 4 \\\\times 10^3 \\\\times 10 \\\\times 0/25 = 100000 + 10000 = 110000 Pa$\\r\\n\\r\\nاکنون، ارتفاع مایع اضافه شده را حساب می‌کنیم و فشار ناشی از آن، که در واقع همان افزایش فشار وارد بر کف ظرف می‌باشد را می‌یابیم:\\r\\n\\r\\n$V = Ah\' \\\\xrightarrow[A = 5cm^2]{V = 55cm^3} 55 = 5 \\\\times h\' \\\\Rightarrow h\' = 11cm$\\r\\n\\r\\n$\\\\Delta P = \\\\rho\' gh\' \\\\xrightarrow[\\\\rho\' = 2 \\\\frac{g}{cm^3} = 2000 \\\\frac{kg}{m^3}]{h\' = 11cm = 0/11m}$\\r\\n\\r\\n$\\\\Delta P = 2000 \\\\times 10 \\\\times 0/11 = 2200 Pa$\\r\\n\\r\\nدر آخر درصد افزایش فشار را حساب می‌کنیم:\\r\\n\\r\\nدرصد افزایش فشار $= \\\\frac{\\\\Delta P}{P_1} \\\\times 100 = \\\\frac{2200}{110000} \\\\times 100 = 2\\\\%$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":40792,\"is_answered\":true},\"7283\":{\"correct_option_id\":41593,\"descriptive_answer\":{\"text\":\"با توجه به رابطه‌های $P = \\\\rho g h$ و $F = PA$ ، نیروی وارد بر کف ظرف از طرف مایع برابر $F = \\\\rho g h A$ می‌باشد که در این‌جا A مساحت کف ظرف است. با توجه به این رابطه، چون A ، $\\\\rho$ و g ثابت‌اند، افزایش نیرو را از رابطه $\\\\Delta F = \\\\rho g A (\\\\Delta h)$ می‌یابیم.\\r\\n\\r\\nاز طرف دیگر، با توجه به این‌که جرم مایع اضافه شده برابر $m = \\\\rho V\' = \\\\rho A\' (\\\\Delta h)$ است، بنابراین $\\\\Delta h = \\\\frac{m}{\\\\rho A\'}$ خواهد بود که در این رابطه $A\'$ مساحت دهانه باریک ظرف است. در این حالت می‌توان نوشت:\\r\\n\\r\\n$\\\\Delta F = \\\\rho g A (\\\\Delta h) \\\\xrightarrow{\\\\Delta h = \\\\frac{m}{\\\\rho A\'}} \\\\Delta F = \\\\rho g A \\\\times \\\\frac{m}{\\\\rho A\'} \\\\Rightarrow \\\\Delta F = \\\\frac{A}{A\'} \\\\times mg$\\r\\n\\r\\n$\\\\xrightarrow{\\\\Delta F = 20 N, A = 100 cm^2 \\\\atop A\' = 20 cm^2} 20 = \\\\frac{100}{20} \\\\times mg \\\\Rightarrow mg = 4N$\\r\\n\\r\\nمی‌بینیم، عدد ترازو به اندازه وزن مایع اضافه شده، یعنی 4N افزایش می‌یابد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7294\":{\"correct_option_id\":40618,\"descriptive_answer\":{\"text\":\"تفاوتی ندارد که روغن به کدام شاخه اضافه شود. فرض می کنیم\\r\\n\\r\\nروغن به شاخه پهن اضافه شود. به این ترتیب سطح آب به اندازه\\r\\n\\r\\n$x$ پایین می آید و حجم آب خروجی از لوله پهن $A1x$ خواهد\\r\\n\\r\\nبود. همین حجم آب به لوله باریک منتقل می شود. ولی چون\\r\\n\\r\\nسطح مقطع آن $1/4$ برابر است، آب در آن به اندازه $4x$ بالا\\r\\n\\r\\nمی رود و افزایش فشار در بخش افقی لوله برابر با فشار ناشی از\\r\\n\\r\\nارتفاع $4x$ آب خواهد بود. از طرفی پس از برقراری تعادل، از\\r\\n\\r\\nبرابری فشار در نقاط هم تراز درون یک مایع داریم:\\r\\n\\r\\n$A1h1 = A2h2 ⇒ π × 2^2 × x = π × 1^2 × h2 ⇒ h2 = 4x$\\r\\n\\r\\n$V$روغن $= A1h$روغن $⇒ 600 = 3 × 2^2 × h$روغن $⇒ h$روغن $= 50 cm$\\r\\n\\r\\n$PA = PB ⇒ ρ$آب$gh$آب $+ P0 = ρ$روغن$gh$روغن $+ P0 ⇒ ρ$آب$h$آب $= ρ$روغن$h$روغن\\r\\n\\r\\n$⇒ 1 × 5x = 0/8 × 50 ⇒ x = 8 cm$\\r\\n\\r\\n$Δh$آب $= 4x = 32 cm$\\r\\n\\r\\n$ΔP = ρ$آب$gΔh$آب $= 1000 × 10 × 0/32 = 3200 Pa$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7299\":{\"correct_option_id\":40598,\"descriptive_answer\":{\"text\":\"11- پاسخ: گزینه 3\\r\\n\\r\\nتندی آب در بخش پهن لوله را با $v1$ و تندی آب در بخش باریک آن را با $v2$ نشان میدهیم. در هنگام ورود آب از بخش پهن به بخش باریک، تندی آن زیاد میشود؛ ازاینرو داریم:\\r\\n\\r\\n$v2 = v1 + (44/100)v1 = 1/44v1$\\r\\n\\r\\nمعادله پیوستگی : $v1A1 = v2A2 ⇒ v1A1 = 1/44v1A2 ⇒ A1 = 1/44A2 \\\\xrightarrow{A=πr^2} πr1^2 = 1/44πr2^2$\\r\\n\\r\\n$⇒ r1^2 = 1/44×(5/2)^2 ⇒ r1 = 1/2×2/5 = 3 cm$\\r\\n\\r\\nاختلاف شعاع دو بخش لوله : $3 cm - (5/2 cm) = 0/5 cm = 5 mm$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7302\":{\"correct_option_id\":40584,\"descriptive_answer\":{\"text\":\"$P = (ρgh)$_آب $+ P_0 ⇒ (ρgh)$_جیوه $= (ρgh)$_آب $+ P_0 ⇒ 13600 × 10 × 1 = 1000 × 10 × h + 13600 × 10 × 0/75$\\r\\n\\r\\n$⇒ 34000 = 10000 h ⇒ h = 3/4 m$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7311\":{\"correct_option_id\":40551,\"descriptive_answer\":{\"text\":\"$P$گاز مخزن $+ P$جیوه $= P$آب $+ P0 ⇒ P$گاز مخزن $+ (ρgh)$جیوه $= (ρgh)$آب $+ P0$\\r\\n\\r\\n$⇒ P$گاز مخزن $+ 13600 × 10 × 17 / 100 = 1000 × 10 × 30 / 100 + 96/12 × 10^3$\\r\\n\\r\\n$⇒ P$گاز مخزن $+ 23120 = 3000 + 96120 ⇒ P$گاز مخزن $= 76000 Pa = 76 kPa$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7315\":{\"correct_option_id\":40535,\"descriptive_answer\":{\"text\":\"آهنگ شارش حجمی آب $= Av ⇒ 0/012 m^3/s = A × 10 m/s ⇒ A = 0/0012 m^2$\\r\\n\\r\\n$A = πR^2 = 0/0012 ⇒ R = 2 × 10^-2 m = 20 mm$\\r\\n\\r\\nقطر مقطع $= 2R = 40 mm$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7323\":{\"correct_option_id\":40501,\"descriptive_answer\":{\"text\":\"گزاره های «الف» و «پ» درست هستند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7337\":{\"correct_option_id\":40444,\"descriptive_answer\":{\"text\":\"$P_B = P_C = ρ$جیوه$gh_1 + P_0 = 13600 × 10 × 0/05 + 10^{5}$\\r\\n\\r\\n$= 6800 + 10^{5} = 0/068 × 10^5 + 10^{5} = 1/068 × 10^{5} Pa$\\r\\n\\r\\n$P$گاز$ = P_B ⇒ P_A = P$گاز$ + ρ$آب$gh_2 = 1/068 × 10^{5} + 1000 × 10 × 2$\\r\\n\\r\\n$= 1/068 × 10^{5} + 0/2 × 10^{5} = 1/268 × 10^{5} Pa$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"7252\":40792},\"totalTimeSpent\":1145,\"questionTimes\":{\"7252\":9780,\"7283\":16013,\"7299\":10991,\"7302\":795,\"7315\":1206,\"7337\":2008},\"selectionLog\":[{\"questionId\":7252,\"optionId\":40792,\"timeSpentMs\":9780,\"timestamp\":1787153017203}],\"lobbyCode\":\"WaYDbwWRP4\"}}', '2026-08-19 15:24:05');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(142, 66, 1, 30.00, 3, 7, 0, 11, 40, '{\"total_questions\":10,\"correct_count\":3,\"incorrect_count\":7,\"unanswered_count\":0,\"accuracy_rate\":30,\"score\":11,\"mabhas_stats\":{\"پنج دوازدهم\":{\"correct\":3,\"incorrect\":7,\"unanswered\":0,\"total\":10}}}', '{\"evaluation\":{\"988\":{\"correct_option_id\":4677,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; برای حل این سؤال دقت کنید که عبارات مطرح شده می توانند برای بیش از یک روش صحیح باشند؛ اما شما باید گزینه ای را انتخاب کنید که ترتیب درستی با توجه به نامگذاری های جدول ارائه می دهد. بررسی موارد مطرح شده : عدم استفاده از انرژی ذخیره شده در مولکول \\\\(NADH\\\\) برای تولید \\\\(ATP\\\\)، در تنفس هوازی، از انرژی ذخیره شده در \\\\(NADH\\\\) طی زنجیره انتقال الکترون برای تولید \\\\(ATP\\\\) بیشتر در یاخته استفاده می شود. در فرایند تخمیر (هم لاکتیکی، هم الكلى) مولكول \\\\(NADH\\\\)، الکترون خود را به ترکیب پذیرنده آلی می دهد تا \\\\(NAD^+\\\\) به منظور تداوم قند کافت بازسازی شود، اما انرژی ذخیره شده در آنها به صورت مستقیم برای تولید \\\\(ATP\\\\) بیشتر در یاخته مصرف نمی شود. طی تخمیر، فقط در قند کافت \\\\(ATP\\\\) تولید می شود پس &laquo;الف&raquo; و &laquo;ج&raquo; می تواند درست باشد. شکست پیوند کربن - کربن و آزادسازی مولکول کربن دی اکسید از آن، در تنفس هوازی، پیرووات اکسایش می یابد که طی آن با آزاد شدن دی اکسید کربن (شکست پیوند کربن &ndash; کربن) بنیان استیل (ترکیب دوکربنی) تشکیل می شود. همچنین در طی چرخه کربس نیز پیوند کربن - کربن شکسته می شود و کربن دی اکسید آزاد می شود. در تخمیر الکلی نیز پیرووات درون مادۀ زمینه سیتوپلاسم، با آزاد کردن کربن دی اکسید به ترکیبی دو کربنی (اتانال) تبدیل می شود. در تخمیر لاکتیکی، پیرووات به لاکتیک اسید تبدیل می شود و مولکول کربن دی اکسید آزاد نمی شود؛ پس &laquo;ه&raquo; و &laquo;و&raquo; می تواند درست باشد. توقف واکنش مربوط به انتقال الکترون ها به گیرنده نهایی آن توسط سیانید، زنجیره انتقال الکترون فقط مربوط به تنفس هوازی است. سیانید می تواند واکنش مربوط به انتقال الکترون ها به گیرنده نهایی زنجیره انتقال الکترون یا همان \\\\(O_2\\\\) را مهار کند. پس، فقط &laquo;ب&raquo; میتواند درست باشد. مبادله الکترون آن با نوعی ترکیب دونوکلئوتیدی، در تنفس هوازی، طی اکسایش پیرووات، پیرووات، الکترون از دست می دهد و آن را به مولکول \\\\(NAD^+\\\\) که ترکیبی دونوکلئوتیدی است، منتقل می کند. در تخمیر لاکتیکی نیز پیرووات، کاهش می یابد و الکترون های مولکول \\\\(NADH\\\\) را دریافت می کند (در تخمیر الکلی، پیرووات مبادله الکترونی با \\\\(NAD^+\\\\) یا \\\\(NADH\\\\) .ندارد). پس موارد &laquo;ه&raquo; و &laquo;د&raquo; می توانند درست باشند.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4678,\"is_answered\":true},\"989\":{\"correct_option_id\":4684,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; این مراحل شامل تبدیل اسید فسفاته به پیرووات هم می شود که طی آن، به ازای هر گلوکز ۴ مولکول \\\\(ATP\\\\) (طی قند کافت و در سطح پیش ماده) تولید می شود. \\\\(NADH\\\\) طی قند کافت در مادۀ زمینۀ سیتوپلاسم و طی اکسایش پیرووات در راکیزه تولید می شود. طی این واکنش ها، به ازای هر گلوکز ۲ مولکول \\\\(NADH\\\\) طی اکسایش پیرووات در راکیزه تولید می شود. بررسی سایر گزینه ها: 1) در طی مسیر واکنش های مطرح شده ۲ مولکول کربن دی اکسید درون میتوکندری (طی اکسایش پیرووات) تولید می شود و ۲ مولکول بنیان استیل به منظور تشکیل استیل کوآنزیم \\\\(A\\\\) ، مصرف می شود. (به ازای هر گلوکز، دو پیرووات مصرف و دو استیل کوآنزیم \\\\(A\\\\) تولید می شود.) 2) قند کافت در ماده زمینه ای سیتوپلاسم، دو مولکول پیرووات به عنوان محصولات نهایی قندکافت، تولید می شوند. دقت کنید که در نخستین مرحله چرخه کربس، ترکیب چهار کربنی با استیل کوآنزیم \\\\(A\\\\) ترکیب می شود؛ پس به ازای هر گلوکز، دوترکیب چهار کربنی مصرف می شود. چراکه به ازای هر گلوکز، چرخه کربس، دو بار رخ می دهد. 3) در طی مسیر واکنش های مذکور، ۲ مولکول استیل کوآنزیم \\\\(A\\\\) درون میتوکندری تولید شده و همچنین ۲ مولکول \\\\(NAD^+\\\\) نیز در طی واکنش های قند کافت مصرف شده و سبب تشکیل دو مولکول \\\\(NADH\\\\) شده اند.\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4684,\"is_answered\":true},\"990\":{\"correct_option_id\":4661,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; ائوزینوفیل ها، نوتروفیل ها، مونوسیت ها، بازوفیل ها و لنفوسیت ها از جمله گویچه های سفید خون هستند. این یاخته ها، \\\\(ATP\\\\) مورد نیاز خود را از راه تنفس هوازی به دست می آورند. افزایش فعالیت آنزیم های درگیر در قندکافت و چرخه کربس به معنای افزایش تنفس هوازی است. دقت کنید مقدار \\\\(ATP\\\\) تولید شده در ازای تجزیه کامل گلوکز در یاخته یوکاریوتی در بهترین شرایط در حداکثر مقدار ممکن خواهد بود که طبق کتاب درسی، ۳۰ مولکول \\\\(ATP\\\\) است. اما خب یک یاخته یوکاریوتی در بدن انسان، لزوما در بهترین شرایط خود نیست و این عدد می تواند کمتر باشد. ۳۰ مولکول \\\\(ATP\\\\) مربوط به شرایط بهینه آزمایشگاهی است. بررسی سایر گزینه ها: 2) ائوزینوفیل ها، نوتروفیل ها، مونوسیت ها، بازوفیل ها ، مگاکاریوسیت و گویچه قرمز، انواع یاخته های حاصل از یاخته های بنیادی میلوئیدی هستند. به دنبال افزایش تنفس هوازی ا(فزایش فعالیت پمپ های غشای داخلی راکیزه)، الکترون های بیشتری به \\\\(O_2\\\\) منتقل می شود و در نتیجه احتمال تولید رادیکال های آزاد نیز افزایش می یابد اما دقت کنید که گویچه های قرمز بالغ فاقد چرخه کربس، اکسایش پیرووات و زنجیره انتقال الکترون (فاقد میتوکندری) هستند. 3) ماکروفاژ و یاخته دندریتی از تمایز مونوسیت ها در بافت ها (خارج از خون) ایجاد می شوند. با افزایش تنفس هوازی مولکول های حامل الکترون (\\\\(NADH\\\\) و\\\\(FADH_2\\\\) ) بیشتری نیز تولید می شوند. این یاخته ها فاقد توانایی تخمیر لاکتیکی هستند. بنابراین افزایش تنفس هوازی در آنها ارتباطی با تغییر در تولید لاکتیک اسید درون یاخته ندارد؛ به بیان دیگر در این یاخته لاکتیک اسیدی تولید نمی شود که حالا بخواهد مقدار آن کمتر شود. 4) تارهای ماهیچه ای، شامل تار کند (به میزان بیشتری تنفس هوازی دارند و به میزان کمتری تخمیر) و تار تند (میزان بیشتری تخمیر لاکتیکی و میزان کمتری، تنفس هوازی دارند) است. در تارهای کند که در آنها تنفس هوازی بیشتری صورت می گیرد، پیرووات وارد اکسایش پیرووات سایر مراحل تنفس هوازی می شود؛ در نتیجه تنفس هوازی بیشتر تولید مولکول های آب در بخش داخلی میتوکندری به دنبال ترکیب یون اکسید و یون های هیدروژن افزایش می یابد. در تارهای تند، بیشتر انرژی از راه تخمیر لاکتیکی تأمین می شود پس به دنبال افزایش مصرف پیرووات، تخمیر لاکتیکی بیشتری (نسبت به تنفس هوازی) رخ می دهد. در نتیجه تولید مولکول های آب در بخش داخلی راکیزه، افزوده نمی شود.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4663,\"is_answered\":true},\"992\":{\"correct_option_id\":4656,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; بخشی از واکنش های تنفس یاخته ای هوازی که در مادۀ زمینۀ سیتوپلاسم انجام می شود، گلیکولیز (قندکافت) است. در واکنشی که قند سه کربنه تک فسفاته اکسایش می یابد (انتقال الکترون ها به \\\\(NAD^+\\\\) و تشکیل \\\\(NADH\\\\))، برای تشکیل اسید دوفسفاته، فسفات به این مولکول سه کربنی (قند فسفاته) متصل خواهد شد و چون این فسفات، نوعی فسفات آزاد است، از این طریق، مقدار فسفات آزاد درون یاخته کاسته خواهد شد. بررسی سایر گزینه ها: 1) در گلیکولیز این رویداد مشاهده نمی شود. ترکیبات اسیدی قندکافت، اسید دوفسفاته و پیروویک اسید هستند. پیروویک اسید به دنبال از دست دادن فسفات های اسید دوفسفاته تشکیل می شود. خود اسید دوفسفاته هم، به دنبال انتقال فسفات به قند فسفاته تشکیل می شود. فسفات، ماده آلی نیست. 2) در گام آخر گلیکولیز، \\\\(ADP\\\\) با دریافت فسفات از ترکیبی اسیدی (اسیدهای دوفسفاته) به \\\\(ATP\\\\) تبدیل خواهد شد. 3) در فرایند قند کافت این اتفاق مشاهده نمی شود. دقت کنید که گرچه در فروکتوز فسفاته که ترکیبی شش کربنه است، بین دو کربن آن، پیوندی اشتراکی شکسته می شود اما طی این واکنش، فسفات ها از فروکتوز جدا نمی شوند.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4656,\"is_answered\":true},\"993\":{\"correct_option_id\":4652,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; تومور (خوش خیم یا بدخیم)، توده یاخته ای است که در اثر تقسیمات میتوز تنظیم نشده ایجاد شده است. رادیکال های آزاد از عوامل ایجاد سرطان (تومور بدخیم) اند. دقت کنید لزوما هر رادیکال آزادی در یاخته ها سبب بروز سرطان نمی شود؛ مثلا ممکن است آسیبی که به ساختارهای یاخته ای وارد می شود سبب شود، یاخته بمیرد و یا حتی این رادیکال ها، ممکن است خنثی شوند (مثلا توسط پاداکسنده ها) بررسی سایر گزینه ها: 1) یون های اکسید (در پی دریافت الکترون توسط اکسیژن در زنجیره انتقال الکترون، تولید می شوند) با یون های هیدروژن ترکیب شده و مولکول های آب را ایجاد می کنند. دقت کنید که یون های اکسید رادیکال آزاد نمی باشند. رادیکال آزاد به طور مستقیم از اکسیژن ایجاد می شود. 2) رادیکال های آزاد ممکن است برای جبران کمبود الکترونی خود به مولکول های سازنده یاخته و اجزای آن (مثل دنا و پروتئین ها)، حمله کنند. اما همه آنها، از این طریق کمبود الکترونی خود را جبران نمی کنند، مثلا گروهی از آنها، ممکن است این الکترون ها را از پاداکسنده ها دریافت کنند. 3) همه رادیکال های آزاد به علت داشتن الکترون(های) جفت نشده در ساختار خود، واکنش پذیری بالایی دارند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4649,\"is_answered\":true},\"1023\":{\"correct_option_id\":4528,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; منظور صورت سؤال، فرایند تخمیر است؛ در کتاب درسی به تخمیر الکلی و لاکتیکی اشاره شده است. طی تخمیر طبق اطلاعات کتاب درسی، پذیرنده نهایی الکترون نوعی ترکیب آلی است و اکسیژن نمی باشد؛ در نتیجه امکان تولید رادیکال آزاد اکسیژن نیز وجود ندارد. در بخش نخستین تخمیر الکلی و لاکتیکی مطرح شده در کتاب، مرحله گلیکولیز (قندکافت) صورت می گیرد و طی واکنش های آنزیمی مرحله انتهایی قند کافت، مولکول ATP با انتقال فسفات از اسید دوفسفاته به ADP (در سطح پیش ماده) تولید می گردد. بنابراین همه جانداران زنده می توانند با استفاده از واکنش های آنزیمی، فسفات را به مولکول آدنوزین دی فسفات بیفزاید. بررسی سایر گزینه ها: 1) طی مرحله سوم قند کافت مولکول \\\\(NAD^+\\\\) (یک نوع گیرنده الکترونی) با دریافت الکترون به NADH تبدیل می شود. FAD در قند کافت مصرف نمی شود. ۲) در طی تخمیر، رایج ترین شکل انرژی زیستی (ATP) توسط زنجیره انتقال الکترون ایجاد نمی شود. ۳) در تخمیر الکلی، همزمان با شکست پیوند کربن - کربن در پیرووات و تولید اتانال، مولکول \\\\(NAD^+\\\\) بازسازی نمی گردد. در تخمیر لاکتیکی نیز پیوند بین کربن های پیرووات شکسته نمی شود. دقت کنید که در هر نوع تخمیر مطرح شده در کتاب درسی، همزمان با تشکیل ترکیب نهایی تخمیر (اتانول یا لاکتات،) NADH مصرف شده و پذیرندۀ الکترونی\\\\(NAD^+\\\\) بازسازی می شود.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4526,\"is_answered\":true},\"1024\":{\"correct_option_id\":4523,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; سیانید یکی از ترکیب های سمی است که واکنش نهایی مربوط به انتقال الکترون ها به اکسیژن را مهار (توقف عملکرد پمپ سوم زنجیره انتقال الکترون) و در نتیجه باعث توقف زنجیره انتقال الکترون در میتوکندری می شود. با توقف این،زنجیره، بقیه مراحل تنفس یاخته ای هم متوقف می شود؛ به عبارتی، این ترکیب به طور غیر مستقیم (نه مستقیم) بر روی فعالیت آنزیم ATP ساز مؤثر است. در واقع با متوقف شدن زنجیره انتقال الکترون، شیب غلظت یون های هیدروژن ایجاد نمی شود و در نتیجه آنزیم ATP ساز فعالیت مناسبی نخواهد داشت. بررسی سایر گزینه ها: 1) اگر نقص در ژن های مربوط به پروتئین های زنجیره انتقال الکترون، منجر به ساخته شدن پروتئین های معیوب شود؛ راکیزه ای که این پروتئین های معیوب را داشته باشد در مبارزه با رادیکال های آزاد، عملکرد مناسبی ندارد. بنابراین رادیکال های آزاد در میتوکندری تجمع می یابند. 2) الکل و انواعی از نقص های ژنی در عملکرد راکیزه در خنثی سازی رادیکال های آزاد مشکل ایجاد می کنند. علاوه بر این، الکل سرعت تشکیل این رادیکال ها را نیز افزایش می دهد. ۴) کربن مونوکسید گازی است که بر تنفس یاخته ای اثر می گذارد، این گاز علاوه بر این که ظرفیت حمل \\\\(O_2\\\\) را در خون کاهش می دهد، با عملکردی مشابه سیانید سبب توقف واکنش مربوط به انتقال الکترون ها به اکسیژن می شود. بنابراین با اختلال در تشکیل یون اکسید، تشکیل آب نیز در بخش داخلی راکیزه (میتوکندری) مختل می گردد.\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4522,\"is_answered\":true},\"1031\":{\"correct_option_id\":4492,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; فقط مورد &laquo;الف&raquo; به نادرستی بیان شده است. بررسی همه موارد: الف) نادرست؛ در تنفس نوری، ATP تولید نمی شود؛ اما در تنفس هوازی این مولکول با افزوده شدن فسفات به ADP تولید می گردد. طی تنفس نوری، فتوسنتر و تنفسی هوازی، حامل الکترون و پذیرنده های آن نیز وجود دارند که نوعی نوکلئوتید هستند، تعداد فسفات این ترکیبات، طی این فرایندها تغییر نمی کند. ب) درست؛ در تنفس هوازی، استیل ترکیبی دوکربنه است که طی مرحلۀ اکسایش پیرووات، ابتدا تولید می شود و جهت ترکیب با کوآنزیم A مصرف می گردد. در تنفس نوری نیز، به دنبال ترکیب شدن ریبولوز بیس فسفات و اکسیژن، نوعی ترکیب ناپایدار تولید می شود که در ادامه به ترکیب های دو و سه کربنی تجزیه می شود. ترکیب دوکربنی نیز در ادامه مصرف شده و از آن کربن دی اکسید تولید می شود. ج) درست؛ اندامک دوغشایی فاقد کلروفیل، یعنی میتوکندری. در تنفس هوازی، طی چرخه کربس و اکسایش پیرووات، مولکول کربن دی اکسید در میتوکندری تولید می گردد. در تنفس نوری نیز، طی فرایندهایی مولکول دوکربنی تولید شده وارد میتوکندری شده و در آنجا یک \\\\(CO_2\\\\) از دست می دهد. د) درست؛ در تنفس هوازی، ترکیب پنج کربنه طی چرخه کربس در میتوکندری تولید و مصرف می شود. در تنفس نوری نیز ترکیب پنج کربنه ریبولوز بیس فسفات با اکسیژن ترکیب می شود.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4491,\"is_answered\":true},\"1033\":{\"correct_option_id\":4483,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; در تنفس یاخته ای، پمپ های زنجیره انتقال الکترون، پروتون ها را از بخش داخلی میتوکندری به فضای بین دو غشا جابه جا می کنند. این جابه جایی از طریق انتقال فعال و به دنبال مصرف انرژی حاصل از جابه جایی الکترون ها رخ می دهد. اما پیرووات هم، از طریق انتقال فعال از ماده زمینه سیتوپلاسم به میتوکندری وارد می شود. این انتقال فعال از طریق پروتئین هایی غیر از اجزای زنجیره انتقال الکترون انجام می گیرد. بررسی سایر گزینه ها: 1) گیرنده نهایی الکترون در تخمیر لاکتیکی، پیرووات است که نوعی بنیان اسیدی آلی سه کربنی می باشد. 2) در گلیکولیز، تولید اسید دوفسفاته (نوعی ماده سه کربنی) با ساخته شدن NADH (حاوی انرژی) همراه است. از طرفی، مصرف شدن این اسید طی قند کافت نیز منجر به تولید مولکول های ATP (حاوی انرژی) خواهد شد. 4) ATP می تواند در چرخۀ کالوین و یا قندکافت مصرف شود. به دنبال افزایش O2 ، ممکن است تنفس یاخته ای هم انجام شود که در این شرایط قندکافت هم رخ می دهد و در مرحله اول آن ATP مصرف می شود.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4483,\"is_answered\":true},\"1053\":{\"correct_option_id\":4403,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; مربوط به انتقال الکترون ها به \\\\(O_2\\\\) را مهار می کنند و این گونه به صورت غیر مستقیم سبب توقف زنجیره انتقال الکترون و ساخته شدن اکسایشی ATP نیز می شوند. دقت کنید که این مولکول ها مستقیماً بر همۀ پروتئین های پمپ کنندۀ پروتون ها به فضای بین دو غشای راکیزه (میتوکندری) اثر نمی گذارند. اثر مستقیم آنها بر پمپ سوم زنجیره است اما، پمپ های اول و دوم، می توانند تا مدتی پس از اثر سیانید و مونواکسید کربن، به پمپ \\\\(H^+\\\\) بپردازند، اما در نهایت فعالیت آنها هم متوقف می شود. بررسی سایر گزینه ها: 1) پیرووات محصول نهایی قندکافت است که در ماهیچه ها، طی تخمیر لاکتیکی می تواند کاهش یابد و به لاکتیک اسید تبدیل شود. در تخمیر، مولكول \\\\(ATP \\\\) تنها از طریق یک روش و آن هم از طریق سطح پیش ماده (در طی گلیکولیز) تولید می شود. 2) اکسایش مولکول های ناقل الکترون مثل \\\\(NADH\\\\) و \\\\(FADH_2\\\\) در زنجیره انتقال الکترون رخ می دهد؛ در نتیجه فعالیت این زنجیره، گاهی ممکن است در بخش انتهایی زنجیره، به دنبال انتقال الکترون ها به \\\\(O_2\\\\) به جای \\\\(O^{2-}\\\\)، رادیکال های آزاد تشکیل شود که واکنش پذیری بالا دارند. 4) در غشای داخلی میتوکندری، آنزیم \\\\(ATP \\\\) ساز با جابه جایی پروتون ها از فضای بین دو غشا به بخش داخلی میتوکندری، سبب تولید مولکول های \\\\(ATP \\\\) (مولکول های زیستی پرانرژی) می شود. دقت کنید که تولید \\\\(ATP \\\\) از \\\\(ADP\\\\) و فسفات با تولید مولکول آب همراه است. آنزیم \\\\(ATP \\\\) ساز، کانالی دارد که پروتون ها را در جهت شیب غلظتشان جابه جا می کند و با استفاده از انرژی حاصل از این جابه جایی، \\\\(ATP \\\\) می سازد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":4402,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"988\":4678,\"989\":4684,\"990\":4663,\"992\":4656,\"993\":4649,\"1023\":4526,\"1024\":4522,\"1031\":4491,\"1033\":4483,\"1053\":4402},\"totalTimeSpent\":40,\"questionTimes\":{\"988\":1000,\"989\":3001,\"990\":2001,\"992\":999,\"993\":2000,\"1023\":5000,\"1024\":3001,\"1031\":2000,\"1033\":2000,\"1053\":1001},\"selectionLog\":[{\"questionId\":992,\"optionId\":4656,\"timeSpentMs\":999,\"timestamp\":1787154707698},{\"questionId\":988,\"optionId\":4678,\"timeSpentMs\":1000,\"timestamp\":1787154710456},{\"questionId\":1024,\"optionId\":4522,\"timeSpentMs\":3001,\"timestamp\":1787154712147},{\"questionId\":1023,\"optionId\":4526,\"timeSpentMs\":5000,\"timestamp\":1787154713481},{\"questionId\":1033,\"optionId\":4483,\"timeSpentMs\":2000,\"timestamp\":1787154714865},{\"questionId\":1053,\"optionId\":4402,\"timeSpentMs\":1001,\"timestamp\":1787154716184},{\"questionId\":990,\"optionId\":4663,\"timeSpentMs\":2001,\"timestamp\":1787154717571},{\"questionId\":1031,\"optionId\":4491,\"timeSpentMs\":2000,\"timestamp\":1787154719122},{\"questionId\":989,\"optionId\":4684,\"timeSpentMs\":3001,\"timestamp\":1787154720607},{\"questionId\":993,\"optionId\":4649,\"timeSpentMs\":2000,\"timestamp\":1787154725330}],\"lobbyCode\":\"v5Y5kzp0Po\"}}', '2026-08-19 15:52:13'),
(143, 67, 112, 0.00, 0, 0, 10, 0, 40, '{\"total_questions\":10,\"correct_count\":0,\"incorrect_count\":0,\"unanswered_count\":10,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"فصل دو دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":10,\"total\":10}}}', '{\"evaluation\":{\"336\":{\"correct_option_id\":5565,\"descriptive_answer\":{\"text\":\"هر چهار مورد این سؤال، نادرست است. بررسی موارد الف) در بزاق، انواعی از آنزیم ها نظیر آمیلاز و لیزوزیم وجود دارند. آنزیم آمیلاز بزاق به گوارش نشاسته کمک می کند. لیزوزیم، آنزیمی است که در از بین بردن باکتری های درون دهان نقش دارد و ماده ای به جز نشاسته را تجزیه می کند. ب) بی کربنات موجود در روده باریک دارای سه منشأ است: 1- بی کربنات ترشح شده توسط پانکراس، 2- بی کربنات موجود در صفرا و ۳- بی کربنات ترشح شده توسط یاخته های پوششی روده باریک. روده باریک جزء اندامهای لوله گوارش (نه اندام های مرتبط با لوله) است. ج) در لوله گوارش، مونوساکاریدها بدون گوارش جذب می شوند ولی دی ساکاریدها و پلی ساکاریدها برای جذب شدن باید گوارش یابند و به مونوساکارید تبدیل شوند. بنابراین، مونوساکاریدهای جذب شده در لوله گوارش دو دسته هستند: ۱- مونوساکاریدهایی که. غذا و ۲- مونوساکاریدهای حاصل از گوارش دی ساکاریدها و پلی ساکاریدها (طی واکنش هیدرولیز). د) یاخته های پوششی سطحی مخاط معده و برخی از یاخته های غده های آن (یاخته های ترشح کننده ماده مخاطی)، مادۀ مخاطی فراوان ترشح می کنند که به شكل لایه ژله ای ،چسبناکی مخاط معده را می پوشاند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"350\":{\"correct_option_id\":5132,\"descriptive_answer\":{\"text\":\"هر چهار مورد این سؤال، صحیح است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"357\":{\"correct_option_id\":5111,\"descriptive_answer\":{\"text\":\"فقط مورد (ج)، صحیح است. هنگام بلع با فشار زبان (نوعی ماهیچه مخطط) به صورت ارادی، توده غذا به عقب دهان و داخل حلق رانده می&zwnj;شود. (درستی مورد ج). با رسیدن غذا به حلق، بلع به شکل غیرارادی (نه ارادی) ادامه پیدا می&zwnj;کند (نه اینکه آغاز شود) (نادرستی مورد الف؛ شروع فرایند بلع زمانی است که غدا توسط زبان به داخل حلق رانده می&zwnj;شود). در ادامه دیواره ماهیچه ای حلق منقبض می&zwnj;شود و حرکت کرمی آن، غذا را به مری می&zwnj;راند. حرکت کرمی در مری ادامه پیدا می&zwnj;کند (نه اینکه شروع شود) (نادرستی مورد د؛ حرکات کرمی در حلق آغاز می&zwnj;شود) و با شل شدن بنداره انتهای مری غذا وارد معده می&zwnj;شود (نادرستی مورد ب؛ پس از ورود غذا به معده، فرایند بلع تمام می&zwnj;شود).\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"419\":{\"correct_option_id\":5000,\"descriptive_answer\":{\"text\":\"یاخته&zwnj;های کناری در غدد معده دارای غشایی فرورفته و غیر&zwnj;مسطح در سمت مجرایی خود هستند. این یاخته&zwnj;ها در ترشح عامل داخلی معده نقش دارند که با کمک به جذب ویتامین \\\\(B_{12}\\\\) در تولید گویچه&zwnj;های قرمز مؤثر می&zwnj;باشد. آسیب یاخته&zwnj;های کناری معده می&zwnj;تواند منجر به بروز نوعی کم&zwnj;خونی خطرناک شود. 1) علاوه بر یاخته&zwnj;های ترشح&zwnj;کننده موسین در لایه مخاطی لوله گوارش یاخته&zwnj;های غدد بزاقی نیز می&zwnj;توانند موسین ترشح کنند. 2) آنزیم تجزیه&zwnj;کننده نشاسته (پلی ساکارید) گیاهی توسط غدد بزاقی، پانکراس و روده باریک ساخته می&zwnj;شود. از بین یاخته&zwnj;های ترشح کننده این آنزیم، فقط یاخته&zwnj;های غدد بزاقی بالاتر از دریچه پیلور قرار دارند. 3) آنزیم لیزوزیم، نوعی آنزیم موجود در ترشحات یاخته&zwnj;های سازنده ماده مخاطی و همچنین غدد بزاقی است که دارای نقش دفاعی است و در نابودی باکتری&zwnj;ها نقش دارد. این آنزیم نقشی در گوارش شیمیایی مواد غذایی ندارد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"497\":{\"correct_option_id\":5353,\"descriptive_answer\":{\"text\":\"یاخته&zwnj;های کناری غدد معده و یاخته&zwnj;های ترشح&zwnj;کننده ماده مخاطی غدد روده، دارای زوائدی غشایی در سطح مجاور به مجرای خود هستند. این ویژگی در تصاویر زیر قابل مشاهده است. از کجا بفهمیم کدوم یاخته در غدد روده کمترینه ؟! از طریق اینکه یاخته&zwnj;های سفید قابل مشاهده در این غدد که کم&zwnj;تعداد&zwnj;ترین یاخته&zwnj;های غدد معده هستند،&zwnj; در قسمت&zwnj;های بالا نام&zwnj;گذاری شده&zwnj;اند. 2) هر دو دسته یاخته ذکر شده، از یاخته&zwnj;های بافت پوششی استوانه&zwnj;ای تک لایه بوده و با غشای پایه تشکیل شده از رشته&zwnj;های پروتئینی و گلیکوپروتئینی در تماس هستند. 3) در میان یاخته&zwnj;های ذکر شده، تنها یاخته&zwnj;های ترشح&zwnj;کننده ماده مخاطی در معده، توانایی تولید موسین (نوعی گلیکوپروتئین حاوی زنجیره کربوهیدراتی) در جهت تولید ماده مخاطی را دارند. در نظر داشته باشید که مولکول&zwnj;های کربوهیدرات دارای دو انتهای حاوی OH می&zwnj;باشند. 4) هیچکدام از یاخته&zwnj;های عنوان&zwnj;شده در این گزینه توانایی ترشح هورمون به سمت آستر بافت پیوندی موجود در زیر بافت پوششی در جهت ورود آن به خون را ندارند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"551\":{\"correct_option_id\":5851,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; موارد &laquo;ب&raquo;، &laquo;ج&raquo; و &laquo;د&raquo; در مورد گروهی از آنها درست است. بررسی همه موارد: الف) پانکراس، غدد بزاقی و کبد، هر سه ترکیباتی را می سازند که واجد یون (هایی) درون خود است؛ بنابراین می توانند میزان یون های فضای درونی بخشی از لوله گوارش را تغییر دهند. به همین دلیل این گزینه در خصوص همۀ این اندام ها درست است. ب) این مورد در خصوص پانکراس درست است، اما کبد و غدد بزاقی، خون خروجی خود را به سیاهرگ باب کبدی نمی فرستند. ج) منظور از این مورد، پردۀ صفاق است. توجه داشته باشید صفاق پرده ای از جنس بافت پیوندی (با رشته های پروتئینی متنوع) است که اندام های درون حفره شکمی را به یکدیگر متصل می کند؛ مانند پانکراس و کبد. د) این مورد در خصوص پانکراس و غدد بزاقی درست است. غدد بزاقی با ترشح آمیلاز و پانکراس با ترشح انواعی از آنزیمهای پروتئینی در تبدیل مواد غذایی به ذرات کوچکتر نقش دارند. صفرا آنزیم ندارد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"563\":{\"correct_option_id\":4891,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; تمامی یاخته های زنده توانایی تجزیه گلوکز طی تنفس یاخته ای را دارند، همچنین آنزیم هایی دارند که مواد مختلف را تجزیه می کند. بررسی سایر گزینه ها: 1) به صورت کلی، یاخته های پوششی سطحی حفرات معده و یاخته های ترشح کننده ماده مخاطی، توانایی ترشح ماده مخاطی به فضای درونی معده را دارند؛ اما دقت داشته باشید که یاخته های پوششی سطحی جزء حفره معده محسوب می شوند؛ نه غده! 2) براساس شکل کتاب درسی دیده می شود که یاخته های اصلی و ترشح کننده ماده مخاطی، با یاخته های کناری در تماس هستند. 4) یاخته های اصلی و کناری، تحت تأثیر هورمون گاسترین قرار می گیرند و برای این هورمون گیرنده دارند.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"642\":{\"correct_option_id\":6056,\"descriptive_answer\":{\"text\":\"مطابق شکل کتاب درسی، غدۀ زیرزبانی در سمتی که به غدۀ بزاقی مجاورش (غده زیرآرواره&zwnj;ای) نزدیک&zwnj;تر است، نازک&zwnj;تر است. بررسی سایر گزینه&zwnj;ها: 1) توجه کنید غدۀ بزاقی بزرگی با این مشخصات وجود ندارد. 2) توجه کنید که مطابق شکل کتاب درسی، مجرای غدۀ بناگوشی از جلوی یا روی (نه پشت) ماهیچه اسکلتی (با ظاهر مخطط) عبور می&zwnj;کند. 3) غدۀ زیر آرواره&zwnj;ای مجرایی دارد که از کنار غدۀ زیرزبانی (جلویی&zwnj;ترین غدۀ بزاقی بزرگ) عبور می&zwnj;کند. پایین&zwnj;ترین غدۀ بزاقی بزرگ، غده زیر آرواره&zwnj;ای است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"1052\":{\"correct_option_id\":4405,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; منظور از صورت سؤال، آنزیم های آمیلاز و لیزوزیم است که دارای جایگاه فعال می باشند. تنها مورد &laquo;ب&raquo; صحیح است. بررسی همه موارد الف) نادرست؛ آنزیم آمیلاز بر روی نشاسته در دهان تأثیر می گذارد و آن را به مولکول های کوچک تر (نه تک پار) تبدیل می کند. همچنین لیزوزیم نیز آنزیم گوارش دهنده تا حد مونومر نمی باشد، بلکه آنزیمی است که دیواره باکتری ها را تجزیه می کند. دقت کنید آنزیم ها، طی واکنش، مصرف نمی شوند، بلکه فقط سبب تبدیل واکنش دهنده ها به فراورده ها می شوند. ب) درست؛ این آنزیم ها در بزاق وجود دارند و بزاق هم، توسط غدد بزاقی بزرگ و کوچک تولید می شود. هر غدۀ برون ریز در بدن انسان، در نهایت ترشحات خود را به درون ساختار مجرا یا مجراهایی وارد می کند. ج) نادرست؛ شبکه عصبی روده ای در انسان از مری تا مخرج گسترش یافته است و بنابراین تأثیری بر ترشحات غدد بزاقی در حفره دهانی ندارد. پل مغزی، ترشح بزاق را کنترل می کند. د) نادرست؛ آسیاب شدن غذا به ذره های بسیار کوچک برای فعالیت بهتر آنزیم های گوارشی (آمیلاز) بر غذا لازم است. این مورد درباره لیزوزیم صادق نیست.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8278\":{\"correct_option_id\":51072,\"descriptive_answer\":{\"text\":\"پاسخ تشریحی آغاز گوارش شیمیایی پروتئین ها در معده و پایان گوارش شیمیایی لیپیدها در روده باریک صورت می گیرد. معده، هورمون گاسترین را ترشح می کند که بر یاخته های اصلی و کناری غدد خود این اندام (بخشی از لوله گوارش) اثر می گذارد؛ اما روده باریک، سکرتین را ساخته و ترشح می کند که محرک ترشح بی کربنات شیره پانکراس (خارج از لوله گوارش) می باشد.\\r\\n\\r\\nبررسی سایر گزینه ها:\\r\\n\\r\\n$ 1 $ بنداره انتهایی معده (پیلور) در سمت راست بدن قرار دارد. بنداره انتهایی روده باریک نیز که در محل اتصال آن با روده کور قرار دارد، در سمت راست بدن قابل مشاهده خواهد بود.\\r\\n\\r\\n$ 3 $ پروتئازهای معده، ابتدا به صورت غیرفعال (پپسینوژن) ترشح شده و سپس با کمک اسیدکلریدریک و حتی خود پپسین فعال می شوند. پروتئازهای شیره پانکراس نیز که به فضای روده باریک می ریزند، ابتدا غیرفعال بوده و پس از ورود به محیط روده فعال می شوند.\\r\\n\\r\\n$ 4 $ بخشی از خون خروجی از معده در بخش قوس بزرگ آن با خون لوزالمعده و کولون پایین رو مخلوط می شود و به سیاهرگ باب می ریزد. از طرفی طبق شکل $15$ فصل $2$ دهم، خون بخشی از روده باریک نیز به خون خروجی از کولون بالارو می پیوندد (با آن مخلوط می شود) و در نهایت به سیاهرگ باب می ریزد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{},\"submittedQuestionIds\":[497,357,336,350,1052,8278,563,551,419,642],\"totalTimeSpent\":40,\"questionTimes\":{\"336\":1000,\"350\":1000,\"357\":996,\"497\":32004,\"1052\":1000,\"8278\":4000},\"selectionLog\":[]}}', '2026-08-23 12:19:47'),
(144, 68, 112, 0.00, 0, 1, 10, 0, 39, '{\"total_questions\":11,\"correct_count\":0,\"incorrect_count\":1,\"unanswered_count\":10,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"فصل دو یازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":10,\"total\":10},\"فصل سه دهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1}}}', '{\"evaluation\":{\"5293\":{\"correct_option_id\":32491,\"descriptive_answer\":{\"text\":\"برای افتراق هیدروکربن‌های سیرشده و سیرنشده می‌توان از برم استفاده کرد. برم قرمزرنگ است و در واکنش با هیدروکربن‌های سیرنشده رنگ خود را از دست می‌دهند و بی‌رنگ می‌شوند. این در حالی است که هیدروکربن‌های سیرشده در این واکنش شرکت نمی‌کنند و رنگ برم را تغییر نمی‌دهند.\\r\\n\\r\\nآلکن‌ها دسته‌ای از هیدروکربن‌های بدون حلقه هستند که در ساختار خود یک پیوند دوگانه دارند و فرمول شیمیایی آن‌ها به‌صورت $CnH2n$ است. دیگر خانواده هیدروکربن‌ها یعنی سیکلوآلکان‌ها با فرمول عمومی $CnH2n$ هستند که ایزومر آلکن‌ها محسوب می‌شوند. سیکلوآلکان‌ها هیدروکربن‌های سیرشده و آلکن‌ها سیرنشده هستند. پس با استفاده از واکنش با برم می‌توان این دو خانواده را از هم تفکیک کرد.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n1 فرمول شیمیایی بنزن $C6H6$ و فرمول شیمیایی نفتالن $C10H8$ است. برای مقایسه درصد جرمی کربن در دو هیدروکربن، به نسبت شمار اتم‌های کربن به هیدروژن آن‌ها نگاه می‌کنیم، هر چه این نسبت بیشتر باشد، درصد جرمی کربن بیشتر خواهد بود. پس درصد جرمی کربن در نفتالن بیشتر است.\\r\\n\\r\\nهمچنین حجم و جرم مولکول‌های نفتالن بیشتر از بنزن بوده و مولکول‌های سنگین‌تری داشته و نیروی بین مولکولی در نفتالن قوی‌تر است و به همین علت می‌توان گفت نقطه جوش نفتالن بیشتر از نقطه جوش بنزن است.\\r\\n\\r\\n3 سیکلو (Cyclo) پیشوندی به معنای حلقوی است که برای نام‌گذاری برخی از (و نه همه) ترکیب‌های آلی حلقوی به کار می‌رود. به‌عنوان مثال سیکلوآلکان‌ها دسته‌ای از هیدروکربن‌های هستند که در ساختار آن‌ها تمام پیوندها یگانه است و تنها یک حلقه در ساختار آن دیده می‌شود. همچنین در نام بنزن، پیشوند سیکلو دیده نمی‌شود.\\r\\n\\r\\n4 فرمول پیوند-خط بنزن و نفتالن به‌صورت زیر است:\\r\\n\\r\\n\\r\\n\\r\\nنسبت تعداد خط به کار رفته در فرمول نفتالن و بنزن برابر است با:\\r\\n\\r\\n$A = 16 / 9 \\\\cong 1/8$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":32490,\"is_answered\":true},\"7854\":{\"correct_option_id\":44581,\"descriptive_answer\":{\"text\":\"گام اول، قبل از هر چیز باید حواستان باشد که در این جا مقاومت معادل برابر مقاومت رئوستا نیست بلکه باید آن را حساب کنیم؛ پس ابتدا مقاومت معادل مدار را در دو حالتی که توان خروجی باتری یکسان است، به دست می آوریم:\\r\\n\\r\\n$R_{eq} = R$ رئوستا $ + 1 => R_{eq_1} = 1 + 1 = 2 Ω , R_{eq_2} = 7 + 1 = 8 Ω$\\r\\n\\r\\nگام دوم، حال با توجه به این که توان خروجی باتری در دو حالت $R_{eq_1}$ و $R_{eq_2}$ با یکدیگر برابر است مقاومت درونی باتری را با استفاده از رابطه $r = √(R_{eq_1} R_{eq_2})$ به دست می آوریم.\\r\\n\\r\\n$r = √(2 × 8) = 4 Ω$\\r\\n\\r\\nگام سوم، جریان خروجی از باتری را در حالتی که مقاومت رئوستا برابر با $6 Ω$ است، محاسبه می کنیم:\\r\\n\\r\\n$R_{eq_3} = 6 + 1 = 7 Ω$\\r\\n\\r\\n$I = ε / R_{eq_3} + r => I = 22 / 7 + 4 => I = 2 A$\\r\\n\\r\\nگام چهارم، در نهایت توان خروجی باتری را با استفاده از رابطه $P$ خروجی $ = εI - rI^2$ به دست می آوریم:\\r\\n\\r\\n$P$ خروجی $ = εI - rI^2 => P = 22(2) - 4(2)^2 => P = 28 W$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7855\":{\"correct_option_id\":44579,\"descriptive_answer\":{\"text\":\"پاسخ تشریحی بررسی عبارت ها:\\r\\n\\r\\nالف) رساناهای الکتریکی خوب مقاومت ویژه بسیار کم و عایق های خوب، مقاومت ویژه بسیار زیادی دارند. دسته ای از مواد وجود دارند که مقاومت ویژه آن ها بین مقاومت ویژه رساناها و نارساناها است؛ به عبارت دیگر، مقاومت ویژه این مواد از مقاومت ویژه رساناها بیشتر و از مقاومت ویژه نارساناها کم تر است. به این دسته از مواد، نیم رسانا می گویند. (✔)\\r\\n\\r\\nب) در برخی مواد مانند جیوه و قلع با کاهش دما، مقاومت ویژه در دمای خاصی به صورت ناگهانی افت می کند و به صفر می رسد و در دماهای پایین تر، هم چنان مقاومت ویژه آن صفر می ماند. به این پدیده، ابررسانایی می گویند. (✖) در این عبارت به اشتباه گفته شده که سیلیسیم و ژرمانیم ابررسانا هستند، در حالی که این دو ماده نیم رسانا هستند!\\r\\n\\r\\nپ) مقاومت ویژه یک ماده به ساختار اتمی و دمای آن بستگی دارد و افزایش طول یا کاهش مساحت آن تأثیری بر مقاومت ویژه نمی گذارد. (✖) (افزایش طول یا کاهش مساحت، مقاومت را افزایش می دهد، اما تأثیری روی مقاومت ویژه ندارد.)\\r\\n\\r\\nت) مقاومت ویژه رساناهای فلزی با افزایش دما زیاد می شود، در حالی که مقاومت ویژه نیم رساناها با افزایش دما، کاهش می یابد. (✔)\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7868\":{\"correct_option_id\":44401,\"descriptive_answer\":{\"text\":\"گام اول: جریان عبوری از باتری را به دست می آوریم:\\r\\n\\r\\n$ R=V/I => 5=(2/5)/I => I=0/5A$\\r\\n\\r\\nگام دوم: $ 2000 mA.h$ ، مقدار باری است که به طور ایمن از باتری تخلیه میشود و $ 0/5 A$ ،جریان خروجی باتری است، مدت زمان تخلیه بار از باتری برابر است با :\\r\\n\\r\\n$ I= \\\\Delta q / \\\\Delta t \\\\rightarrow 0/5 A = 2A.h / \\\\Delta t => \\\\Delta t = 4h = 240 min$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7928\":{\"correct_option_id\":44169,\"descriptive_answer\":{\"text\":\"$19$ - گزینه «$2$» مقاومت معادل مدار را در دو حالت به‌دست می‌آوریم. چون مقاومت‌ها موازی‌اند، داریم: $1 / R_{eq} = 1 / 12 + 1 / 4 => R_{eq} = 3 Ω$ $1 / R\'_{eq} = 1 / 12 + 1 / 12 => R\'_{eq} = 6 Ω$ چون به‌ازای $R_{eq} = r = 4 Ω$ توان خروجی مولد بیشینه می‌شود، بنابراین با توجه به نمودار توان خروجی برحسب مقاومت معادل مدار، وقتی مقاومت از $3Ω$ به $4Ω$ می‌رسد، توان خروجی افزایش و پس از آن وقتی از $4Ω$ به $6Ω$ می‌رسد، توان خروجی کاهش می‌یابد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8005\":{\"correct_option_id\":43859,\"descriptive_answer\":{\"text\":\"$96$ - گزینه «$4$» ابتدا با استفاده از رابطه چگالی، رابطه‌ای بین $L$ و $A$ می‌یابیم: $m = ρV -> V=AL -> m = ρAL => mA / mB = ρA / ρB × AA / AB × LA / LB$ $-> ρA=4/3 ρB, mB=12mA -> mA / 12mA = 4/3 ρB / ρB × AA / AB × LA / LB => LA / LB = 1/16 × AB / AA$ اکنون با استفاده از رابطه $R = ρ L / A$ و با توجه به این که $A = πr^2$ است، می‌توان نوشت: $RA / RB = ρA / ρB × LA / LB × AB / AA -> RA=RB, ρB=4ρA -> 1 = ρA / 4ρA × 1/16 × AB / AA × AB / AA$ $=> (AB / AA)^2 = 64 => AB / AA = 8 -> A=πr^2 -> πrB^2 / πrA^2 = 8 => (rB / rA)^2 = 8$ $=> rB / rA = 2√2 => rA = 1 / 2√2 rB => rA = √2 / 4 rB$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8020\":{\"correct_option_id\":43796,\"descriptive_answer\":{\"text\":\"111- گزینه «1»  میدانیم توان خروجی باتری برابر توان مصرفی مقاومت معادل مدار است. بنابراین، به جای استفاده از رابطه $P=εI-rI2$ ، از رابطه $P=RI2$ استفاده می کنیم. در اینجا، برای حالت اول $R1=R$ و برای حالت دوم $R2=6R$ و $r=3R$ است. بنابراین، با استفاده از رابطه $I = ε / R+r$ ، جریان الکتریکی در هر حالت را می یابیم و سپس نسبت توان ها را حساب می کنیم: $I1 = ε / R1+r -R1=R / r=3R-> I1 = ε / R+3R => I1 = ε / 4R$ $I2 = ε / R2+r -R2=6R / r=3R-> I2 = ε / 6R+3R => I2 = ε / 9R$ $P=RI2 => P2/P1 = R2/R1*(I2/I1)2 -R2=6R / R1=R-> P2/P1 = 6R/R*(ε/9R / ε/4R)2$ $=> P2/P1 = 6*(4/9)2 => P2/P1 = 6*16/81 => P2/P1 = 32/27$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8044\":{\"correct_option_id\":43702,\"descriptive_answer\":{\"text\":\"135- گزینه «3» با داشتن اختلاف پتانسیل دو سر باتری، ابتدا به‌صورت زیر، جریان مدار را می‌یابیم: $V = ε - rI → V=15V,ε=18V / r=0/5Ω → 15 = 18 - 0/5×I ⇒ I = 6A$ اکنون با استفاده از رابطه توان الکتریکی، مقاومت متغیر $R$ را به ازای توان مصرفی $P = 54W$ می‌یابیم: $P = RI2 → P=54W / I=6A → 54 = R×36 ⇒ R = 1/5Ω$ در آخر، با استفاده از رابطه زیر، مقاومت $R\'$ را پیدا می‌کنیم و به دنبال آن نسبت $r/R\'$ را می‌یابیم: $I = ε / Req+r$ $V = ReqI → V = Reqε / Req+r ⇒ 15 = Req×18 / Req+0/5$ $⇒ Req = 2/5Ω$ $Req = R+R\' ⇒ 2/5 = 1/5+R\'$ $⇒ R\' = 1Ω$ $r / R\' = 0/5 / 1 ⇒ r / R\' = 1 / 2$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8077\":{\"correct_option_id\":43501,\"descriptive_answer\":{\"text\":\"تمام وسایل الکتریکی خانگی با ولتاژ $220 V$ کار می‌کنند. به این ترتیب وقتی همه وسایل روشن هستند، به‌طور موازی به یکدیگر متصل‌اند و جریانی که از فیوز در شاخه اصلی می‌گذرد، مجموع جریان‌هایی است که از هر وسیله روشن می‌گذرد.\\r\\n\\r\\n$I$ فیوز $ = I$ اتو $ + I$ بخاری $ + I$ لامپ‌ها\\r\\n\\r\\n$P = VI ⇒ I = P / V ⇒ 15 = 2000 / 220 + 860 / 220 + 40 N / 220 ⇒ 15 = 13 + 2 / 11 N ⇒ N = 11$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8098\":{\"correct_option_id\":43414,\"descriptive_answer\":{\"text\":\"اختلاف پتانسیل پایانه‌های منبع با اختلاف پتانسیل دو سر مقاومت 5 اهمی برابر است؛ ازاین‌رو جریان در مدار برابر خواهد بود با:\\r\\n\\r\\n$V=RI ⇒ 40=5×I ⇒ I=8A$\\r\\n\\r\\nرابطه اختلاف پتانسیل دو سر منبع به‌صورت زیر است:\\r\\n\\r\\n$V=ε-rI ⇒ 40=ε-0/25×8 ⇒ ε=42V$\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8101\":{\"correct_option_id\":43398,\"descriptive_answer\":{\"text\":\"چون ولت‌سنج آرمانی است، جریانی از شاخه شامل ولت‌سنج عبور نمی‌کند، بنابراین سه مقاومت $R_2$ ، $R_1$ و $R_3$ متوالی خواهند بود. از طرفی آمپرسنج آرمانی است، پس جریانی از مقاومت 3 اهمی عبور نمی‌کند (اتصال کوتاه)؛ بنابراین مدار به صورت روبه‌رو ساده می‌شود.\\r\\n\\r\\n$R_eq=R_1+R_2+R_3=2+5+1=8Ω$\\r\\n\\r\\n$I=ε/(R_eq+r)=18/(8+1)=2A$ آمپرسنج $2A$ را نشان می‌دهد. $⇒$\\r\\n\\r\\nولت‌سنج $14V$ را نشان می‌دهد. $⇒ V_B-V_A=R_1,2×I=7×2=14V$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو یازدهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"5293\":32490},\"submittedQuestionIds\":[8077,8101,8098,7928,8005,7868,8020,7854,8044,5293,7855],\"totalTimeSpent\":39,\"questionTimes\":{\"5293\":28989,\"8077\":2004},\"selectionLog\":[{\"questionId\":5293,\"optionId\":32490,\"timeSpentMs\":6997,\"timestamp\":1787488295140}]}}', '2026-08-23 12:32:05');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(145, 69, 4, 7.14, 2, 4, 22, 2, 127, '{\"total_questions\":28,\"correct_count\":2,\"incorrect_count\":4,\"unanswered_count\":22,\"accuracy_rate\":7.14,\"score\":2,\"mabhas_stats\":{\"دو دوازدهم\":{\"correct\":1,\"incorrect\":2,\"unanswered\":1,\"total\":4},\"فصل هفت دهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":9,\"total\":10},\"فصل پنج دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":6,\"total\":6},\"مثلثات دوازدهم\":{\"correct\":1,\"incorrect\":1,\"unanswered\":6,\"total\":8}}}', '{\"evaluation\":{\"403\":{\"correct_option_id\":5713,\"descriptive_answer\":{\"text\":\"همه موارد درست هستند. الف) تنظیم آب تحت عوامل مختلفی قرار دارد. یکی از سازوکارها به غلظت مواد حل شده در خوناب ارتباط دارد. اگر غلظت مواد از حد مشخصی فراتر رود، ترشح هورمون ضد ادراری تحریک می&zwnj;شود. این هورمون با اثر بر کلیه&zwnj;ها، بازجذب آب را افزایش می&zwnj;دهد و مقدار دفع آب از طریق ادرار کاهش می&zwnj;یابد. ب) یکی از ماده&zwnj;های دفعی نیتروژن&zwnj;دار در ادرار اوریک اسید است. اوریک&zwnj;اسید انحلال&zwnj;پذیری زیادی در آب ندارد (نه این که اصلاً در آب حل نشود)؛ بنابراین تمایل آن به رسوب کردن و تشکیل بلور زیاد است. رسوب بلورهای اوریک&zwnj;اسید در کلیه&zwnj;ها باعث ایجاد سنگ کلیه می&zwnj;شود. دقت کنید اندکی از اوریک&zwnj;اسید در آب حل شده و بلور کمتری تشکیل می&zwnj;شود. در نتیجه، آب بیشتر در تشکیل سنگ کلیه کمتر، نقش دارد. ج) هورمون ضد&zwnj;ادراری باعث بازجذب بیشتر آب به خون می&zwnj;شود (جابجایی آب بیشتر از نفرون به مویرگ). بنابراین خونی که در انتهای شبکه مویرگی دور لوله ای (رگی که در مجاورت بخش صعودی لوله هنله است) جریان دارد، مقدار آب بیشتر و فشار اسمزی کمتری دارد. د) در انتهای میزنای دریچه ای قرار دارد که حاصل چین&zwnj;خوردگی مخاط مثانه بر روی دهانه میزنای است (مانع بازگشت ادرار از مثانه به میزنای می&zwnj;شود). در هنگام دفع، آب پس از عبور از این دریچه به مثانه وارد می&zwnj;شود. چنانچه حجم ادرار جمع شده در مثانه از حد مشخصی فراتر رود، کشیدگی دیواره مثانه باعث فعال شدن سازوکار تخلیه ادرار می&zwnj;شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"476\":{\"correct_option_id\":5441,\"descriptive_answer\":{\"text\":\"در سرخرگ&zwnj;های کوچک&zwnj;تر (مانند سرخرگ کلیه)، نسبت به سرخرگ&zwnj;های بزرگ (مانند سرخرگ آئورت)، میزان رشته&zwnj;های کشسان، کمتر و میزان ماهیچه&zwnj;های صاف، بیشتر است. 2) اوره جزء مواد دفعی است و مقداری از اوره که توسط سرخرگ وارد کلیه می&zwnj;شود، از خون خارج شده و وارد نفرون&zwnj;ها می&zwnj;شود. بنابراین، مقدار اوره و سایر مواد دفعی در سرخرگ کلیه بیشتر از سیاهرگ کلیه است. 3) فشار تراوشی ناشی از فشار خون است و با توجه به اینکه به طور کلی، فشار خون در سرخرگ&zwnj;ها بیشتر از سیاهرگ&zwnj;ها است، فشار تراوشی نیز در سرخرگ آئورت بیشتر از بزرگ سیاهرگ زیرین است. اما فشار اسمزی ناشی از پروتئین&zwnj;های خون است و با توجه به اینکه مقدار پروتئین&zwnj;های خون ثابت است، فشار اسمزی نیز در رگ&zwnj;های نشان داده شده برابر است. 4) دریچه&zwnj;های لانه کبوتری، دریچه&zwnj;هایی هستند که در سیاهرگ&zwnj;ها وجود دارند و باعث ایجاد جریان یک&zwnj;طرفه خون در سیاهرگ می&zwnj;شوند. این دریچه&zwnj;ها در سیاهرگ&zwnj;های دست و پا وجود دارند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"480\":{\"correct_option_id\":5440,\"descriptive_answer\":{\"text\":\"پس از ورود ادرار به مثانه، دریچه&zwnj;ای که حاصل چین&zwnj;خوردگی مخاط مثانه روی دهانه میزنای است، مانع بازگشت ادرار به میزنای می&zwnj;شود. چنانچه حجم ادرار جمع&zwnj;شده در مثانه از حد مشخصی فراتر رود، کشیدگی دیواره مثانه باعث فعال شدن سازوکار تخلیه ادرار می&zwnj;شود (نادرستی گزینه ۱ و ۲؛ این دو گزینه قبل از فعال شدن سازوکار تخلیه مثانه رخ می&zwnj;دهند). در محل اتصال مثانه به میزراه، بنداره داخلی میزراه (دارای ماهیچه صاف) قرار دارد که هنگام ورود ادرار باز می&zwnj;شود. بعد از این بنداره، بنداره خارجی میزراه (دارای ماهیچه مخطط) است. برای تخلیه مثانه، لازم است که انقباض هر دو بنداره کم شود (نه اینکه پیام انقباض را دریافت کنند و منقبض شوند) تا بنداره باز شود و ادرار بتواند از بدن خارج شود (نادرستی گزینه ۳). در نوزادان و کودکانی که هنوز ارتباط مغز و نخاع آنان به طور کامل شکل نگرفته است، تخلیه مثانه به صورت غیرارادی انجام می&zwnj;شود. در نتیجه، در یک نوزاد یک ماهه، باز شدن بنداره خارجی میزراه در پی کاهش انقباض ماهیچه آن نیز به صورت غیرارادی انجام می&zwnj;شود (درستی گزینه ۴).\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"604\":{\"correct_option_id\":6021,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در لوله های مالپیگی متصل به رودۀ حشرات و غدد راست روده ای ماهیان غضروفی ساکن آب شور، تعامل مستقیمی میان سامانه تنظیم اسمزی و بخشی از رودۀ جانور وجود دارد. حشرات دارای اسکلت بیرونی و ماهیان دارای اسکلت درونی هستند؛ در هر دو نوع اسکلت بیرونی و درونی، این اسکلت از اندام های درونی پیکر جانور محافظت می کند. بررسی سایر گزینه ها: 2) باریک ترین رگ های خونی مویرگ ها هستند. توجه داشته باشید که حشرات دارای سامانه گردشی باز هستند. جانورانی که سامانه گردشی باز دارند، مویرگ ندارند و همولنف مستقیما به فضای بین یاخته های بدن آن ها وارد می شود و در مجاورت آن ها جریان می یابد! اما در ماهی ها، شبکه مویرگی وجود دارد. 3) قلب در سامانه باز، مایعی به نام همولنف را به حفره های بدن پمپ می کند که همولنف نقش های خون، لنف و آب میان بافتی را بر عهده دارد! در ماهی ها پیک های شیمیایی درون خون دیده می شوند. 4) توجه کنید که نه حشرات و نه ماهیان غضروفی، اسکلت استخوانی ندارند و در نتیجه یاخته استخوانی هم ندارند!\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"606\":{\"correct_option_id\":6019,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; ماهی های آب شیرین در محیطی زندگی می کنند که فشار اسمزی کم تری نسبت به مایعات بدن جانور دارد و آب به راحتی از طریق اسمز وارد بدن جانور می شود و به همین دلیل معمولا آب زیادی نمی نوشند؛ اما در ماهی های آب شور، به دلیل بیشتر بودن فشار اسمزی محیط نسبت به مایعات بدن، آب تمایل به خروج از بدن دارد. بررسی سایر گزینه ها: 1) در هر دو ماهی، دفع مواد زائد نیتروژن دار از طریق کلیه صورت می گیرد. در ماهیان آب شور، برخی یون ها (نه مواد دفعی نیتروژن دار!) از طریق یاخته های آبشش دفع می شوند. 2) ماهیان آب شیرین، برخلاف ماهیان آب شور ادرار رقیق دفع می کنند. در افراد مبتلا به دیابت بی مزه نیز به دلیل کاهش بازجذب آب، فرد ادرار رقیق دفع می کند. 4) در ماهیان آب شیرین، فشار اسمزی مایعات بدن از محیط بیشتر است و این ماهی ها معمولا آب زیادی نمی نوشند. برعکس در ماهیان آب شور، فشار اسمزی مایعات بدن کم تر از محیط است، در نتیجه این ماهیان مقدار زیادی آب می نوشند؛ بنابراین در هر دو گروه میزان نوشیدن آب با فشار اسمزی مایعات بدن رابطه عکس دارد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"607\":{\"correct_option_id\":6015,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; برخی از خزندگان و پرندگان دریایی و بیابانی که آب دریا یا غذای نمک دار مصرف می کنند، می توانند نمک اضافه را از طریق غدد نمکی نزدیک چشم یا زبان، به صورت قطره های غلیظ دفع کنند. دقت کنید که کلیه ها در همۀ خزندگان و پرندگان توانمندی زیادی در بازجذب آب دارند. بررسی سایر گزینه ها: 1) این جانوران، دارای گردش خون مضاعف هستند، پس در قلب چند حفره ای (دو دهلیز و دو بطن دارند) آن ها علاوه بر خون تیره، خون روشن نیز وجود دارد. تغذیه یاخته های ماهیچه قلب همواره با خون روشن و غنی از اکسیژن صورت می گیرد. 2) جدایی کامل بطن ها در پرندگان و پستانداران و برخی خزندگان مثل کروکودیل ها رخ می دهد. این حالت، حفظ فشار در سامانه گردشی مضاعف را آسان می کند؛ در نتیجه کارایی خون رسانی به یاخته ها نسبت به سایر جانداران بیشتر است؛ بنابراین این گزینه ویژگی پرندگان ساکن مناطق بیابانی نمی باشد. 4) مثانه دوزیستان محل ذخیره آب و یون هاست و به هنگام خشک شدن محیط، دفع ادرار کم و مثانه برای ذخیره بیشتر آب بزرگ تر می شود و سپس بازجذب آب از مثانه به خون افزایش پیدا می کند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"893\":{\"correct_option_id\":6591,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; در پروکاریوت ها، منظور از توالی ویژه مؤثر در رونویسی، می تواند توالی راه انداز، اپراتور، جایگاه اتصال فعال کننده و یا توالی پایان رونویسی باشد. در یوکاریوت ها، توالی افزاینده هم، نوعی توالی ویژه است که در رونویسی نقش دارد. از بین مراحل طویل شدن و پایان، فقط در مرحله پایان، پس از رونویسی شدن توالی پایان رونویسی (جزئی از ژن)، آنزیم رنابسپاراز از مولکول دنا (DNA) جدا می شود. دقت کنید که سایر توالی های نام برده شده جزئی از توالی ژن نمی باشند. بررسی سایر گزینه ها: 1) شکسته شدن پیوندهای هیدروژنی میان دو رشته دنا (و در نتیجه پیوندهای بین نوکلئوتیدهایی با قندهای یکسان) را هم در مرحله طویل شدن و هم در مرحله پایان ترجمه می توان مشاهده نمود؛ نه در برخی از آن ها! 2) این گزینه در خصوص مرحله پایان رونویسی است که بعد از رونویسی شدن توالی پایان رونویسی، رنابسپار از از دنا جدا می شود. اما توجه داشته باشید که در پروکاریوت ها، دنای &laquo;هسته ای!&raquo; نداریم و این گزینه از بیخ و بن نادرست می باشد. 4) در مرحله آغاز رونویسی، راه انداز موجب می شود رنا بسپار از اولین نوکلئوتید مناسب را به طور دقیق پیدا و رونویسی را از آنجا آغاز کند. در این حالت بخش کوچکی از مولکول دنا باز و زنجیره کوتاهی از رنا ساخته می شود. با این اوصاف، این گزینه در خصوص هیچ یک از مراحل طویل شدن و پایان صادق نیست.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6589,\"is_answered\":true},\"894\":{\"correct_option_id\":6581,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; موارد &laquo;الف&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) پس از خروج رنای ناقل فاقد آمینواسید از جایگاهE ، براساس وجود یا عدم وجود کدون پایان در جایگاه ،A دو اتفاق می تواند رخ دهد. یا عامل آزاد کننده به جایگاه A وارد می شود (اگر کدون پایان در جایگاه A (باشد که در نهایت رنای ناقل و زنجیره پلی پپتیدی از جایگاه P ریبوزوم خارج می شوند؛ و اگر کدون رمزکننده یک آمینواسید در جایگاه A باشد، جایگاه A آماده پذیرش رنای ناقل بعدی می شود که پس از ورود و استقرار رنای ناقل مکمل به این جایگاه پیوند اشتراکی در جایگاه P ریبوزوم شکسته می شود تا پیوند پپتیدی بعدی تشکیل شود. ب) این مورد همواره رخ می دهد و مخصوص شرایط خاصی نیست! دقت کنید که تشکیل پیوند پپتیدی در جایگاه A رناتن اتفاق می افتد و کمی پس از تشکیل آن، همواره جابه جایی رناتن بر روی رنای پیک رخ میدهد که در نتیجه آن، رنای ناقل متصل به رشته پپتیدی به جایگاه P وارد میشود و رنای ناقل فاقد آمینواسید پس از ورود به جایگاه E رناتن، از آن خارج می گردد. ج) علاوه بر مرحله پایان ترجمه که پیوند بین رشته آمینواسیدی و tRNA شکسته می شود، طی طویل شدن هم این اتفاق می افتد، اما در پایان برخلاف طویل شدن tRNA ،فاقد آمینواسید به جایگاه E منتقل نمیشود بنابراین این جمله فقط درباره مرحله طویل شدن ترجمه صدق می کند یعنی در برخی شرایط رخ می دهد. د) کمی پیش از تشکیل پیوند پپتیدی در جایگاه ،A ریبوزوم پیوند اشتراکی بین آمینواسید و tRNA در جایگاه میانی ریبوزوم (جایگاه(P شکسته می شود. در واقع اگر قرار باشد پیوند پپتیدی تشکیل شود، همواره (نه در برخی شرایط!) باید رشته پپتیدی یا آمینواسید متصل به رنای ناقل در جایگاه ،P از این رنای ناقل جدا شود و سپس به جایگاه A منتقل گردد تا در نهایت به آمینواسید موجود در این جایگاه متصل شود. بنابراین، پیش از تشکیل هر پیوند پپتیدی حین ترجمه، باید پیوند اشتراکی بین رنای ناقل و بخش پپتیدی (یا آمینواسید) متصل به آن شکسته شود.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6583,\"is_answered\":true},\"896\":{\"correct_option_id\":6585,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در یک مولکول رنای ناقل، هر نوکلئوتیدی که در یک انتهای رشته پلی نوکلئوتیدی قرار دارد با سایر نوکلئوتیدهای این رنا، فقط یک پیوند فسفودی استر تشکیل می دهد. براساس شکل کتاب درسی دیده می شود که در رنای ناقل، یکی از این دو نوکلئوتید در جایگاه اتصال به آمینواسید قرار دارد و با نوکلئوتید دیگری در ساختار رنای ناقل، پیوند هیدروژنی تشکیل نمی دهد. طبق شکل کتاب درسی، نوکلئوتید دیگر، در انتهای دیگر رشته پلینوکلئوتیدی پیوند هیدروژنی تشکیل می دهد. بررسی سایر گزینه ها: 2) در ساختار رنای ناقل ،یک نوکلئوتید در یک توالی سه نوکلئوتیدی در یک انتهای tRNA ، جایگاه اتصال به آمینواسید را تشکیل می دهد. مطابق شکل کتاب درسی، این نوکلئوتید جایگاه اتصال به آمینواسید در دورترین نقطه (بیشترین تعداد نوکلئوتید بین آن ها) نسبت به توالی پادرمزه (آنتی کدون) قرار دارد. براساس توالی پادرمزه، آمینواسید خاصی به رنای ناقل متصل می شود. 3) دو حلقه از رنای ناقل که فاقد توالی پادر مزه هستند، در ساختار سه بعدی مولکول رنای ناقل نسبت به تاخوردگی اولیه به یکدیگر نزدیک تر هستند. 4) ساختار نهایی میوگلوبین، ساختار سوم آن است. در میوگلوبین، برای اولین بار، تاخوردگی ها در ساختار دوم رخ می دهد که باعث ایجاد ساختار مارپیچ می شود و تاخوردگی های بیشتر نیز برای تشکیل ساختار سوم ایجاد می شود تا ساختار نهایی پروتئین شکل بگیرد. رنای ناقل نیز پس از تاخوردگی اولیه، تاخوردگی های مجددی پیدا میکند که ساختار سه بعدی آن را پدید می آورد.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6585,\"is_answered\":true},\"897\":{\"correct_option_id\":6572,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; در مرحله آغاز و پایان ترجمه، رنای ناقل در جایگاه A و E ریبوزوم دیده نمی شود. در مرحله آغاز، زیرواحد بزرگ ریبوزوم به زیرواحد کوچک آن متصل می شود و در مرحله پایان ترجمه، زیرواحد بزرگ ریبوزوم از زیرواحد کوچک آن جدا خواهد شد؛ پس تمایل آن ها برای اتصال به هم تغییر می کند. بررسی سایر گزینه ها: 1) دقت داشته باشید این مولکول پلی پپتیدی می تواند دو نوع مولکول مختلف باشد؛ یکی رشته پلی پپتیدی در حال ساخت که به رنای ناقل موجود در جایگاه A اتصال دارد و طی مرحله طویل شدن و با حرکت رناتن وارد جایگاه P می شود. دیگری نیز ممکن است پروتئین آزادکننده باشد که نوعی مولکول پلی پپتیدی است و در مرحلۀ پایان در جایگاه A قرار می گیرد. با قرار گیری پروتئین آزاد کننده در جایگاه ،A دیگر حرکتی توسط رناتن به سمت جلو صورت نمی گیرد. 2) طبق شکل و متن کتاب درسی، در هیچ یک از مراحل ترجمه، امکان این که به صورت هم زمان جایگاه های A و E رناتن توسط رناهای ناقل اشغال شوند، وجود ندارد! زیرا همواره قبل از ورود tRNA به جایگاه ،A رنای ناقل فاقد آمینواسید از جایگاه E خارج شده است. فقط در مرحله طویل شدن، رنای فاقد آمینواسید در جایگاه E دیده می شود. 3) در مرحله طویل شدن، حداکثر دو رنای ناقل به صورت هم زمان در جایگاه های رناتن قابل مشاهده هستند و در مرحله آغاز و پایان فقط یک رنای ناقل در رناتن دیده می شود. طبق شکل کتاب درسی، در فرایند ترجمه، هر آمینواسید جدید به انتهای کربوکسیل (نه آمین) رشته پپتیدی در حال ساخت متصل می گردد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1958\":{\"correct_option_id\":44560,\"descriptive_answer\":{\"text\":\"19- پاسخ: گزینه 1 ▲ مشخصات سؤال: متوسط * صفحه 43 ریاضی 3\\r\\n\\r\\nنکته: $Sin 2α = 2Sin α Cos α$\\r\\n\\r\\nنکته: $Cos 2α = 2Cos^2 α - 1$\\r\\n\\r\\nابتدا عبارت داده شده را ساده می کنیم:\\r\\n\\r\\n$Sin 2α / Sin α = 0/5 \\\\Rightarrow 2Sin α Cos α / Sin α = 1/2 \\\\Rightarrow Cos α = 1/4$\\r\\n\\r\\nبنابراین مقدار خواسته شده برابر است با:\\r\\n\\r\\n$Cos 2α / Cos α = (2Cos^2 α - 1) / Cos α = (2(1/4)^2 - 1) / (1/4) = (2/16 - 1) / (1/4) = (-7/8) / (1/4) = -7/2 = -3/5$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1962\":{\"correct_option_id\":44621,\"descriptive_answer\":{\"text\":\"23- پاسخ: گزینه 2 ▲ مشخصات سؤال: دشوار * صفحه 48 ریاضی 3\\r\\n\\r\\nنکته: جواب های کلی معادله $Sin x = Sin \\\\alpha$ به صورت $x = 2k\\\\pi + \\\\alpha$ یا $x = 2k\\\\pi + \\\\pi - \\\\alpha$ می باشند که $k \\\\in \\\\mathbb{Z}$.\\r\\n\\r\\nنکته: $Sin(\\\\frac{\\\\pi}{2} - \\\\alpha) = Cos \\\\alpha$\\r\\n\\r\\nابتدا نسبت های مثلثاتی دو طرف را یکسان می کنیم. مثلاً می توانیم به جای $Cos 3x$ عبارت $Sin(\\\\frac{\\\\pi}{2} - 3x)$ را جایگزین کنیم.\\r\\n\\r\\n$Cos 3x = Sin x \\\\Rightarrow Sin(\\\\frac{\\\\pi}{2} - 3x) = Sin x \\\\Rightarrow \\\\begin{cases} \\\\frac{\\\\pi}{2} - 3x = 2k\\\\pi + x \\\\\\\\ \\\\frac{\\\\pi}{2} - 3x = 2k\\\\pi + \\\\pi - x \\\\end{cases}$\\r\\n\\r\\n$\\\\Rightarrow \\\\begin{cases} 4x = -2k\\\\pi + \\\\frac{\\\\pi}{2} \\\\\\\\ 2x = -2k\\\\pi - \\\\frac{\\\\pi}{2} \\\\end{cases} \\\\Rightarrow \\\\begin{cases} x = -\\\\frac{k\\\\pi}{2} + \\\\frac{\\\\pi}{8} \\\\\\\\ x = -k\\\\pi - \\\\frac{\\\\pi}{4} \\\\end{cases}$\\r\\n\\r\\nجواب های $x = -k\\\\pi - \\\\frac{\\\\pi}{4}$ از مجموعه جواب $\\\\{\\\\frac{3\\\\pi}{4}\\\\}$ و جواب $x = -\\\\frac{k\\\\pi}{2} + \\\\frac{\\\\pi}{8}$ از مجموعه جواب $\\\\{\\\\frac{\\\\pi}{8} , \\\\frac{5\\\\pi}{8}\\\\}$ در بازه $[0 , \\\\pi]$ قرار دارد.\\r\\n\\r\\nمجموع این جواب ها برابر است با:\\r\\n\\r\\n$\\\\frac{\\\\pi}{8} + \\\\frac{5\\\\pi}{8} + \\\\frac{3\\\\pi}{4} = \\\\frac{6\\\\pi + 6\\\\pi}{8} = \\\\frac{12\\\\pi}{8} = \\\\frac{3\\\\pi}{2}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2245\":{\"correct_option_id\":62166,\"descriptive_answer\":{\"text\":\"21. گزینه 3 درست است. \\r\\n\\r\\nبا جایگذاری $\\\\cos 2x=2\\\\cos^{2}x-1$ خواهیم داشت:\\r\\n\\r\\n$(2\\\\cos^{2}x-1)-\\\\cosx+1=0$\\r\\n\\r\\n$2\\\\cos^{2}x-\\\\cosx=0 \\\\rightarrow \\\\cosx(2\\\\cosx-1)=0$\\r\\n\\r\\n$\\\\cosx=0 \\\\rightarrow x=k\\\\pi+\\\\frac{\\\\pi}{2},k \\\\in z$\\r\\n\\r\\n$\\\\cosx=\\\\frac{1}{2} \\\\rightarrow x=2k\\\\pi \\\\pm \\\\frac{\\\\pi}{3} , k \\\\in z$\\r\\n\\r\\nجوابهای بین 0 و $2\\\\pi$ عبارتند از:\\r\\n\\r\\n$x=\\\\frac{\\\\pi}{2},\\\\frac{3\\\\pi}{2}$\\r\\n\\r\\n$x=\\\\frac{\\\\pi}{3},x=\\\\frac{5\\\\pi}{3}$\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":62166,\"is_answered\":true},\"2295\":{\"correct_option_id\":62365,\"descriptive_answer\":{\"text\":\"۷1. گزینه 2 درست است.\\r\\n\\r\\nنقطه A روی منحنی$f(x)=2\\\\sin^2x$  و نقطه B روی منحنی$g(x)=\\\\cos2x$  است، پس وقتی طول پاره‌خط AB برابر دو واحد باشد. یعنی:\\r\\n\\r\\n$ y_A – y_B = 2 \\\\Rightarrow 2\\\\sin^2 x − \\\\cos2x = 2$\\r\\n\\r\\nبرای حل این معادله مثلثاتی از رابطه $ \\\\cos2x = 1 –\\\\sin^2 x $استفاده کرده و داریم:\\r\\n\\r\\n$2\\\\sin^2 x − (1 – 2\\\\sin^2x) = 2 \\\\rightarrow 4\\\\sin^2 x = 3 \\\\Rightarrow \\\\sin^2 x =\\\\frac{3}{4} \\\\Rightarrow \\\\sin x = \\\\pm\\\\frac{\\\\sqrt{3}}{2}$\\r\\n\\r\\nبا توجه به اینکه مطابق شکل طول نقاط  AوB در بازۀ $(\\\\frac{\\\\pi}{2},\\\\pi)$ قرار دارد، $x=\\\\pi-\\\\frac{\\\\pi}{3}=\\\\frac{2\\\\pi}{3}$ قابل قبول است. پس:\\r\\n\\r\\n$xA = xB = \\\\frac{2\\\\pi}{3}$\\r\\n\\r\\n$y_A =2\\\\sin^2 (\\\\frac{2\\\\pi}{3}) = 2(\\\\frac{\\\\sqrt{3}}{2})^2=\\\\frac{3}{2}$\\r\\n\\r\\nدرنتیجه:\\r\\n\\r\\n$\\\\frac{x_B}{y_A} = \\\\frac{\\\\frac{2\\\\pi}{3}}{\\\\frac{3}{2}}=\\\\frac{4\\\\pi}{9}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2612\":{\"correct_option_id\":74051,\"descriptive_answer\":{\"text\":\"می‌دانیم:\\r\\n\\r\\n$6π/14 = π/2 − π/14$و $3π/7 = 6π/14$\\r\\n\\r\\n$sin(3π/7) cos(π/14) − sin(π/6)$\\r\\n\\r\\n$= sin(π/2 − π/14) cos(π/14) − 1/2$\\r\\n\\r\\n$= cos(π/14) × cos(π/14) − 1/2$\\r\\n\\r\\n$= cos^2(π/14) − 1/2$\\r\\n\\r\\n$=1/2 (2cos^2(π/14) − 1) $\\r\\n\\r\\n$= 1/2cos(π/7) $\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":74050,\"is_answered\":true},\"2619\":{\"correct_option_id\":74083,\"descriptive_answer\":{\"text\":\"می‌دانیم:\\r\\n\\r\\n$α + β = π/2 ⇒ sin α = cos β$\\r\\n\\r\\n$sin 37° = 3/5 ⇒ cos 2α = 1 − 2sin^2 α$\\r\\n\\r\\n$cos 74° = 1 − 2(3/5)^2 = 1 − 2×9/25 = 7/25$\\r\\n\\r\\n$cos 74° = sin 16° ⇒ sin 16° = 7/25=0.28$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2639\":{\"correct_option_id\":74175,\"descriptive_answer\":{\"text\":\"$sin x≠1 \\\\quad (1)$\\r\\n\\r\\n$cos x≠1$\\r\\n\\r\\n$sin^2 x(sin x-1)=cos^2 x(1-cos x)\\r\\n\\r\\n⇒sin^3 x-sin^2 x=cos^2 x-cos^3 x$\\r\\n\\r\\n$⇒sin^3 x+cos^3 x=sin^2 x+cos^2 x$\\r\\n\\r\\n$⇒sin^3 x+cos^3 x=1 \\\\quad (1)$\\r\\n\\r\\n$sin^3 x≤1$\\r\\n\\r\\n$cos^3 x≤1$\\r\\n\\r\\nمعادله ریشه ندارد\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"3838\":{\"correct_option_id\":18250,\"descriptive_answer\":{\"text\":\"88 - گزینه «3»\\r\\n\\r\\nابتدا به کمک روابط $sin^2 2x = 1 - cos^2 2x$ و $cos^2 x = (1 + cos 2x) / 2$ داریم:\\r\\n\\r\\n$3sin^2 2x - 8cos^2 x + 1 = 0 \\\\Rightarrow 3(1 - cos^2 2x) - 8((1 + cos 2x) / 2) + 1 = 0$\\r\\n\\r\\n$\\\\Rightarrow 3 - 3cos^2 2x - 4 - 4cos 2x + 1 = 0 \\\\Rightarrow 3cos^2 2x + 4cos 2x = 0$\\r\\n\\r\\n$\\\\Rightarrow cos 2x(3cos 2x + 4) = 0 \\\\Rightarrow$\\r\\n\\r\\n{\\r\\n\\r\\n$cos 2x = 0$\\r\\n\\r\\n$cos 2x = -4/3 \\\\times$\\r\\n\\r\\n}\\r\\n\\r\\nتوجه شود که $-1 \\\\le cos 2x \\\\le 1$ است بنابراین $cos 2x = -4/3$ غیرقابل قبول است.\\r\\n\\r\\n\\r\\n\\r\\n$cos 2x = 0 \\\\Rightarrow 2x = k\\\\pi + \\\\pi/2 \\\\Rightarrow x = k\\\\pi/2 + \\\\pi/4$\\r\\n\\r\\n\\r\\n\\r\\n| k | 0 | 1 | 2 | 3 |\\r\\n\\r\\n|---|---|---|---|---|\\r\\n\\r\\n| x | $\\\\pi/4$ | $3\\\\pi/4$ | $5\\\\pi/4$ | $7\\\\pi/4$ |\\r\\n\\r\\n\\r\\n\\r\\nمجموع جواب‌ها: $4\\\\pi$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8504\":{\"correct_option_id\":51488,\"descriptive_answer\":{\"text\":\"گیاهان، فسفر مورد نیاز خود را به‌صورت یون‌های فسفات از خاک به‌دست می‌آورند. گرچه فسفات در خاک فراوان است (نادرستی گزینه ۱)، اغلب برای گیاهان غیرقابل‌دسترس است (درستی گزینه ۲). یکی از دلایل، این است که فسفات به بعضی ترکیبات معدنی خاک به‌طور محکمی متصل می‌شود. برخی (نه همه) گیاهان برای جبران، شبکه گسترده‌تری از ریشه‌ها و یا ریشه‌های دارای تار کشنده بیشتر ایجاد می‌کنند که جذب را افزایش می‌دهد (نادرستی گزینه ۴). بیشتر (نه همه) گیاهان دانه‌دار با قارچ‌ها رابطه همزیستی از نوع قارچ‌ریشه‌ای دارند که مواد معدنی و به‌خصوص فسفات را برای آنها فراهم می‌کند (نادرستی گزینه ۳).\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8506\":{\"correct_option_id\":51479,\"descriptive_answer\":{\"text\":\"کودهای شیمیایی، دارای ترکیبات معدنی هستند و کودهای آلی از بقایای در حال تجزیه جانداران تشکیل شده‌اند که به آهستگی مواد معدنی را آزاد می‌کنند. هم کودهای شیمیایی و هم کودهای آلی به گیاهان، آسیب وارد می‌کنند. در واقع، کودهای آلی چون به نیازهای جانداران، شباهت بیشتری دارند، در اثر مصرف بیش از حد آن‌ها، آسیب کمتری به گیاهان وارد می‌کنند. اما کودهای شیمیایی، آسیب زیادی به گیاهان وارد می‌کنند. پس مقدار آسیب این کودها به گیاهان متفاوت است. اما توجه کنید که این کودها در اثر مصرف بیش از حد، به گیاهان آسیب وارد می‌کنند، نه پس از هر بار مصرف!\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۲ خاک از سه بخش تشکیل شده است: ۱- بخش آلی (هوموس یا گیاخاک) ۲- بخش غیرآلی ۳- ریزجانداران یا میکروارگانیسم‌ها. کود آلی سبب افزایش مقدار اجزای هوموس می‌شود، چون دارای اجزای مشابهی با این بخش خاک است. کود زیستی نیز دارای ریزجانداران است؛ بنابراین در افزایش مقدار بخش ریزجانداران خاک نقش دارد. با توجه به این توضیحات می‌توان به شباهت کود آلی و زیستی از نظر نقش در افزایش مقدار اجزای بخشی از خاک پی‌برد. اما معمولاً کودهای زیستی برخلاف کودهای آلی همراه با کودهای شیمیایی به خاک اضافه می‌شوند و در این مورد با یکدیگر، تفاوت دارند.\\r\\n\\r\\n۳ کودهای شیمیایی و زیستی به دلیل فراهم کردن عناصر مورد نیاز گیاهان، نقش غیرمستقیم در افزایش حاصلخیزی خاک دارند و از این نظر به یکدیگر شباهت دارند اما اگر کودهای شیمیایی برخلاف کودهای زیستی در اثر بارش، شسته و وارد آب شوند؛ موجب تسریع رشد گیاهان آبزی، جلبک‌ها و باکتری‌ها می‌شوند که در این صورت، مانع نفوذ نور و اکسیژن کافی به آب می‌شود و در نهایت موجب مرگ و میر جانوران آبزی خواهد شد.\\r\\n\\r\\n۴ کودهای آلی به نیازهای جانداران، شباهت بیشتری دارند اما این بدین معنا نیست که سایر کودها به نیازهای جانداران شباهت ندارند. در واقع کودهای شیمیایی نیز به نیازهای جانداران مانند گیاهان شباهت دارند اما به مقدار کم. پس از این نظر با یکدیگر شباهت دارند. در مقابل کودهای آلی ترکیبات معدنی را با سرعت کم و کودهای شیمیایی، ترکیبات معدنی را با سرعت زیاد به خاک اضافه می‌کنند. پس از نظر سرعت آزادسازی ترکیبات معدنی با یکدیگر، متفاوت هستند.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":51481,\"is_answered\":true},\"8511\":{\"correct_option_id\":51460,\"descriptive_answer\":{\"text\":\"در حد اطلاعات کتاب درسی جاندارانی مانند سس، گل جالیز، شته و نوعی قارچ می‌توانند اندام مکنده‌ی خود را وارد گیاه نمایند تا از مواد مغذی آن استفاده کنند. هیچ‌یک از این جانداران قدرت فتوسنتز و تبدیل دی‌اکسیدکربن به گلوکز را ندارند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ شته!!\\r\\n\\r\\n۳ شته اندام مکنده خود را تا آوند آبکش ساقه وارد می‌کند تا از ترکیبات شیره‌ی پرورده استفاده نماید. همان‌طور که می‌دانید آوند آبکش در بخش مرکزی ساقه وجود ندارد.\\r\\n\\r\\n۴ گل جالیز اندام مکنده‌ی خود را وارد ریشه‌ی گیاهان جالیزی می‌کند. در نوک ریشه کلاهک وجود دارد که یاخته‌های سطحی آن مرده‌اند و به تدریج می‌ریزند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8516\":{\"correct_option_id\":51440,\"descriptive_answer\":{\"text\":\"خاک ترکیبی از مواد آلی غیر آلی و ریز جانداران (میکروارگانیسم‌ها) است. اسیدهای تولید شده توسط جانداران و نیز ریشه گیاهان می‌توانند هوازدگی شیمیایی ایجاد کنند. هوازدگی سبب تولید بخش غیر آلی خاک می‌شود. می‌دانید که بخش‌های غیر آلی می‌توانند فاقد اتم کربن در ساختار خود باشند. توجه داشته باشید که هر ماده آلی در ساختار خود به طور قطع دارای اتم کربن است.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ و ۴ گیاخاک (هوموس) لایه سطحی خاک است و به طور عمده از بقایای جانداران و به‌ویژه اجزای در حال تجزیه آن‌ها تشکیل شده است. گیاخاک با داشتن بارهای منفی یون‌های مثبت را در سطح خود نگه می‌دارند و در نتیجه مانع از شست‌وشوی این یون‌ها می‌شوند. گیاخاک همچنین باعث اسفنجی شدن حالت خاک می‌شود که برای نفوذ ریشه مناسب است. باکتری‌های آمونیاک‌ساز موجود در خاک با مصرف مواد آلی به تولید یون آمونیوم می‌پردازند.\\r\\n\\r\\n۳ ذرات غیر آلی خاک از تخریب فیزیکی و شیمیایی سنگ‌ها در فرایندی به نام هوازدگی ایجاد می‌شوند. این ذرات از اندازه بسیار کوچک رس تا درشت شن و ماسه را شامل می‌شوند. تغییرات متناوب یخ زدن و ذوب شدن که باعث خرد شدن سنگ‌ها می‌شود نمونه‌ای از اثر هوازدگی فیزیکی است. همانطور که اشاره شد اسیدهای تولید شده توسط جانداران و نیز ریشه گیاهان (نوعی اندام غیرهوایی) هم می‌توانند هوازدگی شیمیایی ایجاد کنند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8520\":{\"correct_option_id\":51426,\"descriptive_answer\":{\"text\":\"کودهای شیمیایی شامل مواد معدنی هستند که به راحتی در اختیار گیاه قرار می‌گیرند؛ بنابراین می‌توانند به سرعت، کمبود مواد مغذی خاک را جبران کنند. مصرف بیش از حد کودهای شیمیایی می‌تواند آسیب‌های زیادی به خاک و محیط زیست وارد و بافت خاک را تخریب کند. از طرفی، با شسته شدن توسط بارش‌ها، این مواد به آب‌ها وارد می‌شوند. حضور این مواد (در آب) باعث رشد سریع باکتری‌ها، جلبک‌ها و گیاهان آبزی می‌شود. افزایش این عوامل مانع نفوذ نور و اکسیژن کافی به آب می‌شود و می‌تواند باعث مرگ‌ومیر جانوران آبزی شود. اما توجه داشته باشید که از معایب کودهای آلی، احتمال آلودگی به عوامل بیماری‌زاست نه کودهای شیمیایی!\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ همانطور که اشاره شد، این کودها به سرعت، کمبود مواد مغذی خاک را جبران می‌کنند.\\r\\n\\r\\n۲ کودهای زیستی شامل باکتری‌هایی هستند که برای خاک مفید و با فعالیت و تکثیر خود، مواد معدنی خاک را افزایش می‌دهند. استفاده از این کودها بسیار ساده‌تر و کم هزینه‌تر است. این کودها معمولاً به همراه کودهای شیمیایی به خاک افزوده می‌شوند و معایب دو نوع کود دیگر را ندارند.\\r\\n\\r\\n۳ کودهای شیمیایی سبب رشد باکتری‌ها می‌شوند که رشد باکتری‌ها با افزایش ابعاد آن‌ها به‌صورت برگشت‌ناپذیر انجام می‌شود.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8529\":{\"correct_option_id\":51390,\"descriptive_answer\":{\"text\":\"کودهای آلی، به نیازهای جانداران شباهت بیشتری دارند. کودهای شیمیایی می‌توانند به سرعت، کمبود مواد مغذی خاک را جبران کنند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ مصرف بیش از حد کودهای شیمیایی می‌تواند آسیب‌های زیادی به خاک و محیط زیست وارد و بافت خاک را تخریب کند. از طرفی، با شسته شدن توسط بارش‌ها، این مواد به آب‌ها وارد می‌شوند. حضور این مواد باعث رشد سریع باکتری‌ها، جلبک‌ها و گیاهان آبزی می‌شود.\\r\\n\\r\\n۲ واضح است که کودهای آلی، حاوی مواد آلی هستند! کودهای زیستی نیز حاوی مواد آلی هستند؛ چرا که شامل باکتری‌هایی که جاندار زنده هستند، با فعالیت خود، مواد آلی می‌سازند. کودهای زیستی معمولاً به همراه کودهای شیمیایی به خاک افزوده می‌شوند و معایب دو نوع کود دیگر را ندارند.\\r\\n\\r\\n۳ کودهای زیستی شامل باکتری‌هایی هستند که برای خاک مفید و با فعالیت و تکثیر خود، مواد معدنی خاک را افزایش می‌دهند. کودهای آلی نیز ممکن است حاوی جانداران باشند، چرا که شامل بقایای در حال تجزیه جانداران‌اند و ممکن است این بقایا توسط باکتری‌ها و دیگر جانداران تجزیه شوند. از معایب کودهای آلی، احتمال آلودگی به عوامل بیماری‌زا است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8534\":{\"correct_option_id\":51367,\"descriptive_answer\":{\"text\":\"دقت داشته باشید که نخود، سویا و یونجه گیاهانی هستند که جزئی از تیره پروانه‌واران هستند. در این گیاهان، گل‌ها (نه برگ‌ها!) ظاهری شبیه پروانه دارند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۲ در ریشه گیاهان تیره پروانه‌واران، برجستگی‌هایی به نام گرهک دیده می‌شود؛ اگر به شکل دقت کنید این برجستگی‌ها در ریشه جانبی مشاهده می‌شوند.\\r\\n\\r\\n۳ هنگامی که گیاه نخود، می‌میرد، یا بخش‌های هوایی آن برداشته می‌شود گرهک‌های آن در خاک می‌ماند و گیاخاک غنی از نیتروژن ایجاد می‌کند.\\r\\n\\r\\n۴ در گرهک نخود، باکتری‌های ریزوبیوم قرار گرفته‌اند؛ این باکتری‌ها، برای گیاهان نیتروژن (به فرم آمونیوم) فراهم می‌کنند و در عوض گیاه مواد آلی مورد نیاز باکتری را تأمین می‌کند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8548\":{\"correct_option_id\":51307,\"descriptive_answer\":{\"text\":\"گیاه حشره‌خوار توبره‌واش توانایی فتوسنتز دارد ولی گیاه انگل سس فاقد این توانایی است. گیاه توبره‌واش و گونرا هر دو در مناطق کم‌نیتروژن زندگی می‌کنند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\nگزینه «۲»: محل زندگی گیاه توبره‌واش و آزولا تالاب‌های شمال کشور است.\\r\\n\\r\\nگزینه «۳»: گیاه توبره‌واش با سیانوباکتری‌ها همزیستی ندارد.\\r\\n\\r\\nگزینه «۴»: نه گیاه توبره‌واش و نه گیاه آزولا توانایی تولید اندام مکنده ندارند.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8553\":{\"correct_option_id\":51288,\"descriptive_answer\":{\"text\":\"در بخش پهنک برگ گیاهان گوشت‌خوار امکان مشاهدهٔ ساختارهای مو مانند وجود دارد. (خوب به شکل دقت کنین! اگر نمیتونین اوووووب زوم کنین شکل با کیفیت ترش هم براتون گذاشتیم!حتی از نظر علمی تعداد این کرک‌ها(موها) در پهنک مهمه! که هر تیکه از برگ دارای ۳ تا ساختار مو مانند هستش چرا مهمه؟ آگه حشره به دوتا از این موها برخورد کنه تله بسته میشه.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ با توجه به شکل مقابل، در بخش پهنک برگ‌های گوشت‌خوار، رنگ برگ تفاوت دارد و میزان سبزینه کمتر است.\\r\\n\\r\\n۳ در این برگ‌ها، گوارش حشرات صورت می‌گیرد در نتیجه گروهی از یاخته‌ها وجود دارند که آنزیم‌های گوارشی را تولید و ترشح می‌کنند و گروهی دیگر، مواد گوارش یافته را جذب می‌کنند.\\r\\n\\r\\n۴ در میان مواد جذب شده علاوه بر مواد معدنی، مواد آلی نیز وجود دارند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8557\":{\"correct_option_id\":51274,\"descriptive_answer\":{\"text\":\"همه موارد اشتباه هستند.\\r\\n\\r\\nالف: $۹۰$ درصد گیاهان دانه‌دار با قارچ‌ها به صورت قارچ ریشه‌ای همزیستی دارند.\\r\\n\\r\\nب: با توجه به شکل صفحه $۱۰۲$ رشته‌های قارچ به آوند نفوذ نمی‌کنند.\\r\\n\\r\\nج: به علت گرفتن مواد معدنی قارچ توسط گیاه، گیاه رشد بیشتری می‌کند.\\r\\n\\r\\nد: قارچ ریشه‌ای مواد معدنی را به گیاه داده و از گیاه مواد آلی می‌گیرد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"893\":6589,\"894\":6583,\"896\":6585,\"2245\":62166,\"2612\":74050,\"8506\":51481},\"totalTimeSpent\":127,\"questionTimes\":{\"403\":3009,\"476\":2000,\"604\":997,\"893\":11052,\"894\":2000,\"896\":8975,\"1958\":4996,\"1962\":1004,\"2245\":4008,\"2295\":993,\"2612\":43999,\"8506\":12997,\"8516\":1998,\"8534\":969},\"selectionLog\":[{\"questionId\":893,\"optionId\":6589,\"timeSpentMs\":3053,\"timestamp\":1787643185717},{\"questionId\":893,\"optionId\":6591,\"timeSpentMs\":11052,\"timestamp\":1787643199681},{\"questionId\":893,\"optionId\":6589,\"timeSpentMs\":11052,\"timestamp\":1787643201255},{\"questionId\":896,\"optionId\":6585,\"timeSpentMs\":7976,\"timestamp\":1787643205067},{\"questionId\":894,\"optionId\":6583,\"timeSpentMs\":2000,\"timestamp\":1787643212739},{\"questionId\":2612,\"optionId\":74050,\"timeSpentMs\":43999,\"timestamp\":1787643258722},{\"questionId\":2245,\"optionId\":62166,\"timeSpentMs\":1006,\"timestamp\":1787643262194},{\"questionId\":8506,\"optionId\":51481,\"timeSpentMs\":997,\"timestamp\":1787643271028}],\"lobbyCode\":\"M2l3mgk2yr\"}}', '2026-08-25 07:34:55');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(146, 69, 104, 3.57, 1, 3, 24, 0, 70, '{\"total_questions\":28,\"correct_count\":1,\"incorrect_count\":3,\"unanswered_count\":24,\"accuracy_rate\":3.57,\"score\":0,\"mabhas_stats\":{\"دو دوازدهم\":{\"correct\":1,\"incorrect\":1,\"unanswered\":2,\"total\":4},\"فصل هفت دهم\":{\"correct\":0,\"incorrect\":2,\"unanswered\":8,\"total\":10},\"فصل پنج دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":6,\"total\":6},\"مثلثات دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":8,\"total\":8}}}', '{\"evaluation\":{\"403\":{\"correct_option_id\":5713,\"descriptive_answer\":{\"text\":\"همه موارد درست هستند. الف) تنظیم آب تحت عوامل مختلفی قرار دارد. یکی از سازوکارها به غلظت مواد حل شده در خوناب ارتباط دارد. اگر غلظت مواد از حد مشخصی فراتر رود، ترشح هورمون ضد ادراری تحریک می&zwnj;شود. این هورمون با اثر بر کلیه&zwnj;ها، بازجذب آب را افزایش می&zwnj;دهد و مقدار دفع آب از طریق ادرار کاهش می&zwnj;یابد. ب) یکی از ماده&zwnj;های دفعی نیتروژن&zwnj;دار در ادرار اوریک اسید است. اوریک&zwnj;اسید انحلال&zwnj;پذیری زیادی در آب ندارد (نه این که اصلاً در آب حل نشود)؛ بنابراین تمایل آن به رسوب کردن و تشکیل بلور زیاد است. رسوب بلورهای اوریک&zwnj;اسید در کلیه&zwnj;ها باعث ایجاد سنگ کلیه می&zwnj;شود. دقت کنید اندکی از اوریک&zwnj;اسید در آب حل شده و بلور کمتری تشکیل می&zwnj;شود. در نتیجه، آب بیشتر در تشکیل سنگ کلیه کمتر، نقش دارد. ج) هورمون ضد&zwnj;ادراری باعث بازجذب بیشتر آب به خون می&zwnj;شود (جابجایی آب بیشتر از نفرون به مویرگ). بنابراین خونی که در انتهای شبکه مویرگی دور لوله ای (رگی که در مجاورت بخش صعودی لوله هنله است) جریان دارد، مقدار آب بیشتر و فشار اسمزی کمتری دارد. د) در انتهای میزنای دریچه ای قرار دارد که حاصل چین&zwnj;خوردگی مخاط مثانه بر روی دهانه میزنای است (مانع بازگشت ادرار از مثانه به میزنای می&zwnj;شود). در هنگام دفع، آب پس از عبور از این دریچه به مثانه وارد می&zwnj;شود. چنانچه حجم ادرار جمع شده در مثانه از حد مشخصی فراتر رود، کشیدگی دیواره مثانه باعث فعال شدن سازوکار تخلیه ادرار می&zwnj;شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"476\":{\"correct_option_id\":5441,\"descriptive_answer\":{\"text\":\"در سرخرگ&zwnj;های کوچک&zwnj;تر (مانند سرخرگ کلیه)، نسبت به سرخرگ&zwnj;های بزرگ (مانند سرخرگ آئورت)، میزان رشته&zwnj;های کشسان، کمتر و میزان ماهیچه&zwnj;های صاف، بیشتر است. 2) اوره جزء مواد دفعی است و مقداری از اوره که توسط سرخرگ وارد کلیه می&zwnj;شود، از خون خارج شده و وارد نفرون&zwnj;ها می&zwnj;شود. بنابراین، مقدار اوره و سایر مواد دفعی در سرخرگ کلیه بیشتر از سیاهرگ کلیه است. 3) فشار تراوشی ناشی از فشار خون است و با توجه به اینکه به طور کلی، فشار خون در سرخرگ&zwnj;ها بیشتر از سیاهرگ&zwnj;ها است، فشار تراوشی نیز در سرخرگ آئورت بیشتر از بزرگ سیاهرگ زیرین است. اما فشار اسمزی ناشی از پروتئین&zwnj;های خون است و با توجه به اینکه مقدار پروتئین&zwnj;های خون ثابت است، فشار اسمزی نیز در رگ&zwnj;های نشان داده شده برابر است. 4) دریچه&zwnj;های لانه کبوتری، دریچه&zwnj;هایی هستند که در سیاهرگ&zwnj;ها وجود دارند و باعث ایجاد جریان یک&zwnj;طرفه خون در سیاهرگ می&zwnj;شوند. این دریچه&zwnj;ها در سیاهرگ&zwnj;های دست و پا وجود دارند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"480\":{\"correct_option_id\":5440,\"descriptive_answer\":{\"text\":\"پس از ورود ادرار به مثانه، دریچه&zwnj;ای که حاصل چین&zwnj;خوردگی مخاط مثانه روی دهانه میزنای است، مانع بازگشت ادرار به میزنای می&zwnj;شود. چنانچه حجم ادرار جمع&zwnj;شده در مثانه از حد مشخصی فراتر رود، کشیدگی دیواره مثانه باعث فعال شدن سازوکار تخلیه ادرار می&zwnj;شود (نادرستی گزینه ۱ و ۲؛ این دو گزینه قبل از فعال شدن سازوکار تخلیه مثانه رخ می&zwnj;دهند). در محل اتصال مثانه به میزراه، بنداره داخلی میزراه (دارای ماهیچه صاف) قرار دارد که هنگام ورود ادرار باز می&zwnj;شود. بعد از این بنداره، بنداره خارجی میزراه (دارای ماهیچه مخطط) است. برای تخلیه مثانه، لازم است که انقباض هر دو بنداره کم شود (نه اینکه پیام انقباض را دریافت کنند و منقبض شوند) تا بنداره باز شود و ادرار بتواند از بدن خارج شود (نادرستی گزینه ۳). در نوزادان و کودکانی که هنوز ارتباط مغز و نخاع آنان به طور کامل شکل نگرفته است، تخلیه مثانه به صورت غیرارادی انجام می&zwnj;شود. در نتیجه، در یک نوزاد یک ماهه، باز شدن بنداره خارجی میزراه در پی کاهش انقباض ماهیچه آن نیز به صورت غیرارادی انجام می&zwnj;شود (درستی گزینه ۴).\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"604\":{\"correct_option_id\":6021,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در لوله های مالپیگی متصل به رودۀ حشرات و غدد راست روده ای ماهیان غضروفی ساکن آب شور، تعامل مستقیمی میان سامانه تنظیم اسمزی و بخشی از رودۀ جانور وجود دارد. حشرات دارای اسکلت بیرونی و ماهیان دارای اسکلت درونی هستند؛ در هر دو نوع اسکلت بیرونی و درونی، این اسکلت از اندام های درونی پیکر جانور محافظت می کند. بررسی سایر گزینه ها: 2) باریک ترین رگ های خونی مویرگ ها هستند. توجه داشته باشید که حشرات دارای سامانه گردشی باز هستند. جانورانی که سامانه گردشی باز دارند، مویرگ ندارند و همولنف مستقیما به فضای بین یاخته های بدن آن ها وارد می شود و در مجاورت آن ها جریان می یابد! اما در ماهی ها، شبکه مویرگی وجود دارد. 3) قلب در سامانه باز، مایعی به نام همولنف را به حفره های بدن پمپ می کند که همولنف نقش های خون، لنف و آب میان بافتی را بر عهده دارد! در ماهی ها پیک های شیمیایی درون خون دیده می شوند. 4) توجه کنید که نه حشرات و نه ماهیان غضروفی، اسکلت استخوانی ندارند و در نتیجه یاخته استخوانی هم ندارند!\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"606\":{\"correct_option_id\":6019,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; ماهی های آب شیرین در محیطی زندگی می کنند که فشار اسمزی کم تری نسبت به مایعات بدن جانور دارد و آب به راحتی از طریق اسمز وارد بدن جانور می شود و به همین دلیل معمولا آب زیادی نمی نوشند؛ اما در ماهی های آب شور، به دلیل بیشتر بودن فشار اسمزی محیط نسبت به مایعات بدن، آب تمایل به خروج از بدن دارد. بررسی سایر گزینه ها: 1) در هر دو ماهی، دفع مواد زائد نیتروژن دار از طریق کلیه صورت می گیرد. در ماهیان آب شور، برخی یون ها (نه مواد دفعی نیتروژن دار!) از طریق یاخته های آبشش دفع می شوند. 2) ماهیان آب شیرین، برخلاف ماهیان آب شور ادرار رقیق دفع می کنند. در افراد مبتلا به دیابت بی مزه نیز به دلیل کاهش بازجذب آب، فرد ادرار رقیق دفع می کند. 4) در ماهیان آب شیرین، فشار اسمزی مایعات بدن از محیط بیشتر است و این ماهی ها معمولا آب زیادی نمی نوشند. برعکس در ماهیان آب شور، فشار اسمزی مایعات بدن کم تر از محیط است، در نتیجه این ماهیان مقدار زیادی آب می نوشند؛ بنابراین در هر دو گروه میزان نوشیدن آب با فشار اسمزی مایعات بدن رابطه عکس دارد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"607\":{\"correct_option_id\":6015,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; برخی از خزندگان و پرندگان دریایی و بیابانی که آب دریا یا غذای نمک دار مصرف می کنند، می توانند نمک اضافه را از طریق غدد نمکی نزدیک چشم یا زبان، به صورت قطره های غلیظ دفع کنند. دقت کنید که کلیه ها در همۀ خزندگان و پرندگان توانمندی زیادی در بازجذب آب دارند. بررسی سایر گزینه ها: 1) این جانوران، دارای گردش خون مضاعف هستند، پس در قلب چند حفره ای (دو دهلیز و دو بطن دارند) آن ها علاوه بر خون تیره، خون روشن نیز وجود دارد. تغذیه یاخته های ماهیچه قلب همواره با خون روشن و غنی از اکسیژن صورت می گیرد. 2) جدایی کامل بطن ها در پرندگان و پستانداران و برخی خزندگان مثل کروکودیل ها رخ می دهد. این حالت، حفظ فشار در سامانه گردشی مضاعف را آسان می کند؛ در نتیجه کارایی خون رسانی به یاخته ها نسبت به سایر جانداران بیشتر است؛ بنابراین این گزینه ویژگی پرندگان ساکن مناطق بیابانی نمی باشد. 4) مثانه دوزیستان محل ذخیره آب و یون هاست و به هنگام خشک شدن محیط، دفع ادرار کم و مثانه برای ذخیره بیشتر آب بزرگ تر می شود و سپس بازجذب آب از مثانه به خون افزایش پیدا می کند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"893\":{\"correct_option_id\":6591,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; در پروکاریوت ها، منظور از توالی ویژه مؤثر در رونویسی، می تواند توالی راه انداز، اپراتور، جایگاه اتصال فعال کننده و یا توالی پایان رونویسی باشد. در یوکاریوت ها، توالی افزاینده هم، نوعی توالی ویژه است که در رونویسی نقش دارد. از بین مراحل طویل شدن و پایان، فقط در مرحله پایان، پس از رونویسی شدن توالی پایان رونویسی (جزئی از ژن)، آنزیم رنابسپاراز از مولکول دنا (DNA) جدا می شود. دقت کنید که سایر توالی های نام برده شده جزئی از توالی ژن نمی باشند. بررسی سایر گزینه ها: 1) شکسته شدن پیوندهای هیدروژنی میان دو رشته دنا (و در نتیجه پیوندهای بین نوکلئوتیدهایی با قندهای یکسان) را هم در مرحله طویل شدن و هم در مرحله پایان ترجمه می توان مشاهده نمود؛ نه در برخی از آن ها! 2) این گزینه در خصوص مرحله پایان رونویسی است که بعد از رونویسی شدن توالی پایان رونویسی، رنابسپار از از دنا جدا می شود. اما توجه داشته باشید که در پروکاریوت ها، دنای &laquo;هسته ای!&raquo; نداریم و این گزینه از بیخ و بن نادرست می باشد. 4) در مرحله آغاز رونویسی، راه انداز موجب می شود رنا بسپار از اولین نوکلئوتید مناسب را به طور دقیق پیدا و رونویسی را از آنجا آغاز کند. در این حالت بخش کوچکی از مولکول دنا باز و زنجیره کوتاهی از رنا ساخته می شود. با این اوصاف، این گزینه در خصوص هیچ یک از مراحل طویل شدن و پایان صادق نیست.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6591,\"is_answered\":true},\"894\":{\"correct_option_id\":6581,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; موارد &laquo;الف&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) پس از خروج رنای ناقل فاقد آمینواسید از جایگاهE ، براساس وجود یا عدم وجود کدون پایان در جایگاه ،A دو اتفاق می تواند رخ دهد. یا عامل آزاد کننده به جایگاه A وارد می شود (اگر کدون پایان در جایگاه A (باشد که در نهایت رنای ناقل و زنجیره پلی پپتیدی از جایگاه P ریبوزوم خارج می شوند؛ و اگر کدون رمزکننده یک آمینواسید در جایگاه A باشد، جایگاه A آماده پذیرش رنای ناقل بعدی می شود که پس از ورود و استقرار رنای ناقل مکمل به این جایگاه پیوند اشتراکی در جایگاه P ریبوزوم شکسته می شود تا پیوند پپتیدی بعدی تشکیل شود. ب) این مورد همواره رخ می دهد و مخصوص شرایط خاصی نیست! دقت کنید که تشکیل پیوند پپتیدی در جایگاه A رناتن اتفاق می افتد و کمی پس از تشکیل آن، همواره جابه جایی رناتن بر روی رنای پیک رخ میدهد که در نتیجه آن، رنای ناقل متصل به رشته پپتیدی به جایگاه P وارد میشود و رنای ناقل فاقد آمینواسید پس از ورود به جایگاه E رناتن، از آن خارج می گردد. ج) علاوه بر مرحله پایان ترجمه که پیوند بین رشته آمینواسیدی و tRNA شکسته می شود، طی طویل شدن هم این اتفاق می افتد، اما در پایان برخلاف طویل شدن tRNA ،فاقد آمینواسید به جایگاه E منتقل نمیشود بنابراین این جمله فقط درباره مرحله طویل شدن ترجمه صدق می کند یعنی در برخی شرایط رخ می دهد. د) کمی پیش از تشکیل پیوند پپتیدی در جایگاه ،A ریبوزوم پیوند اشتراکی بین آمینواسید و tRNA در جایگاه میانی ریبوزوم (جایگاه(P شکسته می شود. در واقع اگر قرار باشد پیوند پپتیدی تشکیل شود، همواره (نه در برخی شرایط!) باید رشته پپتیدی یا آمینواسید متصل به رنای ناقل در جایگاه ،P از این رنای ناقل جدا شود و سپس به جایگاه A منتقل گردد تا در نهایت به آمینواسید موجود در این جایگاه متصل شود. بنابراین، پیش از تشکیل هر پیوند پپتیدی حین ترجمه، باید پیوند اشتراکی بین رنای ناقل و بخش پپتیدی (یا آمینواسید) متصل به آن شکسته شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"896\":{\"correct_option_id\":6585,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در یک مولکول رنای ناقل، هر نوکلئوتیدی که در یک انتهای رشته پلی نوکلئوتیدی قرار دارد با سایر نوکلئوتیدهای این رنا، فقط یک پیوند فسفودی استر تشکیل می دهد. براساس شکل کتاب درسی دیده می شود که در رنای ناقل، یکی از این دو نوکلئوتید در جایگاه اتصال به آمینواسید قرار دارد و با نوکلئوتید دیگری در ساختار رنای ناقل، پیوند هیدروژنی تشکیل نمی دهد. طبق شکل کتاب درسی، نوکلئوتید دیگر، در انتهای دیگر رشته پلینوکلئوتیدی پیوند هیدروژنی تشکیل می دهد. بررسی سایر گزینه ها: 2) در ساختار رنای ناقل ،یک نوکلئوتید در یک توالی سه نوکلئوتیدی در یک انتهای tRNA ، جایگاه اتصال به آمینواسید را تشکیل می دهد. مطابق شکل کتاب درسی، این نوکلئوتید جایگاه اتصال به آمینواسید در دورترین نقطه (بیشترین تعداد نوکلئوتید بین آن ها) نسبت به توالی پادرمزه (آنتی کدون) قرار دارد. براساس توالی پادرمزه، آمینواسید خاصی به رنای ناقل متصل می شود. 3) دو حلقه از رنای ناقل که فاقد توالی پادر مزه هستند، در ساختار سه بعدی مولکول رنای ناقل نسبت به تاخوردگی اولیه به یکدیگر نزدیک تر هستند. 4) ساختار نهایی میوگلوبین، ساختار سوم آن است. در میوگلوبین، برای اولین بار، تاخوردگی ها در ساختار دوم رخ می دهد که باعث ایجاد ساختار مارپیچ می شود و تاخوردگی های بیشتر نیز برای تشکیل ساختار سوم ایجاد می شود تا ساختار نهایی پروتئین شکل بگیرد. رنای ناقل نیز پس از تاخوردگی اولیه، تاخوردگی های مجددی پیدا میکند که ساختار سه بعدی آن را پدید می آورد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6588,\"is_answered\":true},\"897\":{\"correct_option_id\":6572,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; در مرحله آغاز و پایان ترجمه، رنای ناقل در جایگاه A و E ریبوزوم دیده نمی شود. در مرحله آغاز، زیرواحد بزرگ ریبوزوم به زیرواحد کوچک آن متصل می شود و در مرحله پایان ترجمه، زیرواحد بزرگ ریبوزوم از زیرواحد کوچک آن جدا خواهد شد؛ پس تمایل آن ها برای اتصال به هم تغییر می کند. بررسی سایر گزینه ها: 1) دقت داشته باشید این مولکول پلی پپتیدی می تواند دو نوع مولکول مختلف باشد؛ یکی رشته پلی پپتیدی در حال ساخت که به رنای ناقل موجود در جایگاه A اتصال دارد و طی مرحله طویل شدن و با حرکت رناتن وارد جایگاه P می شود. دیگری نیز ممکن است پروتئین آزادکننده باشد که نوعی مولکول پلی پپتیدی است و در مرحلۀ پایان در جایگاه A قرار می گیرد. با قرار گیری پروتئین آزاد کننده در جایگاه ،A دیگر حرکتی توسط رناتن به سمت جلو صورت نمی گیرد. 2) طبق شکل و متن کتاب درسی، در هیچ یک از مراحل ترجمه، امکان این که به صورت هم زمان جایگاه های A و E رناتن توسط رناهای ناقل اشغال شوند، وجود ندارد! زیرا همواره قبل از ورود tRNA به جایگاه ،A رنای ناقل فاقد آمینواسید از جایگاه E خارج شده است. فقط در مرحله طویل شدن، رنای فاقد آمینواسید در جایگاه E دیده می شود. 3) در مرحله طویل شدن، حداکثر دو رنای ناقل به صورت هم زمان در جایگاه های رناتن قابل مشاهده هستند و در مرحله آغاز و پایان فقط یک رنای ناقل در رناتن دیده می شود. طبق شکل کتاب درسی، در فرایند ترجمه، هر آمینواسید جدید به انتهای کربوکسیل (نه آمین) رشته پپتیدی در حال ساخت متصل می گردد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1958\":{\"correct_option_id\":44560,\"descriptive_answer\":{\"text\":\"19- پاسخ: گزینه 1 ▲ مشخصات سؤال: متوسط * صفحه 43 ریاضی 3\\r\\n\\r\\nنکته: $Sin 2α = 2Sin α Cos α$\\r\\n\\r\\nنکته: $Cos 2α = 2Cos^2 α - 1$\\r\\n\\r\\nابتدا عبارت داده شده را ساده می کنیم:\\r\\n\\r\\n$Sin 2α / Sin α = 0/5 \\\\Rightarrow 2Sin α Cos α / Sin α = 1/2 \\\\Rightarrow Cos α = 1/4$\\r\\n\\r\\nبنابراین مقدار خواسته شده برابر است با:\\r\\n\\r\\n$Cos 2α / Cos α = (2Cos^2 α - 1) / Cos α = (2(1/4)^2 - 1) / (1/4) = (2/16 - 1) / (1/4) = (-7/8) / (1/4) = -7/2 = -3/5$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1962\":{\"correct_option_id\":44621,\"descriptive_answer\":{\"text\":\"23- پاسخ: گزینه 2 ▲ مشخصات سؤال: دشوار * صفحه 48 ریاضی 3\\r\\n\\r\\nنکته: جواب های کلی معادله $Sin x = Sin \\\\alpha$ به صورت $x = 2k\\\\pi + \\\\alpha$ یا $x = 2k\\\\pi + \\\\pi - \\\\alpha$ می باشند که $k \\\\in \\\\mathbb{Z}$.\\r\\n\\r\\nنکته: $Sin(\\\\frac{\\\\pi}{2} - \\\\alpha) = Cos \\\\alpha$\\r\\n\\r\\nابتدا نسبت های مثلثاتی دو طرف را یکسان می کنیم. مثلاً می توانیم به جای $Cos 3x$ عبارت $Sin(\\\\frac{\\\\pi}{2} - 3x)$ را جایگزین کنیم.\\r\\n\\r\\n$Cos 3x = Sin x \\\\Rightarrow Sin(\\\\frac{\\\\pi}{2} - 3x) = Sin x \\\\Rightarrow \\\\begin{cases} \\\\frac{\\\\pi}{2} - 3x = 2k\\\\pi + x \\\\\\\\ \\\\frac{\\\\pi}{2} - 3x = 2k\\\\pi + \\\\pi - x \\\\end{cases}$\\r\\n\\r\\n$\\\\Rightarrow \\\\begin{cases} 4x = -2k\\\\pi + \\\\frac{\\\\pi}{2} \\\\\\\\ 2x = -2k\\\\pi - \\\\frac{\\\\pi}{2} \\\\end{cases} \\\\Rightarrow \\\\begin{cases} x = -\\\\frac{k\\\\pi}{2} + \\\\frac{\\\\pi}{8} \\\\\\\\ x = -k\\\\pi - \\\\frac{\\\\pi}{4} \\\\end{cases}$\\r\\n\\r\\nجواب های $x = -k\\\\pi - \\\\frac{\\\\pi}{4}$ از مجموعه جواب $\\\\{\\\\frac{3\\\\pi}{4}\\\\}$ و جواب $x = -\\\\frac{k\\\\pi}{2} + \\\\frac{\\\\pi}{8}$ از مجموعه جواب $\\\\{\\\\frac{\\\\pi}{8} , \\\\frac{5\\\\pi}{8}\\\\}$ در بازه $[0 , \\\\pi]$ قرار دارد.\\r\\n\\r\\nمجموع این جواب ها برابر است با:\\r\\n\\r\\n$\\\\frac{\\\\pi}{8} + \\\\frac{5\\\\pi}{8} + \\\\frac{3\\\\pi}{4} = \\\\frac{6\\\\pi + 6\\\\pi}{8} = \\\\frac{12\\\\pi}{8} = \\\\frac{3\\\\pi}{2}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2245\":{\"correct_option_id\":62166,\"descriptive_answer\":{\"text\":\"21. گزینه 3 درست است. \\r\\n\\r\\nبا جایگذاری $\\\\cos 2x=2\\\\cos^{2}x-1$ خواهیم داشت:\\r\\n\\r\\n$(2\\\\cos^{2}x-1)-\\\\cosx+1=0$\\r\\n\\r\\n$2\\\\cos^{2}x-\\\\cosx=0 \\\\rightarrow \\\\cosx(2\\\\cosx-1)=0$\\r\\n\\r\\n$\\\\cosx=0 \\\\rightarrow x=k\\\\pi+\\\\frac{\\\\pi}{2},k \\\\in z$\\r\\n\\r\\n$\\\\cosx=\\\\frac{1}{2} \\\\rightarrow x=2k\\\\pi \\\\pm \\\\frac{\\\\pi}{3} , k \\\\in z$\\r\\n\\r\\nجوابهای بین 0 و $2\\\\pi$ عبارتند از:\\r\\n\\r\\n$x=\\\\frac{\\\\pi}{2},\\\\frac{3\\\\pi}{2}$\\r\\n\\r\\n$x=\\\\frac{\\\\pi}{3},x=\\\\frac{5\\\\pi}{3}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2295\":{\"correct_option_id\":62365,\"descriptive_answer\":{\"text\":\"۷1. گزینه 2 درست است.\\r\\n\\r\\nنقطه A روی منحنی$f(x)=2\\\\sin^2x$  و نقطه B روی منحنی$g(x)=\\\\cos2x$  است، پس وقتی طول پاره‌خط AB برابر دو واحد باشد. یعنی:\\r\\n\\r\\n$ y_A – y_B = 2 \\\\Rightarrow 2\\\\sin^2 x − \\\\cos2x = 2$\\r\\n\\r\\nبرای حل این معادله مثلثاتی از رابطه $ \\\\cos2x = 1 –\\\\sin^2 x $استفاده کرده و داریم:\\r\\n\\r\\n$2\\\\sin^2 x − (1 – 2\\\\sin^2x) = 2 \\\\rightarrow 4\\\\sin^2 x = 3 \\\\Rightarrow \\\\sin^2 x =\\\\frac{3}{4} \\\\Rightarrow \\\\sin x = \\\\pm\\\\frac{\\\\sqrt{3}}{2}$\\r\\n\\r\\nبا توجه به اینکه مطابق شکل طول نقاط  AوB در بازۀ $(\\\\frac{\\\\pi}{2},\\\\pi)$ قرار دارد، $x=\\\\pi-\\\\frac{\\\\pi}{3}=\\\\frac{2\\\\pi}{3}$ قابل قبول است. پس:\\r\\n\\r\\n$xA = xB = \\\\frac{2\\\\pi}{3}$\\r\\n\\r\\n$y_A =2\\\\sin^2 (\\\\frac{2\\\\pi}{3}) = 2(\\\\frac{\\\\sqrt{3}}{2})^2=\\\\frac{3}{2}$\\r\\n\\r\\nدرنتیجه:\\r\\n\\r\\n$\\\\frac{x_B}{y_A} = \\\\frac{\\\\frac{2\\\\pi}{3}}{\\\\frac{3}{2}}=\\\\frac{4\\\\pi}{9}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2612\":{\"correct_option_id\":74051,\"descriptive_answer\":{\"text\":\"می‌دانیم:\\r\\n\\r\\n$6π/14 = π/2 − π/14$و $3π/7 = 6π/14$\\r\\n\\r\\n$sin(3π/7) cos(π/14) − sin(π/6)$\\r\\n\\r\\n$= sin(π/2 − π/14) cos(π/14) − 1/2$\\r\\n\\r\\n$= cos(π/14) × cos(π/14) − 1/2$\\r\\n\\r\\n$= cos^2(π/14) − 1/2$\\r\\n\\r\\n$=1/2 (2cos^2(π/14) − 1) $\\r\\n\\r\\n$= 1/2cos(π/7) $\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2619\":{\"correct_option_id\":74083,\"descriptive_answer\":{\"text\":\"می‌دانیم:\\r\\n\\r\\n$α + β = π/2 ⇒ sin α = cos β$\\r\\n\\r\\n$sin 37° = 3/5 ⇒ cos 2α = 1 − 2sin^2 α$\\r\\n\\r\\n$cos 74° = 1 − 2(3/5)^2 = 1 − 2×9/25 = 7/25$\\r\\n\\r\\n$cos 74° = sin 16° ⇒ sin 16° = 7/25=0.28$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"2639\":{\"correct_option_id\":74175,\"descriptive_answer\":{\"text\":\"$sin x≠1 \\\\quad (1)$\\r\\n\\r\\n$cos x≠1$\\r\\n\\r\\n$sin^2 x(sin x-1)=cos^2 x(1-cos x)\\r\\n\\r\\n⇒sin^3 x-sin^2 x=cos^2 x-cos^3 x$\\r\\n\\r\\n$⇒sin^3 x+cos^3 x=sin^2 x+cos^2 x$\\r\\n\\r\\n$⇒sin^3 x+cos^3 x=1 \\\\quad (1)$\\r\\n\\r\\n$sin^3 x≤1$\\r\\n\\r\\n$cos^3 x≤1$\\r\\n\\r\\nمعادله ریشه ندارد\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"3838\":{\"correct_option_id\":18250,\"descriptive_answer\":{\"text\":\"88 - گزینه «3»\\r\\n\\r\\nابتدا به کمک روابط $sin^2 2x = 1 - cos^2 2x$ و $cos^2 x = (1 + cos 2x) / 2$ داریم:\\r\\n\\r\\n$3sin^2 2x - 8cos^2 x + 1 = 0 \\\\Rightarrow 3(1 - cos^2 2x) - 8((1 + cos 2x) / 2) + 1 = 0$\\r\\n\\r\\n$\\\\Rightarrow 3 - 3cos^2 2x - 4 - 4cos 2x + 1 = 0 \\\\Rightarrow 3cos^2 2x + 4cos 2x = 0$\\r\\n\\r\\n$\\\\Rightarrow cos 2x(3cos 2x + 4) = 0 \\\\Rightarrow$\\r\\n\\r\\n{\\r\\n\\r\\n$cos 2x = 0$\\r\\n\\r\\n$cos 2x = -4/3 \\\\times$\\r\\n\\r\\n}\\r\\n\\r\\nتوجه شود که $-1 \\\\le cos 2x \\\\le 1$ است بنابراین $cos 2x = -4/3$ غیرقابل قبول است.\\r\\n\\r\\n\\r\\n\\r\\n$cos 2x = 0 \\\\Rightarrow 2x = k\\\\pi + \\\\pi/2 \\\\Rightarrow x = k\\\\pi/2 + \\\\pi/4$\\r\\n\\r\\n\\r\\n\\r\\n| k | 0 | 1 | 2 | 3 |\\r\\n\\r\\n|---|---|---|---|---|\\r\\n\\r\\n| x | $\\\\pi/4$ | $3\\\\pi/4$ | $5\\\\pi/4$ | $7\\\\pi/4$ |\\r\\n\\r\\n\\r\\n\\r\\nمجموع جواب‌ها: $4\\\\pi$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"8504\":{\"correct_option_id\":51488,\"descriptive_answer\":{\"text\":\"گیاهان، فسفر مورد نیاز خود را به‌صورت یون‌های فسفات از خاک به‌دست می‌آورند. گرچه فسفات در خاک فراوان است (نادرستی گزینه ۱)، اغلب برای گیاهان غیرقابل‌دسترس است (درستی گزینه ۲). یکی از دلایل، این است که فسفات به بعضی ترکیبات معدنی خاک به‌طور محکمی متصل می‌شود. برخی (نه همه) گیاهان برای جبران، شبکه گسترده‌تری از ریشه‌ها و یا ریشه‌های دارای تار کشنده بیشتر ایجاد می‌کنند که جذب را افزایش می‌دهد (نادرستی گزینه ۴). بیشتر (نه همه) گیاهان دانه‌دار با قارچ‌ها رابطه همزیستی از نوع قارچ‌ریشه‌ای دارند که مواد معدنی و به‌خصوص فسفات را برای آنها فراهم می‌کند (نادرستی گزینه ۳).\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8506\":{\"correct_option_id\":51479,\"descriptive_answer\":{\"text\":\"کودهای شیمیایی، دارای ترکیبات معدنی هستند و کودهای آلی از بقایای در حال تجزیه جانداران تشکیل شده‌اند که به آهستگی مواد معدنی را آزاد می‌کنند. هم کودهای شیمیایی و هم کودهای آلی به گیاهان، آسیب وارد می‌کنند. در واقع، کودهای آلی چون به نیازهای جانداران، شباهت بیشتری دارند، در اثر مصرف بیش از حد آن‌ها، آسیب کمتری به گیاهان وارد می‌کنند. اما کودهای شیمیایی، آسیب زیادی به گیاهان وارد می‌کنند. پس مقدار آسیب این کودها به گیاهان متفاوت است. اما توجه کنید که این کودها در اثر مصرف بیش از حد، به گیاهان آسیب وارد می‌کنند، نه پس از هر بار مصرف!\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۲ خاک از سه بخش تشکیل شده است: ۱- بخش آلی (هوموس یا گیاخاک) ۲- بخش غیرآلی ۳- ریزجانداران یا میکروارگانیسم‌ها. کود آلی سبب افزایش مقدار اجزای هوموس می‌شود، چون دارای اجزای مشابهی با این بخش خاک است. کود زیستی نیز دارای ریزجانداران است؛ بنابراین در افزایش مقدار بخش ریزجانداران خاک نقش دارد. با توجه به این توضیحات می‌توان به شباهت کود آلی و زیستی از نظر نقش در افزایش مقدار اجزای بخشی از خاک پی‌برد. اما معمولاً کودهای زیستی برخلاف کودهای آلی همراه با کودهای شیمیایی به خاک اضافه می‌شوند و در این مورد با یکدیگر، تفاوت دارند.\\r\\n\\r\\n۳ کودهای شیمیایی و زیستی به دلیل فراهم کردن عناصر مورد نیاز گیاهان، نقش غیرمستقیم در افزایش حاصلخیزی خاک دارند و از این نظر به یکدیگر شباهت دارند اما اگر کودهای شیمیایی برخلاف کودهای زیستی در اثر بارش، شسته و وارد آب شوند؛ موجب تسریع رشد گیاهان آبزی، جلبک‌ها و باکتری‌ها می‌شوند که در این صورت، مانع نفوذ نور و اکسیژن کافی به آب می‌شود و در نهایت موجب مرگ و میر جانوران آبزی خواهد شد.\\r\\n\\r\\n۴ کودهای آلی به نیازهای جانداران، شباهت بیشتری دارند اما این بدین معنا نیست که سایر کودها به نیازهای جانداران شباهت ندارند. در واقع کودهای شیمیایی نیز به نیازهای جانداران مانند گیاهان شباهت دارند اما به مقدار کم. پس از این نظر با یکدیگر شباهت دارند. در مقابل کودهای آلی ترکیبات معدنی را با سرعت کم و کودهای شیمیایی، ترکیبات معدنی را با سرعت زیاد به خاک اضافه می‌کنند. پس از نظر سرعت آزادسازی ترکیبات معدنی با یکدیگر، متفاوت هستند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8511\":{\"correct_option_id\":51460,\"descriptive_answer\":{\"text\":\"در حد اطلاعات کتاب درسی جاندارانی مانند سس، گل جالیز، شته و نوعی قارچ می‌توانند اندام مکنده‌ی خود را وارد گیاه نمایند تا از مواد مغذی آن استفاده کنند. هیچ‌یک از این جانداران قدرت فتوسنتز و تبدیل دی‌اکسیدکربن به گلوکز را ندارند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ شته!!\\r\\n\\r\\n۳ شته اندام مکنده خود را تا آوند آبکش ساقه وارد می‌کند تا از ترکیبات شیره‌ی پرورده استفاده نماید. همان‌طور که می‌دانید آوند آبکش در بخش مرکزی ساقه وجود ندارد.\\r\\n\\r\\n۴ گل جالیز اندام مکنده‌ی خود را وارد ریشه‌ی گیاهان جالیزی می‌کند. در نوک ریشه کلاهک وجود دارد که یاخته‌های سطحی آن مرده‌اند و به تدریج می‌ریزند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8516\":{\"correct_option_id\":51440,\"descriptive_answer\":{\"text\":\"خاک ترکیبی از مواد آلی غیر آلی و ریز جانداران (میکروارگانیسم‌ها) است. اسیدهای تولید شده توسط جانداران و نیز ریشه گیاهان می‌توانند هوازدگی شیمیایی ایجاد کنند. هوازدگی سبب تولید بخش غیر آلی خاک می‌شود. می‌دانید که بخش‌های غیر آلی می‌توانند فاقد اتم کربن در ساختار خود باشند. توجه داشته باشید که هر ماده آلی در ساختار خود به طور قطع دارای اتم کربن است.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ و ۴ گیاخاک (هوموس) لایه سطحی خاک است و به طور عمده از بقایای جانداران و به‌ویژه اجزای در حال تجزیه آن‌ها تشکیل شده است. گیاخاک با داشتن بارهای منفی یون‌های مثبت را در سطح خود نگه می‌دارند و در نتیجه مانع از شست‌وشوی این یون‌ها می‌شوند. گیاخاک همچنین باعث اسفنجی شدن حالت خاک می‌شود که برای نفوذ ریشه مناسب است. باکتری‌های آمونیاک‌ساز موجود در خاک با مصرف مواد آلی به تولید یون آمونیوم می‌پردازند.\\r\\n\\r\\n۳ ذرات غیر آلی خاک از تخریب فیزیکی و شیمیایی سنگ‌ها در فرایندی به نام هوازدگی ایجاد می‌شوند. این ذرات از اندازه بسیار کوچک رس تا درشت شن و ماسه را شامل می‌شوند. تغییرات متناوب یخ زدن و ذوب شدن که باعث خرد شدن سنگ‌ها می‌شود نمونه‌ای از اثر هوازدگی فیزیکی است. همانطور که اشاره شد اسیدهای تولید شده توسط جانداران و نیز ریشه گیاهان (نوعی اندام غیرهوایی) هم می‌توانند هوازدگی شیمیایی ایجاد کنند.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":51441,\"is_answered\":true},\"8520\":{\"correct_option_id\":51426,\"descriptive_answer\":{\"text\":\"کودهای شیمیایی شامل مواد معدنی هستند که به راحتی در اختیار گیاه قرار می‌گیرند؛ بنابراین می‌توانند به سرعت، کمبود مواد مغذی خاک را جبران کنند. مصرف بیش از حد کودهای شیمیایی می‌تواند آسیب‌های زیادی به خاک و محیط زیست وارد و بافت خاک را تخریب کند. از طرفی، با شسته شدن توسط بارش‌ها، این مواد به آب‌ها وارد می‌شوند. حضور این مواد (در آب) باعث رشد سریع باکتری‌ها، جلبک‌ها و گیاهان آبزی می‌شود. افزایش این عوامل مانع نفوذ نور و اکسیژن کافی به آب می‌شود و می‌تواند باعث مرگ‌ومیر جانوران آبزی شود. اما توجه داشته باشید که از معایب کودهای آلی، احتمال آلودگی به عوامل بیماری‌زاست نه کودهای شیمیایی!\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ همانطور که اشاره شد، این کودها به سرعت، کمبود مواد مغذی خاک را جبران می‌کنند.\\r\\n\\r\\n۲ کودهای زیستی شامل باکتری‌هایی هستند که برای خاک مفید و با فعالیت و تکثیر خود، مواد معدنی خاک را افزایش می‌دهند. استفاده از این کودها بسیار ساده‌تر و کم هزینه‌تر است. این کودها معمولاً به همراه کودهای شیمیایی به خاک افزوده می‌شوند و معایب دو نوع کود دیگر را ندارند.\\r\\n\\r\\n۳ کودهای شیمیایی سبب رشد باکتری‌ها می‌شوند که رشد باکتری‌ها با افزایش ابعاد آن‌ها به‌صورت برگشت‌ناپذیر انجام می‌شود.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8529\":{\"correct_option_id\":51390,\"descriptive_answer\":{\"text\":\"کودهای آلی، به نیازهای جانداران شباهت بیشتری دارند. کودهای شیمیایی می‌توانند به سرعت، کمبود مواد مغذی خاک را جبران کنند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ مصرف بیش از حد کودهای شیمیایی می‌تواند آسیب‌های زیادی به خاک و محیط زیست وارد و بافت خاک را تخریب کند. از طرفی، با شسته شدن توسط بارش‌ها، این مواد به آب‌ها وارد می‌شوند. حضور این مواد باعث رشد سریع باکتری‌ها، جلبک‌ها و گیاهان آبزی می‌شود.\\r\\n\\r\\n۲ واضح است که کودهای آلی، حاوی مواد آلی هستند! کودهای زیستی نیز حاوی مواد آلی هستند؛ چرا که شامل باکتری‌هایی که جاندار زنده هستند، با فعالیت خود، مواد آلی می‌سازند. کودهای زیستی معمولاً به همراه کودهای شیمیایی به خاک افزوده می‌شوند و معایب دو نوع کود دیگر را ندارند.\\r\\n\\r\\n۳ کودهای زیستی شامل باکتری‌هایی هستند که برای خاک مفید و با فعالیت و تکثیر خود، مواد معدنی خاک را افزایش می‌دهند. کودهای آلی نیز ممکن است حاوی جانداران باشند، چرا که شامل بقایای در حال تجزیه جانداران‌اند و ممکن است این بقایا توسط باکتری‌ها و دیگر جانداران تجزیه شوند. از معایب کودهای آلی، احتمال آلودگی به عوامل بیماری‌زا است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8534\":{\"correct_option_id\":51367,\"descriptive_answer\":{\"text\":\"دقت داشته باشید که نخود، سویا و یونجه گیاهانی هستند که جزئی از تیره پروانه‌واران هستند. در این گیاهان، گل‌ها (نه برگ‌ها!) ظاهری شبیه پروانه دارند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۲ در ریشه گیاهان تیره پروانه‌واران، برجستگی‌هایی به نام گرهک دیده می‌شود؛ اگر به شکل دقت کنید این برجستگی‌ها در ریشه جانبی مشاهده می‌شوند.\\r\\n\\r\\n۳ هنگامی که گیاه نخود، می‌میرد، یا بخش‌های هوایی آن برداشته می‌شود گرهک‌های آن در خاک می‌ماند و گیاخاک غنی از نیتروژن ایجاد می‌کند.\\r\\n\\r\\n۴ در گرهک نخود، باکتری‌های ریزوبیوم قرار گرفته‌اند؛ این باکتری‌ها، برای گیاهان نیتروژن (به فرم آمونیوم) فراهم می‌کنند و در عوض گیاه مواد آلی مورد نیاز باکتری را تأمین می‌کند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":51370,\"is_answered\":true},\"8548\":{\"correct_option_id\":51307,\"descriptive_answer\":{\"text\":\"گیاه حشره‌خوار توبره‌واش توانایی فتوسنتز دارد ولی گیاه انگل سس فاقد این توانایی است. گیاه توبره‌واش و گونرا هر دو در مناطق کم‌نیتروژن زندگی می‌کنند.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\nگزینه «۲»: محل زندگی گیاه توبره‌واش و آزولا تالاب‌های شمال کشور است.\\r\\n\\r\\nگزینه «۳»: گیاه توبره‌واش با سیانوباکتری‌ها همزیستی ندارد.\\r\\n\\r\\nگزینه «۴»: نه گیاه توبره‌واش و نه گیاه آزولا توانایی تولید اندام مکنده ندارند.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8553\":{\"correct_option_id\":51288,\"descriptive_answer\":{\"text\":\"در بخش پهنک برگ گیاهان گوشت‌خوار امکان مشاهدهٔ ساختارهای مو مانند وجود دارد. (خوب به شکل دقت کنین! اگر نمیتونین اوووووب زوم کنین شکل با کیفیت ترش هم براتون گذاشتیم!حتی از نظر علمی تعداد این کرک‌ها(موها) در پهنک مهمه! که هر تیکه از برگ دارای ۳ تا ساختار مو مانند هستش چرا مهمه؟ آگه حشره به دوتا از این موها برخورد کنه تله بسته میشه.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ با توجه به شکل مقابل، در بخش پهنک برگ‌های گوشت‌خوار، رنگ برگ تفاوت دارد و میزان سبزینه کمتر است.\\r\\n\\r\\n۳ در این برگ‌ها، گوارش حشرات صورت می‌گیرد در نتیجه گروهی از یاخته‌ها وجود دارند که آنزیم‌های گوارشی را تولید و ترشح می‌کنند و گروهی دیگر، مواد گوارش یافته را جذب می‌کنند.\\r\\n\\r\\n۴ در میان مواد جذب شده علاوه بر مواد معدنی، مواد آلی نیز وجود دارند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8557\":{\"correct_option_id\":51274,\"descriptive_answer\":{\"text\":\"همه موارد اشتباه هستند.\\r\\n\\r\\nالف: $۹۰$ درصد گیاهان دانه‌دار با قارچ‌ها به صورت قارچ ریشه‌ای همزیستی دارند.\\r\\n\\r\\nب: با توجه به شکل صفحه $۱۰۲$ رشته‌های قارچ به آوند نفوذ نمی‌کنند.\\r\\n\\r\\nج: به علت گرفتن مواد معدنی قارچ توسط گیاه، گیاه رشد بیشتری می‌کند.\\r\\n\\r\\nد: قارچ ریشه‌ای مواد معدنی را به گیاه داده و از گیاه مواد آلی می‌گیرد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"893\":6591,\"896\":6588,\"8516\":51441,\"8534\":51370},\"totalTimeSpent\":70,\"questionTimes\":{\"604\":1000,\"606\":12002,\"893\":31000,\"8516\":1001,\"8534\":998,\"8548\":1999},\"selectionLog\":[{\"questionId\":893,\"optionId\":6589,\"timeSpentMs\":21001,\"timestamp\":1787643256152},{\"questionId\":893,\"optionId\":6591,\"timeSpentMs\":25999,\"timestamp\":1787643265937},{\"questionId\":896,\"optionId\":6588,\"timeSpentMs\":0,\"timestamp\":1787643273760},{\"questionId\":8534,\"optionId\":51370,\"timeSpentMs\":998,\"timestamp\":1787643276317},{\"questionId\":8516,\"optionId\":51441,\"timeSpentMs\":1001,\"timestamp\":1787643277423}],\"lobbyCode\":\"M2l3mgk2yr\"}}', '2026-08-25 07:35:06'),
(147, 70, 104, 10.00, 1, 0, 9, 9, 68, '{\"total_questions\":10,\"correct_count\":1,\"incorrect_count\":0,\"unanswered_count\":9,\"accuracy_rate\":10,\"score\":9,\"mabhas_stats\":{\"دو دوازدهم\":{\"correct\":1,\"incorrect\":0,\"unanswered\":9,\"total\":10}}}', '{\"evaluation\":{\"891\":{\"correct_option_id\":6599,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; منظور صورت سؤال، تنظیم منفی رونویسی در باکتری اشرشیاکلای است. رونویسی از ژن های رمزکننده آنزیم های مرتبط با تجزیه لاکتوز توسط رنابسپاراز، سبب تولید یک رنای پیک چندژنی می شود که سه کدون آغاز و سه کدون پایان دارد. پس از رونویسی از این ژن ها و ترجمه آن و تولید آنزیم های مربوط به تجزیه (آبکافت) لاکتوز، حال نوبت تجزیه آن است که طی این فرایند لاکتوز به جایگاه فعال در ساختار آنزیم مؤثر در تجزیه آن متصل و به دو مونوساکارید تجزیه می شود؛ نهایتا هم، قند گلوکز در دسترس باکتری افزایش می یابد. بررسی سایر گزینه ها: 1) مهارکننده و رنا بسپار از پروتئین هایی هستند که در تنظیم بیان ژن (طی تنظیم منفی رونویسی) نقش . مهارکننده به اپراتور و رنا بسپاراز به راه انداز متصل می شود که هیچ کدام جزء توالی ژن نیستند، بلکه توالی تنظیمی مرتبط با ژن هستند. در حضور لاکتوز، پروتئین مهارکننده از اپراتور (نه بخشی از ژن) جدا می شود. همان طور که گفتیم توالی های اپراتور و راه انداز توالی تنظیمی محسوب می شوند و جزء ژن نمی باشند، بنابراین رونویسی هم نمی گردند. 2) لاکتوز موجود در محیط پس از ورود به باکتری با اتصال به مهار کننده، باعث تغییر شکل آن می شود. تغییر شکل مهارکننده، آن را از اپراتور جدا می کند و مانع از اتصال آن به اپراتور می شود (کاهش تمایل اتصال آن به دنا). دقت کنید که اتصال رنابسپاراز به توالی راه انداز در طی تنظیم منفی رونویسی بدون نیاز به کمک عامل خاصی صورت می گیرد و ارتباطی به حضور لاکتوز در محیط و اتصال آن به مهارکننده ندارد. بنابراین در هر زمانی رنابسپاراز به راه انداز متصل می شود طی این تنظیم، توالی راه انداز قبل از توالی اپراتور قرار دارد. 4) توالی اپراتور بعد از راه انداز قرار دارد و رونویسی هم نمی شود.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"893\":{\"correct_option_id\":6591,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; در پروکاریوت ها، منظور از توالی ویژه مؤثر در رونویسی، می تواند توالی راه انداز، اپراتور، جایگاه اتصال فعال کننده و یا توالی پایان رونویسی باشد. در یوکاریوت ها، توالی افزاینده هم، نوعی توالی ویژه است که در رونویسی نقش دارد. از بین مراحل طویل شدن و پایان، فقط در مرحله پایان، پس از رونویسی شدن توالی پایان رونویسی (جزئی از ژن)، آنزیم رنابسپاراز از مولکول دنا (DNA) جدا می شود. دقت کنید که سایر توالی های نام برده شده جزئی از توالی ژن نمی باشند. بررسی سایر گزینه ها: 1) شکسته شدن پیوندهای هیدروژنی میان دو رشته دنا (و در نتیجه پیوندهای بین نوکلئوتیدهایی با قندهای یکسان) را هم در مرحله طویل شدن و هم در مرحله پایان ترجمه می توان مشاهده نمود؛ نه در برخی از آن ها! 2) این گزینه در خصوص مرحله پایان رونویسی است که بعد از رونویسی شدن توالی پایان رونویسی، رنابسپار از از دنا جدا می شود. اما توجه داشته باشید که در پروکاریوت ها، دنای &laquo;هسته ای!&raquo; نداریم و این گزینه از بیخ و بن نادرست می باشد. 4) در مرحله آغاز رونویسی، راه انداز موجب می شود رنا بسپار از اولین نوکلئوتید مناسب را به طور دقیق پیدا و رونویسی را از آنجا آغاز کند. در این حالت بخش کوچکی از مولکول دنا باز و زنجیره کوتاهی از رنا ساخته می شود. با این اوصاف، این گزینه در خصوص هیچ یک از مراحل طویل شدن و پایان صادق نیست.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"894\":{\"correct_option_id\":6581,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; موارد &laquo;الف&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) پس از خروج رنای ناقل فاقد آمینواسید از جایگاهE ، براساس وجود یا عدم وجود کدون پایان در جایگاه ،A دو اتفاق می تواند رخ دهد. یا عامل آزاد کننده به جایگاه A وارد می شود (اگر کدون پایان در جایگاه A (باشد که در نهایت رنای ناقل و زنجیره پلی پپتیدی از جایگاه P ریبوزوم خارج می شوند؛ و اگر کدون رمزکننده یک آمینواسید در جایگاه A باشد، جایگاه A آماده پذیرش رنای ناقل بعدی می شود که پس از ورود و استقرار رنای ناقل مکمل به این جایگاه پیوند اشتراکی در جایگاه P ریبوزوم شکسته می شود تا پیوند پپتیدی بعدی تشکیل شود. ب) این مورد همواره رخ می دهد و مخصوص شرایط خاصی نیست! دقت کنید که تشکیل پیوند پپتیدی در جایگاه A رناتن اتفاق می افتد و کمی پس از تشکیل آن، همواره جابه جایی رناتن بر روی رنای پیک رخ میدهد که در نتیجه آن، رنای ناقل متصل به رشته پپتیدی به جایگاه P وارد میشود و رنای ناقل فاقد آمینواسید پس از ورود به جایگاه E رناتن، از آن خارج می گردد. ج) علاوه بر مرحله پایان ترجمه که پیوند بین رشته آمینواسیدی و tRNA شکسته می شود، طی طویل شدن هم این اتفاق می افتد، اما در پایان برخلاف طویل شدن tRNA ،فاقد آمینواسید به جایگاه E منتقل نمیشود بنابراین این جمله فقط درباره مرحله طویل شدن ترجمه صدق می کند یعنی در برخی شرایط رخ می دهد. د) کمی پیش از تشکیل پیوند پپتیدی در جایگاه ،A ریبوزوم پیوند اشتراکی بین آمینواسید و tRNA در جایگاه میانی ریبوزوم (جایگاه(P شکسته می شود. در واقع اگر قرار باشد پیوند پپتیدی تشکیل شود، همواره (نه در برخی شرایط!) باید رشته پپتیدی یا آمینواسید متصل به رنای ناقل در جایگاه ،P از این رنای ناقل جدا شود و سپس به جایگاه A منتقل گردد تا در نهایت به آمینواسید موجود در این جایگاه متصل شود. بنابراین، پیش از تشکیل هر پیوند پپتیدی حین ترجمه، باید پیوند اشتراکی بین رنای ناقل و بخش پپتیدی (یا آمینواسید) متصل به آن شکسته شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"895\":{\"correct_option_id\":6578,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; در مرحله پایان ،ترجمه پروتئین(های) عوامل آزاد کننده در تماس با بخشی از رنای پیک قرار می گیرند. در مرحله پایان رونویسی نیز آنزیم پروتئینی رنابسپاراز با نوکلئوتیدهای بخشی از رنای پیک در تماس است. نوکلئوتیدهای سازندۀ رنا دارای قند ریبوز هستند. بررسی سایر گزینه ها: 1) در فرایند ترجمه، پیوند هیدروژنی و رابطه مکملی بین بخش هایی از دو نوع رنا (پیک و ناقل) با نوکلئوتیدهای دارای قندهای یکسان (ریبوز) صورت می گیرد. در رونویسی، پیوندهای هیدروژنی بین رنا و دنا با نوکلئوتیدهایی با قند متفاوت تشکیل می شود. 3) در مرحله آغاز ترجمه، پیوند هیدروژنی بین بازهای کدون آغاز با آنتی کدون مکمل آن تشکیل می شود. در مرحله آغاز رونویسی، پیوندهای هیدروژنی میان دو رشته دنا شکسته می شوند و بین نوکلئوتیدهای رنا و دنا پیوندهای هیدروژنی تشکیل می شوند. 4) در مرحله آغاز رونویسی، زنجیرۀ کوتاهی از رنا تشکیل می شود؛ پس بین نوکلئوتیدهای رنا و دنا پیوندهای هیدروژنی و بین ریبونوکلئوتیدهای رنا، پیوند اشتراکی شکل می گیرد. در آغاز ترجمه، هنوز پیوند پپتیدی (اشتراکی) بین آمینواسیدها تشکیل نمی شود. اما بین ریبونوکلئوتیدهای رنای پیک و رنای ناقل، پیوند هیدروژنی شکل می گیرد.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6578,\"is_answered\":true},\"896\":{\"correct_option_id\":6585,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در یک مولکول رنای ناقل، هر نوکلئوتیدی که در یک انتهای رشته پلی نوکلئوتیدی قرار دارد با سایر نوکلئوتیدهای این رنا، فقط یک پیوند فسفودی استر تشکیل می دهد. براساس شکل کتاب درسی دیده می شود که در رنای ناقل، یکی از این دو نوکلئوتید در جایگاه اتصال به آمینواسید قرار دارد و با نوکلئوتید دیگری در ساختار رنای ناقل، پیوند هیدروژنی تشکیل نمی دهد. طبق شکل کتاب درسی، نوکلئوتید دیگر، در انتهای دیگر رشته پلینوکلئوتیدی پیوند هیدروژنی تشکیل می دهد. بررسی سایر گزینه ها: 2) در ساختار رنای ناقل ،یک نوکلئوتید در یک توالی سه نوکلئوتیدی در یک انتهای tRNA ، جایگاه اتصال به آمینواسید را تشکیل می دهد. مطابق شکل کتاب درسی، این نوکلئوتید جایگاه اتصال به آمینواسید در دورترین نقطه (بیشترین تعداد نوکلئوتید بین آن ها) نسبت به توالی پادرمزه (آنتی کدون) قرار دارد. براساس توالی پادرمزه، آمینواسید خاصی به رنای ناقل متصل می شود. 3) دو حلقه از رنای ناقل که فاقد توالی پادر مزه هستند، در ساختار سه بعدی مولکول رنای ناقل نسبت به تاخوردگی اولیه به یکدیگر نزدیک تر هستند. 4) ساختار نهایی میوگلوبین، ساختار سوم آن است. در میوگلوبین، برای اولین بار، تاخوردگی ها در ساختار دوم رخ می دهد که باعث ایجاد ساختار مارپیچ می شود و تاخوردگی های بیشتر نیز برای تشکیل ساختار سوم ایجاد می شود تا ساختار نهایی پروتئین شکل بگیرد. رنای ناقل نیز پس از تاخوردگی اولیه، تاخوردگی های مجددی پیدا میکند که ساختار سه بعدی آن را پدید می آورد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"897\":{\"correct_option_id\":6572,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; در مرحله آغاز و پایان ترجمه، رنای ناقل در جایگاه A و E ریبوزوم دیده نمی شود. در مرحله آغاز، زیرواحد بزرگ ریبوزوم به زیرواحد کوچک آن متصل می شود و در مرحله پایان ترجمه، زیرواحد بزرگ ریبوزوم از زیرواحد کوچک آن جدا خواهد شد؛ پس تمایل آن ها برای اتصال به هم تغییر می کند. بررسی سایر گزینه ها: 1) دقت داشته باشید این مولکول پلی پپتیدی می تواند دو نوع مولکول مختلف باشد؛ یکی رشته پلی پپتیدی در حال ساخت که به رنای ناقل موجود در جایگاه A اتصال دارد و طی مرحله طویل شدن و با حرکت رناتن وارد جایگاه P می شود. دیگری نیز ممکن است پروتئین آزادکننده باشد که نوعی مولکول پلی پپتیدی است و در مرحلۀ پایان در جایگاه A قرار می گیرد. با قرار گیری پروتئین آزاد کننده در جایگاه ،A دیگر حرکتی توسط رناتن به سمت جلو صورت نمی گیرد. 2) طبق شکل و متن کتاب درسی، در هیچ یک از مراحل ترجمه، امکان این که به صورت هم زمان جایگاه های A و E رناتن توسط رناهای ناقل اشغال شوند، وجود ندارد! زیرا همواره قبل از ورود tRNA به جایگاه ،A رنای ناقل فاقد آمینواسید از جایگاه E خارج شده است. فقط در مرحله طویل شدن، رنای فاقد آمینواسید در جایگاه E دیده می شود. 3) در مرحله طویل شدن، حداکثر دو رنای ناقل به صورت هم زمان در جایگاه های رناتن قابل مشاهده هستند و در مرحله آغاز و پایان فقط یک رنای ناقل در رناتن دیده می شود. طبق شکل کتاب درسی، در فرایند ترجمه، هر آمینواسید جدید به انتهای کربوکسیل (نه آمین) رشته پپتیدی در حال ساخت متصل می گردد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"898\":{\"correct_option_id\":6574,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; هلیکاز در طی همانندسازی، دو رشته دنا را از هم باز می کند، پس فقط یک نوع واکنش خاص را سرعت می بخشد، اما رنابسپاراز علاوه بر این که می تواند پیوندهای هیدروژنی بین دو رشته دنا را بشکند می تواند مولکول رنا هم بسازد؛ یعنی ریبونوکلئوتیدها را با پیوندهای فسفودی استر به هم وصل کند، پس دو نوع واکنش خاص را سرعت می بخشد. بررسی سایر گزینه ها: 1) رنابسپار از قادر است تا پیوندهای اشتراکی از نوع فسفودی استر را بین نوکلئوتیدها برقرارکند. اما هلیکاز چنین قابلیتی ندارد. ۳) هر دو آنزیم رنابسپاراز و هلیکاز، به منظور انجام فعالیت خود، به مولکول دنا متصل می شوند و ۲ رشته دنا را در بر می گیرند. آنزیم رنابسپار از می تواند یک رشته دنا را برای رونویسی شدن! الگو قرار دهد، اما هلیکاز هیچ یک از ۲ رشته را الگو قرار نمی دهد، زیرا توانایی تولید بسپار جدیدی را ندارد. 4) در فرایند رونویسی آنزیم رنابسپاراز RNA) پلیمراز)، پیوندهای هیدروژنی را می شکند؛ اما در فرایند همانندسازی، آنزیم هلیکاز، پیوندهای هیدروژنی را می شکند. دقت داشته باشید که در هر دو فرایند، تشکیل پیوندهای هیدروژنی به شکل خودبه خودی (نه با دخالت آنزیم) انجام می گردد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"899\":{\"correct_option_id\":6565,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در تنظیم منفی، لاکتوز و در تنظیم مثبت، مالتوز در وقوع فرایند نقش مهمی دارد! بلافاصله قبل از شروع رونویسی، پروتئین فعال کننده با مالتوز، دنا و رنابسپار از در تماس قرار می گیرد که به ترتیب نوعی کربوهیدرات، نوکلئیک اسید و پروتئین می باشند. به عبارتی اتصال مالتوز به فعال کننده و در ادامه، اتصال این مجموعه به دنا و در نهایت به رنابسپار از سبب می شود رنابسپاراز به راه انداز بچسبد و رونویسی را شروع کند.\\n\\n بررسی سایر گزینه ها: \\n\\n2) محصول اولیه رونویسی از ژن های مرتبط با تجزیه مالتوز، یک رنای پیک چندژنی است. طبق شکل های ۱۱ و ۱۳ فصل ۲ زیست شناسی ۳ می توان گفت، اولین توالی سه نوکلئوتیدی در یک رنای پیک لزومن کدون آغاز نیست، همچنین آخرین توالی هم لزوما کدون پایان نیست؛ زیرا در ساختار رناهای پیک قبل از کدون آغاز و بعد کدون پایان توالی های نوکلئوتیدی مشاهده می شوند. رنای پیک چندژنی که اینجا ساخته می شود سه کدون آغاز و سه کدون پایان دارد (بخش مربوط به هر ژن کدون آغاز و پایان خود را دارد). \\n\\n3) در یوکاریوت ها در تنظیم بیان ژن در مرحله رونویسی، چند (بیش از دو) مولکول پروتئینی (عوامل رونویسی) به راه انداز و توالی افزاینده متصل می شود که کنارهم قرارگیری این پروتئین ها باعث تسریع رونویسی می شود. اما در تنظیم مثبت رونویسی در اشرشیاکلای به راه انداز، رنابسپاراز و به جایگاه اتصال فعال کننده، پروتئین فعال کننده متصل می شود. \\n\\n4) در تنظیم مثبت رونویسی، پس از راه انداز، توالی ژن ها قرار دارند که در طی رونویسی دو رشته آن ها از هم باز می شود.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"903\":{\"correct_option_id\":6561,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; برای حل این سؤال، تک تک موارد را به ترتیب بررسی می کنیم. مورد اول: همۀ رناهای ناقل به دلیل تاخوردگی های متعدد شکل سه بعدی و فضایی Lشکل به خود می گیرند. رنای رناتنی (rRNA) نیز به دلیل فعالیت آنزیمی خود دارای ساختار سه بعدی و شکل فضایی معین است. مورد دوم: همه انواع رناها و دناهای یاخته؛ مولکول های حامل اطلاعات وراثتی محسوب می شوند و همگی نوعی مولکول اطلاعاتی هستند. مورد سوم: همۀ انواع رناها و دناهای یاخته بسپارهایی (پلیمرهایی) از واحدهای تکرارشونده نوکلئوتیدی هستند. مورد چهارم: تنها برخی رناهای پیک در یاخته های پروکاریوتی می تواند حاوی رونوشت چندین ژن باشد. مورد پنجم: طبق شکل کتاب درسی، رنای پیک، با هر دو زیرواحد کوچک و بزرگ ریبوزوم تماس دارد. رنای ناقل فقط با زیرواحد بزرگ ریبوزوم تماس دارد. رنای رناتنی (rRNA) نیز در ساختار هر دو زیرواحد ریبوزوم حضور دارد. با توجه به توضیحات بالا، سه مورد (موارد اول، دوم و سوم) در خصوص رنای ناقل، چهار مورد (همه موارد به جز مورد اول) در خصوص رنای پیک و چهار مورد (همه موارد به جز مورد چهارم) در خصوص رنای رناتنی صحیح است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"921\":{\"correct_option_id\":6519,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; با توجه به رونویسی از ژن(های) مربوط به ساخته شدن &laquo;عوامل رونویسی&raquo;، باید بدانیم که یاخته مورد نظر صورت سؤال، یوکاریوت است. موارد &laquo;الف&raquo; و &laquo;د&raquo; غیرممکن است. بررسی همه موارد: الف) غیر ممکن - اثر جهش بر توالی های تنظیمی ژن ممکن است سبب افزایش رونویسی ژن های مربوطه شود، با افزایش تولید رنا، امکان افزایش ساخت پروتئین ها هم وجود دارد. اما دقت کنید عوامل رونویسی در یاخته های یوکاریوتی دیده می شوند و در این یاخته ها امکان ترجمه mRNA قبل از اتمام رونویسی وجود ندارد. ب و ج) ممکن - جهش در راه انداز یا افزاینده، ممکن است آن ها را به توالی تنظیمی قوی تر یا ضعیف تر تبدیل کند که به دنبال آن با اثر بر میزان رونویسی از توالی ژن(های) مربوط به آن ها محصول آن را نیز بیشتر یا کمتر می کند؛ بنابراین می توان گفت جهش ممکن است به گونه ای رخ دهد که آنزیم رنا بسپار از نتواند به راه انداز متصل شود یا به علت تمایل کمتر عوامل رونویسی به راه انداز، میزان اتصال آنزیم رنا بسپاراز به راه انداز نیز کمتر شود یا جهش(ها) به گونه ای باشد که عوامل رونویسی به مدت زمان بیشتری به افزاینده متصل باشند (تمایل بیشتر برای اتصال به DNA )، اتصال عوامل رونویسی به افزاینده، سبب خمیده شدن دنا و قرارگیری این بخش در کنار راه انداز می شود. د) غیرممکن - جهش در توالی های تنظیمی، توالی آمینواسیدی پروتئین های حاصل از رونویسی و ترجمه را تغییر نمی دهد، اما دقت کنید اگر این جهش به گونه ای رخ دهد که رنابسپار از نتواند به راه انداز مربوط به ژن های سازنده عوامل رونویسی متصل شود، آن وقت ساخت این پروتئین های عوامل رونویسی مختل می شود و از آنجایی که حضور این پروتئین ها برای بیان ژن های مختلفی در یاخته یوکاریوتی لازم است (در واقع با عدم تولید عوامل رونویسی، اتصال رنابسپاراز به راه انداز سایر ژن ها نیز مختل می شود)، ممکن است در رونویسی سایر ژنها و در نتیجه ساخت آنزیم ها هم اختلال به وجود بیاید به این ترتیب میزان واکنش های آنزیمی یاخته هم تغییر می کند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"895\":6578},\"submittedQuestionIds\":[895,891,899,896,893,897,894,921,903,898],\"totalTimeSpent\":68,\"questionTimes\":{\"891\":1001,\"895\":62000,\"898\":4001},\"selectionLog\":[{\"questionId\":895,\"optionId\":6578,\"timeSpentMs\":62000,\"timestamp\":1787651085061}]}}', '2026-08-25 09:44:50');
