(155, 78, 4, 0.00, 0, 7, 39, 0, 10, '{\"total_questions\":46,\"correct_count\":0,\"incorrect_count\":7,\"unanswered_count\":39,\"accuracy_rate\":0,\"score\":0,\"mabhas_stats\":{\"هندسه دوازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"مثلثات دهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"فصل دو دهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":2,\"total\":3},\"پنج دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"احتمال دهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"سه دوازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"حد و پيوستگي يازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"فصل یک دوازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"معادله و نامعادله دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل شش دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"دو دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل یک دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":3,\"total\":3},\"هشت دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"الگو و دنباله\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"چهار دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"احتمال دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"شمارش بدون شمردن\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"تابع دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"قدرمطلق و جزءصحيح\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"یک دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"شش دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل پنج دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل سه دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":3,\"total\":3},\"تابع دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"آمار\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل سه دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"هفت دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مثلثات دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل هفت دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"معادله و تابع درجه دوم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"فصل چهار دهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":2,\"total\":2},\"فصل یک یازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"احتمال يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"كاربرد مشتق\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"توان هاي گويا و عبارت هاي جبري\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مشتق\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"مجموعه ها\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"حد و پيوستگي دوازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1},\"معادله و نامعادله يازدهم\":{\"correct\":0,\"incorrect\":0,\"unanswered\":1,\"total\":1}}}', '{\"evaluation\":{\"360\":{\"correct_option_id\":5099,\"descriptive_answer\":{\"text\":\"فقط مورد (ج)، صحیح است. در دیواره لوله گوارش (از مری تا مخرج) شبکه&zwnj;های یاخته&zwnj;های عصبی در لایه ماهیچه&zwnj;ای و زیر مخاط وجود دارند. الف) شبکه&zwnj;های یاخته&zwnj;های عصبی که در دیواره مری وجود دارند تحرک (فعالیت یاخته&zwnj;های لایه ماهیچه&zwnj;ای) و ترشح (فعالیت یاخته&zwnj;های لایه مخاطی) را تنظیم کنند. این شبکه&zwnj;ها می&zwnj;توانند مستقل از دستگاه عصبی خودمختار فعالیت کنند اما دستگاه عصبی خودمختار با آن&zwnj;ها ارتباط دارد و بر عملکرد آن&zwnj;ها تأثیر می&zwnj;گذارد. اما در ابتدای مری، لایه ماهیچه&zwnj;ای از نوع ماهیچه اسکلتی است و اعصاب خودمختار نقشی در عصب&zwnj;دهی ماهیچه&zwnj;های اسکلتی ندارند. ب) در لایه ماهیچه&zwnj;ای لوله گوارش، ماهیچه&zwnj;ها به شکل حلقوی و طولی سازمان&zwnj;یافته&zwnj;اند ماهیچه حلقوی نسبت به ماهیچه طولی در قسمت داخلی&zwnj;تر قرار گرفته است و در ارتباط با لایه زیر مخاطی می&zwnj;باشد اما در دیواره معده، یک لایه ماهیچه&zwnj;ای مورب نیز وجود دارد که در سطح داخلی ماهیچه حلقوی قرار گرفته است و بنابراین در معده، ماهیچه مورب (نه حلقوی) در ارتباط با لایه زیر مخاط است. د) لایه بیرونی لوله گوارش، بخشی از صفاق است. صفاق پرده&zwnj;ای است که اندام&zwnj;های درون شکم را به هم وصل می&zwnj;کند. بنابراین، لایه بیرونی اندام&zwnj;های لوله گوارش که خارج از شکم هستند، مانند حلق، در تشکیل صفاق نقش ندارد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"372\":{\"correct_option_id\":5523,\"descriptive_answer\":{\"text\":\"فقط مورد (ب)، نادرست است. الف و ج) بریدن نایژه اصلی به سادگی نای نیست و این به علت ساختار غضروف&zwnj;های نایژه است (درستی مورد الف) که در ابتدا به صورت حلقه کامل و بعد به صورت قطعه&zwnj;قطعه است (درستی مورد ج). ب) در نای گوسفند قبل از دو نایژۀ اصلی یک انشعاب سوم هم مشاهده می&zwnj;شود که به شش راست می&zwnj;رود. شش راست دارای سه لوب است. د) اگر تکه&zwnj;ای از شش را ببرید در مقطع آن سوراخ&zwnj;هایی را مشاهده می&zwnj;کنید که به سه گروه قابل تقسیم&zwnj;اند: نایژه&zwnj;ها، سرخرگ&zwnj;ها و سیاهرگ&zwnj;ها. لبه نایژه&zwnj;ها به علت دارا بودن غضروف، زیر است و به این ترتیب از رگ&zwnj;ها قابل تشخیص است. سرخرگ&zwnj;ها دیواره محکم&zwnj;تری نسبت به سیاهرگ&zwnj;ها دارند و به همین علت، برخلاف سیاهرگ&zwnj;ها دهانه آن&zwnj;ها حتی در نبود خون هم باز است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":null,\"is_answered\":false},\"471\":{\"correct_option_id\":5459,\"descriptive_answer\":{\"text\":\"موارد (ب) و (ج)، درست هستند. الف) به طور کلی همۀ اندام&zwnj;های حفره شکمی و پاها، لنف خود را ابتدا وارد مجرای لنفی چپ (ضخیم&zwnj;ترین مجرای لنفی) می&zwnj;کنند. ب) همانطور که در شکل مشخص است، مجرای لنفی راست برخلاف مجرای لنفی چپ، دارای گره&zwnj;های لنفی در طول خود می&zwnj;باشد. ج) مجرای لنفی راست پس از جدا شدن از مجرای لنفی چپ، از مجاورت کبد عبور می&zwnj;کند که دارای مویرگ&zwnj;های ناپیوسته می&zwnj;باشد. د) در نزدیکی قسمت بالای استخوان ران (در ناحیه کشاله ران) و پایین آن (در ناحیه زانو)، تجمع گره&zwnj;های لنفی مشاهده می&zwnj;شود. محتویات لنفی این نواحی به مجرای لنفی چپ می&zwnj;ریزند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":null,\"is_answered\":false},\"488\":{\"correct_option_id\":6361,\"descriptive_answer\":{\"text\":\"طی استفراغ، اسید معده از بدن خارج می&zwnj;شود و کاهش اسید، باعث قلیایی&zwnj;تر شدن خون (افزایش pH خون) می&zwnj;شود. زمانی که pH خون افزایش یابد، کلیه بیکربنات بیشتری دفع می&zwnj;کند اما افزایش \\\\(CO_2\\\\) خون (مثلاً به دلیل دفع کمتر کربن دی&zwnj;اکسید از بدن در پی کاهش تعداد تنفس در دقیقه) و همچنین اسهال (به دلیل دفع بیکربنات موجود در روده) باعث اسیدی&zwnj;تر شدن خون می&zwnj;شوند و pH خون کاهش می&zwnj;یابد. زمانی که pH خون کاهش یابد، کلیه&zwnj;ها یون هیدروژن را ترشح می&zwnj;کنند (درستی گزینه ۱ و نادرستی گزینه 3). 2) اگر غلظت مواد حل&zwnj;شده در خوناب (مانند سدیم) از حد مشخصی فراتر رود، مرکز تشنگی در هیپوتالاموس تحریک می&zwnj;شود که نتیجه آن فعال&zwnj;شدن مرکز تشنگی و تمایل به نوشیدن آب و از طرف دیگر ترشح هورمون ضد&zwnj;ادراری است. این هورمون با اثر بر کلیه&zwnj;ها، بازجذب آب را افزایش می&zwnj;دهد و به این ترتیب دفع آب از راه ادرار کاهش پیدا می&zwnj;کند. به دنبال کاهش دفع آب از طریق ادرار، غلظت ادرار افزایش می&zwnj;یابد بنابراین، افزایش سدیم خوناب می&zwnj;تواند منجر به افزایش غلظت ادرار شود. 4) تحلیل بیش از حد چربی اطراف کلیه در افرادی که برنامه کاهش وزن سریع و شدید به کار می&zwnj;گیرند ممکن است سبب افتادگی کلیه و تاخوردگی میزنای شود. در این صورت، فرد با خطر بسته شدن میزنای و عدم تخلیه مناسب ادرار از کلیه روبه&zwnj;رو می&zwnj;شود که در نهایت به نارسایی کلیه خواهد انجامید. همچنین حرکت کرمی دیواره میزنای، که نتیجه انقباضات ماهیچه صاف دیواره آن است ادرار را به پیش می&zwnj;راند و بنابراین، آسیب ماهیچه صاف دیواره میزنای نیز می&zwnj;تواند منجر به عدم تخلیه مناسب ادرار از کلیه شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل پنج دهم\",\"selected_option_id\":null,\"is_answered\":false},\"639\":{\"correct_option_id\":6151,\"descriptive_answer\":{\"text\":\"موارد (الف)، (ب) و (ج) نادرست هستند. بررسی موارد: الف) شبکه آندوپلاسمی و ریبوزوم در اتصال مستقیم با غشا خارجی هسته قرار دارند اما تنها شبکه آندوپلاسمی شبکه&zwnj;ای گسترده از کیسه&zwnj;ها را ایجاد می&zwnj;کند. ب) کیسه گلژی، در بسته&zwnj;بندی و ترشح مواد به خارج از یاخته نقش دارد. این اندامک از کیسه&zwnj;هایی تشکیل شده است که روی هم قرار می&zwnj;گیرند و به یکدیگر متصل نیستند. ج) ریبوزوم&zwnj;ها در ساخت اجزای غشای یاخته&zwnj;ای مانند پروتئین&zwnj;های غشایی نقش دارد. این اندامک فاقد غشا در ساختار خود است. د) در یاخته جانوری، تنها راکیزه دارای دو غشای فسفولیپیدی در ساختار خود می&zwnj;باشد. راکیزه در تأمین انرژی یاخته دارای نقش است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"718\":{\"correct_option_id\":6418,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; با توجه به این که در ساختار ساقه تک لپه ای ها، دسته های آوندی در مجاور روپوست نیز یافت می شوند و این که در این بخش از گیاه، یاخته های فیبر مشاهده می شود، می توان گفت در ساختار ساقه این گیاهان می توان نزدیک به روپوست، یاخته های فیبر را مشاهده نمود، اما در گیاهان نهان دانه علفی دولپه، دسته های آوندی در بخش های درونی تر هستند. بررسی سایر گزینه ها: 1) این مورد مربوط به گیاهان دولپه است. ۳) طبق شکل کتاب و سؤال کنکور ۱۴۰۱، در ساقه گیاهان تک لپه، دستجات آوندی بر روی دوایر متعددی قرار دارند؛ نه یک دایره! در گیاهان دولپه، این ساختارها بر روی یک دایره هستند. 4) ترکیبات نیتروژن دار می توانند مواد آلی باشند مثل آمینواسیدها و یا مواد معدنی باشند مثل یون های آمونیوم و نیترات که می دانیم مواد معدنی در آوندهای چوبی دیده می شوند؛ پس در هر دو نوع گیاه امکان مشاهده ترکیبات نیتروژن دار در بخش مرکزی ریشه (جهت ذخیره یا مصرف یا انتقال به سایر بخش ها) وجود دارد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل شش دهم\",\"selected_option_id\":null,\"is_answered\":false},\"836\":{\"correct_option_id\":6714,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; توجه کنید در سطح خارجی غشای همه انواع گویچه های خونی، کربوهیدرات های مختلفی مشاهده می شوند که لزوما ارتباطی به گروه خونی ABO ندارند و جزء غشا هستند؛ مثلا در سطح غشای گویچه های قرمز فردی با گروه خونی O ، کربوهیدرات هایی مشاهده می شود. از طرفی طبق فرض سؤال مادر و پدر، هر دو نمی توانند دگره i را داشته باشند. بررسی سایر گزینه ها: 1) در صورتی که فرزندی مبتلا به فنیل کتونوری (با محدودیت در تغذیه از شیر مادر) متولد شود (دارای ژنوتیپ ff)، ژنوتیپ پدر سالم برای این صفت باید به صورت ناخالص (Ff) باشد. به دنبال وقوع میوز یک در اسپرماتوسیت های اولیه، دگره های مربوط به این صفت از هم جدا شده و به اسپرماتوسیت های ثانویه وارد می شوند؛ بنابراین گروهی از اسپرماتوسیت های ثانویه واجد دگره بارز (F) این صفت و گروهی دیگر نیز واجد دگره نهفته این صفت (f) هستند. از آنجایی که اسپرماتوسیت ثانویه، دارای یک مجموعه کروموزومی به صورت مضاعف شده است (کروموزوم های دو کروماتیدی دارد)، بنابراین اسپرماتوسیت هایی که دگره F را دریافت کرده اند، دو نسخه از این دگره را بر روی یک کروموزوم خود جای می دهند. 3) در این شرایط، مادر حداقل دارای یک دگره نهفته برای هر دو بیماری خواهد بود که احتمال دارد پسر با دریافت دگرۀ نهفته هموفیلی از مادر خود به این بیماری مبتلا شود و با دریافت دگره بارز فنیل کتونوری (از مادر سالم) از نظر این بیماری سالم باشد. 4) با توجه به ژنوتیپ های محتمل در مورد گروه خونی ABO، دو حالت \\\\(AO &times; BB &rarr; AB+BO \\\\) و \\\\(AA &times; BO &rarr; AB+ AO\\\\) محتمل است که فرزندان حداقل یک نوع کربوهیدرات گروه خونی ABO را در سطح غشای گویچه های قرمز خود قرار می دهند.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"سه دوازدهم\",\"selected_option_id\":6716,\"is_answered\":true},\"848\":{\"correct_option_id\":6689,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; پرنده کاکایی پرنده کاکایی پس از آن که جوجه هایش از تخم بیرون می آیند، پوسته های تخم را از لانه خارج می کند. مطابق متن کتاب درسی، در جانوران، هر دو والد می توانند به نوعی هزینه لازم برای پرورش و نگه داری از زاده ها را تأمین کنند. حالا ممکن است یکی هزینه بیشتری بپردازد. بررسی سایر گزینه ها: 2) روی هر یک از پاهای جلویی جیرجیرک یک محفظه هوا وجود دارد که پرده صماخ روی آن کشیده شده است. لرزش پرده در اثر امواج صوتی، گیرنده های مکانیکی را که در پشت پرده صماخ قرار دارند، تحریک و جانور صدا را دریافت می کند. در جیرجیرک مطرح شده در کتاب درسی، جنس نر، زامه ها را به واسطه کیسه ای همراه با مواد مغذی به درون بدن جنس ماده منتقل می کند. در جمعیت این جیرجیرک ها، جانور نر، انتخاب جفت را انجام می دهد و جیرجیرک ماده ای را انتخاب می کند که بزرگ تر باشد. در این جانوران جیرجیرک های ماده برای انتخاب شدن رقابت می کنند. 3) گربه ها از فرومون ها برای تعیین قلمروی خود استفاده می کنند. طبق متن کتاب درسی، در بیشتر پستانداران، نظام چندهمسری وجود دارد، اما همچنان در این نظام نیز، هر دو جنس در موفقیت تولیدمثلی نقش دارند و به عبارتی هر دو زمانی را صرف زادآوری می کنند. مثلا گربه نر با حفظ قلمرو و منابع غذایی و گربه ماده هم با زادآوری و پرورش زاده ها. 4) طاووس های نر، بر روی پرهای خود پر از نقش و نگارهای گوناگون و لکه های چشم مانند هستند. در جمعیت طاووس ها، طاووس های ماده انتخاب جفت را انجام می دهند و طاووسی را انتخاب می کنند که دارای نقش و نگار بیشتری بر روی پرهای خود است؛ دقت کنید در جمعیت طاووس ها، اگرچه کیفیت رژیم غذایی طاووس نر، باعث ایجاد پرهای رنگارنگ و موفقیت وی در جفت گیری می شود اما کیفیت بالاتر غذای والد ماده نیز، سبب توان بالاتر وی در زادآوری و پرورش زاده ها می شود. به عبارتی کیفیت غذا در موفقیت تولیدمثلی هر والد نسبت به دیگری نقش دارد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"هشت دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"877\":{\"correct_option_id\":6612,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; حالا به ترتیب هر کدام از گزاره های صورت سؤال را بررسی می کنیم: الف) در همه دنا (DNA)های حاصل از دور اول همانندسازی، فقط یکی از دو رشته دنا (DNA) واجد ایزوتوپ سنگین نیتروژن هستند. ب) در نیمی از دنا (DNA)های حاصل از دور دوم همانندسازی، هر دو رشته دنا (DNA) واجد ایزوتوپ سبک نیتروژن هستند. ج) در دنای باکتری های اولیه، در همه دنا (DNA)ها هر دو رشته دنا (DNA) واجد ایزوتوپ سنگین نیتروژن هستند. د) در هیچ کدام از مراحل آزمایش، امکان ندارد نیمی از دنا) (DNAهای موجود، نمونه های تهیه شده در دارای چگالی سنگین بوده و نواری در پایین لوله تشکیل دهند؛ چراکه همانندسازی نیمه حفاظتی است. ه) در زمان &#039;۲۰ ، همۀ دناهای حاصل، یک رشته با ایزوتوپ سنگین و یک رشته با ایزوتوپ سبک نیتروژن دارند. در زمان &#039;۴۰ هم همه دناها، حداقل یک رشته دنا با ایزوتوپ سبک را دارند. در زمان &#039;۲۰ ، فقط یک نوار در میانه لوله تشکیل می شود، اما در زمان &#039;۴۰ ، دو نوار تشکیل می شود؛ پس منظور زمان &#039;۴۰ است. و) همه دنا (DNA)های حاصل از دور اول همانندسازی، دارای چگالی متوسط بوده و نواری در میانۀ لوله تشکیل می دهند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"یک دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"894\":{\"correct_option_id\":6581,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; موارد &laquo;الف&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) پس از خروج رنای ناقل فاقد آمینواسید از جایگاهE ، براساس وجود یا عدم وجود کدون پایان در جایگاه ،A دو اتفاق می تواند رخ دهد. یا عامل آزاد کننده به جایگاه A وارد می شود (اگر کدون پایان در جایگاه A (باشد که در نهایت رنای ناقل و زنجیره پلی پپتیدی از جایگاه P ریبوزوم خارج می شوند؛ و اگر کدون رمزکننده یک آمینواسید در جایگاه A باشد، جایگاه A آماده پذیرش رنای ناقل بعدی می شود که پس از ورود و استقرار رنای ناقل مکمل به این جایگاه پیوند اشتراکی در جایگاه P ریبوزوم شکسته می شود تا پیوند پپتیدی بعدی تشکیل شود. ب) این مورد همواره رخ می دهد و مخصوص شرایط خاصی نیست! دقت کنید که تشکیل پیوند پپتیدی در جایگاه A رناتن اتفاق می افتد و کمی پس از تشکیل آن، همواره جابه جایی رناتن بر روی رنای پیک رخ میدهد که در نتیجه آن، رنای ناقل متصل به رشته پپتیدی به جایگاه P وارد میشود و رنای ناقل فاقد آمینواسید پس از ورود به جایگاه E رناتن، از آن خارج می گردد. ج) علاوه بر مرحله پایان ترجمه که پیوند بین رشته آمینواسیدی و tRNA شکسته می شود، طی طویل شدن هم این اتفاق می افتد، اما در پایان برخلاف طویل شدن tRNA ،فاقد آمینواسید به جایگاه E منتقل نمیشود بنابراین این جمله فقط درباره مرحله طویل شدن ترجمه صدق می کند یعنی در برخی شرایط رخ می دهد. د) کمی پیش از تشکیل پیوند پپتیدی در جایگاه ،A ریبوزوم پیوند اشتراکی بین آمینواسید و tRNA در جایگاه میانی ریبوزوم (جایگاه(P شکسته می شود. در واقع اگر قرار باشد پیوند پپتیدی تشکیل شود، همواره (نه در برخی شرایط!) باید رشته پپتیدی یا آمینواسید متصل به رنای ناقل در جایگاه ،P از این رنای ناقل جدا شود و سپس به جایگاه A منتقل گردد تا در نهایت به آمینواسید موجود در این جایگاه متصل شود. بنابراین، پیش از تشکیل هر پیوند پپتیدی حین ترجمه، باید پیوند اشتراکی بین رنای ناقل و بخش پپتیدی (یا آمینواسید) متصل به آن شکسته شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"917\":{\"correct_option_id\":6529,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; تمامی موارد نادرست هستند. بررسی همه موارد: الف) در گروهی از جهش های کوچک حذف و اضافه، حذف و یا اضافه شدن نوکلئوتیدها در توالی بین کدون آغاز و کدون پایان رخ می دهد و در نتیجه طول رنای پیک و در نتیجه، طول رشته پلی پپتیدی حاصل از آن، می تواند تغییر کند. در این شرایط توالی سه نوکلئوتیدی کدون پایان تغییر نخواهد کرد. ب) اگر جهش انجام شده به گونه ای باشد که شکل و عملکرد جایگاه فعال آنزیم را تغییر ندهد، بر فعالیت آنزیم نیز اثر چندانی نمی گذارد؛ بنابراین مدت زمان تبدیل پیش ماده به فراورده را به شدت تغییر نمی دهد. ج) همۀ این جهش ها، توالی نوکلئوتیدی مولکول رنای پیک حاصل از رونویسی ژن را تغییر می دهند. این گزینه به دلیل قید &laquo;فقط در برخی مواقع&raquo; غلط است. د) چرا ممکن است، اگر جهش رمز مربوط به کدون آغاز درDNA (ژن) را تغییر دهد، در این شرایط امکان دارد کدون آغاز در بخش های جلوتری تشکیل شود و پلی پپتیدی کوتاه تر ایجاد شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"چهار دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"989\":{\"correct_option_id\":4684,\"descriptive_answer\":{\"text\":\"گزینه&laquo;4&raquo; این مراحل شامل تبدیل اسید فسفاته به پیرووات هم می شود که طی آن، به ازای هر گلوکز ۴ مولکول \\\\(ATP\\\\) (طی قند کافت و در سطح پیش ماده) تولید می شود. \\\\(NADH\\\\) طی قند کافت در مادۀ زمینۀ سیتوپلاسم و طی اکسایش پیرووات در راکیزه تولید می شود. طی این واکنش ها، به ازای هر گلوکز ۲ مولکول \\\\(NADH\\\\) طی اکسایش پیرووات در راکیزه تولید می شود. بررسی سایر گزینه ها: 1) در طی مسیر واکنش های مطرح شده ۲ مولکول کربن دی اکسید درون میتوکندری (طی اکسایش پیرووات) تولید می شود و ۲ مولکول بنیان استیل به منظور تشکیل استیل کوآنزیم \\\\(A\\\\) ، مصرف می شود. (به ازای هر گلوکز، دو پیرووات مصرف و دو استیل کوآنزیم \\\\(A\\\\) تولید می شود.) 2) قند کافت در ماده زمینه ای سیتوپلاسم، دو مولکول پیرووات به عنوان محصولات نهایی قندکافت، تولید می شوند. دقت کنید که در نخستین مرحله چرخه کربس، ترکیب چهار کربنی با استیل کوآنزیم \\\\(A\\\\) ترکیب می شود؛ پس به ازای هر گلوکز، دوترکیب چهار کربنی مصرف می شود. چراکه به ازای هر گلوکز، چرخه کربس، دو بار رخ می دهد. 3) در طی مسیر واکنش های مذکور، ۲ مولکول استیل کوآنزیم \\\\(A\\\\) درون میتوکندری تولید شده و همچنین ۲ مولکول \\\\(NAD^+\\\\) نیز در طی واکنش های قند کافت مصرف شده و سبب تشکیل دو مولکول \\\\(NADH\\\\) شده اند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"پنج دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1012\":{\"correct_option_id\":4575,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; ابتدا دقت داشته باشید که یاخته های غلاف آوندی در ذرت، توانایی فتوسنتز دارند پس چرخۀ کالوین در آنها، رخ می دهد. مولکول های حامل الکترون در یک یاخته گیاهی فتوسنتز کننده (مثل غلاف آوندی گیاه ذرت) شامل \\\\(NADH\\\\)، \\\\(FADH_2\\\\)و \\\\(NADPH\\\\) هستند. اکسایش حامل های الکترون \\\\(NADH\\\\) و \\\\(FADH_2\\\\)، می تواند در زنجیره انتقال الکترون راکیزه! رخ دهد. \\\\(NADH\\\\) طی تخمیر هم می تواند اکسایش یابد. تخمیر الکلی و لاکتیکی هر دو در گیاهان رخ می دهد. اکسایش \\\\(NADPH\\\\) هم در چرخه کالوین رخ می دهد. طبق توضیحات صورت سؤال، تبدیل اسیدهای سه کربنی به قندهای سه کربنی در چرخه های کالوین، با اکسایش مولکول های \\\\(NADPH\\\\) همراه است. از طرفی، تبدیل مولکول پیرووات به لاکتات در تخمیر لاکتیکی، نیز واکنش دیگری است که در طی آن تبدیل یک ترکیب سه کربنی به نوعی ترکیب سه کربنی دیگر اتفاق میافتد و طی آن، اکسایش مولکول \\\\(NADH\\\\) رخ می دهد. در تمامی این واکنش ها، تعداد اتم های کربن در پیش ماده واکنش، ثابت باقی مانده است. سایر گزینه ها فقط در خصوص چرخۀ کالوین صادق هستند.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"شش دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1021\":{\"correct_option_id\":4534,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; موارد &laquo;الف&raquo; و &laquo;ب&raquo; نادرست هستند. الف) در هر دو دوره، از ریز جانداران برای تولید محصولات تخمیری (فرایندهای مستقل از اکسیژن) استفاده شد. ب) در زیست فناوری کلاسیک نیز امکان تولید مواد دارویی (پادزیست ها) فراهم شد. در دورۀ زیست فناوری نوین نیز ترکیبات دارویی مختلفی مانند انسولین تولید می شوند. ج) در زیست فناوری کلاسیک برای نخستین بار کشت ریز جانداران صورت گرفت. در دوره بعدی نیز کشت ریز جاندارانی مانند باکتری ها برای جداسازی یاخته های تراژنی (مثلا در طی مراحل مهندسی ژنتیک) انجام شد. د) تولید آنزیم ها (عوامل کاهش دهنده انرژی فعال سازی واکنش ها) در دوره زیست فناوری کلاسیک و نوین امکان پذیر بود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"هفت دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1111\":{\"correct_option_id\":34539,\"descriptive_answer\":{\"text\":\" گزینه ۴ درست است.\\r\\n\\r\\nدر حالت کلی چون برای هریک از پارامترهای a, b, c ، چهار مقدار وجود دارد، $4 \\\\times 4 \\\\times 4 = 64$ معادله درجه دوم مختلف می‌توان نوشت.\\r\\n\\r\\nحالا پیشامد مطلوب را به زبان ریاضی می‌نویسیم:\\r\\n\\r\\n$s = p - 2 \\\\Rightarrow \\\\frac{-b}{a} = \\\\frac{c}{a} - 2 \\\\xrightarrow{\\\\times a} -b = c - 2a \\\\Rightarrow b + c = 2a$\\r\\n\\r\\nبا چک کردن مقادیر صحیح از ۱ تا ۴ به جای a, b, c به حالات قابل قبول زیر می‌رسیم:\\r\\n\\r\\n\\\\begin{array}{|c|c|c|}\\r\\n\\r\\n\\\\hline\\r\\n\\r\\nb & c & a \\\\\\\\\\r\\n\\r\\n\\\\hline\\r\\n\\r\\n1 & 1 & 1 \\\\\\\\\\r\\n\\r\\n1 & 3 & 2 \\\\\\\\\\r\\n\\r\\n2 & 2 & 2 \\\\\\\\\\r\\n\\r\\n3 & 1 & 2 \\\\\\\\\\r\\n\\r\\n2 & 4 & 3 \\\\\\\\\\r\\n\\r\\n3 & 3 & 3 \\\\\\\\\\r\\n\\r\\n4 & 2 & 3 \\\\\\\\\\r\\n\\r\\n4 & 4 & 4 \\\\\\\\\\r\\n\\r\\n\\\\hline\\r\\n\\r\\n\\\\end{array}\\r\\n\\r\\nاما دقت کنید! برای آن‌که اساساً در معادله فوق، جمع و ضرب ریشه‌ها معنادار باشد، لازم است که شرط $\\\\Delta > 0$ هم بررسی شود:\\r\\n\\r\\n$b^2 - 4ac > 0 \\\\Rightarrow b^2 > 4ac$\\r\\n\\r\\nاگر مقادیر قابل قبول a, b, c در هریک از ۸ سطر جدول فوق را در نامساوی بالا چک کنید، فقط حالت $b = 3$, $c = 1$ و $a = 2$ صدق می‌کند و لذا فقط یک حالت از ۶۴ حالت قابل قبول است\\r\\n\\r\\n$P = \\\\frac{1}{64}$\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"احتمال دهم\",\"selected_option_id\":34537,\"is_answered\":true},\"1186\":{\"correct_option_id\":41635,\"descriptive_answer\":{\"text\":\"گزینه 4 درست است.\\r\\n\\r\\nبا استفاده از هم‌ارزی پرتوان داریم:\\r\\n\\r\\n$\\\\lim_{x \\\\to -\\\\infty} \\\\frac{a(x-1)^3 + b(2x+1)^3}{\\\\sqrt{x^4+1} \\\\cdot \\\\sqrt{4x^2} - x} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{a(x^3-3x^2+3x-1) + b(8x^3+12x^2+6x+1)}{|x^2| \\\\cdot |2x|} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{a(x^3-3x^2+3x-1) + b(8x^3+12x^2+6x+1)}{2x^2 \\\\cdot (-x)} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{a(x^3-3x^2+3x-1) + b(8x^3+12x^2+6x+1)}{-2x^3}$\\r\\n\\r\\nاز آن جایی که حاصل حد وقتی $x \\\\to -\\\\infty$ برود برابر عدد 9 است، پس جملات دارای توان 3 باید از صورت کسر حد حذف شوند. از طرفی درجه عبارت پرتوان مخرج برابر 3 است، پس درجه عبارت پرتوان صورت نیز باید برابر 3 باشد، پس داریم:\\r\\n\\r\\n$\\\\lim_{x \\\\to -\\\\infty} \\\\frac{a(x^3-3x^2) + b(8x^3+12x^2)}{-2x^3} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{(a+8b)x^3 + (12b-3a)x^2}{-2x^3}$\\r\\n\\r\\n$\\\\Rightarrow \\\\begin{cases} a+8b = 0 \\\\\\\\ \\\\lim_{x \\\\to -\\\\infty} \\\\frac{(12b-3a)x^2}{-2x^3} = 9 \\\\end{cases}$ (این بخش با توجه به تصویر اصلاح می‌شود: مخرج در واقع درجه 2 است)\\r\\n\\r\\nبا اصلاح بر اساس تصویر:\\r\\n\\r\\n$\\\\lim_{x \\\\to -\\\\infty} \\\\frac{(a+8b)x^3+(12b-3a)x^2}{2x^2} = 9 \\\\Rightarrow 12b-3a = 18$\\r\\n\\r\\n$\\\\Rightarrow \\\\begin{cases} a+8b = 0 \\\\\\\\ -3a+12b = 18 \\\\end{cases} \\\\Rightarrow \\\\begin{cases} a = -4 \\\\\\\\ b = \\\\frac{1}{2} \\\\end{cases}$\\r\\n\\r\\nحال حد دوم را محاسبه می‌کنیم:\\r\\n\\r\\n$\\\\lim_{x \\\\to -\\\\infty} \\\\frac{x + \\\\sqrt{a^2x^2+1}}{bx} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{x + \\\\sqrt{16x^2+1}}{\\\\frac{1}{2}x} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{x + 4|x|}{\\\\frac{1}{2}x} = \\\\lim_{x \\\\to -\\\\infty} \\\\frac{x - 4x}{\\\\frac{1}{2}x} = \\\\frac{-3x}{\\\\frac{1}{2}x} = -6$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"حد و پيوستگي دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1244\":{\"correct_option_id\":42177,\"descriptive_answer\":{\"text\":\"گزینه ۱ درست است.\\r\\n\\r\\nهر ۴ نقطه داخل براکت را صحیح می‌کنند، پس پاسخ نقطه‌ای است که نقطه مینیمم نسبی تابع $g$ باشد:\\r\\n\\r\\n$g = \\\\frac{2x^2 + 2}{x} \\\\Rightarrow g\' = \\\\frac{4x^2 - (2x^2 + 2)}{x^2} = \\\\frac{2x^2 - 2}{x^2} = 0 \\\\Rightarrow x = \\\\pm 1$\\r\\n\\r\\nبا توجه به جدول تعیین علامت، $x = 1$ طول نقطه مینیمم نسبی $g$ است.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"حد و پيوستگي يازدهم\",\"selected_option_id\":42178,\"is_answered\":true},\"1391\":{\"correct_option_id\":43168,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 1\\r\\n\\r\\nP(A)=1-(4/6×4/6)=5/9$$\\r\\n\\r\\nP(B)=1/4$$\\r\\n\\r\\nP(A∪B)=5/9+1/4-(5/9×1/4)=29/36$$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"احتمال يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1806\":{\"correct_option_id\":47907,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 4\\r\\n\\r\\nچون $A(2, 3)$ روی نمودار f است، پس $f(2) = 3$ به همین جهت وقتی $A\' \\\\begin{vmatrix} -1 \\\\\\\\ -4 \\\\end{vmatrix}$ روی نمودار $y = \\\\alpha - 2f(\\\\beta - x)$ است پس:\\r\\n\\r\\n$-4 = \\\\alpha - 2f(\\\\beta + 1) \\\\Rightarrow f(\\\\beta + 1) = \\\\frac{\\\\alpha + 4}{2}$\\r\\n\\r\\n$\\\\begin{cases} \\\\beta + 1 = 2 \\\\Rightarrow \\\\beta = 1 \\\\\\\\ \\\\frac{\\\\alpha + 4}{2} = 3 \\\\Rightarrow \\\\alpha = 2 \\\\end{cases} \\\\Rightarrow \\\\beta - \\\\alpha = -1$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"تابع دهم\",\"selected_option_id\":null,\"is_answered\":false},\"1874\":{\"correct_option_id\":49470,\"descriptive_answer\":{\"text\":\"گام اول: عبارت زیر رادیکال سمت چپ، مربع کامل است:\\r\\n\\r\\n$12 − 6√3 = 9 + 3 − 2×3×√3 = (3 − √3)^2 ⇒ √(12 − 6√3)=√((3 − √3)^2)=|3 − √3|=3 − √3$\\r\\n\\r\\nگام دوم: مخرج کسر سمت راست را گویا می‌کنیم:\\r\\n\\r\\n$\\\\frac{1−3√3}{4+√3}×\\\\frac{4−√3}{4−√3}=\\\\frac{4−√3−12√3+9}{16−3}=\\\\frac{13−13√3}{13}=1−√3$\\r\\n\\r\\n$A=√(12−6√3)+\\\\frac{1−3√3}{4+√3}=3−√3+1−√3=4−2√3$\\r\\n\\r\\nگام سوم، حالا داریم:\\r\\n\\r\\n$A=4−2√3=3+1−2√3×1=(√3−1)^2$\\r\\n\\r\\nگام چهارم: با کمی دقت متوجه می‌شویم که $A$ مربع کامل است.\\r\\n\\r\\nگام پنجم: ریشه‌های دوم عدد $A$ برابر $±√((√3−1)^2)$ می‌شوند که واضح است ریشه دوم بزرگتر مقدار مثبت یعنی $√3−1$ برابر می‌شود.\\r\\n\\r\\nگام ششم: عبارت $√3−1$ در بین گزینه‌ها نیست! این‌جا دو روش داریم:\\r\\n\\r\\nامتحان گزینه‌ها:\\r\\n\\r\\n$1$ و $2$ که واضح با $√3−1$ برابر نیستند. سراغ $3$ و $4$ می‌رویم؛ با گویا کردن مخرج کسر داریم:\\r\\n\\r\\n$3)\\\\;\\\\frac{2}{√3+1}×\\\\frac{√3−1}{√3−1}=\\\\frac{2(√3−1)}{3−1}=√3−1\\\\;✓$\\r\\n\\r\\n$4)\\\\;\\\\frac{1}{√3+1}×\\\\frac{√3−1}{√3−1}=\\\\frac{√3−1}{3−1}=\\\\frac{√3−1}{2}\\\\;×$\\r\\n\\r\\nبنابراین جواب $3$ می‌شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"توان هاي گويا و عبارت هاي جبري\",\"selected_option_id\":null,\"is_answered\":false},\"1912\":{\"correct_option_id\":49633,\"descriptive_answer\":{\"text\":\"از طرفین تابع داده شده مشتق می‌گیریم و به جای x عدد 1 قرار می‌دهیم:\\r\\n\\r\\n$g\'(x)f\'(g(x))=\\\\frac{1}{\\\\sqrt{x}}+3a \\\\xrightarrow{x=1} g\'(1)f\'(g(1))=1+3a$\\r\\n\\r\\n$\\\\xrightarrow{g(1)=4} g\'(1)f\'(4)=1+3a \\\\;\\\\;\\\\; (1)$\\r\\n\\r\\nشیب خط مماس بر g در نقطه (1,4) برابر $g\'(1)$ و شیب خط مماس بر $f(x)$ در نقطه‌ای به طول 4 برابر $f\'(4)$ است. چون این دو خط مماس بر هم عمودند، پس:\\r\\n\\r\\n$g\'(1)f\'(4)=-1 \\\\;\\\\;\\\\; (1) \\\\Rightarrow 1+3a=-1 \\\\Rightarrow a=-\\\\frac{2}{3}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مشتق\",\"selected_option_id\":null,\"is_answered\":false},\"1982\":{\"correct_option_id\":49720,\"descriptive_answer\":{\"text\":\"نکته: $Sin^2 \\\\theta + Cos^2 \\\\theta = 1$\\r\\n\\r\\nنکته: $a^2 - b^2 = (a-b)(a+b)$\\r\\n\\r\\n$Cos^4 \\\\theta - Sin^4 \\\\theta = (Cos^2 \\\\theta + Sin^2 \\\\theta)(Cos^2 \\\\theta - Sin^2 \\\\theta) \\\\Rightarrow Cos^4 \\\\theta - Sin^4 \\\\theta = Cos^2 \\\\theta - Sin^2 \\\\theta$\\r\\n\\r\\n$\\\\Rightarrow Cos^4 \\\\theta + Sin^2 \\\\theta = Cos^2 \\\\theta + Sin^4 \\\\theta \\\\Rightarrow A = \\\\frac{Cos^4 \\\\theta + Sin^2 \\\\theta}{Sin^4 \\\\theta + Cos^2 \\\\theta} = 1$\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دهم\",\"selected_option_id\":49723,\"is_answered\":true},\"2033\":{\"correct_option_id\":49702,\"descriptive_answer\":{\"text\":\"گزینه 3 صحیح است.\\r\\n\\r\\nگام اول: اول فرض می‌کنیم مجموعه A، n عضو دارد. تعداد زیرمجموعه‌های k عضوی و 4 عضوی A برابرند، پس:\\r\\n\\r\\n$\\\\binom{n}{4} = \\\\binom{n}{k}$\\r\\n\\r\\nگام دوم: حالا طبق نکته، از تساوی بالا دو نتیجه می‌گیریم که $k=4$ است و یا $ k+4 = n$. طبق گفته سؤال $k \\\\neq 4$ است، پس $k+4 = n$ می‌شود.\\r\\n\\r\\n$ k+4=n \\\\Rightarrow k = n - 4$\\r\\n\\r\\nگام سوم: تعداد زیرمجموعه‌های A برابر $2^{n}$ تا است. اگر به مجموعه A، k عضو اضافه کنیم، تعداد زیرمجموعه‌های آن $2^{n+k}$ می‌شود، پس:\\r\\n\\r\\n$2^{n} + 896 = 2^{n+k}$\\r\\n\\r\\n$2^{n+k} – 2^{n} = 896 \\\\Rightarrow 2^{n}(2^{k} - 1) = 128 \\\\times 7$\\r\\n\\r\\n$\\\\Rightarrow 2^{n}(2^{k} - 1) = 2^{7} \\\\times (2^{3} - 1)\\\\Rightarrow n = 7 , k = 3$\\r\\n\\r\\nگام چهارم: در آخر باید تعداد زیرمجموعه‌های $k-1 = 2$ عضوی مجموعه اولیه A را محاسبه کنیم:\\r\\n\\r\\n$\\\\binom{n}{k-1} = \\\\binom{7}{2} = 21$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مجموعه ها\",\"selected_option_id\":null,\"is_answered\":false},\"2051\":{\"correct_option_id\":45611,\"descriptive_answer\":{\"text\":\"۱۷-گزینه ۴ درست است.\\r\\n\\r\\nشکل بیستم شامل ۲۰ مربع است که به تعداد $۱+۲+\\\\dots+۱۹$ مربع در شکل‌های قبلی حضور دارند، پس:\\r\\n\\r\\n$۱+۲+\\\\dots+۱۹ = \\\\frac{۱۹ \\\\times ۲۰}{۲} = ۱۹۰$\\r\\n\\r\\nبنابراین اعداد حک شده در شکل بیستم از ۱۹۱ تا ۲۱۰ می‌باشند، پس:\\r\\n\\r\\n$۱۹۱+۱۹۲+\\\\dots+۲۱۰ = (۱+۲+\\\\dots+۲۱۰) - (۱+۲+\\\\dots+۱۹۰) =$\\r\\n\\r\\n$\\\\frac{۲۱۰ \\\\times ۲۱۱}{۲} - \\\\frac{۱۹۰ \\\\times ۱۹۱}{۲} = ۱۰۵ \\\\times ۲۱۱ - ۹۵ \\\\times ۱۹۱ = ۴۰۱۰$\\r\\n\\r\\nتوجه کنید که رقم یکان اعداد $۱۰۵ \\\\times ۲۱۱$ و $۹۵ \\\\times ۱۹۱$ برابر ۵ می‌باشد، پس رقم یکان تفاضل آن‌ها صفر است و در گزینه‌ها فقط رقم یکان ۴۰۱۰ برابر صفر می‌باشد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"الگو و دنباله\",\"selected_option_id\":null,\"is_answered\":false},\"2224\":{\"correct_option_id\":62080,\"descriptive_answer\":{\"text\":\"گام اول: عدد مورد نظر بايد هم به ۵ و هم به ۳ بخش‌پذير باشد، پس بايد مضرب ۱۵ شود. بنابراين ابتدا فرض می‌کنيم عدد ده‌رقمی مورد نظر به صورت 5abcddcba5 باشد که هم از دو طرف يکسان خوانده می‌شود و هم دارای يکان ۵ است تا بر ۵ بخش‌پذير باشد. از طرفی برای اين‌که به ۳ بخش‌پذير باشد، بايد مجموع ارقام آن مضرب ۳ باشد. پس:\\r\\n\\r\\nمجموع ارقام عدد ده‌رقمی $10+2a+2b+2c+2d=3k$ در نتیجه: $2(5+a+b+c+d)=3k$\\r\\n\\r\\nگام دوم: از رابطهٔ بالا نتيجه می‌گيريم که $5+a+b+c+d$بايد مضرب ۳ باشد. اگر $a=b=c=d=7$ باشد، حداکثر عبارت $a+b+c+d+d=28$ و اگر $a=b=c=d=5$ باشد حداقل عبارت $a+b+c+d=20$ است، پس: $20 \\\\le a + b + c + d \\\\leq 28$ است. بنابراین برای این که حاصل $5+a+b+c+d$ بر سه بخش پذیر باشد، حاصل $a+b+c+d$ فقط می تواند مقادیر 22 و 28 را بپذیرد؛ یعنی:\\r\\n\\r\\n$a+b+c+d+5=27=3k’ \\\\rightarrow a+b+c+d=22$\\r\\n\\r\\n یا\\r\\n\\r\\n$a+b+c+d+5=33=3k’ \\\\rightarrow a+b+c+d=28$\\r\\n\\r\\nگام سوم: در حالتی که $a+b+c+d=22$، باید مجموعهٔ $\\\\{ a,b,c,d \\\\}$ شامل سه عدد ۵ و يک عدد ۷ باشد؛ يعنی $\\\\{5,5,5,7\\\\}$، اما در حالی که $a+b+c+d=28$ باشد مجموعۀ $\\\\{a,b,c,d\\\\}$ باید شامل 4 عدد 7 باشد؛ یعنی: $\\\\{7,7,7,7\\\\}$.\\r\\n\\r\\nگام چهارم: بنابراین برای نوشتن عدد ده رقمی مورد نظر باید از مجموعۀ $\\\\{a,b,c,d\\\\}$ یک رقم 7 یا 4 رقم ۷ انتخاب کرد؛پس تعداد ارقام مورد نظر برابر است با:\\r\\n\\r\\n$\\\\binom{4}{1}+\\\\binom{4}{4}=4+1=5$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"شمارش بدون شمردن\",\"selected_option_id\":null,\"is_answered\":false},\"2306\":{\"correct_option_id\":51695,\"descriptive_answer\":{\"text\":\"۱ 7 مرکز دایره $W(2, 3)$ و شعاع آن $4$ است.\\r\\n\\r\\n\\r\\n\\r\\nدو خط $y=1$ و $y=5$ نسبت به مرکز دایره متقارن هستند پس چهارضلعی ABCD مستطیل است.\\r\\n\\r\\n\\r\\n\\r\\n$|AD|=|BC|=5-1=4$\\r\\n\\r\\n\\r\\n\\r\\n$(x-2)^2+(y-3)^2=16 \\\\xrightarrow{y=1} (x-2)^2=12$\\r\\n\\r\\n\\r\\n\\r\\n$\\\\Rightarrow x-2=\\\\pm\\\\sqrt{12} \\\\Rightarrow x=2\\\\pm\\\\sqrt{12}$\\r\\n\\r\\n\\r\\n\\r\\n$|AB|=x_B-x_A=(2+\\\\sqrt{12})-(2-\\\\sqrt{12})=2\\\\sqrt{12}=4\\\\sqrt{3}$\\r\\n\\r\\n\\r\\n\\r\\n$S_{ABCD}=4\\\\times4\\\\sqrt{3}=16\\\\sqrt{3}$\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"هندسه دوازدهم\",\"selected_option_id\":51696,\"is_answered\":true},\"2854\":{\"correct_option_id\":75097,\"descriptive_answer\":{\"text\":\". گزینه 2 درست است.\\r\\n\\r\\nاگر نمونه زیر مجموعه جامعه آماری باشد ممکن است تمام افراد تحت مطالعه قرار نگرفته باشد سرشماری انجام نشده است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"آمار\",\"selected_option_id\":null,\"is_answered\":false},\"3576\":{\"correct_option_id\":17049,\"descriptive_answer\":{\"text\":\"48 - پاسخ: گزینه 2\\r\\n\\r\\nمشخصات سؤال: دشوار * ریاضی 3 (فصل 7، درس 1)\\r\\n\\r\\nابتدا به سراغ ظرف اول رفته و مهره ای از آن به ظرف دوم انتقال می دهیم.\\r\\n\\r\\nظرف اول $\\\\rightarrow$ $6/9$ ظرف دوم - سفید $\\\\rightarrow$ $5/10$ سفید ، $5/10$ سیاه\\r\\n\\r\\nظرف اول $\\\\rightarrow$ $3/9$ ظرف دوم - سیاه $\\\\rightarrow$ $4/10$ سفید ، $6/10$ سیاه\\r\\n\\r\\n$P(A) = \\\\text{احتمال خروج لااقل یک مهره سفید} = (1 - \\\\frac{\\\\binom{5}{2}}{\\\\binom{10}{2}}) \\\\times \\\\frac{6}{9} + (1 - \\\\frac{\\\\binom{6}{2}}{\\\\binom{10}{2}}) \\\\times \\\\frac{3}{9}$\\r\\n\\r\\n$P(A) = \\\\frac{2}{3} \\\\times (1 - \\\\frac{10}{45}) + \\\\frac{1}{3} \\\\times (1 - \\\\frac{15}{45}) = \\\\frac{2}{3} \\\\times \\\\frac{7}{9} + \\\\frac{1}{3} \\\\times \\\\frac{2}{3} = \\\\frac{14+6}{27} = \\\\frac{20}{27}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"احتمال دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4216\":{\"correct_option_id\":72828,\"descriptive_answer\":{\"text\":\"راه اول:\\r\\n\\r\\nگام اول، معادله را استاندارد می‌نویسیم:\\r\\n\\r\\n$(x - 1)^2 + a(x - 3) - 4 = 0 \\\\Rightarrow x^2 - 2x + 1 + ax - 3a - 4 = 0 \\\\Rightarrow 1x^2 + (a - 2)x + (-3a - 3) = 0$\\r\\n\\r\\n$A$ $B$ $C$\\r\\n\\r\\nگام دوم، S و P معادله بالا را حساب می‌کنیم:\\r\\n\\r\\n$S = -B / A = -a + 2$     $P = C / A = -3a - 3$\\r\\n\\r\\nگام سوم، چون یکی از ریشه‌ها 2 برابر دیگری است، پس ریشه‌های معادله را α و 2α می‌گیریم.\\r\\n\\r\\nمجموع α و 2α همان S می‌شود:\\r\\n\\r\\n$S = α + 2α \\\\Rightarrow -a + 2 = 3α (1)$\\r\\n\\r\\nضرب α و 2α همان P می‌شود:\\r\\n\\r\\n$P = α \\\\cdot 2α \\\\Rightarrow -3a - 3 = 2α^2 (2)$\\r\\n\\r\\nگام چهارم، از رابطه (1)، α^2 را حساب می‌کنیم:\\r\\n\\r\\n$-a + 2 = 3α \\\\Rightarrow (-a + 2) / 3 = α \\\\Rightarrow α^2 = (a - 2)^2 / 9$\\r\\n\\r\\nاز رابطه (2)، α^2 را تنها می‌کنیم:\\r\\n\\r\\n$-3a - 3 = 2α^2 \\\\Rightarrow α^2 = (-3a - 3) / 2$\\r\\n\\r\\nگام پنجم، دو مقدار به دست آمده برای α^2 را برابر قرار می‌دهیم:\\r\\n\\r\\n$(a - 2)^2 / 9 = (-3a - 3) / 2 \\\\Rightarrow (a^2 - 4a + 4) / 9 = (-3a - 3) / 2 \\\\Rightarrow 2a^2 - 8a + 8 = -27a - 27 \\\\Rightarrow 2a^2 + 19a + 35 = 0 (Δ = 361 - 280 = 81)$\\r\\n\\r\\nگام ششم، دلتای معادله بالا مثبت است، پس دو مقدار حقیقی برای a وجود دارد. مجموع مقادیر a برابر با S معادله بالاست که می‌شود -19 / 2 یعنی -9/5.\\r\\n\\r\\nراه دوم (تیزبازی!):\\r\\n\\r\\nگام اول، اگر کمی (یا بیشتر!) دقت کنید، می‌فهمید x = 3 ریشه معادله $(x - 1)^2 + a(x - 3) - 4 = 0$ است.\\r\\n\\r\\nگام دوم، چون یکی از ریشه‌ها 2 برابر ریشه دیگر است، پس ریشه دوم یا 6 است یا 3 / 2.\\r\\n\\r\\nگام سوم، x = 6 و x = 3 / 2 را در معادله قرار می‌دهیم:\\r\\n\\r\\n$(x - 1)^2 + a(x - 3) - 4 = 0 \\\\xrightarrow{x=6} 25 + 3a - 4 = 0 \\\\Rightarrow a = -7$\\r\\n\\r\\n$(x - 1)^2 + a(x - 3) - 4 = 0 \\\\xrightarrow{x=3/2} 1/4 - 3/2a - 4 = 0 \\\\xrightarrow{\\\\times 4} 1 - 6a - 16 = 0 \\\\Rightarrow 6a = -15 \\\\Rightarrow a = -2/5$\\r\\n\\r\\nگام چهارم، پس مجموع مقادیر a برابر با -9/5 = (-7) + (-2/5) است.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"معادله و تابع درجه دوم\",\"selected_option_id\":null,\"is_answered\":false},\"4224\":{\"correct_option_id\":72800,\"descriptive_answer\":{\"text\":\"راه اول:\\r\\n\\r\\nگزینه‌ها را امتحان می‌کنیم. به ازای هر کدام که حاصل عبارت سمت چپ نامعادله $x|2x - 1| < 1$ برابر با عدد سمت راست (یعنی 1) شد، جواب است:\\r\\n\\r\\n1) $a = 1 \\\\Rightarrow 1|2(1) - 1| = 1 \\\\checkmark$\\r\\n\\r\\n2) $a = 1/2 \\\\Rightarrow 1/2|0| = 0 \\\\times$\\r\\n\\r\\n3) $a = -1/2 \\\\Rightarrow -1/2|2(-1/2) - 1| = -1 \\\\times$\\r\\n\\r\\n4) $a = -1 \\\\Rightarrow -1|2(-1) - 1| = -3 \\\\times$\\r\\n\\r\\nراه دوم:\\r\\n\\r\\nگام اول، ریشه عبارت داخل قدرمطلق را حساب می‌کنیم:\\r\\n\\r\\n$2x - 1 = 0 \\\\Rightarrow x = 1/2$\\r\\n\\r\\nگام دوم، بعد از حذف قدرمطلق، در دو محدوده $x \\\\geq 1/2$ و $x < 1/2$، نامعادله را حل می‌کنیم:\\r\\n\\r\\n$x|2x - 1| < 1 \\\\xrightarrow{x \\\\geq 1/2} x(2x - 1) < 1 \\\\Rightarrow 2x^2 - x - 1 < 0 \\\\xrightarrow{بین ریشه‌ها a+b+c=0} -1/2 < x < 1 \\\\xrightarrow{\\\\cap(x \\\\geq 1/2)} 1/2 \\\\leq x < 1$\\r\\n\\r\\n$x|2x - 1| < 1 \\\\xrightarrow{x < 1/2} x(-2x + 1) < 1 \\\\Rightarrow -2x^2 + x < 1 \\\\Rightarrow 2x^2 - x + 1 > 0 \\\\xrightarrow{\\\\Delta < 0, a > 0} x \\\\in \\\\mathbb{R} \\\\xrightarrow{\\\\cap(x < 1/2)} x < 1/2$\\r\\n\\r\\nگام سوم، بین دو محدوده به دست آمده، اجتماع می‌گیریم:\\r\\n\\r\\nجواب $= [1/2, 1) \\\\cup (-\\\\infty, 1/2) = (-\\\\infty, 1)$\\r\\n\\r\\nپس $a = 1$ است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"قدرمطلق و جزءصحيح\",\"selected_option_id\":null,\"is_answered\":false},\"4233\":{\"correct_option_id\":72763,\"descriptive_answer\":{\"text\":\"نکته: $(gof)(x) = g(f(x))$ ابتدا تابع $fog$ را محاسبه می‌کنیم: $(fog)(-2) = f(g(-2)) = f(-3) = -4$ , $(fog)(3) = f(g(3)) = f(1) = -2$ $(fog)(2) = f(g(2)) = f(-1) =$ تعریف‌نشده , $(fog)(5) = f(g(5)) = f(2) = 5$ $(fog)(7) = f(g(7)) = f(3) = -4$ $fog = \\\\{(-2, -4), (3, -2), (5, 5), (7, -4)\\\\}$ پس داریم: اکنون به محاسبه تابع خواسته شده می‌پردازیم: $((fog)of)(1) = (fog)(f(1)) = (fog)(-2) = -4$ $((fog)of)(3) = (fog)(f(3)) = (fog)(-4) =$ تعریف‌نشده $((fog)of)(-2) = (fog)(f(-2)) = (fog)(2) =$ تعریف‌نشده $((fog)of)(-3) = (fog)(f(-3)) = (fog)(-4) =$ تعریف‌نشده $((fog)of)(2) = (fog)(f(2)) = (fog)(5) = 5$ پس $\\\\{(1, -4), (2, 5)\\\\} = (fog)of$ که حاصل‌ضرب اعضای برد آن برابر است با: $-4 \\\\times 5 = -20$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"تابع دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4796\":{\"correct_option_id\":70365,\"descriptive_answer\":{\"text\":\"56. گزینه 1 \\r\\n\\r\\nمعادله‌ی داده شده را به صورت زیر مرتب می‌کنیم:\\r\\n\\r\\n$x^3+3x^2+3x+1 = \\\\sqrt{x+1} \\\\Rightarrow (x+1)^3 = \\\\sqrt{x+1}$\\r\\n\\r\\nحال نمودار دو تابع $y = (x+1)^3$ و $y = \\\\sqrt{x+1}$ را در یک دستگاه رسم می‌کنیم:\\r\\n\\r\\nملاحظه می‌کنید که معادله مورد نظر یک ریشه $x = -1$ و یک ریشه صفر دارد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"معادله و نامعادله يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4922\":{\"correct_option_id\":49881,\"descriptive_answer\":{\"text\":\" گزینه 2\\r\\n\\r\\nتابع $tan x$ در نقاط $x = k\\\\pi + \\\\frac{\\\\pi}{2}$، $k \\\\in \\\\mathbb{Z}$، تعریف نمی‌شود.\\r\\n\\r\\n$ 0 \\\\le x \\\\le 36 \\\\Rightarrow 0 \\\\le \\\\sqrt{x} \\\\le 6$ (1)\\r\\n\\r\\n$\\\\pi\\\\sqrt{x} = k\\\\pi + \\\\frac{\\\\pi}{2} \\\\Rightarrow \\\\sqrt{x} = k + \\\\frac{1}{2}$ (2)\\r\\n\\r\\nاز (1) و (2) نتیجه می‌گیریم که:\\r\\n\\r\\n$ 0 \\\\le k + \\\\frac{1}{2} \\\\le 6$\\r\\n\\r\\n$\\\\Rightarrow -\\\\frac{1}{2} \\\\le k \\\\le \\\\frac{11}{2} \\\\xrightarrow{k \\\\in \\\\mathbb{Z}} k \\\\in \\\\{0, 1, 2, 3, 4, 5\\\\}$\\r\\n\\r\\nپس 6 عضو در دامنه تابع f وجود ندارد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"مثلثات دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4985\":{\"correct_option_id\":23104,\"descriptive_answer\":{\"text\":\"می‌دانیم $(√7+1)(√7−1)=(√7)^2−1=6$ پس داریم:  \\r\\n\\r\\n$√7−1=\\\\frac{1}{√7+1}$  \\r\\n\\r\\nهمچنین با توجه به اتحاد زوج‌دم‌هم‌عددی داریم:  \\r\\n\\r\\n$(√7+1)^2+x(√7+1)+√7x+1+2$  \\r\\n\\r\\n$=√7x+√7+x+7+√7+x+1+2$  \\r\\n\\r\\nحال این عبارت را در نامعادله‌ سؤال جایگزین می‌کنیم:  \\r\\n\\r\\n$((√7+1)^2+x+x+2+x+3+x+2)^2$  \\r\\n\\r\\n$⇒(√7+1)^2+x+x+x+x+2+x+3$  \\r\\n\\r\\n$<(√7+1)^6$  \\r\\n\\r\\nچون $(√7+1)>1$ است داریم:  \\r\\n\\r\\n$x^2−7x+2⇒x^2−7x−2⇔x>(√7+1)<0$  \\r\\n\\r\\n$a=b=√7$  \\r\\n\\r\\n$b+a=2+(√7−1)=c$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"معادله و نامعادله دهم\",\"selected_option_id\":null,\"is_answered\":false},\"5092\":{\"correct_option_id\":25298,\"descriptive_answer\":{\"text\":\"فاصله‌ی نقطه‌ی فرضی $M(\\\\alpha, \\\\sqrt{2\\\\alpha + 9})$ روی منحنی از نقطه‌ی $A(4, 0)$ باید مینیمم شود، بنابراین:\\r\\n\\r\\n$AM = d = \\\\sqrt{(\\\\alpha - 4)^2 + (\\\\sqrt{2\\\\alpha + 9} - 0)^2}$\\r\\n\\r\\n$\\\\Rightarrow d(\\\\alpha) = \\\\sqrt{\\\\alpha^2 - 8\\\\alpha + 16 + 2\\\\alpha + 9} = \\\\sqrt{\\\\alpha^2 - 6\\\\alpha + 25}$\\r\\n\\r\\nبا استفاده از اتحاد مربع دوجمله‌ای، خواهیم داشت:\\r\\n\\r\\n$d = \\\\sqrt{(\\\\alpha - 3)^2 + 16}$\\r\\n\\r\\nمینیمم زمانی اتفاق می‌افتد که $(\\\\alpha - 3)^2 = 0$ و در نتیجه مینیمم عبارت برابر $d_{min} = \\\\sqrt{16} = 4$ خواهد بود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"كاربرد مشتق\",\"selected_option_id\":null,\"is_answered\":false},\"5228\":{\"correct_option_id\":32233,\"descriptive_answer\":{\"text\":\"گزینه «4»\\r\\n\\r\\n$25/2 g CxHy = 0/3 mol CxHy × mg CxHy / 1 mol CxHy$\\r\\n\\r\\n$⇒ m = 84 g.mol-1$\\r\\n\\r\\n$CxHy ⇒ \\\\{ 12x + y = 84$\\r\\n\\r\\n$\\\\{ 12x / y = 6 ⇒ x = 6 , y = 12 ⇒ C6H12$\\r\\n\\r\\nبا توجه به فرمول عمومی آلکن ها و سیکلو آلکان ها ($CnH2n$) این هیدروکربن می تواند سیر شده یا سیر نشده باشد؛ بنابراین هیدروکربن با ساختار می تواند همانند ترکیب داده شده دارای فرمول مولکولی $C6H12$ باشد.\\r\\n\\r\\nبررسی گزینه های نادرست:\\r\\n\\r\\n1) تفاوت جرم $C4H10 = 58 g.mol-1 , C6H12 = 84 g.mol-1$ مولی آن ها برابر جرم مولی $C2H2$ است. $C2H2$ ساده ترین آلکین است.\\r\\n\\r\\n2) اگر یک سیکلوآلکان باشد، با برم مایع واکنش نمی دهد.\\r\\n\\r\\n3) اگر آن را سیکلو آلکان در نظر بگیریم دارای 6 پیوند $C-C$ خواهد بود، اما اگر یک آلکن باشد، 4 پیوند $C-C$ خواهد داشت.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک یازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"5320\":{\"correct_option_id\":32598,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه $1$ عبارت‌های اول و دوم درست‌اند. پاسخ تشریحی: بررسی عبارت‌های نادرست: عبارت سوم: در هنگام تعادل، سرعت واکنش‌های رفت و برگشت با هم برابر است، نه الزاماً سرعت مصرف واکنش‌دهنده‌(ها) و فراورده(ها). با هم سرعت واکنش‌های رفت یا برگشت از تقسیم سرعت تولید یا مصرف مواد شرکت‌کننده در واکنش بر ضریب استوکیومتری آن‌ها به دست می‌آید. در واکنش تعادلی $aA(g) ⇌ bB(g)$، ضرایب استوکیومتری مواد با هم برابر نیست؛ بنابراین برای این واکنش در هنگام تعادل، داریم: \\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n  عبارت چهارم: در هنگام تعادل سرعت واکنش‌های رفت و برگشت با هم برابر است و به همین دلیل خواص ظاهری (ماکروسکوپی) سامانه از جمله غلظت، رنگ و ... ثابت می‌ماند.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل یک دوازدهم\",\"selected_option_id\":32599,\"is_answered\":true},\"5487\":{\"correct_option_id\":32927,\"descriptive_answer\":{\"text\":\"بررسی گزینه‌های نادرست:\\r\\n\\r\\nگزینه «1»: پاسخ به پرسش «هستی چگونه پدید آمده است؟» که پرسشی بنیادی است در قلمرو علوم تجربی نمی‌گنجد.\\r\\n\\r\\nگزینه «2»: برخی دانشمندان بر این باورند که سرآغاز کیهان با انفجاری مهیب همراه بوده که طی آن انرژی عظیمی آزاد شده است.\\r\\n\\r\\nگزینه «4»: پس از پدید آمدن ذرات زیراتمی، با گذشت زمان و کاهش دما، مجموعه‌های گازی به نام سحابی ایجاد شدند.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"6033\":{\"correct_option_id\":29980,\"descriptive_answer\":{\"text\":\"ابتدا مقدار $CO_2$ تولید شده بر حسب کیلوگرم توسط این دو منبع انرژی را در یک سال (۱۲ ماه) بدست می‌آوریم. بر این اساس، داریم:\\r\\n\\r\\n\\r\\n\\r\\nگاز طبیعی : $? kg CO_2 = 1 year \\\\times \\\\frac{12 month}{1 year} \\\\times \\\\frac{2640 kwh}{1 month} \\\\times \\\\frac{0/35 kg CO_2}{1 kwh} = 11088 kg CO_2$\\r\\n\\r\\n\\r\\n\\r\\nانرژی حاصل از خورشید : $? kg CO_2 = 1 year \\\\times \\\\frac{12 month}{1 year} \\\\times \\\\frac{2640 kwh}{1 month} \\\\times \\\\frac{0/05 kg CO_2}{1 kwh} = 1584 kg CO_2$\\r\\n\\r\\n\\r\\n\\r\\nبنابراین مقدار $CO_2$ تولید شده در یک سال در صورت استفاده از گاز طبیعی برابر با ۱۱۰۸۸ کیلوگرم است. برای حل قسمت اول سوال، کافی است که مقدار گاز $CO_2$ تولید شده در یک سال را بر مقدار $CO_2$ که یک درخت به طور متوسط در یک سال مصرف می‌کند، تقسیم کنیم؛ پس داریم:\\r\\n\\r\\n\\r\\n\\r\\nتعداد درخت $= \\\\frac{11088}{44} = 252$\\r\\n\\r\\n\\r\\n\\r\\nبنابراین حداقل ۲۵۲ درخت مورد نیاز است. برای حل قسمت دوم سوال، درصد تغییر مقدار $CO_2$ تولید شده در یک سال را در صورت استفاده از منبع خورشیدی به جای منبع گاز طبیعی محاسبه می‌کنیم:\\r\\n\\r\\n\\r\\n\\r\\n$\\\\text{درصد تغییر مقدار } CO_2 \\\\text{ تولید شده} = \\\\frac{\\\\text{مقدار } CO_2 \\\\text{ تولید شده توسط منبع خورشیدی} - \\\\text{مقدار } CO_2 \\\\text{ تولید شده توسط منبع گازی}}{\\\\text{مقدار } CO_2 \\\\text{ تولید شده توسط منبع گازی}} \\\\times 100$\\r\\n\\r\\n\\r\\n\\r\\n$= \\\\frac{11088 - 1584}{11088} \\\\times 100 \\\\simeq 86\\\\%$\\r\\n\\r\\n\\r\\n\\r\\nبنابراین اگر به جای منبع گاز از منبع خورشیدی برای تولید برق استفاده شود، میزان تولید $CO_2$، $86\\\\%$ کاهش پیدا می‌کند. البته، توجه داریم که درصد تغییر مقدار گاز $CO_2$ تولید شده در یک سال، با درصد تغییر $CO_2$ تولید شده به ازای هر کیلووات ساعت برق مصرفی، برابر است و می‌توانیم بنویسیم:\\r\\n\\r\\n\\r\\n\\r\\n$\\\\text{درصد تغییر مقدار } CO_2 \\\\text{ تولید شده} = \\\\frac{0/35 - 0/05}{0/35} \\\\times 100 \\\\simeq 86\\\\%$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":null,\"is_answered\":false},\"6298\":{\"correct_option_id\":28882,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 2 (متوسط - مساله و مفهومی - 1003) از آن‌جا که ترکیبات یونی از لحاظ بار الکتریکی خنثی هستند، مجموع بار الکتریکی کاتیون‌ها و آنیون‌های موجود در هر ترکیب یونی باید با هم برابر باشد. از این قاعده می‌توان برای نوشتن فرمول شیمیایی ترکیب‌های یونی و یا پیدا کردن بار آنیون و کاتیون موجود در این مواد استفاده کرد. با توجه به اطلاعات داده شده در صورت سوال در رابطه با نمک‌های آلومینیم پرمنگنات و آلومینیم کرومات، می‌توان گفت بار الکتریکی یون‌های پرمنگنات و کرومات به ترتیب برابر با 1- و 2- است. فرمول شیمیایی پتاسیم پرمنگنات به صورت $KMnO4$ و آمونیوم کرومات به صورت $(NH4)2CrO4$ است. نسبت اتم‌های فلزی به اتم‌های نافلزی در $KMnO4$، برابر با $1/2$ و در $(NH4)2CrO4$ برابر با $1/14$ است. بنابراین نسبت خواسته شده برابر است با: $1 / 2 / 1 / 14 = 14 / 2 = 7$ فرمول شیمیایی پتاسیم کرومات نیز به صورت $K2CrO4$ است. در هر مول از این ماده، 130 گرم اتم فلزی(52 گرم کروم و 78 گرم پتاسیم) و 64 گرم اتم نافلزی(64 گرم اکسیژن) وجود دارد، پس می‌توان گفت تفاوت جرم اتم‌های فلزی و نافلزی در هر مول از این ماده برابر با 66 گرم بوده و تفاوت جرم اتم‌های فلزی و نافلزی در 0/2 مول از این ماده برابر با 13/2 گرم می‌شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":null,\"is_answered\":false},\"6858\":{\"correct_option_id\":46247,\"descriptive_answer\":{\"text\":\"بررسی عبارت‌ها:\\r\\n\\r\\nعبارت اول: نادرست - ممکن است برخی از کاتیون‌های فلزی که قدرت اکسندگی بیشتری دارند به اتم‌های فلز کاهش یابند.\\r\\n\\r\\nعبارت دوم: نادرست - ممکن است در یک واکنش اکسایش و کاهش، هر دو یک عنصر باشند. به عنوان مثال در واکنش زیر اتم‌های نیتروژن هم با کاهش و هم با افزایش عدد اکسایش همراهند.\\r\\n\\r\\n$NO(g) + NO_2(g) + 2NH_3(g) \\\\rightarrow 2N_2(g) + 3H_2O(g)$\\r\\n\\r\\nعبارت سوم: نادرست - در برخی از واکنش‌های اکسایش - کاهش، افزون بر دادوستد الکترون، انرژی (گرما) نیز آزاد می‌شود.\\r\\n\\r\\nعبارت چهارم: نادرست - جهت انجام یک واکنش اکسایش و کاهش، لزومی به وجود ترکیب یونی در اجزای شرکت‌کننده واکنش نیست، به عنوان مثال در این واکنش هیچ ترکیب یونی مشاهده نمی‌شود.\\r\\n\\r\\n$S(s) + O_2(g) \\\\rightarrow SO_2(g)$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"7163\":{\"correct_option_id\":41147,\"descriptive_answer\":{\"text\":\"فرض کنید طول ضلع بیرونی دو مکعب را $a$ بنامیم. در این صورت، هم شعاع حفره\\r\\n\\r\\nکروی در مکعب اول و هم طول ضلع حفره مکعبی در مکعب دوم هر دو معادل $a/2$\\r\\n\\r\\nمی‌باشند. بنابراین، ابتدا حجم حاصل از ماده سازنده هریک از جسم‌ها را به صورت\\r\\n\\r\\nزیر به‌دست آوریم:\\r\\n\\r\\n$V (1)$ مکعب $=$ $V$ مکعب بیرونی $-$ $V$ حفره کروی $=$ $a^3 - 4/3 π R^3$\\r\\n\\r\\n$R=a/2$\\r\\n\\r\\n$------- → V (1)$ مکعب $=$ $a^3 - (4/3 × 3 × a^3/8) = 1/2 a^3$\\r\\n\\r\\n$π=3$\\r\\n\\r\\n$V (2)$ مکعب $=$ $V$ مکعب بیرونی $-$ $V$ حفره مکعبی $=$ $a^3 - (a/2)^3 →$\\r\\n\\r\\n$V (2)$ مکعب $=$ $a^3 - 1/8 a^3 = 7/8 a^3$\\r\\n\\r\\nاکنون طبق رابطه چگالی می‌توان این‌گونه نوشت:\\r\\n\\r\\n$m = ρ × V → m_2/m_1 = ρ_2/ρ_1 × V(2)$ مکعب $/$ $V(1)$ مکعب $--- ρ_1=1/2 ρ_2 →$\\r\\n\\r\\n$m_2/m_1 = ρ_2 / (1/2 ρ_2) × (7/8 a^3) / (1/2 a^3) → m_2/m_1 = 7/2$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7275\":{\"correct_option_id\":40700,\"descriptive_answer\":{\"text\":\"در حالت اول ارتفاع عمودی لوله را به‌صورت زیر می‌یابیم:\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n$sin 30° = $ضلع مقابل / وتر $ = h1/50 -> 1/2 = h1/50 -> h1 = 25cm$\\r\\n\\r\\nچون فشار هوا $75cmHg$ است، بنابراین، در حالت اول فشاری به اندازه $P1 = 75 - 25 = 50cmHg$ از طرف جیوه بر انتهای بسته لوله وارد می‌شود. در حالت دوم که زاویه لوله از راستای قائم $7$ درجه کاهش می‌یابد، زاویه بین لوله و سطح جیوه به $37°$ می‌رسد. بنابراین داریم:\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n$sin 37° = $ضلع مقابل / وتر $ = h2/50 -> 0.6 = h2/50 => h2 = 30cm$\\r\\n\\r\\nمی‌بینیم، در حالت دوم فشاری معادل $P2 = 75 - 30 = 45cmHg$ از طرف جیوه بر انتهای بسته لوله وارد می‌شود. بنابراین، چون فشار وارد بر انتهای بسته لوله کاهش یافته است نیروی وارد بر آن نیز کاهش می‌یابد.\\r\\n\\r\\nبرای محاسبه مقدار کاهش نیرو، ابتدا مقدار کاهش فشار را حساب می‌کنیم و به دنبال آن $ΔF$ را به‌دست می‌آوریم. دقت کنید، برای محاسبه $ΔF$ ، الزاماً باید فشار برحسب $Pa$ باشد.\\r\\n\\r\\n$ΔP = P2 - P1 -> (P2=45cmHg, P1=50cmHg) -> ΔP = 45 - 50 = -5cmHg => |Δh| = 5cm = 0.05m$\\r\\n\\r\\n$ΔP = ρgΔh -> (ρ=13600 kg/m3, Δh=0.05m) -> ΔP = 13600 * 10 * 0.05 = 6800Pa$\\r\\n\\r\\n$ΔF = A * ΔP -> (A=10cm2=10*10^-4 m2)$\\r\\n\\r\\n$ΔF = 10 * 10^-4 * 6800 = 6.8N$\\r\\n\\r\\nبنابراین، نیروی وارد بر انتهای بسته لوله $6.8N$ کاهش می‌یابد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل دو دهم\",\"selected_option_id\":40703,\"is_answered\":true},\"7418\":{\"correct_option_id\":40098,\"descriptive_answer\":{\"text\":\"ابتدا با استفاده از قضیه کار و انرژی جنبشی، کار نیروی مقاومت هوا را از لحظه پرتاب تا\\r\\n\\r\\nلحظه رسیدن به نقطه اوج به‌دست می‌آوریم. دقت کنید، هنگام بالا رفتن گلوله کار نیروی\\r\\n\\r\\nوزن آن منفی است.\\r\\n\\r\\n\\r\\n\\r\\nتصویری از مسیر حرکت یک گلوله. گلوله از ارتفاع ۳۰ متری سطح زمین با سرعت اولیه $v_1 = 20 \\\\frac{m}{s}$ به سمت بالا پرتاب می‌شود. به اندازه $h_1 = 15 m$ بالا می‌رود تا به نقطه اوج برسد، جایی که سرعت آن $v_2 = 0$ است. ارتفاع نقطه اوج از سطح زمین $h_2 = 45 m$ است. سپس گلوله به سمت پایین سقوط می‌کند و با سرعت $v_3 = ?$ به زمین می‌رسد.\\r\\n\\r\\n\\r\\n\\r\\n$\\\\Delta K = W_t \\\\xrightarrow[\\\\Delta K = \\\\frac{1}{2}m(v_2^2 - v_1^2)]{W_t = W_{mg} + W_f} \\\\frac{1}{2}m(v_2^2 - v_1^2) = W_{mg} + W_f$\\r\\n\\r\\n$\\\\xrightarrow{W_{mg} = -mgh_1} \\\\frac{1}{2}m(v_2^2 - v_1^2) = -mgh_1 + W_f$\\r\\n\\r\\n$\\\\xrightarrow[v_1 = 20 \\\\frac{m}{s}, v_2 = 0]{m = 500 g = 0/5 kg, h_1 = 15 m}$\\r\\n\\r\\n$\\\\frac{1}{2} \\\\times 0/5 \\\\times (0 - 400) = -0/5 \\\\times 10 \\\\times 15 + W_f \\\\Rightarrow W_f = -25 J$\\r\\n\\r\\n\\r\\n\\r\\nبا توجه به این‌که نیروی مقاومت هوا در طول مسیر حرکت ثابت است، قضیه کار و انرژی\\r\\n\\r\\nجنبشی را از نقطه اوج تا لحظه رسیدن به زمین می‌نویسیم و تندی گلوله را در لحظه\\r\\n\\r\\nبرخورد با زمین، می‌یابیم. دقت کنید، در هنگام پایین آمدن گلوله کار نیروی وزن مثبت\\r\\n\\r\\nاست. در ضمن چون برای مسیر $h_1 = 15 m$ کار نیروی مقاومت هوا برابر\\r\\n\\r\\n$W_f = -25 J$ است، برای مسیر $h_2 = 45 m$، کار این نیرو سه برابر آن، یعنی\\r\\n\\r\\n$W\'_f = 3 \\\\times (-25) = -75 J$ می‌باشد که با یک تناسب ساده به‌دست می‌آید.\\r\\n\\r\\n\\r\\n\\r\\n$\\\\Delta K\' = W\'_t \\\\xrightarrow[W\'_t = W\'_{mg} + W\'_f]{\\\\Delta K\' = \\\\frac{1}{2}m(v_3^2 - v_2^2)}$\\r\\n\\r\\n$\\\\frac{1}{2}m(v_3^2 - v_2^2) = W\'_{mg} + W\'_f \\\\xrightarrow[v_2 = 0]{W\'_{mg} = mgh_2}$\\r\\n\\r\\n$\\\\frac{1}{2}mv_3^2 = mgh_2 + W\'_f \\\\xrightarrow[h_2 = 45 m]{W\'_f = -75 J, m = 0/5 kg}$\\r\\n\\r\\n$\\\\frac{1}{2} \\\\times 0/5 \\\\times v_3^2 = 0/5 \\\\times 10 \\\\times 45 - 75 \\\\Rightarrow \\\\frac{1}{4}v_3^2 = 150$\\r\\n\\r\\n$\\\\Rightarrow v_3^2 = 600 = 100 \\\\times 6 \\\\Rightarrow v_3 = \\\\sqrt{100 \\\\times 6} \\\\Rightarrow v_3 = 10\\\\sqrt{6} \\\\frac{m}{s}$\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل سه دهم\",\"selected_option_id\":null,\"is_answered\":false},\"7539\":{\"correct_option_id\":39606,\"descriptive_answer\":{\"text\":\"گزینه «2» (امیر پورسیف) ابتدا با استفاده از رابطه تغییر سطح در اثر تغییر دما، ضریب انبساط طولی کره را می‌یابیم. با توجه به نمودار، وقتی دمای کره از صفر درجه سلسیوس به $50^\\\\circ C$ می‌رسد، مساحت کره از $1 cm^2$ به $1.02 cm^2$ می‌رسد، یعنی تغییرات مساحت کره در اثر افزایش دمای $50^\\\\circ C$ برابر $\\\\Delta A = 1.02 - 1 = 0.02 cm^2$ است. بنابراین داریم: $\\\\Delta A = 2\\\\alpha A_1 \\\\Delta\\\\theta \\\\xrightarrow{A_1 = 1 cm^2, \\\\Delta\\\\theta = 50 - 0 = 50^\\\\circ C}$ $0.02 = 2\\\\alpha \\\\times 1 \\\\times 50$ $\\\\Rightarrow \\\\alpha = 2 \\\\times 10^{-4} \\\\frac{1}{^\\\\circ C}$ اکنون $77^\\\\circ F$ را به درجه سلسیوس تبدیل می‌کنیم. دقت کنید، چون شعاع اولیه برحسب $^\\\\circ C$ است، درجه فارنهایت را به درجه سلسیوس تبدیل نموده‌ایم. $F = \\\\frac{9}{5}\\\\theta + 32 \\\\xrightarrow{F = 77^\\\\circ F}$ $77 = \\\\frac{9}{5}\\\\theta + 32 \\\\Rightarrow 45 = \\\\frac{9}{5}\\\\theta$ $\\\\Rightarrow \\\\theta = 25^\\\\circ C$ در نهایت درصد تغییر شعاع کره را با استفاده از رابطه درصد تغییر طول می‌یابیم: درصد تغییر شعاع $= \\\\frac{\\\\Delta R}{R_1} \\\\times 100 \\\\xrightarrow{\\\\Delta R = \\\\alpha R_1 \\\\Delta\\\\theta}$ درصد تغییر شعاع $= \\\\frac{\\\\alpha \\\\times R_1 \\\\Delta\\\\theta \\\\times 100}{R_1}$ $\\\\xrightarrow{\\\\alpha = 2 \\\\times 10^{-4} \\\\frac{1}{^\\\\circ C}, \\\\Delta\\\\theta = 25 - 0 = 25^\\\\circ C}$ درصد تغییر شعاع $= 100 \\\\times 2 \\\\times 10^{-4} \\\\times 25 = 0.5\\\\%$ (دما و گرما) (فیزیک 1، صفحه‌های 90 تا 93)\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل چهار دهم\",\"selected_option_id\":null,\"is_answered\":false},\"8524\":{\"correct_option_id\":51409,\"descriptive_answer\":{\"text\":\"خروج آب به‌صورت قطراتی از انتها یا لبه برگ‌ها در بعضی از گیاهان علفی را تعریق می‌گویند. در هوای بسیار مرطوب که شدت تعرق کاهش می‌یابد، یاخته‌های درون‌پوست همچنان به پمپ‌کردن یون‌های معدنی به درون استوانه آوندی ادامه می‌دهند و در نتیجه تعریق صورت می‌گیرد.\\r\\n\\r\\nبررسی سایر گزینه‌ها:\\r\\n\\r\\n۱ تعریق از ساختارهای ویژه‌ای به نام روزنه‌های آبی انجام می‌شود. این روزنه‌ها همیشه باز هستند؛ بنابراین به کار بردن لفظ \\\"باز می‌شوند\\\" برای این روزنه‌ها غلط است.\\r\\n\\r\\n۲ احتمال وقوع تعریق در صورتی که پمپ یون‌های معدنی به درون استوانه آوندی و تجمع این یون‌ها و آب در آوند چوبی کاهش یابد، کاهش می‌یابد. دقت کنید فشار ریشه‌ای با احتمال وقوع تعریق رابطه مستقیم دارد.\\r\\n\\r\\n۴ انباشت ساکارز در یاخته‌های نگهبان روزنه موجب تورژسانس این یاخته‌ها و بازشدن روزنه‌ها هوایی می‌شود که افزایش تعرق و کاهش احتمال وقوع تعریق را به‌دنبال دارد. دقت کنید تعرق با احتمال وقوع تعریق رابطه معکوس دارد.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"فصل هفت دهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"836\":6716,\"1111\":34537,\"1244\":42178,\"1982\":49723,\"2306\":51696,\"5320\":32599,\"7275\":40703},\"submittedQuestionIds\":[2306,1982,7275,989,1111,836,1244,5320,4985,718,894,5487,848,7163,2051,917,3576,2224,639,1806,4224,877,1012,488,6298,4233,6033,2854,6858,1021,372,4922,8524,4216,471,5228,1391,7418,7539,360,5092,1874,1912,2033,1186,4796],\"totalTimeSpent\":10,\"questionTimes\":{\"1111\":1001,\"1244\":1001,\"2306\":1003,\"5320\":1002,\"7275\":1013},\"selectionLog\":[{\"questionId\":2306,\"optionId\":51696,\"timeSpentMs\":1003,\"timestamp\":1789231830283},{\"questionId\":1982,\"optionId\":49723,\"timeSpentMs\":0,\"timestamp\":1789231831670},{\"questionId\":7275,\"optionId\":40703,\"timeSpentMs\":1013,\"timestamp\":1789231832620},{\"questionId\":1111,\"optionId\":34537,\"timeSpentMs\":1001,\"timestamp\":1789231833813},{\"questionId\":1244,\"optionId\":42178,\"timeSpentMs\":1001,\"timestamp\":1789231835084},{\"questionId\":836,\"optionId\":6716,\"timeSpentMs\":0,\"timestamp\":1789231835517},{\"questionId\":5320,\"optionId\":32599,\"timeSpentMs\":1002,\"timestamp\":1789231836749}]}}', '2026-09-12 16:50:43');
INSERT INTO `quiz_results` (`id`, `quiz_id`, `user_id`, `accuracy_rate`, `correct_count`, `incorrect_count`, `unanswered_count`, `total_score`, `total_time_spent`, `summary_json`, `result_data_json`, `created_at`) VALUES
(156, 79, 1, 10.00, 1, 9, 0, 0, 24, '{\"total_questions\":10,\"correct_count\":1,\"incorrect_count\":9,\"unanswered_count\":0,\"accuracy_rate\":10,\"score\":0,\"mabhas_stats\":{\"فصل یک دهم\":{\"correct\":1,\"incorrect\":9,\"unanswered\":0,\"total\":10}}}', '{\"evaluation\":{\"7122\":{\"correct_option_id\":41311,\"descriptive_answer\":{\"text\":\"ابتدا عدد مورد نظر را به‌صورت نمادگذاری علمی می‌نویسیم:\\r\\n\\r\\n$0/0012ng \\\\frac{mm^2}{\\\\mu s^3} = 1/2 \\\\times 10^{-3}ng \\\\frac{mm^2}{\\\\mu s^3}$\\r\\n\\r\\nاکنون با استفاده از روش تبدیل زنجیره‌ای، یکای آن را به $kg \\\\frac{\\\\mu m^2}{ns^3}$ تبدیل می‌کنیم:\\r\\n\\r\\n$1/2 \\\\times 10^{-3}ng \\\\frac{mm^2}{\\\\mu s^3}$\\r\\n\\r\\n$= 1/2 \\\\times 10^{-3}ng \\\\frac{mm^2}{\\\\mu s^3} \\\\times \\\\frac{10^{-9}g}{1ng} \\\\times \\\\frac{1kg}{10^3g} \\\\times \\\\frac{10^{-6}m^2}{1mm^2}$\\r\\n\\r\\n$\\\\times \\\\frac{1 \\\\mu m^2}{10^{-12}m^2} \\\\times \\\\frac{1 \\\\mu s^3}{10^{-18}s^3} \\\\times \\\\frac{10^{-27}s^3}{1ns^3}$\\r\\n\\r\\n$= \\\\frac{1/2 \\\\times 10^{-3} \\\\times 10^{-9} \\\\times 10^{-6} \\\\times 10^{-27}}{10^3 \\\\times 10^{-12} \\\\times 10^{-18}} kg \\\\frac{\\\\mu m^2}{ns^3}$\\r\\n\\r\\n$= 1/2 \\\\times 10^{-18}kg \\\\frac{\\\\mu m^2}{ns^3}$\\r\\n\\r\\nکه با مقایسه با عبارت صورت سؤال، داریم:\\r\\n\\r\\n$\\\\begin{cases} a=1/2 \\\\\\\\ b=-18 \\\\Rightarrow a+b=1/2+(-18)=-16/8 \\\\end{cases}$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41310,\"is_answered\":true},\"7129\":{\"correct_option_id\":41281,\"descriptive_answer\":{\"text\":\"با استفاده از رابطه چگالی مخلوط، داریم: ($Au$ نماد شیمیایی طلا و $Ag$ نماد شیمیایی نقره است.)\\r\\n\\r\\n$ρ$ مخلوط $= m$ مخلوط $/ V$ مخلوط $=> ρ$ مخلوط $= mAu + mAg / VAu + VAg$\\r\\n\\r\\n$ρ$ مخلوط $= ρAuVAu + ρAgVAg / VAu + VAg$\\r\\n\\r\\n$-> ρ$ مخلوط $= 13 / 6 g / cm3 , VAu + VAg = 5 cm3 / ρAu = 19 g / cm3 , ρAg = 10 g / cm3 ->$\\r\\n\\r\\n$13 / 6 = 19VAu + 10VAg / 5 => 19VAu + 10VAg = 68$\\r\\n\\r\\nاگر دستگاه دو معادله دو مجهولی زیر را حل کنیم، مقادیر $VAu$ و $VAg$ به دست می آید:\\r\\n\\r\\n$\\\\{ 19VAu + 10VAg = 68$\\r\\n\\r\\n$\\\\{ VAu + VAg = 5$\\r\\n\\r\\n$=> \\\\{ 19VAu + 10VAg = 68$\\r\\n\\r\\n$\\\\{ 19VAu + 19VAg = 95$\\r\\n\\r\\n$--------------------$\\r\\n\\r\\n$9VAg = 27$\\r\\n\\r\\n$=> VAg = 3 cm3 , VAu = 2 cm3$\\r\\n\\r\\nخواسته مسئله، محاسبه جرم نقره به کار رفته است، پس طبق تعریف چگالی داریم:\\r\\n\\r\\n$ρAg = mAg / VAg -> ρAg = 10 g / cm3 / VAg = 3 cm3 -> 10 = mAg / 3$\\r\\n\\r\\n$=> mAg = 10 × 3 = 30 g$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41280,\"is_answered\":true},\"7130\":{\"correct_option_id\":41278,\"descriptive_answer\":{\"text\":\"کمیت های اصلی عبارتند از:\\r\\n\\r\\n$1$) طول $2$) جرم $3$) زمان $4$) دما $5$) مقدار ماده $6$) جریان الکتریکی $7$) شدت روشنایی\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41277,\"is_answered\":true},\"7132\":{\"correct_option_id\":41268,\"descriptive_answer\":{\"text\":\"چون در هر دو حالت، حجم آب و روغن برابر حجم بطری خالی است، بنابراین، با توجه به رابطه $ρ = m / V$ و با توجه به این که جرم آب برابر $m1 = 300 - m\'$ و جرم روغن برابر $m2 = 280 - m\'$ است، به صورت زیر جرم بطری را می یابیم.\\r\\n\\r\\n($m\'$ جرم بطری خالی است.)\\r\\n\\r\\n$V = m1 / ρ1 = m2 / ρ2 -> ρ1 = 1 g / cm3 / ρ2 = 0 / 8 g / cm3 -> 300 - m\' / 1 = 280 - m\' / 0 / 8 =>$\\r\\n\\r\\n$240 - 0 / 8m\' = 280 - m\' => 0 / 2m\' = 40 => m\' = 200g$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41269,\"is_answered\":true},\"7136\":{\"correct_option_id\":41254,\"descriptive_answer\":{\"text\":\"یکای $SI$ نیرو، نیوتون $(N)$ است. اما برای یکای فرعی آن می‌توان نوشت:\\r\\n\\r\\n$F=ma=(kg)(\\\\frac{m}{s^2})=\\\\frac{kgm}{s^2}$\"},\"status\":\"wrong\",\"level\":\"آسان\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41252,\"is_answered\":true},\"7147\":{\"correct_option_id\":41211,\"descriptive_answer\":{\"text\":\"سال نوری یکای طول است (رد گزینه‌های $1$ و $2$) و برابر مسافتی است که نور در مدت\\r\\n\\r\\nیک سال در خلأ طی می‌کند. بنابراین، چون تندی نور ثابت است، با استفاده از رابطۀ زیر،\\r\\n\\r\\nمی‌توان نوشت:\\r\\n\\r\\n$d = vt \\\\xrightarrow[t = 3 \\\\times 10^7 s]{v = 3 \\\\times 10^8 \\\\frac{m}{s}} d = 3 \\\\times 10^8 \\\\times 3 \\\\times 10^7 \\\\Rightarrow d = 9 \\\\times 10^{15} m$\\r\\n\\r\\nچون در بین دو گزینۀ باقیمانده $9 \\\\times 10^{15} m$ وجود ندارد، بنابراین گزینۀ «$4$» درست\\r\\n\\r\\nاست و به‌صورت زیر $m$ را به مگامتر تبدیل می‌کنیم. چون مگا یعنی $10^6$، داریم:\\r\\n\\r\\n$d = 9 \\\\times 10^{15} m = 9 \\\\times 10^9 \\\\times 10^6 m \\\\xrightarrow{10^6 m = 1 Mm} d = 9 \\\\times 10^9 Mm$\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41211,\"is_answered\":true},\"7149\":{\"correct_option_id\":41203,\"descriptive_answer\":{\"text\":\"برای محاسبه چگالی گلوله فلزی، چون جرم آن معلوم است، باید حجم آن را بیابیم. با\\r\\n\\r\\nتوجه به این‌که حجم مایع‌های بیرون ریخته از ظرف‌ها برابر حجم گلوله فلزی است،\\r\\n\\r\\nمی‌توان نوشت:\\r\\n\\r\\n$V$ فلز $= V$ الکل بیرون‌ریخته $= V$ آب بیرون‌ریخته\\r\\n\\r\\n$m$ آب $- m$ الکل $= 20 \\\\xrightarrow{m= \\\\rho V} \\\\rho$ آب $V$ آب $- \\\\rho$ الکل $V$ الکل $= 20$\\r\\n\\r\\n$\\\\xrightarrow{V \\\\text{فلز} = V \\\\text{الکل} = V \\\\text{آب}} \\\\xrightarrow{\\\\rho \\\\text{آب} = 1 \\\\frac{g}{cm^3} , \\\\rho \\\\text{الکل} = 0/8 \\\\frac{g}{cm^3}}$\\r\\n\\r\\n$1 \\\\times V$ فلز $- 0/8 \\\\times V$ فلز $= 20 \\\\Rightarrow 0/2 V$ فلز $= 20 \\\\Rightarrow V$ فلز $= 100cm^3$\\r\\n\\r\\nاکنون می‌توان چگالی گلوله را به‌دست آورد:\\r\\n\\r\\n$\\\\rho$ فلز $= \\\\frac{m \\\\text{فلز}}{V \\\\text{فلز}} \\\\xrightarrow{m \\\\text{فلز} = 160 g} \\\\xrightarrow{V \\\\text{فلز} = 100 cm^3}$\\r\\n\\r\\n$\\\\rho$ فلز $= \\\\frac{160 g}{100 cm^3} = 1/6 \\\\frac{g}{cm^3} \\\\xrightarrow{1 g = 10^{-3} kg} \\\\xrightarrow{1 cm^3 = 10^{-3} L} \\\\rho$ فلز $= 1/6 \\\\times \\\\frac{10^{-3} kg}{10^{-3} L}$\\r\\n\\r\\n$\\\\Rightarrow \\\\rho$ فلز $= 1/6 \\\\frac{kg}{L}$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41201,\"is_answered\":true},\"7157\":{\"correct_option_id\":41171,\"descriptive_answer\":{\"text\":\"دقت خط‌کش مدرج و کولیس رقمی را به m و cm تبدیل می‌کنیم.\\r\\n\\r\\n$1 mm = 0/1 cm = 0/001 m =$ دقت خط‌کش\\r\\n\\r\\n$0/1 mm = 0/01 cm = 0/0001 m =$ دقت کولیس\\r\\n\\r\\nبا توجه به نتیجه‌های به‌دست آمده خط‌کش اندازه‌های $0/1 cm$ و $0/001 m$ و\\r\\n\\r\\nکولیس $0/01 cm$ و $0/0001 m$ را می‌تواند اندازه‌گیری کند. بنابراین گزینه «۴»\\r\\n\\r\\nصحیح است.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41169,\"is_answered\":true},\"7162\":{\"correct_option_id\":41148,\"descriptive_answer\":{\"text\":\"مطابق شکل، در شمارنده $(1)$، دقت اندازه‌گیری معادل $2 km/h$ و در شمارنده $(2)$\\r\\n\\r\\nدقت اندازه‌گیری معادل $10 mph$ است. بنابراین برای محاسبه نسبت این دو دقت،\\r\\n\\r\\nباید یکای آنها مشابه هم باشد. در این‌صورت، یکای دقت اندازه‌گیری شمارنده $(2)$ را\\r\\n\\r\\nبه $km/h$ تبدیل می‌کنیم:\\r\\n\\r\\n\\r\\n\\r\\n$10 mile / h \\\\times 1800 m / 1 mile \\\\times 1 km / 10^3 m = 18 km / h$\\r\\n\\r\\n\\r\\n\\r\\nبنابراین:\\r\\n\\r\\nدقت شمارنده $(1)$ / دقت شمارنده $(2)$ $= (2 km / h) / (18 km / h) = 1/9$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41150,\"is_answered\":true},\"7180\":{\"correct_option_id\":41075,\"descriptive_answer\":{\"text\":\"با توجه به این‌که $T=10^{12}$ و $\\\\mu=10^{-6}$ است، با استفاده از تبدیل زنجیره‌ای\\r\\n\\r\\nمی‌توان نوشت:\\r\\n\\r\\n$0/00024 \\\\mu N.Tm = 2/4 \\\\times 10^{-4} \\\\mu N.Tm \\\\times \\\\frac{1 N}{10^6 \\\\mu N} \\\\times \\\\frac{10^{12} m}{1 Tm}$\\r\\n\\r\\n$= 2/4 \\\\times 10^2 N.m$\\r\\n\\r\\nاز طرف دیگر، با توجه به این‌که $1N = 1 kg.\\\\frac{m}{s^2}$ است، داریم:\\r\\n\\r\\n$2/4 \\\\times 10^2 N.m = 2/4 \\\\times 10^2 \\\\frac{kg.m^2}{s^2}$\\r\\n\\r\\n$\\\\frac{M=10^6}{n=10^{-9}} \\\\rightarrow 2/4 \\\\times 10^2 \\\\frac{kg.m^2}{s^2} \\\\times \\\\frac{10^3 g}{1 kg} \\\\times \\\\frac{1 Mg}{10^6 g}$\\r\\n\\r\\n$\\\\times \\\\frac{1 s^2}{(10^9)^2 ns^2} \\\\times \\\\frac{(10^3)^2 mm^2}{1 m^2} = 2/4 \\\\times 10^2 \\\\times 10^3 \\\\times 10^{-18} \\\\frac{Mg.mm^2}{ns^2}$\\r\\n\\r\\n$= 2/4 \\\\times 10^{-13} \\\\frac{Mg.mm^2}{ns^2}$\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل یک دهم\",\"selected_option_id\":41074,\"is_answered\":true}},\"submission\":{\"submittedAnswers\":{\"7122\":41310,\"7129\":41280,\"7130\":41277,\"7132\":41269,\"7136\":41252,\"7147\":41211,\"7149\":41201,\"7157\":41169,\"7162\":41150,\"7180\":41074},\"submittedQuestionIds\":[7130,7132,7162,7122,7129,7149,7147,7180,7136,7157],\"totalTimeSpent\":24,\"questionTimes\":{\"7130\":5001},\"selectionLog\":[{\"questionId\":7130,\"optionId\":41277,\"timeSpentMs\":5001,\"timestamp\":1789601565044},{\"questionId\":7132,\"optionId\":41269,\"timeSpentMs\":0,\"timestamp\":1789601567201},{\"questionId\":7162,\"optionId\":41150,\"timeSpentMs\":0,\"timestamp\":1789601569385},{\"questionId\":7122,\"optionId\":41310,\"timeSpentMs\":0,\"timestamp\":1789601571359},{\"questionId\":7129,\"optionId\":41280,\"timeSpentMs\":0,\"timestamp\":1789601573137},{\"questionId\":7149,\"optionId\":41201,\"timeSpentMs\":0,\"timestamp\":1789601574933},{\"questionId\":7147,\"optionId\":41211,\"timeSpentMs\":0,\"timestamp\":1789601576585},{\"questionId\":7180,\"optionId\":41074,\"timeSpentMs\":0,\"timestamp\":1789601578317},{\"questionId\":7136,\"optionId\":41252,\"timeSpentMs\":0,\"timestamp\":1789601579804},{\"questionId\":7157,\"optionId\":41169,\"timeSpentMs\":0,\"timestamp\":1789601581099}]}}', '2026-09-16 23:33:03'),
(157, 80, 4, 13.33, 2, 3, 10, 8, 18, '{\"total_questions\":15,\"correct_count\":2,\"incorrect_count\":3,\"unanswered_count\":10,\"accuracy_rate\":13.33,\"score\":8,\"mabhas_stats\":{\"دو دوازدهم\":{\"correct\":1,\"incorrect\":1,\"unanswered\":4,\"total\":6},\"تابع يازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":6,\"total\":7},\"فصل چهار یازدهم\":{\"correct\":0,\"incorrect\":1,\"unanswered\":0,\"total\":1},\"تابع دوازدهم\":{\"correct\":1,\"incorrect\":0,\"unanswered\":0,\"total\":1}}}', '{\"evaluation\":{\"495\":{\"correct_option_id\":6415,\"descriptive_answer\":{\"text\":\"غشای پایه در مویرگ&zwnj;های کلافک (مویرگ&zwnj;های منفذدار)، ضخیم است و عبور مولکول&zwnj;های درشت مثل پروتئین&zwnj;ها را محدود می&zwnj;کند. به دنبال تخریب دیواره مویرگ&zwnj;های کلافک، موادی که قبلاً نمی&zwnj;توانستند در اثر تراوش از خون خارج شوند، فرصت خارج شدن از خون را پیدا می&zwnj;کنند و بنابراین پروتئین&zwnj;ها نیز از خون خارج می&zwnj;شوند. با خروج پروتئین&zwnj;ها از خون، فشار اسمزی خون کاهش می&zwnj;یابد. به شکل مقابل توجه کنید، با کاهش فشار اسمزی، (فشار اسمزی کاهش یافته، با خط آبی رنگ در شکل نشان داده شده است) محلی که فشار اسمزی و فشار خون با یکدیگر برابر می&zwnj;شوند، به انتهای مویرگ نزدیک&zwnj;تر می&zwnj;شود. بنابراین در قسمت&zwnj;های بیشتری از مویرگ فشار خون بیشتر از فشار اسمزی خواهد بود و مواد فرصت بیشتری برای خروج از مویرگ&zwnj;های خونی دارند. (حالا میخواد مویرگ&zwnj;های روده باشه یا هر جای دیگه! مهم اینه که فشار اسمزی خون کم شده) 1) با توجه به شماره گذاری&zwnj;های کتاب درسی برای مراحل چرخۀ ضربان قلب، مرحله سوم چرخۀ ضربان قلب، انقباض بطنی است. با کاهش مدت انقباض بطنی، حجم خون خارج شده از بطن&zwnj;ها و در نتیجه فشار خون کاهش می&zwnj;یابد. تراوش به کمک نیروی فشار خون انجام می&zwnj;گیرد و بنابراین با کاهش فشار خون، حجم موادی که طی تراوش از خون خارج می&zwnj;شوند نیز کاهش می&zwnj;یابد. 2) هیپوفیز پسین دو هورمون ضدادراری و اکسی&zwnj;توسین ترشح می&zwnj;کند. به دنبال عدم ترشح هورمون ضدادراری، مقدار زیادی ادرار رقیق از بدن دفع می&zwnj;شود. چنین حالتی به دیابت بی&zwnj;مزه معروف است. کار اصلی دستگاه لنفی، تصفیه و بازگرداندن آب و مواد دیگری است که از مویرگ&zwnj;ها به فضای میان&zwnj;بافتی نشت پیدا می&zwnj;کنند و به مویرگ&zwnj;ها بر نمی&zwnj;گردند. به دنبال عدم ترشح هورمون ضدادراری و دفع مقدار زیادی ادرار رقیق، آب بدن کم می&zwnj;شود! در نتیجه آبی که بخواهد توسط دستگاه لنفی به خون بازگردد نیز کم&zwnj;تر میشود، نه اینکه افزایش پیدا کند. 4) در فرایند انعقاد خونریزی&zwnj;های شدید، پروترومبین و فیبرینوژن که از پروتئین&zwnj;های محلول در خوناب&zwnj;اند، مصرف می&zwnj;شوند. بنابراین در خونریزی&zwnj;های شدید در نقاط مختلف بدن، مقدار زیادی از این پروتئین&zwnj;ها برای تشکیل لخته مصرف می&zwnj;شود و میزان پروتئین&zwnj;های محلول در خوناب کاهش می&zwnj;یابد. با کاهش پروتئین&zwnj;های خوناب، فشار اسمزی خون فشاری که مسبب بازگشت مواد به مویرگ&zwnj;های خونی می&zwnj;شود نیز کاهش می&zwnj;یابد.\"},\"status\":\"wrong\",\"level\":\"سخت\",\"mabhas\":\"فصل چهار یازدهم\",\"selected_option_id\":6413,\"is_answered\":true},\"893\":{\"correct_option_id\":6591,\"descriptive_answer\":{\"text\":\"گزینه&laquo;3&raquo; در پروکاریوت ها، منظور از توالی ویژه مؤثر در رونویسی، می تواند توالی راه انداز، اپراتور، جایگاه اتصال فعال کننده و یا توالی پایان رونویسی باشد. در یوکاریوت ها، توالی افزاینده هم، نوعی توالی ویژه است که در رونویسی نقش دارد. از بین مراحل طویل شدن و پایان، فقط در مرحله پایان، پس از رونویسی شدن توالی پایان رونویسی (جزئی از ژن)، آنزیم رنابسپاراز از مولکول دنا (DNA) جدا می شود. دقت کنید که سایر توالی های نام برده شده جزئی از توالی ژن نمی باشند. بررسی سایر گزینه ها: 1) شکسته شدن پیوندهای هیدروژنی میان دو رشته دنا (و در نتیجه پیوندهای بین نوکلئوتیدهایی با قندهای یکسان) را هم در مرحله طویل شدن و هم در مرحله پایان ترجمه می توان مشاهده نمود؛ نه در برخی از آن ها! 2) این گزینه در خصوص مرحله پایان رونویسی است که بعد از رونویسی شدن توالی پایان رونویسی، رنابسپار از از دنا جدا می شود. اما توجه داشته باشید که در پروکاریوت ها، دنای &laquo;هسته ای!&raquo; نداریم و این گزینه از بیخ و بن نادرست می باشد. 4) در مرحله آغاز رونویسی، راه انداز موجب می شود رنا بسپار از اولین نوکلئوتید مناسب را به طور دقیق پیدا و رونویسی را از آنجا آغاز کند. در این حالت بخش کوچکی از مولکول دنا باز و زنجیره کوتاهی از رنا ساخته می شود. با این اوصاف، این گزینه در خصوص هیچ یک از مراحل طویل شدن و پایان صادق نیست.\"},\"status\":\"correct\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6591,\"is_answered\":true},\"894\":{\"correct_option_id\":6581,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; موارد &laquo;الف&raquo; و &laquo;ج&raquo; به درستی بیان شده اند. بررسی همه موارد: الف) پس از خروج رنای ناقل فاقد آمینواسید از جایگاهE ، براساس وجود یا عدم وجود کدون پایان در جایگاه ،A دو اتفاق می تواند رخ دهد. یا عامل آزاد کننده به جایگاه A وارد می شود (اگر کدون پایان در جایگاه A (باشد که در نهایت رنای ناقل و زنجیره پلی پپتیدی از جایگاه P ریبوزوم خارج می شوند؛ و اگر کدون رمزکننده یک آمینواسید در جایگاه A باشد، جایگاه A آماده پذیرش رنای ناقل بعدی می شود که پس از ورود و استقرار رنای ناقل مکمل به این جایگاه پیوند اشتراکی در جایگاه P ریبوزوم شکسته می شود تا پیوند پپتیدی بعدی تشکیل شود. ب) این مورد همواره رخ می دهد و مخصوص شرایط خاصی نیست! دقت کنید که تشکیل پیوند پپتیدی در جایگاه A رناتن اتفاق می افتد و کمی پس از تشکیل آن، همواره جابه جایی رناتن بر روی رنای پیک رخ میدهد که در نتیجه آن، رنای ناقل متصل به رشته پپتیدی به جایگاه P وارد میشود و رنای ناقل فاقد آمینواسید پس از ورود به جایگاه E رناتن، از آن خارج می گردد. ج) علاوه بر مرحله پایان ترجمه که پیوند بین رشته آمینواسیدی و tRNA شکسته می شود، طی طویل شدن هم این اتفاق می افتد، اما در پایان برخلاف طویل شدن tRNA ،فاقد آمینواسید به جایگاه E منتقل نمیشود بنابراین این جمله فقط درباره مرحله طویل شدن ترجمه صدق می کند یعنی در برخی شرایط رخ می دهد. د) کمی پیش از تشکیل پیوند پپتیدی در جایگاه ،A ریبوزوم پیوند اشتراکی بین آمینواسید و tRNA در جایگاه میانی ریبوزوم (جایگاه(P شکسته می شود. در واقع اگر قرار باشد پیوند پپتیدی تشکیل شود، همواره (نه در برخی شرایط!) باید رشته پپتیدی یا آمینواسید متصل به رنای ناقل در جایگاه ،P از این رنای ناقل جدا شود و سپس به جایگاه A منتقل گردد تا در نهایت به آمینواسید موجود در این جایگاه متصل شود. بنابراین، پیش از تشکیل هر پیوند پپتیدی حین ترجمه، باید پیوند اشتراکی بین رنای ناقل و بخش پپتیدی (یا آمینواسید) متصل به آن شکسته شود.\"},\"status\":\"unanswered\",\"level\":\"سخت\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"895\":{\"correct_option_id\":6578,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; در مرحله پایان ،ترجمه پروتئین(های) عوامل آزاد کننده در تماس با بخشی از رنای پیک قرار می گیرند. در مرحله پایان رونویسی نیز آنزیم پروتئینی رنابسپاراز با نوکلئوتیدهای بخشی از رنای پیک در تماس است. نوکلئوتیدهای سازندۀ رنا دارای قند ریبوز هستند. بررسی سایر گزینه ها: 1) در فرایند ترجمه، پیوند هیدروژنی و رابطه مکملی بین بخش هایی از دو نوع رنا (پیک و ناقل) با نوکلئوتیدهای دارای قندهای یکسان (ریبوز) صورت می گیرد. در رونویسی، پیوندهای هیدروژنی بین رنا و دنا با نوکلئوتیدهایی با قند متفاوت تشکیل می شود. 3) در مرحله آغاز ترجمه، پیوند هیدروژنی بین بازهای کدون آغاز با آنتی کدون مکمل آن تشکیل می شود. در مرحله آغاز رونویسی، پیوندهای هیدروژنی میان دو رشته دنا شکسته می شوند و بین نوکلئوتیدهای رنا و دنا پیوندهای هیدروژنی تشکیل می شوند. 4) در مرحله آغاز رونویسی، زنجیرۀ کوتاهی از رنا تشکیل می شود؛ پس بین نوکلئوتیدهای رنا و دنا پیوندهای هیدروژنی و بین ریبونوکلئوتیدهای رنا، پیوند اشتراکی شکل می گیرد. در آغاز ترجمه، هنوز پیوند پپتیدی (اشتراکی) بین آمینواسیدها تشکیل نمی شود. اما بین ریبونوکلئوتیدهای رنای پیک و رنای ناقل، پیوند هیدروژنی شکل می گیرد.\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":6577,\"is_answered\":true},\"896\":{\"correct_option_id\":6585,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; در یک مولکول رنای ناقل، هر نوکلئوتیدی که در یک انتهای رشته پلی نوکلئوتیدی قرار دارد با سایر نوکلئوتیدهای این رنا، فقط یک پیوند فسفودی استر تشکیل می دهد. براساس شکل کتاب درسی دیده می شود که در رنای ناقل، یکی از این دو نوکلئوتید در جایگاه اتصال به آمینواسید قرار دارد و با نوکلئوتید دیگری در ساختار رنای ناقل، پیوند هیدروژنی تشکیل نمی دهد. طبق شکل کتاب درسی، نوکلئوتید دیگر، در انتهای دیگر رشته پلینوکلئوتیدی پیوند هیدروژنی تشکیل می دهد. بررسی سایر گزینه ها: 2) در ساختار رنای ناقل ،یک نوکلئوتید در یک توالی سه نوکلئوتیدی در یک انتهای tRNA ، جایگاه اتصال به آمینواسید را تشکیل می دهد. مطابق شکل کتاب درسی، این نوکلئوتید جایگاه اتصال به آمینواسید در دورترین نقطه (بیشترین تعداد نوکلئوتید بین آن ها) نسبت به توالی پادرمزه (آنتی کدون) قرار دارد. براساس توالی پادرمزه، آمینواسید خاصی به رنای ناقل متصل می شود. 3) دو حلقه از رنای ناقل که فاقد توالی پادر مزه هستند، در ساختار سه بعدی مولکول رنای ناقل نسبت به تاخوردگی اولیه به یکدیگر نزدیک تر هستند. 4) ساختار نهایی میوگلوبین، ساختار سوم آن است. در میوگلوبین، برای اولین بار، تاخوردگی ها در ساختار دوم رخ می دهد که باعث ایجاد ساختار مارپیچ می شود و تاخوردگی های بیشتر نیز برای تشکیل ساختار سوم ایجاد می شود تا ساختار نهایی پروتئین شکل بگیرد. رنای ناقل نیز پس از تاخوردگی اولیه، تاخوردگی های مجددی پیدا میکند که ساختار سه بعدی آن را پدید می آورد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"898\":{\"correct_option_id\":6574,\"descriptive_answer\":{\"text\":\"گزینه&laquo;2&raquo; هلیکاز در طی همانندسازی، دو رشته دنا را از هم باز می کند، پس فقط یک نوع واکنش خاص را سرعت می بخشد، اما رنابسپاراز علاوه بر این که می تواند پیوندهای هیدروژنی بین دو رشته دنا را بشکند می تواند مولکول رنا هم بسازد؛ یعنی ریبونوکلئوتیدها را با پیوندهای فسفودی استر به هم وصل کند، پس دو نوع واکنش خاص را سرعت می بخشد. بررسی سایر گزینه ها: 1) رنابسپار از قادر است تا پیوندهای اشتراکی از نوع فسفودی استر را بین نوکلئوتیدها برقرارکند. اما هلیکاز چنین قابلیتی ندارد. ۳) هر دو آنزیم رنابسپاراز و هلیکاز، به منظور انجام فعالیت خود، به مولکول دنا متصل می شوند و ۲ رشته دنا را در بر می گیرند. آنزیم رنابسپار از می تواند یک رشته دنا را برای رونویسی شدن! الگو قرار دهد، اما هلیکاز هیچ یک از ۲ رشته را الگو قرار نمی دهد، زیرا توانایی تولید بسپار جدیدی را ندارد. 4) در فرایند رونویسی آنزیم رنابسپاراز RNA) پلیمراز)، پیوندهای هیدروژنی را می شکند؛ اما در فرایند همانندسازی، آنزیم هلیکاز، پیوندهای هیدروژنی را می شکند. دقت داشته باشید که در هر دو فرایند، تشکیل پیوندهای هیدروژنی به شکل خودبه خودی (نه با دخالت آنزیم) انجام می گردد.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"903\":{\"correct_option_id\":6561,\"descriptive_answer\":{\"text\":\"گزینه&laquo;1&raquo; برای حل این سؤال، تک تک موارد را به ترتیب بررسی می کنیم. مورد اول: همۀ رناهای ناقل به دلیل تاخوردگی های متعدد شکل سه بعدی و فضایی Lشکل به خود می گیرند. رنای رناتنی (rRNA) نیز به دلیل فعالیت آنزیمی خود دارای ساختار سه بعدی و شکل فضایی معین است. مورد دوم: همه انواع رناها و دناهای یاخته؛ مولکول های حامل اطلاعات وراثتی محسوب می شوند و همگی نوعی مولکول اطلاعاتی هستند. مورد سوم: همۀ انواع رناها و دناهای یاخته بسپارهایی (پلیمرهایی) از واحدهای تکرارشونده نوکلئوتیدی هستند. مورد چهارم: تنها برخی رناهای پیک در یاخته های پروکاریوتی می تواند حاوی رونوشت چندین ژن باشد. مورد پنجم: طبق شکل کتاب درسی، رنای پیک، با هر دو زیرواحد کوچک و بزرگ ریبوزوم تماس دارد. رنای ناقل فقط با زیرواحد بزرگ ریبوزوم تماس دارد. رنای رناتنی (rRNA) نیز در ساختار هر دو زیرواحد ریبوزوم حضور دارد. با توجه به توضیحات بالا، سه مورد (موارد اول، دوم و سوم) در خصوص رنای ناقل، چهار مورد (همه موارد به جز مورد اول) در خصوص رنای پیک و چهار مورد (همه موارد به جز مورد چهارم) در خصوص رنای رناتنی صحیح است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"دو دوازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1690\":{\"correct_option_id\":47521,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 2\\r\\n\\r\\nدر دو زوج مرتب اول، مؤلفه دوم، برابر a است، پس:\\r\\n\\r\\n$b^2 - b = 2 \\\\Rightarrow b = -1, 2$\\r\\n\\r\\nبه ازای $b = -1$ زوج مرتب‌های سوم و چهارم دارای مؤلفه دوم برابر می‌شوند پس $b = 2$، قابل قبول است.\\r\\n\\r\\n$\\\\begin{cases} f(2) = a \\\\\\\\ f(2) = 2 \\\\end{cases} \\\\Rightarrow a = 2$\\r\\n\\r\\nبه ازای $a = 2$ تابع $2x$ اکیداً صعودی و چون $[x]$ صعودی است پس $2x + [x]$ اکیداً صعودی و در نتیجه یک به یک است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1731\":{\"correct_option_id\":47649,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 2\\r\\n\\r\\nمی‌دانیم اگر $S | \\\\begin{smallmatrix} x_s \\\\\\\\ y_s \\\\end{smallmatrix}$ رأس سهمی باشد، همواره سهمی در هر یک از بازه‌های $(-\\\\infty, x_s]$ و $[x_s, +\\\\infty)$ یک به یک است و چون تابع $y = x^2 - 2ax$ در بازه $[3, +\\\\infty)$ یک به یک است، طول نقطه رأس سهمی همان 3 است. از طرفی برای معادله درجه دوم $y = ax^2 + bx + c$ داریم $x_s = \\\\frac{-b}{2a}$ ، پس:\\r\\n\\r\\n$-\\\\frac{-2a}{2} = 3 \\\\Rightarrow a = 3$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"1786\":{\"correct_option_id\":47848,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 1\\r\\n\\r\\nدر اینجا ضابطه $-3 x $ اکیداً نزولی است و ضابطه $log_a^{\\\\frac{1}{x+7}}$ نیز اکیداً نزولی است، اگر $a > 1$ باشد. حال برد تک‌تک ضابطه‌ها را می‌یابیم:\\r\\n\\r\\n$x \\\\geq 1 \\\\rightarrow -3x \\\\leq -3 \\\\rightarrow R_1 = (-\\\\infty, -3]$\\r\\n\\r\\n$-7 < x < 1 \\\\rightarrow 0 < x + 7 < 8 \\\\xrightarrow{a>1} log_a^0 < log_a^{x+7} < log_a^8 \\\\rightarrow -log_a^{x+7} > -log_a^8$\\r\\n\\r\\nبرای اینکه دو برد اشتراک نداشته باشند، باید:\\r\\n\\r\\n$-log_a^8 \\\\geq -3 \\\\rightarrow log_a^8 \\\\leq 3 \\\\rightarrow a^3 \\\\geq 8 \\\\rightarrow a \\\\geq 2$\"},\"status\":\"correct\",\"level\":\"سخت\",\"mabhas\":\"تابع دوازدهم\",\"selected_option_id\":47848,\"is_answered\":true},\"1797\":{\"correct_option_id\":50293,\"descriptive_answer\":{\"text\":\"پاسخ: گزینه 2\\r\\n\\r\\nمی‌دانیم تابع یک‌به‌یک به ازای هر خروجی دقیقاً یک ورودی دارد، پس می‌توان نوشت:\\r\\n\\r\\n$f(x + 2f(x)) = f(2 - 3x) \\\\xrightarrow{\\\\text{f یک‌به‌یک}} x + 2f(x) = 2 - 3x \\\\Rightarrow 2f(x) = 2 - 4x \\\\Rightarrow f(x) = 1 - 2x$\\r\\n\\r\\nدر نتیجه برای محاسبه خواسته مسئله، داریم:\\r\\n\\r\\n(نمودار تابع f(x) = 1 - 2x و ناحیه محصور بین آن و محورها در مختصات رسم شده است) $S = \\\\frac{1}{2} \\\\times \\\\frac{1}{2} \\\\times 1 = \\\\frac{1}{4}$\"},\"status\":\"wrong\",\"level\":\"متوسط\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":50292,\"is_answered\":true},\"4294\":{\"correct_option_id\":72530,\"descriptive_answer\":{\"text\":\"نکته: طول رأس سهمی $y = ax^2 + bx + c$ برابر $y = -b / 2a$ است. توجه کنید که نمودار تابع $f$ یک سهمی روبه‌بالا است که طول رأس سهمی آن برابر $x_S = a - 1 / 6$ است. اکنون برای آنکه این تابع در بازه $[2, +\\\\infty)$ یک‌به‌یک باشد، باید رأس تابع، قبل از $x = 2$ باشد. $x_S \\\\le 2 \\\\Rightarrow a - 1 / 6 \\\\le 2 \\\\Rightarrow a - 1 \\\\le 12 \\\\Rightarrow a \\\\le 13$ بنابراین حداکثر مقدار $a$ برابر 13 است.\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4320\":{\"correct_option_id\":72422,\"descriptive_answer\":{\"text\":\"نکته: اگر در تابعی در زوج‌مرتب‌های متمایز، مؤلفه‌های دوم تکراری نباشد، آن تابع یک‌به‌یک است. اگر مؤلفه‌های دوم برابر باشد، باید مؤلفه‌های اول نیز برابر باشد. نکته: تابع $f^{-1}$ از جابه‌جا شدن مؤلفه‌های اول و دوم تابع $f$ به‌دست می‌آید. $\\\\begin{cases} (2m, 3) \\\\\\\\ (m^2 - 3, 3) \\\\end{cases} \\\\xrightarrow{\\\\text{مؤلفه دوم تکراری}} 2m = m^2 - 3 \\\\Rightarrow m^2 - 2m - 3 = 0 \\\\Rightarrow \\\\begin{cases} m = -1 \\\\\\\\ m = 3 \\\\end{cases}$ $m = -1 \\\\Rightarrow f = \\\\{(-2, 3), (6, 6)\\\\} \\\\Rightarrow$ تابعی یک‌به‌یک است. $m = 3 \\\\Rightarrow f = \\\\{(6, 3), (6, 6)\\\\} \\\\Rightarrow$ تابع نمی‌باشد؛ زیرا مؤلفه‌های اول تکراری دارد. بنابراین: $f^{-1} = \\\\{(3, -2), (6, 6)\\\\}$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4480\":{\"correct_option_id\":71718,\"descriptive_answer\":{\"text\":\"در رابطه $f(2-g(x)) = \\\\sqrt{x+1}$ قرار می‌دهیم $x=7$: $f(2-g(7)) = \\\\sqrt{8} = 2 \\\\xrightarrow{f(5)=2 \\\\text{ و f یک‌به‌یک است}} 2-g(7) = 5 \\\\Rightarrow g(7) = -3$\"},\"status\":\"unanswered\",\"level\":\"متوسط\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false},\"4905\":{\"correct_option_id\":49803,\"descriptive_answer\":{\"text\":\"گزینه 4\\r\\n\\r\\nدر توابع یک‌به‌یک مؤلفه دوم تکراری نداریم:\\r\\n\\r\\n$\\\\begin{cases} m^2 + \\\\sqrt{n} = 2 \\\\\\\\ m^2 - \\\\sqrt{n} = 0 \\\\end{cases} \\\\xrightarrow{+} 2m^2 = 2 \\\\Rightarrow m^2 = 1 \\\\Rightarrow m = \\\\pm 1$\\r\\n\\r\\n$m^2 + \\\\sqrt{n} = 2 \\\\xrightarrow{m^2 = 1} \\\\sqrt{n} = 1 \\\\Rightarrow n = 1$\\r\\n\\r\\nبه‌ازای $\\\\begin{cases} m = 1 \\\\\\\\ n = 1 \\\\end{cases}$، رابطه f تابع خواهد بود و $ 2 m - n = 1$ است و به‌ازای $\\\\begin{cases} m = -1 \\\\\\\\ n = 1 \\\\end{cases}$ نیز f تابع است و $ 2 m - n = -3$ است.\"},\"status\":\"unanswered\",\"level\":\"آسان\",\"mabhas\":\"تابع يازدهم\",\"selected_option_id\":null,\"is_answered\":false}},\"submission\":{\"submittedAnswers\":{\"495\":6413,\"893\":6591,\"895\":6577,\"1786\":47848,\"1797\":50292},\"submittedQuestionIds\":[898,894,4320,4294,895,495,1731,1797,4480,1690,1786,903,4905,893,896],\"totalTimeSpent\":18,\"questionTimes\":{\"893\":991,\"894\":2007,\"895\":1003,\"896\":4012},\"selectionLog\":[{\"questionId\":1786,\"optionId\":47848,\"timeSpentMs\":0,\"timestamp\":1789898039135},{\"questionId\":893,\"optionId\":6591,\"timeSpentMs\":991,\"timestamp\":1789898041479},{\"questionId\":495,\"optionId\":6413,\"timeSpentMs\":0,\"timestamp\":1789898043231},{\"questionId\":895,\"optionId\":6577,\"timeSpentMs\":1003,\"timestamp\":1789898044191},{\"questionId\":1797,\"optionId\":50292,\"timeSpentMs\":0,\"timestamp\":1789898046527}]}}', '2026-09-20 09:54:09');
