INSERT INTO `tam24_ai_books` (`id`, `title`, `subject`, `grade`, `publisher`, `pdf_url`, `content_text`, `content_summary`, `is_active`, `sort_order`, `created_at`, `updated_at`, `subject_key`) VALUES
(1, 'فیزیک دهم — چاپ ۱۴۰۳', 'فیزیک', 'دهم', 'آموزش و پرورش', '/books/physics-10.pdf', NULL, 'کتاب درسی فیزیک پایه دهم: اندازه‌گیری، کار و انرژی، ویژگی‌های فیزیکی مواد، دما و گرما.', 1, 1, '2026-08-14 14:02:33', '2026-08-14 14:02:33', NULL),
(2, 'ریاضی دهم — چاپ ۱۴۰۳', 'ریاضی', 'دهم', 'آموزش و پرورش', '/books/math-10.pdf', NULL, 'کتاب درسی ریاضی پایه دهم: مجموعه‌ها، الگو و دنباله، توان‌های گویا، معادله‌ها و نامعادله‌ها، تابع، شمارش و احتمال.', 1, 2, '2026-08-14 14:02:33', '2026-08-14 14:02:33', NULL),
(3, 'شیمی دهم — چاپ ۱۴۰۳', 'شیمی', 'دهم', 'آموزش و پرورش', '/books/chemistry-10.pdf', NULL, 'کتاب درسی شیمی پایه دهم: کیهان زادگاه الفبای هستی، ردپای گازها در زندگی، آب آهنگ زندگی.', 1, 3, '2026-08-14 14:02:33', '2026-08-14 14:02:33', NULL);
