(1, 1, 'Hey', NULL, NULL, 2, 1129, '2026-09-15 13:09:41', NULL, '2026-09-15 13:09:39', '2026-09-15 13:09:45', 'math', 1, 'chat', NULL, NULL),
(2, 1, 'فصل یک یازدهم', NULL, NULL, 2, 2334, '2026-09-15 13:13:26', NULL, '2026-09-15 13:13:13', '2026-09-15 13:13:26', 'biology', 0, 'quiz_question', 11039, '{\"questionId\":11039,\"questionText\":\"مطابق با مطالب کتاب درسی، کدام ویژگی مربوط به همهٔ سیناپس‌های فعالی است که یاخته‌های عصبی به منظور انتقال پیام به یاختهٔ دیگری برقرار می‌کنند؟\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار یک ( پیام عصبی چگونه ایجاد و منتقل میشود)\",\"topic\":\"فصل یک یازدهم\",\"category\":\"علوم تجربی\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار یک ( پیام عصبی چگونه ایجاد و منتقل میشود)\",\"choices\":[{\"id\":62600,\"index\":1,\"text\":\"۱) به‌طورحتم به دنبال تغییر شکل فضایی پروتئین، یاختهٔ پس‌سیناپسی تحریک می‌شود.\",\"isCorrect\":false,\"isSelected\":true},{\"id\":62601,\"index\":2,\"text\":\"۲) به‌طورحتم دو ناقل عصبی به‌طور هم‌زمان به نوعی کانال غشایی نورون پس‌سیناپسی متصل می‌شوند.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":62602,\"index\":3,\"text\":\"۳) به‌طورحتم پس از آزادسازی ناقل عصبی، اتصال آن به گیرنده سطح یاختهٔ پس‌سیناپسی بدون مصرف ATP رخ می‌دهد.\",\"isCorrect\":true,\"isSelected\":false},{\"id\":62603,\"index\":4,\"text\":\"۴) به‌طورحتم با رسیدن پیام عصبی به پایانهٔ آکسون، ریزکیسه‌های حاوی ناقل عصبی با برون‌رانی وارد فضای سیناپسی می‌شوند.\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":62600,\"index\":1,\"text\":\"۱) به‌طورحتم به دنبال تغییر شکل فضایی پروتئین، یاختهٔ پس‌سیناپسی تحریک می‌شود.\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":62602,\"index\":3,\"text\":\"۳) به‌طورحتم پس از آزادسازی ناقل عصبی، اتصال آن به گیرنده سطح یاختهٔ پس‌سیناپسی بدون مصرف ATP رخ می‌دهد.\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"به منظور اتصال ناقل عصبی به گیرندۀ خود در سطح یاختۀ پس‌سیناپسی، نیازی به مصرف $ATP$ نیست! بررسی سایر گزینه‌ها: $1$ با اتصال ناقل عصبی به گیرندۀ پروتئینی خود، یاختۀ پس‌سیناپسی تحریک یا مهار (نه همواره تحریک) می‌شود. فعالیت گیرنده ناقل عصبی، با تغییرشکل فضایی آن همراه است. $2$ مطابق شکل، دو مولکول ناقل عصبی به‌طور هم‌زمان به نوعی کانال غشایی در یاختۀ پس‌سیناپسی متصل می‌شوند. اما دقت داشته باشید که یاخته پس‌سیناپسی، همواره نورون نیست و ممکن است یاختۀ ماهیچه‌ای یا یاختۀ غده نیز باشد. $4$ نه نه ..... فقط ناقل‌های عصبی (نه ریزکیسه‌های حاوی ناقل عصبی!) با برون‌رانی وارد فضای سیناپسی می‌شوند.\",\"tags\":[\"زیست شناسی\",\"یازدهم\",\"گفتار یک ( پیام عصبی چگونه ایجاد و منتقل میشود)\",\"فصل یک یازدهم\",\"متوسط\"]}'),
(3, 4, 'آمار', NULL, NULL, 2, 1718, '2026-09-15 13:17:08', NULL, '2026-09-15 13:16:56', '2026-09-15 13:17:08', 'math', 0, 'quiz_question', 2863, '{\"questionId\":2863,\"questionText\":\"به ترتیب «مجموعه تمام افراد یا اشیایی که درباره یک یا چند ویژگی آن‌ها تحقیق صورت می‌گیرد ............» و «در علم آمار، به مرحله بعد از جمع‌آوری اعداد، ............ می‌گویند.»\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":null,\"topic\":\"آمار\",\"category\":\"آمار\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":null,\"choices\":[{\"id\":75132,\"index\":1,\"text\":\"جامعه - تحلیل و تفسیر داده‌ها\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75133,\"index\":2,\"text\":\"جمعیت - اندازه‌گیری\",\"isCorrect\":false,\"isSelected\":true},{\"id\":75134,\"index\":3,\"text\":\"جامعه - قضاوت و پیش‌بینی\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75135,\"index\":4,\"text\":\"جمعیت - سازماندهی و نمایش\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":75133,\"index\":2,\"text\":\"جمعیت - اندازه‌گیری\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":75135,\"index\":4,\"text\":\"جمعیت - سازماندهی و نمایش\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\". گزینه 4 درست است. به مجموعه تمام افراد یا اشیایی که دربارهٔ یک یا چند ویژگی آنها تحقیق صورت می‌گیرد، جامعه یا جمعیت می‌گویند. مراحل علم آمار در شکل زیر کامل شده است. قضاوت و پیش‌بینی < تحلیل و تفسیر داده‌ها < سازماندهی و نمایش < جمع‌آوری اعداد و ارقام\",\"tags\":[\"ریاضیات\",\"دهم\",\"آمار\",\"آسان\"]}'),
(4, 4, 'چند نمونه از خطاهای رایج در حل نامعادله نشان بده و از من بخو', NULL, NULL, 4, 7519, '2026-09-22 15:37:26', NULL, '2026-09-15 14:20:39', '2026-09-22 15:37:26', 'math', 1, 'chat', NULL, NULL),
(5, 4, 'پنج دوازدهم', NULL, NULL, 2, 5181, '2026-09-15 14:22:08', NULL, '2026-09-15 14:21:38', '2026-09-15 14:22:08', 'biology', 0, 'quiz_question', 12589, '{\"questionId\":12589,\"questionText\":\"کدام موارد، جملۀ زیر را به‌درستی کامل می‌نماید؟ «در بدن یک انسان سالم و بالغ، به‌دنبال افزایش ترشح هورمون محرک تیروئید، .................... افزایش می‌یابد.» الف) تولید و مصرف پیرووات در یاختۀ ماهیچۀ اسکلتی ب) فعالیت آنزیمی با پیش‌ماده‌های غیرآلی در فراوان‌ترین یاخته‌های خونی ج) تولید استیل‌کوآنزیم $A$ در یاخته‌های مقعرالطرفین درون نوعی بافت پیوندی د) کاهش اتانال به اتانول در یاختۀ بندارۀ خارجی مخرج در شرایط کاهش اکسیژن\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار دو( مروری بر تنظیم تنفس یاخته ای و تنظیم آن )\",\"topic\":\"پنج دوازدهم\",\"category\":\"پنج دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار دو( مروری بر تنظیم تنفس یاخته ای و تنظیم آن )\",\"choices\":[{\"id\":68986,\"index\":1,\"text\":\"«الف» برخلاف «ب»\",\"isCorrect\":false,\"isSelected\":false},{\"id\":68987,\"index\":2,\"text\":\"«ب» برخلاف «د»\",\"isCorrect\":true,\"isSelected\":true},{\"id\":68988,\"index\":3,\"text\":\"«ج» همانند «د»\",\"isCorrect\":false,\"isSelected\":false},{\"id\":68989,\"index\":4,\"text\":\"«الف» همانند «د»\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":68987,\"index\":2,\"text\":\"«ب» برخلاف «د»\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":68987,\"index\":2,\"text\":\"«ب» برخلاف «د»\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"بررسی موارد: الف) درست. هورمون محرک تیروئید با افزایش هورمون‌های تیروئیدی و تجزیۀ گلوکز، تولید و مصرف پیرووات را افزایش می‌دهد. ب) درست. افزایش تجزیۀ گلوکز، می‌تواند منجر به افزایش تولید $CO_2$ و افزایش فعالیت آنزیم کربنیک‌انیدراز گلبول قرمز شود. ج) نادرست. در گلبول قرمز، استیل‌کوآنزیم $A$ تولید نمی‌شود. د) نادرست. در بدن انسان، تخمیر الکلی انجام نمی‌شود.\",\"tags\":[\"زیست شناسی\",\"دوازدهم\",\"گفتار دو( مروری بر تنظیم تنفس یاخته ای و تنظیم آن )\",\"پنج دوازدهم\",\"متوسط\"]}'),
(6, 120, 'فصل یک یازدهم', NULL, NULL, 6, 8936, '2026-09-16 12:12:22', NULL, '2026-09-16 12:11:39', '2026-09-16 12:12:22', 'chemistry', 0, 'quiz_question', 6362, '{\"questionId\":6362,\"questionText\":\"با توجه به داده‌های جدول زیر که «برآورد مقدار برخی عنصرها در جهان» را نشان می‌دهد، به دو پرسش بعدی پاسخ دهید. | $_{82}\\\\text{Pb}$ | $_{50}\\\\text{Sn}$ | $_{29}\\\\text{Cu}$ | $_{49}\\\\text{In}$ | $_{92}\\\\text{U}$ | $_{22}\\\\text{Ti}$ | عنصر | |---|---|---|---|---|---|---| | $1/44 \\\\times 10^8$ | $1/12 \\\\times 10^7$ | $9/37 \\\\times 10^8$ | $6/0 \\\\times 10^3$ | $3/30 \\\\times 10^6$ | $1/53 \\\\times 10^5$ | مقدار (تن) | ۱- در رابطه با این عنصرها، چه تعداد از مطالب زیر، نادرست‌اند؟ - هیچ دو عنصری، در یک گروه از جدول دوره‌ای قرار ندارند. - تنها یکی از این عنصرها، با گاز نجیب کریپتون، هم‌دوره است. - هیچ یک از این عنصرها، به دستهٔ f جدول دوره‌ای تعلق ندارد. - در نوشتن آرایش الکترونی فشردهٔ اتم نیمی از این عنصرها، از گاز نجیب آرگون استفاده می‌شود.\",\"subjectKey\":\"chemistry\",\"subject\":\"شیمی\",\"lesson\":\"نور+ساختار اتم  و آرایش الکترونی آن\",\"topic\":\"فصل یک یازدهم\",\"category\":\"فصل یک یازدهم\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"نور+ساختار اتم  و آرایش الکترونی آن\",\"choices\":[{\"id\":47452,\"index\":1,\"text\":\"۱\",\"isCorrect\":false,\"isSelected\":false},{\"id\":47453,\"index\":2,\"text\":\"۲\",\"isCorrect\":false,\"isSelected\":true},{\"id\":47454,\"index\":3,\"text\":\"۳\",\"isCorrect\":false,\"isSelected\":false},{\"id\":47455,\"index\":4,\"text\":\"۴\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":47453,\"index\":2,\"text\":\"۲\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":47455,\"index\":4,\"text\":\"۴\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"1. گزینه 4 درست است. عنصرهای قلع و سرب، در گروه 14 جدول دوره‌ای عنصرها قرار دارند (علت نادرستی مطلب اول). عنصرهای تیتانیم و مس، با گاز نجیب کریپتون، هم دوره‌اند (علت نادرستی مطلب دوم). عنصر اورانیم در دستۀ f جدول دوره‌ای عنصرها قرار دارد (علت نادرستی مطلب سوم). در نوشتن آرایش الکترونی فشردۀ عنصرهای تیتانیم و مس، از گاز نجیب آرگون استفاده می‌شود. (علت نادرستی مطلب چهارم). بنابراین، هر چهار مطلب پیشنهاد شده، نادرست‌اند.\",\"tags\":[\"شیمی\",\"یازدهم\",\"نور+ساختار اتم  و آرایش الکترونی آن\",\"فصل یک یازدهم\",\"متوسط\"]}'),
(7, 1, 'فصل دو دهم', NULL, NULL, 2, 2065, '2026-09-16 23:31:28', NULL, '2026-09-16 23:31:08', '2026-09-16 23:31:28', 'chemistry', 0, 'quiz_question', 5836, '{\"questionId\":5836,\"questionText\":\"16- در واکنش تجزیه پتاسیم پرمنگنات در یک ظرف سرباز، در یک بازه زمانی معین حجم گاز اکسیژن در شرایط استاندارد از mL1342 به 2238 mL رسیده است. در همین مدت، جرم مواد موجود در ظرف چند گرم کاهش یافته است؟ $(K=39 , Mn=55 , O=16\\\\ g.mol^{-1})$ (واکنش موازنه شده نیست.) $KMnO_4(s)\\\\xrightarrow{\\\\Delta}K_2MnO_4(s)+MnO_2(s)+O_2(g)$\",\"subjectKey\":\"chemistry\",\"subject\":\"شیمی\",\"lesson\":\"استوکیومتری و واکنش‌ها\",\"topic\":\"فصل دو دهم\",\"category\":\"فصل دو دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"استوکیومتری و واکنش‌ها\",\"choices\":[{\"id\":26703,\"index\":1,\"text\":\"3.20\",\"isCorrect\":false,\"isSelected\":true},{\"id\":26704,\"index\":2,\"text\":\"2.56\",\"isCorrect\":false,\"isSelected\":false},{\"id\":26705,\"index\":3,\"text\":\"1.44\",\"isCorrect\":false,\"isSelected\":false},{\"id\":26706,\"index\":4,\"text\":\"1.28\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":26703,\"index\":1,\"text\":\"3.20\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":26706,\"index\":4,\"text\":\"1.28\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"از روی افزایش حجم اکسیژن، تعداد مول و در نتیجه جرم آن را به دست می آوریم. مطابق قانون پایستگی ماده، افزایش جرم گاز تولید شده، معادل کاهش جرم مواد موجود در ظرف (مواد جامد) است . $?gO2 = (2238 - 1342)mL O2 × 1 mol O2 / 22400 mL O2$ $× 32g O2 / 1mol O2 = 1.28g O2$\",\"tags\":[\"شیمی\",\"دهم\",\"استوکیومتری و واکنش‌ها\",\"فصل دو دهم\",\"متوسط\"]}'),
(8, 112, 'فصل دو یازدهم', NULL, NULL, 4, 4501, '2026-09-17 10:12:35', NULL, '2026-09-17 10:11:24', '2026-09-17 10:12:35', 'physics', 0, 'quiz_question', 8032, '{\"questionId\":8032,\"questionText\":\"تعداد ۵ عدد لامپ را که روی هریک از آن‌ها ($100 \\\\text{ W}, 200 \\\\text{ V}$) نوشته شده است به‌صورت موازی به یکدیگر می‌بندیم و دو سر مجموعه را به یک باتری با نیروی محرکه $220 \\\\text{ V}$ وصل می‌کنیم. مقاومت درونی باتری چند اهم باشد تا هریک از لامپ‌ها با بیشینه توان خود روشن شوند و هیچ‌یک از آن‌ها نسوزند؟\",\"subjectKey\":\"physics\",\"subject\":\"فیزیک\",\"lesson\":\"توان و انرژی\",\"topic\":\"فصل دو یازدهم\",\"category\":\"فصل دو یازدهم\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"سخت\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"توان و انرژی\",\"choices\":[{\"id\":43748,\"index\":1,\"text\":\"۱۰\",\"isCorrect\":false,\"isSelected\":false},{\"id\":43749,\"index\":2,\"text\":\"۱۲\",\"isCorrect\":false,\"isSelected\":false},{\"id\":43750,\"index\":3,\"text\":\"۸\",\"isCorrect\":true,\"isSelected\":true},{\"id\":43751,\"index\":4,\"text\":\"۶\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":43750,\"index\":3,\"text\":\"۸\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":43750,\"index\":3,\"text\":\"۸\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"123- گزینه «3» در صورتی لامپ ها با بیشینه توان خود روشن می شوند که اختلاف پتانسیل مصرفی دو سر لامپ ها (همان اختلاف پتانسیل دو سر باتری) با اختلاف پتانسیل اسمی آن ها ($200V$) یکسان باشد. بنابراین، ابتدا مقاومت معادل لامپ ها را می یابیم: $Req = R/n → R=V2/P → Req = V2/P / n ⇒ Req = V2/nP → n=5, V=200V / P=100W →$ $Req = 2002 / 5×100 ⇒ Req = 80Ω$ اکنون، به صورت زیر مقاومت داخلی باتری را حساب می کنیم: $I = ε / Req+r$ $V = ReqI → V = Reqε / Req+r → ε=220V / V=200V →$ $200 = 80×220 / 80+r ⇒ 2 = 8×22 / 80+r ⇒ 80+r = 88 ⇒ r = 8Ω$\",\"tags\":[\"فیزیک\",\"یازدهم\",\"توان و انرژی\",\"فصل دو یازدهم\",\"سخت\"]}'),
(9, 112, 'آشنایی با دستیار آموزشی', NULL, NULL, 4, 2276, '2026-09-26 09:08:53', NULL, '2026-09-20 08:36:58', '2026-09-26 09:08:53', 'general', 1, 'chat', NULL, NULL),
(10, 4, 'چهار دوازدهم', NULL, NULL, 4, 4783, '2026-09-20 09:51:06', NULL, '2026-09-20 09:49:09', '2026-09-20 09:51:06', 'biology', 0, 'quiz_question', 911, '{\"questionId\":911,\"questionText\":\"جهش ها براساس عوامل ایجاد کننده آن ها به چند دسته تقسیم می شوند. چند مورد درباره جهشی درست است که در اثر عواملی با تشکیل دوپار (دیمر) تیمین درون نوعی ژن یاخته های پوست انسان همراه است؟ الف: باعث تشکیل پیوندهای هیدروژنی میان دو نوکلئوتید پیریمیدینی در یک رشته دنا (DNA) می شود. ب: باعث اختلال در حرکت آنزیم دنابسپار از بر روی نوکلئوتیدهای مولکول دنا (DNA) می شود. ج: ممکن است سبب القای فعالیت آنزیم های تجزیه کننده پروتئین ها در یاخته شود. د: ناشی از مصرف ترکیباتی نظیر بنزوپیرن در دود سیگار و قلیان است.\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار یک ( پیامدها و علت جهش)\",\"topic\":\"چهار دوازدهم\",\"category\":\"علوم تجربی\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار یک ( پیامدها و علت جهش)\",\"choices\":[{\"id\":6557,\"index\":1,\"text\":\"1\",\"isCorrect\":false,\"isSelected\":false},{\"id\":6558,\"index\":2,\"text\":\"2\",\"isCorrect\":true,\"isSelected\":false},{\"id\":6559,\"index\":3,\"text\":\"3\",\"isCorrect\":false,\"isSelected\":true},{\"id\":6560,\"index\":4,\"text\":\"4\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":6559,\"index\":3,\"text\":\"3\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":6558,\"index\":2,\"text\":\"2\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"گزینه&laquo;2&raquo; موارد &laquo;ب&raquo; و &laquo;ج&raquo; درست هستند. بررسی همه موارد: الف) در دوپار تیمین، پیوندهای اشتراکی میان دو باز آلی تیمین مجاور هم (نوکلئوتیدهای پیریمیدینی) در یک رشته از دنا ایجاد می شود؛ نه پیوندهای هیدروژنی (امکان تشکیل پیوند هیدروژنی بین این بازهای آلی وجود ندارد). همچنین توجه داشته باشید این پیوندهای اشتراکی از نوع فسفودی استر نیستند. ب) اتصال دو باز آلی تیمین مجاور هم در یک رشته از مولکول دنا، سبب تغییر حالت (شکل) مولکول دنا در این بخش می شود، پس می تواند سبب اختلال در حرکت آنزیم دنابسپاراز بر روی نوکلئوتیدهای ژن شود. ج) این فرایند، نوعی تغییر در مولکول دنا محسوب می شود. در صورت عدم اصلاح این آسیب، و ماندگار شدن آن، طی چرخه یاخته ای، ممکن است نقطه وارسی \\\\(G_1\\\\) سبب راه اندازی فرایند مرگ برنامه ریزی شده شود. در این حالت پروتئین های تخریب کننده خود یاخته (آنزیم های درون یاخته ای) به سرعت فعال شده و به تجزیه یاخته می پردازند. د) دوپار تیمین به دلیل برخورد اشعه فرابنفش خورشید به یاخته ها ایجاد می شود و نوعی جهش در اثر عوامل جهش زای فیزیکی محسوب می شود. بنزوپیرن که در دود سیگار یافت می شود. از جمله ترکیبات شیمیایی مؤثر در ایجاد جهش است.\",\"tags\":[\"زیست شناسی\",\"دوازدهم\",\"گفتار یک ( پیامدها و علت جهش)\",\"چهار دوازدهم\",\"متوسط\"]}'),
(11, 4, 'یک دوازدهم', NULL, NULL, 0, 0, '2026-09-20 10:18:33', NULL, '2026-09-20 10:18:33', '2026-09-20 10:18:33', 'biology', 0, 'quiz_question', 12028, '{\"questionId\":12028,\"questionText\":\"کدام موارد زیر، دربارهٔ همهٔ مولکول‌هایی درست هستند که در بدن انسان، به‌صورت کاتالیزورهای زیستی عمل می‌کنند؟ الف: جایگاهی با شکل مشابه کل یا بخشی از پیش‌ماده دارند. ب: به کوآنزیم‌ها یا ترکیبات غیرآلی برای فعالیت نیاز دارند. ج: یک یا بیش از یک نوع واکنش را سرعت می‌بخشند. د: روی یک یا چند پیش‌مادهٔ خاص مؤثر هستند.\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار سه ( نقش پروتئین ها )\",\"topic\":\"یک دوازدهم\",\"category\":\"یک دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار سه ( نقش پروتئین ها )\",\"choices\":[{\"id\":66748,\"index\":1,\"text\":\"«الف» و «ب»\",\"isCorrect\":false,\"isSelected\":false},{\"id\":66749,\"index\":2,\"text\":\"«ب»، «ج» و «د»\",\"isCorrect\":false,\"isSelected\":false},{\"id\":66750,\"index\":3,\"text\":\"«ج» و «د»\",\"isCorrect\":true,\"isSelected\":true},{\"id\":66751,\"index\":4,\"text\":\"«الف»، «ب»، «ج» و «د»\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":66750,\"index\":3,\"text\":\"«ج» و «د»\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":66750,\"index\":3,\"text\":\"«ج» و «د»\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"(پاسخ گزینه:3 ) موارد «ج» و «د» صحیح هستند. آنزیم ها، کاتالیزورهای زیستی هستند. بررسی موارد: الف: همه آنزیم ها دارای جایگاه فعال هستند که شکل آن، مکمل (نه مشابه) کل یا بخشی از پیش ماده است. ب: بعضی (نه همه) آنزیم ها برای فعالیت به یون های فلزی (نظیر آهن) یا کوآنزیم ها (نظیر ویتامین ها) نیاز دارند. ج: اگرچه آنزیم ها عملی اختصاصی دارند ولی برخی از آن ها بیش از یک نوع واکنش را سرعت می بخشند. د: هر آنزیم روی یک یا چند پیش ماده خاص مؤثر است.\",\"tags\":[\"زیست شناسی\",\"دوازدهم\",\"گفتار سه ( نقش پروتئین ها )\",\"یک دوازدهم\",\"متوسط\"]}'),
(12, 4, 'یک دوازدهم', NULL, NULL, 2, 2489, '2026-09-20 10:19:46', NULL, '2026-09-20 10:19:32', '2026-09-20 10:19:46', 'biology', 0, 'quiz_question', 12006, '{\"questionId\":12006,\"questionText\":\"چند مورد از موارد زیر در ارتباط با متنوع‌ترین گروه مولکول‌های زیستی از نظر ساختار شیمیایی و عملکردی درست است؟ الف- فراوردۀ یک آنزیم ممکن نیست مجدداً به عنوان پیش‌مادۀ همان آنزیم مورد استفاده قرار بگیرد. ب- دمای مورد نیاز برای بهترین عملکرد یک آنزیم مشخص ممکن است با توجه به محیط متفاوت باشد. ج- اگر در سلولی ژن یک پروتئین وجود نداشته باشد، ممکن نیست خود آن پروتئین در سلول دیده شود. د- یک آنزیم ممکن است در محیط‌هایی با $pH$ کاملاً متفاوت بتواند به درستی فعالیت خود را به انجام برساند.\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار سه ( نقش پروتئین ها )\",\"topic\":\"یک دوازدهم\",\"category\":\"یک دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار سه ( نقش پروتئین ها )\",\"choices\":[{\"id\":66660,\"index\":1,\"text\":\"$1$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":66661,\"index\":2,\"text\":\"$2$\",\"isCorrect\":true,\"isSelected\":false},{\"id\":66662,\"index\":3,\"text\":\"$3$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":66663,\"index\":4,\"text\":\"$4$\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":66660,\"index\":1,\"text\":\"$1$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":66661,\"index\":2,\"text\":\"$2$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"(پاسخ گزینه:2 ) موارد ب و د درست هستند. الف آنزیم دنا بسپاراز نوکلئوتیدها را به هم می چسباند و رشته ی پلی نوکلئوتیدی تولید می کند (فراورده). در صورتی که اشتباهی در روند تولید این رشته وجود داشته باشد، این آنزیم باید این بار از این رشته به عنوان پیش ماده استفاده کند تا نوکلئوتید اشتباهی را از جای خود بردارد. ب آنزیم هایی که در بدن جانداران مشترک هستند لزوماً در یک دمای مشترک فعالیت نمی کنند. مثلاً دنابسپاراز در بدن ما در دمای $37$ درجه بهترین فعالیت را دارد اما در بدن جانداران دیگر لزوماً این گونه نیست. مثلاً برخی از جانوران خون سرد هستند و دمای بدن آن ها پایین تر از $37$ درجه است (مثل مار) و یا برخی جانداران در آب های داغی زندگی می کنند که دمای آن بیشتر از $37$ درجه است. ج گلبول قرمز بالغ نوعی سلول زنده است که فاقد هسته و ژن است. درحالی که درون آن انواعی از پروتئین ها وجود دارد. د آنزیم لیزوزیم آنزیمی پروتئینی است که می تواند در $pH$ های متفاوت به درستی فعالیت کند. مثلاً این آنزیم در دهان و معده و روده ی باریک فعالیت دارد با اینکه $pH$ این بخش ها کاملاً با هم متفاوت است.\",\"tags\":[\"زیست شناسی\",\"دوازدهم\",\"گفتار سه ( نقش پروتئین ها )\",\"یک دوازدهم\",\"متوسط\"]}'),
