(15, 4, 'فصل دو یازدهم', NULL, NULL, 2, 1671, '2026-09-22 22:01:48', NULL, '2026-09-22 22:01:29', '2026-09-22 22:01:48', 'biology', 0, 'quiz_question', 8634, '{\"questionId\":8634,\"questionText\":\"33-کدام گزینه در ارتباط با یک برجستگی روی زبان به درستی بیان شده است؟\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار دو ( چشایی )\",\"topic\":\"فصل دو یازدهم\",\"category\":\"فصل دو یازدهم\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار دو ( چشایی )\",\"choices\":[{\"id\":52667,\"index\":1,\"text\":\"ضخامت بافت پوششی سنگفرشی چند لایه، در بخش‌های کناری نسبت بخش بالایی بیشتر است.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":52668,\"index\":2,\"text\":\"بافت پیوندی پشتیبان، در مجاورت جوانه‌ها به بخش‌هایی از بافت پوششی زبان نفوذ می‌کند.\",\"isCorrect\":false,\"isSelected\":true},{\"id\":52669,\"index\":3,\"text\":\"گیرنده‌های چشایی غیرمجاور، می‌توانند با یک یاخته عصبی ارتباط شیمیایی برقرار کنند.\",\"isCorrect\":true,\"isSelected\":false},{\"id\":52670,\"index\":4,\"text\":\"یک یاخته پوششی سنگفرشی نمی‌تواند در تشکیل بیش از یک منفذ شرکت کند.\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":52668,\"index\":2,\"text\":\"بافت پیوندی پشتیبان، در مجاورت جوانه‌ها به بخش‌هایی از بافت پوششی زبان نفوذ می‌کند.\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":52669,\"index\":3,\"text\":\"گیرنده‌های چشایی غیرمجاور، می‌توانند با یک یاخته عصبی ارتباط شیمیایی برقرار کنند.\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"33 بر اساس شکل کتاب درسی یک یاخته عصبی، اطلاعات حسی مربوط به یک جوانه چشایی توسط یک رشته ارسال می‌شود. بررسی سایر گزینه‌ها: 1 ضخامت بافت پوششی در بخش‌های جانبی کمتر و در بخش بالایی بیشتر می‌باشد. 2 نفوذ بافت پیوندی به بافت پوششی در بخش‌های بالایی دیده می‌شود. 4 بر اساس شکل یک یاخته سنگفرشی می‌تواند در تشکیل دو منفذ چشایی مؤثر باشد.\",\"tags\":[\"زیست شناسی\",\"یازدهم\",\"گفتار دو ( چشایی )\",\"فصل دو یازدهم\",\"متوسط\"]}'),
