(23, 9, 'فصل یک یازدهم', NULL, NULL, 2, 6290, '2026-09-27 07:02:06', NULL, '2026-09-27 07:01:43', '2026-09-27 07:02:06', 'physics', 0, 'quiz_question', 7701, '{\"questionId\":7701,\"questionText\":\"سه کره رسانای کوچک و مشابه $A$، $B$ و $C$ به ترتیب دارای بارهای $q_A = 9\\\\mu C$، $q_B = 8\\\\mu C$ و $q_C = -6\\\\mu C$ روی یک خط راست مطابق شکل زیر روی پایه‌های عایقی قرار دارند. ابتدا کره $B$ را با کره $C$ تماس داده و جدا می‌کنیم و سپس کره $B$ را با کره $A$ تماس می‌دهیم و در انتها سه کره را در مکان قبلی خود قرار می‌دهیم. برایند نیروی الکتریکی وارد بر کره $B$ در حالت جدید چند برابر حالت قبلی است؟ (شعاع کره‌ها در مقایسه با فاصله بین کره‌ها قابل صرف‌نظر است.)\",\"subjectKey\":\"physics\",\"subject\":\"فیزیک\",\"lesson\":\"بار الکتریکی+پایستگی و کوانتیده بودن بار الکتریکی\",\"topic\":\"فصل یک یازدهم\",\"category\":\"فصل یک یازدهم\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"سخت\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"بار الکتریکی+پایستگی و کوانتیده بودن بار الکتریکی\",\"choices\":[{\"id\":45820,\"index\":1,\"text\":\"۶\",\"isCorrect\":false,\"isSelected\":false},{\"id\":45821,\"index\":2,\"text\":\"$\\\\frac{6}{5}$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":45822,\"index\":3,\"text\":\"$\\\\frac{1}{6}$\",\"isCorrect\":true,\"isSelected\":false},{\"id\":45823,\"index\":4,\"text\":\"$\\\\frac{5}{6}$\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":45821,\"index\":2,\"text\":\"$\\\\frac{6}{5}$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":45822,\"index\":3,\"text\":\"$\\\\frac{1}{6}$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"(امیرحسین برادران) $42$ - گزینه «$3$» با توجه به قاعده پایستگی بار، چون کره ها مشابه اند، بار هر یک از کره ها پس از تماس با یکدیگر برابر است: $q\'_B = q\'_C = (q_B + q_C) / 2 → q_B = 8μC , q_C = -6μC → q\'_B = q\'_C = 1μC$ $q\'\'_B = q\'_A = (q\'_B + q_A) / 2 → q\'_B = 1μC , q_A = 9μC → q\'\'_B = q\'_A = 5μC$ اکنون مطابق قانون کولن برایند نیروهای وارد بر کره $B$ را در دو حالت به دست می آوریم: حالت اول) $F_B = F_AB + F_CB$ $F = k |q_1||q_2| / r^2 → F_B = k / r^2 (|q_A| × |q_B| + |q_B| × |q_C|) (*)$ حالت دوم) $F\'_B = k / r^2 (|q\'_A| × |q\'\'_B| - |q\'_C| × |q\'\'_B|) (**)$ $(*) , (**) ⇒ F\'_B / F_B = (|q\'_A| × |q\'\'_B| - |q\'_C| × |q\'\'_B|) / (|q_A| × |q_B| + |q_B| × |q_C|)$ $→ q\'_A = q\'\'_B = 5μC , q\'_C = 1μC , q_A = 9μC , q_B = 8μC , q_C = -6μC → F\'_B / F_B = (5 × 5 - 1 × 5) / (9 × 8 + 8 × 6)$ $⇒ F\'_B / F_B = 20 / 120 = 1 / 6$ (الکتریسیته ساکن) (فیزیک $2$، صفحه های $5$ تا $10$)\",\"tags\":[\"فیزیک\",\"یازدهم\",\"بار الکتریکی+پایستگی و کوانتیده بودن بار الکتریکی\",\"فصل یک یازدهم\",\"سخت\"]}'),
(24, 104, 'فصل یک یازدهم', NULL, NULL, 2, 3726, '2026-09-29 11:56:37', NULL, '2026-09-29 11:56:12', '2026-09-29 11:56:37', 'chemistry', 0, 'quiz_question', 6430, '{\"questionId\":6430,\"questionText\":\"از واکنش $۰/۲$ مول از ۲-بوتن با آب در مجاورت اسید و سپس واکنش الکل به‌دست‌آمده با مقدار کافی از استیک اسید، چند گرم از استر مربوطه به‌دست می‌آید؟ (ضریب استوکیومتری همه مواد در واکنش‌های انجام‌شده برابر یک است.) ($C = ۱۲, O = ۱۶, H = ۱ : g.mol^{-۱}$ ؛ بازده درصدی واکنش را ٪۷۰ در نظر بگیرید.)\",\"subjectKey\":\"chemistry\",\"subject\":\"شیمی\",\"lesson\":\"نفت هدیه ای شگفت انگیز _ الکان - الکین - الکن و هیدروکربن های حلقوی\",\"topic\":\"فصل یک یازدهم\",\"category\":\"فصل یک یازدهم\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"نفت هدیه ای شگفت انگیز _ الکان - الکین - الکن و هیدروکربن های حلقوی\",\"choices\":[{\"id\":47176,\"index\":1,\"text\":\"$۱۶/۲۴$\",\"isCorrect\":true,\"isSelected\":false},{\"id\":47177,\"index\":2,\"text\":\"$۲۳/۲۵$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":47178,\"index\":3,\"text\":\"$۲۸/۷۰$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":47179,\"index\":4,\"text\":\"$۳۱/۴۵$\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":47177,\"index\":2,\"text\":\"$۲۳/۲۵$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":47176,\"index\":1,\"text\":\"$۱۶/۲۴$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"۶۹. گزینه ۱ درست است. زیرا داریم: (به‌طور خلاصه) $2- -> -> CH3COOC4H9$ $1 2- $ | $116g $ --- | --- $0/2 \\\\times 70 / 100 2- $ | $x$ $x = 16/24g $\",\"tags\":[\"شیمی\",\"یازدهم\",\"نفت هدیه ای شگفت انگیز _ الکان - الکین - الکن و هیدروکربن های حلقوی\",\"فصل یک یازدهم\",\"متوسط\"]}'),
(25, 104, 'فصل یک یازدهم', NULL, NULL, 2, 0, '2026-09-29 12:02:16', NULL, '2026-09-29 12:02:11', '2026-09-29 12:02:16', 'chemistry', 0, 'quiz_question', 5193, '{\"questionId\":5193,\"questionText\":\"هر یک از نمادهای فرضی $A$، $D$ و $E$ به یکی از عنصرهای دورۀ سوم جدول دوره‌ای مربوط است. با توجه به جدول زیر کدام گزینه درست است؟\",\"subjectKey\":\"chemistry\",\"subject\":\"شیمی\",\"lesson\":\"مقدمه+الگو روندها در رفتار مواد و عنصر ها - رفتار عنصر ها و شعاع اتم\",\"topic\":\"فصل یک یازدهم\",\"category\":\"فصل یک یازدهم\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"مقدمه+الگو روندها در رفتار مواد و عنصر ها - رفتار عنصر ها و شعاع اتم\",\"choices\":[{\"id\":32094,\"index\":1,\"text\":\"مقایسۀ خصلت فلزی این سه عنصر به‌صورت $D > A > E$ می‌باشد.\",\"isCorrect\":true,\"isSelected\":false},{\"id\":32095,\"index\":2,\"text\":\"عنصر $D$ سطح صیقلی داشته و بر اثر ضربه خرد نمی‌شود.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":32096,\"index\":3,\"text\":\"در شرایط یکسان تمایل عنصر $E$ برای از دست دادن الکترون در مقایسه با عنصر $A$ کمتر است.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":32097,\"index\":4,\"text\":\"$A$ و $E$ عناصری فلزی‌اند و واکنش‌پذیری آن‌ها از فلز آهن کمتر است.\",\"isCorrect\":false,\"isSelected\":true}],\"selectedChoice\":{\"id\":32097,\"index\":4,\"text\":\"$A$ و $E$ عناصری فلزی‌اند و واکنش‌پذیری آن‌ها از فلز آهن کمتر است.\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":32094,\"index\":1,\"text\":\"مقایسۀ خصلت فلزی این سه عنصر به‌صورت $D > A > E$ می‌باشد.\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"گزینه «1» عنصرهای $A$، $D$ و $E$ به‌ترتیب $12Mg$، $14Si$ و $11Na$ می‌باشند. $14Si : )_{2e^-} )_{8e^-} )_{4e^-}$ $12Mg : )_{2e^-} )_{8e^-} )_{2e^-}$ $11Na : )_{2e^-} )_{8e^-} )_{1e^-}$ در هر دوره از جدول دوره‌ای با افزایش عدد اتمی خصلت فلزی کاهش می‌یابد. بررسی گزینه‌های نادرست: گزینه «2»: $14Si$ یک شبه‌فلز است. این شبه‌فلز سطح صیقلی داشته و بر اثر ضربه خرد می‌شود. گزینه «3»: واکنش‌پذیری فلز سدیم از فلز منیزیم بیشتر است. به بیانی دیگر تمایل سدیم برای از دست دادن الکترون بیشتر است. گزینه «4»: واکنش‌پذیری فلزهای گروه‌های 1 و 2 از فلز آهن بیشتر است.\",\"tags\":[\"شیمی\",\"یازدهم\",\"مقدمه+الگو روندها در رفتار مواد و عنصر ها - رفتار عنصر ها و شعاع اتم\",\"فصل یک یازدهم\",\"آسان\"]}'),
(26, 1, 'آمار', NULL, NULL, 2, 1802, '2026-09-29 12:19:14', NULL, '2026-09-29 12:18:51', '2026-09-29 12:19:14', 'math', 0, 'quiz_question', 2863, '{\"questionId\":2863,\"questionText\":\"به ترتیب «مجموعه تمام افراد یا اشیایی که درباره یک یا چند ویژگی آن‌ها تحقیق صورت می‌گیرد ............» و «در علم آمار، به مرحله بعد از جمع‌آوری اعداد، ............ می‌گویند.»\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":null,\"topic\":\"آمار\",\"category\":\"آمار\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":null,\"choices\":[{\"id\":75132,\"index\":1,\"text\":\"جامعه - تحلیل و تفسیر داده‌ها\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75133,\"index\":2,\"text\":\"جمعیت - اندازه‌گیری\",\"isCorrect\":false,\"isSelected\":true},{\"id\":75134,\"index\":3,\"text\":\"جامعه - قضاوت و پیش‌بینی\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75135,\"index\":4,\"text\":\"جمعیت - سازماندهی و نمایش\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":75133,\"index\":2,\"text\":\"جمعیت - اندازه‌گیری\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":75135,\"index\":4,\"text\":\"جمعیت - سازماندهی و نمایش\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\". گزینه 4 درست است. به مجموعه تمام افراد یا اشیایی که دربارهٔ یک یا چند ویژگی آنها تحقیق صورت می‌گیرد، جامعه یا جمعیت می‌گویند. مراحل علم آمار در شکل زیر کامل شده است. قضاوت و پیش‌بینی < تحلیل و تفسیر داده‌ها < سازماندهی و نمایش < جمع‌آوری اعداد و ارقام\",\"tags\":[\"ریاضیات\",\"دهم\",\"آمار\",\"آسان\"]}'),
