(28, 4, 'دو دوازدهم', NULL, NULL, 0, 0, '2026-09-30 15:08:25', NULL, '2026-09-30 15:08:25', '2026-09-30 15:08:25', 'biology', 0, 'quiz_question', 12231, '{\"questionId\":12231,\"questionText\":\"کدام مورد برای تکمیل عبارت زیر مناسب است؟ «در یک یاخته پلاسماسیست، در هر مرحله‌ای از .................... می‌شود، به‌طور طبیعی .................... .»\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار یک (رناهای ساخته شده دچار تغییر میشوند )\",\"topic\":\"دو دوازدهم\",\"category\":\"دو دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار یک (رناهای ساخته شده دچار تغییر میشوند )\",\"choices\":[{\"id\":67559,\"index\":1,\"text\":\"رونویسی که زنجیره‌ای از رنا تولید - قطعاً پیوندهای ضعیفی بین دئوکسی ریبونوکلئوتیدها شکل می‌گیرد.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":67560,\"index\":2,\"text\":\"همانندسازی که مارپیچ دنای خطی باز - ساختاری ایجاد می‌شود که در آن بیش از یک آنزیم حضور دارد.\",\"isCorrect\":false,\"isSelected\":true},{\"id\":67561,\"index\":3,\"text\":\"تغییرات رنای پیک که حین رونویسی در آن ایجاد - ممکن است با شکستن پیوندهای فسفودی استر همراه نباشد.\",\"isCorrect\":true,\"isSelected\":false},{\"id\":67562,\"index\":4,\"text\":\"پروتئین‌سازی که حداقل یک کدون، ترجمه - تشکیل پیوند پپتیدی در یکی از جایگاه‌های رناتن، دور از انتظار نیست.\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":67560,\"index\":2,\"text\":\"همانندسازی که مارپیچ دنای خطی باز - ساختاری ایجاد می‌شود که در آن بیش از یک آنزیم حضور دارد.\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":67561,\"index\":3,\"text\":\"تغییرات رنای پیک که حین رونویسی در آن ایجاد - ممکن است با شکستن پیوندهای فسفودی استر همراه نباشد.\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"(پاسخ گزینه:3) رنای پیک ممکن است دستخوش تغییراتی در حین رونویسی و یا پس از آن شود. یکی از این تغییرات، حذف بخش هایی از مولکول رنای پیک است؛ بنابراین، ممکن است این مولکول دچار تغییراتی شود که بدون شکستن پیوند فسفودی استر انجام می گیرند. بررسی سایر گزینه ها: $1$ در همه ی مراحل رونویسی، بخشی از مولکول رنا تولید می شود اما تشکیل پیوندهای هیدروژنی بین دئوکسی ریبونوکلئوتیدها در مرحله آغاز رونویسی انجام نمی گیرد. $2$ پلاسموسیت یاخته ای است که تقسیم نمی شود و بنابراین نمی تواند دنای خطی خود را همانندسازی نماید. 4 در اولین مرحله از پروتئین سازی، کدون آغاز، ترجمه می شود اما تشکیل پیوند پپتیدی در این مرحله دور از انتظار است.\",\"tags\":[\"زیست شناسی\",\"دوازدهم\",\"گفتار یک (رناهای ساخته شده دچار تغییر میشوند )\",\"دو دوازدهم\",\"متوسط\"]}'),
(29, 1, 'آمار', NULL, NULL, 0, 0, '2026-10-01 15:50:18', NULL, '2026-10-01 15:50:18', '2026-10-01 15:50:18', 'math', 0, 'quiz_question', 2854, '{\"questionId\":2854,\"questionText\":\"در کدام مورد سرشماری انجام نشده است؟\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":null,\"topic\":\"آمار\",\"category\":\"آمار\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":null,\"choices\":[{\"id\":75096,\"index\":1,\"text\":\"تمام افراد جامعه مورد مطالعه قرار گیرند.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75097,\"index\":2,\"text\":\"نمونه زیر مجموعه جامعه آماری\",\"isCorrect\":true,\"isSelected\":true},{\"id\":75098,\"index\":3,\"text\":\"اندازه نمونه برابر اندازه جامعه\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75099,\"index\":4,\"text\":\"نمونه برابر جامعه آماری\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":75097,\"index\":2,\"text\":\"نمونه زیر مجموعه جامعه آماری\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":75097,\"index\":2,\"text\":\"نمونه زیر مجموعه جامعه آماری\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\". گزینه 2 درست است. اگر نمونه زیر مجموعه جامعه آماری باشد ممکن است تمام افراد تحت مطالعه قرار نگرفته باشد سرشماری انجام نشده است.\",\"tags\":[\"ریاضیات\",\"دهم\",\"آمار\",\"متوسط\"]}'),
(30, 3, 'آمار', NULL, NULL, 0, 0, '2026-10-03 08:07:33', NULL, '2026-10-03 08:07:33', '2026-10-03 08:07:33', 'math', 0, 'quiz_question', 2863, '{\"questionId\":2863,\"questionText\":\"به ترتیب «مجموعه تمام افراد یا اشیایی که درباره یک یا چند ویژگی آن‌ها تحقیق صورت می‌گیرد ............» و «در علم آمار، به مرحله بعد از جمع‌آوری اعداد، ............ می‌گویند.»\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":null,\"topic\":\"آمار\",\"category\":\"آمار\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":null,\"choices\":[{\"id\":75132,\"index\":1,\"text\":\"جامعه - تحلیل و تفسیر داده‌ها\",\"isCorrect\":false,\"isSelected\":true},{\"id\":75133,\"index\":2,\"text\":\"جمعیت - اندازه‌گیری\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75134,\"index\":3,\"text\":\"جامعه - قضاوت و پیش‌بینی\",\"isCorrect\":false,\"isSelected\":false},{\"id\":75135,\"index\":4,\"text\":\"جمعیت - سازماندهی و نمایش\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":75132,\"index\":1,\"text\":\"جامعه - تحلیل و تفسیر داده‌ها\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":75135,\"index\":4,\"text\":\"جمعیت - سازماندهی و نمایش\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\". گزینه 4 درست است. به مجموعه تمام افراد یا اشیایی که دربارهٔ یک یا چند ویژگی آنها تحقیق صورت می‌گیرد، جامعه یا جمعیت می‌گویند. مراحل علم آمار در شکل زیر کامل شده است. قضاوت و پیش‌بینی < تحلیل و تفسیر داده‌ها < سازماندهی و نمایش < جمع‌آوری اعداد و ارقام\",\"tags\":[\"ریاضیات\",\"دهم\",\"آمار\",\"آسان\"]}');
INSERT INTO `tam24_ai_conversations` (`id`, `user_id`, `title`, `summary`, `summary_updated_at`, `message_count`, `total_tokens`, `last_message_at`, `archived_at`, `created_at`, `updated_at`, `subject_key`, `title_generated`, `source_type`, `question_id`, `question_snapshot`) VALUES
(31, 3, 'مثلثات دهم', NULL, NULL, 2, 5480, '2026-10-03 08:24:22', NULL, '2026-10-03 08:23:59', '2026-10-03 08:24:22', 'math', 0, 'quiz_question', 2238, '{\"questionId\":2238,\"questionText\":\"اگر $A = \\\\frac{\\\\cos^{4}x}{\\\\cot^{2}x - \\\\cos^{2}x}$ و $B = \\\\frac{1}{\\\\cos^{4}x}$ باشد، چه رابطه­ای بین A و B برقرار است؟\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":\"روابط مثلثاتي\",\"topic\":\"مثلثات دهم\",\"category\":\"مثلثات دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"روابط مثلثاتي\",\"choices\":[{\"id\":62136,\"index\":1,\"text\":\"$B – A – AB = 1$\",\"isCorrect\":true,\"isSelected\":false},{\"id\":62137,\"index\":2,\"text\":\"$AB = 2$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":62138,\"index\":3,\"text\":\"$AB + B = 2$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":62139,\"index\":4,\"text\":\"$A = 2B$\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":62137,\"index\":2,\"text\":\"$AB = 2$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":62136,\"index\":1,\"text\":\"$B – A – AB = 1$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"14. گزینه 1 درست است. $A = \\\\frac{\\\\cos^{4}x}{\\\\cos^{2}x(\\\\frac{1}{\\\\sin^{2}x}-1)} = \\\\frac{\\\\cos^{2}x}{\\\\frac{\\\\cos^{2}x}{\\\\sin^{2}x}} = \\\\sin^{2} x$ $B=\\\\frac{1-\\\\sin^{4}x}{\\\\cos^{4}x}=\\\\frac{(1-\\\\sin^{2}x)(1+\\\\sin^{2}x)}{\\\\cos^{4}x}=\\\\frac{2-\\\\cos^{2}x}{\\\\cos^{2}x}=\\\\frac{2}{\\\\cos^{2}x}-1$ $B+1=\\\\frac{2}{1-A} \\\\Rightarrow 1-A+B-AB=2 \\\\Rightarrow B-A-AB=1$\",\"tags\":[\"ریاضیات\",\"دهم\",\"روابط مثلثاتي\",\"مثلثات دهم\",\"متوسط\"]}'),
(32, 3, 'قوانین اصلی مدارهای سری و موازی را در چند دقیقه مرور کنیم؟ ی', NULL, NULL, 2, 3872, '2026-10-03 08:25:15', NULL, '2026-10-03 08:25:04', '2026-10-03 08:25:16', 'physics', 1, 'chat', NULL, NULL),
(33, 4, 'فصل سه یازدهم', NULL, NULL, 2, 0, '2026-10-03 09:17:40', NULL, '2026-10-03 09:17:37', '2026-10-03 09:17:40', 'biology', 0, 'quiz_question', 11208, '{\"questionId\":11208,\"questionText\":\"کدام موارد جملۀ زیر را به‌درستی کامل می‌نماید؟ «در سازوکار انقباض ماهیچۀ اسکلتی متصل به صلبیه در پی ................. » الف) مصرف ATP می‌تواند ضمن ثابت ماندن طول نوار تیره، نوار روشن کوتاه گردد ب) ورود ناقل عصبی به تار ماهیچه‌ای، کلسیم به درون تارچه وارد می‌گردد ج) تغییرشکل در ساختار چهارم مولکول میوزین دو خط Z به هم نزدیک می‌شوند د) ورود کلسیم به درون شبکۀ آندوپلاسمی شیب کلسیم بین طرفین غشای شبکۀ آندوپلاسمی کاهش می‌یابد\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار دو ( مکانیسم انقباض ماهیچه + تامین انرژی انقباض)\",\"topic\":\"فصل سه یازدهم\",\"category\":\"علوم تجربی\",\"grade\":\"یازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار دو ( مکانیسم انقباض ماهیچه + تامین انرژی انقباض)\",\"choices\":[{\"id\":63276,\"index\":1,\"text\":\"الف- ج\",\"isCorrect\":true,\"isSelected\":false},{\"id\":63277,\"index\":2,\"text\":\"ب- د\",\"isCorrect\":false,\"isSelected\":true},{\"id\":63278,\"index\":3,\"text\":\"الف- د\",\"isCorrect\":false,\"isSelected\":false},{\"id\":63279,\"index\":4,\"text\":\"ب- ج\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":63277,\"index\":2,\"text\":\"ب- د\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":63276,\"index\":1,\"text\":\"الف- ج\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"بررسی موارد: الف) درست - در طی انقباض ماهیچه اسکلتی طول نوار تیره سارکومر تغییر نمی کند، اما نوار روشن کوتاه می شود. ب) نادرست - در سیناپس نورون حرکتی با ماهیچه اسکلتی ناقل عصبی آزاد می شود، اما وارد یاخته ماهیچه ای نمی شود. ج) درست - مولکول میوزین دارای ساختار چهارم است که در طی انقباض تغییرشکلی در آن رخ می دهد. د) نادرست - ورود کلسیم به درون شبکه آندوپلاسمی با انتقال فعال است و این عمل شیب طرفین غشای شبکه آندوپلاسمی را افزایش می دهد.\",\"tags\":[\"زیست شناسی\",\"یازدهم\",\"گفتار دو ( مکانیسم انقباض ماهیچه + تامین انرژی انقباض)\",\"فصل سه یازدهم\",\"متوسط\"]}'),
(34, 130, 'فصل یک دهم', NULL, NULL, 0, 0, '2026-10-06 14:01:35', NULL, '2026-10-06 14:01:35', '2026-10-06 14:01:35', 'biology', 0, 'quiz_question', 8235, '{\"questionId\":8235,\"questionText\":\"چند مورد برای تکمیل عبارت مورد نظر مناسب است؟ «به طور معمول، .................... را می‌توان در شاخۀ .................... از زیرشاخه‌های زیست‌فناوری نوین جست‌وجو کرد.» الف) توضیح ویژگی‌های سامانه‌های پیچیده تنها با مطالعه و بررسی اجزای سازندۀ آن‌ها - کل‌نگری ب) تعریف قوانینی به منظور جلوگیری از ایجاد عامل بیماری‌زای مقاوم به داروهای رایج - اخلاق زیستی ج) استفاده از مفاهیم مهندسی و علم آمار به منظور شناخت بیشتر سامانه‌های غیرزنده - نگرش بین رشته‌ای د) انجام محاسبات در کوتاه‌ترین زمان ممکن و بایگانی پژوهش‌های زیست‌شناختی - فناوری‌های اطلاعاتی و ارتباطی\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار یک ( دنیای زنده)\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"سخت\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار یک ( دنیای زنده)\",\"choices\":[{\"id\":51243,\"index\":1,\"text\":\"1\",\"isCorrect\":false,\"isSelected\":false},{\"id\":51244,\"index\":2,\"text\":\"2\",\"isCorrect\":true,\"isSelected\":true},{\"id\":51245,\"index\":3,\"text\":\"3\",\"isCorrect\":false,\"isSelected\":false},{\"id\":51246,\"index\":4,\"text\":\"4\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":51244,\"index\":2,\"text\":\"2\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":51244,\"index\":2,\"text\":\"2\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"موارد (ب) و (د) عبارت مورد نظر را به درستی تکمیل می‌کنند. بررسی همه موارد: الف همانطور که می‌دانید در کل‌نگری، زیست‌شناسان نمی‌توانند ویژگی سامانه‌های پیچیده را فقط از طریق مطالعه اجزای سازنده آن توضیح دهند و ارتباط بین اجزا مانند خود اجزا در تشکیل جاندار مؤثر بوده و کل سامانه، چیزی بیشتر از مجموع اجزای سازنده آن است. ب در حوزه اخلاق زیستی، وضع قوانینی به منظور جلوگیری از سوءاستفاده‌ها ضرورت دارد. یکی از این سوءاستفاده‌ها می‌تواند تولید عامل بیماری‌زای مقاوم نسبت به داروهای رایج باشد. ج همانطور که در متن کتاب درسی اشاره شده است، در شاخه نگرش بین رشته‌ای، استفاده از سایر رشته‌ها مانند مفاهیم مهندسی و آمار، به منظور شناخت بیشتر سامانه‌های زنده (نه غیرزنده!) صورت می‌گیرد. د در شاخه فناوری‌های اطلاعاتی و ارتباطی، انجام محاسبات در کوتاه‌ترین زمان ممکن، جمع‌آوری، تحلیل و بایگانی پژوهش‌های زیست‌شناختی ممکن است.\",\"tags\":[\"زیست شناسی\",\"دهم\",\"گفتار یک ( دنیای زنده)\",\"فصل یک دهم\",\"سخت\"]}'),
(35, 130, 'فصل یک دهم', NULL, NULL, 0, 0, '2026-10-08 12:22:07', NULL, '2026-10-08 12:22:07', '2026-10-08 12:22:07', 'biology', 0, 'quiz_question', 10308, '{\"questionId\":10308,\"questionText\":\"42- در ارتباط با غشای یاخته‌های جانوری، کدام مورد، صحیح است؟\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار سوم ( یاخته جانوری و اندامک‌های آن)\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"سخت\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار سوم ( یاخته جانوری و اندامک‌های آن)\",\"choices\":[{\"id\":59346,\"index\":1,\"text\":\"هر پروتئین غشایی که در انتقال مواد در دو سوی غشا نقش دارد، دارای دریچه‌ای در سمت سیتوپلاسم یا مایع بین یاخته‌ای است.\",\"isCorrect\":false,\"isSelected\":true},{\"id\":59347,\"index\":2,\"text\":\"هر پروتئین غشایی که در ارتباط با فقط یک‌لایه از فسفولیپیدهای غشایی است، با مایع بین یاخته‌ای در ارتباط است.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":59348,\"index\":3,\"text\":\"هر پروتئین غشایی که به زنجیرهٔ کربوهیدراتی متصل است، در انتقال مواد در دو سوی غشا فاقد نقش است.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":59349,\"index\":4,\"text\":\"هر پروتئین غشایی که با هر دو لایهٔ غشای یاخته‌ای در ارتباط است، به فسفولیپیدهای غشایی متصل است.\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":59346,\"index\":1,\"text\":\"هر پروتئین غشایی که در انتقال مواد در دو سوی غشا نقش دارد، دارای دریچه‌ای در سمت سیتوپلاسم یا مایع بین یاخته‌ای است.\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":59349,\"index\":4,\"text\":\"هر پروتئین غشایی که با هر دو لایهٔ غشای یاخته‌ای در ارتباط است، به فسفولیپیدهای غشایی متصل است.\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"پروتئین‌های سراسری غشا، با هر دو لایۀ غشای یاخته‌ای در ارتباط هستند. این پروتئین‌ها، به فسفولیپیدهای غشایی متصل هستند. بررسی سایر گزینه‌ها: ۱) کانال‌های نشتی، ضمن انتقال مواد در دو سوی غشا، فاقد دریچه هستند. ۲) پروتئین‌هایی که فقط با یک‌لایۀ غشایی در تماس هستند، یا در سمت سیتوپلاسم یا در سمت مایع بین یاخته‌ای قرار دارند. ۳) پروتئین‌های غشایی که با سطح خارجی غشا در ارتباط هستند، می‌توانند به زنجیره‌ای از کربوهیدرات متصل باشند. پروتئین‌های سراسری که در انتقال مواد در دو سوی غشا نقش دارند نیز می‌توانند با این زنجیره‌های کربوهیدراتی در تماس باشند.\",\"tags\":[\"زیست شناسی\",\"دهم\",\"گفتار سوم ( یاخته جانوری و اندامک‌های آن)\",\"فصل یک دهم\",\"سخت\"]}'),
(36, 130, 'فصل یک دهم', NULL, NULL, 0, 0, '2026-10-08 13:06:11', NULL, '2026-10-08 13:06:11', '2026-10-08 13:06:11', 'biology', 0, 'quiz_question', 8238, '{\"questionId\":8238,\"questionText\":\"کدام مورد برای تکمیل عبارت زیر مناسب است؟ «با توجه به شکل مقابل که سطحی از سطوح سازمان‌یابی حیات را نشان می‌دهد، می‌توان گفت ....................»\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار دوم (هفت ویژگی جانداران ، سطوح سازمان یابی حیات)\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار دوم (هفت ویژگی جانداران ، سطوح سازمان یابی حیات)\",\"choices\":[{\"id\":51231,\"index\":1,\"text\":\"در یک سطح پایین‌تر، افرادی در یک مکان زندگی می‌کنند که همگی ژن‌های یکسانی دارند.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":51232,\"index\":2,\"text\":\"در یک سطح بالاتر، چندین بوم‌سازگان وجود دارد که از نظر اقلیم و پراکندگی جانداران مشابه هستند.\",\"isCorrect\":false,\"isSelected\":true},{\"id\":51233,\"index\":3,\"text\":\"در یک سطح پایین‌تر، افراد بالغ توانایی ایجاد زاده‌هایی شبیه خود با قابلیت زنده ماندن و تولیدمثل را دارند.\",\"isCorrect\":true,\"isSelected\":false},{\"id\":51234,\"index\":4,\"text\":\"در یک سطح بالاتر، اجزایی وجود دارد که همگی مجموعه اعمالی برای پایدار نگه‌داشتن وضعیت درونی خود انجام می‌دهند.\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":51232,\"index\":2,\"text\":\"در یک سطح بالاتر، چندین بوم‌سازگان وجود دارد که از نظر اقلیم و پراکندگی جانداران مشابه هستند.\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":51233,\"index\":3,\"text\":\"در یک سطح پایین‌تر، افراد بالغ توانایی ایجاد زاده‌هایی شبیه خود با قابلیت زنده ماندن و تولیدمثل را دارند.\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"شکل مورد نظر هفتمین سطح از سطوح سازمان یابی، یعنی اجتماع را نشان می دهد. یک سطح پایین تر از این سطح همان جمعیت است که در آن همه افراد متعلق به یک گونه هستند و افراد بالغ آن می توانند آمیزش موفقیت آمیز داشته باشند. یعنی می توانند زاده هایی ایجاد کنند که قابلیت زنده ماندن و تولید مثل دارند. بررسی سایر گزینه ها: $ 1 $ همه ی افراد یک جمعیت متعلق به یک گونه هستند اما لزوماً ژن های یکسانی ندارند. مثلاً ممکن است کروموزوم های جنسی در افراد نر و ماده در یک جمعیت متفاوت باشد و در نتیجه ژن های متفاوتی داشته باشد. $ 2 $ یک سطح بالاتر از اجتماع، بوم سازگان است. زیست بوم از چند بوم سازگان تشکیل شده است که از نظر اقلیم و پراکندگی جانداران با هم مشابه هستند. $ 4 $ بوم سازگان از چندین اجتماع به همراه اجزای غیرزنده تشکیل شده است. اجزای غیرزنده ویژگی های حیات را ندارند و فاقد هم ایستایی هستند.\",\"tags\":[\"زیست شناسی\",\"دهم\",\"گفتار دوم (هفت ویژگی جانداران ، سطوح سازمان یابی حیات)\",\"فصل یک دهم\",\"متوسط\"]}'),
(37, 130, 'فصل یک دهم', NULL, NULL, 0, 0, '2026-10-08 13:10:06', NULL, '2026-10-08 13:10:06', '2026-10-08 13:10:06', 'biology', 0, 'quiz_question', 8243, '{\"questionId\":8243,\"questionText\":\"کدام مورد، دربارۀ هشتمین سطح از سطوح سازمان‌یابی حیات درست است؟\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار دوم (هفت ویژگی جانداران ، سطوح سازمان یابی حیات)\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار دوم (هفت ویژگی جانداران ، سطوح سازمان یابی حیات)\",\"choices\":[{\"id\":51211,\"index\":1,\"text\":\"همۀ اجزای آن، دارای ویژگی هم‌ایستایی هستند.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":51212,\"index\":2,\"text\":\"عوامل غیرزندۀ محیط می‌توانند بر آن تأثیرگذار باشند.\",\"isCorrect\":true,\"isSelected\":true},{\"id\":51213,\"index\":3,\"text\":\"اقلیم و پراکندگی جانداران آن می‌توانند متفاوت باشند.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":51214,\"index\":4,\"text\":\"همۀ افراد آن، به یک جمعیت یکسان تعلق دارند.\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":51212,\"index\":2,\"text\":\"عوامل غیرزندۀ محیط می‌توانند بر آن تأثیرگذار باشند.\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":51212,\"index\":2,\"text\":\"عوامل غیرزندۀ محیط می‌توانند بر آن تأثیرگذار باشند.\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"پاسخ تشریحی بوم سازگان شامل عوامل زنده و غیرزنده محیط است، پس عوامل غیرزنده محیط می توانند بر آن تأثیر بگذارند. بررسی سایر گزینه ها: $ 1 $ هم ایستایی از ویژگی های اساسی همه جانداران است، پس جزء غیرزنده بوم سازگان را شامل نمی شود. $ 3 $ اقلیم و پراکندگی جانداران در بوم سازگان یکسان است. $ 4 $ بوم سازگان از اجتماع تشکیل شده است و اجتماع هم از جمعیت های گوناگون!\",\"tags\":[\"زیست شناسی\",\"دهم\",\"گفتار دوم (هفت ویژگی جانداران ، سطوح سازمان یابی حیات)\",\"فصل یک دهم\",\"آسان\"]}'),
(38, 5, 'فصل یک دهم', NULL, NULL, 2, 3609, '2026-10-08 14:53:31', NULL, '2026-10-08 14:53:17', '2026-10-08 14:53:31', 'physics', 0, 'quiz_question', 7087, '{\"questionId\":7087,\"questionText\":\"کدام دسته از یکاهای زیر همگی از یکاهای اصلی SI هستند؟\",\"subjectKey\":\"physics\",\"subject\":\"فیزیک\",\"lesson\":\"مقدمه + مدل سازی + اندازه گیری و کمیت‌ها + SI\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"مقدمه + مدل سازی + اندازه گیری و کمیت‌ها + SI\",\"choices\":[{\"id\":41448,\"index\":1,\"text\":\"کندلا، پاسکال، مول\",\"isCorrect\":false,\"isSelected\":false},{\"id\":41449,\"index\":2,\"text\":\"آمپر، کلوین، متر\",\"isCorrect\":true,\"isSelected\":true},{\"id\":41450,\"index\":3,\"text\":\"ژول، آمپر، مول\",\"isCorrect\":false,\"isSelected\":false},{\"id\":41451,\"index\":4,\"text\":\"اهم، پاسکال، ثانیه\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":41449,\"index\":2,\"text\":\"آمپر، کلوین، متر\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":41449,\"index\":2,\"text\":\"آمپر، کلوین، متر\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"در دستگاه اندازه‌گیری SI ، هفت کمیت طول، جرم، زمان، مقدار ماده، شدت جریان، دما و شدت روشنایی به عنوان کمیت‌های اصلی انتخاب شده‌اند و یکاهای اندازه‌گیری آن‌ها به‌ترتیب متر، کیلوگرم، ثانیه، مول، آمپر، کلوین و کندلا است. بقیۀ کمیت‌ها و یکاهای آن‌ها به عنوان کمیت‌ها و یکاهای فرعی در نظر گرفته می‌شوند.\",\"tags\":[\"فیزیک\",\"دهم\",\"مقدمه + مدل سازی + اندازه گیری و کمیت‌ها + SI\",\"فصل یک دهم\",\"آسان\"]}'),
(39, 5, 'فصل یک دهم', NULL, NULL, 2, 0, '2026-10-08 14:54:45', NULL, '2026-10-08 14:54:42', '2026-10-08 14:54:45', 'physics', 0, 'quiz_question', 7144, '{\"questionId\":7144,\"questionText\":\"دو ظرف مشابه را جداگانه از مایع‌های A و B پر کرده‌ایم. درون مایع A یک گلوله آلومینیمی توپر به جرم $m$ و درون مایع B یک گلوله آلومینیمی توپر دیگر به جرم $\\\\frac{1}{4} m$ می‌اندازیم. جرم بیرون‌ریخته شده از مایع A، دو برابر جرم بیرون‌ریخته شده از مایع B خواهد بود. اگر جرم مساوی از این دو مایع را با یکدیگر مخلوط کنیم، چگالی مخلوط این دو مایع چند برابر چگالی مایع A است؟\",\"subjectKey\":\"physics\",\"subject\":\"فیزیک\",\"lesson\":\"چگالی\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"چگالی\",\"choices\":[{\"id\":41220,\"index\":1,\"text\":\"$\\\\frac{2}{3}$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":41221,\"index\":2,\"text\":\"$\\\\frac{4}{3}$\",\"isCorrect\":true,\"isSelected\":false},{\"id\":41222,\"index\":3,\"text\":\"$\\\\frac{8}{9}$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":41223,\"index\":4,\"text\":\"$\\\\frac{16}{9}$\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":41220,\"index\":1,\"text\":\"$\\\\frac{2}{3}$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":41221,\"index\":2,\"text\":\"$\\\\frac{4}{3}$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"می‌دانیم، وقتی ظرفی را پر از یک مایع کنیم، با انداختن جسم جامد به درون آن، حجم مایع بیرون‌ریخته شده از ظرف، برابر با حجم جسم است. بنابراین می‌توان نوشت: $V_{\\\\text{جسم}} = V_{\\\\text{مایع سرریز}} \\\\xrightarrow{V = \\\\frac{m}{\\\\rho}} \\\\frac{m_{\\\\text{جسم}}}{\\\\rho_{\\\\text{جسم}}} = \\\\frac{m_{\\\\text{مایع سرریز}}}{\\\\rho_{\\\\text{مایع}}}$ $\\\\Rightarrow \\\\rho_{\\\\text{مایع}} = \\\\frac{m_{\\\\text{مایع سرریز}} \\\\times \\\\rho_{\\\\text{جسم}}}{m_{\\\\text{جسم}}} \\\\text{ (1)}$ از طرف دیگر، چون هر دو گلوله آلومینیمی هستند، چگالی آنها یکسان است. بنابراین طبق رابطۀ ($1$) داریم: $(1) \\\\xrightarrow{\\\\text{ثابت} = \\\\rho_{\\\\text{جسم}}} \\\\frac{\\\\rho_A}{\\\\rho_B} = \\\\frac{m_{A\\\\text{ مایع سرریز}}}{m_{B\\\\text{ مایع سرریز}}} \\\\times \\\\frac{m_{B\\\\text{ جسم}}}{m_{A\\\\text{ جسم}}}$ $\\\\xrightarrow{m_{A\\\\text{ جسم}} = m \\\\text{ , } m_{A\\\\text{ مایع سرریز}} = 2m_{B\\\\text{ مایع سرریز}} \\\\text{ , } m_{B\\\\text{ جسم}} = \\\\frac{1}{4}m}$ $\\\\frac{\\\\rho_A}{\\\\rho_B} = \\\\frac{2m_{B\\\\text{ مایع سرریز}}}{m_{B\\\\text{ مایع سرریز}}} \\\\times \\\\frac{\\\\frac{1}{4}m}{m} \\\\Rightarrow \\\\frac{\\\\rho_A}{\\\\rho_B} = \\\\frac{1}{2} \\\\Rightarrow \\\\rho_B = 2\\\\rho_A$ اکنون با درنظر گرفتن جرم یکسان $m$ از هر مایع، حجمشان را برحسب $m$ و $\\\\rho_A$ می‌یابیم. $V_A = \\\\frac{m_A}{\\\\rho_A} \\\\xrightarrow{m_A = m} V_A = \\\\frac{m}{\\\\rho_A}$ $V_B = \\\\frac{m_B}{\\\\rho_B} \\\\xrightarrow[\\\\rho_B = 2\\\\rho_A]{m_B = m} V_B = \\\\frac{m}{2\\\\rho_A}$ در نهایت، با مخلوط کردن جرم مساوی $m$ از دو مایع داریم: $\\\\rho_{\\\\text{مخلوط}} = \\\\frac{m_A + m_B}{V_A + V_B} \\\\xrightarrow{m_A = m_B = m}$ $\\\\rho_{\\\\text{مخلوط}} = \\\\frac{m + m}{\\\\frac{m}{\\\\rho_A} + \\\\frac{m}{2\\\\rho_A}} \\\\Rightarrow \\\\rho_{\\\\text{مخلوط}} = \\\\frac{2m}{\\\\frac{3m}{2\\\\rho_A}} = \\\\frac{4m\\\\rho_A}{3m}$ $\\\\Rightarrow \\\\rho_{\\\\text{مخلوط}} = \\\\frac{4}{3}\\\\rho_A$\",\"tags\":[\"فیزیک\",\"دهم\",\"چگالی\",\"فصل یک دهم\",\"متوسط\"]}'),
(40, 112, 'آشنایی با مباحث ریاضی', NULL, NULL, 2, 1112, '2026-10-09 17:17:31', NULL, '2026-10-09 17:17:30', '2026-10-09 17:17:32', 'math', 1, 'chat', NULL, NULL),
(41, 130, 'فصل یک دهم', NULL, NULL, 0, 0, '2026-10-10 12:31:18', NULL, '2026-10-10 12:31:18', '2026-10-10 12:31:18', 'physics', 0, 'quiz_question', 7174, '{\"questionId\":7174,\"questionText\":\"اگر $A = 10^{-3} \\\\frac{N.ms}{\\\\mu g}$ باشد، در این صورت، A کمیتی ........................ و مقدار آن برحسب یکای SI برابر با ........................ است.\",\"subjectKey\":\"physics\",\"subject\":\"فیزیک\",\"lesson\":\"مقدمه + مدل سازی + اندازه گیری و کمیت‌ها + SI\",\"topic\":\"فصل یک دهم\",\"category\":\"فصل یک دهم\",\"grade\":\"دهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"آسان\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"مقدمه + مدل سازی + اندازه گیری و کمیت‌ها + SI\",\"choices\":[{\"id\":41100,\"index\":1,\"text\":\"فرعی، ۱\",\"isCorrect\":false,\"isSelected\":false},{\"id\":41101,\"index\":2,\"text\":\"فرعی، ۱۰۰۰\",\"isCorrect\":true,\"isSelected\":true},{\"id\":41102,\"index\":3,\"text\":\"اصلی، ۱\",\"isCorrect\":false,\"isSelected\":false},{\"id\":41103,\"index\":4,\"text\":\"اصلی، ۱۰۰۰\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":41101,\"index\":2,\"text\":\"فرعی، ۱۰۰۰\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":41101,\"index\":2,\"text\":\"فرعی، ۱۰۰۰\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"کمیت داده شده را برحسب یکاهای اصلی می‌نویسیم: $A = 10^-3 N.ms / μg = 10^-3 (kg.m/s^2 × 10^-3 s) / (10^-6 × 10^-3 kg) ⇒ A = 10^3 m/s$ چون یکای کمیت $A$ متر بر ثانیه ($m/s$) به‌دست آمده، $A$ کمیت تندی یا سرعت می‌باشد و یک کمیت فرعی است و مقدار آن در $SI$ برابر $1000$ می‌باشد. (فیزیک و اندازه‌گیری) (فیزیک $1$، صفحه‌های $7$ و $10$)\",\"tags\":[\"فیزیک\",\"دهم\",\"مقدمه + مدل سازی + اندازه گیری و کمیت‌ها + SI\",\"فصل یک دهم\",\"آسان\"]}'),
(42, 4, 'یک دوازدهم', NULL, NULL, 0, 0, '2026-10-10 19:30:22', NULL, '2026-10-10 19:30:22', '2026-10-10 19:30:22', 'biology', 0, 'quiz_question', 12053, '{\"questionId\":12053,\"questionText\":\"178- نوعی آنزیم که در صنعت برای تولید سوخت زیستی مورد استفاده قرار می‌گیرد، چه مشخصه‌ای دارد؟\",\"subjectKey\":\"biology\",\"subject\":\"زیست شناسی\",\"lesson\":\"گفتار سه ( نقش پروتئین ها )\",\"topic\":\"یک دوازدهم\",\"category\":\"یک دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"گفتار سه ( نقش پروتئین ها )\",\"choices\":[{\"id\":66848,\"index\":1,\"text\":\"۱) فعال شدن ژن آن در یاخته‌های جانوری مشاهده نمی‌شود.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":66849,\"index\":2,\"text\":\"۲) پیش‌مادهٔ یکسانی با بعضی از آنزیم‌های موجود در شوینده‌ها دارد.\",\"isCorrect\":false,\"isSelected\":false},{\"id\":66850,\"index\":3,\"text\":\"۳) مقدار بسیار کم آن می‌تواند باعث تولید تعداد زیادی مونوساکارید شود.\",\"isCorrect\":true,\"isSelected\":true},{\"id\":66851,\"index\":4,\"text\":\"۴) همهٔ مولکول‌هایی که هنگام انجام واکنش در جایگاه فعال آن قرار می‌گیرند، کربن دارند.\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":66850,\"index\":3,\"text\":\"۳) مقدار بسیار کم آن می‌تواند باعث تولید تعداد زیادی مونوساکارید شود.\",\"isCorrect\":true,\"isSelected\":true},\"correctChoice\":{\"id\":66850,\"index\":3,\"text\":\"۳) مقدار بسیار کم آن می‌تواند باعث تولید تعداد زیادی مونوساکارید شود.\",\"isCorrect\":true,\"isSelected\":true},\"isCorrect\":true,\"explanation\":\"(پاسخ گزینه:3 ) 178 آنزیم سلولاز می تواند سلولز را به مولکول های گلوکز (نوعی مونوساکارید) تجزیه کند. مقدار بسیار کمی از آنزیم (مثل سلولاز) کافی است تا مقدار زیادی از پیش ماده (مثل گلوکز) را در واحد زمان به فرآورده تبدیل کند. بررسی سایر گزینه ها: 1 اغلب جانوران فاقد توانایی تولید آنزیم لازم برای گوارش سلولز (آنزیم سلولاز) هستند؛ اما بعضی از جانوران نیز می توانند آنزیم سلولاز را بسازند و در این جانوران، فعال شدن ژن آنزیم سلولاز مشاهده می شود. 2 پیش ماده آنزیم سلولاز، مولکول سلولز است؛ اما در شوینده ها، آنزیم های لیپاز، پروتئاز و آمیلاز وجود دارند که پیش ماده آن ها، به ترتیب، لیپیدها، پروتئین ها و نشاسته هستند. 4 آنزیم سلولاز، واکنش آبکافت (هیدرولیز) مولکول سلولز را کاتالیز می کند. در این واکنش، مولکول آب به سلولز اضافه می شود تا پیوند بین مولکول های گلوکز شکسته شود. پس در جایگاه فعال آنزیم سلولاز، هم مولکول سلولز قرار می گیرد و هم مولکول آب. مولکول آب، اتم کربن ندارد.\",\"tags\":[\"زیست شناسی\",\"دوازدهم\",\"گفتار سه ( نقش پروتئین ها )\",\"یک دوازدهم\",\"متوسط\"]}'),
(43, 4, 'مثلثات دوازدهم', NULL, NULL, 2, 4010, '2026-10-12 15:20:32', NULL, '2026-10-12 15:20:07', '2026-10-12 15:20:32', 'math', 0, 'quiz_question', 2028, '{\"questionId\":2028,\"questionText\":\"جواب کلی معادلهٔ مثلثاتی $\\\\cos^2 3x - 3\\\\cos 3x + 2 = 0$ کدام است؟ ($k \\\\in \\\\mathbb{Z}$)\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":\"معادلات مثلثاتي\",\"topic\":\"مثلثات دوازدهم\",\"category\":\"مثلثات دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"معادلات مثلثاتي\",\"choices\":[{\"id\":50544,\"index\":1,\"text\":\"$\\\\frac{2k\\\\pi}{3}$\",\"isCorrect\":true,\"isSelected\":false},{\"id\":50545,\"index\":2,\"text\":\"$\\\\frac{k\\\\pi}{3}$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":50546,\"index\":3,\"text\":\"$2k\\\\pi \\\\pm \\\\frac{\\\\pi}{3}$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":50547,\"index\":4,\"text\":\"$2k\\\\pi \\\\pm \\\\frac{2\\\\pi}{3}$\",\"isCorrect\":false,\"isSelected\":false}],\"selectedChoice\":{\"id\":50545,\"index\":2,\"text\":\"$\\\\frac{k\\\\pi}{3}$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":50544,\"index\":1,\"text\":\"$\\\\frac{2k\\\\pi}{3}$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"89 - پاسخ: گزینه 1 ▲ مشخصات سؤال: ساده * ریاضی 3 (فصل 2، درس 2) نکته: $Cos x = Cos \\\\alpha \\\\Rightarrow x = 2k\\\\pi \\\\pm \\\\alpha \\\\ (k \\\\in \\\\mathbb{Z})$ می توان نوشت: $Cos^2 3x - 3 Cos 3x + 2 = 0 \\\\Rightarrow (Cos 3x - 2)(Cos 3x - 1) = 0 \\\\Rightarrow \\\\begin{cases} Cos 3x = 2 \\\\quad \\\\text{غ ق ق} \\\\\\\\ Cos 3x = 1 \\\\Rightarrow 3x = 2k\\\\pi \\\\Rightarrow x = \\\\frac{2k\\\\pi}{3} \\\\end{cases}$\",\"tags\":[\"ریاضیات\",\"دوازدهم\",\"معادلات مثلثاتي\",\"مثلثات دوازدهم\",\"متوسط\"]}'),
(44, 4, 'مثلثات دوازدهم', NULL, NULL, 2, 0, '2026-10-12 15:21:11', NULL, '2026-10-12 15:21:09', '2026-10-12 15:21:11', 'math', 0, 'quiz_question', 2574, '{\"questionId\":2574,\"questionText\":\"اگر معادله مثلثاتی $\\\\ sin(x - \\\\frac{\\\\pi}{2}) + \\\\frac{\\\\sin x}{\\\\cot x} = 0$ در بازه $ [0, $[ a دارای ۴ جواب باشد، حداقل مقدار $ $ a کدام است؟\",\"subjectKey\":\"math\",\"subject\":\"ریاضیات\",\"lesson\":\"معادلات مثلثاتي\",\"topic\":\"مثلثات دوازدهم\",\"category\":\"مثلثات دوازدهم\",\"grade\":\"دوازدهم\",\"questionType\":\"multiple_choice\",\"difficulty\":\"متوسط\",\"academicYear\":null,\"book\":null,\"source\":null,\"chapter\":\"معادلات مثلثاتي\",\"choices\":[{\"id\":73880,\"index\":1,\"text\":\"$\\\\pi$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":73881,\"index\":2,\"text\":\"$\\\\frac{5\\\\pi}{4}$\",\"isCorrect\":false,\"isSelected\":true},{\"id\":73882,\"index\":3,\"text\":\"$\\\\frac{3\\\\pi}{2}$\",\"isCorrect\":false,\"isSelected\":false},{\"id\":73883,\"index\":4,\"text\":\"$\\\\frac{7\\\\pi}{4}$\",\"isCorrect\":true,\"isSelected\":false}],\"selectedChoice\":{\"id\":73881,\"index\":2,\"text\":\"$\\\\frac{5\\\\pi}{4}$\",\"isCorrect\":false,\"isSelected\":true},\"correctChoice\":{\"id\":73883,\"index\":4,\"text\":\"$\\\\frac{7\\\\pi}{4}$\",\"isCorrect\":true,\"isSelected\":false},\"isCorrect\":false,\"explanation\":\"ابتدا معادله داده شده را ساده می‌کنیم و مجموعه جواب آن را به‌دست می‌آوریم: $sin(x-π/2)+sinx/cotx=0$ $⇒−sin(π/2−x)+sinx/(cosx/sinx)=$ $⇒−cosx+sin^2 x/cosx=0$ $⇒(−cos^2x+ sin^2 x) /cosx=0$ $⇒-cos2x/cosx=0⇒cos2x=0⇒2x=kπ+π/2$ $k=0,1,2,3$ $x=π/4,3π/4,5π/4,7π/4$ با توجه به چهار جواب به‌دست آمده حداقل مقدار $a$ برابر $$7π/4 است\",\"tags\":[\"ریاضیات\",\"دوازدهم\",\"معادلات مثلثاتي\",\"مثلثات دوازدهم\",\"متوسط\"]}');
