(32, 13, 'assistant', 'سلام خان! مِت‌ام 😊  \nامروز دوست داری روی کدوم درس یا برنامه‌ریزی مطالعه کار کنیم؟', 963, 31, 994, 5, 'gpt-5.6-luna', 0, '2026-09-21 19:27:54', 0.0002298000, 460, 0, 2000000, NULL, 'general', 'complete', 2241, NULL, 'stop'),
