(74, 27, 'assistant', 'سکه امروز تمام شد. با اشتراک رایگان، گفتگو تا شارژ فردا محدود است. برای ادامه، اشتراک ویژه را فعال کنید.', 0, 0, 0, 0, NULL, 0, '2026-09-30 00:53:46', 0.0000000000, 0, 0, 0, '[{\"type\":\"ui_actions\",\"actions\":[{\"id\":\"upgrade-plan\",\"label\":\"اشتراک ویژه\",\"action\":\"open_plans\"},{\"id\":\"buy-coins\",\"label\":\"خرید سکه\",\"action\":\"open_coins\"}]}]', 'general', 'complete', NULL, NULL, NULL),
