(11, 'math', 'مسئله چالشی', 'یک مسئله سخت از معادله درجه‌دوم بده و بعد از هر مرحله از من بخواه خودم ادامه بدهم.', 'راهنمایی مرحله‌ای', 'puzzle', 'generated', 0, 1, '2026-09-15 12:32:33'),
(12, 'math', 'مفهوم مشتق', 'مشتق را با یک مثال واقعی و ساده توضیح بده و نشان بده چرا شیب نمودار را بیان می‌کند.', 'یادگیری با مثال', 'activity', 'generated', 0, 1, '2026-09-15 12:32:33'),
(13, 'math', 'مرور سریع', 'از مباحث مهم ریاضی یازدهم یک مرور کوتاه و منظم بساز و در پایان سه سؤال بپرس.', 'جمع‌بندی کاربردی', 'refresh-cw', 'generated', 0, 1, '2026-09-15 12:32:33'),
(14, 'math', 'آزمون زمان‌دار', 'پنج تست چهارگزینه‌ای ترکیبی از تابع و معادله طراحی کن تا در ده دقیقه حل کنم، سپس پاسخ‌هایم را بررسی کن.', 'چالش ده‌دقیقه‌ای', 'timer', 'generated', 0, 1, '2026-09-15 12:32:33'),
(15, 'math', 'دام‌های محاسباتی', 'چند نمونه از خطاهای رایج در حل نامعادله نشان بده و از من بخواه دلیل نادرست بودن هر راه‌حل را پیدا کنم.', 'خطاها را کشف کن', 'search', 'generated', 1, 1, '2026-09-15 12:32:33'),
(16, 'chemistry', 'موازنه', 'روش موازنه‌ی معادله‌های شیمیایی را با یک مثال قدم‌به‌قدم یادم بده.', 'پایه‌ای و مهم', 'flask-conical', 'seed', 0, 1, '2026-09-15 12:32:34'),
