(18, 'chemistry', 'پیوندها', 'تفاوت پیوند یونی و کووالانسی را با مثال توضیح بده.', 'مفهومی', 'link', 'seed', 0, 1, '2026-09-15 12:32:34'),
(19, 'chemistry', 'جدول تناوبی', 'روند تغییر شعاع اتمی و انرژی یونش در جدول تناوبی را ساده توضیح بده.', 'روندها', 'grid-3x3', 'seed', 0, 1, '2026-09-15 12:32:34'),
(20, 'chemistry', 'محلول‌ها', 'غلظت مولار چیست؟ یک مسئله حل کن.', 'با مثال عددی', 'beaker', 'seed', 0, 1, '2026-09-15 12:32:34'),
(21, 'physics', 'مفهوم شتاب', 'می‌شود شتاب را با یک مثال روزمره توضیح بدهی؟ فرق شتاب مثبت و منفی چیست؟', 'مثال ساده و تصویری', 'lightbulb', 'generated', 0, 1, '2026-09-15 12:32:36'),
(22, 'physics', 'تمرین پرتابه', 'توپ با سرعت اولیه ۲۰ متر بر ثانیه و زاویه ۳۰ درجه پرتاب می‌شود. برد آن را در شرایط ایده‌آل حساب کنیم؟', 'گام‌به‌گام پیش برو', 'target', 'generated', 0, 1, '2026-09-15 12:32:36'),
(23, 'physics', 'مرور مدارها', 'قوانین اصلی مدارهای سری و موازی را در چند دقیقه مرور کنیم؟ یک مثال کوتاه هم بزن.', 'جمع‌بندی سریع فصل', 'refresh-cw', 'generated', 2, 1, '2026-09-15 12:32:36'),
(24, 'physics', 'چالش تستی', 'یک تست چهارگزینه‌ای از فشار در سطح دبیرستان از من بپرس، اما جواب را تا تلاش من نشان نده.', 'اول خودم حل می‌کنم', 'pencil-line', 'generated', 0, 1, '2026-09-15 12:32:36'),
(25, 'physics', 'اشتباه رایج', 'چرا در سقوط آزاد، بعضی‌ها علامت شتاب گرانش را اشتباه انتخاب می‌کنند؟ با یک مثال کوتاه توضیح بده.', 'دام‌های امتحانی را بشناس', 'triangle-alert', 'generated', 0, 1, '2026-09-15 12:32:36'),
(26, 'chemistry', 'حل مسئله', 'اگر ۴ گرم هیدروژن با اکسیژن واکنش دهد، چند گرم آب تولید می‌شود؟ لطفاً مرحله‌به‌مرحله راهنمایی‌ام کن.', 'راهنمایی مرحله‌ای', 'calculator', 'generated', 0, 1, '2026-09-15 12:32:39'),
(27, 'chemistry', 'راز اسیدها', 'چرا بعضی مواد در آب خاصیت اسیدی یا بازی پیدا می‌کنند؟ مفهوم یونش را ساده و با مثال توضیح بده.', 'توضیح مفهومی ساده', 'flask-conical', 'generated', 0, 1, '2026-09-15 12:32:39'),
(28, 'chemistry', 'مرور سریع', 'از فصل ساختار اتم یک مرور کوتاه و جمع‌بندی‌شده برای امتحانم آماده کن؛ نکات مهم و روابط اصلی را هم بگو.', 'جمع‌بندی نکات مهم', 'refresh-cw', 'generated', 0, 1, '2026-09-15 12:32:39'),
(29, 'chemistry', 'تست چالشی', 'یک تست چهارگزینه‌ای درباره سرعت واکنش‌ها طرح کن، اما پاسخ را فعلاً نگو تا خودم حل کنم.', 'آزمون بدون پاسخ', 'brain', 'generated', 0, 1, '2026-09-15 12:32:39'),
(30, 'chemistry', 'اشتباه رایج', 'چرا در محاسبه عدد اکسایش، گاهی علامت‌ها را اشتباه می‌کنم؟ یک مثال حل‌شده و یک روش جلوگیری از این خطا نشان بده.', 'رفع خطای محاسباتی', 'triangle-alert', 'generated', 0, 1, '2026-09-15 12:32:39'),
(31, 'general', 'برنامه‌ی مطالعه', 'برای یک هفته‌ی آینده یک برنامه‌ی مطالعه‌ی واقع‌بینانه بساز؛ اول از من چند سؤال بپرس.', 'شخصی‌سازی‌شده', 'calendar', 'seed', 0, 1, '2026-09-15 13:05:52'),
(32, 'general', 'تمرکز بهتر', 'چطور در جلسه‌های مطالعه‌ی طولانی تمرکزم را حفظ کنم؟ روش‌های عملی بگو.', 'روش‌های عملی', 'brain', 'seed', 0, 1, '2026-09-15 13:05:52'),
(33, 'general', 'استرس امتحان', 'قبل از امتحان خیلی مضطرب می‌شوم. چند تکنیک سریع و مؤثر بگو.', 'قابل اجرا', 'heart-pulse', 'seed', 0, 1, '2026-09-15 13:05:52'),
(34, 'general', 'مرور هوشمند', 'روش مرور فاصله‌دار را برای درس‌های حفظی توضیح بده و یک نمونه‌ی زمان‌بندی بده.', 'تکنیک یادگیری', 'repeat', 'seed', 0, 1, '2026-09-15 13:05:52'),
(35, 'general', 'کدام درس؟', 'کمکم کن انتخاب کنم امروز روی کدام درس وقت بگذارم؛ اول از وضعیتم بپرس.', 'مشاوره', 'compass', 'seed', 0, 1, '2026-09-15 13:05:52'),
(36, 'general', 'حل مسئله', 'در حل معادلهٔ درجه‌دوم همیشه بین روش تجزیه و فرمول کلی مردد می‌شوم. می‌توانی با یک مثال راهنمایی‌ام کنی؟', 'راهنمای مرحله‌ای', 'Calculator', 'generated', 0, 1, '2026-09-15 13:05:57'),
(37, 'general', 'فهم مفهوم', 'چرا در فیزیک، جرم و وزن را یکی نمی‌دانیم؟ لطفاً با یک مثال روزمره توضیح بده.', 'توضیح با مثال', 'Lightbulb', 'generated', 0, 1, '2026-09-15 13:05:57'),
(38, 'general', 'جمع‌بندی سریع', 'فردا از فصل‌های اول زیست آزمون دارم. می‌توانی نکات کلیدی را به شکل چند پرسش‌وپاسخ کوتاه مرور کنی؟', 'نکات کلیدی فصل', 'BookOpen', 'generated', 0, 1, '2026-09-15 13:05:57'),
(39, 'general', 'تست زمان‌دار', 'از مبحث آرایه‌های ادبی یک تست چهارگزینه‌ای نسبتاً دشوار از من بپرس و بعد پاسخ را تحلیل کن.', 'یک تست چالشی', 'Timer', 'generated', 0, 1, '2026-09-15 13:05:57'),
(40, 'general', 'اشتباه رایج', 'در مبحث حد، گاهی جای‌گذاری مستقیم را در موقعیت نامناسب انجام می‌دهم. می‌توانی یک مثال از این اشتباه و روش درستش نشان بدهی؟', 'دام‌های پرتکرار', 'TriangleAlert', 'generated', 0, 1, '2026-09-15 13:05:57'),
(41, 'biology', 'سفر به سلول', 'اجزای سلول و کار هر کدام را با یک تشبیه ساده توضیح بده، بعد اصطلاح دقیق کتاب را بگو.', 'مفهومی', 'dna', 'seed', 0, 1, '2026-09-15 13:11:29'),
(42, 'biology', 'مرور فصل', 'نکات کلیدی فصل گوارش را به‌صورت خلاصه‌ی کنکوری بگو.', 'قبل از امتحان', 'list-checks', 'seed', 0, 1, '2026-09-15 13:11:29'),
(43, 'biology', 'سؤال تستی', 'یک سؤال تستی از دستگاه گردش خون بده و بعد از جواب من، توضیح بده.', 'با بازخورد', 'target', 'seed', 0, 1, '2026-09-15 13:11:29'),
(44, 'biology', 'مقایسه', 'تفاوت میتوز و میوز را در یک جدول مقایسه‌ای توضیح بده.', 'مقایسه‌ای', 'columns-2', 'seed', 0, 1, '2026-09-15 13:11:29'),
(45, 'biology', 'شکل کتاب', 'شکل قلب در کتاب را برایم توضیح بده: هر بخش چه کاری می‌کند؟', 'مبتنی بر کتاب', 'heart', 'seed', 0, 1, '2026-09-15 13:11:29'),
(46, 'biology', 'حل مسئله ژنتیک', 'اگر مادر ناقل بیماری وابسته به X و پدر سالم باشد، احتمال تولد پسر مبتلا چقدر است؟ مرحله‌به‌مرحله راهنمایی‌ام کن.', 'با جدول پانت حل کن', 'Dna', 'generated', 0, 1, '2026-09-15 13:11:34'),
(47, 'biology', 'راز تنفس سلولی', 'چرا یاخته‌ها برای تولید ATP به اکسیژن نیاز دارند؟ تفاوت نقش گلیکولیز و زنجیره انتقال الکترون را ساده توضیح بده.', 'مفهوم را عمیق بفهم', 'Zap', 'generated', 0, 1, '2026-09-15 13:11:34'),
(48, 'biology', 'جمع‌بندی دستگاه‌ها', 'از دستگاه گردش خون و تنفس، یک مرور سریع و منظم برای امتحانم بساز و ارتباط آن‌ها را هم نشان بده.', 'مرور سریع و کاربردی', 'RefreshCw', 'generated', 0, 1, '2026-09-15 13:11:34'),
(49, 'biology', 'چالش پنج‌گزینه‌ای', 'یک تست مفهومی از فصل تنظیم عصبی در سطح کنکور از من بپرس؛ بعد از پاسخ، گزینه‌ها را تحلیل کن.', 'تست مفهومی کنکوری', 'ListChecks', 'generated', 0, 1, '2026-09-15 13:11:34'),
(50, 'biology', 'دام‌های فتوسنتز', 'کدام برداشت درباره فتوسنتز اشتباه رایج است؟ چند باور نادرست را بگو و دلیل علمی رد هرکدام را توضیح بده.', 'اشتباهات پرتکرار را بشناس', 'TriangleAlert', 'generated', 0, 1, '2026-09-15 13:11:34');
